INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8c5ff60d0229', 'en', 'US', '15 Minute Sausage Meatballs', 'Recipe video above. Save this one for those really busy nights: just chop up sausages, pan fry and voila - juicy meatballs without the fuss! A bottle of passata rather than canned tomato makes for a quick sauce which needs nothing more than a pinch of Italian Herbs and salt thanks to all the free flavour we get from the pre-seasoned meat inside the sausages. Serve over pasta, or polenta (try instant polenta!), mash or make saucy subs. YES!', 'https://www.recipetineats.com/tachyon/2025/10/Sausage-meatballs-15-minutes_0.jpg', 5, 10, 15, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_sausages", "quantity": {"value": 1.4, "unit": "pack of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_italian_herb_mix", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_basil", "quantity": {"value": 0.04, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.7, "unit": "pack of 500g"}}]', '[{"ingredients":["1 tbsp olive oil","700 g / 1.4 lb good sausages","2 garlic cloves (, finely chopped)","3/4 cup chicken stock/broth (, low sodium - sub water (Note 2))","700g / 24 oz tomato passata (US: tomato sauce like Hunt''s) (Note 3)","1/2 tsp dried Italian herb mix (sub dried oregano, or 50/50 oregano/thyme)","1/2 tsp cooking salt / kosher salt (+50% for flakes, halve for table salt)","1/4 tsp red pepper flakes (, optional (hint of warmth - sub pinch of pepper))","1 sprig basil ( - stalk for sauce, leaves for garnish (optional))"]},{"ingredients":["Parmesan (, finely grated)","350g / 12oz pasta of choice (, or polenta, mash or make subs!)"],"purpose":"Serving:"}]', '[{"description":"Brown meatballs (3-4 min), add garlic for last 15 seconds. Reduce stock by half (1 min), add everything else, simmer 4 minutes. Serve!","images":[],"step":1},{"title":"Brown meatballs","description":"Heat the oil in a large non-stick pan over high heat. Add the meatballs and stir for 4 - 5 minutes until lightly browned but still raw inside. (Note 4)","duration":4.5,"images":[],"step":2},{"description":"Add garlic and stir for just 15 seconds until light golden (careful, don''t let it burn!)","images":[],"step":3},{"title":"Simmer","description":"Add the stock and simmer rapidly for 1 minute to reduce by half. Add everything else, stir, bring to a simmer, then lower heat to medium high and let it simmer energetically (but not crazy rapidly) for 4 minutes.","duration":1,"images":[],"step":4},{"description":"Serve with lots of parmesan and hand-torn basil leaves over pasta, polenta, mash or other starchy vehicle of choice, or stuff into subs!","images":[],"step":5},{"description":"Add cooked pasta with 1/2 cup of the pasta cooking water into the pan with meatballs. Toss over medium heat for 1 - 2 minutes until the sauce is stuck to the pasta and it''s stained red, rather than pooled in the base of the pan. Divide between bowls and enjoy!","duration":1.5,"images":[],"step":6}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Italian-esque","Western"],"categories":["dinner-tonight","meatball-recipes","pasta-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","sausage-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ccc413d76a32', 'en', 'US', 'Jamaican Jerk Fish', 'Recipe video above. Jerk seasoning adds a stack of flavour and makes the surface crispy too. Quick way to make a dish that punches way above its weight for effort vs results. I''ve used it for white fish fillets here but it will be excellent with salmon, prawns/shrimp, chicken or turkey.Spiciness - Packs a decent punch! See note for how to control.Jamaican menu week! This Jerk Fish with Jamaican Slaw and Jamaican Coconut Rice and Peas (beans) plus rum and raisin ice cream without an ice cream maker for dessert!', 'https://www.recipetineats.com/tachyon/2023/01/Jerk-fish_0.jpg', 5, 6, 11, 4, '[{"id": "ing_garlic_powder", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.013, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.281, "unit": "jar of 40g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.156, "unit": "jar of 40g"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_nutmeg_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}]', '[{"ingredients":["3 tsp garlic powder","3 tsp onion powder","2 tsp cooking salt / kosher salt (reduce to 1 1/2 tsp for table salt)","3 tsp dried thyme","2 1/2 tsp brown sugar (, lightly packed (Note 2))","2 1/4 tsp cayenne pepper (it''s spicy! See SPICE NOTE)","1 1/2 tsp smoked paprika (sub ordinary paprika)","1 1/4 tsp allspice powder","1/2 tsp cinnamon powder","1/2 tsp nutmeg powder"],"purpose":"Jerk seasoning (Note 1):"},{"ingredients":["4 x 160g/6 oz thin snapper or other white fish fillets (, skinless, boneless (up to 1.5cm / 0.6\" thick, Note 3))","3 tbsp extra virgin olive oil"],"purpose":"Fish:"}]', '[{"title":"Jerk Spice Blend","description":"Mix the Jerk Seasoning spices together in a bowl then spread in a small tray that is just large enough to fit one fish fillet.","images":[],"step":1},{"title":"Coat fish","description":"Pat fish dry with a paper towel. Then coat both sides of each fillet with the jerk seasoning, pressing to adhere. Shake off excess, place on a clean plate and coat remaining fish.","images":[],"step":2},{"title":"Cook fish","description":"Heat half the oil in a large non-stick pan over high heat. When you see small wisps of smoke, place 2 fillets presentation side down and cook for 2 minutes.","duration":2,"images":[],"step":3},{"title":"Flip","description":"the spice crust should be a deep bronze colour with a reddish tinge. Cook the other side for 1 minute until the target internal temperature is 55°C/130°F, or the fish flakes easily at the thickest point.","duration":1,"images":[],"step":4},{"description":"Rest on a rack for 2 minutes (to preserve crispy spice crust). Then serve! Recipes for pictured Jamaican sides coming on Tuesday - stay tuned!","duration":2,"images":[],"step":5}]', '["fish"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Caribbean","Jamaican"],"categories":["dietary","dinner-tonight","fish-recipes","low-calorie-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5f525ffb9048', 'en', 'US', 'Baked Brie', 'Recipe video above. The world''s fastest finger food, this is like the best cheese dip in the world with wow factor! Just pop a brie in the oven for 15 minutes or microwave on high for 2 minutes (seriously, no one will EVER know). Use a budget brie or camember for this, top end brie would be wasted on this recipe.Excellent shared entree or party food that''s really quick and easy to prepare. Be sure to use sturdy plain or flavoured crackers, or crostini for scooping. Wafer thin crackers and chips tend to break.', 'https://www.recipetineats.com/tachyon/2014/11/Baked-Brie_3.jpg', 3, 15, 18, 6, '[{"id": "ing_brie", "quantity": {"value": 250.0, "unit": "block of 200g"}}, {"id": "ing_maple_syrup", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_crostini", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_grapes", "quantity": {"value": 0.35, "unit": "kg"}}]', '[{"ingredients":["250 - 500g / 8 - 16 oz round brie (or camembert (good value is fine! Note 1))","2 tbsp honey or maple syrup (optional)","1 thyme sprig (optional)"]},{"ingredients":["Crostini","1 bunch purple grapes (or green, optional)"],"purpose":"For Serving:"}]', '[{"description":"Preheat oven to 180°C/350°F (all oven types).","images":[],"step":1},{"description":"Unwrap brie and place in a small, shallow ovenproof dish slightly larger than the brie (to be used for serving) OR a piece of crumbled baking / parchment paper (for transference). (Note 2)","images":[],"step":2},{"title":"Oven","description":"Bake for 15 to 20 minutes (for 250g/80z), or until melted through. For 500g/1lb brie, increase to 25 minutes. To check, gently touch the centre of the brie - it should feel very soft, like it is about to collapse if you press any harder.","duration":17.5,"images":[],"step":3},{"title":"Microwave option","description":"2 minutes on high (no one will know!) in 30 second increments.","images":[],"step":4},{"title":"Carefully transfer to serving plate / board","description":"it''s delicate (transfer on paper if you used paper).","images":[],"step":5},{"description":"Drizzle with honey, top with sprig of thyme (if using).","images":[],"step":6},{"description":"Serve immediately with crostini on the side for scooping. Provide a knife to cut through the rind and a cheese or pate knife (or similar) to scoop cheese up onto crostini or crackers (plain or fruit/nut flavoured).","images":[],"step":7}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["snack"],"cuisine":["Western"],"categories":["dietary","gluten-free-recipes","most-popular","quick-and-easy","quick-dinner-ideas-15-minute-meals","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7604c2146ba7', 'en', 'US', 'Pad See Ew - Thai Stir Fried Noodles', 'Recipe video above. Pad See Ew (which means Stir Fried Soy Sauce noodles) is one of the most popular Thai street foods. Traditionally made with Sen Yai which are wide, thin rice noodles which are not that easy to come by. So use dried rice noodles instead - I''ve eaten enough Pad See Ew at Thai restaurants to assure you that there is no compromise on flavour!KEY TIP FOR SUCCESS: Cook the chicken separately from the noodles. Home stoves are no match for the fierce heat of restaurant and street vendor burners. You have to cook separately to get caramelisation on the noodles which is key for authentic flavour. If you don''t, the noodles will just stew and your dish will lack flavour!', 'https://www.recipetineats.com/tachyon/2016/03/Pad-See-Ew-Thai-Noodles_3.jpg', 8, 10, 18, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.4, "unit": "pack of 500g"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_broccoli", "quantity": {"value": 0.008, "unit": "kg"}}]', '[{"ingredients":["200g / 7 oz dried wide rice stick noodles (, or 15 oz / 450g fresh wide flat rice noodles (Sen Yai) (Note 1))"],"purpose":"Noodles"},{"ingredients":["2 tsp dark soy sauce (Note 2)","1 1/2 tbsp oyster sauce","1 tbsp light soy sauce (or all purpose, Note 3)","2 tsp white vinegar (plain white vinegar)","2 tsp sugar (any type)"],"purpose":"Sauce"},{"ingredients":["3 tbsp peanut or vegetable oil (, separated)","2 cloves garlic cloves, very finely chopped","1 cup / 150g / 5oz chicken thighs (boneless, skinless), sliced (Note 4)","1 large egg","4 stems Chinese broccoli (Note 5)"],"purpose":"Stir Fry"}]', '[{"title":"Chinese Broccoli","description":"trim ends, cut into 7.5cm/3\" pieces. Separate leaves from stems. Cut thick stems in half vertically so they''re no wider than 0.8cm / 0.3\" thick.","images":[],"step":1},{"title":"Noodles","description":"Prepare according to packet directions and drain. Time it so they''re cooked just before using - do not leave cooked rice noodles lying around, they break in the wok.","images":[],"step":2},{"title":"Sauce","description":"Mix ingredients until sugar dissolves.","images":[],"step":3},{"description":"Cooking:","images":[],"step":4},{"title":"Heat oil","description":"Heat 1 tbsp oil in a very large heavy based skillet or wok over high heat.","images":[],"step":5},{"title":"Cook garlic and chicken","description":"Add garlic, cook 15 seconds. Add chicken, cook until it mostly changes from pink to white.","images":[],"step":6},{"title":"Chinese broccoli STEMS","description":"Add Chinese broccoli stems, cook until chicken is almost cooked through.","images":[],"step":7},{"title":"Chinese broccoli LEAVES","description":"Add Chinese broccoli leaves, cook until just wilted.","images":[],"step":8},{"title":"Scramble egg","description":"Push everything to one side, crack egg in and scramble.","images":[],"step":9},{"title":"REMOVE chicken from wok","description":"Remove everything in the wok onto a plate (scrape wok clean).","images":[],"step":10},{"title":"Caramelise noodles","description":"Return wok to stove, heat 2 tbsp oil over high heat until it starts smoking (HOT is key!). Add noodles and Sauce. Toss as few times as possible to disperse Sauce and make edges of noodles caramelise - about 1 to 1 1/2 minutes.","images":[],"step":11},{"title":"Add chicken back in","description":"Quickly add chicken and veg back in, and toss to disperse. Serve immediately!","images":[],"step":12}]', '["egg","gluten","peanuts","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-recipes","cuisines","dinner-tonight","main-dishes","most-popular","noodles","quick-and-easy","quick-dinner-ideas-15-minute-meals","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a6b37999ff63', 'en', 'US', 'Crispy Skin Fish', 'Recipe video above. Fish with crispy skin is one of the most delicious quick ways to cook a piece of protein! To nail it every time, you need dry skin, hot oil and to press down lightly to let the skin seal against the hot pan.I''m using Barramundi here but this recipe can be used for any fish with skin that goes crispy - see Note 1.Stove to oven method recommended for thick fillets so for most even cooking of flesh with super crispy skin - see Note 3. Thin fillets can be cooked entirely on the stove. Scoring the skin is recommended for thick fillets for even cooking of the flesh and skin, plus an insurance policy to prevent the skin from curling up.Sauces and sides - See Note 7!', 'https://www.recipetineats.com/tachyon/2021/10/Crispy-Skin-Barramundi_97.jpg', 3, 0, 3, 2, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.18, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_sauces_and_sides", "quantity": {"value": 1.0, "unit": "bottle"}}]', '[{"ingredients":["180g/6oz x 2 barramundi or other fish fillets (, skin on, pin boned (Note 1))","2 tbsp olive oil (or vegetable, canola or grapeseed oil)","3/4 tsp cooking/kosher salt (or 1/2 tsp table salt, Note 2)","1/4 tsp black pepper","Sauces and sides (- see Note 7 below)"]}]', '[{"title":"Thick Fillets definition","description":"Fish > 2.5cm / 1\" thick at the thickest point. Best finished in the oven. (Note 3)","images":[],"step":1},{"title":"Pan type","description":"Non-stick pan, an oven proof one if you have Thick Fillets. (Note 4)","images":[],"step":2},{"title":"Preheat oven (for Thick Fillets)","description":"Preheat oven to 200°C/390°F (180°C fan).","images":[],"step":3},{"description":"Cooking:","images":[],"step":4},{"title":"Dry skin","description":"Pat skin dry with paper towels. For extra precaution, leave the fish fillets in the fridge skin side up, uncovered, for an hour. (I rarely do this)","images":[],"step":5},{"title":"Scoring skin (Note 5)","description":"For Thick Fillets, score the skin by cutting slashes into the skin as pictured in post. 4cm slashes 1cm apart, 2 - 3mm deep, through the skin and ever so slightly into the flesh (1.6\" long, 0.4\" apart, 0.1\" deep)","images":[],"step":6},{"title":"Season fish","description":"Sprinkle the flesh and skin with the salt and pepper just before cooking.","images":[],"step":7},{"title":"Heat oil well","description":"Heat oil in a non stick pan over medium high heat until you see the first small wisps of smoke.","images":[],"step":8},{"title":"Press fish down","description":"Place one fillet into the pan skin side down, then use your fingers or spatula to press down lightly for 10 seconds to allow the skin to seal flat against the hot surface. Repeat with the other fillet (PROS: Do both at the same time!).","duration":0.16666666666666666,"images":[],"step":9},{"title":"Cook skin 2","description":"3 minutes: Cook the skin side for 2 to 3 minutes until it''s crispy in the centre and golden. Lift up to check.","duration":2.5,"images":[],"step":10},{"title":"Transfer Thick Fillets to oven","description":"Transfer to oven for 10 minutes (do not flip, keep skin side still down - goes crispier!) or until the internal temperature is 55°C/131°F. (Note 6)","duration":10,"images":[],"step":11},{"title":"Thin fillets","description":"Turn and cook the flesh side in the pan.","images":[],"step":12},{"title":"Rest 3 minutes","description":"Transfer fish to a rack with the skin side UP. Rest for 3 minutes.","duration":3,"images":[],"step":13},{"title":"Serving","description":"To serve, place on a plate skin side UP. Do not pour sauce on the skin until just before serving else it will soften the fish skin. See ingredients above for suggested sauces and sides!","images":[],"step":14}]', '["fish"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","fish-recipes","mains","other","quick-and-easy","quick-dinner-ideas-15-minute-meals","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_44db9eac2bd1', 'en', 'US', 'Asian Chilli Chicken', 'Recipe video above. A quick chicken dinner that''s an explosion of (spicy!) Asian flavours! Make this with chicken breast, boneless thighs or tenderloins.Spiciness level: Spicy but not blow-your-head-off spicy! Remember, I like to think I''m a Spice Monster, but in reality I can''t handle the heat (literally!). To dial it back, reduce chilli flakes and see Note 2 about reducing Sriracha.', 'https://www.recipetineats.com/tachyon/2021/02/Asian-Chilli-Chicken_7a.jpg', 5, 8, 13, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.02, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_sriracha", "quantity": {"value": 0.113, "unit": "bottle of 400ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_honey", "quantity": {"value": 0.125, "unit": "jar of 500g"}}, {"id": "ing_lime", "quantity": {"value": 0.09, "unit": "net of 500g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["500g / 1lb breast fillets, skinless and boneless (2 large) (Note 1 other cuts)","1/2 tsp each salt and pepper","1 1/2 tbsp rice flour, or all-purpose/plain flour (Note 2)","1 1/2 tbsp oil (, vegetable or canola)"],"purpose":"Chicken:"},{"ingredients":["2 tsp sesame oil","2 garlic cloves (, finely minced)","2 tsp ginger (, finely minced)","1 tsp chilli flakes / red pepper flakes (reduce for less spicy)","1/2 cup water","3 tbsp sriracha (sub ketchup for not spicy, Note 3)","1 tbsp soy sauce (, light or all purpose (Note 4))","1/4 cup honey (sub brown sugar)","3 tbsp lime juice (sub 2 tbsp rice vinegar)"],"purpose":"Sauce:"},{"ingredients":["Green onion (finely sliced), sesame seeds, fresh chilli, lime wedges"],"purpose":"Garnishes (choose):"}]', '[{"title":"Season","description":"Cut each chicken breast in half horizontally to form 4 steaks total. Sprinkle each side with salt, pepper and rice flour, shaking off excess.","images":[],"step":1},{"title":"Pan-fry","description":"Heat oil in a large skillet over high heat. Add chicken and cook for 2 minutes. Turn and cook the other side for 2 minutes, then remove to a plate.","duration":2,"images":[],"step":2},{"description":"Sticky Chilli Sauce:","images":[],"step":3},{"title":"Sesame oil","description":"Allow the skillet to cool a bit then return to the stove on medium. Add sesame oil and heat.","images":[],"step":4},{"title":"Garlic and ginger","description":"Add garlic and ginger, cook for 15 seconds.","duration":0.25,"images":[],"step":5},{"title":"Chilli flakes","description":"Add chilli flakes and cook for 30 seconds until garlic is golden.","duration":0.5,"images":[],"step":6},{"title":"Sriracha, soy and honey","description":"Turn heat up to medium-high. Add water, sriracha, soy sauce and honey, stir well, scraping the base of the pan to dissolve all the golden bits into the liquid.","images":[],"step":7},{"description":"Simmer for 2 minutes until it reduce to a thick syrup. Add lime juice, then simmer for a further 30 seconds until it thickens back to a thick syrup.","duration":2,"images":[],"step":8},{"title":"Coat chicken","description":"Turn heat off. Return chicken to pan, turning to coat in sauce.","images":[],"step":9},{"description":"Serve chicken, topping with remaining sauce in skillet, garnished with green onions, sesame seed and extra lime wedges, if desired.","images":[],"step":10}]', '["gluten","sesame","soy"]', '["high_protein","high_protein_low_calorie","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Asian","Modern Asian"],"categories":["asian-recipes","chicken","chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","low-calorie-recipes","main-dishes","mains","modern-asian","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_438b29404531', 'en', 'US', '12 Minute Thai Chicken Peanut Noodles', 'Recipe video above. Thai Chicken Peanut Noodles is what you make when you''ve got less than 15 minutes to get dinner on the table and you need a Thai fix! Using chicken mince means no meat prep - and you can switch it out with literally any ground meat (beef, turkey, pork). It might not be authentic Thai ... but it''s fast and 100% delicious!NOTE: Trick here is to work quickly so the sauce isn''t all absorbed by the noodles which will make them bloated and clumpy. If your noodles do absorb all the sauce, just add a splash of water to thin it out.', 'https://www.recipetineats.com/tachyon/2021/01/12-Minute-Thai-Chicken-Noodles_2.jpg', 3, 9, 12, 2, '[{"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_chicken_mince", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_red_curry_paste", "quantity": {"value": 0.113, "unit": "bottle"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.469, "unit": "can of 400ml"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.12, "unit": "jar of 375g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 2.0, "unit": "pack of 500g"}}, {"id": "ing_baby_spinach", "quantity": {"value": 2.0, "unit": "bag of 250g"}}, {"id": "ing_peanuts", "quantity": {"value": 0.075, "unit": "jar"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1 tbsp oil","1 garlic clove (, minced)","200g/7oz chicken mince (ground chicken) (Note 1)","1 tsp curry powder (Note 2)","1 1/2 tbsp red curry paste (, separated (Note 3))","1 tsp dark soy sauce (Note 4)","1 1/2 cups chicken stock/broth (, low sodium)","3/4 cup coconut milk ((~1/2 a can), full fat for best flavour)","2 tbsp cider vinegar","3 tbsp peanut butter","2 instant ramen or noodle cakes (~70-100g/2.5-3.5oz per cake; any brand (discard seasoning pack, Note 5))","2 (big!) handfuls baby spinach"]},{"ingredients":["2 tbsp peanuts (, finely chopped)","Roughly chopped fresh coriander/cilantro leaves","Sriracha or other chilli paste (, optional)"],"purpose":"To serve:"}]', '[{"title":"Sauté garlic","description":"Heat oil in a medium skillet over high heat (not too large, else the sauce will evaporate too quickly). Add garlic and cook for 20 seconds until it turns golden.","duration":0.3333333333333333,"images":[],"step":1},{"title":"Cook chicken","description":"Add chicken mince and cook for 2 minutes, breaking it up as you go, until it mostly changes from pink to white.","duration":2,"images":[],"step":2},{"title":"Add flavourings","description":"Add 1 tbsp red curry paste, curry powder and soy sauce. Cook for 1 minute.","duration":1,"images":[],"step":3},{"title":"Cook extra curry paste","description":"Clear a space in the middle of the pan, add remaining 1/2 tbsp curry paste, stir the curry paste for 30 seconds.","duration":0.5,"images":[],"step":4},{"title":"Simmer stock","description":"Add chicken stock, bring to a simmer then reduce to medium-high. Simmer for 1 minute.","duration":1,"images":[],"step":5},{"title":"Add noodles","description":"Squish the noodle cakes in, pushing chicken aside so the noodles are as submerged as possible.","images":[],"step":6},{"title":"Cook 45 sec, flip, 30 sec","description":"Leave to cook for 45 seconds, then flip noodles. Leave for another 30 seconds, then separate the noodles with 2 wooden spoons.","duration":0.75,"images":[],"step":7},{"title":"Add peanut sauce","description":"Push noodles aside, add coconut milk, peanut butter and vinegar, then give it a quick mix to mostly dissolve the peanut butter.","images":[],"step":8},{"title":"Toss with spinach","description":"Add spinach, toss with the noodles for 30 seconds until wilted. Make sure it''s still pretty saucy - everybody loves sauce!","duration":0.5,"images":[],"step":9},{"title":"Serve","description":"Transfer to serving bowls, sprinkle with coriander, peanuts and Sriracha or chilli paste if desired.","images":[],"step":10}]', '["gluten","peanuts","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","Thai-ish"],"categories":["asian-recipes","dinner-tonight","noodles","one-pot-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_13908fb73f78', 'en', 'US', 'Asian Slaw - crunchy Oriental Cabbage Salad with Asian Dressing', 'Recipe video above. A light, healthy, CRUNCHY Asian salad that is a great side for all types of Asian foods. Dressing is a great salty / sour / spicy lime dressing reminiscent of Thai and Vietnamese food. Add CHICKEN if making this as a meal. Serves 8 - 10 as a side, 4 as a meal with chicken.', 'https://www.recipetineats.com/tachyon/2014/07/Asian-Slaw_2.jpg', 15, 0, 15, 8, '[{"id": "ing_cabbage", "quantity": {"value": 9.0, "unit": "head"}}, {"id": "ing_red_cabbage", "quantity": {"value": 9.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 2000.0, "unit": "pack of 1kg"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 3.0, "unit": "bag of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.06, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_mint", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_green_onion", "quantity": {"value": 0.06, "unit": "bunch"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_oil", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_sugar", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_chicken", "quantity": {"value": 0.45, "unit": "kg"}}]', '[{"ingredients":["3 cups green cabbage or Chinese cabbage (, shredded)","3 cups red cabbage (, shredded)","2 large carrots (, julienned)","3 cups bean sprouts","3 green onions (, finely sliced on the diagonal )","1/2 cup coriander / cilantro leaves","1/2 cup mint leaves","1/4 cup Asian Fried Shallots (optional), to garnish (Note 1)"],"purpose":"Asian Slaw"},{"ingredients":["3 tbsp rice vinegar (Note 2)","3 tbsp soy sauce (Note 3)","2 tsp fish sauce (, or more soy (Note 4))","2 tbsp lime juice (, or more rice vinegar (Note 5))","3 tbsp peanut oil (Note 6)","1 1/2 tbsp sugar (, any type)","1/2 tsp birds eye or other red chilli (, finely minced (optional))","2 garlic cloves (, minced)"],"purpose":"Asian Dressing"},{"ingredients":["3 cups shredded cooked chicken"],"purpose":"Chicken option (for meal)"}]', '[{"description":"Combine the dressing ingredients in a jar and shake well.","images":[],"step":1},{"description":"Combine the salad ingredients, except the Asian Fried Shallots.","images":[],"step":2},{"description":"Pour over dressing and toss to combine.","images":[],"step":3},{"description":"Garnish with Asian Fried Shallots. Serve!","images":[],"step":4}]', '["fish","gluten","peanuts","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner","lunch"],"cuisine":["Asian","Thai","Vietnamese"],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","dietary","low-calorie-recipes","modern-asian","quick-and-easy","quick-dinner-ideas-15-minute-meals","salad-recipes-main-course","vegan-lifestyle"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_52b4d6f775dc', 'en', 'US', 'Pumpkin Soup - Classic and Easy', 'Recipe VIDEO above. Just a touch of cream adds a hint of luxury to this super easy pumpkin soup! If you don''t have cream, use milk or add a knob of butter. Make this with any type of pumpkin OR butternut squash / butternut pumpkin (same thing!). FLAVOUR VARIATIONS - see list in post above (includes quantities).Don''t forget crusty bread for dunking! (Or up the ante with crusty cheese bread)', 'https://www.recipetineats.com/tachyon/2017/10/Pumpkin-Soup-2.jpg', 5, 10, 15, 4, '[{"id": "ing_pumpkin", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_chicken", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}]', '[{"ingredients":["1.2 kg / 2.4 lb pumpkin (any type) ( OR butternut squash, unpeeled weight (Note 1))","1 onion (, sliced (white, brown, yellow))","2 garlic cloves (, peeled whole)","3 cups vegetable or chicken broth/stock (, low sodium)","1 cup water","Salt and pepper"]},{"ingredients":["1/2 - 3/4 cup cream (, half and half or milk (Note 2))"],"purpose":"Finishes:"}]', '[{"description":"Cut the pumpkin into 3cm / 2.25\" slices. Cut the skin off and scrape seeds out (video is helpful). Cut into 4cm / 1.5\" chunks.","images":[],"step":1},{"description":"Place the pumpkin, onion, garlic, broth and water in a pot - liquid won''t quite cover all the pumpkin. Bring to a boil, uncovered, then reduce heat and let simmer rapidly until pumpkin is tender (check with butter knife) - about 10 minutes.","images":[],"step":2},{"description":"Remove from heat and use a stick blender to blend until smooth (Note 3 for blender).","images":[],"step":3},{"description":"Season to taste with salt and pepper, stir through cream (never boil soup after adding cream, cream will split).","images":[],"step":4},{"description":"Ladle soup into bowls, drizzle over a bit of cream, sprinkle with pepper and parsley if desired. Serve with crusty bread!","images":[],"step":5}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["coronavirus-food","dietary","dinner-tonight","low-calorie-recipes","main-dishes","nagis-picks","pumpkin","quick-and-easy","quick-dinner-ideas-15-minute-meals","soup-recipes","vegan-lifestyle","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5fc7e5dae9a7', 'en', 'US', 'Chop Suey - Chicken Stir Fry', 'Recipe video above. The essential ingredient for a great Chop Suey sauce is Chinese cooking wine. All Chinese restaurants use it! See notes for subs if you can''t get your hands on it. Veggie loaded, light on the meat, this is healthy and adaptable to whatever you''ve got in your fridge!', 'https://www.recipetineats.com/tachyon/2017/11/Chicken-Stir-Fry-Chop-Suey-5.jpg', 9, 6, 14, 2, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.18, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.013, "unit": "tub of 200g"}}, {"id": "ing_flour", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_stems_choy_sum", "quantity": {"value": 5.0, "unit": "unit"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 1.0, "unit": "bag of 250g"}}]', '[{"ingredients":["180g (6oz ) chicken breast (, thinly sliced)","1/2 tsp baking soda / bi-carb (optional, Note 1)"],"purpose":"Optional Tenderised Chicken (Note 1):"},{"ingredients":["1 tbsp cornflour / corn starch","1 1/2 tbsp light soy sauce (, or all purpose soy(Note 3))","1 tbsp Oyster Sauce (Note 4)","1 tbsp Chinese Cooking Wine (OR Mirin (Note 5))","1/2 tsp sesame oil (optional)","Dash of white pepper (or black)","3/4 cup (185 ml) water"],"purpose":"Sauce (or use Charlie, Note 2):"},{"ingredients":["1 1/2 tbsp vegetable oil (or other cooking oil)","2 garlic cloves (, finely chopped)","1/2 onion (, sliced (white, brown, yellow))","5 - 6 stems choy sum (or other Asian greens)","1 medium carrot","1/2 cup sliced mushrooms (shiitake is authentic, but any will do)","1 cup bean sprouts"],"purpose":"Stir Fry:"}]', '[{"description":"\"Velvet\" Chicken (optional, Note 1)","images":[],"step":1},{"description":"Place chicken in a bowl, sprinkle over baking soda. Use your fingers to mix then set aside for 20 minutes, no longer than 30 minutes (can get too tender). Rinse well, pat excess water with paper towels, set aside (see video).","duration":20,"images":[],"step":2},{"description":"Prep Ingredients:","images":[],"step":3},{"title":"Sauce","description":"Place cornflour and soy sauce in a bowl. Mix until lump free. Then add remaining Sauce ingredients and stir.","images":[],"step":4},{"title":"Chop choy sum","description":"Trim end off choy sum. Then cut into 7cm (3\") pieces. Separate stems from leaves.","images":[],"step":5},{"title":"Chop carrot","description":"Peel then cut into 3cm (1.3\") pieces. Then slice the pieces thinly.","images":[],"step":6},{"description":"Heat oil in a wok or skillet over high heat. Add garlic, stir quickly, then add onion, Cook for 1 minute, moving constantly, until onion is starting to wilt.","duration":1,"images":[],"step":7},{"description":"Add chicken, cook for 1 minute until the surface changes from pink to white.","duration":1,"images":[],"step":8},{"description":"Add choy sum stems, carrot and mushrooms. Stir fry for 1 minute.","duration":1,"images":[],"step":9},{"description":"Add choy sum leaves, bean sprouts and Sauce. Stir fry for 1 to 2 minutes until the Sauce thickens to a thick syrup consistency. Vegetables should still be tender/crisp, not soggy and soft.","duration":1.5,"images":[],"step":10},{"description":"Serve immediately with rice (for low carb, low cal option, try Cauliflower Rice!)","images":[],"step":11}]', '["gluten","sesame","soy"]', '["high_protein","low_calorie"]', '{"mealType":["dinner"],"cuisine":["American Chinese"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-recipes","chinese-recipes","dietary","dinner-tonight","low-calorie-recipes","main-dishes","quick-and-easy","quick-dinner-ideas-15-minute-meals","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e299f8e365a5', 'en', 'US', 'Honey Garlic Chicken Breast', 'Recipe video above. An incredible quick and easy way to serve up chicken breast - seared then simmered in the most amazing honey garlic sauce. Don''t be deceived by the short ingredient list! It''s absolutely worth the extra step of dusting the chicken with flour because it creates a crust for the sauce to cling to. BONUS: See notes for how to make this with any protein - beef, pork, lamb, prawns/shrimp, tofu!', 'https://www.recipetineats.com/tachyon/2018/09/Honey-Garlic-Chicken-Breast_5.jpg', 4, 8, 12, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 3.5, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.045, "unit": "bottle of 500ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_honey", "quantity": {"value": 0.167, "unit": "jar of 500g"}}]', '[{"ingredients":["500g / 1 lb chicken breast (, boneless and skinless (2 pieces))","Salt and pepper","1/4 cup flour (Note 1)","3 1/2 tbsp (50g) unsalted butter (or 2 1/2 tbsp olive oil)","2 garlic cloves (, minced)","1 1/2 tbsp apple cider vinegar (or white or other clear vinegar)","1 tbsp soy sauce (, light or all purpose (Note 2))","1/3 cup honey (or maple syrup)"]}]', '[{"description":"Cut the breasts in half horizontally to create 4 steaks in total. Sprinkle each side with salt and pepper.","images":[],"step":1},{"description":"Place flour in a shallow dish. Coat chicken in flour and shake off excess.","images":[],"step":2},{"description":"Melt most of the butter in a large skillet over high heat - hold back about 1 tsp for later.","images":[],"step":3},{"title":"Place chicken in skillet and cook for 2","description":"3 minutes until golden. Turn and cook the other side for 1 minute.","duration":2.5,"images":[],"step":4},{"description":"Turn heat down slightly to medium high.","images":[],"step":5},{"description":"Make a bit of room in the pan and add garlic and top with remaining dab of butter. Stir garlic briefly once butter melts.","images":[],"step":6},{"description":"Add vinegar, soy sauce and honey. Stir / shake pan to combine. Bring sauce to simmer, then simmer for 1 minute or until slightly thickened.","duration":1,"images":[],"step":7},{"description":"Turn chicken to coat in sauce. If the sauce gets too thick, add a touch of water and stir.","images":[],"step":8},{"description":"Remove from stove immediately. Place chicken on plates and drizzle over remaining sauce.","images":[],"step":9}]', '["gluten","milk","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","mains","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_03ed722046cf', 'en', 'US', 'Restaurant Style Chinese Broccoli with Oyster Sauce', 'Recipe video above. Real Restaurant Style Chinese Broccoli with Oyster Sauce, a classic at Yum Cha (Dim Sum). This sauce is the real deal, and it requires more than just oyster sauce to make it restaurant style! This sauce goes fabulously with any Chinese greens, like bok choy and pak choy.', 'https://www.recipetineats.com/tachyon/2014/06/Chinese-Broccoli-with-Oyster-Sauce_8.jpg', 3, 5, 8, 2, '[{"id": "ing_broccoli", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.09, "unit": "L"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.01, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1 bunch Chinese broccoli (\"Gai Lan\") (Note 1)"]},{"ingredients":["1 tsp corn flour / corn starch","6 tbsp water","1 tbsp oyster sauce","1/2 tsp dark soy sauce","1 tbsp Chinese cooking wine (sub Mirin or Dry Sheer, Note 1)","1/2 tsp sesame oil","1/2 tbsp vegetable oil (or canola or peanut)","1/2 tsp sugar","1 clove garlic (, finely grated)","1 tsp ginger (, finely grated)"],"purpose":"Oyster Sauce"}]', '[{"description":"Trim ends off Chinese Broccoli. If any stems are super thick, cut them in half (you want all stems approximately the same width).","images":[],"step":1},{"description":"Steam Chinese Broccoli using whatever method you want - I microwave in a steamer on high for 4 minutes. The stem should be just cooked - not super soft and floppy.","duration":4,"images":[],"step":2},{"description":"Stack the Chinese broccoli together and cut into 4\"/10cm lengths, then stack neatly on top of each other.","images":[],"step":3},{"description":"Combine water and corn flour in small saucepan, mix to dissolve.","images":[],"step":4},{"description":"Then add remaining ingredients, turn stove onto medium and bring to boil. Boil for 30 seconds to allow to thicken, then remove from stove.","duration":0.5,"images":[],"step":5},{"description":"Drizzle over Chinese broccoli and serve. Best served warm.","images":[],"step":6}]', '["gluten","peanuts","sesame","soy"]', '["keto_friendly","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Asian","Chinese"],"categories":["asian-greens","asian-recipes","asian-takeout","chinese-recipes","modern-asian","quick-and-easy","quick-dinner-ideas-15-minute-meals","side-dishes","stir-fries","yum-cha-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_86dfb2d61191', 'en', 'US', 'Fennel Salad with Lemon Dressing and Parmesan', 'Recipe video above. This Fennel Salad is a classic combination - shaved fennel with a zesty lemon dressing and shaved parmesan. It''s the sort of salad you''ll find on the menu of high end bistros and fine dining restaurants. It presents beautifully, tastes refreshing and even people who don''t usually like fennel enjoy it because the fennel flavour is actually very mild!', 'https://www.recipetineats.com/tachyon/2014/06/Fennel-Salad_6.jpg', 5, 0, 5, 4, '[{"id": "ing_fennel", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}]', '[{"ingredients":["1 medium fennel (, or 2 baby fennels)","1/2 red onion (, shaved or finely sliced)","2 tbsp lemon juice","2 1/2 tbsp extra virgin olive oil (, separated)","1/4 tsp salt","1/4 tsp pepper","1/4 cup parmesan cheese (, freshly grated)"]}]', '[{"description":"Cut stalks off fennel (save fronds). Shave the fennel and onion using a mandolin, or slice finely.","images":[],"step":1},{"description":"Place in a bowl. Add lemon juice and 1 1/2 tbsp olive oil, salt and pepper. Toss.","images":[],"step":2},{"description":"Spread out on a plate \"carpaccio\" style. Drizzle with more olive oil, top with freshly grated parmesan then sprinkle with fennel fronds.","images":[],"step":3},{"description":"Serve immediately!","images":[],"step":4}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["lunch"],"cuisine":["American-Italian","Western"],"categories":["all-vegetable-sides","easter-sides-fresh-light","fennel","quick-and-easy","quick-dinner-ideas-15-minute-meals","side-salads","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8b6d2a374fe0', 'en', 'US', 'Creamy Lemon Chicken Breast', 'Recipe video above. Cream and lemon is a luscious combination and is stellar served over crispy chicken! It''s super easy and fast to make, and the sauce is absolutely to die for. A little dusting of flour creates a terrific crispy coating on the chicken and gives the sauce something to cling to.', 'https://www.recipetineats.com/tachyon/2016/01/Creamy-Lemon-Chicken_8.jpg', 5, 10, 15, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 40.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_chicken", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_lemon", "quantity": {"value": 3.0, "unit": "net of 500g"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.375, "unit": "pack of 200g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["600g / 1.2lb chicken breasts (2 large) (Note 1)","1/2 tsp cooking salt (kosher salt)","1/4 tsp Black pepper","1/4 cup flour (plain / all-purpose)","40g / 3 tbsp butter (, unsalted)","1 - 2 garlic clove, minced","1 1/4 cups chicken broth/stock","3/4 cup cream (, heavy/thickened (Note 2))","3 - 4 tbsp lemon juice (adjust to taste, start with 3 tbsp)","2 tsp Dijon mustard","3/4 cup parmesan cheese (, freshly grated OR store bought finely shredded (Note 3))"],"purpose":"Crispy Chicken"},{"ingredients":["Pasta of choice (I used linguine)","Finely chopped parsley"],"purpose":"To serve"}]', '[{"description":"Slice chicken breast horizontally to create two thin steaks (so you end up with 4 thin steaks in total).","images":[],"step":1},{"description":"Sprinkle each side with salt and pepper, then coat with flour, shaking off excess.","images":[],"step":2},{"description":"Melt butter in a large skillet over medium high heat. Cook chicken 2 minutes on each side until golden and crispy, then remove onto plate.","images":[],"step":3},{"title":"Add a touch of butter if your pan is dry","description":"but you shouldn''t need it. Add garlic, stir 10 seconds.","images":[],"step":4},{"description":"Then add chicken broth, cream, lemon and Dijon mustard. Bring to simmer and scrape the bottom of the pan to dissolve brown bits into the liquid. Use a whisk if needed to dissolve mustard.","images":[],"step":5},{"description":"Add parmesan then simmer rapidly for 3 minutes or until sauce thickens slightly. Add salt, pepper and adjust lemon to taste.","duration":3,"images":[],"step":6},{"description":"Return the chicken to the pan (pour in any juices on the plate too), turn to coat.","images":[],"step":7},{"description":"Place chicken on serving plates with pasta or mashed potatoes. Sprinkle with fresh parsley if using. Spoon over Lemon Sauce and serve! (Bread for mopping wouldn''t go astray either)","images":[],"step":8}]', '["gluten","milk","mustard"]', '["high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","most-popular","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_123fd1c11d33', 'en', 'US', 'Vermicelli Noodle Salad', 'Recipe video above. This noodle salad is a great refreshing salad for any Asian mains - and especially for BBQ''s! This salad will suit most South East Asian Cuisines, including Thai, Vietnamese, Korean and Chinese.', 'https://www.recipetineats.com/tachyon/2014/08/Vermicelli-Noodle-Salad_7.jpg', 15, 0, 10, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.2, "unit": "pack of 500g"}}, {"id": "ing_cabbage", "quantity": {"value": 6.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 225.0, "unit": "pack of 1kg"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 1.5, "unit": "bag of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.04, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.04, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["100g / 4 oz dried vermicelli noodles (Note 1)","2 cups white or green cabbage (, shredded)","1 1/2 cups shredded carrot (1 medium carrot)","1 1/2 cups bean sprouts","2 green onions (, finely sliced)","1/2 cup coriander/ cilantro leaves"]},{"ingredients":["2 tbsp light soy sauce","2 tbsp rice wine vinegar","1 1/2 tsp sugar","1 1/2 tbsp grapeseed oil (or any other neutral oil)","1 garlic clove (, minced)","1 birds eye chilli (, finely minced )"],"purpose":"Dressing (Note 2 for substitutions)"},{"ingredients":["Fried Asian Shallots (, to garnish (optional))","Red chilli (, finely sliced)"],"purpose":"Garnishes (optional)"}]', '[{"description":"Combine dressing ingredients in a jar and shake well to combine. Set aside for 5 minutes for the flavours to infuse.","duration":5,"images":[],"step":1},{"description":"Prepare vermicelli noodles per packet directions (usually soak in warm or boiling water 2 minutes). Drain well then set aside for 10 minutes to drain off exces water. Turn out onto tea towel if necessary to dry more (watery noodles = watery flavour).","duration":10,"images":[],"step":2},{"description":"Combine vermicelli noodles with remaining salad ingredients.","images":[],"step":3},{"description":"Just prior to serving, toss through dressing. Garnish with Fried Asian Shallots if you wish.","images":[],"step":4}]', '["gluten","soy"]', '["low_calorie","vegan","vegetarian"]', '{"mealType":["dinner","lunch"],"cuisine":["Asian","Chinese","Japanese","Korean","Thai","Vietnamese"],"categories":["asian-recipes","no-cook-food","noodles","quick-and-easy","quick-dinner-ideas-15-minute-meals","salad-recipes-main-course","side-salads","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_61321419c229', 'en', 'US', 'Green Bean Salad', 'A very easy green bean salad that I like to make when I''m entertaining because it can be largely prepared ahead.', 'https://www.recipetineats.com/tachyon/2015/05/Green-Bean-Salad_2a.jpg', 10, 3, 13, 5, '[{"id": "ing_green_beans", "quantity": {"value": 453.592, "unit": "pack"}}, {"id": "ing_tomato", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.25, "unit": "pack of 1kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.045, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 lb / 500g green beans (, trimmed)","1 tomato (, diced)","1/4 red onion (, finely diced)"]},{"ingredients":["1 1/2 tbsp lemon juice (or white wine vinegar)","3 - 4 tbsp extra virgin olive oil (adjust to taste)","1 tsp dijon mustard","1 garlic clove","Salt and pepper"],"purpose":"Dressing"},{"ingredients":["Finely chopped parsley (optional)"],"purpose":"Garnish"}]', '[{"description":"Combine the Dressing ingredients in a jar and shake well. Set aside - or refrigerate up to 2 days. Bring to room temperature before using.","images":[],"step":1},{"description":"Bring a large pot of salted water to boil. Add the beans, bring it back up to a boil and boil beans for 60 seconds - no more!","duration":1,"images":[],"step":2},{"description":"Drain and plunge in ice cold water (or run under cold tap water) to stop them from cooking.","images":[],"step":3},{"description":"If making ahead, leave in the colander to dry before transferring to the fridge.","images":[],"step":4},{"description":"To serve, pile the beans on a plate, top with tomato and red onion, drizzled over dressing. Sprinkle with parsley if using.","images":[],"step":5}]', '["mustard"]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["lunch"],"cuisine":[],"categories":["all-vegetable-sides","dietary","easter-sides-fresh-light","gluten-free-recipes","green-beans","quick-and-easy","quick-dinner-ideas-15-minute-meals","side-salads","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d057c0c4e65d', 'en', 'US', 'Beef Stir Fry with Honey and Black Pepper Sauce', 'Recipe video above. Copycat of restaurant style Chinese Beef with Honey and Black Pepper Sauce. Very fast and easy to make - it''s on the table in 15 minutes! The sauce is absolutely divine - sticky, sweet, salty and with a subtle burst of heat from the black pepper.', 'https://www.recipetineats.com/tachyon/2015/07/Chinese-Honey-Pepper-Beef_1.jpg', 10, 5, 15, 4, '[{"id": "ing_soy_sauce", "quantity": {"value": 0.15, "unit": "bottle of 250ml"}}, {"id": "ing_honey", "quantity": {"value": 0.09, "unit": "jar of 500g"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.045, "unit": "bottle of 500ml"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_beef_steak", "quantity": {"value": 0.5, "unit": "kg"}}]', '[{"ingredients":["2 1/2 tbsp soy sauce (Note 1)","3 tbsp honey","1 1/2 tbsp Oyster sauce (sub Hoisin)","1 1/2 tbsp Chinese cooking wine (, Mirin or dry sherry (Note 2))","2 tbsp water","1 tsp coarsely crushed black pepper (or 1/2 tsp normal ground black pepper)"],"purpose":"Sauce"},{"ingredients":["2 tbsp peanut oil (or vegetable or canola oil)","1 garlic clove (, finely minced)","1/2 onion (, peeled and sliced)","500g/1 lb thinly sliced tenderloin, flank, sirloin/Porterhouse/strip, (or any other cut of steak suitable for stir frying (Notes 3))"],"purpose":"Stir Fry"}]', '[{"description":"Mix the Sauce ingredients in a bowl.","images":[],"step":1},{"description":"Heat the oil in a wok or large heavy based skillet over high heat until it is smoking.","images":[],"step":2},{"description":"Add the onion and garlic and cook for 1 minute or until the onion becomes translucent. Keep it moving so the garlic doesn''t burn.","duration":1,"images":[],"step":3},{"description":"Add the beef and stir fry for 1 minute until just cooked to your liking, then remove into bowl.","duration":1,"images":[],"step":4},{"title":"Turn the heat down to medium high, pour in Sauce","description":"it will start simmering very quickly! Let it cook for 1 minute or so until it becomes syrupy - the bubbles will be larger and caramel colour.","duration":1,"images":[],"step":5},{"description":"Add the beef and onion back into the wok, along with any juices pooled on the plate. Toss in the sauce until just warmed through - 1 minute at most. Don''t overcook the beef - that would be tragic!","images":[],"step":6},{"title":"Serve immediately with rice","description":"or for a low carb, low cal option, try Cauliflower Rice!","images":[],"step":7}]', '["gluten","peanuts","soy"]', '["high_protein","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","beef-recipes","chinese-recipes","dinner-tonight","main-dishes","most-popular","quick-and-easy","quick-dinner-ideas-15-minute-meals","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_94900fef52f6', 'en', 'US', 'Thai Chilli Basil Chicken', 'Recipe video above. Right off the streets of Thailand, made in your own home! Spicy, garlicky and savoury with a hint of sweet. Gold standard Thai chicken stir fry, quick to make and no hunting down unusual ingredients.', 'https://www.recipetineats.com/tachyon/2017/03/Thai-Chilli-Basil-Chicken_6.jpg', 10, 5, 15, 2, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_basil", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_oil", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["225g / 7oz chicken thigh fillets (, skinless boneless, cut into bite size pieces)","1 green onion (, cut into 4cm / 2\" lengths.)","1 cup Thai basil leaves (, loosely packed (Holy Basil if you can find it) (Note 1))","2 garlic cloves (, large, finely chopped (Note 2))","1 birds eye or Thai chilli (, deseeded and finely chopped)","1 1/2 tbsp oil (peanut, vegetable or canola)"]},{"ingredients":["2 tsp oyster sauce","1 tsp light soy sauce (Note 3)","1 tsp dark soy sauce (or all purpose) (Note 3)","1 tsp sugar","2 tbsp water"],"purpose":"Sauce"},{"ingredients":["Steamed jasmine rice"],"purpose":"Serving"}]', '[{"description":"Put Sauce ingredients in a small bowl and mix to combine.","images":[],"step":1},{"description":"Heat oil in wok or pan over high heat.","images":[],"step":2},{"description":"Add garlic and chilli and cook for 10 seconds. Don''t inhale - the chilli will make you cough!","duration":0.16666666666666666,"images":[],"step":3},{"description":"Add the white part of the green onions and chicken and fry until cooked, around 2 minutes.","images":[],"step":4},{"description":"Add Sauce and cook for 1 minute until the water reduces to make a thick glossy sauce.","duration":1,"images":[],"step":5},{"description":"Toss through green part of green onions and basil leaves. Stir until just wilted, then serve immediately with steamed jasmine rice.","images":[],"step":6}]', '["gluten","peanuts","soy"]', '["keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-recipes","cuisines","most-popular","quick-and-easy","quick-dinner-ideas-15-minute-meals","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_702974fc47c5', 'en', 'US', 'Healthy Parmesan Garlic Crumbed Fish', 'Recipe video above. Packed generously with a thick, crunchy coating of parmesan and garlic breadcrumbs, this is one fish that everyone is sure to love. Using this recipe, you''ll get perfectly golden crumbs and perfectly cooked fish every time. And the clincher? It''s on the table in just over 10 minutes. I made this using perch fillets (skin off) but you can use any firm white fish fillets.', 'https://www.recipetineats.com/tachyon/2014/07/Parmesan-Baked-Fish_1.jpg', 5, 7, 12, 2, '[{"id": "ing_fish_fillets", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.15, "unit": "jar of 200g"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 0.094, "unit": "loaf"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2 firm white fish fillets ((about 5 oz / 150g each), skin off, at room temperature)","2 tbsp dijon mustard (sub mayo)","Olive oil spray","Salt and pepper"]},{"ingredients":["1/2 cup panko breadcrumbs","1 tbsp parsley (, finely chopped)","1/3 cup (30g) parmesan (, finely grated)","1 garlic clove (, minced)","1 tbsp olive oil","Pinch of salt"],"purpose":"Crumb"}]', '[{"description":"Preheat grill / broiler on high.","images":[],"step":1},{"description":"Combine the Crumb ingredients and mix well to combine.","images":[],"step":2},{"description":"Sprinkle both sides of fish with salt and pepper, then spread the mustard on the top of each fillet (top only).","images":[],"step":3},{"description":"Press the mustard smeared side of the fish into the crumb mixture. Press down firmly to make it stick. Then spray with oil (for extra golden crumb!).","images":[],"step":4},{"description":"Drizzle 1/2 tbsp oil in a skillet and preheat on the stove over high heat.","images":[],"step":5},{"description":"Once skillet is hot, place the fillets in the hot pan then place under the grill / broiler (about 5\"/15cm from the heat source) for 5 - 6 minutes until the crumb is golden and the fish is cooked, rotating as required. Fish should flake in centre once cooked.","duration":5.5,"images":[],"step":6},{"title":"Oven option: bake at 220C/390F for 10","description":"12 minutes, then finish under the grill/broiler on high to make the crumb golden.","duration":11,"images":[],"step":7},{"description":"Serve immediately with lemon wedges!","images":[],"step":8}]', '["fish","milk","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["dietary","dinner-tonight","emergency-recipes","fish-recipes","low-calorie-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_fa2342ba401a', 'en', 'US', 'Baked Fish with Lemon Cream Sauce (One Baking Dish!)', 'Recipe video above. A fantastic quick-fix dinner - baked fish in a lemon cream sauce, all made in ONE PAN! Don''t let the short ingredient list fool you, this tastes so good! The key to the tasty sauce is the fish juices that leeches out while baking and is essentially the broth for the sauce!', 'https://www.recipetineats.com/tachyon/2016/10/Baked-Fish-with-Lemon-Cream-Sauce_9.jpg', 5, 10, 15, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_cream", "quantity": {"value": 0.25, "unit": "carton of 250ml"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_lemon", "quantity": {"value": 0.045, "unit": "net of 500g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 22.5, "unit": "pack of 1kg"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["4 x 150- 180g / 5 - 6 oz fish fillets (, about 1.5cm / 1/2\" thick, skinless and boneless (Note 1))","50g / 4 tbsp unsalted butter","1/4 cup cream, heavy / thickened (See Note 2 for sub options)","1 - 2 garlic cloves (, minced)","1 tbsp Dijon mustard","1 1/2 tbsp lemon juice","Salt & pepper","1 1/2 tbsp eschallots (French onion) (, finely chopped (Note 3))","Fresh parsley and lemon slices (, to serve)"]}]', '[{"description":"Preheat oven to 200°C / 390°F (all oven types).","images":[],"step":1},{"title":"Place fish in a baking dish","description":"ensure the fish isn''t crammed in too snugly. See video or photos in post. Sprinkle both sides of fish with salt and pepper.","images":[],"step":2},{"description":"Place butter, cream, garlic, mustard, lemon juice, salt and pepper in a microwave proof jug or bowl. Microwave in 2 x 30 sec bursts, stirring in between, until melted and smooth.","images":[],"step":3},{"description":"Sprinkle fish with shallots, then pour over sauce.","images":[],"step":4},{"title":"Bake for 10","description":"12 minutes, or until fish is just cooked. Remove from oven and transfer fish to serving plates. Spoon over sauce, and garnish with parsley and lemon wedges if using.","duration":11,"images":[],"step":5}]', '["fish","milk","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","dinner-tonight","easter-mains-fish-seafood","emergency-recipes","fish-recipes","low-calorie-recipes","main-dishes","most-popular","one-pot-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_338eae1fe368', 'en', 'US', 'Chow Mein Ramen Noodles', 'Recipe video above. The fastest, easiest Chow Mein recipe ever! Made using a couple of cheeky shortcuts - ramen noodles, a Coleslaw mix, with the noodles cooked in the same skillet. It''s a quicker version of real Chow Mein - 99% of the flavour, but FASTER!', 'https://www.recipetineats.com/tachyon/2019/06/Chow-Mein-Ramen_3.jpg', 7, 8, 15, 2, '[{"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_chicken", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 2.0, "unit": "pack of 500g"}}, {"id": "ing_pre_shedded_coleslaw_mix", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.06, "unit": "bunch"}}, {"id": "ing_heaped_cup_beansprouts", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1 tbsp oil","200g/7oz chicken (, sliced (thigh, breast))","2 garlic cloves (, minced)","2 ramen or instant noodle cakes (, discard seasoning (Note 1))","200g/7oz pre shedded Coleslaw mix (, cabbage and carrot (Note 2))","3 green onion stems (, cut into 5cm/2\" lengths)","1 heaped cup beansprouts","1 cup (250 ml) water"]},{"ingredients":["1.5 tbsp light soy sauce (Note 3)","1.5 tbsp Oyster Sauce (Note 4)","1 tbsp Chinese Cooking Wine or Mirin (Note 5)","2 tsp sesame oil (, toasted (Note 6))","1 tsp white sugar (SKIP if using Mirin)"],"purpose":"Chow Mein Sauce:"}]', '[{"description":"Mix Sauce in a bowl.","images":[],"step":1},{"description":"Heat oil in a large skillet over high heat. Add garlic, cook 10 seconds.","images":[],"step":2},{"description":"Add chicken and cook until mostly changes from pink to white, then add Sauce.","images":[],"step":3},{"description":"Cook for 1 minute, then add Coleslaw mix and white part of green onions.","duration":1,"images":[],"step":4},{"description":"Cook for 1 1/2 minutes until cabbage wilts, then push everything to the side to make room for the ramen (see video & photos in post).","images":[],"step":5},{"description":"Add water then squidge the ramen cakes in side by side.","images":[],"step":6},{"description":"When water simmers, leave for 45 seconds. Flip, then leave for 30 seconds.","duration":0.75,"images":[],"step":7},{"description":"Loosen noodles, add bean sprouts and green onion, then toss energetically for 1 1/2 - 2 minutes until sauce reduces and coats noodles. (Note 7)","images":[],"step":8},{"description":"Serve immediately!","images":[],"step":9}]', '["gluten","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-recipes","dinner-tonight","emergency-recipes","noodles","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_75598a23ec49', 'en', 'US', 'Lime Marinated Grilled Chicken', 'Recipe video above. This lime marinade has a beautiful depth of flavour and really infuses the chicken with lime flavours! Touch of sugar caramelises the chicken, and depth of flavour is achieved by using soy or fish sauce instead of salt (it doesn''t taste Asiany at all, I swear!). Stove or BBQ best, but can also bake!', 'https://www.recipetineats.com/tachyon/2016/04/Lime-Chicken_2.jpg', 5, 10, 15, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 600.0, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 0.12, "unit": "net of 500g"}}, {"id": "ing_lime", "quantity": {"value": 0.12, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.015, "unit": "kg"}}]', '[{"ingredients":["600-750g / 1.2 - 1.5 lb chicken breasts (4 pieces) or boneless thigh ( (Note 1))","Zest of 1 lime (zest before juicing)","4 tbsp lime juice (1 - 2 limes)","2 garlic cloves (, minced)","3 tbsp brown sugar","1/4 tsp pepper","1 tbsp olive oil","2 tbsp finely chopped cilantro/coriander (optional)","1 tbsp fish sauce (OR 2 tbsp soy sauce) ( (Note 2))"],"purpose":"Chicken Marinade"},{"ingredients":["1 - 2 tbsp olive oil"],"purpose":"To Cook"}]', '[{"description":"Use fist (or rolling pin!) to pound fat end of chicken breast to about 1.7 cm / 2/3\" thickness (not required for thigh).","images":[],"step":1},{"description":"Place chicken and Marinade in a ziplock bag, massage to distribute marinade evenly. Place on a plate or bowl and refrigerate for 24 hours (min 12 hrs, max 48 hrs - Note 3)","images":[],"step":2},{"description":"Remove chicken, discard Marinade. Cook using one method below.","images":[],"step":3},{"description":"To Cook (cooked internal temp 165F/75C)","images":[],"step":4},{"title":"STOVE","description":"Heat oil in a large skillet over medium high heat. Cook chicken for 3 minutes on each side or until caramelised and golden brown (see video!).","duration":3,"images":[],"step":5},{"title":"BBQ","description":"Brush grills with oil and heat to medium high (or medium if your BBQ is strong). Cook chicken for 3 minutes on each side until caramelised (see video!).","duration":3,"images":[],"step":6},{"title":"OVEN","description":"Preheat oven to 425F/220C. Bake 15 minutes, then flick broiler/grill on high and grill for 3 minutes to caramelise surface & finish cooking.","duration":3,"images":[],"step":7},{"description":"Rest and Serve:","images":[],"step":8},{"description":"Transfer chicken to a serving plate, cover loosely with foil and rest for 3 minutes.","duration":3,"images":[],"step":9},{"description":"Garnish with extra coriander/cilantro, lime wedges and chilli if desired, then serve!","images":[],"step":10}]', '["fish","gluten","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","grilling-ideas-and-recipes","low-calorie-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5f12dbf5e47c', 'en', 'US', 'Drunken Noodles (Pad Kee Mao)', 'Recipe video above. Spicy Thai Noodles, a popular Thai take-out dish from the streets of Thailand! Make sure you have all ingredients ready to toss into the wok as once you start cooking, things happen quickly! Spice level: moderate to high (it''s SUPPOSED to be spicy!)', 'https://www.recipetineats.com/tachyon/2014/07/Close-up-Thai-Drunken-Noodles-1.jpg', 10, 6, 16, 2, '[{"id": "ing_rice_noodles", "quantity": {"value": 0.529, "unit": "pack of 375g"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 1000.0, "unit": "pack of 3 heads"}}, {"id": "ing_chilli", "quantity": {"value": 2.0, "unit": "pack of 100g"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.04, "unit": "bunch"}}, {"id": "ing_basil", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.015, "unit": "L"}}]', '[{"ingredients":["7 oz /200g dried rice noodles (, wide (Note 1))"],"purpose":"Noodles"},{"ingredients":["2 tbsp oil (peanut, vegetable or canola)","3 large cloves of garlic (, minced)","2 birds eye chilli or Thai chillies (, deseeded, very finely chopped (Note 2))","1/2 onion (, sliced)","200 g /7oz chicken thighs (, cut into bite size pieces (breast ok too))","2 tsp fish sauce (or soy sauce)","2 green onions (, cut into 3cm/2\" pieces)","1 cup Thai or Thai Holy Basil leaves (sub regular basil, Note 3)"],"purpose":"Stir Fry"},{"ingredients":["3 tbsp oyster sauce","1 1/2 tbsp light soy sauce (Note 4)","1 1/2 tbsp dark soy sauce (Note 4)","2 tsp sugar","1 tbsp water"],"purpose":"Sauce"}]', '[{"description":"Prepare noodles per packet directions.","images":[],"step":1},{"description":"Mix Sauce in a small bowl.","images":[],"step":2},{"description":"Heat oil in wok or large heavy based skillet over high heat.","images":[],"step":3},{"description":"Add garlic and chilli and cook for 10 seconds. Don''t inhale - the chilli will make you cough!","duration":0.16666666666666666,"images":[],"step":4},{"description":"Add onion, cook for 1 minute.","duration":1,"images":[],"step":5},{"description":"Add chicken and fish sauce, and fry until cooked, around 2 minutes.","images":[],"step":6},{"description":"Add green onion, noodles and sauce and cook for 1 minute until the sauce reduces and coats the noodles.","duration":1,"images":[],"step":7},{"description":"Remove from heat and immediately add basil, toss until just wilted, then serve immediately.","images":[],"step":8}]', '["fish","gluten","peanuts","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-recipes","cuisines","dinner-tonight","most-popular","noodles","quick-and-easy","quick-dinner-ideas-15-minute-meals","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9428a4025c5e', 'en', 'US', 'One Pot Chicken, Vegetable & Parmesan Orzo (Risoni)', 'Recipe video above. Tastes just like risotto.... except it''s far quicker to make! Also known as Orzo, this risoni recipe comes with juicy chicken, a creamy parmesan sauce and plenty of hidden vegetables. It''s a quick one pot recipe the kids are sure to love. (And grown ups too!)', 'https://www.recipetineats.com/tachyon/2014/06/Chicken-Vegetable-Risoni_9.jpg', 10, 10, 20, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_frozen_vegetables", "quantity": {"value": 2.5, "unit": "unit"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.45, "unit": "pack of 500g"}}, {"id": "ing_flour", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.562, "unit": "L"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_baby_spinach", "quantity": {"value": 3.0, "unit": "bag of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.375, "unit": "pack of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.375, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","1/2 onion (, diced)","250g / 8oz chicken thigh or breast (, cut into bite size pieces)","2 1/2 cups frozen diced vegetables (carrots, peas, corn, capsicum/peppers, anything!)","1 1/2 cups orzo / risoni (, uncooked (Note 1))","1 1/2 tbsp flour","2 1/4 cups milk (, any fat %)","2 cups chicken or vegetable stock / broth (low sodium)","3 cups baby spinach (packed)","3/4 cup (tightly packed) parmesan (, finely grated (or store bought sandy type))","1/4 tsp cooking salt / kosher salt","1/4 tsp black pepper"]},{"ingredients":["More parmesan","Parsley or chives, if desired"],"purpose":"Serving"}]', '[{"description":"Heat oil in a large pan over high heat. Make sure the pan is reasonably deep - around 5cm / 2.5\" or more. Otherwise, use a large pot.","images":[],"step":1},{"title":"Sear chicken","description":"Add garlic and onion, cook for 1 minute. Add chicken, then cook for 2 minutes until seared on the outside but still raw inside.","duration":1,"images":[],"step":2},{"title":"Vegetables and flour","description":"Add frozen vegetables (still frozen ok) and flour, stir until flour is incorporated.","images":[],"step":3},{"title":"Add uncooked risoni","description":"Add risoni/orzo, stock and milk, then stir well.","images":[],"step":4},{"title":"Cook 7 minutes","description":"Bring to simmer then adjust heat so it''s bubbling gently (see video). Cook for 7 minutes (no lid), stirring every now and then, until risoni is almost tender (still quite soupy at this stage).","duration":7,"images":[],"step":5},{"description":"Add parmesan, spinach, salt and pepper. Stir through until the spinach is wilted.","images":[],"step":6},{"title":"Serve","description":"The consistency should be like a loose risotto (it absorbs liquid and thickens quite quickly when serving), nice and creamy. Serve, garnished with parsley and more parmesan if desired!","images":[],"step":7}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","most-popular","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_625457ad8802', 'en', 'US', 'Asian Beef Bowls', 'Recipe VIDEO above. A fabulous quick stir fry made using beef mince (ground beef) <<-- No slicing meat! It''s not saucy like usual stir fries, you don''t need sauce because the beef mixes through the rice, and it has plenty of flavour and it''s JUICY. Great recipe to add diced or julienned veggies!', 'https://www.recipetineats.com/tachyon/2017/05/Asian-beef-Bowls.jpg', 5, 7, 12, 4, '[{"id": "ing_hoisin_sauce", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.15, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 2.5, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.5, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1 tbsp Hoisin Sauce (or sub with Oyster)","2 tbsp Oyster Sauce (or sub with 1 1/2 tbsp Hoisin)","1 tbsp Chinese cooking wine (or Mirin, dry sherry, sake or any rice wine) (Note 1)","2 1/2 tbsp dark soy sauce (Note 2)","2 tsp white sugar","1/2 tsp sesame oil","1/4 tsp white pepper (or sub with black)"],"purpose":"Sauce:"},{"ingredients":["1 tbsp oil","2 garlic cloves, minced","1 small onion, finely chopped","500 g /1 lb beef mince (ground beef) ( (lean is good))","1/2 cup shallots / scallions (, sliced, plus more for garnish)"],"purpose":"Stir Fry:"},{"ingredients":["Sesame seeds"],"purpose":"Garnishes:"}]', '[{"description":"Mix Sauce together in a bowl","images":[],"step":1},{"description":"Heat oil in a large skillet over high heat. Add garlic and onion, cook for 1 minute or until onion starts browning.","duration":1,"images":[],"step":2},{"description":"Add beef and cook, breaking it up as you go.","images":[],"step":3},{"description":"Once the beef has all changed from red to brown, add Sauce. Cook for a further 2 minutes, or until Sauce has evaporated and beef is cooked. If you want the beef cooked more, add a splash of water and keep cooking (I don''t do this).","images":[],"step":4},{"description":"Stir through shallots, then serve over rice, garnished with more shallots and sesame seeds, if desired. Or for a low carb, low cal option, try Cauliflower Rice!","images":[],"step":5}]', '["gluten","sesame","shellfish","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","beef-mince-recipes","beef-recipes","chinese-recipes","dinner-tonight","emergency-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0cdfb0f33e26', 'en', 'US', 'Noodle Salad With Creamy Sesame Peanut Dressing', 'Recipe video above. A vegetable noodle salad with a dressing that''s creamy, peanutty, with a hint of sesame, tang of lime and mild hit of chilli. GREAT work lunch idea - keeps for days, terrific served cold. Try adding shredded chicken! Also great side for Asian meals. Serves 3 as a meal, or 4 to 5 as a side.', 'https://www.recipetineats.com/tachyon/2014/07/Noodle-Salad-Creamy-Sesame-Peanut-Dressing_5.jpg', 15, 0, 15, 3, '[{"id": "ing_peanut_butter", "quantity": {"value": 0.1, "unit": "jar of 375g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_chilli", "quantity": {"value": 0.3, "unit": "pack of 100g"}}, {"id": "ing_sriracha", "quantity": {"value": 0.037, "unit": "bottle of 400ml"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_water", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.7, "unit": "pack of 500g"}}, {"id": "ing_carrot", "quantity": {"value": 225.0, "unit": "pack of 1kg"}}, {"id": "ing_beansprouts", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_green_beans", "quantity": {"value": 225.0, "unit": "pack"}}, {"id": "ing_capsicum", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.06, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.15, "unit": "pack of 100g"}}]', '[{"ingredients":["1/4 cup peanut butter (, preferably smooth (Note 1))","1 tbsp sesame oil (, toasted (Note 2))","1 tbsp canola oil (or other neutral oil)","2 tbsp soy sauce (Note 3)","2 tbsp sweet chilli sauce","1 tbsp sriracha (adjust spiciness to taste)","2 tbsp lime juice (sub rice or cider vinegar)","1 garlic clove (, minced)","2 to 4 tbsp water (, if needed)"],"purpose":"Dressing"},{"ingredients":["350g / 12 oz fresh egg noodles (about 4 cups, packed)","1.5 cups carrot (, julienned (1 large or 2 small carrots))","2 cups beansprouts","1.5 cups green beans (, halved)","1.5 cups red bell pepper/capsicum (, finely sliced (1 large))","3 green onion stems (, finely sliced on the diagonal )","1 tbsp white sesame seeds (preferably toasted)"],"purpose":"Salad"}]', '[{"description":"Prepare noodles according to packet directions (most just require soaking in hot water). Drain, rinse and set aside to cool.","images":[],"step":1},{"title":"Dressing","description":"Mix together Dressing ingredients, using water only if needed to loosen so it can be tossed through salad. If you reduce Sriracha, might need to add smidge more lime.","images":[],"step":2},{"title":"Beans","description":"Steam or boil green greens until just cooked, tender but still crisp. Drain under running water to cool.","images":[],"step":3},{"title":"Toss","description":"Place salad ingredients in a big bowl, toss with dressing.","images":[],"step":4},{"description":"Garnish with sesame seeds then serve at room temp. Keeps 4 days in the fridge.","images":[],"step":5}]', '["egg","gluten","peanuts","sesame","soy"]', '["vegetarian"]', '{"mealType":["dinner","lunch"],"cuisine":["Asian","Thai"],"categories":["asian-recipes","dinner-tonight","no-cook-food","noodles","quick-and-easy","quick-dinner-ideas-15-minute-meals","salad-recipes-main-course","side-dishes","side-salads","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e2b92cde4e5d', 'en', 'US', 'Fried Rice', 'Recipe video above. Fried rice is a side that goes with all Chinese and Asian foods! This one truly stacks up to your favourite Chinese restaurant, a reader favourite included in my debut cookbook Dinner. See notes for scaling recipe up and using skillet instead of wok, and for GF option.Don''t have day old rice? No worries. Make this reader-favourite Emergency Baked Fried Rice instead.', 'https://www.recipetineats.com/tachyon/2018/03/Egg-Fried-Rice_5-1.jpg', 5, 10, 15, 2, '[{"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 112.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_bacon", "quantity": {"value": 0.6, "unit": "pack of 200g"}}, {"id": "ing_vegetables", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_white_rice", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_green_onion", "quantity": {"value": 2.25, "unit": "bunch"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["2 tbsp oil","1/2 onion (, finely chopped)","2 garlic cloves (, minced)","120 g/4 oz bacon (, chopped (optional, or use ham))","1 - 1 1/2 cups diced vegetables (, frozen or fresh (Note 1))","2 cups (packed) cooked day old white rice (refrigerated or frozen defrosted, Note 2)","3 eggs, whisked","3/4 cup green onions (, (shallots / scallions) sliced)"]},{"ingredients":["1 tbsp Chinese cooking wine (sub Mirin, cooking sake or dry sherry) (Note 4)","1 tbsp Oyster Sauce","1 tbsp light soy sauce (or all purpose) (Note 5)","1 tsp sesame oil (, optional)","1/4 tsp white pepper"],"purpose":"Sauce:"}]', '[{"title":"Heat oil","description":"Heat about 1 1/2 tbsp oil in a wok or 2 tbsp oil in a skillet over high heat until smoking.","images":[],"step":1},{"description":"Add onion, garlic and bacon. Cook until bacon is light golden - about 1 1/2 minutes.","images":[],"step":2},{"description":"Add vegetables (still frozen is fine). Cook for 2 minutes so they defrost and water evaporates.","duration":2,"images":[],"step":3},{"description":"Add rice and Sauce ingredients. Cook for 1 1/2 minutes until liquid evaporates.","images":[],"step":4},{"title":"Scramble egg","description":"Shove rice to the side of the wok / skillet. Add 1/2 tbsp oil into the cleared space, shift wok so the heat is centred over the cleared space. Pour in egg then scramble - cook it through properly, don''t \"soft scramble\".","images":[],"step":5},{"title":"Serve","description":"Add green onion then stir the egg into the rice. Remove from heat and serve immediately!","images":[],"step":6}]', '["egg","gluten","sesame","soy"]', '[]', '{"mealType":["main_course"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","asian-takeout","chinese-recipes","dietary","dinner-tonight","egg-recipes","fried-rice","gluten-free-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","rice-recipes","rice-side-dishes","side-dishes","yum-cha-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5d7d6ed9afef', 'en', 'US', 'Crispy Pan Fried Fish', 'Recipe video above. 3 key tips to ensure your pan fried fish comes out beautifully golden and crispy every time: pat the fish dry, press flour on well but shake excess off well, and heat the pan first before adding the oil or use a heavy duty non stick pan. With a good fish, well seasoned and crispy skin, I don''t need a sauce....but I''ve added a couple in the notes just in case! :)', 'https://www.recipetineats.com/tachyon/2017/06/Crispy-Pan-Fried-Fish-3-1.jpg', 3, 5, 8, 2, '[{"id": "ing_fish_fillets", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_oil", "quantity": {"value": 2.0, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["2 thin fish fillets, around 150g/5 oz each, 1 cm / 2/5\" thick, skin on or off (Note 1)","Salt and pepper","1/4 cup / 35g flour (plain/all purpose, wholemeal)","1 tsp paprika (, optional (Note 2))","2 - 3 tbsp oil, enough to mostly thinly cover base (I use vegetable or canola)"]},{"ingredients":["Lemon wedges","Finely chopped parsley or dill (, for garnish, optional)"],"purpose":"Garnishes:"}]', '[{"description":"Use scrunched up paper towels to pat the fish dry on both sides. This is especially important if you are using thawed frozen fish.","images":[],"step":1},{"description":"Season the fish well on both sides with salt and pepper (key!).","images":[],"step":2},{"description":"Mix the flour and paprika on a plate.","images":[],"step":3},{"description":"Coat fish on both sides with flour, pressing down firmly so it adheres, but shake well to remove excess. (Note 2)","images":[],"step":4},{"description":"Heat a heavy based skillet (normal or non stick) over medium high heat until you see wisps of smoke. Add oil and swirl to coat the pan - it will heat within seconds.","images":[],"step":5},{"title":"Add fish","description":"it should sizzle straight away. Shake the pan lightly to move the fish. Cook for 2 minutes until golden and crisp, pressing down gently, then flip. Cook the other side for 2 minutes until crisp then remove.","duration":2,"images":[],"step":6},{"description":"If it''s browning too quickly, just remove pan from the stove briefly. If it''s stuck, don''t move - it will release naturally once golden.","images":[],"step":7},{"description":"Serve fish immediately with lemon wedges and garnished with dill or parsley, if using. It starts to lose crispiness after 5 minutes.","images":[],"step":8}]', '["fish","gluten"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","fish-recipes","main-dishes","quick-and-easy","quick-dinner-ideas-15-minute-meals","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bade5c6254d0', 'en', 'US', 'Couscous Salad with Sun Dried Tomato and Feta', 'Recipe VIDEO above. A 12 minute, no cook, giant Couscous Salad with sun dried tomato, feta, rocket / arugula, herbs and the added nutty tastiness of chickpeas. My shortcut-flavour tip is to use the oil from the sun dried tomato jar as the dressing - free flavour! The flavour pops from the sun dried tomato and feta are quite intense, so this truly is satisfying to have as a meal, or as a substantial side. This makes quite a lot - serves 5 as a main, or 8 - 10 as a side. Keeps very well.', 'https://www.recipetineats.com/tachyon/2018/01/Couscous-Salad-with-Sun-Dried-Tomato_5a.jpg', 12, 0, 12, 5, '[{"id": "ing_couscous", "quantity": {"value": 187.5, "unit": "pack"}}, {"id": "ing_water", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.22, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 2.4, "unit": "head"}}, {"id": "ing_lemon", "quantity": {"value": 0.15, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.15, "unit": "net of 500g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_feta_cheese", "quantity": {"value": 60.0, "unit": "block of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["1 1/4 cups dried couscous (Note 1)","1 1/4 cups / 315 ml boiled water","1 tsp vegetable stock powder (or 1 cube crumbled) (Note 2)","1 garlic clove (, minced)","1 tsp coriander powder (or cumin - I interchange)","400 g / 14 oz chickpeas (1 can) (, drained)","1/2 cup coriander (, finely chopped)","1/2 cup parsley (, finely chopped (or mint))","1 red onion (, chopped)","220 g / 7 oz jar sun dried tomato strips in OIL (Note 3)","120 g / 4 oz rocket / arugula lettuce (, chopped into 5 cm / 2\" pieces)","Zest of 1 large lemon","5 tbsp fresh lemon juice (2 large lemons)","1/2 tsp coarsely ground black pepper","60 g / 2 oz feta (, crumbled)","Salt and pepper (, to taste)"]}]', '[{"description":"Place chickpeas, couscous, vegetable stock powder, coriander and garlic in a large bowl. Pour over hot water, shake to level out couscous (chickpeas should mostly settle on top). Cover with plate or cling wrap, set aside for 5 minutes.","duration":5,"images":[],"step":1},{"description":"Fluff couscous with fork. Cool a bit.","images":[],"step":2},{"description":"Add coriander, parsley, onion, sun dried tomatoes (including all oil), rocket, lemon juice and black pepper. Sprinkle zest across surface. Toss well to combine.","images":[],"step":3},{"description":"Adjust salt and pepper to taste.","images":[],"step":4},{"description":"Transfer to serving bowl, sprinkle with feta. Serve.","images":[],"step":5}]', '["gluten"]', '["low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["dinner-tonight","easter-sides-fresh-light","lentil-recipes","no-cook-food","pasta-salads-and-rice-salads","quick-and-easy","quick-dinner-ideas-15-minute-meals","salad-recipes-main-course","side-dishes","side-salads","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_fe9a0dfa14b6', 'en', 'US', 'Restaurant Style Salsa', 'Recipe video above. Just like what you get at your favourite restaurant and those jars sold alongside corn chips at the grocery store.... but it''s better, healthier and cheaper! The fresh flavour is so, so good. Make it chunkier or smoother, to your taste.', 'https://www.recipetineats.com/tachyon/2014/05/Salsa_1.jpg', 5, 0, 5, 4, '[{"id": "ing_onion", "quantity": {"value": 37.5, "unit": "pack of 1kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_green_chiles", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 0.015, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}]', '[{"ingredients":["1/4 cup chopped onion (white, brown or yellow)","1 tbsp jalapeño pepper (, seeds removed, roughly chopped (fresh best, canned ok))","400g / 14 oz canned crushed tomato (, best quality)","4 oz / 120g canned diced green chiles (Note 1)","1/4 cup (packed) cilantro/coriander (, roughly chopped)","1/2 tbsp+ lime juice","1 clove garlic (, minced)","1/2 tsp sugar","1/2 tsp salt","1/4 tsp black pepper","1/4 teaspoon ground cumin"]}]', '[{"description":"Place onion and jalapeno in the food processor first, then add remaining ingredients (start with 1/2 tbsp lime juice).","images":[],"step":1},{"title":"Blitz to desired consistency","description":"I like mine pretty smooth because you get better flavour out of the onion etc.","images":[],"step":2},{"description":"Taste test with corn chip for salt and lime. Adjust if necessary.","images":[],"step":3},{"description":"Refrigerate 1 hour before serving with corn chips, or other dippers (see in post for suggestions).","images":[],"step":4}]', '[]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Mexican"],"categories":["burritos","dinner-tonight","dip-recipes","fajitas","mexican-recipes","most-popular","nachos-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","taco-recipes","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a7e069f1f36d', 'en', 'US', 'Prawn Cocktail!!!', 'A classic Prawn Cocktail recipe! Juicy prawns (shrimp) tossed in a beautiful Prawn Cocktail Sauce (Rose Marie Sauce - a pink mayonnaise). The key to a good Rose Marie Sauce is a good mayonnaise. Use whole-egg if you can find it . (Note 1) A classic Aussie summer festive starter!', 'https://www.recipetineats.com/tachyon/2016/12/Prawn-Cocktails-900px.jpg', 10, 0, 10, 6, '[{"id": "ing_shrimp", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_shrimp", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.25, "unit": "jar of 400g"}}, {"id": "ing_ketchup", "quantity": {"value": 0.03, "unit": "bottle of 500g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_horseradish", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_dash_of_tabasco_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}]', '[{"ingredients":["1 kg / 2 lb medium fresh cooked or raw prawns with shell and heads on ((yields ~600g once peeled); OR)","600 g / 1.2 lb fresh cooked prawns already peeled","About 3 cup iceberg lettuce, finely sliced","Lemon wedges","Finely chopped parsley (optional)"]},{"ingredients":["2/3 cup / 165 ml mayonnaise (, preferably good quality whole egg mayonnaise (Note 2))","1 tbsp ketchup (or Australian/UK tomato sauce (Note 3))","1 tsp Worcestershire sauce","1 tsp freshly grated horseradish (or sub 1 1/2 tsp jarred OR 3/4 tsp wasabi)","Dash of tabasco sauce (to taste)","Pinch of cayenne pepper (to taste + tiny bit of colour)"],"purpose":"Sauce"}]', '[{"description":"If you are using whole prawns, remove heads and peel them. Leave a few whole for decorative purposes, if you wish. I find that with medium size already cooked prawns, deveining is usually not necessary (it''s hard to do + so small it''s barely noticeably especially with sauce).","images":[],"step":1},{"description":"Mix together Sauce in a small bowl.","images":[],"step":2},{"description":"Toss prawns with Sauce.","images":[],"step":3},{"description":"Place a bit of lettuce in serving dishes. I like to use Martini glasses, but you can use any small serving vessel, or even small lettuce cups.","images":[],"step":4},{"description":"Top with prawns. Serve, garnished with lemon wedges and a sprinkle of parsley, if using.","images":[],"step":5}]', '["egg"]', '["gluten_free","high_protein","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["snack"],"cuisine":[],"categories":["australia-day","easter-recipes","prawns-shrimp","quick-and-easy","quick-dinner-ideas-15-minute-meals","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1778cbc607c7', 'en', 'US', 'Quick Asian Beef Ramen Noodles', 'Recipe video above. A great quick beef ramen noodle recipe that requires very little prep, and it''s a handy one-pan recipe (no need to boil the noodles separately!). It''s a great noodle stir fry that''s family friendly - everybody loves the sweet-savoury flavour of the sauce!The flavour-trick here is to caramelise the beef well, it makes all the difference, so don''t shortcut it. Next time: try the Chicken and vegetable and Mushroom versions!', 'https://www.recipetineats.com/tachyon/2018/12/Asian-Beef-Noodles_4.jpg', 7, 8, 15, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.004, "unit": "pack of 500g"}}, {"id": "ing_oil", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.02, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 1.0, "unit": "bag of 250g"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_mirin", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["2 packets ramen or other instant noodles (, discard seasoning (Note 1))","1 tsp oil","2 tsp sesame oil (or more oil) (Note 2)","2 garlic cloves (, minced)","1/2 onion (, sliced)","200g / 7oz beef mince (ground beef) (Note 3)","1 1/4 cups (315 ml) water, plus more as needed","Big handful bean sprouts"]},{"ingredients":["1 tbsp dark soy sauce (Note 4)","1 tbsp Oyster sauce (or Hoisin, Note 5)","2 tsp Hoisin sauce (or more Oyster sauce)","1 tbsp mirin (Note 6)"],"purpose":"Sauce:"},{"ingredients":["Finely sliced green onion / shallots","Sesame seeds"],"purpose":"Garnishes (optional):"}]', '[{"description":"Mix Sauce.","images":[],"step":1},{"title":"Sauté onion and garlic","description":"Heat oils in a medium skillet over high heat. Add onion and garlic, cook for 1 1/2 minutes until starting to go golden.","images":[],"step":2},{"title":"Cook beef","description":"Add beef and cook, breaking it up as you go, until it changes from pink to light brown.","images":[],"step":3},{"title":"Caramelise beef","description":"Add Sauce and cook for 2 to 3 minutes until well caramelised (see video).","duration":2.5,"images":[],"step":4},{"title":"Add water and noodles","description":"Push beef to the side to make enough space for the noodles. Add water, place noodles in water.","images":[],"step":5},{"title":"Cook ramen","description":"Leave for 45 seconds then turn. Leave for 30 seconds, then untangle the noodles, then toss through the beef.","duration":0.75,"images":[],"step":6},{"description":"Add beansprouts, toss for 1 minute or until sauce reduces to coat the noodles and the noodles are cooked. (Note 7)","duration":1,"images":[],"step":7},{"description":"Serve immediately, garnished with green onions and sesame seeds.","images":[],"step":8}]', '["gluten","sesame","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","beef-mince-recipes","beef-recipes","dinner-tonight","emergency-recipes","main-dishes","noodles","one-pot-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_aa1b0dc92528', 'en', 'US', 'Real Tomato and Basil Bruschetta', 'Real Tomato and Basil Bruschetta, made the proper Italian way. So simple! The key is to use good crusty bread, like ciabatta or sourdough, and ripe, juicy tomatoes.', 'https://www.recipetineats.com/tachyon/2018/12/Bruschetta_2a.jpg', 5, 5, 10, 4, '[{"id": "ing_bread", "quantity": {"value": 0.2, "unit": "loaf"}}, {"id": "ing_olive_oil", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_basil", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["4 slices crusty bread like sourdough or ciabatta (, sliced 1.5cm/ 3/5\" thick (Note 1))","extra virgin olive oil (, for brushing)","1 garlic clove (, halved (unpeeled))"],"purpose":"Bread"},{"ingredients":["4 tomatoes (medium) (, ripe and juicy, at room temperature)","1/4 cup basil leaves (, roughly chopped)","1 1/2 tbsp extra virgin olive oil (best quality you can afford)","1/4 tsp salt (, kosher / cooking salt)","Black pepper"],"purpose":"Tomato and Basil Topping"}]', '[{"description":"Preheat grill/broiler on high (or grill side of BBQ or griddle skillet).","images":[],"step":1},{"title":"Deseed (optional, note 2)","description":"Cut tomatoes in half. Use a measuring teaspoon to scoop out watery seeds (reserve for other use, see post for suggestions) then dice into 1cm / 2/5\" pieces.","images":[],"step":2},{"title":"Toss","description":"Place tomato and remaining Topping ingredients in a bowl and gently toss to combine. Set aside for 5 to 10 minutes for the flavours to meld and the tomatoes to become juicy and soften slightly.","duration":7.5,"images":[],"step":3},{"description":"Brush each side of bread with oil then grill/broil until golden and crusty - about 3 minutes on each side. (Or just use your toaster then brush with oil)","images":[],"step":4},{"description":"Rub one side of the surface of the bread lightly with the garlic.","images":[],"step":5},{"description":"Pile topping onto bread with some of the juices. Drizzle with more extra virgin olive oil and serve immediately.","images":[],"step":6}]', '["gluten"]', '["low_calorie","vegan","vegetarian"]', '{"mealType":["snack"],"cuisine":["Italian"],"categories":["italian-recipes","no-cook-food","quick-and-easy","quick-dinner-ideas-15-minute-meals","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f1bc7139e306', 'en', 'US', 'Chinese Chicken Salad', 'Recipe video above. This one is all about the fabulous Asian Dressing and the slaw-type shape of the ingredients. Don''t skip the crunchy noodles, they totally make this! Alternative Dressing: standby Asian Sesame Dressing (keeps for weeks).', 'https://www.recipetineats.com/tachyon/2015/06/Chinese-Chicken-Salad_0a.jpg', 15, 0, 15, 2, '[{"id": "ing_light_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_grapes", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cabbage", "quantity": {"value": 12.0, "unit": "head"}}, {"id": "ing_red_cabbage", "quantity": {"value": 4.5, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 150.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.5, "unit": "bunch"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["2 tbsp light soy sauce (Note 1)","3 tbsp rice vinegar (aka rice wine vinegar, or use cider vinegar)","1 tbsp sesame oil (toasted)","2 tbsp grapeseed oil (or canola or any other neutral flavored oil)","1 tsp sugar","1 1/2 tsp fresh ginger (, grated or very finely chopped)","1 garlic clove (, minced)","1/2 tsp black pepper"],"purpose":"Asian Dressing"},{"ingredients":["4 cups Chinese cabbage (Nappa Cabbage), finely shredded (Note 2)","1 1/2 cups red cabbage (, finely shredded)","1 cup carrot (, finely julienned (see video))","2 cups chicken (, shredded)","1/2 cup shallots / scallions (, finely sliced on the diagonal)"],"purpose":"Salad"},{"ingredients":["1/2 to 1 cup crunchy noodles (I use Chang''s) (Note 3)","1 - 2 tsp sesame seeds"],"purpose":"Garnishes"}]', '[{"description":"Combine the Dressing ingredients in a jar and shake. Set aside for 10 minutes or so for the flavours to meld.","duration":10,"images":[],"step":1},{"description":"Place the Salad ingredients together in a large bowl along with half the crunchy noodles. Drizzle over dressing then toss. (Note 4)","images":[],"step":2},{"description":"Divide between serving bowls. Top with more crunchy noodles and a good sprinkle of sesame seeds. Serve immediately!","images":[],"step":3}]', '["gluten","sesame","soy"]', '[]', '{"mealType":["lunch"],"cuisine":["Western Chinese"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-recipes","chinese-recipes","dietary","dinner-tonight","low-calorie-recipes","main-dishes","most-popular","no-cook-food","quick-and-easy","quick-dinner-ideas-15-minute-meals","salad-recipes-main-course"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7691a63fade0', 'en', 'US', 'Omelette', 'Recipe video below above. Fluffy omelettes are a master recipe that everyone should know. The key tip is to use a low-ish heat so the omelette doesn’t burn on the underside before the top sets. Feel free to use your filling of choice – suggestions in the notes below.', 'https://www.recipetineats.com/tachyon/2017/09/Omelette-with-Mushrooms_0-2.jpg', 5, 10, 15, 1, '[{"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_cream", "quantity": {"value": 0.12, "unit": "carton of 250ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_cheese", "quantity": {"value": 0.333, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_mushroom", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 tbsp / 15g butter","3 eggs","2 tbsp cream (or 1 ½ tbsp milk) (Note 1)","Salt and pepper","1/3 cup grated cheese (any melting cheese, I usually use cheddar)"],"purpose":"Omelette:"},{"ingredients":["1 tbsp / 15g butter or olive oil","150 g / 5 oz mushrooms (, sliced (about 1 ½ cups))","1 small garlic clove (, minced)","Pinch of fresh thyme leaves and finely chopped parsley (optional)"],"purpose":"Mushroom Filling (optional):"}]', '[{"title":"Mushroom Filling","description":"Melt butter in a medium or small non stick skillet over high heat. Add mushrooms and cook until starting to go golden on the edges – about 1 ½ minutes. Add garlic, salt and pepper, cook until golden – about 1 ½ minutes. Remove from skillet.","images":[],"step":1},{"description":"Whisk eggs, cream, salt and pepper.","images":[],"step":2},{"description":"Cool skillet and lower heat to medium.","images":[],"step":3},{"description":"Add butter, then when it foams, add egg. Immediately give it a few stirs (as though you’re making scrambled eggs) then when the base just starts to set, spread it all out to cover the base (see video).","images":[],"step":4},{"title":"Wait 20","description":"30 seconds, then use a rubber spatula to lift up the edge, tilt pan to make the egg run off the surface under the omelette. Repeat 2 or 3 times around the edges of the omelette.","images":[],"step":5},{"description":"Sprinkle half the omelette with some of the cheese, top with mushrooms, sprinkle with thyme and parsley, top with remaining cheese.","images":[],"step":6},{"description":"Cover with lid and cook for 30 seconds or until the underside is light golden and top is just set – cheese won’t melt.","duration":0.5,"images":[],"step":7},{"description":"Fold omelette in half to cover mushrooms, transfer to serving plate immediately – residual heat will melt cheese.","images":[],"step":8}]', '["egg","milk"]', '["gluten_free","high_protein","keto_friendly","vegetarian"]', '{"mealType":["breakfast"],"cuisine":["Western"],"categories":["breakfast-recipes","dietary","gluten-free-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9fd98e4ade0f', 'en', 'US', 'Pork Stir Fry with Green Beans', 'RECIPE VIDEO ABOVE. A simplified version of the popular Szechuan dish Stir Fried Green Beans with Minced Pork. Same flavour punch but made with everyday ingredients. Has intense flavour so you won''t miss the sauciness of usual stir fries. Mix it up with rice then eaten with a spoon - forget chopsticks! Don’t skip charring the beans, it''s the defining feature of this stir frySpiciness: Mild. Similar - try the Japanese version of this dish, on RecipeTin Japan!', 'https://www.recipetineats.com/tachyon/2018/04/Pork-Stir-Fry-with-Green-Beans_6-1.jpg', 5, 5, 15, 2, '[{"id": "ing_green_beans", "quantity": {"value": 300.0, "unit": "pack"}}, {"id": "ing_pork_mince", "quantity": {"value": 0.22, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.075, "unit": "pack of 100g"}}, {"id": "ing_rice", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_chilli", "quantity": {"value": 0.075, "unit": "pack of 100g"}}]', '[{"ingredients":["300g / 10oz green beans (Note 1)","220g / 7 oz pork mince (Note 2)","1/2 small onion (, finely chopped (about 1/2 cup))","2 garlic cloves (, finely chopped (Note 3))","2 tsp ginger (, finely chopped (Note 3))","2 1/2 tbsp peanut oil (or vegetable or canola)"]},{"ingredients":["1 tbsp dark soy sauce (Note 4)","1 tbsp Chinese cooking wine (shaoxing wine) (Note 5 for subs)","1 tsp white sugar (sub any sugar or faux sugar)","1 1/2 tsp + Chilli Garlic Sauce (Note 6)"],"purpose":"Sauce"},{"ingredients":["Rice of choice","Sliced red chilli"],"purpose":"For serving"}]', '[{"title":"Sauce","description":"Mix Sauce ingredients in a bowl.","images":[],"step":1},{"title":"Trim the stem end of the beans, then chop into 2","description":"2.5cm / 4/5 - 1\" pieces.","images":[],"step":2},{"title":"Char Beans","description":"Heat 1 1/2 tbsp oil in a heavy based skillet over high heat (I use cast iron) until smoking. Add beans, spread out to cover base. Leave for 1 minute. Quick stir, spread out, cook for 30 seconds. Stir, then leave for 30 seconds, then repeat once more (so 2 1/2 minutes in total cook time) until beans are charred but tender crisp (not withered and floppy). Remove into bowl.","duration":1,"images":[],"step":3},{"title":"Sauté aromatics","description":"Turn heat down to medium high, add 1 tbsp oil. Add onion, then garlic and ginger. Cook for 1 minute until edges of onion are golden.","duration":1,"images":[],"step":4},{"title":"Cook pork","description":"Turn heat back up to high. Add pork and cook, breaking it up as you go. Cook for 2 minutes until the pork is cooked through, then add Sauce. Cook for 30 seconds, then add beans and stir for another 30 seconds.","duration":2,"images":[],"step":5},{"description":"Serve over rice. Garnish with slices of large red chilli (it''s mild), entirely optional. To eat, mix the pork into the rice then eat it with a spoon - forget chopsticks for this one! (For a low carb, low cal option, try Cauliflower Rice)","images":[],"step":6}]', '["gluten","peanuts","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian","Japanese"],"categories":["asian-recipes","chinese-recipes","dietary","dinner-tonight","low-calorie-recipes","main-dishes","pork-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_48b8fa0629f1', 'en', 'US', 'Lemon Butter Sauce for Fish', 'Recipe VIDEO above (helpful for pre-post browned butter). A Lemon Butter Sauce with Crispy Pan Fried Fish that would be perfectly at home in a posh restaurant, yet is so quick to make at home! Browning the butter gives the sauce a rich, nutty aroma which pairs beautifully with fresh lemon, as well as thickening the sauce and giving it a gorgeous golden colour.', 'https://www.recipetineats.com/tachyon/2018/04/Fish-with-Lemon-Butter-Sauce.jpg', 5, 10, 15, 2, '[{"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["60 g / 4 tbsp unsalted butter (, cut into pieces)","1 tbsp fresh lemon juice","Salt and finely ground pepper"],"purpose":"Lemon Butter Sauce:"},{"ingredients":["2 x thin white fish fillets (120-150g / 4-5oz each), skinless boneless (I used Bream, Note 1)","Salt and pepper","2 tbsp white flour","2 tbsp oil (I use canola)"],"purpose":"Crispy Pan Fried Fish:"},{"ingredients":["Lemon wedges","Finely chopped parsley, optional"],"purpose":"Serving:"}]', '[{"description":"Lemon Butter Sauce (see video):","images":[],"step":1},{"description":"Place the butter in a light coloured saucepan or small skillet over medium heat.","images":[],"step":2},{"description":"Melt butter then leave on the stove, whisking / stirring very now and then. When the butter turns golden brown and it smells nutty - about 3 minutes, remove from stove immediately and pour into small bowl. (Note 2)","images":[],"step":3},{"description":"Add lemon juice and a pinch of salt and pepper. Stir then taste when it has cooled slightly. Adjust lemon/salt to taste.","images":[],"step":4},{"title":"Set aside","description":"it will stay pourable for 20 - 30 minutes. See Note 3 for storing.","duration":25,"images":[],"step":5},{"description":"Crispy Pan Fried Fish:","images":[],"step":6},{"description":"Pat fish dry using paper towels. Sprinkle with salt & pepper, then flour. Use fingers to spread flour. Turn and repeat. Shake excess flour off well, slapping between hands if necessary.","images":[],"step":7},{"description":"Heat oil in a non stick skillet over high heat. When the oil is shimmering and there are faint wisps of smoke, add fish. Cook for 1 1/2 minutes until golden and crispy on the edges, then turn and cook the other side for 1 1/2 minutes (cook longer if you have thicker fillets).","images":[],"step":8},{"description":"Remove immediately onto serving plates. Drizzle each with about 1 tbsp of Sauce (avoid dark specks settled at the bottom of the bowl), garnish with parsley and serve with lemon on the side. Pictured in post with Kale and Quinoa Salad.","images":[],"step":9}]', '["fish","gluten","milk"]', '["low_calorie"]', '{"mealType":["main_course"],"cuisine":[],"categories":["dietary","dinner-tonight","easter-mains-fish-seafood","fish-recipes","gluten-free-recipes","main-dishes","quick-and-easy","quick-dinner-ideas-15-minute-meals","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bfa4790039a1', 'en', 'US', 'Peanut Sauce for Stir Fries', 'Recipe VIDEO above. A simple, really tasty peanut sauce to use in stir fries and noodles! Tastes like a Satay Peanut Sauce. To use, follow formula below or for full directions, use this Satay Peanut Chicken Stir Fry or this Stir Fried Noodles with Peanut Sauce recipe. Makes enough sauce for 2 - 3 people, a stir fry with rice, or stir fried noodles.', 'https://www.recipetineats.com/tachyon/2018/03/Peanut-Sauce-for-Stir-Fries_5.jpg', 5, 0, 5, 2, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.03, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.025, "unit": "pack of 400g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.06, "unit": "jar of 375g"}}, {"id": "ing_water", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_single_batch_peanut_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_proteins", "quantity": {"value": 190.0, "unit": "unit"}}, {"id": "ing_vegetables_of_choice_as_required_and_grouped_by_cooking_time", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_double_batch_peanut_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_stir_fry_ingredients_above", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_rice_noodles", "quantity": {"value": 0.267, "unit": "pack of 375g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 tbsp fish sauce (Note 1)","1/2 tbsp dark soy sauce (Note 2)","1 1/2 tsp sugar","2 tsp cornflour / cornstarch","1 garlic clove (, minced)","1 tsp grated ginger","1 tsp curry powder (any type)","1 1/2 tbsp / 30 g crunchy peanut butter, regular (Note 1)","3 tbsp water"],"purpose":"Peanut Sauce"},{"ingredients":["1 SINGLE batch Peanut Sauce (above)","2 tbsp oil","1/2 onion, sliced","1 - 2 garlic cloves, finely chopped or minced","180- 200g / 6 - 7 oz protein of choice, sliced","3 - 4 cups vegetables of choice, chopped / sliced as required and grouped by cooking time (Note 4)"],"purpose":"Stir Fry"},{"ingredients":["DOUBLE batch Peanut Sauce (tap Servings & slide)","Stir fry ingredients above","100g / 3.5 oz dried rice noodles OR 180g/6 oz fresh noodles of choice (, prepared per packet)"],"purpose":"Noodle Stir Fry – you will need"},{"ingredients":["Finely chopped coriander / cilantro, crushed peanuts"],"purpose":"Garnish (optional):"}]', '[{"description":"Place all ingredients other than water in a bowl. Mix to combine. Then add water and mix again.","images":[],"step":1},{"description":"Heat oil in a skillet or wok over high heat. Add garlic and 1/2 sliced onion. Cook 1 minute.","images":[],"step":2},{"description":"Add protein of choice or sliced tofu. Cook 2 minutes until just cooked.","images":[],"step":3},{"description":"Add vegetables in order of time to cook, starting with the veggies that take the longer. Cook briefly until just cooked but still crisp.","images":[],"step":4},{"description":"Add delicate veggies (eg bean sprouts, spinach and other leafy greens) and Sauce. Toss until Sauce thickens (add extra water if needed).","images":[],"step":5},{"description":"Garnish with peanuts and coriander / cilantro, if using. Serve over rice - or for a low carb, low cal option, try Cauliflower Rice!","images":[],"step":6},{"description":"Follow Stir Fry directions. Add NOODLES with the Sauce in step 4.","images":[],"step":7},{"title":"Toss for 1","description":"2 minutes until Sauce thickens and coats noodles. Remove from heat, garnish and serve immediately!","duration":1.5,"images":[],"step":8}]', '["fish","gluten","peanuts","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","asian-takeout","chinese-recipes","dinner-tonight","main-dishes","quick-and-easy","quick-dinner-ideas-15-minute-meals","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_01a94b93797e', 'en', 'US', 'Crispy Parmesan Crusted Chicken', 'Recipe video above. This ultra crispy Parmesan Crusted Chicken is 5 ingredient, 10 minute magic that happens to be gluten free. The idea with this recipe is that shredded parmesan melts, tuns golden and adheres to the chicken, forming a crust. Parmesan has such an intense flavour that you don''t need any other seasonings in this. It tastes like schnitzel, but the coating flavour is far stronger and crunchier (but no carbs!) but is not as thick as a traditional breadcrumb coating. Serve it with cauliflower mash with browned butter for the ultimate low-carb meal!', 'https://www.recipetineats.com/tachyon/2018/01/Parmesan-Crusted-Chicken_1.jpg', 7, 8, 15, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.625, "unit": "pack of 200g"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}]', '[{"ingredients":["500 g / 1 lb chicken breast (2 pieces) ( (Note 1))","1 egg","1 garlic clove (, minced (optional))","Salt and pepper","125 g / 4 oz / 1 1/4 cups shredded parmesan (Note 2)","2 tbsp butter (or more oil)","1 tbsp olive oil"]}]', '[{"description":"Cut each breast in half horizontally to make 4 steaks. If they are much thicker than 1.75 cm / 3/4\" thick (at the thickest point), pound a bit.","images":[],"step":1},{"description":"Place egg, garlic, pinch of salt and pepper in a bowl. Whisk with fork.","images":[],"step":2},{"description":"Place parmesan in a shallow bowl.","images":[],"step":3},{"description":"Dredge chicken in egg, then place in parmesan CUT SIDE DOWN (Note 3). Press, then turn. Coat with extra parmesan, press. Shake off excess. Repeat with remaining chicken.","images":[],"step":4},{"description":"Melt butter and heat oil in a large skillet over high heat.","images":[],"step":5},{"description":"Place chicken in non-stick skillet (or well seasoned cast iron skillet). DO NOT MOVE chicken otherwise the cheese will slide off surface before it adheres! It adheres once it turns crispy.","images":[],"step":6},{"description":"Press down lightly with spatula. Lift a corner to take a peek and turn with tongs when it''s deep golden brown (3 minutes for me).","images":[],"step":7},{"description":"Cook the other side for 3 minutes or until also deep golden brown and crispy (again, do not move until golden). Lightly press down with spatula. Don''t cook longer than 6 minutes in total - dries out the chicken.","duration":3,"images":[],"step":8},{"description":"Serve immediately! I served mine with lemon slices, Cauliflower Mash and a Fennel Slaw with Yoghurt Dressing (Note 5).","images":[],"step":9}]', '["egg","milk"]', '["gluten_free","low_calorie"]', '{"mealType":["main_course"],"cuisine":[],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a9d06760637c', 'en', 'US', 'LEMON HONEY GLAZED SALMON', 'A classic example showcasing how a few simple ingredients can make something truly special – fast! The Seasoning not only adds flavour to the salmon, but also creates a crust that the sauce clings to. The sweetness is balance out by the tartness from lemon.Fellow Australians – make sure your salmon is HUON Salmon!! Just ask your fish monger, they will know. It’s the freshest in Australia (first to market) and it’s ethically farmed. Recipe VIDEO below.', 'https://www.recipetineats.com/tachyon/2017/10/Lemon-Honey-Glazed-Salmon-4.jpg', 5, 8, 13, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_honey", "quantity": {"value": 2.0, "unit": "jar of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.005, "unit": "jar of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}]', '[{"ingredients":["4 salmon fillets (, 180g/6oz each, skinless and boneless)","1 tsp olive oil","50 g / 3.5 tbsp butter (, salted)","1 large garlic clove (, finely chopped)","2 ½ tbsp honey","2 tbsp lemon juice (, fresh)"]},{"ingredients":["3 tbsp flour","1 tsp paprika","½ tsp garlic powder","½ tsp mustard powder (not critical)","1/2 tsp salt","½ tsp black pepper"],"purpose":"Seasoning:"},{"ingredients":["Finely chopped parsley or chives","Lemon slices"],"purpose":"Garnishes (optional):"}]', '[{"description":"Place the Seasoning ingredients in a small dish and mix.","images":[],"step":1},{"description":"Coat salmon in the Seasoning, shaking off excess well.","images":[],"step":2},{"description":"Place oil and about 1 tsp of the butter in a large non stick skillet over medium high heat. Once the butter is melted, add the salmon.","images":[],"step":3},{"description":"Cook salmon for 3 minutes, or until it’s a beautiful bronzed golden brown. Turn and cook for 1 minute.","duration":3,"images":[],"step":4},{"description":"Add remaining butter, garlic and honey. Swirl the mixture around the pan as the butter melts.","images":[],"step":5},{"title":"Simmer for 1 minute","description":"the honey butter mixture will start to bubble like caramel and turn golden. Add lemon juice, shake pan to disperse. Taste sauce – adjust salt, pepper and lemon to taste.","duration":1,"images":[],"step":6},{"description":"Turn salmon over to coat in the sauce, then remove from heat immediately. Place salmon on plates and drizzle over sauce. Garnish with parsley and fresh lemon, if desired","images":[],"step":7}]', '["fish","gluten","milk","mustard"]', '[]', '{"mealType":["main_course"],"cuisine":[],"categories":["dietary","dinner-tonight","easter-mains-fish-seafood","fish-recipes","gluten-free-recipes","main-dishes","quick-and-easy","quick-dinner-ideas-15-minute-meals","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_69453b7ce927', 'en', 'US', 'Chicken Stir Fry with Rice Noodles', 'Recipe video above. A terrific fridge and pantry forage meal, made with your choice of dried noodles, a simple but tasty stir fry sauce and whatever veggies you can scrape together. This is loaded with veggies and light on the noodles, and if you cook it for more than 5 minutes, it''s overcooked!! This is a super quick midweek stir fry that is really tasty.', 'https://www.recipetineats.com/tachyon/2017/06/Chicken-Stir-Fry-with-Rice-Noodles-4.jpg', 10, 5, 15, 2, '[{"id": "ing_chicken_breast", "quantity": {"value": 150.0, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.013, "unit": "pack of 400g"}}, {"id": "ing_oil", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.045, "unit": "bottle of 500ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_rice_noodles", "quantity": {"value": 0.267, "unit": "pack of 375g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_stems_choy_sum", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_capsicum", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_mushroom", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["150 - 180 g/ 5 - 6 oz chicken breast (, cut into thin strips)","1 tsp cornflour / cornstarch (optional)","1 tsp oil (peanut, vegetable, canola) (optional)"],"purpose":"Chicken (Note 1):"},{"ingredients":["2 tbsp oyster sauce (or sub with Hoisin)","1 tbsp dark soy sauce (Note 2)","1/2 tsp each sesame oil, sugar (optional)","1 1/2 tbsp Chinese cooking wine (Shoaxing wine) OR Mirin (Note 3)","1/4 tsp white pepper (or black pepper)","3 tbsp water"],"purpose":"Sauce (or use my Homemade Stir Fry Sauce, step 2):"},{"ingredients":["100 g / 3.5 oz dried rice noodles (Note 4)","1 tbsp oil","1 garlic clove (, finely chopped (Note 5))","1 small onion (, sliced (white, brown, yellow))","1/2 bunch choy sum or other Asian greens (, stems separated from leaves (Note 6))","1/2 red capsicum / bell pepper (, sliced)","1 carrot (, peeled, cut in half lengthwise and sliced on the diagonal)","5 - 7 mushrooms (, sliced)","Sesame seeds and finely sliced green onions/scallions (, optional)"],"purpose":"Stir Fry:"}]', '[{"description":"Mix chicken, cornstarch and oil in a bowl.","images":[],"step":1},{"description":"Mix Sauce ingredients in a bowl. OR use 3 tbsp Homemade Stir Fry Sauce + 6 tbsp water.","images":[],"step":2},{"description":"Just before cooking, soak noodles in hot water per packet directions, then drain. (Note 7)","images":[],"step":3},{"description":"Heat oil in a wok or large skillet over high heat.","images":[],"step":4},{"description":"Add garlic and onion, cook for 30 seconds.","duration":0.5,"images":[],"step":5},{"description":"Add chicken, cook for 1 minute until it changes colour from pink to white.","duration":1,"images":[],"step":6},{"description":"Add carrot, Choy Sum stems and capsicum. Cook for 1 minute.","duration":1,"images":[],"step":7},{"description":"Add mushrooms, cook for 30 seconds.","duration":0.5,"images":[],"step":8},{"description":"Add noodles, Choy Sum leaves and Sauce. Toss for 1 minute until leaves have wilted and Sauce has evaporated. Don''t toss for more then 1 1/2 minutes - noodles may break.","duration":1,"images":[],"step":9},{"description":"Garnish with sesame seeds and green onions then serve immediately.","images":[],"step":10}]', '["gluten","peanuts","sesame","soy"]', '[]', '{"mealType":["main_course"],"cuisine":[],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","chinese-recipes","dinner-tonight","main-dishes","noodles","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b0b2c3e0f4be', 'en', 'US', 'Bacon Pasta with tomato pasta sauce', 'Recipe video above. You''re just 15 minutes away from this pasta with golden crispy bacon in a garlic tomato pasta sauce! Scale recipe by hovering cursor over Servings (see Note 2).', 'https://www.recipetineats.com/tachyon/2017/05/Bacon-Tomato-Pasta-3.jpg', 5, 10, 15, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.32, "unit": "pack of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_bacon", "quantity": {"value": 150.0, "unit": "pack of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["160 g / 5 oz spaghetti or other long strand pasta of choice","1 tsp olive oil (or butter)","150 - 180 g / 5 - 6 oz bacon (, diced)","1 garlic clove (, minced)","1/2 onion (, finely diced (brown, white, yellow))","400 g / 14 oz canned crushed tomato","Salt and pepper","Pinch of sugar (, if needed (Note 1))","Extra virgin olive oil","Finely chopped parsley"]}]', '[{"description":"Have the ingredients lined up and ready to start cooking at the same time.","images":[],"step":1},{"description":"Bring a large pot of water to the bowl. Add a pinch of salt. Cook pasta according to packet but MINUS 2 minutes.","images":[],"step":2},{"description":"Meanwhile, heat oil in a skillet over high heat. Add bacon and cook for 1 minute, then add garlic and onion and cook for 3 minutes or until onion is translucent and bacon is golden. Drain excess fat if desired.","duration":1,"images":[],"step":3},{"description":"Scoop out a mug of pasta cooking water, then pour about 1/2 cup into the skillet. Bring to simmer and stir, scraping the skillet to dissolve in all the golden bits stuck on the pan into the liquid.","images":[],"step":4},{"description":"Add tomato, bring to simmer and cook for 2 minutes, then turn down to medium high.","duration":2,"images":[],"step":5},{"description":"Drain pasta, or if you timed it right, use tongs to transfer it straight from the pot into the skillet.","images":[],"step":6},{"description":"Toss gently using two wooden spoons for 2 minutes, or until the sauce is no longer sitting in the skillet, it''s all on the pasta (see video). If it gets too thick, just add an extra splash of the pasta cooking water.","duration":2,"images":[],"step":7},{"description":"Season with salt and pepper (remember bacon is salty!).","images":[],"step":8},{"description":"Serve immediately, garnished with parmesan, parsley and final drizzle of olive oil if desired.","images":[],"step":9}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["dinner-tonight","italian-recipes","main-dishes","pasta-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8cf02d0a1cc8', 'en', 'US', 'Honey Garlic Salmon (5 Ingredients, 15 Minutes)', 'Recipe video above. A terrific way to serve salmon that is just sooooo crazy quick and easy and soooo delicious!', 'https://www.recipetineats.com/tachyon/2015/03/Honey-Garlic-Salmon.jpg', 5, 10, 15, 2, '[{"id": "ing_honey", "quantity": {"value": 0.12, "unit": "jar of 500g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_fish_fillets", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["4 tbsp honey","2 tbsp soy sauce (all purpose or light soy sauce)","1 tbsp white vinegar (or sub with any other vinegar except balsamic)","1 large garlic clove (or 2 small) (, minced)"],"purpose":"Sauce"},{"ingredients":["2 salmon or trout fillets, skinless (6oz / 200g each)","Olive oil","Salt and pepper"],"purpose":"Salmon"},{"ingredients":["Sesame seeds","Finely sliced chives or shallots/scallions"],"purpose":"Optional Garnishes"}]', '[{"description":"Take salmon out of the fridge 20 minutes before cooking. Pat salmon skin dry with a paper towel and sprinkle with salt and pepper.","images":[],"step":1},{"description":"Whisk together the Sauce ingredients in a small bowl.","images":[],"step":2},{"description":"Drizzle oil in a non stick fry pan and heat over medium high heat (or just under, if your stove runs hot). Place salmon in the pan, and cook the first side for 3 - 4 minutes until golden. Turn, then cook the other side for 2 - 3 minutes or until golden.","duration":3.5,"images":[],"step":3},{"description":"Pour Sauce over salmon. Cook for 1 minute or until it starts to thicken slightly. Check the side of the salmon to tell how cooked through the middle is - I like mine medium rare inside. (Note 1). If Sauce thickens too much before your salmon is cooked to your taste, just add water 1 tbsp at a time.","duration":1,"images":[],"step":4},{"description":"Remove onto serving plates.","images":[],"step":5},{"description":"Serve salmon drizzled with Sauce, sprinkled with sesame seeds and chives/shallots, if desired.","images":[],"step":6}]', '["fish","gluten","sesame","soy"]', '[]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["asian-recipes","australia-day","dietary","dinner-tonight","easter-mains-fish-seafood","fish-recipes","gluten-free-recipes","grilling-ideas-and-recipes","main-dishes","most-popular","quick-and-easy","quick-dinner-ideas-15-minute-meals","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5b92238318f5', 'en', 'US', 'One Pot Chicken Alfredo Pasta', 'Recipe video above. Pasta in a silky, creamy sauce with tender, juicy chicken, all made in ONE POT! (Well, pan:) )', 'https://www.recipetineats.com/tachyon/2017/03/One-Pot-Chicken-Alfredo-2.jpg', 2, 13, 15, 3, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 0.375, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["200 g / 7oz chicken breast, cut in half horizontally","Salt and pepper","1 tbsp olive oil","250 g / 8 oz fettuccine","2 cups milk, any fat %","1 1/2 cups chicken stock / broth","1 large garlic clove, minced","1/2 cup thickened / heavy cream (Note 1)","3/4 cup freshly grated parmesan (Note 2)","Parsley, for garnish"]}]', '[{"description":"Sprinkle both sides of the chicken with salt and pepper.","images":[],"step":1},{"description":"Use a skillet large enough to fit the pasta.","images":[],"step":2},{"description":"Heat oil over medium high heat. Add chicken and cook for 2 minutes on each side until golden and cooked through. Remove onto plate and rest for 5 minutes, then slice while pasta is cooking.","duration":2,"images":[],"step":3},{"description":"Add milk, chicken broth and garlic. Bring to simmer then add pasta.","images":[],"step":4},{"description":"Move pasta around every 30 seconds or so until it is softened (around 3 minutes) so it doesn''t stick. Once pasta is softened, reduce heat to medium and stir every couple of minutes.","images":[],"step":5},{"title":"At about 9","description":"10 minutes, the pasta should be almost cooked but there should still be liquid covering the base of the skillet. Add cream and parmesan and mix.","images":[],"step":6},{"description":"Simmer, stirring occasionally, for ~2 minutes, until sauce is thickened and pasta is cooked. If you cook it too long and the sauce goes gluggy, add a splash of hot tap water - will go back to silky with a few tosses.","images":[],"step":7},{"description":"Adjust salt and pepper to taste and serve immediately, garnished with freshly grated parmesan and parsley!","images":[],"step":8}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","italian-recipes","main-dishes","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bbe82b35b97c', 'en', 'US', 'Asian Steak', 'An incredible Asian Steak recipe, with a simple yet stunning sauce inspired by the great Tetsuya, a highly regarded Japanese-Australian chef. Make this with small pieces of high quality beef steak! See notes for my tips on FREEZING rice - so handy to have on standby for quick meals!', 'https://www.recipetineats.com/tachyon/2017/03/Asian-Steak-3.jpg', 5, 10, 15, 2, '[{"id": "ing_beef_steak", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_mirin", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_cooking_sake", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_butter", "quantity": {"value": 45.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["2 beef tenderloin steaks, around 150g/5oz each (Note 1)","1 tbsp vegetable oil (or other neutral cooking oil)"]},{"ingredients":["1 tbsp soy sauce, all purpose (Note 2)","2 tbsp Mirin (Note 3)","3 tbsp cooking sake (Note 3)","45g/3tbsp unsalted butter","1 small garlic clove, minced","1/2 tsp ginger, minced (can exclude)","3 tsp shallots/scallions (green part) or chives, finely chopped"],"purpose":"Sauce"}]', '[{"description":"Take the steak out of the fridge 20 minutes prior to cooking (or 10 minutes if it''s a stinking hot summer day).","images":[],"step":1},{"description":"Combine soy sauce, Mirin and sake in a small bowl.","images":[],"step":2},{"description":"Heat oil in a skillet over medium high heat until smoking. Add steak and cook to your liking. Mine were 150g/5oz each and 3cm/1.25\" thick and I cooked it 3 minutes on the 1st side and 2 minutes on the second side for medium rare.","images":[],"step":3},{"description":"Transfer steak onto a plate and cover loosely with foil. Rest for 5 minutes.","duration":5,"images":[],"step":4},{"description":"Let the skillet cool down a bit then return to the stove over medium high heat. Add Sauce and bring to simmer, then add butter. When the butter melts and is incorporated into the sauce, immediately remove it from the stove.","images":[],"step":5},{"description":"Stir through garlic, ginger and 2 tsp of shallots (reserve rest for garnish), the sauce should be slightly thickened (if not, keep stirring, thickens more as it cools).","images":[],"step":6},{"description":"Place steak on plates and spoon over sauce. I served the steaks with finely shredded cabbage without dressing (very typical Japanese side) and white rice, plus some edamame on the side.","images":[],"step":7}]', '["gluten","milk","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","beef-recipes","modern-asian","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a138b4e67631', 'en', 'US', 'Beef Soba Noodle Bowl with Green Beans', 'A fusion Japanese soba noodle dish with an amazing dressing that matches perfectly with the juicy steak slices and for slurping up the soba noodles. Fantastic quick meal for hot summer nights!', 'https://www.recipetineats.com/tachyon/2017/03/Beef-Bean-and-Soba-Bowls.jpg', 5, 10, 15, 2, '[{"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_oil", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_mirin", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_beef_steak", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_soba", "quantity": {"value": 170.1, "unit": "pack"}}, {"id": "ing_green_beans_trimmed", "quantity": {"value": 170.1, "unit": "pack"}}, {"id": "ing_green_onion", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_green_onion", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["1 1/2 tbsp soy sauce, light or ordinary (Note 1)","2 1/2 tbsp peanut oil","3 tbsp rice vinegar (Note 2)","1 tbsp mirin (Note 3)","2 tsp brown sugar","2 tsp ginger, minced","1 clove garlic, minced"],"purpose":"Dressing"},{"ingredients":["200g/7 oz rump or sirloin beef steak, excess fat trimmed (Note 4)","1 tsp vegetable oil","6oz/180g soba (Note 5)","6oz/200g green beans, trimmed","1 scallion/shallot, finely sliced","1 tbsp crispy Asian Shallots (Note 6)"],"purpose":"Steak"}]', '[{"description":"Take the steak out of the fridge 30 minutes prior to cooking (or 15 minutes if it''s a stinking hot summer day).","images":[],"step":1},{"description":"Combine dressing ingredients in a jar and shake.","images":[],"step":2},{"description":"Heat the oil in a skillet over high heat until smoking, then cook the steak to your liking. I like mine medium rare - perfect for absorbing the flavours of the delicious dressing - so I cook this rump steak for 2 minutes on the first side and 1 minute 45 seconds on the second side.","duration":2,"images":[],"step":3},{"description":"Transfer to a plate and loosely cover with foil. Rest for 5 minutes, then slice into fairly thin slices against the grain (i.e. find the direction of the fibres then cut at a 90 degree angle straight through them).","duration":5,"images":[],"step":4},{"description":"Meanwhile, bring a pot of water to boil. Cook the soba according to packet instructions (usually 5 minutes). For the last 1 minute of cooking, add the green beans.","images":[],"step":5},{"description":"Drain the noodles and beans and rinse under cold water to stop them from cooking further and to cool the noodles. Roughly separate beans from noodles.","images":[],"step":6},{"description":"To serve, divide the noodles between 2 bowls, top with the beans then the steak slices. Drizzle with the dressing (over the steak and noodles), then garnish with shallot slices and Crispy Asian Shallots.","images":[],"step":7}]', '["gluten","peanuts","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","beef-recipes","dinner-tonight","main-dishes","modern-asian","noodles","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5674b29e5a30', 'en', 'US', 'Spicy Chilli Prawn Pasta (Shrimp)', 'Pasta tossed with juicy prawns and a rich spicy tomato sauce! Super quick for midweek, the secret ingredients in this are the anchovies (it dissolves!) and parmesan which provides that extra umami that you get from simmering a sauce made with prawn shells for hours and hours. See note 1 for more commentary and see video below recipe.', 'https://www.recipetineats.com/tachyon/2017/01/Spicy-Prawn-Pasta-6.jpg', 5, 10, 15, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.36, "unit": "pack of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_shrimp", "quantity": {"value": 150.0, "unit": "kg"}}, {"id": "ing_anchovies", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_wine", "quantity": {"value": 0.083, "unit": "bottle of 750ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_tomato", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_parmesan", "quantity": {"value": 0.05, "unit": "pack of 200g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}]', '[{"ingredients":["180 g / 6 oz fettuccine or other pasta or choice","1 1/2 tbsp olive oil","150 - 180 g / 5 - 6 oz medium prawns/shrimp (, peeled and deveined)","2 anchovies (, whole (or 1/2 tsp anchovy paste))","1 garlic clove (, minced)","1/4 cup white wine","1 tsp+ chilli fakes / red pepper flakes","1 cup / 250 ml tomato passata (Note 2)","2 tsp finely grated parmesan","1/2 lemon","1/4 cup finely chopped fresh parsley (, plus more to serve)"]}]', '[{"title":"Get all the ingredients out and ready to go","description":"this recipe moves fast!","images":[],"step":1},{"description":"Bring a large pot of water to the boil. Add a big pinch of salt and the pasta. Cook for the time per the packet MINUS 1 minute. SCOOP OUT a mugful of pasta cooking water before draining pasta (or transfer it straight from pot into sauce, if you time it right).","images":[],"step":2},{"description":"Heat oil in a skillet over high heat. Add prawns and cook for 30 seconds, until surface just changes from translucent to opaque.","duration":0.5,"images":[],"step":3},{"description":"Add red pepper flakes and anchovies. Stir briefly, then add wine and garlic.","images":[],"step":4},{"description":"Cook for 30 seconds until wine is mostly evaporated.","duration":0.5,"images":[],"step":5},{"description":"Add tomato passata, squeeze of lemon juice, parmesan, salt and pepper. Bring to simmer, turn heat down to medium and cook sauce for 1 minute, stirring frequently (don''t cook for long otherwise will overcook prawns).","duration":1,"images":[],"step":6},{"description":"Add pasta, about 1/2 cup of pasta cooking water and parsley. Toss gently for 1 minute (or gently stir with wooden spoon or tongs) until sauce re-thickens and it coats the pasta.","duration":1,"images":[],"step":7},{"description":"Adjust salt, pepper and spiciness to taste. Serve immediately with more parsley.","images":[],"step":8}]', '["fish","gluten","milk","shellfish"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dinner-tonight","italian-recipes","main-dishes","pasta-recipes","prawns-shrimp","quick-and-easy","quick-dinner-ideas-15-minute-meals","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_35f1ebeeecf3', 'en', 'US', 'Chinese Pork with Noodles ("Chinese Bolognese")', 'Don''t be put off by the Asian speciality sauces, this is one of those recipes that still works GREAT using the substitutions. Some people may even prefer it made with the subs! . The proper name for this stir fried pork with noodles is "Zha Jiang Mian" noodles and is also affectionally referred to as "Chinese Bolognese". Minced / ground pork is stir fried with tasty classic Chinese flavours that are savoury with a touch of spice and sweet. Recipe video is below recipe.', 'https://www.recipetineats.com/tachyon/2016/12/Chinese-Pork-and-Noodles-7.jpg', 10, 10, 20, 3, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 700.0, "unit": "pack of 500g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_vinegar", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_chilli", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_chinese_sweet_bean_sauce", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_pork", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_chilli", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["700 - 800 g / 1.4 - 1.6 lb white noodles (flour noodles), fresh (Note 1)","2 tsp vegetable oil*","2 tsp Chinese black vinegar (Chinkiang vinegar)* (Note 2)"],"purpose":"Noodles"},{"ingredients":["1/3 cup chicken stock / broth","1 tbsp Chilli Bean Sauce (Note 3)","1 tbsp Chinese Sweet Bean Sauce (Note 4)","1 tbsp dark soy sauce (Note 5)","2 tsp Chinese black vinegar (Chinkiang vinegar)* (Note 2)","1 tsp sugar (white or brown)"],"purpose":"Sauce"},{"ingredients":["1 tbsp vegetable oil","2 garlic cloves (, minced)","1 1/2 tsp ginger (, minced or finely chopped)","1/2 onion (, finely chopped (white, brown or yellow))","400 g / 14 oz minced pork (ground pork)"],"purpose":"Stir Fry"},{"ingredients":["2 cucumbers (, cut into batons (deseed if you can be bothered, I don''t!))","Chinese chilli sauce (Note 6)","Coriander / cilantro leaves"],"purpose":"To Serve"}]', '[{"description":"Mix Sauce ingredients together.","images":[],"step":1},{"description":"Prepare noodles according to packet directions. If it says to soak the noodles, you can do that while cooking the stir fry.","images":[],"step":2},{"title":"Optional","description":"Just before serving, toss the noodles with oil and vinegar.*","images":[],"step":3},{"description":"Heat oil in a wok or skillet over medium high heat. Add onions and cook for 1 minute. Add garlic and ginger and cook for 1 minute or until onion is translucent.","duration":1,"images":[],"step":4},{"description":"Add pork and cook, breaking it up as you go, until browned.","images":[],"step":5},{"title":"Add sauce and cook for 3","description":"5 minutes, or until most of the sauce has reduced.","duration":4,"images":[],"step":6},{"description":"Divide noodles between bowls. Top with pork, coriander and fresh cucumbers on the side.","images":[],"step":7},{"description":"To eat, mix up the noodles and pork. I use chopsticks and a spoon - so it''s easier to get the pork and noodles in one mouthful. Don''t hold back on the chilli paste! It goes great with this dish!","images":[],"step":8}]', '["gluten","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","chinese-recipes","dinner-tonight","main-dishes","noodles","pork-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f61e271fd51a', 'en', 'US', 'Spicy Thai Chicken Stir Fry', 'The Thai stir fry sauce used in this recipe is a fantastic versatile stir fry sauce! It''s similar to many well known Thai stir fries like Pad See Ew, Thai Chilli Basil Chicken and Drunken Noodles (Pad Kee Mao). Make this using ground/mince chicken, pork or turkey. See notes for how to use this sauce for other stir fries. Ensure all ingredients are ready to toss into the wok before you start cooking because once you start, it cooks fast!', 'https://www.recipetineats.com/tachyon/2016/11/Spicy-Thai-Chicken-Stir-Fry_4.jpg', 7, 8, 15, 3, '[{"id": "ing_light_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_chilli", "quantity": {"value": 3.0, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2 tsp light soy sauce (Note 1)","1 tsp dark soy sauce (Note 1)","2 tsp fish sauce","1 tbsp oyster sauce","1 tsp sugar"],"purpose":"Sauce"},{"ingredients":["2 tbsp cooking oil (I use peanut or vegetable oil)","3 Thai or birds eye chillis or other small hot red chilli (, finely chopped (Note 2))","4 garlic cloves (, finely chopped)","1 small onion (, halved and sliced (brown, white or yellow))","500 g / 1 lb ground / mince chicken","3 shallot / scallions stems (, chopped into slices)","1 cup coriander/cilantro leaves (loosely packed)"],"purpose":"Stir Fry"},{"ingredients":["Steamed jasmine rice"],"purpose":"Serving"}]', '[{"description":"Mix Sauce ingredients in a small bowl.","images":[],"step":1},{"description":"Heat oil in a wok or heavy based skillet over high heat. Add garlic and chilli - cook for 15 seconds.","duration":0.25,"images":[],"step":2},{"description":"Add onion and cook for 45 seconds.","duration":0.75,"images":[],"step":3},{"description":"Add chicken and cook, breaking it up as you go. When it changes from pink to white, add Sauce. Cook until the liquid mostly disappears - about 2 minutes.","images":[],"step":4},{"description":"Stir through shallots. Then stir through coriander and immediately take off the heat.","images":[],"step":5},{"title":"Serve immediately with jasmine rice or other rice","description":"or for a low carb, low cal option, try Cauliflower Rice! Add slices of cucumber and tomato wedges (very authentic Thai!). Garnish with extra chilli and coriander if desired.","images":[],"step":6}]', '["fish","gluten","peanuts","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["asian-recipes","chicken-breast-recipes","chicken-mince-recipes","chicken-recipes","cuisines","dinner-tonight","main-dishes","quick-and-easy","quick-dinner-ideas-15-minute-meals","stir-fries","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bb375db0f653', 'en', 'US', 'Chinese Chicken and Corn Soup', 'Recipe video above. This is a very quick to make soup that is one of all my all time favourites, it''s thick, creamy (but with no cream!), sweet from the corn, hearty and soul warming. I''ve been known to add greens to it, my favourite being chinese broccoli and broccolini, to make it a complete meal. Though this recipe is made with chicken, it is easily made vegetarian/vegan by omitting the chicken. Watch the cooking videoto see how this is made without using a chopping board!', 'https://www.recipetineats.com/tachyon/2014/06/Chinese-Chicken-Corn-Soup-2.jpg', 5, 5, 10, 2, '[{"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.013, "unit": "pack of 400g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.9, "unit": "bunch"}}]', '[{"ingredients":["2 cups (500ml) chicken or vegetable broth/stock","1 can (16oz/420g) creamed corn","1 tsp soy sauce (all purpose or light)","1 tbsp Chinese cooking wine (OR Mirin or Dry Sherry (can omit))","1 tsp ginger (, minced or finely chopped)","1 garlic clove (, minced or finely chopped)","1 tsp cornflour / cornstarch (, mixed with a splash of cold water)","1 egg (, whisked)","1 cup shredded cooked chicken","Salt and white pepper (, to taste)","3 tbsp sliced scallions / shallots (optional)"]}]', '[{"description":"Place broth, creamed corn, soy sauce, Chinese cooking wine, ginger, garlic and cornflour / water mixture in a saucepan over high heat.","images":[],"step":1},{"description":"Bring to boil, then turn down the heat to medium and stir occasionally. Cook for 5 minutes or until slightly thickened.","duration":5,"images":[],"step":2},{"description":"Adjust seasoning with salt, turn off heat, and slowly whisk in the egg so it cooks in \"ribbons\" throughout the soup. This also thickens the soup.","images":[],"step":3},{"description":"Add the chicken, season with white pepper, and serve, garnished with scallions.","images":[],"step":4}]', '["egg","gluten","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","asian-soups","asian-takeout","chicken-breast-recipes","chicken-recipes","chinese-recipes","dinner-tonight","emergency-recipes","main-dishes","most-popular","quick-and-easy","quick-dinner-ideas-15-minute-meals","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d1e50df8d1cc', 'en', 'US', 'Lemon Pepper Chicken', 'A homemade version of lemon pepper chicken made without store-bought lemon pepper seasoning. It tastes incredible - fresh, fragrant with lovely pops of heat from the pepper. No marinating time required. Great for pork and seafood too! RECIPE VIDEO BELOW.', 'https://www.recipetineats.com/tachyon/2016/10/Lemon-Pepper-Chicken_5.jpg', 10, 5, 15, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 4.0, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.25, "unit": "jar of 50g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["2 chicken breasts (~250 - 300g / 8 - 10oz each)","2 lemons (Note 1)","1 tbsp olive oil","3 tbsp flour","1/2 - 3/4 tsp salt","2 1/2 tsp cracked black pepper (adjust to taste) (Note 2)","1/2 tsp garlic powder (or sub with onion powder) (Note 3)"]},{"ingredients":["1 tbsp olive oil","Fresh parsley (, for garnish)"],"purpose":"Cooking"}]', '[{"description":"Cut the chicken in half horizontally to make 2 steaks. Optional: pound to make them even thickness around 1cm / 2/5\" thick (I do this).","images":[],"step":1},{"title":"Zest the lemons to make 1 1/2","description":"2 tbsp lemon zest. Avoid grating too much of the white part - it''s bitter.","images":[],"step":2},{"description":"Place zest into bowl with 1 tbsp olive oil and mix to combine. Add chicken and use your hands to slather oil mixture onto chicken.","images":[],"step":3},{"description":"Mix flour, salt, pepper and garlic powder in a shallow bowl.","images":[],"step":4},{"description":"Dip chicken into flour mixture, shaking to remove excess.","images":[],"step":5},{"description":"Heat oil in a skillet over medium high heat. Cook chicken for 2 minutes on each side, or until golden.","duration":2,"images":[],"step":6},{"title":"Optional","description":"Slice zested lemon and cook the slices, like pictured.","images":[],"step":7},{"description":"Serve chicken, garnished with fresh parsley if using.","images":[],"step":8}]', '["gluten"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","low-calorie-recipes","main-dishes","most-popular","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_33ef46acfc29', 'en', 'US', 'Creamy Dill Sauce with Salmon or Trout', 'A fantastic quick meal! Dill Sauce is refreshing, rather than heavy as many "creamy" sauces can be, because it is made with sour cream. The slight acidity is a great pairing with salmon or trout which are quite rich and oily. I made this with trout.', 'https://www.recipetineats.com/tachyon/2016/09/Creamy-Dill-Sauce-with-Salmon_5.jpg', 10, 5, 15, 4, '[{"id": "ing_sour_cream", "quantity": {"value": 0.45, "unit": "tub of 250g"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_dill", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_milk", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["3/4 cup sour cream (1)","2 tsp Dijon or hot English mustard (2)","1/2 tsp garlic powder or 1 small garlic clove (, minced)","2 1/2 tbsp fresh dill (, finely chopped)","1 tsp lemon zest","1 - 2 tbsp lemon juice","2 tbsp milk (or olive oil, for richness)","1/4 - 1/2 tsp salt","1/2 tsp white sugar"],"purpose":"Dill Sauce"},{"ingredients":["1/2 - 1 tbsp oil","4 salmon or trout fillets (125g / 4oz each)","Salt and pepper"],"purpose":"Fish"}]', '[{"description":"Mix the Dill Sauce ingredients together (Mix well to loosen the sour cream). Adjust consistency with milk and tartness with lemon juice. Set aside for 10 minutes if you can - if using fresh garlic, set aside for 20 min.","duration":10,"images":[],"step":1},{"description":"Pat fish dry with paper towel. Sprinkle with salt and pepper.","images":[],"step":2},{"description":"Heat oil in skillet over medium high heat. Place fish in skillet skin side down. Cook for 2 minutes, then flip and cook the other side for 1 1/2 minutes.","duration":2,"images":[],"step":3},{"description":"Remove from skillet onto serving plates. Serve with Dill Sauce on the side, garnished with fresh dill and lemon wedges if desired.","images":[],"step":4}]', '["fish","milk","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dietary","dinner-tonight","easter-mains-fish-seafood","easter-recipes","fish-recipes","gluten-free-recipes","main-dishes","quick-and-easy","quick-dinner-ideas-15-minute-meals","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_867c1d0de072', 'en', 'US', 'Honey Lemon Chicken', 'Succulent chicken with a lip smacking honey-lemon sauce. Dinner in a snap - 5 minutes prep, 4 minutes to cook the chicken, 3 minutes for the sauce = 12 minute dinner! Dusting the chicken in flour makes the skin slightly crispy which makes the sauce cling to it. Recipe VIDEO below!', 'https://www.recipetineats.com/tachyon/2016/03/Honey-Lemon-Chicken_2.jpg', 5, 7, 12, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_chicken", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_honey", "quantity": {"value": 0.125, "unit": "jar of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.075, "unit": "net of 500g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.075, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 lb / 500g chicken breast (2 pieces)","Salt and pepper","1/4 cup / 35 g flour (any)"],"purpose":"Chicken"},{"ingredients":["1 1/2 tbsp butter","1 tbsp olive oil","1 garlic clove, minced","3/4 cup / 185 ml chicken broth / stock","1/4 cup / 85g honey","1/4 cup / 60 ml lemon juice (fresh)","1 tsp soy sauce","2 tbsp water"],"purpose":"Sauce"},{"ingredients":["Lemon slices","Finely chopped parsley"],"purpose":"To serve (optional)"}]', '[{"description":"Slice each chicken breast horizontally to form 4 steaks in total. OPTIONAL (for more even cooking): Pound to even thickness about 1cm/ 2/5\" thick.","images":[],"step":1},{"description":"Sprinkle each side generously with salt and pepper.","images":[],"step":2},{"description":"Place flour in shallow dish. Coat the chicken in the flour, shaking off excess.","images":[],"step":3},{"description":"Mix 1 tsp of the flour (reserved from step 3) with the water. Set aside.","images":[],"step":4},{"description":"Cooking","images":[],"step":5},{"description":"Place butter and oil in a skillet over medium high heat until butter is melted and hot. Add chicken and cook for 2 minutes or until golden brown. Turn and cook the other side until golden brown, then transfer onto a plate to rest.","duration":2,"images":[],"step":6},{"description":"Add garlic into the skillet and stir for 20 seconds or until golden. Add chicken broth / stock and bring to simmer. Use a spatula to scrape the brown bits from the bottom of the pan into the liquid.","duration":0.3333333333333333,"images":[],"step":7},{"description":"Add honey, lemon juice, soy sauce and flour/water mixture (from step 4) into the skillet. Mix and bring to simmer for 2 to 3 minutes until thickened into a syrup. Add salt and pepper to taste.","duration":2.5,"images":[],"step":8},{"description":"To serve, pour Sauce over the chicken and garnish with parsley and lemon slices if using. Alternatively, return the chicken to the pan for 30 seconds (to reheat), turning to coat in the sauce.","duration":0.5,"images":[],"step":9}]', '["gluten","milk","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","low-calorie-recipes","main-dishes","most-popular","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0b62b8259ea8', 'en', 'US', 'Creamy Salmon Risoni / Orzo (15 Minute Meal)', 'A creamy risoni dinner in a flash! Get the ingredients out on the bench and it will take just 15 minutes to get this on the table. Watch the video to see how easy it is!', 'https://www.recipetineats.com/tachyon/2016/03/Creamy-Salmon-Risoni-Orzo_2.jpg', 5, 10, 15, 4, '[{"id": "ing_butter", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.338, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.45, "unit": "pack of 500g"}}, {"id": "ing_frozen_peas", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_salmon_fillets", "quantity": {"value": 0.17, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1.5 oz / 40g / 3 tbsp unsalted butter","1/2 onion (, diced (brown, white, yellow))","2 garlic cloves (, minced)","1 tbsp plain flour","2 cups milk (light or full fat)","2 1/4 cups chicken broth / stock","1 1/2 cups dried risoni / orzo (Note 1)","2 cups frozen peas","1/2 cup grated parmesan","6 oz / 185 g hot-smoked salmon (, flaked into large chunks using 2 forks)","Parsley (, chopped, to garnish)"]}]', '[{"description":"Melt butter in a deep skillet or pot over medium high heat.","images":[],"step":1},{"description":"Add onion and garlic, cook for 2 minutes until translucent.","duration":2,"images":[],"step":2},{"description":"Add flour and cook for 1 minute.","duration":1,"images":[],"step":3},{"description":"Switch to a whisk and add half the milk. Whisk to dissolve the pasty onion mixture into the milk (about 20 seconds). Then add remaining milk, chicken broth, risoni and peas.","images":[],"step":4},{"description":"Bring to simmer then turn heat down to medium so it bubbles gently. Cook for 5 minutes - stir occasionally for the first half then more frequently during the second half.","duration":5,"images":[],"step":5},{"title":"At 5 minutes, take it off the stove","description":"it will still be quite saucy (see video) but will reduce in the next steps and while serving.","images":[],"step":6},{"description":"Stir through parmesan cheese, salt and pepper to taste. Then gently stir through salmon.","images":[],"step":7},{"description":"Serve immediately, sprinkled with parsley leaves if desired.","images":[],"step":8}]', '["fish","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dinner-tonight","fish-recipes","main-dishes","most-popular","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","salmon-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9e8a6628d37f', 'en', 'US', 'Fish with Spicy Salsa', 'Super fast to prepare, this is a light, fresh, healthy dinner that''s a satisfying meal for less than 500 calories. By setting the salsa aside, it sweats and the juices become the "sauce" for this recipe without the need to use tons of oil! I made this spicy - Salsa Picante (which means spicy) - but you can just as just omit the chili if you prefer! I added eggplant slices to fill this out, add nutrition and interest to the dish - but this is optional.', 'https://www.recipetineats.com/tachyon/2016/03/Italian-Fish-Spicy-Salsa_4.jpg', 5, 10, 15, 2, '[{"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_basil", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_egg", "quantity": {"value": 6.0, "unit": "carton of 12"}}, {"id": "ing_fish_fillets", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_bread", "quantity": {"value": 0.2, "unit": "loaf"}}]', '[{"ingredients":["2 ripe tomatoes (, deseeded and diced (Note 1))","1/2 tsp fresh chili (, finely chopped (or 1/4 tsp red pepper flakes))","2 tsp extra virgin olive oil","1/4 tsp salt","Black pepper","1/4 cup , packed, basil leaves"],"purpose":"Spicy Salsa"},{"ingredients":["6 slices eggplant (, 1cm / 1/2\" thick)","2 x 150g / 5oz fish fillets (I used perch)","Salt and pepper","1 tbsp plain flour","1 tbsp oil"],"purpose":"Fish"},{"ingredients":["4 slices sourdough bread (, toasted)"],"purpose":"To Serve"}]', '[{"description":"Combine the Spicy Salsa ingredients except basil in a bowl. Set aside for 20 minutes to sweat so juices seep and the tomatoes soften.","duration":20,"images":[],"step":1},{"description":"Season eggplant and fish generously with salt and pepper. Then dust fish with flour, shaking off excess.","images":[],"step":2},{"description":"Heat 1/2 tbsp oil in a non stick skillet over high heat. Add the eggplant and cook each side until charred and softened - about 2 minutes first side, 1 1/2 minutes second side. Remove onto a plate.","images":[],"step":3},{"description":"Heat remaining oil. Add fish and cook until light golden on both sides, pressing down with an egg flip to brown it evenly.","images":[],"step":4},{"description":"Tear basil leaves with your hands and toss through the salsa.","images":[],"step":5},{"description":"To serve, place 3 eggplants on each plate, top with a piece of fish and spoon over the salsa + juices. Serve with toasted sourdough on the side.","images":[],"step":6}]', '["fish","gluten"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["dietary","dinner-tonight","fish-recipes","italian-recipes","low-calorie-recipes","main-dishes","quick-and-easy","quick-dinner-ideas-15-minute-meals","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e04cc7b5370c', 'en', 'US', 'Cajun Blackened Fish {+ Video}', '"Blackening" is a classic Cajun cooking technique which involves searing spice coated seafood and meats in a hot skillet so the rub turns black (but not burnt). I think the black crust and white juicy flesh inside looks so stunning! I served this with a simple Corn Butter Rice Salad - refer to the Notes for the recipe. This is adapted from this Blackened Fish Tacos recipe, a guest post here on RecipeTin Eats by Kathleen of Hapa Nom Nom. Watch the video on my YouTube Channel!', 'https://www.recipetineats.com/tachyon/2016/02/Cajun-Blackened-Fish_3.jpg', 5, 5, 10, 4, '[{"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.016, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}]', '[{"ingredients":["1 tbsp paprika","1 tsp ground cumin","1 tsp onion powder","1 tsp garlic powder","1 tsp dried thyme","1 tsp dry mustard","3/4 tsp salt (table salt)","1/8 tsp cayenne pepper (or to taste)","Good grind of black pepper"],"purpose":"Spice Mix"},{"ingredients":["4 firm white fish fillets (about 150g/5oz each) (Note 1)","2 tbsp extra virgin olive oil"],"purpose":"To Cook"}]', '[{"description":"Combine Spice Mix in a shallow dish and mix.","images":[],"step":1},{"description":"Coat both sides of the fish fillets with the Spice Mix, shaking off excess.","images":[],"step":2},{"description":"Heat oil in a large heavy based skillet over medium high heat.","images":[],"step":3},{"description":"Add fish and cook until the rub turns black, then flip and cook the other side until the fish is cooked to your taste. (Note 2)","images":[],"step":4},{"description":"Serve immediately. I served mine with a buttery Corn Rice Salad - refer to the Notes for the recipe.","images":[],"step":5}]', '["fish","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Cajun"],"categories":["dietary","dinner-tonight","fish-recipes","gluten-free-recipes","grilling-ideas-and-recipes","low-calorie-recipes","main-dishes","quick-and-easy","quick-dinner-ideas-15-minute-meals","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e0bf3cbf0fb4', 'en', 'US', 'Monte Cristo Sandwich (Ham Cheese French Toast)', 'Monte Cristo is America''s answer to the French classic Croque Monseur. Most commonly made with ham, but also found made with turkey and other sliced meats. Gruyere is the most common type of cheese used but really, you can''t go wrong no matter what type of cheese you use, just as long as it''s a good melting cheese!', 'https://www.recipetineats.com/tachyon/2015/12/Monte-Cristo_PS_1.jpg', 5, 8, 13, 2, '[{"id": "ing_bread", "quantity": {"value": 0.2, "unit": "loaf"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.025, "unit": "jar of 400g"}}, {"id": "ing_gruyere_cheese", "quantity": {"value": 2.0, "unit": "block of 200g"}}, {"id": "ing_ham", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}]', '[{"ingredients":["4 slices bread of choice (Note 1)","1 large egg or 2 small eggs","1 tbsp milk","Salt","2 tsp mayonnaise (I like whole egg mayo)","2 - 4 slices gruyere cheese (or other grated or sliced melting cheese of choice)","Ham or turkey (, sliced or shaved)","1 - 2 tbsp unsalted butter"]}]', '[{"description":"Lightly whisk egg, milk and a generous pinch of salt in a flat bowl.","images":[],"step":1},{"description":"Spread 2 slices of bread with mayonnaise.","images":[],"step":2},{"description":"Top with ham, then cheese, then sandwich with remaining slices of bread. Press down firmly.","images":[],"step":3},{"description":"Melt butter in a skillet over medium heat.","images":[],"step":4},{"description":"Dip each side of the sandwiches briefly in the egg mixture, then place in skillet.","images":[],"step":5},{"description":"Cook the first side, pressing down with an egg flip, for 3 minutes or until deep golden brown.","duration":3,"images":[],"step":6},{"description":"Flip and cook the other side for 3 minutes, pressing down firmly with the egg flip, until golden brown and the cheese is melted.","duration":3,"images":[],"step":7},{"description":"Serve immediately, while hot!","images":[],"step":8}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["breakfast","lunch"],"cuisine":["American"],"categories":["breakfast-recipes","leftover-ham-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","sandwiches-and-sliders"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_06c0f643c46d', 'en', 'US', 'Iceberg Lettuce Wedges with Ranch Dressing', 'One of my favourite salads to serve when I''m entertaining because it looks impressive and it takes all of 5 seconds to chop!', 'https://www.recipetineats.com/tachyon/2015/11/Lettuce-Wedges-with-Ranch-Dressing_1.jpg', 10, 0, 10, 4, '[{"id": "ing_butter", "quantity": {"value": 0.5, "unit": "block of 250g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.15, "unit": "tub of 250g"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.094, "unit": "jar of 400g"}}, {"id": "ing_lemon", "quantity": {"value": 0.075, "unit": "net of 500g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_dill", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_chives", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}]', '[{"ingredients":["1/2 cup buttermilk","1/4 cup sour cream","1/4 cup whole egg mayonnaise (if using normal, omit the lemon juice)","2 tsp fresh lemon juice","1 tsp garlic powder","1 1/2 tsp dried dill","2 tbsp fresh chives (, finely chopped)","1/2 tsp table salt","Black pepper"],"purpose":"Ranch Dressing"},{"ingredients":["1 iceberg lettuce (, cut into 6 - 8 wedges)","Chives (, finely chopped (optional))"],"purpose":"To Serve"}]', '[{"description":"Combine the Ranch Dressing ingredients in a bowl and whisk until smooth.","images":[],"step":1},{"description":"Transfer to a jug and refrigerate until required.","images":[],"step":2},{"description":"To serve, place the iceberg wedges onto a plate with the dressing on the side.","images":[],"step":3}]', '["egg","milk"]', '["gluten_free","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Western"],"categories":["all-vegetable-sides","easter-sides-fresh-light","leafy-greens","quick-and-easy","quick-dinner-ideas-15-minute-meals","side-salads","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4c471db437a8', 'en', 'US', 'Cinnamon French Toast Bites', 'French toast in bite size form! These are really fun to make - you "sauté" them as though they are cubes of tofu or chicken, then toss in cinnamon sugar. And it goes without saying they are also fun to eat! They taste like mini cinnamon sugar doughnuts. :)', 'https://www.recipetineats.com/tachyon/2015/03/Cinnamon-Sugar-French-Toast-Bites-2.jpg', 8, 7, 15, 3, '[{"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_maple_syrup", "quantity": {"value": 1.0, "unit": "bottle of 250ml"}}]', '[{"ingredients":["4 thick slices of slightly stale white bread (1\"/2.5cm thick) (Note 1)","2 large eggs (or 3 small eggs)","1/4 cup milk","Pinch of salt","1/4 cup white sugar","1/2 tsp cinnamon powder","3 tbsp butter (, separated)","Maple syrup to serve (not optional!)"]}]', '[{"description":"Cut the crust off the bread, then cut each piece into 9 equal cubes.","images":[],"step":1},{"description":"Whisk the eggs, milk and salt in a medium bowl.","images":[],"step":2},{"description":"Combine sugar and cinnamon in a shallow bowl.","images":[],"step":3},{"description":"Melt 1 1/2 tbsp of butter in a fry pan over medium high heat. Don''t let the butter brown.","images":[],"step":4},{"description":"Quickly toss half the bread cubes in the egg mixture and use your hands to shake off excess egg mixture. Place the bread cubes in the fry pan and use a wooden spoon to \"sauté\" them until browned on all sides - about 2 to 3 minutes.","images":[],"step":5},{"description":"Remove the bread cubes from the fry pan straight into the sugar mixture. Toss to coat, then remove onto a plate.","images":[],"step":6},{"description":"Repeat with remaining bread cubes.","images":[],"step":7},{"description":"Serve immediately, with maple syrup for dipping.","images":[],"step":8}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["breakfast","dessert"],"cuisine":[],"categories":["bite-size-desserts","breakfast-recipes","dessert-recipes","most-popular","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0969a184b350', 'en', 'US', 'Spicy Parmesan Party Popcorn', 'Great party food because it''s so fast and cheap to make, and so addictive but your guests won''t get too full! The key tip with this is to prepare it all in advance then assemble just before serving, otherwise the oil spray and moisture in the parmesan gets absorbed into the popcorn so it loses its crunchiness.', 'https://www.recipetineats.com/tachyon/2015/02/Spicy-Parmesan-Popcorn-FINAL.jpg', 10, 5, 15, 16, '[{"id": "ing_vegetable_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_corn", "quantity": {"value": 0.003, "unit": "can of 400g"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 0.5, "unit": "pack of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.062, "unit": "jar of 40g"}}]', '[{"ingredients":["¼ cup vegetable oil (not required if air popping with a popcorn maker)","½ cup popping corn"],"purpose":"Popcorn"},{"ingredients":["Olive oil spray","1/2 to 2/3 cups freshly grated parmesan cheese (finely grated) (Note 1)","3/4 tsp fine salt (Not flakes because it won''t stick. Table salt is fine)","1 tsp cayenne pepper (or chilli) (adjust to your taste)","1/2 tsp paprika (optional - this is for a bit of extra colour)"],"purpose":"Flavourings"}]', '[{"description":"Pop the popcorn in a popcorn maker or on the stove (see steps 2 and 3).","images":[],"step":1},{"title":"Make popcorn on the stove","description":"Heat oil in a large pot over medium heat. Add a few pieces of popcorn - if the corn slowly spins in the oil then the oil is hot enough.","images":[],"step":2},{"description":"Add remaining popcorn and cover with a lid. Once the popcorn starts popping, shake the pot gently every now and then.","images":[],"step":3},{"description":"Remove from heat when the popping stops (when you can count to 3 between pops) and transfer to a large bowl.","images":[],"step":4},{"description":"Combine the salt, cayenne pepper and paprika in a small bowl and mix to combine (\"Spice Mix.","images":[],"step":5},{"description":"Get a large serving bowl and place 1/3 of the popcorn in it. Spray generously with olive oil then sprinkle over 1/3 of the parmesan and 1/3 of the Spice Mix.Repeat twice more. Do not toss. The flavourings will naturally toss through as people start to dig in.","images":[],"step":6},{"description":"Serve immediately.","images":[],"step":7}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["australia-day","dietary","gluten-free-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","snacks"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_54f53ca70e98', 'en', 'US', 'Mini Strawberry French Toast', 'Super fast to make, and a great breakfast in bed because it''s crumb and cutlery free!', 'https://www.recipetineats.com/tachyon/2015/02/Mini-French-Toast-PS-Edited-FINAL1.jpg', 10, 5, 15, 2, '[{"id": "ing_strawberries", "quantity": {"value": 0.6, "unit": "punnet of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_bread", "quantity": {"value": 0.5, "unit": "loaf"}}, {"id": "ing_maple_syrup", "quantity": {"value": 1.0, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_strawberries", "quantity": {"value": 0.6, "unit": "punnet of 250g"}}]', '[{"ingredients":["1 cup sliced strawberries","2 tsp sugar (white)","2 eggs","2 tbsp milk (full or low fat)","Pinch of salt","1 - 2 tbsp unsalted butter (more = yummier)","10 slices of baguette ((french stick), around 2 1/5\" / 3cm thick)"]},{"ingredients":["Maple syrup (not optional!)","Confectioners sugar (icing sugar), for dusting (optional)","Extra strawberries (optional)"],"purpose":"To Serve"}]', '[{"description":"Combine the sugar and strawberries in a bowl and set aside to macerate (it sweats to form a bit of syrup).","images":[],"step":1},{"description":"Lightly whisk the eggs, milk and salt in a shallow bowl.","images":[],"step":2},{"description":"Melt butter in a large fry pan over medium high heat.","images":[],"step":3},{"description":"Dip each side of the bread slices into the egg, 3 seconds on each side. Place in the pan and fry each side for 2 1/2 minutes, until it is nicely browned.","images":[],"step":4},{"description":"Remove from the fry pan, and serve, topped with the strawberries (use the syrup created), maple syrup and confectioners sugar (icing sugar), if using.","images":[],"step":5}]', '["egg","milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["breakfast"],"cuisine":[],"categories":["breakfast-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_592f9a715eb2', 'en', 'US', 'Grilled Eggplant with Yoghurt Sauce', 'This is adapted from a recipe by Karen Martini, a great Australian chef. Simple to make and so incredibly delicious. A "meaty" meat free dish for carnivores! I have noted where I strayed from the original recipe. This serves 3 to 4 as a light meal (accompanied with, for example, couscous), or 6 to 8 as a side.', 'https://www.recipetineats.com/tachyon/2015/01/DSC_0489.jpg', 8, 7, 15, 3, '[{"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.3, "unit": "tub of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_tahini", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_pomegranate", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_mint", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}]', '[{"ingredients":["3 large eggplants","1/4 cup olive oil","Salt and pepper"],"purpose":"Grilled Eggplant"},{"ingredients":["1 cup plain unsweetened yoghurt (Greek or natural)","1 garlic clove (, minced (Medium size. 1 large clove will make it too garlicky))","1 tsp cumin powder (Note 1)","1 to 2 tbsp fresh lemon juice (use amount to taste) (Note 2)","2 tbsp tahini (sesame paste) (you can leave this out if you don''t have it, it is still a tasty sauce)","1/4 tsp salt (, slightly heaped (about 3/8 tsp))","Black pepper"],"purpose":"Yoghurt Sauce"},{"ingredients":["1/2 pomegranate (, seeds only (Note 3))","2 tbsp mint leaves (, finely sliced)","2 tbsp coriander / cilantro leaves","Red chilli (, finely sliced (to taste) (Note 4))","Wedges or cheeks of lemon (optional)"],"purpose":"Garnish"}]', '[{"description":"Combine the Yoghurt Sauce ingredients in a bowl and mix well. Set aside for the flavours to develop. The longer you leave it, the better it will taste.","images":[],"step":1},{"description":"Use a potato peeler to peel \"strips\" off the eggplant vertically as per the photo below. If your potato peeler is not sharp enough or if the eggplant is on the soft side, you might need to do this with a small sharp knife.","images":[],"step":2},{"description":"Cut the eggplant into 1.5cm / 2/3\" thick rounds.","images":[],"step":3},{"description":"Brush one side of each eggplant with olive oil. The more you use, the yummier it will be!","images":[],"step":4},{"description":"Sprinkle the oiled side of the eggplant with salt and pepper.","images":[],"step":5},{"description":"Heat a griddle pan (or BBQ) on medium high heat. (Note 5)","images":[],"step":6},{"description":"Place the oiled side of each eggplant onto the pan and grill for 2 to 3 minutes until it gets deep char lines on it. While the first side is cooking, brush the other side of each eggplant with the remaining olive oil and sprinkle with salt and pepper.","duration":2.5,"images":[],"step":7},{"description":"Turn the eggplant and cook the other side until the eggplant is cooked through but still holding it''s shape. The easy way to tell is to prod the centre - if you feel resistance, it needs to cook more.","images":[],"step":8},{"description":"Remove the eggplant onto a serving plate and let it cool for a few minutes. Then spoon a dollop of the yoghurt sauce on each, and scatter with coriander/cilantro, mint, pomegranate seeds and chili. Drizzle with extra olive oil and serve with cheeks or wedges of lemon, if desired.","images":[],"step":9}]', '["milk","sesame"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Contemporary Middle Eastern"],"categories":["all-vegetable-sides","cuisines","dietary","easter-sides-warm-hearty","eggplant","gluten-free-recipes","grilling-ideas-and-recipes","middle-eastern-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","side-dishes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e2f91cffecc3', 'en', 'US', 'Red, Green and White Christmas Salad', 'A festive salad filled with Christmas colours to compliment any festive spread! Perfect for making ahead.', 'https://www.recipetineats.com/tachyon/2014/12/Christmas-Sides-618.jpg', 10, 5, 15, 8, '[{"id": "ing_es_asparagus", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_green_beans", "quantity": {"value": 283.5, "unit": "pack"}}, {"id": "ing_snow_peas", "quantity": {"value": 5.0, "unit": "unit"}}, {"id": "ing_feta_cheese", "quantity": {"value": 4.0, "unit": "block of 200g"}}, {"id": "ing_cranberries", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_honey", "quantity": {"value": 0.03, "unit": "jar of 500g"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.09, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["2 bunches asparagus","10 oz / 300g green beans","5 oz / 150g snow peas","4 oz / 120g feta","1/3 cup dried cranberries"]},{"ingredients":["1 tbsp honey","2 tsp dijon mustard","2 tbsp lemon juice","6 tbsp olive oil","1/2 tsp salt","Black pepper"],"purpose":"Dressing"}]', '[{"description":"Fill a large pot with water and bring to boil.","images":[],"step":1},{"description":"Cut the woody ends off the asparagus, then cut the asparagus into 3. Separate the asparagus heads from the stems.","images":[],"step":2},{"description":"Trim the beans and place in a separate pile.","images":[],"step":3},{"description":"Remove the strings along each side of the snow peas.","images":[],"step":4},{"description":"Place the beans in the boiling water. When the water comes back to the simmer again, leave the beans to simmer for 30 seconds. (Note 1)","duration":0.5,"images":[],"step":5},{"description":"Add the asparagus stems in. Once it comes back up to a simmer, count 30 seconds again. Then add the snow peas and asparagus heads, bring it back up to a simmer and count to 30 seconds.","images":[],"step":6},{"description":"Immediately drain the greens and run cold water over the greens for 10 seconds to stop the cooking process.","duration":0.16666666666666666,"images":[],"step":7},{"description":"Once cool, set aside to dry. Roughly dry with a paper towel if serving immediately.","images":[],"step":8},{"description":"Combine the Dressing ingredients in a jar and shake well to mix.","images":[],"step":9},{"description":"Place the greens in a bowl and toss with the Dressing.","images":[],"step":10},{"description":"Transfer to a serving bowl, crumble over feta and scatter with dried cranberries. Serve immediately.","images":[],"step":11}]', '["mustard"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["lunch"],"cuisine":[],"categories":["all-vegetable-sides","dietary","easter-sides-fresh-light","gluten-free-recipes","green-beans","peas","quick-and-easy","quick-dinner-ideas-15-minute-meals","side-salads","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_327ff046697a', 'en', 'US', 'Grilled Vegetables Platter', 'This is like a homemade vegetable antipasto that costs a fraction of store bought, tastes better and you know is preservative free. Whether as a starter or a vegetarian main, this is one of those dishes that proves that simple is best. This recipe includes a Yoghurt Sauce which gives this a Middle Eastern touch. Use whatever vegetables you want, so long as they are suitable for grilling.', 'https://www.recipetineats.com/tachyon/2014/12/Chargrilled-Vegetable-Platter-1.jpg', 8, 7, 15, 4, '[{"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_zucchini", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_squash", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 1.0, "unit": "jar of 50g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.15, "unit": "tub of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.167, "unit": "pack of 3 heads"}}, {"id": "ing_cumin", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_black_pepper", "quantity": {"value": 1.0, "unit": "jar of 50g"}}, {"id": "ing_cumin", "quantity": {"value": 0.062, "unit": "jar of 40g"}}]', '[{"ingredients":["1 red capsicum ((bell pepper), cut into slices)","1 red onion (, peeled and cut into 12 wedges)","1 large eggplant (, sliced vertically into 1/2 cm / 1/5\" slices)","3 zucchinis (, sliced vertically into thin slices)","3 squash (, sliced into thin slices)","Olive oil","Salt","Pepper","Parsley or coriander leaves and lemon wedges (, for garnish)"]},{"ingredients":["1/2 cup Greek yoghurt","1/2 garlic clove (, crushed)","1/2 tsp cumin powder","Squeeze of lemon juice","Salt and pepper","Extra pinch of cumin (, for garnish)"],"purpose":"Yoghurt Sauce"}]', '[{"description":"Combine the Yoghurt Sauce ingredients in a bowl and mix. Set aside in the fridge until required.","images":[],"step":1},{"description":"Heat the outdoor grill on high (hot plate side). Or a heavy based pan on the stove on high heat.","images":[],"step":2},{"description":"Drizzle olive oil on the hot plate / fry pan.","images":[],"step":3},{"description":"Place vegetables on the grill / fry pan and cook until charred (about 1 1/2 - 2 minutes). Turn over then cook the other side until charred (about 1 1/2 minutes). Don''t worry if the vegetables are a bit undercooked, they will continue to cook while resting.","images":[],"step":4},{"description":"Remove from the hot plate / fry pan and place in a bowl. Sprinkle the vegetables in the bowl with a pinch of salt and pepper.","images":[],"step":5},{"description":"Repeat with remaining vegetables, and pile the vegetables on top of each other in the bowl. Don''t forget to add a pinch of salt and pepper on each layer of vegetables.","images":[],"step":6},{"description":"Cover and let it cool to room temperature.","images":[],"step":7},{"description":"If you are making this ahead, place the vegetables in the refrigerator until required. Bring to room temperature before serving.","images":[],"step":8},{"description":"To serve, place the vegetables on a platter, drizzle over olive oil (the more generous the better!) then garnish with parsley/coriander leaves and lemon wedges (if using). Place the yoghurt on the side (garnish with a pinch of cumin powder) and serve with flatbread or crusty bread.","images":[],"step":9}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["snack"],"cuisine":["Middle Eastern"],"categories":["australia-day","dietary","easter-sides-fresh-light","gluten-free-recipes","grilling-ideas-and-recipes","most-popular","quick-and-easy","quick-dinner-ideas-15-minute-meals","side-dishes","side-salads","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3efd06e449ae', 'en', 'US', 'Super Quick Chicken Dinner: Crumbed Chicken with Mashed Potatoes', 'With few clever shortcuts and a bit of multi tasking, you''ll get this complete dinner on the table in 15 minutes. The crunchy crumbed chicken is sensational. The secret is mayonnaise which is used to make the panko breadcrumbs stick to the chicken, plus it provides the seasoning.', 'https://www.recipetineats.com/tachyon/2014/12/Fast-Crumbed-Chicken-1.jpg', 5, 10, 15, 2, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.15, "unit": "jar of 400g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.15, "unit": "pack of 200g"}}, {"id": "ing_bread", "quantity": {"value": 0.113, "unit": "loaf"}}, {"id": "ing_potato", "quantity": {"value": 2.0, "unit": "bag of 2kg"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_cucumber", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}]', '[{"ingredients":["400 g / 13oz chicken breast minute steaks (4 pieces x 100g/3oz each) (Note 1)","4 tbsp mayonnaise (, preferably whole egg (Note 2))","2 tbsp parmesan cheese (, grated)","6 tbsp panko breadcrumbs (Note 3)"],"purpose":"Chicken"},{"ingredients":["2 medium potatoes ((Note 4), not peeled)","1/4 to 1/2 cup milk (full fat or low fat)","1 tbsp butter (optional)","Salt and pepper (, to taste)"],"purpose":"Fast Mashed Potato"},{"ingredients":["1 large cucumber (or 2 small cucumbers)","1 punnet cherry tomatoes (or 2 medium tomatoes)","1 tbsp lemon juice","2 tbsp olive oil","Salt and pepper (, to taste)"],"purpose":"Salad"}]', '[{"description":"Turn grill/broiler on high and place the shelf about 20cm/8\" from the heat source.","images":[],"step":1},{"description":"Place potatoes in the microwave and cook on high for 3 minutes. Then turn the potatoes over and cook on high for a further 2 minutes (or until cooked). Squeeze the potatoes to check if they are cooked.","duration":3,"images":[],"step":2},{"description":"Mix the mayonnaise and parmesan cheese in a small bowl.","images":[],"step":3},{"description":"Place the chicken in a large oven proof fry pan (Note 5). Using the back of a spoon, spread the mayonnaise mixture over each chicken breast.","images":[],"step":4},{"description":"Sprinkle panko breadcrumbs over each piece of chicken. Use your fingers to pat the panko so it sticks to the chicken. (Note 6)","images":[],"step":5},{"description":"Place chicken under the grill/broiler for 8 minutes, or until just cooked through and the crumbs are golden. Check it once at around 6 minutes and rotate the fry pan if necessary so the crumb cooks evenly all over. When cooked, set aside to rest for a few minutes before serving.","duration":8,"images":[],"step":6},{"description":"While the chicken is cooking, get the potatoes out of the microwave (use a dishcloth). Cut each potato in half, then use a dessert spoon to scoop the flesh out into a bowl. Add milk, butter, salt and pepper. Use a potato masher to mash. Add more milk to achieve the desired consistency.","images":[],"step":7},{"title":"Salad","description":"Use a potato peeler to make ribbons from the cucumber. Cut the cherry tomatoes in half. Pile the cucumber and cherry tomatoes onto a plate, then drizzle over lemon juice, olive oil and scatter with salt and pepper.","images":[],"step":8},{"title":"To Serve","description":"Place mashed potato on each plate then top with the chicken. Drizzle with extra olive oil and garnish with finely chopped fresh parsley, if desired. Serve the Salad on the side.","images":[],"step":9}]', '["egg","milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","most-popular","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_41eeea38b062', 'en', 'US', 'Strawberry Nutella French Toast Roll Ups', 'These french toast roll ups taste like an awesome doughnut!', 'https://www.recipetineats.com/tachyon/2014/11/DSC_0303.jpg', 10, 5, 15, 6, '[{"id": "ing_bread", "quantity": {"value": 0.3, "unit": "loaf"}}, {"id": "ing_strawberries", "quantity": {"value": 0.5, "unit": "punnet of 250g"}}, {"id": "ing_nutella", "quantity": {"value": 4.5, "unit": "unit"}}, {"id": "ing_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["6 slices fresh white sandwich bread (, crusts removed)","1/2 punnet strawberries (, diced small)","4 1/2 tbsp Nutella","1/4 cup caster sugar (superfine sugar) (Note 1)","1 tbsp butter"]},{"ingredients":["1 egg (large)","2 tbsp milk (full cream or low fat)","Pinch of salt"],"purpose":"Egg Mixture"}]', '[{"description":"Combine Egg Mixture in a bowl with a flat base large enough to lie the roll up in. Whisk to combine.","images":[],"step":1},{"description":"Spread sugar out in a small dish.","images":[],"step":2},{"description":"Use a rolling pin to roll the bread flat. This makes them easier to roll up (and stay rolled up).","images":[],"step":3},{"description":"Spread each piece of bread with around 3/4 tbsp of Nutella.","images":[],"step":4},{"description":"Sprinkle strawberries along the bottom of each piece of bread.","images":[],"step":5},{"description":"Roll up bread. The Nutella will keep it sealed.","images":[],"step":6},{"description":"Melt butter in pan over medium high heat.","images":[],"step":7},{"description":"Roll each roll up in the Egg Mixture, shake off excess then place in the pan. Repeat with remaining roll ups.","images":[],"step":8},{"description":"Cook for around 4 minutes until each side is golden, rotating every 1 minute or so.","images":[],"step":9},{"description":"Remove from pan and immediately place in the sugar. Roll to coat in sugar, then remove. Repeat with remaining roll ups.","images":[],"step":10},{"description":"Serve immediately, while warm.","images":[],"step":11}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["breakfast","dessert"],"cuisine":[],"categories":["bite-size-desserts","breakfast-recipes","dessert-recipes","most-popular","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f7b1024c0dbd', 'en', 'US', 'Smoked Trout Dip / Potted Smoked Trout (le Budget le Gourmet)', 'An elegant starter that is fast, easy and affordable. Use it as a dip or serve like a spread. Make sure to get whole smoked trout from the seafood shop with the skin on, not the vacuum sealed or canned portions. It''s far cheaper and the flesh is much juicier and flavoursome. This recipe is adapted from Australian Gourmet Traveller. I have provided more detailed ingredients and directions, and changed a step that did not work for me.', 'https://www.recipetineats.com/tachyon/2014/12/Potted-Smoked-Trout-1.jpg', 5, 5, 10, 4, '[{"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_whole_smoked_trout", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_creme_fraiche", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_cream", "quantity": {"value": 0.454, "unit": "carton of 250ml"}}, {"id": "ing_dill", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_chives", "quantity": {"value": 0.03, "unit": "kg"}}]', '[{"ingredients":["1 stick / 4 oz / 120 g unsalted butter (, roughly chopped)","1 eschallot (golden shallot), finely diced (Note 1)","1 garlic clove (, very finely chopped)","Rind of 1 lemon (, very finely grated (yellow part only, the white part is bitter))","1 1/2 tbsp lemon juice","1 lb / 500g whole smoked trout","Pinch of cayenne pepper","4 oz / 120g creme fraiche (or sub with full fat sour cream) (Note 2)","1 tbsp cream (full fat, not whipped)","1/4 cup fresh dill (, coarsely chopped)","2 tbsp chives (, coarsely chopped)"]}]', '[{"description":"Melt butter in a small saucepan over medium heat until melted, then pour 2/3 into a bowl and set aside.","images":[],"step":1},{"description":"Add the shallot, garlic and lemon rind to the pan and let it cook gently for 3 to 5 minutes until soft and translucent (it should not brown). You will only need to stir it occasionally.","duration":4,"images":[],"step":2},{"description":"Meanwhile, remove the skin off the trout and discard. Use your hands to remove the flesh and place into a bowl, being careful to avoid the bones (you will be able to pull the flesh off the bones easily). Use a fork to flake the flesh. Discard the bones.","images":[],"step":3},{"description":"Pour the shallot butter mixture into the bowl with the trout.","images":[],"step":4},{"description":"Add lemon juice, cayenne pepper, creme fraiche, cream and herbs. Stir gently until well combined. Do a taste test and add salt and pepper if required. You may not need salt as smoked trout is often salty (I only add a tiny pinch).","images":[],"step":5},{"description":"Spoon into jars or ramekins (1 large, 2 medium or 4 small) and smooth the surface.","images":[],"step":6},{"description":"Pour over the reserved butter until the top is covered.","images":[],"step":7},{"title":"Place in the refrigerator to set. (Note","description":"Original recipe set to freeze it for 5 - 10 minutes first but I found that this caused the surface of the butter to crack).","duration":7.5,"images":[],"step":8},{"description":"This can be served on the day you make it, but it gets even better with time. It can be made up to a week in advance.","images":[],"step":9},{"description":"Serve with fresh or toasted bread.","images":[],"step":10}]', '["milk"]', '["gluten_free","high_protein","keto_friendly","vegetarian"]', '{"mealType":["snack"],"cuisine":[],"categories":["dietary","dip-recipes","gluten-free-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_72282690db4d', 'en', 'US', 'Shredded Red Cabbage, Carrot and Mint Salad', 'A colourful, refreshing, crunchy salad that is versatile and will suit pretty much any cuisine. I made this as part of a multi-course Middle Eastern menu as a salad to accompany the mains as well as using in wraps.', 'https://www.recipetineats.com/tachyon/2014/11/Shredded-Red-Cabbage-Carrot-and-Mint-Salad.jpg', 10, 0, 10, 4, '[{"id": "ing_cabbage", "quantity": {"value": 12.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_mint", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["4 cups finely shredded red/purple cabbage","1 carrot (, julienned)","Handful of mint leaves (, roughly chopped)"],"purpose":"Salad"},{"ingredients":["2 tbsp lemon juice","3 tbsp olive oil","1/2 tsp salt","Black pepper"],"purpose":"Dressing"}]', '[{"description":"Combine Salad ingredients in a bowl.","images":[],"step":1},{"description":"Add Dressing ingredients, then toss to combine.","images":[],"step":2}]', '[]', '["gluten_free","keto_friendly","low_calorie","vegan","vegetarian"]', '{"mealType":["lunch"],"cuisine":[],"categories":["all-vegetable-sides","cabbage","cuisines","dietary","easter-sides-fresh-light","gluten-free-recipes","middle-eastern-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","side-salads","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_33720d55252d', 'en', 'US', 'Sirloin Steak with Pesto, Bell Peppers (Capsicum) & Flatbread', 'Beef is like wine. You get what you pay for. So if you invest in a good steak, keep it simple and concentrate on the sides to serve up a dinner that will make any meat lover beam with pleasure.', 'https://www.recipetineats.com/tachyon/2014/11/Sirloin-Steak-with-Pesto-Capsicum-and-Flatbread-2.jpg', 5, 10, 15, 2, '[{"id": "ing_beef_steak", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 1.0, "unit": "jar of 50g"}}, {"id": "ing_pesto", "quantity": {"value": 0.003, "unit": "jar of 190g"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["2 x 10oz / 300g sirloin beef steak (, 2.5 cm/ 1 inch thick (the best you can afford))","2 tbsp vegetable oil ((or canola), separated)","1 red bell pepper ((capsicum), deseed, halved and sliced into strips)","Salt and pepper"]},{"ingredients":["Pesto (preferably homemade - see notes for recipe)","Flatbreads (see recipe Easy Soft Flatbread (No Yeast))"],"purpose":"To serve"}]', '[{"description":"Preferably bring your steak to room temperature. This will take 30 minutes if the air temperature is warm/hot, or an hour if it''s cool.","images":[],"step":1},{"description":"Season steaks generously with salt and pepper. Do this just before you cook it.","images":[],"step":2},{"description":"Heat 1 tbsp oil in a heavy based fry pan over high heat until it starts to smoke.","images":[],"step":3},{"description":"Place steaks in the fry pan. Cook each side for 2 minutes for medium rare. See notes for cooking times.","duration":2,"images":[],"step":4},{"description":"Remove steaks from the fry pan onto a plate and cover loosely (not tightly) with foil. Allow to rest for 5 minutes, up to 10 minutes.","duration":5,"images":[],"step":5},{"description":"While the steak is resting, return the fry pan to the stove over medium high heat with 1 tbsp oil.","images":[],"step":6},{"description":"Add the bell pepper (capsicum) and cook, stirring occasionally, until nicely charred. Remove from heat.","images":[],"step":7},{"description":"Serve the steaks topped with the bell pepper and with Pesto and Flatbread on the side.","images":[],"step":8}]', '[]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["main_course"],"cuisine":[],"categories":["beef-recipes","dietary","gluten-free-recipes","grilling-ideas-and-recipes","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_18d2e1a1d64a', 'en', 'US', 'Bacon French Toast Roll Ups', 'Crispy bacon rolled up in french toast that you can eat with your hands. Take it to an insane level by adding Nachos Cheese Dipping Sauce to dunk the roll ups in.', 'https://www.recipetineats.com/tachyon/2014/10/Bacon-French-Toast-Roll-Ups-4.jpg', 5, 10, 15, 2, '[{"id": "ing_bread", "quantity": {"value": 0.3, "unit": "loaf"}}, {"id": "ing_bacon", "quantity": {"value": 1.2, "unit": "pack of 200g"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}]', '[{"ingredients":["6 slices fresh soft sandwich bread (I used white, but you could use wholemeal, wholegrain etc) (note 1)","6 slices of streaky bacon (, rind removed (note 3))","1 tbsp butter","1 egg (large) (note 4)","2 tbsp milk (full cream or low fat)","Pinch of salt"]},{"ingredients":["Nachos Cheese Dip"],"purpose":"To Serve (optional)"}]', '[{"description":"Cut crusts off the bread.","images":[],"step":1},{"description":"Use a rolling pin and roll back and forth 3 or 4 times on each piece of bread to flatten it out. Because it is fresh bread, it should become a bit sticky.","images":[],"step":2},{"description":"Combine egg, milk and salt in a dish or bowl that is large enough for a roll up to lie flat in (so you can roll it in the egg mixture). Whisk with a fork to combine.","images":[],"step":3},{"description":"Heat large pan over high heat (no oil required because the bacon is so fatty).","images":[],"step":4},{"description":"Place bacon in the pan and sear each side until browned but not until it is crispy. If it is too crispy, it will just crumble when rolled up.","images":[],"step":5},{"description":"Place one piece of bacon in the middle of each piece of bread.","images":[],"step":6},{"description":"Roll up the bread, ending with the seam side down. Press down lightly to help it stay in place.","images":[],"step":7},{"description":"Wipe pan clean, place butter in pan and return pan to heat.","images":[],"step":8},{"description":"Roll a roll up in the egg mixture, then shake off excess. Enclose your fist around it (lightly) and twist the roll up a few times back and forth. This rubs the egg mixture into the roll up and helps ensure the seam remains sealed. Repeat with remaining roll ups.","images":[],"step":9},{"description":"Place roll ups in the pan. Cook, rotating, for around 3 to 4 minutes until all sides are golden brown.","images":[],"step":10},{"description":"Remove and serve immediately, with warmed Nachos Cheese Dip (if using).","images":[],"step":11}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["breakfast"],"cuisine":[],"categories":["breakfast-recipes","most-popular","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_79b19833d9ef', 'en', 'US', 'Pea, Zucchini and Pesto Orzo (Risoni)', 'This is a great super quick midweek meal. It''s better made with homemade pesto, but store bought is fine too. I store homemade pesto in the freezer by pouring it into ice cube trays. That way I have serving size portions of pesto on hand when I need it. Sometimes I stir through frozen spinach to add more nutrition into this.', 'https://www.recipetineats.com/tachyon/2014/11/Green-Vegetable-Pesto-Risoni-Orzo-51.jpg', 5, 10, 15, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.2, "unit": "pack of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_basil", "quantity": {"value": 0.75, "unit": "bunch"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_zucchini", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["2/3 cup risoni","1 tbsp olive oil","2 1/2 tbsp basil pesto (, preferably homemade (see notes for recipe))","1 small onion ((brown, yellow or white), diced)","1 garlic clove (, crushed)","3 cups zucchini (, diced)","1 cup frozen peas (, preferably defrosted)","1/4 tsp salt","Black pepper"]},{"ingredients":["Parmesan cheese (, freshly grated)"],"purpose":"To Serve"}]', '[{"description":"Place about 8 cups of water in a large saucepan and bring to boil.","images":[],"step":1},{"description":"Add risoni and cook for 4 minutes, then add peas and cook for a further 1 minute. Note: The risoni will be slightly underdone at this point. It will finish cooking in the remaining steps.","duration":4,"images":[],"step":2},{"description":"Scoop out 1/2 cup of the water from the saucepan, then drain the risoni and set aside until ready to add to the pan.","images":[],"step":3},{"description":"Heat olive oil in a fry pan over medium high heat.","images":[],"step":4},{"description":"Add garlic and onion and sauté for 1 minute until starting to soften.","duration":1,"images":[],"step":5},{"title":"Add zucchini and sauté for a further 2","description":"3 minutes until both the zucchini and onion are softened and the onion is starting to turn a light golden brown.","images":[],"step":6},{"description":"Add pesto, risoni, pasta water reserved in step 3, salt and pepper. Bring the water to a simmer and stir for 1 minute until the water is absorbed.","duration":1,"images":[],"step":7},{"description":"Serve immediately, garnished with freshly grated parmesan.","images":[],"step":8}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dietary","gluten-free-recipes","pasta-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","zucchini-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b2c4210917b8', 'en', 'US', 'Crispy Shredded Chicken Noodle Stir Fry', 'This is a super quick stir fry made using the chicken and braising liquid from my Slow Cooker Crispy Chinese Shredded Chicken. It freezes extremely well so is fantastic to have on hand for fast midweek meals. I made this stir fry using Chinese Broccoli but you can use whatever vegetables you wish. Bean sprouts, carrots, other Chinese greens, broccoli and sliced onion would go particularly well in this dish.', 'https://www.recipetineats.com/tachyon/2014/10/DSC_0180.jpg', 5, 5, 10, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.283, "unit": "pack of 500g"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_chicken", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_sriracha", "quantity": {"value": 0.037, "unit": "bottle of 400ml"}}, {"id": "ing_broccoli", "quantity": {"value": 0.45, "unit": "kg"}}]', '[{"ingredients":["5 oz / 150g dried rice stick noodles (see note 1)","2 tbsp oil (vegetable, canola or peanut oil)","2 garlic cloves (, smashed (see note 2))","1 cup Slow Cooker Crispy Chinese Shredded Chicken (\"Shredded Chicken\")","1/2 cup Slow Cooker Crispy Chinese Shredded Chicken braising liquid (see note 3)","1 tbsp Sriracha sauce (or any hot sauce or chili paste) (optional)","3 cups (tightly packed) Chinese broccoli, leaves separated from stems (cut stems vertically into thin sticks) (about 1 small bunch)"]}]', '[{"description":"Cook / soak rice stick noodles according to packet instructions. Drain and set aside.","images":[],"step":1},{"description":"Heat oil in wok or large fry pan over high heat.","images":[],"step":2},{"description":"Add garlic and stir fry for 30 seconds to flavour the oil. Remove and discard garlic.","duration":0.5,"images":[],"step":3},{"description":"Add the Chinese broccoli stems and Shredded Chicken and stir fry for 1 1/2 minutes.","images":[],"step":4},{"description":"Add the noodles, braising liquid and Sriracaha (if using) and stir fry, tossing the noodles rapidly to coat with the sauce for about 1 minute. The sugar in the braising liquid should make the noodles char a bit.","images":[],"step":5},{"description":"Add the Chinese broccoli leaves and toss to mix in with the noodles, then remove from heat. The Chinese broccoli leaves will continue to cook from the residual heat.","images":[],"step":6},{"description":"Serve immediately.","images":[],"step":7}]', '["peanuts"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","chinese-recipes","dietary","gluten-free-recipes","most-popular","noodles","quick-and-easy","quick-dinner-ideas-15-minute-meals","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e3c745336ab5', 'en', 'US', 'Fish Piccata With Crispy Smashed Potatoes (15 Minute Meal)', 'It''s amazing what you can make in 15 minutes (from scratch) if you get a bit creative! Make this with fresh fish or good quality frozen fish. I made these with beans but I often make it with asparagus and broccolini. You can really use any vegetables you want as long as they cook quickly in a pan with just a bit of braising liquid.', 'https://www.recipetineats.com/tachyon/2014/10/Fish-Piccata-Smashed-Potatoes-Green-Beans-15-minutes.jpg', 5, 10, 15, 2, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_potato", "quantity": {"value": 6.0, "unit": "bag of 2kg"}}, {"id": "ing_green_beans", "quantity": {"value": 198.45, "unit": "pack"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_wine", "quantity": {"value": 0.111, "unit": "bottle of 750ml"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_baby_capers", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["2 pieces firm white fish fillets (around 150 - 200g / 5 - 7 oz each) (with or without skin, your choice) (see notes)","6 baby / chat / new potatoes (about the size of a golf ball) (see notes)","7 oz / 200 g green beans (, trimmed)","1 tbsp fresh parsley (, finely chopped)","2 tbsp olive oil","3 tbsp plain flour","1 tsp salt","Black pepper"]},{"ingredients":["1/3 cup white wine","1/2 cup water","1 - 2 tbsp fresh lemon juice (adjust to your taste)","2 tbsp butter","1 tbsp baby capers (canned)","Salt and pepper"],"purpose":"Sauce"}]', '[{"description":"Cook the potatoes in the microwave for 2 minutes, turn potatoes, then cook for another 1 1/2 - 2 minutes. You will be able to tell by squeezing them if they are ready. Don''t worry if the skin bursts, you are smashing them anyway.","duration":2,"images":[],"step":1},{"description":"Use the side of a knife, meat mallet or your hand (covered with a dish cloth) and smash each potato so they are flattened to around 1.5cm/ 0.5\" thick with a flattish surface. Sprinkle with a pinch of salt.","images":[],"step":2},{"description":"Meanwhile, combine flour, salt and pepper on a plate and dredge each side of the fish in the flour mixture. Shake off excess flour.","images":[],"step":3},{"description":"Heat olive oil in a non stick pan over high heat. Place fish and potatoes in the pan. Press the potatoes down lightly with a spatula to help it crisp up.","images":[],"step":4},{"description":"Cook the first side of both the fish and potatoes for around 2 minutes until golden brown, then turn. Make sure the potato is crispy and brown.","images":[],"step":5},{"description":"Cook the other side of the fish for 1 1/2 minutes (also see notes for fish cooking time). Then remove from the pan onto a plate and cover loosely with foil.","images":[],"step":6},{"description":"Give the potatoes another 30 seconds to 1 minute to make it nice and brown and crispy, then remove from the pan.","images":[],"step":7},{"description":"Turn heat down to medium high.","images":[],"step":8},{"description":"Add wine and water to the pan. Scrape the brown bits off the bottom of the pan and mix it in. When the liquid comes to a rapid simmer, add the beans.","images":[],"step":9},{"description":"Shake the pan occasionally to help the beans cook evenly. Cook the beans in the liquid for around 1 1/2 minutes until \"tender crisp\" (i.e. cooked but still crisp) and remove from pan. If the liquid reduces too much while cooking the beans (which might be the case if you are using a very large heavy based pan), just add a splash of water.","images":[],"step":10},{"description":"Remove pan from heat. By the time you remove the beans, there should just be a bit of sauce left at the bottom of the fry pan, not even covering the entire base of the fry pan.","images":[],"step":11},{"description":"Add lemon juice then stir through butter and capers. Adjust seasoning to taste with salt and pepper.","images":[],"step":12},{"description":"To Serve","images":[],"step":13},{"description":"Place half the beans on each plate and place 3 potatoes on top. Top with a piece of fish. Spoon over the Sauce onto each fish and scatter with parsley. Serve immediately.","images":[],"step":14}]', '["fish","gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":[],"categories":["dietary","dinner-tonight","fish-recipes","gluten-free-recipes","main-dishes","quick-and-easy","quick-dinner-ideas-15-minute-meals","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bc13dba95d36', 'en', 'US', 'Nachos Cheese Dip & Sauce', 'This dip is great not only because it''s a two-in-one recipe, but because unlike most other cheese dips and sauces, it does not separate and congeal as it cools and it is just as good (if not better) served cool or at room temperature as it is warm. It''s also a super simple recipe which takes minutes to prepare and only 5 or so minutes to cook.', 'https://www.recipetineats.com/tachyon/2014/10/Nachos-Cheese-Dip-and-Sauce.jpg', 2, 5, 7, 6, '[{"id": "ing_cheese", "quantity": {"value": 2.5, "unit": "block of 250g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.037, "unit": "pack of 400g"}}, {"id": "ing_milk", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.6, "unit": "jar of 50g"}}, {"id": "ing_hot_sauce", "quantity": {"value": 0.1, "unit": "bottle of 150ml"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2 1/2 cups / 225g / 8oz shredded cheese (Cheddar, Monterey Jack, Colby, etc), shred your own (Important - read Note 1)","1 tbsp cornstarch (corn flour)","1 can evaporated milk (375g / 12oz)","2 tbsp finely chopped jalapeño peppers (fresh or canned)","1 tbsp hot sauce (or adjust to your taste)","1/2 tsp onion powder (optional - adds extra flavour)","1/2 tsp garlic powder (optional - adds extra flavour)","1 tsp salt"]}]', '[{"description":"Toss the cheese and cornstarch together in a saucepan.","images":[],"step":1},{"description":"Add all other ingredients, cook over medium heat, whisking often until the cheese is melted and smooth.","images":[],"step":2},{"title":"Adjust to your taste if required","description":"with extra hot sauce and salt.","images":[],"step":3},{"title":"While hot, it will have a sauce like consistency","description":"perfect for pouring over nachos.","images":[],"step":4},{"description":"As it cools, it will thicken and become a dip-like consistency. Whisk occasionally to mix in the skin that forms on the top.","images":[],"step":5},{"description":"Stir in additional evaporated (or even normal) milk to achieve the desired consistency if you want to use it as a pourable sauce. Note that when you reheat it, it loosens up.","images":[],"step":6}]', '["gluten","milk"]', '["keto_friendly","low_calorie","vegetarian"]', '{"mealType":["snack"],"cuisine":["Tex-Mex"],"categories":["dietary","dip-recipes","gluten-free-recipes","mexican-recipes","most-popular","nachos-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ddd42fa8380f', 'en', 'US', 'Throw Together Salad #1: Rocket (Arugula), Beetroot, Walnuts and Feta w/Balsamic Dressing', 'The first in a series of Throw Together Salads that require little to no chopping. Budget friendly and quick to make! Serves 4 as a side or 2 as a light lunch.', 'https://www.recipetineats.com/tachyon/2014/09/Throw-Together-Salad-Rocket-Arugula-Beetroot-Walnut-Feta-Balsamic-Honey-Dressing-2.jpg', 5, 0, 5, 4, '[{"id": "ing_baby_beetroot", "quantity": {"value": 250.0, "unit": "unit"}}, {"id": "ing_baby_rocket", "quantity": {"value": 0.12, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_walnuts", "quantity": {"value": 45.0, "unit": "jar"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_balsamic_vinegar", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_honey", "quantity": {"value": 0.03, "unit": "jar of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["250 g / 8 oz canned baby beetroot (, halved or quartered if they are large)","120 g / 4 oz baby rocket ((arugula) leaves)","60 g feta ((preferably Danish, otherwise Greek), or goats cheese)","3 tbsp walnuts (, lightly crushed with your fingers)"]},{"ingredients":["2 1/2 tbsp extra virgin olive oil","1 tbsp balsamic vinegar (ordinary, not aged or glazed)","1 tbsp honey","1/2 tsp salt","Black pepper"],"purpose":"Dressing"}]', '[{"description":"Combine the Dressing ingredients in a jar, and shake well. You might need a spoon to break up the honey to mix it in properly. Adjust salt to your taste.","images":[],"step":1},{"description":"Place rocket lettuce in a serving bowl.","images":[],"step":2},{"title":"Scatter over beetroot. No need to toss","description":"because of the weight, it should disperse throughout fairly well.","images":[],"step":3},{"description":"Crumble over the feta and scatter with walnuts.","images":[],"step":4},{"description":"Drizzle over dressing and serve.","images":[],"step":5}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["lunch"],"cuisine":[],"categories":["all-vegetable-sides","dietary","easter-sides-fresh-light","gluten-free-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","rocket-arugula","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_fb7b30a3a2c7', 'en', 'US', 'Ham and Cheese French Toast Roll Ups', 'French toast you can eat with your fingers and taste just like ham and cheese toasties! This would also be great made with bacon or smoked salmon instead of ham.', 'https://www.recipetineats.com/tachyon/2014/10/Ham-and-Cheese-Fresh-Toast-Roll-Up-1.jpg', 10, 5, 15, 2, '[{"id": "ing_bread", "quantity": {"value": 0.3, "unit": "loaf"}}, {"id": "ing_cheese", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_ham", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["6 slices fresh sandwich bread (I used white, but you could use wholemeal, wholegrain etc) (see notes)","3 slices of melting cheese","1 tbsp butter","1 egg (large)","2 tbsp milk (full cream or low fat)","2 small slices of ham (around 50g / 1.5 oz)","Pinch of salt"]}]', '[{"title":"Optional","description":"cut the crusts off the bread.","images":[],"step":1},{"description":"Use a rolling pin to flatten the bread.","images":[],"step":2},{"description":"Divide the ham between the bread and lay it out in a strip about 1cm / 1/3\" wide along the bottom edge of the bread. Cut to fit neatly if necessary - that''s what I did.","images":[],"step":3},{"description":"Top each with 2 slices of cheese, or scatter grated cheese along the ham.","images":[],"step":4},{"description":"Starting from the bottom, roll the bread up and finish with the seam side down.","images":[],"step":5},{"description":"Place the egg, milk and salt in a flat dish and use a fork to whisk.","images":[],"step":6},{"description":"Heat butter in a large fry pan over medium high heat.","images":[],"step":7},{"description":"Dip the roll ups in the egg, rolling to coat all over. Then place in the fry pan. Place all roll ups in the same pan.","images":[],"step":8},{"description":"Cook the roll ups for 45 seconds to 1 minute, then turn 90 degrees. Repeat again 2 more times (so 4 sides of each roll up is browned).","duration":0.75,"images":[],"step":9},{"description":"Remove from pan and serve immediately.","images":[],"step":10}]', '["egg","gluten","milk"]', '["low_calorie"]', '{"mealType":["breakfast"],"cuisine":[],"categories":["breakfast-recipes","leftover-ham-recipes","most-popular","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_12e89ad9167d', 'en', 'US', 'Lemon Pepper Pork', 'A complete meal on the table in just 15 minutes! Made from scratch, so fresh and easy.', 'https://www.recipetineats.com/tachyon/2014/09/Lemon-Pepper-Pork-Grilled-Veg-Feta-Couscous-4.jpg', 5, 10, 15, 2, '[{"id": "ing_pork", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.3, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_zucchini", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_mint", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_couscous", "quantity": {"value": 75.0, "unit": "pack"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_cheese", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.3, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}]', '[{"ingredients":["2 pork cutlets (, at room temperature (200g/7oz each, bone in) (see notes))","1 tbsp lemon pepper (see notes)","2 tbsp olive oil (, separated)","2 zucchinis (, sliced)","1 small red capsicum ((bell pepper), sliced)","1 small red onion ((spanish onion), sliced)","1/2 small lemon","1/4 cup mint leaves (loosely packed)","1/2 cup couscous","1/2 cup boiling water (or chicken or vegetable stock/broth)","50 g / 1.5 oz g / 1.5 oz feta cheese","Salt and pepper","Lemon wedges or cheeks (, to serve (optional))"]}]', '[{"description":"Combine couscous and boiling water in a bowl, cover with cling wrap and set aside for 5 minutes.","duration":5,"images":[],"step":1},{"description":"Sprinkle lemon pepper on both sides of each cutlet and pat to make it stick.","images":[],"step":2},{"description":"Heat 1 tbsp olive oil in fry pan over high heat. Place pork in fry pan and cook the first side for 2 minutes and the second side for 1 1/2 minutes or until cooked to your liking. I like mine medium rare. Remember the pork will continue to cook while resting.","duration":2,"images":[],"step":3},{"description":"Remove pork from the fry pan onto a plate, cover loosely with foil and set aside to rest.","images":[],"step":4},{"description":"Heat remaining 1 tbsp olive oil in the fry pan still on high heat. Add onion and capsicum and sauté for 1 minute, then add the zucchini. Stir and cook the vegetables until charred and just cooked through. Remove pan from heat.","duration":1,"images":[],"step":5},{"description":"Fluff up the couscous with a fork. Add the vegetables and mint leaves. Squeeze over a drizzle of lemon juice and season to taste with salt and pepper. Toss gently to combine.","images":[],"step":6},{"description":"Divide couscous between plates, scatter over feta cheese. Top with pork cutlet and drizzle over resting juices. Serve with lemon cheeks or wedges on the side, if using.","images":[],"step":7}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dietary","dinner-tonight","gluten-free-recipes","grilling-ideas-and-recipes","main-dishes","pork-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ab018d3a384c', 'en', 'US', 'Chicken Marsala', 'Recipe video above. A beloved Italian-American classic comprised of a crispy golden chicken cutlet smothered in a rich Marsala wine flavoured mushroom sauce. A restaurant favourite that''s easy to make at home, one bite and you''ll be hooked for life like I was!The key flavour here is Marsala wine so if you can''t consume alcohol or don''t have it, make Chicken in Creamy Mushroom Sauce instead! Also, this dish uses more alcohol than my usual "just a splash of wine" so it''s not recommended for kids. :)', 'https://www.recipetineats.com/tachyon/2023/06/Chicken-Marsala_0b.jpg', 10, 15, 25, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_eschalots", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_mushroom", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.333, "unit": "bottle of 750ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["2 large chicken breasts (300g/10oz each), cut in half horizontally (or 4 thighs, Note 1)","1/2 tsp cooking salt / kosher salt","1/2 tsp black pepper","1/4 cup flour (, plain/all-purpose)"],"purpose":"Golden crusted chicken:"},{"ingredients":["2 tbsp extra virgin olive oil","2 tbsp / 30g unsalted butter","2 eschalots (US: shallots), peeled and cut into 1cm / 1/3\" squares (Note 2)","1 garlic (, finely minced)","2 cups white mushrooms (, sliced 0.5cm / 1/5\" thick)","1 cup dry marsala wine (Note 3)","1/2 cup chicken stock/broth (, low sodium)","1/2 cup thickened / heavy cream ( (Note 4))","1/4 tsp cooking salt / kosher salt","1/8 tsp black pepper","1 tbsp finely chopped parsley (, for garnish (optional))"],"purpose":"Marsala sauce:"}]', '[{"description":"Chicken escalopes:","images":[],"step":1},{"title":"Pound","description":"Cut each breast in half to form 2 thin steaks. Cover with a freezer bag or Go-Between (Note 5) and pound to 1 cm / 0.4″ thickness using a meat mallet or rolling pin. This tenderises and ensures even cooking of the chicken.","images":[],"step":2},{"title":"Dust","description":"Sprinkle the surface with half the salt, pepper then flour. Lightly rub flour across surface, turn and repeat with remaining salt, pepper and flour. Shake excess flour off each piece just before cooking.","images":[],"step":3},{"title":"Cook","description":"Put half the butter and oil in a large non-stick pan over medium high heat. Once the butter is melted and foamy, place chicken in, then cook for 3 to 4 minutes until it''s gorgeously golden and crispy. Turn and cook the other side for 2 minutes. Remove onto a plate.","duration":3.5,"images":[],"step":4},{"description":"Creamy marsala sauce:","images":[],"step":5},{"title":"Sauté aromatics","description":"In the same pan, add remaining butter and oil. Once butter is melted, add eschalots and garlic. Cook for 1 minute.","duration":1,"images":[],"step":6},{"title":"Cook mushrooms","description":"Add mushrooms. Cook for 3 minutes, stirring regularly.","duration":3,"images":[],"step":7},{"title":"Reduce marsala","description":"Add marsala, turn up heat to high and boil for 3 minutes or until reduced by half.","duration":3,"images":[],"step":8},{"title":"Thicken sauce","description":"Add chicken stock, cream, salt and pepper. Stir, then lower heat so it''s simmering (not boiling rapidly) and simmer for 3 to 5 minutes until the sauce thickens to a cream consistency (not too thick, will thicken more).","duration":4,"images":[],"step":9},{"title":"Rewarm chicken","description":"Nestle chicken into sauce and leave for 30 seconds to reheat.","duration":0.5,"images":[],"step":10},{"description":"Serve! Take off the stove. Sprinkle with parsley, serve over starchy vehicle of choice (I chose mash. Rice, small pasta, polenta or bread for plate mopping also work well!).","images":[],"step":11}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian","Italian-American"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5862af867b74', 'en', 'US', 'Balsamic Glazed Beetroot', 'Transform a can of beetroot into an elegant side dish with just 2 ingredients and 5 minutes. Or if you really want to up the stakes, make this with fresh beetroot!', 'https://www.recipetineats.com/tachyon/2014/09/Balsamic-Glazed-Beetroot-2.jpg', 5, 5, 10, 4, '[{"id": "ing_baby_beetroot", "quantity": {"value": 450.0, "unit": "unit"}}, {"id": "ing_balsamic_vinegar", "quantity": {"value": 0.5, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}]', '[{"ingredients":["450 g / 15 oz can (drained) baby beetroot (beets) OR fresh baby beetroot (about 10)","1/2 cup balsamic vinegar (any quality is fine)","3 tbsp brown sugar","1 tsp thyme leaves (optional)"]}]', '[{"description":"To Cook Fresh Beetroot","images":[],"step":1},{"description":"To cook fresh beetroot, bring a pot of water to boil, then place beetroot in the water and cook for 10 minutes until tender.","duration":10,"images":[],"step":2},{"description":"Drain beetroot, allow to cool to handle and peel off the skin (either with a teaspoon or vegetable peeler).","images":[],"step":3},{"description":"Combine balsamic vinegar and sugar in a small frying pan or saucepan over medium high heat.","images":[],"step":4},{"description":"Bring to simmer and cook, stirring, for 3 to 5 minutes until thickened and syrupy.","duration":4,"images":[],"step":5},{"description":"Remove from heat.","images":[],"step":6},{"description":"Cut larger beetroots into bite size pieces, either into halves or quarters.","images":[],"step":7},{"description":"Toss into balsamic glaze and sprinkle in thyme leaves, if using.","images":[],"step":8},{"description":"Serve slightly warm or at room temperature.","images":[],"step":9}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["easter-sides-warm-hearty","quick-and-easy","quick-dinner-ideas-15-minute-meals","side-dishes","side-salads","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_fbe5d34eefa2', 'en', 'US', 'Sticky Chicken With Vegetable Fried Rice', 'The sticky chicken is the star of this quick mid week meal which can be largely made ahead. Add whatever vegetables you want to the fried rice. The vegetables I used were the ones I happened to have. Note: The recipe says to cook 1 cup of rice which yields 3 cups of cooked rice. But you will only need 1 1/2 cups of cooked rice. The reason I have done it this way is because I find it is quite difficult to cook less than 1 cup of uncooked rice. The rice tends to be undercooked if you cook a small amount because too much steam escapes, and by the time the rice at the top is cooked the bottom is burnt.', 'https://www.recipetineats.com/tachyon/2014/09/Sticky-Chinese-Chicken-Fried-Rice-2.jpg', 10, 10, 20, 2, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_honey", "quantity": {"value": 0.045, "unit": "jar of 500g"}}, {"id": "ing_ginger", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_sriracha", "quantity": {"value": 0.037, "unit": "bottle of 400ml"}}, {"id": "ing_rice", "quantity": {"value": 15.0, "unit": "pack"}}, {"id": "ing_water", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_rice", "quantity": {"value": 15.0, "unit": "pack"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_frozen_peas", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_corn", "quantity": {"value": 0.188, "unit": "can of 400g"}}, {"id": "ing_bok_choy", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}]', '[{"ingredients":["250g (8oz) chicken thigh fillets (, sliced into 1cm/1/3\" slices)","2 tbsp soy sauce","2 tbsp tomato sauce","1 tbsp rice vinegar","1 1/2 tbsp honey (or substitute with 1 tbsp brown sugar)","1/2 tsp fresh ginger (, minced or finely chopped)","1 clove garlic (, minced)","1 tbsp sriracha (or other hot sauce) (optional)"],"purpose":"Chicken & Marinade (Make Ahead)"},{"ingredients":["1 cup long grain rice (, uncooked (see notes))","1 1/2 cups water"],"purpose":"Rice (Make Ahead) (see notes)"},{"ingredients":["1 1/2 cups cooked rice (see notes)","1/2 brown or white onion (, diced)","1 garlic clove (, peeled and smashed (see notes))","1 carrot (, diced)","1/2 cup frozen peas (, thawed)","1/2 cup baby corn (, cut into 1cm/1/3\" slices (or canned or frozen corn) (see notes))","3 bok choys","1 1/2 tbsp peanut oil (, separated)","1 tbsp Chinese cooking wine ((shao hsing wine) or dry sherry)","1 tbsp soy sauce","1 tsp chicken stock powder or crumbled bouillon cube (, or 1/2 tsp salt)"],"purpose":"Fried Rice"},{"ingredients":["1 shallot/scallion (, finely sliced)","1 tsp sesame seeds (optional)"],"purpose":"Garnish"}]', '[{"description":"Make Ahead Preparation","images":[],"step":1},{"description":"Combine Chicken and Marinade ingredients in a bowl and mix to coat. Either set aside for 20 minutes or put it in a ziplock bag and place in the freezer until required.","duration":20,"images":[],"step":2},{"description":"Place rice and water in a medium saucepan. Bring to boil, then turn down heat to low and simmer until all the water is absorbed (8 to 10 minutes). Remove from heat and allow to rest for 10 minutes. Remove lid and allow to cool. Divide into two freezer bags - about 1 1/2 cups per bag. You will only use one bag for the meal. Then place in ziplock bag or container and put it in the freezer.","duration":10,"images":[],"step":3},{"description":"If you want to go the extra step, you could also cut and measure out the carrots, peas and corn and put them in a freezer bag too. I tend not to bother because this does not take long to do and also, you need to cut the onion fresh anyway.","images":[],"step":4},{"description":"To Cook","images":[],"step":5},{"description":"Remove chicken and rice from the freezer and allow to defrost.","images":[],"step":6},{"description":"Cut the stems off the leaves of the bok choy. Cut the stems vertically into 1cm/1/3\" thick sticks.","images":[],"step":7},{"description":"Heat wok or fry pan over high heat. Add sesame seeds and toast for 15 seconds, then remove.","duration":0.25,"images":[],"step":8},{"description":"Heat 1 tbsp oil in wok, add garlic and stir fry for 20 seconds to flavour the oil. Remove garlic and discard.","duration":0.3333333333333333,"images":[],"step":9},{"description":"Add onion and stir fry for 30 seconds.","duration":0.5,"images":[],"step":10},{"description":"Add carrot, peas and corn and stir fry for another 30 seconds.","images":[],"step":11},{"description":"Add the bok choy stems, cook for 30 seconds.","duration":0.5,"images":[],"step":12},{"description":"Add the rice, cooking wine, soy sauce and stock powder and stir fry for another 30 seconds.","images":[],"step":13},{"description":"Remove wok from heat, then add the bok choy leaves and stir quickly to mix them into the rice. Remove fried rice from wok into large bowl.","images":[],"step":14},{"description":"Add 1/2 tbsp oil to wok and return to stove, still on high heat.","images":[],"step":15},{"description":"Remove chicken from marinade (reserve marinade) and place in the wok and stir fry for 1 1/2 minutes until nicely browned but not quite cooked through. Then add the remaining marinade into the wok with 2 tbsp water and allow to cook for 30 seconds until it becomes thick and syrupy. Remove from heat.","duration":0.5,"images":[],"step":16},{"description":"Place fried rice into bowls and top with the sticky chicken. Scatter with shallots/scallions and sesame seeds.","images":[],"step":17}]', '["gluten","peanuts","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","rice-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8d9f99185259', 'en', 'US', 'No Washing Up Ham, Egg & Cheese Bread Bowls', 'A great "no washing up" breakfast idea that''s perfect for feeding a crowd because you can make ahead and cook a lot at the same time. Recipe video below!', 'https://www.recipetineats.com/tachyon/2014/09/No-Washing-Up-Ham-Egg-Cheese-Bread-Bowls-1.jpg', 5, 15, 20, 4, '[{"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_ham", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 4.0, "unit": "carton of 12"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.4, "unit": "pack of 125g"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["4 bread rolls (soft or crusty)","4 small slices of ham (, or 2 big ones cut in half)","4 eggs (, at room temperature)","1/2 cup shredded mozzarella cheese","1 tbsp fresh parsley (, finely chopped (optional))"]}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Cut the tops off the bread rolls.","images":[],"step":2},{"description":"Scoop out the centre and reserve (see notes for ideas to use). To be neat, use a small knife to cut a round outline before scooping out the centre.","images":[],"step":3},{"description":"Line the bread bowl with a layer of ham. Try to use one whole piece if you can because then there is less chance of egg seeping through and being soaked up by the bread.","images":[],"step":4},{"description":"Crack in an egg.","images":[],"step":5},{"description":"Top each with 2 tbsp of mozzarella cheese and a sprinkle of parsley (optional).","images":[],"step":6},{"description":"Put the top back on each roll. Wrap with foil and place in oven to bake for ~15 to 25 minutes. Take a peek at 20 minutes to check them. 20 minutes = runny yolks. 25 minutes + = just cooked yolks. (See notes for more information)","images":[],"step":7},{"description":"Remove from oven, unwrap and serve immediately.","images":[],"step":8}]', '["egg","gluten","milk"]', '[]', '{"mealType":["breakfast"],"cuisine":[],"categories":["australia-day","breakfast-recipes","dinner-tonight","egg-recipes","leftover-ham-recipes","main-dishes","most-popular","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0499e965d877', 'en', 'US', 'Cinnamon Sugar Bread Crust Treats', 'This is how you get kids - big or small - to eat their bread crusts! Tastes like cinnamon doughnuts - only crunchy and a whole lot healthier!', 'https://www.recipetineats.com/tachyon/2014/08/Cinnamon-Sugar-Breadcrust-Treats-2.jpg', 2, 8, 10, 6, '[{"id": "ing_bread", "quantity": {"value": 1.125, "unit": "loaf"}}, {"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_cinnamon", "quantity": {"value": 5.0, "unit": "jar"}}]', '[{"ingredients":["6 cups bread crusts ((enough to spread out over 2 baking trays), preferably stale)","60 g / 2 oz / 4 tbsp butter (, melted)","5 tbsp sugar (separate 1 tbsp)","1 tsp cinnamon"]}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Cut crusts into 3cm/1.5\" pieces.","images":[],"step":2},{"description":"Place bread crusts in a large bowl. Drizzle over butter, tossing the bread crusts as you go (with your other hand) to evenly distribute as best as possible.","images":[],"step":3},{"description":"Sprinkle over 4 tbsp of sugar and cinnamon, and toss through.","images":[],"step":4},{"description":"Spread out over 2 baking trays.","images":[],"step":5},{"description":"Bake for 5 to 8 minutes until golden brown and crunchy (check the ones in the middle of the tray). The tray on the top shelf will be ready first. The bottom tray will take a couple of minutes longer.","duration":6.5,"images":[],"step":6},{"description":"While hot, sprinkle over the remaining 1 tbsp of sugar (1/2 tbsp over each tray). This is mainly for appearance purpose.","images":[],"step":7}]', '["gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["snack"],"cuisine":[],"categories":["baking-recipes","bite-size-desserts","dessert-recipes","most-popular","quick-and-easy","quick-dinner-ideas-15-minute-meals","snacks"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9bb071c80b13', 'en', 'US', 'Greek Lamb and Salad Dinner', 'A super quick Greek dinner!', 'https://www.recipetineats.com/tachyon/2014/08/Greek-lamb-salad-dinner-4.jpg', 10, 5, 15, 4, '[{"id": "ing_beef_steak", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_tomato", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.5, "unit": "pack of 3 heads"}}, {"id": "ing_cheese", "quantity": {"value": 0.25, "unit": "block of 250g"}}, {"id": "ing_olives", "quantity": {"value": 16.0, "unit": "bottle"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 0.4, "unit": "loaf"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.075, "unit": "net of 500g"}}, {"id": "ing_honey", "quantity": {"value": 0.02, "unit": "jar of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.5, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["600 g / 20 oz lamb steaks (4 pieces in total)","2 large cucumbers","4 medium tomatoes","1 red onion (spanish onion)","1/2 cup (combined) parsley and mint leaves","1/2 small garlic clove","1/4 cup crumbled feta cheese","16 olives (black or green)","2 tsp dried oregano","8 slices sourdough bread","Salt and pepper"]},{"ingredients":["1/2 cup extra virgin olive oil","1/4 cup lemon juice","2 tsp honey","1/2 garlic clove (, minced)","1 tsp salt","Black pepper"],"purpose":"Dressing"}]', '[{"description":"Combine the Dressing ingredients and mix well (or put in a jar and shake).","images":[],"step":1},{"description":"Pour 1/4 cup of the Dressing, dried oregano, and a pinch of salt and pepper onto the lamb steaks and use your hands to coat evenly.","images":[],"step":2},{"title":"To freeze","description":"Place the lamb and marinade in a ziplock bag, remove as much air as possible and freeze. To cook, defrost completely and bring back to room temperature.","images":[],"step":3},{"description":"Heat BBQ (grill) or a heavy based pan on the stove over high heat.","images":[],"step":4},{"description":"Remove lamb from marinade. Place lamb on BBQ (or in the pan) and grill each side for 1 to 1 1/2 minutes, or until cooked to your liking. Remove lamb steaks from the BBQ / pan onto a plate and cover loosely with foil to rest.","images":[],"step":5},{"description":"Cut cucumber vertically into 8 pieces.","images":[],"step":6},{"description":"Cut tomatoes into thick slices.","images":[],"step":7},{"description":"Peel red onion and slice finely.","images":[],"step":8},{"description":"Toast bread, either in the toaster or on the BBQ/grill. While still warm, rub lightly with the cut side of the garlic. Optional: drizzle with extra olive oil.","images":[],"step":9},{"description":"Slice lamb into thin slices.","images":[],"step":10},{"description":"Place 4 slices of cucumber on each plate and top with tomato slices, red onion and olives.","images":[],"step":11},{"description":"Place lamb on top, sprinkle over the feta, parsley and mint leaves.","images":[],"step":12},{"description":"Drizzle over Dressing and serve with toasted bread on the side.","images":[],"step":13}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Greek"],"categories":["dinner-tonight","greek-recipes","grilling-ideas-and-recipes","lamb-recipes","main-dishes","mediterranean-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_095f2e0c6f41', 'en', 'US', 'Parmesan Thyme Bread Crust Snacks', 'An irresistible snack invented when my freezer stockpile of bread crusts became out of control. This is how you get kids - big and small - to eat their bread crusts!', 'https://www.recipetineats.com/tachyon/2014/08/Parmesan-Thyme-Breadcrust-4.jpg', 2, 8, 10, 6, '[{"id": "ing_bread", "quantity": {"value": 1.125, "unit": "loaf"}}, {"id": "ing_olive_oil", "quantity": {"value": 7.0, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}, {"id": "ing_thyme", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_thyme", "quantity": {"value": 0.15, "unit": "bunch"}}]', '[{"ingredients":["6 cups bread crusts ((enough to spread out over 2 baking trays), preferably stale)","7 - 8 tbsp olive oil","1/3 cup parmesan cheese (, grated)","1 1/2 tsp dried thyme","1/2 tsp salt (or to taste)","Black pepper","Optional - fresh thyme to garnish"]}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Place bread crusts in bowl. Drizzle over olive oil, tossing the bread crusts as you go (with your other hand) so as to distribute the olive oil as evenly as possible.","images":[],"step":2},{"description":"Add remaining ingredients and use hands to toss through the bread crusts.","images":[],"step":3},{"description":"Spread out over 2 baking trays. Do a taste test to make sure it is seasoned to your liking - adjust if required.","images":[],"step":4},{"description":"Bake for 5 to 8 minutes until golden brown and crunchy (check the ones in the middle of the tray). The tray on the top shelf will be ready first. The bottom tray will take a couple of minutes longer.","duration":6.5,"images":[],"step":5}]', '["gluten","milk"]', '["keto_friendly","low_calorie","vegetarian"]', '{"mealType":["snack"],"cuisine":[],"categories":["quick-and-easy","quick-dinner-ideas-15-minute-meals","snacks","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2bee32ba8dcb', 'en', 'US', 'Giant Pancakes', 'This is how you make pancakes for 4 people in 10 minutes.', 'https://www.recipetineats.com/tachyon/2014/08/Giant-Pancake-3.jpg', 5, 10, 15, 4, '[{"id": "ing_flour", "quantity": {"value": 0.375, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.167, "unit": "tub of 150g"}}, {"id": "ing_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_vanilla_essence", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_strawberries", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_golden_syrup", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sugar", "quantity": {"value": 0.045, "unit": "kg"}}]', '[{"ingredients":["2 1/2 cups plain flour *","5 tsp baking powder *","3 tbsp sugar","1/2 tsp salt","1 tsp vanilla essence","1 egg","2 cups + 2 tbsp milk","1 tsp butter"]},{"ingredients":["Sliced strawberries","Golden syrup","Icing sugar"],"purpose":"To Serve"}]', '[{"description":"Combine flour, baking powder, sugar and salt in a bowl and mix briefly with a whisk to combine.","images":[],"step":1},{"description":"Add vanilla essence, egg and milk. Whisk until lump free.","images":[],"step":2},{"description":"Heat butter in non stick pan (25cm/10\" diameter) over medium high heat. Use an egg flip to spread the butter all over the pan.","images":[],"step":3},{"description":"Use a paper towel to wipe the butter of the pan thoroughly.","images":[],"step":4},{"description":"Pour half the batter in the pan and swirl around to evenly cover the base of the pan.","images":[],"step":5},{"description":"Cook until lots of bubbles appear on the surface. Lift up the edge and peer underneath - if it is golden, it is ready to flip. About 2 minutes.","images":[],"step":6},{"description":"Flip the pancake and cook the other side for 1 1/2 to 2 minutes. The other side will not take as long to cook.","images":[],"step":7},{"description":"Remove from pan and repeat with remaining batter. You will not need to put butter in the pan again.","images":[],"step":8},{"title":"To serve (optional)","description":"top with slices of strawberries and a sprinkling of icing sugar with golden syrup on the side.","images":[],"step":9}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["breakfast"],"cuisine":[],"categories":["breakfast-recipes","dessert-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d13adc526917', 'en', 'US', 'Beef Cheek Ragu Pasta', 'Made with leftover Slow Cooked Beef Cheeks in Red Wine, this pasta part of a series where leftovers are transformed into 2 sensational meals. Using leftover beef cheeks, this luscious pasta is on the table in 15 minutes.', 'https://www.recipetineats.com/tachyon/2014/08/Beef-Cheeks-Pasta-1.jpg', 5, 10, 15, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.7, "unit": "pack of 500g"}}, {"id": "ing_beef_cheeks", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_beef_cheeks", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["350 g / 12 oz dried spaghetti","2 cups leftover beef from Slow Cooked Beef Cheeks in Red Wine (, shredded)","1 cup Sauce of Slow Cooked Beef Cheeks in Red Wine","1 onion ((brown, white or yellow), diced)","2 garlic cloves (, minced)","2 tbsp olive oil","2 cups crushed tomato (canned)","3 tbsp tomato paste","1/2 cup water","1 to 2 tsp salt (adjust to taste)","Black pepper"]},{"ingredients":["Freshly grated parmesan cheese","Parsley (, finely chopped)"],"purpose":"To Serve"}]', '[{"description":"Bring a large pot of salted water to boil. Add pasta and cook for 6 minutes or until just before al dente (i.e. slightly undercooked, very firm to touch). The pasta will be cooked more in the pasta sauce.","duration":6,"images":[],"step":1},{"description":"Meanwhile, heat olive oil in large pan over medium high heat. Add onion and garlic and sauté for 3 minutes.","duration":3,"images":[],"step":2},{"description":"Add remaining ingredients. Bring to rapid simmer, stirring occasionally. Adjust seasoning with salt and pepper. If the sauce seems too thick, add a splash of the pasta cooking water.","images":[],"step":3},{"description":"Use tongs and transfer the pasta straight from the pot of boiling water into the pan with the ragu sauce. Add 1/2 cup of pasta cooking water and gently toss the pasta in the sauce for 1 to 2 minutes. The pasta is ready when the spaghetti is al dente (cooked but slightly firm to touch) and the sauce has thickened and is tossed through the pasta.","duration":1.5,"images":[],"step":4},{"description":"Serve immediately, sprinkled with freshly grated parmesan cheese and parsley if desired.","images":[],"step":5}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["beef-recipes","italian-recipes","most-popular","pasta-recipes","quick-dinner-ideas-15-minute-meals","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6d73364fa63b', 'en', 'US', 'Hummus with Lamb', 'Hummus topped with aromatic lamb mince. A starter or a small meal, this is a show stopper hummus. If you haven''t tried this before, you''re in for a real treat! This recipe makes 2 starter size plates (double what you see in the photo).', 'https://www.recipetineats.com/tachyon/2014/08/Hummus-with-Lamb-1.jpg', 10, 5, 15, 8, '[{"id": "ing_lamb", "quantity": {"value": 0.227, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_cumin", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_paprika", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.016, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.063, "unit": "can of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_tahini", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_pine_nuts", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["8 oz / 250 g ground lamb (mince)","1/2 brown onion (, finely diced)","1 tbsp olive oil","1/2 tsp cumin powder","1/2 tsp coriander powder","1/2 tsp paprika powder","1/8 tsp cinnamon powder","1/4 tsp black pepper","1 tsp salt"],"purpose":"Spiced Lamb"},{"ingredients":["15 oz / 400 g tin chickpeas (, drained)","1/4 cup water","1 garlic clove","Juice of ½ a small lemon","2 tbsp tahini (sesame paste)","2 tbsp extra virgin olive oil","Salt and pepper"],"purpose":"Hummus"},{"ingredients":["1 tbsp pine nuts","1 tbsp parsley (, finely chopped)","Extra virgin olive oil (for drizzling)"],"purpose":"Garnishes"}]', '[{"description":"Place a pan over medium high heat. Add pine nuts and toast until golden. Remove pine nuts from pan and set aside.","images":[],"step":1},{"description":"Return pan to stove (still on medium high heat) and add olive oil.","images":[],"step":2},{"description":"Add onion and cook until translucent (2 minutes). Then turn up the heat to high, add mince, spices and salt. Cook, breaking up the mince into small pieces, until browned and cooked through (3 minutes).","images":[],"step":3},{"description":"Set aside and cover so it doesn''t dry out. Bring it to room temperature.","images":[],"step":4},{"description":"Place all ingredients except salt in a food processor or blender and process until smooth.","images":[],"step":5},{"description":"Taste before adding salt and pepper. Different brands of chick peas have different levels of saltiness. Also adjust acidity with lemon juice, if required.","images":[],"step":6},{"description":"Use water to adjust the consistency to a tomato sauce (ketchup) like consistency. This consistency is \"proper\" hummus. In the Middle East, hummus is not the thick consistency that is typical of store bought hummus in Western countries, it is thinner.","images":[],"step":7},{"description":"Spread hummus on a plate, using the back of a spoon to create \"swirls\".","images":[],"step":8},{"description":"Top with lamb mince, scatter over the pine nuts and sprinkle with parsley. Finish with a drizzle of olive oil.","images":[],"step":9},{"description":"Serve with pita bread.","images":[],"step":10}]', '["sesame"]', '["gluten_free","low_calorie"]', '{"mealType":["snack"],"cuisine":["Middle Eastern"],"categories":["cuisines","lamb-recipes","lentil-recipes","middle-eastern-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f8fb984abbf2', 'en', 'US', 'Vietnamese Pork Chop', 'Pork is probably the most widely used meat in Vietnam. This lemongrass marinade is perfect for a pork cutlet to cook on the outdoor grill.', 'https://www.recipetineats.com/tachyon/2014/08/Vietnamese-Pork-Cutlets-1.jpg', 5, 10, 15, 4, '[{"id": "ing_pork", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_lime", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_lemongrass", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["4 pork cutlets (, around 250g - 300g (8oz - 10oz) each)","1 tbsp vegetable or peanut oil (for cooking)"]},{"ingredients":["1 tsp chilli sauce ((sriracha, chilli paste) or 1 birds eye chilli, finely chopped)","2 cloves minced garlic","Juice of 1 lime","2 tbsp fish sauce","1 tbsp soy sauce","1 1/2 tbsp brown sugar","1 stalk lemongrass (, white part only, bruised them sliced into 1cm/0.5\" pieces)"],"purpose":"Marinade"}]', '[{"description":"Place the Marinade ingredients in a ziplock bag and massage the bag to mix the ingredients.","images":[],"step":1},{"description":"Add pork to the Marinade and massage the bag to coat all the cutlets with the Marinade.","images":[],"step":2},{"description":"Marinate for at least 4 hours, up to 24 hours.","images":[],"step":3},{"description":"Brush the outdoor grill with oil and heat to medium high (or pan on a stove).","images":[],"step":4},{"description":"Remove pork from the marinade.","images":[],"step":5},{"description":"Place pork on the grill and cook each side for 2 minutes, or until cooked (depends on thickness of the cutlets). Remember that it will continue to cook while resting.","duration":2,"images":[],"step":6},{"description":"Remove pork from the grill onto a plate and cover loosely with foil. Rest for 5 minutes before serving.","duration":5,"images":[],"step":7}]', '["fish","gluten","peanuts","soy"]', '["low_calorie"]', '{"mealType":["main_course"],"cuisine":["Asian","Vietnamese"],"categories":["asian-recipes","grilling-ideas-and-recipes","pork-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_edfc828dc1b8', 'en', 'US', 'Jam Jelly Doughnut French Toast', 'French toast dressed up as a strawberry jam jelly doughnut! At 230 calories per serving it''s so much healthier than Krispy Creme. And remember, it''s french toast, so you can have dessert for breakfast!', 'https://www.recipetineats.com/tachyon/2014/08/Jam-Jelly-Doughnut-1.jpg', 10, 5, 15, 3, '[{"id": "ing_bread", "quantity": {"value": 0.3, "unit": "loaf"}}, {"id": "ing_strawberries", "quantity": {"value": 0.18, "unit": "punnet of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}]', '[{"ingredients":["6 slices white sandwich bread (, stale, 1.5cm/0.6\" thick (see notes))","3 tbsp strawberry jam","3 tbsp caster sugar","1 egg","2 tbsp milk","2 tbsp butter"]}]', '[{"title":"Optional","description":"Cut the bread into rounds, as large as you can. See notes for tip.","images":[],"step":1},{"description":"Spread 1 tbsp of strawberry jam into the middle of 3 of the rounds, leaving an edge of about 1cm / 1/4\" so when you put the sandwich together, the jam does not ooze out of the side. (See photo below) Put sandwich together.","images":[],"step":2},{"description":"Place egg and milk in a small bowl and beat lightly.","images":[],"step":3},{"description":"Spread sugar on a small plate.","images":[],"step":4},{"description":"Heat butter in large non stick pan over medium high heat.","images":[],"step":5},{"description":"Quickly dip each side of a sandwich into the egg mixture, then roll the edge in the egg mixture as well. Then place in the pan. Repeat with remaining sandwiches.","images":[],"step":6},{"description":"Cook each side for around 2 minutes, until a deep golden brown.","images":[],"step":7},{"description":"Remove from the pan and immediately place on the plate with the sugar to coat each side and the edges. The faster you get it from the pan into the sugar, the better the sugar will stick.","images":[],"step":8},{"description":"Serve warm or at room temperature.","images":[],"step":9}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["breakfast","dessert"],"cuisine":[],"categories":["breakfast-recipes","dessert-recipes","most-popular","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_da363a94f1d3', 'en', 'US', 'Pea, Cabbage, Parmesan and Mint Salad', 'This is one of those salads where it only takes one bite to know that you could eat the entire bowl yourself as a meal instead of sharing it between 4 as a side. Adapted from a recipe by Karen Martini, a great Australian chef.', 'https://www.recipetineats.com/tachyon/2014/07/Pea-Cabbage-Parmesan-and-Mint-Salad-1.jpg', 10, 0, 10, 4, '[{"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_cabbage", "quantity": {"value": 9.0, "unit": "head"}}, {"id": "ing_mint", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_radishes", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1 cup frozen peas (, blanched)","3 cups green or white cabbage (, finely sliced)","1/2 cup mint leaves (loosely packed)","1/2 cup parsley leaves (loosely packed)","4 radishes (, finely sliced)","1/3 cup parmesan","2 tbsp lemon juice","3 tbsp extra virgin olive oil","1/4 tsp salt","Black pepper"]}]', '[{"description":"Reserve 1 tbsp of the parmesan cheese as garnish.","images":[],"step":1},{"description":"Place all ingredients in a bowl and toss gently to combine.","images":[],"step":2},{"description":"Allow to sit for 5 minutes to allow the cabbage to wilt slightly.","duration":5,"images":[],"step":3},{"description":"Adjust seasoning with extra salt and pepper (if required), garnish with reserved 1 tbsp parmesan cheese and serve.","images":[],"step":4}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["lunch"],"cuisine":[],"categories":["all-vegetable-sides","cabbage","easter-sides-fresh-light","italian-recipes","peas","quick-and-easy","quick-dinner-ideas-15-minute-meals","side-salads","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7b3e98cdc221', 'en', 'US', 'Feta Marinated with Herbs and Chilli', 'A cost effective starter that tastes as delightful as it looks and takes minutes to prepare. You could also make this just by serving a whole block of feta, but cutting it into cubes makes it easier to serve and also you get a better feta/olive oil/herb ratio with every bite!', 'https://www.recipetineats.com/tachyon/2014/07/DSC_0192.jpg', 5, 0, 5, 4, '[{"id": "ing_cheese", "quantity": {"value": 8.0, "unit": "block of 250g"}}, {"id": "ing_oil", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_herbs", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["8 oz / 250 g feta cheese (, preferably Danish or another creamy type (see notes))","1/2 cup extra virgin oil","2 garlic cloves (, peeled)","2 tbsp herbs (, finely chopped. (I used parsley and thyme leaves))","1 birds eye chilli (, finely chopped (or any fresh red chilli of choice))","1//4 tsp lemon rind (, finely grated)","Black pepper"]}]', '[{"title":"Infuse olive oil with garlic (optional)","description":"use the side of your knife to smash the garlic cloves and combine with the olive oil. Cover, refrigerate and leave for as long as possible - a few hours or preferably overnight.","images":[],"step":1},{"description":"If you do not have the time to do Step 1, just mince 1 garlic clove (small) and stir into the olive oil.","images":[],"step":2},{"title":"Cut the feta into bite size cubes","description":"about 1cm / 1/3 inch.","images":[],"step":3},{"description":"Place feta into serving dish, scatter over herbs, chilli, lemon rind and a grind of black pepper.","images":[],"step":4},{"description":"Pour over olive oil. Serve with crusty bread.","images":[],"step":5}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["snack"],"cuisine":[],"categories":["mediterranean-recipes","most-popular","quick-and-easy","quick-dinner-ideas-15-minute-meals","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_20d260fb6149', 'en', 'US', 'Quick Taco Soup with Pork Carnitas', 'Enchiladas in a bowl! A thick, chunky soup on the table in 15 minutes with amazing flavours. This recipe is part of my Pork Carnitas series so is made using Pork Carnitas (Mexican Pulled Pork) but you can also make this with shredded chicken. By using pre cooked meat this is a super fast meal you can get on the table in 15 minutes!', 'https://www.recipetineats.com/tachyon/2014/07/DSC_0044.jpg', 5, 10, 15, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_black_beans", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_corn", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_chilli", "quantity": {"value": 0.013, "unit": "pack of 100g"}}, {"id": "ing_pork", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.68, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 1.0, "unit": "jar of 50g"}}, {"id": "ing_corn", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["1 tbsp olive oil","1 brown or white onion (, diced)","1 red bell pepper ((capsicum), diced)","1 can (15oz / 400g) black beans (Note 2)","1 can (15oz / 400g) sweet corn","2 garlic cloves (, minced)","2 tsp oregano (dried)","2 tsp cumin","1 tsp paprika","1/4 tsp chilli (optional)","2 cups shredded Mexican pulled pork (Pork Carnitas) (or shredded chicken)","24 oz / 680 g tomato puree passata (or crushed tomatoes - see Note 1)","4 cups (1 litre / 2 pints) chicken or vegetable broth / stock","Salt and pepper"]},{"ingredients":["Corn chips","Sour cream","Grated cheese","Cilantro / coriander leaves","Avocado (, diced)"],"purpose":"Toppings (optional)"}]', '[{"description":"Heat the oil in a large saucepan over high heat.","images":[],"step":1},{"description":"Add the pulled pork and cook for 1 minute until parts of it are browned, then remove from the saucepan. Do this step even if you are using shredded chicken or another meat.","duration":1,"images":[],"step":2},{"description":"Add garlic and onion, sauté until onion becomes translucent (2 minutes), then add the capsicum (bell pepper) and cook for 1 minute until softened.","duration":1,"images":[],"step":3},{"description":"Return the pulled pork into the saucepan and add all other ingredients except salt and pepper. If you are making this ahead to FREEZE, see below for instructions.","images":[],"step":4},{"description":"Stir to scrap the brown bits from the pulled pork off the bottom of the pan to mix in with the soup flavours.","images":[],"step":5},{"description":"Bring to boil then turn down heat slightly and allow to simmer rapidly for 3 minutes so the flavours can come together. If you are using crushed tinned tomatoes instead of passata, let it simmer for a further 5 minutes to let the tomatoes breakdown a bit. If the soup gets too thick to your liking, just add a bit more water.","duration":3,"images":[],"step":6},{"description":"Do a taste test, then season with salt and pepper. It is important to season last because different stock brands have different levels of saltiness.","images":[],"step":7},{"description":"Serve with toppings of choice. The more toppings = more delicious!","images":[],"step":8},{"description":"Freezer Friendly Instructions","images":[],"step":9},{"description":"Follow steps 1 to 3.","images":[],"step":10},{"description":"In step 4, do not add the tomato passata or chicken/vegetable stock/broth. Instead, add 1 cup of water, bring to simmer and stir, scraping the bottom of the pot to get the brown bits off.","images":[],"step":11},{"description":"Remove pot from heat and set aside to cool, then pour the contents into a container or ziplock bag and freeze.","images":[],"step":12},{"description":"To cook, defrost, then pour the contents into a saucepan. Add the tomato passata and chicken stock/broth. Then follow steps 6 onwards as per above.","images":[],"step":13}]', '["milk"]', '["gluten_free","high_protein","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Mexican"],"categories":["main-dishes","mexican-recipes","pork-carnitas","pork-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8d2c72cf51cc', 'en', 'US', 'Packet Ramen Makeover', 'Transform packet ramen by topping it with stir fried vegetables in a glossy sauce! You can use whatever vegetables you want for this, just make sure you put them in the wok in order of length of time to cook, starting with the longest. Make it even healthier by using low sodium packet ramen. If you can manage the stir fry while you boil the noodles, you''ll get this on the table in 10 minutes!', 'https://www.recipetineats.com/tachyon/2014/07/Ramen-Makeover-2.jpg', 5, 10, 15, 1, '[{"id": "ing_packet_instant_ramen", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_cabbage", "quantity": {"value": 3.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_mushroom", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 0.25, "unit": "bag of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.5, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_oil", "quantity": {"value": 7.5, "unit": "bottle"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.006, "unit": "pack of 400g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.03, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.015, "unit": "bottle of 500ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_water", "quantity": {"value": 0.045, "unit": "L"}}]', '[{"ingredients":["1 packet instant ramen (Note 1)"]},{"ingredients":["1 cup Chinese cabbage ((loosely packed), chopped into 2.5cm/1\" pieces)","1/2 carrot (, sliced on the diagonal)","3 mushrooms (, sliced (I used shiitake))","1/4 cup bean sprouts","1/2 shallot/scallion (, finely sliced (for garnish))","1 garlic clove (, minced)","1/2 tbsp peanut oil"],"purpose":"Stir Fry (about 2 1/2 cups of chopped vegetables, Note 2)"},{"ingredients":["1/2 tsp corn flour / cornstarch","1 1/2 tsp soy sauce","1 1/2 tsp chinese cooking wine (Note 3)","1/2 tsp sugar","Dash of sesame oil (optional)","3 tbsp water"],"purpose":"Stir Fry Sauce"}]', '[{"description":"Combine the sauce ingredients in a small bowl and mix well until there are no cornflour lumps.","images":[],"step":1},{"description":"Bring water to boil and cook ramen per packet instructions, using the soup stock packet that comes with the ramen. (See Notes)","images":[],"step":2},{"description":"Heat oil in wok (or fry pan) over high heat. Add garlic and stir fry for 20 seconds until fragrant - be careful not to burn it.","duration":0.3333333333333333,"images":[],"step":3},{"description":"Add carrots and mushrooms and stir fry for 30 seconds, then Chinese cabbage and stir fry for another 30 seconds.","duration":0.5,"images":[],"step":4},{"description":"Add sauce and cook for 30 seconds until it becomes thick and glossy.","duration":0.5,"images":[],"step":5},{"description":"Remove from heat, immediately add the bean sprouts and give a quick stir to coat the bean sprouts in the sauce and use the residual heat to slightly cook the bean sprouts.","images":[],"step":6},{"description":"Place noodles and soup in bowl, top with vegetables and garnish with shallots. Serve immediately.","images":[],"step":7}]', '["gluten","peanuts","sesame","soy"]', '["vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Asian","Japanese"],"categories":["asian-recipes","dinner-tonight","main-dishes","noodles","quick-and-easy","quick-dinner-ideas-15-minute-meals","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_570bed46da96', 'en', 'US', 'Trio of Bruschetta: Lemon Cannellini Bean', 'A creamy, lemony bruschetta topping that takes minutes to make. Great pantry bite!', 'https://www.recipetineats.com/tachyon/2014/07/Cannellini-Bean-Bruschetta-Version-2.jpg', 5, 5, 10, 4, '[{"id": "ing_bread", "quantity": {"value": 0.2, "unit": "loaf"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_cannellini_beans", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["4 slices of good quality crusty bread like sourdough or ciabatta (, sliced 1cm/0.5\" thick, preferably slightly stale)","1 garlic clove (, halved (unpeeled))","Extra virgin olive oil (, for drizzling)"],"purpose":"Bread"},{"ingredients":["1 can cannellini beans (15oz/420g)","Zest of half a lemon","1 1/2 tbsp lemon juice","1 tbsp parsley (, finely chopped, plus extra to garnish)","Salt and pepper"],"purpose":"Cannellini and Lemon Topping"}]', '[{"description":"Preheat a griddle pan or barbecue (grill side, not hotplate side) on high.","images":[],"step":1},{"description":"Place bread on the barbecue or griddle pan, and cook each side until nicely toasted and golden brown with char lines. You can also toast the bread in a toaster or grill/broil.","images":[],"step":2},{"description":"Remove from heat and rub the surface of the bread lightly with the garlic.","images":[],"step":3},{"description":"Lemon Cannellini Topping","images":[],"step":4},{"description":"Combine ingredients in a small bowl. Mash about half the beans with a fork - leave some of the beans whole for a bit of texture.","images":[],"step":5},{"description":"Taste first before seasoning with salt and pepper (saltiness of beans depends on brand).","images":[],"step":6},{"description":"Spread topping onto bread. Garnish with extra parsley, drizzle with extra virgin olive oil and serve immediately.","images":[],"step":7}]', '["gluten"]', '["low_calorie","vegan","vegetarian"]', '{"mealType":["snack"],"cuisine":["Italian"],"categories":["italian-recipes","no-cook-food","quick-and-easy","quick-dinner-ideas-15-minute-meals","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1649d06bc276', 'en', 'US', 'Trio of Bruschetta: Celery and Lime Bruschetta', '', 'https://www.recipetineats.com/tachyon/2014/07/DSC_0070.jpg', 5, 5, 10, 4, '[{"id": "ing_bread", "quantity": {"value": 0.2, "unit": "loaf"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_celery", "quantity": {"value": 120.0, "unit": "head"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_lime", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["4 slices of good quality crusty bread like sourdough or ciabatta (, sliced 1cm/0.5\" thick, preferably slightly stale)","1 garlic clove (, halved (unpeeled))"],"purpose":"Bread"},{"ingredients":["6 large sticks of celery","1 garlic clove (, peeled)","4 tbsp extra virgin olive oil","1 tbsp lime juice","1/4 tsp salt (, plus more to taste)","Black pepper"],"purpose":"Celery and Lime Topping"}]', '[{"description":"Preheat a griddle pan or barbecue (grill side, not hotplate side) on high.","images":[],"step":1},{"description":"Place bread on the barbecue or griddle pan, and cook each side until nicely toasted and golden brown with char lines. You can also toast the bread in a toaster or grill/broil.","images":[],"step":2},{"description":"Remove from heat and rub the surface of the bread lightly with the garlic.","images":[],"step":3},{"description":"Celery and Lime Topping","images":[],"step":4},{"description":"Cut 5 1/2 of the celery sticks into chunks (about 4 cups) and place into food processor with remaining ingredients and whizz until smooth. Season to taste with salt and pepper.","images":[],"step":5},{"description":"Dice the remaining 1/2 celery stick. Stir into the celery puree.","images":[],"step":6},{"description":"Spread topping onto bread. Drizzle with extra virgin olive oil and serve immediately.","images":[],"step":7}]', '["gluten"]', '["low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["italian-recipes","no-cook-food","quick-and-easy","quick-dinner-ideas-15-minute-meals","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_21767e5709e7', 'en', 'US', 'S''mores French Toast', 'This is how you sneak in dessert for breakfast!', 'https://www.recipetineats.com/tachyon/2014/07/Smores-French-Toast-2.jpg', 10, 5, 15, 2, '[{"id": "ing_bread", "quantity": {"value": 0.2, "unit": "loaf"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_marshmallows", "quantity": {"value": 16.0, "unit": "unit"}}, {"id": "ing_nutella", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_chocolate", "quantity": {"value": 1.0, "unit": "block of 100g"}}]', '[{"ingredients":["4 slices white sandwich bread (, preferably stale)","1 tbsp butter","1 egg","2 tbsp milk","16 marshmallows (, halved horizontally)","Nutella"]},{"ingredients":["Marshmallows","Chocolate sauce"],"purpose":"Toppings (optional)"}]', '[{"description":"Combine egg and milk in a shallow dish large enough to lay the bread in.","images":[],"step":1},{"description":"Spread Nutella on all 4 slices of bread. Generously!","images":[],"step":2},{"description":"Place marshmallows on 2 of the pieces of bread, with the sticky side of the marshmallows (ie. the cut side) facing up.","images":[],"step":3},{"description":"Heat butter in pan over medium high heat. (See notes)","images":[],"step":4},{"description":"Take the bread with the marshmallows on them and quickly dip the bottom side of the bread (ie. the side without the Nutella and marshmallows on it) into the egg mixture, then place into the pan.","images":[],"step":5},{"description":"Dip the remaining two slices of bread into the egg mixture (the side without Nutella on it) and place on top of the marshmallow topped bread in the pan, to form a sandwich (ie. The side with the Nutella on it should be placed onto the marshmallows and the side you dipped into the egg mixture should face up so when you flip, it will be cooked).","images":[],"step":6},{"description":"Press down lightly with a spatula to help disperse the heat through to the centre of the sandwich to melt the marshmallows. Don''t press too hard - I made that mistake once and most of my marshmallows oozed out the side into the pan.","images":[],"step":7},{"description":"When the bottom is golden brown (about 2 1/2 to 3 minutes), flip and cook the other side until golden brown (about 2 minutes).","images":[],"step":8},{"description":"Don''t worry if the marshmallows aren''t oozing out the side when you finish cooking, they will continue to melt from the heat in the sandwich. But they should be very soft - just touch one and you''ll be able to tell if it''s melted and gooey inside.","images":[],"step":9},{"description":"Serve immediately, topped with extra marshmallows and chocolate sauce, if you wish.","images":[],"step":10}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["breakfast","dessert"],"cuisine":[],"categories":["breakfast-recipes","dessert-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_aab068957f4b', 'en', 'US', 'Teriyaki Chicken (With Homemade Teriyaki Sauce)', 'Make your own Teriyaki Sauce at home - not only is it easy, fast and more tasty, the marinade infuses into the flesh better. Make a larger batch and store it in the fridge so you have it on hand for a quick meal! Also great to cook on the outdoor grill/BBQ. Though not strictly a 15 minute meal because of the marinating time, I have classified it in 15 minute meals because the cooking and active prep time is less than 15 minutes.', 'https://www.recipetineats.com/tachyon/2014/07/Teriyaki-Chicken-1.jpg', 2, 13, 15, 4, '[{"id": "ing_teriyaki_sauce_marinade", "quantity": {"value": 60.0, "unit": "bottle"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_mirin", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_wine", "quantity": {"value": 0.04, "unit": "bottle of 750ml"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}]', '[{"ingredients":["4 tbsp Teriyaki Sauce Marinade","4 chicken thigh fillets (, skinless and boneless (about 5oz/150g each))","1 tbsp oil"]},{"ingredients":["2 tbsp soy sauce","2 tbsp mirin","2 tbsp Japanese cooking wine (sake)","2 tbsp water"],"purpose":"Teriyaki Sauce Marinade"}]', '[{"description":"Teriyaki Sauce Marinade (\"Marinade\")","images":[],"step":1},{"description":"Combine the 4 ingredients in a small saucepan over high heat.","images":[],"step":2},{"description":"Bring to boil, then turn heat down and simmer until it reduces by half - it should only take 5 minutes or so. The consistency should be like a light syrup. Keep your eye on it - it will start to thicken suddenly!","images":[],"step":3},{"description":"Bring to room temperature before using.","images":[],"step":4},{"description":"Combine the Marinade with the chicken and marinate for at least 20 minutes, preferably overnight.","images":[],"step":5},{"description":"Remove chicken from Marinade but do not discard the Marinade liquid.","images":[],"step":6},{"description":"Heat oil in non stick pan over medium to medium-high heat. You don''t want it too hot because otherwise the sugar in the Marinade will burn before the inside is cooked.","images":[],"step":7},{"description":"Place the chicken in the pan and cook the first side for around 3 minutes, checking to ensure the skin isn''t cooking too quickly. If it is, remove pan from heat and turn the heat down, and add about 2 to 4 tbsp of water to the pan then return to the stovetop. The water slows down the searing process on the skin while still allowing the chicken to cook on the inside.","images":[],"step":8},{"description":"Turn chicken over and cook the other side. Just before the chicken is finished cooking, add 2 tbsp of water to the pan and and swirl around and mix with the marinade that has come off the chicken. This will make a dark glossy \"sauce\". Move the chicken around in the pan to coat with this sauce.","images":[],"step":9},{"description":"The Marinade is a strong flavour so you shouldn''t need any extra sauce. But if you do want more, add equal parts of Teriyaki Sauce and water to the pan and allow to come to a simmer and let it cook until the desired consistency.","images":[],"step":10},{"description":"Serve with rice.","images":[],"step":11}]', '["gluten","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Asian","Japanese"],"categories":["asian-recipes","asian-takeout","australia-day","chicken-recipes","grilling-ideas-and-recipes","most-popular","quick-and-easy","quick-dinner-ideas-15-minute-meals","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0e16272cf692', 'en', 'US', 'Homemade Teriyaki Sauce', 'Teriyaki sauce is so easy to make at home, once you''ve made it once you''ll never buy the bottled stuff again!', 'https://www.recipetineats.com/tachyon/2014/07/Teriyaki-Sauce-1-copy.jpg', 2, 10, 12, 8, '[{"id": "ing_soy_sauce", "quantity": {"value": 0.25, "unit": "bottle of 250ml"}}, {"id": "ing_mirin", "quantity": {"value": 0.25, "unit": "bottle of 250ml"}}, {"id": "ing_wine", "quantity": {"value": 0.083, "unit": "bottle of 750ml"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}]', '[{"ingredients":["1/4 cup soy sauce","1/4 cup mirin","1/4 cup Japanese cooking wine (sake)","1/4 cup water"]}]', '[{"description":"Teriyaki Sauce Marinade (\"Marinade\")","images":[],"step":1},{"description":"Combine ingredients in a large saucepan over high heat. The larger the pan, the faster it will reduce. For me it takes about 10 minutes, but it depends on the size of the pan you use.","images":[],"step":2},{"description":"Bring to boil, then turn heat down and simmer until it reduces by half. The consistency should be like a light syrup.","images":[],"step":3},{"description":"Bring to room temperature before using.","images":[],"step":4},{"description":"Combine 3 to 4tbsp of Marinade per 1lb/500g of meat and marinate for at least 20 minutes, preferably overnight. However, if marinating fish, do not marinate for more than a few hours at most - 20 minutes is enough (otherwise the flavour will overpower the fish).","images":[],"step":5},{"description":"Teriyaki goes very well with chicken, beef and fish that suit strong flavours such as salmon.","images":[],"step":6},{"description":"You can grill/broil, pan fry or BBQ/grill the meat.","images":[],"step":7},{"description":"If you are cooking it on the BBQ/grill or broiling/grilling the meat, then baste each side at least once during cooking.","images":[],"step":8},{"description":"If you are cooking this on the stove then just before the meat has finished cooking, add 2 tbsp of water to the pan and swirl it around to mix with the marinade that has come off the meat. Bring it to a rapid simmer and cook until it becomes a thick sauce consistency, and move the meat around in the sauce to coat it.","images":[],"step":9}]', '["gluten","soy"]', '["keto_friendly","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Asian","Japanese"],"categories":["asian-recipes","asian-takeout","chicken-recipes","most-popular","quick-and-easy","quick-dinner-ideas-15-minute-meals","vegan-lifestyle","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2d45ab100146', 'en', 'US', 'Mexican Fried Rice', 'Super fast, super versatile, super tasty - a super mid week meal to add to your rotation! Feel free to substitute the ingredients with whatever you have on hand, including adding proteins - any shredded or diced meat would be a great addition. The key to keeping it "Mexican" is the enchilada sauce and the spices.', 'https://www.recipetineats.com/tachyon/2014/07/Mexican-Fried-Rice-1.jpg', 10, 5, 15, 2, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_black_beans", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_corn", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_rice", "quantity": {"value": 600.0, "unit": "pack"}}, {"id": "ing_proteins", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_enchilada_sauce", "quantity": {"value": 90.0, "unit": "bottle"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_cumin", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_chilli", "quantity": {"value": 0.013, "unit": "pack of 100g"}}, {"id": "ing_paprika", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1 tbsp olive oil","1 large garlic clove (, minced)","1 onion (, diced (white or brown))","1/2 red bell pepper / capsicum (, diced (about 1 cup))","1 cup tinned black beans (drained)","1 cup tinned corn kernels (drained) (or frozen corn)","4 cups cooked rice (see notes)","Optional: 1 1/2 cups protein ((chicken, pork, beef), shredded or diced)"]},{"ingredients":["6 tbsp enchilada sauce (see notes)","2 tbsp water","1/2 tsp cumin","1/4 tsp chilli powder (or to taste)","1/2 tsp paprika","1 tsp salt","Black pepper"],"purpose":"Sauce"}]', '[{"description":"Combine the Sauce ingredients in a small bowl and mix.","images":[],"step":1},{"description":"Heat the oil in a pan over high heat. Add garlic and cook for 10 seconds until fragrant.","duration":0.16666666666666666,"images":[],"step":2},{"description":"Add the onion and bell pepper and cook until the onion becomes translucent - about 2 minutes.","images":[],"step":3},{"description":"If you are using uncooked protein, add it and sauté until just cooked through.","images":[],"step":4},{"description":"Add the black beans and corn. If you are using cooked proteins (like shredded cooked chicken) add it at the same time. Cook for 1 minute just to heat through.","duration":1,"images":[],"step":5},{"description":"Add the rice and Sauce and stir quickly to coat the rice evenly.","images":[],"step":6},{"description":"Check seasoning and add more salt if you require it. Amount of salt required depends on the saltiness of the enchilada sauce you are using.","images":[],"step":7},{"description":"Season with black pepper and serve immediately.","images":[],"step":8}]', '[]', '["gluten_free"]', '{"mealType":["main_course"],"cuisine":["Mexican"],"categories":["mexican-recipes","pork-carnitas","quick-and-easy","quick-dinner-ideas-15-minute-meals","rice-recipes","rice-side-dishes","side-dishes","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_03ba7e9fb047', 'en', 'US', 'Japanese Salmon with Mirin and Soy Sauce', 'This is a classic, simple, everyday way of cooking fish with an amazing flavour that is being made in millions of Japanese households every day. With only 3 ingredients in the marinade (and no chopping!), it takes all of 30 seconds to prepare. Be careful to ensure you cook it over medium heat and no higher - because of the sugar in the mirin, if you cook it on too high a heat the sugar will burn before the inside has been cooked.', 'https://www.recipetineats.com/tachyon/2014/07/Salmon-Soy-Mirin.jpg', 1, 6, 7, 2, '[{"id": "ing_fish_fillets", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_mirin", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_sake", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_oil", "quantity": {"value": 7.5, "unit": "bottle"}}]', '[{"ingredients":["2 salmon fillets (5 oz / 150 g each)","1 tbsp soy sauce","3 tbsp mirin","1 tbsp sake","1/2 tbsp oil"]}]', '[{"description":"Combine all ingredients except the oil in a ziplock bag, remove as much air as possible and marinade overnight (or minimum 3 hours).","images":[],"step":1},{"description":"Heat 1/2 tbsp oil in a non stick pan over medium heat.","images":[],"step":2},{"description":"Add salmon skin side down, cook for 2 to 3 minutes until crispy. Check the skin to ensure it isn''t cooking too quickly - if it is, then turn down the heat and/or remove the pan from the stove briefly to allow the temperature to decrease.","duration":2.5,"images":[],"step":3},{"description":"Drizzle over remaining marinade in the ziplock bag over the flesh side. Flip and cook the flesh side for 2 minutes, or to your liking. I like salmon medium rare so the inside is very moist and just cooked.","duration":2,"images":[],"step":4},{"description":"Rest for a couple of minutes, remembering that the salmon will continue to cook while resting, then serve.","images":[],"step":5}]', '["fish","gluten","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Asian","Japanese"],"categories":["asian-recipes","australia-day","fish-recipes","grilling-ideas-and-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bb58548d6637', 'en', 'US', 'Cinnamon French Toast Sticks', 'French toast you can eat with your fingers and tastes like cinnamon doughnuts!', 'https://www.recipetineats.com/tachyon/2014/07/French-Toast-Sticks-1.jpg', 5, 10, 15, 2, '[{"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_maple_syrup", "quantity": {"value": 1.0, "unit": "bottle of 250ml"}}]', '[{"ingredients":["4 thick slices white bread, preferably stale (Note 1)","2 eggs","1/4 cup milk","Salt","1/3 cup white sugar","1 tsp cinnamon powder","3 tbsp butter","Maple syrup to serve (optional)"]}]', '[{"description":"Remove crust of each slice, then cut each into 3 equal thick batons.","images":[],"step":1},{"description":"Combine the eggs, milk and a pinch of salt in a bowl large enough to roll the bread sticks in.","images":[],"step":2},{"description":"Combine the cinnamon and sugar on a plate.","images":[],"step":3},{"description":"Melt 2 tbsp of the butter in a large pan over medium high heat.","images":[],"step":4},{"description":"Roll the sticks in the egg mixture quickly (do not soak them), shake off excess and place in pan. Cook in 2 batches.","images":[],"step":5},{"description":"Turn to cook each side until golden.","images":[],"step":6},{"description":"Immediately transfer to the plate with the cinnamon sugar and roll to coat. It''s important to do this quickly while they are hot straight out of the pan so it sticks.","images":[],"step":7},{"description":"Melt remaining butter and cook the remaining french toast sticks.","images":[],"step":8},{"description":"Serve immediately with maple syrup to dunk the sticks in.","images":[],"step":9}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["breakfast"],"cuisine":[],"categories":["breakfast-recipes","most-popular","quick-and-easy","quick-dinner-ideas-15-minute-meals","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1247eb05eaef', 'en', 'US', 'Fattoush With Crunchy Flatbread Ribbons', 'My version of the classic Middle Eastern fattoush salad - piled high with crunchy flatbread ribbons which is everybody''s favourite part! A wonderful lemon dressing with extra zing from sumac and the warmth of paprika. This serves 2 as a light meal or 4 as a side.', 'https://www.recipetineats.com/tachyon/2014/07/Fattoush2.jpg', 10, 5, 15, 2, '[{"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_mint", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 2.5, "unit": "loaf"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_paprika", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_sumac", "quantity": {"value": 5.0, "unit": "jar"}}]', '[{"ingredients":["2 tomatoes (, each cut into 8 to 12 wedges)","2 cucumbers (, each cut into 12 sticks)","1/2 red onion (, finely sliced)","1 tbsp lemon juice","1/4 cup mint leaves (if leaves are large, roughly tear by hand)","1/4 cup coriander leaves","2 lebanese flatbreads (Note 1)","1 1/2 tbsp olive oil","Salt and pepper"]},{"ingredients":["2 tbsp lemon juice","2 tbsp extra virgin olive oil","1/2 tsp salt","1 garlic clove (, minced)","1/2 tsp paprika","1 tsp sumac"],"purpose":"Dressing"}]', '[{"description":"Preheat the oven to 350F/180C.","images":[],"step":1},{"description":"Roll up the flatbread then cut into thin slices. Use your fingers to loosen them into a pile of \"ribbons\".","images":[],"step":2},{"description":"Pile onto a baking tray, drizzle over olive oil and a couple of pinches of salt, then use your fingers to coat all the ribbons with the oil.","images":[],"step":3},{"description":"Bake in oven for 3 minutes, then remove tray and move the ribbons around a bit so they bake evenly. At this stage some of the ribbons will not yet be crisp. Turn the oven OFF, then return the tray into the oven for a couple of minutes. This will make all the ribbons crisp without over browning them.","duration":3,"images":[],"step":4},{"description":"While the ribbons are baking, combine the red onion in a small bowl with 1 tbsp lemon juice and pinch of salt. Set aside - it lightly pickles and removes some of the acidity from the onion.","images":[],"step":5},{"description":"Combine the dressing ingredients.","images":[],"step":6},{"description":"Combine the tomatoes, cucumbers, mint and coriander leaves in a small bowl. Squeeze excess juice from the lemons, and add to the bowl.","images":[],"step":7},{"title":"Pour over dressing and toss gently to combine","description":"you may not need all the dressing.","images":[],"step":8},{"description":"Transfer salad onto a platter then pile on the crunchy flatbread ribbons.","images":[],"step":9},{"description":"Sprinkle with extra sumac.","images":[],"step":10}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Arabic","Middle Eastern"],"categories":["cuisines","middle-eastern-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","side-salads","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c1053b443e81', 'en', 'US', 'Garlic White Bean Mash In A Flash', 'Sometimes you''ve just gotta have mash but you simply don''t have the energy (or time) to peel, cut, boil and mash potatoes. On such occasions, this Garlic White Bean Mash In A Flash is simply fabulous to satisfy your craving - suitably named because it requires such little effort to make. I made this as a side for my Healthy Parmesan Garlic Crumbed Fish to make a complete meal in 15 minutes. This recipe is also great to use as a topping for bruschetta.', 'https://www.recipetineats.com/tachyon/2014/07/White-Bean-Mash.jpg', 1, 3, 4, 2, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_cannellini_beans_drained", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1 tbsp extra virgin olive oil","1 garlic clove (, minced)","1 can cannellini beans ((15oz / 420g can), drained)","1/3 cup vegetable stock","1/2 lemon zest (optional)","Salt and pepper to taste"]}]', '[{"description":"Heat oil in pan over medium high, add garlic and sauté until fragrant.","images":[],"step":1},{"description":"Add beans, stock and lemon zest.","images":[],"step":2},{"description":"Simmer for 2 minutes, then use a fork or potato masher to mash.","duration":2,"images":[],"step":3},{"description":"Season to taste with salt and pepper.","images":[],"step":4}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["lentil-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","side-dishes","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e9ad831fb9ea', 'en', 'US', 'Creamy Healthy Broccoli Soup', '', 'https://www.recipetineats.com/tachyon/2014/07/Broccoli-Soup2.jpg', 5, 10, 15, 2, '[{"id": "ing_broccoli", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1 large head of broccoli","1 potato (, peeled and roughly chopped into cubes about 1.5cm / 1/2\" cubes)","1 white or brown onion (, roughly diced)","2 cloves garlic","2 cups / 500 ml vegetable stock / broth","1 cup / 250 ml milk (low fat, cow or soy)","1/2 cup / 125 ml water","Salt and pepper"]}]', '[{"description":"Cut / break broccoli into florets into pieces about half the size of a golf ball. Roughly cut most of the stem, other than the main stem, into thumb size pieces. Discard the main stem, or keep for another use.","images":[],"step":1},{"description":"Place all ingredients except milk, salt and pepper in pot, put on lid, bring to boil then turn down heat to medium and let it rapidly simmer for 8 to 10 minutes.","duration":9,"images":[],"step":2},{"description":"Remove lid, add milk, bring back to boil, then remove from heat and whizz with hand held blender.","images":[],"step":3},{"description":"You can thicken the soup by cooking it for longer on the stove on a medium low heat.","images":[],"step":4},{"description":"Season to taste with salt and pepper, serve with croutons if desired.","images":[],"step":5},{"description":"Cut stale bread into cubes, lightly spray with olive oil, spread on baking stray and bake for 3 to 5 minutes. Sprinkle with salt then top on soup.","duration":4,"images":[],"step":6}]', '["milk","soy"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["broccoli-recipes","dietary","dinner-tonight","low-calorie-recipes","main-dishes","quick-and-easy","quick-dinner-ideas-15-minute-meals","soup-recipes","vegan-lifestyle","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ec7d6c47eb60', 'en', 'US', 'Roasted Broccoli with Toasted Pangritata (Breadcrumbs)', 'The addition of crunchy pangritata (which is just a fancy word for toasted breadcrumbs) takes broccoli to another level that even kids won''t be able to resist!', 'https://www.recipetineats.com/tachyon/2014/06/Broccoli-with-Pangrittata-2-Version-2.jpg', 5, 15, 20, 4, '[{"id": "ing_broccoli", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 0.094, "unit": "loaf"}}, {"id": "ing_parmesan", "quantity": {"value": 0.225, "unit": "pack of 200g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}]', '[{"ingredients":["1 large broccoli or 2 small (, cut into florets)","2 tbsp olive oil","1/2 tsp salt","1/4 tsp freshly ground black pepper"]},{"ingredients":["1/2 cup homemade breadcrumbs ((chunkier the better) or panko)","3 tbsp finely grated Parmesan (optional) (see notes)","1 tbsp extra olive oil","Salt"],"purpose":"Pangritata"}]', '[{"description":"Toss broccoli with 2tbsp olive oil, salt and pepper.","images":[],"step":1},{"description":"Spread on tray and roast in 350F/180C oven for around 10 minutes until slightly softened and starting to brown.","images":[],"step":2},{"description":"Meanwhile, combine breadcrumbs, parmesan, 1 tbsp olive oil and salt in small bowl.","images":[],"step":3},{"description":"When broccoli is almost done, take the tray out, move the broccoli to one side to make room to spread out the breadcrumbs on the tray.","images":[],"step":4},{"description":"Roast broccoli and breadcrumbs for approximately 12 min until the breadcrumbs are golden - don''t walk away, the breadcrumbs will cook quickly.","images":[],"step":5},{"description":"Pile combined broccoli and breadcrumbs into serving bowl.","images":[],"step":6}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["all-vegetable-sides","broccoli","broccoli-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","side-dishes","side-salads","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_37e7fc1978b9', 'en', 'US', 'Fast French Toast with Cinnamon Apples', 'French toast dripping with apple cinnamon syrup - it''s simply incredible that you can get this on the table in 15 minutes!', 'https://www.recipetineats.com/tachyon/2014/06/DSC_00481.jpg', 5, 10, 15, 2, '[{"id": "ing_apples", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_cinnamon", "quantity": {"value": 1.25, "unit": "jar"}}, {"id": "ing_butter", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_bread", "quantity": {"value": 0.2, "unit": "loaf"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 1.0, "unit": "kg"}}]', '[{"ingredients":["2 small red apples (, or 1 large red apple)","1/4 cup white sugar","1/4 tsp cinnamon","1 1/2 tbsp butter","2 tbsp water"],"purpose":"Cinnamon Apples"},{"ingredients":["4 slices white bread (, preferably slightly stale)","2 eggs","1/4 cup milk","2 tbsp butter","1 pinch salt"],"purpose":"French Toast"}]', '[{"description":"Put the sugar, butter and cinnamon in a small saucepan over medium high heat.","images":[],"step":1},{"description":"Meanwhile, cut the apple into 1/4\" / 7mm thick wedges, leaving the skin on.","images":[],"step":2},{"title":"Add the apple and water to the saucepan","description":"it doesn''t matter if the butter/sugar hasn''t completely melted yet.","images":[],"step":3},{"description":"Stir gently every now and let it simmer away until the apples have slightly softened and the syrup turns into a maple syrup consistency. Remove from heat and set aside.","images":[],"step":4},{"description":"While the sauce is simmering away, whisk together the egg, milk, butter and salt into a bowl.","images":[],"step":5},{"description":"Melt half the butter in a large pan over medium high heat (or all if you are cooking them in a large pan that will fit al 4 pieces of bread).","images":[],"step":6},{"description":"Submerge each bread into the mixture, then remove, allowing the excess egg to drip off. Don''t soak the bread in the egg mixture, you don''t want it to be completely soaked through, just coated.","images":[],"step":7},{"description":"Place in pan and cook until golden brown on each side - about 1 1/2 minutes.","images":[],"step":8},{"description":"To serve, place french toast on a plate and top with the apple mixture, spooning over the syrup.","images":[],"step":9}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["breakfast"],"cuisine":[],"categories":["breakfast-recipes","dessert-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b7ac56dbd55e', 'en', 'US', 'Mapo Tofu', 'The Japanese version of the classic Sichuan dish is not as oily or spicy, but still packs a punch when it comes to flavour (and spice if you so choose!) and is made from more readily available ingredients. Because this dish is so saucy, you can make it a complete "one pot" meal by adding more vegetables - any Chinese greens (like bok choy, pak choy) will go wonderfully with this. Even grated vegetables like carrots! As with all stir fried dishes, this is best made with all ingredients prepared and ready to toss into the wok as this comes together quickly once you start cooking.', 'https://www.recipetineats.com/tachyon/2014/06/DSC_0005-Version-2.jpg', 7, 5, 12, 2, '[{"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.75, "unit": "bunch"}}, {"id": "ing_pork", "quantity": {"value": 0.142, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_tofu", "quantity": {"value": 1.134, "unit": "pack of 300g"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.037, "unit": "pack of 400g"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.003, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_wine", "quantity": {"value": 0.04, "unit": "bottle of 750ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}]', '[{"ingredients":["2 tbsp oil (peanut, vegetable or canola)","1 garlic clove (, minced)","1 tsp ginger (, finely chopped or minced)","1/4 cup scallions/shallots (, minced)","5 oz / 150 g ground/minced pork (or beef or chicken)","2 tsp chili bean sauce (, adjust to taste (see notes))","12 oz / 300 g Firm Tofu (see notes)"]},{"ingredients":["1 cup water","1 tbsp cornstarch","1/2 tsp chicken or vegetable stock powder","1 tbsp soy sauce","1/2 tbsp sugar","1 tbsp Hoisin Sauce","2 tbsp Sake or Chinese Wine","1 tsp sesame oil"],"purpose":"Sauce"}]', '[{"description":"In a bowl, combine cornflour with a splash of water, mix to combine, then add remaining Sauce ingredients and mix well.","images":[],"step":1},{"description":"Cut the tofu into 1/2 \"/ 1 cm cubes.","images":[],"step":2},{"description":"Heat oil in wok over high heat.","images":[],"step":3},{"description":"Add garlic and ginger and stir fry for 10 seconds.","duration":0.16666666666666666,"images":[],"step":4},{"description":"Add scallions/shallots and stir fry for 30 seconds.","duration":0.5,"images":[],"step":5},{"description":"Add mince and stir fry until the outside is brown, breaking up clumps.","images":[],"step":6},{"description":"Add Chili Bean Sauce and stir fry for 30 seconds.","duration":0.5,"images":[],"step":7},{"description":"Add tofu and sauce, and gently stir to cook the sauce until it becomes thick and saucy (about 1 to 2 minutes).","images":[],"step":8},{"description":"Serve with rice.","images":[],"step":9}]', '["gluten","peanuts","sesame","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese","Japanese"],"categories":["asian-recipes","beef-mince-recipes","beef-recipes","dinner-tonight","lentil-recipes","main-dishes","pork-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_53e78a1a8d04', 'en', 'US', 'Chinese Stir Fried Noodles Guide', 'A guide to make-your-own stir fried noodles using my Real All Purpose Chinese Stir Fry Sauce which can be made ahead and stored in the fridge for weeks! The measurements are for a single serving, but note that the recipe for the Sauce (separate post) makes a decent size batch for 12 servings.', 'https://www.recipetineats.com/tachyon/2016/02/Spicy-Beef-Hokkien-Stir-Fry_2.jpg', 10, 5, 15, 1, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.2, "unit": "pack of 500g"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_proteins", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_vegetables", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_real_all_purpose_chinese_stir_fry_sauce", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_base_flavouring_your_choice", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_extra_flavourings_your_choice", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["100g/3.5oz fresh noodles (Note 1)","75g / 2.5oz dried noodles (, prepared per packet (Note 2))"],"purpose":"Noodles - choose fresh or dried:"},{"ingredients":["2 tbsp oil","1/2 cup (3 oz / 75g) proteins","2 cups vegetables (, chopped packed cups))","2 tbsp Real All Purpose Chinese Stir Fry Sauce (click through for recipe)","1/4 cup (65ml) water (4 tbsp)","Base Flavouring - your choice (see below)","Extra Flavourings (optional) - your choice (see below)"],"purpose":"Add ins:"}]', '[{"description":"Prepare the protein by slicing them against the grain into 1/4\" / 0.5cm slices or 2/3\" / 2cm cubes.","images":[],"step":1},{"description":"Heat oil in wok over high heat. When oil is hot, add Base Flavouring of choice and stir fry for about 10 seconds - don''t let them burn!","images":[],"step":2},{"description":"Add ingredients in order of length of time to cook, starting with those that take the longest but do not add leafy greens. Start with onion and proteins (together), followed by broccoli and other vegetables in \"floret\" form, followed by carrots, stems of leafy greens, zucchini, eggplant, beans and other firm vegetables, and lastly cabbage and snow peas and other vegetables that take little time to cook. DO NOT add bean sprouts or leafy greens - you will add them in the next step.","images":[],"step":3},{"description":"Remove from heat, add leafy greens (leafy part of bok choy, spinach etc) and bean sprouts (if using), the noodles (use your fingers to break them up), the Sauce, water and Extra Flavours (optional).","images":[],"step":4},{"description":"Return to heat, gently toss for 1 minute to heat through the noodles and for the sauce to thicken. If the water evaporates too quickly, add a bit more.","duration":1,"images":[],"step":5},{"description":"Serve immediately.","images":[],"step":6},{"description":"Base Flavourings (choose any, none or all)","images":[],"step":7},{"description":"Garlic clove, finely chopped (don''t use garlic crusher)","images":[],"step":8},{"description":"Ginger, finely chopped (1 tsp)","images":[],"step":9},{"description":"Birds eye chilli, finely chopped (1/4 to 1/2 tsp) (to your taste)","images":[],"step":10},{"description":"Extra Flavourings (choose any, none or all)","images":[],"step":11},{"description":"Sriracha, Chilli Bean Paste or other Spicy addition (1 tsp)","images":[],"step":12},{"description":"Sweet chilli sauce (1 tbsp)","images":[],"step":13},{"description":"Substitute some or all of the water with pineapple or orange juice","images":[],"step":14},{"title":"Rice vinegar","description":"for a touch of tartness (1 tsp)","images":[],"step":15},{"description":"Fresh cilantro / coriander leaves, or thai basil (2 tbsp)","images":[],"step":16},{"description":"Garlic or ordinary chives, chopped (2 tsp)","images":[],"step":17},{"description":"Pinch of Chinese five spice powder","images":[],"step":18}]', '[]', '["gluten_free","high_protein","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","chinese-recipes","most-popular","noodles","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3f2d55da0d31', 'en', 'US', 'Real Chinese All Purpose Stir Fry Sauce (Charlie!)', 'My secret weapon for mid week meals - an All Purposes Chinese Stir Fry Sauce, a versatile base that makes a wonderfully glossy sauce for any stir fry, including stir fried noodles. Affectionately named Charlie (read in post for why!), store him in the fridge and he''ll be there when you need him. Just add water!Makes 1 1/2 cups of sauce which is enough for around 12 servings.', 'https://www.recipetineats.com/tachyon/2014/06/Stir-Fry-Sauce.jpg', 2, 0, 2, 1, '[{"id": "ing_soy_sauce", "quantity": {"value": 0.5, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.5, "unit": "bottle of 250ml"}}, {"id": "ing_wine", "quantity": {"value": 0.083, "unit": "bottle of 750ml"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.094, "unit": "pack of 400g"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.3, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}]', '[{"ingredients":["1/2 cup light soy sauce ( (Note 1))","1/2 cup oyster sauce","1/4 cup Chinese wine (or dry sherry) (Note 5)","1/4 cup cornstarch / cornflour","1 tbsp sugar","2 tbsp sesame oil (, toasted)","1 tsp ground white pepper (I sometimes use 1 tbsp, I like the spiciness!)"]}]', '[{"description":"Combine ingredients in a jar and shake to combine. Store in fridge and shake before use.","images":[],"step":1},{"description":"Amount to Use (Note 6):","images":[],"step":2},{"title":"Stir Fry","description":"I use 3 tbsp Stir Fry Sauce + 6 tbsp water to make a stir frying for 2 people using around 5 cups of uncooked ingredients (proteins + vegetables).","images":[],"step":3},{"title":"Noodles: I use 3 tbsp of the Stir Fry sauce + 5","description":"6 tbsp water to make a noodle stir fry for 2 people using around 7 cups of the combined stir fry uncooked (vegetables - packed, proteins + noodles - if using).","images":[],"step":4},{"title":"By weight (Noodles & Stir Fry)","description":"Around 3 tbsp Stir Fry Sauce per 1 lb / 500g of combined ingredients (proteins + vegetables + noodles if using) plus 1/3 cup water.","images":[],"step":5},{"description":"Heat 2 tbsp oil in wok over high heat.","images":[],"step":6},{"title":"Add your choice of Base Flavourings","description":"fry for 10 seconds or so to infuse oil.","duration":0.16666666666666666,"images":[],"step":7},{"description":"Add stir fry ingredients in order of time to cook (starting with ingredients that take longest to cook), leaving leafy greens, like the leaves of bok choy, until when you add the sauce (otherwise they will wilt and overcook).","images":[],"step":8},{"description":"Add noodles (if using), sauce and water, your choice of Additional Flavourings and any leafy greens.","images":[],"step":9},{"description":"Gently toss to combine and to let the sauce cook for around 1 minute. The sauce will become a thick, glossy sauce that coats your stir fry.","images":[],"step":10},{"title":"Serve immediately with rice","description":"or for a low carb, low cal option, try Cauliflower Rice!","images":[],"step":11},{"description":"Base Flavourings","images":[],"step":12},{"description":"Garlic, minced or finely sliced","images":[],"step":13},{"description":"Ginger, minced or finely sliced","images":[],"step":14},{"description":"Fresh chillies, minced or finely sliced","images":[],"step":15},{"description":"Additional Flavouring Suggestions","images":[],"step":16},{"description":"Sriracha, Chilli Bean Paste or other Spicy addition","images":[],"step":17},{"description":"Sweet chilli sauce","images":[],"step":18},{"description":"Substitute the water with pineapple or orange juice","images":[],"step":19},{"title":"Rice vinegar","description":"for a touch of tartness","images":[],"step":20},{"title":"Fresh cilantro / coriander leaves, or thai basil","description":"for freshness","images":[],"step":21},{"description":"Garlic or ordinary chives, chopped","images":[],"step":22},{"description":"Pinch of Chinese five spice powder","images":[],"step":23}]', '["gluten","sesame","soy"]', '["keto_friendly","low_calorie","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","chinese-recipes","most-popular","quick-and-easy","quick-dinner-ideas-15-minute-meals","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3b426a11fb45', 'en', 'US', '8 simple Italian Pasta Recipes', 'These pasta recipes are simple Italian classics you''ll find in trattorias all across Italy. “Pantry” meals that take less than 15 minutes to make, each makes enough for 6 people. For all recipes, follow the Base Steps then move onto the recipe specific steps.Use the recipe slider to change the serving size. Key step (especially for simple pastas like these) - tossing the sauce with the cooked pasta and a splash of pasta cooking water. The fat in the sauce reacts with the starch in the cooking water, thickening the sauce and making it stick to the pasta strands. This is the proper way to make pasta - no self respecting Italian or restaurant would ever skip this step!', 'https://www.recipetineats.com/tachyon/2014/06/Pasta1.jpg', 5, 15, 20, 6, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.907, "unit": "pack of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_chilli", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_canned_tomatoes", "quantity": {"value": 1.488, "unit": "can of 400g"}}, {"id": "ing_chilli", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_anchovies", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_thinly_guanciale", "quantity": {"value": 0.17, "unit": "kg"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 2.722, "unit": "punnet of 250g"}}, {"id": "ing_basil", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_black_olives", "quantity": {"value": 113.4, "unit": "bottle"}}, {"id": "ing_capers", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_tinned_tuna", "quantity": {"value": 141.75, "unit": "pack"}}]', '[{"ingredients":["1 lb/500 g dried spaghetti (or other long pasta)"]},{"ingredients":["1/2 cup extra virgin olive oil","10 garlic cloves (, sliced)","1 tbsp red chilli flakes","1/4 cup chopped parsley"],"purpose":"PASTA WITH OLIVE OIL & GARLIC (AGLIO E OLIO):"},{"ingredients":["1/4 cup extra virgin olive oil","2 garlic cloves (, crushed)","21 oz / 600g crushed tinned tomatoes","2 tbsp chilli flakes","1/4 cup chopped parsley"],"purpose":"FIERY PASTA (ARRABIATA):"},{"ingredients":["1/3 cup extra virgin olive oil","2 garlic cloves (, crushed)","2 tbsp anchovies (, finely chopped)","1 tbsp red chilli flakes","1/4 cup chopped parsley"],"purpose":"PASTA WITH ANCHOVIES (SPAGHETTI CON LE ACCIUGHE):"},{"ingredients":["2 tbsp extra virgin olive oil","2 garlic cloves (, crushed)","1/2 brown onion (, diced)","14 oz/400g crushed tinned tomatoes","1/2 tsp red chilli flakes","6 oz/ 180g thinly sliced guanciale (, or diced pancetta or bacon)"],"purpose":"AMATRICE SPAGHETTI (SPAGHETTI ALL’AMATRICIANA):"},{"ingredients":["4 tbsp extra virgin olive oil","2 garlic cloves (, crushed)","24 oz/800g fresh cherry tomatoes (, halved)","1/4 cup fresh basil (, lightly packed)"],"purpose":"FRESH TOMATO & BASIL SAUCE (POMAROLA):"},{"ingredients":["1/4 cup olive oil","3 garlic cloves (, crushed)","1 brown onion (, diced)","28 oz / 800g crushed tinned tomatoes","1/4 cup fresh basil (, lightly packed)"],"purpose":"TOMATO SPAGHETTI (SPAGHETTI NAPOLITANA):"},{"ingredients":["1/4 cup extra virgin olive oil","2 garlic cloves (, crushed)","14 oz/400g crushed tinned tomatoes","1/2 tbsp red chilli flakes","4 oz/100g black sliced olives","2 tbsp capers","1/4 cup chopped parsley"],"purpose":"SPAGHETTI WITH OLIVES AND CAPERS (SPAGHETTI ALLA PUTTANESCA):"},{"ingredients":["1/4 cup extra virgin olive oil","2 garlic cloves (, crushed)","1/2 brown onion (, diced)","14 oz/400g crushed tinned tomatoes","5 oz/150g tinned tuna","1/4 cup chopped parsley"],"purpose":"PASTA WITH TUNA (SPAGHETTI AL TONNO):"}]', '[{"description":"Base Directions (for All):","images":[],"step":1},{"description":"Cook 1lb/500g of dried spaghetti (or any other long dried pasta) in a large pot of salted boiling water per packet MINUS 1 minute.","images":[],"step":2},{"description":"Meanwhile, prepare one of the sauces below.","images":[],"step":3},{"description":"When pasta is ready, scoop out 1 cup of pasta cooking water, and drain pasta.","images":[],"step":4},{"description":"Add pasta into chosen sauce with 3/4 cup pasta cooking water. Toss pasta until sauce thickens and sticks to pasta (called \"emulsifying\" the sauce), 1 - 2 minutes. Use more pasta water if needed to loosen sauce.","images":[],"step":5},{"description":"Season with salt and pepper to taste. Finish pasta per chosen recipe.","images":[],"step":6},{"description":"PASTA WITH OLIVE OIL & GARLIC (AGLIO E OLIO):","images":[],"step":7},{"description":"Heat oil over medium high heat. Add garlic and cook until golden - be careful not to burn it.","images":[],"step":8},{"description":"Toss with pasta and cooking water per Base Directions. Toss through parsley and chilli flakes, serve with parmesan.","images":[],"step":9},{"description":"Heat oil over medium high heat. Add garlic, stir until fragrant, then add the tinned tomatoes and chilli flakes, simmer on medium for 5 minutes.","duration":5,"images":[],"step":10},{"description":"Toss with pasta and cooking water per Base Directions. Toss through parsley and serve with parmesan.","images":[],"step":11},{"description":"PASTA WITH ANCHOVIES (SPAGHETTI CON LE ACCIUGHE):","images":[],"step":12},{"description":"Heat oil over medium high heat. Add garlic and anchovies, stir until the garlic is fragrant and the anchovies have melted.","images":[],"step":13},{"description":"Toss with pasta and cooking water per Base Directions. Toss through parsley and chilli flakes, and serve with parmesan.","images":[],"step":14},{"description":"AMATRICE SPAGHETTI (SPAGHETTI ALL’AMATRICIANA):","images":[],"step":15},{"description":"Heat oil over medium high heat. Add the garlic, onion and guanciale (or pancetta or bacon) and cook until the onion has softened and the guanciale is golden.","images":[],"step":16},{"description":"Add the tinned tomatoes and chilli flakes and bring to rapid simmer. Toss with pasta and cooking water per Base Directions. Serve with parmesan.","images":[],"step":17},{"description":"Heat oil over medium high heat. Add garlic and cook until fragrant, add tomato and cook briefly, just to warm through.","images":[],"step":18},{"description":"Toss with pasta and cooking water per Base Directions. Toss through basil, serve with parmesan.","images":[],"step":19},{"description":"TOMATO SPAGHETTI (SPAGHETTI NAPOLITANA):","images":[],"step":20},{"description":"Heat oil over medium high heat. Add garlic and cook until fragrant, then add the onion and cook until softened. Then add tinned tomatoes and 1/2 cup water, simmer 5 minutes.","images":[],"step":21},{"description":"Toss with pasta and cooking water per Base Directions. Toss through basil and serve with parmesan.","images":[],"step":22},{"description":"SPAGHETTI WITH OLIVES AND CAPERS (SPAGHETTI ALLA PUTTANESCA):","images":[],"step":23},{"description":"Heat oil over medium high heat. Add garlic and cook until fragrant, then add tinned tomatoes, chilli flakes, olives, capers and 1/2 cup water. Simmer 3 minutes.","images":[],"step":24},{"description":"Toss with pasta and cooking water per Base Directions. Toss through parsley and serve with parmesan.","images":[],"step":25},{"description":"Heat oil over medium high heat. Add garlic and cook until fragrant. Add the onion and cook until softened, then add the tinned tomatoes and 1/2 cup water. Simmer 3 minutes, then add the tuna.","images":[],"step":26},{"description":"Toss with pasta and cooking water per Base Directions. Toss through parsley. Seafood pasta typically not served with parmesan but you can if you want!","images":[],"step":27}]', '["fish","gluten"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["italian-recipes","most-popular","pasta-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_fb7050190106', 'en', 'US', 'Fragrant Chickpea Rice Pilaf', 'A very simple, delicately fragranced chickpea rice that is simple to make with minimal prep - no chopping! The addition of herbs, sultanas and crunchy pieces of shallots make this really special. I love this dish so much I can eat it plain - it certainly has plenty of flavour. It only needs to be accompanied with a simple piece of grilled fish or roasted vegetables and you have yourself a complete, satisfying, wonderful meal.', 'https://www.recipetineats.com/tachyon/2014/06/DSC_01091.jpg', 5, 10, 15, 6, '[{"id": "ing_basmati_rice", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.5, "unit": "can of 400g"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_garam_masala", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_sultanas", "quantity": {"value": 0.25, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.5, "unit": "bunch"}}]', '[{"ingredients":["1 cup uncooked basmati rice (or long grain or wild rice)","1 1/2 cups water (Note 2)","1/2 tsp cooking salt / kosher salt"],"purpose":"Basmati rice"},{"ingredients":["1 1/2 tins (21 oz / 600g) chickpeas (, drained, but still wet)","1/4 tsp cooking salt / kosher salt","1 tsp ground cumin","1 tsp garam masala (Note 1 for substitutions)","1 tbsp olive oil","1/4 cup parsley leaves"],"purpose":"Spiced chickpeas"},{"ingredients":["1/4 cup coriander / cilantro leaves","1/4 cup sultanas or currents","Black pepper","1/2 cup fried shallots (, store bought (Note 3))"],"purpose":"Add-ins"}]', '[{"title":"Steam rice","description":"Combine rice, water and 1/2 tsp salt in a medium saucepan over high heat. Bring to the boil (without the lid), then put the lid on and immediately turn the heat down to medium low (or low, for large burners). Simmer with the lid on for 12 minutes or until the water is absorbed. No stirring, no peeking! Remove from the heat (lid still on) and let it rest for 10 minutes - it will absorb the remaining water.","duration":12,"images":[],"step":1},{"title":"Spiced chickpeas","description":"While rice is cooking, combine chickpeas, 1/4 tsp salt, cumin and garam masala in a bowl, toss to coat. Heat 1 tbsp olive oil in large pan over high heat, add the chick peas and shake the pan every now and then for 1 minute. Alternatively, you can roast them in the oven at 350F/180C for 5 minutes. Set aside - you can leave them in the pan if you want.","duration":1,"images":[],"step":2},{"title":"Toss","description":"After the rice has rested, combine with the chickpeas, parsley, coriander and sultanas, and a grind of black pepper. Some of the spice on the chickpeas will come off and disperse throughout the rice - this is supposed to happen. Adjust salt if necessary.","images":[],"step":3},{"description":"Lastly, toss through the crispy shallots. Serve warm or at room temperature.","images":[],"step":4}]', '[]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Middle Eastern"],"categories":["cuisines","lentil-recipes","middle-eastern-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","rice-recipes","rice-side-dishes","side-dishes","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f3382beb2b5f', 'en', 'US', 'Vegetarian Chow Mein', 'This vegetarian/vegan version of chow mein is very close to the traditional version, but I have created a sauce without oyster sauce in it - and obviously substituted the meat with tofu. This recipe contains directions to make this from scratch as well as the directions for making this using my Real Chinese All Purpose Stir Fry Sauce (Vegetarian version) which, if you have a stash of it on hand, makes this super quick to make because you already have the sauce ready made!', 'https://www.recipetineats.com/tachyon/2014/06/Vegetarian-Chow-Mein-3-Version-2.jpg', 10, 5, 15, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.34, "unit": "pack of 500g"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_cabbage", "quantity": {"value": 6.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 75.0, "unit": "pack of 1kg"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 1.0, "unit": "bag of 250g"}}, {"id": "ing_tofu", "quantity": {"value": 0.472, "unit": "pack of 300g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 7.5, "unit": "bottle"}}, {"id": "ing_chilli", "quantity": {"value": 0.075, "unit": "pack of 100g"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["6 oz / 180 g fresh chow mein noodles","2 tbsp oil","2 garlic cloves (, minced)","2 cups shredded Chinese cabbage","1/2 cup carrot (, julienned)","2 scallion/shallot stems (, cut into 2\"/4cm pieces)","1 cup bean sprouts"]},{"ingredients":["5 oz / 150 g firm tofu (, sliced)","1 1/2 tbsp soy sauce","1 tbsp Chinese cooking wine"],"purpose":"Tofu and marinade"},{"ingredients":["1/2 tbsp hoisin sauce","1 1/2 tbsp soy sauce","1/2 tbsp chilli garlic sauce or sriracha (optional)","2 tsp sugar","1/2 tsp sesame oil","1/4 cup water","White pepper"],"purpose":"Sauce"}]', '[{"description":"Prepare noodles according to packet instructions (usually soaking it in boiling water).","images":[],"step":1},{"description":"Combine tofu with marinade and set aside for 5 minutes.","duration":5,"images":[],"step":2},{"description":"Combine sauce ingredients in a small bowl.","images":[],"step":3},{"description":"Heat oil in wok over high heat, add garlic and stir fry for 10 seconds.","duration":0.16666666666666666,"images":[],"step":4},{"description":"Add tofu and stir fry until starting to caramelise - about 1 minute. Stir fry gently so the tofu doesn''t break.","images":[],"step":5},{"description":"Add the cabbage and carrot and stir fry until the cabbage starts to wilt.","images":[],"step":6},{"description":"Add the noodles, scallions/shallots, bean sprouts and sauce and stir fry until the noodles are warmed through and sauce evenly coats the noodles - about 1 minute. Don''t cook it too much - the bean sprouts should still be quite crisp, not wilted.","images":[],"step":7},{"description":"Serve immediately.","images":[],"step":8},{"description":"Directions using homemade Real Chinese All Purpose Stir Fry Sauce","images":[],"step":9},{"description":"If you have a jar of homemade Real Chinese All Purpose Stir Fry Sauce, you do not need to make the marinade or sauce for this recipe.","images":[],"step":10},{"description":"Substitute the tofu marinade with 1 tbsp Stir Fry Sauce","images":[],"step":11},{"description":"Substitute the Sauce ingredients with 1/4 cup Stir Fry Sauce and 1/4 cup water.","images":[],"step":12}]', '["gluten","sesame","soy"]', '["low_calorie","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","noodles","quick-and-easy","quick-dinner-ideas-15-minute-meals","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d38d0216d61d', 'en', 'US', 'Cinnamon Sugar Tortilla Crisps', 'Sweet treats in a flash!', 'https://www.recipetineats.com/tachyon/2014/06/DSC_0091-680x680-1.jpg', 5, 5, 10, 48, '[{"id": "ing_tortillas", "quantity": {"value": 3.0, "unit": "pack of 8"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_cinnamon", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_sugar", "quantity": {"value": 0.03, "unit": "kg"}}]', '[{"ingredients":["3 tortillas","2 tbsp butter (, spreadable)","1/2 tsp cinnamon","2 tbsp sugar"]}]', '[{"description":"Preheat oven to 350F/180C.","images":[],"step":1},{"description":"Spread butter onto each tortilla, like you are buttering toast. Alternatively, melt the butter and brush onto tortillas.","images":[],"step":2},{"description":"Sprinkle generously with cinnamon sugar.","images":[],"step":3},{"description":"Stack the tortillas, then cut into strips, or triangles.","images":[],"step":4},{"description":"Spread in a single layer on a baking tray (3 tortillas should almost perfectly fit).","images":[],"step":5},{"description":"Bake for 5 to 8 minutes until golden and crisp.","duration":6.5,"images":[],"step":6},{"description":"Eat warm or at room temperature.","images":[],"step":7}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":[],"categories":["baking-recipes","bite-size-desserts","dessert-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ef4dfc9f301b', 'en', 'US', 'Dan Dan Noodle Soup (Vegetarian)', 'This Chinese noodle soup is a flavour explosion in a bowl, is <300 cal per serving and only takes just over 10 minutes to make. It is spicy, salty and slightly sour with the fragrance of sesame, with a thicker soup than the usual clear noodle soup stocks and I love the creamy colour and texture which comes from the sesame paste (or tahini), corn starch and the starch from cooking the noodles in the stock. Substitute the vegetables with whatever you have on hand and use whatever noodles you want.', 'https://www.recipetineats.com/tachyon/2014/06/DSC_0038.jpg', 5, 10, 15, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.8, "unit": "pack of 500g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 1.25, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1000.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_flour", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.3, "unit": "pack of 100g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_chilli", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.3, "unit": "pack of 100g"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_bok_choy", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_broccoli", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 1.5, "unit": "bag of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["400 g dried rice stick noodles (see notes)"]},{"ingredients":["4 cups (32 oz/1 litre) vegetable or chicken stock (broth)","5 cups water","3 large garlic cloves (, minced)","2 tsp minced ginger","2 tsp sugar"],"purpose":"Stock"},{"ingredients":["3 tbsp soy sauce","2 tsp cornflour / corn starch","2 Tbsp sesame paste or tahini","4 tbsp black vinegar (see notes)","2 tsp chilli bean sauce ((or substitute with another chilli paste or sauce). Adjust to taste!)","1 1/2 tsp sesame oil"],"purpose":"Stock Sauce"},{"ingredients":["2 medium carrots (, peeled and sliced diagonally)","4 bok choy","2 cups broccoli florets"],"purpose":"Toppings (see notes)"},{"ingredients":["1 1/2 cups bean sprouts","1 scallion / shallot (, chopped)"],"purpose":"Garnish"}]', '[{"description":"Combine stock ingredients in a large pot and bring to boil.","images":[],"step":1},{"description":"Meanwhile, mix the Stock Sauce ingredients together in a small bowl and cut all the vegetables into bite size pieces.","images":[],"step":2},{"description":"Add the Stock Sauce and mix well to dissolve into the soup. Adjust seasoning as required.","images":[],"step":3},{"description":"When the stock comes to a boil, place rice stick noodles in the stock, then 1 minute later add the carrots and broccoli, then 1 minute later remove from heat and add the bok choy stems.","images":[],"step":4},{"description":"Divide the noodles and vegetables between bowls, top with the bok choy leaves and bean sprouts.","images":[],"step":5},{"description":"Ladle soup into bowls over the vegetables and noodles, and garnish with spring onions.","images":[],"step":6},{"title":"Optional","description":"finish with chilli oil and more chilli paste - if you can handle the heat!","images":[],"step":7}]', '["gluten","sesame","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","main-dishes","noodles","quick-dinner-ideas-15-minute-meals","soup-recipes","vegan-lifestyle","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cca29b767b34', 'en', 'US', 'Mexican Couscous Express', 'The most ridiculously easy and fast mid week meal that''s darn tasty and wonderfully light. Feel free to ramp up the toppings - I just added some diced avocado and tomato to keep it fresh, but I also have it with a dollop of source cream and grated cheese. And I have also been known to add crispy tortilla chips too….', 'https://www.recipetineats.com/tachyon/2014/06/Express-Mexican-Couscous-3-Version-21.jpg', 10, 0, 10, 4, '[{"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_couscous", "quantity": {"value": 150.0, "unit": "pack"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_jalape_o", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_black_beans", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_corn", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_avocado", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}]', '[{"ingredients":["1 1/2 tsp salt","2 tsp cumin powder","1 tsp onion powder","1 cup couscous","1 cup boiling water","1/4 cup tomato paste","1 tbsp diced jalapeño (fresh is better, but tinned also ok)","2 scallions (shallots), roughly sliced (optional)","1 can (15 oz / 400 g) black beans (or red kidney beans)","1 can (15 oz / 400 g) corn kernels","Handful of coriander / cilantro"]},{"ingredients":["1 tomato (, deseeded and diced)","1/2 avocado (, diced)","Sour cream","Grated cheese"],"purpose":"Optional"}]', '[{"description":"Place salt, cumin, onion powder and couscous in a bowl, quickly toss to combine.","images":[],"step":1},{"description":"Add boiling water, cover and set aside for 5 minutes.","duration":5,"images":[],"step":2},{"description":"Fluff with fork, add tomato paste and stir to evenly coat the couscous.","images":[],"step":3},{"description":"Add remaining ingredients.","images":[],"step":4},{"description":"Serve with optional toppings.","images":[],"step":5}]', '["gluten","milk"]', '["vegetarian"]', '{"mealType":["main_course"],"cuisine":["Mexican"],"categories":["lentil-recipes","mexican-recipes","pasta-recipes","pork-carnitas","quick-and-easy","quick-dinner-ideas-15-minute-meals","side-dishes","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_705e380679e7', 'en', 'US', 'Watermelon Salad', 'As strange as it sounds, sweet, juicy watermelon with feta, red onion and mint is a winning combination. This summery, light salad is refreshing and is perfect for a summer barbeque.', 'https://www.recipetineats.com/tachyon/2014/05/Watermelon-Salad-v2.jpg', 10, 0, 10, 4, '[{"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_vinegar", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.075, "unit": "L"}}, {"id": "ing_mint", "quantity": {"value": 1.5, "unit": "bunch"}}, {"id": "ing_cheese", "quantity": {"value": 75.0, "unit": "block of 250g"}}, {"id": "ing_mint", "quantity": {"value": 1.5, "unit": "bunch"}}]', '[{"ingredients":["1 kg / 2 lbs watermelon","1 small Spanish red onion (, finely sliced)","3 tbsp red wine vinegar","Salt and pepper","5 tbsp extra virgin olive oil","1 1/2 tbs fresh mint (, roughly chopped)","75 g / 3 oz Danish feta cheese (, crumbled into medium size pieces)","Whole mint sprigs (, to garnish)"]}]', '[{"description":"Cut the flesh from the melon and cut into bite size pieces, removing and discarding the seeds, and set aside. Peel and halve the onion, and thinly slice.","images":[],"step":1},{"description":"In a small bowl, combine the vinegar, salt, pepper, and whisk until salt is dissolved. Slowly whisk in the olive oil, a few drops at a time. Add in the chopped mint, taste, and adjust seasonings.","images":[],"step":2},{"description":"In a large bowl, combine the melon, onion, and feta. Pour the dressing over the melon mixture and toss gently until everything is coated and evenly mixed. Garnish with mint sprigs.","images":[],"step":3}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Italian"],"categories":["italian-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e6c2950c51df', 'en', 'US', 'Muffin Tin Spaghetti Nests (Using Leftover Pasta)', 'This is a great way to use up leftover pasta - you can use any type, whether it''s tomato or cream based. It''s kid friendly, and you can use it as an opportunity to add hidden vegetables, like grated carrot and zucchini. You can also freeze it - it reheats well in both the oven and microwave.', 'https://www.recipetineats.com/tachyon/2014/05/Spaghetti-Muffin-Tin-2-Version-2.jpg', 5, 10, 15, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}]', '[{"ingredients":["Leftover pasta and sauce mixed together","1 egg per 3 packed cups of pasta (see notes)","Grated melting cheese"]}]', '[{"description":"Preheat oven to 350F/180C.","images":[],"step":1},{"description":"Mix the egg and pasta together.","images":[],"step":2},{"description":"Spray muffin tins with oil, then pack tightly with pasta. If you don''t pack the pasta in, it will fall apart.","images":[],"step":3},{"description":"Bake until the pasta goes crunchy and golden on top - around 5 to 8 minutes.","images":[],"step":4},{"description":"Remove from oven and sprinkle on cheese, then return to oven until cheese melts.","images":[],"step":5}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["snack"],"cuisine":[],"categories":["australia-day","pasta-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d7df16be1ba7', 'en', 'US', 'Taco Seasoning', 'Homemade taco seasoning is so much healthier than store bought - it''s preservative free, less artificial tasting and is a fraction of the cost. This recipe makes enough taco seasoning for 1lbs/500g of meat. I also use this for Quesadilla Fillings.', 'https://www.recipetineats.com/tachyon/2014/05/Taco-Seasoning.jpg', 5, 0, 5, 4, '[{"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_chilli", "quantity": {"value": 0.013, "unit": "pack of 100g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["1 tsp garlic powder","1 tsp onion powder","1 tsp dried oregano","2 tsp cumin powder","2 tsp paprika","1/4 tsp chilli powder (adjust spiciness to taste)","1 tsp salt","1/4 tsp black pepper"]}]', '[{"description":"Combine ingredients.","images":[],"step":1},{"description":"Store in an airtight container.","images":[],"step":2},{"description":"Makes 2.5 tablespoons. Combine with 1lbs/500g mince meat, 1/2 cup water, 1 diced onion and 2 tablespoons of tomato paste.","images":[],"step":3}]', '[]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Mexican"],"categories":["mexican-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","taco-recipes","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5a536db8fdcf', 'en', 'US', 'Enchilada Sauce - Classic', 'Enchilada sauce can make or break an enchilada dish. And homemade is always best! There are a lot of enchilada sauce recipes out there - this one is a classic essential.', 'https://www.recipetineats.com/tachyon/2014/05/Enchilada-Sauce_no-text1.jpg', 3, 12, 15, 3, '[{"id": "ing_vegetable_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}]', '[{"ingredients":["1/4 cup vegetable oil","1/4 cup flour (all purpose / plain)","700 g / 24oz tomato passata (1 bottle) or 16 oz (2 cans) US tomato sauce","1 1/2 cups chicken broth, low sodium (or vegetable broth, or water + bouillon cube)","1 tbsp dried oregano","2 tsp cumin","2 tsp paprika","1 tsp garlic powder","1 tsp onion powder","1 tbsp brown sugar","Salt and pepper to taste","Optional extras: cayenne pepper (for spiciness), ground chipotle"]}]', '[{"description":"Heat oil in a saucepan over medium heat.","images":[],"step":1},{"description":"Add flour and whisk until well combined, about 1 minute.","images":[],"step":2},{"description":"Add remaining ingredients except salt and pepper, whisk, bring to boil, then reduce to simmer.","images":[],"step":3},{"description":"Simmer for 10 minutes or so, until thickened, whisking occasionally.","duration":10,"images":[],"step":4},{"description":"Season with salt and pepper.","images":[],"step":5},{"description":"This can be stored for up to 1 week in the refrigerator in an airtight container. It also freezes well.","images":[],"step":6}]', '["gluten"]', '[]', '{"mealType":["main_course"],"cuisine":["Mexican"],"categories":["enchiladas","mexican-recipes","most-popular","quick-and-easy","quick-dinner-ideas-15-minute-meals","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_767427e914ec', 'en', 'US', 'Tomato and Artichoke Salad with Capers', 'An elegant dish that takes minutes to prepare and turns the humble tomato into something really special. The great thing about this dish is that it really enhances the flavour of even the most ordinary tomato so you don''t need bursting-with-flavour-organic-locally-grown tomatoes - in fact, turning the ordinary store bought tomato into something really special is exactly what this dish does.', 'https://www.recipetineats.com/tachyon/2014/05/DSC_0059-680x680-1.jpg', 5, 0, 5, 2, '[{"id": "ing_tomato", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_baby_capers", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_few_tinned_artichokes", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_onion", "quantity": {"value": 0.25, "unit": "pack of 1kg"}}, {"id": "ing_chilli_flakes", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["3 to 4 tomatos (, sliced into 1/3\"/0.5cm slices)","1 tbsp baby capers (, or ordinary capers roughly chopped)","Few tinned artichokes (, roughly chopped)","1/4 red spanish onion (, finely sliced)","1 1/2 tsp salt flakes","Fresh pepper","2 tbsp olive oil","1/2 lemon (, juice only)","2 tbsp fresh oregano leaves (or other herb of your choice)"]}]', '[{"description":"Lay tomatoes on a plate, slightly overlapping.","images":[],"step":1},{"description":"Scatter with capers, artichokes and red onion.","images":[],"step":2},{"description":"Scatter with salt and pepper.","images":[],"step":3},{"description":"Scatter with oregano leaves.","images":[],"step":4},{"description":"Drizzle with olive oil and juice of the 1/2 lemon.","images":[],"step":5},{"description":"Leave for 5 minutes so the salt makes the juices of the tomato seep. Do not leave for too much longer otherwise the salt will draw too much of the tomato juices out!","duration":5,"images":[],"step":6}]', '[]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["lunch"],"cuisine":[],"categories":["all-vegetable-sides","easter-sides-fresh-light","italian-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","side-salads","tomato","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_be6b9689977a', 'en', 'US', 'Creamy Feta Dressing with Iceberg Wedges', 'This creamy feta dressing is lighter than blue cheese dressing and just as delicious. Put your own touch on it using whatever herbs you have - this dressing is extremely versatile and will suit most herbs, even mint. To make this recipe a dip instead of a dressing, just reduce the quantity of milk. This recipe makes just under 2 cups of dressing and serves 4 to 6. It can be stored in the refrigerator for up to a week - it will thicken so loosen it up with a touch of milk.', 'https://www.recipetineats.com/tachyon/2014/05/DSC_0014-Version-21-680x1024-1.jpg', 10, 0, 10, 4, '[{"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_feta_cheese", "quantity": {"value": 0.5, "unit": "block of 200g"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.188, "unit": "jar of 400g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.075, "unit": "tub of 500g"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.833, "unit": "pack of 3 heads"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1 iceberg lettuce","1/2 cup (packed) crumbled feta (preferably Danish or another soft feta)","1/2 cup whole egg mayonnaise","1/4 cup plain yoghurt","1/2 to 3/4 cup milk (use milk to adjust consistency)","Juice of half a lemon","1/2 clove garlic (, crushed, or 1 tsp garlic powder)","1 tbsp chopped fresh oregano","Salt and pepper to taste"]}]', '[{"description":"Cut the iceberg lettuce into 8 wedges, being careful to cut evenly through the centre of the core so each wedges holds together.","images":[],"step":1},{"description":"Combine the feta and mayonnaise into a medium size bowl and use a fork to mash it into a paste. If you use a creamier feta - like Danish - it will be easier to mash into a smooth paste.","images":[],"step":2},{"description":"Add the yoghurt, half the milk, lemon juice, garlic and oregano, and whisk vigorously to make the dressing smooth.","images":[],"step":3},{"description":"Use the remainder of the milk to get the consistency to your taste. I like mine reasonably thick so it sticks to the lettuce. If you make it thinner, it is suitable for tossing through salads.","images":[],"step":4},{"description":"Season to taste. Always season last because the saltiness of fetas and mayonnaise differ.","images":[],"step":5},{"description":"Place 1 or 2 wedges onto each plate and drizzle dressing to serve.","images":[],"step":6}]', '["egg","milk"]', '["gluten_free","vegetarian"]', '{"mealType":["lunch"],"cuisine":[],"categories":["quick-and-easy","quick-dinner-ideas-15-minute-meals","side-salads","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a561220079d7', 'en', 'US', 'Sticky Pantry Chicken Thigh recipe', 'I call this Sticky Pantry Chicken because you probably have most of the ingredients for the marinade in your pantry. It tastes like a fabulous country-style sauce. You''ll have this sweet, sticky chicken on the table in 15 minutes!', 'https://www.recipetineats.com/tachyon/2014/06/Sticky-Pantry-Chicken_3.jpg', 5, 10, 15, 4, '[{"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 6.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_ketchup", "quantity": {"value": 0.1, "unit": "bottle of 500g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_hot_sauce", "quantity": {"value": 0.2, "unit": "bottle of 150ml"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_honey", "quantity": {"value": 0.075, "unit": "jar of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}]', '[{"ingredients":["1 tbsp oil (for frying)","6 (1.5-2lb / 750g-1kg) chicken thigh fillets (, boneless skinless)","1/2 tsp cooking/kosher salt","1/2 tsp black pepper","1/2 cup water"]},{"ingredients":["1/3 cup ketchup ( or tomato sauce (Australian))","2 tbsp soy sauce","1 tbsp dijon or American mustard","2 tbsp hot sauce (optional)","2 tbsp vinegar (any)","2 1/2 tbsp honey","2 garlic cloves (, crushed)"],"purpose":"Sauce"}]', '[{"title":"Sauce","description":"Whisk the ingredients in a medium bowl.","images":[],"step":1},{"description":"Sprinkle each piece of chicken with the salt and pepper.","images":[],"step":2},{"description":"Heat the oil in a large non-stick pan over medium high heat.","images":[],"step":3},{"title":"Coat chicken","description":"Quickly dip a piece of chicken in the Sauce, shake off excess, then place in the pan. Repeat with as many pieces of chicken as you can fit in the pan.","images":[],"step":4},{"description":"Cook the first side for 3 minutes, until it caramelises and is dark golden, then turn and cook the other side for 2 minutes until the chicken is almost cooked through.","duration":3,"images":[],"step":5},{"title":"Sauce","description":"Add the remaining Sauce and water. Bring to a rapid simmer, stirring occasionally, scraping the bottom of the pan to get all the brown bits stuck to the bottom of the pan. When the sauce has thickened (around 1 to 2 minutes), remove the pan from the stove. Turn chicken in Sauce to coat.","images":[],"step":6},{"description":"To serve, place chicken on plate and spoon over Sauce.","images":[],"step":7}]', '["gluten","mustard","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["chicken-recipes","dinner-tonight","main-dishes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e6fcbcb0b379', 'en', 'US', 'Vegetable Tian', 'Recipe video above. I love this colourful Provençal vegetable bake! It’s full of vibrant colours and lovely garlicky Mediterranean flavours, making it just as good as a side dish as it is a vegetarian main. While it feels especially at home alongside French and Mediterranean food, the flavours are so adaptable that it will happily sit beside almost any Western-style meal.Enjoy warm or at room temperature.', 'https://www.recipetineats.com/tachyon/2026/06/Vegetable-tian-5a.jpg', 30, 40, 70, 6, '[{"id": "ing_olive_oil", "quantity": {"value": 0.09, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_zucchini", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 3.0, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_herbes_de_provence", "quantity": {"value": 1.5, "unit": "unit"}}]', '[{"ingredients":["6 tbsp extra virgin olive oil","4 garlic cloves (, finely minced with a knife)","2 tbsp tomato paste","1 eggplant (aubergine), cut in half lengthways then sliced 8mm / 0.3” half moons (~380g / 13.5oz)","3 zucchini (courgette), sliced into 6mm / 0.25” rounds (~180g / 6oz each)","3 red onion (, sliced into 3mm / 0.1” rounds (~140g / 5oz each) (use a mandolin if you have one))","5 tomato (, sliced into 5mm / 0.2” rounds (~140g / 5oz each))","2 tsp cooking / kosher salt (, (or half for table salt, +50% for flakes))","1/2 tsp black pepper","1 1/2 tsp herbes de Provence"]}]', '[{"description":"Sweat the eggplant and zucchini, spread oil, tomato paste and garlic in a dish. Arrange vegetables, alternating, drizzle/sprinkle with oil, Herbs de Provence, salt and pepper. Bake 40 minutes.","images":[],"step":1},{"title":"Preheat oven","description":"Preheat oven to 200°C / 400°F (180°C fan-forced).","images":[],"step":2},{"title":"Sweat eggplant and zucchini","description":"Toss eggplant and zucchini slices in a bowl with 1 teaspoon of salt. Place them in colander over bowl to sweat and leave to drain for about 10 minutes while you slice the remaining vegetables and prepare the baking dish. (Note 2)","images":[],"step":3},{"title":"Prepare baking dish","description":"Spread 1 tbsp olive oil, tomato paste and half the garlic over the base of a ceramic baking dish (30cm x 20cm x 5cm / 12\" x 8\" x 2\"). As the vegetables bake, they will release their juices which will mix into it to create a beautiful sauce underneath.","images":[],"step":4},{"title":"Season again","description":"Give the colander a shake to remove excess water off the eggplant and zucchini (no need to pat them dry), then put them back into a bowl. A lot of salt comes off with the water, so toss with another 1/2 teaspoon of salt.","images":[],"step":5},{"title":"Layer vegetables","description":"Arrange the vegetables vertically in the dish, alternating eggplant, zucchini, onion and tomato (I do it in this order). I usually make around 14 rows (the video is very useful here). Don''t be afraid to pack the vegetables in quite tightly. They will shrink as they bake, so arranging them snugly together helps them stay upright. (Note 3)","images":[],"step":6},{"title":"Season top","description":"Drizzle all-over with remaining olive oil. Sprinkle evenly with remaining garlic, remaining 1/2 teaspoon of salt, black pepper and Herbes de Provence.","images":[],"step":7},{"title":"Bake","description":"Bake for 40 minutes until the vegetables are soft and lightly browned on the edges. Serve immediately, or leave to cool and serve at room temperature.","duration":40,"images":[],"step":8}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["French"],"categories":["all-vegetable-sides","dietary","easter-sides-warm-hearty","eggplant","gluten-free-recipes","jbs-recipes","side-dishes","tomato","vegan-lifestyle","vegetarian-recipes","zucchini","zucchini-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a8921c786e2b', 'en', 'US', 'Baby Gem Lettuce Salad', 'This is a JB salad recipe which he casually threw together one day for lunch as a side to his French Schnitzel. I loved it so much, I insisted we must publish it! It''s crisp, fresh and full of texture - crunchy croutons, juicy tomatoes and a tangy Creamy French Dressing tying it all together. And it''s so pretty too!Please take note of how this salad is build. Presentation matters! :)', 'https://www.recipetineats.com/tachyon/2026/03/French-Baby-Gem-Lettuce-Salad_7.jpg', 15, 10, 25, 4, '[{"id": "ing_lettuce", "quantity": {"value": 3.0, "unit": "head"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 0.6, "unit": "punnet of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.5, "unit": "bunch"}}, {"id": "ing_chives", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_bread", "quantity": {"value": 0.188, "unit": "loaf"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["3 baby gem lettuce (aka little gem lettuce), leaves separated, washed and dried (Note 1)","1 cup cherry tomatoes (, cut in half (or grape tomatoes, or 2 regular tomatoes cut into bite size pieces))","1/2 eschalot (US: shallot), finely diced (Note 2)","1 1/2 tbsp chives (, finely chopped)","1 quantity Creamy French Dressing"]},{"ingredients":["1 cup white bread like baguette (, ciabatta, sourdough, cut into 1cm / 0.4\" cubes - preferably stale (Note 3))","1 tbsp extra virgin olive oil","Pinch of cooking salt / kosher salt"],"purpose":"Croutons:"}]', '[{"description":"Preheat the oven to 200°C / 390°F (180°C fan-forced).","images":[],"step":1},{"description":"Toss the bread with the oil and salt. Spread on a tray and bake for 10 minutes, tossing once halfway.","duration":10,"images":[],"step":2},{"description":"Cool on the tray before using. (These will keep for weeks in an airtight container in the pantry).","images":[],"step":3},{"description":"Place all the lettuce leaves in a large bowl.","images":[],"step":4},{"description":"Add half of each the tomatoes, croutons, chives and eschalots. Drizzle with half the dressing then gently toss with your hands.","images":[],"step":5},{"description":"Pour into a serving bowl or pile on a platter. Scatter the remaining tomatoes, croutons, chives and eschalots across the top, then drizzle with the remaining dressing. Serve!","images":[],"step":6}]', '["gluten"]', '["vegan","vegetarian"]', '{"mealType":["lunch"],"cuisine":["French"],"categories":["all-vegetable-sides","jbs-recipes","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8dbd67893b5b', 'en', 'US', 'Broccoli Pearl Crunch Salad', 'Recipe video above. This is a meal-worthy salad designed to be eaten with a spoon: finely chopped broccoli tossed with slippery pearl couscous, plumped dried cranberries and a nutty salami fry up with red onion and garlic. The red wine vinaigrette is zesty but not too sour thanks to a smidge of honey, and finishing with parmesan is optional, but not really. :)It''s a riot of textures, flavours and colours, and just a great way to use broccoli in a different way. Serve this for lunch with friends, dinner on balmy evenings, or a lazy Sunday lunch with a glass of your favourite white.', 'https://www.recipetineats.com/tachyon/2025/08/Broccoli-pearl-crunch-salad_4.jpg', 25, 15, 70, 4, '[{"id": "ing_broccoli", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_vinegar", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_pears", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_cranberries", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_bacon", "quantity": {"value": 0.5, "unit": "pack of 200g"}}, {"id": "ing_almonds", "quantity": {"value": 0.2, "unit": "pack of 250g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_honey", "quantity": {"value": 0.03, "unit": "jar of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_lemon", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}]', '[{"ingredients":["1 1/2 medium heads broccoli (4 cups chopped small, spoon-eating size)(Note 1)","1 tbsp red wine vinegar (Note 2)","1/4 tsp cooking salt / kosher salt"],"purpose":"Marinated broccoli:"},{"ingredients":["1 cup pearl couscous (Note 3)","1/2 cup dried cranberries"],"purpose":"Couscous and plumped cranberries:"},{"ingredients":["1 tsp olive oil","100g/ 3 oz salami (, chopped into 1x1.25cm pieces (0.2 x 1/2\"), or bacon (Note 4))","1/3 cup almonds (, unsalted, natural (or roasted), chopped into big pieces (Note 5))","1 red onion (, halved, finely sliced)","2 garlic cloves (, finely minced)"],"purpose":"Nutty salami fry up:"},{"ingredients":["2 tbsp red wine vinegar (Note 2)","1 tbsp honey (sub maple, or 2 tsp sugar)","3 tbsp extra virgin olive oil","1 tsp dijon mustard","1 garlic clove (, finely minced)","1 tsp lemon zest (, optional)","1/4 tsp cooking salt / kosher salt","1/8 tsp black pepper"],"purpose":"Red Wine Vinegar Honey Dressing:"},{"ingredients":["1/4 cup+ parmesan (, finely grated (crumbled feta also lovely))"],"purpose":"Serving:"}]', '[{"title":"Dressing","description":"Shake ingredients in a jar.","images":[],"step":1},{"title":"Chop broccoli into small pieces","description":"think, spoon scoop-able size. I slice wads of florets into ~1/2cm / 0.2\" thick slices, spread out on the board then run the knife through, chopping like you would herbs until you have small pieces no bigger than 1.5cm / 0.6\" long, suitable for scooping. Try to make the floret stem parts a bit smaller. (Note 1)","images":[],"step":2},{"title":"Marinated tender-crisp broccoli","description":"Measure out 4 cups of broccoli and put in a bowl. Scrape in all the scattered little floret \"confetti\"! Toss with the vinegar, 1/4 tsp salt and 2 tablespoons of the Dressing. Leave for 30 minutes - softens slightly and takes the raw edge off.","duration":30,"images":[],"step":3},{"title":"Couscous and cranberries","description":"Bring a large saucepan of water to the boil. Cook the couscous for 5 minutes, adding cranberries for last 30 seconds (they plump!). Drain well, then return to saucepan. Toss with 2 tablespoons of Dressing (while hot), then set aside for 10 minutes to cool and absorb flavour.","duration":5,"images":[],"step":4},{"title":"Nutty Salami Fry up","description":"Heat the olive oil over medium high in a large non-stick pan. Add the salami and cook for about 1 1/2 minutes to give them a head start. Then add the almonds and onion, cook for 2 minutes, then add garlic and cook for another 1 minute until the salami is golden (it won''t crisp though - Note 7) and the onion is softened. Tip it on top of the broccoli, let cool for 10 minutes.","duration":2,"images":[],"step":5},{"title":"Toss","description":"Add couscous, all the remaining Dressing and toss well. Tumble into a serving bowl, sprinkle with parmesan then serve!","images":[],"step":6}]', '["gluten","milk","mustard"]', '[]', '{"mealType":["lunch"],"cuisine":["Western"],"categories":["all-vegetable-sides","broccoli","broccoli-recipes","salad-recipes-main-course","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ac448cf78003', 'en', 'US', 'Maple sweet potato salad - with whipped tahini and crispy chickpeas', 'Recipe video above. Channelling my inner Yotam Ottolenghi – maple-roasted sweet potato on a fluffy cloud of whipped tahini, topped with crispy spiced chickpeas and a shower of chopped pistachios. Fabulous statement side or substantial meat-free main - try stuffing into flatbreads. Ridiculously good!', 'https://www.recipetineats.com/tachyon/2025/06/Maple-sweet-potato-salad-with-whipped-tahini_4.jpg', 15, 40, 55, 5, '[{"id": "ing_sweet_potato", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_maple_syrup", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_sriracha", "quantity": {"value": 0.037, "unit": "bottle of 400ml"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.375, "unit": "tub of 500g"}}, {"id": "ing_tahini", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.417, "unit": "pack of 3 heads"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_pistachios", "quantity": {"value": 4.0, "unit": "unit"}}]', '[{"ingredients":["1.5kg / 3 lb sweet potatoes","1 tbsp maple syrup (or 2 1/2 tbsp honey)","1 1/2 tbsp olive oil","1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper"],"purpose":"Maple roasted sweet potato wedges:"},{"ingredients":["400g/ 14 oz can chickpeas (, drained but not dried)","1 tbsp olive oil","1/2 tsp smoked paprika","1/4 tsp garlic powder","1/4 tsp onion powder","1/4 tsp cooking salt / kosher salt","1/4 tsp black pepper"],"purpose":"Crispy seasoned chickpeas:"},{"ingredients":["3 tbsp maple syrup (sub 2 tbsp honey)","1 tbsp sriracha (Note 2)","1 tbsp extra virgin olive oil","1/4 tsp cooking salt / kosher salt (halve for table salt)","Pinch Black pepper"],"purpose":"Spicy maple sauce"},{"ingredients":["1 1/4 cups plain yogurt (, full fat, unsweetened)","3 tbsp tahini (mix well if oil is separated)","2 tbsp lemon juice","1 large garlic clove (, finely grated)","1 tbsp extra virgin olive oil","1/2 tsp cooking salt / kosher salt"],"purpose":"Whipped tahini yogurt sauce:"},{"ingredients":["2 tbsp finely chopped coriander/cilantro leaves (sub parsley)","4 tbsp toasted pistachios (, finely chopped (Note 3))"],"purpose":"Garnishes:"}]', '[{"description":"Preheat the oven to 220°C/450°F (200°C fan). Arrange the oven racks so they are 20 cm/8\" apart (for air circulation).","images":[],"step":1},{"title":"Spicy maple sauce","description":"Mix until combined. Set aside.","images":[],"step":2},{"title":"Sweet potato","description":"Cut each sweet potato lengthways into 6 wedges (or 8, if they are thicker potatoes). Put on a paper lined tray, then toss with the maple syrup, olive oil, salt and pepper. Lay sweet potato wedges on their side.","images":[],"step":3},{"title":"Chickpeas","description":"Drain the chickpeas then spread on a tray (still wet).","images":[],"step":4},{"title":"Baking","description":"Put both trays in the oven (sweet potato on the top shelf). Roast the potatoes for 30 minutes, turning them at the halfway mark. Take the chickpeas out after 10 minutes to flavour them.","duration":30,"images":[],"step":5},{"title":"Crispy seasoned chickpeas","description":"Remove the oven dried chickpeas from the oven after 10 minutes (Note 4). Push them to one side of the tray, drizzle/sprinkle and toss with the oil, spices, salt and pepper. Toss well using a rubber spatula, then return to the oven for a further 15 - 20 minutes until they''re crispy (they will clatter! Note 4).","images":[],"step":6},{"title":"Sweet potato charring (optional)","description":"After 30 minutes (or when the potatoes are soft), switch the oven grill/broiler to high. Tuck in or fold down excess paper around the tray edges (so it doesn''t touch heat element and catch fire). Stand the wedges sharp edge facing up, then pop it under the broiler for 3 to 5 minutes until a bit charred on the edges. ⚠️ SAFETY NOTE: Do not walk away, make sure the paper does not catch fire.","duration":4,"images":[],"step":7},{"title":"Whipped tahini yogurt sauce","description":"While the potatoes are roasting whisk ingredients in a heat-proof bowl just to combine. When ready to use, microwave for just 30 seconds on high, then whisk again for 10 seconds – it will resemble softly whipped cream. (Note 5)","duration":0.16666666666666666,"images":[],"step":8},{"title":"Optional tahini drizzle","description":"Remove 1/4 cup of the tahini sauce and loosen with a little water to a drizzle-able consistency.","images":[],"step":9},{"title":"Assemble","description":"Spread the whipped tahini on a large plate. Pile the sweet potato on, mostly in a single layer. Drizzle with the tahini drizzle (if using), the spicy maple sauce, sprinkle with most of the pistachio and coriander. Sprinkle over chickpeas, then sprinkle with the remaining coriander and pistachios. EAT! (PS Great served warm or at room temperature)","images":[],"step":10}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["MIddle eastern vibes","Western"],"categories":["all-vegetable-sides","dietary","gluten-free-recipes","sweet-potato","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_33d5fbd91088', 'en', 'US', 'The most amazing Chicken Kale Salad', 'Recipe video above. WORTH MAKING - don''t let the length of the ingredients deter you!! This is a big, hearty salad that may well be the best kale salad you''ve ever had. Big call I stand by! :)Filled with good-for-you nutrition yet anything but bland, that creamy tahini sauce totally makes it, thanks to the parmesan. Crunchy seasoned chickpeas add starchy bulk, flavour pops and texture, the cherry tomatoes add juicy bursts and the chicken provides protein. Oh yeah, and there''s kale in it too! :) Powerhouse greens!', 'https://www.recipetineats.com/tachyon/2024/04/Kale-salad-with-creamy-tahini-dressing_9.jpg', 20, 30, 50, 3, '[{"id": "ing_very_tightly_packed_cups_tuscan_kale", "quantity": {"value": 5.0, "unit": "unit"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 0.25, "unit": "pack of 1kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_tomato", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_tahini", "quantity": {"value": 60.0, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 0.075, "unit": "net of 500g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.417, "unit": "pack of 3 heads"}}, {"id": "ing_water", "quantity": {"value": 0.06, "unit": "L"}}]', '[{"ingredients":["5 very tightly packed cups Tuscan kale (cavolo nero) (, leafy part stripped off stem, sliced into 1 cm / 1/2\" ribbons (Note 1))","1 tsp extra virgin olive oil","1/4 tsp salt and pepper"],"purpose":"SOFTENED KALE:"},{"ingredients":["1/4 red onion (, very finely sliced)","1 1/2 cups shredded cooked chicken","2 soft boiled eggs (, halved (optional))"],"purpose":"SALAD:"},{"ingredients":["1 1/2 cups cherry or grape tomatoes","2 tsp extra virgin olive oil","1/4 tsp cooking salt/kosher salt","1/8 tsp black pepper"],"purpose":"BURST TOMATOES"},{"ingredients":["400 g/ 14 oz can chickpeas (, drained but not dried)","1 tbsp olive oil","1/2 tsp smoked paprika","1/4 tsp EACH garlic powder , onion powder","1/4 tsp EACH cooking salt / kosher salt & black pepper"],"purpose":"CRISPY SEASONED CHICKPEAS"},{"ingredients":["4 tbsp (60 g) tahini (, hulled (Note 3))","2 1/2 tbsp lemon juice","3 tbsp extra virgin olive oil","1/3 cup parmesan (finely grated (pack the cup tight), plus extra for serving)","1/2 tsp cooking salt/kosher salt","1/8 tsp black pepper","1 large garlic clove (, peeled)","4 tbsp water (plus more, if needed)"],"purpose":"CREAMY PARMESAN TAHINI DRESSING"}]', '[{"title":"Oven","description":"Roast tomatoes 12 min at 200°C/425°F (180°C fan). Roast plain chickpeas 10 min, toss with oil & seasonings, roast 20 min until crispy (same temp).","images":[],"step":1},{"title":"Salad","description":"Massage kale, leave 20 min. Blitz dressing. Toss kale, chicken, tomatoes, onion with half. Pile on chickpeas, drizzle with remaining dressing, shower with parmesan. EAT!","images":[],"step":2},{"description":"Preheat the oven to 200°C/425°F (180°C fan).","images":[],"step":3},{"title":"Roast tomatoes","description":"Toss the tomatoes with the oil, salt and pepper on a small tray. Roast 12 minutes, then cool on the tray.","images":[],"step":4},{"title":"Crispy chickpeas","description":"Drain the chickpeas then spread on a tray (still wet). Bake 10 minutes (same time as tomatoes). Push the oven dried chickpeas to one side of the tray. Drizzle with the oil and sprinkle with the chickpea spices, salt and pepper. Toss well using a rubber spatula, then return to the oven for a further 20 – 25 minutes until they''re crispy (They should clatter! Note 4).","images":[],"step":5},{"title":"Soften kale","description":"Rub/scrunch the kale with the oil, salt and pepper in a large bowl. Put the kale in a large bowl then drizzle with the oil and add the salt and pepper. Set aside for 20 minutes (softens leaves).","duration":20,"images":[],"step":6},{"title":"Tahini dressing","description":"Put the ingredients in a jug just large enough to fit the head of a stick blender. Blitz until smooth, using extra water if needed to loosen into a thick but pourable consistency (see video).","images":[],"step":7},{"title":"Toss","description":"Pour half the dressing over the kale and toss. Add onion, chicken and most of the tomatoes (save a few for decoration). Toss again.","images":[],"step":8},{"title":"Serve","description":"Transfer into a serving bowl or individual bowls. Top with remaining tomatoes, all the chickpeas and eggs if using. Drizzle with remaining sauce then sprinkle with extra parmesan. DIG IN. SWOON!","images":[],"step":9}]', '["egg","milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["all-vegetable-sides","beans-lentils","leafy-greens","salad-recipes-main-course"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e8fdbc3d0e04', 'en', 'US', 'Spicy maple roast carrots with crispy chickpeas and yogurt sauce', 'Recipe video above. This is a combination of 3 simple things that are devilishly good together: slightly spicy caramelised maple roasted carrots, crispy seasoned chickpeas and a cooling, creamy yogurt sauce with a subtle hint of garlic. The chickpeas add terrific crunch and because they''re a starch, you can easily serve this substantial side dish as a meal. Both the carrots and chickpeas take around 30 minutes in the oven but you might need to add an extra 5 minutes or so depending on how long you take when you take the trays out to toss/season etc .', 'https://www.recipetineats.com/tachyon/2024/02/Spicy-maple-roasted-carrots-with-crispy-chickpeas-and-yogurt-sauce-1.jpg', 15, 40, 55, 5, '[{"id": "ing_carrot", "quantity": {"value": 16.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 16.0, "unit": "pack of 1kg"}}, {"id": "ing_maple_syrup", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_sriracha", "quantity": {"value": 0.075, "unit": "bottle of 400ml"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.3, "unit": "tub of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.417, "unit": "pack of 3 heads"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_pistachios", "quantity": {"value": 3.0, "unit": "unit"}}]', '[{"ingredients":["16 Dutch carrots (, scrubbed clean and tops trimmed (keep 2cm/1\" of tops for looks))","600 g/ 1.2 lb regular carrots (5 medium), peeled, cut into quarters (Note 1)"],"purpose":"Carrots (choose one):"},{"ingredients":["3 tbsp maple syrup (or 2 1/2 tbsp honey)","2 tbsp sriracha","1 1/2 tbsp olive oil","1/4 tsp cooking salt / kosher salt","1/4 tsp black pepper"],"purpose":"Spicy maple sauce (for carrots):"},{"ingredients":["400g/ 14 oz can chickpeas (, drained but not dried)","1 tbsp olive oil","1/2 tsp smoked paprika","1/4 tsp garlic powder","1/4 tsp onion powder","1/4 tsp cooking salt / kosher salt","1/4 tsp black pepper"],"purpose":"Crispy seasoned chickpeas:"},{"ingredients":["1 tbsp maple syrup","1/2 tbsp sriracha"],"purpose":"Extra sauce (optional) – Note 2"},{"ingredients":["1 cup plain yogurt","1/2 tsp garlic (, finely grated)","1 tbsp lemon juice","1 tbsp extra virgin olive oil","1/4 tsp cooking salt / kosher salt"],"purpose":"Lemon garlic yogurt sauce:"},{"ingredients":["2 tbsp finely chopped coriander/cilantro leaves (sub parsley)","3 tbsp toasted pistachios (, finely chopped (Note 3))"],"purpose":"Garnishes:"}]', '[{"description":"Preheat the oven to 200°C/425°F (180°C fan). Arrange the oven racks so they are 20 cm/8\" apart (for air circulation).","images":[],"step":1},{"title":"Chickpeas & carrots","description":"Drain the chickpeas then spread on a tray (still wet). Toss the carrots with the Spicy Maple Sauce ingredients. Put both trays in the oven (carrots on the top shelf).","images":[],"step":2},{"title":"Crispy chickpeas","description":"Remove the oven dried chickpeas from the oven after 10 minutes (Note 4). Push them to one side of the tray, drizzle with the oil and sprinkle with the chickpea spices, salt and pepper. Toss well using a rubber spatula, then return to the oven for a further 20 - 25 minutes until they''re crispy (listen for the clatter when you shake the tray - or eat one! Note 4).","images":[],"step":3},{"title":"Carrots 30 min","description":"Roast the carrots for 30 minutes, tossing halfway, until they are tender and caramelised on the edges.","duration":30,"images":[],"step":4},{"title":"Yogurt Sauce","description":"Mix the ingredients in a bowl and set aside for at least 20 minutes to allow the flavours to develop.","images":[],"step":5},{"title":"Extra sauce","description":"Mix until combined.","images":[],"step":6},{"title":"Assemble","description":"Spread the yogurt sauce on a plate. Pile on the carrots, scraping out every drop of juices on the tray. Drizzle with extra sauce, if using. Sprinkle over chickpeas, then coriander and pistachios. EAT!","images":[],"step":7}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["MIddle eastern vibes","Western"],"categories":["all-vegetable-sides","beans-lentils","carrots","easter-sides-warm-hearty","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_570f4928d5ca', 'en', 'US', 'Holiday Stuffed Sweet Potato', 'Recipe video above. Stuffed sweet potato made for holiday feasting! Twice baked sweet potatoes stuffed with crispy bacon, toasty pecans and swirls of browned butter with melty cheese, and a crunchy sage-panko topping. A swoon-worthy combination of flavours and texture, this is the individual servings version of my sweet potato casserole.Excellent special occasion starchy-side dish with holiday flavour vibes. Get ahead by assembling then baking on the day!', 'https://www.recipetineats.com/tachyon/2023/11/Stuffed-sweet-potato-casserole_5.jpg', 30, 105, 135, 8, '[{"id": "ing_sweet_potato", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_pecan_nuts", "quantity": {"value": 75.0, "unit": "jar"}}, {"id": "ing_bacon", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_bread", "quantity": {"value": 0.094, "unit": "loaf"}}, {"id": "ing_sage", "quantity": {"value": 0.03, "unit": "kg"}}]', '[{"ingredients":["4 x 300g / 10oz sweet potatoes (, skin on, washed and dried)","1/2 tsp cooking / kosher salt","4 tbsp unsalted butter","5 tbsp pecan nuts (Note 2)","200g / 7 oz streaky bacon (, chopped (Note 5 to omit))","1 1/2 cups colby cheese (, shredded (Note 3))","1/4 tsp black pepper","1/4 tsp garlic powder","1/4 tsp onion powder","1/4 tsp paprika"]},{"ingredients":["1/4 tsp cooking / kosher salt","1/2 cup panko breadcrumbs","2 tbsp sage leaves (, finely chopped (Note 4))"],"purpose":"Panko topping:"}]', '[{"description":"Preheat oven to 200°C / 400°F (180°C fan forced).","images":[],"step":1},{"title":"Bake","description":"Prick the skin of the potatoes 15 times with a fork. Place on a foil lined baking tray and bake for 75 minutes or until soft all the way through (check with a butter knife).","duration":75,"images":[],"step":2},{"title":"Scoop","description":"Once potatoes cooked, allow to cool for 10 minutes just to handle. Cut in half lengthwise then scoop out the flesh, leaving a 0.5cm (0.2\") wall (use a tea towel if hot). Place flesh in a bowl.","duration":10,"images":[],"step":3},{"description":"Stuffing (*see below for prepping components*)- Mash the potatoes with a fork. Then add the browned butter, 1/2 tsp salt, pepper, garlic, onion powder and paprika. The add half of each the pecans, bacon and cheese (rest reserved for toppings). Stir until combined.","images":[],"step":4},{"title":"Stuff","description":"Place halved sweet potato back on a paper lined baking tray and stuff them equally with filling. Sprinkle with leftover cheese and bake for 25 minutes until cheese is melted.","duration":25,"images":[],"step":5},{"title":"Crunchy topping","description":"Top with reserved pecans, bacon and panko mixture. Bake for another 3 to 4 minutes","images":[],"step":6},{"description":"Rest for 5 minutes then serve!","duration":5,"images":[],"step":7},{"description":"Stuffing & topping components","images":[],"step":8},{"description":"Prepare these while the potatoes are baking.","images":[],"step":9},{"title":"Browned butter","description":"Melt the butter in a small silver pan or saucepan over medium heat. Leave to simmer on medium heat for 3 to 5 minutes, stirring every now and then, until (when you push foam aside) you see little golden-brown bits and it smells nutty. Immediately pour into a small bowl (including the golden bits) and set aside.","duration":4,"images":[],"step":10},{"title":"Toast pecans","description":"Heat a non-stick pan over medium high heat. Add pecans and toast for 2 to 3 minutes until they have golden spots. Transfer to cutting board, cool then finely chop.","duration":2.5,"images":[],"step":11},{"title":"Crispy bacon","description":"Add bacon into the same pan over medium heat. When the fat starts to melt, turn the heat up to medium high and cook until golden (4 to 5 minutes). Scoop out bacon with a slotted spoon and place into a small bowl. Leave leftover fat in the pan.","images":[],"step":12},{"title":"Golden panko","description":"Still on medium high, add the Panko topping ingredients. Stir until golden, around 2 minutes, then scrape into a bowl.","images":[],"step":13}]', '["milk","nuts"]', '["gluten_free"]', '{"mealType":["main_course"],"cuisine":["Western","Western - Holiday Sides"],"categories":["all-vegetable-sides","easter-sides-warm-hearty","potato-recipes","side-dishes","sweet-potato"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0b8b1254909f', 'en', 'US', 'Green Beans with a Mountain of Panko', 'Recipe video above. My latest "wow-factor" green bean side dish invention which is quick, easy and a make-ahead dream. Blanched beans smothered in a pillowy tahini yogurt sauce piled high with a mountain of parmesan panko breadcrumbs - hence the name!The sauce acts like a glue so you get a stack of crunchy parmesan panko in every-single-bite. Supposed to be a vegetable side dish but I snack on these like fries!!', 'https://www.recipetineats.com/tachyon/2023/11/Green-beans-with-a-mountain-of-panko-overhead.jpg', 10, 5, 15, 6, '[{"id": "ing_green_beans", "quantity": {"value": 700.0, "unit": "pack"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.3, "unit": "tub of 500g"}}, {"id": "ing_tahini", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 0.045, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_bread", "quantity": {"value": 0.141, "unit": "loaf"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}]', '[{"ingredients":["700 g/1.4lb green beans (, ends trimmed (Note 1))","1 tbsp extra virgin olive oil","1/2 tsp cooking/kosher salt","1/4 tsp black pepper"],"purpose":"Beans:"},{"ingredients":["1 cup plain yogurt","2 1/2 tbsp tahini (Note 2)","1 1/2 tbsp lemon juice (sub 1 tbsp clear vinegar)","1 garlic clove (, finely grated)","1/2 tsp cooking/kosher salt"],"purpose":"Whipped Tahini Yogurt:"},{"ingredients":["3/4 cup panko breadcrumbs (Note 3)","3 tbsp extra virgin olive oil","1/8 tsp cooking/kosher salt","1/4 cup parmesan (, finely grated (tightly packed cup))"],"purpose":"Parmesan Panko Mountain:"}]', '[{"description":"Shortform recipe:","images":[],"step":1},{"description":"Toss blanched beans with oil, salt and pepper. Whisk Tahini ingredients, microwave 20 seconds, whisk again. Toast Panko mix on stove. Assemble - beans, sauce then panko. Attack!","images":[],"step":2},{"description":"Full directions:","images":[],"step":3},{"title":"Cook beans","description":"Bring a large pot of water to the boil. Add beans, let it come back to the boil, cook for 2 minutes, then drain in a colander. Rinse under cold running water for 10 seconds to stop cooking (there is NO NEED to use ice!).","duration":2,"images":[],"step":4},{"title":"Season","description":"Spread beans on a tea towel then dry with a 2nd tea towel. Transfer into bowl, toss with the oil, salt and pepper.","images":[],"step":5},{"title":"Panko Mountain","description":"Mix the ingredients in a bowl. Preheat a large non-stick pan on medium high. Add the panko mixture and stir for 4 - 5 minutes until golden brown. Transfer back into the bowl then let it cool.","duration":4.5,"images":[],"step":6},{"title":"Whipped Tahini Yogurt","description":"Whisk ingredients in a heat-proof bowl just to combine. Microwave for just 20 seconds on high, then whisk again for 10 seconds - it will resemble softly whipped cream. (Note 4) Use immediately or at room temperature.","duration":0.16666666666666666,"images":[],"step":7},{"title":"Assemble","description":"Spread green beans on plate. Pour over sauce, pile on panko. Attack!","images":[],"step":8}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["all-vegetable-sides","easter-sides-fresh-light","green-beans","quick-and-easy","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_57c5ad7bfa48', 'en', 'US', 'How I cook frozen peas - Garlic Buttered Peas', 'Recipe video above. Make frozen peas fabulous with my recipe for buttered peas! A quick side that goes with everything. Don''t boil the peas - cook from frozen in garlic butter. Easier, tastier, bright green, never mushy and never watery!', 'https://www.recipetineats.com/tachyon/2023/10/Buttered-peas_2a.jpg', 5, 5, 10, 6, '[{"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_frozen_peas", "quantity": {"value": 500.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 0.015, "unit": "L"}}]', '[{"ingredients":["50g / 3 tbsp unsalted butter (or other oil/fat)","2 garlic cloves (, finely minced)","500g / 1 lb frozen peas (Note 1)","1/2 tsp cooking / kosher salt","1/2 tsp black pepper","1 tbsp water"]}]', '[{"title":"Sauté garlic","description":"Melt butter in a large saucepan over medium heat. Add garlic and cook for 30 seconds until light golden.","duration":0.5,"images":[],"step":1},{"title":"Cook","description":"Add frozen peas, salt, pepper and water. Turn heat up to medium high and cook for 5 minutes, stirring every now and then, until the water is evaporated, the peas are hot and coated in the tasty garlic butter.","duration":5,"images":[],"step":2},{"title":"Serve","description":"Tumble into a bowl and serve!","images":[],"step":3}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["all-vegetable-sides","peas","quick-and-easy","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5cf21e1b7774', 'en', 'US', 'Maple Roasted Pumpkin with Chili and Feta', 'Recipe video above. A seriously delicious, low-effort way to serve roast pumpkin: with a dash of maple syrup for extra caramelisation, a kick of chilli, warm crunch of walnuts and salty pops of creamy feta.Serves 3 as a main or 6 as a side. I made this with pumpkin but it is just as delicious made with squash or sweet potato!', 'https://www.recipetineats.com/tachyon/2015/04/Roast-pumpkin-maple-feta-chilli_9.jpg', 10, 30, 35, 3, '[{"id": "ing_pumpkin", "quantity": {"value": 0.907, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_walnuts", "quantity": {"value": 75.0, "unit": "jar"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_maple_syrup", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 10.0, "unit": "pack of 100g"}}, {"id": "ing_feta_cheese", "quantity": {"value": 0.75, "unit": "block of 200g"}}, {"id": "ing_chilli", "quantity": {"value": 10.0, "unit": "pack of 100g"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["2 lb / 1 kg pumpkin (, peeled, cut into 2.5cm / 1\" cubes (whole, unpeeled weight - Note 1))","1 red onion (, peeled, halved, then cut into 1cm / 0.4\" wedges)","1/2 cup walnuts (, roughly chopped (Note 2))","3 tbsp olive oil","3 tbsp maple syrup (or honey (sub brown sugar Note 3),)","3/4 tsp cooking salt / kosher salt","1 - 1 1/2 tsp dried chili flakes (, adjust to taste (Note 4))"]},{"ingredients":["3/4 cup Danish feta (or Greek feta, or upgrade to goats cheese)","1 large red chilli ((cayenne pepper), deseeded, finely minced)","1 tbsp parsley (finely chopped)"],"purpose":"Garnishes (Optional)"}]', '[{"description":"Preheat oven to 200°C/400°F (180°C fan-forced).","images":[],"step":1},{"title":"Toss","description":"Place the pumpkin, onion and walnuts on a large, paper lined tray. Drizzle with olive oil and maple syrup, then toss to coat (hands really is best). Sprinkle with chilli and salt, toss again, then spread out on a tray. Don''t crowd them else they will stew instead of roast!","images":[],"step":2},{"description":"Roast for 30 minutes, or until the pumpkin is lightly browned and cooked through, tossing once at the 20 minute mark.","duration":30,"images":[],"step":3},{"title":"Finishes","description":"Remove from the oven. Gently toss again, then transfer to a serving platter in a single layer. Crumble over feta, sprinkle with parsley and chilli. Or do the sprinkling on the tray then pile into a bowl. Serve immediately!","images":[],"step":4}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["all-vegetable-sides","dietary","easter-sides-warm-hearty","gluten-free-recipes","pumpkin","pumpkin-squash","quick-and-easy","side-dishes","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_116cdc57caee', 'en', 'US', 'Easy roast potatoes', 'Recipe video above. This is my everyday roast potatoes recipe. No-nonsense, quick to prep, with great garlic-thyme flavour. Fresh herbs are lovely, though dried can be used in a pinch. Don''t make the mistake of using minced garlic. It burns!Serve with everything.', 'https://www.recipetineats.com/tachyon/2023/09/Easy-roast-potatoes_4a.jpg', 5, 60, 65, 5, '[{"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_thyme", "quantity": {"value": 5.0, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 kg/ 2 lb baby potatoes (or other small potatoes, halved (Note 1))","4 tbsp extra virgin olive oil","1 tsp cooking/kosher salt","1/4 tsp black pepper","5 garlic cloves with skin on (, smashed (Note 2))","5 thyme sprigs (or 3 rosemary sprigs (Note 3 for dried herbs))"]},{"ingredients":["Finely chopped parsley or fresh thyme (optional)"],"purpose":"Optional garnish"}]', '[{"description":"Preheat oven to 200°C / 400°F (180°C fan).","images":[],"step":1},{"title":"Smashed garlic","description":"Place side of knife on unpeeled garlic clove. Hit firmly with palm of hand so the garlic bursts open a bit but mostly stays in tact.","images":[],"step":2},{"title":"Toss","description":"Put potatoes on a tray and push together. Drizzle with oil, sprinkle with salt and pepper. Toss to coat. Toss through thyme and garlic. Spread out on tray.","images":[],"step":3},{"title":"Roast 1 hour","description":"Roast for 30 minutes. Toss. Roast for a further 25 to 35 minutes, or until the potatoes are golden. (Note 4 for stuck potatoes & golden TIPS!)","duration":30,"images":[],"step":4},{"title":"Serve","description":"Sprinkle with parsley, if using, and serve immediately!","images":[],"step":5}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["all-vegetable-sides","easter-sides-warm-hearty","potato-recipes","potatoes","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0a4df0854235', 'en', 'US', 'Farro Salad with Sizzled Garlic Dressing', 'Recipe video above. Farro is so much more interesting than pasta or rice! This salad has stellar flavour and texture: nutty farro, juicy burst cherry tomatoes, spinach bits and smeary goats cheese or feta, doused in an addictive hot garlic olive oil dressing with pops of coriander and cumin. You''ll love how we cook the farro - it''s delicious even more you add everything else. Serves 4 as a meal, 8 as a side. Excellent shelf life and brilliant for taking to gatherings - see notes.', 'https://www.recipetineats.com/tachyon/2023/09/Farro-salad_5.jpg', 10, 45, 55, 4, '[{"id": "ing_farro", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.5, "unit": "bottle of 500ml"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_baby_spinach", "quantity": {"value": 2.0, "unit": "bag of 250g"}}, {"id": "ing_cheese", "quantity": {"value": 80.0, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 7.5, "unit": "pack of 3 heads"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.188, "unit": "jar of 40g"}}]', '[{"ingredients":["1 cup farro (, dried, whole (Note 1))","1 cup apple cider vinegar (Note 2)","2 cups water","1 tsp cooking/kosher salt"],"purpose":"Farro:"},{"ingredients":["400g/ 14oz (4 cups) grape tomatoes (or cherry tomatoes)","1 tbsp olive oil","1/4 tsp each salt and pepper"],"purpose":"Burst tomatoes:"},{"ingredients":["1 eschallot (, halved then finely sliced (sub 1/4 red onion) (Note 3))","2 tightly packed cups baby spinach (, roughly chopped (sub arugula/baby rocket))","80g/ 3oz goats cheese (or 120g/4 oz Danish feta (Note 4))"],"purpose":"Add-ins:"},{"ingredients":["2 tbsp extra virgin olive oil","1 1/2 tbsp garlic (, finely minced (~4 cloves))","2 tsp coriander seeds","1 1/2 tsp cumin seeds"],"purpose":"Sizzling garlic cumin dressing:"}]', '[{"description":"Preheat oven to 200°C/400°F (180°C fan).","images":[],"step":1},{"title":"Roast tomatoes and toast farro","description":"Toss tomatoes on a tray with the olive oil, salt and pepper. Spread farro on a separate tray. Put both in the oven, farro on the top shelf, tomatoes underneath. Bake for 8 minutes, shaking the trays halfway. The farro should be browned with a nutty flavour, the tomatoes should be a bit wrinkly but still holding their shape.","duration":8,"images":[],"step":2},{"description":"Cool tomatoes on the tray while you prep everything else.","images":[],"step":3},{"title":"Cook farro (Note 1)","description":"Put the toasted farro in a saucepan with the vinegar, water and salt. Bring to a boil over high heat then reduce to medium so it is simmering. Cover with lid then simmer for 40 - 45 minutes or until all/most of the liquid is absorbed and the farro is ready. It should still have a bite to it (not soft like pasta) but not a hard centre. Add more water if needed, and keep cooking - don''t be afraid to cook it softer if you want. Drain off excess liquid, if there is any, then transfer to a large bowl. (Taste: a bit tangy, the \"vinegar\" component used in salad dressings!)","duration":42.5,"images":[],"step":4},{"description":"Pile eschallots on top. Let farro cool to room temp.","images":[],"step":5},{"title":"Sizzling garlic cumin dressing","description":"Heat oil in a small pan over medium low heat. Add coriander and cumin, cook for 30 seconds until light golden and you can smell it. Add garlic and cook for 30 seconds until light golden.","duration":0.5,"images":[],"step":6},{"title":"Assembling","description":"Immediately pour hot oil over eschallots so it semi-cooks it. Toss. Add spinach, toss. Add tomatoes, gently stir through (some tomato collapsing is encouraged). Pour 1/3 into a serving bowl, crumble over 1/3 goats cheese. Repeat twice more, finishing with goats cheese. Eat!","images":[],"step":7}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Western"],"categories":["all-vegetable-sides","salad-recipes-main-course","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_57f5a30d9edb', 'en', 'US', 'Spicy Asian Zucchini', 'Recipe video above. Here''s a great new quick and easy way to use zucchinis! Meaty zucchini halves stove seared then doused in a mild spicy Asian chilli garlic sauce.The stove works so well here - great colour, and cooks them through just enough so they''re tender-crisp rather than watery-mushy. Though, if you want soft all the way through, it''ll be easier to do them in the oven - see notes.Serve as a substantial side or a hearty healthy lunch!', 'https://www.recipetineats.com/tachyon/2023/08/Spicy-Asian-Zucchini_0.jpg', 5, 10, 15, 5, '[{"id": "ing_zucchini", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_sambal_oelak", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_mirin", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}]', '[{"ingredients":["5 zucchini, small / medium (, cut in half lengthways (Note 1))","1 tbsp canola oil (or other plain oil)","3/4 tsp cooking/kosher salt","1/4 cup crispy fried shallots","1 green onion stem (, finely sliced)"]},{"ingredients":["1 tbsp canola oil (or other plain oil)","3 garlic cloves (, finely minced)","1 tbsp sambal oelak (sub sriracha or chilli crisp) (Note 3)","1 tbsp sesame oil (, toasted)","1 tbsp soy sauce (, light or all-purpose NOT dark soy (Note 4))","2 tbsp mirin ( - sub honey (Note 5))"],"purpose":"Spicy sauce:"}]', '[{"description":"Toss the zucchini in oil then sprinkle with salt and toss to (roughly) coat all over.","images":[],"step":1},{"title":"Cook","description":"Heat a large non-stick pan over medium-high heat. Place half the zucchini cut side down and cook for 3 to 4 minutes until the surface is golden. Turn and cook the skin side for 3 minutes. Pile onto a serving plate and repeat with remaining zucchini.","duration":3.5,"images":[],"step":2},{"title":"Sauce","description":"cool the pan slightly then return to medium heat. Heat the oil then sauté the garlic until light golden. Add remaining Sauce ingredients, simmer for 30 seconds until syrupy.","duration":0.5,"images":[],"step":3},{"title":"Serve","description":"Pour over zucchini, pile on Crispy Asian Shallots and green onion. Eat!","images":[],"step":4}]', '["gluten","sesame","soy"]', '["low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Asian"],"categories":["all-vegetable-sides","asian-recipes","quick-and-easy","vegetarian-recipes","zucchini","zucchini-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6fa5ac5e0230', 'en', 'US', 'Balsamic marinated mushrooms', 'Recipe video above. Roasted mushrooms are delicious. Marinated mushrooms are incredible! Imagine a blend of balsamic vinegar, olive oil, garlic and thyme soaked up by the mushrooms that squirts in your mouth when you bite into it......yes!!!Serve as a meal over mash or polenta, pile on toast smeared with goats cheese, over steak or grilled chicken breast, on the side of a big breakfast fry up, or on a grazing board.', 'https://www.recipetineats.com/tachyon/2023/07/Balsamic-marinated-mushrooms_5.jpg', 5, 35, 40, 4, '[{"id": "ing_mushroom", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_balsamic_vinegar", "quantity": {"value": 0.24, "unit": "bottle of 250ml"}}]', '[{"ingredients":["700g/ 1.4 lb small whole white mushrooms ( or halved larger ones (Note 1))","3 tbsp extra virgin olive oil","1 tsp cooking/kosher salt","1/2 tsp black pepper","5 sprigs fresh thyme (sub 1/2 tsp dried thyme)","2 garlic cloves (, finely minced)","2 garlic cloves (skin on fine), smashed (Note 2)"],"purpose":"Roasted mushrooms:"},{"ingredients":["4 tbsp balsamic vinegar","3 tbsp extra virgin olive oil"],"purpose":"Balsamic marinade:"}]', '[{"description":"Preheat oven to 200°C/375°F (180°C fan).","images":[],"step":1},{"title":"Season","description":"Put mushrooms into a roasting pan (not tray, easier to mix well in pan). They can be snug but should be in a single layer (mushrooms shrink ~25-30%). Toss with olive oil first. Then add salt, pepper, thyme and garlic (minced & whole), then toss again.","images":[],"step":2},{"description":"Roast 35 minutes, tossing well at the 20 minute mark, or until the mushrooms are browned and soft.","images":[],"step":3},{"title":"Marinade","description":"While hot, transfer mushrooms into a bowl (including all the juices). Add balsamic and olive oil. Toss well.","images":[],"step":4},{"title":"Marinate 2 to 24 hrs","description":"Let the mushrooms cool and marinate for 2 hours (uncovered), tossing once or twice, or for even better flavour, marinate overnight (covered in fridge once cool).","images":[],"step":5},{"title":"Serving","description":"Always serve at room temperature or slightly warmed, for best flavour. And don''t waste the juices - it''s full of flavour!","images":[],"step":6},{"title":"Serving options","description":"As part of a grazing board, on polenta or mash as a meal, on toast slathered with goats cheese or cream cheese, on the side of fried eggs, on creamy risotto or risoni/orzo. See in post for a long list!","images":[],"step":7}]', '[]', '["gluten_free","keto_friendly","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["all-vegetable-sides","mushroom-recipes","mushrooms","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_606a306a8219', 'en', 'US', 'Purple rice', 'Recipe video above. Purple rice is a garlicky, butter rice side that owes its vibrant colour to red cabbage! Love this 2-in-1 that combines starch plus plenty of vegetables in one dish, rather than making a salad plus a starch separately. Goes with everything - Western, Asian, Mediterranean, Indian, Mexican!', 'https://www.recipetineats.com/tachyon/2023/02/Purple-rice_1.jpg', 10, 15, 25, 5, '[{"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_red_cabbage", "quantity": {"value": 9.0, "unit": "head"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_rice", "quantity": {"value": 150.0, "unit": "pack"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_green_onion", "quantity": {"value": 0.75, "unit": "bunch"}}]', '[{"ingredients":["30g / 2 tbsp unsalted butter","2 garlic cloves (, finely minced)","1/2 onion (, finely diced)","3 cups finely shredded red cabbage (tightly packed)","1/2 tsp cooking salt (kosher salt)","1/4 tsp black pepper","1 cup jasmin rice (, no need to rinse or soak (Note 1 for other rice))","1 1/4 cup vegetable stock (, low sodium (or chicken stock or water + 1 stock cube- Note 2))"]},{"ingredients":["1/4 cup green onion (, finely chopped)"],"purpose":"Garnish, optional:"}]', '[{"description":"Melt butter in a large saucepan or small pot over medium heat. (Note 3)","images":[],"step":1},{"title":"Sauté veg","description":"Cook onion and garlic for 1 minute until soft. Add cabbage, salt, and pepper. Cook for 2 to 3 minutes, stirring from time to time, until the cabbage starts to soften but not completely floppy (as it will cook more with the rice).","duration":1,"images":[],"step":2},{"title":"Coat rice","description":"Add rice and stir well to coat in the flavour.","images":[],"step":3},{"description":"Add the vegetable stock. Scrape down the sides and press the cabbage-rice mixture down so all the rice is submerged.","images":[],"step":4},{"title":"Cook 12 minutes","description":"Bring to a simmer, then cover with a lid, turn the stove down to medium low (or low on a stronger burner) and cook for 12 minutes. Do not peek or stir!","duration":12,"images":[],"step":5},{"title":"Rest 10 minutes","description":"Turn off the heat, remove the saucepan from the stove and let to rest for another 10 minutes (with the lid on).","images":[],"step":6},{"title":"Fluff & serve","description":"Use a rubber spatula or rice paddle to fluff the rice then tumble into a serving dish. Sprinkle with green onion and serve!","images":[],"step":7}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["all-vegetable-sides","cabbage","easter-sides-warm-hearty","rice-recipes","rice-side-dishes","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0401325e5931', 'en', 'US', 'Glass noodle salad (cellophane / bean thread noodles)', 'Recipe video above. This Asian-style salad combines glass noodles with fresh herbs, vegetables and shredded chicken with a hoisin dressing that''s slightly creamy so it clings nicely to the slippery noodles. The lime cashew crumble really makes this, so don''t skip it!Terrific no-cook meal for hot summer nights. Skip the chicken to turn it into a fabulous starch + veg side for Asian meals. Serves 3 to 4 as a meal, 5 to 6 as a side. More meal-size salads here!', 'https://www.recipetineats.com/tachyon/2023/01/Glass-noodle-salad_2.jpg', 20, 0, 20, 3, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.2, "unit": "pack of 500g"}}, {"id": "ing_chicken", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_cabbage", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_cucumber", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.04, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_mint", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_roasted_cashew_nuts", "quantity": {"value": 150.0, "unit": "jar"}}, {"id": "ing_ime_zest", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_lime", "quantity": {"value": 0.015, "unit": "net of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.225, "unit": "pack of 100g"}}, {"id": "ing_oil", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.056, "unit": "jar of 400g"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_ginger", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_chinese_five_spice", "quantity": {"value": 1.25, "unit": "jar"}}]', '[{"ingredients":["100 g / 3.5 oz bean thread vermicelli noodles / cellophane noodles (Note 1)","3 cups shredded cooked chicken (about 1/2 store bought roast chicken) (Note 2)","2 packed cups ((180g) green cabbage, finely sliced)","1 cucumber (, cut in half, sliced 3mm / 1/8\" thick on the diagonal)","1 carrot (, peeled then julienned)","2 green onion stems (, finely sliced on a diagonal)","1 cup lightly packed coriander/cilantro leaves","1 cup lightly packed mint leaves"],"purpose":"Glass noodle salad:"},{"ingredients":["1 cup unsalted roasted cashew nuts (, roughly chopped)","1 1/2 tsp lime zest","2 tsp lime juice","3/4 tsp caster sugar / superfine sugar (sub ordinary / granulated)","1/2 tsp cooking/kosher salt"],"purpose":"Lime cashew crumble:"},{"ingredients":["3 tbsp light soy sauce","3 tbsp rice vinegar","1 1/2 tbsp sesame oil","1 1/2 tbsp canola oil","1 1/2 tbsp kewpie mayonnaise (or other mayo) (Note 3)","1 tbsp hoisin sauce","3/4 tsp finely grated fresh ginger","1/4 tsp Chinese five spice powder (Note 4)"],"purpose":"Creamy hoisin dressing:"}]', '[{"title":"Glass noodles","description":"Place dry noodles in a bowl and cover with freshly boiled water. Leave for 3 to 4 minutes or until transparent and softened. Drain using a colander, rinse under tap water (for rapid cool and reduce stickiness) then detangle using your fingers. Drain thoroughly before use. Set aside to fully cool.","duration":3.5,"images":[],"step":1},{"title":"Lime cashew crumble","description":"Place ingredients in a bowl and toss. (No marinating time needed)","images":[],"step":2},{"title":"Dressing","description":"Place ingredients in a jar and shake until well combined.","images":[],"step":3},{"title":"Salad","description":"Place glass noodle salad ingredients in a large bowl. Pour over dressing, toss well. Add half the cashews, toss again.","images":[],"step":4},{"title":"Serve","description":"Transfer to a large salad bowl or individual bowls. Sprinkle with remaining lime cashew crumble and serve!","images":[],"step":5}]', '["gluten","nuts","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner","lunch"],"cuisine":["Asian"],"categories":["all-vegetable-sides","no-cook-food","noodles","salad-recipes-main-course","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3a9a280a8af1', 'en', 'US', 'Mexican Corn Salad', 'Recipe video above. A Can''t-Stop-Eating-It delicious way to serve corn, this is a giant salad form of the famous Mexican Street food Esquites, a corn salad sold in cups that you can eat as you wander the streets! I love the way the creamy lime dressing melts into the hot corn as you toss it all together.I urge you to use fresh corn if you can, but this is still super made with frozen corn. Wonderful side dish, especially for Mexican or South Western themed menus!', 'https://www.recipetineats.com/tachyon/2017/03/Mexican-Corn-Salad_9.jpg', 10, 10, 20, 6, '[{"id": "ing_corn", "quantity": {"value": 1.875, "unit": "can of 400g"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.094, "unit": "jar of 400g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.15, "unit": "tub of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_jalapeno", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_onion", "quantity": {"value": 150.0, "unit": "pack of 1kg"}}, {"id": "ing_lime", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_feta_cheese", "quantity": {"value": 60.0, "unit": "block of 200g"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["5 cups corn cut from the cob (~4 large ears) (or frozen corn, not thawed, Note 1)","2 tbsp / 30g butter","2 garlic cloves (, minced)","1/2 tsp each salt and pepper","1/4 cup mayonnaise (can cut down to 2 tbsp)","1/4 cup sour cream (or yoghurt)","1/2 cup parmesan cheese (, finely grated (Note 1))","1 tbsp Jalapeno (, deseeded and finely chopped (optional))","1 cup coriander / cilantro leaves (, roughly chopped)","1 cup green onion (, finely sliced (~2 stems))","1/2 red onion (, finely chopped)","2 - 3 tbsp lime juice (, fresh (plus more to taste))"]},{"ingredients":["60g / 2 oz Cotija or Feta (, crumbled (optional) (Note 2))","Jalapeno slices, coriander/cilantro leaves, lime wedges (, optional)"],"purpose":"Garnishes"}]', '[{"title":"Cut off kernels","description":"Cut the corn off the cob (see photo in post or video for how I do this without getting corn everywhere!) If using frozen, do not thaw.","images":[],"step":1},{"title":"Brown corn","description":"Melt butter in a large skillet over high heat. Add garlic and stir for 10 seconds. Add corn and cook for 5 minutes, stirring every now and then, until you get lovely golden brown bits and the corn is cooked and sweet (don''t stir constantly, harder to brown).","duration":0.16666666666666666,"images":[],"step":2},{"title":"Season corn","description":"Add salt and pepper halfway through cooking corn.","images":[],"step":3},{"title":"Toss with dressing","description":"Transfer corn into large bowl. Add mayonnaise, sour cream, lime juice and parmesan. Toss well to combine - heat will \"melt\" dressing. Add coriander/cilantro, red onion, green onion and jalaepno. Toss again.","images":[],"step":4},{"title":"Serve","description":"Transfer to serving bowl. Crumble over cotija/feta and garnishes of choice. Serve warm or at room temperature.","images":[],"step":5}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Mexican"],"categories":["all-vegetable-sides","corn","dietary","easter-sides-fresh-light","gluten-free-recipes","mexican-recipes","quick-and-easy","side-dishes","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9301eeecda2d', 'en', 'US', 'Cheesy Potato Gratin Stacks (Muffin Tin)', 'Recipe video above. When you combine potatoes, cream, cheese, garlic and butter, you just can''t go wrong. These individual size portions made in a muffin tin are great as a side, for breakfast with eggs (and bacon!) OR as finger food for a party!', 'https://www.recipetineats.com/tachyon/2015/09/Mini-Potato-Dauphinoise-Gratin-Stacks_80.jpg', 15, 45, 60, 12, '[{"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_potato", "quantity": {"value": 1.2, "unit": "bag of 2kg"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_gruyere_cheese", "quantity": {"value": 75.0, "unit": "block of 200g"}}, {"id": "ing_cheese", "quantity": {"value": 75.0, "unit": "block of 250g"}}]', '[{"ingredients":["Oil spray","1.2 kg / 2.4 lb starchy potatoes (, large long ones (Note 1))","30g /2 tbsp butter (, unsalted)","2 garlic cloves (, finely minced)","1/2 cup heavy / thickened cream","1 tsp fresh thyme leaves (or 3/4 tsp dried)","1/2 tsp salt","Black pepper","75g / 2.5 oz gruyere cheese (sliced into 12 squares to fit into muffin tin (or other melting cheese, Note 2))","3/4 cup gruyere cheese ((or other melting cheese), shredded)"]}]', '[{"description":"Preheat oven to 350°F/180°C (all oven types).","images":[],"step":1},{"title":"Brush muffin tin with butter","description":"Melt butter in a saucepan over medium heat then use what you need to lightly brush the muffin tin holes with butter. (Remaining butter is for the cream sauce)","images":[],"step":2},{"title":"Cream sauce","description":"Into the remaining butter, add garlic and cook for 20 seconds. Add cream and salt then bring to a simmer. Simmer for 30 seconds, then remove from stove and keep warm.","duration":0.3333333333333333,"images":[],"step":3},{"title":"Slice potato","description":"Peel potatoes. Trim base so it stands upright. Then cut into cylinder shapes that fit the muffin tin. Cut into 2mm/ 1/10\" slices using a mandolin or sharp knife.","images":[],"step":4},{"title":"Assemble stacks","description":"Place potato slices into the muffin tin so they go halfway up the muffin tin holes. Try to match by size to make them into neat stacks.","images":[],"step":5},{"title":"Cream","description":"Drizzle each potato stack with 1 tsp of cream mixture - use 1/2 of the mixture.","images":[],"step":6},{"title":"Cheese slice","description":"Top with cheese slice.","images":[],"step":7},{"title":"Top with potato, cream then thyme","description":"Top each stack with remaining potato slices so the height is about 1cm / 1/3\" above the rim of the muffin tin (they sink once baked). Drizzle with remaining cream mixture and sprinkle with most of the thyme (reserve some for topping).","images":[],"step":8},{"title":"Baked 40 minutes","description":"Cover loosely with foil and bake for 40 minutes or until potato is cooked through. A small sharp knife should go through without any resistance.","duration":40,"images":[],"step":9},{"title":"Top with cheese, bake 10 minutes","description":"Remove from oven, sprinkle with shredded cheese and bake without foil for 10 minutes or until golden.","duration":10,"images":[],"step":10},{"title":"Garnish with thyme","description":"Sprinkle with remaining thyme.","images":[],"step":11},{"description":"Stand 5 minutes then remove to serve. Use a tablespoon or butter knife to help scope them out. (Note 3)","images":[],"step":12},{"title":"To Serve: Dinner","description":"serve as a side. Finger food - serve warm as is. Breakfast - serve with eggs and bacon.","images":[],"step":13}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["snack"],"cuisine":["French"],"categories":["all-vegetable-sides","dietary","easter-recipes","easter-sides-warm-hearty","gluten-free-recipes","most-popular","potato-recipes","potatoes","side-dishes","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8dab65832cd5', 'en', 'US', 'Japanese Slaw - Chargrill Charlie''s Copycat', 'This is a copycat of a Japanese Slaw sold at a charcoal chicken chain called Chargrill Charlie''s here in Sydney. This slaw-like salad has a Japanese spin with a scattering of edamame, sesame-dressed wakame seaweed salad and a creamy soy dressing. The seaweed totally makes it!Serve it as a side or as a meal with a simple piece of Asian Glazed Salmon or Honey Garlic Chicken Breast.', 'https://www.recipetineats.com/tachyon/2021/08/Japanese-Slaw-Chargrill-Charlies_93.jpg', 15, 0, 15, 4, '[{"id": "ing_cabbage", "quantity": {"value": 15.0, "unit": "head"}}, {"id": "ing_red_cabbage", "quantity": {"value": 6.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.04, "unit": "bunch"}}, {"id": "ing_edamame", "quantity": {"value": 150.0, "unit": "pack"}}, {"id": "ing_japanese_seaweed_salad", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.056, "unit": "jar of 400g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_wasabi_paste", "quantity": {"value": 0.5, "unit": "bottle"}}]', '[{"ingredients":["5 cups (tightly packed) green cabbage (, finely shredded (~1/2 medium head, Note 1))","2 cups (tightly packed) red cabbage (, finely shredded (~1/4 small head, Note 1))","1 carrot (medium) (, peeled and finely shredded (using a julienne shredder, or box grater, Note 2))","2 green onion stems (, finely sliced on the diagonal)","1 cup edamame (, cooked per packet directions (Note 3))","2/3 cup Japanese seaweed salad (, pre dressed (Note 4))"],"purpose":"Japanese Slaw:"},{"ingredients":["1 1/2 tbsp soy sauce","1 1/2 tbsp rice vinegar (sub cider vinegar)","1 1/2 tbsp Kewpie mayonnaise (Note 5)","1 tbsp toasted sesame oil","1 1/2 tbsp olive oil","1 tsp sugar ((any type) or 1 1/2 tsp honey)","1/2 - 1 1/2 tsp wasabi paste (, adjust to taste (entirely optional) (Note 6))"],"purpose":"Dressing:"}]', '[{"title":"Dressing","description":"Shake Dressing ingredients in a jar until the mayonnaise is fully emulsified. Taste and add more sugar if you want.","images":[],"step":1},{"title":"Toss with salad","description":"Place cabbage, carrot, green onion, half the edamame and half the seaweed salad in a bowl. Add about 3/4 of the dressing, toss. (Seaweed will mostly stay in clumps).","images":[],"step":2},{"title":"Wilt","description":"Set aside for 15 minutes to let the cabbage wilt a bit.","duration":15,"images":[],"step":3},{"title":"Serve","description":"Toss again, then pile onto serving platter or bowl. Drape over remaining seaweed salad (in clumps) and edamame, drizzle with remaining Dressing. Serve!","images":[],"step":4}]', '["gluten","sesame","soy"]', '["low_calorie","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Asian-esque"],"categories":["all-vegetable-sides","asian-recipes","cabbage","modern-asian","salad-recipes-main-course","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_81337c1a97e1', 'en', 'US', 'Pear Salad with Blue Cheese and Rocket', 'Classic combination of ingredients, cheeseboard favourites transformed in salad form with the addition of pepper rocket lettuce!Ideal to serve as a starter, light lunch or as a side for a main that''s not too rich.We go light on the dressing here because the blue cheese and juice from the pears act as part of the dressing. See Note 1 for my recommende blue cheeses.', 'https://www.recipetineats.com/tachyon/2021/08/Pear-Blue-Cheese-Rocket-Salad_78.jpg', 15, 0, 15, 5, '[{"id": "ing_pears", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_walnuts", "quantity": {"value": 112.5, "unit": "jar"}}, {"id": "ing_lettuce", "quantity": {"value": 2.4, "unit": "head"}}, {"id": "ing_cheese", "quantity": {"value": 120.0, "unit": "block of 250g"}}, {"id": "ing_mustard", "quantity": {"value": 0.113, "unit": "jar of 200g"}}, {"id": "ing_honey", "quantity": {"value": 0.045, "unit": "jar of 500g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}]', '[{"ingredients":["1 1/2 - 2 pears (, any type, juicy and ripe (or nashi pears or sweet apples))","3/4 cup walnuts (, whole (sub almonds, pecans))","120g / 4oz rocket/arugula lettuce","120g / 4 oz roquefort, gorgonzola, stilton or other good blue cheese, (creamy but can be crumbled into chunks (Note 1))"]},{"ingredients":["1 1/2 tbsp Dijon mustard","1 1/2 tbsp honey","1 1/2 tbsp cider vinegar","1 1/2 tbsp vegetable or olive oil","1/4 tsp salt","1/8 tsp black pepper"],"purpose":"Honey Mustard Dressing:"}]', '[{"title":"Dressing","description":"Shake Dressing in a jar.","images":[],"step":1},{"title":"Pears","description":"Halve then scoop out core. Place cut face down and slice into 3mm / 0.12\" slices. (Note 2)","images":[],"step":2},{"title":"Walnuts","description":"Spread on tray and toast in a 180°C/350°F oven for 8 minutes or until they smell nutty. Leave some whole, break some in half with hands.","duration":8,"images":[],"step":3},{"title":"Dress rocket","description":"In a large bowl, toss rocket with 2 tbsp Dressing.","images":[],"step":4},{"title":"Assemble","description":"Pile 1/3 rocket on a platter. Scatter with 1/3 pears, 1/3 walnuts, 1/3 blue cheese crumbled into small chunks. Repeat twice more. Drizzle with remaining Dressing just before serving.","images":[],"step":5}]', '["milk","mustard"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Western"],"categories":["all-vegetable-sides","leafy-greens","salad-recipes-main-course","uncategorized","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d76c969ce0f2', 'en', 'US', 'Roasted Flat Mushrooms with Green Onion, Thyme & Butter', 'This can be made with any large mushrooms. Roasting them underside-up allows the herb and green onion butter to seep deep in between the mushrooms gills.Covering with foil helps the mushrooms stay nice and moist, while helping the herbs and green onions retain their vibrant emerald colour. It looks so fresh and stunning against the deep brown of the mushroom gills!Simple, easy and exceptionally delicious. Serve as a vegetarian main for 3 - 4 people, starter or side for 6 to 8, or as part of a meatless meal spread.', 'https://www.recipetineats.com/tachyon/2021/08/Large-roasted-mushrooms-with-shallot-scallion-butter_32.jpg', 10, 30, 40, 4, '[{"id": "ing_mushroom", "quantity": {"value": 8.0, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["8 large mushrooms (flat, portobello, \"BBQ\"), around 10 - 12cm / 4 - 4.5\" wide, stem tips trimmed (Note 1)"]},{"ingredients":["100g / 7 tbsp unsalted butter (, softened)","1 cup green onion ((US:scallions), thinly sliced)","1/3 cup parsley (, finely chopped)","1 tbsp fresh thyme leaves (sub 1 tsp dried)","1/2 tsp salt","1/4 tsp black pepper"],"purpose":"Herb & Green Onion Butter:"},{"ingredients":["3 tbsp chopped scallions","1 dozen thyme stalks"],"purpose":"Garnishes (optional):"}]', '[{"title":"Clean mushrooms","description":"See Note 1.","images":[],"step":1},{"description":"Preheat oven to 200°C / 390°F (180°C fan).","images":[],"step":2},{"title":"Mix butter","description":"Mix the Herb & Green Onion Butter ingredients together in a medium bowl.","images":[],"step":3},{"title":"Smear mushrooms","description":"Place mushrooms gills side up on a large tray. Smear the butter mix over the mushroom surfaces. Cover with foil (preserves green colour of herbs).","images":[],"step":4},{"title":"Bake","description":"Bake 25 minutes, until mushrooms are tender.","images":[],"step":5},{"description":"Serve! Arrange on a platter, including all butter and juices on tray. Scatter with thyme stalks and extra scallions over the mushrooms (for a fresh touch), and serve.","images":[],"step":6}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["all-vegetable-sides","mushroom-recipes","mushrooms","quick-and-easy","side-dishes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cf099b4fdafc', 'en', 'US', 'Garden Salad', 'My old school Garden Salad. The one I can make any day because I always have these vegetables on hand! And sometimes, when I feel like getting really fancy, I even add a sprinkle of parsley. 😳There really are no rules when it comes to a Garden Salad. Any greens, any vegetables. Make this your own!', 'https://www.recipetineats.com/tachyon/2021/08/Garden-Salad_47.jpg', 7, 0, 7, 4, '[{"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_cucumber", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_vinegar", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.013, "unit": "jar of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["1 small head iceberg lettuce or other lettuce or leafy greens (, chopped into big bite size pieces (5 to 6 big handfuls))","1 cup cherry or grape tomatoes, halved ((~125g/4oz), or 2 tomatoes cut into wedges or chunks)","1 cucumber (, sliced (medium Lebanese / Persian cucumber, or 1/2 long Telegraph/English cucumber))","1 carrot (, peeled and grated using a box grater)","1 tsp parsley or chives (, very finely chopped (if you''re feeling fancy!))"],"purpose":"Salad:"},{"ingredients":["1 tbsp cider vinegar (or any vinegar or lemon juice) (Note 1)","3 tbsp extra virgin olive oil (or other neutral oil)","1/2 tsp Dijon Mustard (or other non spicy smooth mustard)","1/2 tsp cooking/kosher salt (or 1/4 tsp table salt)","1/2 tsp black pepper"],"purpose":"Dressing:"}]', '[{"title":"Dressing","description":"Shake Dressing in a jar. Taste and adjust - more oil for creamier/less tang, vinegar for more tang, sugar if you want touch of sweet.","images":[],"step":1},{"title":"Toss","description":"Place all Salad ingredients in a big bowl. Pour over Dressing. Toss well.","images":[],"step":2},{"title":"Serve","description":"Transfer to serving bowl and serve immediately!","images":[],"step":3}]', '["mustard"]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Western"],"categories":["all-vegetable-sides","quick-and-easy","side-salads","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0da083f8f9cb', 'en', 'US', 'Panzanella (Italian tomato and bread salad)', 'Panzanella is a classic tomato and bread salad from Tuscany. Bursting with ripe tomatoes, cucumber and basil, it''s hard to think of a salad that screams "summer" any louder. Chunks of lightly toasted bread meanwhile bring delicious texture and some heft to the salad, making it filling enough for lunch or a light meal.Be warned, this salad demands the very best tomatoes! If you don''t have juicy tomatoes, don''t make this. Make another salad instead!And though some Italians may tell you toasting bread is not the traditional way to make Panzanella, don''t skip it. That is, unless you WANT unidentifiable white mush in your bowl within minutes of making this!', 'https://www.recipetineats.com/tachyon/2021/08/Panzanella_24.jpg', 10, 15, 50, 4, '[{"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_basil", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 2.5, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["4 - 5 cups (loosely packed) stale bread (, torn into 2.5cm/1” chunks (~180g/6 oz, depending on bread used))","1 tbsp extra virgin olive oil","4 medium tomatoes (Note 1)","1 tsp cooking/kosher salt (or 3/4 tsp table salt)","2 Lebanese cucumbers (or 1 long telegraph/English cucumber), peeled (optional) (Note 3)","1 cup basil leaves (, loosely packed)"]},{"ingredients":["2 tbsp red or white wine vinegar (Note 4 for other options)","1 tsp Dijon mustard","8 tbsp extra virgin olive oil (, the best you can afford)","1 1/2 tsp garlic (, finely minced (~1 large or 2 small))","1/4 tsp salt"],"purpose":"Dressing:"}]', '[{"description":"Preheat oven to 180°C /350°F (160°C fan).","images":[],"step":1},{"description":"Toss bread chunks with 1 tbsp olive oil in a bowl.","images":[],"step":2},{"title":"Toast","description":"Spread bread on a a tray and toast for about 15 minutes, until the outside is becoming golden and crunchy but the inside is still a little soft, like toast. Remove and leave to cool.","images":[],"step":3},{"description":"Cut tomato into 8 wedges each. Cut some of these wedges into half (I like irregular shapes for this rustic salad).","images":[],"step":4},{"title":"Sweat tomato with salt","description":"Put tomatoes into a colander over a large bowl. Season with the salt, toss and set aside for 10 minutes to draw out the juices. RESERVE the tomato juice in the bowl for the dressing.","duration":10,"images":[],"step":5},{"description":"Cut cucumber into any shaped chunks aroun 2.5cm / 1\" pieces. Again, I like to do irregular but even-sized shapes.","images":[],"step":6},{"title":"Toss veg","description":"Place tomato sweating in colander into large bowl. Add cucumber and basil, toss gently.","images":[],"step":7},{"title":"Tomato Dressing","description":"Add Dressing ingredients into bowl holding the tomato juice, whisk well.","images":[],"step":8},{"title":"Dress salad","description":"Add bread to salad, pour over dressing. Give it a light toss.","images":[],"step":9},{"title":"Rest then serve","description":"Leave for 5 minutes to let the juices soak into the bread, tossing once or twice. Toss once more just before serving!","duration":5,"images":[],"step":10}]', '["gluten","mustard"]', '["vegan","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Italian"],"categories":["all-vegetable-sides","cucumber","italian-recipes","quick-and-easy","tomato"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2522dc6eb002', 'en', 'US', 'Blood Orange Salad', 'This is a salad created to really let blood oranges shine, both visually and flavour wise. Fennel is lightly dressed with just vinegar and olive oil because the idea here is that the juice from the blood oranges acts like a dressing. I couldn''t resist using some of the vibrant ruby red juice to make a small amount of Blood Orange Dressing which I drizzle over just before serving. It looks great, and adds extra flavour!I also like that this salad requires very little salt - the natural sweetness from the oranges carries it.', 'https://www.recipetineats.com/tachyon/2021/08/Blood-Orange-Salad.jpg', 20, 0, 20, 4, '[{"id": "ing_onion", "quantity": {"value": 0.25, "unit": "pack of 1kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_vinegar", "quantity": {"value": 0.09, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_oranges", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_fennel", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}]', '[{"ingredients":["1/4 red onion (, finely sliced or shaved using mandolin 1 mm thick (~1/2 cup))","1/2 tsp white sugar","6 tbsp white wine vinegar (for pickling and dressing)","4 tbsp extra virgin olive oil","1/4 tsp kosher / cooking salt (Note 3)","1/8 tsp pepper","3 blood oranges (Note 1)","1 fennel (, medium, finely sliced or shaved using mandolin 1 mm (4 packed cups, Note 2))","1/4 cup parsley leaves"]}]', '[{"title":"Lightly pickle onion","description":"Mix sugar and vinegar, then add onion and set aside for 15 minutes to lightly pickle (vinegar should just about cover onion). Drain, reserve pickling vinegar.","duration":15,"images":[],"step":1},{"title":"Slice oranges, reserve juice","description":"Cut rind from oranges, then slice into rounds. Reserve all juice on cutting board - you want around 2 teaspoons (if you’re short, sacrifice a slice or two).","images":[],"step":2},{"title":"Blood Orange Drizzle Dressing","description":"Measure out 2 tsp pickling vinegar, shake/whisk with the reserved 2 tsp juice, 2 tbsp EVOO with a pinch of salt and pepper.","images":[],"step":3},{"title":"Lightly dress fennel","description":"Toss fennel in 1 tbsp onion pickling juice, remaining 2 tbsp olive oil, 1/4 tsp salt and 1/8 tsp pepper.","images":[],"step":4},{"title":"Assembling","description":"Place 1/2 orange rounds on plate. Pile over 2/3 the fennel, litter with onion, parsley, place half remaining orange slices on top. Top with remaining fennel, oranges then onion. Sprinkle with parsley leaves. Just before serving, drizzle over the Blood Orange Dressing, mainly on the oranges so it doesn’t stain the fennel too much. Serve immediately!","images":[],"step":5}]', '[]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Western"],"categories":["all-vegetable-sides","fennel","quick-and-easy","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_627b208109e3', 'en', 'US', 'Roasted Vegetables', 'Recipe video above. Knowing how to make Roasted Vegetables well is a life essential! For best results? Don''t mix root vegetables with high moisture vegetables like eggplant and zucchini. Use smashed whole garlic cloves instead of minced which just burns. Same for herbs.And roast in a moderate rather than hot oven so they have time to sweeten and caramelise evenly!I like this mix of vegetables for colour, flavour and texture. Plus (other than the onion) they roast in the same time which keeps things simple. See recipe notes for variations, including other vegetables, herbs etc. Use this recipe for any roast-able vegetables, but separate starchy/dense from watery vegetables.', 'https://www.recipetineats.com/tachyon/2021/07/Roasted-Vegetables_55.jpg', 10, 90, 100, 5, '[{"id": "ing_potato", "quantity": {"value": 400.0, "unit": "bag of 2kg"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_parsnip", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_thyme", "quantity": {"value": 5.0, "unit": "bunch"}}, {"id": "ing_sage", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["400g / 14oz small potatoes (, skin on (10 or so))","2 carrots (, medium/large, peeled)","1 large parsnip ((250g/8oz), peeled)","1 red onion (, large, peeled (200g / 7oz))","5 garlic cloves (, smashed (Note 1))","5 thyme sprigs","3 sage sprigs","4 tbsp extra virgin olive oil","1 tsp cooking/kosher salt","1/4 tsp black pepper"]},{"ingredients":["2 tbsp parsley (, finely chopped)"],"purpose":"Garnish:"}]', '[{"description":"Cutting vegetables:","images":[],"step":1},{"title":"Potatoes","description":"Cut in half. (For large, cut into 3 or 4)","images":[],"step":2},{"title":"Carrots","description":"Cut into 3cm / 1.2\" triangles on the diagonal (see diagram in post).","images":[],"step":3},{"title":"Parsnip","description":"Cut into 4cm / 1.5\" lengths. Then cut into batons / chunks so they are roughly equal size (see diagram in post).","images":[],"step":4},{"title":"Red onion","description":"Cut in half, then cut each half into 4 wedges. Then in cut into 3 or 4 so you get 2cm/ 0.8\" squares.","images":[],"step":5},{"title":"Smashed garlic","description":"Place side of knife on unpeeled garlic clove. Hit firmly with palm of hand so the garlic bursts open a bit but mostly stays in tact.","images":[],"step":6},{"description":"Preheat oven to 200°C / 390°F (180°C fan).","images":[],"step":7},{"title":"Onion","description":"Toss onion in one bowl with 1 tablespoon oil, and a pinch of the salt and pepper. Set aside - we add these later.","images":[],"step":8},{"title":"Other vegetables","description":"Put all other vegetables, thyme and garlic in a separate bowl. Tear sage leaves and stems with hands, add into bowl. Toss with remaining oil, salt and pepper. Spread on a large baking tray.","images":[],"step":9},{"title":"Roasting","description":"Roast 30 minutes. Add onion, toss vegetables. Roast for a further 1 hour, tossing halfway, until cooked through with golden edges.","images":[],"step":10},{"title":"Garnish & serve","description":"Sprinkle with parsley and serve immediately! If you want a sauce for serving (especially if having this as a meal rather than side), I recommend Lemon Yogurt Sauce - drizzle, dollop or dip as you go.","images":[],"step":11}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["all-vegetable-sides","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8f6ed9c25adc', 'en', 'US', 'Ottolenghi''s Green Bean Salad', 'Recipe video above. This is a bewitching green salad adapted from Yotam Ottolenghi''s wildly popular cookbook Jerusalem. It calls for a LOT of fresh chervil and tarragon and it takes time to pick the leaves! Worth the effort to experience the unique combination of flavours when combined with the earthy golden garlic-cumin-coriander dressing.Eastern Mediterranean / Middle Eastern flavours with a touch of French. It''s very, very good!', 'https://www.recipetineats.com/tachyon/2021/07/Ottolenghi-Green-Bean-Salad_6.jpg', 20, 5, 25, 4, '[{"id": "ing_green_beans_trimmed", "quantity": {"value": 500.0, "unit": "pack"}}, {"id": "ing_green_onion", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_chervil", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_tarragon", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_capsicum", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_capers", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["500g/ 1 lb green beans (, trimmed (Note 1))","4 green onions (, finely sliced)","2 cups chervil leaves (Note 2 other herb options)","1/2 cup roughly chopped tarragon leaves (Note 2 other herb options)","2 tsp lemon zest","1/4 tsp salt","1/4 tsp black pepper"]},{"ingredients":["2 red capsicum / bell peppers (, cut into 0.5cm / 0.2\" strips)","2 tsp olive oil","Pinch of salt and pepper"],"purpose":"Sautéed capsicum:"},{"ingredients":["3 tbsp extra virgin olive oil","3 garlic cloves (, finely sliced)","3 tbsp capers (, rinsed and patted dry)","1 tsp cumin seeds","2 tsp coriander seeds"],"purpose":"Dressing:"}]', '[{"title":"Cook beans","description":"Bring a large pot of salted water to the boil. Add beans, bring back up to the boil, then cook for 3 minutes.","duration":3,"images":[],"step":1},{"title":"Drain and dry","description":"Drain, rinse under cold running tap water to cool. Shake off excess water well, then pat dry. Transfer to bowl.","images":[],"step":2},{"title":"Blister capsicum","description":"Heat oil in a heavy based skillet over high heat until smoking. Add capsicum with a pinch of salt and pepper. Cook, stirring every now and then, until tender-crisp with some nice charred edges. Transfer bowl with beans, allow to cool to room temperature.","images":[],"step":3},{"title":"Dressing","description":"Heat oil in a small skillet or saucepan over medium heat. Add garlic and cook for 20 seconds. Add capers and cook for 15 seconds. Add cumin and coriander seeds. Cook until garlic is golden, then immediately pour over the beans.","duration":0.3333333333333333,"images":[],"step":4},{"title":"Toss and serve","description":"Add green onion, herbs, lemon zest, salt and pepper. Toss well. Serve immediately, though it keeps really well overnight too (make sure to serve at room temp).","images":[],"step":5}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Middle Eastern"],"categories":["all-vegetable-sides","easter-sides-fresh-light","green-beans","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3e99e2fd7083', 'en', 'US', 'Sweet Potato Bake', 'Recipe video above. Meet your new favourite sweet potato recipe! Set in a mesmerising ringed pattern, this Sweet Potato Bake is simple to make, eye-catching and tastes even better than it looks. Here''s an excellent, special occasion-worthy side dish that''s still easy enough for dinner tonight!', 'https://www.recipetineats.com/tachyon/2021/06/Sweet-Potato-Bake_4.jpg', 15, 50, 65, 6, '[{"id": "ing_sweet_potato", "quantity": {"value": 1.25, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_rosemary", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["1.25 kg / 2.5 lb 4 -5 sweet potatoes","30g / 2 tbsp unsalted butter (, melted)","2 garlic cloves (, finely minced)","2 tbsp olive oil (, plus a little extra for brushing the skillet)","3/4 tsp kosher / cooking salt","1/4 tsp black pepper","1 tbsp rosemary leaves, finely chopped (, plus more for garnish / serving)"]}]', '[{"description":"Preheat oven to 180°C/350°F (all oven types). Brush skillet base and sides with a little olive oil.","images":[],"step":1},{"title":"Slice potatoes","description":"Slice potatoes 3-4mm thick. A mandoline will make short work of this.","images":[],"step":2},{"title":"Toss","description":"Place in large bowl, pour in all butter plus 1 tbsp olive oil, garlic, rosemary, salt and pepper. Toss well with hands, separating the slices so they are all coated with oil.","images":[],"step":3},{"title":"Layer in skillet","description":"Layer potato in skillet in a circular pattern, overlapping the slices. (See post for details)","images":[],"step":4},{"title":"Bake covered 30 minutes","description":"Cover with foil, bake for 30 minutes until potato is quite soft (almost fully cooked).","duration":30,"images":[],"step":5},{"title":"Brush with oil","description":"Remove from oven, turn up to 220°C/430°F (200°C fan-forced). Remove foil, brush potato with remaining 1 tbsp oil.","images":[],"step":6},{"title":"Bake uncovered 20 minutes","description":"Bake 20 minutes until tops are golden and slightly crisp, and potato is cooked through (check with a knife or skewer).","images":[],"step":7},{"title":"Serve","description":"Scatter with more rosemary leaves, a whole sprig of rosemary and pinch of sea salt flakes if desired. Serve immediately! Sweet potato loses crispiness as it cools.","images":[],"step":8}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["all-vegetable-sides","easter-sides-warm-hearty","potato-recipes","potatoes","side-dishes","sweet-potato"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4bc332be7468', 'en', 'US', 'Lentil Ragout - French Puy lentil side dish', 'Recipe video above. Lentils can be so dull. Trust the French to make them exciting!! Lentil Ragout is a classic French way of cooking lentils. Aromatics are sautéed before simmering Puy Lentils in stock so they absorb the flavour. It''s an outstanding side dish that''s easy to make, the perfect side for any protein.Or just do as I do and eat a whole bowl of this for lunch!', 'https://www.recipetineats.com/tachyon/2014/05/Lentil-Ragout-French-Puy-Lentils_9.jpg', 10, 25, 35, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lentils", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["1 tbsp olive oil","1 garlic clove (, finely minced)","1/2 onion (, finely diced)","1 carrot (large) (, peeled and finely diced)","1 tbsp tomato paste","1 bay leaf (, preferably fresh otherwise dried)","1 thyme sprig","1 cup puy lentils (French lentils) (Note 1)","3 cups vegetable stock","1/2 tsp salt (skip if using store bought)","1/4 tsp black pepper","1 tbsp parsley (, finely chopped)"]}]', '[{"description":"Heat olive oil in a large saucepan over medium heat.","images":[],"step":1},{"title":"Sauté garlic, carrot and onion until softened","description":"around 5 minutes.","images":[],"step":2},{"title":"Cook off tomato paste","description":"Add tomato paste, bay leaf and thyme. Cook 2 minutes.","images":[],"step":3},{"title":"Add lentils, simmer 15 minutes","description":"Add lentils, stock, salt and pepper. Stir, bring to simmer, then lower heat and simmer without a lid for 15 minutes until the lentils are soft (don''t let them overcook so they become mushy!).","duration":15,"images":[],"step":4},{"title":"Season","description":"Stir through parsley. Taste and add more salt or pepper if needed. Serve!","images":[],"step":5}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","vegan","vegetarian"]', '{"mealType":["lunch"],"cuisine":["French"],"categories":["all-vegetable-sides","beans-lentils","lentil-recipes","quick-and-easy","side-dishes","side-salads","vegan-lifestyle","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2b169c00b418', 'en', 'US', 'Pakora (Indian Vegetable Fritters)', 'Recipe video above. Vegetable fritters can be so bland and uninspiring ... but not in the hands of Indian cooks! Pakoras are a traditional Indian street food made with all sorts of vegetables. I''ve used onion, potato and caulifloiwer, but see Note 5 for other options. Serve as starter for an Indian menu, light meal or pass around as canapes. They''re gluten free and vegan so everybody can enjoy them!Spiciness: Mild. Large chillies are not that spicy, and we are using 2 across lots of pakoras! Feel free to omit/reduce the fresh chilli and chilli powder.No deep fry method - See Note 7 for shallow pan-fried version.', 'https://www.recipetineats.com/tachyon/2021/05/Pakora_1.jpg', 20, 20, 40, 40, '[{"id": "ing_flour", "quantity": {"value": 0.338, "unit": "kg"}}, {"id": "ing_turmeric", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_fenugreek_powder", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_chilli", "quantity": {"value": 20.0, "unit": "pack of 100g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 225.0, "unit": "pack of 1kg"}}, {"id": "ing_potato", "quantity": {"value": 2.0, "unit": "bag of 2kg"}}, {"id": "ing_cauliflower", "quantity": {"value": 2.5, "unit": "unit"}}, {"id": "ing_chilli", "quantity": {"value": 20.0, "unit": "pack of 100g"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_oil", "quantity": {"value": 3.0, "unit": "bottle"}}, {"id": "ing_mint", "quantity": {"value": 1.2, "unit": "bunch"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 0.09, "unit": "net of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_ice_cubes", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_yogurt", "quantity": {"value": 0.3, "unit": "tub of 500g"}}, {"id": "ing_mint", "quantity": {"value": 1.2, "unit": "bunch"}}]', '[{"ingredients":["2 1/4 cups chickpea flour (Note 1)","1 tsp turmeric powder","1 tsp cumin powder","1 tsp coriander powder","1 tsp fenugreek powder (Note 2)","1/2 tsp chilli powder (pure chilli powder, Note 3)","2 tsp salt (cooking/kosher salt)","3/4 cups + 2 1/2 tbsp water","1 1/2 cups onions (, grated using standard box grater (~1 1/2 onions))","2 cups potato (~1 large), peeled and grated using standard box grater (Note 4)","2 1/2 cups cauliflower (~1/4 large head), finely chopped into rice size pieces (or grate)","2 large red chillies (cayenne peppers), finely chopped (adjust spiciness to taste, or leave them out)","1 tbsp fresh ginger (, finely grated)","2 tbsp coriander/cilantro leaves (, finely chopped)"]},{"ingredients":["3 - 4 cups vegetable or canola oil (4cm / 1.5\" depth in pot)"],"purpose":"For cooking:"},{"ingredients":["2 cups mint leaves","1 cup coriander/cilantro leaves","1/4 cup eschalot (, sliced)","3 tbsp lime juice","1 tsp caster sugar","1/2 tsp cumin seeds","1/2 tsp cooking/kosher salt","2 ice cubes (loosens + keeps sauce green)"],"purpose":"Coriander Mint Sauce for Pakoras (Option 1):"},{"ingredients":["1 cup plain yoghurt","1/2 cup mint leaves (, packed)","1/4 tsp salt"],"purpose":"Minted Yogurt Sauce (Option 2):"}]', '[{"title":"Make batter","description":"Place chickpea flour in a bowl with the spices (turmeric, cumin, coriander, fenugreek, chilli). Slow whisk in the water.","images":[],"step":1},{"title":"Mix in Vegetables","description":"Add potato, cauliflower, onion, ginger, chilli and coriander. Mix well with a wooden spoon. It should be a thick batter, almost paste-like.","images":[],"step":2},{"title":"Preheat oven to 80°C/175°F","description":"to keep cooked pakoras warm. Set a rack over a tray.","images":[],"step":3},{"title":"Heat oil","description":"Heat 4cm / 1.5\" oil in a large heavy based pot to 180°C/350°F (Note 6).","images":[],"step":4},{"title":"Form patties","description":"Drop 2 tbsp of batter roughly formed into a patty shape into the oil. I use my hands (as is typical in India!) but you can also use 2 tablespoons (be careful of splash-age). Don''t crowd the pot, it will lower the temperature too much.","images":[],"step":5},{"title":"Fry pakoras: Fry 2","description":"3 minutes until golden. Drain on paper towels. Keep cooked pakoras hot in the oven on a rack set over a tray.","images":[],"step":6},{"title":"Serve","description":"Serve pakoras with Coriander Mint Sauce or Minted Yogurt Sauce!","images":[],"step":7},{"description":"Coriander Mint Sauce OR Mint Yogurt Sauce:","images":[],"step":8},{"description":"Place ingredients in a small food processor or Nutribullet, or use a stick blender. Blitz until smooth.","images":[],"step":9}]', '["gluten","milk"]', '["keto_friendly","low_calorie","vegetarian"]', '{"mealType":["snack"],"cuisine":["Indian"],"categories":["all-vegetable-sides","cauliflower","curry-recipes","deep-fried-recipes","dietary","finger-food","fritters-tots-and-similar","gluten-free-recipes","indian-recipes","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ecc2ab94db14', 'en', 'US', 'Twice Baked Potatoes (Stuffed Jacket Potatoes)', 'Recipe video above. Baked potatoes stuffed with a creamy, cheesy, mashed potato filling hit with salty pops of bacon. Think of it as the spud love-child of jacket potatoes and mashed potato! This is pretty much every cheese lovin,’ carb monster''s dream come true. Dainty food this ain''t – this is proper comfort food, turned up to 11!Serve it as a side, or as a meal.', 'https://www.recipetineats.com/tachyon/2021/05/Twice-Baked-Potatoes_5.jpg', 15, 75, 90, 8, '[{"id": "ing_potato", "quantity": {"value": 4.0, "unit": "bag of 2kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_butter", "quantity": {"value": 120.0, "unit": "block of 250g"}}, {"id": "ing_cream", "quantity": {"value": 0.333, "unit": "carton of 250ml"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.06, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_chives", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}]', '[{"ingredients":["4 x 300g / 10oz potatoes ( - Sebago (Aus), Russet (US), Maris Piper / King Edwards (UK) (Note 1))","1 tbsp canola or vegetable oil","1/2 tsp salt"]},{"ingredients":["200g / 7oz bacon (streaky) (, chopped into small batons (Note 2))","120g / 8 tbsp unsalted butter","1/3 cup cream (pure or thickened / heavy)","1 cup cheddar cheese (, shredded (Note 3))","3 green onions (, finely sliced)","1/4 tsp salt","1/4 tsp pepper"],"purpose":"Creamy potato filling:"},{"ingredients":["1 1/2 tbsp chives (, finely chopped (garnish))","Sour cream (recommended!)"],"purpose":"Garnish and serving (optional)"}]', '[{"description":"Preheat oven to 220°C / 430°F (200°C fan). Place a rack on a tray (recommended but not critical).","images":[],"step":1},{"title":"Prick potatoes","description":"Wash, scrub and dry potatoes well. Prick each potato 8 times with a fork.","images":[],"step":2},{"title":"Oil and salt","description":"Put potatoes in a bowl, pour over oil and rub onto potatoes. Then sprinkle over salt and use your hands to coat. (Just do this as best you can. Some will stick, much will not!)","images":[],"step":3},{"title":"Bake","description":"Place potatoes on rack and bake for 75 minutes or until you can pierce with a small knife with no resistance.","duration":75,"images":[],"step":4},{"description":"Prepare filling add-ins:","images":[],"step":5},{"title":"Cook bacon","description":"Place bacon in a cold non-stick pan over medium heat. When the fat starts to melt, turn the heat up to high and cook bacon until golden. Drain on paper towels.","images":[],"step":6},{"title":"Heat butter and cream","description":"Melt butter in a saucepan over medium heat. Then add cream and heat until hot, but don''t let it boil. (You could also do this in a microwave)","images":[],"step":7},{"description":"Stuff potatoes:","images":[],"step":8},{"title":"Lower oven","description":"Turn oven down to 200°C / 390°F (180°C fan).","images":[],"step":9},{"title":"Scoop out potato flesh","description":"Allow potatoes to cool enough so you can handle them (or use a tea towel). Cut in half lengthwise and scoop out potato flesh, leaving 0.7cm (1/3\") thick layer of potato still stuck to skin.","images":[],"step":10},{"title":"Mash potato","description":"Place potato flesh in a bowl and mash while hot until smooth.","images":[],"step":11},{"title":"Add-ins","description":"Add half the cheese (save the rest for topping), most of the bacon (save a bit for garnish), all the green onion, hot cream and butter, salt and pepper. Stir to combine.","images":[],"step":12},{"title":"Stuff and top with cheese","description":"Fill potato skins with the mashed potato mixture. Top with remaining cheese.","images":[],"step":13},{"title":"Bake","description":"Bake for 20 to 25 minutes until the cheese is melted, golden and bubbly.","duration":22.5,"images":[],"step":14},{"title":"Serve","description":"Serve immediately, garnish with sour cream, reserved bacon and chives.","images":[],"step":15}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["American","Western"],"categories":["all-vegetable-sides","dietary","easter-sides-warm-hearty","gluten-free-recipes","potato-recipes","potatoes","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_072c6ca55ea2', 'en', 'US', 'German Potato Salad', 'Recipe video above. This is a warm potato salad, German-style! Slices of boiled potato are tossed in a warm, tangy-sweet bacon vinaigrette while hot so they absorb the flavour. They''re then showered with crispy, golden bacon bits and hit with freshness from dill and green onion. This excellent combination of flavours and textures makes this quite possibly my all-time favourite potato salad!', 'https://www.recipetineats.com/tachyon/2021/05/German-Potato-Salad_4.jpg', 10, 25, 35, 6, '[{"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 0.5, "unit": "pack of 200g"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_oil", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.167, "unit": "bottle of 500ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.04, "unit": "bunch"}}, {"id": "ing_dill", "quantity": {"value": 0.045, "unit": "kg"}}]', '[{"ingredients":["1 kg / 2 lb baby red potatoes or other small waxy potatoes (Note 1)","2 tsp salt","100g / 3oz streaky bacon (, chopped into 2cm x 4mm (0.8 x 0.15\") lardons )","1/4 red onion (, sliced)","1/4 cup canola oil (or grapeseed)","1/3 cup apple cider vinegar","2 tbsp white sugar","2 green onions (, finely sliced)","3 tbsp fresh dill (, finely chopped (sub parsley))"]}]', '[{"description":"Cook potato:","images":[],"step":1},{"title":"Boil potatoes","description":"Place the baby potatoes in a large pot of cold water with the salt. Bring to the boil then reduce heat. Simmer 10 minutes or until just cooked through but still slightly firm in the centre (they will continue cooking as they cool, you don''t want to overcook them so they hold their shape).","images":[],"step":2},{"title":"Slice","description":"Drain and set aside to cool slightly, then slice into rounds about 0.7cm / ¼\" thick.","images":[],"step":3},{"title":"Cook bacon","description":"Place bacon in a large, unheated non-stick pan or well-seasoned cast iron skillet. Turn the heat to medium. As the bacon heats up, the fat will start to melt. Turn the heat up to medium-high and cook the bacon until it starts to turn golden – about 3 minutes.","images":[],"step":4},{"title":"Cook onion","description":"Turn heat down to medium. Add the red onion slices and cook 3 minutes or until the onion is soft.","images":[],"step":5},{"title":"Add vinegar and sugar","description":"Add the cider vinegar and sugar, bring to a simmer, scraping the base of the pan to dissolve all the golden bits stuck to the pan into the liquid.","images":[],"step":6},{"title":"Add oil","description":"Add the oil, and simmer for 2 minutes longer. The dressing is now ready.","duration":2,"images":[],"step":7},{"title":"Toss potato through","description":"Add potatoes and gently toss using two spatulas for 1 minute or so, until all the potatoes are well coated in the dressing and absorb some of the dressing.","duration":1,"images":[],"step":8},{"title":"Check for salt","description":"Taste and add more salt if you want (the bacon already should add enough).","images":[],"step":9},{"description":"Assemble salad:","images":[],"step":10},{"title":"Layer potatoes","description":"Pile about 1/4 of the potato on to a platter or in a bowl. Sprinkle with 1/4 of the green onion and dill. Top with another 1/4 of potato, sprinkle with more green onion and dill. Repeat until all used up.","images":[],"step":11},{"description":"Serve! I love it served warm, but it''s also terrific at room temperature!","images":[],"step":12}]', '[]', '["gluten_free","low_calorie"]', '{"mealType":["main_course"],"cuisine":["German","Western"],"categories":["all-vegetable-sides","dietary","german-food","gluten-free-recipes","potato-recipes","potatoes","side-salads","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_73aebd3c9735', 'en', 'US', 'German Cucumber Salad', 'This is a recipe for a refreshing German Cucumber Salad. Called Gurkensalat, it''s a staple side salad you''ll find versions of in every household in Germany. It''s particularly favoured during the warmer weather for its cooling effects, as well as alongside rich mains such as German Pork Knuckle.It will go with virtually any European or Western dish, as it has a clean, neutral flavour.The dressing is very thick at first, but it naturally becomes diluted with the cucumber juices so you end up with a thinner, white dressing. This makes this Cucumber Salad refreshing rather than cloying. Don''t skip the dill, it really makes it!', 'https://www.recipetineats.com/tachyon/2021/05/German-Cucumber-Salad_4.jpg', 10, 0, 10, 5, '[{"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.3, "unit": "tub of 250g"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_dill", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["2 English / telegraph cucumbers (ie. long cucumbers. Sub 4 x Lebanese cucumbers, Note 1)"]},{"ingredients":["1/2 cup sour cream (sub plain, thick yogurt)","1 tbsp white vinegar (plain distilled vinegar)","1 tsp white sugar","1 tbsp fresh dill (, finely chopped)","1/2 tsp salt","Black pepper"],"purpose":"Dressing:"}]', '[{"description":"Peel cucumbers and finely slice into 2mm / 0.2\" slices using a mandoline (or by hand and show off your knife skills!)","images":[],"step":1},{"description":"Mix dressing ingredients in a small bowl.","images":[],"step":2},{"description":"Toss cucumbers with dressing, then set aside for at least 4 hours or even overnight. The cucumbers will soften and leach juice which will thin the dressing to the right consistency.","images":[],"step":3},{"title":"Serving","description":"Toss well then transfer to bowl for serving. Serve chilled for the most refreshing flavour!","images":[],"step":4}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["lunch"],"cuisine":["German"],"categories":["all-vegetable-sides","cucumber","dietary","german-food","gluten-free-recipes","side-salads","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_330f864f40e2', 'en', 'US', 'Ratatouille (French Vegetable Stew)', 'Recipe video above. Ratatouille is a French vegetable stew that at first glance seems like a humble dish – because it is. Made well though, it''s a summery stunner bursting with the sunny tastes of the Mediterranean! The key to flavour-packed ratatouille is to sauté each vegetable separately before braising everything together. Ratatouille can comfortably star as a vegetarian main, otherwise it makes a perfect vegetable side.Makes side for 6 to 8 people, main meal for 4 people.', 'https://www.recipetineats.com/tachyon/2021/04/Ratatouille_0.jpg', 15, 45, 60, 8, '[{"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.09, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_zucchini", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_black_olives", "quantity": {"value": 20.0, "unit": "bottle"}}, {"id": "ing_basil", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["1 eggplant (aubergine) (, cut into 2cm / ¾\" cubes (leave skin on) (~450g / 16oz))","1/2 tsp salt (, cooking / kosher salt)"],"purpose":"Eggplant:"},{"ingredients":["3 tomatoes (, chopped (~150g / 5oz each), Note 1 canned subs)","6 tbsp extra virgin olive oil","2 brown onion (, chopped 1cm / ⅖\" cubes (~150g / 5oz each))","2 capsicum (1 red, 1 yellow), ( cut into 2cm / ⅘\" cubes (~200g / 7oz each))","2 zucchinis (courgettes), ( diced into 1.5cm / ½\" pieces (~200g / 7oz each))","2 garlic cloves (, finely chopped (~3 tsp))","1 tsp fresh thyme leaves (, chopped (Note 2 for subs))","3/4 tsp salt (, cooking/kosher salt)","1/4 tsp black pepper","20 black olives (, pitted, halved)"],"purpose":"Other ingredients for Ratatouille:"},{"ingredients":["1 tbsp fresh basil (, finely chopped, plus more for garnish (Note 2 subs))","Extra virgin olive oil (, for drizzling)"],"purpose":"Finishing:"}]', '[{"title":"Sweat eggplant","description":"Place eggplant in a colander set over a bowl. Sprinkle with salt, toss with hands. Leave for 30 minutes to sweat (no need to wipe off water that beads on surface).","duration":30,"images":[],"step":1},{"title":"Make tomato puree","description":"Place tomato in a blender, food processor or other appliance of choice. Blitz until smooth. (No need to do this if using passata or crushed tomato.)","images":[],"step":2},{"description":"Cook vegetables:","images":[],"step":3},{"title":"Cook eggplant","description":"Heat 2 tbsp oil in a large skillet over medium high heat. Add eggplant and cook for 4 to 5 minutes, stirring regularly, until it''s golden on the surface but still somewhat firm and raw inside. Transfer to a large pot.","duration":4.5,"images":[],"step":4},{"title":"Cook onion and garlic","description":"In the same skillet, add another 1 tbsp olive oil. Add onion and garlic with a pinch of the salt. Cook for 3 minutes until onion is soft with a hint of golden on the edges. Add to pot holding eggplant.","duration":3,"images":[],"step":5},{"title":"Cook capsicum","description":"Add another 1 tbsp of olive oil and cook the capsicum with a pinch of salt for 3 minutes. It should still be firm inside. You won''t get much colour on the capsicum, this is OK. Add to pot.","duration":3,"images":[],"step":6},{"title":"Cook zucchini","description":"Add another 1 tbsp olive oil and cook the zucchini with a pinch of salt for 3 minutes. Make sure it stays firm (ie. raw inside). Like the capsicum, it won''t go golden. Add to pot.","duration":3,"images":[],"step":7},{"title":"Add remaining ingredients to pot","description":"Turn the stove under the pot to medium-high. Add tomato, thyme, olives, remaining salt and all the pepper, and mix. Once the mixture is hot, reduce heat to a low simmer.","images":[],"step":8},{"title":"Braise: Cook for 20","description":"25 minutes with the pot lid off, stirring every now and then, until all the vegetables are cooked through and the liquid has reduced. The mixture should be thick enough so you can pile it on a plate (ie. not watery), but still very moist and juicy.","duration":22.5,"images":[],"step":9},{"title":"Basil and salt","description":"Taste and add more salt if needed; vegetables can taste bland if not enough salt is added. Stir through basil then serve immediately, drizzled with extra virgin olive oil and a sprinkle of extra basil on top, if desired. Serve as a main with crusty bread, or as a side dish. See above recipe card for more ideas!","images":[],"step":10}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["French","Western"],"categories":["all-vegetable-sides","dietary","easter-sides-warm-hearty","gluten-free-recipes","low-calorie-recipes","side-dishes","stews","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1c1e86451385', 'en', 'US', 'Cauliflower Cheese', 'Recipe video above. Most people think of this British classic as a side dish, but as far as I''m concerned, it''s equally worthy as a main!Most recipes will have you just boil the cauliflower, but it''s honestly so much tastier roasted. As for the cheese? I''ve gone with my favourite combination of Red Leicester and gruyere! Excellent melting qualities for a silky smooth sauce with a gorgeous golden colour and wonderful flavour. But any melting cheese will work a treat here. See the post for details!', 'https://www.recipetineats.com/tachyon/2021/04/Cauliflower-Cheese_5.jpg', 10, 60, 70, 5, '[{"id": "ing_cauliflower", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_nutmeg_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}]', '[{"ingredients":["1kg / 2 lb cauliflower florets (1 very large, 1 1/2 medium or 2 small cauliflower heads, Note 1)","2 tbsp extra virgin olive oil","1/2 tsp sea salt","1/8 tsp pepper"],"purpose":"Roasted cauliflower:"},{"ingredients":["60g / 4 tbsp unsalted butter","3½ tbsp flour (, plain / all-purpose)","1 cup milk (full fat best)","1 cup cream (or more milk)","1/2 tsp cooking salt (kosher salt)","1/4 tsp nutmeg powder (freshly grated is best)","1 cup Red Leicester cheese (or cheddar), grated (Note 2)","1/2 cup gruyère cheese (, grated (or other melting cheese of choice, Note 2))"],"purpose":"Cheese sauce (Mornay sauce):"},{"ingredients":["1/2 cup Red Leicester cheese (or cheddar), grated (Note 2)","1/2 cup gruyère cheese (, grated (or other melting cheese of choice, Note 2))"],"purpose":"Topping:"}]', '[{"description":"Roasted cauliflower:","images":[],"step":1},{"description":"Preheat oven to 220°C / 430°F (200°C fan).","images":[],"step":2},{"description":"Toss cauliflower in oil, salt and pepper. Spread on a large tray.","images":[],"step":3},{"description":"Roast 20 minutes (don''t turn). Cauliflower should still be a bit firm, but with some colour on them. Remove from oven.","images":[],"step":4},{"description":"Turn oven down to 180°C/350°F.","images":[],"step":5},{"description":"Cheese sauce (Mornay sauce):","images":[],"step":6},{"title":"Heat milk: Heat milk and cream until hot","description":"either on the stove or in microwave.","images":[],"step":7},{"title":"Make roux","description":"Melt butter in a large saucepan or small pot over medium heat. Add flour and cook, stirring regularly, for 3 minutes.","duration":3,"images":[],"step":8},{"title":"Add milk","description":"While stirring, pour in half the milk. Once the roux is dissolved into the milk (mixture will thicken), stir in remaining milk. Stir on the heat for 1 minute – mixture should be thick enough to coat a wooden spoon.","duration":1,"images":[],"step":9},{"title":"Add cheese","description":"Turn the stove off, but leave the pot on the turned off stove. Stir in salt, nutmeg and both cheeses. The cheese will thicken the mixture so it''s like a thick sauce.","images":[],"step":10},{"title":"Mix in cauliflower","description":"Add cauliflower and toss to coat in the sauce.","images":[],"step":11},{"title":"Fill baking dish","description":"Transfer mixture to a 2L / 2qt baking dish (30 x 20 x 5cm / 12 x 8 x 2\").","images":[],"step":12},{"title":"Top with cheese","description":"Sprinkle over gruyère followed Red Leicester cheese.","images":[],"step":13},{"description":"Bake at 180°C/350°F for 30 minutes until the cheese is melted, and cauliflower is bubbly and golden.","duration":30,"images":[],"step":14},{"title":"Serve","description":"Sprinkle with parsley if desired. Stand 5 minutes then serve!","images":[],"step":15}]', '["gluten","milk"]', '["vegetarian"]', '{"mealType":["main_course"],"cuisine":["British","Western"],"categories":["all-vegetable-sides","cauliflower","easter-sides-warm-hearty","side-dishes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9d6ffec11b7e', 'en', 'US', 'Red Potato Salad with Bacon and Corn (No mayonnaise!)', 'Recipe video above. Here''s a terrific potato salad peppered with tasty bacon bits and charred golden pops of sweet corn. Forget mayonnaise! We''re using a cider vinegar dressing that doubles as a marinade for the hot potatoes so they absorb flavour as they cool. Make the most of every opportunity to pump up the flavour!Serve at room temperature or just slightly warm. Not hot and definitely not fridge cold (criminal!)', 'https://www.recipetineats.com/tachyon/2021/04/Red-Potato-Salad-with-Bacon-and-Corn_9.jpg', 15, 15, 30, 6, '[{"id": "ing_potato", "quantity": {"value": 1.2, "unit": "bag of 2kg"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.04, "unit": "bunch"}}, {"id": "ing_corn", "quantity": {"value": 2.0, "unit": "can of 400g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.04, "unit": "bunch"}}, {"id": "ing_bacon", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.12, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_mustard", "quantity": {"value": 0.013, "unit": "jar of 200g"}}, {"id": "ing_sugar", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["1.2kg / 2.4 lb red potatoes (, sliced 0.8cm / ⅓\" thick (5cm / 2\" round, Note 1))","1 tbsp salt (for cooking potatoes)","1 eschalot (, finely sliced (US: shallot, Note 2))","2 ears of corn (whole, Note 3)","2 green onions (, finely sliced (3/4 cup))","200g / 7oz bacon ((streaky is best!), chopped)"]},{"ingredients":["3 tbsp cider vinegar","8 tbsp extra virgin olive oil","1 clove garlic (, minced or grated)","1/2 tsp dijon mustard","3/4 tsp white sugar","1/2 tsp salt","1/4 tsp black pepper"],"purpose":"Cider vinegar dressing:"}]', '[{"title":"Dressing","description":"Shake Dressing in a jar.","images":[],"step":1},{"title":"Cook potato","description":"Bring a large pot of water to the boil and add salt. Add potato. Bring it back up to the boil, then cook for 5 minutes or until just soft. Keep an eye on them – sliced potatoes cook quickly, and if they overcook they will break when tossing.","duration":5,"images":[],"step":2},{"title":"Drain and marinate","description":"Drain potatoes, then transfer them to a bowl. Handle gently – the shape of these potatoes make them prone to breaking while hot (they''re firmer when cool). Pour over 3/4 of the dressing, add eschalots and toss very gently. Set aside to marinate for 30 minutes.","duration":30,"images":[],"step":3},{"title":"Cook bacon","description":"Place bacon in a cold non-stick pan then turn the stove to medium high. As the pan heats, the bacon fat will melt so there''s no need for oil! Cook bacon, stirring constantly (to avoid spitting!), until golden or to your taste. Drain on paper towels.","images":[],"step":4},{"title":"Cook corn","description":"Meanwhile, cook corn cob using one of these methods. Either grill on the BBQ (10 min on high) or directly over the gas flame on your stove (6 min, direct contact with flame), until nicely charred and corn is cooked. Otherwise, cut the corn off the kernels then pan fry on high heat in residual bacon fat or 1 tbsp olive oil until charred.","images":[],"step":5},{"title":"Cut off kernels","description":"Cut kernels off cob, trying to keep of the kernels in clumps (looks nice!). (Note 4 for my method)","images":[],"step":6},{"title":"Make salad","description":"To the same bowl, add all the corn, half the bacon and most of the green onion. Toss gently, then transfer to serving bowl. Scatter with reserved bacon and green onion, drizzle over remaining Dressing. Serve!","images":[],"step":7}]', '["mustard"]', '["gluten_free"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["all-vegetable-sides","dietary","easter-sides-warm-hearty","gluten-free-recipes","potato-recipes","potatoes","side-dishes","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_95e46d5dc398', 'en', 'US', 'Cabbage and Carrot Thoran-style Salad (Indian Salad)', 'A surprising flavour combination that''s knock-your-socks-off-good: Finely shredded cabbage and carrot are tossed with a spiced coconut Indian "sambal" of sorts. Based on the traditional Indian Thoran dry curry, this Indian Salad ridiculously delicious!Note: Pictured salad is a double batch of the recipe written below', 'https://www.recipetineats.com/tachyon/2021/02/Cabbage-Carrot-Thoran_0.jpg', 15, 10, 25, 5, '[{"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_mustard", "quantity": {"value": 0.019, "unit": "jar of 200g"}}, {"id": "ing_cumin", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_eschalots", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_chilli", "quantity": {"value": 0.01, "unit": "pack of 100g"}}, {"id": "ing_curry_leaves", "quantity": {"value": 12.0, "unit": "kg"}}, {"id": "ing_turmeric", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_desiccated_coconut", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_red_cabbage", "quantity": {"value": 0.25, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}]', '[{"ingredients":["2 tbsp coconut oil (, unrefined (Note 1))","3/4 tsp black mustard seeds (Note 2)","3/4 tsp cumin seeds","3 eschalots (USA: shallots) (, finely diced (Note 3))","1/2 onion ((large), finely diced)","3 garlic cloves (, finely minced)","1 green chilli (, deseeded and finely chopped (Note 4))","12 curry leaves (, fresh (Note 5))","1/2 tsp tumeric powder","1/2 cup desiccated coconut (, unsweetened (Note 6))","1/2 cup water","3/4 tsp salt","1/4 small red cabbage (, very finely sliced (~6 cups))","2 small carrots or 1 very large carrot (, peeled and finely shredded)"]},{"ingredients":["1/4 cup fresh coriander/cilantro leaves (, roughly chopped)"],"purpose":"Garnish:"}]', '[{"description":"Melt oil in a large non-stick skillet over medium high heat.","images":[],"step":1},{"title":"Add black mustard seeds and cook for 30 seconds","description":"they will pop and sizzle","duration":0.5,"images":[],"step":2},{"description":"Add cumin seeds and cook for 30 seconds.","duration":0.5,"images":[],"step":3},{"description":"Add eschalot and onion, cook for 3 minutes until translucent but not coloured.","duration":3,"images":[],"step":4},{"description":"Add garlic and green chilli, cook for 2 minutes until softened but not golden.","duration":2,"images":[],"step":5},{"description":"Add turmeric and curry leaves, cook for 30 seconds.","duration":0.5,"images":[],"step":6},{"description":"Add coconut, water and salt. Cook until water mostly evaporates – about 3 minutes.","images":[],"step":7},{"description":"Place carrot and cabbage in a large bowl. Add hot coconut mixture. Toss well – the cabbage should wilt from the heat.","images":[],"step":8},{"description":"Taste and check if it needs more salt for your taste.","images":[],"step":9},{"description":"Toss through coriander. Serve warm or at room temperature. Best eaten on the day of making. See Note 7 regarding reheating/making ahead.","images":[],"step":10}]', '["mustard"]', '["gluten_free","keto_friendly","low_calorie","vegan","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Indian"],"categories":["all-vegetable-sides","cabbage","curry-recipes","indian-recipes","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3557a8c149b9', 'en', 'US', 'Peach Salad II with Orange Poppyseed Dressing', 'This is my go-to Peach Salad, the one that makes an appearance alongside everything all summer long! The combination of flavours in this just works so well together - juicy sweet peaches, peppery rocket, creamy salty pops of feta, soft crunch of walnuts and a nutty poppyseed dressing with a hint of orange flavour.(PS In case you are wondering, Peach Salad I is my luxe version involving fresh mozzarella and prosciutto. It''s practically a centrepiece in itself!)', 'https://www.recipetineats.com/tachyon/2021/02/Peach-Salad-with-Poppyseed-Dressing_Thumbnail-Cover.jpg', 15, 0, 15, 6, '[{"id": "ing_baby_rocket_arugula", "quantity": {"value": 0.12, "unit": "kg"}}, {"id": "ing_peaches", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_walnuts", "quantity": {"value": 50.0, "unit": "jar"}}, {"id": "ing_cream", "quantity": {"value": 0.28, "unit": "carton of 250ml"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.09, "unit": "L"}}, {"id": "ing_oranges", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_poppy_seeds", "quantity": {"value": 15.0, "unit": "jar"}}, {"id": "ing_sugar", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}]', '[{"ingredients":["120g/ 4oz baby rocket/arugula","2 yellow peaches (, ripe and juicy, halved then cut into thin slices (nectarines also work))","1/3 cup walnuts (, lightly toasted then broken or chopped into pieces (Note 1))","70g / 2oz creamy Danish feta (or Persian marinated feta or goats cheese)"],"purpose":"Salad:"},{"ingredients":["2 tbsp apple cider or white wine vinegar","6 tbsp extra virgin olive oil (or a nut oil)","1 tsp orange zest (, finely grated (optional))","2 tsp Dijon mustard","1 tbsp poppy seeds","1/4 tsp sugar","1/4 tsp salt"],"purpose":"Dressing:"}]', '[{"title":"Dressing","description":"Shake ingredients in a jar.","images":[],"step":1},{"description":"Place rocket in a bowl. Drizzle with just a little bit of dressing, then toss to coat.","images":[],"step":2},{"description":"Transfer 1/3 of the salad to serving bowl, scatter over 1/3 peaches, walnuts and feta, drizzle with dressing. Repeat twice more. Serve!","images":[],"step":3}]', '["milk","mustard"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Western"],"categories":["all-vegetable-sides","holiday-salad-marathon","peach-recipes","side-salads","with-fruits"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5ef8766ed096', 'en', 'US', 'Honey-Cinnamon Pumpkin Lentil Salad', 'This is a recipe inspired by the flavours of a Spiced Sweet Potato Lentil Salad from a cookbook called Community by Sydney local Hetty McKinnon. Lentils are tossed with cinnamon-perfumed, pan-roasted pumpkin, along with candied walnuts, a handful of greens and drizzle with a spiced Honey Dressing. SO MOUTH-WATERINGLY GOOD, this is definitely what I consider to be a Company-Worthy Salad: Filling, nutritious, and something different. It makes an excellent vegetable meal option or work lunch idea, else as a substantial side.', 'https://www.recipetineats.com/tachyon/2021/02/Honey-Cinnamon-Pumpkin-Lentil-Salad_Thumbnail-18.jpg', 15, 25, 40, 4, '[{"id": "ing_pumpkin", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_cinnamon", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_lentils", "quantity": {"value": 2.0, "unit": "can of 400g"}}, {"id": "ing_rocket_arugula", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_walnuts", "quantity": {"value": 112.5, "unit": "jar"}}, {"id": "ing_maple_syrup", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_honey", "quantity": {"value": 0.045, "unit": "jar of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_ginger", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["400g / 14 oz pumpkin or butternut squash","2 tbsp extra virgin olive oil","1 tsp cinnamon","1/2 tsp all spice","1/4 tsp salt"],"purpose":"Cinnamon Pumpkin:"},{"ingredients":["800g/ 28oz canned lentils (, well drained & patted dry (Note 1))","2 cups (packed) rocket/arugula leaves (preferably baby, otherwise hand-tear large ones)","1/2 red onion (, finely sliced)","3 tsp fresh thyme leaves"],"purpose":"Salad:"},{"ingredients":["3/4 cup walnuts (or pecans)","1 1/2 tbsp honey ((must be runny, so warm if super-thick), or maple syrup)","1/4 tsp cinnamon","Pinch of salt"],"purpose":"Honey Walnuts (optional, can just use plain walnuts, Note 2):"},{"ingredients":["2 tbsp red wine vinegar","2 tbsp honey","4 tbsp extra virgin olive oil","1 garlic clove ((small), finely grated)","1/4 tsp allspice powder","1/4 tsp ginger powder","Salt and pepper"],"purpose":"Dressing:"}]', '[{"description":"Pan-roasted spiced pumpkin:","images":[],"step":1},{"description":"Toss pumpkin with 1 tbsp olive oil, cinnamon, all spice and salt.","images":[],"step":2},{"title":"Pan roast","description":"Heat a large non stick skillet with 1 tbsp olive oil over medium high heat. Add about half the pumpkin, spreading out into one layer. Cook for 3 minutes until golden. Turn and cook the other side for 3 minutes until golden and cooked through. Remove and let cool until just warm.Repeat with other half of the pumpkin, adding a little more oil to the pan if required.","duration":3,"images":[],"step":3},{"title":"Toss","description":"Place walnuts in a bowl, drizzle with honey, sprinkle with cinnamon and salt. Mix, spread on paper-lined baking tray.","images":[],"step":4},{"title":"Bake","description":"Bake at 180°C/350°F (160°C fan) for 15 minutes, tossing once halfway. Leave to cool, then use fingers to roughly break walnuts up into slightly smaller pieces.","duration":15,"images":[],"step":5},{"title":"Dressing","description":"Place ingredients in a jar and shake well.","images":[],"step":6},{"title":"Toss","description":"Place lentils, rocket, red onion, thyme and pumpkin in a large bowl. Pour over most of the Dressing, then gently toss.","images":[],"step":7},{"title":"Plate up","description":"Pile up on serving platter. Sprinkle with candied walnuts. Drizzle over remaining Dressing, then serve!","images":[],"step":8}]', '[]', '["gluten_free","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Middle Eastern-ish"],"categories":["all-vegetable-sides","beans-lentils","dietary","gluten-free-recipes","holiday-salad-marathon","pumpkin","pumpkin-squash","salad-recipes-main-course","side-salads","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c2296618aa79', 'en', 'US', 'Potatoes au Gratin (Dauphinoise)', 'Recipe video above. The ultimate potato bake, created by the French!!! Potato + cream + cheese with a hint of garlic and thyme = pure heaven. Based on Julia Child''s Potato Dauphinoise recipe. This is THE perfect make ahead potato dish, the most luxurious of all potato casseroles, the better version of Scalloped Potatoes!Authenticity note: traditional Dauphinoise in France does not contain cheese. But I could never imagine making it without..... It makes it better. You know it does!', 'https://www.recipetineats.com/tachyon/2014/12/Potatoes-au-gratin_2.jpg', 15, 90, 105, 8, '[{"id": "ing_cream", "quantity": {"value": 1.5, "unit": "carton of 250ml"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_potato", "quantity": {"value": 1.25, "unit": "bag of 2kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_cheese", "quantity": {"value": 2.5, "unit": "block of 250g"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["1 1/2 cups cream (, full fat (Note 1))","2 garlic cloves (, minced)","30g / 2 tbsp unsalted butter (, melted)","1.25 kg / 2.5 lb starchy potatoes (, Russet, Sebago, Maris Piper (Note 2))","1 tsp salt","1/4 tsp pepper","2 1/2 cups gruyere cheese (colby, cheddar, havarti or tasty), freshly grated yourself (Note 3)","2 tsp thyme leaves (, fresh (optional - but highly recommended))"]}]', '[{"title":"Cream Mixture","description":"Place butter, cream and garlic in a jug. Mix until combined.","images":[],"step":1},{"description":"Preheat oven to 180°C/350°F (both fan and standard ovens).","images":[],"step":2},{"title":"Slice potatoes","description":"Peel the potatoes and slice them 1/8\"/3 mm thick. Or use a slicer!","images":[],"step":3},{"title":"Layer 1","description":"Spread 1/3 of the potatoes in a baking dish (Note 3), then pour over 1/3 of the Cream Mixture, scatter with 1/3 of the salt, pepper and thyme. Sprinkle with 3/4 cups cheese.","images":[],"step":4},{"title":"Layers 2 & 3","description":"Repeat for the 2nd and third layer, but do not finish with cheese on the top layer (will add later).","images":[],"step":5},{"title":"Cover & bake","description":"Cover with lid or foil, and bake for 1 hour 15 minutes or until the potatoes in the middle are soft (use knife to test), it might take 1 1/2 hours. (Note 5)","images":[],"step":6},{"title":"Top with cheese, bake again","description":"Remove foil, top with cheese. Bake for a further 10 to 15 minutes until golden and bubbly. Stand 5 minutes before serving.","images":[],"step":7}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["French"],"categories":["all-vegetable-sides","dietary","easter-recipes","easter-sides-warm-hearty","gluten-free-recipes","most-popular","potato-recipes","potatoes","side-dishes","sunday-supper","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f2e127cf7ffd', 'en', 'US', 'Yotam Ottolenghi''s Cauliflower Salad', 'From his famous cookbook "Jerusalem", this salad is classic Ottolenghi: simple but a unique combination, and 100% yum. If you only try one cauliflower salad in your life, make it this one!Handy related recipes: How to cut cauliflower florets quickly & neatly, and Roasted Cauliflower.', 'https://www.recipetineats.com/tachyon/2014/06/Yotam-Ottolenghis-Cauliflower-Salad_Cover-photo.jpg', 10, 30, 40, 5, '[{"id": "ing_cauliflower", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_hazelnuts", "quantity": {"value": 50.0, "unit": "jar"}}, {"id": "ing_pomegranate", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.042, "unit": "jar of 40g"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.042, "unit": "jar of 40g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_maple_syrup", "quantity": {"value": 0.03, "unit": "bottle of 250ml"}}]', '[{"ingredients":["1 large cauliflower or 2 small","2 tbsp extra virgin olive oil","1/2 tsp each salt and pepper"],"purpose":"Roasted Cauliflower"},{"ingredients":["1 celery stalk (, cut into 0.5cm / 0.3\" slices on the diagonal)","1/3 cup hazelnuts (, raw, skin on)","1/2 pomegranate (, seeds only (~1/3 cup))","1 cup parsley leaves (, lightly packed)"],"purpose":"Salad:"},{"ingredients":["2 tbsp extra virgin olive oil","1/3 tsp cinnamon powder (Note 2)","1/3 tsp allspice (Note 2)","1 tbsp sherry vinegar","1 1/2 tsp maple syrup (or honey or golden syrup)","1/4 tsp each salt and pepper"],"purpose":"Dressing"}]', '[{"description":"Roast Cauliflower:","images":[],"step":1},{"description":"Preheat oven to 220°C/425°F (200°C fan).","images":[],"step":2},{"description":"Toss cauliflower with oil, salt and pepper. Spread on tray, roast 20 minutes, turn, then roast for a further 5 to 10 minutes until the edges are golden brown and the cauliflower is cooked through. Don''t let it get overcooked, sad and soggy!","images":[],"step":3},{"description":"Transfer to bowl and let cool for 20 minutes.","duration":20,"images":[],"step":4},{"description":"Toast Hazelnuts:","images":[],"step":5},{"description":"Turn oven down to 160°C/320°F (140°C fan). Spread hazelnuts on tray then roast for 5 minutes until they smell amazing.","duration":5,"images":[],"step":6},{"description":"Cool slightly, then roughly chop (most skin will naturally fall off).","images":[],"step":7},{"description":"Place hazelnuts, parsley and celery into the bowl. Sprinkle over cinnamon, allspice, salt and pepper. Drizzle with olive oil, maply syrup and vinegar. Toss gently with hands or rubber spatula.","images":[],"step":8},{"title":"Plate up","description":"Taste, add more salt or pepper if needed. Transfer to serving bowl. Scatter over pomegranates. Serve at room temperature.","images":[],"step":9}]', '[]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Middle Eastern"],"categories":["all-vegetable-sides","cauliflower","cuisines","easter-sides-fresh-light","holiday-salad-marathon","middle-eastern-recipes","quick-and-easy","side-salads","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5cf7169dba2a', 'en', 'US', 'Roasted Cauliflower', 'Recipe video above. The key to really good roasted cauliflower is a hot oven so you get tasty golden edges before the inside turns into overcooked mush!Parmesan and breadcrumbs is a sensational extra flavour variation that elevates it - the extra savoury boost plus little bits of crunchy bits is seriously good!Sauce options: Pile roasted cauliflower on plate and drizzle with Tahini Sauce or Lemon Yogurt Sauce.', 'https://www.recipetineats.com/tachyon/2020/12/Roasted-Cauliflower-cover.jpg', 5, 25, 30, 5, '[{"id": "ing_cauliflower", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 0.15, "unit": "pack of 200g"}}, {"id": "ing_bread", "quantity": {"value": 0.056, "unit": "loaf"}}]', '[{"ingredients":["1 large head cauliflower","2 1/2 tbsp olive oil","1/2 tsp each salt and pepper","2 garlic cloves (, finely minced)","1 tbsp parsley (, roughly chopped, for sprinkling (optional))"]},{"ingredients":["2 tbsp parmesan (, finely grated (store bought, sandy type))","3 tbsp panko breadcrumbs"],"purpose":"Parmesan Flavour Option:"}]', '[{"description":"Preheat oven to 220°C/425°F (200°C fan).","images":[],"step":1},{"description":"Toss cauliflower in a large bowl with oil, salt, pepper and garlic if using. (You can do this on the tray, but you''ll need more oil). Add parmesan and Panko breadcrumbs at this point, if using.","images":[],"step":2},{"description":"Spread on tray. Roast 20 minutes. Flip cauliflower, roast a further 5 minutes until you have golden edges and it''s soft all the way through.","images":[],"step":3},{"description":"Serve immediately, sprinkled with parsley if using.","images":[],"step":4}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["all-vegetable-sides","cauliflower","holiday-salad-marathon"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_aa9c18813ce0', 'en', 'US', 'How to cut cauliflower florets - efficiently, with least mess!', 'Don''t you hate how tiny little bits fly everywhere when you cut cauliflower??? No more! Here''s my quick and easy way to cut cauliflower.', 'https://www.recipetineats.com/tachyon/2020/12/Cauliflower-florets-square.jpg', 2, 0, 2, 4, '[{"id": "ing_cauliflower", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["1 cauliflower head - any size"]}]', '[{"description":"Cut whole cauliflower in half down the middle.","images":[],"step":1},{"description":"Then again to make 4 quarters.","images":[],"step":2},{"description":"Cut the core out on the diagonal.","images":[],"step":3},{"description":"Use your hands to break into florets.","images":[],"step":4},{"description":"If you end up with some large ones, use a knife to cut into half or even thirds so all the florets are roughly the same size - this will ensure they cook through evenly. Use as directed by recipe!","images":[],"step":5}]', '[]', '["gluten_free","keto_friendly","low_calorie","vegan","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Western"],"categories":["all-vegetable-sides","cauliflower","good-to-know","how-to"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_67a2df8a5dd8', 'en', 'US', 'Pea Puree', 'Basic recipes will call for just boiling peas then pureeing. The fine dining restaurant way is to saute garlic and eschalots in butter before adding peas and stock to simmer until soft, blitzing into a puree then pressing through a colander to make it silky smooth. It tastes luxurious!Wonderful side dish with any protein - meats, roasts, fish, prawns/shrimp - for both the splash of colour and the dual purpose it serves as a side dish as well as a semi-sauce. Nice change from the usual mash!', 'https://www.recipetineats.com/tachyon/2020/12/Pea-Puree-cover-photo.jpg', 10, 6, 16, 6, '[{"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_butter", "quantity": {"value": 125.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_eschalots", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_mint", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 kg / 2 lb frozen peas","125g / 8 tbsp butter (, unsalted)","2 garlic cloves, (minced)","2 medium eschalots (, finely sliced (ie the baby onions, aka French onions, US: shallots))","2 cups chicken or vegetable stock/broth (, low sodium (use vegetable stock if the puree is for fish))","1/4 tsp salt","1/8 tsp white pepper"]},{"ingredients":["1 small handfuls mint leaves (optional)"],"purpose":"Minted option:"}]', '[{"title":"Aromatics","description":"Melt butter in a saucepan over medium heat. Add garlic and eschalots, saute 3 minutes until soft, but don''t let them go golden.","images":[],"step":1},{"title":"Cook peas","description":"Add frozen peas and stock, increase heat to bring to simmer then cover and reduce heat to medium. Simmer 2 minutes.","images":[],"step":2},{"title":"Reserve Liquid","description":"Remove 1/3 cup liquid from the saucepan, reserve.","images":[],"step":3},{"title":"Blitz","description":"Transfer all peas and remaining liquid into a food processor. Add salt and pepper, and mint if using. Blitz on high for 1 minute until smooth.","duration":1,"images":[],"step":4},{"title":"Optional straining","description":"For extra smooth, press through a mesh colander with a rubber spatula (it''s easy).","images":[],"step":5},{"title":"Adjust consistency","description":"Use Reserved Liquid as needed to achieve the desired consistency - I like a soft, dolloping consistency. Sometimes people want it looser. Add more salt and pepper if desired - remember, this is not supposed to be strongly flavoured or seasoned!","images":[],"step":6},{"description":"Serve warm. Either dollop/smear onto plates, or serve in bowls for people to help themselves.","images":[],"step":7}]', '["fish","milk"]', '["gluten_free"]', '{"mealType":["main_course"],"cuisine":["French","Western"],"categories":["all-vegetable-sides","holiday-salad-marathon","peas","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c9cf4bbe12ea', 'en', 'US', 'French Bistro Salad', 'This is a classic French Leaf Salad you''ll find in bistros all across France, known for the use of lots of fresh herbs with a simple dressing. Light and clean, intended to be served alongside rich foods like Quiche Lorraine, Beef bourguignon and Coq au Vin that French food is known for. Though French, it will suit any Western food - and beyond!Use this recipe as more of a guide rather than exact recipe to be followed. Switch the leafy greens, use herbs you enjoy, crack open a jar of something pickled. Just make sure to use LOTS of fresh herbs!', 'https://www.recipetineats.com/tachyon/2020/12/French-Bistro-Salad-cover-photo.jpg', 10, 0, 10, 4, '[{"id": "ing_lettuce", "quantity": {"value": 0.5, "unit": "head"}}, {"id": "ing_lettuce", "quantity": {"value": 0.5, "unit": "head"}}, {"id": "ing_tarragon", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_chives", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_walnuts", "quantity": {"value": 75.0, "unit": "jar"}}, {"id": "ing_eschalots", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_vinegar", "quantity": {"value": 0.167, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.045, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.075, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["1/2 big head green oak or butter/bibb lettuce (about 8 big handfuls - but don''t crush the leaves to measure!)","1 baby cos/romaine lettuce","1/2 cup tarragon leaves","1/2 cup chives (, cut into 3cm / 1 1/2\" lengths)","3/4 cup parsley leaves","1/2 cup walnuts (, roughly chopped then toasted and cooled (optional, Note 1))"]},{"ingredients":["2 eschalots ((aka French onion, US: shallots), finely sliced)","2/3 cup red or white wine vinegar","4 tbsp white sugar"],"purpose":"Quick Pickled Eschalots:"},{"ingredients":["1.5 tbsp lemon juice","5 tbsp extra virgin olive oil","1/2 tsp each salt and pepper"],"purpose":"Dressing:"}]', '[{"title":"Quick Pickled Eschalots","description":"Stir sugar in vinegar until dissolved. Stir in eschalots, then leave for 30 minutes until it becomes floppy and turns pink. Drain.","duration":30,"images":[],"step":1},{"title":"Dressing","description":"Shake Dressing in a jar.","images":[],"step":2},{"title":"Assemble","description":"Pile lettuce on a platter (flatter better than deep bowl). Drizzle with about 1/2 the Dressing then toss gently with your hands. Scatter over fresh herbs, pickled eschalots and walnuts. Drizzle lightly with more Dressing. Serve immediately!","images":[],"step":3}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["lunch"],"cuisine":["French","Western"],"categories":["all-vegetable-sides","holiday-salad-marathon","leafy-greens","side-salads","vegan-lifestyle"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6e855c2eeac8', 'en', 'US', 'Tomato Salad with Olive Tapenade', 'This is a great tomato salad that makes the most of juicy ripe tomatoes when they''re in season! French influence with the use of black olive tapenade, the salty tang of the tapenade adds flavour interest while bringing out the sweetness in the juicy tomatoes. If you''ve got a jar of tapenade lying around, this will take minutes to prepare. Otherwise, it''s worth making your own - freshly made tapenade has real olive flavour unlike any you can buy in a jar!', 'https://www.recipetineats.com/tachyon/2020/12/Tomato-with-Olive-Tapenade_Cover-photo.jpg', 15, 0, 15, 4, '[{"id": "ing_tomato", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_kalamata_or_other_black_deli_olives", "quantity": {"value": 150.0, "unit": "bottle"}}, {"id": "ing_capers", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_fish_fillets", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_vinegar", "quantity": {"value": 0.001, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.068, "unit": "L"}}]', '[{"ingredients":["5 tomatoes (, medium sized, sliced into 1cm/ 0.2\" thick rounds)","1/4 tsp salt","1/2 cup flat leaf parsley leaves (, left whole or roughly torn)","Extra olive oil (, for drizzling)"],"purpose":"Tomato Salad:"},{"ingredients":["1 cup kalamata or other black deli olives (, preferably unpitted (Note 1))","2 tsp capers (, drained or rinsed (if packed in salt), chopped)","1 garlic clove (, medium, minced)","1 large or 2 small anchovy fillets ((Note 2), minced)","1/4 tsp red or white wine vinegar","4 - 5 tbsp extra virgin olive oil (, use your best stuff!)"],"purpose":"Tapenade:"}]', '[{"title":"Season tomatoes","description":"Place sliced tomatoes into a bowl. Sprinkle over the salt and toss well but gently. Leave to sit for 15 mins, then drain off any liquid the tomatoes have dropped. Meanwhile make the tapenade.","duration":15,"images":[],"step":1},{"description":"Pit olives if required. Combine olives, capers, garlic, anchovy and vinegar in a blender or food processor. Smaller is better, eg. a Nutribullet.","images":[],"step":2},{"description":"Add 4 tbsp of olive oil and blend until a rough paste forms, scraping down the sides as you go. If the paste is very thick and you are having trouble blending, add another 1 tbsp of olive oil to help it along.","images":[],"step":3},{"description":"You should have a nice paste that’s combined to a smooth but not super-fine puree (we want a little character), and isn’t excessively oily.","images":[],"step":4},{"description":"Drain your tomatoes one last time, then arrange slices overlapping on a large plate or platter. Dollop over the tomatoes 1/3 of the tapenade, or as much as you feel you want.","images":[],"step":5},{"description":"Garnish with parsley leaves. Drizzle salad with a little more olive oil (~1 tbsp). Serve with some remaining tapenade on the side so people can help themselves.","images":[],"step":6}]', '["fish"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["lunch"],"cuisine":["French","Western"],"categories":["all-vegetable-sides","holiday-salad-marathon","side-salads","tomato"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c50871c3926f', 'en', 'US', 'Roasted Asparagus', 'Recipe video above. Roasting is a terrific quick and easy way to prepare asparagus that''s so much tastier than steaming or blanching! You really only need salt, pepper and olive oil, but garlic always makes everything tastier. To make it company worthy, toss with a little lemon juice at the end, then grate over some parmesan. Serve with everything!', 'https://www.recipetineats.com/tachyon/2020/12/Roasted-Asparagus_9-cover-photo.jpg', 5, 7, 12, 3, '[{"id": "ing_asparagus", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.15, "unit": "pack of 200g"}}]', '[{"ingredients":["500g/1 lb asparagus (3 standard Australian bunches)","1 1/2 tbsp extra virgin olive oil","1/4 tsp each salt and pepper","1 garlic clove (, finely minced (knife or garlic press))"]},{"ingredients":["2 tbsp lemon juice","2 tbsp parmesan (, freshly grated)"],"purpose":"Optional finishes:"}]', '[{"description":"Preheat oven to 220°C/430°F (200°C fan).","images":[],"step":1},{"title":"Snap the woody ends off the asparagus","description":"it will naturally break at the right point.","images":[],"step":2},{"description":"Pile onto tray. Drizzle with oil, sprinkle with salt, pepper and garlic. Toss, then spread out on tray.","images":[],"step":3},{"description":"Roast 7 minutes, or until ends have a bit of colour on them and the asparagus is just cooked through. It will take 10 - 12 minutes for very thick ones. Don''t let them get wrinkly and sad!","images":[],"step":4},{"description":"Remove from oven.","images":[],"step":5},{"description":"Toss with lemon juice, if using. Pile onto serving platter, grate over optional parmesan. Serve!","images":[],"step":6}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Western"],"categories":["all-vegetable-sides","asparagus","holiday-salad-marathon","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6be434280d04', 'en', 'US', 'Vietnamese Chicken Salad', 'Recipe video above. Big, juicy, slaw-like salad with chicken, and singing with signature Vietnamese flavours: Lots of fresh herbs and a zingy Nuoc Cham salad dressing. I like cutting the chicken into thin batons so it sort of blends into the cabbage - and it makes less goes further!Don''t skimp on the herbs and peanuts here. It really brings added freshness and texture to the dish.This will serve 3 hungry adults or 4 normal servings (as a meal). Skip the chicken for a perfect Vietnamese side salad.', 'https://www.recipetineats.com/tachyon/2020/11/Vietnamese-Chicken-Salad_2.jpg', 15, 0, 15, 3, '[{"id": "ing_chicken", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_cabbage", "quantity": {"value": 6.0, "unit": "head"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_carrot", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_chilli", "quantity": {"value": 10.0, "unit": "pack of 100g"}}, {"id": "ing_mint", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_chilli", "quantity": {"value": 10.0, "unit": "pack of 100g"}}, {"id": "ing_peanuts_roasted", "quantity": {"value": 75.0, "unit": "jar"}}]', '[{"ingredients":["350g/12oz cooked chicken (, cut into thin batons (2 large cooked breasts, Note 1))","6 heaped cups wombok cabbage (Napa cabbage), finely shredded (Note 2)","1/2 red onion (, very finely sliced (so it''s floppy))","1 red capsicum / bell pepper (, finely sliced into thin batons)","2 cucumbers (, remove seeds then finely sliced into half moons (or 1 long continental/English cucumber))","1 large carrot (, peeled then julienned (I use a shredder))","1 large chilli (, deseeded then julienned, optional (Note 3))","1 cup (tightly packed) mint leaves ( , large leaves roughly torn by hand (Note 4))","1 cup (tightly packed) coriander/cilantro leaves (Note 4)"],"purpose":"Salad:"},{"ingredients":["2 tbsp lime juice","2 tbsp rice vinegar","1/4 cup fish sauce (sub light or all purpose soy sauce)","1/4 cup canola oil (or vegetable, grapeseed, peanut)","1 tbsp white sugar","1 large garlic clove (, very finely minced)","2 tsp red chilli (, deseeded then very finely minced (birds eye or Thai Red Chilli best, Note 3))"],"purpose":"Dressing:"},{"ingredients":["1/2 cup peanuts, roasted unsalted (, finely chopped (~1/3 cup once chopped, Note 5))"],"purpose":"Finishing:"}]', '[{"title":"Dressing","description":"Shake Dressing ingredients in a jar. Set aside 10 minutes to let flavours meld.","images":[],"step":1},{"title":"Toss","description":"Place all Salad ingredients in a very large bowl. Pour over half the Dressing and toss well. Set aside 5 minutes (veg will soften slightly, making it more \"slaw-like\").","images":[],"step":2},{"title":"Toss again","description":"Just before serving, toss again then add most of the remaining Dressing. Taste then add more Dressing if you want.","images":[],"step":3},{"description":"Serve sprinkled with lots of peanuts! (Note 6)","images":[],"step":4}]', '["fish","gluten","peanuts","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["lunch"],"cuisine":["Modern Vietnamese"],"categories":["all-vegetable-sides","asian-recipes","holiday-salad-marathon","modern-asian","no-cook-food","salad-recipes-main-course","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f872075b95d4', 'en', 'US', 'Spring Salad with Goats Cheese', 'A wonderful way to use seasonal spring vegetables to make an elegant salad that goes with just about everything! This salad combines asparagus, snow peas, peas, cos (romaine). We then add goats cheese for creamy and tangy pops to take it up another notch. You could easily substitute with feta (preferably soft Danish Feta) or if you prefer milder cheese, dollops of fresh mozzarella, bocconcini or fresh ricotta would work beautifully. Or leave the cheese out altogether if you''re being truly virtuous!', 'https://www.recipetineats.com/tachyon/2020/11/Spring-Salad-cover-photo.jpg', 10, 5, 15, 4, '[{"id": "ing_es_asparagus", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_snow_peas_trimmed_and_string_removed", "quantity": {"value": 120.0, "unit": "unit"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_frozen_peas", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_cheese", "quantity": {"value": 90.0, "unit": "block of 250g"}}, {"id": "ing_mint", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.09, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["3 bunches (24 spears) asparagus (, woody ends snapped off (Note 1))","120g / 4oz snow peas ((about 16 large or 20 smaller ones), trimmed and string removed)","1 head baby gem or cos lettuce (aka romaine) (washed (16 leaves, Note 2))","2 cups fresh or frozen peas (Note 3)","90g / 3oz goats cheese","1 cup (loosely packed) fresh mint leaves, (, roughly torn)"],"purpose":"Salad:"},{"ingredients":["1 tsp lemon zest (from 1 lemon)","2 tbsp (30ml) lemon juice","6 tbsp (90ml) extra virgin olive oil","1/4 tsp each salt and pepper"],"purpose":"Lemon Dressing:"}]', '[{"description":"Bring a large pot of water to the boil.","images":[],"step":1},{"description":"Add snow peas to pot, boil for 1 1/2 minutes.","images":[],"step":2},{"description":"Add the asparagus spears, boil for another 1 1/2 minutes.","images":[],"step":3},{"description":"Add frozen peas, and boil for another 30 seconds or until the water just returns to a simmer, and peas turn bright green.","images":[],"step":4},{"description":"Immediately drain, refresh vegetables under cold running water until cooled to stop cooking process.","images":[],"step":5},{"description":"Remove the asparagus and snow peas, blot with paper towels to dry. Leave peas in colander to drain, giving them a toss now and then to help them dry. (It''s important to dry vegetables, otherwise it dilutes the dressing and it won''t stick. You could use a salad spinner with care, o just let them naturally dry which is easier.)","images":[],"step":6},{"description":"Split the larger baby cos leaves down the middle, use the small ones whole.","images":[],"step":7},{"description":"Cut asparagus stems in half on a slight angle.","images":[],"step":8},{"description":"Shake Dressing ingredients in a jar.","images":[],"step":9},{"description":"Combine vegetables in a bowl, dress and toss.","images":[],"step":10},{"description":"Arrange salad on a platter (Note 5). Top with small chunks of goats cheese. Serve immediately!","images":[],"step":11}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Western"],"categories":["all-vegetable-sides","holiday-salad-marathon","leafy-greens","peas","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8e8983c16bf3', 'en', 'US', 'Spicy Joint''s Creamy Sesame Sauce with Lettuce Salad', 'A little salty, a little sweet, and packed with sesame flavour, this sauce - and it’s really more of a sauce than a dressing in consistency - punches well, well, well above its weight for such a short list of basic ingredients. One mouthful and you’ll be forever hooked! Drizzle over lettuce, as is traditional, or just use for dunking raw vegetables (I do this a LOT). This is a copycat of a side salad at some of our favourite Sydney Sichuan restaurants like Spicy Joint, and Chongqing Noodles.', 'https://www.recipetineats.com/tachyon/2020/11/Spicy-Joint-Creamy-Sesame-Sauce-with-Lettuce-Salad-Cover-photo.jpg', 5, 0, 5, 4, '[{"id": "ing_sesame_seeds", "quantity": {"value": 0.06, "unit": "pack of 100g"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.02, "unit": "jar of 375g"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.03, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.03, "unit": "pack of 100g"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.005, "unit": "bottle of 250ml"}}, {"id": "ing_water", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_lettuce", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["2 tbsp Chinese sesame paste (Note 1)","1/2 tbsp peanut butter (Note 2)","1/2 tsp white sugar","1/4 tsp salt","1/2 tbsp oyster sauce (Note 3)","1 tbsp sesame oil (, toasted (ie brown, not yellow))","1/4 tsp dark soy sauce (Note 4)","3-4 tbsp water (or more)"],"purpose":"Creamy Sesame Sauce:"},{"ingredients":["2 baby cos lettuce or for authentic, equivalent amount of Chinese lettuce (celtuce) (, trimmed (Note 5 for subs))","sesame seeds for garnish (black, ideally for the colour, but white or roasted are fine)"],"purpose":"Lettuce Salad:"}]', '[{"description":"Separate, wash, trim and dry lettuce leaves. Slice any large ones in half vertically. Leave smaller leaves whole.","images":[],"step":1},{"title":"Sauce","description":"Mix all ingredients except water together in a bowl. Start by mixing in 3 tbsp water, a tablespoon at a time. Let the sauce sit for one minute. If the sauce starts to split, or the sauce is too thick, add another tablespoon of water. Keep doing this until you have a pourable / drizzle-able sauce that is emulsified (ie. oil is not separated).","images":[],"step":2},{"description":"Arrange leaves on platter, drizzle around half of the dressing over or so. You will NOT need all the dressing; keep the rest for something else. Garnish with sesame seeds. (Alternative: just use to dip in raw veg. It is SO good!)","images":[],"step":3}]', '["gluten","peanuts","sesame","soy"]', '["low_calorie","vegan","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Chinese","Sichuan"],"categories":["all-vegetable-sides","asian-recipes","chinese-recipes","dressings","holiday-salad-marathon","leafy-greens","modern-asian","salad-dressings","side-salads","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0fd071acb095', 'en', 'US', 'Baby Potatoes with Butter & Fresh Herbs', 'This is a wonderful, elegant potato side dish that''s not too rich so it''s ideal to serve with rich mains like roasts, and light enough to serve with more delicate foods such as seafood (fish, prawns/shrimp, lobster, crab, mixed seafood platter!).It''s a classic side dish you will see offered at fine dining restaurants as a less heavy potato side compared to things like Paris Mash (the world''s richest mashed potatoes!).', 'https://www.recipetineats.com/tachyon/2020/11/Baby-potatoes-with-butter-and-herbs-cover-photo-7.jpg', 5, 15, 20, 5, '[{"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_dill", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_chives", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["1kg/ 2 lb baby potatoes / new potatoes (, about 3cm/1.2\" round ideal (look for same size ones))","1 tbsp salt (, for cooking (Note 1))","30g/ 2 tbsp unsalted butter (no need to melt)","1/2 tsp each salt and pepper"]},{"ingredients":["2 tbsp fresh dill (, finely chopped)","1 tbsp chives (, finely chopped)","1 tbsp parsley (, finely chopped)"],"purpose":"Fresh Herbs:"}]', '[{"title":"Boil potatoes","description":"Place potatoes in a large pot of cold tap water with 1 tbsp salt. Bring to a boil over high heat, then lower heat to medium so they''re simmering gently (this stops skin splitting). Cook for 10 - 15 minutes until there''s no resistance when pierced with a knife. Alternatively, steam the potatoes.","duration":12.5,"images":[],"step":1},{"title":"Steam dry","description":"Drain in colander then leave for a minute to let the potatoes steam dry (if wet, butter won''t stick).","images":[],"step":2},{"title":"Toss with butter","description":"Transfer to a bowl, add salt, pepper and butter. Toss to melt and coat.","images":[],"step":3},{"description":"Add herbs just before serving. Stir through, transfer to serving bowl and serve warm!","images":[],"step":4}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["all-vegetable-sides","holiday-salad-marathon","potato-recipes","potatoes","side-dishes","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1e18911c7447', 'en', 'US', 'Peach Salad', 'This is a classic Peach Salad, simple as it is supposed to be, intended to make the most of juicy sweet peaches when they are in season! It''s a magical summer salad combination - sweet peaches, salty prosciutto, creamy buffalo mozzarella and the pepper rocket/arugula.Make sure all ingredients are at room temperature for the best eating experience.', 'https://www.recipetineats.com/tachyon/2020/11/Peach-Salad-Cover-Thumbnail.jpg', 10, 0, 10, 4, '[{"id": "ing_peaches", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_loosely_packed_rocket_arugula", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.2, "unit": "pack of 125g"}}, {"id": "ing_prosciutto", "quantity": {"value": 0.16, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.045, "unit": "net of 500g"}}, {"id": "ing_mustard", "quantity": {"value": 0.037, "unit": "jar of 200g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.068, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["3 small peaches or 2 large peaches","4 cups loosely packed rocket/arugula","150g/5oz ball buffalo or cow’s milk mozzarella (1 ball, ok it slightly less or more)","4 slices prosciutto (or jamon serrano, about 70g/2.5 oz; for other subs see Note 1)"],"purpose":"Salad:"},{"ingredients":["1 1/2 tbsp fresh lemon juice","1 1/2 tsp Dijon mustard","4 1/2 tbsp extra virgin olive oil","1/4 tsp each salt and pepper"],"purpose":"Dressing:"}]', '[{"title":"Cut peach","description":"Halve peaches. Remove seed. Cut each half into half again. If your peaches are really large, cut each half into thirds.","images":[],"step":1},{"title":"Dressing","description":"Combined dressing ingredients in a jar and shake well.","images":[],"step":2},{"description":"Toss rocket in ~2 tbsp of dressing.","images":[],"step":3},{"title":"Mozzarella","description":"Tear mozzarella into pieces.","images":[],"step":4},{"title":"Assemble","description":"Arrange rocket, peaches, mozzarella on a large plate or platter. Drape prosciutto around salad. Drizzle remaining oil over the salad. Serve!","images":[],"step":5}]', '["milk","mustard"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["lunch"],"cuisine":["Italian"],"categories":["all-vegetable-sides","holiday-salad-marathon","italian-recipes","peach-recipes","rocket-arugula","side-salads","with-fruits"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_79228e3a9a1e', 'en', 'US', 'Chang''s Crispy Noodle Salad', 'This back-of-packet salad from the packet of Chang''s Crispy Noodles is an Aussie staple! I''ve tweaked the dressing slightly to make it less oily and reduce the sugar, and it''s still just as good in my opinion.Serve with everything - it might have Asian roots, but it appears at every backyard BBQ alongside snags, steaks and kebabs!', 'https://www.recipetineats.com/tachyon/2020/11/Changs-Crispy-Noodle-Cabbage-Salad_Countdown.jpg', 10, 0, 10, 5, '[{"id": "ing_cabbage", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.2, "unit": "pack of 500g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_almonds", "quantity": {"value": 0.4, "unit": "pack of 250g"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.075, "unit": "L"}}]', '[{"ingredients":["1 Chinese cabbage (wombok), or 1/2 a giant one (Note 1)","100g/ 3.5oz Chang''s crispy noodles (store bought, the fine ones not chunky ones, Note 2)","5 green onions (, finely sliced on the diagonal)","100g/ 3.5oz slivered almonds"]},{"ingredients":["4 tbsp white vinegar (just ordinary vinegar, nothing fancy!)","2 tbsp white sugar (or brown)","2 tbsp soy sauce (, all purpose or light, NOT dark soy sauce)","2 tsp sesame oil (, toasted (brown, not yellow untoasted))","5 tbsp olive oil"],"purpose":"Dressing:"}]', '[{"title":"Toast almonds","description":"Lightly toast the slivered almonds in a small skillet over medium heat until lightly browned (no oil). Remove immediately and let cool.","images":[],"step":1},{"title":"Dressing","description":"Shake Dressing ingredients in a jar until sugar is dissolved. (This keeps for 3 weeks!)","images":[],"step":2},{"title":"Shred cabbage","description":"Cut cabbage (see photos in post, helpful): cut 1 slit down the middle lengthwise (or 2, if it''s giant like the one I used). Then finely slice so it''s shredded. Just use the top 1/2 - 2/3, mostly leafy part. Reserve the thick crunchy white part for another use (excellent in stir fries!).","images":[],"step":3},{"title":"Toss everything except crispy noodles","description":"Place cabbage in a big bowl with toasted almonds and green onions. Pour over Dressing, toss well.","images":[],"step":4},{"description":"Add crispy noodles! Toss through noodles just before serving so they stay crisp!","images":[],"step":5}]', '["gluten","sesame","soy"]', '["vegan","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Asian-esque","Western"],"categories":["all-vegetable-sides","asian-recipes","cabbage","holiday-salad-marathon","modern-asian","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_92a516dbbe0d', 'en', 'US', 'Leftover Celery Salad', 'This is a really handy and quick recipe to use up leftover celery that we all seem to have in our fridge! It''s a bit tart because it''s semi pickled, sort of salsa-like and and intriguingly tasty, thanks to the surprising combination of caraway seeds and dill. If you don''t have either of these, you can even skip the fresh herbs altogether - see notes for alternative suggestions. Serve as a side salad, or as a little dish of pickles to accompany a meal.', 'https://www.recipetineats.com/tachyon/2020/11/Celery-Salad_6-SQ-countdown.jpg', 10, 0, 10, 3, '[{"id": "ing_beef_steak", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_dill", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_caraway_seeds", "quantity": {"value": 7.5, "unit": "jar"}}, {"id": "ing_vinegar", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["5 ribs celery","3 tbsp dill (, finely chopped)","2 tbsp parsley (, finely chopped)","1.5 tsp caraway seeds","2 1/2 tbsp white wine vinegar (, red wine vinegar or cider vinegar)","3 tbsp extra virgin olive oil","2 tsp sugar","1/2 tsp salt","1/4 tsp black pepper"]}]', '[{"description":"Remove the leaves from the celery and trim off the dirty base. Finely slice on the diagonal into 4mm / 1/6\" slices.","images":[],"step":1},{"description":"Toss in a bowl with remaining ingredients. Set aside for 10 minutes before serving.","duration":10,"images":[],"step":2},{"title":"Keeps for up to 3 days in the fridge","description":"the celery softens and becomes even more pickle like.","images":[],"step":3}]', '[]', '["gluten_free","keto_friendly","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["all-vegetable-sides","celery","good-to-know","holiday-salad-marathon","quick-and-easy","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ea7b9bd406da', 'en', 'US', 'New York Times Famous Broccoli Salad - with Cumin, Garlic and Sesame', 'Recipe video above. This is a wildly popular raw Broccoli Salad by Melissa Clark of the New York Times. The red wine vinegar lightly "cooks" the broccoli so it''s not as hard as plain raw broccoli, then it''s marinated in an intensely flavoured cumin, garlic and sesame infused olive oil. It is unexpectedly good, it''s unique, and I keep making it so I wanted to share the recipe.Not a fan of raw broccoli? This probably isn''t the dish to convert you, I''ll admit. Try instead just lightly steaming the broccoli - it''s really worth making just for the dressing!', 'https://www.recipetineats.com/tachyon/2020/11/Broccoli-Cumin-Garlic-Salad_SQ-countdown.jpg', 10, 1, 11, 4, '[{"id": "ing_broccoli", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_vinegar", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["500g/1lb broccoli florets (, large florets halved or cut into thirds (3 medium or 2 large broccoli heads, 1kg/2lb in total))","1 tbsp red wine vinegar (or white wine vinegar, sherry vinegar, cider vinegar)","3/4 tsp salt, cooking/kosher ( (if table salt: 1/2 tsp))","1/4 tsp black pepper","1/3 cup extra virgin olive oil","4 garlic cloves (, finely minced using knife (not crusher))","2 tsp cumin seeds (whole, not powder)","2 tsp sesame oil (, roasted (Note 1))","1/4 tsp red pepper flakes / chilli fakes (optional)"]}]', '[{"title":"\"Cook\" raw broccoli","description":"Toss broccoli in red wine vinegar, salt and pepper. Set aside 10 minutes - it will lightly pickle, almost \"ceviche\" the broccoli.","images":[],"step":1},{"title":"Garlic, spice and oil mix","description":"Heat olive oil in a small skillet over medium heat. Add garlic, cumin seeds and red pepper flakes. Cook, stirring, until garlic is light golden. Stir in sesame oil.","images":[],"step":2},{"title":"Toss broccoli","description":"Immediately pour oil mix over broccoli. Toss very well using a rubber spatula to scrape up all the oil from the side of the bowl.","images":[],"step":3},{"title":"Marinate","description":"Leave on the counter for at least 1 hour to marinate, or refrigerate for up to 48 hrs (it gets better with time).","images":[],"step":4},{"description":"Serve at room temp, not cold, for best flavour!","images":[],"step":5}]', '["sesame"]', '["gluten_free","keto_friendly","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["all-vegetable-sides","broccoli","broccoli-recipes","holiday-salad-marathon","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9e8f09d9ff5a', 'en', 'US', 'Bitter Leaf and Orange Salad with Orange Poppyseed Dressing', 'This is a classic salad pairing you often see at fine dining restaurants and up market bistros. The slightly bitter edge of the leafy greens combined with the sweet juicy orange slices acts as a palette cleanser for rich mains such as roasts, and it looks bright and festive on the table.Paired here with a fabulous Orange Poppyseed Dressing to drive home the citrus flavour, but it looks great when you see the little poppyseeds on the orange slices!', 'https://www.recipetineats.com/tachyon/2020/11/Bitter-Leaf-and-Orange-Salad-with-Orange-Poppyseed-Dressing_SQ-countdown.jpg', 10, 0, 10, 4, '[{"id": "ing_bitter_leaves", "quantity": {"value": 200.0, "unit": "unit"}}, {"id": "ing_oranges", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.075, "unit": "L"}}, {"id": "ing_oranges", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_sugar", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_poppy_seeds", "quantity": {"value": 15.0, "unit": "jar"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["200g / 6 oz bitter leaves (~8 cups, packed) (, such as endive, chicory and radicchio (either a mix or one kind, Note 1))","2 large oranges (any kind)"],"purpose":"Salad:"},{"ingredients":["2 tbsp apple cider or white wine vinegar","5 tbsp extra virgin olive oil or a nut oil","1 tsp grated orange zest (, lightly packed)","2 tsp Dijon mustard","1/4 tsp sugar","1 tbsp poppy seeds","1/2 tsp each salt and pepper"],"purpose":"Orange and poppy seed dressing:"}]', '[{"description":"Put leaves into a large mixing bowl. Tear or cut any large leaves into smaller bite size pieces.","images":[],"step":1},{"description":"Peel oranges and remove skin and all outer pith (white part) using a knife.","images":[],"step":2},{"description":"Slice into 0.7 cm / 1/3\" thick wheels and deseed. Alternatively, segment oranges. Add to leaves.","images":[],"step":3},{"description":"Mix or shake Dressing ingredients in a jar until sugar dissolves.","images":[],"step":4},{"description":"Dress salad and toss.","images":[],"step":5}]', '["mustard"]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Western"],"categories":["all-vegetable-sides","holiday-salad-marathon","leafy-greens","quick-and-easy","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2bac993ff75a', 'en', 'US', 'Pomegranate Salad - with Spinach, Kale, Honey Walnuts & Pomegranate Dressing', 'Recipe video above. Fabulously festive to look at, and scrumptious to eat! Crunchy Honey Walnuts add texture, while creamy blue cheese brings tangy umami to this party. And as for raw kale haters? Don''t despair! This kale is MARINATED to tenderise and temper the kale flavour.As for the pomegranates - use pre-seeded if you must, but there''s something so satisfying about smacking them out yourself! .... Oh, and it''s juicier and fresher too! ;)BONUS: Keeps pretty well even once dressed. SERVES: 3 as a filling lunch, 8-10 as a side salad.', 'https://www.recipetineats.com/tachyon/2020/11/Pomegranate-Salad-Kale-Spinach_6-SQ-countdown.jpg', 15, 15, 30, 8, '[{"id": "ing_kale", "quantity": {"value": 5.0, "unit": "unit"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_pomegranate", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_baby_spinach", "quantity": {"value": 8.0, "unit": "bag of 250g"}}, {"id": "ing_cheese", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_cranberries", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_oranges", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_walnuts", "quantity": {"value": 225.0, "unit": "jar"}}, {"id": "ing_maple_syrup", "quantity": {"value": 0.25, "unit": "bottle of 250ml"}}, {"id": "ing_cinnamon", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_pomegranate_molasses", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_vinegar", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["5 kale stems (big and leafy, sub baby rocket/arugula but skip marinating)","1 tsp extra virgin olive oil","Pinch of salt and pepper"],"purpose":"Marinated kale (tenderised for tastiness, Note 1):"},{"ingredients":["1 pomegranate (, big, juicy (or 1 cup pomegranate arils, Note 2))","8 cups (120g/4.5oz) baby spinach (or baby rocket/arugula)","100g/3.5 oz blue cheese (, crumbled yourself (Note 3))","1/2 cup dried cranberries (or raisins, craisins)","2 blood oranges (, normal oranges, yellow peach, nectarine or grapefruit (optional, for extra colour/juicy/interest))"],"purpose":"Salad:"},{"ingredients":["1 1/2 cup walnuts or pecans","1/4 cup honey ((runny, so warm if super thick), or maple syrup)","1/2 tsp cinnamon","1/8 tsp salt"],"purpose":"Honey Cinnamon Walnuts:"},{"ingredients":["2 tbsp pomegranate molasses (Note 4)","1 1/2 tbsp red wine vinegar (or white wine vinegar or cider vinegar)","4 tbsp extra virgin olive oil","1/2 tsp each salt and pepper"],"purpose":"Pomegranate Dressing:"}]', '[{"description":"Marinated Kale:","images":[],"step":1},{"title":"Remove leaves","description":"Grab the base of the stalk then run your fist up the stalk to remove the leaves.","images":[],"step":2},{"title":"Slice","description":"bundle the kale leaves on a chopping board, then slice 0.5 cm / 1/5\" thick.","images":[],"step":3},{"title":"Scrunch","description":"Place in bowl, drizzle with olive oil, sprinkle with salt and pepper. Use your hands to scrunch in order to soften leaves and coat everything with the oil. Do this for 20 seconds. Leave for 30 minutes to marinate - leaves will soften. Try it - much tastier than plain raw!","duration":0.3333333333333333,"images":[],"step":4},{"title":"Toss","description":"Place walnuts in a bowl, drizzle with honey, sprinkle with cinnamon and salt. Mix, spread on paper lined baking tray.","images":[],"step":5},{"title":"Bake","description":"Bake at 180°C/350°F (160°C fan) for 15 minutes, tossing once halfway. Leave to cool, then use fingers to roughly break walnuts up into slightly smaller pieces.","duration":15,"images":[],"step":6},{"description":"Pomegranate Dressing:","images":[],"step":7},{"description":"Place ingredients in a jar and shake very well, being sure that there is no molasses left on the bottom of the jar. (Shake in jar is better than whisking to bring this dressing together).","images":[],"step":8},{"description":"Remove Pomegranate Seeds:","images":[],"step":9},{"description":"Cut pomegranate in half. Over a bowl, turn cut face downwards, then use a wooden spoon to (very!) firmly smack the back of the pomegranate. The seeds will fly out through your fingers into the bowl. It''s very satisfying!!!","images":[],"step":10},{"description":"Keep smacking all over the skin until the seeds are all out. Pick out any white pith that fell out, then use seeds per recipe. You will probably get some juices pooling in the bowl; add this to the dressing too.","images":[],"step":11},{"description":"Slice fruit (if using):","images":[],"step":12},{"title":"Peaches, nectarines","description":"Halve, remove stone, then cut into 4mm / 1/6\" slices.","images":[],"step":13},{"title":"Grapefruit, oranges","description":"Cut off peel and pith, then segment (see this video at 41 sec for demo)","images":[],"step":14},{"title":"Dress greens lightly","description":"Place kale and spinach leaves in a giant bowl. Drizzle with about 3 tablespoons of Dressing then toss very well.","images":[],"step":15},{"title":"Layer half","description":"Pour half kale/spinach into a large serving bowl. Sprinkle with 1/3 EACH of walnuts, blue cheese (crumbled), pomegranates, orange segments, and cranberries.","images":[],"step":16},{"title":"Presentation layer","description":"Top with remaining kale & spinach, then remaining walnuts, blue cheese, pomegranates, orange segments and cranberries. Drizzle over remaining dressing just before serving.","images":[],"step":17},{"title":"Serving","description":"Best served freshly assembled but this salad will hold up much better than most because kale doesn''t go as soggy once dressing, it''s even good the next day!","images":[],"step":18}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Western"],"categories":["all-vegetable-sides","holiday-salad-marathon","leafy-greens","salad-recipes-main-course","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_815bc2b37fa3', 'en', 'US', 'Brussels Sprouts in Creamy Carbonara Sauce - with bacon!', 'Recipe video above. This is like Brussels Sprouts cooked gratin-style, except easier and faster because it''s all made in one skillet on the stove! The idea with this recipe is to get a load of flavour into the brussels sprouts by firstly sautéing in bacon fat and garlic, then simmering in a creamy carbonara-esque sauce to finish cooking them through.I love how the brussels sprouts acts like a sponge for the sauce, so that when you bite into them the creamy sauce squirts out into your mouth!', 'https://www.recipetineats.com/tachyon/2020/11/Creamy-Brussels-Sprouts_6.jpg', 10, 15, 25, 6, '[{"id": "ing_bacon", "quantity": {"value": 0.75, "unit": "pack of 200g"}}, {"id": "ing_brussels_sprouts", "quantity": {"value": 750.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.4, "unit": "pack of 125g"}}]', '[{"ingredients":["150g/ 5oz bacon (, chopped (use streaky, not lean))","750g/1 1/2 lb brussels sprouts (Note 1)","1/4 tsp salt","1/2 tsp black pepper","2 garlic cloves (, finely minced)","1/2 cup chicken or vegetable stock / broth (, low sodium (Note 2))","1 cup cream (, heavy/thickened (Note 3))","1/2 cup parmesan (, finely grated (best to grate your own))","1/2 cup shredded mozzarella (or any other melting cheese)"]}]', '[{"title":"Prepare brussels sprouts","description":"Trim the woody end off, halve, then remove scraggly and loose outer layers.","images":[],"step":1},{"title":"Cook bacon","description":"Place bacon in cold non stick skillet, then turn the stove on medium high (Note 4). Cook bacon for 2 to 3 minutes until golden, then remove with a slotted spoon.","duration":2.5,"images":[],"step":2},{"title":"Reserve some fat","description":"Discard excess bacon fat, leaving behind 2 tablespoons (or so). If you''re short, add a dab of butter or olive oil.","images":[],"step":3},{"title":"Sauté brussels","description":"Add brussels sprouts and cook for 3 minutes, stirring every now and then, until the cut face becomes light golden.","duration":3,"images":[],"step":4},{"description":"Add garlic, salt and pepper, then keep sautéing for another 1 minute or until the cut face become golden.","images":[],"step":5},{"title":"Braise in stock","description":"Add chicken stock then lower heat to medium and simmer for 4 - 5 minutes, stirring every now and then to encourage even cooking, until the brussels are almost cooked through (check with a knife). Don''t let them cook through completely - we will be simmering a little more.","duration":4.5,"images":[],"step":6},{"description":"Add cream and stir. Simmer for 2 minutes to reduce.","duration":2,"images":[],"step":7},{"description":"Add parmesan and cheese. Stir until melted, then simmer for a further 1 minute to to let the sauce thicken more and for the brussels sprouts to finish cooking through. (Note 5 on sauce thickness)","images":[],"step":8},{"title":"Check for salt","description":"Taste and add more salt if needed (I usually find it doesn''t need any more.)","images":[],"step":9},{"title":"Sprinkle with bacon","description":"Transfer to serving bowl, sprinkle with cooked bacon and serve hot!","images":[],"step":10}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["all-vegetable-sides","brussels-sprouts","side-dishes","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_806ce1163186', 'en', 'US', 'Fondant Slow-Roasted Sweet Potatoes - with Maple Butter Pecans', 'Recipe video above. The familiar sweetness of sweet potato gets a boost of savoury by cooking them fondant style: Roasting in stock, long and slow, so the inside turns meltingly creamy and the outsides caramelise. And if that''s not enough (and it really is - you can serve it just like that) you''ve got the option to douse with a Maple Butter Pecan Sauce which elevates it to "wow"!Is it sweet? Yes. But it''s counter-balanced by the infusion of savoury in the potato flesh and the nuts. If you prefer some tartness instead, use the Honey Lemon Sauce in this sweet potato salad recipe instead (switch honey with maple!)', 'https://www.recipetineats.com/tachyon/2020/10/Fondant-Sweet-Potatoes-with-maple-butter-sauce_4.jpg', 5, 60, 65, 6, '[{"id": "ing_sweet_potato", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 25.0, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_maple_syrup", "quantity": {"value": 0.5, "unit": "bottle of 250ml"}}, {"id": "ing_butter", "quantity": {"value": 25.0, "unit": "block of 250g"}}, {"id": "ing_pecans", "quantity": {"value": 0.333, "unit": "unit"}}, {"id": "ing_cinnamon", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.15, "unit": "bunch"}}]', '[{"ingredients":["1.5 kg / 3 lb sweet potatoes - 3 thick ones (Note 1)","25g/ 1 1/2 tbsp butter (, unsalted, melted (Note 2))","1 1/2 tbsp olive oil (Note 2)","3/4 tsp salt (, kosher/cooking (1/2 tsp table salt))","1/2 tsp black pepper","1 1/4 cups chicken stock (, low sodium (or vegetable stock))","1 garlic clove (, finely minced)"],"purpose":"Fondant Potatoes:"},{"ingredients":["1/2 cup maple syrup (pure, Note 3)","30g/ 2 tbsp butter (, unsalted)","1/3 cup pecans (, chopped (Note 4))","1/2 tsp cinnamon","Pinch of salt"],"purpose":"Maple Butter Pecan Sauce (optional / not really!):"},{"ingredients":["1 1/2 tsp fresh thyme leaves (highly recommended)"],"purpose":"Serving"}]', '[{"description":"Fondant Potatoes:","images":[],"step":1},{"description":"Preheat oven to 240°C/465°F (220°C fan).","images":[],"step":2},{"description":"Cut the potatoes into 3cm / 1.2\" discs.","images":[],"step":3},{"description":"Place the potatoes in a large roasting pan or baking sheet with tallish sides (we''re adding liquid later).","images":[],"step":4},{"description":"Drizzle with butter and oil, sprinkle with half the salt and pepper. Squidge around, turn potatoes, sprinkle with remaining salt and pepper.","images":[],"step":5},{"title":"Roast","description":"Place in the oven and roast for 20 minutes.","duration":20,"images":[],"step":6},{"title":"Turn, continue roasting","description":"Carefully turn potatoes, then roast for a further 15 minutes.","images":[],"step":7},{"title":"Baste, add stock","description":"Spoon the butter/oil collecting in the pan over the potatoes. Then carefully pour the stock in around the potatoes, and scatter the garlic into the liquid.","images":[],"step":8},{"title":"Roast to absorb stock","description":"Return to the oven, and roast for a further 15 to 20 minutes or until most of the liquid has been absorbed/evaporated. The exact time depends on the height of pan walls / how heavy-based your pan is etc.","images":[],"step":9},{"title":"Assemble & serve","description":"Transfer potatoes to serving platter, scraping up some of the pan juices as you go (Note 5), and piling them high on the plate. Pour over Maple Butter Pecan Sauce and sprinkle with fresh thyme leaves just before serving. Serve warm - or at room temperature!","images":[],"step":10},{"description":"Maple Butter Pecan Sauce:","images":[],"step":11},{"description":"Place pecans in a saucepan or small skillet over medium high heat. Stir for 30 seconds until you can smell the pecans. Add remaining ingredients, then once the butter melts and it starts bubbling, simmer on medium heat for 1 1/2 minutes until it reduces and thickens slightly (it gets thicker as it cools).","duration":0.5,"images":[],"step":12},{"description":"Transfer to serving jug. Serve over potatoes.","images":[],"step":13}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Western","Western - Holiday Sides"],"categories":["all-vegetable-sides","potato-recipes","side-salads","slow-cooked-fall-apart","sweet-potato"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d235e1fda485', 'en', 'US', 'Roasted Pumpkin with Lemon Yogurt Sauce and Pine Nuts', 'Recipe video above. This is a great way to use pumpkin that ticks a lot of boxes - it''s simple to make, works just as well as a side for a grand roast, or as part of a salad lunch spread, can easily to altered to fit various cuisines and occasions by changing the nuts and fresh herb, and it looks rustic and good with zero effort!Excellent served hot, warm or even at room temperature.', 'https://www.recipetineats.com/tachyon/2020/10/Roasted-Pumpkin-with-Yogurt-Sauce_2-SQ.jpg', 10, 30, 40, 4, '[{"id": "ing_pumpkin", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.225, "unit": "tub of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_pine_nuts", "quantity": {"value": 0.3, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_sumac", "quantity": {"value": 0.625, "unit": "jar"}}]', '[{"ingredients":["1.2kg / 2.4 lb pumpkin (, skin on seeds in weight (or butternut squash or sweet potato, Note 1))","2 tbsp extra virgin olive oil","1 garlic clove (, finely minced using garlic press)","1/2 tsp each salt and pepper"],"purpose":"Roasted Pumpkin:"},{"ingredients":["3/4 cup Greek yogurt (or other plain, non sweet yogurt)","1/2 small garlic clove (, finely minced using garlic press)","1 tbsp lemon juice","1 tbsp extra virgin olive oil","1/4 tsp each salt and pepper"],"purpose":"Lemon Yogurt Sauce:"},{"ingredients":["2 tbsp pine nuts (or other nuts of choice)","2 tbsp fresh coriander/cilantro leaves (, roughly chopped (or parsley))","1/8 tsp sumac (paprika or other theme appropriate spice, Note 2)"],"purpose":"Sprinkling and garnishes:"}]', '[{"description":"Roasted Pumpkin:","images":[],"step":1},{"description":"Preheat oven to 220°C/430°F (200°C fan). Line a tray with baking/parchment paper.","images":[],"step":2},{"description":"Peel, deseed and cut pumpkin into 3cm / 1.2\" cubes - see photos in post for how I do it with little effort. You should end up with about 1 kg - enough to fill a tray.","images":[],"step":3},{"description":"Place pumpkin in a bowl, add garlic, salt, pepper and olive oil. Toss well using a rubber spatula.","images":[],"step":4},{"description":"Spread on tray. Roast 20 minutes. Turn pumpkin pieces, then roast a further 7 to 10 minutes until nicely coloured but holding it''s shape, rather than being a mushy mess.","images":[],"step":5},{"description":"Lemon Yogurt Sauce:","images":[],"step":6},{"description":"Mix ingredients then set aside for at least 10 minutes to let the flavours develop.","images":[],"step":7},{"description":"Preheat skillet over medium high heat (no oil). Add pine nuts and cook, stirring regularly, until it smells amazing and it''s got a hint of browning on both sides. Remove from pan.","images":[],"step":8},{"description":"Pile the pumpkin in a mound on a plate. Drizzle over yogurt sauce, add a little drizzle of olive oil, then sprinkle with sumac, pine nuts and coriander.","images":[],"step":9},{"description":"I think it''s best served with the pumpkin hot or warm, but for a warm summer day, it is also excellent served at room temperature. Just cool pumpkin, then dress and garnish just before serving.","images":[],"step":10}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Middle Eastern","Western"],"categories":["all-vegetable-sides","cuisines","middle-eastern-recipes","pumpkin","pumpkin-squash","quick-and-easy","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_31d50d263f25', 'en', 'US', 'Crispy Potato Rosti', 'Recipe video above. This is a recipe for truly crispy Potato Rosti that''s beautifully golden on the outside and fluffy on the inside. The secret is pan frying in the right fat! Butter = tasty but not crispy. Oil = crispy but flavourless. The Swiss cracked the code - use clarified butter (or ghee!). Buy it or make your own (it''s super easy).And if you want ultra ultra crispy, make small thin ones instead - they are literally potato crisp crispy!This recipe would probably serve 6 normal people, but in my family it serves 4. Makes 1 giant rosti about 2cm / 4/5" thick, or 10 - 12 small rostis.', 'https://www.recipetineats.com/tachyon/2020/10/Potato-Rosti_2.jpg', 10, 25, 35, 4, '[{"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 15.0, "unit": "block of 250g"}}, {"id": "ing_butter", "quantity": {"value": 15.0, "unit": "block of 250g"}}]', '[{"ingredients":["1kg/ 2 lb potatoes (skin on weight) ( - Aus: Sebago (dirt brushed), US: Yukon Gold, Russet, UK: Maris Piper, King Edwards (Note 1))","3/4 tsp salt (, kosher/cooking salt (or 1/2 tsp table salt))","1/2 tsp finely ground black pepper","15g/ 1 tbsp clarified butter / ghee or normal butter (, melted (Note 2))"]},{"ingredients":["60g/ 4 tbsp clarified butter / ghee (, separated (sub half butter, half vegetable oil) (Note 2))"],"purpose":"Cooking:"}]', '[{"description":"Grate & squeeze:","images":[],"step":1},{"description":"Peel then grate the potatoes using a box grater, trying to get nice long strands if you can.","images":[],"step":2},{"description":"Grab handfuls of potato and squeeze out excess liquid, then place in bowl. This helps make the potato crispier (otherwise all that water has to steam out in the pan).","images":[],"step":3},{"description":"Add butter, salt and pepper then toss. Don''t worry if your potatoes go brown/reddy - it''s still safe to eat, and turns white again when cooked.","images":[],"step":4},{"description":"Cook","images":[],"step":5},{"description":"Melt half the clarified butter in a 26cm / 10.5\" (or thereabouts) non-stick pan or skillet over medium low heat. Shallow non-stick pan with sloped sides is best for easy rosti removal.","images":[],"step":6},{"description":"Place the potato in pan, but do not pack down. Use rubber spatula to tidy the edges, then lightly pat down to even surface.","images":[],"step":7},{"title":"Cook first side","description":"Cook 12 minutes until underside is very golden and crispy, lifting edge with rubber spatula to check. If by 8 minutes it is not going golden, increase heat.","images":[],"step":8},{"title":"TIP: Insurance policy","description":"If you didn''t use a non stick pan, slide the rubber spatular underneath all the way to the middle and run it around, to be 100% sure nothing is stuck before attempting flip.","images":[],"step":9},{"title":"Flip","description":"Cover pan with a round wooden board with a handle (or anything similar with a handle, Note 3). Holding the handle of the board, flip quickly - and with confidence!","images":[],"step":10},{"title":"Cook second side","description":"Melt remaining clarified butter in the pan, then slide the rosti back in and cook for 12 minutes until golden crispy, and there is no resistance when a knife is inserted into the middle.","duration":12,"images":[],"step":11},{"description":"Slide onto cutting board, cut into 4 or 6 wedges and serve immediately!","images":[],"step":12},{"description":"Use 25g / 1 1/2 tbsp clarified butter for each batch, medium heat in a non stick pan. Place potato in rounds in a skillet, around 8cm / 3\" wide, 1.5 - 2cm / 2/3\" thick (without patting down). Cook 5 minutes until deep golden and crispy, flip, and cook another 5 minutes until done.","images":[],"step":13},{"description":"To hold / keep warm","images":[],"step":14},{"description":"Transfer to rack set over tray in a 120°C/250°F oven until ready to serve.","images":[],"step":15}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Swiss","Western"],"categories":["all-vegetable-sides","potato-recipes","potatoes","side-dishes","sunday-supper"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_373ce38d7a5f', 'en', 'US', 'Tabbouleh White Bean Salad', 'Recipe video above. Think Tabbouleh -- but with the bulgur switched for white beans to make a more substantial salad that''s an excellent starch + veg side dish, or light meal for warm days! It''s fresh, lemony, herby, totally delicious and good for you.To add protein, top with grilled chicken or fish, hot smoked trout or even a can of tuna / other fish.Serves 8 - 10 as a side, 4 - 5 as a meal. Keeps for 3 days.', 'https://www.recipetineats.com/tachyon/2020/09/White-Bean-Salad-Tabbouleh.jpg', 15, 40, 55, 8, '[{"id": "ing_green_beans", "quantity": {"value": 800.0, "unit": "pack"}}, {"id": "ing_tomato", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_cucumber", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_mint", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_mustard", "quantity": {"value": 0.013, "unit": "jar of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["800g / 24 oz (2 cans) white beans (like cannellini, navy/haricot, butter beans) (, drained (Note 1 & 3))","4 tomatoes (, cut into 1.25cm / 1/2\" pieces)","3 cucumbers ((or 1 1/2 long English/Telegraph cucumbers), cut into 1.25cm / 1/2\" pieces)","1/2 red onion (, finely chopped)","1 cup parsley (, roughly chopped (1 large bunch))","1/3 cup mint (, roughly chopped)"],"purpose":"Salad:"},{"ingredients":["2 tbsp lemon juice","4 tbsp extra virgin olive oil","1 garlic clove (, small, minced using garlic press)","1/2 tsp Dijon mustard (Note 2)","1/2 tsp salt (, kosher/cooking salt (1/4 tsp table salt))","1/2 tsp black pepper"],"purpose":"Lemon Dressing:"}]', '[{"description":"Place Dressing ingredients in a jar and shake well to combine.","images":[],"step":1},{"description":"Place Salad ingredients in a big bowl. Drizzle over most of the Dressing, toss well.","images":[],"step":2},{"description":"Transfer to serving bowl. Serve!","images":[],"step":3}]', '["milk","mustard"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Mediterranean","Western"],"categories":["all-vegetable-sides","beans-lentils","cucumber","lentil-recipes","side-dishes","side-salads","tomato","vegan-lifestyle"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a8c1bee407a8', 'en', 'US', 'Green Beans in Creamy Parmesan Sauce - with bacon!', 'Recipe video above. The easier and dare I say a tastier alternative to Green Bean Casserole! Using the bacon fat and garlic to saute the green beans before semi steaming/braising the beans in chicken broth guarantees flavour even before we get to the creamy paremsan sauce!Serve this as an extra special side dish, or turn it into a meal by using it as a pasta sauce, or over rice/quinoa/cauliflower rice/mash.', 'https://www.recipetineats.com/tachyon/2020/09/Green-Beans-in-Creamy-Parmesan-Sauce-with-Bacon_7.jpg', 13, 12, 25, 4, '[{"id": "ing_bacon", "quantity": {"value": 0.75, "unit": "pack of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_green_beans", "quantity": {"value": 500.0, "unit": "pack"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["150g/ 5oz bacon (, chopped (use streaky, not lean))","2 garlic cloves (, finely minced)","500g/1lb green beans (, trimmed, cut into ~5cm / 2\" pieces)","1/2 cup chicken or vegetable stock / broth (, low sodium)","1 cup cream (, heavy/thickened (Note 1))","1/2 cup parmesan (, finely grated (best to grate your own))","Black pepper (, freshly ground)"]}]', '[{"description":"Place bacon in cold skillet, then turn the stove on high. (Note 2)","images":[],"step":1},{"description":"Cook bacon for 2 to 3 minutes until golden, then remove with a slotted spoon.","duration":2.5,"images":[],"step":2},{"description":"Discard excess bacon fat, leaving behind 1 1/2 tablespoons (or so). If you''re short, add a dab of butter (or olive oil).","images":[],"step":3},{"title":"Add garlic and stir for 10","description":"15 seconds until light golden.","duration":0.20833333333333334,"images":[],"step":4},{"description":"Add green beans and stir to coat in garlicky bacon fat.","images":[],"step":5},{"description":"Add chicken stock, stir, bring to simmer then cover with lid. (Note 3) Cook 3 minutes, stirring every now and then so it cooks evenly, until beans are tender-crisp, still bright green and almost cooked to your liking (it will cook more). There should be some liquid left (if not, that''s ok too)","images":[],"step":6},{"description":"Add cream, parmesan and pepper. Stir, bring to simmer then lower heat to medium low and let it gently simmer for 2 minutes until the cream reduces and becomes thicker. If you want it to stick to the beans thickly when warm, then reduce the sauce for another 1 minute until the sauce is quite thick. (Note 4)","duration":2,"images":[],"step":7},{"description":"Taste and add salt if needed (I don''t find it needs more).","images":[],"step":8},{"description":"Transfer to serving bowl, sprinkle with cooked bacon and extra parmesan if you like.","images":[],"step":9}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["all-vegetable-sides","green-beans","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ec4d6615a26e', 'en', 'US', 'Green Bean Avocado Salad with Creamy Avocado Dressing', 'Recipe video above. Copycat of a popular salad at a charcoal chicken chain in Sydney called Chargrill Charlie''s. I don''t go for their chicken. But they do good salads! Love the avocado on avocado in this. :)Haven''t tried but I imagine asparagus and broccolini would be terrific alternatives to the beans (similar shape and texture).Serves 6 to 8 as a side, 3 - 4 as a light meal with crusty bread or soft rolls.', 'https://www.recipetineats.com/tachyon/2020/08/Chargrill-Charlies-Green-Bean-Avocado-Salad-with-Avocado-Dressing_0.jpg', 20, 0, 20, 6, '[{"id": "ing_green_beans", "quantity": {"value": 500.0, "unit": "pack"}}, {"id": "ing_tomato", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_capsicum", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.18, "unit": "tub of 250g"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_water", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["500g / 1 lb green beans (, ends trimmed, cut into 5cm / 2\" pieces)","3 tomatoes (, cut into thin wedges)","1 avocado (large, or 2 medium) (, diced into 1.5cm / 2/3\" pieces)","1/2 red capsicum / bell pepper (, diced)","1/2 red onion (, finely diced)"],"purpose":"Green Bean Salad"},{"ingredients":["1/2 cup ripe avocado (smush into cup to measure, or estimate - 1/2 medium avo)","3 tbsp extra virgin olive oil","3 tbsp sour cream or yogurt (Greek or plain, unsweetened) - OPTIONAL (Note 1)","2 tbsp lemon juice","1 garlic clove, small (, minced using garlic crusher (Note 2))","4 tbsp water (to thin out, it''s very rich!)","1/2 tsp salt","1/4 tsp black pepper"],"purpose":"Creamy Avocado Dressing:"}]', '[{"description":"Place all ingredients into a Nutribullet or small food processor and blitz until smooth (including any Extra Flavouring Options suggested in the standalone Creamy Avocado Dressing recipe).","images":[],"step":1},{"description":"Use water to thin to just pourable consistency (so it''s not super gloopy and thick). Taste and add the following to taste: salt, pepper, lemon, oil.","images":[],"step":2},{"description":"Steam green beans using method of choice until soft (I microwave, 5 minutes on high). Drain then leave to cool and dry.","images":[],"step":3},{"description":"Place remaining salad ingredients in a large bowl with the beans. Drizzle with half the Dressing. Toss. Serve with remaining Dressing on the side.","images":[],"step":4},{"title":"Presention note","description":"It looks a bit of a mess once tossed. If you''re serving to impress, just drizzle the Avocado Dressing over and take to the table like that (see in post, it''s much prettier!).","images":[],"step":5}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Western"],"categories":["all-vegetable-sides","avocado","green-beans","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_afb8c20dde42', 'en', 'US', 'Creamy Avocado Dressing', 'Recipe video above. This is a dressing that uses avocado to make it creamy, rather than mayonnaise or loads of oil. It doesn''t taste very avocado-ey because avocados are dense so it needs to be thinned out to make it pourable as a dressing. Rather, think of the avocado as the better-for-you means to get a creamy dressing fix!Excellent use for avocados that are a bit overripe or with brown spotty bits. Use as dressing for all your favourite salads. Particularly good salads that call for Ranch, Caesar or other mayo-rich dressings.Makes 1 1/4 cups - enough for a side salad for 6 to 8 (depending on how much you use!)', 'https://www.recipetineats.com/tachyon/2020/08/Creamy-Avocado-Dressing.jpg', 5, 0, 5, 8, '[{"id": "ing_avocado", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.18, "unit": "tub of 250g"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_water", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_see_note_3", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["1/2 cup ripe avocado (smush into cup to measure, or estimate - 1/2 medium avo)","3 tbsp extra virgin olive oil","3 tbsp sour cream or yogurt (Greek or plain, unsweetened) - OPTIONAL (Note 1)","2 tbsp lemon juice","1 garlic clove, small (, minced using garlic crusher (Note 2))","4 tbsp water (to thin out, it''s very rich!)","1/2 tsp salt","1/4 tsp black pepper"],"purpose":"Creamy Avocado Dressing:"},{"ingredients":["See Note 3"],"purpose":"EXTRA FLAVOURING OPTIONS:"}]', '[{"description":"Place all ingredients into a Nutribullet or small food processor and blitz until smooth. (Inc Extra Flavouring Options)","images":[],"step":1},{"description":"Use water to thin to just pourable consistency (so it''s not super gloopy and thick).","images":[],"step":2},{"title":"Taste and add the following to taste","description":"salt, pepper, lemon, oil. Use as salad dressing!","images":[],"step":3},{"description":"Keeps 3 days in the fridge without going brown. See Note 3 for how to keep even longer!","images":[],"step":4}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Western"],"categories":["all-vegetable-sides","avocado","dressings","salad-dressings"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_247f08932ef8', 'en', 'US', 'Eggplant Curry - South Indian Brinjal Curry', 'Recipe video above. This curry is not for the faint hearted! Eggplant (Brinjal) stars in this strong flavoured curry, roasted rather than fried for a healthier yet equally delicious (high temp does the trick here), then simmered in an intensely spiced South Indian curry sauce so it sucks up the flavour and partially collapses to create a big pot of juicy (delicious) mush. Incidentally vegan (as much of South Indian food is). See recipe notes for subs for the harder to find spices. And when you''ve made this, use the same spices to make this Vegetable Samosa Pie!Spiciness: Pretty mild. Spiciness only comes from the chilli powder so if you''re concerned, skip or reduce it!', 'https://www.recipetineats.com/tachyon/2020/08/Eggplant-Curry-Indian__2.jpg', 15, 60, 75, 4, '[{"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 58.333, "unit": "carton of 12"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_mustard", "quantity": {"value": 0.019, "unit": "jar of 200g"}}, {"id": "ing_curry_leaves", "quantity": {"value": 14.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.113, "unit": "can of 400ml"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_round_clove", "quantity": {"value": 1.25, "unit": "jar"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_chilli", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 0.4, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.5, "unit": "jar of 40g"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.4, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["2 tbsp vegetable oil (or canola)","700g / 1.2 lb eggplant (aubergine) (, 2 medium (Note 1))","1/2 tsp each salt and pepper"],"purpose":"Roasted Eggplant:"},{"ingredients":["3 tbsp vegetable oil (or canola)","3/4 tsp black mustard seeds (Note 2)","14 curry leaves, fresh (Note 3)","1 red onion (, quartered and thinly sliced)","3 tbsp passata or tomato pulp (or canned tomato) (Note 4)","1 tbsp garlic (, grated (4 cloves approx))","1 tbsp ginger (, grated (1.5cm piece approx))","1 1/4 cups water","3/4 tsp salt","3 tbsp coconut milk (or cream, full fat (Note 5))"],"purpose":"Curry:"},{"ingredients":["1/4 tsp cardamom powder","1/4 tsp ground clove","1/4 tsp black pepper","1/2 tsp chilli powder (or cayenne (NOT US Chilli Powder))","4 tsp coriander powder","4 tsp cumin powder"],"purpose":"Curry Spices:"},{"ingredients":["Basmati rice","Yogurt (, highly recommended)","Coriander/cilantro leaves (, optional)","Easy flatbread (as naan!) (, optional)"],"purpose":"Serving"}]', '[{"description":"Roasted Eggplant:","images":[],"step":1},{"description":"Preheat oven to 240°C / 450°F (220°C fan). Line tray with parchment/baking paper.","images":[],"step":2},{"description":"Cut eggplant into 2cm / 4/5\" slices, then cut into 2cm / 4/5\" batons.","images":[],"step":3},{"description":"Place in large bowl, toss with oil, salt and pepper.","images":[],"step":4},{"description":"Spread on tray, roast 20 minutes. Turn, roast for a further 10 minutes - edges should be caramelised, soft inside, but they''re not shrivelled up and dismal. Use per recipe.","images":[],"step":5},{"description":"Heat oil in a large pot over medium heat. Add mustard seeds, let them sizzle for 15 seconds.","duration":0.25,"images":[],"step":6},{"description":"Add curry leaves, stir, leave to sizzle for 15 seconds - seeds might pop, Indian cooking is very dramatic!","duration":0.25,"images":[],"step":7},{"description":"Add onions, cook 5 minutes until golden brown.","images":[],"step":8},{"description":"Add tomato, cook for 1 minute, stirring.","duration":1,"images":[],"step":9},{"description":"Add garlic and ginger, cook 2 minutes.","images":[],"step":10},{"description":"Add Curry Spices and salt, and cook for another 3 minutes - it will be a thick paste and might stick to the bottom of the pot, don''t let it burn (if it starts to, remove from stove and quickly add splash of water to loosen).","images":[],"step":11},{"description":"Stir in water, and then add the eggplant.","images":[],"step":12},{"description":"Gently stir, partially cover, reduce heat to low and simmer 30 minutes. Stir carefully once or twice (so the eggplants don''t break up completely), add more water if it dries out.","images":[],"step":13},{"description":"Stir in coconut milk, taste then add more salt if needed.","images":[],"step":14},{"description":"Your result should be a very thick, juicy, strongly flavoured curry with eggplant partially intact but half collapsed.","images":[],"step":15},{"description":"Serve with basmati rice and a dollop of yogurt and fresh coriander leaves, if you want.","images":[],"step":16}]', '["milk","mustard"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["all-vegetable-sides","curry-recipes","dietary","eggplant","gluten-free-recipes","indian-recipes","low-calorie-recipes","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_457a5d9390ad', 'en', 'US', 'Our best No Mayo Coleslaw', 'Recipe video above. This Slaw is addictive! The combination of ingredients in this might seem surprising but the flavours work extremely well together. With a subtle, refreshing flavour yet somehow at the same time has that "juiciness" that we love about traditional mayo based Coleslaw. The flavour of the fennel and caraway seeds it quite subtle - in fact, many people don''t even realise it''s in there, they just know it''s delicious!We love serving this refreshing salad with rich Southern Foods like Fried Chicken, Brisket, BBQ Chicken, Pork Ribs and BBQ Pulled Pork. It''s a perfect match!', 'https://www.recipetineats.com/tachyon/2020/08/No-Mayo-Coleslaw_9.jpg', 15, 0, 15, 10, '[{"id": "ing_cabbage", "quantity": {"value": 5.0, "unit": "head"}}, {"id": "ing_fennel_bulb", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_apples", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_dill", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_caraway_seeds", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_garlic", "quantity": {"value": 2.0, "unit": "pack of 3 heads"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.09, "unit": "bottle of 500ml"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.075, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}]', '[{"ingredients":["1/4 large head green cabbage (or 1/2 small head) (, shredded (~12 cups, Note 1))","1 medium fennel bulb (, trimmed, halved and shaved at 1.5 mm on a mandolin (Note 2))","1 red apple (any kind is fine), halved and thinly sliced (1.5 mm thick)","1 cup dill leaves, roughly chopped (about 1 whole bunch)","2 tsp caraway seeds (Note 4)"],"purpose":"Coleslaw:"},{"ingredients":["2 small clove garlic (, minced)","3 tbsp apple cider vinegar (, or less to taste (Note 6))","5 tbsp olive oil","2 tsp Dijon mustard","1 1/2 tsp caster sugar (Note 5)","1/2 tsp salt (Note 5)","1/8 tsp black pepper"],"purpose":"Dressing:"}]', '[{"title":"Dressing","description":"Shake Dressing ingredients in a jar.","images":[],"step":1},{"description":"Toss! Place cabbage, fennel, apple and dill in a very large bowl. Pour over Dressing, toss well.","images":[],"step":2},{"description":"Sprinkle with caraway seeds then toss again.","images":[],"step":3},{"description":"Set aside for at least 1 hour to allow cabbage to wilt. Give it a good toss, then transfer to serving bowl and serve!","images":[],"step":4},{"title":"Storage","description":"Keeps perfecty for 3 to 4 days in the fridge. Dressing stops apple from going brown. Best to bring to room temperature before serving.","images":[],"step":5}]', '["mustard"]', '["gluten_free","keto_friendly","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["all-vegetable-sides","cabbage","fennel","quick-and-easy","side-salads","vegan-lifestyle"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1f4ba82bdc05', 'en', 'US', 'Roasted Broccolini with Tahini Sauce', 'Recipe video above. I think that roasting is the best way to cook broccolini. It brings out the flavour and you get crunchy golden tips - the best part! It makes a wonderful side dish eaten plain, but if you drizzle it with a simple Tahini Sauce and sprinkle with nuts, it becomes company-worthy as an impressive side dish OR a main served with crusty bread or stuffed into flatbreads.Especially brilliant served with all things Middle Eastern.', 'https://www.recipetineats.com/tachyon/2020/08/Roasted-Broccolini-with-Tahini-Sauce_5.jpg', 10, 15, 25, 4, '[{"id": "ing_broccoli", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_tahini", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_water", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_honey", "quantity": {"value": 0.015, "unit": "jar of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_pine_nuts", "quantity": {"value": 0.375, "unit": "pack of 100g"}}]', '[{"ingredients":["500g/1 lb broccolini (, ends trimmed (3 standard bunches in Australia))","1 tbsp extra virgin olive oil","1/4 tsp each salt and pepper","1 garlic clove (, finely minced)"]},{"ingredients":["1/4 cup tahini","2.5 tbsp water","1.5 tsp honey","1 tbsp lemon juice","1/2 garlic clove (, pressed through garlic crusher or grated using microplan (to make sauce smooth))","1/4 tsp each salt and pepper"],"purpose":"Tahini Sauce:"},{"ingredients":["1/4 cup flaked almonds, pine nuts or pistachios (, toasted (Note 2))"],"purpose":"Garnish:"}]', '[{"description":"Preheat oven to 220°C/425°F (200°C fan).","images":[],"step":1},{"title":"Sauce","description":"Mix Tahini Sauce ingredients until combined. It should be loose enough so it can be drizzled, but not too runny. Set aside 15 minutes.","images":[],"step":2},{"title":"Toss broccolini","description":"Pile broccolini on tray, drizzle with oil, sprinkle with salt, pepper and garlic.","images":[],"step":3},{"title":"Roast for 12","description":"15 minutes until the broccolini floret ends are dark brown and crunchy (the best part!), and the broccolini stem is just tender. (But if you want it really soft, lower temp to 180C/350F and cook 20 min).","duration":13.5,"images":[],"step":4},{"title":"Plate up","description":"Transfer to serving plate, allow to cool until warm. Drizzle over tahini sauce, sprinkle with almonds or pine nuts and serve! Excellent served warm OR at room temp.","images":[],"step":5},{"description":"The Tahini Sauce goes brilliantly with other roasted vegetables too, including: carrots, cauliflower, broccoli, green beans and asparagus.","images":[],"step":6}]', '[]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern"],"categories":["all-vegetable-sides","broccoli","quick-and-easy","side-salads","vegan-lifestyle"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_68e5a9432445', 'en', 'US', 'Quick and Easy Baked Zucchini', 'Recipe video above. This is just a really tasty, quick and easy way to cook zucchini in the oven. For all those times you need a quick veggie side dish! A little sprinkle of parmesan adds great flavour, and breadcrumbs adds a touch of terrific texture.Roasting at a high temp makes the parmesan golden and gets some browning on the zucchini before they turn into watery mush.', 'https://www.recipetineats.com/tachyon/2020/07/Parmesan-Roasted-Zucchini_4.jpg', 3, 12, 15, 4, '[{"id": "ing_zucchini", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 0.037, "unit": "loaf"}}, {"id": "ing_parmesan", "quantity": {"value": 0.15, "unit": "pack of 200g"}}]', '[{"ingredients":["600g/ 1.2lb zucchinis (4 large, 5 medium)","2 tbsp olive oil","1/2 tsp each salt and pepper","2 tbsp breadcrumbs","2 tbsp parmesan (, grated (store bought sandy type is best))"]}]', '[{"description":"Preheat oven to 240°C / 450°F (220°C fan) with the oven shelf set high in the oven.","images":[],"step":1},{"description":"Trim the ends off the zucchini. Cut medium zucchinis in quarters lengthwise, and large ones into sixths (halve then cut each half into 3 lengthwise to make 6 long \"wedges\").","images":[],"step":2},{"description":"Pile zucchini on a tray. Drizzle with 1 tablespoon oil, salt and pepper. Toss.","images":[],"step":3},{"description":"Line up in two rows so they''re touching each other, with the skin side down.","images":[],"step":4},{"description":"Sprinkle evenly with breadcrumbs, then parmesan, drizzle with 1 tablespoon oil.","images":[],"step":5},{"description":"Bake 12 minutes until the parmesan is golden and zucchini is soft but not soggy.","images":[],"step":6},{"description":"Serve immediately!","images":[],"step":7}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["all-vegetable-sides","quick-and-easy","side-dishes","side-salads","zucchini","zucchini-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_732f4bfb09a6', 'en', 'US', 'Great Roasted Carrots', 'Recipe video above. In my opinion, there is only one way to roast carrots - on a high temperature so they brown beautifully in the same time it cooks for the inside to become sweet and tender. Cooked this way, you need nothing more than salt and pepper, though a hit of garlic never hurts!Extra flavouring options - see Note 3.', 'https://www.recipetineats.com/tachyon/2020/07/Roasted-Carrots_7.jpg', 5, 30, 35, 5, '[{"id": "ing_carrot", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_see_note_3", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 kg / 2 lb carrots (, peeled and ends trimmed (Note 1))","2 tbsp olive oil","3/4 tsp salt","1/2 tsp black pepper","2 garlic cloves (, minced using garlic press or finely grated using microplane (optional, Note 2))"]},{"ingredients":["See Note 3"],"purpose":"Extra flavouring options"},{"ingredients":["Fresh parsley"],"purpose":"Optional garnish:"}]', '[{"description":"Preheat oven to 220°C/430°F (200°C fan).","images":[],"step":1},{"description":"Cut the carrots on the diagonal into 5cm / 2\" lengths. Cut the thicker ones in half lengthwise so they are all roughly the same width.","images":[],"step":2},{"description":"Place on a tray, drizzle with oil, sprinkle with salt and pepper, toss.","images":[],"step":3},{"title":"Roast 20 minutes","description":"Spread out on tray, roast 20 minutes.","images":[],"step":4},{"title":"Flip & garlic","description":"Remove from oven. Push carrots to one end, add garlic and toss. (Add other Flavour Options at this point too)","images":[],"step":5},{"title":"Roast 10 minutes","description":"Roast for a further 10 minutes. Remove from oven, toss carrots to coat in the garlicky oil and juices on the tray.","images":[],"step":6},{"description":"Sprinkle with parsley and serve!","images":[],"step":7}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["all-vegetable-sides","carrots","quick-and-easy","side-salads","vegan-lifestyle"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_606208bf5626', 'en', 'US', 'Roasted Eggplant Lentil Salad (Aubergine Salad)', 'Recipe video above. Lentils and roasted eggplant (aubergine) is such a great combination - especially when you infuse the lentils with flavour by cooking them in a seasoned broth, and you try my method of roasting eggplant so they stay plump and juicy inside with great caramelisation on the outside! (For more roasted eggplant uses, visit this roasted eggplant recipe).Great to serve at a brunch as a main - it holds up well for hours. Serve warm, or at room temp. Serves 3 to 4 as main, 8 - 10 as a side.', 'https://www.recipetineats.com/tachyon/2020/07/Roasted-Eggplant-Lentil-Salad_4.jpg', 15, 1470, 1485, 4, '[{"id": "ing_lentils", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_chicken", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_egg", "quantity": {"value": 58.333, "unit": "carton of 12"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_thyme", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_feta_cheese", "quantity": {"value": 60.0, "unit": "block of 200g"}}]', '[{"ingredients":["1 cup dried green or brown lentils (or French/puy) (Note 1 for canned)","1 cup vegetable or chicken broth (or water + 1 bouillon cube, crumbled)","1 1/2 cups water","1 large garlic clove (, smashed, skin removed (Note 2))","Lemon peel (about 1.5 x 5 cm / 3/4 x 2\")","1 bay leaf (, dry or fresh)","2 sprigs thyme (, or 1/2 tsp dried thyme)","1 rib celery (, broken into 3 or 4 pieces (or just a handful of celery leaves, can skip))"],"purpose":"TASTY LENTILS!"},{"ingredients":["700g / 1.4 lb eggplant / aubergine (2 medium)","2 1/2 tbsp olive oil","1/4 tsp EACH salt and pepper"],"purpose":"Roasted Eggplant:"},{"ingredients":["2 tbsp lemon juice (or cider vinegar, white or red wine vinegar)","4 tbsp extra virgin olive oil","1 tsp Dijon mustard","1 garlic clove (, minced using garlic press)","1 tsp thyme leaves (, fresh (or 1/2 ts dried - can omit, or other herbs, Note 3))","1 tsp sugar (, optional)","1/2 tsp EACH salt + black pepper"],"purpose":"Garlic Lemon Dressing:"},{"ingredients":["250g/ 8 oz cherry tomatoes (, halved (large quartered))","2 handfuls rocket / arugula lettuce (, torn into 5cm/2\" pieces)","60g/ 2 oz feta (, crumbled (or more!))"],"purpose":"Salad:"}]', '[{"title":"Dressing","description":"shake in a jar.","images":[],"step":1},{"description":"Place Lentil ingredients in a saucepan, bring to simmer over medium heat. Place lid on then lower heat to medium low so it''s simmering gently.","images":[],"step":2},{"description":"Cook for 20 minutes (for al dente, my preference), or 25 minutes (for soft), stirring occasionally.","duration":20,"images":[],"step":3},{"description":"Drain, then pick out all the flavouring bits (garlic etc). BRIEFLY rinse to get grit off - don''t wash off all the flavour! Shake off excess water well.","images":[],"step":4},{"description":"Preheat oven to 240°C / 450°F (220°C fan). Line a tray with parchment/baking paper.","images":[],"step":5},{"title":"Cut eggplant into large cubes","description":"3 cm / 1.2\". Place in large bowl, drizzle with oil, salt and pepper.","images":[],"step":6},{"description":"Toss well, then immediately spread on tray and roast 20 minutes. Flip, then roast for a further 10 minutes - edges should be caramelised, soft inside, but they''re not shrivelled up and dismal.","images":[],"step":7},{"description":"Add tomato and rocket into lentils, drizzle over most of the Dressing then toss.","images":[],"step":8},{"description":"Pour onto serving platter. Pile over eggplant.","images":[],"step":9},{"description":"Drizzle eggplant with remaining Dressing, sprinkle with feta . Serve warm or at room temp! Great with a side of flatbread or this easy crusty bread.","images":[],"step":10}]', '["mustard"]', '["gluten_free","high_protein"]', '{"mealType":["dinner","lunch"],"cuisine":["Western"],"categories":["all-vegetable-sides","beans-lentils","eggplant","lentil-recipes","salad-recipes-main-course","side-salads","vegan-lifestyle"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_372f55d7ea8d', 'en', 'US', 'Oven roasted eggplant (aubergine)', 'Recipe video above. This is a recipe for how to roast eggplant in the oven so each piece is plump and juicy on the inside, and beautifully caramelised on the outside. As oposed to a mushy mess, or shrivelled up and dismal! The key is: large pieces and high oven temp.Eggplant is actually really bland when raw, but it completely transforms when roasted. You don''t need anything more than salt and pepper, but I''ve added some suggestions!', 'https://www.recipetineats.com/tachyon/2020/07/Roasted-Eggplant_9.jpg', 5, 30, 35, 4, '[{"id": "ing_egg", "quantity": {"value": 58.333, "unit": "carton of 12"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["700g/ 1.2 lb eggplants ((2 medium), aka aubergine)","3 tbsp olive oil","1/2 tsp salt (kosher / cooking salt, or 1/4 tsp table salt)","1/2 tsp black pepper"]}]', '[{"description":"Preheat oven to 240°C / 450°F (220°C fan).","images":[],"step":1},{"title":"Line a tray with parchment/baking paper (optional","description":"recommended for first timers so you don''t lose the caramelised surface).","images":[],"step":2},{"title":"Cut eggplant into large cubes","description":"3 cm / 1.2\". Place in large bowl, drizzle with oil, salt and pepper.","images":[],"step":3},{"description":"Toss well, spread on tray, roast 20 minutes. Turn, roast for a further 10 minutes - edges should be caramelised, soft inside, but they''re not shrivelled up and dismal.","images":[],"step":4},{"description":"Transfer to serving plate. Delicious served plain, but see below for some finishing options.","images":[],"step":5},{"description":"1 teaspoon fresh thyme leaves (my favourite!), drizzle of fresh lemon juice, parsley, chives or green onions (for touch of freshness and colour, not so much flavour), tiny drizzle of balsamic vinegar (pop of tartness is terrific! OR drizzle of balsamic glaze), dollop of yogurt (creamy yogurt pairs really well with the juicy eggplant flesh).","images":[],"step":6}]', '[]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["all-vegetable-sides","eggplant","quick-and-easy","side-dishes","side-salads","vegan-lifestyle"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c738d2314315', 'en', 'US', 'Garlic Butter Roasted Mushrooms', 'Recipe video above. Here''s a simple, incredibly delicious way to roast mushrooms: tossed in garlic butter then roasted on a high temp to make them golden brown on the outside whilst keeping them juicy on the inside. The addition of olive oil stops the butter from burning and also adds a touch of extra flavour - but the dominant flavour is still butter (and garlic!). The lemon and thyme finishing touch is optional - it''s terrific plain - it''s an extra flavour option.Serves 2 as a main, 4 - 5 as a side.', 'https://www.recipetineats.com/tachyon/2018/10/Roasted-Mushrooms-Garlic-Butter_0.jpg', 5, 20, 25, 4, '[{"id": "ing_mushroom", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 0.045, "unit": "net of 500g"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}]', '[{"ingredients":["500g / 1lb mushrooms (, button or Swiss brown / cremini OR 8 large (like portabello))","50g / 3 tbsp unsalted butter (, melted)","1 tbsp olive oil","2 garlic cloves (, finely minced)","1/2 tsp each salt and pepper"]},{"ingredients":["1 1/2 tbsp lemon juice","1 tsp fresh thyme leaves (parsley also good for colour)"],"purpose":"Optional finishing flavour:"}]', '[{"description":"Preheat oven to 220°C/450°F (200°F fan).","images":[],"step":1},{"description":"Toss mushrooms with butter, oil, garlic, salt and pepper in a large bowl using a rubber spatula.","images":[],"step":2},{"title":"Spread on a baking tray and roast for 25 minutes","description":"do not toss or turn.","duration":25,"images":[],"step":3},{"description":"Remove from oven. If using lemon and thyme, push mushrooms together onto one side of the tray, drizzle with lemon, sprinkle with thyme and toss. Serve immediately!","images":[],"step":4},{"description":"How to roast LARGE MUSHROOMS (eg portabello)","images":[],"step":5},{"description":"(Video here for large mushrooms) Place mushrooms cap side down (ie stems facing up) in a medium baking dish (so they are kind of snug - they shrink).","images":[],"step":6},{"description":"Spoon 1 tsp of butter over each mushroom, then use the rest to brush the edges (or carefully drizzle over edges).","images":[],"step":7},{"description":"Drizzle over olive oil, sprinkle with salt and pepper.","images":[],"step":8},{"description":"Roast for 20 minutes (tender but still a slight firmness) or 25 minutes (tender) - no turning. There will be juices in the pan and plenty pooled in the mushrooms caps.","duration":20,"images":[],"step":9},{"description":"Squeeze over a bit of lemon juice, sprinkle with thyme. Serve mushrooms, drizzled with pan juices (see notes for serving suggestions).","images":[],"step":10}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["all-vegetable-sides","dietary","dinner-tonight","easter-sides-warm-hearty","gluten-free-recipes","main-dishes","mushroom-recipes","mushrooms","quick-and-easy","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bf6e7621c638', 'en', 'US', 'Incredible BBQ Grilled Vegetables - marinated!', 'Recipe video above! An assortment of vegetables grilled on the BBQ until tender-crisp with charred edges, then while still hot, tossed in a Lemon Herb & Garlic Marinade so they suck up the flavour. Great served freshly made, even better the next day! See in post for serving ideas - antipasto / cheeseboard, starter, side dish, main, salad, or pasta. Oven roasted directions also included.', 'https://www.recipetineats.com/tachyon/2019/06/Marinated-Grilled-Vegetables_3.jpg', 20, 20, 40, 8, '[{"id": "ing_capsicum", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_zucchini", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_es_asparagus", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.1, "unit": "net of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.5, "unit": "pack of 100g"}}]', '[{"ingredients":["2 red capsicum/bell peppers","2 yellow capsicum/bell peppers","2 red onions","1 eggplant (, halved lengthwise, then 1.25cm/ 0.5\" thick semi circles)","2 zucchini (, 0.7cm / 1/3\" thick slices on diagonal)","2 bunches asparagus (, ends trimmed)","200g/ 7oz button mushrooms"],"purpose":"Vegetables (Note 1):"},{"ingredients":["1/4 cup (65ml) extra virgin olive oil","1 tsp each salt and pepper","3 cloves garlic (, minced)","1/4 cup parsley (, roughly chopped (or chives))"],"purpose":"Grilling/Roasting:"},{"ingredients":["1/3 cup (85ml) lemon juice","1/3 cup (85ml) extra virgin olive oil","2 tsp white sugar","2 garlic cloves (, minced)","1/2 tsp each salt and pepper","1/2 tsp each dried basil, parsley, oregano, thyme (Note 2)","1/2 - 1 tsp chilli flakes (adjust spice to taste, Note 3)"],"purpose":"Grilled Vegetable Marinade (Dressing):"}]', '[{"description":"Place ingredients in a jar and shake well. Set aside 10 minutes+.","images":[],"step":1},{"description":"Cutting Vegetables (see video):","images":[],"step":2},{"description":"Keep pieces large for easy handling on the BBQ (so you don''t have to turn hundreds of pieces!) and so they don''t fall through the grills.","images":[],"step":3},{"title":"Capsicum/bell peppers","description":"cut the \"walls\" off, then cut each each on the diagonal into fairly large pieces.","images":[],"step":4},{"title":"Onion (Note 4)","description":"keep the root end (hairy end!) in tact. Peel, cut in half, then cut into wedges through the root end.","images":[],"step":5},{"description":"Grilling/Roasting Vegetables:","images":[],"step":6},{"description":"Brush BBQ grills lightly with oil, then preheat to high. Or oven 250°C/480°F.","images":[],"step":7},{"description":"Place vegetables in a very large bowl or use a big tray. Drizzle with oil, sprinkle with salt, pepper and garlic. Toss with hands (there is no better way!).","images":[],"step":8},{"description":"Place on BBQ and cook until tender crisp with charred edges - cook times below. Then remove into large bowl.","images":[],"step":9},{"description":"Cook times:","images":[],"step":10},{"title":"Asparagus, zucchini","description":"grill 2 min each side. (Oven - 10 min, no flipping)","images":[],"step":11},{"title":"Capsicum, mushroom, onion","description":"grill 3 min each side (oven 15 min, flip at 10 min)","images":[],"step":12},{"title":"Eggplant","description":"grill 4 min each side. Jab in middle to ensure soft but not soggy! (oven 18 min)","images":[],"step":13},{"description":"While vegetables are still hot, drizzle over Dressing and toss.","images":[],"step":14},{"description":"Set aside 10 minutes+ before serving, sprinkled with parsley. See in post for serving ideas.","images":[],"step":15}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["all-vegetable-sides","grilling-ideas-and-recipes","side-dishes","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0c03fd41a726', 'en', 'US', 'Creamy Cucumber Salad with Lemon Yogurt Dressing', 'Recipe video above. A beautiful tangy, refreshing Cucumber Salad! The yogurt dressing pairs beautifully with the fresh cucumber. Great side salad for Middle Eastern food, Greek, Indian and rich meat-heavy mains like Roasts.', 'https://www.recipetineats.com/tachyon/2019/10/Cucumber-Salad-Mint-Yogurt_1.jpg', 10, 0, 10, 5, '[{"id": "ing_cucumber", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_mint", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_yogurt", "quantity": {"value": 0.3, "unit": "tub of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["3 cucumbers (, standard (or 2 long Telegraph/English cucumbers) (Note 1))","1/2 red onion (, finely sliced)","1/4 cup mint leaves (, finely chopped (or 2 tsp dried mint))"]},{"ingredients":["1 cup yogurt (, full fat (Greek or plain))","2 tbsp extra virgin olive oil","2 tbsp lemon juice","1 garlic clove (, minced)","1/2 tsp salt and pepper (, each)"],"purpose":"Creamy Lemon Yogurt Dressing"}]', '[{"title":"Dressing","description":"Mix ingredients then leave for 20 minutes for the flavours to develop.","duration":20,"images":[],"step":1},{"title":"Cucumber","description":"Cut cucumber in half lengthwise, then slice into 3mm / 1/8\" thick slices.","images":[],"step":2},{"title":"Toss","description":"Place cucumber, onion and mint in a bowl. Pour over Dressing and toss, then serve.","images":[],"step":3}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Middle Eastern","Western"],"categories":["all-vegetable-sides","cucumber","quick-and-easy","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_eacdf979ea96', 'en', 'US', 'Caesar Salad - with homemade Caesar Salad Dressing', 'Recipe video above. This homemade Caesar Salad Dressing recipe will rival that of any great restaurant! Anchovy is key to proper flavour in the dressing - every self respecting restaurant uses it, so if you''ve had Caesar Salad out and loved it, you''ve eaten anchovies!Add chicken to make a meal, or serve it straight up the classic way.', 'https://www.recipetineats.com/tachyon/2016/05/Caesar-Salad_7.jpg', 20, 20, 40, 5, '[{"id": "ing_mayonnaise", "quantity": {"value": 0.375, "unit": "jar of 400g"}}, {"id": "ing_garlic", "quantity": {"value": 0.833, "unit": "pack of 3 heads"}}, {"id": "ing_fish_fillets", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_milk", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 2.0, "unit": "loaf"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_bacon", "quantity": {"value": 0.75, "unit": "pack of 200g"}}, {"id": "ing_lettuce", "quantity": {"value": 30.0, "unit": "head"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["1 cup mayonnaise (Hellman''s or S&W Whole Egg) (Note 1)","1/2 tsp garlic (, finely minced (use garlic press, if you can))","2 anchovy fillets ( or 3/4 tsp Anchovy paste (Note 2))","2 tbsp fresh lemon juice","1 tsp Dijon mustard","1 tsp Worcestershire sauce","1/2 cup freshly grated parmesan cheese (, or 1/3 cup store bought grated parmesan cheese (Note 3))","3 - 4 tbsp milk (to adjust consistency)","1/4 tsp salt","1/4 tsp Black pepper"],"purpose":"Dressing"},{"ingredients":["2 - 3 slices white bread (, 2/3\" / 1.5cm thick (Note 4))","1 garlic (, cut in half)","1 tbsp olive oil","1/4 tsp salt"],"purpose":"Garlic Croutons"},{"ingredients":["150g / 5oz streaky bacon (, cooked and chopped)","10 cups cos / romaine lettuce (, chopped, wash & dried (1 large, 2 medium, 3 small) (Note 5))","Freshly grated parmesan (, for garnish)"],"purpose":"Salad"},{"ingredients":["2 - 4 eggs (, cooked to your taste, peeled and halved)","500g / 1lb chicken breast fillets (2 pieces)","1/2 tsp EACH salt and pepper","1 tbsp olive oil"],"purpose":"Optional Extras – Chicken & Egg"}]', '[{"description":"Whizz all ingredients in food processor until smooth, starting with 3 tbsp milk.","images":[],"step":1},{"description":"Taste and adjust salt and pepper as desired, and use milk to get the dressing to the desired consistency. (Note 6)","images":[],"step":2},{"description":"Set aside for 20 minutes+ to allow flavours to develop.","duration":20,"images":[],"step":3},{"description":"Place bacon into a cold skillet (no oil), then turn onto medium high. Cook until golden, turn, cook other side until golden. Remove onto paper towels, cool, then chop.","images":[],"step":4},{"description":"Garlic Croutons","images":[],"step":5},{"description":"Preheat oven to 180°C/350°F.","images":[],"step":6},{"description":"Toast bread in the toaster for 1 minute (or oven for 2 minutes each side) until surface is dried but not browned.,","duration":1,"images":[],"step":7},{"description":"Rub both sides of each piece of bread with the cut side of the garlic (Note 7).","images":[],"step":8},{"description":"Remove crust from bread (optional) and cut into cubes - around 1.5 cups. Drizzle with 1 - 2 tbsp olive oil, sprinkle with salt, then bake until golden, shaking the tray once. Sandwich bread will take around 7 minutes, sourdough and similar breads take 12 - 15 min.","images":[],"step":9},{"description":"Place lettuce in bowl with 1/2 the Dressing. Toss well, taste, then decide if you want more Dressing.","images":[],"step":10},{"description":"Transfer to serving bowl. (Top with chicken and egg if using) Scatter over with bacon and croutons. Sprinkle with parmesan and serve!","images":[],"step":11},{"title":"OPTIONAL EXTRAS","description":"Chicken & Egg","images":[],"step":12},{"title":"Eggs","description":"Place the eggs in a saucepan and cover with water. Place over medium high heat and bring to simmer. Once the water is simmering, turn down to medium (gentle simmer) and cook for 3 min (for soft centres), 4 min for firm yolks and 6 min for hard boiled. Remove eggs, run under cold water for 15 sec then leave submerged in a bowl of cold tap water for 5 min. Peel then set aside. (Note 6)","duration":3,"images":[],"step":13},{"title":"Chicken","description":"Either pound the chicken to about 1.2cm/ 1/2\" even thickness, or slice each breast in half horizontally. Sprinkle both sides with salt and pepper. Use bacon fat remaining in skillet. Cook first side for 5 min, turn then cook the other side for 2 min. Remove, cover loosely with foil and rest for 5 min. Cut into slices.","duration":5,"images":[],"step":14}]', '["egg","fish","gluten","milk","mustard"]', '["keto_friendly","low_calorie"]', '{"mealType":["dinner","lunch"],"cuisine":["South Western"],"categories":["all-vegetable-sides","chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","leafy-greens","main-dishes","no-cook-food","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3e8a328d125c', 'en', 'US', 'Salad Dressing', 'This is my everyday salad dressing "formula". This recipe makes just over 1/4 cup of dressing as is enough to dress a large leafy salad for 4 people - you just want the lettuce to be lightly coated, not drowning. The trick is to make this in a jar so you can shake it really well, which will make the oil and vinegar emulsify, meaning they mix together and thicken so they will coat your salad nicely.', 'https://www.recipetineats.com/tachyon/2020/03/Salad-Dressing_5.jpg', 2, 0, 2, 4, '[{"id": "ing_vinegar", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.013, "unit": "jar of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 0.5, "unit": "pack of 3 heads"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_honey", "quantity": {"value": 0.01, "unit": "jar of 500g"}}, {"id": "ing_herbs", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["1 tbsp any vinegar or lemon juice (my favourite is cider vinegar) (Note 1)","3 tbsp extra virgin olive oil (or other neutral oil)","1/2 tsp Dijon Mustard (or other non spicy smooth mustard)","1/2 tsp EACH salt and pepper"]},{"ingredients":["1/2 - 1 small garlic clove* (, pressed through crusher or smashed (Note 2))","1 tsp lemon zest*","1/4 tsp sugar (Note 3)","1 tsp honey (Note 3)","Finely chopped fresh herbs","1/2 tsp dried herbs*","Pinch of red pepper flakes"],"purpose":"Optional Flavourings – choose:"}]', '[{"description":"Place Dressing ingredients and Optional Flavourings in a jar and shake well until mustard dissolves.","images":[],"step":1},{"description":"Makes enough for a big leafy salad for 4 people (4 big handfuls of lettuce), or garden salad.","images":[],"step":2},{"title":"Storage","description":"Excluding garlic and fresh herbs, Dressing will keep for weeks in the fridge - just give it a good shake before using. Big batch - click servings and slide.","images":[],"step":3},{"description":"Use to dress any fresh salad (make sure leaves are dry otherwise it won''t stick) or steamed, boiled or roasted vegetables (douse while hot so it absorbs!). Drizzle and toss well just before serving.","images":[],"step":4}]', '["mustard"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Western"],"categories":["all-vegetable-sides","dressings","leafy-greens","salad-dressings","salad-recipes-main-course","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e5ccec053a88', 'en', 'US', 'Chipotle Lime Roasted Cauliflower', 'Recipe video above. One of the most delicious quick and easy dish I''ve ever made with cauliflower! Serve it as a side, or have it as a meal as I''ve done many times (yes, it''s that good!)', 'https://www.recipetineats.com/tachyon/2020/03/Chipotle-Lime-Roasted-Cauliflower_0.jpg', 10, 25, 35, 4, '[{"id": "ing_cauliflower", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_chipotle", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_lime", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["1 large head cauliflower (, cut into florets)","2 garlic cloves (, minced)","2.5 tbsp extra virgin olive oil","1.5 tsp chipotle powder (more or less for spiciness!) (Note 1)","3/4 tsp salt","1/2 tsp black pepper","1 tbsp lime juice (1 medium to large lime)","1 tbsp coriander/cilantro leaves (, finely chopped (optional, sub parsley or chives))"]}]', '[{"description":"Preheat oven to 200°C/390°F.","images":[],"step":1},{"description":"Place cauliflower in a large bowl. Drizzle over oil, sprinkle with garlic. Use hands to mix and rub oil over all cauliflower.","images":[],"step":2},{"description":"Sprinkle over chipotle, salt and pepper. Toss to coat.","images":[],"step":3},{"description":"Spread out on tray. Bake 25 minutes, tossing once, until the edges are caramlised and cauliflower is just tender.","images":[],"step":4},{"description":"Remove from oven. Push cauliflower together, drizzle over lime juice.","images":[],"step":5},{"description":"Sprinkle with coriander and serve hot.","images":[],"step":6}]', '[]', '["gluten_free","keto_friendly","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["South Western","Western"],"categories":["all-vegetable-sides","cauliflower","quick-and-easy","side-dishes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_303759e5fe3e', 'en', 'US', 'Creamy Mashed Potato', 'Recipe video above. This is my essential mashed potato recipe I make 362 days of the year*. It''s a must-have at holiday gatherings and Sunday Suppers, and it''s the mash you''ve seen smothered by sauces and gravies in hundreds of recipes on my website! Easy, creamy, buttery, rich but not insanely so (we have Paris Mash for that). Serve with everything. (*The other 3 days of the year I make Paris Mash, KFC Potato and Gravy, and Creamy Cauliflower Mash)', 'https://www.recipetineats.com/tachyon/2020/03/Creamy-Mashed-Potato_7.jpg', 10, 20, 30, 6, '[{"id": "ing_potato", "quantity": {"value": 1.5, "unit": "bag of 2kg"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_milk", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1.5 kg / 3 lb potatoes, peeled and cut into 2.5cm/1” cubes (Preferably Sebago, Russet or Maris Piper, Note 1)","1 tbsp salt (for cooking)"]},{"ingredients":["60g / 4 tbsp unsalted butter (, chopped)","1/2 cup milk (, preferably warmed)","1/2 tsp salt"],"purpose":"Flavourings:"},{"ingredients":["Extra melted butter","Chives or parsley (, chopped)"],"purpose":"Garnish:"}]', '[{"description":"Place in a large pot with 1 tbsp salt. Add water so it’s 10cm / 4” above potatoes.","images":[],"step":1},{"description":"Bring to a boil over high heat then reduce heat so it’s simmering rapidly. Cook 15 minutes or until potatoes are very soft (jab with fork to test, they should fall apart).","images":[],"step":2},{"description":"Drain well, return into pot. Leave for 1 minute, shaking pot every now and then, to encourage evaporation of water.","duration":1,"images":[],"step":3},{"description":"Add Flavourings then mash well, using milk to make it looser if desired.","images":[],"step":4},{"title":"DO NOT use","description":"a beater, stick blender, food processor or blender. You can pulse with a stand mixer or handheld mixer but be cautious, stop as soon as it''s creamy (potatoes will quickly go from perfect to gluey using appliances).","images":[],"step":5},{"description":"Transfer to serving bowl, make pretty swirls across the top and drizzle over butter. Sprinkle with chives then serve!","images":[],"step":6},{"title":"MAKE AHEAD / KEEPING WARM","description":"choose:","images":[],"step":7},{"title":"30 minutes or less","description":"Cover bowl tightly with cling wrap and keep in a warm place (like near the stove), will stay warm for 30 min. Gently stir before serving.","duration":30,"images":[],"step":8},{"title":"Up to 2 hours, over hot water","description":"place bowl with mash over a pot of boiling hot water (turn stove on every now and then to keep water hot) or keep about 3 cm / 1\" water gently simmering. Bowl should not touch water.","images":[],"step":9},{"title":"Up to 4 hours, slow cooker warm seeting","description":"press baking paper/parchment paper onto potato surface, then cover tightly with foil. Keep in slow cooker on WARM setting (60C/140F or less).","images":[],"step":10},{"title":"Day before","description":"use this recipe for Make Ahead Mashed Potatoes (uses a restaurant trick!)","images":[],"step":11}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Universal","Western"],"categories":["all-vegetable-sides","potato-recipes","potatoes","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4e800c376233', 'en', 'US', 'Cherry Tomato Salad', 'Recipe video above. This fresh, juicy tomato salad brings together two of the greatest flavour combinations known to mankind - tomato and basil! Make this with cherry tomatoes or grape tomatoes, or even normal tomatoes cut into chunks.The vinaigrette is slightly thickened with mustard so it clings to the tomato better, and a touch of red onion provides some much needed freshness.', 'https://www.recipetineats.com/tachyon/2020/03/Tomato-Basil-Salad_2.jpg', 10, 0, 10, 4, '[{"id": "ing_cherry_tomatoes", "quantity": {"value": 3.0, "unit": "punnet of 250g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_basil", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_vinegar", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.013, "unit": "jar of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["750g/ 1.5lb cherry tomatoes or grape tomatoes (or large tomatoes)","1/2 red onion (, finely sliced)","1/2 cup basil leaves (, tightly packed, finely sliced (Note 2))"]},{"ingredients":["1 tbsp cider vinegar (Note 3 for others)","2.5 tbsp extra virgin olive oil","1/2 tsp dijon mustard (or other non spicy mustard)","1/2 tsp each salt and pepper"],"purpose":"Dressing:"}]', '[{"description":"Shake Dressing in a jar. Taste and add more salt or pepper, or oil if you want less tart.","images":[],"step":1},{"title":"Cut Tomatoes","description":"cut cherry tomatoes / grape tomatoes in half. If using large ones, cut into wedges then bite size pieces.","images":[],"step":2},{"description":"Place tomatoes, onion and basil in a bowl.","images":[],"step":3},{"description":"Pour over Dressing. Gently toss and serve immediately.","images":[],"step":4}]', '["mustard"]', '["gluten_free","keto_friendly","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Italian","Western"],"categories":["all-vegetable-sides","quick-and-easy","side-dishes","side-salads","tomato"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5c7961754908', 'en', 'US', 'Cowboy Bean Salad', 'Recipe video above. Why make a boring ole'' Bean Salad when you can make it a COWBOY one?? A fresh, simple, healthy black bean salad with a South West lime dressing, this is endlessly versatile and lasts for days. Serve it as a side, stuff it in tacos, burritos and wraps. Pile onto burritos and tacos, take it to work for lunch! {Quantity: Written recipe scaled down to use 1 can of each beans and corn, pictures and video show double batch}', 'https://www.recipetineats.com/tachyon/2020/02/Bean-Salad_8.jpg', 15, 0, 15, 8, '[{"id": "ing_black_beans", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_corn", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_chipotle", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_cumin", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}]', '[{"ingredients":["400g/14 oz can black beans (, rinsed & drained (Note 1))","400g/14 oz can corn (, drained (or frozen thawed 1.5 cups))","1 red capsicum/bell pepper (, 1cm/1/3\" diced)","1 avocado (, diced)","1 red onion (, diced)","3/4 cup coriander/cilantro (, roughly chopped)","250g/8oz cherry tomatoes (, quartered (or 2 large tomatoes, deseeded and diced, Note 2))"],"purpose":"Cowboy Bean Salad:"},{"ingredients":["2 tbsp lime juice","4 tbsp olive oil","1/4 tsp chipotle powder (or American Chili Powder, Note 3)","1/4 tsp cumin powder","2 tsp sugar","1 garlic (, finely ninced)","1/4 tsp black pepper","1/2 tsp salt"],"purpose":"Cowboy Lime Dressing:"}]', '[{"description":"Shake Dressing in a jar.","images":[],"step":1},{"description":"Place Salad ingredients in a big bowl. Drizzle over Dressing, toss.","images":[],"step":2},{"description":"Serve immediately, or keep for up to 4 days! Might need a squeeze of lime to freshen the flavour.","images":[],"step":3},{"description":"Serve as a light meal or side (goes with everything - beef, fish, prawns, pork, chicken). Especially great with all things Mexican – stuff in / pile on tacos, burritos, enchiladas, nachos, fajitas - and Southern Foods (pulled pork, barbcue ribs, fried chicken!)","images":[],"step":4}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["South Western","Western"],"categories":["all-vegetable-sides","beans-lentils","lentil-recipes","no-cook-food","side-salads","tropical","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b5dbe1cbf8b4', 'en', 'US', 'KFC Potato and Gravy', 'Recipe video above. KFC Potato and Gravy is known for the soft, fluffy yet creamy mashed potato doused with their signature gravy, perfect for dunking in crusty Fried Chicken and fries. Now make it at home! (Except with real ingredients - no potato flakes here!)', 'https://www.recipetineats.com/tachyon/2020/02/KFC-Potato-and-Gravy-featured-image.jpg', 5, 20, 25, 8, '[{"id": "ing_batch_homemade_kfc_gravy", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sebago_russet_maris_piper", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 75.0, "unit": "block of 250g"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_milk", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}]', '[{"ingredients":["1 batch homemade KFC Gravy","1.5kg/ 3lb Sebago (Aus dirt brushed), Russet (US), Maris Piper (UK) ( or other starchy potatoes)","1 tbsp salt (for water)","75g (5 tbsp) unsalted butter, cubed","1/2 cup (125ml) cream (heavy / thickened)","3/4 cup (185ml) milk, full fat","Freshly ground black pepper","Salt to taste"]}]', '[{"description":"Peel and cut potatoes into 3cm / 1.25\" cubes.","images":[],"step":1},{"description":"Place in a pot, add 1 tbsp salt and water so it''s 5cm / 2\" above potatoes.","images":[],"step":2},{"description":"Bring water to a boil, then boil for 15 minutes until potatoes are very soft and starting to fall apart.","duration":15,"images":[],"step":3},{"description":"Drain, leave in colander to steam dry for 3 minutes.","duration":3,"images":[],"step":4},{"description":"Meanwhile, melt butter in a saucepan over medium high heat. Add cream and milk, heat until just before simmer - do not let it boil. Remove from stove.","images":[],"step":5},{"description":"Pass potato through a potato ricer (Note 1) or use a masher with holes. Do not use beater - will make it dense.","images":[],"step":6},{"description":"Add hot milk mixture, 1/2 tsp salt and 1/4 tsp pepper. GENTLY stir until mixed through.","images":[],"step":7},{"description":"Taste for salt and pepper, add more if needed.","images":[],"step":8},{"description":"Transfer into serving bowl. Pour over Gravy and serve immediately with anything and everything!","images":[],"step":9},{"description":"For a KFC at home experience, serve with homemade Fried Chicken (it''s better than KFC!)","images":[],"step":10}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["all-vegetable-sides","potato-recipes","potatoes","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4d80cab85e30', 'en', 'US', 'Cucumber Salad with Herb & Garlic Dressing (Vinaigrette)', 'Recipe video above. Crisp, juicy cucumber and a tasty Herb & Garlic Vinaigrette makes for a sensational salad!! It''s refreshing with extra flavour from the dressing - I can eat SO MUCH of this!! A touch of mustard is key here - thickens the dressing to help it coat the cucumber slices.', 'https://www.recipetineats.com/tachyon/2019/10/Cucumber-Salad-with-Herb-Garlic-Vinaigrette_4.jpg', 10, 0, 10, 5, '[{"id": "ing_cucumber", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_vinegar", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_mustard", "quantity": {"value": 0.013, "unit": "jar of 200g"}}, {"id": "ing_mixed_herbs", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["3 cucumbers (, standard (or 2 long Telegraph/English cucumber(Note 1))","1/2 red onion (, finely diced)"]},{"ingredients":["1 1/2 tbsp red wine vinegar (Note 2)","3 tbsp extra virgin olive oil","1 garlic clove (, minced)","1/2 tsp Dijon mustard","3/4 tsp mixed dried herbs (Note 3 sub)","1/2 tsp white sugar (optional)","1/2 tsp salt and black pepper (, EACH)"],"purpose":"Herb & Garlic Dressing:"}]', '[{"description":"Shake Dressing in a jar.","images":[],"step":1},{"title":"Cucumber","description":"Trim ends then slice about 3 mm/ 1/8\" thick.","images":[],"step":2},{"description":"Place in bowl with red onion.","images":[],"step":3},{"description":"Pour over Dressing, toss gently and serve immediately.","images":[],"step":4}]', '["mustard"]', '["gluten_free","keto_friendly","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["all-vegetable-sides","cucumber","quick-and-easy","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_417c8f72af1a', 'en', 'US', 'Cauliflower Fried Rice', 'Recipe video above. This is how you make cauliflower rice totally delicious - by making Cauliflower Fried Rice! The trick is to cook it hard and fast, just like real fried rice, and to ensure the cauliflower rice are "cooked rice size" rather than blitzed into tiny couscous-size grains. This gives it a real fried rice mouthfeel and eating experience!', 'https://www.recipetineats.com/tachyon/2020/01/Cauliflower-Fried-Rice_4.jpg', 10, 10, 20, 5, '[{"id": "ing_oil", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_bacon", "quantity": {"value": 0.375, "unit": "pack of 200g"}}, {"id": "ing_carrot", "quantity": {"value": 225.0, "unit": "pack of 1kg"}}, {"id": "ing_cauliflower", "quantity": {"value": 400.0, "unit": "unit"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_green_onion", "quantity": {"value": 0.04, "unit": "bunch"}}, {"id": "ing_mirin", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}]', '[{"ingredients":["1.5 tbsp oil (, separated (vegetable, canola, peanut))","3 garlic cloves (, minced)","1/2 onion (, finely chopped)","75g/ 2.5 oz ham or bacon (, diced)","1 1/2 cups frozen diced peas, carrots, corn (mix, or other diced fresh veg of choice)","400g (4 cups) cauliflower rice, raw (Note 1)","2 eggs (, lightly whisked)","2 green onions (, finely sliced)"]},{"ingredients":["1 tbsp Mirin (or Chinese Cooking Wine) (sub dry sherry or cooking sake) (Note 2)","1 tbsp Oyster Sauce (sub Hoisin)","1.5 tbsp soy sauce (, light or all purpose (Note 3))","1 tsp sesame oil (, toasted)"],"purpose":"Sauce – Mix:"}]', '[{"description":"Heat 1 tbsp oil in a large skillet over high heat.","images":[],"step":1},{"description":"Add garlic and onion, cook for 30 seconds.","duration":0.5,"images":[],"step":2},{"description":"Add ham, cook for 1 minute to release flavour.","duration":1,"images":[],"step":3},{"description":"Add frozen vegetables, cook 2 minutes until carrot is almost cooked.","images":[],"step":4},{"description":"Add cauliflower and Sauce. Cook, stirring regularly, for 4 minutes until sauce is reduced and cauliflower is almost cooked - firm, tender crisp, not soft and mushy.","duration":4,"images":[],"step":5},{"description":"Push the cauliflower to one side of the skillet. Add 1/2 tbsp oil, let it heat up briefly, then pour in egg.","images":[],"step":6},{"description":"Leave for 10 seconds, then leisurely scramble it. Once almost cooked, mix egg through cauliflower.","duration":0.16666666666666666,"images":[],"step":7},{"description":"Toss through green onions then serve immediately!","images":[],"step":8}]', '["egg","gluten","peanuts","sesame","soy"]', '["low_calorie"]', '{"mealType":["main_course"],"cuisine":["American Chinese","Asian"],"categories":["all-vegetable-sides","asian-recipes","cauliflower","dietary","fried-rice","low-calorie-recipes","rice-recipes","rice-side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d241e172827f', 'en', 'US', 'Cauliflower Rice', 'Recipe video above. Don''t make this expecting it to taste exactly like rice. It doesn''t - the texture is different, the flavour is different. BUT it''s a tasty, much lower calorie alternative to rice with a neutral flavour that makes it a great healthy option for serving with saucy foods. Once doused with tasty stir fry sauces or curries, you may well forget you''re eating cauliflower. And think of what you can do with all the calorie credits!!! {77% less calories, 87% less carbs than rice}', 'https://www.recipetineats.com/tachyon/2020/01/Cauliflower-Rice_3.jpg', 5, 5, 10, 5, '[{"id": "ing_cauliflower", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["1 head cauliflower (or 500g/1lb store bought prepared cauliflower rice, Note 1)"]}]', '[{"description":"Cut / break cauliflower into florets (including stems) that will fit into the feeding tube of food processor.","images":[],"step":1},{"description":"Fit food processor with grating disc. Place lid on, then push the florets into the feeding tube with the motor running on low.","images":[],"step":2},{"description":"Cauliflower will blitz into rice shaped bits! Can use raw but I prefer cooking it - use a method below.","images":[],"step":3},{"description":"Other grating methods:","images":[],"step":4},{"title":"Food processor standard \"S\" blade","description":"fill halfway with florets, pulse 4 to 5 times until largest bits are the size of cooked rice (half will be couscous size, half rice sized). Repeat as needed.","images":[],"step":5},{"title":"Hand grating","description":"cut whole cauliflower into quarters, then grate by hand.","images":[],"step":6},{"title":"Cooking Method options (6","description":"8 cups rice):","images":[],"step":7},{"description":"Only cook cauliflower rice until it is just cooked - don''t let it go soft and mushy (it gets watery).","images":[],"step":8},{"title":"Roasting","description":"drizzle with 1 tbsp olive oil. Toss, spread on tray, bake at 200°C/390°F for 15 minutes, tossing halfway through cook time.","duration":15,"images":[],"step":9},{"title":"Microwave","description":"place in container with lid with vent open. Microwave 4 to 5 minutes on high until tender crisp. Don''t overcook too soggy.","images":[],"step":10},{"title":"Oven steam","description":"place in covered baking dish, bake 200°C/390°F for 20 minutes.","duration":20,"images":[],"step":11},{"title":"Stove","description":"Heat 1 tbsp olive oil in large skillet over medium high heat. Optional: Cook 2 minced garlic cloves 20 sec until golden. Add rice, cook 4 to 5 minutes, stirring every minute or so, for 5 minutes until just cooked.","duration":5,"images":[],"step":12},{"description":"Serve in place of rice with stir fries, curries, anything saucy that you like serving with rice.","images":[],"step":13},{"description":"Use in place of rice or grains in salads and fried rice.","images":[],"step":14}]', '[]', '["gluten_free","keto_friendly","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["all-vegetable-sides","cauliflower","good-to-know","rice","rice-recipes","rice-side-dishes","side-dishes","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7aab64439291', 'en', 'US', 'Green Bean Salad with Cherry Tomatoes and Feta', 'Recipe video above. This is a great salad to make in big bowls for gatherings! Also ideal to prep ahead for the week - it lasts for days undressed.', 'https://www.recipetineats.com/tachyon/2019/11/Green-Bean-Salad-Cherry-Tomato-Feta_4b.jpg', 10, 5, 15, 8, '[{"id": "ing_green_beans", "quantity": {"value": 453.592, "unit": "pack"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.4, "unit": "punnet of 250g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_feta_cheese", "quantity": {"value": 120.0, "unit": "block of 200g"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.09, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.037, "unit": "jar of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["1 lb / 500g green beans (, trimmed)","350g / 12oz cherry tomatoes (, halved)","1/2 red onion (, finely sliced)","120g / 4oz feta (, crumbled)"]},{"ingredients":["2 tbsp lemon juice (or white wine vinegar)","6 tbsp extra virgin olive oil (adjust to taste)","1 1/2 tsp dijon mustard","1 garlic clove (, minced)","1/2 tsp salt","1/4 tsp black pepper"],"purpose":"Dressing"}]', '[{"description":"Combine the Dressing ingredients in a jar and shake well. Set aside - or refrigerate up to 2 days. Bring to room temperature before using.","images":[],"step":1},{"description":"Cook Beans","images":[],"step":2},{"description":"Bring a large pot of salted water to boil. Add the beans, bring it back up to a boil and simmer for 2 minutes (tender) to 3 minutes (tender).","duration":2,"images":[],"step":3},{"description":"Drain in colander then run under cold tap water to cool (or plunge into bowl of ice water).","images":[],"step":4},{"description":"Drain well then pat dry with clean dish towels.","images":[],"step":5},{"description":"Place beans in a bowl with tomato and onion. Drizzle with dressing, then toss. Garnish with feta. Serve!","images":[],"step":6}]', '["mustard"]', '["gluten_free","keto_friendly","low_calorie","vegan","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Western"],"categories":["all-vegetable-sides","green-beans","quick-and-easy","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4add7eb9c73d', 'en', 'US', 'Savoury Sweet Potato Casserole', 'Recipe video above. A magnificant savoury sweet potato casserole made with creamy mashed sweet potato with swirls of browned butter, topped with a crunchy parmesan panko breadcrumb topping sprinkled with sage and crumbled bacon. Unapologetically indulgent!', 'https://www.recipetineats.com/tachyon/2019/11/Sweet-Potato-Casserole_5.jpg', 20, 135, 155, 10, '[{"id": "ing_sweet_potato", "quantity": {"value": 1.75, "unit": "kg"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.3, "unit": "tub of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 250.0, "unit": "block of 250g"}}, {"id": "ing_sage", "quantity": {"value": 15.0, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 0.141, "unit": "loaf"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_bacon", "quantity": {"value": 0.75, "unit": "pack of 200g"}}]', '[{"ingredients":["1.75kg / 3.5lb sweet potato (3 large or 6 smaller ones)","1/2 cup (115g) sour cream","1/2 cup (50g) parmesan (, freshly grated)","2 garlic cloves (, finely minced)","3/4 tsp salt","1/4 tsp black pepper"],"purpose":"Sweet potato mash:"},{"ingredients":["250g / 8oz butter (, salted, cut into 2cm/1\" cubes)","15 sage leaves (Note 1)"],"purpose":"Browned butter & crispy sage:"},{"ingredients":["3/4 cup panko breadcrumbs (Note 2)","1/2 cup (50g) parmesan (, finely grated)","1/4 tsp each salt and pepper","150g / 5oz bacon (, streaky, cooked until golden then finely chopped)"],"purpose":"Topping:"}]', '[{"description":"Preheat oven to 180°C/350°F.","images":[],"step":1},{"description":"Place potatoes on a foil lined tray. Bake for 1 hour 15 minutes (small) to 1 hour 40 minutes (large) until knife can be easily inserted into the centre.","images":[],"step":2},{"description":"Cool potatoes until they can be handled (but still piping hot inside!) or use tea towel to handle.","images":[],"step":3},{"description":"Browned Butter & crispy sage:","images":[],"step":4},{"description":"Meanwhile, place butter in a large silver saucepan over medium heat.","images":[],"step":5},{"description":"Once melted and starts to foam, add sage leaves. Cook 1 minute or until golden brown, then fish through the foam to find the leaves and drain on paper towels (will crisp when cool).","images":[],"step":6},{"description":"Continue to leave butter on stove until foam dies down and you see black bits on the bottom of the pan (it will smell nutty).","images":[],"step":7},{"title":"Strain through paper towel lined sieve","description":"should have 180ml or so.","images":[],"step":8},{"description":"Crumble sage leaves in your hand (chop if not fully crisp) and place in bowl.","images":[],"step":9},{"description":"Add 1/4 cup Browned Butter, panko, parmesan, garlic, salt and pepper, mix.","images":[],"step":10},{"description":"Cut slits down the middle of the potatoes then scoop flesh out into a bowl.","images":[],"step":11},{"description":"Add 1/4 cup Browned Butter (below), sour cream, parmesan, salt and pepper. Mash or use electric beater to mash until smooth (if using food processor, be careful not to overdo as it will make potato gluey).","images":[],"step":12},{"description":"Assemble & bake:","images":[],"step":13},{"description":"Place half the potato in a baking dish (2 litre / 2 quarts). Make swirls across surface with spoon (as catchment for butter!), then drizzle over 1/4 cup Browned Butter. Cover the butter pools with remaining potato - the less you disturb the butter, the better!","images":[],"step":14},{"description":"Sprinkle over Topping. Bake 25 minutes until top is golden brown and edges are bubbling.","images":[],"step":15},{"description":"Sprinkle with crumbled bacon, then bake a further 5 minutes. If you''ve got any leftover butter, drizzle it on then serve!","images":[],"step":16}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["all-vegetable-sides","potato-recipes","side-dishes","sunday-supper","sweet-potato","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_41af10f2b584', 'en', 'US', 'Green Bean Casserole', 'Recipe video above. The most amazing creamy mushroom sauce smothering tender green beans, topped with crispy fried onions! The perfect green bean casserole with the right ratio of sauce to beans, well flavoured silky, creamy sauce with the perfect thickness and the perfect delicately crunchy onions! See notes for best way to MAKE AHEAD!', 'https://www.recipetineats.com/tachyon/2019/11/Green-Bean-Casserole_Main.jpg', 15, 60, 75, 8, '[{"id": "ing_green_beans", "quantity": {"value": 750.0, "unit": "pack"}}, {"id": "ing_onion", "quantity": {"value": 2000.0, "unit": "pack of 1kg"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 0.037, "unit": "loaf"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.36, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_chicken", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_pinch_nutmeg", "quantity": {"value": 0.003, "unit": "jar"}}]', '[{"ingredients":["750g/ 1.5lb green beans (, trimmed and halved)"]},{"ingredients":["2 large yellow onions (, peeled, halved and thinly sliced (or 3 medium))","1/4 cup (35g) flour (plain/all purpose)","2 tbsp panko breadcrumbs (Note 1)","1/2 tsp salt","1/4 tsp black pepper","4 cups / 1 litre (approx) vegetable oil (, for deep-frying (or peanut, canola oil Note 2))"],"purpose":"Crispy Fried Onions:"},{"ingredients":["3 tbsp (50g) butter (, unsalted)","360g /12 oz mushrooms (, chopped 1cm / 1/3\" pieces)","3/4 tsp salt","1/4 tsp black pepper","2 garlic cloves (, minced)","3 tbsp (35g) flour (plain/all purpose)","1 1/2 cups (375ml) vegetable or chicken broth/stock (, low sodium)","1/2 cup (125ml) cream (, heavy/thickened)","Pinch nutmeg (or sprinkle of freshly grated)"],"purpose":"Creamy Mushroom Sauce:"}]', '[{"description":"Boil the green beans for 3 minutes until just tender (or to your taste), then drain and run under cold tap water (to stop cooking further). You could also steam.","duration":3,"images":[],"step":1},{"description":"Transfer to clean tea towel and pat dry. Set aside.","images":[],"step":2},{"title":"Line tray with 3","description":"4 layers paper towels.","images":[],"step":3},{"description":"Toss onions with flour, panko, salt and pepper.","images":[],"step":4},{"description":"Heat about 2cm / 3/4\" oil in a heavy based skillet over medium high heat. Dip the end of one onion in - it should sizzle satisfyingly immediately.","images":[],"step":5},{"description":"Add some onions, not too many (see video), then fry for 1 1/2 minutes or until LIGHT golden brown.","images":[],"step":6},{"description":"Transfer to tray, spreading out (don''t pile up). (Note 3)","images":[],"step":7},{"description":"Repeat with remaining onion (5-6 batches). Set aside to cool, DO NOT cover.","images":[],"step":8},{"description":"Creamy Mushroom Sauce:","images":[],"step":9},{"description":"Melt butter in a skillet over medium high heat. Add mushrooms and cook for 1 minute.","duration":1,"images":[],"step":10},{"description":"Add salt and pepper, cook until mushroom starts to soften (1.5 minutes) then add garlic and cook for 1 minute until garlic is golden.","duration":1,"images":[],"step":11},{"description":"Turn heat down to medium, add flour and mix until you can''t see flour anymore.","images":[],"step":12},{"description":"While stirring constantly, gradually pour in half the broth. When flour lumps are dissolved, pour in remaining broth and cream, stir.","images":[],"step":13},{"description":"Add nutmeg, stir.","images":[],"step":14},{"description":"Cook for 5 minutes, stirring casually at first then regularly as it thickens, until sauce thickly coats back of wooden spoon and you can draw a path across it (see video). Sauce will not thicken further in oven.","duration":5,"images":[],"step":15},{"description":"Assemble & bake:","images":[],"step":16},{"description":"Preheat oven to 350°F / 180°C (160°C fan).","images":[],"step":17},{"description":"Pour beans into pot they were boiled in (or use bowl). Pour over Mushroom Sauce, stir.","images":[],"step":18},{"description":"Pour into 2.5 quart / 2.5 ltr casserole dish (Note 4), smooth surface.","images":[],"step":19},{"description":"Sprinkle with onions (might not use all!), then bake for 15 minutes until bubbling on the edges and the onions are deep golden. CHECK at 10 minutes to ensure onions are not burning (Note 5).","duration":15,"images":[],"step":20},{"description":"Serve immediately! (See notes for make ahead)","images":[],"step":21}]', '["gluten","milk","peanuts"]', '["low_calorie"]', '{"mealType":["main_course"],"cuisine":["American","Thanksgiving"],"categories":["all-vegetable-sides","casseroles-and-cosy-bakes","green-beans","side-dishes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9dba30436655', 'en', 'US', 'Duck Fat Potatoes - the world''s crispiest, BEST Roast Potatoes!', 'Recipe video above. Duck Fat Potatoes are without a doubt the BEST crispy roast potatoes in the world!! A potato side that''s served in fine dining restaurants, potatoes roasted in duck fat have an incredible thick, golden brown crust that''s unbelievably crunchy in a way that you will never be able to replicate using oil. And it''s a pure, clean flavour that''s unlike cooking with other animal fats.If duck fat is out of reach, make Truly Crunchy Roast Potatoes - same method, but using oil instead. After no-fuss no-par boil roast potatoes? Make these!', 'https://www.recipetineats.com/tachyon/2019/10/Duck-Fat-Potatoes_2.jpg', 15, 75, 90, 6, '[{"id": "ing_potato", "quantity": {"value": 1.75, "unit": "bag of 2kg"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_semolina", "quantity": {"value": 30.0, "unit": "pack"}}, {"id": "ing_duck_fat", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_rosemary", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_chilli_flakes", "quantity": {"value": 0.003, "unit": "jar of 40g"}}]', '[{"ingredients":["1.75-2kg/ 3.5-4lb potatoes (, medium to large, Sebago or Dutch Creams (Aus), Yukon Gold or Russet (US), Maris Piper (UK) (Note 1))","1 tbsp salt","2 tbsp semolina (Note 2)","1.5 tsp salt (, kosher salt)"],"purpose":"Par boiling:"},{"ingredients":["200g/ 7oz Duck Fat (or Goose Fat, Note 3)"],"purpose":"Roasting:"},{"ingredients":["2 tsp rosemary (, roughly chopped)","Sea salt flakes"],"purpose":"Serving, optional:"}]', '[{"description":"Peel the potatoes, then cut into 7.5cm / 3\" pieces (Note 4).","images":[],"step":1},{"description":"Preheat oven to 230°C/450°F (230°C fan).","images":[],"step":2},{"description":"Par Boiling & Roughing up:","images":[],"step":3},{"description":"Add 1 tbsp salt then potatoes in a large pot of boiling water. Boil 10 minutes.","images":[],"step":4},{"description":"Drain potatoes well.","images":[],"step":5},{"description":"Shake excess water out of pot, return turned off stove. Tip potatoes in then stand for 5 minutes to steam out excess water.","duration":5,"images":[],"step":6},{"description":"Add 1.5 tsp salt and the semolina. Place lid on then shake the pot up and down vigorously 5 to 7 times to rough up the surface.","images":[],"step":7},{"description":"Pour duck fat into heavy based metal roasting pan (not glass or ceramic, Note 5).","images":[],"step":8},{"description":"Heat in oven for 5 to 7 minutes until it''s shimmering and very hot with little wisps of smoke (Note 6)","duration":6,"images":[],"step":9},{"description":"Working quickly and carefully, remove pan from oven.","images":[],"step":10},{"description":"Transfer potato in (be CAREFUL!), turn to coat in fat then arrange cut face down.","images":[],"step":11},{"description":"Roast for 25 minutes. Turn potatoes, roast 15 minutes. Turn again, then roast 10 to 15 minutes until deep golden and super crunchy.","duration":25,"images":[],"step":12},{"description":"Transfer to warm serving bowl. Sprinkle with sea salt flakes and rosemary, serve immediately!","images":[],"step":13}]', '[]', '["gluten_free","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["all-vegetable-sides","duck","iconic-dishes","potato-recipes","potatoes","roasts","side-dishes","sunday-supper"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9b61d714f411', 'en', 'US', 'Asian Side Salad', 'Recipe video above. This Asian Side Salad is as versatile as the name suggests - it''s a terrific fresh salad that will pair with any Asian food! From Chinese to Japanese, Thai to Vietnamese, Malaysian, Singaporean, Korean and Taiwanese, it''s right at home alongside fiery Asian curries as it is with a Chinese BBQ Pork, Thai Chicken Satay or Chicken Fried Rice.', 'https://www.recipetineats.com/tachyon/2019/10/Asian-Side-Salad_3.jpg', 10, 0, 10, 4, '[{"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_oil", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_mixed_leafy_salad_greens", "quantity": {"value": 120.0, "unit": "unit"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.75, "unit": "bunch"}}]', '[{"ingredients":["1 tbsp soy sauce (light or all purpose, not dark soy)","3 tbsp peanut oil (or canola, vegetable or other neutral oil)","2 tbsp rice vinegar (sub cider vinegar)","1 tsp sesame oil","1 tsp brown sugar","1 tsp ginger (, minced)","1 clove garlic (, minced)"],"purpose":"Dressing:"},{"ingredients":["120 g / 4oz mixed leafy salad greens","250 g / 8oz cherry tomatoes (, halved)","1/2 red onion (, finely sliced)","1/4 cup crispy fried shallots (Note 1)"],"purpose":"Salad:"}]', '[{"description":"Shake Dressing ingredients in a jar.","images":[],"step":1},{"description":"Place Salad ingredients except fried shallots in a bowl. Drizzle with Dressing and toss.","images":[],"step":2},{"description":"Sprinkle with fried shallots and served immediately!","images":[],"step":3}]', '["gluten","peanuts","sesame","soy"]', '["keto_friendly","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Asian"],"categories":["all-vegetable-sides","asian-recipes","leafy-greens","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3552baa80601', 'en', 'US', 'Rocket Salad with Balsamic Dressing and Shaved Parmesan', 'Recipe video above. A classic side salad that makes an appearance on fine dining restaurants and local bistros! It goes with virtually every Western dish, with the pepper flavour of rocket lettuce making it ideal to pair with rich meat-heavy or carb heavy mains like pastas and roasts.', 'https://www.recipetineats.com/tachyon/2019/09/Rocket-Salad-with-Balsamic-Dressing_1.jpg', 5, 0, 5, 4, '[{"id": "ing_rocket_arugula", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_parmesan", "quantity": {"value": 0.075, "unit": "pack of 200g"}}, {"id": "ing_balsamic_vinegar", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["150g / 5 oz rocket / arugula (4 big handfuls)","15g / 0.5oz parmesan (, shaved finely using vegetable peeler)"]},{"ingredients":["1 tbsp balsamic vinegar","2 1/2 tbsp extra virgin olive oil","1/2 tsp each salt and pepper"],"purpose":"Balsamic Dressing:"}]', '[{"description":"Shake Balsamic Dressing in jar.","images":[],"step":1},{"description":"Place rocket in a bowl, drizzle with Dressing then toss.","images":[],"step":2},{"description":"Transfer to serving bowl. Shave over parmesan. Serve immediately.","images":[],"step":3}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Western"],"categories":["all-vegetable-sides","rocket-arugula","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a3ac7dcbe3f0', 'en', 'US', 'Seasoned Baked Potato Wedges', 'Recipe video above. Crunchy wedges seasoned so they taste like the wedges you can get from the freezer section at the supermarket! I found that the trick to make crunchy wedges is to use the right amount of oil. Too much results in soggy wedges and the seasoning comes off!', 'https://www.recipetineats.com/tachyon/2015/05/Seasoned-Baked-Potato-Wedges_7.jpg', 10, 40, 50, 4, '[{"id": "ing_potato", "quantity": {"value": 2.0, "unit": "bag of 2kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_paprika", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_sweet_chili_sauce", "quantity": {"value": 1.0, "unit": "bottle of 375ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["2 lb / 1 kg potatoes (, peeled (4 large ones) (Note 1))","3 tbsp olive oil"]},{"ingredients":["1 1/2 tsp paprika","1 tsp garlic powder","1/2 tsp onion powder (or sub with more garlic powder)","1 tsp salt","1/2 tsp pepper"],"purpose":"Seasoning"},{"ingredients":["Sour cream and","Sweet chili sauce","Other options: Ketchup, tomato sauce, aioli, mayo, yogurt, BBQ sauce, relish","Avocado Dipping Sauce"],"purpose":"To serve (optional – but highly recommended for optimal experience!)"}]', '[{"description":"Preheat oven to 220°C/430°F (200°C/390°F fan/convection)","images":[],"step":1},{"description":"Mix the Seasoning ingredients.","images":[],"step":2},{"description":"Cut the potatoes in half lengthwise, then cut each half into 4 \"wedges\" (so you get 8 pieces from each potato). If your potato is small/medium, just cut into 6 wedges.","images":[],"step":3},{"description":"Place potatoes in a large bowl, drizzle over oil and seasoning. Toss with hands.","images":[],"step":4},{"description":"Spread out on tray, ensuring cut side lies flat on the tray.","images":[],"step":5},{"description":"Bake for 35 to 45 minutes, turning once, or until dark golden brown and crispy.","duration":40,"images":[],"step":6},{"description":"Serve immediately!","images":[],"step":7},{"title":"Dipping sauces","description":"Classic Aussie way is with sour cream and sweet chilli sauce. Otherwise, try tomato sauce/ketchup, BBQ sauce, yogurt, ranch, aoli.","images":[],"step":8}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["snack"],"cuisine":["Western"],"categories":["all-vegetable-sides","australia-day","dietary","easter-sides-warm-hearty","gluten-free-recipes","most-popular","potato-recipes","potatoes","quick-and-easy","side-dishes","super-bowl-party-food","vegan-lifestyle"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_312d46a7d63f', 'en', 'US', 'How to make Grilled Corn', 'Recipe video above. The most effortless vegetable side dish for a BBQ....There''s nothing quite like biting in a juicy corn on the cob with melted butter dripping down your hands! SCALE recipe using slider.', 'https://www.recipetineats.com/tachyon/2019/07/Grilled-Corn_0.jpg', 2, 10, 12, 4, '[{"id": "ing_corn", "quantity": {"value": 4.0, "unit": "can of 400g"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["4 whole corn on the cob","2 tbsp/ 30g melted butter (, salted)"]},{"ingredients":["Softened butter (, salted (not optional))","Finely chopped parsley (optional)"],"purpose":"Serving:"}]', '[{"description":"Preheat BBQ (grill side) until very hot.","images":[],"step":1},{"description":"Peel husk off the corn.","images":[],"step":2},{"description":"Place corn on the BBQ (no oil required).","images":[],"step":3},{"description":"Cook for 10 minutes, turning every couple of minutes, until there''s little charred bits and the kernels are tender when pierced with a knife, but still JUICY! Overcooked corn is shrivelled, dry and sad.","duration":10,"images":[],"step":4},{"description":"In the last minute, brush with melted butter and roll around.","images":[],"step":5},{"description":"Serve corn with softened butter, sprinkled with parsley if desired!","images":[],"step":6}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["all-vegetable-sides","corn","tropical","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_07d01567d118', 'en', 'US', 'Creamy Mashed Cauliflower', 'Recipe VIDEO above. So tasty in its own right, you won''t just make it as a low carb alternative to mashed potato! See Note 1 for SUBS & alternatives!', 'https://www.recipetineats.com/tachyon/2019/05/Cauliflower-Mash_7.jpg', 15, 10, 25, 6, '[{"id": "ing_cauliflower", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.15, "unit": "tub of 250g"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1 kg / 2lb cauliflower florets (Note 1)","2 garlic cloves (, peeled, whole)","2 tbsp (30g) unsalted butter","1/4 cup (25g) parmesan cheese (, shredded)","1/4 cup (55g) sour cream (, optional)","1 - 3 tbsp cooking water","Salt and pepper (, to taste)"]},{"ingredients":["Melted butter, parsley, pepper"],"purpose":"Garnishes (optional):"}]', '[{"description":"Cut the larger florets in half or quarter so they''re all about the same size.","images":[],"step":1},{"description":"Add cauliflower and garlic into a large pot of boiling water and cook for 10 minutes until very soft.","duration":10,"images":[],"step":2},{"description":"Scoop out a mug of cooking water.","images":[],"step":3},{"description":"Drain well, then transfer to food processor.","images":[],"step":4},{"description":"Add remaining ingredients, starting with no water, blitz until smooth. (Use handheld blender stick if you don''t have food processor)","images":[],"step":5},{"description":"Use reserved cooking water to adjust consistency to taste and help puree smooth.","images":[],"step":6},{"description":"Adjust salt and pepper to taste","images":[],"step":7},{"description":"Transfer to serving bowl, drizzle with melted butter and garnish with parsley if desired.","images":[],"step":8},{"description":"Serve as a side with anything that you''d usually serve with mashed potato!","images":[],"step":9}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["all-vegetable-sides","cauliflower","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_51478c6640a5', 'en', 'US', 'Magic Broccoli (Best roasted broccoli recipe ever!)', 'Recipe video above. This is insanely simple to make but it''s the best broccoli ever! I call it "Magic Broccoli" because it IS magic how a little roasting and a drizzle of lemon juice and parmesan can transform broccoli!', 'https://www.recipetineats.com/tachyon/2014/09/Magic-Broccoli_2.jpg', 10, 25, 35, 4, '[{"id": "ing_broccoli", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.15, "unit": "pack of 200g"}}]', '[{"ingredients":["2 medium to large heads of broccoli (, about 1 kg / 2 lb)","2 garlic cloves (, finely sliced or minced)","2 1/2 tbsp extra virgin olive oil","1/2 tsp salt (adjust to your taste)","Black pepper","Zest of half a lemon","1 tbsp lemon juice","2 tbsp freshly grated parmesan cheese (, plus more for garnish)"]}]', '[{"description":"Preheat oven to 220°C/425°F (200°C fan).","images":[],"step":1},{"description":"Cut/break broccoli into florets and pile onto baking tray. (Note 2 re: stem)","images":[],"step":2},{"title":"Toss","description":"Drizzle all over with extra virgin olive oil, scatter with garlic, salt and pepper. Toss with fingers or tongs, then spread out over tray in a single layer (or toss in large bowl or ziplock bag).","images":[],"step":3},{"description":"Roast for 20 to 25 minutes until the tips of the florets are slightly browned and crispy. The broccoli should be \"tender crisp\", meaning just cooked through, not soft and floppy.","duration":22.5,"images":[],"step":4},{"title":"Finish","description":"Remove from the oven and immediately drizzle over the lemon juice, zest, and parmesan. Toss quickly, transfer to serving plate and garnish with a bit more parmesan. Serve warm!","images":[],"step":5}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["all-vegetable-sides","broccoli","broccoli-recipes","easter-sides-warm-hearty","most-popular","quick-and-easy","side-dishes","side-salads","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_55a649b406ed', 'en', 'US', 'Caprese Salad', 'A summer staple! The thing that sets this Caprese Salad apart from the usual is that it''s tossed with a garlic-herb vinaigrette first then finished with a balsamic glaze. Keeps it looking "clean" with terrific flavour! Serve as a side, on toast with avocado or as a light meal with bread.', 'https://www.recipetineats.com/tachyon/2019/01/Caprese-Salad_8.jpg', 15, 0, 15, 6, '[{"id": "ing_mozzarella", "quantity": {"value": 1.76, "unit": "pack of 125g"}}, {"id": "ing_tomato", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_basil", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_balsamic_glaze_reduction", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_mustard", "quantity": {"value": 0.013, "unit": "jar of 200g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_vinegar", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.025, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["220 g/7oz bocconcini / baby or cherry mozzarella (, halved (Note 1))","500 g / 1 lb cherry or grape tomatoes (, halved)","1/2 cup basil leaves (, torn or roughly chopped)","Balsamic glaze / reduction (, for drizzling (Note 2))"]},{"ingredients":["1 small garlic clove (, minced)","1/2 tsp Dijon mustard (or other non spicy mustard)","2.5 tbsp extra virgin olive oil","1 tbsp white wine vinegar (Note 3)","1/4 tsp each dried oregano (, parsley, thyme (or rosemary))","1/2 tsp salt","Black pepper"],"purpose":"Caprese Salad Dressing:"}]', '[{"description":"Place Dressing ingredients in a jar and shake very well. Adjust to taste.","images":[],"step":1},{"description":"Place tomatoes, bocconcini and most of the basil in a bowl. Drizzle over dressing, toss gently.","images":[],"step":2},{"description":"Transfer to shallow serving bowl. Just before serving, drizzle with balsamic glaze and sprinkle with remaining basil.","images":[],"step":3},{"description":"Serve immediately.","images":[],"step":4}]', '["milk","mustard"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["all-vegetable-sides","italian-recipes","quick-and-easy","salad-recipes-main-course","side-salads","tomato"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_65f776f64a03', 'en', 'US', 'Paris Mash (Rich & Creamy Mashed Potato)', 'Recipe video above. This is mashed potato as served at top tier restaurants. It''s soft and almost pourable, intensely buttery and has a more pure potato flavour. Restaurants double pass the potato through a mill then a fine sieve so it''s 100% lump free. For this home version, I simply pass the potato through a ricer OR mash it. Nobody notices the imperfections because they''re too focussed on the amazing flavour and the creamy yet fluffy texture!', 'https://www.recipetineats.com/tachyon/2018/12/Paris-Mash_Creamy-Mashed-Potato_1.jpg', 15, 45, 60, 6, '[{"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_butter", "quantity": {"value": 150.0, "unit": "block of 250g"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 150.0, "unit": "block of 250g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 kg / 2 lb Dutch Cream, Desiree, Yukon Gold or Maris Piper potatoes (Note 1)","150 - 200 g / 5 - 7 oz cold unsalted butter (, cut into 1.5cm / 1/2\" cubes (Note 2))","1/2 - 3/4 cup (125 - 185ml) milk (, warmed (Note 3))","Salt"]},{"ingredients":["Softened butter","Finely chopped parsley"],"purpose":"Garnish:"}]', '[{"description":"Scrub potatoes clean.","images":[],"step":1},{"description":"Place potatoes in a large pot and cover with cold water. Bring to the boil then reduce heat and simmer for 30 to 40 minutes until the potatoes are very soft (depends on size).","duration":35,"images":[],"step":2},{"description":"Alternatively, peel then chop into 2.5cm / 1\" cubes (Note 4), cook 12 to 15 minutes until soft.","images":[],"step":3},{"description":"Drain potatoes and return empty pot to stove.","images":[],"step":4},{"description":"Using tea towels to handle the hot potatoes, peel them using a small knife (skin should slide off pretty easily).","images":[],"step":5},{"title":"Mash the potatoes using one of these methods","description":"Press them through a potato ricer or a food mill / grinder fitted with the finest disc, or mash in the pot using a potato masher (preferably with round holes, yields a similar result to potato ricer).","images":[],"step":6},{"title":"Pro step","description":"Then pass the potato through a drum sieve for 100% smooth mashed potato, like you get at restaurants. I do not do this (read in post)","images":[],"step":7},{"description":"Turn stove on low and stir mashed potato for 1 minute (evaporate excess water).","duration":1,"images":[],"step":8},{"description":"Add a few cubes of butter and a little splash of milk. Stir until butter melts and is incorporated.","images":[],"step":9},{"description":"Repeat until all butter is used up, using milk to adjust the consistency to your desired taste towards the end. It should be soft and creamy, almost pourable.","images":[],"step":10},{"description":"Season to taste with salt.","images":[],"step":11},{"description":"Pour into serving bowl. Use a spoon to create swirls on the surface, top with small dollop of butter and a tiny sprinkle of parsley. Serve immediately!","images":[],"step":12}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["all-vegetable-sides","easter-sides-warm-hearty","iconic-dishes","potato-recipes","potatoes","side-dishes","sunday-supper"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2ce5a534f18d', 'en', 'US', 'Garlic Sautéed Spinach', 'A super quick side that''s good for you and tastes fabulous. It always amazes me how much spinach wilts - so this is a great way to consume ALOT of good nutrition with just a few bites! A terrific side for meaty mains. Try a classic steakhouse dinner with Prime Rib or steak, Paris Mash and this Sautéed Spinach!', 'https://www.recipetineats.com/tachyon/2018/12/Spinach_Garlic-Sauteed_0.jpg', 5, 4, 9, 2, '[{"id": "ing_spinach", "quantity": {"value": 2.0, "unit": "bag of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["2 bunches spinach (Note 1)","1 tbsp olive oil","2 garlic cloves (, finely chopped)","Salt and pepper"]}]', '[{"description":"Trim the stem from the leaves, then wash the leaves very well (spinach often holds a lot of dirt).","images":[],"step":1},{"description":"Shake off excess water but do not dry (water droplets helps steam-cook the spinach).","images":[],"step":2},{"description":"Heat oil in a large skillet over medium high heat. Add garlic and cook for 20 seconds until it becomes light golden and smells amazing.","duration":0.3333333333333333,"images":[],"step":3},{"description":"Add spinach, then use tongs or 2 wooden spoons to toss until the spinach wilts - about 2 minutes. I like mine just wilted.","images":[],"step":4},{"description":"Remove from heat immediately and sprinkle with salt and pepper and toss once more.","images":[],"step":5},{"description":"Transfer to serving platter and serve.","images":[],"step":6}]', '[]', '["gluten_free","keto_friendly","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["all-vegetable-sides","easter-sides-warm-hearty","side-dishes","spinach"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_de2d198f4652', 'en', 'US', 'Parmesan Roasted Green Beans', 'Recipe video above. The most amazing SUPER SPEEDY way to prepare fresh green beans!! Tender crisp garlic green beans with terrific crunch from breadcrumbs and savoury from parmesan. Be prepared to fight over the little parmesan wafers - the are the gold nuggets!!', 'https://www.recipetineats.com/tachyon/2018/11/Parmesan-Roasted-Green-Beans_9a.jpg', 5, 15, 20, 4, '[{"id": "ing_green_beans", "quantity": {"value": 500.0, "unit": "pack"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 0.062, "unit": "loaf"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}]', '[{"ingredients":["500 g / 1 lb green beans (, ends trimmed)","2 tbsp olive oil (, separated)","2 garlic cloves (, finely chopped)","1/2 tsp each salt and pepper","1/3 cup panko breadcrumbs (Note 1)","1/3 cup grated parmesan (Note 2)"]}]', '[{"description":"Preheat oven to 220C/425F OR the broiler/grill on high with the shelf about 30cm/12\" from the heat source.","images":[],"step":1},{"description":"Pile beans on a tray. Drizzle with 1 tbsp of the oil, garlic, salt and pepper. Toss.","images":[],"step":2},{"description":"Line up on the tray, pushing the beans next to each other (I do 2 rows).","images":[],"step":3},{"description":"Sprinkle with breadcrumbs then parmesan. Drizzle with remaining oil.","images":[],"step":4},{"description":"Roast for 15 minutes or broil/grill for 8 minutes until the parmesan is golden.","duration":15,"images":[],"step":5},{"description":"Use a spatula/egg flip to transfer beans to serving platter. Serve immediately!","images":[],"step":6}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["all-vegetable-sides","easter-sides-warm-hearty","green-beans","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5049d8a705dc', 'en', 'US', 'Brown Sugar Glazed Carrots', 'Recipe video above. The most amazing quick and easy roasted carrots! Roasting brings out the best in carrots, always. And the caramelised edges are the BEST - it''s the only way I make Glazed Carrots!', 'https://www.recipetineats.com/tachyon/2018/11/Brown-Sugar-Roast-Carrots_3.jpg', 10, 25, 35, 5, '[{"id": "ing_carrot", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 kg / 2 lb carrots (, peeled (Note 1))","1/4 cup (40g) brown sugar (, loosely packed (Note 2))","2 garlic cloves (, minced)","2 tbsp butter (30g) (, melted (or olive oil))","1 tbsp olive oil","½ tsp salt","¼ tsp black pepper","Parsley (, for garnish (optional))"]}]', '[{"description":"Preheat oven to 220C/425F (standard) or 200C/400F (fan).","images":[],"step":1},{"description":"Cut carrot on the diagonal into 4cm / 1.75” lengths. Halve thicker end so they are all roughly the same width.","images":[],"step":2},{"description":"Toss in a bowl with sugar, butter, garlic, oil, salt and pepper. Pour onto tray, spread out.","images":[],"step":3},{"description":"Roast 15 minutes. Toss, then roast a further 10 minutes until soft and caramelised on the edges with plenty of glaze left on the tray.","images":[],"step":4},{"description":"Toss carrots in the glaze, sprinkle with parsley if using. Serve warm.","images":[],"step":5}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["all-vegetable-sides","carrots","easter-sides-warm-hearty","quick-and-easy","sunday-supper","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_812146ae9bd5', 'en', 'US', 'Healthier Creamy Yogurt Salad Dressings', 'Recipe video above. Here''s 5 very, very good creamy dressings made with yogurt instead of mayonnaise. All the flavour of their traditional mayo-based counterparts, but less fat and better for you! You might ditch that jar of mayo for good!', 'https://www.recipetineats.com/tachyon/2018/10/SouthWest-Salad-with-Greek-Yogurt-Ranch-Dressing.jpg', 10, 0, 10, 1, '[{"id": "ing_yogurt", "quantity": {"value": 0.15, "unit": "tub of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.075, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.013, "unit": "jar of 200g"}}, {"id": "ing_mustard", "quantity": {"value": 0.013, "unit": "jar of 200g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_chives", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_honey", "quantity": {"value": 0.06, "unit": "jar of 500g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}]', '[{"ingredients":["1/2 cup plain yogurt (, preferably Greek)","1/4 cup extra virgin olive oil","2 1/2 tbsp lemon juice","1 tsp garlic (, minced)","1 1/2 tsp sugar","1/4 tsp black pepper","1/2 tsp salt"],"purpose":"Creamy Lemon Yogurt Salad Dressing:"},{"ingredients":["1 cup plain yogurt (, preferably Greek)","2 tbsp olive oil","1 small garlic clove (, minced)","1/4 tsp EACH dried dill, parsley, chives, garlic powder, black pepper","1/2 tsp EACH onion powder, mustard powder","1/2 tsp salt","2 tsp white sugar","1 1/2 tbsp lemon juice"],"purpose":"Yogurt Ranch Dressing:"},{"ingredients":["1 cup plain yogurt (, preferably Greek)","3 tbsp olive oil","2 tbsp milk","2 tbsp wholegrain mustard","1 tbsp dijon mustard","1 tbsp vinegar","2 tsp white sugar","1/4 cup fresh chives (, finely chopped)","1/2 tsp garlic powder, onion powder"],"purpose":"Yogurt Potato Salad Dressing:"},{"ingredients":["1/2 cup plain yogurt (, preferably Greek)","2 tbsp Dijon mustard","2 tbsp honey","1 1/2 tbsp cider vinegar","1/4 tsp EACH garlic powder, salt and pepper"],"purpose":"Oil-Free Honey Mustard Dressing:"},{"ingredients":["1 cup plain yogurt (, preferably Greek)","1/2 garlic clove (, minced)","2 anchovy fillets or 3/4 tsp Anchovy paste (Note 2)","1 tbsp fresh lemon juice","1 tsp Dijon mustard","1 tsp Worcestershire sauce","1 tsp white sugar","2 tbsp olive oil","1/2 cup freshly grated parmesan cheese","2 - 4 tbsp milk (adjust consistency)","1/2 tsp salt","Black pepper"],"purpose":"Yogurt Caesar Salad Dressing:"}]', '[{"description":"All Dressings except Caesar:","images":[],"step":1},{"description":"Mix ingredients in a bowl. Set aside for 30 minutes+ to allow flavours to develop.","duration":30,"images":[],"step":2},{"description":"Use milk to adjust to desired consistency.","images":[],"step":3},{"description":"Caesar Salad Dressing:","images":[],"step":4},{"description":"Blitz in a food processor until smooth. Use milk to adjust consistency.","images":[],"step":5}]', '["fish","milk","mustard"]', '["gluten_free"]', '{"mealType":["lunch"],"cuisine":[],"categories":["all-vegetable-sides","dressings","easter-sides-fresh-light","quick-and-easy","salad-dressings","side-salads","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6cd94dc76a0e', 'en', 'US', 'Apple Salad with Candied Walnuts and Cranberries', 'Recipe video above. A terrific bright, fresh salad with a great combination of flavours and textures. The candied nuts and plumping the cranberries is optional - but don''t skip it if you''re making this for company! The dressing is best kept simple to let the ingredients in the salad take centre stage. Makes more candied nuts than you need but I find it hard to make a smaller batch.', 'https://www.recipetineats.com/tachyon/2018/10/Apple-Salad-with-Candied-Walnuts-Cranberries_3-2.jpg', 15, 5, 20, 5, '[{"id": "ing_apples", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_mixed_salad_leaves", "quantity": {"value": 120.0, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_cranberries", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_walnuts", "quantity": {"value": 150.0, "unit": "jar"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.037, "unit": "jar of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["1 red apple (, quartered, seeds remove, finely sliced)","Squeeze of lemon juice (to stop apple browning)","120 g/4 oz mixed salad leaves (4 to 5 big handfuls)","1/2 red onion (, finely sliced (wedge way, not half moon))","3/4 cup dried cranberries","2 tbsp feta or goats cheese (, crumbled (garnish, optional))"]},{"ingredients":["1 tbsp butter (, salted)","1/4 cup white sugar","1 cup walnuts or pecans"],"purpose":"Candied Walnuts (or other nuts):"},{"ingredients":["2 tbsp cider vinegar","4 tbsp olive oil","1.5 tsp Dijon mustard","1.5 tsp white sugar","1/2 tsp salt","1/4 tsp pepper"],"purpose":"Dressing:"}]', '[{"description":"Place butter in a small non stick skillet over medium heat. When melted, add sugar. Stir briefly, then leave until the sugar mostly melts.","images":[],"step":1},{"description":"When it starts bubbling a bit, add nuts.","images":[],"step":2},{"description":"Stir 2 minutes. Pour out on parchment paper lined tray.","images":[],"step":3},{"description":"Spread nuts out, allow to cool. Roughly chop half, leave some whole.","images":[],"step":4},{"description":"Plump Cranberries:","images":[],"step":5},{"description":"Place in a bowl, pour over freshly boiled water. Leave to soak 10 minutes then drain.","images":[],"step":6},{"description":"Drizzle with lemon juice and toss (stops apple from browning).","images":[],"step":7},{"description":"Place Dressing ingredients in a jar and shake well. Adjust to taste - more oil to make it creamier, sugar for sweet, vinegar for tart.","images":[],"step":8},{"description":"Place salad in a large bowl with half the apple slices and all the onion. Drizzle with half the dressing then toss.","images":[],"step":9},{"description":"Scatter over the cranberries, desired amount of walnuts, remaining apple slices and feta. Drizzle with remaining dressing. Serve immediately!","images":[],"step":10}]', '["milk","mustard"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Western"],"categories":["all-vegetable-sides","dinner-tonight","easter-brunch-recipes","easter-sides-fresh-light","leafy-greens","quick-and-easy","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6dae03ba2561', 'en', 'US', 'Greek Lemon Potatoes', 'Recipe video above. The idea behind this recipe is that the potatoes suck up the amazing lemon-garlic-oregano flavoured broth, then roasted until golden crispy edges. These won''t go super crunchy because of the way they''re cooked - but you won''t miss the crunch because they have flavour unlike any other ordinary roasted potato! If crunch is what you''re after, try these recipes: Duck Fat Potatoes, or Truly Crunchy Roast Potatoes.', 'https://www.recipetineats.com/tachyon/2018/09/Greek-Lemon-Potatoes_1.jpg', 10, 70, 80, 5, '[{"id": "ing_potato", "quantity": {"value": 1.2, "unit": "bag of 2kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.1, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["1.2 kg / 2.5lb potatoes (Aus: Desiree, US: Yukon Gold, UK: Maris Piper) (Note 1)","1 1/2 cups chicken stock/broth (, low sodium (Note 2))","1/2 cup olive oil","1/3 cup lemon juice","5 garlic cloves (, finely grated using microplane (Note 3))","1 tbsp dried oregano","2 tsp salt (Note 4)"]},{"ingredients":["Lemon wedges, fresh oregano leaves"],"purpose":"Garnish (optional)"}]', '[{"description":"Preheat oven to 200°C/390°F (180°Cfan).","images":[],"step":1},{"title":"Cut potatoes","description":"Peel potatoes and cut large ones into thick wedges - about 3cm / 1.2\" thick - and medium ones into 3 (see photo in post).","images":[],"step":2},{"title":"Coat potatoes","description":"Place potatoes in a roasting pan with all the other ingredients. Toss well.","images":[],"step":3},{"title":"Roast 45 minutes","description":"Roast for 20 minutes. Turn potatoes, roast for a further 25 to 30 minutes until the liquid is mostly absorbed by potatoes/evaporated and you''re left with mainly oil in the pan.","duration":20,"images":[],"step":4},{"title":"To crisp the potatoes (optional)","description":"Transfer potatoes to a separate tray. (Note 3) Tilt the original roasting pan and scoop off as much of the oil as you can (some juices is ok), then drizzle over the potatoes.","images":[],"step":5},{"title":"Roast 35 minutes","description":"Transfer potatoes to oven and roast for 35 - 40 minutes, turning once or twice, until potatoes are golden and a bit crispy on the edges.","duration":37.5,"images":[],"step":6},{"title":"Heat pan juices","description":"Return pan #1 with the garlic juices to the oven for the last 5 - 10 minutes or so to reduce down and make the garlic golden. (Optional, Note 4)","images":[],"step":7},{"title":"Plate up","description":"Transfer potatoes to serving platter. Drizzle over the reduced garlic pan juices (or toss potatoes in the pan). Serve, garnished with lemon wedges and oregano if desired.","images":[],"step":8}]', '[]', '["gluten_free","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Greek"],"categories":["all-vegetable-sides","easter-sides-warm-hearty","greek-recipes","mediterranean-recipes","potato-recipes","potatoes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d9ce6d18dfe0', 'en', 'US', 'Indian Salad with Tomato and Mint Dressing', 'An ideal refreshing salad to serve on the side of rich spicy curries! The dressing here is simply Raita, a mint yoghurt sauce often served on the side of curries.', 'https://www.recipetineats.com/tachyon/2018/08/Indian-Salad-Tomato-with-Mint-Dressing_2.jpg', 10, 0, 10, 4, '[{"id": "ing_tomato", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.25, "unit": "pack of 1kg"}}, {"id": "ing_garam_marsala", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_yogurt", "quantity": {"value": 0.3, "unit": "tub of 500g"}}, {"id": "ing_mint", "quantity": {"value": 1.2, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.015, "unit": "L"}}]', '[{"ingredients":["3 large ripe tomatoes, (, sliced into rounds)","1/4 red onion (, very thinly sliced)","1 pinch of garam marsala (, to taste (optional))"],"purpose":"Salad:"},{"ingredients":["1 cup / 250g plain yoghurt","2 cups mint leaves","1 tbsp lemon juice (, or to taste)","Couple of pinches of salt","1 tbsp+ water"],"purpose":"Raita Mint Dressing:"}]', '[{"description":"Blitz ingredients in a food processor until it becomes a smooth, bright green sauce.","images":[],"step":1},{"description":"Use extra water to thin to a pourable consistency.","images":[],"step":2},{"description":"Put the tomatoes in a bowl. Sprinkle with pinch of salt, mix with your hands and leave to rest for 10 minutes (extracts a bit of juice, makes them juicier).","duration":10,"images":[],"step":3},{"description":"Drain the tomatoes. Mix with the onion in a serving bowl.","images":[],"step":4},{"description":"Drizzle dressing over the tomato salad.","images":[],"step":5},{"description":"Sprinkle with a pinch of garam marsala if desired.","images":[],"step":6}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Indian"],"categories":["all-vegetable-sides","indian-recipes","quick-and-easy","side-salads","tomato"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c758d4cecfd7', 'en', 'US', 'Lemon Potato Salad', 'Recipe video above. You don''t need mayo to make a terrific potato salad! The secret is to marinate the potatoes so they suck up all that flavour!', 'https://www.recipetineats.com/tachyon/2018/08/Lemon-Potato-Salad_9.jpg', 10, 10, 20, 5, '[{"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_salt", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.075, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.075, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.075, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["1 kg / 2 lb baby potatoes (Note 1)","2 tbsp salt (for water)","1 cup green onions (, sliced)","1/4 cup parsley (, finely chopped)"]},{"ingredients":["5 tbsp / 75 ml extra virgin olive oil","1/4 cup / 65 ml lemon juice","1 tbsp lemon zest (1 large lemon)","1 garlic clove, large, minced","1 tsp Dijon mustard","1.5 tsp sugar","3/4 tsp salt","1/2 tsp black pepper"],"purpose":"Dressing:"}]', '[{"title":"Dressing","description":"Shake in a jar.","images":[],"step":1},{"description":"Halve so they are about 2.5cm / 1\" pieces (cut large ones into 3).","images":[],"step":2},{"description":"Bring 4 litres / 4 quarts water to the boil, add salt. Add potatoes, bring back up to the boil then reduce to simmer. Cook for 5 minutes or until just cooked - don''t let them overcook or become too soft, they will keep cooking from residual heat.","duration":5,"images":[],"step":3},{"description":"Drain and immediately transfer to a bowl.","images":[],"step":4},{"description":"While potatoes are hot, pour over half the Dressing. Use rubber spatular to gently stir.","images":[],"step":5},{"description":"Set aside to marinate for at least 30 minutes, even overnight.","images":[],"step":6},{"description":"Add green onions and parsley, pour over remaining Dressing. Carefully toss with rubber spatular, then serve. Great warm or at room temperature, and it''s also great the next day.","images":[],"step":7}]', '["mustard"]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["all-vegetable-sides","easter-brunch-recipes","easter-sides-fresh-light","easter-sides-warm-hearty","potato-recipes","potatoes","quick-and-easy","side-salads","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b75cdf2c8296', 'en', 'US', 'Everyday Cabbage Salad', 'Goes with practically anything. Think of it like Coleslaw - minus the mayo dressing. Great with light foods like seafood, and refreshing with hearty foods like stews and roasts. Chop the cabbage and keep in the fridge with the dressing in a jar, lasts for up to a week! Use just cabbage, and any colours you please. Can''t-Stop-Eating-It-Delicious!', 'https://www.recipetineats.com/tachyon/2018/07/Everyday-Cabbage-Salad_8.jpg', 10, 0, 10, 4, '[{"id": "ing_cabbage", "quantity": {"value": 15.0, "unit": "head"}}, {"id": "ing_red_cabbage", "quantity": {"value": 6.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 150.0, "unit": "pack of 1kg"}}, {"id": "ing_vinegar", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_sugar", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}]', '[{"ingredients":["5 cups shredded green cabbage","2 cups shredded red cabbage (or more green)","1 cup shredded carrot (or more cabbage)"],"purpose":"Salad:"},{"ingredients":["1/4 cup cidar vinegar","2 tbsp oil (vegetable or canola, or light olive oil)","1 1/2 - 2 tbsp white sugar (adjust to taste)","1 tsp dijon mustard","1/2 tsp salt"],"purpose":"Dressing:"}]', '[{"description":"Shake Dressing ingredients in a jar. Start with 1 1/2 tbsp sugar and adjust to taste.","images":[],"step":1},{"description":"Place Salad ingredients in a large bowl. Pour over Dressing, toss. Set aside 20 minutes - mound will reduce by almost half and become juicy! Serve.","images":[],"step":2}]', '["mustard"]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["all-vegetable-sides","cabbage","quick-and-easy","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_36ed866179cd', 'en', 'US', 'Broccoli Salad with Lighter Creamy Dressing', 'RECIPE VIDEO ABOVE. Slicing the florets creates a larger surface area so the dressing tenderises the broccoli more effectively, so the broccoli is tender crisp rather than a harsh, raw bite. I also like to have plenty of dressing because dressing soaked florets is my favourite part, so rather than a mayo only dressing, I opt to make more of a lighter dressing with less mayo that''s pourable and coats every piece of broccoli thoroughly. Less oil, more dressing, more flavourings!', 'https://www.recipetineats.com/tachyon/2018/07/Broccoli-Salad-with-Lighter-Mayo-Dressing_3.jpg', 15, 0, 15, 6, '[{"id": "ing_broccoli", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 0.75, "unit": "pack of 200g"}}, {"id": "ing_cranberries", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_almonds", "quantity": {"value": 0.3, "unit": "pack of 250g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.188, "unit": "jar of 400g"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.225, "unit": "tub of 500g"}}, {"id": "ing_milk", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.075, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_dill", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["500 g/1 lb broccoli florets (2 large heads, 22cm/9\" diameter)","150 g/5oz bacon (, chopped then cooked until golden)","3/4 cup dried cranberries (or raisins, sultanas or blueberries)","1/2 cup almond slivers","1/2 red onion (, finely sliced)"],"purpose":"Broccoli Salad:"},{"ingredients":["1/2 cup mayonnaise","3/4 cup Greek yoghurt or sour cream","1/4 cup / 65ml milk (, low fat)","1/4 cup / 65ml lemon juice (or cider vinegar)","2 garlic cloves (, minced)","1 tsp each onion powder (, garlic powder, mustard powder)","1 tbsp sugar","1 1/2 tsp dried dill","1 tsp dried parsley","1 tsp salt","1/4 tsp finely ground pepper"],"purpose":"Dressing:"}]', '[{"description":"Cut the florets into slices no thicker than 0.7 cm / 1/4\" thick.","images":[],"step":1},{"description":"Place in a bowl with remaining Salad ingredients.","images":[],"step":2},{"title":"Mix Dressing well in a large bowl","description":"use a whisk to ensure it''s all well incorporated. It will be thin and pourable - see video for consistency.","images":[],"step":3},{"description":"Pour all over Salad, toss well.","images":[],"step":4},{"description":"Cover and refrigerate overnight (minimum 2 hours). Remove from fridge and bring to room temperature before serving.","images":[],"step":5}]', '["milk","mustard","nuts"]', '["gluten_free","low_calorie"]', '{"mealType":["main_course"],"cuisine":[],"categories":["all-vegetable-sides","broccoli","broccoli-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1b7bb2d5e14c', 'en', 'US', 'Creamy Broccoli Casserole', 'RECIPE VIDEO ABOVE. This is the broccolli version of Cauliflower Cheese! Tender broccoli smothered in a creamy garlic-parmesan cheese sauce which is pretty much the one I use for everybody''s favoure Mac and Cheese. It''s nice and saucy, rather than being stodgy and so thick you can cut into it like cake, so there''s extra cheese sauce to spoon over once served.', 'https://www.recipetineats.com/tachyon/2015/05/Broccoli-Casserole_8.jpg', 10, 60, 70, 4, '[{"id": "ing_broccoli", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.09, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 0.094, "unit": "loaf"}}]', '[{"ingredients":["600g / 1.2 lb broccoli florets (, small to medium (2 large heads, Note 1))","60g / 4 tbsp unsalted butter","4 garlic cloves (, minced)","6 tbsp plain flour","2 cups milk (, preferably warm (full or low fat))","1 1/2 cups chicken broth/stock (, preferably warm)","1.5 cups cheddar cheese, freshly grated (Note 2)","1/2 cup grated parmesan cheese","Salt and pepper"]},{"ingredients":["1/2 cup panko breadcrumbs","1/4 cup grated parmesan cheese","20g / 1.5 tbsp unsalted butter, melted"],"purpose":"Topping:"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Mix Topping ingredients in a bowl with a pinch of salt and pepper. Set aside.","images":[],"step":2},{"description":"Melt butter in a large pot over medium heat. Add garlic and cook for 1 minute until it smells incredible.","duration":1,"images":[],"step":3},{"description":"Add flour and cook for 1 minute, stirring constantly.","duration":1,"images":[],"step":4},{"description":"While whisking, slowly pour in half the milk. Once fully incorporated, whisk in the remaining milk plus the chicken broth.","images":[],"step":5},{"description":"Cook for 4 to 5 minutes, whisking every now and then and more towards the end, until the sauce thickens so that it coats the back of a wooden spoon and when you draw your finger across it, the path stays (see video).","duration":4.5,"images":[],"step":6},{"description":"Turn off heat, add cheeses, stir in (don''t worry if it doesn''t melt fully). Then do a taste test and add a bit of salt if required.","images":[],"step":7},{"description":"Add broccoli and stir well to coat.","images":[],"step":8},{"description":"Pour into a casserole dish, pat down to fill. Sprinkle over Topping, cover with foil then bake for 25 minutes.","duration":25,"images":[],"step":9},{"description":"Remove foil and bake for a further 20 minutes until the topping is deep golden and the broccoli is tender.","images":[],"step":10},{"description":"Stand for 5 minutes before serving.","duration":5,"images":[],"step":11}]', '["gluten","milk"]', '["low_calorie"]', '{"mealType":["main_course"],"cuisine":["French influence"],"categories":["all-vegetable-sides","broccoli","broccoli-recipes","casseroles-and-cosy-bakes","easter-recipes","easter-sides-warm-hearty","quick-and-easy","side-dishes","sunday-supper","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4eb30e62ff1b', 'en', 'US', 'Coleslaw', 'RECIPE VIDEO ABOVE. A really great Coleslaw doesn''t have tons of ingredients in it - just cabbage and carrot. It''s really all about the dressing! Serve as a side salad or pile onto sandwiches. A terrific summer salad that''s even better the next day. Try this on BBQ Pulled Pork Sandwiches! User slider to scale recipe - click on servings.', 'https://www.recipetineats.com/tachyon/2018/06/Coleslaw_7a.jpg', 10, 20, 30, 6, '[{"id": "ing_cabbage", "quantity": {"value": 21.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.188, "unit": "jar of 400g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.3, "unit": "tub of 250g"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.045, "unit": "bottle of 500ml"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_celery", "quantity": {"value": 0.075, "unit": "head"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.25, "unit": "jar of 50g"}}]', '[{"ingredients":["7 cups green cabbage (, finely shredded (Note 1))","1 medium carrot (, shredded (1 1/2 cups))"]},{"ingredients":["1/2 cup Hellman''s mayonnaise (or other whole egg mayo)","1/2 cup sour cream or yoghurt, (full fat is best)","1 1/2 tbsp apple cider vinegar (or sub with white wine vinegar)","2 tsp Dijon mustard","2 tbsp white sugar","3/4 tsp celery salt","1/4 tso black pepper"],"purpose":"Dressing"}]', '[{"description":"Mix Dressing ingredients together.","images":[],"step":1},{"description":"Place cabbage and carrot in a bowl. Pour over Dressing, toss well. Set aside for at least 20 minutes before serving, preferably 2 hours - this will make the cabbage go limp as it should, and also draw moisture out of the cabbage and carrot to thin out the dressing. Overnight is even better!","images":[],"step":2},{"description":"Toss well before serving.","images":[],"step":3}]', '["egg","milk","mustard"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["all-vegetable-sides","cabbage","easter-sides-fresh-light","quick-and-easy","side-salads","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1252098bdbd6', 'en', 'US', 'Corn Salad with Avocado', 'Recipe video above (see how I cut the kernels off!) My favourite corn salad, the one I make most often. Best made with fresh corn but canned is fine too. I love making this with avocado but when it''s not available, I use cucumber which adds a great juicy crunch to this. Use lime or lemon for the dressing - both are great!', 'https://www.recipetineats.com/tachyon/2017/05/Corn-Salad-in-Avocado_3.jpg', 10, 5, 15, 4, '[{"id": "ing_corn", "quantity": {"value": 2.0, "unit": "can of 400g"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 0.8, "unit": "punnet of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["2 corn on the cob (or 400g / 14 oz canned corn, drained)","1 avocado (, cut into large dice)","200 g / 7 oz cherry tomatoes (, halved (or 2 large tomatoes, cut into large dice))","2 shallots / scallions (, finely sliced or 1 small red onion finely chopped)","1/3 cup finely chopped coriander/cilantro (or parsley)","2 tbsp lime juice or 1 1/2 tbsp lemon juice","3 tbsp extra virgin olive oil","Salt and pepper"]}]', '[{"description":"Bring a large pot of water to the boil and cook corn on the cob for 3 minutes. Drain corn, run under cold water to stop cooking further. Once cool to touch, cut corn off the cob. Cool.","duration":3,"images":[],"step":1},{"description":"Place remaining ingredients in a large bowl, drizzle over lime juice, olive oil and a good pinch of salt and pepper. Toss gently, serve.","images":[],"step":2}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["lunch"],"cuisine":[],"categories":["all-vegetable-sides","avocado","corn","dietary","easter-brunch-recipes","easter-sides-fresh-light","gluten-free-recipes","quick-and-easy","side-salads","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ab746e05f3bd', 'en', 'US', 'Kale and Quinoa Salad', 'Inactive marinating time: 30 minutes. Recipe video above.A seriously tasty kale salad that also happens to incorporate quinoa, another superfood! Marinating is the secret to tasty raw kale salads. Keeps for days! Makes 3 as a light meal, or serves 6 - 8 as a side.', 'https://www.recipetineats.com/tachyon/2018/04/Kale-Quinoa-Salad_4.jpg', 45, 15, 60, 3, '[{"id": "ing_kale", "quantity": {"value": 8.0, "unit": "unit"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_quinoa_any_colour", "quantity": {"value": 150.0, "unit": "pack"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_dill", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_almonds", "quantity": {"value": 0.333, "unit": "pack of 250g"}}, {"id": "ing_feta_cheese", "quantity": {"value": 100.0, "unit": "block of 200g"}}]', '[{"ingredients":["8 cups (packed) kale leaves (Note 1)","1 tbsp extra virgin olive oil","1/4 tsp each salt and pepper"],"purpose":"Marinated Kale:"},{"ingredients":["1 cup quinoa, any colour","2 cups water"],"purpose":"Quinoa:"},{"ingredients":["Zest of 1 large lemon","2 1/2 tbsp lemon juice","3 tbsp extra virgin olive oil","1 tsp Dijon mustard (or American)","1 garlic clove (, minced)","1 tsp sugar (optional, I add it)","1/2 tsp each salt and pepper"],"purpose":"Dressing:"},{"ingredients":["1/4 cup dill leaves (, roughly chopped)","1/4 cup coriander/cilantro leaves (, roughly chopped)","1 red onion (, quartered and finely sliced (optional))","1/3 - 1/2 cup chopped roasted almonds","100 g/3.5oz crumbled feta"],"purpose":"Salad:"}]', '[{"description":"Marinated Kale:","images":[],"step":1},{"description":"Scrunch up the kale leaves then slice to about 1cm / 2/5\" thickness.","images":[],"step":2},{"description":"Transfer to large bowl.","images":[],"step":3},{"description":"Drizzle over oil, scatter with salt and pepper. Use your hands to scrunch the kale leaves for 1 minute (see video). It should shrink to about half the size.","duration":1,"images":[],"step":4},{"description":"Set aside for 30 minutes. The leaves will soften, making them suitable for eating raw.","duration":30,"images":[],"step":5},{"description":"Place quinoa in a fine mesh colander, then rinse under running water for 30 seconds. Drain excess water well. (Or do this in a big bowl)","duration":0.5,"images":[],"step":6},{"description":"Place in a saucepan with water. Cover with lid, bring to simmer over medium heat then leave for 12 - 15 minutes until all water is absorbed.","duration":13.5,"images":[],"step":7},{"title":"Remove from heat, leave lid on, and rest for 5","description":"10 minutes. Fluff with fork then cool (spread on tray and refrigerate to speed up).","duration":7.5,"images":[],"step":8},{"description":"Place ingredients in a jar, screw lid on and shake well. Set aside for 10 minutes.","duration":10,"images":[],"step":9},{"description":"Add the quinoa into the bowl with the kale. Add all the dill and coriander/cilantro, half the nuts, feta, and 2/3 of dressing.","images":[],"step":10},{"description":"Toss well.","images":[],"step":11},{"description":"Transfer into serving platter or bowls. Drizzle with remaining dressing, garnish with remaining feta and nuts.","images":[],"step":12},{"title":"See Note 3 for serving suggestions","description":"I''ve been having this as a meal, just plain.","images":[],"step":13}]', '["mustard"]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["all-vegetable-sides","dietary","easter-brunch-recipes","easter-sides-fresh-light","gluten-free-recipes","leafy-greens","pasta-salads-and-rice-salads","quick-and-easy","salad-recipes-main-course","side-dishes","side-salads","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7c51d18f70d4', 'en', 'US', 'Ultra Crispy Smashed Potatoes', 'Recipe VIDEO above. Extra crispy on the outside, fluffy on the inside. They taste like French fries except they''re buttery (and look more rustic! :) ) These will be your new favourite way with potatoes! Makes 12, depending on size of potatoes. Make as many as can fit on the tray once smashed, as long as they aren''t touching.', 'https://www.recipetineats.com/tachyon/2018/02/Crispy-Smashed-Potatoes_4a_1500px.jpg', 10, 90, 70, 12, '[{"id": "ing_potato", "quantity": {"value": 700.0, "unit": "bag of 2kg"}}, {"id": "ing_potato", "quantity": {"value": 700.0, "unit": "bag of 2kg"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["700g / 1.4 lb small potatoes (12 - 14) (Note 1)","1 - 1.2kg / 2 - 2.4lb medium potatoes (6 - 8)"],"purpose":"Potatoes – choose:"},{"ingredients":["1 tbsp salt (for boiling)","30g / 2 tbsp unsalted butter (, melted)","1 tbsp olive oil","3/4 tsp salt (for sprinkling)","1/4 tsp black pepper","Finely chopped parsley (, optional garnish)"],"purpose":"Cooking:"}]', '[{"title":"Cook potatoes","description":"Bring a pot of water to the boil, add 1 tbsp salt. Cook potatoes until soft - small ones should take around 20 to 25 minutes, medium ones might take 30 minutes. It''s ok if the skin splits. Alternatively, steam or microwave them.","images":[],"step":1},{"description":"Preheat oven to 200°C/390°F (180°C fan).","images":[],"step":2},{"title":"Steam dry","description":"Drain the potatoes and let them dry in the colander for 5 minutes or so.","duration":5,"images":[],"step":3},{"description":"Smash! Place on the tray then use a large fork or potato masher to squish them, keeping them in one piece. Thin = crisper. Thicker = fluffier insides. (Both good!) More nubbly surface = better crunch!","images":[],"step":4},{"title":"Steam dry again","description":"Leave on the tray to steam dry for 5 minutes or so - makes them crispier!","duration":5,"images":[],"step":5},{"title":"Drizzle","description":"Drizzle with butter, then olive oil. Sprinkle with salt and pepper.","images":[],"step":6},{"title":"Bake","description":"Bake for 45 minutes (small potatoes) to 55 minutes (medium) or until deep golden and crispy. Do not flip!","duration":45,"images":[],"step":7},{"description":"Serve hot, sprinkled with parsley if desired.","images":[],"step":8}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["all-vegetable-sides","dietary","easter-sides-warm-hearty","gluten-free-recipes","potato-recipes","potatoes","quick-and-easy","side-dishes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d508e992f93a', 'en', 'US', 'Roasted Sweet Potato Stacks', 'A terrific sweet potato side! Crispy edges, buttery and salty, combined with the natural sweetness of sweet potato and a hint of rosemary. Use a mandolin to make short work of slicing the potatoes - or use this opportunity to practice your knife skills!! Recipe VIDEO below.', 'https://www.recipetineats.com/tachyon/2017/10/Roasted-Sweet-Potato-Stacks-4.jpg', 15, 45, 60, 12, '[{"id": "ing_sweet_potato", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_rosemary", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["1.2 kg / 2.4 lb sweet potato (, unpeeled weight, about 5 - 6.5 cm / 2 - 2.7\" wide)","50 g / 3 tbsp unsalted butter (, melted)","1 1/2 tbsp olive oil","2 tbsp finely chopped fresh rosemary (or 1 tbsp dried, or other herbs of choice)","1 1/4 tsp salt","1/2 tsp black pepper"]}]', '[{"description":"Preheat oven to 375F/190C (standard) or 350F/180C (fan/convection).","images":[],"step":1},{"description":"Peel the potatoes, then slice thinly (about 2 mm / 1/10\" thick). Transfer into a large bowl.","images":[],"step":2},{"description":"Add remaining ingredients. Toss well with your hands.","images":[],"step":3},{"description":"Place piles of the slices in the muffin tin. Don''t worry if they are higher than the rim - they shrink about 25%.","images":[],"step":4},{"description":"Top each stack with about 1/2 tsp of the remaining butter mixture in the bowl.","images":[],"step":5},{"description":"Bake for 45 minutes, or until the edge of the top slices are starting to brown and the inside of the stacks are cooked (use skewer or knife to check).","duration":45,"images":[],"step":6},{"description":"Use a fork and knife to remove the stacks from the muffin tin. Optional: Brush tops with residual butter in muffin tin. Serve as soon as possible.","images":[],"step":7}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["all-vegetable-sides","dietary","easter-sides-warm-hearty","gluten-free-recipes","potato-recipes","quick-and-easy","side-dishes","sweet-potato","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4286d8d1a15e', 'en', 'US', 'Roasted Parmesan Crusted Cauliflower', 'Recipe VIDEO above. The healthier version of the popular Parmesan Crusted Potatoes! Try it for dinner tonight - as a side, or as the main meal. Or how about passing it around at a gathering?', 'https://www.recipetineats.com/tachyon/2017/09/Parmesan-Crusted-Cauliflower-Main-1.jpg', 10, 25, 35, 4, '[{"id": "ing_cauliflower", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_bread", "quantity": {"value": 0.047, "unit": "loaf"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_paprika", "quantity": {"value": 0.062, "unit": "jar of 40g"}}]', '[{"ingredients":["1 large head of cauliflower (, firm not old and floppy)","2 1/2 tbsp olive oil","Black pepper","Oil spray (I use olive oil) (Note 1)","Finely chopped parsley (, for garnish, if desired)"]},{"ingredients":["1/2 cup / 50g grated parmesan (, the sand-like type (Note 2))","1/4 cup panko breadcrumbs (Note 3)","1/2 tsp dried oregano or thyme","1/2 tsp paprika","1/2 tsp black pepper"],"purpose":"Crust:"}]', '[{"description":"Preheat oven to 200C/390F (standard) or 180C/350F (fan/convection).","images":[],"step":1},{"description":"Mix Crust ingredients in a small bowl.","images":[],"step":2},{"description":"Break cauliflower into large florets. Cut very large florets into 1.5cm / 3/5\" thick slices, and the medium florets in half. You want a large flat surface area on each piece for the crust to adhere to.","images":[],"step":3},{"description":"Line a baking tray (30 x 40 cm / 12 x 16\") with paper.","images":[],"step":4},{"description":"Drizzle tray with oil. Use a cauliflower to spread the oil all over the paper (see video).","images":[],"step":5},{"description":"Sprinkle Crust mixture all over the tray, as evenly as possible. Don''t touch it once scattered.","images":[],"step":6},{"description":"Place cauliflower down on the Crust mixture, pressing down lightly. Don''t jam them right up against each other (they will steam and go soggy), keep a tiny bit of space between each one.","images":[],"step":7},{"description":"Spray generously with oil. Sprinkle with a bit of black pepper (optional).","images":[],"step":8},{"description":"Bake for 20 minutes until crust is deep golden.","duration":20,"images":[],"step":9},{"description":"Use tongs to turn the cauliflower so the crust side is up. Bake for a further 5 minutes.","images":[],"step":10},{"description":"Serve immediately, sprinkled with finely chopped parsley or other herb, if desired.","images":[],"step":11}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["all-vegetable-sides","cauliflower","dinner-tonight","easter-sides-warm-hearty","main-dishes","quick-and-easy","side-dishes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e5b92a011845', 'en', 'US', 'Roast Pumpkin, Spinach and Feta Salad', 'Recipe video above. Try this Roast Pumpkin, Spinach and Feta Salad for your next Sunday lunch! Drizzled with a Honey Balsamic Dressing, this is a magical combination of ingredients. I usually serve this at room temperature but it''s also great warm. Serves 2 - 3 as a meal, 4 - 5 as a side.', 'https://www.recipetineats.com/tachyon/2017/09/Roasted-Pumpkin-Spinach-Salad-2.jpg', 10, 25, 35, 4, '[{"id": "ing_pumpkin", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_balsamic_vinegar", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_honey", "quantity": {"value": 0.03, "unit": "jar of 500g"}}, {"id": "ing_pine_nuts", "quantity": {"value": 0.375, "unit": "pack of 100g"}}, {"id": "ing_baby_spinach", "quantity": {"value": 150.0, "unit": "bag of 250g"}}, {"id": "ing_feta_cheese", "quantity": {"value": 60.0, "unit": "block of 200g"}}]', '[{"ingredients":["600 g / 1.2 lb pumpkin (after peeling), cut into 3cm / 1.25\" cubes (Note 1)","1 1/2 tbsp olive oil","Salt and pepper"],"purpose":"Pumpkin:"},{"ingredients":["2.5 tbsp / 50 ml extra virgin olive oil","2 tbsp balsamic vinegar","1 tbsp honey","Salt and pepper"],"purpose":"Dressing:"},{"ingredients":["1/4 cup / 35g pine nuts (Note 2)","150 g / 5 oz baby spinach leaves (4 handfuls)","60 g / 2 oz feta (, crumbled (or more!!))"],"purpose":"Salad:"}]', '[{"description":"Preheat oven to 220C/430F (standard) or 200C/390F (fan/convection).","images":[],"step":1},{"description":"Toss pumpkin with olive oil, salt and pepper. Spread on baking tray, bake for 20 minutes. Remove from oven, flip, then bake for a further 7 - 10 minutes until golden but not mushy. (Note 3) Loosen pumpkin with egg flip (it can adhere as it cools), then if serving salad at room temperature, leave to cool.","duration":20,"images":[],"step":2},{"description":"Shake Dressing in a jar. Taste and adjust to taste. I like it a bit sharp because it balances out the flavours in this salad.","images":[],"step":3},{"description":"Toast pine nuts in a dry skillet over medium heat until light golden and it smells nutty. Remove pine nuts from skillet as soon as it''s ready.","images":[],"step":4},{"description":"Place Spinach in a bowl. Drizzle with a bit of dressing then toss.","images":[],"step":5},{"description":"Add pumpkin, just a bit of feta and pine nuts, then GENTLY BRIEFLY toss just to disperse the feta. (If you toss vigorously, the feta can make it look messy).","images":[],"step":6},{"description":"Transfer to serving plate. Sprinkle over remaining feta and pine nuts. Just before serving, drizzle with remaining dressing (dressing doesn''t stay on baby spinach well, so worth drizzling at end). Serve!","images":[],"step":7}]', '[]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["all-vegetable-sides","dietary","easter-brunch-recipes","easter-sides-fresh-light","gluten-free-recipes","pumpkin","pumpkin-squash","quick-and-easy","salad-recipes-main-course","side-salads","spinach","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a29a70975c55', 'en', 'US', 'Crispy Roasted Parmesan Potatoes', 'Recipe video above. Tender potatoes with the most incredible CRISPY parmesan crust! Make these for your Sunday Roast or pass them around at a party! Serves 4 -5 as a side. Also, don''t miss the Parmesan Crusted CAULIFLOWER!', 'https://www.recipetineats.com/tachyon/2017/09/Parmesan-Crusted-Potatoes-1.jpg', 10, 35, 45, 4, '[{"id": "ing_potato", "quantity": {"value": 750.0, "unit": "bag of 2kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_paprika", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.45, "unit": "tub of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.75, "unit": "bunch"}}]', '[{"ingredients":["750 g / 1.5 lb baby potatoes (, halved (about 3.5cm / 1.75\", 20 - 24 potatoes))","2 tbsp olive oil (, plus more for drizzling)"]},{"ingredients":["1/2 cup / 50 g grated parmesan (, the sand-like type (Note 1))","1/2 tsp garlic powder (or sub with onion powder)","1/2 tsp dried oregano or thyme","1/2 tsp paprika","1/4 tsp salt (I use table salt, leave out to lower sodium)","1/2 tsp black pepper"],"purpose":"Parmesan Mixture:"},{"ingredients":["3/4 cup sour cream, or sub with plain yoghurt (, or a combination of both)","1/4 cup finely chopped green onions/scallions (, plus more for garnish (or chives))"],"purpose":"Dipping Sauce (Optional):"}]', '[{"description":"Preheat oven to 200C/400F (180C fan-forced).","images":[],"step":1},{"description":"Mix Parmesan Mixture in a bowl.","images":[],"step":2},{"description":"Drizzle oil in 22 x 33cm / 9 x 13\" glass baking dish (Note 2). Tilt pan to spread all over the base.","images":[],"step":3},{"description":"Use a spoon to scatter the Parmesan Mixture over the base. Spread as evenly as you can. Once sprinkled, do not touch - don''t try to spread it.","images":[],"step":4},{"description":"Place potatoes cut side down, pressing firmly.","images":[],"step":5},{"title":"Optional","description":"drizzle top of potatoes with a touch of oil or spray with oil, then sprinkle with salt.","images":[],"step":6},{"title":"Bake potatoes for 35","description":"40 minutes or until they are soft and the parmesan crust is deep golden (you can check through the glass!)","duration":37.5,"images":[],"step":7},{"description":"REST for 5 minutes. Then use an egg flip to cut between every 4 or so potatoes (i.e. cutting through the parmesan crust which bonds between each potato - see video), then scoop up 4 or so potatoes and flip them upside down so the cheese side is up on a serving platter.","duration":5,"images":[],"step":8},{"description":"Serve with Dipping Sauce, if using, and sprinkle over extra green onions if desired. Serve as a side dish or as nibbles!","images":[],"step":9}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["all-vegetable-sides","easter-sides-warm-hearty","finger-food","potato-recipes","potatoes","quick-and-easy","side-dishes","super-bowl-party-food","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_91a00d9643c8', 'en', 'US', 'Easy Creamy Cheesy Potato Bake', 'An easier, creamier alternative to Scalloped Potatoes / Potato Dauphinoise, this is made with cubes of potato that are cooked in the dish with the sauce. Far less effort than slicing potatoes thinly, making sauce separately then layering it all in a dish. Recipe video is below!', 'https://www.recipetineats.com/tachyon/2017/04/Creamy-Cheesy-Potato-Bake-3.jpg', 10, 85, 95, 10, '[{"id": "ing_potato", "quantity": {"value": 1.25, "unit": "bag of 2kg"}}, {"id": "ing_milk", "quantity": {"value": 0.167, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.125, "unit": "jar of 400g"}}, {"id": "ing_thyme", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 666.667, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.8, "unit": "pack of 125g"}}]', '[{"ingredients":["1.25kg/ 2.5lb potatoes (any, other than waxy potatoes, see Note 1)","2/3 cup (160 ml) milk (full or low fat)","3/4 cup (185 ml) thickened cream (heavy cream) (heavy cream)","1/3 cup mayonnaise (, preferably whole egg (or 1/4 cup cream) (Note 2))","1 1/2 tsp fresh thyme leaves (, plus more for garnish (or 1 tsp dried))","2 large garlic cloves (, minced)","3/4 tsp salt","Black pepper","2 cups (200g) shredded cheese (, for mixing (Note 3))","1 cup (100g) shredded mozzarella cheese ( (or sub with another cheese, Note 3))"]}]', '[{"description":"Preheat oven to 180C/350F (all types).","images":[],"step":1},{"description":"Peel and cut the potatoes into 1 3/4 cm / 2/3\" cubes. Place in a large bowl.","images":[],"step":2},{"description":"Add all remaining ingredients except mozzarella. Mix.","images":[],"step":3},{"description":"Pour into a 3 litre / quart baking dish (mine is 22cm / 9\" square x 6 cm / 2.3\" high).","images":[],"step":4},{"description":"Cover with foil. Bake 60 minutes, or until potatoes are tender.","images":[],"step":5},{"description":"Remove foil, sprinkle over mozzarella cheese. Bake for 25 minutes or until cheese is golden.","duration":25,"images":[],"step":6},{"title":"Rest for 5","description":"10 minutes before serving, garnished with extra theme leaves if desired.","duration":7.5,"images":[],"step":7}]', '["egg","milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["all-vegetable-sides","dietary","easter-recipes","easter-sides-warm-hearty","gluten-free-recipes","potato-recipes","potatoes","quick-and-easy","side-dishes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d56ef658b84b', 'en', 'US', 'JP''s Iceberg Lettuce Dill Salad', 'My favourite iceberg lettuce salad! Light and refreshing, this is by far the salad I make the most often using iceberg lettuce. The red cabbage adds colour and the snow peas add a touch of crunch, so feel free to substitute these with other vegetables if you wish. Don''t skip the herbs, they "make" this salad!', 'https://www.recipetineats.com/tachyon/2016/12/JPs-Iceberg-Lettuce-Dill-Salad-12.jpg', 10, 0, 10, 4, '[{"id": "ing_lettuce", "quantity": {"value": 24.0, "unit": "head"}}, {"id": "ing_red_cabbage", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_snow_peas", "quantity": {"value": 6.0, "unit": "unit"}}, {"id": "ing_dill", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_green_onion", "quantity": {"value": 0.5, "unit": "bunch"}}, {"id": "ing_verjuice", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.09, "unit": "net of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.013, "unit": "jar of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["8 cups iceberg lettuce (, chopped or torn into bite size pieces)","Handful of finely sliced red cabbage (just for a bit of colour)","6 snow peas (, diagonally sliced (adds crunch to the salad))","3/4 cup dill (, lightly packed)","3/4 cup coriander/cilantro (, lightly packed)","1/2 eschalot / french onion ((US: shallots), finely chopped)"]},{"ingredients":["4 tbsp Verjuice (Note 1)","3 tbsp extra virgin olive oil (or use lemon infused and skip the zest)","1 tsp lemon zest","1/2 tsp sugar (white)","1/2 tsp yellow mustard powder","Salt and pepper"],"purpose":"Dressing:"}]', '[{"description":"Mix Dressing together in screw top jar and shake.","images":[],"step":1},{"description":"Mix eschalot and herbs together in the salad bowl. Drizzle with 1/3 of dressing about 20 mins before serving.","images":[],"step":2},{"description":"Lay rest of salad ingredients on top.","images":[],"step":3},{"description":"Just before serving, add rest of dressing and toss","images":[],"step":4}]', '["mustard"]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["lunch"],"cuisine":[],"categories":["all-vegetable-sides","easter-brunch-recipes","easter-sides-fresh-light","leafy-greens","quick-and-easy","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3721411562f0', 'en', 'US', 'Italian Dressing', 'A classic everyone should know, the secret ingredient in a truly great Italian Dressing is parmesan cheese. By making this with garlic powder rather than fresh, this Dressing lasts for a couple of weeks (subject to shell life of your parmesan). If you use fresh, it must be consumed within 2 - 3 days.', 'https://www.recipetineats.com/tachyon/2016/12/Italian-Dressing-2.jpg', 5, 0, 5, 1, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_vinegar", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 0.05, "unit": "pack of 200g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.016, "unit": "jar of 40g"}}, {"id": "ing_basil", "quantity": {"value": 0.013, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}]', '[{"ingredients":["2 tbsp extra virgin olive oil","1 tbsp red or white wine vinegar (Note 1)","2 tsp freshly grated parmesan (Note 2)","1 tsp sugar (any)","1/8 tsp garlic powder (or 1 small garlic clove minced, if using within 3 days)","1/8 tsp each dried basil (, oregano and parsley (or a mix of choice))","1/8 tsp red pepper flakes (Note 3)","1/4 tsp salt","Freshly ground pepper"],"purpose":"Single Batch (1/4 cup, salad for 4 servings)"},{"ingredients":["2/3 cup extra virgin olive oil","1/3 cup red or white wine vinegar (Note 1)","2 tbsp freshly grated parmesan (Note 2)","1 1/2 tbsp sugar (any)","3/4 tsp garlic powder (or 2 garlic cloves minced, if using within 3 days)","1/2 tsp each dried basil (, oregano and parsley (or a mix of choice))","3/4 tsp red pepper flakes (Note 3)","1 tsp salt","1/2 tsp freshly ground pepper"],"purpose":"Big Batch to Keep (1 1/4 cups)"}]', '[{"description":"Place ingredients in a jar and shake well until combined.","images":[],"step":1},{"description":"Adjust sugar, salt and pepper to taste. For less tang, add more olive oil, for more tang, add more vinegar.","images":[],"step":2},{"description":"Keep in the refrigerator for up to 2 weeks.","images":[],"step":3},{"description":"For the Single Batch, this makes just over 1/4 cup and is enough to dress 3 handfuls of leafy greens.","images":[],"step":4}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["lunch"],"cuisine":[],"categories":["all-vegetable-sides","dietary","dressings","gluten-free-recipes","quick-and-easy","salad-dressings","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c87f18eba906', 'en', 'US', 'Honey Mustard Dressing', 'Creamy, tangy with a touch of sweet. A true crowd pleaser, use for leafy greens and roasted vegetables. It goes fantastic with my Roasted Sweet Potato Salad!', 'https://www.recipetineats.com/tachyon/2016/12/Honey-Mustard-Dressing-3.jpg', 5, 0, 5, 1, '[{"id": "ing_mustard", "quantity": {"value": 0.188, "unit": "jar of 200g"}}, {"id": "ing_honey", "quantity": {"value": 0.125, "unit": "jar of 500g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}]', '[{"ingredients":["1/4 cup Dijon mustard","1/4 cup honey","1/4 cup cider vinegar","1/4 cup vegetable or olive oil","1 tsp salt","Black pepper"],"purpose":"Big Batch to Keep (1 cup)"},{"ingredients":["1 1/2 tbsp Dijon mustard","1 1/2 tbsp honey","1 1/2 tbsp cider vinegar","1 1/2 tbsp vegetable or olive oil","1/4 tsp salt","Black pepper"],"purpose":"Single side salad batch (makes 1/3 cup, enough for a side salad for 4 ppl)"}]', '[{"description":"Place ingredients in a jar and shake well until you can''t see any honey on the base of the jar. Adjust sweet (honey), sour (vinegar) and salt to taste.","images":[],"step":1},{"description":"Keep for 3 weeks in the fridge in an airtight jar. (As long as the shelf life of your ingredients is greater than 3 weeks).","images":[],"step":2},{"title":"Single side salad","description":"Drizzle over 4 big handfuls of leafy greens and other salad of choice.","images":[],"step":3}]', '["mustard"]', '["gluten_free","vegetarian"]', '{"mealType":["lunch"],"cuisine":[],"categories":["all-vegetable-sides","dietary","dressings","gluten-free-recipes","quick-and-easy","salad-dressings","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ff1b5e025249', 'en', 'US', 'Asian Sesame Dressing', 'A fantastic standby dressing to have on hand because it keeps for 3 weeks! Use this Asian dressing for leafy green salads, Asian slaws, noodle salads and chopped salads. It''s also a terrific dressing to make steamed vegetables so much tastier. Finish with a sprinkle of fresh sesame seeds and sliced greens onions!', 'https://www.recipetineats.com/tachyon/2016/12/Asian-Sesame-Dressing-4.jpg', 3, 0, 3, 1, '[{"id": "ing_soy_sauce", "quantity": {"value": 0.25, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.3, "unit": "pack of 100g"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}]', '[{"ingredients":["1/4 cup soy sauce","2 tbsp toasted sesame oil","1/4 cup white vinegar (adjust to taste for sharpness)","1/4 cup olive oil (Note 1)","1 tbsp sugar ((any type) or 1 1/2 tbsp honey)"],"purpose":"Big batch to keep (makes 1 cup)"},{"ingredients":["1 tbsp soy sauce","2 tsp toasted sesame oil","1 tbsp white vinegar","1 tbsp olive oil (Note 1)","1 tsp sugar ((any type) or 1 1/2 tsp honey)"],"purpose":"Single serving batch"}]', '[{"description":"Place ingredients in a jar and shake well until sugar is dissolved. Adjust saltiness with salt and sweetness with sugar to taste.","images":[],"step":1},{"description":"Keep for up to 3 weeks, in the fridge (to be safe). Bring to room temp and shake well before use.","images":[],"step":2},{"title":"Single serving batch is enough for 3","description":"4 cups of shredded cabbage / leafy greens i.e. a side salad for 4 people.","images":[],"step":3},{"title":"Big batch","description":"my rule of thumb for how much dressing to use is generally 1 tbsp of dressing per 1 packed cup of shredded vegetables and 2 tsp per handful of leafy greens.","images":[],"step":4}]', '["gluten","sesame","soy"]', '["keto_friendly","low_calorie","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Asian"],"categories":["all-vegetable-sides","asian-recipes","dietary","dressings","gluten-free-recipes","quick-and-easy","salad-dressings","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cbc08c7ec9c0', 'en', 'US', 'Poppyseed Salad Dressing', 'Poppyseed Dressing is so much more than just a creamy dressing with poppyseed in it. The poppyseeds ada a beautiful nutty aroma, and can take an otherwise humble salad to new heights!', 'https://www.recipetineats.com/tachyon/2016/12/Poppyseed-Dressing.jpg', 5, 0, 5, 1, '[{"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_vinegar", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_poppyseeds", "quantity": {"value": 22.5, "unit": "jar"}}, {"id": "ing_mustard", "quantity": {"value": 0.013, "unit": "jar of 200g"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.037, "unit": "jar of 400g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.125, "unit": "L"}}]', '[{"ingredients":["1 eschalot / French shallot ((\"shallot\" in the US i.e. the small onions), finely chopped)","1/4 cup white wine vinegar","1/4 cup white sugar","1 1/2 tbsp poppyseeds","1/2 tsp mustard powder (or 1 tsp mild English mustard, not hot)","1 tbsp mayonnaise (can omit, makes it creamier)","1/2 tsp salt","1/2 cup olive oil or grapeseed oil"]}]', '[{"description":"Place ingredients in a jar. Shake very well. Adjust salt and pepper to taste. Store in the fridge for up to 2 weeks.","images":[],"step":1}]', '["mustard"]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["all-vegetable-sides","dietary","dressings","gluten-free-recipes","quick-and-easy","salad-dressings","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9fe3d02a7af9', 'en', 'US', 'French Salad Dressing (French Vinaigrette)', 'A classic everyone should know! Served the true French way, drizzle it over leafy greens and toss lightly. PS A classic French vinaigrette does not have garlic in it, hence why this can be kept for up to 2 weeks.', 'https://www.recipetineats.com/tachyon/2016/12/French-Dressing-2-1.jpg', 5, 0, 5, 1, '[{"id": "ing_green_onion", "quantity": {"value": 0.75, "unit": "bunch"}}, {"id": "ing_vinegar", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.1, "unit": "jar of 200g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1/4 cup eschalots / French shallots (, finely chopped (Note 1))","1/4 cup red or white wine vinegar (or sherry or champagne vinegar)","4 tsp Dijon Mustard","1/2 cup extra virgin olive oil (or more if you want richer)","1/2 tsp salt","Black pepper"],"purpose":"Big Batch to keep (1 cup)"},{"ingredients":["1 tbsp eschalots / French shallots (, finely chopped (Note 1))","1 tbsp red or white wine vinegar (or sherry or champagne vinegar)","1 tsp Dijon Mustard","2 tbsp olive oil (I use 5 tbsp)","Salt and pepper"],"purpose":"Small batch (Side salad for 4 ppl)"}]', '[{"description":"Place ingredients in a jar and shake well until combined. Adjust salt and pepper to taste. Let rest for 5 minutes before using, or keep up to 2 weeks.","duration":5,"images":[],"step":1},{"title":"Small Batch","description":"Use to dress 4 handfuls of leafy greens.","images":[],"step":2}]', '["mustard"]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["lunch"],"cuisine":[],"categories":["all-vegetable-sides","dietary","dressings","gluten-free-recipes","quick-and-easy","salad-dressings","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e3286d517269', 'en', 'US', 'Maple Syrup Dressing', 'A classic vinaigrette slightly sweetened with maple syrup. Fall flavours, this goes perfectly with roasted veg as well as leafy greens.', 'https://www.recipetineats.com/tachyon/2016/12/Maple-Syrup-Dressing-2.jpg', 5, 0, 5, 1, '[{"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_maple_syrup", "quantity": {"value": 0.03, "unit": "bottle of 250ml"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1 tbsp apple cider vinegar","2 tbsp olive oil","1 1/2 tsp pure maple syrup","1 tsp Dijon mustard","Salt and pepper"],"purpose":"Single Batch"},{"ingredients":["1/3 cup apple cider vinegar","2/3 cup olive oil (extra virigin is ok)","2 tbsp pure maple syrup","1 tbsp Dijon mustard","1/2 tsp salt","Black pepper"],"purpose":"Big Batch to keep (1 cup)"}]', '[{"description":"Place ingredients in a jar. Shake until well combined and creamy.","images":[],"step":1},{"title":"Store","description":"Keep in the fridge for 2 to 3 weeks.","images":[],"step":2},{"title":"Single Batch","description":"This will dress 4 large handfuls of leafy greens / fresh salad, or about 500g / 1 lb roasted sweet potato or pumpkin place o 2 handfuls of rocket lettuce / arugula.","images":[],"step":3}]', '["mustard"]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["lunch"],"cuisine":[],"categories":["all-vegetable-sides","dietary","dressings","gluten-free-recipes","quick-and-easy","salad-dressings","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c661f4b46d41', 'en', 'US', 'Balsamic Vinegar Dressing', 'A classic dressing that everyone should know! The "formula" is 1 part vinegar to 3 parts oil. Some people who like sharper dressing will use less oil. The better the quality of the vinegar and oil, the better the dressing!', 'https://www.recipetineats.com/tachyon/2016/12/Balsamic-Dressing-1.jpg', 2, 0, 2, 1, '[{"id": "ing_balsamic_vinegar", "quantity": {"value": 0.25, "unit": "bottle of 250ml"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1/4 cup balsamic vinegar (ordinary, not caramelised or syrupy)","3/4 cup extra virgin olive oil (or less if you like sharper dressing)","Salt and pepper to taste"],"purpose":"Big Batch To Keep"},{"ingredients":["1 tbsp balsamic vinegar","3 tbsp extra virgin olive oil (or less if you like sharper dressing)","Salt and pepper to taste"],"purpose":"Single Batch (Serves 3 - 4 as a side)"},{"ingredients":["Honey or sugar (, to taste)"],"purpose":"Optional extra"}]', '[{"description":"Place ingredients in a jar and shake very well. Adjust salt and pepper to taste.","images":[],"step":1},{"description":"Keeps for 3 weeks on the counter (unless it is very hot where you are, store it in the fridge), assuming you use fresh olive oil. Do not keep for more than 4 weeks as high quality olive oil tends to lose flavour beyond 4 weeks after opening the bottle.","images":[],"step":2}]', '[]', '["gluten_free","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["all-vegetable-sides","dietary","dressings","gluten-free-recipes","italian-recipes","leafy-greens","quick-and-easy","salad-dressings","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_64a48c26eee3', 'en', 'US', 'Louisiana Strawberry Spinach Salad with Strawberry Balsamic Dressing', 'This is a fabulous salad - especially for special occasions! It''s a surprising combination of ingredients that works brilliantly together. The Dressing is especially beautiful! This is a recipe by Chef Varnedoe of Baton Rouge’s Restaurant IPO (now closed :( ), via Around Anna''s Table.', 'https://www.recipetineats.com/tachyon/2016/11/Strawberry-Salad-13.jpg', 15, 5, 20, 4, '[{"id": "ing_strawberries", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_balsamic_vinegar", "quantity": {"value": 0.75, "unit": "bottle of 250ml"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_strawberries", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_pecans", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_baby_spinach", "quantity": {"value": 4.0, "unit": "bag of 250g"}}, {"id": "ing_strawberries", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_cheese", "quantity": {"value": 75.0, "unit": "block of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["250 g / 8 oz fresh strawberries (, tops cut off)","3/4 cups balsamic vinegar","1/4 cup olive oil","4 tbsp brown sugar (, packed (light brown))","2 tbsp strawberry jam or preserves","1/2 tsp salt"],"purpose":"Strawberry Balsamic Dressing (makes ~1 3/4 cups)"},{"ingredients":["1 cup pecans (mostly whole, can chop some)","2 tbsp brown sugar (any)","2 tbsp / 30 g butter"],"purpose":"Candied pecans:"},{"ingredients":["4 cups baby spinach (, packed)","16 (250 g / 8 oz) large strawberries (, sliced )","75 - 100 g / 2 - 3.5 oz blue cheese (, crumbled (to taste))","Salt and pepper"],"purpose":"Salad"}]', '[{"description":"Whizz Dressing ingredients in a food processor or blender. Strain if desired (to remove little strawberry seeds). Keep for up to 2 weeks in the fridge.","images":[],"step":1},{"title":"Pecans","description":"Line a tray with parchment / baking paper. Melt butter in a medium saucepan over medium heat. Add pecans, toss to coat. Add sugar and stir for 5 minutes. The sugar will melt and coat the pecans. Pour onto tray, spread out, allow to cool - it will harden.","duration":5,"images":[],"step":2},{"description":"To serve, place the spinach and half the strawberries in a bowl and drizzle over a bit of Dressing. Toss gently, then transfer to a serving bowl. Top with remaining strawberries, then drizzle with more Dressing. Crumble over blue cheese and scatter with pecans. Serve immediately, with remaining Dressing on the side!","images":[],"step":3}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Louisiana","Southern"],"categories":["all-vegetable-sides","dietary","gluten-free-recipes","side-salads","spinach"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cee757dc09c1', 'en', 'US', 'Roasted Sweet Potato Salad', 'The combination of ingredients in this salad is magical! Golden caramelised sweet potato that''s juicy inside, fresh peppery rocket / arugula, warm soft crunch of pecans, creamy saltiness from goats cheese (or Danish feta), BACON and a drizzle of Honey Lemon Dressing. The dressing is not too sweet - just enough honey to cut through the sharpness of the lemon. Worthy of a meal or a place at a festive gathering!', 'https://www.recipetineats.com/tachyon/2016/11/Roasted-Sweet-Potato-Salad-3.jpg', 15, 30, 45, 2, '[{"id": "ing_sweet_potato", "quantity": {"value": 600.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_rocket_salad_arugula", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_pecans", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_oil", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_bacon", "quantity": {"value": 0.5, "unit": "pack of 200g"}}, {"id": "ing_cheese", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_honey", "quantity": {"value": 0.03, "unit": "jar of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.013, "unit": "jar of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["600 - 700 g / 1.2 - 1.4 lb sweet potato (, peeled (2 medium))","1 1/2 tbsp olive oil"],"purpose":"Potato"},{"ingredients":["100 g / 3.5 oz rocket salad / arugula (~3 handfuls)","1/2 cup (70g / 5 oz) pecans","1 tsp oil","100 g / 3.5 oz bacon (, chopped (I used lean))","60 g / 2 oz Goats Cheese or Danish feta (Note 1)"],"purpose":"Salad"},{"ingredients":["1 tbsp honey","2 tbsp lemon juice (, fresh)","2 tbsp extra virgin olive oil","1/2 tsp Dijon mustard","Salt and pepper (, to taste)"],"purpose":"Honey Lemon Dressing"}]', '[{"description":"Preheat oven to 220C / 430F.","images":[],"step":1},{"description":"Cut sweet potato into 1.5cm / 3/5\" thick slices. Cut the larger rounds in half (into semi circles).","images":[],"step":2},{"description":"Place in a bowl, drizzle over oil, sprinkle with salt and pepper. Toss well to coat. Pour onto baking tray.","images":[],"step":3},{"description":"Roast for 20 minutes, then use an egg flip to turn and roast for a further 10 minutes or until golden.","duration":20,"images":[],"step":4},{"description":"Meanwhile, place Dressing ingredients in a jar, mix with a teaspoon (to get honey off the base) then shake well until combined.","images":[],"step":5},{"description":"Toast pecans in a dry skillet over medium high heat for 3 minutes, or until they smell nutty.","duration":3,"images":[],"step":6},{"description":"Remove pecans, then heat 1 tsp oil. Add bacon and cook until golden.","images":[],"step":7},{"description":"To assemble, place everything in a bowl, reserving some bacon, pecans and goats cheese for garnish. Drizzle with most of the dressing, then toss gently.","images":[],"step":8},{"description":"Transfer into a serving bowl, garnish with remaining bacon, pecans and goats cheese. Drizzle with remaining dressing. Serve!","images":[],"step":9}]', '["milk","mustard"]', '["gluten_free","low_calorie"]', '{"mealType":["lunch"],"cuisine":[],"categories":["all-vegetable-sides","dietary","easter-brunch-recipes","easter-sides-fresh-light","gluten-free-recipes","quick-and-easy","salad-recipes-main-course","side-salads","sweet-potato"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_584c14d79c6b', 'en', 'US', 'Broccoli Salad with Sour Cream Dressing', 'No more boring broccoli! The star of this is the Sour Cream Dressing - creamy and tangy, but made without mayonnaise! The almonds add creamy nuttiness, the shallots add pops of freshness and the bacon....well, we all know bacon makes EVERYTHING better! Use this recipe as a base and add your favourite salad toppings.', 'https://www.recipetineats.com/tachyon/2016/09/Broccoli-Salad_2.jpg', 15, 3, 18, 4, '[{"id": "ing_broccoli", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 0.75, "unit": "pack of 200g"}}, {"id": "ing_almonds", "quantity": {"value": 0.15, "unit": "pack of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.2, "unit": "tub of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.02, "unit": "bottle of 500ml"}}, {"id": "ing_milk", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_sugar", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1 large or 2 small heads of broccoli","150 g / 5 oz lean bacon, chopped","1/4 cup flaked almonds, or other nuts of choice","2 shallots / scallions, or red onion, finely chopped"]},{"ingredients":["1/3 cup sour cream (I use low fat)","1 tbsp extra virgin olive oil","1/4 tsp garlic powder, or 1/2 small garlic clove, minced","2 tsp apple cider vinegar, or white wine vinegar","2 - 3 tbsp milk, plus more to adjust consistency","1 tbsp Dijon mustard","3/4 tsp white sugar","Salt and pepper"],"purpose":"Sour Cream Dressing"}]', '[{"description":"Mix the Sour Cream Dressing ingredients together in a bowl. Adjust salt and pepper to taste. and set aside for 20 minutes for the flavours to develop. Use milk to adjust dressing to desired consistency.","duration":20,"images":[],"step":1},{"description":"Break / cut broccoli into smallish florets. Blanch in boiling water or steam until just cooked - it should still be tender but crisp. Drain in a colander, run under tap water to help cool faster and leave to cool. Shake around in colander occasionally to loosen water caught in the floret heads (watery broccoli salad not nice!).","images":[],"step":2},{"description":"Toast almonds in non stick skillet over medium high heat until golden. Remove into bowl.","images":[],"step":3},{"description":"Cook bacon in skillet over high heat until golden. Drain on paper towels.","images":[],"step":4},{"description":"Place salad ingredients in a bowl. Drizzle over dressing and toss to combine. Transfer to serving bowl.","images":[],"step":5},{"description":"I served this with Oven Baked Pork Chops.","images":[],"step":6}]', '["milk","mustard"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["lunch"],"cuisine":[],"categories":["all-vegetable-sides","broccoli","broccoli-recipes","easter-sides-fresh-light","quick-and-easy","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_dc30e23b43d8', 'en', 'US', 'Greek Salad with Homemade Greek Salad Dressing', 'A fresh, classic Greek salad with a homemade Greek Salad Dressing. Bright zesty and fresh, this is a classic recipe everyone should know!', 'https://www.recipetineats.com/tachyon/2016/07/Greek-Salad_4.jpg', 15, 0, 15, 4, '[{"id": "ing_tomato", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_cucumber", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_feta_cheese", "quantity": {"value": 8.0, "unit": "block of 200g"}}, {"id": "ing_black_kalamata_olives", "quantity": {"value": 155.925, "unit": "bottle"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.09, "unit": "L"}}]', '[{"ingredients":["3 tomatoes (size of a tennis ball)","4 Lebanese / Persian cucumbers (about 8\"/20cm long)","1/2 small red onion (size of a tennis ball)","1 small green capsicum / bell pepper","8 oz / 250 g feta block","5.5 oz / 125g black kalamata olives (Note 2)","1 tsp dried oregano"],"purpose":"Salad"},{"ingredients":["1 garlic clove (, minced (about 1/2 tsp minced garlic))","1 tsp dried oregano","1/4 tsp salt (or 1/2 tsp Kosher salt)","Freshly ground black pepper","3 tbsp red wine vinegar","6 tbsp extra virgin olive oil (preferably Greek!)"],"purpose":"Greek Salad Dressing"}]', '[{"description":"Place Greek Salad Dressing ingredients in a jar and shake until well combined. Set aside for 20 minutes to let the flavours infuse.","duration":20,"images":[],"step":1},{"title":"Tomatoes","description":"Cut each tomato into 6 wedges, then cut each wedge into 3 or 4 pieces. If the tomato is watery, scoop out the watery seeds inside with a teaspoon.","images":[],"step":2},{"title":"Cucumbers","description":"Slice the cucumber into 1/2cm / 1/5\" thick slices. Or if they are thick cucumbers, slice the cucumber in half vertically, then slice.","images":[],"step":3},{"title":"Onion","description":"Peel and finely slice the red onion. I keep it in rings - you could cut it in half then slice. (Note 2)","images":[],"step":4},{"title":"Capsicum","description":"Cut into short strips.","images":[],"step":5},{"title":"Feta","description":"Cut into 1cm / 2/5\" cubes.","images":[],"step":6},{"description":"Place the tomato, cucumber, onion, feta and olives in a bowl, sprinkle with oregano then pour over dressing. Toss to combine. Serve immediately!","images":[],"step":7}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Greek"],"categories":["all-vegetable-sides","cucumber","dietary","easter-sides-fresh-light","gluten-free-recipes","greek-recipes","mediterranean-recipes","most-popular","quick-and-easy","side-dishes","side-salads","tomato"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8915bb761e94', 'en', 'US', 'Grilled Mexican Corn with Chipotle Adobo Sauce (Mexicano Restaurant Copycat)', 'This is the best corn I have ever had. It is a copycat of corn I had at a modern Mexican restaurant in Narrabeen, Sydney, called Mexicano (which I think is the second best corn! :) ) ! The chargrilled flavour is key for the ultimate corn experience. But don''t worry! You can make it on stovetop - I''ve provided directions for both methods.Real Mexican street corn is sprinkled with Cotjia which isn''t available here in Sydney. Parmesan is a ripper substitute - and dare I say it takes it to another level!', 'https://www.recipetineats.com/tachyon/2015/05/Corn-with-Adobo-Mayo_in-parmesan.jpg', 5, 10, 15, 4, '[{"id": "ing_chipotle_in_adobo_sauce", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.094, "unit": "jar of 400g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.15, "unit": "tub of 250g"}}, {"id": "ing_lime", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_corn", "quantity": {"value": 4.0, "unit": "can of 400g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_chilli", "quantity": {"value": 0.013, "unit": "pack of 100g"}}, {"id": "ing_lime", "quantity": {"value": 0.03, "unit": "net of 500g"}}]', '[{"ingredients":["1 1/2 tbsp chipotle in adobo sauce (1 chipotle + sauce totalling 1 1/2 tbsp) (Note 4)","1/4 cup whole egg mayonnaise (Note 1)","1/4 cup sour cream","1 tbsp lime juice","1/2 tsp dried oregano flakes","1/4 tsp salt","Black pepper"],"purpose":"Chipotle Adobo Mayo"},{"ingredients":["4 to 6 corn on the cob","1/2 cup freshly grated parmesan cheese (Note 2)","1/4 tsp ancho chili powder (, chipotle powder or smoky paprika)","Lime wedges (, for serving)"],"purpose":"Corn"}]', '[{"description":"Place the Chipotle Adobo Mayo ingredients in a small food processor and blend until smooth. (Note 3)","images":[],"step":1},{"title":"BBQ","description":"Heat the grill side on high. Grill corn for around 8 minutes, or until charred all over and cooked through.","images":[],"step":2},{"title":"Stovetop","description":"Boil a large pot of water. Add the corn and boil for 10 minutes. Drain and let the corn steam dry in the colander for a few minutes. Heat a skillet with 1 tbsp of olive oil over high heat. Add the corn and cook all over until nicely charred.","duration":10,"images":[],"step":3},{"description":"Allow the corn to cool slightly.","images":[],"step":4},{"description":"Place the parmesan in a shallow dish.","images":[],"step":5},{"description":"Use a pastry brush to generously slather each corn with the Chipotle Adobo Mayo.","images":[],"step":6},{"description":"Roll the corn in the parmesan.","images":[],"step":7},{"description":"Sprinkle with a pinch of ancho chili powder, and serve with lime wedges on the side.","images":[],"step":8}]', '["egg","milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Mexican"],"categories":["all-vegetable-sides","australia-day","corn","dietary","easter-sides-warm-hearty","gluten-free-recipes","grilling-ideas-and-recipes","mexican-recipes","quick-and-easy","side-dishes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a2da897632e1', 'en', 'US', 'Roasted Cauliflower with Almond Sauce (Ester Restaurant)', 'This is a signature dish from Ester restaurant in Sydney, Australia which is one of the top restaurants in Australia, as well as being one of the trendiest. The recipe was provided by the restaurant to Gourmet Traveller Australia which is where I found it. The restaurant chargrills it in an enormous wood fired oven. I don''t have one of those in my tiny kitchen but the chargrill flavour is easy to recreate using the grill/broiler. I''ve provided two alternative sauce options because the almond sauce is quite rich and also sometimes I can''t be bothered to pull out my food processor to make the sauce. :)', 'https://www.recipetineats.com/tachyon/2015/03/Roasted-Cauliflower-Almond-Sauce-1_680px.jpg', 15, 15, 30, 4, '[{"id": "ing_almonds", "quantity": {"value": 0.3, "unit": "pack of 250g"}}, {"id": "ing_water", "quantity": {"value": 0.167, "unit": "L"}}, {"id": "ing_extra_virgin_olive_oil", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_cauliflower", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_almonds", "quantity": {"value": 0.3, "unit": "pack of 250g"}}, {"id": "ing_mint", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["1 cup almond meal","2/3 cup water","3/4 cup + 1 tbsp extra virgin olive oil (, separated)","2 tbsp brown rice vinegar (or rice vinegar or apple cider vinegar)","2 egg yolks","1 tsp salt (plus more to taste)","Black pepper"],"purpose":"Almond Sauce"},{"ingredients":["1 large head of cauliflower (Note 1)","2 tbsp extra virgin olive oil","1/2 lemon (, juice only)","Salt and pepper","1/2 cup almonds (, roughly chopped and lightly toasted in a dry frypan)","1/2 cup fresh mint leaves (packed)"],"purpose":"Roasted Cauliflower"}]', '[{"description":"Place the almond meal, water and 2 tbsp of olive oil in a small saucepan over medium heat. Heat until the almond meal starts to swell - around 2 to 3 minutes.","images":[],"step":1},{"description":"Pour the almond mixture into a blender or small food processor and whiz until smooth. Add brown rice vinegar and salt and whizz to mix.","images":[],"step":2},{"description":"With the blender running, add the egg yolks then pour the oil in a thin stream. Keep whizzing while you pour and the sauce will become thick and creamy. Taste to check the salt and pepper, then set aside (keep at room temperature).","images":[],"step":3},{"description":"Roasted Cauliflower","images":[],"step":4},{"description":"Cut the cauliflower into quarters (leaving most of the outer leaves on). Cut off a bit of the core, otherwise it won''t cook through because it is thicker (see photo below).","images":[],"step":5},{"description":"Bring a large pot of water to boil. Add the cauliflower, bring back to boil then boil for 3 minutes. (Alternatively you could steam it.)","duration":3,"images":[],"step":6},{"description":"Drain and leave the cauliflower to steam dry for 10 minutes. It also continues cooking.","duration":10,"images":[],"step":7},{"description":"Preheat the grill/broiler on high and place the rack around 20cm/8\" from the heat source.","images":[],"step":8},{"description":"Drizzle the cauliflower with olive oil then place under the grill/broiler for 5 minutes until nicely charred, then turn the cauliflower and char the other side for a few minutes.","duration":5,"images":[],"step":9},{"description":"Remove the cauliflower from under the grill/broiler and drizzle with lemon juice and sprinkle with salt and pepper.","images":[],"step":10},{"description":"To Serve","images":[],"step":11},{"description":"Spread about 3/4 cup of the Almond Sauce on a plate. Place the cauliflower on top, sprinkle over the almonds and mint.","images":[],"step":12},{"description":"This can be served warm or at room temperature.","images":[],"step":13}]', '["egg","nuts"]', '["gluten_free","keto_friendly","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["all-vegetable-sides","cauliflower","dietary","easter-sides-warm-hearty","gluten-free-recipes","main-dishes","roasts","side-dishes","sunday-supper","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c3e5cb1c04ca', 'en', 'US', 'Truly Crunchy Roast Potatoes', 'Roast potatoes that have a thick, crunchy crust and are soft and fluffy on the inside. Based on a Nigella Lawson recipe, except she uses goose fat instead of cooking oil. Directions for her recipe are included in the notes. You can cut down on the fat if you want, but the less the oil, the thinner the crunchy crust and the less crunchy it will be. I do not recommend reducing it less than 1/3 cup. These potatoes are the perfect accompaniment to the Slow Roasted Rosemary Garlic Lamb Shoulder and can be made while the lamb is resting.', 'https://www.recipetineats.com/tachyon/2015/02/DSC_0038.jpg', 15, 60, 75, 6, '[{"id": "ing_oil", "quantity": {"value": 100.0, "unit": "bottle"}}, {"id": "ing_potato", "quantity": {"value": 3.0, "unit": "bag of 2kg"}}, {"id": "ing_semolina", "quantity": {"value": 30.0, "unit": "pack"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}]', '[{"ingredients":["2/3 cup / 165 ml oil - it must be one of the following: Safflower Oil","3 lb / 1.5 kg potatoes (Note 2)","2 tbsp semolina (best substitute is polenta)","2 tsp salt (increase to 3 tsp if you have a salty palette) (Note 3)"]}]', '[{"description":"Pour the oil in a metal or cast iron baking dish and place in the oven. Crank up your oven to as high as it will go (mine is 250C/480F fan forced).","images":[],"step":1},{"description":"Boil a large pot of water. Peel and cut the potatoes into large pieces, about 6cm/2.2\" wide. (Note 4)","images":[],"step":2},{"description":"Boil the potatoes for 10 minutes. Drain then return to the pot.","duration":10,"images":[],"step":3},{"description":"Scatter over the semolina and salt. Clamp the lid on and give the pot 5 good shakes to rough up the potatoes. Leave the lid on and set aside.","images":[],"step":4},{"description":"The oil should be hot enough by the time the oven comes to temperature. Test it by tossing in a pinch of potato - it should sizzle straight away.","images":[],"step":5},{"description":"Pour the potatoes in (be careful of oil splashing). Working quickly, use an egg flip to toss the potatoes in the oil, spread them out as best you can then put the pan to the oven.","images":[],"step":6},{"description":"Turn the oven down to 220C/425F. Roast for around 50 minutes, possibly up to 1 hr 15 minutes (Note 5), turning once during baking. They are ready when they are a golden brown with some browned edges and they are crunchy. (Note 6)","images":[],"step":7},{"description":"Serve immediately! They will stay crunchy for around 30 minutes, but the faster you get them on the table, the better! They also crisp up pretty well when reheated - reheat @220C/425F for around 15 minutes (from room temp, add 5 min from fridge).","images":[],"step":8}]', '[]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["all-vegetable-sides","dietary","easter-recipes","easter-sides-warm-hearty","gluten-free-recipes","main-dishes","most-popular","potato-recipes","potatoes","roasts","side-dishes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c6a16607664b', 'en', 'US', 'Make Ahead Mashed Potatoes (Restaurant Trick)', 'Make-ahead mashed potatoes are super handy for busy holiday festivities! The trick with creamy mashed potatoes is simple - more cream, more butter!', 'https://www.recipetineats.com/tachyon/2014/12/Creamy-Make-Ahead-Mashed-Potato_1.jpg', 10, 15, 25, 5, '[{"id": "ing_potato", "quantity": {"value": 2.0, "unit": "bag of 2kg"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_chives", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["2 lb / 1 kg starchy potatoes (Note 1)","1 cup / 250 ml cream (, half and half or milk (Note 2))","60g / 1/4 cup butter","Salt and pepper"]},{"ingredients":["Olive oil","Chives (, finely chopped)","Pepper"],"purpose":"To Serve"}]', '[{"description":"Peel and cut the potatoes into large chunks.","images":[],"step":1},{"description":"Bring a pot of water to the boil, then add the potatoes. Cook for 20 minutes until soft and starting to fall apart.","duration":20,"images":[],"step":2},{"description":"Drain then tip back into the pot placed over the stove (turned off). Allow to steam dry for a few minutes.","images":[],"step":3},{"description":"Mash to your taste. Do NOT use a hand held mixer, blender or food processor - it will activate the starches in the potatoes and make it gluey.","images":[],"step":4},{"description":"To make ahead, transfer to a bowl and cover with cling wrap, pressing onto the potato to remove as much air as possible. Refrigerate up to 2 days until required.","images":[],"step":5},{"description":"On the day of, place the cream and butter in a pot and bring to a boil. Turn the stove off but leave the pot on the stove. Add the potatoes and stir into the cream.","images":[],"step":6},{"description":"If you want to make your potatoes creamier, push them to the side, add more cream/milk, turn the stove on, bring to a simmer then stir.","images":[],"step":7},{"description":"Season with salt and pepper.","images":[],"step":8},{"description":"Serve warm, garnished with chopped chives, a drizzle of olive oil and pepper.","images":[],"step":9}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["all-vegetable-sides","dietary","easter-sides-warm-hearty","gluten-free-recipes","potato-recipes","potatoes","quick-and-easy","side-dishes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f238a63fd25d', 'en', 'US', 'Warm Red Cabbage Salad with Garlic Herb Butter', 'This salad will add a splash of colour to any table! It takes minutes to make and takes the humble cabbage to a whole new level. The tiny splash of balsamic vinegar really makes an incredible difference. A great tip I picked up from Jamie Oliver!', 'https://www.recipetineats.com/tachyon/2014/12/Christmas-Sides-626-1.jpg', 10, 5, 15, 4, '[{"id": "ing_spinach", "quantity": {"value": 0.5, "unit": "bag of 250g"}}, {"id": "ing_red_cabbage", "quantity": {"value": 0.25, "unit": "head"}}, {"id": "ing_butter", "quantity": {"value": 2.5, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_herbs", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_balsamic_vinegar", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_pistachios", "quantity": {"value": 3.0, "unit": "unit"}}]', '[{"ingredients":["1/2 bunch English spinach leaves (, sliced into 1cm / 1/2 inch strips)","1/4 red cabbage (, cut into 2.5 x 5cm / 1 x 2\" rectangles (Note 1))","2 1/2 tbsp unsalted butter","1 garlic clove ((large), minced)","1 tbsp fresh chopped herbs (, your choice (I used thyme, rosemary and parsley))","1 tsp balsamic vinegar","1 tsp salt","3 tbsp pistachios (, roughly chopped)"]}]', '[{"description":"Place the butter and garlic in a fry pan over medium high heat.","images":[],"step":1},{"description":"Once melted, leave to sizzle for 15 seconds to allow the garlic to infuse the butter. Then add the salt and herbs, and swirl the pan to spread throughout the butter.","duration":0.25,"images":[],"step":2},{"description":"Add the cabbage and cook, tossing in the butter to coat the leaves.","images":[],"step":3},{"description":"Once the cabbage just starts to wilt, remove from the heat. Add the spinach and balsamic vinegar. Toss so the residual heat wilts the spinach slightly and the balsamic vinegar tosses through.","images":[],"step":4},{"description":"Transfer onto a serving plate and scatter over pistachios. Serve immediately.","images":[],"step":5}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["lunch"],"cuisine":[],"categories":["all-vegetable-sides","cabbage","dietary","easter-sides-warm-hearty","gluten-free-recipes","quick-and-easy","side-salads","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d27453f81f6c', 'en', 'US', 'Vegetarian Garlic Stuffed Mushrooms', 'These mushrooms are a great side for 4, a light meal for 2 or as an appetiser to pass around at a party because they are small enough to be eaten whole. They are best served warm but still delicious at room temperature. Refer to the notes for directions to prepare ahead. Love loading it up with great garlic flavour!', 'https://www.recipetineats.com/tachyon/2014/10/DSC_0262.jpg', 5, 15, 20, 2, '[{"id": "ing_mushroom", "quantity": {"value": 0.283, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_bread", "quantity": {"value": 0.094, "unit": "loaf"}}, {"id": "ing_garlic", "quantity": {"value": 1000.0, "unit": "pack of 3 heads"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["10 oz / 300 g button mushrooms","3 tbsp olive oil","1/2 cup panko breadcrumbs (note 1)","3 large garlic cloves (, minced)","1 tbsp finely chopped parsley","1/2 tbsp fresh thyme leaves (, chopped (or 1/4 tsp dried thyme) (see notes))","2 to 3 pinches of salt (to your taste)","Black pepper"]}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Break the stalks off the mushrooms, being careful to keep the caps in one piece.","images":[],"step":2},{"description":"Pile the caps into a baking dish or tray. Drizzle over 1 tbsp olive oil and toss to coat. Spread the mushrooms out on the tray, cup side up.","images":[],"step":3},{"description":"Finely chop the stalks.","images":[],"step":4},{"description":"Heat 1 tbsp olive oil in a fry pan over medium high heat.","images":[],"step":5},{"description":"Add the mushroom stalks and garlic and sauté for 1 1/2 to 2 minutes until softened.","images":[],"step":6},{"description":"Add the panko bread crumbs and sauté for 1 to 2 minutes until it becomes a light golden colour.","duration":1.5,"images":[],"step":7},{"description":"Remove pan from heat and toss through salt, pepper, parsley and thyme leaves.","images":[],"step":8},{"description":"Use a teaspoon to spoon panko filling into each mushroom cup. Don''t worry about spillage! Just pile the filling into each cup as well as you can.","images":[],"step":9},{"description":"Drizzle over remaining 1 tbsp of olive oil and bake for approximately 10 minutes, or until the mushrooms are softened (but not soft. They will go soggy and lose their shape).","images":[],"step":10},{"description":"Serve warm or at room temperature.","images":[],"step":11}]', '[]', '["gluten_free","keto_friendly","low_calorie","vegan","vegetarian"]', '{"mealType":["lunch"],"cuisine":[],"categories":["all-vegetable-sides","dietary","easter-sides-warm-hearty","finger-food","gluten-free-recipes","mushroom-recipes","mushrooms","quick-and-easy","side-dishes","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_19f13d87295c', 'en', 'US', 'Cinnamon Roasted Pumpkin', 'The flavour combination of caramelised roasted pumpkin with cinnamon is stellar and set off perfectly with tangy, creamy yoghurt and bursts of nutty crunch from the pine nuts. Simple to make, satisfying enough to have as a meal or a great side to accompany chicken, beef or lamb.', 'https://www.recipetineats.com/tachyon/2014/07/Cinnamon-Roasted-Pumpkin-2.jpg', 10, 30, 40, 4, '[{"id": "ing_pumpkin", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_cinnamon", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.15, "unit": "tub of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.5, "unit": "net of 500g"}}, {"id": "ing_pine_nuts", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1/4 Jap Pumpkin ((1 kg / 2lb), unpeeled, deseeded, cut into 6 wedges)","3 tbsp olive oil","1 tsp cinnamon","1/4 salt","Black pepper"],"purpose":"Roasted Pumpkin"},{"ingredients":["1/2 cup plain greek yoghurt (, loosened with a bit of water)","1/4 lemon","1 tbsp pine nuts (, toasted)","1 tbsp coriander leaves","1 birds eye chilli (, finely sliced)"],"purpose":"Garnish"}]', '[{"description":"Preheat oven to 200C/390F.","images":[],"step":1},{"description":"Combine olive oil, cinnamon, salt and pepper in a shallow dish large enough to fit the pumpkin wedges. Even a plate will work, it just needs to be large enough to lay the pumpkin wedge flat.","images":[],"step":2},{"description":"Place each side of the pumpkin wedge in the olive oil mixture, using your hands if needed to spread the cinnamon over each piece, including on the skin. Place pumpkin on baking tray and drizzle over any remaining olive oil.","images":[],"step":3},{"description":"Bake for 20 to 30 minutes until the pumpkin is golden and cooked through (no need to turn). (See notes on cooking tips)","duration":25,"images":[],"step":4},{"description":"When the pumpkin is cooked, remove from baking tray and place on serving platter. Drizzle over lemon juice. Rest for 5 to 10 minutes before garnishing.","duration":7.5,"images":[],"step":5},{"description":"If you are making it ahead, let it come to room temperature before putting on the other garnishes.","images":[],"step":6},{"description":"To serve, season with extra salt and pepper, drizzle over the yoghurt, scatter over pine nuts, coriander leaves and chilli.","images":[],"step":7}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner","lunch"],"cuisine":["Contemporary Middle Eastern"],"categories":["all-vegetable-sides","cuisines","easter-sides-warm-hearty","middle-eastern-recipes","pumpkin","pumpkin-squash","quick-and-easy","side-dishes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4c234ed40853', 'en', 'US', 'Middle Eastern Roasted Eggplant with Couscous', 'Eggplant slathered in a fragrant chermoula paste, then roasted until soft and gooey, and piled high with a fresh couscous. Easy to prepare and absolutely divine. This is satisfying enough to be a meal on its own with just a very simple side salad. The recipe makes about twice the amount of couscous you actually need, but it''s difficult to make in a smaller quantity and also extra couscous on the side makes this a more complete meal. The couscous is versatile and you can easily add your own touch to it. Capers would be lovely, as would crumbled feta, sundried tomatoes, fresh tomatoes and cucumber.', 'https://www.recipetineats.com/tachyon/2014/06/Eggplant-Couscous-2-Version-2-680x1024-1.jpg', 15, 40, 55, 4, '[{"id": "ing_egg", "quantity": {"value": 0.167, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_couscous", "quantity": {"value": 112.5, "unit": "pack"}}, {"id": "ing_sultanas", "quantity": {"value": 0.25, "unit": "unit"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_olives", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_almonds", "quantity": {"value": 0.15, "unit": "pack of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.75, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.06, "unit": "L"}}]', '[{"ingredients":["2 medium eggplants"]},{"ingredients":["2 garlic cloves (, crushed)","2 tsp ground cumin","2 tsp ground coriander","1 tsp chilli flakes","1 tsp paprika","Rind of 1 medium lemon","4 tbsp olive oil","1/2 tsp salt"],"purpose":"Chermoula"},{"ingredients":["1/2 tsp salt","3/4 cup couscous","1/4 cup sultanas or currants","3/4 cup boiling water","1/4 cup roughly chopped green olives","1/4 cup flaked almonds (, dry toasted on stove or in oven)","1/4 cup scallions or spring onion (, chopped)","1/4 cup chopped cilantro (coriander) and mint (1/4 cup together)","Black pepper","Juice of 1/2 lemon","2 tbsp extra virgin olive oil"],"purpose":"Couscous"}]', '[{"description":"Preheat the oven to 350F/180C.","images":[],"step":1},{"description":"Slice the eggplant lengthwise, then use small knife to make diagonal criss cross scores deep into the eggplant, making sure you don''t cut the skin. (See notes)","images":[],"step":2},{"description":"Combine the chermoula ingredients and mix into a paste. Slather onto the eggplant.","images":[],"step":3},{"description":"Place on baking tray, flesh side up, and roast for 40 minutes until completely soft. The cooking time will vary depending on the size of the eggplant you are using.","duration":40,"images":[],"step":4},{"description":"Place the couscous, salt and sultanas into a bowl, add the boiling water and cover for 5 minutes.","duration":5,"images":[],"step":5},{"description":"Fluff the couscous with a fork, add the remaining ingredients and toss through to combine. Adjust seasoning to your taste.","images":[],"step":6},{"description":"To serve, pile each eggplant high with couscous, finish with a dollop of yoghurt (see notes for vegan alternative) and garnish with cilantro. Best served warm but also delicious at room temperature.","images":[],"step":7}]', '["gluten"]', '["vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern"],"categories":["all-vegetable-sides","cuisines","eggplant","middle-eastern-recipes","quick-and-easy","side-dishes","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_32be45094d73', 'en', 'US', 'Popcorn chicken - better than KFC!', 'Recipe video above. This is better than KFC because it''s actually crispy - KFC popcorn chicken is not, it''s soft and greasy! The flavour is remarkably similar with my copycat of the KFC''s 11 secret herbs and spices. It''s ridiculously good - you want to shovel it in your mouth by the handful!Relatively straightforward and on the easy end of frying recipes because it''s just shallow fried and takes just 2 minutes. Serve in cups or mini popcorn boxes with Honey Mustard Dipping Sauce for a fun meal or snack that everyone loves! Air fryer and baking options - not covered in this recipe, please see FAQ above for reason.', 'https://www.recipetineats.com/tachyon/2025/01/Popcorn-chicken_2-close-up.jpg', 25, 10, 35, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 0.75, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_flour", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.188, "unit": "pack of 400g"}}, {"id": "ing_celery", "quantity": {"value": 0.05, "unit": "head"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.013, "unit": "jar of 200g"}}, {"id": "ing_ginger", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_oil", "quantity": {"value": 2.5, "unit": "bottle"}}, {"id": "ing_mustard", "quantity": {"value": 0.013, "unit": "jar of 200g"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["500g / 1lb chicken breast (, skinless boneless, tenderloin or boneless thighs (Note 1))"]},{"ingredients":["3/4 cup buttermilk (Note 2 for yogurt/milk sub)","1 1/2 tsp cooking salt / kosher salt (Note 3)","1 large egg (~50 - 55g, 2 oz in shell)"],"purpose":"Buttermilk marinade:"},{"ingredients":["1 1/2 cups flour (, plain / all purpose)","1/2 cup corn flour / cornstarch (makes it crispy!)"],"purpose":"Popcorn Chicken Breading (Note 4):"},{"ingredients":["1 tsp cooking salt / kosher salt (Note 3)","1/2 tsp celery salt (sub 1/4 tsp extra salt)","1 tsp black pepper","1 tsp regular paprika (aka sweet paprika, not hot or smoked)","1 tsp dried thyme (, crushed with fingers to make it finer)","1 tsp dried oregano (, crushed with fingers to make it finer)","3/4 tsp onion powder","2 tsp garlic powder","1/2 tsp mustard powder","1/2 tsp ginger powder","1/4 tsp cayenne pepper (, optional (tiniest background warmth, doesn''t make it spicy))"],"purpose":"KFC 11 Secret Herbs and Spices (Note 4):"},{"ingredients":["2 1/2 - 3 1/2 cups canola oil (2.5 cm / 1\" depth) (, or vegetable or peanut oil (Note 8 for re-use))"],"purpose":"To fry:"},{"ingredients":["1/2 batch Honey mustard dipping sauce (pictured in post)","Ketchup, tomato sauce,"],"purpose":"Dipping sauce suggestions"}]', '[{"description":"Abbreviated directions:","images":[],"step":1},{"description":"Marinade chicken 1 hour+ in Buttermilk Marinade. Dribble then rub 3 tbsp marinade in breading to make small clumps. Dredge chicken, fry 2 minutes at 180C/350F.","images":[],"step":2},{"description":"Marinade chicken:","images":[],"step":3},{"description":"Cut chicken into small 1.25 cm / 1/2\" cubes.","images":[],"step":4},{"title":"Marinade","description":"Whisk marinade in a bowl. Add chicken, stir to coat, then refrigerate for 1 hour (no longer than 24 hours).","images":[],"step":5},{"description":"Prepare breading:","images":[],"step":6},{"title":"Breading mixture","description":"Mix together Breading and all KFC Secret Herbs & Spices in a large bowl (larger surface area = coat more chicken in one go).","images":[],"step":7},{"description":"Clump = crunchy! Drizzle 3 tablespoons of the Marinade into the flour mixture. Use your fingers to rub in so you get lots of small lumpy bits all throughout (this fries up into extra crunchy bits, secret trick!).","images":[],"step":8},{"description":"Prepare to cook (work in specified order of steps):","images":[],"step":9},{"title":"Frying vessel (Note 5)","description":"Large saucepan / small pot ~20cm/8\" recommended for beginners. Large pot / deep skillet ~24cm/9.5\" or larger recommended only for capable cooks. Use heavy based (not light and flimsy), for safety and heat retention.","images":[],"step":10},{"description":"Preheat oven to 50°C/125°F, to keep cooked chicken warm.","images":[],"step":11},{"description":"Breading (PS I''m right handed):","images":[],"step":12},{"title":"Bread chicken","description":"Pick up a handful of chicken from the marinade with your left hand, then scatter across surface of the flour mixture. Spoon flour over chicken then toss with the spoon to coat.","images":[],"step":13},{"title":"Shake off excess (use right hand)","description":"Separate the chicken pieces and press the clumpy flour onto the chicken pieces. Pick up a handful, shake excess flour off through fingers (no need to be thorough). Spread chicken on tray. Repeat with remaining chicken. Voila! No clumpy flour-batter-caked fingers!","images":[],"step":14},{"title":"Separate and last minute coat (Note 6)","description":"Just before frying, use your fingers to briefly re-toss the chicken you''re about to cook in the residual flour on the tray (to freshen up the flour coating, as it sits around it sweats/gets wet), and make sure the chicken pieces are not stuck together.","images":[],"step":15},{"description":"Line a tray with paper towels (for draining cooked chicken). Preheat oven to 50°C/125°F to keep cooked chicken warm.","images":[],"step":16},{"title":"Heat oil","description":"Add oil to your pot to a depth of 2.5 cm / 1\". Heat it over medium high to 180°C/350°F (Note 7).","images":[],"step":17},{"title":"Fry 2 minutes","description":"Pick up some chicken and put it in a spider with large holes (Note 8) and shake so excess flour falls through (or use hands to shake off excess flour then then transfer into a scoop to lower into oil). Carefully lower chicken into the oil. Fry for 2 - 2.5 minutes until golden, separating any that get stuck together around halfway through.","images":[],"step":18},{"title":"Drain","description":"Scoop out with a spider and spread on a paper towel lined tray Keep cooked chicken warm in the oven and cook remaining chicken.","images":[],"step":19},{"title":"Serve chicken","description":"in popcorn boxes, for extra fun factor! - with dipping sauce of choice (pictured, Honey Mustard).","images":[],"step":20}]', '["egg","gluten","milk","mustard","peanuts"]', '["high_protein","keto_friendly","low_calorie"]', '{"mealType":["dinner","snack"],"cuisine":["Southern","Western"],"categories":["american","chicken-breast-recipes","chicken-recipes","deep-fried-recipes","snacks"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_28f5dd915897', 'en', 'US', 'Chili dogs', 'Recipe video above. A pan-fried or BBQ sausage smothered in chili sauce in a hot dog bun. Cracker of a recipe for summer BBQ''s, gatherings with friends and game-day! My chili sauce is a copy-cat of the famous Ben''s Chili Bowl half-smoke chili dogs in Washington DC. Love how their boldly spiced chili sauce is thick and almost "smooth", so it stays in the hot dog better. I replicated this by blitzing the chili a bit. Releases flavour, thickens the sauce. Win!Also, skip the cheap hot dog "footy franks". Do what Ben''s does - use a good smoked sausage.', 'https://www.recipetineats.com/tachyon/2023/02/Chili-dog.jpg', 20, 210, 230, 6, '[{"id": "ing_smoked_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_mustard", "quantity": {"value": 0.013, "unit": "jar of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 2.5, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 7.5, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_sausages", "quantity": {"value": 0.012, "unit": "pack of 500g"}}, {"id": "ing_bread", "quantity": {"value": 6.0, "unit": "loaf"}}, {"id": "ing_onion", "quantity": {"value": 7.5, "unit": "pack of 1kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.013, "unit": "jar of 200g"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}]', '[{"ingredients":["3 tsp smoked paprika (sub plain paprika)","3 tsp cumin powder","1 tsp cayenne pepper (, adjust to taste)","1 1/2 tsp garlic powder","1 1/2 tsp onion powder","1 1/2 tsp oregano","1/2 tsp mustard powder","1/2 tsp black pepper"],"purpose":"Homemade chili powder (Note 1):"},{"ingredients":["1 tbsp olive oil","2 garlic cloves (, finely minced)","1/2 onion (, finely chopped)","1/2 red capsicum / bell pepper (, finely chopped)","500 g/1 lb ground beef / beef mince","1 tbsp tomato paste","400g / 14 oz canned crushed tomato","2 beef cubes (I like Oxo, easy to crumble, Note 2)","1 1/2 cups water","3/4 tsp cooking/kosher salt (, plus more to taste)"],"purpose":"Chili sauce:"},{"ingredients":["6 good smoked sausages (kransky, bratwurst, half-smoke) or hot dogs of choice (Note 3)","6 hot dog buns","1/2 white onion (, finely chopped)","Yellow mustard (I use Heinz American mustard)","2 cups Colby or Monterey Jack (, shredded (or other cheese of choice))","Plain crinkle cut potato chips (, optional side for serving (traditional!))"],"purpose":"Chili dogs:"}]', '[{"title":"Sauté aromatics","description":"Heat oil over medium high in a heavy based pot. Cook the onion, garlic and capsicum for 3 minutes.","duration":3,"images":[],"step":1},{"title":"Brown beef","description":"Add beef and cook, breaking it up as you go, until you no longer see raw meat. Add tomato paste and stir for 1 minute.","duration":1,"images":[],"step":2},{"title":"Sauce","description":"Add the spices, tomato, water, crumbled beef cube and salt. Stir well.","images":[],"step":3},{"title":"Slow cook 3 hours","description":"Bring the chili to a simmer then turn down to low, on a small burner. Put the lid partially on (to allow for sauce reduction). Simmer for 3 hours on low (goal: small bubble every now and then), stirring just to ensure the base doesn’t catch. OR put it in a 160°C/325°F oven for 3 hours (lid partially cracked).","images":[],"step":4},{"title":"Slow cooker (Note 4)","description":"Reduce water to 3/4 cup. After chili comes to a simmer on the stove, transfer everything to a slow cooker then cook on low for 6 to 8 hours on low.","images":[],"step":5},{"title":"Thicken sauce","description":"Remove 1 1/2 cups of the chili into a container so the head of a stick blender will be submerged under the chili. Then blitz until smooth (~ 15 seconds). Add the pureed sauce back in the pot and stir well.","images":[],"step":6},{"title":"Sauce goal","description":"As you stir, the remaining beef bits should become quite fine (rather than bolognese type chunks) because the beef is so tender. If the beef bits are not as small as desired, use a potato masher in the pot - it won''t take long. The chili sauce should be a thick sauce that mounds up a bit when you scoop it, not runny. (Note 5) Keep sauce warm.","images":[],"step":7},{"title":"Optional rest overnight","description":"Allow the sauce to cool then refrigerate overnight. As with most slow-cooked stewy things, the flavour improves! Reheat on the stove before proceeding.","images":[],"step":8},{"description":"Preheat oven to 180°C/350°F (160°C fan).","images":[],"step":9},{"title":"Grill/pan-fry","description":"Preheat a pan with 1/2 tbsp oil (or the BBQ) on medium / medium high. Brown the stages all over until they are heated through (they are already cooked inside, it''s just about heating/colour).","images":[],"step":10},{"title":"Assemble","description":"Place hot dog buns on a tray. Stuff with a sausage, top with a squiggle of mustard and a sprinkle of onion. Spoon over a generous amount of warm chili sauce, top with cheese.","images":[],"step":11},{"description":"Bake for 7 to 10 minutes or until the cheese is melted. Serve immediately. Traditionally with a mound of plain crinkle cut potato chips and an ice cold beer!","duration":8.5,"images":[],"step":12}]', '["milk","mustard"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["American","Tex-Mex"],"categories":["american","beef","beef-mince-recipes","beef-recipes","grilling-ideas-and-recipes","mains","sandwiches-and-sliders","sausage-recipes","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ef8334721dda', 'en', 'US', 'My best Pulled Pork', 'Recipe video above. This takes 36 hours to make - but it''s worth it. A 24-hour dry brine seasons the pork all the way through, followed by slow-roasting for 12 hours at a really low temperature. I would not tell you to roast a pork for 12 whole hours if I was not 100% sure that this produces the very best results! It really does, and the reason is simple: lower heat means less moisture loss which means more succulent meat. Plus, a great bark on the surface that everybody loves about traditional BBQ food. It’s my favourite part!', 'https://www.recipetineats.com/tachyon/2022/10/12-hour-BBQ-pulled-pork_7-3.jpg', 15, 720, 735, 15, '[{"id": "ing_pork_shoulder", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_beer", "quantity": {"value": 1.136, "unit": "bottle of 330ml"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.09, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.75, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.2, "unit": "jar of 50g"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.5, "unit": "bottle of 500ml"}}, {"id": "ing_ketchup", "quantity": {"value": 0.9, "unit": "bottle of 500g"}}, {"id": "ing_molasses", "quantity": {"value": 45.0, "unit": "jar"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 20.0, "unit": "bottle"}}, {"id": "ing_tabasco", "quantity": {"value": 2.0, "unit": "unit"}}]', '[{"ingredients":["4 - 5 kg / 8 - 10 lb pork butt / Boston butt / square cut pork shoulder (skinless, bone in, fat cap on, Note 1)","1 1/2 cups beer (, any except dark beers like Guinness (Note 2))","1 cup water"]},{"ingredients":["6 tbsp brown sugar","2 tbsp paprika powder","1 tbsp garlic powder","1 tbsp onion powder","1 tbsp mustard powder","2 tsp cumin powder","2 tsp dried oregano","1 tsp cayenne pepper (can omit)","2 tbsp cooking/kosher salt* (Note 4)","2 tsp black pepper"],"purpose":"RUB (Note 3):"},{"ingredients":["1 cup apple cider vinegar (Note 5)","3 cups ketchup (or Aussie tomato sauce)","1 cup water","3 tbsp molasses (original, not backstrap, Note 6)","2/3 cup brown sugar","4 tsp Worcestershire sauce","2 tsp Tabasco (optional spiciness)","4 tsp mustard powder","3 tsp garlic powder (sub onion powder)","2 tsp cooking/kosher salt (Note 4)","2 tsp black pepper"],"purpose":"BARBECUE SAUCE:"}]', '[{"title":"Dry brine overnight (Note 7)","description":"Pat the pork dry and place in a large ceramic dish. Mix Brine ingredients in a small bowl and rub it all over the pork, being sure to get into the cracks and crevices. Turn it fat side up (smoother side) covered with as much rub as possible. Refrigerate uncovered for 24 hours.","images":[],"step":1},{"description":"Preheat oven to 110°C (both fan-forced and standard) / 230°F.","images":[],"step":2},{"title":"Prepare for roasting","description":"Transfer pork to a roasting pan (do not wipe the rub off) with the fat side up. Discard any liquid and residual rub left in the brining dish. Pour beer and water around the pork, topping up with extra water as needed so the liquid level is 2.5 cm / 1\" (insurance against pan going dry).","images":[],"step":3},{"title":"Slow roast 12 hours (Note 8)","description":"Roast, uncovered, for 12 hours, or until the internal temperature reaches 95°C/203°F and the meat falls apart effortlessly using two forks. ⚠️ Make sure your oven does not automatically turn off mid cook, many have auto-off functions that kick in at 12 hours (also factor in oven pre-heating time)!","images":[],"step":4},{"title":"Shred","description":"Transfer the pork to a large pan (reserve juices in roasting pan). Rest for 20 minutes then shred with tongs / forks - it will be effortless! You can discard the fat cap at this stage if you want. I leave some, it makes the shredded pork even juicier.","duration":20,"images":[],"step":5},{"title":"Sauce it","description":"Pour 3/4 cup of the juices from the roasting pan and 1 cup of Barbecue Sauce (see below) over the pork, and toss.","images":[],"step":6},{"description":"Serve Pulled Pork with remaining Barbecue Sauce on the side so people can help themselves. Either make a big Southern feast with a side of cornbread, coleslaw and potato salad or macaroni salad. Or make Pulled Pork buns with soft rolls stuffed with coleslaw, Pulled Pork and the BBQ sauce!","images":[],"step":7},{"description":"Barbecue sauce:","images":[],"step":8},{"description":"Place ingredients in a large saucepan and whisk to combine.","images":[],"step":9},{"title":"Simmer 45 minutes","description":"Bring to simmer on medium heat, then reduce to a low simmer for 45 minutes. Stir occasionally.","duration":45,"images":[],"step":10},{"title":"Add pork juices","description":"When the pork is cooked, add 1/2 cup of the juices from the roasting pan into the BBQ sauce and simmer for 5 minutes. Use water to control thickness – it should have a thick syrupy consistency. Serve warm or at room temperature (not fridge cold).","duration":5,"images":[],"step":11}]', '["mustard"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Southern"],"categories":["american","iconic-dishes","main-dishes","mains","pork","pork-recipes","slow-cooked-fall-apart","sunday-supper","super-bowl-party-food","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a6efcb1570e6', 'en', 'US', 'Mapo Tofu', 'Recipe video above. Mapo Tofu is in my all-time Top 5 foods. That''s how much I love it. So I am beyond excited to bring you this Sichuan classic that is everything a great, authentic Mapo Tofu should be - fiery, deeply savoury, unapologetically bold and so incredibly delicious, I almost wept with happiness!It''s a recipe from our RTM Chef Xiao (Hannah) Huang, born and raised in Sichuan. So she knows a thing or two about Mapo Tofu! See all Hannah''s recipes here.See Notes section for spiciness and how to control.PS I know 100g/3.5oz pork doesn''t sound like a lot compared to 600g/21oz tofu, but it seems like so much more in the finished dish! Mapo tofu magic :)', 'https://www.recipetineats.com/tachyon/2026/07/Mapo-tofu-0.jpg', 20, 25, 45, 4, '[{"id": "ing_black_pepper", "quantity": {"value": 0.3, "unit": "jar of 50g"}}, {"id": "ing_tofu", "quantity": {"value": 2.0, "unit": "pack of 300g"}}, {"id": "ing_water", "quantity": {"value": 0.625, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.01, "unit": "bottle of 250ml"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_pork_mince", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 10.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_black_beans", "quantity": {"value": 0.037, "unit": "can of 400g"}}, {"id": "ing_broad_bean_sauce_paste", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_chilli", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.025, "unit": "pack of 400g"}}, {"id": "ing_white_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1 tbsp whole pink Sichuan peppercorns (or green) - for 1 tsp powder (Note 1)"]},{"ingredients":["600g/ 21 oz silken tofu (, cut into 1.5cm / 0.6\" squares (Note 2))","2 1/2 cups water","1 tsp cooking salt / kosher salt (halve for table salt, +50% for salt flakes)","1/2 tsp dark soy sauce (Note 3)"],"purpose":"Blanched tofu:"},{"ingredients":["1 tbsp canola oil (, or other neutral oil eg. vegetable, peanut)","100g/ 3.5 oz pork mince (ground pork), preferably 20% fat but even lean is fine, or beef (Note 4)","1 tsp light soy sauce (or regular / all-purpose soy, not dark soy sauce)"],"purpose":"Golden pork:"},{"ingredients":["1/4 cup canola oil (Note 5)","2 tbsp garlic (, finely minced (4 large cloves))","2 1/2 tbsp ginger (, finely minced with a knife)","1 tbsp preserved black beans (aka salted black beans, fermented black beans), finely chopped (Note 6)","1 tbsp broad bean sauce/paste (, we use Pixian doubanjiang, the spicy Sichuan version (Note 7))","1 tsp light soy sauce (or regular / all-purpose soy, not dark soy sauce)","2 tsp chilli powder (, pure - NOT US chili powder blend (Note 8))","1 tsp smoked paprika (substitute regular/sweet paprika)","1 tsp white sugar","1 green onion stem (, finely sliced)","3/4 cup beef stock/broth (, low sodium)","1 tsp sesame oil (toasted ie. brown, not un-toasted which is yellow)"],"purpose":"Mapo tofu:"},{"ingredients":["2 tsp cornflour / cornstarch","1/4 cup water"],"purpose":"Cornflour slurry"},{"ingredients":["White rice"],"purpose":"Serving"}]', '[{"description":"Toast, grind and sift Sichuan peppercorns. Blanch tofu 3 min. Cook pork until golden, remove.","images":[],"step":1},{"description":"Sauté garlic and ginger 90 sec, then black bean and bean sauce 3 min, then chilli and paprika 30 sec. Add beef stock and soy, simmer tofu 10 min. Add sugar, pork, 1/2 tsp Sichuan pepper, then thicken sauce with cornflour slurry. Stir in green onion and sesame, serve garnished with 1/2 tsp Sichuan pepper.","images":[],"step":2},{"description":"Sichuan pepper powder:","images":[],"step":3},{"title":"Toast peppercorns","description":"In a small skillet over medium heat (no oil), toast the peppercorns for 2 - 3 minutes until fragrant (some will “pop” and crack open).","duration":2.5,"images":[],"step":4},{"title":"Grind and sift","description":"Transfer to a mortar and pestle, or spice grinder. Cool for a few minutes, then grind as finely as possible. Sift through a fine mesh sieve to remove the coarser husks (discard these). Measure out 1 teaspoon to use in the dish.","images":[],"step":5},{"title":"Blanch","description":"Bring the water, dark soy and salt to a boil in a large saucepan over higher heat. Carefully add the tofu, then once it comes back up to the boil, lower the heat slightly so it’s simmering rapidly and simmer for 3 minutes. This step removes raw beany flavour and seasons the tofu. And don''t worry, the tofu won''t fall apart!","duration":3,"images":[],"step":6},{"title":"Remove","description":"Use a slotted spoon to carefully scoop the tofu out into a bowl. Set aside.","images":[],"step":7},{"title":"Cook golden pork","description":"Heat the oil in a wok over high heat. (Note 9) Cook pork, breaking it up as you go, until you no longer see pink. Then lower the heat to medium and cook for another 2 minutes until the pork has golden bits. Add the light soy sauce, stir for 5 seconds, the remove the pork into a bowl and set aside.","duration":0.08333333333333333,"images":[],"step":8},{"title":"Sauté aromatics","description":"Reduce heat to low. Add the rest of the oil into the wok, then cook the garlic and ginger for 90 seconds. Add black beans and broad bean paste, cook for 3 minutes, stirring constantly. Add chilli powder and paprika, cook for 30 seconds..","duration":1.5,"images":[],"step":9},{"title":"Simmer","description":"Add the beef stock and light soy. Turn the heat up to medium high, then once it starts bubbling, gently add the tofu (discard any excess water pooled in the tofu bowl). Simmer gently for 10 minutes (lower heat as needed), gently scraping the base with a rubber spatula every now and then to ensure it doesn’t catch (I push across base, avoid stirring as tofu will break). There should still be plenty of liquid at the end, mapo tofu is saucy.","duration":10,"images":[],"step":10},{"title":"Cornflour slurry","description":"Mix the water and cornflour together. This will thicken the sauce.","images":[],"step":11},{"title":"Thicken sauce","description":"Add the sugar, pork mince, 1/2 teaspoon sichuan powder. Stir gently using the rubber spatula. Pour the cornflour slurry all over the surface (not in one place) then gently stir again.","images":[],"step":12},{"title":"Finish and serve","description":"Stir in most of the green onion (reserve a little for garnish) and sesame oil. Pour into a serving bowl. Sprinkle with remaining Sichuan pepper and garnish with green onion. Serve over rice!","images":[],"step":13}]', '["gluten","peanuts","sesame","soy"]', '["keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese","Sichuan"],"categories":["asian-recipes","asian-takeout","chinese-recipes","iconic-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_aa9c494f8569', 'en', 'US', 'Thai Grilled Chicken (Gai Yang)', 'Recipe video above. This Thai Chicken recipe is an easy way to make Gai Yang at home, Thailand’s famous barbecue chicken. It uses a fragrant Thai marinade that delivers street-stall delicious – without pounding pastes, lighting coals or wrestling a whole chicken! Cook on the stove though it''s especially great on the BBQ.A dipping sauce isn’t essential because the marinade already brings big flavour and keeps the chicken super juicy. But in Thailand it’s traditional, so why not? Spoon it over or dunk away!Serve with Coconut Rice and swoon!', 'https://www.recipetineats.com/tachyon/2015/06/Thai-chicken-marinated-Gai-Yang_0.jpg', 8, 12, 20, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.907, "unit": "kg"}}, {"id": "ing_lemongrass", "quantity": {"value": 20.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 6.667, "unit": "pack of 3 heads"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.907, "unit": "kg"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_nam_jim_jaew", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_rice", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["2 lb / 1 kg chicken thigh fillets (skinless, boneless) (Note 1)"]},{"ingredients":["1 large lemongrass stalk (, white part only, reedy outer layers removed, sliced 5mm / 1/5\" thick (Note 2 tube paste sub))","4 cloves garlic (, peeled (whole))","2 1/2 tbsp fish sauce","1 tbsp light soy sauce (, or any all-purpose soy or tamari (Note 3))","2 tsp dark soy sauce (Note 3)","3 tbsp (tightly packed) brown sugar or palm sugar","2 tbsp oil (, vegetable, canola, or any other neutral flavoured oil)"],"purpose":"Marinade"},{"ingredients":["Nam Jim Jaew (- traditional Thai Dipping Sauce for meat *RECOMMENDED*)","Lime Sweet Chilli Sauce","Bottle of sweet chilli sauce"],"purpose":"Sauce options *optional*- CHOOSE ONE"},{"ingredients":["Lime wedges","Red chili (, finely sliced (optional))","Cilantro / coriander leaves (optional)","Coconut rice"],"purpose":"Garnishes / sides"}]', '[{"title":"Blitz","description":"Place Marinade ingredients EXCEPT oil in a jug just large enough to fit the head of a stick blender. Blitz until lemongrass and garlic is fully pureed. (No stick blender? Finely grate lemongrass and garlic, then mix)","images":[],"step":1},{"title":"Marinate","description":"Pour in a bowl. Add oil, stir. Add chicken, toss to thoroughly coat. Cover and marinate overnight (my bare minimum is 3 hours). No marinating time? Finely slice, toss in marinade then cook like a stir-fry.","images":[],"step":2},{"description":"Heat the outdoor BBQ grill on high or a non stick pan over high heat on the stove.","images":[],"step":3},{"title":"Cook","description":"Remove chicken from the Marinade and discard the Marinade (unless baking in the oven - refer Note 3). Put chicken on the BBQ or in the pan, then turn heat down to medium (sweet marinade = prone to burning). Cook the chicken until golden brown - around 5 to 6 minutes on each side. (If it burns, flip straight away. You can flip repeatedly, as needed.)","images":[],"step":4},{"title":"Rest and serve","description":"Rest for 3 minutes. Serve alongside a mound of steamy coconut rice with lime wedges, garnished with fresh chilies and coriander/cilantro, and your chosen sauce.","duration":3,"images":[],"step":5}]', '["fish","gluten","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Thai"],"categories":["asian-recipes","australia-day","chicken-breast-recipes","chicken-recipes","cuisines","dietary","gluten-free-recipes","grilling-ideas-and-recipes","modern-asian","most-popular","quick-and-easy","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0350dff8c6de', 'en', 'US', 'Easy Chinese Beef Stir Fry', 'Recipe video above. This is my classic Chinese Beef Stir Fry. It''s easy and fast, and really does taste just like your favourite Chinese restaurant thanks for the stir fry sauce (the secret is Chinese cooking wine).Great recipe to use up whatever leftover greens you have in the fridge! And you''ll love the velveting beef technique - simple and highly effective Chinese restaurant method for succulent, soft beef in stir fries.Tip: Instead of making this Sauce, you can use Charlie, my All Purpose Stir Fry Sauce (see Note 3)', 'https://www.recipetineats.com/tachyon/2015/12/Chinese-Beef-Stir-Fry_8.jpg', 15, 8, 23, 3, '[{"id": "ing_beef_steak", "quantity": {"value": 0.198, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.013, "unit": "tub of 200g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.06, "unit": "bottle of 500ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.037, "unit": "pack of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 2.5, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_bok_choy", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.04, "unit": "bunch"}}, {"id": "ing_white_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["7 oz / 200 g beef rump steak or flank (, or any other quick cooking steak cut (Note 1))","1/2 tsp baking soda / bi-carbonate soda (, for velveting (Note 2))"],"purpose":"Velveting the beef (tenderising)"},{"ingredients":["2 tbsp soy sauce, light or all-purpose (NOT dark soy (Note 4))","1 tbsp oyster sauce","2 tbsp Chinese cooking wine ( OR Mirin (Note 5))","1 tsp white sugar","1/2 tsp sesame oil (, toasted (brown) not untoasted (yellow))","Pinch white pepper (, substitute with black pepper)"],"purpose":"Sauce (Note 3)"},{"ingredients":["3 tsp cornstarch / corn flour","1/2 cup water (, separated)"],"purpose":"Sauce thickener"},{"ingredients":["1 1/2 tbsp peanut oil","1 garlic clove (, finely minced with a knife)","1/2 small onion (, sliced (yellow, brown or white))","1/2 red capsicum / bell pepper (, sliced into 7mm / 1/3\" thick slices)","1 small carrot (, peeled, halved lengthwise and sliced thinly on the diagonal)","2 bok choy (, cut leaves from stems, cut thick stems lengthways to make them all roughly the same width)","2 green onion (, cut into 1.5\"/3cm pieces, firm white end separated from soft green parts)"],"purpose":"Stir Fry"},{"ingredients":["Steamed white rice","Sesame seeds (optional)"],"purpose":"To Serve"}]', '[{"description":"Abbreviated recipe","images":[],"step":1},{"description":"Tenderise beef 20 minutes, rinse, toss with 1.5 tbsp sauce. Mix in cornflour then water into Sauce. Stir fry in this order: onion + garlic > beef > carrot + capsicum + bok choy stems + green onion stems > sauce > wilt bok choy leaves + green onion. Serve!","images":[],"step":2},{"description":"Velvet beef (tenderise)","images":[],"step":3},{"title":"Velvet beef","description":"Place the beef in a bowl. Sprinkle the baking soda over then use your fingers to toss the beef to coat as evenly as possible. Set aside for 20 minutes (no longer).","duration":20,"images":[],"step":4},{"description":"Rinse the beef under tap water in a colander to remove baking soda. Shake and pat off excess water (doesn''t need to dry fully, just don''t want it soaking). Put in a bowl.","images":[],"step":5},{"description":"Cook stir fry","images":[],"step":6},{"title":"Sauce","description":"Mix ingredients together. Measure out 1 1/2 tablespoons and use it to coat the beef. To the remaining sauce, mix in the cornflour until lump-free, then add the water.","images":[],"step":7},{"title":"Cook aromatics","description":"Heat the oil in a large non-stick pan or wok over high heat. Add the onion and garlic, cook for 10 seconds.","duration":0.16666666666666666,"images":[],"step":8},{"description":"Add the beef and cook until it changes colour from red to light brown but not cooked through.","images":[],"step":9},{"title":"Vegetables #1","description":"Add the capsicum, carrots, bok choy stems and white part of the green onions. Stir fry for 1 minute","duration":1,"images":[],"step":10},{"description":"Add Sauce, then stir until it starts to bubble (it will thicken quickly)","images":[],"step":11},{"title":"Leafy vegetables","description":"Add the bok choy leaves and green part of the green onions. Toss for another 30 seconds to 1 minute until they are just wilted, the sauce thickens and becomes glossy, coating everything nicely.","images":[],"step":12},{"title":"Serve immediately with rice","description":"or for a low carb, low cal option, try Cauliflower Rice! Garnish with sesame seeds, if desired.","images":[],"step":13}]', '["gluten","peanuts","sesame","soy"]', '["keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","beef-recipes","chinese-recipes","dinner-tonight","main-dishes","quick-and-easy","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_04b91e1bf760', 'en', 'US', 'Korean Beef Bulgogi Rice Bowls - the easy way', 'Recipe video above. This has gone straight to the top of my favourite quick way to use beef mince! An easy version of Korean Beef Bulgogi, one of Korea''s most famous food exports, made with ground beef rather than pricey steaks but using an authentic Bulgogi marinade so it takes a fraction of the effort and cost. I’ve made rice bowls, there''s many ways to serve this - noodles, rice wraps, burritos or tacos (so trendy!). See in post for list!PS Don''t skip the apple and grated onion. This is what sets bulgogi apart from generic soy + sugar + garlic "Asian" sauces!', 'https://www.recipetineats.com/tachyon/2025/09/Easy-Korean-Bulgogi-Beef-Bowls_7.jpg', 15, 10, 25, 4, '[{"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 15.0, "unit": "pack of 1kg"}}, {"id": "ing_apples", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.15, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_mirin", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_white_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_baby_spinach", "quantity": {"value": 1.0, "unit": "bag of 250g"}}, {"id": "ing_carrot", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 4.5, "unit": "head"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}]', '[{"ingredients":["500g / 1 lb beef mince ((ground beef), any fat % you like)","1 tbsp canola oil (, or any other plain flavoured oil, + 2 tsp (to wilt baby spinach))"]},{"ingredients":["1 tbsp onion (, finely grated (~1/4 onion) (Note 1))","3 tbsp red apple (, finely grated (skin on is fine, ~1/2 apple) (Note 1))","3 garlic cloves (, finely grated)","1 tsp ginger (, finely grated)","2 1/2 tbsp soy sauce ( - all-purpose or light (Note 2))","1 tbsp sesame oil","1 tbsp mirin (, omit for no alcohol (Note 3))","1 tbsp brown sugar","1/8 tsp black pepper"],"purpose":"Bulgogi sauce (don’t skip the onion & apple!):"},{"ingredients":["2 tbsp soy sauce ( - all-purpose or light (Note 2))","1 tbsp sesame oil","2 tsp brown sugar","2 tsp rice vinegar (or apple cider vinegar)"],"purpose":"Rice bowl drizzle sauce:"},{"ingredients":["white rice (medium or short grain, if you can)","4 large handfuls baby spinach (or similar chopped leafy greens - cabbage, kale)","1 large carrot (, peeled and julienned or grated using box grater (I use a julienne shredding tool))","1 avocado (, mashed)","1/4 cup pickled ginger (, I like pink for colour)","1 1/2 cups baby cos / romaine lettuce (, torn into bite size pieces)","1 tsp white sesame seeds","1 green onion (, finely sliced)"],"purpose":"For rice bowl (very flexible!):"}]', '[{"title":"Sauces","description":"Mix the Bulgogi sauce in a bowl, and the rice bowl drizzle sauce in a separate bowl.","images":[],"step":1},{"title":"Wilt spinach","description":"Heat the 2 teaspoons of oil in a large non-stick pan over high heat. Add half the spinach, toss with tongs until semi wilted (~30 sec), then add the rest. Toss until wilted (~ 1 minute) then remove into a bowl.","images":[],"step":2},{"title":"Cook Bulgogi beef","description":"Add 1 tablespoon oil to the pan. Still on high heat, add the beef and cook, breaking it up as you go, until you no longer see raw beef. Add the Bulgogi sauce, then let it simmer rapidly, stirring every now and then, until the sauce is mostly evaporated. Then stir regularly until the beef gets a bit of lovely caramelisation on it, but is still moist from the sauce.","images":[],"step":3},{"title":"Assemble","description":"Spoon beef over rice, place spinach and carrot. Top with pickled ginger and a dollop of mashed avocado. Tuck lettuce down the side. Sprinkle with sesame seeds and green onion. Serve with sauce for drizzling all over everything before jumbling it all up and digging in!","images":[],"step":4}]', '["gluten","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","korean fusion"],"categories":["asian-recipes","beef-mince-recipes","beef-recipes","modern-asian","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_004ad51c5489', 'en', 'US', 'Easy Crispy Thai Pork Bites with Sticky Sweet Chilli Sauce', 'Recipe video above. This is the sort of dish you find at modern Thai restaurants - golden cubes of pork tenderloin, crispy on the outside and succulent inside, tossed in a sticky limey, sweet chilli sauce.6 ingredients. Gluten free. No deep frying. All the flavour. None of the fuss! Dinner on the table in 20 minutes.PS Haven''t tried air frying but confident it will work great!', 'https://www.recipetineats.com/tachyon/2025/09/Crispy-Thai-Pork-Bites-Sweet-Chilli-Sauce_4.jpg', 10, 10, 20, 4, '[{"id": "ing_pork", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.056, "unit": "pack of 400g"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_chilli", "quantity": {"value": 0.75, "unit": "pack of 100g"}}, {"id": "ing_ime_juice", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 0.045, "unit": "net of 500g"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["600 g / 1.2 lb pork tenderloin (, cut into 2cm/0.8\" cubes (Note 1))","1 tbsp fish sauce (Note 2)","1 1/2 tbsp + 1/2 cup cornflour / cornstarch","> 1 cup neutral flavoured oil (, 0.5cm / 0.2\" depth (canola, sunflower, vegetable, peanut oil - not olive oil))"],"purpose":"Crispy pork bites:"},{"ingredients":["1/2 cup sweet chilli sauce (Note 3)","1 1/2 tbsp lime juice","1 tbsp fish sauce (Note 2)","2 garlic cloves (. finely grated)"],"purpose":"Sweet chilli sauce:"},{"ingredients":["Coriander/cilantro leaves (, roughly torn by hand, optional)","Lime wedges (, optional)","Jasmine rice (, or other rice of choice)"],"purpose":"Garnish and serving:"}]', '[{"description":"Toss pork with fish sauce and 1.5 tbsp cornflour, then coat in 1/2 cup cornflour, shake off excess. Cook in 2 batches for 3 min until golden, remove from oil. Simmer sauce 3 min, toss to coat pork, serve.","duration":3,"images":[],"step":1},{"description":"Toss the pork with the fish sauce, then the 1 1/2 tbsp cornflour. The coating should be a bit sticky.","images":[],"step":2},{"title":"Crispy coating","description":"Sprinkle over the 1/2 cup of cornflour and toss with fingers to coat each piece, separating pieces stuck together. Give each piece a light squeeze in your fist to make the cornflour stick - you can do 2 or 3 pieces at a time in each hand. Drop into a colander, then give it a shake to remove excess cornflour - important step. (Note 4)","images":[],"step":3},{"description":"Heat 0.5 cm / 0.2\" oil in a non-stick pan or large pot over high heat - dip a piece of pork in, it should sizzle straight away.","images":[],"step":4},{"title":"3 minute cook","description":"Spread half the pork in the oil. Cook for 1 minute undisturbed until golden. Flip then cook for another 2 minutes (3 minutes in total, including time it takes to flip) or until golden and crisp. Don''t overcook - tenderloin is lean!","duration":1,"images":[],"step":5},{"title":"Drain","description":"Remove with a slotted spoon onto a paper towel-lined tray to drain. Cook remaining pork. Taste-test one \"just to check\" crispiness! ;)","images":[],"step":6},{"title":"Sauce","description":"Pour out all the oil (strain and re-use, it''s very clean). Return the pan to medium heat. Add the Sauce ingredients, stir and let it simmer for 2 minutes until it thickens into a syrupy consistency.","duration":2,"images":[],"step":7},{"title":"Quick toss","description":"Add pork, toss quickly to coat.","images":[],"step":8},{"description":"Serve immediately over rice, sprinkled with a little coriander and a lime wedge. I like to serve it classic Thai street-food style with plain tomato and cucumber wedges (no dressing) - the freshness is great with this dish!","images":[],"step":9}]', '["fish","peanuts"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["modern thai"],"categories":["asian-recipes","cuisines","mains","modern-asian","pork","pork-recipes","quick-and-easy","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_58a74d9254a2', 'en', 'US', 'Crispy Chinese Lemon Chicken - old school style!', 'Recipe video above. I like my Chinese Lemon Chicken the old school way, with a crispy battered cutlet sliced then sauced! The twice-fried Chinese fry batter used here stays crisper than regular batters (also less greasy) but once doused with the lemon sauce, it''s best served and eaten fast! Lemon sauce has a high water content so the crust will never stay crispy as long as other Chinese fried foods like, say, Honey Prawns.You''ll love the lemon sauce - brighter flavour and not tooth-achingly sweet like restaurants often are. For crispy bite size pieces, use the sauce in this recipe with the chicken from the Crispy Chinese Honey Chicken.', 'https://www.recipetineats.com/tachyon/2025/08/Crispy-Chinese-Lemon-Chicken_0.jpg', 20, 10, 30, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.094, "unit": "pack of 400g"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.008, "unit": "tub of 150g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.375, "unit": "tub of 200g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.15, "unit": "net of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.833, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_lemon", "quantity": {"value": 0.15, "unit": "net of 500g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}]', '[{"ingredients":["4 x 125g/3oz chicken thigh fillets (, skinless and boneless (or 2 breasts - Note 1))","1/2 tsp cooking salt / kosher salt","1/4 cup cornflour / cornstarch","1 - 1 1/2 litres (4 - 6 cups) vegetable or canola oil (, for frying - 4cm / 1.6\" depth (re-usable, Note 2))"]},{"ingredients":["1/3 cup cornflour / cornstarch","1/3 cup + 1 tbsp plain flour (all-purpose flour)","1/2 tsp cooking salt / kosher salt","1/4 tsp baking powder","1/2 cup COLD soda water (, not sparking mineral water (Note 3))"],"purpose":"STAY-CRISP FRY BATTER"},{"ingredients":["6 tsp cornflour/cornstarch","1/2 cup chicken stock/broth (, low sodium)","1/2 cup lemon juice (, fresh)","1/3 cup white sugar","1/2 tsp garlic (, finely grated)","1/2 tsp ginger (, finely grated)","1 tbsp Chinese cooking wine (can omit for alcohol-free)"],"purpose":"LEMON SAUCE"},{"ingredients":["Lemon slices (, to serve (optional))","1 green onion (, finely sliced on the diagonal, to serve (optional))"],"purpose":"GARNISH (optional)"}]', '[{"description":"Pound chicken to 0.7cm / 1/3\", salt, dust with cornflour. Dip in batter, fry 3 min at 160°C/320°F, cool 20 min, fry again 3 min at 200°C/390°F until dark golden and crispy. Slice, serve with sauce (simmer 3 min).","images":[],"step":1},{"title":"Refrigerate batter dry","description":"Whisk the cornflour, flour, baking powder and salt in a bowl, then put it in the fridge which you proceed with other prep (Note 4)","images":[],"step":2},{"title":"Pound chicken","description":"Place chicken on a cutting board and cover with a freezer bag or similar (I use Go-Between, Note 5) then pound with a meat mallet or bottom of a skillet until it is an even 0.7cm / 1/3\" thick. Sprinkle both sides with the 1/2 teaspoon of salt.","images":[],"step":3},{"title":"Dust","description":"Spread the cornflour on a plate and dust each side of the chicken with it, shaking off excess. Put on a plate and set aside while you keep preparing.","images":[],"step":4},{"description":"Preheat oil to 160°C/320°F in a large heavy based pot (mine is 24cm/9.4\"). The oil needs to be at least 4cm/1.6\" depth so the chicken floats.","images":[],"step":5},{"title":"Finish batter","description":"Remove bowl from the fridge, add soda water and whisk just until combined, then stop - some small lumps are ok, better than whisking to death (makes crust less puffy and light). It should be a fairly thin batter, enough to coat the chicken but fairly thinly.","images":[],"step":6},{"title":"Fry #1","description":"Dip a piece of chicken in the batter and let the excess drip off, then carefully place in the oil. Do another piece (if it will fit). Fry for 3 minutes until very pale golden. Remove onto a paper towel lined tray and repeat with remaining chicken.","duration":3,"images":[],"step":7},{"description":"Cool chicken for 20 minutes. (Note 6) Meanwhile, make the sauce.","duration":20,"images":[],"step":8},{"title":"Lemon Sauce","description":"Place the cornflour and a splash of the chicken stock in a small saucepan. Whisk until lump-free, then add remaining stock and sauce ingredients. Whisk and bring to a simmer over medium heat, then let it simmer for 3 minutes, whisking every now and then until it becomes a thin honey consistency. At first, it will go very thick (too thick for sauce) then it becomes thinner. Remove from heat, cover and keep warm (reheated if needed to loosen).","duration":3,"images":[],"step":9},{"title":"Fry #2","description":"Heat the oil to 200°C/390°F. Fry 2 pieces of chicken for 3 minutes until deep golden and super crispy, turning the chicken in the oil at the halfway mark. Remove onto a paper towel lined tray and repeat with remaining chicken.","duration":3,"images":[],"step":10},{"title":"Serving","description":"Cut the chicken into 2cm thick slices (3/4\"), transfer onto individual or shared serving plate. Pour over the Lemon Sauce, garnish with green onions and lemon slices if using. Serve with steamed rice (see in post for more side options).","images":[],"step":11}]', '["gluten"]', '["high_protein","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chicken","chicken-breast-recipes","chicken-recipes","chinese-recipes","deep-fried-recipes","mains"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6e006a653319', 'en', 'US', 'Pork Adobo', 'Recipe video above. Pork Adobo is the pride of the Philippines - one bite and you''ll be hooked! Pork braised until meltingly tender in an intense soy-garlic sauce that reduces down to a glaze, served over steaming rice, this is food so good yet so simple to make, you''ll be shaking your head in disbelief.Our adobo sauce has a well rounded flavour, intensely savoury but not overly salty or too sour (some restaurants make it really sour), and not too sweet. The sauce is meant to be thin so a little goes a long way on your rice.Slow cooker not recommended, sorry, see Note 6.', 'https://www.recipetineats.com/tachyon/2025/08/Pork-adobo-served-with-rice.jpg', 10, 120, 130, 4, '[{"id": "ing_pork_shoulder", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 13.333, "unit": "pack of 3 heads"}}, {"id": "ing_water", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.5, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.03, "unit": "bottle of 250ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.25, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.15, "unit": "jar of 50g"}}, {"id": "ing_bay_leaf", "quantity": {"value": 5.0, "unit": "unit"}}, {"id": "ing_pineapple", "quantity": {"value": 6.0, "unit": "unit"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 2.0, "unit": "kg"}}]', '[{"ingredients":["1 kg/ 2 lb pork shoulder (the parts ribboned with fat not lean parts), skinless, cut into 6cm/2.5\" cubes - or belly (Note 1)","2 tbsp vegetable oil (, or any other neutral flavoured oil)","1 large onion (, cut in half then 0.8\" / 1/3\" wedges)","8 cloves garlic (, finely sliced)","3 cups water","1/2 cup light soy sauce (, sub regular/all-purpose soy (Note 2))","1 1/2 tsp dark soy sauce (Note 2)","1/4 cup rice vinegar (sub regular white vinegar)","3 tbsp (tightly packed) brown sugar","1 1/2 tsp black peppercorns (, can omit (Note 3))","5 bay leaves (, preferably fresh, dried ok too)"]},{"ingredients":["6 pineapple rings (, each cut into 8 pieces, from canned pineapple in juice not syrup, or 2 cups fresh pineapple pieces)","2 tsp vegetable oil (, or any other neutral flavoured oil)"],"purpose":"Optional pineapple (Note 4):"},{"ingredients":["1 green onion (, finely sliced)","2 batches jasmine rice"],"purpose":"Garnish/serving:"}]', '[{"description":"Brown pork, remove, sauté onion and garlic, add everything else. Return pork, bring to boil, slow cook 1 1/2 hours until fall-apart. Caramelise pineapple pieces. Remove pork, reduce sauce to 1 1/2 cups (375 ml), stir in pork and caramelised pineapple until warmed. Serve over rice!","images":[],"step":1},{"title":"Sear pork","description":"Heat the oil in a large heavy based pot over high heat. Sear half the pork until golden all over - about 4 minutes - then remove into a bowl. Repeat with remaining pork, add to the bowl.","images":[],"step":2},{"title":"Sauté","description":"Reduce heat to medium. Add the onion, cook for 2 minutes. Add garlic and cook for another minute until the onion is softened.","duration":2,"images":[],"step":3},{"title":"Braising liquid","description":"Add water, soy sauces, vinegar, sugar, peppercorns and bay leaves. Stir. Add the pork back in, including any juices accumulated in the bowl.","images":[],"step":4},{"title":"Slow cook 1 1/2 hours","description":"Bring to a boil, then partially cover with a lid (leave a 2cm / 1\" crack) and reduce the heat to low/medium low so the liquid is simmering very, very gently. (Note 5) Simmer for 1 1/2 hours or until the pork is fall-apart tender (keep simmering if not tender).","images":[],"step":5},{"title":"Caramelise pineapple","description":"While pork is simmering, heat the oil in a non-stick pan over medium heat. Spread the pineapple out in one layer and cook each side until golden, about 4 minutes each side (I use spatula + tongs to turn). Remove onto plate until required.","images":[],"step":6},{"title":"Reduce sauce","description":"Remove pork with a slotted spoon (onion etc doesn''t matter when it''s in or out). Increase heat to high and boil to reduce the liquid down to 1 1/2 cups - it will be a very thin syrup (it''s not supposed to be thick), about 7 to 10 minutes.","images":[],"step":7},{"title":"Coat pork","description":"Reduce heat to low. Add the pork and pineapple pieces, plus any juices in the bowl. Stir gently to coat in the sauce and warm the pork through again.","images":[],"step":8},{"description":"Serve over jasmine rice, garnished with green onion if using.","images":[],"step":9}]', '["gluten","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Filipino"],"categories":["asian-recipes","iconic-dishes","pork-recipes","slow-cooked-fall-apart","stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d6d383962b8e', 'en', 'US', 'The fastest noodle stir fry I know - from scratch!', 'Recipe video above. This family-size noodle stir fry is a complete meal with protein and plenty of veg, made from scratch in just 15 minutes, and it’s seriously tasty. The sauce uses just two ingredients, fish sauce and kecap manis, which might sound like an unusual combination but these have more flavour than regular sauces like soy sauce! Together, they deliver big savoury, sweet, glossy flavour with zero fishiness. I can’t stop making this, it’s perfect for busy weeknights!** Saltiness note: Be sure not to miss the step to use some of the sauce to season the chicken, otherwise too much ends up on the noodles and it can taste a bit too salty. **', 'https://www.recipetineats.com/tachyon/2025/06/2-ingredient-noodle-stir-fry-_5.jpg', 7, 8, 15, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 0.14, "unit": "bunch"}}, {"id": "ing_cabbage", "quantity": {"value": 15.0, "unit": "head"}}, {"id": "ing_kecap_mani", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 1.0, "unit": "jar of 50g"}}, {"id": "ing_chilli", "quantity": {"value": 0.15, "unit": "pack of 100g"}}]', '[{"ingredients":["400g/14oz chicken thighs (, skinless boneless, thinly sliced 0.75cm/1/4\" thick (or breast))","500g / 1 lb hokkien noodles, lo mein, other noodles (, from the fridge, prepared per packet, rinsed well, drained (Note 1))","1 tbsp peanut oil (or any other neutral oil)","2 garlic cloves (, finely minced)","7 green onions (, cut into 5cm/2\" lengths, soft dark green parts separated from the white / pale green firmer parts)","5 cups green cabbage (, sliced ~1cm / 0.4\" thick (Napa/Chinese cabbage also works))"]},{"ingredients":["2 tbsp kecap mani (sweet soy) ( (Note 2))","1/4 cup fish sauce","1 pinch white pepper (sub black pepper)"],"purpose":"Sauce (just 2 ingredients!):"},{"ingredients":["1 tbsp+ chilli crisp, chilli paste or sriracha (add > taste > add > taste!) (Note 3)"],"purpose":"Optional grown up touch:"}]', '[{"description":"Toss chicken with 2 tbsp sauce. In a large 30cm/12\" non-stick pan over high heat, cook chicken first, adding garlic and white part of green onion towards the end. Cabbage 1 1/2 minutes, then noodles, sauce (add in 2 batches) and chilli crisp. Wilt green onion, serve!","images":[],"step":1},{"title":"Sauce","description":"Mix the ingredients in a small bowl.","images":[],"step":2},{"description":"Toss the chicken with 2 tablespoons of the sauce (no marinating time needed).","images":[],"step":3},{"description":"Cooking:","images":[],"step":4},{"title":"Cook chicken","description":"Heat the oil in a large 30cm/12\" non-stick pan over high heat until very hot. Add the chicken and cook for 2 minutes. Add the garlic and white part of the green onion, cook for another 30 seconds until chicken is just cooked.","duration":2,"images":[],"step":5},{"title":"Cabbage","description":"Add the cabbage, toss for 1 1/2 minutes or until it starts to go floppy.","images":[],"step":6},{"title":"Sauce and noodles","description":"Add the noodles and half the sauce, toss for a minute until the sauce is absorbed and no longer pooling in the pan (~ 45 seconds). Then add the remaining sauce and toss again until it''s all evenly coated and no liquid remains (~ 1 minute), adding chilli crisp towards the end, if using. (Note 4)","images":[],"step":7},{"title":"Serve","description":"Toss through the green part of the green onion until it''s wilted (barely 20 seconds), then divide between bowls. Noodle slurping time!","images":[],"step":8}]', '["fish","peanuts","soy"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","noodles","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_eed1600b9acf', 'en', 'US', 'Ginger chicken and rice (one pot recipe!)', 'Recipe video above. This one-pot ginger chicken and rice is inspired by the flavours of Hong Kong claypot rice, steamed with a layer of mushrooms and finished with a drizzle of sauce. It''s gone straight into my top 3 one-pot recipes!I''ve used a mix of Asian mushrooms here which have more interesting textures and impart more flavour into the rice than regular white mushrooms. But I wouldn''t hesitate to make this with any type of mushrooms!', 'https://www.recipetineats.com/tachyon/2025/06/Ginger-chicken-and-rice-with-mushrooms_5.jpg', 10, 25, 45, 4, '[{"id": "ing_oil", "quantity": {"value": 60.0, "unit": "bottle"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_rice", "quantity": {"value": 225.0, "unit": "pack"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_green_onion", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_ginger", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 666.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_shiitake_mushrooms", "quantity": {"value": 1.0, "unit": "pack of 150g"}}, {"id": "ing_oyster_mushrooms", "quantity": {"value": 1.0, "unit": "pack of 150g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 2.0, "unit": "jar of 50g"}}, {"id": "ing_kecap_manis_note_4", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 2.0, "unit": "jar of 50g"}}]', '[{"ingredients":["4 tbsp oil","500g/ 1 lb chicken thighs (, boneless, skinless, cut into small bite size pieces (Note 1))","1 1/2 cups long grain rice (, NOT RINSED (Note 2))","2 cups chicken stock (, low sodium)","4 green onion stems (, white part finely sliced, green flopped part cut into 5cm/2\" lengths)","1 1/2 tbsp ginger (, grated)","2 large garlic cloves (, finely minced)","4 - 5 slices ginger (~5mm / 0.2\" thick (large enough to easily pick out later), no need to peel)"]},{"ingredients":["150g / 5oz shiitake mushrooms (, fresh (~2 heaped cups), small halved, large thickly sliced)","150g / 5 oz oyster mushrooms ((~2 heaped cups), small kept whole, large cut into 2 or 3)","200g / 7 oz king mushrooms (, halved then cut into thick slices 7mm thick)","2 pinches salt and white pepper (each)"],"purpose":"Mushrooms (use any you want – Note 3):"},{"ingredients":["3 tbsp kecap manis ((sweet soy) - Note 4)","2 tbsp fish sauce","1/8 tsp white pepper (sub black)"],"purpose":"Simple claypot sauce:"}]', '[{"title":"ABBREVIATED","description":"Toss chicken with 1 1/2 tbsp sauce. Sear mushrooms in 2 batches, remove. SeaL chicken, add garlic, ginger and white part green onions towards end. Stir in rice, add stock and ginger slices, cover with mushrooms, steam 20 min. Rest 10 min, toss with sauce and green onion.","images":[],"step":1},{"title":"Sauce","description":"Mix sauce ingredients in a small bowl. Toss chicken with 1 1/2 tbsp of the sauce, set the rest aside for drizzling.","images":[],"step":2},{"title":"Lightly sear mushrooms","description":"Heat 1 1/2 tbsp oil in a large heavy based pot on high heat. Cook half the mushrooms with a pinch of salt and pepper until some of the mushrooms have a light tinge of golden on the surface, but don''t try to cook them all the way through (we want to do that in the rice). Remove into bowl. Repeat with remaining mushrooms.","images":[],"step":3},{"title":"Seal chicken","description":"Heat the remaining 1 tablespoon of oil until hot. Add the chicken and stir for 1 minute, just until the surface is sealed but inside still raw. Add white part of green onion, garlic and ginger, stir 30 seconds. Add rice, stir briefly just to coat in oil.","duration":1,"images":[],"step":4},{"title":"Simmer liquid","description":"Add stock and ginger slices. Bring to a rapid simmer. Scatter mushrooms across surface (add any pooled liquid too), then let it come to a rapid simmer again.","images":[],"step":5},{"title":"Steam 20 minutes","description":"Put the lid on, reduce stove to low (or medium low, for weak burners). Cook for 20 minutes (do not stir) until the liquid is fully absorbed.","duration":20,"images":[],"step":6},{"title":"Rest 10 minutes","description":"Remove pot from the stove with the lid still on and rest for 10 minutes.","duration":10,"images":[],"step":7},{"title":"Drizzle and toss","description":"Drizzle remaining sauce all over, add green part of green onions. Gently toss until the green onion is mostly wilted. Serve!","images":[],"step":8}]', '["fish","shellfish","soy"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","modern-asian","one-pot-recipes","quick-and-easy","rice-recipes","rice-side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f600a7f8dba3', 'en', 'US', 'Hokkien noodles with chicken', 'Recipe video above. My everyday Hokkien Noodles recipe. A great sauce. Strips of chicken. Lots of vegetables. 6 minute cook. Dinner in 20 minutes flat!', 'https://www.recipetineats.com/tachyon/2024/08/Hokkien-noodles-with-chicken_2.jpg', 14, 6, 20, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 0.16, "unit": "bunch"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_cabbage", "quantity": {"value": 3.0, "unit": "head"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.03, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.16, "unit": "bunch"}}]', '[{"ingredients":["500g/ 1 lb hokkien noodles (, (fridge best) (Note 1))","350g/ 12 oz chicken thighs (boneless, skinless), cut into lot of thin 0.5 x 3cm / 0.2 x 1.2\" pieces (Note 2)","2 tbsp canola oil (or vegetable, cottonseed, peanut oil)","2 garlic cloves (, finely minced)","8 green onion stems (, cut into 5cm / 2\" lengths, white part separated from green part (Note 3))","1 red capsicum (bell peppers) (, cut into thin 0.5cm / 0.2\" strips)","3 heaped cups green cabbage (, cut into thin 1 x 5cm / 0.5 x 2\" strips)"]},{"ingredients":["2 tbsp light soy sauce (Note 4)","1 1/2 tbsp dark soy sauce (Note 4)","2 tbsp oyster sauce (Note 5)","1 tbsp Mirin or Chinese cooking wine (Note 6)","1 tbsp sesame oil (, toasted (Note 7))","1/8 tsp white pepper (sub black pepper)"],"purpose":"Sauce:"},{"ingredients":["White sesame seeds","Finely sliced green onion"],"purpose":"Optional garnishes"}]', '[{"description":"Abbreviated recipe:","images":[],"step":1},{"description":"Marinate chicken with 1 1/2 tbsp Sauce. Cook chicken 1 min, add garlic and white part of green onion, cook 1 min. Add capsicum & cabbage, cook 2 min. Add green part of green onion, noodles, sauce, toss 2 min. Serve!","images":[],"step":2},{"title":"Sauce","description":"Mix the sauce in a small bowl.","images":[],"step":3},{"title":"Briefly marinate chicken","description":"Toss the chicken with 1 1/2 tbsp of the Sauce. Marinate for 10 minutes while you prepare the noodles and vegetables.","duration":10,"images":[],"step":4},{"title":"Rinse noodles","description":"Prepare the noodles per the packet directions (soak in boiling water or briefly boil). Drain in a colander then rinse briefly under tap water (Note 8)","images":[],"step":5},{"title":"Sear chicken","description":"Heat the oil in a large non-stick pan over high heat until very hot (mine is 30cm/12\", Note 9 re: wok). Add the chicken and toss for 1 minute. Add the garlic and white part of the green onion, then toss for another 1 minute or until the surface of the chicken is sealed (but still a bit raw inside)","duration":1,"images":[],"step":6},{"title":"Cook veg & noodles","description":"Add the capsicum and cabbage. Toss for 2 minutes until the cabbage is mostly wilted. Add the green part of the green onions, noodles and sauce. Toss for 1 1/2 to 2 minutes until the noodles are stained a lovely mahogany colour.","duration":2,"images":[],"step":7},{"description":"Serve immediately, sprinkled with sesame seeds and green onion if desired!","images":[],"step":8}]', '["gluten","peanuts","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","chinese-recipes","noodles","quick-and-easy","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3af8d4554aa7', 'en', 'US', 'Beef Tataki', 'Recipe video above. Here''s a Beef Tataki recipe, a fusion Japanese restaurant favorite with thinly sliced beef in a citrusy dressing. Making it at home costs a fraction of eating out!I make the deluxe restaurant version with beef tenderloin, crispy potato straws, and garlic oil for entertaining. Whereas the steak version with Asian Sesame Dressing and a sprinkle of crispy fried shallots with a side of Smashed Cucumbers and Garlic Pot-Steamed Rice is my sort of Monday night meal!Serves 2 as a main with sides or 4 as a starter as part of a larger banquet (see my new fusion Japanese menu here).', 'https://www.recipetineats.com/tachyon/2024/07/Beef-tataki_8.jpg', 20, 30, 50, 2, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_beef_steak", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_cooking_sake", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_mirin", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_yuzu", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_grapes", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}]', '[{"ingredients":["250g / 8 oz beef tenderloin/fillet (PREMIUM option) (- thin piece 13-15cm long (5-6\"), cut to even thickness (Note 1))","300g /10 oz sirloin steak ((aka Porterhouse in Australia, US: New York strip) (Note 2) - EASIER)"],"purpose":"Beef – choose ONE:"},{"ingredients":["1/2 tbsp vegetable oil (or other neutral flavoured oil)","1/4 tsp cooking salt / kosher salt"],"purpose":"Cooking:"},{"ingredients":["1 tbsp cooking sake (Note 4)","2 tsp mirin (Note 4)","1 tbsp rice vinegar (substitute apple cider vinegar)","1 1/2 tbsp Japanese soy sauce (, regular (Note 5))","1 tbsp yuzu (, or 1/2 tbsp each lime and lemon juice (Note 6))"],"purpose":"Yuzu Dressing (Note 3 other options):"},{"ingredients":["2 tbsp grapeseed oil (rapeseed oil or light olive oil)","3 garlic cloves (, sliced 2 mm thick)"],"purpose":"Garlic oil (optional, Note 7)"},{"ingredients":["Crispy potato straws (Pommes Paille, pictured, \"fancier\" option!)","Crispy fried shallots (store bought, easy option)"],"purpose":"Crispy topping options – CHOOSE ONE"},{"ingredients":["1 green onion (, finely sliced (optional curling, Note 8))"],"purpose":"Garnish:"}]', '[{"description":"Beef tenderloin:","images":[],"step":1},{"title":"Prep","description":"Preheat the oven to 130°C / 275°F (all oven types). Rub the beef with the oil and sprinkle with salt. Place on a rack set on a tray.","images":[],"step":2},{"title":"Roast for 18","description":"20 minutes or until the internal temperature in the middle is 41°C / 105°F (check first at 15 minutes, Note 9).","duration":19,"images":[],"step":3},{"title":"Sear","description":"Heat a cast iron skillet on high heat until it is smoking. Sear each side of the beef for just 10 seconds, no longer (I do 4 sides).","images":[],"step":4},{"title":"Cool","description":"Transfer the beef onto a rack on a tray. Cool for 30 minutes on the counter then refrigerate uncovered for 2 hours.","duration":30,"images":[],"step":5},{"title":"Thinly slice","description":"When ready to serve, slice it as thinly as you can without tearing the beef, aiming for 3mm / 1/16\" but up to 5mm / 1/8\" thick is fine. (Note 10 for tips)","images":[],"step":6},{"description":"Place the sake and mini in a tiny saucepan on low heat. Bring to a simmer, then simmer for 1 minute. Pour into a bowl, let it cool. Then stir in remaining dressing ingredients.","duration":1,"images":[],"step":7},{"description":"Garlic infused oil:","images":[],"step":8},{"description":"Put the garlic and oil in a tiny saucepan on low heat. Simmer for 5 minutes, stirring a few times, until the garlic is light golden. Cool for 15 minutes then strain (reserve crispy garlic for another use)","duration":5,"images":[],"step":9},{"title":"Plate up","description":"Lay the beef slices on a plate, overlapping slightly. Drizzle with 3-4 tbsp of the Dressing, then 1 1/2 tbsp of the garlic oil. Pile the crispy potato in a heap in the middle, sprinkle with green onion. (Or use the easy steak garnish options above instead).","images":[],"step":10},{"title":"To eat","description":"Serve straight away. Make sure you get some crispy potato in every bite, and squidge the beef around in the tasty sauce.","images":[],"step":11},{"description":"Easy steak option:","images":[],"step":12},{"title":"Cook","description":"Rub the steak with the oil then sprinkle with the salt. Heat a cast iron skillet on high heat until it is smoking. Cook the steak to rare (1 1/2 - 2 minutes on each side, but it will depend on thickness of steak), or to your taste (Note 11 for doneness). Cool & thinly slice steak per beef tenderloin steps above.","images":[],"step":13},{"title":"Assemble","description":"Place the slices in a line, slightly overlapping. Drizzle over Dressing and oil (or alternative Sauce of choice). Sprinkle crispy fried shallots down the centre then green onion. Serve!","images":[],"step":14}]', '["fish","gluten","soy"]', '[]', '{"mealType":["dinner","snack"],"cuisine":["fusion japanese","Modern Asian"],"categories":["asian-recipes","modern-asian"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_48a44116bb5e', 'en', 'US', 'Easy Singapore Chicken Vermicelli Noodles', 'Recipe video above. This is just a downright delicious and easy noodle stir fry that channels the flavours of everybody''s favourite Singapore Noodles. Same sauce, same egg ribbons, and strips of red capsicum. But with chicken and bacon instead of having to make or hunt down Chinese BBQ Pork and peel fresh prawns! I''ve also added bean sprouts and baby spinach for extra no-chop veg quota to turn this into a complete meal. This might not be traditional but it''s quick, easy, tasty, and you can make it tonight!', 'https://www.recipetineats.com/tachyon/2024/04/Easy-Singapore-chicken-vermicelli-noodles-2.jpg', 15, 10, 25, 3, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.2, "unit": "pack of 500g"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.09, "unit": "bottle of 500ml"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.3, "unit": "jar of 50g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_bacon", "quantity": {"value": 0.5, "unit": "pack of 200g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 1.0, "unit": "bag of 250g"}}, {"id": "ing_baby_spinach", "quantity": {"value": 1.0, "unit": "bag of 250g"}}]', '[{"ingredients":["100 g/3.5 oz dried vermicelli noodles (not glass noodles)"]},{"ingredients":["3 tbsp light soy sauce (, or all-purpose soy (not dark soy) (Note 1))","3 tbsp Chinese cooking wine (Shaoxing wine, Note 2)","3 tsp curry powder (Note 3)","1 tsp white sugar","1/2 tsp white pepper (sub black pepper)"],"purpose":"Singapore noodles sauce:"},{"ingredients":["150g/ 5 oz skinless boneless chicken thighs","1/4 tsp cooking salt / kosher salt","1/2 tsp curry powder (Note 3)"],"purpose":"Chicken:"},{"ingredients":["2 tbsp plain oil (canola, veg, peanut)","2 eggs (, whisked)","100g/3 oz streaky bacon (, chopped into small pieces)","1/2 brown onion (, finely sliced)","3 garlic cloves (, finely minced)","1 red capsicum ((bell pepper), deseeded and finely sliced)","1 very heaped cup bean sprouts (or more leafy greens)","1 very heaped cup baby spinach (or other cook-able leafy greens or more bean sprouts)"],"purpose":"Stir fry add-ins:"}]', '[{"title":"Sauce","description":"Mix the sauce in a small bowl or jug.","images":[],"step":1},{"title":"Season chicken","description":"Toss the seasoned chicken ingredients in a bowl.","images":[],"step":2},{"description":"Prepare noodles per the packet directions then drain in a colander (usually says to soak in boiled water for 3 - 5 minutes).","duration":4,"images":[],"step":3},{"title":"Egg ribbons","description":"Heat a small amount of the oil in a large non stick pan over medium high heat. Pour the egg in a swirl to make a thin omelette. Once the surface is set (literally 30 seconds), slide or flip it onto a cutting board. Cool so you can handle it, roll it up into a cigar then cut into 7mm / 1/3\" strips. Separate. Voila! Egg ribbons!","images":[],"step":4},{"title":"Stir-fry","description":"Heat the remaining oil in the same pan over high heat. Add the bacon and cook for 1 minute. Add the onion and cook until it starts to wilt and the bacon is light golden (about 2 minutes). Add the chicken and cook until the surface is seared. Then add the garlic and capsicum and cook for another 2 minutes until the chicken is cooked.","duration":1,"images":[],"step":5},{"title":"Noodles","description":"Add (in this order) the baby spinach, bean sprouts, noodles then sauce. Using 2 spatulas, toss well for 1 1/2 minutes or until the sauce stains the noodles. There will be noodle breakage - that''s normal.","images":[],"step":6},{"title":"Finish","description":"Toss through the egg ribbons (gently, just to disperse) then serve immediately!","images":[],"step":7}]', '["egg","gluten","peanuts","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","quick-and-easy","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_716a59c2271e', 'en', 'US', 'Thai Turmeric Chicken (Gai Yang Khamin)', 'Recipe video. This is based on a popular southern Thailand street food that''s typically made with a butterflied chicken grilled over smokey coals. It''s sweet but has complexity owing to the simple but clever marinade.Here, I''m making a home version using the marinade for bone-in chicken thighs instead and baked it in my boring oven. I miss the charcoal flavour but it''s still lip smackingly delicious! The tumeric powder really makes it. :)', 'https://www.recipetineats.com/tachyon/2015/11/Thai-Turmeric-Chicken_4.jpg', 10, 50, 230, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.15, "unit": "bottle of 250ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_turmeric", "quantity": {"value": 15.0, "unit": "jar"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.037, "unit": "kg"}}]', '[{"ingredients":["5 large chicken thighs, skin-on, bone-in (~1.2kg/2.4lb) (Note 1)"]},{"ingredients":["4 garlic cloves (, finely minced or crushed using garlic press)","2 tbsp fish sauce","2 1/2 tbsp oyster sauce","1 tsp white pepper (, ground (sub black))","1 tbsp ground turmeric","1/4 cup brown sugar (tightly packed cup)"],"purpose":"Marinade"}]', '[{"title":"Marinade chicken","description":"Mix Marinade ingredients in a large bowl. Add chicken and toss to coat. Marinade for at least 3 hours, preferably overnight.","images":[],"step":1},{"description":"Preheat oven to 180°C/350°F (160°C fan-forced).","images":[],"step":2},{"title":"Prepare","description":"Line a tray with baking paper/parchment paper. Place chicken on the tray, skin side up. Scrape all Marinade out of th bowl and dab onto chicken.","images":[],"step":3},{"description":"Bake for 40 minutes, basting at the 30 minute and 40 minute mark using the tray juices to make it golden brown and sticky, and rotate the tray as needed for even colour.","duration":40,"images":[],"step":4},{"description":"Increase the oven temperature to 200°C/390°F (180°C fan-forced). Pop the chicken back in for a final 10 minutes to caramelise the skin.","images":[],"step":5},{"description":"Rest for 3 minutes before serving with jasmine or coconut rice, and plain chunks of tomato and cucumber the Thai way!","duration":3,"images":[],"step":6}]', '["fish","gluten"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["asian-recipes","australia-day","chicken-breast-recipes","chicken-recipes","cuisines","dietary","gluten-free-recipes","grilling-ideas-and-recipes","quick-and-easy","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9cb8b7f4cf19', 'en', 'US', 'Spicy Wontons - Din Tai Fung!', 'Recipe video above. Everybody knows Din Tai Fung* has the best Spicy Wontons. Here''s my copy-cat! Very specific mix of spices, it''s less spicy, less vinegary and more savoury than typical Chinese dumpling houses, designed so you can slop up every bit of that tasty sauce with the wontons without blowing your head off! So, so, very good!* Global dumpling restaurant chain that declares itself the world''s best dumplings. Many Sydney-siders would not disagree.', 'https://www.recipetineats.com/tachyon/2023/09/Spicy-wontons-din-tai-fung_7-2.jpg', 10, 5, 15, 12, '[{"id": "ing_wontons", "quantity": {"value": 11.0, "unit": "unit"}}, {"id": "ing_green_onion", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_chinese_five_spice", "quantity": {"value": 1.25, "unit": "jar"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.003, "unit": "L"}}, {"id": "ing_chilli", "quantity": {"value": 0.06, "unit": "pack of 100g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.05, "unit": "bottle of 250ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_water", "quantity": {"value": 0.037, "unit": "L"}}]', '[{"ingredients":["1/2 tsp Chinese chicken stock powder (, or regular western stock powder (Note 5))","1 tbsp green onion (, sliced then roughly chopped, for garnish)","Extra chilli oil (, for drizzling (Note 5))"],"purpose":"Wontons:"},{"ingredients":["2 garlic cloves (, very finely minced)","1 tsp caster / superfine sugar (sub regular sugar)","1/2 tsp red chilli flakes (red pepper flakes), OPTIONAL, for spicy food lovers (Note 2)","1/4 tsp sichuan pepper powder (Note 3)","1/4 tsp Chinese five spice powder (Note 4)","1/2 tsp Chinese chicken stock powder (, or regular western stock powder (Note 5))","2 tbsp Chinese chilli oil (⚠️ Note 5), adj for spiciness (sub with sesame oil)","1 tbsp vegetable oil (sub canola, peanut or other natural oil)","2 1/2 tsp light soy sauce (, or all-purpose soy (Note 6))","1 tsp rice vinegar (sub other clean vinegar)","2 1/2 tbsp hot water (just tap is fine)"],"purpose":"Chilli oil sauce for wontons:"}]', '[{"description":"Chilli oil sauce for wontons:","images":[],"step":1},{"title":"Mix spices","description":"Put the garlic, sugar, chilli flakes, sichuan pepper, five spices and stock powder in a medium mixing bowl.","images":[],"step":2},{"title":"Heat oil","description":"Heat the chilli oil and vegetable oil in a small frying pan over medium heat until hot. Pour over garlic mixture. Enjoy the sizzle! (Don''t worry, it doesn''t spit)","images":[],"step":3},{"title":"Add sauces:","description":"Whisk in soy sauce, rice vinegar and hot water. The oil will remain a little separated on top. Set aside while you make wontons.","images":[],"step":4},{"title":"Cook wontons","description":"Bring a large saucepan of water to the boil. Add wontons and cook until they float: 4 minutes for freshly made, 6 to 8 minutes from frozen.","images":[],"step":5},{"title":"Assemble","description":"Transfer to serving dish using a slotted spoon. Pour over sauce, add an extra drizzle of chilli oil (if you dare!), sprinkle with green onion. Serve immediately!","images":[],"step":6}]', '["gluten","peanuts","sesame","soy"]', '["keto_friendly","low_calorie"]', '{"mealType":["dinner","snack"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","iconic-dishes","modern-asian"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_15e4c46ddb04', 'en', 'US', 'Bok Choy in Ginger Sauce', 'Recipe video above. My favourite way to cook bok choy is with a lovely shiny, ginger sauce. Great way to load up on leafy Asian greens quickly and easily! Be careful not to overcook the bok choy, it cooks really fast. Pan-steam for just 45 seconds, then it finishes cooking in 30 seconds with the sauce. Recipe also works great with other Asian Greens like pak choy, choy sum (see Note 1). Make this ginger version one day then garlic the next! Serve as a side, with fluffy rice or over noodles in soup.', 'https://www.recipetineats.com/tachyon/2023/09/Bok-choy-in-ginger-sauce.jpg', 3, 3, 6, 4, '[{"id": "ing_bok_choy", "quantity": {"value": 6.0, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_ginger", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.037, "unit": "pack of 400g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.03, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.02, "unit": "bottle of 500ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["6 small bok choys (, up to ~17cm/7\" long, or other Asian greens (Note 1 + photos in post))","2 tbsp vegetable oil","1/4 cup ginger (, finely julienned (or 1 tbsp garlic))","1/4 cup water"]},{"ingredients":["3 tsp cornflour/cornstarch","1 1/2 tsp light soy sauce (, or all-purpose soy (Note 2))","1 tsp oyster sauce (sub vegetarian oyster sauce)","2 tsp Chinese cooking wine (Note 3)","1 tsp sesame oil (, toasted)","1/4 cup water","1/4 tsp cooking salt","Pinch white pepper"],"purpose":"Sauce (Note 5 for Charlie shortcut!):"}]', '[{"title":"Cutting","description":"Trim the base of the bok choy then separate all the leaves. Leave the delicate baby bok choy in the centre intact, it''s precious! Cut giant stems in half lengthwise so they are all roughly the same size. Rinse in colander, shake off excess water (don''t need to dry fully).","images":[],"step":1},{"title":"Sauce","description":"Stir Sauce ingredients except water in a jug until cornflour is dissolved. (Easier to make lump free with less liquid). Then stir in water.","images":[],"step":2},{"title":"Gingery oil","description":"Put the ginger and oil in a large non-stick pan. Turn onto medium heat. Once the ginger starts sizzling, sauté for 1 minute until it turns light golden and is a bit floppy. Add bok choy then use 2 spatulas to toss the ginger for around 15 seconds to coat.","duration":1,"images":[],"step":3},{"title":"Steam","description":"Turn heat up to medium, pour water over. Cover with lid and steam for just 45 seconds.","images":[],"step":4},{"title":"Sauce","description":"Remove lid (bok choy will still be a bit underdone), pour in sauce, toss for 30 seconds until sauce changes from murky to clear, and thickens. Bok choy should be just floppy but still soft crunch, not mushy. If your sauce gets too thick (Note 4), add a tiny splash of water and mix.","duration":0.5,"images":[],"step":5},{"title":"Serve","description":"Pour the bok choy and all the sauce onto a serving plate, then eat!","images":[],"step":6}]', '["gluten","sesame","soy"]', '["keto_friendly","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Asian","Chinese"],"categories":["asian-greens","asian-recipes","dietary","low-calorie-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3c520b158734', 'en', 'US', 'Garlic Noodles', 'Recipe video above. Quick & easy, this is a fusion Asian dish made famous by Thanh Long restaurant in San Francisco, via Kenji Lopez-Alt. Big garlic flavours and Asian sauces are combined with parmesan which gives it an extra savoury punch. Makes these noodles lip smackingly good! Add a fried egg and broccolini cooked with the noodles for a quick meal. Or serve as a side with any Asian meal!', 'https://www.recipetineats.com/tachyon/2023/09/Garlic-noodles-with-egg-close-up.jpg', 5, 6, 11, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.28, "unit": "pack of 500g"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 10.0, "unit": "pack of 3 heads"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_maggi_seasoning", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.28, "unit": "pack of 500g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.75, "unit": "bunch"}}]', '[{"ingredients":["140g/ 5oz dried ramen or noodle cakes ((2 cakes) - Note 1 for other options)"],"purpose":"Noodles:"},{"ingredients":["30g / 2 tbsp unsalted butter","2 tbsp (6 cloves) garlic, finely minced (yep, a lot!)","2 tsp oyster sauce (sub vegetarian oyster sauce)","2 tsp fish sauce (sub soy sauce - Note 2)","1 1/2 tsp Maggi seasoning (sub soy sauce - Note 3)","1/4 cup noodle cooking water (, more if needed (Note 4))","1/4 cup (tightly packed) finely grated parmesan ( (freshly grated, Note 5))","1/4 cup green onion (, thinly sliced (~1 stem))"],"purpose":"Sauce:"}]', '[{"title":"Noodles","description":"Cook the noodles in a large saucepan per packet directions. Scoop out ~1/2 cup cooking water. Strain noodles and set aside.","images":[],"step":1},{"title":"Sauce","description":"Melt butter in the same saucepan over medium heat. Add garlic and cook, stirring until soft. Add oyster sauce, fish sauce, Maggi seasoning and 1/4 cup cooking water. Stir to combine.","images":[],"step":2},{"title":"Toss","description":"Add cooked noodles, parmesan and green onion. Toss until the noodles are all coated, and the sauce is not pooled in the bottom of the saucepan. Add more cooking water 1 tbsp at the time, if needed to loosen the noodles.","images":[],"step":3},{"description":"Serve immediately!","images":[],"step":4},{"title":"Serving suggestion","description":"fried egg and broccolini cooked with the noodles*, tossed with Asian Sesame Dressing you always have in your fridge. :)* Broccolini takes about 3 minutes, so put it into the water before/after/with the noodles depending on the noodle cooking time.","images":[],"step":5}]', '["fish","gluten","milk","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["asian fusioin","Asian-esque"],"categories":["asian-recipes","noodles","quick-and-easy","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8bf5422252bf', 'en', 'US', 'Vietnamese Caramel Ginger Chicken', 'Recipe video above. Vietnamese caramel sauce is a popular sweet/savoury used in Vietnamese dishes. Here, it''s used for bite size chicken pieces that get coated in the glaze with a generous dose of ginger. It''s quick, easy, something different and outrageously good!** NOTE: Sadly seeing reader feedback that the liquid isn''t reducing and chicken isn''t caramelising. Please ensure to use a LARGE PAN and be brave, simmer RAPIDLY! Else the liquid will take ages to reduce. See Note 4.**', 'https://www.recipetineats.com/tachyon/2023/08/Vietnamese-Ginger-Caramel-Chicken_6-close-up.jpg', 7, 15, 22, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1 kg / 2 lb skinless chicken thigh fillets (, cut into large 5cm/2\" pieces (Note 1))","3 tbsp fish sauce","1 bird’s eye chilli or Thai chilli (, deseeded, finely minced (optional) - Note 2)","3 tbsp vegetable oil","1/4 cup brown sugar (, tightly packed)","1/3 cup ginger (, finely julienned (about 5 cm/2\" thick piece))","2 eschallots (, halved then finely sliced (sub half red onion) (Note 3))","1/2 cup boiling water"]},{"ingredients":["Fresh coriander/cilantro or green onion slices (recommended)","Red chilli (, finely sliced (optional))","Jasmine rice"],"purpose":"Garnishes & serving:"}]', '[{"description":"Toss chicken with fish sauce and chilli, then set aside while you prepare the other ingredients. You could marinate even overnight but it''s not necessary.","images":[],"step":1},{"title":"Pan size","description":"Use a large non-stick pan (mine is 30cm/12\", must be large). Else, be prepared to remove chicken at end to speed up sauce reduction. See Note 4!","images":[],"step":2},{"title":"Caramel","description":"Mix oil and sugar in the cold pan, then turn onto medium high heat. As soon as the sugar is melted, remove the pan from the stove then carefully add the chicken (⚠️ it will sizzle so don''t throw it in!) . Add ginger and shallots, toss briefly. The caramel may harden, that''s ok, it will re-melt.","images":[],"step":3},{"title":"Cook outside of chicken","description":"Then put the pan back on the stove and stir just until the chicken changes from pink to white all over, but not browned, and definitely not cooked through.","images":[],"step":4},{"title":"Simmer 10 min","description":"Add water, stir, bring to a simmer. Simmer very rapidly, still on medium high (or even high!), for 10 to 12 minutes, until the liquid reduces right down to a glaze. It might take longer if your pan is smaller or your stove is weaker, that''s ok. Stir every now and then while watery, then once it''s reduced down to a glaze, toss regularly to get nice colour on the chicken. The further you take it, the better the colour!","duration":11,"images":[],"step":5},{"description":"Serve with jasmine rice or other plain rice garnished with extra slices of chilli and fresh coriander if desired. Smashed cucumbers or Asian Slaw would be a terrific side!","images":[],"step":6}]', '["fish"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Vietnamese"],"categories":["asian-recipes","chicken","chicken-recipes","mains","modern-asian","quick-and-easy","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_28bfac61179b', 'en', 'US', 'Thai Coconut Pumpkin Soup', 'Recipe video above. This is a brilliant way to turn a classic pumpkin soup into something that tastes more exotic - with very little effort. Think - pumpkin soup with Thai Red Curry vibes. It''s so good!See separate tutorial for how I cut butternut pumpkin and the Pumpkin Soup recipe for how I cut pumpkin.', 'https://www.recipetineats.com/tachyon/2023/08/Thai-Coconut-Pumpkin-Soup_2.jpg', 10, 15, 25, 5, '[{"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_thai_red_curry_paste", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_pumpkin", "quantity": {"value": 1.8, "unit": "kg"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.625, "unit": "L"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_roti_frozen_pan_fried_for_dunking_note_6", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["2 tbsp vegetable oil (or other oil)","1 brown onion (, diced)","2 garlic cloves (, finely minced)","3 tbsp Thai red curry paste (, Maesri recommended (Note 1))","1.8kg/ 3.6 lb pumpkin or butternut squash ( - peeled, deseeded then chopped into 3cm / 1.2\" chunks (~1.3 kg/2.6 lb) (Note 2))","2 1/2 cups vegetable stock (, salt reduced (or chicken stock))","400ml/ 14 oz (1 can) coconut milk, (full fat, best quality (Note 3))","1 tbsp fish sauce (sub light or regular soy sauce, Note 4)"]},{"ingredients":["Crispy Asian shallots (, highly recommended (Note 5))","Red cayenne pepper (, finely sliced)","Fresh coriander leaves","Roti ((the flaky kind), frozen, pan fried - for dunking (SO GOOD!) - Note 6)"],"purpose":"Garnishes (optional):"}]', '[{"title":"Sauté","description":"Heat oil in a large heavy based pot over medium high heat. Add onion and garlic, cook for 2 minutes until soft.","duration":2,"images":[],"step":1},{"description":"Add curry paste and cook for 2 minutes.","duration":2,"images":[],"step":2},{"description":"Add pumpkin and stir to coat in the flavours for around 2 minutes.","images":[],"step":3},{"title":"Simmer 8 minutes","description":"Set aside 1/4 cup coconut milk for garnish. Add stock, remaining coconut milk and fish sauce. Bring to simmer then reduce heat to medium and simmer for 8 minutes until the pumpkin is soft.","duration":8,"images":[],"step":4},{"description":"Blitz using stick blender until smooth.","images":[],"step":5},{"description":"Serve topped with garnishes. Dunk in roti. Enjoy!","images":[],"step":6}]', '["fish","gluten","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian","Thai"],"categories":["asian-recipes","asian-soups","cuisines","pumpkin","quick-and-easy","soup-recipes","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e2dad4918e12', 'en', 'US', 'Japchae - Korean Noodles', 'Recipe video above. Sort of a stir fry, sort of a noodle salad, this big, colourful Korean noodle dish is tossed together in a bowl rather than on the stove and served barely warm. Made with chewy, slippery sweet potato noodles (dangmyeon) which are available in large grocery stores, though can be substitute with glass noodles (bean thread noodles) or vermicelli noodles in a pinch.Makes a big batch - leftovers make for a terrific lunch!', 'https://www.recipetineats.com/tachyon/2023/07/Japchae-Korean-noodles_9.jpg', 20, 15, 35, 5, '[{"id": "ing_beef_steak", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_beef_steak", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.3, "unit": "pack of 100g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_sweet_potato", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.06, "unit": "bunch"}}, {"id": "ing_shiitake_mushrooms", "quantity": {"value": 1.333, "unit": "pack of 150g"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_baby_spinach", "quantity": {"value": 4.5, "unit": "bag of 250g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.3, "unit": "pack of 100g"}}]', '[{"ingredients":["600g/1.2lb bone-in beef short ribs *RECOMMENDED* (300g/10oz boneless)","300g/10 oz boneless beef short ribs *RECOMMENDED*","300g/10oz scotch fillet / boneless rib eye (or other steak, recommend tenderising (Note 1))"],"purpose":"Choose beef option (Note 1):"},{"ingredients":["2 tsp soy sauce (, all-purpose or light soy (Note 2))","2 tsp white sugar","2 tsp finely minced garlic","1/2 tsp black pepper"],"purpose":"Beef marinade:"},{"ingredients":["1/4 cup soy sauce (, all-purpose or light soy (Note 2))","2 tsp white sugar","1/2 tsp finely minced garlic","1 1/2 tbsp sesame oil","1/2 tsp cooking/kosher salt","1/2 tsp black pepper"],"purpose":"Noodle dressing:"},{"ingredients":["250g/ 8oz sweet potato noodles (dangmyeon), dried (Note 3)","4 tbsp vegetable oil (or other plain oil)","1 tsp cooking/kosher salt (, divided)","1 onion (, peeled, halved, sliced into 6mm/1/4\" wedges)","3 green onion stems (, cut into 5cm / 2\" lengths, white & green parts separated)","200g/7oz fresh shiitake mushrooms (, stem removed, cut into 5mm/1/5\" slices (Note 4))","2 carrots (, peeled, cut into 3mm / 1/8\" batons)","1 red capsicum/bell pepper (, cut into 0.5cm / 1/5\" slices)","4 1/2 cups (tightly packed) baby spinach","2 tbsp white sesame seeds"],"purpose":"Noodles & vegetables:"}]', '[{"description":"Quick beef marinade:","images":[],"step":1},{"description":"Cut beef into strips that are ~ 5mm thick, 1cm wide and about 5cm long (1/5\" x 2/5\" x 2\"). If using shortribs, trim excess fat, cut the meat off the bone. Then cut each piece in half lengthwise (to form 2 \"steaks\") then slice into 5mm thick. (See step photos in post or video at 0.11s, Note 6)","images":[],"step":2},{"title":"Marinate","description":"Put beef in a bowl. Add marinade ingredients, then mix. Set aside marinate while you proceed with recipe, ~15 - 20 minutes is all it needs. (Note 5)","images":[],"step":3},{"description":"Sauce and noodles:","images":[],"step":4},{"title":"Sauce","description":"Mix the Sauce ingredients in a very large mixing bowl.","images":[],"step":5},{"title":"Noodles","description":"Cook sweet potato noodles per packet directions (normally 8 min in boiling water). Drain, briefly rinse under tap water then shake off excess water well. Add noodles into the bowl with the dressing. DO NOT MIX.","images":[],"step":6},{"title":"Batch 1","description":"Heat 2 tablespoons of oil in a large non-stick pan (30cm/12\") over high heat. Cook the brown onion, white part of green onion and shiitake mushrooms with 1/2 tsp salt for 2 1/2 to 3 minutes, stirring constantly, just until starting to soften but not going golden. Pour on top of the noodles - don''t mix yet!","images":[],"step":7},{"title":"Batch 2","description":"Using the same pan still on high heat, heat 1 tbsp oil then cook the carrot and capsicum for 1 1/2 minutes, constantly stirring. Add spinach, green onion and the final 1/2 tsp salt. Keep cooking for 1 1/2 minutes until the spinach is wilted. Transfer into the noodle bowl - still don''t mix!","images":[],"step":8},{"title":"Cook beef","description":"In the same pan, heat the final 1 tbsp of oil still on high heat. Add beef and cook for 1 1/2 minutes until very lightly golden and just cooked through. Add to the noodle bowl. Don''t mix!","images":[],"step":9},{"description":"Mix! Add most of the sesame seeds (reserve some for topping). NOW you can mix! Toss, toss, toss.","images":[],"step":10},{"title":"Serve","description":"Transfer into a serving bowl, sprinkle with remaining sesame seeds. This is meant to be eaten warm, not piping hot. Eat!","images":[],"step":11}]', '["fish","gluten","sesame","soy"]', '[]', '{"mealType":["lunch","dinner"],"cuisine":["Korean"],"categories":["asian-recipes","korean-recipes","noodles","quick-and-easy","summer"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6e6cc9cb5cdb', 'en', 'US', 'Sizzling ginger steamed fish', 'Recipe video above. Named as such because the ginger and green onion topping sizzles dramatically when you pour hot oil over oven steamed fish! An incredibly simple way to make a healthy steamed fish recipe a whole lot more exciting with fresh Asian flavours.Squidge every bite of fish very well in the sauce before eating. The sauce is really tasty - it will surprise you.', 'https://www.recipetineats.com/tachyon/2023/07/Sizzling-ginger-fish_1.jpg', 5, 15, 20, 2, '[{"id": "ing_fish_fillets", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_cooking_sake", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.5, "unit": "bunch"}}, {"id": "ing_ginger", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_oil", "quantity": {"value": 10.0, "unit": "bottle"}}]', '[{"ingredients":["2 x 180g/ 6 oz thinnish white fish fillet (, skinless (~1.5 cm/ 2/3\" thick) (Note 1))","1 tsp cooking sake (sub mirin, Chinese cooking wine, dry sherry) (Note 2)","Small pinch salt","Small pinch white pepper (sub black)"]},{"ingredients":["1/2 cup green onion (, green part only, finely sliced on diagonal (Note 3))","2 tbsp ginger (, finely julienned (Note 3))","1 tbsp large red chilli (, deseeded finely julienned on diagonal, optional (Note 4))"],"purpose":"TOPPING (divide between 2 fish):"},{"ingredients":["2 tsp light soy sauce (, or all-purpose soy (Note 5))","2 tsp sesame oil (, toasted)","2 tbsp peanut oil (or veg, canola, grapeseed)"],"purpose":"SAUCE (divide between 2 fish):"}]', '[{"description":"Preheat oven to 200°C/400°F (180°C fan).","images":[],"step":1},{"title":"Prepare parcel","description":"Place a 2 x 25cm / 10\" piece of foil on a work surface. Top with a piece of parchment/baking paper slightly smaller. Place fish on paper.","images":[],"step":2},{"title":"Season fish & wrap","description":"Sprinkle each side of the fish with a SMALL pinch of salt and pepper. Drizzle the top of each fish with 1/2 tsp sake. Form a parcel - make a parcel with the paper first, then the foil. (See video or step photos).","images":[],"step":3},{"title":"Bake","description":"Place parcels on a tray. Bake for 12 minutes or until the internal temperature is 55°C/130°F (I pierce thermometer through foil) or the fish flesh flakes (open to check). Thin fish cooks fast when enclosed!","duration":12,"images":[],"step":4},{"title":"Rest 3 min","description":"Put each parcel on a plate and unwrap, folding down the sides to create a “boat” that will catch the sauce that you can squidge the fish in. Rest for 3 minutes - heat the oil while it rests.","duration":3,"images":[],"step":5},{"description":"Heat oil until hot in a tiny saucepan or small pan over medium heat.","images":[],"step":6},{"description":"Sizzle! Top the fish with green onion, ginger and chilli. Drizzle with soy and sesame oil. Pour oil all over the green onion and ginger - it will sizzle dramatically!","images":[],"step":7},{"description":"Serve immediately. Eat fish out of foil, squidging the flaky pieces well in the sauce before eating. See post for what I served it with!","images":[],"step":8}]', '["fish","gluten","peanuts","sesame","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","dietary","fish-recipes","low-calorie-recipes","mains","other","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1ad6752ed673', 'en', 'US', 'Beef Chow Mein - great beef mince noodle recipe!', 'Recipe video above. The beef mince version of everybody''s favourite Chicken Chow Mein - great way to cook up ground beef with noodles. Economical and no meat chopping required, with plenty of hidden vegetables so it''s a complete dinner! Scrambling up an egg with the beef is a neat trick to make the beef cling to the noodles better.', 'https://www.recipetineats.com/tachyon/2023/07/Beef-chow-mein_5.jpg', 15, 10, 25, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.4, "unit": "pack of 500g"}}, {"id": "ing_oil", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.06, "unit": "bunch"}}, {"id": "ing_egg", "quantity": {"value": 16.667, "unit": "carton of 12"}}, {"id": "ing_cabbage", "quantity": {"value": 6.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 1.0, "unit": "bag of 250g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.03, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.045, "unit": "bottle of 500ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.019, "unit": "pack of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.045, "unit": "L"}}]', '[{"ingredients":["200g/ 7 oz chow mein noodles (, or other thin yellow egg noodles or 3 ramen cakes (Note 1))","1 1/2 tbsp canola oil","2 garlic cloves (, finely minced)","200g/ 7 oz beef mince / ground beef (any fat %)","3 green onion stems (, cut into 5cm/2\" lengths, white and green parts separated)","1 egg","2 cups green cabbage (, finely sliced (or Chinese cabbage))","1 carrot (, peeled, cut into thin batons)","1 heaped cups bean sprouts (~ 75g / 2 1/2 oz) (Note 5 - storage tip)"],"purpose":"Chow Mein:"},{"ingredients":["1 1/2 tbsp light soy sauce (or all-purpose soy sauce (Note 2))","1 1/2 tsp dark soy sauce (Note 2)","1 1/2 tbsp oyster sauce (Note 3)","1 1/2 tbsp Chinese cooking wine (Shaoxing) (Note 4)","1 1/2 tsp white sugar","Pinch white pepper"],"purpose":"Chow Mein Sauce:"},{"ingredients":["1 1/2 tsp cornflour / cornstarch","3 tbsp water"],"purpose":"Sauce thickener:"}]', '[{"title":"Sauce","description":"Mix ingredients in a small bowl then set aside. Some is used to flavour the beef, then the rest for the noodles.","images":[],"step":1},{"title":"Sauce thickener (cornflour slurry)","description":"Mix the cornflour / cornstarch and water in a separate small bowl.","images":[],"step":2},{"description":"Prepare noodles per packet directions then drain.","images":[],"step":3},{"title":"Cook beef","description":"Heat the oil in a large non-stick pan over high heat. Cook garlic for 10 seconds, then add the beef and cook until you can no longer see pink. Add 1 1/2 tablespoons of the Sauce and the white part of the green onions. Cook for another 2 minutes to get the beef nicely caramelised.","duration":0.16666666666666666,"images":[],"step":4},{"title":"Finish sauce","description":"Mix the cornflour slurry into the remaining sauce.","images":[],"step":5},{"title":"Egg","description":"Add the egg into the pan then mix it through the beef, it will sort of scramble. Egg makes the beef stick to the noodles better!","images":[],"step":6},{"title":"Cabbage & carrot","description":"When the egg is mostly cooked, add the carrot and cabbage. Cook for 1 minute until cabbage starts to wilt.","duration":1,"images":[],"step":7},{"title":"Sauce & noodles","description":"Give the sauce a quick mix. Add the bean sprouts, noodles and sauce into the pan. Toss well for 1 minute or until sauce is dispersed through the noodles. Add green part of green onions. Toss for another 1 minute.","duration":1,"images":[],"step":8},{"title":"Serve","description":"Divide between bowls and serve!","images":[],"step":9}]', '["egg","gluten","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","beef-mince-recipes","beef-recipes","chinese-recipes","dinner-tonight","noodles","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f783d2e8882d', 'en', 'US', 'Chili crisp noodles', 'Recipe video. Ridiculously good and ridiculously fast, here by popular demand after a sneak peek on Instagram! Chili crisp oil is the star ingredient here, adds spiciness, awesome crunch, savouriness, and a touch of sweet. Widely available these days - see Note 6.Tastes like Spicy Sichuan Dan Dan Noodles - but much faster to make. LOTS OF SUB OPTIONS because chili crisp carries so much of the flavour weight here!', 'https://www.recipetineats.com/tachyon/2023/06/Chili-crisp-noodles_2.jpg', 7, 0, 7, 2, '[{"id": "ing_sesame_seeds", "quantity": {"value": 0.3, "unit": "pack of 100g"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.3, "unit": "pack of 100g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 2.0, "unit": "pack of 100g"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_ramen_noodles", "quantity": {"value": 35.0, "unit": "pack of 4"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.28, "unit": "pack of 500g"}}]', '[{"ingredients":["2 tbsp Chinese sesame paste (Note 1 subs)","2 tbsp light soy sauce (Note 2)","1 tbsp rice vinegar (Note 3)","1 tsp white sugar (or other sugar, or honey, maple)","2 tsp sesame oil (, toasted (Note 4))","1/8 tsp+ cooking / kosher salt (Note 5)","2 heaped tbsp chilli crisp (get oil + chili bits)","1 tbsp ginger (, finely minced*)","1 tbsp garlic (, finely minced*)","1 green onion stem (, finely sliced (or 1/4 red onion finely sliced))","1/3 cup coriander/cilantro (, roughly chopped*)"]},{"ingredients":["140g/ 5oz (2 cakes) instant noodles / ramen noodles","250g/8oz fresh noodles (like hokkien, lo mein)"],"purpose":"Noodle options (Note 7):"}]', '[{"title":"CHECK the spiciness of your chilli crisp","description":"taste it!! Laoganma is not actually that spicy (most store bought brands I''ve used are similar) and the quantity used is based on that brand. If yours is very spicy, start with less and add more later.","images":[],"step":1},{"title":"Base sauce","description":"Mix the sesame oil, vinegar, soy, sugar, salt and sesame paste in a bowl. Top with green onion (don’t mix in).","images":[],"step":2},{"title":"Sizzling chili crisp","description":"Heat chilli crisp and oil in a small pan over medium heat. Add ginger and garlic, stir 30 seconds until golden and it smells amazing. Pour over green onion - enjoy the sizzle! Then mix.","images":[],"step":3},{"title":"Toss","description":"Cook noodles per packet directions. Drag the noodles straight from the saucepan into the bowl (extra water loosens the sauce). Toss. Use cooking water to loosen more if needed. Toss through coriander/cilantro.","images":[],"step":4},{"title":"Adjust & finish","description":"Taste. Add more salt if needed and more chilli crisp if desired (not all chilli crisp is the same saltiness / spiciness). Eat!","images":[],"step":5}]', '["gluten","sesame","soy"]', '["vegetarian"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","chinese-recipes","modern-asian","noodles","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_709a5f652dd3', 'en', 'US', 'Xinjiang Cumin Lamb Stir Fry', 'Recipe video above. A cumin spiced lamb dish might sound totally un-Chinese, but it''s actually authentic and very on-trend! Hailing from the Xinjiang province of China, if you love Middle Eastern and Chinese food, you will love this. Bold cumin flavour with tingling "cold" spiciness from Sichuan pepper and earthy chilli flavour (but not spiciness) from the dried chillis.Spice level - On the upper warm buzz side, but not fiery heat because Sichuan pepper is a different type of spiciness, see note 4.Recipe credit: Adapted from Real-Deal Xinjiang Cumin Lamb from Omnivore''s Cookbook, one of my trusted sources for authentic Chinese cooking. I made a few minor tweaks to streamline but the flavour is bang on!', 'https://www.recipetineats.com/tachyon/2023/05/Xinjiang-Cumin-Lamb-Stir-Fry_3.jpg', 15, 8, 53, 4, '[{"id": "ing_lamb", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.031, "unit": "tub of 200g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.075, "unit": "pack of 400g"}}, {"id": "ing_cumin", "quantity": {"value": 0.75, "unit": "jar of 40g"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_chilli", "quantity": {"value": 0.75, "unit": "pack of 100g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 8.333, "unit": "pack of 3 heads"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_rice", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["500g/ 1 lb boneless lamb leg meat (or rump) (, sliced 1/2 cm / 1/5\" thick (Note 1))","1 tbsp soy sauce (, light or all-purpose (not dark or sweet))","1 tbsp Chinese cooking wine (Note 2)","1/2 tsp cooking/kosher salt","1 1/4 tsp baking soda (, sifted if lumpy (Note 3))","2 tbsp cornflour / cornstarch"],"purpose":"Lamb & marinade:"},{"ingredients":["2 tbsp cumin powder","1/2 tsp white sugar","1/2 tsp ground Sichuan pepper (Note 4 to grind your own)"],"purpose":"Spice mix:"},{"ingredients":["4 tbsp vegetable oil (or canola, peanut)","1/2 cup dried Chinese chillis (, whole, 25-30 pcs (Note 5))","1 onion (, halved then sliced 8mm / 1/4\" thick)","2 tbsp finely minced ginger (~5cm/2\" piece)","5 cloves garlic (, finely sliced)","1/2 cup coriander/cilantro (, roughly chopped)","1 tsp toasted sesame seeds","Plain rice (, fried rice - more suggestions listed in post)"],"purpose":"Stir fry:"}]', '[{"title":"Marinade","description":"Combine lamb, soy sauce, Chinese cooking wine, salt, baking soda and cornflour in a mixing bowl. Mix well then set aside for marinade for 30 minutes (counter fine).","duration":30,"images":[],"step":1},{"title":"Spice mix","description":"Mix the ingredients in a small bowl.","images":[],"step":2},{"title":"Cook lamb","description":"Heat 3 tablespoons of the oil in a large non-stick skillet (30cm/1\") over medium-high heat until hot. Add half the lamb and spread out in a single layer. Leave for 30 seconds then, using 2 wooden spoons, toss for a further 1 minute until the lamb is slightly golden. Remove onto a plate then repeat with remaining lamb (you shouldn''t need more oil).","duration":0.5,"images":[],"step":3},{"title":"Sauté aromatics","description":"Heat the remaining 1 tablespoon of oil. Add the dried chilli, ginger and garlic. Stir for 10 seconds to release flavour, then add the onion. Cook for 2 minutes until the onion just starts to soften.","duration":0.16666666666666666,"images":[],"step":4},{"title":"Spiced lamb","description":"Add the cooked lamb then sprinkle the spice mix over. Toss well to evenly coat.","images":[],"step":5},{"title":"Finish dish","description":"Add the cilantro, sesame seeds and toss. Serve over rice! (Note: the dried chillies are not meant to be eaten.)","images":[],"step":6}]', '["gluten","peanuts","sesame","soy"]', '["high_protein","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","chinese-recipes","lamb","lamb-recipes","mains","modern-asian","quick-and-easy","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8e8c2f23ee7c', 'en', 'US', 'Spicy Korean Noodle Soup (quick & healthy)', 'Recipe video above. For all those times you need a spicy Asian noodle fix - FAST! This packs a serious flavour punch. The secret is the juices from the kimchi jar and a good dollop of gochujang, that magical spicy Korean paste you can get "everywhere" these days. To add protein, cook raw prawns/shrimp or fish pieces in the broth (only takes 3 min), or top with slices of BBQ pork. You can also poach chicken in the broth using this foolproof method.', 'https://www.recipetineats.com/tachyon/2023/05/Spicy-Korean-noodle-soup_4.jpg', 5, 15, 20, 2, '[{"id": "ing_chicken_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_cabbage", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_kimchi_juice", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_gochujang", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_ginger", "quantity": {"value": 0.08, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.4, "unit": "pack of 500g"}}, {"id": "ing_stems_choi_sum", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.125, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.75, "unit": "bunch"}}]', '[{"ingredients":["4 cups / 1 litre chicken stock/broth (, low-sodium)","2/3 cup cabbage kimchi (Note 1)","2 tbsp kimchi juice (, from kimchi tub (Note 1))","3 tbsp gochujang (Note 2)","2 tbsp light soy sauce (Note 3)","2 tsp fish sauce (sub more soy)","1 tbsp Chinese cooking wine (Shaoxing wine, Note 4)","2 slices ginger (, sliced 0.7cm / 1/3\" thick (skin on))","1 large garlic clove (, smashed (Note 5))"],"purpose":"Spicy Korean Soup Broth"},{"ingredients":["200g/ 7oz thin fresh egg noodles (or 100g/3.5oz dried - Note 6)","4 stems choi sum (or other Asian greens, cut into 7cm / 2.5\" lengths, stems separated from leafy part)","1 small carrot (, peeled, cut into thin matchsticks)","2 1/2 tsp sesame oil (, toasted (Note 8))","1/4 cup finely sliced green onions (1 stem)"],"purpose":"Add-Ins (Note 7):"}]', '[{"title":"Broth","description":"Place all broth ingredients in a saucepan. Bring to a simmer over medium-high heat, then reduce heat so it’s simmering gently. Simmer 10 minutes without a lid.","images":[],"step":1},{"title":"Cook vegetables","description":"Add choi sum stems and carrot to the broth. Simmer for 2 minutes. Add choi sum leaves and simmer for another minute. Stir in sesame oil just before serving.","duration":2,"images":[],"step":2},{"title":"Noodles","description":"Meanwhile, cook egg noodles in boiling water per packet directions. Drain, give the noodles a quick rinse under tap water. Shake off excess water well.","images":[],"step":3},{"title":"Assemble","description":"Divide noodles between bowls. Top with the vegetables. Pick the garlic and ginger out of the broth, then broth pour over the noodles. Sprinkle with green onions and serve!","images":[],"step":4}]', '["egg","fish","gluten","sesame","soy"]', '["high_protein","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian","Korean"],"categories":["asian-recipes","asian-soups","korean-recipes","noodles","quick-and-easy","soup-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_34918cac7840', 'en', 'US', 'AMAZING vegetarian lettuce wraps', 'Recipe video. The meat-free version of Chinese san choy bow. You never knew vegetarian lettuce wraps could be so delicious. I never knew either, until I made these! Crumbled tofu lends the filling a meaty texture while vegetables add lovely texture, all smothered in a glossy, savoury sauce. Vegetarian food (and healthy, no less!) was never so delicious. And interesting. And easy. It''s AMAZING!Feel free to substitute the veg with other sauté-able vegetables of choice.', 'https://www.recipetineats.com/tachyon/2023/03/Vegetarian-lettuce-wraps_4.jpg', 15, 10, 25, 2, '[{"id": "ing_cornstarch", "quantity": {"value": 0.016, "unit": "pack of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_tofu", "quantity": {"value": 0.833, "unit": "pack of 300g"}}, {"id": "ing_oil", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 75.0, "unit": "pack of 1kg"}}, {"id": "ing_green_beans", "quantity": {"value": 75.0, "unit": "pack"}}, {"id": "ing_mushroom", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 240.0, "unit": "head"}}, {"id": "ing_peanuts", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sriracha", "quantity": {"value": 1.0, "unit": "bottle of 400ml"}}]', '[{"ingredients":["1 1/4 tsp cornflour / cornstarch","3 tbsp water","1 1/2 tbsp light soy sauce (Note 1)","1 tsp dark soy sauce (Note 1)","1 1/2 tbsp oyster sauce (Note 2)","1 tsp sesame oil (, toasted)","1 tbsp Chinese cooking wine (or sub Mirin or dry sherry, Note 3)","1 tsp white sugar","1 tsp finely grated ginger (sub garlic)"],"purpose":"San choy bow sauce:"},{"ingredients":["250g/8oz extra firm tofu (Note 4)","1 tbsp oil","1 garlic (, finely minced)","1/2 onion (, finely diced)","1/2 cup carrot (, chopped into 5mm/ 0.2\" pieces)","1/2 cup green beans (, sliced into 5mm/0.2\" rounds)","1/2 cup mushroom (, chopped into 5mm/ 0.2\" pieces)"],"purpose":"Filling:"},{"ingredients":["12 lettuce leaves (+/- depending on lettuce size, Note 5)","Peanuts (, finely chopped (I like salted, but unsalted fine))","Green onion (, finely sliced)","Sriracha (, for drizzling (highly recommended))"],"purpose":"Wraps:"}]', '[{"title":"Sauce","description":"Mix cornflour/cornstarch with water until lump free. Add everything else, then mix.","images":[],"step":1},{"title":"Crumble tofu","description":"Drain tofu, then cut into 5mm/0.2\" slices. Use your fingers to crumble into a mince. Not too fine crumbs, can always break up more when cooking (just like cooking mince/ground meat!).","images":[],"step":2},{"title":"Filling","description":"Heat oil over high heat in a large non stick pan. Cook onion, garlic and carrot for 1 minute. Add green beans and mushrooms. Cook 2 minutes - green beans should still be firm.","duration":1,"images":[],"step":3},{"title":"Sauce it","description":"Add tofu and toss through. Pour in the sauce. Stir for 1 minute or until the sauce thickens and is coating the mixture nicely. (If it evaporates too quickly, add a splash of water)","duration":1,"images":[],"step":4},{"title":"Serving","description":"Transfer filling into a bowl. Lay out on the table with lettuce leaves, green onion, peanuts and bottle of sriracha.","images":[],"step":5},{"title":"DIY lettuce wraps","description":"Spoon filling into lettuce leaf. Drizzle with sriracha, sprinkle with peanuts and green onion. Bundle / fold, eat!","images":[],"step":6}]', '["gluten","sesame","soy"]', '["low_calorie","vegan","vegetarian"]', '{"mealType":["dinner","snack"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","asian-takeout","chinese-recipes","dietary","low-calorie-recipes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_077b3a509ad3', 'en', 'US', 'Mango pancakes', 'Recipe video above. Everybody''s favourite at yum cha! Forget the long weekend queues, make them yourself. It''s 75% cheaper and they taste exactly like the real thing.If this is your first time, allow for some crepe-learning causalities (hence I say 9 - 12 pancakes). Even better, just double the batter so you have plenty to practice with and eat leftovers for breakfast!', 'https://www.recipetineats.com/tachyon/2023/02/Mango-pancakes-cut-open.jpg', 20, 20, 40, 10, '[{"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.094, "unit": "pack of 400g"}}, {"id": "ing_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 250.0, "unit": "carton of 12"}}, {"id": "ing_red_food_colouring", "quantity": {"value": 0.25, "unit": "unit"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_mango", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.05, "unit": "bottle of 50ml"}}]', '[{"ingredients":["1 cup milk (, full fat)","1/3 cup plain flour (all-purpose flour)","1/4 cup cornflour / cornstarch","1/4 cup icing sugar / powdered sugar","3 large eggs (55-60g/2oz each)","1/4 tsp yellow food colouring (Note 1)","Canola oil spray"],"purpose":"The pancake (crepe!):"},{"ingredients":["2 large ripe mangoes (, skin peeled with a knife, cut into 10 to 12 pieces (7 x 2.5 x 1 cm, 3 x 1 x 1/2\"))"],"purpose":"Mango (Note 2):"},{"ingredients":["3/4 cup thickened/heavy cream (, fridge cold)","3 tbsp icing sugar / powdered sugar (, sifted)","1/2 tsp vanilla extract"],"purpose":"Cream filling:"}]', '[{"title":"Batter","description":"Place the milk in a bowl. Sift the flour, cornflour and icing sugar in then whisk until lump free. Add eggs and food colouring, whisk until combined. It will be a very thin, watery batter.","images":[],"step":1},{"description":"Refrigerate for 1 hour. (Note 3)","images":[],"step":2},{"title":"Measure batter","description":"Give the batter a mix (to stir in flour settled at bottom) then measure out 45 ml (3 tbsp) of crepe batter.","images":[],"step":3},{"title":"Non-stick pan","description":"Use a 18cm/7\" non-stick pan (Note 4). Spray lightly with oil then heat over a medium low stove.","images":[],"step":4},{"title":"Cook pancake","description":"Pour the batter into the middle - it should sizzle very lightly - then swirl to cover the base in a thin layer. Cook for 45 seconds to 1 minute or until the middle is set to touch. About halfway through cooking, start loosening the edges with a rubber spatula to ensure it flips out easily.","duration":0.75,"images":[],"step":5},{"description":"Flip the crepe out upside down onto a large cutting board. GOAL: Surface is set, underside has no golden patches. (Note 5) Adjust heat as needed.","images":[],"step":6},{"description":"Cook more! Spray pan with oil then continue cooking the pancakes. You can flip them out on top of each other.","images":[],"step":7},{"title":"Cool","description":"Full cool the crepes for 1 hour before using.","images":[],"step":8},{"title":"Cream","description":"Just before assembling, place the cream, icing sugar and vanilla in a cold bowl and beat until stiff (about 2 minutes on speed 8 of a 10 speed hand mixer).","images":[],"step":9},{"title":"Filling","description":"Place a crepe on a work surface so the side that was in contact with the pan is facing up. (Note 6) Spread 1cm/1/3\" thick layer of cream one-third of the way up the pancake, in the shape of a piece of mango. Top with mango.","images":[],"step":10},{"description":"Roll, burrito style (see step photos or video), ending with the seam-side down. Repeat with remaining pancakes.","images":[],"step":11},{"description":"Serve immediately! Mango pancakes wait for no-one (due to the cream).","images":[],"step":12}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","dessert-recipes","yum-cha-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e906d00f3e36', 'en', 'US', 'Firecracker Beef', 'Recipe video above. This is a thrifty yet excellent dinner for all those times you need to scratch your Spicy Asian Food itch, fast! Seared beef mince gets tossed through a fiery Firecracker Sauce, tastes a bit like a spicy beef version of the much-loved Vietnamese Caramelised Pork Mince. Sweetness & spice level - Fairly spicy! See notes to reduce. Firecracker sauce is supposed to be a bit sweet to offset spice, also see notes.', 'https://www.recipetineats.com/tachyon/2022/11/Firecracker-beef-mince_2-2.jpg', 3, 10, 13, 4, '[{"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_sriracha", "quantity": {"value": 0.15, "unit": "bottle of 400ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_rice", "quantity": {"value": 30.0, "unit": "pack"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_cucumber", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sriracha", "quantity": {"value": 0.15, "unit": "bottle of 400ml"}}]', '[{"ingredients":["1½ tbsp oil (vegetable, canola, peanut)","500g / 1 lb beef mince / ground beef (Note 1)","2 garlic cloves (, finely minced)","1 tsp chilli flakes / red pepper flakes (adjust to your taste)","3 tbsp water"]},{"ingredients":["2 tbsp soy sauce (, light or all-purpose (Note 2))","2 tbsp rice vinegar (Note 3)","4 tbsp sriracha sauce (Note 4)","4 tbsp brown sugar (tightly packed)"],"purpose":"Firecracker sauce:"},{"ingredients":["Rice, (soba or vermicelli noodles)","1 green onion (, finely sliced)","1 tsp sesame seeds","Diced cucumber, julienned carrot, finely sliced red radish","Extra sriracha sauce (, if you dare!)"],"purpose":"To serve (optional!):"}]', '[{"title":"Sauce","description":"Mix Firecracker sauce ingredients in a small bowl and set aside.","images":[],"step":1},{"title":"Cook beef","description":"Heat oil in a large frypan over high heat. Add beef and cook, breaking it up as you go, until you can no longer see raw meat (2½ minutes). Add garlic and chilli flakes and cook for 1 minute.","duration":1,"images":[],"step":2},{"title":"Caramelise beef","description":"Add Firecracker sauce ingredients, stir to coat the beef. Cook for 5 to 7 minutes, stirring only every minute or so initially, then more towards the end, until the sauce reduces and you can see the beef caramelising. Caramelise well for good flavour!","duration":6,"images":[],"step":3},{"title":"Water","description":"Add the water and cook for 1 minute (the water makes the beef saucier!)","duration":1,"images":[],"step":4},{"description":"Serve over rice, sprinkled with sesame seeds, green onion and a squirt of extra sriracha if you''re feeling brave! Add a pile of vegetables of choice on the side. Dive in!","images":[],"step":5}]', '["gluten","peanuts","sesame","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","beef","beef-mince-recipes","beef-recipes","dinner-tonight","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b8e7f32b3af1', 'en', 'US', 'Vegetable Dumplings (Potstickers!)', 'Recipe video above. 4 years in the making, my favourite vegetable dumpling! These are a standout because you can actually taste the vegetables and it''s got good texture, rather than just being a wad of tasteless, watery mush which is sadly all too common.Don''t get too hung about about the wrapping part. If the pleating is too challenging, just seal it flat. Quicker, easier, and it tastes exactly the same. :)', 'https://www.recipetineats.com/tachyon/2022/09/Vegetable-Dumplings-1-on-plate.jpg', 45, 3, 48, 30, '[{"id": "ing_cabbage", "quantity": {"value": 6.0, "unit": "head"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_mushroom", "quantity": {"value": 8.0, "unit": "kg"}}, {"id": "ing_tofu", "quantity": {"value": 0.375, "unit": "pack of 300g"}}, {"id": "ing_garlic", "quantity": {"value": 0.833, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_potato", "quantity": {"value": 2.0, "unit": "bag of 2kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.075, "unit": "pack of 100g"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 2.0, "unit": "jar of 50g"}}, {"id": "ing_round_dumpling_wrappers", "quantity": {"value": 30.0, "unit": "unit"}}, {"id": "ing_oil", "quantity": {"value": 7.5, "unit": "bottle"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}]', '[{"ingredients":["2 cups green cabbage (, finely chopped into 2mm pieces)","1/2 tsp cooking/kosher salt"],"purpose":"Wilted cabbage for Filling:"},{"ingredients":["8 dried shiitake mushroom (40 g total), medium size (Note 1)","3/4 cup firm tofu (, finely diced into 3-4mm / 1/8\" cubes (Note 2))","1/2 tsp garlic (, finely grated)","1 tsp ginger (, finely grated)","2 tbsp green onion (, finely sliced then minced)","2 tbsp finely grated floury potato (, including juices, for binding (Sebago, russet, Maris piper, Note 3))","1 1/2 tsp toasted sesame oil (Note 4)","1 tsp light soy sauce (or all-purpose, not dark soy)","1/4 tsp sugar (any)","1/4 tsp cooking/kosher salt","2 pinches white pepper (sub black)"],"purpose":"Filling:"},{"ingredients":["30 - 35 round dumpling wrappers (gow gee, Note 5)","2 - 3 tbsp canola oil","1/4 cup water per cooking batch"],"purpose":"Cooking:"}]', '[{"description":"Quick recipe (for pros):","images":[],"step":1},{"description":"Wilt cabbage 20 min, squeeze. Soak mushrooms 30 min, squeeze, finely chop. Mix with remaining Filling ingredients. Wrap. Pan fry 2 min, 1/4 cup water, pan-steam 5 min.","images":[],"step":2},{"title":"Full recipe","description":"filling:","images":[],"step":3},{"title":"Prepare cabbage","description":"Toss cabbage with 1/2 tsp salt in a bowl. Set aside for 20 minutes. Then grab handfuls and squeeze out excess water as best you can. Place squeezed cabbage in a bowl for mixing the filling in.","duration":20,"images":[],"step":4},{"title":"Shiitake mushrooms","description":"Soak mushrooms in 1 litre of boiling water for 30 minutes. Squeeze out excess liquid and finely chop into 2 mm pieces. Add to the filling bowl.","duration":30,"images":[],"step":5},{"title":"Potato","description":"Add grated potatoes to filling mix, including all the liquid that leached out when you grated it. We want all that starchy juice for its binding power!","images":[],"step":6},{"title":"Filling","description":"Add remaining ingredients into the filling bowl, mix to combine. It will look crumbly - don''t worry, everything sticks together better when steamed thanks to the potato.","images":[],"step":7},{"title":"Dumpling wrappers","description":"Take one wrapper from the packet. Keep unused wrappers covered so they don''t dry out.","images":[],"step":8},{"title":"Wrap dumplings","description":"(See video at 1m 30s!) Place a wrapper in your non-dominant hand. Dip your index finger in water and run it along the lower half of the wrapper (edge closest to you). Place 1 loosely-packed tablespoon of filling in the centre. Fold the wrapping over the filling, then seal with pleats. (If this is too hard, skip the pleats and seal flat).","images":[],"step":9},{"title":"Finished dumplings","description":"Stand dumpling upright with the pleats on top, and lightly press down to flatten the base. Shape gently into a slight curve. Place on a tray lightly dusted with cornflour/cornstarch. Repeat for remaining dumplings. Keep completed dumplings covered with a tea towel to prevent them from drying out. If you''re making ahead, cover dumplings with cling wrap and refrigerate. See storage notes.","images":[],"step":10},{"description":"Cook (pan-frying + steaming):","images":[],"step":11},{"title":"Cooking vessel","description":"Use a large non-stick pan with a lid (Note 6).","images":[],"step":12},{"title":"Pan fry","description":"Heat 1 tablespoon oil over medium high heat. Pan fry 12 to 15 dumplings for 2 minutes until the base is golden brown.","duration":2,"images":[],"step":13},{"title":"Steam","description":"Pour over 1/4 cup water over the dumplings in the skillet - it will steam and bubbly vigorously! Place the lid on and steam for 5 minutes or until the water in the pan has evaporated.","duration":5,"images":[],"step":14},{"description":"Cooked! Remove the lid. The water should have been driven off, and the wrapping should be semi-transparent (indicating it is cooked). The base should be crispy again. If not, leave the pan uncovered for a bit until the base crisps up again in the oil.","images":[],"step":15},{"title":"Serve","description":"Scoop the dumplings up with a spatula and place on a serving plate. Serve with soy sauce and chili paste for dipping, or rice vinegar mixed with soy sauce. Best served fresh - I get another batch cooking as we eat the freshly cooked ones!","images":[],"step":16},{"description":"Steaming-only option:","images":[],"step":17},{"description":"Using either a bamboo steamer set over a large wok with simmering water, or other larger steamer. Line with a fitted sheet of parchment paper with holes, and steam the dumplings for 8 minutes.","duration":8,"images":[],"step":18}]', '["gluten","sesame","soy"]', '["keto_friendly","low_calorie","vegan","vegetarian"]', '{"mealType":["snack","dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chinese-recipes","dumplings"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_787630138c29', 'en', 'US', 'Red Vietnamese Fried Rice', 'Recipe video above. This is the fried rice version of traditional Vietnamese red rice (plain tomato rice steamed in a pot). I added ham, peas and egg to turn it into a quick and easy meal. Frying up the tomato rice with garlic adds extra flavour which is on point!Serves 2 as a meal, or 4 to 5 as a side.', 'https://www.recipetineats.com/tachyon/2022/09/Red-Vietnamese-Fried-Rice_3.jpg', 8, 7, 15, 2, '[{"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_ham", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.375, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}]', '[{"ingredients":["30g / 2 tbsp unsalted butter","3 garlic cloves (, finely minced)","1/2 cup diced ham (I use pre-chopped, Note 1)","1 cup frozen peas","2 1/2 cups day-old cooked jasmine rice (Note 2)","2 tbsp tomato paste","2 tsp fish sauce (Note 3)","2 tsp soy sauce (all purpose or light, not dark soy, Note 4)","1/4 tsp white sugar","2 eggs (, whisked)"]}]', '[{"description":"Melt most of the butter in a large non-stick skillet over high heat (save a dab for scrambling eggs).","images":[],"step":1},{"description":"Add garlic, cook for 10 seconds.","duration":0.16666666666666666,"images":[],"step":2},{"description":"Add ham, stir for 30 seconds.","duration":0.5,"images":[],"step":3},{"description":"Add peas, stir for 30 seconds.","duration":0.5,"images":[],"step":4},{"title":"Rice and tomato paste","description":"Add rice and tomato paste, cook for 2 minutes.","duration":2,"images":[],"step":5},{"title":"Sauces","description":"Add fish sauce, soy and sugar, cook 1 minute to get a bit of nice caramelisation on the tomatoey rice.","images":[],"step":6},{"title":"Scramble eggs","description":"Push rice to one side of the pan. In the cleared space, melt reserved butter then pour in the egg and scramble until just set.","images":[],"step":7},{"title":"Serve","description":"Toss cooked egg through the rice. Serve!","images":[],"step":8}]', '["egg","fish","gluten","milk","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Vietnamese"],"categories":["asian-recipes","fried-rice","modern-asian","quick-and-easy","rice-recipes","rice-side-dishes","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a9ca2a056a5d', 'en', 'US', 'Teriyaki Salmon Noodles', 'Recipe video above. Here''s a great quick noodle recipe that''s got everything you want for a meal. It''s got carbs, veg and protein. It''s quick. It''s one-pan. It''s easy. And it''s super tasty!! This is also a delicious dish that can wring two generous meal servings from just one piece of salmon. An economical tip! :)', 'https://www.recipetineats.com/tachyon/2022/07/Teriyaki-Salmon-Noodles_1-1.jpg', 5, 10, 15, 2, '[{"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 2.0, "unit": "pack of 500g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_broccoli", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.15, "unit": "bottle of 250ml"}}, {"id": "ing_mirin", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_cooking_sake", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2 tbsp oil (veg or canola)","250 g / 8 oz salmon fillet (s), skinless, sliced into 2cm / 0.7\" strips (lengthwise, Note 1)","2 instant noodle / ramen noodle cakes (discard seasoning packs) (Note 2 other noodles)","1/2 onion (, cut into 1cm / 0.3\" slices)","1 garlic clove (, finely minced)","1 small bunch Chinese broccoli (gai lan), cut into 5 cm / 2\" lengths, leaves separated from stem (Note 3)"]},{"ingredients":["2 1/2 tbsp soy sauce (, light or all-purpose (Note 4))","2 tbsp mirin (Note 5)","2 tbsp cooking sake (Note 5)","1 tsp white sugar"],"purpose":"Teriyaki Sauce:"}]', '[{"title":"Teriyaki Sauce","description":"Mix the ingredients in a small bowl until the sugar is dissolved.","images":[],"step":1},{"description":"Coat salmon with 1 tablespoon of Teriyaki Sauce in a bowl, then set aside while you cook the noodles. (No need to marinate)","images":[],"step":2},{"description":"Cook your noodles per the packet directions. Drain, briefly rinse under tap water then set aside.","images":[],"step":3},{"title":"Cook salmon","description":"Heat 1/2 tablespoon oil in a large non-stick pan over high heat. Cook the salmon for 1 1/2 minutes on each side or until golden, then remove to a plate. Pour any remaining sauce in the skillet over the salmon.","images":[],"step":4},{"title":"Cook aromatics","description":"Roughly clean the pan with a paper towel then return to the stove, still on high heat. Heat 1 tablespoon of the remaining oil and cook the onion and garlic for 30 seconds. Add Chinese broccoli stems and cook for 1 minute.","duration":0.5,"images":[],"step":5},{"title":"Noodles & sauce","description":"Add noodles and half the Sauce. Toss for 2 minutes until the Sauce is absorbed. Add the remaining Sauce and toss to disperse. Then spread the noodles out in the pan, cook for 30 seconds un-disturbed. Repeat again 3 to 4 times (~3 min total) - a trick for nice caramelisation on the noodles (which = flavour!).","duration":2,"images":[],"step":6},{"title":"Leafy greens","description":"Drizzle the remaining 1/2 tablespoon oil around the side of the pan, then add the Chinese broccoli leaves. Toss for a further 1 1/2 minutes or until the leaves wilt.","images":[],"step":7},{"title":"Add back salmon","description":"Remove pan from stove. Place salmon on top, break into large chunks then toss through.","images":[],"step":8},{"title":"Serve","description":"Divide between bowls and serve immediately!","images":[],"step":9}]', '["fish","gluten","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","noodles"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_20c1ee39fb9f', 'en', 'US', 'Supreme Soy Noodles', 'Recipe video above .Soy noodles needs more than just soy sauce, otherwise they are way too boring! This is a great Chinese noodle side for everything Asian. They''re flavoured enough to eat plain, but neutral enough to serve alongside mains (see in post for accompanying main suggestions). Supremely easy, supremely tasty - Supreme Soy Noodles!If you want to add more veg and protein, better to use the Lo Mein recipe (need more sauce!).', 'https://www.recipetineats.com/tachyon/2022/05/Picking-up-Supreme-Soy-Noodles-chopsticks.jpg', 5, 5, 10, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_green_onion", "quantity": {"value": 0.16, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_mirin", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}]', '[{"ingredients":["500 g / 1 lb fresh yellow or white noodles (, medium thickness (see Note 1))","2 tbsp oil (vegetable, canola, or peanut)","8 green onions (, ends trimmed, cut into 7cm / 2.5” lengths, white parts separated from green parts)","2 garlic cloves (, finely chopped)"]},{"ingredients":["2 tsp sesame oil (toasted sesame oil)","2 tsp light soy sauce (Note 2)","1 tbsp dark soy sauce (Note 2)","1 tbsp oyster sauce (Note 3)","1 tbsp mirin (Note 4 for subs)"],"purpose":"Soy-sauce noodle sauce:"}]', '[{"description":"Mix Sauce ingredients in a small bowl.","images":[],"step":1},{"description":"Cook noodles per packet directions (see cooking tip in Notes). Drain and give it a quick rinse under tap water to stop them sticking together as they sit.","images":[],"step":2},{"title":"Sauté garlic","description":"Heat oil in a large deep non-stick skillet or wok over high heat. Add white part of green onions, stir for 20 seconds. Add garlic and stir for 10 seconds or until light golden.","duration":0.3333333333333333,"images":[],"step":3},{"title":"Add noodles, sauce","description":"Add noodles then pour over Sauce. Toss for 1 1/2 minutes. Don’t skimp on this step, the flavour is so much better when the noodles caramelise slightly. If your stove is a bit weak, you might need to go longer!","images":[],"step":4},{"title":"Green onions","description":"Add green onion and toss until just wilted, about 20 seconds. Serve immediately.","images":[],"step":5}]', '["gluten","peanuts","sesame","soy"]', '["low_calorie","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","asian-takeout","chinese-recipes","noodles","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6d98a13ffa3b', 'en', 'US', 'Honey Prawns - stays crispy for ages!', 'Recipe video above. A recipe for old school Chinese restaurant style Honey Prawns! This recipe uses a proven method used in my Honey Chicken recipe for Honey Prawns that stays crispy hours even after coating in the sauce!1. Double coating - cornflour/cornstarch to seal in juices, followed by batter.2. Cold batter made with soda water = crispier coating that''s puffy and light, not dense and greasy.3. Cornflour/cornstarch + flour batter - cornflour for ultra crispiness, flour for golden colour.4. Double fry for extra long lasting, thicker crispiness AND less greasy (Asian secret!).5. No-soggy Sauce - glucose or corn syrup to make it "candy like" to stick on the prawn crust rather than soaking in, plus NO WATER in the sauce.Note - the sauce is sweet. That''s the way it''s supposed to be! But not as sickly sweet as many Chinese restaurants tend to be. Please do not try to change the sauce as it has been formulated to prevent making the batter soggy.', 'https://www.recipetineats.com/tachyon/2021/09/Honey-Prawns_23.jpg', 10, 20, 30, 4, '[{"id": "ing_shrimp", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.188, "unit": "pack of 400g"}}, {"id": "ing_flour", "quantity": {"value": 0.09, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.017, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.013, "unit": "tub of 200g"}}, {"id": "ing_oil", "quantity": {"value": 3.0, "unit": "bottle"}}, {"id": "ing_honey", "quantity": {"value": 0.167, "unit": "jar of 500g"}}, {"id": "ing_corn", "quantity": {"value": 0.056, "unit": "can of 400g"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.02, "unit": "bottle of 500ml"}}, {"id": "ing_rice_noodles", "quantity": {"value": 0.067, "unit": "pack of 375g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["300g/ 10oz prawns/shrimp (, peeled with tail on (600g/1.2lb whole unpeeled) (Note 1))","1/2 tsp kosher/cooking salt (halve for table salt)"],"purpose":"Prawns"},{"ingredients":["1/2 cup cornflour/cornstarch"],"purpose":"Dredging:"},{"ingredients":["9 tbsp cornflour/cornstarch (Note 2)","6 tbsp flour (, plain/all-purpose)","1/2 tsp baking powder (NOT baking soda)","1/2 tsp kosher/cooking salt (halve for table salt)","2/3 cup + 1 tbsp COLD soda water, club soda or seltzer water (NOT sparkling mineral water, Note 3)"],"purpose":"Ultra-crispy fry batter:"},{"ingredients":["3 - 4 cups vegetable or canola oil (~4cm / 1.5\" depth in a pot)"],"purpose":"Oil, for frying:"},{"ingredients":["1/3 cup (100g) honey","1.5 tbsp (25g) glucose OR corn syrup (light) (Note 4)","1 tbsp light soy sauce (or all-purpose)","2 tsp Chinese cooking wine (or mirin)"],"purpose":"Honey Sauce (Note 8 on sweetness):"},{"ingredients":["25g / 2 oz Vermicelli rice noodles (optional) (, a wad of it (not mung bean noodles, it must be rice noodles))","Sesame seeds, finely sliced green onions"],"purpose":"Garnish / serving:"}]', '[{"description":"Season and dust prawns:","images":[],"step":1},{"title":"Salt prawns","description":"Mix prawns with salt. (Don''t do this ahead, salt makes prawns sweat = compromise crispy coating!)","images":[],"step":2},{"title":"Dust","description":"Place 1/2 cup cornflour/cornstarch in a bowl. Dip prawn in, shake off excess then put on a plate. Repeat with all prawns.","images":[],"step":3},{"description":"Cold batter and fry #1:","images":[],"step":4},{"title":"Chill dry ingredients","description":"Whisk together flour, cornflour/cornstarch, baking powder and salt in a bowl. Place in fridge while oil heats up. (Helps keep batter cold, cold batter = crispier prawns)","images":[],"step":5},{"title":"Heat oil","description":"Fill small pot or large saucepan with 4cm / 1.7\" oil. Heat to 160°C/320°F on medium high stove.","images":[],"step":6},{"title":"Make cold batter","description":"When the oil is near target temp, add soda water into the dry ingredients. Then do the minimum whisks to just combine (10 or so) - a few lumps ok, better than whisking too much (changes coating texture).","images":[],"step":7},{"title":"Batter thickness","description":"Should fully coat prawns easily, not be see-through, but not thick and heavy. See video at 38 seconds for cues. Use extra soda water 1 teaspoon at a time to achieve right thickness.","images":[],"step":8},{"title":"Dredge","description":"Holding a prawn by the tail, dip into the batter then hold up for a 2 seconds to let the excess batter drip off. Then carefully place in oil. Repeat with another 5 prawns (6 per batch).","images":[],"step":9},{"title":"3 minutes Fry #1","description":"Cook for 3 minutes until light golden and crispy. When you pick them up, you can tell it''s very crispy.","duration":3,"images":[],"step":10},{"title":"Drain and repeat","description":"Place prawns on a tray with paper towels. Repeat with remaining prawns. I cook in 4 batches. Don''t crowd the pot as it brings oil temperature down too much.","images":[],"step":11},{"description":"Cool prawns for 20 minutes (Note 5). Meanwhile, make Sauce.","duration":20,"images":[],"step":12},{"title":"Simmer","description":"Place ingredients in a small saucepan over medium heat. Bring to simmer, turn down stove to medium low then leave to simmer for 3 minutes.","duration":3,"images":[],"step":13},{"title":"Syrupy consistency","description":"The consistency should be like maple syrup (see video). Turn off stove, place lid on to keep warm (when cool, it gets too thick to toss prawns in it).","images":[],"step":14},{"title":"Fry #2","description":"for ultra-crispy!","images":[],"step":15},{"description":"Heat oil to 200°C/390°F.","images":[],"step":16},{"title":"3 minutes Fry #2","description":"Place half the prawns in oil (you can crowd the pot for Fry #2). Cook for 3 minutes or until it changes from pale golden to very golden, then remove to a paper towel-lined plate. You can tell by touching that it''s built-to-last crispy! More golden = crispier (but don''t overcook the prawns!) Repeat with remaining prawns.","duration":3,"images":[],"step":17},{"description":"Sauce and serve:","images":[],"step":18},{"title":"Quickly toss","description":"Transfer prawns to a metal bowl then pour over Honey Sauce. Quickly toss with rubber spatula to coat prawns in sauce. (Sauce starts thickening if you take too long, so be quick!)","images":[],"step":19},{"title":"Garnish","description":"Pile prawns over crispy rice noodles (if using), scatter with sesame seeds, green onion and serve!","images":[],"step":20},{"description":"Puffy crispy rice noodles (optional):","images":[],"step":21},{"description":"At any point while oil is hot, drop a wad of noodles into hot oil, wait 3 seconds until it puffs up, then remove with tongs.","images":[],"step":22},{"description":"Drain on paper towels, place on plate. Top with prawns! (Note: Crispy noodles stays crispy \"forever\" so you can do this well ahead. Not for eating - is flavourless.)","images":[],"step":23}]', '["gluten","sesame","shellfish","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chinese-recipes","deep-fried-recipes","prawns-shrimp"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2c0a261f4050', 'en', 'US', 'Sesame Crusted Tofu Steaks with Teriyaki Sauce', 'Recipe video above. Sesame seeds add excellent flavour and give tofu a crispy crust crust that stays crispy even when doused with Teriyaki Sauce. Great quick and easy recipe to convert tofu haters - so far from bland, we''re in a different stratosphere!', 'https://www.recipetineats.com/tachyon/2021/09/Crispy-Sesame-Tofu-Steaks-hero.jpg', 5, 10, 15, 4, '[{"id": "ing_tofu", "quantity": {"value": 4.0, "unit": "pack of 300g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.6, "unit": "pack of 100g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.6, "unit": "pack of 100g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_mirin", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_cooking_sake", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}]', '[{"ingredients":["4 extra firm or hard tofu (, cut into 10 x 5 x 1.5cm slices (4 x 2 x 0.6\"), 100g / 3.5oz each (Note 1))","1/4 tsp each salt and pepper","2 tbsp flour (, plain/all purpose)","1 egg (, lightly whisked)","4 tbsp white sesame seeds (Note 2) (yes, you really need 4 tbsp!)","4 tbsp black sesame seeds (Note 2)","2 tbsp canola/vegetable oil","2 garlic cloves (, finely sliced 1mm thick (optional, Note 2))","1 green onion (, finely sliced (for garnish))"]},{"ingredients":["2 tbsp soy sauce (, preferably Japanese all-purpose, else light soy sauce (Note 4))","2 tbsp mirin (, preferably Japanese (Note 5))","2 tbsp cooking sake (, preferably Japanese (Note 6))","2 tbsp water"],"purpose":"Teriyaki Sauce:"}]', '[{"description":"Sesame coating:","images":[],"step":1},{"title":"Season tofu","description":"Pat tofu dry with paper towels. Sprinkle with salt and pepper.","images":[],"step":2},{"title":"Prepare crust coating","description":"Place flour, egg and sesame in separate bowls (medium shallow bowls or tupperware best).","images":[],"step":3},{"title":"Sesame crust","description":"Press tofu into flour, shake off excess. Dip in egg, then let excess drip off before coat in sesame seeds, pressing to adhere all over. Repeat with remaining tofu.","images":[],"step":4},{"description":"Cooking:","images":[],"step":5},{"title":"Crispy garlic","description":"Heat oil in a non stick skillet over medium heat. Add garlic and cook until golden and crisp. Remove and drain on paper towels.","images":[],"step":6},{"title":"Cook tofu","description":"Turn heat up to medium-high. Place tofu in skillet and cook for 1 1/2 minutes until the sesame smells nutty and becomes crisp. Turn carefully and cook the other side for 1 1/2 minutes. Then use tongs to prop the tofu steaks up on its sides to sear the edges until crisp - about 30 seconds each side should do it (see video for my technique).","images":[],"step":7},{"title":"Drain","description":"Remove tofu to paper towel lined plate.","images":[],"step":8},{"title":"Teriyaki Sauce","description":"Lower heat to medium then add Teriyaki Sauce ingredients. Simmer for 1 minute until it reduces to a syrupy consistency, then remove skillet from stove.","duration":1,"images":[],"step":9},{"title":"Serve","description":"Place tofu steak on plate. Spoon over Teriyaki Sauce (it clings to sesame, don''t worry, crust stays crispy). Sprinkle with garlic and green onion. Devour, then declare, \"I LOVE TOFU!!\".","images":[],"step":10}]', '["egg","gluten","sesame","soy"]', '["low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Japanese(ish)","Modern Asian"],"categories":["asian-recipes","dietary","dinner-tonight","low-calorie-recipes","quick-and-easy","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_59b37d24b607', 'en', 'US', 'Ayam Goreng (Malaysian Fried Chicken)', 'Recipe video above. Marinated in a curry paste made with lemongrass, garlic and spices then tossed in cornflour to make the coating ultra craggy and crunchy, Ayam Goreng is Malaysia''s answer to Southern Fried Chicken. Hot contender for the world''s best fried chicken!Spiciness: Very mild. Feel free to dial it up by adding more chilli powder!', 'https://www.recipetineats.com/tachyon/2021/07/Ayam-Goreng_08.jpg', 10, 30, 1480, 4, '[{"id": "ing_chicken", "quantity": {"value": 1.25, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_fennel_seeds", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_galangal", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.15, "unit": "jar of 50g"}}, {"id": "ing_lemongrass", "quantity": {"value": 20.0, "unit": "bunch"}}, {"id": "ing_turmeric", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_eshalots_and_roughly", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.263, "unit": "can of 400ml"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.188, "unit": "pack of 400g"}}, {"id": "ing_oil", "quantity": {"value": 1750.0, "unit": "bottle"}}, {"id": "ing_chilli", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["1.25 kg / 2.5 lb chichen thighs ad drumsticks, bone in skin on ( (I use 4 thighs, 3 drumsticks, Note 1))"]},{"ingredients":["2 tsp coriander seeds","2 tsp cumin seeds","1 tsp fennel seeds"],"purpose":"Toasted spices:"},{"ingredients":["3 garlic cloves (, roughly chopped)","1 tbsp ginger (, roughly chopped)","1 tbsp galangal (, roughly chopped (Note 2))","1 1/2 tsp curry powder (any type fine, mild or spicy - your choice)","1 lemongrass (, white part only roughly chopped (Note 3))","1 tsp turmeric powder","2 small eshalots (French onions, US: shallots), peeled and roughly chopped (Note 4)","1 1/2 tsp cooking/kosher salt (or 1 tsp table salt)","1/2 tsp chilli powder (, adjust to taste (Note 5))","2 tsp brown sugar","7 tbsp coconut milk (full fat best!)"],"purpose":"Ayam Goreng Curry Paste:"},{"ingredients":["1/2 cup cornflour / cornstarch","1.75 litres / quarts vegetable or canola oil"],"purpose":"Cooking:"},{"ingredients":["1 tbsp garlic (,minced (not too small, else it burns))","1 tbsp large red chilli ((cayenne pepper), deseeded and minced)","1 tbsp green onion (, minced)","Pinch of salt","Coriander/cilantro leaves"],"purpose":"Garnish (optional):"}]', '[{"title":"Toast spices","description":"Toast spices in a small skillet over medium heat (no oil) for 2 minutes or until the spices smell fragrant. Transfer seeds into Nutribullet, small food processor OR into a tall jug that fits a stick blender.","duration":2,"images":[],"step":1},{"title":"Curry paste","description":"Add remaining Curry Paste ingredients and blend until smooth.","images":[],"step":2},{"title":"Marinate","description":"Pour Curry Paste over chicken in a ziplock bag (or bowl, Note 6). Toss to coat, then marinate for 24 hours in the fridge, up to 48 hours.","images":[],"step":3},{"description":"PREPARE TO COOK (WORK IN SPECIFIED ORDER OF STEPS):","images":[],"step":4},{"title":"Dechill chicken","description":"Remove chicken from fridge 30 minutes prior to cooking and transfer into a bowl (most marinade should be stuck to chicken).","images":[],"step":5},{"title":"Preheat oven to 80°C/175°F and place rack on tray","description":"to keep chicken warm. (Note 7)","images":[],"step":6},{"title":"Cornflour coating","description":"Add cornflour to chicken and toss to coat - it will thicken the paste, this is what makes the craggy coating.","images":[],"step":7},{"title":"Heat oil 180°C/350°F","description":"Pour oil into a wide, heavy based pot to a depth of 6 cm / 2.5 \" (my 26cm/10.5\" cast iron pot = 1.75L/quarts oil, Note 8). Heat over medium high heat to 180°C/350°F - maintain temp as best you can (Note 9). This recipe will NOT work well with an air fryer – see Note 8.","images":[],"step":8},{"title":"Fry","description":"Carefully place 3 pieces of chicken in, do not touch for 2 min (to let crust adhere). Oil temperature should drop to 150°C/300°C - increase heat if needed.","duration":2,"images":[],"step":9},{"title":"Fry 8 minutes (75°C / 167°F)","description":"Fry for 8 minutes (wings for 5 minutes), or until deep golden brown and internal temperature at thickest part is 75°C / 167°F.","duration":8,"images":[],"step":10},{"title":"Keep warm","description":"Place cooked chicken onto rack and keep warm in oven. Cook remaining chicken.","images":[],"step":11},{"description":"Serve immediately, sprinkled with coriander and garlic-chilli garnish, if using. See in post for side dish suggestions!","images":[],"step":12},{"description":"Heat 3 tbsp oil in a small skillet over medium heat. Add garlic and chilli, cook until garlic is starting to go light golden. Then add green onion and cook until garlic is golden. Drain on paper towels, sprinkle with salt. Cool then sprinkle on chicken.","images":[],"step":13}]', '[]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Asian","Malaysian","South East Asian"],"categories":["asian-recipes","asian-takeout","chicken","chicken-recipes","deep-fried-recipes","iconic-dishes","mains"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_720d4ba41b50', 'en', 'US', 'Sticky Honey Soy Chicken - baked', 'Recipe video above. This is still the best, EASIEST sticky honey soy chicken recipe I have come across. And I''ve tried many over the years! Marginally adapted from this recipe by Sprinkles and Sprouts. The sauce is very thin when you put it together and gets even thinner while baking, but miraculously, it suddenly thickens into an incredible glaze to squidge the chicken in. It''s salty and sweet with a lovely hit of sesame.Please do not double the recipe or sauce, this will prevent the sauce from reducing down to the sticky glaze you see pictured.', 'https://www.recipetineats.com/tachyon/2016/02/Honey-Soy-Baked-Chicken_60.jpg', 5, 50, 55, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_honey", "quantity": {"value": 0.09, "unit": "jar of 500g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.01, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1.2kg / 2.4lb bone-in, skin-on chicken thighs OR drumsticks (5 - 6 pieces) (Note 1)","1 red onion (, peeled, cut into wedges)"]},{"ingredients":["3 cloves garlic (, minced)","3 tbsp honey","3 tbsp soy sauce (Note 2)","1 tbsp apple cider vinegar (or ordinary white vinegar)","1 tsp sesame oil","1/2 tsp black pepper"],"purpose":"Glaze"},{"ingredients":["Sesame seeds","Fresh coriander/cilantro leaves (or other green things like green onion, parsley, chives)"],"purpose":"Garnish (optional)"}]', '[{"description":"Preheat oven to 200°C/390°F (180°C fan).","images":[],"step":1},{"title":"Line pan","description":"Line a baking dish with foil then baking paper. The baking tray should fit the chicken comfortably, not too spaced apart (glaze will dry out), not too snug (glaze won''t thicken enough). (Note 3)","images":[],"step":2},{"title":"Glaze","description":"Mix the Glaze ingredients together.","images":[],"step":3},{"title":"Pour glaze over chicken","description":"Place onion and chicken in the baking dish skin side down, then pour the Glaze over.","images":[],"step":4},{"title":"Bake 50","description":"60 minutes: Bake for 25 minutes, then turn and bake for a further 25 to 35 minutes, until the chicken is browned and the glaze is sticky. If the glaze is not syrupy, remove the chicken to a plate and put the pan back in for a few minutes (it will reduce quickly).","duration":25,"images":[],"step":5},{"title":"Squidge/coat chicken","description":"Turn chicken and squidge in the glaze, then also spoon it over.","images":[],"step":6},{"description":"Serve! Serve with rice and steamed greens, sprinkled with sesame seeds and fresh cilantro/coriander leaves.","images":[],"step":7}]', '["gluten","sesame","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian influence"],"categories":["asian-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f505a0450ac5', 'en', 'US', 'Beef Satay with Thai Peanut Sauce', 'Recipe video above. Meat on sticks is always a good thing, and Thai Beef Satay is one of the best! In this beef version of Thai Chicken Satay, a secret tenderising satay marinade makes economical steak astonishingly succulent. So good, you can eat it plain – but no one in their right mind would skip the Thai Peanut Sauce!Note: Baking soda tenderised beef needs to be thoroughly cooked to be tender. The beef is still a bit chewy if it''s medium or less (because we''re using economical beef).Top tip: Excellent to grill on the BBQ, or even better, over charcoal for a truly authentic Thai experience.Use leftover sauce for Thai Chicken Satay, Gado Gado (Indonesian Salad with Peanut Sauce) or just douse a bowl of plain rice. You can''t go wrong!', 'https://www.recipetineats.com/tachyon/2021/07/Thai-Beef-Satay-with-Peanut-Sauce.jpg', 15, 15, 1470, 12, '[{"id": "ing_skewers", "quantity": {"value": 13.0, "unit": "pack of 50"}}, {"id": "ing_beef_steak", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_coconut_mik", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.3, "unit": "jar of 50g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_red_curry_paste", "quantity": {"value": 0.05, "unit": "bottle"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.013, "unit": "tub of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.417, "unit": "can of 400ml"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.133, "unit": "jar of 375g"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_vinegar", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_peanuts", "quantity": {"value": 0.075, "unit": "jar"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["13-16 bamboo skewers (, 16cm / 6.5\" long (Note 1))"]},{"ingredients":["600g / 1.2lb beef rump steak (top sirloin in the US) (, 2.5 cm/1\" pieces (Note 2))","1/4 cup coconut mik (, full fat (I use Ayam, Note 3))","1 tbsp curry powder (Note 4)","1 tsp white sugar","2 tsp red curry paste (Note 5)","1/2 tsp baking soda / bi-carb (tenderiser, Note 6)","1 tsp salt"],"purpose":"Marinade:"},{"ingredients":["1 tbsp red curry paste (Note 5)","2/3 cup coconut milk (, full fat (I use Ayam, Note 3))","1/3 cup natural peanut butter (, smooth (Note 7))","1 1/2 tbsp white sugar","1 tsp dark soy sauce (Note 8)","1/2 tsp salt","1 tbsp cider vinegar (Note 9)","1/3 cup water"],"purpose":"Thai Peanut Sauce:"},{"ingredients":["1 1/2 tbsp vegetable oil (, for cooking)","2 tbsp peanuts (, finely chopped)","Lime wedges (optional)","Coriander / cilantro leaves and sliced red chilli (optional)"],"purpose":"Cooking & Serving:"}]', '[{"description":"If cooking on a BBQ or over charcoal, soak skewers for 2 hours in water so they don''t burn.","images":[],"step":1},{"description":"Thai Beef Satay Skewers:","images":[],"step":2},{"description":"Mix together the beef and Marinade in a bowl. Cover with cling wrap and marinate overnight (do not reduce marinating time else the beef may not tenderise enough).","images":[],"step":3},{"title":"Thread onto skewers","description":"I do 4 pieces each.","images":[],"step":4},{"description":"Heat 1.5 tbsp oil in a large non stick pan over medium high heat.","images":[],"step":5},{"title":"Cook 10 minutes (yes, well done!)","description":"Cook skewers in batches for 2 to 2 1/2 minutes on all 4 sides until deep golden (total of 8 to 10 minutes) and fully cooked through. (Note: baking soda tenderised beef needs to be thoroughly cooked to be tender. The beef is still a bit chewy if it''s medium or less.)","images":[],"step":6},{"title":"Rest","description":"Transfer skewers to plate and rest for 3 minutes before serving with Peanut Sauce.","duration":3,"images":[],"step":7},{"description":"Thai Peanut Sauce:","images":[],"step":8},{"description":"Place all Peanut Sauce ingredients in a small saucepan over medium low heat.","images":[],"step":9},{"description":"Stir to combine then simmer, stirring every now and then, for 5 minutes. Adjust consistency with water - it should be a pourable but thickish sauce.","duration":5,"images":[],"step":10},{"description":"Remove from stove, cover with lid and keep warm while cooking skewers.","images":[],"step":11},{"description":"Pour sauce into a bowl. Sprinkle with some peanuts - stir some through if you want.","images":[],"step":12},{"description":"Pile satay skewers onto a platter, sprinkle with remaining peanuts, coriander and chilli.","images":[],"step":13},{"description":"Serve with sauce on the side for dipping. Add a side of Jasmine Rice or Thai Fried Rice or Pineapple Fried Rice to complete the meal!","images":[],"step":14}]', '["gluten","peanuts","soy"]', '["keto_friendly","low_calorie"]', '{"mealType":["dinner","snack"],"cuisine":["Thai"],"categories":["asian-recipes","asian-takeout","beef","beef-recipes","cuisines","grilling-ideas-and-recipes","mains","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8d212b4e6ec6', 'en', 'US', 'Prawn Stir Fry (Shrimp)', 'Recipe video above. Dinner is sorted with these plump and juicy prawns in a classic ginger sesame Chinese stir fry sauce, with snow peas and broccolini. It’s a Chinese restaurant standard!As with all stir fries, feel free to switch the vegetables for anything you''ve got!TOP TIP: The best way to ensure you don''t overcook the prawns is to cook them first, remove, then add them back in at the end. Perfectly plump and juicy prawns, every single time!', 'https://www.recipetineats.com/tachyon/2021/06/Prawn-Stir-Fry-Shrimp_8.jpg', 10, 7, 17, 3, '[{"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.037, "unit": "pack of 400g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 2.5, "unit": "bottle"}}, {"id": "ing_shrimp", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_broccoli", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_snow_peas", "quantity": {"value": 120.0, "unit": "unit"}}]', '[{"ingredients":["1 1/2 tbsp light soy sauce (sub all purpose soy, Note 1)","1 tbsp Chinese cooking wine (sub Mirin or dry sherry, Note 2)","2 tsp oyster sauce (Note 3)","1/2 tsp sesame oil (, toasted (Note 4))","1 tbsp cornflour/cornstarch","1/8 tsp white pepper (sub black pepper)","3/4 cup water"],"purpose":"Prawn Stir Fry Sauce:"},{"ingredients":["2 tbsp oil (, peanut, canola or vegetable)","250g / 8 oz medium prawns (, raw, peeled and deveined (equiv. 500g/1lb whole prawns, Note 5))","1/2 onion (, sliced, brown or white)","2 tsp ginger (, finely julienned (~2cm / 0.7\" piece))","2 tsp garlic (, finely chopped (~ 2 cloves))","1 1/2 bunches broccolini (, trimmed, cut into 5cm / 2\" lengths, (~1 1/2 cups. Sub normal broccoli))","120g / 4 oz snow peas (, thin string removed from both sides)"],"purpose":"Stir Fry:"}]', '[{"title":"Steam broccolini","description":"Steam broccolini until crisp-tender, about 2 - 3 minutes (remember it will cook more in the stir fry). Set aside to drain and dry.","images":[],"step":1},{"title":"Stir Fry Sauce","description":"Put all Stir Fry Sauce ingredients except water into a bowl. Mix until cornflour is dissolved. Then stir in water.","images":[],"step":2},{"title":"Cook then remove prawns","description":"Heat oil in a wok or large skillet on medium to medium-high heat. Add prawns and spread them in a single layer. Cook for 1 1/2 minutes, then turn and cook the other side for 1 minute until cooked through. Try not to make the prawns too golden (they are only lightly browned in stir fries). Remove prawns to a bowl. Set aside.","duration":1,"images":[],"step":3},{"title":"Cook onion, garlic and ginger","description":"Add more oil if the pan seems a bit dry. Still on medium-high heat, add onion and cook for 1 minute. Then add ginger and garlic and cook for another 1 minute until onion is starting to soften but not colour.","duration":1,"images":[],"step":4},{"title":"Add snow peas, then broccolini","description":"Add snow peas and toss until coated with oil. Then add broccolini and toss through.","images":[],"step":5},{"title":"Add Sauce and thicken","description":"Give the Sauce a stir (to dissolve cornflour settled at bottom), then pour into skillet. Cook, stirring, until sauce thickens to syrup consistency (about 1 minute) and coats the ingredients nicely.","images":[],"step":6},{"title":"Add prawns back in","description":"Then add the prawns back in (including any juices in the bowl). Toss for another 30 seconds until prawns are warmed through.","images":[],"step":7},{"title":"Serve","description":"Serve with rice!","images":[],"step":8}]', '["gluten","peanuts","sesame","soy"]', '["high_protein","low_calorie","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","asian-takeout","chinese-recipes","dinner-tonight","prawns-shrimp","quick-and-easy","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cde66a3d365b', 'en', 'US', 'Golden Turmeric Fish (Indonesian baked fish recipe)', 'Recipe video above. This homestyle Indonesian baked fish recipe is made with a Turmeric Curry Paste slathered on to white fish fillets which are then baked, and served topped with an Indonesian-style tomato salsa called Sambal Tomat.The curry paste is a gorgeously vibrant yellow colour thanks to the turmeric, and packed with fragrant and fresh South-East Asian curry flavours (as opposed to big, in-your-face-spice like Indian curries!).Sambal Tomat comes in all forms, from complex versions with flavourings like shrimp paste, to simpler and fresh ones like this one. We only need a simple one, the curry paste has plenty of flavour!', 'https://www.recipetineats.com/tachyon/2021/05/Golden-Turmeric-Fish-Indonesian_7.jpg', 15, 15, 30, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_turmeric", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_macadamia_nuts", "quantity": {"value": 22.5, "unit": "jar"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_lime", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_lemongrass", "quantity": {"value": 2.5, "unit": "bunch"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_chilli", "quantity": {"value": 10.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["4 x 180g / 6oz white fish fillets (, medium to thick, skinless (Note 1))","1/2 tsp salt","1 tbsp lime juice"],"purpose":"Quick lime marinade:"},{"ingredients":["1 small eschalot (~1/4 cup roughly chopped) (Note 2)","1 garlic clove (, finely grated*)","2 tsp fresh turmeric (, finely grated* or substitute powdered (Note 3))","1 tsp ginger (, peeled and finely grated*)","1 1/2 tbsp macadamia nuts (Note 4)","1/4 tsp salt","1/8 tsp black pepper","1 kaffir lime leaf (, torn by hand (Note 5))","2.5cm / 1\" piece of fresh lemongrass, white part only, ( cut into 1cm / 0.2\" pieces (Note 6))","1 tbsp oil","2 tbsp water"],"purpose":"Turmeric Curry Paste:"},{"ingredients":["2 tsp oil","250g / 8oz cherry tomatoes (, quartered)","1 large red chilli (cayenne pepper) (, deseeded and finely diced (adjust to taste, Note 7))","2 tsp coriander/cilantro leaves (, finely chopped (plus more for garnish))","1/4 tsp salt"],"purpose":"Sambal Tomat Topping:"}]', '[{"title":"Prep","description":"Preheat oven to 200°C / 390°F (180°C fan). Line a tray with baking / parchment paper.","images":[],"step":1},{"title":"Quick fish marinade","description":"Sprinkle fish with salt and drizzle with lime juice. Leave in fridge while making paste - just 10 minutes is fine.","images":[],"step":2},{"title":"Turmeric Curry Paste","description":"Place ingredients in a container that fits a stick blender. Then blend with stick until smooth, using extra water if needed until it is a paste consistency (ie. can be slathered on fish).","images":[],"step":3},{"title":"Slather and bake","description":"Smear paste onto surface of fish (not underside). Bake for 15 minutes until the internal temperature is 55°C/131°F (medium, just cooked but not raw at all, very juicy).","duration":15,"images":[],"step":4},{"title":"Rest","description":"Remove from oven and remove fish from tray (otherwise it keeps cooking). Rest 3 minutes, serve over rice with Sambal Tomat (below) and extra fresh coriander.","images":[],"step":5},{"title":"Sambal Tomat Topping","description":"Heat oil in a non-stick pan over medium heat. Add tomato, chilli and salt. Sauté 2 minutes until tomato is slightly softened. Stir through coriander, serve over fish.","images":[],"step":6}]', '["fish","nuts"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian","Indonesian"],"categories":["asian-recipes","curry-recipes","dietary","fish-recipes","gluten-free-recipes","low-calorie-recipes","mains","modern-asian","other","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_61ac668a588e', 'en', 'US', 'Galbi - Korean BBQ Marinated Beef Short Ribs', 'Recipe video above. This is an excellent Korean barbecue marinade that will work with pork, chicken or even lamb. And while it''s delicious cooked on the stove, a BBQ will better replicate the true Korean barbecue experience!Do not worry about overcooking the thin slices of beef. The marinade is magical, it keeps the thin slices of beef incredibly tender even if you cook it for over 10 minutes which would ordinarily turn the beef into inedible dry cardboard!', 'https://www.recipetineats.com/tachyon/2021/04/Korean-Beef-Short-Ribs-Galbi_6-1.jpg', 10, 10, 20, 4, '[{"id": "ing_beef_steak", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.333, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_mirin", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_onion", "quantity": {"value": 37.5, "unit": "pack of 1kg"}}, {"id": "ing_pears", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.03, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_rice", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_cucumber", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["1 kg/ 2lb beef short ribs, butterflied Korean style (pictured) ( or thinly sliced through the bone (Note 1 for subs))","1 tbsp vegetable oil (, for cooking)"]},{"ingredients":["1/3 cup soy sauce (all purpose or light soy, not dark or sweet)","1/4 cup brown sugar","2 tbsp mirin (Note 2)","1/4 cup onion (, finely grated (including juice))","1/4 cup nashi pear (, finely grated including juice (sub normal pear or any red apple, Note 3))","2 tsp garlic (, finely grated)","2 tsp ginger (, finely grated)","2 tbsp water","1 tbsp toasted sesame oil (Note 4)","1 tsp black pepper"],"purpose":"Korean Barbecue Marinade:"},{"ingredients":["Green onion, sesame seeds, coriander/cilantro leaves (, for garnish)","Kimchi Fried Rice","Smashed Cucumbers"],"purpose":"Serving (optional):"}]', '[{"title":"Make Marinade","description":"Whisk Marinade ingredients in a bowl.","images":[],"step":1},{"title":"Marinade 24 hours","description":"Place beef in a ziplock bag, glass or ceramic container. Pour over Marinade, mix well to coat. Cover and marinade for 24 hours.","images":[],"step":2},{"description":"Cooking:","images":[],"step":3},{"description":"Remove beef from Marinade, discard Marinade.","images":[],"step":4},{"title":"BBQ","description":"Heat on high until smoking hot, then brush grills with vegetable oil. Lay beef on BBQ and cook for 2 minutes on one side until caramelised. Turn and cook the other side until caramelised. Remove, loosely cover with foil, cook remaining beef.","duration":2,"images":[],"step":5},{"title":"Stove","description":"Cut beef strips into pieces that will fit your skillet. Heat skillet with oil over high heat. Add beef and cook for 2 minutes until caramelised, then turn and cook the other side for 2 minutes.","duration":2,"images":[],"step":6},{"description":"Garnish beef with sesame seeds and green onions if desired. You don''t need a sauce for this one - it is literally dripping with flavour! Pictured in post with Kimchi Fried Rice and Ginger Smashed Cucumbers.","images":[],"step":7}]', '["gluten","sesame","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian","BBQ","Korean"],"categories":["asian-recipes","asian-takeout","beef","beef-recipes","grilling-ideas-and-recipes","iconic-dishes","korean-recipes","mains","modern-asian"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d4b904f2b27d', 'en', 'US', 'Thai Cashew Chicken Stir Fry', 'Recipe video above. Crunchy and creamy cashews are the star in this popular Thai chicken stir fry! Tossed with a bold and savoury Thai stir fry sauce, make this as spicy as you want – or not at all.Thai Cashew Chicken is a dry-style stir fry so there''s not a ton of sauce like with Chinese Cashew Chicken. But the flavour in this one is much more intense so you don''t need nor do you want more sauce, it will be too salty!SPICINESS: Nice buzz to it from 1/2 a fresh chilli, not blow-your-head-off spicy.', 'https://www.recipetineats.com/tachyon/2021/04/Thai-Cashew-Chicken_9.jpg', 10, 8, 18, 2, '[{"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_cashews", "quantity": {"value": 75.0, "unit": "jar"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.04, "unit": "bunch"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.5, "unit": "jar of 40g"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2 tbsp peanut oil (or canola or vegetable oil)","1/2 cup raw cashews (, unsalted (Note 1 for roasted))","1 garlic clove (, finely minced)","1/2 onion ((brown, yellow, or white), cut into thin wedges)","200g/7oz chicken thighs (, skinless and boneless, sliced into 1cm / 1/3\" thin strips (Note 2))","2 green onions (, cut into 2.5cm / 1” lengths, white part separated from green part)","1/2 red cayenne pepper (, deseeded and finely sliced on the diagonal (omit or reduce if preferred) (Note 3))"]},{"ingredients":["1 tbsp oyster sauce (Note 4)","1 tsp dark soy sauce (Note 5)","2 tsp fish sauce (Note 6)","1 tsp white sugar","3 tbsp water"],"purpose":"Sauce:"},{"ingredients":["Red chilli (, finely sliced (optional garnish))","Jasmine rice (, for serving (or other rice of choice))"],"purpose":"Serving:"}]', '[{"title":"Sauce","description":"Mix all the Sauce ingredients in a small bowl.","images":[],"step":1},{"title":"Cook cashews","description":"Heat oil over medium heat in a wok or large skillet. Add cashews and cook for 5 minutes until they become a dark golden colour and crunchy (yep, you might have to eat one to check!). Remove from skillet with a slotted spoon.","duration":5,"images":[],"step":2},{"title":"Garlic & onion","description":"Turn heat up to high. Add garlic and onion. Cook for 30 seconds.","duration":0.5,"images":[],"step":3},{"title":"Chicken","description":"Add chicken. Cook for 1 minute until the outside changes from pink to white.","duration":1,"images":[],"step":4},{"title":"White part of green onion & chilli","description":"Add white part of green onions and chilli. Cook for 1 minute until chicken is just cooked through.","duration":1,"images":[],"step":5},{"title":"Add Sauce","description":"Cook for 1 minute until it reduces down to a syrup, coating the chicken nicely.","duration":1,"images":[],"step":6},{"title":"Green onion & cashews","description":"Add green part of green onions and cashews. Toss for 30 seconds.","duration":0.5,"images":[],"step":7},{"title":"Serve","description":"Transfer to serving dish. Serve with jasmine rice, or other rice of choice, garnished with extra red chilli (if you can handle the heat!).","images":[],"step":8}]', '["fish","gluten","peanuts","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["asian-recipes","asian-takeout","chicken","chicken-breast-recipes","chicken-recipes","cuisines","dinner-tonight","mains","quick-and-easy","stir-fries","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_abf215527aa2', 'en', 'US', 'Kimchi Fried Rice', 'Recipe video above. Kimchi Fried Rice is a staple in every Korean household. It''s a typical way to use up leftover rice and kimchi, while still delivering big flavours that belie its humble nature. Along with kimchi, gochujang (Korean chilli paste) is the other hero ingredient that brings flavour, colour and heat to the party!Don''t panic! It''s not nearly as spicy as it looks and it''s easy to adjust the heat in the recipe.Serve alongside all things Korean, or Asian really. Or as a main with a fried egg!', 'https://www.recipetineats.com/tachyon/2021/03/Kimchi-Fried-Rice-Skillet.jpg', 10, 6, 16, 4, '[{"id": "ing_sesame_seeds", "quantity": {"value": 0.02, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_mushroom", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_gochujang", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_kimchi", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_kimchi_juice", "quantity": {"value": 0.25, "unit": "unit"}}, {"id": "ing_s", "quantity": {"value": 1.2, "unit": "pack"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_crispy_seaweed_strips", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2 tsp sesame oil (, toasted, separated (1 tsp + 1 tsp))","2 garlic cloves (, finely chopped)","200g/7oz enoki mushrooms (Note 1)","1 tbsp oil (, vegetable, peanut or canola)","1 tbsp gochujang (Korean chilli paste, Note 2)","1 cup (packed) kimchi (Note 3)","1/4 cup kimchi juice (, from the kimchi above (Note 3))","3 cups cooked (, day old white rice (Note 4))"]},{"ingredients":["Fried egg (, runny yolk, sunny-side up)","Black sesame seeds","Green onions (, finely sliced)","Crispy seaweed strips (Note 5)"],"purpose":"Garnishes:"}]', '[{"title":"Strain kimchi juice","description":"Place kimchi in a sieve set over a bowl. Press firmly to extract as much juice as you can. We need juice for the sauce, and to reduce the wetness of the kimchi so it doesn''t make the rice soggy.","images":[],"step":1},{"title":"Measure kimchi juice","description":"Measure out 3 tablespoons of the kimchi juice and set aside. (Note 3 if you''re short).","images":[],"step":2},{"title":"Cook enoki mushrooms","description":"Heat 1 tsp sesame oil in a large non-stick pan over medium-high heat. Add enoki mushrooms, about 1/2 tsp garlic, plus a pinch of salt and pepper. Cook for 1 1/2 minutes until just-wilted, then remove to a plate.","images":[],"step":3},{"title":"Garlic and gochujang","description":"Return pan to the stove. Add oil. Add garlic and cook for 20 seconds until it''s lightly golden. Add gochujang and cook for 30 seconds until it dries out a bit – just move it around in a lump, breaking it up a bit as you can.","duration":0.3333333333333333,"images":[],"step":4},{"title":"Cook kimchi","description":"Add kimchi and cook for 1 minute, just to heat it through (kimchi doesn''t need to be cooked) and drive off any excess moisture.","duration":1,"images":[],"step":5},{"title":"Add rice and kimchi juice","description":"Add rice and kimchi juice, toss well for 1 1/2 minutes until the rice is fully stained red. Toss well to ensure the gochujang mixed with the kimchi disperses throughout the rice.","images":[],"step":6},{"title":"Enoki mushrooms and 1 tsp sesame oil","description":"Add the enoki mushrooms and remaining 1 teaspoon of sesame oil. Toss through rice.","images":[],"step":7},{"description":"Serve, topped with garnishes of choice!","images":[],"step":8}]', '["egg","peanuts","sesame"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Asian","Korean"],"categories":["asian-recipes","asian-takeout","fried-rice","korean-recipes","modern-asian","rice-recipes","rice-side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b830007f7c89', 'en', 'US', 'Asian Glazed Baked Barramundi (or other fish)', 'Recipe video above. Banish boring baked fish with this sweet n'' savoury, gently spiced Asian-style barbecue glaze. A quick finish under the broiler / grill caramelises the glaze for maximum flavour! For the most juicy and perfectly cooked fish, take the fish out when the internal temperature is 55C/135F. Serve with plain or flavoured rice, and some wholesome veggies to complete.', 'https://www.recipetineats.com/tachyon/2021/02/Baked-Barramundi-with-Asian-Glaze_5.jpg', 10, 25, 35, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.05, "unit": "pack of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.3, "unit": "bottle of 250ml"}}, {"id": "ing_honey", "quantity": {"value": 0.12, "unit": "jar of 500g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.03, "unit": "pack of 100g"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_mirin", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_sambal_oelek", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_chinese_five_spice", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}]', '[{"ingredients":["4 x 180g / 6oz barramundi fillets (, skinless, boneless; or other ~2.5cm / 1\" thick firm white fish fillets (Note 1))"]},{"ingredients":["4 tsp cornflour / cornstarch","2 tbsp water","5 tbsp soy sauce (, all-purpose or light soy sauce (Note 2))","4 tbsp honey (else maple syrup or 5 tbsp brown sugar)","1 tbsp sesame oil","1 tbsp Chinese black vinegar or rice vinegar (Note 3)","1 tbsp mirin (Note 4)","1 tsp sambal oelek (, or other Asian chilli paste / sauce (Note 5))","1/2 tsp Chinese Five Spice (Note 6)","1 clove garlic (, finely minced)","1 tsp ginger (, finely grated)","1/4 tsp Sichuan pepper (, or white pepper (Note 7))"],"purpose":"Glaze:"},{"ingredients":["Sesame seeds","Green onions (Note 8)","Large red chilli, finely sliced"],"purpose":"Garnishes"}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan). Line a tray with parchment/baking paper. Place shelf in middle of oven.","images":[],"step":1},{"title":"Cornflour slurry","description":"Mix water and cornflour in a small bowl.","images":[],"step":2},{"title":"Make glaze","description":"Place remaining glaze ingredients in a small saucepan over medium-low heat. Simmer for 2 minutes. Add cornflour slurry then stir well. Cook it for a further 2 minutes until it thickens into a thick paste – thick enough so it stays on the fish when brushed on. See photo in post or video. If it is just a thick syrup, it will slide off the fish.","duration":2,"images":[],"step":3},{"title":"Brush glaze on Fish","description":"Place fish fillets on tray. Dab/brush paste on on the top and sides.","images":[],"step":4},{"title":"Bake then broil/grill","description":"Bake fish for 15 minutes. Then flick to broiler/grill on high, and cook for 3 minutes to caramelise the surface. Target an internal temperature of 55°C/131°F for medium, which is just cooked but not raw at all. Fish temperature will continue to rise to 58°C/136.5°F during resting.","duration":15,"images":[],"step":5},{"title":"Garnish","description":"Remove from oven, transfer to serving plates and rest for 5 minutes. Garnish with green onion, chillies and sesame seeds, as desired. Pictured in post with a side of Coconut Rice and cucumber with Asian Sesame Dressing.","duration":5,"images":[],"step":6}]', '["fish","gluten","sesame","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","dietary","dinner-tonight","fish-recipes","low-calorie-recipes","mains","modern-asian","other","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c5073c149d32', 'en', 'US', 'Char Siu Pork - Chinese BBQ Pork', 'Recipe video above. Your favourite Chinese barbecue pork made at home! Slow cooked so it''s juicy on the inside with the most incredible sticky glaze, this is finger licking'' good! Chicken version here.', 'https://www.recipetineats.com/tachyon/2018/05/Char-Siu-Chinese-Barbecue-Pork_9b.jpg', 5, 90, 2975, 6, '[{"id": "ing_brown_sugar", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_honey", "quantity": {"value": 0.125, "unit": "jar of 500g"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_five_spice", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_red_food_colouring", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_pork_shoulder", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_honey", "quantity": {"value": 0.125, "unit": "jar of 500g"}}]', '[{"ingredients":["1 1/2 tbsp brown sugar (white also ok)","1/4 cup honey","1/4 cup hoisin sauce","2 tbsp light soy sauce (, or all purpose soy (Note 1))","1 tbsp soy sauce (, just all purpose (or more light soy) (Note 1))","1 tsp Chinese five spice powder (Note 2)","1 tbsp oil (vegetable or canola) (Note 3)","2 tsp red food colouring (, optional (Note 4))"],"purpose":"Marinade"},{"ingredients":["1.2 - 1.5kg / 2.4 - 3lb pork scotch fillet (aka collar neck, pork neck) OR pork shoulder (Note 5)","2 tbsp Extra Honey"],"purpose":"Cooking:"}]', '[{"description":"Cut pork in half to make two long strips. (Note 5)","images":[],"step":1},{"description":"Mix Marinade ingredients in a bowl.","images":[],"step":2},{"description":"Place the pork and Marinade in a stain proof container or ziplock bag. Marinate 24 to 48 hours in the fridge (3 hours is the bare minimum).","images":[],"step":3},{"description":"Preheat oven to 160C/320F.","images":[],"step":4},{"description":"Line a tray with foil and place a rack on top (recommended but not critical).","images":[],"step":5},{"description":"Remove pork from the marinade, save Marinade. Place pork on rack.","images":[],"step":6},{"description":"Roast for 30 minutes.","duration":30,"images":[],"step":7},{"description":"Meanwhile, pour reserved marinade in a saucepan. Mix Extra Honey into marinade. Bring to simmer over medium high and cook for 2 minutes until syrupy. Remove from heat.","duration":2,"images":[],"step":8},{"description":"Remove pork from oven. Dab marinade all over, then turn. Baste then roast for a further 30 minutes.","images":[],"step":9},{"description":"Remove pork from oven. Brush with marinade again, then turn, brush with marinade and roast for a further 20 minutes. If charring too quickly, cover with foil.","images":[],"step":10},{"description":"Baste again on surface then bake for a further 10 minutes until caramelised and sticky. Meat should be tender but not falling apart, like with pulled pork. Allow to rest for 10 minutes before slicing.","duration":10,"images":[],"step":11},{"description":"Serve with rice and steamed Chinese greens. See notes for more uses!","images":[],"step":12}]', '["fish","gluten","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["main_course"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chinese-recipes","dietary","gluten-free-recipes","iconic-dishes","most-popular","pork-recipes","quick-and-easy","yum-cha-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ad31a0106d3d', 'en', 'US', 'General Tso''s Chicken', 'Recipe video above. That perfect combination of sweet, savoury, spicy and tangy with crispy Chinese chicken bites. This is a Chinese takeout favourite that pushes all the right buttons!', 'https://www.recipetineats.com/tachyon/2020/10/General-Tsao-Chicken_1.jpg', 15, 10, 25, 4, '[{"id": "ing_soy_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_chilli", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.01, "unit": "pack of 100g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.037, "unit": "pack of 400g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_oil", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_oil", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_chilli", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["3 tbsp soy sauce - light or all-purpose (NOT dark soy, Note 1)","1 tbsp hoisin sauce","1 tbsp rice vinegar (sub white wine vinegar)","2 tsp chilli paste (, any (Sambal Oelak is great))","1 tsp sesame oil (toasted preferably (Note 6))","3 tbsp brown sugar","1 tbsp cornflour/cornstarch","3/4 cup chicken stock/broth (, low sodium)"],"purpose":"Sauce/Chicken Marinade:"},{"ingredients":["600g/ 1.4 lb chicken thighs (, boneless skinless, cut into 2.5cm / 1\" pieces (breast / tenderloin - Note 2))","1 tsp ginger (, finely grated)","1 tsp garlic (,finely grated)","1 cup cornflour/cornstarch (Note 5)","1 - 4 cups oil, for frying (peanut, vegetable or canola; Note 4)"],"purpose":"Chicken:"},{"ingredients":["2 tbsp oil (peanut, vegetable or canola)","2 tsp ginger (, finely chopped (Note 3))","2 cloves garlic (, finely chopped (Note 3))","1/2 teaspoon red chilli flakes (red pepper flakes)"],"purpose":"Stir Fry Sauce:"},{"ingredients":["Finely sliced green onion","Sesame seeds"],"purpose":"Garnishes (at least 1 recommended):"}]', '[{"title":"Sauce-Marinade","description":"Mix the soy, hoisin, vinegar, chilli and sesame oil.","images":[],"step":1},{"title":"Marinate Chicken","description":"Take out 2 tablespoons of Sauce-Marinade and mix with chicken. Add ginger and garlic to chicken, mix, then marinate 30 minutes.","images":[],"step":2},{"title":"Dust chicken","description":"Add cornflour into chicken and toss to coat, ensuring pieces are separated so they get fully coated.","images":[],"step":3},{"title":"Shake off excess","description":"Tip into a colander and shake to remove excess cornflour (or grab handfuls, shake so cornflour falls through your fingers).","images":[],"step":4},{"title":"Finish Sauce","description":"To the remaining Sauce-Marinade (that you made in Step 1), add sugar and cornflour. Mix, then add chicken stock and mix.","images":[],"step":5},{"title":"Heat oil","description":"Heat 2 cm / 4/5\" oil in a deep skillet (or large pot - whatever you’re comfortable with) to 200°C/390°F. To use less, see Note 4.","images":[],"step":6},{"title":"Fry","description":"Cook chicken 3 minutes, turning halfway, until golden and crispy. Drain on paper towel lined plate.","images":[],"step":7},{"title":"New / clean skillet","description":"Discard oil, wipe skillet and return to heat. Or use another large skillet.","images":[],"step":8},{"title":"Stir Fry Sauce","description":"Heat oil in a large skillet over medium heat. Add garlic, ginger, chilli flakes, saute 30 seconds until garlic is light golden. Add Sauce, bring to simmer and stir occasionally until it thickens enough that you can draw a path across pan base.","images":[],"step":9},{"title":"Toss! Add chicken, toss to coat quickly","description":"the quicker you are, the crispier the chicken stays! Transfer to serving plate, garnish and serve immediately with your rice of choice.","images":[],"step":10}]', '["gluten","peanuts","sesame","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["American Chinese","Chinese"],"categories":["asian-recipes","asian-takeout","chicken-recipes","chinese-recipes","modern-asian"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c2ace503e5a6', 'en', 'US', 'Chinese Rice Soup', 'Recipe video above. This is a really quick and easy soup recipe that''s filling and nourishing. The Asian infused soup broth adapted from my Chinese Noodle Soup has a depth of flavour that belies the few ingredients called for. As for add ins - in the spirit of simplicity and speed, I''ve just used fish and choy sum. But you''re only limited by your imagination!', 'https://www.recipetineats.com/tachyon/2020/10/Chinese-Rice-Soup_0.jpg', 5, 10, 15, 3, '[{"id": "ing_chicken_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.045, "unit": "bottle of 500ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.25, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_white_rice", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_stems_choy_sum", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1 litre / 32 oz chicken stock/broth, low sodium (Note 1)","1 cup water","2 garlic cloves (, smashed (Note 2))","1.5 cm / 1/2\" ginger piece, (cut into 3 slices)","1 1/2 tbsp light soy sauce (, or normal all purpose soy sauce (Note 3))","1 1/2 tbsp Chinese cooking wine (, key ingredient (Note 4 subs))","1/4 - 1/2 tsp sesame oil (, toasted (optional) (Note 5))","1/4 tsp white pepper (sub black, can omit)"],"purpose":"Broth"},{"ingredients":["3/4 cup uncooked white rice (- long grain, medium grain, short grain, jasmine (Note 6))","3 stems choy sum (, cut into 2cm / 1\" lengths, stems separated from leaves (Note 8))","250g / 8 oz white fish fillets (, cut into 2.5cm / 1\" cubes (Note 8))","1 green onion (, finely sliced)"],"purpose":"Add Ins"},{"ingredients":["Crispy fried shallots (Note 9)","Crunchy fried noodles (, pictured in post (Note 9))","Chilli oil or paste"],"purpose":"Toppings (1 minimum, all best!)"}]', '[{"title":"Combine broth ingredients","description":"Place chicken stock, soy sauce, Chinesse cooking wine, garlic and ginger in a small pot over high heat.","images":[],"step":1},{"title":"Simmer to infuse","description":"Place lid on, bring to simmer then reduce to medium and simmer for 5 minutes to allow the flavours to infuse.","duration":5,"images":[],"step":2},{"title":"Add rice","description":"Add rice and cook uncovered for 10 minutes - broth surface should be bubbling very gently.","duration":10,"images":[],"step":3},{"title":"Add fish & stems","description":"Add fish and stems of choy sum, cook for 2 minutes.","duration":2,"images":[],"step":4},{"description":"Pick garlic and ginger out of soup.","images":[],"step":5},{"description":"Stir through choy sum leaves (they will wilt almost instantly), sesame oil and pepper. Serve immediately.","images":[],"step":6}]', '["fish","gluten","sesame","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","asian-soups","chinese-recipes","emergency-recipes","fish-recipes","quick-and-easy","rice-recipes","seafood-recipes","soup-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9d58951cd4c5', 'en', 'US', 'Satay Chicken Curry (Malaysian)', 'Recipe video above. Forget skewers - THIS is how you get a satay fix! This Malaysian Chicken Satay Curry features chicken marinated in a homemade satay seasoning, simmered in a heady peanut satay sauce that''s coconuty and heavily seasoned. Truly restaurant quality. Yet -simple. No hunting down unsual ingredients!Spice level: Pretty warm buzz but not that spicy. If concerned, read note 1 & 3 for how to play it safe with the chilli!Adapted from a Satay recipe by a Malaysian chef and the Satay Sauce from Chinta Ria, a popular Sydney Asian restaurant - refer Note 10.', 'https://www.recipetineats.com/tachyon/2016/05/Satay-Chicken-Curry_9.jpg', 20, 25, 45, 5, '[{"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_turmeric", "quantity": {"value": 0.005, "unit": "jar"}}, {"id": "ing_paprika", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_chilli", "quantity": {"value": 3.0, "unit": "pack of 100g"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.35, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_chilli", "quantity": {"value": 3.0, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_chicken", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_peanuts_roasted", "quantity": {"value": 112.5, "unit": "jar"}}, {"id": "ing_kecap_mani", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.08, "unit": "jar of 375g"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_lemongrass", "quantity": {"value": 20.0, "unit": "bunch"}}, {"id": "ing_peanuts", "quantity": {"value": 0.281, "unit": "jar"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 3.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1 1/2 tsp coriander","1 1/2 tsp cumin powder","1 1/2 tsp tumeric","1 1/2 tsp paprika (sweet or normal, not smoked or spicy)","1 1/4 tsp chilli powder (, adjust to taste (not US \"Chili Powder\", Note 1))","3 1/2 tsp curry powder (, not HOT (any, Malaysian, generic, Clives of India, Keens))","1 1/4 tsp salt (, cooking / kosher (or 1 tsp table salt))","2 tsp white sugar"],"purpose":"Satay Seasoning"},{"ingredients":["750g / 1.5 lb chicken thigh fillets (, cut into bite size pieces (Note 2))","1/2 onion ((brown, white or yellow), grated)"],"purpose":"Chicken"},{"ingredients":["2 tbsp oil (, separated)","3 - 6 birds eye chillies or other small hot red chillies (, finely chopped (Note 3))","1/4 cup onion (brown, white or yellow), finely diced (~ 1/4 onion)","4 garlic cloves (, minced)","1 cup chicken broth / stock","3/4 cup peanuts, roasted unsalted, (, chopped, separated)","2 tsp kecap manis (Note 4)","3 tsp dark soy sauce (Note 5)","400g / 14oz coconut milk (preferably full fat but light will be ok)","2 tbsp peanut butter (, pure best but spread ok too, crunchy or smooth)","2 tbsp lime juice (, to taste)"],"purpose":"Satay Sauce"},{"ingredients":["3 makrut lime leaves (formerly kaffir lime leaves) (Note 6)","1 lemongrass stalk (, white part only, smashed to burst open (Note 7))"],"purpose":"Flavour Infusion – choose ONE:"},{"ingredients":["Peanuts (, chopped)","Cilantro / coriander leaves","Fresh chilli, finely chopped"],"purpose":"Garnish (choices)"}]', '[{"description":"Combine Satay Seasoning ingredients in a small bowl.","images":[],"step":1},{"description":"Marinate & Cook Chicken:","images":[],"step":2},{"title":"Marinate","description":"Combine chicken with 3 1/2 TABLESPOONS Satay Seasoning and onion in a bowl. Marinate for at least 3 hours, preferably overnight, minimum 20 minutes (Note 6)","images":[],"step":3},{"title":"Cook","description":"Heat 1 tbsp oil in a non stick skillet over high heat (Note 7). Cook chicken in 2 batches until browned all over but still raw inside. Transfer to bowl, cover and keep warm.","images":[],"step":4},{"title":"Saute aromatics","description":"Using the same skillet, turn heat down to medium and heat 1 tbsp oil. Add chill, onion and garlic cloves. Sauté until onion is translucent - around 2 minutes.","images":[],"step":5},{"title":"Satay Seasoning","description":"Add remaining Satay Seasoning and cook for 1 minute.","duration":1,"images":[],"step":6},{"title":"Blitz","description":"Transfer to a blender or small food processor (I use a Nutribullet). Add chicken stock and 1/2 cup of the peanuts (rest gets added later). Puree until pretty smooth - some peanut chunks can remain. Pour mixture back into the skillet.","images":[],"step":7},{"title":"Add remaining ingredients into sauce","description":"Add remaining 1/4 cup peanuts, kecap manis, dark soy sauce, coconut milk and peanut butter. Stir to combine.","images":[],"step":8},{"title":"Add lime leaf or lemongrass","description":"Crush makrut lime leaf in hand a bit (to break leaf to release the flavour). Add lime leaf OR lemongrass and chicken to sauce.","images":[],"step":9},{"title":"Simmer","description":"Bring to simmer, turn heat down to medium low and simmer for 15 minutes until thickened.","duration":15,"images":[],"step":10},{"title":"Serve","description":"Add lime juice to taste. Serve with rice (jasmine, white rice or brown rice). Garnish with peanuts, cilantro/coriander leaves and more chilli if desired. See Note 9 for suggested sides.","images":[],"step":11}]', '["gluten","peanuts","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","Malaysian"],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","curry-recipes","dietary","gluten-free-recipes","main-dishes","most-popular"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9064b7108256', 'en', 'US', 'Mongolian Lamb', 'Recipe video above. At “posher” establishments, Mongolian Lamb arrives at the table on a hot iron plate, sizzling and spitting for theatric effect. Sizzle aside, this homemade version is a near perfect replica. Even the velveted texture of the lamb!The sauce is sweet and savoury, with Chinese Five Spice and Hoisin the dominant flavours. It''s completely addictive!Also excellent made with beef - see Note 1.', 'https://www.recipetineats.com/tachyon/2020/08/Mongolian-lamb_9.jpg', 15, 10, 25, 4, '[{"id": "ing_lamb", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.013, "unit": "tub of 200g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.013, "unit": "pack of 400g"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_chilli", "quantity": {"value": 0.075, "unit": "pack of 100g"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_chinese_five_spice", "quantity": {"value": 1.25, "unit": "jar"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 4.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 0.08, "unit": "bunch"}}]', '[{"ingredients":["350g / 12 oz lamb meat (backstrap/fillet, mid loin chops, shoulder - or any cut in Note 1)","1/2 tsp baking soda (bicarb soda) (tenderiser, Note 2)","1 tsp cornflour / cornstarch","1 tbsp light soy sauce (or all purpose, Note 3)","1 tbsp Chinese cooking wine (Note 4 subs)"],"purpose":"Lamb and marinade:"},{"ingredients":["3 tsp cornflour / cornstarch","2 tsp dark soy sauce (Note 3)","1 tsp light soy sauce (or all purpose, Note 3)","1 1/2 tsp Sambal Oelak or other chilli paste (or omit for no spice)","3 tbsp hoisin sauce (I used Lee Kum Kee brand)","2 tbsp Chinese cooking wine (Note 4 subs)","1/4 tsp Chinese five spice powder (Note 5)","3/4 cup water","1 tsp sesame oil (, toasted (Note 6))"],"purpose":"Sauce:"},{"ingredients":["2 tbsp vegetable oil (or canola or peanut)","1 large onion (, cut into large 2.5cm / 1\" squares)","2 cloves garlic (, finely chopped)","4 green onions (, cut into 5cm/2\" lengths)"],"purpose":"Stir fry:"}]', '[{"description":"Tenderise Lamb:","images":[],"step":1},{"description":"Combine lamb and marinade ingredients, mix very well. Cover and refrigerate to marinate and tenderise the lamb.","images":[],"step":2},{"title":"Marinate 2 hours","description":"Backstrap, Midloin chops and other listed Tender Cuts in Note 1.","images":[],"step":3},{"title":"Marinate 24 hours","description":"lamb shoulder and other listed Economical Cuts in Note 1. (Bare minimum marinade times is 6 hrs).","images":[],"step":4},{"description":"Cooking:","images":[],"step":5},{"title":"Sauce","description":"Mix cornflour with the soy sauces, then mix in the remaining sauce ingredients. (Note 7)","images":[],"step":6},{"title":"Cook onion","description":"Heat oil over high heat in a wok or heavy based skillet. Add onions, and stir fry for 30 seconds until starting to colour. Add garlic and toss through quickly.","duration":0.5,"images":[],"step":7},{"title":"Cook Lamb","description":"Add lamb and cook for 3 minutes until most of it changes from red to brown, and some pieces start getting nice golden brown surfaces.","duration":3,"images":[],"step":8},{"title":"Add Sauce","description":"Add green onions, stir for 30 seconds (meat should all now be brown), then add Sauce. Stir and let simmer for 1 - 2 minutes until thickened.","duration":0.5,"images":[],"step":9},{"description":"Serve with rice!","images":[],"step":10}]', '["fish","gluten","peanuts","sesame","soy"]', '["high_protein","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chinese-recipes","lamb","lamb-recipes","mains"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_97919cb57f33', 'en', 'US', 'Built-to-last CRISPY Honey Chicken', 'Recipe video above. This recipe brings together a plethora of Asian cooking secrets for a crispy chicken that stays crispy for 4+ hrs even after tossing with sauce:1. Double coating - dredge in cornflour/cornstarch followed by batter2. Cold batter made with soda water = crispier chicken that''s puffy and light, not dense and greasy3. Cornflour/cornstarch + flour batter - cornflour for ultra crispiness, flour for golden colour + baking powder lift4. Double fry for extra long lasting, thicker crispiness AND less greasy (Asian secret!)5. No-Soggy Sauce - glucose or corn syrup to make it "candy like" to stick on chicken crust rather than soaking in, plus NO WATER in the sauce.See Notes for make ahead (99% like freshly made).', 'https://www.recipetineats.com/tachyon/2020/08/Honey-Chicken_0.jpg', 20, 30, 50, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.02, "unit": "bottle of 500ml"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.025, "unit": "pack of 400g"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 7.0, "unit": "tub of 200g"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.008, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_honey", "quantity": {"value": 0.167, "unit": "jar of 500g"}}, {"id": "ing_corn", "quantity": {"value": 0.056, "unit": "can of 400g"}}, {"id": "ing_rice_noodles", "quantity": {"value": 0.067, "unit": "pack of 375g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["300g/ 10oz chicken thighs (, skinless boneless, cut into 2.5cm/1\" pieces (Note 1))","1 tbsp light soy sauce (or all purpose, NOT dark soy)","2 tsp Chinese cooking wine (sub with soy)","2 tsp cornflour/cornstarch"],"purpose":"Chicken & Marinade:"},{"ingredients":["1/2 cup cornflour/cornstarch"],"purpose":"Dredging:"},{"ingredients":["6 tbsp cornflour/cornstarch (Note 8)","4 tbsp flour (, plain/all purpose)","7 - 8 tbsp COLD soda water, club soda or seltzer water (NOT sparkling mineral water, Note 2)","1/4 tsp baking powder (NOT baking soda)","1/4 tsp salt (, kosher/cooking (halve for table salt))"],"purpose":"Stay-Crispy Puffy Batter:"},{"ingredients":["2 - 3 cups vegetable oil (or canola)"],"purpose":"Oil, for frying:"},{"ingredients":["1/3 cup (100g) honey","1.5 tbsp (25g) glucose OR corn syrup (light) (Note 6)","1 tbsp light soy sauce (or all purpose)","2 tsp Chinese cooking wine (or more soy sauce)"],"purpose":"Honey Sauce (Note 8 on sweetness):"},{"ingredients":["25g / 2 oz Vermicelli rice noodles (optional) (, a wad of it (not bean noodles, must be rice noodles))","Sesame seeds, finely sliced green onions"],"purpose":"Garnish / serving:"}]', '[{"description":"Recommended step for beginners:","images":[],"step":1},{"description":"Place batter mixing bowl in the fridge with the flour, baking powder and salt. (Helps keep batter cold = crispier chicken)","images":[],"step":2},{"description":"Marinate & Dust Chicken:","images":[],"step":3},{"title":"Marinade","description":"Mix Chicken and Marinade in a bowl. Refrigerate for 30 minutes.","duration":30,"images":[],"step":4},{"title":"Dust","description":"Spread the 1/2 cup cornflour/cornstarch on a shallow plate. Scatter over about 8 to 10 chicken pieces, toss to coat, shake off excess, put on a plate. Repeat with all chicken.","images":[],"step":5},{"description":"Cold Batter & Fry #1:","images":[],"step":6},{"title":"Rack","description":"Place a rack on a tray (for draining, Note 3)","images":[],"step":7},{"title":"Heat oil","description":"Fill small pot or large saucepan with 4cm / 1.7\" oil. Heat to 180°C/350°F on medium high stove (or until chicken starts sizzle straight away when dipped).","images":[],"step":8},{"title":"Make Cold Batter","description":"Whisk together flour, cornflour/cornstarch, baking powder and salt. Pour in 7 tbsp soda water, then do minimum whisks just to combine (10 or so) - few lumps ok, better than whisking too much (changes coating texture).","images":[],"step":9},{"title":"Batter thickness","description":"should fully coat chicken easily, not be see through, but not thick and heavy - see video at 44 seconds. Use extra water 1 teaspoon at a time to achieve right thickness.","images":[],"step":10},{"title":"Dredge","description":"Drop 8 or so pieces of chicken into the batter. Turn to coat, then carefully place in oil.","images":[],"step":11},{"title":"Fry #1","description":"Cook for 3 minutes until light golden and crispy - when you pick them up, you can tell it''s very crispy.","duration":3,"images":[],"step":12},{"title":"Drain & repeat","description":"Place on rack, repeat with remaining chicken - I cook in 4 batches, don''t crowd the pot, brings oil temperature down too much.","images":[],"step":13},{"description":"Cool chicken for 20 minutes (Note 4). Meanwhile, make Sauce.","duration":20,"images":[],"step":14},{"description":"Place ingredients in a large saucepan over medium heat. Bring to simmer, then leave to simmer for 3 minutes.","duration":3,"images":[],"step":15},{"description":"Consistency should be like maple syrup (video at 1 min 11 sec). Turn off stove, place lid on to keep warm (when cool, gets too thick to toss chicken).","images":[],"step":16},{"title":"Fry #2","description":"for ultra crispy!","images":[],"step":17},{"description":"Heat oil to 200°C/390°F.","images":[],"step":18},{"description":"Add in half the chicken (you can crowd the pot for Fry #2). Cook for 90 seconds until it changes from pale golden to very golden (but not dark golden, chicken will overcook), then remove onto rack. More golden = crispier chicken.","duration":1.5,"images":[],"step":19},{"title":"Repeat with remaining chicken. (Feel the chicken","description":"you can tell it''s built-to-last crispy!)","images":[],"step":20},{"description":"Toss in Sauce & Serve:","images":[],"step":21},{"description":"Tumble into saucepan with sauce, use rubber spatula to quick toss until coated with sauce. (Sauce starts thickening if you take too long, so be quick!)","images":[],"step":22},{"description":"Pile chicken up over crispy noodles (if using), scatter with sesame seeds and green onion and serve!","images":[],"step":23},{"description":"Puffy Crispy Noodles (optional):","images":[],"step":24},{"description":"At any point while oil is hot, drop wad of noodles into hot oil, wait 3 seconds until it puffs up, then remove with tongs.","images":[],"step":25},{"description":"Drain on paper towels, place on plate to top with chicken!","images":[],"step":26}]', '["gluten","sesame","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chicken","chicken-breast-recipes","chicken-recipes","chinese-recipes","deep-fried-recipes","iconic-dishes","mains","modern-asian"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6437007c7815', 'en', 'US', 'Sweet and Sour Pork', 'Recipe video above. The best ever Sweet and Sour Pork recipe is loaded with tricks the Chinese have been using for centuries: double dredgeand double fry for extra crispy, cornflour instead of flour, economical pork used for juiciness, but tenderised with baking soda so you''d swear they''re pricey chops, and a sauce that''s not sickeningly sweet. Don''t let the list of ingredients daunt you. There''s a lot of repeat ingredients!OVEN option provided in notes. Because sometimes, you just have to....', 'https://www.recipetineats.com/tachyon/2020/08/Sweet-and-Sour-Pork_6.jpg', 20, 30, 50, 5, '[{"id": "ing_pork", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.009, "unit": "tub of 200g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.025, "unit": "pack of 400g"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_oil", "quantity": {"value": 2.0, "unit": "bottle"}}, {"id": "ing_sugar", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.167, "unit": "bottle of 500ml"}}, {"id": "ing_pineapple", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_ketchup", "quantity": {"value": 0.09, "unit": "bottle of 500g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 2.5, "unit": "bottle"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_flour", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 2.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_pineapple", "quantity": {"value": 3.0, "unit": "unit"}}]', '[{"ingredients":["400g/14oz pork scotch roast (aka pork neck, collar butt) or shoulder / butt, (cut into 2cm / 4/5\" cubes (Note 1))","1/2 onion (, finely grated (Note 2a))","1 tsp garlic (, finely grated (Note 2a))","1 tsp ginger (, finely grated (Note 2a))","3/8 tsp baking soda (bi-carb) (Note 2b)","2 tsp cornflour/cornstarch","2 tbsp light soy sauce (, or all purpose (Note 3))"],"purpose":"Tenderised Marinated Pork:"},{"ingredients":["5 tbsp cornflour/cornstarch ( - for mixing in)","1/2 cup cornflour/cornstarch ( - for Coating)","2 - 3 cups vegetable or canola oil"],"purpose":"For frying:"},{"ingredients":["1/3 cup white sugar","1/3 cup apple cider vinegar (or 1/4 cup normal white vinegar)","3 tbsp pineapple juice (from a 227g/8oz can pineapple pieces in juice, preferably no added sugar, Note 4)","3 tbsp ketchup (or Aussie tomato sauce)","1/2 tsp Worcestershire sauce","1 tbsp soy sauce (, light)","1 tsp Oyster Sauce (Note 5)","4 tsp cornflour/corn starch","1/2 cup water"],"purpose":"Sweet & Sour Sauce:"},{"ingredients":["1 tbsp oil","1 garlic clove (, finely chopped)","2 tsp ginger (, finely chopped)","1 onion (medium), cut into 2.5cm/ 1\" cubes (brown, white, yellow)","1/2 red capsicum/bell pepper ((large), cut into 2.5cm / 1\" cubes)","1/2 green capsicum/bell pepper ((large), cut into 2.5cm / 1\" cubes)","1 cup pineapple pieces (from the can of pineapple under Sauce)"],"purpose":"Stir Frying:"}]', '[{"description":"Mix Pork with Marinade. Marinade 18 to 24 hours. (See Note 1 for marinating time for other cuts)","images":[],"step":1},{"title":"Rack & warm oven","description":"Preheat oven to 80°C/175°F and place rack on tray - to keep pork warm.","images":[],"step":2},{"title":"Sauce","description":"Place all Sauce ingredients EXCEPT water in a large jug or small bowl. Mix until combined, then mix in water.","images":[],"step":3},{"title":"Be Stir Fry Ready","description":"Have all ingredients lined up, ready to toss in. After Fry #2, things move quickly.","images":[],"step":4},{"title":"Coating #1","description":"Mix 5 tablespoons cornflour into the pork and leave for 5 minutes. At first, it will be white from the cornflour, but after a while it will sweat and make the cornflour (mostly / partially) wet, and will be sticky (this is key for coating to stick).","duration":5,"images":[],"step":5},{"title":"Coating #2","description":"Spread 1/2 cup cornflour in a shallow bowl. Coat pork, shaking off excess, and pile onto a plate.","images":[],"step":6},{"description":"Reserve cornflour in case you need to dust again just prior to frying. Pork should be at least half white when you put it into the oil (if not, just sprinkle with reserved cornflour).","images":[],"step":7},{"description":"Fried Crispy Pork (Note 6 for oven):","images":[],"step":8},{"title":"Heat oil","description":"Pour enough oil into a large saucepan or small pot so it''s 2.5cm / 1\" deep. Heat to 180°C/350°F (or until pork immediately starts sizzling when you dip it in).","images":[],"step":9},{"title":"Fry #1","description":"Cook pork in batches, being sure not to crowd the pot, for 3 minutes until golden. Drain on rack. This step is just to cook the pork. It takes me 4 batches.","duration":3,"images":[],"step":10},{"title":"Fry #2","description":"Turn the stove up slightly and heat oil to 200°C/390°F. Starting with the coolest pork, add half the pork (you can crowd the pot) and cook for 1 1/2 minutes, or until pork is deep golden brown and crispy. Transfer to rack, repeat with remaining pork - I do 2 batches.","images":[],"step":11},{"description":"Keep warm in oven.","images":[],"step":12},{"description":"Sauce & Stir Fry:","images":[],"step":13},{"description":"Heat oil in a very large skillet over high heat.","images":[],"step":14},{"description":"Add garlic, ginger and onion, stir for 1 1/2 minutes. Add capsicum and stir for 2 minutes.","duration":2,"images":[],"step":15},{"description":"Add Sauce & pinapple, then let it come to a rapid simmer. Simmer for 2 minutes until it thickens - when you drag the spoon across the base, a path should briefly appear (see video at 1 min 53 s).","duration":2,"images":[],"step":16},{"title":"10 second toss","description":"Add pork, then QUICKLY toss to coat - aim for 10 seconds!","duration":0.16666666666666666,"images":[],"step":17},{"description":"Serve asap! Pour onto serving plate, serve immediately! Will stay crispy for around 5 minutes then starts softening but still has a solid coating. This is just the reality of Sweet and Sour Pork, even at restaurants!","images":[],"step":18}]', '["gluten","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chinese-recipes","deep-fried-recipes","modern-asian","pork-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4d2ed32f7ebe', 'en', 'US', 'Chicken Broccoli Stir Fry (extra sauce!)', 'Recipe video above. Big batch stir fry made with chicken and broccoli, and lots and lots of sauce - because broccoli florets hold lots of sauce but I still want some to soak my rice!This sauce uses the minimum ingredients you can get away with but still make something that stacks up to real Chinese take out. Chinese cooking wine (shoaxing wine) is the restaurant secret - just a small splash adds depth of flavour into the sauce.Shortcut using Charlie - see Note 5 (the sauce in this recipe is basically Charlie!).', 'https://www.recipetineats.com/tachyon/2020/07/Chicken-Broccoli-Stir-Fry_2.jpg', 10, 6, 16, 5, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.037, "unit": "tub of 200g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.075, "unit": "pack of 400g"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.045, "unit": "bottle of 500ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_broccoli", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_white_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["500g/1 lb chicken breast, thinly sliced (or boneless thighs, do not tenderise)","1 1/2 tsp baking soda / bi-carb soda (Note 1)"],"purpose":"Tenderised chicken (Note 1)"},{"ingredients":["2 tbsp cornflour/cornstarch","3 tbsp light soy sauce (, or all purpose soy (Note 2))","1 1/2 tbsp Chinese cooking wine (shaoxing wine) or Mirin (Note 3)","3 tbsp oyster sauce (Note 4)","2 tsp sesame oil (, toasted (Note 5))","Dash of white pepper (sub black)"],"purpose":"Sauce (Note 6 for using Charlie all-purpose stir fry):"},{"ingredients":["2 tbsp oil (, peanut, vegetable or canola)","1/2 onion (, sliced)","2 garlic cloves (, finely minced with knife)","400g/ 14 oz broccoli florets (, broken/cut into small bite size pieces (2 medium heads, ~5 cups))","1 1/4 cups water"],"purpose":"Stir Fry:"},{"ingredients":["White rice (or other rice of choice)"],"purpose":"For serving:"}]', '[{"title":"Tenderise chicken","description":"Consider tenderising chicken breast using this method. (Not needed for thigh)","images":[],"step":1},{"title":"Broccoli","description":"steam or boil using preferred method until cooked to your taste (it won''t cook any further in the stir fry). I usually microwave steam 3 minutes on high. Drain well (waterlogged florets = diluted sauce).","images":[],"step":2},{"title":"Sauce","description":"Mix cornflour and soy sauce until lump free, then mix in remaining ingredients.","images":[],"step":3},{"title":"Cook aromatics","description":"Heat oil in a large skillet over high heat. Add garlic and onion, stir for 10 seconds until garlic starts to go golden.","duration":0.16666666666666666,"images":[],"step":4},{"title":"Cook chicken","description":"Add chicken and cook for 2 minutes or until the chicken is just cooked through.","duration":2,"images":[],"step":5},{"title":"Thicken sauce","description":"Add broccoli, Sauce and water. Stir well and cook for 1 to 2 minutes until the Sauce thickens and becomes glossy, and coats the ingredients.","duration":1.5,"images":[],"step":6},{"description":"Serve over rice!","images":[],"step":7}]', '["gluten","peanuts","sesame","soy"]', '["high_protein","low_calorie"]', '{"mealType":["dinner"],"cuisine":["American Chinese","Asian","Chinese"],"categories":["asian-recipes","broccoli-recipes","chicken-breast-recipes","chicken-recipes","chinese-recipes","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e0a60baac8d6', 'en', 'US', 'Pineapple Fried Rice (Thai)', 'Recipe video above. Terrific side dish option with a tropical or summer flair! This is a Thai dish made with a classic Thai Fried Rice Sauce. Use ONE of the 3 sauces - all are traditional. Serve with all things Thai, Asian, BBQ, tropical themed, Caribbean (excellent match!), fish, prawns/shrimp, salmon - see in post for ideas. Also - featured in Monday''s Honey Soy Chicken.', 'https://www.recipetineats.com/tachyon/2020/06/Pineapple-Fried-Rice_1.jpg', 10, 10, 20, 6, '[{"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_peas", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_pineapple", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_green_onion", "quantity": {"value": 1.5, "unit": "bunch"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_thai_seasoning", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["2 tbsp vegetable oil","2 garlic cloves (, finely minced)","1/2 onion (, finely chopped)","1/2 red capsicum / bell peppers (, diced (~ 3/4 cup))","1/2 cup peas (, frozen)","3 cups day old jasmine rice (, cooked (Note 1))","1 1/2 cups pineapple pieces (, fresh or canned drained (~ 220g) (Note 2))","1/2 cup green onion (, sliced)"]},{"ingredients":["1 tbsp oyster sauce","1 1/2 tbsp fish sauce","1/2 tsp sugar"],"purpose":"Sauce Option 1 (Base version, recommended):"},{"ingredients":["1 tbsp oyster sauce","1 1/2 tbsp soy sauce (, light or all purpose (not dark soy))"],"purpose":"Sauce Option 2:"},{"ingredients":["1 1/2 tbsp soy sauce","1 tbsp Thai Seasoning (Gold Mountain)"],"purpose":"Sauce Option 3:"}]', '[{"description":"Heat oil in a wok or large non stick skillet over high heat.","images":[],"step":1},{"description":"Add garlic and onion, cook for 1 minute.","duration":1,"images":[],"step":2},{"description":"Add capsicum, cook for 1 minute.","duration":1,"images":[],"step":3},{"description":"Add peas, stir for 30 seconds.","duration":0.5,"images":[],"step":4},{"description":"Add rice and Sauce ingredients of choice. Cook, stirring constantly, for 2 minutes or until rice grains goes from being wet with sauce to sort of caramelised.","duration":2,"images":[],"step":5},{"description":"Add pineapple, stir for just 30 seconds to warm through.","images":[],"step":6},{"description":"Stir through green onions then serve!","images":[],"step":7}]', '["fish","gluten","soy"]', '["low_calorie"]', '{"mealType":["main_course"],"cuisine":["Thai","Tropical!"],"categories":["asian-recipes","cuisines","fried-rice","modern-asian","rice-recipes","rice-side-dishes","side-dishes","thai-recipes","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6691a38fb1f7', 'en', 'US', 'How to cook Jasmine Rice (stove)', 'Recipe video above. The key to fluffy jasmine rice is to use less water than usual because it''s a softer rice - only 1 1/4 cups for each 1 cup of rice. Most recipes get this wrong and the rice is way too soft/gummy. Rinsing is optional - it barely makes a difference to fluffiness (see comments in post). And it''s a pain! Also, if you rinse, you need to reduce water by 2 tablespoons to factor in that the rice becomes waterlogged!1 cup rice = 3 cups cooked = 3 to 4 servings as a side.', 'https://www.recipetineats.com/tachyon/2020/06/Jasmine-Rice_8.jpg', 1, 12, 13, 3, '[{"id": "ing_jasmine_rice", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.312, "unit": "L"}}]', '[{"ingredients":["1 cup jasmine rice","1 1/4 cups water (cold tap water)"],"purpose":"No rinsing method:"},{"ingredients":["1 cup jasmine rice","1 1/4 cups MINUS 2 tbsp water"],"purpose":"Rinsed rice:"}]', '[{"description":"No rinsing (my everyday method):","images":[],"step":1},{"description":"Place rice and water in a medium saucepan (one with a tight fitting lid). Bring to rapid simmer with NO LID on medium high.","images":[],"step":2},{"description":"Turn down to low or medium low so it''s simmering gently, then place lid on. Do not lift lid during cook.","images":[],"step":3},{"description":"Cook 12 minutes or until water is absorbed by rice - tilt pot to check (if lid not glass, then QUICKLY lift lid to check).","images":[],"step":4},{"description":"Keep the lid on then remove from heat. Stand 10 minutes, fluff with rubber spatula or rice paddle, then serve.","images":[],"step":5},{"description":"RINSED RICE (Note 3):","images":[],"step":6},{"description":"Place rice in a bowl, fill with water and swish. Once cloudy, drain. Repeat 2 - 3 more times until water is pretty clear - it will never be completely clear.","images":[],"step":7},{"description":"Drain rice in a colander, transfer to saucepan.","images":[],"step":8},{"title":"Add water","description":"1 1/4 cups of water MINUS 2 tablespoons per 1 cup of rice. Follow cook steps above in No Rinsing.","images":[],"step":9}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Asian","Modern Vietnamese","Thai"],"categories":["asian-recipes","cuisines","good-to-know","rice","rice-recipes","rice-side-dishes","side-dishes","thai-recipes","vegan-lifestyle"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_399afb02c305', 'en', 'US', 'Gado Gado (Indonesian Salad with Peanut Sauce)', 'Recipe video above. Fun to say, delicious to eat, the Gado Gado peanut sauce will make any vegetables into a big, healthy, tasty meal! Use any veg you want - the ones I''ve used are in the spirit of traditional Indonesian Gado Gado. Using Thai Red Curry Paste is an effective shortcut - it uses a lot of the ingredients used in Gado Gado sauce. Saves time, effort and money!All the veg can be warm or at room temp, so cook them first. Tempeh/tofu is best hot and crispy fresh out of the skillet.', 'https://www.recipetineats.com/tachyon/2020/06/Indonesian-Gado-Gado.jpg', 15, 15, 30, 2, '[{"id": "ing_peanut_butter", "quantity": {"value": 0.133, "unit": "jar of 375g"}}, {"id": "ing_red_curry_paste", "quantity": {"value": 0.1, "unit": "bottle"}}, {"id": "ing_kecap_mani", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_ime_juice", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.312, "unit": "can of 400ml"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_spinach", "quantity": {"value": 1.0, "unit": "bag of 250g"}}, {"id": "ing_beansprouts", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_potato", "quantity": {"value": 200.0, "unit": "bag of 2kg"}}, {"id": "ing_cucumber", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_shrimp", "quantity": {"value": 15.0, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_tempeh", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_peanuts", "quantity": {"value": 0.037, "unit": "jar"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}]', '[{"ingredients":["1/3 cup natural peanut butter, smooth or crunchy (your choice) (Note 1)","4 tsp red curry paste (, store bought (Maesri brand best, Note 2))","3 tsp Kecap Manis (Indonesian sweet soy sauce, Note 3)","1 tsp sambal oelak or other chilli paste (adjust spiciness to taste)","1/2 tsp salt","1 large garlic clove (, pressed using garlic press (~ 3/4 tsp))","1 1/2 tbsp lime juice (Note 4)","1/2 cup coconut milk (, full fat (Ayam brand best))","1/2 cup water"],"purpose":"Gado Gado Sauce:"},{"ingredients":["1 bunch spinach (, roots trimmed)","4 cups beansprouts","200g / 7 oz potato ( - small halved, large peeled chopped 2 cm / 1\" cubes OR 1.5cm / 1/2\" slices)","1 cucumber (, sliced on the diagonal ( or 1/2 long cucumber ie Telegraph/English))","2 - 3 boiled eggs (, peeled and halved)","15 prawn crackers (, optional (Note 6))"],"purpose":"Salad (use any veg, Note 5):"},{"ingredients":["2 tbsp vegetable or peanut oil","200g / 7 oz tempeh (or firm tofu, Note 7)"],"purpose":"Crispy Tempeh (or tofu):"},{"ingredients":["1 tbsp finely chopped peanuts (highly recommended)","Red chilli (, finely sliced, optional (small = spicy, large = less spicy))"],"purpose":"Garnishes:"}]', '[{"description":"Gado Gado Peanut Sauce:","images":[],"step":1},{"description":"Mix all ingredients in a small saucepan over medium low heat. Bring to simmer then cook for 5 minutes, stirring regularly so the bottom doesn''t catch, until it thickens. If too thick, just add more water - should be able to drizzle it (see video for thickness).","duration":5,"images":[],"step":2},{"title":"Taste and adjust as follows","description":"lime for more sour, salt, sugar for sweet.","images":[],"step":3},{"description":"Cover and keep warm.","images":[],"step":4},{"description":"Blanched Vegetables:","images":[],"step":5},{"description":"Bring a saucepan of water to the boil.","images":[],"step":6},{"description":"Add potatoes and cook for 5 minutes or until cooked through. Use a slotted spoon to transfer to colander to drain.","duration":5,"images":[],"step":7},{"description":"Cook beansprouts for 3 minutes or until just wilted. Transfer to colander, press out excess water.","duration":3,"images":[],"step":8},{"title":"Add spinach, push under to submerge","description":"will instantly wilt. Remove, transfer to colander, press out excess water.","images":[],"step":9},{"description":"Crispy tempeh or tofu:","images":[],"step":10},{"description":"Slice into 0.75 x 5 cm / 1/3 x 2\" slices (or thereabouts).","images":[],"step":11},{"description":"Heat oil in a skillet over medium high heat. Cook tempeh 2 min on each side until deep golden and crispy. (Tofu ~ 1 1/2 min)","images":[],"step":12},{"description":"Either make one platter for sharing, or individual. Vegetables and egg can be served warm or at room temp, sauce should be served warm (it thickens when cool).","images":[],"step":13},{"description":"Place vegetables and tempeh on serving plate, top with egg.","images":[],"step":14},{"description":"Pour sauce into serving bowl.","images":[],"step":15},{"description":"Serve Gado Gado Salad with peanut sauce, peanuts for sprinkling, fresh chillies and prawn crackers on the side.","images":[],"step":16}]', '["egg","gluten","peanuts","shellfish","soy"]', '["high_protein"]', '{"mealType":["dinner","lunch"],"cuisine":["Bali","Indonesian"],"categories":["asian-recipes","modern-asian","salad-recipes-main-course","sauces","side-salads","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7cf6bc869af5', 'en', 'US', 'Chinese Noodle Soup', 'Recipe video above. A simple, delicious Chinese noodle soup with a broth that you''d swear came from your favourite Chinese restaurant! This is a midweek version so it''s made with store bought soup broth rather than a made from scratch broth. I''ve kept the toppings very simple because this recipe is more about the broth than the toppings. You can add any toppings you want - vegetables and proteins (refer Note 7).', 'https://www.recipetineats.com/tachyon/2016/06/Chinese-Noodle-Soup_0.jpg', 5, 10, 15, 2, '[{"id": "ing_chicken_stock", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.045, "unit": "bottle of 500ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.25, "unit": "pack of 100g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.36, "unit": "pack of 500g"}}, {"id": "ing_bok_choy", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["3 cups chicken stock/broth, low sodium (Note 1)","2 garlic cloves (, smashed (Note 2))","1.5 cm / 1/2\" ginger piece, (cut into 3 slices (optional, but highly recommended))","1 1/2 tbsp light soy sauce (, or normal all purpose soy sauce (Note 3))","2 tsp sugar (any)","1 1/2 tbsp chinese cooking wine (Note 4)","1/4 - 1/2 tsp sesame oil (, toasted (optional) (Note 5))"],"purpose":"Broth"},{"ingredients":["180g / 6oz fresh egg noodles (Note 6)","2 large bok choy or other vegetables of choice (use any blanchable veg - Note 7)","1 cup shredded cooked chicken (or other protein of choice)","1 scallion / shallot (, green part only finely sliced (optional garnish))"],"purpose":"Toppings & Noodles"}]', '[{"description":"Place Broth ingredients in a saucepan over high heat. Place lid on, bring to simmer then reduce to medium and simmer for 8 - 10 minutes to allow the flavours to infuse.","duration":9,"images":[],"step":1},{"description":"Meanwhile, cook noodles according to packet directions.","images":[],"step":2},{"description":"Cut bok choys in half (for small / medium) or quarter (for large). Wash thoroughly.","images":[],"step":3},{"description":"Either cook the bok choi in the broth in the soup broth OR noodle cooking water for 1 min (if noodles required boiling).","duration":1,"images":[],"step":4},{"description":"Pick garlic and ginger out of soup.","images":[],"step":5},{"description":"Place noodles in bowls. Top with chicken and bok choy. Ladle over soup, garnish with green onions. Great served with chilli paste or fresh chillis.","images":[],"step":6}]', '["egg","gluten","sesame","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","asian-soups","asian-takeout","chicken-breast-recipes","chicken-recipes","chinese-recipes","dietary","dinner-tonight","emergency-recipes","low-calorie-recipes","main-dishes","most-popular","noodles","quick-and-easy","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a3986a4ee5df', 'en', 'US', 'Vietnamese Rice Paper Rolls (Spring Rolls)', 'Recipe video above. Vietnamese Rice Paper Rolls are incredibly fresh and healthy. The Vietnamese peanut dipping sauce that accompanies this is sensational and completely addictive!', 'https://www.recipetineats.com/tachyon/2014/07/Vietnamese-Rice-Paper-Rolls-7.jpg', 20, 0, 20, 7, '[{"id": "ing_rice", "quantity": {"value": 7.0, "unit": "pack"}}, {"id": "ing_shrimp", "quantity": {"value": 11.0, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.1, "unit": "pack of 500g"}}, {"id": "ing_lettuce", "quantity": {"value": 140.0, "unit": "head"}}, {"id": "ing_mint", "quantity": {"value": 14.0, "unit": "bunch"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 1.0, "unit": "bag of 250g"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.04, "unit": "jar of 375g"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_milk", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_chilli", "quantity": {"value": 0.025, "unit": "pack of 100g"}}]', '[{"ingredients":["7 - 14 sheets of 22cm/8.5\" round rice paper (Note 1)","11 small cooked prawns/shrimp (about 12cm/5\" in length, unpeeled including the head)","50g / 1.5 oz dried vermicelli noodles","7 lettuce leaves - use a lettuce with soft leaves, like Oak or Butter Lettuce (Note 2)","14 mint leaves","1 cup bean sprouts"]},{"ingredients":["1 tbsp peanut butter, preferably smooth (crunchy is ok too)","2 tbsp Hoisin Sauce","1 1/2 tbsp white vinegar (or lime juice)","1/3 cup milk ( (any fat %) (or water))","1 garlic clove, minced","1/2 tsp crushed chilli, samba oelak or other chilli paste, adjust to taste (optional)"],"purpose":"Vietnamese Peanut Dipping Sauce (Note 3)"}]', '[{"title":"Peanut Sauce","description":"Combine the Peanut Dipping Sauce ingredients. Mix briefly (it won''t come together), then microwave for 30 seconds. Mix again until smooth. Set aside to cool. Adjust sour with vinegar, salt with salt and spiciness to taste. Thickness can be adjusted with milk or water once cooled.","duration":0.5,"images":[],"step":1},{"description":"Place vermicelli noodles in a bowl and cover with warm water for 2 minutes, then drain (or follow packet instructions).","duration":2,"images":[],"step":2},{"description":"Peel the prawns, slice in half lengthwise and devein (watch video).","images":[],"step":3},{"description":"Remove the crunchy core of the lettuce leaves (watch video).","images":[],"step":4},{"title":"Tip","description":"LETTUCE BUNDLE (Note 4): Place some vermicelli noodles and bean sprouts in a lettuce leaf, then roll it up, finishing seam side down. Repeat.","images":[],"step":5},{"description":"Fill a large bowl with warm water. The bowl doesn''t need to be large enough to fit the whole rice paper in one go.","images":[],"step":6},{"description":"Place two rice papers together (if using 2). Note which side is the smooth side - this is supposed to be the outside of the spring roll. Submerge the rice papers into the water (both of them at the same time, together) for 2 seconds. If your bowl isn''t large enough to fit the whole rice paper in one go, that''s fine, just rotate it and count 2 seconds for each section you submerge into the water.","duration":0.03333333333333333,"images":[],"step":7},{"description":"Place both the rice papers (one on top of the other, they will stick together) on a board or the counter with the smooth side down.","images":[],"step":8},{"description":"On the top part of the rice paper, place 3 prawns with a mint leaf in between, as per the photo below.","images":[],"step":9},{"description":"Place the lettuce bundle with the seam side down onto the middle of the rice paper.","images":[],"step":10},{"description":"Fold the left and right edges of the rice paper in, then starting from the bottom, roll up to cover the lettuce bundle. Then keep rolling firmly. The rice paper is sticky, it will seal itself.","images":[],"step":11},{"description":"If you placed the ingredients on the rice paper as per the photo below, your rice paper rolls should look pretty with the prawn and mint leaves on the smooth side of the roll and the seam on the side or underside of the roll.","images":[],"step":12},{"description":"Serve immediately with the peanut dipping sauce.","images":[],"step":13}]', '["milk","peanuts","shellfish"]', '["gluten_free","low_calorie"]', '{"mealType":["snack"],"cuisine":["Vietnamese"],"categories":["asian-recipes","asian-takeout","dietary","finger-food","low-calorie-recipes","modern-asian","most-popular","no-cook-food","prawns-shrimp","quick-and-easy","seafood-recipes","side-dishes","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3cc35b7cd599', 'en', 'US', 'Basmati Rice (simple method, fluffy rice!)', 'Recipe video above. The most common mistake people make when cooking rice is using too much water which makes rice gummy and gluey, especially if you also rinse the rice and make it waterlogged. Using a rice to water ratio of 1 to 1.5, you will be able to make perfectly fluffy basmati rice without fussing with rinsing or draining giant pots of boiling water. Simple, and highly effective! {Scale recipe - click on servings and slide, but read Note 2}', 'https://www.recipetineats.com/tachyon/2020/03/Basmati-Rice_9.jpg', 1, 12, 13, 3, '[{"id": "ing_basmati_rice", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.375, "unit": "L"}}]', '[{"ingredients":["1 cup uncooked basmati rice ( (Note 1))","1 1/2 cups water (just cold tap water)"]}]', '[{"description":"Place rice and water in a medium size saucepan over medium high heat, no lid.","images":[],"step":1},{"title":"Bring to a simmer","description":"the edges should be bubbling, the middle should be rippling, the surface will be foaming.","images":[],"step":2},{"description":"Place a tight fitting lid on, then turn heat down to medium low (low for strong stoves).","images":[],"step":3},{"title":"Cook for 12 minutes","description":"DO NOT LIFT LID.","duration":12,"images":[],"step":4},{"description":"Tilt saucepan, then take a QUICK peek to ensure all water is absorbed - be super quick, then clamp lid back on.","images":[],"step":5},{"description":"Remove from heat, leave for 5 to 10 minutes with lid on, then fluff with fork and marvel at fluffy rice!","duration":7.5,"images":[],"step":6},{"title":"Note","description":"Large batches will take slightly longer - about 13 minutes for 2 cups, about 15 minutes for 4 cups (use a pot).","images":[],"step":7}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Indian","Middle Eastern"],"categories":["asian-recipes","good-to-know","indian-recipes","rice","rice-recipes","rice-side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f0b300af633a', 'en', 'US', 'Mie Goreng (Mee Goreng)', 'Recipe video above. These noodles tossed in a sticky savoury sweet sauce originates from Indonesia but is also popular in Malaysia. With chicken, prawns, vegetables and the signature egg ribbons, it''s pretty fully loaded! They''re commonly made by street vendors with instant noodles which give it the familiar crinkly noodle look, but feel free to use any noodles you want. (PS Ketchup is authentic!)', 'https://www.recipetineats.com/tachyon/2020/02/Mie-Goreng_5.jpg', 15, 10, 25, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_kecap_mani", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_ketchup", "quantity": {"value": 0.06, "unit": "bottle of 500g"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.12, "unit": "kg"}}, {"id": "ing_shrimp", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_cabbage", "quantity": {"value": 6.0, "unit": "head"}}, {"id": "ing_beansprouts", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.06, "unit": "bunch"}}]', '[{"ingredients":["3 instant noodle cakes (I use this)","250g/8oz fresh egg noodles (, thin to medium)","150g / 5oz dried egg noodles (, thin to medium)"],"purpose":"Noodles – use ONE (Note 1):"},{"ingredients":["2 tbsp kecap manis (or dark sweet soy sauce) (Note 2)","2 tsp light soy sauce (or normal soy, Note 3)","2 tsp dark soy sauce (, or more light soy sauce (Note 3))","1 tbsp oyster sauce (Note 4)","2 tbsp ketchup (yes really!)","1 tsp sambal oelak, chilli paste or Sriracha (adjust spiciness to taste)","2 tsp sesame oil"],"purpose":"Sauce:"},{"ingredients":["2 tbsp vegetable oil","2 eggs (, lightly whisked)","3 garlic cloves (, finely chopped)","120g/4oz chicken breast or thigh (, sliced thinly into small bite size pieces)","100g/3.5oz prawns/shrimp (, raw, peeled and deveined (smaller are better))","2 cups cabbage (, finely sliced (any green or white cabbage))","1 cup beansprouts","3 green onions (, cut into 5cm/2\" lengths (green and white part))"],"purpose":"Stir Fried Noodles:"}]', '[{"description":"Mix the Sauce in a bowl.","images":[],"step":1},{"description":"Prepare noodles per packet directions just before cooking.","images":[],"step":2},{"description":"Heat 1 tbsp oil in a large skillet over medium heat. Pour in egg, swirl to coat base. Cook 1 minute until mostly set, then flip (do your best!).","images":[],"step":3},{"description":"Slide onto cutting board, roll up into loose \"wrap\". Slice into 1cm/ 1/3\" thick pieces - you now have egg ribbons!","images":[],"step":4},{"description":"Cooking:","images":[],"step":5},{"description":"Heat remaining 1 tbsp oil in same skillet over HIGH heat.","images":[],"step":6},{"description":"Add garlic and chicken, cook until half surface turns white.","images":[],"step":7},{"description":"Add prawns and cook for 1 minute until chicken is mostly cooked.","duration":1,"images":[],"step":8},{"description":"Add cabbage and bean sprouts, toss for 1 minute until a bit wilted.","duration":1,"images":[],"step":9},{"title":"Add noodles, green onions and Sauce, toss for 1","description":"2 minutes until Sauce reduces and noodles caramelise a bit.","duration":1.5,"images":[],"step":10},{"description":"Toss through egg ribbons and serve immediately!","images":[],"step":11}]', '["egg","gluten","sesame","shellfish","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","Indonesian","Malaysian"],"categories":["asian-recipes","noodles"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f78cce541191', 'en', 'US', 'Momofuku Bossam (Korean Slow Cooked Pork Shoulder Roast)', 'Recipe video above. This is David Chang''s famous Momofuku Bossam (or Bo ssam), his take on the traditional Korean pork dish that costs US$250 at his NYC restuarant! Pork shoulder is dry cured so it''s seasoned from end to end, then slow roasted until fall apart tender and finished with a brown sugar crust. Serve with condiments for DIY lettuce wraps for an epic eating experience that will be remembered for years to come!', 'https://www.recipetineats.com/tachyon/2020/02/Momofuku-Bossam-Korean-Slow-Cooked-Pork-Shoulder_1-1.jpg', 10, 300, 1450, 10, '[{"id": "ing_pork", "quantity": {"value": 3.5, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.105, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 7.5, "unit": "bunch"}}, {"id": "ing_ginger", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 50.0, "unit": "bottle"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.03, "unit": "bottle of 250ml"}}, {"id": "ing_vinegar", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_ssamjang", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_gochujang", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_oil", "quantity": {"value": 50.0, "unit": "bottle"}}, {"id": "ing_water", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_lettuce", "quantity": {"value": 4.0, "unit": "head"}}, {"id": "ing_white_rice", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_kimchi", "quantity": {"value": 500.0, "unit": "unit"}}, {"id": "ing_oysters", "quantity": {"value": 12.0, "unit": "kg"}}]', '[{"ingredients":["3.5-4 kg/ 7-8 lb pork butt / shoulder (, bone in & skinless (Note 1))","1/2 cup (110g) white sugar","1/2 cup (115g) kosher or cooking salt (NOT table salt) (Note 2)"],"purpose":"Slow Cooked Pork:"},{"ingredients":["1 tbsp kosher or cooking salt (NOT table salt) (Note 2)","7 tbsp brown sugar (, light or normal (not dark))"],"purpose":"Brown Sugar Crust:"},{"ingredients":["2.5 cups scallions (, thinly sliced (both green and white parts, ~5-6 stems))","1/2 cup fresh ginger (, peeled and finely grated (Note 3))","1/3 cup canola oil (Note 4)","1.5 tsp light soy sauce (or all purpose, not dark soy sauce Note 5)","1 teaspoon sherry vinegar (Note 6)","1/2 tsp kosher or cooking salt (, to taste (Note 2))"],"purpose":"Ginger Shallot Sauce:"},{"ingredients":["2 tbsp ssamjang (Note 8)","1 tbsp gochujang (Note 8)","5 tsp sherry vinegar (Note 6)","2 tbsp canola oil (Note 4)","1 tbsp water","1 tsp white sugar"],"purpose":"Spicy Ssam Sauce (Note 7):"},{"ingredients":["4 - 5 heads butter/bib lettuce (40 - 50+ leaves, Note 9)","3 cups cooked white rice","500g/1lb kimchi","12 + oysters (, raw, in shell (optional, Note 10))"],"purpose":"Serving:"}]', '[{"description":"Bossam Slow Cooked Pork:","images":[],"step":1},{"description":"Mix sugar and salt together. Pat pork dry. Coat pork in sugar salt mixture, getting it into all the crevices. Rub/pat well to adhere as best you can - discard excess salt unused/falls off (usually ~ 2-3 tbsp).","images":[],"step":2},{"description":"Place in a glass dish (Note 13), cover loosely with cling wrap and refrigerated 24 - 36 hours (Note 11).","images":[],"step":3},{"description":"Preheat oven to 150°C/300°F (all oven types) with rack in the middle of oven.","images":[],"step":4},{"title":"Remove pork from fridge","description":"surface will be wet. Either transfer pork to clean pan (metal, ceramic or glass) or drain off excess liquid / scrape out salt/sugar in same glass pan. Do not rinse pork.","images":[],"step":5},{"description":"Roast 5 hours (Note 12), uncovered, spooning over pan juices once each hour, until you can easily pull the meat apart with 2 forks (check on side).","images":[],"step":6},{"description":"Remove from oven, rest for 10 minutes (up to 1 hour is fine, loosely cover in foil).","duration":10,"images":[],"step":7},{"description":"Turn oven up to 260°C/500°F (all oven types).","images":[],"step":8},{"description":"Brown Sugar Crust:","images":[],"step":9},{"description":"Mix brown sugar and salt.","images":[],"step":10},{"description":"Spoon juices all over pork.","images":[],"step":11},{"description":"Spoon sugar onto pork and use your hands to make it stick to the top and sides (not underneath). Make layer on top as even as you can (for even caramelisation).","images":[],"step":12},{"description":"Place in oven for 10 minutes until surface is a deep golden crust, sugar is bubbling and caramelised (see VIDEO!). Keep a close eye on it from 5 minutes. If the highest points start getting black, cover with small piece of foil (just stick it on).","duration":10,"images":[],"step":13},{"description":"Remove from oven and transfer to serving platter for serving. (Don''t use pan juices, it will be salty from brine)","images":[],"step":14},{"title":"Ginger Shallot Sauce","description":"Mix ingredients in bowl and stand for 20 minutes to let it soften.","duration":20,"images":[],"step":15},{"title":"Ssam Sauce","description":"Mix ingredients together. Oil will naturally separate over time if sauce is left to stand, just mix again to reincorporate.","images":[],"step":16},{"description":"Place pork on serving platter with lettuce, oysters, kimchi, rice, Ginger Shallot Sauce and Ssam Sauce on the side.","images":[],"step":17},{"title":"Attack the pork","description":"it will shred easily. Shred as much or little as you want, let people do it themselves or you can do it for them. Prepare to fight over the epic crust.","images":[],"step":18},{"description":"To eat, place lettuce in hand. Spoon in some rice, top with pulled pork, small piece of kimchi, oyster, some ginger shallot sauce then finally a little drizzle of spicy Ssam sauce.","images":[],"step":19},{"description":"Bundle up, bite and enjoy!","images":[],"step":20}]', '["gluten","milk","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","Korean","Modern Asian"],"categories":["asian-recipes","dietary","gluten-free-recipes","iconic-dishes","korean-recipes","main-dishes","modern-asian","pork-recipes","roasts","slow-cooked-fall-apart"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8af630ad60ee', 'en', 'US', 'Siu Mai (Shumai - Chinese Steamed Dumplings)', 'Recipe video above. Siu Mai is the first thing you grab off the trolleys when you descend upon your favourite Yum Cha. And now you can get your Siu Mai fix on demand! These Chinese steamed dumplings are filled with a classic pork and prawn filling. Serves 2 - 3 as a main meal, or more as part of a larger spread. Also see Japanese Shumai (smaller, topped with peas!)', 'https://www.recipetineats.com/tachyon/2020/02/Siu-Mai_Chinese-steamed-dumplings_3.jpg', 30, 8, 38, 20, '[{"id": "ing_shiitake_mushrooms", "quantity": {"value": 3.0, "unit": "pack of 150g"}}, {"id": "ing_pork_mince", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.013, "unit": "kg"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.045, "unit": "bottle of 500ml"}}, {"id": "ing_shrimp", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_egg", "quantity": {"value": 20.0, "unit": "carton of 12"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.05, "unit": "kg"}}]', '[{"ingredients":["3 dried shiitake mushrooms (, soaked in boiling water, finely chopped (Note 1))","350g/ 13oz pork mince (ground pork) (, fatty (Note 2))","3/4 tsp salt","2.5 tsp sugar","1 tsp light soy sauce (Note 4)","1.5 tbsp Chinese cooking wine (aka Shaoxing wine, sub Mirin or dry sherry) (Note 5)","150g/5oz prawns/shrimp (, peeled and deveined, chopped 0.5cm / 1/5\" (Note 3))","2 tbsp white part of green onions (, finely minced (Note 6))","20 - 25 wonton wrappers / egg wrappers (8cm/3.5\" squares or rounds (Note 7))"]},{"ingredients":["50g/1.5oz flying fish roe (Note 8 for alternatives)"],"purpose":"Garnish:"}]', '[{"description":"Place pork, salt, soy sauce, rice wine, sugar with the pork meat/mince in a large mixing bowl. Mix vigorously with a spoon or use your hands until it becomes pasty (initially it will be crumbly) - about 30 seconds.","images":[],"step":1},{"description":"Add mushrooms, prawns and green onions, mix until just dispersed (don''t crush the prawn meat).","images":[],"step":2},{"description":"Making Siu Mai (process steps and video helpful!):","images":[],"step":3},{"description":"Form an \"O\" with your forefinger and thumb.","images":[],"step":4},{"description":"Place a wonton wrapper over the \"O\". Push in 1 heaped teaspoon of Filling and push down into the \"O\" hole.","images":[],"step":5},{"description":"Use a butter knife to smear more Filling into until level with edge of wonton.","images":[],"step":6},{"description":"Place on work surface and push down to flatten base and use fingers to shape into a round.","images":[],"step":7},{"description":"Steaming Dumplings:","images":[],"step":8},{"description":"Line a 30cm/12\" bamboo steamer (or stove steamer) with baking paper with holes in it (Note 9)","images":[],"step":9},{"description":"Fill a wok big enough to hold steamer with about 2 cups of water (Note 10). Bring to rapid simmer over medium high heat.","images":[],"step":10},{"title":"Place Siu Mai in steamer (20","description":"25 fits). Place lid on, place on wok over simmering water.","images":[],"step":11},{"description":"Steam 8 minutes, or until internal temperature of dumplings is 75°C/165°F. (If yours are bigger due to larger wonton wrappers are bigger, they will take longer).","images":[],"step":12},{"description":"Remove steamer from wok. Remove lid and place a tiny bit of roe in the middle of each dumpling.","images":[],"step":13},{"description":"Serve immediate with dipping sauce!","images":[],"step":14},{"description":"Siu Mai Dipping Sauce:","images":[],"step":15},{"description":"Provide soy sauce, Chinese black vinegar or normal white vinegar, Chinese chilli paste (or Sriracha or other chilli). Let people mix their own to their taste (I do: 3 parts soy, 1 part vinegar, as much chilli as I think I can handle).","images":[],"step":16}]', '["egg","fish","gluten","shellfish","soy"]', '["keto_friendly","low_calorie"]', '{"mealType":["snack","dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","chinese-recipes","dumplings","iconic-dishes","modern-asian","yum-cha-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_14e5bd3dff07', 'en', 'US', 'Dan Dan Noodles', 'Recipe video above. The iconic spicy Sichuan Dan Dan Noodles, made at home! Am intensely flavoured spicy sesame chilli oil sauce tossed with noodles and pork. Don''t be daunted by the list and steps, there''s no need to rush. Cook and prepare all the parts except the noodles. Cook the noodles just before serving so they''re piping hot because the idea is to toss hot noodles with the pork and sauce so the heat warms everything else up. That''s the Dan Dan way!', 'https://www.recipetineats.com/tachyon/2020/02/Dan-Dan-Noodles_4-2.jpg', 15, 15, 30, 4, '[{"id": "ing_sesame_seeds", "quantity": {"value": 0.3, "unit": "pack of 100g"}}, {"id": "ing_chilli", "quantity": {"value": 0.225, "unit": "pack of 100g"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.24, "unit": "bottle of 250ml"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_chinese_five_spice", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_chilli", "quantity": {"value": 0.225, "unit": "pack of 100g"}}, {"id": "ing_chicken", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_pork_mince", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_sui_mi_ya_cai", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_stems_choy_sum", "quantity": {"value": 16.0, "unit": "unit"}}, {"id": "ing_green_onion", "quantity": {"value": 0.04, "unit": "bunch"}}, {"id": "ing_peanuts", "quantity": {"value": 0.037, "unit": "jar"}}]', '[{"ingredients":["2 tbsp Chinese sesame paste (sub tahini, Note 1)","1.5 tbsp Chinese chilli paste in oil (, adjust spiciness (Note 2))","4 tbsp light soy sauce (Note 3)","2 garlic cloves (, minced)","3 tsp white sugar","1/2 tsp Chinese five spice powder (Note 4)","1 tsp Sichuan pepper powder (, preferably freshly ground (Note 5))","3 tbsp (or more!) chilli oil (, preferably Chinese (Note 6))","3/4 cup (185ml) chicken broth/stock (, hot, low sodium)"],"purpose":"Dan Dan Sauce:"},{"ingredients":["2 tsp Hoisin sauce","1 tsp dark soy sauce (Note 7)","1 tbsp Chinese cooking wine (sub 2 tbsp extra chicken stock)","1/2 tsp Chinese five spice powder (Note 4)","1 tbsp vegetable oil","250g/ 8oz pork mince (ground pork)"],"purpose":"Pork topping:"},{"ingredients":["1 tsp vegetable oil","30g (1/4 cup) Sui Mi Ya Cai (preserved mustard greens) (, finely chopped (Note 8))"],"purpose":"Sui mi ya cai (preserved mustard greens):"},{"ingredients":["500g/1lb white fresh noodles (, medium thickness (Note 9))","16 choy sum stems (, cut into 15cm pieces)","2 green onions (, finely sliced)","1 tbsp peanuts (, finely chopped (optional))"],"purpose":"To serve:"}]', '[{"description":"Mix all ingredients except oil and chicken stock. Then gently stir in oil and stock - oil should be sitting on surface. Set aside.","images":[],"step":1},{"description":"Mix together hoisin, soy, Chinese wine and five spice (\"Sauce\").","images":[],"step":2},{"description":"Heat oil in a skillet or wok over high heat. Add pork and cook, breaking it up as you, until it changes from pink to white. Add Sauce and cook for 1 minute, then transfer into a bowl.","duration":1,"images":[],"step":3},{"description":"Sui mi ya cai (preserved mustard greens):","images":[],"step":4},{"description":"Return skillet to stove, reduce to medium heat. Add oil into middle of skillet.","images":[],"step":5},{"description":"Add Sui mi ya cai and stir for 30 seconds, just to warm through. Set aside.","duration":0.5,"images":[],"step":6},{"description":"Noodles & choi sum:","images":[],"step":7},{"description":"Bring a large pot of water to the boil. Cook noodles per packet directions.","images":[],"step":8},{"description":"Add choi sum for last 1 minute of cooking.","images":[],"step":9},{"description":"Ladle 1/4 of Dan Dan Sauce into a bowl. Pile in noodles, top with pork and Sui mi ya cai. Place choi sum on side.","images":[],"step":10},{"description":"Sprinkle with peanuts and green onions and serve.","images":[],"step":11},{"description":"To eat, mix it all up to coat the noodles well with Sauce, then devour!","images":[],"step":12}]', '["gluten","mustard","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["American Chinese","Sichuan","Szechuan"],"categories":["asian-recipes","chinese-recipes","iconic-dishes","modern-asian","noodles"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4a39a35780f5', 'en', 'US', 'Thai Lettuce Wraps (Larb Gai, Laab Gai)', 'Recipe video above. This is a really authentic recipe for Thai Lettuce Wraps (Larb Gai). It is super fast to make, incredibly fresh but full of fragrance and a hit of spice.', 'https://www.recipetineats.com/tachyon/2015/01/Thai-Lettuce-Wraps_Larb-Gai_0.jpg', 10, 10, 20, 2, '[{"id": "ing_cornstarch", "quantity": {"value": 0.025, "unit": "pack of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_ime_juice", "quantity": {"value": 2.5, "unit": "unit"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_chilli", "quantity": {"value": 2.0, "unit": "pack of 100g"}}, {"id": "ing_chicken_mince", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_mint", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_peanuts", "quantity": {"value": 0.113, "unit": "jar"}}, {"id": "ing_lettuce", "quantity": {"value": 6.0, "unit": "head"}}, {"id": "ing_chilli", "quantity": {"value": 2.0, "unit": "pack of 100g"}}]', '[{"ingredients":["2 tsp cornflour / cornstarch (OR 2 tbsp uncooked rice (any rice is fine) (Note 1))","3 tbsp water","2 1/2 tbsp lime juice (1 to 2 limes)","2 tbsp fish sauce","2 tsp brown sugar","2 tbsp peanut oil (or other high smoke point cooking oil)","1 tbsp fresh ginger (, grated or very finely chopped)","2 garlic cloves (, large, minced)","1 lemon grass stalk (, white and very pale green part only, finely chopped (Note 2))","2 Thai or birds eye chilli (, deseeded and finely chopped (adjust to taste))","1 lb / 500g chicken mince ((ground chicken) OR pork)","1/2 red onion (, cut into 4 wedges then finely sliced)","1/3 cup coriander/cilantro leaves (, plus extra to garnish)","1/3 cup mint leaves (, plus extra to garnish)"]},{"ingredients":["3 tbsp crushed peanuts (optional)","6 - 8 small to medium lettuce leaves (I used baby cos / romaine) (Note 3)","Extra lime wedges, chilli"],"purpose":"Serving"}]', '[{"title":"Sauce","description":"Place water and cornflour OR rice powder into a small bowl. Mix into a slurry. Add lime juice, fish sauce and sugar and mix to combine. Set aside.","images":[],"step":1},{"description":"Heat peanut oil in a wok (or heavy based fry pan) over medium high heat. Add ginger, garlic, lemongrass and chilli and sauté for 45 seconds to 1 minute until fragrant. Do not let the garlic burn, it will taste bitter.","duration":0.75,"images":[],"step":2},{"description":"Add the chicken and turn up the heat to high. Cook the chicken, breaking up the mince into small pieces.","images":[],"step":3},{"description":"Once the chicken turns white and is almost cooked through (about 3 to 4 minutes), add Sauce. Cook for 45 seconds to 1 minute to coat the chicken and for the sauce to thicken.","duration":0.75,"images":[],"step":4},{"description":"Remove wok from heat. Stir through onion, coriander/cilantro and mint.","images":[],"step":5},{"description":"Spoon filling into a bowl, and serve with lettuce, peanuts, extra herbs and lime wedges on the side - leave everyone to make their own. Spoon filling into lettuce cups and garnish with what you want!","images":[],"step":6},{"title":"Sauce option","description":"Take it over the top by serving with Thai Peanut Satay Sauce, as pictured in the first photo in post! It''s extra amazing (though not traditional!)","images":[],"step":7}]', '["fish","peanuts"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["asian-recipes","asian-takeout","chicken-mince-recipes","chicken-recipes","cuisines","dietary","dinner-tonight","gluten-free-recipes","low-calorie-recipes","main-dishes","modern-asian","most-popular","quick-and-easy","stir-fries","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0a43dbd28272', 'en', 'US', 'Saucy Vegetable Stir Fry', 'Recipe video above. Any vegetables are totally scoffable when they''re smothered in a tasty Chinese gravy! Use any veg you want - just add them according to the cook time (hard veg in first, leafy veg in last). For a quick hit of protein, toss in some cubes of firm tofu. For a chicken version, use this Chicken Stir Fry. Recipe works with Charlie - see Note 4.', 'https://www.recipetineats.com/tachyon/2020/01/Vegetable-Stir-Fry_9.jpg', 10, 5, 15, 4, '[{"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_buk_choy", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_mushroom", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1 tbsp vegetable oil","2 garlic cloves (, finely chopped)","1 tbsp ginger (, finely sliced (optional))","1/2 onion (, peeled and sliced)","1 carrot (, large)","3 medium buk choy ( or other leafy greens of choice (Note 1))","1 cup mushrooms (, sliced 3mm / 1/8\" thick)","1 capsicum (, sliced 1/2cm / 1/5\" thick)"]},{"ingredients":["1 tbsp cornflour / corn starch","1 1/2 tbsp soy sauce (, light or all purpose (not dark soy) (Note 2))","2 tsp Oyster Sauce","1 tbsp Chinese Cooking Wine or Mirin (Note 3)","1/2 tsp sesame oil (optional)","Dash of white pepper (or black)","3/4 cup / 185 ml water"],"purpose":"Sauce (or use 4 tbsp Charlie, Note 4):"},{"ingredients":["Finely sliced green onions","Sesame seeds"],"purpose":"Garnishes, optional:"}]', '[{"description":"Vegetable Prep:","images":[],"step":1},{"title":"Carrot","description":"cut in half lengthwise then diagonally sliced 2mm / 1/10\" thick","images":[],"step":2},{"title":"Buk Choy (Note 1)","description":"Trim base off, then cut leaves off the stem. Cut the stem lengthwise into 1cm / 2/5\" wide pieces. Keep leaves separate from stems, they will be cooked at different times.","images":[],"step":3},{"title":"Sauce (Charlie","description":"Note 4):","images":[],"step":4},{"description":"Place cornflour and soy sauce in a bowl and mix until cornflour is dissolved, then mix in remaining Sauce ingredients.","images":[],"step":5},{"description":"Cooking:","images":[],"step":6},{"description":"Heat oil in a wok or large heavy based skillet over high heat.","images":[],"step":7},{"description":"Add garlic and ginger, stir for 10 seconds. Add onion, stir for 30 seconds.","duration":0.16666666666666666,"images":[],"step":8},{"title":"Add carrot, capsicum and stems of buk choy","description":"stir for 1 minute.","duration":1,"images":[],"step":9},{"description":"Add mushrooms, then stir for 2 to 3 minutes until the vegetables are almost cooked.","duration":2.5,"images":[],"step":10},{"description":"Add Sauce and toss for 1 minute until Sauce thickens and becomes glossy, coating all the vegetables. Don''t overcook so they become floppy and limp - they should be just cooked, \"crisp tender\".","duration":1,"images":[],"step":11},{"description":"Remove from stove and serve over rice (low carb option: cauliflower rice). Garnish with green onions and sesame seeds if using. A big dollop of chilli sauce wouldn''t go astray either!","images":[],"step":12}]', '["gluten","sesame","soy"]', '["low_calorie","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-greens","asian-recipes","asian-takeout","chinese-recipes","dietary","gluten-free-recipes","low-calorie-recipes","mains","quick-and-easy","side-dishes","stir-fries","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_43bd74ad9828', 'en', 'US', 'Vietnamese Pho recipe', 'Recipe video above. Experience the magic of one of the greatest soups in the world with this easy to follow traditional recipe! The depth of flavour in the broth will blow you away - it looks so clear and light but it''s packed with flavour.Getting enough flavour and light-richness into the soup broth calls for the right combination of meat AND bones. You can''t just use bones (even really meaty ones), the soup just lacks flavour. I tried multiple times. Use the leftover cooked brisket to make Caramelised Vietnamese Pulled Beef (it''s so good!) and see in post for more ways to use it.Next time - try Chicken Pho! It''s amazing, and quicker to make. :)', 'https://www.recipetineats.com/tachyon/2019/04/Beef-Pho_6.jpg', 20, 180, 200, 6, '[{"id": "ing_onion", "quantity": {"value": 2000.0, "unit": "pack of 1kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_star_anise", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_cinnamon_quill", "quantity": {"value": 4.0, "unit": "jar"}}, {"id": "ing_cardamon_pods", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_beef_brisket", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_marrow_bones_cut_to_reveal_marrow", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 3.5, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.04, "unit": "kg"}}, {"id": "ing_rice", "quantity": {"value": 50.0, "unit": "pack"}}, {"id": "ing_beef", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_brisket_slices", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_beansprouts_handful", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_sriracha", "quantity": {"value": 1.0, "unit": "bottle of 400ml"}}]', '[{"ingredients":["2 large onions (, halved)","150g / 5oz ginger (, sliced down the centre)"],"purpose":"Aromatics:"},{"ingredients":["10 star anise","4 cinnamon quills","4 cardamon pods","3 cloves (the spice cloves!)","1.5 tbsp coriander seeds"],"purpose":"Spices"},{"ingredients":["1.5kg / 3lb beef brisket","1kg / 2lb meaty beef bones","1kg / 2lb marrow bones ((leg, knuckle), cut to reveal marrow)","3.5 litres / 3.75 quarts water (15 cups)"],"purpose":"Beef bones (Note 1):"},{"ingredients":["2 tbsp white sugar","1 tbsp salt","40 ml / 3 tbsp fish sauce (Note 2)"],"purpose":"Seasoning:"},{"ingredients":["50g / 1.5 oz dried rice sticks (or 120g/4oz fresh) (Note 3)","30g / 1 oz beef tenderloin, raw, very thinly sliced (Note 4)","3 - 5 brisket slices (used for broth)"],"purpose":"Noodle Soup – PER BOWL:"},{"ingredients":["Beansprouts, handful","Thai basil, 3 - 5 sprigs","Coriander/cilantro, 3 - 5 sprigs (or more basil)","Lime wedges*","Finely sliced red chilli*","Hoisin sauce*","Sriracha* (for spiciness)"],"purpose":"Toppings:"}]', '[{"description":"Heat a heavy based skillet over high heat (no oil) until smoking.","images":[],"step":1},{"description":"Place onion and ginger in pan cut side down. Cook for a few minutes until it''s charred, then turn. Remove and set aside.","images":[],"step":2},{"description":"Toast Spices lightly in a dry skillet over medium high heat for 3 minutes.","duration":3,"images":[],"step":3},{"description":"Remove impurities:","images":[],"step":4},{"description":"Rinse bones & brisket then cover with water in large stock pot.","images":[],"step":5},{"description":"Boil for 5 minutes, then drain.","duration":5,"images":[],"step":6},{"description":"Rinse each bone and brisket under tap water.","images":[],"step":7},{"description":"Wipe pot clean, bring 3.5 litres / 3.75 quarts water to boil.","images":[],"step":8},{"description":"Add bones and brisket, onion, ginger, Spices","images":[],"step":9},{"title":"Add onion, ginger, Spices, sugar and salt","description":"water should just barely cover everything.","images":[],"step":10},{"description":"Cover with lid, simmer 3 hours.","images":[],"step":11},{"description":"Remove brisket (should be fall-apart tender), cool then refrigerate for later.","images":[],"step":12},{"description":"Simmer remaining soup UNCOVERED for 40 minutes.","duration":40,"images":[],"step":13},{"description":"Strain broth into another pot, discard bones and spices. Should be about 2.5 litres / 2.65 quarts (10 cups), if loads more, reduce.","images":[],"step":14},{"description":"Add fish sauce, adjust salt and sugar if needed. Broth should be beefy, fragrant with spices, savoury and barely sweet.","images":[],"step":15},{"description":"Prepare rice noodles per packet, just prior to serving.","images":[],"step":16},{"description":"Place noodles in bowl. Top with raw beef and brisket.","images":[],"step":17},{"title":"Ladle over about 400 / 14 oz hot broth","description":"will cook beef to medium rare.","images":[],"step":18},{"description":"Serve with Toppings on the side!","images":[],"step":19}]', '["fish"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Vietnamese"],"categories":["asian-recipes","asian-soups","beef-recipes","iconic-dishes","soup-recipes","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a0e0746cfb8d', 'en', 'US', 'Pad Thai', 'Recipe video above. Here''s a Pad Thai recipe that really does taste just as good as takeout from good Thai restaurants, and you''ll find everything you need at the supermarket! I use chicken here but feel free to switch with any protein, even prawns/shrimp. If you''re after a truly authentic Pad Thai recipe, see here - but be warned that most people will find it a little too "real" for their palettes because Pad Thai in Thailand has stronger fish sauce/dried shrimp "funk". (Don''t misread that word! :))', 'https://www.recipetineats.com/tachyon/2018/05/Chicken-Pad-Thai_9.jpg', 20, 10, 30, 2, '[{"id": "ing_rice", "quantity": {"value": 125.0, "unit": "pack"}}, {"id": "ing_tamarind_puree", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_oil", "quantity": {"value": 2.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_beansprouts", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_tofu", "quantity": {"value": 0.25, "unit": "pack of 300g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_peanuts", "quantity": {"value": 0.094, "unit": "jar"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_more_beansprouts", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["125 g / 4oz Chang''s Pad Thai dried rice sticks (Note 1)"]},{"ingredients":["1 1/2 tbsp tamarind puree (, NOT concentrate (Note 2))","3 tbsp (packed) brown sugar","2 tbsp fish sauce (Note 3)","1 1/2 tbsp oyster sauce (Note 4)"],"purpose":"Sauce:"},{"ingredients":["2 - 3 tbsp vegetable or canola oil","1/2 onion (, sliced (brown, yellow))","2 garlic cloves (, finely chopped)","150 g/5oz chicken breast (or thigh) (, thinly sliced)","2 eggs (, lightly whisked)","1 1/2 cups of beansprouts","1/2 cup firm tofu, cut into 3cm / 1 1/4\" batons (see photo)","1/4 cup garlic chives , cut into 3cm / 1 1/4\" pieces","1/4 cup finely chopped peanuts"],"purpose":"Stir Fry:"},{"ingredients":["Lime wedges (essential)","Ground chilli or cayenne pepper (optional)","More beansprouts"],"purpose":"For serving:"}]', '[{"description":"Place noodles in a large bowl, pour over plenty of boiling water. Soak for 5 minutes, then drain in a colander and quickly rinse under cold water. Don''t leave them sitting around for more than 5 - 10 minutes.","duration":5,"images":[],"step":1},{"description":"Mix Sauce in small bowl.","images":[],"step":2},{"description":"Heat 2 tbsp oil in a large non stick pan (or well seasoned skillet) over high heat. Add garlic and onion, cook for 30 seconds.","duration":0.5,"images":[],"step":3},{"description":"Add chicken and cook for 1 1/2 minutes until mostly cooked through.","images":[],"step":4},{"description":"Push to one side of the pan, pour egg in on the other side. Scramble using the wooden spoon (add touch of extra oil if pan is too dry), then mix into chicken.","images":[],"step":5},{"description":"Add bean sprouts, tofu, noodles then Sauce.","images":[],"step":6},{"description":"Toss gently for about 1 1/2 minutes until Sauce is absorbed by the noodles.","images":[],"step":7},{"description":"Add garlic chives and half the peanuts. Toss through quickly then remove from heat.","images":[],"step":8},{"description":"Serve immediately, sprinkled with remaining peanuts and lime wedges on the side, with a sprinkle of chilli and a handful of extra beansprouts on the side if desired (this is the Thai way!). Squeeze over lime juice to taste before eating.","images":[],"step":9}]', '["egg","fish","gluten","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-recipes","cuisines","noodles","quick-and-easy","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_88ed38ea95b9', 'en', 'US', 'Filipino Chicken Adobo (Flavour Kapow!)', 'Recipe video above. One of the most amazing Asian chicken thigh recipes I have ever come across. Intense in flavour, but so fast and easy to prepare! The chicken is so tender, it eats like it''s been slow-cooked.', 'https://www.recipetineats.com/tachyon/2015/02/Filipino-Chicken-Adobo_6.jpg', 10, 35, 45, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.333, "unit": "bottle of 250ml"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_bay_leaf", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_water", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.3, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.04, "unit": "bunch"}}]', '[{"ingredients":["750g / 1.5 lb chicken thigh fillets (, boneless and skinless (5 - 6 pieces) (Note 1))","3 garlic cloves (, minced)","1/3 cup (85ml) soy sauce (, ordinary all purpose or light (not dark soy sauce, Note 2))","1/3 cup + 2 tbsp white vinegar (, see Note 3)","4 bay leaves (fresh) or 3 dried"],"purpose":"Chicken and Marinade"},{"ingredients":["2 tbsp oil (, separated (vegetable, canola or peanut))","3 garlic cloves (, minced)","1 small brown onion (, diced)","1 1/2 cups (375 ml) water","2 tbsp brown sugar","1 tbsp whole black pepper (sub 2 tsp coarse cracked pepper)"],"purpose":"For cooking"},{"ingredients":["2 green onions/scallions (, sliced (garnish))"],"purpose":"Serving:"}]', '[{"description":"Combine Chicken and Marinade ingredients in a bowl. Marinate for at least 20 minutes, or up to overnight.","images":[],"step":1},{"description":"Heat 1 tbsp oil in a skillet over high heat. Remove chicken from marinade (reserve marinade) and place in the pan. Sear both sides until browned – about 1 minute on each side. Do not cook the chicken all the way through.","images":[],"step":2},{"description":"Remove chicken skillet and set aside.","images":[],"step":3},{"description":"Heat the remaining oil in skillet. Add garlic and onion, cook 1 1/2 minutes.","images":[],"step":4},{"description":"Add the reserved marinade, water, sugar and black pepper. Bring it to a simmer then turn heat down to medium high. Simmer 5 minutes.","images":[],"step":5},{"description":"Add chicken smooth side down. Simmer uncovered for 20 to 25 minutes (no need to stir), turning chicken at around 15 minutes, until the sauce reduces down to a thick jam-like syrup.","duration":22.5,"images":[],"step":6},{"description":"If the sauce isn''t thick enough, remove chicken onto a plate and let the sauce simmer by itself - it will thicken much quicker - then return chicken to the skillet to coat in the glaze.","images":[],"step":7},{"description":"Coat chicken in glaze then serve over rice. Pictured in post as a healthy dinner plate (415 calories) with cauliflower rice and Ginger Smashed Cucumbers.","images":[],"step":8}]', '["gluten","peanuts","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Filipino"],"categories":["asian-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","low-calorie-recipes","main-dishes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a24a8884f9ef', 'en', 'US', 'Lo Mein Noodles', 'Recipe video above. If you want lip smackingly delicious Lo Mein noodles just like takeout, you just need to get the SAUCE right! The noodle part is easy - you can literally use any noodles, even pasta (yep, seriously). Also, switch out the vegetables with 5 cups (packed) of any chopped vegetables of choice.', 'https://www.recipetineats.com/tachyon/2019/11/Lo-Mein_5.jpg', 8, 7, 15, 3, '[{"id": "ing_oil", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 6.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.12, "unit": "bunch"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.05, "unit": "pack of 400g"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 20.0, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.12, "unit": "bunch"}}]', '[{"ingredients":["1.5 tbsp vegetable or peanut oil","2 garlic cloves (, finely minced (Note 1))","1/2 onion (, finely sliced)","300g / 10oz chicken or other protein (, sliced 0.5cm / 1/5\" thick (Note 2))","2 medium carrots (, peeled and cut into 4 x 0.75cm / 1.75 x 1/3\" batons)","1 large red capsicum / bell pepper (, sliced (or 2 small))","6 green onions (, cut into 5 cm/2” lengths)","500g / 1lb Lo Mein, Hokkien or other medium thickness egg noodles, fresh, (, prepared per packet (Note 3 for dried))","1/4 cup (65ml) water"]},{"ingredients":["4 tsp cornflour / cornstarch","2 tbsp dark soy sauce (Note 4)","2 tbsp soy sauce or light soy sauce ( (Note 4))","1 tbsp Chinese cooking wine or Mirin (Note 5 subs)","1 tsp white sugar (omit if using Mirin)","1/2 tsp sesame oil (, toasted, optional (Note 6))","1/4 tsp white pepper (sub black)"],"purpose":"Sauce:"},{"ingredients":["Green onion (, finely sliced)"],"purpose":"Garnish (optional):"}]', '[{"title":"Sauce","description":"Mix cornflour and dark soy until lump free, then add remaining Sauce ingredients.","images":[],"step":1},{"title":"Season Chicken","description":"Transfer 2 tsp Sauce into bowl with chicken. Toss to coat.","images":[],"step":2},{"description":"Heat oil in a wok or large heavy based skillet over high heat until smoking.","images":[],"step":3},{"description":"Add onion and garlic, stir 30 seconds.","images":[],"step":4},{"description":"Add chicken, stir until white on the outside, still raw inside - 1 minute.","images":[],"step":5},{"description":"Add carrot and capsicum/bell peppers, cook 2 minutes or until chicken is cooked.","images":[],"step":6},{"description":"Add noodles, Sauce and water. Use 2 wooden spoons and toss for 30 seconds.","duration":0.5,"images":[],"step":7},{"description":"Add green onions, toss for another 1 minute until all the noodles are slick with sauce.","images":[],"step":8},{"description":"Serve immediately, garnished with extra green onions if using.","images":[],"step":9}]', '["egg","gluten","peanuts","sesame","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["American Chinese","Asian","Chinese"],"categories":["asian-recipes","asian-takeout","chinese-recipes","dinner-tonight","main-dishes","noodles","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_eeb67fe4e806', 'en', 'US', 'Chow Mein', 'Recipe video above. A great Chow Mein that truly rivals Chinese restaurants comes down to the sauce! Make this with your protein of choice (Note 1). Have all the ingredients ready to go before you start cooking because it''s done in 5 minutes!', 'https://www.recipetineats.com/tachyon/2018/08/Chow-Mein_1.jpg', 10, 5, 15, 2, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_cabbage", "quantity": {"value": 12.0, "unit": "head"}}, {"id": "ing_oil", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.4, "unit": "pack of 500g"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 1.5, "unit": "bag of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.06, "unit": "bunch"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.025, "unit": "pack of 400g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.045, "unit": "bottle of 500ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["200g /6 oz chicken breast or thigh fillets (, thinly sliced (Note 1 tenderise option))","4 cups green cabbage (, finely shredded (Note 3))","1 1/2 tbsp peanut oil (or other cooking oil)","2 cloves garlic (, finely chopped)","200g /6 oz chow mein noodles (Note 2)","1 carrot (, julienned)","1 1/2 cups bean sprouts","3 green onions (, cut into 5cm/2\" pieces)","1/4 cup (65 ml) water"]},{"ingredients":["2 tsp cornflour / cornstarch","1 1/2 tbsp soy sauce (, all purpose or light (Note 4))","1 1/2 tbsp oyster sauce (sub Hoisin)","1 1/2 tbsp Chinese cooking wine (OR Mirin (Note 5))","2 tsp sugar (reduce to 1 tsp if using Mirin)","1/2 tsp sesame oil","White pepper (sub black)"],"purpose":"Chow Mein Sauce:"}]', '[{"description":"Mix together cornflour and soy sauce, then mix in remaining ingredients.","images":[],"step":1},{"title":"Alternative","description":"Use 1/3 cup Chinese All Purpose Stir Fry Sauce, if you have some in stock.","images":[],"step":2},{"description":"Chicken & Noodles","images":[],"step":3},{"title":"Marinate Chicken","description":"Pour 1 tbsp of Sauce over the chicken, mix to coat, set aside to marinate for 10 minutes.","duration":10,"images":[],"step":4},{"title":"Noodles","description":"Prepare the noodles according to the packet instructions (my pack says soak in boiled water for 1 minute), then drain.","duration":1,"images":[],"step":5},{"description":"Cooking:","images":[],"step":6},{"description":"Heat oil in wok or large fry pan over high heat.","images":[],"step":7},{"description":"Add garlic and stir fry for 10 seconds or until it starts to turn golden - don''t let it burn!","duration":0.16666666666666666,"images":[],"step":8},{"description":"Add chicken and stir fry until the surface gets a tinge of browning but inside is still raw - about 1 minute.","images":[],"step":9},{"description":"Add the cabbage, carrot, and the white pieces of shallots (i.e. from the base of the stalk). Stir fry for 1 1/2 minutes until the cabbage is mostly wilted.","images":[],"step":10},{"description":"Add the noodles, Sauce and water*. Stir fry for 1 minute, tossing constantly.","duration":1,"images":[],"step":11},{"description":"Add bean sprouts and remaining shallots/scallions. Toss through for 30 seconds or until the bean sprouts just start to wilt.","duration":0.5,"images":[],"step":12},{"description":"Remove from heat and serve immediately.","images":[],"step":13}]', '["gluten","peanuts","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-recipes","chinese-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","most-popular","noodles","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a47f4ce5f371', 'en', 'US', 'Vietnamese Noodles with Lemongrass Chicken', 'Recipe video above. This Vietnamese lemongrass marinade is exceptional - you''ll absolutely love it! This is one of my siganture recipes - it''s as delicious as it is healthy, ideal for making ahead, for midweek meals and a cheap (impressive) meal idea for large groups. DON''T BE DAUNTED by the list of ingredients - the ingredients for the marinade and sauce are largely the same!', 'https://www.recipetineats.com/tachyon/2017/01/Vietnamese-Noodles-with-Lemongrass-Chicken_7.jpg', 20, 10, 30, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 600.0, "unit": "kg"}}, {"id": "ing_lemongrass", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 600.0, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.24, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.4, "unit": "pack of 500g"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_lettuce", "quantity": {"value": 15.0, "unit": "head"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 3.0, "unit": "bag of 250g"}}, {"id": "ing_mint", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}]', '[{"ingredients":["600 - 800g / 1.2 - 1.6lb chicken thigh fillets (, skinless and boneless or breast (or pork, beef or any seafood))","1 stalk lemongrass (, white part only, bruised them sliced into pieces easy to pick out later (Note 1))","2 garlic cloves (, finely chopped or minced)","2 tbsp lime juice","2 tbsp fish sauce (Note 2)","1 tbsp soy sauce (all purpose or light, NOT dark soy)","2 tbsp brown sugar","1 tbsp vegetable oil"],"purpose":"Chicken and Marinade"},{"ingredients":["1/4 cup fish sauce (Note 3)","4 tbsp rice vinegar","2 tbsp white sugar","1/2 cup water","2 garlic cloves (, finely chopped)","1 red birds eye chilli (, finely chopped (Note 4))","3 tbsp lime juice"],"purpose":"Nuoc Cham (Vietnamese Sauce)"},{"ingredients":["1/2 tbsp oil","200 g / 7 oz vermicelli noodles (, dried)","2 carrots (, julienned)","2 cucumbers (, julienned (optional: remove seeds))","5 cups iceberg lettuce (, finely sliced)","3 cups bean sprouts","Handful of mint leaves","Handful of cilantro/coriander","Sliced red chilli (for garnish - optional)","Lime wedges (to serve - optional but recommended)"],"purpose":"Noodle Bowl"}]', '[{"description":"Lemongrass Chicken","images":[],"step":1},{"description":"Combine Chicken and Marinade ingredients and set aside for at least 1 hour, up to 24 hours. (Note 4)","images":[],"step":2},{"description":"Heat 1/2 tbsp oil in a fry pan over medium heat (or heat the BBQ). Remove chicken from marinade, shaking off large bits of lemongrass (small bits should fall off during cooking).","images":[],"step":3},{"description":"Place chicken in the pan and cook each side until dark golden brown and chicken is just cooked through - about 6 to 8 minutes in total.","images":[],"step":4},{"description":"Remove from pan, shaking off any remaining bits of visible lemongrass and set aside to rest for 5 minutes. Then slice into thin pieces.","duration":5,"images":[],"step":5},{"description":"Nuoc Cham Sauce","images":[],"step":6},{"description":"Combine the Nuoc Cham ingredients and mix well to dissolve the sugar. Adjust to your taste (spiciness, lime, sweetness) and set aside for at least 20 minutes.","images":[],"step":7},{"description":"Soak the vermicelli noodles in hot water for 3 minutes (or according to packet instructions), then drain and rinse under cold water to stop the noodles from sticking together.","duration":3,"images":[],"step":8},{"title":"Individual servings","description":"Place noodles in bowl. Top with vegetables and herbs, and sliced chicken pieces. Drizzle with a few tablespoons of Nuoc Cham Sauce (be generous, ~ 4 tbsp per serving) and serve with lime wedges.","images":[],"step":9},{"title":"DIY (my preferred way)","description":"Place chicken, vegetables, herbs, noodles and sauce in separate bowls / piled on platters. Then let everyone make their own bowls!","images":[],"step":10}]', '["fish","gluten","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Vietnamese"],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","dietary","gluten-free-recipes","grilling-ideas-and-recipes","low-calorie-recipes","most-popular","noodles","quick-and-easy","salad-recipes-main-course","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_69ddfa114ba2', 'en', 'US', 'Chicken Fried Rice', 'Recipe video above. A fully loaded, completely delicious Chicken Fried Rice! Serve it as a side - or have it as a main! (See here for a classic side dish Fried Rice).', 'https://www.recipetineats.com/tachyon/2019/09/Chicken-fried-rice-copy.jpg', 10, 10, 20, 4, '[{"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 112.5, "unit": "pack of 1kg"}}, {"id": "ing_bacon", "quantity": {"value": 0.6, "unit": "pack of 200g"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_corn", "quantity": {"value": 0.188, "unit": "can of 400g"}}, {"id": "ing_frozen_peas", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_white_rice", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 2.25, "unit": "bunch"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.075, "unit": "bottle of 500ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["2 tbsp oil (, peanut, vegetable or canola)","2 eggs (, lightly whisked)","150g (5oz) chicken breast (, finely sliced into small pieces)","2 garlic cloves (, minced)","1/2 onion (, finely chopped)","120g (4oz) bacon (, excess fat trimmed, chopped (Note 1))","1 small carrot* (, peeled and diced 0.75cm / 1/3\")","1/2 cup frozen corn* (or can or fresh)","1/2 cup frozen peas*","2 cups (packed) cooked white rice (, day old (Note 2))","3/4 cup green onions (, finely sliced)"]},{"ingredients":["2.5 tbsp Chinese cooking wine or Mirin (Note 3)","1 tbsp oyster sauce (Note 4)","3 tbsp light soy sauce (Note 5)","1/2 tsp sesame oil (, optional)","1/4 tsp white pepper (, optional)"],"purpose":"SAUCE:"}]', '[{"title":"Sauce & chicken","description":"Mix Sauce in a bowl. Pour 2 tsp over chicken, toss to coat, then set aside for 10 minutes.","duration":10,"images":[],"step":1},{"title":"Egg","description":"Heat 1 tbsp oil in a wok or skillet over medium heat. Add egg and scramble until just cooked (still a touch wet) then remove.","images":[],"step":2},{"title":"Fried Rice","description":"Turn heat up to high, add remaining 1/2 tbsp oil and bacon into same skillet. Cook for 1 minute or so until fat starts to melt, then add onion and garlic.","duration":1,"images":[],"step":3},{"title":"Cook until bacon is light golden","description":"about 1 1/2 minutes.","images":[],"step":4},{"description":"Add vegetables (still frozen is fine). Cook for 1 minute.","duration":1,"images":[],"step":5},{"description":"Add chicken and cook until it changes from pink to white - about 1 1/2 minutes.","images":[],"step":6},{"description":"Add rice and Sauce ingredients. Cook for 1 1/2 minutes, stirring consantly.","images":[],"step":7},{"description":"Add egg and green onion, toss through to disperse then remove from heat.","images":[],"step":8},{"description":"Serve immediately!","images":[],"step":9}]', '["egg","gluten","peanuts","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","chinese-recipes","fried-rice","quick-and-easy","rice-recipes","rice-side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8a9efba3e783', 'en', 'US', 'How to cook rice - perfectly and easily', 'Recipe video above. Use this recipe for short, medium and long grain white rice. See separate recipes for: jasmine, basmati and brown rice.Stovetop yields the best result for perfect, evenly cooked fluffy rice. This is my default, favourite method. Oven is best for large batch as it cooks more evenly than on the stove (we use the oven at RecipeTin Meals). The microwave method is handy to know because it''s fastest!DO NOT RINSE your rice, you do not need to rinse for fluffy rice (read in post for more information). Exception: if you are concerned about cleanness (eg purchased from sacks at markets). If you rinse your rice, reduce the water by 2 tablespoons per 1 cup of rice (to account for waterlogged rice) else your rice will be overly soft and a bit mushy.', 'https://www.recipetineats.com/tachyon/2019/10/How-to-cook-rice-featured-image.jpg', 1, 13, 24, 3, '[{"id": "ing_white_rice", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_white_rice", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.375, "unit": "L"}}]', '[{"ingredients":["1 cup white rice (- short, medium or long grain, uncooked (Note 1))","1 1/2 cups water"],"purpose":"Stovetop (my default method):"},{"ingredients":["2 cups white rice (- short, medium or long grain (Note 1, 2))","3 cups boiling water (Note 3)"],"purpose":"Oven:"},{"ingredients":["1 cup white rice (- short, medium or long grain (Note 1))","2 cups boiling water (Note 3)"],"purpose":"Microwave:"}]', '[{"description":"Before you start:","images":[],"step":1},{"title":"Check rice type","description":"This recipe is for the following white rice types: long grain, medium grain, short grain (excluding sushi rice). See separate recipes for: basmati, jasmin and brown rice.","images":[],"step":2},{"description":"DO NOT RINSE your rice (read intro above for why).","images":[],"step":3},{"description":"Stovetop (my default):","images":[],"step":4},{"title":"Bring to simmer","description":"Place water and rice in a large saucepan over medium high heat. Once the entire surface of the water is bubbling gently(and it gets a bit foamy, see video), turn heat down to low and cover with lid.","images":[],"step":5},{"title":"Cook 13 minutes","description":"Cook for 13 minutes. Do not stir, do not remove lid. Water should now all be absorbed - tilt to check.","duration":13,"images":[],"step":6},{"title":"Rest","description":"Remove from stove, still with lid, and leave for 10 minutes.","duration":10,"images":[],"step":7},{"title":"Fluff","description":"Remove lid, fluff with rice paddle or fork, and serve!","images":[],"step":8},{"description":"Preheat oven to 200°C/390°F (180°C fan forced).","images":[],"step":9},{"title":"Pot","description":"Use a small casserole pot about 24cm/10\" wide with a lid. (Note 4)","images":[],"step":10},{"title":"Bake 35 minutes","description":"Place boiling water and rice in pot, cover with lid and bake for 35 minutes.","duration":35,"images":[],"step":11},{"title":"Rest & fluff","description":"Remove from oven, and leave for 10 minutes with the lid still on. Remove lid, fluff with rice paddle or fork, and serve! (Makes 6 cups)","duration":10,"images":[],"step":12},{"description":"Place rice and boiling water in tall microwave proof container (Note 5).","images":[],"step":13},{"description":"Microwave on high for 12 minutes with NO LID (1100 - 1200W microwaves).","duration":12,"images":[],"step":14},{"title":"Rest & fluff","description":"Remove, cover with lid, leave for 10 minutes. Remove lid, fluff with rice paddle or fork, and serve!","duration":10,"images":[],"step":15}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["American Chinese","Asian","Chinese","Western"],"categories":["asian-recipes","chinese-recipes","good-to-know","quick-and-easy","rice","rice-recipes","rice-side-dishes","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e1d3b895634b', 'en', 'US', 'Tom Yum Soup (Thai Soup)', 'Recipe video above! The famous Thai Soup, made at home, and it''s honestly the real deal!! See recipe notes for shortcut using frozen peeled prawns/shrimp. Also, CHOOSE from classic clear Tom Yum (Tom Yum Goong Nam Sa) or the creamy Tom Yum version (Tom Yum Goong Nam Khon)!', 'https://www.recipetineats.com/tachyon/2019/09/Tom-Yum-soup_2.jpg', 15, 20, 35, 2, '[{"id": "ing_shrimp", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_lemongrass", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_galangal", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_lime", "quantity": {"value": 5.0, "unit": "net of 500g"}}, {"id": "ing_chilli", "quantity": {"value": 2.0, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_oyster_mushrooms", "quantity": {"value": 0.8, "unit": "pack of 150g"}}, {"id": "ing_tomato", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 5.0, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 2.0, "unit": "pack of 100g"}}, {"id": "ing_milk", "quantity": {"value": 0.083, "unit": "L"}}]', '[{"ingredients":["300g / 10oz whole prawns / shrimp (with heads and shells on (Note 7))"]},{"ingredients":["3 cup (750 ml) water","1/2 cup (125 ml) chicken stock/broth (, low sodium)","2 stalks of lemongrass (, outer layers peeled(Note 1))","1.5 cm / 3/5\" piece of galangal (, cut into 4 slices (Note 2))","5 kaffir lime leaves (, torn roughly (Note 3))","2 Thai or birdseye chillies (Note 4)","3 garlic cloves"],"purpose":"Broth:"},{"ingredients":["120g / 4oz oyster mushrooms","1 roma tomato (, cut into wedges)","1/2 white onion ((medium sized), cut into wedges about 1 cm thick)","1 tsp sugar","3 tbsp fish sauce (Note 5)","3 tbsp lime juice","Coriander/cilantro (, for garnish)"],"purpose":"Soup Add Ins:"},{"ingredients":["1 1/2 tbsp Thai roasted chili sauce (Nam Prik Pa, Note 6)","1/3 cup (75 ml) evaporated milk"],"purpose":"Creamy Tom Yum Option:"}]', '[{"description":"Peel the prawns. Place heads and shell in pot, reserve meat.","images":[],"step":1},{"description":"Use a meat mallet or similar to bash the garlic, chilli and lemongrass so they burst open to release flavour. Add into pot.","images":[],"step":2},{"description":"Crush kaffir lime leaves with your hands. Add into pot.","images":[],"step":3},{"description":"Add galangal, stock and water. Bring to simmer on high heat, cover, then reduce to medium and simmer for 10 minutes.","duration":10,"images":[],"step":4},{"description":"Strain the broth, discard the prawn shells etc, then return broth into same pot over low heat.","images":[],"step":5},{"description":"Add onions and mushrooms, simmer 3 minutes. Add tomatoes, simmer for 1 minute.","duration":1,"images":[],"step":6},{"description":"Add prawns, simmer 2 minutes or until just cooked.","images":[],"step":7},{"description":"Stir in sugar and fish sauce, simmer for 1 minute.","duration":1,"images":[],"step":8},{"description":"Add lime juice, then taste. Adjust sweet (sugar), salt (fish sauce) and sour (lime) to your taste (trust me, you''ll know when you like it!).","images":[],"step":9},{"description":"Ladle into bowls and serve with fresh coriander and fresh chilli! This is the CLEAR version of Tom Yum.","images":[],"step":10},{"description":"Creamy Tom Yum:","images":[],"step":11},{"description":"When you add sugar, also add Thai Chilli Paste and evaporated milk.","images":[],"step":12},{"description":"Then continue with recipe!","images":[],"step":13},{"title":"Bonus","description":"Tom KHA!","images":[],"step":14},{"description":"Following Creamy Tom Yum steps but use coconut milk instead of evaporated milk.","images":[],"step":15}]', '["fish","milk","shellfish"]', '["gluten_free","high_protein","low_calorie"]', '{"mealType":["dinner","snack"],"cuisine":["Thai"],"categories":["asian-recipes","asian-soups","cuisines","dietary","iconic-dishes","low-calorie-recipes","soup-recipes","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_efb2e92c00eb', 'en', 'US', 'Vietnamese Caramelised Pork Bowls', 'Recipe video above. An exciting way to use ground meat (mince) to make a quick stir fry that taste unbelievable! This is great made with chicken, turkey or pork. It also works with beef though it is better made with "white meats". Serve it over rice or vermicelli noodles to make rice bowls with shredded lettuce, carrots and cucumbers on the side (very classic Vietnamese meal!).**NOTE: If you reduce sugar then the pork will not caramelise as well and it will take longer to get colour on it!**', 'https://www.recipetineats.com/tachyon/2015/11/Vietnamese-Ground-Pork-Bowls_7.jpg', 10, 10, 20, 4, '[{"id": "ing_oil", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_pork_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cucumber", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["1 1/2 tbsp cooking oil (I use peanut oil)","1/2 onion (, finely diced (brown, white or yellow) (~1/2 cup))","2 tsp ginger (, grated or minced)","2 garlic cloves (, minced (2 tsp paste))","1 birds eye or Thai chili (, deseeded and finely chopped (can omit, Note 1))","500g / 1 lb pork mince (ground pork) (Note 2)","5 tbsp (tightly packed brown sugar (don''t skimp, else won''t caramelise)","2 tbsp fish sauce"]},{"ingredients":["1 green onion stem (, finely sliced)","Jasmine rice (or other rice for serving)","Sliced red chilli, tomato, cucumber (optional)"],"purpose":"Serving:"}]', '[{"description":"Heat the oil in a large skillet over high heat.","images":[],"step":1},{"title":"Sauté","description":"Add the onion, ginger, garlic and chili and cook for 2 minutes.","duration":2,"images":[],"step":2},{"title":"Cook pork","description":"Add the pork mince and cook for 2 minutes or so until white all over, breaking up the meat with a wooden spoon.","duration":2,"images":[],"step":3},{"title":"Add sauce & caramelise","description":"Add the sugar and fish sauce. Stir, then leave it to cook without touching until all the juices cook out and the pork starts caramelised - about 2 minutes. Then stir it and leave it again, without stirring, for around 30 seconds to get more caramelisation. Repeat twice more until caramelised to your taste.","images":[],"step":4},{"description":"Serve over jasmine or other rice, or vermicelli noodles, garnished with sliced green onion. For a low carb, low cal option, try Cauliflower Rice! I like to have chunks of plain cucumber and carrots on the side which is a classic way of making Vietnamese bowls.","images":[],"step":5}]', '["fish","peanuts"]', '["gluten_free","high_protein","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Vietnamese"],"categories":["asian-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","pork-recipes","quick-and-easy","stir-fries","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b8d7cd238ad5', 'en', 'US', 'Sticky Chinese Chicken Wings', 'Recipe video above. My family recipe for the ultimate Sticky Chinese Wings, perfected over years with many heated debates! Many of the ingredients can be substituted and you''ll still get a similar flavour - refer to the notes. Spiciness: A hint of spicy from the chilli sauce, can be omitted.', 'https://www.recipetineats.com/tachyon/2014/06/Sticky-Chinese-Chicken-Wings_5.jpg', 10, 50, 60, 6, '[{"id": "ing_chicken", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.06, "unit": "bottle of 500ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_ketchup", "quantity": {"value": 0.075, "unit": "bottle of 500g"}}, {"id": "ing_chilli", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_five_spice_powder", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.15, "unit": "pack of 100g"}}]', '[{"ingredients":["1.5 kg /3 lb chicken wings (, cut into drumettes and wingettes (Note 1))"]},{"ingredients":["1/2 tsp sesame oil (, toasted )","2 tbsp lemon juice","2 tbsp Chinese cooking wine (Shaoxing wine, sub Mirin, dry sherry)","2 tbsp soy sauce (, light or all purpose)","2 tbsp brown sugar or honey","1 1/2 tbsp hoisin sauce","1 1/2 tbsp oyster sauce","1/4 cup ketchup (or Aussie tomato sauce)","1 tbsp chilli garlic sauce (or sambal oelek (adjust spiciness to taste))","4 cloves garlic (, minced)","1 tbsp ginger (, finely grated)","1/2 tsp five spice powder"],"purpose":"Chicken Wing Marinade (Note 2 for substitutions)"},{"ingredients":["Finely sliced shallots/scallions","Sesame seeds","Coriander/cilantro leaves","Finely sliced fresh chili"],"purpose":"Garnishes (optional)"}]', '[{"description":"Mix Marinade ingredients.","images":[],"step":1},{"description":"Place wings in large bowl, pour over Marinade and toss well. Set aside for 10 minutes - do not marinate for longer than 1 hour. (Note 3)","duration":10,"images":[],"step":2},{"description":"Preheat the oven to 180C/350F.","images":[],"step":3},{"description":"Line baking tray with foil then greaseproof paper (you''ll thank me later).","images":[],"step":4},{"description":"Shake excess marinade off wings (but reserve the marinade) and spread on baking tray - can be fairly snug but not super squished (use 2 trays if needed).","images":[],"step":5},{"title":"Bake 45","description":"50 minutes, basting with a brush at 25 minutes and 35 minutes, using the reserved marinade and juieces on the tray.","images":[],"step":6},{"description":"The meat should be able to be pulled off the bones quite easily, they should be just starting to char on the edges and a sticky, dark red/golden colour all over.","images":[],"step":7},{"title":"Sprinkle with garnishes","description":"coriander/cilantro leaves, sesame seeds, chilli, sliced shallots/scallions - then serve!","images":[],"step":8}]', '["gluten","sesame","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["snack","dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","australia-day","chicken-recipes","chicken-wings","dinner-tonight","grilling-ideas-and-recipes","modern-asian","quick-and-easy","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d42919bd0e7f', 'en', 'US', 'Chinese Crispy Noodles with saucy Chicken and Vegetables (crispy CHOW MEIN!)', 'Recipe video above. Crispy noodles topped with a saucy chicken and vegetable stir fry, my favourite dish at my local Chinese!! Restaurants typically make this by deep frying the noodles. For my home version, I crisp up the noodles in a pan - much healthier, less mess, just as fast and definitely just as tasty!', 'https://www.recipetineats.com/tachyon/2014/08/Crispy-Chinese-Noodles-Chow-Mein_9.jpg', 15, 10, 25, 2, '[{"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.06, "unit": "bottle of 500ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.013, "unit": "pack of 100g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.4, "unit": "pack of 500g"}}, {"id": "ing_water", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 1.25, "unit": "bottle"}}, {"id": "ing_chicken", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_bok_choy", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_cabbage", "quantity": {"value": 6.0, "unit": "head"}}]', '[{"ingredients":["1 tbsp oyster sauce","2 tbsp Chinese cooking wine ( (shoasing wine) (sub Dry Sherry, Mirin, Note 1))","1.5 tbsp soy sauce (, light or all purpose (not dark soy))","1/4 tsp sesame oil","1 tsp sugar","White pepper (, one dash)","3/4 cup (185ml) chicken stock / broth (, low sodium)","3 tbsps cornflour / corn starch"],"purpose":"Sauce"},{"ingredients":["200 g / 8 oz fresh chow mein noodles (Note 2)","4 tbsp water (, separated)","2 tbsp peanut oil (or vegetable or canola)"],"purpose":"Crispy Noodles"},{"ingredients":["150 g / 5 oz chicken (, thinly sliced)","1 tbsp peanut oil (, if needed (or vegetable or canola))","2 garlic cloves (, finely chopped)","1/2 onion (, sliced)","1 carrot * (, small, halved lengthwise then sliced on diagonal)","1 bok choy * (, stems and leaves separated with stems cut vertically into sticks)","2 shallots/scallions * (, cut into 5cm/2\" pieces)","2 cups cabbage * (, cut into 2.4cm / 1\" squares)","1/2 cup (125ml) water"],"purpose":"Stir Fry"}]', '[{"description":"Sauce & Chicken Marinade","images":[],"step":1},{"description":"Mix the Sauce ingredients EXCEPT cornflour and chicken broth/stock.","images":[],"step":2},{"description":"Remove 1 tbsp Sauce and mix through chicke. Leave to marinate 10 minutes+.","images":[],"step":3},{"description":"Mix cornflour into Sauce until lump free.","images":[],"step":4},{"description":"Turn oven onto low (to keep noodles warm while you cook the topping).","images":[],"step":5},{"description":"Divide noodles into 2 then shape into 20cm/8\" rounds. Keep them tangled - this holds them together while cooking.","images":[],"step":6},{"description":"Heat 1 tbsp oil in skillet over medium high heat. Place 1 noodle cake into pan then drizzle over 2 tbsp water.","images":[],"step":7},{"description":"Wait until the water evaporates (steam cooks the noodles), then pat down lightly and let the noodles cook for a further 1 to 2 minute until the bottom of the noodles are golden brown (lift up with a spatula to check).","images":[],"step":8},{"description":"Slide noodles onto a plate, then flip upside down back into the pan. Cook for a further 1 1/2 - 2 minutes until golden brown, then transfer to tray and place in oven to keep warm.","images":[],"step":9},{"description":"Repeat with remaining noodle cake.","images":[],"step":10},{"description":"Saucy Stir Fry Topping","images":[],"step":11},{"description":"Add an extra 1 tbsp oil if needed, increase heat to HIGH. Add garlic and onion, cook for 30 seconds.","duration":0.5,"images":[],"step":12},{"description":"Add chicken and cook until it changes from pink to white (still raw inside)","images":[],"step":13},{"description":"Add the carrot and bok choy stems, cook 30 seconds.","images":[],"step":14},{"description":"Add cabbage and leaf of buk choy, cook for 1 minute until they start to wilt.","duration":1,"images":[],"step":15},{"description":"Add chicken broth, water, then Sauce and stir. Let it simmer for 1 - 2 minutes until the Sauce thickens to a syrup consistency (see video).","duration":1.5,"images":[],"step":16},{"description":"To serve","images":[],"step":17},{"description":"Place a noodle cake on the plate, then spoon over the stir fry onto the middle of the noodles (leave edges crispy) being sure to use up all the sauce so it soaks the noodles. Serve immediately!","images":[],"step":18}]', '["gluten","peanuts","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","chicken-recipes","chinese-recipes","dinner-tonight","most-popular","noodles","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_fbe7e4a0da99', 'en', 'US', 'Thai Beef Salad', 'Recipe video above. A great Thai Beef Salad comes down to the perfect balance of flavours in the dressing. To achieve this, I''m going to ask you to use teaspoons to measure the garlic and chilli. Because - not all garlic cloves are the same size. So annoying, right??!Grinding coriander to mix into the dressing gives this an extra dimension that makes this a restaurant standard recipe. It makes all the difference to the flavour!', 'https://www.recipetineats.com/tachyon/2015/07/Thai-Beef-Salad_2.jpg', 20, 5, 25, 2, '[{"id": "ing_chilli", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 0.417, "unit": "pack of 3 heads"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_sugar", "quantity": {"value": 0.011, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 0.09, "unit": "net of 500g"}}, {"id": "ing_grapes", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_beef_steak", "quantity": {"value": 7.0, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_lettuce", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 10.0, "unit": "punnet of 250g"}}, {"id": "ing_onion", "quantity": {"value": 0.25, "unit": "pack of 1kg"}}, {"id": "ing_cucumber", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_mint", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_peanuts", "quantity": {"value": 0.094, "unit": "jar"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["1/2 tsp birds eye or Thai Chilli (, deseeded and finely minced (Note 1))","1/4 tsp finely minced garlic (1/2 small clove)","1 tbsp finely chopped cilantro/coriander stems","2 1/4 tsp white sugar","2 tbsp fish sauce","3 tbsp lime juice","1 tbsp grapeseed oil (or canola or vegetable oil)","1 small pinch cooking / kosher salt"],"purpose":"Dressing"},{"ingredients":["7 - 8 oz / 200 - 250 g good quality beef steak - sirloin (, at room temperature (Note 2))","1 tbsp oil (vegetable, peanut or canola oil)","1/4 tsp each salt and pepper","2 heaped cups mixed lettuce leaves","10 cherry tomatoes (, halved)","1/4 small red onion (, very finely sliced)","1/2 cucumber (optional deseed) (, cut horizontally then cut into slices (about 1/3 cup))","1/4 cup cilantro/coriander leaves (, lightly packed)","1/4 cup mint leaves (, lightly packed)"],"purpose":"Salad"},{"ingredients":["1/4 cup finely chopped peanuts (, roasted, unsalted)","Extra cilantro/coriander and mint leaves"],"purpose":"Garnish"}]', '[{"description":"Place the birds eye chili, garlic, cilantro stems and a small pinch of salt into a mortar and pestle. Grind until a smooth paste forms.","images":[],"step":1},{"description":"Add the remaining Dressing ingredients. Adjust sugar, lime juice and fish sauce to taste. Set aside.","images":[],"step":2},{"title":"Alternative","description":"Finely mince garlic, coriander and chilli. Use side of knife to smear into paste on cutting board, then shake in jar with remaining ingredients.","images":[],"step":3},{"description":"Preheat a skillet over high heat until screaming hot and smoking.","images":[],"step":4},{"description":"Drizzle the beef with 1/2 tbsp of oil on both sides, then sprinkle with a good pinch of salt and pepper. Cook the beef to your liking (Note 2).","images":[],"step":5},{"title":"Cook times","description":"for steak 2cm / 4/5” thick, 2 min on each side for medium rare (until internal temp is 52°C/125°F) OR 2 1/2 min each side for medium (internal temp 57°C/135°F).","images":[],"step":6},{"description":"Remove the beef from the skillet onto a plate. Loosely tent with foil and set aside for 10 minutes to rest.","duration":10,"images":[],"step":7},{"description":"Place lettuce in a bowl, drizzle with 1 tbsp Dressing and toss.","images":[],"step":8},{"description":"Slice the beef thinly against the grain (Note 2) and place in a bowl with the remaining Salad ingredients. Dress with most remaining Dressing and toss gently.","images":[],"step":9},{"description":"Pile dressed lettuce onto plate(s), pile over beef and other salad ingredients.","images":[],"step":10},{"description":"Sprinkle with peanuts and garnish with extra cilantro/coriander and mint leaves if using, drizzle with remaining Dressing. Serve immediately!","images":[],"step":11}]', '["fish","peanuts"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["lunch"],"cuisine":["Asian","Thai"],"categories":["asian-recipes","asian-takeout","beef-recipes","cuisines","dietary","dinner-tonight","gluten-free-recipes","grilling-ideas-and-recipes","low-calorie-recipes","main-dishes","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_04b861d4f5dd', 'en', 'US', 'Tuna Poke Bowl', 'Recipe video above. The Dressing is what makes or breaks a Poke Bowl. This Ginger-Sesame one MAKES it!!! Mirin is the secret ingredient - it adds complexity and flavour that''s missing from usual Poke Bowl Dressings. It looks like a long list of ingredients and there are quite a few bits and pieces, but it''s actually a very leisurely recipe to make. (PS Dicing fish is great flavour carrier technique) GREAT HOT WEATHER FOOD!', 'https://www.recipetineats.com/tachyon/2019/08/Tuna-Poke-Bowls-main.jpg', 20, 15, 35, 4, '[{"id": "ing_rice", "quantity": {"value": 300.0, "unit": "pack"}}, {"id": "ing_water", "quantity": {"value": 0.625, "unit": "L"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.25, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 3.0, "unit": "pack of 100g"}}, {"id": "ing_mirin", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_chilli", "quantity": {"value": 0.125, "unit": "pack of 100g"}}, {"id": "ing_ginger", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_sashimi_grade_tuna_0_7cm_1_4_dice", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_cucumber", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_radishes", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_shelled_edamame", "quantity": {"value": 150.0, "unit": "pack"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["2 cups sushi rice (, rinsed (Note 1))","2 1/2 cups water"],"purpose":"Sushi Rice:"},{"ingredients":["1/4 cup rice vinegar (Note 2)","2 tsp sugar (, white)","1/4 tsp salt"],"purpose":"Sushi Rice Seasoning:"},{"ingredients":["1 1/2 tbsp light or all purpose soy sauce (Note 3)","2 tsp dark soy (Note 3)","2 1/2 tbsp toasted sesame oil (Note 4)","2 tbsp mirin (Note 5)","2 tbsp rice vinegar (Note 2)","2 1/2 tsp chilli paste or Sriracha","1 1/2 tsp grated ginger (, fresh)"],"purpose":"Ginger Marinade Dressing:"},{"ingredients":["350g / 12oz sashimi grade tuna (or salmon, trout or kingfish), diced 0.7cm / 1/4\" dice (Note 7)","1 small carrot (, finely julienned)","1 cucumber (, deseeded and finely diced (Note 7))","1 small avocado (, peeled and cut into 8 wedges (or dice))","6 red radish (, finely sliced)","1 cup shelled edamame (, boiled or steamed per packet (Note 8))","1 green onion (, finely sliced on the diagonal)","Black sesame seeds"],"purpose":"Poke Bowl:"}]', '[{"description":"Place water and rice in a large saucepan over medium high heat, no lid.","images":[],"step":1},{"description":"As soon as it comes to a boil (see video), lower heat to medium low, place lid on and leave for 18 - 20 minutes or until water is completely absorbed). DO NOT stir, DO NOT remove lid!","duration":19,"images":[],"step":2},{"description":"Remove from stove with lid still on and leave undisturbed for 15 minutes.","duration":15,"images":[],"step":3},{"description":"Sushi Rice Seasoning:","images":[],"step":4},{"description":"Mix Sushi Seasoning ingredients until sugar dissolves.","images":[],"step":5},{"description":"Spread rice out into large pan (23 x 33cm / 9 x 13\"), drizzle half Seasoning all over.","images":[],"step":6},{"description":"Using a rice paddle OR rubber spatula, cut through the rice and gently fold the rice over (see video!) to mix the Seasoning through.","images":[],"step":7},{"description":"After 1 minute of mixing, drizzle remaining Seasoning then cut/fold for 1 minute. Will look wet but will absorb in next step.","duration":1,"images":[],"step":8},{"description":"Leave rice to cool to warm or room temp (if you can stick it in front of a fan, that''s even better!) - about 20 minutes.","images":[],"step":9},{"description":"Poke Bowl Assembly:","images":[],"step":10},{"title":"Dressing","description":"Mix ingredients in a bowl.","images":[],"step":11},{"description":"Divide rice between bowls. Top with radish, carrot, edamame and avocado.","images":[],"step":12},{"description":"Place tuna in Dressing and toss (no need to marinate), then immediately transfer onto rice.","images":[],"step":13},{"description":"Sprinkle cucumber over the top (mainly on tuna), then green onion and sesame seeds.","images":[],"step":14},{"description":"Drizzle over remaining Dressing then serve!","images":[],"step":15}]', '["fish","gluten","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","Hawaiian","Japanese(ish)","Western"],"categories":["asian-recipes","fish-recipes","rice-recipes","salad-recipes-main-course","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4264b86b0e37', 'en', 'US', 'Salmon Salad with Asian Ginger Sesame Dressing', 'Recipe video above. A mighty Salmon Salad that tastes even better than it looks! Vibrant flavours with a fabulous variety of textures - and the Asian Ginger Sesame Dressing gives this amazing flavours!', 'https://www.recipetineats.com/tachyon/2019/07/Salmon-Salad_1.jpg', 15, 10, 25, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_radishes", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 3.0, "unit": "head"}}, {"id": "ing_edamame", "quantity": {"value": 150.0, "unit": "pack"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.15, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["3 - 4 salmon fillets (, skinless)","3/4 tsp salt and pepper (, each)","1 tbsp oil","250g / 1.5 cups cherry tomatoes (, halved)","2 cucumber (, sliced (or 1 English/telegraph long cucumber))","1 large avocado (, cut into 1.5cm / 2/3\" pieces)","6 red radish (, sliced)","150g / 5 oz leafy crisp lettuce of choice (6 big handfuls)","1 cup edamame (, cooked per packet (Note 1))","1 green onion (, finely sliced on diagonal)","1/4 cup crispy fried shallots (Note 2)"]},{"ingredients":["2 tbsp soy sauce (light or all purpose)","2 1/2 tbsp rice vinegar (aka rice wine vinegar Note 3)","1 tbsp sesame oil (toasted, Note 4)","3 tbsp olive oil (or other neutral flavoured oil)","1.5 tsp sugar (, any type)","2 tsp fresh ginger (, grated)","1 garlic clove (, minced)","1/2 tsp black pepper"],"purpose":"Asian Ginger Sesame Dressing:"}]', '[{"description":"Place Dressing ingredients in a jar and shake well.","images":[],"step":1},{"description":"Sprinkle both sides of salmon with salt and pepper.","images":[],"step":2},{"description":"Heat oil in a non stick skillet over medium high heat.","images":[],"step":3},{"description":"Place salmon in upside down (ie skin side up), cook for 3 minutes or until deep golden.","duration":3,"images":[],"step":4},{"title":"Turn and cook for another 2","description":"3 minutes, or until cooked to your taste.","images":[],"step":5},{"description":"Remove onto plate and cool for 5 minutes.","duration":5,"images":[],"step":6},{"description":"Assemble Salad:","images":[],"step":7},{"description":"Place lettuce in a large bowl. Drizzle with a bit of dressing and toss.","images":[],"step":8},{"description":"Place lettuce in a large serving bowl (or individual plates). Top with salmon, then place tomato, cucumber, avocado, edamame and radish in piles around it.","images":[],"step":9},{"description":"Sprinkle with green onion and crispy shallots.","images":[],"step":10},{"description":"Just prior to serving, drizzle all over with remaining Dressing.","images":[],"step":11}]', '["fish","gluten","sesame","soy"]', '["high_protein"]', '{"mealType":["lunch","dinner"],"cuisine":["Asian influence"],"categories":["asian-recipes","fish-recipes","modern-asian","salad-recipes-main-course","salmon-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2252d8487ad7', 'en', 'US', 'Laksa Noodle Soup', 'Recipe video above. This is a recipe for a real Malaysian restaurant quality laksa made by sprucing up store bought laksa paste! You can''t just dump store bought laksa paste into coconut broth! The key is to freshen up the paste by sautéing it with garlic, ginger, chilli and lemongrass. Makes a world of difference! This makes 2 large bowls. Because large is the only way to go with Laksa!', 'https://www.recipetineats.com/tachyon/2016/09/Laksa.jpg', 15, 45, 60, 2, '[{"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_lemongrass", "quantity": {"value": 20.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_laksa_paste", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.1, "unit": "pack of 500g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.1, "unit": "pack of 500g"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 80.0, "unit": "bag of 250g"}}, {"id": "ing_tofu", "quantity": {"value": 0.267, "unit": "pack of 300g"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.03, "unit": "bottle of 250ml"}}, {"id": "ing_aksa_paste", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_sriracha", "quantity": {"value": 0.037, "unit": "bottle of 400ml"}}, {"id": "ing_chilli", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.15, "unit": "pack of 100g"}}]', '[{"ingredients":["2 cups (500 ml) chicken stock / broth","1 cup (250 ml) water","3 chicken drumsticks (Note 1)"],"purpose":"Chicken Stock"},{"ingredients":["1 1/2 tbsp oil","2 garlic cloves (, minced)","2 cm / 4/5\" piece of ginger (, finely grated)","1 lemongrass (, white part grated, (Note 2))","2 birds eye chillis (, finely chopped (Note 3))","1/2 cup (135g) laksa paste (Note 4)","400ml can coconut milk (Note 5)","2 tsp fish sauce (sub soy)"],"purpose":"Laksa Broth"},{"ingredients":["50g / 1.5 oz vermicelli noodles (, dried)","100g / 3.5oz hokkien noodles (optional, Note 6)","80g / 2.5 oz bean sprouts","80g / 2.5 oz tofu puffs (, cut in half (Note 7))"],"purpose":"Noodles + Toppings"},{"ingredients":["1/2 tsp sugar (, white)","1 1/2 tsp soy sauce (, light or all purpose)","1/2 garlic clove (, minced)","1 1/2 tsp Laksa paste (Note 4)","1 tbsp Sriracha sauce (, or other chilli sauce)","1 tbsp chilli paste from jar (, or more Sriracha)","1 tbsp vegetable oil (any plain oil)"],"purpose":"Laksa Chilli Sauce (Note 8)"},{"ingredients":["Fresh coriander / cilantro (recommended)","Lime wedges (recommended)","Crispy fried shallots (, optional (Note 8))","Finely sliced red chilli (, optional )"],"purpose":"Garnishes"}]', '[{"description":"Place Chicken Stock ingredients in a medium saucepan over high heat. Bring to simmer, then reduce to medium high.","images":[],"step":1},{"description":"Cook for 25 minutes or until chicken flesh is falling off the bone and liquid reduces by about 1/3.","duration":25,"images":[],"step":2},{"description":"Discard skin, pull flesh off the bone and place in bowl, discard bone. Set broth aside.","images":[],"step":3},{"description":"Laksa Chilli Sauce","images":[],"step":4},{"description":"Mix ingredients together in a small bowl. Set aside for 20 minutes.","duration":20,"images":[],"step":5},{"description":"Heat oil in a large saucepan or small pot over medium low heat. Add garlic and ginger, sauté for 20 seconds, then add lemongrass and chillis. Cook for 1 minute.","duration":0.3333333333333333,"images":[],"step":6},{"description":"Add laksa paste. Turn heat up to medium and cook for 2 minutes, stirring constantly, or until fragrant.","duration":2,"images":[],"step":7},{"description":"Add chicken stock, coconut milk, fish sauce and 2 tsp of Laksa Chilli Sauce. Place lid on and simmer on for 10 minutes.","duration":10,"images":[],"step":8},{"description":"Adjust to taste using lime juice (for sour) and fish sauce (for saltiness). Add tofu puffs. Leave on turned off stove with lid on for 5 minutes.","duration":5,"images":[],"step":9},{"description":"Prepare noodles per packet directions.","images":[],"step":10},{"description":"Divide noodles between 2 bowls. Top with shredded chicken.","images":[],"step":11},{"description":"Pour broth over chicken. Top with beansprouts. Sprinkle with Garnishes you choose to use. Serve with Laksa Chilli Sauce on the side.","images":[],"step":12}]', '["fish","gluten","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Malaysian"],"categories":["asian-recipes","asian-soups","asian-takeout","chicken-breast-recipes","chicken-drumstick-recipes","chicken-recipes","curry-recipes","iconic-dishes","main-dishes","noodles","soup-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ee8281ce2abc', 'en', 'US', 'Thai Fried Rice', 'Recipe video above. Real Thai Fried Rice, just how it''s made in Thailand and also just like takeout! The scrambling of the egg in the wok with the other ingredients pushed to the side is a classic Thai method. 3 sauce variations provided (refer Note 3 for explanation).', 'https://www.recipetineats.com/tachyon/2015/09/Thai-Fried-Rice_2.jpg', 14, 6, 20, 5, '[{"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 666.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_shrimp", "quantity": {"value": 0.142, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.06, "unit": "bunch"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_one_sauce_option", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_thai_seasoning", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cucumber", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["2 tbsp vegetable oil (or canola or peanut oil)","2 large garlic cloves (, very finely chopped)","1/2 onion (, diced)","5 oz / 150 g small prawns/shrimp (cooked or raw) (, or chicken breast thinly sliced (Note 1))","3 green onion (shallots) (, cut into 1.5 \"/4 cm pieces)","2 eggs (, lightly beaten)","3 cups cooked jasmine rice (, cold (preferably refrigerated overnight) (Note 2))","ONE Sauce Option (see below for options)"]},{"ingredients":["1 1/2 tbsp soy sauce","1 1/2 tbsp oyster sauce"],"purpose":"Sauce Option 1"},{"ingredients":["2 tbsp fish sauce","1 1/2 tbsp oyster sauce","1 tsp sugar (any type)"],"purpose":"Sauce Option 2"},{"ingredients":["1 1/2 tbsp light soy sauce","1 1/2 tbsp Thai Seasoning (Gold Mountain) (Note 4)"],"purpose":"Sauce Option 3"},{"ingredients":["Tomato wedges","Cucumber slices","Fresh coriander"],"purpose":"To Serve (optional)"}]', '[{"description":"Heat oil in a large wok or a large skillet over medium high heat. (Add 1 tbsp extra oil if using a skillet)","images":[],"step":1},{"description":"Add garlic and onion, stir fry for 30 seconds.","duration":0.5,"images":[],"step":2},{"description":"Add prawns/shrimp and white part of green onion, stir fry for 1 minute.","duration":1,"images":[],"step":3},{"description":"Push everything to the side and pour the egg onto the other side. Scramble it quickly - about 20 seconds.","images":[],"step":4},{"description":"Add the rice and Sauce of choice. Stir fry for 2 minutes, adding green part of green onions halfway through, until all the rice is coated with the Sauce.","duration":2,"images":[],"step":5},{"description":"Serve immediately, garnished with fresh cilantro/coriander with tomato and cucumbers on the side. (See in post for more serving ideas)","images":[],"step":6}]', '["egg","fish","gluten","peanuts","shellfish","soy"]', '["low_calorie"]', '{"mealType":["main_course"],"cuisine":["Thai"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-recipes","cuisines","dietary","dinner-tonight","fried-rice","gluten-free-recipes","main-dishes","quick-and-easy","rice-recipes","rice-side-dishes","side-dishes","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_86182c6e2c0d', 'en', 'US', 'Thai Fish Cakes', 'Recipe video above. These taste JUST like the Thai Fish Cakes from your favourite Thai restaurant! They should be firm but bouncy, almost a spongey texture, well seasoned, golden brown and with lovely complex flavours from the red curry paste and other seasonings.', 'https://www.recipetineats.com/tachyon/2016/04/Thai-Fish-Cakes_1-1.jpg', 10, 15, 25, 12, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_red_curry_paste", "quantity": {"value": 0.225, "unit": "bottle"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_green_beans", "quantity": {"value": 6.0, "unit": "pack"}}, {"id": "ing_oil", "quantity": {"value": 4.0, "unit": "bottle"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_lime", "quantity": {"value": 0.03, "unit": "net of 500g"}}]', '[{"ingredients":["1 lb / 500g white fish fillets (, skinless and pin boned, cut into chunks (Note 1))","3 tbsp red curry paste (Note 2)","1 tbsp cilantro/coriander leaves (, chopped)","1 tbsp fish sauce (sub soy sauce)","1 tbsp lime juice","1 egg","1/4 cup (40g) rice flour (or cornstarch / corn flour)","6 green beans (, finely sliced (optional, Note 3))","4 - 6 tbsp oil (vegetable, canola, sun flower)"]},{"ingredients":["Sweet chilli sauce","Cilantro/coriander leaves","Lime wedges"],"purpose":"To Serve"}]', '[{"description":"Place fish, red curry paste, cilantro/coriander, fish sauce, lime and egg in a food processor. Whizz until the fish is minced and it looks like a paste. (See video)","images":[],"step":1},{"description":"Transfer to a bowl and stir through rice flour and green beans until flour is all incorporated. (Note 4)","images":[],"step":2},{"description":"Measure 1/4 cup of mixture (I use an ice cream scoop - Note 5), form 1cm / 2/5\" thick patties.","images":[],"step":3},{"description":"Heat enough oil in skillet over medium high heat to cover the base (4 tbsp or so)","images":[],"step":4},{"description":"Place in oil, cook 2 minutes until deep golden brown, then turn and cook the other side for 2 minutes. Transfer to paper towel lined plate.","duration":2,"images":[],"step":5},{"description":"Repeat with remaining mixture, adding more oil into the skillet if required.","images":[],"step":6},{"description":"Serve with Sweet Chilli Sauce, garnished with cilantro/coriander leaves and lime wedges on the side. Add a side of Thai Fried Rice or even just plain jasmine rice to make a meal!","images":[],"step":7}]', '["egg","fish","gluten","soy"]', '["keto_friendly","low_calorie"]', '{"mealType":["snack"],"cuisine":["Thai"],"categories":["asian-recipes","asian-takeout","cuisines","dietary","dinner-tonight","finger-food","fish-recipes","gluten-free-recipes","main-dishes","seafood-recipes","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_46c73eae64a3', 'en', 'US', 'Banh Mi recipe', 'Recipe video above! See in post for more details and photos about the authentic ingredients, where to source them, and the BEST subs from everyday supermarkets. When combined with everything else, it still tastes like an incredibly authentic Banh Mi!', 'https://www.recipetineats.com/tachyon/2019/07/Overhead-photo-of-Banh-Mi.jpg', 20, 0, 20, 4, '[{"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_chicken", "quantity": {"value": 0.09, "unit": "kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.225, "unit": "jar of 400g"}}, {"id": "ing_thi_nguoi_or_brawn", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.09, "unit": "kg"}}, {"id": "ing_pork", "quantity": {"value": 0.09, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.9, "unit": "bunch"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_green_onion", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 2.0, "unit": "pack of 100g"}}, {"id": "ing_maggi_seasoning", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_carrot", "quantity": {"value": 4.0, "unit": "pack of 1kg"}}, {"id": "ing_water", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_vinegar", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_pork", "quantity": {"value": 0.09, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.09, "unit": "kg"}}]', '[{"ingredients":["4 crusty long bread rolls (Note 1)","6 tbsp pork or chicken pate (Note 2)","6 tbsp mayonnaise (Note 3)","4 - 8 slices Thi Nguoi (\"pink ham\") OR brawn (aka head cheese, Note 4)","4 - 8 slices Cha Lua Vietnamese pork loaf OR chicken loaf (Note 5)","4 - 8 slices roast or grilled pork cold cuts (Note 6)","1.5 cups fresh coriander/cilantro sprigs (Note 7)","2 cucumbers (, finely sliced lengthwise into long strips)","4 green onion stems (, cut into the length of the rolls)","2 red chillies (, finely sliced (or more!) (or less...))","2 tsp Maggi Seasoning (, for drizzling (Note 8))"]},{"ingredients":["4 medium carrots (, peeled cut into 2-3mm / 1/10\" batons)","1 1/2 cups (375ml) hot water (, boiled)","1/2 cup (100g) white sugar","4 tsp salt","3/4 cup (185ml) rice wine vinegar (sub apple cider vinegar)"],"purpose":"Pickled Carrots:"},{"ingredients":["Pork meatballs for Banh Mi (Note 9)","Shredded rotisserie or poached chicken (Note 10)"],"purpose":"Other Filling Options!"}]', '[{"description":"Split rolls down the centre of the top (see video).","images":[],"step":1},{"description":"Spread 1.5 tbsp pate on one side, then 1.5 tbsp mayonnaise on top.","images":[],"step":2},{"description":"Layer in the hams, cucumber slices and green onion.","images":[],"step":3},{"description":"Stuff in plenty of carrots and coriander sprigs.","images":[],"step":4},{"title":"Sprinkle with fresh chilli","description":"as much as you dare!","images":[],"step":5},{"description":"Drizzle with Maggi Seasoning (about 1/2 tsp per roll).","images":[],"step":6},{"description":"Close sandwich together and devour!","images":[],"step":7},{"title":"Banh Mi pork meatballs","description":"for each Banh Mi, use 3 meatballs. Shake off excess sauce, split warm meatballs in half then stuff into Banh Mi in place of the ham.","images":[],"step":8},{"title":"Shredded cooked chicken","description":"use in place of ham. I often use store bought rotisserie chicken for convenience!","images":[],"step":9},{"description":"Pickled Carrots","images":[],"step":10},{"description":"Dissolve salt and sugar in the hot water, then add rice vinegar.","images":[],"step":11},{"title":"Add carrot, then let stand for at least 1 hour","description":"carrot should be a bit tangy, a bit floppy but still with a soft crunch.","images":[],"step":12},{"description":"Drain and use per recipe.","images":[],"step":13}]', '["gluten","milk"]', '[]', '{"mealType":["lunch"],"cuisine":["Vietnamese"],"categories":["asian-recipes","asian-takeout","banh-mi","iconic-dishes","no-cook-food","sandwiches-and-sliders","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_daa08d39a60c', 'en', 'US', 'Nasi Goreng (Indonesian Fried Rice)', 'Recipe video above. A traditional Indonesian fried rice recipe which is often served with a fried egg for a protein boost to make it a meal, but I usually serve it as a side dish. The magic ingredient in this is kecap manis, a sweet soy sauce which is available in large supermarkets and of course in Asian stores. Feel free to swap out the chicken for other proteins! Shrimp/prawns, tofu, beef and pork are all great alternatives.', 'https://www.recipetineats.com/tachyon/2016/03/Nasi-Goreng_3-1.jpg', 10, 10, 20, 4, '[{"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.142, "unit": "kg"}}, {"id": "ing_kecap_mani", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_white_rice", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_shrimp", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 4.0, "unit": "carton of 12"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_cucumber", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}]', '[{"ingredients":["1 tbsp oil","5 oz / 150g chicken breast (, thinly sliced (or other protein))","1 tbsp kecap manis (sweet soy sauce, Note 1)"],"purpose":"Chicken"},{"ingredients":["1.5 tbsp oil","2 garlic cloves (, finely chopped)","1 tsp red chilli (, finely chopped (Note 2))","1 onion (, small, diced)","3 cups cooked white rice (, day old, cold (Note 3))","2 tbsp kecap manis (sweet soy sauce, Note 1)","2 tsp shrimp paste (, optional (Note 4))"],"purpose":"Rice"},{"ingredients":["4 eggs (, fried to taste)","1 green onion (, sliced)","Tomatos and cucumbers, (cut into wedges/chunks)","Fried shallots (, store bought (optional) (Note 3))","Lime wedges"],"purpose":"Garnishes / side servings (optional)"}]', '[{"description":"Heat oil in a large skillet or wok over high heat.","images":[],"step":1},{"description":"Add chilli and garlic, stir for 10 seconds.","duration":0.16666666666666666,"images":[],"step":2},{"description":"Add onion, cook for 1 minute.","duration":1,"images":[],"step":3},{"description":"Add chicken, cook until it mostly turns white, then add 1 tbsp kecap manis and cook for a further 1 minute or until chicken is mostly cooked through and a bit caramelised.","images":[],"step":4},{"description":"Add rice, 2 tbsp kecap manis and shrimp paste, if using. Cook, stirring constantly, for 2 minutes until sauce reduces down and rice grains start to caramelise (key for flavour!).","duration":2,"images":[],"step":5},{"description":"Serve, garnished with garnishes of choice (green onions, red chilli, fried shallots).","images":[],"step":6},{"description":"Serve as a side for Asian main dishes or as part of a large spread, Asian or not! :) See in post for suggestions.","images":[],"step":7},{"title":"Make it a meal","description":"traditional Indonesian style!: Serve with a fried egg sunny side up (runny yolk!), tomato wedges and slices of cucumber on the side.","images":[],"step":8}]', '["egg","gluten","shellfish","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Indonesian"],"categories":["asian-recipes","asian-takeout","dietary","dinner-tonight","fried-rice","gluten-free-recipes","main-dishes","quick-and-easy","rice-recipes","rice-side-dishes","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_daa30431ea02', 'en', 'US', 'Bibimbap', 'Recipe VIDEO above. One of Korea''s most famous food exports! The key here is the Bibimbap Sauce - feel free to switch the veg and meat, whatever you use is going to be amazing once mixed up with that Sauce. There''s a lot of components here but there''s repeat ingredients and it''s an easy recipe - and it''s MEANT to be served at room temp so don''t rush!', 'https://www.recipetineats.com/tachyon/2019/05/Bibimbap_5.jpg', 40, 30, 70, 4, '[{"id": "ing_white_rice", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 4.0, "unit": "carton of 12"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_beef_steak", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_apples", "quantity": {"value": 0.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_honey", "quantity": {"value": 0.03, "unit": "jar of 500g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_zucchini", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_spinach", "quantity": {"value": 1.0, "unit": "bag of 250g"}}, {"id": "ing_shiitake_mushrooms", "quantity": {"value": 8.0, "unit": "pack of 150g"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 4.0, "unit": "bag of 250g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.04, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_gochujang_paste", "quantity": {"value": 60.0, "unit": "bottle"}}, {"id": "ing_mirin", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}]', '[{"ingredients":["4 cups cooked white rice (, preferably short grain (Note 1))","4 eggs","2 tsp sesame seeds"]},{"ingredients":["250 g/8oz beef tenderloin or thick steak (, very finely sliced (subs, Note 2))","1/4 green apple (, grated using box grater (Note 3))","3 garlic cloves (, minced)","1 tsp minced ginger","1 tbsp soy sauce (, light or all purpose (Note 4))","1 tbsp honey (or brown sugar)","2 tsp sesame oil (, toasted (Note 9))"],"purpose":"Korean Beef & Marinade:"},{"ingredients":["2 carrots (, large, cut into 5 x 0.5cm/2 x 1/5\" batons)","2 zucchini (, large, cut into 5 x 0.5cm/2 x 1/5\" batons)","1 bunch of spinach (, cut into 5cm/2\" lengths)","8 dried shiitake mushrooms (, large (Note 5))","4 cups bean sprouts","2 tsp garlic (, minced (3 cloves))","8 tsp vegetable oil (, separated)","1/2 tsp salt","1.5 tsp soy sauce (, light or all purpose (Note 4))","1/4 tsp fish sauce (sub soy)","1/4 tsp white sugar","Sesame oil (, toasted (Note 9))"],"purpose":"Vegetables:"},{"ingredients":["4 tbsp gochujang paste (Note 6)","2 tbsp mirin (Note 7)","2 tbsp rice vinegar (Note 8)","1.5 tsp soy sauce (Note 4)","3 tsp white sugar","1 garlic clove (, finely grated)","2.5 tsp sesame oil (, toasted (Note 9))"],"purpose":"Bibimbap Sauce:"}]', '[{"description":"Bibimbap Sauce:","images":[],"step":1},{"description":"Mix ingredients until sugar is dissolved.","images":[],"step":2},{"description":"Marinated Beef:","images":[],"step":3},{"description":"Mix the marinade in a bowl, then add beef. Marinate for 30 minutes to overnight.","duration":30,"images":[],"step":4},{"description":"Heat 2 tsp oil in a large skillet over high heat. Let excess marinade drip off then add beef. Cook for 3 - 4 minutes until cooked and there''s some caramelised bits, then remove from skillet.","duration":3.5,"images":[],"step":5},{"description":"Keep warm until required or reheat to warm.","images":[],"step":6},{"description":"Prepare Vegetables:","images":[],"step":7},{"title":"Shiitake","description":"Soak mushrooms in a large bowl of boiling water for 30 minutes, or until rehydrated. Drain, squeeze out excess water, then slice.","duration":30,"images":[],"step":8},{"title":"Carrot and Zucchini salting (optional, Note 10)","description":"Place carrot and zucchini in separate bowls, sprinkle each with 1/4 tsp salt, toss, leave for 20 minutes then drain excess liquid.","duration":20,"images":[],"step":9},{"description":"Cook Vegetables:","images":[],"step":10},{"description":"Get 2 skillets going if you can!","images":[],"step":11},{"title":"Shiitake","description":"Heat 2 tsp oil oil in a skillet over medium high heat. Cook mushrooms for 2 minutes. Add 1.5 tsp soy, 1/4 tsp sugar, 1/2 tsp of garlic. Stir for 1 minute, then remove.","duration":2,"images":[],"step":12},{"title":"Carrot","description":"Add 2 tsp oil into the skillet, cook carrot until just tender (5 to 8 minutes), then remove.","images":[],"step":13},{"title":"Zucchini","description":"Cook as with carrot for 4 minutes.","duration":4,"images":[],"step":14},{"title":"Spinach","description":"Heat 2 tsp veg with a splash of sesame oil. Saute until starting to wilt. Add 1/2 tsp garlic, and salt to taste, stir, then remove. When cool, squeeze to drain out excess liquid.","images":[],"step":15},{"title":"Beansprouts","description":"Simmer in water for 5 min or steam in microwave for 3 min until floppy. Drain under cold water, then cool. Squeeze out excess liquid with hands, place in bowl. Mix with 2 tsp sesame oil, 1 tsp garlic, 1/4 tsp fish sauce.","duration":5,"images":[],"step":16},{"description":"Vegetables can cool, they are meant to be at room temp or slightly warm.","images":[],"step":17},{"description":"Fry eggs in a skillet to your taste (I like mine with runny yolks).","images":[],"step":18},{"description":"Place warm rice in bowls.","images":[],"step":19},{"description":"Top with vegetables and beef, as pictured in post, then lastly, the egg.","images":[],"step":20},{"description":"Sprinkle with sesame seeds, drizzled with sesame oil. Serve with Bibimbap Sauce!","images":[],"step":21}]', '["egg","fish","gluten","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Korean"],"categories":["asian-recipes","asian-takeout","beef-recipes","iconic-dishes","korean-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a3bad777ed77', 'en', 'US', 'Asian Mushroom Ramen Noodles', 'Recipe video above. A quick Asian ramen noodle side dish with caramelised garlic mushrooms with a hint of sesame! Don''t let this 4 ingredient sauce fool you - once it hits the pan, it completely transforms. 4 as a side, 2 as a main (add more veggies!)', 'https://www.recipetineats.com/tachyon/2019/03/Mushroom-Ramen-Noodles_3.jpg', 5, 10, 15, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.004, "unit": "pack of 500g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_mushroom", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_water", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_mirin", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}]', '[{"ingredients":["2 packets ramen or other instant noodles (, uncooked, discard seasoning (Note 1))","1.5 tbsp vegetable oil (or other neutral flavoured oil)","400g / 14 oz mushrooms (, sliced (any type))","2 garlic cloves (, minced)","2 tsp sesame oil (or more oil) (Note 2)","5 green onion stems (shallots/scallions)","1 1/4 cups (315 ml) water, plus more as needed"]},{"ingredients":["1 tbsp dark soy sauce (Note 3)","1 tbsp Oyster sauce (or Hoisin, Note 4)","2 tsp Hoisin sauce (or more Oyster sauce)","1 tbsp mirin (Note 5)"],"purpose":"SAUCE:"}]', '[{"description":"Mix Sauce ingredients in a small bowl.","images":[],"step":1},{"description":"Cut green onion into 5cm/2\" lengths. Separate white/pale green part from green part.","images":[],"step":2},{"description":"Heat oil in a large skillet over high heat. Add mushrooms and cook for 3 minutes.","duration":3,"images":[],"step":3},{"description":"Add the garlic and sesame oil, cook until mushrooms and garlic are golden.","images":[],"step":4},{"description":"Add Sauce, give it a quick stir. Add white part of green onions. Cook 1 minute until mushrooms are caramelised.","images":[],"step":5},{"description":"Push mushrooms to the side to make a big well in the centre.","images":[],"step":6},{"description":"Add water then squidge noodle cakes in.","images":[],"step":7},{"description":"Cook 45 seconds, then flip. Cook 30 seconds then break up the noodles.","images":[],"step":8},{"description":"Add green part of green onions and toss well, adding more water if needed to make it saucy.","images":[],"step":9},{"description":"Serve immediately!","images":[],"step":10}]', '["gluten","sesame","soy"]', '["low_calorie","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","dinner-tonight","emergency-recipes","mushroom-recipes","noodles","one-pot-recipes","quick-and-easy","side-dishes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3196c7ccbf7b', 'en', 'US', 'Thai Chicken Satay with Peanut Sauce', 'Recipe video above. Thai Chicken Satay Skewers are tasty enough to eat plain but we''d never skip Thai Peanut Sauce for dipping! The essential ingredient for a really great peanut sauce is natural peanut butter with no added sugar or oil. But normal peanut butter will work fine too.', 'https://www.recipetineats.com/tachyon/2019/03/Thai-Satay-Chicken_8.jpg', 15, 15, 30, 15, '[{"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_skewers", "quantity": {"value": 13.0, "unit": "pack of 50"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.3, "unit": "jar of 50g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_red_curry_paste", "quantity": {"value": 0.05, "unit": "bottle"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.3, "unit": "jar of 375g"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_peanuts", "quantity": {"value": 0.075, "unit": "jar"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["400 g/14oz coconut milk ((1 can), full fat)","13-16 bamboo skewers (, 16cm / 6.5\" long (Note 1))"]},{"ingredients":["600 g / 1.2lb chicken thighs (, boneless skinless, cut into 2cm/4/5\" pieces (Note 2))","1 tbsp curry powder (Note 3)","1 tsp white sugar","2 tsp red curry paste (Note 4)","1 tsp cooking salt / kosher salt (sub 1/2 tsp table salt)"],"purpose":"Marinade:"},{"ingredients":["2 tbsp red curry paste (Note 4)","3/4 cup natural peanut butter, smooth (Note 5)","1/4 cup white sugar","2 tsp dark soy sauce (Note 6)","1 tsp cooking salt / kosher salt (sub 1/2 tsp table salt)","2 tbsp cider vinegar (Note 7)","3/4 cup water"],"purpose":"Thai Peanut Sauce:"},{"ingredients":["2 tbsp peanuts finely chopped","Lime wedges (optional)","Coriander / cilantro leaves and sliced red chilli (optional)"],"purpose":"Serving:"}]', '[{"description":"If cooking on a BBQ or over charcoal, soak skewers for 2 hours in water.","images":[],"step":1},{"description":"Thai Chicken Satay Skewers:","images":[],"step":2},{"description":"Mix together the chicken and Marinade with 1/4 cup of coconut milk, then set aside for at least 20 minutes, or overnight.","images":[],"step":3},{"title":"Thread onto skewers","description":"I do 4 to 5 pieces each.","images":[],"step":4},{"description":"Heat 1.5 tbsp oil in a large non stick pan over medium high heat.","images":[],"step":5},{"description":"Cook skewers in batches for 3 minutes on each side until golden.","duration":3,"images":[],"step":6},{"description":"Thai Peanut Sauce:","images":[],"step":7},{"description":"Place remaining coconut milk and Peanut Sauce ingredients in a saucepan over medium low heat.","images":[],"step":8},{"description":"Stir to combine then simmer, stirring every now and then, for 5 minutes.","duration":5,"images":[],"step":9},{"title":"Adjust consistency with water","description":"it should be a pourable but thickish sauce.","images":[],"step":10},{"description":"Cover with lid and keep warm while cooking skewers.","images":[],"step":11},{"description":"Pour some sauce into a bowl. Sprinkle with some peanuts - stir some through if you want.","images":[],"step":12},{"description":"Pile satay skewers onto a platter, sprinkle with remaining peanuts, coriander and chilli.","images":[],"step":13},{"description":"Serve with sauce on the side for dipping. Add a side of Jasmine Rice or Thai Fried Rice to complete the meal!","images":[],"step":14}]', '["gluten","peanuts","soy"]', '["keto_friendly","low_calorie"]', '{"mealType":["dinner","snack"],"cuisine":["Thai"],"categories":["asian-recipes","chicken-recipes","cuisines","iconic-dishes","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b9bef2f0ca1d', 'en', 'US', 'Hot and Sour Soup', 'Recipe video above. A firm Chinese starter favourite! A glossy soup broth that''s savoury, sour and as spicy as you want it to be, filled with mushrooms, tofu and bamboo shoots. Skip the chicken to make it meat free, or add shrimp/prawns or fish pieces. Serves 6 - 8 as a starter, or 4 as a light meal.', 'https://www.recipetineats.com/tachyon/2019/02/Hot-and-Sour-Soup_1_6.jpg', 20, 20, 40, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.22, "unit": "kg"}}, {"id": "ing_shiitake_mushrooms", "quantity": {"value": 12.0, "unit": "pack of 150g"}}, {"id": "ing_mushroom", "quantity": {"value": 12.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_chicken", "quantity": {"value": 0.22, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_tofu", "quantity": {"value": 0.417, "unit": "pack of 300g"}}, {"id": "ing_bamboo_shoots", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.094, "unit": "pack of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["220 g / 7oz chicken breast","12 dried shiitake mushrooms (or 150g/5oz fresh) (Note 1)","1/2 cup wood ear mushrooms (, chopped 1.5cm/ 3/5\" pieces (Note 1))"]},{"ingredients":["1 tsp dried chilli / red pepper flakes (, adjust spice to taste (Note 2))","2 tsp dark soy sauce (Note 3)","1 tbsp light soy sauce (Note 3)","1 tsp ginger (, finely grated)","1/2 tsp white pepper (sub black)","6 cups (1.5L/1.5qt) chicken or veg stock/broth (, low sodium)","1 tsp sesame oil","1 tsp sugar","1/4 cup (65 ml) white vinegar (adjust to taste)"],"purpose":"Hot and sour soup broth:"},{"ingredients":["125 g / 4oz firm tofu (~ 1 cup) (, cut into 1.2cm / 0.5\" cubes (Note 4))","1/4 cup bamboo shoots (, thinly sliced (Note 5))","2 eggs (, whisked)","1/4 cup (40g) cornstarch/cornflour","1/4 cup (125 ml) water","Salt to taste","1 shallot/scallion (, finely sliced)"],"purpose":"Soup:"}]', '[{"description":"Cover shiitake mushrooms with plenty of boiling water. Stand 20 - 30 minutes until soft, drain, then slice thinly. (Discard or reserve liquid for other use)","images":[],"step":1},{"description":"Poached chicken:","images":[],"step":2},{"description":"Place chicken broth, ginger, soy sauces, chilli, sugar, pepper and sesame oil in a large pot over medium high heat.","images":[],"step":3},{"description":"Once simmering, add chicken, cover and reduce heat so it''s simmering.","images":[],"step":4},{"description":"Cook 10 minutes, remove chicken and shred.","images":[],"step":5},{"description":"Add vinegar, shiitake, wood ear mushrooms, bamboo shoots, tofu and shredded chicken into the soup.","images":[],"step":6},{"description":"Stir, simmer for 10 minutes.","duration":10,"images":[],"step":7},{"description":"Mix cornflour with water. While stirring soup at a medium pace, slowly pour the cornflour mixture in (ensures no lumps).","images":[],"step":8},{"description":"When it starts simmering again, stir constantly and slowly pour egg in a thin stream - this will create the signature \"egg ribbons\".","images":[],"step":9},{"title":"Taste","description":"add salt if desired, more chilli if you want.","images":[],"step":10},{"description":"Add shallots and serve!","images":[],"step":11}]', '["egg","gluten","sesame","soy"]', '["high_protein","low_calorie"]', '{"mealType":["dinner","snack"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-soups","asian-takeout","chinese-recipes","dietary","dinner-tonight","low-calorie-recipes","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7dc28d39aab0', 'en', 'US', 'How to Tenderise Chicken for Stir Fries (Chinese secret!)', 'Ever notice how the chicken in stir fries at your favourite Chinese restaurant is incredibly tender, and how it''s just never as good at home? It''s because the chicken breast is tenderised, a method called "velveting chicken". Use this for the juiciest chicken breast you''ll ever have in stir fries and noodles! SCALE recipe - click on servings and slide.', 'https://www.recipetineats.com/tachyon/2019/03/Tenderise-velvet-chicken-cover-photo-square.jpg', 5, 0, 5, 3, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.019, "unit": "tub of 200g"}}]', '[{"ingredients":["250 g / 8 oz chicken breast slices OR bite size pieces (not whole pieces, Note 1)","3/4 tsp baking soda (bi-carb/bi-carbonate)"]}]', '[{"description":"Place chicken in a bowl and sprinkle baking soda all over the surface.","images":[],"step":1},{"description":"Toss with fingers to coat as evenly as possible.","images":[],"step":2},{"description":"Refrigerate 20 minutes for slices, 30 minutes for bite size pieces.","images":[],"step":3},{"description":"Rinse well in colander to remove baking soda.","images":[],"step":4},{"description":"Shake off then pat away excess water (doesn''t need to be 100% dry).","images":[],"step":5},{"title":"Use as directed in chosen recipe","description":"stir fries and noodles (see in post for suggested recipes). Can be marinated, cooked on the stove, deep fried, simmered in broth.","images":[],"step":6}]', '[]', '["gluten_free","low_calorie"]', '{"mealType":["dinner"],"cuisine":["American Chinese"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-recipes","chinese-recipes","good-to-know","stir-fries","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4fe0f880b8cf', 'en', 'US', 'How to tenderise beef (velveting beef)', 'Chinese restaurants tenderise economical cuts of beef so they are tender and juicy in stir fries. It''s also done for chicken. There''s a few methods - this baking soda way is the easiest, fastest and highly effective. Though I''m sharing this with beef stir fries in mind, don''t just limit yourself to Asian food. This beef can be used for any recipe calling for strips of beef to be cooked quickly, like Beef Stroganoff. Do not use this method for whole steaks (read Note 4).', 'https://www.recipetineats.com/tachyon/2015/03/How-to-Tenderise-Beef-Chinese-Method.jpg', 25, 0, 25, 2, '[{"id": "ing_beef", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.019, "unit": "tub of 200g"}}]', '[{"ingredients":["250 g / 8 oz stewing beef or other economical beef cuts (Note 1)","3/4 tsp baking soda / bi-carbonate soda (Note 2)"]}]', '[{"description":"Slice beef thinly against the grain. (Note 3)","images":[],"step":1},{"description":"Place in a bowl. Sprinkle over baking soda, toss with fingers to coat evenly.","images":[],"step":2},{"description":"Refrigerate for 30 to 40 minutes. (See Note 1 for different cuts)","duration":35,"images":[],"step":3},{"description":"Rinse beef well with tap water. Shake off excess water, then use paper towels to blot away excess water (doesn''t need to be 100% dry).","images":[],"step":4},{"description":"Proceed with recipe of choice. Beef can be marinated or seasoned before cooking, stir fried or deep fried, and it will be soft and tender, \"velvet\" like. Use for Stir Fries, Stir Fried Noodles, Beef Stroganoff and any other recipe calling for quick-cooked beef strips.","images":[],"step":5}]', '[]', '["gluten_free","high_protein","low_calorie"]', '{"mealType":["dinner"],"cuisine":["American Chinese","Chinese"],"categories":["asian-recipes","asian-takeout","beef-recipes","chinese-recipes","good-to-know","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2d254514e6f2', 'en', 'US', 'Egg Foo Young (Chinese omelette)', 'Recipe video above. This is how the Chinese do omelettes! Egg Foo Young was created as a recipe to use up leftovers, so make this your own using what you have - see Notes for the formula. Otherwise, use EITHER the prawn/shrimp or pork filling. Makes 4 small omelettes, serves 2 as meal with rice, or 4 as part of a banquet.', 'https://www.recipetineats.com/tachyon/2018/07/Egg-Foo-Yung-5.jpg', 10, 15, 25, 4, '[{"id": "ing_flour", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_egg", "quantity": {"value": 6.0, "unit": "carton of 12"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 2.0, "unit": "bag of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 4.0, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_one_filling_of_choice_below", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_shrimp", "quantity": {"value": 100.0, "unit": "kg"}}, {"id": "ing_pork", "quantity": {"value": 0.11, "unit": "kg"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 4.0, "unit": "bunch"}}]', '[{"ingredients":["4 tsp cornflour / corn starch","1 1/2 tbsp light soy sauce (, or all purpose (Note 2))","2 tsp Oyster Sauce","1 tbsp Chinese Cooking Wine (shaoxing wine) OR Mirin (Note 3)","1/2 tsp sesame oil","1 cup / 250 ml water","Dash of white pepper"],"purpose":"Sauce (Note 1 for Charlie option):"},{"ingredients":["6 eggs","2 cups bean sprouts (just eyeball it)","4 shallots/green onions (, white part only, sliced)","Salt and white pepper","2 tbsp vegetable oil","1 tsp sesame oil","1 garlic clove (, finely chopped)","ONE Filling of Choice, below (Prawn or Pork)"],"purpose":"Omelette:"},{"ingredients":["100 - 120g/3.5 - 4 oz chopped raw small prawns/shrimp (, peeled and deveined (Note 4))"],"purpose":"Option 1: For Prawn /Shrimp Egg Foo Young"},{"ingredients":["100 - 120g/3.5 - 4 oz ground/mince pork (or chicken, turkey, beef or veal)","1/2 tsp EACH soy sauce and Oyster Sauce","1/4 tsp sugar","Dash of sesame oil"],"purpose":"Option 2: For Pork Egg Foo Young :"},{"ingredients":["Sesame seeds, sliced green onion"],"purpose":"Garnish (optional):"}]', '[{"description":"Mix cornflour and soy sauce. Then add remaining ingredients.","images":[],"step":1},{"description":"Pour into a saucepan over medium heat. Bring to simmer, stirring constantly. Simmer for 1 minute until sauce thickens to thin syrup consistency. Remove from stove, set aside.","duration":1,"images":[],"step":2},{"title":"MICROWAVE option","description":"Microwave on high for 1 1/2 minutes. Stir very well, microwave for another 1 1/2 minutes until thickened. Mix well again.","images":[],"step":3},{"description":"Place pork in a bowl, add remaining ingredients. Use fork to mix through.","images":[],"step":4},{"description":"Whisk eggs in a bowl.","images":[],"step":5},{"description":"Add beansprouts, green onions, pork or prawns, salt and pepper. If using pork, crumble the raw pork in with fingers (see video). Mix through.","images":[],"step":6},{"description":"Heat 1/2 tbsp vegetable oil and drizzle of sesame oil in a non stick skillet over medium heat. Add a bit of garlic and quickly saute (10 seconds) and push into centre of skillet.","images":[],"step":7},{"description":"Ladle in 1/4 of batter. Use spatular to push edges in to form a round(ish) shape.","images":[],"step":8},{"description":"Cook until the underside is light golden (about 1 1/2 minutes) then flip and cook the other side for 1 minute. The raw meat will cook through in this time. Repeat with remaining egg to make 4 omelettes (use 2 pans if you can!).","duration":1,"images":[],"step":9},{"description":"Slide omelette onto plate. Pour over sauce. Sprinkle with sesame seeds and green onions, if using.","images":[],"step":10},{"description":"Serve with a side of rice and steamed vegetables of choice. Double the sauce if you want enough to pour over the rice and veggies! (Click on Servings to scale recipe up).","images":[],"step":11}]', '["egg","gluten","sesame","shellfish","soy"]', '["keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["American Chinese"],"categories":["asian-recipes","chinese-recipes","dinner-tonight","egg-recipes","prawns-shrimp","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0a70c1e4ca66', 'en', 'US', 'Homemade Thai Green Curry Paste', 'Recipe video above. Usually, the main reason to make homemade curry paste is because you just can''t get the same intense, fresh flavour in a jar. And while that holds true for green curry paste, the other very big advantage is that you can control the spiciness without compromising flavour or the signature green colour.', 'https://www.recipetineats.com/tachyon/2019/02/Homemade-Thai-Green-Curry-Paste_3.jpg', 15, 0, 15, 5, '[{"id": "ing_cayenne_pepper", "quantity": {"value": 0.1, "unit": "jar of 40g"}}, {"id": "ing_chilli", "quantity": {"value": 6.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_lemongrass", "quantity": {"value": 40.0, "unit": "bunch"}}, {"id": "ing_galangal", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 8.333, "unit": "pack of 3 heads"}}, {"id": "ing_shrimp", "quantity": {"value": 0.013, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.08, "unit": "jar of 50g"}}, {"id": "ing_turmeric", "quantity": {"value": 1.25, "unit": "jar"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_water", "quantity": {"value": 2.0, "unit": "L"}}]', '[{"ingredients":["4 green cayenne pepper chilis (, deseeded and chopped (Note 1))","6 Thai green chilis (, chopped (Note 1))","2 red shallots / eschallots (, chopped)","2 lemongrass stems (, trimmed and finely chopped (about 2.5 - 3 tbsp) (Note 2))","2 tbsp galangal (, grated (Note 3))","5 cloves garlic (, chopped)","2.5 tsp dried shrimp paste (Belacan) (Note 4)","2 tsp lime zest (, grated)","1 tsp ground coriander","1 tsp ground cumin","1/4 tsp white pepper","1/4 tsp turmeric","2 tbsp chopped coriander/cilantro root and stem (Note 5)","1/4 cup coriander / cilantro leaves (, loosely packed)","2 - 3 tbsp water (, as needed)"]}]', '[{"description":"Combine all ingredients except water in a powerful blender or food processor. I use my Vitamix because it makes the paste smoother.","images":[],"step":1},{"description":"Blend to a fine paste, scraping down the sides as you go. Add the water as required to help it blend (you may not need any as the herbs and chilis have moisture).","images":[],"step":2},{"description":"Use to make Thai Green Curry!","images":[],"step":3},{"description":"Best to use immediately. Otherwise, refrigerate for up to 2 days, or freeze for 1 month.","images":[],"step":4}]', '["shellfish"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["asian-recipes","cuisines","curry-recipes","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1b144c63090f', 'en', 'US', 'Chinese Crispy Pork Belly', 'Recipe video above. This is Chinese pork belly, just like you get from the Chinese BBQ meat shops! The best crackling in the world, with the signature bubbles, super crispy and golden. If pricking the skin is too daunting for you, use the Foolproof Easy Method (Note 7)', 'https://www.recipetineats.com/tachyon/2017/01/Crispy-Chinese-Pork-Belly-1.jpg', 20, 90, 110, 8, '[{"id": "ing_pork", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.045, "unit": "bottle of 500ml"}}, {"id": "ing_chinese_five_spice", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}]', '[{"ingredients":["1 pork belly, skin on (800 - 1.2kg / 1.6 - 2.4 lb) (Note 1)","1 1/2 tbsp Chinese cooking wine (Shaoxing wine) (Note 2)","1 tsp Chinese five spice powder (Note 3)","1 tsp white pepper (sub black pepper)","1/2 tsp salt","1 tbsp white vinegar (helps conduct heat evenly)","200 g / 7 oz rock salt (Note 4)"]}]', '[{"description":"Prepare Pork Belly","images":[],"step":1},{"description":"Use an ice pick, sharp metal skewer or another tool to prick tons and tons of holes in the skin. Avoid piercing int o the fat as best you can, and really ensure you do not pierce the flesh (Note 5)","images":[],"step":2},{"description":"Turn the pork belly upside down. Rub the flesh (not skin) with Chinese cooking wine, dribbling it on gradually. Sprinkle over five spice powder, salt and pepper. Rub all over flesh, including sides (not on skin).","images":[],"step":3},{"description":"Turn skin side up and place in a container. Dab skin dry with paper towels. Refrigerate uncovered for 12 hours (max 24 hrs, min 3 hrs).","images":[],"step":4},{"description":"Cook:","images":[],"step":5},{"description":"Preheat oven to 180C/350F (all oven types).","images":[],"step":6},{"description":"Remove pork from fridge. Place onto a large sheet of foil. Fold up sides of foil around the pork to enclose it snugly (see photos in post or video) with a 1.5cm / 2/5\" rim above the pork skin (to hold salt in).","images":[],"step":7},{"description":"Transfer pork to baking tray. Dab skin with paper towels.","images":[],"step":8},{"description":"Brush skin with vinegar.","images":[],"step":9},{"description":"Spread rock salt on the skin (the foil edges will stop it from falling down the sides).","images":[],"step":10},{"description":"Roast for 60 minutes.","duration":60,"images":[],"step":11},{"description":"Remove pork from oven and transfer onto work surface.","images":[],"step":12},{"description":"Switch to grill/broiler on medium high. Move shelf so it is at least 25cm/10\" from the heat source.","images":[],"step":13},{"description":"Fold down foil and scrape all the salt off the top and sides. Return pork only (i.e. discard foil) to baking tray.","images":[],"step":14},{"title":"Place under grill/broiler for 20","description":"25 minutes, rotating tray once, until skin is golden, crispy and puffed. (Note 6)","duration":22.5,"images":[],"step":15},{"description":"To Serve","images":[],"step":16},{"title":"Remove pork onto cutting board. Slice into 1","description":"1.5cm / 2/5 - 3/5\" thick slices, then into smaller slices like pictured in post.","images":[],"step":17},{"title":"Serve with ordinary yellow mustard","description":"or Hot English Mustard if you like spicy like me! Not Dijon, just ordinary American or other yellow mustard (yes really!). Sometimes it is served with white sugar on the side too. Add some fresh raw vegetables (I use cucumber and radish).","images":[],"step":18}]', '[]', '["gluten_free","high_protein","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chinese-recipes","dietary","gluten-free-recipes","iconic-dishes","main-dishes","modern-asian","pork-recipes","roasts","sunday-supper"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_de3df7ab583a', 'en', 'US', 'Chinese Cashew Chicken', 'Recipe video above. The soft, creamy crunch of cashews is a perfect addition to this saucy chicken stir fry! Truly stacks up to your favourite take out - read the glowing reviews! If using breast, consider tenderising it the Chinese way ("Velveting Chicken")', 'https://www.recipetineats.com/tachyon/2015/10/Cashew-Chicken_6.jpg', 15, 6, 21, 4, '[{"id": "ing_cornstarch", "quantity": {"value": 0.037, "unit": "pack of 400g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.045, "unit": "bottle of 500ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.09, "unit": "L"}}, {"id": "ing_roasted_cashews", "quantity": {"value": 112.5, "unit": "jar"}}]', '[{"ingredients":["1 tbsp cornstarch / cornflour","3 tbsp soy sauce (, all purpose or light (Note 1))","1 1/2 tbsp Chinese cooking wine or Mirin (Note 2)","3 tbsp oyster sauce","2 tsp sesame oil","Dash of white pepper (sub black)"],"purpose":"Sauce"},{"ingredients":["500g / 1 lb chicken thigh (, skinless boneless, cut into 2.5cm/1\" pieces (Note 3))","2 tbsp peanut oil (or vegetable oil)","2 garlic cloves (, minced)","1/2 onion (, chopped into 1.75 cm / 3/4\" pieces(yellow, brown or white))","1 green capsicum / bell pepper (, chopped into 2 cm / 0.8\" pieces)","6 tbsp water","3/4 cup roasted cashews (, unsalted)"],"purpose":"Stir Fry"}]', '[{"title":"Sauce","description":"Mix cornflour and soy sauce until there''s no lumps. Then add remaining Sauce ingredients and mix.","images":[],"step":1},{"title":"Marinate","description":"Transfer 2 tbsp Sauce to chicken, mix to coat. Set aside for 10 minutes+.","duration":10,"images":[],"step":2},{"title":"Cook","description":"Heat oil over high heat in a wok or heavy based skillet. Add the garlic and onion, cook for 1 minute.","duration":1,"images":[],"step":3},{"description":"Add chicken and cook for 2 minutes. Add capsicum and cook for 1 minute.","duration":2,"images":[],"step":4},{"description":"Add Sauce and water. Bring to simmer and cook, stirring, for 1 minute or until Sauce thickens.","duration":1,"images":[],"step":5},{"description":"Stir through cashews, remove from stove. Serve immediately with rice - or for a low carb, low cal option, try Cauliflower Rice!","images":[],"step":6}]', '["gluten","peanuts","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-recipes","chinese-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","most-popular","quick-and-easy","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3da0bdd640da', 'en', 'US', 'Chicken Vegetable Ramen Noodles', 'Recipe video above. A great quick Asian ramen noodle recipe that''s jam packed with a surprising amount of vegetables! Caramelise the chicken well - makes all the difference. Switch veg as desired. Also see the ground beef / mince version - Asian Beef Ramen Noodles.', 'https://www.recipetineats.com/tachyon/2019/01/Chicken-Ramen-Noodles_4.jpg', 10, 8, 18, 3, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.004, "unit": "pack of 500g"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_cabbage", "quantity": {"value": 6.0, "unit": "head"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_mirin", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["2 packets ramen or other instant noodles (, discard seasoning (Note 1))","1 tbsp oil","2 garlic cloves (, minced)","1/2 onion (, sliced)","200g / 7oz chicken thighs, cut into bite size pieces (Note 2)","1 1/4 cups (315 ml) water, plus more as needed","1 carrot (, cut into matchsticks)","1 small red capsicum / bell pepper (, sliced )","2 cups cabbage (, finely sliced (any type))"]},{"ingredients":["1 tbsp dark soy sauce (Note 3)","1 tbsp Oyster sauce (or Hoisin, Note 4)","2 tsp Hoisin sauce (or more Oyster sauce)","1 tbsp Mirin (Note 5)"],"purpose":"Sauce:"},{"ingredients":["Finely sliced green onion / shallots"],"purpose":"Garnishes (optional):"}]', '[{"description":"Mix Sauce.","images":[],"step":1},{"description":"Heat oil in a large skillet over high heat. Add onion and garlic, cook for 1 1/2 minutes until starting to go golden.","images":[],"step":2},{"description":"Add chicken and cook just until the outside mostly changes from pink to white.","images":[],"step":3},{"description":"Add Sauce and cook for 1 minute until chicken is quite caramelised.","duration":1,"images":[],"step":4},{"description":"Add carrot and capsicum, cook for 1 minute (chicken should now be nicely caramelised, see video).","duration":1,"images":[],"step":5},{"description":"Push chicken and veg to the side to make enough space for the noodles. Add water, place noodles in water.","images":[],"step":6},{"description":"When the water starts simmering on the edges, leave noodles for 45 seconds then turn.","duration":0.75,"images":[],"step":7},{"description":"Leave for 30 seconds, then untangle the noodles, then toss through the chicken and veg.","duration":0.5,"images":[],"step":8},{"description":"Add cabbage, toss for 1 minute until sauce reduces to coat the noodles and the noodles are cooked. (Note 6)","duration":1,"images":[],"step":9},{"description":"Serve immediately, garnished with green onions.","images":[],"step":10}]', '["gluten","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","chicken","chicken-breast-recipes","chicken-recipes","dinner-tonight","emergency-recipes","main-dishes","mains","noodles","one-pot-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_277f37b3f256', 'en', 'US', 'Spring Roll recipe', 'Recipe video above. Everybody''s favourite Spring Rolls, made at home! Nothing like the ones at suburban Chinese takeout joints with unidentifiable mushy fillings and overly greasy. These are shatteringly crisp and golden, just like they should be, and you will actually be able to taste the filling!', 'https://www.recipetineats.com/tachyon/2017/09/Spring-Rolls-6.jpg', 20, 10, 30, 15, '[{"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_pork_mince", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_shiitake_mushrooms", "quantity": {"value": 6.0, "unit": "pack of 150g"}}, {"id": "ing_carrot", "quantity": {"value": 225.0, "unit": "pack of 1kg"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 1.5, "unit": "bag of 250g"}}, {"id": "ing_cabbage", "quantity": {"value": 4.5, "unit": "head"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.013, "unit": "pack of 400g"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_bread", "quantity": {"value": 15.0, "unit": "loaf"}}, {"id": "ing_flour", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 6.0, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 1.0, "unit": "bottle of 500ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}]', '[{"ingredients":["1 tbsp oil","2 garlic cloves (, finely chopped or minced)","400 g / 13 oz pork mince ((ground pork), or chicken or turkey)","6 dried shiitake mushrooms soaked in boiling water OR 8 fresh (Note 1)","1 1/2 cups shredded carrot (1 large or 2 small)","1 1/2 cups (heaped) bean sprouts","1 1/2 cups (packed) shredded green cabbage (any type is fine)","1 tsp cornflour / cornstarch","1 1/2 tbsp Oyster Sauce","2 tsp soy sauce (light or all purpose is best, dark is also ok)"],"purpose":"Filling:"},{"ingredients":["15 – 20 spring roll wrappers, defrosted (21.5 cm / 8” squares) OR 35 - 40 small spring roll wrappers (Note 2), or Egg Roll wrappers to make Egg Rolls (Note 6)","2 tsp cornflour (for sealing rolls)","1 tbsp water (for sealing rolls)","Oil for frying (I use vegetable) OR oil spray for baking (I use canola)"],"purpose":"Spring Rolls:"},{"ingredients":["2 tsp cornflour/ cornstarch","2 tbsp water","½ cup apple cider vinegar","1/3 cup brown sugar (adjust to taste)","2 tbsp tomato ketchup","2 tsp soy sauce"],"purpose":"Sweet and Sour Sauce (makes ~ 2/3 cup):"}]', '[{"description":"Heat oil in a skillet or wok over high heat. Add garlic, stir quickly, then add pork. Cook, breaking it up as you go, until it turns white.","images":[],"step":1},{"description":"Add carrot, bean sprouts, cabbage and mushrooms. Cook for 3 minutes or until vegetables are wilted. Add cornflour, soy sauce and Oyster sauce, cook for 1 minute until the liquid is gone. The Filling should not be watery, it should be kind of sticky (watery filling = soggy spring rolls = ? ).","duration":3,"images":[],"step":2},{"title":"Cool Filling (super speedy","description":"spread on tray, refrigerate 5 minutes). (Hot filling = spring rolls burst open = ? )","images":[],"step":3},{"description":"Mix cornflour and water in a small bowl (for sealing the rolls).","images":[],"step":4},{"description":"Carefully peel off one spring roll wrapper, keep the others covered under a damp tea towel.","images":[],"step":5},{"description":"Place the wrapper with the SMOOTH SIDE DOWN (Note 3) in a diamond position. Place a very heaped dessert spoon of filling on the bottom. Roll up halfway, fold sides in, then finish rolling. Use cornflour sludge to seal. (Watch VIDEO below). They should be about 12 cm / 5\" long, 2.5cm / 1\" wide once wrapped.","images":[],"step":6},{"description":"Pour enough oil in a wok or large saucepan (Note 4) so it is double the height of the spring rolls. Heat on medium high until hot - stick a bamboo chopstick or wooden spoon handle in, if rapid bubbles appear, then it''s hot enough.","images":[],"step":7},{"title":"Carefully place spring rolls in the oil (about 4","description":"5 at a time) and cook, turning occasionally, until deep golden - around 1 1/2 - 2 minutes. Transfer to paper towels to drain.","images":[],"step":8},{"description":"Repeat with remaining spring rolls. Serve while hot with Sweet and Sour Sauce!","images":[],"step":9},{"description":"Place spring rolls on a rack and place the rack on a tray. Spray very generously with oil all over (use canola or other natural oil). Bake at 200C/400F (standard) or 180C/350F (fan / convection) for 20 to 25 minutes until golden and crispy - no need to turn.","duration":22.5,"images":[],"step":10},{"description":"SWEET and SOUR SAUCE:","images":[],"step":11},{"description":"Combine ingredients in a small saucepan over medium heat. Bring to simmer, stirring regularly, then simmer until it thickens to taste (about 3 - 5 minutes).","images":[],"step":12}]', '["egg","gluten","soy"]', '["low_calorie"]', '{"mealType":["snack"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chinese-recipes","deep-fried-recipes","modern-asian","super-bowl-party-food","yum-cha-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_037ee287ff80', 'en', 'US', 'Thai Coconut Soup', 'Recipe video above. This amazing quick & easy Thai Coconut Soup is made from scratch!! Tastes like a Thai coconut curry, a cross between Tom Yum and Laksa soups. This recipe is all about the soup broth, so put whatever you want into the soup! This is the noodle soup version of this Poached Salmon in Coconut Lime Sauce.', 'https://www.recipetineats.com/tachyon/2018/10/Coconut-Noodle-Soup_3.jpg', 8, 12, 20, 2, '[{"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_shrimp", "quantity": {"value": 10.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_lemongrass", "quantity": {"value": 20.0, "unit": "bunch"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.2, "unit": "jar of 50g"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.4, "unit": "pack of 500g"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 1.0, "unit": "bag of 250g"}}, {"id": "ing_lime", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 tbsp vegetable oil","10 prawns/shrimp (, peeled and deveined (Note 1))","2 garlic cloves (, finely grated)","2 tsp ginger (, finely grated)","1 lemongrass (, peeled, finely grated (Note 2))","1 tbsp brown sugar","1 1/2 tbsp fish sauce (or soy sauce)","2 tsp curry powder (Note 3)","1 tsp coriander powder","2 tsp chilli garlic paste or other chilli paste (, adjust to taste (Note 4))","400 g/14oz coconut milk (Note 5)","2 cups /500ml chicken broth (or vegetable)","2 tsp lime zest (1 lime)","200 g / 7 oz fresh egg noodles, (prepared per packet (other noodles Note 6))","Big handful bean sprouts"]},{"ingredients":["Lime wedges","Fresh coriander/cilantro leaves","Sliced red onion (or sliced green onion), Fried Asian shallots (Note 7), sliced red chilli, more chilli paste (optional)"],"purpose":"Toppings / for serving:"}]', '[{"description":"Heat oil in a large saucepan over high heat. Add prawns and sear both sides until light golden (doesn''t need to cook inside). Remove onto plate.","images":[],"step":1},{"description":"Turn heat down to medium. If pot is looking dry, add a touch of extra oil.","images":[],"step":2},{"description":"Add garlic, ginger and lemongrass. Saute for 20 seconds until garlic is golden.","duration":0.3333333333333333,"images":[],"step":3},{"description":"Add sugar and fish sauce. Stir and cook for 30 seconds - it should look like caramel.","duration":0.5,"images":[],"step":4},{"description":"Add chilli paste, coriander and curry powder. Stir and cook for 30 seconds.","duration":0.5,"images":[],"step":5},{"description":"Add chicken broth and coconut milk. Stir and bring to simmer.","images":[],"step":6},{"description":"Simmer for 2 minutes, then add lime zest and return prawns into broth.","duration":2,"images":[],"step":7},{"description":"Cook for 2 minutes just to reheat and finish cooking the prawns.","duration":2,"images":[],"step":8},{"description":"Place noodles in bowl. Ladle over soup.","images":[],"step":9},{"description":"Top with bean sprouts and coriander, plus toppings of choice (chilli, red onion, Asian fried shallots).","images":[],"step":10},{"description":"Squeeze over lime juice to taste. Slurp and be happy!","images":[],"step":11}]', '["egg","fish","gluten","shellfish","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Asian","Thai"],"categories":["asian-recipes","asian-soups","cuisines","dinner-tonight","main-dishes","prawns-shrimp","quick-and-easy","soup-recipes","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c22559ce5ce4', 'en', 'US', 'Kung Pao Chicken', 'Recipe video above. Kung Pao chicken - done right! The flavour of this sauce is very similar to proper restaurant versions, with a great balance of savoury-sweet and sour with the numbing tingle from Sichuan pepper. Use whole Sichuan peppercorns if you have them, otherwise ground is fine (which is what I use).', 'https://www.recipetineats.com/tachyon/2018/09/Kung-Pao-Chicken.jpg', 15, 10, 25, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.025, "unit": "pack of 400g"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_water", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 2.5, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 6.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.06, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.15, "unit": "jar of 50g"}}, {"id": "ing_whole_peanuts", "quantity": {"value": 112.5, "unit": "jar"}}]', '[{"ingredients":["1 lb / 500g chicken thigh (, cut into bite size pieces)"],"purpose":"Chicken"},{"ingredients":["2 tsp cornflour / cornstarch","1 tbsp light soy sauce (Note 2)","1.5 tbsp dark soy sauce (Note 3)","2 tbsp Chinese black vinegar (Note 4)","1 tbsp Chinese cooking wine (Note 5)","3 tbsp sugar (, any)","1/2 tsp sesame oil","1/3 cup water"],"purpose":"Sauce"},{"ingredients":["2 tbsp peanut oil (or other cooking oil)","2 garlic cloves (, minced)","1 tsp ginger (, finely chopped)","6 - 10 dried chillies (adjust to taste), cut into 2cm/ 3/4\" pieces, most seeds discarded (Note 7)","3 green onions (, cut into 2cm/ 3/4\" pieces, white parts separated from green)","1.5 tsp ground sichuan peppercorns (, adjust to taste (Note 6))","3/4 cup whole peanuts (or 1/2 cup halved) (, roasted unsalted)"],"purpose":"Stir Fry"}]', '[{"description":"Sauce & Marinade Chicken:","images":[],"step":1},{"description":"Mix cornflour and soy sauce in a small bowl until cornflour is dissolved. Then mix in remaining Sauce ingredients EXCEPT water.","images":[],"step":2},{"description":"Pour 1.5 tbsp Sauce over chicken. Toss to coat, set aside for 10 - 20 minutes.","duration":15,"images":[],"step":3},{"description":"Add water into remaining Sauce.","images":[],"step":4},{"description":"Heat oil in wok over high heat. Add garlic, ginger and chillies. Cook for 30 seconds or until fragrant.","duration":0.5,"images":[],"step":5},{"description":"Add chicken, cook until it turns white, then add the white part of the green onions. Cook until chicken is cooked through - about 2 minutes.","images":[],"step":6},{"description":"Add Sauce and Sichuan pepper. Bring to simmer, mixing constantly, until almost all the sauce reduces to a thick syrup.","images":[],"step":7},{"description":"Just before the end, mix through peanuts and green part of the green onions. Also check spiciness - add more Sichuan pepper if you can handle the heat!","images":[],"step":8},{"title":"Serve immediately with rice","description":"or for a low carb, low cal option, try Cauliflower Rice!","images":[],"step":9}]', '["gluten","peanuts","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-recipes","chinese-recipes","dinner-tonight","main-dishes","modern-asian","most-popular","quick-and-easy","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e49ada168e82', 'en', 'US', 'One Pot Chinese Chicken and Rice', 'Recipe video above. It''s like fried rice and Chinese chicken made in one pot! If you can''t find Chinese broccoli, see notes for how to make with other vegetable options. A terrific quick and easy dinner!', 'https://www.recipetineats.com/tachyon/2018/09/One-Pot-Chinese-Chicken-and-Rice_3.jpg', 10, 20, 30, 4, '[{"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_broccoli", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_white_rice", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.06, "unit": "bottle of 500ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1 tbsp oil","2 garlic cloves (, minced)","1 tsp ginger (, grated)","1 onion (, finely chopped)","500g (1 lb) chicken thighs (, skinless boneless, halved (Note 1))","1 big bunch Chinese Broccoli with thick stems (Note 2)"]},{"ingredients":["1 cup (180g) uncooked white rice ( (Note 3))","1 1/2 cups (375 ml) chicken broth (, low salt)"],"purpose":"Rice:"},{"ingredients":["2 cloves garlic (, small, chopped)","2 tbsp Chinese cooking wine (or Mirin (Note 4))","3 tbsp oyster sauce (or sub with Hoisin)","1 1/2 tbsp dark soy sauce (Note 5)","1/4 tsp white pepper (or black)"],"purpose":"Sauce:"},{"ingredients":["green onion (, sliced)","Sesame seeds"],"purpose":"Garnish:"}]', '[{"description":"Mix Sauce in a large bowl. Add chicken and set aside to marinate for 10 minutes to overnight.","duration":10,"images":[],"step":1},{"description":"Cut Chinese broccoli stems cut into 2.5 cm/1\" pieces, leafy part 5cm/2.5cm pieces.","images":[],"step":2},{"description":"Heat oil in a large pot over medium high heat. Remove chicken from marinade, shaking off excess marinade - RESERVE marinade!","images":[],"step":3},{"title":"Cook both sides until golden","description":"about 90 seconds on each side, don''t let them burn! Remove chicken onto plate.","images":[],"step":4},{"description":"Add a touch of oil if pot is dry. Add onion, garlic and ginger, cook for 2 minutes until tinged with gold.","duration":2,"images":[],"step":5},{"description":"Add rice, stir to coat grains in oil. Add broth, reserved Marinade and Chinese broccoli stems. Stir.","images":[],"step":6},{"description":"Place chicken across the top, pour in juices pooled on plate. Cover, bring to simmer then lower heat to medium.","images":[],"step":7},{"description":"Cook for 12 -15 minutes or until liquid is absorbed (tilt pot to check).","duration":13.5,"images":[],"step":8},{"description":"Remove from heat. Working quickly, scatter Chinese broccoli leaves across surface, clamp lid back on.","images":[],"step":9},{"description":"Rest for 10 minutes. Remove lid, toss rice and serve, garnished with sesame seeds and green onions. A dollop of your favourite chilli paste wouldn''t go astray either!","duration":10,"images":[],"step":10}]', '["gluten","sesame","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","chicken","chicken-breast-recipes","chicken-recipes","chinese-recipes","dinner-tonight","main-dishes","mains","one-pot-recipes","quick-and-easy","rice-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c69c2adb2b4d', 'en', 'US', 'Wonton Soup', 'Recipe VIDEO above. Homemade wontons are amazing! No fillers, just real ingredients in the filling. Terrific standby freezer meal!', 'https://www.recipetineats.com/tachyon/2016/09/Wontons_4.jpg', 20, 15, 35, 50, '[{"id": "ing_wonton_wrappers", "quantity": {"value": 50.0, "unit": "unit"}}, {"id": "ing_pork_mince", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_shrimp", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.06, "unit": "bottle of 500ml"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.3, "unit": "pack of 100g"}}, {"id": "ing_chicken", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.06, "unit": "bottle of 500ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.3, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_bok_choy", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 40.0, "unit": "pack of 500g"}}]', '[{"ingredients":["50 - 60 wonton wrappers (Note 1)"]},{"ingredients":["200 g / 7 oz lean pork mince (ground pork)","200 g / 7 oz peeled prawns / shrimp (, roughly chopped)","1 tbsp ginger (, finely grated (1.5\" / 3cm piece))","2 shallots / green onions (, finely chopped (5 tbsp))","1 tbsp light soy sauce (Note 2)","2 tbsp Chinese cooking wine (Shaoxing wine) (Note 3)","1/2 tsp salt","2 tbsp sesame oil, toasted (Note 4)"],"purpose":"Wonton Filling"},{"ingredients":["3 cups / 750 ml chicken broth (Note 5)","2 garlic cloves (, smashed (6))","⅓\" / 1 cm piece of ginger (, sliced (optional, but highly recommended))","1½ tbsp light soy sauce (Note 2)","2 tsp sugar (any)","1½ tbsp chinese cooking wine (Note 3)","¼ - ½ tsp sesame oil"],"purpose":"Broth (for 2 servings)"},{"ingredients":["Shallots / scallions (, finely chopped)","Bok choy (, quartered, or Chinese broccoli cut into 10cm /4\" lengths (optional))","40 - 50 g / 1.5 - 1.75 oz dried egg noodles per person (, (optional) (8))"],"purpose":"To Serve"}]', '[{"description":"Place Filling ingredients in a bowl. Use a potato masher to mash until fairly smooth - about 20 mashes. Don''t turn the prawn into a complete paste, small chunks are good.","images":[],"step":1},{"description":"Wrapping (See photos and video):","images":[],"step":2},{"description":"Use My Way (better Wonton Soup experience!) or the Asian Grocery Store Way (easier to pack for freezing).","images":[],"step":3},{"description":"Lay Wontons on work surface. Use 2 teaspoons to put the Filling on the wontons. Work in batches of 5 if starting out, up to 15 or 20 if confident. Brush 2 edges with water. Fold to seal, pressing out air. Brush water on one corner and bring corners together, pressing to seal.","images":[],"step":4},{"description":"Place wrapped wontons into a container with a lid as you work (so they don''t dry out).","images":[],"step":5},{"description":"Cooking/Freezing:","images":[],"step":6},{"title":"To cook","description":"bring a large pot of water to boil. Place wontons in water and cook for 4 minutes or until they float. Remove with slotted spoon straight into serving bowls. Ladle over broth.","duration":4,"images":[],"step":7},{"title":"To freeze","description":"Freeze uncooked in airtight containers. Cook from frozen for 6 to 8 minutes. IMPORTANT: Do not freeze if you made this with defrosted frozen prawns. (Note 11)","duration":7,"images":[],"step":8},{"description":"Place Broth ingredients in a saucepan over high heat. Add white ends of scallions/shallots if leftover from Wonton filling.","images":[],"step":9},{"description":"Place lid on, bring to simmer then reduce to medium high and simmer for 5 - 10 minutes to allow the flavours to infuse. Pick garlic and ginger out before using.","duration":7.5,"images":[],"step":10},{"description":"If using vegetables, blanch in the soup broth and place in serving bowl.","images":[],"step":11},{"description":"Prepare noodles according to packet directions (if using noodles). Place in serving bowl with cooked wontons and blanched vegetables.","images":[],"step":12},{"description":"Ladle over soup. Serve!","images":[],"step":13}]', '["egg","gluten","sesame","shellfish","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-soups","asian-takeout","chinese-recipes","dietary","dumplings","iconic-dishes","low-calorie-recipes","main-dishes","most-popular","noodles","soup-recipes","yum-cha-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2ae7b968998d', 'en', 'US', 'Poached Salmon in Coconut Lime Sauce', 'Recipe video above. Poached Salmon in a coconut lime sauce that tastes like a Thai coconut curry - except it''s super quick and easy to make! Even though the salmon is poached, it''s well worth searing lightly to brown for the extra flavour on both the salmon and in the sauce.', 'https://www.recipetineats.com/tachyon/2018/09/Poached-Salmon-in-Coconut-Lime-Sauce_2.jpg', 10, 15, 25, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_lemongrass", "quantity": {"value": 20.0, "unit": "bunch"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.01, "unit": "pack of 100g"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_lime", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_steamed_asian_greens", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["4 salmon fillets (, 180g/6oz each preferably skinless (Note 1))","Salt and pepper","2 tbsp oil (, separated)","2 garlic cloves (, finely grated)","2 tsp ginger (, finely grated)","1 lemongrass (, peeled, finely grated (Note 2))","1 tbsp brown sugar","1 tsp chilli garlic paste (or other chilli paste, adjust to taste (Note 3))","400 g/14oz coconut milk (Note 2)","1 tbsp fish sauce (or soy sauce)","2 tsp lime zest (1 lime)","Lime juice (, to taste)"]},{"ingredients":["Fresh coriander/cilantro leaves (, finely chopped (recommended))","Finely sliced large red chillies (optional)","Vermicelli noodles OR (, soaked per packet, or rice)","Steamed jasmine rice","Steamed Asian greens"],"purpose":"Garnish/serving:"}]', '[{"description":"Sprinkle both sides of salmon with salt and pepper.","images":[],"step":1},{"description":"Heat 1 tbsp oil in a non stick pan or well seasoned skillet over medium high heat. Add salmon, skin side up, and sear for just 1 1/2 minutes until golden. Turn salmon and cook the other side just for 1 minute, then remove onto a plate (should still be raw inside).","duration":1,"images":[],"step":2},{"description":"Turn heat down to medium low and allow skillet to cool.","images":[],"step":3},{"description":"Heat remaining 1 tbsp oil. Add garlic, ginger and lemongrass. Cook until garlic is light golden ~ 1 minute.","images":[],"step":4},{"description":"Add sugar and cook for 20 seconds until it becomes a caramel (see video). Then stir in chilli paste.","duration":0.3333333333333333,"images":[],"step":5},{"description":"Add coconut milk and stir, scraping the bottom of the skillet to dissolve any bits stuck on the base into the sauce.","images":[],"step":6},{"description":"Stir in fish sauce, increase heat to medium. Simmer for 2 minutes.","duration":2,"images":[],"step":7},{"description":"Place salmon into the sauce, lower heat and simmer gently for 4 minutes, or until just cooked.","duration":4,"images":[],"step":8},{"description":"Remove salmon, stir in lime zest and juice to taste. Adjust salt to taste with fish sauce.","images":[],"step":9},{"description":"Serve salmon over noodles or rice. Spoon over sauce, garnish with coriander and chili if using.","images":[],"step":10}]', '["fish","gluten","soy"]', '["high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Thai-ish"],"categories":["asian-recipes","cuisines","dinner-tonight","fish-recipes","quick-and-easy","salmon-recipes","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ac4a42795f42', 'en', 'US', 'Massaman Curry', 'Recipe video above. Not the fastest recipe in the world, but worth it! Rich and beautifully fragrant with the signature hint of smokiness, this mild curry is one of the most popular Thai curries ever. While many restaurants tend to tone down the spices and substantially increase the sugar, this recipe is based on authentic versions by Thai food authorities including David Thompson and Sujet Saenkham of Spice I Am. Super easy to adapt to other proteins - see notes! STORE BOUGHT CURRY PASTE version - see bottom of recipe', 'https://www.recipetineats.com/tachyon/2018/08/Massaman-Curry_3.jpg', 30, 120, 150, 4, '[{"id": "ing_lemongrass", "quantity": {"value": 20.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 6.0, "unit": "pack of 100g"}}, {"id": "ing_onion", "quantity": {"value": 4.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 8.333, "unit": "pack of 3 heads"}}, {"id": "ing_galangal", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_water", "quantity": {"value": 4.0, "unit": "L"}}, {"id": "ing_round_clove", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_cumin", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_round_nutmeg", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_coriander", "quantity": {"value": 0.075, "unit": "bunch"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cinnamon", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_beef", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_cinnamon_quill", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_star_anise", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_tamarind_paste_puree", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_potato", "quantity": {"value": 2.0, "unit": "bag of 2kg"}}, {"id": "ing_peanuts", "quantity": {"value": 0.113, "unit": "jar"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1 lemongrass (Note 1)","6 dried red Asian chillis (not Thai! Note 2)","4 eschallots (, peeled (Note 3))","5 cloves garlic (, unpeeled)","3 cm / 2.25\" galangal piece (, peeled, cut into 3/4 cm / 1/2\" slices (Note 4))","4 - 6 tbsp water"],"purpose":"Spice Paste:"},{"ingredients":["1/2 tsp ground cloves","3/4 tsp cumin","1/8 tsp ground nutmeg","3/4 tsp coriander","1/2 tsp cardamom","1/2 tsp cinnamon"],"purpose":"Spice Paste Dried Spices:"},{"ingredients":["700 g / 1.4lb beef chuck (, cut into 4cm / 2.5\" cubes (Note 5))","500 ml / 2 cups beef broth (, low sodium)","2 bay leaves"],"purpose":"Beef:"},{"ingredients":["1/4 cup / 65 ml vegetable oil","400 ml / 14 oz coconut milk (full fat, 1 can)","1 cinnamon quill","1 star anise","1 tsp tamarind paste/puree (Note 6)","1 tbsp fish sauce","1 tbsp white sugar","2 medium-small potatoes (, peeled and cut into 2.5cm / 1\" pieces)"],"purpose":"Curry Sauce:"},{"ingredients":["3 tbsp peanuts (, roughly chopped)","Finely sliced red chilli (optional)","Asian fried shallots (optional, Note 7)","Steamed jasmine rice"],"purpose":"Garnish & serving:"}]', '[{"description":"Lemongrass (see video):","images":[],"step":1},{"description":"Remove reedy outer layers and trim lemongrass per Note 1.","images":[],"step":2},{"description":"Reserve all the trimmings (for beef). Finely chop the white part (for paste.","images":[],"step":3},{"description":"Place Beef ingredients in a medium saucepan. Liquid should almost cover beef but not completely - if not, add water.","images":[],"step":4},{"description":"Add lemongrass trimmings.","images":[],"step":5},{"description":"Bring to boil over high heat, then reduce heat and simmer gently for 1.5 - 2 hours until beef is fork tender.","images":[],"step":6},{"description":"Remove beef. If there''s much more than 1.5 cups liquid, simmer to reduce. Set liquid aside.","images":[],"step":7},{"description":"Char Aromatics (char = flavour!):","images":[],"step":8},{"description":"Place heavy based skillet over high heat until smoking (no oil).","images":[],"step":9},{"description":"Add eschalot, garlic and galangal in skillet. Get a nice char on them, then remove (~1.5 minutes).","images":[],"step":10},{"description":"Add dried chillies into skillet, char 10 seconds or so on each side until charred, then remove.","images":[],"step":11},{"title":"Once cool enough to handle","description":"Grate galangal. Peel garlic. Break chillies in half, shake out seeds and discard.","images":[],"step":12},{"description":"Spice Paste Dried Spices:","images":[],"step":13},{"description":"Wipe the skillet used above or use a clean one. Heat on medium heat, add Spice Paste Dried Spices. Toast for 30 seconds or until they start to smell fragrant - do not let them burn. Immediately transfer into bowl.","duration":0.5,"images":[],"step":14},{"description":"Place chillies in food processor. (Note 8) Blitz until finely chopped.","images":[],"step":15},{"description":"Add galangal, finely chopped lemongrass, the toasted Spice Paste Dried Spices, and remaining Spice Paste ingredients, starting with 4 tbsp water. Blitz until smooth - add more water if required.","images":[],"step":16},{"description":"Place oil in a pot or large skillet over medium high heat. Add curry paste and cook for 3 minutes until the liquid has cooked out and it''s thick and fragrant.","duration":3,"images":[],"step":17},{"description":"Add coconut milk, stir to incorporate.","images":[],"step":18},{"description":"Add cinnamon, star anise and reserved beef braising liquid. Reduce heat to medium and simmer for 3 minutes.","duration":3,"images":[],"step":19},{"description":"Stir in fish sauce, tamarind and sugar, stir.","images":[],"step":20},{"description":"Add potatoes and cook for 7 minutes or until potatoes are tender, turning as required.","duration":7,"images":[],"step":21},{"description":"Add beef and simmer for 2 minutes or until sauce has reduced and thickened.","duration":2,"images":[],"step":22},{"title":"Adjust","description":"saltiness with fish sauce, sour with tamarind and sweet with sugar. The taste should be sweet, salty and sour, with more emphasis on the sweet and sour notes. Top up with a little water if the curry seems too thick","images":[],"step":23},{"description":"Serve over jasmine rice, garnished with peanuts (essential!) plus optional crispy Asian shallots and fresh chillies.","images":[],"step":24}]', '["fish"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["asian-recipes","beef-recipes","cuisines","curry-recipes","iconic-dishes","main-dishes","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_723ad7b04adb', 'en', 'US', 'Chinese Ham Bone Rice Soup (Congee)', 'Recipe video above. The ham version of the traditional Chinese rice soup known as Congee - Rice slow cooked until it breaks down to thicken the broth flavoured with ham bone. Every year, the Chinese fight over leftover Christmas ham bones to make this! :) But actually, using a store bought ham hock is safer - see note 1.', 'https://www.recipetineats.com/tachyon/2018/08/Ham-Bone-Rice-Soup-Congee_9.jpg', 10, 150, 160, 5, '[{"id": "ing_ham_bone_hock", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_white_rice", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 2.25, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1 kg (2 lb) ham bone / hock (Note 1)","1 1/4 cups long grain white rice (, uncooked)","9 cups (2.25 L or 2.25 QT) water"]},{"ingredients":["Salt & white pepper","Finely sliced green onion","Fried asian shallots / onions or something else crunchy (, optional (Note 2))","Sesame oil (, optional)"],"purpose":"Garnishes / finishes:"}]', '[{"description":"Place bone, rice and water in a large pot, slow cooker or pressure cooker. Cover with lid.","images":[],"step":1},{"description":"Cook using preferred method (times below), or until meat on ham is tender enough to shred.","images":[],"step":2},{"description":"Remove ham from soup, shred meat. Discard fatty / thick skin and sinew, keep bone. Use scissors if needed to chop meat.","images":[],"step":3},{"description":"Stir rice well, then return meat AND bone into soup.","images":[],"step":4},{"description":"Cook using preferred method, until rice is broken down and soup has a porridge like consistency - see video.","images":[],"step":5},{"description":"Remove bone. Stir vigorously, then adjust consistency with water if desired. Or simmer uncovered if necessary to thicken. Adjust salt to taste (I usually just need a pinch), add a dash of pepper.","images":[],"step":6},{"description":"Serve rice soup garnished with green onions, a sprinkle of Asian Fried Shallots and drizzle of sesame oil.","images":[],"step":7},{"title":"Storage tip","description":"Return bone into the soup, it continues to add flavour.","images":[],"step":8},{"description":"Cook times:","images":[],"step":9},{"title":"Stove: Simmer on low for 1 3/4","description":"2 hours (no stirring), shred meat, then on low for 30 minutes, stirring every now and then.","duration":30,"images":[],"step":10},{"title":"Slow Cooker","description":"Low for 8 hours, shred meat, then low for 1 - 2 hours.","images":[],"step":11},{"title":"Pressure Cooker","description":"High for 50 minutes, shred meat, then high for 15 minutes or 20 minutes on sauté function.","duration":50,"images":[],"step":12}]', '["sesame"]', '["gluten_free","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-soups","chinese-recipes","dietary","dinner-tonight","emergency-recipes","gluten-free-recipes","leftover-ham-recipes","main-dishes","quick-and-easy","rice-recipes","slow-cooker-recipes","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8c05ae3b1308', 'en', 'US', 'Char Kway Teow', 'Recipe video above. Epic Malaysian street food favourite - made at home! Use the Base Recipe if you''re a capable cook with a powerful gas stove and a good cast iron wok or large heavy based skillet. Otherwise, I recommend using the Easier Method.', 'https://www.recipetineats.com/tachyon/2018/07/Char-Kway-Teow_6.jpg', 15, 5, 20, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_lard", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_shrimp", "quantity": {"value": 10.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_sausages", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 2.5, "unit": "bag of 250g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.1, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy", "quantity": {"value": 5.0, "unit": "unit"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.1, "unit": "bottle of 250ml"}}]', '[{"ingredients":["500 g / 1 lb fresh wide rice noodle (Note 1)","2 tbsp lard (, or vegetable oil (Note 2))","2 tbsp vegetable oil (, separated)","10 small prawns/shrimp (, shelled and deveined)","2 garlic cloves (, finely chopped)","1 Chinese sausage / Lup Chong Sausage (, sliced thinly on the diagonal (Note 3))","5 cm / 2\" piece of fried fish cake (, sliced thinly (Note 4))","20 stems garlic chives (, cut into 4 pieces (Note 5))","2 1/2 cups bean sprouts","2 eggs (, whisked)"]},{"ingredients":["5 tsp dark soy sauce (Note 6)","4 tsp light soy (Note 6)","2 tsp oyster sauce (Note 6)","4 tsp kecap manis / sweet soy sauce (Note 6)"],"purpose":"Sauce:"}]', '[{"description":"Mix Sauce together.","images":[],"step":1},{"description":"Do not attempt to pull noodles apart while cold and hard - they break.","images":[],"step":2},{"description":"Place whole packet in microwave, heat on high for 1 1/2 minutes - 2 minutes until warm and pliable, not hot, turning packet over as needed.","images":[],"step":3},{"description":"Handle carefully and measure out 500g/1 lb noodles into a heatproof bowl. Separate noodles stuck together.","images":[],"step":4},{"description":"If noodles become cold and brittle before cooking, cover with cling wrap and microwave for 30 seconds to make warm (not hot, just warm) to reduce breakage.","duration":0.5,"images":[],"step":5},{"description":"Cook using Base Recipe (capable cooks) or Easier Method.","images":[],"step":6},{"title":"Cooking","description":"BASE Recipe:","images":[],"step":7},{"description":"Heat lard and 1 tbsp oil in a wok or very large heavy based skillet over high heat. Swirl around the wok.","images":[],"step":8},{"description":"When it starts smoking, add prawns. Cook for 30 seconds.","duration":0.5,"images":[],"step":9},{"description":"Add garlic, stir for 10 seconds.","duration":0.16666666666666666,"images":[],"step":10},{"description":"Add noodles, then using both hands on the handle, toss 4 times until coated with oil (or gently fold using a spatula + wooden spoon, see video).","images":[],"step":11},{"description":"Add Chinese sausage and fish cake, toss or gently fold 4 times.","images":[],"step":12},{"description":"Add bean sprouts and garlic chives, toss or gently fold 6 times.","images":[],"step":13},{"description":"Push everything to one side, add remaining 1 tbsp oil. Add egg and cook, moving it around until mostly set - about 1 minute. Use wooden spoon to chop it up roughly.","images":[],"step":14},{"description":"Pour Sauce over noodles, then toss to disperse Sauce through the noodles. Pause between tosses to give the noodles a chance to caramelise on the edges.","images":[],"step":15},{"description":"Serve immediately!","images":[],"step":16},{"title":"Cooking","description":"EASIER Method:","images":[],"step":17},{"description":"Heat 1 tbsp oil in a large non stick skillet over high heat.","images":[],"step":18},{"description":"When heated, add shrimp and cook for 1 1/2 minutes until just cooked through, then remove into bowl","images":[],"step":19},{"description":"Add Chinese sausage and fish cake, and cook for 1 minute until sausage is caramelised, then add to bowl.","duration":1,"images":[],"step":20},{"description":"Add 1 tbsp oil then add egg and cook, pushing in the edges to make a thick omelette. Once set, chop it up roughly using a wooden spoon (see video), then add to bowl.","images":[],"step":21},{"description":"Add bean sprouts and cook for about 1 minute until just starting to wilt, then add to bowl.","images":[],"step":22},{"description":"Add lard. Once melted and starting to smoke, add garlic then immediately add noodles. Fold gently 4 times using a spatula + wooden spoon (see video) just to disperse oil through noodles.","images":[],"step":23},{"description":"Tip all the other ingredients back in plus the chives. Fold gently twice, then pour all the Sauce over.","images":[],"step":24},{"description":"Gently toss 4 to 6 times to disperse the sauce, pausing in between to allow the noodles to have a chance to caramelise on the edges a bit.","images":[],"step":25},{"description":"Remove from stove and serve immediately.","images":[],"step":26}]', '["egg","fish","gluten","shellfish","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Malaysian"],"categories":["asian-recipes","asian-takeout","iconic-dishes","noodles","prawns-shrimp"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5bd36663a3fe', 'en', 'US', 'Chinese Steamed Pork Buns', 'Recipe video above. These are truly just like what you get at Yum Cha / Dim Sum. Soft fluffy white buns with a juicy sweet and savoury filling. Perfect freezer standby - microwave from frozen and it''s like they''re fresh out of the bamboo steamer!', 'https://www.recipetineats.com/tachyon/2018/06/Chinese-BBQ-Pork-Buns_9.jpg', 50, 20, 70, 12, '[{"id": "ing_yeast", "quantity": {"value": 1.0, "unit": "pack of 5 sachets"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.375, "unit": "pack of 400g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.083, "unit": "tub of 150g"}}, {"id": "ing_onion", "quantity": {"value": 50.0, "unit": "pack of 1kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_pork", "quantity": {"value": 0.225, "unit": "kg"}}]', '[{"ingredients":["1 tsp active dry yeast powder","1/4 cup / 65 ml warm water","1 tbsp white sugar"],"purpose":"Yeast Activation:"},{"ingredients":["1/2 cup /125 ml warm water","4 tbsp /70g white sugar","2 cups / 300g plain flour (all purpose)","1 cup / 155g cornflour / cornstarch","1/4 cup / 65 ml vegetable oil","2 1/2 tsp baking powder"],"purpose":"Dough:"},{"ingredients":["1 tbsp vegetable oil","1/3 cup finely chopped escalot or white onion (Note 1)","1 tbsp sugar","1 1/2 tbsp soy sauce (, regular or light (not dark))","1 1/2 tbsp oyster sauce (can sub Hoisin)","1 tbsp sesame oil","1/2 cup water","1 tbsp cornflour dissolved in 1 tbsp water","1 1/2 cups Chinese Barbecue Pork (, diced (Note 2))"],"purpose":"Pork Filling:"}]', '[{"title":"Yeast Activation","description":"Place yeast, sugar and water in a small bowl. Mix, then set aside for 10 minutes until it becomes foamy.","duration":10,"images":[],"step":1},{"description":"Place flour, cornflour and sugar in a stand mixer bowl fitted with a dough hook. Mix briefly to combine.","images":[],"step":2},{"description":"Add yeast mixture, oil and water. Mix on low speed for 3 minutes until a smooth ball of dough forms. It should be soft and elastic, not so sticky it gets stuck all over your hands. Adjust with a touch of flour/water if required to get the dough consistency right.","duration":3,"images":[],"step":3},{"description":"Cover with cling wrap and place in a warm dry place for 2 hours until it doubles in volume. (Note 3). Meanwhile, make Filling.","images":[],"step":4},{"description":"Remove cling wrap, scatter over baking powder. Return to stand mixer and mix on low for 2 minutes.","duration":2,"images":[],"step":5},{"description":"Turn dough out onto work surface, sprinkle with flour. Knead lightly to form a smooth round disc.","images":[],"step":6},{"description":"Making Buns (watch video):","images":[],"step":7},{"description":"Cut dough into 4 pieces. Take one piece, roll into an even log, cut into 3 pieces (so 12 pieces in total).","images":[],"step":8},{"description":"Take one piece of dough, cover remaining with cling wrap or tea towel.","images":[],"step":9},{"description":"Roll into round 4.5\" / 11 cm in diameter, making the edges thinner.","images":[],"step":10},{"description":"Place dough in hand, put 1 1/2 tbsp of Filling in the centre.","images":[],"step":11},{"description":"Pinch 8 pleats around the edges. Then gather the pleats together one by one to seal the bun. Pinch the top the twist.","images":[],"step":12},{"title":"Repeat with remaining dough","description":"make 12 in total.","images":[],"step":13},{"description":"Cover buns loosely with cling wrap and leave in a warm place for 15 minutes.","duration":15,"images":[],"step":14},{"description":"Line a large bamboo steamer (or other steamer) with parchment paper punctured with holes (Note 4).","images":[],"step":15},{"description":"Place 6 to 8 buns on paper, cover with steamer lid.","images":[],"step":16},{"description":"Pour about 4 cm / 1 1/2 inches in a wok / pot (steamer should not touch water) and bring to rapid simmer over medium high.","images":[],"step":17},{"description":"Place steamer in wok, then cook for 12 minutes. Check water halfway through, top up if required.","duration":12,"images":[],"step":18},{"description":"Buns are ready when they spring back when touched, and the buns have formed a smooth skin.","images":[],"step":19},{"description":"Remove steamer from wok, serve warm!","images":[],"step":20},{"description":"Heat oil in a saucepan over medium heat. Add eschalots and cook for 2 minutes.","duration":2,"images":[],"step":21},{"description":"Add sugar, soy sauce, oyster sauce, sesame oil and water. Mix.","images":[],"step":22},{"description":"While stirring, slowly pour cornflour mixture in. Mix until smooth.","images":[],"step":23},{"title":"Stir in pork. Cook until sauce is thickened, 1","description":"1 1/2 minutes (see video for consistency). Set aside to cool (thickens when cools).","images":[],"step":24}]', '["gluten","sesame","soy"]', '["low_calorie"]', '{"mealType":["main_course"],"cuisine":[],"categories":["asian-recipes","chinese-recipes","dumplings","iconic-dishes","modern-asian","yum-cha-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0e95ce4fa65a', 'en', 'US', 'Singapore Noodles', 'One of the most popular stir fried noodles, made at home! Made with Chinese BBQ Pork (Char Siu), prawns/shrimp, egg and vegetables with a signature curry seasoning. See notes for a quick Char Siu and subs. This recipe makes 2 generous servings. Recipe video below.', 'https://www.recipetineats.com/tachyon/2015/04/Singapore-Noodles_6.jpg', 15, 10, 25, 2, '[{"id": "ing_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.06, "unit": "bottle of 500ml"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.25, "unit": "jar of 50g"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.2, "unit": "pack of 500g"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_shrimp", "quantity": {"value": 8.0, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_pork", "quantity": {"value": 0.227, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["2 tbsp soy sauce (Note 1)","2 tbsp Chinese cooking wine (Note 2)","2 1/2 tsp curry powder (hot or ordinary, Note 3)","1/2 tsp sugar","1/2 tsp white pepper (black also ok)"],"purpose":"Sauce"},{"ingredients":["100g / 3 oz dried rice vermicelli noodles (Note 4)","2 tbsp peanut oil (, separated)","8-10 medium raw shrimp / prawns (, shelled and deveined)","2 eggs (, beaten)","1/2 medium onion (, thinly sliced (yellow, brown or white))","4 garlic cloves (, minced)","1 tsp ginger (, freshly grated)","1/2 lb / 250g Chinese barbecue pork (Char Siu), thinly sliced (Note 5)","1 cup red capsicum / bell pepper","2 tsp thinly sliced hot green pepper (adjust to taste, optional)"],"purpose":"Stir Fry"}]', '[{"description":"Combine the Sauce ingredients in a small bowl and mix.","images":[],"step":1},{"description":"Place rice vermicelli noodles in a large bowl filled with boiled water and soak as per packet instructions. Drain and set aside.","images":[],"step":2},{"description":"Heat 1 tbsp of oil in a wok or heavy based fry pan over medium heat. Add the shrimp/prawns, cook until just cooked - about 2 1/2 to 3 minutes. Remove and set aside.","images":[],"step":3},{"description":"Add the egg and spread it out to make a thin omelette. Once set, use a spatula to roll it up, remove from the wok and slice (while still rolled up).","images":[],"step":4},{"description":"Return the wok to medium heat and add the remaining 1 tbsp of oil. Add the garlic, ginger and onion, cook for 2 minutes until onion is slightly softened.","duration":2,"images":[],"step":5},{"description":"Add capsicum and cook for 1 minute.","duration":1,"images":[],"step":6},{"description":"Add noodles and Sauce, give it a few tosses. Then add the egg, pork, shrimp/prawns, chillies (if using). Toss until the sauce coats all the noodles and everything is heated through - about 1 to 2 minutes.","images":[],"step":7},{"description":"Serve immediately.","images":[],"step":8}]', '["egg","gluten","peanuts","shellfish","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese","Hong Kong","Singapore"],"categories":["asian-recipes","asian-takeout","chinese-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","most-popular","noodles","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bbdd82be973f', 'en', 'US', 'San Choy Bow (Chinese Lettuce Wraps)', 'Recipe video above. One of my favourite starters at Chinese restaurants, the ultimate (almost) carb free healthy dish of all time! It all comes down to the Sauce - with a great Sauce, you can change up the filling to your taste. I''ve copied the filling served by Chinese restaurants but feel free to substitute with other vegetables or make it entirely meat free (this is a great recipe to make vegetarian).', 'https://www.recipetineats.com/tachyon/2017/02/Lettuce-Wraps-2.jpg', 15, 5, 20, 3, '[{"id": "ing_cornstarch", "quantity": {"value": 0.016, "unit": "pack of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.06, "unit": "bottle of 500ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_pork_mince", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_water", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_corn", "quantity": {"value": 5.0, "unit": "can of 400g"}}, {"id": "ing_mushroom", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 160.0, "unit": "head"}}, {"id": "ing_peanuts", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 1/4 tsp cornflour / cornstarch","3 tbsp water, (separated)","1 1/2 tbsp light soy sauce (Note 1)","1 tsp dark soy sauce (Note 1)","2 tbsp oyster sauce","1 tsp sesame oil","2 tbsp Chinese cooking wine (or sub Mirin or dry sherry, Note 2)","1 tsp white sugar (can omit)"],"purpose":"Sauce"},{"ingredients":["1 tbsp peanut oil","1 clove large garlic, (minced)","1/2 tsp ginger, (minced)","300g / 10oz pork mince (ground pork) (Note 3)","1/2 onion, (finely chopped)","1 small carrot, (finely chopped)","100g/ 3.5oz canned water chestnuts, (drained and finely chopped (Note 4))","5 baby corn, (canned or fresh, finely chopped (Note 4))","5 mushrooms, (finely chopped(shiitake is best, I used Swiss Brown))"],"purpose":"Filling (Note 6)"},{"ingredients":["8 leaves large or 16 - 20 small lettuce, preferably soft (Note 5)","Crushed peanuts","Finely sliced scallions / shallots"],"purpose":"Serving"}]', '[{"description":"Mix cornflour with 1 tbsp water until lump free. Then add remaining Sauce ingredients and mix.","images":[],"step":1},{"description":"Heat oil in a wok or large skillet over high heat. Add garlic and ginger, give it a quick stir then add onion.","images":[],"step":2},{"description":"Cook for 1 minute then add pork. Cook pork until it turns white.","duration":1,"images":[],"step":3},{"description":"Add all the vegetables. Cook for 2 minutes until the carrot is softened and pork is cooked through.","duration":2,"images":[],"step":4},{"description":"Add Sauce and cook for 1 1/2 minutes or until it thickens and glossy, coating the Filling.","images":[],"step":5},{"description":"Transfer Filling into serving bowl. Lay out lettuce leaves, peanuts and scallions on the side.","images":[],"step":6},{"description":"To serve, spoon some Filling into a lettuce leaf. Top with peanuts and scallions, bundle it up and enjoy!","images":[],"step":7}]', '["gluten","peanuts","sesame","soy"]', '["low_calorie"]', '{"mealType":["snack","dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chicken-mince-recipes","chicken-recipes","chinese-recipes","dietary","dinner-tonight","low-calorie-recipes","main-dishes","pork-recipes","quick-and-easy","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ccbb82d85924', 'en', 'US', 'Chinese Beef and Broccoli', 'Recipe video above. Faster than take out, healthier and tastier. This is a recipe from a Chinese restaurant! If using economical beef, consider tenderising it the Chinese way ("velveting", simple, highly effective!)', 'https://www.recipetineats.com/tachyon/2015/03/Chinese-Beef-and-Broccoli_3.jpg', 10, 10, 20, 3, '[{"id": "ing_cornstarch", "quantity": {"value": 0.075, "unit": "pack of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_chinese_five_spice", "quantity": {"value": 0.625, "unit": "jar"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.01, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.34, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_broccoli", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["2 tbsp cornstarch / cornflour","1/4 cup water","1 tsp sugar","1 tbsp dark soy sauce (Note 1)","1 1/2 tbsp light soy sauce (Note 1)","1 tbsp Chinese cooking wine (Shaoxing wine) (Note 2)","1/8 tsp Chinese five spice powder (Note 3)","1 tsp sesame oil (optional)","1/8 tsp tsp black pepper"],"purpose":"Sauce"},{"ingredients":["2 tbsp oil","12 oz / 360g beef fillet, flank or rump (Note 4 for tenderising option)","1 garlic clove, finely chopped","1 tsp fresh ginger, finely chopped","4 - 5 cups broccoli florets (1 head), cooked (Note 5)","1 cup water"],"purpose":"Stir Fry"},{"ingredients":["Sesame seeds (optional)"],"purpose":"Serving:"}]', '[{"description":"Place cornflour and water in bowl then mix. Add remaining Sauce ingredients.","images":[],"step":1},{"description":"Slice the beef into 1/4\" / 0.5cm thick slices. Place the beef and 2 tbsp of the Sauce into a bowl and set aside.","images":[],"step":2},{"description":"Heat oil in a skillet over high heat. Add beef and spread out, leave for 1 minute until browned.","duration":1,"images":[],"step":3},{"description":"Stir beef for 10 seconds, then add garlic and ginger. Stir for another 30 seconds or until beef is no longer pink.","duration":0.16666666666666666,"images":[],"step":4},{"description":"Pour Sauce and water into the skillet and quickly mix.","images":[],"step":5},{"description":"When the sauce starts bubbling, add broccoli. Stir to coat the broccoli in Sauce, then let it simmer for 1 minute or until Sauce is thickened.","duration":1,"images":[],"step":6},{"description":"Remove from heat immediately and serve over rice. Sprinkle with sesame seeds if desired.","images":[],"step":7}]', '["fish","gluten","sesame","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese American"],"categories":["asian-recipes","asian-takeout","beef-recipes","broccoli-recipes","chinese-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","most-popular","quick-and-easy","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_aeeea4463c87', 'en', 'US', 'Chinese dumplings (Potstickers!)', 'Recipe video above. Time to get your dumpling game on! Don''t fret about perfect pleats - if it''s all too hard, just press the seams together without pleating, plenty of Chinese restaurants do this. This recipe has a pork and cabbage filling, which is traditional and common. After a Vegetable filling? Here it is!', 'https://www.recipetineats.com/tachyon/2018/03/Potstickers_6a.jpg', 30, 25, 55, 30, '[{"id": "ing_shiitake_mushrooms", "quantity": {"value": 5.0, "unit": "pack of 150g"}}, {"id": "ing_cabbage", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_pork_mince", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_wine", "quantity": {"value": 0.01, "unit": "bottle of 750ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_round_dumpling_wrappers", "quantity": {"value": 30.0, "unit": "unit"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 4.0, "unit": "L"}}]', '[{"ingredients":["5 - 6 dried shiitake mushrooms (Note 1)","1 ½ cups finely chopped Chinese cabbage (Napa cabbage)","½ tsp salt","250 g / 0.5 lb fatty pork mince (20 - 30% fat ideal - Note 2)","¼ cup garlic chives (, finely chopped*)","2 tsp light soy sauce (light or dark soy also ok)","1 1/2 tsp Chinese wine (Note 4)","½ tsp sesame oil*","¼ tsp white pepper (black also ok)","1 garlic clove (, minced)","½ tsp grated fresh ginger*"]},{"ingredients":["30 - 35 round dumpling wrappers (Note 5)","1/2 cup water per batch","4 - 6 tsp vegetable oil"],"purpose":"To cook:"}]', '[{"title":"Shiitake Mushroom","description":"Place the mushrooms in a bowl and pour over plenty of boiled water. Leave for 20 minutes or until rehydrated. Squeeze out excess water, then finely chop.","duration":20,"images":[],"step":1},{"title":"Cabbage","description":"Place cabbage in a bowl with salt. Toss with fingers, then set aside for 15 minutes. Squeeze out excess liquid from cabbage using hands.","duration":15,"images":[],"step":2},{"title":"Filling","description":"Place cabbage, mushrooms and remaining Filling ingredients in a bowl. Mix with your hands until well combined.","images":[],"step":3},{"description":"Make Dumplings (watch video + see photos in post):","images":[],"step":4},{"description":"Peel one wrapper off and place on the palm of your left hand (if right handed). Dip your finger in water and run it along half the edge of the wrapper.","images":[],"step":5},{"description":"Place 1 heaped tablespoon of Filling in the centre. Fold wrapper over, then pleat to seal. Alternatively, just press together with no pleats.","images":[],"step":6},{"description":"Finish so the dumpling is curved slightly, see photos in post, with the pleats on the top.","images":[],"step":7},{"description":"Place on tray. Cover with cling wrap or wet tea towel (important). Repeat with remaining dumplings. Should make 30, if yours are extremely plump you may only make 25.","images":[],"step":8},{"description":"Cooking:","images":[],"step":9},{"description":"Make sure your pan has a lid that fits it half decently (Note 6).","images":[],"step":10},{"description":"Heat 2 tsp oil in a non stick pan over medium high heat. Add dumplings, pressing down firmly to flatten the base onto the pan. Cook around 8 to 10 per batch.","images":[],"step":11},{"description":"When the base is golden brown (check them), add 1/2 cup of water into the pan.","images":[],"step":12},{"description":"Immediately clamp the lid on, then leave for 7 minutes (any less and the pleats won''t be cooked through so if your water dries out, add a bit more).","duration":7,"images":[],"step":13},{"title":"Remove lid","description":"most of the water should be evaporated, the pleats should be cooked through. Leave the pan on the stove until the base dries and the underside of the dumplings are once again crisp.","images":[],"step":14},{"description":"Remove dumplings from pan and transfer to serving plate. Repeat with remaining Dumplings.","images":[],"step":15},{"description":"Serve with Dipping Sauces of choice. (Note 7)","images":[],"step":16}]', '["gluten","sesame","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chinese-recipes","dumplings","iconic-dishes","pork-recipes","yum-cha-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1bf3fddcd4c0', 'en', 'US', 'Stir Fried Noodles with Peanut Sauce', 'Noodles tossed in a peanut sauce with vegetables and your choice of protein! With the hint of curry flavour, the peanut sauce tastes like satay peanut stir fries you get at Chinese restaurants here in Australia. The flavour of this sauce belies the short list of simple ingredients - good Asian peanut sauces typically have a much lengthier list of ingredients. Make your own stir fry or noodles using whatever ingredients you have - use this Satay Peanut Sauce for Stir Fries (sauce recipe + "formula" for stir fry). Stir Fried Noodles recipe VIDEO below.', 'https://www.recipetineats.com/tachyon/2018/03/Stir-Fried-Noodles-with-Peanut-Sauce_6.jpg', 15, 8, 23, 2, '[{"id": "ing_peanut_butter", "quantity": {"value": 0.1, "unit": "jar of 375g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.025, "unit": "pack of 400g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.15, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.18, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.025, "unit": "tub of 200g"}}, {"id": "ing_rice_noodles", "quantity": {"value": 0.267, "unit": "pack of 375g"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 150.0, "unit": "pack of 1kg"}}, {"id": "ing_cabbage", "quantity": {"value": 4.5, "unit": "head"}}, {"id": "ing_beansprouts", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_peanuts", "quantity": {"value": 0.003, "unit": "jar"}}]', '[{"ingredients":["1/4 cup / 60g crunchy peanut butter (Note 1)","1 1/2 tbsp fish sauce (Note 2)","1 1/2 tbsp dark soy sauce (Note 3)","2 tsp sugar","2 tsp cornflour / cornstarch","2 garlic clove (, minced)","2 tsp grated ginger","1 1/2 tsp curry powder (any type)","1/4 cup / 65 ml water"],"purpose":"Sauce:"},{"ingredients":["180 g/ 6 oz thinly sliced chicken breast","1 tsp bicarb / baking soda (optional, Note 4)"],"purpose":"Chicken:"},{"ingredients":["100 g/3.5 oz dried rice noodles (Note 5)","2 tbsp oil","1 garlic (, finely chopped)","1/2 onion (, sliced)","1 cup shredded carrot","1 1/2 cups shredded cabbage","1 cup beansprouts"],"purpose":"Stir Fry:"},{"ingredients":["Finely chopped coriander/cilantro","Crushed peanuts"],"purpose":"Garnish (highly recommended):"}]', '[{"title":"Tenderise Chicken (optional, Note 4)","description":"Place chicken and bicarb in a bowl and mix with your fingers. Set aside for 20 minutes. Rinse well in a colander then shake off excess water. Roughly pat dry with a paper towel.","duration":20,"images":[],"step":1},{"title":"Sauce","description":"Place all ingredients except water in a bowl and mix (microwave if needed to melt the peanut butter). Add water and mix.","images":[],"step":2},{"description":"Prepare noodles per packet directions (usually soak in boiled water). Drain, set aside.","images":[],"step":3},{"description":"Heat oil in a large skillet or wok over high heat. Add garlic and onion, stir for 30 seconds.","duration":0.5,"images":[],"step":4},{"description":"Add chicken and cook until the outside changes from pink to white. Add carrot and cabbage, cook until it starts to wilt.","images":[],"step":5},{"description":"Add noodles, bean sprouts and Sauce. Toss for 1 1/2 - 2 minutes or until the Sauce thickens and coats the noodles.","images":[],"step":6},{"description":"Serve immediately, garnished with coriander and peanuts.","images":[],"step":7}]', '["fish","gluten","peanuts","soy"]', '[]', '{"mealType":["main_course"],"cuisine":[],"categories":["asian-recipes","asian-takeout","chinese-recipes","dinner-tonight","main-dishes","noodles","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3d463492b257', 'en', 'US', 'Thai Red Curry with Chicken', 'Recipe VIDEO above. A Thai Red Curry with Chicken is one of the world''s most popular curries! Make this with store bought curry paste (we give it a freshness boost) OR homemade red curry paste (the fresh flavour can''t be beaten!). SPICE Level: Mild to hot BUT if using store bought paste, depends on what brand you use (Note 5).', 'https://www.recipetineats.com/tachyon/2018/02/Thai-Red-Curry-Chicken-1.jpg', 5, 20, 25, 4, '[{"id": "ing_thai_red_curry_paste", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_quantity_homemade_thai_red_curry_paste", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 666.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_lemongrass", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_lime", "quantity": {"value": 6.0, "unit": "net of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_pumpkin", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_green_beans", "quantity": {"value": 120.0, "unit": "pack"}}, {"id": "ing_basil", "quantity": {"value": 12.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["5 - 6 tbsp Thai Red Curry Paste (store bought, Maesri best) (Note 1)","1 quantity homemade Thai Red Curry Paste"],"purpose":"Red Curry Paste – choose ONE:"},{"ingredients":["2 large garlic cloves (, minced)","2 tsp fresh ginger (, finely grated )","1 tbsp lemongrass paste (or finely chopped fresh (Note 3))"],"purpose":"Extras – only for jar curry paste (Note 2)"},{"ingredients":["3 tbsp vegetable oil (or canola or peanut)","1 cup (250 ml) chicken broth/stock (, low sodium)","400 ml / 14 oz coconut milk (full fat!)","6 kaffir lime leaves (Note 4)","1 tbsp sugar (white, brown or palm)","2 tsp fish sauce (, plus more to taste)","350g / 12 oz chicken thighs (boneless and skinless), cut into 0.75 / 1/3\" thick slices (Note 5)","150g / 5 oz pumpkin or butternut squash, ( cut into 1.5cm / 3/5\" cubes (~1 heaped cup))","120g / 4oz green beans (, trimmed and cut into 5cm/2\" pieces)","12 Thai basil leaves (Note 6)"],"purpose":"Thai Red Curry"},{"ingredients":["Fresh red chilli slices (small chilli - spicy, large = less spicy)","Fresh coriander / cilantro leaves","Steamed jasmine rice"],"purpose":"Garnishes (optional) & serving:"}]', '[{"description":"Heat oil in a large heavy based skillet over medium high heat.","images":[],"step":1},{"description":"Add curry paste and Extras (if using jar paste) and cook for about 2 minutes so it \"dries out\" (See video)","images":[],"step":2},{"description":"Add chicken broth and stir to dissolve paste. Simmer rapidly for 3 minutes or until liquid reduces by half.","duration":3,"images":[],"step":3},{"description":"Add coconut milk, lime leaves, sugar and fish sauce. Stir, then add chicken.","images":[],"step":4},{"description":"Spread chicken out, bring to simmer, then turn heat down to medium. Simmer for about 8- 10 minutes or until Sauce reduces, the chicken is cooked and the sauce is almost at the thickness you want.","images":[],"step":5},{"description":"Do a taste test. Add more fish sauce (or even shrimp paste) to add more saltiness, sugar for sweetness.","images":[],"step":6},{"description":"Add pumpkin and beans, stir. Cook for 3 minutes or until pumpkin is just cooked through and Sauce is thickened - see video for Sauce thickness.","duration":3,"images":[],"step":7},{"description":"Remove from heat. Stir through a handful of Thai basil leaves.","images":[],"step":8},{"description":"Serve over jasmine rice, garnished with fresh red chilli slices and fresh coriander/cilantro leaves, if desired.","images":[],"step":9}]', '["fish","peanuts"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-recipes","cuisines","curry-recipes","dietary","gluten-free-recipes","iconic-dishes","main-dishes","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c8ada42fec32', 'en', 'US', 'Thai Red Curry Paste', 'Developed over years by the RecipeTin Family, this is our Thai Red Curry Paste recipe that will make a curry that is truly tastes like what you get at great Thai restaurants. Guided by world renowned Thai Chefs, this is a Thai Red Curry paste recipe that''s doable for any home cook that we truly believe stacks up to the best of what you''ll get at restaurants. See post for more background information. Use this to make Thai Red Curry! Recipe VIDEO above. Enjoy!', 'https://www.recipetineats.com/tachyon/2018/02/Thai-Red-Curry-Paste_0.jpg', 10, 0, 10, 1, '[{"id": "ing_chilli", "quantity": {"value": 16.0, "unit": "pack of 100g"}}, {"id": "ing_lemongrass", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_galangal", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_shrimp", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["16 dried chillis (, chopped into 1 cm / 0.5\" pieces seeds shaken out (Note 1))","2 tbsp lemongrass (, sliced, reedy outer skin removed (1 large) (Note 2))","1 tbsp grated galangal, peeled and grated (Note 3)","4 garlic cloves, peeled whole","1 tbsp shrimp paste in oil (Note 4)","1/2 tsp ground coriander","1/2 tsp ground cumin","1 tbsp chopped coriander/cilantro stem and roots (Note 5)","2 red shallots (, peeled and roughly chopped (Note 6))","1 tsp lime zest","¼ cup reserved chilli soaking water"]}]', '[{"title":"Taste dried chillies for spiciness","description":"see Note 1. Place the chopped chillies in a large boil and pour over about 3 cups of freshly boiled water. Leave to soak for a good 30 minutes or so.","images":[],"step":1},{"description":"Remove chillis and reserve water.","images":[],"step":2},{"description":"Put chillis in a blender or powerful food processor.","images":[],"step":3},{"description":"Add remaining curry paste ingredients into the blender along with 1/4 cup of the chilli soaking water.","images":[],"step":4},{"title":"Blitz on high until smooth","description":"test by rubbing between your fingers. It takes around 20 seconds in my Vitamix which is a powerful blender. It might take up to 1 minute. Use a touch more water as required to aide with blending.","images":[],"step":5},{"description":"Scrape into a bowl or airtight container. Store for up to 3 days in the fridge, or freeze it to use later.","images":[],"step":6},{"description":"Use in place of store bought curry paste in recipes that call for it - especially Thai Red Curry!","images":[],"step":7}]', '["shellfish"]', '["gluten_free"]', '{"mealType":["main_course"],"cuisine":[],"categories":["asian-recipes","asian-takeout","cuisines","curry-recipes","dietary","gluten-free-recipes","main-dishes","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3001269a9630', 'en', 'US', 'Sesame Crusted Salmon', 'Recipe VIDEO above. Just roll salmon in sesame seeds and bake - you''ll be amazed how well it sticks! Served over soba and Asian greens with a fabulous Asian dressing, this is a great quick salmon recipe.', 'https://www.recipetineats.com/tachyon/2018/02/Sesame-Crusted-Salmon_3.jpg', 5, 15, 20, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.75, "unit": "pack of 100g"}}, {"id": "ing_oil", "quantity": {"value": 20.0, "unit": "bottle"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_es_baby_buk_choi", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_mirin", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}]', '[{"ingredients":["4 x 150-200g / 5-7 oz skinless boneless salmon or trout fillets (Note 1)","Salt and pepper","75g/ 1/2 cup white sesame seeds","4 tsp vegetable or canola oil (or other neutral oil, not olive oil)","Sliced shallots / scallions (, optional garnish)"]},{"ingredients":["250 g / 8 oz dried soba noodles (Note 2)","2 bunches baby buk choi (, or other greens of choice (Note 3))"],"purpose":"Soba and greens:"},{"ingredients":["1 1/2 tbsp soy sauce (, light or ordinary (Note 4))","2 1/2 tbsp vegetable or canola oil (or other neutral oil, not olive)","3 tbsp rice vinegar (Note 2)","1 tbsp Mirin (Note 2)","2 tsp sugar (any, I use white)","2 tsp fresh ginger (, minced)","1 clove garlic (, minced)"],"purpose":"Asian Dressing:"}]', '[{"description":"Take salmon out of fridge 20 minutes before cooking.","images":[],"step":1},{"description":"Preheat oven to 220C/430F (standard) or 200C/390F (fan). Place shelf about 20cm/8\" from the broiler heat source at the top of the oven.","images":[],"step":2},{"description":"Sprinkle both sides of the salmon with salt and pepper.","images":[],"step":3},{"description":"Place sesame in shallow dish. Press salmon into sesame seeds to coat on all sides. Place on tray.","images":[],"step":4},{"description":"Drizzle top with oil.","images":[],"step":5},{"title":"Bake for 10 minutes. Flick to broiler on high","description":"broil / grill for 3 minutes until the top is a bit golden (or bake for 5 minutes, but won''t be as golden). (Note 5)","duration":10,"images":[],"step":6},{"description":"Remove from oven, rest 3 minutes. Serve with soba and greens, garnished with scallions (optional) and drizzled with Dressing.","images":[],"step":7},{"description":"Soba and greens:","images":[],"step":8},{"description":"Bring a large pot of water to the boil.","images":[],"step":9},{"description":"Cook soba per packet directions. Add greens for the last 1 minute of cooking.","images":[],"step":10},{"description":"Drain then divide between bowls.","images":[],"step":11},{"description":"Place ingredients in jar and shake. Set aside for 5 minutes.","duration":5,"images":[],"step":12}]', '["fish","gluten","sesame","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Asian influence"],"categories":["asian-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_04c12d065cdc', 'en', 'US', 'Thai Chicken Salad', 'Recipe VIDEO above. A chicken salad with a fantastic Thai chilli lime dressing with a great tangy-sweet-salty-spicy balance that South East Asian food is known for. Using Chilli Garlic Sauce is a great way to thicken dressing as well as adding more layers of flavour. Serves 2 as a main, 4 as a side.', 'https://www.recipetineats.com/tachyon/2017/11/Thai-Chicken-Salad-1.jpg', 15, 20, 35, 2, '[{"id": "ing_chicken_breast", "quantity": {"value": 180.0, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 3.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_cucumber", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 0.25, "unit": "pack of 1kg"}}, {"id": "ing_chilli", "quantity": {"value": 5.0, "unit": "pack of 100g"}}, {"id": "ing_roasted_cashews", "quantity": {"value": 75.0, "unit": "jar"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 5.0, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 2.5, "unit": "pack of 3 heads"}}, {"id": "ing_lime", "quantity": {"value": 0.045, "unit": "net of 500g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}]', '[{"ingredients":["180 - 220 g / 6 -7oz chicken breast"]},{"ingredients":["150 g / 5 oz mixed lettuce leaves (or other of choice)","1 cup cherry or grape tomatoes (, halved)","1 small cucumber (, sliced)","1/4 red onion (, finely sliced)","1/2 large red chilli (, deseeded and very finely sliced (Note 1))","1/2 cup roasted cashews (, unsalted preferred)","1/4 cup coriander / cilantro leaves"],"purpose":"Salad:"},{"ingredients":["1 tbsp finely chopped coriander/cilantro stems (see video)","1 1/2 tsp Chilli Garlic Sauce (Note 2)","1 small garlic (, minced)","1 1/2 tbsp fresh lime juice (or rice vinegar)","2 tsp fish sauce (Note 3)","1 tbsp canola oil (or vegetable, grapeseed or other neutral oil)","1 1/2 tsp sugar (any, I use white)"],"purpose":"Thai Chilli Lime Dressing:"}]', '[{"description":"Take the chicken out of the fridge 30 minutes before cooking.","images":[],"step":1},{"description":"Boil water in a saucepan. Add chicken, put the lid on, let the water come back up to a simmer, then remove from stove. Set aside for 20 minutes (even up to 45 min is fine). (Note 4)","duration":20,"images":[],"step":2},{"description":"Remove chicken from water and shred, then cool.","images":[],"step":3},{"description":"Place ingredients in a jar. Shake well. Taste and adjust as required. It should be a balance of tangy / sweet / salty / hint of spice. (Note 5)","images":[],"step":4},{"description":"Place Salad ingredients in a large bowl. Drizzle over most of the Dressing, toss. Serve immediately, drizzled with remaining Dressing.","images":[],"step":5}]', '["fish"]', '["gluten_free"]', '{"mealType":["dinner","lunch"],"cuisine":["Thai"],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","cuisines","dietary","dinner-tonight","gluten-free-recipes","low-calorie-recipes","main-dishes","quick-and-easy","salad-recipes-main-course","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_47e0d48a8e4a', 'en', 'US', 'Thai Meatballs', 'Recipe video above. The beautiful, fresh Thai flavour in these meatballs are amazing! Truly like something you''d get at those posh Thai restaurants. These aren''t authentic Thai, as far as I know there really aren''t meatballs in Thai cuisine (at least, not like this, they have them in soups), but all the flavourings in this are real-deal-Thai.', 'https://www.recipetineats.com/tachyon/2017/10/Thai-Meatballs.jpg', 20, 25, 45, 4, '[{"id": "ing_pork_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_lemongrass", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_lime", "quantity": {"value": 3.0, "unit": "net of 500g"}}, {"id": "ing_chilli", "quantity": {"value": 3.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 0.141, "unit": "loaf"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_chilli", "quantity": {"value": 3.0, "unit": "pack of 100g"}}, {"id": "ing_lime", "quantity": {"value": 3.0, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["500 g / 1 lb pork mince (ground pork, or chicken)","1 tbsp lemongrass paste (or finely chopped fresh) (Note 1)","1 tsp grated ginger","3 cloves garlic (, minced)","3 kaffir lime leaves, stem removed and very finely shredded, optional extra (Note 2)","3 Thai or birds eye chillies (, seeds removed and finely chopped (Note 3))","1/4 cup coriander/cilantro (, leaves and stem finely chopped (Note 4))","1 tsp sugar (any)","1 tbsp fish sauce (can sub with soy sauce if required)","3/4 cup panko breadcrumbs (+ extra 1/4 cup if needed)","1 small egg","Oil spray"],"purpose":"Meatballs:"},{"ingredients":["1/2 cup / 125 ml sweet chilli sauce (, store bought (Note 5))","1 garlic clove (, minced)","2 tbsp lime juice (, plus more to taste)"],"purpose":"Sweet Chilli Dipping Sauce:"},{"ingredients":["Coriander/cilantro leaves (, finely sliced large red chillies)","Steamed jasmine rice"],"purpose":"Optional garnishes & serving:"}]', '[{"description":"Preheat oven to 220C/430F (standard) or 200C/390F (fan / convection).","images":[],"step":1},{"description":"Place a rack on a tray (optional, rack keeps balls slightly rounder).","images":[],"step":2},{"description":"Place Meatball ingredients in a bowl (except oil spray), mix well with your hands. Only use extra breadcrumbs if necessary - sometimes, chicken mince can be quite wet. Scoop up 1 slightly heaped tablespoon and roll into a ball (about 3cm / 1.25\" diameter). (Note 6 for my way)","images":[],"step":3},{"description":"Spray rack well with oil and place the meatballs on the rack.","images":[],"step":4},{"description":"Spray meatballs generously with oil, then bake for 20 - 25 minutes or until a bit browned. They should be beautifully soft - see video!","duration":22.5,"images":[],"step":5},{"description":"Serve warm with Sauce, garnished with coriander and chillies if desired.","images":[],"step":6},{"description":"Place ingredients in a bowl and mix. Set aside for at least 10 minutes before using.","images":[],"step":7}]', '["egg","fish","gluten","soy"]', '[]', '{"mealType":["dinner","snack"],"cuisine":["Thai"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-mince-recipes","chicken-recipes","cuisines","finger-food","meatball-recipes","pork-recipes","super-bowl-party-food","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_20b1481b67eb', 'en', 'US', 'Vietnamese Coconut Caramel Chicken', 'The chicken version of the wildly popular Vietnamese Caramel Pork! It''s saucier and made with coconut milk so it has a gorgeous coconut fragrance. It''s sweet with savoury undertones, looks thoroughly unimpressive while cooking but then magically transforms in the last 5 minutes. Recipe VIDEO below.', 'https://www.recipetineats.com/tachyon/2017/10/Vietnamese-Coconut-Caramel-Chicken.jpg', 5, 55, 60, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.15, "unit": "bottle of 250ml"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 10.0, "unit": "pack of 100g"}}]', '[{"ingredients":["4 large / 5 small chicken thighs (, bone in skin on (Note 1))","1/2 cup / 80 g brown sugar (, loosely packed)","1 tbsp water","400 g / 14 oz coconut milk (, low fat (1 can) (Note 2))","1 1/2 tbsp fish sauce (Note 3)","2 1/2 tbsp rice vinegar (or cider vinegar)","2 garlic cloves (, minced)","1 eschallot / French onion (, finely sliced (Note 4))","1/4 tsp white pepper (or black)"]},{"ingredients":["1 shallot (, finely sliced (green onion / scallion))","1 large red chilli (, finely sliced)"],"purpose":"Garnishes (optional):"}]', '[{"description":"Place sugar and water in a skillet over medium heat. Stir, then when it bubbles and the sugar is melted (it looks like caramel), add the rest of the ingredients except chicken.","images":[],"step":1},{"description":"Stir, then put the chicken in SKIN SIDE DOWN.","images":[],"step":2},{"description":"Adjust the heat so it is simmering energetically. Not rapidly, not a slow simmer (I use medium high heat on a weak stove, medium on a strong stove).","images":[],"step":3},{"description":"After 25 minutes, turn the chicken.","images":[],"step":4},{"description":"After another 25 minutes, the fat should separate from the sauce and turn a pale brown (see video).","images":[],"step":5},{"description":"Turn chicken so the skin side is down. Move it around so the sauce doesn''t catch on the bottom of the skillet and to brown the skin.","images":[],"step":6},{"description":"Once sauce and skin is brown, remove from heat.","images":[],"step":7},{"description":"Place chicken on serving plates, spoon over some sauce (don''t need much, chicken is infused with flavour + sauce is strong).","images":[],"step":8},{"description":"Garnish with shallots and chilli, if using. Serve with rice.","images":[],"step":9}]', '["fish"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Vietnamese"],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","quick-and-easy","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3b3a01348f89', 'en', 'US', 'Chinese Beef and Broccoli Noodles', 'Everybody''s favourite Chinese Beef and Broccoli - with noodles! I make this in a large skillet because it serves 4 so there''s too much for a wok. If you scale it down to serve 2 (use scaler by hovering over Servings), you can make this in a wok. See notes for how to make this with CHARLIE, my all purpose stir fry sauce. Recipe VIDEO below.', 'https://www.recipetineats.com/tachyon/2017/10/Beef-and-Broccoli-Noodles-3.jpg', 10, 10, 20, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 350.0, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_broccoli", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 400.0, "unit": "pack of 500g"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.037, "unit": "pack of 400g"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.045, "unit": "bottle of 500ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chinese_five_spice", "quantity": {"value": 0.625, "unit": "jar"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["350 - 400 g / 12 - 14 oz beef rump or fillet (, thinly sliced (or other quick cooking cut of beef))","1 1/2 tbsp peanut or vegetable oil","2 garlic cloves (, finely chopped)","1/2 onion (, finely sliced)","1 large head broccoli (, broken into small florets)","400 - 450g / 14 - 15 oz egg noodles (hokkien, lo mein, singapore - from the fridge) (Note 1)"]},{"ingredients":["1/2 cup / 125 ml water","1 tbsp cornflour / cornstarch","2 tbsp dark soy sauce (Note 2)","1 1/2 tbsp light soy sauce (Note 2)","1 1/2 tbsp Chinese cooking wine/Shoasing wine (Note 3)","1 tsp white sugar (omit if using Mirin)","1/8 tsp Chinese five spice powder (not critical)","1/2 tsp sesame oil (not critical)","1/4 tsp pepper (white or black)"],"purpose":"Sauce:"},{"ingredients":["Sesame seeds","Chopped shallots / green onions / scallions"],"purpose":"Optional Garnishes:"}]', '[{"title":"Sauce","description":"Place water and cornflour in a bowl, mix. Then add remaining ingredients and mix.","images":[],"step":1},{"title":"Beef","description":"Place in a bowl and add 1 1/2 tbsp Sauce. Mix.","images":[],"step":2},{"title":"Broccoli & Noodles","description":"Bring a large pot of water to the boil. Add broccoli, cook for 1 minute. Add noodles then after 15 seconds, use a wooden spoon to separate the noodles then immediately drain (don''t have the noodles in the water for more than 1 minute).","duration":1,"images":[],"step":3},{"description":"Heat oil in a large skillet over high heat.","images":[],"step":4},{"description":"Add garlic, quickly stir. Add onion and cook for 1 minute until it''s tinged with brown.","duration":1,"images":[],"step":5},{"description":"Add beef and cook until it changes from red to brown.","images":[],"step":6},{"description":"Add noodles, broccoli and sauce. Toss together for 1 1/2 - 2 minutes or until Sauce thickens and coats the noodles. Sprinkle with sesame seeds and shallots, if using, and serve!","images":[],"step":7}]', '["egg","fish","gluten","peanuts","sesame","soy"]', '[]', '{"mealType":["main_course"],"cuisine":[],"categories":["asian-recipes","asian-takeout","broccoli-recipes","chinese-recipes","noodles","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e4dad176b9ea', 'en', 'US', 'Vietnamese Caramel Pork', 'Recipe VIDEO above. "Thit Kho To" - Tender pork in a sweet savoury glaze that has quite an intense flavour. Though made using coconut water as the broth, but it doesn''t have a coconut flavour at all! It looks so unimpressive right up until the end when it magically transforms into sticky caramelised pork pieces!', 'https://www.recipetineats.com/tachyon/2017/10/Vietnamese-Caramel-Pork_-4.jpg', 10, 90, 100, 4, '[{"id": "ing_brown_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_pork_shoulder", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1/2 cup / 100g brown sugar, tightly packed","1 tbsp water","1 kg / 2 lb pork shoulder (butt) or boneless skinless pork belly, cut into 3 cm / 1.2\" pieces (Note 1a)","1.5 cups / 375 ml coconut water (Note 1b)","1 eschallot / shallot (, very finely sliced (Note 2))","2 garlic cloves (, minced)","1 1/2 tbsp fish sauce","1/4 tsp white pepper"]},{"ingredients":["Red chilli and finely sliced shallots/green onions"],"purpose":"Garnishes:"}]', '[{"description":"Place sugar and water in a large pot over medium heat. Stir, then when it bubbles and the sugar is melted (it looks like caramel), add the rest of the ingredients.","images":[],"step":1},{"description":"Stir, then adjust the heat so it is simmering fairly energetically. Not rapidly, not a slow simmer (I use medium heat on a weak stove, between medium and low on a strong stove).","images":[],"step":2},{"description":"Simmer for 1.5 hours, uncovered. Stir once or twice while cooking.","images":[],"step":3},{"description":"At around 1.5 hours, when the liquid has reduced down and the pork is tender, (see Note 3 if pork is not yet tender), the fat will separate (see video).","images":[],"step":4},{"description":"Stir and the pork will brown and caramelise in the fat.","images":[],"step":5},{"description":"Once the liquid is all gone and it''s now stuck on the pork pieces, it''s ready.","images":[],"step":6},{"description":"Serve over rice, garnished with fresh chilli and shallots. Simple pickled vegetables are ideal for a side because the fresh acidity pairs well with the rich pork.","images":[],"step":7}]', '["fish"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Vietnamese"],"categories":["asian-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","pork-recipes","quick-and-easy","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a3caa8a06fac', 'en', 'US', 'Sesame Noodles', 'Recipe video above. Sesame Noodles tossed in a wicked Asian Sesame Peanut Dressing! Terrific served at room temperature or warm, this is a great side dish. Or turn it into a complete meal by adding shredded salads like carrots, cabbage and bean sprouts, and how about some shredded chicken too? Serves 6 - 8 as a side.', 'https://www.recipetineats.com/tachyon/2017/08/Sesame-Noodles-2.jpg', 10, 5, 15, 6, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_green_onion", "quantity": {"value": 2.25, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_peanuts", "quantity": {"value": 2.0, "unit": "jar"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 1.0, "unit": "bottle of 250ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 1.0, "unit": "bottle of 250ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 1.0, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.08, "unit": "jar of 375g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_chilli", "quantity": {"value": 0.1, "unit": "pack of 100g"}}]', '[{"ingredients":["500 g / 1 lb fresh egg noodles (Note 1)","3/4 cup green onions (, finely sliced (scallions))","1 tbsp sesame seeds, (plus more for garnish)","2 - 3 tbsp crushed peanuts, (optional, plus more for garnish)"]},{"ingredients":["1 ½ tbsp dark soy sauce (Note 2)","1 tbsp normal soy sauce (Note 2)","1 ½ tbsp rice vinegar","2 tbsp sesame oil","2 tsp fresh grated ginger","1 garlic clove (minced)","2 tsp white sugar","2 tbsp peanut butter","1 tbsp Chinese sesame paste or tahini (Note 3)","2 tsp garlic chilli paste, like Sambal Oelak, or Sriracha (adjust to taste) (Note 4)"],"purpose":"Sauce:"}]', '[{"description":"Cook noodles per packet directions. Drain then briefly rinse under tap to stop them sticking together.","images":[],"step":1},{"description":"Place Sauce ingredients in a bowl. Mix until smooth – microwave briefly if required to assist.","images":[],"step":2},{"description":"Place the noodles in a large bowl, add shallots, dressing, sesame seeds and peanuts if using. Toss well. Garnish with more sesame seeds. Serve warm or at room temperature.","images":[],"step":3}]', '["egg","gluten","peanuts","sesame","soy"]', '["low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Asian"],"categories":["asian-recipes","chinese-recipes","no-cook-food","noodles","quick-and-easy","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_44febe8729e9', 'en', 'US', 'Quick Satay Peanut Stir Fry (any protein)', 'VIDEO below. A gem of a recipe given to me by a reader, this is a brilliant QUICK Satay Stir Fry that tastes like Chinese style satay that you get from Chinese restaurants here in Australia. Make this with your choice of protein - great with beef (pictured), chicken, pork, shrimp or tofu. Use shredded shaped vegetables - ideal for this sauce which is not the saucy type.', 'https://www.recipetineats.com/tachyon/2017/07/Quick-Satay-Stir-Fry.jpg', 10, 7, 17, 3, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.025, "unit": "pack of 400g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.06, "unit": "jar of 375g"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_beef", "quantity": {"value": 300.0, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 75.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 1.0, "unit": "bag of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.5, "unit": "bunch"}}, {"id": "ing_peanuts", "quantity": {"value": 0.094, "unit": "jar"}}]', '[{"ingredients":["1 1/2 tbsp fish sauce (Note 1)","1 1/2 tsp sugar","2 tsp cornflour / cornstarch","1 garlic clove (, minced)","1 tsp grated ginger","1 tsp curry powder (any - I use hot!)","1 1/2 tbsp crunchy peanut butter (smooth also ok)","2 tbsp water"],"purpose":"Sauce:"},{"ingredients":["300 - 350 g / 10 - 12 oz beef (, chicken or pork thinly sliced (or peeled prawns/shrimp) (Note 2))","2 tbsp oil","1 garlic (, finely chopped (Note 3))","1 large onion (, sliced)","1 large carrot (, julienned (Note 4))","1 big handful bean sprouts (~1 1/2 cups packed)","1/2 cup finely sliced shallots / green onions (plus more for garnish)","1/4 cup crushed peanuts (, plus more for garnish (optional))"],"purpose":"Stir Fry:"}]', '[{"description":"Mix Sauce ingredients EXCEPT WATER together in a small bowl. Then mix in water (easier to combine).","images":[],"step":1},{"description":"Place beef in a bowl, add 1 tbsp Sauce. Mix, set aside 10 minutes.","images":[],"step":2},{"description":"Heat oil in a wok or large heavy based skillet over high heat. Add garlic and stir until golden (~10 sec) then add onion. Cook for 1 minute.","duration":1,"images":[],"step":3},{"description":"Add beef. Cook for 1 1/2 minutes or until it mostly turns brown (some red spots ok). If using pork, chicken or prawns, cook until almost cooked through.","images":[],"step":4},{"description":"Add carrots, bean sprouts and Sauce. Cook until veggies are wilted.","images":[],"step":5},{"description":"Add peanuts and shallots, stir.","images":[],"step":6},{"description":"Serve immediately with rice or noodles, garnished with extra shallots and peanuts if desired. (For a low carb, low cal option, try Cauliflower Rice!)","images":[],"step":7}]', '["fish","peanuts","shellfish"]', '["gluten_free","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","beef-recipes","chicken-breast-recipes","chicken-recipes","chinese-recipes","quick-and-easy","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5a26e2bb87e7', 'en', 'US', 'Teriyaki Chicken Meatballs', 'Recipe video above. Soft, plump, juicy meatballs smothered in a homemade Teriyaki sauce! The sauce for this recipe is based my mother''s authentic Teriyaki Chicken recipe. Serve these as a meal or pass them around at a party.', 'https://www.recipetineats.com/tachyon/2017/07/Teriyaki-Chicken-Meatballs.jpg', 20, 15, 35, 4, '[{"id": "ing_cornstarch", "quantity": {"value": 0.037, "unit": "pack of 400g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.25, "unit": "bottle of 250ml"}}, {"id": "ing_cooking_sake", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_mirin", "quantity": {"value": 0.25, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.18, "unit": "L"}}, {"id": "ing_chicken_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_bread", "quantity": {"value": 0.188, "unit": "loaf"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_cooking_sake", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1 tbsp cornflour / cornstarch","1/4 cup / 65ml soy sauce (, all purpose / ordinary (Note 1))","1/4 cup / 65ml cooking sake (, or sub with Chinese cooking wine or dry sherry (Note 2))","1/4 cup / 65ml Mirin (Note 2)","1 tbsp white sugar (brown also ok)","¾ cup / 180 ml water"],"purpose":"Teriyaki Sauce:"},{"ingredients":["500 g / 1 lb chicken mince (ground chicken) (or pork or turkey)","1 egg (preferably small 50g / 1.4 oz)","1 cup panko breadcrumbs (or ¾ cup normal breadcrumbs)","1 garlic clove (, minced)","1 ½ tsp cooking sake (, or sub with Chinese cooking wine or dry sherry (Note 2))","½ tsp salt"],"purpose":"Meatballs:"},{"ingredients":["1 tbsp oil","Sliced green onions / scallions (, for garnish (optional))","Sesame seeds (, for garnish (optional))"],"purpose":"Cooking:"}]', '[{"description":"Place Meatball ingredients in a bowl.","images":[],"step":1},{"description":"Place cornflour in a bowl with 1 tbsp of the water, then mix until lump free. Then add the soy sauce, sake, mirin and sugar, mix.","images":[],"step":2},{"description":"Add 2 tsp of Teriyaki Sauce into the Meatball bowl.","images":[],"step":3},{"description":"Add remaining water into the Sauce and mix. Set aside.","images":[],"step":4},{"description":"Mix Meatball mixture with your hands. Measure out 1 heaped tablespoon and roll into balls. See Note 3 for tips if mixture is too sticky.","images":[],"step":5},{"description":"Heat oil in a large skillet over medium high heat. Add all the meatballs and cook, rolling to brown all over, for 5 minutes. They will still be a bit raw inside.","duration":5,"images":[],"step":6},{"description":"Turn heat down. Give the Sauce a quick mix then add it into the pan. Bring to a simmer then cook for 2 - 3 minutes or until it thickens into a glossy sauce that coats the meatballs.","duration":2.5,"images":[],"step":7},{"description":"Serve over rice, garnished with green onions and sesame seeds if desired.","images":[],"step":8}]', '["egg","gluten","sesame","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Asian","Japanese","Western"],"categories":["asian-recipes","chicken-mince-recipes","chicken-recipes","dinner-tonight","main-dishes","meatball-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1769dff5dbb3', 'en', 'US', 'Chinese BBQ Chicken', 'The marinade for this chicken is based on the famous Chinese BBQ Pork (Char Siu), a very popular recipe on my blog! It’s sweet, savoury, sticky, laced with Chinese Five Spice. Add your own touch like ginger and chilli for a kick! The red food colouring is optional – it gives the chicken the reddish tinge that Char Siu is known for. Recipe VIDEO below, MARINATING TIME: 3 - 24 hrs.', 'https://www.recipetineats.com/tachyon/2017/06/Chinese-BBQ-Chicken-2.jpg', 5, 20, 25, 4, '[{"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_honey", "quantity": {"value": 0.045, "unit": "jar of 500g"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 1.0, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_five_spice", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_few_drops_red_food_colouring", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_skewers", "quantity": {"value": 10.0, "unit": "pack of 50"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["2 garlic cloves (, minced)","2 tsp brown sugar","1 1/2 tbsp honey","1 1/2 tbsp hoisin sauce","2 tsp oyster sauce","1 ½ tbsp light soy sauce (or all purpose)","1/2 tsp Chinese five spice powder (Note 1)","1/2 tsp sesame oil (not critical)","Few drops red food colouring (, optional)"],"purpose":"Marinade:"},{"ingredients":["750 g / 1.5lb chicken thigh fillets (, skinless boneless (or breast))","1 tbsp vegetable oil","10 – 12 bamboo skewers (, soaked in water for 1 hour (optional))","Green onions / scallions (, finely sliced, for garnish (optional))"],"purpose":"Chicken:"}]', '[{"description":"Place Marinade ingredients in a ziplock bag or bowl and mix to combine.","images":[],"step":1},{"title":"Add chicken and mix to coat. Marinade for 3","description":"24 hours.","images":[],"step":2},{"title":"Optional","description":"Cut chicken into bite size or large pieces and thread onto skewers. Use 1 skewer for small pieces, 2 for large, like pictured in post.","images":[],"step":3},{"description":"Heat half the oil in a heavy based skillet over medium high heat, or BBQ on medium (if using grill side, brush oil on bars).","images":[],"step":4},{"description":"Remove chicken from marinade (RESERVE for basting) and place in the skillet - cook in 2 batches, don''t crowd the pan. Cook for 4 minutes then turn.","duration":4,"images":[],"step":5},{"description":"Use the Marinade to baste the cooked side of the chicken. After 3 minutes, turn the chicken over so the basted side is now cooking again - cook for 1 minute.","duration":1,"images":[],"step":6},{"description":"Baste the chicken, then turn again and cook for 45 sec - 1 min.","duration":0.75,"images":[],"step":7},{"description":"Transfer chicken to a plate, cover loosely with foil and rest for 5 minutes.","duration":5,"images":[],"step":8},{"description":"Serve, garnished with green onions / scallions if using!","images":[],"step":9}]', '["gluten","sesame","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","chinese-recipes","grilling-ideas-and-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_215f822ca070', 'en', 'US', 'Beef Rendang', 'RECIPE VIDEO above. Beef Rendang is a Malaysian curry and is an extravagantly rich dish that is easy to prepare but takes time and patience to slow cook. Unlike many curries, this is a "dry" curry which means the beef is not swimming in sauce. Though you may think that the sauce is often the best part of a curry, the beef is "fall apart at a touch" tender and covered in a thick, saucy curry which then mixes through the rice so it is not in the least bit "dry"! This can be made in a slow cooker (see notes) but I recommend making this on the stove for best results.', 'https://www.recipetineats.com/tachyon/2014/11/Beef-Rendang-13.jpg', 20, 180, 200, 6, '[{"id": "ing_chilli", "quantity": {"value": 12.0, "unit": "pack of 100g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 8.333, "unit": "pack of 3 heads"}}, {"id": "ing_lemongrass", "quantity": {"value": 60.0, "unit": "bunch"}}, {"id": "ing_galangal", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_ginger", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_beef_steak", "quantity": {"value": 0.907, "unit": "kg"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_powder", "quantity": {"value": 1.25, "unit": "jar"}}, {"id": "ing_star_anise", "quantity": {"value": 3.0, "unit": "jar"}}, {"id": "ing_cardamon", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_lemongrass", "quantity": {"value": 60.0, "unit": "bunch"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_water", "quantity": {"value": 12.0, "unit": "L"}}, {"id": "ing_lime", "quantity": {"value": 8.0, "unit": "net of 500g"}}, {"id": "ing_desiccated_coconut", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}]', '[{"ingredients":["12 dried chilies, rehydrated in boiling water, or 12 large fresh (Note 1a)","1 small onion, finely chopped (Note 1b)","5 cloves garlic, minced","3 lemongrass stalks, white part only, sliced (Note 2)","1 1/2 tbsp fresh galangal, finely chopped (Note 3)","1 1/2 tbsp fresh ginger, minced","2 tbsp oil (vegetable, canola or peanut oil)"],"purpose":"Spice Paste"},{"ingredients":["2 lb/ 1 kg chuck steak, or other slow cooking beef, cut into 4cm / 1.6\" cubes (Note 4)","1 tbsp oil (vegetable, peanut, canola)","1 cinnamon stick","1/4 tsp clove powder","3 star anise","1/2 tsp cardamon powder","1 lemongrass stick, bottom half of the stick only and smashed (Note 5)","400ml / 14 oz coconut milk (1 standard can)","2 tsp tamarind puree / paste, or tamarind pulp soaked in 1 tbsp of hot water, seeds removed (Note 6)","4 large kaffir lime leaves (or 6 small) , very finely sliced (Note 7)","1/3 cup desiccated coconut (finely shredded coconut)","1 tbsp brown sugar or grated palm sugar","1 1/2 tsp salt"],"purpose":"Curry"}]', '[{"description":"Place Spice Paste ingredients in a small food processor and whizz until fine. NOTE: If using dried chilli and you know your food processor is not that powerful, chop the chilli first.","images":[],"step":1},{"description":"Heat 1 tbsp oil in a large heavy based pot over high heat. Add half the beef and brown, then remove onto plate. Repeat with remaining beef.","images":[],"step":2},{"description":"Lower heat to medium low. Add Spice Paste and cook for 2 - 3 minutes until the wetness has reduced and the spice paste darkens (don''t breathe in too much, the chilli will make you cough!).","duration":2.5,"images":[],"step":3},{"description":"Add remaining Curry ingredients and beef. Stir to combine.","images":[],"step":4},{"description":"Bring to simmer, then immediately turn down the heat to low or medium low so the sauce is bubbling very gently.","images":[],"step":5},{"description":"Put the lid on the pot and leave it to simmer for 1 hr 15 minutes.","duration":60,"images":[],"step":6},{"description":"Remove lid and check the beef to see how tender it is. You don''t want it to be \"fall apart at a touch\" at this stage, but it should be quite tender. If it is fall apart already, remove the beef from the pot before proceeding.","images":[],"step":7},{"title":"Turn up heat to medium and reduce sauce for 30","description":"40 minutes, stirring every now and then at first, then frequently towards the end until the beef browns and the sauce reduces to a paste that coats the beef. (Note 9)","duration":35,"images":[],"step":8},{"description":"The beef should now be very tender, fall apart at a touch. If not, add a splash of water and keep cooking. Remove from heat and serve with plain or Restaurant Style Coconut Rice.","images":[],"step":9}]', '["peanuts"]', '["gluten_free","high_protein"]', '{"mealType":["main_course"],"cuisine":["Asian","Malaysian"],"categories":["asian-recipes","asian-takeout","beef-recipes","curry-recipes","dietary","gluten-free-recipes","main-dishes","slow-cooker-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b0e6e7ac26e5', 'en', 'US', 'Thai Coconut Marinated Chicken', 'Recipe video above. Chicken infused in a gorgeous Thai coconut marinade which infuses with flavour and adds buttery richness from the coconut milk. MARINATING TIME: 24 - 48 hours.', 'https://www.recipetineats.com/tachyon/2017/05/Thai-Coconut-Marinated-Chicken-4.jpg', 15, 10, 25, 5, '[{"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_lemongrass", "quantity": {"value": 20.0, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_turmeric", "quantity": {"value": 0.007, "unit": "jar"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.469, "unit": "can of 400ml"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.04, "unit": "jar of 375g"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_ime_juice", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 0.045, "unit": "net of 500g"}}]', '[{"ingredients":["1 tsp garlic (, minced)","1 tsp ginger (, minced)","1 tsp chilli (, finely chopped (or paste is fine), adjust quantity to taste (Note 2))","1 lemongrass (OR paste) (, white part only, finely chopped(Note 3))","1 1/2 tsp coriander powder","3/4 tsp tumeric powder","1/2 tsp curry powder (any is fine)","1 tbsp brown sugar","2 1/2 tbsp fish sauce (sub soy)","3/4 cup coconut milk (full fat please!)"],"purpose":"Marinade (Note 1):"},{"ingredients":["750 g - 1 kg / 1.5 - 2 lb chicken thigh fillets (, skinless and boneless (Note 4))","Oil for cooking"],"purpose":"Chicken:"},{"ingredients":["1/2 cup coconut milk","1 tbsp peanut butter, smooth","2 tbsp Hoisin Sauce","1 1/2 tbsp lime juice","1 garlic clove (, minced)","1/2 tsp chilli paste or fresh chilli (, adjust to taste)"],"purpose":"Coconut Peanut Sauce:"},{"ingredients":["Finely chopped coriander / cilantro and more chilli (, for garnish)","Lime wedges (highly recommended)"],"purpose":"Garnish (optional):"}]', '[{"description":"Mix marinade in a large bowl. Add chicken and mix. Cover with cling wrap and marinate in the fridge for 24 - 48 hours (can''t skip marinating for this recipe).","images":[],"step":1},{"description":"Brush BBQ with oil, or heat 1 tbsp in a skillet (I used a skillet). Use Medium heat - or Medium Low if your stove/BBQ runs hot (otherwise marinade may burn).","images":[],"step":2},{"description":"Remove chicken from marinade, shaking off excess. Cook the first side for around 5 minutes or until caramelised and golden. Turn then cook the other side for 4 minutes until caramelised.","duration":4,"images":[],"step":3},{"title":"BAKING","description":"See Note 4.","images":[],"step":4},{"description":"Transfer chicken to serving plate, cover loosely with foil and rest for 5 minutes. Garnish with coriander / chilli if desired, and serve with lime wedges and Sauce.","duration":5,"images":[],"step":5},{"description":"Place ingredients in a bowl and mix a bit. Microwave for 30 seconds, then mix until smooth. Bring to room temperature or serve warm (it thickens a bit when cooled).","duration":0.5,"images":[],"step":6}]', '["fish","peanuts","soy"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","cuisines","dietary","gluten-free-recipes","grilling-ideas-and-recipes","quick-and-easy","thai-recipes","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_309e35313cf4', 'en', 'US', 'Chinese Cashew Chicken MEATBALLS!', 'Everything you know and love about Chinese Cashew Chicken - made with meatballs! Recipe video below.', 'https://www.recipetineats.com/tachyon/2017/02/Cashew-Chicken-Meatballs-3.jpg', 20, 15, 35, 4, '[{"id": "ing_soy_sauce", "quantity": {"value": 0.25, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.125, "unit": "bottle of 500ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.25, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.037, "unit": "pack of 400g"}}, {"id": "ing_chicken_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_bread", "quantity": {"value": 0.141, "unit": "loaf"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_cashews", "quantity": {"value": 150.0, "unit": "jar"}}]', '[{"ingredients":["1/4 cup soy sauce, ordinary or light (Note 1)","1/4 cup Chinese cooking wine (shaoshing wine, or sub with dry sherry) (Note 4)","1/4 cup Oyster sauce","2 tsp sesame oil"],"purpose":"Sauce – Part 1:"},{"ingredients":["1 tbsp cornflour / cornstarch"],"purpose":"Sauce – Part 2:"},{"ingredients":["500g/1lb chicken mince (ground chicken)","2 cloves garlic, minced","1 egg, small (Note 2)","3/4 cup panko breadcrumbs","1/2 tsp salt","1/4 tsp white pepper (or sub with black)"],"purpose":"Meatballs:"},{"ingredients":["2 tbsp peanut oil (or vegetable or canola)","1 clove garlic, minced","1 small onion, sliced","1 green capsicum / bell pepper, chopped into 1.75cm / 2/3\"","3/4 cup water","1 cup cashews, unsalted"],"purpose":"Stir Fry:"}]', '[{"description":"Place Sauce Part 1 ingredients in a jar and shake well. Place 2 tsp Sauce into a large bowl that you will be making the Meatballs in. Then add the cornflour into the Sauce jar and shake. Set Sauce aside.","images":[],"step":1},{"description":"Add remaining Meatballs ingredients into the bowl. Mix until just combined.","images":[],"step":2},{"description":"Measure out a heaped tablespoon of mixture and dollop onto a work surface. Then roll into balls (see Note 2 if mixture is too loose / sticky to form into balls).","images":[],"step":3},{"description":"Heat oil in a skillet over medium high heat. Add meatballs and cook, browning as best you can all over, or at least on both sides. Once browned all over (about 4 minutes), carefully transfer onto a plate. They will still be a bit raw inside.","images":[],"step":4},{"description":"Return skillet to the stove, still on medium high. Add onion and garlic, cook for 1 minute. Add capsicum and cook for 1 minute. Add Sauce and water and quickly mix - it will simmer quickly.","duration":1,"images":[],"step":5},{"description":"Transfer meatballs (and juices on the plate) into the Sauce. Turn heat down to medium and simmer, stirring occasionally, for 3 - 4 minutes, or until the Sauce reduces and thickens (by which time the meatballs will be cooked).","duration":3.5,"images":[],"step":6},{"description":"Stir through cashews, serve over rice!","images":[],"step":7}]', '["egg","gluten","peanuts","sesame","soy"]', '[]', '{"mealType":["main_course"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chicken-mince-recipes","chicken-recipes","chinese-recipes","meatball-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5a34a1ade631', 'en', 'US', 'Sticky Chicken Drumsticks in Chinese Plum Sauce', 'A fantastic one for midweek and a crowd pleaser! These sticky chicken drumsticks are baked in the oven until tender, and basted with an incredible Chinese plum sauce which is sweet with a touch of tang and the beautiful fragrance of plum. See notes for skipping the marinating time!', 'https://www.recipetineats.com/tachyon/2017/02/Sticky-Baked-Chicken-Drumsticks-in-Plum-Sauce-4.jpg', 5, 50, 55, 4, '[{"id": "ing_chicken", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_fountain_plum_sauce", "quantity": {"value": 112.5, "unit": "bottle"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.25, "unit": "bottle of 250ml"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_chinese_five_spice", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1.2kg / 2.4lb large chicken drumsticks (8 drumsticks)"]},{"ingredients":["3/4 cup / 185ml Fountain Plum Sauce (Note 1)","1/3 cup brown sugar (can reduce to 1/4 cup)","1/4 cup soy sauce (all purpose or light, not dark soy sauce)","2 tbsp Hoisin Sauce","2 cloves garlic, (minced)","1/2 tsp ginger, (minced)","1/2 tsp Chinese Five Spice Powder (Note 2)"],"purpose":"Plum Marinade / Glaze"},{"ingredients":["Sesame seeds","Finely chopped scallions"],"purpose":"Garnish (optional)"}]', '[{"description":"Place Marinade ingredients in a ziplock bag (or bowl) and mix. Add chicken and massage to coat in the Marinade. Refrigerate for 1 hour (see Note 3 for skipping this).","images":[],"step":1},{"description":"Preheat oven to 180C/350F (all types).","images":[],"step":2},{"description":"Line a tray with baking paper / parchment paper (or foil then spray with oil).","images":[],"step":3},{"description":"Transfer chicken to tray, shaking off excess marinade. RESERVE Marinade.","images":[],"step":4},{"title":"Baking & Basting (Total bake time","description":"50 min)","images":[],"step":5},{"description":"Bake chicken for 20 minutes.","duration":20,"images":[],"step":6},{"description":"Remove from oven. Spoon / slather / brush with reserve marinade (generously!) (Note 4). Bake for 10 minutes.","duration":10,"images":[],"step":7},{"description":"Remove from oven and TURN chicken. Baste again using tray juices and reserved marinade. Bake for 10 minutes.","duration":10,"images":[],"step":8},{"description":"Remove from oven and baste again (very generously!) using tray juices and reserved marinade. Bake for 10 minutes.","duration":10,"images":[],"step":9},{"description":"Remove chicken from oven and scrape/brush tray juices onto chicken (don''t waste free flavour!).","images":[],"step":10},{"description":"Sprinkle with sesame seeds and shallots/scallions if using. I served it with rice and steamed broccolini.","images":[],"step":11}]', '["gluten","sesame","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Asian-esque"],"categories":["asian-recipes","chicken-drumstick-recipes","chicken-recipes","dinner-tonight","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_39ecd939f19a', 'en', 'US', 'Chinese Satay Chicken Stir Fry', '{Video below} My homemade copycat of the Chinese takeout favourite - chicken satay stir fry! The coconut and peanut flavour is not as intense as Malaysian and Thai satay sauce, and the satay seasoning flavour is stronger. The chicken is tenderised the way Chinese restaurants do - perfect to make breast nice and juicy. This step is optional, but I think it''s worth it for a true Chinese restaurant experience! MARINATING TIME: 20 minutes for tenderising, 10 minutes for seasoning, both optional.', 'https://www.recipetineats.com/tachyon/2017/02/Chicken-in-Satay-Sauce-3.jpg', 15, 5, 20, 2, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.227, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.019, "unit": "tub of 200g"}}, {"id": "ing_coriander", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_turmeric", "quantity": {"value": 1.25, "unit": "jar"}}, {"id": "ing_chilli", "quantity": {"value": 0.013, "unit": "pack of 100g"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.15, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.06, "unit": "jar of 375g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_sriracha", "quantity": {"value": 0.025, "unit": "bottle of 400ml"}}, {"id": "ing_lemongrass", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.208, "unit": "can of 400ml"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["8 oz / 250g chicken breast","3/4 tsp baking soda (bi carb soda) (optional)"],"purpose":"Tenderised Chicken, optional (Note 5)"},{"ingredients":["1/2 tsp coriander powder","1/2 tsp cumin powder","1/4 tsp turmeric powder","1/4 tsp chilli powder (Not US Chilli powder! See Note 1)","1 1/2 tsp Curry Powder (Note 2)","1/2 tsp salt","1/4 tsp white pepper"],"purpose":"Satay Seasoning"},{"ingredients":["1 1/2 tbsp smooth peanut butter","2 tsp brown sugar","1 tsp light soy sauce (Note 3)","2 tsp rice vinegar","2 tsp Sriracha (or other hot sauce)","1/2 tsp lemongrass paste (Note 4)","1/3 cup coconut milk (full fat)","1/4 cup water"],"purpose":"Satay Sauce"},{"ingredients":["1 tbsp peanut oil (or other plain oil)","1 onion (, finely chopped)","2 garlic cloves (, minced)","Shallots/scallions (, sliced (optional garnish))"],"purpose":"Stir Fry"}]', '[{"description":"Tenderise Chicken (optional)","images":[],"step":1},{"description":"Cut chicken in half length wise then slice thinly. Place in a bowl with baking soda, use fingers to coat. Set aside for 20 minutes.","duration":20,"images":[],"step":2},{"description":"Rinse well, pat dry with paper towel then place in a bowl.","images":[],"step":3},{"description":"Seasoning","images":[],"step":4},{"description":"Mix together Seasoning.","images":[],"step":5},{"description":"Sprinkle 1 tsp of Seasoning over chicken. Mix to coat then set aside for 10 minutes (not critical, can skip this).","duration":10,"images":[],"step":6},{"description":"Place all ingredients except water in a bowl. Add remaining Seasoning. Mix, then add water and mix.","images":[],"step":7},{"description":"Heat oil in wok or skillet over high heat. Add onion and garlic, stir fry for 1 minute.","duration":1,"images":[],"step":8},{"description":"Add chicken and stir fry for 2 minutes until just cooked through and a bit browned.","duration":2,"images":[],"step":9},{"description":"Lower heat slightly, then add Sauce. Stir fry until it reduce down and becomes thicker - 1 to 1 1/2 minutes.","images":[],"step":10},{"title":"Serve immediately with rice","description":"or for a low carb, low cal option, try Cauliflower Rice! Garnish with sliced shallots/scallions if desired.","images":[],"step":11}]', '["gluten","peanuts","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-recipes","chinese-recipes","dinner-tonight","main-dishes","quick-and-easy","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a3bfc3967cfe', 'en', 'US', 'Asian Salmon Salad', 'A fresh salad topped with a gloriously sticky Asian Salmon, then drizzled with the salmon glaze and finished with an incredible (yet simple!) Asian Sesame Dressing. Quick to prepare and packs a flavour punch! Tip: Don''t cook the salmon for any longer than 3 minutes, otherwise it will overcook! {Recipe video below}', 'https://www.recipetineats.com/tachyon/2017/02/Asian-Salmon-Salad-4.jpg', 12, 3, 15, 2, '[{"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_sriracha", "quantity": {"value": 0.037, "unit": "bottle of 400ml"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_salmon_fillets", "quantity": {"value": 250.0, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_lettuce", "quantity": {"value": 15.0, "unit": "head"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 15.0, "unit": "punnet of 250g"}}, {"id": "ing_avocado", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_cucumber", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_white_vinegar", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.5, "unit": "bunch"}}]', '[{"ingredients":["1 tbsp soy sauce (, low sodium / ordinary (Note 1))","2 tbsp EACH hoisin sauce, rice vinegar, honey (Note 2)","1 tbsp sriracha (, or other hot sauce (can omit))","2 tbsp water","1 garlic clove (, minced)"],"purpose":"Sauce"},{"ingredients":["250 - 300 g / 8 - 10 oz salmon (, skin off)","2 tsp oil (vegetable, canola, peanut oil)","5 cups lettuce (, bite size pieces (I used cos lettuce))","15 cherry tomatoes (, halved)","1/2 avocado (, sliced)","1 cucumber (, halved, deseeded and sliced (Note 3))"],"purpose":"Salmon & Salad"},{"ingredients":["1 tbsp soy sauce (Note 1)","1 tsp sesame oil","1½ tbsp white vinegar","1 tbsp olive oil (Note 4)","1 tsp sugar ((any type) or 1½ tsp honey)"],"purpose":"Asian Sesame Dressing"},{"ingredients":["1/2 tsp sesame seeds","1/2 scallion / shallot (, finely sliced)"],"purpose":"Optional Garnishes"}]', '[{"description":"Cut salmon into 2.5cm / 1\" cubes.","images":[],"step":1},{"description":"Mix Sauce in a medium bowl. Add salmon, set aside for 3 minutes.","duration":3,"images":[],"step":2},{"description":"Mix Dressing ingredients in a jar. Shake very well (jar is best).","images":[],"step":3},{"description":"Divide Salad ingredients between 2 bowls.","images":[],"step":4},{"description":"Heat oil in a non stick medium skillet over medium high heat. Remove salmon from Sauce, shaking off excess. Reserve Sauce.","images":[],"step":5},{"description":"Place salmon in skillet. Cook for 2 minutes, turning to caramelise as many of the sides as you can (all sides is not practical, too much turning). (Note 5)","duration":2,"images":[],"step":6},{"description":"Pour Sauce into skillet. Cook for 30 seconds or until the Sauce reduces to a syrup (see video for how it bubbles).","duration":0.5,"images":[],"step":7},{"description":"Remove from stove. Immediately transfer salmon onto Salad. Leave to rest / cool for a few minutes. Then spoon the glaze over the salmon. Sprinkle with sesame seeds and shallots/scallions, if using.","images":[],"step":8},{"description":"Drizzle salad with Dressing. Serve immediately.","images":[],"step":9}]', '["fish","gluten","peanuts","sesame","soy"]', '[]', '{"mealType":["lunch"],"cuisine":["Asian"],"categories":["asian-recipes","dinner-tonight","fish-recipes","main-dishes","quick-and-easy","salad-recipes-main-course","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3d94717200ce', 'en', 'US', 'Chinese Chicken Salad with Asian Peanut Salad Dressing', 'A crunchy Chinese chicken salad tossed with a lip smackingly delicious peanut dressing, this is the sort of salad that''s a truly satisfying meal in itself!', 'https://www.recipetineats.com/tachyon/2016/12/Chinese-Chicken-Salad-Peanut-Dressing-15.jpg', 15, 0, 15, 2, '[{"id": "ing_peanut_butter", "quantity": {"value": 0.1, "unit": "jar of 375g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_oil", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_sriracha", "quantity": {"value": 0.025, "unit": "bottle of 400ml"}}, {"id": "ing_honey", "quantity": {"value": 0.03, "unit": "jar of 500g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_cabbage", "quantity": {"value": 4.5, "unit": "head"}}, {"id": "ing_red_cabbage", "quantity": {"value": 3.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 225.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 1.5, "unit": "bag of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_peanuts", "quantity": {"value": 0.094, "unit": "jar"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.25, "unit": "pack of 500g"}}]', '[{"ingredients":["2 1/2 tbsp peanut butter","2 tsp toasted sesame oil","1 tbsp canola oil (or vegetable, grapeseed or peanut oil)","2 tsp soy sauce","2 tsp+ Sriracha","1 tbsp honey","1 tbsp + 2 tsp rice wine vinegar","1 - 1 1/2 tbsp water (or lime juice)","1 garlic clove (, minced)","1/2 tsp ginger (, freshly grated)"],"purpose":"Dressing"},{"ingredients":["1 1/2 cups Chinese cabbage / Napa cabbage (, shredded)","1 cup red cabbage (, shredded)","1 1/2 cups carrots (, julienned (I used Just Veg pre shredded carrots) (Note 1))","1 1/2 cups shredded cooked chicken","1 1/2 cups bean sprouts","1 shallot / green onion / scallion (, finely sliced on the diagonal)","1/4 cup peanuts (, roughly chopped)","1/4+ cups crunchy fried noodles (I use Changs)"],"purpose":"Salad"}]', '[{"description":"Mix Dressing in a jug or small bowl. Use water to adjust consistency (it should be pretty thick and gloopy), Sriracha for spiciness and saltiness with salt (not more soy sauce).","images":[],"step":1},{"description":"Place all Salad ingredients in a bowl, reserving some noodles, peanuts and shallots for topping. Drizzled with Dressing and toss. Garnish with remaining noodles, peanuts and shallots and serve immediately.","images":[],"step":2}]', '["gluten","peanuts","sesame","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["lunch"],"cuisine":[],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","chinese-recipes","dinner-tonight","main-dishes","most-popular","quick-and-easy","salad-recipes-main-course"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bc482fdc5f3e', 'en', 'US', 'Chinese Steamed Fish with Ginger Shallot Sauce', 'Steamed Chinese Fish with a Ginger and Shallot Sauce! Love the drama as the hot oil is poured over the fresh ginger and shallots, cooking it and creating the gorgeous sauce. This recipe is one of those true treasures that are simple yet taste so incredible, and it''s healthy too! The fish can be steamed or baked - refer photos in post or video below recipe.', 'https://www.recipetineats.com/tachyon/2016/11/Chinese-Fish-Ginger-Shallot-Sauce-9.jpg', 5, 15, 20, 2, '[{"id": "ing_fish_fillets", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_ginger", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_japanese_cooking_sake", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_salt", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_oil", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["2 x 350 - 400g / 12 - 13 oz bream or snapper fish (, gutted, scaled and cleaned (Note 1))","2 stems of shallots ((scallions / green onions), diagonally julienned to 5cm/2\" length)","4 x 3cm / 1 x 2\" piece of ginger julienned","2 tbsp Japanese cooking sake (Note 2)","2 pinches of salt","3 tsp soy sauce (Note 3)","2 tsp sesame oil","4 tbsp oil (vegetable, canola or peanut oil)"]},{"ingredients":["Red chilli julienned (Note 4)"],"purpose":"Garnish (optional)"}]', '[{"description":"Cut 2 slashes on each side of the fish. Cut through to the bone.","images":[],"step":1},{"description":"Drizzle 1 tbsp of sake onto each fish.","images":[],"step":2},{"description":"Steam fish using method of choice, or bake (see directions below).","images":[],"step":3},{"description":"Meanwhile, heat oil over medium high heat until hot.","images":[],"step":4},{"description":"Transfer fish onto serving plates. Top with shallots and ginger.","images":[],"step":5},{"description":"Sprinkle with salt, drizzle over soy sauce and sesame oil.","images":[],"step":6},{"title":"Pour oil over fish","description":"enjoy the drama as it bubbles!","images":[],"step":7},{"description":"Sprinkle with red chilli if using and serve with rice and steamed Asian Greens.","images":[],"step":8},{"description":"Bamboo steamers in wok (see video)","images":[],"step":9},{"description":"Place fish on a plate and put plate in bamboo steamer. Repeat with other fish. Stack bamboo steamers and put lid on.","images":[],"step":10},{"description":"Fill wok with water, ensuring it doesn''t touch the bottom of the steamer. Bring water to boil over high heat, then place bamboo steamer on wok.","images":[],"step":11},{"description":"Steam for 10 minutes. Carefully transfer fish onto serving places.","duration":10,"images":[],"step":12},{"description":"Wrap each fish in foil, place on tray. Bake at 180C/350F for 15 minutes. Open foil and carefully transfer fish onto serving plates.","duration":15,"images":[],"step":13},{"description":"Steamer fitted inside a large pot, or a microwave steamer.","images":[],"step":14}]', '["fish","gluten","peanuts","sesame","soy"]', '["keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","chinese-recipes","dietary","dinner-tonight","fish-recipes","gluten-free-recipes","main-dishes","seafood-recipes","yum-cha-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d07ba27a9a33', 'en', 'US', 'Foolproof Poached Chicken with Ginger Shallot Sauce', 'A foolproof method for poaching chicken breast with guaranteed juicy chicken every single time. Served with a Ginger Shallot (Scallion) Sauce that is so good, you will want to put it on everything! Also accompanied with a quick chilli sauce (optional). This is like a (much) faster, healthier midweek version of the famous Hainanese Chicken & Rice. Also see cooking video below recipe - don''t miss the Dozer cameo at the end! HIGH ALTITUDE locations - please see note 4', 'https://www.recipetineats.com/tachyon/2016/10/Foolproof-Poached-Chicken-Ginger-Shallot-Sauce-2.jpg', 10, 25, 35, 3, '[{"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_ginger", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.075, "unit": "L"}}, {"id": "ing_chilli", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_sriracha", "quantity": {"value": 0.037, "unit": "bottle of 400ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}]', '[{"ingredients":["2 chicken breasts (, boneless skinless, 250g/8.5 oz each (Note 1))"]},{"ingredients":["3 - 4 shallots / scallions (, green and white part thinly sliced (1 heaped cup))","2 tbsp finely grated ginger","1/4 tsp salt","5 tbsp vegetable oil (or peanut or grapeseed oil)"],"purpose":"Ginger Shallot Sauce"},{"ingredients":["1 tbsp chilli paste","1 tbsp Sriracha","1 tsp soy sauce","1 tsp sugar","1 garlic clove","1 tsp grated ginger"],"purpose":"Quick Chilli Sauce"}]', '[{"description":"Take chicken out of the fridge 30 minutes before cooking.","images":[],"step":1},{"description":"Fill a saucepan with water so the chicken breast will be well submerged with at least 2\" / 5cm of water above it.","images":[],"step":2},{"description":"Bring water to boil. Place chicken breast in water, place lid on, bring back up to the boil. Remove saucepan from stove and set aside for 20 minutes (it''s fine up to 45 min, won''t overcook).","duration":20,"images":[],"step":3},{"description":"Remove chicken from water and slice. Serve with Sauces (below) and rice.","images":[],"step":4},{"description":"Ginger Shallot Sauce","images":[],"step":5},{"description":"Combine and mix ingredients in a bowl. Set side for 20 minutes. It will sweat and become more liquidy.","duration":20,"images":[],"step":6},{"description":"Mix ingredients in a bowl. Set aside for 15 minutes.","duration":15,"images":[],"step":7}]', '["gluten","peanuts","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","chinese-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f29906a3807d', 'en', 'US', 'Sweet and Sour Chicken Stir Fry', 'This bright and colourful stir fry is made with a classic Sweet & Sour Sauce which is truly like what you get at good Chinese restaurants. This is not made by deep frying the chicken - it''s tasty enough as it is without adding more calories!! Also see Baked version of the fried Sweet & Sour Chicken - recipe here. I know 1/2 cup of sugar sounds like a lot, but it works out at 1 1/2 tbsp per serving, which isn''t too bad!', 'https://www.recipetineats.com/tachyon/2016/09/Sweet-and-Sour-Chicken-Stir-Fry-8.jpg', 10, 10, 20, 4, '[{"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.167, "unit": "bottle of 500ml"}}, {"id": "ing_pineapple", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_ketchup", "quantity": {"value": 0.09, "unit": "bottle of 500g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_pineapple", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1/2 cup white sugar (Note 1)","1/3 cup apple cider vinegar","3 tbsp pineapple juice (from the canned pineapple pieces)","3 tbsp ketchup (Australia: tomato sauce)","1 tsp Worcestershire sauce (Note 2)","1 tsp soy sauce (, light or all purpose (Note 2))","1 tsp Oyster Sauce (Note 2)","1/4 tsp salt"],"purpose":"Sauce"},{"ingredients":["1 tbsp cornflour / corn starch + 2 tbsp water (, mixed together)"],"purpose":"Thickener"},{"ingredients":["1 1/2 tbsp peanut oil (or vegetable)","1 garlic clove (, minced or finely chopped)","1 onion (, halved and sliced (brown, yellow or white) (see photo in post))","400 g / 13 oz chicken thigh fillets (, cut into bite size pieces (Note 3))","1 red capsicum / bell pepper (, cut into bite size pieces)","1 green or yellow capsicum / bell pepper (, cut into bite size pieces)","1 can ((8oz/250g) canned pineapple pieces in natural juice. Separate pineapple from juice.)","Sliced shallots / scallions (, for garnish)"],"purpose":"Stir Fry"}]', '[{"description":"Mix together Sauce ingredients. Mix together Thickener in a separate small bowl.","images":[],"step":1},{"description":"Heat oil in a wok or skillet over high heat. Add garlic and onion, cook for 1 minute.","duration":1,"images":[],"step":2},{"description":"Add chicken and stir fry until it it is white all over but still pink inside.","images":[],"step":3},{"description":"Add capsicum and stir fry for 2 minutes.","duration":2,"images":[],"step":4},{"description":"Add Sauce ingredients. Stir until sugar has dissolved and the sauce begins to bubble.","images":[],"step":5},{"description":"Add Thickener. Bring to simmer, stirring constantly. Then cook until it thickens to a syrup consistency - about 3 minutes.","images":[],"step":6},{"description":"Stir through pineapple pieces (just to warm) and remove from stove.","images":[],"step":7},{"title":"Serve immediately with rice","description":"or for a low carb, low cal option, try Cauliflower Rice! Garnish with shallots if desired.","images":[],"step":8}]', '["gluten","peanuts","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-recipes","chinese-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","most-popular","quick-and-easy","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_727fe1250725', 'en', 'US', 'Truly Crispy Oven Baked Chicken Wings', 'VIDEO above in post. Learn how EASY it is to make SERIOUSLY Crispy Oven Baked Wings! The secret is tossing the wings in baking powder and baking it on low first to render out the fat before increasing the heat to very high to make the skin crispy. Serve these with one of the SAUCES in the notes. Also see FREQUENTLY ASKED QUESTIONS below the recipe.', 'https://www.recipetineats.com/tachyon/2014/11/Crispy-Baked-Wings_6.jpg', 10, 70, 80, 6, '[{"id": "ing_chicken", "quantity": {"value": 1.814, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 5.0, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}]', '[{"ingredients":["4 lb / 2 kg chicken wings (, cut into wingettes and drumettes (Note 1))","5 teaspoons baking powder (NOT BAKING SODA / BI-CARB SODA!!)","3/4 teaspoon salt","Oil spray"],"purpose":"Crispy Wings"}]', '[{"description":"If you are organised enough, uncover the chicken wings and leave them in the fridge for a few hours to dry out. Otherwise, use a paper towel to pat the wings dry.","images":[],"step":1},{"description":"Adjust oven racks to upper-middle and lower-middle positions.","images":[],"step":2},{"title":"Preheat oven to 250F/120C (all oven types","description":"standard/convection/fan).","images":[],"step":3},{"description":"Line a baking tray with foil, then place a rack (like a cooling rack) on the foil. Spray the rack with oil spray.","images":[],"step":4},{"description":"Place wings in a large bowl or in a ziplock bag. Add the baking powder and salt, then toss to coat evenly.","images":[],"step":5},{"description":"Place the wings on the baking tray in a single layer with the skin side up. They should just fit snugly. They will shrink when they cook because the fat renders out so don''t worry if they look too snug.","images":[],"step":6},{"description":"Place wings on the lower middle oven rack and bake for 30 minutes.","duration":30,"images":[],"step":7},{"description":"Move wings up to the upper middle rack and increase the oven temperature to 425F/220C. Bake for 40 - 50 minutes, rotating the tray halfway through.","duration":45,"images":[],"step":8},{"description":"Remove baking tray from the oven and let it stand for 5 minutes.","duration":5,"images":[],"step":9},{"description":"Toss wings in sauce of choice or serve it on the side to dip / drizzle on the wings, then serve.","images":[],"step":10}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["snack"],"cuisine":[],"categories":["asian-recipes","chicken-recipes","chicken-wings","dietary","dinner-tonight","gluten-free-recipes","main-dishes","most-popular","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_242962313501', 'en', 'US', 'Asian Chicken (Asian marinade)', 'A great all rounder Asian Marinade that infuses chicken with sweet/savoury flavours. This Asian chicken can be grilled, baked or cooked on the stove! MINIMUM MARINADE TIME: 1 hour (or overnight)', 'https://www.recipetineats.com/tachyon/2016/06/Asian-Marinated-Chicken_Hero.jpg', 10, 10, 20, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.045, "unit": "bottle of 500ml"}}, {"id": "ing_sriracha", "quantity": {"value": 1.0, "unit": "bottle of 400ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.01, "unit": "pack of 100g"}}, {"id": "ing_oil", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1 - 1.5 lb / 500 - 750g chicken thigh fillets (, skinless boneless)"]},{"ingredients":["3 cloves garlic (, minced)","2 tsp ginger (, freshly grated)","2 tbsp soy sauce","2 tbsp tomato ketchup","2 tbsp Oyster sauce","1 1/2 tbsp Chinese cooking wine OR Mirin (Note 1)","1 - 3 tbsp Sriracha (adjust spiciness to taste)","2 tbsp brown sugar","1 tsp sesame oil"],"purpose":"Asian Marinade (see notes for subs)"},{"ingredients":["2 tsp oil","Sesame seeds","Finely sliced shallots / green onions","Finely sliced red chilies"],"purpose":"Cooking / Garnishes (optional)"}]', '[{"description":"Mix Marinade ingredients together. Add chicken and mix to coat. Marinade in the fridge for a minimum of 1 hour or up to overnight.","images":[],"step":1},{"description":"Heat oil in a large non stick skillet or BBQ over medium high heat. (See notes for other cooking methods) Add chicken and cook until each side is dark golden brown and chicken is cooked through (about 3 minutes each side). Transfer to plate, cover loosely with foil and rest for 3 minutes.","duration":3,"images":[],"step":2},{"description":"Garnish with chillies, shallots and sesame seeds if desired. Serve with white rice and slices of cucumber.","images":[],"step":3}]', '["gluten","sesame","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","dietary","gluten-free-recipes","grilling-ideas-and-recipes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b4e91c0f7a18', 'en', 'US', 'Chinese Fried Rice with Shrimp / Prawns', 'This is a simple, traditional Chinese Fried Rice recipe by Kylie Kwong, Australia''s most well known Chinese Chef. The key to an authentic tasting fried rice like you get at proper Chinese restaurants is the Sauce, using day old or cold fresh cooked rice and ensuring you don''t overcrowd the wok, causing the rice to stew instead of stir fry! Feel free to add more vegetables (not too much otherwise the sauce will thin out) or substitute the prawns with other proteins.', 'https://www.recipetineats.com/tachyon/2016/05/Chinese-Fried-Rice_2.jpg', 10, 10, 20, 3, '[{"id": "ing_oil", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_bacon", "quantity": {"value": 0.562, "unit": "pack of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_shrimp", "quantity": {"value": 0.142, "unit": "kg"}}, {"id": "ing_white_rice", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.025, "unit": "pack of 100g"}}]', '[{"ingredients":["3 tbsp peanut oil ((or vegetable), separated)","2 eggs (, lightly beaten)","3/4 cup bacon (, excess fat trimmed, chopped (or 1/2 cup Chinese Sausage) (Note 1))","2 garlic cloves (, minced)","3 tsp ginger (, minced or very finely chopped)","1/2 onion (, finely chopped (about 3/4 cup) (brown, white or yellow))","1 tbsp Chinese cooking wine or dry sherry (or sake, Japanese cooking wine) (Note 2)","1/2 tsp sugar","5 oz/150g small shrimp/prawns (, cooked and peeled (Note 3))","3 cups cooked long grain white rice (, refrigerated overnight (Note 4))","3 scallions (, thinly sliced)"]},{"ingredients":["1 tbsp Oyster Sauce","1 1/2 tbsp soy sauce (all purpose or light) (Note 3)","1/2 tsp sesame oil (roasted - i.e. dark colour)"],"purpose":"Sauce"}]', '[{"description":"Mix together Sauce ingredients, set aside.","images":[],"step":1},{"description":"Heat 1 tbsp oil in a wok (or heavy based skillet/fry pan) over medium heat. Add eggs and cook until scrambled, then remove onto plate.","images":[],"step":2},{"description":"Increase heat to high and add bacon. Cook until golden, then remove onto plate with egg - about 2 minutes.","images":[],"step":3},{"description":"Drain off excess bacon fat.","images":[],"step":4},{"description":"Add remaining 2 tbsp oil, garlic and ginger. (Note 5) Return wok to stove on high heat. Stir fry as it comes up to heat, don’t let it burn. When garlic starts to sizzle, add onion and stir fry for 2 minutes until golden.","duration":2,"images":[],"step":5},{"description":"Add Chinese wine and sugar and let it simmer rapidly, stirring, for 20 seconds, until mostly evaporated.","duration":0.3333333333333333,"images":[],"step":6},{"description":"Add prawns/shrimp and stir fry for 1 minute to heat through (if pre-cooked, cook longer to cook if raw).","duration":1,"images":[],"step":7},{"description":"Add rice, Sauce, eggs, bacon and all but 2 tbsp of shallots/scallions. Stir fry for 2 minutes until rice is hot - around 2 minutes.","duration":2,"images":[],"step":8},{"description":"Transfer to serving plate, sprinkle with remaining scallions and serve.","images":[],"step":9}]', '["egg","gluten","peanuts","sesame","shellfish","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","asian-takeout","chinese-recipes","dietary","dinner-tonight","fried-rice","gluten-free-recipes","main-dishes","prawns-shrimp","quick-and-easy","rice-recipes","rice-side-dishes","side-dishes","yum-cha-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_01f73ac4f487', 'en', 'US', 'Thai Mango Chicken Curry', 'The secrets to making a GREAT curry using store bought curry paste are: saute the paste with onion, garlic and chilli, simmer the sauce with kaffir lime leaves (KEY TIP!) and using fish sauce for seasoning. This curry is made using mango puree which is a miracle way to make a thick saucy curry but with 1/3 less calories than just using coconut milk (mangoes have 1/5th of the calories of coconut milk!). Read more in Note 2. If you don''t have mangoes, you can make this with just coconut milk which is just as tasty but has more calories - see Note 3.', 'https://www.recipetineats.com/tachyon/2016/02/Mango-Thai-Red-Curry-with-Chicken_2.jpg', 15, 20, 35, 3, '[{"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.5, "unit": "pack of 100g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.544, "unit": "kg"}}, {"id": "ing_thai_red_curry_paste", "quantity": {"value": 4.0, "unit": "bottle"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_chicken", "quantity": {"value": 0.544, "unit": "kg"}}, {"id": "ing_mango", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.544, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_chilli", "quantity": {"value": 0.5, "unit": "pack of 100g"}}]', '[{"ingredients":["1 tbsp oil (vegetable, canola, grape seed)","3 garlic cloves (, minced)","1/2 tsp ginger (, minced (not critical))","1/2 - 1 tsp red chilli (, minced (Optional. I used 1 tsp.))","1 small onion (, sliced (brown, white, yellow) or 3 eschallots)","1.2 lb / 600g chicken thigh fillets ((or breast), cut into bite size pieces)","4 - 5 tbsp Thai Red Curry Paste (Note 1)","1 can (400ml/13oz) coconut milk (full fat is better but low fat is ok too)","3/4 cup chicken broth","1 cup mango puree (, preferably fresh (1 large mango) (Note 2))","1 tbsp fish sauce","2 kaffir lime leaves"]},{"ingredients":["Steamed jasmine rice","Coriander/cilantro leaves","Lime wedges","Fresh red chili (, sliced)"],"purpose":"To Serve"}]', '[{"description":"Heat oil in a skillet over medium high heat.","images":[],"step":1},{"description":"Add garlic, ginger, chilli (if using) and onion and saute until the onion is starting to soften.","images":[],"step":2},{"description":"Add chicken and cook until white all over but still raw inside.","images":[],"step":3},{"description":"Add curry paste and saute for 2 minutes until fragrant.","duration":2,"images":[],"step":4},{"description":"Add coconut milk and chicken broth. Bring to simmer, stirring to dissolve the curry paste into the liquid. Then add the mango, fish sauce and kaffir lime leaves.","images":[],"step":5},{"title":"Turn heat down to medium and simmer for 12","description":"15 minutes, stirring occasionally, until the sauce is thickened. Adjust saltiness using fish sauce.","duration":13.5,"images":[],"step":6},{"description":"Serve over jasmine rice, garnished with coriander/cilantro, wedges of lime and slices of red chilli, if desired.","images":[],"step":7}]', '["fish"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","cuisines","curry-recipes","dietary","gluten-free-recipes","main-dishes","most-popular","thai-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8746b85a91e6', 'en', 'US', 'Easy Chinese Honey Sesame Chicken', 'Crispy oven baked chicken chicken with a sesame crust tossed in a sticky sauce. Really easy and absolutely irresistible! If you can''t find sesame paste or tahini, substitute with peanut butter. Seriously! (Refer to Note 2)', 'https://www.recipetineats.com/tachyon/2016/02/Chinese-Honey-Sesame-Chicken_3.jpg', 10, 20, 30, 3, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.225, "unit": "pack of 100g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.225, "unit": "pack of 100g"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_chicken", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_vinegar", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_honey", "quantity": {"value": 0.105, "unit": "jar of 500g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.225, "unit": "pack of 100g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.056, "unit": "pack of 400g"}}, {"id": "ing_oil", "quantity": {"value": 0.04, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 lb / 500g chicken thighs (, cut into 1.2cm/ 1/2\" slices (Note 1))","1/2 tsp salt","2 tsp sesame paste OR tahini (Note 2)","2 tsp soy sauce","1 1/2 tbsp sesame seeds (, toasted)","1/2 cup plain flour","Oil spray"],"purpose":"Chicken"},{"ingredients":["1 tbsp Chinese cooking wine (Shaoshing / Shaoxing wine) or sherry (or use chicken broth/stock)","3/4 cup chicken broth / stock","1 tsp rice wine vinegar or Chinese black vinegar (or ordinary white vinegar)","3 1/2 tbsp honey","1 1/2 tbsp soy sauce (, all purpose ordinary (Note 3))","2 tsp sesame oil"],"purpose":"Sauce"},{"ingredients":["1 1/2 tbsp cornstarch / cornflour mixed with 2 tbsp water"],"purpose":"Cornstarch"},{"ingredients":["2 tsp oil (vegetable, canola, peanut)","2 garlic cloves (, minced)"],"purpose":"To Cook"},{"ingredients":["1 scallion/shallot stem (, sliced)","1 1/2 tbsp sesame seeds (, toasted)"],"purpose":"Garnish"}]', '[{"description":"Preheat oven to 200C/430F with shelf placed on the highest level. Spray baking tray with oil.","images":[],"step":1},{"description":"Mix sesame paste and soy sauce in a bowl (to loosen it up, easier to coat chicken). Add chicken, salt and sesame seeds.","images":[],"step":2},{"description":"Place flour in a separate bowl and coat chicken in flour, shaking off excess. Place chicken on baking tray.","images":[],"step":3},{"description":"Bake for 12 minutes. Remove from oven.","duration":12,"images":[],"step":4},{"description":"Flick to broiler/grill as high as it will go with shelf about 15cm/6\" from the heat source.","images":[],"step":5},{"description":"Turn chicken. Broiler/grill for 5 minutes until golden and quite crispy (Note 4), then remove.","duration":5,"images":[],"step":6},{"description":"Meanwhile, mix together Sauce in one bowl and Cornstarch in another.","images":[],"step":7},{"description":"Heat oil in a wok or skillet (I used a skillet) over medium heat. Add garlic and cook for 30 seconds until fragrant but not browned.","duration":0.5,"images":[],"step":8},{"description":"Add Sauce and bring to bubble. Add Cornstarch and cook for 30 seconds until it thickens into a thick syrup.","duration":0.5,"images":[],"step":9},{"description":"Remove the Sauce immediately from the stove and pour over the chicken.","images":[],"step":10},{"description":"Toss chicken in Sauce then sprinkle over Sesame Seeds and Shallots/Scallions to serve. Serve with rice.","images":[],"step":11}]', '["gluten","peanuts","sesame","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-recipes","chinese-recipes","dinner-tonight","main-dishes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c20ebf4893bf', 'en', 'US', 'Coconut Shrimp / Prawns with Spicy THAI Mango Sauce', 'Crunchy coconut shrimp / prawns with a spicy Thai inspired Mango Sauce! These are shallow fried, not deep fried and the prawns cook VERY fast. These reheat really well! Refer to Note 6 for make ahead instructions. I made the sauce using Keitt mangoes because I think the slight tang is perfect for this recipe, but you can use any mangoes you want.', 'https://www.recipetineats.com/tachyon/2016/02/Coconut-Shrimp-Mango-Sauce_2.jpg', 20, 10, 30, 4, '[{"id": "ing_shrimp", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_bread", "quantity": {"value": 0.094, "unit": "loaf"}}, {"id": "ing_desiccated_coconut", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_mango", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_onion", "quantity": {"value": 30.0, "unit": "pack of 1kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_sriracha", "quantity": {"value": 0.037, "unit": "bottle of 400ml"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_coconut_milk", "quantity": {"value": 2.0, "unit": "can of 400ml"}}]', '[{"ingredients":["1 lb / 500 g whole prawns OR 12oz/350g peeled fresh prawns (Note 1)","1/4 tsp salt","Black pepper","1 egg","1/2 cup panko breadcrumbs","1/2 cup desiccated coconut (Note 2)","Oil (, for frying)"],"purpose":"Shrimp / Prawns"},{"ingredients":["1 cup (packed) fresh mango. roughly diced","2 tbsp cilantro/coriander (, leaves and stems, roughly chopped)","2 tbsp red onion or eschallots (, finely chopped)","1 tbsp fish sauce (or substitute with light or ordinary soy sauce)","1 tbsp sriracha (Note 3)","1 tsp red chilli (, finely chopped (adjust to taste))","2 - 3 tbsp coconut milk (adjust for desired sauce consistency)"],"purpose":"Mango Sauce"}]', '[{"title":"Mango Sauce","description":"Place ingredients in a small food processor (or blender or use a blender stick). Whizz until smooth. Adjust salt and spice to taste. Use coconut milk to adjust the consistency.","images":[],"step":1},{"description":"Peel and devein the shrimp / prawns. Sprinkle with salt and pepper.","images":[],"step":2},{"description":"Whisk egg in a small bowl. Mix panko and coconut in another bowl.","images":[],"step":3},{"description":"Dip a prawn in the egg mixture then coat with panko. Repeat with remaining prawns.","images":[],"step":4},{"description":"Heat oil in a skillet (Note 4) over medium high heat. Toss in a clotted lump of panko/egg to test for heat - if it sizzles right away and floats to the top, then the oil is hot enough.","images":[],"step":5},{"description":"Working in batches, carefully place prawns in the hot oil. Cook for just 45 seconds (Note 5) until golden brown - start counting when you slide the first prawn in and remove the prawns from the oil in the order that you put them in.","images":[],"step":6},{"description":"Remove onto a paper towel lined tray to drain.","images":[],"step":7},{"description":"Serve warm with Spicy Mango Dipping Sauce!","images":[],"step":8}]', '["egg","fish","gluten","soy"]', '[]', '{"mealType":["snack","dinner"],"cuisine":[],"categories":["asian-recipes","cuisines","deep-fried-recipes","finger-food","most-popular","prawns-shrimp","seafood-recipes","super-bowl-party-food","thai-recipes","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_010395e59caf', 'en', 'US', 'Spicy Beef Hokkien Noodles', 'This recipe is made using my Homemade Chinese Stir Fry Sauce but I''ve also provided directions in Note 1 for how to make just enough sauce for this recipe. Use whatever veggies, meat and noodles you want!', 'https://www.recipetineats.com/tachyon/2016/02/Spicy-Beef-Hokkien-Stir-Fry_4.jpg', 10, 10, 20, 4, '[{"id": "ing_beef_steak", "quantity": {"value": 0.369, "unit": "kg"}}, {"id": "ing_homemade_chinese_stir_fry_sauce", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_oil", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_chilli", "quantity": {"value": 0.3, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_snow_peas", "quantity": {"value": 7.0, "unit": "unit"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.851, "unit": "pack of 500g"}}, {"id": "ing_chilli", "quantity": {"value": 0.3, "unit": "pack of 100g"}}]', '[{"ingredients":["13oz / 400g beef rump steak (, trimmed, thinly sliced)","2 tbsp Homemade Chinese Stir-fry Sauce (Note 1)","1 1/2 tbsp peanut oil"],"purpose":"Beef"},{"ingredients":["1 1/2 tbsp peanut oil","2 garlic cloves (, crushed)","1 small onion (brown, white or yellow)","1 red capsicum/bell pepper (, sliced)","1/3 cup Homemade Chinese Stir-fry Sauce (Note 1)","3/4 cup water","2 tbsp chilli paste (, hot sauce, sriracha (to taste) OR finely chopped chilli)","3 scallions/shallots (, cut into 3cm lengths)","7oz / 200g snow peas (, trimmed)","15oz / 450g fresh hokkien noodles (, from the fridge section)"],"purpose":"Stir Fry"},{"ingredients":["Sliced red chilli (, sliced scallions/shallots and toasted sesame seeds)"],"purpose":"To Garnish (optional)"}]', '[{"title":"Marinate beef","description":"Mix beef and 2 tbsp Stir-fry Sauce in a glass or ceramic bowl. Set aside for 20 minutes to marinate.","duration":20,"images":[],"step":1},{"title":"Noodles","description":"Prefer the noodles per the packet directions. Drain in a colander and rinse under tap water to remove excess starch (makes noodles gluey). Shake off excess water.","images":[],"step":2},{"title":"Cook beef","description":"Heat 1 1/2 tbsp oil in a large wok over high heat. Cook beef for 1 1/2 minutes or until just cooked through. Transfer to a bowl.","images":[],"step":3},{"title":"Cook vegetables","description":"Heat 1 1/2 tbsp oil. Add garlic and onion, cook for 30 seconds. Add capsicum and cook for 1 minute. Transfer to the bowl with the beef.","duration":0.5,"images":[],"step":4},{"title":"Cook green onion and snow peas","description":"Add 1/3 cup Homemade Chinese Stir-fry Sauce, water and chili paste. Cook for 30 seconds or until sauce starts to thicken. Add green onion and snow peas, cook for 30 seconds.","duration":0.5,"images":[],"step":5},{"title":"Toss with noodles","description":"Return beef and capsicum mixture to the wok, add noodles and stir fry for 1 minute 30 seconds, tossing to coat everything in the sauce.","duration":1,"images":[],"step":6},{"description":"Serve immediately, garnished with chili, sliced scallions/shallots and sesame seeds if desired.","images":[],"step":7}]', '["peanuts","sesame"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","beef-recipes","chinese-recipes","dinner-tonight","main-dishes","noodles","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_749d68bbb7ff', 'en', 'US', 'Japanese GYOZA (Dumplings)', 'My mother''s traditional recipe for Gyoza, Japanese dumplings. You can get the gyoza wrappers at Woolworths and Coles! The best way to learn how to make these is to watch the RECIPE VIDEO below!', 'https://www.recipetineats.com/tachyon/2016/01/Gyoza-Japanese-Dumplings_2.jpg', 25, 20, 45, 40, '[{"id": "ing_cabbage", "quantity": {"value": 4.5, "unit": "head"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_pork", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 50.0, "unit": "pack of 3 heads"}}, {"id": "ing_garlic", "quantity": {"value": 50.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.037, "unit": "pack of 400g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_flour", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_round_wonton_wrappers_1_1_2_packets", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_vinegar", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1 1/2 cups green cabbage, very finely chopped","1 tsp salt, separated","1 lb / 500g ground pork (mince) (fattier the better)","1 cup garlic chives, finely chopped (Note 1)","1 garlic cloves, crushed","1 tsp ginger, grated","1 tsp sesame oil","1 tbsp cornstarch / corn flour","2 tsp soy sauce"],"purpose":"Filling"},{"ingredients":["1 tsp cornflour (cornstarch) - for tray","40 - 45 round wonton (gyoza) wrappers (Gow Gee wrappers) - 1 1/2 packets (Note 2)","3 tbsp vegetable oil (or other cooking oil)"],"purpose":"Gyoza"},{"ingredients":["Soy sauce","Rice wine vinegar","Chili oil (Rayu is Japanese chili oil)"],"purpose":"Dipping Sauce"}]', '[{"description":"Combine cabbage and 1/2 tsp salt in a small bowl, then set aside for 20 minutes to allow the cabbage to wilt slightly.","duration":20,"images":[],"step":1},{"description":"Place remaining Filling ingredients (including remaining 1/2 tsp salt) in a large bowl. Squeeze out any excess water from the cabbage and add to the bowl.","images":[],"step":2},{"description":"Use your hands to mix the Filling.","images":[],"step":3},{"description":"Sprinkle a baking tray with 1 tsp of cornstarch / cornflour.","images":[],"step":4},{"description":"Place 1 gyoza wrapper on your palm (left hand for right-handed people). Dip your finger in water and run it around the edge of half the gyoza wrapper (to seal).","images":[],"step":5},{"description":"Place 1 slightly heaped tbsp of Filling on the wrapper. Fold wrapper over and use your right hand assisted by your left hand thumb to create 4 pleats. Press to seal and place on the tray. Repeat with remaining wrappers. (See video for demo)","images":[],"step":6},{"description":"To Cook","images":[],"step":7},{"description":"Heat 1 tbsp oil in a large skillet (that has a lid) over medium high heat.","images":[],"step":8},{"description":"Place about 12 gyoza in rows, slightly overlapping each other. Cook until the underside is light golden, then pour 1/3 cup of water around the gyoza and place the lid on.","images":[],"step":9},{"description":"Cook until the water has completely evaporated (so the golden underside is not wet and soggy) and the wrapper is slightly translucent on top - about 3 to 4 minutes. (See video)","images":[],"step":10},{"description":"Use an egg flip to transfer onto a plate upside down i.e. golden side up.","images":[],"step":11},{"description":"Serve with Dipping Sauce.","images":[],"step":12},{"description":"Serve each ingredient separately so people can mix according to their taste. I use about equal portions of soy sauce and vinegar with a generous splash of chili oil.","images":[],"step":13}]', '["gluten","sesame","soy"]', '["low_calorie"]', '{"mealType":["snack"],"cuisine":["Japanese"],"categories":["asian-recipes","dumplings","modern-asian","most-popular","noodles","pork-recipes","side-dishes","yum-cha-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_485d509b3234', 'en', 'US', 'Satay Chicken Noodle Salad', 'Chicken satay tossed in a noodle salad loaded with plenty of veggies with a creamy peanut satay dressing! Serve this warm or at room temperature.', 'https://www.recipetineats.com/tachyon/2016/01/Satay-Chicken-Noodle-Salad_1.jpg', 15, 5, 20, 3, '[{"id": "ing_peanut_butter", "quantity": {"value": 0.003, "unit": "jar of 375g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_sriracha", "quantity": {"value": 0.056, "unit": "bottle of 400ml"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.225, "unit": "can of 400ml"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.567, "unit": "pack of 500g"}}, {"id": "ing_red_cabbage", "quantity": {"value": 6.0, "unit": "head"}}, {"id": "ing_cabbage", "quantity": {"value": 6.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 10.0, "unit": "pack of 100g"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.34, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.15, "unit": "jar of 50g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_peanuts", "quantity": {"value": 0.113, "unit": "jar"}}]', '[{"ingredients":["¼ cup peanut butter (preferably smooth)","1 garlic clove (, minced)","1 tbsp sesame oil","2 tbsp soy sauce","2 tsp brown sugar","1 1/2 tbsp sriracha (, or 2 tsp chili paste/sauce + 2 tsp vinegar)","2 tbsp lime juice","6 tbsp coconut milk (I used low fat)","2 tbsp water","1/4 tsp salt"],"purpose":"Dressing"},{"ingredients":["10 oz/300g fresh egg noodles (Note 1)","2 cups red cabbage (, shredded)","2 cups green cabbage (, shredded)","2 carrots (, finely chopped)","1/4 tsp salt","2 scallion/shallot stems (, finely sliced on the diagonal)","1 large red chilli (not very spicy), deseeded and finely sliced (Note 2)"],"purpose":"Salad"},{"ingredients":["12 oz / 350g chicken breast (, cut in half vertically and thinly sliced)","Salt and pepper","1 1/2 tsp curry powder","2 tsp sweet soy sauce/ kecap manis (Note 3)","1 tbsp cooking oil"],"purpose":"Satay Chicken"},{"ingredients":["3 tbsp peanuts (, roughly chopped)"],"purpose":"Garnish"}]', '[{"description":"Mix dressing ingredients in a bowl until smooth.","images":[],"step":1},{"description":"Prepare noodles according to packet instructions.","images":[],"step":2},{"description":"Place both cabbages and carrots in a bowl, add 1/4 tsp salt, toss to combine and set aside for 5-10 minutes to wilt lightly.","duration":7.5,"images":[],"step":3},{"description":"Place the Satay Chicken ingredients EXCEPT the oil in a bowl and toss to coat.","images":[],"step":4},{"description":"Heat oil in a non stick fry pan over high heat. Add the chicken and cook for 3 minutes until golden, then transfer to a plate.","duration":3,"images":[],"step":5},{"description":"Toss noodles and remaining salad ingredients with chicken and Dressing, then serve. Serve at room temperature or warm.","images":[],"step":6}]', '["egg","gluten","peanuts","sesame","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner","lunch"],"cuisine":[],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","most-popular","noodles"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d078b09c4553', 'en', 'US', 'Honey Sriracha Chicken Skewers', 'Spice Level: MediumJust 5 ingredients is all you need to make a marinade that doubles as a fantastic glaze for these skewers! Just 20 minutes of marinating time required. A great balance of sweet, spicy and savoury.', 'https://www.recipetineats.com/tachyon/2016/01/Honey-Sriracha-Glazed-Chicken-Skewers_1.jpg', 15, 10, 25, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.68, "unit": "kg"}}, {"id": "ing_honey", "quantity": {"value": 0.167, "unit": "jar of 500g"}}, {"id": "ing_mustard", "quantity": {"value": 0.15, "unit": "jar of 200g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.24, "unit": "bottle of 250ml"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_hot_sauce", "quantity": {"value": 2.0, "unit": "bottle of 150ml"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 22.5, "unit": "bottle"}}]', '[{"ingredients":["1.5 lb / 750g lb / 750g chicken thigh fillets (Note 1)"]},{"ingredients":["1/3 cup honey","2 tbsp Dijon mustard (Note 2)","4 tbsp soy sauce","2 garlic cloves (, crushed)","2 - 3 tbsp sriracha OR any other hot sauce ((e.g. Frank''s), adjust amount to your taste)","1/4 tsp salt"],"purpose":"Marinade Glaze"},{"ingredients":["1 1/2 tbsp oil (I used vegetable)"],"purpose":"To cook"}]', '[{"description":"Cut the chicken into 2cm / 4/5\" cubes.","images":[],"step":1},{"description":"Mix Marinade ingredients together in a bowl until smooth.","images":[],"step":2},{"description":"Transfer 4 tablespoons of the Marinade into a small bowl (\"Reserved Marinade\", to use for basting).","images":[],"step":3},{"description":"Add chicken into the bowl with the remaining Marinade. Mix to coat and set aside for 20 minutes to marinade (up to overnight). (Note 3)","duration":20,"images":[],"step":4},{"description":"Thread chicken onto skewers, discard marinade in the bowl. I used 14 small ones about 18cm/7\" long, 4 pieces of chicken on each.","images":[],"step":5},{"description":"Heat oil on a BBQ or skillet over medium heat. Place skewers on the BBQ and cook the first side for 2 1/2 minutes, then turn the skewers.","images":[],"step":6},{"description":"Baste the COOKED side that is now facing up generously with the reserved Reserved Marinade. After 2 1/2 minutes, turn the skewers and quickly baste the other side generously with the Reserved Marinade. Turn immediately. Cook for just a few seconds, then transfer to a plate. (Note 4)","images":[],"step":7},{"description":"Baste the skewers on the plate one more time with the Reserved Marinade, then serve.","images":[],"step":8},{"description":"I served mine with Cilantro/Coriander Lime Rice (Note 5)","images":[],"step":9}]', '["gluten","mustard","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian-syle"],"categories":["asian-recipes","australia-day","chicken-breast-recipes","chicken-recipes","dinner-tonight","grilling-ideas-and-recipes","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_017cac58dae4', 'en', 'US', 'Tuna Tartare with Lychees', 'Here''s a cheffy dish that is really elegant but super easy to make! This is the sort of dish you get at posh restaurants that they charge a fortune for. The ingredients for this cost me around $17 (in Sydney, Australia). This serves 4 to 6 as a shared or individual starter.', 'https://www.recipetineats.com/tachyon/2015/12/Lychee-Tuna-Tartare_6.jpg', 15, 0, 15, 4, '[{"id": "ing_sashimi_grade_tuna", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_ychees", "quantity": {"value": 7.0, "unit": "unit"}}, {"id": "ing_chilli", "quantity": {"value": 0.225, "unit": "pack of 100g"}}, {"id": "ing_onion", "quantity": {"value": 37.5, "unit": "pack of 1kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_lime", "quantity": {"value": 0.09, "unit": "net of 500g"}}, {"id": "ing_avocado", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_coriander", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 0.09, "unit": "net of 500g"}}]', '[{"ingredients":["200 g/7oz sashimi grade tuna (or any other sashimi grade fish) (Note 1)","7 lychees (, fresh (Note 2))","1 1/2 tbsp large red chili (not a spicy one), very finely diced (Note 3)","1/4 cup red onion (, very finely diced)","1 1/2 tbsp coriander/cilantro leaves (, finely chopped)","3 tbsp extra virgin olive oil (, plus extra)","3 tbsp lime juice (, plus extra)","1/2 small avocado (, diced (~ 1/2 cup))","Salt and pepper"]},{"ingredients":["Sliced sourdough baguette (, toasted)","Extra coriander/cilantro leaves","Lime wedges"],"purpose":"To serve"}]', '[{"title":"Freeze tuna for 20 minutes","description":"just to firm. Slice into 3mm / 1/8\" strips, then cut those strips into 3mm / 1/8\" cubes. Place in a bowl.","duration":20,"images":[],"step":1},{"description":"Peel the lychees, then finely dice the flesh and add into the bowl (Note 4). Scrape the juices that pool on the cutting board into the bowl too - don''t waste a drop!","images":[],"step":2},{"description":"Add the chili, onion and coriander, olive oil and lime juice into the bowl. Season with a generous pinch of salt and a good grind of pepper.","images":[],"step":3},{"description":"Use your fingers to toss together gently. Taste and adjust olive oil, lime and salt to taste.","images":[],"step":4},{"description":"Pile on a platter, top with avocado and garnish with coriander/cilantro leaves. Drizzle with more olive oil. Serve immediately (Note 5), with toasted bread and extra lime wedges.","images":[],"step":5}]', '["fish"]', '["gluten_free"]', '{"mealType":["snack"],"cuisine":["Modern Asian","South American"],"categories":["asian-recipes","australia-day","dietary","fish-recipes","gluten-free-recipes","modern-asian","quick-and-easy","seafood-recipes","side-dishes","south-american-recipes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0b9d90963e47', 'en', 'US', 'Japanese Miso Salmon Side (BBQ or bake)', 'Recipe video below. My mother''s recipe for Miso Marinated Salmon. The flavour infused in the salmon is incredible. An authentic Japanese recipe, make this on the barbecue or even in the oven! You can get all the ingredients for this at Woolworths supermarket in Australia, including the side of salmon.', 'https://www.recipetineats.com/tachyon/2015/12/Miso-Marinated-Salmon-Side_2a.jpg', 10, 5, 15, 5, '[{"id": "ing_salmon_fillets", "quantity": {"value": 1.6, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_miso_paste", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_sake", "quantity": {"value": 25.0, "unit": "bottle"}}, {"id": "ing_mirin", "quantity": {"value": 0.1, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1.6 - 2.4 lb / 0.8 - 1.2kg side of salmon (, skin on (Note 1))","Oil (, for barbecue)"]},{"ingredients":["5 tbsp miso paste (Note 2)","2 tbsp white sugar","1 2/3 tbsp sake (Japanese rice wine)","1 2/3 tbsp mirin (Japanese sweet rice wine)"],"purpose":"Marinade"},{"ingredients":["Sesame seeds","Scallions/shallots (, finely sliced)"],"purpose":"Garnishes"}]', '[{"description":"Mix together the marinade ingredients in a small bowl until smooth.","images":[],"step":1},{"description":"Place the salmon skin side up on a work surface and slather with just under half the marinade.","images":[],"step":2},{"description":"Turn the salmon so it is skin side down onto a large piece of cling wrap. Slather the remaining marinade on the flesh side.","images":[],"step":3},{"description":"Wrap the salmon in cling wrap. Marinade for 24 to 48 hours.","images":[],"step":4},{"description":"Scrape the marinade off (do not rinse with water) and leave the salmon to come to room temperature <- KEY for perfectly cooked salmon.","images":[],"step":5},{"description":"Preheat barbecue plate side on MEDIUM LOW. Leave it to heat up for a good 10 to 15 minutes - another tip for cooking salmon perfectly.","images":[],"step":6},{"description":"Add oil just before cooking. Place the salmon on the BBQ skin side down. Cook for 3 minutes, then use two spatulas to turn it. Cook the flesh side for 2 - 3 minutes or until caramelised, then flip it again so the skin side is down then transfer to a tray.","duration":3,"images":[],"step":7},{"description":"Cover loosely with foil to rest for 5 minutes before serving. It will continue cooking while resting.","duration":5,"images":[],"step":8},{"description":"Garnish with sesame seeds and finely sliced shallots.","images":[],"step":9}]', '["fish","sesame"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Japanese","Modern Asian"],"categories":["asian-recipes","australia-day","dietary","easter-mains-fish-seafood","fish-recipes","gluten-free-recipes","grilling-ideas-and-recipes","modern-asian","quick-and-easy","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a0a97af3fc6c', 'en', 'US', 'Asian Grilled Shrimp / Prawns', 'Whether you make these on your BBQ or in a fry pan, this is a simple but magical combination of ingredients that tastes like something you''d get at a fancy restaurant! Actually, this is a copy of a great dish I had at a restaurant in Sydney called Esther.The nutty flavour of the browned butter pairs perfectly with a drizzle of sweet soy sauce and the freshness of lime. Add a sprinkle of chili for heat! Keep some bread on hand to mop up the glorious juices.', 'https://www.recipetineats.com/tachyon/2015/12/Asian-Barbecue-Prawns_31.jpg', 10, 5, 15, 2, '[{"id": "ing_shrimp", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 0.333, "unit": "block of 250g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.75, "unit": "bottle of 250ml"}}, {"id": "ing_ime", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 lb / 500 g shrimp / prawns (fresh), peeled and deveined (Note 1)","2 garlic cloves (, crushed)","2 tbsp vegetable oil","1/3 cup salted butter (or 1/3 cup unsalted butter + big pinch of salt)","3/4 to 1 tsp tsp sweet soy sauce / kecap manis (Note 2)","1 lime (, large)"]},{"ingredients":["1 red birds eye chilli (, deseeded and finely sliced or chopped)","Cilantro / coriander leaves"],"purpose":"Garnishes (all optional)"}]', '[{"description":"Combine shrimp / prawns, garlic and oil in a small bowl, use your fingers to coat then set aside for 15 minutes.","duration":15,"images":[],"step":1},{"description":"Browned Butter","images":[],"step":2},{"description":"Meanwhile, melt butter in a small silver fry pan or saucepan over medium heat. (Note 3)","images":[],"step":3},{"description":"Heat until it starts to foam, then swirl the pan occasionally to distribute heat evenly.","images":[],"step":4},{"description":"Cook until the butter turns golden, smells nutty and there are brown specks at the bottom (you might need a teaspoon to push the foam aside).","images":[],"step":5},{"description":"Remove from heat immediately. Pour into a jug, leaving behind most of the bitter brown specks (I strained it - because I was making an effort!).","images":[],"step":6},{"description":"Set aside until required.","images":[],"step":7},{"description":"Prawns / Shrimp","images":[],"step":8},{"description":"Heat the BBQ or fry pan over high heat (no oil).","images":[],"step":9},{"description":"Add prawns / shrimp and cook until each side is lightly golden brown, but be sure not to overcook! (Note 4)","images":[],"step":10},{"description":"Serve","images":[],"step":11},{"description":"Place prawns in a bowl. Grate over the zest of a lime, then cut the lime in half and squeeze over about 1 tbsp of lime juice. Drizzle with 1 tbsp of browned butter, toss gently.","images":[],"step":12},{"description":"Transfer to a plate. Drizzle with 2 tbsp of browned butter then lastly, drizzle over kecap manis, using as thin a stream as you can.","images":[],"step":13},{"description":"Serve immediately, garnished with chilli and cilantro/coriander, if using.","images":[],"step":14}]', '["gluten","milk","shellfish","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","australia-day","dinner-tonight","grilling-ideas-and-recipes","main-dishes","modern-asian","most-popular","prawns-shrimp","quick-and-easy","seafood-recipes","side-dishes","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_198a454d0c8a', 'en', 'US', 'Pot Roasted Coconut Chicken', 'Chicken in a fragrant coconut broth with an intensity of flavour that belies the few ingredients this recipe uses! The broth is so good that you will want to drink it straight. And the chicken stays beautifully moist by roasting it in the broth/stock. This is a clean-eating recipe that you would never think of as "clean"!', 'https://www.recipetineats.com/tachyon/2015/11/Fragrant-Coconut-Pot-Roasted-Chicken_1_600px.jpg', 15, 75, 90, 5, '[{"id": "ing_chilli", "quantity": {"value": 20.0, "unit": "pack of 100g"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_chicken", "quantity": {"value": 1.361, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 1.361, "unit": "kg"}}, {"id": "ing_lemongrass", "quantity": {"value": 20.0, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.992, "unit": "can of 400ml"}}, {"id": "ing_potato", "quantity": {"value": 0.8, "unit": "bag of 2kg"}}, {"id": "ing_ime", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.015, "unit": "kg"}}]', '[{"ingredients":["2 long red chilies (Note 1)","1 tsp freshly grated ginger","2 garlic cloves (, crushed)","1 tbsp coconut oil (or substitute with olive oil)","1/2 tsp salt","Black pepper","1 cup finely chopped cilantro/coriander leaves","3 lb /1.6kg whole chicken (, preferably organic/free range)","2 cups / 500 ml chicken broth/stock (preferably reduced salt)","1 lemongrass (, white part only, bruised (Note 2))","2 kaffir lime leaves (Note 3)","14 oz /400ml light coconut milk (1 can)","0.8 lb / 400g baby potatoes (, scrubbed clean)","1 lime","2 tsp coconut sugar (or substitute with brown sugar)","1 tbsp fish sauce"]}]', '[{"description":"Preheat oven to 390F/200C.","images":[],"step":1},{"description":"Finely mince ONE red chili (~1 tbsp). Combine chili, ginger, garlic, oil, 1/2 cup cilantro/coriander, salt and pepper in a small bowl and set aside.","images":[],"step":2},{"description":"Rinse and pat the chicken dry (inside and out) with paper towels. Starting from the neck end of the chicken, use a teaspoon upside down to loosen the skin from the meat across the surface of the chicken (i.e. not the legs or wings). Just go as far as you can.","images":[],"step":3},{"description":"Spoon the cilantro/mixture between the meat and the skin near neck. Use the spoon to spread it a bit, then to finish it off, use your finger/hands ON the skin to spread the mixture as far and evenly as you can. Doesn''t need to be perfect! :)","images":[],"step":4},{"description":"Place the chicken stock/broth, kaffir lime leaves, lemongrass and the whole red chili into a dutch oven or baking tray. (Note 4)","images":[],"step":5},{"description":"Place the chicken in the broth, cover with a lid and roast for 45 minutes. Remove the lid, add the coconut milk and potatoes then roast for a further 30 minutes, or until juices run clear when pierced.","duration":45,"images":[],"step":6},{"description":"Remove the chicken from the broth and cover loosely with foil to rest for 5 minutes.","duration":5,"images":[],"step":7},{"title":"Skim excess fat off the surface of the broth","description":"I usually get about 5 tbsp of fat off.","images":[],"step":8},{"description":"Add the juice from the lime, sugar and fish sauce. Stir until the sugar is dissolved. Add remaining cilantro/coriander.","images":[],"step":9},{"description":"Serve the chicken with the broth in a pouring jug, or cut up the chicken and serve it in the broth.","images":[],"step":10}]', '["fish"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Modern Asian"],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","dietary","easter-mains","easter-recipes","gluten-free-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ca14a5a12d86', 'en', 'US', 'Asian Glazed Salmon', 'Recipe video above. This salmon is marinated for just 30 minutes in a simple but super tasty Asian marinade and then broiled/grilled to produce a gorgeous caramelisation. Just a really fantastic, quick and delicious way to cook salmon using pantry staples.', 'https://www.recipetineats.com/tachyon/2015/10/Asian-Glazed-Salmon-take-3_4-2-1.jpg', 5, 10, 15, 2, '[{"id": "ing_fish_fillets", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_sweet_chili_sauce", "quantity": {"value": 0.08, "unit": "bottle of 375ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_steamed_asian_greens", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_rice", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["2 x 180g / 6oz salmon fillets (, skinless (Note 1))","Oil spray (olive oil, canola oil etc)"]},{"ingredients":["1 tsp fresh ginger (, finely grated)","1 garlic clove (, crushed)","1 tbsp soy sauce","2 tbsp oyster sauce","2 tbsp sweet chili sauce (Note 2)"],"purpose":"Marinade"},{"ingredients":["Sesame seeds","Scallions/shallots (, finely sliced)","Steamed Asian Greens","Rice"],"purpose":"To Serve (optional)"}]', '[{"title":"Marinade salmon","description":"Combine the Marinade ingredients in a shallow bowl. Add salmon and turn to coat. Cover and marinate for 30 minutes or up to overnight.","duration":30,"images":[],"step":1},{"description":"Preheat grill/broiler on high. Place the rack 25 cm / 10\" from the heat source.","images":[],"step":2},{"title":"Glaze","description":"Place salmon on baking tray (no oil required, no paper - it will burn). Dab glaze onto the salmon, whatever will stick. Don''t pour excess glaze on, it will pool around the salmon and burn.","images":[],"step":3},{"title":"Cook","description":"Grill/broil for 7 minutes. Remove, spray the surface generously with oil. Grill/broil for another 1 to 3 minutes until the surface is caramelised at the salmon is cooked - the flesh should flake. (Internal temperature 50°C/122°F for medium rare - see Note 3) . Be careful not to overcook the salmon!","duration":7,"images":[],"step":4},{"description":"Serve salmon sprinkled with sesame seeds, scallions/shallots with rice and steamed Asian greens on the side.","images":[],"step":5}]', '["fish","gluten","sesame","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","dinner-tonight","fish-recipes","main-dishes","modern-asian","most-popular","quick-and-easy","salmon-recipes","seafood-recipes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7cc28750e6ed', 'en', 'US', 'Baked Sweet and Sour Chicken', 'My oven baked version of Sweet & Sour chicken which is not like most recipes you will find on the internet. My sauce uses less sugar so it''s not overly sweet, the sauce ingredients has a few extra things in it so it really does taste more like restaurant Sweet & Sour sauce, and the chicken is only baked for 20 minutes so it does not dry out (but still lovely and crispy!). The ingredients list for this recipe is longer than most on my site - but it is well worth it!', 'https://www.recipetineats.com/tachyon/2015/10/Sweet-Sour-Chicken_600px1-Featured.jpg', 15, 25, 40, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.375, "unit": "pack of 400g"}}, {"id": "ing_oil", "quantity": {"value": 3.0, "unit": "bottle"}}, {"id": "ing_oil", "quantity": {"value": 3.0, "unit": "bottle"}}, {"id": "ing_oil", "quantity": {"value": 3.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_pineapple", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.167, "unit": "bottle of 500ml"}}, {"id": "ing_pineapple", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_ketchup", "quantity": {"value": 0.09, "unit": "bottle of 500g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_water", "quantity": {"value": 0.015, "unit": "L"}}]', '[{"ingredients":["1 lb / 500 g chicken breast (, cut into bite size cubes)","1/2 tsp salt","1 large egg or 2 small eggs (, lightly beaten (enough to coat chicken))","1 cup cornstarch / cornflour (, placed in a large ziplock bag)","3 to 5 tbsp oil (vegetable, canola)","Oil spray"],"purpose":"Chicken"},{"ingredients":["1/2 tbsp oil","1 garlic clove","1 small onion (, cut into large dice)","1/2 red bell pepper (, cut into bite size pieces)","1/2 green bell pepper (, cut into bite size pieces)","1 can ((8oz/250g) canned pineapple pieces in natural juice. Separate pineapple from juice.)"],"purpose":"Stir Fry"},{"ingredients":["1/2 cup sugar (white or brown - I use either)","1/3 cup apple cider vinegar","2 - 3 tbsp pineapple juice (from the canned pineapple pieces)","3 tbsp ketchup (Australia: tomato sauce)","1 tsp Worcestershire sauce (Note 1)","1 tsp soy sauce (Note 1)","1 tsp Oyster Sauce (Note 1)","1/4 tsp salt"],"purpose":"Sauce"},{"ingredients":["1 tbsp cornflour / corn starch + 4 tbsp water (, mixed together)"],"purpose":"Thickener"}]', '[{"description":"Preheat oven to 200C/390F.","images":[],"step":1},{"description":"Place chicken in a bowl, sprinkle with salt then add the egg. Mix to coat all chicken with egg, then drain out excess egg. (Note 2)","images":[],"step":2},{"description":"Working a handful at a time, shake excess egg mixture off chicken then place chicken in ziplock bag. When all the chicken is in the bag, seal (trap as much air in it as you can to make a \"balloon\") and shake well to coat chicken in cornflour. Discard excess cornflour.","images":[],"step":3},{"description":"Heat oil in a large skillet on high. Add chicken (in 2 batches if your skillet is not big enough) and cook briefly for 2 minutes, turning, just to make the outside light golden and a bit crispy. The chicken should be raw inside.","duration":2,"images":[],"step":4},{"description":"Transfer to baking tray, spray with oil and bake for 15 to 20 minutes until it becomes a little more golden brown and is crispy.","duration":17.5,"images":[],"step":5},{"description":"Meanwhile, discard oil in the skillet and wipe briefly with paper towels. Reduce heat to medium high and heat 1/2 tbsp oil. Add garlic and sauté for 20 seconds, then add onion and cook for 2 minutes.","duration":0.3333333333333333,"images":[],"step":6},{"description":"Add bell peppers and cook for 1 minute.","duration":1,"images":[],"step":7},{"description":"Add Sauce ingredients. Stir until sugar has dissolved and the sauce begins to bubble.","images":[],"step":8},{"description":"Add Thickener. Bring to simmer, stirring constantly. Then cook until it thickens to a syrup consistency - about 3 minutes.","images":[],"step":9},{"description":"Stir through pineapple pieces (just to warm) and remove from stove.","images":[],"step":10},{"description":"When the chicken is done, add it into the skillet and toss to coat in the sauce.","images":[],"step":11},{"title":"Serve immediately with rice","description":"or for a low carb, low cal option, try Cauliflower Rice! Garnish with scallions if desired.","images":[],"step":12}]', '["egg","gluten","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["American Chinese"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-recipes","chinese-recipes","dinner-tonight","main-dishes","most-popular","quick-and-easy","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_971538e77c0f', 'en', 'US', 'Crispy Sticky Mongolian Beef', 'Recipe VIDEO above. This Mongolian Beef is super crispy and coated in a sticky salty / sweet sauce - but not TOO sweet! It''s absolutely divine and everyone I''ve made this for has raved about it. Don''t be daunted by the ingredients list - there are a number of repeat ingredients! I just like to separate them into groups for ease of following the recipe.', 'https://www.recipetineats.com/tachyon/2015/08/Mongolian-Beef_600px_overhead-1-Featured.jpg', 15, 10, 25, 2, '[{"id": "ing_beef_steak", "quantity": {"value": 0.227, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.013, "unit": "pack of 400g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.013, "unit": "pack of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.045, "unit": "bottle of 500ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}]', '[{"ingredients":["8 oz / 250g beef steak (rump, scotch or flank), sliced into 1/5\" / 3mm slices (Note 1)","1 tsp soy sauce","1 tsp cornstarch/cornflour","1 tsp vegetable oil"],"purpose":"Beef and Marinade"},{"ingredients":["2 tsp cornflour / cornstarch","1/4 cup water","2 tbsp soy sauce (light or all purpose, NOT dark)","1/4 cup chicken broth","1 1/2 tbsp Chinese cooking wine or dry sherry, or more chicken broth (Note 2)","3 tbsp / 1/4 cup brown sugar, lightly packed"],"purpose":"Sauce"},{"ingredients":["1/4 - 1 1/2 cups vegetable oil (Note 1)","1/4 cup cornstarch/cornflour"],"purpose":"Crispy Beef"},{"ingredients":["1/2 tsp ginger, finely minced","2 garlic cloves, crushed","2 scallions/shallots, cut into 1 1/2\" / 4cm pieces on the diagonal"],"purpose":"Stir Fry"}]', '[{"description":"Beef and Marinade","images":[],"step":1},{"description":"Combine the Beef and Marinade ingredients in a bowl and marinate for 10 minutes (though you could even leave it overnight).","duration":10,"images":[],"step":2},{"description":"Mix the cornstarch with a splash of the water. Then add the remaining Sauce ingredients, including remaining water.","images":[],"step":3},{"description":"Crispy Beef and Stir Fry","images":[],"step":4},{"description":"Add 1/4 cup cornstarch and use your fingers to lightly coat the beef.","images":[],"step":5},{"description":"Heat 1/4 cup oil in a wok (Note 2) over medium high heat. Add 1/2 the beef and cook the first side for around 45 seconds or until golden and crisp. Then flip (I use an egg flip) and cook the other side for 30 - 45 seconds until golden and crisp. Remove onto a paper towel lined plate. Repeat with remaining beef.","duration":0.625,"images":[],"step":6},{"description":"Discard the oil, leaving behind about 1 tablespoon in the wok.","images":[],"step":7},{"description":"Add the ginger and garlic and sauté for about 15 seconds. Don''t let it burn!","images":[],"step":8},{"description":"Add the Sauce into the wok. Bring it to a simmer and let it cook for about 1 1/2 minutes or until it thickens into a glossy sticky sauce.","images":[],"step":9},{"description":"Add the beef and scallions, toss to coat and cook for a further 30 seconds.","images":[],"step":10},{"title":"Serve immediately with rice","description":"or for a low carb, low cal option, try Cauliflower Rice!","images":[],"step":11}]', '["gluten","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["American Chinese"],"categories":["asian-recipes","asian-takeout","beef-recipes","chinese-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","modern-asian","most-popular","quick-and-easy","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e5df44e2a467', 'en', 'US', 'Korean Bulgogi Beef Stir Fry', 'This is a very classic, traditional dish from Korea. It is becoming increasingly popular in Western countries as more and more people are discovering not only how delicious it is, but how easy it is to make with ingredients you can get from the supermarket! The beef has a lovely balance of sweet and salty. The use of grated apple and onion is classic Korean and it makes all the difference! Bulgogi is traditionally cooked over charcoal or a tabletop BBQ, however, I''ve made this in stir fry form which is also a way it''s used.This recipe makes enough for 2 to 3 people, served with rice as a main.', 'https://www.recipetineats.com/tachyon/2015/08/Korean-Beef-Bowl_Featured-Image.jpg', 15, 5, 20, 2, '[{"id": "ing_beef", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_onion", "quantity": {"value": 500.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.075, "unit": "pack of 100g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_mirin", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.075, "unit": "pack of 100g"}}, {"id": "ing_onion", "quantity": {"value": 500.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_apples", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["14 oz / 400 g thinly sliced beef (, any good quality tender cut suitable for grilling (Note 1))","1 scallion/shallot stem (, green and white part separated, both finely sliced (Note 2))","1/2 large onion ((brown, yellow or white), peeled and thinly sliced)","1/2 medium carrot (, peeled, cut vertically then cut into thin slices on the diagonal)","1 tbsp cooking oil (I use peanut or vegetable oil)","1/2 tbsp sesame seeds"],"purpose":"Beef"},{"ingredients":["3 tbsp ordinary soy sauce (I use Kikkoman)","1 1/2 tbsp brown sugar","1 tbsp mirin (Note 3)","1/2 tbsp sesame oil","2 tbsp grated onion (brown, white or yellow)","2 cloves garlic (, minced)","3 tbsp grated red apple ((not green - they are too tart) OR nashi pears)","1/2 tsp minced ginger","Black pepper"],"purpose":"Marinade"}]', '[{"description":"Blot the beef dry using a paper towel then place into a bowl.","images":[],"step":1},{"description":"Mix together the Marinade ingredients in a small bowl, then add the beef. Stir gently to coat the beef, cover with cling wrap and set aside to marinate for at least 1 hour, preferably overnight. Because the meat is thin, you still get good flavour even with 1 hour of marinating.","images":[],"step":2},{"description":"Heat the oil in a wok or large fry pan over high heat.","images":[],"step":3},{"description":"Add the onion and white part of the scallion/shallots. Cook for 1 minute.","duration":1,"images":[],"step":4},{"description":"Then add the beef, including the Marinade, and carrots. Cook for around 3 to 5 minutes, stirring constantly, until the beef is just cooked.","images":[],"step":5},{"description":"Remove from heat, then toss through the sesame seeds.","images":[],"step":6},{"title":"Serve immediately with rice","description":"or for a low carb, low cal option, try Cauliflower Rice! Sprinkle with extra sesame seeds and the reserved green part of the scallions.","images":[],"step":7}]', '["gluten","peanuts","sesame","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Korean"],"categories":["asian-recipes","beef-recipes","dietary","dinner-tonight","gluten-free-recipes","korean-recipes","main-dishes","most-popular","quick-and-easy","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3f8c05e7c675', 'en', 'US', 'Vietnamese Garlic Shrimp (Prawn) Noodle Salad', 'This is a great, fresh salad with a fantastic Vietnamese dressing based on a recipe by Bill Granger, a famous Australia chef. I really like this dressing because it''s got plenty of flavour but the fish sauce is mild in it. I love Nuoc Cham, which is the classic Vietnamese dipping sauce that doubles as dressings. But some people find that the fish sauce flavour is too strong. Plus, it''s an art form to get the flavour balance right!', 'https://www.recipetineats.com/tachyon/2015/07/Viet-Noodle-Salad_680px_1.jpg', 15, 5, 20, 2, '[{"id": "ing_shrimp", "quantity": {"value": 12.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_ime_juice", "quantity": {"value": 0.25, "unit": "unit"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.142, "unit": "pack of 500g"}}, {"id": "ing_lettuce", "quantity": {"value": 9.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 150.0, "unit": "pack of 1kg"}}, {"id": "ing_cucumber", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_beansprouts", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_mint", "quantity": {"value": 0.15, "unit": "bunch"}}]', '[{"ingredients":["12 - 15 medium shrimp (prawns), shelled and deveined (about 5 - 7 oz / 150 - 200g, excluding shells)","1 tbsp olive oil","2 garlic cloves (, minced)","Pinch of salt and pepper"],"purpose":"Garlic Shrimp (Prawns)"},{"ingredients":["1/4 cup lime juice","1/4 cup fish sauce","2 tbsp rice vinegar","1 tbsp caster sugar","1 large garlic clove (, very finely chopped)","1 tsp very finely chopped red chili (, adjust to taste (I use birds eye which is spicy))"],"purpose":"Dressing"},{"ingredients":["2.5 oz / 75g dried rice vermicelli noodles (Note 1)","3 cups iceberg lettuce (, shredded)","1 cup carrot (, cut into fine matchsticks)","1 1/2 cups cucumber (, cut into matchsticks)","1 1/2 cups beansprouts","1/4 cup coriander leaves (, lightly packed)","1/4 cup mint leaves ((ordinary or Vietnamese), lightly packed)"],"purpose":"Salad"}]', '[{"description":"Combine the Garlic Shrimp ingredients in a small bowl and set aside for 10 minutes.","duration":10,"images":[],"step":1},{"description":"Combine the Dressing ingredients in a small jar, give it a shake then set aside for 10 minutes.","duration":10,"images":[],"step":2},{"description":"Heat a skillet / fry pan over high heat. Add the shrimp, scraping in the olive oil and garlic from the sides of the bowl. Cook for 2 minutes, or until browned and the shrimp is just cooked through. (Note 2)","duration":2,"images":[],"step":3},{"description":"Remove the prawns from the skillet onto a plate.","images":[],"step":4},{"description":"Prepare the vermicelli noodles according to the packet directions. I like to just soak them in hot tap water for a few minutes, this ensures they don''t overcook. Then drain the noodles.","images":[],"step":5},{"description":"Arrange the noodles and remaining Salad ingredients on a large plate (like the photo) or toss together in a bowl. Top with prawns (warm or at room temperature). Drizzle over the Dressing (or toss through), or you can serve the Dressing on the side.","images":[],"step":6},{"description":"Serve immediately.","images":[],"step":7}]', '["fish","shellfish"]', '["gluten_free","low_calorie"]', '{"mealType":["lunch"],"cuisine":["Modern Vietnamese"],"categories":["asian-recipes","dietary","dinner-tonight","gluten-free-recipes","low-calorie-recipes","main-dishes","most-popular","noodles","prawns-shrimp","quick-and-easy","seafood-recipes","side-salads","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0d6f9af65544', 'en', 'US', 'Shrimp / Prawn Pad Thai (Spice I Am Restaurant Recipe)', 'This is an authentic recipe for Pad Thai from the Spice I Am cookbook, one of the most critically acclaimed Thai restaurants in Sydney. This is a very traditional recipe for those who like truly authentic Thai street food as the dried shrimp flavour is stronger than what you get in westernised Pad Thai recipes. For something more like what you get at mainstream Thai restaurants, use this Everyday Pad Thai recipe.', 'https://www.recipetineats.com/tachyon/2018/05/Spice-I-Am-authentic-Prawn-Pad-Thai-web.jpg', 10, 10, 20, 3, '[{"id": "ing_rice_noodles", "quantity": {"value": 0.378, "unit": "pack of 375g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_shrimp", "quantity": {"value": 12.0, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_tofu", "quantity": {"value": 0.284, "unit": "pack of 300g"}}, {"id": "ing_shrimp", "quantity": {"value": 12.0, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_tamarind_puree", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_chilli", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_roasted_peanuts", "quantity": {"value": 42.525, "unit": "jar"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 5.0, "unit": "bag of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 10.0, "unit": "pack of 3 heads"}}, {"id": "ing_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}]', '[{"ingredients":["5 oz / 150 g dried Pad Thai rice noodles (Note 1)","4 tbsp vegetable oil","12 raw shrimp (prawns), shelled and deveined (Note 2)","1 small red shallot (, finely sliced (Note 3))","3 oz / 80 g firm tofu (, cut into small matchsticks)","1.75 oz / 50 g dried shrimp (Note 4)","1/4 cup fish sauce","2 tbsp palm sugar (or brown sugar)","2 tbsp tamarind puree (Note 5)","1 tsp white vinegar","1/2 tsp + chili powder (, to taste (Note 6))","2 eggs (, lightly beaten)","1.5 oz / 45 g roasted unsalted peanuts (, finely ground)","5 oz / 150 g bean sprouts","2 tbsp garlic chives (, cut into 3/4\" / 2cm lengths)","1 tsp white sugar","Lime wedges (, to serve)"]}]', '[{"description":"Place the rice noodles in a bowl and cover with lukewarm water and set aside for 1 hour. (Note 7) Drain then set aside.","images":[],"step":1},{"description":"Heat 2 tbsp of the oil in a wok or large heavy based fry pan over medium heat. Add the prawns and cook until they just change colour. (Note 8) Remove from the wok and set aside.","images":[],"step":2},{"description":"Add the shallot and stir fry for 2 minutes. Then add the tofu, dried shrimp, fish sauce, palm sugar and tamarind puree and cook for 1 minute until the sugar has dissolved.","duration":2,"images":[],"step":3},{"description":"Add the rice noodles, vinegar and 2 tsp chili powder and stir fry for 2 minutes.","duration":2,"images":[],"step":4},{"description":"Turn the heat down to low and push the noodles to one side. Add the remaining 2 tbsp of oil into the wok then the egg.","images":[],"step":5},{"description":"Push the noodles over the egg and stir, scraping the base of the wok so the egg scrambles and mixes in with the noodles.","images":[],"step":6},{"description":"Remove from heat. Add half the peanuts, most of the bean sprouts, garlic chives, prawns and toss gently.","images":[],"step":7},{"description":"Transfer to serving platter. Sprinkle with white sugar and remaining peanuts. Serve immediately with lime wedges on the side and sprinkled with extra chili powder, if desired.","images":[],"step":8}]', '["egg","fish","shellfish","soy"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["asian-recipes","asian-takeout","cuisines","dietary","gluten-free-recipes","most-popular","noodles","prawns-shrimp","seafood-recipes","thai-recipes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_96928ff590f9', 'en', 'US', 'Thai Chicken Salad Wonton Cups', 'Wonton wrappers baked in a muffin tin to form cups, then filled with a refreshing Thai salad garnished with a little spice kick!', 'https://www.recipetineats.com/tachyon/2015/03/Thai-Chicken-Salad-Wonton-Cup-1.jpg', 20, 15, 35, 12, '[{"id": "ing_wonton_wrappers", "quantity": {"value": 12.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_ime_juice", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.013, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_oil", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_chicken", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_cabbage", "quantity": {"value": 4.5, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 112.5, "unit": "pack of 1kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["12 wonton wrappers"]},{"ingredients":["1 garlic (, smashed (Note 1))","1 1/2 tbsp lime juice","2 tsp rice vinegar","2 1/2 tsp fish sauce","1 tsp soy sauce","1 1/2 tbsp canola oil (or grape seed, vegetable or other neutral flavoured oil)","1 tsp sugar (or honey)","1 - 2 birds eye chilli (, deseeded and finely chopped (or 1 - 2 tsp of chili paste or hot sauce))"],"purpose":"Dressing"},{"ingredients":["1 1/2 cups shredded cooked chicken (I used poached chicken breast)","1 1/2 cups finely shredded cabbage","3/4 cup carrot (, finely julienned)","1/3 cup finely chopped shallots/scallions (or sub with red onion or eschallots)"],"purpose":"Chicken Salad"},{"ingredients":["Sesame seeds","Fresh coriander/cilantro leaves"],"purpose":"Garnish"}]', '[{"description":"Preheat oven to 160C/320F.","images":[],"step":1},{"description":"Place wonton wrappers into a regular muffin tin, moulding it into the cups. Bake for 12 to 15 minutes, until crisp and light golden brown. Remove from the oven and let the cups cool in the muffin tin. Store in an airtight container until required (stays crisp for up to 3 days).","duration":13.5,"images":[],"step":2},{"description":"Combine Dressing ingredients in a jar and shake to combine. Set aside for at least 10 minutes to allow the flavours to infuse.","images":[],"step":3},{"description":"Combine Chicken Salad ingredients in a bowl and toss to combine.","images":[],"step":4},{"title":"To serve","description":"Discard the garlic clove from the Dressing, then toss it through the Chicken Salad. Divide the Chicken Salad between the cups. Garnish with sesame seeds and cilantro/coriander, if using. Serve immediately.","images":[],"step":5}]', '["fish","gluten","sesame","soy"]', '["keto_friendly","low_calorie"]', '{"mealType":["snack"],"cuisine":[],"categories":["asian-recipes","australia-day","chicken-breast-recipes","chicken-recipes","cuisines","finger-food","modern-asian","quick-and-easy","super-bowl-party-food","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_52908fe66415', 'en', 'US', 'Satay Chicken with Restaurant Style Peanut Sauce (Indonesian/Bali style)', 'Though Satay Chicken is better known as Thai or Malaysian food, it actually originated from Indonesia and the Indonesian version is by far the simplest. The Peanut Sauce is my own - refer to the notes for why I prefer this to the authentic version. It is thick so it is great for dolloping, rather than a thin dipping sauce. Satay Chicken is fabulous for outdoor BBQ''s, parties and for fast midweek meals! They also reheat really well in the microwave. They can be cooked on the outdoor grill, on the stove or under the grill/broiler.', 'https://www.recipetineats.com/tachyon/2015/02/DSC_0060.jpg', 15, 20, 35, 12, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_kecap_mani", "quantity": {"value": 2.5, "unit": "unit"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_skewers", "quantity": {"value": 12.0, "unit": "pack of 50"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_chilli", "quantity": {"value": 3.0, "unit": "pack of 100g"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.2, "unit": "jar of 375g"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.625, "unit": "can of 400ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.15, "unit": "bottle of 250ml"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_roasted_peanuts", "quantity": {"value": 37.5, "unit": "jar"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_peanuts", "quantity": {"value": 0.094, "unit": "jar"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 lb / 500g chicken thigh fillets (skinless and boneless)","2 1/2 tbsp kecap manis (thick sweet soy sauce - see Note 1)","1 tbsp unsalted butter (, melted)","12 - 14 small bamboo skewers (, soaked in water for at least 30 minutes)"],"purpose":"Chicken"},{"ingredients":["1 tbsp cooking oil (peanut, canola, vegetable)","2 garlic cloves (, minced)","1 small or 1/2 large onion (, diced (red, brown, yellow or white))","3 birds eye chillis (, sliced (or sub with hot sauce))","1/2 cup peanut butter (smooth or crunchy)","1 cup coconut milk (full fat is better, but light is ok)","2 1/2 tbsp kecap manis (Note 1)","1/2 tbsp soy sauce","1/2 tsp salt","1/4 cup crushed unsalted roasted peanuts (buy crushed or chop your own)","1 - 2 tbsp fresh lime juice"],"purpose":"Peanut Sauce"},{"ingredients":["Crushed peanuts","Lime wedges","Sliced shallots/scallions"],"purpose":"Garnish (optional)"}]', '[{"description":"Cut the chicken into 1.5cm/0.5\" cubes. Thread onto skewers - 4 to 5 pieces per skewer.","images":[],"step":1},{"description":"Combine kecap manis and butter, then brush onto chicken.","images":[],"step":2},{"description":"Cook the skewers on a hot BBQ (outdoor grill) or on the stove in a large non stick fry pan (add a splash of oil, and make sure the skewers will fit in the pan). Grill/broiler would also work.","images":[],"step":3},{"description":"Serve, garnished with crushed peanuts, shallots and with lime wedges and Peanut Sauce on the side.","images":[],"step":4},{"description":"Heat oil in a small saucepan over medium high heat. Add garlic, onion and chillis and cook for 3 minutes until onion is translucent.","duration":3,"images":[],"step":5},{"description":"Turn heat down to medium, then add peanut butter, coconut milk, kecap manis, soy sauce and salt. Simmer for 10 minutes, whisking occasionally.","duration":10,"images":[],"step":6},{"description":"Use a handheld stick to puree (so the onion and chilli blends throughout the sauce - this is key). (See Note 2 for blending instructions) Stir through crushed peanuts and lime juice and simmer for 2 minutes. Allow to cool slightly before serving or to room temperature - it will thicken.","duration":2,"images":[],"step":7}]', '["gluten","milk","peanuts","soy"]', '["keto_friendly","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Asian","Indonesian"],"categories":["asian-recipes","asian-takeout","australia-day","chicken-breast-recipes","chicken-recipes","dietary","gluten-free-recipes","grilling-ideas-and-recipes","most-popular"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3d2f76ec3665', 'en', 'US', 'Chinese Zucchini Pancakes', 'These are old fashioned Chinese pancakes made with zucchini from a fabulous Chinese food blog called Chinese Sichuan Food. I love these pancakes so much that I''ve made them 3 or 4 times in the last month. I make them for breakfast as well as making mini ones to serve as appetisers!', 'https://www.recipetineats.com/tachyon/2014/11/Chinese-Zucchini-Pancakes.jpg', 10, 5, 15, 4, '[{"id": "ing_zucchini", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_flour", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_chinese_five_spice", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_oil", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_vinegar", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_chilli", "quantity": {"value": 0.013, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}]', '[{"ingredients":["1 large zucchini (, grated (1 1/2 cups, not packed in))","3 shallots / scallions (, thinly sliced (about 3/4 cup))","2 eggs","1 cup flour","3/4 tsp salt","1 tsp Chinese five spice (note 1)","1 tsp sesame oil"],"purpose":"Batter"},{"ingredients":["2 tbsp vegetable or other cooking oil"],"purpose":"For cooking"},{"ingredients":["2 tsp Chinese black vinegar (note 2)","1 tsp sesame oil","1 small garlic clove (, finely chopped)","1/4 tsp salt","1/4 tsp chili paste or sauce (optional - see note 3)"],"purpose":"Dipping sauce"},{"ingredients":["Extra sliced shallots / scallions"],"purpose":"To Serve"}]', '[{"description":"Use a cheese grater and grate the zucchini straight into a medium size bowl.","images":[],"step":1},{"description":"Add the remaining ingredients and mix until just combined. Don''t mix too much, just until it is just combined because otherwise you will overwork the flour and the pancake will be tough and hard. The batter will be quite thick, thicker than you expect. It will thin out in the next step.","images":[],"step":2},{"description":"Set aside for 15 minutes. During this time the zucchini will sweat water. Give the batter a quick stir to mix the water in.","duration":15,"images":[],"step":3},{"description":"While the batter is set aside, combine the Dipping Sauce ingredients in a small bowl then set aside.","images":[],"step":4},{"description":"Heat oil in a large heavy based fry pan over medium high heat.","images":[],"step":5},{"description":"Scoop up 1/2 cup (levelled) of batter and place in the pan. Use the bottom of the cup measure (or a spoon) to pat/spread the batter to make a circle that is roughly 12cm / 5 inches in diameter. Repeat with remaining batter (or cook in batches of 2 if your fry pan is not large enough).","images":[],"step":6},{"description":"Cook each side for 1 1/2 minutes until golden brown.","images":[],"step":7},{"description":"Serve immediately, scattered with extra shallots/scallions with the dipping sauce on the side.","images":[],"step":8}]', '["egg","gluten","sesame"]', '["vegan","vegetarian"]', '{"mealType":["breakfast","snack"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","breakfast-recipes","chinese-recipes","zucchini-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f11d8c37d39e', 'en', 'US', 'Restaurant Style Coconut Rice (Coconut Milk)', 'This is a recipe for exceptionally fluffy, coconut rice! No gluggy coconut milk scum left on the surface, each grain is clean and fluffy. The trick is to BAKE it rather than use the stove. No scorched pot, and the rice grains are evenly cooked!Make it Asian-restaurant style by adding pandan leaves OR kaffir lime leaves. Or finish with a sprinkle of toasted coconuts. Serve with: tropical, Caribbean, Indian and Asian foods. See recipe card below for stove-top COCONUT POWDER version (no rice rinse, no soak).', 'https://www.recipetineats.com/tachyon/2014/10/Restaurant-Style-Coconut-Rice-2.jpg', 5, 40, 17, 4, '[{"id": "ing_jasmine_rice", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.025, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_pandan_leaves", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_lime", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_desiccated_coconut", "quantity": {"value": 0.015, "unit": "kg"}}]', '[]', '[{"description":"Rinse rice in water until the water runs pretty clear. (Note 1)","images":[],"step":1},{"title":"Soak & drain","description":"Drain rice then soak in water for 1 hour. Then drain in a colander and leave to drain well for 5 minutes.","images":[],"step":2},{"description":"Preheat oven to 200°C / 400°F (180°C fan).","images":[],"step":3},{"title":"Rice in pan","description":"Place the rice in a 20cm / 8\" square pan (metal or ceramic). Add pandam or kaffir, if using.","images":[],"step":4},{"title":"Heat coconut milk","description":"Heat coconut milk, water, sugar and salt in a saucepan over high heat. Bring to a boil and stir to dissolve the sugar.","images":[],"step":5},{"title":"Bake 40 minutes","description":"Working quickly (to minimise heat loss), pour hot liquid over rice, stir quickly to spread rice evenly. Cover with foil then bake in the oven for 40 minutes.","duration":40,"images":[],"step":6},{"title":"Rest 15 minutes","description":"Remove the pan from the oven. Take a quick peek to ensure the liquid has been absorbed (tilt pan to check). There will be coconut cream on the surface - that''s normal. Rest rice, covered, for 15 minutes. Do not shortcut this!","duration":15,"images":[],"step":7},{"description":"Fluff with rubber spatula. Garnish with toasted coconut, if using, then serve. Marvel at fluffy rice!","images":[],"step":8}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Asian"],"categories":["asian-recipes","asian-takeout","dietary","easter-sides-warm-hearty","gluten-free-recipes","modern-asian","most-popular","quick-and-easy","rice-recipes","rice-side-dishes","side-dishes","tropical","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9933c7c2de1f', 'en', 'US', 'Slow Cooker Crispy Chinese Shredded Chicken', 'This is one of those Chinese dishes that tastes great even if you have to substitute one or two of the ingredients or get the quantities a bit wrong. I really encourage you to go to an Asian Grocery store to get Chinese cooking wine because it is so cheap! I bought a large bottle for A$0.99 (less than US$1.00). This shredded chicken is great served on rice, with noodles (like this Crispy Shredded Chicken Noodle stir fry), in fried rice, stir fries or even on salads.', 'https://www.recipetineats.com/tachyon/2014/11/Crispy-Slow-Cooker-Chinese-Shredded-Chicken.jpg', 5, 480, 485, 10, '[{"id": "ing_chicken", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 1.25, "unit": "bottle of 500ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_vinegar", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 1.25, "unit": "bottle of 250ml"}}, {"id": "ing_ginger", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_oil", "quantity": {"value": 45.0, "unit": "bottle"}}]', '[{"ingredients":["3 - 4 lb / 1.5 - 2 kg whole chicken (, skin on)","2 1/2 cups Chinese cooking wine (or sherry) (see notes)","3/4 cup brown sugar (or substitute with white sugar)","1/4 cup black vinegar (or substitute with malt vinegar, or white vinegar. Don''t use balsamic)","1 1/4 cups light soy sauce (or substitute with 3/4 cup ordinary soy sauce + 1/2 cup water + 1 tsp salt)","3 tbsp coarsely chopped ginger (no need to peel)","4 garlic cloves (, crushed (not minced - see notes))","3 tbsp cooking oil (vegetable, peanut or canola)"]}]', '[{"description":"Slow Cooker","images":[],"step":1},{"description":"Place all ingredients except the oil in slow cooker.","images":[],"step":2},{"description":"Slow cook on low for 8 hours.","images":[],"step":3},{"description":"Place all ingredients except the oil in a pot in which the chicken fits quite snugly but not tightly (you don''t want the sides of the chicken pressed up tightly against the wall of the pot).","images":[],"step":4},{"description":"Put lid on and bring to boil over high heat. Turn heat down to low and let it simmer for 1 1/2 to 2 hours, until the meat is very tender and falling off the bone.","images":[],"step":5},{"description":"Shredding and Crisping","images":[],"step":6},{"description":"Remove chicken from braising liquid.","images":[],"step":7},{"description":"Shred with your hands or two forks, including the skin. The meat should fall off very easily.","images":[],"step":8},{"description":"Heat 1 tbsp of oil over high heat in a large heavy based fry pan.","images":[],"step":9},{"description":"Add chicken (enough to cover the pan without crowding it) and drizzle over braising liquid.","images":[],"step":10},{"description":"Cook until the underside is browned and crispy (about 1 1/2 minutes), then remove from the pan. Don''t flip the chicken (see notes).","images":[],"step":11},{"description":"Repeat with remaining chicken (it takes me 3 batches).","images":[],"step":12},{"description":"Serve with rice, on rice stick noodles or on a salad with the remaining braising liquid on the side. It is also great in fried rice.","images":[],"step":13},{"description":"This freezes really well, before or after browning the chicken. Just divide into freezer bags, label then freeze. If you froze it before browning the chicken, then brown it after thawing.","images":[],"step":14}]', '["gluten","peanuts","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["main_course"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","chinese-recipes","dietary","gluten-free-recipes","main-dishes","most-popular","quick-and-easy","slow-cooked-fall-apart","slow-cooker-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6304c26db9ab', 'en', 'US', 'Slow Cooker Beef and Broccoli', 'This slow cooker version of Beef & Broccoli is made using the same ingredients as the authentic way of making this but the quantities have been adjusted to make it suitable for slow cooking. Making this in a slow cooker means you can use a budget cut of beef and it makes it meltingly tender. AND it''s freezer friendly!', 'https://www.recipetineats.com/tachyon/2014/09/Slow-Cooker-Beef-Broccoli-2.jpg', 10, 180, 190, 4, '[{"id": "ing_beef_steak", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_broccoli", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_ginger", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.04, "unit": "bottle of 500ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 4.0, "unit": "jar of 50g"}}]', '[{"ingredients":["500 g / 16 oz chuck steak or other beef cut suitable for slow cooking","300 g / 16 oz broccoli florets (about 6 cups, 1 giant broccoli or 2 medium)","2 tbsp corn flour (corn starch)","1 cup water (see note 2)"]},{"ingredients":["2 tbsp oil","2 tbsp finely sliced fresh ginger (note 1)","3 tbsp soy sauce (normal dark soy sauce)","2 tbsp oyster sauce","4 tsp Chinese cooking wine (rice wine) or dry sherry (note 5)","1 tsp sesame oil (optional)","1 tsp sugar","4 dashes white pepper"],"purpose":"Sauce"}]', '[{"description":"Cut the beef into thin slices against the grain (which means at 90 degrees to the direction of the fibres in the meat).","images":[],"step":1},{"description":"Place beef in slow cooker.","images":[],"step":2},{"description":"Mix the corn flour with the water, then add to the slow cooker.","images":[],"step":3},{"description":"Add the Sauce ingredients to the slow cooker.","images":[],"step":4},{"description":"Cook on HIGH for 3 hours (or pressure cook on high for 40 minutes).","images":[],"step":5},{"description":"To Serve Immediately","images":[],"step":6},{"description":"Steam or boil broccoli until \"tender crisp\" (just cooked, still bright green and still crisp).","images":[],"step":7},{"description":"Add to beef and sauce, toss to combine. Serve over rice.","images":[],"step":8},{"description":"To Make Ahead to Freeze (2 months) or Refrigerate (2 days)","images":[],"step":9},{"description":"Let the beef and sauce cool.","images":[],"step":10},{"description":"Meanwhile, blanch the broccoli very briefly, then run under cold water or plunge into ice water to stop from cooking further.","images":[],"step":11},{"description":"Drain broccoli, then combine with the beef and sauce.","images":[],"step":12},{"description":"Place into ziplock bags or airtight containers and freeze or refrigerate.","images":[],"step":13},{"description":"To cook, thaw then reheat in the microwave, covered. Be careful not to heat for too long because otherwise the broccoli will overcook.","images":[],"step":14},{"description":"Serve with rice.","images":[],"step":15}]', '["gluten","sesame","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","beef-recipes","broccoli-recipes","chinese-recipes","main-dishes","quick-and-easy","slow-cooker-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9b28a0462ee3', 'en', 'US', 'Vietnamese Chicken Wings', 'These wings are marinaded in classic Vietnamese flavours then grilled to perfection on the barbecue! They can also be cooked in the oven.', 'https://www.recipetineats.com/tachyon/2014/07/Vietnamese-Wings-1-Version-21.jpg', 15, 40, 55, 24, '[{"id": "ing_chicken", "quantity": {"value": 0.907, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 6.667, "unit": "pack of 3 heads"}}, {"id": "ing_ime_juice", "quantity": {"value": 0.25, "unit": "unit"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_lemongrass", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["2 lb / 1 kg chicken wings","Oil for grilling"]},{"ingredients":["4 cloves minced garlic","1/4 cup lime juice (2 to 3 limes)","1/4 cup fish sauce","2 tbsp soy sauce","3 tbsp brown sugar","2 tbsp vegetable oil","2 stalks lemongrass"],"purpose":"Marinade"},{"ingredients":["1 birds eye chilli (, finely chopped)","Coriander leaves"],"purpose":"Garnishes (optional)"}]', '[{"description":"Bruise the lemongrass using the side of your knife (or a pestle). Slice the white part only into 0.5cm / 1/4\" slices, thick enough to pick off later if any stick to the wings.","images":[],"step":1},{"description":"Combine lemongrass with the rest of the marinade ingredients and mix well.","images":[],"step":2},{"description":"Combine marinade with wings in a ziplock bag. Remove as much air as possible from the bag and seal. Massage marinade into the wings to evenly disperse.","images":[],"step":3},{"description":"Marinate for at least a few hours, preferably overnight.","images":[],"step":4},{"description":"When ready to cook, pour the wings and marinade into a large bowl.","images":[],"step":5},{"description":"To cook on grill","images":[],"step":6},{"description":"Lightly oil the grill and preheat on medium low. The grill side cooks the wings more evenly than the hotplate side.","images":[],"step":7},{"description":"Remove wings from marinade and grill until cooked through. Do not cook on a high heat otherwise the sugar will burn before the inside of the wings are cooked.","images":[],"step":8},{"description":"Just before the wings are ready, remove the wings from the grill and put them back into the bowl and toss in the marinade, then put back on the BBQ and sear quickly on both sides.","images":[],"step":9},{"description":"To cook in oven","images":[],"step":10},{"description":"Preheat oven to 180C/350F and put the rack in the top part of the oven.","images":[],"step":11},{"description":"Line a baking tray with baking paper and place a rack on it.","images":[],"step":12},{"description":"Remove wings from the marinade and spread out over the rack.","images":[],"step":13},{"description":"Bake for 20 to 25 minutes until the top side is golden brown, then turn the wings and baste.","duration":22.5,"images":[],"step":14},{"description":"Return to oven for another 10 to 15 minutes until the wings are a dark golden brown.","images":[],"step":15},{"description":"Turn again, baste and return to the oven for another 5 minutes.","images":[],"step":16},{"description":"To serve","images":[],"step":17},{"description":"Serve garnished with coriander leaves and chilli slices (optional).","images":[],"step":18}]', '["fish","gluten","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["snack"],"cuisine":["Asian","Vietnamese"],"categories":["asian-recipes","australia-day","chicken-recipes","chicken-wings","grilling-ideas-and-recipes","quick-and-easy","super-bowl-party-food","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_38cbd41f053d', 'en', 'US', 'Momofuku Marinated Beef Skirt Steak Ssam', '"Ssam" refers to Korean dishes in which leafy vegetables, usually lettuce, are wrapped around meat. This is a recipe by the much celebrated chef David Chang, from his famous New York restaurant Momofuku. The marinade for the beef is a classic Korean marinade and infuses the meat with enough flavour that they can be eaten as is, without a sauce. The sauces are simple to make once you get your hands on the ingredients. Excluding the marinating time, this is really fast and easy to make.', 'https://www.recipetineats.com/tachyon/2014/07/Momofuku-Marinated-Skirt-Steak-Ssam-3.jpg', 20, 10, 30, 4, '[{"id": "ing_beef_steak", "quantity": {"value": 0.907, "unit": "kg"}}, {"id": "ing_apples", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 1.0, "unit": "bottle of 250ml"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 4.536, "unit": "bunch"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_grapes", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 2.0, "unit": "bottle of 250ml"}}, {"id": "ing_vinegar", "quantity": {"value": 0.004, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_ssamjang", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_kochujang", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_oil", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_lettuce", "quantity": {"value": 3.0, "unit": "head"}}]', '[{"ingredients":["2 lb / 1 kg skirt / flank / hanger steak (Note 1)","2 cups apple juice","½ cup light soy sauce","5 garlic cloves (, minced)","1/2 brown onion","1 tsp sesame oil","1 tsp freshly ground black pepper"],"purpose":"Beef and Marinade"},{"ingredients":["8 oz / 250 g shallots/scallions (, thinly sliced)","5 g fresh ginger (, finely chopped or minced)","4 tbsp grape seed oil (or another neutral oil)","1 1/2 tsp light soy sauce","3/4 tsp sherry vinegar","3/4 tsp salt (adjust to taste)"],"purpose":"Ginger Spring Onion Sauce"},{"ingredients":["1 tbsp ssamjang (Korean fermented bean-and- chili paste, available in many Asian stores)","1/2 tbsp kochujang (Korean chili paste, available in many Asian stores)","1/4 cup sherry vinegar","1/4 cup grape seed oil (or another neutral oil)"],"purpose":"Ssam Sauce"},{"ingredients":["3 small heads of Bib Lettuce (, leaves removed, washed and dried)"],"purpose":"To Serve"}]', '[{"description":"Combine Beef with Marinade and marinade at least overnight, up to 24 hours.","images":[],"step":1},{"description":"Remove beef from marinade. Preheat outdoor grill or heavy based skillet on stove on very high heat. You want it to be screaming hot. Cook the beef to your liking (see notes for guide).","images":[],"step":2},{"description":"When done, remove from heat, cover loosely with foil and let them rest for 5 to 10 minutes.","duration":7.5,"images":[],"step":3},{"description":"Make the Ginger Spring Onion Sauce by combining the ingredients and mixing to combine.","images":[],"step":4},{"description":"Make the Ssam Sauce by combining the ingredients and mixing well until smooth.","images":[],"step":5},{"description":"Slice the beef into 0.5cm / 0.2 inch thick slices, against the grain.","images":[],"step":6},{"description":"Serve with lettuce, Ginger Spring Onion Sauce and Ssam Sauce on the side.","images":[],"step":7},{"description":"To eat, place a piece of beef in a lettuce leaf, top with some of each sauce, then fold over lettuce, eat and be happy.","images":[],"step":8}]', '["gluten","sesame","soy"]', '["high_protein","high_protein_low_calorie","vegan","vegetarian"]', '{"mealType":["snack","dinner"],"cuisine":["Asian","Fusion","Korean"],"categories":["asian-recipes","australia-day","beef-recipes","grilling-ideas-and-recipes","korean-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_11570f07c9a3', 'en', 'US', 'Foolproof Poached Chicken Noodle Soup', 'This recipe uses a foolproof method of poaching chicken breast so you''ll never, ever overcook it. The soup stock is a refreshingly light and the flavour is enhanced by poaching the chicken in the same liquid. A perfect super fast, low maintenance mid week meal!', 'https://www.recipetineats.com/tachyon/2014/06/Untitled-2.jpg', 5, 30, 35, 2, '[{"id": "ing_chicken_breast", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_bok_choy", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 1.0, "unit": "bag of 250g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.283, "unit": "pack of 500g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.045, "unit": "bottle of 500ml"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_star_anise", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 chicken breast (up to 300g/10 oz)","3 bok choys (or 4 small ones)","1 cup bean sprouts","5 oz / 150 g fresh egg noodles"]},{"ingredients":["2 cups / 16 oz / 500 mls chicken stock","1 cup water","1 1/2 tbsp soy sauce","2 tsp sugar","1 1/2 tbsp chinese cooking wine (or sub with 2 tsp sherry or sake (rice wine))","2 tsp ginger (, minced)","2 garlic cloves (, minced)","1 star anise"],"purpose":"Soup Stock"},{"ingredients":["1 scallion/shallot (, light green and green part only, sliced)","Fried Asian shallots"],"purpose":"Garnish (optional)"}]', '[{"description":"Combine Soup Stock ingredients in a medium saucepan large enough to hold the 2 chicken breasts side by side (without being crammed in). Bring to boil, taste and adjust if necessary.","images":[],"step":1},{"description":"Add chicken to soup, bring back to boil. Remove from heat and put aside covered for 20 - 25 mins. Don''t worry if you leave it for longer, it won''t over cook.","duration":22.5,"images":[],"step":2},{"description":"When the chicken is poached, remove from the soup and slice into 1/4\" / 0.5cm slices.","images":[],"step":3},{"title":"Cook noodles according to the packet instructions","description":"usually for fresh noodles soaking them in boiling water is sufficient.","images":[],"step":4},{"description":"Cut the bok choy leaves from the stems, cut the stems vertically into 1/3\" / 1cm wide sticks.","images":[],"step":5},{"description":"Bring the soup (without the poached chicken in it) back to boil, add the bok choy stems, boil for 30 seconds then remove from heat, add the bok choy leaves and bean sprouts.","duration":0.5,"images":[],"step":6},{"description":"To assemble place noodles in bowl, top with bok choy, chicken and spoon over soup.","images":[],"step":7},{"description":"Garnish with scallions/shallots and fried shallots.","images":[],"step":8}]', '["egg","gluten","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","asian-soups","chicken-breast-recipes","chicken-recipes","chinese-recipes","emergency-recipes","main-dishes","noodles","quick-and-easy","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2acebf032e38', 'en', 'US', 'Scallion Pancakes (Shallot Pancakes)', 'My favourite Chinese restaurant treat, made at home! So easy, and unbelievably good. The roll out dough will keep in the fridge for a couple of days, or you can freeze them, then pop them in the pan when you are ready to cook (you don''t even need to defrost them). They are best eaten fresh off the stove!', 'https://www.recipetineats.com/tachyon/2014/06/DSC_0036-680x680-1.jpg', 20, 10, 30, 4, '[{"id": "ing_flour", "quantity": {"value": 0.375, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_green_onion", "quantity": {"value": 6.0, "unit": "bunch"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_oil", "quantity": {"value": 0.24, "unit": "bottle"}}, {"id": "ing_soy_sauce", "quantity": {"value": 1.0, "unit": "bottle of 250ml"}}, {"id": "ing_vinegar", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["2 1/2 cups plain flour","1 tsp salt","1 cup water","2 cups chopped shallots (aka green onions, shallots) (half a large bunch)","Oil spray (any is fine, except olive oil)","4 tbsp vegetable or canola oil"]},{"ingredients":["Soy sauce","Black vinegar (or substitute with white vinegar)","Chilli paste (optional)"],"purpose":"Dipping Sauce"}]', '[{"description":"Combine flour and 1 tsp salt in a bowl, add water in 3 batches, mixing in between with a spoon (see notes for tips on getting the dough right).","images":[],"step":1},{"description":"Knead for a minute, either in the bowl or on a flour dusted surface, then cover with cling wrap and rest for 10 minutes.","duration":10,"images":[],"step":2},{"description":"Divide dough into 2 pieces.","images":[],"step":3},{"description":"Roll out dough thinly into a rectangle should about 1.5ft/50cm x 8\"/20cm.","images":[],"step":4},{"title":"Spray lightly with oil (any oil is fine","description":"except perhaps olive oil), then roll it up starting from the wide end so you have a long roll.","images":[],"step":5},{"description":"Coil it into a snail shape, push down with your hand and roll out again into the same shape.","images":[],"step":6},{"description":"Spray again with oil, scatter over the chopped scallions and a pinch of salt. Then roll it up again, starting from the wide end.","images":[],"step":7},{"description":"Cut the roll in half, and coil each roll.","images":[],"step":8},{"description":"Repeat with the other ball of dough. You will end up with 4 coils.","images":[],"step":9},{"description":"Flatten each coil, then roll out into round shapes about 1/3 \" / 0.5 cm thick.","images":[],"step":10},{"description":"Heat 1 tbsp oil in pan, pan fry for 1 1/2 minutes on the first side, then 1 minute on the other side, pushing down with a spatula if necessary to get it to cook the surface evenly. It should be a dark golden brown colour.","images":[],"step":11},{"description":"Combine equal parts of soy sauce and black vinegar into a small sauce dish, and add a dollop of Asian chilli paste.","images":[],"step":12}]', '["gluten","soy"]', '["vegan","vegetarian"]', '{"mealType":["snack"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","asian-takeout","chinese-recipes","quick-and-easy","side-dishes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cfcd56822166', 'en', 'US', 'Sticky Chinese Pork Spare Ribs', 'Deliciously sticky and moorish, these ribs are great for entertaining. Once you start, it’s hard to stop - make sure you provide plenty of nap- kins for your guests!', 'https://www.recipetineats.com/tachyon/2014/05/Sticky-Chinese-Ribs-2.jpg', 10, 150, 160, 4, '[{"id": "ing_beef_steak", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.01, "unit": "pack of 100g"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_wine", "quantity": {"value": 0.04, "unit": "bottle of 750ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.24, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_sambal_oelek", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 10.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_chinese_five_spice", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["2 kg / 4 lbs meaty pork ribs (, cut into single rib pieces)","1 tsp sesame oil","2 tbsp lemon juice","2 tbsp shao xing wine","4 tbsp soy sauce","4 tbsp brown sugar or honey","4 tbsp tomato sauce or ketchup","2 tbsp hoisin sauce","2 tbsp oyster sauce","2 tbsp sambal oelek","6 cloves garlic (, finely chopped)","2 tbsp grated ginger","1 tsp Chinese five spice powder","1 tsp salt","Sesame seeds (, coriander, shallots and red chilli to garnish (optional))"]}]', '[{"description":"Mix marinade ingredients together in a bowl or freezer bag. Add the ribs and marinate for at least an hour, or overnight if possible. You can freeze the marinaded meat if you wish.","images":[],"step":1},{"description":"Before cooking, let the ribs come to room temperature.","images":[],"step":2},{"description":"Preheat the oven to 160C/320F.","images":[],"step":3},{"description":"Pour the ribs and all the marinade into a baking dish large enough so the ribs are in a single layer, but not so large that they are too spread out.","images":[],"step":4},{"description":"Add water up to about 1/3 of the way up the ribs. 6 Cover tightly with foil and place in oven to cook for approximately 1.5 hours.","images":[],"step":5},{"description":"Take out of the oven, remove the foil and touch the ribs – they should be quite tender, but not falling off the bone. The marinade in the baking dish should still be quite watery.","images":[],"step":6},{"description":"Turn the ribs over, then return the baking dish to the oven without the foil. After 20 minutes, take the ribs out – they should be nicely browned and starting to char. Turn the ribs, then spoon the marinade over, then return to the oven for another 10 to 20 minutes.","images":[],"step":7},{"description":"The ribs are done when they are falling off the bone, sticky and glossy and the marinade has reduced down to a thick sauce coating the ribs.","images":[],"step":8},{"description":"Rest for 5 minutes. Garnish with coriander, sesame seeds, julienned shallots and sliced fresh red chilli.","duration":5,"images":[],"step":9}]', '["gluten","sesame","soy"]', '[]', '{"mealType":["main_course"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","chinese-recipes","pork-recipes","uncategorized","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_110a8a75fe09', 'en', 'US', 'My quickest Chinese Vegetable Soup - low calorie miracle!', 'Recipe video above. My quickest Chinese Vegetable Soup. Quick and easy, versatile, extremely low 108 calories yet still downright delicious. If only all healthy food was this tasty!Pile in as much veg as you want! It cooks down so you can really go wild. (PS If you need carbs though - I get it - here''s the Noodle Soup version here and the Rice Soup version here!)**Slide the Servings scaler to scale up**', 'https://www.recipetineats.com/tachyon/2024/06/Chinese-Veg-Soup-50968-close-up.jpg', 5, 10, 15, 2, '[{"id": "ing_chicken_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_star_anise", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.045, "unit": "bottle of 500ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_broccoli", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1 litre / 4 cups chicken stock/broth, ( low sodium (Note 1))","2 garlic cloves (, peeled and halved)","1.5 cm / 1/2\" ginger piece, (cut into 5 thin slices (optional, but highly recommended))","1 star anise (, optional)","1 1/2 tbsp light soy sauce (, or all purpose soy sauce (Note 2))","2 tsp sugar (any)","1 1/2 tbsp chinese cooking wine (Note 3)","1/2 tsp sesame oil (, toasted (optional) (Note 5))"],"purpose":"Infused Asian Broth"},{"ingredients":["4 - 6 stems Chinese broccoli (or bok choy, stems and leaves sliced and separated (Note 7 for how to chop))","1 small carrot (, peeled, cut in half lengthways then finely sliced on the diagonal )","75g / 2.5 oz enoki mushrooms (\"faux\" noodles!), or other mushrooms sliced or quartered (Note 8)"],"purpose":"Vegetables (be generous!) – or other veg Note 6"},{"ingredients":["1/2 cup coriander/cilantro sprigs/leaves (, lightly packed (or Thai basil, mint, chives))","1 green onion (, green part only finely sliced)","2 tbsp crispy fried shallots (store bought, staple in my pantry!)","Chilli crisp, chilli sauce or sriracha (, optional )","Other ideas: sesame seeds, sliced chilli, Thai basil"],"purpose":"Toppings"}]', '[{"title":"Infused broth","description":"Place Broth ingredients in a large saucepan over high heat. Place lid on, bring to a simmer then reduce to the lowest heat and simmer gently for 10 minutes to allow the flavours to infuse. (Meanwhile, chop the veg)","duration":10,"images":[],"step":1},{"title":"Cook vegetables","description":"Turn the heat up to high and bring the liquid back to a rapid simmer. Add the carrots, Chinese broccoli stems and enoki mushrooms. Cook 3 minutes. Add Chinese broccoli leaves, push in a simmer for 2 minutes until wilted.","duration":2,"images":[],"step":2},{"title":"Serve","description":"Pick the garlic and ginger out of soup. Divide between 2 bowls. Top with a mound of coriander, sprinkle with green onions, shower with crispy shallots, and a good dollop of chilli sauce or chilli crisp. Dig in, feel good!","images":[],"step":3}]', '["gluten","sesame","soy"]', '["low_calorie"]', '{"mealType":["main_course"],"cuisine":["Asian","Chinese"],"categories":["asian-soups","dietary","low-calorie-recipes","quick-and-easy","soup-recipes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3ce3afb0cf8b', 'en', 'US', 'Vietnamese Chicken Pho soup (Pho Ga)', 'Recipe video above. Chicken Pho (Pho Ga) - the little sister of famous Beef Pho, equally delicious but much easier to make! I call it the Vietnamese version of homemade chicken noodle soup made from scratch. Except - dare I say it - so much more exciting!You won''t use all the chicken, but it''s infused with lovely flavour so there''s loads of uses - see Note 7.', 'https://www.recipetineats.com/tachyon/2020/05/Chicken-Pho_2.jpg', 10, 90, 100, 4, '[{"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_ginger", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_star_anise_pods", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_s", "quantity": {"value": 4.0, "unit": "pack"}}, {"id": "ing_fennel_seeds", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.04, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_rice_noodles", "quantity": {"value": 0.96, "unit": "pack of 375g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.04, "unit": "bunch"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 3.0, "unit": "bag of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_imes", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_sriracha", "quantity": {"value": 1.0, "unit": "bottle of 400ml"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1 tbsp oil (, vegetable or canola (or other plain oil))","2 onions (, halved (skin on fine))","5cm/ 2\" piece of ginger (, sliced 0.75cm / 1/3\" thick (unpeeled))"],"purpose":"Charred aromatics:"},{"ingredients":["2 litres / 2 quarts water","1.5 kg / 3 lb chicken thighs, bone in skin on (Note 1)","1 small bunch coriander/cilantro (Note 2)","5 star anise pods (was short in photo & video!)","1 cinnamon stick","4 cloves","2 tsp fennel seeds","2 tsp coriander seeds","8 tsp fish sauce","6 tsp white sugar","3/4 tsp salt (Cooking/kosher salt, or 1/2 tsp table salt)"],"purpose":"Pho Soup Broth:"},{"ingredients":["360g / 13 oz dried rice noodles (, thin flat (or 600g fresh))","2 green onions stems (, finely sliced)"],"purpose":"Noodle Bowls:"},{"ingredients":["3 cups bean sprouts (Note 3)","1 small bunch EACH Thai Basil, min, coriander/cilantro (Note 4)","2 limes (, cut into 4 wedges)","Hoisin sauce","Sriracha","Red chillies (, finely sliced (optional))"],"purpose":"Toppings – help yourself"}]', '[{"title":"Char onion & ginger","description":"Heat oil in a 6 litre / 6 quart pot (Note 5) over high heat. Place ginger and onion facedown, leave undisturbed for 2 minutes until they blacken. Turn and leave for another 2 minutes.","duration":2,"images":[],"step":1},{"title":"Put everything in pot","description":"Add water and remaining Broth ingredients EXCEPT salt. Bring it a simmer, then lower heat so it''s simmering VERY gently with the lid on, but open a crack (Note 6).","images":[],"step":2},{"description":"Simmer gently 1.5 hours. Scoop off scum (dirty foam) that rises to surface once or twice during the simmering.","images":[],"step":3},{"title":"Strain & measure","description":"Remove chicken, then strain broth into a clean pot - you should have 1.5 litres / 1.5 quarts. If you have more, simmer to reduce. If less, top it up with water.","images":[],"step":4},{"title":"Salt broth","description":"Add salt, bring broth to a gentle simmer. Broth should be slightly on the salty side - it dilutes when you add the noodles.","images":[],"step":5},{"description":"Keep broth warm until ready to serve","images":[],"step":6},{"description":"Shred chicken meat, discard bones and skin. (Note 6 Leftover Chicken ideas)","images":[],"step":7},{"description":"Place Toppings out on the table.","images":[],"step":8},{"description":"Reheat chicken (can briefly dunk in broth!).","images":[],"step":9},{"description":"Prepare noodles per packet directions, just prior to serving. Drain very well (excess water dilutes broth).","images":[],"step":10},{"description":"Place noodle in bowls. Top with chicken, ladle over 375ml / 1.5 cups broth. Sprinkle with green onion.","images":[],"step":11},{"description":"Pile on Toppings of choice, add a squeeze of lime into the broth. Consume immediately!","images":[],"step":12}]', '["fish"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Vietnamese"],"categories":["asian-soups","iconic-dishes","soup-recipes","vietnamese-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_309a5dcc98d0', 'en', 'US', 'Chinese Orange Chicken', 'Recipe video above. This is a recipe for Chinese Orange Chicken that makes impressively crispy chicken pieces without deep frying. The sauce has great orange flavour, it''s not too sweet, and I love the background hint of ginger!The chicken does lose crispiness once tossed with sauce, but you''ll still get crispy bits. It''s not a flaw, it''s the way it is! More importantly though, the sauce really clings to the surface of the chicken so you get a good amount of that lovey orange sauce with every bite.Source: Loosely based on the Orange Chicken by Woks of Life, though I used my no-deep-fry method and tweaked the sauce to my taste.', 'https://www.recipetineats.com/tachyon/2026/06/Orange-chicken-0.jpg', 20, 15, 35, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_ginger", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.075, "unit": "pack of 400g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_oranges", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_oranges", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.06, "unit": "bottle of 500ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_white_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["600g/1.2 lb boneless skinless chicken thighs or breast (, cut into 2.5cm / 1\" pieces)","2 tbsp light soy sauce (, or all-purpose soy (not dark soy - Note 1))","1/2 tsp finely grated ginger (, optional)","1/8 tsp white pepper (substitute black pepper)","2 tbsp cornflour / cornstarch (- for mixing)","3/4 cup cornflour / cornstarch (- for crispy coating)","3/4 - 1 cup vegetable oil (, or other plain oil (1/2 cm / 0.2\" depth))"]},{"ingredients":["2 tsp orange zest (, from 1 orange)","1 cup orange juice (, either squeeze oranges or use fresh bottled OJ (or use the orange then top up with bottle))","1 1/2 tbsp cornflour / cornstarch","2 tbsp Chinese cooking wine (/Shaoxing wine (Note 2))","2 tbsp rice vinegar (substitute white vinegar)","1/3 cup + 2 tbsp white sugar","2 tbsp light soy sauce ( or all-purpose soy sauce (not dark soy - Note 1))","1/4 tsp cooking salt / kosher salt (halve for table salt, double for flakes)","1 tsp ginger (, finely grated)","2 garlic cloves (, finely minced with a knife)"],"purpose":"Orange sauce:"},{"ingredients":["White rice (, or other plain rice of choice)","1 green onion (, finely sliced - optional garnish)","White sesame seeds - optional garnish"],"purpose":"For serving:"}]', '[{"description":"Mix chicken with soy, ginger, pepper and 2 tbsp cornflour, then coat in remaining cornflour. Clench few pieces in fist, shake off excess cornflour in colander. Shallow-fry until deep golden. Remove oil, sauté garlic, simmer sauce 2 min until thickened. Add zest, toss chicken, serve!","images":[],"step":1},{"title":"Orange sauce","description":"Whisk the cornflour and soy sauce in a large jug or medium bowl until lump free. Then whisk in everything else except garlic and orange zest. Set aside.","images":[],"step":2},{"title":"Coat chicken","description":"Mix the chicken pieces with the soy sauce, ginger, pepper and the 2 tablespoons of cornflour in a large bowl. Mix well - the coating becomes a bit sticky and acts as a glue. Add the 3/4 cup cornflour and toss to coat each piece, separating as needed (they stick together a bit).","images":[],"step":3},{"title":"Press and shake off","description":"Pick up a few pieces and enclose in your fist, to really press the cornflour on. Place in a colander, then repeat with remaining chicken. Shake colander so excess cornflour falls through the holes. This press-and-shake method is highly effective crispy no-fry technique! (Note 3)","images":[],"step":4},{"title":"Shallow-fry until crispy","description":"Heat the oil on high heat in a large deep non-stick pan (mine is 30cm/12\"). The chicken should sizzle straight away when you dip it. Spread half the chicken out (or as much as you can, without crowding), and cook for 1 1/2 minutes on each side, using tongs to turn, until deep golden and crispy. Remove onto a paper towel lined tray and repeat with remaining chicken.","images":[],"step":5},{"title":"Sauté","description":"Pour out all but 2 tablespoons of the oil, and scrape out any loose crispy bits. Return the pan to medium high heat. Sauté garlic until light golden, about 20 - 30 seconds.","images":[],"step":6},{"title":"Thicken sauce","description":"Give the sauce a whisk (to mix cornflour settled on the base) then pour it in the pan. Simmer for 1 to 2 minutes until it thickens into a thick, glossy syrup (honey consistency). Stir in zest.","duration":1.5,"images":[],"step":7},{"title":"Toss","description":"Put the chicken back into the pan and toss quickly to coat in the sauce. Serve over rice, garnished with green onion.","images":[],"step":8}]', '["gluten","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Chinese","Chinese American"],"categories":["asian-takeout","chicken-recipes","chinese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8b2c5c3577cb', 'en', 'US', 'Thai Green Papaya Salad (Som Tum)', 'Recipe video above. In Thailand, Green Papaya Salad is traditionally made in giant mortar and pestles large enough to hold the entire salad. The dressing is pounded first, and the rest of the salad is added, pounded a little and finally tossed. For this home version, we use an ordinary size mortar instead. We make the salad in stages, then bring it all together at the end in a bowl. Different method. Same result! Like all good Thai food, the taste of the finished dish should be a balance of sweet, salty, sour and spicy. The lime brings zing, palm sugar adds sweetness, while the fish sauce and dried shrimp lend deep savouriness and complexity.For a truly authentic experience, be brave and don''t skimp on the chilli. Green Papaya Salad is MEANT to be spicy!', 'https://www.recipetineats.com/tachyon/2021/08/Green-Papaya-Salad_54.jpg', 25, 0, 25, 4, '[{"id": "ing_garlic", "quantity": {"value": 10.0, "unit": "pack of 3 heads"}}, {"id": "ing_chilli", "quantity": {"value": 6.0, "unit": "pack of 100g"}}, {"id": "ing_shrimp", "quantity": {"value": 0.09, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_ime_juice", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_roasted_peanuts", "quantity": {"value": 150.0, "unit": "jar"}}, {"id": "ing_snake_beans", "quantity": {"value": 20.0, "unit": "pack"}}, {"id": "ing_tomato", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_green_papaya", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_basil", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["2 tbsp garlic (, roughly chopped (10 normal or 4 large garlic cloves))","6 bird eye chillies, (, roughly chopped with seeds (use fewer for less spicy, Note 1))","6 tbsp dried shrimp (Note 2)","1 cup palm sugar (, grated using standard box grater, loosely packed (Note 3))","1/2 cup lime juice","1/2 cup fish sauce"],"purpose":"Dressing:"},{"ingredients":["1 cup roasted peanuts (, unsalted)","20 snake beans (, cut in 5cm/2\" pieces (raw, Note 4))","3 cups grape tomato (, cut in half (~400g / 14oz))","500g / 4 cups green papaya (, shredded, TIGHTLY packed cups (~1 medium, 2/3 large, Note 5))","1/2 cup Thai basil leaves (Note 6)"],"purpose":"Green Papaya Salad:"}]', '[{"title":"Crush peanuts","description":"Place peanuts in a mortar and pestle. Pound lightly to break them up into largish pieces, not into powder. Transfer to bowl.","images":[],"step":1},{"title":"Garlic and chilli paste","description":"Place garlic and chilli in the mortar. Pound into a paste. Add shrimp and pound to crush them – no need to grind them to a paste.","images":[],"step":2},{"title":"Dressing","description":"Stir in palm sugar, lime and fish sauce until sugar dissolves. Pour Dressing into a large bowl.","images":[],"step":3},{"title":"Bruise snake beans","description":"Add snake beans to mortar (in batches if needed). Pound to bruise, split and soften (they are raw, so they need to be bashed to soften). Add to Dressing.","images":[],"step":4},{"title":"Crush tomato","description":"Grab handfuls of tomato, crush with your hands then add into the bowl.","images":[],"step":5},{"title":"Add papaya","description":"Add papaya and 3/4 of the peanuts. Toss well with 2 wooden spoons or tongs.","images":[],"step":6},{"title":"Serve immediately (Note 7)","description":"Once everything is coated in Dressing, immediately pile up onto plates. Spoon over some dressing (there will be a bit of dressing still left in the bowl, that''s normal). Garnish with Thai basil leaves, sprinkle with remaining peanuts. Serve immediately (Note 7).","images":[],"step":7}]', '["fish","shellfish"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["lunch"],"cuisine":["Thai"],"categories":["asian-takeout","cuisines","dietary","gluten-free-recipes","iconic-dishes","salad-recipes-main-course","side-salads","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d1eece5a9055', 'en', 'US', 'Spinach French Onion Cob Dip', 'Recipe video above. Australia''s favourite dip!! This retro classic is a French onion dip made using a packet soup mix with spinach stirred through, served in a hollowed out cob bread loaf.Don''t even think about making this from scratch - that is not the Australian way!Use the bread scooped out for dipping, and look forward to the end when the dip is all gone and everybody rips into the dip-soaked bread bowl!', 'https://www.recipetineats.com/tachyon/2026/06/Spinach-French-Onion-Cob-Dip-4.jpg', 10, 0, 190, 12, '[{"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_cream_cheese", "quantity": {"value": 250.0, "unit": "block of 250g"}}, {"id": "ing_sour_cream", "quantity": {"value": 1.2, "unit": "tub of 250g"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.188, "unit": "jar of 400g"}}, {"id": "ing_spinach", "quantity": {"value": 250.0, "unit": "bag of 250g"}}, {"id": "ing_cob_loaf_preferably_sourdough_or_other_shape_loaf_about_25cm_wide", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 packet (40g/1.4oz) French onion soup mix powder, ( full salt (not low salt))","250g/8 oz cream cheese (, full fat)","300g/ 10oz sour cream (, full fat (or 250g/8oz tub + top up with yogurt or extra mayo))","1/2 cup mayonnaise (, whole-egg or Kewpie)","250g/8 oz frozen chopped spinach (, thawed (I microwave), excess water squeezed out with hands (Note 1))","1 cob loaf (crusty round bread), preferably sourdough, or other shape loaf, about 25cm/10oz wide (Note 2)"]},{"ingredients":["Artichokes, chopped water chestnuts, green onion, bacon, garlic, shredded cheese, jalapeño (for zing!)"],"purpose":"Extra add-in suggestions"}]', '[{"description":"Warm cream cheese then mix well to soften. Mix in mayo, sour cream and soup, then spinach. Fridge 3 hours, serve in bread bowl!","images":[],"step":1},{"title":"Soften cream cheese","description":"Put the cream cheese in a microwave-proof bowl and use a wooden spoon to roughly break it up into 8 or so chunks. Microwave on high for ~30 seconds then mix well until it is soft and loose, like sour cream.","images":[],"step":2},{"title":"Mix","description":"Add the sour cream, mayonnaise and soup powder, mix well. Then stir in spinach.","images":[],"step":3},{"title":"Fridge 3 hours","description":"Refrigerate, covered, for 3 hours (or overnight) to let the flavours meld.","images":[],"step":4},{"title":"Bread bowl","description":"Using a bread knife, cut a lid off the bread (about 2.5cm/1\" thick). Cut around the inside of the loaf, leaving a 2cm/0.8\" border and base. Score the bread inside the ring into 2.5cm/1\" squares, then pull the pieces out with your fingers to create a bread bowl.","images":[],"step":5},{"title":"Serve","description":"Take it out of the fridge 1 hour prior to serving to take the chill out and loosen (if needed, warm slightly in microwave). Give it a good mix, pour into the bowl and serve with the bread pieces on the side for dipping. I recommend providing extra dippers (crackers, chips - my favourite is crinkle cut plain potato chips) as there is more dip than bread!","images":[],"step":6},{"description":"Warm baked version","images":[],"step":7},{"description":"Loosely wrap the dip filled bread with foil and bake for 30 minutes at 180°C/350°F (160°C fan-forced). Olive oil spray bread pieces and season with pinch of salt. Scatter around the unwrapped cob dip and bake for a further 15 minutes or until the bread pieces are lightly browned. Serve warm!","duration":30,"images":[],"step":8}]', '["egg","gluten","milk"]', '["low_calorie"]', '{"mealType":["main_course"],"cuisine":["Australian"],"categories":["australia-day","dip-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a612eb324787', 'en', 'US', 'Greek Zucchini Tots', 'Recipe video above. These tasty bites are from the Greek Island of Alonnisos, adapted from the Courgette / Zucchini Rissoles recipe in The Food and Cooking of Greece cookbook. Such a great way to use the humble zucchini to make something fabulous that''s meal worthy and great to pass around at a party!Traditionally they''re deep fried but I like to make them in the oven (handy, healthier) and make them tater-tot (potato gem) shapes. But you can make them any shape you want!', 'https://www.recipetineats.com/tachyon/2015/10/Greek-zucchini-tots_0-1.jpg', 20, 30, 80, 30, '[{"id": "ing_zucchini", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 0.188, "unit": "loaf"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_green_onion", "quantity": {"value": 2.25, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_cheese", "quantity": {"value": 0.5, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.225, "unit": "tub of 500g"}}, {"id": "ing_mint", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["1 lb / 500 g zucchinis (courgettes)","1/4 tsp cooking salt / kosher salt"],"purpose":"Zucchini"},{"ingredients":["1/2 cup plain flour ((all-purpose flour), can sub gluten-free flour)","1 cup panko breadcrumbs ((Note 1), can sub gluten-free flour)","2 eggs","3/4 cup green onion (, finely sliced (white and pale green parts only))","1/2 cup parmesan cheese (, finely grated (I use store bought sandy type), can also use shredded cheddar or tasty cheese)","1 tbsp dried oregano (or 2 teaspoon other dried herbs)","2 garlic cloves (, minced)","1/4 tsp cooking salt / kosher salt","150 g / 5 oz Greek feta cheese (, crumbled)"],"purpose":"Batter"},{"ingredients":["Olive oil spray","Lemon wedges and oregano leaves (, optional garnishes)"],"purpose":"Cooking and serving"},{"ingredients":["3/4 cup plain Greek yoghurt (, or any plain unsweetened yogurt)","1 tbsp fresh mint (, finely chopped)","1/2 tbsp lemon juice","1/2 tbsp extra virgin olive oil (or more)","1/4 tsp each salt and pepper"],"purpose":"Minted Yoghurt (optional)"}]', '[{"description":"Preheat oven to 200°C/390°F (180°C fan-forced)","images":[],"step":1},{"title":"Sweat zucchini","description":"Grate the zucchini using a standard box grater. Place into a large colander, sprinkle with the salt, toss with your fingers and leave to sweat for 30 minutes.","duration":30,"images":[],"step":2},{"title":"Squeeze out liquid","description":"Working a handful at a time, squeeze out the excess water (as much as you can) and place the zucchini in a bowl.","images":[],"step":3},{"title":"Tots batter","description":"Add the Batter ingredients except the feta and mix well to combine. Add the feta and gently stir through.","images":[],"step":4},{"title":"Form tots","description":"Dollop heaped tablespoons 2 trays lined with baking paper / parchment paper (I get 29 in total). Then use your fingers to shape them into cylinder \"tater-tot / potato gem\" shapes.","images":[],"step":5},{"title":"Bake","description":"Spray generously with oil. Bake for 30 minutes, swapping the trays at around 20 minutes (for extra golden, spray again with oil), or until golden brown and a crunchy crust forms on the surface. The tray on the bottom might need a few extra minutes.","duration":30,"images":[],"step":6},{"description":"Serve with Minted Yogurt, lemon wedges and sprinkled with fresh oregano leaves if using.","images":[],"step":7},{"description":"Mix together ingredients and set aside for at least 10 minutes before serving.","images":[],"step":8}]', '["egg","gluten","milk"]', '["keto_friendly","low_calorie","vegetarian"]', '{"mealType":["snack","breakfast","dinner","lunch"],"cuisine":["Greek"],"categories":["australia-day","finger-food","fritters-tots-and-similar","greek-recipes","mediterranean-recipes","side-dishes","super-bowl-party-food","vegetarian-recipes","zucchini-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_01e0d6003f68', 'en', 'US', 'Prawn cocktail mini tacos (shrimp)', 'Recipe video above. Prawn cocktails, in canapé form! These one-bite mini tacos are fantastic finger food, and you’ll love the nifty trick for making the miniature taco shells - just use an upside-down muffin tin!Fill with anything chopped small enough to fit - try Jalapeño chicken, spicy salmon, Thai chicken salad or even old school taco beef! In the spirit of summer here in Australia (and an attempt to be grown-up cocktail party canapé worthy), I''ve gone for prawn cocktail with a classic Marie Rose sauce.', 'https://www.recipetineats.com/tachyon/2025/01/Prawn-cocktail-mini-tacos_0.jpg', 25, 12, 67, 17, '[{"id": "ing_tortillas", "quantity": {"value": 6.0, "unit": "pack of 8"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_shrimp", "quantity": {"value": 0.22, "unit": "kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.15, "unit": "jar of 400g"}}, {"id": "ing_ketchup", "quantity": {"value": 0.03, "unit": "bottle of 500g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_cream", "quantity": {"value": 0.01, "unit": "carton of 250ml"}}, {"id": "ing_es_of_tabasco", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.016, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.016, "unit": "jar of 40g"}}, {"id": "ing_corn", "quantity": {"value": 6.0, "unit": "can of 400g"}}, {"id": "ing_chives", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_salmon_fillets", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_beans", "quantity": {"value": 0.003, "unit": "can of 400g"}}]', '[{"ingredients":["6 corn tortillas (~13cm / 3\" wide (Note 1 on flour tortillas))","1/4 tsp cooking salt / kosher salt (halve for table salt)","Olive oil spray"],"purpose":"Mini tacos:"},{"ingredients":["220g/7 oz cooked prawns/shrimp, peeled (ie 500g/1 lb whole cooked in shell, then peel yourself, Note 2)"],"purpose":"Prawns:"},{"ingredients":["4 tbsp mayonnaise (, preferably whole egg, or Kewpie (Note 3))","1 tbsp ketchup (or Aussie tomato sauce)","1 tsp Worcestershire sauce","1/2 tsp horseradish cream (, or better yet fresh horseradish (Note 4))","2 dashes of tabasco (, for touch of spice (optional))","1/8 tsp cayenne pepper (, for touch of spice (optional))","1/8 tsp garlic powder (or small garlic clove pressed using garlic crusher)","1 tbsp cornichons ((or dill pickle), finely chopped)"],"purpose":"Prawn cocktail sauce:"},{"ingredients":["1 tbsp chives (, finely sliced (or parsley))","Fancy options - salmon roe, caviar (not pictured)","Dried black beans or rock salt (, to keep upright when serving (optional, Note 5))"],"purpose":"Garnish/serving:"}]', '[{"description":"Abbreviated recipe:","images":[],"step":1},{"description":"Cut 17 x 6cm/2.4\" rounds, microwave to soften, oil and salt, press into upside muffin tin. Bake 12 minutes, cool in tin. Fill!","images":[],"step":2},{"description":"Crispy mini taco shells:","images":[],"step":3},{"description":"Preheat the oven to 180°C/350°F (160°C fan-forced). Get a standard 12 hole muffin tin.","images":[],"step":4},{"description":"Cut circles from the tortillas using a 6cm / 2.4\" cutter. (Note 6 on using offcuts)","images":[],"step":5},{"title":"Warm","description":"Spread half on a dinner plate and microwave for 30 seconds on high (makes them pliable). Spray the warm tortillas lightly with oil, sprinkle with half the salt.","duration":0.5,"images":[],"step":6},{"title":"Wedge","description":"Turn the muffin tin upside down. Wedge the tortillas salt side down between the muffin tin holes - they fold into taco shapes! Repeat with remaining rounds.","images":[],"step":7},{"description":"Spray the surface of the tortillas lightly with oil (no salt).","images":[],"step":8},{"description":"Bake for 12 minutes, or until quite golden and crispy. Cool in the muffin tin so they set. (Stays crisp 2 days!)","duration":12,"images":[],"step":9},{"description":"Prawn cocktail filling:","images":[],"step":10},{"description":"Dice the prawns into small 5mm / 0.2\" cubes (for large, cut in half horizontally, lengthwise then chop - see video).","images":[],"step":11},{"description":"Mix the Marie Rose sauce in a bowl. Then stir the prawns through, just before assembling.","images":[],"step":12},{"description":"Fill taco shells with prawn cocktail filling, sprinkle with chives. To keep them upright, place on a bed of rock salt or dried beans for serving.","images":[],"step":13},{"description":"Pass around, bask in praise, be coy when people ask how you made those marvellous mini taco shells!","images":[],"step":14}]', '["egg","fish","gluten","milk","shellfish"]', '["keto_friendly","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["australia-day","dietary","finger-food","gluten-free-recipes","prawns-shrimp","seafood-recipes","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6a8ca80c1883', 'en', 'US', 'Nando''s Peri Peri Chicken Burgers', 'Recipe video above. This is my copycat of Nando''s famous Peri Peri Chicken Burgers! Chicken marinated in a homemade Peri Peri sauce, seared for an authentic char, piled onto warm buns and slathered with a homemade "Perinaise" (Peri Peri Mayonnaise sauce). This is moreish, burger perfection, better than take-out!Serve with French fries or wedges for a real-deal Nando''s experience at home. Excellent for gatherings - marinade large batches of chicken, cook on the BBQ, set up a DIY burger station!', 'https://www.recipetineats.com/tachyon/2015/11/Nandos-Peri-Peri-Chicken-Burger_9.jpg', 15, 15, 210, 4, '[{"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_oil", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_vinegar", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.75, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_drops_red_food_colouring", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_peri_peri_sauce", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.188, "unit": "jar of 400g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.15, "unit": "tub of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_chicken_breast", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}]', '[{"ingredients":["1 - 3 birds eye red chilies (1 is very mild, 3 is mildly spicy) (Note 1)","1 medium red capsicum / bell pepper (, roughly cut into 1.5cm / 1/2\" pieces)","5 garlic cloves (, peeled, whole)","3 tbsp vegetable or canola oil (, or other plain flavoured oil)","4 tbsp malt vinegar (Note 2)","2 tbsp smoked paprika (substitute regular / sweet paprika)","1 tbsp dried oregano","2 tsp onion powder (substitute garlic powder)","1 1/2 tsp white sugar","1 1/2 tsp cooking salt / kosher salt","3 drops red food colouring (optional, Note 3)"],"purpose":"Peri Peri Sauce/Marinade"},{"ingredients":["3 tbsp Peri Peri Sauce (above)","1/2 cup whole egg mayonnaise (or other mayonnaise)","1/4 cup sour cream (or yoghurt)"],"purpose":"Perinaise"},{"ingredients":["2 tbsp olive oil","4 chicken breasts or chicken thigh fillets (, skinless boneless (each large enough for a burger))","4 soft rolls (, split and lightly toasted (if desired))","2 tomatoes (, sliced)","Lettuce of choice"],"purpose":"Burgers"}]', '[{"title":"Prepare chicken breast","description":"If using breast, pound to 1 cm / 0.4\" even thickness (cover with go-between or freezer bags, use a meat mallet or rolling pin). Then trim each chicken piece so it is a bit larger than the buns (factor in 20% shrinkage when it cooks).","images":[],"step":1},{"title":"Peri Peri Sauce","description":"Put the Per Peri Sauce ingredients in a jug and blitz until smooth using a stick blender, or other appliance of choice (food processor, blender, NutriBullet).","images":[],"step":2},{"title":"Marinade chicken","description":"Pour 1/2 cup of the sauce into a bowl or ziplock bag. Add the chicken and turn to coat. Marinate for at least 3 hours, or up to 24 hours, in the fridge.","images":[],"step":3},{"title":"Perinaise","description":"Mix together the Perinaise ingredients. Set aside.","images":[],"step":4},{"title":"Cook chicken","description":"Heat 1 tablespoon of olive oil in a fry pan over medium / medium-high heat, OR brush BBQ grill with oil then heat. Cook breast for 3 minutes on each side, thighs for 4 minutes (in batches, if they won''t fit in the pan), lowering the heat as needed if they are charring too much (char = legit!).","duration":3,"images":[],"step":5},{"title":"Rest","description":"Remove the chicken onto a plate, loosely cover with foil and rest for 5 minutes. (Meanwhile, toast the rolls)","duration":5,"images":[],"step":6},{"title":"Assemble","description":"To make the burgers, spread the base of a roll with Peri-naise. Top with lettuce, tomato then chicken, then top with more Peri-naise and extra Peri Peri sauce if desired!","images":[],"step":7}]', '["egg","milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Portuguese"],"categories":["australia-day","burger-recipes","chicken-breast-recipes","chicken-recipes","dietary","gluten-free-recipes","grilling-ideas-and-recipes","mediterranean-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a0043c593ab3', 'en', 'US', 'Cheesymite Scrolls (Cheese & Vegemite!)', 'Recipe video above. This is an unapologetic copycat recipe of the Bakers Delight Cheesymite Scrolls - but better, because I use butter and they use flavourless oil! With pillowy soft white bread, Vegemite and cheese, the dough is easy to work with and forgiving to make. This makes 12 good sized scrolls and you''ll save a bundle - $12.50 for this recipe compared to $54 to buy a dozen.See Note 7 for food processor option. If using cups to measure the cheese, make sure to tightly pack it else you''ll be short (devastating!).', 'https://www.recipetineats.com/tachyon/2024/08/Cheesymite-scrolls_0.jpg', 25, 35, 60, 12, '[{"id": "ing_bread", "quantity": {"value": 0.75, "unit": "loaf"}}, {"id": "ing_yeast", "quantity": {"value": 3.0, "unit": "pack of 5 sachets"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_vegemite", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_cheese", "quantity": {"value": 5.0, "unit": "block of 250g"}}]', '[{"ingredients":["4 cups bread flour (, substitute plain/all-purpose flour (Note 1))","3 tsp instant yeast (rapid-rise yeast) (Note 2)","2 tsp white sugar","1 1/4 tsp cooking salt ((kosher salt), halve for table salt)","1 1/2 cups+ 2 tbsp warm milk (full or low fat) (Note 3)"],"purpose":"Dough:"},{"ingredients":["50g/ 3 tbsp salted butter (, softened)","3 tbsp Vegemite (Note 4)","5 cups (500 g) Colby cheese (, freshly shredded (or cheddar, Monterey Jack) (Note 5))"],"purpose":"Vegemite & cheese:"}]', '[{"description":"Abbreviated recipe","images":[],"step":1},{"description":"Mix dry ingredients, add milk, knead 5 min. Rise until doubled (1.5 hours). Punch, roll out to 48 x 28 cm / 11 x 19” rectangle. Spread with butter, Vegemite then 300g cheese. Roll, cut into 12, put in lined pan, rise 30% (30 min). Top with remaining cheese.","images":[],"step":2},{"description":"Bake 25 minutes at 180°C/350°F (160°C fan), rotate, bake 10 minutes 200°C/375°F (180°C fan) - keep an eye on it. Cool 10 min, eat!","images":[],"step":3},{"title":"Check yeast","description":"If your yeast is old or you weren''t storing it in the fridge, check it''s still good, see Note 6.","images":[],"step":4},{"title":"Make dough","description":"Put the flour, yeast, sugar and salt in the bowl of a stand mixer fitted with a dough hook. Briefly mix to combine. Add the milk then mix on low until you no longer see flour. Then beat, starting on low then increasing to medium partway through, for 5 minutes until the dough is smooth (see video for before/after visuals). (Note 8)","duration":5,"images":[],"step":5},{"title":"Rise #1","description":"Shape the dough into a ball then put it back in the bowl. Cover with cling wrap. Let it rise in a warm place for 1 1/2 hours or until it doubles in size (see steps in post for more guidance).","images":[],"step":6},{"title":"Roll out","description":"Punch the dough to deflate in the bowl. Lightly flour a work surface, turn the dough out then use your hands to roughly shape it into a rectangle. Then roll out into a 48 x 28 cm / 11 x 19”rectangle using a rolling pin.","images":[],"step":7},{"description":"Spread the dough with butter then with Vegemite. Sprinkle the whole area evenly with 3 cups (300g) of the cheese.","images":[],"step":8},{"title":"Cut","description":"Roll up into a log then cut into 12 even pieces.","images":[],"step":9},{"description":"Pre-heat the oven to 180°C/350°F (160°C fan-forced). Lightly grease a 23 x 33cm / 9 x 13″ pan with butter. Then line with baking paper with overhang (so you can lift the slab out later).","images":[],"step":10},{"title":"Rise #2","description":"Place the scrolls into the pan, evenly spaced apart. Spray a piece of cling wrap lightly with oil then cover the pan. Let the scrolls rise in a warm place for 30 minutes or until they expand/rise by about 30-50%.","duration":30,"images":[],"step":11},{"title":"Bake","description":"Top the scrolls with the remaining cheese. Bake for 25 minutes. Then rotate the pan and bake for a further 10 minutes at 200°C/375°F (180°C fan-forced) or until the cheese on the surface of the scrolls around the edge of the pan are light golden.","duration":25,"images":[],"step":12},{"title":"Rest","description":"Cool in the pan for 5 minutes. Use the paper overhang to lift the slab onto a cooling rack then cool for a further 5 minutes. Peel the scrolls apart then devour! Best eaten warm. 20 seconds in the microwave!","duration":5,"images":[],"step":13}]', '["gluten","milk"]', '["high_protein","vegetarian"]', '{"mealType":["snack"],"cuisine":["Australian"],"categories":["australia-day","breads","snacks"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6dbba6d0b9a5', 'en', 'US', 'Melting Moments', 'Recipe video above. These special cookies are an Australian cafe favourite. Shortbread cookies joined with lemon buttercream frosting, they are beautifully buttery, lemony and true to their name, literally "melt in your mouth" unlike any other cookie I know!My cookies are generous sized because I like them big: 6cm / 2.4" diameter, 3.5-4cm / 1.5" thick. I wouldn''t go any larger (too much cookie) but feel free to go smaller!', 'https://www.recipetineats.com/tachyon/2023/11/Melting-moments_5.jpg', 20, 15, 35, 14, '[{"id": "ing_butter", "quantity": {"value": 250.0, "unit": "block of 250g"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.188, "unit": "pack of 400g"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_passionfruit_pulp", "quantity": {"value": 0.06, "unit": "kg"}}]', '[{"ingredients":["250g (2 sticks + 1 tbsp) unsalted butter (, softened (Note 1))","1 tsp vanilla extract","1/2 cup soft icing sugar / powdered sugar (, sifted (not PURE icing sugar, Note 2))","1 1/2 cups plain / all-purpose flour","1/2 cup cornflour / cornstarch"],"purpose":"Melting moments:"},{"ingredients":["100g / 7 tbsp unsalted butter (, softened)","2 cups soft icing sugar / powdered sugar (, sifted (not PURE icing sugar, Note 2))","2 tsp lemon zest","1 tsp lemon juice"],"purpose":"Lemon icing:"},{"ingredients":["80g / 6 tbsp unsalted butter (, softened)","2 cups soft icing sugar / powdered sugar (, sifted (not PURE icing sugar, Note 2))","4 tbsp fresh passionfruit pulp (, (not canned, too sweet))","1 tbsp lemon juice"],"purpose":"Passionfruit icing:"}]', '[{"description":"Preheat oven to 180°C / 350°F (160°C fan-forced). Line 2 trays with paper.","images":[],"step":1},{"title":"Cream butter","description":"Place butter, vanilla and icing sugar in a bowl. Beat for 1 minute until smooth and fluffy (start on low to avoid an icing sugar cloud-storm).","duration":1,"images":[],"step":2},{"title":"Dry in 3 lots","description":"Stir in cornflour and flour in 3 lots using a rubber spatula. (ie add 1/3 of flour + cornflour, stir in, repeat twice more).","images":[],"step":3},{"description":"Scoop 1 tablespoon of the mixture onto the trays (cookie scoop handy here), then roll into balls using lightly floured hands (to prevent it from sticking). You should have 24 - 28 balls.","images":[],"step":4},{"title":"Bake","description":"Press down into 1 cm / 0.4\" thickness using a fork. Bake for 15 minutes, switching the trays at the 10 minute mark. Fully cool on trays.","duration":15,"images":[],"step":5},{"title":"Sandwiching","description":"Pipe frosting onto half the melting moments, then sandwich with remaining cookies.","images":[],"step":6},{"title":"Set","description":"Refrigerate for 1 hour to set the frosting (else it''s so soft, it squirts out!). Then remove from the fridge 30 minutes prior to serving.","images":[],"step":7},{"title":"Cream butter","description":"Place butter in a bowl and beat with an electric mixer on medium high for 1 minute until smooth and fluffy. Add 1/3 of the icing sugar, then beat in starting on low and increasing to high (to avoid snow-storm!). Repeat another 2 times.","duration":1,"images":[],"step":8},{"title":"Beat 2 minutes","description":"Add lemon zest and juice. Then beat on high for 2 minutes until fluffy. Transfer to piping bag, snip end off to make a 1cm / 1/2\" hole. Use per recipe.","duration":2,"images":[],"step":9},{"description":"Passionfruit icing:","images":[],"step":10},{"description":"Same method as above for lemon icing.","images":[],"step":11}]', '["gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Australian"],"categories":["australia-day","baking-recipes","cookies","dessert-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2b84323b4311', 'en', 'US', 'Moroccan lamb backstrap', 'Recipe video above. Love lamb backstrap - beautifully tender with a relatively mild lamb flavour. Pairs 100% perfectly with a bold, earthy Moroccan Ras el hanout spice blend. Cook this lean, delicate meat gently - keep it blushing pink for optimum juiciness!Serve on a bed of Pearl couscous salad or traditional couscous for a fabulous share platter. Cook on the stove or BBQ on warm summer days!', 'https://www.recipetineats.com/tachyon/2023/01/Moroccan-lamb-backstraps_1-1.jpg', 10, 10, 20, 4, '[{"id": "ing_lamb", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_cumin", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_ginger", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.025, "unit": "bunch"}}, {"id": "ing_powder", "quantity": {"value": 3.75, "unit": "jar"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.225, "unit": "tub of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_paprika", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_pears", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_couscous", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_more_side_suggestions_in_post", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["2 x 250g/8oz lamb backstraps (Note 1)","1 tbsp extra virgin olive oil (rubbing)","1 1/2 tbsp extra virgin olive oil (cooking)"]},{"ingredients":["1 1/2 tsp cooking/kosher salt","3/4 tsp cumin powder","3/4 tsp ground ginger","3/4 tsp black pepper","1/2 tsp allspice powder","1/4 tsp cinnamon powder","1/4 tsp coriander powder","1/8 tsp clove powder"],"purpose":"Moroccan spice mix (ras el hanout, Note 2):"},{"ingredients":["3/4 cup Greek yoghurt","1 tbsp lemon juice","1 tbsp olive oil (, plus extra swish for drizzling)","1/4 tsp each salt and pepper","Pinch of sumac or paprika (, optional garnish)"],"purpose":"Yogurt sauce (for serving):"},{"ingredients":["Pearl couscous salad (pictured in post)","Classic couscous","More side suggestions in post"],"purpose":"Sides (optional):"}]', '[{"title":"Yogurt sauce","description":"Mix ingredients. Refrigerate until required.","images":[],"step":1},{"title":"Moroccan spice mix","description":"Mix the spices in a small bowl.","images":[],"step":2},{"title":"Coat backstrap","description":"Pat the backstraps dry with a paper towel then rub all over with 1 tbsp olive oil. Sprinkle the spice mix on the lamb backstraps - use it all! Set aside for 1 hour to marinate (if time permits, can skip).","images":[],"step":3},{"title":"Cook","description":"Heat 1 1/2 tablespoons olive oil in a large skillet over medium high heat. Cook the lamb backstops for 4 minutes on each side, or until the core temperature is 59°C/138°F.","duration":4,"images":[],"step":4},{"title":"Rest","description":"Transfer onto a rack set over a tray (or just a plate) to rest for 3 minutes. Cut into 0.75 - 1 cm / 1/4 - 1/3\" thick slices. Serve with yogurt sauce!","duration":3,"images":[],"step":5}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern","Moroccan"],"categories":["australia-day","easter-mains","easter-recipes","lamb","lamb-recipes","mains","moroccan"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_29ab4ee84863', 'en', 'US', 'Truly Crispy Oven Baked Buffalo Wings', 'Recipe video above. This recipe uses a genius technique discovered by Cook''s Illustrated to make chicken wings in the oven that come out so crispy that it''s hard to believe they aren''t deep fried. Tossed in a classic Buffalo sauce and served with a side of blue cheese dip and celery sticks and you have one of the most genius food combinations this world has ever seen! Full FAQ is available in the original Crispy Baked Wings (scroll below recipe).', 'https://www.recipetineats.com/tachyon/2019/01/Baked-Buffalo-Wings_0.jpg', 15, 70, 85, 8, '[{"id": "ing_chicken", "quantity": {"value": 1.814, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 5.0, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_hot_sauce", "quantity": {"value": 0.833, "unit": "bottle of 150ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 0.5, "unit": "block of 250g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.3, "unit": "tub of 250g"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.094, "unit": "jar of 400g"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_milk", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_beer", "quantity": {"value": 1.0, "unit": "bottle of 330ml"}}]', '[{"ingredients":["4 lb / 2kg chicken wings, wingettes & drumettes (Note 1)","5 teaspoons baking powder (NOT baking soda / bi-carb soda) (Note 2)","3/4 teaspoons kosher salt / cooking salt (not table salt, too fine)"],"purpose":"Crispy Baked Wings"},{"ingredients":["4 tbsp (60g) unsalted butter, melted","1/2 cup Frank’s Original Red Hot Sauce (Note 3)","1 tbsp brown sugar","1/4 tsp kosher salt / cooking salt"],"purpose":"Sauce"},{"ingredients":["1/2 cup crumbled blue cheese, softened (I use gorgonzola)","1/2 cup sour cream","1/4 cup mayonnaise (, preferably whole-egg)","1 clove small garlic (, minced)","1 - 3 tbsp milk","2 tbsp lemon juice","1/2 tsp kosher salt / cooking salt","Black pepper"],"purpose":"Blue Cheese Dip"},{"ingredients":["Celery sticks","Lots of beer!"],"purpose":"To Serve"}]', '[{"description":"Crispy Baked Wings","images":[],"step":1},{"title":"Dry overnight (optional)","description":"If you plan ahead, lay the wings on a rack on a rimmed baking tray and let them dry uncovered in the fridge overnight. Alternatively, pat them dry with paper towels.","images":[],"step":2},{"description":"Preheat the oven to 250°F/120°C (all oven types). Put one oven shelf in the lower quarter of the oven and one in the top quarter.","images":[],"step":3},{"description":"Line the tray with foil. Put a rack on the tray then spray the rack with oil.","images":[],"step":4},{"title":"Toss wings","description":"Place the wings in a large bowl. Sprinkle over baking powder and salt. Use hands to toss well (or shake in ziplock bag) to coat wings evenly.","images":[],"step":5},{"title":"Bake 30 minutes on low temp","description":"Place the wings skin side up on the rack (ok if snug, they shrink). Bake on the lower shelf in the oven for 30 minutes.","duration":30,"images":[],"step":6},{"title":"Bake 40 minutes on high","description":"Move the tray up to the higher shelf and turn the oven up to 425°F / 220°C (all oven types). Bake for a further 40 to 50 minutes, rotating the tray halfway through. The wings do not need to be turned over. They are ready when dark golden brown and the skin is very crispy.","images":[],"step":7},{"title":"Toss in sauce","description":"Transfer the wings into a large bowl. Pour over sauce and toss to coat. (Alternatively, serve wings plain with Buffalo Sauce for dipping).","images":[],"step":8},{"description":"Serve immediately with Blue Cheese Dip (for both wings and celery sticks dunking)!","images":[],"step":9},{"description":"Whisk together the Sauce ingredients until the sugar is melted. Keep warm or reheat just prior to using.","images":[],"step":10},{"description":"Blue Cheese Dip","images":[],"step":11},{"description":"Mash the blue cheese with sour cream until smooth (or to your taste).","images":[],"step":12},{"description":"Add remaining ingredients and mix well until combined, using milk to get it to the consistency you want. Store in the fridge until required. Remove from the fridge 15 minutes before serving.","images":[],"step":13}]', '["egg","milk"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["main_course"],"cuisine":["American"],"categories":["australia-day","chicken-recipes","chicken-wings","dietary","dinner-tonight","gluten-free-recipes","main-dishes","most-popular","quick-and-easy","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1cb692c4bbf2', 'en', 'US', 'Mini Pavlovas', 'Recipe video above. Mini Pavs are so cute and so practical! Easier and safer to make and transport than a large traditional pav, they have a delicate crisp shell and the signature marshmallow centre inside with slightly chewy edges - just as they should! Top with whipped cream and fruit of choice!', 'https://www.recipetineats.com/tachyon/2022/12/Mini-Pavs-final_9.jpg', 25, 90, 115, 12, '[{"id": "ing_egg", "quantity": {"value": 13.333, "unit": "carton of 12"}}, {"id": "ing_sugar", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.031, "unit": "pack of 400g"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.5, "unit": "carton of 250ml"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_cream", "quantity": {"value": 1.5, "unit": "carton of 250ml"}}, {"id": "ing_strawberries", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_blueberries", "quantity": {"value": 1.0, "unit": "punnet of 125g"}}, {"id": "ing_mint", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sugar", "quantity": {"value": 0.188, "unit": "kg"}}]', '[{"ingredients":["160 ml / 2/3 cup egg whites (5 - 6 large eggs) (Note 1)","1 1/4 cups caster sugar (superfine sugar)","2 1/2 tsp cornflour / cornstarch (Note 2)","1 tsp white vinegar (Note 2)"],"purpose":"Mini Pavlovas:"},{"ingredients":["1 1/2 cups heavy/thickened cream ((whipping cream), COLD)","3 tbsp caster sugar / superfine sugar","1 tsp vanilla extract","Stabilise the whipped cream"],"purpose":"Whipped cream:"},{"ingredients":["Strawberries, mangoes ( - diced into 1cm / 1/3\" cubes)","Blueberries, raspberries, kiwi sliced, passionfruit pulp","Small mint sprigs","Icing sugar / powdered sugar (, for dusting)"],"purpose":"Toppings – choose:"}]', '[{"title":"Egg whites","description":"Separate the egg yolks from egg whites while fridge cold (it''s easier). Measure out 2/3 cup (160 ml) egg whites then set aside to come to room temperature for 30 minutes (fluffs better at room temp).","duration":30,"images":[],"step":1},{"description":"Preheat oven to 150°C / 325°F (all oven types).","images":[],"step":2},{"title":"Add sugar","description":"In a stand mixer or using an electric beater, beat the egg whites on high for 1 minute. While still beating, add the sugar 1 dessert spoon at a time.","duration":1,"images":[],"step":3},{"title":"Beat 8 minutes","description":"Continue to beat for 8 minutes on high until it''s fluffy, glossy, and there are no sugar grains remaining when you rub a bit between your fingers. Add vinegar and cornflour then beat for a further 30 seconds.","duration":8,"images":[],"step":4},{"title":"Line tray","description":"Dab a bit on the corner of 2 trays then cover with baking paper (parchment).","images":[],"step":5},{"description":"Pipe mounds Transfer meringue mixture into a large piping bag fitted with nozzle of choice. Pipe 12 - 13 mounds 6 - 7 cm / 2.5\" wide about 5 cm / 2\" tall. Use a spoon to flatten and make a slight dent on the surface to hold cream and fruit. Pavs should end up about 4 cm / 1.6\" high.","images":[],"step":6},{"title":"Bake 1 hour 30 minutes","description":"Place both trays in the oven, immediately turn oven DOWN to 110°C/225°F (100°C fan) and bake for 1 hour 30 minutes or until they are dry to touch. Keep baking if still sticky - exact times may vary. (Note 4)","images":[],"step":7},{"title":"Cool in oven","description":"Turn oven OFF and leave to fully cool for 4 hours or overnight around 10 hours (I usually do this).","images":[],"step":8},{"title":"Airtight container","description":"As soon as the pavs are fully cool, store in an airtight container in a cool, dry place until required. (Note 6)","images":[],"step":9},{"title":"Cream","description":"Beat cream ingredients in a large bowl on high until soft peaks form (1 minute using a stand mixer, 2 - 3 minutes with hand held beater). (Note: if making stabilised whipped cream, follow the steps for your chosen method).","images":[],"step":10},{"title":"Decorate","description":"Just before serving, spoon a big dollop of cream in the nest, top with fruit and dust with icing sugar if using.","images":[],"step":11}]', '["egg","milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Australian","New Zealand"],"categories":["australia-day","baking-recipes","bite-size-desserts","dessert-recipes","easter-baking-desserts","egg-white-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1c9eac8a44d2', 'en', 'US', 'Chicken Shawarma (Middle Eastern)', 'Recipe video above. The smell when this is cooking is outrageous! The marinade is very quick to prepare and the chicken can be frozen in the marinade, then defrosted prior to cooking. Best cooked on the outdoor grill / BBQ, but I usually make it on the stove. Serve with Yogurt Sauce or the Tahini sauce in this recipe. Add a simple salad and flatbread laid out on a large platter, then let everyone make their own wraps!', 'https://www.recipetineats.com/tachyon/2017/01/Chicken-Shawarma-Wrap_3.jpg', 10, 10, 20, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_cardamon", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_yogurt", "quantity": {"value": 1.0, "unit": "tub of 500g"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_hot_sauce", "quantity": {"value": 1.0, "unit": "bottle of 150ml"}}]', '[{"ingredients":["1 kg / 2 lb chicken thigh fillets (, skinless and boneless (Note 3))"]},{"ingredients":["1 large garlic clove (, minced (or 2 small cloves))","1 tbsp ground coriander","1 tbsp ground cumin","1 tbsp ground cardamon","1 tsp ground cayenne pepper (reduce to 1/2 tsp to make it not spicy)","2 tsp smoked paprika","2 tsp salt","Black pepper","2 tbsp lemon juice","3 tbsp olive oil"],"purpose":"Marinade"},{"ingredients":["1 batch Lemon yogurt sauce","4 - 5 flatbreads (Lebanese or pita bread orhomemade soft flatbreads)","Sliced lettuce (cos or iceberg)","Tomato slices","Red onion (, finely sliced)","Cheese (, shredded (optional))","Hot sauce of choice (optional)"],"purpose":"To Serve"}]', '[{"title":"Marinade chicken","description":"Combine the marinade ingredients in a large ziplock bag. Add the chicken, seal, the massage from the outside with your hands to make sure each piece is coated. Marinate 24 hours (minimum 3 hours).","images":[],"step":1},{"title":"Yogurt Sauce","description":"Combine the Yogurt Sauce ingredients in a bowl and mix. Cover and put in the fridge until required (it will last for 3 days in the fridge).","images":[],"step":2},{"title":"Preheat stove or BBQ","description":"Heat a large non-stick skillet with 1 tablespoon over medium high heat, or lightly brush a BBQ hotplate/grills with oil and heat to medium high. (See notes for baking)","images":[],"step":3},{"title":"Cook chicken","description":"Place chicken in the skillet or on the grill and cook the first side for 4 to 5 minutes until nicely charred. Turn and cook the other side for 3 to 4 minutes (the 2nd side takes less time).","duration":4.5,"images":[],"step":4},{"title":"Rest","description":"Remove chicken from the grill and cover loosely with foil. Set aside to rest for 5 minutes.","duration":5,"images":[],"step":5},{"description":"To Serve","images":[],"step":6},{"description":"Slice chicken and pile onto platter alongside flatbreads, Salad and the Yoghurt Sauce (or dairy free Tahini sauce from this recipe).","images":[],"step":7},{"description":"To make a wrap, get a piece of flatbread and smear with Yoghurt Sauce. Top with a bit of lettuce and tomato and Chicken Shawarma. Roll up and enjoy!","images":[],"step":8}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Arabic","Middle Eastern","Moroccan"],"categories":["australia-day","chicken-breast-recipes","chicken-recipes","cuisines","dietary","gluten-free-recipes","grilling-ideas-and-recipes","middle-eastern-recipes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_eba234227723', 'en', 'US', 'Greek Butterflied Lamb Leg', 'Recipe video above. This is a terrific, bold Greek marinade for lamb that both tenderises and infuses it with garlicky, herby, lemon flavours. Butterflied lamb leg is a fantastic way to enjoy lamb because the flattened shape means it can be cooked relatively quickly compared to roasting a whole leg. In fact, I think that butterflied lamb leg is one of the best cuts of lamb for the BBQ!', 'https://www.recipetineats.com/tachyon/2021/01/Butterflied-Lamb-Leg_0.jpg', 5, 25, 30, 8, '[{"id": "ing_lamb", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 1000.0, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 0.1, "unit": "net of 500g"}}, {"id": "ing_zest", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 0.1, "unit": "net of 500g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_greek_salad", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_tzatziki", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_more_ideas_listed_in_post", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["1.5 - 1.8kg / 3 - 3.6 lb butterflied (ie. boneless) lamb leg (Note 1)"]},{"ingredients":["1 tbsp dried oregano","3 large garlic cloves (, minced using garlic press)","2 tsp salt","1 tsp black pepper","1/3 cup fresh lemon juice","1 tbsp zest (= zest of 1 lemon)","1/2 cup olive oil"],"purpose":"Marinade:"},{"ingredients":["1 tbsp oil (for brushing BBQ or for stove sear)"],"purpose":"For cooking:"},{"ingredients":["Lemon (, for garnish)","Oregano leaves (, optional garnish as pictured)","Flatbreads or store bought pita breads","Greek Salad","Flatbreads or store bought pita breads","More ideas listed in post"],"purpose":"Serving options:"}]', '[{"description":"Mix marinade ingredients in a large ziplock bag.","images":[],"step":1},{"description":"Add lamb, massage bag well to get the marinade into all the meat cracks and crevices.","images":[],"step":2},{"description":"Seal bag and marinate for 24 hours (3 hours minimum).","images":[],"step":3},{"description":"Remove lamb from the fridge 1 hour prior to cooking (to take fridge chill out for more even cooking).","images":[],"step":4},{"description":"Brush grates with oil then preheat BBQ until very hot. (Takes a good 15 minutes, lid closed, with my basic gas BBQ).","images":[],"step":5},{"description":"Remove lamb from marinade and place on the grill, fat side down.","images":[],"step":6},{"description":"Cook for 12 minutes, then turn and cook the flesh side for 8 minutes, or until the internal temperature in the thickest part registers 57°C / 135°F for medium-rare or desired pull temperature (see Note 3).","duration":12,"images":[],"step":7},{"description":"Loosely cover with foil, and rest for 10 minutes before serving.","duration":10,"images":[],"step":8},{"description":"Stove/Oven (Note 2):","images":[],"step":9},{"description":"Preheat oven to 180°C/350°F (all oven types). Place a rack on a tray.","images":[],"step":10},{"description":"Cut lamb into 2 or 3 large pieces so it fits in your skillet.","images":[],"step":11},{"description":"Heat oil in skillet over medium-high heat. Sear until golden brown on both sides, around 2 - 3 minutes each side. (Note: It will not colour much more in the oven)","images":[],"step":12},{"title":"Roast for 22","description":"25 minutes, or until the thickest part registers 57°C / 135°F for medium-rare or desired pull temperature (see Note 3).","duration":23.5,"images":[],"step":13},{"description":"Remove from oven, loosely cover with foil, and rest for 10 minutes before serving.","duration":10,"images":[],"step":14},{"description":"Either slice it at the table, or slice prior to serving and pile onto a platter. Fabulous served with Greek Salad, Tzatziki and flatbreads, as pictured in post.","images":[],"step":15},{"title":"More side suggestions","description":"Lemon Rice, Mediterranean Rice Salad, Greek Chickpea Salad, Lemon Orzo Salad.","images":[],"step":16}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Greek"],"categories":["australia-day","easter-mains","easter-recipes","grilling-ideas-and-recipes","lamb","lamb-recipes","mains","roast-lamb","roasts"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b49cd69460b4', 'en', 'US', 'Homemade Rotisserie Doner Kebab Meat - beef or lamb!', 'Recipe video above. This is a homemade version of the giant punching bag size Doner kebab meats rotating on vertical rotisseries in kebab shops! It might be small, but what it lacks in size it makes up for in authenticity and flavour. Prepare to be amazed - it tastes JUST like the real deal (and your house will smell like a kebab shop!)Excellent food for gatherings - make ahead, wow factor, DIY wraps and economical.', 'https://www.recipetineats.com/tachyon/2020/07/Carving-Doner-Kebab-Meat-1.jpg', 20, 120, 140, 8, '[{"id": "ing_beef_mince", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_cinnamon", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 8.0, "unit": "loaf"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 6.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_hummus", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_tomato", "quantity": {"value": 6.0, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}]', '[{"ingredients":["1 kg / 2 lb lamb or beef mince (ground meat) (, preferably 15% fat (Note 1))","200g / 7oz streaky bacon (, roughly diced (Note 2))","1 onion (, diced (brown, yellow, white))","2 clove garlic (, roughly chopped)","1 tbsp vegetable oil (or olive oil (for frying))"]},{"ingredients":["1 tsp dried oregano","2 tsp ground cumin","2 tsp ground coriander","1/2 tsp cinnamon","3 tsp salt (, kosher/cooking salt (Note 3))","1 tsp black pepper"],"purpose":"Seasoning Spices:"},{"ingredients":["8 flatbreads (Lebanese bread authentic!)","1 iceberg lettuce (, finely shredded)","6 tomatoes (, halved and sliced)","2 red onions (, finely sliced)","Hummus","Yogurt sauce (, optional (recipe Note 8))","More Sauce options: chilli sauce/Sriracha (I use this), BBQ, sweet chilli, tomato sauce/ketchup","Extra options: tabbouleh, shredded cheese"],"purpose":"Doner Kebabs:"}]', '[{"title":"Mix beef or lamb with all the Spices","description":"mix well using your hands.","images":[],"step":1},{"description":"Cover and refrigerate 2 hours minimum, or up to 24 hours.","images":[],"step":2},{"description":"Preheat oven to 170°C/ 325°F (150°C fan).","images":[],"step":3},{"description":"Line baking pan with foil.","images":[],"step":4},{"description":"Check to ensure skewers are long enough to prop on the sides of the pan. (Note 5)","images":[],"step":5},{"description":"Place onion, bacon and garlic in a 8 cup/2L+ food processor. Blitz until it becomes a paste (video at 29 sec),~30 sec on high, scraping down sides as you go.","images":[],"step":6},{"description":"Add meat and blitz on low until it becomes a paste (video at 42 sec), scraping down sides (~1 min for powerful food processors, 2 min for less powerful). (Note 4)","images":[],"step":7},{"description":"Shape Doner Kebab Meat:","images":[],"step":8},{"description":"Turn meat out onto work surface. Wet hands with water, then shape into an even block 20cm/8\" long.","images":[],"step":9},{"description":"Place 2 x 60cm / 2 feet long pieces of foil overlapping each other by 1/3. (Note 6)","images":[],"step":10},{"description":"Place meat on the end of the foil, then roll it up, tightly wrapping it in the foil.","images":[],"step":11},{"description":"Twist the ends firmly to form a log 25cm/10\" long, then snip off excess foil. Roll into even log.","images":[],"step":12},{"description":"Thread skewers through the log.","images":[],"step":13},{"description":"Place log elevated in pan by propping skewers on the edge of the pan. (Note 7)","images":[],"step":14},{"description":"Cooking:","images":[],"step":15},{"description":"Cook for 1 1/2 hours, turning once after 1 hour, until the log reaches 70°C/160°F (up to 80°C/175°F is fine). The log is cooked at this point. (Note 9)","images":[],"step":16},{"description":"Remove foil from log but leave skewers in place.","images":[],"step":17},{"description":"Increase oven heat to 250°C/480°F, or as high as your oven can go if it can''t reach this.","images":[],"step":18},{"description":"Bake for 10 to 15 minutes, rotating once, until browned all over.","duration":12.5,"images":[],"step":19},{"description":"Shaving / pan frying (kebab shop style!):","images":[],"step":20},{"description":"Remove skewers then stand the meat upright.","images":[],"step":21},{"title":"Shave meat thinly","description":"carve as much as you intend to use.","images":[],"step":22},{"description":"Heat oil in a skillet over medium high heat. Cook shaved meat lightly coloured but still \"floppy\" (not crisped). Use immediately for Doner Kebabs!","images":[],"step":23},{"description":"Smear hummus on warmed flatbread. Top with lettuce, tomato, and onion.","images":[],"step":24},{"description":"Pile on Doner Kebab Meat. Drizzle with sauce(s) of choice.","images":[],"step":25},{"description":"Roll up tightly, wrap in foil if desired (to hold together). Grab and devour!","images":[],"step":26}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Turkish"],"categories":["australia-day","beef-mince-recipes","beef-recipes","cuisines","grilling-ideas-and-recipes","iconic-dishes","lamb-recipes","main-dishes","mains","middle-eastern-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8b91a54343e0', 'en', 'US', 'Greek Chicken Gyros with Tzaziki', 'Recipe video above. The marinade for the chicken is so sensational that I use it even when I''m not making Gyros! This is fantastic for entertaining because you can just lay it all out for guests to help themselves. The smell when the chicken is cooking is incredible - you can really smell the oregano and garlic!Recipe includes a Tzatziki, you can also use a Lemon Yogurt Sauce for a quicker option (make a double batch).', 'https://www.recipetineats.com/tachyon/2015/06/Greek-Chicken-Gyros_original-pics__8.jpg', 20, 6, 26, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.907, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1000.0, "unit": "pack of 3 heads"}}, {"id": "ing_vinegar", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.09, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.375, "unit": "tub of 500g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.375, "unit": "tub of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 1000.0, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}]', '[{"ingredients":["2 lb / 1 kg chicken thigh fillets (, boneless skinless)"]},{"ingredients":["3 large garlic cloves (, minced (~ 3 tsp))","1 tbsp white wine vinegar (or red wine or apple cider vinegar)","3 tbsp lemon juice","1 tbsp extra virgin olive oil","3 tbsp Greek yogurt (, preferably full fat)","1 1/2 tbsp dried oregano","1 tsp salt","Black pepper"],"purpose":"Marinade"},{"ingredients":["2 cucumbers (to make about 1/2 - 3/4 cup grated cucumber after squeezing out juice)","1 1/4 cups Greek yoghurt (, preferably full fat)","1 tbsp lemon juice","1 tbsp extra virgin olive oil (or more if you want richer)","1 garlic clove (, minced)","1/4 tsp salt","Black pepper"],"purpose":"Tzatziki"},{"ingredients":["3 tomatoes (, desseeded and diced)","3 cucumbers (, diced)","1/2 red spanish onion (, peeled and finely chopped)","1/4 cup fresh parsley leaves (optional)","Salt and pepper"],"purpose":"Salad"},{"ingredients":["4 to 6 pita breads or flat breads"],"purpose":"To Serve"}]', '[{"description":"Place the Marinade ingredients in a ziplock bag and massage to mix. Add the chicken into the ziplock bag and massage to cover all the chicken in the Marinade. Marinate for at least 2 hours, preferably 3 hours, ideally 12 hours and no longer than 24 hours.","images":[],"step":1},{"description":"Make the Tzatziki","images":[],"step":2},{"description":"Cut the cucumber in half lengthwise. Use a teaspoon to scrape the watery seeds out. Coarsely grate the cucumber using a box grater. Then wrap in paper towels or a tea towel and squeeze to remove excess liquid.","images":[],"step":3},{"description":"Place cucumber in a bowl. Add remaining ingredients then mix to combine. Set aside for at least 20 minutes for the flavours to meld.","images":[],"step":4},{"description":"Combine ingredients in a bowl.","images":[],"step":5},{"description":"Cook Chicken","images":[],"step":6},{"description":"Brush the outdoor grill with oil, then preheat on medium high. Or heat 1 tbsp of oil in a fry pan over medium high heat.","images":[],"step":7},{"description":"Remove chicken from Marinade. Cook the chicken for 2 to 3 minutes on each side, until golden brown and cooked through (cooking time depends on size of chicken).","duration":2.5,"images":[],"step":8},{"description":"Remove the chicken from the grill / fry pan onto a plate. Cover loosely with foil and allow to rest for 5 minutes before serving.","duration":5,"images":[],"step":9},{"description":"If your chicken thighs are large, you may need to cut them. Mine were small.","images":[],"step":10},{"description":"Get a pita bread or flatbread (preferably warmed) and place it on a piece of parchment (baking) paper (or you could use foil). Place some Salad down the middle of the bread, then top with chicken and Tzatziki.","images":[],"step":11},{"description":"Roll the wrap up, enclosing it with the parchment paper. Twist the end with the excess parchment paper to secure it and cut if desired.","images":[],"step":12},{"description":"I prefer to lay everything out on a table and let everyone help themselves.","images":[],"step":13}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner","lunch"],"cuisine":["Greek"],"categories":["australia-day","chicken-breast-recipes","chicken-recipes","dietary","gluten-free-recipes","greek-recipes","grilling-ideas-and-recipes","mediterranean-recipes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_be57c0cee375', 'en', 'US', 'Anzac Biscuits (Golden Oatmeal Cookies)', 'Recipe video above. The great Aussie Anzac biscuits!! Crispy on the outside, a little chewy in the middle, buttery, with a beautiful deep golden colour with a toffee flavour. They will stay crispy on the edges for a week and though they will soften, still fresh for another week. Re-crisp with a quick blast in the oven!Sweetness - Some readers have commented they find these too sweet. I really don''t find them too sweet, I was not brought up with very sugary desserts. If you reduce sugar, you will lose crispiness and the cookie will be more crumbly ie texture not as Anzac biscuits are intended to be!', 'https://www.recipetineats.com/tachyon/2014/07/Anzac-Biscuits_7.jpg', 15, 15, 30, 16, '[{"id": "ing_flour", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_rolled_oats", "quantity": {"value": 0.3, "unit": "pack of 500g"}}, {"id": "ing_desiccated_coconut", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 150.0, "unit": "block of 250g"}}, {"id": "ing_golden_syrup", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.025, "unit": "tub of 200g"}}]', '[{"ingredients":["1 cup plain flour (all purpose flour)","1 cup rolled oats","1 cup desiccated coconut (, unsweetened)","3/4 cup white sugar (, preferably caster / superfine)","150g / 5oz unsalted butter","4 tbsp golden syrup (Note 1)","1 tsp baking soda (bicarbonate soda)"]}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan forced)","images":[],"step":1},{"description":"Line 2 baking trays with baking paper.","images":[],"step":2},{"title":"Mix dry","description":"Mix flour, oats, coconut and sugar in a bowl.","images":[],"step":3},{"title":"Melt butter and golden syrup","description":"Place butter and golden syrup in a saucepan over medium high heat and stir until butter has melted.","images":[],"step":4},{"title":"Baking soda: Add baking soda and stir to combine","description":"it will fizz up, this is normal. Immediately remove from heat.","images":[],"step":5},{"title":"Biscuit dough","description":"Pour butter mixture into flour and mix until just combined. The mixture will be crumbly but should stick when you press together.","images":[],"step":6},{"title":"Form patties","description":"Scrunch / press 1 tablespoon of the mixture into balls, then flatten into patties. (Thinner = crisper, thicker = chewier centre, crispy edges) Place balls, 2.5 cm/1\" apart, on prepared trays.","images":[],"step":7},{"description":"Bake for 15 minutes, swapping trays halfway during cooking, or until deep golden. (Bake 12 min for chewy biscuits!)","duration":15,"images":[],"step":8},{"title":"Cool to crisp","description":"Stand on trays for 5 minutes. Transfer to a wire rack to cool - they harden as they cool!","duration":5,"images":[],"step":9}]', '["gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Australian"],"categories":["australia-day","baking-recipes","cookies","dessert-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_761573d53216', 'en', 'US', 'Lamingtons', 'Recipe video above. There is no cake more Australian than the Lamington! The sponge in this recipe is buttery and moist, generously coated in chocolate and coconut. Sandwiching with jam and cream is optional - takes it over the top, but it''s great without. KEY TIP: Freeze the sponge before coating - read Note 2.', 'https://www.recipetineats.com/tachyon/2019/01/Lamingtons_4.jpg', 40, 25, 65, 15, '[{"id": "ing_butter", "quantity": {"value": 125.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.05, "unit": "bottle of 50ml"}}, {"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_flour", "quantity": {"value": 0.263, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.117, "unit": "tub of 150g"}}, {"id": "ing_milk", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_cocoa_powder", "quantity": {"value": 0.2, "unit": "pack of 250g"}}, {"id": "ing_water", "quantity": {"value": 0.15, "unit": "L"}}, {"id": "ing_desiccated_coconut", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_strawberries", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}]', '[{"ingredients":["125 g / 4.5 oz unsalted butter (, softened)","1 cup (220g) caster sugar","1/2 tsp vanilla extract","3 eggs (, room temperature)","1 3/4 cups (260g) flour (, plain/all purpose, sifted (Note 1))","3.5 tsp baking powder","1/2 cup (125 ml) milk (low or full fat)"],"purpose":"Butter Sponge"},{"ingredients":["4 cups (480g) icing sugar ((confectionary sugar), sifted)","1/3 cup (22g) cocoa powder","1 tbsp (15g) unsalted butter","150ml (1/2 cup + 2 tbsp) boiling water"],"purpose":"Icing"},{"ingredients":["3 - 4 cups desiccated coconut"],"purpose":"Coating"},{"ingredients":["Strawberry jam","1 cup (250 ml) cream","1 tbsp white sugar"],"purpose":"Optional: Jam and Cream"}]', '[{"description":"Preheat oven to 180C/350F (or fan forced 160C/320F).","images":[],"step":1},{"description":"Sift flour and baking powder together.","images":[],"step":2},{"description":"Grease a 20 cm x 30 cm / 8\" x 12\" cake pan. Line with baking paper (parchment paper), leaving an overhang on all sides (to make it easy to remove).","images":[],"step":3},{"description":"Beat butter, sugar and vanilla with an electric mixer on medium high speed until light and fluffy - about 1 1/2 to 2 minutes.","images":[],"step":4},{"description":"Add eggs 1 at a time, beating well after each addition so the batter is smooth, not curdled.","images":[],"step":5},{"description":"Add half the flour and gently fold to combine, then stir in half the milk. Repeat with remaining flour and milk.","images":[],"step":6},{"description":"Pour the batter into the prepared pan and bake for 25 minutes until a skewer inserted into the centre comes out clean.","duration":25,"images":[],"step":7},{"description":"Stand for 5 minutes then use the overhang baking paper to lift the cake out onto a wire rack and cool completely.","duration":5,"images":[],"step":8},{"description":"Prepare Cake to Coat","images":[],"step":9},{"description":"Cut cake into 15 squares (5 x 3), or 18 rectangles. Freeze for 1 to 1.5 hours. (Note 2)","images":[],"step":10},{"description":"Combine the Icing ingredients in a heat proof bowl and mix until smooth. Should be a syrup consistency, but not watery. (Note 2)","images":[],"step":11},{"description":"Place coconut in a shallow bowl or pan with a largish surface area (Note 3).","images":[],"step":12},{"description":"Place a piece of cake in the icing and roll to coat using 2 forks. Transfer it into the coconut and quickly roll to coat all over in coconut. Transfer to tray.","images":[],"step":13},{"description":"Repeat with remaining sponges.","images":[],"step":14},{"description":"Stand for 1 to 2 hours, or until set. Then serve with tea and coffee!","images":[],"step":15},{"title":"Optional","description":"Jam and Cream","images":[],"step":16},{"description":"Beat cream and sugar until firm peaks form.","images":[],"step":17},{"description":"Cut coated Lamington in half horizontally. Spread with jam then pipe or dollop on cream. Top with lid, keep refrigerated.","images":[],"step":18}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Australian"],"categories":["australia-day","baking-recipes","dessert-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_792255761dab', 'en', 'US', 'Homemade French Onion Dip', 'Recipe video above. Classic French Onion Dip - made at home! The key to the amazing flavour base is to cook the onions slowly because they sweeten and caramelise.', 'https://www.recipetineats.com/tachyon/2015/07/French-Onion-Dip_5.jpg', 10, 25, 35, 2, '[{"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 375.0, "unit": "pack of 1kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_cream_cheese", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.094, "unit": "jar of 400g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.3, "unit": "tub of 250g"}}]', '[{"ingredients":["3 tbsp butter","2 1/2 cups diced onions (2 to 3 onions) (brown, yellow or white)","3/4 tsp salt","1/2 tsp black pepper","1/2 tsp onion powder","1/4 tsp cayenne pepper","4 oz / 120 g cream cheese ((cold), cut into cubes)","1/4 cup whole egg mayonnaise","1/2 cup sour cream (full fat is best, but you can use low fat or even yoghurt)"]}]', '[{"description":"Melt the butter in a fry pan over medium heat.","images":[],"step":1},{"description":"Add the onions, salt, pepper, onion powder and cayenne pepper. Cook for 5 minutes, stirring. Then reduce the heat to medium low and cook for 20 to 25 minutes, stirring occasionally. The onions should be sweet and golden. Remove from stove and allow to cool.","duration":5,"images":[],"step":2},{"description":"Place the cream cheese, sour cream and mayo in a bowl, mix until smooth (use microwave in 10 sec bursts if needed to assist)","images":[],"step":3},{"description":"Add the caramelised onions. Mix until just combined. Refrigerate at least 2 hours to allow flavours to develope, overnight is better!","images":[],"step":4},{"description":"Serve at room temperature, garnished with chopped chives if desired. Best served with crinkle cut plain potato chips!","images":[],"step":5}]', '["egg","milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western food"],"categories":["australia-day","dietary","dip-recipes","gluten-free-recipes","most-popular","super-bowl-party-food","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c2571271cbda', 'en', 'US', 'Lamb Koftas with Yoghurt Dressing', 'RECIPE VIDEO ABOVE. The smell of Middle Eastern spices while this is cooking is totally intoxicating!! Try this Lamb Kofta recipe once, and you''ll be addicted for life! Traditionally cooked over charcoal, brilliant on the BBQ, but I usually cook these midweek on the stove. **great recipe for gatherings, DIY spread, make ahead**', 'https://www.recipetineats.com/tachyon/2014/11/Lamb-Koftas_7.jpg', 15, 15, 30, 8, '[{"id": "ing_lamb_mince", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_bread", "quantity": {"value": 8.0, "unit": "loaf"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_cinnamon", "quantity": {"value": 7.5, "unit": "jar"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.5, "unit": "jar of 50g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.3, "unit": "tub of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.5, "unit": "jar of 50g"}}, {"id": "ing_skewers", "quantity": {"value": 8.0, "unit": "pack of 50"}}, {"id": "ing_bread", "quantity": {"value": 8.0, "unit": "loaf"}}, {"id": "ing_red_cabbage", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}]', '[{"ingredients":["1 lb / 500 g lamb mince (ground lamb)","1/2 onion (, grated)","1/4 cup breadcrumbs (, preferably panko)","2 cloves garlic (, crushed)","2 tbsp chopped fresh coriander"],"purpose":"Koftas"},{"ingredients":["2 tsp cumin","2 tsp coriander","2 tsp paprika","1.5 tsp ground cinnamon","3/4 tsp cayenne pepper (this is a bit spicy, reduce to taste or leave out)","1 tsp cooking / kosher salt","1/2 black pepper"],"purpose":"Kofta Spices"},{"ingredients":["1 cup yogurt (, Greek or other thick plain)","1 tbsp extra virgin olive oil","1 clove garlic (, crushed)","1 tsp cumin","1 tbsp lemon juice","1/4 tsp salt and pepper (, each)"],"purpose":"Yoghurt Sauce"},{"ingredients":["8 skewers (Note 1)","8 flatbreads (small)","Shredded Red Cabbage, Carrot and Mint Salad (Note 3)","OR shredded lettuce, tomato and onion slices (Note 3)"],"purpose":"To Serve"}]', '[{"title":"Yogurt Sauce","description":"Combine the yogurt sauce ingredients and leave in fridge for at least 20 mninutes for the flavor to develop (overnight even better!).","images":[],"step":1},{"title":"Koftas","description":"Grate the onion into the bowl using a standard box grater. Add remaining Kofta ingredients and mix well with your hands.","images":[],"step":2},{"description":"With damp hands, divide the meat into 8 equal pieces and push and shape the meat onto 8 skewers. Make them smooth (looks nicer, pictured!) or a bit nubbly (more surface area to brown!).","images":[],"step":3},{"description":"Cooking:","images":[],"step":4},{"title":"Stove","description":"Preheat 1/2 tbsp oil in a large skillet over medium high heat. Cook in batches for 5 minutes in total, turning to brown evenly all over.","duration":5,"images":[],"step":5},{"title":"BBQ","description":"BBQ on medium high for about 6 minutes, rotating to brown all over.","images":[],"step":6},{"title":"Broiler/oven grill","description":"preheat and cook koftas 30cm/10\" from heat source for 12 minutes, rotating as needed until lightly browned (you won''t get as good a browning as stove/BBQ).","duration":12,"images":[],"step":7},{"title":"Do a DIY spread","description":"pile everything onto a platter a make everyone serve themselves.","images":[],"step":8},{"description":"Get a flatbread, smear with Yogurt Sauce, top with Red Cabbage Mint Salad (more options Note 3) then Kofta, drizzle over more Yoghurt Sauce. Devour and be happy!","images":[],"step":9}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Middle Eastern","Moroccan"],"categories":["australia-day","cuisines","dietary","dinner-tonight","gluten-free-recipes","grilling-ideas-and-recipes","lamb-recipes","middle-eastern-recipes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_14689a674677', 'en', 'US', 'Oven Pork Ribs with Barbecue Sauce', 'Recipe video above. Barbecue pork ribs made in the oven! It''s easy, the ribs are meltingly tender and it''s packed full of flavour from the rub, braising the ribs in cider (see Note 1 for subs!) and the homemade barbecue sauce glaze! (Note: BBQ Sauce ingredients not consistet with the video!! Editing blunder - use ingredients listed in recipe below. Need to fix video!!)', 'https://www.recipetineats.com/tachyon/2016/01/Oven-Pork-Ribs-with-Barbecue-Sauce_4.jpg', 15, 135, 150, 6, '[{"id": "ing_paprika", "quantity": {"value": 0.312, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_beef_steak", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_apples", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.25, "unit": "bottle of 500ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_molasses", "quantity": {"value": 22.5, "unit": "jar"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}]', '[{"ingredients":["2.5 tsp paprika powder","2 tsp garlic powder (sub with onion powder)","1.5 tsp onion powder (sub with garlic powder)","1 tsp cayenne pepper (omit for not spicy)","1.5 tsp dried thyme","1.5 tsp dried oregano","1.5 tsp salt","0.5 tsp black pepper"],"purpose":"Barbecue Rub for Ribs:"},{"ingredients":["2 - 2.5kg / 4 - 5lb pork ribs (2 racks)","3/4 cup sweet alcoholic apple cider (hard cider) (, or apple juice (Note 2))","1 tbsp olive oil"],"purpose":"Ribs"},{"ingredients":["1/2 cup apple cider vinegar (Note 3)","1 1/2 cups tomato ketchup (or Aussie tomato sauce)","1/2 cup water (or use remaining apple cider!)","1 1/2 tbsp molasses (, orginal (not blackstrap, Note 4))","1/3 cup brown sugar","2 tsp mustard powder","1 1/2 tsp garlic powder","2 tsp Worcestershire sauce","1 tsp salt","1 tsp black pepper","1 tsp Tabasco or cayenne pepper (optional, for spiciness)"],"purpose":"Homemade Barbecue Sauce"}]', '[{"description":"Combine the Rub ingredients and rub onto both sides of the ribs (most on meaty side). Set aside to marinate for 20 minutes (or overnight).","duration":20,"images":[],"step":1},{"description":"Preheat oven to 160°C/320°F (all oven types).","images":[],"step":2},{"description":"Place ribs on a tray in a single layer. Pour apple cider underneath the ribs, cover with foil then bake for 1 hour 30 minutes or until the meat is pretty tender (Note 5).","images":[],"step":3},{"description":"Remove from oven, turn up to 180°C/350°F. Remove foil, drizzle with olive oil, then return ribs to oven for 15 minutes or until rub becomes nice and crusty.","duration":15,"images":[],"step":4},{"description":"Line a new tray with foil then baking / parchment paper (you''ll thank me later).","images":[],"step":5},{"description":"Remove ribs from oven, transfer to lined tray. Pour any juices from tray over the ribs.","images":[],"step":6},{"description":"Flip ribs so the bonier side is up. Slather with Barbecue Sauce, then bake 10 minutes.","images":[],"step":7},{"description":"Remove from oven, then turn ribs over so the meaty side is up. Slather with Barbecue Sauce, bake 5 minutes. Repeat 2 or 3 more times until you''ve got a thick glaze on the ribs.","images":[],"step":8},{"description":"Cut ribs into individual or multiple rib portions and serve with remaining Barbcue Sauce!","images":[],"step":9},{"description":"Place all ingredients in a saucepan and simmer over medium heat, stirring occasionally, for 45 minutes or until thickened.","duration":45,"images":[],"step":10},{"title":"Adjust to taste","description":"sweetness with brown sugar / honey, salt and sour with vinegar. Use for glazing ribs and as a sauce for serving.","images":[],"step":11}]', '["mustard"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["American"],"categories":["australia-day","grilling-ideas-and-recipes","iconic-dishes","most-popular","pork-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_56ecce5d96e5', 'en', 'US', 'Steamed Mussels', 'Recipe video above. Mussels are highly underrated – they’re cheap, quick and easy to cook, and delicious! This is a classic way to cook mussels - in a garlic white wine butter sauce. Be sure to have plenty of crusty bread to mop up the delicious sauce, it''s my favourite part!', 'https://www.recipetineats.com/tachyon/2014/05/Mussels-with-Garlic-White-Wine_2.jpg', 10, 10, 20, 4, '[{"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_2_lbs_mussels", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.333, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["50g / 3 tbsp butter (, unsalted)","1/2 onion (, finely chopped (brown, yellow, white))","3 garlic cloves (, very finely chopped)","1 kg / 2 lbs mussels (, bearded and scrubbed (Note 1))","1 cup (250ml) dry white wine","2 tomatoes (, deseeded and diced (Note 2))"]},{"ingredients":["1/4 cup flat leaf parsley (, roughly chopped)","Lemon wedges (essential!)","Crusty bread to serve (essential!)"],"purpose":"Serving:"}]', '[{"description":"Heat oil in a large, heavy pot over medium heat, melt butter.","images":[],"step":1},{"description":"Add the garlic and onion, stirring occasionally until onion is soft and fragrant - about 3 minutes.","images":[],"step":2},{"description":"Turn heat up to high, add wine and bring to boil. Simmer 2 minutes until the harsh alcoholic smell is gone.","images":[],"step":3},{"description":"Stir in tomatoes, add mussels stir to coat in sauce a bit.","images":[],"step":4},{"description":"Cover, lower heat to medium high and cook, shaking pot once or twice.","images":[],"step":5},{"title":"The mussels are cooked when they are open","description":"around 6 to 8 minutes.","images":[],"step":6},{"description":"Toss through parsley and season to taste with salt and pepper. Be careful with the salt as the mussels are already salty, so taste first.","images":[],"step":7},{"description":"Drizzle with extra virgin olive oil, and serve with lemon wedgeds on the side so people can use as much as they wish. Serve immediately with crusty bread to mop up the sauce!","images":[],"step":8}]', '["gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["australia-day","dinner-tonight","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ff3cad72a151', 'en', 'US', 'Aussie Meat Pie recipe', 'Recipe video above. The great Australian meat pie - made at home! Buttery shortcrust base filled with slow cooked fall apart chunky beef smothered in a rich gravy, topped with puff pastry. Legendary! {See notes for beef mince version}Also see the Family Size Meat Pie, mini Party Pies and Sausage Rolls!', 'https://www.recipetineats.com/tachyon/2019/04/Meat-Pies_3.jpg', 40, 220, 260, 6, '[{"id": "ing_batches_homemade_shortcrust_pastry", "quantity": {"value": 1.5, "unit": "pack"}}, {"id": "ing_frozen_shortcrust_pastry_sheets_thawed", "quantity": {"value": 3.0, "unit": "pack"}}, {"id": "ing_refrigerated_pie_crusts", "quantity": {"value": 2.0, "unit": "pack"}}, {"id": "ing_frozen_puff_pastry_sheets_just_thawed", "quantity": {"value": 3.0, "unit": "pack"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_beef", "quantity": {"value": 1.25, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.2, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_wine", "quantity": {"value": 1.0, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.2, "unit": "jar of 50g"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}]', '[{"ingredients":["1 1/2 batches homemade shortcrust pastry","3 frozen shortcrust pastry sheets, thawed (300g/10oz)","2 refrigerated pie crusts (US/Can)"],"purpose":"Pie Base – Choose ONE (Note 1):"},{"ingredients":["3 frozen puff pastry sheets, just thawed (300g/10oz) (Note 2)","1 egg (, lightly whisked)"],"purpose":"Pie Lid:"},{"ingredients":["1.25 kg / 2.5lb beef chuck (, 2.5cm/1\" cubes (Note 3))","1/2 tsp each salt & pepper","2 - 3 tbsp olive oil","1 onion (, diced)","4 garlic cloves (, minced)","5 tbsp flour (, plain/all purpose)","1 1/4 cups (315 ml) beef stock, low sodium (Note 4)","3 cups (750 ml) red wine (, dry full bodied (Note 5))","2 tbsp tomato paste","1 tsp Worcestershire sauce","2 tsp black pepper (, coarsely ground)","2 bay leaves"],"purpose":"Filling:"}]', '[{"description":"Sprinkle beef with 1/2 tsp salt and pepper.","images":[],"step":1},{"description":"Heat 1 tbsp oil in a large heavy based pot over high heat. Add 1/3 of the beef and brown aggressively all over, then remove. Repeat with remaining beef, adding more oil if needed.","images":[],"step":2},{"description":"Turn stove down to medium high. Add garlic and onion, cook 3 minutes.","images":[],"step":3},{"description":"Add flour, stir through.","images":[],"step":4},{"description":"Slowly add beef stock while stirring constantly. Once flour is dissolved, add wine, tomato paste, Worcestershire, pepper and bay leaves.","images":[],"step":5},{"description":"Return beef into pot, cover with lid, adjust heat so it''s simmering gently.","images":[],"step":6},{"description":"Simmer 1 hr 45 minutes. Remove lid, increase heat slightly and simmer 30 - 45 minutes, stirring regularly, or until beef is fork tender and liquid reduces down to a thickish gravy, just about covering beef (see video). Do not reduce liquid too much - thickens more as it cools & in pie.","images":[],"step":7},{"description":"Remove from stove, cover and cool filling (I usually leave overnight).","images":[],"step":8},{"description":"Preheat oven to 180C/350F.","images":[],"step":9},{"description":"Cut out 6 rounds from the shortcrust pastry, then drape pastry into pie tins - don''t stretch and pull pastry, causes shrinkage. (Notes 1 & 6)","images":[],"step":10},{"description":"Place pies on tray. Top each pie with large sheets of parchment / baking paper and fill with pie weights (Note 7).","images":[],"step":11},{"description":"Bake 20 minutes, remove, then use paper overhang to carefully remove pie weights.","images":[],"step":12},{"description":"Return crusts into oven for 5 minutes or until base is light golden and dry (can skip, Note 8). Remove from oven.","duration":5,"images":[],"step":13},{"description":"Fill pies with cooled filling, push down to fill. Should be slightly mounded.","images":[],"step":14},{"title":"Cut rounds from partially thawed puff pastry","description":"cut them slightly larger than the edge of the cooked pastry bases.","images":[],"step":15},{"description":"Brush edge of pie crusts with egg, then place lid on filling, pressing edges to seal puff pastry to the shortcrust pastry.","images":[],"step":16},{"description":"Brush lids with egg, then cut a 1cm / 0.5\" incision in the middle using a small knife.","images":[],"step":17},{"description":"Bake 30 minutes or until deep golden and puffed.","images":[],"step":18},{"description":"Devour hot and fresh, topped with tomato sauce or ketchup if desired!","images":[],"step":19}]', '["egg","gluten"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Australian"],"categories":["australia-day","beef-recipes","iconic-dishes","quiches-tart-and-pie-recipes","slow-cooked-fall-apart"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8cbd643628e5', 'en', 'US', 'Prawn Mango Avocado Summer Salad with Lime Dressing', 'Recipe video above (useful tips for chopping mango and avo). Prawns, Mango and Avocado are a magical combination! This summer salad is fresh and healthy, yet satisfying to have as a meal or great for sharing! Make this with: rice, quinoa, risoni/orzo or pearl couscous.', 'https://www.recipetineats.com/tachyon/2019/01/Prawn-Avocado-Mango-Salad-with-Lime-Dressing_2.jpg', 15, 10, 25, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.75, "unit": "pack of 500g"}}, {"id": "ing_shrimp", "quantity": {"value": 300.0, "unit": "kg"}}, {"id": "ing_mango", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_rocket_arugula", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["2.5 cups cooked risoni/orzo or similar (Note 1)","300 – 400g / 10 – 12 oz cooked peeled prawns / shrimp (~750g unpeeled whole cooked)","1 large mango (, cut 1.5cm / ½” pieces)","1 large ripe avocado (, cut 1.5cm / ½” pieces )","75 g / 2.5 oz rocket / arugula (, roughly chopped (Note 2))","250 g / 8oz cherry tomatoes (, halved)","1/2 red onion (, finely sliced)","1/4 cup coriander / cilantro leaves (, finely chopped (Note 2))"],"purpose":"Salad:"},{"ingredients":["4 tbsp (60 ml) extra virgin olive oil","2 tbsp (30 ml) lime juice ((fresh), plus more to taste)","1 small garlic clove (, minced)","1/2 tsp salt","1/4 tsp black pepper"],"purpose":"Lime Dressing:"}]', '[{"description":"Shake Dressing in a jar.","images":[],"step":1},{"title":"Chop prawns into 1.75","description":"2 cm / 2/3” pieces.","images":[],"step":2},{"description":"Place all Salad Ingredients in a bowl, pour over dressing. Toss very gently using rubber spatula. Adjust to taste with more lime if desired. Serve immediately!","images":[],"step":3}]', '["shellfish"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["australia-day","dietary","dinner-tonight","easter-brunch-recipes","easter-sides-fresh-light","gluten-free-recipes","main-dishes","mains","no-cook-food","pasta-salads-and-rice-salads","prawns-shrimp","quick-and-easy","salad-recipes-main-course","seafood-recipes","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_36772bb70b27', 'en', 'US', 'Marinated Beef Kebabs', 'Recipe video above. Using a marinade infuses the beef with flavour as well as tenderising so you''ll have juicy steak pieces even if you opt for a more economical cut of beef. Use the reserved marinade to baste the kebabs as they cook for extra flavour! Buy the beef in a block so you can cut them into large cubes. Marinading time - 24 hours will give you the best results (most tender beef), though even 3 hours is better than not marinating at all. Makes 8 skewers.', 'https://www.recipetineats.com/tachyon/2018/07/Beef-Kabobs_2.jpg', 15, 8, 23, 8, '[{"id": "ing_beef_steak", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_mushroom", "quantity": {"value": 16.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.15, "unit": "bottle of 250ml"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_balsamic_vinegar", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_skewers", "quantity": {"value": 16.0, "unit": "pack of 50"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_pink_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}]', '[{"ingredients":["750g / 1.5 lb rump (picanha), beef tri-tip, sirloin steak or other steak cut (suitable for quick cooking (Note 1))","3 capsicum / bell peppers (red, yellow green)","1 large red onion","16 small mushrooms (, 3.25cm / 1.3\" wide)"]},{"ingredients":["1 tsp minced garlic (2 large garlic clove)","1 tsp onion powder (or sub with garlic powder)","2 1/2 tbsp soy sauce (Note 2)","2 tbsp Worcestershire sauce","2 tbsp balsamic vinegar","1 tbsp vegetable oil (or other neutral flavoured oil)","1/4 tsp black pepper"],"purpose":"Marinade:"},{"ingredients":["16 flat metal skewers (, 25 - 30cm / 10 - 12\" (Note 3))","Olive oil (, for drizzling and cooking)","Finely chopped parsley (, garnish (optional))"],"purpose":"Cooking:"},{"ingredients":["Pink sauce (, pictured in post - Note 4)","Lemon Yogurt Sauce (this goes well with the flavours here)"],"purpose":"Optional sauce:"}]', '[{"description":"Cut the beef into 3.25cm / 1.3\" wide cubes.","images":[],"step":1},{"title":"Marinade","description":"Mix Marinade in a bowl. Add beef. Marinate for 3 - 24 hours.","images":[],"step":2},{"description":"Making the kebab skewers","images":[],"step":3},{"description":"Cut capsicum and onion into 3.25cm / 1.3\" wide squares.","images":[],"step":4},{"description":"Thread beef (reserve Marinade), vegetables and mushrooms on each skewer. I use 2 pieces of vegetables between each piece of beef. Thread loosely - don''t smush together tightly (helps even cooking).","images":[],"step":5},{"description":"Brush kebabs lightly with Reserved Marinade (including vegetables), then drizzle with olive oil.","images":[],"step":6},{"title":"Cook and baste","description":"Heat BBQ or large skillet over high heat. Add 1 tbsp oil, then when smoking, cook kebabs in batches for 2 minutes on each side until slightly charred (4 sides = 8 minutes in total), basting with Reserved Marinade as you go.","duration":2,"images":[],"step":7},{"title":"Rest and serve","description":"Transfer to plate, cover loosely with foil and rest for 3 minutes before serving. Garnish with parsley if desired. See note for pictured Pink Dipping Sauce.","duration":3,"images":[],"step":8}]', '["gluten","milk","soy"]', '["high_protein","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mediterranean","Western"],"categories":["australia-day","beef","beef-recipes","grilling-ideas-and-recipes","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_446c91c55580', 'en', 'US', 'Macaroni Salad', 'Recipe VIDEO above. This is just a great classic, Macaroni Salad. Plenty of creamy dressing that you know and love, but slightly lightened up - all the flavour, less guilt! Serves 6-8 as a side. For an even healthier option, try this with a mayo-free Creamy Lemon Dressing or Ranch Dressing!', 'https://www.recipetineats.com/tachyon/2017/12/Macaroni-Salad_4-1.jpg', 15, 10, 20, 6, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_celery", "quantity": {"value": 3.0, "unit": "head"}}, {"id": "ing_capsicum", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 2.25, "unit": "bunch"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.188, "unit": "jar of 400g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.3, "unit": "tub of 250g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["250 g / 1/2 lb macaroni elbow pasta","1 1/2 tbsp salt (to cook pasta)","1 cup celery (, finely sliced (1 stalk))","3/4 cup red capsicum / bell peppers (, finely diced (1 small))","3/4 cup green onions (, finely sliced (1 large stem))","1 medium carrot (, grated (using standard box grater))"]},{"ingredients":["1/2 cup mayonnaise (Hellmann''s, Best Foods, S&W or other whole egg mayonnaise)","1/2 cup yoghurt or sour cream (, full or low fat)","1 tbsp cider vinegar","2 tsp Dijon mustard","2 tsp sugar","3/4 tsp garlic powder","1 1/4 tsp salt","1/2 tsp pepper"],"purpose":"Dressing:"}]', '[{"title":"Bring large pot of water to the boil","description":"4 to 5 litres / quarts. Add salt then add pasta. Cook per packet directions.","images":[],"step":1},{"description":"Drain pasta then cool.","images":[],"step":2},{"description":"Meanwhile, mix Dressing ingredients in a bowl.","images":[],"step":3},{"description":"Place pasta in a bowl. Add remaining Macaroni Salad ingredients. Pour over Dressing.","images":[],"step":4},{"description":"Toss. Adjust salt / sugar / sour (vinegar) / mayo to taste.","images":[],"step":5},{"description":"Set aside for at least 20 minutes. Then serve at room temperature (not cold). It''s great the next day too!","images":[],"step":6}]', '["egg","gluten","milk","mustard"]', '["low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["australia-day","easter-sides-fresh-light","pasta-recipes","pasta-salads-and-rice-salads","quick-and-easy","side-dishes","side-salads","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b8ee823f83ca', 'en', 'US', 'Hamburger Recipe', 'Recipe video above. All you need for great beef hamburgers is decent beef and lots of salt and pepper. This is the way it''s done by all the grilling masters like Bobby Flay, and your favourite diners!', 'https://www.recipetineats.com/tachyon/2016/02/Beef-Hamburgers_7-2.jpg', 15, 20, 35, 4, '[{"id": "ing_beef", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 3.0, "unit": "pack of 1kg"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_cheese", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.005, "unit": "jar of 200g"}}, {"id": "ing_french_fries", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}]', '[{"ingredients":["800g - 1kg / 1.6 - 2 lb ground beef (mince), 20%+ fat (Note 1)","Salt and pepper","3 onions, peeled and sliced into rings","2 tbsp oil","4 - 8 slices cheese of choice, I use Swiss (optional)"],"purpose":"Hamburger Pattie"},{"ingredients":["4 soft hamburger buns, lightly toasted","Lettuce, tomato slices","Ketchup, mustard, relish, sliced pickles"],"purpose":"Hamburger"},{"ingredients":["French fries","Baked potato wedges"],"purpose":"On the side"}]', '[{"description":"Separate beef into 4 equal portions. Use hands to lightly form into patties the size of your buns (mine are about 10 cm / 4\") - don''t press hard, light fingers = soft juicy patties (see video for how I do this).","images":[],"step":1},{"description":"Season generously with salt and pepper on both sides. Make a dent on one side (stop burger from become dome shape and shrinking when cooking).","images":[],"step":2},{"description":"Heat 1 tbsp oil in a heavy based skillet or BBQ over high heat. Add onion and cook until wilted and caramelised. Season with salt and pepper, then remove.","images":[],"step":3},{"description":"Heat 1 tbsp oil until smoking. Add patties and cook for 2 minutes until deep golden with a great crust. Do not press! Flip carefully, cook for 1 minute then top with cheese (if using). Cover with lid and cook for further 1 minute until cheese is melted.","duration":2,"images":[],"step":4},{"description":"Meanwhile, toast the cut side of the buns lightly.","images":[],"step":5},{"title":"To serve","description":"Spread base of buns with sauce / condiment of choice. Top with lettuce then tomato, then hamburger patty. Pile over onions, sliced pickles, then more sauce/condiments. Top with lid of bun. Serve immediately.","images":[],"step":6}]', '["milk","mustard"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["australia-day","beef-mince-recipes","beef-recipes","burger-recipes","dietary","dinner-tonight","gluten-free-recipes","grilling-ideas-and-recipes","main-dishes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1ad0e830bdbe', 'en', 'US', 'Slow Cooker Beef Brisket with BBQ Sauce', 'Video above. Beef brisket slow cooked until tender, then finished in the oven to get that gorgeous caramelisation, basted with a homemade BBQ Sauce that the brisket is cooked in. Slice it and serve as part of a hearty Southern style supper or pile it up high on sliders!', 'https://www.recipetineats.com/tachyon/2017/07/Slow-Cooker-BBQ-Beef-Brisket-1-1.jpg', 15, 600, 615, 8, '[{"id": "ing_beef_brisket", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.019, "unit": "jar of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.25, "unit": "bottle of 500ml"}}, {"id": "ing_ketchup", "quantity": {"value": 0.45, "unit": "bottle of 500g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 15.0, "unit": "bottle"}}]', '[{"ingredients":["1.5 – 2 kg / 3 – 4 lb beef brisket (Note 1)","1 tbsp olive oil (or a neutral oil like vegetable, canola)"]},{"ingredients":["1 tbsp brown sugar","2 tsp paprika powder","1 tsp onion powder","1 tsp garlic powder","1/2 tsp cumin powder","3/4 tsp mustard powder","1 tsp salt","1/2 tsp black pepper"],"purpose":"Rub:"},{"ingredients":["2 garlic cloves (, minced)","1/2 cup / 125 ml apple cider vinegar","1 1/2 cups / 375 ml ketchup","1/2 cup / 110g brown sugar (, packed)","2 tsp EACH black pepper, onion powder, mustard powder","1 tsp cayenne pepper (adjust to taste re: spiciness)","1 tbsp Worcestershire sauce"],"purpose":"BBQ Sauce:"}]', '[{"description":"Mix Rub ingredients. Rub all over brisket. If time permits, leave for 30 minutes – 24 hours in the fridge, but I rarely do this.","duration":30,"images":[],"step":1},{"description":"Combine BBQ Sauce ingredients in a slow cooker. Mix then add the brisket – squish it in if needed, like I did (see video).","images":[],"step":2},{"description":"Slow cook in slow cooker for 8 hours (1.5 kg / 3 lb) to 10 hours (2 kg / 4 lb). (Note 2 for pressure cooker and click here for oven)","images":[],"step":3},{"description":"Remove brisket onto a tray.","images":[],"step":4},{"description":"Pour liquid in slow cooker into a saucepan. Bring to simmer over medium high heat and reduce until it thickens to a syrup consistency (it thickens more as it cools).","images":[],"step":5},{"description":"Meanwhile, drizzle brisket with oil then roast in a 200C/390F oven for 15 minutes until brown spots appear. Remove then baste generously with Sauce, then return to oven for 5 minutes. Remove and baste again, then return to oven for 5 – 10 minutes until it caramelises and looks like the photos. (See note for BBQ option)","duration":15,"images":[],"step":6},{"title":"TO SERVE","description":"Slice brisket thinly across the grain and serve with remaining BBQ Sauce. This is terrific served as a meal with sides or piled high onto rolls with Coleslaw as sliders. See Note 3 for more ideas.","images":[],"step":7}]', '["mustard"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["American","Southern"],"categories":["australia-day","beef","beef-recipes","iconic-dishes","main-dishes","mains","quick-and-easy","sandwiches-and-sliders","slow-cooked-fall-apart","slow-cooker-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3f3664f52608', 'en', 'US', 'Scones', 'Recipe video above. Super quick and easy classic plain scone recipe, fluffy inside with golden tops. Using a food processor is not only easier, it eliminates common pitfalls when it comes to making scones. Serve with copious amounts of jam and cream!', 'https://www.recipetineats.com/tachyon/2018/04/Scones_7a.jpg', 10, 12, 22, 10, '[{"id": "ing_flour", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 80.0, "unit": "block of 250g"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_strawberries", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.05, "unit": "bottle of 50ml"}}]', '[{"ingredients":["3 cups / 450g self raising flour (Note 1)","80 g / 3 oz cold salted butter (, cut into 1 cm / 2/5\" cubes (Note 2))","1 cup / 250 ml milk, fridge cold (Note 2)","Extra flour (, for dusting)","Extra milk (, for brushing)"]},{"ingredients":["Strawberry jam (or other of choice)","250 ml / 1 cup whipping cream","1 tbsp white sugar","1/2 tsp vanilla extract (optional)"],"purpose":"Serving:"}]', '[{"description":"Preheat oven to 200C/390F (standard) or 180C/350F (fan / convection).","images":[],"step":1},{"description":"Place flour in food processor, then butter. Blitz on high for 8 seconds until it resembles breadcrumbs.","duration":0.13333333333333333,"images":[],"step":2},{"description":"Pour milk all over the flour (don''t pour in one place). Blitz for 6 to 8 seconds on high until the crumbs turn into ball(s).","duration":0.11666666666666667,"images":[],"step":3},{"description":"Transfer dough onto work surface, scrape out residual bits in the food processor.","images":[],"step":4},{"description":"Knead lightly no more than 10 times just to bring the dough together into one smooth ball, then pat down into a 2 cm / 4/5\" thick disc. Dust with extra flour if necessary (I don''t need it).","images":[],"step":5},{"title":"Optional","description":"Lightly roll across the top with a rolling pin to smooth the top.","images":[],"step":6},{"description":"Dip a 5 cm / 2\" round cutter into Extra Flour.","images":[],"step":7},{"description":"Plunge cutter straight down and back out into dough - do not twist. Repeat all over disc.","images":[],"step":8},{"description":"Remove excess dough from around scones, then carefully transfer scones onto baking tray, taking care not to smear / press the cut sides. (Note 4)","images":[],"step":9},{"description":"Gather together dough scraps and repeat. I get 10 scones in total.","images":[],"step":10},{"description":"Brush tops lightly with milk. (Optional)","images":[],"step":11},{"description":"Bake for 10 to 12 minutes until the top is golden and it sounds hollow when tapped.","duration":11,"images":[],"step":12},{"description":"Remove from oven, then transfer onto dish towel and wrap loosely (makes top soft).","images":[],"step":13},{"title":"Once cooled to warm (10","description":"15 minutes), serve warm.","images":[],"step":14},{"description":"Tradition is to split the scone with hands (no knife!), slather with jam and dollop on cream.","images":[],"step":15},{"description":"Whip cream, sugar and vanilla until soft peaks form. Makes 2 cups of whipped cream.","images":[],"step":16}]', '["gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Australian","English"],"categories":["australia-day","baking-recipes","dessert-recipes","easter-brunch-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_37eb94fd3e20', 'en', 'US', 'Slow Cooked Lamb Shawarma', 'This meltingly tender Slow Cooked Shawarma is the stuff food dreams are made of!! Slathered in a deceptively simple shawarma spice rub then slow cooked until fall apart, the flavour and fragrance of this lamb is absolutely heavenly. Make this Middle Eastern speciality with lamb shoulder or lamb leg. Finishing on the BBQ is optional - ideal for reheating if making ahead / summer BBQ''s! SLOW COOKER directions added in notes. Recipe VIDEO below.', 'https://www.recipetineats.com/tachyon/2018/01/Lamb-Shawarma_4.jpg', 10, 210, 220, 6, '[{"id": "ing_lamb", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_cardamon", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}]', '[{"ingredients":["2kg / 4 lb lamb shoulder (bone in) or 1.7 kg / 3.5 lb butterflied lamb leg (Note 1)"]},{"ingredients":["3 garlic cloves (, minced)","1 tbsp ground coriander","1 tbsp ground cumin","1 tbsp ground cardamon","1 tsp cayenne pepper (1/2 tsp = not spicy)","2 tsp smoked paprika (ordinary also ok)","1 1/2 tsp salt","1/2 tsp black pepper","1/4 cup / 65 ml extra virgin olive oil","2 - 3 tbsp / 40 - 60 ml lemon juice"],"purpose":"Shawarma Paste:"},{"ingredients":["2 cups / 500 ml water"],"purpose":"Cooking:"}]', '[{"description":"Preheat oven to 180C/350F (standard) or 160C/320F (fan forced / convection).","images":[],"step":1},{"description":"Place Paste ingredients in a bowl, starting with 2 tbsp lemon juice, and mix. It should be a wet paste that can be slathered onto the lamb (see video).","images":[],"step":2},{"description":"Place lamb in a large roasting pan. Slather all over with paste. Optional: Marinate 24 hours (not mandatory, I usually skip).","images":[],"step":3},{"description":"Position the lamb with the fat side up. Pour water around, cover tightly with foil.","images":[],"step":4},{"title":"Roast 3 hours, removing from the oven 2","description":"3 times to spoon over pan juices (ie baste).","images":[],"step":5},{"title":"Remove foil. Meat should be tender","description":"check with 2 forks.","images":[],"step":6},{"description":"Baste again, then return to oven for 30 minutes to get a nice crust.","duration":30,"images":[],"step":7},{"title":"Remove lamb from roasting pan","description":"reserve juices.","images":[],"step":8},{"description":"Finish on BBQ, Optional (Note 2):","images":[],"step":9},{"description":"Cool the lamb for 20 minutes or so (so it firms up slightly, easier to handle).","duration":20,"images":[],"step":10},{"description":"If you used shoulder, pull the meat off the bone in 4 or 5 chunks (see video).","images":[],"step":11},{"description":"Preheat BBQ to medium and oil if required.","images":[],"step":12},{"description":"Coat lamb in pan juices. Sear on both sides until deep golden and a crust forms. Dab with pan juices on both sides.","images":[],"step":13},{"description":"Slice or shred lamb, as desired. Drizzle with plenty of juices.","images":[],"step":14},{"description":"Make Lamb Shawarma wraps by serving with shredded lettuce, tomatoes and minted yoghurt (Note 3) or pile over Lemon Herbed Couscous (Note 4) and garnish with pomegranate seeds and parsley or chopped coriander/cilantro (if desired). Both pictured in post.","images":[],"step":15}]', '[]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern"],"categories":["australia-day","cuisines","dietary","easter-mains","easter-recipes","gluten-free-recipes","grilling-ideas-and-recipes","iconic-dishes","lamb-recipes","main-dishes","middle-eastern-recipes","quick-and-easy","roast-lamb","roasts","slow-cooked-fall-apart","slow-cooker-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_75e43303c8ff', 'en', 'US', 'Smoked Salmon Dip', 'A wonderful dip to impress! It has a beautiful smoked salmon flavour, it''s soft and creamy, with a fabulous fresh lemon and dill flavour. Store bought is completely incomparable - typically too hard, too sour and the smoked salmon flavour is barely there plus probably not real because real smoked salmon has a shelf life of only 3 to 5 days once opened! Makes 2 cups. Recipe VIDEO below.', 'https://www.recipetineats.com/tachyon/2017/12/Smoked-Salmon-Dip-5a.jpg', 5, 0, 5, 6, '[{"id": "ing_salmon_fillets", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_cream_cheese", "quantity": {"value": 200.0, "unit": "block of 250g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.15, "unit": "tub of 250g"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.094, "unit": "jar of 400g"}}, {"id": "ing_dill", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.167, "unit": "pack of 3 heads"}}, {"id": "ing_lemon", "quantity": {"value": 0.015, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.015, "unit": "net of 500g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["200 g / 7 oz smoked salmon (or trout)","200 g / 7 oz Philadelphia cream cheese (, full fat)","1/4 cup / 55g sour cream (Note 1)","1/4 cup / 60g mayonnaise (Note 1, 2)","1/4 cup fresh dill (, roughly chopped)","1/2 garlic clove (, minced)","1 1/2 tsp lemon zest (1 lemon)","1 - 2 tbsp lemon juice","Pinch of salt and pepper"]}]', '[{"description":"Place all ingredients in a food processor, starting with 1 tbsp lemon juice. Only use a small pinch of salt to start because smoked salmon is salty, also bear in mind saltiness of crackers being used.","images":[],"step":1},{"title":"Whizz until fairly smooth","description":"about 10 seconds on high - scraping sides as required.","images":[],"step":2},{"description":"Adjust lemon and salt to taste. Whizz again briefly.","images":[],"step":3},{"description":"Transfer into bowl, garnish with lemon slices and more dill if desired. Serve at room temperature with crackers - I like using melba toasts and mini crostinis.","images":[],"step":4}]', '["fish","milk"]', '["gluten_free","low_calorie"]', '{"mealType":["main_course"],"cuisine":[],"categories":["australia-day","dietary","dip-recipes","fish-recipes","gluten-free-recipes","quick-and-easy","salmon-recipes","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_27c046944521', 'en', 'US', '5 Great Prawn Dipping Sauces', 'Choose from a classic pink Marie Rose / Thousand Island sauce, Tartare, Seafood Cocktail Sauce, a Thai Sweet Chilli Lime Sauce for something fresher (not everyone likes mayo!) or our Family Favourite Prawn Dipping Sauce, a cross between Marie Rose and Tartare with more freshness and flavour. See notes for description of each sauce. All these sauces will be great with any seafood (fish, squid) and especially with lobster, crab, balmain bugs, scallops etc. No video today - these are all just dump and mix!!', 'https://www.recipetineats.com/tachyon/2017/12/Prawn-Dipping-Sauces-7-1.jpg', 5, 0, 5, 1, '[{"id": "ing_tomato", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.037, "unit": "jar of 400g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_dash_tabasco", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_lemon", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_corn", "quantity": {"value": 0.037, "unit": "can of 400g"}}, {"id": "ing_dill", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_capers_drained_and", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_sugar", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_ketchup", "quantity": {"value": 0.2, "unit": "bottle of 500g"}}, {"id": "ing_horseradish", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_dash_tabasco", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_chilli", "quantity": {"value": 0.75, "unit": "pack of 100g"}}, {"id": "ing_ime_juice", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.075, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.417, "unit": "pack of 3 heads"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_corn", "quantity": {"value": 0.037, "unit": "can of 400g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.025, "unit": "bunch"}}, {"id": "ing_dill", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_or_so_dashes_of_tabasco", "quantity": {"value": 4.0, "unit": "unit"}}]', '[{"ingredients":["2/3 cup / 160 g tomato ketchup","1 tbsp mayonnaise","1/4 tsp each mustard powder (or Dijon), onion powder, garlic powder, white sugar","Dash Tabasco","1 tsp lemon juice, fresh","1 tsp Worcestershire Sauce","Salt and pepper"],"purpose":"COCKTAIL SAUCE:"},{"ingredients":["1 cup / 220g mayonnaise (Note 1)","1 tbsp gherkin/cornichon, very finely chopped","1 1/2 tsp fresh dill, finely chopped","1 tsp fresh parsley, chopped","1 tsp capers, drained and finely chopped","1.5 tbsp lemon juice, fresh","1/2 tsp white sugar","1/4 tsp salt"],"purpose":"TARTARE SAUCE"},{"ingredients":["2/3 cup / 145g mayonnaise (Note 1)","1 tbsp ketchup","1 tsp Worcestershire Sauce","1 tsp fresh horseradish (or sub 1 1/2 tsp jarred)","Dash of Tabasco","Pinch cayenne pepper"],"purpose":"MARIE ROSE"},{"ingredients":["5 tbsp / 75g Sweet Chilli Sauce, store bought (I use Trident)","2/3 cup / 165 ml lime juice, fresh (4 - 5 limes)","5 tbsp / 75 ml olive oil (can sub with neutral oil like canola)","1 garlic clove, minced","1 tbsp white sugar (or other)","1/4 cup coriander / cilantro leaves, finely chopped"],"purpose":"THAI LIME SWEET CHILLI SAUCE"},{"ingredients":["2/3 cup / 145g mayonnaise (Note 1)","1/3 cup / 80 g ketchup","1 1/2 tbsp capers, drained and finely chopped","1 1/2 tbsp gherkin/cornichon, finely chopped","1 1/2 tbsp eschallot or onion, finely chopped","1/4 cup dill leaves, finely chopped","1 dash Worcestershire Sauce","4 or so dashes of Tabasco","1 tbsp lemon juice (adjust to taste)"],"purpose":"RECIPETIN FAMILY FAVOURITE"}]', '[{"description":"All sauces except Thai Sauce:","images":[],"step":1},{"description":"Place ingredients in a bowl and mix to combine.","images":[],"step":2},{"description":"Adjust salt to taste (Note 3).","images":[],"step":3},{"description":"Place all ingredients except coriander in a bowl, whisk well. Stir through coriander and add salt and pepper to taste. Rest 20 minutes before using.","images":[],"step":4}]', '["mustard"]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["snack"],"cuisine":[],"categories":["australia-day","prawns-shrimp","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9d63ee5aedd4', 'en', 'US', 'Doner Kebab recipe', 'Recipe VIDEO above. A homemade version of the chicken kebab rolls you get at your favourite kebab shop! It tastes remarkably similar to the kebab shop chicken meat. I oven bake it, but imagine it rotisserie style over the BBQ or charcoal! You will need 4 long metal skewers for this, around 30cm / 12" long.', 'https://www.recipetineats.com/tachyon/2017/11/Chicken-Doner-Kebab-1.jpg', 20, 55, 1515, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_yogurt", "quantity": {"value": 0.3, "unit": "tub of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_hummus", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_tabbouleh", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 7.5, "unit": "pack of 1kg"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_mejadra_for_kebab_plate", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["1 kg / 2 lb chicken thighs (, skinless and boneless (Note 1))","Olive oil (, for drizzling)"]},{"ingredients":["1 cup plain yoghurt (, unsweetened (I use Greek))","3 garlic cloves minced","1 1/2 tsp coriander powder","2 tsp cumin powder","2 tsp paprika","1 tsp cayenne pepper (, optional)","1 1/2 tsp onion powder","1/2 tsp black pepper","2 1/2 tbsp tomato paste","1 1/2 tsp cooking salt / kosher salt","1 tbsp lemon juice (substitute apple cider vinegar)","2 tbsp olive oil"],"purpose":"Marinade:"},{"ingredients":["Lebanese bread / flatbreads / pita bread (, warmed)","Finely sliced iceberg lettuce","Tomato slices","Hummus (or Note 2 for simple Yoghurt Sauce)","Tabbouleh (optional, Note 3)","Red onion slices","Shredded cheese","Chilli Sauce (I use Sriracha, it''s perfect)","Mejadra ((Middle Eastern Rice with Lentils), for Kebab Plate)"],"purpose":"For Serving (choose):"}]', '[{"title":"Marinade","description":"Mix Marinade in a large bowl. Add chicken and mix to coat well. Cover and marinate in the fridge for a minimum of 3 hours, 24 hours is ideal. If only 3 hours, add an extra 1/2 tsp salt.","images":[],"step":1},{"description":"Preheat oven to 220°C / 430°F (200°C fan-forced).","images":[],"step":2},{"description":"Choose a pan of a size such that the skewers will stay propped up on the pan walls (see photos in post or video) and the chicken will be elevated off the base. Line with foil.","images":[],"step":3},{"title":"Thread onto skewers","description":"Remove chicken from fridge. Divide the chicken into 2 piles. Take one piece of chicken, fold in half then thread onto two skewers (see video). Repeat and push the chicken snugly up against each other. Repeat with other skewer.","images":[],"step":4},{"description":"Prop the 2 skewers on the edges of the baking pan. Drizzle surface with oil.","images":[],"step":5},{"description":"Bake for 35 minutes or until the surface is golden with some charred bits (char is good!). Spoon the pan juices over the chicken. Turn, drizzle with oil and bake for a further 20 minutes. If you want more colour, oven grill/broil for a few minutes on high (I don''t do this).","duration":35,"images":[],"step":6},{"title":"Rest 5 minutes","description":"Baste again with pan juices and stand for 5 minutes.","duration":5,"images":[],"step":7},{"title":"Carving","description":"Stand the skewers upright or on an angle, and slice meat fairly thinly. Use to make Doner Kebabs or Kebab Plates.","images":[],"step":8},{"description":"Making Doner Kebabs rolls:","images":[],"step":9},{"description":"Place a lebanese bread (or pita bread or other flatbread) on a piece of foil. Spread with a generous dollop of Hummus (or yoghurt sauce - Note 2). Top with shredded lettuce, slices of tomato, Tabbouleh (for a truly authentic experience! Note 3), cheese (I usually go this) and Chicken. Drizzle with chilli sauce if desired (I use Sriracha, it''s perfect).","images":[],"step":10},{"description":"Roll up tightly and wrap in foil. Consume and be happy!","images":[],"step":11},{"description":"Serve chicken with Mejadra (Middle Eastern Spiced Rice with Lentils), shredded lettuce, tomatoes, slices of red onion, tabbouleh, dollop of hummus. Optional to serve flatbread / lebanese bread on the side.","images":[],"step":12}]', '["gluten","milk"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Turkish"],"categories":["australia-day","chicken-breast-recipes","chicken-recipes","dietary","gluten-free-recipes","mediterranean-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_72dec9df4e75', 'en', 'US', 'Steak Sandwich', 'A juicy steak sandwich, piled high with tender slices of steak, tomato, lettuce, caramelised onion, garlic aioli and mustard. The caramelised onion really gives this a "gourmet" spin but see notes for faster suggestions.', 'https://www.recipetineats.com/tachyon/2017/01/Steak-Sandwich-9.jpg', 10, 60, 70, 4, '[{"id": "ing_mayonnaise", "quantity": {"value": 0.281, "unit": "jar of 400g"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 3000.0, "unit": "pack of 1kg"}}, {"id": "ing_butter", "quantity": {"value": 40.0, "unit": "block of 250g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_balsamic_vinegar", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_beef_steak", "quantity": {"value": 600.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 1.2, "unit": "head"}}, {"id": "ing_mustard", "quantity": {"value": 0.005, "unit": "jar of 200g"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["3/4 cup mayonnaise (, preferably whole egg)","1 large garlic clove (, minced)"],"purpose":"Quick Garlic Aioli (Note 1)"},{"ingredients":["3 large onions (, peeled and finely sliced (brown, white or yellow))","40 g / 3 tbsp butter","2 tbsp brown sugar","1 tbsp balsamic vinegar","1/4 tsp salt & pepper"],"purpose":"Caramelised Onion (Note 2)"},{"ingredients":["600 - 700 g / 1.2 - 1.4 lb grilling beef steak (Note 3)","Salt and pepper","1 tbsp vegetable oil","2 tomatoes (, thickly sliced)","60 g / 2 oz rocket /arugula or other lettuce of choice","Mustard (I use American)","Turkish bread (, about 60cm / 2 feet long (or 4 rolls / buns of choice))"],"purpose":"Steak Sandwich"}]', '[{"title":"Garlic Aioli","description":"Mix mayonnaise and garlic together. Set aside for 30 minutes+ for the flavour to develop (do not keep for more than 3 days tops).","duration":30,"images":[],"step":1},{"title":"Caramelised Onion","description":"Melt butter in a skillet over medium low heat. Add onions and stir to coat in butter. Place lid on (or place a baking tray over skillet) and leave for 20 minutes, stirring once or twice. Remove lid then cook for a further 20 minutes, stirring every now and then, until onion is golden (increase heat slightly if the colour is not changing). Add sugar, vinegar, salt and pepper. Cook for a further 10 minutes until jammy. Remove from heat and keep warm.","duration":20,"images":[],"step":2},{"description":"Take beef out of fridge 20 minutes before cooking. Season generously with salt and pepper.","images":[],"step":3},{"description":"Heat oil in a skillet over high heat (or heat BBQ). Cook steak to your liking - if using a secondary cut like Bavette, skirt or flat iron, it''s best medium rare.","images":[],"step":4},{"description":"Transfer beef to a plate, cover loosely with foil and rest for 5 - 10 minutes. Then slice thinlyagainst the grain.","duration":7.5,"images":[],"step":5},{"description":"Assemble sandwich","images":[],"step":6},{"description":"Cut turkish bread into 15cm/6\" lengths and split into half. Toast lightly.","images":[],"step":7},{"description":"Spread the bottom piece generously with garlic aioli. Top with rocket, then tomato slices, beef, caramelised onion. Spread the top piece of bread with mustard then place on top.","images":[],"step":8}]', '["egg","gluten","milk","mustard"]', '["high_protein"]', '{"mealType":["main_course"],"cuisine":[],"categories":["australia-day","beef-recipes","dinner-tonight","grilling-ideas-and-recipes","main-dishes","quick-and-easy","sandwiches-and-sliders"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_386f5b692d01', 'en', 'US', 'Pavlova!!', 'Recipe video above. A classic Aussie Pav recipe with my tips that make all the difference, especially during hot humid summers which make Pavs prone to collapsing during or after baking. Top your Pav with whatever fruit you want!', 'https://www.recipetineats.com/tachyon/2016/12/Pavlova-3-SQ.jpg', 10, 90, 100, 10, '[{"id": "ing_egg", "quantity": {"value": 12.5, "unit": "carton of 12"}}, {"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.037, "unit": "pack of 400g"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.5, "unit": "carton of 250ml"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_strawberries", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}]', '[{"ingredients":["150 ml / 5 oz egg whites (4-5 eggs fridge cold eggs) (Note 1)","1 cup caster sugar (superfine sugar)","1 tbsp cornflour / cornstarch, sifted","1 tsp white vinegar"]},{"ingredients":["1 1/2 cups thickened cream / heavy cream (any whipping cream)","1/4 cup caster sugar (superfine sugar)","1 tsp vanilla extract or essence"],"purpose":"Cream"},{"ingredients":["Fruit of choice. I used: raspberries, blueberries, strawberries and cherries."],"purpose":"Topping"}]', '[{"description":"Separate the whites and yolks while eggs are cold. Measure 150 ml/5oz egg whites (just shy of 2/3 cup, 140 - 160ml is ok).","images":[],"step":1},{"description":"Set whites aside to come to room temperature.","images":[],"step":2},{"description":"Preheat oven to 170°C/340°F (180°C fan-forced).","images":[],"step":3},{"description":"Place whites in a bowl. Use a stand mixer (I use speed 7) or handheld beater (high) and beat until soft peaks form (Note 2)","images":[],"step":4},{"description":"Add sugar 1 tbsp at a time, beating as you go. (Note 3)","images":[],"step":5},{"description":"After adding the sugar, beat for a further 3 minutes or until thick and glossy. Rub a little of the fluff between your fingers, there should be no sugar grit - that means it is ready.","images":[],"step":6},{"title":"Add cornflour and vinegar, beat on low for 5","description":"7 seconds (or fold through with spatula) until just mixed through.","duration":0.1,"images":[],"step":7},{"description":"Making the Pav (Note 4)","images":[],"step":8},{"description":"Get the base of a springform cake pan (24cm/9.5\" or larger) and turn it upside down. Dab meringue on the edge and place a piece of baking paper (parchment paper) on top.","images":[],"step":9},{"description":"Gently place half the fluff onto the paper. Use the cake pan as a guide to make it round and coax it into a circle shape around 20cm / 8\" in diameter (Note 5).","images":[],"step":10},{"description":"Carefully scoop out the remaining fluff. Now coax it into a dome shape (not a cake with straight smooth sides) with edges sloping in slightly. Flatten top. Make it 4-5cm / 2 \" high - not much higher. (Note 5). See video / photos in post. It will rise/expand.","images":[],"step":11},{"description":"Transfer to baking tray. CAREFULLY place in the oven, GENTLY close the door and turn oven DOWN to 115°C/240°F (100°C fan).","images":[],"step":12},{"title":"Bake for 1 1/2 hours","description":"no peeking, no thundering through kitchen! (Note 6)","images":[],"step":13},{"description":"Turn oven off, leave the door closed and leave Pav in the oven overnight to cool (I''ve done 18 hours).","images":[],"step":14},{"description":"Transfer Pav to serving platter then slide cake pan out from underneath. Use butter knife if required to loosen edges from paper, then slide paper out from underneath.","images":[],"step":15},{"description":"Just before serving, top with cream and fruit of choice.","images":[],"step":16},{"description":"Serve and be a rock star!","images":[],"step":17},{"description":"Place cream, sugar and vanilla in a bowl. Beat cream until it is thickened and just holds its shape - don''t overbeat, it should be silky smooth, not speckled with bubbles and stiff.","images":[],"step":18}]', '["egg","milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Australian"],"categories":["australia-day","baking-recipes","dessert-recipes","dietary","easter-baking-desserts","egg-white-recipes","gluten-free-recipes","iconic-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e45e5e8ae8a5', 'en', 'US', 'Ripper Beef Nachos', 'The nachos cheese sauce takes 5 minutes to make and will take your nachos to the next level, ensuring even coverage of cheese goodness over every chip! You can substitute the homemade Nachos Seasoning with 1 packet store bought taco seasoning.', 'https://www.recipetineats.com/tachyon/2016/01/Beef-Nachos_2b.jpg', 20, 15, 35, 8, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_beef", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_corn", "quantity": {"value": 0.992, "unit": "can of 400g"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_quantity_proper_guacamole", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_quantity_pico_de_gallo", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}]', '[{"ingredients":["1 tbsp olive oil","2 garlic cloves","1/2 onion (, finely chopped)","1 lb / 500g ground beef (mince)","2 tbsp tomato paste","2 tbsp water"],"purpose":"Beef"},{"ingredients":["1 tsp each onion powder ((Note 1), dried oregano, salt)","2 tsp each dried cumin powder (, paprika)","1/4 tsp cayenne pepper (, or to taste)"],"purpose":"Nachos Seasoning"},{"ingredients":["14 oz / 400g corn chips (, good quality (Note 2))","2 cups grated cheese (cheddar, tasty, gruyere, Monterey Jack)","1 quantity Nachos Cheese Sauce (, warm (Note 3))"],"purpose":"Nachos"},{"ingredients":["Sliced scallions / shallots","1 quantity Proper Guacamole (, Restaurant Style)","1 quantity Pico de Gallo (Note 4)","Sour cream"],"purpose":"Sides/Garnish"}]', '[{"title":"Beef","description":"Heat oil in a skillet over high heat. Add garlic and onion, cook until translucent. Add beef and cook, breaking it up as you go. Once beef is cooked, add Nachos Seasoning, tomato paste and water. Cook for a further 2 minutes, then set aside.","images":[],"step":1},{"description":"Preheat oven to 180C/350F.","images":[],"step":2},{"description":"Spread half the corn chips in a single layer on a baking tray. Drizzle over about 1 cup Nachos Cheese Sauce (see KEY TIPS in Note 3), top with 1/2 the Beef and 1/2 the grated cheese ensuring most of the Cheese Sauce is covered.","images":[],"step":3},{"description":"Spread over remaining corn chips, drizzle over remaining Nachos Cheese Sauce, Beef and grated cheese, again ensuring all the Cheese Sauce is covered.","images":[],"step":4},{"description":"Bake for 15 minutes or until cheese is melted.","duration":15,"images":[],"step":5},{"description":"Serve immediately, garnished with sliced scallions/shallots if using and with Guacamole, Pico de Galloand Sour Cream on the side.","images":[],"step":6}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Tex-Mex"],"categories":["australia-day","beef-mince-recipes","beef-recipes","dietary","gluten-free-recipes","mexican-recipes","nachos-recipes","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e3c9a9974434', 'en', 'US', 'Cheese and Bacon Potato Skins', 'My potato skins are made extra crispy and extra tasty by brushing them with bacon fat!', 'https://www.recipetineats.com/tachyon/2016/01/Cheese-Bacon-Potato-Skins_5.jpg', 10, 45, 55, 6, '[{"id": "ing_potato", "quantity": {"value": 2.0, "unit": "bag of 2kg"}}, {"id": "ing_bacon", "quantity": {"value": 10.0, "unit": "pack of 200g"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[]', '[{"description":"Prepare Potato Skins","images":[],"step":1},{"description":"Prick each potato 4 times with a fork, then place them on the outer edge of the microwave turntable. Microwave on high for 8 minutes, then turn the potatoes and microwave on high for another 8 minutes.","duration":8,"images":[],"step":2},{"description":"Use a sharp knife to cut the potatoes in half. Use a spoon to scoop out the potato, leaving a thin skin about 1/2cm/ 1/6\" thick.","images":[],"step":3},{"description":"Preheat oven to 180C/350F.","images":[],"step":4},{"description":"Spread bacon on a tray and bake for 8 minutes, or until LIGHT golden and the fat has melted.","duration":8,"images":[],"step":5},{"description":"Remove bacon onto a paper towel lined plate using a slotting spoon. RESERVE bacon fat on tray.","images":[],"step":6},{"description":"Crisp Potato Skins","images":[],"step":7},{"description":"Place potato skins upside down on the tray. Use a brush to brush the bacon fat on the tray onto the potato skin. Sprinkle with salt and pepper.","images":[],"step":8},{"description":"Bake for 15 to 20 minutes, or until the skin is quite crispy.","duration":17.5,"images":[],"step":9},{"description":"Fill Potato Skins","images":[],"step":10},{"description":"Remove baking tray from the oven and turn the potato skins over.","images":[],"step":11},{"description":"Sprinkle with salt and pepper. Fill the potato skins with 2/3 of the bacon, then top with cheese.","images":[],"step":12},{"description":"Top with remaining bacon.","images":[],"step":13},{"description":"Bake for 10 minutes or until cheese is melted.","duration":10,"images":[],"step":14},{"description":"To serve","images":[],"step":15},{"description":"Serve with sour cream, sprinkled with scallions.","images":[],"step":16}]', '["milk"]', '["gluten_free"]', '{"mealType":["main_course"],"cuisine":[],"categories":["australia-day","dietary","finger-food","gluten-free-recipes","most-popular","potato-recipes","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_dee6efc2464a', 'en', 'US', 'Magic Spanish Romesco Sauce / Dip', '45 million Spaniards can''t be wrong! There is a reason why this is the national sauce of Spain - it''s incredibly versatile and delicious! Use it as a sauce, dip, spread and as pesto - or even as a marinade! Romesco sauce is smoky and creamy, but so much healthier than normal dips. It''s like pesto - with a fraction of the calories!', 'https://www.recipetineats.com/tachyon/2016/01/Magic-Spanish-Romesco-Sauce_1.jpg', 5, 30, 35, 2, '[{"id": "ing_capsicum", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_bread", "quantity": {"value": 0.1, "unit": "loaf"}}, {"id": "ing_almonds", "quantity": {"value": 0.3, "unit": "pack of 250g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2 red capsicum / bell peppers (Note 1)","1 tomato","5 garlic cloves","3 tbsp extra virgin olive oil","2 slices white sandwich bread (, crusts removed (Note 2))","1/2 cup natural almonds (Note 3)","1 tbsp sherry vinegar (or red or white wine vinegar)","1 tbsp smoked paprika","1/4 tsp cayenne pepper (optional)","1 tsp salt"]}]', '[{"description":"Preheat barbecue grill OR gas stove on high and chargrill capsicum using until black and blistered all over. (Note 4)","images":[],"step":1},{"description":"Place in a bowl and cover for at least 20 minutes. The capsicum will cool down and sweat, allowing the skin to slide off easily. Peel and discard the skin, and the seeds, place in blender.","images":[],"step":2},{"description":"Preheat oven to 180C/350F. Place tomato and garlic on foil, drizzle with 2 tsp oil, and wrap.","images":[],"step":3},{"description":"Place foil packet on a tray, add bread and almonds onto the tray. Bake for 5 minutes until bread is golden, remove almonds and bread. Tear bread into pieces, place in blender with almonds.","duration":5,"images":[],"step":4},{"description":"Bake garlic and tomato for a further 25 minutes or until tomato is tender. Open foil, allow to cool until you can handle it. Peel tomato, add to blender. Squeeze garlic from skins, place in blender.","images":[],"step":5},{"description":"Add remaining ingredients, whizz until smooth. Adjust salt and pepper to taste.","images":[],"step":6},{"description":"Store in the fridge for up to 1 week. Refer to Notes for ideas for how to use!","images":[],"step":7}]', '["gluten"]', '["vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Spanish"],"categories":["australia-day","dip-recipes","mediterranean-recipes","side-dishes","spanish-recipes","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b338b87e00e2', 'en', 'US', 'Ham and Cheese Puffs', 'Recipe video above. Cute little bites that require only 5 ingredients and are absolutely irresistible! Fabulous way to use up leftover Christmas ham to a finger food for New Years Eve .', 'https://www.recipetineats.com/tachyon/2015/12/Ham-Cheese-Puffs_2.jpg', 15, 15, 30, 18, '[{"id": "ing_sheet_puff_pastry", "quantity": {"value": 2.0, "unit": "pack"}}, {"id": "ing_mustard", "quantity": {"value": 4.0, "unit": "jar of 200g"}}, {"id": "ing_shaved_ham", "quantity": {"value": 0.227, "unit": "kg"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}]', '[{"ingredients":["2 sheets puff pastry (, 25cm/10\" square)","4 - 5 tbsp Dijon mustard","8 oz/250g shaved ham","2 cups shredded cheddar cheese (or any other melting cheese) (Note 1)","2 egg yolks (or 1 egg - Note 2)","Oil spray"]}]', '[{"description":"Preheat oven to 200°C/425°F (180°C fan-forced). Spray 2 baking trays lightly with oil or line with baking paper (parchment paper).","images":[],"step":1},{"title":"Puff pastry","description":"Let the puff pastry partially defrost then cut into 9 x 8cm/3.5\" squares.","images":[],"step":2},{"description":"Spread about 1/2 tsp of mustard diagonally across each square.","images":[],"step":3},{"description":"Top with ham and sprinkle with cheese.","images":[],"step":4},{"title":"Wrap","description":"Dab one corner with egg yolk using a brush. Fold the opposite corner over the filling first, then fold the corner with the egg yolk over it and press down to bond. Place on baking tray then repeating with remaining squares.","images":[],"step":5},{"title":"Bake","description":"Brush the top with egg. Bake for 15 minutes or until deep golden brown and puffed.","duration":15,"images":[],"step":6},{"description":"Serve warm!","images":[],"step":7}]', '["egg","milk","mustard"]', '["gluten_free"]', '{"mealType":["snack"],"cuisine":["Western"],"categories":["australia-day","finger-food","leftover-ham-recipes","quick-and-easy","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bd9f86c133f5', 'en', 'US', 'Garlic Bread Mini Pizzas (Muffin Tin)', 'These mini pizzas are made using bread! Brushed with garlic butter so this really does taste like a cross between garlic bread and pizza. The filling options are endless - use your favourite pizza toppings.', 'https://www.recipetineats.com/tachyon/2015/10/Garlic-Bread-Mini-Pizza_600px_Featured.jpg', 15, 10, 25, 12, '[{"id": "ing_bread", "quantity": {"value": 0.6, "unit": "loaf"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_pizza_sauce", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 37.5, "unit": "pack of 1kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 0.75, "unit": "block of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.75, "unit": "jar of 50g"}}]', '[{"ingredients":["12 slices white sandwich bread (, fresh (Note 1))","2 tbsp butter","2 garlic cloves (, crushed)","1/8 tsp salt","1/2 cup pizza sauce (Note 2)","1/4 cup red onion (, finely diced)","1/3 cup mushroom (, finely chopped)","3/4 cup grated cheese (, melting (I used a mix of mozzarella and tasty, equal amounts))","1/4 cup sliced small pepperoni (Note 3)"]}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Use a large empty can (800g/28oz canned tomato can) to cut out rounds from the bread. (Note 4)","images":[],"step":2},{"description":"Mould into a muffin tin.","images":[],"step":3},{"description":"Place butter, garlic and salt in a microwave-proof bowl or mug and microwave in 30 second increments until the butter is melted.","images":[],"step":4},{"description":"Brush cups with butter, ensuring you use the garlic too.","images":[],"step":5},{"description":"Divide the pizza sauce between the cups, then top with onion and mushrooms.","images":[],"step":6},{"description":"Top with cheese then with pepperoni.","images":[],"step":7},{"description":"Bake for 10 to 15 minutes, or until the cheese is melted and bread is golden on the edges.","duration":12.5,"images":[],"step":8},{"description":"Serve warm!","images":[],"step":9}]', '["gluten","milk"]', '["keto_friendly","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["australia-day","finger-food","quick-and-easy","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b16203be9bf0', 'en', 'US', 'Browned Butter Garlic Prawns with Cauliflower Puree', 'Simple and elegant. This is my copycat of a meal I had at a posh restaurant in the city which cost 4 times as much as making it at home! Please use fresh prawns for this, not frozen ones. It makes a huge difference. Believe me, I''ve tried this with frozen before - not good!', 'https://www.recipetineats.com/tachyon/2015/09/Garlic-Brown-Butter-Prawns_1-Featured.jpg', 10, 10, 20, 2, '[{"id": "ing_shrimp", "quantity": {"value": 0.283, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_wine", "quantity": {"value": 0.06, "unit": "bottle of 750ml"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_cauliflower", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_milk", "quantity": {"value": 0.333, "unit": "L"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["10 oz / 300 g peeled prawns (12 to 14 large prawns) (about 500g whole unpeeled prawns)","2 cloves garlic (, crushed)","2 tbsp olive oil","Salt and pepper","3 tbsp white wine"],"purpose":"Garlic Prawns"},{"ingredients":["3 tbsp salted butter","2 garlic cloves (, smashed (Note 1))"],"purpose":"Browned Butter"},{"ingredients":["1/2 medium cauliflower (, broken into florets)","1 to 3 tbsp butter (or to taste)","1/3 to 2/3 cup milk","Salt and pepper"],"purpose":"Cauliflower Puree"},{"ingredients":["Parsley (, finely chopped)"],"purpose":"To Serve"}]', '[{"title":"Garlic Prawns","description":"Combine ingredients except the wine in a bowl, using your fingers to toss gently. Set aside for 10 minutes.","duration":10,"images":[],"step":1},{"title":"Cauliflower Puree","description":"Cook the cauliflower in boiling water until soft - about 10 minutes. Drain and allow to cool slightly. Transfer cauliflower to a blender or food processor, add butter, 1/3 cup of milk, salt and pepper. Puree until smooth, using extra milk to get the texture to your liking. Leave in the blender with the lid on to keep warm.","images":[],"step":2},{"description":"Browned Butter","images":[],"step":3},{"description":"Place the butter and garlic in a small silver saucepan or small silver fry pan over medium heat. After a few minutes, the butter will start to foam. Then it will begin to turn brown, begin to smell nutty and little brown flecks will appear.","images":[],"step":4},{"description":"When the garlic is a golden brown colour, transfer to a small bowl (I pick them out with chopsticks).","images":[],"step":5},{"description":"When the butter turns a golden brown colour, remove from the stove. Carefully pour the butter into the bowl with the garlic, leaving the brown specks in the saucepan (they are a bit bitter). You should have about 2 tbsp of browned butter.","images":[],"step":6},{"description":"Cook Prawns","images":[],"step":7},{"description":"Heat a skillet over high heat (no oil). Add the prawns and cook for 50 seconds or until the underside has just a hint of golden brown. Turn and cook the other side for 30 seconds, then add the wine and cook for another 30 seconds or until the wine has evaporated.","duration":0.8333333333333334,"images":[],"step":8},{"description":"To Serve","images":[],"step":9},{"description":"Spread about 1 cup of Cauliflower Puree onto a plate. Top with half the prawns, drizzle with browned butter and sprinkle with parsley.","images":[],"step":10}]', '["milk"]', '["gluten_free","high_protein","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["australia-day","dietary","dinner-tonight","easter-mains-fish-seafood","gluten-free-recipes","grilling-ideas-and-recipes","main-dishes","most-popular","prawns-shrimp","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_97f611fadbd2', 'en', 'US', 'Coconut Marinated Chicken (Grill or Stove)', 'Coconut milk is a fantastic marinade which tenderises the chicken and infuses it with rich flavour. The added bonus is that the marinade doubles as a scrumptious sauce! Cook this on your BBQ or stovetop.', 'https://www.recipetineats.com/tachyon/2015/08/Coconut-Marinated-Chicken_2-Featured.jpg', 10, 15, 25, 4, '[{"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_imes_all_the_zest_3_tbsp_of_juice", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.3, "unit": "jar of 50g"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_hot_sauce", "quantity": {"value": 0.2, "unit": "bottle of 150ml"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.68, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 can coconut milk (preferably full fat, but light is ok) (14oz/400g)","2 limes - all the zest + 3 tbsp of juice","1 tbsp mild curry powder","2 tsp paprika","1 tbsp fresh ginger (, finely grated)","3 garlic cloves (, crushed)","2 tbsp Frank''s classic hot sauce (, or other hot sauce of choice (adjust to taste) (Note 2))","3/4 tsp salt","Black pepper"],"purpose":"Marinade"},{"ingredients":["1.5 lb / 750g chicken thigh fillets (, skinless and boneless)","1 tbsp oil (for cooking)","3/4 cup water"],"purpose":"Chicken"},{"ingredients":["Fresh coriander leaves"],"purpose":"Garnish (optional)"}]', '[{"description":"Combine the Marinade ingredients in a ziplock bag. Add the chicken and set aside to marinate for at least 3 hours, preferably overnight.","images":[],"step":1},{"description":"Remove the chicken from the Marinade, shaking off the excess. Keep the Marinade for the Sauce (below).","images":[],"step":2},{"description":"Brush the BBQ with oil and heat to medium high, or heat the oil in a skillet over medium high heat.","images":[],"step":3},{"description":"Cook the chicken for around 7 minutes on the first side and 5 minutes on the second side, or until cooked through.","images":[],"step":4},{"description":"Transfer the chicken to a plate, cover loosely with foil and rest for 5 minutes.","duration":5,"images":[],"step":5},{"description":"Serve with Sauce and garnished with fresh cilantro leaves, if using.","images":[],"step":6},{"description":"Pour the marinade into a small saucepan over medium heat.","images":[],"step":7},{"description":"Add the water and bring to a simmer. Cook for at least 10 minutes, or until thickened to desired consistency. (Note 1) Transfer to a sauce bowl.","images":[],"step":8}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Tropical!"],"categories":["australia-day","chicken-breast-recipes","chicken-recipes","dietary","gluten-free-recipes","grilling-ideas-and-recipes","most-popular","quick-and-easy","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_972cfb6e9cec', 'en', 'US', 'Italian Dressing Chicken Marinade', 'Italian Dressing Chicken Marinade is an Italian Chicken Marinade that doubles as a salad dressing! This is one of my tricks for easy midweek meals and it''s a highly effective method to make delicious meals with less effort. I''ve made a zucchini side salad here, but feel free to use the dressing for ANY salad you want!', 'https://www.recipetineats.com/tachyon/2015/07/Italian-Marinated-Grilled-Chicken_680px_1.jpg', 10, 10, 20, 4, '[{"id": "ing_vinegar", "quantity": {"value": 0.068, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_mixed_italian_herbs", "quantity": {"value": 2.5, "unit": "unit"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_zucchini", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_mint", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["4 1/2 tbsp white wine vinegar (Note 1)","2 cloves garlic","2 tbsp extra virgin olive oil","1 tbsp dijon mustard","1 1/2 tsp sugar","1 tsp salt","Black pepper"],"purpose":"Dressing Marinade"},{"ingredients":["1/2 tbsp olive oil","2 1/2 tsp mixed Italian dried herbs (either a packet mix or mix herbs like basil, parsley, oregano, rosemary and thyme)","1 tsp dried red chili flakes (optional)","750 g / 1.5lb chicken thighs, boneless skinless, or breast (cut in half horizontally)"],"purpose":"Marinated Chicken"},{"ingredients":["1 tbsp extra virgin olive oil","2 zucchinis (, finely sliced into rounds using a mandolin)","2 tbsp baby mint leaves (, or 1 tbsp sliced larger mint leaves)"],"purpose":"Zucchini Side"}]', '[{"description":"Place the Dressing Marinade ingredients in a small jar and shake well to combine.","images":[],"step":1},{"description":"Marinade Chicken:","images":[],"step":2},{"description":"Put the Marinated Chicken ingredients in a bowl or ziplock bag and add 5 tablespoons of the Dressing Marinade.","images":[],"step":3},{"description":"Massage / mix to coat the chicken. Set aside for marinade for at least 20 minutes, ideally 3 hours or up to 24 hours.","images":[],"step":4},{"description":"Cook Chicken:","images":[],"step":5},{"title":"Grill/BBQ","description":"You shouldn''t need any oil, but if you are concerned, brush your grill with oil. Heat the grill on medium high and cook the chicken for around 3 to 4 minutes on each side. (Cook breast for less)","images":[],"step":6},{"title":"Stove","description":"Preheat 1/2 tbsp oil in a large non stick fry pan over medium high heat. Add the chicken and cook each side for around 4 to 5 minutes, or until dark golden brown and cooked through.","images":[],"step":7},{"description":"When the chicken is cooked, remove it from the grill/fry pan onto a plate, loosely cover with foil and set aside for 10 minutes.","duration":10,"images":[],"step":8},{"description":"Serve the chicken with the zucchini salad and toasted bread.","images":[],"step":9},{"description":"Salad & Dressing:","images":[],"step":10},{"description":"Add the 1 tablespoon of olive oil (from the Zucchini Side ingredients) into the jar with the remaining Dressing Marinade and shake well. Set aside.","images":[],"step":11},{"description":"Toss the zucchinis and mint with the Dressing Marinade.","images":[],"step":12}]', '["mustard"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["main_course"],"cuisine":["American-Italian","Italian"],"categories":["australia-day","chicken-breast-recipes","chicken-recipes","dietary","gluten-free-recipes","grilling-ideas-and-recipes","italian-recipes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ac9573256b05', 'en', 'US', 'Lemon Garlic Baked Ricotta', 'Super fast and easy to make, a fabulous dip / spread for your next party! Keep the topping garnishes simple or as creative as you want - I''ve provided some suggestions below.', 'https://www.recipetineats.com/tachyon/2015/06/Baked-Ricotta-Both_680px_1.jpg', 5, 15, 20, 8, '[{"id": "ing_ricotta", "quantity": {"value": 1.2, "unit": "tub of 250g"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 2.0, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}]', '[{"ingredients":["2 cups of full fat ricotta (, the best you can afford)","1 to 3 tbsp full fat cream or milk (, optional (only required if you aren''t using fresh Italian ricotta))","Zest of 1 lemon","2 medium garlic cloves (, minced)","1/4 tsp salt","2 tbsp olive oil"]}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Place the ricotta in a bowl. If you are using supermarket ricotta (as opposed to fresh Italian ricotta), it might be a bit dry. Use the cream or milk to loosen the ricotta into creamy \"peanut butter\" type consistency (ie. easily spreadable).","images":[],"step":2},{"description":"Add the lemon, garlic and salt and mix to combine.","images":[],"step":3},{"description":"Get to 1 cup capacity ramekins or any other oven proof dish (I used tapas dishes). Divide the ricotta between the dishes and drizzle over 1 tbsp olive oil (reserve other tbsp for after baking).","images":[],"step":4},{"description":"Bake for 15 to 20 minutes until the top is lightly browned.","duration":17.5,"images":[],"step":5},{"description":"Remove from oven, drizzle with remaining 1 tbsp olive oil then serve immediately with toasted pieces of bread (tip: rub lightly with garlic - it''s amazing!).","images":[],"step":6},{"description":"Garnish options (optional)","images":[],"step":7},{"description":"Fresh thyme, parsley or any other herbs, finely chopped (pictured)","images":[],"step":8},{"description":"Chopped tomatoes, red onion and parsley (pictured)","images":[],"step":9},{"description":"Finely chopped antipasto (eg olives, sun dried tomatoes)","images":[],"step":10}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["australia-day","dietary","gluten-free-recipes","quick-and-easy","side-dishes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1c5738f6af0d', 'en', 'US', 'Cheesy Jalapeno Bacon Stuffed Baguette with Garlic Butter', 'A new idea for party food! This is great for making ahead. Just assemble then pop it in the freezer until you need it, then all you have to do is bake them when you are ready to serve! So many options for fillings....I''ve provided a few more ideas in the notes.', 'https://www.recipetineats.com/tachyon/2015/05/Stuffed-Baguette_680px_MAIN.jpg', 15, 20, 35, 25, '[{"id": "ing_oil", "quantity": {"value": 7.5, "unit": "bottle"}}, {"id": "ing_bacon", "quantity": {"value": 1.134, "unit": "pack of 200g"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_cream_cheese", "quantity": {"value": 8.0, "unit": "block of 250g"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.4, "unit": "pack of 125g"}}, {"id": "ing_packed_jalape_os", "quantity": {"value": 0.25, "unit": "unit"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1/2 tbsp oil","8 oz / 250g bacon, diced (I used lean bacon)","1 x 20\" / 50 cm baguette / french stick","8 oz / 250g Philadelphia cream cheese, softened (full or low fat)","1 cup cheddar cheese, shredded (Note 1)","1/2 cup mozzarella cheese, shredded","1/4 cup packed jalapeños, finely chopped (if using fresh, deseed it. Or use canned, drained)","1 cup finely chopped scallions/shallots, green and white part (packed)","Black pepper"]},{"ingredients":["3 tbsp butter","2 garlic cloves, minced","Pinch of salt"],"purpose":"Garlic butter"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Heat oil in a pan over high heat. Add bacon and cook until lightly browned. Remove onto a plate lined with a paper towel to drain excess fat. Set aside to cool.","images":[],"step":2},{"description":"Cut the ends off the baguette and cut the baguette in half (or quarters - makes it easier to stuff).","images":[],"step":3},{"description":"Use a long knife (preferably bread knife) to cut the bread out, leaving about a 1/2\" / 1.5cm wall of bread and crust. (Note 2)","images":[],"step":4},{"description":"Place the bacon, cream cheese, cheddar and mozzarella cheese, jalapeños, scallions/shallots and pepper in a bowl and mix until combined.","images":[],"step":5},{"description":"Use a knife or piping bag to stuff the mixture inside the baguettes.","images":[],"step":6},{"title":"Garlic Butter","description":"melt butter with the garlic and salt in the microwave or on the stove.","images":[],"step":7},{"description":"Brush the baguette with garlic butter (or you can do this after you slice it).","images":[],"step":8},{"description":"Slice the baguette into 1 1/4cm / 1/2\" slices.","images":[],"step":9},{"description":"Keep the slices pressed up against each other, and transfer to a large piece of foil.","images":[],"step":10},{"description":"Wrap the baguette, then bake for 15 to 20 minutes, or until the bread is crusty and the cheese inside is melted.","duration":17.5,"images":[],"step":11},{"description":"For optimal experience, serve warm!","images":[],"step":12}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["main_course"],"cuisine":[],"categories":["australia-day","most-popular","side-dishes","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_359e75b4a8ed', 'en', 'US', 'Ricotta and Spinach Puff Pastry Bites', 'A cute twist on the typical cheese and spinach triangles. These are great because you get more out of one sheet of puff pastry because the ration of filling to pastry is higher than usual! The shape of these puffs are adapted from Bon Appetit.', 'https://www.recipetineats.com/tachyon/2015/04/Cheese-Spinach-Puffs-2_680px.jpg', 10, 15, 25, 15, '[{"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_ricotta", "quantity": {"value": 0.794, "unit": "tub of 250g"}}, {"id": "ing_spinach", "quantity": {"value": 8.0, "unit": "bag of 250g"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 0.75, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_sheets_puff_pastry_defrosted", "quantity": {"value": 2.0, "unit": "pack"}}]', '[{"ingredients":["1 egg","7 oz / 200g ricotta (preferably full fat but low fat also works) (Note 1)","8 oz / 250g frozen chopped spinach (, thawed and squeezed of excess water)","3/4 cup grated cheddar cheese (or tasty or gruyere or any other melting cheese with flavour)","3/4 tsp salt","Black pepper"],"purpose":"Filling"},{"ingredients":["2 sheets puff pastry ((25cm/10\" square), defrosted)","1 egg (, lightly beaten (egg wash))"],"purpose":"Pastry"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Spray 2 standard muffin / cupcake tins with oil.","images":[],"step":2},{"description":"Place egg in a bowl and lightly whisk. Add remaining Filling ingredients and mix to combine. Taste and adjust salt to taste.","images":[],"step":3},{"description":"Cut each pastry into 9 equal pieces (18 in total). You probably won''t use 3 pieces.","images":[],"step":4},{"description":"Mould 15 pieces of pastry into the muffin tins.","images":[],"step":5},{"description":"Divide the Filling between each, then bring the four corners into the centre and press down to stick together. Don''t overfill otherwise you won''t be able to seal the pastries or they will burst open when baking (which regularly happens with mine).","images":[],"step":6},{"description":"Brush with egg wash, then bake for 15 to 20 minutes or until deep golden brown.","duration":17.5,"images":[],"step":7},{"description":"Allow to rest for 5 minutes before removing.","duration":5,"images":[],"step":8},{"description":"Serve warm or cool.","images":[],"step":9}]', '["egg","milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["snack"],"cuisine":[],"categories":["australia-day","breakfast-recipes","finger-food","quick-and-easy","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2d0f21e13b53', 'en', 'US', 'Double Cheese and Bacon Rolls', 'Not only topped but also STUFFED with bacon and cheese! Just like the ones from Baker''s Delight (bakery chain in Australia) - but better because there''s a double hit of bacon and cheese! Directions provided for Active Dry Yeast and Instant Yeast.', 'https://www.recipetineats.com/tachyon/2015/02/DSC_0391.jpg', 20, 25, 45, 8, '[{"id": "ing_yeast", "quantity": {"value": 1.0, "unit": "pack of 5 sachets"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_bread", "quantity": {"value": 0.562, "unit": "loaf"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_bacon", "quantity": {"value": 1.5, "unit": "pack of 200g"}}, {"id": "ing_cheese", "quantity": {"value": 3.5, "unit": "block of 250g"}}, {"id": "ing_cheese", "quantity": {"value": 3.5, "unit": "block of 250g"}}]', '[{"ingredients":["1 sachet Active Dry Yeast (7g, 1/4oz, 2 1/4 tsp (US, AUS), 2 tsp UK) (see Note 1 for Instant Yeast)","2 tsp caster sugar (or granulated or super fine white sugar)","1 cup warm water (Not boiling. Just tap water is fine)","3 cups bread flour (Note 2)","1 tsp salt","1 tbsp olive oil (or sub with any other oil)","1 egg (, lightly beaten)"],"purpose":"Bread Roll"},{"ingredients":["300 g / 10 oz bacon (, diced)","3.5 oz / 100g provolone cheese (, cut into 8 slices (or any other melting cheese) (Note 3))","1 cup grated cheese (tasty, cheddar or any other cheese that melts)"],"purpose":"Topping"}]', '[{"description":"Combine the yeast, sugar and water in a bowl and mix until yeast dissolves. Set aside in a warm place for 10 minutes until frothy. (Note 4)","duration":10,"images":[],"step":1},{"description":"Combine the flour and salt in a bowl. Add the yeast mixture and olive oil. Then either use the dough hook on your mixer and mix for about 3 minutes on medium low, or knead by hand on a lightly floured surface (about 100 kneads), until the dough is smooth and elastic. It should come away from the side of the bowl and shouldn''t stick. If it is too sticky, add some extra flour.","images":[],"step":2},{"description":"Place the dough in a bowl and cover loosely. (Note 5) Set aside in a warm place for 1 hour or until doubled in size. (Note 4)","images":[],"step":3},{"description":"Meanwhile, sauté half the bacon in a non stick pan over high heat until lightly browned. Remove from pan and set aside to cool.","images":[],"step":4},{"description":"Spray baking tray with oil.","images":[],"step":5},{"description":"Punch down the dough, then cut into 8 pieces.","images":[],"step":6},{"description":"Get one piece of dough and flatten it. Take a piece of provolone cheese and fold it in half to form a square. Top with 1 tbsp of cooked bacon. Fold the edges in to \"wrap\" it, shaping it into a round shape. Seal then flip over and place on baking try. Flatten with your hand to around 2cm / 4/5\" thick. Repeat with remaining dough.","images":[],"step":7},{"description":"Brush with egg mixture. Top each with 1 1/2 tbsp grated cheese and the uncooked bacon.","images":[],"step":8},{"description":"Cover with clean tea towel and set aside for 30 minutes or so in a warm place until it has risen by around 50% (Note 6).","duration":30,"images":[],"step":9},{"description":"Preheat oven to 180C/350F.","images":[],"step":10},{"description":"Bake for 20 to 25 minutes or until they are golden brown.","duration":22.5,"images":[],"step":11},{"description":"Best served warm, so the filling is gooey!","images":[],"step":12}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["main_course"],"cuisine":[],"categories":["australia-day","breads","breakfast-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_67145580b45c', 'en', 'US', 'Spicy Little Muffin Tin Chicken Tostadas', 'A great little party appetiser that are really fast to prepare! The tostada cups will stay fresh in an airtight container for around 3 days. The chicken filling can be made 2 days ahead and stored in the refrigerator. Don''t be afraid of the amount of jalapeños used! The heat is tempered considerably when mixed in with the mayonnaise, and also canned jalapeños are not as spicy as fresh. It is a zingy kick of spice but won''t blow your head off. :) This makes 10 mini tostadas.', 'https://www.recipetineats.com/tachyon/2015/02/Spicy-Little-Muffin-Tin-Chicken-Tostadas-31.jpg', 15, 15, 30, 10, '[{"id": "ing_tortillas", "quantity": {"value": 2.0, "unit": "pack of 8"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.094, "unit": "jar of 400g"}}, {"id": "ing_jalape_o", "quantity": {"value": 0.25, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_lime", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.5, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_chicken", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["2 to 3 tortillas (flour or corn)","Oil spray"]},{"ingredients":["1/4 cup whole egg mayonnaise","1/4 cup finely chopped canned jalapeño (, drained (Note 1))","1 1/2 tsp salt","1/2 tsp black pepper","1 tbsp lime juice (or more to taste)","1/2 cup sliced shallots/scallions (or 1/4 cup finely diced red onion)","2 tbsp finely diced coriander/cilantro stems","1 1/4 cups shredded cooked chicken (plain, unseasoned)"],"purpose":"Filling"},{"ingredients":["Coriander/cilantro leaves","Diced avocado"],"purpose":"Garnish"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Cut out 10 rounds using a 7.5cm/3\" round cutter OR 400g/14oz empty, clean can. You should be able to get 5 out of each tortilla.","images":[],"step":2},{"description":"Mould into standard size muffin tins. Spray with oil, then bake for 10 to 15 minutes until golden brown and crisp. Allow to cool in the muffin tin then set aside until required in an airtight container.","duration":12.5,"images":[],"step":3},{"description":"Place all the Filling ingredients except the chicken in a bowl and mix to combine. Then add the chicken and toss gently to coat.","images":[],"step":4},{"description":"To serve, divide the chicken filling between the tostada cups. Sprinkle with coriander/cilantro leaves and avocado.","images":[],"step":5}]', '["egg","gluten"]', '["keto_friendly","low_calorie"]', '{"mealType":["snack"],"cuisine":["Mexican-esque"],"categories":["australia-day","chicken-breast-recipes","chicken-recipes","dietary","finger-food","gluten-free-recipes","mexican-recipes","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_45d3aee876a7', 'en', 'US', 'Pull Apart Pizza Bread', 'Party food you can make ahead, freeze and can even be reheated in the microwave without it going soggy! Every piece of bread you pull out is like a mini pizza!', 'https://www.recipetineats.com/tachyon/2015/01/DSC_0377.jpg', 15, 30, 45, 8, '[{"id": "ing_butter", "quantity": {"value": 0.333, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_pizza_sauce", "quantity": {"value": 50.0, "unit": "bottle"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.25, "unit": "pack of 125g"}}, {"id": "ing_black_pepper", "quantity": {"value": 2.268, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 0.25, "unit": "pack of 1kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}]', '[{"ingredients":["1/3 cup salted butter","1 garlic clove (, minced (or 2 if you like really garlicky))","1 baguette / french (, 60cm / 2 feet long (or multiple short ones))","1/3 cup pizza sauce","1 1/4 to 1 1/2 cups grated mozzarella cheese (Notes 1 and 2)","4 oz / 120g pepperoni (, sliced or diced (I used mini pepperoni))","1/4 red onion (, finely diced (optional))","1/2 tbsp fresh parsley (, finely diced (optional))"]}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Melt butter with the garlic in it.","images":[],"step":2},{"title":"Cut the french stick into 1.5","description":"2 cm / 3/5\" - 4/5\" thick slices (about 25 slices, including ends) and lay them out on a work surface.","images":[],"step":3},{"description":"Brush butter on each slice, ensuring to dab some garlic on. Use most but not all the butter.","images":[],"step":4},{"description":"Spread a small dab of pizza sauce on each piece of bread, top with onion, cheese then pepperoni (in this order).","images":[],"step":5},{"description":"Stack 6 or 7 pieces of bread on top of each other. Then pick up the stack (hold the top and bottom pieces) and place it in a 22cm / 8\" square baking dish. (See photos below) (Note 3)","images":[],"step":6},{"description":"Brush the top of the bread with the remaining butter.","images":[],"step":7},{"description":"Cover with foil and bake for 15 minutes, or until cheese is mostly melted. Then remove the foil and bake for 10 minutes or until golden brown and crusty (to your liking).","duration":15,"images":[],"step":8},{"description":"Remove from oven, sprinkle with parsley (if using) and serve immediately!","images":[],"step":9}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["australia-day","most-popular","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6065692cc38b', 'en', 'US', 'Party Pies (Aussie Mini Beef Pies)', 'Classic Aussie fare - a meat pie with a beef filling that''s been braised until tender. Great food for parties that freezes extremely well! The great thing about mini pies is that you can make them in pie tins, muffin tins or even cupcake trays! Just make sure to cut the rounds so they fit the tin that you use.', 'https://www.recipetineats.com/tachyon/2015/01/Party-Pies-Mini-Beef-Pies-3.jpg', 25, 25, 50, 16, '[{"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_beef_steak", "quantity": {"value": 1.361, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_wine", "quantity": {"value": 0.333, "unit": "bottle of 750ml"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.2, "unit": "jar of 50g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.113, "unit": "pack of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_frozen_shortcrust_pastry_sheets_thawed", "quantity": {"value": 4.0, "unit": "pack"}}, {"id": "ing_sheets_frozen_puff_pastry_thawed", "quantity": {"value": 4.0, "unit": "pack"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}]', '[{"ingredients":["3 tbsp olive oil","3 lb / 1.5kg chuck steak (, cut into 1cm / 2/5\" cubes (or other beef cut suitable for slow cooking))","2 onions (, peeled and diced (brown, yellow or white))","3 garlic cloves (, minced)","2 tbsp tomato paste","4 cups / 1 litre / 1 quart beef stock/broth","1 cup red wine (anything dry and dark, not light like pinot noir)","2 dried bay leaves (or 3 fresh)","1 1/2 tsp salt (, plus more to taste)","2 tsp black pepper","3 tbsp cornstarch (cornflour)","4 tbsp water"],"purpose":"Filling"},{"ingredients":["1 egg yolk (, lightly beaten (or 1 whole egg, for a slightly less dark golden finish))","4 sheets frozen shortcrust pastry ((25cm x 25cm / 10\" x 10\"), thawed)","3 - 4 sheets frozen puff pastry (25cm x 25cm / 10\" x 10\"), thawed (Note 1)"],"purpose":"Pastry"},{"ingredients":["Tomato Sauce / Tomato Ketchup"],"purpose":"To Serve"}]', '[{"description":"Place 1 tbsp of oil in a large heavy based pot over high heat. Add half the beef and sear until the outside is lightly browned. Remove from the pot into a bowl and repeat with remaining beef.","images":[],"step":1},{"description":"Lower the heat to medium high and add the remaining olive oil. Add the onion and garlic and sauté until the onion is translucent - around 5 minutes.","images":[],"step":2},{"description":"Return the beef to the pot along with all other Filling ingredients other than the cornstarch / cornflour and water. Mix to combine. The liquid should be just enough to cover most of the beef but there should be a bit protruding through the surface.","images":[],"step":3},{"description":"Bring to a simmer, then lower the heat to low / medium low so it is bubbling very gently. Leave to cook for 50 minutes to 1 hour, stirring occasionally, or until the beef is very tender. Because the beef is cut so small, it shouldn''t take much longer than 1 hour. If the liquid evaporates too quickly, just add a bit more water.","duration":50,"images":[],"step":4},{"description":"When the beef is ready (or almost ready), mix the cornstarch / cornflour and water together then pour it into the pot. Mix through and allow to cook for 5 minutes to thicken the sauce. Adjust salt to taste.","duration":5,"images":[],"step":5},{"description":"Remove pot from the stove and set aside to cool. The sauce will thicken more when it cools.","images":[],"step":6},{"description":"Assemble the Pies","images":[],"step":7},{"description":"Preheat oven to 180C/350F.","images":[],"step":8},{"description":"Spray 16 holes of Texas muffin tins or pie tins (8cm / 3.2\" diameter across top). I made half in muffin tins and half in pie tins.","images":[],"step":9},{"description":"Cut the pastry base out of the shortcrust pastry using a 10 cm/ 4\" round cutter (I use an empty 800g/14oz canned tomato tin - perfect size). This fits both the pie and muffin tins.","images":[],"step":10},{"description":"Press the rounds into the tins and fill to the brim with the Filling.","images":[],"step":11},{"description":"Cut the pie tops out of the puff pastry using a 8 cm / 3.2\" round cutter (a scone cutter is the perfect size).","images":[],"step":12},{"description":"Place the lids on top of the filling, gently pressing to try to join the top with the casing.","images":[],"step":13},{"description":"Pearce the lids 3 or 4 times with a small knife. Brush with egg wash. Bake for 20 to 25 minutes until dark golden brown (or deep golden brown if you used a whole egg for the wash).","duration":22.5,"images":[],"step":14},{"description":"Allow to rest for a few minutes before turning out onto a wire rack. Serve very warm with tomato sauce (tomato ketchup).","images":[],"step":15}]', '["egg"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["main_course"],"cuisine":["Australian"],"categories":["australia-day","beef-recipes","finger-food","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a33bf53d793d', 'en', 'US', 'Cheese Truffles (Mini Cheese Balls)', 'These mini cheese balls are cute and a nice change up from the usual giant cheese balls you see. You don''t have to worry about the giant cheese ball becoming a mess when people get stuck into it because each ball is a single serving and you get to use different coatings to make a kaleidoscope of colours! I''ve provided 3 different fillings so you can choose which one you want to make (or make all three!). In the photo you see, I made all 3 but you can''t tell in the photo because the filling of all 3 look pretty much the same.', 'https://www.recipetineats.com/tachyon/2014/12/Cheese-Truffles-1370-2.jpg', 15, 0, 15, 18, '[{"id": "ing_cream_cheese", "quantity": {"value": 8.0, "unit": "block of 250g"}}, {"id": "ing_cheese", "quantity": {"value": 8.0, "unit": "block of 250g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 2.5, "unit": "bottle"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 8.0, "unit": "block of 250g"}}, {"id": "ing_feta_cheese", "quantity": {"value": 10.0, "unit": "block of 200g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.06, "unit": "tub of 250g"}}, {"id": "ing_herbs", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}, {"id": "ing_walnuts", "quantity": {"value": 50.0, "unit": "jar"}}, {"id": "ing_cranberries", "quantity": {"value": 0.05, "unit": "kg"}}]', '[{"ingredients":["8 oz / 250g cream cheese (, softened)","1 cup grated cheese (tasty, cheddar or any other cheese with flavour)","1/2 tsp garlic powder","1/2 tsp worcestershire sauce","Salt to taste"],"purpose":"Cream Cheese Filling (makes 18)"},{"ingredients":["10 oz / 300g goats cheese"],"purpose":"Goats Cheese Filling (makes 18)"},{"ingredients":["10 oz / 300g Danish feta (Note 1)","1 cup grated cheese (tasty, cheddar or any other cheese with flavour)","1 tbsp sour cream (or approximately 2 tsp of milk or water)"],"purpose":"Feta Cheese Filling (makes 18)"},{"ingredients":["1/4 cup finely chopped fresh herbs (I used parsley and dill)","1/4 cup parmesan cheese (, finely shredded or grated)","1/3 cup walnuts (, finely chopped)","1/3 cup dried cranberries (, finely chopped)"],"purpose":"Coatings - to coat 18 balls in total (Note 2)"}]', '[{"title":"Cream Cheese Filling","description":"place ingredients in a bowl and mix well until combined. Adjust salt to taste.","images":[],"step":1},{"title":"Feta Cheese Filling","description":"place ingredients in a bowl and mix well until combined.","images":[],"step":2},{"title":"Make the balls","description":"measure out 1 tbsp of filling and use a teaspoon to scoop the filling out of the tablespoon and place onto a tray or cutting board. Once you have scooped out all the filling, use your hands to roll into balls. Refrigerate for 3 to 4 hours.","images":[],"step":3},{"description":"Place the Coatings into small bowls.","images":[],"step":4},{"description":"Roll the cheese balls in the Coatings.","images":[],"step":5},{"description":"Refrigerate the cheese balls until ready to serve.","images":[],"step":6},{"description":"Take them out of the fridge around 15 minutes before serving (so they are spreadable).","images":[],"step":7},{"description":"Serve with crackers or pieces of toasted bread.","images":[],"step":8}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["snack"],"cuisine":[],"categories":["australia-day","dietary","gluten-free-recipes","most-popular","quick-and-easy","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_22c26dea8dff', 'en', 'US', 'Avocado salad', 'Recipe video above. This is my favourite avocado salad. Cooling cucumber with creamy avocado, tangy lime juice, optional fresh herbs and my secret ingredient - a pinch of red pepper flakes which keeps things interesting! Doesn''t make it spicy, more of a slight cooling hum of earthy warmth.', 'https://www.recipetineats.com/tachyon/2023/11/Avocado-salad_0.jpg', 10, 0, 10, 4, '[{"id": "ing_avocado", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_cucumber", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 0.25, "unit": "pack of 1kg"}}, {"id": "ing_dill", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_lime", "quantity": {"value": 0.09, "unit": "net of 500g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}]', '[{"ingredients":["2 big ripe avocados (, cut into quarters then 1 cm / 0.4\" slices)","3 cucumbers ( ~17cm/7\" long, sliced into 4mm / 1/6\" rounds (Note 1))","1/4 red onion (, finely sliced)","2 tbsp dill (, finely chopped, optional recommended (Note 2))","2 tbsp coriander/cilantro leaves (,roughly chopped, optional recommended (Note 2))"],"purpose":"Salad:"},{"ingredients":["3 tbsp extra virgin olive oil","3 tbsp lime juice (, or lemon juice (or more, adjust to taste!))","1/4 tsp chilli flakes / red pepper flakes","1/4 tsp black pepper","3/4 tsp cooking / kosher salt"],"purpose":"Dressing:"}]', '[{"description":"Put all the salad ingredients in large bowl. Drizzle over lime juice and oil, sprinkle with salt, pepper and red chilli flakes.","images":[],"step":1},{"description":"Toss gently using your hands, gently separating the avocado slices as you go. Taste and add more lime if you want.","images":[],"step":2},{"description":"Tumble into a bowl and serve!","images":[],"step":3}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Western"],"categories":["avocado","cucumber","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_415d24541499', 'en', 'US', 'Strawberry Avocado Salad', 'Recipe video above. A show off salad to impress! Skip the pecans to make it a quick ''n easy salad for anytime. This makes a BIG salad for sharing (8 - 10 as side). Scale recipe down if needed (click Servings and slide!)', 'https://www.recipetineats.com/tachyon/2019/05/Strawberry-Salad-with-Avocado_6.jpg', 20, 5, 25, 8, '[{"id": "ing_baby_spinach", "quantity": {"value": 180.0, "unit": "bag of 250g"}}, {"id": "ing_onion", "quantity": {"value": 15.0, "unit": "pack of 1kg"}}, {"id": "ing_strawberries", "quantity": {"value": 1.5, "unit": "punnet of 250g"}}, {"id": "ing_avocado", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_feta_cheese", "quantity": {"value": 120.0, "unit": "block of 200g"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_pecans", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 15.0, "unit": "pack of 1kg"}}, {"id": "ing_vinegar", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.075, "unit": "L"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.056, "unit": "jar of 400g"}}, {"id": "ing_poppyseeds", "quantity": {"value": 15.0, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["180g / 6 oz baby spinach","1 red onion ((small), halved and finely sliced)","375g / 12 oz ripe strawberries (, sliced (Note 1))","2 avocados (, quartered and sliced (Note 2))","120g / 4oz feta (, crumbled)"],"purpose":"Salad:"},{"ingredients":["1 tbsp (15g) butter, unsalted","3 tbsp white sugar","1 cup pecans (, roughly chopped)"],"purpose":"Candied Pecans (Note 3):"},{"ingredients":["1 tbsp eschallots ((French onion), very finely chopped)","2.5 tbsp white wine vinegar","5 tbsp olive oil","1.5 tbsp mayonnaise","1 tbsp white sugar","1 tbsp poppyseeds","3/4 tsp salt","1/4 tsp black pepper"],"purpose":"Poppyseed Dressing:"}]', '[{"description":"Place Dressing ingredients in a jar and shake well. Set aside for 10 minutes+ (keeps for a week).","duration":10,"images":[],"step":1},{"description":"Candied Pecans:","images":[],"step":2},{"description":"Place butter and sugar in a non stick skillet over medium high. When butter is melted, add nuts.","images":[],"step":3},{"title":"Stir 5 minutes","description":"sugar will go sandy, then eventually melt into a caramel.","images":[],"step":4},{"description":"Once sugar melts, cook for 2 minutes then spread pecans out on tray.","duration":2,"images":[],"step":5},{"description":"Cool then break to separate.","images":[],"step":6},{"description":"Assemble Salad:","images":[],"step":7},{"description":"Place spinach and onion in a bowl, drizzle with about 3 tbsp Dressing, toss.","images":[],"step":8},{"description":"Transfer 1/3 spinach in a bowl. Scatter over 1/3 of each strawberries, avocado, feta, pecans. Drizzle with a bit of dressing.","images":[],"step":9},{"description":"Top with another 1/3 spinach, strawberries, avocado, feta, pecans, then a bit more Dressing. Repeat once more.","images":[],"step":10},{"description":"Serve immediately!","images":[],"step":11}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Western"],"categories":["avocado","salad-recipes-main-course","side-dishes","side-salads","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3344dbe9889e', 'en', 'US', 'French Apple Cake', 'Recipe video above. This is a lovely simple recipe for a traditional French Apple Cake that my mum made almost every week when I was growing up in France. My version is almost the same as my Mum’s, but I changed it slightly - I can''t help it, I''m a chef! The cake is beautifully moist and can be served warm (for me, the best way!) or at room temperature with some vanilla ice cream or whipped cream on the side.Rum option - I know some recipes add rum to this cake, but my mum never did, so this version doesn’t include any. However, if you would like to add some, 1 tablespoon of dark or spiced rum works beautifully. It won’t change the texture, but it adds a lovely warmth and gently perfumes the cake 😊.', 'https://www.recipetineats.com/tachyon/2026/05/French-Apple-Cake-4.jpg', 20, 30, 65, 8, '[{"id": "ing_apples", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 250.0, "unit": "carton of 12"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_flour", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.042, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.004, "unit": "carton of 250ml"}}]', '[{"ingredients":["3 red apples - I like Pink Lady (, peeled and diced into 1.5cm/0.6\" cubes (~ 3 1/2 cups) (Note 1 for other varieties))","100g(7 tbsp) unsalted butter, softened","3/4 cup caster sugar / superfine sugar (Note 2)","3 large eggs (, at room temperature (55g/2oz each in shell))","1 tsp vanilla extract (, natural / pure)","1 1/3 cups plain flour / all-purpose flour","1 1/4 tsp baking powder","1/4 tsp cooking salt / kosher salt"]},{"ingredients":["Icing sugar / powdered sugar (, for dusting)","Vanilla ice cream"],"purpose":"For serving:"}]', '[{"description":"Cream butter then sugar. Beat in eggs one at a time, then vanilla. Beat in dry ingredients, stir through apple. Bake in 23cm/9\" pan at 180°C/350°F (160°C fan) for 30 minutes.","duration":30,"images":[],"step":1},{"description":"Preheat the oven to 180°C/350°F (160°C fan-forced).","images":[],"step":2},{"title":"Cake pan","description":"Butter a 23cm/9\" round cake pan and line the base with baking paper / parchment paper. No need to line the sides.","images":[],"step":3},{"title":"Dry ingredients","description":"In a separate bowl, whisk together the flour, baking powder and salt.","images":[],"step":4},{"title":"Cream butter and sugar","description":"Using a handheld beater or stand mixer with the paddle attachment, beat the butter for 1 minute on medium until creamed. Add the sugar and beat on medium for 1 minute until fluffy and becomes a paler yellow.","duration":1,"images":[],"step":5},{"title":"Eggs and vanilla","description":"Add the eggs one at a time, mixing well after each addition. Beat in the vanilla extract.","images":[],"step":6},{"description":"Add the flour mixture into the bowl and beat on low until you can no longer see dry flour, then stop beating. You don''t want to overmix.","images":[],"step":7},{"title":"Apples","description":"Stir through the diced apples using a spatula. The batter will be quite thick, it''s not pourable.","images":[],"step":8},{"title":"Bake","description":"Spread the batter evenly into the prepared cake pan. Bake for 35 minutes, or until a skewer inserted in the centre comes out clean (because the batter is quite thick and if your oven runs a bit cool, it could take up to 45 minutes). (Note 3)","duration":35,"images":[],"step":9},{"title":"Rest and serve","description":"Let the cake rest for 5 minutes in the pan before removing. Cool for a further 10 minutes then serve warm or let it cool completely on a wire rack. Dust with icing sugar, if desired. If serving warm, it''s especially lovely with a scoop of ice cream.","duration":5,"images":[],"step":10}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["French"],"categories":["baking-recipes","cosy-desserts","dessert-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_55e073d4476d', 'en', 'US', 'My Favourite Chocolate Frosting', 'Recipe video above. My favourite Chocolate Frosting tastes like the most delicious chocolate mousse you''ve ever had. It’s beautifully creamy, completely smooth, with a rich chocolate flavour and far less sweet than buttercream. It''s essentially a cross between buttercream and chocolate ganache, lightened with the use of cream cheese rather than more butter.Pastry chefs will recognise its crèmeux-like texture, but there''s no eggs in this. It''s sturdier than whipped cream, so it''s a brilliant all-rounder that can be piped into tall swirls on cupcakes or spreading in cake layers without squishing out when cut.Cream cheese is the key ingredient - provides fluffed volume and structure (rather than using excessive amounts of butter), but you won''t taste any tang!PS Just to be clear - this is still sweet! It''s a frosting, after all :) But it has 70% less sugar than the equivalent volume of buttercream.----------------------Yield - 1.2 kg, 6 cups of frosting. See Note 1 for what this is enough for.', 'https://www.recipetineats.com/tachyon/2026/04/My-Favourite-Chocolate-Frosting_9.jpg', 30, 2, 32, 6, '[{"id": "ing_chocolate", "quantity": {"value": 200.0, "unit": "block of 100g"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_cocoa_powder", "quantity": {"value": 0.15, "unit": "pack of 250g"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_cream_cheese", "quantity": {"value": 250.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.1, "unit": "kg"}}]', '[{"ingredients":["200 g / 7 oz dark chocolate chips or melts (semi-sweet chocolate chips), or chopped block (Note 2)","3/4 cup thickened cream / heavy cream (, or other whipping cream 35 - 40% fat (Note 3))","1/4 cup dutch processed cocoa powder (no need to sift), or regular unsweetened cocoa powder (Note 4)"],"purpose":"Chocolate base:"},{"ingredients":["100 g / 7 tbsp unsalted butter (, softened (or use salted and skip salt))","250 g soft icing sugar / powdered sugar (, sifted (Note 5))","250 g / 8 oz Philadelphia cream cheese block (not tub), at room temperature (Note 6)","1/2 cup thickened cream / heavy cream (, fridge cold)","1/4 tsp cooking salt / kosher salt (halve for table salt, +50% for flakes)"],"purpose":"Chocolate frosting:"}]', '[{"description":"Bloom cocoa with cream for 5 min. Melt chocolate, mix with bloomed cocoa, cool 15 minutes. Beat butter, then icing sugar (goes sandy), then cream cheese until smooth. Beat in chocolate. Chill 2 hrs. Add cream, whip to stiff peaks. Use immediately to frost or pipe.","duration":5,"images":[],"step":1},{"title":"Bloom cocoa","description":"Heat the cream in a heatproof bowl until hot but make sure it doesn''t come to a boil. Add cocoa powder and whisk until lump free - it will be like a thin paste. Set aside 5 minutes to bloom (brings out chocolate flavour).","images":[],"step":2},{"title":"Melt chocolate","description":"Place the chocolate chips in a heatproof bowl and melt in the microwave in bursts until smooth - 30 seconds on high, stir, then 20 second increments.","images":[],"step":3},{"title":"Chocolate paste","description":"Add the cocoa paste into the melted chocolate. Whisk until combined and smooth, it will be like a thin paste. Cool for 15 minutes on the counter - it will thicken. Don''t worry if a skin forms on the surface, it will beat out in the next step.","duration":15,"images":[],"step":4},{"title":"Cream cheese whip","description":"In a separate large bowl, beat butter with a handheld mixer until soft and fluffy (about 1 1/2 minutes on high). Add icing sugar and beat until it resembles wet sand (~ 30 seconds). Add cream cheese and beat until smooth and creamy (~30 seconds), stopping once no yellow butter bits remain.","images":[],"step":5},{"title":"Beat in chocolate","description":"Add all the chocolate paste and beat until combined.","images":[],"step":6},{"title":"Refrigerate","description":"Cover the bowl with cling wrap and refrigerate for 2 hours until properly fridge-cold (stick the beaters in the bowl). This gives the frosting structure. You can leave it in the fridge at this point for days.","images":[],"step":7},{"title":"Fluff frosting","description":"Remove bowl from the fridge. Add cream and salt. Beat on high for 1 1/2 minutes or until you have stiff peaks (ie upright Santa hats, not floppy elf hat). The frosting should be beautifully creamy like buttercream but also fluffy like whipped cream - better taste test to check! It will be a little pale - it darkens once piped/spread.","images":[],"step":8},{"title":"Frost","description":"Use immediately to frost cakes and pipe onto cupcakes - spread with knife/offset spatula or transfer into piping bag. (Note 6 on thickness) Ideally, refrigerate frosted cakes for at least 30 minutes to let the frosting set before serving.","images":[],"step":9},{"description":"Holding and serving notes","images":[],"step":10},{"description":"Once set, the frosting will hold its shape in the fridge and will not deflate. It does not harden in the fridge so can be enjoyed fridge cold, though I personally prefer my cakes at room temperature. When out of the fridge, keep it out of the sun - the frosting melts more easily than buttercream, but is much more stable than whipped cream.","images":[],"step":11}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["baking-recipes","dessert-recipes","frosting-and-icing"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_820c8a70f1bc', 'en', 'US', 'Galettes Bretonnes (Brittany Butter Biscuits)', 'Recipe video above. Galettes Bretonnes are classic French butter biscuits from Brittany and one of my favourite! Known for their rich slightly salty flavour, delicate sandy crumb and their melt-in-the-mouth texture, they’re a staple in shops across France. Yet they’ve always felt personal to me because my grandmother would always buy some for me as a child. They still take me right back, so here’s my recipe to make them at home.', 'https://www.recipetineats.com/tachyon/2026/04/Galettes-Bretonnes-French-Butter-Biscuits_0.jpg', 30, 30, 75, 24, '[{"id": "ing_butter", "quantity": {"value": 180.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_flour", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.005, "unit": "L"}}]', '[{"ingredients":["180g / 12 tbsp salted butter (, softened (Note 1))","2/3 cup caster sugar / superfine sugar (Note 2)","1 egg yolk (, from large eggs (55g/2oz each in shell), at room temperature (Note 3))","1 tsp vanilla extract","2 cups plain flour / all-purpose flour"]},{"ingredients":["1 egg yolk (, from large eggs (55g/2oz each in shell), at room temperature )","1 tsp milk"],"purpose":"Egg wash"}]', '[{"description":"Cream butter and sugar. Beat in yolk and vanilla, then beat in flour in 3 batches. Turn out, knead into ball, refrigerate 1 hr. Roll out into 5mm/0.2\" thickness, cut out 7cm/2.8\" rounds (24 pieces). Brush with egg wash, score cross design with fork, bake 15 min @ 180°C / 350°F (160°C fan).","images":[],"step":1},{"title":"Cream butter & sugar","description":"Place butter in a bowl and beat for 30 seconds using an electric beater on low speed. Then add sugar and beat for 1 minute on medium until fluffy and slightly paler in colour.","duration":0.5,"images":[],"step":2},{"description":"Beat in egg yolk and vanilla, just until combined then stop beating.","images":[],"step":3},{"title":"Make dough","description":"Add 1/3 of the flour to the mixture and mix still using the beater on medium low speed. Once incorporated, add half of the remaining flour then mix and repeat with the remaining flour. It will resemble like wet sand. Turn out onto the work surface and use your hands to bring it together, then knead it into a smooth ball of dough.","images":[],"step":4},{"title":"Rest","description":"Wrap in cling film and refrigerate for 1 hour. (Note 4)","images":[],"step":5},{"description":"Preheat oven to 180°C / 350°F (160°C fan-forced).","images":[],"step":6},{"title":"Roll","description":"Using a rolling pin, roll the dough between two sheets of baking paper / parchment paper to 5mm / 0.2\" thickness. It doesn''t matter what shape it rolls out to as long as it''s the correct thickness.","images":[],"step":7},{"title":"Cut","description":"Using a 7cm / 2.8\" round cookie cutter, cut out the galletes. Use a spatula to transfer them onto 3 baking paper / parchment paper lined trays. Re-roll scraps and repeat until all dough is used - you should get 24 biscuits. (Note 5)","images":[],"step":8},{"title":"Egg wash","description":"Mix together egg yolk and milk then brush the galettes lightly with the egg wash.","images":[],"step":9},{"title":"Decorate","description":"Dip a fork in water and use the back of the fork to lightly scrape a cross on the surface of each biscuit, lightly etching a line into the dough, not just the egg wash (watch video, it''s helpful).","images":[],"step":10},{"title":"Bake 2 trays for 14","description":"15 minutes until the biscuits are lightly golden (watch the top tray as it might brown faster). Once they are done, bake the 3rd tray.","duration":14.5,"images":[],"step":11},{"title":"Cool","description":"Leave biscuits on trays for 5 minutes, then transfer to a rack to cool completely.","duration":5,"images":[],"step":12}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["French"],"categories":["baking-recipes","cookies","dessert-recipes","jbs-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_fbb38f3440e9', 'en', 'US', 'Salted Caramel Cheesecake', 'Recipe video above. If you’re looking for a Salted Caramel Cheesecake with big caramel flavour in every bite, you’ve found it! Taking pride of place in my cheesecake collection, this has swirls of buttery caramel baked right throughout the creamy cheesecake filling and extra caramel swished over the top. The perfect balance of rich, creamy, sweet and salty.The best feature are the swirls that open up into cracks. Watch everyone fight for the slices with the MOST cracks, because the crevices fill with caramel! Before you start, please read the IMPORTANT NOTES in Notes section below. Thank you! - Nagi', 'https://www.recipetineats.com/tachyon/2026/03/Salted-caramel-cheesecake_2.jpg', 30, 45, 555, 16, '[{"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 75.0, "unit": "block of 250g"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_biscoff_cookies_or_other_plain_biscuit_cookies_2_1_crumbs", "quantity": {"value": 300.0, "unit": "pack"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_cream_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.3, "unit": "tub of 250g"}}, {"id": "ing_egg", "quantity": {"value": 250.0, "unit": "carton of 12"}}, {"id": "ing_caramel_sauce", "quantity": {"value": 0.5, "unit": "bottle"}}, {"id": "ing_chilli_flakes", "quantity": {"value": 0.062, "unit": "jar of 40g"}}]', '[{"ingredients":["1 cup caster sugar / superfine sugar (Note 1)","75g / 5 tbsp unsalted butter (, cold, cut into ~ 1cm / 0.4\" cubes )","1/2 cup thickened cream / heavy cream (, or any full-fat pourable cream)","1/2 tsp cooking salt / kosher salt (halve for table salt, + 50% for salt flakes)"],"purpose":"Salted Caramel:"},{"ingredients":["300g/10 oz Biscoff cookies (38 pieces) or other plain biscuit/cookies 2 1/2 cups crumbs) (Note 2)","1/2 tsp cinnamon powder","1 tbsp brown sugar","Pinch of salt","120g / 8 tbsp unsalted butter (, melted)"],"purpose":"Biscoff Biscuit Base:"},{"ingredients":["1 lb / 500g cream cheese (, full fat, softened to room temperature (Note 3 - take note UK/Europe!))","1 tsp vanilla extract","1/2 cup sour cream (, full fat (substitute with yogurt))","3/4 cup caster sugar / superfine sugar (or regular white sugar / granulated sugar)","3 large eggs (, at room temperature (~55g/2oz in-shell))","1/2 of the salted caramel sauce (Note 4 for store-bought)","1/8 tsp cooking salt / kosher salt"],"purpose":"Cheesecake Filling:"},{"ingredients":["1/2 of the salted caramel sauce (Note 4 for store-bought)","1 tsp sea salt flakes (Note 5)"],"purpose":"Decorating:"}]', '[{"title":"Caramel","description":"melt sugar in 4 batches, whisk in salt ,butter and cream off heat, simmer 1 min. Fully cool. Base - blitz biscuits into crumbs, then everything else. Press into lined 23 x 33cm pan (9x13\"). Filling - Beat cream cheese, then beat in vanilla, sour cream, sugar and salt. Beat in eggs one at a time. Pour over base, swirl in half the caramel, bake 35 min @ 160°C/320°F (140°C fan), cool in door-open oven, fridge 6 hrs. Drizzle with caramel and salt flakes.","images":[],"step":1},{"description":"Salted Caramel for Cheesecake (start this 1 hour prior):","images":[],"step":2},{"title":"Melt sugar in 4 batches","description":"Spread 1/4 of the sugar in a medium saucepan over medium high heat (or medium, if it''s a strong stove). Let it melt, stirring if needed, then add another 1/4 of the sugar, melt, then repeat twice more.","images":[],"step":3},{"title":"Amber colour","description":"Once all the sugar has melted, leave it on the stove for 1 - 2 minutes until it becomes an amber colour. ⚠️DON''T WALK AWAY! Sugar burns easily. :)","duration":1.5,"images":[],"step":4},{"description":"Make it caramel! Remove the saucepan off the stove. Add the salt and butter, whisk until melted (it may not combine with the sugar, that''s ok). Then slowly and carefully pour in ~1/3 of the cream (⚠️ it will steam and bubble a bit). Whisk that to combine, then whisk in remaining cream (it won''t bubble).","images":[],"step":5},{"title":"Simmer","description":"Return to the stove, still on medium high. Once you see bubbles, let it simmer for 1 minute, stirring and scraping down sides as needed.","duration":1,"images":[],"step":6},{"title":"Cool 1 hour","description":"Pour into a bowl. Cover with cling wrap touching the surface (to prevent a skin from forming). Let it fully cool on the counter before using - about 1 hour.","images":[],"step":7},{"description":"Preheat oven to 160°C/320°F (140°C fan-forced). Place shelf in middle of oven.","images":[],"step":8},{"title":"Line pan","description":"Lightly grease a 23 x 33cm / 9 x 13\" metal pan with unsalted butter. Line with baking paper with overhang to lift the cheesecake out at the end.","images":[],"step":9},{"description":"Cheesecake Biscuit Base:","images":[],"step":10},{"title":"Blitz","description":"Break up biscuits roughly by hand and place in a food processor. Blitz until fine crumbs. Add cinnamon, sugar, salt and butter. Briefly blitz until it resembles wet sand. (Note 6)","images":[],"step":11},{"description":"Pour into the prepared pan, then firmly press it evenly across the base (base only, not the sides).","images":[],"step":12},{"description":"Cheesecake filling:","images":[],"step":13},{"title":"Cream cheese","description":"Use an electric beater or stand mixer fitted with the paddle (not whisk). Beat the cream cheese just until smooth, no longer than 20 seconds on speed 4. (You want to minimise air bubbles in the batter as they are unsightly).","images":[],"step":14},{"description":"Add vanilla, sour cream, sugar and salt. Beat until just combined.","images":[],"step":15},{"description":"Add eggs one at a time, beating in between for just 5 seconds. After the last egg, beat as needed until batter is smooth - but stop beating immediately once smooth.","images":[],"step":16},{"description":"Pour the mixture onto the base and spread out evenly.","images":[],"step":17},{"title":"Caramel swirls","description":"Use a spoon to randomly dollop half the salted caramel you made across the surface. Then use a chopstick to make some swirls. Not too many - we don''t want to mix the caramel into the batter, you just want to spread it across the surface. Don''t worry about prettiness (we drizzle more on at the end).","images":[],"step":18},{"description":"Bake for 35 minutes. The middle should still be a bit soft, but not like a waterbed (ie runny batter under surface skin).","duration":35,"images":[],"step":19},{"title":"Cool in oven","description":"Cool the cheesecake in the oven with the door open approx 20 cm / 8\" for about 1 hour (Note 6)","images":[],"step":20},{"title":"Fill cracks and decorate","description":"As it cools, some of the swirls will open up into cracks. Use a teaspoon to fill these with salted caramel, then use most of the remaining caramel to do bold drizzles across all across the surface, I use about 3/4 of it (use leftover for serving, or another use).","images":[],"step":21},{"title":"Fridge set","description":"Refrigerate the cheesecake in the pan for 6 hours+ or overnight.","images":[],"step":22},{"title":"Remove & cut","description":"To remove, lift the cheesecake out using the paper overhang. Sprinkle with salt flakes. Cut into however many pieces you desire - 16 bars (pictured), or into 40 x 4cm or 77 x 3cm Petit Four size squares (adorable!).","images":[],"step":23}]', '["egg","milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","cheesecakes","dessert-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2788c5cc8dbf', 'en', 'US', 'JB''s Banana Bread', 'Recipe above video. The wait is finally over! After weeks of testing, tweaking and plenty of taste-testing, my banana bread is finally ready to share. Crispy golden top, caramelised sides, and a soft crumb with big banana flavours that slices like a dream. Let’s go!For metric measurements, click on the "metric" button at the top of the ingredients list.', 'https://www.recipetineats.com/tachyon/2026/03/Banana-bread-19Mar2026_2.jpg', 20, 70, 150, 8, '[{"id": "ing_flour", "quantity": {"value": 0.338, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.025, "unit": "tub of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.156, "unit": "jar of 40g"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_bananas", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.2, "unit": "tub of 250g"}}, {"id": "ing_butter", "quantity": {"value": 80.0, "unit": "block of 250g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.25, "unit": "bottle of 50ml"}}]', '[{"ingredients":["2 1/4 cup plain flour / all-purpose flour","1 tsp baking soda (, sifted (bi-carbonate soda) (Note 1))","1/2 tsp cooking salt / kosher salt (half for table salt, +50% for flakes)","1 1/4 tsp cinnamon powder","1/4 tsp allspice powder"],"purpose":"Dry Batter Ingredients:"},{"ingredients":["4 medium ripe banana (400g / 14oz peeled, makes 1 3/4 cup once puréed) (Note 2)","1 tightly packed cup brown sugar","2 large egg + 1 egg yolk (, at room temperature (~55g/2oz shell-on weight))","1/3 cup sour cream (, full fat best (Note 3))","80g (5 tbsp) unsalted butter (, melted)","1/3 cup vegetable oil","2 1/2 tsp vanilla extract"],"purpose":"Wet Batter Ingredients:"}]', '[{"description":"Preheat oven and line loaf pan. Whisk dry ingredients together. In a seperate bowl, mash bananas, then mix in the rest of wet ingredients. Add dry to wet and mix gently until just combined. Pour into prepared pan. Bake at 180°C/350°F (160°C fan) 70 minutes.","images":[],"step":1},{"description":"Preheat oven to 180°C/350°F (160°C fan-forced). Arrange the shelf so the loaf will sit in the middle of the oven.","images":[],"step":2},{"title":"Prepare the pan","description":"Scrunch a 40 cm / 16\" sheet of baking / parchment paper and press it into a loaf pan (21.5 x 11.5 x 7 cm / 4.5 x 8.5 x 2.75\"), leaving overhang on the sides for easy lifting.","images":[],"step":3},{"title":"Whisk dry","description":"Mix dry ingredients in a bowl, whisk together the flour, baking soda, salt, cinnamon and allspice until well combined.","images":[],"step":4},{"title":"Mash Bananas","description":"In a large mixing bowl, mash the bananas with a potato masher until mostly smooth. Measure out 1 3/4 cups - save the excess for your morning smoothie. (Note 4)","images":[],"step":5},{"title":"Add wet","description":"Add the brown sugar, eggs, extra yolk, sour cream, melted butter, oil and vanilla. Whisk until combined.","images":[],"step":6},{"title":"Add dry","description":"Pour the dry ingredients into the wet. Fold gently with a spatula until the flour is just incorporated. Having a few little flour lumps is ok, it''s better than overmixing which will make your banana bread firmer rather than soft.","images":[],"step":7},{"title":"Fill pan","description":"Pour the batter into the prepared pan and smooth the surface.","images":[],"step":8},{"title":"Bake","description":"Put the banana bread in the oven and bake for 70 minutes, until a skewer inserted in the centre comes out clean (turning the pan around halfway through cooking). While cooking, a crack will naturally appear along the top of your banana bread. The centre continues to expand, it pushes through the firm crust, creating that classic split. (Note 5)","duration":70,"images":[],"step":9},{"description":"Cool in the pan for 10 minutes, then lift out, and place on a wire rack. Let it cool for an hour before slicing. (Note 6)","duration":10,"images":[],"step":10},{"title":"Serving","description":"Serve banana bread slices slightly warm or at room temperature. It’s great on its own, or spread with a little butter. Perfect for breakfast, afternoon tea, or a quick snack any time of the day.","images":[],"step":11}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","dessert-recipes","jbs-recipes","quick-bread"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_afbd377900db', 'en', 'US', 'Vanilla Cream Filled Chocolate Ganache Cupcakes', 'Recipe video above. Chocolate cupcakes filled with lightly sweetened vanilla whipped cream with a thick layer of chocolate ganache fudge frosting. Try to tell me you aren''t already reaching for the mixing bowl! It''s a WOW combination that will make you question whether you will ever eat a regular cupcake again.... ;)The cream is stabilised with a little cream cheese so the cupcakes will last 3 days without the cream melting, plus the slight tang is lovely against all the rich chocolate. To get ahead, the ganache frosting can be made the day before then left on the counter to soften until spreadable.PS The recipe makes a little more cream and ganache that you might need. Use for ice cream, dip in biscuits, eat with a spoon!', 'https://www.recipetineats.com/tachyon/2025/10/Vanilla-whipped-cream-filled-chocoalte-cupcakes_3.jpg', 40, 22, 62, 12, '[{"id": "ing_flour", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_cocoa_powder", "quantity": {"value": 0.3, "unit": "pack of 250g"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.017, "unit": "tub of 150g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.013, "unit": "tub of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_oil", "quantity": {"value": 50.0, "unit": "bottle"}}, {"id": "ing_milk", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.003, "unit": "L"}}, {"id": "ing_coffee_granules", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_water", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_chocolate", "quantity": {"value": 180.0, "unit": "block of 100g"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_cream_cheese", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.113, "unit": "kg"}}]', '[{"ingredients":["3/4 cup plain flour / all-purpose flour","1/2 cup cocoa powder (, sifted (unsweetened regular, not dutch processed))","1/2 tsp baking powder","1/2 tsp baking soda (bi-carbonate soda)","1/2 tsp cooking salt / kosher salt (halve for table salt, +25% for flakes)"],"purpose":"Dry ingredients:"},{"ingredients":["3/4 cup (tightly packed) brown sugar","2 large eggs ( at room temperature (~50-55g/2oz each in shell))","1/3 cup oil (canola, vegetable or any other plain flavoured oil)","1/3 cup milk (preferably full fat though any % will work, even non dairy)","1 tsp vanilla extract","1/2 tsp white vinegar ( - activates baking soda (Note 1))"],"purpose":"Wet ingredients:"},{"ingredients":["1 tsp coffee granules (, optional (Note 2))","1/3 cup hot water"],"purpose":"Hot coffee flavour enhancer (Note 2):"},{"ingredients":["180g / 6 oz dark chocolate / semi-sweet chocolate melts or chips (, or chopped dark chocolate - (Note 3 for other chocolate))","3/4 cup (180 ml) thickened cream / heavy cream (or any regular cream 30% - 36% fat, NOT low fat cream - Note 4)"],"purpose":"Chocolate Ganache Frosting:"},{"ingredients":["2/3 cup thickened cream / heavy cream (or any whipped cream)","50g/ 3 tbsp block cream cheese (, softened (stabilises cream - Note 5), substitute with tub cream cheese)","2 tbsp caster sugar / superfine sugar","1 tsp vanilla extract"],"purpose":"Stabilised vanilla whipped cream:"}]', '[{"title":"Ganache first","description":"pour hot cream over ganache, stand 7 minutes, stir until smooth, fridge 2 hrs until spreadable. Cupcakes: Whisk Dry and Wet in separate bowls, whisk Wet into Dry, then whisk in hot coffee. Fill cupcake liners halfway, bake 22 minutes at 180°C/350°F (160°C fan), cool 1.5 hrs. Cream: Whip cream cheese, vanilla and sugar first, then cream. Cut out cavity, trim to make lid. Fill with cream, put lid on, top with ganache. Enjoy!","images":[],"step":1},{"title":"Melt chocolate","description":"Place chocolate in a microwave-proof bowl. Heat cream until hot, just before boiling - do not let it boil, it''s too hot. Pour over chocolate, shake bowl to submerge all the chocolate.","images":[],"step":2},{"title":"Leave for 7 minutes","description":"DO NOT COVER (condensation = enemy of chocolate). Mix with a spatula until combined and smooth (~ 1 minute, be patient). If you have little unmelted lumps, microwave for 20 seconds then mix again (repeat as needed)","duration":7,"images":[],"step":3},{"title":"Cool to thicken (goal","description":"peanut butter spread consistency) - Cool in the fridge for 2 hours, OR refrigerate longer / overnight then leave to soften on counter for 15 – 20 minutes so it becomes spreadable.","images":[],"step":4},{"description":"Preheat oven to 180°C/350°F (160°C fan-forced). Put cupcake liners in a standard 12 hole muffin tin.","images":[],"step":5},{"title":"Batter","description":"Whisk the Dry ingredients in a large bowl. Whisk the Wet ingredients in a separate bowl until combined.","images":[],"step":6},{"title":"Hot coffee","description":"dissolve coffee granules in the hot water.","images":[],"step":7},{"title":"Finish batter","description":"Pour the Wet mixture into the Dry ingredients. Whisk until combined. Add hot coffee and whisk again until combined. Firmly bang bowl on counter 3 times (removes large air bubbles).","images":[],"step":8},{"title":"Fill","description":"Transfer mixture into a pouring jug (scrape out all batter). Fill cupcake liners halfway (no more - else cupcakes will overflow/sink).","images":[],"step":9},{"description":"Bake 22 minutes or until a toothpick inserted into the centre comes out clean.","images":[],"step":10},{"description":"Cool in the pan for 5 minutes then transfer to cooling rack to fully cool for at least 1 1/2 hours.","duration":5,"images":[],"step":11},{"description":"Filling / frost:","images":[],"step":12},{"title":"Cut cream hole","description":"Use a small knife to cut a shallow cylinder-shaped cavity out of the cupcake, leaving a 1.25 cm / 1/2\" border. Use a spoon to scoop the cake out. Trim so you are left with a 1 cm / 0.4\" thick lid. (Keep lids and cupcakes together so the holes match the lids!)","images":[],"step":13},{"title":"Whipped cream","description":"Put the cream cheese, vanilla and sugar in a bowl. Beat with an electric beater on high for 1 minute until soft and creamy. Add cream and peat until firm peaks form. (If using stand mixer, use whisk attachment).","duration":1,"images":[],"step":14},{"title":"Fill","description":"Use a teaspoon to fill the cavity with cream, then cover with the lid, pressing in so it sits flush with the cupcake surface. Fill as much as you can without making cream ooze out when you put the lid on!","images":[],"step":15},{"title":"Frost","description":"Dollop a very heaped tablespoon of ganache on top, then spread. Sprinkle with white chocolate or decorate as desired. ENJOY!","images":[],"step":16}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","cupcakes-and-muffins","dessert-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a6ff56dd2328', 'en', 'US', 'Maple Pecan Pie Bars', 'Recipe video above. Tastes like pecan pie - but so much easier to make!! LOVE the maple flavour in this.If pecans aren''t your thing, make this with whatever nut you want - almonds, walnuts and macadamia comes immediately to mind, though I''d love to try this with peanuts and honey instead of maple.', 'https://www.recipetineats.com/tachyon/2025/08/Maple-Pecan-Pie-Bars_4.jpg', 20, 30, 50, 16, '[{"id": "ing_butter", "quantity": {"value": 75.0, "unit": "block of 250g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_pecans", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_maple_syrup", "quantity": {"value": 0.333, "unit": "bottle of 250ml"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_chilli_flakes", "quantity": {"value": 0.031, "unit": "jar of 40g"}}]', '[{"ingredients":["75g (5 tbsp) unsalted butter (, melted)","1/3 cup (tightly packed) brown sugar","1/4 tsp cooking salt / kosher salt","1 cup plain flour (all-purpose flour)"],"purpose":"Base:"},{"ingredients":["1 1/2 cups pecans (Note 1)","75g (5 tbsp) unsalted butter","1/2 cup (tightly packed) brown sugar","1/4 tsp cooking salt / kosher salt","1/3 cup maple syrup (, real not artificially flavoured (honey would also work))","2 large eggs (~55g/2oz each)","1 tsp vanilla extract"],"purpose":"Maple Pecan Pie Filling:"},{"ingredients":["1/3 cup pecans","2 tsp maple syrup","1 pinch salt","1/4 tsp salt flakes (, for sprinkling at the end (optional but recommended))"],"purpose":"Decorating:"}]', '[{"title":"Base","description":"mix butter, sugar and salt, then flour. Press into 20cm/8\" lined pan, bake 15 min at 180C/350F (160C fan), cool 15 min. Oven toast pecans 10 min (put in with base), roughly chop. Filling - bring butter, maple, sugar and salt to simmer, cool 5 min, whisk in eggs and vanilla, then pecans. Pour on base, top with maple coated whole pecans, bake 25 min.","images":[],"step":1},{"description":"Preheat the oven to 180°C/350°F (160°C fan-forced).","images":[],"step":2},{"description":"Grease a 20cm/8\" square pan lightly with butter then line with paper, with overhang to lift out later. (Note 2 for scaling up)","images":[],"step":3},{"title":"Make base","description":"Melt the butter in a microwave proof bowl. Mix in the sugar and salt, then the flour. Press evenly into the base of the pan (I use my hands first, then finish with a spatula to make it fairly even, no need to be meticulous).","images":[],"step":4},{"title":"Bake and cool","description":"Bake for 20 minutes, then cool for 15 minutes before filling (keeps the base crisper but you can skip this).","duration":20,"images":[],"step":5},{"title":"Toast pecans","description":"Spread the pecans for the filling on a tray and bake in the oven for 10 minutes (I put them in with the base). Remove, then when cool enough to handle, roughly chop.","duration":10,"images":[],"step":6},{"title":"Maple filling","description":"Melt the butter in a small saucepan over medium heat. Mix in the sugar, maple syrup and salt. Once it comes to a proper simmer, remove from the stove and cool for 5 minutes. Whisk the eggs and vanilla in, then stir the chopped pecans in. (You can set aside until ready to use).","duration":5,"images":[],"step":7},{"title":"Decorating pecans","description":"Toss the pecans with the maple syrup.","images":[],"step":8},{"title":"Fill and bake","description":"Pour the pecan filling onto the base and spread out evenly. Top with the Decorating Pecans. Bake 25 minutes.","images":[],"step":9},{"title":"Cool","description":"Remove and cool fully to room temperature to let it set (~ 2 hrs, fridge will expedite). Then cut into 16 squares (or 9...) and eat with your hands!","images":[],"step":10}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","dessert-recipes","slices-bars"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_46f5b1cbd1a4', 'en', 'US', 'Mini Cinnamon Muffins', 'Recipe video above. These are way too easy to keep popping in your mouth. They taste like cinnamon doughnuts! Except, baked, not fried :) And the inside is more plush and buttery because the recipe is based on French Madeleines. How did I never do that before - it''s too good and too easy not to adapt for other recipes!I make these mini because the batter works best for small little cakes - and also, so cute! But you can totally use a regular muffin tin, see Note 3.', 'https://www.recipetineats.com/tachyon/2025/08/Mini-cinnamon-muffins_7.jpg', 20, 12, 32, 24, '[{"id": "ing_flour", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.042, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_milk", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.2, "unit": "bottle of 50ml"}}, {"id": "ing_butter", "quantity": {"value": 75.0, "unit": "block of 250g"}}, {"id": "ing_oil", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.094, "unit": "jar of 40g"}}]', '[{"ingredients":["3/4 cup plain flour ( / all-purpose flour (Note 1))","1 1/4 tsp baking powder (make sure yours is still active!)","1/8 tsp cooking salt / kosher salt","2 large eggs (, at room temperature (55-60g/2oz each))","1/2 cup caster sugar ( / superfine sugar (Note 2))","2 tsp oil (canola, veg or other neutral oil)","2 tbsp milk (, full fat best but low fat ok)","2 tsp vanilla extract","75g (5 tbsp) unsalted butter (, melted and cooled but still warm)","Canola oil spray (, or other neutral oil spray (Note 1))"]},{"ingredients":["2 tbsp caster sugar (/ superfine sugar (Note 2))","3/4 tsp cinnamon powder"],"purpose":"Cinnamon sugar:"}]', '[{"description":"Whisk flour, baking powder and salt. In a separate bowl, whisk eggs and sugar vigorously, then oil, milk and vanilla. Add flour in 2 batches, then butter. Spray mini muffin tin, fill 3/4 full, bake 12 min at 180°C/350°F (160°C fan), bang out then toss in cinnamon sugar.","images":[],"step":1},{"description":"Preheat oven to 180°C/350°F (160°C fan-forced). (Don''t grease the muffin tin yet)","images":[],"step":2},{"title":"Cinnamon Sugar","description":"Mix the ingredients in a small bowl and set aside.","images":[],"step":3},{"title":"Dry ingredients","description":"Whisk the flour, baking powder and salt in a small bowl.","images":[],"step":4},{"title":"Wet ingredients","description":"In a separate medium bowl, whisk the eggs and sugar vigorously for 20 seconds until pale yellow. Add oil, milk and vanilla and whisk again.","duration":0.3333333333333333,"images":[],"step":5},{"title":"Finish batter","description":"Add half the flour, gently whisk in, then whisk in the remaining flour. Gently whisk in the butter until incorporated. Set aside while you prepare the muffin tin.","images":[],"step":6},{"title":"Spray and bake","description":"Generously spray a 24 hole mini muffin tin with oil. (Note 3) Fill each 3/4 full with batter (don''t be greedy and overfill, they will not rise as they should!). A small cookie scoop with lever is handy, or a jug or piping bag.","images":[],"step":7},{"description":"Bake 12 minutes. Cool for 2 minutes then invert and assertively bang the pan edge on a work surface to knock the muffins out of the tin. (Don''t try to pry out, they will break)","duration":2,"images":[],"step":8},{"description":"Toss in cinnamon sugar while warm (sticks better) then serve immediately!","images":[],"step":9}]', '["egg","gluten","milk"]', '["keto_friendly","low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","cupcakes-and-muffins","dessert-recipes","muffin-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ff3c27575676', 'en', 'US', 'Peanut Butter Stuffed Brownies', 'Recipe video above. High impact brownie with a neat layer of peanut butter stuffed inside so you get fudgy chocolate brownie and peanut butter in every single bite!Forget trying to spread peanut butter on a layer of brownie batter (it''s impossible. Impossible!). Make your life easy and freeze a slab of peanut butter in your brownie pan, then just sandwich that between the batter.PS Sprinkling salt flakes on the peanut butter slab and again on top of the brownie is 👌🏻', 'https://www.recipetineats.com/tachyon/2025/07/Peanut-butter-stuffed-brownies_9.jpg', 15, 32, 227, 16, '[{"id": "ing_peanut_butter", "quantity": {"value": 0.4, "unit": "jar of 375g"}}, {"id": "ing_chilli_flakes", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_chocolate", "quantity": {"value": 1.25, "unit": "block of 100g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 250.0, "unit": "carton of 12"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_cocoa_powder", "quantity": {"value": 0.15, "unit": "pack of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1 cup (250g) smooth peanut butter spread for stuffing","1 tsp salt flakes (, divided)"],"purpose":"Peanut butter matters"},{"ingredients":["200g / 14 tbsp unsalted butter (1 3/4 US sticks)","1 1/4 cups (200g) dark chocolate chips (7 oz) (Note 2)","1 cup loosely packed brown sugar (, loosely packed )","3 large eggs (, lightly beaten)","1 tsp vanilla extract","1/2 cup plain flour","1/4 cup cocoa powder","1/8 tsp cooking salt / kosher salt"],"purpose":"Brownie"}]', '[{"description":"Save 2 tbsp peanut butter for swirling, warm to loosen then freeze rest in lined pan. Melt butter and chocolate, mix in sugar, then eggs + vanilla, then flour + cocoa + salt. Pour half in pan, top with peanut butter slab, cover with remaining batter, swirl through warmed reserved peanut butter. Bake 32 min at 180°C/350°F (160°C fan). Cool 1 hr on counter, 3 hrs+ in fridge, cut.","images":[],"step":1},{"title":"Line pan","description":"Grease a 20cm/8\" square pan with butter then line with baking paper (parchment).","images":[],"step":2},{"title":"Frozen peanut butter slab","description":"Set aside 2 tablespoons of the peanut butter for the swirls. Warm the remaining peanut butter in the microwave to loosen (~30 sec on high), then pour into the pan. Spread evenly, sprinkle with half the sea salt flakes. Freeze for 2 - 3 hours until it''s so firm you can pick it up. Lift out of pan using the paper, then put it back in the freezer on the paper while you make the batter (it softens quickly).","images":[],"step":3},{"description":"Line pan again with baking paper, with overhang so you can lift the brownie out.","images":[],"step":4},{"description":"Preheat oven to 180°C/350°F (160°C fan forced).","images":[],"step":5},{"title":"Melt","description":"Place butter and chocolate in a heatproof bowl. Microwave in 30 second bursts, stirring in between (takes me 1m 30 sec) until melted and smooth. Stir to combine.","images":[],"step":6},{"title":"Batter","description":"Add sugar, mix, then add eggs and vanilla and mix well until smooth and molten. Add flour, cocoa and salt. Stir until smooth.","images":[],"step":7},{"title":"Stuff","description":"Pour half the batter into the pan. Top with frozen peanut butter slab, spread with remaining batter.","images":[],"step":8},{"title":"Swirl","description":"Randomly dollop/drizzle the 2 tbsp peanut butter across the surface. Use a butter knife or teaspoon to make random swirls, make grooves if needed to reveal brownie batter - Note 3 for tips!","images":[],"step":9},{"description":"Bake for 32 minutes. The middle will still jiggle (it sets when cool) but the edges should be firmish.","duration":32,"images":[],"step":10},{"title":"Set","description":"Cool in the pan on the counter for an hour, then refrigerate for at least 3 hours to let it properly set, else the peanut butter will ooze out when cutting. Cut into 16 squares. Let it come to room temperature for 15 minutes+ then devour! Store in an airtight container in a cool, dry place.","duration":15,"images":[],"step":11}]', '["egg","gluten","milk","peanuts"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":["South Western"],"categories":["baking-recipes","chocolate","dessert-recipes","slices-bars"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5f55e9943e89', 'en', 'US', 'Red velvet cheesecake', 'Recipe video above. A no-bake showstopper where the bold, striking colour of Red Velvet Cake meets the creamy decadence of cheesecake. The filling is beautifully chocolatey, rich-yet-light, with that signature velvety texture that just melts in your mouth.Make this when you have people to impress - it''s special!', 'https://www.recipetineats.com/tachyon/2025/07/Red-velvet-cheesecake_5.jpg', 30, 0, 30, 12, '[{"id": "ing_oreo_cookies", "quantity": {"value": 200.0, "unit": "pack"}}, {"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_gelatine_powder", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_cream_cheese", "quantity": {"value": 500.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_chocolate", "quantity": {"value": 150.0, "unit": "block of 100g"}}, {"id": "ing_red_food_colouring", "quantity": {"value": 6.0, "unit": "unit"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_chocolate", "quantity": {"value": 150.0, "unit": "block of 100g"}}]', '[{"ingredients":["200g/ 7oz Oreo cookies (1.5 standard packs, Note 1)","60g / 4 tbsp unsalted butter (, melted)"],"purpose":"Base:"},{"ingredients":["2 tsp gelatine powder (unflavoured gelatine) (Note 2)","2 tbsp water","1 cup heavy/thickened cream (, fridge cold)","500g / 1 lb cream cheese (, softened (block form, Note 3))","3/4 cup caster sugar / superfine sugar (Note 4)","1 tsp vanilla extract","150g / 5 oz 70% chocolate (or dark chocolate)","6 tsp red food colouring ((Note 6) - UK readers especially!)"],"purpose":"Red velvet cheesecake filling:"},{"ingredients":["1 1/4 cups heavy/thickened cream (, fridge cold (for whipping))","3 tbsp caster sugar / superfine sugar","1 tsp vanilla extract","Optional - stabilise the cream so it doesn''t deflate"],"purpose":"Whipped cream topping:"},{"ingredients":["2 tbsp shaved or grated dark chocolate (I use a potato peeler, grater also works)"],"purpose":"Chocolate topping:"}]', '[{"title":"Inverted pan base","description":"Flip the base of a 20cm / 8\" springform pan upside down – this makes it easier to remove the finished cheesecake without the lip in the way. Very lightly butter the pan base, then press on a square sheet of baking paper. Clip the pan sides onto the base, letting the excess paper stick out the sides (for easy removal later). Butter and line the pan sides with more baking paper.","images":[],"step":1},{"description":"Oreo biscuit base:","images":[],"step":2},{"title":"Blitz cookies","description":"Roughly break up Oreos with hands and place in food processor. Blitz until they become fine crumbs. Add melted butter, then blitz again until combined.","images":[],"step":3},{"title":"Press into pan","description":"Transfer crumbs into prepared pan, pressing evenly and firmly on to the base (I use the underside of a straight-sided, flat-bottomed cup measure to do this).","images":[],"step":4},{"description":"Red velvet cheesecake filling:","images":[],"step":5},{"title":"Bloom gelatine","description":"Place water in a small bowl then sprinkle the gelatine powder across the surface. Stir to partly dissolve. Set aside 5 minutes. It will turn into a solid rubber; this process is called blooming. Microwave the gelatine for 15 seconds to turn it into liquid, stir, then let it stand for 3 to 5 minutes to cool. But it MUST be liquid when added into the mixture (else you''ll end up with gelatine lumps), so re-melt if needed.","duration":0.25,"images":[],"step":6},{"title":"Whip the cream until stiff peaks form (2","description":"3 minutes on high).","images":[],"step":7},{"title":"Whip cream cheese","description":"In a separate bowl (no need to clean beaters), beat the cream cheese and sugar for 2 minutes on high until fluffy and smooth. Add the cooled gelatine liquid and vanilla, beat another 30 seconds to mix it through well.","duration":2,"images":[],"step":8},{"description":"Make it red! Add the lukewarm melted chocolate and red food colouring. Beat well for 1 minute until well combined. It should be a dark, seductive scarlet red colour rather than bright red, bearing in mind the cream will lighten it a bit.","duration":1,"images":[],"step":9},{"title":"Fold in cream","description":"Add one third of the whipped cream to the cream cheese mixture and gently fold until just combined. Then fold in the remaining cream.","images":[],"step":10},{"title":"Transfer to cake pan","description":"Pour the mixture into the prepared tin and place in the fridge for at least 6 hours to set.","images":[],"step":11},{"title":"Remove cheesecake","description":"Release the sides of the springform pan. Use the paper to slide the cheesecake off the base onto a serving platter. Peel the paper off the sides, then slide the paper out from under the cake.","images":[],"step":12},{"title":"Whip cream","description":"Place the cream, sugar and vanilla in a bowl. Beat on high for 2 minutes until softly whipped. (See here for make-ahead stabilised whipped cream option).","duration":2,"images":[],"step":13},{"title":"Decorate","description":"Pile the whipped cream on the cheesecake in the middle, leaving a 2.5cm/1\" border. Sprinkle with shaved chocolate. Serve!","images":[],"step":14}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","cheesecakes","dessert-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f4722a2760eb', 'en', 'US', 'Stabilised whipped cream', 'Stabilised whipped cream is regular whipped cream with an ingredient added which makes it hold its form far better than regular whipped cream which starts to deflate within 30 minutes. It will stay aerated, fluffy, and won''t weep so you can use it to decorate cakes, pipe onto cupcakes and layer on trifles the day before, and it looks perfect the next day. You can also whip it up today and leave it in a piping bag overnight or in a bowl, ready to use tomorrow.There''s a handful of common ways to stabilise cream, and the 3 methods I use are in this recipe so choose the one that suits you.1 cup (250ml) whipping cream = 2 cups whipped', 'https://www.recipetineats.com/tachyon/2025/07/Whipped-cream_1.jpg', 5, 0, 5, 2, '[{"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_mascarpone", "quantity": {"value": 0.333, "unit": "unit"}}, {"id": "ing_elatine_powder_i_use_mckenzie_s_brand", "quantity": {"value": 3.75, "unit": "jar"}}, {"id": "ing_water", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.03, "unit": "kg"}}]', '[{"ingredients":["1 cup thickened cream (heavy cream) or whipping cream (, fridge cold (Note 1))","3 1/4 tsp cream stabiliser powder"],"purpose":"Cream stabiliser powder (handiest):"},{"ingredients":["1 cup thickened cream (heavy cream) or whipping cream (, fridge cold (Note 1))","1/3 cup mascarpone (, fridge cold (40%+ fat, PLEASE GET A REPUTABLE ONE Note 3))"],"purpose":"Mascarpone method (rich and luscious):"},{"ingredients":["3/4 tsp gelatine powder ((unflavoured gelatine), I use McKenzie''s brand)","1 tbsp water","1 cup thickened cream (heavy cream) or whipping cream (, fridge cold (Note 1))","1 tbsp extra heavy / thickened cream"],"purpose":"Gelatine method (handy):"},{"ingredients":["1 tsp vanilla extract","2 tbsp caster sugar / superfine sugar OR","1/2 cup icing sugar / powdered sugar (, sifted (for Chantilly Cream - Note 4))"],"purpose":"Flavouring and sweetness for all methods:"}]', '[{"description":"Cream stabiliser powder:","images":[],"step":1},{"description":"Put the cream, cream stabiliser, vanilla, and sugar or icing sugar in a bowl. Beat for 2 minutes on high until soft peaks form (or a little longer if you want stiff peaks). Ready for use!","duration":2,"images":[],"step":2},{"description":"Holds its structure for up to 3 days in the fridge.","images":[],"step":3},{"description":"Mascarpone method:","images":[],"step":4},{"description":"Place the cream, mascarpone, and icing sugar or sugar and vanilla in a bowl. Beat until it is the stiffness you are after (1 1/2 minutes if you want soft peaks (kind of dollops) or 2 minutes for stiff peaks (for piping).","images":[],"step":5},{"description":"Holds its structure for up to 3 days in the fridge.","images":[],"step":6},{"description":"Gelatine method:","images":[],"step":7},{"description":"Place the water in a small bowl and sprinkle the gelatine over. Mix to dissolve then leave for 5 minutes to bloom - it will turn into a rubbery lump.","duration":5,"images":[],"step":8},{"description":"Microwave for 10 to 15 seconds to melt. Stir in 1 tbsp cream to cool it down.","duration":0.20833333333333334,"images":[],"step":9},{"description":"Put the cream, vanilla, and sugar or icing sugar in a bowl. Beat for 1 minute until quite foamy, then add the gelatine liquid. Keep beating until it is the stiffness you are after - about 30 seconds for soft peaks, or 1 minute for stiff peaks.","duration":1,"images":[],"step":10},{"description":"HOW TO USE AND STORE stabilised whipped cream:","images":[],"step":11},{"description":"Use immediately as you would regular cream (eg decorating cakes, piping, spreading).","images":[],"step":12},{"title":"Keep for use later","description":"immediately transfer into a piping bag or bowl for use the next day. Important: DO NOT STIR before use, it breaks the cream and makes it watery.","images":[],"step":13}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dessert"],"cuisine":["French","Western"],"categories":["baking-recipes","frosting-and-icing"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3294cc8056d1', 'en', 'US', 'Cheese scones', 'Recipe video above. As much as I love traditional jam and cream ones, these savoury cheese scones have my heart…. does it surprise anyone that I make mine extra cheesy? 🙂 This recipe is adapted from my classic scones recipe. See FAQ above for creation notes! :)', 'https://www.recipetineats.com/tachyon/2025/06/Cheese-scones_6-1-copy.jpg', 15, 20, 35, 6, '[{"id": "ing_flour", "quantity": {"value": 0.263, "unit": "kg"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.1, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_milk", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}]', '[{"ingredients":["1 3/4 cups plain flour (/ all purpose flour)","1 1/2 cups shredded cheddar or tasty cheese (packet shredded ok, tightly pack the cups!) (Note 1)","3 tsp baking powder (Note 2)","1/2 tsp cooking salt / kosher salt (halve for table salt, +50% for flakes)","100g (7 tbsp) unsalted butter, cold, cut into 1 cm cubes","3/4 cup milk (, cold, plus a little extra for brushing (preferably full fat))"]},{"ingredients":["1/2 cup shredded cheese (, for topping)","Butter (, for spreading)"],"purpose":"Topping / serving:"}]', '[{"description":"Abbreviated recipe:","images":[],"step":1},{"description":"Pulse dry ingredients once, butter 4 times, cheese once. Add milk while pulsing 8–10 times. Shape into 3cm / 1.2\" thick disc on baking paper, brush with milk, top with cheese, cut into 6 wedges. Space 5cm/2\" apart on tray. Bake 20 min at 200°C/390°F (180°C fan), rest 5 min.","images":[],"step":2},{"description":"Preheat oven to 200°C/390°F (180°C fan-forced).","images":[],"step":3},{"title":"Blitz dry","description":"Put flour, baking powder and salt in a food processor with a standard \"S\" blade. Pulse once. Add butter, pulse 4 to 5 times until the largest butter pieces you see are pea size. (You can also do this by hand - see Note 3)","images":[],"step":4},{"description":"Add cheese, pulse once just to mix through a bit.","images":[],"step":5},{"description":"Pour milk through the feeding tube while pulsing 8 to 10 times until the flour is just incorporated, then stop straight away. The dough will be shaggy rather than smooth, and it should be a bit sticky but can be handled.","images":[],"step":6},{"title":"Bring dough together","description":"Scatter a work surface with 1 tsp flour. Scrape the dough out of the food processor then bring together into a ball with your hands. Try to avoid using extra flour, but dust with more if needed (I don’t).","images":[],"step":7},{"title":"6 wedges","description":"Put it on a sheet of baking paper, pat and shape into 3cm / 1.2\" thick round disc. Brush with milk (top and sides), sprinkle with cheese, lightly press in. Cut into 6 wedges. (Note 4 for rounds)","images":[],"step":8},{"title":"Bake","description":"Transfer to baking tray. Pull each wedge out a bit so they are 5cm/2\" apart. Bake 20 minutes until the surface is golden.","images":[],"step":9},{"description":"Cool 5 minutes on the tray, then enjoy warm with a smear of butter!","images":[],"step":10}]', '["gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["snack"],"cuisine":["Western"],"categories":["baking-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_35d8dd645a51', 'en', 'US', 'Biscoff stuffed cookies', 'Recipe video. The Biscoff stuffed version of the infamous 48-times Chocolate Chip Cookies, a shameless Butter Boy copycat. They''re so good, I''m worried I''ve peaked.😭The dough is spiced like Biscoff and wrapped around frozen Biscoff spread blobs, baking up crisp-edged, chewy and soft inside. Best news? You can bake these now rather than refrigerating overnight! They''re a 12/10 if you wait 12 hours but a 9/10 baked with just a short 2 hour chill.See FAQ for how (and why) the dough differs from the CCC version.', 'https://www.recipetineats.com/tachyon/2025/06/Biscoff-stuffed-cookies_3.jpg', 20, 20, 205, 8, '[{"id": "ing_biscoff_spread", "quantity": {"value": 280.0, "unit": "unit"}}, {"id": "ing_butter", "quantity": {"value": 225.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.338, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.037, "unit": "pack of 400g"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.008, "unit": "tub of 150g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.013, "unit": "tub of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_ginger", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_chocolate", "quantity": {"value": 1.25, "unit": "block of 100g"}}]', '[{"ingredients":["280g / 9.5 oz biscoff spread (, smooth (8 x 1 tablespoon generously heaped, 35g/1 1/4 oz each) (Note 1))","225g / 2 US sticks unsalted butter (, cut into 1cm / 1/2\" cubes (Note 1))"]},{"ingredients":["2 1/4 cups plain flour / all-purpose flour (, spooned and levelled (IMPORTANT - Note 2))","3 tsp cornflour/cornstarch (, tightly pack and level the spoon measure (Note 2))","1/4 tsp baking powder","1/2 tsp baking soda / bi-carb (, sifted if lumpy (don''t sub more baking powder, Note 3))","1/2 tsp cooking salt / kosher salt (halve for table salt, +50% for flakes)"],"purpose":"Dry ingredients:"},{"ingredients":["1 tsp cinnamon powder","1/2 tsp all spice powder (sub mixed spice)","1/4 tsp ginger powder"],"purpose":"Biscoff spices (Note 4)"},{"ingredients":["3/4 cup (tightly packed) brown sugar (light brown sugar)","1/3 cup caster sugar / superfine super (sub regular/granulated)","1 large egg ((55g / 2 oz in shell), at room temp)","1 yolk from a large egg (, at room temp)","1 tsp vanilla extract"],"purpose":"Wet ingredients:"},{"ingredients":["1 1/4 cups white chocolate chips (, plus extra for decorating)"],"purpose":"Choc chips (Note 5):"}]', '[{"description":"Freeze 8 x 1.25cm/1/2\" blobs Biscoff until firm (~1 hr). Brown butter, cool, hand mix in sugar, then egg + vanilla. Mix in whisked Dry & spices, adding choc towards end. Portion into 8, stuff with frozen Biscoff. Fridge 12 -24 hrs (bare min 2 hrs). Bake from fridge cold 4 on each lined tray, 180°C/350°F (170°C fan) 19 min, top with more choc while hot if desired. Cool 20 min on tray, attack!","images":[],"step":1},{"title":"Frozen Biscoff stuffing","description":"Dollop Biscoff on paper lined plate or small tray, and spread into 1.25cm/1/2\" thick discs (just roughly is fine). Freeze 1 hour or until firm enough to pick up.","images":[],"step":2},{"description":"Browned butter:","images":[],"step":3},{"title":"Simmer to brown","description":"Put the butter in a silver saucepan or small pan over medium high heat. Once melted, let it simmer (as in, bubbling) for 4 to 5 minutes, stirring every now and then, until it gets real foamy, you see little golden specks (wade through foam to see), it smells nutty & extra buttery.","duration":4.5,"images":[],"step":4},{"title":"Cool","description":"Immediately pour into a heatproof bowl, including all those golden specks, scraping out every bit of butter. Cool to room temperature (~45 minutes), cool enough so it won''t melt the choc chips (Note 6)","images":[],"step":5},{"description":"Whisk Dry ingredients and Spices in a separate bowl.","images":[],"step":6},{"title":"Mix Wet","description":"To the browned butter, add both sugars and mix with a wooden spoon. Add the egg, yolk and vanilla. Mix until smooth - it will look like caramel.","images":[],"step":7},{"title":"Finish dough","description":"Add the Dry ingredients and mix until the flour is mostly incorporated. Add the choc chips and stir until the flour is fully incorporated.","images":[],"step":8},{"title":"Stuff","description":"Measure out 8 x 125g portions of dough (4.4 oz/ heaped 1/3 cup), press dough together into a rough ball. Flatten, top with frozen Biscoff, enclose and shape into a ball with a flat base (ie tall dome), sealing cracks to avoid Biscoff leakage. Alternative: Break each into 2 balls, flatten both, sandwich Biscoff in between then fold up sides to enclose. You''ll figure out the best method!","images":[],"step":9},{"description":"CHILLING (Note 8):","images":[],"step":10},{"title":"Fridge 12 hours (min 2 hrs)","description":"Place in an airtight container and refrigerate for 12 hours, up to 48 hours. BARE MINIMUM is 2 hours or until dough is firm! (Note 8)","images":[],"step":11},{"description":"Preheat oven to 180°C/350°F oven (170°C fan-forced). (Note 9)","images":[],"step":12},{"description":"Place fridge-cold cookies 7.5 cm/3\" apart on a tray lined with baking paper/parchment paper. (I do 4 cookies on each tray)","images":[],"step":13},{"title":"Bake for 18","description":"19 minutes or until the edges are golden and the surface is cooked (ie not melty raw dough) but still pale.","duration":18.5,"images":[],"step":14},{"title":"Decorate and cool","description":"Working quickly, press extra choc chips on the surface (Note 10), then cool on the tray for 20 minutes - finishes baking, edges crisp more and they get more golden all over.Tip: While hot, you can also reshape with a rubber spatula or similar into a tidy round shape.","duration":20,"images":[],"step":15},{"title":"Grab now","description":"peak eating moment! Or, transfer to a rack to cool fully before storing in an airtight container.","images":[],"step":16}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","cookies","dessert-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2f4929decf09', 'en', 'US', 'The Chocolate Chip Cookies of my dreams!', 'Recipe video. These are my idea of the perfect chocolate chip cookie - superior crispy outsides, soft baked inside with excellent chew, buttery with butterscotch tones and a milk-dark chocolate combo that''s just right. And they''re BIG (2.5cm/1" thick, 11cm/4.5" wide) - intended for high impact!Inspired by Australia''s famous Butter Boy milk choc cookies, it took 48 attempts to perfect these. For best results, use scales and do not skip the 12 hour dough chill (see note 5). Also see Troubleshooting and FAQ below recipe card for extra tips.IMPORTANT: If you don''t have a sweet tooth, these are not for you! Sugar cannot be decreased without compromising results (I really tried). These are unapologetically outrageous in every way!', 'https://www.recipetineats.com/tachyon/2025/03/The-Chocolate-Chip-Cookie-of-my-dreams-_2.jpg', 20, 20, 40, 8, '[{"id": "ing_butter", "quantity": {"value": 225.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.037, "unit": "pack of 400g"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.008, "unit": "tub of 150g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.013, "unit": "tub of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_chocolate", "quantity": {"value": 1.5, "unit": "block of 100g"}}, {"id": "ing_chocolate", "quantity": {"value": 1.5, "unit": "block of 100g"}}]', '[{"ingredients":["225g / 2 US sticks unsalted butter (, cut into 1cm / 1/2\" cubes)"]},{"ingredients":["2 cups (300g) plain flour / all-purpose flour (, spooned and levelled (IMPORTANT - Note 1))","3 tsp cornflour/cornstarch (, tightly pack and level the spoon measure)","1/4 tsp baking powder","1/2 tsp baking soda / bi-carb (, sifted if lumpy (don''t sub more baking powder, Note 2))","1/2 tsp cooking salt / kosher salt (halve for table salt, +50% for flakes)"],"purpose":"Dry ingredients:"},{"ingredients":["1 tightly packed cup (200g) brown sugar (light brown sugar)","1/2 cup (100g) caster sugar / superfine super (sub regular/granulated)","1 large egg ((55g / 2 oz in shell), at room temp)","1 yolk from a large egg (, at room temp)","1 tsp vanilla extract"],"purpose":"Wet ingredients:"},{"ingredients":["1 1/2 cups (250g) dark chocolate chips (/ semi-sweet choc chips, plus extra for decorating)","3/4 cup (150g) milk chocolate chips"],"purpose":"Choc chips (Note 3):"}]', '[{"description":"Brown butter, cool, hand mix in sugar, then egg + vanilla. Mix in whisked Dry, adding choc towards end. Form 8 x 155g (1/2 cup) discs 3.75cm/1.5\" thick. Fridge 12 -24 hrs. Bake from fridge cold 4 at a time, 180°C/350°F (170°C fan) 17 min, top with more choc while hot if desired. Cool 20 min on tray, attack!","images":[],"step":1},{"description":"Browned butter:","images":[],"step":2},{"title":"Simmer to brown","description":"Put the butter in a silver saucepan or small pan over medium high heat. Once melted, let it simmer (as in, bubbling) for 4 to 5 minutes, stirring every now and then, until it gets real foamy, you see little golden specks (wade through foam to see) and it smells nutty & extra buttery.","duration":4.5,"images":[],"step":3},{"title":"Cool","description":"Immediately pour into a heatproof bowl, including all those golden specks. Cool to room temperature (~45 minutes), cool enough so it won''t melt the choc chips (Note 4)","images":[],"step":4},{"description":"Whisk Dry ingredients in a separate bowl.","images":[],"step":5},{"title":"Mix Wet","description":"To the browned butter, add both sugars and mix with a wooden spoon. Add the egg, yolk and vanilla. Mix until smooth - it will look caramel.","images":[],"step":6},{"title":"Finish dough","description":"Add the Dry ingredients and mix until the flour is mostly incorporated. Add the choc chips and stir until the flour is fully incorporated.","images":[],"step":7},{"title":"Make dough discs","description":"Measure out 8 x 155g (5.3 oz/ 1/2 cup) portions of dough, roll into a ball then shape into a 3.75cm/1.5\" thick round disc. Place in a very airtight container. (Note 5 for smaller cookies)","images":[],"step":8},{"title":"Fridge 12 hours","description":"Refrigerate for 12 hours, up to 48 hours (Note 6 for different chill times).","images":[],"step":9},{"description":"Preheat oven to 180°C/350°F (170°C fan-forced). (Note 7)","images":[],"step":10},{"description":"Place 4 fridge-cold cookies 7.5 cm/3\" apart on a tray lined with baking paper/parchment paper. (Note 8 baking tips)","images":[],"step":11},{"description":"Bake for 17 minutes or until the edges are golden and the surface is just set (ie not melty raw dough) but still pale.","duration":17,"images":[],"step":12},{"title":"Decorate and cool","description":"Working quickly, press extra choc chips on the surface (Note 9), then cool on the tray for 20 minutes - finishes baking, edges crisp more and they get more golden all over.Tip: While hot, you can also reshape with a rubber spatula or similar into a tidy round shape.","duration":20,"images":[],"step":13},{"title":"Grab now","description":"peak eating moment! Or, transfer to a rack to cool fully before storing in an airtight container.","images":[],"step":14}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","cookies"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f7ae1aec8b2b', 'en', 'US', 'Coconut mango bars with lime glaze', 'Recipe video above. I adore the combination of mangoes, coconut and lime is a no-fail combination, and here it is in handheld bar form. The contrast of the crispy base and crumbly coconutty topping sandwiching the juicy mango layer is so good! I also like the texture the oats add, that it''s not too sweet, and straightforward to make. Honestly, cutting the mangoes takes the most time!TOP TIP: Mango slices = terrific thick layer of juicy mango. Diced mango mostly turns into mush. Slicing wins!', 'https://www.recipetineats.com/tachyon/2025/01/Mango-bars_4.jpg', 20, 30, 50, 12, '[{"id": "ing_butter", "quantity": {"value": 125.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_flour", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_oats", "quantity": {"value": 150.0, "unit": "pack"}}, {"id": "ing_desiccated_or_shredded_coconut", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.017, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_mango", "quantity": {"value": 2.5, "unit": "unit"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.019, "unit": "pack of 400g"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_lime", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.025, "unit": "bottle of 50ml"}}]', '[{"ingredients":["125g/ 1 stick unsalted butter (Note 1 US conversion note)","1/2 cup caster/superfine white sugar (regular/granulated also ok)","1 large egg","1 1/2 cups flour (, plain / all-purpose)","1 cup oats (Note 2)","3/4 cup desiccated or finely shredded coconut (, unsweetened (not flakes, too big))","1/2 tsp baking powder","1/4 tsp cooking salt / kosher salt (or 1/8 tsp table salt)"],"purpose":"Coconut crumble base & topping:"},{"ingredients":["2 1/2 cups (400 g) mango slices (, 5mm/0.2\" thin, 2 large-ish mangoes (Note 3))","1 1/2 tsp cornflour / cornstarch","2 tbsp white sugar (don''t skip this even if mangoes are sweet, Note 4)"],"purpose":"Mango filling:"},{"ingredients":["3/4 cup soft icing sugar / powdered sugar (Note 5)","1 tsp lime zest","3 tsp lime juice (, plus more as needed (1/4 tsp at a time))","1/4 tsp vanilla extract"],"purpose":"Lime glaze (optional – but not really!)"}]', '[{"description":"Melt butter, mix in sugar, then egg, then everything else. Press 1 3/4 cups into 20cm/8\" lined pan. Toss mango filling ingredients, spread on base, crumble over remaining mixture. Bake 30 min. Cool, drizzle with glaze.","images":[],"step":1},{"description":"Full directions:","images":[],"step":2},{"description":"Preheat oven to 180°C/350°F (160°C fan-forced). Grease then line a 20cm/8\" panwith baking paper (parchment), ensuring you have overhang so you can lift it out at the end.","images":[],"step":3},{"description":"Base & crumbs mixture:","images":[],"step":4},{"title":"Melt butter","description":"Cut the butter into ~1.25cm/1/2\" chunks and melt in a microwave-proof bowl, or use a saucepan and stove. (Note 6)","images":[],"step":5},{"title":"Mix","description":"Add the sugar to the butter and mix with a wooden spoon. Add egg and mix until smooth. Add remaining ingredients and mix until you no longer see flour.","images":[],"step":6},{"title":"Base","description":"Measure out 1 3/4 cups (packed) of the mixture (the rest gets used for the topping). Spread into the pan and use your hands to evenly press it into the base.","images":[],"step":7},{"title":"Mango filling (do this just before use)","description":"Put the mango in a bowl. Sprinkle over the sugar and cornflour. Use your hands to gently toss until evenly coated.","images":[],"step":8},{"title":"Assemble","description":"Spread the mango evenly across the base. Crumble the remaining mixture across the surface, leaving spots of mango exposed.","images":[],"step":9},{"description":"Bake for 30 minutes until the surface is light golden.","duration":30,"images":[],"step":10},{"title":"Cool","description":"Remove from the oven and fully cool in the pan (~ 2 hours) before lifting out using the excess paper onto a cutting board. (Speed things up: 30 min counter, 30 minute fridge).","images":[],"step":11},{"title":"Lime glaze","description":"Mix the ingredients in a medium bowl, using extra lime juice 1/4 tsp at a time if needed until it''s a honey consistency. Drizzle randomly across the surface. Leave for 10 minutes to let the glaze surface crust.","duration":10,"images":[],"step":12},{"title":"Serve","description":"Cut into 12 squares (sensible) or 9 (greedy). Devour!","images":[],"step":13}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","dessert-recipes","slices-bars"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_374e5c76ec5d', 'en', 'US', 'Nutella Stuffed Cookies', 'Recipe video above. These have a chewy/soft centre, crispy edge and melty Nutella in the middle that floods in your mouth. It is as good and as naughty as it sounds, and dangerously simple to make!Try to eat it exactly 15 minutes out of the oven. It''s still warm but the edges have crisped up just enough so you can hold the cookie without sagging, and the Nutella is still molten inside. That is an unmatched cookie eating experience!', 'https://www.recipetineats.com/tachyon/2024/11/Nutella-stuffed-cookies_2.jpg', 25, 12, 127, 10, '[{"id": "ing_nutella", "quantity": {"value": 10.0, "unit": "unit"}}, {"id": "ing_chocolate", "quantity": {"value": 10.0, "unit": "block of 100g"}}, {"id": "ing_flour", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.013, "unit": "tub of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 120.0, "unit": "block of 250g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_honey", "quantity": {"value": 0.01, "unit": "jar of 500g"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}]', '[{"ingredients":["10 tbsp (slightly heaped) Nutella (or other chocolate-nut spread)","1/2 cup dark chocolate chips (or chopped 70% dark chocolate)"]},{"ingredients":["1 1/3 cups plain flour / all-purpose flour","1/2 tsp baking soda (bi-carbonate soda, Note 1)","1/4 tsp cooking salt / kosher salt","120g/ 8 tbsp unsalted butter (, cut into 1 cm / 1/2\" cubes (fridge cold is fine))","2/3 cup (tightly packed) brown sugar (Note 2)","1 tsp vanilla extract","1 tsp honey (or corn syrup (Note 3))","1 large egg (55g / 2 oz), at room temperature (Note 4)"],"purpose":"Cookie dough:"}]', '[{"description":"Abbreviated recipe (hand-mixed):","images":[],"step":1},{"description":"Mix flour, baking soda and salt. In separate bowl, barely melt butter, mix to finish melting. Mix in vanilla, honey and sugar, then egg. Mix in flour, fridge 1.5 hrs. Freeze Nutella discs 1 hr. Enclose Nutella with dough, press in choc chips, bake 12 -13 min at 180°C/350°F (160°C fan). Cool 10 min on tray, then at least 5 min on rack. Attack!","images":[],"step":2},{"description":"Cookie dough:","images":[],"step":3},{"title":"Mix dry","description":"Mix the flour, baking soda and salt in a bowl, set aside.","images":[],"step":4},{"title":"Barely melt butter","description":"Using a heatproof bowl, microwave the butter for 30 seconds on high until mostly but not fully melted, then stir with a rubber spatula to finish melting it so it''s \"milky\" rather than clear yellow oil (Note 5).","duration":0.5,"images":[],"step":5},{"title":"Wet mixture","description":"Add the sugar, vanilla and honey, stir until combined. Add the egg and stir until combined, it should look like caramel.","images":[],"step":6},{"title":"Chill dough 1 1/2 hours","description":"Add the flour mixture and stir until combined. The mixture should be slightly warm and too soft to roll into balls. Cover and refrigerate for 1 1/2 hours to cool and firm up enough to roll into a log.","images":[],"step":7},{"description":"Frozen Nutella mounds:","images":[],"step":8},{"description":"Line a small tray with baking paper / parchment paper. Dollop Nutella on tray and spread to ~8mm/ 1/3\"thick rounds. Freeze for 1 hour until firm enough to pick up.","images":[],"step":9},{"description":"Stuffing and baking:","images":[],"step":10},{"description":"Preheat the oven to 180°C/350°F (160°C fan-forced). Lightly grease 2 trays then line with paper.","images":[],"step":11},{"title":"Cut dough","description":"Scrape dough out and shape/roll into a ~18cm / 7\" log. Cut into 10 equal pieces.","images":[],"step":12},{"title":"Stuff","description":"Flatten cookie dough, press in frozen Nutella, bundle dough up around it to enclose and seal. Flip upside down so the smooth side is facing up. Shape into ~1.5cm/ 3/5\" thick rounds, press choc chips into the surface and sides. Repeat to make 10 cookies, 5 on each tray, 8cm/3\" apart to allow for spreading (Note 6 working tips).","images":[],"step":13},{"title":"Bake both trays at the same time for 12","description":"13 minutes, or until the edges of the cookies are golden, the centre is pale golden and just set (ie not raw melty dough).","duration":12.5,"images":[],"step":14},{"title":"Cool & swoon","description":"Remove from the oven and leave on the tray for 10 minutes (finish cooking / set). Transfer to a rack, cool for at least another 5 minutes. Grab, bite, swoon. That moment when the melty Nutella floods into your mouth.....","duration":10,"images":[],"step":15}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","cookies","dessert-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1ad90bb5c2b5', 'en', 'US', 'White Chocolate Raspberry Loaf', 'Recipe video above. White chocolate raspberry loaf is a quick bread recipe that is simple to make, rustically pretty and can be enjoyed anytime of the day. Tart raspberries plus sweet white chocolate is such a classic pairing! The raspberries add moisture and colour pops in a way that no other berry does. Use fresh or frozen, though it does rise a touch better using fresh.The glaze is the perfect finishing touch for a touch of extra sweetness without overwhelming this loaf (which is not very sweet at all). I''m a sucker for the thin crackly skin on the glaze.', 'https://www.recipetineats.com/tachyon/2024/09/White-chocolate-raspberry-loaf_2.jpg', 20, 75, 140, 10, '[{"id": "ing_butter", "quantity": {"value": 125.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.3, "unit": "tub of 500g"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_lemon", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_flour", "quantity": {"value": 0.263, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.067, "unit": "tub of 150g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.013, "unit": "tub of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_raspberries", "quantity": {"value": 1.8, "unit": "punnet of 125g"}}, {"id": "ing_flour", "quantity": {"value": 0.263, "unit": "kg"}}, {"id": "ing_chocolate", "quantity": {"value": 0.5, "unit": "block of 100g"}}, {"id": "ing_sugar", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}]', '[{"ingredients":["125 g/ 8 tbsp unsalted butter (1 US stick) (Note 1)","3/4 cup caster sugar (superfine sugar) ( (Note 2))","1 cup plain yogurt (, at room temperature, full fat best (Note 3))","2 large eggs (, at room temperature (~50-55g/2 oz each))","1 tsp vanilla extract","1 tsp lemon zest (not critical)"],"purpose":"Wet ingredients:"},{"ingredients":["1 3/4 cup plain flour (all-purpose flour)","2 tsp baking powder","1/2 tsp baking soda (Note 4)","1/4 tsp cooking salt / kosher salt"],"purpose":"Dry ingredients:"},{"ingredients":["1 1/2 cups raspberries (, fresh or frozen (not thawed, see Note 5 tips))","2 tsp flour (, prevents raspberries from sinking (Note 6))","1/2 cup white chocolate chips"],"purpose":"Add-ins:"},{"ingredients":["6 - 8 raspberries (optional)"],"purpose":"Extra Raspberries – decoration"},{"ingredients":["1 cup icing sugar / powdered sugar (, sifted)","1/2 tsp vanilla extract","6 tsp milk (, preferably full fat but low / 0% fat ok)","Pinch of salt"],"purpose":"Glaze:"}]', '[{"description":"Abbreviated recipe:","images":[],"step":1},{"description":"Toss raspberries in flour (if frozen, keep in freezer). Whisk butter and sugar then remaining Wet. Mix in dry, fold through choc and raspberries. Bake in lined 22 x 12 cm pan (8.7 x 4.7\") at 190°C/375°F (170°C fan) for 40 minutes, cover with foil then bake another 35 minutes (+ 5 min for frozen raspberries). Cool, glaze!","duration":40,"images":[],"step":2},{"description":"Full recipe directions:","images":[],"step":3},{"description":"Preheat the oven to 190°C/375°F (170°C fan-forced). Grease and line a 22 x 12 x 7 cm loaf pan with paper (8.7 x 4.7 x 2.75\", Note 6).","images":[],"step":4},{"description":"Toss the raspberries with the flour. If using frozen, put the bowl in the freezer (so they don''t thaw).","images":[],"step":5},{"title":"Wet ingredients","description":"Put the butter in a heatproof bowl and microwave until melted. Cool for a minute then whisk in the sugar. Next, add the yogurt, eggs, vanilla and lemon. Whisk until combined.","images":[],"step":6},{"title":"Dry ingredients","description":"Sprinkle the dry ingredients across the surface, then mix it in using a rubber spatula. Stop mixing as soon as the flour is incorporated - some lumps in the batter is fine. (Over mixing = tough loaf)","images":[],"step":7},{"title":"Raspberries","description":"Working fast, add the white chocolate and the raspberries (including any residual flour in the bowl), then mix briefly just to disperse the raspberries. (Fresh raspberries - careful not to squish them. Frozen - work fast, else the batter chills and thickens = takes longer to bake). Batter is pretty thick.","images":[],"step":8},{"title":"Fill pan","description":"Scrape batter into the prepared pan. Roughly level the surface (spreads and levels in the oven). Press Extra Raspberries into the surface, if using.","images":[],"step":9},{"description":"Bake 40 minutes. Cover loosely with foil then bake for a further 35 minutes for fresh raspberries, 40 minutes for frozen. A skewer inserted into the centre should come out without raw batter on it.","images":[],"step":10},{"description":"Cool 5 minutes in the pan, then transfer onto a rack. Full cool before glazing.","images":[],"step":11},{"description":"Mix Glaze ingredients in a bowl until smooth.","images":[],"step":12},{"title":"Glaze","description":"Put the rack on a tray or plate to catch glaze drips. Drizzle glaze all over the cake. Scrape up glaze from the plate and glaze again.","images":[],"step":13},{"title":"Serve","description":"Leave for 20 minutes to let a crust form on the glaze before cutting thick slices to serve.","duration":20,"images":[],"step":14}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","dessert-recipes","quick-bread"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7cd598d1f546', 'en', 'US', 'Homemade artisan crackers - sesame sea salt flavour', 'Recipe video above. Homemade crackers! How much do you spend on your favourite artisan crackers? This whole recipe might cost $1 - and they’re so easy, no kneading, no yeast. Use for cheese platters, dips, or snack on them like chips!You can really taste the sesame in this, unlike store bought crackers. Feel free to experiment with your own flavours - try rosemary, cracked pepper, poppyseeds. For fruit & nut, use this Gourmet Crackers recipe.', 'https://www.recipetineats.com/tachyon/2024/08/Crackers_2.jpg', 15, 22, 37, 5, '[{"id": "ing_flour", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_water", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_chilli_flakes", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}]', '[{"ingredients":["1 cup plain flour / all-purpose flour (, plus extra for rolling out)","1/4 tsp cooking salt (kosher salt)","1 tbsp white sesame seeds","1/3 cup water (just regular tap water)","2 tbsp extra virgin olive oil"],"purpose":"Cracker dough:"},{"ingredients":["1 tbsp white sesame seeds","1/2 tsp salt flakes (Note 1)","Olive oil spray (Note 2)"],"purpose":"Sprinkling / spraying:"}]', '[{"description":"Abbreviated recipe:","images":[],"step":1},{"description":"Mix dry ingredients, make well, stir in wet. Divide in half, roll out 3mm / 1/8\" thick. Transfer to paper, sprinkle with sesame and flakes, roll to 2mm / 1/12\". Cut into 5cm / 2\" pieces, transfer to tray, spray with oil. Bake 12 min, rearrange to colour evenly, bake 8 to 10 min until light golden.","images":[],"step":2},{"description":"Preheat the oven to 200°C / 400°F (180°C fan-forced).","images":[],"step":3},{"description":"Mix the flour, sesame and salt in a bowl using a rubber spatula or wooden spoon. Make a well in the centre then add the water and oil. Using the handle of the spatula to mix until the flour is incorporated.","images":[],"step":4},{"description":"Roll out #1 Sprinkle the counter lightly with flour. Scrape the dough out then knead a few times to bring it together into a ball. Cut in half. Roll one piece out to 3mm / 1/8\" thin oval shape. (Note 3)","images":[],"step":5},{"title":"Sprinkle","description":"Place a sheet of baking paper (parchment) on a cutting board. Transfer the rolled out dough onto the paper. Sprinkle with half the sesame and half the salt flakes. Roll out even thinner on the paper to 2mm / 1/12\" (thinner = crispier).","images":[],"step":6},{"description":"Cut into 5cm / 2\" squares using a pizza cutter or knife (Note 4). You''ll have smaller pieces on the edge and corners, that''s fine. Leave the pieces as is, don''t try to move them (so thin, it''s too hard!). Slide the paper onto a tray. Repeat with the other piece of dough.","images":[],"step":7},{"title":"Bake","description":"Spray with oil. Bake both trays together for 12 minutes. Remove from the oven. Re-arrange to move the more golden pieces on the outer rim of the tray to the centre (so they cook evenly). Bake for a further 8 to 10 minutes or until all the pieces are light golden (white = not crispy!).","duration":12,"images":[],"step":8},{"title":"Serving","description":"Remove from the oven and leave the crackers to cool on the tray (~20 minutes). Make dip or prepare cheese platter worthy of your homemade crackers. Then attack!","images":[],"step":9}]', '["gluten","sesame"]', '["low_calorie","vegan","vegetarian"]', '{"mealType":["snack"],"cuisine":["Western"],"categories":["baking-recipes","snacks"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cec4d93cbf7f', 'en', 'US', 'Pistachio Cake', 'Recipe video above. Using freshly blitzed pistachios makes this cake really special, for both real pistachio flavour and a soft, moist cake texture. So don''t be tempted to buy pre-powdered (if such a thing even exists!). Finished with what I''ve christened a Cream Cheese Whip which is like a much lighter, less sweet version of Cream Cheese Buttercream Frosting. Goes so well with the nuttiness of this cake.Note: Every ingredient has a purpose, I never include things just for the sake of it! See Ingredients section for the reason for each.', 'https://www.recipetineats.com/tachyon/2024/08/Pistachio-cake-2_9.jpg', 20, 55, 150, 10, '[{"id": "ing_pistachio_kernels", "quantity": {"value": 125.0, "unit": "jar"}}, {"id": "ing_flour", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.042, "unit": "tub of 150g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.006, "unit": "tub of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.225, "unit": "tub of 500g"}}, {"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_oil", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_sugar", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.05, "unit": "bottle of 50ml"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_drops_red_food_colouring", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_cream_cheese", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_cream", "quantity": {"value": 0.4, "unit": "carton of 250ml"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}]', '[{"ingredients":["125g/ 4.4oz (just shy 1 cup) pistachio kernels (, unsalted (Note 1))"]},{"ingredients":["1 cup plain flour (all-purpose flour)","1 1/4 tsp baking powder","1/4 tsp baking soda (bi-carb soda) (Note 2)","1/4 tsp cooking salt / kosher salt"],"purpose":"Dry ingredients for batter:"},{"ingredients":["3/4 cup yogurt (, plain, full-fat, at room temperature (Note 3))","60g/ 4 tbsp unsalted butter (, melted and slightly cooled)","1/4 cup plain oil (canola, vegetable, cottonseed etc)","3/4 cup caster sugar (superfine sugar)","1/2 tsp vanilla extract","1 large egg ((50-55g/2oz), at room temperature)"],"purpose":"Wet:"},{"ingredients":["4 drops green food colouring (, optional (Note 4))"],"purpose":"Colouring (optional)"},{"ingredients":["100g/ 3.5oz cream cheese (, at room temperature (block best, tub ok))","3/4 cup thickened cream (heavy cream) or whipping cream (Note 5)","3 tbsp caster sugar (superfine sugar)","1/2 tsp vanilla extract","2 tsp lemon juice (optional)","Pinch of salt"],"purpose":"Cream cheese whip:"}]', '[{"description":"Preheat the oven to 180°C/350°F (160° fan-forced). Grease and line a 20 cm / 8\" round cake pan with baking paper (parchment paper).","images":[],"step":1},{"description":"Pistachio powder:","images":[],"step":2},{"title":"Toast","description":"Spread the pistachios on a tray. Bake for 12 minutes, shaking once halfway, or until the pistachios smell nutty and are crisp (eat to check!). Fully cool on the tray (~15 minutes).","duration":12,"images":[],"step":3},{"title":"Blitz","description":"Measure out 3/4 cup pistachios (save the rest for decorating). Blitz into a powder using pulses, taking care not to turn it into a paste. I use a NutriBullet (2 x 2 sec bursts). Spice grinder or small food processor would also work. Some larger pistachio bits are fine, but aim for 98% powder. (Note 6)","images":[],"step":4},{"title":"Break up clumps","description":"Put the pistachio powder in a large bowl with the flour. Briefly whisk to combine then use your fingers to rub pistachio powder clumps into a powder. No need to be meticulous here, just get the larger ones.","images":[],"step":5},{"title":"Dry","description":"Add the remaining Dry ingredients then whisk to combine.","images":[],"step":6},{"title":"Wet","description":"Put all the Wet ingredients in a separate bowl and whisk until combined.","images":[],"step":7},{"title":"Combine wet & dry","description":"Pour the Wet into the Dry ingredients bowl. Use a rubber spatula to mix until the flour is almost mixed in.","images":[],"step":8},{"description":"Colour it! Add the food colouring. Then finish mixing the batter until mostly lump free (small lumps will dissolve when baked).","images":[],"step":9},{"description":"Scrape the batter into the pan and spread out it out (no need to be meticulous, the surface will smooth out in the oven).","images":[],"step":10},{"description":"Bake for 40 minutes, turning the pan at 30 minutes so the surface browns evenly, or until a skewer inserted into the centre comes out without batter on it.","duration":40,"images":[],"step":11},{"description":"Cool in the pan for 10 minutes, then turn out onto a cooling rack and cool completely. (~1 hour)","duration":10,"images":[],"step":12},{"description":"Chop the reserved pistachios (mix of finely chopped and larger chunks).","images":[],"step":13},{"description":"Spread the cake with the Cream Cheese Whip (steps below). Sprinkle with chopped pistachios. Cut and eat!","images":[],"step":14},{"description":"Cream cheese whip:","images":[],"step":15},{"description":"Beat the cream cheese for a good 2 minutes on medium high until it''s really light and creamy, scraping down the sides as needed. Do not shortcut this step, else you may end up with cream cheese lumps!","images":[],"step":16},{"title":"Whip","description":"Add the remaining ingredients then beat until the cream is softly whipped and spreadable, about 1 minute on medium high.","images":[],"step":17}]', '["egg","gluten","milk","nuts"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","dessert-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1df53751fd8e', 'en', 'US', 'Jam Drops (Thumbprint Cookies)', 'Recipe video above. Buttery vanilla shortbread biscuits filled with jam, made the old fashioned way - because you can''t improve on perfection! I''m a little more generous on the jam than typical recipes, and insist on baking the jam into the cookie rather than filling the dent in afterwards (it''s just not the same!).I also insist on making this the traditional way using your thumb to make the dent (hence the recipe name Thumbprint Cookies). Use any flavoured jam you want, though strawberry and raspberry are popular choices (strawberry is pictured), apricot is also common.', 'https://www.recipetineats.com/tachyon/2024/07/Jam-drops-Thumbprint-cookies_5-2.jpg', 26, 14, 40, 28, '[{"id": "ing_butter", "quantity": {"value": 225.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.2, "unit": "bottle of 50ml"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_flour", "quantity": {"value": 0.375, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_strawberries", "quantity": {"value": 0.3, "unit": "punnet of 250g"}}]', '[{"ingredients":["225g (2 sticks) unsalted butter, softened","3/4 cup caster sugar / superfine sugar (regular/granulated sugar ok too, Note 1)","2 tsp vanilla extract","1 large egg (, at room temperature (~50-55g/2oz))","2 1/2 cups plain flour (all-purpose flour)","1/4 tsp cooking salt / kosher salt","1/2 cup strawberry or raspberry jam (, or any other flavour, mixed well to loosen (Note 2))"]}]', '[{"description":"Abbreviated steps for baking pros:","images":[],"step":1},{"description":"Cream butter and sugar. Beat in vanilla, egg and salt, then beat in flour. Roll 3cm/1.2\" balls (#60 cookie scoop), flatten, indent, fill. Bake 14 minutes 180°C/350°F (160°C fan), cool on tray.","images":[],"step":2},{"description":"Full recipe steps","images":[],"step":3},{"description":"Preheat the oven to 180°C/350°F (160°C fan-forced). Line 2 trays with baking paper/parchment paper.","images":[],"step":4},{"title":"Cream butter and sugar","description":"Beat the butter and sugar until creamy - about 1 1/2 minutes on medium speed using an electric beater or stand mixer fitted with the paddle attachment.","images":[],"step":5},{"title":"Crumbly dough","description":"Add the vanilla, egg and salt, then beat for ~20 seconds until incorporated. Add the flour and salt, then beat until you cannot see white flour. The mixture will be crumbly.","images":[],"step":6},{"title":"Form cookies","description":"Measure out 1 tablespoon of mixture, very tightly packed (#60 cookie scoop). Tap out onto your hand, scrunch in your first to press into a dough then roll into a smooth ball (3cm/1.2\"). Flatten into a 1.25cm / 0.5\" thick disc then use your thumb to make an indent. (This method avoids cracks, see Note 3).","images":[],"step":7},{"title":"Fill","description":"Place cookie on the tray, and repeat to make 25 - 28 cookies, leaving 3.5cm / 1.5\" between each. Fill the indent with slightly heaped 1/2 teaspoon jam (Note 4).","images":[],"step":8},{"description":"Bake for 14 minutes (both trays at the same time), or until the edges are light golden and the surface is pale golden. Rotate and switch the tray shelves at the 10 minute mark, so they cook evenly.","duration":14,"images":[],"step":9},{"description":"Cool fully on the tray (the base will finish cooking). Then grab and devour!","images":[],"step":10}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","cookies","dessert-recipes","emergency-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d07d071557ac', 'en', 'US', 'Chocolate Peanut Butter Cake for a Crowd', 'Recipe VIDEO above. This sinfully delicious cake is a killer combination of my beloved rich Chocolate Cake smothered with fluffy peanut butter frosting, topped with Reece''s Peanut Butter Cups then finished with a drizzle of melted chocolate and peanut butter.It''s decadent and outrageous, so it''s perfect for feeding a crowd to a) impress b) it will easily serve 20 to 25 people, up to 30 - you don''t need giant slices because it''s so rich!You''ll love how easy the chocolate cake is to make, and the touch of salt in the frosting.', 'https://www.recipetineats.com/tachyon/2024/06/Chocolate-peanut-butter-cake-6.jpg', 30, 45, 195, 20, '[{"id": "ing_flour", "quantity": {"value": 0.263, "unit": "kg"}}, {"id": "ing_cocoa_powder", "quantity": {"value": 0.45, "unit": "pack of 250g"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.05, "unit": "tub of 150g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.037, "unit": "tub of 200g"}}, {"id": "ing_sugar", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.2, "unit": "bottle of 50ml"}}, {"id": "ing_instant_coffee_powder", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 250.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.2, "unit": "jar of 375g"}}, {"id": "ing_chocolate", "quantity": {"value": 1.0, "unit": "block of 100g"}}, {"id": "ing_cream", "quantity": {"value": 0.12, "unit": "carton of 250ml"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.2, "unit": "jar of 375g"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.2, "unit": "jar of 375g"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.2, "unit": "jar of 375g"}}, {"id": "ing_peanuts", "quantity": {"value": 0.094, "unit": "jar"}}]', '[{"ingredients":["1 3/4 cups flour (, plain / all purpose)","3/4 cup cocoa powder (, unsweetened (Note 1))","1 1/2 tsp baking powder","1 1/2 tsp baking soda (bi-carb soda) (Note 2)","2 cups white sugar (or caster/superfine sugar)","1 tsp cooking / kosher salt (yes, really!)","2 large eggs","1 cup milk (low or full fat)","1/2 cup vegetable oil (, or other plain flavoured oil like canola, grapeseed, rapeseed, sunflower)","2 tsp vanilla extract","2 tsp instant coffee powder (, OPTIONAL (Note 3))","1 cup boiling water (makes the chocolate flavour \"bloom\")"]},{"ingredients":["250g / 2 sticks unsalted butter (, softened)","4 cups (500 g) soft icing sugar / powdered sugar (, sifted (Note 4))","1/2 cup (120 g) smooth peanut butter (spread, not pure) (Note 5)","1/4 tsp cooking/kosher salt","1 tbsp milk"],"purpose":"Peanut Butter Buttercream Frosting"},{"ingredients":["1/2 cup chocolate chips or melts (US: semi sweet chips)","2 tbsp cream (thickened/heavy or pure, not low fat)","3 tbsp peanut butter (, warmed in microwave to make it runny)","120g / 4 oz mini Reece''s Peanut Butter Cups","10+ miniature Reece''s Peanut Butter Cups (, halved)","1/4 cup salted peanuts (, finely chopped)"],"purpose":"Toppings (optional, recommended)"}]', '[{"description":"Preheat oven to 180C°/350°F (160°C fan).","images":[],"step":1},{"description":"Grease a 23 x 33cm / 9 x 13\" metal cake pan with butter. Then line with paper with overhang, to make it easier to lift out. (For round pans, see Note 4).","images":[],"step":2},{"title":"Dry ingredients","description":"Sift flour, cocoa, baking powder and baking soda into a large bowl. Add Sugar and salt. Whisk briefly to combine.","images":[],"step":3},{"title":"Wet ingredients","description":"Add eggs, milk, oil and vanilla. Whisk well to combine until lump free - about 30 seconds.","images":[],"step":4},{"title":"Boiling water","description":"Add the coffee powder then the boiling water. Whisk to incorporate. The batter is VERY thin (see video). Pour batter into the cake pan.","images":[],"step":5},{"description":"Bake for 45 minutes or until a wooden skewer inserted into the centre comes out clean.","duration":45,"images":[],"step":6},{"description":"Cool for 10 minutes, then fully cool on a wire rack before frosting (~2 hours).","duration":10,"images":[],"step":7},{"description":"Peanut butter buttercream frosting","images":[],"step":8},{"description":"Beat butter for 3 minutes on high until soft and fluffy, using a stand mixer with the paddle attachment or handheld beater.","duration":3,"images":[],"step":9},{"title":"Icing sugar","description":"Add icing sugar in 3 lots. Beat it in, starting on low speed then increasing the speed (to avoid a snow storm). Once incorporated, add more icing sugar and repeat.","images":[],"step":10},{"title":"Beat 3 minutes","description":"Once the icing sugar has all been added, added the peanut butter, salt and milk. Beat on high speed for 3 minutes to make it really nice and fluffy. Ready to use!","duration":3,"images":[],"step":11},{"title":"Chocolate drizzle","description":"Place the chocolate and cream in a small bowl. Microwave in 15 second increments on high, stirring in between, until smooth. Cool for 10 minutes before using.","duration":10,"images":[],"step":12},{"title":"Frost","description":"Spread all the frosting across the surface of the cake, from edge to edge.","images":[],"step":13},{"title":"Decorate","description":"Drizzle the top randomly with half the chocolate drizzle and melted peanut butter. Sprinkle with the peanut butter cups. Drizzle with remaining chocolate and peanut butter and sprinkle with the peanuts.","images":[],"step":14},{"description":"Serve immediately! Cut into pieces as large (or small 😢) as you want. Refrigerate leftovers for 5 days though always bring to room temperature (because the frosting goes hard when cold).","images":[],"step":15}]', '["egg","gluten","milk","peanuts"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","slices-bars","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c5288095b40b', 'en', 'US', 'Zucchini cheese muffin slab', 'Recipe video above. This is a zucchini loaded savoury cheese muffin in slab form which is a handy big-batch recipe to serve lots of people without fussing with muffin tins (pain to clean!). Consider it like a zucchini slice, but more like a muffin than a frittata. Excellent shelf life of 5 days, economical to make, this will easily serve 15 to 20 people and is great to tuck into lunch boxes or serve for morning tea. Don''t be alarmed by the thickness of the batter, it gets a lot of moisture from the zucchini as it bakes! (PS Next time, try the pizza version!)', 'https://www.recipetineats.com/tachyon/2024/04/Zucchini-cheese-muffin-slab_3.jpg', 20, 40, 60, 15, '[{"id": "ing_zucchini", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_zucchini", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chilli_flakes", "quantity": {"value": 2.0, "unit": "jar of 40g"}}, {"id": "ing_flour", "quantity": {"value": 0.412, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.117, "unit": "tub of 150g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.013, "unit": "tub of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_oil", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.005, "unit": "L"}}]', '[{"ingredients":["2 zucchinis (300g / 10 oz, ~17cm/7\" long) (Note 1)","3/4 tsp cooking salt / kosher salt","2 cups (tightly packed) shredded cheese at room temperature (, like cheddar, tasty, colby, I use pre-shredded (Note 2))"]},{"ingredients":["1 medium zucchini","1 tsp extra virgin olive oil","Pinch black pepper","2 pinches sea salt flakes (optional, for sprinkling at end)"],"purpose":"Decorative topping:"},{"ingredients":["2 3/4 cups flour (, plain/all purpose)","3 1/2 tsp baking powder","1/2 tsp baking soda / bi-carbonate of soda (Note 3)","1/2 tsp cooking salt / kosher salt"],"purpose":"Dry ingredients:"},{"ingredients":["2 garlic cloves (, crushed using a garlic crusher or finely grated using a microplane)","1 cup milk (, preferably full fat, at room temp (I microwave 20 sec))","50g / 3 tbsp unsalted butter (, melted, cooled)","3 tbsp neutral oil (canola, vegetable, peanut)","2 large eggs ((55g/2 oz each), at room temperature)","1 tsp white vinegar (Note 4)"],"purpose":"Wet ingredients:"}]', '[{"title":"Sweat zucchini","description":"Grate 2 of the zucchinis using a box grater. Toss with the salt then set aside for 20 minutes. Grab handfuls and squeeze out excess liquid (no need to be super forceful here but make a bit of effort!). You should have 2 very tightly packed cups. Set aside.","duration":20,"images":[],"step":1},{"title":"Decorative zucchini","description":"Finely slice the 3rd zucchini however you want, to decorate the surface. I cut the zucchini in half then into long strips. Thin coins is also nice. Toss with the oil and pepper.","images":[],"step":2},{"description":"Preheat the oven to 200°C/400°F (180°C fan-forced). Lightly grease a 23 x 33cm / 9 x 13\" metal pan with butter. Line with paper with overhang (so you can lift it out later).","images":[],"step":3},{"title":"Batter","description":"Whisk the Dry ingredients in a large bowl using a handheld whisk. Make a well in the centre. Whisk the Wet ingredients in a separate bowl until combined. Pour the Wet into the Dry ingredients. Mix using a wooden spoon until the flour is mostly incorporated but there''s still flour visible.","images":[],"step":4},{"title":"Add-ins","description":"Add zucchini and cheese then mix through. Some flour lumps is fine. Minimise mixing else the crumb will be tough. The batter will be thick - the zucchini will sweat more in the oven.","images":[],"step":5},{"title":"Bake","description":"Scrape into the prepared pan and smooth the surface. Top with the zucchini slices. Bake for 40 minutes or until a skewer inserted in the middle comes out clean.","duration":40,"images":[],"step":6},{"title":"Cool","description":"Sprinkle with sea salt flakes. Cool in the pan for 10 minutes. Use the excess paper to slide the slab onto a cooling rack then remove the paper. Cool for at least another 10 minutes.","duration":10,"images":[],"step":7},{"description":"Cut into pieces (3 x 5 pieces, or 4 x 5). Nobody ever says no to a smear of butter either, especially if served warm!","images":[],"step":8}]', '["egg","gluten","milk","peanuts"]', '["vegetarian"]', '{"mealType":["snack"],"cuisine":["Western"],"categories":["baking-recipes","snacks","zucchini-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_083a27257b24', 'en', 'US', 'Mini chocolate cakes', 'Recipe video above. We make mini chocolate cakes because they''re adorable, there''s an excellent ratio of frosting to cake, and you get the whole thing to yourself! With 3 layers of chocolate cake smothered in fluffy chocolate buttercream frosting, these are the perfect special occasion dessert.No round cutter? Make square or rectangle layer cakes instead! Makes 7 x 3 layer cakes that are 7cm / 2.8” wide.', 'https://www.recipetineats.com/tachyon/2023/11/Mini-chocolate-cakes_2.jpg', 45, 0, 45, 7, '[{"id": "ing_flour", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_cocoa", "quantity": {"value": 50.0, "unit": "jar"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.025, "unit": "tub of 150g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.019, "unit": "tub of 200g"}}, {"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_instant_coffee_powder", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_butter", "quantity": {"value": 250.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_cocoa_powder", "quantity": {"value": 0.3, "unit": "pack of 250g"}}, {"id": "ing_chocolate", "quantity": {"value": 1.0, "unit": "block of 100g"}}, {"id": "ing_raspberries", "quantity": {"value": 1.0, "unit": "punnet of 125g"}}]', '[{"ingredients":["1 cup plain flour / all-purpose flour","1/3 cup cocoa (, sifted (unsweetened, not dutch processed - Note 1))","3/4 tsp baking powder","3/4 tsp baking soda / bi-carb (Note 2)","1 cup white sugar","1/2 tsp cooking salt / kosher salt","1 large egg (, at room temperature)","1/2 cup milk (, preferably full fat, at room temperature)","1/4 cup plain oil (, like vegetable, canola, peanut oil)","1 tsp vanilla extract","1/2 cup boiling water","1 tsp instant coffee powder (, option (Note 3))"]},{"ingredients":["250g / 1 cup unsalted butter (, softened)","4 cups soft icing sugar / powdered sugar (, sifted)","1/2 cup cocoa powder (, unsweetened)","1 tsp vanilla extract","5 tbsp milk (, preferably full fat)"],"purpose":"Chocolate Buttercream"},{"ingredients":["Dark chocolate (, finely shaved using a knife (white chocolate is also pretty))","Raspberries, rosemary sprigs"],"purpose":"Decorations"}]', '[{"description":"Preheat oven to 180°C / 350°F (160°C fan-forced).","images":[],"step":1},{"title":"Baking pan","description":"Butter a 40 x 28.5 x 2.5cm cm tray (15.8 x 11.3 x 1\" - US standard jelly roll pan) then line with baking paper (parchment paper).","images":[],"step":2},{"title":"Whisk dry","description":"Sift the flour, cocoa, baking powder and baking soda into a bowl. Add the sugar and salt, then whisk to combine.","images":[],"step":3},{"title":"Mix in wet","description":"Add the egg, milk, oil and vanilla. Whisk to combine. Dissolve the coffee in the hot water, then add into the batter. Whisk to combine. The batter will be VERY thin!","images":[],"step":4},{"title":"Bake","description":"Pour into the pan and bake for 13 minutes.","duration":13,"images":[],"step":5},{"description":"Cool for 10 minutes then use the paper overhang to lift the cake onto a rack and cool for 30 minutes (leave it on the paper). Then refrigerate uncovered for at least 1 hour before cutting rounds (cake is too soft when freshly baked).","duration":10,"images":[],"step":6},{"description":"Assembling & frosting:","images":[],"step":7},{"title":"Cutting rounds","description":"Cover the sticky surface with paper. Then flip upside down onto a cutting board (ie sticky side down). (Note 4) Peel the paper off the base. Then press out 21 x 6cm / 2.4\" rounds (or other size or shape as you desire).","images":[],"step":8},{"title":"Pipe frosting","description":"Place a piece of cake on a small piece of paper, using a dab of frosting to stop it from sliding. Pipe coils of frosting on the layers, using 3 rounds for each cake. Pipe frosting around the sides and on the top. (A cake turntable is handy if you''ve got one but not essential.)","images":[],"step":9},{"title":"Smooth frosting","description":"Smooth the frosting using a small offset spatula or knife, taking care to only touch the surface. Avoid touching the cake because it will dislodge crumbs that will end up in your frosting!","images":[],"step":10},{"description":"Decorate with piles of chocolate shards. I also used raspberries and rosemary for the photos in the post!","images":[],"step":11},{"description":"Chocolate buttercream:","images":[],"step":12},{"description":"Beat butter for 3 minutes on high until soft and fluffy. Add icing sugar in 3 lots. Beat it in, starting on low speed then increasing the speed (to avoid a snow storm). Once incorporated, add more icing sugar and repeat.","duration":3,"images":[],"step":13},{"title":"Beat 3 minutes","description":"Once the icing sugar has all been added, added the cocoa powder, milk and vanilla. Beat again, starting on low speed then increasing the speed gradually. Once the cocoa is incorporated, beat on high for 3 minutes to make it really nice and fluffy.","duration":3,"images":[],"step":14},{"title":"Piping bags","description":"Transfer to a piping bag for frosting. (This is the fastest and easiest way, trust me on this. Even a ziplock bag will work here).","images":[],"step":15}]', '["egg","gluten","milk","peanuts"]', '["vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["baking-recipes","dessert-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9d53b5251d9b', 'en', 'US', 'Bursting Blueberry Crumb Cake', 'Recipe video above. With almost double the blueberries of normal recipes and extra crunchy streusel topping, this Blueberry Crumb Cake is like a blueberry crumble on a soft, warm lemon cake. Melty scoop of vanilla ice cream on top is perfection!Please ensure your eggs, sour cream and milk are not fridge cold as they will not incorporate into the batter properly.', 'https://www.recipetineats.com/tachyon/2023/10/Blueberry-Crumb-Cake_6.jpg', 15, 65, 80, 12, '[{"id": "ing_flour", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.025, "unit": "bottle of 50ml"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.067, "unit": "tub of 150g"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.2, "unit": "tub of 250g"}}, {"id": "ing_milk", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_blueberries", "quantity": {"value": 4.0, "unit": "punnet of 125g"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}]', '[{"ingredients":["2/3 cups flour (, plain/all-purpose)","½ cup caster sugar (superfine sugar)","1/2 tsp cinnamon powder","1/8 tsp cooking/kosher salt","60g / 4 tbsp melted butter","1/4 tsp vanilla extract"],"purpose":"Crunch crumb (Streusel):"},{"ingredients":["1 1/3 cups flour (, plain/all-purpose)","2 tsp baking powder","1/4 tsp cooking/kosher salt","3/4 cup caster sugar (superfine sugar)","1 tsp vanilla extract","1 tbsp lemon zest","1/3 cup sour cream (, at room temperature (sub plain yogurt))","90 g / 6 tbsp unsalted butter (, melted then cooled slightly (don’t use piping hot))","1/3 cup sour cream (, at room temperature (sub plain yogurt))","1/3 cup milk (, at room temperature (full fat best, low fat ok))"],"purpose":"Lemon vanilla cake:"},{"ingredients":["500 g / 1 lb fresh blueberries (Note 1 for frozen)","2 tsp lemon juice","2 tbsp caster sugar (superfine sugar)","3 tbsp flour (, plain/all-purpose)"],"purpose":"Blueberries:"}]', '[{"description":"Preheat oven to 200°C / 400°F (180°C fan-forced). Line a 20cm springform pan with paper (here''s how I do it).","images":[],"step":1},{"title":"Crumb","description":"Put the flour, sugar, cinnamon and salt in a medium bowl and mix together with a fork. Then add the butter and vanilla, and use the fork to mix until all the flour is wet, then stop mixing. We want it lumpy and crumbly!","images":[],"step":2},{"description":"Zest the lemon first and put it aside for the batter before measuring out juice for the blueberry tossing.","images":[],"step":3},{"title":"Blueberries","description":"Toss the blueberries with lemon juice to wet the surface. Sprinkle with sugar and flour, toss to coat. Set aside.","images":[],"step":4},{"description":"Lemon vanilla cake:","images":[],"step":5},{"title":"Whisk dry","description":"Whisk the flour, baking powder and salt in a small bowl.","images":[],"step":6},{"title":"Whisk wet","description":"In a larger bowl, whisk the sugar, vanilla, zest and eggs until the surface is a bit foamy (~ 15 sec by hand). Add the butter and sour cream, whisk until smooth.","images":[],"step":7},{"title":"Combine wet and dry","description":"Switch to a rubber spatula. Add the flour in 3 batches, folding in between until the flour is mostly incorporated. Then add the milk and stir until combined. Some small lumps is ok!","images":[],"step":8},{"title":"Assembling","description":"Pour the batter into the pan. Scatter blueberries on top. Sprinkle any leftover flour at the bottom of the blueberry bowl on top of the blueberries. Cover with chunks of crumb, aiming for ~85% coverage. If necessary, enclose powdery bits in your fist to press them into clumps!","images":[],"step":9},{"description":"Bake for 65 minutes, rotating the pan halfway, until a skewer inserted into the centre comes out clean (blueberry smear is ok!).","duration":65,"images":[],"step":10},{"description":"Cool 10 minutes in the pan. Remove the cake from the springform pan then cool for at least another 10 minutes before cutting to serve.","images":[],"step":11},{"title":"Serving","description":"For the best blueberry crumble-cake experience, serve warm with a scoop of vanilla ice cream! Otherwise, be normal and serve it at room temperature. Ice cream or cream also welcome here.","images":[],"step":12}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","blueberries","dessert-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_35021ab74251', 'en', 'US', 'Pumpkin Cake with Cream Cheese Frosting', 'Recipe video above. Beautiful moist pumpkin cake with maple cream cheese frosting! A very easy, very forgiving recipe. Nothing gives cakes colour, texture and flavour like pumpkin!Makes a generous amount of fluffy frosting. Feel free to reduce - some reduces have cut by half!', 'https://www.recipetineats.com/tachyon/2016/11/Pumpkin-cake_close-up.jpg', 15, 40, 55, 12, '[{"id": "ing_pumpkin", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_pumpkin", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 333.333, "unit": "carton of 12"}}, {"id": "ing_sugar", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 150.0, "unit": "bottle"}}, {"id": "ing_flour", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.133, "unit": "tub of 150g"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cream_cheese", "quantity": {"value": 6.0, "unit": "block of 250g"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_maple_syrup", "quantity": {"value": 0.333, "unit": "bottle of 250ml"}}, {"id": "ing_pecans", "quantity": {"value": 0.5, "unit": "unit"}}]', '[{"ingredients":["1 2/3 cups fresh pumpkin puree (, I use this (Note 1))","15 oz / 425g canned pure pumpkin (, 1 can (Note 1))"],"purpose":"Pumpkin puree options"},{"ingredients":["4 large eggs (55-60g/2oz each), at room temperature )","1 2/3 cups white sugar (or caster/superfine sugar, Note 2)","1 cup vegetable or canola oil (or other neutral flavoured oil)","2 cups plain/all-purpose flour","4 tsp baking powder","2 tsp cinnamon powder","1 tsp cooking / kosher salt (Note 3)"],"purpose":"Other cake batter ingredients"},{"ingredients":["6 oz / 180g cream cheese (block, at room temperature (Note 4))","1 cup / 225g unsalted butter (, softened)","1 tsp vanilla extract","4 cups soft icing sugar / powdered sugar (, sifted (Note 5))"],"purpose":"Frosting"},{"ingredients":["1/3 - 1/2 cup maple syrup (don''t be shy!)","1/2 cup pecans (, roughly chopped)"],"purpose":"Finishing"}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan-forced). Spray and line a large pan around 9 x 13\" / 23 x 33cm with baking paper with overhang. (Note 6)","images":[],"step":1},{"title":"Batter","description":"In a large bowl, whisk together the eggs, sugar, oil and pumpkin. Add remaining ingredients and mix well.","images":[],"step":2},{"title":"Bake","description":"Pour batter into prepared pan. Bake for 40 minutes or until a toothpick comes out clean.","duration":40,"images":[],"step":3},{"description":"Cool for 10 minutes before turning out onto cooling rack to cool completely (~ 2 hours) before frosting.","duration":10,"images":[],"step":4},{"title":"Frosting","description":"Spread frosting on then use the back of a spoon to make swirly dents. Drizzle over maple syrup, concentrating on the dents to create maple syrup pools! Sprinkle with pecans. Then serve.","images":[],"step":5},{"title":"Cream butter","description":"Place the cream cheese and butter in a bowl. Beat for 2 minutes until smooth and fluffy.","duration":2,"images":[],"step":6},{"description":"Add the icing sugar in 3 batches, starting the beater on low after each addition to avoid a snowstorm. Once incorporated, turn the beater up to high and beat for 3 minutes or until the frosting is light and fluffy. Beat in vanilla. Use frosting immediately.","duration":3,"images":[],"step":7}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","classic-cakes","dessert-recipes","pumpkin"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_570bd0177a4a', 'en', 'US', 'Chocolate Cream Pie', 'Recipe video above. This is a magnificent yet surprisingly straight forward pie that can be made days in advance of serving. A biscuit base, filled with a creamy pudding / chocolate custard filling and topped with clouds of cream that''s made entirely from scratch. No pudding mix around here!', 'https://www.recipetineats.com/tachyon/2017/03/Chocolate-cream-pie_4.jpg', 25, 25, 55, 10, '[{"id": "ing_oreo_biscuits", "quantity": {"value": 25.0, "unit": "pack"}}, {"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.094, "unit": "pack of 400g"}}, {"id": "ing_sugar", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_egg", "quantity": {"value": 4.0, "unit": "carton of 12"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_chocolate", "quantity": {"value": 150.0, "unit": "block of 100g"}}, {"id": "ing_chocolate", "quantity": {"value": 150.0, "unit": "block of 100g"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_chocolate", "quantity": {"value": 150.0, "unit": "block of 100g"}}]', '[{"ingredients":["25 Oreo biscuits (, whole with filling in tact (244g / 8.5 oz) (Note 1))","60g / 4 tbsp unsalted butter (, melted)"],"purpose":"Crust:"},{"ingredients":["1/4 cup cornflour / cornstarch","2/3 cup caster sugar (superfine sugar)","Pinch of salt","2 cups milk (whole or reduced fat, not zero fat)","1 cup cream (pouring or thickened/heavy), or sub with milk (Note 2)","4 egg yolks","2 tbsp / 30g unsalted butter (, cut into 1cm / 0.5\" cubes)","1 tsp vanilla extract","150g/ 5 oz dark 70% cocoa chocolate ( or bittersweet chocolate, finely chopped (Note 4))","75g/ 3 oz milk chocolate (, finely chopped (Note 4))"],"purpose":"Filling:"},{"ingredients":["1 1/2 cups thickened / heavy cream (, for whipping)","2 tbsp white sugar","1/2 tsp vanilla extract"],"purpose":"Whipped cream"},{"ingredients":["Chocolate (, for grating (optional decoration))"],"purpose":"Optional garnish"}]', '[{"description":"Preheat oven to 180°C/350°F (160° fan-forced).","images":[],"step":1},{"title":"Cut round paper","description":"Cut a round piece of baking / parchment paper, the size of the pie dish (to prevent skin forming on custard). (Note 5)","images":[],"step":2},{"description":"Oreo cookie crust:","images":[],"step":3},{"title":"Blitz","description":"Break up Oreos roughly by hand and place in a food processor. Blitz into crumbs (~10 sec). Add butter, blitz to mix through. Mixture should resemble wet sand. (No food processor? Bash in ziplock bag with a rolling pin).","images":[],"step":4},{"title":"Press","description":"Pour into a 23cm / 9\" pie dish. Spread crumbs out and press firmly into the base and up the walls using your hands, spatula or something flat.","images":[],"step":5},{"title":"Bake for 10 minutes. Remove from oven","description":"the crust will be slightly puffed. Press down gently using a rubber spatula (makes it even crustier!) then allow to cool on the counter before filling.","duration":10,"images":[],"step":6},{"description":"Filling (see video, it''s helpful):","images":[],"step":7},{"title":"Whisk dry, then wet","description":"Place cornflour, sugar and salt in a large saucepan. Whisk to combine. Add milk, cream and yolks. Whisk to combine.","images":[],"step":8},{"title":"Heat to thicken","description":"Turn heat onto medium high. As the mixture warms up, whisk every now and then, but not constantly. As the liquid starts to get hot at around the 3 - 5 minute mark (you''ll see steam), turn the stove down to medium low and start to whisk constantly. You will feel and see the mixture start to thicken. Got lumps? See Note 6!","images":[],"step":9},{"title":"45 second whisk","description":"When you see slow, lazy bubbles (~6 minutes, you will need to pause whisking to see bubbles), whisk constantly for 45 seconds then take it off the stove.","duration":0.75,"images":[],"step":10},{"title":"Chocolate and butter","description":"Add butter, chocolate and vanilla. Whisk until chocolate melts and filling is smooth.","images":[],"step":11},{"description":"Assembling / setting custard","images":[],"step":12},{"description":"Pour hot filling into pie crust, filling it right to the top, smooth surface. Gently place round baking paper on surface. (Surplus custard? Note 7)","images":[],"step":13},{"description":"Cool on the counter for 2 hours then refrigerate for 12+ hours to allow the custard to fully set.","images":[],"step":14},{"title":"Whipped cream","description":"Beat whipped cream ingredients in a bowl on high for 2 to 3 minutes until softly whipped.","duration":2.5,"images":[],"step":15},{"title":"Topping","description":"Carefully peel back paper. Pile on the whipped cream, then grate chocolate across the surface.","images":[],"step":16},{"title":"Serving","description":"Keep the pie in the pie tin. Cut and serve!","images":[],"step":17}]', '["egg","milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","dessert-recipes","easter-baking-desserts","easter-recipes","egg-yolk-recipes","sweet-pies"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_49ab00407966', 'en', 'US', 'Easy Lemon Bars', 'Recipe video above. Just a handful of ingredients is all that''s required to make these fresh bars with a beautiful classic shortbread base topped with a lemon curd. This is a really easy recipe, just ensure you don''t overbake!', 'https://www.recipetineats.com/tachyon/2016/04/Lemon-Bars_2.jpg', 15, 40, 235, 16, '[{"id": "ing_flour", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 110.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 250.0, "unit": "carton of 12"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.15, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.15, "unit": "net of 500g"}}]', '[{"ingredients":["3/4 cup plain flour (all purpose flour)","1/4 cup rice flour (or cornstarch/cornflour) (Note 1)","1/2 cup icing sugar / powdered sugar (, sifted)","1/4 tsp salt","110g / 1 stick unsalted butter (, cold, cut into 1cm / 1/2\" cubes)"],"purpose":"Shortbread Base"},{"ingredients":["3 large eggs (55-60g/2oz each)","1 cup caster sugar / super-fine sugar (sub regular sugar)","2 tbsp plain flour (all purpose flour)","1 tbsp lemon zest (do this before juicing)","1/2 cup lemon juice (2 - 3 lemons)"],"purpose":"Lemon Curd Topping"}]', '[{"description":"Preheat oven to 180C/350F (160C fan). Spray a 20cm/8\" square tin with oil and line with baking/parchment paper with overhang (so it can be lifted out once cooked).","images":[],"step":1},{"title":"Base","description":"Place Shortbread Base ingredients in a food processor fitted with the standard \"S\" blade. Pulse 5 to 10 times until it becomes like sand. (Or use tips of fingers, Note 2). Pour into the tin, spread, then press firmly into the base, pushing it right up to the edges. Using something flat to press in is helpful!","images":[],"step":2},{"description":"Bake base for 20 minutes or until golden on the edges and pale golden in the middle. Remove from oven. (⚠️ Note: don''t let it cool, pour in curd immediately).","duration":20,"images":[],"step":3},{"title":"Lemon Curd","description":"While the base is baking, place Lemon Topping ingredients in a bowl and whisk until combined.","images":[],"step":4},{"title":"Bake 20 minutes","description":"Pour Lemon Curd onto base, then bake for 20 minutes until the topping is set but still soft.","duration":20,"images":[],"step":5},{"title":"Cool","description":"Remove from then oven and cool on the counter for 1 hour, then fridge for at least 2 hours. Slice into 16 squares. Dust with icing sugar (confectionary sugar) and serve!","images":[],"step":6}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","dessert-recipes","quick-and-easy","slices-bars"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_13dfadb9e064', 'en', 'US', 'Apple turnovers - with cream filled option!', 'Recipe video above. There''s nothing like a fresh homemade Apple Turnover! The flavour of the filling is so much better than store bought. While I adore the sentiment of cream filled turnovers, these days I tend to serve warm turnovers with cream for dunking. Easier and faster, plus the turnovers are sooo good warm!', 'https://www.recipetineats.com/tachyon/2023/08/Apple-turnovers_8-1.jpg', 20, 30, 50, 8, '[{"id": "ing_apples", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.025, "unit": "pack of 400g"}}, {"id": "ing_cinnamon", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.05, "unit": "bottle of 50ml"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_cream", "quantity": {"value": 2.0, "unit": "carton of 250ml"}}, {"id": "ing_cream", "quantity": {"value": 2.0, "unit": "carton of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}]', '[{"ingredients":["4 Granny Smith apples (, peeled, diced into 1.25cm cubes, 6 cups (Note 1))","2 tsp cornflour/cornstarch (thickens sauce)","1 tsp cinnamon","1/2 cup white sugar","1/2 tsp vanilla extract","Pinch salt"],"purpose":"Apple turnover filling:"},{"ingredients":["2 square puff pastry sheets ( (25 cm/10\"), butter best (Note 3))","1 egg (, whisked)"],"purpose":"Apple turnover:"},{"ingredients":["2 batches Stabilised whipped cream OR stiff whipped cream (Note 3)"],"purpose":"Cream filled version:"},{"ingredients":["1 batch Whipped cream for dunking ( - for easy option (Note 4))","Icing sugar / powdered sugar (, for dusting (optional))"],"purpose":"Optional serving extras:"}]', '[{"title":"Filling","description":"Put apples in a large saucepan. Toss with cornflour. Add everything else. Cook on medium to medium-high heat, stirring regularly, for 5 minutes. Apple should be softened but not mushy or losing shape, with some but not too much caramel.","duration":5,"images":[],"step":1},{"title":"Cool","description":"Spread the filling on a large plate then let it fully cool. (Note 5)","images":[],"step":2},{"description":"Line a large cutting board or upside down tray with baking/parchment paper.","images":[],"step":3},{"title":"Make turnovers","description":"Working one puff pastry sheet at a time, barely thawed, cut into 4 squares (12.5cm/5\"). Brush 2 sides with egg, then pile filling on the egg brushed side. Avoid using sauce, soaks base and if it leaks onto edge it will not seal. (Save leftover sauce & apple for pancakes, french toast, ice cream etc!)","images":[],"step":4},{"title":"Wrap","description":"Fold over, seal with fork dipped in flour (prevents sticking to pastry). Transfer to paper lined cutting board.","images":[],"step":5},{"description":"Refrigerate for 20 minutes (cold = better puffing).","duration":20,"images":[],"step":6},{"description":"Preheat oven to 200°C/400°F (180°C fan).","images":[],"step":7},{"title":"Bake 25 min","description":"Slide the paper with the turnovers on it onto a large baking tray. (Note 6 for why) Brush turnovers with egg. Stab 3 times. Bake 25 minutes or until golden.","images":[],"step":8},{"description":"Serve warm, dusted with icing sugar and whipped cream for dunking.","images":[],"step":9},{"description":"Cream filled option","images":[],"step":10},{"description":"Transfer turnovers to a cooling rack. Fully cool. Split seam side open with knife. Pipe in cream. EAT!","images":[],"step":11}]', '["egg","milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","bite-size-desserts","dessert-recipes","quick-and-easy","sweet-pies"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e5fad33842c2', 'en', 'US', 'Glazed lemon loaf', 'Recipe video above. Just a lovely lemon loaf with really great lemon flavour that''s fuss-free to make, easy to transport and serve. Oil and yogurt keeps the crumb moist while butter adds lovely flavour. It stays fresh for 5 days!Everybody loves the lemon glaze but it''s also terrific without because you can toast it, slather with butter then drizzle with honey. SO GOOD!', 'https://www.recipetineats.com/tachyon/2023/06/Glazed-lemon-loaf_4.jpg', 15, 65, 260, 8, '[{"id": "ing_flour", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.133, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.3, "unit": "tub of 500g"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_butter", "quantity": {"value": 75.0, "unit": "block of 250g"}}, {"id": "ing_oil", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.05, "unit": "bottle of 50ml"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.188, "unit": "kg"}}]', '[{"ingredients":["2 cups plain flour / all-purpose flour (Note 1 for GF)","4 tsp baking powder","1/8 tsp salt"],"purpose":"Dry ingredients:"},{"ingredients":["1 cup plain yogurt (, at room temperature)","2 large eggs ((~55g/2oz each), at room temperature)","75g / 5 tbsp unsalted butter (, melted and cooled)","1/4 cup vegetable or canola oil (or other neutral flavoured oil)","2 tbsp lemon zest (~2 large lemons)","1/4 cup lemon juice","1 1/4 cups caster sugar / superfine sugar (sub normal/granulated sugar)","1/2 tsp vanilla extract","1 1/2 tsp lemon extract ( - sub 1 tbsp extra zest (Note 3))"],"purpose":"Wet ingredients (Note 2 – room temp):"},{"ingredients":["1 cup soft icing sugar/powdered sugar (, sifted)","3 - 3 1/2 tsp+ lemon juice"],"purpose":"Glaze (optional):"}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan-forced). Grease then line a 21 x 11 x 7 cm (8.5 x 4.5 x 2.75\") with baking / parchment paper. (Note 4)","images":[],"step":1},{"title":"Batter","description":"Whisk Dry ingredients in a large bowl. Whisk Wet ingredients in a separate bowl. Pour Wet ingredients into the Dry ingredients. Whisk just until lump free. Pour into the prepared loaf pan then smooth the surface.","images":[],"step":2},{"description":"Bake 45 minutes uncovered. Loosely cover with foil then bake a further 20 minutes or until a skewer inserted comes out clean.","images":[],"step":3},{"title":"Cool & glaze","description":"Stand 10 min in pan then turn out onto a cooling rack. Fully cool before glazing (~3 hours). Use a spoon to spread and coax lovely glaze drips down the side! Cut thick slices and serve.","images":[],"step":4},{"title":"Glaze","description":"Whisk ingredients until combined and smooth, a thick smooth frosting that will drip thickly, not be transparent. Start with 3 1/2 teaspoons lemon juice, and add 1/2 tsp extra, as needed. (Note 5 on thickness)","images":[],"step":5}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","breads","dessert-recipes","quick-and-easy","quick-bread"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1402ec1089de', 'en', 'US', 'No-bowl Chocolate Nut Bars', 'Recipe video above. Not a single bowl is required to make these bars! Everything is put together right in the cake pan. Hot contender for the world''s best emergency baked goodie!Tastes: caramel-y, chewy, chocolatey and peanuty. Like a caramel slice but with peanuts - and much faster to make!', 'https://www.recipetineats.com/tachyon/2015/09/No-bowl-choc-nut-bars_9.jpg', 10, 30, 220, 16, '[{"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_plain_sweet_biscuits", "quantity": {"value": 150.0, "unit": "pack"}}, {"id": "ing_desiccated_coconut", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_peanuts", "quantity": {"value": 0.375, "unit": "jar"}}, {"id": "ing_chocolate", "quantity": {"value": 1.0, "unit": "block of 100g"}}, {"id": "ing_milk", "quantity": {"value": 0.395, "unit": "L"}}]', '[{"ingredients":["100g (7 tbsp) unsalted butter (, cut into a few chunks)","1 cup (100g) plain biscuits, crushed (eg. Marie, Arrowroot, digestives, Graham crackers - Note 1)","1 cup desiccated coconut (unsweetened)","1 cup unsalted peanuts (, or other nuts of choice (Note 2))","1 cup dark choc chips (US: semi-sweet chips) (Note 2)","395g (14 oz) (1 can) sweetened condensed milk (Note 3)"]}]', '[{"description":"Preheat oven to 180C/350F (160C fan-forced)","images":[],"step":1},{"title":"Line pan","description":"Lightly spray a 20cm/8\" square pan with oil then press in a sheet of paper (no need to be meticulous here).","images":[],"step":2},{"title":"Melt butter","description":"Place the butter in the pan then melt in the oven for 5 minutes.","duration":5,"images":[],"step":3},{"title":"Biscuit base","description":"Swirl pan to spread butter then sprinkle over crushed biscuits. Spread then gently press down (again, I am not meticulous about evenness here).","images":[],"step":4},{"title":"Layer","description":"Scatter over the coconut, followed by about 2/3 of the peanuts and choc chips (reserve some for the top). Pour over condensed milk, spread for even coverage. Top with remaining nuts and chocolate chips.","images":[],"step":5},{"description":"Bake for 30 minutes or until the edge of the surface is golden brown.","duration":30,"images":[],"step":6},{"description":"Fully cool before cutting (3 hours on counter, or 1 hr counter + 1 hr fridge). Remove using paper overhang then cut and eat!","images":[],"step":7}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","dessert-recipes","quick-and-easy","slices-bars"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6ac35d9a86b7', 'en', 'US', 'Up-and-go breakfast muffins!', 'Recipe video above. No more dry, bland healthy muffins. These are healthy - but delicious!! Just 1 1/4 tsp of oil and 2 tsp honey per muffin, lower fat than usual sweet-treat muffins, refined sugar free and contain extra dietary fibre. Great for breakfast because it''s not sweet like cake. But also morning tea - they are just sweet enough for me. :) Stays fresh for days.', 'https://www.recipetineats.com/tachyon/2023/05/Up-and-go-breakfast-muffins_9.jpg', 15, 25, 40, 12, '[{"id": "ing_oil", "quantity": {"value": 50.0, "unit": "bottle"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.167, "unit": "L"}}, {"id": "ing_yogurt", "quantity": {"value": 0.1, "unit": "tub of 500g"}}, {"id": "ing_honey", "quantity": {"value": 0.25, "unit": "jar of 500g"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.05, "unit": "bottle of 50ml"}}, {"id": "ing_wheat_germ_wheat_bran", "quantity": {"value": 1.25, "unit": "unit"}}, {"id": "ing_flour", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.033, "unit": "tub of 150g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.025, "unit": "tub of 200g"}}, {"id": "ing_raspberries", "quantity": {"value": 2.0, "unit": "punnet of 125g"}}, {"id": "ing_apples", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_chocolate", "quantity": {"value": 1.25, "unit": "block of 100g"}}]', '[{"ingredients":["1/3 cup coconut oil (, virgin or unrefined (normal oil also works but not as tasty, Note 1))","1 large egg (, at room temperature (~55g/2oz))","2/3 cup milk (, at room temperature - full fat best (low fat and non-dairy ok too))","1/3 cup yogurt (, plain/unsweetened)","1/2 cup honey (or maple syrup)","1/2 tsp vanilla extract"],"purpose":"Wet:"},{"ingredients":["1 1/4 cups wheat germ (best) (OR 1 1/4 cups (80g) wheat bran (Note 2))","1 1/2 cups wholemeal flour (sub ordinary flour - Note 3)","1/4 tsp salt","1 tsp cinnamon powder","1 tsp baking powder (Note 4)","1 tsp baking soda (, sifted if lumpy (or 3 tsp extra baking powder) - Note 4)"],"purpose":"Dry:"},{"ingredients":["250g / 8 oz raspberries (, 18 set aside and cut in half to decorate top if desired)","2 cups diced fresh fruit ((not watery) - like apples, pears)","1 1/4 cups dried fruit, nuts, choc chips etc"],"purpose":"Add ins – CHOOSE ONE:"}]', '[{"description":"Preheat oven to 190°C / 375°F (170°C fan). Line a 12 hole standard muffin tin with muffin cases OR spray generously with oil.","images":[],"step":1},{"title":"Whisk wet","description":"Place coconut oil in a microwave proof bowl. Microwave for 45 seconds on high or until melted. Add remaining Wet ingredients, whisk until smooth.","duration":0.75,"images":[],"step":2},{"title":"Mix in Dry","description":"Sprinkle the Dry ingredients across the surface in the order listed. Mix just until combined.","images":[],"step":3},{"title":"Raspberries","description":"Gently stir in the whole raspberries or other add-ins of choice.","images":[],"step":4},{"title":"Fill muffin tin","description":"Divide batter between the 12 holes using an ice cream scoop. Decorate top with halved raspberries.","images":[],"step":5},{"description":"Bake 25 minutes. Cool 5 minutes then transfer to a cooling rack.","images":[],"step":6}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["breakfast","snack"],"cuisine":["Baking"],"categories":["baking-recipes","breakfast-recipes","cupcakes-and-muffins","dessert-recipes","dietary","low-calorie-recipes","muffin-recipes","snacks"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0c2b48695f4f', 'en', 'US', 'Brown butter oatmeal choc chip cookies', 'Recipe video above. This is extremely fast and easy, and ridiculously good. No creaming butter, no chilling cookie dough. Don’t pause to wonder if it’s worth the extra 3 minutes to brown the butter. I’m telling you it is! It makes them extra-buttery with a nutty edge. Off the charts delish!DESCRIPTION: Chewy in the middle (thanks to oats) with crispy edges. Extra buttery flavour! Use choc chips for convenience but if you''re making to impress, chop your own. Makes 22 cookies 7cm/2.7" wide', 'https://www.recipetineats.com/tachyon/2023/04/Brown-butter-oatmeal-choc-chip-cookie_8.jpg', 10, 20, 30, 22, '[{"id": "ing_butter", "quantity": {"value": 150.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_rolled_oats", "quantity": {"value": 0.45, "unit": "pack of 500g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.025, "unit": "tub of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_chocolate", "quantity": {"value": 200.0, "unit": "block of 100g"}}]', '[{"ingredients":["150g/10 tbsp unsalted butter (, cut into 1cm / 1/2\" cubes)","1 cup flour (, plain/all-purpose)","1 1/2 cups rolled oats (not quick or steel cut)","1 tsp baking soda (bi-carb) (, sifted if lumpy)","1/8 tsp cooking/kosher salt","1 cup brown sugar (tightly packed)","1 large egg (, at room temperature (~55g/2oz))","1 tsp vanilla extract","200g/ 7 oz 70% dark chocolate block, I use Lindt (Note 1, sub 1 cup / 200g chips)"]}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan). Lightly grease then line three baking trays with paper.","images":[],"step":1},{"title":"Brown butter","description":"Melt butter in a small silver pan or saucepan over medium heat (Note 2). Leave to simmer on medium heat for 3 to 5 minutes, stirring every now and then, until (when you push foam aside) you see little golden-brown bits. Immediately pour the butter and all the brown bits into a large mixing bowl (large enough to mix the cookie dough) and set aside to cool for 5 minutes.","duration":4,"images":[],"step":2},{"title":"Chop choc","description":"Cut the chocolate into 1cm /1/4\" pieces. Transfer the chunks into a bowl and leave the fine chocolate dust behind for another purpose (makes cookies speckled, Note 1).","images":[],"step":3},{"title":"Mix dry ingredients","description":"Whisk flour, oats, baking soda, and salt in a large bowl.","images":[],"step":4},{"title":"Back to the butter","description":"Add sugar to the brown butter and whisk (it might not combine fully). Add egg and vanilla, whisk until smooth.","images":[],"step":5},{"title":"Finish dough","description":"Add dry ingredients into the egg-butter mixture. Mix with a wooden spoon until the flour is almost mixed in. Add chocolate, and stir until mixed through and you can no longer see flour. Set aside for 5 minutes to let the mixture firm up a bit.","duration":5,"images":[],"step":6},{"title":"Cookies","description":"Scoop a heaped tablespoon of dough onto the tray, 5 cm / 2 \" apart. (I use a size 40 cookie scoop, makes 22 cookies) Flatten to 8 mm / 1/3\" thick, reshaping sides if needed if they split/go wonky.","images":[],"step":7},{"title":"Bake","description":"Bake 2 trays for 11 minutes, switching shelves and rotating the tray at the 7 minute mark, or until the surface is light golden. For 1 tray, bake 10 minutes, rotating the tray at the 6 minute mark.","duration":11,"images":[],"step":8},{"description":"Cool on the tray for 10 minutes, then transfer onto a cooling rack to fully cool. (A sprinkle of salt flakes wouldn''t go astray!)","duration":10,"images":[],"step":9}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","cookies","dessert-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_008546a82a2f', 'en', 'US', 'Hot Cross Buns recipe', 'Recipe video above. Fluffy, perfectly spiced homemade Hot Cross Buns! Watch video to see the dough before and after kneading, and how I roll the balls to get nice smooth golden tops. Also, see below for the NO KNEAD version!', 'https://www.recipetineats.com/tachyon/2017/03/Hot-Cross-Buns-5.jpg', 25, 20, 165, 12, '[{"id": "ing_yeast", "quantity": {"value": 0.03, "unit": "pack of 5 sachets"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_bread", "quantity": {"value": 5.0, "unit": "loaf"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.025, "unit": "jar of 40g"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.025, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sultanas", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_oranges", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_flour", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.075, "unit": "L"}}, {"id": "ing_jam", "quantity": {"value": 0.037, "unit": "jar of 370g"}}]', '[]', '[{"title":"Mix dry","description":"Place flour, yeast, sugar, all spice, cinnamon, and salt in a large bowl. Briefly mix with stand mixer fitted with a dough hook.","images":[],"step":1},{"title":"Add wet","description":"Add butter, milk, egg, sultanas and zest.","images":[],"step":2},{"title":"Standmixer","description":"Mix for 5 minutes until a smooth elastic dough forms. Start on speed 2 then once the ingredients are combined, increase to speed 4. After 1 minute, add extra flour if required, just enough so dough comes away from side of bowl when mixing and doesn''t stick terribly to your fingers. (Note 5).","duration":5,"images":[],"step":3},{"title":"Hand kneading","description":"Alternatively, dust a work surface with flour and knead by hand for 10 minutes.","duration":10,"images":[],"step":4},{"description":"Dough is kneaded enough when it''s smooth and does not break when stretched - see photos & video for before/after comparison.","images":[],"step":5},{"description":"Leave dough in the bowl, cover with cling wrap and place in a warm, wind free place to rise until doubled in size. This will take anywhere between 30 minutes to 1 1/2 hours depending on how warm it is - see Note 6.","images":[],"step":6},{"description":"Forming Balls (watch video, it''s helpful):","images":[],"step":7},{"description":"Line a 31.5 x 23.5 cm / 9 x 13\" tray with baking paper with overhang.","images":[],"step":8},{"description":"Remove cling wrap and punch dough to deflate.","images":[],"step":9},{"description":"Dust work surface with flour, place dough on work surface, shape into a log - this will deflate the air. Cut into 12 equal pieces.","images":[],"step":10},{"description":"Take one piece and press down with palm, then use your fingers to gather into a ball, then roll the dough briefly to form a ball. This stretches the dough on one side and that''s how I get a nice smooth surface.","images":[],"step":11},{"description":"Place the ball with the smooth side up on the tray. Repeat with remaining dough. Line them up 3 x 4.","images":[],"step":12},{"description":"Spray a piece of cling wrap lightly with oil (any), then loosely place over the tray.","images":[],"step":13},{"title":"Return tray to warm place and leaver 30","description":"45 minutes, until the dough has risen by about 75% (less than double in size).","images":[],"step":14},{"description":"Partway through Rise #2, preheat oven to 180°C/350°F (all oven types).","images":[],"step":15},{"description":"Mix flour and water until a thick runny paste forms - see video for thickness required.","images":[],"step":16},{"description":"Spoon into a round 3 mm piping bag or small ziplock bag then snip corner.","images":[],"step":17},{"description":"Remove the cling wrap and pipe crosses onto the buns. Go slow so it hugs the curves.","images":[],"step":18},{"description":"Bake in preheated oven (180°C/350°F) for 22 minutes, or until the surface is a deep golden brown. The surface colour is the best test for this recipe.","duration":22,"images":[],"step":19},{"description":"Meanwhile, place jam and water in a bowl, microwave for 30 seconds. Mix to combine.","duration":0.5,"images":[],"step":20},{"description":"Remove buns from oven. Use overhang to lift buns onto a cooling rack.","images":[],"step":21},{"description":"Brush with jam mixture while warm. Allow to cool to warm before serving.","images":[],"step":22}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","dessert-recipes","easter-baking-desserts","easter-brunch-recipes","easter-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_fe2e9d604a83', 'en', 'US', 'Cheesecake stuffed carrot bundt cake', 'Recipe video above. Perfect for a party, this combines two holiday favorites into one - a carrot Bundt cake with creamy cheesecake inside! A combination that everybody adores. Inspired by a cake spied on my friend Jennifer Sabin Sattley’s website, Carlsbad Cravings (love!).You will need 2 full blocks of cream cheese for this recipe. Take care with the glaze thickness - keep it thick so it blankets the cake generously. Not the usual thin see-through glaze. Feel so cheated!', 'https://www.recipetineats.com/tachyon/2023/04/Cheesecake-stuffed-carrot-bundt-cake-2.jpg', 45, 60, 105, 14, '[{"id": "ing_pineapple", "quantity": {"value": 400.0, "unit": "unit"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_cocoa_powder", "quantity": {"value": 0.06, "unit": "pack of 250g"}}, {"id": "ing_cream_cheese", "quantity": {"value": 340.0, "unit": "block of 250g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.2, "unit": "tub of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.05, "unit": "bottle of 50ml"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 250.0, "unit": "carton of 12"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.05, "unit": "tub of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_milk", "quantity": {"value": 0.167, "unit": "L"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_carrot", "quantity": {"value": 300.0, "unit": "pack of 1kg"}}, {"id": "ing_desiccated_coconut", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_walnuts", "quantity": {"value": 150.0, "unit": "jar"}}, {"id": "ing_cream_cheese", "quantity": {"value": 340.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}]', '[{"ingredients":["400g/14 oz can crushed pineapple ( in natural juice (Note 1))","unsalted butter (, for greasing)","1 tbsp cocoa powder (unsweetened), for dusting (Note 2)"]},{"ingredients":["340g / 12 oz cream cheese block (, softened (Note 3))","1/3 cup sour cream (, full fat (yoghurt also ok))","1/2 cup white sugar (regular/granulated)","2 tsp lemon zest","1/2 tsp vanilla extract","3 tbsp plain/all-purpose flour","1 large egg (, at room temperature)"],"purpose":"Cheesecake Stuffing:"},{"ingredients":["2 cups plain/all-purpose flour","2 tsp baking soda/bi-carb (NOT baking powder, Note 4)","1/2 tsp salt (cooking/kosher salt)","2 tsp cinnamon powder","2/3 cup milk (, full fat, at room temperature (not fridge-cold))","1 tsp white vinegar (Note 5)","3 large eggs (, at room temperature)","1 1/2 cups (packed) brown sugar","1/2 cup canola oil (or other neutral oil)","2 cups shredded carrot (, using a box grater (2 carrots))","1/4 cup desiccated coconut (, unsweetened (finely shredded, not large flakes))","1 cup walnuts (, roughly chopped)"],"purpose":"Batter:"},{"ingredients":["115 g / 4 oz cream cheese (, softened (Note 3))","30g/ 2 tbsp unsalted butter (, softened)","1/2 tsp vanilla extract","2 cups soft icing sugar / powdered sugar (, sifted)","1 1/2 tbsp milk (, full-fat, plus more as needed)","1 tbsp lemon juice"],"purpose":"Thick cream cheese glaze:"}]', '[{"description":"Preheat oven to 200°C/400°F (180°C fan). Grease a 12-cup (3 litre) Bundt pan (Note 6) with butter, then dust well with cocoa, shaking out excess. (Why cocoa? See Note 2)","images":[],"step":1},{"title":"Prep pineapple","description":"Drain pineapple in a colander, pressing out excess juice and reserving. Set pineapple and juice aside.","images":[],"step":2},{"title":"Cheesecake filling","description":"Using an electric beater, beat the cream cheese, sour cream, sugar, lemon and vanilla just until smooth. Beat in flour, just until incorporated. Beat in egg until mixed in. Transfer cheesecake mix into a piping bag and refrigerate until required.","images":[],"step":3},{"title":"Batter","description":"Whisk together the flour, baking soda, salt, and cinnamon in a large bowl. Set aside. In a separate bowl, combine the milk, vinegar, eggs, brown sugar, canola oil, and ¼ cup of the reserved pineapple juice. Whisk until smooth, then stir in the crushed pineapple, shredded carrot, coconut flakes, and walnuts, if using. Pour this over the flour mixture and gently stir until combined.","images":[],"step":4},{"title":"Assemble","description":"Pour about 2 1/2 cups of batter into the Bundt pan. Cut a 1.8cm / 3/4\" hole in the end of the piping bag. Pipe a ring of the filling directly on top of the batter—avoid touching sides of pan. Cover with remaining batter.","images":[],"step":5},{"description":"Bake for 30 minutes. Remove, cover loosely with foil and bake for another 30 minutes. Check with a skewer to ensure it''s cooked (straight down into cheesecake, and also on the inner wall of the ring)","duration":30,"images":[],"step":6},{"title":"Glaze","description":"Cool 20 minutes in the pan. Invert on to a rack and allow to fully cool. Spoon the glaze on top, allowing it to drip down the sides of the cake. Sprinkle with walnuts, if using. Cut with a hot knife (for neater slices) and serve!","images":[],"step":7},{"description":"Cream cheese glaze:","images":[],"step":8},{"description":"Beat butter, cream cheese, and vanilla until smooth. Beat in icing sugar in two batches, starting on a low speed first (to avoid powder storm!).","images":[],"step":9},{"title":"Adjust thickness","description":"Beat in milk and lemon juice. Add extra milk 1 teaspoon at a time until it becomes a thick glaze - BE CAREFUL, it will go from too thick to too thin with just a tiny bit of milk! GOAL: a glaze you can spoon onto the cake, so it oozes thickly down the sides, rather than being thin and transparent like most glazes.","images":[],"step":10}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":["Holiday","Western"],"categories":["baking-recipes","cheesecakes","dessert-recipes","easter-baking-desserts"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_53b9a4d0751c', 'en', 'US', 'Easiest Ever Raspberry Jam Bars', 'Recipe video above. The charm of a crumble pie but in convenient hand-held form, Raspberry Jam Oat Bars have a buttery oatmeal base, a layer of jam, then topped with a crumble. Love how the same mixture is used for the base and crumbly topping. Handy - and fast to make!', 'https://www.recipetineats.com/tachyon/2016/07/Raspberries-jam-oat-bars_1.jpg', 10, 30, 100, 16, '[{"id": "ing_butter", "quantity": {"value": 125.0, "unit": "block of 250g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_flour", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_rolled_oats", "quantity": {"value": 0.45, "unit": "pack of 500g"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.017, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_raspberries", "quantity": {"value": 1.2, "unit": "punnet of 125g"}}]', '[{"ingredients":["125g / 1 stick unsalted butter (, melted)","1/2 cup brown sugar (, tightly packed)","1 large egg (55-60g / 2 oz)","1 1/2 cups flour (plain / all-purpose)","1 1/2 cups rolled oats (traditional oats, not quick, instant or steel-cut)","1/2 tsp baking powder","Pinch salt","1 cup raspberry jam (or other flavour)"]}]', '[{"description":"Preheat oven to 200°C/400°F (180°C fan). Grease a 20cm/8\" metal pan with butter then line with baking/parchment paper with overhang (so it can be lifted out once cooked).","images":[],"step":1},{"title":"Oatmeal cookie base","description":"Melt butter in a microwave proof bowl. Mix in sugar until lump free. Add egg then mix until incorporated. Then add flour, oats, baking powder and salt and mix until you can no longer see flour.","images":[],"step":2},{"title":"Base","description":"Spread 1 1/2 cups of the mixture in the prepared pan, and press in with your hands. Spread with jam (microwave to loosen, if needed), then use your hands to crumble the remaining mixture over the top (Note 3).","images":[],"step":3},{"title":"Bake for 30","description":"35 minutes or until the top is deep golden. Remove and allow to fully cool in the pan (~ 2 hours) before lifting out of the tin using the baking paper. (Speed things up: 30 min counter, 30 minute fridge)","duration":32.5,"images":[],"step":4},{"description":"Cut into 16 squares. Enjoy!","images":[],"step":5}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","dessert-recipes","quick-and-easy","slices-bars"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8b0007b02552', 'en', 'US', 'Easy Lemon Coconut Almond Cake', 'Recipe video above. Many people have tried this now and no one thinks of it as a gluten free cake. It''s just a delicious cake! Coconut and lemon is a lovely flavour combination with the subtle flavour of almond meal. Lovely springy, moist crumb like the fan-favourite orange cake. Bonus: Just about the fastest, easiest cake recipe I know!1 1/2 tsp of lemon zest mightn''t sound like much but the lemon flavour comes through just the right amount, in my opinion. :)', 'https://www.recipetineats.com/tachyon/2023/03/Lemon-coconut-cake_2.jpg', 10, 40, 110, 10, '[{"id": "ing_butter", "quantity": {"value": 150.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 333.333, "unit": "carton of 12"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_almonds", "quantity": {"value": 0.15, "unit": "pack of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.033, "unit": "tub of 150g"}}, {"id": "ing_desiccated_coconut", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.015, "unit": "net of 500g"}}, {"id": "ing_almonds", "quantity": {"value": 0.15, "unit": "pack of 250g"}}]', '[{"ingredients":["150g / 10 tbsp unsalted butter","4 large eggs ((55-60g/2oz each), at room temp)","1 tsp vanilla extract","3/4 cup caster sugar (superfine sugar, Note 2)","1 1/2 cups almond meal (ground almond, Note 1)","1/4 tsp cooking/kosher salt","1 tsp baking powder","3/4 cup desiccated coconut (US: finely shredded unsweetened coconut)","1 1/2 tsp lemon zest (1 large lemon)","1/4 cup flaked almonds (, optional (Note 3))"]}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan). Grease a 20cm/8” round cake pan (or springform pan) with butter then line with paper.","images":[],"step":1},{"title":"Melt butter","description":"Place the butter in a large microwavable bowl and melt in the microwave. Let cool for a couple of minutes.","images":[],"step":2},{"title":"Wet ingredients","description":"Add egg, vanilla and sugar and whisk until combined.","images":[],"step":3},{"title":"Dry ingredients","description":"Add almond meal, salt, baking powder, coconut and lemon zest. Whisk until combined.","images":[],"step":4},{"title":"Bake 40 minutes","description":"Pour into pan. Sprinkle over almonds. Bake 40 minutes. Cool 15 minutes in pan then carefully turn out onto cooling rack.","images":[],"step":5},{"description":"Cool at least 1 hour before cutting slices to serve. Moist enough to serve plain - doesn''t need cream or anything!","images":[],"step":6}]', '["egg","milk","nuts"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","dessert-recipes","dietary","easter-baking-desserts","gluten-free-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_18ab296cdf46', 'en', 'US', 'Lunchbox pizza bread (quick)', 'Recipe video above. A quick to make pizza bread, made for tucking into lunchboxes or a great savoury snack for morning tea. It''s something I created as an economical alternative to pizza bread from Bakers'' Delight, a popular Australian bakery chain. Use store-bought pizza sauce and pre-shredded cheese for convenience (true to name!), and whatever toppings your heart desires. Sour cream and olive oil keeps the crumb moist so it will stay fresh for 4 days in an airtight container.', 'https://www.recipetineats.com/tachyon/2023/02/Lunchbox-pizza-bread_8-1.jpg', 15, 40, 55, 12, '[{"id": "ing_flour", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.05, "unit": "tub of 150g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.013, "unit": "tub of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.15, "unit": "tub of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_pizza_sauce", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 0.25, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_kalamata_olives", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.01, "unit": "jar of 50g"}}]', '[{"ingredients":["2 cups plain flour (all-purpose flour)","1 1/2 tsp baking powder","1/2 tsp baking soda / bi-carb soda (, sifted (Note 1))","1/2 tsp cooking/kosher salt"],"purpose":"DRY INGREDIENTS:"},{"ingredients":["1 large egg (60g / 2 oz)","1 cup milk (full or low fat)","1/4 cup sour cream (, or plain yogurt)","3 tbsp olive oil"],"purpose":"WET:"},{"ingredients":["1 cup shredded cheese ( (colby, cheddar, Monterey Jack, Devondale \"3 cheese blend\") (Note 2))"],"purpose":"CHEESE FOR BATTER:"},{"ingredients":["1 1/2 cups shredded cheese, ( same as above (Note 2))","1/2 cup pizza sauce (, store bought or homemade (any of them))","1/4 red onion (, finely sliced)","1/2 green capsicum / bell pepper (, finely sliced)","1/4 cup sliced kalamata olives","50g/ 2 oz pepperoni slices (about 1/2 cup)"],"purpose":"PIZZA TOPPINGS:"}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan). Oil spray a 23 x 33 cm (9 x 13\") metal pan then line with baking / parchment paper (Note 3).","images":[],"step":1},{"description":"Whisk Dry ingredients in a large bowl.","images":[],"step":2},{"description":"Whisk Wet ingredients in a separate bowl until combined.","images":[],"step":3},{"title":"Combine Wet & Dry","description":"Pour Wet into the Dry ingredients. Mix with a rubber spatula until the flour is mostly mixed in but you can still see a bit of flour. Add cheese then stir until you can no longer see flour. Some small lumps is fine, they will bake out.","images":[],"step":4},{"title":"Assemble","description":"Scrape into the baking pan and evenly spread - it''s not that thick, remember it rises! Spread the surface with pizza sauce. Sprinkle with cheese, then (in this order) onion, capsicum, olives then pepperoni.","images":[],"step":5},{"title":"Bake 40 min","description":"Bake 25 minutes uncovered. Cover with a baking tray (or foil) then bake for a further 15 minutes.","images":[],"step":6},{"description":"Cool 10 minutes in the pan then use the paper overhang to lift or slide out onto a cooling rack. Cool for a further 10 minutes before slicing to serve.","images":[],"step":7},{"title":"Serving","description":"Great at room temp though for VIP''s, sometimes I warm it in the oven, drizzle with a swish of olive oil and sprinkle with a pinch of oregano.","images":[],"step":8}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["lunch","snack"],"cuisine":["Western"],"categories":["baking-recipes","breads","pizza-recipes","quick-and-easy","snacks","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0ee6448958b5', 'en', 'US', 'Eclairs', 'Recipe video above. While éclairs in the wonderful world of French pastries are made with custard hidden inside, éclairs as we know them here in Australia are split and generously filled with whipped cream. A neat trick for a great éclair cream filling is adding mascarpone. It adds structure so the cream doesn’t completely squirt out when you take a bite (because don’t you just hate that!?), as well as improving storage quality.And as for the choux pastry? It’s light-as-air and beautifully crisp, something you rarely see with store bought eclairs!', 'https://www.recipetineats.com/tachyon/2022/11/Eclairs_0a.jpg', 45, 120, 165, 20, '[{"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 333.333, "unit": "carton of 12"}}, {"id": "ing_chocolate", "quantity": {"value": 100.0, "unit": "block of 100g"}}, {"id": "ing_cream", "quantity": {"value": 0.667, "unit": "carton of 250ml"}}, {"id": "ing_corn", "quantity": {"value": 3.5, "unit": "can of 400g"}}, {"id": "ing_cream", "quantity": {"value": 0.667, "unit": "carton of 250ml"}}, {"id": "ing_mascarpone", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sugar", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_vanilla_bean_paste", "quantity": {"value": 10.0, "unit": "jar"}}]', '[{"ingredients":["100g / 7 tbsp unsalted butter (, cut into 1 cm / 1/2\" cubes)","1 cup water","1 cup plain/all-purpose flour","Pinch cooking/kosher salt","4 large eggs (55-60g/2oz each) (, at room temperature (Note 1))"],"purpose":"CHOUX PASTRY"},{"ingredients":["100g/ 3.5 oz 70% cocoa dark chocolate block (, finely chopped (Note 2))","2/3 cup thickened/heavy cream (Note 3)","3 1/2 teaspoons corn syrup or liquid glucose (Note 4)"],"purpose":"SHINY CHOCOLATE GLAZE:"},{"ingredients":["3 cups thickened/heavy cream or whipping cream (min 35% fat, Note 3)","1 cup mascarpone (40%+ fat, Note 6)","1 2/3 cups icing sugar/powdered sugar (, sifted)","2 tsp vanilla bean paste or extract or, 2 vanilla pods (Note 7)"],"purpose":"STABILISED CHANTILLY CREAM (Note 5)"}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan). Position one shelf in the top third of the oven and another in the lower third. Lightly spray 3 trays with canola oil and line with baking/parchment paper.","images":[],"step":1},{"title":"Simmer liquid","description":"Melt butter in a medium saucepan over medium heat. When the butter is almost melted, add water.","images":[],"step":2},{"title":"Flour","description":"Once the liquid starts simmering, add flour and salt, and vigorously stir with a wooden spoon (while still on the stove). The mixture will turn pasty then in about 10 seconds it will transform into a sticky ball of dough that comes away from the walls of the saucepan. Once this happens, remove from the stove and leave to cool for 10 minutes (no longer).","duration":10,"images":[],"step":3},{"title":"Eggs","description":"Add eggs one at a time, mixing vigorously with a wooden spoon after each addition, making sure each egg is incorporated before adding the next. At first, the mixture will look separated but when you keep stirring, it comes together. When finished the mixture should be a sticky, thick paste that holds its shape, not sloppy and loose (see video or photos).","images":[],"step":4},{"title":"Pipe","description":"Transfer mixture into a piping bag fitted with a 15 mm star tip (Note 8). Pipe logs 12-14 cm long, 2.5 cm wide, 1.5 cm tall, 5 cm apart from each other. (5\" long, 1\" wide, 0.6\" tall, 2\" apart) Do not crowd the tray else they won’t go crispy. You should get around 20.","images":[],"step":5},{"description":"Bake 2 trays on the shelves for 45 minutes. At the 30 minute mark, open the oven door for 2 seconds to release steam (makes them crispier), then again at 35 minutes and 40 minutes. Remove the tray at 45 minutes.","duration":45,"images":[],"step":6},{"title":"Cool","description":"Remove choux buns from the oven and allow to fully cool on the trays. If you used 3 trays, bake the 3rd tray of choux pastry per above directions.","images":[],"step":7},{"title":"Split","description":"Slice choux buns in half horizontally.","images":[],"step":8},{"description":"Shiny chocolate glaze:","images":[],"step":9},{"description":"Place chocolate in a bowl.","images":[],"step":10},{"title":"Pour over hot cream","description":"Heat cream and glucose in a small saucepan over medium heat until just below boiling. Pour mixture over chocolate, shake so the chocolate is submerged. Let stand for 1 minute.","duration":1,"images":[],"step":11},{"description":"Mix with a rubber spatula until smooth (do not use a whisk, it creates bubbles). Transfer into a wide, shallow bowl large enough to dip the eclairs.","images":[],"step":12},{"title":"Coat eclairs","description":"Dip the lid of each éclair into the chocolate. Place on a tray and refrigerate for 30 minutes until the chocolate is firm to the touch.","duration":30,"images":[],"step":13},{"title":"Whip cream","description":"Place all the Chantilly Cream ingredients in a bowl. Whip using an electric beater on medium high for 3 minutes or until stiff peaks form. Transfer into piping bag fitted with a star tip.","duration":3,"images":[],"step":14},{"title":"Fill eclairs","description":"Pipe in cream using whatever pattern takes your fancy, generously thick. Place the lid on then serve!","images":[],"step":15}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Australian","British","French"],"categories":["baking-recipes","bite-size-desserts","dessert-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cb288684dc42', 'en', 'US', 'Whipped cream (Chantilly Cream)', 'Recipe video above. My recipe for whipped cream that I use for "everything". It''s actually Chantilly cream, the French name for whipped cream that''s lightly sweetened and flavoured with vanilla. Use to decorate cakes, pipe onto cupcakes, dollop on fruit and swirl onto sundaes!⚠️ IMPORTANT: You MUST use whipping cream, not pouring cream that cannot be whipped! Check the carton label - they should say if the cream is for whipping. Some readers have had issues with the cream not whipping and I suspect that is the reason. 😢Yield - Cream doubles in volume when whipped. So 1 cup cream (250ml) = 2 cups whipped (500ml).** See separate recipe here for STABILISED WHIPPED CREAM that will hold its form for 2 - 3 days, this is super handy!**', 'https://www.recipetineats.com/tachyon/2022/11/Chantilly-cream_5.jpg', 5, 0, 5, 2, '[{"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_vanilla_bean_paste", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_vanilla_pod", "quantity": {"value": 1.0, "unit": "jar"}}]', '[{"ingredients":["1 cup heavy / thickened cream or whipping cream (, cold - NOT pouring cream! (Note 1))","1/2 cup icing sugar/powdered sugar (, sifted, sub 2 tbsp white sugar (Note 2))"],"purpose":"Whipped cream"},{"ingredients":["1 tsp vanilla extract (my standard) (- best economical option)","1 tsp vanilla bean paste (- my most used \"good\" option)","1 vanilla pod (, seeds scraped (PREMIUM option))"],"purpose":"Vanilla flavour – choose ONE (Note 3):"}]', '[{"title":"Whip cream","description":"Place the cream, icing sugar, vanilla of choice. Whip using an electric beater on medium high, moving the beater around the bowl, or until whipped to stiffness you are after. Then it''s ready for use!","images":[],"step":1},{"title":"Stiffness options","description":"Whip for around 1 1/2 minutes if you want soft peaks (kind of dollops) or 2 minutes for stiff peaks (for piping). See in post for photos of soft vs stiff peaks. If scaling up, it will take longer.","images":[],"step":2},{"title":"To use","description":"Fill a piping bag with nozzle of choice and pipe. Spread onto cakes or dollop on a bowl of fruit or onto pies!","images":[],"step":3}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Australian","British","French"],"categories":["baking-recipes","dessert-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_46fdfe348364', 'en', 'US', 'My Perfect Apple Pie', 'Recipe video above. Basic Apple Pie recipes just call for piling raw apples in an uncooked pie crust. It will work ... but the crust will have raw patches, be soggy, the apples unevenly cooked and you''ll have a giant empty cavity under the pie lid. Hmm.If, like me, that''s not good enough for you, make my Perfect Apple Pie! The trick: bake the apples for the filling first and blind bake your crust. Result? Superior flavour, perfectly cooked apple filling, a crispy base and no unsightly gaping cave under your pie lid!NOTE: Saddened to see mixed reviews where the wrong apple types has been used. This recipe is made for Granny Smith Apples! Other apples are not juicy enough or too soft. Please follow the recipe!', 'https://www.recipetineats.com/tachyon/2022/11/Apple-Pie_8.jpg', 60, 120, 180, 10, '[{"id": "ing_x_homemade_shortcrust_pastry", "quantity": {"value": 2.0, "unit": "pack"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_apples", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_cinnamon", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_ginger", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_round_nutmeg", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_cream", "quantity": {"value": 0.004, "unit": "carton of 250ml"}}]', '[{"ingredients":["2 x homemade shortcrust pastry ( this recipe, or store bought (Note 1))","1 egg (, lightly whisked)","2 tsp white sugar (granulate/regular, not caster/superfine), optional (Note 2)"]},{"ingredients":["2kg/ 4 lb Granny Smith apples (, cored, peeled, halved, cut into 1 cm / 1/3\" thick slices. (Note 3))","1 cup brown sugar","1 tsp ground cinnamon","1/2 tsp ground ginger","1/4 tsp ground nutmeg","3/4 tsp cooking/kosher salt","1 tsp unsalted butter"],"purpose":"Apple pie filling:"},{"ingredients":["Vanilla ice cream, cream"],"purpose":"Serving"}]', '[{"title":"Shortcrust","description":"Make a double batch of my shortcrust pastry recipe. Form the dough discs, wrap and refrigerate per the recipe.","images":[],"step":1},{"title":"Line tin","description":"Roll out one dough just large enough to fit a 23cm/9\" metal pie tin, following directions in the shortcrust recipe. You want the base relatively thick so it''s sturdy. Trim off excess pastry, prick the base 30 times with a fork (don''t pierce through).","images":[],"step":2},{"title":"Freeze (Note 4)","description":"Cover with cling wrap and freeze for 2 hours.","images":[],"step":3},{"description":"While crust is freezing, make apple filling. Then continue with pie crust steps.","images":[],"step":4},{"description":"Preheat oven to 200°C / 400°F (180°C fan).","images":[],"step":5},{"title":"Blind bake (Note 5)","description":"Place two large sheets of baking/parchment paper in a \"X\" over the pie tin then fill with baking beads (Note 4). Bake 25 minutes.","images":[],"step":6},{"title":"Egg wash (Note 5)","description":"Remove from oven. Use paper excess to remove beads into a bowl. Brush base and sides (not rim) lightly with whisked egg. Return crust to oven for 5 minutes.","duration":5,"images":[],"step":7},{"title":"Cool","description":"Crust should be light golden and look fully cooked. Cool 15 minutes before filling.","images":[],"step":8},{"description":"Lattice (Note 6 for full lid):","images":[],"step":9},{"description":"Remove remaining dough from fridge 30 minutes prior. Roll out to 3 mm / 1/8\" thick and cut into 12 x 2.5cm/1\" strips. Transfer to board, cover with cling wrap and refrigerate until required.","images":[],"step":10},{"description":"Apple Pie Filling:","images":[],"step":11},{"description":"Preheat oven to 180°C / 350°F (160°C fan).","images":[],"step":12},{"title":"Spice mix","description":"Mix the sugar, cinnamon, ginger, nutmeg and salt in a bowl.","images":[],"step":13},{"title":"Toss","description":"In a large bowl, sprinkle spice mix over apple slices. Toss well with hands, separating pieces that are stuck together.","images":[],"step":14},{"title":"Bake","description":"Spread across 2 large trays. Bake until soft but still holding form - check first at 15 min, and every 5 mins thereafter (mine take 40 min - Note 7). Do not stir or rotate trays.","images":[],"step":15},{"title":"Drain off juices","description":"Remove trays from oven. Using a spatula to hold the apples back, pour apple juices into a saucepan (drain off what you can, you don''t need every drop).","images":[],"step":16},{"title":"Cool apple","description":"Leave apple slices to cool on the tray, about 15 minutes.","images":[],"step":17},{"title":"Apple syrup","description":"Add butter to apple juice saucepan and simmer on low heat until it reduces to 1/3 cup (80 ml), becoming syrupy. This might take 1 minute if you didn''t start with much juices, or 3 - 5 minutes if you started with 1/2 cup or more juices. Remove from stove and let cool.","images":[],"step":18},{"description":"Assemble and bake:","images":[],"step":19},{"description":"Turn oven up to 200°C/400°F (180°C fan).","images":[],"step":20},{"title":"Fill","description":"Use a spatula or egg flip to scoop up apple slices. Fill the pie crust with 2/3 of the apples, gently pressing out air pockets. Then arrange the remaining apples on top so they mound slightly at the centre. Pour apple syrup over the slices and any residual juices from the baking trays.","images":[],"step":21},{"title":"Pastry lattice or lid: Top with pastry lattice","description":"see in post for my method. Trim excess, and press to adhere on to pie crust rim using water to seal. Brush lattice with egg wash (avoid the pie rim else it will over-brown there), ensuring you don''t get pools of egg in the joins. Sprinkle with sugar.","images":[],"step":22},{"description":"Bake 45 minutes or until the pastry is golden and you see the syrup bubbling through the lattice.","images":[],"step":23},{"title":"Serving fresh","description":"Cool at least 3 hours before cutting to serve!","images":[],"step":24},{"title":"Option for neat slices","description":"After cooling, refrigerate overnight. Turn pie out of pie dish (it''s sturdy enough once cooled). Then you can cut neat slices. Place on a tray, cover with foil and reheat for 10 minutes in a 180°C/350°F oven (or microwave in emergency!).","duration":10,"images":[],"step":25},{"description":"In either case serve with vanilla ice cream, always!","images":[],"step":26}]', '["egg","milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","dessert-recipes","sweet-pies"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a5bc4d03536a', 'en', 'US', 'Mini cheesecakes', 'Recipe video above. Fabulously adorable little individual cheesecakes that are perfect for gatherings. They are easier to make than 1 large cheesecake and a whole lot less messy to serve! Decorate with berries and whipped cream, or use the topping from this Strawberry or Blueberry Cheesecake.Please ensure the fridge ingredients are at room temperature so the filling mixture is completely smooth. Nobody wants little lumps in their cheesecake!', 'https://www.recipetineats.com/tachyon/2022/11/Mini-cheesecakes_8-2.jpg', 15, 27, 42, 12, '[{"id": "ing_digestive_biscuits_or_graham_crackers", "quantity": {"value": 150.0, "unit": "pack"}}, {"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.016, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_cream_cheese", "quantity": {"value": 375.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.3, "unit": "tub of 250g"}}, {"id": "ing_lemon", "quantity": {"value": 0.015, "unit": "net of 500g"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_cream", "quantity": {"value": 1.5, "unit": "carton of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_strawberries", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_mint", "quantity": {"value": 12.0, "unit": "bunch"}}]', '[{"ingredients":["150g/ 5 oz digestive biscuits (10 pieces) or Graham Crackers (20 squares) ( (Note 1 for other biscuits))","60g / 4 tbsp unsalted butter (, melted)","1 tbsp caster sugar (superfine sugar)","1/8 tsp cinnamon powder (optional)","Pinch of salt"],"purpose":"Base:"},{"ingredients":["375g / 12 oz cream cheese (block), at room temperature (Note 2)","1 1/2 tbsp flour (, plain / all-purpose)","1 tsp vanilla extract","1/2 cup sour cream (, room temperature (or plain yogurt))","1/2 cup caster sugar (superfine sugar)","1 1/2 tsp lemon zest (1 lemon)","Pinch of salt","2 large eggs (, must be at room temperature (Note 3))"],"purpose":"Filling:"},{"ingredients":["1 1/2 cups thickened / heavy cream","1/2 tsp vanilla extract","15g / 2 tbsp icing sugar / powdered sugar (, sifted (or 1 tbsp caster sugar))"],"purpose":"Chantilly Cream:"},{"ingredients":["Strawberries (small), blueberries and raspberries","12 small sprigs of mint","Icing sugar / powdered sugar (, for dusting)"],"purpose":"Decorating (optional):"}]', '[{"description":"Preheat oven to 160°C / 325°F (140°C fan) with the shelf 1/3 from the bottom of the oven. Line a 12-hole standard muffin tin with paper muffin liners.","images":[],"step":1},{"title":"Blitz","description":"Break the crackers up with your hands then blitz in a food processor until they form fine crumbs - about 10 seconds or so. (Note 4) Add remaining Base ingredients, blitz to combine. It should have the texture of wet sand.","images":[],"step":2},{"title":"Press","description":"Divide mixture between the muffin tin holes. Press down firmly to flatten using something flat and round. A 1/3 cup measure fits perfectly in mine my tin holes for this purpose.","images":[],"step":3},{"title":"Bake","description":"Backe for 7 minutes then cool bases for 5 minutes before filling.","duration":7,"images":[],"step":4},{"title":"Filling (Note 5)","description":"Beat cream cheese on speed 5 of an electric beater just until smooth (~ 10 seconds). Add flour, vanilla, sour cream, sugar and lemon. Beat on speed 5 just until combined (~10 seconds). Beat in eggs one at a time just until incorporated. Mixture should be like a thick pancake batter.","images":[],"step":5},{"title":"Bake filling","description":"Divide mixture between muffin holes. Use it all - you can can go within 3mm of rim as it won’t rise much. Bake for 20 minutes.","duration":20,"images":[],"step":6},{"title":"Chill","description":"Remove from the oven then cool for 1 hour on the counter in the muffin tin. When cooled, cover with baking/parchment paper then loosely with cling wrap. Refrigerate for at least 6 hours and preferably overnight, or until the liner can be peeled off cleanly.","images":[],"step":7},{"description":"Decorate and serve:","images":[],"step":8},{"title":"De-chill","description":"If you have the time, remove cheesecakes from the fridge 30 minutes prior to serving, to take some of the fridge chill out (the cheesecake is nicer at room temperature).","images":[],"step":9},{"title":"Chantilly cream","description":"Place ingredients in a bowl and beat on high until the cream is thick enough to pipe/dollop.","images":[],"step":10},{"title":"Decorate","description":"Pipe or dollop with cream, decorate with berries, dust with icing sugar. Serve proudly!","images":[],"step":11}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","bite-size-desserts","cheesecakes","dessert-recipes","easter-baking-desserts"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_353ff630895f', 'en', 'US', 'Cinnamon Apple Bread', 'Recipe video above. This is a great, relatively quick-to-make sweet loaf bread ideal for afternoon tea or breakfast treat. The most time-consuming part is chopping the apple because there''s quite a lot of the fruit in this! Yogurt and oil make the crumb beautifully moist so it will stay fresh for days. I like to add walnuts for soft crunch but it''s entirely optional. The apple slice topping is also optional. So many options! :)Want apple muffins instead? Here it is!', 'https://www.recipetineats.com/tachyon/2022/10/Cinnamon-Apple-Bread_7.jpg', 20, 85, 105, 10, '[{"id": "ing_apples", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_apples", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_flour", "quantity": {"value": 0.263, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.033, "unit": "tub of 150g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.013, "unit": "tub of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.225, "unit": "tub of 500g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_oil", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_walnuts", "quantity": {"value": 150.0, "unit": "jar"}}]', '[{"ingredients":["1 Granny Smith apple (, quartered, cored, thinly sliced 3 mm / 1/8\" thick (Note 1))","1 1/2 tbsp demerara sugar (or turbinado sugar, Note 2)","1/4 tsp cinnamon powder"],"purpose":"Topping (optional):"},{"ingredients":["3 cups diced Granny Smith apple (, 1/2” cubes, skin on (approx 2 large apples) (Note 2))","1 tsp cinnamon powder","3 tbsp brown sugar"],"purpose":"Cinnamon Apple:"},{"ingredients":["1 tsp cinnamon powder","1/2 tsp ginger powder (Note 3)","1/4 tsp allspice (or mixed spice) (Note 3)","1 3/4 cups plain / all-purpose flour","1 tsp baking powder","1/2 tsp baking soda (, sifted (Note 4))","1/4 tsp cooking / kosher salt"],"purpose":"Batter – Dry:"},{"ingredients":["3/4 cup brown sugar","3/4 cup yogurt (, plain unsweetened (sub sour cream), at room temperature (Note 5))","2 eggs (, at room temperature (Note 5))","1/2 cup canola oil (or other neutral flavoured oil)","1 tsp vanilla extract"],"purpose":"Batter – Wet:"},{"ingredients":["1 cup walnuts (, toasted, roughly chopped into 1cm/1/3\" pieces (not too small) (Note 6))"],"purpose":"Walnuts (optional):"}]', '[{"description":"Preheat oven to 200°C/390°F (180°C fan). Position shelf in the middle of the oven.","images":[],"step":1},{"title":"Loaf pan (Note 7)","description":"Use a 21.5 x 11.5 x 7 cm / 4.5 x 8.5 x 2.75\" pan. Spray with canola oil then line the long side + base with a single piece of paper leaving some overhang (don’t worry about lining short sides).","images":[],"step":2},{"title":"Topping","description":"Mix the Demerara sugar and cinnamon in a small bowl. Set aside.","images":[],"step":3},{"title":"Cinnamon Apple","description":"Mix Cinnamon Apple ingredients in a bowl. Set aside while you prepare the batter (the sugar will make the apple sweat = good thing!).","images":[],"step":4},{"title":"Batter","description":"Whisk the Dry ingredients in a bowl. In a separate bowl, whisk Wet ingredients. Pour Wet mix into the Dry bowl, whisk just until smooth. Stir in apples (including all juices) and walnuts. Batter should be thick but dollop-able (not pourable in thin stream, nor thick like sticky bread dough). Scrape into loaf pan, smooth surface.","images":[],"step":5},{"title":"Topping","description":"Take 1/4 of the apple slices, fan out (so they''re overlapping) then arrange on top. Repeat in two more lots of 1/4 of an apple. (I find to cover the surface, I only use 3/4 of the apple.) Sprinkle with the cinnamon sugar.","images":[],"step":6},{"description":"Bake 60 minutes. Cover loosely with foil, bake for further 25 minutes or until skewer inserted into the centre comes out smooth.","images":[],"step":7},{"description":"Rest 15 minutes in the pan then use paper overhang to remove to a rack. Cool at least 1 hour on rack before slicing!","images":[],"step":8},{"title":"Serving","description":"The bread is moist and flavoured enough to eat plain though nobody complains if it''s lightly toasted and slathered with butter!","images":[],"step":9}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","quick-bread","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ce0e20245cd6', 'en', 'US', 'Blueberry Custard Cake', 'Recipe video above. A vanilla cake with custard baked into it, studded with bursting blueberries. Rustic. Easy. Dreamy. You''ll love how you can cut neat slices but the custard is melt-in-your-mouth!', 'https://www.recipetineats.com/tachyon/2022/09/Blueberry-Custard-Cake-3-copy.jpg', 15, 55, 70, 12, '[{"id": "ing_milk", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_vanilla_bean_paste", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_sugar", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 3.125, "unit": "carton of 12"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.131, "unit": "pack of 400g"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_oil", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_egg", "quantity": {"value": 3.125, "unit": "carton of 12"}}, {"id": "ing_yogurt", "quantity": {"value": 0.15, "unit": "tub of 500g"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.05, "unit": "bottle of 50ml"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_flour", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.067, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_blueberries", "quantity": {"value": 2.0, "unit": "punnet of 125g"}}]', '[{"ingredients":["1 1/2 cups milk (, full fat)","1 tsp vanilla bean paste (or extract)","1/3 cup superfine/caster sugar (Note 1)","1/4 cup / 60 g egg yolks (~4 large eggs) ( (Note 2))","3 1/2 tbsp cornflour / cornstarch","30 g / 2 tbsp unsalted butter (, cold, cut into 1 cm / 1/2\" cubes)"],"purpose":"Custard:"},{"ingredients":["1/2 cup superfine/caster sugar (Note 1)","1/4 cup canola oil (or other neutral oil)","1 large egg (Note 3)","1/2 cup plain yogurt (Note 4)","1/2 tsp vanilla extract","2 tsp lemon zest (, finely grated (1 large lemon))"],"purpose":"Cake – wet:"},{"ingredients":["1 cup flour (, plain / all-purpose)","2 tsp baking powder","Pinch of salt"],"purpose":"Cake – Dry:"},{"ingredients":["250 g / 8 oz blueberries (, fresh or frozen (do not thaw))"],"purpose":"Blueberries:"}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan) with the shelf in the middle of the oven.","images":[],"step":1},{"description":"Grease a 20 cm / 8\" springform pan with butter. Line the base and sides with paper.","images":[],"step":2},{"title":"Heat milk","description":"Heat the milk with vanilla and half the sugar in a medium saucepan over medium heat until hot.","images":[],"step":3},{"title":"Whisk egg","description":"Whisk yolks with remaining sugar, then whisk in the cornflour.","images":[],"step":4},{"title":"Milk into egg","description":"Slowly pour about 1/2 cup hot milk into the eggs while whisking. Once incorporated, pour in remaining milk and whisk to combine.","images":[],"step":5},{"title":"Thicken","description":"Pour the mixture back into the saucepan. Cook on medium, whisking constantly until you feel it starting to thicken then immediately turn down to low (2 - 3 minutes). Keep whisking then when you see a lazy bubble appear and burst on the surface, whisk for 30 seconds longer.","duration":0.5,"images":[],"step":6},{"title":"Enrichen with butter","description":"Take off the stove. Whisk in butter until smooth. Scrape into a bowl then cover with cling wrap touching surface. Leave to cool while making the batter (Note 5 for custard tips)","images":[],"step":7},{"title":"Batter","description":"Whisk Wet ingredients in a large bowl. Add the Dry ingredients then whisk until smooth. Remove 1/3 cup of the batter (Note 5) then pour the remaining batter into the prepared pan and smooth the surface. (Bake the 1/3 cup batter in a separate greased ramekin for 25 minutes).","duration":25,"images":[],"step":8},{"title":"Custard topping","description":"Whisk custard until smooth. Dollop half around the edges of the cake surface then spread inwards with offset knife. Smooth the surface, then scatter with half the blueberries. Mix remaining blueberries into remaining custard, then spread across the cake surface, pressing blueberries in to flatten the surface.","images":[],"step":9},{"title":"Bake 45 minutes","description":"Place the cake in the oven and bake for 35 minutes. Remove, then use 2 small paring knives to burst some of the blueberries on the surface (1 knife to stop blueberry spinning, the other to burst). Limit bursting time to 1 minute, no longer! Then bake for a further 10 minutes.","duration":35,"images":[],"step":10},{"title":"Cool","description":"Remove cake from the oven. Fully cool in the cake pan (around 3 hours). Then refrigerate for 12 hours, still in the pan.","images":[],"step":11},{"description":"Serve! Remove cake from the pan then cut into slices. Best served at room temperature rather than fridge cold!","images":[],"step":12}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","dessert-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c0271e827580', 'en', 'US', 'Flourless Chocolate Brownies (gluten free)', 'Recipe video above. Like my flourless chocolate cake, I make these Flourless Chocolate Brownies even when I’m not after a gluten free dessert because they’re that good! Using almond meal instead of flour adds lovely undertones of nuttiness as well as guaranteeing they''ll be fudgy and moist.Very easy, forgiving recipe, hard to stuff up. See note for scaling up. See all my gluten free recipe here.', 'https://www.recipetineats.com/tachyon/2014/05/Flourless-Chocolate-Brownies-Gluten-Free_3-1.jpg', 15, 25, 40, 16, '[{"id": "ing_chocolate", "quantity": {"value": 1.0, "unit": "block of 100g"}}, {"id": "ing_butter", "quantity": {"value": 85.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_almonds", "quantity": {"value": 0.4, "unit": "pack of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.1, "unit": "kg"}}]', '[{"ingredients":["1 cup dark chocolate chips or melts / semi-sweet chocolate (Note 1)","85 g / 6 tbsp unsalted butter (, cut into 1 cm / 1/2\" cubes)","1/4 tsp cooking/kosher salt","3/4 cup brown sugar (sub white)","1 tsp vanilla extract","2 large eggs (55-60g / 2 oz each)","2/3 cup almond meal / ground almonds (or almond flour, Note 2)","1/3 cup rice flour (Note 3)"]}]', '[{"description":"Preheat the oven to 180°C / 325°F (160°C fan-forced) with a rack in the lower third of the oven.","images":[],"step":1},{"title":"Preparation","description":"Grease and line a 20cm / 8\" square pan with baking paper (parchment paper) with excess overhang so it''s easy to lift out the brownie when cooked.","images":[],"step":2},{"title":"Melt butter and chocolate","description":"Place chocolate, butter and salt in a heatproof bowl. Microwave in 3 x 30 second bursts on high, mixing in between, until melted and smooth. You could also do this over simmering water on the stove.","images":[],"step":3},{"title":"Cool 5 minutes","description":"Mix well to combine the chocolate and butter then leave to cool for 5 minutes.","duration":5,"images":[],"step":4},{"title":"Add vanilla, sugar and eggs","description":"Stir in the vanilla and sugar. Crack the eggs straight into the bowl, and stir until combined.","images":[],"step":5},{"title":"Add dry","description":"Add almond meal and rice flour, and mix very well until fully combined.","images":[],"step":6},{"title":"Bake","description":"Pour the batter into the prepared pan and smooth the surface. Bake for 25 minutes or until the brownies are slightly puffed all over and a toothpick inserted into the center comes out moist but clean. You want it to be moist!","duration":25,"images":[],"step":7},{"title":"Cool and serve","description":"Cool brownies for at least 30 minutes in the pan. Remove the brownie by holding the edges of the baking paper, fully cool on a rack. Then cut into squares (3 x 3 for gigantic ones, 4 x 4 for sensible ones). See Note 4 for more cutting tips.","images":[],"step":8}]', '["egg","gluten","milk","nuts"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","dessert-recipes","dietary","gluten-free-recipes","most-popular","quick-and-easy","slices-bars"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_da3146e306fa', 'en', 'US', 'Christmas Cookies (Vanilla Biscuits / Sugar Cookies)', 'Recipe video above. These cookies are made for cutting out into shapes because they hold their shape when baking! They are plain, sweet vanilla biscuits that are perfect for icing and decorating as you please - and wonderful served plain too. NO CHILL!', 'https://www.recipetineats.com/tachyon/2019/12/Christmas-Cookies-Sugar-Cookies_7.jpg', 25, 10, 35, 40, '[{"id": "ing_butter", "quantity": {"value": 225.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.15, "unit": "bottle of 50ml"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_flour", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.025, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}]', '[{"ingredients":["225g / 1 cup unsalted butter (, softened (or use salted, skip salt))","1 cup caster/superfine sugar (granulated/ordinary white sugar ok too)","1 1/2 tsp vanilla extract","1 large egg (55-60g / 1.9-2oz)","3 cups flour (, plain / all purpose)","3/4 tsp baking powder","3/4 tsp salt"]},{"ingredients":["Icing for Sugar Cookies"],"purpose":"Icing for Sugar Cookies"}]', '[{"description":"Preheat Oven to 180°C / 350°F (160°C fan). Line 2 baking sheets with parchment paper.","images":[],"step":1},{"description":"Beat butter and sugar in a large bowl until creamy (1 minute on speed 5)","images":[],"step":2},{"description":"Add egg and vanilla, beat until completely combined.","images":[],"step":3},{"description":"Add flour, baking powder, and salt.","images":[],"step":4},{"description":"Start mixing slowly, then beat until the flour is incorporated - it will be clumpy.","images":[],"step":5},{"description":"Dust work surface with flour, scrape dough out of bowl. Pat together then cut in half, then shape into 2 discs.","images":[],"step":6},{"description":"Roll out to 0.3cm / 1/8\" (for thinner, crispier cookies) or 0.6cm / 1/4\" (for thicker, softer cookies), sprinkling with flour under and over the dough so it doesn''t stick.","images":[],"step":7},{"description":"Use cookie cutters to press out shapes and use a knife or spatula to transfer shapes to prepared baking sheets. (Keep dough that doesn''t fit in the oven in the fridge).","images":[],"step":8},{"description":"Bake for 10 minutes, swapping trays halfway (Note 2), until the surface is pale golden and the edges are just beginning to turn light golden.","duration":10,"images":[],"step":9},{"description":"Allow cookies to cool completely on trays (they will finish cooking on the trays).","images":[],"step":10},{"description":"Decorating options:","images":[],"step":11},{"title":"Icing","description":"see Icing for Christmas Cookies recipe.","images":[],"step":12},{"description":"Melt chocolate then dip the surface into chocolate.","images":[],"step":13},{"description":"Dot with icing sugar and decorated with silver balls","images":[],"step":14},{"description":"Dust with icing sugar","images":[],"step":15},{"description":"Serve plain! They are sweet vanilla biscuits so they are wonderful eaten just as they are!","images":[],"step":16}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","cookies","dessert-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7a2f530afb82', 'en', 'US', 'Blueberry Bread Loaf', 'Recipe video above. A quick blueberry lemon bread that is fast to prepare! Incredibly moist, bursting with blueberries and the fresh hint of lemon. The glaze is optional - it''s delicious even without!', 'https://www.recipetineats.com/tachyon/2016/06/Blueberry-Lemon-Loaf_34.jpg', 15, 75, 90, 8, '[{"id": "ing_flour", "quantity": {"value": 0.263, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.067, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.3, "unit": "tub of 500g"}}, {"id": "ing_egg", "quantity": {"value": 250.0, "unit": "carton of 12"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.5, "unit": "bottle of 50ml"}}, {"id": "ing_oil", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_blueberries", "quantity": {"value": 1.8, "unit": "punnet of 125g"}}, {"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_milk", "quantity": {"value": 1.0, "unit": "L"}}]', '[{"ingredients":["1 3/4 cups flour (, plain / all purpose)","1 cup white sugar (, preferably caster/superfine)","2 tsp baking powder","Pinch of salt"],"purpose":"Dry"},{"ingredients":["1 cup plain yoghurt (preferably not low fat)","3 large eggs (, 55 - 60g / 2oz each)","2 tsp lemon zest (1 large or 2 small lemons)","1/2 teaspoon vanilla extract","1/2 cup canola oil (or vegetable, grapeseed oil)"],"purpose":"Wet"},{"ingredients":["2 tsp flour","1 1/2 cups frozen or fresh blueberries (no need to defrost)"],"purpose":"Blueberries"},{"ingredients":["1 1/2 cups soft icing sugar / powdered sugar (, sifted)","2 tbsp lemon juice","1-2 tbsp milk (, if needed)"],"purpose":"Optional lemon glaze"}]', '[{"description":"Preheat oven to 200°C/390°F (180°C fan forced).","images":[],"step":1},{"title":"Line loaf pan","description":"Butter and line a loaf pan with parchment / baking paper. I used a 21 x 11 x 7 cm pan (8.3 x 4.5 x 2.75\") which makes a nice tall loaf.","images":[],"step":2},{"title":"Coat blueberries","description":"Toss blueberries in flour (less flour sticks if dry, more if frozen). This helps keep them suspended in the batter.","images":[],"step":3},{"description":"Whisk Dry ingredients in a bowl.","images":[],"step":4},{"title":"Add Wet ingredinets","description":"Make a well in the Dry ingredients. Add Wet ingredients. Whisk until incorporated.","images":[],"step":5},{"title":"Fold in blueberries","description":"Fold in blueberries, including any flour remaining in the blueberry bowl.","images":[],"step":6},{"title":"Bake","description":"Pour into the prepared tin. Bake for 50 minutes, then cover with foil. Bake for a further 15 - 25 minutes, or until a skewer comes out clean. Check after 15 minutes, then if the skewer comes out with batter on it, bake a further 10 minutes.","duration":50,"images":[],"step":7},{"title":"Cool","description":"Rest for 5 minutes then turn onto a cooling rack and completely cool. Drizzle with Glaze. Wait until the glaze sets (about 20 minutes) before slicing to serve.","duration":5,"images":[],"step":8},{"description":"Whisk icing sugar and lemon until smooth, using milk only if needed to achieve the right thickness (Note 3). Pour or spread over cake set on a rack over a baking tray. Scrape glaze drippings on the tray back onto the cake.","images":[],"step":9}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Baking"],"categories":["baking-recipes","blueberries","dessert-recipes","easter-brunch-recipes","most-popular","quick-and-easy","quick-bread"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d52a7426489b', 'en', 'US', 'Flan Pâtissier (French Custard Tart)', 'Recipe video above. Also known as Parisian Flan, this traditional French custard tart is the most magnificent custard tart in the world (in my humble opinion!). It''s like a giant Portuguese Tart - but better, because there''s so much more custard!The custard is truly incredible - rich, creamy, but not overly sweet. Sets perfectly to cut neat slices but melts in your mouth.DO NOT BE DAUNTED by the lengthy looking instructions. At its core, it is just a puff pastry crust filled with custard. Details are provided to ensure there''s enough information even for less confident bakers.(And PS, it''s SUPPOSED to look rustic!)At its best in the 24 hours after 12 hours refrigeration after finished custard comes out of oven (crispiest base). Keeps 4 - 5 days but pastry starts to lose crispiness (it''s still AWESOME though!).My typical workflow: Make custard and line pan with pastry in evening. Bake in morning, fridge all day, serve that evening. Or bake in early evening, fridge overnight, serve the next day.', 'https://www.recipetineats.com/tachyon/2021/10/Flan-Patissier_79.jpg', 20, 85, 105, 4, '[{"id": "ing_milk", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_vanilla_bean", "quantity": {"value": 2.0, "unit": "jar"}}, {"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 10.0, "unit": "carton of 12"}}, {"id": "ing_egg", "quantity": {"value": 10.0, "unit": "carton of 12"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.263, "unit": "pack of 400g"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 10.0, "unit": "carton of 12"}}]', '[{"ingredients":["1 litre / 1 quart milk (, full fat)","2 vanilla beans (, seeds scraped, beans reserved (Note 1))","1 cup caster sugar (, separated)","120g / 4.2 oz egg yolks (~6 to 7 large eggs, 100 ml, Note 2)","1 large egg (55 - 60g / 2 oz)","7 tbsp (70g) cornflour/cornstarch (scoop and level, Note 3)","50g (5 tbsp) unsalted butter (, cut into 1cm cubes (cold))"],"purpose":"Creme Patissiere:"},{"ingredients":["2 sheets butter puff pastry, FROZEN (25cm / 10\" squares, 185g/6oz each) (Note 4)","1 egg yolk (, whisked)","Butter (, for greasing)"],"purpose":"Pastry:"}]', '[{"description":"Creme Patissiere:","images":[],"step":1},{"title":"Infuse milk","description":"Place milk, vanilla seeds, used beans and 50g (1/4 cup) sugar in a large saucepan over medium high heat. Bring to just before boiling, stirring to dissolve the sugar. Remove from heat, place lid on and leave to steep for 10 minutes.","duration":10,"images":[],"step":2},{"title":"Yolk mixture","description":"Meanwhile, place egg yolks, egg and remaining sugar in a large bowl and whisk to combine. Add cornflour and whisk until smooth.","images":[],"step":3},{"title":"Temper eggs","description":"While whisking the eggs, slowly pour in about half the milk in a thin stream. Whisk until combined.","images":[],"step":4},{"title":"Thicken custard","description":"Pour the egg-milk mixture back into the saucepan then whisk to combine. Place over medium low heat, stirring constantly so the base doesn''t catch, until it starts to thicken (you will feel it). It should happen within 3 to 5 minutes. If it gets lumpy, remove off heat, whisk vigorously - will become smooth.","images":[],"step":5},{"title":"Stir 20 seconds after bubbles appear","description":"When the custard is thickened and hot and you see the first big lazy bubbles appear on the base, whisk constantly on the stove for a further 20 seconds then remove from stove. (To check for bubbles, pause stirring for a few seconds)","images":[],"step":6},{"title":"Butter","description":"Whisk butter in until fully incorporated.","images":[],"step":7},{"title":"Strain & cool","description":"Immediately strain into a bowl through a fine mesh strainer. Discard vanilla bean. Cover with cling wrap touching the surface. Cool on counter (3 hrs+) then refrigerate 12 - 24 hours. (Note 5)","images":[],"step":8},{"title":"Work with pastry as frozen as possible","description":"it''s easier. (Note 4)","images":[],"step":9},{"title":"Cut base and sides","description":"Cut base out using the inside of the pan as a guide on one sheet of puff pastry. Cut three 25 x 5.5cm (2.15 x 10″) wide strips on the other sheet of puff pastry. Place base and sides back in freezer. RESERVE offcuts (for emergency patching).","images":[],"step":10},{"title":"Line pan","description":"Butter and line the sides of a 20cm/8\" springform pan with a 5.5cm / 2.2\" strip of baking paper. We are not using the pan base. (Note 6)","images":[],"step":11},{"title":"Line sides","description":"Place cake pan on a square sheet of baking paper on a plate. (Note 6) Remove cut puff pastry from freezer. Working quickly, when sides have JUST thawed enough to bend, line sides of cake pan with puff pastry, overlapping by 1cm / 0.4\", using water to seal - just press down for now (will seal properly later).","images":[],"step":12},{"title":"Base","description":"Brush base of sides with water. Fit base into cake pan (see video at 2 min 50 sec for technique).","images":[],"step":13},{"title":"Seal pastry","description":"Use the back of a teaspoon to press base into the corner. Then smear the now-thawing puff pastry to full seal.","images":[],"step":14},{"title":"Prick base","description":"Prick base 30 times with fork. (I always forget!!)","images":[],"step":15},{"title":"Freeze: Cover with cling wrap, freeze 4","description":"24 hours. (Note 4)","images":[],"step":16},{"description":"Preheat oven to 220°C/430°F (200°C fan) for 30 minutes.","duration":30,"images":[],"step":17},{"title":"Line & fill with beads","description":"Pick up crust using paper and place on tray (on the paper). Crumple 2 x 60cm / 2 feet long sheets of baking paper (Note 7) then fit into crust arranged in X. Fill with baking beads 1cm / 0.4\" below rim (Note 8). Press to push paper into corners.","images":[],"step":18},{"title":"Blind bake 25 min + 5 min","description":"Bake 25 minutes, then use overhang paper to remove beads carefully (if sides look like they will cave in, return to oven with beads for 5 min). Bake 5 minutes then cool 10 minutes. (Seal any visible cracks with puff pastry scraps)","duration":5,"images":[],"step":19},{"description":"Assemble Flan Pâtissier:","images":[],"step":20},{"description":"Turn oven down to 200°C/390°F (180°C fan).","images":[],"step":21},{"title":"Fill with custard","description":"Remove Creme Patissiere from fridge. Whisk to loosen, scrape into crust - fill to 1cm/0.4\" below rim. (Leftover custard Note 7) Smooth surface, brush custard surface with egg yolk (use it all).","images":[],"step":22},{"description":"Bake 65 minutes, rotating tray 180° at 45 minutes. It will puff up in the last 15 ninutes like a souffle. Remove from oven - it will still be very wobbly, have faith! It will set when cool!Golden surface - If the top is not golden like pictured, switch on broiler to caramelise surface. Watch carefully - takes minutes!","images":[],"step":23},{"description":"Cool on counter for 4 hours (in pan). Transfer to plate (still in pan), cover loosely with cling wrap, then refrigerate 12+ hours.","images":[],"step":24},{"title":"Serve","description":"Remove from fridge 1 hour prior to serving to bring to room temperature. Cut into slices like cake! The pastry is crispy & flaky. The custard will cut neatly (it will not ooze) but when you bite into it, the custard is beautifully soft and creamy. Traditionally eaten as a hand held bakery treat in France but you can use a plate if you''re feeling civilised!","images":[],"step":25},{"title":"Shelf life","description":"Flan Pâtissier is at its best in the first 24 hours after it is put in the fridge after baking as this is when the pastry is still beautifully crisp. Beyond this the pastry starts to soften which no one has pointed out yet because everyone is besotted by the custard! But I notice. :)","images":[],"step":26}]', '["egg","milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dessert"],"cuisine":["French"],"categories":["baking-recipes","dessert-recipes","easter-baking-desserts","iconic-dishes","sweet-pies"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3e978e9f1efe', 'en', 'US', 'Lemon Cake - with a secret Fluffy Lemon Frosting', 'Recipe video above. This is the Lemon Cake you make when you want to impress. 3 cake layers with a velvety, tender crumb based on my signature Vanilla Cake recipe that readers around the world have fallen in love with. Finished with a magic fluffy not-too-sweet lemon frosting (read more about it here - it also has a huge fan following!). Bonus: this cake stays perfectly fresh for 4 whole days. That''s unheard of!Pressed for time? Make this quick Lemon Cake with Lemon Glaze.', 'https://www.recipetineats.com/tachyon/2021/09/Lemon-Cake-with-Lemon-Frosting_85.jpg', 20, 30, 50, 12, '[{"id": "ing_flour", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 2.5, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 333.333, "unit": "carton of 12"}}, {"id": "ing_sugar", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 115.0, "unit": "block of 250g"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.3, "unit": "bottle of 50ml"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 0.09, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.09, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.09, "unit": "net of 500g"}}, {"id": "ing_flour", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 115.0, "unit": "block of 250g"}}]', '[{"ingredients":["2 cups plain / all purpose flour (cake flour OK too, Note 1)","2 1/2 teaspoons baking powder","1/4 tsp salt","4 large eggs (50 - 55g / 2 oz each), at room temp (Note 3)","1 1/2 cups caster / superfine sugar (granulated/regular ok too, Note 2)","115g / 1/2 cup unsalted butter (, cut into 1.5cm / 1/2” cubes (or so))","1 cup milk (, full fat (Note 5))","3 tsp vanilla extract (, the best you can afford (Note 6))","3 tsp vegetable or canola oil (Note 7)","3 tbsp lemon zest (from 2 lemons)","1/3 cup lemon juice","1/4 tsp natural lemon extract (lemon oil) (, recommended but not essential (Note 8))"],"purpose":"Lemon Cake"},{"ingredients":["6 1/2 tbsp flour, plain/all purpose","1 1/3 cups milk (full fat best, low fat ok, 0% fat no good)","1 1/3 cups caster / superfine white sugar (or granulated/ordinary)","300g / 1 1/3 cups unsalted butter (, softened)","3 tsp lemon zest (from 1 lemon)","4 tbsp fresh lemon juice"],"purpose":"My secret Less-Sweet Lemon Frosting:"}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan) for 20 minutes before starting the batter (Note 9). Place shelf in the middle of the oven.","duration":20,"images":[],"step":1},{"title":"Cake pans","description":"Grease 3 x 20cm / 8” cake pans with butter, then line with parchment / baking paper. (Note 10 more pan sizes) Best to use cake pan without loose base, if you can.","images":[],"step":2},{"description":"Combine Dry Ingredients","images":[],"step":3},{"description":"Whisk flour, baking powder and salt in a large bowl. Set aside.","images":[],"step":4},{"description":"Beat eggs until aerated:","images":[],"step":5},{"description":"Beat eggs for 30 seconds on speed 6 of a Stand Mixer fitted with a whisk attachment, or hand beater.","duration":0.5,"images":[],"step":6},{"description":"With the beater still going, pour the sugar in over 45 seconds.","images":[],"step":7},{"description":"Then beat for 7 minutes on speed 8, or until tripled in volume and white.","duration":7,"images":[],"step":8},{"description":"Finish cake batter:","images":[],"step":9},{"title":"Heat Milk-Butter","description":"While egg is beating, place butter and milk in a heatproof jug and microwave 2 minutes on high to melt butter (or use stove). Do not let milk bubble and boil (foam is ok). If you do this ahead, cover and keep hot while beating eggs.","images":[],"step":10},{"title":"Gently add flour","description":"When the egg is whipped, scatter 1/3 flour across surface, then beat on Speed 1 for 5 seconds. Add half remaining flour, then mix on Speed 1 for 5 sec. Add remaining flour, then mix on Speed 1 for 5 - 10 sec until the flour is just mixed in. Once you can’t see flour, stop straight away.","duration":0.08333333333333333,"images":[],"step":11},{"title":"Lighten hot milk with some Egg Batter","description":"Pour hot milk, vanilla, lemon juice and zest and oil into the now empty flour bowl. Add about 1 1/2 cups (2 ladles or so) of the Egg Batter into the Milk-Butter (don''t need to be 100% accurate with amount). Use a whisk to mix until smooth - you can be vigorous here. Will look foamy.","images":[],"step":12},{"title":"Slowly add milk","description":"Turn beater back on Speed 1 then pour the Milk mixture into the Egg Batter over 15 seconds, then turn beater off.","images":[],"step":13},{"title":"Scrape and final mix","description":"Scrape down sides and base of bowl. Beat on Speed 1 for 10 seconds - batter should now be smooth and pourable.","duration":0.16666666666666666,"images":[],"step":14},{"description":"Pour batter into pans.","images":[],"step":15},{"title":"Knock out bubbles","description":"Bang each cake pan on the counter 3 times to knock out big bubbles (Note 10 for why)","images":[],"step":16},{"description":"Bake 23 minutes or until golden and toothpick inserted into centre comes out clean.","images":[],"step":17},{"description":"Remove from oven. Cool in cake pans for 15 minutes, then gently turn out onto cooling racks. If using as layer cakes, cool upside down - slight dome will flatten perfectly. Level cake = neat layers.","duration":15,"images":[],"step":18},{"description":"Frost with provided Lemon Frosting, or Lemon Cream Cheese Frosting from this Lemon Blueberry Layer Cake recipe.","images":[],"step":19},{"description":"Secret Less-Sweet Fluffy Lemon Frosting:","images":[],"step":20},{"title":"Thickening roux","description":"Place flour and sugar in a large saucepan over medium heat. Cook, stirring constantly, for 30 seconds.","duration":0.5,"images":[],"step":21},{"title":"Add milk","description":"While whisking constantly, slowly pour the milk in (this ensure it''s lump free). As the milk gets hotter, it will start to thicken - stir constantly so the base doesn''t catch.","images":[],"step":22},{"title":"Thicken roux","description":"Cook until the mixture thickens in a thick, dolloping custard - see video for texture. (Note 13 tip)","images":[],"step":23},{"title":"Cool","description":"Remove from heat and scrape into a bowl. Cover with cling wrap, pressing down onto the surface to prevent a skin from forming. Cool completely (20 min counter then 30 min fridge), but do not let it get fridge cold. (Note 14) It will firm into a very thick paste.","images":[],"step":24},{"title":"FROSTING","description":"cream butter: Beat butter with either a handheld beater or stand mixer (with whisk attachment) for 3 minutes until it''s smooth and changes from yellow to very pale yellow, almost white.","duration":3,"images":[],"step":25},{"title":"FROSTING","description":"add roux: While beating on speed 5, add the roux one heaped tablespoon at a time. Take about 1 minute to add it all. Once all added, add lemon zest and juice, then whip for 2 minutes until you can see that it is stiff enough to hold peaks liek whipped cream. Do not whip more than 4 to 5 minutes (this will activate starch and make it sticky).","duration":2,"images":[],"step":26},{"description":"Flip a cake layer upside down (for level surface). Spread with 3 - 4mm / 0.12 - 0.16\" frosting. Top with another upside cake layer, spread with ore frosting. Cover with final cake layer then use remaining frosting to cover top and sides.","images":[],"step":27}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_17f4137c8a54', 'en', 'US', 'Chocolate Muffins', 'Recipe video above. Chocolate muffins that truly taste of chocolate and stay fresh for days are a rarity! This recipe delivers, thanks to some tidy tricks including hot milk to bloom the cocoa, and a little coffee to enhance the chocolate flavour (you won''t taste the coffee). Using brown sugar, oil, sour cream and less egg meanwhile is the secret to keeping the crumb ultra-moist and tender!', 'https://www.recipetineats.com/tachyon/2021/08/Chocolate-Muffins_14.jpg', 15, 25, 40, 12, '[{"id": "ing_flour", "quantity": {"value": 0.263, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.031, "unit": "tub of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_cocoa_powder", "quantity": {"value": 0.3, "unit": "pack of 250g"}}, {"id": "ing_instant_coffee_granules_powder", "quantity": {"value": 15.0, "unit": "jar"}}, {"id": "ing_milk", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.45, "unit": "tub of 250g"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_chocolate", "quantity": {"value": 1.5, "unit": "block of 100g"}}]', '[{"ingredients":["1 3/4 cups plain flour (all-purpose flour) (Note 1)","1 1/4 tsp baking soda / bi-carb (Note 2)","1/2 tsp salt","1/2 cup Dutch process cocoa powder (, sifted (Note 3))","1 tbsp instant coffee granules / powder (, optional (Note 4))","3/4 cup milk (, full fat, HOT)","1/2 cup canola oil (or veg or other neutral flavoured oil)","1 cup brown sugar (, packed (Note 5))","1 tsp vanilla extract","3/4 cup sour cream (or thick plain yogurt (fridge-cold fine, Note 6))","1 large egg (55-60g / 2oz) (fridge-cold fine, Note 6)","1 1/2 cups dark chocolate chips (US: semi-sweet chips)"]}]', '[{"description":"Preheat oven to 210°C / 410°F (190°C fan). Place shelf in the top 1/3 of the oven. Line a 12-hole standard muffin tin with paper cases.","images":[],"step":1},{"title":"Sift Dry ingredients","description":"Sift flour, baking soda and salt into a large bowl.","images":[],"step":2},{"title":"Bloom cocoa","description":"In a separate bowl, sift the cocoa then add coffee and HOT milk. Whisk until lump-free.","images":[],"step":3},{"title":"Add remaining Wet ingredients","description":"To the cocoa mixture, add sugar, oil, egg, sour cream and vanilla. Whisk until smooth.","images":[],"step":4},{"title":"Mix flour in","description":"Pour Wet mix into the bowl holding the flour. Whisk until smooth and glossy. Stop once it''s smooth, don''t mix excessively. (Note 7)","images":[],"step":5},{"title":"Add chocolate chips","description":"Stir in most of the chocolate chips - reserve approx 1/4 cup for topping.","images":[],"step":6},{"title":"Fill muffin tin","description":"Divide the batter between the 12 holes, up to 0.5cm / 0.2\" from rim of paper liner. (Note 8)","images":[],"step":7},{"title":"Top with chocolate chips","description":"Top muffins with reserved chocolate chips (just pile in middle, they spread when baked).","images":[],"step":8},{"title":"Bake at high temp, 5 minutes","description":"Bake for 5 minutes in preheated oven. The higher temp kick will start the rise.","duration":5,"images":[],"step":9},{"title":"Lower oven, 20 minutes","description":"Turn oven DOWN to 190°C / 375°F (170°C fan). Bake a further 20 minutes, checking at 15 minutes. When toothpick comes out clean they''re ready. Don''t confuse melted chocolate with raw batter!","images":[],"step":10},{"description":"EAT! Rest in muffin tin for a few minutes, then transfer to cooling rack. Allow to cool for 15 minutes before devouring!","duration":15,"images":[],"step":11}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","cupcakes-and-muffins","dessert-recipes","muffin-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c04df59b88d5', 'en', 'US', 'Red Velvet Cupcakes with Cream Cheese Frosting', 'Recipe video above. What''s so special about Red Velvet Cupcakes, anyway? It''s the crumb. True to its name, it''s "velvety" and soft, with a hint of vanilla and chocolate flavour, not to mention the striking vibrant red colour! Frosted with fluffy cream cheese frosting, this is a cupcake that likes to steal the lime light. And we happily let it!Adapted from my Red Velvet Cake recipe, a long standing reader favourite!', 'https://www.recipetineats.com/tachyon/2021/08/Red-Velvet-Cupcakes_58-SQ.jpg', 30, 20, 50, 12, '[{"id": "ing_flour", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_cocoa_powder", "quantity": {"value": 0.06, "unit": "pack of 250g"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.05, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.003, "unit": "L"}}, {"id": "ing_red_food_colouring", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_cream_cheese", "quantity": {"value": 170.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.1, "unit": "kg"}}]', '[{"ingredients":["1 1/3 cups cake flour (sub plain / all purpose flour, Note 1)","1 tbsp cocoa powder (, unsweetened (Note 2))","1 1/2 tsp baking powder (not baking soda, Note 3)","Pinch of salt"],"purpose":"Dry Ingredients:"},{"ingredients":["60g / 4 tbsp unsalted butter (, softened (Note 4))","2/3 cup caster sugar (superfine sugar)","2 large eggs (, at room temperature (Note 5))","1/3 cup vegetable oil (or canola)","1/2 cup buttermilk (, at room temperature (Note 6))","1 tsp vanilla extract","1/2 tsp white vinegar (Note 7)","1 tbsp red food colouring (yes, 1 whole tablespoon!)"],"purpose":"Wet Ingredients:"},{"ingredients":["1/3 cup unsalted butter (, softened (Note 4))","170g / 6oz Philadelphia block cream cheese (, softened (Note 8))","1/2 tsp vanilla extract","1/8 tsp salt","2 1/2 cups soft icing sugar mixture (powdered sugar) (, sifted (Note 9))"],"purpose":"Cream Cheese Frosting:"}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan). Line a standard 12 hole muffin tin with cupcake liners.","images":[],"step":1},{"description":"Sift Dry ingredients together into a bowl.","images":[],"step":2},{"title":"Cream butter","description":"Put the butter in a separate bowl and beat on speed 2 for 1 minute with an electric mixer or stand mixer (paddle attachment).","duration":1,"images":[],"step":3},{"title":"Cream sugar","description":"Add sugar then beat for a further 2 minutes, same speed, until the butter is very pale yellow, almost white.","images":[],"step":4},{"title":"Beat in eggs","description":"Add the eggs one at a time beating for 30 seconds on speed 1 after each addition.","duration":0.5,"images":[],"step":5},{"title":"Add remaining Wet ingredients","description":"Add oil, buttermilk, vanilla and red food colouring then beat on Speed 1 until incorporated and the batter is smooth.","images":[],"step":6},{"title":"Beat in flour","description":"Sprinkle the Dry ingredients across the surface and mix on Speed 1 for just 20 seconds. Scrape down sides of the bowl, then mix again for 10 seconds. The batter should now be smooth - few small lumps is ok. Do not keep beating - overworks batter = cupcakes not as soft!","duration":0.16666666666666666,"images":[],"step":7},{"title":"Fill pan","description":"Divide the batter between the 12 cupcake liners - it should fill 3/4 of the way, but it depends on the size of the cupcake liners you use.","images":[],"step":8},{"description":"Bake for 20 minutes or until a skewer inserted into the centre of the middle cupcake comes out clean.","duration":20,"images":[],"step":9},{"title":"Cool","description":"Immediately remove cupcakes onto a wire rack. Cool completely before frosting with cream cheese frosting.","images":[],"step":10},{"title":"Cream butter","description":"Place butter in a bowl and beat for 1 minute until it''s smooth and starts to become paler in colour - speed 6 on stand mixer, speed 9 for electric beater.","duration":1,"images":[],"step":11},{"title":"Cream cream cheese","description":"Add cream cheese then beat for a further 1 minute on the same speed until smooth.","images":[],"step":12},{"title":"Add icing sugar","description":"Add icing sugar in 4 batches, beating in between until incorporated, starting on speed 1 so you don''t get a dust storm in your face!","images":[],"step":13},{"title":"Beat until fluffy","description":"Add vanilla and salt, then beat for 2 minutes until fluffy - speed 6 with stand mixer, speed 9 with electric beater. It should be creamy but still hold its shape in a peak (see video). If it''s too sloppy, place in fridge for 30 minutes, then beat again.","duration":2,"images":[],"step":14},{"title":"Pipe","description":"Transfer into piping bag with desired piping tip. Pipe onto cupcakes - makes enough to generously frost 12 cupcakes as pictured in post.","images":[],"step":15}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","cupcakes-and-muffins","dessert-recipes","easter-baking-desserts"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_56be8695649e', 'en', 'US', 'Peach Cobbler', 'Recipe video above. The ONLY pudding I make on warm summer days!There''s peach cobblers with batter toppings, and the ones with the Amercian biscuit / Aussie scone type toppings. I way prefer the latter. Crumbly on the outside, fluffy and moist on the inside, wafting with the smell of cinnamon, covering juicy, warm peaches coated in syrup.You''ll love how the syrup in this peach cobbler is made using the juices of the peach, rather than just a plain sugar syrup. Peach flavour to the max!Serving with ice cream is not optional. (Well, ok, cream will do if that''s all you''ve got!)', 'https://www.recipetineats.com/tachyon/2021/07/Peach-Cobbler_76.jpg', 20, 30, 50, 5, '[{"id": "ing_peaches", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.013, "unit": "pack of 400g"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.033, "unit": "tub of 150g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.013, "unit": "tub of 200g"}}, {"id": "ing_butter", "quantity": {"value": 85.0, "unit": "block of 250g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.15, "unit": "tub of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}]', '[{"ingredients":["1.5kg / 3lb (8) yellow peaches (ripe and juicy!), peeled, stone removed, cut into eight wedges (Note 1)","1/4 cup caster / superfine sugar","1 tsp cornflour / cornstarch","1 tbsp lemon juice (plus more as desired)","1/8 tsp salt"]},{"ingredients":["1 1/4 cups flour (, plain/all purpose)","1/3 cup caster / superfine sugar","1 tsp baking powder","1/2 tsp baking soda (bi-carb) (or extra 1 1/2 tsp baking powder)","1/4 tsp salt","85g / 6 tbsp unsalted butter","1/2 cup plain yoghurt ((or sour cream), full fat)"],"purpose":"Cobbler topping:"},{"ingredients":["1 tsp demerara sugar (Note 3)","1/2 tsp cinnamon powder"],"purpose":"Topping:"},{"ingredients":["Ice cream (or whipped cream)"],"purpose":"Serving:"}]', '[{"title":"Macerate peaches","description":"Put peaches and sugar in a large bowl and toss together. Leave for 40 minutes to macerate, to let the peaches leach juice and sweat.","duration":40,"images":[],"step":1},{"title":"Preheat oven","description":"Partway through the maceration, preheat oven to 210°C/410°F (200°C fan).","images":[],"step":2},{"title":"Drain peaches","description":"Drain in a colander, saving the juices.","images":[],"step":3},{"title":"Syrup","description":"Measure out 1/4 cup (65ml) juice and put in a large bowl. Add cornflour, salt and 1 tbsp of the lemon juice to the peach juice. Mix well.","images":[],"step":4},{"title":"Mix with peaches","description":"Pour peaches into the syrup, toss to coat. Taste - it should be a bit tart, slightly sweet, but not overly sweet. Add more lemon or sugar to adjust to your taste (fresh peaches always vary in sweetness!).","images":[],"step":5},{"title":"Parbake peaches","description":"Pour the peaches and juice into a medium glass or ceramic baking pan. Mine is a 28 x 18cm / 11 x 7\" oval dish (Note 2). Bake 12 minutes, then remove.","images":[],"step":6},{"description":"Cobbler topping:","images":[],"step":7},{"title":"Rub in butter","description":"Meanwhile, whisk together flour, sugar, baking powder, baking soda, and salt to combine. Add butter and rub it in with your fingers until it resembles breadcrumbs (Alternatively, food processor via 10 x 1-sec pulses).","images":[],"step":8},{"title":"Gently fold through yogurt","description":"Add yogurt and gently mix through with rubber spatula until a dough is formed. Stop mixing when yogurt is mostly mixed through with some streaks of flour still visible (they will disappear when topping).","images":[],"step":9},{"title":"Top peaches","description":"Crumble lumps of the topping across the surface. Don''t fully cover the surface, to let some heat through else the syrup won''t reduce and thicken.","images":[],"step":10},{"description":"Sprinkle with demerara sugar and cinnamon.","images":[],"step":11},{"description":"Bake for 20 minutes, then remove from oven. The cobbler is done when an instant read thermometer measures the centre of the biscuit topping as 95°C/203°F and the top is a lovely golden.","duration":20,"images":[],"step":12},{"title":"Rest to thicken sauce","description":"Rest for 20 minutes to allow syrup to thicken - it will still be perfectly warm for serving.","duration":20,"images":[],"step":13},{"description":"Serve with a dollop of ice cream or whipped cream!","images":[],"step":14}]', '["gluten","milk"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":["American","Southern"],"categories":["baking-recipes","dessert-recipes","peach-recipes","puddings-cosy-desserts","sunday-supper"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d40ff2e9c48c', 'en', 'US', 'Madeleines', 'Recipe video above. Madeleines are sweet little French sponge cakes that are as delightful to look at as they are to eat. A recipe taught to me by our resident French Chef JB, these adorable mini butter cakes with their signature shell shape are flavoured with a hint of lemon and make for a lovely afternoon tea, or a pretty finish for any meal. Best served hot and fresh out of the oven. Keep the batter in a piping bag (even overnight - or freezer for weeks!), then 10 minutes in the oven is all it takes!', 'https://www.recipetineats.com/tachyon/2021/07/Madeleines_04.jpg', 15, 10, 25, 24, '[{"id": "ing_flour", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.042, "unit": "tub of 150g"}}, {"id": "ing_egg", "quantity": {"value": 250.0, "unit": "carton of 12"}}, {"id": "ing_sugar", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_milk", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_honey", "quantity": {"value": 0.02, "unit": "jar of 500g"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.2, "unit": "bottle of 50ml"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_butter", "quantity": {"value": 135.0, "unit": "block of 250g"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_sugar", "quantity": {"value": 0.1, "unit": "kg"}}]', '[{"ingredients":["3/4 cup + 1 tbsp plain flour (all purpose flour)","1 1/4 tsp baking powder","3 large eggs (, at room temperature (Note 1))","2/3 cup caster sugar (superfine sugar) (ordinary / granulated sugar ok too)","1 tsp salt","1 tbsp vegetable oil (or other neutral oil)","3 tbsp milk (, full fat (low fat ok too))","2 tsp honey (or maple syrup)","2 tsp vanilla extract","2 tsp lemon zest","135g / 9.5 tbsp unsalted butter (, melted, warm (not hot))","Canola oil spray (or other neutral oil)","Icing sugar / powdered sugar (optional, for dusting)"]}]', '[{"title":"Sift flour","description":"Sift the flour and baking powder into a bowl.","images":[],"step":1},{"title":"Whisk eggs and sugar","description":"Whisk the eggs and sugar vigorously for 2 minutes until it becomes paler in colour and it''s foamy (or 1 minute on speed 6 with handheld beater).","duration":2,"images":[],"step":2},{"title":"Mix flour in 3 parts","description":"Add the flour mixture in 3 parts, whisking gently in between until combined.","images":[],"step":3},{"title":"Add everything else except butter","description":"Add salt, oil, milk, honey, vanilla and lemon. Mix until combined.","images":[],"step":4},{"title":"Add butter","description":"Add butter, mix gently with a rubber spatula until combined. The batter is fairly thin but should leave a faint ribbon briefly on the surface (see video).","images":[],"step":5},{"title":"Cover and refrigerate","description":"Cover with plastic wrap touching the surface and leave it in the fridge overnight (minimum 6 hours).","images":[],"step":6},{"description":"Baking (next day):","images":[],"step":7},{"description":"Preheat oven to 200°C / 390°F (180°C fan) for at least 30 minutes.","images":[],"step":8},{"title":"Piping bags","description":"Pour the madeleine batter into 2 piping bags (or 1 large) either fitted with a round tip nozzle around 0.7 - 1.2cm (0.3 - 0.5\") wide, or snip the end off. (You can refrigerate until required at this stage, or freeze 2 months).","images":[],"step":9},{"title":"Spray and fill pan","description":"Spray the madeleine pan with oil. Fill each hole almost to the top (2just 1m from the rim).","images":[],"step":10},{"title":"Bake","description":"Bake for 10 minutes until light golden.","duration":10,"images":[],"step":11},{"description":"Serve warm! Unmold straight away. Pile onto serving platter. Dust with icing sugar and serve immediately, while hot!","images":[],"step":12}]', '["egg","gluten","milk"]', '["keto_friendly","low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["French"],"categories":["baking-recipes","cupcakes-and-muffins","dessert-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_76928295eb53', 'en', 'US', 'Oatmeal Raisin Cookie (Soft & Chewy)', 'Recipe video above. If you love your oatmeal cookies soft and chewy, this is THE Oatmeal Raisin Cookie recipe for you! Crispy on the edges, buttery with the faintest waft of cinnamon and studded with plump juicy raisins, these keep really well and smell heavenly when they''re in the oven.This is a Cook''s Illustrated recipe and they found the key to achieving this are: a) the size (these are larger than usual) and b) using baking powder, not baking soda.', 'https://www.recipetineats.com/tachyon/2016/07/Oatmeal-Raisin-Cookies_3.jpg', 20, 25, 45, 16, '[{"id": "ing_raisins", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_flour", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.017, "unit": "tub of 150g"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_butter", "quantity": {"value": 250.0, "unit": "block of 250g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_rolled_oats", "quantity": {"value": 0.9, "unit": "pack of 500g"}}]', '[{"ingredients":["1 1/2 cups raisins (Note 1)","1 1/2 cups flour (all purpose / plain)","1/2 tsp salt","1/2 tsp baking powder","1 tsp cinnamon powder","250g / 8 oz (2 sticks) unsalted butter (, at room temperature (Note 2))","1 cup brown sugar (packed)","1 cup white sugar (granulated. Superfine/caster also ok)","2 large eggs (, at room temperature (Note 3))","3 cups rolled oats (Note 4)"]}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan). Adjust oven racks to middle and low position, ensuring you have 4\"/10cm between each rack. Line 2 trays with parchment/baking paper.","images":[],"step":1},{"title":"Optional","description":"Soak raisins in boiled water for 10 minutes. Drain then pat dry. (This makes them plumper).","duration":10,"images":[],"step":2},{"title":"Sift dry ingredients","description":"Sift flour, salt, baking powder and cinnamon into a bowl.","images":[],"step":3},{"title":"Cream butter and sugar","description":"Using a stand mixer or electric mixer, beat butter until creamy. Then beat in sugar until fluffy - about 2 - 3 minutes.","images":[],"step":4},{"title":"Add eggs","description":"Beat in eggs one at a time until incorporated.","images":[],"step":5},{"title":"Mix in flour","description":"Use a wooden spoon to stir the flour mixture in.","images":[],"step":6},{"title":"Stir in oats and raisins","description":"Stir in oats and raisins - this requires a bit of effort as the dough gets firm!","images":[],"step":7},{"title":"Roll and flatten balls","description":"Form 4cm / 1.6\" balls (~18) and place onto baking trays 4\"/10cm apart. I use an ice cream scoop. Then press down to slighty flatten into a thick disc shape.","images":[],"step":8},{"description":"Bake for 11 minutes. Then swap the trays between the shelves AND turn the trays around. Bake for a further 11 - 14 minutes, or until cookies are golden on the edges and LIGHT golden on the surface.","duration":11,"images":[],"step":9},{"description":"Cool on the trays for 5 minutes before transferring to cooling rack. Cool for 30 minutes before serving.","duration":5,"images":[],"step":10}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","cookies","dessert-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d8b967bf45d9', 'en', 'US', 'The Best Pound Cake', 'Recipe video above. Pound Cake is a classic, very buttery vanilla cake commonly made in loaf form. The crumb is quite dense compared to typical cakes, but when made well, it should be moist, soft and melt-in-your mouth, as this one is!This Pound Cake recipe is based on one called "The Perfect Pound Cake" from "The Cake Bible" by Rose Levy Beranbaum. She tested it over 40 times and we’ve tried it many ways as well, but couldn''t improve on it. So I’ve taken the liberty of changing the name here to the BEST Pound Cake. :-)Please make sure the milk, butter and eggs are at room temperature, as directed in the recipe. This is especially important for Pound Cake.', 'https://www.recipetineats.com/tachyon/2021/06/Pound-Cake_6.jpg', 20, 50, 100, 10, '[{"id": "ing_milk", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 250.0, "unit": "carton of 12"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.15, "unit": "bottle of 50ml"}}, {"id": "ing_flour", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.025, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 13.0, "unit": "block of 250g"}}]', '[{"ingredients":["3 tbsp milk (, full fat, at room temperature)","3 large eggs (, at room temperature (150 - 165g / 6oz total including shell, Note 1))","1 1/2 tsp vanilla extract","1 cup cake flour (, sifted (if using cup measures, measure after sifting, Note 2))","3/4 cup caster sugar (superfine sugar)","3/4 tsp baking powder","1/4 tsp salt","13 tbsp (185 grams) butter, unsalted, softened to 18°C / 64°F; (Note 4)"]}]', '[{"description":"Preheat the oven to 180°C/350°F (165°C fan) with the shelf arranged so the loaf pan will sit in the middle of the oven.","images":[],"step":1},{"title":"Prepare pan","description":"Grease a 21.5 x 11.4 x 6.9cm / 8.5 x 4\" loaf pan with unsalted butter, then dust with flour, knocking out excess (Note 2)","images":[],"step":2},{"title":"Whisk wet","description":"In a medium bowl, lightly whisk together the milk, eggs and vanilla. Set aside.","images":[],"step":3},{"title":"Whisk dry","description":"Place the flour, sugar, baking powder and salt in a large bowl or stand mixer. Beat for 30 seconds on Speed 1 using an electric beater or the stand mixer.","duration":0.5,"images":[],"step":4},{"title":"Add butter and half eggs","description":"Add the softened butter and 1/2 of the egg mixture. Beat on Speed 1 until incorporated (about 30 - 40 secs) – it will become a thick batter. Increase to Speed 7 and continue to beat for 1 minute.","duration":1,"images":[],"step":5},{"title":"Add half of remaining egg mix","description":"Scrape down the bowl. Add half the remaining egg mixture (ie. 1/4 of the original total) and beat 20 seconds on Speed 7.","images":[],"step":6},{"title":"Add remaining egg mix","description":"Scrape down the sides again. Add all the remaining egg mixture (ie. 1/4 of the original total) and beat 20 seconds.","images":[],"step":7},{"title":"Fill pan","description":"Scrape batter into the prepared loaf pan and smooth the top.","images":[],"step":8},{"title":"First bake (30 min)","description":"Bake for 30 minutes until top begins to split slightly.","duration":30,"images":[],"step":9},{"title":"Cut split (optional)","description":"Working quickly, open the oven (do not take pan out) and make a light cut with a small, sharp knife along the split (15 cm / 6\") to help the split to open up nicely. Work fast – do not leave oven open for long or the cake will collapse.","images":[],"step":10},{"title":"Second bake (20 min)","description":"Bake another 20-25 minutes until a skewer inserted in the centre comes out clean. If the cake is getting dark you can cover it with a loose sheet of foil towards the end of the bake time.","images":[],"step":11},{"title":"Cool","description":"Cool in the pan for 10 minutes then turn out onto a wire rack to cool completely.","duration":10,"images":[],"step":12},{"title":"Serving","description":"Serve thick slices with any of the following or a combination – whipped cream and fruit (traditional); just butter; butter + honey (pictured in post); a fruit compote; mascarpone or thick yogurt with crushed nuts (pistachio would be fabulous!). See in post for more ideas.","images":[],"step":13}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","dessert-recipes","quick-bread"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9fdaf73d7fee', 'en', 'US', 'French Lemon Tart - Tarte au Citron', 'Recipe video above. This is an elegant, classic French Lemon Tart recipe that''s totally straightforward to make. The lemon tart filling is my ideal version: smooth and melt-in-your-mouth creamy, and not too sweet or too sour (like so many recipes seem to be??!). It''s set just enough so you can cut neat slices.The tart crust is a French Sweet Tart Crust called Pâte Sucrée. It''s tastier and easier than the usual shortcrust. This is the only tart crust recipe you will ever need!IMPORTANT: Readers have had problems with butter splitting in the lemon curd. This occurs if heat is too strong. Please use low heat, as per recipe directions! :)', 'https://www.recipetineats.com/tachyon/2021/06/French-Lemon-Tart_5-main.jpg', 10, 15, 25, 12, '[{"id": "ing_sweet_tart_crust", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_lemon", "quantity": {"value": 0.15, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.15, "unit": "net of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 12.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}]', '[{"ingredients":["1 sweet tart crust"]},{"ingredients":["1 tbsp lemon zest (1 lemon''s worth)","1/2 cup lemon juice (from 1 - 2 lemons)","3/4 cup white sugar","12 tbsp / 170g unsalted butter (, cut in 1cm (1/2\") cubes)","3 whole eggs (large, (Note 1))","3 egg yolks (from large-size eggs, Note 1)"],"purpose":"Lemon Tart filling:"}]', '[{"description":"Make tart crust per linked recipe, including blind baking the empty tart crust. Allow to fully cool before filling (to ensure it won''t go soggy).","images":[],"step":1},{"description":"Lemon Tart filling:","images":[],"step":2},{"title":"Preheat oven","description":"Preheat oven to 180℃/350℉ (160℃ fan)","images":[],"step":3},{"title":"Whisk ingredients together","description":"Put all ingredients in a medium saucepan and whisk to combine.","images":[],"step":4},{"title":"Thicken on stove","description":"Place the saucepan on the stove over low / medium low heat. Whisk constantly, especially as the butter is melting, to ensure it doesn''t split. Keeping stirring until the mixture thickens enough to visibly mound (ie. holds its shape briefly) on the surface when dolloped – about 5 minutes, though it might take longer depending on stove strength, saucepan heat retention etc. See video and photos for thickness guide. Don''t take it off the stove until it''s thick enough otherwise the Filling won''t set.","images":[],"step":5},{"description":"Strain into a bowl using a fine mesh strainer.","images":[],"step":6},{"title":"Fill tart","description":"Pour into tart shell and smooth the filling surface using an offset spatula or similar.","images":[],"step":7},{"title":"Bake","description":"Bake for 5 minutes. It will still be a soft custard when you touch it but not liquidity. It will set more when cooled so it''s sliceable.","duration":5,"images":[],"step":8},{"title":"Cool","description":"Cool tart fully to allow it to set before slicing to serve. Pictured with a dollop of creme fraiche (a thick, rich cream that has a slight tartness, and goes very well with the lemon tart) or whipped cream and even vanilla ice cream.","images":[],"step":9},{"description":"Decorate if desired with lemon slices, edible flowers, raspberries. Else pipe on dollops of whipped cream or dust with icing sugar!","images":[],"step":10}]', '["egg","milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["French","Western"],"categories":["baking-recipes","sweet-pies"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ed235f0b3b72', 'en', 'US', 'Brioche', 'Recipe video above. Rich and buttery, yet amazingly light and elegant, making delicious, boulangerie (French bakery) quality brioche at home is actually far easier than you''d think! Store bought are pricey and poor imitations of what truly great brioche should be, skimping on butter and using shortcut methods.This is a traditional recipe for French brioche that was created with the assistance of a classically trained French Chef, Jean-Baptiste Alexandre. Meet Chef JB!No stand mixer? See Note 16 for a 5 minute food processor method!Want to bake it later? No problems, refrigerate the dough for a day or two! See Note 17.', 'https://www.recipetineats.com/tachyon/2021/06/Brioche_6.jpg', 45, 35, 510, 10, '[{"id": "ing_yeast", "quantity": {"value": 2.5, "unit": "pack of 5 sachets"}}, {"id": "ing_milk", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.052, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 6.25, "unit": "carton of 12"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 150.0, "unit": "block of 250g"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_egg", "quantity": {"value": 6.25, "unit": "carton of 12"}}]', '[{"ingredients":["2 1/2 tsp instant/rapid rise dried yeast (other yeasts see Note 1)","4 tbsp milk (, warm, full fat (Note 2))","2 cups plain/all purpose flour (not bread flour, Note 3)","3 1/2 tbsp caster/superfine sugar (Note 4)","1/2 cup eggs (2 1/2 eggs) (, lightly whisked, at room temperature (Note 5))","1 tsp salt (cooking/kosher salt, not table salt Note 6)","150g / 10.5 tbsp unsalted butter (, cut into 1.25 / 1/2\" pieces, softened (but not melting, Note 7))"]},{"ingredients":["Oil spray (, anything neutral flavoured (canola, vegetable, not olive oil))","1/2 leftover egg (, lighter whisked (Egg Wash, use leftover egg from above))"],"purpose":"Other:"}]', '[{"title":"Bloom yeast (Note 1)","description":"In a small bowl, mix 1 tsp sugar, yeast and milk together. Cover with cling wrap and set aside in a warm place for 10 minutes until foamy.","duration":10,"images":[],"step":1},{"title":"Dough making methods","description":"Base recipe method uses a Stand Mixer. See Note 5 for faster food processor method.","images":[],"step":2},{"title":"Make dough","description":"In the bowl of a stand mixer fitted with a dough hook, add the flour, eggs, salt, rest of the sugar and the foamy yeast. Mix on Speed 1 until ingredients are combined.","images":[],"step":3},{"title":"Mixing Part 1","description":"After the ingredients are combined, then mix on Speed 1 for 5 minutes then on Speed 2 for 10 minutes, (Yes really, 15 minutes, see Note 8!)","duration":5,"images":[],"step":4},{"title":"Slow add butter","description":"With the stand mixer still on Speed 2, drop butter cubes in gradually, over about 90 seconds to 2 minutes, giving the dough a chance to mix most of the butter in. (Note 9)","images":[],"step":5},{"title":"Incorporate butter","description":"Keep mixing until the butter is fully incorporated- about 1 minute. Dough will be pasty and sticky!","images":[],"step":6},{"title":"Mixing Part 2","description":"Then mix on Speed 2 for 20 minutes, scraping down the sides of the bowl every now and then.","duration":20,"images":[],"step":7},{"title":"Dough goals (Note 8)","description":"At first the mixture it will be very pasty and stuck to the sides of the bowl. By the end, the dough should come together, caught up in the dough hook, and not be stuck on the sides of the bowl. Very soft, but able to pick it up. You should be able to do the \"window pane\" test using a walnut size piece (Note 10). If not, keep kneading! (Note 11 trouble shooting)","images":[],"step":8},{"description":"Rising, Fridge & Shaping:","images":[],"step":9},{"title":"Rise #1 (2 hrs)","description":"Shape the dough into a ball, put it back into the stand mixer bowl. Cover with cling wrap and put it in a warm place for 2 hours until it has doubled in size.","images":[],"step":10},{"title":"Cut into 3","description":"Punch the dough dough to release all the air. Scrape out onto a lightly floured work surface. Fold the outside of the dough in 6 times. Shape into a log then cut into 3 equal portions and shape into a ball (~225g/7.9oz per piece).","images":[],"step":11},{"title":"Fridge (1.5 hrs)","description":"Line a deep container or roasting pan with baking/parchment paper lightly sprayed with oil. Place dough on paper, cover with cling wrap/lid and refrigerate for 1.5 hours (Note 12).","images":[],"step":12},{"title":"Braid","description":"Remove dough from fridge. Place on a lightly floured work surface and roll each piece into a 35cm/14\" logs. Braid the logs, and tuck the ends under to make them tidy.","images":[],"step":13},{"title":"Loaf pan","description":"Spray a 21.5 x11cm (8.5 x 4.3\") loaf pan well coated with oil spray, then place the dough in. Lightly spray cling wrap with oil, then cover the dough.","images":[],"step":14},{"title":"Rise #2 (3 hrs)","description":"Rise in a warm place for 3 hours or until it is just over double in size. (Note 13)","images":[],"step":15},{"title":"Preheat oven","description":"Preheat oven to 200°C/390°F (180°C fan) when dough is almost ready.","images":[],"step":16},{"title":"Shelf position","description":"Position shelf so loaf will sit in the lowest 1/3 of the oven.","images":[],"step":17},{"title":"Egg wash","description":"Brush the brioche surface very gently with whisked egg.","images":[],"step":18},{"title":"Bake uncovered 15 min","description":"Bake brioche for 15 minutes, uncovered, until a beautiful deep golden.","duration":15,"images":[],"step":19},{"title":"Bake covered 20 min","description":"Remove from oven. Loosely cover with foil. Bake for a further 20 minutes or until the internal temperature is 88°C/190°F. (Note 14)","images":[],"step":20},{"title":"Turn out and cool","description":"Immediately turn brioche out onto a rack. Cool for at least 45 minutes before slicing (or tearing!) to serve (still warm).","images":[],"step":21},{"title":"Serving","description":"Best served warm, with butter and lovely jams, the French way! Either slice warm loaf, or toast slices. (Note 16) See in post for more serving ideas - savoury, sweet, breakfast, lunch, dessert!","images":[],"step":22},{"description":"What the finished brioche should be like:","images":[],"step":23},{"description":"The crust will be delicately crusty and flake gently when you slice it. It will be ultra soft inside, much softer than usual breads, with a pale yellow colour from the butter and eggs. Though traditionally sliced to serve, a unique characteristic is that if you tear the bread, it shreds like cotton candy. This is the sign off a well made traditional French brioche that you will not find in run-of-the-mill grocery store cheap brioche! Subtly sweet with a beautiful butter flavour (another thing store bought lacks!).","images":[],"step":24}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["French"],"categories":["baking-recipes","breads","easter-baking-desserts","iconic-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8e9d439c5e40', 'en', 'US', 'Italian Almond Cookies (Ricciarelli) - gluten free!', 'Recipe video above. These lovely little Italian cookies have a beautiful chewy texture and bursting with almond flavour. And because they''re gluten free and dairy free, everyone can enjoy them!The almond sliver coating is something I copied from an Italian bakery in Sydney. It gives the cookie a great textural finish and makes it less fragile. Without it, you need to handle the cookie with care, and to me it feels less like a cookie because the crust is quite soft.These cookies are traditionally studded with dried cherries but other similar dried fruit will work in a pinch eg cranberries, or even raisins.', 'https://www.recipetineats.com/tachyon/2021/05/Italian-Almond-Cookies_6.jpg', 15, 15, 30, 20, '[{"id": "ing_almonds", "quantity": {"value": 1.2, "unit": "pack of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_almonds", "quantity": {"value": 1.2, "unit": "pack of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_cherries", "quantity": {"value": 0.15, "unit": "pack of 500g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_honey", "quantity": {"value": 0.02, "unit": "jar of 500g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_almonds", "quantity": {"value": 1.2, "unit": "pack of 250g"}}]', '[{"ingredients":["2 cups almond meal or blanched ground almonds (Note 1)","1/2 cup caster / superfine sugar (Note 2)","2 tsp lemon zest (1 lemon)","3 drops natural almond extract","1/8 tsp salt","1/2 cup dried cherries (, chopped (Note 3))","2 egg whites (, at room temperature (from 2 large eggs, Note 4))","2 tsp honey"]},{"ingredients":["1 Extra egg white","1 1/2 cups flaked almonds"],"purpose":"Almond Coating (optional, Note 5):"}]', '[{"description":"Preheat oven to 190°C/375°F (170°C fan). Line 2 trays with baking/parchment paper.","images":[],"step":1},{"title":"Combine Dry Ingredients","description":"Place the almond meal, sugar, zest, almond extract and salt in a bowl. Whisk together until zest and almond extract is evenly distributed. Add the cherries and set aside","images":[],"step":2},{"title":"Beat eggs whites","description":"Using an electric mixer or a whisk, beat the egg whites and honey to soft peaks (Note 5). About 2 minutes on Speed 8 of a handheld beater, or 1 1/2 minutes on Speed 6 of a stand mixer.","images":[],"step":3},{"description":"Fold the beaten egg whites gently into the almond mixture. You will seemingly knock most of the air out of the meringue, that''s ok! (You actually haven''t :) ).","images":[],"step":4},{"description":"Forming & Coating Cookies:","images":[],"step":5},{"description":"Place Extra egg white in a small bowl and whisk with a fork until foamy. Place flaked almonds in another bowl.","images":[],"step":6},{"title":"Form 2.5cm/1\" balls","description":"Scoop up about 1 tablespoon of the mixture and shape into a rough ball (2.5cm/1\" ball). I do this using 2 eating spoons - we don''t need perfect balls here.","images":[],"step":7},{"title":"Coat in egg whites","description":"Drop the ball into foamy egg whites. Use 2 forks to turn to coat, then pick up and place in the flaked almonds.","images":[],"step":8},{"title":"Almond coating","description":"Coat cookies with the almonds, pressing them on to cover as completely as you can. Don''t worry if you get some double layers or pieces sticking out - no need to be neat or thorough here!","images":[],"step":9},{"title":"Bake 13 minutes","description":"Place on prepared tray 2.5cm / 1\" apart. Bake for 13-15 minutes until golden brown. Start checking at 12 minutes to be sure the nuts aren’t burning","duration":14,"images":[],"step":10},{"title":"Cool","description":"Transfer to rack to cool completely before serving.","images":[],"step":11},{"title":"Store","description":"Store in an airtight container. They last up to 10 days in a storage container or can be frozen","images":[],"step":12}]', '["egg","nuts"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Italian"],"categories":["baking-recipes","cookies","dessert-recipes","dietary","egg-white-recipes","gluten-free-recipes","italian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_29da8bc2cde2', 'en', 'US', 'Crème Brûlée (French Vanilla Custard)', 'Recipe video above. A classic French Crème Brûlée with a silky smooth rich custard and crunchy caramel top. It''s a stunner – and so easy!', 'https://www.recipetineats.com/tachyon/2016/09/Creme-Brulee_8.jpg', 10, 40, 50, 4, '[{"id": "ing_cream", "quantity": {"value": 2.0, "unit": "carton of 250ml"}}, {"id": "ing_vanilla_pod", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_egg", "quantity": {"value": 5.0, "unit": "carton of 12"}}, {"id": "ing_sugar", "quantity": {"value": 0.037, "unit": "kg"}}]', '[{"ingredients":["2 cups pure cream (Aus) / heavy cream (US) (Note 1)","1 vanilla pod OR 1 tsp vanilla bean paste (Note 2)","5 egg yolks (Note 3 for using leftover whites)","1/4 cup caster sugar (superfine sugar)"]},{"ingredients":["2 tsp caster sugar (superfine sugar)"],"purpose":"Toffee Topping"}]', '[{"title":"Vanilla bean","description":"Split vanilla pod down the middle and scrape the seeds out using a small knife. Place into saucepan with cream and the empty vanilla pod.","images":[],"step":1},{"title":"Infuse cream","description":"Simmer uncovered over low heat for 10 minutes. Remove from stove and set aside to infuse for 1 hour with lid on (you can skip this step if using paste, just let it cool to lukewarm). Remove vanilla pod. Skim off any skin that has formed on the surface.","duration":10,"images":[],"step":2},{"title":"Preparation","description":"Preheat oven to 130°C/265°F (120°C fan). Place 4 x ⅔ cup / 150 ml empty ramekins in a baking pan with high enough sides that enough water can be poured in to come halfway up ramekins.","images":[],"step":3},{"title":"Boil water","description":"Boil a kettle of water.","images":[],"step":4},{"title":"Whisk egg yolks and sugar","description":"Whisk yolks and sugar until just well combined. Don''t whisk too much, as this can create bubbles.","images":[],"step":5},{"title":"Add cream","description":"Pour cream into eggs and gently stir to combine. Divide mixture between ramekins with a soup ladle.","images":[],"step":6},{"title":"Water bath","description":"Pour in enough boiling water so it comes halfway up the sides of the ramekins. (If you have too much water, ramekins will float around - not good!)","images":[],"step":7},{"title":"Bake: Bake for 35","description":"40 minutes, or until the custard is set but there is still a slight wobble when you GENTLY give the ramekin a little shake.","duration":37.5,"images":[],"step":8},{"title":"Chill","description":"Remove ramekins from water. Leave to cool, then refrigerate for at least 6 hours and preferably overnight (up to 3 days is OK).","images":[],"step":9},{"title":"Blow torch method","description":"Sprinkle 1/2 tsp sugar over the surface of each crème brûlée. Use a blow torch to melt and caramelise the sugar. Serve immediately.","images":[],"step":10},{"title":"Grill / broiler method","description":"Crème brûlée should be first refrigerated overnight. Preheat grill to high. Place crème brûlée under grill for 1 minute or until sugar is melted and caramelised. Refrigerate afterwards for at least 20 minutes and up to 1 hour (to reset custard immediately under toffee), then serve.","duration":1,"images":[],"step":11},{"title":"Crème brûlée perfect texture","description":"The texture should be like a very thick yogurt, rather than set so it is sliceable like cake or even like a soft set jelly. When you take a scoop, the custard should barely hold together, but shouldn''t be melting or running. When you take a bite the custard should literally just melt in your mouth.","images":[],"step":12}]', '["egg","milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dessert"],"cuisine":["French"],"categories":["baking-recipes","dessert-recipes","dietary","egg-yolk-recipes","gluten-free-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d2eba9588200', 'en', 'US', 'Pistachio Pear Tart', 'Recipe video above. This delightful Pear Tart is filled with a frangipane cream made with pistachios rather than the usual almonds, which gives it a dazzling green colour and stunning flavour. It''s a perfect Autumn dessert that makes the most of ripe pears when they''re in season. Smart and yet rustically casual, this tart is fitting for any occasion!', 'https://www.recipetineats.com/tachyon/2021/04/Pistacchio-Pear-Tart_2.jpg', 15, 90, 105, 10, '[{"id": "ing_sweet_tart_crust", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_pears", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.05, "unit": "bottle of 50ml"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_pistachios", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_jam", "quantity": {"value": 0.081, "unit": "jar of 370g"}}]', '[{"ingredients":["1 Sweet Tart Crust (Note 1)"]},{"ingredients":["4 pears (of equal size, 220g/7oz each, ~10cm/4\" tall, Note 2)","1 lemon (, to acidulate water and stop pears from going brown (Note 3))","2 litres / 2 quarts water","1 cup white sugar","1/2 tsp vanilla extract (or 1/4 tsp vanilla powder (Note 4))"],"purpose":"Poached Pears:"},{"ingredients":["100g / 7 tbsp unsalted butter (, softened, cut into 1cm / 0.4\" cubes)","1/2 cup caster sugar","2 large eggs (, 55-60g / 2 oz each, at room temperature)","3/4 cup pistachios (unsalted, roasted) (, shelled and skinned (blitz until fine powder))"],"purpose":"Pistachio Cream Filling (Frangipane):"},{"ingredients":["2 1/2 tbsp pistachios (unsalted, roasted) (, finely chopped (for sprinkling))","2 tbsp apricot jam (, mixed with 1 tsp water and warmed in microwave (for glazing))"],"purpose":"Finishing:"}]', '[{"description":"Make and bake Tart Crust, then fully cool before using.","images":[],"step":1},{"description":"Peel, remove stem, then halve and core (I use melon baller). Keep peeled pears in a separate bowl of water with a squeeze of lemon juice (to stop them going brown).","images":[],"step":2},{"description":"Place 2L / 2 quarts water, sugar and vanilla in a pot and bring it to a boil. Lower heat so the water is rippling but there are no large bubbles breaking on surface. Beads of tiny bubbles is fine.","images":[],"step":3},{"title":"Place pears into pot, poach for 20","description":"25 minutes until pears are soft all the way through. Check with a knife on the side, not top of pears. (Note 5).","duration":22.5,"images":[],"step":4},{"description":"Once cooked, drain on paper towels until fully cool.","images":[],"step":5},{"description":"Pistachio filling:","images":[],"step":6},{"description":"Mix butter and sugar with a wooden spoon until smooth.","images":[],"step":7},{"description":"Add eggs one at a time, whisking each until fully incorporated before adding the next.","images":[],"step":8},{"description":"Mix in pistachio until fully incorporated.","images":[],"step":9},{"description":"Constructing tart:","images":[],"step":10},{"description":"Preheat oven to 200°C/390°F (180°C fan).","images":[],"step":11},{"description":"Spread pistachio mixture in tart crust, and smooth the surface.","images":[],"step":12},{"description":"Place 7 pear halves on top in a radial pattern with the narrow ends pointing inwards. Cut the 8th half so it will fit in the centre, and place in middle of tart. Slightly push pears in so that they''re partially submerged (see reference photo / video above).","images":[],"step":13},{"description":"Bake for 35 minutes. Remove from oven.","duration":35,"images":[],"step":14},{"description":"While still warm, brush with apricot jam glaze to make it shiny, then sprinkle with chopped pistachios.","images":[],"step":15},{"description":"Fully cool, then slice to serve. It''s beautiful just served as-is. Optional extras: a dollop of creme fraiche (pictured in post), whipped cream or ice cream.","images":[],"step":16}]', '["egg","milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["French","Western"],"categories":["baking-recipes","dessert-recipes","sweet-pies"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bf4e13836c9f', 'en', 'US', 'Pâte Sucrée - French Sweet Tart Crust (pastry dough)', 'Recipe video above. If I only had room for one Sweet Tart Crust recipe in my life, this would be it. Called Pâte Sucrée in French, it''s an excellent master pastry for all sweet tarts, such as the Pistachio Pear Tart recipe I shared today.Buttery and not too sweet, flaky but not so crumbly that makes it difficult to eat with a fork. Plus, the dough is extremely easy to work with - easier than Shortcrust Pastry.Makes enough pastry for a tart tin up to around 24 x 3 cm / 9.5 x 1.2" big.', 'https://www.recipetineats.com/tachyon/2021/04/French-Sweet-Tart-Crust-Pate-Sucree-_0.jpg', 15, 30, 45, 1, '[{"id": "ing_flour", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.098, "unit": "kg"}}, {"id": "ing_almonds", "quantity": {"value": 0.15, "unit": "pack of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}]', '[{"ingredients":["1 1/2 cups flour (, plain/all purpose)","6 1/2 tbsp soft icing sugar / powdered sugar (, sifted (Note 1))","2 1/2 tbsp almond meal / ground almonds (Note 2)","1/4 tsp salt","100g / 7 tbsp butter (, unsalted, softened, cut into 1cm cubes)","1 large egg (, at room temperature (55-60g/2 oz) (Note 3))"]}]', '[{"title":"Mix Dy Ingredients","description":"Whisk together flour, icing sugar, salt and almond meal in a bowl.","images":[],"step":1},{"title":"Add butter","description":"Use your fingertips to rub the butter into the dry ingredients until it resembles breadcrumbs. (Note 4).","images":[],"step":2},{"title":"Add egg","description":"Mix with a rubber spatula until it becomes too hard to stir anymore, then use your hands to bring it together into a dough.","images":[],"step":3},{"title":"Bring dough together","description":"Turn dough out onto a work surface, then knead to bring together into a smooth ball. Flatten into a 2cm / 0.8\" thick disc. Wrap with cling wrap and refrigerate for 30 minutes.","duration":30,"images":[],"step":4},{"description":"Unwrap chilled dough. Place on a lightly floured work surface.","images":[],"step":5},{"description":"Roll out into a 32cm / 13\" round (3mm / 1/8\" thick).","images":[],"step":6},{"title":"Line tart tin","description":"Roll pastry lightly on to a rolling pin (ie. so it wraps around itself). Then unroll it gently over the tart tin.","images":[],"step":7},{"title":"Fit pastry","description":"Adjust the pastry to fit into the tart tin, fitting into the corner, taking care not to stretch it (causes shrinkage during bake).","images":[],"step":8},{"title":"Trim excess dough","description":"Roll the rolling pin over tart tin to trim excess dough. Pictured tart tin is 24 x 3 cm / 9.5 x 1.2\" - you can use any up to this size.","images":[],"step":9},{"description":"Prick the base of the pastry 30 times with a fork. Not all the way through - just make a light prick on the surface.","images":[],"step":10},{"description":"Chill pastry in tart tin for 30 minutes.","duration":30,"images":[],"step":11},{"description":"Preheat oven to 200°C / 390°F (180°C fan).","images":[],"step":12},{"title":"Baking beads","description":"Cover pastry with 2 sheets of baking paper (parchment paper), in a \"X\" arrangement. Fill with baking beads (or 2 cups dry raw rice or beans).","images":[],"step":13},{"description":"Par Baked Tart Crust:","images":[],"step":14},{"description":"Baking times for a Par Baked Tart to be used for tarts that are baked for > 30 minutes once the filling is added into the cooked tart shell.","images":[],"step":15},{"description":"Bake 15 minutes the remove from oven. Use excess paper to remove baking beads.","images":[],"step":16},{"title":"Bake uncovered 5 minutes","description":"Return tart crust to oven for 5 minutes. Pastry should be light golden, crispy on surface, but slighty undercooked inside (will finish cooking once filled and baked again).","duration":5,"images":[],"step":17},{"description":"Fully Cooked Tart Crust:","images":[],"step":18},{"description":"Use these baking times if the tart shell is to be used for raw fillings (ie tart not baked once crust is filled) OR fillings that are baked for < 25 minutes.","images":[],"step":19},{"description":"Bake 15 minutes the remove from oven. Use excess paper to remove baking beads.","images":[],"step":20},{"title":"Bake uncovered 10 minutes","description":"This will fully cook the pastry through and give it nice colour which we need as the pastry won''t cook through in less than 25 minutes once filled.","images":[],"step":21},{"title":"Cool","description":"Remove then cool in tart tin before filling (this ensures crust stays crispy once filled), then baking again if filling needs to be cooked (like this Pistachio Frangipane Pear Tart).","images":[],"step":22},{"description":"Make ahead up to 3 days, suitable for baking once filled.","images":[],"step":23}]', '["egg","gluten","milk","nuts"]', '["high_protein","vegetarian"]', '{"mealType":["dessert"],"cuisine":["French","Western"],"categories":["baking-recipes","quiches-tart-and-pie-recipes","sweet-pies"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2240613321cd', 'en', 'US', 'Pineapple Upside Down Cake', 'Recipe video above. Bringing back the retro classic! You will love everything about this cake. The sticky, caramelised pineapple and cherry topping. The ultra-tender and moist vanilla cake. How it''s studded with pineapple bits inside. And how we use some of the pineapple juice to flavour the cake. Because why would we waste it??', 'https://www.recipetineats.com/tachyon/2021/03/Pineapple-Upside-Down-Cake-2_8.jpg', 20, 45, 65, 10, '[{"id": "ing_pineapple", "quantity": {"value": 565.0, "unit": "unit"}}, {"id": "ing_cherries", "quantity": {"value": 12.0, "unit": "pack of 500g"}}, {"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.033, "unit": "tub of 150g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.006, "unit": "tub of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_pineapple", "quantity": {"value": 565.0, "unit": "unit"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.15, "unit": "tub of 250g"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_pineapple", "quantity": {"value": 565.0, "unit": "unit"}}]', '[{"ingredients":["565g/ 20 oz canned pineapple slices in juice (not in syrup, Note 1)","12 - 18+ maraschino cherries (Note 2)","60g/ 4 tbsp unsalted butter (, melted)","1/2 cup brown sugar"],"purpose":"Topping:"},{"ingredients":["1 1/2 cups flour","1 tsp baking powder","1/4 tsp baking soda (sub 1 tsp baking powder)","1/4 tsp salt","1/3 cup milk (, full or low-fat)","1/4 cup pineapple juice (, reserved from can (under Topping ingredients))","1/4 cup sour cream (, full fat (sub plain yogurt))","1 tsp vanilla extract (or essence)","115g/ 1 stick butter (, unsalted, softened (to 18C/64F, Note 3))","3/4 cup white sugar","2 large eggs (, at room temperature (Note 4))","Any leftover pineapple (, chopped (Note 1))"],"purpose":"CAKE:"}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan).","images":[],"step":1},{"description":"Pineapple decorative top:","images":[],"step":2},{"title":"Dry fruits","description":"Line a tray with paper towels or a tea towel, then place pineapple and cherries on. Pat dry with paper towels.","images":[],"step":3},{"title":"Butter","description":"Pour melted butter into a 23cm/9\" cake pan at least 5cm/2\" deep. (Not springform, as they''ll leak.) Brush butter up the sides.","images":[],"step":4},{"title":"Brown sugar","description":"Sprinkle sugar over the base, roughly spreading it out (use the brush).","images":[],"step":5},{"title":"Arrange pineapple","description":"Place one pineapple ring in the centre, then surround with either halved pineapple rings (as pictured), or whole ones.","images":[],"step":6},{"description":"Decorate with cherries as desired. Most people just put them in the middle of the pineapple rings.","images":[],"step":7},{"description":"Press cherries and pineapples down firmly so they are in direct contact with the base of the cake pan - so you get vibrant red and yellow colour pops at the end, not tarnished by caramel. (Note 5)","images":[],"step":8},{"title":"Flour Mixture","description":"Whisk flour, baking powder, baking soda and salt in a bowl.","images":[],"step":9},{"title":"Milk Mixture","description":"Whisk milk, sour cream, pineapple juice and vanilla in a 2nd bowl.","images":[],"step":10},{"title":"Cream butter and sugar","description":"In a third (final!) bowl, beat the butter and sugar for 2 minutes on speed 7 (handheld mixer) until fluffy.","duration":2,"images":[],"step":11},{"title":"Eggs","description":"Add eggs one at a time, beating for 20 seconds in between.","duration":0.3333333333333333,"images":[],"step":12},{"title":"Add Flour Mixture then Milk Mixture, alternating","description":"Add 1/3 of the Flour Mixture, then mix in using a rubber spatula. Add 1/2 the Milk Mixture, mix in. Add half the remaining Flour Mixture, mix. Add all the remaining Milk Mixture, mix. Then mix in the last of the Flour Mixture. Stir in the leftover pineapple pieces.","images":[],"step":13},{"title":"Fill pan","description":"Spread batter over pineapple layer, smooth and level the surface.","images":[],"step":14},{"title":"Bake","description":"Bake for 30 minutes. Remove, loosely cover with foil, then bake for a further 15 minutes until a toothpick inserted into the centre comes out clean.","duration":30,"images":[],"step":15},{"description":"Turning out cake:","images":[],"step":16},{"title":"Cool 20 minutes","description":"Remove cake from oven and leave inside pan to cool for 20 minutes.","duration":20,"images":[],"step":17},{"description":"Flip! Run a butter knife around the inner edge of the cake pan. Put a plate or serving platter over the cake, then flip. Tap base / shake pan gently then lift slowly. Voila!","images":[],"step":18},{"description":"Cool completely before serving.","images":[],"step":19}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","dessert-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_07eb7fcf2319', 'en', 'US', 'Carrot Cake Cupcakes with Cream Cheese Frosting', 'Recipe video above. Carrot cake, but in cupcake form! These little beauties are ultra-moist, spiked with cinnamon and dotted through with nuts. Crowned with a creamy and fluffy cream cheese frosting, they''re perfect as little treats or served for dessert.While carrot seems like a bizarre thing to add to a cake, the reason for it is very simple: It results in a moist and tender crumb quite unlike any other type of cake. It doesn''t taste like carrot at all, and were it not in the name nobody would be the wiser!', 'https://www.recipetineats.com/tachyon/2021/02/Carrot-Cake-Cupcakes_5.jpg', 30, 20, 45, 12, '[{"id": "ing_pineapple", "quantity": {"value": 440.0, "unit": "unit"}}, {"id": "ing_milk", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.003, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.031, "unit": "tub of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.156, "unit": "jar of 40g"}}, {"id": "ing_carrot", "quantity": {"value": 200.0, "unit": "pack of 1kg"}}, {"id": "ing_coconut", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_walnuts", "quantity": {"value": 50.0, "unit": "jar"}}, {"id": "ing_cream_cheese", "quantity": {"value": 180.0, "unit": "block of 250g"}}, {"id": "ing_butter", "quantity": {"value": 90.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.05, "unit": "bottle of 50ml"}}]', '[{"ingredients":["440g / 14 oz (1 can) crushed pineapple in juice (, drained but RESERVE juice (Note 1))"]},{"ingredients":["1/2 cup milk (, at room temperature (full fat best, low fat ok))","1/2 tsp white vinegar (or lemon juice or other clear vinegar, (Note 2))","2 large eggs (, at room temperature)","1 cup brown sugar (loosely packed)","1/3 cup vegetable oil (or canola)"],"purpose":"Wet Ingredients"},{"ingredients":["1 1/3 cups flour (, plain / all-purpose)","1 1/4 tsp baking soda (aka bicarb soda, Note 3) (NOT BAKING POWDER!)","1/4 tsp salt","1 1/4 tsp cinnamon powder"],"purpose":"Dry Ingredients"},{"ingredients":["1 1/3 cups shredded carrot (, 1 medium carrot peeled (Note 4))","2 tbsp coconut (, shredded or desiccated (unsweetened))","1/3 cup walnuts or pecans (, roughly chopped (ie. measure after chopping))"],"purpose":"Stir-ins"},{"ingredients":["180g / 6oz cream cheese (, at room temperature (Note 5))","90g / 6 tbsp unsalted butter (, softened (17°C/62°F))","3 1/2 cups soft icing sugar / powdered sugar (, sifted (Note 6))","1/2 tsp vanilla extract","1/8 tsp salt"],"purpose":"Cream Cheese Frosting"},{"ingredients":["1/4 cup walnuts or pecans (, moderately finely chopped)"],"purpose":"Decorating (optional)"}]', '[{"description":"Preheat oven to 180°C/350°F (all oven types). Line a 12-hole muffin tin with cupcake liners.","images":[],"step":1},{"title":"Canned pineapple","description":"Drain crushed pineapple well, reserving the juice. Measure out 3/4 cup pineapple and 2 tbsp pineapple juice.","images":[],"step":2},{"title":"Whisk Dry Ingredients","description":"Whisk Dry ingredients in a large bowl.","images":[],"step":3},{"title":"Whisk Wet Ingredients","description":"In a separate bowl, whisk together the milk, vinegar, eggs, sugar, oil and the 2 tbsp pineapple juice from Step 2.","images":[],"step":4},{"title":"Add-ins","description":"Stir in carrot, crushed pineapple, coconut and pecans into the Wet ingredients bowl.","images":[],"step":5},{"title":"Combine Wet & Dry","description":"Pour Wet into Dry ingredients, stir only until flour is no longer visible. Batter will be lumpy (from the stir-ins) and thick, but runny.","images":[],"step":6},{"title":"Fill muffin tin","description":"Divide batter between 12 holes. (A 3-tbsp levered ice cream scoop makes life super-easy here.)","images":[],"step":7},{"description":"Bake 20 minutes or until a toothpick inserted into the centre comes out clean. Transfer to cooling rack and fully cool before frosting.","images":[],"step":8},{"description":"Cream Cheese Frosting","images":[],"step":9},{"title":"Cream butter","description":"Using the paddle attachment on a stand mixer (or whisk attachments for hand mixer), beat the butter for 1 minute until smooth, scraping down the sides as needed.","duration":1,"images":[],"step":10},{"title":"Cream cheese","description":"Add cream cheese then beat for 1 minute until smooth.","duration":1,"images":[],"step":11},{"title":"Icing sugar","description":"Add 1/3 of the icing sugar, then starting on the lowest speed (to avoid a powdery explosion!), beat until mostly incorporated. Add half the remaining icing sugar, beat it in, then the remaining icing sugar.","images":[],"step":12},{"description":"Fluff it! Beat on high for 2 minutes until fluffy. Add vanilla and salt, beat briefly to incorporate.","duration":2,"images":[],"step":13},{"title":"Pipe","description":"Transfer to piping bag fitted with a round tip (or ziplock bag with snipper corner). Pipe on to cupcake, sprinkle with chopped walnuts or pecans if desired.","images":[],"step":14}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","cupcakes-and-muffins","dessert-recipes","easter-baking-desserts"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6ecd351a2f9f', 'en', 'US', 'Molten Chocolate Cakes', 'Recipe video above. The one thing that sets these Lava Cakes apart from the rest? The molten centre isn''t just raw cake batter, it''s melted chocolate. No more stress about overcooking the molten centre - because chocolate will always ooze. And chocolate trumps raw cake batter in the texture and taste test, always!Shortcut tip: Use a Lindt ball in place of the ganache. I''d use the dark chocolate balls (blue wrappers). Readers have tried and LOVE this!', 'https://www.recipetineats.com/tachyon/2021/02/Chocolate-Lava-Cake_7.jpg', 10, 20, 30, 4, '[{"id": "ing_chocolate", "quantity": {"value": 0.5, "unit": "block of 100g"}}, {"id": "ing_cream", "quantity": {"value": 0.24, "unit": "carton of 250ml"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.24, "unit": "carton of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_strawberries", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}]', '[{"ingredients":["1/2 cup dark chocolate chips or melts/ semi sweet chocolate chips (Note 1)","4 tbsp cream (, heavy/thickened)"],"purpose":"Molten Chocolate Ganache Centre:"},{"ingredients":["1 cup dark chocolate chips or melts/ semi sweet chocolate chips (Note 1)","100g / 7 tbsp unsalted butter (, cut into 1cm / ½\" cubes)","2 eggs (, at room temperature)","2 egg yolks (, at room temperature (Note 2))","1/2 cup caster/superfine sugar (sub ordinary white sugar)","2 tbsp flour (, plain / all purpose)"],"purpose":"Cake Batter:"},{"ingredients":["Ice-cream or cream (highly recommended!)","Cocoa or icing sugar / powdered sugar (, for dusting)","Strawberries (, raspberries or edible flowers, optional decoration)"],"purpose":"To Serve:"}]', '[{"description":"Molten chocolate ganache:","images":[],"step":1},{"description":"Place chocolate and cream in a microwave-proof bowl. Microwave on high for three 20-second bursts, stirring in between, until chocolate is melted and smooth.","images":[],"step":2},{"description":"Let cool on the counter for 10 minutes, then refrigerate for 3 hours or until firm enough to scoop into balls. (Note 3)","duration":10,"images":[],"step":3},{"description":"Preheat oven to 200°C / 390°F (180°C fan).","images":[],"step":4},{"title":"Grease & dust moulds","description":"Grease 4 x 170ml / 5.75oz dariole or pudding moulds with butter then dust insides with cocoa powder, tapping out excess. (Note 4)","images":[],"step":5},{"title":"Melt chocolate and butter","description":"Place chocolate and butter in a bowl. Microwave in 30 second bursts, stirring in between. Stir well until smooth, then leave to cool for 5 minutes.","duration":5,"images":[],"step":6},{"title":"Whisk eggs and sugar","description":"In a separate bowl, whisk together the eggs, egg yolks and sugar.","images":[],"step":7},{"title":"Combine with chocolate","description":"Add the melted chocolate into the eggs, and mix until combined.","images":[],"step":8},{"title":"Fold through flour","description":"Add flour and fold through until just combined. Do not over-mix.","images":[],"step":9},{"title":"Fill moulds","description":"Pour or scoop the batter into prepared moulds until it reaches ⅓ of the way up.","images":[],"step":10},{"title":"Drop in ganache","description":"Place one generously-heaped teaspoon of ganache into middle of batter. Top with more batter until it reaches 1.5cm / ⅗\" from the top rim. Repeat for remaining moulds.","images":[],"step":11},{"title":"Bake 20 minutes","description":"Place the moulds on an oven tray and bake for 20 minutes, or until the pudding tops spring back when gently touched.","duration":20,"images":[],"step":12},{"title":"Turn out","description":"Stand for 2 minutes, then turn onto plate. Tap base then gently remove each mould.","duration":2,"images":[],"step":13},{"description":"Serve with ice-cream or cream, dusted with cocoa powder. Decorate with strawberries!","images":[],"step":14}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","cosy-desserts","dessert-recipes","egg-yolk-recipes","puddings-cosy-desserts"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_098ad3497a85', 'en', 'US', 'Salted Caramel-Stuffed Brownies', 'Recipe video above. How do you make a fudge-y brownie even better? Stuff it with salted caramel!', 'https://www.recipetineats.com/tachyon/2015/08/Salted-Caramel-Stuffed-Brownies_7a.jpg', 20, 30, 50, 16, '[{"id": "ing_butter", "quantity": {"value": 200.0, "unit": "block of 250g"}}, {"id": "ing_chocolate", "quantity": {"value": 200.0, "unit": "block of 100g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_cocoa_powder", "quantity": {"value": 0.15, "unit": "pack of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.395, "unit": "L"}}, {"id": "ing_maple_syrup", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}]', '[{"ingredients":["200g / 7oz unsalted butter","200g / 7oz dark chocolate / semi sweet chocolate chips (Note 1)","1 cup brown sugar","3 eggs (, lightly whisked)","1 tsp vanilla extract (or essence)","1/2 cup flour (, plain/all purpose)","1/4 cup cocoa powder","1/8 tsp salt"],"purpose":"Brownie"},{"ingredients":["395g / 14 oz can sweetened condensed milk","2 tbsp golden syrup or maple syrup (Note 2)","60g / 2 oz unsalted butter","1 tsp salt"],"purpose":"Salted Caramel"}]', '[{"description":"Preheat oven to 180°C/350°F (all oven types).","images":[],"step":1},{"description":"Butter and line a 20cm / 8\" square tin with parchment / baking paper.","images":[],"step":2},{"description":"Place the ingredients in a small saucepan over medium high heat. Stir occasionally for the first 1 minute. When it is heated (ie. when you see wisps of steam), whisk constantly (leisurely, not vigorously!) for 7 minutes, ensuring the base doesn''t catch (Note 3). It should be a pale golden colour.","duration":7,"images":[],"step":3},{"description":"Remove from stove and whisk for 30 seconds. Place lid on, set aside and keep warm.","duration":0.5,"images":[],"step":4},{"description":"Brownies:","images":[],"step":5},{"title":"Melt chocolate & butter","description":"Place chocolate and butter in a bowl. Microwave in three 30 second bursts on high, stirring in between bursts, until melted and smooth.","images":[],"step":6},{"title":"Add sugar, eggs, vanilla","description":"Add the sugar, eggs and vanilla extract to the chocolate mixture and mix well to combine.","images":[],"step":7},{"title":"Add dry ingredients","description":"Sift in the flour, cocoa powder and salt. Mix until smooth and combined.","images":[],"step":8},{"title":"Reserve some batter","description":"Measure out 1/2 cup of brownie batter and set aside. Pour the remaining batter into the prepared tin.","images":[],"step":9},{"title":"Pour over caramel","description":"Pour the Salted Caramel over the brownie batter, getting as much coverage as you can (as you can''t easily spread the caramel once poured). If caramel has cooled and is no longer pourable, reheat it on stove for 1 minute until runny again.","duration":1,"images":[],"step":10},{"title":"Cover with reserved brownie batter","description":"Dollop the reserved 1/2 cup of brownie batter randomly over the Salted Caramel. Use a knife or skewer to make “swirls” - they won''t be so visible once baked, it''s more about spreading brownie batter over the caramel.","images":[],"step":11},{"title":"Bake","description":"Place in the oven and bake for 30 minutes (for very gooey brownie, as pictured) to 35 minutes (for very moist but not super-gooey).","duration":30,"images":[],"step":12},{"title":"Cool","description":"Leave to cool in pan for 10 minutes. Use surplus paper overhang to lift out onto a cooling rack. Cool for a further 20 minutes before slicing. Note: Caramel is a bit gooey when still warm but sets firmer once fully cooled, ie. it will cut through neatly.","duration":10,"images":[],"step":13}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","dessert-recipes","most-popular","slices-bars"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0f2c58644adb', 'en', 'US', 'Blueberry Cake with Lemon Frosting', 'Recipe video above. This is the blueberry cake I make when I want to go all out! It''s always received with gasps of delight when the first slice is pulled out. :)Adapted from my Vanilla Cake, the crumb is soft and plush, infused with a subtle hint of lemon which goes so well with blueberries. The slight tang of cream cheese frosting is a perfect match for this cake and takes it over the top.Stays fresh for 5 whole days!', 'https://www.recipetineats.com/tachyon/2021/01/Slice-of-3-layer-Blueberry-Cake.jpg', 30, 25, 55, 12, '[{"id": "ing_flour", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 2.5, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 333.333, "unit": "carton of 12"}}, {"id": "ing_sugar", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 115.0, "unit": "block of 250g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.6, "unit": "tub of 250g"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.3, "unit": "bottle of 50ml"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_blueberries", "quantity": {"value": 3.0, "unit": "punnet of 125g"}}, {"id": "ing_flour", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 115.0, "unit": "block of 250g"}}, {"id": "ing_cream_cheese", "quantity": {"value": 250.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_blueberries", "quantity": {"value": 3.0, "unit": "punnet of 125g"}}]', '[{"ingredients":["2 cups flour (, plain / all purpose (Note 1))","2 1/2 teaspoons baking powder","1/4 tsp salt","4 large eggs (50-55g / 2oz each), at room temp (Note 2)","1 1/2 cups sugar (, caster / superfine (Note 3))","115g / 1/2 cup unsalted butter (, melted & HOT)","1 cup sour cream (, full fat, at room temperature (Note 5))","3 tsp vanilla extract","3 tsp vegetable or canola oil (Note 6)","3 tsp lemon zest"]},{"ingredients":["375g / 2 1/2 cups blueberries (Note 7 for frozen)","2 tsp flour"],"purpose":"Blueberries"},{"ingredients":["225g / 2 sticks unsalted butter (, at room temperature)","250g / 8oz cream cheese (, brick not tub, at room temperature but not too soft (Note 8, esp UK))","4 cups soft icing sugar / powdered sugar (, SIFTED)","1 tsp vanilla extract","2 tbsp lemon juice","Pinch of salt"],"purpose":"Lemon Cream Cheese Frosting"},{"ingredients":["Extra blueberries, lemon slices, edible flowers"],"purpose":"Decorating (optional):"}]', '[{"title":"Preheat oven","description":"Preheat oven to 180°C/350°F (160°C fan) for 20 minutes before starting the batter. Place one shelf in the middle of the oven and a second beneath it.","duration":20,"images":[],"step":1},{"title":"Cake pans","description":"Grease 3 x 20cm / 8” cake pans with butter and line with parchment / baking paper. (Note 9 more pan sizes)","images":[],"step":2},{"title":"Blueberries","description":"Set aside ~1/3 of the blueberries (for scattering later). Toss the remaining blueberries in flour.","images":[],"step":3},{"title":"Be prepared","description":"Have all batter ingredients measured out and ready to add in. New to baking? Read ''Tips for Success'' above recipe card.","images":[],"step":4},{"title":"Combine dry ingredients","description":"Whisk flour, baking powder and salt in a large bowl. Set aside.","images":[],"step":5},{"title":"Whisk eggs","description":"Beat eggs for 30 seconds on speed 6 of a stand mixer fitted with a whisk attachment, or hand beater.","duration":0.5,"images":[],"step":6},{"title":"Add sugar, then beat","description":"With the beater still going, pour the sugar in over 45 seconds. Then beat for 7 minutes on speed 8, or until tripled in volume and white.","duration":7,"images":[],"step":7},{"title":"Gently add flour","description":"Scatter 1/3 flour across surface of whipped eggs, then beat on Speed 1 for 5 seconds. Add half remaining flour, mix on Speed 1 for 5 sec. Add remaining flour, then mix on Speed 1 for 5 - 10 sec until the flour is just mixed in. Once you can’t see flour, stop straight away.","duration":0.08333333333333333,"images":[],"step":8},{"title":"Whisk wet ingredients","description":"Put sour cream, hot butter, oil, vanilla and lemon zest into the now-empty flour bowl. Whisk well until smooth.","images":[],"step":9},{"title":"''Temper'' sour cream mix","description":"Add about 1 1/2 cups of the egg mixture into the sour cream bowl (2 big scoops, no need to be accurate). Whisk well until smooth.","images":[],"step":10},{"title":"Slowly combine sour cream mix and egg mix","description":"Turn beater back on Speed 1 then scrape the sour cream mixture into the egg mixture over 15 seconds, then turn beater off.","images":[],"step":11},{"title":"Scrape and final mix","description":"Scrape down sides and base of bowl. Beat on Speed 1 for 10 seconds. The batter should be thick but soft, not runny and thin.","duration":0.16666666666666666,"images":[],"step":12},{"title":"Blueberries","description":"Quickly but gently fold in flour coated blueberries.","images":[],"step":13},{"description":"Divide batter between cake pans, smooth the surface. Scatter over reserved blueberries.","images":[],"step":14},{"description":"Bake 25 minutes or until golden and toothpick inserted into centre comes out clean. (If you cannot fit all pans on one shelf, put 2 pans in the middle shelf and 1 pan underneath. Take the top pans out at 25 minutes, move the lower pan to middle shelf and bake for a further 3 minutes)","images":[],"step":15},{"description":"Once out of oven, cool in cake pans for 15 minutes, then gently turn out onto cooling racks upside down. Peel off baking paper and cool upside down - any slight dome will flatten perfectly (for neat layers).","duration":15,"images":[],"step":16},{"description":"Frost upside down layers with Cream Cheese Frosting! Decorate with extra blueberries, lemon slices and edible flowers, if desired.","images":[],"step":17},{"description":"Lemon Cream Cheese Frosting:","images":[],"step":18},{"description":"Beat butter with whisk attachment in stand mixer for 2 minutes until fluffy and creamy, and it becomes a paler colour. Add cream cheese, then beat for 30 seconds just until smooth.","duration":2,"images":[],"step":19},{"description":"Add icing sugar / powdered sugar, then gently mix on speed 1 (to avoid an icing powder storm). If you do get a powder storm, cover with tea towel, then once mostly incorporated, beat on high for a full 2 minutes on Speed 7.","images":[],"step":20},{"description":"Add vanilla and lemon juice, then beat for a further 30 seconds. Use immediately. (Note 11 re: frosting too sloppy)","images":[],"step":21}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","blueberries","dessert-recipes","easter-baking-desserts"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7c7a75646835', 'en', 'US', 'Gingerbread Men', 'Recipe video above. Classic gingerbread men! I love these because you can actually taste the spices. Smells like Christmas when they''re baking!TOP TIP: The dough is quite sticky to work with (but sticky dough = moist cookie!). The trick is to make sure it''s cold - so if it gets too sticky, return to refrigerator for a bit at anytime during roll out/cutting process.', 'https://www.recipetineats.com/tachyon/2020/11/Gingerbread-Men_7.jpg', 30, 40, 70, 18, '[{"id": "ing_flour", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.1, "unit": "tub of 150g"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_cinnamon", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_mixed_spice", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_round_clove", "quantity": {"value": 15.0, "unit": "jar"}}, {"id": "ing_butter", "quantity": {"value": 85.0, "unit": "block of 250g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.2, "unit": "bottle of 50ml"}}, {"id": "ing_molasses_light_true", "quantity": {"value": 75.0, "unit": "jar"}}]', '[{"ingredients":["3 cups flour (, plain/all purpose)","3 tsp baking powder","1 tbsp ground ginger","2 tsp ground cinnamon","1 tsp mixed spice (Note 1)","1/4 tsp ground cloves (Note 2)"],"purpose":"Dry Ingredients:"},{"ingredients":["85g / 5 1/2 tbsp unsalted butter (, softened (Note 3))","3/4 cup brown sugar (Note 4 re: light or dark brown)","1 large egg (, at room temperature (Note 5))","2 tsp vanilla extract","1/2 cup molasses, light / true (NOT blackstrap)(Note 6)"],"purpose":"Wet Ingredients:"}]', '[{"description":"Whisk Dry Ingredients on one bowl.","images":[],"step":1},{"title":"Cream butter & sugar","description":"In a separate bowl, cream the butter and sugar together using a stand mixer or electric beater on speed 7 for 2 minutes, or until light and fluffy.","duration":2,"images":[],"step":2},{"title":"Egg & vanilla","description":"Add the egg and vanilla, then mix on speed 5 until combined (~30 sec).","images":[],"step":3},{"title":"Molasses","description":"Add the molasses, mix for 1 minute using speed 2.","duration":1,"images":[],"step":4},{"title":"Gradually add dry ingredients","description":"Add 1/4 of the Dry ingredients, then mix until you can''t see flour (start on speed 1 to stop flour flying everywhere!). Repeat until all Dry ingredients are mixed in, then mix for further 15 seconds. Dough should be soft and a bit sticky - see video for texture.","images":[],"step":5},{"title":"Refrigerate","description":"Pat dough into a disc shape, wrap in the cling wrap and refrigerate for at least 2 hours or until firm. (Can refrigerate 5 days or freeze 3 months).","images":[],"step":6},{"description":"Preheat the oven to 375°F/190°C (170°C fan) and set a shelf in the middle. Line 3 x baking trays with parchment/baking paper.","images":[],"step":7},{"description":"Take the dough out of the refrigerator and cut into half. Wrap half and return to the fridge.","images":[],"step":8},{"description":"Roll out (Note 7)- Sprinkle a sheet of baking paper very lightly with flour. Place dough on top, sprinkle surface very lightly with flour. Place another sheet of baking paper on top. Roll dough out until 4mm / 1/6\" thick using a rolling pin. As you work, flip and if paper is wrinkling, peel it off then put if back on, smoothing out wrinkles.","images":[],"step":9},{"title":"Cut out shapes (Note 8)","description":"Use a gingerbread cookie cutter to cut out gingerbread men shapes, firmly pressing to cut all the way through. If the dough sticks to the cutter, dip it into flour.","images":[],"step":10},{"title":"Transfer","description":"Use a palette knife (or large knife) to transfer shapes onto baking sheet. Place 6 on the first sheet. Tidy edges if necessary using a butter knife.","images":[],"step":11},{"title":"Bake Tray 1","description":"Bake for 12 minutes (for classic light golden) or 14 minutes (dark golden and crisp). Then remove and cool fully on tray.","duration":12,"images":[],"step":12},{"title":"Repeat","description":"Meanwhile, gather scraps of dough, press together then roll out again. If dough is sticky, return to refrigerator and work on the other half of the dough instead. Repeat rolling out and cutting out. You should have 18 to 20 gingerbread men in total (depending on cutter size)","images":[],"step":13},{"title":"Trays 2 & 3","description":"Fill and bake 2nd and 3rd tray with gingerbread men, 6 to 8 on each tray. I find the workflow that works best is baking one tray at a time ie. roll/cut-out/fill/bake one tray while you prepare the next.","images":[],"step":14},{"title":"Decorate","description":"Fully cool on trays, then decorate! Use a half batch of this Royal Icing recipe to pipe and stick on decorations (sets hard and doesn''t soak into cookies). The recipe makes more than you need, but it''s impractical to make less. So freeze leftovers in fully sealed piping bag for future use.","images":[],"step":15}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","cookies"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b56a65dd8aa3', 'en', 'US', 'Bread and Butter Pudding', 'Recipe video above. A quintessential British dessert and a firm favourite world-wide, this is custardy on the inside, and golden and buttery on the surface! While pre-sliced bread works a treat, it''s dinner party-worthy when made with bread that can be cut or torn into cubes. Crunchier surface, and better custardy texture inside!This is the Aussie / British version which is far less sweet than typical American Bread Pudding recipes (but still plenty sweet in my opinion!). Toppings are not optional!', 'https://www.recipetineats.com/tachyon/2017/04/Bread-Butter-Pudding_4.jpg', 10, 25, 35, 6, '[{"id": "ing_bread", "quantity": {"value": 8.0, "unit": "loaf"}}, {"id": "ing_sultanas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.8, "unit": "carton of 250ml"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_chocolate", "quantity": {"value": 1.0, "unit": "block of 100g"}}]', '[{"ingredients":["8 heaped cups white bread, preferably slightly stale, cut into 2.5 cm / 1\" cubes (see Note 1 if for pre-sliced bread)","1 cup sultanas or raisins (or more!)"]},{"ingredients":["3 eggs","1 1/2 cups milk (low or full fat, not zero fat)","1 cup heavy / thickened cream (or any other cream, Note 2 for more milk option)","3 tbsp / 40g unsalted butter, melted and cooled","1/2 cup white sugar","1 tsp cinnamon powder","1 tsp vanilla extract"],"purpose":"Egg Mixture:"},{"ingredients":["30g / 2 tbsp unsalted butter, melted - for top pre baking","20g / 1 1/2 tbsp unsalted butter, melted - for brushing post baking (optional)","Icing sugar / powdered sugar, for dusting","Ice cream, cream, custard, chocolate sauce, caramel sauce, etc"],"purpose":"Finishes / Serving"}]', '[{"description":"Preheat oven to 180°C/350°F (all oven types)","images":[],"step":1},{"title":"Egg Mixture","description":"Place eggs in a large bowl, whisk briefly. Add remaining Egg Mixture ingredients and whisk.","images":[],"step":2},{"title":"Soak Bread","description":"Add bread and sultanas, briefly mix, then set aside for 3 minutes to allow egg mixture to soak through the bread.","duration":3,"images":[],"step":3},{"title":"Transfer to baking dish","description":"Pour into a baking dish (10 cup / 2.5 litre / 2.5 quart). If you have lots of sultanas on the surface, poke them below the surface (Note 3).","images":[],"step":4},{"title":"Drizzle then bake","description":"Drizzle over melted butter, then bake for 25 - 30 minutes or until golden on top and the inside is set but still slightly wobbly (poke to check).","duration":27.5,"images":[],"step":5},{"description":"Brush with remaining 1 1/2 tbsp melted butter (optional), then dust with icing sugar.","images":[],"step":6},{"title":"Serve","description":"rest for a few ninutes, then serve immediately, with toppings of choice! My favourites are ice cream, custard and cream.","images":[],"step":7}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":["Australian","English","Western"],"categories":["baking-recipes","cosy-desserts","dessert-recipes","easter-baking-desserts","puddings-cosy-desserts","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d07588cb470a', 'en', 'US', 'Vanilla Cupcakes - stays moist 4 days!!', 'Recipe video above. Your search for the perfect Vanilla Cupcakes is over! These have a professional bakery-style crumb that''s way more plush and velvety than typical recipes. And very importantly, these stay perfectly fresh for 4 days - unheard of!While for Vanilla Cake, I prefer using a standmixer, for these cupcakes, I find it''s easier to use a handheld beater - see notes for why.Metric - click button above ingredients. Sweetness - Note 11. Cake flour - no need, better with plain flour. See Notes for four key things to guarantee success.', 'https://www.recipetineats.com/tachyon/2020/09/Vanilla-Cupcakes-with-Vanilla-Swiss-Meringue-2.jpg', 20, 22, 42, 12, '[{"id": "ing_flour", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.042, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_sugar", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_milk", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.2, "unit": "bottle of 50ml"}}, {"id": "ing_oil", "quantity": {"value": 7.5, "unit": "bottle"}}]', '[{"ingredients":["1 cup plain / all purpose flour (cake flour OK too, Note 1)","1 1/4 tsp baking powder (NOT baking soda, Note 2)","1/8 tsp salt","2 large eggs (50 - 55g / 2 oz each), at room temp (Note 3)","3/4 cup caster / superfine sugar (granulated/regular ok too, Note 4)","60g / 1/4 cup unsalted butter (, cut into 1.5cm / 1/2” cubes)","1/2 cup milk (, full fat (Note 5))","2 tsp vanilla extract (, the best you can afford (Note 6))","1 1/2 tsp vegetable or canola oil (Note 7)"]}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan) for 20 minutes before starting the batter (Note 8). Place shelf in the middle of the oven.","duration":20,"images":[],"step":1},{"description":"Place cupcake liners in a standard muffin tin. (Note 9)","images":[],"step":2},{"description":"Cupcake Batter:","images":[],"step":3},{"title":"Whisk Dry","description":"Whisk flour, baking powder and salt in a large bowl. Set aside.","images":[],"step":4},{"title":"Heat Milk-Butter","description":"Place butter and milk in a heatproof jug and microwave 2 minutes on high to melt butter. Do not let milk bubble and boil (foam ok). Cover and leave in microwave to keep very warm (stove: cover with lid and leave on turned off stove). (Note 10)","images":[],"step":5},{"title":"Mix eggs","description":"In a separate, preferably heavy based glass bowl, beat eggs for 30 seconds on speed 6 of a handheld beater.","duration":0.5,"images":[],"step":6},{"title":"Add sugar","description":"With the beater still going, pour the sugar in over 30 seconds.","images":[],"step":7},{"title":"Beat until tripled","description":"Beat eggs for 6 minutes on speed 8, or until tripled in volume and almost pure white.","duration":6,"images":[],"step":8},{"title":"Add flour","description":"When the egg is whipped, scatter 1/3 flour across surface, then beat on Speed 1 for 5 seconds. Stop beating, add half remaining flour, then mix on Speed 1 for 5 sec. Add remaining flour, then mix on Speed 1 for 5 - 10 sec until the flour is just mixed in. Once you can’t see flour, stop straight away.","duration":0.08333333333333333,"images":[],"step":9},{"title":"Temper milk","description":"Pour hot milk, vanilla and oil into the now empty flour bowl. Add about 3/4 cups of the Egg Batter into the hot milk (don''t need to be 100% accurate with amount). Use a whisk to mix until smooth - you can be vigorous here. Will look foamy.","images":[],"step":10},{"title":"Slowly add milk","description":"With the beater on Speed 1, pour the Milk mixture into the Egg Batter over 15 seconds, then turn beater off.","images":[],"step":11},{"title":"Scrape and final mix","description":"Scrape down sides and base of bowl. Beat on Speed 1 for 10 seconds - batter should now be smooth and pourable.","duration":0.16666666666666666,"images":[],"step":12},{"title":"Fill muffin tin","description":"Pour batter into muffin tin, filling 2/3 of the way up. Do not fill more (causes flat / sunken surfaces). Easiest to use a standard ice cream scoop with lever.","images":[],"step":13},{"description":"Bake 22 minutes or until golden and toothpick inserted into middle comes out clean.","images":[],"step":14},{"description":"Remove from oven. Cool just 2 minutes then use a fork to help remove and place on cooling rack. Cool completely before icing with frosting of choice (Note 11 for ideas), or cream and fresh berries or jam.","images":[],"step":15}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","cupcakes-and-muffins","dessert-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a8c1fb7d3125', 'en', 'US', 'My Secret Less-Sweet, Fluffy Vanilla Frosting', 'Recipe video above. This is actually an old fashioned frosting called Ermine Frosting that was traditionally used for Red Velvet Cake. Though not widely known, many consider it far superior to buttercream because its 100% silky smooth, far less sweet and much fluffier - which means you can pipe sky high mounds onto cupcakes and it won''t be sickly sweet. The texture is like whipped cream but slightly more dense. But while whipped cream deflates within hours, this frosting will hold its shape for days! Don''t be turned off by the flour - you absolutely cannot taste it at all. Makes enough to frost 12 cupcakes generously with tall swirls (pictured), or 24 cupcakes swirled on with a knife, or a two or three layer 20 - 23cm/8-9" cake.', 'https://www.recipetineats.com/tachyon/2020/09/Fluffy-Vanilla-Frosting_Less-Sweet_Ermine-Frosting_1-white-copy.jpg', 20, 10, 30, 12, '[{"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.15, "unit": "bottle of 50ml"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 225.0, "unit": "block of 250g"}}, {"id": "ing_cocoa_powder", "quantity": {"value": 0.15, "unit": "pack of 250g"}}]', '[{"ingredients":["5 tbsp flour (, plain/all purpose)","1 cup white sugar (, regular/granulated (can reduce to 1/2 cup, Note 1))","1 cup milk, warmed using any method (, full fat best (but even 0% fat works))","1 1/2 tsp vanilla extract","Pinch of salt","225g / 1 cup unsalted butter (, softened but not too soft! (Note 3))"]},{"ingredients":["1/4 cup cocoa powder, unsweetened (Dutch processed best, if you can)"],"purpose":"Chocolate Frosting option:"}]', '[{"description":"Thickening Roux:","images":[],"step":1},{"description":"Place flour and sugar in a large saucepan over medium heat. Cook, stirring constantly, for 30 seconds.","duration":0.5,"images":[],"step":2},{"description":"While whisking constantly, slowly pour the milk in (this ensure it''s lump free).","images":[],"step":3},{"title":"As the milk gets hotter, it will start to thicken","description":"stir constantly so the base doesn''t catch.","images":[],"step":4},{"description":"Cook until the mixture thickens in a thick, dolloping custard - see video for texture. TIP: Thicker texture = thicker frosting texture but won''t make the frosting dense, it''s still fluffy and spreadable but it just makes it \"sturdier\" with sharper edges when piped.","images":[],"step":5},{"description":"Remove from heat and scrape into a bowl. Cover with cling wrap, pressing down onto the surface to prevent a skin from forming.","images":[],"step":6},{"description":"Cool completely (I leave on counter for 20 min or so then refrigerate 30 min to speed up but don''t let it get chilled, best at room temp to beat into butter). You can leave in fridge overnight but take it out 1 hour prior to using (to dechill - otherwise it won''t mix well with softened butter).","duration":20,"images":[],"step":7},{"description":"Making the Fluffy Frosting:","images":[],"step":8},{"description":"Place butter in a bowl and use either a handheld beater or stand mixer (with whisk attachment) to beat for 3 minutes until it''s smooth and changes from yellow to very pale yellow, almost white.","duration":3,"images":[],"step":9},{"description":"Now start whipping in the Thickening Roux. On speed 5 (medium), start adding the thick roux one heaped tablespoon at a time. Take about 1 minute to add it all.","images":[],"step":10},{"description":"Once all added, add vanilla and salt, then whip for 2 to 3 minutes until you can see that it is still enough to hold peaks. Then it''s ready to use!","duration":2.5,"images":[],"step":11},{"description":"Chocolate flavoured option:","images":[],"step":12},{"description":"Beat in the cocoa powder at the end, just until mixed through.","images":[],"step":13},{"description":"Frosting cakes and cupcakes:","images":[],"step":14},{"description":"Use it like any other frosting on cakes and cupcakes - either spread it on with a knife or put in a piping bag. You can pipe sky-high mounds and it will hold its form, as pictured on Vanilla Cupcakes in this post.","images":[],"step":15},{"description":"See notes for storage / make ahead.","images":[],"step":16}]', '["gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","cupcakes-and-muffins","dessert-recipes","frosting-and-icing"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_39d387217808', 'en', 'US', 'Strawberry Cake (really easy cake recipe)', 'Recipe video above. With 500g / 1lb strawberries IN and ON the cake, this really is bursting with fresh strawberry flavour! This may well be the fastest and easiest cake recipe you''ll make this year. Yogurt keeps the crumb beatifully tender and moist, and it keeps perfectly for days.Resist the temptation to load it up with more than 1 cup chopped strawberries inside the cake - strawberries are really juicy which leeches into the batter, exponentially increasing bake time + can make the crumb too wet.Lovely served at room temperature with cream, or warm with ice cream (I love it both ways!).', 'https://www.recipetineats.com/tachyon/2020/07/Strawberry-Cake_0.jpg', 15, 50, 65, 10, '[{"id": "ing_strawberries", "quantity": {"value": 2.0, "unit": "punnet of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.3, "unit": "tub of 500g"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_flour", "quantity": {"value": 0.338, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.133, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.004, "unit": "carton of 250ml"}}, {"id": "ing_strawberries", "quantity": {"value": 2.0, "unit": "punnet of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}]', '[{"ingredients":["500g / 1 lb strawberries (, hulled (ie tops removed))"],"purpose":"Strawberries"},{"ingredients":["1 cup sugar (, caster/superfine best but granulated ok too)","1/2 cup oil (, canola or vegetable oil)","2 eggs (, large (~50g/1.75 oz each))","1 tbsp grated lemon rind","1/4 cup lemon juice (1 large lemon)","1 cup plain yoghurt (, unsweetened (Greek or just plain))","1 tsp vanilla extract (or essence)"],"purpose":"WET:"},{"ingredients":["2 1/4 cups flour (, plain/all purpose)","4 tsp baking powder (or 1 1/4 tsp baking soda)","Pinch of salt"],"purpose":"DRY:"},{"ingredients":["Whipped cream","Extra strawberries","Icing sugar/ powdered sugar (, for dusting)"],"purpose":"SERVING:"}]', '[{"description":"Preheat oven to 200°C/390°F (180°C fan).","images":[],"step":1},{"description":"Grease and line a 23 cm / 9\" cake pan with baking paper/parchment paper. (Any type of cake pan is fine)","images":[],"step":2},{"title":"For inside of cake","description":"Dice some strawberries into ~1.5cm / 1\" pieces to make 1 cup (about 1/3 of the strawberries)","images":[],"step":3},{"title":"Topping","description":"Cut the remaining strawberries in half.","images":[],"step":4},{"description":"Place Wet ingredients in a bowl and whisk well for 1 minute.","duration":1,"images":[],"step":5},{"description":"Add Dry ingredients then whisk well until lump free.","images":[],"step":6},{"description":"Pour half into cake pan, smooth surface. Scatter over diced strawberries.","images":[],"step":7},{"description":"Top with remaining batter. Smooth surface, then top with halved strawberries, cut face down.","images":[],"step":8},{"description":"Bake 50 minutes or until skewer inserted into centre comes out clean. (Note 1) If you need to cook longer, cover with foil if it starts getting too golden.","images":[],"step":9},{"description":"Stand 15 minutes in the cake pan before turning out onto cooling rack.","images":[],"step":10},{"description":"Cool 15 minutes+ before serving warm or at room temp. Dust with icing sugar, and serve with cream or if serving warm, ice cream!","images":[],"step":11}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","dessert-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8af952c34f96', 'en', 'US', 'Crumpet recipe', 'Recipe video above. This is the crumpet recipe released by Warburtons, the UK''s largest commercial maker of crumpets! The batter is extraordinarily easy to make, but cooking them may take practice to get the temperature right for your stove. But if you''ve nailed pancakes, you will nail crumpets!Double rising agent is the key here for the signature holes - baking powder PLUS yeast. Just one doesn''t cut it, and baking soda doesn''t work as well.It''s alarming how much time I''ve lost watching the bubbles pop...it''s mesmerising!!!', 'https://www.recipetineats.com/tachyon/2020/07/Crumpets-recipe_1.jpg', 5, 20, 25, 6, '[{"id": "ing_flour", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.2, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.033, "unit": "tub of 150g"}}, {"id": "ing_yeast", "quantity": {"value": 1.0, "unit": "pack of 5 sachets"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}]', '[{"ingredients":["150g (1 cup) white flour (, plain / all purpose)","200ml (3/4 cup + 1 tbsp) warm water (, tap water (200g) (Note 1))","1/2 tsp salt (, cooking/kosher salt (1/4 tsp table salt))","1/2 tsp white sugar","1 tsp baking powder"]},{"ingredients":["1 tsp yeast (, instant/rapid rise OR dry active yeast (Note 2))","1 tbsp warm water (just tap water)"],"purpose":"Yeast Mixture"},{"ingredients":["2 tbsp unsalted butter (, melted (or vegetable oil))"],"purpose":"Cooking:"}]', '[{"description":"Crumpet Batter:","images":[],"step":1},{"description":"Place flour, water and salt in a bowl and whisk for 2 minutes (electric beater 1 minute on speed 5).","duration":2,"images":[],"step":2},{"title":"Yeast Mixture","description":"Dissolve Yeast into 1 tbsp warm water in a small bowl.","images":[],"step":3},{"description":"Add Yeast Mixture, sugar and baking powder into bowl, then whisk for 30 seconds (or 15 sec speed 5).","duration":0.5,"images":[],"step":4},{"description":"Cover with cling wrap or plate, then place in a very warm place for 15 to 30 minutes until the surface gets nice and foamy. It will only increase in volume by ~10 - 15%.","duration":22.5,"images":[],"step":5},{"description":"Cooking Crumpets:","images":[],"step":6},{"description":"Grease 2 or 3 rings with butter (approx 9 cm / 3.5\" wide, though any ring or metal shaper will do, Note 3) (TIP: Non stick rings - brush with melted butter. Everything else - smear with butter)","images":[],"step":7},{"description":"Brush non stick skillet lightly with melted butter then place rings in the skillet.","images":[],"step":8},{"description":"Turn stove on medium high (medium for strong stoves) and bring to heat (Note 4 for \"sizzle test\").","images":[],"step":9},{"description":"Pour 1/4 cup batter into the rings (65ml), about 1cm / 2/5\" deep (will rise ~60%).","images":[],"step":10},{"title":"Cook for 1 1/2 minutes","description":"bubbles should start appearing on the surface (but not popping yet).","images":[],"step":11},{"title":"Turn heat down to medium, cook for 1 minute","description":"some bubbles should pop around the edges.","duration":1,"images":[],"step":12},{"description":"Turn heat down to medium low, cook for a further 2 1/2 to 4 minutes, until the surface is \"set\" and it''s clear there will be no more bubbles popping! (At this stage you can help the final bubbles pop with a skewer!)","images":[],"step":13},{"description":"Remove rings (you might need to run knife around to loosen).","images":[],"step":14},{"description":"Then flip and cook the other side for 20 to 30 seconds for a blush of colour.","duration":0.4166666666666667,"images":[],"step":15},{"description":"Transfer to write rack (golden side down) and fully cool.","images":[],"step":16},{"description":"Can be eaten once cool, but it''s even better the next day (Note 5).","images":[],"step":17},{"description":"How to eat crumpets:","images":[],"step":18},{"description":"Toast in a toaster until the base is crispy.","images":[],"step":19},{"description":"Slather generously with butter, then spread of choice (honey is perfection) and devour immediately!","images":[],"step":20}]', '["gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["breakfast"],"cuisine":["British","UK","Western"],"categories":["baking-recipes","breads","breakfast-recipes","vegan-lifestyle"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_18cdc0d1bdb1', 'en', 'US', 'Byron Bay Chocolate Chip Cookies', 'Recipe video above. This is a copycat of Australia''s most famous Chocolate Chip Cookies - the Byron Bay Milk Choc Chunk Cookies! Just like the real deal, these are big, crunchy, buttery and loaded with a generous amount of chocolate. See reader feedback on the White Chocolate Macadamia which uses the same cookie dough! Good quality milk chocolate for baking is hard to come by, so we''re using dark chocolate here - but if anything, it intensifies the chocolate experience!Cookie emergency? No beater? No worries! Make these fast & easy Chocolate Chip Cookies instead (they''re soft and chewy, no chill time).', 'https://www.recipetineats.com/tachyon/2020/06/Byron-Bay-Chocolate-Chip-Cookies_8.jpg', 20, 25, 45, 12, '[{"id": "ing_butter", "quantity": {"value": 175.0, "unit": "block of 250g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.2, "unit": "bottle of 50ml"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.017, "unit": "tub of 150g"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_chocolate", "quantity": {"value": 200.0, "unit": "block of 100g"}}]', '[{"ingredients":["175g / 12 1/2 tbsp unsalted butter (, softened (6.2 oz, Note 1 - softening tip!))","1/3 cup brown sugar (light or normal, not dark)","1/3 cup white sugar (, caster / superfine)","1/8 tsp salt","2 egg yolks (, at room temperature (Note 6 for using leftover whites))","2 tsp vanilla extract/essence","1/2 tsp baking powder","1/2 cup rice flour (sub with plain/all purpose flour, Note 2)","1 1/2 cups flour (, plain/all purpose)","200g / 7 oz dark or semi-sweet chocolate block (, chopped into pretty small pieces (Note 3))"]}]', '[{"description":"Place butter, salt and both sugars in a bowl. Beat on speed 5 for 1 minute until it''s soft, creamy and fluffy.","duration":1,"images":[],"step":1},{"title":"Add yolks and vanilla","description":"beat for 1 minute until well incorporated.","duration":1,"images":[],"step":2},{"description":"Add baking powder, rice flour and half the plain flour. Beat until you can''t see flour anymore, then add remaining flour and beat again until incorporated.","images":[],"step":3},{"description":"Mixture will be fairly clump and thick, but if you press between your fingers, it should stick together (rather than being dry and crumbly).","images":[],"step":4},{"description":"Use a wooden spoon to stir chocolate through.","images":[],"step":5},{"description":"Tip out onto a work surface then press together into a 22cm / 9\" log. Wrap in cling wrap or paper, twisting to seal the ends.","images":[],"step":6},{"title":"Refrigerate 1.5","description":"2 hours (Note 4).","images":[],"step":7},{"description":"Preheat oven to 200°C/390°F (180°C fan).","images":[],"step":8},{"description":"Line 2 trays with baking/parchment paper. Put one shelf in the middle of the oven, and the other underneath.","images":[],"step":9},{"description":"Remove from fridge, unwrap.","images":[],"step":10},{"description":"Use a serrated knife to slice into 1.75cm / 2/3\" thick slices. Saw carefully through choc chunks. If it falls apart on edges, just press if back together, no big deal. Place 6 on each tray.","images":[],"step":11},{"description":"Bake 10 minutes. Turn oven down to 170°C/340°F (150°C fan), switch trays (Note 5)","images":[],"step":12},{"description":"Bake for a further 15 minutes until surface is light golden and edges are a bit golden.","images":[],"step":13},{"title":"Remove from oven and cool completely on trays","description":"this makes them crunchy.","images":[],"step":14},{"title":"STORAGE","description":"Keeps for at least 2 weeks in an airtight container - they stay 100% crunchy, just like they''re freshly made.","images":[],"step":15}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Australia","Western"],"categories":["baking-recipes","cookies","dessert-recipes","egg-yolk-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a99c1e66bcb6', 'en', 'US', 'Sandwich Bread WITHOUT Yeast! (Dead easy)', 'Recipe video above. This is a bread loaf made without yeast or any other non-standard pantry ingredients. It''s as close as you will get to real bread made with yeast! It has a proper crumb like real bread and it''s sliceable, rather than being "muffin-like" which many no-yeast breads are. Loosely based on Damper, a traditional Australian bread historically made by swagmen and drovers over campfire (except I''ve brought it into the 21st century!) Toggle for METRIC (weights).', 'https://www.recipetineats.com/tachyon/2020/05/No-Yeast-Sandwhich-Bread_9-1.jpg', 5, 50, 55, 16, '[{"id": "ing_flour", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.267, "unit": "tub of 150g"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.562, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 37.5, "unit": "bottle"}}]', '[{"ingredients":["4 cups flour (, plain/all purpose (Note 1))","8 tsp baking powder (Note 2)","3 tsp white sugar","1 1/2 tsp cooking / kosher salt (REDUCE to 1 tsp if using table salt, Note 3)","2 1/4 cups milk (, warmed (any - Note 4))","1/4 cup oil (, any plain (vegetable, canola, sunflower, rapeseed, grapeseed, light olive oil))"]}]', '[{"description":"Preheat oven to 220°C/430°F (200°C fan).","images":[],"step":1},{"description":"Grease a 22 x 13 cm / 9 x 5\" loaf pan, then line with parchment/baking paper with overhang (to lift out).","images":[],"step":2},{"title":"Mix dry","description":"Place flour, baking powder, salt and sugar in a bowl, mix to combine.","images":[],"step":3},{"title":"Add wet","description":"Make a well in the centre, pour in oil and milk. Mix until flour is fully incorporated - batter will be thick but stirrable.","images":[],"step":4},{"title":"Fill pan","description":"Scrape into loaf pan, using a rubber spatula to scrape the bowl clean and smooth the surface.","images":[],"step":5},{"description":"Bake 30 minutes. Remove from oven, cover with foil.","images":[],"step":6},{"description":"Return to oven. Turn oven DOWN to 200°C/390°F (180°C fan), bake 20 minutes.","images":[],"step":7},{"description":"Remove from oven. Cool in pan 5 minutes, then use excess paper to lift out and transfer to cooling rack.","images":[],"step":8},{"title":"Cool completely before slicing","description":"45 minutes+. It IS more delicate than yeast breads (can''t change science!) but slices far better than the usual \"cake like\" no yeast breads. Slices perfectly on Day 2 and beyond.","images":[],"step":9},{"description":"Use for sandwiches, toast, grilled cheese, french toast, bread and butter pudding - anything you use \"real\" sandwich bread for!","images":[],"step":10}]', '["gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Australian","Western"],"categories":["baking-recipes","breads","quick-and-easy","quick-bread"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cb9d2c5b3d98', 'en', 'US', 'Chocolate Cake', 'Recipe VIDEO above. This is the everyday Chocolate Cake I make over and over again. The crumb is tender and moist, it truly tastes of chocolate (rarer than you might think!) and you only need one bowl and a whisk. It''s the famous Hershey''s "Perfectly Chocolate" Cake , one of the few recipes I''ve used from another source with no changes to the ingredients at all (yes it''s Perfect!)', 'https://www.recipetineats.com/tachyon/2018/03/Chocolate-Cake_2.jpg', 10, 35, 45, 8, '[{"id": "ing_flour", "quantity": {"value": 0.263, "unit": "kg"}}, {"id": "ing_cocoa_powder", "quantity": {"value": 0.45, "unit": "pack of 250g"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.05, "unit": "tub of 150g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.037, "unit": "tub of 200g"}}, {"id": "ing_sugar", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.2, "unit": "bottle of 50ml"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_chocolate", "quantity": {"value": 1.5, "unit": "block of 100g"}}]', '[{"ingredients":["1 3/4 cups plain / all purpose flour","3/4 cup cocoa powder (, unsweetened (Note 2))","1 1/2 tsp baking powder","1 1/2 tsp baking soda (bi-carb soda)","2 cups white sugar (Note 1)","1 tsp salt","2 eggs (~55-65g / 2 oz each)","1 cup milk (low or full fat)","1/2 cup vegetable oil (or canola)","2 tsp vanilla extract","1 cup boiling water"]},{"ingredients":["1 1/2 batches Chocolate Buttercream Frosting (slide scaler on recipe)"],"purpose":"Chocolate Buttercream Frosting"}]', '[{"description":"Preheat oven to 180C°/350°F (160°C fan). Read Note 4 regarding shelf positions.","images":[],"step":1},{"description":"Grease 2 x 22cm/9\" cake pans with butter, then line the base. (Note 3 re: springform pans and other pan sizes).","images":[],"step":2},{"description":"Sift flour, cocoa, baking powder and baking soda into a large bowl. Add Sugar and salt. Whisk briefly to combine.","images":[],"step":3},{"description":"Add eggs, milk, oil and vanilla. Whisk well to combine until lump free - about 30 seconds.","images":[],"step":4},{"description":"Add boiling water and whisk to incorporate. The batter is VERY thin (see video).","images":[],"step":5},{"description":"Pour batter into cake pans.","images":[],"step":6},{"description":"Bake for 35 minutes or until a wooden skewer inserted into the centre comes out clean. See Note 4 regarding cook time if pans are on different shelves.","duration":35,"images":[],"step":7},{"description":"Cool for 10 minutes, then turn out onto wire racks upside down (Note 5).","duration":10,"images":[],"step":8},{"description":"Cool completely before frosting. I frosted the cake with my Chocolate Buttercream Frosting (scale recipe up by 50%).","images":[],"step":9}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["baking-recipes","classic-cakes","dessert-recipes","easter-baking-desserts","nagis-picks","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_28591311c24f', 'en', 'US', 'World''s Easiest Yeast Bread recipe - Artisan, NO KNEAD', 'Recipe video above. This super crusty homemade bread recipe is going to blow your mind! The world’s easiest yeast bread that’s just like the very best artisan bread you pay top dollar for, with an incredible crispy, chewy crust, and big fat holes like sourdough. Recipe is forgiving so don’t fret if things don’t go perfectly, it will be salvageable. SEE NOTES for options like no dutch oven, different yeast, MAKE AHEAD up to 3 days! And tomorrow, make the Cheese Bread version!', 'https://www.recipetineats.com/tachyon/2020/03/No-Knead-Easy-Yeast-Bread-recipe.jpg', 5, 40, 45, 10, '[{"id": "ing_flour", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_yeast", "quantity": {"value": 2.0, "unit": "pack of 5 sachets"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 0.45, "unit": "kg"}}]', '[{"ingredients":["3 cups (450g) flour (, bread or plain/all purpose (Note 1))","2 tsp instant or rapid rise yeast (Note 2 for normal / active dry yeast)","1 1/2 tsp cooking salt / kosher salt (, HALVE if using table salt (Note 3))","1 1/2 cups (375 ml) very warm tap water (, NOT boiling or super hot (ie up to 55°C/130°F) (Note 4))"]},{"ingredients":["1 1/2 tbsp flour (, for dusting)"],"purpose":"Dough shaping"}]', '[{"title":"Mix Dough","description":"Mix flour, yeast and salt in a large bowl. Add water, then use the handle of a wooden spoon to mix until all the flour is incorporated. Dough will be wet and sloppy – not kneadable, but not runny like cake batter. Adjust with more water or flour if needed for right consistency (see video at 17 sec, Note 5).","images":[],"step":1},{"title":"Rise","description":"Cover with cling wrap or plate, leave on counter for 2 - 3 hours until it doubles in volume, it’s wobbly like jelly and the top is bubbly (see video at 24 seconds). If after 1 hour it doesn’t seem to be rising, move it somewhere warmer (Note 6).","images":[],"step":2},{"title":"Optional","description":"refrigerate for flavour development (Note 9): At this stage, you can either bake immediately (move onto Step 5) or refrigerate for up to 3 days.","images":[],"step":3},{"title":"Take chill out of refrigerated dough","description":"if you refrigerated dough per above, leave the bowl on the counter for 45 - 60 minutes while the oven is preheating. Cold dough does not rise as well.","duration":52.5,"images":[],"step":4},{"title":"Preheat oven (Note 7)","description":"Put dutch oven in oven with lid on (26cm/10\" or larger). Preheat to 230°C/450°F (220° fan) 30 minutes prior to baking. (Note 8 for no dutch oven)","images":[],"step":5},{"title":"Shape dough","description":"Sprinkle work surface with 1 tbsp flour, scrape dough out of bowl. Sprinkle top with 1/2 tbsp flour.","images":[],"step":6},{"description":"Using a dough scraper or anything of similar shape (cake server, large knife, spatula), fold the sides inwards (about 6 folds) to roughly form a roundish shape. Don’t be too meticulous here – you’re about to deform it, it’s more about deflating the bubbles in the dough and forming a shape you can move.","images":[],"step":7},{"title":"Transfer to paper","description":"Slide a large piece of parchment/baking paper (not wax paper) next to the dough, then flip the dough upside down onto the paper (ie seam side down, smooth side up). Slide/push it towards the middle, then reshape it into a round(ish) shape. Don''t get too hung up about shape. In fact, lopsided = more ridges = more crunchy bits!","images":[],"step":8},{"title":"Dough in pot","description":"Remove piping hot dutch oven from oven. Use paper to place dough into pot, place lid on.","images":[],"step":9},{"description":"Bake 30 minutes covered, then 12 minutes uncovered or until deep golden and crispy.","images":[],"step":10},{"description":"Cool on rack for 10 minutes before slicing.","duration":10,"images":[],"step":11}]', '["gluten"]', '["low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["baking-recipes","breads","coronavirus-food","emergency-recipes","good-to-know"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f66760ef89e3', 'en', 'US', 'Easy Chocolate Brownies', 'Recipe video above. These are my "go to" brownies, the one I have been making for years that''s super easy and outrageously chocolatey. The best fudgey chocolatey brownies made without fuss, in one bowl in 10 minutes. These are not the cakey kind, they''re soft fudgey kind. Super rich and moist!', 'https://www.recipetineats.com/tachyon/2016/08/Brownies_0.jpg', 10, 25, 35, 9, '[{"id": "ing_butter", "quantity": {"value": 200.0, "unit": "block of 250g"}}, {"id": "ing_chocolate", "quantity": {"value": 200.0, "unit": "block of 100g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_cocoa_powder", "quantity": {"value": 0.15, "unit": "pack of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chocolate", "quantity": {"value": 200.0, "unit": "block of 100g"}}, {"id": "ing_walnuts", "quantity": {"value": 225.0, "unit": "jar"}}]', '[{"ingredients":["200g / 14 tbsp unsalted butter (1 3/4 US sticks)","200 g / 1 1/4 cups dark chocolate chips (7 oz) (Note 1)","1 cup (175g) brown sugar (, loosely packed )","3 eggs (, lightly beaten)","1 tsp vanilla extract","1/2 cup (75g) plain flour","1/4 cup (30g) cocoa powder","Pinch of salt","180g/6oz dark chocolate block/bar (optional)"]},{"ingredients":["1.5 cups roughly chopped walnuts (or other nuts)"],"purpose":"Alternative stir in"}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan forced).","images":[],"step":1},{"description":"Spray a 20cm/8\" square tin with oil and line with baking/parchment paper with overhang (Note 2).","images":[],"step":2},{"description":"Place butter and chocolate chips in a heatproof bowl, microwave in 30 second bursts (takes me 1m 30 sec) until melted. Stir until smooth.","images":[],"step":3},{"description":"Add sugar and vanilla, mix, then add eggs and mix well until smooth and molten.","images":[],"step":4},{"description":"Add flour, cocoa and salt and stir until smooth. Stir in chopped chocolate, pour into pan.","images":[],"step":5},{"description":"Bake 24 minutes for really gooey in the centre, 28 minutes for fudgey but still very moist (my favourie, shown in video & photos), 32 minutes for moist fudge-cake-like. (See in post for toothpick testphotos).","images":[],"step":6},{"description":"If you didn''t use the extra chocolate for stirring in, reduce cook time by 2 minutes.","images":[],"step":7},{"description":"Rest for 10 minutes before lifting out of the pan. Allow to cool for at least 20 minutes before cutting. Store in an airtight container for 4 days (bet they don''t last that long!) or freeze for 3 months.","duration":10,"images":[],"step":8}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["South Western"],"categories":["baking-recipes","dessert-recipes","quick-and-easy","slices-bars"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_fb60fb2a72fe', 'en', 'US', 'World''s Best No Yeast Bread - Irish Soda Bread!', 'RECIPE VIDEO ABOVE. The world''s best bread made without yeast! Rustic, hearty bread made using baking soda for rise instead of yeast but still has an aerated, chewy crumb like normal bread. No rise time! Traditional Irish recipe - no egg or butter, it''s better without (read in post). use a combination of white and whole wheat flour for best flavour.', 'https://www.recipetineats.com/tachyon/2019/03/Irish-Soda-Bread_No-Yeast-Bread_3.jpg', 5, 40, 45, 12, '[{"id": "ing_flour", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.037, "unit": "tub of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}]', '[{"ingredients":["2 cups white flour (plain / all purpose)","1 3/4 cups wholemeal flour (wholewheat, Note 1)","2 - 3 tbsp Extra Flour (either flour, for dusting)","1 1/2 tsp baking soda (bi-carb, Note 2)","1 1/2 tsp salt","2 cups buttermilk (, fridge cold (Note 3))"]}]', '[{"description":"Preheat oven to 220°C/430°F (200°C fan).","images":[],"step":1},{"description":"Line tray with baking paper.","images":[],"step":2},{"description":"Whisk both flours (not Extra Flour), baking soda and salt in a bowl.","images":[],"step":3},{"description":"Add buttermilk, stir until it''s too hard to stir anymore.","images":[],"step":4},{"description":"Sprinkle 2 tbsp Extra Flour onto work surface, scrape out dough, sprinkle with more flour.","images":[],"step":5},{"description":"Gently knead no more than 8 times, bring together into a ball. (Note 4)","images":[],"step":6},{"description":"Transfer to tray, pat into 2.5cm/1\" thick disc.","images":[],"step":7},{"description":"Cut cross on surface 1cm / 0.3\" deep using serrated knife.","images":[],"step":8},{"description":"Bake 20 minutes. Turn oven down to 200°C/390°F (180°C fan).","images":[],"step":9},{"description":"Bake further 20 minutes, or until the base sounds hollow when tapped in the middle.","images":[],"step":10},{"description":"Transfer to rack and cool for at least 30 minutes before slicing.","images":[],"step":11}]', '["gluten"]', '["low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Irish"],"categories":["baking-recipes","breads","coronavirus-food","dinner-tonight","quick-and-easy","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1024bc6cd0a5', 'en', 'US', 'Caramel Slice', 'Recipe video above. An easy Caramel Slice recipe that delivers as promised - a creamy caramel filling that sets perfectly (no more runny caramel!) and chooclate that doesn''t crack when you cut into it!', 'https://www.recipetineats.com/tachyon/2020/03/Caramel-Slice_2_SQ.jpg', 15, 40, 55, 12, '[{"id": "ing_flour", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_desiccated_coconut", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 125.0, "unit": "block of 250g"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_milk", "quantity": {"value": 0.395, "unit": "L"}}, {"id": "ing_chocolate", "quantity": {"value": 200.0, "unit": "block of 100g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}]', '[{"ingredients":["1 cup flour, (plain/all purpose)","1/2 cup brown sugar (, loosely packed)","1/2 cup desiccated coconut (US: sweetened finely shredded coconut, Note 1)","125g / 4.5oz unsalted butter (, melted)"],"purpose":"Base"},{"ingredients":["125g / 4.5oz unsalted butter (, roughly chopped)","1/2 cup (80g) brown sugar (, loosely packed)","1 tsp vanilla extract (or essence)","395g / 14oz sweetened condensed milk (1 can, 300ml) (Note 1b)"],"purpose":"Caramel filling"},{"ingredients":["200g / 7oz dark or milk melting chocolate (US: semi-sweet chocolate chips)","1 tbsp vegetable oil"],"purpose":"Chocolate Topping"}]', '[{"description":"Preheat oven to 180°C/350°F (fan 160°C)","images":[],"step":1},{"description":"Grease and line a 28x 18cm (lamington pan) / 7\" x 11\" rectangle pan with baking/parchment paper (Note 2). Have overhang for ease of removal.","images":[],"step":2},{"description":"Mix together Base ingredients and press into a pan (I use an egg flip)","images":[],"step":3},{"description":"Bake for 15 minutes until the surface is golden. Cool in fridge if you have time (Note 3).","duration":15,"images":[],"step":4},{"description":"Lower oven to oven to 160°C/320°F (fan 140°C)","images":[],"step":5},{"description":"Place butter, sugar and vanilla in a saucepan over medium low heat. When the butter is melted, whisk to combine with sugar, then just leave it until it comes to a simmer.","images":[],"step":6},{"description":"When bubbles appear, add condensed milk. Whisk constantly for 5 minutes (Note 4), until you start getting some big slow bubbles on the base.","duration":5,"images":[],"step":7},{"description":"Once bubbles start appearing, whisk for 1 minute, then pour onto Base. Tilt pan to spread evenly.","duration":1,"images":[],"step":8},{"description":"Bake for 12 minutes. Don''t worry if you get splotchy brown bits (this happens with ovens that don''t distribute heat evenly).","duration":12,"images":[],"step":9},{"description":"Cool on counter for 20 minutes then refrigerate 30 minutes - bottom of pan should be warm but surface cool (not cold) to touch. (Note 5)","duration":20,"images":[],"step":10},{"description":"Place chocolate and oil in a microwave proof bowl. Microwave in 30 second bursts, stirring in between, until chocolate is fully melted (takes me 4 x 30 sec).","images":[],"step":11},{"description":"Pour over caramel, spread with spatula. Then gently shake pan to make the surface completely flat.","images":[],"step":12},{"description":"Refrigerate 1 hour or until set. Remove from fridge and leave out for 5 minutes to take chill out of chocolate slightly. Then cut into bars or squares to serve!","duration":5,"images":[],"step":13}]', '["gluten","milk"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":["Australian","Western"],"categories":["baking-recipes","dessert-recipes","most-popular","slices-bars"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a5a370e1db42', 'en', 'US', 'Carrot Cake (Easy and ultra moist!)', 'Recipe video above. A fabulously easy, moist Carrot Cake with lots of fluffy cream cheese frosting! Perfect flavour and texture, with a hint of cinnamon, subtle soft crunch from walnuts and coconut, extra flavour and moisture from crushed pinapple. A reader recipe that has become my go-to Carrot Cake recipe!', 'https://www.recipetineats.com/tachyon/2016/04/Carrot-Cake_4.jpg', 30, 30, 45, 12, '[{"id": "ing_pineapple", "quantity": {"value": 440.0, "unit": "unit"}}, {"id": "ing_pineapple", "quantity": {"value": 440.0, "unit": "unit"}}, {"id": "ing_milk", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.05, "unit": "tub of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_carrot", "quantity": {"value": 300.0, "unit": "pack of 1kg"}}, {"id": "ing_coconut", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_walnuts", "quantity": {"value": 75.0, "unit": "jar"}}, {"id": "ing_cream_cheese", "quantity": {"value": 180.0, "unit": "block of 250g"}}, {"id": "ing_butter", "quantity": {"value": 225.0, "unit": "block of 250g"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.225, "unit": "kg"}}]', '[{"ingredients":["440g / 20 oz can crushed pineapple (, drained but RESERVE juice (Note 1))","1/4 cup (65 ml) reserved canned pineapple juice (from canned pineapple above)"]},{"ingredients":["3/4 cup (185 ml) milk (, at room temperature (full or low fat) )","1 tsp white vinegar (or lemon juice or other clear vinegar, (Note 2)","3 eggs (55g/2oz each)","1 1/2 cups (265g) brown sugar (loosely packed)","1/2 cup (125 ml) vegetable oil (or canola)"],"purpose":"Wet Ingredients"},{"ingredients":["2 cups (300g) flour (, plain / all purpose)","2 tsp baking soda (aka bi carb soda, Note 3) (NOT BAKING POWDER)","1/2 tsp salt","2 tsp cinnamon powder"],"purpose":"Dry Ingredients"},{"ingredients":["2 cups grated carrot (, about 2 carrots, peeled (Note 4))","1/4 cup coconut (, shredded or desiccated (plain / unsweetened))","1/2 cup walnuts or pecans (, roughly chopped)"],"purpose":"Stir Ins"},{"ingredients":["180g / 6oz cream cheese (, at room temperature (Note 5))","225g / 1 cup unsalted butter (, softened)","1 tsp vanilla extract","4 cups (480g) icing sugar / powdered sugar (, sifted if clumpy (Note 6))"],"purpose":"Frosting"}]', '[{"description":"Preheat oven to 180°C/350°F (all oven types). Grease and line two 20-22.5 cm/8 - 9\" round pans OR a 9 x 13\" / 22 x 33cm pan with baking/parchment paper. (Note 7)","images":[],"step":1},{"description":"Drain crushed pineapple well, reserving the juice. Measure out 1/4 cup of pineapple juice.","images":[],"step":2},{"description":"Whisk Dry ingredients in a large bowl.","images":[],"step":3},{"description":"In a separate bowl, whisk together the milk, vinegar, eggs, sugar, oil and the 1/4 cup pinepple juice from Step 2.","images":[],"step":4},{"description":"Stir in carrot, crushed pineapple, coconut and pecans into the Wet ingredients bowl.","images":[],"step":5},{"description":"Pour Wet into Dry ingredients, stir until flour is incorporated.","images":[],"step":6},{"description":"Pour into prepared pan(s). Bake round cakes for 35 minutes, rectangle cake for 40 minutes, or until a skewer inserted into the middle comes out clean and the cake is golden on top.","duration":35,"images":[],"step":7},{"description":"Rest for 10 minutes in the pan before turning out onto a cooling rack. Frost once completely cool.","duration":10,"images":[],"step":8},{"description":"Cream Cheese Frosting","images":[],"step":9},{"description":"Beat together cream cheese, butter and vanilla until smooth. Then beat in the icing sugar in 2 batches until it is well incorporated and the frosting is fluffy - about 3 minutes on speed 7 stand mixer.","images":[],"step":10},{"description":"Flip one cake upside down on serving platter (for flat surface). Spread with 1/3 frosting. Place 2nd cake upside down on frosting. Frost top and sides with remaining frosting.","images":[],"step":11},{"description":"If cooler than 25°C/77°C and not humid, ok to keep cake in airtight container not in fridge. If very humid OR warmer than 25°C/77°C, store in fridge (Note 8).","images":[],"step":12}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","classic-cakes","dessert-recipes","easter-baking-desserts","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a189b5803a06', 'en', 'US', 'Icing for Biscuits (Royal Icing)', 'Recipe video above. Known as Royal Icing, this is an icing that''s made for decorating any biscuits and cookies, like the Christmas Cookies shown in the photos. It sets hard, has a lovely glossy sheen that''s like the cookies you get from gourmet stores and the best patisseries about town. RAW EGG?? Don''t worry! The egg is not raw. It is "cooked" by the sugar. Essentially cured actually, in the same way that salt + sugar is used to cure things like salmon (like my Beetroot Cured Salmon and Gravlax).Bonus: I''m also sharing my cheeky SHORTCUT method to ice the entire surface of the cookie without using a piping bag!', 'https://www.recipetineats.com/tachyon/2019/12/Christmas-Cookies-Sugar-Cookies_6.jpg', 15, 0, 15, 60, '[{"id": "ing_sugar", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 3.125, "unit": "carton of 12"}}, {"id": "ing_corn", "quantity": {"value": 0.075, "unit": "can of 400g"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_food_dye_liquid_or_gel", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["500g / 1 lb PURE icing sugar / powdered sugar (, sifted (plus extra for adjusting) (Note 1))","1/4 cup egg whites (~3 eggs) (Note 2)","2 tbsp corn syrup (or 1.5 tbsp glucose syrup, Note 3)","1 - 1 1/2 tbsp water (, plus more as needed)"],"purpose":"Icing:"},{"ingredients":["Food Dye - liquid or gel (, go by eye for quantity (Note 4))"],"purpose":"Colouring:"}]', '[{"description":"Place Icing ingredients in a large bowl, starting with 1 tablespoon water, and beat for 1 minute on speed 5 until smooth and glossy (start on low then speed up).","duration":1,"images":[],"step":1},{"description":"Divide icing into different bowls for colouring. Add food dye and mix - keep adding colouring until you achieve the colour you are after. If icing gets too thin, add more icing sugar.","images":[],"step":2},{"title":"Icing consistency test","description":"Should be able to draw a figure 8 on the surface and you can see if for 2 seconds before sinking in and disappearing. Should be thick enough to pipe details but thin enough to spread smoothly on surface of cookie. ADJUST icing - thinner with water (1/2 tsp at a time), thicker with more icing sugar.","duration":0.03333333333333333,"images":[],"step":3},{"description":"Transfer icing into disposable piping bags or ziplock bags.","images":[],"step":4},{"description":"Snip the TINIEST bit off the corner. Smaller hole = better detail in icing. Remember: You can cut hole bigger, but not smaller! OR using very thin piping nozzle.","images":[],"step":5},{"description":"Pipe decorations on cookies as desired.","images":[],"step":6},{"description":"Decorate with sprinkles etc while wet (so they stick). Or dry completely before piping on details.","images":[],"step":7},{"description":"To fill a large surface, use toothpick to spread.","images":[],"step":8},{"description":"QUICK METHOD to ice biscuits (see video demo):","images":[],"step":9},{"description":"Place skewer on edge of frosting bowl.","images":[],"step":10},{"description":"Hold edge of cookie with two fingers, then carefully dip face of cookie into frosting.","images":[],"step":11},{"description":"Pull out of frosting then lightly scrape surface across skewer to remove excess.","images":[],"step":12},{"description":"Decorate with sprinkles etc while wet (so they stick). Or dry completely before piping on details.","images":[],"step":13}]', '["egg"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","cookies","dessert-recipes","egg-white-recipes","frosting-and-icing"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_595efa6cb1d3', 'en', 'US', 'Moist Blueberry Muffins', 'Recipe video above. Buttermilk, both baking powder AND bicarb are the secret to really soft, fluffy muffins. Simpler muffin recipes are more dense and drier, though you can make a brown sugar muffin batter that''s just as soft without buttermilk - use this Brown Sugar Apple Muffins recipe. (Note: the crumb colour is not as white as this muffin because of the brown sugar)KEY TIP: Do not over mix the batter, a few lumps is ok! Overmixing = tough muffins.', 'https://www.recipetineats.com/tachyon/2016/10/Blueberry-Muffins_4.jpg', 10, 20, 30, 12, '[{"id": "ing_flour", "quantity": {"value": 0.375, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.1, "unit": "tub of 150g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.025, "unit": "tub of 200g"}}, {"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.2, "unit": "bottle of 50ml"}}, {"id": "ing_blueberries", "quantity": {"value": 2.0, "unit": "punnet of 125g"}}]', '[{"ingredients":["2 1/2 cups plain flour (all purpose flour)","3 tsp baking powder","1 tsp baking soda / bi carb soda (sub extra 3 tsp baking powder)","1 cup white sugar (caster, granulated or superfine)","1/4 tsp salt"],"purpose":"Dry Ingredients"},{"ingredients":["1 cup buttermilk (Note 1)","60g / 4 tbsp butter (, unsalted, melted)","4 tbsp vegetable oil","2 large eggs (, at room temperature, lightly whisked (Note 2))","2 tsp vanilla extract"],"purpose":"Wet Ingredients"},{"ingredients":["250g / 8 oz blueberries (, fresh (~2 cups, Note 3))"],"purpose":"Blueberries"}]', '[{"description":"Preheat oven to 200°C/390°F (all oven types) (Note 4). Line a 12 hole muffin tin with paper patties.","images":[],"step":1},{"title":"Whisk Dry","description":"Whisk flour, baking powder, baking soda, sugar and salt in a bowl.","images":[],"step":2},{"title":"Whisk Wet","description":"In a separate bowl, whisk buttermilk, melted butter, oil, eggs and vanilla.","images":[],"step":3},{"title":"Combine Wet & Dry","description":"Make a well in the flour bowl, pour in egg mixture. Mix until just combine - try not to stir more than 8 times. Some flour lumps in the batter is fine.","images":[],"step":4},{"title":"Add blueberries","description":"Stir through most of the blueberries - reserve some for topping.","images":[],"step":5},{"title":"Fill muffin tin","description":"Divide batter between paper cases. Top with remaining blueberries.","images":[],"step":6},{"title":"Bake 1","description":"Bake for 5 minutes, then turn oven down to 180°C/350°F.","duration":5,"images":[],"step":7},{"title":"Bake 2","description":"Bake for a further 13 minutes (fan) or 15 minutes (standard ovens), or until a skewer inserted into the muffin comes out clean.","images":[],"step":8},{"title":"Cool","description":"Remove muffins from the muffin tin immediately onto a cooling rack. Serve warm or at room temperature (warm is extra yum!)","images":[],"step":9}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","blueberries","cupcakes-and-muffins","dessert-recipes","easter-brunch-recipes","muffin-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_94476c964803', 'en', 'US', 'Pumpkin Pie', 'Recipe video above. The perfect Pumpkin Pie that''s soft custardy rather than lumpy and curdled. Perfect level of spicing - you can taste it but it doesn''t overwhelm the natural pumpkin flavour - sweet but not crazy sweet. And NO CRACKS on the surface!', 'https://www.recipetineats.com/tachyon/2019/11/Pumpkin-Pie_2.jpg', 15, 45, 60, 12, '[{"id": "ing_homemade_pie_crust_or", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_22_5cm_crust", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_pumpkin", "quantity": {"value": 0.263, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_cinnamon", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_round_clove", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_pinch_nutmeg", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_cream", "quantity": {"value": 1.333, "unit": "carton of 250ml"}}, {"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}]', '[{"ingredients":["1 homemade pie crust OR","1 9\"/22.5cm store bought crust"]},{"ingredients":["1 3/4 cups pumpkin puree (, from 15 oz/425g can or homemade puree (Note 1))","2/3 cup (145g) sugar, white/granulated","1/2 tsp salt","2 tsp cinnamon","1 tsp ground ginger","1/4 tsp ground cloves","Pinch of nutmeg","1 1/3 cups (330 ml) cream, heavy / thickened (cold)","3 eggs"],"purpose":"Pumpkin Pie Filling:"}]', '[{"description":"If using homemade pie crust, blind bake it per the Pie Crust recipe and fill crust straight after removing from oven.","images":[],"step":1},{"description":"If using store bought, blind baking is not necessary (but if you want to, follow the Pie Crust recipe).","images":[],"step":2},{"description":"Preheat oven to 170°C / 335°F (150°C fan).","images":[],"step":3},{"description":"Place pumpkin, sugar, salt and spices into a saucepan over medium heat. Once you see steam, cook, stirring regularly, for 5 minutes (this removes excess moisture and lets spices bloom).","duration":5,"images":[],"step":4},{"description":"Remove from stove and scrape into a bowl. Add cream, whisk.","images":[],"step":5},{"description":"Whisk eggs in one by one, mixing just enough to incorporate. If you whisk vigorously for ages, it will aerate the mixture, leading to cracks.","images":[],"step":6},{"description":"Pour into Pie Crust, transfer to oven.","images":[],"step":7},{"title":"Bake 45","description":"55 minutes or until the centre is set but still has a slight jiggle and the toothpick inserted into the middle comes out clean but damp (if it still has pumpkin batter, keep cooking). (Note 2)","images":[],"step":8},{"description":"Cool completely for 4 hours+ before cutting to serve. Serve with cream and dusting of cinnamon or nutmeg if desired!","images":[],"step":9}]', '["egg","milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["American","Thanksgiving"],"categories":["baking-recipes","dessert-recipes","pumpkin","sweet-pies"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cde2be544cef', 'en', 'US', 'Pie Crust (Shortcrust Pastry)', 'Recipe video above. My go-to pie crust I''ve been loyal to for more years than I can remember, a classic pie crust also known as shortcrust pastry. Flaky and easy with a dough that comes together in 1 minute using a food processor, though you can just use your hands.Use for Sweet and savoury pies - Pecan Pie, Pumpkin Pie to the great Aussie Meat Pie!Makes pastry for 1 x 23cm / 9" pie dish or tart tin (serves 8 - 12 people). Double it for a covered pie (use recipe scaler). VIDEO and PROCESS PHOTOS above super helpful for newbies!', 'https://www.recipetineats.com/tachyon/2019/11/Pie-Crust.jpg', 15, 20, 110, 8, '[{"id": "ing_flour", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 115.0, "unit": "block of 250g"}}, {"id": "ing_water", "quantity": {"value": 0.037, "unit": "L"}}]', '[{"ingredients":["1 1/4 cups flour (plain / all purpose flour)","2 tsp white sugar (skip if making savoury pie)","1/2 tsp salt","115g / 8 tbsp unsalted butter (, cold, cut into 1cm/ 1/3\" cubes (Note 1))","2 1/2 tbsp ice cold water (+ more as required)"]}]', '[{"title":"Pulse Dry","description":"Place flour, sugar and salt in food processor. Pulse twice to combine.","images":[],"step":1},{"title":"Cut in butter","description":"Scatter butter across surface. Pulse 5 times until the largest pieces are the size of chickpeas.","images":[],"step":2},{"title":"Add chilled water","description":"With the motor running on low, pour 2.5 tbsp of water into the tube feeder.","images":[],"step":3},{"title":"Form crumbs","description":"Keep blitzing for 10 seconds until crumbs form (also see video). Pinch between fingers - they should stick and form a dough.","duration":0.16666666666666666,"images":[],"step":4},{"title":"HAND option","description":"Whisk flour, sugar and salt in large bowl. Rub butter into flour with tips of fingers until it resembles crumbs - it should look the same as using a food processor. Then mix in cold water with rubber spatula, then proceed with steps below.","images":[],"step":5},{"title":"Form disc","description":"Tip crumbs out onto work surface, bring together into dome (don''t knead), pat into 2cm/ 4/5\" thick disc.","images":[],"step":6},{"title":"Chill","description":"Wrap in clingwrap then refrigerate 1 hour (up to 2 days, otherwise freeze).","images":[],"step":7},{"title":"Dust with flour","description":"Sprinkle work surface with flour, unwrap dough and place on the flour. Sprinkle top with flour, dust rolling pin with flour.","images":[],"step":8},{"title":"Roll out","description":"Roll out into round that''s 10cm/4\" larger than 22.5cm/9\" pie tin. Patch up and roll over cracks as necessary","images":[],"step":9},{"title":"Transfer to pie dish","description":"Gently roll the pastry so it wraps around the rolling pin. Unroll it over the pie dish.","images":[],"step":10},{"description":"Drape pastry into pie tin (do not stretch/pull, causes shrinkage).","images":[],"step":11},{"title":"Trim","description":"If making a pie with NO LID (like Pumpkin Pie), then trim edges with scissors leaving a 1 cm / 2/5\" overhang. If making a pie with a lid (like a Meat Pie) then trim edges so they align with the edge of the pie tin (ie no excess overhang).","images":[],"step":12},{"description":"Tuck excess under, if appliable (ie per step above, if making a no lid pie). Then crimp or decorate edge as desired.","images":[],"step":13},{"title":"Refrigerate: Put pie crust in the freezer for 15","description":"30 minutes (while oven heats up). This helps prevent shrinkage, firms up the butter again (flakiness!) and helps to ensure decorative crimped edges remain in tact.","duration":22.5,"images":[],"step":14},{"title":"Baking options (Note 4)","description":"Blind bake the pie crust if it will be baked once filled (eg Meat Pie, Pumpkin Pie). Fully bake the pie crust if it will not be baked once filled.","images":[],"step":15},{"description":"Blind bake (par-bake, Note 4):","images":[],"step":16},{"description":"Preheat oven to 200°C/390°F (180°C fan).","images":[],"step":17},{"title":"Line & weigh down","description":"Place 2 large pieces of parchment/baking paper crosswise over the pastry, then fill with baking beads or lots of rice or dried beans to weigh it down. (Note 2)","images":[],"step":18},{"title":"Bake 1 covered","description":"Bake for 15 minutes, then remove from oven.","duration":15,"images":[],"step":19},{"title":"Bake 2 uncovered","description":"Use excess paper to CAREFULLY remove hot beads, then return to oven for 5 minutes or until base is light golden (doesn''t need to be 100% cooked though).","duration":5,"images":[],"step":20},{"title":"Cool","description":"Remove from oven. Cool 15 minutes in the pie tin before filling (another measure to avoid soggy base).","images":[],"step":21},{"description":"Fully baked option (Note 4):","images":[],"step":22},{"description":"Follow directions per Blind Baking steps above BUT bake at 190°C/375°F (170°C fan) covered with baking beads for 25 minutes, then 15 minutes uncovered until golden. Fully cool before filling.","duration":25,"images":[],"step":23},{"description":"Fill and bake per directions of chosen pie filling - such as Pumpkin Pie, Pecan Pie, Meat Pie. The par baked pastry will not be 100% cooked, it finishes cooking with the filling. It''s cooked enough so the crust will not go soggy.","images":[],"step":24}]', '["gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["baking-recipes","dessert-recipes","sweet-pies"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a668a5003e52', 'en', 'US', 'Lemonade Scones - 3 Ingredients From Scratch', 'Recipe video above. Moist and fluffy scones, made with only 3 ingredients! These are truly miracle. They must be served with copious amounts of cream and jam. That''s a given!', 'https://www.recipetineats.com/tachyon/2019/09/Lemonade-Scones_2.jpg', 10, 15, 25, 10, '[{"id": "ing_flour", "quantity": {"value": 0.525, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_lemon", "quantity": {"value": 0.3, "unit": "net of 500g"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_jam", "quantity": {"value": 0.003, "unit": "jar of 370g"}}]', '[{"ingredients":["3 1/2 cups self raising flour (, plus extra for dusting (flour sub - Note 1))","1 cup thickened cream ((heavy cream), not whipped!)","1 cup lemonade (Note 2)"]},{"ingredients":["Whipped cream","Jam"],"purpose":"To serve"}]', '[{"description":"Preheat oven to 200°C/390°F (180°C fan). Line tray with baking/parchment paper.","images":[],"step":1},{"description":"Combine the flour, cream and lemonade in a bowl and mix until flour is mostly combined. Do not over mix, it will make the scones dense! The dough should be soft and fairly sticky.","images":[],"step":2},{"description":"Turn out onto a floured surface, and knead gently just 3 - 5 times to bring dough together, then gently pat into a disc shape 2.5cm/1\" thick.","images":[],"step":3},{"title":"Use a 6cm/2.5\" round cutter to cut rounds","description":"press straight up and down (don''t twist), flour cutter in between. (Note 4)","images":[],"step":4},{"description":"Use a knife or similar to scoop up (avoid touching sides) and place on tray, slightly touching each other (they help each other rise).","images":[],"step":5},{"description":"Brush the tops lightly with milk. (Note 5)","images":[],"step":6},{"description":"Bake for 15 minutes until golden on top. Place on rack to cool. Place tea towel over them to stop the tops from getting crusty.","duration":15,"images":[],"step":7},{"description":"Serve with copious amounts of cream and jam, and of course tea!","images":[],"step":8}]', '["gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Australian","New Zealand","UK"],"categories":["baking-recipes","breakfast-recipes","dessert-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6876d3b416a8', 'en', 'US', 'Mediterranean Savoury Muffins', 'Recipe video above. Savoury Muffins are cheesy muffins studded with Mediterranean flavours! These stay moist and fresh for several days, making them ideal for gift, make ahead for for afternoon tea , a school fete, or a lunchbox filler idea.', 'https://www.recipetineats.com/tachyon/2019/09/Mediterranean-Savoury-Muffins_8.jpg', 15, 25, 40, 12, '[{"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_feta_cheese", "quantity": {"value": 75.0, "unit": "block of 200g"}}, {"id": "ing_olives", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_tomato", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 1.5, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.5, "unit": "bunch"}}, {"id": "ing_flour", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.05, "unit": "tub of 150g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.013, "unit": "tub of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.15, "unit": "tub of 250g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}]', '[{"ingredients":["Butter or oil spray (, for greasing)"]},{"ingredients":["2 cups (200g) cheddar cheese (, shredded (or other cheese))","75g / 2.5oz feta (, crumbled*)","1/2 cup green olives slices (*)","1/2 cup sun-dried tomatoes strips (*)","1/2 cup roasted peppers (*, drained and chopped (capsicum))","1/2 cup green onions (*, sliced )"],"purpose":"Add Ins:"},{"ingredients":["2 cups (300g) flour (plain / all purpose flour)","1 1/2 tsp baking powder","1/2 tsp baking soda (/ bi-carb soda (sub 1 1/2 tsp baking powder))","1/2 tsp salt"],"purpose":"Dry Ingredients:"},{"ingredients":["1 egg (large, about 60g / 2 oz)","1 cup (250 ml) milk (full or low fat)","1/4 cup (60g) sour cream (or plain yoghurt (Note 1))","1/4 cup (60ml) vegetable oil ( (or any plain flavoured oil))","1 garlic clove (, minced)"],"purpose":"Wet ingredients:"}]', '[{"description":"Preheat oven to 180°C/350°F (160°C/320°F fan).","images":[],"step":1},{"description":"Brush a 12 hole standard muffin tin generously with butter","images":[],"step":2},{"description":"Whisk Dry ingredients in a bowl.","images":[],"step":3},{"description":"Whisk Wet ingredients in a separate bowl.","images":[],"step":4},{"description":"Pour Wet into the Dry ingredients bowl. Mix 8 times.","images":[],"step":5},{"description":"Add cheese, feta, sun dried tomato, capsicum, olives and green onion. Mix as few times as possible just to incorporate remaining bits of flour - no more than 7 big stirs (secret to soft muffs).","images":[],"step":6},{"description":"Divide between 12 holes in muffin in (I use an ice cream scooper). Batter should be thick and fill muffin tin slightly mounded (see video)","images":[],"step":7},{"description":"Bake for 25 minutes or until the muffins are golden and crusty and spring back when touched in the centre.","duration":25,"images":[],"step":8},{"description":"Cool for 10 minutes, then transfer to cooling rack. Serve warm for optimum experience!","duration":10,"images":[],"step":9}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["snack"],"cuisine":["Western"],"categories":["baking-recipes","muffin-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_dacf75f3021a', 'en', 'US', 'Chocolate Zucchini Bread', 'Recipe video above. Zucchini? What zucchini? All I see is the most decadent, moist chocolate loaf you may ever have in your life!', 'https://www.recipetineats.com/tachyon/2019/06/Chocolate-Zucchini-Bread_2.jpg', 15, 65, 80, 10, '[{"id": "ing_zucchini", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.263, "unit": "kg"}}, {"id": "ing_cocoa_powder", "quantity": {"value": 0.2, "unit": "pack of 250g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.037, "unit": "tub of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_vanilla_essence", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_sugar", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_chocolate", "quantity": {"value": 300.0, "unit": "block of 100g"}}]', '[{"ingredients":["3 cups grated zucchini (2 large or 3 small) (Note 1)","1 3/4 cups (260g) flour, plain/all purpose","1/3 cup (40g) unsweetened cocoa powder, preferably dutch processed (Note 2)","1.5 tsp baking soda (bi-carbonate) (Note 3)","1/2 tsp salt","2 tsp vanilla essence","1 1/4 cup (275g) white sugar","2 eggs","100g / 7 tbsp unsalted butter (, melted)","300g / 10 oz dark chocolate (, coarsely chopped (keep some larger chunks!) (Note 4))"]}]', '[{"description":"Preheat oven to 180C/350F (160C fan).","images":[],"step":1},{"description":"Grease and line a large loaf pan (mine is 28 x 15 x 6.5cm / 11 x 6 x 2.5\").","images":[],"step":2},{"description":"Grab handfuls of zucchini and squeeze out excess liquid, then place in colander to drain while you prepare the batter. (Note 4)","images":[],"step":3},{"description":"In a large bowl, whisk together flour, cocoa, baking soda and salt.","images":[],"step":4},{"description":"In a separate bowl, whisk together eggs and sugar. Then add butter and vanilla, and whisk until fully incorporated.","images":[],"step":5},{"description":"Pour egg mixture into flour bowl and stir with wooden spoon until flour is just incorporated - batter will be thick!","images":[],"step":6},{"description":"Add zucchini and chocolate and stir to mix through - it will be very thick at first but it will loosen into a thick, spreadable batter (see video).","images":[],"step":7},{"description":"Scrape into loaf pan, bake 45 minutes. Cover with foil and bake a further 20 minutes or until skewer inserted into the centre comes out clean (except for melted chocolate streaks!)","images":[],"step":8},{"description":"Stand in loaf pan for 15 minutes before removing. Cool on rack for a further 10 minutes before slicing.","duration":15,"images":[],"step":9},{"title":"Extra amazing served warm","description":"you get melty chocolate bits and it''s extra fudgy in the middle!","images":[],"step":10}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","dessert-recipes","zucchini-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_49cf29baa69b', 'en', 'US', 'Outrageous Triple Chocolate Cookies', 'Recipe video above. Better than Byron Bay Triple Chocolate Fudge Cookies with 40% chocolate! Crispy on the edges and truly chewy on the inside (rather than just being sloppy raw cookie dough) thanks to a secret ingredient - glucose. And they live up to their name - these are outrageously rich!', 'https://www.recipetineats.com/tachyon/2019/06/Triple-Chocolate-Cookies_6.jpg', 15, 12, 27, 12, '[{"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.2, "unit": "bottle of 50ml"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_glucose", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_flour", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.017, "unit": "tub of 150g"}}, {"id": "ing_cocoa_powder", "quantity": {"value": 0.15, "unit": "pack of 250g"}}, {"id": "ing_chocolate", "quantity": {"value": 0.75, "unit": "block of 100g"}}, {"id": "ing_chocolate", "quantity": {"value": 0.75, "unit": "block of 100g"}}]', '[{"ingredients":["60g / 4 tbsp unsalted butter (, softened)","2/3 cups (120g) brown sugar (, tightly packed)","2 tsp vanilla extract","2 egg yolks (, at room temperature (Note 4 for using leftover whites))","2 tbsp glucose (sub light corn syrup, Note 1)","1 cup (150g) flour (, plain/all purpose)","1/2 tsp baking powder","1/4 cup (30g) cocoa powder (, unsweetened, preferably Dutch processed (Note 2))","3/4 cup (150g) white chocolate chips (Note 3)","1/2 cup (100g) dark chocolate chips (Note 3)"]}]', '[{"description":"Preheat oven to 190C/375F (170C fan) with one shelf in the middle and another under it.","images":[],"step":1},{"description":"Use a bowl at room temp, not ice cold glass/metal (butter will go hard).","images":[],"step":2},{"title":"Place butter in bowl and beat until smooth","description":"about 30 seconds on speed 5.","images":[],"step":3},{"description":"Add sugar and beat for 45 sec to 1 min until light and fluffy.","duration":0.75,"images":[],"step":4},{"description":"Add yolks, beat until fully incorporated (~20 sec).","images":[],"step":5},{"description":"Add vanilla and glucose, beat until incorporated (~15 sec).","images":[],"step":6},{"description":"Add flour, baking powder and cocoa. Stir with wooden spoon until incorporated (will be a stiff dough).","images":[],"step":7},{"description":"Mix through chocolate chips.","images":[],"step":8},{"description":"Scoop / roll 12 balls a touch smaller than a golf ball, then flatten to 1cm / 2/5\" thick on baking trays (2 trays).","images":[],"step":9},{"description":"Bake both trays for 10 minutes.","duration":10,"images":[],"step":10},{"description":"Take top tray out, move tray underneath to top shelf and bake a further 1 minute then remove. The cookies will look ever so slightly undercooked in the centre - they will finish cooking on the tray (this is how we make them chewy!)","images":[],"step":11},{"description":"Leave cookies to cool on the tray for 20 minutes, then transfer to cooling rack.","duration":20,"images":[],"step":12},{"description":"Allow to cool fully before serving (becomes chewy when cools, even better the next day!)","images":[],"step":13}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["baking-recipes","cookies","dessert-recipes","egg-yolk-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ccb3bfe229eb', 'en', 'US', 'Apple Crumble Bars', 'Recipe video above. Tastes like Apple Crumble - in bar form! Shortbread-like base, jammy apple filling and crumbly top. Take it over the top with a drizzle of salted caramel sauce - and ice cream! Great quick apple recipe ideal for a handheld snack, or transform into a dessert for dinner party.', 'https://www.recipetineats.com/tachyon/2019/05/Apple-Crumble-Bars_9.jpg', 20, 35, 55, 9, '[{"id": "ing_butter", "quantity": {"value": 125.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.017, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_rolled_oats", "quantity": {"value": 0.1, "unit": "pack of 500g"}}, {"id": "ing_apples", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_cinnamon", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_nutmeg", "quantity": {"value": 1.25, "unit": "jar"}}, {"id": "ing_caramel_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_cream", "quantity": {"value": 0.004, "unit": "carton of 250ml"}}]', '[{"ingredients":["125g / 1 stick unsalted butter (, melted)","2 cups (300g) flour (, plain/all purpose)","1/2 cup (100g) white sugar","1/2 tsp baking powder","Pinch of salt","1 egg"],"purpose":"Base & crumble topping:"},{"ingredients":["1/3 cup (30g) rolled oats (Note 1)"],"purpose":"For crumble topping:"},{"ingredients":["3 - 4 large granny smith apples (, cut into 0.7cm / 1/3\" dice(~4 cups))","1/4 cup (35g) plain flour (all purpose flour)","1/4 cup (50g) white sugar","1/2 tsp cinnamon","1/4 tsp nutmeg"],"purpose":"Apple Filling:"},{"ingredients":["Salted caramel sauce","Ice cream!"],"purpose":"Serving"}]', '[{"description":"Preheat oven to 180C/350.","images":[],"step":1},{"description":"Grease a 20cm/8\" square pan and line with baking/parchment paper with overhang (so it can be lifted out once cooked).","images":[],"step":2},{"description":"Mix together butter, flour, sugar, baking powder and salt until you can no longer see white bits of flour.","images":[],"step":3},{"description":"Add egg and mix.","images":[],"step":4},{"description":"Lightly press 2/3 of the mixture into the bottom of the pan.","images":[],"step":5},{"description":"Bake for 15 minutes until slightly golden, then remove and cool for 5 minutes.","duration":15,"images":[],"step":6},{"title":"Apple Filling","description":"While the base is cooking, mix together Apple Filling ingredients in a bowl.","images":[],"step":7},{"description":"Crumble Topping:","images":[],"step":8},{"description":"Add oats into reserved crumble mixture. Mix with wooden spoon / fingers until oats are mostly incorporated into the dough.","images":[],"step":9},{"description":"Spread Apple Filling on base, then use hands to crumble topping all over.","images":[],"step":10},{"title":"Bake for 30","description":"35 minutes or until the top is deep golden.","duration":32.5,"images":[],"step":11},{"description":"Remove and allow to cool in the tin before lifting out of the tin using the baking paper.","images":[],"step":12},{"description":"Cut and serve! Eat with hands, or serve on plates. Take it over the top with ice cream and salted caramel sauce!","images":[],"step":13}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","dessert-recipes","slices-bars"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4ff74e7abbe8', 'en', 'US', 'Salmon Quiche', 'Recipe video above. The most amazing salmon quiche made with smoked salmon!! When cooked, it''s looks just like cooked normal salmon - but with better seasoning in every bite. This fills a deep dish quiche tin 23cm / 9″ diameter, 3.5 cm / 1.5″ deep. Scale down for smaller tins and prepared pie shells - see Note 1.', 'https://www.recipetineats.com/tachyon/2019/04/Salmon-Quiche_6.jpg', 20, 90, 110, 8, '[{"id": "ing_homemade_quiche_crust", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_sheets_frozen_shortcrust_pastry", "quantity": {"value": 2.0, "unit": "pack"}}, {"id": "ing_x_9_refrigerated_pie_crust", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_ready_made_pie_shell", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_butter", "quantity": {"value": 15.0, "unit": "block of 250g"}}, {"id": "ing_eek", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_pears", "quantity": {"value": 8.0, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 5.0, "unit": "carton of 12"}}, {"id": "ing_cream", "quantity": {"value": 1.5, "unit": "carton of 250ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_dill", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_salmon_fillets", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_gruyere_cheese", "quantity": {"value": 0.75, "unit": "block of 200g"}}, {"id": "ing_salmon_fillets", "quantity": {"value": 0.2, "unit": "kg"}}]', '[{"ingredients":["1 homemade quiche crust (shortcrust pastry)","2 sheets frozen shortcrust pastry","1 x 9\" refrigerated pie crust (, fitted in a 9\" pie dish or tart tin)","1 ready made pie shell (23cm / 9\", fridge or frozen)"],"purpose":"Quiche Crust – choose one (Note 1):"},{"ingredients":["15g / 1 tbsp butter (, unsalted)","1 leek (, white part only halved and finely sliced (Note 2))","2 garlic cloves (, minced)","8 - 10 asparagus spears","5 eggs (~55 - 60g / 2oz each)","1 1/2 cups (375ml) cream (, full fat (Note 3))","1/4 tsp salt + pinch pepper","2 tbsp fresh dill (, roughly chopped (Note 4))","200g / 7 oz smoked salmon (, cut into 4cm / 1.7\" pieces (Note 5))","3/4 cup (75g) gruyere cheese (, grated (Note 6))"],"purpose":"Quiche Filling:"},{"ingredients":["Dill sprigs and extra smoked salmon"],"purpose":"Decorations (optional)"}]', '[{"description":"Quiche Crust (Note 1):","images":[],"step":1},{"title":"Homemade quiche crust or frozen shortcrust pastry","description":"prepare and bake the crust per Quiche Crust recipe.","images":[],"step":2},{"title":"Refrigerated pie crust","description":"unroll, fit into a 9\" pie dish or tart tin. Bake per packet directions.","images":[],"step":3},{"title":"Prepared pie shell (ie comes in foil dish)","description":"bake per packet directions, scale Filling down to 4 eggs (Note 1).","images":[],"step":4},{"description":"Preheat oven to 180C/350F (160C/320F fan forced).","images":[],"step":5},{"description":"Place cooked quiche crust on a tray.","images":[],"step":6},{"title":"Asparagus","description":"break woody ends off (Note 7). Cut into 3.5cm / 1.5\" pieces, separate tips from stems (tips for decorating).","images":[],"step":7},{"description":"Melt butter in a skillet over medium heat. Add leeks and garlic, saute for 2 minutes or until leeks are translucent, don''t let them go golden.","duration":2,"images":[],"step":8},{"description":"Stir in asparagus stems (don''t cook), then remove from stove.","images":[],"step":9},{"description":"Cool slightly then scatter across base of quiche crust.","images":[],"step":10},{"description":"Whisk together eggs, cream, dill, salt, pepper in a bowl.","images":[],"step":11},{"description":"Scatter 2/3 of the salmon across quiche, folding/twisting pieces rather than laying flat.","images":[],"step":12},{"description":"Top with cheese, pour over egg mixture.","images":[],"step":13},{"description":"Top with remaining salmon and asparagus tips.","images":[],"step":14},{"description":"Bake for 40 minutes or until top is light golden and centre is set but still slightly jiggly when you poke it.","duration":40,"images":[],"step":15},{"description":"Rest for 10 minutes before carefully removing from tin and slicing.","duration":10,"images":[],"step":16}]', '["egg","fish","milk"]', '["gluten_free"]', '{"mealType":["breakfast","dinner"],"cuisine":["Western"],"categories":["baking-recipes","easter-brunch-recipes","easter-recipes","egg-recipes","fish-recipes","quiches-tart-and-pie-recipes","salmon-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d6966578a8fb', 'en', 'US', 'Quiche Crust / Shortcrust Pastry for Pies', 'Recipe video above. This is a recipe for quiche and pie crusts, both of which are made using shortcrust pastry. This is a great, EASY classic quiche crust. Quiche crusts are just made with shortcrust pastry. Made using a food processor, very slightly adapted from this recipe by Emeril Lagasse.Inactive chill time: 1 hour. This is the recipe I''ve been using for years and years, and it has never failed me! Makes pastry for 1 x 23cm / 9" pie dish or tart tin (serves 8 - 12 people).', 'https://www.recipetineats.com/tachyon/2019/04/Quiche-Crust_4.jpg', 15, 35, 50, 8, '[{"id": "ing_flour", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_water", "quantity": {"value": 0.045, "unit": "L"}}]', '[{"ingredients":["1 1/4 cups (185g / 5.6 oz) plain white flour (all purpose flour)","1/2 tsp salt","100g / 7 tbsp unsalted butter, cold, cut into 1cm/ 1/3\" cubes","3 tbsp ice cold water (+ more as required)"]}]', '[{"description":"Place flour, salt and butter in a food processor.","images":[],"step":1},{"description":"Pulse 10 times or until it looks like breadcrumbs.","images":[],"step":2},{"description":"With the motor running on low, pour 2.5 tbsp of water into the tube feeder.","images":[],"step":3},{"description":"Turn up to high and blitz for 30 seconds or until it turns into a ball of dough. Initially it will look like breadcrumbs, then it will turn into a ball of soft dough - some random escaped bits is fine. If it doesn''t look like its coming together at 20 seconds, add another 1/2 tbsp of water. Don''t blitz longer than 30 seconds at most.","duration":0.5,"images":[],"step":4},{"description":"Form a disc, wrap in cling wrap. If there are escaped crumble bits, that''s fine - just press them in. Refrigerate for 1 - 3 hours.","images":[],"step":5},{"description":"Preheat oven to 200C/390F (standard) or 180C/350F (fan forced)","images":[],"step":6},{"description":"Sprinkle work surface with flour, unwrap dough and place on the flour. Sprinkle top with flour, then roll out into a 27cm/11\" round.","images":[],"step":7},{"description":"Gently roll the pastry so it wraps around the rolling pin.","images":[],"step":8},{"title":"Unroll it over the quiche pan or pie dish","description":"23cm / 9\".","images":[],"step":9},{"description":"Press the pastry into the edges of the quiche pan, patching up edges if required (if pastry doesn''t quite reach top of rim).","images":[],"step":10},{"description":"Roll the rolling pin across the top to cut off the excess pastry.","images":[],"step":11},{"title":"Optional extra \"safe measure\" refrigeration","description":"15 minutes. See (Note 2).","images":[],"step":12},{"description":"Place a large piece of parchment paper over the pastry, then fill with baking beads or lots of rice or dried beans to weigh it down. (Note 3)","images":[],"step":13},{"description":"Bake for 20 minutes, then remove from oven.","duration":20,"images":[],"step":14},{"description":"Turn oven DOWN to 180C/350F (or 160C/320F fan).","images":[],"step":15},{"description":"Use excess paper to CAREFULLY remove hot beads, then return to oven for 10 minutes or until base is light golden.","duration":10,"images":[],"step":16},{"description":"Remove from oven and fill with chosen Quiche Filling. Quiche Lorraine, Salmon Quiche, Italian Sausage or your other filling of choice.","images":[],"step":17},{"description":"The pastry will not be 100% cooked, it finishes cooking with the filling. It''s cooked enough so the crust will not go soggy.","images":[],"step":18}]', '["gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["French"],"categories":["baking-recipes","quiches-tart-and-pie-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a2ba7506ff6e', 'en', 'US', 'White Chocolate Macadamia Nut Cookies', 'Recipe video above. Copycat of the famous Byron Bay Cookies sold in cafes across Australia, these are big, thick and buttery, and they are crispy but softly textured and they melt in your mouth. White chocolate and macadamia nuts is a classic cookie combination!', 'https://www.recipetineats.com/tachyon/2019/04/White-Chocolate-Macadamia-Nut-Cookies_7.jpg', 15, 25, 40, 13, '[{"id": "ing_butter", "quantity": {"value": 175.0, "unit": "block of 250g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.2, "unit": "bottle of 50ml"}}, {"id": "ing_flour", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.017, "unit": "tub of 150g"}}, {"id": "ing_macadamias", "quantity": {"value": 100.0, "unit": "unit"}}, {"id": "ing_chocolate", "quantity": {"value": 125.0, "unit": "block of 100g"}}]', '[{"ingredients":["175g / 5.5 oz butter, unsalted, softened (11 US tbsp)","1/3 cup brown sugar","1/3 cup white sugar (, caster/superfine best)","1/8 tsp salt","2 egg yolks (Note 6 for using leftover whites)","2 tsp vanilla extract/essence","1 1/2 cups flour (, plain/all purpose)","1/2 cup rice flour (sub with plain) (Note 1)","1/2 tsp baking powder","100g / 3.5 oz macadamias (, roughly chopped (Note 2))","125g / 4 oz white eating chocolate (, chopped into pretty small pieces (not baking chocolate, Note 3))"]}]', '[{"description":"Beat butter, sugar and salt on medium (speed 5) using a hand held mixer for 1 minute until smooth.","duration":1,"images":[],"step":1},{"description":"Add egg yolks and vanilla, beat for 1 minute or until smooth.","duration":1,"images":[],"step":2},{"description":"Add baking powder, rice flour and half the plain flour. Beat with mixer on medium speed until flour is incorporated.","images":[],"step":3},{"description":"Add remaining flour and beat with mixer until flour is incorporated. Add macadamia nuts and chocolate, then mix through with a wooden spoon (dough gets a bit too hard to use mixer).","images":[],"step":4},{"description":"Scrape mixture onto a work surface, press together and shape into a 22cm/9\" log.","images":[],"step":5},{"description":"Roll up in baking paper or cling wrap, twist ends then refrigerate for 2 hours.","images":[],"step":6},{"description":"Slice and bake:","images":[],"step":7},{"description":"Preheat oven to 200°C/390°F (180°C fan).","images":[],"step":8},{"description":"Line 2 trays with baking paper.","images":[],"step":9},{"description":"Remove log from fridge, unwrap and slice into 1.75cm / 3/4\" thick slices (12 - 13 cookies).","images":[],"step":10},{"description":"Place 6 on each tray, bake for 10 minutes.","duration":10,"images":[],"step":11},{"description":"Turn oven down to 170°C/340°F (150°C fan), switch the trays between shelves.","images":[],"step":12},{"description":"Bake 15 minutes, remove from oven and cool cookies on tray.","images":[],"step":13},{"description":"Cool fully before serving.","images":[],"step":14}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","cookies","dessert-recipes","egg-yolk-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e67588cdbc97', 'en', 'US', 'Shortbread Cookies', 'Recipe video above. I’m a firm believer that shortbread cookies should be sinfully buttery and delectably tender. And these are, as great shortbread cookies should be, not that sweet, quite delicate and when you bite into them, they crumble softly, as demonstrated in the VIDEO! TRICK for clean cuts, no crumbles, is to slice halfway through baking.', 'https://www.recipetineats.com/tachyon/2017/08/Shortbread-4.jpg', 5, 30, 35, 24, '[{"id": "ing_butter", "quantity": {"value": 250.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.3, "unit": "kg"}}]', '[{"ingredients":["250g / 8 oz salted butter, softened (2 x US sticks, 1 cup) (or unsalted + ¼ tsp salt)","3/4 cup (90g) icing sugar (powdered sugar) (Note 2)","2 cups (300g) plain / all purpose flour"]}]', '[{"description":"Preheat oven to 160C/325F (standard) or 150C/300F (fan forced / convection).","images":[],"step":1},{"description":"Butter and line a 31.5 x 23.5 cm / 9 x 13\" pan with baking paper with overhang.","images":[],"step":2},{"description":"Beat butter until smooth (or use very soft butter and a wooden spoon). Add icing sugar and beat until combined.","images":[],"step":3},{"title":"Add half the flour and beat until mostly combined","description":"it will resemble wet sand. Then beat in the remainder. Use your hands to bring it together into a smooth ball of dough – knead lightly if required.","images":[],"step":4},{"description":"Roughly press down into a rectangle shape, then transfer into the pan. Press into the pan. Optional: Roll over the top using a small rolling pin or glass (that’s what I used) for a smooth surface. Don’t press down too hard – it makes the cookies firmer","images":[],"step":5},{"description":"Bake for 20 minutes until edges are very light golden and most of the surface is still pale gold.","duration":20,"images":[],"step":6},{"description":"Remove from the oven. Working quickly, cut into desired shape (I do 8 x 3 bars, like Walker’s shortbread biscuits) and prick all over with a fork (optional).","images":[],"step":7},{"description":"Return to the oven for 8 minutes or until the surface is light golden – not browned. Turn the oven off, crack it open ajar, then leave to cool for at least 1 hour in the oven.","duration":8,"images":[],"step":8},{"description":"Remove from the oven, use paper overhang to remove the biscuits from the pan. Cool fully on rack. Serve with tea!!","images":[],"step":9}]', '["gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Scottish","Western"],"categories":["baking-recipes","cookies","dessert-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9ac1a30bd995', 'en', 'US', 'Easy Chocolate Fudge Cake', 'Recipe video above. This cake is rich, very chocolatey and super moist! It''s based on a brownie / mud cake recipe - but with a bit of extra rise so it''s not as dense and gooey. This recipe is easy and it''s virtually foolproof - it is VERY forgiving! It''s not very tall because it''s so rich and it''s a single layer cake.', 'https://www.recipetineats.com/tachyon/2018/11/Easy-Chocolate-Fudge-Cake_3a.jpg', 10, 60, 70, 12, '[{"id": "ing_chocolate", "quantity": {"value": 125.0, "unit": "block of 100g"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_cocoa_powder", "quantity": {"value": 0.15, "unit": "pack of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.033, "unit": "tub of 150g"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_coffee_granules", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}]', '[{"ingredients":["125g / 4 oz dark chocolate chips (Note 1)","100g / 7 tbsp butter (, salted (or unsalted butter + 1/4 tsp salt))","1 1/4 cups white sugar (, caster / superfine best (Note 2))","1/4 cup oil (vegetable, canola)","1 tsp vanilla extract","2 eggs (, at room temperature)","1/4 cup cocoa powder (Note 3)","1 cup flour (, plain / all purpose (Note 4))","1 tsp baking powder","1 cup boiling hot water","1 tbsp coffee granules (, optional (Note 5))"]},{"ingredients":["1 cup heavy / thickened cream (, 30%+ fat (Note 6))","250g / 8 oz dark chocolate chips (Note 1)"],"purpose":"Ganache"}]', '[{"description":"Preheat oven to 150C/300F (standard) or 130C/265F (fan). Grease a 22 cm / 9\" springform cake pan and line with parchment / baking paper.","images":[],"step":1},{"title":"Melt butter and chocolate","description":"Place butter and chocolate in a heatproof bowl. Microwave 3 x 30 seconds on high, mix in between, until melted. Mix.","images":[],"step":2},{"title":"Oil, vanilla & Sugar","description":"Add oil, vanilla and sugar, mix to combine (this brings down batter temp).","images":[],"step":3},{"title":"Eggs","description":"Add eggs and mix until combined.","images":[],"step":4},{"title":"Dry Ingredients","description":"Sift cocoa, baking powder and flour (and coffee, if using) directly into the bowl. Mix until smooth, batter will be thin. Some small lumps is ok.","images":[],"step":5},{"title":"Hot water","description":"Add hot water. Mix until incorporated.","images":[],"step":6},{"title":"Bake","description":"Pour into the cake tin and bake for 1 hour or until a skewer inserted into the centre comes out moist but clean. Check at 50 minutes. The surface will crack (sometimes badly!) but sill subside when it cools and gets covered with frosting so don''t stress!","images":[],"step":7},{"title":"Cool","description":"Remove sides from the cake pan and transfer to a cooling rack to cool. Cool completely before carefully handling to remove base (Note 7).","images":[],"step":8},{"description":"Ganache (Note 8)","images":[],"step":9},{"description":"Place chocolate and cream in a heatproof bowl. Microwave 3 x 30 seconds, mixing in between, until chocolate melts. DO NOT let cream come to boil.","images":[],"step":10},{"description":"Stir chocolate until smooth. Refrigerate for 1 to 2 hours or until thickened to a spreadable consistency like peanut butter.","images":[],"step":11},{"title":"Spread over the cake","description":"tops and sides. Use a teaspoon in a swirling motion to achieve the textured surface you see in the photos.","images":[],"step":12}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","classic-cakes","dessert-recipes","easter-baking-desserts","easter-recipes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_86e1568ad1d5', 'en', 'US', '5 Ingredient Chocolate Peanut Butter Bars (NO BAKE!)', 'Recipe VIDEO above. These no bake bars just happen to only require 5 ingredients. The hardest part is waiting for them to set!', 'https://www.recipetineats.com/tachyon/2015/06/Chocolate-Peanut-Butter-Bars_6.jpg', 15, 0, 15, 16, '[{"id": "ing_butter", "quantity": {"value": 115.0, "unit": "block of 250g"}}, {"id": "ing_arnott_s_marie_crackers_or_16_graham_cracker_squares", "quantity": {"value": 150.0, "unit": "pack"}}, {"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.3, "unit": "jar of 375g"}}, {"id": "ing_chocolate", "quantity": {"value": 1.0, "unit": "block of 100g"}}]', '[{"ingredients":["115g / 1/2 cup / 1 US stick melted salted butter (or unsalted butter + 1/4 tsp salt)","1 cup crushed Arnott''s Marie crackers (11 crackers) or graham cracker crumbs (8 crackers) (Note 1)","1 cup icing sugar / powdered sugar","3/4 cup peanut butter (smooth)"],"purpose":"Base"},{"ingredients":["1 cup dark chocolate chips - the melting kind (US: semi sweet) (Note 2)","2 tbsp peanut butter (smooth)"],"purpose":"Topping"}]', '[{"description":"Butter and line a 8\" / 20cm square dish or pan with baking paper.","images":[],"step":1},{"description":"Place the Base ingredients in a bowl and mix until combined. Press into the prepared pan.","images":[],"step":2},{"description":"Melt the Topping ingredients (I do it in the microwave in 2 x 30 second bursts). Pour and spread over the Base - smooth the top or do swirls (see photos for examples of each).","images":[],"step":3},{"title":"Refrigerate until set","description":"about 1 1/2 hours. Remove from fridge, allow to come to room temp slightly (so top cuts neatly). Cut into 16 squares (or whatever shape you want!). Best served at room temperature.","images":[],"step":4}]', '["gluten","milk","peanuts"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":[],"categories":["baking-recipes","dessert-recipes","dietary","gluten-free-recipes","most-popular","quick-and-easy","slices-bars"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ab8f47d3b9f5', 'en', 'US', 'Sticky Date Pudding', 'Recipe video above. You''re my favourite pudding - and always will be.... My favourite part is poking holes in the pudding and pouring over the hot butterscotch sauce so it soaks in, making it so ultra moist... And then of course serving it with even more sauce!', 'https://www.recipetineats.com/tachyon/2018/07/Sticky-Date-Pudding_5.jpg', 15, 35, 50, 7, '[{"id": "ing_pitted_dates", "quantity": {"value": 280.0, "unit": "unit"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.025, "unit": "tub of 200g"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 80.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_flour", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.05, "unit": "tub of 150g"}}, {"id": "ing_cream", "quantity": {"value": 1.5, "unit": "carton of 250ml"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.05, "unit": "bottle of 50ml"}}, {"id": "ing_cream", "quantity": {"value": 1.5, "unit": "carton of 250ml"}}]', '[{"ingredients":["280g / 9 oz pitted dates (, roughly chopped (Note 1))","1 tsp baking soda / bi carb soda","1 cup boiling water","1/4 cup brown sugar (, loosely packed)","80g / 6 tbsp unsalted butter (, softened)","2 eggs (, at room temperature)","1 1/4 cups plain flour (all purpose flour)","1 1/2 tsp baking powder"]},{"ingredients":["1 cup brown sugar (, tightly packed)","1 1/2 cups thickened cream (heavy cream)","1/2 tsp vanilla extract","70g / 5 tbsp unsalted butter"],"purpose":"Butterscotch Sauce:"},{"ingredients":["Ice cream or dolloping cream"],"purpose":"Serving:"}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan-forced).","images":[],"step":1},{"description":"Grease 7 pudding moulds (Note 2) with butter or grease and line a 20 cm / 8\" square cake pan with overhang.","images":[],"step":2},{"description":"Place dates in a bowl, sprinkle over baking soda. Pour over boiling water. Stand 10 minutes, then mash well with a potato masher (or fork) until it resembles sloppy porridge (see video for texture / thickness). (Note 3)","images":[],"step":3},{"description":"Place butter and sugar in a bowl. Beat until combined and smooth.","images":[],"step":4},{"description":"Add eggs, beat until incorporated.","images":[],"step":5},{"description":"Add flour then sprinkle baking powder across the surface. Mix until flour is incorporated.","images":[],"step":6},{"description":"Add dates, mix quickly until dates are well incorporated into the batter. (Note 2) Follow directions to make one pudding or individual ones.","images":[],"step":7},{"description":"Pour into cake pan, smooth surface. Bake 35 minutes or until skewer inserted into the centre comes out clean.","images":[],"step":8},{"description":"While still hot, poke about 40 holes all over the surface using a skewer. Pour over 1/2 cup Butterscotch Sauce, leave to soak for 10 minutes.","duration":10,"images":[],"step":9},{"description":"Use overhang to lift cake out. Cut, serve warm with remaining warm sauce and ice cream or cream.","images":[],"step":10},{"description":"Baking Individual Puddings:","images":[],"step":11},{"description":"Pour batter into pudding moulds, only fill 2/3 of the way up.","images":[],"step":12},{"description":"Bake for 25 minutes, or until skewer inserted into the centre comes out clean.","duration":25,"images":[],"step":13},{"description":"While still hot, poke about 10 holes on the surface of the pudding. Spoon over 1 tbsp of Butterscotch Sauce per Pudding. Leave to soak 10 minutes.","images":[],"step":14},{"description":"Turn pudding moulds upside down on serving plate. Serve warm with remaining warm sauce and ice cream or cream.","images":[],"step":15},{"description":"Butterscotch Sauce:","images":[],"step":16},{"description":"Place ingredients in a saucepan over medium heat. Once butter is melted, stir, then bring to simmer.","images":[],"step":17},{"description":"Simmer for 2 minutes, stirring once, then remove from heat. Serve warm.","duration":2,"images":[],"step":18}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":[],"categories":["baking-recipes","cosy-desserts","dessert-recipes","easter-baking-desserts","puddings-cosy-desserts","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_979abf20ec34', 'en', 'US', 'Apple Crumble', 'Recipe video above. A filling of tender, cinnamon laced apples topped with a nubbly crunchy, golden topping. You''ll love how this Apple Crumble isn''t overly sweet, and how the filling is syrupy and jammy, rather than watery or dry. The smell when this is cooking is everything! SWEETNESS - see Note 4.', 'https://www.recipetineats.com/tachyon/2016/05/Apple-Crumble_1a-1.jpg', 15, 40, 55, 6, '[{"id": "ing_apples", "quantity": {"value": 0.907, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_round_cinnamon", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_rolled_oats", "quantity": {"value": 0.3, "unit": "pack of 500g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.017, "unit": "tub of 150g"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_butter", "quantity": {"value": 125.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.004, "unit": "carton of 250ml"}}]', '[{"ingredients":["2 lb / 1kg Granny Smith Apples( green apples) (, weight before peeling)","1 tbsp flour (, plain / all-purpose)","1/2 cup white sugar (sub brown sugar)","2 tbsp lemon juice (or water)","1/2 tsp ground cinnamon"],"purpose":"Apple Filling"},{"ingredients":["1 cup rolled oats / oatmeal (quick cooking is ok)","1 cup flour (, plain / all-purpose)","1 cup (loosely packed) brown sugar (sub white sugar)","1/2 tsp baking powder","1 tsp cinnamon powder","125g / 1/2 cup unsalted butter (, melted)","Pinch of salt"],"purpose":"Topping"},{"ingredients":["Vanilla ice cream"],"purpose":"To Serve"}]', '[{"description":"Preheat oven to 180°C / 350°F (both fan and standard).","images":[],"step":1},{"title":"Apple","description":"Peel apples, then cut into 1.5cm/ 1/2” cubes.","images":[],"step":2},{"title":"Apple filling","description":"Place apples in a bowl. Sprinkle with flour, sugar and cinnamon, then pour over lemon juice. Toss, then spread out evenly in a 1.5 litre/1.5 quart baking dish.","images":[],"step":3},{"title":"Crumble topping","description":"Place Topping ingredients in a bowl. Mix until clumps form, like wet sand (see video). Spread over the apples, crumbling with fingers if required to get that crumbly topping.","images":[],"step":4},{"description":"Bake for 30 to 40 minutes or until golden brown. Remove, cover loosely with foil to keep warm and let stand for 10 minutes before serving (let''s the apple syrup thicken slightly).","duration":35,"images":[],"step":5},{"description":"Serve warm with vanilla ice cream!","images":[],"step":6}]', '["gluten","milk"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","cosy-desserts","dessert-recipes","easter-baking-desserts","easter-recipes","puddings-cosy-desserts","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e22293723016', 'en', 'US', 'Savoury Cheese Muffins', 'Recipe video above. They taste like cheesy garlic bread - in muffin form! If you want lovely high domes as pictured, this makes 11 muffins. It''s irritating, I know, but such is life. See notes for Add In options!', 'https://www.recipetineats.com/tachyon/2016/05/Cheesy-Savoury-Muffins_1a.jpg', 15, 20, 35, 11, '[{"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.05, "unit": "tub of 150g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.013, "unit": "tub of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.15, "unit": "tub of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}]', '[{"ingredients":["3 tbsp / 50g unsalted butter","2 garlic cloves (, crushed using a garlic press or grated finely)","2 cups (200g) shredded cheddar cheese (Note 1)"],"purpose":"Butter and Cheese:"},{"ingredients":["2 cups plain flour /all purpose flour","1 1/2 tsp baking powder","1/2 tsp baking soda / bi-carb soda (Note 2)","1/2 tsp salt"],"purpose":"Dry Ingredients"},{"ingredients":["1 egg (large, about 60g / 2 oz)","1 cup milk (full or low fat)","1/4 cup sour cream (or plain yoghurt)","1/3 cup vegetable or olive oil (or any plain flavoured oils)","1/4 cup finely chopped fresh parsley (, optional (Note 3))","1 garlic clove (, crushed using garlic press or finely grated using microplane)"],"purpose":"Wet Ingredients"}]', '[{"description":"Melt butter with garlic, brush 11 holes generously (reserve bit for tops). Whisk Dry and Wet ingredients in separate bowls. Pour Dry into Wet, mix just 8 times. Add cheese, mix as little as you can. Fill 11 holes of muffin tin. Bake 25 minutes at 180°C/350°F (160°C fan), brush tops with remaining butter.","images":[],"step":1},{"description":"Preheat oven to 180°C/350°F (160°C fan-forced)","images":[],"step":2},{"title":"Garlic butter","description":"Place butter and garlic in a microwave proof bowl and melt in 2 x 30 second bursts. Mix.","images":[],"step":3},{"title":"Grease muffin tin","description":"Brush a 11 holes of a standard muffin tin generously with the butter, being sure to slather with some garlic. Use most - just reserve a bit for brushing the tops later)","images":[],"step":4},{"title":"Make batter","description":"Whisk Dry ingredients in a bowl. Whisk Wet ingredients in a separate bowl. Pour Wet into the Dry ingredients bowl. Mix 8 times - some flour will remain not mixed in, that''s ok.","images":[],"step":5},{"description":"Add cheese, then mix as few times as possible just to incorporate remaining bits of flour - no more than 7 big stirs (secret to soft muffs). The batter can be lumpy, that''s fine.","images":[],"step":6},{"title":"Fill muffin tin","description":"Divide between 11 holes in muffin in (I use an ice cream scooper). Batter should be thick and fill muffin tin to top (if in ball shape due to scooper, leave as is). See video.","images":[],"step":7},{"title":"Bake for 25","description":"27 minutes or until the muffins are domed, golden and crusty. A toothpick inserted should come out clean.","duration":26,"images":[],"step":8},{"title":"Butter brush and cool","description":"Brush remaining butter on the surface (re-melt again if needed). Let muffins cool in the pan for 5 minutes then remove onto cooling rack. Cool for at least 5 minutes before getting stuck into them!","duration":5,"images":[],"step":9}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["snack","breakfast"],"cuisine":["Western"],"categories":["baking-recipes","breakfast-recipes","easter-brunch-recipes","most-popular","muffin-recipes","quick-and-easy","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7584719c2794', 'en', 'US', 'Chocolate Buttercream Frosting', 'Recipe video above. The key to ensuring your buttercream comes out fluffy and smooth (rather than dense and gritty) is to beat, beat, beat and to use the right ratio of butter to icing sugar. Quantity - This makes enough to swirl frosting on 12 cupcakes (see photos in post), to smear on 18 cupcakes, or a single layer 20-22cm / 8-9" cake (like this Chocolate Fudge Cake).For a 2 layer cake, like as depicted in this Chocolate Cake recipe (2 layer 22cm/9" cake), increase the recipe by 50%. Use the recipe scaler (hover /click on servings and slide) and increase until icing sugar becomes 3.75 cups (ie 3 3/4 cups) / 450g.', 'https://www.recipetineats.com/tachyon/2018/03/Chocolate-Cake_0.jpg', 15, 0, 15, 12, '[{"id": "ing_butter", "quantity": {"value": 200.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.375, "unit": "kg"}}, {"id": "ing_cocoa_powder", "quantity": {"value": 0.3, "unit": "pack of 250g"}}, {"id": "ing_milk", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}]', '[{"ingredients":["200g / 3/4 cup unsalted butter, softened","2 1/2 cups soft icing sugar / powdered sugar (, sifted (Note 1))","1/2 cup cocoa powder (, unsweetened, preferably Dutch Processed, sifted(Note 3))","1/4 cup milk (any)","1 tsp vanilla extract ( (optional))"]}]', '[{"description":"Place butter in the bowl of a stand mixer with paddle attached. Beat for 3 minutes on speed 7 until it becomes pale.","duration":3,"images":[],"step":1},{"description":"Add half the icing sugar and cocoa powder. Beat for 3 minutes - start slow, increase to speed 7.","duration":3,"images":[],"step":2},{"description":"Add remaining icing sugar and cocoa powder. Beat again for 3 minutes.","duration":3,"images":[],"step":3},{"description":"Add milk and vanilla if using. Beat again for 1 minute on speed 7.","duration":1,"images":[],"step":4},{"description":"Spread onto cakes / cupcakes, or spoon into frosting bag and pipe.","images":[],"step":5}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["baking-recipes","frosting-and-icing","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_954048d61237', 'en', 'US', 'Glazed Lemon Yogurt Cake recipe', 'Recipe VIDEO above. This is a wonderful, simple tea cake with bright lemon flavours. It''s beautifully moist and keeps for days thanks to the yogurt (bakers'' trick!). I love how it''s made in one bowl with just a whisk, and it''s quick to prepare. Glazed with a lemon glaze - or try my quick cream cheese frosting (recipe in notes).', 'https://www.recipetineats.com/tachyon/2018/03/Lemon-Cake_3.jpg', 15, 50, 65, 10, '[{"id": "ing_oil", "quantity": {"value": 100.0, "unit": "bottle"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_lemon", "quantity": {"value": 0.045, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.045, "unit": "net of 500g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.3, "unit": "tub of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.133, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.3, "unit": "tub of 500g"}}]', '[{"ingredients":["2/3 cup vegetable or canola oil","2 large eggs (~50 - 55g/2oz each, in shell)","1 1/2 tbsp lemon zest (1 large or 2 medium lemons)","1/4 cup fresh lemon juice","1 cup plain yoghurt (Note 1)","1 1/4 cups caster sugar (superfine sugar, granulated ok too)"],"purpose":"Wet:"},{"ingredients":["2 cups plain flour (all purpose flour)","4 tsp baking powder","Pinch of salt"],"purpose":"Dry:"},{"ingredients":["1 3/4 cup icing sugar (powdered sugar)","1 tbsp lemon juice","1 1/2 tbsp plain yogurt"],"purpose":"Glaze:"}]', '[{"description":"Preheat oven to 180C/350F (standard) or 160C/320F (fan/convection). Grease a 20 cm / 8” cake pan with butter.","images":[],"step":1},{"description":"Place Wet ingredients in a bowl. Whisk until combined.","images":[],"step":2},{"description":"Sprinkle over flour, baking powder and salt. Whisk until smooth - few small lumps is ok.","images":[],"step":3},{"title":"Pour into pan","description":"it should be fairly thick but pourable (see video). Bake for 50 minutes or until a skewer comes out clean.","duration":50,"images":[],"step":4},{"description":"Remove metal ring and cool on rack then glaze.","images":[],"step":5},{"description":"Place ingredients in a bowl and whisk until smooth. Test down the side of the bowl to get the right thickness, using 1 tsp of yoghurt at a time to thin it out if required. Glaze should drip (slowly, because it''s thick) but not be see through.","images":[],"step":6},{"description":"Place rack on a tray or baking paper.","images":[],"step":7},{"description":"Pour glaze over the middle of the cake, gently push towards the edges so it drips down the sides.","images":[],"step":8},{"description":"Let it set for 1 hour before transferring to a serving plate.","images":[],"step":9},{"description":"See note for how I did the lemon slices in the photos, and the alternative quick Cream Cheese Frosting.","images":[],"step":10}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","classic-cakes","dessert-recipes","easter-baking-desserts","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8017854d02be', 'en', 'US', 'No Bake Mango Cheesecake', 'A celebration of summer! A creamy mousse-like VERY mangoey filling on a biscuit base topped with a beautiful mango jelly, piles of whipped cream, more mango and passionfruit. Toppings are optional - it''s stunning without, prettier with! Recipe VIDEO below.', 'https://www.recipetineats.com/tachyon/2018/01/Mango-Cheesecake-3.jpg', 30, 0, 30, 12, '[{"id": "ing_arnott_s_marie_biscuits_or_digestives_graham_crackers_or_other_plain_sweet_biscuit", "quantity": {"value": 150.0, "unit": "pack"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_mango", "quantity": {"value": 700.0, "unit": "unit"}}, {"id": "ing_elatin_powder", "quantity": {"value": 22.5, "unit": "jar"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_cream_cheese", "quantity": {"value": 500.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 2.0, "unit": "carton of 250ml"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_mango", "quantity": {"value": 700.0, "unit": "unit"}}, {"id": "ing_passionfruit", "quantity": {"value": 2.0, "unit": "kg"}}]', '[{"ingredients":["150 g / 5 oz Arnott''s Marie Biscuits (17 crackers), or digestives, Graham Crackers or other plain sweet biscuit","100 g / 3.5 oz unsalted butter (, melted)","2 tbsp white sugar"],"purpose":"Base:"},{"ingredients":["700 g / 1.4 lb mango flesh ( (2 large mangoes) (Note 1))"],"purpose":"Mango:"},{"ingredients":["4 1/2 tsp gelatin powder (Note 2)","1/2 cup cold tap water","500 g / 1 lb Philadelphia cream cheese, softened (2 blocks)","2/3 cup caster sugar (superfine white sugar)","1 1/4 cups whipping cream*"],"purpose":"Filling:"},{"ingredients":["3/4 tsp gelatin powder (Note 2)","1/4 cup cold tap water","1 tbsp lemon juice"],"purpose":"Mango Jelly:"},{"ingredients":["1 1/4 cups whipping cream*","1 tbsp white sugar","1 tsp vanilla extract","1 large mango, cut into cubes","2 passionfruit"],"purpose":"Toppings (optional):"}]', '[{"title":"Pan","description":"Use a 22 cm / 9\" springform pan (or similar size). Turn the base UPSIDE DOWN (for ease of removal later).","images":[],"step":1},{"title":"Line","description":"Place a square sheet of baking paper on the base, then secure in springform pan (see video) with excess paper hanging out sides. Grease sides with butter and line with paper.","images":[],"step":2},{"description":"Blitz crackers into fine crumbs in a food processor.","images":[],"step":3},{"title":"Press","description":"Add butter and sugar, blitz until combined. Pour into prepared cake pan. Press down firmly - base only, not sides.","images":[],"step":4},{"title":"Bloom gelatine","description":"Put water in a heatproof bowl. Sprinkle gelatin over surface (don''t dump in centre). Stir to partly dissolve. Set aside 5 minutes - it turns gelatinous.","images":[],"step":5},{"title":"Melt gelatine","description":"Microwave 15 seconds on high x 2, stirring in between. Stir until dissolved (few tiny specks ok). Cool 5 minutes, but it must still be liquid when you add it into the cheesecake mixture. (You can re-melt in the microwave if necessary).","images":[],"step":6},{"title":"Puree mango","description":"Place mango in food processor. Blitz until smooth. Measure out 3/4 cup and reserve for mango jelly, set aside.","images":[],"step":7},{"title":"Cheesecake filling","description":"Add cream cheese, cream, sugar and gelatine mixture into food processor (2.5L/2.5qt/10 cup+ capacity - Note 3). Blitz for 30 seconds or so until smooth.","duration":0.5,"images":[],"step":8},{"description":"Pour into cake pan. Refrigerate 3+ hours until top is set before pouring the mango jelly on top.","images":[],"step":9},{"title":"Bloom gelatine","description":"Pour water into bowl, sprinkle over gelatin. Leave 5+ min. Microwave on high 2 x 10 sec, stir well until granules dissolved. Set aside 5 minutes to cool.","images":[],"step":10},{"title":"Add mango","description":"Place reserved mango puree (from step 4 under Filling) and lemon in a bowl. Pour over gelatin and whisk well.","images":[],"step":11},{"description":"Pour over cheesecake filling. Tilt cake around to spread.","images":[],"step":12},{"description":"Refrigerate 12 hours+.","images":[],"step":13},{"description":"Release pan sides, then use overhang paper to slide cheesecake onto serving plate. Then slide the paper out from under the cheesecake.","images":[],"step":14},{"title":"Whip cream","description":"Place cream, vanilla and sugar in a bowl. Whip until the cream is softy whipped.","images":[],"step":15},{"title":"Decorate","description":"Swirl the cream on top of the cheese. Top with more chopped mango and passionfruit pulp. Serve and relish in praises!","images":[],"step":16}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","cheesecakes","dessert-recipes","easter-baking-desserts","quick-and-easy","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9b71eb67adca', 'en', 'US', 'Christmas Trifle', 'Recipe VIDEO above. The one thing that will elevate your Trifle from "ok" to PHENOMENAL is making jelly with real cranberry juice instead of using artifical flavoured jelly. It''s no different to making instant jelly - it''s just that you use fruit juice and gelatine instead of flavoured jelly crystals! Make real jelly, then you can totally get away with using store bought shortcuts for everything else - like the custard and cake. NOTE: I used to use flavourless Aeroplane Jelly for the jelly (click here for the original recipe). It''s no longer available, so the recipe uses plain gelatine instead which was previously an alternative in the notes. Video not yet refilmed. Will do so next year! START THIS recipe the day before as it needs time to set in the fridge.', 'https://www.recipetineats.com/tachyon/2017/12/Christmas-Trifle-3.jpg', 30, 10, 86, 10, '[{"id": "ing_x_450g_madeira_cake_or_pound_cake", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_oranges", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_gelatine_powder", "quantity": {"value": 35.0, "unit": "jar"}}, {"id": "ing_cranberry_juice_original", "quantity": {"value": 0.9, "unit": "kg"}}, {"id": "ing_strawberries", "quantity": {"value": 500.0, "unit": "punnet of 250g"}}, {"id": "ing_blueberries", "quantity": {"value": 1.0, "unit": "punnet of 125g"}}, {"id": "ing_cream", "quantity": {"value": 2.5, "unit": "carton of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.9, "unit": "kg"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.15, "unit": "bottle of 50ml"}}, {"id": "ing_milk", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.9, "unit": "kg"}}, {"id": "ing_vanilla_bean_paste", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_sugar", "quantity": {"value": 0.9, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 4.0, "unit": "carton of 12"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.188, "unit": "pack of 400g"}}]', '[{"ingredients":["1 x 450g / 14 oz Madeira cake or Pound cake store bought (Note 1)","1/3 cup orange or other fruit flavoured liquor (like Cointreau), or apple, orange or other fruit juice (or 2 tbsp brandy)","7 tsp gelatine powder (Note 2)","6 cups Cranberry juice, original (ie WITH sugar added, not No Added Sugar, Note 2)","500 - 750g (1 - 1.5 lb) strawberries (, halved)","1 each punnet blueberries, raspberries"]},{"ingredients":["2 1/2 cups heavy / thickened cream (or pure whipping cream)","3 tbsp white sugar (caster sugar ok)","1 1/2 tsp vanilla extract"],"purpose":"Cream:"},{"ingredients":["3 cups milk (full or low fat)","1/4 cup caster sugar (superfine sugar)","1 tsp vanilla bean paste (or extract) (Note 4)","1/4 cup caster sugar ((superfine sugar), extra)","4 egg yolks (Note 7 for using leftover whites)","1/2 cup cornflour / cornstarch"],"purpose":"Homemade Thick Custard (or 900g 1 tub Pauls Double Thick Vanilla Custard, Note 3):"}]', '[{"description":"Cut cake into 2 cm / 0.8\" cubes. Cover bottom of 3.5 L / 3.5 qt trifle dish with cake (might not use all) and sprinkle with liquor or juice.","images":[],"step":1},{"title":"Optional extra","description":"Scatter over 1/2 to 1 punnet halved strawberries (this is not in ingredients list).","images":[],"step":2},{"description":"Cranberry Jelly:","images":[],"step":3},{"title":"Heat half juice","description":"Put half the cranberry juice into a saucepan over medium heat (3 cups / 750ml). Bring to a simmer, then turn off stove.","images":[],"step":4},{"title":"Dissolve geatline","description":"Meanwhile, put remaining room temperature cranberry juice into a very large bowl. Sprinkle gelatine all across surface (don''t dump in one place, else you get lumps). Whisk until mostly dissolved (will finish dissolving in next step).","images":[],"step":5},{"description":"Pour in hot cranberry juice. Whisk until gelatin is fully dissolved.","images":[],"step":6},{"description":"Pour HALF the warm jelly liquid carefully down the side of the trifle dish so the cake pieces are submerged. Refrigerate the trifle dish uncovered for 1 1/2 hours until it is partly set. It needs to be set enough so you can gently place a strawberry on it and it will stay on the surface. Proceed to Custard Layer steps.","images":[],"step":7},{"description":"Pour remaining warm jelly in a bowl and leave on the counter. DO NOT refrigerate.","images":[],"step":8},{"description":"Meanwhile, make the custard so it is ready to use (see below for how to make).","images":[],"step":9},{"description":"Remove trifle from fridge. Whisk the room temperature custard to loosen. Spoon onto the jelly, smooth surface, press against wall of glass to seal (stops jelly bleed so you get neat layers). Refrigerate uncovered for 1 hour until the surface has firmed up a bit - just enough to hold the jelly (jelly is soft, so custard doesn''t need to be fully set).","images":[],"step":10},{"description":"Partially set remaining jelly","images":[],"step":11},{"description":"Give the remaining jelly a good whisk then put it in the fridge at the same time to thicken a bit but not fully set. Refrigerate for 1 hour, but check at 30 minutes to ensure it isn''t setting too fast. The jelly should be sloppy but spoonable, scoops up in a small mound. If it fully sets, you''ll end up with a \"broken glass\" effect on the next jelly layer rather than a clear layer (read Note 5).","images":[],"step":12},{"description":"Remove trifle and jelly from fridge. Jelly should be sloppy. Carefully spoon over jelly, smooth surface. Scatter over 1 punnet halved strawberries (or half each raspberries and strawberries). Refrigerate for 3 hours+ (can leave in fridge for 48 hours, until ready to assemble).","images":[],"step":13},{"title":"Cream","description":"Beat cream, sugar and vanilla until softly whipped.","images":[],"step":14},{"description":"Once jelly is set, just before serving, top with cream, then pile over remaining berries. Dust with icing sugar.","images":[],"step":15},{"description":"Serve!! PS It is imperative to ensure every servings includes a bit of every layer in the trifle 😂","images":[],"step":16},{"description":"Homemade Custard:","images":[],"step":17},{"description":"Bring milk, ¼ cup sugar and vanilla to a simmer in a large saucepan over medium heat. Do not boil.","images":[],"step":18},{"description":"In a large bowl, whisk together remaining ¼ cup sugar and yolks, then whisk in cornflour until smooth.","images":[],"step":19},{"description":"While whisking, carefully pour in about ½ cup of milk mixture. Once mixed in, slowly pour in remaining milk while whisking. Once incorporated and smooth, pour back into saucepan.","images":[],"step":20},{"description":"Return saucepan to stove over low heat. Whisk constantly until it becomes thick and custardy – this will happen quite quickly, about 45 seconds (ie it is liquidy when you start, then suddenly it thickens). Once thickened, remove immediately from heat (it will continue to thicken as it cools).","images":[],"step":21},{"description":"Immediately pour into a bowl and cover with cling wrap, pressing onto surface. Leave on the counter to cool to room temp until trifle is ready to layer with custard. Makes 750ml. (Note 5)","images":[],"step":22}]', '["egg","milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dessert"],"cuisine":["British","Western"],"categories":["baking-recipes","dessert-recipes","egg-yolk-recipes","iconic-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4065f9fe052b', 'en', 'US', 'Never Ending Meringue Tranche (1.6 metres / 5.2 ft)', 'Recipe VIDEO below. Named as such because it can be made as long as you want!!! Light as air meringue that can be made days in advance, topped with cream and fresh fruit, this is less "risky" to make than Pavlova in the height of a hot, humid summer. A dessert spectacular that will be the talk of the town to years to come! Scale recipe by using slider on Servings (click & slide).', 'https://www.recipetineats.com/tachyon/2017/12/Never-Ending-Meringue-Tart-7.jpg', 25, 75, 100, 16, '[{"id": "ing_egg", "quantity": {"value": 15.0, "unit": "carton of 12"}}, {"id": "ing_sugar", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 2.4, "unit": "carton of 250ml"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_mango", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_strawberries", "quantity": {"value": 2.0, "unit": "punnet of 250g"}}, {"id": "ing_blueberries", "quantity": {"value": 3.6, "unit": "punnet of 125g"}}, {"id": "ing_sugar", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_mint", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["180 ml / 6 oz egg whites (, 5 to 6 eggs (Note 1))","300 g / 10 oz caster sugar (superfine sugar)"],"purpose":"Meringue:"},{"ingredients":["600 ml / 20 oz heavy whipping cream","1 tsp vanilla extract","3 tbsp caster sugar (superfine sugar)","2 large mangoes","500 g / 1 lb strawberries (2 punnets)","450 g / 15 oz raspberries and blueberries (mix and match, 3 Aus punnets in total together)"],"purpose":"Toppings:"},{"ingredients":["Icing sugar / powdered sugar (, for dusting (optional))","Chopped fresh mint"],"purpose":"Optional:"}]', '[{"description":"Preheat oven to 120C/250F (standard) or 100C/210F (fan/convection).","images":[],"step":1},{"description":"Mark 2 rectangles 11 x 40 cm / 4.5 x 15\" on a sheet of baking paper using pencil, with 2.5cm / 1\" between each outline. Repeat with another sheet of paper (so 4 outlines).","images":[],"step":2},{"description":"Find 2 baking trays large enough so the outline fits on the tray surface when the tray is turned upside down (rim gets in way of piping).","images":[],"step":3},{"description":"Fit a large piping bag with a 11mm / 0.5\" round nozzle. (Ziplock: Note 2)","images":[],"step":4},{"description":"Separate the egg whites while the eggs are fridge cold.","images":[],"step":5},{"description":"Place whites in a large clean, dry bowl. Whip until it all turns into foam and there''s no liquid whites left (1 minute on speed 8 with KitchenAide).","images":[],"step":6},{"description":"With the beater still going, add the sugar one heaped tablespoon at a time - about 1 minute.","images":[],"step":7},{"description":"After the sugar is added, crank the beater up to speed 10 and whip for 1 minute. Fluff should be glossy and when you rub between fingers, there should be barely any sugar grit - a bit is ok.","duration":1,"images":[],"step":8},{"description":"Tart (video is helpful):","images":[],"step":9},{"description":"Spoon half the meringue into piping bag (Note 3).","images":[],"step":10},{"description":"Dab small amount on the corner of an upside down baking tray. Place paper on tray pencil marking side down.","images":[],"step":11},{"title":"Pipe filling inside the lines","description":"don''t worry if there are gaps (loads in my video). Use dessert spoon to smooth surface - the base should be about 1/2 cm thick (rises to ~7 mm cooked).","images":[],"step":12},{"description":"Pipe blobs along one short end (to make tart ends) and all along both long sides. Do this to both on Tray 1. Place in oven.","images":[],"step":13},{"description":"Repeat with remaining meringues on Tray 2, but do not pipe blobs along the short end (these will be the middle pieces). Place in oven on shelf just below Tray 1.","images":[],"step":14},{"description":"Use any remaining meringue to make extra small blobs (good for repairs / decoration / nibbling). Place this tray on the floor of oven.","images":[],"step":15},{"description":"Bake for 45 minutes, then swap the two trays (tray with blobs not a priority, leave it!).","duration":45,"images":[],"step":16},{"description":"Bake for further 30 minutes, then turn off the oven, keep door closed and leave to cool (can keep in oven even for days). Meringue should be dry and crisp, able to lift off paper.","images":[],"step":17},{"description":"Place cream, vanilla and sugar in a bowl and whip until soft peaks form.","images":[],"step":18},{"description":"Trim joining ends of meringues with knife so they are straight.","images":[],"step":19},{"description":"Dab cream on cut end and join meringues. Assemble where you plan to serve.","images":[],"step":20},{"description":"Spread over cream, top with fruit, dust with sugar. Serve immediately, and puff up with pride when lavished with compliments!","images":[],"step":21}]', '["egg","milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["baking-recipes","dessert-recipes","dietary","easter-baking-desserts","egg-white-recipes","gluten-free-recipes","iconic-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_207fbb2df2c4', 'en', 'US', 'Homemade Gourmet Crackers', 'These are a copycat of Gourmet Crackers sold at my local shops which are so expensive to buy! For 1/5th of the price to buy, these are simple to make and they taste much better (having done side by side taste testing!). They last for at least a month in an airtight container, or you can keep the loaf in the freezer then slice and bake when desired. They taste sweet / savoury and are perfect with cheese. Customisable! Recipe VIDEO below.', 'https://www.recipetineats.com/tachyon/2017/12/Homemade-Gourmet-Crackers-3.jpg', 15, 75, 90, 40, '[{"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_cranberries", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.025, "unit": "tub of 200g"}}, {"id": "ing_rolled_oats", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_cup_sunflower_seeds", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_turmeric", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_cinnamon", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_nutmeg", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_rosemary", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}]', '[{"ingredients":["1 cup / 250 ml milk (any fat % cow''s milk)","¼ cup / 50g brown sugar (, packed)","¼ cup plain unsweetened yoghurt (I used Greek)","½ cup / 75g plain flour (all purpose)","½ cup / 75g whole wheat / wholemeal flour","½ cup dried cranberries (or other dried fruit of choice)","1 tsp baking soda / bi-carb (or 3 tsp baking powder)","½ cup rolled oats (or 1/3 cup more nuts of choice)","¼ cup sunflower seeds (or other seeds or nuts of choice)"]},{"ingredients":["½ tsp ground turmeric (can omit)","½ tsp cinnamon","¼ tsp nutmeg (or All Spice or 1/8 tsp cloves)","¼ tsp dried thyme","1 tsp dried rosemary (or ½ tsp more thyme)","¼ tsp salt","1/8 tsp black pepper"],"purpose":"Spices:"}]', '[{"description":"Preheat oven to 180C/350F (all oven types). Grease and line a small loaf tin with baking paper (mine is 21 x 11 x 7 cm / 8.5 x 4.5 x 3”) (Note 1).","images":[],"step":1},{"description":"Whisk the milk, sugar and yoghurt in a bowl.","images":[],"step":2},{"description":"In a separate bowl, add plain flour, wholemeal flour and cranberries. Stir – use fingers to break up cranberries if required.","images":[],"step":3},{"description":"Add remaining ingredients, including Spices, plus the milk mixture. It should be a thick batter, like muffin batter (note: batter in video looks slightly thicker because it was standing for a couple of minutes, doesn''t affect outcome).","images":[],"step":4},{"description":"Scrape/pour into tin. Bake for 25 minutes or until a skewer inserted into the middle comes out clean.","duration":25,"images":[],"step":5},{"description":"Cool on rack, then wrap in cling wrap and freeze for at least 2 hours, up to 3 months. (Note 2)","images":[],"step":6},{"description":"Unwrap loaf and allow to thaw partially so the outside is not rock hard frozen (around 20 minutes).","images":[],"step":7},{"description":"Preheat oven to 120C/250F (all oven types). Place one shelf in the middle, and another shelf beneath it.","images":[],"step":8},{"title":"Use a serrated bread knife to slice thinly","description":"around 2 mm / 1/12” thick (see video). Place biscuits on 2 large baking trays, you can squeeze them in as they won’t expand or stick.","images":[],"step":9},{"description":"Bake for 50 minutes or until they are a light brown, swapping trays halfway.","duration":50,"images":[],"step":10},{"title":"Leave biscuits on tray to cool","description":"they will harden so they snap when you break them. (Note 3)","images":[],"step":11},{"description":"Store in an airtight container for 4 weeks (probably ok for longer, I’ve only done 4 weeks). Brilliant served with creamy cheeses like brie, camembert, but soft, creamy blue cheeses is the ultimate pairing!","images":[],"step":12}]', '["gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["baking-recipes","finger-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e4d10fe42289', 'en', 'US', 'Blueberry Lemon Yoghurt Cake', 'An incredibly moist cake that''s bursting with fresh blueberries and bright lemon flavours, this is astonishingly quick to make! This cake is not overly sweet, so if you have a sweet tooth, add an extra 1/4 cup of sugar. Recipe VIDEO below.', 'https://www.recipetineats.com/tachyon/2017/11/Blueberry-Lemon-Yoghurt-Cake-6a.jpg', 10, 50, 60, 12, '[{"id": "ing_blueberries", "quantity": {"value": 3.0, "unit": "punnet of 125g"}}, {"id": "ing_flour", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 100.0, "unit": "bottle"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.3, "unit": "tub of 500g"}}, {"id": "ing_flour", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.133, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["375 g / 12 oz blueberries, fresh (, divided (3 punnets) (Note 1 for frozen))","1 tbsp plain flour (all purpose flour)"],"purpose":"Blueberries:"},{"ingredients":["1 1/4 cups / 275g white sugar (, preferably caster / superfine)","2/3 cup / 165ml vegetable or canola oil","2 eggs","1 ½ tbsp grated lemon rind","¼ cup / 65 ml lemon juice","1 cup / 250 g plain yoghurt (I use Greek)"],"purpose":"Wet:"},{"ingredients":["2 ¼ cups / 335g plain flour (all purpose flour)","4 tsp baking powder (Note 2 for baking soda / bi carb)","Pinch of salt"],"purpose":"Dry:"}]', '[{"description":"Preheat oven to 200C / 390F (standard) or 180C / 350F (fan / convection). Grease a 22 cm / 9” springform pan with butter, line base with baking paper.","images":[],"step":1},{"description":"Rinse blueberries, shake off excess water (but don’t pat dry). Set aside about 1/3 of the blueberries (for topping cake). Toss remaining blueberries in flour, set aside.","images":[],"step":2},{"description":"Whisk Wet in a large bowl. Add flour and salt, sprinkle over baking powder.","images":[],"step":3},{"title":"Whisk until just combined","description":"few small lumps is fine. Stir through blueberries (including loose flour in bowl). Pour into pan, top with remaining blueberries.","images":[],"step":4},{"description":"Place in oven, TURN DOWN to 180C/350F (standard) or 160C/320F (fan/convection). Bake 50 minutes or until skewer comes out clean. Remove sides of springform pan and cool on a rack, then once cool remove the base.","images":[],"step":5},{"description":"Sprinkle with icing sugar (powdered sugar). Serve!","images":[],"step":6}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["baking-recipes","blueberries","dessert-recipes","easter-baking-desserts","easter-brunch-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_47338e5e17cc', 'en', 'US', 'Pecan Pie', 'The great American classic! Watch the short recipe VIDEO which is very helpful for this recipe. The all-butter shortcrust pastry is flaky and delicate (see proof in video!), just as it should be - no shortening required. If you''re a pie first timer, consider using the egg pie crust which is a bit easier to roll out and handle - see recipe notes. The filling is a soft-set caramel custard with chopped up pecans and the top is decorated beautifully with whole pecans. Be still my beating heart.... this may be the mother of all pies!', 'https://www.recipetineats.com/tachyon/2017/11/Pecan-Pie.jpg', 30, 60, 90, 10, '[{"id": "ing_flour", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 115.0, "unit": "block of 250g"}}, {"id": "ing_water", "quantity": {"value": 2.5, "unit": "L"}}, {"id": "ing_pecans", "quantity": {"value": 1.25, "unit": "unit"}}, {"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 115.0, "unit": "block of 250g"}}, {"id": "ing_corn", "quantity": {"value": 0.281, "unit": "can of 400g"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_bourbon", "quantity": {"value": 3.0, "unit": "unit"}}]', '[{"ingredients":["1¼ cups plain white flour (all purpose flour)","¼ tsp salt","2 tsp white sugar","115 g / 1 stick unsalted butter (, cold, cut into 1cm/ ⅓\" cubes)","2.5 - 3 tbsp ice cold water"],"purpose":"Pie Crust (or 9″ store bought) (Note 1):"},{"ingredients":["1 1/4 cups pecans (, enough to decorate top)","1 1/4 cup pecans (for filling)"],"purpose":"Pecans:"},{"ingredients":["3 eggs","1 cup / 200g brown sugar, packed","60 g / 4 tbsp unsalted butter (, melted)","3/4 cup / 185 ml light corn syrup (Note 2 for subs)","1 tsp vanilla extract","¼ tsp salt","3 tbsp bourbon (or rum or marsala, or other liquor of choice, or omit)"],"purpose":"Filling:"}]', '[{"description":"Place flour, salt and sugar in a food processor. Pulse twice.","images":[],"step":1},{"description":"Scatter over butter. Pulse 5 times or until the largest pieces are the size of peas.","images":[],"step":2},{"description":"Turn food processor on low and add 2.5 tbsp water, keep blitzing for 7 to 10 seconds until it forms crumbly clumps (see video). Pinch with your fingers - it should come together - if not, add 1/2 tbsp water until it does. Don''t blitz longer than 20 seconds.","duration":0.14166666666666666,"images":[],"step":3},{"description":"Turn out crumbs onto work surface, use hands to bring together into a ball then pat into a 1.5cm / 1/2\" thick disc. Wrap in cling wrap and refrigerate for 30 minutes.","duration":30,"images":[],"step":4},{"description":"Preheat oven to 180C/350F (standard) / 160C / 320F (fan / convection).","images":[],"step":5},{"description":"Scatter 1 1/4 cups pecans on baking tray and bake for 3 to 5 minutes or until you smell them.","duration":4,"images":[],"step":6},{"description":"Remove from oven and roughly chop. Set aside.","images":[],"step":7},{"title":"Remaining 1 1/4 cups don''t need toasting","description":"they are for the top.","images":[],"step":8},{"description":"Pie Crust Rollling Out (video helpful):","images":[],"step":9},{"description":"Dust work surface with flour.","images":[],"step":10},{"description":"Place dough on work surface, dust top with flour. Roll out into 25cm/12\" circle, patching up cracks as required. Remember: the crumblier the dough, the more flaky your pastry which is GOOD!","images":[],"step":11},{"description":"Roll the pastry onto your rolling pin, then roll it out onto a 22cm / 9\" pie tin. Press in, then trim edges with scissors with a 1cm / 0.3\" overhang.","images":[],"step":12},{"description":"Turn the edges under and press down neatly. Crimp if desired (see video).","images":[],"step":13},{"description":"Place 2 large pieces of baking paper over the pie crust then fill with pie weights or dried beans or rice. Weight is essential to avoid shrinking pastry.","images":[],"step":14},{"description":"Bake 20 minutes, then remove pie weights and let the pastry cool for 5 minutes before filling.","duration":5,"images":[],"step":15},{"description":"Whisk eggs in a large bowl. Add remaining Filling ingredients and whisk until smooth.","images":[],"step":16},{"description":"Stir through chopped pecans.","images":[],"step":17},{"title":"Pour into crust","description":"it should fill it about 1 cm / 2/5\" from the top (you may have excess if your pastry shrank).","images":[],"step":18},{"description":"Top with whole pecans in desired pattern.","images":[],"step":19},{"description":"Place pie in oven. Bake for 50 minutes, checking at 40 minutes, until it doesn''t jiggle much when you shake it but the centre is still soft when you touch it (see video).","duration":50,"images":[],"step":20},{"description":"It will be puffed and cracks will look extreme, but it will deflate as it cools. If your pastry / pecans are browning too quickly, cover with foil.","images":[],"step":21},{"description":"Serving / Storing:","images":[],"step":22},{"description":"Cool completely before serving, to allow the custard to set - 2 - 4 hours.","images":[],"step":23},{"description":"Slice, and serve with ice cream or cream if desired - I don''t need either!","images":[],"step":24},{"title":"Store in an airtight container","description":"great for 2 days, but I''m perfectly happy with mine even after 4.","images":[],"step":25}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":[],"categories":["baking-recipes","dessert-recipes","sweet-pies"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6e988948bba9', 'en', 'US', 'Stay-Fresh Apple Muffins!', 'Recipe VIDEO above. These muffins are a miracle - they stay fresh for 4 to 5 days!! KEY TIP: Do not over mix batter (causes dry muffin), stir until flour is just incorporated, few lumps is fine. This recipe will work with cup measures regardless of which country you are in, with the exception of Japan - please use weights provided.', 'https://www.recipetineats.com/tachyon/2017/10/Apple-Muffins-1-recropped.jpg', 10, 20, 30, 11, '[{"id": "ing_apples", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.167, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.025, "unit": "tub of 200g"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}]', '[{"ingredients":["2 level cups apple pieces (peeled) (, 0.7 cm / 1/3\" cubes (2 large apples, I use red))","1 tbsp melted butter (, for muffin tim (or use paper liners))"]},{"ingredients":["115g / 0.5 cup unsalted butter (, melted (1 stick))","1 cup (200g) brown sugar (, packed)","2/3 cup (165 ml) milk (low fat, full fat, non dairy also fine)","1 large egg (approx 60g / 2 oz)","1 tsp white vinegar (or any other clear vinegar)"],"purpose":"Wet:"},{"ingredients":["2 cups (300g) wholemeal flour (wholewheat flour)(white also ok, Note 1)","1 tsp baking soda (bi carb) (NOT baking powder)","1 tsp cinnamon powder","Pinch salt"],"purpose":"Dry:"},{"ingredients":["2 tbsp raw sugar (demerara sugar - large granules)"],"purpose":"Topping (optional):"}]', '[{"description":"Preheat oven to 200C/390F.","images":[],"step":1},{"description":"Brush a 12 hole, standard muffin tin with melted butter, or line with paper cases. (Note 3)","images":[],"step":2},{"description":"Place butter and brown sugar in a bowl, whisk to combine.","images":[],"step":3},{"description":"Add milk, then egg and vinegar. Whisk to combine.","images":[],"step":4},{"description":"Scatter flour across batter surface, followed by baking soda, cinnamon and salt. Whisk 10 times until the flour is incorporated - some lumps is fine.","images":[],"step":5},{"description":"Stir through apple -minimum stirs just to disperse.","images":[],"step":6},{"title":"Scoop batter into muffin tin","description":"I use an ice cream scoop - filling it all the way to the top. If using a scooper, leave it the slight ball shape (see video) - don''t smooth the top. You should get 12 (see Note 3).","images":[],"step":7},{"title":"Sprinkle with sugar (if using","description":"makes surface slightly crispy), place muffins in the oven.","images":[],"step":8},{"description":"Immediately turn down to 180C/350F.","images":[],"step":9},{"description":"Bake for 20 minutes (standard) or 18 minutes (fan / convection) , or until a skewer comes out clean.","duration":20,"images":[],"step":10},{"description":"Rest in the muffin tin for 5 minutes then transfer to a rack to cool.","duration":5,"images":[],"step":11},{"title":"Once fully cooled, store in an airtight container","description":"it will stay moist for up to 5 days. These also freeze very well.","images":[],"step":12}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["baking-recipes","cupcakes-and-muffins","dessert-recipes","easter-brunch-recipes","muffin-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1e0f006fc067', 'en', 'US', 'Butter Cake (Vanilla Sponge Cak)', 'Recipe video above. An exceptional, classic butter cake made with basic pantry staples. Tender crumb, moist, keeps well for 3 days. Slightly adapted from a Cook''s Illustrated master recipe - refer to notes. I prefer making this recipe using a handheld beater rather than a stand mixer.Want to step it up? Try my very best Vanilla Cake.', 'https://www.recipetineats.com/tachyon/2017/09/Vanilla-Sponge-Cake-2.jpg', 15, 25, 40, 12, '[{"id": "ing_butter", "quantity": {"value": 225.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 333.333, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.2, "unit": "bottle of 50ml"}}, {"id": "ing_flour", "quantity": {"value": 0.263, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.094, "unit": "pack of 400g"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.067, "unit": "tub of 150g"}}, {"id": "ing_sugar", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 2.5, "unit": "carton of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_strawberries", "quantity": {"value": 1.6, "unit": "punnet of 250g"}}]', '[{"ingredients":["225 g / 2 sticks unsalted butter (, cut into 8 pieces and softened)"]},{"ingredients":["4 large eggs ((55 - 65g / 2 - 2.5 oz each), at room temperature)","1/2 cup / 125 ml milk ((whole or low fat, not no fat), room temperature)","2 tsp vanilla extract"],"purpose":"Wet:"},{"ingredients":["1 3/4 cups / 265g plain flour (all purpose flour, 7 oz) (Note 1)","1/4 cup cornflour / cornstarch (Note 1)","2 tsp baking powder","1 1/2 cups / 330g caster sugar / superfine sugar (normal white sugar also ok)","3/4 tsp salt"],"purpose":"Dry:"},{"ingredients":["2 1/2 cups / 625 ml whipping cream","2 tbsp white sugar","1 tsp vanilla extract","400 g/ 14 oz strawberries (, halved (1 1/2 punnets))"],"purpose":"Strawberries & Cream:"}]', '[{"description":"Preheat oven to 180C/350F (standard) or 160C/320F (fan / convection). Put the rack in the middle of the oven.","images":[],"step":1},{"description":"Butter 2 x 20cm / 8\" cake pans (Note 2). Line the base with baking paper.","images":[],"step":2},{"description":"Place Wet ingredients in a bowl and whisk to combine.","images":[],"step":3},{"description":"Place Dry ingredients in a bowl and use a handheld beater on speed 1 (slowest) to quickly whisk.","images":[],"step":4},{"description":"Add 1/3 of the butter, then put the beater whisk in the butter, and mix using speed 1. Once the butter is incorporated a bit, speed up to 5 and whisk for 10 seconds.","duration":0.16666666666666666,"images":[],"step":5},{"description":"Add another 1/3 of the butter then repeat, then add remaining butter and repeat again. It should look like wet sand (see video / photos in post).","images":[],"step":6},{"description":"Add half the Wet mixture, beat until incorporated. Add remaining Wet mixture, then beat on speed 5 (medium) until almost completely smooth.","images":[],"step":7},{"description":"Divide between cake pans, smooth surface (it levels out in the oven), then bake for 25 minutes.","duration":25,"images":[],"step":8},{"description":"A skewer inserted into the middle should come out clean but moist.","images":[],"step":9},{"description":"Cool on cooling rack for at least 15 minutes then remove cake from pan.","images":[],"step":10},{"description":"Frosting / Decorating with Strawberries & Cream:","images":[],"step":11},{"title":"Optional","description":"Use a serrated knife (I use a bread knife) to cut the top off each cake to make it completely flat. This makes neat layers when you cut into the cake.","images":[],"step":12},{"description":"Place cream, vanilla and sugar in a bowl. Beat on high with a handheld beater or stand mixer until firm peaks form.","images":[],"step":13},{"description":"If piping little swirls around the edge like in the photos, transfer 1 cup of cream into a piping bag fitted with a large star nozzle.","images":[],"step":14},{"description":"Place a cake on a serving platter. Spread a thin layer of cream over the top.","images":[],"step":15},{"description":"Cover with strawberries, cut side down.","images":[],"step":16},{"description":"Top with 1/3 of the cream.","images":[],"step":17},{"description":"Place 2nd cake on top. Cover top and sides with remaining cream. Pipe cream around the edge.","images":[],"step":18},{"description":"Decorate with remaining strawberries, as desired.","images":[],"step":19}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":[],"categories":["baking-recipes","classic-cakes","dessert-recipes","easter-baking-desserts","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c95cb34e6d8a', 'en', 'US', 'World''s Best Easy Peanut Butter Cookies', 'A better version of the popular 3 ingredient peanut butter cookies! By switching white sugar with brown sugar, these cookies are SOFT and CHEWY instead of crumbly and crisp. They aren''t dense and gluggy, which one might expect because they are made without flour - see the inside of the cookie in the photo in the post. They are not too sweet and they truly taste of peanut butter (rarer than you might think!). Recipe VIDEO below.', 'https://www.recipetineats.com/tachyon/2017/09/Peanut-Butter-Cookies-3-Ingredients-5.jpg', 10, 10, 20, 14, '[{"id": "ing_peanut_butter", "quantity": {"value": 0.4, "unit": "jar of 375g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}]', '[{"ingredients":["1 cup / 265 g peanut butter (, smooth or crunchy - commercial spread, NOT pure peanut butter (I use Bega) (Note 1))","200 g/ 1 cup , packed, brown sugar (Note 2)","1 egg"]}]', '[{"description":"Place ingredients in a bowl and mix to combine. It will be soft, too soft for scooping. Refrigerate for 10 minutes.","duration":10,"images":[],"step":1},{"description":"Meanwhile, preheat oven to 180C / 350F (standard) or 160C/320F (fan / convection).","images":[],"step":2},{"description":"Line 2 trays with parchment paper.","images":[],"step":3},{"description":"Place 1 tbsp scoops of the dough onto the trays (I use a cookie scoop) 5cm/2\" apart.","images":[],"step":4},{"description":"Dip a large fork in a bowl of hot tap water (stops fork sticking to dough). Press down on the dough, then press 90 degrees the other way (watch video) so the cookie is 1 cm / 2/5\" thick. Re-dip fork in water as required.","images":[],"step":5},{"description":"Put both trays in the oven and bake for 10 minutes, swapping the trays halfway through, or until light golden on the surface and golden on the edges. (Or longer if you want crisper cookies)","duration":10,"images":[],"step":6},{"description":"Leave to cool on the tray. Store in an airtight container for up to 4 - 5 days.","images":[],"step":7}]', '["egg","peanuts"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["baking-recipes","cookies","dessert-recipes","dietary","gluten-free-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_097cc8c011f1', 'en', 'US', 'Salted Caramel Tart', 'Recipe video above. This is made using the Australian way of making creamy caramel using condensed milk mixed with a traditional caramel made with butter and sugar. It is the same method for Caramel Slice. You don’t need a candy thermometer, and the caramel sets perfectly so it is beautifully soft and doesn’t run everywhere when you cut it. The topping is a chocolate ganache that is soft and melds into the caramel with every bite. This is decadent and luxurious, yet straight forward to make. Great show of dessert!!!', 'https://www.recipetineats.com/tachyon/2017/08/Salted-Caramel-Tart-3.jpg', 15, 25, 40, 12, '[{"id": "ing_plain_sweet_biscuits", "quantity": {"value": 225.0, "unit": "pack"}}, {"id": "ing_butter", "quantity": {"value": 150.0, "unit": "block of 250g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.009, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.333, "unit": "carton of 250ml"}}, {"id": "ing_chocolate", "quantity": {"value": 150.0, "unit": "block of 100g"}}, {"id": "ing_chilli_flakes", "quantity": {"value": 0.219, "unit": "jar of 40g"}}]', '[{"ingredients":["225g / 8 oz plain sweet biscuits, about 2 cups (packed) crushed (Arnott’s Marie Crackers, Graham Crackers, Note 1 for Digestives)","150g / 10 tbsp unsalted butter (, melted (Note 1 for Digestives))"],"purpose":"Base:"},{"ingredients":["100g / 7 tbsp unsalted butter","1 cup brown sugar (tightly packed cup)","2 cans sweetened condensed milk (395g / 14oz each can)","1 3/4 tsp salt (2 ½ - 3 tsp salt flakes)"],"purpose":"Caramel:"},{"ingredients":["1/3 cup thickened cream ((heavy cream), or any cream 30%+ fat)","150g / 5 oz dark chocolate melts / chips","Sea salt flakes (, for topping (recommended))"],"purpose":"Chocolate Ganache Topping:"}]', '[{"description":"Preheat oven to 180*C/350°F (160°C fan-forced). Grease and line the base only of a 23cm / 9\" tart tin with a loose base. (Or a springform pan of a similar size)","images":[],"step":1},{"title":"Blitz biscuits","description":"Roughly break up biscuits and place in a food processor, then whizz until fine crumbs form. Or do this step with a ziplock bag and rolling pin.","images":[],"step":2},{"title":"Press","description":"Pour crumbs into a bowl, add melted butter, mix until it looks like wet sand and no dry crumbs remain. Pour into tin, then press firmly into base and sides – use something flat like a cup to assist (refer to video).","images":[],"step":3},{"title":"Bake & cool","description":"Transfer to tray (safe handling), place in oven and bake for 10 minutes, then remove and cool slightly (5 minutes in fridge).","duration":10,"images":[],"step":4},{"description":"Melt butter in a large saucepan over medium heat. Add sugar and whisk to combine – butter may not incorporate fully.","images":[],"step":5},{"title":"Whisk","description":"Once it starts bubbling and the sugar is completely melted, pour in the condensed milk, whisking as you go. Whisk constantly until you see steam coming off the caramel (~ 4 minutes), then remove from heat.","images":[],"step":6},{"title":"Pour into base","description":"Add salt (adjust to taste), then pour the caramel into the tart base.","images":[],"step":7},{"description":"Bake for 15 minutes or until the edges of the caramel surface is golden and the surface has a “skin” on it, but the caramel is still soft and the centre jiggles slightly (see video for demo.)","duration":15,"images":[],"step":8},{"description":"Cool on counter while you make the chocolate.","images":[],"step":9},{"description":"Chocolate Ganache:","images":[],"step":10},{"title":"Melt chocolate","description":"Place cream and chocolate in a heat proof bowl. Microwave in 2 x 30 second bursts, stirring in between, until smooth.","images":[],"step":11},{"title":"Cool then pour","description":"Set aside for 10 minutes to thicken slightly, then pour over the base. Smooth top or make swirls like I did (just wait until the chocolate thickens slightly). Sprinkle with sea salt flakes.","duration":10,"images":[],"step":12},{"description":"Refrigerate for 1 ½ hours to allow chocolate to set. Then remove and bring to room temperature before slicing to serve. Handle carefully when sliding the tart off the base - or just leave it on to be safe and just remove the sides.","images":[],"step":13}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","dessert-recipes","easter-baking-desserts"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0d53c9f42627', 'en', 'US', 'Flourless Chocolate Cake', 'Recipe video above. Typically, flourless chocolate cakes are made by beating egg whites until stiff then folding through the batter. Such cakes rise when baking, but then it sinks once cooled, creating a “crater” on the surface and a slightly denser cake. This recipe made using a touch of baking powder yields are slightly fluffier cake – plus it’s far easier and quicker, and the cake has a fairly level surface. The surface has a thin crackly layer like brownies (GF version here) and the inside is lovely and moist. This cake is also quite forgiving - no need for measuring ingredients to the exact gram. After this one, try this GF Whole Orange Cake that readers from all over have fallen in love with!', 'https://www.recipetineats.com/tachyon/2017/07/Flourless-Chocolate-Cake.jpg', 10, 45, 55, 10, '[{"id": "ing_chocolate", "quantity": {"value": 1.5, "unit": "block of 100g"}}, {"id": "ing_butter", "quantity": {"value": 120.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 250.0, "unit": "carton of 12"}}, {"id": "ing_vanilla", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_cocoa_powder", "quantity": {"value": 0.15, "unit": "pack of 250g"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.017, "unit": "tub of 150g"}}, {"id": "ing_almonds", "quantity": {"value": 1.2, "unit": "pack of 250g"}}]', '[{"ingredients":["1 1/2 cups dark chocolate chips (Note 1)","120g / 1 stick unsalted butter (, melted)","3/4 cup white sugar","3 large eggs (at room temperature (60g/2oz each+) (Note 2))","1 tsp vanilla","1/4 cup cocoa powder (, sfited (preferably Dutch processed i.e. the more expensive stuff))","1/2 tsp baking powder","2 cups almond meal / almond flour (or hazelnut flour)"]}]', '[{"description":"Preheat oven to 180C/350F (160°C fan).","images":[],"step":1},{"description":"Butter and line a 20cm / 8\" spring form pan.","images":[],"step":2},{"description":"Melt chocolate and butter in microwave in 30 second bursts, stirring in between until smooth.","images":[],"step":3},{"description":"Whisk in sugar. Add eggs and vanilla, whisking well until combined,","images":[],"step":4},{"description":"Switch to wooden spoon. Add cocoa powder, baking powder and almond meal, fold through until just combined.","images":[],"step":5},{"description":"Pour batter into pan, bake 45 min until top has thin crust and skewer comes out clean, not smeared with batter.","images":[],"step":6},{"description":"Cool cake in the pan for 10 minutes, then remove sides. Cool completely on rack before carefully removing base.","duration":10,"images":[],"step":7},{"description":"Dust with cocoa powder then serve. I served mine with strawberries and dollop cream, but it doesn''t need it!","images":[],"step":8}]', '["egg","gluten","milk","nuts"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","classic-cakes","dessert-recipes","dietary","easter-baking-desserts","gluten-free-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_24e1ead3f5a2', 'en', 'US', 'No Knead Cinnamon Rolls', 'Soft, fluffy cinnamon rolls made from scratch with a dump-and-mix dough that requires no kneading! Frosted with a sticky cream cheese glaze, these are sweet but nowhere near as sickly sweet as store bought ones. This recipe is quite forgiving - see notes. Instructions are long because I''m providing helpful hints but this recipe is actually quite straight forward! Recipe video below.', 'https://www.recipetineats.com/tachyon/2017/06/Cinnamon-Rolls-11.jpg', 20, 20, 40, 12, '[{"id": "ing_yeast", "quantity": {"value": 3.0, "unit": "pack of 5 sachets"}}, {"id": "ing_sugar", "quantity": {"value": 0.07, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_flour", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.75, "unit": "jar of 40g"}}, {"id": "ing_cream_cheese", "quantity": {"value": 90.0, "unit": "block of 250g"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.07, "unit": "kg"}}]', '[{"ingredients":["1 tbsp dry yeast (Note 1)","70 g / 1/3 cup caster sugar ((superfine sugar), or sub with normal white sugar)","1/2 cup / 125 ml warm water (Note 2)","600 g / 20 oz plain flour / all purpose flour (4 1/2 US Cups, 4 Cups everywhere else exc Japan) (Note 3)","1/2 tsp salt","1 cup / 250 ml milk (, lukewarm, whole or low fat, (Note 2))","50 g / 3.5 tbsp unsalted butter (, melted and slightly cooled)","2 large eggs (, beaten with fork)"],"purpose":"Buns:"},{"ingredients":["1/4 cup / 35g plain flour ((all purpose flour), plus more as required)"],"purpose":"EXTRA FLOUR:"},{"ingredients":["90 g / 6 tbsp unsalted butter (, melted)","1 cup / 220 g brown sugar (, packed)","2 tbsp cinnamon powder"],"purpose":"For Rolls:"},{"ingredients":["90 g / 3 oz cream cheese (, softened)","50 / 3 tbsp unsalted butter (, softened)","1 tsp vanilla extract (or essence)","1 1/4 cups / 150g soft icing sugar / powdered sugar","2 - 3 tbsp milk (, any (or water))"],"purpose":"Cream Cheese Glaze:"}]', '[{"description":"Place the yeast and 2 teaspoons of the sugar in a medium bowl, then pour in water. Leave for 5 minutes until it froths.","duration":5,"images":[],"step":1},{"description":"Place 600g/20oz flour, remaining sugar and salt in a bowl. Mix to combine.","images":[],"step":2},{"description":"Make a well in the centre. Add milk, butter, eggs and pour in the yeast liquid, including all froth.","images":[],"step":3},{"title":"Mix until combined with wooden spoon","description":"it will be like a sticky muffin batter, not kneadable.","images":[],"step":4},{"title":"Rise # 1","description":"Cover with cling wrap and place in a warm place (25C/77F+) to rise for around 1 1/4 - 1 1/2 hrs or until almost tripled in volume. (Note 4) Dough surface should be bubbly (see video or photos in post).","images":[],"step":5},{"description":"Making Rolls & Rise #2 (video is helpful):","images":[],"step":6},{"description":"Line a 31.5 x 23.5 cm / 9 x 13\" tray with baking paper with overhang.","images":[],"step":7},{"description":"Mix cinnamon and sugar in a bowl.","images":[],"step":8},{"description":"Uncover dough, mix with spoon to deflate.","images":[],"step":9},{"description":"Sprinkle half Extra Flour on work surface, pour dough on, sprinkle over remaining Extra Flour. Use hands to incorporate the flour into the dough - it may not absorb it all (or need more), the dough will stop absorbing flour when it''s no longer sticky, should be soft, pliable.","images":[],"step":10},{"description":"If work surface is now flour free, sprinkle with more flour.","images":[],"step":11},{"description":"Shape dough into log, then roll out into 28 x 48 cm / 11 x 19\" rectangle.","images":[],"step":12},{"description":"Pour over butter, then brush all over, then sprinkle with cinnamon sugar.","images":[],"step":13},{"description":"Roll up firmly, then shape into an even log.","images":[],"step":14},{"description":"Cut into 12 pieces (4cm / 1.6\"), then place on tray (3 x 4).","images":[],"step":15},{"description":"Cover with tea towel then place in warm place for 40 minutes or until almost doubled.","duration":40,"images":[],"step":16},{"description":"Baking / Frosting:","images":[],"step":17},{"description":"Preheat oven to 180C/350F (standard) or 160C/320F (fan / convection). Place shelf in the middle of the oven.","images":[],"step":18},{"description":"Bake for 20 minutes, rotating the tray at 16 minutes.","duration":20,"images":[],"step":19},{"description":"Buns are ready when the middle rolls are golden and the outer ones are deep golden on the edges. Tap the middle ones - they should sound hollow.","images":[],"step":20},{"title":"Optional","description":"Brush with 1 tbsp / 15g melted butter to remove any residual flour spots.","images":[],"step":21},{"description":"Use paper overhang to lift rolls onto cooling rack (key step - Note 5). Cool for 1 hour (will still be warm).","images":[],"step":22},{"description":"Use a spoon to frost with glaze. Best served warm!","images":[],"step":23},{"description":"Place butter, cream cheese and vanilla in a bowl. Beat until smooth (10 - 15 seconds).","images":[],"step":24},{"description":"Add icing sugar, beat to incorporate. Add enough milk to make it a consistency that can be spooned over the buns and it drips slightly (see video).","images":[],"step":25}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":[],"categories":["baking-recipes","breads","dessert-recipes","easter-baking-desserts","easter-brunch-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b7252e09e182', 'en', 'US', 'Soft Easy Chocolate Chip Cookies', 'RECIPE VIDEO ABOVE. This is my I need chocolate chip cookies now recipe that makes soft, buttery cookies. No waiting for butter to soften, no electric beater, no refrigeration time, no rolling dough into balls. The hardest part is waiting for them to cool!Adapted from Cooks Illustrated. Makes 13 large or 26-30 small. {This recipe will work no matter which country you live in - see Note 5. High altitude baking - see Note 6.} Note: For my Rolls Royce Chocolate Chip Cookies, see here (it requires overnight refrigeration and worth the wait!).', 'https://www.recipetineats.com/tachyon/2017/06/Soft-Chocolate-Chip-Cookies-3.jpg', 10, 22, 32, 13, '[{"id": "ing_flour", "quantity": {"value": 0.263, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.005, "unit": "tub of 200g"}}, {"id": "ing_butter", "quantity": {"value": 175.0, "unit": "block of 250g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.2, "unit": "bottle of 50ml"}}, {"id": "ing_chocolate", "quantity": {"value": 1.25, "unit": "block of 100g"}}]', '[{"ingredients":["1 3/4 cups plain / all purpose flour","1 tsp salt","½ tsp baking soda (bi carb soda)","175g / 12 tbsp unsalted butter (, cut into 2 cm/ 4/5\" cubes (1.5 US sticks / 6 oz))","1/2 cup brown sugar (, packed (light or dark) (Note 1))","1/2 cup caster sugar (US: granulated sugar)","1 egg","1 egg yolk","2 tsp vanilla extract","1 1/4 cups chocolate chips (, separated (US: semi sweet chocolate chips or chunks))"]}]', '[{"description":"Preheat oven to 180C / 350F (standard) or 160C/320F (fan / convection). Place oven shelf in the middle of the oven.","images":[],"step":1},{"description":"Line 2 trays with baking / parchment paper.","images":[],"step":2},{"description":"Whisk the flour, salt and baking soda in a bowl.","images":[],"step":3},{"description":"Place the butter in a large heatproof bowl. Microwave until the butter is almost fully melted (25 sec for room temp butter, 40 sec for fridge cold butter on high).","images":[],"step":4},{"description":"Whisk to finish melting the butter. (Note 2)","images":[],"step":5},{"description":"Add brown and white sugar, whisk energetically for 15 seconds.","duration":0.25,"images":[],"step":6},{"description":"Add egg, yolk and vanilla, whisk well for 15 seconds.","duration":0.25,"images":[],"step":7},{"description":"Add flour mixture and mix until flour is almost fully incorporated.","images":[],"step":8},{"description":"Add 1 cup chocolate chips, stir to disperse and flour is fully incorporated. Batter will be quite loose.","images":[],"step":9},{"description":"Stand for 5 minutes for batter to firm up a bit so it is scoop-able into mounds. (Note 3)","duration":5,"images":[],"step":10},{"title":"LARGE COOKIES","description":"Scoop up a level ice cream scoop / 3 tbsp / 1/4 cup (Note 4) and place on baking trays 5cm / 2\" apart - 13 balls. Top with remaining choc chips (these remain on surface once baked = prettier).","images":[],"step":11},{"title":"SMALL COOKIES (26","description":"30): Scoop up 1.5 tbsp (heaped tbsp measure) OR 1/2 an ice cream scoop (this works well). Place on baking trays 4cm / 1.75\" apart, top with choc chops.","images":[],"step":12},{"title":"Bake 1 tray at a time. LARGE COOKIES","description":"Bake for 8 minutes, then rotate the tray and bake for 3 minutes (11 minutes in total). SMALL COOKIES: Bake 6 minutes, turn then bake 3 minutes (9 min total). The cookies should be just golden on the edges and pale golden on top. They will be slightly puffed up.","duration":8,"images":[],"step":13},{"title":"Cool on the tray","description":"they finish cooking. They will lose the puffiness while resting. Dig in and get your cookie fix!","images":[],"step":14}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","cookies","dessert-recipes","egg-yolk-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_defbebbc9efa', 'en', 'US', 'Best Easy Chocolate Cupcakes', 'Recipe video above. These cupcakes are deeply chocolatey, they''re moist - and stay moist for 3 days - and have a terrific tender crumb. It''s extremely simple to make - no creaming butter, no beater required. By far the best chocolate cupcakes I''ve ever had made with such little effort!', 'https://www.recipetineats.com/tachyon/2017/05/Chocolate-Cupcakes11.jpg', 15, 20, 30, 12, '[{"id": "ing_flour", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.013, "unit": "tub of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 120.0, "unit": "block of 250g"}}, {"id": "ing_chocolate", "quantity": {"value": 60.0, "unit": "block of 100g"}}, {"id": "ing_cocoa_powder", "quantity": {"value": 0.3, "unit": "pack of 250g"}}, {"id": "ing_milk", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_sprinkles", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["3/4 cup plain/all purpose flour","3/4 cup caster sugar (super fine sugar, or sub with normal white sugar)","1/2 tsp baking soda / bi carbonate soda (Note 1)","Pinch of salt"],"purpose":"Dry:"},{"ingredients":["120g / 8 tbsp unsalted butter (, cut into 1\" / 2cm pieces (1 US stick / 1/2 cup))","60g / 2 oz dark chocolate (, preferably 70%+ cocoa, broken into pieces (Note 2))","1/2 cup cocoa powder (, preferably Dutch processed (Note 3))","1/2 cup milk","1/4 cup vegetable oil (or other neutral flavour oil)","2 large eggs (55 - 60g / 2 oz each)","1 tsp vanilla extract","1 1/2 tsp white vinegar"],"purpose":"Wet:"},{"ingredients":["120g / 8 tbsp unsalted butter (, cut into 1\" / 2cm pieces (1 US stick / 1/2 cup))","1/2 cup cocoa powder (, preferably Dutch processed)","2 1/2 cups soft icing sugar / powdered sugar (NOT pure icing sugar)","3 - 4 tbsp milk (any)","Sprinkles and other decorations, if desired"],"purpose":"Chocolate Fudge Frosting:"}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan). Put oven rack in the middle of the oven.","images":[],"step":1},{"description":"Place 12 cupcake liners in a cupcake tin.","images":[],"step":2},{"description":"Sift Dry ingredients into a bowl. Whisk briefly.","images":[],"step":3},{"description":"Place butter and chocolate in a separate, large heatproof bowl. Microwave for 45 seconds, mix, then microwave for another 30 seconds. Mix until chocolate is melted and smooth (keep microwaving in 20 sec bursts if chocolate not melted).","duration":0.75,"images":[],"step":4},{"description":"Add cocoa powder and mix.","images":[],"step":5},{"description":"Add milk and oil, then eggs, vanilla and vinegar. Whisk until smooth.","images":[],"step":6},{"description":"Add flour mixture and whisk until lump free.","images":[],"step":7},{"description":"Divide mixture between cupcake liners. I use a ice cream scoop for this. They should be just over 3/4 full.","images":[],"step":8},{"title":"Bake for 18","description":"20 minutes, or until skewer inserted into the cupcake in the middle of the tray comes out clean.","duration":19,"images":[],"step":9},{"description":"Remove from oven and immediately transfer to cooling rack (spoon or knife helps).","images":[],"step":10},{"description":"Once cool, spread with frosting and decorate with sprinkles if desired. Alternatively, use Chocolate Buttercream Frosting!","images":[],"step":11},{"description":"Speedy Chocolate Fudge Frosting:","images":[],"step":12},{"description":"Melt butter then mix in cocoa powder until smooth.","images":[],"step":13},{"description":"Add icing sugar and milk. Mix until smooth. Use milk to adjust consistency if required - it should be a soft spreadable consistency (like peanut butter).","images":[],"step":14}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["baking-recipes","cupcakes-and-muffins","dessert-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_74cac2173a11', 'en', 'US', 'SOFT NO KNEAD Dinner Rolls', 'Recipe video above. These soft dinner rolls are like magic! Just mix the ingredients in a bowl - no kneading, no stand mixer, no special ingredients required. These are soft, fluffy and moist, nicely salted with a touch of sweet. This requires 2 hrs 15 minutes+ rise time.', 'https://www.recipetineats.com/tachyon/2017/04/No-Knead-Bread-Rolls_5.jpg', 10, 15, 25, 12, '[{"id": "ing_yeast", "quantity": {"value": 3.0, "unit": "pack of 5 sachets"}}, {"id": "ing_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_bread", "quantity": {"value": 0.75, "unit": "loaf"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}]', '[{"ingredients":["1 tbsp dry yeast (Note 1)","1/4 cup caster/superfine sugar (, or sub with normal white sugar)","1/2 cup warm water (Note 2)","4 cups bread flour + extra for dusting (Note 3)","1 1/2 tsp salt (, cooking/kosher salt)","1 cup milk, (lukewarm, whole or low fat, (Note 2))","50g / 3 1/2 tbsp unsalted butter (, melted and cooled)","2 eggs (, at room temperature, beaten with fork)"],"purpose":"Buns:"},{"ingredients":["1 tbsp butter (, melted)"],"purpose":"Brushing:"}]', '[{"description":"Place the yeast and 2 teaspoons of the sugar in a medium bowl, then pour in water. Leave for 5 minutes until it froths.","duration":5,"images":[],"step":1},{"description":"Place flour, remaining sugar and salt in a bowl. Mix to combine.","images":[],"step":2},{"description":"Make a well in the centre. Add milk, butter, eggs and pour in the yeast liquid, including all froth.","images":[],"step":3},{"title":"Mix until combined with wooden spoon","description":"it will be like a thick muffin batter. Not pourable, but thick and sticky.","images":[],"step":4},{"description":"Leave dough in the bowl, cover with a wet (clean) tea towel and place in a warm place (25C/77F+) to rise for around 1 1/2 - 2 hours or until almost tripled in volume. See Note 4 for how I do this (you will laugh - but it works every time!). Dough surface should be bubbly (see video or photos in post).","images":[],"step":5},{"description":"Forming Balls (watch video, it''s helpful):","images":[],"step":6},{"description":"Line a 31.5 x 23.5 cm / 9 x 13\" tray with baking paper with overhang.","images":[],"step":7},{"description":"Remove tea towel and punch dough to deflate, then mix briefly in the bowl to get rid of the bubbles in the dough.","images":[],"step":8},{"description":"Dust work surface with flour, scrape dough on work surface. Dust top of dough then shape into a log. Cut log into 4 pieces, then cut each piece into 3 pieces (12 in total).","images":[],"step":9},{"description":"Take one piece and press down with palm, then use your fingers to gather into a ball, flip (so smooth side is up) then roll the dough briefly to form a ball. This stretches the dough on one side and that''s how I get a nice smooth surface on my roll. (For this step, use as much flour as needed to handle dough and avoid piercing inside into the wet dough)","images":[],"step":10},{"description":"Place the ball with the smooth side up on the tray. Repeat with remaining dough. Line them up 3 x 4.","images":[],"step":11},{"description":"Spray surface of rolls (or cling wrap) with oil (any), then place cling wrap over the tray.","images":[],"step":12},{"title":"Return tray to warm place and leave for 30","description":"45 min, until the dough has risen by about 75% (less than double in size).","duration":37.5,"images":[],"step":13},{"description":"Partway through Rise #2, preheat oven to 200C/390F (standard) or 180C/350F (fan/convection).","images":[],"step":14},{"title":"Bake for 15","description":"18 minutes, or until the surface is a golden brown and the roll in the centre sounds hollow when tapped. The surface colour is the best test for this recipe.","duration":16.5,"images":[],"step":15},{"description":"Remove rolls from oven. Brush with melted butter.","images":[],"step":16},{"description":"Use overhang to lift rolls onto a cooling rack. Allow to cool to warm before serving.","images":[],"step":17}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["baking-recipes","breads","coronavirus-food","easter-brunch-recipes","easter-recipes","good-to-know","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1e7dc8eb40cc', 'en', 'US', 'Custard (aka Creme Anglaise)', 'A beautiful, classic pouring custard recipe, made the proper way with just egg as a thickener - no cornflour. Also known as Creme Anglaise. This recipe makes 1 1/3 cups of Custard which is enough for 4 - 5 servings. It''s quite rich so a little goes a long way! Recipe video below. Picture with the ever popular Easy Moist Apple Cake.', 'https://www.recipetineats.com/tachyon/2017/03/Custard-4.jpg', 5, 15, 20, 5, '[{"id": "ing_vanilla_bean", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_milk", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_sugar", "quantity": {"value": 0.037, "unit": "kg"}}]', '[{"ingredients":["1 vanilla bean (Note 1)","1 cup / 250ml heavy / thickened cream (Note 2)","1/4 cup / 65 ml milk (whole or reduced fat, not zero fat)","3 egg yolks","1/4 cup / 50g white sugar, preferably caster / superfine"]}]', '[{"description":"Using a small knife, cut a slit down the length of the vanilla bean then scrape out seeds (see video).","images":[],"step":1},{"description":"Place cream, milk and vanilla seeds + vanilla bean into a small saucepan over medium heat. When it just comes to simmer, remove and cool for 5 minutes.","duration":5,"images":[],"step":2},{"description":"Meanwhile, place yolks and sugar in a bowl. Whisk for 2 minutes until it becomes a bit pale.","duration":2,"images":[],"step":3},{"description":"Remove vanilla pod from milk and discard.","images":[],"step":4},{"description":"While whisking, SLOWLY pour milk into the eggs. Then pour it back into the saucepan.","images":[],"step":5},{"description":"Return to low heat (can use medium low if on electric). Whisk regularly for first 3 minutes, then pretty much constantly for the next 5 minutes, or until the custard coats the back of a spoon. You should be able to draw a path (see video).","images":[],"step":6},{"description":"Remove from heat.","images":[],"step":7},{"title":"Optional","description":"strain to make extra silky smooth.","images":[],"step":8},{"description":"Keeps for 3 days in the fridge. Custard will thicken slightly more as it cools to room temperature. Do not freeze. See note 3 for suggested uses.","images":[],"step":9}]', '["egg","milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":[],"categories":["baking-recipes","dessert-recipes","dietary","easter-baking-desserts","easter-recipes","frosting-and-icing","gluten-free-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6e53237a2343', 'en', 'US', 'Fresh Strawberry Bars', 'A buttery biscuit base topped with strawberry jam and fresh strawberries and a lovely crumble. Love how fast this is to put together - no mixers required! Makes 16 sensible or 9 large bars. {Recipe video below}', 'https://www.recipetineats.com/tachyon/2017/03/Strawberry-Bars-4.jpg', 15, 35, 50, 16, '[{"id": "ing_butter", "quantity": {"value": 125.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_rolled_oats", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.11, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.003, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_strawberries", "quantity": {"value": 1.2, "unit": "punnet of 250g"}}, {"id": "ing_strawberries", "quantity": {"value": 1.2, "unit": "punnet of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.11, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.025, "unit": "pack of 400g"}}]', '[{"ingredients":["125 g / 1 stick unsalted butter, melted","1½ cups/ 225 g plain flour (all purpose flour)","1½ cups / 135 g rolled oats (traditional oats, not quick, instant or steel cut)","½ cup / 110 g brown sugar","½ tsp baking powder","Pinch of salt","1 egg","2/3 cup strawberry jam"]},{"ingredients":["2 cups chopped strawberries (about 375g)","2 tbsp white sugar","2 tsp cornflour / cornstarch"],"purpose":"Strawberries"}]', '[{"description":"Preheat oven to 180C/350 (fan forced). (Note 1)","images":[],"step":1},{"description":"Spray a 20cm/9\" square tin with oil and line with baking/parchment paper with overhang (so it can be lifted out once cooked).","images":[],"step":2},{"description":"Mix together flour, oats, sugar, baking powder and salt. Add butter and egg then mix.","images":[],"step":3},{"description":"Measure out 1 cup of the mixture (for topping) and set aside. Place remaining mixture in the tin and press into base.","images":[],"step":4},{"description":"Mix together Strawberries, sugar and cornflour in a bowl (don''t do this in advance because sugar will make strawberries sweat = runny filling).","images":[],"step":5},{"description":"Spread base with jam (Note 2), then scatter over strawberries. Use your hands to crumble the remaining mixture over the top (Note 3).","images":[],"step":6},{"title":"Bake for 35","description":"40 minutes or until the top is deep golden. Remove and allow to cool for 10 minutes in the tin before lifting out of the tin using the baking paper. It will sag - don''t worry, it will set.","duration":37.5,"images":[],"step":7},{"description":"Cut into squares. Serve at room temperature. Store in airtight container (in fridge if it''s very hot where you are).","images":[],"step":8}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":[],"categories":["baking-recipes","dessert-recipes","quick-and-easy","slices-bars"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_132cacdd8097', 'en', 'US', 'Easy Cinnamon Bread', 'Recipe video above. Easy to make, this easy Cinnamon Swirl Quick Bread is made without yeast! It''s super moist - and stays moist for days afterwards - it tastes buttery and you get gorgeous pockets of sweet sticky cinnamon sugar!', 'https://www.recipetineats.com/tachyon/2017/03/Cinnamon-Swirl-Quick-Bread-hero.jpg', 15, 70, 85, 8, '[{"id": "ing_flour", "quantity": {"value": 0.375, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.05, "unit": "tub of 150g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.025, "unit": "tub of 200g"}}, {"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.8, "unit": "tub of 250g"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.2, "unit": "bottle of 50ml"}}, {"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.562, "unit": "jar of 40g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.113, "unit": "kg"}}]', '[{"ingredients":["2 1/2 cups / 375g plain flour (all purpose flour)","1 cup / 220g white sugar","1 1/2 tsp baking powder","1 tsp baking soda"],"purpose":"Dry Ingredients:"},{"ingredients":["3 eggs","1/2 cup / 125 ml vegetable oil","1 1/3 cups / 290g sour cream (Note 1)","2 tsp vanilla extract"],"purpose":"Wet Ingredients:"},{"ingredients":["60g / 4 tbsp unsalted butter, melted","1 1/2 tbsp cinnamon powder","3/4 cup / 165 g brown sugar, packed"],"purpose":"Cinnamon Sugar:"}]', '[{"description":"Preheat oven to 180C/350F (all oven types).","images":[],"step":1},{"description":"Grease a loaf tin approximately 21 x 11 cm / 8\" x 4\" and line with baking paper, leaving overhang (see video).","images":[],"step":2},{"description":"Place Dry Ingredients in a bowl and whisk to combine.","images":[],"step":3},{"description":"Place Wet Ingredients in a separate bowl and whisk until combined.","images":[],"step":4},{"description":"Place Cinnamon Sugar ingredients in a bowl and mix to combine (it should be like a slurry, see video).","images":[],"step":5},{"description":"Make a well in the Dry Ingredients bowl. Pour in Wet Ingredients, then mix 12 - 15 times until just combined (few lumps ok, see video).","images":[],"step":6},{"description":"Spoon about 1/4 of the batter into the tin (about 1.5cm / 3/5\" deep) and smooth surface.","images":[],"step":7},{"description":"Dollop about 1/3 of the Cinnamon Sugar over the batter.","images":[],"step":8},{"description":"Top with half the remaining batter. Dollop the remaining Cinnamon Sugar over the batter. Drag a butter knife back and forth (lengthwise and cross wisto make the swirls. Top with remaining batter - dollop it on, the more the Cinnamon Sugar is moved about, the more swirls!","images":[],"step":9},{"description":"Bake uncovered for 45 minutes. Then remove and cover with foil, and bake for a further 20 minutes or until a skewer inserted into the middle comes out clean.","duration":45,"images":[],"step":10},{"description":"Stand in the tin for 5 minutes before lifting it out onto a cooling rack. Allow to cool before slicing (can still be warm but don''t slice while hot, may crumble). Moist and flavoursome enough to eat plain but a little extra butter doesn''t hurt!","duration":5,"images":[],"step":11}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":[],"categories":["baking-recipes","breads","dessert-recipes","easter-brunch-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_578af07063f1', 'en', 'US', 'Cookie Mix In a Jar: White Chocolate Cranberry Cookies', 'A fabulous gift! This Cookie Mix In a Jar makes soft White Chocolate Cranberry Cookies - perfect for Christmas. You just need to add melted butter and an egg, then mix with a wooden spoon. No beater required! Click here for the instructions to attach to the jar. Recipe VIDEO below.', 'https://www.recipetineats.com/tachyon/2016/12/Cranberry-Oatmeal-Cookie-Mix-Jar-8-SQ.jpg', 10, 14, 24, 12, '[{"id": "ing_itre_1_quart_mason_jar", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sugar", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.025, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_quick_cooking_oats", "quantity": {"value": 150.0, "unit": "pack"}}, {"id": "ing_cranberries", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_chocolate", "quantity": {"value": 1.0, "unit": "block of 100g"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}]', '[{"ingredients":["1 litre / 4 cups / 1 quart / 32 oz mason jar","1/3 cup / 70g white sugar (granulated, super fine or caster)","1/3 cup / 70g brown sugar (normal or light)","3/4 cup / 113g plain flour (all purpose flour)","3/4 tsp baking powder","1/2 tsp salt","1 cup / 90g quick cooking oats","1 cup / 120g dried cranberries","1 cup/ 180g white chocolate chips"],"purpose":"Cookie Mix"},{"ingredients":["1 stick / 4 oz / 125g unsalted butter (, melted)","1 large egg (around 60g / 2oz)"],"purpose":"To Bake"}]', '[{"description":"Layer Cookie Mix ingredients in the jar in the order listed. I don''t have anything to tamper with so I just shake / spread out with spoon (see video below recipe).","images":[],"step":1},{"title":"Seal and attach baking instructions","description":"Print here.","images":[],"step":2},{"description":"If your tray is prone to sticking, lightly grease with butter or line with baking / parchment paper (I do not bother). You will need 2 trays.","images":[],"step":3},{"description":"Add Cookie Mix, butter and egg in a bowl. Mix with wooden spoon. Refrigerate 30 minutes.","images":[],"step":4},{"description":"Preheat oven to 375F/190C (standard) or 340F / 170C (fan / convection).","images":[],"step":5},{"description":"Scoop dough with ice cream scoop, level and press in with fingers, then drop onto tray 5cm / 2\" apart (makes 12 large cookies, 8cm/3” rounds). Or measure heaped tablespoon and roll into balls (makes 18 small cookies 5cm/2”).","images":[],"step":6},{"title":"Optional","description":"If you remember, pick out some choc bits and cranberries and use to stud the top of the balls. For aesthetic reasons only. :)","images":[],"step":7},{"description":"Bake 8-10 minutes (small), 12-14 minutes (large) until light golden, swapping the trays at halftime. Rest 2 minutes then transfer to cooling rack.","images":[],"step":8}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":[],"categories":["baking-recipes","cookies","dessert-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4ef0d563b4e2', 'en', 'US', 'Chocolate Self Saucing Pudding', 'Recipe video above. A classic chocolate self saucing pudding! One batter magically transforms into a moist chocolate cake AND a chocolate sauce. The sauce has the consistency of maple syrup - never watery, never gluggy. This is easy and fast to make. Serve it up straight away otherwise the sauce gets absorbed into the cake!', 'https://www.recipetineats.com/tachyon/2016/11/Chocolate-Self-Saucing-Pudding-4.jpg', 10, 30, 40, 5, '[{"id": "ing_brown_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_cocoa_powder", "quantity": {"value": 0.15, "unit": "pack of 250g"}}, {"id": "ing_water", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.083, "unit": "tub of 150g"}}, {"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}]', '[{"ingredients":["1 cup (175g) brown sugar (, loosely packed (Note 1))","1/4 cup (30g) cocoa powder (, unsweetened (Note 2))","1 1/4 cups (315ml) boiling water"],"purpose":"Topping"},{"ingredients":["1 cup (150g) plain flour (all purpose flour)","2 1/2 tsp baking powder","1/3 cup (70g) white sugar (, preferably caster/super fine but ordinary ok)","1/4 cup (30g) cocoa powder (, unsweetened (Note 2))","Pinch of salt","1/2 cup (125ml) milk","50 g / 4 1/2 tbsp butter (, melted)","1 egg","1 tsp vanilla extract"],"purpose":"Batter"}]', '[{"description":"Preheat oven to 170C/335F (standard) / 150C/305F (fan forced / convection).","images":[],"step":1},{"title":"Grease a 5","description":"6 cup baking dish with butter. (Note 3)","images":[],"step":2},{"title":"Topping","description":"Whisk brown sugar and cocoa in a bowl, set aside.","images":[],"step":3},{"description":"Whisk flour, baking powder, caster sugar, cocoa powder and salt in a bowl.","images":[],"step":4},{"description":"In a separate bowl or jug, whisk together the butter and milk, then whisk in the egg and vanilla.","images":[],"step":5},{"description":"Pour the egg mixture into the flour mixture. Mix until combined - it will be a thick batter.","images":[],"step":6},{"description":"Spread into baking dish. Sprinkle with sugar / cocoa mixture. Shake gently to spread out thinly.","images":[],"step":7},{"description":"Carefully pour the hot water over the back of a dessert spoon all over the top of the pudding - see photo in post or video below recipe. (Note 4)","images":[],"step":8},{"description":"Transfer to oven and bake for 30 minutes, or until the top of the cake springs back when poked lightly. The top will be a bit crusty, like the top of brownies.","duration":30,"images":[],"step":9},{"description":"Remove from oven, stand for just a few minutes (no more!), then serve immediately. (Note 5)","images":[],"step":10}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":[],"categories":["baking-recipes","cosy-desserts","dessert-recipes","easter-baking-desserts","easter-recipes","puddings-cosy-desserts","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c9731ccd96c1', 'en', 'US', 'CLASSIC Blueberry Cheesecake Bars', 'The pops of juicy blueberries combined with a creamy yet light cheesecake is a killer! This cheesecake is light yet creamy once you bite into it. It''s similar to a New York Baked Cheesecake and Japanese Baked Cheesecake - light yet rich. See in post for a description / comparison with the other cheesecake bar types I''m sharing in this post - No Bake and Creamier Baked.', 'https://www.recipetineats.com/tachyon/2016/10/Blueberry-Cheesecake-Bars-No-Bake-30.jpg', 15, 35, 50, 9, '[{"id": "ing_arnott_s_marie_crackers_or_16_graham_cracker_squares", "quantity": {"value": 18.0, "unit": "pack"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_cream_cheese", "quantity": {"value": 320.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 2.0, "unit": "bottle of 50ml"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_egg", "quantity": {"value": 0.167, "unit": "carton of 12"}}, {"id": "ing_blueberries", "quantity": {"value": 250.0, "unit": "punnet of 125g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}]', '[]', '[{"description":"Preheat oven to 160C/320F (all oven types).","images":[],"step":1},{"description":"Spray a 20cm/9\" square tin with oil and line with baking/parchment paper with overhang (so it can be lifted out once cooked).","images":[],"step":2},{"description":"Place biscuits in a food processor and blitz until fine crumbs form. Add butter and sugar and blitz to combine - it should look like wet sand. (Note 1)","images":[],"step":3},{"description":"Pour into tin and use something with a flat bottom to press into base.","images":[],"step":4},{"description":"Filling (Note 2)","images":[],"step":5},{"description":"Beat cream cheese until smooth, not fluffy. Add flour and beat until just combined.","images":[],"step":6},{"description":"Add sour cream, sugar, vanilla and lemon. Beat until combined. Add eggs, one and a time, beating in between until just combined.","images":[],"step":7},{"title":"Fold in most of the blueberries","description":"reserve some for topping. Pour into tin and smooth surface. Top with remaining blueberries.","images":[],"step":8},{"description":"Bake for 35 minutes (fan forced / convection) or 40 minutes (standard), or until cheesecake is set but the middle wobbles a bit like jelly - see video. The surface should not be browned, there will probably be some minor cracks.","duration":35,"images":[],"step":9},{"description":"Cool in tin, then refrigerate (covered) for at least 4 hours. Use paper overhang to lift out, dust with icing sugar if desired. Cut into squares or bars. Serve!","images":[],"step":10}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":[],"categories":["baking-recipes","blueberries","cheesecakes","dessert-recipes","quick-and-easy","slices-bars"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c07faccb26e1', 'en', 'US', 'Easiest Ever MOIST Apple Cake', 'A very moist, perfectly spiced Apple Cake! This is incredibly easy to make - no mixer required. This must be made with fresh apples, not canned. See note 5 for information about different measures in different countries & different oven types. Also, I do not recommend substituting butter for all or part of the oil - it does not come out as moist and you can''t taste buttery flavour anyway because of the spice flavourings! FREEZES great!', 'https://www.recipetineats.com/tachyon/2016/09/Apple-Cake-5.jpg', 15, 50, 65, 12, '[{"id": "ing_flour", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.019, "unit": "tub of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_round_nutmeg", "quantity": {"value": 3.75, "unit": "jar"}}, {"id": "ing_sugar", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.15, "unit": "bottle of 50ml"}}, {"id": "ing_apples", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_almonds", "quantity": {"value": 0.3, "unit": "pack of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.188, "unit": "kg"}}]', '[{"ingredients":["2 cups flour (, plain / all purpose (Note 1))","3/4 tsp baking soda (bi-carb soda) (Note 1)","3/4 tsp EACH salt, cinnamon and ground cloves","1/2 tsp ground nutmeg (or 1/4 tsp freshly ground)","1 1/4 cups white sugar (Note 2)","1 cup vegetable oil","2 eggs (, large, at room temperature (55-60g/2oz each))","1 1/2 tsp vanilla extract","2 cups apple ( , peeled, cored and cut into 8mm/ 1/3\" cubes (~2 large, 3 small) (Note 3))"]},{"ingredients":["1/2 cup flaked raw almonds","Icing sugar . confectioners sugar, for dusting"],"purpose":"Optional Extra"}]', '[{"description":"Preheat oven to 180°C/350°F (all oven types).","images":[],"step":1},{"description":"Grease and line a 21 cm / 9\" springform cake pan. (Note 4)","images":[],"step":2},{"description":"Place flour, baking soda, salt and spices in a large bowl and whisk to combine.","images":[],"step":3},{"description":"Whisk oil and sugar in a bowl, then whisk in eggs and vanilla.","images":[],"step":4},{"description":"Pour the wet ingredients into the dry and mix with a wooden spoon until JUST combined. Stir through apple (optional: add 3/4 cup chopped walnuts or other nuts).","images":[],"step":5},{"description":"Pour into cake pan. Sprinkle over almonds.","images":[],"step":6},{"title":"Bake for 50 minutes","description":"1 hr. Check at 50 minutes - it is cooked when a skewer inserted into the centre comes out clean.","duration":50,"images":[],"step":7},{"description":"Cool for 10 minutes before turning out onto a rack to cool. Dust with icing sugar if using, then serve. This cake doesn''t need cream or ice cream because it is so moist, but I wouldn''t turn it down!","duration":10,"images":[],"step":8}]', '["egg","gluten"]', '["vegan","vegetarian"]', '{"mealType":["dessert"],"cuisine":[],"categories":["baking-recipes","dessert-recipes","easter-baking-desserts","easter-recipes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ad7106559dd6', 'en', 'US', 'Peanut Butter Cheesecake Stuffed Chocolate Loaf', 'A gorgeous moist chocolate quick bread with a creamy peanut butter cheesecake baked right in! A dream come true for all peanut butter and chocolate lovers. The cake is truly moist, actually tastes of chocolate and the filling is creamy. Added bonus: freezes perfectly! The measurements for this recipe apply to every country except if you are in Japan, please use weights. The recipe is quite forgiving.', 'https://www.recipetineats.com/tachyon/2016/09/Peanut-Butter-Cheesecake-Stuffed-Chocolate-Loaf4.jpg', 15, 70, 85, 10, '[{"id": "ing_cream_cheese", "quantity": {"value": 5.0, "unit": "block of 250g"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.133, "unit": "jar of 375g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_sugar", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.2, "unit": "tub of 250g"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_flour", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.1, "unit": "tub of 150g"}}, {"id": "ing_butter", "quantity": {"value": 0.333, "unit": "block of 250g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_cocoa_powder", "quantity": {"value": 0.2, "unit": "pack of 250g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_yogurt", "quantity": {"value": 0.15, "unit": "tub of 500g"}}, {"id": "ing_vanilla", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_chocolate", "quantity": {"value": 1.25, "unit": "block of 100g"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}]', '[{"ingredients":["5 oz / 150 g cream cheese (, at room temperature)","1/3 cup / 85 g smooth peanut butter","1 egg","1/3 cup / 75 g caster sugar / superfine sugar (2)","1/3 cup / 75 g sour cream","1 tsp vanilla extract"],"purpose":"Filling"},{"ingredients":["1 1/2 cups / 225 g plain flour (all purpose)","3 tsp baking powder","1 cup / 220 g caster sugar / superfine sugar (2)","1 stick / 125 g unsalted butter","1/4 cup / 60 ml vegetable oil (sub with canola, sunflower or other neutral flavoured oil)","1/3 cup / 40 g cocoa powder (, unsweetened)","2 eggs","1/2 cup / 125 g yoghurt (3)","1 tsp vanilla","1 1/4 cups / 200 g dark chocolate chips (4)"],"purpose":"Cake"},{"ingredients":["2 tbsp hot water (5)"],"purpose":"Assembly"}]', '[{"description":"Beat the cream cheese and peanut butter using a stand mixer, electric beater or whisk until smooth.","images":[],"step":1},{"description":"Beat in egg until combined. Beat in remaining ingredients until smooth. Cover and refrigerate for 30 minutes.","duration":30,"images":[],"step":2},{"description":"Preheat oven to 180C/350F (fan forced / convection) or 200C / 390F (standard).","images":[],"step":3},{"description":"Spray a loaf and line a loaf pan (23.5 x 13cm / 8½ x 4¼\") with parchment / baking paper. (I just tear a piece off to line the long side, per photo in post)","images":[],"step":4},{"description":"Whisk together flour, baking powder and sugar in a large bowl.","images":[],"step":5},{"description":"Melt butter in microwave in a large heatproof bowl, then whisk in oil and cocoa powder.","images":[],"step":6},{"description":"Whisk in eggs, yoghurt and vanilla into chocolate mixture. Pour mixture into flour and mix until just combine. Stir through chocolate chips.","images":[],"step":7},{"description":"Remove Filling from fridge, give it a good mix to loosen it up - if it''s too stiff, it will sink into the batter.","images":[],"step":8},{"description":"Pour 1/3 of the batter into the loaf pan, smooth surface.","images":[],"step":9},{"description":"Pour over the Filling and smooth surface.","images":[],"step":10},{"description":"Add 2 tbsp hot water into remaining Batter (5), give it a quick mix to combine. Then pour batter over the Filling and smooth surface.","images":[],"step":11},{"description":"Bake for 15 minutes, then turn oven down to 160C/320F (fan forced / convection) or 180C / 350F (standard oven). Bake for 55 minutes, or until a skewer inserted into the top half of the cake comes out almost clean.","duration":15,"images":[],"step":12},{"description":"Stand for 15 minutes in the loaf pan before using parchment paper overhang to lift onto a cooling rack. Cool completely before slicing - it takes a few hours.","duration":15,"images":[],"step":13},{"title":"Optional","description":"Drizzle with melted white chocolate and/or peanut butter white chocolate (7).","images":[],"step":14}]', '["egg","gluten","milk","peanuts"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":[],"categories":["baking-recipes","cheesecakes","dessert-recipes","quick-bread"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2462650aa4d9', 'en', 'US', 'Homemade Nutella', 'A silky, creamy homemade Nutella! It tastes just like the real thing, with a slightly stronger hazelnut flavour and the pure taste of preservative free homemade goodness. This really will knock your socks off. A must try at least once in your life!', 'https://www.recipetineats.com/tachyon/2016/08/Homemade-Nutella_3.jpg', 10, 10, 20, 1, '[{"id": "ing_skinless_hazelnuts", "quantity": {"value": 250.0, "unit": "jar"}}, {"id": "ing_cocoa_powder", "quantity": {"value": 0.15, "unit": "pack of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}]', '[{"ingredients":["250 g / 8 oz raw skinless hazelnuts (Note 1)","1/4 cup /30 g Dutch processed unsweetened cocoa powder (Note 2)","3/4 cup / 90 g icing sugar / confectionary sugar","2 tbsp hazelnut oil (or vegetable, canola, grapeseed or other neutral flavoured oil)","1 tsp vanilla extract"]}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Place hazelnuts on a baking tray, roast for 8 minutes or until golden. Transfer into blender.","duration":8,"images":[],"step":2},{"description":"Blend on the lowest speed until the nuts are ground into a crumb. Scrape down the sides as necessary. Then increase the speed to 4 until it turns into a paste. You may need to scrape down the sides - in my Vitamix blender, I did not have to. Then increase the speed as high as it will go and whizz until it becomes smooth with a consistency like honey.","images":[],"step":3},{"description":"Add remaining ingredients, then whizz, starting on low and increasing to high. Whizz until smooth - the sugar takes the longest to dissolve (Note 3).","images":[],"step":4},{"title":"Pour into a jar","description":"it will be lovely and warm. Allow to cool to spread consistency. Do not refrigerate as the sugar will crystallise and it will become grainy.","images":[],"step":5},{"description":"Use as you do Nutella! Especially fabulous with Nutella Crepes!","images":[],"step":6}]', '["nuts"]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["dessert"],"cuisine":[],"categories":["baking-recipes","dessert-recipes","dietary","gluten-free-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0984bafb44c5', 'en', 'US', 'Best Chocolate Chip Muffin', 'A perfect sweet muffin base that''s super quick to mix! This is moist and fluffy, with a beautiful dome like the muffins you get from bakeries and cafes. I load this up with chocolate chips but feel free to substitute with your favourite berries, nuts or dried fruit. Don''t worry if you don''t have BUTTERMILK - use the substitute in Note 1. KEY TIP: Do not over mix the batter, it is the key culprit for hard muffins. A few flour lump remaining is absolutely fine. UPDATE 14 Oct 2016: This recipe was originally made with just butter. However, I found that by swapping out half the butter with oil, you get a slightly more moist muffin while still having the benefit of the flavour that the butter provides.', 'https://www.recipetineats.com/tachyon/2016/06/Choc-Chip-Muffins_5.jpg', 10, 20, 30, 12, '[{"id": "ing_flour", "quantity": {"value": 0.375, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.1, "unit": "tub of 150g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.025, "unit": "tub of 200g"}}, {"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 0.25, "unit": "block of 250g"}}, {"id": "ing_butter", "quantity": {"value": 0.25, "unit": "block of 250g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.2, "unit": "bottle of 50ml"}}, {"id": "ing_chocolate", "quantity": {"value": 1.75, "unit": "block of 100g"}}]', '[{"ingredients":["2 1/2 cups / 375g plain flour (all purpose flour)","3 tsp baking powder","1 tsp baking soda / bi carb soda","1 cup / 220g white sugar (Note 1)","1/4 tsp salt"],"purpose":"Dry Ingredients"},{"ingredients":["1 cup / 250ml buttermilk (Note 2)","1/4 cup / 60g unsalted butter, melted","4 tbsp / 80 ml vegetable oil","2 large eggs, lightly whisked","2 tsp vanilla extract"],"purpose":"Wet Ingredients"},{"ingredients":["1 3/4 cups / 300g chocolate chips (US: semi-sweet)"],"purpose":"Chocolate Chips"}]', '[{"description":"Preheat oven to 200C/390F (all ovens) (Note 6). Line a 12 hole muffin tin with paper patties.","images":[],"step":1},{"description":"Whisk flour, baking powder, baking soda, sugar and salt in a bowl. Stir through chocolate chips.","images":[],"step":2},{"description":"In a separate bowl, whisk buttermilk, melted butter, oil, eggs and vanilla.","images":[],"step":3},{"description":"Make a well in the flour bowl, pour in egg mixture. Mix until just combine - try not to stir more than 8 times. Some flour lumps in the batter is fine.","images":[],"step":4},{"description":"Divide batter between paper cases. Top with remaining 1/4 cup chocolate chips.","images":[],"step":5},{"description":"Bake for 5 minutes, then turn down to 180C/350F (fan forced/convection) and bake for a further 15 minutes, or until a skewer inserted into the muffin comes out clean.","duration":5,"images":[],"step":6},{"description":"Remove muffins from the muffin tin immediately onto a cooling rack.","images":[],"step":7},{"description":"Serve warm or at room temperature (warm is extra yum!)","images":[],"step":8}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":[],"categories":["baking-recipes","cupcakes-and-muffins","dessert-recipes","easter-brunch-recipes","most-popular","muffin-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6ef9412e397b', 'en', 'US', 'Red Velvet Cake', 'Recipe VIDEO above. The classic, iconic Red Velvet Cake! The sponge is soft and velvety, true to it''s name, with a buttery flavour, moist with a hint of chocolate, vanilla and tang from buttermilk. MEASURES: Don''t switch between weights/ml and cups in the recipe, read note 11. UK: Please read notes 7 and 9. After Red Velvet Cupcakes? Here''s the recipe!', 'https://www.recipetineats.com/tachyon/2016/06/Red-Velvet-Layer-Cake_4.jpg', 30, 25, 55, 10, '[{"id": "ing_flour", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_cocoa_powder", "quantity": {"value": 0.12, "unit": "pack of 250g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.025, "unit": "tub of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 0.5, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.2, "unit": "bottle of 50ml"}}, {"id": "ing_butter", "quantity": {"value": 0.5, "unit": "block of 250g"}}, {"id": "ing_red_food_colouring_liquid", "quantity": {"value": 2.5, "unit": "unit"}}, {"id": "ing_cream_cheese", "quantity": {"value": 14.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.225, "unit": "kg"}}]', '[{"ingredients":["2 2/3 cups (400 g) plain cake flour (Note 1)","2 tbsp (10 g) cocoa powder (, unsweetened)","1 tsp (5 g) baking soda / bi-carb soda (, NOT baking powder (Note 2))","Pinch of salt"],"purpose":"Dry Ingredients"},{"ingredients":["1/2 cup (115 g) unsalted butter (, softened (1 US stick))","1 1/2 cups (330 g) caster / superfine white sugar (Note 3a)","2 eggs (, at room temperature (around 2 oz / 60g each))","1 cup (250ml) vegetable oil","1 tsp white vinegar","2 tsp vanilla extract (or essence)","1 cup (250 ml) buttermilk (, at room temperature (Note 4))","2 1/2 tbsp red food colouring liquid (UK: use Gel, Note 7)"],"purpose":"Wet Ingredients"},{"ingredients":["14 oz (400 g) Philadelphia Cream Cheese, block (, softened but not too soft (UK see Note 9))","1/2 cup (115 g) unsalted butter (, softened (but not too soft))","1 1/2 tsp vanilla extract","4 cups (450 g) soft icing sugar / powdered sugar (sifted (Note 3b))"],"purpose":"Frosting (Note 10)"}]', '[{"description":"Preheat oven to 180C/350F (all oven types). Butter 2 x 21cm / 8\" round cake pans (sides and base) and dust with cocoa powder.","images":[],"step":1},{"description":"Sift the Dry Ingredients and whisk to combine in a bowl.","images":[],"step":2},{"description":"Place butter and sugar in a bowl and beat with electric beater or in stand mixer until smooth and well combined (use paddle attachment if using stand mixer).","images":[],"step":3},{"description":"Add eggs, one at a time, beating in between to combine. At first it will look curdle - keep beating until it''s smooth.","images":[],"step":4},{"description":"Add vegetable oil, vinegar, vanilla, buttermilk and red food colouring. Beat until combined and smooth (Note 5).","images":[],"step":5},{"title":"Add Dry Ingredients. Beat until just combined","description":"some small lumps is ok, that''s better than over mixing.","images":[],"step":6},{"title":"Divide batter between cake pans. Bake for 25","description":"30 minutes on the same shelf, or until a toothpick inserted into the centre comes out clean. (Note 6)","duration":27.5,"images":[],"step":7},{"description":"Rest for 10 minutes in the pan then turn out onto a cooling rack and allow to cool.","duration":10,"images":[],"step":8},{"description":"Beat together cream cheese, butter and vanilla for 3 minutes (this makes it really smooth and changes from yellow to almost white). Add icing sugar and beat for 2 minutes or until frosting is light and fluffy to your taste. If your frosting seems too runny (depends on quality of cream cheese/ if the cream cheese was too soft), just add more icing sugar.","duration":3,"images":[],"step":9},{"description":"Cut the top off the cake using a serrated knife (to make the layers neat).","images":[],"step":10},{"description":"Spread one cake with 1 1/2 cups of frosting. Top with the other cake. Spread top and sides with remaining frosting.","images":[],"step":11},{"title":"Optional","description":"Crumble offcuts and use to decorate the top rim and base of the cake.","images":[],"step":12}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":["American","Western"],"categories":["baking-recipes","classic-cakes","dessert-recipes","easter-baking-desserts","easter-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6baf528f7a25', 'en', 'US', 'Classic Baked Cheesecake', 'Recipe video above. Some cheesecakes are quite dense and very rich (like New York Cheesecake), whereas others are so airy they are almost like soufflé, like the the famous Japanese Cotton Cheesecake. This cheesecake lies in between - the filling is smooth and rich, but not heavy and dense because it is baked and also due to the addition of sour cream. It''s a truly beautiful cheesecake, a classic you will treasure forever!PS There is no need to use a fiddly water bath for baking to avoid surface cracks. You just need to bake at a low temperature and cool in the oven.', 'https://www.recipetineats.com/tachyon/2016/03/Baked-Cheesecake_8-SQ.jpg', 30, 55, 75, 12, '[{"id": "ing_arnott_s_marie_crackers_or_16_graham_cracker_squares", "quantity": {"value": 200.0, "unit": "pack"}}, {"id": "ing_butter", "quantity": {"value": 120.0, "unit": "block of 250g"}}, {"id": "ing_cream_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.3, "unit": "tub of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_egg", "quantity": {"value": 250.0, "unit": "carton of 12"}}, {"id": "ing_strawberries", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.225, "unit": "kg"}}]', '[{"ingredients":["200g / 7 oz Arnott''s Marie crackers or other plain biscuit (Aus) or 28 Graham Cracker squares (Note 1)","120g / 8 tbsp unsalted butter (, melted)"],"purpose":"CHEESECAKE BISCUIT BASE:"},{"ingredients":["1 lb / 500g cream cheese (, softened (Note 2))","2 tbsp plain flour (all purpose flour)","1 tsp vanilla extract","1/2 cup sour cream (full fat)","1 1/2 cups caster sugar (superfine sugar)","Zest of 1 lemon","3 large eggs (, at room temperature)"],"purpose":"CHEESECAKE FILLING:"},{"ingredients":["Strawberries, blueberries, raspberries","Icing sugar / powdered sugar (, for dusting)"],"purpose":"TOPPINGS:"}]', '[{"description":"Preheat oven to 160°C/320°F (140°C fan).","images":[],"step":1},{"title":"Prepare pan","description":"Get a 20cm/8\" springform cake tin. Turn the base UPSIDE DOWN (Note 4), butter lightly and place a square piece of parchment/baking paper on the base. Then clip into the springform pan - excess paper will stick out, see photos in post and video. Butter and line the side of the pan.","images":[],"step":2},{"title":"Blitz","description":"Break up biscuits roughly by hand and place in a food processor. Blitz until fine crumbs (Note 5). Add butter, briefly blitz until dispersed and it resembles wet sand.","images":[],"step":3},{"title":"Press into pan","description":"Pour into the prepared cake tin. Use a spatula to roughly spread it out over the base and up the walls. Use something with a flat base and vertical edges (I used a measuring cup) to press the crumbs up the wall almost to the top of the sides, and flatten the base.","images":[],"step":4},{"title":"Beat cream cheese","description":"Use a mixer or beater to beat the cream cheese until smooth - about 30 seconds on medium high,.","images":[],"step":5},{"title":"Finish batter","description":"Add flour, beat until just combined (10 sec). Add vanilla, sour cream, sugar and lemon zest. Beat until just combined (10 - 15 sec). Add eggs one at a time, beat in between until just combined (10 sec each). Don''t over beat, we don''t want to aerate the batter.","images":[],"step":6},{"title":"Bake","description":"Pour into prepared crust. Bake for 55 minutes. The top should be a very light golden brown, not cracked, and near perfectly flat. It should jiggle slightly when you gently shake the pan.","duration":55,"images":[],"step":7},{"description":"Cool in the oven with the door open 20 cm / 8\" (Note 6), then refrigerate for 4 hours+ in the pan.","images":[],"step":8},{"description":"Remove springform pan sides. Use overhang paper to slide cheesecake off the cake pan. Then slide the cheesecake off the paper.","images":[],"step":9},{"title":"Serve","description":"Top with berries and dust with icing sugar!","images":[],"step":10}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":[],"categories":["baking-recipes","cheesecakes","dessert-recipes","easter-baking-desserts","easter-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3cdbfa2a5879', 'en', 'US', 'Caramelized Pears and Blue Cheese Tarts', 'The flavour combination of these tarts is truly a match made in heaven. Sweet, soft pears with creamy, salty blue cheese, piled on flaky puff pastry and scattered with crunchy walnuts. I served these with a dollop of creamy, thick yoghurt on the side which I thought cuts through the richness a bit. But I can''t decide whether I like these better with or without the yoghurt - you choose!', 'https://www.recipetineats.com/tachyon/2015/03/Caramelized-Pear-Blue-Cheese-Gorgonzola-Tart-2.jpg', 10, 30, 40, 4, '[{"id": "ing_sheet_frozen_puff_pastry", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_pears", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_cheese", "quantity": {"value": 0.333, "unit": "block of 250g"}}, {"id": "ing_walnuts", "quantity": {"value": 45.0, "unit": "jar"}}]', '[{"ingredients":["1 sheet store bought frozen puff pastry (, thawed (25 cm x 25cm / 10\" x 10\"))","2 pears","2 tbsp unsalted butter","1/3 cup brown sugar (, lightly packed)","Pinch of salt","1 egg (, lightly beaten)","1/3 to 1/2 cup crumbled blue cheese (I used gorgonzola)","3 tbsp walnuts (, roughly chopped)"]}]', '[{"description":"Preheat oven to 180C/350F and line baking tray with parchment/baking paper.","images":[],"step":1},{"description":"Cut the puff pastry into 4 equal squares (Note 1) and transfer to baking tray.","images":[],"step":2},{"description":"Score a 2/3\" / 1.5cm border on each piece. (Note 2)","images":[],"step":3},{"description":"Cut each pear into quarters, remove the core and cut each quarter into 3 or 4 slices.","images":[],"step":4},{"description":"Place the pear, butter, sugar and salt in a small fry pan or saucepan over medium high heat. Cook for 5 minutes, stirring occasionally, until the pear is softened and the pear juice has mixed in with the butter and sugar to form a syrup.","duration":5,"images":[],"step":5},{"description":"Set aside to cool for 5 minutes. Meanwhile, brush the border of the pastry with egg wash. (Note 3)","duration":5,"images":[],"step":6},{"description":"Pile the pear mixture onto each piece of pastry, staying within the border. Drizzle with some of the syrup.","images":[],"step":7},{"description":"Bake for 20 to 25 minutes, until deep golden brown. Toss the walnuts onto the baking tray for the last 5 minutes of baking.","duration":22.5,"images":[],"step":8},{"description":"Remove the tarts from the oven and let them cool for 5 minutes.","duration":5,"images":[],"step":9},{"description":"Top with crumbled blue cheese, scatter with walnuts and drizzle with remaining syrup. Serve immediately, with yoghurt on the side, if using.","images":[],"step":10}]', '["egg","milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["snack","dessert"],"cuisine":[],"categories":["baking-recipes","breakfast-recipes","dessert-recipes","easter-brunch-recipes","quiches-tart-and-pie-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9d3982020976', 'en', 'US', 'Red Velvet Cookies', 'These cookies have a "cake like" texture so they honestly taste just like a red velvet cupcake, except they''re in cookie form! Which means a) a higher frosting to "cupcake" ratio; and b) less calories per serving. :) The cream cheese frosting is very soft and creamy and stays that way ie. a crust does not form.', 'https://www.recipetineats.com/tachyon/2015/04/Red-Velvet-Cupcake-Cookies-Cream-Cheese-Frosting_680px_Main_2.jpg', 20, 15, 35, 20, '[{"id": "ing_butter", "quantity": {"value": 0.5, "unit": "block of 250g"}}, {"id": "ing_vanilla_bean_paste", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.15, "unit": "tub of 250g"}}, {"id": "ing_cocoa_powder", "quantity": {"value": 0.12, "unit": "pack of 250g"}}, {"id": "ing_red_food_colouring", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_flour", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.033, "unit": "tub of 150g"}}, {"id": "ing_cream_cheese", "quantity": {"value": 5.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_sprinkles", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["1/2 cup unsalted butter (, softened (110g / 3 3/4 oz))","1 tsp vanilla bean paste (or extract/essence)","1 cup caster sugar (220g / 7 3/4 oz)","2 eggs (, at room temperature)","1/4 cup sour cream or plain yogurt (full fat)","2 tbsp cocoa powder","3/4 tbsp red food colouring","2 cups plain white flour (250g / 9 oz)","1 tsp baking powder"],"purpose":"Cookies"},{"ingredients":["6 tbsp unsalted butter (, softened (75g / 2 1/2 oz))","5 oz / 150g cream cheese (, softened)","1 tsp vanilla bean paste (or extract/essence)","2 1/4 cups powdered (icing) sugar (225g / 7 1/2 oz)"],"purpose":"Cream Cheese Frosting"},{"ingredients":["Red sprinkles (optional)"],"purpose":"Decoration"}]', '[{"description":"Cookies","images":[],"step":1},{"description":"Preheat oven to 180C/350F.","images":[],"step":2},{"description":"Line two cookie sheets with baking (parchment) paper. I streak the tray with a bit of butter to make the paper stay in place.","images":[],"step":3},{"description":"Use a mixer or handheld beater to cream the butter, vanilla extract and sugar until light and fluffy - around 3 minutes on high.","images":[],"step":4},{"description":"Add the eggs, sour cream, cocoa powder and red food colour and mix until combined.","images":[],"step":5},{"description":"Add the flour and baking powder and mix until just combined.","images":[],"step":6},{"description":"Drop heaped tablespoons of batter onto the baking tray, spacing them out around 1 inch / 2.5cm from each other and the edge of the tray.","images":[],"step":7},{"description":"Bake for 8 to 10 minutes until the top springs back when touched.","duration":9,"images":[],"step":8},{"description":"Allow to cool for 5 minutes on the tray before transferring to a wire rack.","duration":5,"images":[],"step":9},{"description":"Top with cream cheese frosting and red sprinkles, if using.","images":[],"step":10},{"description":"Cream Cheese Frosting","images":[],"step":11},{"description":"Beat the ingredients together until fluffy and smooth - around 5 minutes on high.","images":[],"step":12}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":[],"categories":["baking-recipes","cookies","dessert-recipes","most-popular"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_02175736ddd9', 'en', 'US', 'Magic Three Layer Custard Cake (From One Batter)', 'One simple batter turns into a 3 layered cake with a top layer of sponge, a middle layer of custard and a fudge-like base. It''s like....magic! Adapted from Magic Cake by Jo Cooks.', 'https://www.recipetineats.com/tachyon/2015/04/Magic-Cake-Slice-Close-Up_680px.jpg', 20, 50, 70, 9, '[{"id": "ing_egg", "quantity": {"value": 4.0, "unit": "carton of 12"}}, {"id": "ing_sugar", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_strawberries", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_cream", "quantity": {"value": 0.004, "unit": "carton of 250ml"}}]', '[{"ingredients":["4 eggs (, yolks and whites separated (at room temperature))","3/4 cup (150g) sugar ( (ordinary or caster sugar))","1 tsp vanilla extract","1 stick (4oz / 125g / 1/2 cup) unsalted butter (, melted )","3/4 cup (4oz / 115g) plain all purpose flour","2 cups (500 ml / 1 pint) milk ((lukewarm) (full fat or low fat but not zero fat) )"]},{"ingredients":["Icing sugar ((powdered sugar), for dusting)","Fresh strawberries","Whipped cream"],"purpose":"To Serve (optional)"}]', '[{"description":"Preheat oven to 325F/160C (standard oven / fan forced or convection)","images":[],"step":1},{"description":"Butter a 8\" x 8\" / 20cm x 20cm square cake tin (Note 4).","images":[],"step":2},{"description":"Beat egg whites with a mixer until stiff peaks form. Set aside.","images":[],"step":3},{"description":"Place the egg yolks and sugar in a bowl and beat until it turns pale yellow - about 1 minute.","images":[],"step":4},{"description":"Add the vanilla extract and butter and beat until well incorporated - about 30 seconds to 1 minute.","images":[],"step":5},{"description":"Add the flour and beat until just combined.","images":[],"step":6},{"description":"Pour the milk in slowly while beating, and beat until well combined (or if using a hand held mixer, add 1/4 milk at a time, beating in between).","images":[],"step":7},{"description":"Use a spatula to fold in the egg whites in the batter, one third at a time, until just incorporated. You don''t want to knock the air out of the egg whites. Don''t worry if there are a few egg white lumps in the batter. The batter should be very thin, almost like a thick pouring cream.","images":[],"step":8},{"description":"Pour the batter into the prepared cake tin.","images":[],"step":9},{"description":"Baking Directions","images":[],"step":10},{"description":"Bake until the top is golden brown and the cake does not \"jiggle\" when you gently shake the tin - around 40 to 50 minutes. Check the cake at 30 minutes - if the top is already golden brown but the cake is not yet set (i.e. it jiggles), cover loosely with foil and return to the oven, 10 minutes at a time, until set.","images":[],"step":11},{"description":"Allow to cool in the tin for 10 minutes, then turn out onto a cooling rack.(Note 3) Cool completely before serving.","duration":10,"images":[],"step":12},{"description":"To Serve","images":[],"step":13},{"title":"Cut into squares","description":"I cut it into 12 in the photo, but 9 is more realistic serving size portions.","images":[],"step":14},{"description":"Dust with icing sugar just before serving.","images":[],"step":15},{"description":"Serve with a side of whipped cream and strawberries, if using.","images":[],"step":16}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":[],"categories":["baking-recipes","dessert-recipes","easter-baking-desserts","easter-recipes","most-popular"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_03e6331326a9', 'en', 'US', 'Brownie Cookie Sandwich with Peanut Butter Frosting', 'Brownie cookies sandwiched together with a fluffy peanut butter frosting! The cookie has a thin crackly surface (just like normal brownies!) and is soft and moist on the inside. Not dense and fudgey, not cakey, it lies in between. Possibly the most indulgent cookie I have ever had. The frosting is fluffy and creamy with a touch of salt which cuts through the richness. I made these quite large - around 3.5" / 8.5cm in diameter - and it makes 10. These are an extremely generous serving and quite rich so if you don''t have a major sweet tooth, you may want to make them smaller (makes 20 cookies with a 2"/5cm diameter).', 'https://www.recipetineats.com/tachyon/2015/03/Brownie-Cookie-Sandwich-Peanut-Butter-Frosting-2.jpg', 30, 15, 45, 10, '[{"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_chocolate", "quantity": {"value": 10.0, "unit": "block of 100g"}}, {"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_cocoa_powder", "quantity": {"value": 0.12, "unit": "pack of 250g"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.017, "unit": "tub of 150g"}}, {"id": "ing_flour", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.4, "unit": "jar of 375g"}}, {"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_cream", "quantity": {"value": 0.333, "unit": "carton of 250ml"}}]', '[{"ingredients":["1 stick / 1/2 cup / 115g unsalted butter (, cut into chunks)","10 oz / 300g dark chocolate chips (or buttons, melts or block chocolate cut into chunks)","1 cup + 2 tbsp caster sugar","3 eggs","2 tbsp cocoa powder","1 tsp vanilla extract","1/2 tsp salt","1/2 tsp baking powder","3/4 cup plain flour","1/2 cup dark chocolate chips"],"purpose":"Brownie Cookie"},{"ingredients":["1 cup smooth peanut butter","1 cup confectioners'' sugar (icing sugar)","2.5 oz / 5 tbsp / 70g / 2/3 stick unsalted butter (, softened)","3/4 tsp vanilla extract","1/4 tsp salt","1/3 cup heavy cream (unwhipped pouring cream)"],"purpose":"Peanut Butter Frosting"}]', '[{"description":"Brownie Cookie","images":[],"step":1},{"description":"Preheat oven to 180C/350F.","images":[],"step":2},{"description":"Line two baking trays with parchment / baking paper.","images":[],"step":3},{"description":"Pour 1\" / 2.5cm of water into a large saucepan or small pot and bring to a simmer over medium low heat.","images":[],"step":4},{"description":"Place a bowl over the simmer water and melt the butter and 10oz/300g chocolate chips. Stir until smooth.","images":[],"step":5},{"description":"While the chocolate is melting, place the eggs, cocoa powder and sugar in a bowl and beat for 3 minutes on high (using an electric beater or stand mixer with the whisk attachment).","duration":3,"images":[],"step":6},{"description":"Pour 1/3 of the melted chocolate into the egg mixture and mix well, then pour the remaining melted chocolate in and mix again.","images":[],"step":7},{"description":"Add the vanilla, salt and baking powder and mix until combined.","images":[],"step":8},{"title":"Add the flour and mix until just combined","description":"do not over mix.","images":[],"step":9},{"description":"Fold in 1/2 cup dark chocolate chips. See image below for batter consistency.","images":[],"step":10},{"description":"To make large ones like I did, drop 2 tbsp of mixture onto the baking tray, leaving 2\"/5cm between each cookie. To make normal sized ones, use 1 tbsp of mixture per cookie. (Note 1)","images":[],"step":11},{"description":"Bake large cookies for 15 minutes for very soft or 17 to 20 minutes for firmer cookies. Bake small ones for 10 to 12 minutes for very soft, or 15 minutes for firmer. (Either way it is still moist!)","duration":15,"images":[],"step":12},{"description":"Allow to rest on the baking tray for 5 to 10 minutes before carefully transferring to a cooling rack.","duration":7.5,"images":[],"step":13},{"description":"Peanut Butter Frosting","images":[],"step":14},{"description":"Place all ingredients except the cream in a stand mixer bowl with the paddle attachment. Beat for 5 minutes on high, or until creamy. Scrape down the sides as you go. Add the cream then beat for a further 2 minutes, or until the frosting is fluffy.","duration":5,"images":[],"step":15},{"description":"This can also be done using a hand held beater but it will take a few minutes longer.","images":[],"step":16},{"description":"Spread Peanut Butter frosting on a cookie, then sandwich with another cookie. Repeat with remaining cookies.","images":[],"step":17}]', '["egg","gluten","milk","peanuts"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":[],"categories":["baking-recipes","cookies","dessert-recipes","most-popular"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7a180c242f83', 'en', 'US', 'Baked Apple Pie Fries with Salted Caramel Dipping Sauce', 'Your favourite apple pie....as fries!! These are a great finger food dessert for casual entertaining. Using my tip to freeze the pastry after sandwiching it with the Apple Pie Filling, cutting them into perfect strips with plenty of filling in each piece is a breeze (otherwise it squirts out when you cut it!). Served with a super fast and simple salted caramel sauce.', 'https://www.recipetineats.com/tachyon/2015/02/Baked-Apple-Pie-Fries-with-Salted-Caramel-Dipping-Sauce-2.jpg', 15, 25, 40, 36, '[{"id": "ing_apples", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_cinnamon", "quantity": {"value": 1.25, "unit": "jar"}}, {"id": "ing_sheets_frozen_shortcrust_pastry", "quantity": {"value": 2.0, "unit": "pack"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}]', '[{"ingredients":["1 1/4 cups canned Apple Pie Filling (increase to 1 3/4 cups if using US refrigerated pie crust) (Note 1)","3 tbsp sugar (your choice - white, brown, raw) (Note 2)","1/4 tsp cinnamon","2 sheets frozen shortcrust pastry (25cm/10\" square) (do not thaw) OR 14 oz refrigerated pie crust (Note 1)","1 egg","2 tbsp sugar granules (or ordinary sugar) (optional - for sprinkling)","Oil spray"],"purpose":"Apple Pie Fries"},{"ingredients":["1 cup caster sugar","1/3 cup water","1/2 cup heavy cream (not whipped)","1/4 tsp salt","1 tbsp unsalted butter"],"purpose":"Salted Caramel Sauce"}]', '[{"description":"Place Apple Pie Filling, sugar and cinnamon in the food processor and whizz until smooth.","images":[],"step":1},{"description":"Working quickly so the pastry does not defrost, place one sheet of pastry on a cutting board or other flat surface. Spread the filling over the pastry, leaving a thin border. Place the other sheet on top. Brush with egg wash, sprinkle with sugar granules (if using) then place the pastry in the freezer for at least 1 hour (Note 3).","images":[],"step":2},{"description":"Preheat oven to 180C/350F. Spray large baking tray with oil (or 2 small ones).","images":[],"step":3},{"description":"Remove pastry from the freezer. Let it defrost for 5 to 10 minutes, until the pastry is softened - it doesn''t need to thaw completely but it can''t be frozen stiff otherwise it will crack when you cut it. DO NOT let the pie filling defrost!","duration":7.5,"images":[],"step":4},{"description":"Use a large knife to cut it into \"fries\". I cut mine into 12 strips vertically (2cm / 4/5\" wide) then 3 horizontally (8cm/3\" long) to make 36 fries.","images":[],"step":5},{"description":"Carefully transfer to baking tray and set them aside to come to room temperature while the oven heats up.","images":[],"step":6},{"description":"Bake for 15 to 25 minutes, until golden brown on top. (Note 4)","duration":20,"images":[],"step":7},{"description":"Remove from oven, let it rest for 5 minutes then transfer to cooking rack.","duration":5,"images":[],"step":8},{"description":"Serve with Salted Caramel Sauce.","images":[],"step":9},{"description":"Salted Caramel Sauce","images":[],"step":10},{"description":"Place sugar and water in a small saucepan over high heat. Swirl the pan to help the sugar dissolve easily but do not stir. Let it come to a rapid simmer and cook for around 3 to 4 minutes until it turns a light golden brown.","images":[],"step":11},{"description":"Remove from heat and CAREFULLY and slowly pour the cream in (it will bubble and froth slightly pour slowly). Whisk to combine. Then add the salt and butter and whisk again.","images":[],"step":12},{"description":"Serve with Apple Pie Fries.","images":[],"step":13}]', '["egg","milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":[],"categories":["baking-recipes","bite-size-desserts","dessert-recipes","most-popular"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_fc7bc7289687', 'en', 'US', 'Man Candy: Candied Bacon and Nuts', 'Easy to make, and a great gift for any bacon lover. Just be careful who you give it to. Because they will be begging you to make it again and again and again!!', 'https://www.recipetineats.com/tachyon/2015/01/DSC_0519.jpg', 10, 25, 35, 6, '[{"id": "ing_bacon", "quantity": {"value": 1.2, "unit": "pack of 200g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.016, "unit": "jar of 40g"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.06, "unit": "jar of 50g"}}, {"id": "ing_pecans", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_walnuts", "quantity": {"value": 150.0, "unit": "jar"}}, {"id": "ing_maple_syrup", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_pumpkin", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.06, "unit": "jar of 50g"}}]', '[{"ingredients":["6 slices centre cut or middle bacon (about 200g / 6 oz) (Note 1)","1/4 cup brown sugar (light or normal)","1/2 tsp paprika (Note 2)","1/8 tsp cayenne pepper (Note 2)","1 lemon (, zest only)","Pinch of salt","Black pepper (3 grinds)"],"purpose":"Candied Bacon"},{"ingredients":["1 cup pecans (, roughly chopped)","1 cup walnuts (, roughly chopped)","1/4 cup brown sugar (light or normal)","2 tbsp maple syrup","1 tsp pumpkin pie spice (Note 3)","1/2 tsp paprika (Note 2)","1/8 tsp cayenne pepper (Note 2)","1/8 tsp pepper","Black pepper (3 grinds)"],"purpose":"Candied Nuts"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Line a baking tray with baking paper (parchment paper).","images":[],"step":2},{"description":"Cut the bacon into 1.5cm / 0.6\" pieces (remove rind if it has it).","images":[],"step":3},{"description":"Combine with remaining Candied Bacon ingredients in a bowl and use your fingers to coat the bacon.","images":[],"step":4},{"description":"Combine the Candied Nuts ingredients in a bowl and toss to combine.","images":[],"step":5},{"description":"Spread the Candied Bacon onto a baking tray and bake for 10 minutes, or until the sugar is bubbling and the bacon is starting to turn brown (i.e. almost cooked).","duration":10,"images":[],"step":6},{"description":"Remove the bacon from the tray using a slotted spatula (so you don''t get too much bacon fat) and transfer it into the bowl with the nuts. Mix to combine.","images":[],"step":7},{"description":"Use a spatula to scrape and pour the excess oil off the parchment paper (this is what I did).","images":[],"step":8},{"description":"Pour the nuts back onto the baking tray and bake for 15 minutes, stirring once at half time.","duration":15,"images":[],"step":9},{"description":"Turn the oven off and open the door slightly. Leave for at least 15 minutes, then remove and allow to cool.","images":[],"step":10},{"description":"Break the candy into chunks. To store, place into an airtight container and keep in the refrigerator. (Note 4)","images":[],"step":11}]', '[]', '["gluten_free"]', '{"mealType":["main_course"],"cuisine":[],"categories":["baking-recipes","bite-size-desserts","dessert-recipes","dietary","gluten-free-recipes","most-popular","pork-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f91e7b29519b', 'en', 'US', 'Gingerbread Boxes & Mason Jars', 'Gingerbread Cookies transformed into mason jars and boxes! No cookie cutter, mixer or any other special equipment required to make these. Fill with goodies for a completely edible homemade gift! Tip: The Mason Jars are easier to make because they don''t require constructing! This recipe makes either 2 boxes or 2 mason jars. Please note: The gingerbread recipe used in this recipe is specific for this recipe. It is lighter than most gingerbread recipes (less butter, honey instead of molasses or golden syrup) so the Mason Jar doesn''t slide down the can while baking (which is what happens if you use a gingerbread recipe with more butter in it). For Gingerbread Men and Cookies, use this Gingerbread Men recipe.', 'https://www.recipetineats.com/tachyon/2014/11/Gingerbread-Boxes-Mason-Jars-10.jpg', 45, 15, 60, 2, '[{"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_honey", "quantity": {"value": 0.25, "unit": "jar of 500g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_flour", "quantity": {"value": 0.375, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.033, "unit": "tub of 150g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.025, "unit": "tub of 200g"}}, {"id": "ing_ginger", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_round_cinnamon", "quantity": {"value": 7.5, "unit": "jar"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_chocolate", "quantity": {"value": 1.0, "unit": "block of 100g"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_x_empty_400g_cans", "quantity": {"value": 2.0, "unit": "kg"}}]', '[{"ingredients":["50 g / 1.8 oz unsalted butter (, chopped)","1/2 cup firmly packed brown sugar","1/2 cup honey","1 egg (, lightly whisked)","2 1/2 cups plain flour","1 tsp baking powder","1 tsp bicarbonate of soda","1 1/2 tsp ground ginger","1 1/2 tsp ground cinnamon","1/2 tsp All Spice (or ground cloves)"],"purpose":"Gingerbread"},{"ingredients":["1 cup milk chocolate buttons"],"purpose":"To Construct Boxes"},{"ingredients":["1 egg (, white only)","2 cups sifted icing sugar (confectioner''s sugar)"],"purpose":"Royal Icing (Optional for decorating)"},{"ingredients":["Silver Sugar Balls"],"purpose":"Decorations (Optional)"},{"ingredients":["2 x empty 400g /14oz cans (, washed and labels removed (e.g. canned tomatoes))"],"purpose":"Equipment Required for Mason Jars"}]', '[{"description":"Place butter, brown sugar and honey in a small saucepan over low heat. Stir until the butter is melted and sugar is dissolved. Set aside until almost at room temperature. (Note 1)","images":[],"step":1},{"description":"Pour into a large bowl and add the egg. Mix until combined.","images":[],"step":2},{"description":"Sift the remaining Gingerbread ingredients straight into the bowl. Mix until just combined, then use your hands to knead it a few times in the bowl to bring the dough together. (Or turn onto work surface if your bowl isn''t large enough).","images":[],"step":3},{"description":"Flatten dough into a disc, wrap in cling wrap and place in the fridge for 1 1/2 hours. (Note 2)","images":[],"step":4},{"description":"Remove dough from fridge. For ease of handling, cut the dough into 2 pieces. Use a rolling pin to roll out to 3mm / 1/ 10\" thickness between two pieces of baking (parchment) paper. See Note 3 for an easy way to do this.","images":[],"step":5},{"description":"Proceed with instructions to make Boxes or Mason Jars.","images":[],"step":6},{"description":"Preparing and Baking Boxes","images":[],"step":7},{"description":"Preheat oven to 180C/350F with one oven shelf in the centre and the other directly below it.","images":[],"step":8},{"description":"Line 2 baking trays with baking paper (parchment paper).","images":[],"step":9},{"description":"Cut out 12 squares from the rolled out dough that are 8cm x 8 cm (3\" x 3\"). Place onto baking tray.","images":[],"step":10},{"title":"Optional","description":"Cut 2 x small squares to use as the \"knob\" in the centre of the lid. Place small squares in the centre of 2 squares.","images":[],"step":11},{"description":"Bake for 12 to 15 minutes until golden brown. The top tray will take around 12 minutes, the bottom tray will be closer to 15 minutes (move it to the upper shelf when you take out the first tray).","duration":13.5,"images":[],"step":12},{"description":"Allow to stand for 5 minutes on the tray then remove onto cooling racks.","duration":5,"images":[],"step":13},{"description":"Constructing Boxes","images":[],"step":14},{"description":"Once the squares are cool, select 8 squares to be the walls of the boxes and line them up in front of you with the flat side down on the bench (i.e. the side that was on the baking tray).","images":[],"step":15},{"description":"Use a knife to trim the bottom and right side of each square (to make the edges flat - easier to construct).","images":[],"step":16},{"description":"Melt the milk chocolate buttons.","images":[],"step":17},{"description":"Use a knife to spread melted chocolate on the right edge (that you trimmed) of one square (Square A). Hold Square A standing upright so the bottom edge (that you trimmed) is flat on the work surface.","images":[],"step":18},{"description":"Get another square (Square B) and hold it upright so the bottom trimmed edge is on the work surface. Attach the chocolate edge of Square A to the flat side of Square B (i.e. the side that was on the baking tray). Hold for 20 seconds to let the chocolate firm up a bit.","duration":0.3333333333333333,"images":[],"step":19},{"description":"On Square B, use a knife to spread melted chocolate on the right edge you trimmed. Then attach that to another square, then repeat until you have constructed the walls of a box. Repeat for other box.","images":[],"step":20},{"description":"While the walls are setting, get two more squares. Trim them with a knife so they are the right size to fit inside the walls - this will be the Base of the box. Spread a little chocolate on the edges of the square then pick up the walls and put it over the Base and push down so the Base fits inside the walls.","images":[],"step":21},{"description":"Use Royal Icing to hide the edges and decorations of choice. I used Silver Sugar Balls. Attach the decorations while the Royal Icing is wet.","images":[],"step":22},{"description":"Prepare Mason Jars","images":[],"step":23},{"description":"Line 1 baking tray with baking paper (parchment paper).","images":[],"step":24},{"description":"Press the open end of the can into the dough to cut out 2 rounds. These will be the base.","images":[],"step":25},{"description":"Cut 2 x strips of baking paper that are at least the height of the can and are long enough so it will overlap when you wrap the can. Butter the baking paper then wrap around the cans.","images":[],"step":26},{"title":"For cutting the dough","description":"Cut a rectangle out of baking paper that is the height of the can and the length to wrap around the can with a 1 inch / 2cm overlap. **This is important. See Note 4.**","images":[],"step":27},{"description":"Lay the rectangle from step 4 on the dough and use a large knife to cut out the rectangle. Repeat to make two rectangles.","images":[],"step":28},{"description":"Leaving the dough on the baking paper it was rolled out on, place the can on one end of the dough and roll up firmly to cover the can. Make sure it wraps snugly, saggy dough will result in a saggy Mason Jar. Remove parchment paper, trim any excess dough and use your fingers to seal. Repeat with other can. Place the cans on their side on the baking tray, seam side down.","images":[],"step":29},{"description":"Gather up the dough remnants and roll out again. Place one can with the dough wrapped around it upright onto the dough and use a small knife to cut out rounds. Repeat to make 2 rounds. These will be the lids. Place onto baking tray.","images":[],"step":30},{"title":"Optional","description":"Cut a small square and place in the centre of the lids. (I forgot to do this and had to stick on a cooked piece of gingerbread!)","images":[],"step":31},{"description":"Place baking tray in the fridge with the cans on their side for 30 minutes. This helps stop the mason jars from sliding down when baking.","duration":30,"images":[],"step":32},{"description":"Baking Mason Jars","images":[],"step":33},{"description":"Preheat oven to 180C/350F. Put the oven shelf in the middle of your oven (note 5).","images":[],"step":34},{"description":"Remove the baking tray from the fridge. If the dough on the cans has sagged slightly, use your hands to press it against the can.","images":[],"step":35},{"description":"Turn the cans upright on the baking tray and place the tray into the oven.","images":[],"step":36},{"description":"Bake for 20 to 25 minutes, until golden brown, turning the tray halfway through (so the mason jar bakes an even colour).","duration":22.5,"images":[],"step":37},{"description":"Remove from oven and let cool for 5 minutes before transferring to a cooling rack.","duration":5,"images":[],"step":38},{"description":"Once cool, gently pull the can and baking paper out of the Mason Jar. It should slip out fairly easily, if not, just twist it slightly to loosen then pull out.","images":[],"step":39},{"description":"Fit the small circles into the base of the Mason Jar. It might need trimming to fit - be careful not to over trim, you want it to fit snugly. You do not need anything to make it stay in place because the gingerbread is sticky and the base should fit snugly.","images":[],"step":40},{"description":"Decorating is optional. With a ribbon, I don''t think any decorations are required. On one, I piped Royal Icing along the bottom, top and rim with Silver Sugar Balls.","images":[],"step":41},{"description":"Use a mixer to beat the egg white until soft peaks form. Gradually add icing sugar, a heaped dessert spoon at a time, making sure it is incorporated before adding the next tablespoon.","images":[],"step":42},{"description":"Transfer the Royal Icing into a piping bag with tip of choice.","images":[],"step":43},{"description":"Use to decorate the Boxes and Mason Jar, as desired.","images":[],"step":44},{"description":"Fill with homemade (or bought) treats of choice. Mine are pictured filled with homemade Chocolate Ganache Truffles. Tie with ribbons to make them pretty!","images":[],"step":45}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["baking-recipes","dessert-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2114100f10be', 'en', 'US', 'Mini Apple Pie Wonton Cups', 'When you''re pressed for time, these mini apple pies are great to prepare for a crowd! All the elements can be prepared ahead then it takes just minutes to assemble to serve.', 'https://www.recipetineats.com/tachyon/2014/11/DSC_0262.jpg', 10, 10, 20, 18, '[{"id": "ing_wonton_wrappers", "quantity": {"value": 18.0, "unit": "unit"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_small", "quantity": {"value": 5.0, "unit": "unit"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.333, "unit": "kg"}}, {"id": "ing_cinnamon", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.333, "unit": "kg"}}, {"id": "ing_few_drops_vanilla_essence", "quantity": {"value": 0.003, "unit": "jar"}}]', '[{"ingredients":["18 wonton wrappers","Oil spray"]},{"ingredients":["5 cups small diced (, peeled Granny Smith apples (around 1.5 lb / 800g, 5 medium size apples))","2 tbs butter","1/3 to 1/2 cup brown sugar (adjust to taste, depends on tartness of apples)","2 tsp cinnamon","1/4 cup water","Pinch of salt"],"purpose":"Apple Pie Filling"},{"ingredients":["3/4 cup whipping cream (unwhipped)","2 tbsp powdered sugar ((icing sugar), sifted)","Few drops vanilla essence"],"purpose":"Cream"}]', '[{"description":"Preheat oven to 390F/200C.","images":[],"step":1},{"description":"Mould wonton wrappers into standard size muffin tin / cupcake trays. Spray lightly with oil (this helps them bake evenly golden) then bake for 10 to 15 minutes until crisp and golden. Remove from oven and let cool in the muffin tins.","duration":12.5,"images":[],"step":2},{"description":"Meanwhile, place Apple Pie Filling ingredients in a large saucepan over high heat. Bring to simmer, then turn the heat down to medium. Let simmer, stirring occasionally, until the apple is softened, around 8 minutes. There should be no liquid left, just a syrupy coating on the apple. Adjust sweetness to taste. The amount of sugar required differs depending on the tartness/sweetness of the apples. Remove from heat and let cool until it is warm.","images":[],"step":3},{"description":"Meanwhile, whip cream and powdered sugar (icing sugar) until soft peaks form.","images":[],"step":4},{"description":"To serve, spoon still warm Apple Pie Filling into wonton cups and top with a dollop of cream. Serve immediately.","images":[],"step":5}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":[],"categories":["baking-recipes","bite-size-desserts","dessert-recipes","sweet-pies"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4df459bde8fb', 'en', 'US', 'Peanut Butter Chocolate Molten Lava Cake', 'This luxurious looking dessert is so simple to make! The two key things to ensure you do are: 1) grease and dust the mould so they slip out easily when you turn them out onto a plate; and 2) don''t overfill the mould! You don''t need to use expensive chocolate for this. And though I made these in dariole moulds, you can make these in ramekins or even a muffin tin.', 'https://www.recipetineats.com/tachyon/2014/10/Peanut-Butter-Chocolate-Lava-Molten-Cake-2.jpg', 7, 16, 23, 5, '[{"id": "ing_chocolate", "quantity": {"value": 7.0, "unit": "block of 100g"}}, {"id": "ing_butter", "quantity": {"value": 3.5, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_peanut_butter", "quantity": {"value": 5.0, "unit": "jar of 375g"}}, {"id": "ing_cocoa_powder", "quantity": {"value": 1.0, "unit": "pack of 250g"}}]', '[{"ingredients":["7 oz / 200g dark chocolate melts (note 1)","3.5 oz / 100g unsalted butter (, chopped)","2 eggs","2 egg yolks","1/2 cup caster sugar","2 tbsp flour","5 heaped tsp smooth peanut butter","Cocoa powder (, for dusting)"]}]', '[{"description":"Preheat oven to 200C/390F (standard) or 180C/350F (convection/fan forced).","images":[],"step":1},{"description":"Place chocolate and butter in a bowl. Microwave in 30 second bursts, stirring in between. Stir well to combine butter and chocolate and leave to cool for 5 minutes.","duration":5,"images":[],"step":2},{"description":"Meanwhile, generously grease 5 x 3/4 cup dariole moulds then dust with cocoa powder. (See notes 2 and 3)","images":[],"step":3},{"description":"In a separate bowl, whisk together the eggs (2 x whole eggs + 2 x yolks) and sugar.","images":[],"step":4},{"description":"Add the chocolate mixture and mix until combined.","images":[],"step":5},{"description":"Add flour and fold through until just combined. Do not over mix.","images":[],"step":6},{"description":"Pour batter into dariole moulds until it reaches halfway.","images":[],"step":7},{"description":"Drop a heaped teaspoon of peanut butter in the centre of each. Push down gently to mostly submerge.","images":[],"step":8},{"description":"Top up with remaining batter until the dariole mould is 3/4 filled. Do not overfill! (Note 4)","images":[],"step":9},{"description":"Bake for 16 minutes, or until the top springs back when touched gently. (Note 5)","duration":16,"images":[],"step":10},{"description":"Turn out onto plate. If you dusted the mould with cocoa powder, it should slip out easily. If it does not, then run a knife around the edge.","images":[],"step":11},{"description":"Serve immediately!","images":[],"step":12}]', '["egg","gluten","milk","peanuts"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":[],"categories":["baking-recipes","dessert-recipes","egg-yolk-recipes","most-popular"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1fdd4f16dc30', 'en', 'US', '3 Ingredient Shortbread Cookie Sandwich w/Dulce De Leche', 'These shortbread cookies only require 3 ingredients and 10 minutes to prepare to pop into the oven! These are sandwiched with Dulce De Leche caramel filling which requires only 1 ingredient and takes 15 seconds to prepare. I made these cookies quite large so each one is a rather generous sized serving. You can make them smaller if you want, just adjust the baking time.', 'https://www.recipetineats.com/tachyon/2014/10/Dulce-De-Leche-Shortbread-Cookie-Sandwich-1.jpg', 10, 20, 30, 8, '[{"id": "ing_butter", "quantity": {"value": 225.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_dulce_de_leche_1_ingredient_recipe", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["225 g / 8 oz (2 sticks) unsalted butter (, softened)","1/2 cup icing sugar ((powdered sugar), plus extra for dusting work surface)","2 cups plain flour","Dulce De Leche (see Slow Cooker Dulce De Leche (Caramel Sauce) - 1 ingredient recipe)"]}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Line a baking tray with parchment paper. If your baking tray is small, you might need 2.","images":[],"step":2},{"description":"Combine butter and icing sugar in a bowl and mix until smooth and well combined.","images":[],"step":3},{"description":"Add flour and mix until it starts to look like dough (it will start out looking crumbly but it will come together). Use your hands to roughly form a ball.","images":[],"step":4},{"description":"Scatter icing sugar over a work surface and turn the dough out onto it.","images":[],"step":5},{"description":"Flatten out to about 1cm / 1/2” thickness with your hand, then place a sheet of baking paper over it and use a rolling pin to lightly roll it out to 0.5cm / 1/4 “ thickness.","images":[],"step":6},{"description":"Use a 6.5cm/2.5” round cookie cutter to cut rounds out, then use a knife or egg flip to transfer the cookies to the baking tray.","images":[],"step":7},{"description":"Ball up the excess dough and cut more rounds. You should get 16 cookies.","images":[],"step":8},{"description":"Bake for 15 to 18 minutes until pale golden brown and starting to just slightly brown on the edges. You might think it is undercooked, but it will continue to cook on the baking tray.","duration":16.5,"images":[],"step":9},{"description":"Remove baking trays from oven and let the cookies cool on the tray.","images":[],"step":10},{"description":"When the cookies are cool, spread half the cookies with a dollop of Dulce De Leche. Then sandwich with remaining cookies.","images":[],"step":11}]', '["gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":[],"categories":["baking-recipes","cookies","dessert-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7c446c04df7a', 'en', 'US', 'Crispy Pork Belly Banh Mi', 'Recipe video above. The crispy pork belly version of the famous Vietnamese sandwich, inspired by Ca Com in Melbourne, a famous banh mi shop. Hands down one of the best sandwiches I have ever made in my life, and my favourite type of banh mi (all my recipes here). Excellent food for sharing with friends and Sunday lunches.The Special Sauce is a copycat of the Ca Com sauce and it''s an excellent match for crispy pork - thicker so it clings and doesn''t soak and soften the skin or bread.PS The recipe for the crispy skin pork belly is based on the much-loved Crispy Pork Belly recipe. So you can have confidence that your pork WILL have perfect crispy crackling!', 'https://www.recipetineats.com/tachyon/2024/03/Crispy-pork-belly-banh-mi_3.jpg', 15, 180, 195, 5, '[{"id": "ing_pork", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_chinese_five_spice", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 60.0, "unit": "bottle"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.113, "unit": "can of 400ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.01, "unit": "bottle of 250ml"}}, {"id": "ing_bread", "quantity": {"value": 5.0, "unit": "loaf"}}, {"id": "ing_chicken", "quantity": {"value": 0.12, "unit": "kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.225, "unit": "jar of 400g"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.06, "unit": "bunch"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 1.2, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 3.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.06, "unit": "bunch"}}]', '[{"ingredients":["1kg / 2 lb pork belly with skin on","1 1/2 tsp canola or vegetable oil (, divided)","1/2 tsp Chinese Five Spice (, optional (you won''t miss it))","1 tsp cooking/kosher salt (, divided)","1/4 tsp black pepper (or white pepper)"],"purpose":"Crispy pork belly for banh mi"},{"ingredients":["4 tbsp Hoisin sauce","3 tbsp coconut milk (, full fat)","1/2 tsp dark soy sauce (mainly for colour, sub light or regular soy)"],"purpose":"Special banh mi sauce (Ca Com copy!)"},{"ingredients":["5 crusty white rolls (lightly oven toast to crisp if crust is softened)","120g/ 4 oz chicken pate (Note 2)","6 tbsp whole-egg mayonnaise (or Kewpie)","1 batch Vietnamese pickled carrots and daikon ()","3 green onion stems (, cut to length of rolls (2 to 3 pieces per roll))","2 cucumbers (, finely sliced using vegetable peeled or knife)","2 cups coriander/cilantro leaves (and small sprigs)","3 Birds Eye or Thai chillis (, finely sliced)","8 tbsp crispy fried shallots (, store bought (Note 3))"],"purpose":"To make the banh mi (5 rolls)"}]', '[{"description":"Crispy pork belly for banh mi","images":[],"step":1},{"title":"Dry skin overnight","description":"Place pork belly on a plate. Pat skin dry with paper towels. Leave uncovered in fridge overnight to dry out the skin. (If you don''t have time, pat the skin dry as best you can).","images":[],"step":2},{"description":"Preheat oven to 140°C/285°F (both fan and standard ovens).","images":[],"step":3},{"title":"Season flesh","description":"Drizzle flesh side with 1 tsp oil. Sprinkle over 1/2 tsp salt, and all the pepper and Chinese five spice. Rub all over the flesh, including on the sides.","images":[],"step":4},{"title":"Foil boat","description":"Place 2 pieces of foil on a work surface. Put the belly in middle of foil, skin side up. Fold the sides in to enclose the belly, forming an open box, pinching corners to seal tightly and make it as snug as possible. Place meat on a tray.","images":[],"step":5},{"title":"Season skin","description":"Pat skin dry with paper towels. Rub with 1/2 tsp oil then sprinkle remaining 1/2 tsp salt evenly all over the skin surface, from edge to edge.","images":[],"step":6},{"title":"Slow roast 2 hours","description":"Place in the oven and roast for 2 hours, tightening the foil around the pork after 1 hour (the pork will shrink). This protects the flesh from drying out.","images":[],"step":7},{"title":"Increase heat","description":"Remove pork from oven, then increase heat to 240°C/465°F (all oven types).","images":[],"step":8},{"title":"Level pork","description":"Remove pork from foil, discard fat and foil. Place pork on a rack set over a tray. Use scrunched up balls of foil stuffed under pork to prop it up so the skin surface is as level and horizontal as possible (see photos in post).","images":[],"step":9},{"description":"30 minutes blast! Place the pork back in the oven for 30 minutes, rotating after 15 minutes as needed, until the crackling is deep golden, puffy and crispy all over. If some patches are browning faster, protect with foil patches.","duration":30,"images":[],"step":10},{"title":"Rest 10 minutes","description":"Remove pork from oven. Rest for 10 minutes before slicing.","duration":10,"images":[],"step":11},{"description":"Making the banh mi","images":[],"step":12},{"title":"Sauce","description":"Mix the ingredients in a bowl then set aside. This will keep for 5 days in the fridge .","images":[],"step":13},{"title":"Chop pork","description":"Cut the pork into 1 1/2 cm / 0.6\" thick slices, then each slide into 1 1/2 cm / 0.6\" chunks.","images":[],"step":14},{"title":"Split & spread","description":"Split the roll in half down the side, keeping the lid attached. Smear the base with 1 1/2 tbsp of pate, then 1 1/2 tbsp of mayonnaise (on top of the pate)","images":[],"step":15},{"title":"Stuff","description":"Pile about 1/3 cup pickled vegetables on the mayonnaise. Lay 2 slices of cucumber and 2 green onions against the lid. Pile pork on top. Drizzle pork with 1 tbsp of sauce. Stuff coriander/cilantro down the side, sprinkle with chilli then2 tablespoons of crispy shallots as you want (if using).","images":[],"step":16},{"title":"Serving","description":"Eat immediately! Banh mi is definitely one of those foods best eaten freshly made!","images":[],"step":17}]', '["egg","gluten","soy"]', '["high_protein","keto_friendly"]', '{"mealType":["dinner","lunch"],"cuisine":["Vietnamese"],"categories":["banh-mi","iconic-dishes","modern-asian","sandwiches-and-sliders","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6e846f1512d3', 'en', 'US', 'Vietnamese pickled carrots and daikon (radish)', 'Recipe video above. If you''ve been to Vietnam or Vietnamese restaurants, you''ve probably seen these pickles which are commonly served alongside grilled meats, on noodle bowls (like lemongrass chicken, pork and meatballs) and stuffed generously in Banh Mi! Keeps for 2 months in the fridge - keep the vegetables submerged in the liquid in airtight jars or containers. Excellent with all sorts of Vietnamese food.', 'https://www.recipetineats.com/tachyon/2024/03/Vietnamese-pickled-carrot-and-daikon_9.jpg', 15, 0, 15, 4, '[{"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_daikon", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_vinegar", "quantity": {"value": 0.188, "unit": "L"}}]', '[{"ingredients":["2 medium carrots (, peeled cut into 3mm / 1/10\" batons (Note 1))","1/2 large daikon (white radish) (, peeled, cut the same as carrots (Note 1))","1 1/2 cups boiling water","1/2 cup white sugar","4 tsp cooking / kosher salt","3/4 cup rice wine vinegar (sub apple cider vinegar)"],"purpose":"Pickled vegetables:"}]', '[{"title":"Pickle","description":"In a large bowl, dissolve the salt and sugar in the hot water. Stir in vinegar. Add carrots and daikon - they should just about be covered.","images":[],"step":1},{"title":"2 hours","description":"Leave for 2 hours until the vegetables are slightly floppy.","images":[],"step":2},{"title":"Using","description":"Drain well to use, or just take out what you need (no liquid, just the vegetables).","images":[],"step":3},{"title":"Storing","description":"The vegetables will keep in the fridge for 2 months, in the pickling liquid. Use airtight glass containers or jars (not plastic).","images":[],"step":4}]', '[]', '["gluten_free","high_protein","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Vietnamese"],"categories":["banh-mi","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_50aa37b34562', 'en', 'US', 'Chicken banh mi (Vietnamese sandwich)', 'Recipe video above. This is the chicken version of Vietnamese Banh Mi that''s so popular in Australia! All the familiar flavours of Banh Mi - pate, mayo, fresh herbs and pickled vegetables - but with shredded chicken instead of mystery pink cold cuts. :)Don''t skip the pickled vegetables. They totally make it.For lemongrass grilled chicken, use the chicken in this recipe in place of the shredded chicken, and skip the Maggi seasoning.', 'https://www.recipetineats.com/tachyon/2023/02/Chicken-banh-mi_5.jpg', 15, 0, 15, 4, '[{"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_water", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_vinegar", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_bread", "quantity": {"value": 2.0, "unit": "loaf"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_chicken", "quantity": {"value": 0.12, "unit": "kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.15, "unit": "jar of 400g"}}, {"id": "ing_chicken", "quantity": {"value": 0.12, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_cucumber", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 0.9, "unit": "bunch"}}, {"id": "ing_maggi_seasoning", "quantity": {"value": 0.25, "unit": "unit"}}, {"id": "ing_chilli", "quantity": {"value": 2.0, "unit": "pack of 100g"}}]', '[{"ingredients":["2 medium carrots (, peeled cut into 2-3mm / 1/10\" batons (Note 1))","1/2 large white radish (daikon), peeled, cut the same as carrots (Note 1)","1 1/2 cups boiling water","1/2 cup white sugar","4 tsp cooking / kosher salt","3/4 cup rice wine vinegar (sub apple cider vinegar)"],"purpose":"Pickled vegetables:"},{"ingredients":["4 crusty white rolls (~ 20cm/8\" (Note 2))","2 - 3 tbsp salted butter","120g/ 4 oz chicken pate (or other pate of choice)","4 tbsp whole egg mayonnaise or Kewpie","4 cups (400g/ 14oz) shredded chicken","2 - 3 green onion stems (, cut to bread roll length (3 pieces per Banh Mi))","1 cucumber (, thinly sliced lengthwise (2 slices per Banh Mi))","1 1/2 cups (lightly packed) coriander/cilantro sprigs","1/4 tsp Maggi seasoning (per Banh Mi (Note 3))","2 - 3 birds eye or Thai red chilli (, finely sliced)"],"purpose":"Banh Mi:"}]', '[{"description":"Pickled vegetables:","images":[],"step":1},{"title":"Pickle","description":"In a large bowl, dissolve the salt and sugar in the hot water. Stir in vinegar. Add carrots and daikon - they should just about be covered.","images":[],"step":2},{"title":"2 hours","description":"Leave for 2 hours until slightly floppy. Drain well then use per recipe.","images":[],"step":3},{"description":"Split the bread roll in half but don''t cut all the way through.","images":[],"step":4},{"title":"Butter","description":"Spread the lid with butter.","images":[],"step":5},{"title":"Pate then mayo","description":"Spread the base with 1 to 2 tablespoons pate (be generous!), then 1 1/2 tbsp mayonnaise.","images":[],"step":6},{"title":"Chicken & Maggi","description":"Pile on shredded chicken, drizzle with 1/4 tsp Maggi seasoning (you can always add more later).","images":[],"step":7},{"description":"Fresh stuff! Stuff with pickled vegetables, 2 slices of cucumber, 3 slices of green onion and coriander. Finally, sprinkle with as much chilli as you dare. Jam the lid down and devour!","images":[],"step":8}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["lunch"],"cuisine":["Vietnamese"],"categories":["banh-mi","no-cook-food","sandwiches-and-sliders","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_db37fc0765e7', 'en', 'US', 'Charcoal Chicken Shop Chicken Skewers', 'Recipe video above. This is my copycat of those tasty Chicken Skewers sold at charcoal chicken shops all across Australia. They''re so heavily flavoured they are practically crusted with seasoning, in the best possible way! Great on the BBQ (also, you can cook them all in one go), but honestly just as good on the stove.You can cook them straight away though if you’ve got the time, an overnight marinade will take the flavour to another level.PS See Note 1 if you think this looks good but you''re feeling too lazy to skewer. :)', 'https://www.recipetineats.com/tachyon/2026/03/Kebab-shop-chicken-skewers_4.jpg', 15, 20, 35, 10, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.562, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_sauce_options", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_rice", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_onion", "quantity": {"value": 15.0, "unit": "pack of 1kg"}}]', '[{"ingredients":["800g / 1.6 lb boneless chicken thighs (, cut into large 2.5cm / 1\" squares, I cut each thigh into ~6 to 8 pieces. (Note 1))","3 - 4 tbsp olive oil (, for cooking)"]},{"ingredients":["1 1/2 tbsp garlic powder (or 2 garlic cloves finely grated using microplane)","1 tbsp onion powder (or more garlic powder)","1 tbsp paprika (, regular/sweet (not spicy), smoked great too)","1 tsp mustard power (sub 1 tsp dijon or yellow mustard, not spicy)","1 tsp dried oregano (or thyme)","1/2 tsp curry powder *secret ingredient* (regular grocery stores ones, I use Clives)","1 1/4 tsp cooking salt / kosher salt (halve for table salt, +50% for flakes)","1/2 tsp black pepper","3 tbsp extra virgin olive oil","2 tbsp lemon juice (or white wine/red wine vinegar, or similar)"],"purpose":"Chicken marinade:"},{"ingredients":["Sauce options -","Flatbreads","Shredded lettuce, tomato slices (2 - 3 whole), finely sliced red onion","Shredded lettuce, tomato slices (2 - 3 whole), finely sliced red onion"],"purpose":"For serving – options"}]', '[{"title":"Mix marinade, marinate chicken 12","description":"24 hrs (if you can), skewer, cook 3 minutes on each side on medium high.","images":[],"step":1},{"title":"Marinade","description":"Mix the Marinade ingredients in a bowl, it should be like a paste. Add chicken pieces and toss well to coat every piece well.","images":[],"step":2},{"description":"Marinate for 12 to 24 hours (even 3 hours helps) though they are still tasty cooked straight away!","images":[],"step":3},{"title":"Skewer","description":"Thread the chicken pieces onto skewers. I usually do 10 to 12, with 3 to 4 pieces on each. (You could also skewer then leave skewered for marinating time, do it whichever way suits!)","images":[],"step":4},{"title":"Stove cook","description":"Heat a large non stick pan on medium high with enough oil to lightly coat the base. Cook the skewers in batches for 3 minutes on each side, controlling the heat as needed so the spices don''t burn. Transfer onto a plate, loosely cover with foil to keep warm. Wipe black bits out of the pan using a paper towel, add more oil and continue cooking.","duration":3,"images":[],"step":5},{"title":"BBQ option","description":"Brush the grills or flat plate lightly with oil. Heat on medium (or medium high, if your BBQ is not that strong). Cook skewers for 3 - 4 minutes on each side, adjusting the heat as needed so the spices don''t burn.","duration":3.5,"images":[],"step":6},{"description":"Serve the skewers with flatbreads or pita pockets, shredded lettuce, tomato and onion slices with sauce of choice (see ingredients section for options). Or make plates with a side of seasoned rice (see options above), a fresh Greek Salad and sauce of choice.","images":[],"step":7}]', '["mustard"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Aussie","Western"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","grilling-ideas-and-recipes","mains"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4592bdfe7ef9', 'en', 'US', 'Lamb Souvlaki', 'Recipe video above. The bold garlic-oregano Greek marinade works wonders to tenderise and infuse incredible flavour into the lamb! The flavour when this is cooking is out of this world. Eat them straight off the skewer while still hot or bundle up into warm pita bread with fixings.', 'https://www.recipetineats.com/tachyon/2023/11/Lamb-souvlaki_7.jpg', 20, 10, 30, 12, '[{"id": "ing_lamb", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_skewers", "quantity": {"value": 8.0, "unit": "pack of 50"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_lemon", "quantity": {"value": 0.15, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.15, "unit": "net of 500g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_vinegar", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_batch_tzatziki", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.15, "unit": "net of 500g"}}]', '[{"ingredients":["1.2 kg/ 2.4 lb boneless lamb leg (, fat trimmed, cut into 2.5cm/1” cubes (~900g / 1.8lb after trimming) (Note 1))","1 tsp cooking / kosher salt","1/2 tsp black pepper","1 tbsp extra virgin olive oil","8 - 12 skewers (, wooden or bamboo)"]},{"ingredients":["5 garlic cloves (, finely minced)","5 tbsp lemon juice","2 tsp lemon zest","2 tsp dried oregano","3 fresh bay leaves (, crushed in hand (or 2 dried kept whole))","1/3 cup white wine vinegar","3 tbsp extra virgin olive oil","1 tsp cooking / kosher salt"],"purpose":"Lamb souvlaki marinade:"},{"ingredients":["4 - 6 pita bread","1 batch Tzatziki","Greek salad ((chop small for stuffing) or shredded lettuce and tomato slices)","Greek lemon rice (to make plates instead of wraps)"],"purpose":"To serve – stuffed or make plates:"}]', '[{"description":"Mix marinade ingredients in a bowl. Add lamb and toss to coat.","images":[],"step":1},{"title":"Marinate in fridge for 12","description":"24 hours.","images":[],"step":2},{"description":"Skewer & cook:","images":[],"step":3},{"title":"Skewer","description":"Remove meat from marinade and thread 3 to 4 pieces on each to make 12 skewers, or 5 to make 8 larger skewers (pictured in post).","images":[],"step":4},{"description":"Sprinkle the meat with the salt and pepper. (This really makes a difference to the finished dish, better than just in the marinade).","images":[],"step":5},{"title":"Cook","description":"Heat 1 tbsp olive oil in a large non-stick pan over high heat. Cook half the skewers for 3 minutes, turn then cook the other side for 3 minutes until nicely seared (target internal temp 60°C/140°F for medium rare, optimum juiciness).","duration":3,"images":[],"step":6},{"description":"Transfer to a plate and loosely cover with foil to keep warm while you cook the remaining skewers.","images":[],"step":7},{"description":"BBQ cooking (Note 2):","images":[],"step":8},{"title":"Soak skewers","description":"Soak wood/bamboo skewers in water for 30 minutes if planning to cook on the BBQ (prevents burning). My skewers are 18cm/7” which fit in a pan (stove cooking).","duration":30,"images":[],"step":9},{"description":"Preheat BBQ to medium high. Flat iron hot plate is safer for wooden skewers (so they don''t catch fire) else use metal skewers on the grill side.","images":[],"step":10},{"title":"Skewer, oil & season","description":"Skewer per above. Drizzle with the oil (so it doesn''t stick to the BBQ) then sprinkle both sides with the salt and pepper.","images":[],"step":11},{"description":"BBQ cook for 3 minutes on each side.","duration":3,"images":[],"step":12},{"description":"Serve:","images":[],"step":13},{"description":"Pile Souvlaki onto a serving platter for DIY wraps with tzatziki (from this recipe), toasted pita bread and Greek salad (chopped small), or shredded lettuce and tomato slices. Else, make plates with lemon rice and a Greek Salad!","images":[],"step":14}]', '["gluten"]', '["keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Greek"],"categories":["greek-recipes","grilling-ideas-and-recipes","lamb","lamb-recipes","mains","mediterranean-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_122983ed27af', 'en', 'US', 'Vietnamese Lemongrass Pork steaks (tenderised!)', 'Recipe video above. Pork infused with a Vietnamese lemongrass marinade, then cooked over high heat for an authentic char-grill like you get at Vietnamese street stalls! Economical pork shoulder is a tough cut of meat that''s tenderised using a touch of baking soda. Even if you overcook these pork steaks, they are still tender inside!Use to make the popular Vietnamese rice noodle salad, Bún thịt nướng, or serve with coconut or jasmine rice and Asian slaw for a lovely dinner.', 'https://www.recipetineats.com/tachyon/2023/04/Vietnamese-noodles-lemongrass-pork-1.jpg', 15, 6, 21, 4, '[{"id": "ing_pork_shoulder", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_lemongrass", "quantity": {"value": 40.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_lime", "quantity": {"value": 0.12, "unit": "net of 500g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.019, "unit": "tub of 200g"}}]', '[{"ingredients":["500g/1 lb pork shoulder (, skinless and boneless, or pork scotch (roast or steaks) (Note 1))","3 tbsp canola oil"]},{"ingredients":["2 lemongrass stalks (, white part only, bruised, cut into 1 cm / 0.4\" slices on angle (Note 2))","4 garlic cloves (, finely minced)","4 tbsp lime juice","3 tbsp fish sauce","1 tbsp soy sauce (all purpose or light, NOT dark soy, Note 3)","4 tbsp brown sugar (tightly packed tablespoons)","3 tbsp oil (canola, vegetable, peanut)","3/4 tsp baking soda/bi-carb (, for tenderising (Note 4))"],"purpose":"Marinade:"}]', '[{"title":"Cut pork","description":"Cut into 8 equal, thinnish slices of pork. I find it easiest using the knife on a 45° angle, but if you have the right shape piece you can just cut straight down.","images":[],"step":1},{"description":"Pound each steak to 5mm / 0.2\" thickness using the scary side of a meat mallet (jagged, not flat), using go-between (Note 5) or a freezer bag to avoid damaging the meat. (You can use baking paper for rolling pin or the flat side of the mallet.)","images":[],"step":2},{"title":"Marinade","description":"Mix the marinade ingredients in a bowl, it will fizz when the baking soda is added! Add pork then toss well to coat using tongs. Transfer to a ziplock bag and marinate for 24 hours.","images":[],"step":3},{"description":"Remove pork from the marinade and brush off the lemongrass pieces. Discard marinade - it''s done its job!","images":[],"step":4},{"title":"Cook","description":"Heat a cast iron skillet over high heat until you see wisps of smoke. Add 1 1/2 tbsp oil, then cook half the pork for 1 1/2 minutes on one side and 1 minute on the other side until nicely charred. Remove onto a plate. Scrape pan clean of loose black bits then cook the remaining pork.","images":[],"step":5},{"description":"Serve! Make Pork Noodle Bowls (bun thit nuong) or serve with rice and a side salad - see note 6 and in post for suggestions!","images":[],"step":6},{"title":"NOTE","description":"The thin pork steaks are beyond well done in 2 1/2 minutes but it doesn''t matter because the baking soda keeps them tender. It will be blushing pink inside due to the baking soda (same happens with beef). You could cook them for another 5 minutes and they will still be tender inside. Miracle!","images":[],"step":7}]', '["fish","gluten","peanuts","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Vietnamese"],"categories":["grilling-ideas-and-recipes","mains","pork","pork-recipes","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2cbbce58a9c1', 'en', 'US', 'Marinated Vegetarian Pasta Salad', 'Recipe video above! How do you make the best ever vegetable pasta salad? MARINATE the veggies. Roast or BBQ any veg you want, then toss in a marinade so they absorb the flavour while hot before mixing through pasta. This is a big, fat JUICY flavour loaded pasta salad that lasts for days and days - see PRO TIP for keeping pasta salads juicy!', 'https://www.recipetineats.com/tachyon/2019/07/Marinated-Vegetable-Pasta-Salad_6.jpg', 15, 30, 75, 8, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.8, "unit": "pack of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_feta_cheese", "quantity": {"value": 120.0, "unit": "block of 200g"}}, {"id": "ing_capsicum", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_zucchini", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_asparagus", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_lemon", "quantity": {"value": 0.1, "unit": "net of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.5, "unit": "pack of 100g"}}]', '[{"ingredients":["400g / 14oz curly pasta (, dried (or other of choice))","1/4 cup parsley (, roughly chopped (or chives))","120g / 4oz feta (, crumbled into big chunks)"]},{"ingredients":["2 capsicum/bell peppers ((1 red, 1 yellow), cut into 2.5cm / 1\" pieces)","1 red onion (, cut into wedges)","1 eggplant (, halved lengthwise, then 1.25cm/ 0.5\" thick semi circles)","2 zucchini (, cut into 1.5cm / 2/3\" chunks (see video))","200g/ 7oz button mushrooms (, halved (large ones quartered))","1 bunch asparagus (, ends trimmed, cut into 5cm/2\" lengths)"],"purpose":"Vegetables (Note 1):"},{"ingredients":["1/4 cup (65ml) extra virgin olive oil","1 tsp each salt and pepper","3 cloves garlic (, minced)"],"purpose":"Roasting:"},{"ingredients":["1/3 cup (85ml) lemon juice","1/3 cup (85ml) extra virgin olive oil","2 tsp white sugar","2 garlic cloves (, minced)","1/2 tsp each salt and pepper","1/2 tsp each dried basil, parsley, oregano, thyme (Note 2)","1/2 - 1 tsp chilli flakes (adjust spice to taste, Note 3)"],"purpose":"Marinade / Dressing:"}]', '[{"description":"Marinade/Dressing:","images":[],"step":1},{"description":"Place ingredients in a jar and shake well. Set aside 10 minutes+.","images":[],"step":2},{"description":"Roasted Vegetables:","images":[],"step":3},{"title":"Preheat oven to 250°C/480°F (230°F fan)","description":"super high heat replicates BBQ charred edges.","images":[],"step":4},{"title":"Toss veggies in oil","description":"Place all vegetables other than asparagus in a large bowl. Drizzle with oil, sprinkle with salt, pepper and garlic, toss.","images":[],"step":5},{"description":"Spread vegetables on 2 trays (fill one less than the other). Roast 25 minutes, tossing once.","images":[],"step":6},{"title":"Add asparagus","description":"Drizzle asparagus with oil and pinch of salt and pepper. Add into oven for last 5 minutes.","images":[],"step":7},{"title":"BBQ Option","description":"See Marinated BBQ Vegetables for directions.","images":[],"step":8},{"title":"Marinate veggies","description":"Transfer vegetables into large bowl, pour over 1/2 the Dressing. Toss, then leave to marinate for 30 minutes to 3 hours.","duration":30,"images":[],"step":9},{"title":"Cook pasta + 2 minutes","description":"In large pot of salted water, cook pasta per packet directions but ADD 2 minutes to the cook time (Note 5 for why). Drain and return pasta into pot.","images":[],"step":10},{"description":"Add vegetables, including veg juices, into the pasta pot. Add remaining Dressing and parsley, then toss. Set aside for 15 minutes to cool slightly.","duration":15,"images":[],"step":11},{"title":"Serve! Sprinkle with feta and serve! Keeps 4","description":"5 days, serve at room temp.","images":[],"step":12},{"description":"Make ahead PRO TIP (Note 4):","images":[],"step":13},{"description":"SCOOP OUT a mug of pasta cooking water just before draining. Add 3 tbsp water to reserved Dressing (after marinating veg), shake well. Use this Dressing per above, but reserve 3 tbsp to freshen up pasta salad on Day 2 onwards.","images":[],"step":14},{"title":"Freshen up pasta salad","description":"Bring to room temp or briefly microwave (cold pasta = dry) to warm gently. Toss with Reserved Dressing then serve.","images":[],"step":15}]', '["gluten"]', '["vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["grilling-ideas-and-recipes","pasta-recipes","pasta-salads-and-rice-salads","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9f489d640e96', 'en', 'US', 'Slow cooked Beef Ribs with barbecue sauce (beef short ribs)', 'Recipe video above. Beef ribs slow braised in a silky, shiny homemade barbecue sauce until the meat is fall apart and ridiculously juicy inside, and the outside is bronzed and sticky. Also known as beef short ribs, this is one of the best cuts for slow cooking, far superior to beef chuck because there''s more marbling. Beef chuck always has some dry patches!100% perfect for make ahead and freezing.', 'https://www.recipetineats.com/tachyon/2020/09/Beef-Short-Ribs.jpg', 15, 240, 255, 6, '[{"id": "ing_beef_steak", "quantity": {"value": 6.0, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.019, "unit": "jar of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.25, "unit": "bottle of 500ml"}}, {"id": "ing_ketchup", "quantity": {"value": 0.45, "unit": "bottle of 500g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["6 x 300 - 350g / 10 - 12 oz beef ribs ((aka beef short ribs) (Note 1), patted dry)"]},{"ingredients":["1 tbsp brown sugar (sub white)","2 tsp paprika","1 tsp garlic powder (sub 1 tsp fresh garlic)","1 tsp onion powder (sub garlic powder)","1/2 tsp cumin powder","3/4 tsp mustard powder (Note 2)","1 tsp cooking salt / kosher salt (reduce by 25% for table salt, increase 50% for salt flakes)","1/2 tsp black pepper"],"purpose":"RUB:"},{"ingredients":["2 garlic cloves (, minced (sub 2 tsp powder))","1/2 cup apple cider vinegar (Note 2 subs)","1 1/2 cups ketchup (, or Aussie tomato sauce)","1/2 cup brown sugar (, loosely packed (ie don''t pack it tight)(sub white))","2 tsp EACH black pepper, onion powder, mustard powder (Note 2)","1 tsp cayenne pepper (adjust to taste re: spiciness)","1 tbsp Worcestershire sauce (sub soy sauce)","2 cups water"],"purpose":"Barbecue SAUCE:"},{"ingredients":["Parsley or chives (, chopped)"],"purpose":"Optional garnish:"}]', '[{"description":"Coat ribs in rub, mix sauce except water in pan, then add water. Bake ribs in sauce covered 3.5 hrs at 160°C/320°F, turn, then 30 min uncovered. Serve!","images":[],"step":1},{"description":"Preheat oven to 160°C/320°F (both fan & standard).","images":[],"step":2},{"title":"Rub","description":"Mix Rub in a small bowl large, enough to fit one rib. Press beef ribs into the rub, coating all sides. Shake off excess.","images":[],"step":3},{"title":"BBQ Sauce","description":"Mix Barbecue Sauce ingredients, except water, in a baking pan. Then mix in water.","images":[],"step":4},{"title":"Coat","description":"Place ribs in sauce, turning to coat. Arrange meat side down in the sauce, bone side exposed (sauce won''t cover completely, that''s ok).","images":[],"step":5},{"title":"Bake 3.5 hours","description":"Cover tightly with foil or lid, bake 3 1/2 hours. Remove from oven, remove foil. Turn ribs (some may have fall over, that''s ok, just turn them). Spoon over sauce.","images":[],"step":6},{"title":"Bake 30 min","description":"Bake 30 minutes uncovered, spooning over sauce again halfway through, until surface is caramelised and sticky. Check to ensure ribs are tender - pry a bit apart using two forks. (If not, cover and return to oven, but after 4 hrs they certainly should be!)","images":[],"step":7},{"title":"Serve","description":"Remove ribs onto serving plate (use a spoon as meat will barely be attached to bone, if at all). Mix sauce to bring together (Note 3 on adjustments). Serve with ribs! (See below for serving suggestions)","images":[],"step":8}]', '["gluten","mustard","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Southern","Western"],"categories":["beef","beef-recipes","grilling-ideas-and-recipes","mains","slow-cooked-fall-apart","slow-cooker-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d3952a77e07a', 'en', 'US', 'Spanish Paella', 'Recipe video above. The most famous Spanish dish of them all! Paella is meant to be a fun relaxed dish, so don''t get hung up about having the exact same seafood I''ve used - see Notes. And don''t be scared of making paella - it is actually very forgiving if you have the right liquid/rice ratios and follow the order in which I cook things!Note on Chorizo - NOT in traditional Spanish Paella recipes however, it''s widely used in Spanish restaurants outside of Spain. Australia would faint if I excluded it. So it''s in!', 'https://www.recipetineats.com/tachyon/2016/08/Paella-8.jpg', 15, 30, 45, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_chorizo", "quantity": {"value": 0.198, "unit": "kg"}}, {"id": "ing_squid", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_rice", "quantity": {"value": 225.0, "unit": "pack"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_saffron_threads", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_shrimp", "quantity": {"value": 12.0, "unit": "kg"}}, {"id": "ing_2_lbs_mussels", "quantity": {"value": 12.0, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 4.0, "unit": "net of 500g"}}]', '[{"ingredients":["1 - 2 tbsp olive oil","7 oz / 200g chorizo (2 pieces) (, sliced 1/2 cm / 1/5\" thick (Note 1))","200g / 6 oz squid (calamari) (, cut into 7mm / 1/4\" thick rings (Note 2))","1 onion (, diced (brown, white, yellow))","3 garlic cloves (, minced)","1 red capsicum / bell pepper (, diced)","1 1/2 cups paella rice (\"Bomba\", \"Valencia\" or \"Calasparra\" rice) (Note 3)","2 juicy ripe tomatoes, peeled and diced (OR 3/4 cup canned crushed tomato (Note 4))","300g / 10 oz chicken thigh fillets (, cut into 1.5\" / 3.5cm pieces)","3 1/2 cups chicken broth/stock (not low sodium) ( or homemade seafood broth (Note 5))","1 tsp saffron threads (or 1/4 tsp ground saffron, Note 6)","1 cup frozen peas","12- 16 medium / large prawns (, whole (shell on) (Note 7))","12 large mussels (, cleaned & check freshness (Note 8))"]},{"ingredients":["Fresh parsley (, chopped)","2 Lemons (, cut into wedges)"],"purpose":"Garnish"}]', '[{"title":"Chorizo","description":"Heat 1 tbsp oil in a 30cm / 10\" paella pan or large skillet over high heat (Note 9). Add chorizo and cook until browned on each side (~ 3 minutes). Remove with a slotted spoon and set aside.","images":[],"step":1},{"title":"Squid","description":"Add squid and cook for 45 seconds on each side, then remove and set aside.","duration":0.75,"images":[],"step":2},{"title":"Garlic, onion, capsicum","description":"Add remaining oil (if needed). Add garlic and onion, cook for 2 minutes. Add capsicum, cook for 1 minute.","duration":2,"images":[],"step":3},{"title":"Chicken","description":"Add chicken. Cook for 2 minutes until lightly browned but still raw inside.","duration":2,"images":[],"step":4},{"title":"Add Rice","description":"Add rice and mix until the grains are coated in oil.","images":[],"step":5},{"title":"Cooking broth","description":"Add in most of the chorizo (reserve 1/4 for garnish), chicken stock, fresh or crushed tomato and saffron. Stir.","images":[],"step":6},{"title":"Simmer 1","description":"Bring it to a simmer then adjust heat so it''s simmering fairly gently (not super rapidly, will burn rice). Simmer for 10 minutes - no stirring! At this stage, a bit of rice should be poking through to the surface but there should still be plenty of liquid.","duration":10,"images":[],"step":7},{"title":"Add peas, prawns and mussels","description":"Scatter over peas, squidge the prawns and mussels into the rice (partial submerge is fine).","images":[],"step":8},{"title":"Simmer 2","description":"Cook for 8 minutes (turn prawns halfway if you think it''s necessary) or until prawns are opaque, mussels are open, and most of the liquid has been absorbed but still a bit liquidy. Discard any mussels that do not open. Remove from stove.","duration":8,"images":[],"step":9},{"title":"Check rice","description":"Do a taste test to see if the rice is cooked - it should be firm but cooked. If it is too firm for your taste, no stress, just add a splash of hot water (not too much!) and keep cooking.","images":[],"step":10},{"title":"Rest","description":"Scatter over squid and reserved chorizo (residual heat will warm through), cover with lid then rest for 5 minutes (rice will absorb remainig liquid). Paella rice should now be tender but \"juicy\", not stodgy and thick (if it is, add splash of water to loosen it).","duration":5,"images":[],"step":11},{"title":"Garnish","description":"scatter with parsley and wedges of lemon. Take to table as is, then mix up rice with seafood before serving!","images":[],"step":12}]', '["shellfish"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Spanish"],"categories":["chicken-recipes","dietary","gluten-free-recipes","grilling-ideas-and-recipes","iconic-dishes","mediterranean-recipes","prawns-shrimp","quick-and-easy","seafood-recipes","spanish-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e36e6d0302c9', 'en', 'US', 'Huli Huli Chicken (Tropical Hawaiian chicken)', 'Recipe video above. There''s just no chance you make this without doing a little hula dance… swish those hips!!! Traditional Hawaiian recipe with in-your-face tropical flavours. Sweet, savoury, very sticky! Best 24 - 48 hr marinade, but you can get away with 3 hrs but baste extra generously.IMPORTANT: Do not use pureed fresh pineapple or fresh, pure pineapple juice from the fridge - it will over tenderise chicken, see Note 2. Use any pineapple juice sold in the aisles, not fridge - can, bottle or vac packed.', 'https://www.recipetineats.com/tachyon/2020/07/Hawaiian-Huli-Huli-Chicken_1.jpg', 10, 12, 22, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_pineapple", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_ginger", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 7.5, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.5, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.125, "unit": "bottle of 500ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_sriracha", "quantity": {"value": 0.037, "unit": "bottle of 400ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_pineapple", "quantity": {"value": 0.75, "unit": "unit"}}]', '[{"ingredients":["1.5 kg / 3 lb chicken thighs (or breast, Note 1)","1 tbsp vegetable oil"]},{"ingredients":["3/4 cup pineapple juice, canned or bottled (NOT FRESH!) (, unsweetened (Note 2))","1 1/2 tbsp ginger (, freshly grated (Note 3))","1 1/2 tbsp garlic (, freshly grated (Note 3))","1/2 cup tomato ketchup (or Aussie tomato sauce)","1/2 cup soy sauce","1/4 cup sherry or Chinese cooking wine (Note 4)","1/4 cup brown sugar","1 tbsp Sriracha","2 tbsp rice vinegar (or cider vinegar)","1 tbsp sesame oil (, toasted)"],"purpose":"Marinade:"},{"ingredients":["Sliced green onion","Pineapple slices (, grilled for 3 minutes on each side for lines)"],"purpose":"Garnishes, optional:"}]', '[{"description":"Mix marinade, set aside 3/4 cup (185 ml) for basting.","images":[],"step":1},{"description":"Pour the rest over the chicken in a glass or ceramic container (not metal or plastic), coat chicken then marinade 24 - 48 hours.","images":[],"step":2},{"description":"Cooking:","images":[],"step":3},{"description":"Brush BBQ grills with oil then preheat to medium high, or heat oil in a skillet over medium high heat.","images":[],"step":4},{"description":"Drain excess marinade from chicken, place on BBQ/skillet.","images":[],"step":5},{"title":"Cook the first side for 2","description":"3 minutes until golden (adjust heat if browning too fast), then flip and cook for 2 minutes.","duration":2.5,"images":[],"step":6},{"description":"Baste (dab) generously with reserved marinade, then flip and cook for 1 minute.","duration":1,"images":[],"step":7},{"description":"Repeat this every minute or so for a total cook time of 10 minutes, or until internal temp in the thickest part registers 75°C/167°F (for thigh) or 65°C / 150°F (for breast).","images":[],"step":8},{"description":"Transfer chicken to a plate, loosely cover with foil and rest for 3 minutes before serving, garnished with green onion if desired.","duration":3,"images":[],"step":9}]', '["gluten","sesame","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Hawaiian","Tropical!"],"categories":["chicken-breast-recipes","chicken-recipes","grilling-ideas-and-recipes","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9bc75da5bbef', 'en', 'US', 'Honey Soy Chicken - Marinade and Sauce (excellent grilled!)', 'Recipe video above. This is my premium recipe for Honey Soy chicken, a step up from this quick Honey Garlic Chicken and easy Baked Honey Soy Chicken, neither of which call for marinating. One mixture is used as a marinade, for basting, and also to make a fabulous glossy sauce to drizzle over the chicken and everything on your plate. It''s especially good for grilling! (More BBQ recipes here) Pictured with Pineapple Fried Rice.Other chicken cuts - For wings, use the Honey Soy Wings recipe. For drumsticks and bone-in thighs, use the Honey Soy Baked Chicken recipe.', 'https://www.recipetineats.com/tachyon/2020/06/Honey-Soy-Chicken_4.jpg', 10, 20, 30, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.25, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.5, "unit": "bottle of 250ml"}}, {"id": "ing_honey", "quantity": {"value": 0.333, "unit": "jar of 500g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.125, "unit": "bottle of 500ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.03, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 7.5, "unit": "pack of 3 heads"}}, {"id": "ing_water", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.019, "unit": "pack of 400g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1.25 - 1.5 kg/ 2.5 - 3 lb skinless boneless chicken thighs OR breast (Note 1)","1 tbsp vegetable oil (, for cooking)"]},{"ingredients":["1/2 cup soy sauce (, all purpose or light (not dark, Note 2))","2/3 cup honey (sub maple syrup)","1/3 cup cider vinegar (or rice vinegar)","1/4 cup Chinese cooking wine or dry sherry (key ingredient, Note 3)","1 tbsp sesame oil (, toasted (Note 4))","1 1/2 tbsp garlic (, finely minced)"],"purpose":"Honey Soy Marinade Sauce:"},{"ingredients":["1/3 cup water","1 1/2 tsp cornflour/cornstarch"],"purpose":"Serving Sauce:"},{"ingredients":["Green onion (, finely sliced)","Sesame seeds"],"purpose":"Garnishes (optional):"}]', '[{"description":"Marinade Sauce:","images":[],"step":1},{"description":"Place ingredients in a jug and mix well until honey is completely dissolved.","images":[],"step":2},{"description":"Reserve 1/4 cup for Basting, refrigerate. (Note 5)","images":[],"step":3},{"description":"Reserve 2/3 cup for Serving Sauce, refrigerate.","images":[],"step":4},{"title":"Marinade Chicken","description":"Pour remaining marinade over chicken in a container. Coat chicken thoroughly. Cover, refrigerate 24 to 48 hours (minimum 3 hrs).","images":[],"step":5},{"description":"Serving Sauce (Makes 1 cup):","images":[],"step":6},{"description":"Place reserved sauce in a small saucepan. Mix cornflour and water, then add into saucepan.","images":[],"step":7},{"description":"Simmer over medium for 5 minutes, stirring regularly, until it thickens to a syrupy consistency. Set aside and keep warm. (If it gets too thick, just add a bit more water)","duration":5,"images":[],"step":8},{"description":"Cook:","images":[],"step":9},{"description":"Brush BBQ plate or grills with oil and heat to medium high. Or heat oil in a large skillet over medium high heat.","images":[],"step":10},{"title":"THIGHS","description":"Place chicken on BBQ. Cook the first side for 2 minutes, then flip and dab with reserved Basting Sauce. Cook for 2 minutes, flip and baste. Then flip/baste every 1 minute for total cook time of ~ 10 minutes or until a thermometer reads 75°C/165°F.","duration":2,"images":[],"step":11},{"title":"BREAST","description":"Cook first side 2 minutes, flip, baste. Cook 2 minutes, then flip and baste every 45 sec or so for total cook time of ~8 minutes (internal temp 66°C / 151°F).","images":[],"step":12},{"title":"REST","description":"Transfer to serving plate, cover loosely with foil and rest for 5 minutes.","duration":5,"images":[],"step":13},{"description":"SERVE chicken garnished with sesame seeds and green onion, with sauce on the side so people can help themselves.","images":[],"step":14}]', '["gluten","sesame","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian-esque","Western"],"categories":["chicken-breast-recipes","chicken-recipes","grilling-ideas-and-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_946d7108572e', 'en', 'US', 'Sticky Grilled Chicken', 'Recipe video above. Sticky, savoury and sweet, this is the marinade I use for grilled chicken that I know is a guaranteed hit with everyone, kids and adults! It tastes like a country-style rub, and it''s finger licking'' good.', 'https://www.recipetineats.com/tachyon/2019/07/Sticky-Grilled-Chicken_7.jpg', 10, 10, 1460, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_ketchup", "quantity": {"value": 0.15, "unit": "bottle of 500g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.25, "unit": "bottle of 250ml"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.06, "unit": "bottle of 500ml"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 20.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}]', '[{"ingredients":["700g/ 1.4lb chicken thighs (, skinless boneless (Note 1))"]},{"ingredients":["1/2 cup ketchup","1/3 cup brown sugar (, packed)","1/4 cup soy sauce (, all purpose or light (NOT dark))","2 tbsp apple cider vinegar","2 tbsp olive oil","4 tsp Worcestershire Sauce","4 garlic cloves (, minced)"],"purpose":"Marinade / Glaze (Note 2 for subs):"}]', '[{"description":"Mix Marinade in a large bowl.","images":[],"step":1},{"description":"Scoop out 1/2 cup and reserve for basting (\"Glaze\").","images":[],"step":2},{"description":"Add chicken, turn to coat. Marinade overnight (minimum 3 hours, up to 48 hours, or freeze).","images":[],"step":3},{"description":"Brush BBQ with vegetable or canola oil, then preheat to medium.","images":[],"step":4},{"description":"Pick up chicken, allowing excess Marinade to drip off.","images":[],"step":5},{"description":"Place on BBQ, cook 4 minutes until nicely caramelised.","images":[],"step":6},{"description":"Turn chicken, then brush generously with Glaze. Cook 4 minutes.","images":[],"step":7},{"description":"Flip, brush with more Glaze, flip again and brush with Glaze.","images":[],"step":8},{"description":"Remove chicken onto plate, cover loosely with foil.","images":[],"step":9},{"description":"Rest 3 minutes before serving, sprinkled with parsley if using. Pictured in post with Macaroni Salad!","images":[],"step":10},{"title":"Stove","description":"follow up steps in a non stick pan, heated to medium high with 1 tbsp oil (cook in batches if needed).","images":[],"step":11},{"title":"Oven","description":"use this recipe: Sticky Baked Chicken","images":[],"step":12}]', '["gluten","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-recipes","grilling-ideas-and-recipes","main-dishes","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b0e8d796cad9', 'en', 'US', 'Beef Steak Marinade', 'Recipe video above. This is a marinade to transform good value steaks by making them juicier, more tender and adding a hint of flavour while not overpowering the flavour of the beef. With this marinade, you won''t need a sauce for the beef, though I can never resist some garlic butter!', 'https://www.recipetineats.com/tachyon/2016/07/Steak-Marinade_4.jpg', 5, 5, 730, 2, '[{"id": "ing_beef_steak", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.833, "unit": "pack of 3 heads"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_balsamic_vinegar", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["2 steaks (, economical (Note 1))"]},{"ingredients":["1 tsp Dijon mustard","1/2 tsp minced garlic (1 large garlic clove)","1/2 tsp onion powder (or sub with garlic powder)","1 tbsp soy sauce (Note 2)","1 tbsp oil (I use olive oil, but any oil is fine)","1 tbsp Worcestershire sauce","1 tbsp balsamic vinegar","Black pepper"],"purpose":"Marinade"}]', '[{"description":"Mix together mustard, garlic and onion powder. Then mix in remaining ingredients.","images":[],"step":1},{"description":"Place beef in a ziplock bag with Marinade and marinade overnight (12 - 24 hours).","images":[],"step":2},{"description":"Remove from the fridge 30 minutes before cooking to bring to room temperature - key for even cooking of steaks. Shake off excess marinade.","images":[],"step":3},{"description":"Brush BBQ Grills with oil, then heat on high heat until is really hot - you should see wisps of smoke. Or heat a heavy based skillet on high until very hot, then add oil - it will heat almost instantly.","images":[],"step":4},{"description":"Add steaks. For 2cm / 3/4\" thick steaks, cook the first side for 2 minutes, then turn and cook the other side for 2 minutes (medium rare 52°C/125°F, chart below for other doneness temps). (Note 3)","duration":2,"images":[],"step":5},{"description":"Remove from skillet onto a WARM plate, cover loosely with foil and set aside for 5 minutes.","duration":5,"images":[],"step":6},{"title":"Serve! I couldn''t resist garlic butter","description":"see recipe in notes.","images":[],"step":7}]', '["gluten","mustard","soy"]', '["high_protein","keto_friendly","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef-recipes","dietary","gluten-free-recipes","grilling-ideas-and-recipes","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a2cffd800f15', 'en', 'US', 'Fish Tacos', 'Recipe video above. Fish marinated in classic Mexican fresh flavours, seared until golden, are perfect for tacos. The lightly pickled red cabbage is a perfect accompanied for the soft fish, a great texture contrast. A wonderful recipe for white fish fillets, you will NOT miss deep fried fish!', 'https://www.recipetineats.com/tachyon/2016/05/Fish-Tacos_4-1.jpg', 15, 10, 45, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.544, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_lime", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_chipotle", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_jalapeno", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_red_cabbage", "quantity": {"value": 12.0, "unit": "head"}}, {"id": "ing_green_onion", "quantity": {"value": 0.06, "unit": "bunch"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.45, "unit": "tub of 250g"}}, {"id": "ing_sriracha", "quantity": {"value": 2.0, "unit": "bottle of 400ml"}}, {"id": "ing_tortillas", "quantity": {"value": 12.0, "unit": "pack of 8"}}, {"id": "ing_lime", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}]', '[{"ingredients":["1.2 lb / 600g firm white fish fillets (Note 1)","Zest of 1 lime","3 tbsp lime juice","1 tbsp chipotle powder (Note 2)","1 tbsp canned jalapeno (, finely chopped)","1/4 cup cilantro / coriander (, finely chopped)","2 garlic cloves (, minced)","3 tbsp olive oil","Salt and pepper"],"purpose":"Fish Marinade"},{"ingredients":["4 cups red cabbage (, finely shredded)","3 green onion stems (, finely sliced on the diagonal)","2 tbsp red wine vinegar (or white wine vinegar, cider vinegar)","1/2 tsp salt"],"purpose":"Quick Pickled cabbage"},{"ingredients":["3/4 cup sour cream (or yogurt)","2 - 3 tbsp sriracha (, adjust to taste (Note 3))"],"purpose":"Pink Taco Sauce"},{"ingredients":["1 tbsp olive oil","12 small tortillas ((corn or flour), warmed)","lime wedges","coriander/cilantro leaves"],"purpose":"To Cook & Serve"}]', '[{"title":"Marinade fish","description":"Combine Fish Marinade ingredients in a ziplock bag. Set aside for 20 minutes to marinate - no longer than 1 hour.","duration":20,"images":[],"step":1},{"title":"Pickled Cabbage","description":"Place Pickled Cabbage ingredients in a bowl. Toss to combine and set aside for 30 minutes. Drain excess liquid, scrunch cabbage with your hands (to help soften). Set aside.","duration":30,"images":[],"step":2},{"title":"Pink Sauce","description":"Mix to combine.","images":[],"step":3},{"title":"Cook fish","description":"Heat oil in a skillet over high heat. Cook fish for 2 minutes on each side, or until golden and cooked.","duration":2,"images":[],"step":4},{"description":"Remove fish onto plate then flake into large pieces.","images":[],"step":5},{"description":"To assemble tacos, top with cabbage then fish, a dollop of sour cream and a squeeze of lime juice. Fold tortilla over and enjoy!","images":[],"step":6}]', '["fish","gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["dietary","fish-recipes","gluten-free-recipes","grilling-ideas-and-recipes","low-calorie-recipes","mexican-recipes","most-popular","quick-and-easy","seafood-recipes","taco-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_38731e98ea9b', 'en', 'US', 'Avocado Chicken Burgers', 'Recipe video above. Ground chicken burgers can be so bland and boring. Not these! Parmesan, garlic and a hint of dried sage adds great savoury flavour, and you’ll love how these cook up beautifully golden with crispy edges!', 'https://www.recipetineats.com/tachyon/2019/08/Avocado-Chicken-Burgers_9.jpg', 15, 10, 25, 4, '[{"id": "ing_chicken", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_parmesan", "quantity": {"value": 0.375, "unit": "pack of 200g"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_sage", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_lettuce", "quantity": {"value": 1.2, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.003, "unit": "jar of 400g"}}, {"id": "ing_french_fries", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}]', '[{"ingredients":["500g/ 1.2 lb ground chicken (mince) (Note 1)","1 cup panko breadcrumbs","1 egg","3/4 cup parmesan (, finely grated (Note 2))","1 cup green onion (, finely sliced (~2 stems))","2 garlic cloves (, minced)","1/2 tsp dried sage (Note 3)","1/2 tsp salt and pepper (, each)"],"purpose":"Chicken Burger Patties:"},{"ingredients":["2 tbsp olive oil","4 soft burger buns or brioche buns","1 avocado (big!) (or 2 medium)","60g / 2 oz rocket / arugula or other lettuce of choice","2 tomatoes (, sliced)","4 slices Swiss cheese (or other cheese)","Mayonnaise, relish, ketchup or tomato sauce (to smear lid)"],"purpose":"Burgers:"},{"ingredients":["French fries","Baked potato wedges"],"purpose":"On the side"}]', '[{"description":"Chicken Burger Patties","images":[],"step":1},{"description":"Place Pattie ingredients in bowl, mix well with hands.","images":[],"step":2},{"description":"Form 4 patties, 1.5cm / 3/5\" thick, slightly larger than the buns (shrinks slightly). If mixture is super sticky (Note 4), either refrigerate mixture for 30 minutes, or wet hands or lightly spray hands with oil (I do this).","duration":30,"images":[],"step":3},{"description":"Heat oil in skillet over medium high heat. Add patties, working in batches. Cook for 2 minutes or until deep golden, then flip.","duration":2,"images":[],"step":4},{"description":"After 1 minute, top with a piece of cheese and place lid on to melt cheese.","images":[],"step":5},{"description":"Once cheese is melted, remove patties from skillet.","images":[],"step":6},{"description":"Split buns and lightly toast in oven or under broiler/grill.","images":[],"step":7},{"description":"Cut avocado in half, scoop out a generous amount then \"smash\" it on the base of the bun with a fork. Sprinkle with salt and pepper.","images":[],"step":8},{"description":"Top with Chicken Pattie, then rocket/arugula and tomato.","images":[],"step":9},{"description":"Smear the top bun with mayonnaise (or relish, ketchup, other condiment of choice) and place lid on bun.","images":[],"step":10},{"description":"Devour and be happy!","images":[],"step":11}]', '["egg","milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["burger-recipes","chicken-mince-recipes","chicken-recipes","dinner-tonight","grilling-ideas-and-recipes","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8e1a22cf6ea9', 'en', 'US', 'Chimichurri Steak', 'Recipe video above. An essential part of Argentinian cuisine, Chimichurri Sauce is steadily growing in popularly throughout the rest of the world - with good reason! It''s fresh, zingy with a bit of a bite, and pairs so perfectly with a simple grilled steak. It''s also fantastic with fish, chicken and pork!', 'https://www.recipetineats.com/tachyon/2016/08/Steak-with-Chimichurri-Sauce_1.jpg', 5, 10, 15, 4, '[{"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_beef_steak", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1 cup parsley leaves (, tightly packed)","1 tbsp oregano leaves (, tightly packed (still lovely without))","4 garlic cloves (, minced)","0 - 2 tsp red pepper flakes (optional - adjust to taste)","1/4 cup (65 ml) red wine vinegar (Note 1)","1/2 tsp salt","Black pepper","1/2 cup (125 ml) extra virgin olive oil"],"purpose":"Chimichurri Sauce"},{"ingredients":["700g / 1.4lb flat iron, flank, skirt steak (or other steak of choice, at room temperature (Note 3))","Salt and pepper"],"purpose":"Steak"}]', '[{"description":"Chimichurri Sauce","images":[],"step":1},{"description":"Place all ingredients except oil in a food processor. Whizz until parsley is finely chopped, but not pureed - see video or photos. Alternatively chop parsley by hand.","images":[],"step":2},{"description":"Transfer into a small bowl. Add oil, gently stir. Set aside for 1 hour before use, overnight is even better!","images":[],"step":3},{"description":"Store in an airtight container in the refrigerator and use within 3 days (Note 3). Makes 3/4 cup.","images":[],"step":4},{"description":"Take steak out of the fridge 30 minutes prior to cooking.","images":[],"step":5},{"description":"Heat BBQ or heavy based skillet with 1 tbsp vegetable or canola oil over high heat until smoking.","images":[],"step":6},{"description":"Sprinkle each side of steak generously with salt and pepper.","images":[],"step":7},{"description":"Add steak and cook to your liking.","images":[],"step":8},{"title":"Cook times","description":"for steak 2cm / 4/5” thick, 2 min on each side for medium rare (until internal temp is 52C/125F, will rise to 54C/130F after resting) OR 2 1/2 min each side for medium (internal temp 57C/135F, will rise to 60C/140F).","images":[],"step":9},{"description":"Transfer to a plate, cover loosely with foil and rest for 5 - 10 minutes.","duration":7.5,"images":[],"step":10},{"description":"Cut thin slices against the grain (see photo below) and serve with Chimichurri Sauce on the side so people can help themselves.","images":[],"step":11}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Argentinian"],"categories":["beef-recipes","dietary","dinner-tonight","gluten-free-recipes","grilling-ideas-and-recipes","main-dishes","quick-and-easy","roast-beef","south-american-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f02244be45ca', 'en', 'US', 'A great Chicken Marinade (great grilled or pan seared!)', 'Recipe video above. This is a great everyday Chicken Marinade, one you make with things you''ve already got with plenty of sub options (see notes). It will make any cut of chicken extra juicy, infuse it with savoury flavour that''s a touch of sweet, with a hint of herby goodness. Especially good for chicken breast, and terrific for grilling!', 'https://www.recipetineats.com/tachyon/2019/06/Grilled-Chicken-Marinades-Cover-Graphic.jpg', 5, 10, 15, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.3, "unit": "bottle of 250ml"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}]', '[{"ingredients":["700g / 1.4 lb chicken breast, tenderloins or thigh (Note 1)"]},{"ingredients":["2 tbsp honey OR brown sugar","1 tbsp olive oil (or any oil)","5 tbsp soy sauce","2 tbsp lemon juice","2 tsp Worcestershire sauce","4 garlic cloves (, minced)","1 tsp dried oregano (or rosemary, thyme, minced herbs)","1/2 tsp black pepper (, ground)"],"purpose":"Chicken marinade (subs Note 3):"},{"ingredients":["Finely chopped parsley","Lemon slices"],"purpose":"Garnishes (optional)"}]', '[{"title":"Recommended","description":"Pound breast to even thickness using a meat pounder, rolling pin, or fist. OR cut large ones in half horizontally to form 2 cutlets (steaks) for each.","images":[],"step":1},{"description":"Mix marinade in a ziplock bag (or container in which chicken fits snugly). Add chicken.","images":[],"step":2},{"description":"Marinate 3 hours to overnight, though even 30 minutes is effective. (Note 2)","images":[],"step":3},{"description":"Heat 1 tbsp olive oil in a large skillet over medium high heat, and cook chicken per times below until deep golden (see video). If browning too quickly, lower heat.","images":[],"step":4},{"description":"Transfer to serving plate, cover loosely with foil and rest for 3 minutes before serving, garnished with parsley and lemon slices if desired.","duration":3,"images":[],"step":5},{"description":"Cook times:","images":[],"step":6},{"title":"Whole breast and boneless thighs: 3","description":"4 minutes each side (internal temp 165F/75C)","images":[],"step":7},{"title":"Cutlets and tenderloin","description":"2 minutes each side","images":[],"step":8}]', '["gluten","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","grilling-ideas-and-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4077e7717b6c', 'en', 'US', 'Grilled Garlic Bread', 'Recipe video above. Here''s how to make garlic bread on the BBQ! A simple method that ensures loads of garlicky buttery goodness, lightly charred bread and no flare up disasters that will scorch your bread into unrecognisable lumps of coal!', 'https://www.recipetineats.com/tachyon/2019/06/Grilled-Garlic-Bread_4.jpg', 5, 10, 15, 6, '[{"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_butter", "quantity": {"value": 125.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["1 bread loaf (, fairly flat (rather than a tall loaf, Note 1))","125 g / 1 stick salted butter (or unsalted + 3/4 tsp salt)","3 garlic cloves (, very finely chopped (do not use crusher or jar, Note 2))","1 tbsp finely chopped parsley (, optional)"]}]', '[{"description":"Preheat BBQ to medium high.","images":[],"step":1},{"description":"Melt butter in a small saucepan over medium high heat.","images":[],"step":2},{"description":"Add garlic and salt, stir until garlic is LIGHT golden and salt is dissolved.","images":[],"step":3},{"description":"Immediately remove from heat, set aside for for few minutes to let garlic infuse into butter.","images":[],"step":4},{"description":"Split the bread in half lengthwise. Or use thick individual slices of bread.","images":[],"step":5},{"description":"Spoon just over half the butter onto the cut face of the bread, avoiding the garlic bits. Brush a bit of butter on the other side.","images":[],"step":6},{"title":"Place bread cut face down and cook for 3","description":"5 minutes or until you have crusty edges, then flip.","duration":4,"images":[],"step":7},{"description":"Brush away any burnt garlic bits, then baste on the remaining garlic butter. Garlic bits are mainly for flavour infusion but feel free to put them on too, great texture!","images":[],"step":8},{"description":"Once underside is crusty (3 min or so), remove, sprinkle with parsley, cut and serve!","images":[],"step":9}]', '["gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["breads","grilling-ideas-and-recipes","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d7ea4ab4ac20', 'en', 'US', 'Crispy Grilled Shrimp (Prawns) with Lemon Butter Sauce', 'Recipe video above. Seasoned and CRISPY on the outside, juicy on the inside, drizzled with a simple-yet-incredible lemon butter sauce, you''ll love the little crispy little golden garlic bits in the sauce! This is a recipe made for the BBQ, but works great on the stove too (Note 4).', 'https://www.recipetineats.com/tachyon/2019/06/Crispy-Grilled-Shrimp-Lemon-Butter-Sauce_2.jpg', 5, 10, 15, 4, '[{"id": "ing_butter", "quantity": {"value": 90.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_lemon", "quantity": {"value": 0.045, "unit": "net of 500g"}}, {"id": "ing_shrimp", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 0.045, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.045, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["90g / 6 tbsp butter (, unsalted)","1/4 tsp salt","3 tsp garlic (, very finely chopped (do not use mincer, Note 1))","1.5 tbsp lemon juice (, plus more to taste)"],"purpose":"Lemon Garlic Butter:"},{"ingredients":["500g/ 1 lb large shrimp / prawns (, raw, peeled and deveined (Note 2))","1 tsp garlic powder","1 tsp smoked paprika (plain or sweet ok too)","1/4 tsp cayenne pepper","1 tbsp lemon juice (skip if using stove)","2 tbsp olive oil","1/2 tsp salt","1/4 tsp pepper"],"purpose":"Shrimp/Prawns:"},{"ingredients":["1 lemon (, halved, grilled if desired)","Lemon wedges or slices","2 tbsp finely chopped parsley"],"purpose":"Serving (optional):"}]', '[{"description":"Brush BBQ grills with oil, then preheat on high until very hot.","images":[],"step":1},{"description":"If shrimp are small and might fall through grills, skewer them (use 2 skewers, Note 3)","images":[],"step":2},{"description":"Melt butter in a small saucepan over medium high heat.","images":[],"step":3},{"description":"Add garlic and salt. Stir until garlic is LIGHT golden brown, then immediately remove from stove (residual heat will make garlic golden & crispy).","images":[],"step":4},{"description":"Stir through lemon.","images":[],"step":5},{"title":"Shrimp/Prawns (Stove","description":"Note 4):","images":[],"step":6},{"description":"Pat shrimp dry with paper towels (to ensure crispiness!)","images":[],"step":7},{"description":"Just prior to cooking, place in bowl, sprinkle/drizzle over remaining ingredients. Toss gently to coat.","images":[],"step":8},{"description":"Working quickly, place shrimp on BBQ and cook each side for 2 minutes until golden and crusty.","duration":2,"images":[],"step":9},{"description":"Immediately remove shrimp onto serving plate.","images":[],"step":10},{"description":"Drizzle over all the Lemon Garlic Butter, sprinkle with parsley and serve immediately with fresh lemon.","images":[],"step":11},{"description":"Crusty bread to mop up the crazy delish butter on the plate is essential!","images":[],"step":12}]', '["milk","shellfish"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["grilling-ideas-and-recipes","prawns-shrimp","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6764a38a414b', 'en', 'US', 'Marinated Grilled Salmon', 'Recipe VIDEO above. Make your next grilled salmon AMAZING with a simple yet incredible Salmon Marinade that will infuse the salmon with extra flavour! It''s savoury with a touch of sweet and hint of garlic, and does double duty as a sauce for serving!', 'https://www.recipetineats.com/tachyon/2019/06/Marinated-Grilled-Salmon_8.jpg', 5, 12, 17, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.333, "unit": "bottle of 250ml"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_honey", "quantity": {"value": 0.09, "unit": "jar of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}]', '[{"ingredients":["4 salmon fillets (, skin on best (150-180g/5-6oz each, Note 1))","Olive oil (, for cooking)"]},{"ingredients":["1/3 cup (85 ml) soy sauce (, low sodium)","2 tbsp lemon juice","3 tbsp honey","2 tbsp olive oil","2 garlic cloves (, minced)"],"purpose":"Marinade (Sauce)- Note 2:"},{"ingredients":["Parsley, chives or green onion (, finely chopped)","Lemon slices"],"purpose":"Serving (optional)"}]', '[{"description":"Place marinade in a ziplock bag and mix to combine.","images":[],"step":1},{"title":"Add salmon and massage to coat. Marinate for 3","description":"24 hours (1 hr minimum).","images":[],"step":2},{"description":"Take out of fridge 30 minutes prior to cooking.","images":[],"step":3},{"description":"Remove salmon onto plate, allowing excess marinade to drain off.","images":[],"step":4},{"description":"Sauce (basting + serving):","images":[],"step":5},{"description":"Pour remaining marinade into a small saucepan and simmer over medium high for 3 to 5 minutes until syrupy.","duration":4,"images":[],"step":6},{"description":"Pour into bowl/jug (some used for basting, some for serving).","images":[],"step":7},{"description":"Brush BBQ grills with oil. Then preheat to medium (or medium low for strong BBQ''s).","images":[],"step":8},{"description":"Drizzle salmon with oil, the place onto the BBQ flesh side down (skin side up).","images":[],"step":9},{"description":"Cook for 3 minutes or until golden, then use tongs to carefully turn.","duration":3,"images":[],"step":10},{"description":"Brush the flesh with Sauce, then close BBQ lid.","images":[],"step":11},{"title":"Cook for 3","description":"4 minutes, basting one more time halfway through, or until the internal temperature is 50C/120F(medium rare) or 55C/130F (medium).","duration":3.5,"images":[],"step":12},{"description":"Transfer salmon to plate and serve with remaining Sauce.","images":[],"step":13}]', '["fish","gluten","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","fish-recipes","grilling-ideas-and-recipes","quick-and-easy","salmon-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9ccf041ee881', 'en', 'US', 'A great Chicken Marinade (great grilled or pan seared!)', 'Recipe video above. This is a great everyday Chicken Marinade, one you make with things you''ve already got with plenty of sub options (see notes). It will make any cut of chicken extra juicy, infuse it with savoury flavour that''s a touch of sweet, with a hint of herby goodness. Especially good for chicken breast, and terrific for grilling!', 'https://www.recipetineats.com/tachyon/2019/05/Chicken-Marinade_8-1.jpg', 5, 10, 15, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.3, "unit": "bottle of 250ml"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}]', '[{"ingredients":["700g / 1.4 lb chicken breast, tenderloins or thigh (Note 1)"]},{"ingredients":["2 tbsp honey OR brown sugar","1 tbsp olive oil (or any oil)","5 tbsp soy sauce","2 tbsp lemon juice","2 tsp Worcestershire sauce","4 garlic cloves (, minced)","1 tsp dried oregano (or rosemary, thyme, minced herbs)","1/2 tsp black pepper (, ground)"],"purpose":"Chicken marinade (subs Note 3):"},{"ingredients":["Finely chopped parsley","Lemon slices"],"purpose":"Garnishes (optional)"}]', '[{"title":"Recommended","description":"Pound breast to even thickness using a meat pounder, rolling pin, or fist. OR cut large ones in half horizontally to form 2 cutlets (steaks) for each.","images":[],"step":1},{"description":"Mix marinade in a ziplock bag (or container in which chicken fits snugly). Add chicken.","images":[],"step":2},{"description":"Marinate 3 hours to overnight, though even 30 minutes is effective. (Note 2)","images":[],"step":3},{"description":"Heat 1 tbsp olive oil in a large skillet over medium high heat, and cook chicken per times below until deep golden (see video). If browning too quickly, lower heat.","images":[],"step":4},{"description":"Transfer to serving plate, cover loosely with foil and rest for 3 minutes before serving, garnished with parsley and lemon slices if desired.","duration":3,"images":[],"step":5},{"description":"Cook times:","images":[],"step":6},{"title":"Whole breast and boneless thighs: 3","description":"4 minutes each side (internal temp 165F/75C)","images":[],"step":7},{"title":"Cutlets and tenderloin","description":"2 minutes each side","images":[],"step":8}]', '["gluten","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","grilling-ideas-and-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3f1261d41111', 'en', 'US', 'Baked Tandoori Chicken', 'Recipe video above. Tandoori chicken - baked in the oven! For everyone who doesn''t have a tandoor sitting in the middle of their kitchen. :) The flavour infusion and the lovely crust from the marinade is sensational. Easy sub for Kashmiri Chilli, the only ingredient that is not sold at supermarkets.', 'https://www.recipetineats.com/tachyon/2015/09/Tandoori-Chicken__2.jpg', 10, 40, 50, 5, '[{"id": "ing_yogurt", "quantity": {"value": 0.45, "unit": "tub of 500g"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 0.045, "unit": "net of 500g"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_garam_masala_spice_mix", "quantity": {"value": 15.0, "unit": "jar"}}, {"id": "ing_chilli", "quantity": {"value": 0.225, "unit": "pack of 100g"}}, {"id": "ing_turmeric", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.25, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.225, "unit": "pack of 100g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_mint", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1 1/2 cups plain yoghurt (full fat best)","2 tbsp oil (any)","1 1/2 tbsp lemon juice","2 tsp ginger (, grated)","5 garlic cloves (, minced)","3 tsp garam masala spice mix (Note 1)","1.5 tbsp kashmiri chilli powder (Note 2 subs)","1 tsp turmeric powder","2 tsp cumin","2 1/2 tsp coriander powder","1/2 tsp chilli powder, adjust to taste (pure, not US chili Note 3)","1 tsp salt"],"purpose":"Tandoori Marinade:"},{"ingredients":["1.2kg / 2.4lb drumsticks, bone-in skin on chicken thighs or Marylands (whole chicken legs) (Note 4)","Oil spray"],"purpose":"Chicken:"},{"ingredients":["1 cup plain yoghurt","1/2 cup mint leaves, packed","Salt and pepper","Olive oil"],"purpose":"Mint Yoghurt (optional)"},{"ingredients":["Basmati rice (OR Saffron rice (see note))"],"purpose":"Serving"}]', '[{"description":"Mix Marinade ingredients in a large bowl. Add chicken, cover and marinate 12 to 24 hours (Note 5)","images":[],"step":1},{"description":"Preheat oven to 180C/350F. Line a tray with foil and place a rack on the tray.","images":[],"step":2},{"description":"Remove chicken from the Marinade, shaking off excess (reserve Marinade), and place on the rack. Bake for 20 minutes, then slather Marinade generously on both sides.","duration":20,"images":[],"step":3},{"description":"Bake for a further 10 minutes, brush/dab top with Marinade.","images":[],"step":4},{"description":"Bake further 10 minutes, do a final baste with Marinade then spray with oil.","images":[],"step":5},{"description":"Increase heat to 220C/450F. Bake for a further 10 to 15 minutes until you get some nice charred spots. Serve with Minted Yogurt and Saffron Rice (below) or plain Basmati Rice.","images":[],"step":6},{"description":"Minted Yoghurt:","images":[],"step":7},{"description":"Combine ingredients in a food processor and blitz until mint is very finely chopped.","images":[],"step":8},{"description":"Preheat BBQ with closed lid to medium, brush grills lightly with oil. Place bone-in skin-on chicken skin side down on grills, cook 5 min until surface is just caramelised - no more.","images":[],"step":9},{"description":"Baste, then flip. Baste, then close lid. Cook for 20 minutes or until internal temperature is 175F/80C (bone in thighs and drumsticks), basting once or twice more.","duration":20,"images":[],"step":10}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["main_course"],"cuisine":["Indian","Nepalese"],"categories":["chicken-drumstick-recipes","chicken-recipes","curry-recipes","dietary","gluten-free-recipes","grilling-ideas-and-recipes","iconic-dishes","indian-recipes","main-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9e9bc63f23ec', 'en', 'US', 'A Great Pork Chop Marinade', 'Recipe video above. This marinade will make any pork chops or steak extra juicy as well as infusing it with great savoury flavour and a touch of sweet. Soy sauce is the secret ingredient - it does not taste the least bit "Asiany" or soy saucey. MINIMUM MARINADE TIME: 1 hr+ for thin chops, 3 hrs+ for thick.', 'https://www.recipetineats.com/tachyon/2017/08/Marinated-Pork-Chops-3A.jpg', 5, 10, 15, 4, '[{"id": "ing_pork", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.333, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["4 bone in pork chops, 2 cm / 4/5\" thick about 280g/9 oz each (Note 1)","1 tbsp oil"]},{"ingredients":["1/3 cup (85 ml) soy sauce (light or all purpose, not dark)","2 tbsp brown sugar","2 tsp Worcestershire sauce","1 tsp Dijon mustard","2 garlic cloves (, minced)","¼ tsp black pepper"],"purpose":"Marinade:"}]', '[{"description":"Place Marinade ingredients in a ziplock bag. Massage to combine.","images":[],"step":1},{"description":"Add chops. Massage to coat in the Marinade. Marinate for 1 – 24 hours. (Note 2)","images":[],"step":2},{"description":"Take the chops out of the fridge 20 minutes before cooking.","images":[],"step":3},{"description":"Brush BBQ grill or drizzle oil in pan, heat on medium high. Add pork and cook for 4 minutes or until the underside is caramelised and the pork releases from the grill, then turn the chops and cook for 3 minutes (Note 2 for thin chops).","duration":4,"images":[],"step":4},{"description":"Baste both sides with residual marinade in ziplock bag, then cook the basted side for 30 seconds before serving. The chops should have a great crust","duration":0.5,"images":[],"step":5},{"description":"Transfer chops to a plate, cover loosely with foil. Rest for 3 minutes before serving.","duration":3,"images":[],"step":6}]', '["gluten","mustard","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dinner-tonight","grilling-ideas-and-recipes","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2b021325e6d0', 'en', 'US', 'Bun Cha - Vietnamese Meatballs', 'Recipe video above. Everything you know and love about Vietnamese food - fresh, healthy and full of flavour! Bun Cha in Vietnam is served slightly differently (read in post), but here I''ve made noodle bowls which are more familiar to those outside of Vietnam. See Notes for what this tastes like!', 'https://www.recipetineats.com/tachyon/2019/01/Vietnamese-Pork-Meatballs_6.jpg', 20, 10, 30, 2, '[{"id": "ing_pork_mince", "quantity": {"value": 250.0, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_lemongrass", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_oil", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_water", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.2, "unit": "pack of 500g"}}, {"id": "ing_big_handful_beansprouts", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["250 - 300 g/8 - 10 oz pork mince (ground pork)(Note 1)","1 tbsp fish sauce (Note 2)","2 tsp white sugar","1/3 cup finely chopped green onions / scallions","1 clove garlic (, minced)","Pinch of white pepper and salt","2 tsp lemongrass paste or fresh finely chopped (, optional (Note 4))","1 1/2 tbsp oil (, for cooking)"],"purpose":"Meatballs:"},{"ingredients":["3 tbsp white sugar","3 tbsp fish sauce (Note 2)","2 tbsp rice wine vinegar","2 tbsp lime juice","1/3 cup water","1 birds eye chilli (, seeded and finely chopped (Note 3))","3 cloves garlic (, finely chopped)"],"purpose":"Nuoc Cham (Vietnamese Dressing / Sauce – Note 2):"},{"ingredients":["100 g / 3.5 oz vermicelli noodles (, dried)","Big handful beansprouts","Few lettuce leaves (, folded or shredded)","Julienned carrot and white radish (daikon), optional quick pickle (Note 5)","Handful of coriander/cilantro sprigs (, mint)","Sliced red chilli (, lime wedges (optional))"],"purpose":"Serving (Note 4):"}]', '[{"title":"Sauce","description":"Mix ingredients. Set aside 10 minutes+.","images":[],"step":1},{"title":"Noodles","description":"Pour over boiling water and soak per packet directions. Drain, set aside.","images":[],"step":2},{"description":"Mix all ingredients except oil until combined.","images":[],"step":3},{"description":"Shape into 6 mini hamburger patties with your hands.","images":[],"step":4},{"description":"Heat oil in a skillet over medium high heat. Add patties and cook for 2 1/2 minutes or until golden. Flip, cook 2 minutes then remove.","images":[],"step":5},{"description":"Assemble Bowls:","images":[],"step":6},{"description":"Place noodles in bowl. Top with a handful of beansprouts, wedge in lettuce, carrots and radish in.","images":[],"step":7},{"description":"Place meatballs on top, top with coriander and mint.","images":[],"step":8},{"description":"Spoon over a generous amount of Sauce (it''s supposed to be like a soup broth), eat and be happy!","images":[],"step":9}]', '["fish"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Vietnamese"],"categories":["dinner-tonight","grilling-ideas-and-recipes","iconic-dishes","meatball-recipes","pork-recipes","quick-and-easy","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_eea72dc7c5d1', 'en', 'US', 'Lemon Garlic Marinated Grilled Pork Chops', 'Recipe VIDEO above. Nothing infuses pork chops with flavour like a good marinade! This one is ideal for grilling so the high heat sears the crust beautifully. But the pork chops can of course be cooked on the stove, or even bake them! Also use this marinade for the proteins - see notes.', 'https://www.recipetineats.com/tachyon/2018/01/Lemon-Garlic-Oregano-Pork-Chops-3.jpg', 5, 10, 15, 4, '[{"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.1, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.1, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_pork", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 37.5, "unit": "bottle"}}]', '[{"ingredients":["3 garlic cloves (, minced)","1 tbsp dried oregano (or other herbs, Note 1)","Zest of 1 lemon","1/3 cup (85 ml) lemon juice (1 large or 2 medium lemons)","1/4 cup (65 ml) olive oil","3/4 tsp salt","1/4 tsp black pepper"],"purpose":"Marinade:"},{"ingredients":["4 pork chops bone in (, 2cm / 4/5\" thick about 280g/9 oz each (Note 2))","Oil (, for cooking)"],"purpose":"Pork:"}]', '[{"description":"Whisk Marinade ingredients in a bowl (or ziplock bag). Add pork. Marinade for 1 hr minimum, 3 hours ideal, 12 hours max (Note 3).","duration":60,"images":[],"step":1},{"description":"Take the pork out of the fridge 20 minutes before cooking.","images":[],"step":2},{"description":"Shake excess marinade off (but don''t wipe dry) and cook using preferred method. Pictured in post served with Minted Yoghurt - see notes!","images":[],"step":3},{"description":"Brush grills / plate with oil and heat on high until smoking.","images":[],"step":4},{"description":"Place pork on grills and cook the first side for 4 minutes until it is nicely charred. Turn and cook the other side for 3 minutes. Turn the porks on their side to briefly sear the fat side (see video). Transfer to plate, rest for 3 - 5 minutes then serve.","duration":4,"images":[],"step":5},{"description":"Heat skillet with about 1 tbsp oil over high heat. Add pork and cook for 1 minute, then turn DOWN slightly to medium high. Cook for another 3 minutes, then turn and cook the other side for 3 minutes. Turn the porks on their side to briefly sear the fat side (see video).","duration":1,"images":[],"step":6},{"title":"Transfer to plate, rest for 3","description":"5 minutes then serve.","duration":4,"images":[],"step":7},{"description":"Preheat oven to 200C / 390F (fan forced / convection) or 220C / 430F (standard oven).","images":[],"step":8},{"description":"Place oven shelf in top 1/3 of oven.","images":[],"step":9},{"description":"Place pork on tray. Bake for 15 minutes, then flick to grill/broiler and grill on high for 5 minutes until the surface is nicely browned.","duration":15,"images":[],"step":10},{"title":"Transfer to plate, rest for 3","description":"5 minutes then serve.","duration":4,"images":[],"step":11}]', '[]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dietary","dinner-tonight","gluten-free-recipes","greek-recipes","grilling-ideas-and-recipes","main-dishes","mediterranean-recipes","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_15bee2208c90', 'en', 'US', 'Chicken Burger Recipe', 'Recipe video above. Crispy seasoned chicken breast, topped with a mandatory slice of melted cheese and piled onto soft rolls with onion, avocado, lettuce, tomato and garlic mayo. The key to juicy chicken is to cook it hard and fast! You can eyeball the Seasoning - it will be tasty as long as you use "around" the right amounts. :)Want to the chicken mince version? Here''s it is!', 'https://www.recipetineats.com/tachyon/2017/07/Chicken-Burgers-4.jpg', 15, 10, 25, 4, '[{"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_paprika", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 2000.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken_breast", "quantity": {"value": 400.0, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.003, "unit": "jar of 400g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_french_fries", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}]', '[{"ingredients":["1/3 cup /80g flour (any white)","1 tsp salt","½ tsp black pepper","¾ tsp paprika","1 tsp thyme","½ tsp garlic powder","½ tsp onion powder"],"purpose":"Seasoning:"},{"ingredients":["2 tbsp olive oil","2 large onions (, halved them sliced (white, brown or yellow))","400 - 500g / 14 oz - 1 lb chicken breast (2 pieces) (, cut in half horizontally into 2 thin steaks)","4 – 8 slices Swiss or other melting cheese slices (Note 1)","4 soft rolls (I used brioche burger buns)","1 avocado","Lettuce","2 large tomatoes"],"purpose":"Burgers:"},{"ingredients":["½ cup mayonnaise (I use whole egg)","1 large garlic clove (, minced)"],"purpose":"Garlic Mayo:"},{"ingredients":["French fries","Baked potato wedges"],"purpose":"On the side"}]', '[{"description":"Mix Garlic Mayo ingredients in a small bowl, set aside for 20+ minutes.","images":[],"step":1},{"description":"Mix Seasoning in a flat bowl / dish.","images":[],"step":2},{"description":"If required, pound chicken to about 1 cm / 2/5” thick. If wanting to be exact, trim to shape of rolls BUT ensure it is about 15% larger (it shrinks) (Note 2).","images":[],"step":3},{"description":"Heat 1 tbsp oil in a skillet over high heat (if doing on BBQ, drizzle flat plate).","images":[],"step":4},{"description":"Add onion and cook, turning regularly, for 5 minutes until golden. Season with salt and pepper, toss, then remove.","duration":5,"images":[],"step":5},{"description":"While cooking the onions, preheat oven to 160C/320F. Split rolls, then lightly toast / warm the rolls (if using BBQ, just toast the cut side until crispy). Leave in turned off oven with door ajar while you cook chicken.","images":[],"step":6},{"description":"Heat 1 tbsp oil into the same skillet, still on high heat.","images":[],"step":7},{"description":"Dredge chicken in Seasoning, shake off excess, then place in skillet. Repeat.","images":[],"step":8},{"description":"Cook for 2 ½ minutes until golden, then flip.","images":[],"step":9},{"description":"Top with cheese then leave for 1 1/2 minutes. When the underside is golden, if the cheese is not yet melted, place lid on for 15 seconds (or tray or foil).","duration":0.25,"images":[],"step":10},{"description":"Remove chicken from skillet onto plate. Cover loosely with foil while you start assembling the burgers.","images":[],"step":11},{"description":"Smear base of roll with avocado, sprinkle with salt and pepper. Top with chicken, onion, lettuce then tomato.","images":[],"step":12},{"description":"Smear lid of roll with Garlic Mayo, place on burger. Enjoy!","images":[],"step":13}]', '["egg","gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["burger-recipes","chicken-breast-recipes","chicken-recipes","dinner-tonight","grilling-ideas-and-recipes","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5e23c18c020d', 'en', 'US', 'Creamy Garlic Prawns / Shrimp and Cheesy Potatoes Foil Packet Recipe', 'Recipe video above. Juicy, perfectly cooked prawns/shrimp bathed in a creamy garlic sauce piled on top of cheesy potatoes with a side of steamed asparagus, all cooked in a foil packet! Grill these on the BBQ, bake them in the oven or even cook these on the stove!', 'https://www.recipetineats.com/tachyon/2017/06/Creamy-Prawn-Cheesy-Potatoes-Foil-Pack_1.jpg', 10, 10, 20, 4, '[{"id": "ing_potato", "quantity": {"value": 600.0, "unit": "bag of 2kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_shrimp", "quantity": {"value": 20.0, "unit": "kg"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.75, "unit": "pack of 125g"}}, {"id": "ing_es_asparagus", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["600 g / 1.2 lb potatoes (, peeled and cut into 1.5cm cubes)","1 tsp dried thyme leaves (optional)","Salt and pepper","3/4 cup thickened / heavy cream","30 - 50 g / 2 - 3 tbsp butter (more = richer!)","1 garlic clove (, minced)","20 - 24 prawns/shrimp (, peeled and deveined, tail on or off)","3/4 - 1 cup mozzarella or other melting cheese of choice","2 - 3 bunches asparagus (, trimmed then cut in half, fat ones vertically cut in half (Note 1))","Finely chopped parsley"]}]', '[{"description":"Bring a large pot of water to the boil. Add potatoes and cook for 5 minutes or until just cooked.","duration":5,"images":[],"step":1},{"description":"Drain potatoes, then sprinkle with salt, pepper and thyme. Toss to coat.","images":[],"step":2},{"description":"Meanwhile, place the cream, butter and garlic in a heatproof bowl. Microwave 30 - 40 seconds on high, until butter melts when stirred. If time permits, cool (place in fridge to speed up). (Note 1)","images":[],"step":3},{"description":"Preheat oven to 200C/390F (standard) or 180C/350F (fan/convection) or BBQ on medium high with hood down.","images":[],"step":4},{"description":"Tear 4 x 45cm/18\" pieces of heavy duty foil (Note 2).","images":[],"step":5},{"description":"Divide potatoes among foil sheets. Top with cheese, then prawns and asparagus, then drizzle over cream sauce.","images":[],"step":6},{"description":"Sprinkle with salt, pepper and parsley.","images":[],"step":7},{"description":"Bring the long ends of the foil together over the prawns, then fold down to seal, then fold in the sides (watch video, it''s easy!)","images":[],"step":8},{"description":"Place on a baking tray or BBQ and cook for 10 minutes (small prawns) - 12 minutes (medium prawns). (Note 4)","duration":10,"images":[],"step":9},{"title":"Serve immediately","description":"do not leave them sitting around inside the unopened packet, the prawns and asparagus will overcook and leech water, making the sauce watery.","images":[],"step":10}]', '["milk","shellfish"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","grilling-ideas-and-recipes","main-dishes","one-pot-recipes","prawns-shrimp","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_49339ac0168c', 'en', 'US', 'Carne Asada', 'The famous Latin American grilled beef! Marinated in a wicked Carne Asada marinade that infuses and tenderises the beef, this is beautiful made with any cut of beef suitable for quick grilling but is traditionally made with flank and skirt steak. Use for tacos, burritos or serve on rice, or try a salad! This recipe serves 5 - 6, because it''s sliced thinly a bit goes a long way.', 'https://www.recipetineats.com/tachyon/2017/06/Carne-Asada-4.jpg', 10, 8, 18, 6, '[{"id": "ing_garlic", "quantity": {"value": 6.667, "unit": "pack of 3 heads"}}, {"id": "ing_oranges", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_ime_juice", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.25, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_jalapeno", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_1_2kg_1_5_2_5lb_skirt_of_flank", "quantity": {"value": 750.0, "unit": "unit"}}, {"id": "ing_tortillas", "quantity": {"value": 1.0, "unit": "pack of 8"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 0.075, "unit": "net of 500g"}}]', '[{"ingredients":["4 cloves garlic (, minced)","1/2 cup / 125 ml orange juice","1/4 cup / 65 ml lime juice (about 2 limes)","1 cup finely chopped coriander / cilantro","1/2 teaspoon salt","1/4 teaspoon black pepper","1/4 cup / 65 ml olive oil","1 jalapeno ((fresh), finely minced)","2 tbsp white vinegar (any clear or clear-ish vinegar will be ok here e.g. white wine vinegar, cider vinegar)"],"purpose":"Marinade:"},{"ingredients":["Oil","750 g - 1.2kg / 1.5 - 2.5lb skirt of flank (I used a 900g/1.8lb skirt) (Note 1)"],"purpose":"Cooking:"},{"ingredients":["Tortillas","Avocado Slices","Pico De Gallo or Tomato","Coriander/cilantro leaves","Lime wedges"],"purpose":"To Serve as Carne Asada Tacos:"}]', '[{"description":"Place the Marinade ingredients in a large ziplock bag and mix. Add beef and massage through the bag to coat evenly. Seal then marinate for 1- 8 hours (12 hours max, otherwise meat gets over marinated and can be mushy).","images":[],"step":1},{"title":"Take the skirt steak out of the fridge 20","description":"30 minutes before cooking to bring to room temperature.","images":[],"step":2},{"description":"Brush BBQ with oil and heat on high until smoking (or use a large skillet over high heat and turn the fan on!).","images":[],"step":3},{"description":"Cook skirt steak for 3 minutes each side for rare, 4 minutes for medium rare. For flank, cook for 4 minutes each side for rare and 5 minutes for medium rare. Don''t cook beyond medium - chewy beef!","duration":3,"images":[],"step":4},{"description":"Remove onto a plate and cover loosely with foil. Rest for 5 minutes then slice thinly against the grain (Note 2).","duration":5,"images":[],"step":5},{"description":"Serve with tacos, in burritos or on rice!","images":[],"step":6}]', '[]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["South American"],"categories":["beef-recipes","dietary","gluten-free-recipes","grilling-ideas-and-recipes","mexican-recipes","quick-and-easy","south-american-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_90eeed1c7626', 'en', 'US', 'Rosemary Garlic Grilled Lamb Chops', 'A tasty way to prepare economical cuts of lamb chops and steaks! Tenderise and infuse them with flavour with a delicious marinade then grill to perfection on the BBQ (or stove). Marinade for at least 2 hours, preferably overnight (no longer than 24 hours). Update: This is (was!) a tart marinade and following feedback from some readers by email and from a friend, I have tweaked the recipe slightly to take the edge off the vinegar. :) Resounding feedback all round!', 'https://www.recipetineats.com/tachyon/2016/12/Rosemary-Garlic-Marinated-Lamb-Chops-5.jpg', 5, 10, 15, 4, '[{"id": "ing_lamb", "quantity": {"value": 600.0, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_vinegar", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_honey", "quantity": {"value": 0.03, "unit": "jar of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_rosemary", "quantity": {"value": 0.125, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["600 - 800 g / 1.2 - 1.6lb lamb chops (4 - 8, depending on size)","Oil (, for cooking, if required)"]},{"ingredients":["2 1/2 tbsp red wine vinegar","1 tbsp extra virgin olive oil","1 tbsp honey","3 garlic cloves (, minced)","1 1/4 tsp finely chopped fresh rosemary (or 1 tsp dried rosemary)","1/2 tsp dried thyme","3/4 - 1 tsp sea salt","Black pepper"],"purpose":"Marinade"}]', '[{"description":"Mix Marinade ingredients in a bowl until salt dissolves. Add lamb, mix to coat, then marinate at least 2 hours, preferably overnight, up to 24 hours.","images":[],"step":1},{"description":"Brush BBQ bars with oil if required (Note 1) and heat to medium high (or heat 1/2 tbsp oil in skillet on stove on medium high).","images":[],"step":2},{"description":"Cook lamb to your taste. I had 4 x 150g/5oz lamb loin chops about 2cm/3/4\" thick and 3 minutes on each side = medium. I also cooked smashed garlic cloves and rosemary sprigs for garnish.","images":[],"step":3},{"description":"Transfer lamb to plate, cover loosely with foil and rest for 5 minutes.","duration":5,"images":[],"step":4},{"description":"Serve with sides of choice!","images":[],"step":5}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dietary","gluten-free-recipes","grilling-ideas-and-recipes","lamb-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_206b298a2d19', 'en', 'US', 'Chicken Souvlaki with Tzatziki', 'This Greek favourite is so easy to make at home! Loaded with classic Greek flavours of lemon, garlic and dried oregano. Fabulous for an outdoor BBQ!', 'https://www.recipetineats.com/tachyon/2016/07/Chicken-Souvlaki_1.jpg', 15, 10, 25, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.68, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.075, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.375, "unit": "tub of 500g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}]', '[{"ingredients":["1.5 lb / 750 g chicken thigh fillets ((or breast), cut into 1\"/2.5cm pieces)","2 tbsp olive oil","1/4 cup lemon juice","3 garlic cloves (, minced)","2 tbsp dried oregano","1/2 - 3/4 tsp salt","Black pepper"],"purpose":"Marinade"},{"ingredients":["1 tbsp olive oil","Flatbreads / wraps / pita bread","Lettuce","Tomato slices"],"purpose":"To Cook / Serve"},{"ingredients":["2 Lebanese cucumbers (to make about ½ cup grated cucumber after squeezing out juice)","1 1/4 cups / 300 g plain Greek yoghurt","2 tsp white wine vinegar (or red wine or apple cider vinegar)","1 tbsp lemon juice","1/2 garlic clove (, minced)","1 tbsp extra virgin olive oil (or more if you want richer)","1/2 tsp salt","Black pepper"],"purpose":"Tzatziki"}]', '[{"description":"Place chicken and Marinade into a bowl and set aside to marinate for at least 3 hours to overnight.","images":[],"step":1},{"description":"Thread chicken onto 8 skewers.","images":[],"step":2},{"description":"Heat oil in a large skillet over high heat (or BBQ). Cook skewers for 3 minutes on each side, or until cooked through.","duration":3,"images":[],"step":3},{"description":"Serve Chicken Souvlaki with tzatziki, flatbreads (make your own!), lettuce and tomato slices.","images":[],"step":4},{"description":"Cut the cucumber in half lengthwise. Use a teaspoon to scrape the watery seeds out. Coarsely grate the cucumber using a box grater. Then wrap in paper towels or a tea towel and squeeze to remove excess liquid.","images":[],"step":5},{"description":"Place cucumber in a bowl. Add remaining ingredients then mix to combine. Set aside for at least 20 minutes for the flavours to meld.","images":[],"step":6}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Greek"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","gluten-free-recipes","greek-recipes","grilling-ideas-and-recipes","mediterranean-recipes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3aca52194d76', 'en', 'US', 'Pineapple Coconut Hawaiian Chicken Skewers', 'This recipe is based on the marinade of the Hawaiian street food chicken you can get from roadside stalls throughout Hawaii, except I added coconut. Coconut is a brilliant base for marinades because it adds richness into the flesh as well as infusing it with sweetness and coconut flavours. I served this with a Coconut Lime Rice (it uses the balance of coconut milk leftover after this recipe from a standard 14oz/400g can). MARINATING TIME: 3 hrs - overnight recommended, but even 20 minutes is enough.', 'https://www.recipetineats.com/tachyon/2016/05/Coconut-Pineapple-Chicken-Skewers_4.jpg', 15, 10, 25, 8, '[{"id": "ing_coconut_milk", "quantity": {"value": 0.469, "unit": "can of 400ml"}}, {"id": "ing_pineapple", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_lime", "quantity": {"value": 0.225, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.5, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.68, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_skewers", "quantity": {"value": 8.0, "unit": "pack of 50"}}]', '[{"ingredients":["3/4 cup coconut milk (from a 14oz/400g can, use leftovers for Coconut Lime Rice!)","1/2 cup pineapple juice (Note 1)","3 tbsp brown sugar","2 tbsp tomato sauce/ketchup","3 tbsp soy sauce","Zest and juice of 1 lime","2 garlic cloves (, minced)","1/2 tsp EACH onion powder (, cumin, paprika,)","1 tsp ginger powder (or 1/2 tsp grated fresh ginger)","1/2 - 1 tsp cayenne pepper (, optional)","1/2 tsp salt"],"purpose":"Marinade"},{"ingredients":["1.5 lb / 750g chicken thigh fillets (, cut into 1\"/2.5cm pieces)","1 tbsp olive or vegetable oil","8 skewers (, soaked in water for 30 minutes if cooking on outdoor BBQ)"],"purpose":"Skewers"}]', '[{"description":"Combine Marinade ingredients in a bowl. Remove 1/2 cup of Marinade (for basting) and set aside in fridge. Add chicken, cover and marinate in the fridge for at least 3 hours, preferably overnight. But even 20 minutes is enough - compensate with extra basting.","images":[],"step":1},{"description":"Drain and discard marinade. Thread chicken onto skewers.","images":[],"step":2},{"description":"Heat oil in a large skillet or on outdoor BBQ over medium high heat. Cook skewers, turning to cook all sides, and basting generously with reserved Marinade. (Note 1)","images":[],"step":3},{"description":"Serve with Coconut Lime Rice.","images":[],"step":4}]', '["gluten","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Hawaiian"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","gluten-free-recipes","grilling-ideas-and-recipes","most-popular","quick-and-easy","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e454613f7927', 'en', 'US', 'Mexican Grilled Chicken Tacos', 'Wonderfully authentic Mexican flavours, a homestyle version of Sinaloa chicken, a popular Mexican street food. Adapted from Bobby Flay''s "Mexican Red Chicken" recipe from his cookbook "Bobby Flay''s Barbecue Addiction". (Note 1)', 'https://www.recipetineats.com/tachyon/2016/04/Mexican-Grilled-Chicken-Tacos_1.jpg', 5, 10, 15, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_oranges", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.06, "unit": "bottle of 500ml"}}, {"id": "ing_ime_juice", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_chipotle", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.016, "unit": "jar of 40g"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_tortillas", "quantity": {"value": 1.0, "unit": "pack of 8"}}, {"id": "ing_pico_de_gallo", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 0.045, "unit": "net of 500g"}}]', '[{"ingredients":["1 - 1.5 lb / 500 - 750g chicken thigh fillets (Note 2)","1 tbsp olive oil"]},{"ingredients":["4 tbsp orange juice","2 tbsp apple cider vinegar (or rice vinegar)","1 1/2 tbsp lime juice","3 garlic cloves (, minced)","1 1/2 tbsp chipotle or ancho chile powder (Note 3)","2 tsp dried oregano","2 tsp smoked paprika powder (Note 4)","1/8 tsp All Spice","1/4 tsp cinnamon powder","1/4 - 1/2 tsp cayenne pepper (optional - for spiciness)","1 tsp salt","Black pepper"],"purpose":"Marinade"},{"ingredients":["Tortillas or taco shells","Pico de Gallo (tomato salsa)","Sour cream","Avocado","Fresh coriander / cilantro","Lime wedges"],"purpose":"Taco Fixings"}]', '[{"description":"Place Marinade ingredients in a ziplock bag. Add chicken, massage to coat then refrigerate to marinate for at least 3 hours, preferably overnight.","images":[],"step":1},{"description":"Remove chicken from Marinade, discard Marinade.","images":[],"step":2},{"description":"Heat oil in a skillet over medium high heat (or even better, do this on the BBQ on medium high). Cook chicken for 4 minutes on each side, until dark golden brown.","duration":4,"images":[],"step":3},{"description":"Remove chicken onto plate, cover loosely with foil and rest for 3 minutes.","duration":3,"images":[],"step":4},{"description":"Cut into strips and use for tacos. (See Note 5 for more serving options)","images":[],"step":5}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","gluten-free-recipes","grilling-ideas-and-recipes","mexican-recipes","quick-and-easy","taco-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4a3c120e6ed8', 'en', 'US', 'Beef Steak Fajitas', 'Recipe video above. Beef Fajitas made extra juicy and extra tasty with a wicked marinade that tenderises and flavours the beef! But if you don''t have time to marinade, see Note 7 for a faster version. Adapted from this recipe by Tyler Florence (mine is easier and I think it is just as tasty!)', 'https://www.recipetineats.com/tachyon/2016/03/Beef-Fajitas_4.jpg', 15, 15, 30, 4, '[{"id": "ing_beef_steak", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_oranges", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_cumin", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_chipotle", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 2.0, "unit": "bottle"}}, {"id": "ing_capsicum", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 2.5, "unit": "pack of 1kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_tortillas", "quantity": {"value": 12.0, "unit": "pack of 8"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1 lb / 500g beef steak (rump and skirt are ideal) (Note 1)","4 tbsp / 1/4 cup orange juice (, fresh (1 orange))","2 tbsp lime juice","2 garlic cloves (, minced)","1/2 tsp cumin powder","1/2 tsp coriander powder","1/2 tsp onion powder (optional)","1 tsp chipotle powder (Note 2)","1/2 tsp salt","Black pepper"],"purpose":"Marinated Beef"},{"ingredients":["2 - 3 tbsp oil","2 bell peppers/capsicum (, sliced (Note 3))","1 large onion (, halved and sliced (brown, yellow, white))","Salt and pepper"],"purpose":"Fajitas"},{"ingredients":["12 tortillas (, small)","Avocado","Cilantro/coriander","Sour cream","Lime wedges","Tomatoes (, sliced, or Pico de gallo)"],"purpose":"Fixings"}]', '[{"description":"Place the Marinated Beef ingredients in a ziplock bag, massage to coat then refrigerate for 2 hour to overnight.","images":[],"step":1},{"description":"Remove beef from marinade 30 minutes prior to cooking (to bring to room temperature) and pat dry with paper towels. Discard marinade.","images":[],"step":2},{"description":"Drizzle 1/2 tbsp of oil on each side of the beef (1 tbsp in total).","images":[],"step":3},{"description":"Heat the BBQ or a skillet on high heat. Cook beef to your liking. (Note 4)","images":[],"step":4},{"description":"Remove beef onto a plate and cover loosely with foil.","images":[],"step":5},{"description":"Return skillet to stove, still on high heat, and heat 1/2 tbsp oil. Add onions, sprinkle with salt and pepper, and cook until soft and charred. Remove onto serving plate.","images":[],"step":6},{"description":"Heat remaining 1/2 tbsp oil in the skillet. Add bell pepper/capsicum, sprinkle with salt and pepper, and cook until charred. Remove onto plate.","images":[],"step":7},{"description":"Slice beef thinly against the grain (Note 5).","images":[],"step":8},{"description":"Serve with warmed tortillas and fixings of choice. (Note 6)","images":[],"step":9}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["beef-recipes","dietary","fajitas","gluten-free-recipes","grilling-ideas-and-recipes","low-calorie-recipes","mexican-recipes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1ee599ec9dd5', 'en', 'US', 'Turkish Lamb Kofta Kebabs', 'A simple, exotic, fragrant midweek meal. 30 minutes, start to finish. Adapted from a recipe by Effendi restaurant in Balmain, Sydney, as shown in the Food Safari "Fire" TV series. See notes for changes made to the original recipe.', 'https://www.recipetineats.com/tachyon/2016/02/Turkish-Kebabs-1_3.jpg', 20, 10, 30, 4, '[{"id": "ing_lamb_mince", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_pistachio_nuts", "quantity": {"value": 37.5, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_cumin", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_yogurt", "quantity": {"value": 0.225, "unit": "tub of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}]', '[{"ingredients":["1 lb / 500g lamb mince (ground lamb) (or substitute with beef)","1 small onion (, grated or minced using a food processor - about 1/4 cup (white, brown or yellow) (Note 1))","1 garlic clove (, minced)","1/4 cup pistachio nuts (, ground (Optional. I use my food processor) (Note 2))","3/4 tsp cooking salt / kosher salt (halve for table salt, +50% for salt flakes)","1 tsp black pepper","1 tbsp cumin powder","1 tbsp red pepper flakes","1 tbsp olive oil"],"purpose":"Kebabs"},{"ingredients":["3/4 cup plain yoghurt (I use Greek)","1 tbsp lemon juice","1/2 garlic clove (, minced)","Salt and pepper"],"purpose":"Yoghurt Sauce"},{"ingredients":["Pita bread or lebanese flat bread (, warmed)","Lettuce leaves of choice","Sliced tomato","Sliced red onion"],"purpose":"To Serve"}]', '[{"description":"Mix together Yoghurt Sauce ingredients and place in the refrigerator to allow the flavours to develop.","images":[],"step":1},{"description":"Place the Kebab ingredients except the oil in a bowl and use your hands to just combine (don''t over mix).","images":[],"step":2},{"description":"Divide into 8 portions and mould onto skewers.","images":[],"step":3},{"description":"Heat oil in a large skillet over medium high heat. Add skewers (I could fit all in, placing them in alternating directions) and cook for 8 minutes, turning to brown all sides.","duration":8,"images":[],"step":4},{"description":"Meanwhile, slice tomatoes and red onion.","images":[],"step":5},{"description":"Serve kebabs with pita bread, lettuce, tomatoes, red onion and yoghurt sauce on the side. Wedges of lemon are also a great accompaniment.","images":[],"step":6}]', '["gluten","milk","nuts"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Turkish"],"categories":["cuisines","dietary","dinner-tonight","gluten-free-recipes","grilling-ideas-and-recipes","lamb-recipes","main-dishes","middle-eastern-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_58ce4d3da4a7', 'en', 'US', 'Peruvian Chicken with Garlic Butter Rice', 'Known as Peruvian Blackened Chicken ("Pollo a la Brasa"), this chicken is traditionally made on a rotisserie. As with every ethnic dish, there are many many versions but the common ingredients in all are soy sauce, garlic and paprika. I served this with a garlic butter rice on the side. The rice recipe makes enough for around 6 servings and you''ll be thankful for this because it''s so yummy, you will want leftovers for the next day!', 'https://www.recipetineats.com/tachyon/2015/12/Peruvian-Roast-Chicken_1.jpg', 10, 45, 55, 4, '[{"id": "ing_chicken", "quantity": {"value": 1.134, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.24, "unit": "bottle of 250ml"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_rice", "quantity": {"value": 300.0, "unit": "pack"}}, {"id": "ing_chicken", "quantity": {"value": 1.134, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["2.5 lb (1.2 kg) chicken pieces (Note 1)"]},{"ingredients":["1 tbsp garlic powder OR 3 garlic cloves (, minced)","2 tsp cumin powder","1 tbsp paprika powder (preferably smoked but plain is ok)","4 tbsp soy sauce (Note 2)","2 tbsp lime juice (, fresh (1 lime))","1 tbsp olive oil"],"purpose":"Marinade"},{"ingredients":["4 garlic cloves, minced","1/2 onion (, finely diced (white, brown, yellow))","1 tbsp olive oil","2 cups long grain rice (, uncooked)","2 cups chicken broth / stock","1 cup water","2 - 4 tbsp butter (Note 3)","Salt and pepper"],"purpose":"Garlic Butter Rice"}]', '[{"description":"Place the Marinade ingredients in a small bowl and mix until lump free.","images":[],"step":1},{"description":"Place the chicken in a ziplock bag (my preferred method) or non reactive bowl and coat with Marinade. Marinade for at least 3 hours, preferably overnight (24 hours) OR freeze it straight away, then it will marinade while it defrosts.","images":[],"step":2},{"description":"Preheat oven to 180C/350F. Place chicken in a baking dish, skin side up. Slather leftover marinade onto the skin. Roast for 45 minutes or until deep burnt-red golden brown in colour.","duration":45,"images":[],"step":3},{"description":"Rest for 5 minutes before serving with Garlic Butter Rice and a green salad.","duration":5,"images":[],"step":4},{"description":"Garlic Butter Rice","images":[],"step":5},{"description":"Heat oil in a saucepan over medium heat. Add garlic and onion and cook for 5 minutes until onion is translucent and sweet.","duration":5,"images":[],"step":6},{"description":"Add rice and stir so the rice becomes translucent. Add broth and water, then cover and turn heat down to medium low.","images":[],"step":7},{"description":"Cook for 12 to 15 minutes until the liquid has JUST evaporated, then remove from stove and allow to rest for 10 minutes.","duration":13.5,"images":[],"step":8},{"description":"After resting, add the butter and stir the rice to fluff it up and disperse the butter.","images":[],"step":9}]', '["gluten","milk","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Peruvian","South American"],"categories":["chicken-drumstick-recipes","chicken-recipes","dietary","gluten-free-recipes","grilling-ideas-and-recipes","quick-and-easy","rice-recipes","south-american-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_25c585b65bde', 'en', 'US', 'Blackened Fish Tacos', 'Fish cooked with a punchy spice rub of Cajun Flavours! Perfectly paired with a Avocado-Lime Slaw to make these irresistible tacos.', 'https://www.recipetineats.com/tachyon/2015/10/Blackened-Fish-Tacos1-Featured.jpg', 20, 6, 26, 8, '[{"id": "ing_greek_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_imes_zested_and_juiced", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_jalape_os", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_mint", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_red_cabbage", "quantity": {"value": 3.0, "unit": "head"}}, {"id": "ing_cabbage", "quantity": {"value": 3.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.094, "unit": "jar of 400g"}}, {"id": "ing_sriracha", "quantity": {"value": 0.013, "unit": "bottle of 400ml"}}, {"id": "ing_lime", "quantity": {"value": 4.0, "unit": "net of 500g"}}, {"id": "ing_paprika", "quantity": {"value": 0.75, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_tortillas", "quantity": {"value": 8.0, "unit": "pack of 8"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["½ cup greek yogurt","1 avocado","1 cup cilantro/coriander leaves","2 garlic cloves","2 limes zested and juiced","2 jalapeños","2 tbsp mint (, roughly chopped)","½ tsp Kosher salt","Freshly ground black pepper (, to taste)","1 cup red cabbage (, finely shredded*)","1 cup green cabbage (, finely shredded*)","2 carrots (, grated*)"],"purpose":"Avocado-Lime Slaw"},{"ingredients":["1/4 cup mayonnaise","1 tsp Sriracha","1 tbsp fresh lime juice"],"purpose":"Quick Sriracha Aioli"},{"ingredients":["2 tbsp paprika","2 tsp ground cumin","2 tsp onion powder","2 tsp garlic powder","2 tsp dried thyme","2 tsp dry mustard","1 1/4 tsp Kosher salt","1/4 tsp cayenne pepper","2 tbsp extra virgin olive oil","4 tilapia fillets"],"purpose":"Blackened Fish"},{"ingredients":["8 (6 inch) tortillas","2 jalapeños (, sliced)","1 small bunch cilantro"],"purpose":"To Serve"}]', '[{"description":"In the bowl of a food processor, add the yogurt, avocado, cilantro, garlic, lime zest, lime juice, jalapeños, mint, salt, and pepper. Puree until smooth and creamy. Taste and add more salt and pepper, if needed. Place the shredded cabbage and carrots in a large bowl. Add 1/2 a cup of the avocado-lime dressing from the food processor and stir to combine. Add more dressing if you would like a creamier slaw. If not, you can use the extra dressing to top the tacos later. Refrigerate until ready to use.","images":[],"step":1},{"description":"In a small bowl, combine the ingredients for the Sriracha Aioli. Refrigerate until ready to use.","images":[],"step":2},{"description":"If you would like to toast the tortillas (highly recommended if you are using corn tortillas)* heat a pan over medium-high heat. Once hot, warm each tortilla 1 to 2 minutes per side – you want to heat the tortillas just enough to slightly char and add a bit of crispness, but not so much that when you fold it, it cracks. Wrap the tortillas in a clean tea towel to keep warm and set aside.","images":[],"step":3},{"description":"On a large plate, combine all of the spices to make the blackened seasoning. Dredge both sides of each fish fillet in the spice mixture. In a large saute pan, heat the olive oil over medium-high heat. At the first wisp of smoke from the pan, add the fillets, working in batches if needed. Cook for 2 -3 minutes on each side. (Do not move the fish fillets around while they''re cooking. Leave them be until they''re ready to flip). Transfer the cooked fillets to a cutting board and slice each fillet in-half, vertically - making 8 pieces.","duration":2.5,"images":[],"step":4},{"description":"To serve, top each tortilla with the fish, avocado-lime slaw, jalapeños, cilantro, and drizzle with the Sriracha aioli. Serve with extra wedges of lime and enjoy!","images":[],"step":5}]', '["milk","mustard"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Fusion"],"categories":["dietary","dinner-tonight","fish-recipes","gluten-free-recipes","grilling-ideas-and-recipes","main-dishes","mexican-recipes","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_68168b6c5abf', 'en', 'US', 'Bacon Wrapped Hot Dogs with Cheese Sauce', 'Full loaded hot dogs with bacon wrapped hot dogs, onions and smothered with a fantastic cheese sauce that stays creamy even at room temperature. This recipe makes more cheese sauce than you will probably need but it''s better to be safe than sorry. Use leftovers as dip!', 'https://www.recipetineats.com/tachyon/2015/06/Bacon-Wrapped-Hot-Dogs-3.jpg', 15, 10, 25, 6, '[{"id": "ing_cheddar_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.037, "unit": "pack of 400g"}}, {"id": "ing_milk", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_hot_dogs", "quantity": {"value": 6.0, "unit": "unit"}}, {"id": "ing_bacon", "quantity": {"value": 6.0, "unit": "pack of 200g"}}, {"id": "ing_othpicks", "quantity": {"value": 12.0, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 4.0, "unit": "pack of 1kg"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_bread", "quantity": {"value": 6.0, "unit": "loaf"}}, {"id": "ing_bacon", "quantity": {"value": 6.0, "unit": "pack of 200g"}}]', '[{"ingredients":["2½ cups grated cheddar or tasty cheese (, or any other good melting cheese)","1 tbsp cornstarch (corn flour)","1 can evaporated milk (375g / 12oz)","½ tsp onion powder (optional - adds extra flavour)","½ tsp garlic powder (optional - adds extra flavour)","1 tsp salt","1 to 2 tbsp milk"],"purpose":"Cheese Sauce"},{"ingredients":["6 hot dogs (American style - Note 1)","6 strips of streaky bacon (, long enough to wrap each hot dog)","12 to othpicks (, soaked in water for 30 minutes)","4 brown onions (, peeled and sliced)","1 tbsp oil","6 soft hot dog buns"],"purpose":"Hot dogs"},{"ingredients":["1/4 cup bacon (, diced)"],"purpose":"Bacon for Garnish"}]', '[{"description":"Toss together the cheese and cornstarch in a small saucepan.","images":[],"step":1},{"description":"Add the remaining ingredients EXCEPT the milk and cook over medium heat, whisking occasionally for the first couple of minutes then frequently as the cheese melts. Whisk until the Cheese Sauce is smooth (about 5 minutes).","images":[],"step":2},{"description":"Remove from the stove and let it cool to room temperature. Whisk vigorously every 5 minutes or so to blend the \"skin\" that forms on the surface into the Cheese Sauce.","images":[],"step":3},{"description":"Once it is at room temperature, use the milk to make the consistency suitable for dolloping onto the hot dogs.","images":[],"step":4},{"description":"Trim the edges of the bacon so they wrap neatly without overlapping.","images":[],"step":5},{"description":"Lay a strip of bacon on a work surface. Place a hot dog on the bacon on the diagonal. Then roll up the hot dog in bacon. Use a toothpick to secure each end. (See photo below)","images":[],"step":6},{"description":"If you are cooking the hot dogs on the stove or flat iron side of the BBQ, use scissors to trim the toothpicks so they aren''t sticking out. (Note 2)","images":[],"step":7},{"description":"Brush the grill side with oil and drizzle the remaining oil on the flat iron side of the BBQ. Then heat on medium high (or do this in a frypan over medium high on the stove).","images":[],"step":8},{"description":"On the flat iron side, add the onion and cook until dark golden brown. Cook the extra Bacon for Garnish at the same time (if using).","images":[],"step":9},{"description":"On the grill side, cook the hot dogs, turning until nicely browned all over.","images":[],"step":10},{"description":"Partially cut the hot dog buns. Place a bacon wrapped hot dog in the bun, top with onion, a generous amount of Cheese Sauce and Bacon for Garnish (if using).","images":[],"step":11}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["main_course"],"cuisine":["American"],"categories":["beef-recipes","grilling-ideas-and-recipes","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7e46742aecb2', 'en', 'US', 'Jamaican Jerk Chicken Drumsticks', 'The flavours of Jamaica in your own home! These chicken drumsticks have a really punchy, strong flavour. Make them as spicy as you want - or not! These are really tasty even if you pull back - or even leave out - the chili. This recipe is adapted from Oven Baked Jerk Chicken recipe by Immaculate Bites. I served these with Caribbean Rice and Beans (see recipe below) which is also a recipe from Immaculate Bites. This recipe needs to be marinating for at least 4 hours before cooking. It can be cooked in the oven or on the grill.', 'https://www.recipetineats.com/tachyon/2015/03/Jamaican-Jerk-Chicken-Rice-with-Beans-4_680px_webready.jpg', 15, 50, 65, 4, '[{"id": "ing_chicken", "quantity": {"value": 0.04, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_ime_juice_only", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 0.012, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_nutmeg_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[]', '[{"description":"Pat the chicken dry with a paper towel and place in a large ziplock bag.","images":[],"step":1},{"description":"Place Marinade ingredients in a food processor and whizz until smooth. Try not to touch the Marinade with bare hands to avoid getting chili on your hands.","images":[],"step":2},{"description":"Pour the Marinade into the ziplock bag. Close the bag, squeezing out excess air. Massage the bag from the outside to disperse the Marinade throughout the chicken. Marinate for at least 4 hours, or up to 24 hours.","images":[],"step":3},{"description":"When ready to cook, remove the chicken from the Marinade but reserve the Marinade.","images":[],"step":4},{"description":"Preheat the oven to 180C/350 (fan forced).","images":[],"step":5},{"description":"Place a wire rack on a baking tray lined with foil. Place the drumsticks on the rack and baste the top with half the Marinade. Bake for 25 minutes.","duration":25,"images":[],"step":6},{"description":"Turn the drumsticks and baste the top with the remaining Marinade. Bake for a further 20 to 25 minutes, until the drumsticks are very dark brown.","images":[],"step":7},{"description":"Rest for 5 minutes before serving, garnished with coriander/cilantro if using.","duration":5,"images":[],"step":8},{"description":"Preheat the grill side of the BBQ on medium (or medium low if your BBQ is strong). Brush the grill with oil, if required.","images":[],"step":9},{"description":"Place the chicken on the grill. Brush the top with 1/2 the Marinade. Cook for 10 minutes, then turn.","duration":10,"images":[],"step":10},{"description":"Brush the top with the remaining Marinade and cook for a further 5 to 8 minutes.","images":[],"step":11},{"description":"Then turn the chicken again (to cook the side that you just brushed Marinade on) and cook for a few minutes. (Total cook time around 20 minutes in total)","images":[],"step":12},{"description":"Remove from the BBQ and rest for 5 minutes before serving, garnished with coriander/cilantro if using.","duration":5,"images":[],"step":13}]', '["gluten","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Caribbean","Jamaican"],"categories":["chicken-drumstick-recipes","chicken-recipes","dietary","gluten-free-recipes","grilling-ideas-and-recipes","quick-and-easy","rice-recipes","rice-side-dishes","side-dishes","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_680f5c829f9b', 'en', 'US', 'Tzatziki Chickpea Salad', 'Recipe video above. Think of this Chickpea Salad as a better-for-you potato salad. Except - it can do so much more! Chickpeas mixed with an extra chunky tzatziki dressing, use this to make protein-laden salad bowls, super-food sandwiches, serve as a side or scoop with crackers.', 'https://www.recipetineats.com/tachyon/2024/09/Tzatziki-chickpea-salad_0.jpg', 12, 0, 72, 4, '[{"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.375, "unit": "tub of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_dill", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_chickpeas", "quantity": {"value": 2.0, "unit": "can of 400g"}}, {"id": "ing_celery", "quantity": {"value": 2.25, "unit": "head"}}, {"id": "ing_capers", "quantity": {"value": 30.0, "unit": "bottle"}}]', '[{"ingredients":["2 cucumbers (, grated using a box grater, excess water squeezed out very well (3/4 cup once squeezed))","1 1/4 cups Greek yogurt (or thick plain yogurt)","1 tbsp lemon juice","2 1/2 tbsp extra virgin olive oil (, plus extra for drizzling)","1/4 cup roughly chopped fresh dill (, plus extra for sprinkling, or half the quantity chopped fresh mint (Note 1))","1 large garlic clove (, crushed using garlic press , finely grate or very finely minced using a knife)","1/2 tsp cooking salt / kosher salt"],"purpose":"Tzatziki:"},{"ingredients":["2 x 400g / 14 oz cans chickpeas (, well drained (Note 2 for dried))","3/4 cup finely sliced celery (1 - 2 stems)","2 tbsp chopped capers (sub cornichons or dill pickles)"],"purpose":"Salad:"}]', '[{"title":"Mix","description":"Put the Tzatziki ingredients in a big bowl and mix. Add the chickpeas, celery and capers, mix again.","images":[],"step":1},{"title":"Wait 1 hour","description":"You can eat it straight away but it''s better if you can set aside for at least 1 hour to let the flavours meld (especially salt from capers & the garlic). It''s even better the next day. Give it a taste and add a pinch of extra salt if needed (capers saltiness can differ).","images":[],"step":2},{"description":"Serve drizzled with extra olive oil and extra dill. Dive in!","images":[],"step":3},{"description":"Ways to eat it:","images":[],"step":4},{"description":"As a side salad or salad meal, stuffed into sandwiches/wraps (+ avocado, good \"glue\"), add chicken or canned tuna for protein-boost salad meal.","images":[],"step":5}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Greek(ish)","Western"],"categories":["beans-lentils","dietary","gluten-free-recipes","lentil-recipes","no-cook-food","salad-recipes-main-course","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5e4a72222a2c', 'en', 'US', 'One-pan baked sausage & lentils', 'Recipe video above. In this recipe where both lentils and sausages are baked together in the same pan, the lentils absorb the sausage juices as they cook, making the humble lentils tastier than you ever dreamed possible! The recipe starts on the stove sautéing aromatics right in the roasting pan. Any metal pan will work, and it doesn''t matter if your stove burner isn''t large enough for the roasting pan- mine certainly isn''t.Don''t skip the cumin seeds. It gives this a special touch!', 'https://www.recipetineats.com/tachyon/2023/03/Baked-sausage-with-lentils_9.jpg', 10, 50, 60, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_green_onion", "quantity": {"value": 4.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_cumin", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_lentils", "quantity": {"value": 0.562, "unit": "can of 400g"}}, {"id": "ing_carrot", "quantity": {"value": 4.0, "unit": "pack of 1kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_chicken", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_sausages", "quantity": {"value": 8.0, "unit": "pack of 500g"}}]', '[{"ingredients":["3 tbsp extra virgin olive oil","4 eschallots/shallots (, peeled, halved, finely sliced (sub 1 large onion, Note 1))","3 garlic cloves (, finely minced)","1 tbsp cumin seeds (don''t skip this!)","1 1/2 cups puy lentils / French lentils (sub green/brown lentils, Note 3)","4 small carrots (, peeled, quartered, diced into 8mm/ 1/3\" cubes)","1 tsp cooking salt (kosher salt)","3/4 tsp black pepper","3 cups chicken broth/stock (, low sodium)","8 x 85g/3oz pork sausages (Note 3)"]}]', '[{"description":"Pre-heat oven to 200°C/400°F (180°C fan).","images":[],"step":1},{"title":"Cooking vessel","description":"Use a metal roasting pan ~23 x 33 cm / 9 x 13\". Fold a sheet of baking/parchment paper (large enough to cover pan) in half and cut 4 x ~10cm/4\" slits (steam vents! Note 4). Else, use foil - just tear steam vents.","images":[],"step":2},{"title":"Sauté aromatics","description":"Put the pan directly on the stove (really, it''s ok!) and heat the olive oil over medium high heat. Add eschallots and garlic, sauté for 3 minutes until soft. Add cumin seeds and stir for 1 minute.","duration":3,"images":[],"step":3},{"title":"Lentils & stock","description":"Add dried lentils, carrot, salt, pepper and stock. Bring to a simmer.","images":[],"step":4},{"title":"Sausages & paper","description":"Gently place the sausages on top (don''t press in). Cover with the paper, gently pressing so it \"sticks\" to the stock.","images":[],"step":5},{"description":"Bake for 25 minutes on the middle shelf. Remove paper and bake for 20 more minutes to brown the sausages.","duration":25,"images":[],"step":6},{"title":"Rest 5 min","description":"Remove from the oven. Rest for 5 minutes.","duration":5,"images":[],"step":7},{"description":"Serve the sausages with lentils. The flavour-loaded lentils are saucy so they act as the sauce for the sausages! Also pictured in post - baby spinach with Everyday Dressing.","images":[],"step":8}]', '[]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","lentil-recipes","quick-and-easy","sausage-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a80c52a806f1', 'en', 'US', 'Simple Bean Soup from El Bulli (world''s all time greatest restaurant!)', 'Recipe video above. This Bean Soup comes to you from El Bulli restaurant, famed in its time for topping the World’s 50 Best Restaurant list, year after year. But fear not! This is not a complex Michelin star dish. It’s a simple bean soup from the El Bulli staff cookbook, "The Family Meal".If this tasty little number is good enough for the folks behind this world class restaurant, it’s good enough for the rest of us!Don''t skip the Picada. It totally makes it.', 'https://www.recipetineats.com/tachyon/2021/09/El-Bulli-Bean-Soup-with-Picada_22.jpg', 15, 45, 60, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.025, "unit": "bunch"}}, {"id": "ing_rosemary", "quantity": {"value": 0.025, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_tomato", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_x_400g_cans_cannellini_beans", "quantity": {"value": 4.0, "unit": "pack"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_whole_hazelnuts", "quantity": {"value": 37.5, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}]', '[{"ingredients":["1 tbsp extra virgin olive oil","1 garlic clove ((large), minced)","1 brown onion (, (1 large, 2 small), finely chopped (~180g/6oz))","1/4 tsp fresh thyme (, chopped (sub 1/8 tsp dried))","1/4 tsp fresh rosemary (, chopped (sub 1/8 tsp dried))","1 bay leaf (, fresh (or 1/2 dried))","1/3 cup tomato passata (Note 1)","4 x 400g/14oz cans cannellini beans (, drained (Note 2 for dried))","3 cups vegetable stock"],"purpose":"Bean Soup:"},{"ingredients":["1 cup fresh parsley leaves (, roughly chopped (ie chop then lightly pack in))","1 garlic clove ((medium), roughly chopped)","2 tbsp extra virgin olive oil","1/4 cup whole hazelnuts (, skin on (or almonds))","1/2 tsp cooking / kosher salt (or 1/4 tsp table salt) (Note 4)"],"purpose":"Picada recipe (makes 4 tbsp):"}]', '[{"title":"Saute onion and herbs 8 minutes","description":"Heat oil in a large heavy based pot over medium heat. Add garlic, onion, herbs and cook, stirring regularly, for 8 minutes until the onions are a deep golden brown and sweet.","duration":8,"images":[],"step":1},{"title":"Cook tomato passata 8 minutes","description":"Add tomato passata and cook over low heat for another 8 minutes until the tomato changes from red and watery to dark brown a d very thick. Don''t skimp on this step, it''s key for flavour!","images":[],"step":2},{"title":"Simmer","description":"Stir in the beans followed by the vegetable stock. Adjust heat so it''s bubbling very gently and simmer for 15 minutes with the lid off.","duration":15,"images":[],"step":3},{"title":"Blitz","description":"Transfer 2/3 cup (150ml) of soup into a jug or jar large enough to fit the head of a blender stick. Blitz until smooth then stir it back into the soup to thicken the broth.","images":[],"step":4},{"title":"Stir in Picada","description":"Just before serving, stir in 2 tablespoons of Picada. Taste and add more salt if needed (canned beans differ in salt). Then serve immediately.","images":[],"step":5},{"title":"Serve","description":"Dollop each bowl with 1 teaspoon of remaining Picada. Crusty bread highly recommended (easy Artisan, no yeast bread or French brioche).","images":[],"step":6},{"title":"Toast hazelnuts","description":"Preheat a small skillet over medium heat. Add hazelnuts and toast, shaking the skillet regularly, until there are golden patches and they smell nutty.","images":[],"step":7},{"title":"Remove most skin","description":"Transfer hazelnuts to a clean tea towel. Bundle up and rub vigorously with hands to remove most of the skin (which is bitter). (No need to do this with almonds)","images":[],"step":8},{"title":"Blitz","description":"Roughly chop hazelnuts then add into a jug just large enough to fit the head of a stick blender with remaining ingredients. Blitz until it''s like pesto - not completely smooth. Use per recipe.","images":[],"step":9}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Spanish"],"categories":["dietary","gluten-free-recipes","lentil-recipes","soup-recipes","spanish-recipes","vegan-lifestyle","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0bbfbc881e89', 'en', 'US', 'Homemade Baked Beans with Bacon (Southern)', '(Recipe video above) Southern baked beans in a thick savoury sauce with a touch of sweet and hint of tang. Loaded with BACON! Serve as a side, or have it for breakfast with bacon and eggs. It even makes a hearty meal itself - great for slopping up with bread!', 'https://www.recipetineats.com/tachyon/2017/02/Southern-Baked-Beans-with-Bacon_8.jpg', 10, 75, 85, 12, '[{"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_bacon", "quantity": {"value": 0.75, "unit": "pack of 200g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_x_400g_cans_red_kidney_or_other_beans_drained_and_rinsed", "quantity": {"value": 3.0, "unit": "pack"}}, {"id": "ing_ketchup", "quantity": {"value": 0.225, "unit": "bottle of 500g"}}, {"id": "ing_tomato", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_molasses", "quantity": {"value": 37.5, "unit": "jar"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 7.5, "unit": "bottle"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["1 tbsp oil","150g/ 5 oz bacon (, chopped)","1 medium onion (, finely chopped)","3 cloves garlic (, minced (or 1 1/2 tsp garlic paste))","3 x 400g / 14oz cans red kidney or other beans, drained and rinsed (Note 1)","3/4 cup ketchup (Note 2)","3/4 cup tomato passata / US tomato puree (Note 3)","1/4 cup molasses (Note 4)","2 tbsp cider vinegar","3/4 cup water","2 tsp mustard powder (or 1 tbsp Dijon or American mustard)","1 1/2 tsp Worcestershire sauce","1/2 tsp cayenne pepper","3/4 tsp EACH salt & pepper (, plus more to taste)"]}]', '[{"description":"Heat oil over high heat (can skip oil if bacon is super fatty). Add bacon and cook for 2 minutes.","duration":2,"images":[],"step":1},{"description":"Add onion and garlic. Cook for 3 minutes until onion and bacon are golden.","duration":3,"images":[],"step":2},{"description":"Add remaining ingredients. Stir, bring to simmer, then place lid on.","images":[],"step":3},{"description":"Then either turn down heat to medium low (simmering gently) and cook on the stove for 1 hour, stirring every now and then so the bottom doesn''t catch. OR bake at 160°C/325°F for 60 minutes.","images":[],"step":4},{"title":"SLOW COOKER option","description":"Reduce water to 1/4 cup, transfer to slow cooker and cook for 6 hours on low.","images":[],"step":5},{"description":"The sauce should be thickened (cook with lid off for a bit if not thick enough) and glossy. Adjust salt and pepper to taste at the end. See notes for serving suggestions!","images":[],"step":6}]', '["mustard"]', '["gluten_free","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Southern"],"categories":["easter-sides-warm-hearty","lentil-recipes","side-dishes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b1885916fa7d', 'en', 'US', 'Greek Marinated Chickpea Salad', 'Recipe video above. Chickpea salads can be so bland... but not this one! We''re marinating the chickpeas so they absorb the flavour of the lovely Greek dressing. Mediterranean flavours, bright and fresh,this works as a starch + veg side dish, or main course served with crusty bread or flatbreads for scooping!Serves 4 as a main course or 8 as a side.', 'https://www.recipetineats.com/tachyon/2020/06/Chickpea-Salad_0.jpg', 10, 0, 10, 4, '[{"id": "ing_chickpeas", "quantity": {"value": 2.0, "unit": "can of 400g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.075, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_mustard", "quantity": {"value": 0.013, "unit": "jar of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_spinach", "quantity": {"value": 3.0, "unit": "bag of 250g"}}, {"id": "ing_feta_cheese", "quantity": {"value": 100.0, "unit": "block of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}]', '[{"ingredients":["800g/ 14oz (2 cans) chickpeas, (well drained (Note 1))"]},{"ingredients":["2 tbsp red wine vinegar (Note 2)","5 tbsp extra virgin olive oil","1 garlic clove (, minced using garlic press)","2 tsp dried oregano","1/2 tsp dijon mustard (or other non spicy smooth mustard)","3/4 tsp EACH salt and pepper"],"purpose":"Dressing / Marinade:"},{"ingredients":["1/2 red onion (, finely sliced)","1/2 cup red wine vinegar (Note 2)","1 tsp white sugar","1/2 tsp salt"],"purpose":"Quick pickled onion (pickling optional, Note 3):"},{"ingredients":["250g/ 8oz cherry or grape tomatoes (, halved (or 2 normal tomatoes))","3 cups (packed) spinach, (sliced 1/2 cm / 1/5\" thick (Note 4))","100g/ 3oz feta","3/4 cup chargrilled peppers (, drained and sliced 1cm / 1/3\" thick (optional, Note 5))"],"purpose":"Salad:"}]', '[{"description":"Shake Dressing in a jar.","images":[],"step":1},{"description":"Marinated chickpeas:","images":[],"step":2},{"description":"Place chickpeas in a microwaveable bowl. Toss with half the Dressing.","images":[],"step":3},{"description":"Microwave 1 1/2 minutes, stirring every 30 seconds, until warmed through.","images":[],"step":4},{"description":"Set aside 20 minutes to marinate (warm chickpeas = absorbs flavour).","images":[],"step":5},{"description":"Quick Pickled Onion:","images":[],"step":6},{"description":"Mix ingredients in a bowl, set aside 30 minutes until onion is wilted. Drain.","images":[],"step":7},{"title":"Speedy option","description":"microwave for 2 minutes until hot, cool 10 minutes then use.","duration":2,"images":[],"step":8},{"description":"Assemble salad:","images":[],"step":9},{"description":"Place spinach in a big bowl, add marinated chickpeas (including all residual Dressing in the bowl). Add tomatoes, pickled onion and peppers, if using.","images":[],"step":10},{"description":"Pour over remaining Dressing, toss well. Transfer to serving plate, crumble over feta, serve!","images":[],"step":11}]', '["mustard"]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["dinner","lunch"],"cuisine":["Greek(ish)","Western"],"categories":["beans-lentils","lentil-recipes","quick-and-easy","salad-recipes-main-course","side-dishes","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ef69eda03bc7', 'en', 'US', 'Homemade Heinz Baked Beans', 'Recipe video above. This is seriously so similar to Heinz, it''s scary! Except - no artifical flavouring, and the sauce isn''t slimy which I really hate about canned baked beans. Make with DRIED or CANNED beans. Navy beans / haricot, if you can find them (that''s what Heinz uses) otherwises any beans (preferably white).', 'https://www.recipetineats.com/tachyon/2014/05/Homemade-Heinz-Baked-Beans_0.jpg', 5, 30, 95, 8, '[{"id": "ing_navy_beans", "quantity": {"value": 300.0, "unit": "pack"}}, {"id": "ing_x_400g_cans_harricot_navy_beans_cannellini_or_any_white_beans", "quantity": {"value": 3.0, "unit": "pack"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_tomato", "quantity": {"value": 0.09, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.09, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.1, "unit": "pack of 400g"}}]', '[{"ingredients":["2 cups (14 oz) dried Navy beans (aka Haricot) (or other white beans)","3 x 400g/14oz cans harricot/navy beans, cannellini or any white beans (, drained )"],"purpose":"Beans – choose ONE (Note 1):"},{"ingredients":["2 cups chicken stock/broth (, low sodium, OR homemade vegetable stock (Note 2))","1 cup water","2 tsp Worcestershire sauce","6 tbsp ketchup or Aussie/British tomato sauce (Note 3)","2 tbsp tomato paste","3 tbsp brown sugar","1 tbsp apple cider vinegar","1/2 tsp garlic powder (or more onion powder)","1/2 tsp garlic powder (or more onion powder)","1/2 tsp black pepper","1 tsp salt"],"purpose":"Baked beans:"},{"ingredients":["8 tsp cornflour / cornstarch","1/4 cup water"],"purpose":"Sauce thickening:"}]', '[{"description":"Cook dried beans:","images":[],"step":1},{"description":"No need to do these steps if using canned beans, start with Step 1 under \"Baked Beans\" below.","images":[],"step":2},{"title":"Soak beans in a big bowl of water for 8","description":"24 hrs, then drain.","duration":960,"images":[],"step":3},{"title":"Skim foam","description":"Place beans in a large pot of water over high heat. Bring to a simmer, then skim off foam.","images":[],"step":4},{"description":"Simmer Reduce heat so it''s simmering gently (medium or medium low). Partially cover with lid (leaving a crack for steam to escape), then cook for 1 - 1.5 hrs until just tender. (Start checking at 45 min). Beans should be still slightly firm on inside (they''re cooked more in the sauce). Drain, use per recipe.","images":[],"step":5},{"title":"Mix","description":"Place all Baked Beans ingredients in a pot (except beans) and stir, then add beans.","images":[],"step":6},{"title":"Simmer","description":"Bring to a simmer, then lower heat to medium low and simmer for 20 minutes, without the lid. Stir every now and then so the beans don''t catch on the bottom of the pot.","duration":20,"images":[],"step":7},{"description":"Mix cornflour with water. Pour into pot while stirring, then cook for 2 minutes until sauce thickens - it will thicken quickly. (Note 3)","duration":2,"images":[],"step":8},{"title":"Check for salt","description":"Taste and add more salt if needed.","images":[],"step":9},{"title":"Serve it the traditional way","description":"piled over hot buttered toast. Or ladle into bowls, eat with a spoon and dunk in hot crusty bread! Popular breads - simple crusty Artisan bread, Irish Soda Bread (No yeast) and No Yeast Sandwich Bread","images":[],"step":10}]', '[]', '["gluten_free","low_calorie"]', '{"mealType":["breakfast"],"cuisine":["British","English","Western"],"categories":["breakfast-recipes","lentil-recipes","quick-and-easy","side-dishes","vegan-lifestyle","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7687065f7be2', 'en', 'US', 'Creamy Tomato Bean Soup', 'Recipe video above. This is a white bean soup with a thick, creamy broth that''s full of savoury flavour with a hint of tomato. It''s a fast way to turn bland beans into a really filling soup that so simple to make, yet so, so good! The flavour trick - blitzing up the sautéed onion, carrot and garlic with just a bit of the beans. Keep it meat free or see notes for how to add ham, bacon, chicken or sausage! This is VERY filling - and keeps you full for ages (thank you beans!)', 'https://www.recipetineats.com/tachyon/2020/04/Creamy-Tomato-Bean-Soup_0.jpg', 5, 20, 25, 4, '[{"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_italian_herb_mix", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_tomato", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_chicken", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_x_420g_cans_cannellini_or_any_white_beans_drained_rinsed", "quantity": {"value": 3.0, "unit": "pack"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_baby_spinach", "quantity": {"value": 120.0, "unit": "bag of 250g"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}]', '[{"ingredients":["2 tbsp/ 30g butter (, unsalted)","1 onion (, finely chopped (brown, yellow, white))","2 garlic cloves (, finely chopped)","1 carrot (, large, peeled and finely chopped)","1 1/2 tsp Italian herb mix OR other dried herbs (oregano, thyme, parsley, basil, or mixed)","3/4 cup (170g) tomato paste (Note 1)","1/2 cup (125ml) dry white wine (, optional (can omit) )","4 cups (1 litre) stock/broth, chicken or veg (, low sodium)","3 x 420g/15oz cans cannellini or any white beans, drained & rinsed","1/2 cup (50g) parmesan (, grated)","1/2 tsp EACH salt and pepper","120g/4oz baby spinach (or 5 - 6 cups any other leafy greens OR 4 cups diced veg, Note 3)","3/4 cup (185ml) cream, heavy/thickened ((optional) OR more butter!)"]}]', '[{"description":"Melt butter in a pot over medium high heat. Cook garlic, onion and carrot for 5 minutes until carrot is soft and sweet.","duration":5,"images":[],"step":1},{"description":"About 3 minutes in, add the Italian herbs and cook with the onion (makes the herb flavour \"bloom\").","images":[],"step":2},{"description":"Turn heat up to high, add tomato paste. Cook for 2 minutes to remove the “raw” flavour.","duration":2,"images":[],"step":3},{"description":"Add white wine, cook for 3 minutes until the harsh “winey” smell is gone and mostly evaporates so you’re just left with tomato paste again.","duration":3,"images":[],"step":4},{"description":"Add 1/2 cup of beans (to thicken soup), stock, parmesan, salt and pepper. Stir, low heat, cover and simmer 3 minutes, stirring every now and then.","images":[],"step":5},{"description":"Use a stick blender to puree until smooth (or transfer to blender).","images":[],"step":6},{"description":"Add remaining beans, simmer 3 minutes. Stir in spinach until wilted, then stir in cream if using. Add more salt and pepper if needed (note: canned beans are already salted).","images":[],"step":7},{"description":"Serve with crusty bread for dunking!","images":[],"step":8}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","gluten-free-recipes","lentil-recipes","quick-and-easy","soup-recipes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9c910cef270e', 'en', 'US', 'Lentil Curry - mega flavour lentil recipe!', 'Recipe video above. This will be an eye opener for you - an incredible creamy coconut curry made with just TWO spices! Hugely economical, this is essentially a streamlined version of Indian Dahl, delivering a similar intoxicating curry flavour but a whole lot less complicated.', 'https://www.recipetineats.com/tachyon/2020/04/Lentil-Curry_9.jpg', 5, 55, 60, 5, '[{"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.6, "unit": "jar of 50g"}}, {"id": "ing_turmeric", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_lentils", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["50g (3 tbsp) butter (, unsalted (sub 2 tbsp neutral oil))","4 garlic cloves (, finely minced (Note 1))","1.5 tbsp ginger (, finely minced (Note 1))","1 onion (, finely chopped (white, yellow, brown))","2 tbsp curry powder (, mild or spicy (your choice!) (Note 2))","1/2 tsp tumeric powder","1/2 tsp cayenne pepper (, optional)","1 1/4 tsp salt","1/2 tsp black pepper","1 cup dried lentils (, green or brown (or any other dried lentils or split peas, Note 3))","400 ml / 14 oz coconut milk (, full fat)","400g/ 14 oz canned tomato (, crushed or diced)","3 cups (750 ml) water"]},{"ingredients":["1/2 cup coriander/cilantro (, finely chopped)","Yogurt (, optional)","Basmati rice (or other rice)"],"purpose":"Serving:"}]', '[{"title":"Saute onion","description":"Melt butter in a pot over medium heat. Add onion, garlic and ginger. Slowly cook, stirring every now and then, for 10 minutes until tinged with gold and the onion is sweet.","duration":10,"images":[],"step":1},{"title":"Cook off spices","description":"Turn heat up to high, add curry powder and turmeric, stir for 1 1/2 minutes.","images":[],"step":2},{"title":"Add everything else","description":"Add remaining ingredients and stir. Bring to simmer, then place lid on and adjust heat to low / medium low so it''s simmering gently.","images":[],"step":3},{"title":"Simmer","description":"Simmer for 30 minutes, then remove lid and simmer for a further 10 minutes to reduce the sauce. {Note 2 for cook times of other lentils}","duration":30,"images":[],"step":4},{"description":"Lentils should be soft, sauce should be thickened and creamy. Too thick, add water. Too thin, simmer with lid off - thickens quickly.","images":[],"step":5},{"title":"Coriander","description":"Stir through half the coriander, then taste and add more salt if needed.","images":[],"step":6},{"description":"Serve over basmati rice, sprinkled with more coriander and a dollop of yogurt. (Low carb option - cauliflower rice).","images":[],"step":7}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["coronavirus-food","curry-recipes","dinner-tonight","indian-recipes","lentil-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9f86eb812b83', 'en', 'US', 'Lentil Soup', 'Recipe VIDEO above. Don''t settle for a bland lentil soup. Make it right, and you''ll have everyone begging for seconds...and thirds! The touch of spices and finishing it off with lemon really lifts this soup to the next level.', 'https://www.recipetineats.com/tachyon/2017/03/Lentil-Soup-6.jpg', 10, 45, 55, 6, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_carrot", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_steak", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_lentils", "quantity": {"value": 0.75, "unit": "can of 400g"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_paprika", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["2 tbsp olive oil","1 onion, chopped (white, brown, yellow)","2 garlic cloves, minced","1 large carrot (, chopped (about 1 1/4 cups))","2 celery ribs (, chopped (about 1 1/4 cups))","2 cups / 400g dried lentils (, green or brown, rinsed (Note 1))","400g / 14 oz crushed tomato","1.5 litres / 1.5 quarts (6 cups) vegetable or chicken (stock / broth, low sodium)","1/2 tsp each cumin and coriander powder","1 1/2 tsp paprika powder","2 dried bay leaves","1 lemon (zest + juice)","1/4 tsp salt and pepper, (each)"]},{"ingredients":["Chopped fresh parsley, for garnish","Warm bread, to serve"],"purpose":"To Serve"}]', '[{"description":"Heat oil in a large pot over medium heat. Add garlic and onion, cook for 2 minutes.","duration":2,"images":[],"step":1},{"title":"Add celery and carrot. Cook for 7","description":"10 minutes or until softened and the onion is sweet. Don''t rush this step, it is key to the flavour base of the soup.","duration":8.5,"images":[],"step":2},{"description":"Add all remaining ingredients except the lemon and salt. Stir.","images":[],"step":3},{"description":"Increase heat and bring to simmer. Scoop scum on the surface off and discard (do this again during cooking if required). Place lid on and turn heat down to medium low. Simmer for 35 - 40 minutes or until lentils are soft.","duration":37.5,"images":[],"step":4},{"description":"Remove bay leaves.","images":[],"step":5},{"title":"Thicken Soup","description":"Using a stick blender, do 2 or 3 quick whizzes to thicken the soup (see video below). Or transfer 2 cups to a blender, let it cool slightly, then hold lid with tea towel and blend then transfer back into pot.","images":[],"step":6},{"description":"Add a touch of water if you want to adjust soup consistency. Season to taste with salt and pepper. Grate over the zest of the lemon then add a squeeze of lemon juice just before serving. Garnish with parsley if desired and serve with warm crusty bread slathered liberally with butter!","images":[],"step":7}]', '["gluten"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["coronavirus-food","dinner-tonight","lentil-recipes","main-dishes","quick-and-easy","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d0c2f5002235', 'en', 'US', 'Brazilian Coconut Chickpea Curry', 'Recipe video above. A chickpea recipe that even carnivores think is worth making!! The sauce is from this traditional Brazilian Fish Stew. I call it a curry because it tastes distinctly curryish - except with a fraction of the ingredients!', 'https://www.recipetineats.com/tachyon/2020/02/Brazilian-Chickpea-Curry_2.jpg', 10, 15, 25, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_chickpeas", "quantity": {"value": 2.0, "unit": "can of 400g"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.5, "unit": "jar of 40g"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_baby_spinach", "quantity": {"value": 50.0, "unit": "bag of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 0.9, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_rice", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["1.5 tbsp olive oil","1 onion (, finely chopped)","2 garlic cloves (, minced)","1 red capsicum/bell peppers (, cut into 3 x 0.75cm / 1.25 x 1/3\"\" strips)","2 cans chickpeas (, drained (Note 1))","400ml/14oz coconut milk (, full fat for best flavour (Note 2))","400ml/14oz can crushed tomato","1 cup (250ml) chicken or vegetable stock/broth (, low sodium)","1 tbsp paprika","1 tbsp cumin","1/2 - 1 tsp cayenne pepper (adjust spiciness to taste)","1.5 tsp sugar (any type)","0.5 tsp salt","50g / 2oz baby spinach leaves (or kale)"],"purpose":"Chickpea Curry:"},{"ingredients":["3 tbsp coriander/cilantro (, roughly chopped, plus more for serving (Note 3))","1 tbsp lime juice (, plus extra wedges for serving)","Yogurt (optional)","Rice - or something to soak up the sauce (Note 4)"],"purpose":"Finishing & Serving:"}]', '[{"description":"Heat oil in a pot or large deep skillet over high heat. Add garlic and onion, cook for 1 minute.","duration":1,"images":[],"step":1},{"description":"Add capsicum, cook for 2 minutes until onion is translucent and slightly golden on edges.","duration":2,"images":[],"step":2},{"description":"Add remaining Curry ingredients except baby spinach. Stir, bring to simmer then lower to medium low so it''s simmering gently.","images":[],"step":3},{"title":"Simmer 12","description":"15 minutes until it changes from pale pink to an orangey red colour.","images":[],"step":4},{"description":"Stir in spinach until just wilted, then stir in coriander and lime juice. Add more salt it needed.","images":[],"step":5},{"description":"Serve over rice with a dollop of yogurt, extra sprinkle of coriander and squeeze of lime (don''t go overboard, I often do and it''s too sour!)","images":[],"step":6}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Brazilian","South American"],"categories":["curry-recipes","dietary","gluten-free-recipes","lentil-recipes","main-dishes","quick-and-easy","south-american-recipes","stews","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2ebeddbe4e0a', 'en', 'US', 'Easy Chickpea Curry with Potato (Chana Aloo Curry)', 'Recipe video above. Say goodbye to boring chickpea recipes! This vegetarian curry called Channa Aloo Curry, is a really great authentic Chickpea Curry that packs serious flavour, is easy, and no need to hunt down unusual spices - everything is from the local grocery shop. It''s a Caribbean curry from Trinidad that tastes very similar to tomato based Indian curries. Spiciness: Medium, from the cayenne pepper most, and bit from white pepper. Can reduce or omit (Note 3).', 'https://www.recipetineats.com/tachyon/2016/01/Chickpea-Curry_7.jpg', 15, 25, 40, 5, '[{"id": "ing_curry_powder", "quantity": {"value": 0.6, "unit": "jar of 50g"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_nutmeg_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 666.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_potato", "quantity": {"value": 1.5, "unit": "bag of 2kg"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.985, "unit": "can of 400g"}}, {"id": "ing_tomato", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.04, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_white_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2 tbsp curry powder (, mild - just regular grocery store brands like Clives, Keens(Note 2))","1 tsp All Spice powder","1 tsp nutmeg powder (or 1/2 tsp freshly grated)","1 1/2 tsp smoked paprika (or normal/sweet)","2 tsp dried thyme leaves (or 3 tsp fresh)","1 tsp cumin powder","3/4 tsp cayenne pepper (for spiciness - reduce or omit (Note 3))","1 tsp white pepper (or 1/2 tsp black pepper) (Note 3)"],"purpose":"Spices (Note 1):"},{"ingredients":["3 tbsp canola or coconut oil (any type) (, or any other oil for cooking)","2 large garlic cloves (, minced)","1 large onion (, diced (brown, white, yellow))","1 1/2 cups potatoes (, cut into 1.2cm / 1/2\" cubes (1 large, any type, peeled))","28 oz / 800g canned chickpeas (2 x 14oz/400g cans), drained (Note 3)","14 oz / 400g canned crushed tomatoes","2 cups vegetable or chicken broth/stock (, low sodium)","1 tsp cooking salt / kosher salt (, plus more to taste (halve for table salt))","2 green onion (, sliced (green & white part))","2 tbsp fresh parsley (, finely chopped (or coriander/cilantro) - optional)"],"purpose":"Curry"},{"ingredients":["1 tbsp coriander/cilantro leaves (, chopped - optional)","Dollop of yogurt (- recommended)","Basmati rice (OR)","White rice"],"purpose":"Serving – choose"}]', '[{"description":"Sauté garlic and onion, then toast Spices for 1 min. Stir in potatoes, then chickpeas, tomato, stock and salt. Simmer 15 min, stir in green onion and parsley, serve!","duration":1,"images":[],"step":1},{"title":"Sauté","description":"Heat oil in a large pot or very deep skillet over medium high heat. Add onion and garlic, cook for 3 minutes until onion is translucent.","duration":3,"images":[],"step":2},{"description":"Add Curry Spices and stir for 1 minute.","duration":1,"images":[],"step":3},{"description":"Add the potatoes and stir to coat in the Spices. If the spices start to stick to the bottom of the pot, add a tiny splash of water.","images":[],"step":4},{"title":"Simmer 15 minutes","description":"Add the chickpeas, tomatoes, veg or chicken broth and salt. Bring to simmer then turn down the heat to medium and simmer for 15 minutes, or until the potatoes are cooked and the sauce has thickened.","duration":15,"images":[],"step":5},{"title":"Adjust salt","description":"Taste and add more salt if needed. Stir through scallions/shallots and parsley.","images":[],"step":6},{"description":"Serve with rice with a dollop of yogurt and coriander/cilantro if desired. Basmati would be ideal, or Coconut Rice if you''re wanting to impress. To go all out, add some Easy Soft Flatbreads!","images":[],"step":7}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Caribbean","Trinidad"],"categories":["curry-recipes","dietary","dinner-tonight","gluten-free-recipes","indian-recipes","lentil-recipes","main-dishes","quick-and-easy","vegan-lifestyle","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_39547d7e90fb', 'en', 'US', 'Falafel', 'Recipe video above. Deep bronze and crispy on the outside, vivid green, moist and fluffy on the inside. Delicately spiced with a beautiful fresh herb flavour, these falafels are the perfect balance of flavour, texture and can''t-stop-eating-them delicious! Best served fresh out of the fryer. Recipe requires 12 hrs+ soaking time.', 'https://www.recipetineats.com/tachyon/2018/09/Falafel_4.jpg', 25, 10, 35, 20, '[{"id": "ing_chick_peas", "quantity": {"value": 225.0, "unit": "unit"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_green_onion", "quantity": {"value": 6.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.017, "unit": "tub of 150g"}}, {"id": "ing_flour", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.075, "unit": "L"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_tahini", "quantity": {"value": 60.0, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_tabbouleh", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_hummus", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}]', '[{"ingredients":["225 g / 8 oz dried chick peas (Note 1)","1 cup parsley leaves (, roughly chopped)","1 cup coriander/cilantro leaves (, roughly chopped)","6 scallions/shallots (, white and light green part only finely chopped (Note 2))","2 cloves of garlic (, minced)","1 tsp cumin","1/2 tsp coriander","1 1/2 tsp salt","1/2 tsp baking powder (Note 3)","4 tsp flour ((plain/all purpose) OR chickpea flour)","5 tbsp water"],"purpose":"Falafels:"},{"ingredients":["500 ml / 2 cups+ vegetable oil (Note 4)"],"purpose":"For frying:"},{"ingredients":["4 tbsp tahini","2 tbsp lemon juice","4 tbsp water","1/4 tsp salt (adjust to taste)"],"purpose":"Tahini Sauce (Other Sauces Note 5):"},{"ingredients":["Pita bread or other flatbreads","Tabbouleh (recipe below)","Hummus (optional extra)","Shredded lettuce, tomato slices, sliced red or white onion"],"purpose":"Serving (Note 6):"}]', '[{"description":"Place chickpeas in a large bowl and pour over plenty of cold water. Leave to soak 12 + hours (even 2 days is fine).","images":[],"step":1},{"description":"Drain chickpeas well. Place in food processor, add remaining Falafel ingredients.","images":[],"step":2},{"description":"Blitz for 2 to 3 minutes on high, scraping down sides as necessary, until the chickpeas are very small grains. Mixture should look like smooth guacamole from the outside (see video).","duration":2.5,"images":[],"step":3},{"description":"Scoop up heaped tablespoons and shape into balls (or dome, disc or torpedo), place on a tray. Should make around 20, about 2.5cm / 1\" wide.","images":[],"step":4},{"description":"Refrigerate for 30 minutes.","duration":30,"images":[],"step":5},{"title":"Pour oil in a skillet or large pot","description":"at least 1.7 cm / 2/3\" depth (Note 4). Heat on medium high to 180 - 190C / 355F (or drop a bit in, should sizzle energetically).","images":[],"step":6},{"description":"Place a ball in a large spoon (or tongs) and slide ball in. Cook in batches for around 4 minutes, using 2 forks to roll, until deep golden and super crusty on the outside.","images":[],"step":7},{"description":"Drain on paper towels. Repeat with remaining falafel.","images":[],"step":8},{"description":"Serve fresh out of the fryer with Sauce of choice! Make falafel wraps or plates with tabbouleh, tomato, onion, and Sauces of choice. See Notes 5 and 6.","images":[],"step":9},{"description":"Combine tahini and lemon juice, and mix well. The mixture will stiffen.","images":[],"step":10},{"description":"Stir in the water 1 tbsp at a time and it will loosen again. The final consistency should be like a thick drizzle sauce (see video). Season to taste with salt.","images":[],"step":11}]', '["gluten"]', '["keto_friendly","low_calorie","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern"],"categories":["cuisines","deep-fried-recipes","dietary","gluten-free-recipes","iconic-dishes","lentil-recipes","middle-eastern-recipes","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b9129fe3a95f', 'en', 'US', 'Easy Coconut Curry Sauce', 'Recipe video above. This 30 minute recipe is all about the sauce that has beautiful depth of flavour, tastes like an Indian curry but not quite as intense. Specifically created this using spices you can get from everyday grocery stores, rather than having to find speciality Indian spices, but without sacrificing flavour. It''s utterly addictive! I really love lentils and pumpkin with this creamy sauce, but feel free to use whatever you want, including proteins - see notes. Spiciness: Low, as long as your Curry Powder and Garam Masala are not spicy.', 'https://www.recipetineats.com/tachyon/2018/04/Coconut-Curry-with-Lentils-and-Pumpkin_0.jpg', 15, 15, 30, 5, '[{"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_chicken", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_lentils", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_pumpkin", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_baby_spinach", "quantity": {"value": 2.0, "unit": "bag of 250g"}}, {"id": "ing_cashews", "quantity": {"value": 75.0, "unit": "jar"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_garam_masala", "quantity": {"value": 15.0, "unit": "jar"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.6, "unit": "jar of 50g"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_turmeric", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}]', '[{"ingredients":["2 tbsp coconut oil, ghee or any regular cooking oil (canola, olive oil etc)","4 garlic cloves (, minced)","2 tsp fresh ginger (, finely grated)","1/2 onion (, finely chopped (brown or yellow))","400ml/14oz can coconut milk (full fat)","1 cup chicken broth","1/2 cup tomato passata (tomato puree) (Note 1)","400 g/14 oz can brown lentils (, drained)","250 g / 8 oz pumpkin (~3 cups) (, cut into 2cm / 4/5\" cubes)","2 cups (tightly packed) baby spinach","1/2 cup cashews (, unsalted (roasted or raw) (Note 2))","1/2 tsp each cooking/kosher salt + black pepper"]},{"ingredients":["1 tbsp garam masala (Note 3)","2 tbsp curry powder (mild or spicy, your choice, Note 4)","2 tsp cumin","1 tsp coriander powder","1 tsp paprika (sweet, or hot for spice!)","1/2 tsp turmeric powder"],"purpose":"Spices:"},{"ingredients":["Coriander/cilantro leaves (, whole or chopped)","Chopped cashews (optional)"],"purpose":"Serving garnishes:"}]', '[{"title":"Sauté aromatics","description":"Heat oil in a deep skillet or pot over medium high heat. Add onion, garlic and ginger, cook for 2 minutes until onion is a bit tinged with gold.","duration":2,"images":[],"step":1},{"title":"Cook off spices","description":"Add Spices and stir for 1 minute. Don''t worry if it looks a bit dried out.","duration":1,"images":[],"step":2},{"title":"Coconut sauce","description":"Add coconut milk, passata and broth. Stir until incorporated. Add lentils and pumpkin. Bring to simmer then adjust heat so it''s simmering energetically.","images":[],"step":3},{"description":"Simmer for 10 minutes or until pumpkin is tender but not mushy, and sauce has thickened.","duration":10,"images":[],"step":4},{"description":"Stir through baby spinach until wilted, then cashew nuts. Add salt and pepper last, adding more if needed.","images":[],"step":5},{"description":"Serve over rice, sprinkled with coriander and extra cashews, if using.","images":[],"step":6}]', '[]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["curry-recipes","dietary","dinner-tonight","gluten-free-recipes","lentil-recipes","main-dishes","pumpkin","quick-and-easy","sunday-supper","vegan-lifestyle","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_044ee0a4008f', 'en', 'US', 'Middle Eastern Spiced Chickpea Salad', 'Recipe video above. The best Chickpea Salad I''ve ever had! Inspired by a recipe from "Jerusalem" by Yotam Ottolenghi, spiced chickpeas give this a wow factor and the Dressing is a beautiful lemon vinaigrette that is not as sharp as most lemon dressings.', 'https://www.recipetineats.com/tachyon/2014/05/Spiced-Chickpea-Salad_1.jpg', 12, 3, 10, 4, '[{"id": "ing_chickpeas", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_cardamon", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_vinegar", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["400g / 14 oz can chickpeas, drained but still wet (Note 1)","2 tbsp olive oil"],"purpose":"Chickpeas"},{"ingredients":["1 tsp ground cumin","1 1/2 tsp All Spice","1 tsp ground cardamon","1/4 tsp salt"],"purpose":"Chickpea Spices"},{"ingredients":["2 cucumbers (, diced)","2 tomatoes ((or 3 medium tomatoes), diced)","1 red onion (small) (, diced)","1/4 cup coriander leaves (, roughly chopped)","1/4 cup parsley (, roughly chopped)"],"purpose":"Salad"},{"ingredients":["1 1/2 tbsp sherry vinegar (Note 2)","Zest of half a lemon","2 tbsp lemon juice","1/4 cup extra virgin olive oil","1 tsp caster sugar","1 garlic clove, smashed (Note 3)","Salt and pepper"],"purpose":"Dressing"}]', '[{"description":"Combine the Dressing ingredients in a jar and shake. Set aside for 20 minutes to allow the flavours to develop.","duration":20,"images":[],"step":1},{"description":"Place chickpeas in a large bowl. Scatter over Spices, then toss to coat. The wetness of the chickpeas will make the spices stick.","images":[],"step":2},{"description":"Heat 2 tbsp olive oil in a large pan over high heat and fry the chickpeas for a couple of minutes. Shake the pan so the chickpeas roll, or stir gently (so the spice coating doesn''t come off). Transfer into bowl and cool slightly.","images":[],"step":3},{"description":"Combine the Salad Ingredients in a bowl. Drizzle with a bit of Dressing and toss. Transfer to serving bowl.","images":[],"step":4},{"description":"Top salad with chickpeas (warm or at room temperature). Drizzle with more Dressing. Toss very gently, if desired (don''t toss too much otherwise spice comes off chickpeas). Serve immediately.","images":[],"step":5},{"description":"Great served with a dollop of yoghurt and pita bread to stuff the salad into.","images":[],"step":6}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Middle Eastern"],"categories":["beans-lentils","cuisines","lentil-recipes","middle-eastern-recipes","quick-and-easy","salad-recipes-main-course","side-salads","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_986a091f1ab0', 'en', 'US', 'Chickpea Lamb Shawarma Soup', 'No such thing as bland chickpea soups in my world! Exploding with the flavours of your favourite Chicken Shawarma, except it’s in SOUP form with lamb and chickpeas! This is not spicy, the small amount of cayenne pepper gives it a tiny warm hum, so if you want it spicier, just add more at the end. Deceptively veggie loaded and is quick to make! Recipe VIDEO below.', 'https://www.recipetineats.com/tachyon/2017/12/Chickpea-Lamb-Shawarma-Soup-4.jpg', 10, 20, 30, 4, '[{"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_cardamon", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_lamb_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_chickpeas", "quantity": {"value": 2.0, "unit": "can of 400g"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_spinach", "quantity": {"value": 1.0, "unit": "bag of 250g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["2 tsp EACH cumin powder, coriander, paprika","1 tsp cardamon powder (can omit if you don’t have)","¼ tsp cinnamon powder","½ tsp cayenne pepper (adjust to taste)","1/2 tsp black pepper","1 tsp salt"],"purpose":"Spices:"},{"ingredients":["2 tbsp olive oil","2 garlic cloves (, minced)","1 onion (, finely chopped)","500 g / 1 lb lamb mince (ground lamb, or beef) (Note 1)","2 tbsp tomato paste","2 carrots (, peeled and chopped (about size of chickpeas))","600 g / 21 oz canned chickpeas (, drained and rinsed (1.5 standard cans, Note 2))","400 g / 14 oz can crushed tomato","3 cups / 750 ml chicken broth / stock","1 bunch spinach (, roughly chopped (about 4 packed cups) (wilts a lot))"],"purpose":"Soup:"},{"ingredients":["Plain yoghurt (or sour cream)","Chopped fresh coriander / cilantro"],"purpose":"Garnishes (highly recommended):"}]', '[{"description":"Heat oil in a large pot over high heat. Add garlic and onion, cook for 1 minute until starting to turn translucent.","duration":1,"images":[],"step":1},{"description":"Add lamb and cook, breaking it up as you go. When it has mostly turned from pink to light brown, add spices.","images":[],"step":2},{"description":"Cook for 1 minute, then add tomato paste and cook for another 1 minute. (It smells amazing!)","duration":1,"images":[],"step":3},{"description":"Add carrots, chickpeas, tomato and broth. Stir and bring to simmer.","images":[],"step":4},{"description":"Cover with lid, lower heat so it is bubbling energetically but not crazy rapidly. Cook for 10 minutes until carrot is tender but not super soft – I like it to have a bit of bite still, if you want super soft, keep cooking.","duration":10,"images":[],"step":5},{"description":"Stir through spinach. Once wilted, adjust salt, pepper and spiciness (cayenne) to taste, and water if you want more liquid.","images":[],"step":6},{"description":"Ladle into bowls, add a dollop of yoghurt and a generous sprinkling of coriander. Enjoy!","images":[],"step":7}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern"],"categories":["cuisines","dietary","gluten-free-recipes","lamb-recipes","lentil-recipes","main-dishes","middle-eastern-recipes","quick-and-easy","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_26ea360a002d', 'en', 'US', 'Hummus', 'RECIPE VIDEO ABOVE. EVERYONE should know how to make a great hummus! I usually make this with canned chickpeas but see notes for using dried (stove or pressure cooker). Quick to make, and so much better than store bought - it''s always so sour because of the preservatives.With a decent food processor, the hummus is certainly smooth enough for my taste. But if you want ultra smooth, see the recipe notes!', 'https://www.recipetineats.com/tachyon/2014/05/Hummus-2-4.jpg', 5, 0, 5, 6, '[{"id": "ing_chickpeas", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_lemon", "quantity": {"value": 0.075, "unit": "net of 500g"}}, {"id": "ing_tahini_hulled_mixed_well_before_using", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.083, "unit": "L"}}]', '[{"ingredients":["400g / 14 oz canned chickpeas (1 can) (, drained (reserve liquid and a few chickpeas for garnish) (Dried Chickpeas - Note 1))","1/4 cup liquid from the canned chickpeas","1 medium garlic clove (, minced)","1/4 cup fresh lemon juice","1/2 cup tahini, hulled (sesame paste), mixed well before using (Note 2)","1/3 cup extra virgin olive oil","1/4 tso cooking salt / kosher salt (plus more if needed)","Pinch black pepper"]},{"ingredients":["Pinch of paprika, more olive oil and reserved chickpeas"],"purpose":"Garnish"}]', '[{"title":"Extra smooth optional steps","description":"If you want ultra smooth hummus, do one of the extra Smooth Hummus steps below (I rare bother!).","images":[],"step":1},{"title":"Reserve for garnish","description":"Reserve 10 or so chickpeas for garnish.","images":[],"step":2},{"description":"Blitz! Place remaining chickpeas, garlic, lemon, tahini and olive oil in a food processor or blender. Blitz until it becomes a paste.","images":[],"step":3},{"title":"Season","description":"Add the salt and pepper.","images":[],"step":4},{"title":"Thin sauce","description":"Add reserved liquid from can. Blitz for a couple of minutes until smooth but it won''t be 100% smooth unless you do one of the extra steps below. (Personally, not being 100% smooth doesn''t bother me, it''s \"normal\"!)","images":[],"step":5},{"title":"Adjust","description":"Adjust lemon and salt to taste (saltiness of different chickpea brands differ), and loosen it needed by adding more liquid. It should be a soft dropping consistency, like ketchup.","images":[],"step":6},{"title":"Serve the traditional way","description":"dollop a big scoop of hummus on a plate or shallow bowl. Use a spoon to spread it and make swirls on the surface. Top with reserved chickpeas, drizzle generously with more olive oil and sprinkle with paprika.","images":[],"step":7},{"description":"Optional- easy ways to make ultra smooth hummus (Note 4)","images":[],"step":8},{"title":"Method 1","description":"Drain chickpease, place in large bowl and fill with water. Grab handfuls and rub between your hands submerged in the water - skins will rub off and float to surface. Skim floating skin off, drain and use per recipe.","images":[],"step":9},{"title":"Method 2","description":"Tip all contents of can INCLUDING liquid into heatproof bowl. Cover loosely with lid or clingwrap, microwave on high for 3 minutes. Drain then use per recipe (hot chickpeas blitz smoother).","duration":3,"images":[],"step":10}]', '["sesame"]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Middle Eastern"],"categories":["cuisines","dip-recipes","lentil-recipes","middle-eastern-recipes","quick-and-easy","super-bowl-party-food","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f025441aa29b', 'en', 'US', 'Sexy Lentil Salad', 'Not just another lentil salad....this is Can''t-Stop-Eating-It delish. Made with green lentils, feta, tomatoes, cucumber and drizzled with a beautiful lemon salad dressing. Cooking the lentils in a simple flavoured broth rather than just water or marinating canned lentils in the dressing makes all the difference. Outrageously long-looking ingredient list is misleading! Keeps well for 2 days, recipe video below.', 'https://www.recipetineats.com/tachyon/2017/07/Lentil-Salad-5.jpg', 15, 20, 35, 4, '[{"id": "ing_lentils", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_chicken", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_feta_cheese", "quantity": {"value": 90.0, "unit": "block of 200g"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1 cup / 200g dried green lentils (or other lentils) (Note 1 for canned)","1 cup / 200g vegetable or chicken broth (or water + 1 bouillon cube, crumbled)","1 1/2 cups / 375 ml water","1 large garlic clove (, smashed (Note 2))","Lemon peel (about 1.5 x 5 cm / 3/4 x 2\")","1 bay leaf (, dry or fresh)","2 sprigs thyme (, or 1/2 tsp dried thyme)","1 rib celery (, broken into 3 or 4 pieces (or just a handful of leafy fronds))"],"purpose":"Lentils:"},{"ingredients":["250 g / 8oz cherry tomatoes (, halved or quartered (Note 3))","2 cucumbers (, cut into quarters then diced)","1 red onion (, finely diced)","¼ cup coriander / cilantro (, finely chopped)","¼ cup parsley (, finely chopped)","90 g / 3 oz feta (, crumbled (or more!))","2 handfuls rocket / arugula lettuce (optional - bed for salad)"],"purpose":"Salad:"},{"ingredients":["2 tsp lemon zest","2 tbsp lemon juice","1/3 cup / 85 ml extra virgin olive oil","1 tsp Dijon mustard","1 garlic clove (, minced)","1 tsp sugar, optional","½ tsp salt + black pepper"],"purpose":"Lemon Dressing:"}]', '[{"description":"Place Lentil ingredients in a large saucepan over high heat. Bring to simmer then turn down to medium low. Cook for 20 minutes for firm (I like this) or 25 minutes for soft. DO NOT overcook and make it mushy!","duration":20,"images":[],"step":1},{"description":"Drain in a colander, pick out celery etc. Rinse VERY quickly just to remove any grit coating the lentils (don''t want to rinse away flavour!). Set aside.","images":[],"step":2},{"description":"Place Dressing ingredients in a jar, shake well.","images":[],"step":3},{"description":"Place lentils, tomato, cucumber, onion, coriander, parsley and some of the feta in a large bowl. Pour over most of the Dressing, then toss.","images":[],"step":4},{"description":"Place rocket lettuce on a serving platter. Pile salad on top. Drizzle over remaining Dressing and crumble over feta. Serve! (I like serving with pita bread to stuff it in)","images":[],"step":5}]', '["mustard"]', '["gluten_free","low_calorie"]', '{"mealType":["main_course"],"cuisine":[],"categories":["beans-lentils","dietary","dinner-tonight","easter-brunch-recipes","easter-sides-fresh-light","gluten-free-recipes","lentil-recipes","low-calorie-recipes","main-dishes","quick-and-easy","salad-recipes-main-course","side-dishes","side-salads","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_730988d3915d', 'en', 'US', 'Middle Eastern Rice (Mejadra)', 'Mejadra is a fragrant Middle Eastern rice pilaf with crunchy fried onion throughout it. This is slightly adapted from a Yotam Ottolenghi recipe, from his wonderful cookbook Jerusalem. The main difference is that he uses dried lentils, I use canned. If you don''t have time or don''t want to deep fry, substitute the fried onions with Asian fried shallots, available from Asian stores and the Asian section of major supermarkets in Australia (Coles, Woolies). The taste is remarkably similar!', 'https://www.recipetineats.com/tachyon/2014/05/Mejadra-Middle-Eastern-Rice-Pilaf-1.jpg', 5, 15, 20, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_lentils", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_round_turmeric", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_round_cinnamon", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 3000.0, "unit": "pack of 1kg"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}]', '[{"ingredients":["2 tbsp olive oil","2 tsp cumin seeds (or 1 tsp ground cumin)","1 1/2 tbsp coriander seeds (or 1 1/2 tsp ground coriander)","1 cup basmati or long grain rice (, uncooked)","1 1/4 cup / 315 ml water (see notes)","400g / 14 oz canned brown lentils, drained (1 can) (, drained )","1/2 tsp ground turmeric","1 1/2 tsp ground cinnamon","1 tsp sugar","1 tsp salt","Black pepper"]},{"ingredients":["3 large or 4 small onions (, very finely sliced)","1 cup / 250 ml vegetable or sunflower oil","Salt"],"purpose":"Crispy Fried Onions (Note 2)"}]', '[{"description":"Heat oil in a medium saucepan over medium high heat. Add about 1/3 of the onions and cook for 5 minutes until golden and crispy. Drain on paper towels.","duration":5,"images":[],"step":1},{"description":"Repeat with remaining onions, in two batches.","images":[],"step":2},{"description":"Put the olive oil, cumin seeds and coriander in a saucepan over medium heat.","images":[],"step":3},{"description":"Cook for a couple of minutes until the spices are fragrant.","images":[],"step":4},{"description":"Add the rice and stir to coat with the oil and spices.","images":[],"step":5},{"description":"Add the water and lentils.","images":[],"step":6},{"description":"While it comes to boil, add all the other spices, salt and pepper.","images":[],"step":7},{"description":"When it comes to a boil, turn it down to medium-low, cover with lid and let cook for 10 to 12 minutes, or until all the liquid has mostly been absorbed.","duration":11,"images":[],"step":8},{"title":"Remove from heat and let it rest for 10 minutes","description":"during this time, any residual liquid will absorb.","duration":10,"images":[],"step":9},{"description":"Fluff rice with a fork and adjust the seasoning with more salt if you wish.","images":[],"step":10},{"description":"Just prior to serving, stir through most of the onions and top with remainder. Sprinkle with chopped coriander if desired. Best served warm.","images":[],"step":11}]', '[]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Arabic","Middle Eastern"],"categories":["cuisines","easter-sides-warm-hearty","lentil-recipes","middle-eastern-recipes","quick-and-easy","rice-recipes","rice-side-dishes","side-dishes","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e1af99f04c95', 'en', 'US', 'Cauliflower and Chickpea Curry', 'This homestyle traditional Indian curry has all the familiar complex, spicy flavours of curries you know and love, but is much healthier and lighter than the usual suspects you get from restaurants. No hunting down hard to find ingredients! I really recommend serving this with yoghurt - adds a touch of creaminess to this healthy tomato based curry. Adding the garam masala towards the end is a great tip - adds a fresh burst of curry flavour', 'https://www.recipetineats.com/tachyon/2016/09/Cauliflower-Chickpea-Curry_6.jpg', 10, 20, 30, 4, '[{"id": "ing_vegetable_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1000.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_turmeric", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_uncategorized", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_frozen_peas", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_garam_masala", "quantity": {"value": 15.0, "unit": "jar"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}]', '[{"ingredients":["4 tbsp vegetable oil","1 tbsp ginger (finely grated)","3 large garlic cloves (minced.)","1 large onion (chopped (brown, white, yellow))","3 tsp coriander powder","1/4 tsp tumeric powder","1 tsp cumin powder","2 tsp paprika","1 1/2 cups chicken stock","800 g / 28 oz can crushed tomato","300 g / 4 cups (packed cauliflower small florets (1 small / 1/2 large cauliflower))","400 g / 14 oz can chickpeas (drained)","Salt","1 tsp sugar - optional (Note 1)","3/4 cup frozen peas (75g)","3 tsp garam masala powder (Note 2)","1/4 cup coriander / cilantro leaves (chopped)","Yoghurt (to serve (highly recommended))"]}]', '[{"description":"Heat oil in a large deep skillet or pot over medium high heat. Add garlic and ginger, cook for 1 minute. Add onion and cook for 6 - 8 minutes or until golden and caramelised.","duration":1,"images":[],"step":1},{"description":"Add coriander, turmeric, cumin and paprika. Cook for 1 minute.","duration":1,"images":[],"step":2},{"description":"Add chicken stock and tomato. Stir to combine, bring to simmer and cook for 5 minutes.","duration":5,"images":[],"step":3},{"description":"Add cauliflower and chickpeas. Cook for 15 minutes or until cauliflower is soft and sauce has thickened. If sauce is thickening too quickly (Note 3), put the lid on. Adjust salt to taste, and add sugar if using.","duration":15,"images":[],"step":4},{"description":"Add peas and garam masala. Cook for 2 minutes, then remove from stove. Stir through most of the coriander.","duration":2,"images":[],"step":5},{"description":"Serve curry with basmati rice or plain white rice, garnished with reserved coriander and yoghurt on the side.","images":[],"step":6}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["curry-recipes","dietary","dinner-tonight","gluten-free-recipes","indian-recipes","lentil-recipes","main-dishes","most-popular","quick-and-easy","vegan-lifestyle","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_43603b3d94f8', 'en', 'US', 'Vegetarian Mexican Lasagna', 'Mexican flavours stacked in a lasagna-type form = Mexican Lasagna! Fresh, light and healthy yet packed full of flavour thanks to the gorgeous Enchilada sauce. The key is whizzing it up in a blender to get the punchy fresh flavours into the sauce! Feel free to swap out the veggies with whatever you want to use.', 'https://www.recipetineats.com/tachyon/2016/09/Vegetarian-Mexican-Casserole-Lasagna_2.jpg', 15, 30, 45, 5, '[{"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_zucchini", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_black_beans", "quantity": {"value": 1.062, "unit": "can of 400g"}}, {"id": "ing_corn", "quantity": {"value": 0.562, "unit": "can of 400g"}}, {"id": "ing_tortillas", "quantity": {"value": 750.0, "unit": "pack of 8"}}, {"id": "ing_cheese", "quantity": {"value": 2.5, "unit": "block of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["800 g / 28oz crushed canned tomato","1 tbsp olive oil","1 clove garlic (, whole peeled)","1/2 red onion (, chopped)","1 cup fresh coriander / cilantro (, lightly packed)","1 tbsp EACH cumin (, oregano and paprika (any type))","1 tsp EACH salt (, garlic powder, cayenne pepper (optional) and sugar (any))","2 tsp coriander powder","Black pepper"],"purpose":"Enchilada Sauce"},{"ingredients":["1 tbsp olive oil","1 garlic clove (, minced)","1/2 red onion (, finely chopped)","1 large red capsicum / bell pepper (, chopped (~1 1/2 cups))","2 zucchinis (, chopped (~1 1/2 cups))"],"purpose":"Hot Filling"},{"ingredients":["425 g / 14 oz can black beans (, drained and rinsed)","1 1/2 cups frozen corn","6 large flour tortillas (approx 22 cm / 9\" wide) (2)","2 1/2 cups / 200g grated melting cheese (I used low fat cheddar)","Fresh coriander / cilantro leaves (, for garnish (optional))"],"purpose":"Assembling"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Place Enchilada Sauce ingredients in a blender and whizz until onion is whizzed in and no longer visible. (In my Vitamix, I started on 3 then cranked it to 8 and it took 15 seconds)","images":[],"step":2},{"description":"Heat oil in a large non stick skillet. Add garlic and onion, cook for 1 minute. Add capsicum, cook for 1 minute. Add zucchini and cook for 3 minutes until charred. Remove skillet from heat.","duration":1,"images":[],"step":3},{"description":"Smear a bit of Enchilada Sauce on the bottom of a casserole dish. Place 1 tortilla in the middle, then tear on in half and place on either side (see step photos or video).","images":[],"step":4},{"description":"Top with half the Hot Filling. Scatter over half the black beans, half the corn. Drizzle over 1 cup Enchilada Sauce and 3/4 cup grated cheese.","images":[],"step":5},{"description":"Repeat with another layer so you have 2 layers of filling. Then for the last layer, top with tortillas then cover 2 cups of Enchilada Sauce (Note 3) and scatter over remaining cheese.","images":[],"step":6},{"description":"Bake for 25 minutes or until cheese is bubbling and golden. Stand for 5 minutes, then garnish with fresh coriander and serve.","duration":25,"images":[],"step":7}]', '["gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Tex-Mex"],"categories":["casseroles-and-cosy-bakes","dietary","gluten-free-recipes","lentil-recipes","low-calorie-recipes","quick-and-easy","vegan-lifestyle","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8099f73ff738', 'en', 'US', 'One Skillet Oven Baked Chicken Shawarma and Rice Pilaf', 'This combines two of my favourite Middle Eastern foods into one pot - Chicken Shawarma and Rice Pilaf. The Chicken Shawarma is the same recipe as the one I use for grilling (recipe here) with just quantities adjusted to suit using thigh cutlets cooked on the stove. The rice pilaf has been adapted from Yotam Ottolenghi''s Chicken with Cardamon Rice recipe from his cookbook "Jerusalem" (one of my all time favourite cookbooks!). Note that this is not an authentic way of preparing Chicken Shawarma! Real Shawarma is cooked on a rotisserie then shaved and served in a kebab. This is my one pot rice version - Shawarma flavours, made in one pot with rice!', 'https://www.recipetineats.com/tachyon/2015/08/One-Pot-Chicken-Shawarma-and-Rice_Hero.jpg', 15, 50, 65, 5, '[{"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 0.09, "unit": "net of 500g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_rice", "quantity": {"value": 225.0, "unit": "pack"}}, {"id": "ing_chicken", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_cardamon", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 2.0, "unit": "jar"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_raisins", "quantity": {"value": 0.25, "unit": "unit"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 large garlic clove (, minced (or 2 small cloves))","1 1/2 tsp ground coriander","1 1/2 tsp ground cumin","1 tsp ground cardamom","1 tsp smoked paprika (or ordinary is fine)","1 tsp cayenne pepper (optional)","1/2 tsp salt","Black pepper","3 tbsp lemon juice"],"purpose":"Spice Rub"},{"ingredients":["5 chicken thigh fillets (, bone in, skin on - about 2 lb / 1kg in total (Note 1))","1/2 tbsp olive oil","1 small onion (, finely diced)","2 garlic cloves (, minced)","1 1/2 cups long grain rice (, uncooked (Note 2))","1 1/2 cups chicken broth (or water)","2 cups water","3/4 - 1 tsp salt","Black pepper","1 1/2 tsp cardamon powder","2 cinnamon sticks (or 1/2 tsp cinnamon powder)","400g (14oz) can chickpeas (, drained (1 can))","1/4 cup raisins or sultanas (optional)"],"purpose":"Chicken and Rice"},{"ingredients":["Yoghurt (plain, unsweetened. Greek yoghurt is great)","Cilantro/coriander leaves (, roughly chopped)","Parsley leaves (, roughly chopped)"],"purpose":"Garnish (optional)"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Mix the Spice Rub ingredients together in a small bowl. Slather onto the chicken, covering both sides.","images":[],"step":2},{"title":"Optional","description":"Marinate for at least 1 hour, up to 24 hours. (Note 3)","images":[],"step":3},{"description":"Heat olive oil in a large skillet over medium high heat. Add the chicken, skin side down, and cook for 5 minutes on each side, or until light golden brown.","duration":5,"images":[],"step":4},{"description":"Remove chicken from skillet. Scrape off excess black bits stuck to the pan and discard, along with excess oil (but leave some to cook the onion).","images":[],"step":5},{"description":"Add garlic and onion. Cook for 2 minutes until translucent.","duration":2,"images":[],"step":6},{"description":"Add rice and stir so the grains are coated in oil and become a bit translucent.","images":[],"step":7},{"description":"Add remaining ingredients. Place the chicken on top - it should be half submerged with the skin above the surface. Pour in the juices from the plate as well.","images":[],"step":8},{"description":"Bring to simmer, then place a lid on (or cover with foil) and transfer to oven.","images":[],"step":9},{"description":"Bake for 35 minutes, then remove the lid and bake for a further 10 minutes.","duration":35,"images":[],"step":10},{"description":"Remove from the oven. Let it rest for 5 minutes.","duration":5,"images":[],"step":11},{"description":"Remove chicken from the rice and mix the rice quickly (to evenly distribute flavour).","images":[],"step":12},{"description":"Serve, garnished with cilantro/coriander and parsley if desired. I also like to serve it with a bit of plain yoghurt. (Note 4)","images":[],"step":13}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern"],"categories":["chicken-recipes","cuisines","dietary","dinner-tonight","gluten-free-recipes","lentil-recipes","main-dishes","middle-eastern-recipes","most-popular","one-pot-recipes","quick-and-easy","rice-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_aa0a3cf3ec6f', 'en', 'US', 'Chorizo Baked Beans on Toast', 'Transform canned beans into an upmarket bistro style breakfast with the addition of chorizo! Baked beans is a breakfast staple in Australia and the UK. A great one takes hours to make. This is much faster to make than the traditional method, and the extra flavour oomph comes from the chorizo!', 'https://www.recipetineats.com/tachyon/2015/07/Chorizo-Beans-Egg-Toast_600px_1-Featured.jpg', 10, 15, 25, 3, '[{"id": "ing_chorizo", "quantity": {"value": 0.184, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_cannellini_beans_drained", "quantity": {"value": 396.9, "unit": "pack"}}, {"id": "ing_tomato", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["6 1/2 oz / 200g chorizo (Note 1)","1 tbsp olive oil","2 garlic cloves (, minced)","1/2 onion (, diced (white, brown or yellow))","14 oz / 420g canned cannellini beans ((or any other white beans, such as navy), drained)","14 oz / 420g can crushed tomatoes","1/2 cup water","1 tbsp sugar (brown, white or raw - or even honey)","1 tsp paprika","1 1/2 tsp cumin powder","1/2 tsp cayenne pepper or red chili flakes (optional)","1 tsp salt","Black pepper"],"purpose":"Baked Beans"},{"ingredients":["Eggs (, cooked to your liking sunny side up (or poached or boiled))","Sourdough bread slices (, toasted)"],"purpose":"To Serve"}]', '[{"description":"Dice most of the chorizo, leaving some in slice form if you want to use them for garnish like I did.","images":[],"step":1},{"description":"Heat the olive oil in a skillet over high heat.","images":[],"step":2},{"description":"Add the garlic and onions and cook for 2 minutes or until starting to turn translucent.","duration":2,"images":[],"step":3},{"description":"Add the chorizo (all of it) and saute until the chorizo is nicely browned.","images":[],"step":4},{"description":"Add the remaining Baked Beans ingredients. Bring to simmer, then turn it down to medium low and leave to bubble away gently for 10 minutes or so, stirring occasionally. Add a splash of water if it gets too thick to your liking.","duration":10,"images":[],"step":5},{"description":"Adjust salt and pepper to taste.","images":[],"step":6},{"description":"To Serve","images":[],"step":7},{"description":"Pile the Baked Beans onto toasted sourdough and top with a fried egg.","images":[],"step":8}]', '["egg","gluten"]', '["high_protein"]', '{"mealType":["breakfast"],"cuisine":[],"categories":["breakfast-recipes","dietary","gluten-free-recipes","lentil-recipes","side-dishes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8478f8a826c9', 'en', 'US', 'Breakfast Enchiladas', 'Fully loaded breakfast enchiladas! Tortillas wrapped around scrambled eggs, bacon and beans cooked with a fragrant tomato sauce and gooey melted cheese. Serve with plenty of toppings for optimal experience! The Filling is great for making ahead - 3 days in the fridge or you can freeze it. I find that 1 enchilada is not quite enough (but I have a rather robust appetite! :) ) and 2 is too much. So in my house, 6 of these serves 4 - 1 1/2 each!', 'https://www.recipetineats.com/tachyon/2015/06/Breakfast-Enchiladas-2_680px.jpg', 15, 30, 45, 6, '[{"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_canned_tomatoes", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_kidney_beans", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_bacon", "quantity": {"value": 1.134, "unit": "pack of 200g"}}, {"id": "ing_egg", "quantity": {"value": 416.667, "unit": "carton of 12"}}, {"id": "ing_tortillas", "quantity": {"value": 6.0, "unit": "pack of 8"}}, {"id": "ing_cheese", "quantity": {"value": 0.5, "unit": "block of 250g"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 1/2 tbsp olive oil","2 garlic cloves (, minced)","1 small onion ((red, brown, white, yellow), diced)","1 cup red capsicum ((bell peppers), roughly diced)","400 g / 14 oz crushed tinned tomato","400 g / 14 oz canned black beans or red kidney beans (, drained)","2 tsp paprika powder","2 tsp cumin powder","1/2 tsp salt","Black pepper"],"purpose":"Filling"},{"ingredients":["8 oz / 250 g bacon (, diced)","5 large eggs ((or 6 normal eggs), lightly whisked)"],"purpose":"Bacon and Eggs"},{"ingredients":["6 soft tortillas (standard size around 20cm/8\" in diameter)","1/2 cup cheese"],"purpose":"Enchiladas"},{"ingredients":["Diced avocado","Sour cream","Coriander/cilantro"],"purpose":"Garnishes (optional)"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Heat olive oil in a large skillet over high heat. Add garlic and onion and saute until the onion is translucent.","images":[],"step":2},{"description":"Add the capsicum and cook for another 1 minute.","images":[],"step":3},{"description":"Add remaining Filling ingredients. Stir then turn the heat down to medium and let it cook for 5 minutes or so until thickened. Transfer to a bowl and let it cool slightly.","duration":5,"images":[],"step":4},{"description":"Wipe the pan clean and return to high heat. Add bacon and cook until light golden brown. Drain fat if there is excess. Turn heat down to medium Add the eggs and gently stir and fold them into the bacon mixture until the eggs almost set but are still watery.","images":[],"step":5},{"description":"Remove pan from heat. The eggs will continue cooking in the residual heat.","images":[],"step":6},{"description":"Lay the tortillas on a work surface. Divide the Filling mixture between them, then top with Bacon and Egg mixture. Sprinkle with cheese then roll the Enchiladas up.","images":[],"step":7},{"description":"Place in a baking dish (or tray) and bake for 10 to 15 minutes, or until the top is golden brown and you can see that the cheese has melted.","duration":12.5,"images":[],"step":8},{"description":"Serve with desired garnished. I highly recommend sour cream and avocado.","images":[],"step":9}]', '["egg","milk"]', '["gluten_free"]', '{"mealType":["main_course"],"cuisine":[],"categories":["breakfast-recipes","dietary","egg-recipes","enchiladas","gluten-free-recipes","lentil-recipes","mexican-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_726aa57f79b9', 'en', 'US', 'Antipasto chickpea salad', 'Recipe video above. This salad uses big, punchy antipasto flavours to transform canned chickpeas from meh to seriously delicious - fast! Excellent protein-laden, meat-free meal or work lunch option as it keeps well for 3 days. Switch out the add-ins with whatever takes your fancy. But whatever you do, don''t skip the sun-dried tomatoes. The tasty oil from the jar is used for the dressing, and it’s your secret flavor weapon here.', 'https://www.recipetineats.com/tachyon/2023/05/Antipasto-chickpea-salad_8.jpg', 15, 0, 15, 4, '[{"id": "ing_extra_virgin_olive_oil", "quantity": {"value": 0.075, "unit": "L"}}, {"id": "ing_vinegar", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_coriander", "quantity": {"value": 0.025, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_chickpeas", "quantity": {"value": 2.0, "unit": "can of 400g"}}, {"id": "ing_packed_cups_baby_rocket_arugula_leaves", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_jar_marinated_artichoke_hearts", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_black_kalamata_olives", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_tomato", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 0.025, "unit": "bunch"}}, {"id": "ing_feta_cheese", "quantity": {"value": 200.0, "unit": "block of 200g"}}]', '[{"ingredients":["5 tbsp oil reserved from sun-dried tomatoes jar ((in salad, below), or extra virgin olive oil)","2 1/2 tbsp sherry vinegar (Note 1)","1 medium garlic clove (, minced using garlic press (or finely grated))","1/4 tsp ground coriander","1/4 tsp cooking salt/kosher salt","1/4 tsp black pepper"],"purpose":"Dressing:"},{"ingredients":["2 x 400g/14 oz cans chickpeas (, drained (Note 3 for dried))","3 packed cups baby rocket/arugula leaves (, roughly torn by hand into 2.5cm / 1\" pieces (Note 4))","350g/12 oz jar roasted red pepper strips (, drained, roughly chopped into 2.5cm/1\" pieces)","200g/7 oz jar marinated artichoke hearts (, drained, roughly chopped into 1.25 cm / 1/2\" pieces)","1/2 cup sliced black kalamata olives","3/4 cup sun-dried tomato strips in oil (, chopped into 1.25 cm / 1/2\" pieces (reserve oil from jar for Dressing) (3 oz))","250g/8oz cherry tomatoes (, halved)","1/3 cup coriander/cilantro leaves (, roughly chopped)","200g/7 oz Danish feta (or Greek) (, crumbled)"],"purpose":"Salad (Note 2):"}]', '[{"title":"Dressing","description":"Shake ingredients in a jar to combine.","images":[],"step":1},{"title":"Toss","description":"Set aside a bit of coriander/cilantro and feta for garnish. Place all remaining salad ingredients into a big mixing bowl. Pour dressing over salad, and toss gently together to combine well. The feta will get a bit smeary - love it!","images":[],"step":2},{"title":"Serve","description":"Transfer to serving dish. Garnish with reserved feta and coriander/cilantro. Dig in!","images":[],"step":3}]', '[]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Western"],"categories":["beans-lentils","no-cook-food","quick-and-easy","salad-recipes-main-course","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_600b1b4235e2', 'en', 'US', 'Easy slow cooker BBQ pulled beef', 'Recipe video above. Make this when you want a big batch of succulent pulled beef smothered in an incredible homemade barbecue sauce, made using the convenience of a slow cooker. Pile into sliders, heap onto plates, stuff into baked potatoes. So many ways to enjoy it!Adapted from my Easy Slow Cooker BBQ pulled pork recipe. I don''t sear the pork before slow cooking, but it''s really worth searing the beef. I tried without and it was still great, but it''s noticeably better when you do. :)Easy to scale up - I can do a double batch in my slow cooker.', 'https://www.recipetineats.com/tachyon/2026/06/Easy-slow-cooker-BBQ-shredded-beef-8.jpg', 30, 620, 650, 8, '[{"id": "ing_beef", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.5, "unit": "bottle of 500ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_molasses", "quantity": {"value": 45.0, "unit": "jar"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 20.0, "unit": "bottle"}}, {"id": "ing_tabasco", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_green_onion", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["1.5 kg / 3 lb chuck beef (, cut into 4 thick steaks (Note 1))","1 cup beer (anything other than dark stouts like Guinness), or beef stock/broth, low sodium (Note 2)","3 tbsp olive oil (or other neutral oil, for searing)"]},{"ingredients":["3 tbsp (tightly packed) brown sugar","1 tbsp paprika powder (regular/sweet or smoked)","1 tbsp garlic powder","2 tsp onion powder","2 tsp mustard powder","1 tsp cumin powder","2 tsp cooking salt / kosher salt","1 tsp black pepper"],"purpose":"RUB:"},{"ingredients":["1 cup apple cider vinegar (Note 3)","3 cups tomato ketchup (or Aussie tomato sauce)","3 tbsp molasses (, orginal (not blackstrap, Note 4))","2/3 cup brown sugar","4 tsp mustard powder","3 tsp garlic powder","4 tsp Worcestershire sauce","2 tsp cooking salt / kosher salt","2 tsp black pepper","2 tsp Tabasco ( or cayenne pepper (optional, very faint background spiciness))"],"purpose":"BBQ Sauce:"},{"ingredients":["2 tbsp green onion (, finely sliced)"],"purpose":"Option garnish (for serving in bowl)"}]', '[{"description":"Mix BBQ sauce in slow cooker. Coat beef in Rub, sear. Deglaze pan with beer. Arrange beef in slow cooker, add beer, slow cook 10 hours. Shred, reduce BBQ sauce on stove, toss half with beef, serve rest on the side.","images":[],"step":1},{"title":"BBQ Sauce","description":"Put all the ingredients in a slow cooker and whisk to combine.","images":[],"step":2},{"title":"Season beef","description":"Mix the Rub together in a medium bowl. Dredge the steak in the Rub to coat on both sides.","images":[],"step":3},{"title":"Sear","description":"Heat half the oil in a large non stick pan over medium high heat. Brown 2 steaks for 1 - 1 1/2 minutes on each side until deep golden but take care not to burn the spice rub. Place in the slow cooker. Wipe the pan clean of black bits, heat the remaining oil and repeat with remaining 2 steaks.","images":[],"step":4},{"title":"Deglaze pan with beer","description":"Add the beer into the pan and let it simmer rapidly, scraping the base as you go, until it is reduced down to about 1/4 cup - about 3 minutes. Pour into the slow cooker.","images":[],"step":5},{"title":"Slow cook 10 hours","description":"Arrange the beef so each piece is as submerged as much as possible. Slow cook on low for 10 hours. The beef should be tender enough to easily shred.","images":[],"step":6},{"title":"Shred","description":"Remove the beef into a pan and shred with 2 forks.","images":[],"step":7},{"title":"Reduce sauce","description":"Pour the sauce from the slow cooker into a pot or large deep fry pan. Simmer on medium high for 15 to 20 minutes until thickened to a BBQ sauce consistency. Stir regularly towards the end and lower heat as needed if it starts to splutter aggressively.","duration":17.5,"images":[],"step":8},{"title":"Toss","description":"Pour about 1/3 to 1/2 the sauce over the beef and toss (use enough to moisten and flavour, but not make it soggy).","images":[],"step":9},{"description":"Serve the beef with remaining BBQ sauce. Use for sliders and sandwiches with Coleslaw for classic southern sliders (pictured), make plates with Corn bread, Mac and Cheese and corn on the cob on the side, stuff into baked potatoes. You just can''t go wrong however you serve it!","images":[],"step":10}]', '["mustard"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["BBQ","Southern","Texas","Western"],"categories":["beef","beef-recipes","mains","sandwiches-and-sliders","slow-cooked-fall-apart","slow-cooker-recipes","stews"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_de90de965662', 'en', 'US', 'Beef Rump Cap Roast (Picanha)', 'Recipe video above. Rump cap is considered by many to be the best cut for roast beef - prime rib quality without the price tag! But cook it wrong and it’s a chewy disaster. This recipe uses a safe, straightforward method that ends with pure roast beef bliss - edge-to-edge medium rare and a golden, crackly fat cap. Bonus: two new steak sauce obsessions provided! Chimichurri Butter plus a Roasted Garlic Butter (links in ingredient list)', 'https://www.recipetineats.com/tachyon/2025/11/Rump-cap-roast-picanha_1.jpg', 10, 90, 100, 8, '[{"id": "ing_beef_steak", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_chilli_flakes", "quantity": {"value": 0.625, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_classic_chimichurri", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_bearnaise_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_cafe_de_paris", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_mushroom", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_wine", "quantity": {"value": 1.0, "unit": "bottle of 750ml"}}, {"id": "ing_cream", "quantity": {"value": 0.004, "unit": "carton of 250ml"}}]', '[{"ingredients":["2 kg/ 4 lb beef rump cap / picanha ((more names: sirloin cap, coulette), silver skin trimmed off)","5 tsp sea salt flakes (or 3 1/2 tsp cooking salt / kosher salt - Note 2)","1/2 tsp black pepper"]},{"ingredients":["Chimichurri butter (pictured, stellar!)","Roasted Garlic Butter (pictured, current obsession!)","Classic Chimichurri","Bearnaise sauce","Cowboy butter","Cafe de Paris","Creamy mushroom sauce","My favourite Blue Cheese Sauce (page 330 of Dinner)","Red wine sauce (page 327 of Dinner)","Dijon mustard, wholegrain mustard, horseradish cream (good ones!)"],"purpose":"Sauce options:"}]', '[{"description":"Score fat (cut right in), rub meat with 2 tsp salt, and 3 tsp on fat cap. Roast on rack at 140°C/285°F (120°C fan) until the internal temperature is 48°C / 118°F (~70 minutes - 1 1/2 hrs). Rest 30 minutes, brown fat cap quickly under very hot oven grill/broiler (3 min max). Serve immediately!","images":[],"step":1},{"description":"Preheat the oven to 140°C/285°F (120°C fan-forced).","images":[],"step":2},{"title":"Dry","description":"Pat excess moisture off the surface of the rump cap with paper towels.","images":[],"step":3},{"title":"Score the fat cap with 2.5cm / 1\" diamonds","description":"cut well into the fat but don''t cut into the meat. (But not a disaster if you do, unlike pork crackling!)","images":[],"step":4},{"title":"Rub salt","description":"Rub the meat surface with 2 teaspoons of the salt and half the pepper (ie underside and sides). Then rub the remaining 3 teaspoons of salt and pepper into the fat cap.","images":[],"step":5},{"title":"Meat thermometer","description":"Place the beef on a rack set on a tray. Insert an oven-safe meat thermometer into the middle of the thickest part of the beef, if using.","images":[],"step":6},{"title":"Slow-roast","description":"Roast until the internal temperature is 48°C / 118°F, between 70 to 90 minutes (it varies! Note 3)","images":[],"step":7},{"title":"Rest","description":"Remove from the oven and leave on the counter for 30 - 40 minutes to rest (do not cover). The internal temperature will climb to 56°C / 132.8°F which is perfect medium rare. (Note 4 for other doneness)","duration":35,"images":[],"step":8},{"description":"Brown fat cap:","images":[],"step":9},{"title":"Preheat","description":"Halfway through the resting time, preheat the oven grill / broiler as high as it will go. Arrange the shelf so the surface of the fat cap will be 12cm / 5\" from the heat element.","images":[],"step":10},{"title":"Brown","description":"Grill rump cap for 2 - 3 minutes until the fat cap is golden and a bit crisp. Keep a close eye on it, it can burn quickly, and remove after 3 minutes even if not golden enough else you risk a band of overcooked beef.","duration":2.5,"images":[],"step":11},{"title":"Ready! The beef is ready to serve","description":"there is no need to rest again.","images":[],"step":12},{"description":"Slicing to serve:","images":[],"step":13},{"description":"Cut the beef thinly into 8mm / 1/3\" slices and serve with sauce of choice (you can go up to 1.25cm / 1/2\" if you have wagyu). Don''t be tempted to cut thick slices, this beef cut is not suitable for that! (Note 5 about grain direction)","images":[],"step":14}]', '["milk","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef","beef-recipes","iconic-dishes","mains","roast-beef","roasts","sunday-supper"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3c5b97ebc16f', 'en', 'US', 'Birria Tacos', 'Recipe video above. Birria Tacos - or Quesabirria - the legendary crispy red tacos stuffed with cheesy shredded beef dunked in rich consommé. This was a beast of a recipe to crack, so I’m thrilled we finally got there. What makes these special: specify chillies by weight not number, toss shredded beef in sauce, skim red-oil off to use for crisping tacos, and our consommé is not watery and thin, it''s a smidge thicker than usual so it clings better.These deliver big flavour with every single bite, the consommé is rich and full bodied with beefy chilli flavour, and wow the tacos are crisp! Important: Birria is very reliant on chillies for flavour. So if you don''t have scales for the chillies, deseed, chop, then measure using cups. Don''t rely on "2 anchos", they can vary so much in size.', 'https://www.recipetineats.com/tachyon/2025/09/Birria-tacos_4.jpg', 30, 180, 210, 22, '[{"id": "ing_chilli", "quantity": {"value": 0.25, "unit": "pack of 100g"}}, {"id": "ing_chilli", "quantity": {"value": 0.25, "unit": "pack of 100g"}}, {"id": "ing_chilli", "quantity": {"value": 0.25, "unit": "pack of 100g"}}, {"id": "ing_chilli", "quantity": {"value": 0.25, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.075, "unit": "L"}}, {"id": "ing_beef", "quantity": {"value": 1.3, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_bay_leaf", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.06, "unit": "bottle of 500ml"}}, {"id": "ing_salt", "quantity": {"value": 0.013, "unit": "kg"}}, {"id": "ing_tortillas", "quantity": {"value": 20.0, "unit": "pack of 8"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_cheese", "quantity": {"value": 3.5, "unit": "block of 250g"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_hot_sauce", "quantity": {"value": 1.0, "unit": "bottle of 150ml"}}]', '[{"ingredients":["25 g (0.9 oz) guajillo chillies, dried (~4 pieces, heaped 3/4 cup once chopped) (Note 1)","45 g (1.6 oz) ancho chillies, dried (~2-3 pieces, 1 cup once chopped) (Note 1)","6 g (0.2 oz) chillies de arbol, dried (~6 pieces, 2 tbsp once chopped) (Note 1)","1/2 cup chilli soaking water (reserve after simmering)","5 garlic cloves (, peeled)","1 small onion (, roughly sliced (~tennis ball size))","1 medium tomato (, roughly sliced (180g))","2 tsp dried oregano","1 tsp ground cumin","1/8 tsp black pepper"],"purpose":"Birria adobo (paste):"},{"ingredients":["5 tbsp vegetable oil (or canola oil) (Note 2)","1.3 kg/2.6 lb chuck beef (, cut into 6 large pieces (or boneless beef short ribs - 1.8kg/3.6 lb bone-in) (Note 3))","2 cups beef stock / broth (, low sodium)","10 cloves (or 1/4 tsp ground cloves)","1 cinnamon stick (substitute 1/4 tsp powder, but it''s not quite the same)","3 bay leaves (, preferably fresh else dried)","2 tbsp apple cider vinegar (or regular white vinegar, red or white wine vinegar)","2 1/2 tsp cooking salt / kosher salt (halve for table salt, +30% for flakes)"],"purpose":"Birria braising:"},{"ingredients":["1/2 tsp cooking salt / kosher salt"],"purpose":"Beef seasoning:"},{"ingredients":["20 - 25 corn tortillas (14.5cm/6\" wide) (Note 4)","1 white onion (, diced (Note 5))","1/2 cup finely chopped coriander / cilantro leaves","3 1/2 cups (350g) shredded Colby, Monterey Jack or (Oaxaca cheese (if you can get it) (Note 6))","Lime wedges (, optional)","Your favorite salsa or hot sauce (, optional)"],"purpose":"Birria Tacos:"}]', '[{"description":"Simmer chopped chillies 10 min. Strain, blitz Adobo paste. Brown beef, cook off adobo paste, slow-cook beef 2 1/2 hrs (lid on). Remove meat, shred, skim fat off braising liquid (\"Birria Oil\"). Toss beef in skillet with 1 cup braising liquid (aka Consomme). Heat 1 tsp Birria oil over low heat, wipe pan with tortilla, remove, repeat x2 with 1/2 tsp oil each. Top tortilla with cheese, beef, onion, coriander, fold over, pan fry until crisp. Serve with Birria Consomme for dunking!","images":[],"step":1},{"description":"Prepare chillis:","images":[],"step":2},{"description":"Use gloves if you''re sensitive to working with chilli!","images":[],"step":3},{"title":"Deseed","description":"Trim and discard stems. Cut lengthwise, remove and discard the seeds. Roughly chop into 1 - 1.5cm / 1/4\" pieces.","images":[],"step":4},{"title":"Simmer","description":"Put chillis in a large saucepan of boiling water. Simmer rapidly for 10 minutes to soften, until flesh is mushy (skin stays intact but softens).","duration":10,"images":[],"step":5},{"description":"Reserve 1/2 cup of chilli-simmering water. Drain chilli in a sieve, lightly press out residual liquid.","images":[],"step":6},{"title":"Birria Adobo (paste)","description":"Place cooked chillies, reserved 1/2 cup chilli water and remaining Adobo ingredients in a tall jug large enough to fit the head of a stick blender. Blitz for 20 seconds until as smooth as possible (it''s not completely smooth, see video). You can also do this in a small food processor, NutriBullet or blender (Note 7).","duration":0.3333333333333333,"images":[],"step":7},{"title":"Sear beef","description":"Heat the oil in a large heavy based pot over high heat (I use my 24cm / 9.6\" dutch oven). Add half the beef and sear each side aggressively until it''s dark golden brown (about 1 - 1 1/2 minutes each side). Remove to a bowl and repeat with remaining beef.","images":[],"step":8},{"title":"Cook off Adobo","description":"Add the paste to same pan and stir for 2 minutes in oil (lower heat if spitting aggressively).","duration":2,"images":[],"step":9},{"title":"Slow cook 2 1/2 hours","description":"Add all Birria braising ingredients, stir, then add the beef. Bring to a boil then lower heat until it''s simmering very gently (small gentle bubbles every now and then). Cover with a lid and cook for 2 1/2 hours, or until beef shreds easily (short ribs take 3 - 3.5 hrs). (Note 8 for slow cooker)","images":[],"step":10},{"title":"Shred","description":"Remove the beef to a clean pan and shred well. Add the 1/2 teaspoon of salt and toss meat to distribute.","images":[],"step":11},{"title":"Birria oil","description":"Skim off as much of the red oil floating on braising liquid surface as possible (ideally 6 tbsp+) and place in a separate bowl (this is the \"Birria Oil\"). Precious stuff!","images":[],"step":12},{"title":"Soak beef","description":"Pour 1 cup of the braising liquid (\"Birria Consommé\") into a large non-stick pan over medium-high heat. Let it simmer for 15 seconds, then add all the beef and toss in the sauce until it''s all absorbed by the beef, there should be almost none pooled in the pan. Move beef back into the shredding pan, scraping the non-stick pan clean.","duration":0.25,"images":[],"step":13},{"title":"Birria Consommé","description":"Taste and check for salt, add more if needed. It should be on the slightly salty side (because it''s used for dipping) but not too salty to drink a small cup like soup. Keep warm to use for dipping once tacos are done.","images":[],"step":14},{"title":"Red tortillas","description":"Heat 1 teaspoon Birria Oil in the same non-stick pan over medium-low heat. Put a tortilla in and \"wipe\" around to make the underside red. Once the tortilla is soft (no need to flip) - about 10 seconds - remove to a work surface red side down. Repeat twice more, heating 1/2 teaspoon Birria Oil for each tortilla.","images":[],"step":15},{"title":"Stuff","description":"Spread cheese on half of each tortilla, top with beef, then onion and coriander/cilantro.","images":[],"step":16},{"description":"Crisp! Fold over then pan-fry 3 Birria Tacos at a time (in the same pan) over medium-high heat for 2 minutes on each side, until golden-red and crispy.","duration":2,"images":[],"step":17},{"title":"Serve","description":"Remove and serve while hot with the Birria Consommé for dunking! (Drink leftover consommé, it might be the best soup broth you have this year).","images":[],"step":18}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["beef","beef-recipes","iconic-dishes","mains","mexican-recipes","slow-cooked-fall-apart","slow-cooker-recipes","taco-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f1acfebb1ff2', 'en', 'US', 'Tomahawk Steak', 'Recipe video above. Don’t cook a tomahawk steak entirely on the BBQ - you’ll end up with a thick, overcooked band! The best way is to use the reverse-sear method: oven first, then BBQ. It''s stress free and you''ll have blushing pink meat from edge to edge with a killer crust - steak perfection! All credit to J Kenji Lopez-Alt for popularising this now world renowned method which can be used for all thick cut steaks.No BBQ? See note 5 for the oven-only method.PS Please a meat thermometer to nail the doneness - this is not the time to guess.PPS Even if you overshoot to 60°C/140°F, it still eats like medium-rare. Also - see FAQ above for making stacks for a tomahawk party!', 'https://www.recipetineats.com/tachyon/2025/05/Tomahawk-steak-shoot-3_6-1.jpg', 5, 60, 80, 2, '[{"id": "ing_beef_steak", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_bearnaise_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_cafe_de_paris", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_mushroom", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chimichurri_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_wine", "quantity": {"value": 1.0, "unit": "bottle of 750ml"}}, {"id": "ing_mustard", "quantity": {"value": 0.005, "unit": "jar of 200g"}}]', '[{"ingredients":["1 tomahawk steak (1.2 - 1.5kg / 2.4 - 3lb) (Note 1)","2 tsp cooking salt/kosher salt","3/4 tsp black pepper","1 tbsp olive oil"],"purpose":"Tomahawk Steak"},{"ingredients":["Cowboy butter (pictured in post - Tomahawk worthy!)","Bearnaise sauce","Cafe de Paris","Creamy mushroom sauce","Chimichurri sauce","Blue cheese sauce (page 330 of Dinner)","Blue cheese sauce (page 330 of Dinner)","Dijon or seeded mustard"],"purpose":"Steak sauce options"}]', '[{"description":"Season, slow-roast on rack at 140°C/285°F (120°C fan) for 40-45 minutes to 50°C/122°F. Rest 10 minutes. Preheat BBQ until screaming hot, drizzle steak with oil, lower BBQ to low/med low and sear on hot BBQ 3 - 4 minutes on each side (temp 55°C (128°F)). Rest 3 minutes (temp rises to 57°C/135°F = perfect medium rare 🙌🏻). Slice, serve with Cowboy Butter!","duration":42.5,"images":[],"step":1},{"description":"Oven slow-roast:","images":[],"step":2},{"title":"De-chill","description":"Take the steak out of the fridge 1 hour prior to cooking. Remove from packaging and pat the surface dry. (Do not salt).","images":[],"step":3},{"description":"Preheat the oven to 140°C/285°F (120°C fan-forced).","images":[],"step":4},{"title":"Season","description":"Sprinkle the steak meat with salt and pepper, then use your hands to rub it in.","images":[],"step":5},{"title":"Slow(ish) roast","description":"Put the steak on a rack and set it on a baking tray. (Note 2) Bake for 40 to 45 minutes, or until the internal temperature is 50°C/122°F (for medium rare, see Note 3 for other doneness).","duration":42.5,"images":[],"step":6},{"title":"Rest","description":"Take the tray out of the oven and leave the steak on the counter for 10 minutes. (Internal temperature should rise by 3 degrees).","duration":10,"images":[],"step":7},{"description":"Preheat the BBQ on high until it''s screaming hot. Use the flat plate side if you''re not a confident BBQ''er, or the grill side if you''re a BBQ master. (Note 4)","images":[],"step":8},{"title":"Oil","description":"Drizzle the oil on the steak and lightly pat to spread (don''t rub off the salt), using most of the surface area of the meaty part.","images":[],"step":9},{"title":"Turn BBQ DOWN","description":"If using the grill side, reduce to low (if yours is strong, mine is) or medium low (for weaker ones). If using the flat plate side, lower to medium. Do this just before putting the tomahawk on.","images":[],"step":10},{"title":"Edges first","description":"Using tongs, hold the steak upright and sear the edges and bone first (only if you''ve got meat on it), rotating and moving every minute or so to achieve this all the way around. ⚠️Flare-ups – If searing on the grill side, don’t walk away - flare-ups are inevitable. See Note 4 for managing.","images":[],"step":11},{"title":"Steak crust","description":"Then place the steak down on the grill and cook for 3 to 4 minutes on each side, or until the internal temperature is 55°C / 131°F. For classic X grill lines, rotate once 45° partway through.","duration":3.5,"images":[],"step":12},{"title":"Rest the steak on a rack for 3 minutes","description":"the internal temperature will rise to 57°C/135°F which is perfect medium rare.","duration":3,"images":[],"step":13},{"title":"Serve","description":"Cut into 1 cm / 0.4\" thick slices. Serve with steak sauce of choice! (Pictured: Cowboy Butter, highly recommend!).","images":[],"step":14}]', '["milk","mustard"]', '["gluten_free","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef","beef-recipes","iconic-dishes","mains"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0e4199cee174', 'en', 'US', 'Beef in black bean sauce', 'Recipe video above. This incredible Beef in Black Bean Sauce recipe is from Hannah, a chef at our food bank RecipeTin Meals who was born and raised in China, and comes from a long line of chefs. I''ll wager this recipe beats any Chinese restaurant you’ve tried - even “fancy” city ones - and it is far, far cheaper. Made from scratch, it leaves jarred sauces in the dust. Shockingly easy!', 'https://www.recipetineats.com/tachyon/2025/04/Beef-in-black-bean-sauce_8.jpg', 20, 10, 90, 4, '[{"id": "ing_black_beans", "quantity": {"value": 0.188, "unit": "can of 400g"}}, {"id": "ing_beef_steak", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_oil", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.025, "unit": "pack of 400g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.006, "unit": "tub of 200g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_white_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1/2 cup (75g) preserved black beans (salted black beans, fermented black beans, Note 1)","400g/14 oz beef rump steak (US: top sirloin) (, thinly sliced 3mm / 0.1\" (Note 2))","1 brown onion (, medium size, cut into 2.5cm/1\" squares)","1 green capsicum ((bell pepper), medium size, cut into 2.5cm/1\" squares)","1 tbsp garlic (, finely minced with a knife ~ 4 cloves (Note 3))","1/2 cup peanut oil (or vegetable, canola) (Note 4)","1 tbsp Chinese cooking wine (shaoxing wine) (Note 5)"]},{"ingredients":["1 tbsp light soy sauce (Note 6)","1 tsp dark soy sauce (Note 6)","1 tbsp oyster sauce","2 tsp cornflour / cornstarch","1/4 tsp baking soda (bi-carbonate) (Note 7)","1 tbsp sesame oil (toasted ie brown, not untoasted which is yellow)"],"purpose":"Tenderising beef marinade:"},{"ingredients":["1 tbsp light soy sauce (Note 6)","2 tsp white sugar","2 tbsp cornflour/cornstarch (20g)","1 cup water"],"purpose":"Sauce:"},{"ingredients":["White rice"],"purpose":"Serving:"}]', '[{"description":"Abbreviated recipe:","images":[],"step":1},{"description":"Marinade beef 1 hour, soak beans, mix sauce. Shallow fry beef 30 seconds, remove. Discard all but 3 tbsp oil. Add and cook in this order: black beans 20 seconds, garlic 10 seconds, onion + capsicum 1 minute, beef 1 minute, cooking wine 30 seconds, sauce 1 minute or until thickened. Serve!","images":[],"step":2},{"description":"Mix the marinade ingredients EXCEPT sesame oil in a bowl. Add beef, mix to coat. Add sesame oil, mix again.","images":[],"step":3},{"title":"Marinade","description":"Refrigerate to marinade for 1 hour.","images":[],"step":4},{"title":"Soak beans","description":"Put the salted black beans in a medium bowl and cover with water. Set aside for 30 minutes to 1 hour to soak, then drain.","duration":30,"images":[],"step":5},{"title":"Mix sauce","description":"Put the cornflour, soy sauce and sugar in a jug or small bowl. Mix until lump free then mix in the water. Set aside.","images":[],"step":6},{"description":"Cooking:","images":[],"step":7},{"title":"Cook beef","description":"Heat the oil in a wok (or non stick pan) over high heat. Add the beef and cook, tossing, for 30 seconds until it changes from red to brown. Remove with a slotted spoon onto a plate.","duration":0.5,"images":[],"step":8},{"description":"Discard most of the oil in the wok, keep just 3 tablespoons.","images":[],"step":9},{"title":"Aromatics","description":"Return the wok to high heat. Add the black beans and stir for 20 seconds, then add the garlic and stir for 10 seconds. Add the capsicum and onion, cook for 1 minute.","duration":0.3333333333333333,"images":[],"step":10},{"title":"Beef","description":"Add beef and any juices pooled on the plate, toss for 1 minute. Pour the Chinese cooking wine around the sides of the wok so it runs down into the beef then toss for 30 seconds (Note 8)","duration":1,"images":[],"step":11},{"title":"Sauce","description":"Pour the sauce in, then stir and let it bubble for 1 minute or until the sauce thickens, is shiny and coats the beef beautifully.","duration":1,"images":[],"step":12},{"title":"Serve","description":"Pour into a serving bowl and serve with rice!","images":[],"step":13}]', '["gluten","peanuts","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["beef","beef-recipes","chef-hannahs-recipes","chinese-recipes","iconic-dishes","mains"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_31cea54aec7d', 'en', 'US', 'Thai Sweet Chilli Beef Bowls', 'Recipe video above. This quick dinner using beef mince channels Thai Chilli Basil stir fry vibes (but, no basil and not spicy) with poke bowl versatility (but, no pricey raw fish!). I use bottled sweet chilli sauce for simplicity instead of fresh chilli, garlic, sugar and thickener, and it works a treat. Plus, it''s more kid friendly because you can barely taste the spice.The key is the Sweet Chilli Drizzle Sauce! It adds flavor to the beef, rice, and veggies (raw or cooked). Jumble it all up and dig in!', 'https://www.recipetineats.com/tachyon/2024/12/Thai-sweet-chilli-beef-bowls_0.jpg', 13, 7, 20, 4, '[{"id": "ing_roasted_cashews", "quantity": {"value": 50.0, "unit": "jar"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_coriander", "quantity": {"value": 0.9, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.3, "unit": "pack of 100g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_steamed_or_veg", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["1/3 cup roasted cashews (, unsalted (or peanuts, Note 1))","1 tbsp canola oil (, or other plain cooking oil)","500 g / 1 lb beef mince (ground beef)","1 small onion (, finely chopped)","2 garlic cloves (, finely minced)","3 tbsp roughly chopped coriander/cilantro leaves (sub green onion)"]},{"ingredients":["2 tbsp sweet chilli sauce (I use Trident)","2 tbsp fish sauce (Note 2)","2 tbsp rice vinegar (sub cider vinegar)","1 tbsp oyster sauce (Note 3)","1 tbsp dark soy sauce (Note 3)"],"purpose":"Sweet chilli stir fry sauce:"},{"ingredients":["1 garlic clove (, minced using garlic crusher)","3 tbsp sweet chilli sauce","2 tbsp lime juice (sub rice vinegar when limes are crazy expensive)","2 tsp fish sauce (Note 2)"],"purpose":"Sweet chilli drizzle sauce:"},{"ingredients":["2 batches jasmine rice (or other plain rice of choice)","Steamed or fresh veg (Note 5) (pictured: chopped cucumber, coriander/cilantro, red onion finely sliced)"],"purpose":"Serving:"}]', '[{"description":"Abbreviated recipe","images":[],"step":1},{"description":"Mix each sauce. Toast cashews, sauté onion + garlic 1 min, then cook beef. Add sauce, cook until reduced/caramelised, serve over rice with veg on side. Spoon over drizzle sauce, top with cashews and coriander.","images":[],"step":2},{"title":"Drizzle sauce","description":"Mix the ingredients in a bowl, set aside.","images":[],"step":3},{"title":"Stir fry sauce","description":"Mix the ingredients in a separate bowl, set aside.","images":[],"step":4},{"title":"Toast cashews","description":"Heat a large non-stick pan over medium high heat. Add the cashews and toast for 2 minutes. Transfer to a cutting board then roughly chop once cool.","duration":2,"images":[],"step":5},{"title":"Cook beef","description":"Heat the oil in the same pan over high heat. Add the garlic and onion, cook for 1 minute. Add the beef and cook, breaking it up as you go, until you no longer see raw meat.","duration":1,"images":[],"step":6},{"description":"Sauce it! Add the cooking sauce and cook well, stirring, until it mostly reduces down so the sauce caramelises on the beef, about 3 - 4 minutes. (Don''t shortcut this step, it''s where the flavour is!)","images":[],"step":7},{"description":"Serve the beef over rice with a side of veg. Douse everything with the sauce, top with cashews and coriander (fresh chilli wouldn''t go astray either). To eat, jumble everything up then dig in!","images":[],"step":8}]', '["fish","gluten","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef","beef-mince-recipes","beef-recipes","dinner-tonight","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5732397bf16b', 'en', 'US', 'One Pot Cajun Beef Pasta with lots-of-veg', 'Recipe video above. A big bubbly beefy pasta in a Cajun flavoured tomato sauce, filled with lots of hidden vegetables, all made in one pot! Love that it''s a complete meal, and a great way to stretch 500g/1lb beef to serve more people with the bonus of a stack of "hidden" vegetables (carrot, zucchini ,zucchini, canned tomato and onion - yes, onion counts towards daily veg intake!).Leftovers are excellent! Fridge or freeze.', 'https://www.recipetineats.com/tachyon/2024/09/One-pot-Cajun-Beef-Pasta_0.jpg', 15, 25, 40, 7, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_zucchini", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_kidney_beans", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.7, "unit": "pack of 500g"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_paprika", "quantity": {"value": 0.562, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}]', '[{"ingredients":["1 tbsp olive oil","2 garlic cloves (, finely minced)","1 onion (, chopped)","500g/ 1 lb beef mince (ground beef) (Note 1)","1 carrot (, medium, shredded using box grater (I keep skin on) )","1 zucchini (, medium, shredded using box grater (Note 2))","1 red capsicum (bell pepper), chopped (Note 2)","2 tbsp tomato paste","800g/ 28 oz canned crushed tomato","400g/ 14 oz kidney beans (, drained (or other beans of choice, can omit))","2 cups chicken stock/broth (, low sodium (sub beef stock))","2 cups water (just regular tap water!)","350g / 12 oz (3 cups) elbow pasta (macaroni) (, spirals, penne, ziti, small shells, rigatoni or similar size, uncooked (Note 3))","1 1/2 cups (tightly packed) colby cheese (or other melting cheese of choice, preferably freshly shredded (melts better))","1 green onion stem (, finely sliced (optional garnish))"],"purpose":"One-pot pasta:"},{"ingredients":["1 1/2 tsp dried thyme","1 1/2 tbsp paprika (sweet/regular, not smoked or spicy)","2 tsp garlic powder","2 tsp onion powder","1/2 tsp cayenne pepper (, optional (faintly spicy))","1/4 tsp black pepper","1 1/4 tsp cooking salt / kosher salt"],"purpose":"Cajun spices:"}]', '[{"description":"Heat the oil in a large heavy based pot with a lid over high heat.","images":[],"step":1},{"title":"Cook vegetables","description":"Cook the onion and garlic for 2 minutes. Add the beef and cook, breaking it up as you go, until you no longer see red meat. Add the carrot and zucchini, cook for 2 minutes until the water they release mostly evaporates. Add the capsicum and cook for 2 minutes.","duration":2,"images":[],"step":2},{"title":"Spices","description":"Add the tomato paste and Cajun Spices. Cook for 1 minute.","duration":1,"images":[],"step":3},{"title":"Pasta sauce","description":"Add the canned tomato, water (I swill the cans clean), stock and beans. Mix and bring to a simmer.","images":[],"step":4},{"description":"Add the pasta, stir, let it come back up to the simmer. Put the lid on and lower the heat slightly to medium so the liquid is simmering (not bubbling madly).","images":[],"step":5},{"description":"Cook for 15 minutes, stirring every few minutes so the base doesn''t catch. The pasta should be a bit firmer than you want in the middle, and still a bit soupy which is good! Liquid gets absorbed in the next step.","duration":15,"images":[],"step":6},{"title":"Melt cheese","description":"Give it a stir, smooth the surface, sprinkle with cheese. Put the lid on then turn the stove off (leave the pot on the stove). Leave for 3 minutes so the residual heat melts the cheese and the pasta finishes cooking.","duration":3,"images":[],"step":7},{"title":"Serve","description":"Remove from the stove, sprinkle with green onion if desired, then serve immediately while saucy and the cheese is gooey!","images":[],"step":8}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef","beef-mince-recipes","beef-recipes","mains","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ac5f1a0b1b90', 'en', 'US', 'Beef Tenderloin with Creamy Mushroom Sauce', 'Recipe video above. This recipe uses a simple but highly effective, low-risk slow-roasting technique for evenly cooked tenderloin that''s blushing pink from edge to edge. No thick overcooked band!A slather of garlic-thyme-butter gives the beef a tasty crust, and the drippings from roasting are used to make a magnificent creamy mushroom sauce. Marsala, an Italian fortified wine you can pick up cheaply, is the secret ingredient in the sauce for a luxurious edge of flavour. But if you need to be alcohol free, see recipe notes.Please get a meat thermometer to take the guess work out! It''s far cheaper than the beef. (Note 4)PRO TIP: Season the beef the night before for best results. (Note 5)', 'https://www.recipetineats.com/tachyon/2023/12/Beef-tenderloin-with-mushroom-sauce_3.jpg', 15, 60, 75, 4, '[{"id": "ing_beef", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 75.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_mushroom", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_marsala", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}]', '[{"ingredients":["1 - 1.25kg/ 2 - 2.5lb centre cut beef tenderloin (eye fillet), tied (Note 1)","1 1/2 tsp cooking / kosher salt","1/2 tsp black pepper","1 tbsp vegetable oil"],"purpose":"Beef:"},{"ingredients":["75g/ 5 tbsp unsalted butter (, softened)","1 tsp garlic (, finely grated or very finely minced with a knife)","1 tsp fresh thyme leaves (, finely chopped (Note 2))","1/4 tsp cooking/kosher salt","1/4 tsp black pepper"],"purpose":"Garlic-Thyme-Butter-Slather:"},{"ingredients":["150g/5 oz white mushrooms (, sliced 3mm thick)","1/2 tsp garlic (, finely minced)","1 thyme sprig (Note 2)","3/4 cup marsala (, Italian fortified wine (Note 3))","1/2 cup chicken stock (, low sodium)","3/4 cup thickened cream (heavy cream)","1/4 tsp black pepper"],"purpose":"Creamy mushroom sauce:"}]', '[{"title":"Prep beef","description":"Pat beef dry with paper towels, sprinkle with salt and pepper all over. Place the beef on a rack on a tray then refrigerate uncovered 12 to 24 hours. (Can skip, Note 5)","images":[],"step":1},{"title":"Butter Slather","description":"Mix Butter Slather ingredients in a bowl.","images":[],"step":2},{"title":"De-chill","description":"Remove the beef from the fridge 2 hours prior to cooking. This helps the beef cook evenly.","images":[],"step":3},{"title":"Sear","description":"Heat oil in an ovenproof heavy based pan over high heat until smoking. (Note 6) Brown the surface of the beef all over, aggressively and quickly. Then put the beef back on the rack to cool for 15 minutes (so the butter doesn''t instantly melt when you put it on).","duration":15,"images":[],"step":4},{"description":"Preheat oven to 120°C/250°F (both fan and standard ovens) (Note 7).","images":[],"step":5},{"title":"Butter","description":"Put beef back in cooled skillet. Slather 3/4 of the butter onto the beef - top and sides (not underside).","images":[],"step":6},{"title":"Roast 40","description":"50 minutes - Roast for 15 minutes. Remove, slather remaining butter onto the top and sides. Roast for a further 25 - 35 minutes or until the internal temperature is 53°C/127°F for medium rare (Note 8 for other levels of doneness).","duration":15,"images":[],"step":7},{"title":"Rest & serve","description":"Remove beef from the skillet onto a cutting board and rest for 10 minutes. The internal temperature will rise 56-58°C / 133-136°F (this is medium rare). Slice thickly and serve with Creamy Mushroom Sauce!","duration":10,"images":[],"step":8},{"description":"Creamy mushroom sauce","images":[],"step":9},{"title":"Roasting juices","description":"Pour all juices in skillet into a bowl or jug. The fat will rise to the surface. Pour off 1/4 cup (60ml) of the fat back into the skillet (reserve the rest for later).","images":[],"step":10},{"title":"Cook mushrooms","description":"Turn the stove onto high. Once the butter is hot, add mushrooms and cook until they start to sweat. Then add thyme and garlic, and cook for a further 2 minutes until the mushrooms are softened.","images":[],"step":11},{"title":"Sauce","description":"Add chicken stock/broth and reduce by half. Add marsala, cream, pepper and remaining reserved roasting juices. Simmer on medium / medium high for 5 minutes until it reduces by half and the sauce is thickened. Taste - it should be slightly on the salty side (which will seem just right with each mouthful of beef). Add more salt if needed. Serve with beef.","duration":5,"images":[],"step":12}]', '["fish","milk"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef","beef-recipes","mains","roast-beef","roasts","sunday-supper"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_37e8be83e724', 'en', 'US', 'One pot creamy tomato beef pasta', 'Recipe video above. This is a beefy pasta cooked with Italian seasonings in a creamy tomato sauce. Epitome of homemade comfort food with the convenience of one-pot cooking! Love how the pasta absorbs the flavour of the sauce.For more, see the full One Pot Pasta recipe collection.', 'https://www.recipetineats.com/tachyon/2023/08/One-pot-creamy-tomato-beef-pasta_0.jpg', 10, 20, 30, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_italian_herbs", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.7, "unit": "pack of 500g"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 1/2 tbsp olive oil","2 garlic cloves (, finely minced)","1 onion (, finely chopped)","500g/ 1 lb beef mince / ground beef","2 tsp Italian herbs (Note 1)","2 tbsp tomato paste","400g/ 14 oz can crushed tomatoes (or tomato passata)","1/2 tsp red pepper flakes (chilli flakes, optional)","1 1/2 tsp cooking salt/kosher salt","1/2 tsp black pepper","4 cups (1 L) chicken stock/broth (, low sodium (Note 2))","350g/ 12oz fusilli, penne, elbow macaroni ( or other short pasta (Note 3))","3/4 cups thickened / heavy cream"]},{"ingredients":["Parmesan cheese (, finely grated)","Parsley (, finely chopped, optional)"],"purpose":"Serving:"}]', '[{"title":"Sauté","description":"Heat the oil on high heat in a large heavy-based pot. Cook garlic and onion for 1 1/2 minutes.","images":[],"step":1},{"title":"Cook beef & seasonings","description":"Add beef and cook, breaking it up as you go, until you can no longer see red meat. Add the Italian herbs and cook for 30 seconds, then add tomato paste and cook for 1 minute to cook out the raw flavour.","duration":0.5,"images":[],"step":2},{"title":"All in","description":"Add crushed tomato, chicken stock, salt, pepper and red pepper flakes, if using. Stir, then add the pasta.","images":[],"step":3},{"title":"Cook 15 min","description":"Bring the liquid to a simmer, then cook for 15 minutes, stirring every couple of minutes then more frequently towards the end (ensure pasta doesn''t stick to base) until the pasta is just about cooked.","duration":15,"images":[],"step":4},{"title":"Creamy","description":"Add cream, then simmer for a further 1 to 2 minutes. It will still be quite saucy - this is what you want! Pasta absorbs liquid quickly, so it will still be nice and oozy when you start eating.","images":[],"step":5},{"title":"Serve","description":"Remove from the stove. Give it a good stir then ladle into bowls. Serve with parmesan and parsley.","images":[],"step":6}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["beef","beef-mince-recipes","beef-recipes","dinner-tonight","mains","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5231f7ba1735', 'en', 'US', 'Crispy Lebanese Meat Stuffed Pita - Arayes', 'Recipe video above. Lebanese street food - pita bread stuffed with spiced kofta meat, pan fried until crispy! Think of these as Lebanese quesadillas or easy Gozleme. :) The unique method here is that it''s cooked with raw meat inside, so the tasty meat juices soaks into and flavours the pita bread as it cooks. It''s outrageously delicious. I bet you become as obsessed with these as I have!', 'https://www.recipetineats.com/tachyon/2023/07/Arayes_2-close-up.jpg', 15, 15, 30, 10, '[{"id": "ing_bread", "quantity": {"value": 5.0, "unit": "loaf"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.3, "unit": "tub of 500g"}}, {"id": "ing_tahini", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}]', '[{"ingredients":["5 pita bread (, the thin pocket type, ~15cm/6\" diameter (250g/8oz pack), cut in half (Note 1))","Olive oil spray (or brush with olive oil)"]},{"ingredients":["1/2 brown onion","500g/ 1 lb lamb or beef mince (ground meat) (Note 2)","2 garlic cloves (, finely grated)","1 tbsp finely chopped parsley (, optional)","3 tsp ground coriander","3 tsp ground cumin","1 1/2 tsp smoked paprika (sub plain paprika)","3/4 tsp ground allspice (sub mixed spice)","1/2 tsp cayenne pepper (reduce/omit for less spicy - Note 4)","1 1/4 tsp cooking/kosher salt"],"purpose":"Spiced meat filling:"},{"ingredients":["1 cup plain yogurt","2 tbsp tahini (or Chinese sesame paste - Note 5)","1 tbsp lemon juice","1 garlic clove (, finely grated)","1/2 tsp cooking/kosher salt"],"purpose":"Whipped tahini yogurt sauce:"}]', '[{"description":"Spiced meat filling:","images":[],"step":1},{"description":"Grate the onion in a bowl using a standard box grater. We want the juices and all! (Note 4)","images":[],"step":2},{"title":"Meat filling","description":"Add remaining meat filling ingredients. Mix well with your hands.","images":[],"step":3},{"description":"Divide stuffing in 10 (about 55 to 60g per portion, 1/4 cup). Flatten into a semi-circle shape slightly smaller than the pita bread half.","images":[],"step":4},{"title":"Stuff","description":"Gently open a pita then place the meat inside. Close, then press to spread to the edge and make it fairly evenly flat. (Is your pita tearing? See Note 5 for tip!)","images":[],"step":5},{"description":"Cooking Arayes:","images":[],"step":6},{"description":"Preheat oven to 50C/120F. Place a rack on a tray. (To keep cooked Arayes warm.)","images":[],"step":7},{"title":"Cook","description":"Heat a large frying pan over medium high heat. Spray both sides of the pita with olive oil then place 2 or 3 pieces in the pan (whatever you can fit). Cook for about 2 minutes on each side, pressing down lightly with a spatula, until golden and crispy. The meat is spread so thin it cooks really quickly! {Sandwich press - Note 7}","images":[],"step":8},{"title":"Keep warm","description":"Transfer cooked Arayes onto the rack and put in the oven to keep warm. Cook remaining pita.","images":[],"step":9},{"title":"Serve","description":"Cut in half if desired (sometimes I do, sometimes I don''t!). Pile Arayes onto a serving platter. Serve with Whipped Tahini sauce. Enjoy!","images":[],"step":10},{"description":"Whipped tahini sauce:","images":[],"step":11},{"description":"Place ingredients in a heatproof bowl and whisk to combine. Microwave for 15 seconds on high. Whisk again - it should resemble soft whipped cream. Use slightly warm or at room temperature.","duration":0.25,"images":[],"step":12}]', '["gluten","milk","sesame"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["lebanese","Middle Eastern"],"categories":["beef","beef-mince-recipes","beef-recipes","cuisines","lamb","mains","middle-eastern-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c74153ab432e', 'en', 'US', 'Saltimbocca', 'Recipe video above. This rustic Italian classic is fabulously quick to make thanks to thin slices of veal that cook in 2 1/2 minutes flat. Traditionally made with veal, Saltimbocca is also excellent with chicken or beef. The trick to a great Saltimbocca sauce is to slowly melt in cubes of cold butter by swirling the pan off the heat. This thickens the sauce and makes it luxuriously silky. It''s a stunner! Serve with mashed potato, cauliflower mash or mop your plate clean with bread.', 'https://www.recipetineats.com/tachyon/2022/09/Veal-saltimbocca_6.jpg', 7, 5, 12, 2, '[{"id": "ing_beef_steak", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_sage", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_prosciutto", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_wine", "quantity": {"value": 0.083, "unit": "bottle of 750ml"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2 x 80g / 3 oz thin veal steaks or boneless cutlets","1/4 tsp black pepper","4 large sage leaves","4 prosciutto slices (finely sliced, Note 2)","2 tbsp flour (plain/all-purpose)","2 tbsp olive oil"]},{"ingredients":["50 g / 3 tbsp COLD unsalted butter (, cut into 1cm / 1/3\" cubes (Note 3))","1/4 cup white wine (, pinot grigio or chardonnay (Note 4))","Small pinch of salt"],"purpose":"Saltimbocca Sauce:"}]', '[{"description":"Prepare saltimbocca:","images":[],"step":1},{"title":"Pound","description":"Place the veal between sheets of cling wrap or paper. Pound to an even 3mm thickness using a meat mallet (Note 5 for tips!) Cut each piece in half so you have 4 pieces in total, and sprinkle both sides with pepper.","images":[],"step":2},{"title":"Prosciutto and sage","description":"Fold a slice of prosciutto in half then place on one piece of veal (trim if needed so it''s not hanging off the sides too much). Place a sage leaf on top then secure with a toothpick, piercing from the underside (see step photos or video). Do the same with the other piece of veal.","images":[],"step":3},{"title":"Dust","description":"Spread flour on a plate. Press the non-prosciutto side of the veal into the flour, shaking off excess (do not flour the prosciutto side).","images":[],"step":4},{"description":"Cook:","images":[],"step":5},{"title":"First side 1 1/2 minutes","description":"Heat oil in a large fry pan over medium-high heat. Place veal slices in the pan, prosciutto-side down, and cook for 90 seconds until prosciutto is beautifully golden.","duration":1.5,"images":[],"step":6},{"description":"Other side 1 min:Turn veal and cook the other side for 1 minute. Remove to a warm plate.","duration":1,"images":[],"step":7},{"description":"Tip out excess oil (do not scrape pan clean however). Return skillet to stove, with heat still on.","images":[],"step":8},{"title":"Reduce wine","description":"Pour in wine (careful, it will be steamy!) plus pinch of salt. Bring to a simmer then let it cook for 20 to 30 seconds, stirring to scrape up the brown fond from the base of the pan, until wine is reduced by half.","duration":0.4166666666666667,"images":[],"step":9},{"title":"Swirl butter","description":"Keep the pan on the stove but turn the stove OFF. Scatter the butter in the pan then swirl (or stir) until it melts. The clear liquid will thicken magically into a luscious butter sauce!","images":[],"step":10},{"description":"Serve:","images":[],"step":11},{"description":"Divide veal between plates. Spoon over sauce. Devour! (Careful of the toothpick!)","images":[],"step":12}]', '["gluten","milk"]', '["high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["beef","chicken-breast-recipes","italian-recipes","mains","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_009c06f39fc0', 'en', 'US', 'Family Meat Pie', 'Recipe video above. Aussies love a good meat pie. We love the hand-held ones because we get the whole thing to ourselves. But when you''ve got sharing vibes, this Family-size Meat Pie is the one you pull out. Shortcrust base, slow cooked fall-apart chunks of beef smothered in a rich gravy with a golden puff pastry lid.It''s knee-shatteringly good comfort food!Workflow - I usually make the filling the day before, then refrigerate overnight. Then I do everything else on the day of serving.', 'https://www.recipetineats.com/tachyon/2021/09/Meat-Pie-Family-Size_39-new.jpg', 20, 240, 440, 6, '[{"id": "ing_beef", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 0.625, "unit": "pack of 200g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_guinness", "quantity": {"value": 330.0, "unit": "unit"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_quantity_shortcrust_pastry", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_sheet_puff_pastry", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["800g/ 1.6lb chuck beef (, 3.5cm/1.4\" cubes (Note 1))","3/4 tsp salt","1/2 tsp pepper","2 tbsp olive oil (, plus more as needed (or vegetable or canola))"],"purpose":"Beef:"},{"ingredients":["30g / 2tbsp unsalted butter","200g / 7 oz mushrooms (, smallish, halved (larger ones quartered))","125g / 4 oz streaky bacon (, cut into 1 x 1.5cm / 0.4 / 0.6\" cubes)","1 onion (, cut into 2cm / 0.8\" cubes)","2 garlic cloves (, minced)","1 celery (, cut into 1cm/0.4\" slices (split wide end of celery lengthwise, don’t want giant celery chunks))","1 carrot (, halved, 1cm/0.4\" slices (quarter very thick end if needed))","330ml / 11 oz Guinness (Note 2)","2 cups beef stock (, homemade or store bought low sodium (Note 3))","1 cup water","1/4 tsp salt","3/4 tsp coarsely crushed black pepper (, plus more as desired)"],"purpose":"Filling:"},{"ingredients":["4 tbsp flour","60g / 4 tbsp unsalted butter (, softened)"],"purpose":"Beurre Manié (sauce thickener, Note 4)"},{"ingredients":["1 quantity shortcrust pastry","1 sheet puff pastry (, for lid (Note 6))","1 egg (, lightly whisked)"],"purpose":"Pastry:"},{"ingredients":["Ketchup or Aussie Tomato Sauce (, for serving)"],"purpose":"Serving:"}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan).","images":[],"step":1},{"title":"Brown beef","description":"Sprinkle beef with 3/4 tsp salt and 1/2 tsp pepper. Heat oil in a large heavy based pot over high heat. Brown beef aggressively in 2 to 3 batches (do not crowd pot, else it gets watery instead of browning). Then remove beef into a big bowl.","images":[],"step":2},{"title":"Wipe down pot","description":"Wipe pot clean of burnt bits, if needed.","images":[],"step":3},{"title":"Cook bacon","description":"Cool pot, add bacon. Place pot back onto medium heat. When you see some fat starting to melt, turn heat up to medium high and cook bacon until golden. Then remove into bowl with beef.","images":[],"step":4},{"title":"Cook mushrooms","description":"Melt 30g/ 2tbsp butter in the pot. Cook mushrooms until golden with a pinch of salt and pepper. Remove into separate bowl with slotted spoon.","images":[],"step":5},{"title":"Cook other vegetables","description":"Add onion, garlic, carrot and celery then cook for 5 minutes until onion is soft and sweet, not too golden. Add oil if needed, but bacon fat + residual butter should be enough.","duration":5,"images":[],"step":6},{"title":"Oven slow cook","description":"Add beef, bacon, Guinness, water, stock, 1/4 tsp salt and 3/4 tsp pepper. Stir then bring to simmer. Cover with lid, then transfer to oven for 1 hour.","images":[],"step":7},{"description":"Add mushrooms, then continue cooking in the oven for a further 1 hour. Meat should be starting to be tender at this stage.","images":[],"step":8},{"description":"Thicken Sauce and Cool:","images":[],"step":9},{"title":"Stove reduce","description":"Remove pot from oven. Remove lid, then simmer on low heat for 20 minutes to reduce sauce. Meat should now be \"fall-apart-tender\" but just holding form (not disintegrating).","duration":20,"images":[],"step":10},{"title":"Sauce thickener (Beurre Manié","description":"Note 4): Mix together butter and flour until smooth.","images":[],"step":11},{"title":"Thicken sauce","description":"Stir Beurre Manié into sauce. Once melted, leave on the stove for another 2 minutes. Sauce should be thicker than a normal stew, like a honey consistency. Sauce will not thicken any more in oven, so make it exactly what you want - Note 7. Also, there will be more sauce than you expect for a pie - some gets absorbed by pastry (but won''t make it soggy).","images":[],"step":12},{"title":"Cool","description":"Cover pot with lid, then let it cool completely, preferably overnight. (Note 8)","images":[],"step":13},{"description":"Assemble and bake:","images":[],"step":14},{"title":"Shortcrust base","description":"Make and blind bake Shortcrust Pastry per that recipe using a 23cm/9” pie dish, whether using homemade or store bought. Then let it cool for at least 15 minutes (stays crispier).","images":[],"step":15},{"title":"Preheat oven","description":"Turn oven up to 200°C/390°F (180°C fan).","images":[],"step":16},{"title":"Fill pie","description":"Bring filling to room temp, do not use fridge cold. (Note 9) Fill pie with filling (use it all, pack it in a level surface or have slight mound).","images":[],"step":17},{"title":"Puff pastry lid","description":"Partially thaw puff pastry (do not cut). Brush lip of pie crust base with egg, then top with puff pastry sheet. Trim excess with scissors, press to adhere to edges. Then press the tip of a fork around the edge to make little crimps (to further adhere + decorative).","images":[],"step":18},{"title":"Egg wash","description":"Brush top with remaining whisked egg, then make a 2.5cm / 1\" X incision in middle to allow steam to escape (stops lid doming).","images":[],"step":19},{"title":"Bake: Bake 45","description":"50 minutes until top is super golden. Rest 5 minutes. Brag in comments below that you made this magnificent pie. Save Nagi a slice. Then serve remainder with ketchup or Aussie tomato sauce!","images":[],"step":20}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Australian"],"categories":["beef","beef-recipes","casseroles-and-cosy-bakes","mains","quiches-tart-and-pie-recipes","slow-cooked-fall-apart","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a7e5f4b903d8', 'en', 'US', 'Café de Paris - Steak butter sauce', 'Recipe video above. Café de Paris is a butter for steak flavoured with a mix of herbs, spices and savoury condiments. Despite the name, it originates from Switzerland, popularised by a restaurant called "Café de Paris". Now a staple steak sauce around the world (including in Paris!), slices of this compound butter are placed on hot steaks so they melt to form a butter sauce. It''s so simple, yet so incredibly good!Makes enough for 4 to 6 steaks, depending on how much butter you want on your steaks. Keeps for 2 months in the fridge, also excellent over seafood, poultry and hot steamed veg!', 'https://www.recipetineats.com/tachyon/2021/08/Cafe-de-Paris-butter-for-steak_19.jpg', 10, 0, 10, 4, '[{"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_fish_fillets", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_paprika", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_tarragon", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_beef_steak", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_beef_steak", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}]', '[{"ingredients":["100g / 7 tbsp unsalted butter (, softened)","2 tbsp eschalot (small), very finely chopped (Note 1)","1 garlic (, finely minced)","3 anchovy fillets (, finely chopped (Note 2))","1 tsp lemon juice","1 tsp Worcestershire sauce","1 tsp Dijon mustard","1 tsp curry powder (mild, Note 3)","1/2 tsp paprika (plain or sweet, not smoked or spicy)","1 tsp kosher / cooking salt","2 tsp tarragon (, finely chopped (Note 4))","2 tsp parsley (, finely chopped)"]},{"ingredients":["Steaks of choice (Note 5)","1/2 tsp cooking/kosher salt per steak","1/4 tsp black pepper per steak","1 tbsp vegetable or canola oil"],"purpose":"Steak:"}]', '[{"description":"Café de Paris butter:","images":[],"step":1},{"description":"Place ingredients in a bowl and mix to combine.","images":[],"step":2},{"description":"Place on cling wrap and roughly shape into a 20cm / 8\" log using spatulas or butter knives.","images":[],"step":3},{"description":"Roll up, then twist ends tightly. As you tighten the ends, the butter will shape into a neat, firm log.","images":[],"step":4},{"description":"Tie ends if needed to keep the shape. Refrigerate for 3 hours or until firm.","images":[],"step":5},{"title":"To use","description":"Slice into 0.7cm (1/3\") slices, then let them soften to room temperature (so they melt easier). Place on hot steak so it melts - I use 2 slices each steak. Leftovers - fridge 3 days or freeze 2 months (pre sliced for ease of use).","images":[],"step":6},{"description":"Cooking Steak:","images":[],"step":7},{"description":"Cooking Steak:","images":[],"step":8},{"title":"Bring to room temp","description":"Take the steak out of the fridge 30 minutes prior to cooking.","images":[],"step":9},{"title":"Dry","description":"Pat steaks dry with paper towels.","images":[],"step":10},{"title":"Heat skillet","description":"Heat oil in a heavy based skillet over high heat until it is very hot - you should see smoke!","images":[],"step":11},{"title":"Season","description":"Sprinkle each side of the steak generously with salt and pepper, then immediately place in the skillet.","images":[],"step":12},{"title":"Cook steak to taste","description":"For 2cm (3/4\") thick steaks, cook the first side for 2 minutes, then turn and cook the other side for 2 minutes (medium rare 52°C/125°F, chart below for other doneness temps).","duration":2,"images":[],"step":13},{"title":"Rest","description":"Transfer steaks to a warm plate, cover loosely with foil and rest for 5 to 10 minutes, then serve.","duration":7.5,"images":[],"step":14},{"description":"Cooking Steak:","images":[],"step":15},{"title":"Leftovers","description":"fridge 3 days or freeze 2 months (pre sliced for ease of use).","images":[],"step":16}]', '["fish","milk","mustard"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["French"],"categories":["beef","beef-recipes","mains","quick-and-easy","sauces"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_751a5c03d295', 'en', 'US', 'Mexican Meatballs', 'Recipe video above. The best Mexican Meatballs are spiced with Mexican flavours and made with:1. crushed corn chips instead of breadcrumbs (more flavour!);2. a combination of beef AND pork (softer and tastier); and3. are browned in the oven then simmered in the chipotle tomato sauce for a winning flavour exchange: meatball juices leech into the sauce, and the meatballs absorb the sauce flavour. Win win!Spiciness: Chipotle powder and fresh jalapeno in meatballs gives it a warm buzz but definitely not spicy. Same for chipotle chilli in sauce. Feel free to reduce both and add a pinch of paprika in its place.', 'https://www.recipetineats.com/tachyon/2021/06/Mexican-Meatballs_5.jpg', 20, 25, 45, 4, '[{"id": "ing_beef_mince", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_pork_mince", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_corn", "quantity": {"value": 0.125, "unit": "can of 400g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_coriander", "quantity": {"value": 0.9, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 0.9, "unit": "bunch"}}, {"id": "ing_jalape_o", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_cumin", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_chipotle", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.9, "unit": "bunch"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_chipotle_from_a_can_of_chipotle_in_adobo", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_adobo_sauce_from_a_can_of_chipotle_in_adobo", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.9, "unit": "bunch"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_guacamole", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_rice", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["250g / 8oz beef mince (ground beef)","250g / 8oz pork mince (ground pork), or more beef (Note 1)","1/2 red onion (, grated using a standard box grater)","50g / 1.75 oz plain corn chips (, sub breadcrumbs + 1/4 tsp salt (Note 2))","1 egg","3 tbsp coriander/cilantro (, finely chopped (sub chives or parsley))","3 tbsp parsley (, finely chopped (optional))","2 tsp fresh jalapeño (, seeds removed and finely minced (reduce/omit for not spicy))","Oil spray (preferably olive oil)"],"purpose":"Meatballs:"},{"ingredients":["1 1/2 tsp ground cumin","1 tsp chipotle powder (, sub more smoked paprika, reduce for less spicy (Note 3))","1 tsp coriander powder","1 tsp garlic powder (sub 1/2 fresh garlic clove, finely grated)","1/2 tsp paprika (, hot for spicy or sweet for not (or sub more Chipotle powder))","1 tsp salt","1/2 tsp black pepper"],"purpose":"Meatball Mexican Spices:"},{"ingredients":["2 tbsp olive oil","2 cloves garlic (, finely minced)","1 chipotle from a can of Chipotle in Adobo (, finely chopped - add another for extra flavour! (Note 4))","1 tsp Adobo Sauce from a can of Chipotle in Adobo (Note 4)","800g / 24 oz crushed tomato","1 tsp sugar","1 tbsp coriander/cilantro (, roughly chopped)"],"purpose":"Chipotle Sauce:"},{"ingredients":["Coriander/cilantro leaves (, whole)","Shredded cheese","Sour cream","Guacamole (or just diced, sliced or mashed plain avocado)","Rice, for serving ((Note )"],"purpose":"Toppings & garnishes (pick & choose):"}]', '[{"description":"Preheat oven to 220°C/390°F (200°C fan). Place a rack over a tray. Spray rack with oil.","images":[],"step":1},{"title":"Blitz corn chips","description":"Place corn chips in a Nutribullet or food processor. Blitz until they become fine crumbs. (Else put in a ziplock bag and bash!)","images":[],"step":2},{"title":"Meatball mixture","description":"Place meatball ingredients and meatball Mexican spices in a bowl and mix well with your hands.","images":[],"step":3},{"title":"Roll meatballs: Roll into 3","description":"3.5cm / 1.2 - 1.4\" balls. Place on rack. Should make around 20 - 24 meatballs.","images":[],"step":4},{"title":"Bake 10 minutes","description":"Spray meatballs generously with oil. Bake 10 minutes until browned (they will still be raw inside, we finish cooking them in the sauce).","images":[],"step":5},{"description":"While the meatballs are in the oven, start the sauce.","images":[],"step":6},{"title":"Sauté garlic and chipotle","description":"Heat oil over medium high heat in a large skillet. Add garlic and cook for 30 seconds. Add chopped Adobo Chile and sauté for 20 seconds.","duration":0.5,"images":[],"step":7},{"title":"Simmer 5 minutes","description":"Add tomato, Adobo sauce and sugar. Bring to simmer, then turn heat down to low and cook, stirring every now and then, for 5 minutes.","duration":5,"images":[],"step":8},{"description":"Finish Meatballs:","images":[],"step":9},{"title":"Cook meatballs in sauce","description":"Remove meatballs from oven and transfer into sauce. Continue to cook the sauce for another 10 minutes, rolling meatballs every now and then, until the sauce is thickened and the meatballs are cooked.","images":[],"step":10},{"title":"Fresh coriander","description":"Sprinkle with chopped coriander/cilantro.","images":[],"step":11},{"title":"Serving","description":"Serve over rice or stuff into tortillas with toppings of choice!","images":[],"step":12}]', '["egg","milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Mexican","Tex-Mex"],"categories":["beef","beef-mince-recipes","beef-recipes","mains","meatball-recipes","mexican-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c72d597383e7', 'en', 'US', 'Beef Bourguignon (Beef Burgundy)', 'Recipe video above. Considered by many to be the mother of all stews, Beef Bourguignon is a French dish made with beef, bacon lardons, carrots, onions and mushrooms slow-cooked in a rich red wine sauce. For the most magnificent stew of your life, start this 2 days before you plan to serve it, do not shortcut pan roasting ingredients individually, and use homemade beef stock if you can!', 'https://www.recipetineats.com/tachyon/2021/02/Beef-Bourguignon_7.jpg', 40, 150, 190, 5, '[{"id": "ing_beef", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 2000.0, "unit": "pack of 1kg"}}, {"id": "ing_onion", "quantity": {"value": 16.0, "unit": "pack of 1kg"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 0.12, "unit": "bunch"}}, {"id": "ing_wine", "quantity": {"value": 1.0, "unit": "bottle of 750ml"}}, {"id": "ing_oil", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 0.75, "unit": "pack of 200g"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.09, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["800g/ 1.6 lb chuck beef (, cut in 4-5 cm / 2” cubes (Note 1))","2 large carrots ((~300g/10oz), cut on an angle into 4-5 cm / 2” pieces)","16 pearl onions or small, round pickling onions (Note 2)","1 bay leaf (, fresh (sub: dried))","3 sprigs thyme","750ml/ 25 oz pinot noir or other red wine (Note 3)"],"purpose":"Beef marinade:"},{"ingredients":["3 tbsp oil (, olive, canola or vegetable)","3/4 tsp salt","1/2 tsp pepper"],"purpose":"Browning beef:"},{"ingredients":["200g/ 7oz mushrooms (, halved (quarters if large))","150g/ 5oz bacon piece (, cut into 1cm / 1/2” thick batons (Note 4))","50g/3 tbsp unsalted butter","3 garlic cloves (, minced)","2 tbsp tomato paste","6 tbsp flour (, plain/all purpose)","3 cups beef stock (low sodium)","1/4 tsp salt","2 tbsp chopped parsley (, for garnish)"],"purpose":"Stew:"}]', '[{"title":"Marinate beef","description":"Place the Beef Marinade ingredients in a large, non-reactive ceramic dish or ziplock bag. Marinate overnight in the fridge (minimum 12 hours, maximum 24 hours).","images":[],"step":1},{"description":"Strain liquid into a bowl, reserve marinade. Separate the beef, carrots and onion.","images":[],"step":2},{"title":"Reduce wine","description":"Pour red wine into a saucepan and bring to a boil over medium high heat. Simmer vigorously, skimming off any impurities that rise to the surface, until reduced by half. Set aside.","images":[],"step":3},{"description":"Brown beef and vegetables:","images":[],"step":4},{"description":"Preheat oven to 180°C / 350°F (160°C fan).","images":[],"step":5},{"title":"Dry beef","description":"Line a tray with paper towels, spread beef out, then pat dry with paper towels.","images":[],"step":6},{"title":"Season beef","description":"Sprinkle beef with 3/4 tsp salt and 1/2 tsp black pepper.","images":[],"step":7},{"title":"Brown beef","description":"Heat 2 tbsp oil in a large, heavy-based, oven-proof pot over high heat. Add 1/3 beef and brown aggressively all over. Remove into bowl, then repeat with remaining beef, adding more oil if needed.","images":[],"step":8},{"title":"Fry bacon","description":"Add bacon and cook for 3 minutes until golden. Add to bowl with beef.","duration":3,"images":[],"step":9},{"title":"Sauté mushrooms","description":"Add mushrooms and cook for 5 minutes, or until golden. Remove into a new bowl.","duration":5,"images":[],"step":10},{"title":"Sauté onion","description":"Add a bit of extra oil if needed, then cook onions for 5 minutes or until there are nice golden patches. Add to bowl with mushrooms.","duration":5,"images":[],"step":11},{"title":"Sauté carrot","description":"Add butter into pot. Once melted, add carrot and cook for 3 - 4 minutes until there are golden patches. Add garlic and cook for a further 1 minute.","duration":3.5,"images":[],"step":12},{"title":"Tomato paste","description":"Add tomato paste and cook for 2 minutes.","duration":2,"images":[],"step":13},{"title":"Flour","description":"Add flour and cook for 2 minutes.","duration":2,"images":[],"step":14},{"title":"Add wine and stock","description":"While stirring, slowly pour in beef stock – this helps the flour dissolve lump-free into the stock. Then add wine and mix until flour mixture is dissolved and mostly lump-free (Note 6).","images":[],"step":15},{"title":"Add beef into pot","description":"Add beef, bacon, thyme, bay leaf, 1/4 tsp salt and pepper into the pot, then stir well.","images":[],"step":16},{"description":"Slow-cook:","images":[],"step":17},{"title":"Oven 1 hour","description":"Bring to a simmer, then cover and transfer to oven for 1 hour. (Note 7)","images":[],"step":18},{"title":"Mushrooms and onion","description":"Remove from oven, stir in mushrooms and onion.","images":[],"step":19},{"title":"Oven 1½ hours","description":"Cover with lid and return to oven for 1½ hours, or until beef is \"fall-apart tender\".","images":[],"step":20},{"title":"Adjust salt","description":"Remove from oven, taste sauce and add salt if needed. (Note 8 - important!)","images":[],"step":21},{"title":"Leave overnight (recommended)","description":"If time permits, leave the stew overnight before serving because as with all stews, it gets better with time! Reheat gently on a low stove.","images":[],"step":22},{"title":"Serve over mashed potato","description":"Essential for mopping up every drop of that amazing sauce!","images":[],"step":23}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["French"],"categories":["beef","beef-recipes","iconic-dishes","mains","stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8d6676aa595a', 'en', 'US', 'Caramelised Vietnamese Shredded Beef', 'Recipe video above. A very quick, very tasty way to use up leftover cooked beef used in things like broth (see notes to start from raw). Created to use up leftover brisket from making Vietnamese Pho. Cooked is tossed in a Vietnamese lemongrass marinade then pan fried until golden. It''s INSANELY delicious!', 'https://www.recipetineats.com/tachyon/2019/04/Vietnamese-Shredded-Beef_2.jpg', 14, 6, 20, 3, '[{"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_lemongrass", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_cucumber", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["500g / 1lb (3 cups) leftover cooked brisket or other beef (, shredded or chopped (Note 1))","1 - 2 tbsp oil (, for cooking)"]},{"ingredients":["2 garlic cloves (, minced)","2 tbsp lime juice","2 tbsp fish sauce","1 tbsp soy sauce (, light or all purpose)","2.5 tbsp (packed) brown sugar","1 tbsp vegetable oil","1 tbsp lemongrass paste (Note 2)"],"purpose":"Marinade:"},{"ingredients":["Rice or noodles","Lime wedges OR Nuoc Cham (Note 3)","Fresh coriander/cilantro leaves (and/or finely sliced green onions)","Finely sliced red chilli, sliced cucumber, crushed peanuts*"],"purpose":"Serving:"}]', '[{"description":"Mix Marinade in a bowl.","images":[],"step":1},{"description":"Add shredded beef and mix. Set aside 5 minutes.","images":[],"step":2},{"description":"Heat oil in a large skillet over high heat. Add about half the beef and spread out in single layer.","images":[],"step":3},{"description":"Leave undisturbed until golden (about 1 minute). Flip then cook the other side just briefly (about 30 seconds) just to heat and get a touch of golden, then remove.","images":[],"step":4},{"description":"Repeat with remaining beef.","images":[],"step":5},{"description":"Serve over rice, using either limes or Nuoc Cham as the sauce, and garnishes of choice (I used them all in the photos!)","images":[],"step":6}]', '["fish","gluten","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Modern Vietnamese"],"categories":["beef","beef-recipes","dietary","gluten-free-recipes","mains","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f99b03cb0544', 'en', 'US', 'Beef Stroganoff', 'RECIPE VIDEO ABOVE. Juicy strips of beef smothered in a sour cream mushroom gravy - a quick dinner everyone will love! KEY STEPS: Sear beef super quickly for maximum juiciness and use a large skillet (for quick sear + fast sauce reduction). Stroganoff calls for good beef but if you only have a budget cut, use this easy Chinese method to tenderise the beef (it''s called "velveting"). It''s life changing - and perfect for Stroganoff.', 'https://www.recipetineats.com/tachyon/2018/01/Beef-Stroganoff_2-1-1.jpg', 15, 15, 30, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 40.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.6, "unit": "tub of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 250.0, "unit": "pack of 500g"}}, {"id": "ing_chives", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["600 g / 1.2 lb scotch fillet steak / boneless rib eye (Note 1)","2 tbsp vegetable oil (, divided)","1 large onion ((or 2 small onions), sliced)","300 g / 10 oz mushrooms (, sliced (not too thin))","40 g / 3 tbsp butter","2 tbsp flour (Note 2)","2 cups / 500 ml beef broth (, preferably salt reduced)","1 tbsp Dijon mustard","150 ml / 2/3 cup sour cream","Salt and pepper"]},{"ingredients":["250 - 300 g / 8 - 10 oz pasta or egg noodles of choice (Note 3)","Chopped chives (, for garnish (optional))"],"purpose":"Serving:"}]', '[{"description":"Use your fist (or rolling pin or mallet) to flatten the steaks to about 3/4cm / 1/3\" thick. Slice into 5mm / 1/5\" strips (cut long ones in half), discarding excess fat.","images":[],"step":1},{"description":"Sprinkle with a pinch of salt and pepper.","images":[],"step":2},{"description":"Heat 1 tbsp oil in a large skillet over high heat. Scatter half the beef in the skillet, QUICKLY spread it with tongs. Leave untouched for 30 seconds until browned. Turn beef quickly (as best you can!). Leave untouched for 30 seconds to brown. Immediately remove onto a plate. Don''t worry about pink bits and that it will be raw inside.","duration":0.5,"images":[],"step":3},{"description":"Add remaining 1 tbsp oil and repeat with remaining beef.","images":[],"step":4},{"description":"Turn heat down to medium high. Add butter, melt. Then add onions, cook for 1 minute, then add mushrooms.","duration":1,"images":[],"step":5},{"description":"Cook mushrooms until golden. Scrape bottom of fry pan to get all the golden bits off (this is flavour!).","images":[],"step":6},{"description":"Add flour, cook, stirring, for 1 minute.","duration":1,"images":[],"step":7},{"description":"Add half the broth while stirring. Once incorporated, add remaining broth.","images":[],"step":8},{"description":"Stir, then add sour cream and mustard. Stir until incorporated (don''t worry if it looks split, sour cream will \"melt\" as it heats).","images":[],"step":9},{"description":"Bring to simmer ,then reduce heat to medium low. Once it thickens to the consistency of pouring cream (3 - 5 minutes), adjust salt and pepper to taste.","images":[],"step":10},{"description":"Add beef back in (including plate juices). Simmer for 1 minute, then remove from stove immediately. (Note 4)","duration":1,"images":[],"step":11},{"description":"Serve over pasta or egg noodles, sprinkled with chives if desired.","images":[],"step":12}]', '["egg","fish","gluten","milk","mustard"]', '["high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Russian","Western"],"categories":["beef","beef-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","mains","nagis-picks","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1ea0f9b2f17b', 'en', 'US', 'Sloppy Joes', 'Recipe video above. Everybody loves Sloppy Joes - and they''re easy to make from scratch! I like making it with crushed tomato and less ketchup, and skipping the flavoured canned tomato sauces. Ideal freezer food, and to scale up to make for gatherings. SWEETNESS: Sloppy Joes are typically quite sweet, this is less sweet than most. But if you want it with just a bit of sweetness, skip the brown sugar and add it in gradually towards the end, adjusting to taste.', 'https://www.recipetineats.com/tachyon/2018/10/Sloppy-Joes_3.jpg', 10, 40, 50, 5, '[{"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_ketchup", "quantity": {"value": 0.15, "unit": "bottle of 500g"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 5.0, "unit": "loaf"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_other_fixing_options_see_note_4", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["1 tbsp /15g butter","2 garlic cloves (, minced)","1 onion (, finely chopped)","1 green capsicum/bell pepper (, diced)","500 g/1lb ground beef (mince) (Note 1)","1 tbsp Dijon mustard (OR 1 tsp dry mustard)","1.5 tbsp brown sugar","1/2 cup ketchup","400 g/14oz crushed tomato (, canned)","2 tsp Worcestershire sauce","1 tbsp tomato paste","1 beef bouillon cube (, crumbled (Note 2))","1/4 tsp black pepper"]},{"ingredients":["5 to 6 soft rolls (Note 3)","Cheese slices (optional)","Other fixing options - see Note 4"],"purpose":"To serve:"}]', '[{"description":"Melt butter in a large pot over high heat.","images":[],"step":1},{"description":"Ad garlic and onion, cook for 2 minutes until onion is almost translucent.","duration":2,"images":[],"step":2},{"description":"Add capsicum and cook for 2 minutes until softened.","duration":2,"images":[],"step":3},{"description":"Add beef and cook, breaking it up as you go, until it changes from red to brown.","images":[],"step":4},{"description":"Add remaining ingredients. Mix well, then turn heat down to medium low (or low for strong stoves).","images":[],"step":5},{"description":"Cover and cook for 30 minutes, stirring once or twice to make sure it doesn''t catch on the base. (If in rush, cook 15 minutes without lid)","duration":30,"images":[],"step":6},{"description":"Remove lid and give it a good stir for a minute. Mixture should be thick, not runny and saucy (see video). Adjust salt to taste.","images":[],"step":7},{"description":"Toast rolls. Butter if desired (I don''t).","images":[],"step":8},{"description":"Pile on lots of filling, immediately top with cheese (heat should semi melt, otherwise pop under broiler/grill). Top with lid and serve immediately!","images":[],"step":9}]', '["milk","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef","beef-mince-recipes","dinner-tonight","mains","quick-and-easy","sandwiches-and-sliders","sunday-supper"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_eee5a4909093', 'en', 'US', 'OSSO BUCO', 'Recipe VIDEO above. Meltingly tender veal shanks slow cooked in a tomato sauce, a classic Italian dish! This is traditionally served with Risotto Milanese (saffron risotto) but is also terrific over mashed potato, polenta and even pasta. Gremolata is also served with Osso Buco and it provides a fantastic freshness to contrast with the richness of this dish.', 'https://www.recipetineats.com/tachyon/2017/08/Osso-Buco-2.jpg', 15, 90, 105, 5, '[{"id": "ing_thick_veal_osso_bucco", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_kitchen_string", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.12, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}]', '[{"ingredients":["5 thick veal osso bucco (300 g / 10 oz each, 2.5cm / 1” thick) (or beef, Note 1)","Salt and pepper","Kitchen string (optional)","2 tbsp olive oil","1 small onion (, finely chopped)","3 garlic cloves (, minced)","1 small carrot (, finely chopped)","1 celery stick (, finely chopped)","800 g / 28 oz can crushed tomato","1 cup / 250 ml dry white wine ((not sweet, not fruity), or chicken broth)","1 cup / 250 ml chicken broth","1 chicken bouillon cube (optional, or use beef)","2 tbsp tomato paste","3 sprigs thyme or 1 ½ tsp dried thyme","2 bay leaves"]},{"ingredients":["1 cup parsley leaves (flat or curly), lightly packed","2 – 3 tsp lemon zest (, finely grated)","1 garlic clove (, minced)"],"purpose":"Gremolata:"},{"ingredients":["Risotto Milanese ((saffron risotto, recipe in notes), mashed potato or pasta)"],"purpose":"For Serving:"}]', '[{"description":"Sprinkle both sides of the veal very generously with salt and pepper.","images":[],"step":1},{"description":"Heat the oil in a large heavy based pot over high heat. Add beef and sear on both sides so it has a nice brown crust. Remove onto a plate, turn heat down to medium low.","images":[],"step":2},{"description":"If the pot is looking dry, add a splash of oil. Add garlic and onion, cook for 1 minute, then add carrot and celery. Cook on low heat for 8 minutes or until it is softened and sweet.","duration":1,"images":[],"step":3},{"title":"OPTIONAL","description":"Meanwhile, tie kitchen string around each piece of veal – holds it together for nice presentation (it falls apart once slow cooked).","images":[],"step":4},{"description":"Add tomato, wine, broth, bouillon cube (crumbled), tomato paste, thyme, and bay leaves. Mix, then return veal into pot, place lid on.","images":[],"step":5},{"title":"Adjust heat so the liquid is simmering gently","description":"about medium low. Cook until tender enough to be pried apart with forks – check at 1.5 hours then every 15 minutes after that.","images":[],"step":6},{"description":"Use slotted spoon to remove veal into bowl, cover to keep warm. Simmer liquid on medium for 5 – 15 minutes or until thickened to taste. Adjust salt & pepper at the end.","duration":10,"images":[],"step":7},{"description":"Traditionally served with Saffron Risotto (Risotto Milanese, recipe in notes), but is also terrific with mashed potato, creamy polenta or even pasta. Place a piece of Osso Buco on the serving plate, spoon over sauce, then top with Gremolata.","images":[],"step":8},{"description":"Place the parsley leaves on a cutting board. Top with garlic and lemon zest. Finely chop the parsley. Transfer to serving bowl and set aside for at least 20 minutes before use.","images":[],"step":9}]', '["gluten"]', '[]', '{"mealType":["dinner"],"cuisine":["American-Italian"],"categories":["beef","beef-recipes","dietary","gluten-free-recipes","italian-recipes","mains","stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_42199f3a765f', 'en', 'US', 'One Pot Lasagna', 'Recipe video above. This is how to make an easy lasagna from scratch in one pan, complete with layers!! It''s such a great way to get a lasagna fix mid week when you don''t have the time to make a proper lasagna. Everyone will be so amazed when you tell them you made it in one pot! (Well, one pan...)This is a quick version so the meat sauce (essentially Spaghetti Bolognese) is cooked quickly, and you''ll love how we use one bottle of tomato passata for both the meat sauce and tomato topping. Make sure to use dried lasagna sheets, not fresh, which will be too soft here.Note: The carrot and celery are optional, as is the ricotta layer (but boy is it good when you use it!)', 'https://www.recipetineats.com/tachyon/2026/05/One-pot-lasagna-with-layers-5-1.jpg', 20, 50, 80, 5, '[{"id": "ing_tomato", "quantity": {"value": 0.68, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.68, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_italian_herb_mix", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_ricotta", "quantity": {"value": 0.6, "unit": "tub of 250g"}}, {"id": "ing_milk", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_sheets_lasagna", "quantity": {"value": 8.0, "unit": "pack"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.5, "unit": "pack of 125g"}}, {"id": "ing_parsley", "quantity": {"value": 0.1, "unit": "bunch"}}]', '[{"ingredients":["24 oz / 700g (1 bottle) tomato passata ((pureed tomato - Note 1), used for both the meat sauce and sauce topping)"]},{"ingredients":["2 tbsp olive oil","3 garlic cloves (, finely minced)","1 small onion (, diced)","1 small carrot (optional) (, peeled and shredded using a box grater)","1 celery stick (optional) (, shredded using a box grater (discard stringy bits remaining))","1 lb / 500g beef mince (ground beef)","2 tbsp tomato paste","2 beef bouillon stock cubes (, crumbled)","2 tsp Worcestershire sauce","1/2 tsp white sugar (Note 2)","1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper","1/2 cup water"],"purpose":"Meat sauce:"},{"ingredients":["1 tsp dried Italian herb mix (, or equal parts dried basil, oregano and parsley)","1/2 tsp garlic powder (or 1 crushed garlic clove)","1/4 tsp white sugar (Note 2)","1/2 tsp cooking salt / kosher salt","1/4 cup water"],"purpose":"Topping Sauce flavourings"},{"ingredients":["1 cup good ricotta (I like Paesanella) or smooth ricotta (Note 3)","1 tbsp milk (, as needed (probably won''t need for smooth ricotta))","1/4 tsp cooking salt / kosher salt"],"purpose":"Creamy ricotta dollops (faux bechamel!) – optional"},{"ingredients":["8 sheets (250g / 8oz) dried lasagna (US: no-boil \"oven-ready\" lasagna) (, not fresh (Note 4))","1 1/2 tightly packed cups mozzarella cheese (, shredded)","2 tsp parsley (, finely chopped (optional))"],"purpose":"Lasagna"}]', '[{"title":"Meat sauce","description":"Sauté onion, garlic, celery and carrot, cook beef. Add 2/3 bottle of passata + remaining Meat Sauce ingredients, simmer 10 min. Topping Sauce - add everything into remaining passata in bottle, shake. Creamy ricotta - vigorously whisk until it''s like whipped cream. Layer - Remove half meat sauce from pan. Slide lasagna sheets under Meat Sauce (break as needed), then do 2 more layers using reserved meat sauce. Dollop with ricotta, cover with cheese, bake 30 min at 180C/350F (160C). Stand 10 min before cutting.","images":[],"step":1},{"title":"Sauté","description":"Heat olive oil in a deep skillet/pan over medium high heat. (Mine is 26cm/10.5\" wide, 5cm/2\" deep) (Note 5) Add garlic, onion, carrot and celery. Sauté until onion is translucent - about 3 minutes.","images":[],"step":2},{"title":"Cook beef","description":"Turn up heat to high. Add beef and cook, breaking it up with the spatula, until you no longer see red.","images":[],"step":3},{"title":"Sauce","description":"Add about 2/3 of the passata (keep rest for Sauce), and remaining Meat Sauce ingredients. Bring to rapid simmer, then turn down to medium/medium low. Simmer gently for 10 minutes.","duration":10,"images":[],"step":4},{"description":"Preheat oven to 180°C/350°F (160°C fan-forced).","images":[],"step":5},{"title":"Make sauce","description":"Add Sauce Flavourings into the tomato passata bottle and shake to combine.","images":[],"step":6},{"title":"Creamy ricotta (optional)","description":"Put the ingredients in a bowl. Start softening the ricotta using smearing motions with the back of a spoon, then switch to a whisk and give it a vigorous whisk for 20 - 30 seconds until it resembles whipped cream. (If using smooth ricotta, you''ll barely need to do this).","duration":0.4166666666666667,"images":[],"step":7},{"description":"Assemble lasagna (in-post step photos and video are helpful)","images":[],"step":8},{"title":"Remove half filling","description":"Remove the pan from the stove. Remove half the Meat Sauce into a bowl.","images":[],"step":9},{"title":"Base layer","description":"Slide one lasagna sheet, starting from the side, under the Meat Sauce - this will be the base of the lasagna. Break up pieces of lasagne and slide them in under the Meat Sauce around the sides of the pan (to form the remainder of the bottom layer). There is no need to be accurate with coverage here, you can overlap and have gaps. We are making a rustic quick lasagna, remember! Spread the Meat Sauce to cover all the lasagna sheets.","images":[],"step":10},{"title":"Layer 2","description":"Top with another layer of dried lasagna sheets. Then spread over the Meat Sauce in the bowl.","images":[],"step":11},{"title":"Layer 3","description":"Cover with a 3rd layer of lasagna sheets.","images":[],"step":12},{"title":"Toppings","description":"Pour over the Sauce and spread over the top. Do 12 - 15 dollops of ricotta across the surface (if using). Sprinkle with cheese.","images":[],"step":13},{"title":"Bake and rest","description":"Bake for 30 minutes uncovered, then set aside for 10 minutes to stabilise a bit.","duration":30,"images":[],"step":14},{"title":"Serve","description":"Sprinkle with parsley (if using), then cut and serve! Enjoy with a simple Balsamic Rocket Salad and Garlic Bread on the side.","images":[],"step":15}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian-esque","Western"],"categories":["beef-mince-recipes","beef-recipes","casseroles-and-cosy-bakes","italian-recipes","most-popular","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_80025a6e18b0', 'en', 'US', 'Pastel de Choclo (Chilean Beef and Corn Casserole)', 'Recipe video above. Meet my new favourite way to turn beef mince and a big bag of frozen corn into dinner! This is Pastel de Choclo, a classic Chilean casserole with a spiced onion beef filling and a thick corn topping that bakes up lightly caramelised, with surprise pockets of olives, raisins and boiled egg tucked inside. It''s like South America''s answer to Cottage Pie! Hearty, comforting, something a little difference, I love the combination of the sweet corn pudding with the savoury beef filling. PS Frozen corn is super convenient but gosh, imagine making it with fresh summer corn?Recipe credits: Inspired by a visit to La Paula, a wonderful Chilean establishment in Fairfield, Sydney, and developed with reference to a number of recipes, listed in the blue box above the video.', 'https://www.recipetineats.com/tachyon/2026/05/Pastel-de-choclo-0.jpg', 20, 75, 110, 8, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_beef_mince", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 3000.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 2000.0, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_cumin", "quantity": {"value": 0.562, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_corn", "quantity": {"value": 3.125, "unit": "can of 400g"}}, {"id": "ing_milk", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_basil", "quantity": {"value": 12.0, "unit": "bunch"}}, {"id": "ing_corn", "quantity": {"value": 3.125, "unit": "can of 400g"}}, {"id": "ing_pitted_black_olives_else_kalamata_is_fine", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_raisins", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}]', '[{"ingredients":["2 tbsp olive oil","1 kg / 2 lb beef mince (ground beef)","3 large onions (, diced (4 - 5 medium ones))","6 large garlic cloves (, finely minced)","1/4 cup plain flour (all-purpose flour)","1 1/2 cups beef stock/broth (, low sodium)"],"purpose":"Beef filling:"},{"ingredients":["1 1/2 tbsp cumin powder","1 tbsp paprika (regular/sweet, not spicy or smoked)","1 1/2 tsp cooking salt / kosher salt","1/2 tsp black pepper"],"purpose":"Beef spice mix:"},{"ingredients":["50g/ 3 tbsp unsalted butter (or olive oil)","1.25 kg/ 2.5 lb frozen corn (, still frozen is fine, or kernels cut off corn cobs (8 cups) (Note 1 on canned corn))","1 1/2 tsp cooking salt / kosher salt","1/2 cup milk (any fat %, non-dairy is ok too)","12 - 15 large basil leaves (, optional (Note 2))","2 tbsp fine cornmeal (or semolina (Note 3))"],"purpose":"Corn layer:"},{"ingredients":["1/4 cup pitted black olives (roughly chopped, Chilean or South American (if you can) else Kalamata is fine)","2 soft boiled eggs (, quartered (8 minutes lowered into boiling water))","2 tbsp raisins (or sultanas)","1 tbsp regular sugar (granulated sugar) (, not caster sugar / superfine sugar (Note 4))","Pinch paprika"],"purpose":"Assembling / baking:"}]', '[{"description":"Preheat oven to 200°C/390°C (180°C fan-forced).","images":[],"step":1},{"title":"Cook beef","description":"Heat the oil in a large 30cm/12\" pan over high heat. Add the beef and cook, breaking it up as you go, until you no longer see red. Cook for another couple of minutes, breaking up the beef into fine pieces. Remove beef from the pan using a slotted spoon, leaving the fat and juices behind.","images":[],"step":2},{"title":"Cook onion","description":"To the same pan, add the onion and garlic. Cook for 5 minutes, stirring regularly, until the onion is translucent.","duration":5,"images":[],"step":3},{"title":"Simmer and reduce","description":"Add the beef and mix through. Stir in the spices. Add the flour and mix until you no longer see flour. Add the stock and stir - it will thicken into a gravy quite quickly, coating the beef. Lower heat to medium and cook for 5 minutes, stirring regularly so the base doesn''t catch, until the mixture is thick enough so you can draw a path across the base of the pan and it stays.","duration":5,"images":[],"step":4},{"description":"Remove from stove and spread in a 23 x 33 cm (9 x 13\") pan, then set aside and let it cool while you make the corn.","images":[],"step":5},{"title":"Sauté","description":"Melt the butter in a pot over medium high heat. Add corn (still frozen is fine) and cook for 5 minutes, stirring regularly.","duration":5,"images":[],"step":6},{"title":"Blitz","description":"Add milk, salt and basil. Stir, then use a stick blender to blitz ~ 30 seconds (moving it around) or until you no longer see whole corn kernels. It won''t be complete smooth which is what you want.","images":[],"step":7},{"title":"Thicken","description":"Stir in cornmeal. Lower heat to medium or medium low so it''s not spitting. Cook for 5 minutes, stirring regularly so the base doesn''t catch. It should be thick enough to mound in a heap on the spoon, and when you draw a path across the base it should stay in place.","duration":5,"images":[],"step":8},{"description":"Assemble and bake:","images":[],"step":9},{"title":"Assemble","description":"Press the eggs into the beef, scatter with olives and raisins.","images":[],"step":10},{"title":"Corn topping","description":"Dollop the corn mixture across the surface then spread and smooth the surface. Sprinkle all over with the sugar, then paprika (sprinkle from a height for light coverage).","images":[],"step":11},{"title":"Bake for 40","description":"45 minutes until the surface is golden. Cool 15 minutes to let it set a bit so you can cut neat(ish) slices, then cut like lasagna and serve!","duration":42.5,"images":[],"step":12}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Chilean","South American"],"categories":["beef-mince-recipes","casseroles-and-cosy-bakes","south-american-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_da0ac6dc0fd6', 'en', 'US', 'Moroccan Spiral Meatball Zucchini Bake', 'Recipe video above. I love recipes like this - everyday ingredients used in a different way to make something new and interesting! Moroccan-spiced lamb meatballs are baked in a striking spiral arrangement with zucchini and capsicum in a bubbly garlicky tomato sauce. You will be impressed at how soft the meatballs are, and how the deceptively simple tomato sauce gets so much flavour as it bakes!Serve straight from the pan with flatbreads, couscous or basmati rice.Inspired by Özlem Warren''s Baked Aubergine Kebab with Meatballs from Özlem''s Turkish Table.', 'https://www.recipetineats.com/tachyon/2025/08/Moroccan-Meatball-Zucchini-Spiral-Bake_7.jpg', 25, 35, 60, 4, '[{"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_lamb_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_zucchini", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["1/2 cup panko breadcrumbs (use GF if needed, can substitute regular breadcrumbs)","1/2 onion (, grated with a standard box grater)","500g / 1 lb lamb mince (ground lamb), or beef (Note 1)","1 egg","2 garlic cloves (, finely minced using a garlic crusher or knife)","1/4 cup pretty finely chopped parsley (, plus extra for garnish)"],"purpose":"Meatballs:"},{"ingredients":["1 tsp cumin powder","1 tsp coriander power","1 tsp paprika (sweet / regular, or smoky - not spicy)","1/4 tsp cinnamon powder (don''t skip this! Magical :) )","1/4 tsp cayenne pepper ((or black pepper), tiny amount so doesn''t make it spicy)","3/4 tsp cooking salt / kosher salt"],"purpose":"Moroccan spice mix:"},{"ingredients":["2 fat zucchinis / courgettes (5cm/2\" wide, 22cm/9\" long is ideal), cut into ~20 x 1.2 cm / 0.5\" thick rounds (Note 2)","1 large or 1 1/2 regular red capsicum (bell pepper), cut into ~20 x large-ish chunks 5 x 2.5cm / 1 x 2\" (Note 3)","1/2 tbsp extra virgin olive oil (, plus extra for drizzling to bake)","1/4 tsp each salt and pepper"],"purpose":"Vegetables:"},{"ingredients":["2 garlic cloves (, crushed using garlic press)","2 1/2 tbsp tomato paste","2 tbsp extra virgin olive oil","1/2 cup warm tap water","1/8 tsp each salt and pepper"],"purpose":"Garlic tomato sauce:"},{"ingredients":["Plain yogurt (, thinned with a little water to make it drizzle-able)","Flatbreads (, rice(basmati recommended), couscous, mash)"],"purpose":"Serving"}]', '[{"description":"Toss Vegetables, mix Sauce. Make meatball mixture, roll and squish 16 meatballs, wedge between zucchini rounds, tuck capsicum in. Pour over sauce, bake 35 minutes at 200°C/375°F (180°C fan).","images":[],"step":1},{"description":"Preheat oven to 200°C/375°F (180°C fan-forced).","images":[],"step":2},{"description":"Toss capsicum and zucchini with the oil, salt and pepper in a bowl, and set aside.","images":[],"step":3},{"title":"Sauce","description":"Mix the sauce ingredients in a small jug or bowl.","images":[],"step":4},{"title":"Meatball mixture","description":"Put the breadcrumbs in a bowl and grate the onion over. Toss with fingertips to wet the breadcrumbs with the onion juices. Then add remaining meatball ingredients and the Moroccan spice mix. Mix well with your hands.","images":[],"step":5},{"title":"Roll & squish","description":"Roll the mixture into 16 balls then squish slightly to 1.5cm / 0.6\" thickness (~2.5 tbsp/45g each), about the size of (or slightly larger than) the zucchini rounds.","images":[],"step":6},{"description":"Stand upright with a zucchini round wedged and arrange in a 26cm/10.5\" round cast-iron pan (or baking dish of similar size). I do them in a ring then use the rest to fill in the middle. Arrange loosely because next we wedge the capsicum in between wherever you can. Fill the whole pan so everything holds each other up, and use as much capsicum & zucchini as you can (you might have leftover). There are NO RULES with arrangement here, make this your own delicious artwork! :)","images":[],"step":7},{"description":"Pour sauce over everything, aiming to pour some over everything as best you can. Drizzle all over with about 1 tbsp olive oil.","images":[],"step":8},{"description":"Bake for 35 minutes until the surface of the meatballs are nicely browned.","duration":35,"images":[],"step":9},{"description":"Serve with flatbreads or garlic rice, being sure to spoon plenty of the delicious sauce over everything!","images":[],"step":10}]', '["egg","gluten","milk"]', '["high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern"],"categories":["beef-mince-recipes","cuisines","dietary","gluten-free-recipes","lamb","mains","meatball-recipes","middle-eastern-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7d36cbdc7d5e', 'en', 'US', 'Smothered rissoles', 'Recipe video above. Rissoles are great. Smothered rissoles are AWESOME!!! Especially when it’s mushroom gravy doing the smothering. :)They''re the softest rissoles you''ve ever had because we cook them in the gravy as it thickens. They come out so much softer than regular rissoles!Serve over buttery mash for cosy comfort food you''ll crave week after week.', 'https://www.recipetineats.com/tachyon/2025/07/Smothered-rissoles-overhead.jpg', 20, 15, 35, 4, '[{"id": "ing_onion", "quantity": {"value": 500.0, "unit": "pack of 1kg"}}, {"id": "ing_bread", "quantity": {"value": 0.094, "unit": "loaf"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_zucchini", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_thyme", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 500.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_mushroom", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.052, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}]', '[{"ingredients":["1/2 large onion (, grated using standard box grater (Note 1))","1/2 cup panko breadcrumbs (sub regular breadcrumbs, Note 2)","500g/ 1lb beef mince (ground beef)","1 small zucchini (, grated)","1 small carrot (, peeled and grated)","1 large egg","1 large garlic clove (, crushed using garlic press or finely grated)","1/2 tsp dried thyme (optional)","1/2 tsp oregano (optional)","1/4 tsp black pepper","3/4 tsp cooking salt / kosher salt (halve for table salt)","2 tsp Worcestershire sauce"],"purpose":"RISSOLES:"},{"ingredients":["2 tbsp olive oil (, for cooking)"],"purpose":"COOKING:"},{"ingredients":["30g/ 2 tbsp unsalted butter","1/2 onion (, sliced 5mm/0.2\" thick)","2 garlic cloves (, finely chopped)","200g/ 7 oz mushrooms (, sliced 5mm/0.2\" thick)","3 1/2 tbsp flour (plain / all-purpose)","2 cups beef stock / broth (, low sodium)","1/4 tsp cooking salt / kosher salt (halve for table salt)","1/4 tsp black pepper","1 tsp Worcestershire sauce"],"purpose":"MUSHROOM GRAVY"},{"ingredients":["Mashed potato (or other starchy vehicle of choice)"],"purpose":"TO SERVE"}]', '[{"description":"Mix rissole ingredients, form 12 patties, slightly indent one side. Cook in 2 batches until lightly browned but raw inside. Wipe pan clean, melt butter, cook onion, then mushrooms, add garlic towards end. Make roux then gravy. Cook rissoles in gravy as it thickens, 4 - 5 minutes, serve!","images":[],"step":1},{"description":"Grate the onion into a large bowl, add panko, toss to soak in the onion juices. Add remaining rissole ingredients and mix well with your hands.","images":[],"step":2},{"title":"Dented patties","description":"Form 12 patties (1/4 cup each) and make a slight indentation on one side (this prevents doming while cooking).","images":[],"step":3},{"title":"Lightly brown","description":"Heat 1 tablespoon of the oil in a large non-stick pan (30cm/12\") over medium high heat. Cook half the rissoles for 1 1/2 minutes on each side until lightly browned but still raw inside. Remove onto a plate. Add the remaining oil and repeat with remaining rissoles.","images":[],"step":4},{"description":"Mushroom gravy:","images":[],"step":5},{"title":"Clean pan","description":"Discard excess oil and give the pan a rough clean with paper towels, just to remove most of the black bits.","images":[],"step":6},{"title":"Cook mushrooms","description":"Melt the butter in the same pan, cook the onion for 1 minute, then add the mushrooms and cook for 3 - 4 minutes until they release water, soften, then become lightly browned. Add the garlic for the last 30 seconds.","duration":1,"images":[],"step":7},{"title":"Cook off flour","description":"Turn the heat down to medium, scatter flour across the surface and stir for 1 minute - it will be like a dry paste.","duration":1,"images":[],"step":8},{"title":"Half beef stock","description":"While stirring, pour in half the stock then keep mixing until the flour paste dissolves and thickens the liquid, and is lump free (about 30 seconds).","images":[],"step":9},{"title":"Simmer rissoles and thicken gravy","description":"Add remaining stock, Worcestershire sauce, salt and pepper. Stir, turn heat up slightly to medium high. When it starts simmering, gently place the rissoles in (including any juices pooled on the plate). Cook rissoles 4 - 5 minutes until the liquid thickens into a thin gravy (aim for thinner than you want, thickens as you serve).","images":[],"step":10},{"description":"Serve rissoles over mash with plenty of sauce! Add a sprinkle of parsley if you''re feeling fancy.","images":[],"step":11}]', '["egg","gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Aussie","Australian"],"categories":["beef-mince-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4e8dbcdfe4f9', 'en', 'US', 'Crispy oven baked beef quesadillas', 'Recipe video above. This is a super handy method to make 3, 4 or 8 quesadillas in the oven at the same time rather than cooking them one by one on the stove. They are impressively crispy (see photos and video for proof!) and very quick to make.Stuffed with my beef taco filling though you can switch with chicken, turkey, pork or lamb, or stuff with whatever your heart desires as long as it''s not too watery because this might affect how well the tortilla crisps in the oven.', 'https://www.recipetineats.com/tachyon/2024/07/Baked-Beef-Quasadillas-51259.jpg', 5, 20, 25, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 0.125, "unit": "can of 400g"}}, {"id": "ing_black_beans", "quantity": {"value": 0.125, "unit": "can of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_tortillas", "quantity": {"value": 4.0, "unit": "pack of 8"}}, {"id": "ing_cheese", "quantity": {"value": 1.25, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.833, "unit": "pack of 3 heads"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.016, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_pico_de_gallo", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_nothing", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["2 tsp olive oil","250g/ 8oz beef mince ((ground beef) - or chicken, turkey, pork, lamb)","1 tbsp tomato paste","1/3 cup corn kernels (canned, drain, or frozen)","1/3 cup black beans (caned, drained)","2 tbsp water"]},{"ingredients":["4 flour tortillas (20cm/8\"), Mission crisps best, Old El Paso the least (Note 1)","3 tsp olive oil","1 1/4 tightly packed cups shredded cheese ( - cheddar, colby, tasty cheese, Monterey jack (not mozzarella))"],"purpose":"Quesadillas:"},{"ingredients":["1/2 tsp EACH ground garlic (, onion, dried oregano)","1 tsp EACH cumin (, paprika powder)","1/8 tsp cayenne pepper (, optional)","1/4 tsp cooking salt / kosher salt"],"purpose":"Homemade taco seasoning:"},{"ingredients":["Avocado sauce ( or Guacamole)","Pico de Gallo","Sour cream","Nothing (I happily eat it plain!)"],"purpose":"Serving:"}]', '[{"title":"Filling","description":"Heat the oil in a non stick pan over high heat. Add the beef and cook, breaking it up as you go, until the red colour is mostly gone. Add the Taco Seasoning and cook for 1 minute. Add the tomato paste and cook for 30 seconds. Stir in the beans and corn, then add the water and stir. The filling should be juicy (not dry) but not watery (compromises crispiness!). Remove into a bowl and cool for at least 15 minutes.","duration":1,"images":[],"step":1},{"description":"Preheat the oven to 220°C / 425°F (200°C fan-forced). Grease a metal tray with 1 teaspoon of olive oil (I use my hand).","images":[],"step":2},{"title":"Assemble quesadillas","description":"Spread the filling on one side of the quesadilla. Top with cheese, fold to cover. Place on tray, repeat with remaining quesadillas.","images":[],"step":3},{"description":"Drizzle the top of each with 1/2 tsp olive oil then spread using your hands (top and sides, not underside). Press the quesadilla down to flatten the surface.","images":[],"step":4},{"description":"Bake for 8 minutes. Flip the quesadillas, bake for 5 minutes, flip again then bake for a further 2 minutes or until crispy. (Sometimes I spritz with oil to give it a helping hand)","duration":8,"images":[],"step":5},{"title":"Serve","description":"Cut each into half and serve immediately with dipping sauce/toppings of choice.","images":[],"step":6}]', '["gluten","milk"]', '["high_protein","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["beef-mince-recipes","mexican-recipes","quesadillas","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a5b8c424a45a', 'en', 'US', 'Qeema Indian Curried Beef', 'An authentic Indian spiced ground (minced) beef recipe known as Qeema (or keema or kheema). This is a gem of a recipe because it tastes incredible but unlike many Indian dishes, there are no hard-to-find spices in the ingredients. And it''s super fast - on the table in 20 minutes! Serve over basmati rice. Great with plain yogurt, even better with Mint Yogurt.', 'https://www.recipetineats.com/tachyon/2016/04/Queema-Indian-Curried-Beef-Mince_3.jpg', 5, 15, 20, 4, '[{"id": "ing_oil", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_ginger", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1666.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_aram_masala", "quantity": {"value": 1.25, "unit": "unit"}}, {"id": "ing_cumin", "quantity": {"value": 0.156, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.125, "unit": "bunch"}}, {"id": "ing_turmeric", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.125, "unit": "bunch"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.006, "unit": "tub of 500g"}}, {"id": "ing_mint", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["3 tbsp vegetable or canola oil (, or other neutral oil)","4 tsp ginger (, finely mince)","5 large garlic cloves (, minced (about 4 tsp))","1 large onion (, finely diced)","500g / 1 lb beef mince (ground beef)","3/4 tsp cooking salt / kosher salt","1 tsp cayenne pepper (or chilli powder (pure, not US chili powder spice mix), omit for not spicy)","1 1/4 tsp garam masala (Note 1)","1 1/4 tsp cumin powder","1 1/4 tsp coriander powder","1/2 tsp turmeric powder","1 cup water"]},{"ingredients":["1 green cayenne pepper (, deseeded, finely sliced)","Cilantro/coriander leaves","Plain yogurt or Mint yogurt (below)"],"purpose":"Garnish"},{"ingredients":["3/4 cup plain yogurt","1/2 cup (lightly packed) mint leaves","1/4 tsp cooking salt / kosher salt"],"purpose":"Mint yogurt (optional, pictured in post)"}]', '[{"title":"Sauté","description":"Heat oil in a skillet over high heat. Add ginger and garlic and saute for 30 seconds until golden, don''t let it burn! Add onion and cook for 1 minute until it is starting to turn translucent.","duration":0.5,"images":[],"step":1},{"description":"Add beef and cook, breaking it up as you go, until it changes from pink to light brown. Add remaining ingredients EXCEPT water. Cook for a further 2 minutes to let the spices bloom.","images":[],"step":2},{"title":"Cook 10 minutes","description":"Add water, give it a stir, then put a lid on (or cover with a baking tray). Turn heat down to medium and let it simmer for 10 minutes or until most of the water has evaporated.","duration":10,"images":[],"step":3},{"description":"Serve over with basmati rice or plain white rice, garnished with extra chilli and coriander/cilantro, and lots of Mint Yogurt. Naan or flatbreads would make it even better, though if time is not your friend, try frozen roti (pictured in post, Note 3).","images":[],"step":4},{"title":"Blitz then stir","description":"Put just 1/4 cup of the yogurt with the mint leaves and salt in a jug just big enough to fit the head of a stick blender. Blitz until mint is very finely chopped. Then stir in remaining yogurt. (Note 4) Refrigerate until required.","images":[],"step":5}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["beef-mince-recipes","beef-recipes","curry-recipes","dietary","dinner-tonight","gluten-free-recipes","indian-recipes","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_595f731dc716', 'en', 'US', 'Easy Moroccan Stuffed Eggplant (beef or lamb)', 'Recipe video above. A delicious, unique, EASY way to serve up eggplant and minced / ground beef or lamb! Think of this as a midweek take on traditional Arabic stuffed eggplant that''s usually hollowed out.Don''t worry if you don''t have every single spice. There''s so many in this spice mix, it will still be tasty even if you''re missing one...or two, even three!Serves 2 as a main with a small side salad, or 4 as a meal with a starch (flatbread, couscous) and a substantial side (like this Pumpkin Salad, roast veg, chickpea salad), or 4 as a generous starter.', 'https://www.recipetineats.com/tachyon/2016/03/Moroccan-baked-eggplant-halves-with-beef-or-lamb_0.jpg', 15, 45, 90, 2, '[{"id": "ing_egg", "quantity": {"value": 0.167, "unit": "carton of 12"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cinnamon", "quantity": {"value": 1.25, "unit": "jar"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.833, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_lamb_mince", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_pinenuts", "quantity": {"value": 30.0, "unit": "jar"}}]', '[{"ingredients":["2 x 250g/8oz eggplants (aubergines), ~17cm/7\" long (Note 1)","3/4 tsp cooking salt / kosher salt","1 tbsp extra virgin olive oil","1 tbsp lemon juice (or more oil)"],"purpose":"Eggplant"},{"ingredients":["1 1/2 tsp EACH coriander, paprika","1 tsp cumin","3/4 tsp all spice powder","1/2 tsp EACH garlic powder, ginger, turmeric powder","1/4 tsp cinnamon","1/4 tsp cayenne pepper"],"purpose":"Chermoula spice mix (Note 2)"},{"ingredients":["1 tbsp olive oil","1 garlic clove (, finely minced)","1/2 onion (, finely chopped)","250g / 8oz beef or lamb mince (, lean if you can (chicken, turkey, pork also ok))","1/2 tsp cooking/kosher salt","2 tsp tomato paste (Note 3)","1/4 cup water"],"purpose":"Spiced beef or Lamb topping"},{"ingredients":["Yoghurt (, plain)","2 tbsp coriander/cilantro leaves (, roughly chopped (sub parsley))","2 tbsp pinenuts (, toasted (Note 4))"],"purpose":"To Serve"}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan).","images":[],"step":1},{"title":"Sweat eggplants (recommended, see Note 5 to skip)","description":"Cut eggplants in half then score with 2.5cm / 1\" diamonds. Rub surface with salt, getting some into the slits. Place face down in a colander and set aside for 30 minutes. Gently squeeze like a sponge to remove excess water, pat surface dry.","duration":30,"images":[],"step":2},{"description":"Mix Chermoula spice mix ingredients in a bowl. Remove 3 teaspoons for the meat and set aside. Add olive oil and lemon juice into the remaining spice mix and mix into a paste.","images":[],"step":3},{"title":"Roast eggplant","description":"Place eggplant on baking tray. Slather spice mix onto the surface. Roast for 45 minutes until softened.","duration":45,"images":[],"step":4},{"title":"Spiced topping","description":"Heat oil in a non stick skillet over medium high heat. Cook onion and garlic for 1 minute. Turn heat up to high, add lamb/beef and cook, breaking it up as you go, until you no longer see red. Add reserved spices and salt, then cook for a further 1 minute. Add tomato paste and cook for 1 minute. Stir in water, cook for 1 minute until it''s juicy but not watery.","duration":1,"images":[],"step":5},{"title":"Assemble","description":"Top eggplant with beef/lamb. Sprinkle over coriander, dollop with yogurt and pine nuts. Finish with an extra drizzle of extra virgin olive oil, if desired!","images":[],"step":6}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern"],"categories":["beef-mince-recipes","beef-recipes","cuisines","dietary","dinner-tonight","gluten-free-recipes","lamb-recipes","low-calorie-recipes","main-dishes","middle-eastern-recipes","moroccan","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_12984a900bda', 'en', 'US', 'Beef fried rice', 'Recipe video above. GREAT quick dinner to make with beef mince, complete with veg, protein and starch! The trick is using a strong savoury sauce and caramelise the beef well for extra delicious flavour.Frozen cooked rice is a staple in my house. Don''t have day-old-cooked rice? Don''t try this recipe - you''ll be disappointed with gummy rice! Make Baked Fried Rice instead (starts with uncooked rice, and it''s awesome!). Use the beef to make Asian Beef and serve together.', 'https://www.recipetineats.com/tachyon/2023/02/Beef-fried-rice_4.jpg', 10, 10, 20, 4, '[{"id": "ing_dark_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_oil", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 75.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 300.0, "unit": "pack of 1kg"}}, {"id": "ing_rice", "quantity": {"value": 450.0, "unit": "pack"}}, {"id": "ing_green_onion", "quantity": {"value": 1.5, "unit": "bunch"}}]', '[{"ingredients":["1 tbsp dark soy sauce (Note 1)","2 tsp light soy sauce (Note 1)","2 tbsp oyster sauce (Note 2)","1 tbsp Chinese cooking wine (Note 3)","1/2 tsp white sugar","1/8 tsp white pepper (sub black)"],"purpose":"Sauce:"},{"ingredients":["1 tsp sesame oil","2 eggs (, lightly whisked)"],"purpose":"Scrambled eggs:"},{"ingredients":["2 tbsp oil (peanut, veg, canola or other neutral oil)","1/2 onion (, finely diced)","2 garlic cloves (, finely minced)","250g / 8 oz beef mince / ground beef (I use lean, Note 4)","2 cups frozen diced carrots, peas, corn ( (still frozen fine!) (or fresh diced veg))","3 cups day-old cooked rice (1c uncooked rice = 3c cooked, Note 5)","1/2 cup finely sliced green onions (1-2 stems)"],"purpose":"Fried rice:"}]', '[{"description":"Mix Sauce ingredients in a small bowl, then set aside.","images":[],"step":1},{"title":"Scramble eggs","description":"Heat sesame oil in a large wok or non-stick pan over medium high heat. Add egg and cook, stirring gently, so it is softly scrambled. Remove onto a plate.","images":[],"step":2},{"title":"Cook beef","description":"Heat vegetable oil in the same pan over high heat. Add onion and garlic, cook for 30 seconds. Add beef and cook, breaking it up as you go, for 2 minutes or until you no longer see raw beef. Add 2 tablespoons of sauce and cook for 1 minute.","duration":0.5,"images":[],"step":3},{"title":"Veg / caramelise beef","description":"Add frozen vegetables and cook for 2 minutes or until the beef gets nicely caramelised - this is the trick to great flavour so do not shortcut this!","duration":2,"images":[],"step":4},{"title":"Rice & sauce","description":"Add rice and remaining sauce. Toss for 2 minutes until the sauce is well dispersed throughout the rice and the rice grains start to caramelise a bit.","duration":2,"images":[],"step":5},{"title":"Egg & green onion","description":"Then add scrambled eggs and green onion, give it a quick toss to disperse then divide between bowls. EAT!","images":[],"step":6}]', '["egg","gluten","peanuts","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["beef-mince-recipes","fried-rice","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4f77c864ba2c', 'en', 'US', 'Cheeseburgers (double or single)', 'Recipe video above. This cheeseburger recipe assumes your bun is 10cm/4" wide. If it''s larger, you may want to scale up the beef so you don''t end up with wafer-thin patties or a burger patty that''s much smaller than your bun. Nobody likes biting into bread with no beef!!Slather with sauce of choice though for a really great burger experience, try my Special Burger Sauce (quick, no cook) or my Tomato Chutney for Burgers.', 'https://www.recipetineats.com/tachyon/2022/08/Stack-of-cheeseburgers.jpg', 10, 10, 20, 4, '[{"id": "ing_beef_mince", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 2.0, "unit": "bottle"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_cheese", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_lettuce", "quantity": {"value": 8.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_gherkins", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_special_burger_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_ketchup", "quantity": {"value": 1.0, "unit": "bottle of 500g"}}, {"id": "ing_mustard", "quantity": {"value": 0.005, "unit": "jar of 200g"}}, {"id": "ing_french_fries", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["600 g / 1.2 lb beef mince (ground beef) (, at least 20% fat (Note 1 for quality))"],"purpose":"Single Cheeseburgers:"},{"ingredients":["1.2 kg / 2.4 lb beef mince (ground beef) (, at least 20% fat (Note 1 for quality))"],"purpose":"Mighty Double Cheeseburgers:"},{"ingredients":["1/8 tsp each salt and pepper PER burger","2 - 3 tbsp canola oil"],"purpose":"Cooking:"},{"ingredients":["4 soft burger buns or rolls (, around 10cm/4\" wide (Note 2))","4 - 8 slices burger cheese (American) or other cheese or choice (Note 3)","8 cos/romaine lettuce leaves (, torn to size (or shredded iceberg))","2 large tomatoes (, cut into eight 7mm/ 1/4\" slices)","1 red onion (, finely sliced into rings (Note 4))","2 large gherkins (, finely sliced (Note 5))"],"purpose":"Everything else you need:"},{"ingredients":["Special Burger Sauce (creamy orangey/pink one, quick no cook)","Tomato chutney for burgers","Ketchup","Mustard"],"purpose":"Sauce options:"},{"ingredients":["French fries (and it''s epic!)"],"purpose":"On the side:"}]', '[{"title":"Patties","description":"Separate the beef into 4 equal portions, or 8 if making double cheeseburgers (do it!). Gently roll each portion into balls then press down into round patties that are slightly larger than your bun to allow for shrinkage (12 cm / 4.7\" wide, 1 cm / 0.4\" thick for a 10cm / 4\" burger bun).","images":[],"step":1},{"title":"Prepare","description":"Get all your burger bits and pieces out and ready to use. Don''t salt your beef until just before cooking (it toughens the meat).","images":[],"step":2},{"title":"Toast buns","description":"Preheat the grill to high. Place the bread cut face up on a tray and toast for 3 to 5 minutes until light golden. (If using BBQ, place cut face down on the grill). Set aside.","duration":4,"images":[],"step":3},{"title":"Dent patty","description":"Sprinkle one side of patties with half the salt and pepper. Flip, then press a dent into the middle of each patty. (Prevents patties doming when cooking and reduces shrinkage!). Sprinkle this dented side with the remaining salt and pepper.","images":[],"step":4},{"description":"Preheat 1 tablespoon oil in a large cast iron skillet over high heat until very hot - smoking hot! (Note 6)","images":[],"step":5},{"title":"Cook","description":"Cook 2 to 4 patties (whatever fits in the pan) for 1 1/2 minutes. Press down lightly with a spatula (not too hard else the meat juices squeeze out!). Flip, then immediately top with a slice of cheese. Cook for another 1 1/2 minutes (cheese will melt by itself!) then transfer burgers to a tray to rest for 3 minutes.","duration":3,"images":[],"step":6},{"title":"Preheat","description":"If your BBQ hot plate/grill is well seasoned (ie oiled), there is no need to oil before cooking. If not, lightly brush with vegetable or canola oil (or use scrunched up paper towel). Then preheat your BBQ on high until very hot and you see wisps of smoke.","images":[],"step":7},{"description":"Cook the burgers per above directions for 1 1/2 minutes on each side, topping with cheese as soon as you flip, then resting for 3 minutes. (You can also toast the buns on the grill (face down on the grills, 2 - 3 minutes.)","duration":3,"images":[],"step":8},{"description":"Slather the base of the bun with your sauce of choice. My order of assembly: lettuce, tomato, burger (x 2 for double!), gherkins, onion, sauce on bun lid, jam it on top of the stack.","images":[],"step":9},{"description":"DEVOUR with French Fries on the side.","images":[],"step":10}]', '["milk","mustard"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef-mince-recipes","burger-recipes","dinner-tonight","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e6728afe4931', 'en', 'US', 'Beef & Lentil Soup with vegetables', 'Recipe video above. Here''s a different way to use beef mince - a hearty Beef & Lentil Soup loaded with vegetables! Flavoured with spices and low on effort thanks to the ground beef, lentil soups can be so boring - but not this one. :)Healthy, hearty, economical - it''s a complete dinner made in one pot. 100% perfect for freezing, use any veg you want and switch up the spicing to your taste!', 'https://www.recipetineats.com/tachyon/2020/11/Beef-and-Lentil-Soup_9.jpg', 10, 30, 40, 6, '[{"id": "ing_moroccan_spice_mix", "quantity": {"value": 37.5, "unit": "jar"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 37.5, "unit": "pack of 1kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_lentils", "quantity": {"value": 0.469, "unit": "can of 400g"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_zucchini", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_green_beans", "quantity": {"value": 100.0, "unit": "pack"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.75, "unit": "bunch"}}]', '[{"ingredients":["2 1/2 tbsp Moroccan spice mix (store-bought)","1 tsp allspice (mixed spice will work too)","2 tsp cumin powder","2 tsp paprika","3/4 tsp black pepper","1/2 tsp salt (Note 2)"],"purpose":"My Moroccan Spice Mix (or change it up! Note 1):"},{"ingredients":["1 tbsp olive oil","2 garlic cloves (, finely chopped)","1 onion (, finely chopped (brown, white, or yellow))","500g / 1lb beef mince (ground beef) (I use lean)","1 1/4 cups dried lentils (or 2 cans, drained, Note 3)","2 carrots (*, cut into 1cm / 1/3” dice)","2 celery stalks (*, chopped into 1cm / 1/3”pieces)","2 zucchinis (*(small, or 1 large), cut into 1cm / 1/3” dice)","100g / 4 oz green beans (*, trimmed, cut into 1.5cm / 1/2” pieces)","800g / 28 oz crushed canned tomato","4 cups / 1 litre beef stock (, low sodium (Note 4))","3 cups water"],"purpose":"Soup:"},{"ingredients":["Yogurt (plain or Greek)","1/4 cup Coriander/cilantro leaves, or sliced green onions"],"purpose":"Serving:"}]', '[{"description":"Mix spices in a small bowl.","images":[],"step":1},{"title":"Saute onion & garlic","description":"Heat oil in a large pot over medium high heat. Cook onion and garlic for 3 minutes until golden on the edges.","duration":3,"images":[],"step":2},{"title":"Brown & spice beef","description":"Turn heat up to high, add beef and cook until it''s no longer red, breaking it up as you go. Add 2 tablespoons of the Spice Mix and cook it for a further 2 minutes - it will smell so good!","images":[],"step":3},{"title":"Carrot & celery","description":"Add carrot and celery, then stir for 1 minute. (If using your own veg mix, add the veg in this step that will hold up to full 25 min simmer time)","duration":1,"images":[],"step":4},{"title":"Make broth","description":"Add water, beef stock, canned tomato, lentils and remaining Spice Mix too. Give it a stir, bring to simmer, then place lid on and reduce to medium low so it''s simmering gently. Lentils will take 25 - 30 minutes to cook until soft. Very old lentils can take 5 - 10 minutes longer.","images":[],"step":5},{"description":"Simmer 15 minutes then add zucchini & green beans.","images":[],"step":6},{"description":"Simmer 10 minutes longer or until lentils are soft (ie. 25 minutes total).","images":[],"step":7},{"description":"Serve! Taste and add more salt if desired. Ladle into bowls and serve with yogurt and coriander.","images":[],"step":8}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Any flavour you want!","Western"],"categories":["beef-mince-recipes","beef-recipes","dietary","gluten-free-recipes","one-pot-recipes","quick-and-easy","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3a0f4afca90a', 'en', 'US', 'One Pot Pasta Bolognese', 'Recipe video above. For One-Pot-Pasta Cynics (and Italian cooking pursists), there''s a special message for you at the top of the post! :)This recipe is everything you love about Spaghetti Bolognese - the rich, thick tomato sauce, full flavoured (never bland!), made from scratch WITH the pasta in one pot! Excellent big batch cooking, keeps well. Tomato passata (aka tomato puree) is the key here for an instant thick, rich sauce rather than cooking down crushed tomato.Pasta types - long, short or tiny, but read recipe note 4 for adjustments.', 'https://www.recipetineats.com/tachyon/2020/09/One-Pot-Pasta-Bolognese_6.jpg', 10, 20, 30, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_italian_mixed_herbs", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.25, "unit": "jar of 50g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.25, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.7, "unit": "pack of 500g"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","1 onion (, finely chopped)","500g / 1 lb beef mince (ground beef) (, I use lean)","700g / 24.5 oz tomato passata (tomato puree) (Note 1)","3 cups beef broth (or stock cubes + water, Note 2)","2 tsp Italian mixed herbs (options, see Note 3)","1/4 - 1/2 tsp chilli flakes (red pepper flakes) (, adjust to taste)","2 tsp Worcestershire Sauce","2 tbsp tomato paste","3/4 tsp each salt and pepper","350g / 12 oz spaghetti (, uncooked (other pasta - Note 4))"]},{"ingredients":["Parmesan"],"purpose":"For serving"}]', '[{"title":"Saute onion & garlic","description":"Heat oil in a large pot over high heat. Cook garlic and onion for 2 minutes until translucent.","duration":2,"images":[],"step":1},{"title":"Cook beef","description":"Add beef and cook, breaking it up as you go.","images":[],"step":2},{"title":"Add tomato","description":"Once beef has all changed from red to brown, add tomato passata.","images":[],"step":3},{"title":"Rinse out bottle","description":"Pour some beef stock into the empty bottle, shake, then pour into the pot.","images":[],"step":4},{"title":"Add everything else","description":"Add remaining beef stock and all remaining ingredients except spaghetti. Give it a good stir, then let it come up to the boil.","images":[],"step":5},{"title":"Add spaghetti","description":"Add pasta, fanning it out around the pot. Leave for 30 seconds to start softening, then start pushing it in under the liquid.","duration":0.5,"images":[],"step":6},{"title":"Cook pasta","description":"Once fully submerged, cook for 12 minutes, stirring every minute or so, and more towards the end. At about the 8 minute mark, lower the heat to medium otherwise the base might catch (but ensure it is still bubbling gently - you don''t want pasta just bloating in warm water).","duration":12,"images":[],"step":7},{"title":"Remove from stove, toss well","description":"Take it off the stove once the pasta is JUST cooked, the tiniest bit firmer than you want, and when still saucy. Toss it for about 30 seconds or so - the sauce will reduce further, the pasta will finish cooking.","images":[],"step":8},{"description":"Serve immediately, garnished with parmesan.","images":[],"step":9}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian-esque","Western"],"categories":["beef-mince-recipes","beef-recipes","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e42c79327ae1', 'en', 'US', 'Meatloaf recipe', 'Recipe video above. Meatloaf is so much more than a giant hunk of ground beef in a loaf shape. It should ooze with flavour, be moist and tender yet not crumble apart when sliced. And the caramelised glaze is the crowning glory!', 'https://www.recipetineats.com/tachyon/2019/10/Meatloaf_3a.jpg', 15, 75, 90, 8, '[{"id": "ing_bread", "quantity": {"value": 0.188, "unit": "loaf"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_beef", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_beef", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}]', '[{"ingredients":["1 cup panko breadcrumbs (Note 1)","1 large onion (, grated (brown, yellow))","1 kg / 2 lb ground beef (mince) (, preferably not lean)","2 eggs","3 garlic cloves (, minced)","1 tsp Worcestershire Sauce","1/4 cup tomato ketchup","1/4 cup chopped parsley ((optional), or 2 tsp dried parsley or basil)","1 tsp dried thyme","2 beef bouillon cubes (, crumbled or 2 tsp beef powder (Note 2))","1 tsp black pepper"]},{"ingredients":["1/2 cup tomato ketchup","2 tbsp cider vinegar","1 tbsp brown sugar (, lightly packed)"],"purpose":"Meatloaf Glaze:"}]', '[{"description":"Preheat oven to 180C/350F. Oil or spray a loaf tin. (Note 3)","images":[],"step":1},{"title":"Glaze","description":"Mix together in a small bowl. Set aside.","images":[],"step":2},{"title":"Meatloaf","description":"Place breadcrumbs in a very large bowl. Grate over onion. Mix so the breadcrumbs are all wet. (Note 4)","images":[],"step":3},{"description":"Add remaining ingredients. Mix well using your hands. Form into a loaf shape, pinching together then smoothing over creases and cracks (helps prevent cracks during baking).","images":[],"step":4},{"description":"Transfer into loaf tin. Brush generously with glaze, using about 1/2.","images":[],"step":5},{"description":"Bake for 45 minutes. Remove from oven and brush with most of the remaining glaze. If there is excess fat pooling, scoop/pour it off.","duration":45,"images":[],"step":6},{"description":"Bake for a further 30 minutes. Remove from oven.","images":[],"step":7},{"description":"Stand for 10 minutes before turning out and cutting into thick slices. You will probably get a bit of crumbling just on the edges of the first couple of slices, this is normal and indicative of the tenderness of the meatloaf (zero crumble indicates firm packed harder meatloaf which isn''t as enjoyable!).","duration":10,"images":[],"step":8},{"description":"Ideal served with a dollop of ketchup, creamy mashed potatoes and steamed vegetables.","images":[],"step":9}]', '["egg"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef-mince-recipes","beef-recipes","main-dishes","nagis-picks","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b632459db6e4', 'en', 'US', 'Cottage Pie', 'Recipe video above. One of the greatest comfort foods of all time! A ground beef (mince) filling in a tasty gravy, topped with mashed potato. Make it a Shepherd''s Pie simply by swapping the beef for lamb.', 'https://www.recipetineats.com/tachyon/2016/10/Cottage-Pie_5.jpg', 15, 75, 90, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_beef", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_potato", "quantity": {"value": 1.2, "unit": "bag of 2kg"}}, {"id": "ing_milk", "quantity": {"value": 0.167, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.15, "unit": "pack of 200g"}}]', '[{"ingredients":["1 1/2 tbsp olive oil","2 garlic cloves (, minced)","1 onion (, finely chopped)","1 carrot (, finely chopped*)","1 celery (, finely chopped*)","750g / 1.5 lb beef mince (ground beef)","1/4 cup (40g) flour (plain / all purpose)","1/4 cup (55g) tomato paste","2 cups (500 ml) beef stock / broth (, low sodium)","1/2 cup (125 ml) red wine (or water)","1 beef bouillon cube (, crumbled (stock cube, or 1 tsp stock powder))","2 tbsp Worcestershire sauce","1 tsp dried thyme (or 3 sprigs fresh thyme)","2 dried bay leaves","3/4 tsp salt","1/2 tsp black pepper"]},{"ingredients":["1.2 kg / 2.5 lb potatoes (, peeled and cut into 2.5cm / 1\" cubes)","2/3 cup (165 ml) milk (, warmed)","2 tbsp (30g) butter"],"purpose":"Topping"},{"ingredients":["2 tbsp (30g) butter","2 tbsp (20g) parmesan, grated"],"purpose":"Parmesan Crust (optional)"}]', '[{"description":"Heat oil in a large skillet over medium high heat. Add onion and garlic, cook for 1 minute. Then add carrots and celery. Cook for 3 minutes or until softened and sweet.","duration":1,"images":[],"step":1},{"description":"Turn heat up to high. Add beef and cook, breaking it up as you go, until browned.","images":[],"step":2},{"description":"Add flour and mix in. Add tomato paste, broth, red wine, bouillon cube, Worcestershire sauce, thyme, bay leaves, salt and pepper.","images":[],"step":3},{"description":"Bring to simmer, then turn down heat so it is simmering rapidly - I have it on medium high. Cook for 30 minutes, stirring occasionally, until it reduces down to a gravy consistency (Note 1) (see video). Taste then add more salt if desired.","duration":30,"images":[],"step":4},{"description":"Transfer to 6 cup pie dish (1.5 litre / quart). Cover, cool if you have time (even overnight). Cool filling = easier to top with mash (Note 2)","images":[],"step":5},{"description":"Preheat oven to 180°C/350°F.","images":[],"step":6},{"description":"Cook potatoes in boiling water for 15 minutes or until soft. Drain then return to pot on turned off stove. Shake briefly and allow to steam dry for 30 seconds or so (Note 3).","duration":15,"images":[],"step":7},{"description":"Add butter and mash until melted, then add milk and salt. Mash until smooth.","images":[],"step":8},{"description":"Spread onto pie, use a fork to rough up the surface (rougher surface = more golden bits). Sprinkle with paremsan, drizzle with butter (or skip this and just drizzle with olive oil)","images":[],"step":9},{"title":"Bake for 25","description":"30 minutes or until golden on top and bubbling on the edges. Stick a knife into the middle to ensure it is piping hot.","duration":27.5,"images":[],"step":10},{"description":"Stand for 5 minutes before serving, garnished with fresh thyme leaves if desired.","duration":5,"images":[],"step":11}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["English","South Western"],"categories":["beef-mince-recipes","beef-recipes","lamb-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a1a938a59fa0', 'en', 'US', 'Swedish Meatballs (homemade Ikea Meatballs)', 'Recipe video above. Juicy meatballs smothered in a beautiful creamy gravy, with a hint of spicing that Swedish Meatballs are known for. Made extra soft and extra tasty by soaking fresh bread in grated onion - tried and tested technique used in my most of my meatball recipes, highly approved by readers! (See Italian Meatball reviews as an example)', 'https://www.recipetineats.com/tachyon/2017/01/Swedish-Meatballs_8.jpg', 20, 30, 50, 5, '[{"id": "ing_bread", "quantity": {"value": 0.1, "unit": "loaf"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_beef", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_pork", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_round_nutmeg", "quantity": {"value": 300.0, "unit": "jar"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_butter", "quantity": {"value": 40.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}]', '[{"ingredients":["2 slices white sandwich bread (, crusts removed, chopped into small cubes (Note 1))","1 onion (, small (brown, white or yellow))","300g / 10 oz ground beef (mince)","300g / 10 oz ground pork (mince) (, or sub with more beef (Note 2))","1 egg","1/4 tsp ground nutmeg (, preferably freshly grated)","1/4 tsp All Spice powder (Note 3)","1/4 tsp black pepper","3/4 tsp salt","1 tbsp oil"],"purpose":"Meatballs"},{"ingredients":["40g / 3 tbsp butter (, unsalted)","3 tbsp flour","2 cups beef broth/stock ((salt reduced), or sub with chicken)","1/2 cup heavy / thickened cream (Note 4)"],"purpose":"Gravy"}]', '[{"description":"Grate onion using a standard box grater (see video).","images":[],"step":1},{"description":"Scrape onion and juices into bowl. Add bread and mix well - onion juice should make bread soggy (if not, add a tiny splash of milk). Set aside to soak for 1 minute.","duration":1,"images":[],"step":2},{"description":"Add remaining Meatball ingredients EXCEPT oil. Mix well.","images":[],"step":3},{"description":"Using a tablespoon measure and measure out a heaped tablespoon (or use ice cream scooper which is what I do), dollop on work surface. Repeat with remaining mixture: 25 - 30 meatballs. Then roll into shape.","images":[],"step":4},{"description":"Cooking","images":[],"step":5},{"description":"Heat 1 tbsp oil in a skillet over medium high heat. Add half the meatballs and brown all over (but raw inside still) - about 3 minutes. Remove onto plate, then brown the remaining batch.","images":[],"step":6},{"description":"If there is lots of oil, pour off excess and discard. Lower heat to medium.","images":[],"step":7},{"description":"Add butter into skillet and melt. Add flour and stir in. Cook for 1 minute.","duration":1,"images":[],"step":8},{"title":"While mixing, add about 1/4 of the beef broth","description":"it will thicken quickly. Then gradually add remaining beef broth, stirring as you go. Switch to whisk if required to make it lump free.","images":[],"step":9},{"description":"When the liquid is simmering, add meatball and juices pooled on plate.","images":[],"step":10},{"description":"Turn up heat slightly to keep it at a rapid simmer. Cook for 8 - 10 minutes or until the liquid thickens into a thin gravy, stirring occasionally.","duration":9,"images":[],"step":11},{"description":"Add cream, simmer for a further 2 minutes then remove from stove.","images":[],"step":12},{"description":"Serve over mashed potato (or Cauliflower Mash for low carb). For a truly authentic experience, add a dollop of ligonberry jam on the side!","images":[],"step":13}]', '["egg","gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["swedish"],"categories":["beef-mince-recipes","beef-recipes","meatball-recipes","mediterranean-recipes","pork-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c23684436d63', 'en', 'US', 'Baked Ziti', 'Recipe video above. A big, juicy pasta bake! It’s meaty, cheesy, and loaded with flavour from a healthy dose of seasonings. This great American classic may well be the mother of all pasta bakes....', 'https://www.recipetineats.com/tachyon/2018/10/Baked-Ziti_0.jpg', 10, 60, 70, 6, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.6, "unit": "pack of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_ricotta", "quantity": {"value": 0.6, "unit": "tub of 250g"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.8, "unit": "pack of 125g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.5, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_fennel_seeds", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}]', '[{"ingredients":["300g / 10oz ziti or penne pasta ( (Note 1))","1 tbsp olive oil","3 garlic cloves (, minced)","1 small onion ((brown, white or yellow), finely chopped)","500g / 1 lb ground beef or pork (OR 50/50 combo (Note 2))","700g / 24 oz tomato passata (pureed tomato, Note 3)","1/2 cup water","1 tsp EACH dried basil, oregano, sugar","1 cup ricotta (, optional (Note 4))","1 cup grated mozzarella cheese (or other melting cheese)","1 cup parmesan (, freshly grated (optional))","Finely chopped parsley or basil (optional garnish)"]},{"ingredients":["2 tsp fennel seeds (optional, Note 5)","1 tbsp paprika (plain or sweet)","1/4 tsp cayenne pepper OR 3/4 tsp chilli flakes (adjust to taste)","2 tsp onion powder","1 tsp EACH salt and black pepper"],"purpose":"Seasonings:"}]', '[{"description":"Cook ziti for the recommended cooking time on the packet MINUS 2 minutes. (Note 5) Drain, then return to pot.","images":[],"step":1},{"description":"Preheat oven to 180C/350F.","images":[],"step":2},{"title":"Make Sauce","description":"Heat oil in a large skillet over high heat. Add onion and garlic and cook for 2 minutes or until onion is translucent.","duration":2,"images":[],"step":3},{"description":"Add meat and cook, breaking it up as you go. When it is just cooked, add Seasonings and cook for 2 minutes.","duration":2,"images":[],"step":4},{"description":"Add passata, water, basil, oregano and sugar. Bring to simmer, reduce heat to low and cook for 10 minutes. Adjust salt and pepper to taste (remember it gets spread across lots of pasta).","duration":10,"images":[],"step":5},{"title":"Toss Ziti with Sauce","description":"Pour about 2 cups of sauce into the pot with the ziti. Toss.","images":[],"step":6},{"title":"Assemble","description":"Spread ziti into baking dish (23x33cm / 9x13\"). Dollop with ricotta. Pour over remaining sauce. Top with cheese and parmesan.","images":[],"step":7},{"title":"Bake","description":"Cover loosely with foil. Bake 20 minutes. Remove foil, bake further 10 to 15 minutes until cheese is golden.","images":[],"step":8},{"title":"Serve","description":"Sprinkle with parsley or basil if desired, then serve!","images":[],"step":9}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["American","Western"],"categories":["beef-mince-recipes","beef-recipes","casseroles-and-cosy-bakes","dinner-tonight","italian-recipes","main-dishes","most-popular","pasta-bakes","pasta-recipes","pork-recipes","quick-and-easy","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_52381cf58f4e', 'en', 'US', 'Spaghetti Bolognese', 'Recipe video above. My everyday Bolognese recipe I make over and over again. This Meat Sauce has terrific depth of flavour for such a quick recipe - though if you have the time, it''s stellar cooked slowly for a couple of hours. My 3 "secret" tips are: Worcestershire Sauce, Beef Bouillon Cubes and a touch of sugar.', 'https://www.recipetineats.com/tachyon/2018/07/Spaghetti-Bolognese.jpg', 10, 30, 40, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_beef", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.8, "unit": "pack of 500g"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["1 1/2 tbsp olive oil","2 garlic cloves (, minced)","1 onion (, finely chopped (brown, yellow or white))","1 lb / 500g beef mince (ground beef) (OR half pork, half beef (Note 1))","1/2 cup (125 ml) dry red wine (sub water or beef broth/stock)","2 beef bouillon cubes (, crumbled OR granulated beef bouillon (Note 2))","800g / 28 oz can crushed tomato (or tomato passata)","2 tbsp tomato paste","2 tsp white sugar (, if needed (Note 3))","2 tsp Worcestershire sauce","2 dried bay leaves","2 sprigs fresh thyme (or 1/2 tsp dried thyme or oregano)","3/4 tsp cooking salt (kosher salt)","1/2 tsp black pepper"]},{"ingredients":["400 g / 13 oz spaghetti (, dried)","Parmesan cheese (and finely chopped parsley (optional))"],"purpose":"To Serve"}]', '[{"title":"Sauté","description":"Heat oil in a large pot or deep skillet over medium high heat. Add onion and garlic, cook for 3 minutes or until light golden and softened.","duration":3,"images":[],"step":1},{"title":"Cook beef","description":"Turn heat up to high and add beef. Cook, breaking it up as your go, until browned.","images":[],"step":2},{"title":"Reduce wine","description":"Add red wine. Bring to simmer and cook for 1 minute, scraping the bottom of the pot, until the alcohol smell is gone.","duration":1,"images":[],"step":3},{"title":"Simmer","description":"Add the remaining ingredients. Stir, bring to a simmer then turn down to medium so it bubbles gently. Cook for 20 - 30 minutes (no lid), adding water if the sauce gets too thick for your taste. Stir occasionally.","duration":25,"images":[],"step":4},{"title":"Slow simmer option","description":"really takes this to another level, if you have the time! Add 3/4 cup of water, cover with lid and simmer on very low for 2 - 2.5 hours, stirring every 30 minutes or so. (Note 5) Uncover, simmer 20 minutes to thicken sauce. (Note 6 for slow cooker)","images":[],"step":5},{"description":"Taste and add more salt it desired. Serve over spaghetti - though if you have the time, I recommend tossing the sauce and pasta per steps below.","images":[],"step":6},{"description":"Tossing Sauce and Spaghetti (optional, Note 4)","images":[],"step":7},{"description":"Bring a large pot of salted water to boil. Add pasta and cook per packet directions MINUS 1 minute.","images":[],"step":8},{"description":"Scoop out a mug of pasta cooking water and set aside, then drain the pasta.","images":[],"step":9},{"description":"Add pasta into the bolognese sauce with about 1/2 cup (125 ml) of reserved pasta water over medium heat. Toss gently for 1 1/2 - 2 minutes, or until the spaghetti turns red and the sauce thickens.","images":[],"step":10},{"description":"Divide between bowls. Garnish with parmesan and parsley if desired.","images":[],"step":11}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["beef-mince-recipes","beef-recipes","dinner-tonight","italian-recipes","main-dishes","pasta-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_fa5b824fb3d6', 'en', 'US', 'Spinach Beef Cannelloni (Manicotti)', 'Recipe video above. You will love how flavourful the juicy beef filling and sauce is! Too many recipes disappoint by using plain canned tomato - the sauce needs flavour! It will seem like there''s a lot of sauce (and there is) and that it''s too thin (and it is!) BUT you need it because the cannelloni sucks up a lot when it''s cooking!!! Serves 4 very hungry people, 5 normal people.', 'https://www.recipetineats.com/tachyon/2019/11/Beef-Cannelloni_8.jpg', 30, 45, 75, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_chilli", "quantity": {"value": 0.013, "unit": "pack of 100g"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_spinach", "quantity": {"value": 250.0, "unit": "bag of 250g"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_nelloni_tubes", "quantity": {"value": 21.0, "unit": "unit"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.6, "unit": "pack of 125g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","1/2 onion (, finely chopped)","1 carrot (, small, finely chopped (optional))","1 celery rib (, finely chopped (optional))","800g / 28oz crushed tomato (, canned)","2 cups (500ml) chicken stock / broth (, low sodium (or vegetable))","1/2 tsp EACH thyme, oregano, salt, pepper","1/4 tsp chilli flakes (, optional)"],"purpose":"Cannelloni Sauce:"},{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","1/2 onion (, finely chopped)","500g / 1lb beef mince (, lean)","250g / 8oz frozen spinach, chopped (, thawed, excess liquid squeezed out (Note 1))","1 beef bouillon cube (, crumbled (Note 2))","1/2 tsp pepper","1 tsp Worcestershire Sauce"],"purpose":"Spinach Beef Filling:"},{"ingredients":["21 - 24 cannelloni tubes (220g/7oz) (OR 10 Manicotti tubes (Note 3))","2 cups mozzarella cheese (, freshly grated (or other melting cheese))","Chopped parsley (, garnish (optional))"],"purpose":"Cannelloni:"}]', '[{"description":"Cannelloni Sauce:","images":[],"step":1},{"description":"Heat oil in a large saucepan or pot over medium high heat. Add garlic and onion, cook 2 minutes. Add carrot and celery, cook 5 minutes.","images":[],"step":2},{"description":"Add remaining Sauce ingredients then stir. Bring to simmer, lower heat to medium, cover with lid and simmer for 10 minutes.","duration":10,"images":[],"step":3},{"description":"Use a stick blender to blitz until smooth (or cool slightly and use blender or food processor). Set aside.","images":[],"step":4},{"description":"Spinach Beef Filling:","images":[],"step":5},{"description":"Heat oil in a large skillet over high heat. Add onion and garlic, cook 2 minutes.","images":[],"step":6},{"description":"Add beef and cook, breaking it up as you go, until it all changes from red to brown.","images":[],"step":7},{"description":"Stir in spinach, then add crumbled beef cube, Worcestershire sauce, pepper and 1 cup of Cannelloni Sauce. Stir, cook 2 minutes.","images":[],"step":8},{"description":"Remove and cool slightly.","images":[],"step":9},{"description":"Assembly and Baking:","images":[],"step":10},{"description":"Preheat oven to 180°C/350°F.","images":[],"step":11},{"description":"Transfer Beef Filling into a piping bag with a wide nozzle. Stand cannelloni tubes upright in a container, then pipe filling in. (Or do this step with teaspoon/finger/dinner knife!).","images":[],"step":12},{"description":"Spread about 1 1/4 cups Sauce in a 23x33cm / 9x13\" dish. Lay the cannelloni on top, then pour over remaining Sauce.","images":[],"step":13},{"description":"Sprinkle with cheese, loosely cover with foil.","images":[],"step":14},{"description":"Bake 25 minutes, remove foil then bake a further 10 minutes until the cheese is bubbly with some golden spots.","images":[],"step":15},{"description":"Remove from oven, sprinkle with parsley if using then serve!","images":[],"step":16}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["American-Italian","Italian","Western"],"categories":["beef-mince-recipes","beef-recipes","italian-recipes","pasta-bakes","pasta-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a0e55a1c3079', 'en', 'US', 'One Pot Chili Mac and Cheese', 'Recipe video above. A homemade Chili with the addition of macaroni and cheese = Chili Mac ‘n Cheese! This is terrifically moorish and a fabulous one pot meal. Super quick too! The key with this recipe is to turn the stove off as soon as the pasta is just cooked - it will keep cooking in the residual heat. Spice level with 1/2 tsp cayenne pepper = warm hum. Dial up or down as you please!', 'https://www.recipetineats.com/tachyon/2017/10/Chilli-Mac_0.jpg', 10, 15, 25, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_kidney_beans", "quantity": {"value": 1.05, "unit": "can of 400g"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}]', '[{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","1 onion (, finely chopped)","1 red capsicum / bell pepper (, chopped)","500g / 1 lb ground beef (mince) (, I use lean)","800g / 28 oz crushed canned tomato","420g / 14 oz can red kidney beans (, drained)","2 1/2 cups (625 ml) beef broth (chicken broth also ok)","250g / 8 oz elbow macaroni pasta ((elbow pasta), uncooked)","2 cups (200g) shredded cheese (cheddar, Monterey Jack, tasty cheese)","1/4 cup coriander / cilantro ( finely chopped, for garnish)"]},{"ingredients":["1/2 tsp cayenne pepper ( or pure chilli powder (adjust spiciness to taste) (Note 1))","2 tsp paprika powder","2 tsp cumin powder","1 1/2 tsp onion powder (can sub garlic powder)","1 tsp dried oregano","1/2 tsp black pepper","1 1/4 tsp salt"],"purpose":"Spices (Homemade Chili Powder):"}]', '[{"description":"Heat oil in large pot over high heat. Add garlic and onion, cook for 1 minute. Then add capsicum and cook until onion is translucent.","duration":1,"images":[],"step":1},{"description":"Add beef and cook, breaking it up as you go.","images":[],"step":2},{"description":"Once the beef turns from red to brown, add remaining ingredients except cheese. Stir, bring to simmer, then turn the heat down to medium.","images":[],"step":3},{"description":"Cover and cook for 12 minutes or until the macaroni is al dente, meaning just cooked, still a tiny bit on the firm side. It should be saucy but not tons of liquid (see video).","duration":12,"images":[],"step":4},{"description":"Turn the stove OFF but leave the pot on the stove. Stir through half the cheese – it should be a bit saucy. Adjust salt and pepper to taste. Top with remaining cheese, put the lid back on and leave until the cheese melts - about 2 minutes (sauce will absorb further during this period).","images":[],"step":5},{"description":"Sprinkle with coriander, if desired, and serve immediately.","images":[],"step":6}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["American"],"categories":["beef-mince-recipes","beef-recipes","casseroles-and-cosy-bakes","dinner-tonight","main-dishes","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e28f756a4177', 'en', 'US', 'Mexican Ground Beef Casserole with Rice (Beef mince!)', 'Recipe video above. A big juicy pot of beef and rice loaded with Mexican flavours! The rice is tender and perfectly cooked, and the tomato sauce is generously flavoured with a Mexican Spice mix. A quick dinner made in one pot with not much prep!', 'https://www.recipetineats.com/tachyon/2019/09/Mexican-Ground-Beef-Casserole-with-Rice_0.jpg', 10, 20, 30, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 150.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_white_rice", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.375, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_black_beans", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}]', '[{"ingredients":["2 tbsp olive oil","1 onion (, finely chopped)","3 garlic cloves (, minced)","500g (1 lb) ground beef ((mince), lean)","1/3 cup tomato paste","1 1/4 cup long grain white rice (, uncooked (Note 1))","2.5 cups (625 ml) chicken broth/stock (, low sodium)","400g (14oz) can corn kernels (, drained (Note 2))","400g (14oz) can black beans (, drained (or other beans))","1 capsicum/bell pepper (, diced)","1 cup green onions/shallots","2 cups (200g) cheese (, shredded (anything that melts! Note 3))"]},{"ingredients":["0.5 tsp cayenne pepper (Note 4)","1.5 tbsp dried oregano","3 tsp cumin","3 tsp coriander","3 tsp onion powder","2 tsp paprika","1.5 tsp salt"],"purpose":"MEXICAN SPICES:"}]', '[{"description":"Heat oil in a large pot over high heat. Add garlic and onion, cook 1 1/2 minutes until onion is translucent.","images":[],"step":1},{"description":"Add beef and cook, breaking it up as you go, until you no longer see raw meat (about 2 minutes).","images":[],"step":2},{"description":"Add Mexican Spices and cook for 30 seconds.","duration":0.5,"images":[],"step":3},{"description":"Add capsicum and cook for 1 minute.","duration":1,"images":[],"step":4},{"description":"Add tomato paste and broth, stir to mix in.","images":[],"step":5},{"description":"Add rice, corn and black beans.","images":[],"step":6},{"description":"Stir, bring to simmer then cover and lower heat to medium low (simmering gently). Cook 15 minutes.","images":[],"step":7},{"description":"Remove lid, quickly stir through green onion and HALF the cheese.","images":[],"step":8},{"description":"Smooth top then sprinkle on remaining cheese. Cover and leave for 1 minute just to melt cheese.","duration":1,"images":[],"step":9},{"description":"Remove from stove and serve immediately, garnished with more green onion if desired.","images":[],"step":10}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Tex-Mex","Western"],"categories":["beef-mince-recipes","beef-recipes","casseroles-and-cosy-bakes","dinner-tonight","mexican-recipes","one-pot-recipes","quick-and-easy","rice-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c1b7bdfa33cd', 'en', 'US', 'Beef Enchiladas', 'Recipe video above. Moreishly delish! These beef enchiladas are made extra tasty with a juicy filling made with beef, refried beans and a homemade Enchilada spice mix. The refried beans are excellent here - fills it out, makes the Filling juicy and adds flavour!', 'https://www.recipetineats.com/tachyon/2016/06/Beef-Enchiladas_main.jpg', 10, 35, 45, 4, '[{"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.5, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.5, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 5.0, "unit": "pack of 1kg"}}, {"id": "ing_beef", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_refried_beans", "quantity": {"value": 400.0, "unit": "pack"}}, {"id": "ing_black_beans", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_tortillas", "quantity": {"value": 8.0, "unit": "pack of 8"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 tsp each onion & garlic powder (Note 1)","1 tbsp each cumin powder, paprika and dried oregano","1/2 - 1 tsp cayenne pepper (optional, spiciness)"],"purpose":"Spice Mix"},{"ingredients":["2 tbsp olive oil","3 tbsp flour (, plain/all purpose)","2 cups (500ml) chicken stock / broth (, low sodium)","1 1/2 cups (375 ml) tomato passata OR US 1 can (8 oz) canned tomato sauce (eg Hunts) (Note 2)","1/4 tsp each salt and pepper"],"purpose":"Enchilada Sauce"},{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","1 onion (, finely chopped (~1 cup))","1 lb / 500g ground beef (mince)","400g / 14oz refried beans (1 can, I use Old El Paso)","400g / 14oz black beans, drained (1 can, Note 3)"],"purpose":"Beef"},{"ingredients":["8 tortillas (or burrito wraps)","1.5 cups (150g) grated melting cheese, or more (I like Monterey Jack, tasty or cheddar cheese)","Cilantro/coriander leaves (, roughly chopped (optional garnish))"],"purpose":"Enchiladas"}]', '[{"description":"Mix together Spice Mix ingredients. Set aside.","images":[],"step":1},{"description":"Enchilada Sauce","images":[],"step":2},{"description":"Heat oil in a large saucepan over medium heat. Add flour and mix to combine into a paste. Cook for 1 minute, stirring constantly.","duration":1,"images":[],"step":3},{"description":"Add 1/2 cup chicken broth, whisk straight away then it will turn into a thick smooth paste quite quickly.","images":[],"step":4},{"description":"Add remaining chicken broth, passata, salt, pepper and 2 tablespoons of SPICE MIX. Whisk","images":[],"step":5},{"description":"Increase heat slightly to medium high. Cook for 3 to 5 minutes, whisking regularly, until the sauce thickens to the consistency of thick syrup (see video). Remove from stove.","duration":4,"images":[],"step":6},{"description":"Preheat oven to 180C/350F.","images":[],"step":7},{"description":"Heat oil in a skillet over high heat. Add garlic and onion, cook for 2 minutes.","duration":2,"images":[],"step":8},{"description":"Add beef and cook for 2 minutes, breaking it up as you go. Add remaining Spice Mix. Cook for a further 2 minutes or until completely brown.","duration":2,"images":[],"step":9},{"description":"Add refried beans, black beans, about 1/4 cup of Enchilada Sauce + salt & pepper. Mix (Note 4) and cook for 2 minutes then remove from stove (see video).","duration":2,"images":[],"step":10},{"description":"Smear a bit of Sauce on the bottom of a baking dish (stops sliding).","images":[],"step":11},{"description":"Place filling on the lower third of a tortilla. Roll up then place in the baking dish, seam side down. Repeat with remaining Filling & Tortillas.","images":[],"step":12},{"description":"Pour Sauce over the Enchiladas, top with cheese, bake for 10 minutes covered (Note 5) then 10 minutes uncovered. Serve hot!","duration":10,"images":[],"step":13}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["beef-mince-recipes","beef-recipes","dinner-tonight","enchiladas","main-dishes","mexican-recipes","most-popular","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1efdb2577c3a', 'en', 'US', 'Mexican Stuffed Peppers', 'Recipe video above. That moment when you cut into these Mexican Stuffed Peppers and the cheesy, flavour loaded juicy beef and rice filling comes oozing out.....THEN you find out it''s only 387 calories for a giant stuffed capsicum?? It''s a little food miracle, right there. 🙌🏼', 'https://www.recipetineats.com/tachyon/2019/08/Mexican-Stuffed-Peppers_3.jpg', 20, 90, 110, 5, '[{"id": "ing_capsicum", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 150.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_beef", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_rice", "quantity": {"value": 75.0, "unit": "pack"}}, {"id": "ing_corn", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.2, "unit": "pack of 125g"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_guacamole", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["5 capsicum / peppers (, large about 12cm/4.5\" tall (Note 1))","1 tbsp olive oil","1 onion (, chopped (brown, white, yellow))","3 garlic cloves (, minced)","350g (12oz) ground beef ((mince), lean)","1/4 cup tomato paste","1 1/4 cups (315 ml) chicken broth/stock (, low sodium)","1/2 cup long or medium grain rice (, uncooked (Note 2))","1 cup corn kernels (Note 3)","1 cup green onions (, finely sliced (or red onion))","1 1/2 cups (150g) mozzarella (, shredded)","1/2 cup (125 ml) water"]},{"ingredients":["1/2 tsp cayenne pepper","1 tbsp dried oregano","2 tsp cumin","2 tsp coriander","1.5 tsp onion powder","3/4 tsp salt"],"purpose":"Mexican Spices:"},{"ingredients":["Guacamole (Note 5 Quick Guac)","Sour Cream","1 tbsp fresh coriander/cilantro (, finely chopped)"],"purpose":"For serving (optional):"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Hollow Peppers:","images":[],"step":2},{"description":"Using a small knife, cut around the top of the capsicum at downwards 45 degree angle. Remove top, empty seeds. If capsicum bottoms aren''t quite level, cut so they''ll sit flat. (Be careful to cut off as little as possible so you don'''' accidentally cut a hole in the bottom.)","images":[],"step":3},{"description":"Place capsicums in a baking dish that will fit them snugly (Note 4)","images":[],"step":4},{"description":"Heat oil in a large skillet over high heat,","images":[],"step":5},{"description":"Add onion and garlic, cook for 2 minutes.","duration":2,"images":[],"step":6},{"description":"Add beef and cook, breaking it up as you go, until it''s all changed from pink to brown.","images":[],"step":7},{"description":"Add Spices, stir through. Then add Tomato paste and cook for 1 minute.","duration":1,"images":[],"step":8},{"description":"Add rice, corn and chicken broth. Stir, bring to simmer, place lid on and lower heat to medium low.","images":[],"step":9},{"title":"Cook for 13","description":"15 minutes until rice is JUST cooked - mixture should be fairly loose still at this stage, not thick and stodgy (see video).","duration":14,"images":[],"step":10},{"description":"Stir in green onion.","images":[],"step":11},{"description":"Spoon half the filling into the prepared capsicums.","images":[],"step":12},{"description":"Top with half the cheese, then fill to top with remaining beef rice.","images":[],"step":13},{"description":"Place capsicum lids back on, pour 1/2 cup water into the pan.","images":[],"step":14},{"description":"Cover tightly with foil, bake 45 minutes.","images":[],"step":15},{"description":"Remove foil and capsicum lids. Top with remaining cheese. Bake further 5 to 10 minutes, just until cheese is melted.","images":[],"step":16},{"title":"Serve with sour cream and Guacamole! Quick Guac","description":"Note 5.","images":[],"step":17}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican","Western"],"categories":["beef-mince-recipes","dietary","low-calorie-recipes","mexican-recipes","rice-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_84fd03d8fe70', 'en', 'US', 'Baked Spaghetti', 'Recipe video above. It''s your favourite Bolognese - in the form of a juicy pasta bake! Do a quick simmer - or go all out and slow cook for a couple of hours for a richer sauce and melt-in-your-mouth beef. **FREEZER BEAUTY!** Can even bake from frozen (see notes).', 'https://www.recipetineats.com/tachyon/2019/07/Baked-Spaghetti_1.jpg', 15, 90, 105, 10, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_beef", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.25, "unit": "bottle of 750ml"}}, {"id": "ing_beef", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_bay_leaf", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_cheese", "quantity": {"value": 8.0, "unit": "block of 250g"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.6, "unit": "pack of 125g"}}]', '[{"ingredients":["2 tbsp olive oil","3 garlic cloves (, minced)","1 onion (, finely chopped)","1 carrot (, finely diced (optional))","1 stick celery (, finely diced (optional))","750g / 1.5lb ground beef (mince)","3/4 cup (185ml) dry red wine (or sub with water or beef broth/stock)","3 beef bouillon cubes (, crumbled (Note 1))","1.2kg / 2.4 lb crushed tomato (, canned)","1/4 cup tomato paste","1 - 3 tsp white sugar (, if needed (Note 2))","2 tsp Worcestershire sauce","3 dried bay leaves","2 sprigs fresh thyme (or 1/2 tsp dried thyme or oregano)","Salt and pepper"],"purpose":"Bolognese Sauce:"},{"ingredients":["500g/ 1lb spaghetti","8 - 10 slices Swiss cheese ((or other type), enough for a layer)","2 cups (200g) mozzarella cheese, shredded"],"purpose":"Spaghetti Bake:"}]', '[{"description":"Heat oil in a large, heavy based pot over medium high heat.","images":[],"step":1},{"description":"Add garlic and onion, cook 2 minutes.","images":[],"step":2},{"description":"Add celery and carrot, cook 3 minutes.","images":[],"step":3},{"description":"Turn heat up to high, add beef and cook, breaking it up as you go.","images":[],"step":4},{"description":"Once beef is brown, add wine. Simmer rapidly for 2 minutes.","duration":2,"images":[],"step":5},{"description":"Add remaining Sauce ingredients, stir.","images":[],"step":6},{"description":"Bring to simmer, lower heat, cover with lid. Simmer for 45 minutes (minimum) or 1.5 - 2 hours (best!).","duration":45,"images":[],"step":7},{"title":"If liquid evaporates too much, add water","description":"should be saucy (see video/pics). Adjust salt and pepper to taste.","images":[],"step":8},{"description":"Assemble & Bake:","images":[],"step":9},{"description":"Preheat oven to 180C/350F.","images":[],"step":10},{"description":"Cook pasta per packet directions, minus 1 minute.","images":[],"step":11},{"description":"Drain, then return into pot.","images":[],"step":12},{"description":"Add just over half the Sauce, toss.","images":[],"step":13},{"description":"Spread half the pasta in a casserole pan, spread with half remaining Sauce.","images":[],"step":14},{"description":"Top with cheese slices, then remaining pasta, remaining Sauce, finish with mozzarella.","images":[],"step":15},{"description":"Cover loosely with foil (so cheese doesn''t stick), bake 25 minutes.","images":[],"step":16},{"description":"Remove foil (reserve), bake further 10 minutes than remove.","images":[],"step":17},{"title":"Cover loosely with foil, stand 10","description":"15 minutes. Then cut slices with a knife and use a spatula to serve pieces like lasagna!","images":[],"step":18}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef-mince-recipes","casseroles-and-cosy-bakes","pasta-bakes","pasta-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_34a71665f297', 'en', 'US', 'Moussaka (Greek Eggplant Lasagna)', 'Recipe video above. A traditional recipe for an iconic Greek dish from a wonderful cookbook called The Food And Cooking Of Greece by Sara Nassopoulos. Layers of soft eggplant, rich beef or lamb filling lightly spiced with oregano and cinnamon, topped with a thick layer of bechamel sauce. It looks like a lot of steps but the recipe has a nice flow to it - I''ve popped prompts in the steps. 🙂', 'https://www.recipetineats.com/tachyon/2019/03/Greek-Moussaka_3-re-edited-SQ.jpg', 40, 30, 70, 6, '[{"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_lamb", "quantity": {"value": 0.635, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.635, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.635, "unit": "kg"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_cinnamon", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_butter", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.625, "unit": "L"}}, {"id": "ing_nutmeg", "quantity": {"value": 1.25, "unit": "jar"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.006, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 0.062, "unit": "loaf"}}]', '[{"ingredients":["1 kg / 2 lb eggplant (aubergines) (, 0.75cm / 0.3\" thick slices)","1 tsp salt","2 - 3 tbsp olive oil"],"purpose":"Eggplant"},{"ingredients":["1 tbsp olive oil","1 onion (, diced (brown, white, yellow))","3 garlic cloves (, minced)","1.4 lb / 700 g ground beef or lamb (mince) (Note 1)","1/2 cup red wine (, dry (optional))","14 oz /400g crushed tomatoes","3 tbsp tomato paste","1 cup beef broth/stock (Note 2)","1 beef bouillon cube (, crumbled (or 1 tsp powder))","2 bay leaves","1.5 tsp sugar (any)","2 tsp dried oregano","1/2 tsp cinnamon (or 1 stick, use whole)","3/4 tsp salt"],"purpose":"Filling"},{"ingredients":["4 tbsp (60g) butter","5 tbsp plain flour","2 1/2 cups milk (any fat %)","1/4 tsp nutmeg, freshly grated (optional)","1/2 cup parmesan cheese, grated (or Kefalotiri Cheese) (Note 3)","1 egg","1 egg yolk","1 1/4 tsp Vegeta, vegetable or chicken stock powder (or salt) (Note 4)","1/4 tsp pepper"],"purpose":"Bechamel Sauce"},{"ingredients":["1/3 cup panko breadcrumbs (Note 5)"],"purpose":"Topping"}]', '[{"description":"Eggplant (Note 6)","images":[],"step":1},{"description":"Place eggplant slightly overlapping in a large colander. Sprinkle with some salt. Repeat with remaining eggplant.","images":[],"step":2},{"description":"Leave to sweat for 30 minutes. Meanwhile, make Meat Sauce and Béchamel Sauce.","duration":30,"images":[],"step":3},{"description":"Preheat oven to 240C/450F.","images":[],"step":4},{"title":"Pat eggplant dry","description":"make sure to do this well, otherwise it''s too salty. Lay on parchment paper lined trays (you might need 3 trays, work in batches), brush with oil.","images":[],"step":5},{"title":"Bake 15","description":"20 minutes or until lightly browned and softened . Remove and set aside to cool slightly.","images":[],"step":6},{"description":"Heat olive oil in a large skillet or pot over high heat, then cook the garlic and onion for 2 minutes.","duration":2,"images":[],"step":7},{"description":"Add the beef or lamb and cook until it changes from pink to brown, breaking it up as you go.","images":[],"step":8},{"description":"Add wine, cook for 1.5 minutes or until alcohol smell is gone.","images":[],"step":9},{"description":"Add remaining ingredients and stir to combine. Bring to a simmer, then lower heat to medium low and cook for 15 minutes, or until reduced to a thick sauce.","duration":15,"images":[],"step":10},{"description":"Melt butter in a pan over medium heat. Add flour and cook for 1 minute, stirring constantly.","duration":1,"images":[],"step":11},{"description":"Stirring constantly, slowly add the milk. Then stir regularly for 3 to 5 minutes or until it thickens so that it thickly coats the back of a wooden spoon (see video / step photos).","duration":4,"images":[],"step":12},{"description":"Remove from the stove and whisk in cheese, nutmeg, Vegeta/stock powder (or salt) and pepper.","images":[],"step":13},{"description":"Allow to cool for 5 minutes, then whisk the eggs in. Cover with lid until required.","duration":5,"images":[],"step":14},{"description":"Lower oven to 180C/350F (all oven types).","images":[],"step":15},{"description":"Place half the eggplant in the bottom of a baking dish (I used my 26cm/9\" Lodge skillet), then top with all the Filling.","images":[],"step":16},{"description":"Top with remaining eggplant, then pour over the Béchamel Sauce, sprinkle with breadcrumbs.","images":[],"step":17},{"title":"Bake for 30","description":"40 minutes or until golden brown. Allow to stand for 10 minutes before serving.","duration":35,"images":[],"step":18}]', '["egg","gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Greek"],"categories":["beef-mince-recipes","beef-recipes","casseroles-and-cosy-bakes","greek-recipes","mediterranean-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c9b653ea691c', 'en', 'US', 'Cheeseburger Casserole (Homemade Hamburger Helper)', 'Recipe video above. It''s beefy, cheesy and saucy. If you love Cheeseburgers and Mac and Cheese, then you will LOVE this Cheeseburger Casserole! A homemade version of Hamburger Helper, the boxed pasta. One pot, 30 minutes start to finish!', 'https://www.recipetineats.com/tachyon/2016/08/Cheeseburger-Casserole_Hamburger-Helper_0.jpg', 10, 20, 30, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.68, "unit": "pack of 500g"}}, {"id": "ing_corn", "quantity": {"value": 0.188, "unit": "can of 400g"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_hot_sauce", "quantity": {"value": 0.1, "unit": "bottle of 150ml"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.8, "unit": "pack of 125g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}]', '[{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","1 onion, chopped","1 small carrot * (, chopped (optional))","1 celery stalk * (, chopped (optional))","500 g/ 1 lb ground beef (mince) (, preferably lean)","12 oz / 340g dried macaroni (, uncooked)","1/2 cup frozen corn * (, optional)","2 cups chicken broth/stock, low sodium","1 tbsp hot sauce or Sriracha sauce (, adjust to taste)","1 tsp American chili powder (Note 1)","1 tsp dried oregano","1 tsp garlic powder (, or sub onion powder)","800 g / 28 oz crushed tomato","2 tbsp tomato paste","1 1/4 tsp salt","1/2 tsp black pepper","1.5 - 2 cups (150 - 200g) cheddar or tasty cheese, shredded (Note 3)","1 cup (100g) mozzarella cheese (, for topping)"]},{"ingredients":["1 green onion (, sliced)"],"purpose":"Garnish (optional)"}]', '[{"description":"Heat oil in a dutch oven or large deep skillet over medium high heat.","images":[],"step":1},{"description":"Add onion and garlic, cook 1 minute.","images":[],"step":2},{"description":"Add celery and carrot, cook 3 minutes until soft.","images":[],"step":3},{"description":"Increase heat to high and add beef. Cook, breaking it up as you go, until no longer pink - 3 minutes.","images":[],"step":4},{"description":"Add remaining ingredients EXCEPT cheese. Stir to combine, add macaroni, then turn down to medium or medium low so it''s simmering gently.","images":[],"step":5},{"description":"Cover, cook 8 minutes. Pasta should be just about cooked, and still nice and saucy.","images":[],"step":6},{"description":"Add cheddar cheese, stir. Top with mozzarella cheese.","images":[],"step":7},{"description":"Cover with lid, cook for a further 2 minutes.","images":[],"step":8},{"title":"Remove from stove. The pasta should now be cooked","description":"tender but firm, not mushy, slick with sauce, not dried out.","images":[],"step":9},{"description":"Serve immediately, garnished with green onions, if using.","images":[],"step":10}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["American","Western"],"categories":["beef-mince-recipes","beef-recipes","casseroles-and-cosy-bakes","dinner-tonight","main-dishes","most-popular","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7d3ada56b5c4', 'en', 'US', 'Beef Burritos', 'Recipe video above. Simple, super tasty everyday beef burritos made with a homemade beef mince filling (ground beef), rice and your choice of fillings. One of the best freezer meals ever!', 'https://www.recipetineats.com/tachyon/2017/06/Beef-Burritos.jpg', 15, 20, 35, 6, '[{"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 5.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_tortillas", "quantity": {"value": 6.0, "unit": "pack of 8"}}, {"id": "ing_rice", "quantity": {"value": 450.0, "unit": "pack"}}, {"id": "ing_cabbage", "quantity": {"value": 9.0, "unit": "head"}}, {"id": "ing_corn", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_black_beans", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_tomato", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 5.0, "unit": "pack of 1kg"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}]', '[{"ingredients":["1 tsp each onion powder (, dried oregano, salt)","2 tsp each dried cumin powder (, paprika)","1/4 tsp black pepper","¼ tsp cayenne pepper (, or to taste (optional))"],"purpose":"Burrito Seasoning:"},{"ingredients":["1/2 tbsp olive oil","2 garlic cloves","½ onion (, finely chopped)","500g / 1 lb beef mince (ground beef), I use lean","2 tbsp tomato paste","3 tbsp water"],"purpose":"Beef:"},{"ingredients":["6 - 8 large soft flour tortillas or round wraps (~25cm/10”+) (Note 1)","3 cups cooked rice (, warm not piping hot (I use white long grain))","3 cups iceberg lettuce or cabbage (, finely sliced (use cabbage if freezing))","1 cup corn kernels (I use canned, drained)","1 cup black beans (I use canned, drained)","3 tomatoes, deseeded and diced","1/2 red onion (, finely chopped)","Finely chopped coriander / cilantro (optional)","1 1/2 cups / 150g shredded cheese of choice (melting kind)"],"purpose":"Burritos:"}]', '[{"description":"Heat oil in a skillet over high heat. Add garlic and onion, cook for 2 minutes until onion is lightly browned. Add beef and cook, breaking it up as you go, until it turns from red to brown.","duration":2,"images":[],"step":1},{"description":"Add Taco Seasoning (or use 1 packet store bought) and cook for 1 minute. Then add tomato paste and water, cook for 3 minutes until the water is mostly evaporated but the beef is still juicy, not dried out. Set aside to cool for 10 minutes – piping hot filling will steam the burrito, making the tortilla soggy.","duration":1,"images":[],"step":2},{"title":"Optional","description":"If not warming rolled burrito, warm the tortillas before rolling (per packet directions).","images":[],"step":3},{"title":"Place a burrito on a work surface. Place 1/4","description":"1/3 cup of rice just below the centre. Top with 1/4 - 1/3 cup beef, then some lettuce, corn, black beans, tomato, a sprinkle of red onion, coriander and cheese.","images":[],"step":4},{"description":"Fold up the bottom to cover the filling then fold the edges in (video helpful to see how to do this). Roll up tightly, then wrap in foil. Serve as is or heat per below.","images":[],"step":5},{"title":"HEATING","description":"To warm through, pan fry (dry pan) in the foil over medium high heat for a few minutes on each side to slightly crisp and warm the outside. Or for 10+ minutes on a medium low heat if you want to melt the cheese. Or they can be baked at 180C/350F for 20 minutes in the foil – this will warm them all the way through and crisp up the tortilla slightly. If they are straight from the fridge, they will take around 30 minutes to warm through.","duration":20,"images":[],"step":6},{"description":"Burritos are best served with something to dollop/dip - sour cream (or yoghurt) and some sort of chilli sauce are my usual because it''s easy. When I''m making more of an effort, I use Restaurant Style Salsa or Guacamole.","images":[],"step":7}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Mexican","Tex-Mex"],"categories":["beef-mince-recipes","beef-recipes","burritos","dinner-tonight","main-dishes","mexican-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_494a09f6bc64', 'en', 'US', 'Italian Meatballs (Extra Soft and Juicy!)', 'Recipe video above. These are my idea of "perfect" meatballs. I make them extra soft and juicy by using bread instead of breadcrumbs, and the grated onion is my secret tip for adding extra flavour into this. Plus, no need to sauté diced onion before mixing it in! Served with a rich tomato sauce made extra tasty by cooking it in the same pan that the meatballs are browned in.', 'https://www.recipetineats.com/tachyon/2015/08/Italian-Meatballs_original.jpg', 20, 20, 40, 4, '[{"id": "ing_bread", "quantity": {"value": 1.25, "unit": "loaf"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_beef", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_pork", "quantity": {"value": 0.085, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.68, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_italian_herb_mix", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}]', '[{"ingredients":["1 lightly packed cup of diced white sandwich bread (, crusts removed (Note 1 for SUB))","1 small onion (brown, white or yellow)","14 oz / 400 g ground beef (mince)","3 oz / 100g ground pork (mince), or sub with more beef (Note 2)","1 egg","1/4 cup fresh parsley (, finely chopped (Note 3))","2 garlic cloves (, minced)","1/4 cup Parmigiano-Reggiano ((or parmesan), freshly grated)","3/4 tsp salt","1/4 tsp black pepper"],"purpose":"Meatballs"},{"ingredients":["2.5 tbsp olive oil","2 garlic cloves (, minced)","3/4 cup onion (, finely chopped (white, brown or yellow))","24 oz / 700 g tomato passata (Tomato Puree in US/CAN - Note 4)","1/2 cup water","1 tsp red pepper flakes (chili flakes)","3 tsp dried Italian herb mix (parsley, basil, thyme, oregano)","1 tsp salt","Black pepper"],"purpose":"Cooking Meatballs & Sauce"},{"ingredients":["Pasta of choice","Parmesan","Parsley (, finely chopped (optional))"],"purpose":"To Serve"}]', '[{"description":"Grate the onion using a standard box grater in a large bowl until you have about 1/2 cup of grated onion and juices.","images":[],"step":1},{"description":"Add bread, mix to combine so the onion juice soaks the bread and disintegrates. Set aside while you prep the other ingredients (5 min or so).","images":[],"step":2},{"description":"Add all the remaining Meatball ingredients. Use hands to mix well.","images":[],"step":3},{"description":"Measure out a heaped tablespoon and roll lightly to form a ball. Repeat with remaining mixture. (Note 5)","images":[],"step":4},{"description":"Heat 1 1/2 tbsp olive oil in a large non stick fry pan over medium high heat. Add the meatballs and brown all over - about 3 - 4 minutes.","images":[],"step":5},{"description":"When they are browned but NOT cooked through, carefully transfer them onto a plate.","images":[],"step":6},{"description":"Cooking & Sauce:","images":[],"step":7},{"description":"Heat 1 tbsp of olive oil into the fry pan.","images":[],"step":8},{"description":"Add the onion and garlic and sauté for 2 to 3 minutes until translucent. Add the remaining Sauce ingredients. Bring to a simmer, then turn down to medium low so it bubbles gently rather than splattering everywhere.","duration":2.5,"images":[],"step":9},{"description":"Carefully transfer the meatballs and any juices that have pooled on the plate into the Sauce.","images":[],"step":10},{"title":"Cook the meatballs for 8","description":"10 minutes, turning and stirring occasionally. Adjust Sauce salt and pepper to taste.","duration":9,"images":[],"step":11},{"description":"While the meatballs are cooking, cook your pasta of choice.","images":[],"step":12},{"description":"Serve the meatballs on pasta, garnished with extra parmesan and parsley if using.","images":[],"step":13}]', '["egg","gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["beef-mince-recipes","beef-recipes","dinner-tonight","italian-recipes","main-dishes","meatball-recipes","most-popular","pasta-recipes","sunday-supper"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a35df47910fa', 'en', 'US', 'Easy Taco Soup', 'Recipe video above. All the fixings of a taco - in soup form! Don''t skip the toppings - they totally make it! At least cheese and sour cream or yoghurt are essential.', 'https://www.recipetineats.com/tachyon/2017/02/Taco-Soup-5-1.jpg', 10, 20, 30, 4, '[{"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.312, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 5.0, "unit": "pack of 1kg"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_black_beans", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_corn", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_chilli", "quantity": {"value": 1.2, "unit": "pack of 100g"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_corn", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["1 tsp EACH garlic powder, onion powder and cayenne pepper","2 tsp EACH dried oregano and paprika","2 1/2 tsp cumin powder","3/4 tsp salt","1/2 tsp black pepper"],"purpose":"Homemade Taco Seasoning (Note 1)"},{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","1 onion (, finely chopped (brown or yellow))","500 g / 1 lb ground beef ((mince), lean)","400 g/ 14 oz can black beans (1 can) (, drained and rinsed (Note 2))","400g / 14oz can corn kernels (1 can) (, drained and rinsed)","120 g / 4.5 oz canned green chili (Note 3)","800 g / 28 oz canned crushed tomato","2 cups beef broth"],"purpose":"Soup"},{"ingredients":["Shredded cheese (essential!)","Sour cream (or yoghurt (essential!))","Fresh coriander/cilantro leaves or shallots/scallions (, finely sliced)","Corn chips","Other options: diced avocado, squeeze of lime juice"],"purpose":"Toppings (Don’t skip these!)"}]', '[{"description":"Heat oil in a pot over medium high heat. Add garlic and onion, cook until softened (3 min).","images":[],"step":1},{"description":"Add beef and turn up the heat to high. Cook, breaking it up as you go, until it all changes from pink to brown.","images":[],"step":2},{"description":"Add remaining Soup ingredients and Taco Seasoning. Bring to a simmer then turn heat down to medium.","images":[],"step":3},{"description":"Simmer for 10 minutes to bring the flavours together. Adjust thickness with water if desired.","duration":10,"images":[],"step":4},{"title":"This is how I like to serve it","description":"place a handful of corn chips in the bowl. Ladle in soup. Top with sour cream, cheese, coriander and a few crushed corn chips. For a healthier option, skip the corn chips in the bowl and/or serve more on the top / side of the soup.","images":[],"step":5}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Tex-Mex"],"categories":["beef-mince-recipes","beef-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","mexican-recipes","quick-and-easy","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1dd67641236b', 'en', 'US', 'Chilli Con Carne', 'Recipe video above. Everybody''s favourite Chili, nice and saucy! Made with a from-scratch Chili Powder rather than a store bought mix - it''s so much more reliable and you just need pantry staples. Don''t skip the beef bouillon cubes (stock cube) - it adds so much more flavour into the sauce than using just salt, or even liquid beef stock.Make a quick midweek version though when you''ve got the time, it''s well worth slow cooking. See notes for Serving and Topping options!', 'https://www.recipetineats.com/tachyon/2016/06/Chili-Con-Carne_8.jpg', 10, 30, 40, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_kidney_beans", "quantity": {"value": 0.992, "unit": "can of 400g"}}, {"id": "ing_beef", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 1.0, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.5, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.625, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_tortillas", "quantity": {"value": 1.0, "unit": "pack of 8"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}]', '[{"ingredients":["1 tbsp olive oil","3 garlic cloves (, minced)","1 onion (, diced (brown, white, yellow))","1 red capsicum ((bell pepper), diced)","1 lb / 500g beef mince / ground beef","3 tbsp tomato paste","800g / 28 oz can crushed tomato","14 oz / 420g can red kidney beans (, drained (or other beans))","2 beef bouillon cubes (stock cubes), crumbled (Note 1)","1 1/2 tsp sugar (any type)","1/2 - 1 1/2 cups water"]},{"ingredients":["1 - 2 tsp cayenne pepper (adjust to taste) (Note 2)","4 tsp paprika powder","5 tsp cumin powder","2 tsp garlic powder (or onion powder)","2 tsp onion powder","2 tsp oregano","1 1/2 tsp cooking salt / kosher salt"],"purpose":"Chili Spice Mix:"},{"ingredients":["Rice, corn chips, tortillas (Note 5 for more)","Sour cream, yoghurt, grated cheese, coriander./cilantro (Note 6 for more)"],"purpose":"To Serve"}]', '[{"description":"Heat oil in a large skillet over medium high heat. Add garlic and onion, cook for 1 minute, then add capsicum and cook for 2 minutes until onion is translucent.","duration":1,"images":[],"step":1},{"description":"Turn heat up to high and add beef. Cook, breaking it up as you go, until mostly browned.","images":[],"step":2},{"description":"Add Chili Spice Mix. Cook until beef is browned all over. (This step helps release extra flavour from the spices)","images":[],"step":3},{"description":"Add remaining ingredients, with 1/2 cup of water for Quick Cook or 1 1/2 cups for Slow Cook. Bring to simmer, then adjust heat per step below:","images":[],"step":4},{"title":"Quick Cook","description":"20 to 40 minutes, uncovered, on medium low heat so it''s bubbling gently; OR","images":[],"step":5},{"title":"Slow Cook","description":"1.5 hours to 2 hours, covered, on low heat so it''s bubbling very gently. (Note 3 Slow Cooker)","images":[],"step":6},{"description":"Adjust salt to taste just before serving.","images":[],"step":7},{"description":"Serve over rice, or ladle into bowls and serve with corn chips or warm tortillas on the side with Toppings of choice (Note 6). See Note 7 for more serving options. My usual: Either over rice or with corn chips, always with sour cream, cheese and coriander.","images":[],"step":8}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Tex-Mex"],"categories":["beef-mince-recipes","beef-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","quick-and-easy","slow-cooker-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f436429c6149', 'en', 'US', 'Beef and Rice with Veggies', 'Recipe video above. Ground beef cooked with seasoned rice and plenty of veggies - kind of like a pilaf or fried rice! This dish is not spicy - the cayenne pepper just adds a touch of warmth, not spiciness.', 'https://www.recipetineats.com/tachyon/2018/02/Beef-Rice_7.jpg', 5, 20, 25, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_white_rice", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 33.333, "unit": "carton of 12"}}, {"id": "ing_baby_spinach", "quantity": {"value": 3.0, "unit": "bag of 250g"}}]', '[{"ingredients":["2 tbsp olive oil","1 onion (, diced (any type))","1 red capsicum / bell pepper (, diced (large))","2 garlic cloves (, minced)","500g (1 lb) ground beef (mince) (, lean)","2 1/2 tbsp tomato paste","1 1/4 tsp salt","1/2 tsp EACH cumin, black pepper","1 tsp each onion powder, dried oregano (or other herb of choice)","1/4 tsp cayenne pepper (optional)","1 dried bay leaf","1 1/4 cups (225g) long grain white rice (, uncooked (Note 1))","2 cups (500 ml) beef broth (, low sodium)","2 cups (300g) diced frozen veggies (, I used corn, pea, carrot mix (Note 2))","3 big handfuls baby spinach (~ 90g/3 oz) (, or other leafy greens (Note 3))"]}]', '[{"description":"Heat oil in large pot over high heat. Add onion, capsicum and garlic. Cook for 1 minute.","duration":1,"images":[],"step":1},{"description":"Add beef, cook until brown, breaking it up as you go.","images":[],"step":2},{"description":"Add tomato paste, salt, pepper, onion powder, oregano, cumin and cayenne pepper. Cook for 1 minute.","duration":1,"images":[],"step":3},{"description":"Turn heat down to medium. Add rice and beef broth, mix well. Add frozen veggies and bay leaf, then stir.","images":[],"step":4},{"description":"Place lid on, lower heat to medium low so it''s simmering gently. Cook for 12 - 15 minutes (might even take longer) until all liquid is absorbed (tilt pot to check). The rice should be just cooked, but will be wet.","duration":13.5,"images":[],"step":5},{"description":"Remove from heat. Quickly toss spinach on top of the rice and put the lid back on. Leave to rest for 10 minutes.","duration":10,"images":[],"step":6},{"description":"Fluff rice and mix through wilted spinach with a fork. Adjust salt if desired. Serve!","images":[],"step":7}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef-mince-recipes","beef-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","one-pot-recipes","quick-and-easy","rice-recipes","rice-side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_40339b8e866e', 'en', 'US', 'Salisbury Steak with Mushroom Gravy', 'Recipe VIDEO above. Salisbury steak is a totally scrumptious way to transform the humble ground beef / mince into something amazing! The onion grating / soaking breadcrumbs will make your patties extra tasty and tender, and the Mushroom Gravy is made extra delicious by cooking the Salisbury Steaks IN the gravy.And next time - try Salisbury Steak Meatballs!', 'https://www.recipetineats.com/tachyon/2015/12/Salisbury-Steak-2.jpg', 15, 15, 30, 5, '[{"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_bread", "quantity": {"value": 0.094, "unit": "loaf"}}, {"id": "ing_beef", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_ketchup", "quantity": {"value": 0.06, "unit": "bottle of 500g"}}, {"id": "ing_beef", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 2.5, "unit": "bottle"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_mushroom", "quantity": {"value": 0.142, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1/2 onion (white, brown or yellow)","1/2 cup panko breadcrumbs (or 1/3 cup ordinary breadcrumbs)","1 lb/500g ground beef (mince)","1 garlic clove (, minced)","1 egg","2 tbsp ketchup","1 beef bouillon cube (, crumbled)","1/2 tsp Worcestershire sauce","3 tsp dijon mustard (OR 2 tsp dry mustard powder)"],"purpose":"Salisbury Steak"},{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","1/2 onion (, finely chopped)","5 oz/150g mushrooms (, sliced)","30g / 2 tbsp unsalted butter","3 tbsp flour (all purpose / plain)","2 cups beef broth / stock (, low sodium)","1/2 cup water","2 tsp dijon mustard","2 tsp Worcestershire sauce","Salt and pepper"],"purpose":"Gravy"}]', '[{"description":"Salisbury Steaks","images":[],"step":1},{"title":"Onion grating","description":"Place breadcrumbs in a bowl. Use a box grater and grate the onion over the breadcrumbs. Mix with fingers, leave to soak for a few minutes.","images":[],"step":2},{"title":"Mix","description":"Add remaining Salisbury Steak ingredients into the large bowl. Use your hands to mix until just combined. Mix well for a couple of minutes until the mixture becomes a bit \"pasty\" which will ensure your patties hold together well.","images":[],"step":3},{"title":"Form patties","description":"Divide into 5 and pat very firmly into oval patties around 3/4\" / 1 2/3 cm thick.","images":[],"step":4},{"description":"Cooking and Gravy","images":[],"step":5},{"title":"Brown patties","description":"Heat oil in a skillet over high heat. Add the steaks and cook the first side for 1 minute or until browned, then gently flip and brown the other side (they will still be raw inside). Remove onto plate.","duration":1,"images":[],"step":6},{"title":"Cook aromatics","description":"If skillet is looking dry, add a touch more oil. Add chopped onion and garlic and cook for 2 minute until onions are a bit translucent.","duration":2,"images":[],"step":7},{"title":"Cook mushrooms","description":"Add the mushrooms into the skillet and cook for 2 - 3 minutes until golden.","duration":2.5,"images":[],"step":8},{"title":"Make gravy roux","description":"Turn heat down to medium. Add butter. Once melted, add flour and cook for 30 seconds, stirring constantly.","duration":0.5,"images":[],"step":9},{"title":"Gravy","description":"Gradually add in beef broth, stirring as you go. Once mostly lump free, whisk in remaining Gravy ingredients.","images":[],"step":10},{"title":"Finish cooking steaks","description":"Add steaks along with the juices on the plate. Cook for 5 - 7 minutes, or until gravy is thickened, stirring occasionally around the steaks. If the gravy thickens too quickly, add more water.","duration":6,"images":[],"step":11},{"title":"Season gravy","description":"Remove steaks onto a plate. Taste gravy and adjust salt and pepper to taste.","images":[],"step":12},{"description":"Serve salisbury steaks topped with the mushroom gravy - over mashed potato is ideal! Sprinkle with a bit of parsley if desired.","images":[],"step":13}]', '["egg","gluten","milk","mustard"]', '["high_protein","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef-mince-recipes","beef-recipes","dinner-tonight","main-dishes","most-popular","mushroom-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c987af51504a', 'en', 'US', 'Cocktail Meatballs with Sweet & Sour Dipping Sauce', 'Terrific for gatherings because they reheat so well! These baked meatballs are extra juicy and tasty due to: a) using a combination of beef and pork; b) my little trick to soak the breadcrumbs in grated onion which is a technique I used in most of my meatballs, including the wildly popular Italian Meatballs and Swedish Meatballs (read the rave reviews!). The Sauce and Meatballs individually are lovely, but combined together they are sensational. Recipe VIDEO below.', 'https://www.recipetineats.com/tachyon/2017/11/Cocktail-Meatballs-7.jpg', 20, 25, 45, 25, '[{"id": "ing_bread", "quantity": {"value": 0.141, "unit": "loaf"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_pork_mince", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.037, "unit": "pack of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.065, "unit": "L"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.25, "unit": "bottle of 500ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.065, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_chives", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["3/4 cup panko breadcrumbs (Note 1)","½ onion","250 g / ½ lb beef mince (ground beef) (Note 2)","250 g / ½ lb pork mince (ground pork) (Note 2)","1 egg","1 garlic clove (, minced)","1½ tsp Worcestershire Sauce","3/4 tsp salt","½ tsp black pepper"],"purpose":"Meatballs:"},{"ingredients":["1 tbsp cornflour/ cornstarch","¼ cup / 65 ml water","½ cup / 125 ml apple cider vinegar","1/2 cup / 100g brown sugar (adjust to taste)","¼ cup / 65 ml tomato ketchup","1 tbsp soy sauce (Note 2)"],"purpose":"Sweet and Sour Sauce (makes ~ 1 cup):"},{"ingredients":["Finely chopped chives"],"purpose":"Garnish (optional):"}]', '[{"description":"Preheat oven to 220C / 430F (standard) or 200C / 390F (fan / convection).","images":[],"step":1},{"description":"Grate onion into a large bowl using a standard box grater. Add breadcrumbs and mix to coat. Leave to soak for a few minutes.","images":[],"step":2},{"description":"Add remaining Meatballs ingredients. Mix well with your hands until combined.","images":[],"step":3},{"description":"Measure out level tablespoons and dollop onto work surface. Roll into balls. (My way of rolling balls - fast!)","images":[],"step":4},{"description":"Place a rack on a baking tray (optional, Note 3). Spray rack generously with oil. Place balls on the rack.","images":[],"step":5},{"description":"Bake for 25 minutes or until browned. Remove tray from oven, immediately transfer meatballs in a large bowl (if you leave them, they stick).","duration":25,"images":[],"step":6},{"description":"Drizzle with enough sauce to coat the meatballs. Toss gently, then transfer to serving bowl / plate. Garnish with chives, if desired.","images":[],"step":7},{"description":"Serve meatballs with toothpicks and remaining Sauce for Dipping.","images":[],"step":8},{"description":"SWEET and SOUR SAUCE:","images":[],"step":9},{"description":"Combine ingredients in a small saucepan over medium heat. Whisk to combine.","images":[],"step":10},{"description":"Bring to simmer, stirring / whisking regularly, then simmer until it thickens to a syrup consistency – or thicker if you like. (about 3 minutes)","images":[],"step":11},{"description":"Pour meatballs in a bowl, pour a bit of sauce to coat. Serve with remaining sauce, garnished with chives.","images":[],"step":12}]', '["egg","gluten","soy"]', '[]', '{"mealType":["main_course"],"cuisine":[],"categories":["beef-mince-recipes","beef-recipes","dinner-tonight","finger-food","main-dishes","meatball-recipes","quick-and-easy","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5d01e8557124', 'en', 'US', 'Rissoles!', 'Recipe video above. Plump, extra juicy, extra tasty rissoles - an Aussie favourite! I usually make Beef Rissoles but these can be made with lamb, pork, chicken or turkey. Makes 10 - 12 rissoles. (PS For those who are unfamiliar with rissoles, they are basically squashed meatballs. A classic Aussie family favourite :) )', 'https://www.recipetineats.com/tachyon/2017/09/Beef-Rissoles-1_-2.jpg', 15, 15, 30, 4, '[{"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_bread", "quantity": {"value": 0.094, "unit": "loaf"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_zucchini", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_thyme", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1 small brown onion","1/2 cup panko breadcrumbs (or normal)","500 g / 1 lb beef mince (ground beef) (Note 1)","1 small zucchini","1 small carrot","1 egg","1 large garlic clove (, minced)","1/2 tsp dried thyme","1/2 tsp oregano (or sub with other favourite herbs)","1/2 tsp each salt and pepper","2 tsp Worcestershire Sauce"],"purpose":"Rissoles:"},{"ingredients":["1 - 2 tbsp oil"],"purpose":"Cooking:"},{"ingredients":["Tomato Ketchup!"],"purpose":"Serving:"}]', '[{"description":"Grate the onion into a large bowl using a box grater (see video). Add panko, mix briefly to coat in the onion juices.","images":[],"step":1},{"description":"Grate zucchini and carrot into the bowl. Add remaining Rissoles ingredients. Mix well. Scoop up about 1/4 cup of mixture, form a 1.7cm / 2/3\" thick pattie. Indent the middle slightly (Note 2, see photos in post). Repeat with remaining mixture - you should make 10 - 12.","images":[],"step":2},{"description":"Heat oil in a skillet over medium heat. Add half the patties and cook for 4 minutes or until dark golden. Press LIGHTLY with spatula, if you press hard, you''ll press the juices out!","duration":4,"images":[],"step":3},{"title":"Flip and cook the other side for 3","description":"4 minutes until golden.","duration":3.5,"images":[],"step":4},{"description":"Transfer to plate, repeat with remaining rissoles.","images":[],"step":5},{"description":"Serve with tomato ketchup!","images":[],"step":6}]', '["egg"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Australian","Western"],"categories":["beef-mince-recipes","beef-recipes","dinner-tonight","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a87cd55d2a4f', 'en', 'US', 'Lasagna', 'Recipe video above. One of my signature recipes! This is a lasagna made the traditional Italian way, with a slow cooked ragu and a béchamel sauce ("Besciamella"). No ricotta - that''s the American-Italian version. Though it requires patience to make, it is worth every minute. The ragu bolognese is melt-in-you-mouth tender and the sauce is rich and thick. Makes 8 giant or 10 normal servings. This lasagna has 4 layers of lasagna sheets with 3 layers of meat and cheese sauce, then finished with a cheese sauce topping. You could stretch it to 4 ragu layers. If making 5 layers, scale up the recipe by 25% (click on servings and slide) and use a very deep pan!', 'https://www.recipetineats.com/tachyon/2025/03/Lasagna_6-1.jpg', 20, 240, 260, 10, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_beef_mince", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.333, "unit": "bottle of 750ml"}}, {"id": "ing_beef", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_sugar", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_gruyere_cheese", "quantity": {"value": 2.0, "unit": "block of 200g"}}, {"id": "ing_pinch_nutmeg", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_sheets_lasagna", "quantity": {"value": 350.0, "unit": "pack"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.2, "unit": "pack of 125g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 tbsp olive oil","1 onion (, finely chopped (white, yellow or brown))","1 medium carrot (, peeled and very finely diced)","1 celery stick (, very finely diced)","2 garlic cloves (, minced)","1 kg / 2 lb beef mince (ground beef) (Note 1)","800g / 28 oz canned crushed tomato","1/4 cup tomato paste","1 cup pinot noir red wine (, or other dry red wine (Note 2))","3 beef bouillon cubes (, crumbled)","2 bay leaves (, dried or fresh)","1/2 tsp EACH dried thyme and oregano","2 tsp Worcestershire Sauce","1 - 2 tsp sugar (if needed - Note 3)","1/2 tsp salt and black pepper"],"purpose":"Ragu Bolognese:"},{"ingredients":["60g / 4 tbsp butter","1/2 cup flour","4 cups milk (, preferably full fat but low fat ok)","2 cups gruyere or Colby cheese (, shred yourself (or cheddar, Monterey Jack, OR 1 cup / 100g shredded parmesan) (Note 4))","Pinch of freshly ground nutmeg","Salt and pepper"],"purpose":"Cheese Sauce (Besciamella):"},{"ingredients":["350g/ 12 oz fresh lasagna sheets (or 250g/8oz dried) (Note 5)","1 1/2 cups (tightly packed) mozzarella cheese (, shred yourself (Note 4))","Finely chopped basil or parsley (, for garnish (optional))"],"purpose":"Lasagna:"}]', '[{"description":"Heat oil in a large heavy based pot over medium heat. Add garlic, onion, celery and carrots. Cook for 10 minutes until softened and sweet - they should not brown (if they do, turn heat down).","duration":10,"images":[],"step":1},{"description":"Add beef, turn heat up and cook the beef, breaking it up as you go.","images":[],"step":2},{"description":"Once the beef has all turned brown, add the remaining Ragu ingredients EXCEPT the sugar.","images":[],"step":3},{"description":"Stir then adjust the heat so it is bubbling very gently. Place the lid on and cook for 1.5 - 2 hours, stirring every now and then, then remove the lid and simmer for 30 minutes.","duration":30,"images":[],"step":4},{"description":"The ragu is ready when the meat is really tender and the sauce has thickened and is rich - see video for consistency (Note 6). Adjust salt and pepper to taste, and add sugar if required (Note 3)","images":[],"step":5},{"title":"Warm milk up in a saucepan (optional","description":"just makes sauce thicken faster).","images":[],"step":6},{"description":"In a large saucepan, melt butter over medium low heat. Add flour and mix constantly for 1 minute.","duration":1,"images":[],"step":7},{"description":"Pour about 1 cup of the milk in, mixing as you go to incorporate into the flour mixture. Once mostly lump free, add remaining milk. Use a whisk if needed to make it lump free.","images":[],"step":8},{"description":"Turn heat up to medium high. Stir occasionally at first then regularly after a few minutes until sauce thickens - about 5 - 8 minutes. It should coat the back of the wooden spoon.","images":[],"step":9},{"description":"Remove from heat, add cheese, nutmeg, salt and pepper. Mix until the cheese is melted. The Sauce should be thick but still easily pourable - the consistency of heavy cream (you need to be able to drizzle it over the Ragu when layering - see video). If it''s too thick, add a splash of water or milk.","images":[],"step":10},{"description":"Preheat oven to 180°C/350°F.","images":[],"step":11},{"description":"Use a 33 x 22 x 7 cm / 13 x 9 x 2.5\" baking dish.","images":[],"step":12},{"description":"Smear a bit of Ragu on the base, then cover with lasagna sheets. Tear sheets to fit.","images":[],"step":13},{"description":"Spread over 2 1/2 cups of Ragu (enough to cover sheets), then drizzle over 1 cup of Cheese Sauce.","images":[],"step":14},{"description":"Top with lasagna sheets (Note 7). Spread with another 2 1/2 cups of Ragu, then 1 cup of Cheese Sauce. Top with lasagna sheets then repeat 1 more time.","images":[],"step":15},{"description":"Top with a 4th layer of lasagna sheets, then pour over the remaining Cheese Sauce.","images":[],"step":16},{"description":"Sprinkle with Mozzarella, then bake for 25 minutes or until golden and bubbling.","duration":25,"images":[],"step":17},{"description":"Stand for 5 to 10 minutes before cutting and serving, garnished with basil or parsley if desired.","duration":7.5,"images":[],"step":18}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["beef-mince-recipes","beef-recipes","casseroles-and-cosy-bakes","iconic-dishes","italian-recipes","pasta-bakes","pasta-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_30bc0fb0f39f', 'en', 'US', 'Oven Baked Italian Meatballs', 'Soft, juicy, extra tasty Oven Baked Italian Meatballs AND tomato sauce, made entirely in the oven! By baking the meatballs on a rack placed on top of the baking dish with the sauce in it, the meatball juices drips into the sauce (extra flavour!), the underside of the meatballs are partially "steamed" which makes them juicier, they aren''t sitting in a pool of oil and the meatballs stay nice and round! See recipe notes for using the recipe SCALER (hover over servings). Recipe video below!', 'https://www.recipetineats.com/tachyon/2017/04/Baked-Italian-Meatballs-5.jpg', 20, 30, 50, 4, '[{"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.68, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_italian_herb_mix", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 1.25, "unit": "loaf"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_beef", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_parsley", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_parsley", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}]', '[{"ingredients":["1/2 onion, finely chopped","2 garlic cloves, minced","1 tbsp olive oil","24 oz / 800 g crushed tomato (2 x standard cans)","3/4 cup chicken broth","1 tsp red pepper (chili) flakes (optional)","2 tsp dried Italian herb mix (parsley, basil, thyme, oregano)","1 tsp salt + black pepper"],"purpose":"Sauce:"},{"ingredients":["1 lightly packed cup of sliced white sandwich bread, torn into small pieces, crusts removed (Note 1)","½ onion, grated - including juices (yellow, brown or white)","14 oz / 400 g ground beef (beef mince)","3 oz / 100g ground pork (mince) or substitute with ground beef (beef mince) (Note 2)","1 egg","¼ cup fresh parsley, finely chopped (Note 3)","2 garlic cloves, minced","¼ cup Parmigiano-Reggiano (or parmesan), freshly grated","¾ tsp salt","¼ tsp black pepper","Olive oil spray (or other oil spray)"],"purpose":"Meatballs:"},{"ingredients":["Fresh parsley, chopped","Parmigiano-Reggiano or parmesan, freshly grated"],"purpose":"Serving:"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Place onion, garlic and olive oil in a (approx) 30 x 25 cm / 12 x 10\" pan (Note 4). Mix, spread out, then bake for 8 minutes. (Start the meatballs)","duration":8,"images":[],"step":2},{"description":"Remove from oven, add remaining Sauce ingredients. Mix.","images":[],"step":3},{"description":"Place rack on top of pan.","images":[],"step":4},{"description":"Turn oven up to 200C/390F.","images":[],"step":5},{"description":"Place the bread and onion in a large bowl. Mix to combine so the onion juice soaks the bread, set aside for 3 minutes. Bread should disintegrate into mush - if not, add a splash of milk or water to help it along.","duration":3,"images":[],"step":6},{"description":"Add all the remaining Meatball ingredients except oil spray. Use you hands to mix well.","images":[],"step":7},{"description":"Measure out very generously heaped tablespoons and roll into firm balls. It should make around 20 - don''t make them too small, they will cook too quickly.","images":[],"step":8},{"description":"Place meatballs on the rack, ensuring they are positioned over the pan so the juices will drip into the Sauce.","images":[],"step":9},{"description":"Spray generously with oil.","images":[],"step":10},{"title":"Bake for 20 minutes. Optional","description":"flick to grill/broil on high for 2 minutes at the end, to get better browning.","duration":20,"images":[],"step":11},{"description":"Transfer meatballs from rack into the Sauce. Stir to coat meatballs in Sauce.","images":[],"step":12},{"description":"Serve with spaghetti or other pasta of choice, garnished with fresh parsley and parmesan.","images":[],"step":13}]', '["egg","gluten","milk"]', '[]', '{"mealType":["main_course"],"cuisine":[],"categories":["beef-mince-recipes","beef-recipes","dinner-tonight","italian-recipes","main-dishes","meatball-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_652e35409965', 'en', 'US', 'Greek Meatballs', 'Juicy Greek Meatballs (Keftedes), beautifully flavoured with red onion, parsley, a hint of mint and dried oregano with a slightly crispy surface. See recipe video below.', 'https://www.recipetineats.com/tachyon/2017/03/Greek-Meatballs-6-hero.jpg', 20, 12, 32, 5, '[{"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_pork_mince", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_bread", "quantity": {"value": 0.188, "unit": "loaf"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_mint", "quantity": {"value": 120.0, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}]', '[{"ingredients":["1 red onion, grated","500g / 1 lb beef mince (ground beef) (or lamb!)","200g / 6.5oz pork mince (ground pork), or more beef","2 garlic cloves, minced","1 cup / 60g panko breadcrumbs (or use normal)","1 egg","1/4 cup fresh parsley, finely chopped","6 large mint leaves, finely chopped (spearmint if you can, it''s authentic)","1/2 tsp dried oregano","1 tbsp extra virgin olive oil","3/4 tsp salt","Black pepper"],"purpose":"Meatballs:"},{"ingredients":["1/2 cup flour (any white)","3 tbsp olive oil","Finely chopped parsley (optional, for garnish)","Tzatziki (Note 5) or Greek yoghurt"],"purpose":"Cooking / Serving:"}]', '[{"description":"Grate the onion straight into a large bowl, then add remaining Meatball ingredients. Use your hands to mix well for a few minutes until the mixture is quite smooth and very well combined.","images":[],"step":1},{"title":"Optional: Refrigerate for 1 hour","description":"makes them easier to roll + retains round shape when cooking.","images":[],"step":2},{"description":"Measure out heaped tablespoons and dollop onto a work surface - should make around 32 - 35. Then roll into balls.","images":[],"step":3},{"description":"Heat most of the oil in a large skillet over medium high heat (medium if you have a strong gas stove). Use enough oil to cover the surface of the skillet.","images":[],"step":4},{"title":"Cook in 2 to 3 batches","description":"Dredge meatballs lightly in flour, shaking off excess, then place in the skillet. Roll them around and cook for 5 - 6 minutes, until nicely browned all over. Remove onto plate, cover to keep warm and repeat with remaining meatballs.","duration":5.5,"images":[],"step":5},{"title":"BAKING","description":"Alternatively, spray generously with oil (preferably olive oil) then bake at 180C/350F for 20 minutes or until browned. The pan frying method is the traditional way and the meatballs are slightly juicier.","duration":20,"images":[],"step":6},{"description":"Serve as a starter as part of a mezze platter with pita bread and tzatziki, or make dinner plates by adding a salad like a Greek Salad!","images":[],"step":7}]', '["egg","gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Greek"],"categories":["beef-mince-recipes","beef-recipes","finger-food","greek-recipes","meatball-recipes","mediterranean-recipes","quick-and-easy","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_68130eb882c4', 'en', 'US', 'Cheeseburger Party Meatballs', 'Cheeseburgers in bite size party food form! These are great for making ahead - assemble but don''t melt the cheese, then when ready to serve, microwave just to melt the cheese. You probably won''t have leftovers, but if you do, stuff them into rolls to make Cheeseburger Meatball subs!', 'https://www.recipetineats.com/tachyon/2016/11/Cheeseburger-Meatballs-1.jpg', 15, 15, 30, 25, '[{"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 7.5, "unit": "bottle"}}, {"id": "ing_bread", "quantity": {"value": 0.188, "unit": "loaf"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_cheese", "quantity": {"value": 6.0, "unit": "block of 250g"}}, {"id": "ing_baby_gherkins", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_ketchup", "quantity": {"value": 1.0, "unit": "bottle of 500g"}}]', '[{"ingredients":["500 g / 1 lb beef mince (ground beef)","1 tsp onion powder","1/2 tsp garlic powder","1/2 tsp salt","1/2 tsp black pepper","1 1/2 tsp Worcestershire Sauce","1 cup panko breadcrumbs (or 3/4 cup normal breadcrumbs)","1 egg"],"purpose":"Meatballs"},{"ingredients":["1 tbsp oil","6 - 8 processed cheese slices (Note 1)","Baby gherkins","Ketchup (, to serve)"],"purpose":"Assembling"}]', '[{"description":"Place Meatball ingredients in a bowl and use your hands to combine.","images":[],"step":1},{"description":"Refrigerate for 30 minutes (firms up, easier to handle). If in a rush, add more breadcrumbs until mixture is roll-able.","duration":30,"images":[],"step":2},{"description":"Scoop up heaped tablespoons and dollop onto work surface with the flick of the wrist. Repeat with remaining mixture. Then roll into balls.","images":[],"step":3},{"description":"Cut cheese into small squares to top each meatball.","images":[],"step":4},{"description":"Cut larger gherkins in half, lengthwise.","images":[],"step":5},{"description":"Heat oil in a skillet over medium high heat. Add meatballs in batches and cook, shaking the pan so they roll around, until browned all over and cooked through - 5 minutes. Between batches, drain excess oil (but keep some to cook next batch).","images":[],"step":6},{"description":"Place cooked meatballs on a large plate that fits in your microwave. Top with cheese and a gherkin and secure with a toothpick.","images":[],"step":7},{"title":"Microwave for 60","description":"90 seconds or until cheese melts. Serve warm with ketchup!","duration":1.25,"images":[],"step":8}]', '["egg","milk"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["snack"],"cuisine":[],"categories":["beef-mince-recipes","beef-recipes","finger-food","meatball-recipes","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1e11cde4fa1a', 'en', 'US', 'Italian Meatball Soup', 'My Classic Italian Meatballs are one of the most popular recipes on my site. They''re extra soft and juicy, and extra tasty thanks to just a couple of little but key extra steps - using bread soaked in grated onion, and using a mix of ground beef and pork (mince). And now by popular demand, here is my Meatball Soup made using my Classic Italian Meatballs! This soup is really thick and hearty, and the tomato broth is extra tasty thanks to the meatballs!', 'https://www.recipetineats.com/tachyon/2016/04/Meatball-Soup_4.jpg', 25, 30, 55, 5, '[{"id": "ing_bread", "quantity": {"value": 1.25, "unit": "loaf"}}, {"id": "ing_onion", "quantity": {"value": 75.0, "unit": "pack of 1kg"}}, {"id": "ing_beef", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 75.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.68, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.68, "unit": "kg"}}, {"id": "ing_italian_mixed_herbs", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.454, "unit": "pack of 500g"}}, {"id": "ing_basil", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.5, "unit": "pack of 125g"}}]', '[{"ingredients":["1 lightly packed cup of sliced white sandwich bread (, torn into small pieces, crusts removed (Note 1))","1/2 cup grated onion (brown, white or yellow)","14 oz / 400 g ground beef (beef mince)","3 oz / 100g ground pork (mince) or more ground beef (Note 2)","1 egg","1/4 cup fresh parsley (, finely chopped (Note 3))","2 garlic cloves (, minced)","1/4 cup Parmigiano-Reggiano ((or parmesan), freshly grated)","3/4 tsp salt","1/4 tsp black pepper"],"purpose":"Meatballs"},{"ingredients":["1 1/2 tbsp olive oil","1 cup onion (, finely chopped (white, brown or yellow))","2 garlic cloves (, minced)","2 cups chicken broth / stock (or water)","1 cup water","24 oz / 700g passata (pureed tomato) (Note 4)","28 oz / 800g canned tomato","1 tbsp Italian mixed herbs (Note 5)","2 tsp garlic powder (or onion powder)","1 - 2 tsp red pepper / chilli flakes (optional)","8 oz / 250g spaghetti (dried, not fresh or cooked)"],"purpose":"Soup"},{"ingredients":["1/4 cup fresh basil leaves (, torn)","1/2 - 3/4 cup shredded mozzarella cheese","Parmigiano-Reggiano ((or parmesan), freshly grated)"],"purpose":"Garnish (optional)"}]', '[{"description":"Place the bread and onion in a large bowl. Mix to combine so the onion juice soaks the bread.","images":[],"step":1},{"description":"Add all the remaining Meatball ingredients. Use you hands to mix well.","images":[],"step":2},{"description":"Roll a slightly heaped tablespoon of mixture into a ball. Repeat with remaining mixture. Should make around 24. (Note 6) Refrigerate meatballs for 30 minutes (Note 7)","duration":30,"images":[],"step":3},{"description":"Heat 1 1/2 tbsp olive oil in a large pot over medium high heat. Add the meatballs in a single layer and brown all over (still raw inside) - I do this in 2 batches. Remove meatballs onto a plate and set aside.","images":[],"step":4},{"description":"If the pot is looking dry, add a touch more olive oil. Add onion and garlic and cook for 2 minutes.","duration":2,"images":[],"step":5},{"description":"Add chicken broth, bring to simmer and scrape the bottom of the pot to mix the brown bits into the liquid.","images":[],"step":6},{"description":"Add remaining Soup ingredients except spaghetti. Bring to simmer, turn heat down to medium and cook for 5 minutes, stirring occasionally, scraping the bottom of the pot.","duration":5,"images":[],"step":7},{"description":"Take the lid off and add spaghetti. Use tongs to push it all under the liquid as it starts to soften. Once the spaghetti is submerged, add the meatballs. Cook for around 12 minutes, or until spaghetti is just cooked but still firm (al dente). Remove from stove.","images":[],"step":8},{"description":"If using cheese, sprinkle on the surface of the soup after you take it off the stove, put the lid back on and let the heat melt the cheese (~2 minutes).","images":[],"step":9},{"description":"Ladle soup, spaghetti and meatballs into bowls. Garnish with basil leaves and serve with Parmigiano-Reggiano, if using.","images":[],"step":10}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["beef-mince-recipes","beef-recipes","italian-recipes","main-dishes","meatball-recipes","most-popular","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e3d8e83202bc', 'en', 'US', 'Italian Meatloaf with Marinara Sauce', 'My Italian meatloaf is made extra juicy by soaking bread in grated onion instead of using breadcrumbs. The seasonings for the meatloaf are the same as what is used for homemade Italian sausages, so this really tastes like an Italian meatloaf! And the sauce is made extra tasty by adding the loaf pan juices and cooking the meatloaf IN the sauce for part of the time.', 'https://www.recipetineats.com/tachyon/2015/12/Italian-Meatloaf_4.jpg', 15, 60, 75, 6, '[{"id": "ing_capsicum", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_bread", "quantity": {"value": 0.375, "unit": "loaf"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_cream", "quantity": {"value": 0.12, "unit": "carton of 250ml"}}, {"id": "ing_pork", "quantity": {"value": 0.369, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.726, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_fennel_seeds", "quantity": {"value": 12.5, "unit": "jar"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.009, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 4.5, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_canned_tomatoes", "quantity": {"value": 1.588, "unit": "can of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_mixed_italian_herbs", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 4.5, "unit": "jar of 50g"}}, {"id": "ing_black_pepper", "quantity": {"value": 4.5, "unit": "jar of 50g"}}]', '[{"ingredients":["1 1/2 cups diced red bell pepper / capsicum (1 large)","1 tbsp olive oil","2 cups stale white bread (, crusts removed, roughly diced (about 3 slices))","1 small onion","2 tbsp cream (or milk)","13 oz / 400 g ground pork (mince)","1.6lb / 800 g ground beef (mince)","2 eggs","2 1/2 tsp fennel seeds","3 tsp paprika (sweet or smoked)","1 3/4 tsp salt","Pepper"]},{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","1/2 onion (, finely chopped (brown, white, yellow))","1.4 lb / 700 g tomato passata or crushed tinned tomatoes (Note 1)","3/4 cup water","2 tsp dried Mixed Italian Herbs","1 - 3 tsp red pepper flakes (optional)","Salt and pepper"],"purpose":"Sauce"}]', '[{"description":"Preheat oven to 180C/350F. Spray a 28cm/11\" loaf pan, then line with parchment / baking paper, leaving overhang (Note 2).","images":[],"step":1},{"description":"Heat oil over high heat. Add capsicum, leave for 1 minute without stirring so it starts to char (burn) then stir and continue cooking to char it more (about 2 minutes in total). Remove and set aside.","duration":1,"images":[],"step":2},{"description":"Place bread in a large bowl. Grate onion into the bowl, using a normal box cutter (Note 3). Add cream, then use your hands to squidge the mixture together so the bread is completely soaked and starts to disintegrate.","images":[],"step":3},{"description":"Add remaining meatloaf ingredients, including capsicum. Use your hands to mix it together until JUST combined. Do not over mix otherwise it will become dense.","images":[],"step":4},{"description":"Press into the loaf pan (Note 4). Drizzle with olive oil then bake for 30 minutes. Meanwhile, make the Sauce.","duration":30,"images":[],"step":5},{"description":"Take the meatloaf out of the oven. Carefully lift the meatloaf out of the loaf pan (using the paper overhang) onto a work surface. Then transfer the meatloaf into the skillet with the Sauce.","images":[],"step":6},{"description":"Pour juices in the loaf pan into the skillet. Return to the oven for a further 30 to 40 minutes, or until cooked to your liking.","images":[],"step":7},{"description":"Take it out of the oven and let it rest for 5 minutes before slicing. Serve the meatloaf with the Sauce, garnished with parmesan if desired.","duration":5,"images":[],"step":8},{"description":"I like to serve this with mashed potatoes but it is also lovely with pasta.","images":[],"step":9},{"description":"Heat oil in a ovenproof skillet over medium heat. Add onion and garlic and cook for 3 minutes until translucent.","duration":3,"images":[],"step":10},{"description":"Add remaining ingredients. Bring to a simmer and cook for 5 minutes on the stove, adjusting salt and pepper to taste.","duration":5,"images":[],"step":11},{"description":"Take it off the stove. Follow the steps above to place the meatloaf in and bake it.","images":[],"step":12}]', '["egg","gluten","milk"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["beef-mince-recipes","beef-recipes","dinner-tonight","italian-recipes","main-dishes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_211a911cd221', 'en', 'US', 'Nachos Pie', 'Nachos - in lasagne form! This is how to get your midweek Nachos fix with far less guilt! You can substitute the spices for a packet Nachos mix if you prefer. The Pico De Gallo adds freshness but is not essential! It is still scrumptious without it. You could make this even healthier by reducing the beef in this and adding more vegetables, like corn, diced zucchini and bell peppers (capsicum).', 'https://www.recipetineats.com/tachyon/2015/07/Nacos-Pie_600px_2a_Featured.jpg', 10, 40, 50, 6, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_beef", "quantity": {"value": 0.369, "unit": "kg"}}, {"id": "ing_packet_taco_seasoning_or_make_your_own_see_note_1", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_kidney_beans", "quantity": {"value": 0.992, "unit": "can of 400g"}}, {"id": "ing_tortillas", "quantity": {"value": 3.0, "unit": "pack of 8"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_corn", "quantity": {"value": 3.0, "unit": "can of 400g"}}, {"id": "ing_avocado", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.9, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}]', '[{"ingredients":["1 tbsp olive oil","1 onion (, diced (brown, yellow, white))","2 garlic cloves","13 oz / 400 g ground/mince beef (use lean!)","1 oz / 28 g packet Taco Seasoning OR make your own - see Note 1","1/2 tsp black pepper","700 g / 24oz tomato passata or pureed canned tomatoes (Note 2)","1/2 cup water","14 oz / 400 g canned red kidney beans ((or any other beans), drained)","3 - 4 soft tortillas ((flour or corn) - for layering)","1 cup grated cheese (I used mozzarella, but any melting cheese is fine)","2 oz / 70 g corn chips"]},{"ingredients":["1/2 avocado (, diced)","1 large tomato (, deseeded and diced (Note 3))","1/4 spanish ((red) onion, diced)","2 tbsp lime juice (fresh or bottled)","3 tbsp fresh coriander leaves","1/2 tbsp olive oil","Salt and pepper"],"purpose":"Pico de Gallo (optional)"},{"ingredients":["Sour cream"],"purpose":"To serve"}]', '[{"description":"Preheat the over to 350F/180C.","images":[],"step":1},{"description":"Heat the oil in a large skillet over high heat.","images":[],"step":2},{"description":"Add the garlic and onion, and cook until translucent.","images":[],"step":3},{"description":"Add the beef and cook, breaking up into pieces, until browned. Add the Taco Seasoning and pepper about halfway through browning the beef.","images":[],"step":4},{"description":"Add the tomato passata, water and beans. Cook for 5 minutes, stirring occasionally until thickened but still very saucy. Remove from heat.","duration":5,"images":[],"step":5},{"description":"Assemble & Bake","images":[],"step":6},{"description":"Lay a tortilla in a pie dish (24 cm / 9 inch diameter). Use a slotted spoon to top with just under 1/2 the meat. Try to avoid using too much sauce so sort of \"shake\" each spoonful to drain out sauce.","images":[],"step":7},{"description":"Top with another tortilla + torn/cut pieces of another tortilla to cover completely.","images":[],"step":8},{"description":"Top with the remaining meat, again avoiding the sauce.","images":[],"step":9},{"description":"Top with remaining tortillas, then pour over all the sauce (and any residual meat).","images":[],"step":10},{"description":"Place in the oven and bake for 20 minutes. If you''re worried about overspill, place it on a baking tray.","duration":20,"images":[],"step":11},{"description":"Remove from the oven, cover with corn chips then scatter with cheese. Bake until the chips are a bit golden and the cheese is melted - 10 to 15 minutes.","images":[],"step":12},{"description":"Serve, topped with Pico De Gallo and Sour Cream on the side, if using.","images":[],"step":13},{"description":"Combine ingredients in a bowl. Toss and adjust salt/pepper to taste.","images":[],"step":14}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican-esque"],"categories":["beef-mince-recipes","beef-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","mexican-recipes","nachos-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_94aae0a6fbf0', 'en', 'US', 'One Pot Orzo / Risoni Bolognaise', 'Dinner all made in one pot in just 20 minutes! A yummy bolognaise sauce made with orzo/risoni instead of spaghetti. Great couch food - and for kids too, less mess!', 'https://www.recipetineats.com/tachyon/2015/06/One-Pot-Bolognaise-Orzo-Risoni_680px_1.jpg', 3, 18, 21, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_beef", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.68, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_italian_herbs", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_beef", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.45, "unit": "pack of 500g"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["1 tbsp olive oil","2 cloves of garlic (, minced)","1 small onion (, peeled and diced (brown, white or yellow))","1 lb / 500g ground beef (mince)","24 oz / 700g tomato passata (Note 3)","2 tsp Worcestershire sauce","2 tsp dried Italian Herbs (, or any combination of dried parsley, oregano, basil)","2 beef bouillon cubes (Note 1)","1/2 to 1 tsp salt (to taste)","Black pepper","3 cups water","1 1/2 cups dried orzo / risoni"]},{"ingredients":["Freshly grated parmesan cheese","Finely chopped parsley"],"purpose":"To serve (optional)"}]', '[{"description":"Heat the oil in a large skillet/fry pan (or pot) over medium high heat. Add the onion and garlic and cook for 3 minutes or until translucent.","duration":3,"images":[],"step":1},{"description":"Add the mince and turn the heat up to high. Cook the mince, breaking it up as you go.","images":[],"step":2},{"description":"When the mince is browned, add the remaining ingredients except the orzo. When the liquid comes to a simmer (it might bubble and spit slightly) add the orzo/risoni.","images":[],"step":3},{"description":"Give it a quick stir then turn the heat down to medium low.","images":[],"step":4},{"description":"Cook for 10 minutes, stirring frequently towards the end to ensure the orzo/risoni doesn''t stick to the bottom of the pan. If your liquid is evaporating too quickly, just add a slosh of hot water (tap or boiling).","duration":10,"images":[],"step":5},{"description":"Remove the risoni from the heat. The risoni should be a teeny bit hard still and it should be very saucy when you take it off the stove. (Note 2)","images":[],"step":6},{"description":"Check for seasoning (salt), then give it a good stir.","images":[],"step":7},{"description":"Serve immediately, while it''s piping hot and nice and saucy, garnished with freshly grated parmesan and parsley, if desired.","images":[],"step":8}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Italian-esque"],"categories":["beef-mince-recipes","beef-recipes","dinner-tonight","italian-recipes","main-dishes","most-popular","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_03d122dd09fd', 'en', 'US', 'Leftover Pasta Fritters', 'A sensational way to turn dull, dried up leftover pasta into something ridiculously delicious. You can use any type of pasta to make these. This is a sensational fast meal - it will take you 15 minutes to make 12 of them if you use a large fry pan so you can cook them in 2 batches. Inspired by Hapa Nom Nom''s Spaghetti Pizza.', 'https://www.recipetineats.com/tachyon/2015/03/Leftover-Pasta-Spaghetti-Fritters-11.jpg', 5, 10, 15, 12, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.9, "unit": "pack of 500g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_bread", "quantity": {"value": 0.75, "unit": "loaf"}}, {"id": "ing_cheese", "quantity": {"value": 0.5, "unit": "block of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}]', '[{"ingredients":["3 cups (packed) cold leftover pasta (sauce and pasta mixed together), packed (Note 1)","2 eggs","3/4 to 1 1/4 cups breadcrumbs (I used panko breadcrumbs)","1/2 cup grated cheese (optional) (Note 2)","Salt and pepper (, to taste)","2 tbsp olive oil"]}]', '[{"description":"Roughy chop the pasta (I placed the pasta in a bowl and cut it with scissors).","images":[],"step":1},{"description":"Add the eggs, breadcrumbs (start with 3/4 cup) and cheese. Mix and add salt and pepper to taste.","images":[],"step":2},{"description":"Scoop up a ball and flatten it slightly to test if it holds together ok. If required, add more panko. (Note 3)","images":[],"step":3},{"description":"Heat olive oil in a fry pan over medium high heat.","images":[],"step":4},{"description":"Scoop up a level 1/3 cup of the mixture (packed well) and place in the fry pan (tap the bottom of the cup to get the mixture to drop out into the pan). Use the bottom of the cup measure to pat the mixture into 1 cm / 2/5\" thickness. Repeat to make however many fritters you can fit in the pan.","images":[],"step":5},{"description":"Cook the first side for around 2 minutes or until it turns a dark brown and crispy. Turn, then cook the other side until crispy (around 1 to 1 1/2 minutes).","images":[],"step":6},{"description":"Remove from the pan onto a paper towel to drain. Repeat with remaining batter.","images":[],"step":7},{"description":"Serve immediately. Garnish with finely chopped parsley leaves and freshly grated Parmesan, if desired.","images":[],"step":8}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dinner","snack"],"cuisine":[],"categories":["beef-mince-recipes","beef-recipes","fritters-tots-and-similar","italian-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_98fb4edc94a6', 'en', 'US', 'Meatloaf Cupcakes With Mashed Potato', 'Everything tastes better in miniature form! These Meatloaf Cupcakes are made extra irresistible by piling on mashed potato. These freeze very well. They are also great for hiding vegetables. I only added grated carrot, but you can mix in whatever vegetables you want. Finely chopped spinach or cabbage would blend in well, as would grated zucchini.', 'https://www.recipetineats.com/tachyon/2014/10/Meatloaf-Cupcakes-2.jpg', 15, 25, 40, 8, '[{"id": "ing_beef_mince", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_panko", "quantity": {"value": 150.0, "unit": "jar"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_potato", "quantity": {"value": 2.0, "unit": "bag of 2kg"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 lb / 500g beef mince (ground beef)","1 onion (, grated (brown, white or yellow))","2 small carrots (, grated)","2 eggs","1/4 cup grated parmesan cheese","1/4 cup tomato ketchup (or tomato sauce)","1 cup panko (or breadcrumbs)","1 tsp garlic powder","1 tsp dried oregano","1 tsp dried thyme","1 tsp salt","Pepper"],"purpose":"Meatloaf Cupcakes"},{"ingredients":["2 large or 3 medium potatoes","1 tbsp butter (optional)","1/2 - 1 cup milk"],"purpose":"Mashed Potato"},{"ingredients":["Tomato ketchup or sauce","Parsley (, finely chopped (optional))"],"purpose":"Garnish"}]', '[{"description":"Meatloaf Cupcakes","images":[],"step":1},{"description":"Preheat oven to 180C/350F.","images":[],"step":2},{"description":"Spray 8 holes of a muffin tin.","images":[],"step":3},{"description":"Grate the onion and carrot straight into a large bowl.","images":[],"step":4},{"description":"Add remaining meatloaf ingredients and use your hands to mix and combine well.","images":[],"step":5},{"description":"Scoop up 1/2 cup of mince and use your hands to form a rough ball shape. Press into the muffin tin. The surface should be a slight dome shape.","images":[],"step":6},{"description":"Repeat with remaining mince. It should make about 8.","images":[],"step":7},{"title":"Bake for 20","description":"25 minutes until browned on top. Remove from oven.","duration":22.5,"images":[],"step":8},{"description":"Peel and dice the potato. Steam or boil until soft but not waterlogged.","images":[],"step":9},{"description":"Drain, then add butter and 1/2 cup of milk. Mash using a potato masher until smooth or to your liking. Add extra milk if you need it. The mash needs to be creamy but stiff enough to hold its shape when piped or piled onto the Meatloaf Cupcakes.","images":[],"step":10},{"description":"Smear a dollop of tomato ketchup on the Meatloaf Cupcakes.","images":[],"step":11},{"description":"Top with mashed potato, either by piping it or just dolloping it on with a spoon.","images":[],"step":12},{"description":"Serve with a sprinkle of parsley, if using.","images":[],"step":13}]', '["egg","milk"]', '["gluten_free","high_protein","low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["beef-mince-recipes","beef-recipes","dietary","gluten-free-recipes","most-popular","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d37889fcde81', 'en', 'US', 'Shepherd''s Pie Potato Skins', 'Don''t save the potato you scoop out for another dish - mash it and pile it on top to make these irresistible Shepherd''s Pie Potato Skins!', 'https://www.recipetineats.com/tachyon/2014/09/Shepherds-Pie-Potato-Skins-1.jpg', 5, 10, 15, 4, '[{"id": "ing_beef_mince", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_frozen_mixed_vegetables", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_potato", "quantity": {"value": 4.0, "unit": "bag of 2kg"}}, {"id": "ing_milk", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["250 g / 8 oz lamb or beef mince (ground meat)","1 tbsp olive oil","½ onion ((brown, white or yellow), diced)","1 clove garlic (, minced)","1 1/2 cups frozen mixed vegetables (pea, corn, carrots) (or fresh)","2 tbsp flour","1 cup beef stock/broth (or 1 stock / bouillon cube dissolved in hot water)","½ cup water","½ tsp salt","½ tsp dried thyme","½ tsp dried oregano","Black pepper"]},{"ingredients":["4 large potatoes (, scrubbed clean (about 400g/13oz each))","½ to 1 cup milk (full or low fat)","2 tbsp butter (optional – but highly recommended)","Salt to taste"],"purpose":"Potatoes and Mash"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Prepare the Potatoes and Mash","images":[],"step":2},{"description":"Prick the potatoes with a fork (about 6 times on each potato) and microwave on high for 5 minutes. Then turn and microwave for a further 5 minutes. Pierce with a knife to check if they are cooked.","duration":5,"images":[],"step":3},{"description":"Remove from microwave (use a dish cloth). Cut off the tops and scoop out the center using a spoon, leaving a fairly thin skin (about 0.5 cm / 0.2”).","images":[],"step":4},{"description":"Place the potato scooped out in a bowl. Add milk, butter and salt and mash with a potato masher until smooth, or to your liking.","images":[],"step":5},{"description":"If you want to pipe the filling, place the mashed potato into a piping back with a large star tip nozzle.","images":[],"step":6},{"description":"Meanwhile, make the filling. Heat the olive oil in a large fry pan over medium high heat.","images":[],"step":7},{"description":"Add onion and garlic, sauté for 2 minutes until softened.","duration":2,"images":[],"step":8},{"description":"Turn up heat to high. Add mince beef (ground beef) and cook, breaking up the mince as you go, until nicely browned and cooked – about 3 minutes.","images":[],"step":9},{"description":"Sprinkle over flour and stir to combine.","images":[],"step":10},{"description":"Add remaining ingredients and stir to combine. Bring to simmer and continue to stir until the sauce is thick and glossy – around 2 minutes.","images":[],"step":11},{"description":"Remove from heat.","images":[],"step":12},{"description":"Assemble Potatoes","images":[],"step":13},{"description":"Fill each potato with the Filling so it is slightly heaped. Push down lightly to pack the filling in well.","images":[],"step":14},{"description":"Pipe over the mashed potato, or scoop it on with a spoon then fluff it up with a fork. You probably won’t use all of it – save the remainder or serve it on the side.","images":[],"step":15},{"description":"Place in the oven and bake for 15 to 20 minutes until the mashed potato is starting to brown on the ridges.","duration":17.5,"images":[],"step":16},{"description":"Serve immediately!","images":[],"step":17}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["beef-mince-recipes","beef-recipes","dietary","gluten-free-recipes","most-popular","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7bc9976f3f6e', 'en', 'US', 'B85 Beef Sausage Rolls - with jalapeño and cheese', 'Recipe video above. Copycat of the legendary beef sausage rolls at B85 Artisan Bakery in the quaint Sydney suburb of Camden, these are next-level good! These are big, bold, juicy, cheesy, and loaded flavour, and I especially love how the tangy pickled jalapeño cut through the richness. These are JUMBO, like the B85 ones. See Note 6 for party sausage rolls.', 'https://www.recipetineats.com/tachyon/2025/05/B85-Beef-sausage-rolls-recipe_4.jpg', 20, 50, 70, 4, '[{"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_bread", "quantity": {"value": 0.094, "unit": "loaf"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_beef_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_pickled_jalapeno", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_sheet_frozen_puff_pastry", "quantity": {"value": 2.0, "unit": "pack"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1 small onion (, peeled, whole)","1/2 cup panko breadcrumbs (Note 1)","500g/1 lb beef mince ((ground beef), fattier the better)","1 egg","2 garlic cloves (, minced with garlic press or finely grated)","1 beef stock cube (, crumbled (OXO is my favourite) or 1/2 tsp cooking salt / kosher salt)","1/2 tsp cooking salt / kosher salt (halve for table salt, +25% for flakes)","1/4 tsp black pepper","1/3 cup pickled jalapeno (, roughly chopped (~3mm) (Note 2))","1 1/2 cups (150g) cheddar (, shredded, or other cheese of choice (Note 3), pre-shredded ok)","1/2 cup (50g) parmesan (, shredded using box grater (pre-shredded ok))","2 sheets frozen puff pastry (, butter is better (24cm / 9.5\" squares) (Note 4))","1 egg (, separated)"]},{"ingredients":["1 tsp white sesame seeds","1/2 tsp black sesame seeds (or more white)"],"purpose":"Sprinkling:"},{"ingredients":["Aussie tomato sauce or ketchup"],"purpose":"Serving:"}]', '[{"description":"Abbreviated recipe:","images":[],"step":1},{"description":"Toss grated onion and panko, then mix everything else except cheeses. Then mix in cheese. Divide in 2, wrap in pastry, seal with egg white. 3 slits, brush with yolk, sprinkle with sesame. 35 minutes at 200°C/425°F (180C fan) then 15 minutes on a rack.","images":[],"step":2},{"description":"Preheat oven 200°C/425°F (180C fan-forced).","images":[],"step":3},{"title":"Onion soak","description":"Grate the onion in a bowl using a box grater, reserving all the onion juices. Add panko breadcrumbs and toss to wet.","images":[],"step":4},{"title":"Everything else but cheese","description":"Then add beef, egg, garlic, stock cube, salt, pepper and jalapeño. Mix well with hands to combine.","images":[],"step":5},{"title":"\"Crumble\" in cheese","description":"Add cheeses, then use fingers to firstly “crumble” the cheese through the beef before mixing well with hands (this method prevents cheese from clumping together).","images":[],"step":6},{"title":"Roll","description":"Barely thaw puff pastry (stiffer = easier to handle). Divide meat into 2 equal logs. Roll up in the puff pastry, then overlap the base with double layer, sealing with egg white. Finish with the seam side down and trim off surplus puff pastry (about 2 cm/0.8\").","images":[],"step":7},{"title":"Finish sausage rolls","description":"Cut each log in half. Cut 3 diagonal slashes on the top of each sausage roll. Brush with egg yolk, sprinkle with sesame seeds.","images":[],"step":8},{"title":"Bake","description":"Place the sausage rolls on a paper lined tray. Bake for 35 minutes, then transfer onto rack (to elevate out of fat, Note 5). Bake a further 15 minutes until pastry is deep golden and underside is crispy.","duration":35,"images":[],"step":9},{"description":"Cool on rack 5 minutes before attacking! Serve with Aussie tomato sauce or ketchup.","images":[],"step":10}]', '["egg","milk","sesame"]', '["gluten_free","high_protein"]', '{"mealType":["snack"],"cuisine":["Australian"],"categories":["beef-recipes","iconic-dishes","snacks"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0b052606b4c6', 'en', 'US', 'Goulash (Hungarian beef stew)', 'Recipe video above. The national dish of Hungary! Boldly flavoured with stacks of paprika, lots of onion, garlic and capsicum/bell peppers, with fall apart hunks of beef. It''s sort of a stew, sort of a soup. The broth is not supposed to be as thick as typical stews. It''s naturally thickened slightly using fresh tomatoes that break down into the sauce.Serve like soup in bowls with bread for dunking. (Try cheese bread. Obsessed!).', 'https://www.recipetineats.com/tachyon/2023/06/Hungarian-Goulash-_7.jpg', 15, 140, 155, 5, '[{"id": "ing_beef", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.009, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.938, "unit": "jar of 40g"}}, {"id": "ing_caraway_seeds", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_beef_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_potato", "quantity": {"value": 2.0, "unit": "bag of 2kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["1 kg/2 lb beef chuck (, cut in 3.5cm / 1.5\" cubes (Note 1))","1 3/4 tsp cooking salt / kosher salt","1 tsp black pepper","1 tbsp extra virgin olive oil","2 tbsp/ 30g unsalted butter","2 brown onions (, cut into 1cm / 1/2\" squares)","5 garlic cloves (, finely minced)","2 capsicum/bell peppers ((1 red + 1 yellow), cut into 2 cm / 0.8\" squares)","2 tomatoes (, cut into 8 wedges then in half)","1/4 cup Hungarian-style paprika (sub ordinary paprika, Note 2)","1 tsp caraway seeds (, optional (Note 3))","1 bay leaf","1 litre / 4 cups beef stock/broth (, low-sodium)","2 carrots (, peeled, cut in quarters lengthwise then into 1cm / 0.4\" pieces)","2 potatoes (, cut into 1.2cm / 1/2\" cubes)","1 tbsp finely chopped parsley (, optional garnish)"]}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan), though you can use your slow cooker or stove instead (oven easiest! Note 4).","images":[],"step":1},{"title":"Season beef","description":"Toss the beef with half the salt and pepper.","images":[],"step":2},{"title":"Cook onion","description":"Heat the oil and melt the butter in a large oven-proof dutch oven over high heat. Cook onion for 6 minutes until the edges are light golden.","duration":6,"images":[],"step":3},{"title":"Cook beef","description":"Add the beef and stir until the outside changes from red to brown, about 2 minutes. It won''t go golden brown, it''s not supposed to.","images":[],"step":4},{"title":"Add vegetables","description":"Add garlic, capsicum and tomato. Stir for 3 minutes - the tomato will mostly breakdown.","duration":3,"images":[],"step":5},{"description":"Add paprika, caraway and bay leaf. Stir for 30 seconds.","duration":0.5,"images":[],"step":6},{"title":"Slow cook","description":"Add beef stock, stir, bring to simmer. Cover with a lid and transfer to the oven for 1 1/2 hours.","images":[],"step":7},{"title":"Add potato","description":"The beef should be pretty tender but not quite \"fall-apart\". Stir in carrot and potatoes. Return to oven, covered, for another 30 minutes. Beef should now be \"fall-apart\" - if not, return to the oven for 10 minutes at a time.","duration":10,"images":[],"step":8},{"title":"Serve","description":"Ladle goulash into bowls and sprinkle with parsley. Eat as is, with optional bread for dunking! (Pictured with cheese bread)","images":[],"step":9}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["European","Hungarian"],"categories":["beef-recipes","slow-cooked-fall-apart","soup-recipes","stews","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_46a7ff96a1d0', 'en', 'US', 'Beef Standing Rib Roast (Prime Rib)', 'Recipe video above. The juiciest, tastiest, BEST roast beef in the world is Prime Rib!! Also known as Standing Rib Roast, this is slathered in a herb and garlic butter, then roasted to juicy perfection. By using a lower but not super low oven temperature, we can be assured of a beautiful even cook throughout the whole roast, yet still have it on the table in a couple of hours. Bonus: lower temp = more forgiving! Meat thermometer is a MUST!', 'https://www.recipetineats.com/tachyon/2018/11/Standing-Rib-Roast_Prime-Rib_0.jpg', 10, 120, 130, 6, '[{"id": "ing_standing_rib_roast_prime_rib", "quantity": {"value": 2.5, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_rosemary", "quantity": {"value": 0.12, "unit": "bunch"}}, {"id": "ing_butter", "quantity": {"value": 150.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_rosemary", "quantity": {"value": 0.12, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_beef", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.833, "unit": "bottle of 750ml"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.037, "unit": "pack of 400g"}}]', '[{"ingredients":["2.5 kg / 5 lb standing rib roast / prime rib (, bone in (Note 1))","1 onion (, unpeeled, quartered (brown, yellow, white))","1 head of garlic (, unpeeled, halved horizontally)","5 sprigs thyme","3 sprigs rosemary"]},{"ingredients":["150g/ 10 tbsp unsalted butter (, softened)","5 garlic cloves (, minced)","2 tsp finely chopped fresh rosemary (or 1 tsp dried)","2 tsp finely chopped fresh thyme (or 1 tsp dried)","2 tsp salt","1 tsp black pepper"],"purpose":"Garlic Herb Butter:"},{"ingredients":["1 1/2 cups beef broth/stock (, low salt)","2 1/2 cups dry red wine (Note 2)","1 tbsp cornflour/cornstarch (optional, Note 3)"],"purpose":"Red Wine Sauce:"}]', '[{"title":"Bring Beef to room temp","description":"Take beef out of the fridge 2 - 3 hours before cooking to bring to room temp (key tip for even cooking). Pat dry with paper towel.","images":[],"step":1},{"description":"Preheat oven to 240°C/460°F (220°C fan). Adjust shelf so beef will be sitting in the middle of the oven.","images":[],"step":2},{"title":"Garlic Herb Butter","description":"Mix together.","images":[],"step":3},{"title":"Roasting bed","description":"Place onion, garlic and herbs in a heavy based oven proof skillet (or use a roasting pan).","images":[],"step":4},{"title":"Slather 1","description":"Spread a thin layer of butter on the underside of the beef (ie the bone side). Place beef on onion etc, butter side down. Spread about 2/3 of the butter on the top and sides (reserve some for Slather 2).","images":[],"step":5},{"title":"Hot oven","description":"Roast 20 minutes.","images":[],"step":6},{"title":"Slather 2","description":"Remove, spread over remaining butter. Turn oven down to 120°C/250°F (100°C fan).","images":[],"step":7},{"title":"Slow roast","description":"Roast for a further 1 1/2 hours, basting every 30 minutes with the juices in the pan, until the internal temperature is 51°C / 123.8°F in the centre (for medium rare, Note 4). Start checking the internal temp early.","images":[],"step":8},{"title":"Rest","description":"Transfer beef to plate. Cover loosely with foil and rest for 20 - 30 minutes. Internal temperature will rise to 56-58°C / 133-136.4°F (which is medium rare).","duration":25,"images":[],"step":9},{"description":"Slice beef and serve with Sauce! For a classic high-end Steakhouse experience, serve with Paris Mash and Garlic Sautéed Spinach.","images":[],"step":10},{"description":"Red Wine Sauce:","images":[],"step":11},{"description":"Place skillet with onion and garlic left in it on the stove over high heat. Add wine and beef stock, rapidly simmer for 10 minutes until it reduces by 2/3 or so, down to 1 1/2 cups or liquid.","duration":10,"images":[],"step":12},{"description":"Lower heat to medium. Mix cornflour with 2 tbsp water. Drizzle in half and stir. Sauce will thicken in 1 minute or so. Add more cornflour water mixture if you want it thicker.","images":[],"step":13},{"description":"Strain into bowl, pour into sauce jug.","images":[],"step":14}]', '["milk"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef-recipes","iconic-dishes","main-dishes","roast-beef","roasts","sunday-supper"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9cf1897bf5c6', 'en', 'US', 'Beef and Guinness Stew', 'RECIPE VIDEO ABOVE. The iconic Irish Beef and Guinness Stew is easy to make but requires patience while it slow cooks! The Guinness Beer is the secret weapon ingredient in this, creating a sauce that has wonderful deep complex flavours.', 'https://www.recipetineats.com/tachyon/2019/03/Irish-Beef-Guinness-Stew_6.jpg', 10, 180, 190, 6, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_beef", "quantity": {"value": 1.134, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_bacon", "quantity": {"value": 0.851, "unit": "pack of 200g"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_beer", "quantity": {"value": 1.333, "unit": "bottle of 330ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_carrot", "quantity": {"value": 3.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 40.0, "unit": "head"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 0.12, "unit": "bunch"}}]', '[{"ingredients":["2 tbsp olive oil","2.5 lb / 1.25 kg beef chuck (, boneless short rib or any other slow cooking beef (no bone))","3/4 tsp each salt and black pepper","3 garlic cloves (, minced)","2 onions (, chopped (brown, white or yellow))","6 oz / 180g bacon (, speck or pancetta, diced)","3 tbsp flour (all purpose/plain, Note 3 for GF)","440ml / 14.9 oz Guinness Beer (Note 1)","4 tbsp tomato paste","3 cups (750 ml) chicken stock/broth (or beef broth - Note 4)","3 carrots (, peeled and cut into 1.25 cm / 1/2\" thick pieces)","2 large celery stalks (, cut into 2cm / 1\" pieces)","2 bay leaves","3 sprigs thyme (or sub with 1 tsp dried thyme leaves)"]}]', '[{"description":"Cut the beef into 5cm/2\" chunks. Pat dry then sprinkle with salt and pepper.","images":[],"step":1},{"description":"Heat oil in a heavy based pot over high heat. Add beef in batches and brown well all over. Remove onto plate. Repeat with remaining beef.","images":[],"step":2},{"description":"Lower heat to medium. If the pot is looking dry, add oil.","images":[],"step":3},{"description":"Cook garlic and onion for 3 minutes until softening, then add bacon.","duration":3,"images":[],"step":4},{"description":"Cook until bacon is browned, then stir through carrot and celery.","images":[],"step":5},{"description":"Add flour, and stir for 1 minute to cook off the flour.","duration":1,"images":[],"step":6},{"description":"Add Guinness, chicken broth/stock and tomato paste. Mix well (to ensure flour dissolves well), add bay leaves and thyme.","images":[],"step":7},{"description":"Return beef into the pot (including any juices). Liquid level should just cover - see video or photos.","images":[],"step":8},{"description":"Cover, lower heat so it is bubbling gently. Cook for 2 hours - the beef should be pretty tender by now. Remove lid then simmer for a further 30 - 45 minutes or until the beef falls apart at a touch, the sauce has reduced and thickened slightly.","images":[],"step":9},{"description":"Skim off fat on surface, if desired. Adjust salt and pepper to taste. Remove bay leaves and thyme.","images":[],"step":10},{"description":"Serve with creamy mashed potatoes!!","images":[],"step":11}]', '["gluten"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Irish"],"categories":["beef-recipes","iconic-dishes","main-dishes","most-popular","slow-cooked-fall-apart","slow-cooker-recipes","stews","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4030ba105eb5', 'en', 'US', 'Slow Cooker Beef Stroganoff', 'Recipe video above. The slow cooked version of Beef Stroganoff! Fall apart beef smothered in a creamy Stroganoff sauce with buttery garlic mushrooms, it''s made with economical stewing beef yet tastes like a million dollars! 3 cook methods provided: stove, slow cooker or pressure cooker/instant pot* Recipe update: pursuant to some readers having difficulties with flour lumps, the steps have been updated to make it easier!', 'https://www.recipetineats.com/tachyon/2020/02/Slow-Cooked-Beef-Stroganoff-Stew_9.jpg', 15, 510, 525, 6, '[{"id": "ing_beef", "quantity": {"value": 1.75, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.15, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_butter", "quantity": {"value": 20.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.105, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.3, "unit": "jar of 200g"}}, {"id": "ing_beef_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.9, "unit": "tub of 250g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.15, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_chives_for_garnish", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1.75kg/ 3.5lb beef chuck or other stewing beef (, cut in 4cm / 1.5” cube (Note 1))","1.5 tsp each salt and pepper","2 tbsp oil","20 g/ 1 tbsp butter (, unsalted)","1 large onion (, halved then sliced into 1 cm / 2/5\" slices)","4 garlic cloves (, minced)","7 tbsp flour (, plain / all purpose)","4 tbsp Dijon Mustard","1 litre / 1 quart beef stock/broth (, reduced salt)","1 1/2 cups sour cream (, full fat best)"]},{"ingredients":["3 tbsp/ 45 g butter (, unsalted)","700 g / 1.2 lb mushrooms (, sliced into 0.5cm thick slices)","3 garlic cloves (, finely minced)","1/2 tsp salt and pepper"],"purpose":"Garlic Butter Mushrooms:"},{"ingredients":["Pasta, wide egg noodles, mashed potato","Chives for garnish"],"purpose":"Serving:"}]', '[{"title":"Season beef","description":"Pat beef dry then sprinkle with all the salt and pepper.","images":[],"step":1},{"title":"Brown beef","description":"Heat 1 tbsp oil in a large heavy based pot or skillet* over high heat. Add beef in a single layer (not squished) and brown aggressively all over - 4 minutes or so. Remove and repeat with rest of beef, adding more oil as needed.","images":[],"step":2},{"title":"Sauté aromatics","description":"Let the pot cool down a bit then return to stove. Melt half the butter, then cook garlic and onion for 3 minutes until softened.","duration":3,"images":[],"step":3},{"title":"Add flour","description":"Sprinkle the flour across the surface, then stir. Add the mustard, and stir - it will look gluey, that''s ok, it will dissolve.","images":[],"step":4},{"title":"Add stock","description":"While stirring, pour in about half the beef stock then mix so the flour mixture dissolves into the liquid. It will thicken quite quickly into a gravy-like consistency .Switch to a whisk if needed, to make it lump free. Then add remaining stock, stir well, scraping the bottom of the pot, and bring to simmer. Cook using chosen method below.","images":[],"step":5},{"title":"SLOW COOKING","description":"choose method:","images":[],"step":6},{"title":"Slow cooker","description":"Transfer all liquid into slow cooker. Add beef, then slow cook 8 hours on LOW or 5 hours on HIGH.","images":[],"step":7},{"title":"Stove","description":"Add beef into pot. Cover with lid and adjust heat to low/medium low so the it''s simmering gently. Simmer 2 hrs (check at 1.5 hrs) until beef beef falls apart easily.","images":[],"step":8},{"title":"Instant pot","description":"SKIP FLOUR, follow Note 5 Gluten Free option. 40 minutes on high, same method as slow cooker.","images":[],"step":9},{"title":"Other pressure cookers","description":"40 minutes on high, same method as slow cooker.","images":[],"step":10},{"description":"Melt half the butter in a large skillet over high heat. Add half the mushrooms and cook until almost golden (~3 minutes). Add half the garlic, salt and pepper, cook until golden. Remove, repeat with remaining butter, mushrooms and garlic.","images":[],"step":11},{"description":"Mix sour cream with 1.5 cups of liquid from slow cooker (Note 2), then gently stir into stew - careful, the beef is delicate!","images":[],"step":12},{"description":"Gently stir in mushrooms.","images":[],"step":13},{"description":"Serve over noodles, pasta or mashed potato, sprinkled with chives!","images":[],"step":14}]', '["egg","gluten","milk","mustard"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Russian(ish)","Western"],"categories":["beef-recipes","slow-cooked-fall-apart","slow-cooker-recipes","stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ca60c453049b', 'en', 'US', 'Pot Roast', 'Recipe VIDEO above. The ultimate one-pot family meal! Meltingly tender slow cooker beef and vegetables smothered in a gravy like sauce - because it''s so much tastier than just a watery broth! I like to make this in my slow cooker but I''ve also added directions for pressure cooker, stove and oven.', 'https://www.recipetineats.com/tachyon/2018/09/Slow-Cooker-Beef-Pot-Roast-4.jpg', 15, 500, 515, 8, '[{"id": "ing_bread", "quantity": {"value": 2.0, "unit": "loaf"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_carrot", "quantity": {"value": 5.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 3.0, "unit": "head"}}, {"id": "ing_wine", "quantity": {"value": 0.333, "unit": "bottle of 750ml"}}, {"id": "ing_beef", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_rosemary", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_potato", "quantity": {"value": 750.0, "unit": "bag of 2kg"}}]', '[{"ingredients":["2 kg / 4 lb beef chuck roast , rolled (Note 1)","1 tsp each salt and pepper","2 tbsp olive oil","1 onion ((large), cut into large dice)","5 garlic cloves (, peeled and smashed (Note 2a))","5 carrots (, peeled and cut into 2.5cm/1\" pieces)","3 celery stalks (, cut into 4 cm / 1.5\" pieces)","1 cup (250ml) dry red wine (sub with beef broth)","3 cups (750ml) beef broth (, salt reduced)","1/3 cup (50g) flour (plain / all purpose) (GF - Note 2b)","1 tsp dried rosemary","1 1/2 tsp dried thyme","750g / 1.5 lb potatoes (, peeled and cut into 2.5 cm / 1\" pieces)"]}]', '[{"description":"Pat beef dry with paper towels. Sprinkle generously with salt and pepper all over.","images":[],"step":1},{"description":"Heat oil in a skillet over high heat. Brown aggressively all over - a deep dark brown crust is essential for flavour base! Should take about 7 minutes.","images":[],"step":2},{"description":"Transfer beef to slow cooker.","images":[],"step":3},{"description":"In the same skillet, add onion and garlic. Cook for 2 minutes until onion is browned.","duration":2,"images":[],"step":4},{"description":"Add wine, reduce by half. Transfer to slow cooker.","images":[],"step":5},{"description":"Mix together flour and about 1 cup of the broth. Lumps is fine. Pour into slow cooker.","images":[],"step":6},{"description":"Add remaining broth, carrots, celery, rosemary and thyme into slow cooker.","images":[],"step":7},{"description":"Cover and slow cook on LOW for 5 hours. (45 min pressure cook on HIGH, Note 3a for Oven and Stove)","images":[],"step":8},{"description":"Add potato, slow cook on LOW for 3 hours. (10 min pressure cooker on HIGH, Note 3b)","images":[],"step":9},{"description":"Remove beef. Rest for 5 minutes, then slice thickly.","duration":5,"images":[],"step":10},{"description":"Adjust salt and pepper of Sauce to taste.","images":[],"step":11},{"description":"Serve beef with vegetables and plenty of sauce! Bread also terrific for mopping up sauce - try these No Knead Dinner Rolls, No Yeast Irish Soda Bread or these fabulous Cheese Muffins.","images":[],"step":12}]', '["gluten"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef-recipes","main-dishes","nagis-picks","one-pot-recipes","slow-cooker-recipes","stews","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5515756f9dd9', 'en', 'US', 'Shredded Beef Chili Con Carne', 'Recipe video above. My signature Chili recipe, made with pulled beef! The sauce has richer, more complex flavours that you can never achieve using ground / mince beef like traditional Chilli Con Carne. If you''re out of time, skip browning the beef - then it''s a 5 minute prep job, "set and forget". Freezes exceptionally well.', 'https://www.recipetineats.com/tachyon/2014/10/Shredded-Beef-Chili.jpg', 15, 480, 495, 12, '[{"id": "ing_beef", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 6.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_kidney_beans", "quantity": {"value": 2.0, "unit": "can of 400g"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}]', '[{"ingredients":["2kg / 4lb beef chuck roast (Note 1)","2 tbsp olive oil","1 tsp EACH salt and pepper"],"purpose":"Beef Browning"},{"ingredients":["4 cloves garlic (, minced)","2 onions (, diced (brown, yellow, white))","1 large red capsicum/bell pepper (, seeds removed and diced)","1/2 cup (125ml) beef broth/stock (or water)"],"purpose":"Flavour Base"},{"ingredients":["800g / 28oz canned red kidney beans (, drained (2 x 400g/14oz cans))","800g/28oz crushed tomato","1/4 cup tomato paste","1 cup (250 ml) beef broth/stock"],"purpose":"Chili"},{"ingredients":["1 tbsp EACH cumin, onion powder, garlic powder, oregano, smoked paprika (or plain paprika)","1 tsp cayenne pepper (, or to taste (spiciness))","1 tsp salt","1/2 tsp black pepper"],"purpose":"Homemade Chili Spices (Note 2)"},{"ingredients":["3 tbsp cornflour / corn starch","1/4 cup (65ml) beef broth/stock or water"],"purpose":"Sauce Thickener"}]', '[{"description":"Brown Beef (Note 2)","images":[],"step":1},{"description":"Cut the beef into four equal sizes. Season with salt and pepper.","images":[],"step":2},{"description":"Heat 1/2 the oil in a heavy based skillet over high heat. Brown beef well all over - about 1 1/2 minute on each side, then remove onto a plate.","images":[],"step":3},{"description":"Saute Aromatics","images":[],"step":4},{"description":"Add a touch more oil if needed.","images":[],"step":5},{"description":"Add the garlic, onion and capsicum (bell peppers) and saute until caramelised, around 2 to 3 minutes.","images":[],"step":6},{"description":"Add 1/2 cup beef broth, bring to simmer, scraping the bottom of the skillet to dissolve brown bits into the liquid. Simmer for 30 seconds then scrape it all into the slow cooker.","duration":0.5,"images":[],"step":7},{"description":"Slow Cook!","images":[],"step":8},{"description":"In the slow cooker, add the beans, tomato, tomato paste, beef broth and Chili Spices. Stir, then add beef - it won''t be fully submerged, beef juices will raise liquid level (see video).","images":[],"step":9},{"description":"Cook on low for 8 hours.","images":[],"step":10},{"description":"Remove beef from slow cooker and shred with two forks.","images":[],"step":11},{"description":"Mix cornflour and 1/4 cup beef stock, then pour into slow cooker. Add beef, then slow cook for a further 20 minutes to allow sauce to thicken.","images":[],"step":12},{"description":"Adjust seasoning to taste with salt and pepper.","images":[],"step":13},{"description":"To serve","images":[],"step":14},{"description":"Serve with garnishes of choice, such as sour cream, guacamole or diced avocado, grated cheese, coriander/cilantro. Serve either with corn chips or cornbread for dunking, or serve over rice!","images":[],"step":15}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["main_course"],"cuisine":["Tex-Mex","Western"],"categories":["beef-recipes","dietary","gluten-free-recipes","main-dishes","most-popular","quick-and-easy","slow-cooked-fall-apart","slow-cooker-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5c295f901f3c', 'en', 'US', 'Slow Cooked Beef Cheeks', 'Recipe video above. These slow cooked beef cheeks are so meltingly tender that you can eat them with a spoon. And the sauce is so flavourful you''ll want to drink it out of a cup! This recipe makes enough to serve 6 people, made with 6 small beef cheeks (or share 4 large ones). Leftovers are brilliant to freeze, or turn into a quick Ragu to toss through pasta or making a Pie!', 'https://www.recipetineats.com/tachyon/2014/08/Beef-Cheeks.jpg', 15, 210, 225, 6, '[{"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_beef_cheeks", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_thyme", "quantity": {"value": 0.24, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_wine", "quantity": {"value": 0.667, "unit": "bottle of 750ml"}}, {"id": "ing_salt", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["3 tbsp olive oil (, separated)","1.5 kg/3lb beef cheeks (, (4 large or 6 small beef cheeks))","1 onion (white, brown or yellow), roughly diced (about 1 cup)","1 celery stalk (, roughly diced (about 1 cup))","1 carrot (, roughly diced (about 3/4 cup))","4 garlic cloves (, minced)","6 stems of fresh thyme ( or 1 1/2 tsp dried thyme leaves)","4 dried bay leaves (or 3 fresh bay leaves)","1 cup (250 ml) beef stock (broth)","2 cups (500 ml) red wine (full bodied eg. cabernet sauvignon or merlot)","2 - 3 tsp salt (, separated)","Black pepper"]}]', '[{"title":"Prepare the beef cheeks","description":"cut off any large, fatty membrane. Pat dry then use 1 tsp of salt and black pepper to season the beef all over.","images":[],"step":1},{"description":"Heat 2 tbsp olive oil in a large heavy based pot over high heat. Sear half the beef cheeks on each side until nicely browned. Remove beef cheeks onto a plate, repeat with remaining cheeks.","images":[],"step":2},{"description":"Turn down the heat to medium high and heat the remaining 1 tbsp of olive oil. Add garlic and onion. Sauté for 3 minutes until onion is becoming translucent.","duration":3,"images":[],"step":3},{"description":"Add the celery and carrot,s sauté for a further 3 minutes.","images":[],"step":4},{"description":"Follow directions for your chosen cooking method below.","images":[],"step":5},{"description":"Slow Cooker Directions","images":[],"step":6},{"description":"Pour the onion mixture into the slow cooker and place the beef cheeks on top.","images":[],"step":7},{"description":"Pour the wine into the pot and return to heat. Turn the heat up to high, bring to simmer and let it simmer for 1 minute (to cook out the wine a bit). Scrape the brown bits off the bottom of the pan so it mixes in with the wine.","duration":1,"images":[],"step":8},{"description":"Pour the wine into the slow cooker, then all the remaining ingredients, starting with a pinch of salt and pepper (add more to taste later).","images":[],"step":9},{"description":"Cook in the slow cooker on Low for 8 hours or High for 6 hours for 250g/8oz size beef cheeks or Low for 10 - 12 hours or High for 8 hours for 350g/12oz beef cheeks.","images":[],"step":10},{"description":"Open the slow cooker and remove the beef cheeks. Discard the thyme stems and bay leaves.","images":[],"step":11},{"description":"Use a handheld stick blender to puree the braising liquid into a smooth Sauce - it will change from a dark brown to a lighter brown colour.","images":[],"step":12},{"description":"Transfer liquid into saucepan, simmer on stove on medium high until the Sauce turns a darker brown colour and reduces by about 1/4 to 1/3, to a gravy consistency - about 10 minutes.","images":[],"step":13},{"description":"Do a taste test and adjust the seasoning (salt and pepper) to your taste.","images":[],"step":14},{"description":"Remove from heat, return beef cheeks to the Sauce, cover and keep warm until ready to serve.","images":[],"step":15},{"description":"Pressure Cooker Directions","images":[],"step":16},{"description":"Follow the Slow Cooker directions but cook on high in your pressure cooker for 1 hour on high for small cheeks (around 250g/8oz each).","images":[],"step":17},{"description":"Stovetop and Oven Directions","images":[],"step":18},{"description":"Pour the wine into the pot / casserole dish (with the onion mixture) and stir to scrape the brown bits off the bottom of the pot. Bring wine to simmer for 1 minute.","duration":1,"images":[],"step":19},{"description":"Add remaining ingredients, starting with a pinch of salt and pepper (add more to taste later), the place lid on.","images":[],"step":20},{"title":"Stove","description":"Simmer on medium low for 2 to 2 1/2 hours until the cheeks are very tender, turn at least once during cooking.","images":[],"step":21},{"title":"Oven","description":"160C/320F for 3 to 3 1/2 hours .","images":[],"step":22},{"description":"Remove the beef cheeks from sauce. Discard the thyme stems and bay leaves.","images":[],"step":23},{"description":"Use a handheld stick blender to puree the braising liquid into a smooth Sauce - it will change from a dark brown to a lighter brown colour.","images":[],"step":24},{"description":"Bring the Sauce to simmer over medium heat and simmer until it turns a darker brown colour and reduces by about 1/4 to 1/3, to a gravy consistency - about 3 to 5 minutes.","images":[],"step":25},{"description":"Do a taste test and adjust the seasoning (salt and pepper) to your taste.","images":[],"step":26},{"description":"Remove from heat, return beef cheeks to the Sauce, cover and keep warm until ready to serve.","images":[],"step":27},{"description":"To Serve","images":[],"step":28},{"description":"Serve beef cheeks on Paris Mash (ultimate creamy mashed potato!) or Creamy Mashed Cauliflower, drizzled with a generous amount of Sauce. Garnish with finely chopped parsley if desired.","images":[],"step":29}]', '[]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["main_course"],"cuisine":["Italian"],"categories":["beef-recipes","italian-recipes","main-dishes","most-popular","slow-cooked-fall-apart","slow-cooker-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_39a03d526671', 'en', 'US', 'How to cook steak - like a chef!', 'Recipe video above. Here''s a cheffy way to cook steak that really makes the most of a good steak - or fancies up economical steaks! Basting with garlic-thyme infused butter as the steak is cooking adds flavour and luxury to the steak. You''ll feel like a total pro cooking it and it''ll rival the best steakhouse in town!', 'https://www.recipetineats.com/tachyon/2019/07/Cheffy-Garlic-Butter-Steak_9.jpg', 5, 6, 11, 1, '[{"id": "ing_fish_fillets", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 75.0, "unit": "block of 250g"}}, {"id": "ing_rosemary", "quantity": {"value": 0.24, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}]', '[{"ingredients":["1 - 2 boneless ribeye or scotch fillet (, 2.5 cm / 1\" thick, approx 300g/10 oz each (Note 1))","1 tbsp vegetable oil","Salt and pepper","75g / 5 tbsp unsalted butter (, cut into 1.25cm / 1/2\" cubes (Note 2))","6 sprigs fresh thyme or 3 sprigs rosemary","5 garlic cloves (, peeled and smashed to split (Note 3))"]}]', '[{"title":"Bring to room temp","description":"Take the steak out of the fridge 30 minutes prior to bring to room temperature.","images":[],"step":1},{"title":"Dry steaks","description":"Pat dry with paper towels.","images":[],"step":2},{"title":"Heat skillet","description":"Heat oil in a heavy based skillet over high heat until it is very hot - you should see smoke!","images":[],"step":3},{"title":"Season","description":"Sprinkle each side of the steak generously with salt and pepper, then immediately place in the skillet.","images":[],"step":4},{"title":"Sear Side 1: Cook for 2","description":"2.5 minutes until you get a great crust, then turn.","images":[],"step":5},{"title":"Garlic Butter","description":"Leave for 1 minute, then push steaks to one side and toss in butter, garlic and thyme. BE CAREFUL - the thyme will sputter!","duration":1,"images":[],"step":6},{"title":"Baste","description":"As soon as the butter is melted, continuously spoon the butter over the steak until it''s cooked to your liking - 2 minutes in total for the 2nd side for medium rare (52C/125F, chart below for other doneness temps)","images":[],"step":7},{"title":"Basting also renders fat on the side of the steak","description":"use tongs to sear the edges at the end if you want it browned more.","images":[],"step":8},{"title":"Rest","description":"Transfer steak to a plate and cover loosely with foil, rest for 5 to 10 minutes.","duration":7.5,"images":[],"step":9},{"description":"Serve steak with a bit of the butter from the skillet drizzled on top. Pictured in post with Crispy Smashed Potatoes.","images":[],"step":10}]', '["fish","milk"]', '["gluten_free","high_protein","keto_friendly","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef-recipes","dinner-tonight","iconic-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c2328cd05d7d', 'en', 'US', 'Mexican Shredded Beef (and Tacos)', 'Recipe video above. This is how I make Mexican Shredded Beef. The sauce is rich, thick and full of flavor, and the beef is very tender and juicy. I use this shredded beef for tacos, burritos, enchiladas, quesadillas and even to make sliders - see in post for list of ideas and directions!', 'https://www.recipetineats.com/tachyon/2015/09/Mexican-Shredded-Beef_1.jpg', 20, 180, 200, 20, '[{"id": "ing_chipotle", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_beef", "quantity": {"value": 1.361, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 10.0, "unit": "pack of 1kg"}}, {"id": "ing_oranges", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_tomato", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}]', '[{"ingredients":["1 1/2 tbsp chipotle powder (, adjust spiciness to taste (Note 5))","1 tbsp paprika","1 tbsp dried oregano","1 tsp All Spice powder (ground All Spice)","1 tsp coriander powder","2 tsp onion powder or garlic powder (OR 1 tsp of each)","1 tsp salt and pepper (, each)"],"purpose":"Spice Mix"},{"ingredients":["1 - 2 tbsp olive oil","3 lb / 1.5kg beef chuck or brisket ((or gravy or any other slow cooking beef) cut into 4 pieces)","5 garlic cloves, minced","1 onion (, diced (yellow, brown or white))","3/4 cup (185 ml) orange juice","2 tbsp lime juice","14 oz / 400g can crushed tomatoes","2 cups (500 ml) beef or chicken broth/stock","1/2 cup (125ml) water","Salt and pepper"],"purpose":"Beef"}]', '[{"description":"Combine the Spice Mix ingredients in a bowl. Sprinkle 4 teaspoons over the beef and pat so it sticks.","images":[],"step":1},{"description":"Heat the olive oil in a large heavy based pot over high heat. Add the beef (in batches if necessary) and brown well on all sides. Remove onto a plate.","images":[],"step":2},{"description":"Turn the stove down to medium. If the pot looks dry, add more olive oil.","images":[],"step":3},{"description":"Add the garlic and onion and cook for 3 minutes until soft.","duration":3,"images":[],"step":4},{"description":"Add the orange juice and lime juice, and scrape the bottom of the pot so the brown bits mix into the liquid.","images":[],"step":5},{"description":"Add tomato, beef stock, water and remaining spice mix. Mix, then return beef into pot.","images":[],"step":6},{"description":"Put the lid on, bring to a simmer then turn the stove down so it is bubbling gently, not rapidly.","images":[],"step":7},{"description":"Cook for 2 hours, then remove lid and simmer for another 30 minutes until beef is tender enough to shred. (Note 2 other cook methods).","images":[],"step":8},{"description":"Remove the beef from sauce, shred with 2 forks.","images":[],"step":9},{"description":"Leave the sauce to simmer with the lid off for 10 to 15 minutes to reduce and thicken to your taste. Adjust salt to taste. Optional: puree with stick blender to make it smooth (I do this for company)","duration":12.5,"images":[],"step":10},{"description":"Toss beef back into the sauce (can reserve some Sauce for drizzling on tacos if you want, there''s plenty).","images":[],"step":11},{"description":"Transfer beef into large dish and serve. See notes for suggestions.","images":[],"step":12},{"description":"To make tacos, serve the beef with warmed small tortillas, avocado slices, Pico de Gallo, shredded cheese, sour cream, lime wedges and extra cilantro/coriander leaves.","images":[],"step":13}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["beef-recipes","dietary","gluten-free-recipes","main-dishes","mexican-recipes","quick-and-easy","slow-cooker-recipes","taco-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b81fef89157c', 'en', 'US', 'Marinated Roast Beef', 'Recipe video above. Use this marinade to transform economical roast beef into something special! It will infuse with flavour, add juiciness and make the beef tender. KEY TIP: internal temp of beef rises by 8C/14F while resting, so must take out of oven BEFORE desired internal temp, see Note 4. Marinade 2 - 3 days.', 'https://www.recipetineats.com/tachyon/2019/05/Marinated-Roast-Beef_7-1.jpg', 10, 70, 80, 6, '[{"id": "ing_bolar_blade_top_blade_roast_eye_of_round_roast_oyster_blade_roast", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_mustard", "quantity": {"value": 0.15, "unit": "jar of 200g"}}, {"id": "ing_balsamic_vinegar", "quantity": {"value": 0.15, "unit": "bottle of 250ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.5, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_rosemary", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_potato", "quantity": {"value": 3.0, "unit": "bag of 2kg"}}, {"id": "ing_carrot", "quantity": {"value": 4.0, "unit": "pack of 1kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.375, "unit": "kg"}}]', '[{"ingredients":["1.5kg / 3 lb Bolar Blade (pictured in post), Top Blade Roast, Eye of Round Roast, Oyster Blade Roast","1 tbsp olive oil"]},{"ingredients":["3 garlic cloves (, minced (2.5 tsp jar))","1 tbsp Worcestershire Sauce","2 tbsp dijon mustard","2 1/2 tbsp balsamic vinegar","1/2 cup soy sauce","1/4 cup olive oil","1 tbsp white sugar","2 tsp onion powder","1 tsp black pepper","2 tsp dried thyme","1 tsp dried rosemary"],"purpose":"Marinade (Note 2):"},{"ingredients":["3 potatoes (, cut into 5cm/2\" chunks)","4 carrots (, peeled cut into 4cm/1.7\" pieces)","Salt and pepper"],"purpose":"Vegetables (optional):"},{"ingredients":["1/4 cup flour","2 1/2 cups beef broth ((stock), low sodium)","3/4 tsp black pepper (, coarsely ground)"],"purpose":"Gravy (optional, Note 4)"}]', '[{"description":"Mix Marinade ingredients in a large ziplock bag.","images":[],"step":1},{"description":"Add beef, marinade for 2 days (24 hrs min, 3 days max).","images":[],"step":2},{"description":"Cooking:","images":[],"step":3},{"title":"De-chill","description":"Take beef out of fridge 1 hour prior.","images":[],"step":4},{"description":"Preheat oven to 240C/450F (both fan and regular ovens).","images":[],"step":5},{"title":"Toss vegetables","description":"Put the vegetables in an ovenproof skillet. Remove beef from marinade. Pour all the marinade onto the vegetables and toss. Top with the beef.","images":[],"step":6},{"title":"High temp roast","description":"Drizzle beef with oil, roast 20 minutes.","images":[],"step":7},{"title":"Keep roasting","description":"Turn oven down to 180C/350F (160C fan-forced), roast for a further 35 - 40 minutes or until a meat thermometer inserted into the centre registers 44°C / 111°F for medium rare (Note 3 for other doneness). Note - thinner and smaller pieces than pictured / per ingredients will cook faster, so check earlier!","images":[],"step":8},{"title":"Rest","description":"Remove beef onto plate, cover loosely in foil and rest for 20 - 30 minutes (internal temp will rise to 52°C / 125°F which is perfect medium rare!).","duration":25,"images":[],"step":9},{"title":"Brown vegetables","description":"Return vegetables to oven to brown a bit, if needed.","images":[],"step":10},{"description":"To serve, slice beef thinly. Serve roast veg and juices in the skillet OR make gravy (below)!","images":[],"step":11},{"description":"Gravy (optional)","images":[],"step":12},{"description":"Remove vegetables, leave juices in skillet. Skim excess off fat from surface, leave behind 2 tbsp.","images":[],"step":13},{"title":"Flour","description":"Place on medium high heat on stove. Add flour and stir for 1 minute.","duration":1,"images":[],"step":14},{"title":"Stock","description":"Slowly add beef stock while stirring. If needed, use whisk to remove lumps.","images":[],"step":15},{"title":"Thicken","description":"Bring to simmer for 2 minutes until thickens to gravy consistency. Stir in pepper and salt, if needed (taste to check). Serve with beef.","duration":2,"images":[],"step":16}]', '["gluten","mustard","shellfish","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef-recipes","iconic-dishes","roast-beef","roasts","sunday-supper"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1203f6abcbd2', 'en', 'US', 'Schnitzel!', 'Recipe VIDEO above. Golden brown and extra crunchy schnitzel. No need to deep fry, just shallow fry it. Make schnitzel with pork, chicken, veal, beef or turkey! These are quite big - about 22 cm/ 9" long, but they are thin.', 'https://www.recipetineats.com/tachyon/2017/08/Schnitzel-11.jpg', 10, 15, 25, 4, '[{"id": "ing_pork", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_beef_steak", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_turkey_breast_cutlets", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_bread", "quantity": {"value": 0.281, "unit": "loaf"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}]', '[{"ingredients":["600g / 1.2 lb boneless pork (4 steaks / boneless chops, about 150 g/5 oz each)","600g / 1.2 lb large chicken breasts (2 pieces,300g / 10 oz each)","600g / 1.2 lb veal or beef steaks (4 pieces, 150g / 5 oz each)","600g / 1.2 lb turkey breast cutlets (4 pre sliced pieces, 150g / 5 oz each)"],"purpose":"Choose ONE of these:"},{"ingredients":["Salt and pepper","3/4 cup flour","2 eggs","1 1/2 cups panko breadcrumbs (Note 1)","Oil for frying (canola, vegetable)"],"purpose":"Schnitzel:"}]', '[{"title":"Chicken breast prep","description":"cut in half horizontally to create two steaks.","images":[],"step":1},{"description":"Place the protein of choice on a work surface and cover with a sheet of baking paper or cling wrap. Use a rolling pin to pound to even thickness about 0.8 cm / 1/3\" thick (don''t pound too thin, hard to handle / might tear).","images":[],"step":2},{"description":"Sprinkle both sides of meat with salt and pepper.","images":[],"step":3},{"description":"Place flour in one dish, panko in another (or use a large tray for both like I did, see photos), and whisk eggs in a bowl.","images":[],"step":4},{"description":"Coat meat in flour, shake off excess. Dip into egg, shake off excess. Press into breadcrumbs, and turn, pressing to adhere, then transfer to plate. Repeat.","images":[],"step":5},{"description":"Heat 1.5cm / 3/5\" oil in a heavy based deep skillet over medium high heat.","images":[],"step":6},{"description":"Dip the end of a schnitzel in to check if the oil is hot enough - it should sizzle straight away (see video).","images":[],"step":7},{"description":"Carefully place 2 schnitzels in the oil and cook for 3 minutes until deep golden, turn then cook the other side for 3 minutes.","duration":3,"images":[],"step":8},{"description":"Transfer to a paper towel lined plate to drain excess oil. Repeat with remaining schnitzel.","images":[],"step":9},{"title":"Serve with lemon wedges","description":"I usually serve schnitzel plain like this. Or see note for Mushroom Gravy recipe. Also see note for potato rosti, pictured in post.","images":[],"step":10}]', '["egg","gluten"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Austrian","German","Western"],"categories":["beef-recipes","chicken-breast-recipes","chicken-recipes","deep-fried-recipes","dinner-tonight","main-dishes","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a62f6300e01c', 'en', 'US', 'Braised Beef Short Ribs in Red Wine Sauce', 'Recipe video above. This is the sort of food you''ll pay top dollar for at fine dining restaurants but is actually very easy to make at home. Wine provides complexity and depth of flavour so you only need a few ingredients! Oven is best but stove/slow cooker/pressure cooker/IP also work, directions in notes.', 'https://www.recipetineats.com/tachyon/2019/02/Slow-Cooked-Braised-Beef-Short-Ribs_3.jpg', 15, 180, 195, 5, '[{"id": "ing_beef_steak", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.15, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_steak", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.667, "unit": "bottle of 750ml"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_thyme", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}]', '[{"ingredients":["5 - 6 beef short ribs (, 300-400g/10-14oz each (Note 1))","1.5 tsp each salt and pepper","2 tbsp olive oil","3 garlic cloves (, crushed)","1 large onion (, chopped (brown, yellow or white))","2 celery ribs (, chopped)","2 carrots (, chopped)","2 tbsp tomato paste","2 cups (500ml) dry red wine (Note 2)","2 cups (500ml) beef stock/broth, low sodium","2 sprigs thyme (optional)","2 bay leaves"]}]', '[{"description":"Preheat oven to 160°C/325°F.","images":[],"step":1},{"description":"Sprinkle beef all over with salt and pepper.","images":[],"step":2},{"description":"Heat oil in a large ovenproof pot over high heat. Add half the ribs and brown aggressively all over (~5 - 7 min in total). Remove and repeat with remaining ribs, then remove.","images":[],"step":3},{"description":"Turn heat down to medium. Add onion and garlic into the same pot and cook for 2 minutes.","duration":2,"images":[],"step":4},{"description":"Add carrot and celery, cook for 5 minutes until carrot is softened and sweet.","duration":5,"images":[],"step":5},{"description":"Add tomato paste and cook for 1 minute.","duration":1,"images":[],"step":6},{"description":"Add wine, broth, thyme and bay leaves. Stir until tomato paste is dissolved.","images":[],"step":7},{"description":"Return beef into liquid, arranging them so they are submerged (Note 3).","images":[],"step":8},{"description":"Cover with lid and transfer to oven for 3 hours, or until the meat can easily be pried apart with forks. (Note 4 Other cook methods)","images":[],"step":9},{"description":"Remove beef carefully, keeping the meat on the bone. (Note 4) Cover to keep warm.","images":[],"step":10},{"description":"Strain all liquid in the pot, pressing juices out of the onion, carrot etc. (Optional - can skip if you don''t mind chunky sauce) Return sauce into pot, bring to simmer and stir. Adjust as necessary - simmer to reduce/thicken, add water to thin, season with salt and pepper if needed.","images":[],"step":11},{"description":"Place beef on serving plate, spoon over sauce. Serve!","images":[],"step":12}]', '[]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":[],"categories":["beef-recipes","iconic-dishes","slow-cooker-recipes","stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0fc950cea8d9', 'en', 'US', 'Beef Stew', 'Recipe VIDEO above. Just a great, classic beef stew with meltingly tender beef smothered in a rich sauce. Be sure to brown the beef well - it''s key for the deep rich colour and flavour of the sauce! Great on the day, but even better the next day so make ahead if you can. Stove, oven, slow cooker or pressure cooker.', 'https://www.recipetineats.com/tachyon/2018/04/Beef-Stew_0.jpg', 15, 160, 165, 6, '[{"id": "ing_beef", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_carrot", "quantity": {"value": 3.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.667, "unit": "bottle of 750ml"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 0.16, "unit": "bunch"}}, {"id": "ing_potato", "quantity": {"value": 400.0, "unit": "bag of 2kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}]', '[{"ingredients":["1.2 kg / 2.4lb chuck beef (, cut into 3.5 cm / 1.5\" cubes (Note 1))","1 tsp each salt and pepper","3 tbsp olive oil (, divided)","1 large onion (, halved then cut into 1 cm / 2/5\" slices)","4 garlic cloves (, minced)","3 carrots (, cut into 2.5cm / 1\" pieces on the diagonal)","2 celery stalks (, cut into 2.5 cm / 1\" pieces)","1/3 cup / 50g flour","3 cups / 750ml beef broth / stock (, salt reduced)","2 cups / 500 ml red wine (, bold and dry (Cab Sauv, Burgundy, Merlot) (Note 2))","2 tsp Worcestershire Sauce","2 tbsp tomato paste","2 bay leaves (, fresh or dried)","4 sprigs thyme","400 g / 14 oz baby potatoes (, halved)","More salt and pepper (, to taste.)"]}]', '[{"description":"Sprinkle beef with salt and pepper.","images":[],"step":1},{"description":"Heat 1 1/2 tbsp oil in a large, heavy based casserole pot over high heat until just starting to smoke.","images":[],"step":2},{"description":"Add 1/3 of the beef and brown aggressively all over - about 4 minutes. Remove to bowl, repeat with remaining beef, adding more oil if required.","images":[],"step":3},{"description":"Turn down heat to medium high. Add 1 tbsp oil if required. Add onion and garlic, cook for 2 minutes until onion is softened slightly and golden on the edge.","duration":2,"images":[],"step":4},{"description":"Add carrot and celery, stir for 1 minute to coat in flavours.","duration":1,"images":[],"step":5},{"description":"Sprinkle flour evenly across surface, then stir to coat.","images":[],"step":6},{"description":"Add broth, red wine, tomato paste and Worcestershire sauce. Stir to dissolve tomato paste and flour into liquid.","images":[],"step":7},{"description":"Add cooked beef (including any juices), thyme, bay leaf and potato. Stir. Water level should almost fully cover everything (see video), if not, add a touch of water.","images":[],"step":8},{"description":"Bring to simmer, then adjust heat to low / medium low so it''s simmering gently. (Note 3 for other cooking methods)","images":[],"step":9},{"description":"Cover and cook for 1 hour 45 minutes or until beef is pretty tender (check with 2 forks at 1.5 hrs).","images":[],"step":10},{"description":"Remove lid and simmer for further 30 minutes or until sauce reduces slightly. It should be like a thin gravy (see video) and beef should now be very tender.","images":[],"step":11},{"description":"Season to taste with salt and pepper.","images":[],"step":12},{"description":"Serve over creamy mashed potato with a sprig of fresh thyme for decoration or a sprinkle of parsley (Note 4).","images":[],"step":13}]', '["gluten"]', '[]', '{"mealType":["dinner"],"cuisine":[],"categories":["beef-recipes","dinner-tonight","main-dishes","one-pot-recipes","quick-and-easy","slow-cooked-fall-apart","slow-cooker-recipes","stews","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c32a52dc825b', 'en', 'US', 'Mushroom Sauce', 'Recipe video above. From steaks to chicken, chops to pasta, this creamy Mushroom Sauce is one you''ll make over and over again. See in post for more uses!Luxurious yet simple, the key here is getting complexity into the sauce using wine, parmesan and broth. See note for how to lighten this up.Makes around 3 cups - enough to generously smother 4 to 5 pieces of protein, or toss through pasta for 3 to 4 people.', 'https://www.recipetineats.com/tachyon/2018/09/Creamy-Mushroom-Sauce_3.jpg', 8, 12, 20, 4, '[{"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_mushroom", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_wine", "quantity": {"value": 0.083, "unit": "bottle of 750ml"}}, {"id": "ing_chicken", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["2 tbsp unsalted butter","1/2 tbsp olive oil","300g / 10 oz mushrooms (, sliced (Note 1))","Pinch of salt and pepper","2 garlic cloves (, minced)","1/4 cup (65 ml) white wine or rose (, dry (Note 2 subs))","1/2 cup (125 ml) chicken or vegetable broth","1 cup (250 ml) heavy / thickened cream (Note 3)","1/2 cup parmesan (,finely grated (30g / 1 oz) (Note 4))","2 tsp fresh thyme leaves (or 1/4 - 1/2 tsp dried)"]}]', '[{"description":"Heat oil and melt butter in a skillet over medium high heat. Add mushrooms and leisurely cook until golden brown - takes about 4 to 5 minutes. No need to stir constantly.","images":[],"step":1},{"description":"Just before they''re done, add the garlic and a pinch of salt and pepper. Cook until garlic is golden (~ 1 minute).","images":[],"step":2},{"title":"Add white wine","description":"it will sizzle! Stir, scraping the bottom of the skillet, for 1 minute or until mostly evaporated.","duration":1,"images":[],"step":3},{"description":"Add broth, cream and parmesan. Stir, then lower heat to medium so the sauce is simmering - do not boil rapidly, cream may split.","images":[],"step":4},{"title":"Stir occasionally and simmer for 2","description":"3 minutes until it thickens. It shouldn''t be super thick, this is a rich sauce.","duration":2.5,"images":[],"step":5},{"description":"Stir through thyme, adjust salt and pepper to taste. Remove from stove.","images":[],"step":6},{"description":"Serve over steak or other cooked protein. Toss through pasta, stuff into baked potatoes, serve with roast beef, chicken or pork, smothered omelettes. See in post for more ideas!","images":[],"step":7}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["beef-recipes","chicken-breast-recipes","chicken-recipes","dinner-tonight","mushroom-recipes","quick-and-easy","roast-beef","sauces"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d2c740108b09', 'en', 'US', 'Homemade Pastrami Without a Smoker', 'Recipe video above. This is an easy homemade Pastrami for all the poor sods like myself who don''t live around the corner from a New York Jewish deli. Tender, juicy and with the signature pastrami spice crust, this is astonishingly straight forward to make - and is outrageously good!ALSO - use the pastrami to make homemade Rebuen sandwiches!', 'https://www.recipetineats.com/tachyon/2014/05/Homemade-Pastrami-slices.jpg', 20, 660, 680, 6, '[{"id": "ing_beef", "quantity": {"value": 1.814, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 1.2, "unit": "jar of 50g"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_mustard", "quantity": {"value": 0.037, "unit": "jar of 200g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_liquid_smoke", "quantity": {"value": 2.0, "unit": "unit"}}]', '[{"ingredients":["4 lbs / 2kg good corned beef, with a thick fat cap (Note 1)"]},{"ingredients":["4 tbsp fresh coarsely ground black pepper","2 tbsp coriander powder","1 1/2 tsp mustard powder","1 tbsp brown sugar","1 tbsp smoked paprika","2 tsp garlic powder","2 tsp onion powder","2 tbsp liquid smoke (optional)"],"purpose":"Spice Mix:"}]', '[{"description":"Mix Spice Mix and spread out on a tray. Pat beef dry then roll in Spice Mix, coating well all over. Sprinkle with liquid smoke it using (I rarely use this).","images":[],"step":1},{"description":"Place beef fat cap side down and wrap in a large sheet of foil. Repeat again with another sheet of foil and flip the beef so the fat cap is on the top.","images":[],"step":2},{"description":"Place rack in slow cooker (Note 2), place beef on rack. Slow cook for 10 hours on low or electric pressure cook for 1 hour 40 minutes (see notes for oven).","images":[],"step":3},{"description":"Remove beef, cool then refrigerate for 6 hours +. Reserve juices in slow cooker.","images":[],"step":4},{"description":"Unwrap beef. Place rack on tray, place beef on rack. Bake 30 minutes at 180C/350F until spice crust is set.","images":[],"step":5},{"title":"Remove from oven, slice thinly","description":"pastrami will be tender. Place some pastrami in a dish, spoon over a bit of reserved juices. Cover and microwave to warm (I like to add a slice of Swiss cheese).","images":[],"step":6},{"title":"New York Deli style Pastrami Sandwich","description":"Pile high on toasted rye bread slathered with plenty of mustard of choice. Serve with pickles on the side! Plus plain potato crisps (for the full deli experience!)","images":[],"step":7},{"title":"Rebuen sandwiches","description":"see this recipe.","images":[],"step":8}]', '["mustard"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["American"],"categories":["beef-recipes","iconic-dishes","main-dishes","quick-and-easy","sandwiches-and-sliders","slow-cooker-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5b1073ac6175', 'en', 'US', 'Steak with Creamy Peppercorn Sauce', 'Recipe video above. One of the best steak sauces in this world, this is the creamy peppercorn sauce used in Steak au Poivre. It''s super simple because it''s made using the steak drippings and either brandy or cognac. The alcoholic taste is cooked out and you''re left with an amazing sweet/savoury/creamy sauce with great depth of flavour and beautiful pops of heat from the peppercorns. Use crushed black peppercorns for spicier or canned green peppercorns for more mild heat (I much prefer black, not really a fan of green canned).', 'https://www.recipetineats.com/tachyon/2018/05/Steak-with-Creamy-Peppercorn-Sauce_5.jpg', 5, 12, 17, 2, '[{"id": "ing_beef_steak", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 2.0, "unit": "jar of 50g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_brandy", "quantity": {"value": 0.333, "unit": "unit"}}, {"id": "ing_beef", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 2.0, "unit": "jar of 50g"}}]', '[{"ingredients":["2 300g/10oz New York Strip / Porterhouse steaks (or other of choice, Note 1)","Salt and pepper","1 tbsp vegetable oil"]},{"ingredients":["1/3 cup (85 ml) brandy or cognac (or marsala) (Note 2)","3/4 cup (185 ml) beef broth/stock (, low sodium (important! Note 3))","1/2 cup (125 ml) cream (, heavy/thickened)","2 - 3 tsp coarsely crushed whole black peppercorns (or canned green peppercorns, drained) (Note 4)"],"purpose":"Sauce:"}]', '[{"description":"Take the steaks out of the fridge 20 minutes before planning to cook.","images":[],"step":1},{"description":"Crush the pepper using a rolling pin, mortar and pestle or the side of a hardy knife.","images":[],"step":2},{"description":"Just before cooking, sprinkle both sides of steak generously with salt and black pepper.","images":[],"step":3},{"description":"Heat oil in a skillet over high heat until smoking.","images":[],"step":4},{"description":"Add steaks and cook the first side for 2 minutes until it has a great crust, then flip and cook the other side for 2 minutes (for medium rare).","duration":2,"images":[],"step":5},{"description":"Stack the steaks on top of each other, then use tongs to sear the fat strip.","images":[],"step":6},{"description":"Transfer to plate, cover loosely with foil to rest while you make the sauce.","images":[],"step":7},{"description":"Add brandy or cognac into the same skillet and let it simmer rapidly, scraping the bottom of the pan, until it has mostly reduced and you can no longer smell the harsh alcohol smell (~1 min).","images":[],"step":8},{"description":"Add broth, bring to simmer and let it simmer rapidly for 2 to 3 minutes or until it reduces by half.","duration":2.5,"images":[],"step":9},{"description":"Turn heat down to medium. Add cream and pepper, stir, then simmer for 1 1/2 to 2 minutes until it thickens (do not let it boil rapidly).","images":[],"step":10},{"description":"Taste sauce, adjust salt (and pepper!) to taste.","images":[],"step":11},{"description":"Transfer steaks to warmed serving plates. Spoon over sauce. Serve immediately! Pictured with Crispy Smashed Potatoes and Garlic Spinach. (Note 6)","images":[],"step":12}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["main_course"],"cuisine":[],"categories":["beef-recipes","dinner-tonight","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_62bacf141147', 'en', 'US', 'Slow Cooked Shredded Beef Ragu Pasta', 'Recipe video above. Ragu is one of those recipes that really showcases the beauty of Italian cooking - everyday ingredients, fast prep, leave it to cook long and slow and you end up with a luscious dish that tastes like a million bucks. This recipe makes enough sauce to serve 8 and freezes great.', 'https://www.recipetineats.com/tachyon/2017/07/Beef-Ragu-11a.jpg', 20, 150, 170, 5, '[{"id": "ing_beef", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 150.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 3.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_thyme", "quantity": {"value": 0.075, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_pappardelle", "quantity": {"value": 453.592, "unit": "pack"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1.2kg / 2.5 lb chuck beef (or other slow cooking beef cut, cut into equal 4 pieces (Note 1))","1 tbsp salt","Black pepper","3 tbsp olive oil (, separated)","3 cloves garlic (, minced)","1 onion (, diced)","1 cup carrots (, diced (Note 2))","1 cup celery (, diced (Note 2))","800g / 28oz crushed canned tomatoes","3 tbsp tomato paste","2 beef bouillon cubes (, crumbled (Note 3))","1 cup / 250ml red wine (, full bodied (like merlot, cabernet sauvignon), or sub with beef broth/stock)","1 1/2 cups / 375 ml water (Note 3)","3/4 tsp dried thyme ( or 3 sprigs fresh thyme)","3 dried bay leaves"],"purpose":"Ragu"},{"ingredients":["1 lb /500g dried pappardelle (, or other pasta of choice (Note 4))","Freshly grated parmesan cheese or parmigiano reggiano","Fresh parsley (, finely chopped (optional))"],"purpose":"To Serve (Not all Sauce is used)"}]', '[{"description":"Pat beef dry and sprinkle with salt and pepper","images":[],"step":1},{"title":"Sear Beef","description":"Heat 1 tbsp olive oil over high heat in a heavy based pot. Add beef and sear each piece aggressively on all sides until very browned (3 - 5 minutes in total), then remove onto a plate.","images":[],"step":2},{"description":"Turn stove down to medium low and add remaining 2 tbsp of olive oil.","images":[],"step":3},{"title":"Soffrito","description":"Add garlic and onion and sauté for 2 minutes. Then add the carrots and celery and sauté slowly for 5 minutes.","duration":2,"images":[],"step":4},{"description":"Add remaining Ragu ingredients and return the beef to the pot (including pooled juices). Turn the stove up and bring it to a simmer, then turn it down to low so it''s bubbling very very gently. (Note 7)","images":[],"step":5},{"title":"Slow cook","description":"Cover the pot and let it cook for 2 hours or until beef is tender enough to shred. (Note 5 for slow cooker and pressure cooker).","images":[],"step":6},{"title":"Shred","description":"Remove beef then coarsely shred with 2 forks. Return beef to the pot. Simmer for 30 minutes until sauce is reduced and thickened - beef will soften slightly more during this step.","duration":30,"images":[],"step":7},{"title":"Final season","description":"Do a taste test and adjust the seasoning to your taste with salt and pepper. ALSO, add 1/2 tsp sugar if sauce is a bit sour for your taste (Note 6). Place the lid on and set aside until ready to serve (it''s even better the next day and freezes well for months!).","images":[],"step":8},{"description":"To Serve (Note 4):","images":[],"step":9},{"description":"Bring a very large pot of water with 1 tbsp of salt to the boil.","images":[],"step":10},{"description":"Add pasta and cook for 1 minute less than the recommended cooking time as per the packet instructions.","duration":1,"images":[],"step":11},{"description":"Meanwhile, place 5 cups of the Ragu in a very large fry pan, dutch oven or use 2 normal size fry pans. Heat over high heat while the pasta is cooking.","images":[],"step":12},{"description":"When the pasta is ready, transfer it directly from the pot into the fry pan using tongs.","images":[],"step":13},{"description":"Add 3/4 cup of pasta water into the fry pan.","images":[],"step":14},{"description":"Gently toss the pasta (I use 2 wooden spoons) for 1 to 2 minutes, until the sauce water evaporates and leaves you with a thick Ragu sauce that coats the pasta.","duration":1.5,"images":[],"step":15},{"description":"Yell for your family to sit down at the dinner table because you need to serve it immediately!","images":[],"step":16},{"description":"Serve with plenty of freshly grated parmesan, or even better, with parmigiano reggiano.","images":[],"step":17}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["beef-recipes","iconic-dishes","italian-recipes","main-dishes","most-popular","pasta-recipes","slow-cooked-fall-apart","slow-cooker-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_46e230f6c472', 'en', 'US', 'Epic Chunky Beef and Mushroom Pie', 'Tender, fall apart chunks of beef with mushrooms in the most incredible gravy ever. The secret ingredient - Dried Porcini Mushrooms! They add a savoury earthiness that can''t be replicated and takes this pie to the next level.', 'https://www.recipetineats.com/tachyon/2017/06/Beef-Mushroom-Pie-6.jpg', 15, 150, 165, 6, '[{"id": "ing_mushroom", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_beef", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 3.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 3.0, "unit": "pack of 1kg"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_dark_ale", "quantity": {"value": 300.0, "unit": "unit"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.3, "unit": "L"}}, {"id": "ing_thyme", "quantity": {"value": 0.12, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_bacon", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_sheet_puff_pastry", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}]', '[{"ingredients":["20 g / 0.7 oz dried porcini mushrooms (slices, whole or chopped) (Note 1)","1 ¼ cups / 312 ml boiled water","1 kg / 2 lb chuck beef (, cut into 2.5cm/1” cubes (Note 2))","1 - 2 tbsp vegetable oil","2 garlic cloves (, minced)","1 onion (, finely chopped)","1 celery (, finely chopped)","1 carrot (, finely chopped)","3 carrots (, halved lengthwise then cut into 1.5cm/ 3/5” chunks)","1/3 cup flour (any)","300 ml / 10 oz dark ale (or substitute with red wine, Guinness or more beef stock)","2 cups / 500 ml beef stock","3 sprigs thyme or 1 tsp dried thyme leaves","2 bay leaves (, fresh or dried)","200 g / 7 oz bacon (, diced)","300 - 400g / 10 – 13 oz Swiss brown mushrooms (, larger ones halved)","1 – 2 sheets puff pastry (enough to cover pie)","1 egg yolk"]}]', '[{"description":"Place porcini in a bowl and add hot water. Leave to soak for at least 30 minutes. Strain mushrooms and reserve soaking liquid. Roughly chop porcini.","images":[],"step":1},{"description":"Sprinkle beef with salt and pepper.","images":[],"step":2},{"description":"Heat 1 tbsp oil in a large heavy based pot. Add half the beef and brown all over, then remove and repeat with remaining beef. Set beef aside.","images":[],"step":3},{"description":"Turn stove down to medium low. If the pot is looking dry, add more oil. Add onion and garlic, cook for 2 minutes. Add finely chopped carrots and celery, cook for 6 minutes or until softened and sweet (taste test!). Add carrot chunks and cook for 2 minutes.","duration":2,"images":[],"step":4},{"description":"Add flour and stir through.","images":[],"step":5},{"description":"Add ale, beef stock, and stir to dissolve the flour.","images":[],"step":6},{"description":"Add thyme, bay leaves, porcini, reserved porcini soaking liquid (don’t tip in gritty bits settled at bottom) and cooked beef. Turn heat up slightly, mix, bring to simmer, then cover. Adjust heat so it is simmering gently, not energetically.","images":[],"step":7},{"description":"Cook for 1 hr 45 minutes or until beef is tender. (See video)","duration":60,"images":[],"step":8},{"description":"Meanwhile, cook bacon in a skillet over high heat until golden. Remove and reserve bacon drippings in pan. Add mushrooms and cook for 5 minutes until golden all over. Return bacon into skillet, toss to coat mushrooms, then stir through stew.","duration":5,"images":[],"step":9},{"description":"Simmer stew, uncovered, for 15 minutes until mushrooms are tender. Then remove from stove and cool.","duration":15,"images":[],"step":10},{"description":"To cook:","images":[],"step":11},{"description":"Preheat oven to 200C/390F.","images":[],"step":12},{"description":"Pour stew into a pie dish, even out surface. Pictured pie dish is 24 x 20 x 4.5 cm / 10 x 8 x 1.8\" (1.5L / 1.5 Qt) - see Notes for more conversions.","images":[],"step":13},{"description":"Top with puff pastry (if too big, just fold the ends in), brush with egg yolk. Cut a few slits in the surface then bake for 30 – 35 minutes until deep golden and the filling is piping hot in the middle (stick a knife in to check).","duration":32.5,"images":[],"step":14},{"description":"Rest for 5 minutes before serving!","duration":5,"images":[],"step":15}]', '["egg","gluten"]', '[]', '{"mealType":["dinner"],"cuisine":[],"categories":["beef-recipes","iconic-dishes","main-dishes","mushroom-recipes","slow-cooked-fall-apart","slow-cooker-recipes","stews","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_eea747ed0c94', 'en', 'US', 'Shredded Beef Burritos', 'Crispy burritos filled with juicy Mexican Shredded Beef with a rich sauce, Mexican red rice and cheese. These are MADE for freezing - perfect standby meal! This recipe is for 8 burritos. However, 1 batch of Mexican Shredded Beef makes enough for around 15 burritos. If you aren''t freezing the burritos, feel free to add other things inside such as avocado, fresh salsa, pico de gallo, lettuce and tomato! (These are not suitable for freezing which is why I don''t use them)', 'https://www.recipetineats.com/tachyon/2015/09/Beef-Burritos_600px_1-Featured.jpg', 15, 10, 25, 8, '[{"id": "ing_tortillas", "quantity": {"value": 1000.0, "unit": "pack of 8"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_beef", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_rice", "quantity": {"value": 300.0, "unit": "pack"}}, {"id": "ing_corn", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_black_beans", "quantity": {"value": 1.0, "unit": "can of 400g"}}]', '[{"ingredients":["8 large extra soft flour tortillas (10\"/26cm)","1 1/2 to 2 cups shredded cheese (I used Monterey Jack)","3 to 4 cups Mexican Shredded Beef plus sauce (, tossed or separated (Note 1))","2 cups Mexican Red Rice","400g/14oz can corn kernels (, drained)","400g/14oz can black beans (, drained)"]}]', '[{"description":"Microwave half the tortillas very briefly to warm them up (15 seconds or so). This ensures they don''t crack when you roll them.","images":[],"step":1},{"title":"Place 1 tortilla on a workbench","description":"cover the rest with a tea towel to keep them warm.","images":[],"step":2},{"description":"Place cheese down the middle of the tortilla, then top with 1/3 cup of beef, some corn, beans, then 1/4 cup rice.","images":[],"step":3},{"description":"Roll the burrito up. (Note 2) Wrap in foil to hold it together.","images":[],"step":4},{"description":"If you are serving it immediately, heat a skillet over medium heat. Cook the burritos for around 4 to 5 minutes on each side to make the tortilla brown and heat the inside through.","images":[],"step":5},{"description":"If freezing, place in the freezer. To reheat, you can either bake from frozen (with foil on) at 350F/180C for about 40 to 45 minutes, or thaw and cook in the skillet per above. You could microwave it (remove the foil) but I like my burritos a bit crispy!","images":[],"step":6}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["beef-recipes","burritos","dietary","gluten-free-recipes","mexican-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_758c5783200d', 'en', 'US', 'Fiery Fall Apart Mexican Beef Ribs', 'Fall apart beef short short ribs, smothered in a rich fiery sauce with an incredible depth of flavour. Though it takes time to cook, the prep is pretty fast. I accompanied this with Mexican Green Rice with Corn - recipe is below. The flavour of that rice is so incredible, you can eat it plain!', 'https://www.recipetineats.com/tachyon/2015/02/Mexican-Beef-Short-Ribs-Chipotle-Adobo-Sauce-3.jpg', 15, 150, 165, 8, '[{"id": "ing_chipotles_in_adobo_chipotles_and_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_tomato", "quantity": {"value": 28.0, "unit": "kg"}}, {"id": "ing_beef_steak", "quantity": {"value": 2.4, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.008, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_cumin", "quantity": {"value": 0.037, "unit": "jar of 40g"}}, {"id": "ing_bay_leaf", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 4.0, "unit": "bunch"}}, {"id": "ing_oranges", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}]', '[]', '[{"description":"Preheat oven to 180C with the shelf in the middle.","images":[],"step":1},{"description":"Puree the Chipotles in Adobo with the canned tomato (\"Chipotle Puree\"). (Note 3)","images":[],"step":2},{"description":"Pat the beef dry with a paper towel, then season with 1/2 tbsp salt and pepper.","images":[],"step":3},{"description":"Heat oil in a heavy based large fry pan over high heat. Add the beef in batches and sear on all sides until nicely browned, but not cooked through (about 4 minutes in total). Remove into a roasting dish (preferably one with a lid)","images":[],"step":4},{"description":"If the pan is looking dry, add a splash of oil. Add the garlic and sauté for 15 seconds, then add the onion and cook for 3 minutes until the onion is starting to brown.","duration":0.25,"images":[],"step":5},{"description":"Add the Chipotle Puree and all the remaining ingredients into the pan (including the remaining 1/2 tbsp salt). Bring to simmer and scrape the bottom of the pan to mix all the brown bits into the liquid. Cook for 1 minute.","duration":1,"images":[],"step":6},{"description":"Pour the liquid into the roasting dish over the ribs.","images":[],"step":7},{"title":"Cover with lid (or with foil","description":"use a double layer) and bake in the oven for 1 1/2 hours.","images":[],"step":8},{"description":"Remove lid/foil, then return to oven for a further 45 minutes to 1 hour until the beef is \"fall apart\" and the sauce has thickened and darkened.","images":[],"step":9},{"description":"Let rest for 5 minutes. Garnish with fresh coriander leaves, then serve with lime wedges on the side.","duration":5,"images":[],"step":10},{"description":"I served this with Mexican Green Rice with Corn (recipe below). This would also be great for tacos, burritos, on mashed potato.","images":[],"step":11}]', '[]', '["gluten_free","high_protein"]', '{"mealType":["main_course"],"cuisine":["Mexican-esque"],"categories":["beef-recipes","dietary","gluten-free-recipes","mexican-recipes","rice-recipes","rice-side-dishes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d7cca9032908', 'en', 'US', 'Aloo Paratha (Indian Potato Stuffed Flatbread)', 'Aloo Paratha is a very popular breakfast dish in India. The beauty of this recipe is how flexible it is - there are so many options and variations you can do and I''ve provided a bunch of suggestions in the notes. The dough is extremely simple to make and handle. The only "must do" in this recipe is letting the dough rest for 20 minutes.', 'https://www.recipetineats.com/tachyon/2014/11/Aloo-Paratha-3.jpg', 15, 12, 27, 4, '[{"id": "ing_flour", "quantity": {"value": 0.375, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_potato", "quantity": {"value": 1.5, "unit": "bag of 2kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.5, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_ginger", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_garam_masala", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.013, "unit": "pack of 100g"}}]', '[{"ingredients":["2 1/2 cups plain white flour (Note 1)","1 tsp salt","1 cup water (Note 2)","2 tbsp vegetable oil ((or any other cooking oil), ghee or butter)"],"purpose":"Dough"},{"ingredients":["1 1/2 cups mashed potato (Notes 3 and 4)","1/2 cup shallots/scallions (, chopped)","2 tbsp fresh coriander/cilantro (, roughly chopped (optional - adds a nice burst of freshness))","1/2 tsp fresh ginger (, grated (optional - Note 5))","1 tsp Garam Masala (Note 6)","1 tsp Ajwain/ Carom seeds OR 1 tsp thyme (Note 7)","1/4 tsp chili powder (Note 8)","1/2 tsp salt"],"purpose":"Filling"}]', '[{"description":"Place the flour, water and salt in a bowl. Use a table knife to mix the ingredients together, then use your hands.","images":[],"step":1},{"description":"Once the dough is sort of formed, turn it out onto a work surface and knead it 60 times. It should be smooth and elastic, not sticky or crumbly.","images":[],"step":2},{"description":"Form the dough into a ball, cover with cling wrap and set aside for at least 20 minutes (up to a few hours). Do not refrigerate.","images":[],"step":3},{"description":"Meanwhile, make the Filling. Place all Filling ingredients into a bowl and mix to combine.","images":[],"step":4},{"description":"Preheat oven to very low (to keep Parathas warm because you can only cook one at a time).","images":[],"step":5},{"description":"Cut the dough into 4 pieces with a knife.","images":[],"step":6},{"description":"Take one ball and use a rolling pin to roll it out into a round about 18cm/7\" in diameter.","images":[],"step":7},{"description":"Place 1/3 cup of the Filling into the middle of the rolled out dough.","images":[],"step":8},{"description":"Gather the edges of the dough to enclose the Filling (see photo below). Remove as much air as possible from inside then pinch to seal.","images":[],"step":9},{"description":"Flatten the ball slightly and shape the flattened disc into a circle using your hands.","images":[],"step":10},{"description":"Turn the dough over so the \"sealed\" side is facing down. Use a rolling pin to roll it out to about 1 1/2 cm / 2/3\" thickness. Repeat with remaining dough.","images":[],"step":11},{"description":"Heat 1 tbsp of oil in a non stick fry pan over medium heat.","images":[],"step":12},{"description":"Place one Paratha into the fry pan and cook the first side for 1 minute 45 seconds. Use an egg flip to check if it is ready to turn - the underside should be golden brown.","duration":1,"images":[],"step":13},{"description":"Turn the Paratha over and cook the other side for 1 minute 30 seconds.","duration":1,"images":[],"step":14},{"description":"Remove from fry pan onto a wire rack (this stops the underside from going soggy due to sweat) and place into a low oven to keep warm while you cook the remaining Parathas.","images":[],"step":15},{"description":"Add a small drizzle of the remaining oil into the pan (you should not need much). Proceed to cook the remaining Parathas.","images":[],"step":16},{"description":"Cut into 4 pieces and serve immediately. It can be served with chutney or yoghurt on the side. I find that the Filling has so much flavour that it doesn''t need anything on the side.","images":[],"step":17}]', '["gluten","milk"]', '["vegetarian"]', '{"mealType":["snack","breakfast"],"cuisine":["Indian"],"categories":["beef-recipes","indian-recipes","side-dishes","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_289df661a761', 'en', 'US', 'Chili Con Carne Corn Bread Pie', 'These pies are filled with Chili Con Carne and topped with corn bread! The corn bread batter only takes a few minutes to make. You can make on large pie or individual pies. You can also add vegetables into the filling - corn and peas would go especially well.', 'https://www.recipetineats.com/tachyon/2014/10/Chili-Con-Carne-Corn-Bread-Pie4.jpg', 5, 20, 25, 4, '[{"id": "ing_chilli", "quantity": {"value": 6.0, "unit": "pack of 100g"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_butter", "quantity": {"value": 0.5, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_corn", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_flour", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}]', '[{"ingredients":["4 cups Shredded Beef Chili Con Carne","1 tbsp fresh parsley (, finely chopped (optional))"]},{"ingredients":["1/2 cup melted butter","3 eggs","1 cup milk","1/2 cup polenta / cornmeal (Note 3)","1 1/2 cups self raising flour (or 3 tsp baking powder plus 1 1/4 cups + 3 tbsp of plain flour)","1/2 cup sugar","1/4 tsp salt","1 cup of canned creamed corn"],"purpose":"Corn Bread Topping"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Place 1 cup of Shredded Beef Chili Con Carne into 4 individual pie dishes, or 1 large pie dish.","images":[],"step":2},{"description":"Combine Corn Bread Topping dry ingredients in a bowl and given them a quick stir to combine.","images":[],"step":3},{"description":"Add Corn Bread Topping wet ingredients and mix to combine until lump free.","images":[],"step":4},{"description":"Pour corn bread mixture over filling so it is about 1.5 cm / 1/2\" thick.","images":[],"step":5},{"description":"Place pie in the oven and bake for 20 to 30 minutes until golden brown on top. If making one large one, it will take closer to 35 minutes. To test for doneness, insert a skewer in the middle of the corn bread and make sure it comes out clean. If there is batter on the skewer, return to oven.","duration":25,"images":[],"step":6},{"description":"Allow to rest for 5 minutes before serving, garnished with fresh parsley.","duration":5,"images":[],"step":7}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["main_course"],"cuisine":[],"categories":["beef-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6d9ac559dfb1', 'en', 'US', 'Beef and Mushroom Pie (3 in 1)', 'This is comfort food at its best because it''s so fast to prepare. Made using leftover Slow Cooked Beef Cheeks in Red Wine, this pie takes just 15 minutes to prepare to pop into the oven to bake until puffed and golden.', 'https://www.recipetineats.com/tachyon/2014/08/Beef-Cheek-Pie-2.jpg', 15, 25, 40, 4, '[{"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_beef_cheeks", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_beef_cheeks", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_tomato", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1 sheet ready rolled puff pastry ((25cm x 25cm / 10\" x 10\"), thawed)","1 egg (, lightly beaten)"]},{"ingredients":["2 cups shredded beef cheeks from Slow Cooked Beef Cheeks in Red Wine leftovers","1 1/2 cups leftover sauce from Slow Cooked Beef Cheeks in Red Wine","2 tbsp olive oil","1 onion ((brown, white or yellow), diced)","2 garlic cloves (, minced)","2 carrots (, diced roughly to the size of peas (about 1 1/2 cups))","1 cup frozen green peas","1 cup canned crushed tomato","1 1/2 cups sliced button mushrooms","3 tbsp tomato paste","1 cup water","1 tsp thyme (dried)","1 tsp oregano (dried)","1 tsp salt (, plus more to taste)","Black pepper"],"purpose":"Pie Filling"}]', '[{"description":"Preheat the oven to 180C/350F.","images":[],"step":1},{"description":"You will need 4 x 1 2/3 cup capacity ramekins.","images":[],"step":2},{"description":"Place 1 ramekin on the puff pastry and use it as a guide to cut rounds out of the puff pastry. Cut 4 rounds.","images":[],"step":3},{"description":"Heat oil in large heavy based pan over medium high heat.","images":[],"step":4},{"description":"Add onion and garlic, and sauté for 2 minutes.","duration":2,"images":[],"step":5},{"description":"Add carrots and sauté for 1 minute. Then add mushrooms and sauté for another minute.","duration":1,"images":[],"step":6},{"description":"Add remaining Pie Filling ingredients. Let simmer for 3 minutes to bring the flavours together.","duration":3,"images":[],"step":7},{"description":"Divide the Pie Filling between the 4 ramekins. Top with puff pastry rounds and cut a small slash in each (steam vents).","images":[],"step":8},{"description":"Brush with egg, then place into the oven to bake for 20 to 25 minutes until the pastry is dark golden and puffed.","duration":22.5,"images":[],"step":9},{"description":"Remove from oven, let stand for 5 minutes before serving.","duration":5,"images":[],"step":10}]', '["egg"]', '["gluten_free","high_protein"]', '{"mealType":["main_course"],"cuisine":[],"categories":["beef-recipes","most-popular","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0fda9b63e56d', 'en', 'US', 'Pavlova Bombs', 'Recipe video above. Pavlova Bombs are mini pavlovas balls that are filled with lemon curd, raspberry coulis and whipped cream. They look so innocent when placed before you - then they explode with colourful fillings when you smash into them! Show aside, the flavour and texture combination here is just incredible.Shockingly easy to make - just poke a hole in the base of small pavs, and fill with whatever you want. Think, passionfruit pulp, mango puree, chopped fruit, chocolate sauce, caramel sauce! See in post for more suggestions.', 'https://www.recipetineats.com/tachyon/2025/12/Pavlova-bombs_6.jpg', 25, 90, 115, 5, '[{"id": "ing_egg", "quantity": {"value": 6.667, "unit": "carton of 12"}}, {"id": "ing_sugar", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.016, "unit": "pack of 400g"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.003, "unit": "L"}}, {"id": "ing_raspberries", "quantity": {"value": 20.0, "unit": "punnet of 125g"}}, {"id": "ing_lemon", "quantity": {"value": 6.0, "unit": "net of 500g"}}, {"id": "ing_uncategorized", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.05, "unit": "bottle of 50ml"}}, {"id": "ing_option_to_stabilise", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_pistachios", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_mint", "quantity": {"value": 5.0, "unit": "bunch"}}, {"id": "ing_raspberries", "quantity": {"value": 20.0, "unit": "punnet of 125g"}}, {"id": "ing_sugar", "quantity": {"value": 0.1, "unit": "kg"}}]', '[{"ingredients":["80 ml / 1/3 cup egg whites (, from 3 large eggs (Note 1))","2/3 cups caster sugar ((superfine sugar), do not cut down, it will affect result!)","1 1/4 tsp cornflour / cornstarch (Note 2)","1/2 tsp white vinegar (Note 2)"],"purpose":"Pavlova Balls:"},{"ingredients":["Raspberry Coulis","Lemon Curd (uses the 3 leftover yolks from the Pav)","(See in post for other options (- passionfruit pulp, pureed mango, chopped up fruit, chocolate sauce!))"],"purpose":"Fillings"},{"ingredients":["1 cup heavy/thickened cream ((or any other whipping cream), COLD)","1 1/2 tbsp caster sugar / superfine sugar","1/2 tsp vanilla extract","Option to stabilise (so you can whip cream day before - see here for how (Note 3))"],"purpose":"Whipped cream:"},{"ingredients":["1 1/2 tbsp unsalted pistachios (, finely chopped)","5 mint sprigs (, small)","20 raspberries","Icing sugar / powdered sugar (, for dusting)"],"purpose":"Garnishes"}]', '[{"description":"Pipe then shape meringues into 5 domes. Bake 1 1/2 hours at 110°C/225°F (100°C fan), cool 3 hours / overnight in oven. Cut small hole in Pav bomb base, squidge around with chopstick to make room for fillings. Fill with coulis then curd, plug hole with cream. Decorate, SMASH!","images":[],"step":1},{"description":"Preheat oven to 150°C / 325°F (all oven types).","images":[],"step":2},{"title":"Egg whites","description":"Separate the egg yolks from egg whites while fridge cold (it''s easier). Measure out 1/3 cup (80 ml) egg whites then set aside to come to room temperature for 15 minutes (fluffs better at room temp).","duration":15,"images":[],"step":3},{"title":"Add sugar","description":"In a stand mixer or using an electric beater, beat the egg whites on high for 1 minute. While still beating, slowly pour the sugar in over 1 minute.","duration":1,"images":[],"step":4},{"title":"Beat 5 minutes","description":"Continue to beat for 5 minutes on high until it''s fluffy, glossy, and there are no sugar grains remaining when you rub a bit between your fingers. Add vinegar and cornflour then beat for a further 30 seconds.","duration":5,"images":[],"step":5},{"title":"Line tray","description":"Dab a bit on the corner of 2 trays then cover with baking paper (parchment).","images":[],"step":6},{"description":"Pipe mounds Transfer meringue mixture into a large piping bag. Snip the end to make a large 2cm / 0.8\" hold. Pipe 5 mounds on the tray, then smooth into domes that are taller than they are wide (they flatten slightly when baked). Mine are about 4 cm / 1.6\" wide and 6.5cm /2.6\" tall. Use a small offset spatula or butter knife to smooth into a dome shape (no need to be perfect, it gets decorated later).","images":[],"step":7},{"title":"Bake 1 hour 30 minutes","description":"Place both trays in the oven, immediately turn oven DOWN to 110°C/225°F (100°C fan) and bake for 1 hour 30 minutes or until they are dry to touch (check base). Keep baking if still sticky - exact times may vary. (Note 4)","images":[],"step":8},{"title":"Cool in oven","description":"Turn oven OFF and leave to fully cool for 3 hours or overnight around 10 hours (I often do this while I sleep so handy!).","images":[],"step":9},{"description":"Make the Lemon Curd and Raspberry Coulis while the pavlovas are in the oven. Very easy - simmer to thicken, strain, then chill before using.","images":[],"step":10},{"title":"Whipped cream","description":"Beat cream ingredients in a large bowl on high until soft peaks form (45 seconds using a stand mixer, 1 - 1 1/2 minutes with hand held beater). Do this just prior to serving, unless you stabilise the cream (which can be done the day before). Note: if making stabilised whipped cream, follow the steps for your chosen method (there''s multiple ways to do it).","images":[],"step":11},{"description":"Assemble Pavlova Bombs:","images":[],"step":12},{"title":"Piping bags","description":"Transfer the raspberry coulis, lemon curd and cream into separate piping bags. Snip a small 5 mm / 1/5\" off the end of the raspberry coulis, and a larger 1cm / 0.4\" off the cream piping bag. (No piping bag? See Note 5)","images":[],"step":13},{"description":"Access hole! Place a pavlova bomb upside down in a muffin tin, to hold in place as you work. Carefully cut a 1cm / 0.4\" hole in the middle using a small sharp knife. Stick a chopstick into the hole and squidge around GENTLY to move some pavlova marshmallow centre out of the way to make room for the fillings.","images":[],"step":14},{"description":"Pipe some raspberry coulis in (~ 1 1/2 tsp), then lemon curd (~ 2 - 3 tsp). Plug the hole with cream.","images":[],"step":15},{"title":"Plate up","description":"Pipe ~2 tbsp cream on a plate, top with pavlova bomb (stops it from sliding). Pipe then spread more cream on the top of the pavlova bomb. Top with a raspberry, mint sprig, sprinkle of pistachio, dust with icing sugar.","images":[],"step":16},{"title":"Smash! Serve immediately","description":"pavs don''t wait around once assembled! Encourage everyone to smash into their Pavlova Bombs so you get a bit of everything in your first bite - delicate crispy meringue, marshmallow centre, tangy lemon curd, bright raspberry coulis. SWOON!","images":[],"step":17}]', '["egg","milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Australian","New Zealand"],"categories":["bite-size-desserts","dessert-recipes","iconic-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_38f5220bbafb', 'en', 'US', 'Chocolate Pudding Pots', 'Recipe video above. This is like a richer, more luxurious Chocolate Mousse, with a quarter of the effort. Tastes sophisticated. Easy to pretty up. Brilliant ready-to-go dinner party dessert: make ahead 5 days!I especially love that this is not too sweet, it''s all about the chocolate flavour. Be sure to use 70% chocolate as the pudding relies on this to help it set (higher cocoa % = firmer chocolate). If using dark chocolate / semi-sweet chocolate chips, increase the cornflour/cornstarch - see note 1.Makes 5 pots just shy of 1/2 cup each which is good portion for dessert. TIP: You can whip the cream ahead too, just stabilise it so it doesn''t deflate.', 'https://www.recipetineats.com/tachyon/2025/10/Chocolate-pudding-pots_3.jpg', 10, 5, 15, 5, '[{"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_sugar", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_cocoa_powder", "quantity": {"value": 0.12, "unit": "pack of 250g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.056, "unit": "pack of 400g"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.5, "unit": "carton of 250ml"}}, {"id": "ing_chocolate", "quantity": {"value": 150.0, "unit": "block of 100g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 1.5, "unit": "carton of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_chocolate", "quantity": {"value": 150.0, "unit": "block of 100g"}}]', '[{"ingredients":["2 large egg yolks (ie yolks of eggs ~50-55g/2oz each, from cartons labelled \"large eggs\")","1/3 cup caster sugar / superfine sugar (or regular white sugar)","1 tsp vanilla extract","2 tbsp cocoa powder (, sifted (unsweetened))","1 1/2 tbsp cornflour / cornstarch","1 cup milk (, full fat is best)","1 1/2 cups thickened cream / heavy cream (, or any other regular full-fat pourable cream)","150 g/5oz 70% cocoa chocolate (bittersweet chocolate), finely chopped - see note for dark chocolate / semi-sweet chocolate (Note 1)","Pinch of salt"]},{"ingredients":["3/4 cup thickened cream / heavy cream or any other cream for whipping (, fridge cold)","1/2 tsp vanilla extract","2 tsp white sugar"],"purpose":"Whipped cream:"},{"ingredients":["2 tbsp 70% cocoa chocolate ((bittersweet chocolate), finely chopped (Note 1) )"],"purpose":"Garnish:"}]', '[{"description":"Whisk yolks and sugar in a saucepan, then vanilla, cocoa, cornflour and splash of milk. Whisk in remaining milk, cream and salt. Heat on medium (whisk), once bubbles appear keep stirring 15 seconds, then take off stove. Stir in chocolate, pour in glasses, chill. Decorate then serve!","images":[],"step":1},{"title":"Whisk mixture","description":"Put the yolks and sugar in a medium saucepan. Whisk until combined. Add the vanilla, cocoa, cornflour and a small splash of milk. Whisk until lump free. Add the remaining milk, cream and salt then whisk to combine.","images":[],"step":2},{"title":"Heat gently","description":"Put the saucepan over medium heat on the stove. Whisk every now and then initially, and more frequently as the mixture heats up as it will thicken on the base. Be sure to get right into the edges.","images":[],"step":3},{"title":"Melt chocolate","description":"Once gentle bubbles break the surface (about 5 minutes), stir for another 15 seconds then remove off the stove. Add the chocolate and stir until melted. (Note 2) ⚠️ Do not boil cornflour mixture longer as it may kill the setting qualities of the cornflour.","images":[],"step":4},{"title":"Pour quickly and cool","description":"Immediately pour the mixture into 5 small glasses, ramekins etc - if you are too slow, the mixture will thicken and leave ripples on the surface (it''s just a visual thing, we can hide with cream!). Cool on the counter for 15 minutes then refrigerate uncovered for 3 hours until set. (Keep 5 days!) See FAQ for what to do if your pudding is too loose, and what may have caused it.","duration":15,"images":[],"step":5},{"description":"To serve:","images":[],"step":6},{"title":"Whip cream","description":"With an electric beater, whip the cream ingredients for 1 - 1 1/2 minutes on high until softly whipped. (Stabilise the cream if making ahead)","images":[],"step":7},{"title":"Decorate","description":"Spoon a dollop on the pudding, sprinkle with chocolate and serve!","images":[],"step":8}]', '["egg","milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["bite-size-desserts","dessert-recipes","no-bake-sweet-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4541d572078f', 'en', 'US', 'Rocky Road', 'Recipe video above. I love a good Rocky Road. I love the heftiness and endless versatility of add-ins. Though, unsurprisingly, I have views on what makes a good one! Ratios matter. Too much chocolate and not enough add-ins is not good! So here''s my Rocky Road recipe. Super easy. :)Use chips or melts for an easy option. Upgrade to Lindt for premium. Excellent food gift. Think - Christmas, birthdays, thank you, get well present.', 'https://www.recipetineats.com/tachyon/2023/08/Rocky-Road-stacked.jpg', 15, 0, 195, 12, '[{"id": "ing_chocolate", "quantity": {"value": 225.0, "unit": "block of 100g"}}, {"id": "ing_chocolate", "quantity": {"value": 225.0, "unit": "block of 100g"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_marshmallows_pink_and_white", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_raspberries", "quantity": {"value": 0.9, "unit": "punnet of 125g"}}, {"id": "ing_desiccated_coconut_unsweetened", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_peanuts", "quantity": {"value": 0.188, "unit": "jar"}}]', '[{"ingredients":["225 - 250g / 8 oz dark chocolate melts or chips (1 1/2 cups) (or block, chopped (US: semi-sweet chips))","225 - 250g / 8 oz milk chocolate melts or chips (1 1/2 cups) (or block, chopped (or more dark choc))","2 tbsp coconut oil or any plain flavoured oil (prevents cracking, adds bit of sheen, Note 2)"],"purpose":"Chocolate (read Note 1!):"},{"ingredients":["3 cups marshmallows, pink and white (, most cut in half (firmly pack the cups!))","3/4 cup raspberry lollies (, halved)","1/3 cup desiccated coconut ((or flakes), unsweetened)","1/2 cup unsalted peanuts (, very roughly chopped (ie almost just halved))"],"purpose":"Nagi’s Rocky Road Add-ins (Note 3):"}]', '[{"description":"Line a 20cm/8\" square pan with baking paper (parchment paper).","images":[],"step":1},{"title":"Melt chocolate","description":"Place chocolate and oil in a bowl. Microwave in 30 second increments, stirring in between, until melted and smooth.","images":[],"step":2},{"title":"Add-ins","description":"Stir the Add-ins into the chocolate. Pour into pan, spreading out evenly.","images":[],"step":3},{"description":"Refrigerate for 3 hours or until fully cool.","images":[],"step":4},{"title":"Cut","description":"Remove from the fridge 30 minutes prior to cutting. I cut into 5 lines, then into chunks for eating or larger pieces for gifting!","images":[],"step":5}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Australian","Western"],"categories":["bite-size-desserts","candy","dessert-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ad4677bb54b0', 'en', 'US', 'Golden Gaytime Popcorn - copycat recipe!', 'Recipe video above. I love Golden Gaytime Popcorn. But it''s expensive. So I decided to create a homemade version - with a 68% saving! It costs $8.96 to make this recipe which equates to 5 packets of Gaytime Popcorn which costs $28.75 ($5.75 per packet). After inspecting the packet ingredients, it''s just caramel popcorn drizzled with chocolate and sprinkled with biscuits crumbs. Easy!One batch makes 780g / 28oz, 12 cups = 5 packets of store-bought Golden Gaytime popcorn.', 'https://www.recipetineats.com/tachyon/2023/07/Gaytime-popcorn_5.jpg', 15, 55, 65, 12, '[{"id": "ing_vegetable_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_corn", "quantity": {"value": 0.188, "unit": "can of 400g"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 0.188, "unit": "can of 400g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_toffee_or_caramel_essence_or_1_tsp_vanilla", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.013, "unit": "tub of 200g"}}, {"id": "ing_chocolate", "quantity": {"value": 1.25, "unit": "block of 100g"}}, {"id": "ing_plain_sweet_biscuits", "quantity": {"value": 4.0, "unit": "pack"}}]', '[{"ingredients":["1/4 cup vegetable oil (not required if air popping with a popcorn maker)","1/2 cup popping corn"],"purpose":"For the popcorn"},{"ingredients":["100g / 7 tbsp unsalted butter","1 cup brown sugar (, tightly packed cup)","1/2 cup light corn syrup ( (sub glucose, Note 1))","1/2 tsp cooking/ kosher salt","2 tsp toffee or caramel essence OR 1 tsp vanilla (substitute) (Note 2)","1/2 tsp baking soda (bi-carb) (Note 3)"],"purpose":"For the caramel"},{"ingredients":["1 1/4 cups dark or white chocolate melts or chips (US: semi-sweet chips), I used ~25% white and 75% dark (Note 4)","4 plain sweet biscuits (like Marie Crackers) (Note 5)"],"purpose":"Golden Gaytime Finishes"}]', '[{"title":"Test oil","description":"Heat oil in a large pot over medium heat. Add a few pieces of popcorn and wait until it pops, then quickly remove.","images":[],"step":1},{"title":"Pop","description":"Add remaining popcorn, elevate off stove to shake and spread corn out evenly. Cover with a lid. Once the popcorn starts popping in earnest, shake the pot gently once. Then crack the lid a tiny bit - let''s steam escape for crisper popcorn.","images":[],"step":2},{"description":"Remove from heat when the popping stops (when you can count to 3 between pops) and transfer to a (very!) large bowl.","images":[],"step":3},{"description":"Preheat oven to 110°C/230°F (both fan and standard ovens).","images":[],"step":4},{"title":"Combine","description":"Melt butter in a saucepan over medium heat. Add sugar, corn syrup and salt. Stir until just combined.","images":[],"step":5},{"title":"Simmer","description":"When it starts to bubble, simmer for 4 minutes - DO NOT STIR!","duration":4,"images":[],"step":6},{"title":"Baking soda \"foamy\"","description":"Remove from heat then quickly whisk in caramel (toffee or vanilla) and baking soda. When you stop whisking, the caramel will foam and increase in volume.","images":[],"step":7},{"title":"Coat popcorn","description":"Quickly pour straight over popcorn, toss until caramel cools and starts to harden.","images":[],"step":8},{"description":"Baking to crisp caramel coating:","images":[],"step":9},{"description":"Spread popcorn on 2 large paper lined baking trays.","images":[],"step":10},{"description":"Bake for 45 minutes, tossing every 10 minutes or so. Caramel will remelt for the first 2-3 tosses - tossing coats popcorn more evenly with caramel. (If using glucose, bake further 15 minutes).","duration":45,"images":[],"step":11},{"title":"Cool","description":"Remove from oven, leave to cool on the tray for 20 minutes. Then break up the popcorn - no need to be too pedantic, clumps are great!","duration":20,"images":[],"step":12},{"description":"Drizzle and crumbs","images":[],"step":13},{"title":"Crumbs","description":"Place biscuits in a ziplock bag and bash into crumbs.","images":[],"step":14},{"title":"Melt chocolate","description":"Place chocolate in a heatproof bowl and microwave in 30 second increments on high, stirring in between, until melted and smooth - about 1 1/2 minutes. (If doing a small amount of white chocolate, reduce to 20 second increments).","images":[],"step":15},{"title":"Piping bags","description":"Transfer chocolate into a piping bag. Use scissors to snip a small opening at the tip. (Alternative: just drizzle with a spoon).","images":[],"step":16},{"title":"Drizzle & crumb","description":"Push the popcorn together but in a single layer. Drizzle criss-cross (or any pattern!) all over the popcorn. Sprinkle with biscuits crumbs while the chocolate is wet so it sticks.","images":[],"step":17},{"title":"Fridge","description":"Refrigerate for 15 minutes until the chocolate is firm. Gently break popcorn into pieces. EAT!","duration":15,"images":[],"step":18},{"description":"Store in an airtight container in a cool place. Stays crisp for at least a week. Our test batches never lasted any longer!","images":[],"step":19}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["bite-size-desserts","candy","dessert-recipes","snacks"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3525a7113794', 'en', 'US', 'Affogato', 'Recipe video above. The world''s fastest and smartest dessert, courtesy of the Italians. This is what you make when you claim you''re too full dessert! It''s coffee, dessert and optional after dinner drink, all rolled into one. Genius.Hot coffee and melty gelato or ice cream is a match made in heaven.', 'https://www.recipetineats.com/tachyon/2023/06/Affogato_0.jpg', 5, 0, 5, 1, '[{"id": "ing_cream", "quantity": {"value": 4.0, "unit": "carton of 250ml"}}, {"id": "ing_shot_hot_espresso_coffee_note_2", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_frangelico_amaretto_or_other_liquor_note_3", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["1 large or 2 small(ish) scoops vanilla gelato or ice cream ( (Note 1))","1 shot (30 ml/1 oz) hot espresso coffee ( (short black) - Note 2)","1 tbsp frangelico, amaretto or other liquor ((optional) - Note 3)"]}]', '[{"description":"Put ice cream in glass suitable for affogato eating (Note 4).","images":[],"step":1},{"description":"Place shot of espresso and liquor (if using) on the side.","images":[],"step":2},{"description":"Pour the hot espresso then liquor over the ice cream. Enjoy swirls of melty ice cream blending into the coffee. Dig in immediately!","images":[],"step":3}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Italian"],"categories":["bite-size-desserts","cosy-desserts","dessert-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_04ec3f2bcd82', 'en', 'US', 'Christmas Popcorn Candy', 'Recipe video above. This is Caramel Popcorn, dressed up for Christmas! Perfumed with warm traditional Christmas spices and studded with almonds, it is outrageously addictive. Great as a snacky dessert option, for gifting and store-like candy. Stays crispy 2 - 3 weeks!Baking soda makes the caramel coating foamy so it coats the popcorn thinly and evenly, rather than in sticky globs. CARAMEL COVERAGE: Use 1/3 cup kernels for full caramel coverage (very sweet, like candy pieces, pictured in post), 3/4 cup for a lighter coating (still sweet enough but you get some white patches, see this photo for comparison)', 'https://www.recipetineats.com/tachyon/2020/12/Holiday-Caramel-Popcorn_3.jpg', 10, 55, 65, 8, '[{"id": "ing_vegetable_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_corn", "quantity": {"value": 0.125, "unit": "can of 400g"}}, {"id": "ing_almonds", "quantity": {"value": 0.4, "unit": "pack of 250g"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 0.125, "unit": "can of 400g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.013, "unit": "tub of 200g"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_round_clove", "quantity": {"value": 1.25, "unit": "jar"}}]', '[{"ingredients":["1/4 cup vegetable oil (not required if air popping with a popcorn maker)","1/3 cup popping corn (10 cups popcorn, Note 1 for lighter caramel coverage)","2/3 cup slivered almonds"],"purpose":"For the popcorn"},{"ingredients":["100g / 7 tbsp butter (, unsalted)","1 cup brown sugar (, packed)","1/2 cup (170g) corn syrup (, light (substitute glucose, Note 2))","1/2 tsp salt","1 tsp vanilla extract","1/2 tsp baking soda"],"purpose":"For the caramel"},{"ingredients":["3 tsp cinnamon powder","2 tsp ginger powder","1/2 tsp allspice powder (or more cinnamon)","1/4 tsp ground cloves (or more cinnamon)"],"purpose":"Christmas Spices"}]', '[{"description":"Heat oil in a large pot over medium heat. Add a few pieces of popcorn and wait until it pops, then quickly remove.","images":[],"step":1},{"description":"Add remaining popcorn, elevate off stove to shake and spread corn out evenly. Cover with a lid. Once the popcorn starts popping in earnest, shake the pot gently once.","images":[],"step":2},{"description":"Remove from heat when the popping almost stops (when you can count to 3 between pops) and transfer to a (very!) large bowl. You need 10 cups of popcorn.","images":[],"step":3},{"description":"Preheat oven to 110°C/230°F.","images":[],"step":4},{"description":"Melt butter in a saucepaan over medium heat.","images":[],"step":5},{"description":"Add sugar, corn syrup (or glucose) and salt. Stir until just combined.","images":[],"step":6},{"title":"When it starts to bubble, simmer for 4 minutes","description":"DO NOT STIR!","duration":4,"images":[],"step":7},{"description":"Remove from heat then quickly whisk in Christmas Spices, vanilla and baking soda. Whisk vigorously for 10 seconds, then when you stop whisking, the caramel will foam and increase in volume.","duration":0.16666666666666666,"images":[],"step":8},{"description":"Quickly pour straight over popcorn, toss to coat.","images":[],"step":9},{"description":"Sprinkle over the almonds, and toss again until caramel cools and starts to harden.","images":[],"step":10},{"description":"Baking to crisp:","images":[],"step":11},{"description":"Spread popcorn across 2 baking trays.","images":[],"step":12},{"description":"Bake for 45 minutes, tossing every 10 minutes or so. Caramel will remelt for the first 2-3 tosses - tossing further coats popcorn more evenly with caramel. (If using glucose instead of corn syrup, bake further 15 minutes).","duration":45,"images":[],"step":13},{"description":"Remove from oven, leave to cool. Gently break into pieces then transfer to airtight container for storage. Stays crisp 2 - 3 weeks!","images":[],"step":14}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["bite-size-desserts","candy","dessert-recipes","popcorn"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ed5f7b76575a', 'en', 'US', 'Lightly Sweet ''n Salty CRISPY Butter Popcorn', 'Recipe video above. This is a homemade version of a very popular, slightly sweet and lightly salty Butter Popcorn sold at grocery stores (Cobs brand, for those of you in Australia!). I love it, and replicated it so I could serve giant bowls of it when I have friends around. It''s always a hit!BONUS: It stays crispy for days! The secret is clarified butter which is 100% fat, and no water. Normal butter is 15% water so it what makes popcorn soggy. It''s a Movie Popcorn secret!', 'https://www.recipetineats.com/tachyon/2020/11/Slightly-sweet-and-salty-popcorn_0.jpg', 5, 15, 20, 13, '[{"id": "ing_corn", "quantity": {"value": 0.25, "unit": "can of 400g"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.03, "unit": "kg"}}]', '[{"ingredients":["2/3 cup popping corn","2 tbsp clarified butter or ghee (, or oil, for stovetop popcorn(Note 1))"],"purpose":"Popcorn:"},{"ingredients":["1 tbsp salt (you won''t use it all, Note 2)"],"purpose":"\"Popcorn Salt\":"},{"ingredients":["3 tbsp clarified butter or ghee (, melted (Note 1))","1/2 tsp Popcorn Salt (per directions below)","2 tbsp icing sugar / powdered sugar"],"purpose":"Flavourings:"}]', '[{"title":"Pop the kernels using your method of choice","description":"either popcorn maker or stove (see next section)","images":[],"step":1},{"description":"Stovetop Popcorn","images":[],"step":2},{"title":"Heat fat","description":"Melt clarified butter in a large pot over medium high heat (medium for strong stoves). Add a few kernels of popcorn and wait until they pop - this means the oil is now hot enough. Quickly remove test popcorn.","images":[],"step":3},{"title":"Add popcorn","description":"Add remaining popcorn, lift pot off stove to shake and spread corn out evenly. Cover with a lid and return to heat. Once the popping really gets going, shake the pot gently once.","images":[],"step":4},{"description":"Done! Remove from heat when the popping largely stops (3 seconds between pops) and transfer to a (very!) large bowl.","images":[],"step":5},{"description":"Place salt in a mortar and pestle then grind into a fine powder. You could also do this using a spice grinder. You won''t use it all, but it''s harder to work with a smaller quantity than this.","images":[],"step":6},{"description":"Sprinkle & toss!","images":[],"step":7},{"description":"Drizzle melted clarified butter all over the popcorn surface. Sprinkle with half the salt, then use small sieve to dust with half the icing sugar.","images":[],"step":8},{"description":"Toss very well in large bowl. Then sprinkle with remaining salt and dust with remaining icing sugar. Toss well again. At this stage you can add more sugar or salt, to your taste. The above quantities make it slightly salty and lightly sweet which to me is the perfect balance!","images":[],"step":9}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["snack"],"cuisine":["Western"],"categories":["bite-size-desserts","candy","dessert-recipes","snacks"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4ee0a0fe3b8e', 'en', 'US', 'Churros Recipe', 'Recipe video above. I am obsessed with Churro!! Great party food because they reheat well in the oven. If you don''t have a piping bag, just drop little dollops of dough in the oil and make churros doughnut balls!', 'https://www.recipetineats.com/tachyon/2016/08/Churros_9.jpg', 5, 15, 20, 12, '[{"id": "ing_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_cinnamon", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_flour", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.033, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_chocolate", "quantity": {"value": 0.5, "unit": "block of 100g"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}]', '[{"ingredients":["1/4 cup caster / superfine sugar","2 tsp ground cinnamon"],"purpose":"Cinnamon Sugar Coating"},{"ingredients":["1 cup flour, plain / all purpose (Note 1)","1 tsp baking powder","Pinch of salt","1 tbsp vegetable, canola or olive oil (not extra virgin olive oil)","1 cup boiling water","2 cups+ vegetable or canola oil (, for frying)"],"purpose":"Churros"},{"ingredients":["1/2 cup dark chocolate or semi sweet chocolate chips (Note 2)","1/2 cup thickened / heavy cream (heavy cream)"],"purpose":"Chocolate Sauce"}]', '[{"title":"Cinnamon sugar coating","description":"Combine sugar and cinnamon in a shallow bowl, set aside.","images":[],"step":1},{"title":"Batter","description":"Mix flour, baking powder and salt in a bowl. Add oil and water and mix until just combined - it should be a thick, gummy batter, like a wet sticky dough, not thin and watery.","images":[],"step":2},{"title":"Piping bag","description":"Transfer dough into a piping bag with a 8mm / 1/3\" star tip nozzle. Set aside while oil heats.","images":[],"step":3},{"title":"Heat oil","description":"Heat 5cm / 2\" oil over medium high in a small pot, wok or small but deep skillet (Note 3) to 170°C/340°F, or until it takes 20 seconds for a small cube of bread to turn golden.","images":[],"step":4},{"title":"Pipe & snip","description":"Pipe 15cm / 6\" lengths of dough into the oil, snipping with scissors (snip close to oil surface to avoid splash). Do 3 to 4 per batch, makes 10 to 12 in total.","images":[],"step":5},{"title":"Cook","description":"Cook for 2-3 minutes or until golden and crisp, rolling occasionally.","duration":2.5,"images":[],"step":6},{"title":"Drain","description":"Remove onto paper towel lined plate to drain. Then roll in sugar. Serve hot with Chocolate Sauce!","images":[],"step":7},{"description":"Chocolate Sauce:","images":[],"step":8},{"description":"Place in a heatproof bowl and microwave in 30 second bursts, stirring in between, until smooth. Set aside for 5 minutes to cool and thicken slightly.","duration":5,"images":[],"step":9}]', '["gluten","milk"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":["Mexican","Spanish"],"categories":["bite-size-desserts","deep-fried-recipes","dessert-recipes","mediterranean-recipes","mexican-recipes","south-american-recipes","spanish-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ff3a02a97120', 'en', 'US', 'Easy Chocolate Truffles', 'Recipe video above. A basic but luxurious chocolate ganache truffle recipe, made using ordinary dark chocolate melts from the supermarket! These are rich and creamy and a great base to add flavourings of choice (suggestions below). Makes around 24 truffles. Use for gifting, post dinner treats, serve with coffee!', 'https://www.recipetineats.com/tachyon/2014/11/Chocolate-Truffles_5.jpg', 15, 0, 15, 24, '[{"id": "ing_chocolate", "quantity": {"value": 285.0, "unit": "block of 100g"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_desiccated_coconut", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_cocoa_powder", "quantity": {"value": 0.15, "unit": "pack of 250g"}}, {"id": "ing_peanuts", "quantity": {"value": 0.188, "unit": "jar"}}, {"id": "ing_sprinkles", "quantity": {"value": 0.333, "unit": "unit"}}, {"id": "ing_sugar", "quantity": {"value": 0.037, "unit": "kg"}}]', '[{"ingredients":["285g / 10 oz dark chocolate melts (chocolate chips, or chocolate block coarsely chopped)","2 tbsp (30g) unsalted butter","1/2 cup (125ml) cream (full fat, not low fat, not whipped)"]},{"ingredients":["1/2 cup desiccated coconut","1/4 cup unsweetened cocoa powder (Dutch Processed is darker, looks \"posh\")","1/2 cup crushed peanuts (small, so can stick)","1/3 cup sprinkles or similar","1/4 cup icing sugar / powdered sugar"],"purpose":"Coating ideas (each enough to coat 24 truffles)"}]', '[{"description":"Place chocolate, cream and butter in a microwave proof bowl. Microwave on high for 4 x 30 second bursts, stirring in between.","images":[],"step":1},{"description":"Cover bowl with a plate and stand for 5 minutes, then stir until chocolate is melted and smooth (this is a ganache!)","duration":5,"images":[],"step":2},{"description":"Place the bowl in the refrigerator for 6 hours. Do not be tempted to shortcut it by freezing it! (Note 2)","images":[],"step":3},{"description":"Put a dinner plate or tray that you will use to place the rolled truffles on in the fridge as well.","images":[],"step":4},{"description":"Rolling the Truffle Balls","images":[],"step":5},{"description":"Place cocoa / coatings of choice in a small bowl or plate.","images":[],"step":6},{"description":"Remove Ganache from fridge. The chocolate mixture should be firm - softer than cold butter but harder than peanut butter.","images":[],"step":7},{"description":"Get an ice pack or bag of frozen peas from the freezer and place on the bench. Cover with a couple of paper towels. (\"Freezer Pack\").","images":[],"step":8},{"description":"Scoop up a tablespoon (using tablespoon measure), then use a teaspoon to scoop the mixture out into your hands (see video). Roll into ball then place on chilled plate. Repeat with remaining chocolate mixture, chilling hands on Freezer Pack as needed.","images":[],"step":9},{"description":"Once all balls are rolled, roll in cocoa or Coatings of choice. Serve at room temp so the chocolate is beautifully creamy inside!","images":[],"step":10}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["bite-size-desserts","candy","dessert-recipes","dietary","gluten-free-recipes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b8f2357dbbe7', 'en', 'US', 'Caramel Popcorn', 'Recipe video above. The secret to a great caramel popcorn that''s evenly coated with caramel with a thin, crispy coating of caramel (rather that globs of sticky caramel) is baking soda and baking the popcorn to dry it out. This caramel corn stays crispy for 2+ weeks!!! CARAMEL COVEREAGE: Use 1/3 cup kernels for full caramel coverage (very sweet, like candy pieces), 3/4 cup for "normal" (see in post for photo and description).', 'https://www.recipetineats.com/tachyon/2014/05/Caramel-Popcorn.jpg', 10, 55, 65, 8, '[{"id": "ing_vegetable_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_corn", "quantity": {"value": 0.125, "unit": "can of 400g"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 0.125, "unit": "can of 400g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.013, "unit": "tub of 200g"}}]', '[{"ingredients":["1/4 cup (60ml) vegetable oil (not required if air popping with a popcorn maker)","1/3 cup popping corn (10 cups popcorn, Note 1 for lighter caramel coverage)"],"purpose":"For the popcorn"},{"ingredients":["100g / 7 tbsp butter (, unsalted)","1 cup (220g) brown sugar (, packed)","1/2 cup (170g) corn syrup (, light (sub glucose, Note 2 more subs))","1/2 tsp salt","1 tsp vanilla extract","1/2 tsp baking soda"],"purpose":"For the caramel"}]', '[{"description":"Heat oil in a large pot over medium heat. Add a few pieces of popcorn and wait until it pops, then quickly remove.","images":[],"step":1},{"description":"Add remaining popcorn, elevate off stove to shake and spread corn out evenly. Cover with a lid. Once the popcorn starts popping in earnest, shake the pot gently once.","images":[],"step":2},{"description":"Remove from heat when the popping stops (when you can count to 3 between pops) and transfer to a (very!) large bowl. You need 10 cups of popcorn.","images":[],"step":3},{"description":"Preheat oven to 110°C/230°F.","images":[],"step":4},{"description":"Melt butter in a saucepaan over medium heat.","images":[],"step":5},{"description":"Add sugar, corn syrup and salt. Stir until just combined.","images":[],"step":6},{"title":"When it starts to bubble, simmer for 4 minutes","description":"DO NOT STIR!","duration":4,"images":[],"step":7},{"description":"Remove from heat then quickly whisk in vanilla and baking soda. When you stop whisking, the caramel will foam and increase in volume.","images":[],"step":8},{"description":"Quickly pour straight over popcorn, toss until caramel cools and starts to harden.","images":[],"step":9},{"description":"Baking to crisp:","images":[],"step":10},{"description":"Spread popcorn on 2 baking trays.","images":[],"step":11},{"description":"Bake for 45 minutes, tossing every 10 minutes or so. Caramel will remelt for the first 2-3 tosses - tossing coats popcorn more evenly with caramel. (If using glucose or honey, bake further 15 minutes).","duration":45,"images":[],"step":12},{"description":"Remove from oven, leave to cool. Gently break into pieces and serve. Stays crisp 2 - 3 weeks!","images":[],"step":13}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["bite-size-desserts","candy","dessert-recipes","quick-and-easy","snacks"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_792f111672ff', 'en', 'US', 'Profiteroles', 'Recipe video above. Crispy light-as-air pastry balls filled with custard or cream and topped with chocolate. There are few things in life as delightful as biting into one of these! Terrific lighter / finger food option for dessert. Bonus: people are always impressed when you bring these to gatherings - but they''re pretty straightforward!', 'https://www.recipetineats.com/tachyon/2018/11/Profiteroles_4.jpg', 30, 40, 70, 48, '[{"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 333.333, "unit": "carton of 12"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.004, "unit": "carton of 250ml"}}, {"id": "ing_cream", "quantity": {"value": 0.004, "unit": "carton of 250ml"}}, {"id": "ing_cream", "quantity": {"value": 0.004, "unit": "carton of 250ml"}}, {"id": "ing_egg", "quantity": {"value": 333.333, "unit": "carton of 12"}}, {"id": "ing_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.131, "unit": "pack of 400g"}}, {"id": "ing_milk", "quantity": {"value": 0.583, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_vanilla_bean_paste", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_chocolate", "quantity": {"value": 250.0, "unit": "block of 100g"}}, {"id": "ing_cream", "quantity": {"value": 0.8, "unit": "carton of 250ml"}}]', '[{"ingredients":["100g / 7 tbsp unsalted butter","1 cup water","1 cup flour (, plain / all purpose)","4 large eggs (55 - 60g / 2 oz each (weight with shell), at room temperature)","Pinch of salt"],"purpose":"Choux Pastry (profiterole pastry balls):"},{"ingredients":["Vanilla custard (Creme Patissiere) (below)","Ice cream (Note 1)","Whipped cream (Note 2)"],"purpose":"Filling Options (choose one):"},{"ingredients":["4 egg yolks (Note 5 for using leftover whites)","1/4 cup white sugar (, caster / superfine)","3 1/2 tbsp cornflour / cornstarch","2 1/3 cups milk (, full fat best)","1/4 cup extra white sugar (, caster / superfine)","1 tsp vanilla bean paste (or extract or essence)"],"purpose":"Thick Custard Filling (Creme Patissiere):"},{"ingredients":["250g / 8 oz dark chocolate (or US semi-sweet)","1 cup cream"],"purpose":"Chocolate Sauce (Note 3):"}]', '[{"title":"Simmer butter & water","description":"Place butter in a saucepan over medium heat. When mostly melted, add water then bring to a rapid simmer.","images":[],"step":1},{"title":"Add flour","description":"While liquid is simmering, add flour and pinch of salt, and stir vigorously with a wooden spoon (still on stove) until the dough forms sort of a ball and pulls away from the sides of the saucepan (see video). About 1 minute.","images":[],"step":2},{"title":"Cool","description":"Remove from heat and let mixture cool for 10 minutes.","duration":10,"images":[],"step":3},{"description":"Preheat oven to 220°C/420°F (200°C fan).","images":[],"step":4},{"title":"Prepare trays","description":"Lightly grease 2 large or 3 standard baking trays with butter, then line with paper. (Grease stops paper sliding)","images":[],"step":5},{"title":"Add egg into cool dough","description":"Add 1 egg into batter, beat until combined. Add remaining eggs one at a time making sure each is combined before adding the next. Dough should be like a thick paste (see video).","images":[],"step":6},{"title":"Transfer to piping bag","description":"Place dough into a piping bag fitted with a 13 - 15mm round tip (1/2 - 3/5\").","images":[],"step":7},{"title":"Pipe blobs","description":"Pipe 2 tsp blobs 5cm/2\" apart (I do 16 on each tray). Makes 40 - 50 blobs.","images":[],"step":8},{"title":"Pat down peak","description":"Wet your finger with water and pat down any peaks to form domes (for nice round balls).","images":[],"step":9},{"description":"Bake 2 trays at a time for 15 minutes, switching the trays halfway.","duration":15,"images":[],"step":10},{"description":"Remove from oven, reduce heat to 180°C/35°0F (160°C fan). They should be crispy enough that when pierced, they will not collapse - if not, return to oven for 3 minutes.","duration":3,"images":[],"step":11},{"title":"Pierce balls with knife then return to oven for 5","description":"7 minutes until golden and crispy.","duration":6,"images":[],"step":12},{"title":"Cool & fill","description":"Transfer to rack, cool fully before filling with custard, cream or split then fill with ice cream. Drizzle with chocolate and serve!","images":[],"step":13},{"description":"Chocolate topping:","images":[],"step":14},{"description":"Place cream and chocolate in a heatproof bowl. Microwave 4 x 30 seconds, stirring in between, until incorporated. Cool to warm, then use for drizzling or dipping.","images":[],"step":15},{"description":"Custard filling:","images":[],"step":16},{"description":"Whisk yolks and sugar, then whisk in cornflour.","images":[],"step":17},{"description":"Place milk, vanilla and extra sugar in a saucepan over medium high. Heat until just before simmering.","images":[],"step":18},{"description":"Whisk in 1/4 cup hot milk into egg mixture. Whisk in another 1/4 cup. Then add remaining milk mixture and whisk.","images":[],"step":19},{"description":"Pour back into saucepan. Return to stove on medium low (low for strong stoves). Whisk constantly 2 to 3 minutes until the mixture thicks to a thick dolloping custard consistency.","images":[],"step":20},{"description":"Remove from heat immediately, pour into bowl. Press cling wrap onto surface (stops skin forming) then refrigerate for 4 to 5 hours until set. Do not whisk again once set (loses thickness).","images":[],"step":21},{"description":"Spoon into piping bag fitting with a very fine nozzle. Then pipe into profiteroles (use the hole pierced during bake, or make a new hole).","images":[],"step":22}]', '["egg","gluten","milk"]', '["keto_friendly","low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["bite-size-desserts","dessert-recipes","egg-yolk-recipes","iconic-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8a87c897ea63', 'en', 'US', 'Baklava', 'Recipe video above. Layers upon layers of flaky pastry with a syrup soaked walnut or pistachio filling! Just like store bought - except it''s not overly sweet, and you will love the hint of lemon. Makes 24 whole pieces plus a bunch of half pieces (cooks'' treat!). Keeps for a WEEK!! This recipe is best started the night before and needs 6+hours resting time.', 'https://www.recipetineats.com/tachyon/2018/09/Baklava_1.jpg', 45, 70, 115, 24, '[{"id": "ing_sheets_filo_phyllo_pastry", "quantity": {"value": 40.0, "unit": "pack"}}, {"id": "ing_walnuts", "quantity": {"value": 500.0, "unit": "jar"}}, {"id": "ing_butter", "quantity": {"value": 285.0, "unit": "block of 250g"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_honey", "quantity": {"value": 0.25, "unit": "jar of 500g"}}]', '[{"ingredients":["40 sheets filo/phyllo pastry (2 x 375g or 1 x 1lb pack, Note 1 for pack sizes)","500g / 1 lb walnuts (other nuts Note 2)","285 g / 10 oz unsalted butter (, melted and slightly cooled)","1 tsp cinnamon powder"]},{"ingredients":["1 cup / 200g white sugar","2 tbsp lemon juice","3/4 cup / 185 ml water","1/2 cup / 170 g honey"],"purpose":"Syrup:"}]', '[{"description":"You will need a 23 x 33 cm / 9 x 13\" baking pan.","images":[],"step":1},{"description":"For best results, thaw phyllo pastry overnight in the fridge (even if the pack says otherwise) then take out of the fridge 30 minutes prior.","images":[],"step":2},{"description":"Cut phyllo to the size of the baking pan.","images":[],"step":3},{"description":"Keep pastry covered with a damp tea towel at all times.","images":[],"step":4},{"description":"Place nuts and cinnamon in a food processor. Pulse 15 times or until fine crumbs - don''t let it turn into powder.","images":[],"step":5},{"description":"Assemble Baklava (see Layers visual below):","images":[],"step":6},{"description":"Preheat oven to 160C / 325F.","images":[],"step":7},{"title":"Base","description":"Brush base of pan with butter. Lay over one sheet of phyllo. Brush with butter. Repeat to use 10 sheets, brushing every single sheet with butter. Scatter over 3/4 cup walnuts.","images":[],"step":8},{"title":"Mid layers","description":"Cover with 5 sheets of phyllo, brushing every sheet with butter. Top with 3/4 cup walnuts. Repeat 3 more times.","images":[],"step":9},{"title":"Top","description":"Cover with 10 sheets of phyllo, brushing every sheet with butter, including the final layer.","images":[],"step":10},{"description":"Cut the baklava into 4 long strips, then cut on the diagonal to make diamonds. (Note 3)","images":[],"step":11},{"title":"Bake for 1 hour","description":"1 hr 15 minutes until golden brown. Meanwhile, make syrup (needs time to cool)","images":[],"step":12},{"description":"Remove from oven and immediately pour over syrup.","images":[],"step":13},{"description":"Leave to soak for at least 6 hours, preferably overnight.","images":[],"step":14},{"description":"Check to ensure each piece is cut all the way through, then serve. Keeps for a week!","images":[],"step":15},{"description":"Place ingredients in a saucepan over medium high heat. Bring to a simmer, stir to dissolve sugar. Lower heat to medium and simmer for 3 minutes, remove from heat and cool.","duration":3,"images":[],"step":16}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Greek"],"categories":["bite-size-desserts","cuisines","dessert-recipes","greek-recipes","iconic-dishes","mediterranean-recipes","middle-eastern-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9a8ab7ae481b', 'en', 'US', 'Chocolate Covered Strawberries', 'Recipe video above. These are the ultimate 3 ingredient dessert! Bite size, low cal, easy to make vast quantities - FAST!', 'https://www.recipetineats.com/tachyon/2017/01/Chocolate-Covered-Strawberries-8.jpg', 10, 0, 10, 4, '[{"id": "ing_chocolate", "quantity": {"value": 1.0, "unit": "block of 100g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_strawberries", "quantity": {"value": 2.0, "unit": "punnet of 250g"}}, {"id": "ing_desiccated_coconut", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_nuts", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_sprinkles", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_other_coating_of_choice", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["1 cup (175g) chocolate chips (Note 1)","2 tsp vegetable oil (or grapeseed oil, canola, peanut or other neutral oil) (Note 2)","500g / 1 lb strawberries (~25 strawberries, depends on size, Note 3)"]},{"ingredients":["Desiccated coconut","Crushed nuts","Sprinkles","Other coating of choice"],"purpose":"Optional – for coating"}]', '[{"description":"Line a tray with baking paper (parchment paper).","images":[],"step":1},{"description":"Place chocolate in a microwave proof bowl.","images":[],"step":2},{"description":"Microwave on high in 30 second bursts, stirring in between, until smooth (see video).","images":[],"step":3},{"description":"Pick up a strawberry by its stem, or gather up the leaves around the stem to get a grip hold on the strawberry.","images":[],"step":4},{"description":"Dip into the chocolate, rolling to coat most of it (see video), the place onto the tray.","images":[],"step":5},{"description":"Repeat with remaining strawberries.","images":[],"step":6},{"description":"If using coconut / nuts or other coating, dip into the coating then lay on tray.","images":[],"step":7},{"description":"Refrigerate for 30 minutes or until chocolate is firm.","duration":30,"images":[],"step":8},{"description":"Best served within 12 hours of making. (Note 4)","images":[],"step":9}]', '["peanuts"]', '["gluten_free","keto_friendly","low_calorie","vegan","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Dessert"],"categories":["bite-size-desserts","dessert-recipes","easter-baking-desserts","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_879363f9cdf5', 'en', 'US', 'Mini No Bake Nutella Cheesecake', 'A Oreo biscuit base topped with a mousse-like Nutella Cheesecake. It''s so easy to make and it''s NO BAKE!', 'https://www.recipetineats.com/tachyon/2016/07/No-Bake-Mini-Nutella-Cheesecake_7.jpg', 20, 0, 20, 12, '[{"id": "ing_packet", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_cream_cheese", "quantity": {"value": 8.0, "unit": "block of 250g"}}, {"id": "ing_nutella", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_cream", "quantity": {"value": 0.907, "unit": "carton of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.05, "unit": "bottle of 50ml"}}, {"id": "ing_nutella", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}]', '[{"ingredients":["1 (4.8 oz / 137g) packet (oreo cookies (Note 1))","3 tbsp / 45 g unsalted butter (, melted)"],"purpose":"Biscuit Base"},{"ingredients":["8 oz / 250 g Philadelphia cream cheese (brick form, NOT tub!) (, softened)","3/4 cup + 2 tbsp / 240 g Nutella (or hazelnut spread)","1/4 cup / 65 ml heavy cream (Note 2)","1/2 cup / 30 g icing sugar (confectionary / powdered sugar)","1/2 tsp vanilla extract (optional)"],"purpose":"Cheesecake"},{"ingredients":["1/3 cup / 80 g Nutella (Note 3)","3/4 cup / 185 ml heavy cream (Note 2)","2 tbsp / 25 g sugar"],"purpose":"Toppings"}]', '[{"description":"Line a standard 12 hole muffin tin with paper patties.","images":[],"step":1},{"description":"Use a food processor or place Oreos in a ziplock bag and bash with a rolling pin to make fine crumbs.","images":[],"step":2},{"description":"Mix Oreo crumbs with butter. Divide between holes and press firmly to flatten.","images":[],"step":3},{"description":"Beat cream cheese until smooth. Then beat in icing sugar, Nutella and vanilla extract. Add cream and beat for 2 to 3 minutes or until fluffy like frosting.","duration":2.5,"images":[],"step":4},{"description":"Divide mixture between holes. Smooth out top. Refrigerate until firm in muffin tin (Note 5)","images":[],"step":5},{"description":"Beat cream until starting to thicken, add sugar then beat until soft peaks form. Transfer to piping bag (optional) and pipe / dollop cream on each.","images":[],"step":6},{"description":"Place Nutella in one corner of a small ziplock bag and microwave for 15 seconds on high. Snip a a tiny hole in one corner of the ziplock bag. Drizzle over cheesecakes. (Note 6)","duration":0.25,"images":[],"step":7},{"description":"Serve cool (Note 7)","images":[],"step":8}]', '["milk","nuts"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":[],"categories":["bite-size-desserts","cheesecakes","dessert-recipes","most-popular"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bce4a37d39c0', 'en', 'US', 'Homemade Reese''s Peanut Butter Cups', 'I created this recipe out of necessity. Because I am addicted to Reese''s Peanut Butter Cups but they''re pretty expensive here in Sydney!', 'https://www.recipetineats.com/tachyon/2014/09/Peanut-Butter-Cups-edited-ps-2.jpg', 15, 0, 15, 30, '[{"id": "ing_peanut_butter", "quantity": {"value": 0.4, "unit": "jar of 375g"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_chocolate", "quantity": {"value": 500.0, "unit": "block of 100g"}}]', '[{"ingredients":["1 cup / 250g smooth peanut butter","60g / 4 tbsp unsalted butter","1/4 cup / 55g brown sugar","1 cup / 120g icing sugar (powdered sugar) (see notes)","500 g /16 oz chocolate (for melting, not eating chocolate)"]}]', '[{"description":"Line 3 x 12 hole mini muffin tins with paper patties.","images":[],"step":1},{"description":"Combine peanut butter, butter and sugar in a small saucepan over medium heat. Heat until melted, stirring constantly, until it starts to bubble gently. Remove from heat and add the powdered sugar 1/4 cup at a time, stirring vigorously to dissolve into the peanut butter mixture.","images":[],"step":2},{"description":"Set the peanut butter filling aside to cool (refrigerate to speed up the process).","images":[],"step":3},{"description":"Melt half the chocolate in the microwave in 30 second bursts, stirring in between.","images":[],"step":4},{"description":"Pour about 1 1/2 to 2 tsp of melted chocolate into each muffin cup.","images":[],"step":5},{"description":"Scoop up one slightly heaped tsp of the peanut butter filling and roll into a ball then flatten slightly. The disc should be smaller than the muffin cup diameter as you want chocolate to cover the side of the peanut butter filling. Place into the centre of the muffin cup. Repeat with remaining peanut butter filling.","images":[],"step":6},{"description":"Refrigerate for 20 minutes until the chocolate is set.","duration":20,"images":[],"step":7},{"description":"Melt the remaining chocolate in the microwave in 30 second bursts, stirring in between.","images":[],"step":8},{"description":"Pour about 1 1/2 to 2 tsp of melted chocolate into each muffin cup, covering the peanut butter filling. Gently bang the muffin tin on the counter top to even out the surface of each peanut butter cup.","images":[],"step":9},{"description":"Refrigerate for 20 minutes until the chocolate is set.","duration":20,"images":[],"step":10},{"description":"Remove paper patties and serve.","images":[],"step":11}]', '["milk","peanuts"]', '["gluten_free","vegetarian"]', '{"mealType":["dessert"],"cuisine":[],"categories":["bite-size-desserts","candy","dessert-recipes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6a96e2e1f0d3', 'en', 'US', 'Blueberry Cheesecake', 'Recipe video above. To say this Blueberry Cheesecake is bursting with blueberries is an understatement! Baked to achieve that elusive light-yet-rich creamy cheesecake filling, studded with blueberries inside and smothered in an incredible glossy blueberry sauce topping. It''s magnificent!Don''t be daunted by the number of steps - they are straightforward, I''ve just broken it down into managable steps. Cheesecakes are actually less "risky" than cakes because - no worries about not rising, sinking in middle etc.If blueberries are expensive right now but you''re absolutely busting to make this, skip the topping and serve with cream instead.', 'https://www.recipetineats.com/tachyon/2020/08/Blueberry-Cheesecake_1.jpg', 30, 70, 300, 12, '[{"id": "ing_arnott_s_marie_crackers_or_16_graham_cracker_squares", "quantity": {"value": 200.0, "unit": "pack"}}, {"id": "ing_butter", "quantity": {"value": 120.0, "unit": "block of 250g"}}, {"id": "ing_cream_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.3, "unit": "tub of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_blueberries", "quantity": {"value": 2.0, "unit": "punnet of 125g"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.019, "unit": "pack of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}]', '[{"ingredients":["200g/7 oz Arnott''s Marie crackers or other plain biscuit (Aus) or 28 Graham Cracker squares (Note 1)","120g / 8 tbsp unsalted butter (, melted)"],"purpose":"Cheesecake Biscuit Base:"},{"ingredients":["1 lb / 500g cream cheese (, well softened (Note 2))","2 tbsp flour (, plain/ all purpose flour)","1 tsp vanilla extract","1/2 cup sour cream (full fat, sub yogurt)","1 1/2 cups caster sugar (superfine sugar)","Zest of 1 lemon (can skip)","3 eggs (, at room temperature)","250g / 8oz blueberries (Note 3)"],"purpose":"Cheesecake Filling:"},{"ingredients":["375g / 13 oz blueberries (Note 3)","2 tbsp lemon juice (or water)","1/2 cup white sugar","1/2 tsp vanilla extract","1 1/2 tsp cornflour/cornstarch","2 tbsp water"],"purpose":"Blueberry Topping for Cheesecake:"}]', '[{"description":"Preheat oven to 160°C/320°F (140°C fan). Place shelf in middle of oven.","images":[],"step":1},{"title":"Line inverted base","description":"Get a 20cm/8\" springform cake tin. Turn the base UPSIDE DOWN (Note 4), butter lightly then press on a square piece of parchment/baking paper. Then clip into the springform pan - excess paper will stick out, see photos in post and video.","images":[],"step":2},{"title":"Line sides","description":"Butter and line the side of the pan.","images":[],"step":3},{"description":"Cheesecake Biscuit Base:","images":[],"step":4},{"description":"Break up biscuits roughly by hand and place in a food processor.","images":[],"step":5},{"description":"Blitz until fine crumbs. Add butter, briefly blitz until dispersed and it resembles wet sand.(Note 5)","images":[],"step":6},{"description":"Pour into the prepared cake tin. Use a spatula to roughly spread it out over the base and up the walls.","images":[],"step":7},{"description":"Use something with a flat base and vertical edges (I use a measuring cup) to press the crumbs up the wall almost to the top of the sides, and flatten the base.","images":[],"step":8},{"title":"Cream cheese","description":"Use a stand mixer (with paddle) or handheld beater to beat the cream cheese until just smooth, no longer than 20 seconds on speed 4. (You do not want to aerate cheesecake filling too much as it causes cracks when it bakes)","images":[],"step":9},{"description":"Add flour, beat for 5 seconds on speed 4 until just incorporated.","duration":0.08333333333333333,"images":[],"step":10},{"description":"Add vanilla, sour cream, sugar and lemon zest. Beat until just combined (10 sec max, speed 4).","images":[],"step":11},{"title":"Eggs: Add eggs one at a time","description":"beat for 5 seconds on speed 4 in between each. After the last egg, beat as needed until batter is smooth - but stop beating immediately once smooth.","duration":0.08333333333333333,"images":[],"step":12},{"title":"Blueberries","description":"Stir in blueberries with a rubber spatula. Pour into prepared crust.","images":[],"step":13},{"title":"Bake","description":"Bake for 70 minutes. The top should be a bit puffed, very light golden brown, not cracked, and near perfectly flat. It should jiggle slightly when you gently shake the pan, see video at 1 min 23 sec (sets in next step).","duration":70,"images":[],"step":14},{"title":"Cool","description":"Cool the cake in the oven with the door open approx 20 cm / 8\" for about 2 hours (Note 6), then refrigerate for 4 hours+ in the pan or overnight. Cake will sink and surface should be flat.","images":[],"step":15},{"title":"Release","description":"Remove sides of springform pan. Use overhang paper to slide cheesecake off the cake pan base. Then slide the cheesecake off the paper.","images":[],"step":16},{"description":"Blueberry Sauce for Cheesecake:","images":[],"step":17},{"description":"Place 1 cup of blueberries (125g/4oz), vanilla, sugar and lemon juice in a saucepan. Stir then bring to simmer over medium heat. Simmer for 7 minutes until blueberries breakdown.","duration":7,"images":[],"step":18},{"title":"Mix cornflour and water, then stir in","description":"it wil thicken quickly.","images":[],"step":19},{"description":"Stir in remainig blueberries. Sauce should be syrupy - remove from stove and cool. Will thicken as it cools.","images":[],"step":20},{"description":"Once cool, stir. Adjust thickness 1/2 teaspoon of water at a time to make it the perfect \"oozing\" consistency (see video, Note 7) - be careful, don''t make it runny!","images":[],"step":21},{"title":"Spoon onto cheesecake so it''s completely covered","description":"you''ll have maybe 1/2 cup sauce left, good for touch ups. Refrigerate 2 hours+.","images":[],"step":22},{"description":"Slice and serve!","images":[],"step":23}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["blueberries","cheesecakes","dessert-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9c6601fc733c', 'en', 'US', 'Extra Fluffy Blueberry Pancakes', 'Recipe video above. I like to make my blueberry pancakes a little thicker and fluffier than plain pancakes because the blueberries kind of weighs the batter down. To do this, use baking soda (bi-carb) to make them rise plus a smidge of vinegar which gives the baking soda a kick start. Don''t worry, you can''t taste it! Use fresh or frozen blueberries (don''t thaw).', 'https://www.recipetineats.com/tachyon/2019/01/Blueberry-Pancakes_8.jpg', 5, 15, 20, 6, '[{"id": "ing_blueberries", "quantity": {"value": 1.8, "unit": "punnet of 125g"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.067, "unit": "tub of 150g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.006, "unit": "tub of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_milk", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_maple_syrup", "quantity": {"value": 1.0, "unit": "bottle of 250ml"}}]', '[{"ingredients":["1 1/2 cups (225g) blueberries (, fresh or frozen (don''t thaw) (Note 1))","Butter for pan"]},{"ingredients":["1 cup flour (, plain / all purpose)","2 tbsp white sugar","2 tsp baking powder","1/4 tsp baking soda (aka bi carbonate soda/bi-carb) (Note 2)","Pinch of salt"],"purpose":"Dry:"},{"ingredients":["1 egg","30g / 2 tbsp melted butter (, unsalted)","3/4 cup milk (, any fat % or non dairy)","1 tsp vanilla extract","1 tsp white vinegar (Note 3)"],"purpose":"Wet:"},{"ingredients":["Softened butter","Maple syrup"],"purpose":"Serving:"}]', '[{"description":"Whisk Dry ingredients.","images":[],"step":1},{"description":"Add Wet ingredients, whisk until just incorporated. Stir through blueberries.","images":[],"step":2},{"description":"Cook","images":[],"step":3},{"description":"Melt about 1 tsp butter in a non stick skillet over medium high heat (medium if strong stove).","images":[],"step":4},{"description":"Dollop a heaped 1/4 cup into the skillet, quickly nudge into a circle about 10 - 12 cm / 4-5\" wide (smaller = thicker). (Note 4)","images":[],"step":5},{"description":"Cook for 1 1/2 minutes until a few bubbles appear and underside is mostly golden.","images":[],"step":6},{"title":"Flip with confidence. Cook a further 1 minute","description":"poke centre, should spring back, underside should be golden.","images":[],"step":7},{"description":"Keep warm & serve","images":[],"step":8},{"description":"Transfer to rack and keep warm in 100C/200F oven in single layer (do not stack). Or get 2 pans going (won''t need to keep warm)","images":[],"step":9},{"description":"Repeat with remaining batter, using extra butter as required.","images":[],"step":10},{"description":"Serve with copious amounts of maple syrup and softened butter.","images":[],"step":11}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["breakfast"],"cuisine":[],"categories":["blueberries","breakfast-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8aefa3151e30', 'en', 'US', 'Quick and dirty focaccia', 'Recipe video above. Thanks to an ultra-high 93% hydration dough based on the infamous NYT No Knead Artisan Bread, all you need to do is mix in a bowl and pour into a pan - no kneading, no folding, no touching the dough until it''s time to dimple! The result is extraordinary - a golden, crisp crust with a soft, fluffy interior and a respectable amount of big bubbles. 93% as good as traditional focaccia with 30% of the effort - high returns!It’s so easy and so good, you’ll think you’ve died and gone to Focaccia Heaven. :)Sound too good to be true? Try it. :-) It''s so low effort and so fool-proof, you''ve got nothing to lose!', 'https://www.recipetineats.com/tachyon/2025/08/Quick-and-dirty-focaccia-freshly-baked.jpg', 5, 25, 205, 6, '[{"id": "ing_bread", "quantity": {"value": 0.375, "unit": "loaf"}}, {"id": "ing_yeast", "quantity": {"value": 1.125, "unit": "pack of 5 sachets"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_chilli_flakes", "quantity": {"value": 0.094, "unit": "jar of 40g"}}]', '[{"ingredients":["2 cups (300g) bread flour (or plain/all-purpose flour, Note 1)","1 1/8 tsp (3.5g) instant yeast (aka rapid rise yeast) (Note 2)","3/4 tsp (4.5g) cooking salt / kosher salt (-50% for table salt, + 50% for salt flakes)","1 cup + 2 tbsp (280 ml / 280g) very warm water (1/3 cup boiling water then top up with cold tap water) (Note 3)"]},{"ingredients":["1 1/2 tbsp extra virgin olive oil","1/4 tsp (heaped) sea salt flakes (or regular salt, couple of pinches)"],"purpose":"Topping:"}]', '[{"description":"Mix dry, then mix in water. Rise 2 hrs to double. Drizzle EVOO into pan, pour into pan, rise 45 min by 50%. Oil surface, very lightly dimple, sprinkle with salt flakes, bake 25 min at 220°C / 425°F (200°C fan).","images":[],"step":1},{"title":"Very sticky dough","description":"Put the flour, yeast and salt in a bowl, mix to combine with a rubber spatula. Make a well in the centre, pour the warm water in then mix until you no longer see flour. It should be like a thick muffin batter - way too sticky and loose to knead.","images":[],"step":2},{"title":"Rise #1 (2 hrs)","description":"Cover with cling wrap then put in a very warm place to rise for 2 hours or until doubled in volume (Note 4), or do Rise #1 in the fridge 24 - 48 hrs (Note 5).","images":[],"step":3},{"title":"Line pan","description":"Use a 26.5 x 20 x 5cm (10.5 x 8 x 2\") rectangle pan (metal, not glass or ceramic) or a 22cm/9″ square pan. Lightly grease with butter (not oil). Scrunch up a sheet of baking paper, un-scrunch then press into the pan, ensuring you have overhang to lift the focaccia out later. (Note 6)","images":[],"step":4},{"title":"Dough in pan","description":"Drizzle and spread 1/2 tablespoon of olive oil in the pan on the paper. Pour the dough batter in, then use 2 rubber spatulas to coax the dough out into the corners as best you can. Don''t get too hung up on this, it will fill the pan as it rises.","images":[],"step":5},{"title":"Rise #2 (45 min)","description":"Cover with a cutting board (or similar - flat - but make sure there''s enough space for the dough to rise!! Note 6), then put in a very warm place for 45 minutes or until it rises by 50 - 70% (you should see some nice big bubbling on the surface). Halfway through, preheat oven.","duration":45,"images":[],"step":6},{"description":"Preheat the oven to 220°C / 425°F (200°C fan-forced) with the oven rack in the middle.","images":[],"step":7},{"description":"Drizzle 1 tbsp of olive oil across the surface. Rub a little oil on your fingertips then use your fingers to spread the oil lightly across the surface. (Note 6 for Toppings)","images":[],"step":8},{"title":"LIGHT dimpling","description":"Use your fingers to LIGHTLY press dimples into the surface of the dough, only pressing down about 1cm/0.4\" into the dough, not all the way down like traditional focaccia else you will deflate the dough.","images":[],"step":9},{"title":"Salt flakes","description":"Sprinkle all over the surface.","images":[],"step":10},{"description":"Bake for 25 minutes, rotating the pan at the 15 minute mark, until the surface is deep golden.","duration":25,"images":[],"step":11},{"title":"Cool 10 minutes","description":"Lift the focaccia out of the pan using the excess paper onto a cooling rack, then slide the paper out from underneath. Cool for 10 minutes then attack! Always best served warm.","duration":10,"images":[],"step":12},{"description":"Serving / cutting:","images":[],"step":13},{"title":"Bread basket","description":"I cut into 4cm / 1.5\" wide strips then each into 2 pieces. Appetiser or to nibble on with drinks - I cut them into smaller pieces (generous) 2-bite pieces. In every scenario, it''s accompanied with a good extra virgin olive oil for dipping, sometimes with a swirl of aged balsamic vinegar. Also makes excellent cheese toasties and sandwiches!","images":[],"step":14}]', '["gluten"]', '["vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Italian","Western"],"categories":["breads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_680395a3951c', 'en', 'US', 'Cheese, Garlic and Herb Quick Bread (no yeast)', 'Recipe video above. A bread made without yeast with swirls of herb and pockets of cheese throughout with addictive garlic flavour. Slices well and especially great toasted!Enjoy for morning tea, take to picnics, serve on the side of meals, dunk into soups and slow cooked stews! Serve warm for the best eating experience, preferably with lashings of butter.PS You can totally use homemade or store-bought pesto instead of the herb & garlic swirl. Use 1/3 to 1/2 cup. Bear in mind the flavour will only be as good as the pesto you use :)', 'https://www.recipetineats.com/tachyon/2015/09/Cheese-Herb-Garlic-Quick-Bread_3.jpg', 15, 50, 80, 8, '[{"id": "ing_cheese", "quantity": {"value": 7.0, "unit": "block of 250g"}}, {"id": "ing_rosemary", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.338, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.033, "unit": "tub of 150g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.15, "unit": "tub of 500g"}}, {"id": "ing_milk", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_butter", "quantity": {"value": 3.5, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}]', '[{"ingredients":["7 oz / 200g block of cheese"]},{"ingredients":["2 tbsp fresh rosemary (, finely chopped)","2 tbsp fresh parsley leaves (, finely chopped)","1 tsp dried oregano","1/2 tsp dried thyme","2 garlic cloves (, crushed using garlic press or finely grated)","3 tbsp extra virgin olive oil","1/2 tsp cooking salt / kosher salt (halve for fine table salt)"],"purpose":"Herb and garlic swirl"},{"ingredients":["2 1/4 cups plain flour (all-purpose flour)","1 tsp baking soda ((bi-carbonate soda), sub 3 1/2 tsp baking powder)","3/4 tsp cooking salt / kosher salt (halve for table salt)"],"purpose":"Dry Ingredients"},{"ingredients":["1/2 cup plain yogurt (, Greek or regular (full fat, unsweetened))","3/4 cup milk (, full fat best, low fat ok)","2 large eggs (~50-55g/2oz each)","3 1/2 tbsp (50g) unsalted butter (, melted)","2 tbsp olive oil","2 small garlic cloves (, crushed with garlic crusher or grated)"],"purpose":"Wet Ingredients"}]', '[{"description":"Preheat oven to 180°C/350°F (both fan and standard ovens).","images":[],"step":1},{"title":"Loaf tin","description":"Grease a 21 x 11 x 7 cm loaf pan (8.3 x 4.5 x 2.75\") lightly with butter or oil spray then line with baking paper (parchment paper). (Note 3)","images":[],"step":2},{"title":"Herb and garlic swirl","description":"Mix the ingredients in a small bowl, it should be a thick dollop-able mixture.","images":[],"step":3},{"title":"Dry ingredients","description":"Whisk the Dry Ingredients in a bowl.","images":[],"step":4},{"title":"Wet ingredients","description":"Whisk the wet ingredients in a separate bowl.","images":[],"step":5},{"title":"Combine","description":"Make a well in the centre of the Dry Ingredients. Pour the Wet Ingredients in and mix until just combined.","images":[],"step":6},{"title":"Swirls and cheese Layer 1","description":"Pour 1/3 of the batter into the bread tin. Dollop 1/3 of the herbs across the top then use a knife to \"swirl\" it into the batter up and down, and also turning the batter over (refer photo below). Use 1/3 of the cheese slices and push them randomly into the batter. Push some all the way in and leave some poking out of the batter.","images":[],"step":7},{"title":"Layers 2 and 3","description":"Repeat twice more. Don''t worry about herb mixture exposed and cheese slices sticking out the surface, looks amazing when baked!","images":[],"step":8},{"description":"Bake for 30 minutes, or until the top is golden. Remove from oven and cover with foil, then bake for a further 20 minutes (total baking time 50 minutes). Check to make sure the centre is cooked by inserting a skewer - it should come out clean.","duration":30,"images":[],"step":9},{"description":"Cool in the loaf tin for 5 minutes then turn the bread out onto a cooling rack. Allow to cool for at least another 10 minutes before cutting thick slices. Butter is optional but always welcome!","duration":5,"images":[],"step":10}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["breads","breakfast-recipes","easter-brunch-recipes","most-popular","quick-and-easy","quick-bread","side-dishes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4675cf1889ce', 'en', 'US', 'Cheese bread (no knead!)', 'Recipe video above.', 'https://www.recipetineats.com/tachyon/2023/06/Cheese-bread-main-photos_7a.jpg', 5, 45, 50, 10, '[{"id": "ing_bread", "quantity": {"value": 0.562, "unit": "loaf"}}, {"id": "ing_yeast", "quantity": {"value": 2.0, "unit": "pack of 5 sachets"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_cheese", "quantity": {"value": 2.5, "unit": "block of 250g"}}]', '[{"ingredients":["3 cups bread flour (Note 1 re: plain/all-purpose flour)","2 tsp instant yeast (aka rapid rise (Note 2))","1 1/2 tsp cooking/kosher salt","1 1/2 cups very warm tap water (Note 3)","2 1/2 cups (tightly packed) Colby cheese (, freshly shredded (or other cheese of choice - Note 4))"]}]', '[{"title":"SHORTHAND RECIPE","description":"for experts","images":[],"step":1},{"title":"Mix dry ingredients, mix in water. Rise 2","description":"3 hrs until doubled.","images":[],"step":2},{"description":"Preheat pot 240°C/450°F (220°C fan). Turn dough out. Reserve 1/3 cheese for topping. Fold inwards 4 times, stuffed/layered with remaining cheese. Flip onto parchment paper. Pile reserved cheese on top.","images":[],"step":3},{"description":"Bake 35 minutes covered, 10 minutes uncovered. Rest 10 minutes. Eat!","images":[],"step":4},{"description":"Magic no-knead dough:","images":[],"step":5},{"title":"Shaggy dough","description":"Using a rubber spatula, mix flour, salt and yeast in a large bowl. Add water, then mix using the handle of the spatula until you can no longer see flour. The dough should be too sticky to knead by hand, but not pourable like cake batter (see video at X seconds).","images":[],"step":6},{"title":"Rise","description":"Cover with cling wrap and leave to rise in a warm place for 2 to 3 hours until the dough doubles in volume (Note 5). The surface should be bubbly, and the mixture should jiggle when you shake the bowl.","images":[],"step":7},{"title":"Preheat pot","description":"Half an hour before the dough is ready, put a 24-28cm / 4.5-8 quart heavy based pot with a lid in the oven to preheat to 240°C/450°F (220°C fan-forced). Note 7 for no dutch oven method.","images":[],"step":8},{"title":"Pat into disc","description":"Sprinkle work surface with 1 tbsp flour. Scrape dough out, sprinkle surface with flour, pat into a ~20cm/8\" disc.","images":[],"step":9},{"title":"Cheese it","description":"Set aside 1/3 of the cheese for topping. Cover surface with half the remaining cheese.","images":[],"step":10},{"title":"Fold inwards stuffed with cheese","description":"Using a dough scraper or anything of similar shape (cake server, large knife, spatula), fold the sides inwards 4 times to roughly form a roundish shape, topping each layer of with the remaining cheese (but keep the final layer cheese free, it will be the base of the bread). (Note 6 for tips)","images":[],"step":11},{"title":"Paper transfer","description":"Flip the dough onto a sheet of parchment/baking paper so the seamside is (mostly) facedown. Tidy the shape if desired. (Note 6)","images":[],"step":12},{"title":"Cheese crown","description":"Pile the reserved cheese on.","images":[],"step":13},{"title":"Hot pot transfer","description":"Remove hot pot from the oven. Use paper to transfer dough into the pot, keeping it on the paper. Put lid on.","images":[],"step":14},{"description":"Bake 35 minutes. Remove lid. Bake 10 minutes to colour the surface.","images":[],"step":15},{"title":"Cool","description":"Remove pot from oven. Use paper to transfer bread onto a cooling rack. Remove paper. Cool at least 10 minutes before slicing! (Note 8)","images":[],"step":16}]', '["gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["breads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_763a53d45d79', 'en', 'US', 'Pide - Turkish Flat Bread / Pizza', 'Recipe video above. It''s hard to get great pide outside of Turkey. It''s hit and miss, even at many Turkish places. Solution: make it yourself! Pide is easier than you think, and it will tick all your pide boxes: pillowy soft bread inside with a crispy base, generous on the toppings. SO GOOD!Makes 2 pide around 40cm / 16" long. A generous meal for 2 people, normal meal for 3 people!TOPPINGS – Choose only 1. Each batch is enough to top 2 pides.', 'https://www.recipetineats.com/tachyon/2021/05/Platter-of-pide.jpg', 30, 30, 60, 2, '[{"id": "ing_yeast", "quantity": {"value": 1.0, "unit": "pack of 5 sachets"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_bread", "quantity": {"value": 0.375, "unit": "loaf"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.2, "unit": "pack of 125g"}}, {"id": "ing_semolina", "quantity": {"value": 2.5, "unit": "pack"}}, {"id": "ing_topping_of_choice", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_sprinkling_finishes_of_choice", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_baby_spinach", "quantity": {"value": 280.0, "unit": "bag of 250g"}}, {"id": "ing_cumin", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_sausages", "quantity": {"value": 0.25, "unit": "pack of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_lamb_mince", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_baharat_spice_mix", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_capsicum", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_cheese", "quantity": {"value": 150.0, "unit": "block of 250g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_sumac", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}]', '[{"ingredients":["1 tsp rapid rise / instant yeast (sub active dry yeast, Note 1)","1/2 tsp white sugar","2 tbsp + 2/3 cups very warm water (, (~40℃ /104℉, Note 2))","2 cups bread flour (sub all purpose/plain flour, Note 3)","3/4 tsp salt","1 1/2 tsp olive oil"],"purpose":"Dough (Makes 2 pide):"},{"ingredients":["150g / 5oz Turkish kasar cheese or mozzarella (Note 4)","1/2 tsp semolina (, optional (Note 10))","1 Topping of choice (each makes enough for 2 pides)","1 egg (optional, Note 13)","Sprinkling finishes of choice (listed below)"],"purpose":"Pide Assembling:"},{"ingredients":["2 tsp olive oil","1/2 onion (, finely diced)","280g / 10oz baby spinach","1/2 tsp cumin","1/2 tsp pepper","1/4 tsp salt (kosher / cooking salt)"],"purpose":"Spinach Topping:"},{"ingredients":["125g / 4oz Turkish sujuk sausage (sub chorizo, Note 5)"],"purpose":"Turkish Sausage Topping (Sujuk):"},{"ingredients":["1 tbsp olive oil","1/2 onion (, finely diced)","1 garlic cloves (, finely minced)","250g / 8oz lamb mince (or beef)","1 tsp tomato paste","1 tsp baharat spice mix (Note 6)","1/2 tsp cumin","1/8 tsp each salt and pepper","1/2 red capsicum / bell pepper (, finely diced)","1/2 tomato (, finely chopped)","1 tsp lemon juice"],"purpose":"Lamb Topping:"},{"ingredients":["4 tbsp Turkish tulum cheese or feta (, crumbled (Note 7))","Dried oregano","Sesame seeds (, toasted)","Sumac","Fresh coriander/cilantro leaves","Extra virgin olive oil"],"purpose":"Sprinkling Finishes – Choose (Note 11):"}]', '[{"title":"Bloom yeast","description":"Mix yeast with 2 tbsp warm water and sugar in a small bowl. Cover with cling wrap, leave for 10 minutes until foamy.","duration":10,"images":[],"step":1},{"title":"Make dough","description":"Mix together flour and salt in a large bowl or stand mixer bowl. Add the yeast mixture, olive oil and remaining 2/3 cups water. Mix together with a wooden spoon. Once the flour is mostly incorporated, switch to your hands and bring it together into a dough.","images":[],"step":2},{"title":"Knead","description":"Sprinkle work surface with 1 tbsp flour, then knead for 8 to 10 minutes by hand OR 3 minutes on speed 6 of a stand mixer. Dough is kneaded enough when it''s smooth and does not break when stretched - see photos video for before/after comparison. (Note 8)","duration":9,"images":[],"step":3},{"title":"Rise 1","description":"Shape into a ball. Smear inside of used bowl with a bit of olive oil, place dough inside. Cover with cling wrap and rise in warm place for 1.5 hours, or until doubled in size. (Note 9)","images":[],"step":4},{"title":"Rise 2","description":"Punch dough down to fully deflate, then divide into 2 equal pieces. Pull the sides down and tuck underneath so the top is smooth, underside is bunched up. Shape into ball and place on a lightly floured tray, smooth side up. Sprinkle surface with flour, then cover with damp tea towel. Rise 1 hour until doubled in size.","images":[],"step":5},{"description":"Assembling & Baking Pide:","images":[],"step":6},{"description":"Preheat oven to 240°C/465°F (220°C fan). Place shelf on the top and middle.","images":[],"step":7},{"title":"Roll","description":"Roll dough out on a lightly floured surface into an oval shape 40cm/16\" long and 20cm/8\" wide (widest point).","images":[],"step":8},{"title":"Prepare 2 trays","description":"Sprinkle 1/4 tsp semolina on each tray, 40cm/16\" long and 15cm/6\" wide. (Note 10)","images":[],"step":9},{"title":"Top Pide","description":"Place a rolled out dough on the semolina. Sprinkle with cheese, then sprinkle chosen Topping evenly across the surface, leaving a 2cm / 4/5\" border all around.","images":[],"step":10},{"title":"Fold dough","description":"Brush the ends with water. Pinch ends together to seal then fold the sides of the pide in.","images":[],"step":11},{"title":"Bake","description":"Bake 15 minutes, switching trays halfway, until the crust is golden.","images":[],"step":12},{"title":"Egg option","description":"Bake pide for 10 minutes, then crack the egg on top and return to oven for 5 minutes. This applies to all Pide - egg can be added for any of them!","duration":10,"images":[],"step":13},{"title":"Top & Serve","description":"Sprinkle with toppings of choice. (Note 11 for combos I used). Cut into 3cm / 1.3\" slices and serve!","images":[],"step":14},{"description":"Spinach Topping:","images":[],"step":15},{"description":"Heat oil in a skillet over medium heat. Cook onion for 3 minutes until translucent. Add spinach, cook until just wilted (add in batches if necessary). Stir in cumin, salt & pepper. Cool before using.","duration":3,"images":[],"step":16},{"description":"Turkish Sausage Topping:","images":[],"step":17},{"description":"Roughly chop, then turn the sausage into mince (ground meat) by using a Nutribullet or food processor.","images":[],"step":18},{"description":"Heat oil in a skillet over medium high heat. Cook garlic and onion for 3 minutes until soft. Add lamb and cook until it changes from pink to brown. Add tomato paste, Baharat, cumin, salt, pepper and cook for 3 minutes.","duration":3,"images":[],"step":19},{"description":"Add capsicum, tomato and lemon juice, then cook over medium heat until most of the liquid evaporates (a couple of minutes usually, though depends on juiciness of tomato). Cool before using.","images":[],"step":20}]', '["egg","gluten","milk","sesame"]', '["high_protein"]', '{"mealType":["dinner","snack"],"cuisine":["Middle Eastern","Turkish"],"categories":["breads","iconic-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_81399cd4e420', 'en', 'US', 'Focaccia recipe', 'Recipe video above. Forget the pale, too-sweet pillow bread that fuelled the focaccia rage of the 90''s. This is how Focaccia should be - crispy on the outside, yet moist and fluffy inside with a little chew. This authentic Italian bread is bursting with character and impossible to stop eating at just one slice!Short on time? Try the new Quick and Dirty Focaccia!', 'https://www.recipetineats.com/tachyon/2021/03/Rosemary-Garlic-Focaccia_2.jpg', 0, 30, 30, 6, '[{"id": "ing_bread", "quantity": {"value": 0.312, "unit": "loaf"}}, {"id": "ing_sugar", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}, {"id": "ing_yeast", "quantity": {"value": 1.0, "unit": "pack of 5 sachets"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_potato", "quantity": {"value": 125.0, "unit": "bag of 2kg"}}, {"id": "ing_chilli_flakes", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_rosemary", "quantity": {"value": 0.25, "unit": "bunch"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 12.0, "unit": "punnet of 250g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.075, "unit": "bunch"}}, {"id": "ing_kalamata_olives", "quantity": {"value": 16.0, "unit": "bottle"}}]', '[{"ingredients":["1 2/3 cups bread flour (Note 1)","4 tsp white sugar","1 1/4 tsp salt (, kosher/cooking salt)","1 tsp instant / rapid rise yeast (Note 2)","3/4 cup very warm water (~40℃ /104℉)","1 1/2 tbsp extra virgin olive oil","125g/ 1/2 cup (packed) boiled and mashed potato (, around 1/2 large potato; floury variety (Note 3))"],"purpose":"Focaccia Dough:"},{"ingredients":["4 tbsp extra virgin olive oil","1/4 tsp sea salt flakes (Note 4)"],"purpose":"For baking:"},{"ingredients":["5 garlic cloves (, cut into fine batons (Note 5))","3/4 cup extra virgin olive oil","2 1/2 tsp finely chopped rosemary leaves (fresh)"],"purpose":"Garlic Rosemary Topping (Note 5):"},{"ingredients":["12 - 14 cherry tomatoes (, red)","3/4 tsp dried oregano leaves (or 2 1/2 tsp finely chopped rosemary leaves)"],"purpose":"Cherry Tomato Topping:"},{"ingredients":["16 - 18 kalamata olives (, pitted)","3/4 tsp dried oregano leaves (or 2 1/2 tsp finely chopped rosemary leaves)"],"purpose":"Black Olive Topping:"}]', '[{"description":"Focaccia Dough:","images":[],"step":1},{"title":"Make mashed potato","description":"Peel potato, cut into 2.5cm / 1\" chunks. Boil until fully tender (around 10 - 15 mins; check centre with skewer). Drain and mash very well with a potato ricer or masher until smooth and lump-free. Set aside to cool, and measure out required quantity.","images":[],"step":2},{"title":"Mix Dry","description":"Place flour, salt, sugar and yeast in a large bowl and mix well with a firm rubber spatula.","images":[],"step":3},{"title":"Add Wet","description":"Make a well in the centre, then add olive oil and warm water. Mix with spatula until you can no longer see flour. Dough should be sticky – too sticky to knead by hand. If your dough seems a touch dry, work in a tablespoon of water at a time to adjust (see video for reference).","images":[],"step":4},{"title":"Add Potato","description":"Add mashed potato. Using a folding motion, start mixing it through using the spatula. Then start smearing it along the walls of the bowl. Once potato is evenly incorporated, shape roughly into a ball in the bowl.","images":[],"step":5},{"title":"Rise 1","description":"Cover bowl with cling wrap, then put in a warm place (25°C/77°F) for 30 minutes until it increases in volume by 50% or up to double in size. (Note 6)","duration":30,"images":[],"step":6},{"title":"Fold dough","description":"Get another large bowl, drizzle with 2 teaspoons of olive oil then use your hands to smear it around the bowl. Scrape dough in, then fold the edges of the dough into the centre six times. Shape into ball, cover with cling wrap.","images":[],"step":7},{"title":"Rise 2","description":"Put the bowl in a warm place (25°C/77°F) for 30 minutes until it increases in volume by 50% or up to double in size.","duration":30,"images":[],"step":8},{"title":"Prepare pan (see Note 7 for pan types info)","description":"Meanwhile, prepare the pan. Use a 26.5 x 20 x 5 cm / 10.5 x 8 x 2” metal non-stick pan, or a 9”/23cm round cake pan, preferably not springform. Pour in 2 tablespoons of olive oil, then smear it all across the base and along the walls.","images":[],"step":9},{"title":"Preheat oven","description":"Preheat oven to 220°C / 430°F (200°C fan), and set a rack on middle shelf. Allow enough time to ensure oven has been preheated for at least 15 mins for best results.","images":[],"step":10},{"title":"Put dough in pan","description":"Scrape dough into prepared pan. Stretch and pull to fill the base as best you can (itʼs an elastic dough so a bit stubborn!), and get the surface roughly level. Itʼs ok if itʼs bumpy, it will smooth out later.","images":[],"step":11},{"title":"Rise 3","description":"Cover pan with cling wrap, then put in a warm place for 40 minutes until the dough expands and fills the pan, and the height rises by around 25 - 30%.","duration":40,"images":[],"step":12},{"description":"Prepare for Baking:","images":[],"step":13},{"title":"Smear surface with oil","description":"Drizzle the surface with 2 teaspoons of olive oil, and smear/rub it over lightly with your hands.","images":[],"step":14},{"description":"Poke! Using both your hands like claws, push your fingers deep into the dough, right to the base of the pan to create the signature dimples. Do this around half a dozen times across dough surface. This will somewhat deflate the dough and is OK. (Note 8)","images":[],"step":15},{"title":"Toppings: Top with toppings of choice","description":"see below.","images":[],"step":16},{"title":"Finishing olive oil & salt flakes","description":"Drizzle the surface with 2 tablespoons of olive oil so it runs into the dimples. Then sprinkle with sea salt flakes.","images":[],"step":17},{"title":"Bake for 25","description":"30 minutes until the top is deep golden and lightly crisp, while the sides are fried and crusty.","duration":27.5,"images":[],"step":18},{"title":"Cool","description":"Turn out onto a cooling rack. Let is rest for at least 10 minutes before cutting to serve. It is ridiculously good served freshly made!","images":[],"step":19},{"title":"Optional","description":"Finishing with a final flourish of extra virgin olive oil across the surface certainly doesnʼt go astray! Also some olive oil for dipping is always welcome. :)","images":[],"step":20},{"title":"Confit Garlic & Rosemary","description":"Place garlic and oil in a small saucepan over medium heat. Once the oil becomes hot, turn down to low and leave for 10 minutes. The garlic should not sizzle, it just poaches gently in hot oil. Strain, cool, then press onto surface of focaccia. Sprinkle with rosemary. Proceed with recipe.","duration":10,"images":[],"step":21},{"title":"Cherry tomato","description":"Squish each tomato while holding near focaccia surface. Press onto surface, pushing into the dough. Sprinkle with oregano. Proceed with recipe.","images":[],"step":22},{"title":"Olives","description":"Press onto surface of focaccia, pushing into the dough. Sprinkle with oregano. Proceed with recipe.","images":[],"step":23}]', '["gluten"]', '["low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Italian"],"categories":["breads","iconic-dishes","italian-recipes","side-dishes","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f3a144aa1056', 'en', 'US', 'Naan recipe – fluffy, bubbly, chewy!', 'Recipe video above. This is a recipe for naan bread that''s fluffy, bubbly and chewy, just as it should be. Nobody will ever mistake this for just another basic flatbread! Perfect for slopping up your favourite Indian curries – yet so good that you''ll happily devour it plain, straight out of the skillet.Bearing in mind that we aren''t cooking in nuclear-level 480°C hot tandoors, see in post for background notes on how I find this recipe to most closely replicates restaurant naan. Makes: 6 naans, ~15-16cm / 6 - 7" diameter. For more Indian recipes, browse the Indian collection.', 'https://www.recipetineats.com/tachyon/2021/02/Naan_1-1.jpg', 20, 10, 30, 6, '[{"id": "ing_yeast", "quantity": {"value": 1.0, "unit": "pack of 5 sachets"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 1.875, "unit": "carton of 12"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 0.328, "unit": "loaf"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_nigella_seeds", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}]', '[{"ingredients":["1 tsp instant / rapid rise yeast (Note 1)","1/2 cup warm tap water (~40°C/105°F in temperature)","1 tbsp white sugar","2 tbsp milk (, full fat (low fat ok too))","1 1/2 tbsp whisked egg (, at room temp (around 1/2 an egg, Note 2))","1/2 tsp salt (, cooking / kosher)","1 3/4 cups bread flour (, or all-purpose/plain (Note 3))","30g / 2 tbsp ghee or unsalted butter (, melted (Note 4))"]},{"ingredients":["30g / 2 tbsp tbsp ghee or butter (, melted (Note 4))","1 small garlic clove (, for Garlic Butter option (Note 5))","Nigella seeds","Coriander/cilantro (, finely chopped)"],"purpose":"Finishes:"},{"ingredients":["Shredded cheese (for cheese naan) – Monterey Jack, cheddar, tasty, colby, anything that melts (shred yourself) (Note 6)"],"purpose":"Cheese Naan:"}]', '[{"title":"Bloom yeast","description":"Mix yeast with warm water and sugar in a small bowl. Cover with cling wrap, leave for 10 minutes until foamy.","duration":10,"images":[],"step":1},{"title":"Egg and milk","description":"Whisk milk and egg together.","images":[],"step":2},{"title":"Flour","description":"Sift flour and salt into a separate bowl.","images":[],"step":3},{"title":"Add wet ingredients","description":"Make a well in the flour, add yeast mixture, and butter and egg mixture. Mix together with a spatula. Once the flour is mostly incorporated, switch to your hands and bring it together into a ball. No kneading is required.","images":[],"step":4},{"title":"Proof 1","description":"Cover the bowl with cling-wrap, then leave in a warm place for 1 - 1.5 hrs until it doubles in size. (Note 7)","images":[],"step":5},{"title":"Cut into 6 pieces","description":"Place the dough on a lightly floured surface. Cut into 6 equal pieces, then shape into balls into spheres with a smooth surface by stretching the surface and tucking it under (see video).","images":[],"step":6},{"title":"Proof 2","description":"Place balls on a lightly-floured tray or plate. Sprinkle lightly with flour, cover loosely with a lightweight tea towel. Put in a warm place to rise for 15 minutes until it increases in size by about 50%.","duration":15,"images":[],"step":7},{"title":"Roll out","description":"Place a round on a lightly-floured work surface, flatten with your hand. Roll out into 3 - 4mm / 0.12 - 0.16\" thick rounds (about 16cm / 6.5\" wide).","images":[],"step":8},{"title":"Heat skillet","description":"Rub a cast iron skillet with a very light coat of oil using 1/2 tsp oil on a paper towl (unless already well seasoned). Set over high heat until you see wisps of smoke. (Note 8 for other pans)","images":[],"step":9},{"title":"Cook naan","description":"Place a naan dough in the skillet and cook for 1 to 1 1/2 minutes until the underside is deep golden / slightly charred – the surface should get bubbly. Flip then cook the other side for 1 minute until the bubbles become deep golden brown.","duration":1,"images":[],"step":10},{"title":"Cook remaining naan","description":"Remove, set aside, and repeat with remaining naan, taking care to regulate the heat of the skillet so it doesn''t get too hot.","images":[],"step":11},{"title":"Finishing","description":"Brush freshly cooked naan with melted butter or ghee (or garlic butter, Note 5). Sprinkle with nigella seeds and coriander. Serve hot!","images":[],"step":12},{"description":"Roll out a naan per above directions. Brush with plain butter or garlic butter. (Note 5) Place a mound of cheese in the middle - about 1/4 cup, lightly-packed. Bundle it up, money bag-style, then twist to seal.","images":[],"step":13},{"description":"Turn upside down so the smooth side is up. Roll out to 6-7mm / 1/4\" thick rounds.","images":[],"step":14},{"description":"Heat a well-seasoned cast iron skillet preheated over high heat, but not until the skillet is smoking. Cook naan for around 1 1/2 minutes on the first side until golden – it will puff up! Turn and cook the other side for around 45 seconds.","images":[],"step":15}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Indian"],"categories":["breads","curry-recipes","iconic-dishes","indian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d10e2860ff98', 'en', 'US', 'Cornbread recipe (creamed corn)', 'Recipe video above. This cornbread is super moist, not too sweet and not crumbly! It''s a Northern style corn bread that''s super quick and easy to make. Also see Cornbread Muffins!', 'https://www.recipetineats.com/tachyon/2014/12/Corn-bread_1.jpg', 10, 30, 40, 10, '[{"id": "ing_corn", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_flour", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.1, "unit": "tub of 150g"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_butter", "quantity": {"value": 0.5, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.188, "unit": "L"}}]', '[{"ingredients":["3/4 cup yellow cornmeal (, medium grind (Sold in packets labelled \"polenta\" in Australia, Note 1))","1 1/2 cups flour (plain / all purpose)","1 tbsp baking powder","1/2 cup white sugar","1/4 tsp salt"],"purpose":"Dry Ingredients"},{"ingredients":["1 cup canned creamed corn","1/2 cup / 125g melted butter (, unsalted)","2 eggs (, lightly whisked)","3/4 cups milk"],"purpose":"Wet Ingredients"},{"ingredients":["1 - 2 tbsp butter (, melted (for greasing & brushing))"],"purpose":"Baking"}]', '[{"description":"Place a 26cm/10\" castiron skillet in the oven and preheat to 220C / 425F while making the batter.","images":[],"step":1},{"description":"Place the Dry Ingredients in a bowl and mix.","images":[],"step":2},{"description":"Place Wet ingredients in a separate bowl and mix until combined.","images":[],"step":3},{"description":"Pour Wet into the Dry ingredients, mix until combined.","images":[],"step":4},{"description":"Take the skillet out of the oven. Add the 1 tbsp of butter and swirl it around to coat the base and halfway up the sides (or use a brush to do this)","images":[],"step":5},{"description":"Pour the batter in, smooth surface.","images":[],"step":6},{"description":"Turn oven down to 190°C/375°F, then bake for 25 to 30 minutes, or until the top is light golden brown and a skewer inserted into the middle comes out clean (or when you poke the top, it springs back).","duration":27.5,"images":[],"step":7},{"description":"Cool 15 minutes in the skilet before tunring out onto serving platter or cutting board.","images":[],"step":8},{"description":"Best served warm! It can be served in the skillet or turned out. Serve with butter and honey as well, to take it over the top!","images":[],"step":9}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["American","Southern","Western"],"categories":["breads","easter-sides-warm-hearty","quick-and-easy","side-dishes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f51a6d797f3b', 'en', 'US', 'Garlic Bread', 'Recipe video above. Nothing beats homemade garlic bread!! Takeout will never taste as good because the garlic is not fresh so the preservatives give it a sour flavour. For the ultimate Garlic Bread experience, skip the fancy artisan bread and use an economical French stick / baguette with a softish thin crust instead. And don''t skimp on butter!', 'https://www.recipetineats.com/tachyon/2018/03/Garlic-Bread_9.jpg', 10, 15, 25, 6, '[{"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_butter", "quantity": {"value": 125.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["1 French stick / baguette (, ~ 60cm / 2ft long (Note 1))","125 g / 1 US stick unsalted butter (, softened)","2 tsp fresh garlic (, very finely minced (~3 - 4 cloves, pack the teaspoon))","1/2 tsp cooking salt / kosher salt (halve for table salt, +50% for flakes)","2 tsp finely chopped parsley (optional)"]}]', '[{"description":"Preheat oven to 200C/390F.","images":[],"step":1},{"description":"Cut the French stick in half. Then cut the bread almost all the way through into 2cm / 4/5\" thick slices.","images":[],"step":2},{"description":"Mix together the butter, garlic, salt and parsley. Taste to see if it''s salty / garlicky enough for your taste (Note 2).","images":[],"step":3},{"description":"Smear garlic butter over cut side of bread (Note 2).","images":[],"step":4},{"description":"Smear remaining butter on the top and sides of the bread.","images":[],"step":5},{"description":"Wrap each bread in foil.","images":[],"step":6},{"description":"Bake for 15 minutes until the crust is crispy (check through foil).","duration":15,"images":[],"step":7},{"description":"Unwrap and serve!","images":[],"step":8}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["breads","dinner-tonight","quick-and-easy","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9b384084002d', 'en', 'US', 'Quick Cheesy Garlic Bread', 'Recipe video above. The quickest and BEST way to make Cheesy Garlic Bread - just drizzle with melted garlic butter, bake, top with cheese then melt. Perfect shape for dunking into soups and stews, or upgrade any meal!', 'https://www.recipetineats.com/tachyon/2019/01/Cheesy-Garlic-Bread_1-Square.jpg', 5, 25, 30, 8, '[{"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_mozzarella", "quantity": {"value": 2.0, "unit": "pack of 125g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 bread loaf approx 30cm/12\" long (Note 1)","100 g / 1/2 cup unsalted butter","1/2 tsp salt","3 garlic cloves (, minced (~ 3 tsp))","2 - 2.5 cups (200 - 250g) mozzarella cheese, grated (Note 2)","Parsley (, for sprinkling (optional))"]}]', '[{"description":"Preheat oven to 160C/320F.","images":[],"step":1},{"description":"Mix butter with garlic and salt.","images":[],"step":2},{"description":"Cut bread in half horizontally.","images":[],"step":3},{"title":"Drizzle with garlic butter all over","description":"don''t miss any patches!","images":[],"step":4},{"description":"Bake 20 minutes until bread is crispy on the edges.","images":[],"step":5},{"description":"Crank oven up to 200C/390F. Top with cheese, bake 7 - 10 min until cheese is melted and bubbly.","images":[],"step":6},{"description":"Sprinkle with parsley if using, cut bread into pieces. Serve immediately as a side for meals, dunking in soups and stews!","images":[],"step":7}]', '["gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["breads","quick-and-easy","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a07e01971d24', 'en', 'US', 'Cheese and Garlic Crack Bread (Pull Apart Bread)', 'Recipe video above. This is garlic bread - on crack! Great to share with a crowd, or as a centre piece for dinner accompanied by a simple salad.', 'https://www.recipetineats.com/tachyon/2018/03/Cheese-Garlic-Crack-Bread_1200px-copy.jpg', 10, 20, 30, 8, '[{"id": "ing_crusty_loaf", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.8, "unit": "pack of 125g"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 666.667, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["1 crusty loaf (, preferably sourdough or Vienna)","1 cup shredded Mozzarella cheese (or other melting cheese)"]},{"ingredients":["100 g / 1 stick (8 tbsp) unsalted butter (, softened)","2 large garlic cloves (, minced)","3/4 tsp salt","1 tbsp fresh parsley (, finely chopped)"],"purpose":"Garlic Butter"}]', '[{"description":"Preheat the oven to 180C/350F.","images":[],"step":1},{"description":"Combine butter, garlic and salt in a heatproof bowl and melt in the microwave. Stir through parsley.","images":[],"step":2},{"description":"Cut the bread on a diagonal into 2cm/1\" diamonds but do not cut all the way through the bread.","images":[],"step":3},{"description":"Use your fingers or a knife to pry open each crack and drizzle in a teaspoon of butter and stuff in a pinch of cheese. This might sound like a bit of an effort, but I promise you it is worth it! You don''t need to be super neat, it''s nice to have some of the butter drizzled over the crust.","images":[],"step":4},{"description":"Brush surface with remaining butter.","images":[],"step":5},{"description":"Wrap with foil and bake for 20 minutes until the cheese has mostly melted, then unwrap and bake for 5 - 10 minutes more to make the bread nice and crusty.","duration":20,"images":[],"step":6},{"description":"Serve immediately. (See note 1 for best make ahead methods)","images":[],"step":7}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["snack"],"cuisine":[],"categories":["breads","iconic-dishes","most-popular","quick-and-easy","side-dishes","super-bowl-party-food","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8aa7d98d54bf', 'en', 'US', 'Cornbread Muffins', 'Recipe video above. These muffins are so tasty and moist that you don''t even need butter for them, just eat them plain! I especially like to serve these as a side to Chili Con Carne, and of course they make an appearance for any Southern meals I make! Can also be made in a skillet.', 'https://www.recipetineats.com/tachyon/2014/10/Cornbread-Muffins_9.jpg', 10, 20, 30, 12, '[{"id": "ing_butter", "quantity": {"value": 0.5, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_corn", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_flour", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.1, "unit": "tub of 150g"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 0.5, "unit": "block of 250g"}}]', '[{"ingredients":["1/2 cup / 125 ml / 115 g butter (, melted unsalted)","2 eggs","3/4 cup / 185 ml milk (, any fat %)","1 CUP canned creamed corn (NOT 1 CAN!!!)"],"purpose":"Wet Ingredients"},{"ingredients":["3/4 cup yellow cornmeal (sold in packets labelled \"polenta\" in Australia) (Note 1)","1 1/2 cups (225g) flour (plain/all purpose)","1 tbsp baking powder","1/2 cup (110g) white sugar (can reduce to 1/4 cup)","1/4 tsp salt"],"purpose":"Dry Ingredients"},{"ingredients":["Extra melted butter (for greasing and brushing)"],"purpose":"Baking:"}]', '[{"description":"Preheat oven to 180C/350F. Brush a 12 hole standard muffin tin with melted butter.","images":[],"step":1},{"description":"Combine Dry ingredients in a bowl and give them a quick stir to combine.","images":[],"step":2},{"description":"Whisk Wet ingredients in a bowl until combined.","images":[],"step":3},{"description":"Pour Wet into Dry ingredients. Mix until combined.","images":[],"step":4},{"title":"Spoon the batter into the greased muffin tray","description":"use it all up, fill the holes right up!","images":[],"step":5},{"description":"Bake in the oven for 20 minutes or until the top is golden brown.","duration":20,"images":[],"step":6},{"title":"Remove muffin tray from the oven. Optional","description":"Brush tops with melted butter. Cool for 5 minutes then remove muffins onto a rack.","duration":5,"images":[],"step":7}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Southern"],"categories":["breads","dinner-tonight","easter-brunch-recipes","easter-sides-warm-hearty","most-popular","muffin-recipes","quick-and-easy","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ccb1a3d6c607', 'en', 'US', 'Cheesy Zucchini Bread', 'Recipe video above. Ultra moist, cheesy quick bread with a subtle zucchini flavour even though it''s jam packed with 2 large zucchinis! The zucchini keeps this bread beautifully moist - you''ll happily scoff this down even without slathering it with butter. (PS Zucchini is known as courgettes in some countries :) )', 'https://www.recipetineats.com/tachyon/2018/01/Zucchini-Cheese-Bread_8.jpg', 15, 50, 65, 8, '[{"id": "ing_zucchini", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 8.0, "unit": "block of 250g"}}, {"id": "ing_milk", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 0.25, "unit": "block of 250g"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 2.0, "unit": "pack of 3 heads"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 0.338, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.067, "unit": "tub of 150g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.013, "unit": "tub of 200g"}}]', '[{"ingredients":["2 cups grated zucchini (, packed (2 medium zucchinis, 380g / 13 oz grated))","3/4 tsp salt","8 slices Swiss cheese (200g / 6.5 oz) (Note 1)"],"purpose":"Zucchini and Cheese:"},{"ingredients":["1 1/4 cups / 315 ml milk (any, I use low fat)","1/4 cup / 45 g melted butter (, unsalted)","2 tbsp canola oil (or vegetable or other neutral flavoured oil)","2 eggs","2 small garlic cloves (, crushed)","1 tsp white vinegar"],"purpose":"Wet Ingredients:"},{"ingredients":["2 1/4 cups / 335g plain / all purpose flour","2 tsp baking powder (Note 2)","1/2 tsp baking soda (bi-carb) (Note 2)","1/2 tsp salt"],"purpose":"Dry Ingredients:"}]', '[{"description":"Use a standard box grater to grate the zucchini. Measure out 2 cups, place in bowl, sprinkle with salt, use fingers to disperse. Leave for 20 minutes.","duration":20,"images":[],"step":1},{"description":"Squeeze handfuls to remove excess water and place zucchini in a bowl. Set aside.","images":[],"step":2},{"description":"Preheat oven to 180°C / 350°F (all oven types).","images":[],"step":3},{"description":"Butter and line a loaf pan (Note 3)","images":[],"step":4},{"description":"Place Dry ingredients in a bowl. Whisk to combine.","images":[],"step":5},{"description":"Place Wet Ingredients in a bowl. Whisk to combine.","images":[],"step":6},{"description":"Make a well in the centre of the Dry ingredients. Pour in Wet. Mix quickly until flour is incorporated (Note 4).","images":[],"step":7},{"description":"Quickly stir through zucchini.","images":[],"step":8},{"description":"Spread 1/3 of the batter in the loaf pan. Top with 4 slices of cheese.","images":[],"step":9},{"description":"Spread with batter, top with 4 slices of cheese, then finish with remaining batter. Smooth top.","images":[],"step":10},{"description":"Bake for 50 minutes or until a skewer inserted into the centre comes out clean.","duration":50,"images":[],"step":11},{"title":"Optional","description":"Brush top with a bit of melted butter.","images":[],"step":12},{"description":"Cool in the pan for 10 minutes then transfer to rack to cool. Cool for at least 20 minutes before slicing.","duration":10,"images":[],"step":13},{"description":"Store in a container (Note 5 for humid weather warning!)","images":[],"step":14}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["breads","easter-brunch-recipes","easter-sides-warm-hearty","quick-and-easy","side-dishes","vegetarian-recipes","zucchini-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_dc343de04a3b', 'en', 'US', 'Easy Soft Flatbread (No Yeast)', 'Recipe video above. The dough for this recipe is ridiculously easy to make with only a minute or two of kneading. The bread is soft and pliable so it''s perfect for using as a wrap, stuffed with whatever takes your fancy. It''s also a great make ahead recipe - the dough keeps for around 3 days. See NOTES for substitutions, including using GLUTEN FREE flour. 30 minute resting time. Recipe VIDEO below.', 'https://www.recipetineats.com/tachyon/2014/05/Easy-Soft-Flatbread_7.jpg', 5, 10, 45, 6, '[{"id": "ing_flour", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 3.5, "unit": "block of 250g"}}, {"id": "ing_milk", "quantity": {"value": 0.188, "unit": "L"}}]', '[{"ingredients":["2 cups plain flour (all purpose flour) ((level cups, unsifted, not packed), + keep 1/4 cup extra for dusting & adjusting dough)","1/2 tsp salt","3 1/2 tbsp / 50g unsalted butter (1.75 oz)","3/4 cup milk"]}]', '[{"title":"Melt butter in milk","description":"Combine butter and milk and heat until butter is just melted - on stove or in microwave.","images":[],"step":1},{"title":"Combine Dry","description":"Combine 2 cups flour, salt, butter and milk in a bowl.","images":[],"step":2},{"title":"Knead 2 minutes","description":"Sprinkle work surface with flour then knead for a few minutes until it is smooth - it doesn''t need much kneading. Add extra flour if the dough is too sticky.","images":[],"step":3},{"title":"Rest 30 minutes","description":"Wrap with cling wrap and rest at room temperature for 30 minutes or so.","duration":30,"images":[],"step":4},{"title":"Roll into rounds","description":"Dust bench top with flour, cut dough into 6 pieces, roll into balls, then roll out into 20cm / 8\" rounds, 2 - 3 mm thick.","images":[],"step":5},{"title":"Heat pan","description":"Heat a non stick pan over high heat (no oil). (Note 1)","images":[],"step":6},{"title":"Cook","description":"Place one flatbread in the pan, cook for around 1- 1 1/2 minutes - it should puff up dramatically. Once the underside has nice golden patches on it, flip and cook the other side for 45 seconds to 1 minute until the underside has golden spots and it puffs up again.","duration":0.75,"images":[],"step":7},{"title":"Keep wrapped in tea towel","description":"Stack the cooked bread and keep wrapped with a tea towel - the moisture helps soften the surface, making them even more pliable. Continue to cook with remaining pieces.","images":[],"step":8},{"title":"Brush with butter or oil (optional)","description":"Brush or spray bread with olive oil or melted butter, for a more luxurious finish. Or even with melted butter mixed with minced garlic for a garlic butter version!","images":[],"step":9}]', '["gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Greek","Mediterranean"],"categories":["breads","breakfast-recipes","coronavirus-food","cuisines","middle-eastern-recipes","most-popular","quick-and-easy","side-dishes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_19553019da5d', 'en', 'US', 'Zucchini Slice', 'Recipe video above. This is how I make Australia''s favourite savoury slice. It is a cross between a frittata, quiche and muffin. Great breakfast, lunch or snack, it''s high in protein, veggie quota plus of course cheese!Most recipes just stir raw chopped onion and uncooked bacon into the egg mixture. But I''m not a fan of raw onion bits, so I grate it instead - the shredded onion cooks through perfectly in the oven. As for the bacon, it''s gotta be sautéed in the oil! Not only does it make the bacon yummier, the oil gets bacon flavour which is then mixed into the batter to make sure the slice doesn''t dry out. Enjoy this warm or cold, great either way!UPDATE: To make it gluten-free, use GF flour. To make it lower-carb, replace the self raising flour with 1 1/4 cups almond meal and 1 teaspoon baking powder.', 'https://www.recipetineats.com/tachyon/2026/04/Zucchini-Slice_9.jpg', 15, 40, 70, 12, '[{"id": "ing_zucchini", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_bacon", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_egg", "quantity": {"value": 416.667, "unit": "carton of 12"}}, {"id": "ing_flour", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}]', '[{"ingredients":["400 g / 14 oz zucchini (2 medium), grated using box grater, excess water squeezed out using hands (about 4 cups grated)","1 brown onion (, peeled, grated using box grater (including all juices))","1/4 cup extra virgin olive oil","200g / 7oz streaky bacon (, chopped into 1cm/0.4\" squares)","1 garlic clove (, finely minced using a garlic press)","5 large eggs (~50-55g/2oz each)","1 cup self-raising flour (Note 1 & Note 2 for low-carb GF option)","1 1/2 cups (tightly packed) cheddar or tasty cheese (, shredded (packet shredded ok))"]}]', '[{"description":"Sauté bacon in the oil, add garlic towards end. Whisk eggs, whisk in flour until lump free. Mix in everything else with wooden spoon. Spread in 30 x 20 cm (12 x 8\") lined pan, sprinkle with cheese and bacon, bake 35 min.","images":[],"step":1},{"description":"Preheat oven to 180°C/350°F (160°C fan-forced).","images":[],"step":2},{"description":"Crumple a sheet of baking paper in your hands then place in a 30 x 20 x 3cm (12 x 8\") lamington pan (or thereabouts) with overhang for lifting the slice out. No need to grease the pan - the mixture will weigh the paper in place.","images":[],"step":3},{"description":"Set aside a little bit of cheese and bacon to sprinkle the surface.","images":[],"step":4},{"title":"Sauté bacon","description":"Heat the oil in a non-stick pan over medium high heat. Add the remaining bacon and stir for 2 minutes or until very light golden. Add the garlic and stir for just 10 seconds, then remove from the stove and set the pan aside to cool slightly.","duration":2,"images":[],"step":5},{"title":"Make batter","description":"In a large bowl, whisk the eggs, then whisk in the flour until lump free. Add the zucchini, onion (including all grating juices), oil and bacon from the pan and cheese. Switch to a wooden spoon and mix until combined.","images":[],"step":6},{"description":"Pour into the lined pan, then push the mixture into the corners and smooth the surface. Sprinkle with reserved cheese and raw bacon.","images":[],"step":7},{"description":"Bake for 35 minutes, rotating at the 20 minute mark, or until the top is golden and a skewer inserted into the middle comes out clean.","duration":35,"images":[],"step":8},{"description":"Cool in the pan for 10 minutes then lift out using the overhang paper. Cool for another 10 minutes before slicing. Enjoy warm or at room temperature!","duration":10,"images":[],"step":9}]', '["egg","gluten","milk"]', '["keto_friendly","low_calorie"]', '{"mealType":["breakfast","snack"],"cuisine":["Australian","Western"],"categories":["breakfast-recipes","egg-recipes","snacks","zucchini-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bc3510f74721', 'en', 'US', 'JB''s Crêpes', 'Recipe above video. Crêpes are one of the easiest and most loved French dishes. It''s one of the first things I learned how to cook as a kid and every time I make them, it always reminds me of home. Everybody loves them whether you serve them simply or dressed up!', 'https://www.recipetineats.com/tachyon/2025/11/Crepese-1.jpg', 10, 25, 95, 15, '[{"id": "ing_flour", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 250.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 45.0, "unit": "block of 250g"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_chocolate", "quantity": {"value": 1.0, "unit": "block of 100g"}}, {"id": "ing_more_suggestions_listed_in_the_post_see_above", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["1 2/3 cups plain flour / all-purpose flour (, sifted)","3 tbsp caster sugar / superfine sugar (, regular white sugar is fine too)","1/4 tsp cooking salt / kosher salt","3 large eggs (, (55g/2oz each in shell) - fridge cold is fine)","2 cups full fat milk (, but works with lite milk too)","1/3 cup water (Note 1)","2 tbsp vegetable oil or other neutral flavoured oil (Note 1)","45 g (3 tbsp) unsalted butter (, cut into small cubes (for cooking))"]},{"ingredients":["Icing sugar then rolled - simple French home style","Berries, whipped cream, melted chocolate or Nutella, icing sugar - as pictured in the post","More suggestions listed in the post - see above"],"purpose":"Topping suggestions"}]', '[{"description":"Abbreviated recipe","images":[],"step":1},{"description":"Whisk flour, sugar and salt. Add eggs then milk, water, oil and whisk into a smooth batter. Cover and rest for an hour. Cook in a lightly buttered non-stick pan, swirling ¼ cup batter to cover the surface. Cook for 1 minute. Flip, cook for 30 seconds, remove once golden and stack as you go.","duration":1,"images":[],"step":2},{"description":"Make the batter","images":[],"step":3},{"description":"Sift flour into a large mixing bowl. Add sugar and salt, then whisk to combine.","images":[],"step":4},{"description":"Make a well in the centre and add the eggs. Whisk gently and only mix in a bit of the flour. You can’t blend all the flour with just the eggs yet, so just mix in enough to make a thick paste.","images":[],"step":5},{"description":"Gradually add the milk, whisking between each addition to create a smooth batter with no lumps.","images":[],"step":6},{"description":"Whisk in the water and oil until the batter is glossy and pourable. When you dip a spoon in, it should coat the back lightly. Not too thick, not too runny. (Note 1)","images":[],"step":7},{"description":"Cover and rest for 1 hour at room temperature. (Note 2)","images":[],"step":8},{"description":"Cook the crêpes","images":[],"step":9},{"description":"Heat a 24cm / 9.5\" non-stick crêpe pan over medium-high heat (medium if your stove runs hot). If you don’t have one, any good non-stick pan will work, just adjust how much batter you pour in depending on the size, so it spreads nicely without being too thick or thin.","images":[],"step":10},{"description":"Melt about 1/2 tsp butter, then wipe it off with a paper towel, you want just a little of butter left, no visible pools. (Note 3)","images":[],"step":11},{"title":"Pour the batter","description":"Using a ladle, scoop up ¼ cup of batter, lift the pan off the heat, ladle most of the batter into the centre, and immediately swirl the pan so the batter coats the surface in a thin, even layer. Still while swirling, use the rest of the batter to fill up the empty spots before it sets. Tilting quickly gives you uniform crêpes.","images":[],"step":12},{"description":"Cook for 45 seconds to 1 minute until the underside is lightly golden and flip using a long spatula and cook the other side for about 30 seconds. (Note 4 & 5)","duration":0.75,"images":[],"step":13},{"description":"Slide onto a plate, then repeat, adding butter each time.","images":[],"step":14},{"description":"To serve","images":[],"step":15},{"description":"Stack your crêpes as you go, they’ll stay soft and flexible. Serve warm either rolled burrito style with the ends tucked in to hold everything or folded into quarters with your favourite topping! (see ingredients)","images":[],"step":16}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert","snack"],"cuisine":["French"],"categories":["breakfast-recipes","dessert-recipes","jbs-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_84b4aa1107c4', 'en', 'US', 'Pikelets', 'Recipe video above. Growing up in Australia, pikelets were a treat we enjoyed for breakfast or any time of the day! Outside of Australia, you might know these as drop scones, Scottish pancakes or silver dollar pancakes. Quick and easy, you''ll have a pile of these baby pancakes ready to enjoy in less than 20 minutes. Best served warm but lovely even at room temperature.Copious amounts of jam and cream essential. It''s the Aussie way!', 'https://www.recipetineats.com/tachyon/2016/06/Pikelets-51079.jpg', 5, 12, 17, 12, '[{"id": "ing_flour", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.083, "unit": "tub of 150g"}}, {"id": "ing_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.05, "unit": "bottle of 50ml"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_strawberries", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_cream", "quantity": {"value": 0.004, "unit": "carton of 250ml"}}]', '[{"ingredients":["1 1/4 cups plain flour (/ all-purpose flour (Note 1))","2 1/2 tsp baking powder","2 tbsp white sugar","Pinch of salt","1 large egg (50-55g / 2 oz in shell)","3/4 cup milk (full fat best, but any type even non dairy ok)","1/2 tsp vanilla extract (optional but recommended)","2 tsp butter"]},{"ingredients":["Strawberry jam","Whipped cream"],"purpose":"To Serve"}]', '[{"title":"Whisk dry","description":"Whisk the flour, baking powder, salt and sugar in a bowl.","images":[],"step":1},{"title":"Add wet","description":"Make a well in the centre. Add the egg, milk and vanilla, then whisk until it''s almost lump free. The batter should be the consistency like thick honey - looser than tomato sauce, thicker than maple syrup. (Note 2)","images":[],"step":2},{"description":"Melt 1 tsp butter in a non-stick pan over medium high heat (or medium, for strong stoves). Then most of the butter off with a paper towel so there are no visible drops of bubbles of butter (Note 3).","images":[],"step":3},{"description":"Drop ~2 tbsp batter into the pan and coax into 7.5cm/3\" rounds. An ice cream scoop with lever will be your friend here. I cook 4 at a time.","images":[],"step":4},{"description":"Cook until bubbles appear on the surface and once 4 or more of these bubbles pop (1 1/2 minutes), this means they are ready to flip. Flip with confidence! Then cook the other side for 1 minute or until golden.","duration":1,"images":[],"step":5},{"title":"Keep cooking","description":"Remove onto a plate. Cook the next batch (no need to add extra butter until 3rd batch).","images":[],"step":6},{"description":"Serve warm with jam and cream, or butter!","images":[],"step":7}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["breakfast"],"cuisine":["Australia"],"categories":["breakfast-recipes","dessert-recipes","quick-and-easy","snacks"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3e84d5dfe4fa', 'en', 'US', 'Wholesome Cinnamon Breakfast Muffins', 'Recipe video above. Wholesome but don''t taste like cardboard, I love them! A variant of the popular Morning Glory muffins, they''re just sweet enough to be a morning tea treat yet healthy enough to be considered breakfast with only 12 grams of sugar per muffin. Soft moist crumb inside, they stay fresh for 5 days and freeze perfectly!', 'https://www.recipetineats.com/tachyon/2024/08/Cinnamon-breakfast-muffins-morning-glory-muffins_7-1.jpg', 15, 25, 40, 12, '[{"id": "ing_walnuts", "quantity": {"value": 112.5, "unit": "jar"}}, {"id": "ing_carrot", "quantity": {"value": 300.0, "unit": "pack of 1kg"}}, {"id": "ing_apples", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_desiccated_coconut", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_raisins", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_flour", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.044, "unit": "tub of 200g"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 250.0, "unit": "carton of 12"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.167, "unit": "L"}}, {"id": "ing_oranges", "quantity": {"value": 0.037, "unit": "kg"}}]', '[{"ingredients":["3/4 cup walnuts (or other nuts)","2 cups (lightly packed) shredded carrot (, 2 - 3 carrots (use a box grater, I don''t peel))","1 1/4 cups (lightly packed) shredded Granny Smith apple, (including juices (1 apple, keep skin on))","1/2 cup desiccated coconut (finely shredded, unsweetened)","3/4 cup raisins (or sultanas, apricots or other dried fruit)"],"purpose":"Add ins (Note 1 for alternatives):"},{"ingredients":["2 cups wholemeal flour (/ wholewheat flour (or plain/all-purpose flour))","1 3/4 tsp baking soda (bi-carbonate soda) (Note 2)","2 tsp cinnamon powder","1 tsp ground ginger (not critical, Note 3)","1/2 tsp cooking salt / kosher salt"],"purpose":"Dry ingredients:"},{"ingredients":["3/4 cup brown sugar (tightly packed cup)","3 large eggs (, at room temperature (~50g/2 oz each))","2/3 cup olive oil (not extra virgin), or canola oil, liquid coconut oil (Note 4)","1/4 cup orange juice (sub any fruit juice or milk, Note 5)"],"purpose":"Wet ingredients:"}]', '[{"description":"Abbreviated recipe:","images":[],"step":1},{"description":"Toast walnuts 190°C/375°F (170°C fan) 8 minutes. Cool, roughly chop. Whisk dry, whisk wet in separate bowl. Add wet into dry with add-ins, mix, fill oil-sprayed muffin tin. Bake 25 minutes.","images":[],"step":2},{"description":"Preheat the oven to 190°C/375°F (170°C fan-forced).","images":[],"step":3},{"title":"Toast walnuts","description":"Put the walnuts on a tray and toast for 8 minutes. Cool for 5 minutes on the tray then roughly chop into 5mm / 0.2\" pieces.","duration":8,"images":[],"step":4},{"description":"Spray a 12 hole standard muffin tin with oil, or line with muffin cases.","images":[],"step":5},{"title":"Batter","description":"Whisk the dry ingredients in a large bowl. Whisk the wet ingredients until combined in a separate bowl. Pour the wet ingredients and all the add-ins into the Dry Ingredients bowl. Mix with a wooden spoon just until you can no longer see flour, then stop mixing (over-mixed batter = tough muffs!).","images":[],"step":6},{"title":"Divide the mixture between the holes","description":"they will mound above the rim! (See photos in post). A lever ice cream scoop is super useful here. And don''t worry, they won''t overflow, they rise and dome.","images":[],"step":7},{"description":"Bake for 25 minutes or until a skewer inserted into the centre comes out clean.","duration":25,"images":[],"step":8},{"description":"Cool for 5 minutes in the muffin tin, then transfer onto a cooling rack and cool for at least another 5 minutes before grabbing on. Slathering with softened salted butter is encouraged!","duration":5,"images":[],"step":9}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["breakfast","snack"],"cuisine":["Western"],"categories":["breakfast-recipes","cupcakes-and-muffins","muffin-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9bbbfe4c3804', 'en', 'US', 'Homemade sausage patties', 'Recipe video above. This is your favourite pork sausage in patty form. It''s so easy - just pork mince (ground pork) mixed with a spice blend. Great to make ahead and freeze, then cook up on demand.Serve for dinner with garlic rice and steamed green beans tossed with French Dressing. O make burgers! Also great for breakfast with scrambled eggs on toast. (I''d still use ketchup :) )', 'https://www.recipetineats.com/tachyon/2023/09/Homemade-pork-sausage-patties_1.jpg', 10, 10, 20, 8, '[{"id": "ing_pork_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_sage", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_ketchup", "quantity": {"value": 1.0, "unit": "bottle of 500g"}}]', '[{"ingredients":["500g/ 1 lb pork mince (ground pork) (sub chicken, turkey)","1 tsp dried ground sage (secret ingredient! Note 1)","1/2 tsp dried thyme (, crushed with fingers (Note 2))","1 tsp onion powder (sub more garlic powder)","1/2 tsp garlic powder (sub more onion powder)","1 tsp black pepper","3/4 tsp cooking / kosher salt (or 1/2 tsp table salt)","1/2 tsp sugar (optional)"],"purpose":"Sausage patties:"},{"ingredients":["2 tbsp olive oil","Ketchup for serving"],"purpose":"Cooking & serving:"}]', '[{"title":"Make patties","description":"Place sausage pattie ingredients in a bowl and mix well with your hands. Divide into 8 and form 1 cm / 0.4\" thick patties. Make a shallow dent in the middle of the surface - this prevents the patties from doming as they cook.","images":[],"step":1},{"title":"Cook 4 minutes","description":"Heat 1 tablespoon of oil in a large non stick pan over medium high heat. Cook half the patties for 2 minutes on each side until golden. Transfer to a paper towel lined plate. Heat remaining oil and cook remaining patties.","duration":2,"images":[],"step":2},{"description":"Serve with ketchup! (See recipe card intro for serving ideas)","images":[],"step":3}]', '[]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["breakfast","dinner"],"cuisine":["Western"],"categories":["breakfast-recipes","mains","pork","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_222280ad64b8', 'en', 'US', 'Really great waffles', 'Recipe video above. This is a no-fuss waffle batter recipe that makes really great waffles that are delightfully crispy on the outside and delicately soft on the inside. Make them right now, or make the batter the night before for waffles with even softer insides - see Note 1!You need a waffle maker - see note 2 for my thoughts on economical v premium.Makes 9-10 with my good waffle maker (thicker, bigger), 12-14 with my Kmart waffle maker (which I still love!).', 'https://www.recipetineats.com/tachyon/2023/08/Waffles_7.jpg', 10, 15, 145, 10, '[{"id": "ing_flour", "quantity": {"value": 0.338, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.133, "unit": "tub of 150g"}}, {"id": "ing_milk", "quantity": {"value": 0.333, "unit": "L"}}, {"id": "ing_vanilla_essence", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_egg", "quantity": {"value": 333.333, "unit": "carton of 12"}}, {"id": "ing_butter", "quantity": {"value": 150.0, "unit": "block of 250g"}}, {"id": "ing_maple_syrup", "quantity": {"value": 1.0, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_strawberries", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}]', '[{"ingredients":["2 1/4 cup flour (, plain / all purpose)","2 1/2 tbsp caster sugar / superfine sugar (sub granulated / ordinary sugar)","Pinch cooking / kosher salt","4 tsp baking powder","1 1/3 cup milk (, full fat, slightly warmed (not piping hot))","1/2 tsp vanilla essence","4 large eggs","150g / 11 tbsp unsalted butter (, melted and slightly cooled (not piping hot))"],"purpose":"Waffle batter:"},{"ingredients":["Butter (, softened (strongly recommended!))","Maple syrup ((strongly recommended!), or honey)","Icing sugar / powdered sugar (, for dusting)","Strawberries, other fruit"],"purpose":"Topping options:"}]', '[{"title":"Whisk dry","description":"Place the flour, sugar, baking powder and salt in a large mixing bowl. Whisk to mix.","images":[],"step":1},{"title":"Whisk in wet","description":"Add milk, eggs and vanilla. Whisk to combine. Add melted butter then whisk until lump free. The batter should be pourable but thick - slightly thinner than pancakes.","images":[],"step":2},{"title":"Recommended resting (Note 1)","description":"Cover then refrigerate overnight, or for at least 2 hours. Softer insides, better flavour. Else, proceed immediately with cooking.","images":[],"step":3},{"description":"Preheat a waffle maker (Note 2, inc setting options). A non stick one will not need oil, plus there is butter in the batter.","images":[],"step":4},{"title":"Cooking","description":"Use a ladle to pour batter in to just cover the iron. Don''t get greedy - it will leak out the sides! Cook until golden and crisp - my good waffle iron takes 3 1/2 minutes, my Kmart one takes 6 minutes.","images":[],"step":5},{"title":"Serving","description":"Transfer onto plates and serve as you go, with desired toppings. Or, put on a rack and keep warm in a preheated 70°C/150°F oven while you continue cooking!","images":[],"step":6}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["breakfast"],"cuisine":["Western"],"categories":["breakfast-recipes","dessert-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bfe8ff3ac9ee', 'en', 'US', 'Ham and cheese omelette', 'Recipe video above. This "scrambled egg" method is a great, easy way to make omelettes that are soft and custardy inside without worries about raw egg in the middle. Essentially, you make soft scrambled eggs, then spread (like jam) across the pan so it sets into an omelette. Fill, fold, serve!Makes 1 omelette, a filling meal for one.', 'https://www.recipetineats.com/tachyon/2023/06/Ham-and-cheese-omelette_1.jpg', 5, 5, 10, 1, '[{"id": "ing_egg", "quantity": {"value": 250.0, "unit": "carton of 12"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.06, "unit": "carton of 250ml"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_ham", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 0.333, "unit": "block of 250g"}}, {"id": "ing_chive", "quantity": {"value": 0.002, "unit": "kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_toast", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["3 large eggs (, ~55g/2oz each (fridge cold fine))","Pinch of salt (that''s all you need)","1 tbsp cream (or milk), optional (Note 1)"]},{"ingredients":["1 tbsp/ 15 g unsalted butter (or 2 tsp extra virgin olive oil)","1/3 cup chopped ham (I use store bought, Note 2)","1/3 - 1/2 cup shredded colby cheese (, use box grater (or cheddar, tasty, gruyere, Monterey Jack - Note 3))"],"purpose":"Cooking / add-ins"},{"ingredients":["1 stem chive (, finely chopped)","Garlic butter roasted mushrooms","Roasted cherry tomatoes (on vine, Note 4)","Toast"],"purpose":"Serving (optional, pictured)"}]', '[{"title":"Heat control","description":"If at any stage your omelette is cooking too fast, remove the pan off the stove to let it cool down and lower the heat.","images":[],"step":1},{"description":"Whisk the eggs, salt and cream in a bowl for 10 seconds until slightly foamy.","duration":0.16666666666666666,"images":[],"step":2},{"title":"Warm ham","description":"Melt 1/3 of the butter in a 24cm/9.5\" non-stick pan (or thereabouts, Note 5) over medium heat until foamy. Swirl/spread to coat the base, then cook ham using a rubber spatula for 90 seconds until warmed through. Remove into bowl.","duration":1.5,"images":[],"step":3},{"title":"Semi-scramble eggs","description":"Melt and swirl remaining butter in the pan. Give the eggs a quick whisk then pour into the pan. Leave for 15 seconds or until the very edges set, then do long leisurely strokes around and across the pan to scrape up cooked egg and let the raw egg run onto the base. Continue for 30 seconds or so until the egg is partially cooked. GOAL: wet enough to spread like jam, but not so wet that the egg runs when you tilt the pan.","duration":0.25,"images":[],"step":4},{"description":"Spread the egg evenly across the pan (no need to be meticulous). Top half with cheese, then ham. (By this time, the omelette should be almost cooked through but still shiny/custardy on the surface).","images":[],"step":5},{"description":"Loosen the naked side then fold over using 2 rubber spatulas. Leave in the pan for another 30 seconds to melt the cheese and finish cooking inside.","images":[],"step":6},{"title":"Serve","description":"Slide or flip onto a plate and serve! Sprinkle with chives if desired.","images":[],"step":7}]', '["egg","milk"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["breakfast"],"cuisine":["Western"],"categories":["breakfast-recipes","egg-recipes","leftover-ham-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9b9d4185b788', 'en', 'US', 'Fluffy Ricotta Pancakes', 'Recipe video above. Ricotta pancakes are a step up from plain ones because they are extra soft and fluffy inside. Made famous by Australia''s very own Bill Granger, a signature dish at his popular bistro Bills.Stove control is key, because these are thicker than standard pancakes. Heat too low, and the pancakes will be raw batter inside or won''t rise enough. Too high, and the pancakes will burn before the inside is cooked. Aim for 3 minutes and golden brown surfaces. It''s fine to go over (they will still be moist inside) but if you go under 2 1/2 minutes, they will be raw inside.9 - 10 pancakes (about 13cm/5" in diameter).', 'https://www.recipetineats.com/tachyon/2016/03/Ricotta-pancakes_0-1.jpg', 15, 30, 45, 9, '[{"id": "ing_ricotta", "quantity": {"value": 0.45, "unit": "tub of 250g"}}, {"id": "ing_egg", "quantity": {"value": 250.0, "unit": "carton of 12"}}, {"id": "ing_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.05, "unit": "bottle of 50ml"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.067, "unit": "tub of 150g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.006, "unit": "tub of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_strawberries", "quantity": {"value": 0.907, "unit": "punnet of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_maple_syrup", "quantity": {"value": 1.0, "unit": "bottle of 250ml"}}]', '[{"ingredients":["3/4 cup ricotta cheese (, full fat (Note 1))","3 large eggs (55g/2oz each)","3 tbsp caster sugar (superfine sugar)","3/4 cup milk (full fat best but low fat fine)","1/2 tsp vanilla extract","1 tsp white vinegar (or other clear or clear-ish vinegar, Note 2)"],"purpose":"Wet ingredients"},{"ingredients":["1 1/3 cups plain/all-purpose flour","2 tsp baking powder","1/4 tsp baking soda (bi0carb) (or 3/4 tsp extra baking powder (Note 3))","Pinch of salt"],"purpose":"Dry ingredients"},{"ingredients":["1 tbsp (15g) butter (, melted (Note 4))","8 oz / 250g strawberries (, halved or quartered)","1 tbsp caster/superfine sugar","Maple syrup (, for dousing)"],"purpose":"Serving/cooking"}]', '[{"title":"Whisk wet","description":"Place the Wet ingredients in a bowl and whisk vigorously to combine. You should have little ricotta curd bits in it, but you don''t want giant ricotta clumps.","images":[],"step":1},{"title":"Add dry","description":"Scatter the Dry ingredients across the surface then whisk until combined. The batter is a little thicker than standard pancake batter.","images":[],"step":2},{"title":"Lightly butter pan","description":"Heat a non-stick pan over medium heat until hot (I use 2 pans). Brush lightly with melted butter (or melt a bit then wipe off excess with paper towels - Note 4).","images":[],"step":3},{"title":"Batter","description":"Pour in 1/4 cup batter - it should just about spread evenly into a round but may need a bit of coaxing. (I use an ice cream scoop - Note 5)","images":[],"step":4},{"title":"Cook 3 minutes","description":"Cook the first side for 1 1/2 minutes or until golden brown (turn heat down if browning too fast). Flip then cook the other side for 1 1/2 minutes or until golden. Remove onto a plate.","images":[],"step":5},{"title":"Cook remaining","description":"If your non-stick coating is good, you won''t need more butter though a very light brush of melted butter every 2nd or 3rd pancake won''t hurt. Continue cooking, lowering the heat as you go as the pan gets hotter. You should get 9 to 10 in total. Keep cooked pancakes stacked so they keep each other warm (or use a low 50C/125F oven).","images":[],"step":6},{"description":"Serve ricotta pancakes with macerated strawberries (below), softened butter and copious amounts of maple syrup!","images":[],"step":7},{"description":"Macerated strawberries (optional)","images":[],"step":8},{"description":"Toss together strawberries and sugar in a small bowl. Set aside for 20 minutes to allow them to sweat and soften slightly. (Even overnight in fridge is fine.) Serve on pancakes!","duration":20,"images":[],"step":9}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["breakfast"],"cuisine":["Western"],"categories":["breakfast-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bb2d3376b6e5', 'en', 'US', 'Baked Vegetable Frittata', 'Recipe video above. Healthy, delicous protein packed frittata that''s great for making ahead. Think - breakfast on the run, picnics, or lunch on demand. Keeps 5 days in the fridge or months in the freezer!Soft and custardy on the inside, flavoured with a sprinkle of cheese and feta, studded with Roasted Herb Garlic Vegetables. SWITCH the veggies with 5 - 7 CUPS OF ANYTHING you want: cooked chicken, flaked tuna or salmon (fresh or canned), other vegetables, antipasto type things. See post for more ideas!', 'https://www.recipetineats.com/tachyon/2019/03/Baked-Frittata_1.jpg', 15, 70, 85, 8, '[{"id": "ing_egg", "quantity": {"value": 10.0, "unit": "carton of 12"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_feta_cheese", "quantity": {"value": 100.0, "unit": "block of 200g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_mixed_herbs", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_pumpkin", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_zucchini", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}]', '[{"ingredients":["10 eggs","3/4 cups cream or milk (, full fat best (Note 1))","1/2 tsp salt and pepper, each","1 1/2 cups shredded cheese (cheddar, tasty, or other of choice)","100g/3 oz mushroom, sliced (I used 1 large, optional)","100g / 3oz feta (, crumbled (optional))"]},{"ingredients":["2 tbsp olive oil","2 garlic cloves, minced","3/4 tsp salt","1/2 tsp pepper","1.5 tsp mixed dried herbs (or use any of choice)","350g / 12oz pumpkin (, butternut or sweet potato, 1.7cm / 0.7\" cubes)","2 zucchinis (, sliced 1.25 / 0.5\" thick rounds)","1 large red capsicum ((bell pepper), sliced)"],"purpose":"Herb Garlic Roasted Vegetables (Note 2 for switches):"}]', '[{"description":"Roasted Vegetables:","images":[],"step":1},{"description":"Preheat oven to 220°C/430°F (200°C fan).","images":[],"step":2},{"description":"Toss vegetables on tray with oil, garlic, herbs, salt and pepper. Spread out.","images":[],"step":3},{"description":"Roast 25 minutes, undisturbed (no flipping). Remove and cool for at least 5 minutes before using.","images":[],"step":4},{"description":"Baked Frittata:","images":[],"step":5},{"description":"Lower oven to 180°C/350°F (160°C fan).","images":[],"step":6},{"title":"Grease & line pan","description":"Spray a 19 x 30cm / 8 x 10\" rectangle or 22 cm / 9\" square pan lightly with oil, then line with parchment paper with overhang. (Note 3)","images":[],"step":7},{"title":"Egg mixture","description":"Whisk eggs, cream, salt and pepper in a bowl.","images":[],"step":8},{"title":"Assemble","description":"Spread 2/3 of the vegetables in the prepared pan. Pour over egg mixture, sprinkle with cheese, then top with remaining vegetables.","images":[],"step":9},{"title":"Topping","description":"Top with crumbled feta, then mushrooms. Drizzle mushrooms with a touch of olive oil (makes it brown).","images":[],"step":10},{"title":"Bake","description":"Bake 40 minutes until centre is just set.","images":[],"step":11},{"title":"Rest & serve","description":"Rest frittata 5 minutes in the pan. Use paper overhang to lift out of pan, then slice into squares and serve.","images":[],"step":12},{"title":"Serving later","description":"Cool on rack and remove paper from underneath (otherwise base gets soggy). Cut then refrigerate up to 5 days, or freeze. Reheat in microwave.","images":[],"step":13}]', '["egg","milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["breakfast","lunch"],"cuisine":["Western"],"categories":["breakfast-recipes","dietary","dinner-tonight","easter-brunch-recipes","egg-recipes","gluten-free-recipes","pumpkin","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_fc96705858d5', 'en', 'US', 'Baked Eggs with Mushrooms (Shirred Eggs)', 'Recipe video above. Shirred Eggs are a type of baked eggs, and are a super-simple way to turn the humble egg into an enticing meal for breakfast, lunch or dinner. Eggs are cracked over a bed of garlicky mushroom and spinach in small dishes, topped with a dash cream and parmesan then baked until just-set.Serve for breakfast, brunch, or as a light meal anytime of the day! This makes:- Standard breakfast for 4 people with bread (double up on eggs for more filling option)- Big breakfast for 2 people (make double in larger ramekin)', 'https://www.recipetineats.com/tachyon/2021/08/Baked-Eggs_89.jpg', 5, 20, 25, 4, '[{"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_baby_spinach", "quantity": {"value": 4.0, "unit": "bag of 250g"}}, {"id": "ing_egg", "quantity": {"value": 333.333, "unit": "carton of 12"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_cream", "quantity": {"value": 0.25, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 0.3, "unit": "pack of 200g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.016, "unit": "jar of 40g"}}, {"id": "ing_chives", "quantity": {"value": 0.01, "unit": "kg"}}]', '[{"ingredients":["30g / 2 tbsp unsalted butter","200g / 7oz mushrooms (, sliced thinly (0.3cm / 1/8\"))","2 cloves garlic (, finely minced)","2 tsp fresh thyme leaves","1/4 tsp cooking / kosher salt","1/8 tsp black pepper","4 cups baby spinach"],"purpose":"Mushroom Spinach Filling:"},{"ingredients":["4 large eggs (, fridge cold (Note 1))","Pinch salt and pepper","1/4 cup thickened cream (heavy cream)","4 tbsp parmesan (, freshly grated)","1/8 tsp smoked paprika (optional)","2 tsp chives (, finely chopped (optional))"],"purpose":"Baked Eggs:"}]', '[{"description":"Preheat oven to 200°C / 390°F (180°C fan). Lightly oil or butter four ramekins – 300ml / 10oz (1 1/4 cups).","images":[],"step":1},{"title":"Cook mushrooms","description":"Melt butter in a large skillet over medium high heat. Cook mushrooms until starting to go golden on the edges, 3 minutes. Add garlic, thyme, salt and pepper. Cook for further 1 minute until mushrooms and garlic are golden.","images":[],"step":2},{"title":"Wilt spinach","description":"Add spinach and stir for 30 seconds, just until wilted.","duration":0.5,"images":[],"step":3},{"title":"Fill ramekins","description":"Divide mushroom mixture evenly into the ramekins. Make a slight dent in the middle, crack eggs in (yolk should settle in centre). Sprinkle each egg with pinch of salt and pepper, drizzle with cream, pile on parmesan.","images":[],"step":4},{"title":"Bake: Bake in oven for 12","description":"15 minutes until egg whites are just set and yolks are cooked to your liking (I like runny!). Check it at 12 minutes - hotter ovens, lower walled ramekins etc can make them cook faster. Take out of oven slightly undercooked as egg will keep cooking.","duration":13.5,"images":[],"step":5},{"title":"Paprika","description":"Sprinkle smoked paprika and chives on top, serve immediately with warm bread for dunking!","images":[],"step":6}]', '["egg","milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["breakfast"],"cuisine":["Western"],"categories":["breakfast-recipes","dietary","egg-recipes","low-calorie-recipes","quick-and-easy","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2715a86d008d', 'en', 'US', 'Croque Monsieur (French hot ham and cheese sandwich)', 'Recipe video above. Unapologetically calorific, this is the famous French hot ham and cheese sandwich! If you want to make it the traditional way, do not skimp on cheese or butter, and do not even think about using low fat anything. 😂While it''s thought of as a brunch/breakfast, Croque Monsieur is typically served as lunch in France with a side of fries and simple salad.Truly one of the greatest sandwiches in the world, one that I say everyone should experience at least once in their lives ….', 'https://www.recipetineats.com/tachyon/2021/04/Croque-Monsieur_0.jpg', 15, 15, 30, 2, '[{"id": "ing_milk", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_butter", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 1.0, "unit": "jar of 50g"}}, {"id": "ing_nutmeg", "quantity": {"value": 0.625, "unit": "jar"}}, {"id": "ing_bread", "quantity": {"value": 0.2, "unit": "loaf"}}, {"id": "ing_gruyere_cheese", "quantity": {"value": 8.0, "unit": "block of 200g"}}, {"id": "ing_ham", "quantity": {"value": 0.12, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.1, "unit": "jar of 200g"}}, {"id": "ing_cheese", "quantity": {"value": 8.0, "unit": "block of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.225, "unit": "pack of 200g"}}]', '[{"ingredients":["1/2 cup milk","1/2 cup cream (pure or heavy / thickened)","1 1/2 tbsp / 25g unsalted butter","1 1/2 tbsp flour (, plain / all-purpose)","1/4 tsp salt (, kosher/cooking salt)","1 pinch white pepper","1/8 tsp nutmeg (, preferably freshly ground)"],"purpose":"Bechamel:"},{"ingredients":["4 slices sourdough bread (, 1.5cm / ⅗\" thick (Note 1))","8 slices Swiss or gruyere cheese (165g / 6 oz, enough for 2 layers a sandwich) (Note 2)","120g / 4 oz ham slices (, preferably smoked)","4 tsp Dijon mustard","30g / 2 tbsp unsalted butter"],"purpose":"Sandwich:"},{"ingredients":["1/2 cup gruyere cheese (, shredded (packed cup, Note 2))","3 tbsp parmesan (, finely shredded (Note 2))"],"purpose":"Topping:"}]', '[{"description":"Preheat oven to 200°C/390°F (180°C fan).","images":[],"step":1},{"description":"Béchamel sauce:","images":[],"step":2},{"title":"Heat milk and cream","description":"Place milk and cream in a saucepan over medium heat. Heat until steaming, but don''t let it boil. Set aside.","images":[],"step":3},{"title":"Make roux","description":"Melt butter in a separate small saucepan over medium heat, then turn the heat down to low. Add flour and cook, stirring almost constantly, for 3 minutes. Don''t let it brown.","duration":3,"images":[],"step":4},{"title":"Add hot milk","description":"While stirring, add half the milk. Once incorporated into the roux, mix in remaining milk, nutmeg, salt and pepper.","images":[],"step":5},{"title":"Thicken","description":"Mix for 30 seconds to a minute or until it thickens into a spreadable and soft butter-like consistency (ie. not runny). If you have lumps, whisk until gone. Remove from heat (it is OK if it cools).","duration":0.5,"images":[],"step":6},{"description":"Assemble for pan frying:","images":[],"step":7},{"title":"Spread with Bechamel","description":"Spread half the béchamel over the 4 slices of bread, as though you are buttering them to make normal sandwiches! (Reserve half the béchamel for topping)","images":[],"step":8},{"title":"Cheese + Dijon","description":"Top two pieces of bread with 2 slices of gruyere or Swiss cheese each (fold as needed to make them fit). Then spread the cheese with half the Dijon Mustard (this might sound weird, but see in post for why we do this!).","images":[],"step":9},{"title":"Ham + Dijon","description":"Top with ham, then spread ham with remaining Dijon mustard.","images":[],"step":10},{"description":"Top each of the two slices with 2 more slices of cheese (again, folding as needed), then close sandwiches with the other slices.","images":[],"step":11},{"description":"Melt butter in a skillet over medium to medium-high heat. Place sandwiches in the skillet, and cook for 2 minutes, pressing down lightly with an egg flip or spatula, until a deep golden brown.","duration":2,"images":[],"step":12},{"description":"Turn and cook the other side until golden brown. Transfer to a baking tray.","images":[],"step":13},{"description":"Bake then broil:","images":[],"step":14},{"title":"Topping","description":"Slather remaining béchamel thickly on the upper pieces of bread. Sprinkle with Gruyere, then parmesan.","images":[],"step":15},{"title":"Bake and broil","description":"Bake 15 minutes, then switch to the grill/broiler for 3 minutes and grill until the top is golden and bubbling.","duration":3,"images":[],"step":16},{"description":"Serve:","images":[],"step":17},{"description":"Immediately transfer to warmed serving plates, with knives and fork for serving (it''s too messy to eat with hands.) For a traditional French bistro experience, add a side of fries and leafy greens lightly dressed in French Dressing or a basic vinaigrette. Devour and weep with joy! (Over the sandwich that is, not the salad!)","images":[],"step":18}]', '["gluten","milk","mustard"]', '["high_protein"]', '{"mealType":["breakfast","lunch"],"cuisine":["French"],"categories":["breakfast-recipes","easter-brunch-recipes","leftover-ham-recipes","sandwiches-and-sliders"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_72c849583849', 'en', 'US', 'Egg White Omelette (Fluffy, Soufflé-style)', 'Recipe video above. If the words "Egg White Omelette" conjures visions of a bland mat of white rubber, be prepared to have your mind blown. Because this omelette is Amazing - with a capital "A"!It''s a very worthy way to use up leftover egg whites after making something using egg yolks.I''m not going to lie, you might not quite nail it first go. It might not be as fluffy, or it might not look as neat. But it doesn''t matter. You are going to enjoy every bite of this souffle-like omelette, with a flavour-loaded filling.And next time, you will nail it! : )', 'https://www.recipetineats.com/tachyon/2021/03/Egg-White-Omelette-in-skillet_0.jpg', 7, 3, 10, 1, '[{"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_parmesan", "quantity": {"value": 0.05, "unit": "pack of 200g"}}, {"id": "ing_chives", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 10.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 1.0, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_asparagus", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_paper_thin_slices_prosciutto", "quantity": {"value": 2.0, "unit": "kg"}}]', '[{"ingredients":["3 egg whites (Note 1)"]},{"ingredients":["10g/ 1/3 oz pecorino (, finely shredded (sub parmesan, Note 2))","1/2 tsp chives (, finely chopped + extra for garnish)","10g/ 2 tsp unsalted butter","1/8 tsp sea salt","1 small pinch white pepper"],"purpose":"Omelette"},{"ingredients":["1 tsp olive oil","1/2 cup asparagus (, finely sliced on an angle (~2 spears, 25g/1 oz))","2 paper-thin slices prosciutto (20g/ 2/3oz)"],"purpose":"Filling"}]', '[{"description":"Pre-heat oven to 200°C/390°F (180°C fan).","images":[],"step":1},{"description":"First, separate eggs and place whites in a bowl. Reserve yolks for another use.","images":[],"step":2},{"title":"Cook asparagus and prosciutto","description":"Heat olive oil in a 20cm/8\" oven-proof, non-stick pan over medium heat. Add asparagus and cook until tender. When almost done, add prosciutto and stir for 30 seconds – just enough to warm through but not crisp. Transfer to a bowl and set aside.","duration":0.5,"images":[],"step":3},{"title":"Melt butter","description":"Add butter into the same skillet and place over low heat. The butter should melt and be bubbling gently (ie. hot, but not smoking) when the egg whites are ready to pour in. (Note 3)","images":[],"step":4},{"description":"Whisk whites until it''s just opaque, fluffy and creamy. Do not take it to \"stiff peaks\". It should be a consistency so you can draw a figure 8 on the surface and it stays there without sinking. You do not want to be able to do \"elf hats\" (see in post for photo), that''s too stiff. (Whisking time for me: 90 seconds by hand, 30 seconds on Speed 4 electric beater).","images":[],"step":5},{"description":"Add chives, salt and pepper. Whisk a few times just to mix through.","images":[],"step":6},{"description":"Immediately pour egg whites into hot skillet, spread with a spatula to cover surface. Stir for 10 to 12 seconds until the whites start to set on the base.","duration":0.18333333333333332,"images":[],"step":7},{"description":"Remove from stove, then lightly tap the pan 5 times on the stove grates or a heat mat to remove bubbles from the base.","images":[],"step":8},{"description":"Sprinkle asparagus, prosciutto and pecorino on half the omelette (the half opposite the handle).","images":[],"step":9},{"description":"Transfer to oven for 2 minutes.","duration":2,"images":[],"step":10},{"description":"Remove from oven. Run rubber spatula around edges and then under the side without the filling, carefully fold omelette in half to cover the filling.","images":[],"step":11},{"description":"Press the omelette''s rounded edge against the side of the pan for 30 seconds to seal the edge.","duration":0.5,"images":[],"step":12},{"title":"Turn out onto plate","description":"Hold a plate at a 45 degree angle. Then flip the omelette out onto the plate so it lands upside down, ie. pan-contact face up (see video for demo).","images":[],"step":13},{"description":"Garnish with chives. Serve immediately!","images":[],"step":14}]', '["egg","milk"]', '["gluten_free","high_protein","keto_friendly","low_calorie"]', '{"mealType":["breakfast"],"cuisine":["Western"],"categories":["breakfast-recipes","dietary","egg-recipes","egg-white-recipes","gluten-free-recipes","low-calorie-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_107bdcc1d63f', 'en', 'US', 'Cheese & Bacon Breakfast Strata Cake (Breakfast Casserole!)', 'Recipe video above. Strata, breakfast casserole, savoury French toast bake or savoury bread pudding. It doesn''t matter what you call this, it''s totally delish and can be made ahead, so it''s great for feeding a crowd! It tastes like a cross between a quiche, French toast and an omelette.Excellent use of leftover bread, and also to make less bacon stretch further. Also customisable - imagine all the add in possibilites! See in post for some ideas.', 'https://www.recipetineats.com/tachyon/2020/10/Cheese-Bacon-Bread-Bake-07.jpg', 15, 30, 45, 8, '[{"id": "ing_bacon", "quantity": {"value": 1.5, "unit": "pack of 200g"}}, {"id": "ing_egg", "quantity": {"value": 500.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 1.312, "unit": "loaf"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["300g / 10 oz bacon (, diced (or ham))","6 large eggs","1 1/4 cups milk (full cream or low fat)","1/4 tsp salt","Black pepper","7 cups (packed) any plain bread (I use baguettes) (, cut into 2 cm / 1 inch cubes (preferably slightly stale, Note 1))","2 cups cheese (, shredded (Note 2))"]},{"ingredients":["parsley (, finely chopped (garnish - optional))"],"purpose":"Optional garnish"}]', '[{"title":"Cook bacon","description":"Heat a large non-stick frying pan over high heat. (Use a bit of oil if not using non-stick). Add all but 2 tbsp of bacon (reserve some for topping just before baking), cook until lightly browned. Remove from the pan and drain on a paper towel.","images":[],"step":1},{"title":"Whisk eggs and milk","description":"Whisk the eggs, milk, salt and pepper in a large bowl (or container, if leaving overnight).","images":[],"step":2},{"title":"Soak bread","description":"Add the bread, 1 1/2 cups of the cheese and the cooked bacon to the egg mixture. Mix well. Cover and set aside in the fridge for at least 30 minutes (until all the egg is soaked into the bread) or overnight.","images":[],"step":3},{"description":"To Cook:","images":[],"step":4},{"description":"Preheat oven to 180°C/350°F (all oven types).","images":[],"step":5},{"title":"Grease cake tin","description":"Generously grease a 20cm/8\" springform cake tin with butter (cake pan without loose sides also ok, also see Note 3 re: leakage risk).","images":[],"step":6},{"title":"Fill","description":"Pour the bread mixture into the cake tin, pat down to compress. Scatter with reserved uncooked bacon and remaining 1/2 cup of cheese. Cover loosely with foil.","images":[],"step":7},{"description":"Bake for 25 minutes, then remove the lid and bake for a further 15 - 20 minutes until golden on top and a skewer inserted into the centre comes out clean (no raw egg).","duration":25,"images":[],"step":8},{"title":"Rest & slice","description":"Allow to rest for 5 minutes before removing the springform or turning out. Garnish with parsley if using. Cut into slices to serve. Be civil and eat it on a plate with a fork, or just use your hands!","duration":5,"images":[],"step":9}]', '["egg","gluten","milk"]', '["high_protein","low_calorie"]', '{"mealType":["breakfast"],"cuisine":["Western"],"categories":["breakfast-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a2307c979354', 'en', 'US', 'Eggs Benedict', 'Recipe video above. Eggs Benedict, made easy! Featuring my no-compromise Easy Method for Poached Eggs and a 90-second Foolproof Hollandaise Sauce.But if it all sounds too daunting for a sleepy Sunday morning, take the easy way out and prepare the poached eggs and Hollandaise Sauce up to 2 days ahead. They both reheat perfectly.Save a bucketload by staying in for brunch this weekend - and you don''t even have to get out of your PJ''s!!Makes 8 Eggs Benedict to serve 4 people, ie. 2 eggs + 1 split muffin per person', 'https://www.recipetineats.com/tachyon/2020/10/Hollandaise-Sauce_7.jpg', 5, 20, 25, 4, '[{"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.045, "unit": "net of 500g"}}, {"id": "ing_water", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 175.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_bacon", "quantity": {"value": 1.6, "unit": "pack of 200g"}}, {"id": "ing_shaved_or_ham", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_salmon_fillets", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_english_muffins_split", "quantity": {"value": 4.0, "unit": "pack"}}, {"id": "ing_each_chives_and_parlsey", "quantity": {"value": 0.015, "unit": "kg"}}]', '[{"ingredients":["3 egg yolks (, from large eggs (55-60g / 2 oz each, Note 1))","1/4 tsp cayenne pepper ( or white pepper)","1/4 tsp salt","1 1/2 tbsp lemon juice (, plus more to taste)","1 1/2 tbsp water (, plus more as needed)","175g/ 1 1/2 sticks unsalted butter (, cut into 1.5 cm / 1/2\" cubes (Note 2))"],"purpose":"Hollandaise Sauce"},{"ingredients":["8 large eggs (, fridge cold (Note 3))"],"purpose":"Poached Eggs"},{"ingredients":["8 slices bacon ( - streaky, Canadian (traditional) or other)","200g / 7oz shaved or sliced ham (16 slices, ie. 2 slices per muffin half)","250g / 8oz smoked salmon slices (, at room temp)"],"purpose":"Protein – choose one:"},{"ingredients":["4 English Muffins, split (or 8 slices other bread, or 4 brioche or other rolls)","1 tbsp each Chives and parlsey (, roughly chopped, for garnish)"],"purpose":"Assembling"}]', '[{"description":"Preheat oven to 50°C/120°F.","images":[],"step":1},{"description":"Cook bacon in a little oil or butter to your liking. Transfer to small baking pan, cover with foil then place in oven.","images":[],"step":2},{"title":"Ham","description":"if using ham, cover and place in oven to warm slightly.","images":[],"step":3},{"description":"Lightly toast English muffins then keep warm on rack on tray.","images":[],"step":4},{"description":"Hollandaise Sauce:","images":[],"step":5},{"description":"Place egg yolks in a tall narrow jug that the blender stick fits in, all the way to the base.","images":[],"step":6},{"description":"Add water, lemon juice, cayanne pepper and salt. Blitz briefly to combine.","images":[],"step":7},{"description":"Melt butter in a heatproof jug until hot (be very careful to ensure it doesn''t explode if using microwave!). If you use a stove, pour into a jug. Let it stand for just 15 seconds until the milky whites settles at the bottom of the jug. (Note 2)","images":[],"step":8},{"description":"With the blender stick going on high, slowly pour the butter in a thin stream into the eggs over around 45 seconds. Leave behind most of the milky whites in the butter - about 1 1/2 tbsp. (Note 2) Once all the butter is in, the sauce should be thick, creamy, smooth and pale yellow. Now blitz for a further 10 seconds, moving the stick up and down.","images":[],"step":9},{"title":"Thickness","description":"If too thick, mix in warm tap water 1 teaspoon at a time. It should be thick but pourable so it will coat and stick to the eggs but not be transparent.","images":[],"step":10},{"title":"Keep warm","description":"Transfer to a bowl, cover and keep warm - it will stay warm for 15 min but even room temp is fine (will heat up when in contact with hot eggs).","duration":15,"images":[],"step":11},{"title":"Strain eggs","description":"Crack an egg into a small strainer set over a bowl or glass. Leave for 30 seconds and jiggle around a bit so watery whites strain through. Transfer to teacup. Repeat for another 3 eggs - separate teacup for each","duration":0.5,"images":[],"step":12},{"title":"Heat water","description":"Fill a large pot with 7.5 cm / 3\" water. (Note 4) Bring water to the boil over high heat, then turn the heat down so there are tiny bubbles from the base of the pot but big bubbles are not breaking water surface. (Note 5)","images":[],"step":13},{"title":"Roll eggs into water","description":"Submerge a teacup into the water so you can gently roll the egg out onto the base of the pot - minimise the drop distance for neatest shape. Repeat with remaining eggs - don''t take longer than 15 seconds to put them all in.","images":[],"step":14},{"title":"Turn eggs","description":"20 seconds after the first egg has gone in, eggs should be starting but are not fully set. Use a slotted spoon and tablespoon/dessert spoon to gently turn the eggs upside down - start with the first egg that went in, end with the last.","images":[],"step":15},{"title":"Poach 1 1/2 minutes","description":"Leave for 1 minute, then turn again. Leave for another 30 seconds then using a slotted spoon, lift one out to check for doneness - whites should be soft but set, yolks should be runny.","duration":1,"images":[],"step":16},{"title":"Drain","description":"Transfer to paper towel to drain and for top to dry with residual heat - 15 seconds. (Don''t leave for too long or it can get stuck to the paper towel.)","images":[],"step":17},{"description":"Place 2 English muffins halves on a plate. Pile on ham, bacon or smoked salmon. Top with poached egg, spoon over Hollandaise Sauce, sprinkle with parsley and chives. Serve immediately!","images":[],"step":18}]', '["egg","fish","gluten","milk"]', '[]', '{"mealType":["breakfast"],"cuisine":["Western"],"categories":["breakfast-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_284e49dc74de', 'en', 'US', 'Poached Eggs', 'Recipe video above. Here are the two methods I use to poach eggs:1. Easy Method - a "drop and roll" technique to make multiple eggs at the same time. Slightly less "perfect" poached egg shape, but small compromise. Can make up to 6 eggs at a time;2. Classic Whirlpool Method - requires more practice but best if striving for the "perfect" poached egg shape, or sense of accomplishment! Not recommended for eggs 2 weeks old, or older (see diagram in post to determine age of eggs). Use Easy Method instead.Do not skip straining to remove watery whites which is what causes a mess with poached eggs. (Unless you''ve got just-laid eggs!)Fresh eggs make the best shaped, tidy poached eggs. See diagram in post to detemine how old your eggs are. Older eggs (1 week+) - stick with the Easy Method to be safe. (Note 1)', 'https://www.recipetineats.com/tachyon/2020/10/Poached-Eggs.jpg', 1, 2, 3, 1, '[{"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.03, "unit": "L"}}]', '[{"ingredients":["1 - 6 eggs (, fridge cold (Note 1))"]},{"ingredients":["2 tbsp white vinegar or cider vinegar - Whirlpool method only (Note 2)"],"purpose":"Optional:"}]', '[{"description":"Strain Eggs (do this first for either Method)","images":[],"step":1},{"description":"Crack an egg into a small strainer set over a bowl or glass. Leave for 30 seconds and jiggle around a bit so watery whites strain through.","duration":0.5,"images":[],"step":2},{"description":"Carefully transfer to a teacup. Repeat for as many eggs as you plan to make in one batch (Whirlpool max 2, Easy Method up to 6), one in each teacup.","images":[],"step":3},{"description":"Boil water then reduce heat","images":[],"step":4},{"description":"For both methods, bring water to the boil over high heat, then turn the heat down so there are tiny bubbles from the base of the pot but big bubbles are not breaking water surface. (Note 4)","images":[],"step":5},{"description":"Easy Method (good to make 4 to 6 eggs):","images":[],"step":6},{"description":"Fill a pot with 7.5 cm / 3\" water. (Note 3) Bring to boil then lower heat, per above directions.","images":[],"step":7},{"description":"Submerge a teacup into the water so you can gently roll the egg out onto the base of the pot - minimise the drop distance for neatest shape.","images":[],"step":8},{"description":"Repeat with more eggs, but don''t take longer than 15 seconds to put them all in.","images":[],"step":9},{"description":"20 seconds after the first egg has gone in, eggs should be starting to but are not fully set. Use a slotted spoon and tablespoon/dessert spoon to gently turn the eggs upside down - start with the first egg that went in, end with the last.","images":[],"step":10},{"description":"Leave for 1 minute, then turn again.","duration":1,"images":[],"step":11},{"description":"Leave for another 30 seconds then using a slotted spoon, lift one out to check for doneness - whites should be soft but set, yolks should be runny.","images":[],"step":12},{"title":"Drain & serve","description":"Transfer to paper towel to drain and for top to dry with residual heat - 15 seconds. (Don''t leave for too long or it can get stuck to the paper towel.) Serve! See below for ideas.","images":[],"step":13},{"description":"Whirlpool Method:","images":[],"step":14},{"description":"Fill a large saucepan or small pot with 7.5 cm / 3\" of water. Add vinegar, if using (I don''t). Bring to boil then lower heat, per above directions.","images":[],"step":15},{"description":"Using the handle of a flat-handled wooden spoon, stir the water quickly (10cm/4\" diameter circle) to create a whirlpool so the vortex (\"V\" shape in water) stays for 7 seconds. (Note 5)","duration":0.11666666666666667,"images":[],"step":16},{"description":"Carefully slip the egg into the middle of the vortex, with the teacup as close to the water as possible but do NOT touch the water - it will break the water motion.","images":[],"step":17},{"description":"The spinning water will make the whites wrap around itself so it forms a lovely poached egg shape once it stops spinning (~ 15 seconds).","images":[],"step":18},{"title":"Leave for 1 1/2 to 2 minutes","description":"after 30 seconds, you can rotate once or twice, or swirl water again if you want to do it for you.","images":[],"step":19},{"description":"Using a slotted spoon, lift out to check for doneness - whites should be soft but set, yolks should be runny.","images":[],"step":20},{"title":"Drain & serve","description":"Transfer to paper towel to drain and for top to dry with residual heat - 15 seconds. (Don''t leave for too long or it can get stuck to the paper towel.) Serve!","images":[],"step":21},{"title":"Multiple eggs","description":"Use 15 cm / 6\" of water. Once the first egg has set (~ 30 sec), swirl water again and drop in another. I''ve seen experts do 4 eggs. I prefer the Easy Method!","images":[],"step":22},{"description":"Large batch poached eggs","images":[],"step":23},{"title":"Store in cold water","description":"Use either method above, and place cooked eggs in a large bowl of cold tap water which stops the eggs cooking further. If making a lot, use ice water to ensure water temperature stays down","images":[],"step":24},{"title":"To reheat","description":"Bring a large pot of water to the boil, then turn heat down to low. Transfer eggs straight from cold water into hot water, leave 30 seconds - they will not cook in this time, but will just reheat. Drain on paper towels, then serve!","images":[],"step":25},{"description":"Serve on toast, perhaps smeared with avocado, on asparagus or make Eggs Benedict! Great also on homemade baked beans and even a Caesar salad!","images":[],"step":26}]', '["egg"]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["breakfast"],"cuisine":["Western"],"categories":["breakfast-recipes","egg-recipes","good-to-know"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_960aaee078a5', 'en', 'US', 'Crustless Quiche - Ham and Cheese', 'Recipe video above. Tastes like Quiche Lorraine, minus the carbs and a load of prep time. Buy pre chopped ham and pre shredded cheese, and you''ll get this in the oven in 5 minutes flat! Excellent breakfast or brunch that keeps for days, serve slices like quiche OR stuff into rolls, make burritos! (see in post for photo)', 'https://www.recipetineats.com/tachyon/2020/09/Crustless-Quiche-Ham-and-Cheese_4.jpg', 5, 35, 40, 6, '[{"id": "ing_egg", "quantity": {"value": 416.667, "unit": "carton of 12"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_ham", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}]', '[{"ingredients":["5 large eggs (~50 - 55g / 2oz each)","1 cup cream (, heavy/thickened (halve if subbing milk, Note 1))","1/4 tsp salt (Note 2)","1/2 tsp black pepper","100g/ 3.5 oz ham (, diced)","1 cup shredded cheese (anything that melts except mozzarella, Note 3)","1 green onion (, sliced)"]}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan-forced). Grease a 22.5cm / 9\" pie dish with butter or spray lightly with oil. (Note 4)","images":[],"step":1},{"description":"Whisk eggs, cream, salt and pepper.","images":[],"step":2},{"description":"Scatter most of the ham, cheese and green onion in the pie pan.","images":[],"step":3},{"description":"Pour in egg mixture. Top with remaining ham, cheese and green onion.","images":[],"step":4},{"description":"Bake 35 minutes until golden on top and centre barely wiggles. Don''t overcook, it will lose custardy-ness.","images":[],"step":5},{"description":"Remove from oven, rest 5 minutes and watch it deflate!","images":[],"step":6},{"description":"Cut then serve with a simple side salad, or stuff into soft rolls, or wrap into burritos (then pan fry to crisp!)","images":[],"step":7}]', '["egg","milk"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["breakfast"],"cuisine":["Western"],"categories":["breakfast-recipes","egg-recipes","leftover-ham-recipes","quiches-tart-and-pie-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1ae25d0cadd8', 'en', 'US', 'Scrambled eggs - soft and creamy, just as they should be!', 'Recipe video above. No one should tell you how to take your eggs. But everyone should know how to make scrambled eggs well! 60 seconds, soft, creamy, custardy. Perfection!Scrambled egg calories - 91 calories per egg (182 cal per serving of 2 eggs), including the butter.', 'https://www.recipetineats.com/tachyon/2020/07/Scrambled-Eggs_5.jpg', 1, 1, 2, 2, '[{"id": "ing_egg", "quantity": {"value": 4.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.04, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_bread", "quantity": {"value": 0.2, "unit": "loaf"}}]', '[{"ingredients":["4 eggs","2 tbsp milk (, any fat % (optional, Note 1))","1/4 tsp salt","2 grinds black pepper","1 tbsp / 15g butter (or margarine or oil)"]},{"ingredients":["4 slices bread (, toasted & slathered with butter)"],"purpose":"For serving:"}]', '[{"description":"Use a non stick skillet or well seasoned cast iron pan (about 25cm / 10\") and a rubber spatular (or flat edge wooden spoon).","images":[],"step":1},{"description":"Whisk together eggs, milk, salt and pepper.","images":[],"step":2},{"description":"Melt butter over medium heat (Note 1), then pour egg in.","images":[],"step":3},{"description":"Wait 5 seconds, then start leisurely pushing the rubber spatula back and forth in long strokes, and all around the skillet edges, to push the set egg out of the way and let raw egg run onto the skillet to cook. After 30 seconds or so, start adding some folding action too.","images":[],"step":4},{"description":"Cook for 60 seconds in total until you have a pile of soft, custardy scrambled egg folds (\"curds\") and no raw egg leaking on the edges of the pile.","duration":1,"images":[],"step":5},{"description":"Take it off the stove when it''s still a bit undercooked for your taste.","images":[],"step":6},{"title":"Gently push /fold the eggs for another 10 seconds","description":"it will finish cooking with residual pan heat - then slide onto hot toasted crusty bread slathered with butter.","images":[],"step":7},{"description":"Sprinkle with extra pepper then devour immediately! For a touch of garnish, look no further than an 80''s style sprig of curly parsley. 👌🏻","images":[],"step":8}]', '["egg","gluten","milk"]', '["keto_friendly","low_calorie","vegetarian"]', '{"mealType":["breakfast"],"cuisine":["Western"],"categories":["breakfast-recipes","egg-recipes","good-to-know"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9ac49af702b7', 'en', 'US', 'Extra Crispy Corn Fritters', 'Recipe video above. Sweet pops of fresh corn on the inside, very crispy on the outside. These heavenly fritters are light on batter, heavy on the corn – just the way they should be! Makes a lovely meal for 2 with a leafy green salad on the side, or a starter for 4.', 'https://www.recipetineats.com/tachyon/2020/05/Crispy-Corn-Fritters_0-copy.jpg', 10, 20, 30, 8, '[{"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.094, "unit": "pack of 400g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.006, "unit": "tub of 200g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_corn", "quantity": {"value": 0.75, "unit": "can of 400g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_green_onion", "quantity": {"value": 2.25, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}]', '[{"ingredients":["1/4 cup flour (, plain / all purpose)","1/4 cup cornflour / cornstarch","1/4 tsp baking soda (or 3/4 tsp baking powder)","1 egg","2 tbsp milk (any type)","2 cups fresh corn kernels (, raw (2 cobs) (canned or frozen also fine - Note 1))","1/2 cup parmesan (, finely grated)","3/4 cup green onions (, sliced)","1/2 cup coriander/cilantro (, roughly chopped (sub more green onion))"]},{"ingredients":["1/2 cup vegetable oil","Oil spray"],"purpose":"For cooking:"},{"ingredients":["Avocado sauce","Sour cream, ketchup (don’t judge until you’ve tried it!)"],"purpose":"Serving – choose:"}]', '[{"description":"Preheat oven to 120°C / 250°F and set a wire rack on a baking tray.","images":[],"step":1},{"description":"Place flour, cornflour and baking soda in a bowl, mix to combine.","images":[],"step":2},{"description":"Add egg and milk, mix until incorporated (batter will be lumpy and thick).","images":[],"step":3},{"description":"Add corn, parmesan, green onions and coriander. Mix until all the corn is evenly coated in batter.","images":[],"step":4},{"description":"Add enough oil into the skillet so it just covers the base. Heat over medium high heat.","images":[],"step":5},{"description":"Spray the underside of a spatula with oil (so batter won’t stick when you flatten).","images":[],"step":6},{"description":"Place 1/4 cup batter into skillet (ice cream scooper with lever is handy), then flatten to 1cm thick. Repeat with 2 or 3 more, but don’t crowd the skillet.","images":[],"step":7},{"description":"Cook 3 minutes until deep golden and crisp, then flip and cook the other side for 2 – 3 minutes.","duration":2.5,"images":[],"step":8},{"description":"Transfer to rack and keep warm in oven. Repeat with remaining fritters, using more oil as necessary.","images":[],"step":9},{"description":"Serve with sauce of choice for dunking!","images":[],"step":10}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["breakfast","dinner","snack"],"cuisine":["Western"],"categories":["breakfast-recipes","fritters-tots-and-similar","quick-and-easy","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1d0ae28e015b', 'en', 'US', 'Bacon and Egg Breakfast Muffins', 'Recipe video above. Bacon and eggs...in a muffin! These are great for "grab and go". This makes 4 large muffins (Texas muffin tin size - Note 3). This recipe isn''t suitable for ordinary size muffin tins as it isn''t large enough to hold the egg and batter.', 'https://www.recipetineats.com/tachyon/2015/05/Bacon-Egg-Breakfast-Muffins_3.jpg', 15, 20, 35, 4, '[{"id": "ing_bacon", "quantity": {"value": 0.75, "unit": "pack of 200g"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.042, "unit": "tub of 150g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.006, "unit": "tub of 200g"}}, {"id": "ing_milk", "quantity": {"value": 0.167, "unit": "L"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.003, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.4, "unit": "tub of 250g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 4.0, "unit": "carton of 12"}}, {"id": "ing_egg", "quantity": {"value": 4.0, "unit": "carton of 12"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}]', '[{"ingredients":["150g / 5oz bacon (, chopped (I use lean))","1 cup green onion (, finely sliced (2 stems))","1 cup (100g) cheddar cheese (, shredded (or other of choice))"],"purpose":"Flavourings"},{"ingredients":["1 1/2 cups (225g) flour (, plain / all purpose)","1 1/4 tsp baking powder (Note 1)","1/4 tsp baking soda (aka bicarbonate soda, Note 1)"],"purpose":"Dry Ingredients"},{"ingredients":["2/3 cup (165 ml) milk (, full or low fat)","1/2 tsp white vinegar (Note 2)","1/2 tsp salt","2/3 cup sour cream or plain yoghurt (, preferably full fat)","3 tbsp vegetable oil (or other neutral flavoured oil)","1 egg"],"purpose":"Wet Ingredients"},{"ingredients":["4 eggs","2 tbsp melted butter"],"purpose":"Muffin"}]', '[{"description":"Preheat oven to 180C/350F. Brush 4 Texas muffin tin holes with with butter. (Note 3)","images":[],"step":1},{"description":"Heat a non stick pan over high heat. Add bacon and fry until lightly browned. Remove onto a paper towel to drain the fat, then set aside.","images":[],"step":2},{"description":"Place Dry Ingredients in a bowl and mix to combine.","images":[],"step":3},{"description":"Whisk Wet Ingredients in a separate bowl.","images":[],"step":4},{"description":"Pour the Wet Ingredients into the Dry Ingredients until flour is almost incorporated (limit to 8 stirs!) - don''t overmix (makes muffins hard).","images":[],"step":5},{"description":"Add green onion, bacon and cheese, stir 5 times.","images":[],"step":6},{"description":"Place 1/4 cup batter into each of the 4 muffin tin holes.","images":[],"step":7},{"description":"Use spoon to make a well in the batter, crack egg into each well.","images":[],"step":8},{"description":"Divide the remaining batter between each hole to cover the egg - best way is to dollop batter around the yolk, then on top of the yolk, then spread to cover (see video).","images":[],"step":9},{"description":"Brush the muffins with melted butter, then bake for 25 minutes or until golden brown.","duration":25,"images":[],"step":10},{"description":"Remove from oven and allow to rest for 5 minutes before turning out onto a cooling rack.","duration":5,"images":[],"step":11},{"description":"Best served warm!","images":[],"step":12}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["breakfast"],"cuisine":["Western"],"categories":["breakfast-recipes","easter-brunch-recipes","egg-recipes","most-popular","muffin-recipes","pork-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c7c5957595ec', 'en', 'US', 'Healthy Oatmeal Breakfast Cookies', 'Recipe video above. Like homemade granola - in cookie form! A satisfying grab ''n run breakfast that tastes like your favourite Oatmeal Raisin Cookies. Same chewy and moist inside (thanks to the mashed dates!), but not as crispy. And these happen to be healthy! Customisable - see notes.', 'https://www.recipetineats.com/tachyon/2018/09/Breakfast-Cookie_7.jpg', 15, 20, 35, 6, '[{"id": "ing_pitted_dates", "quantity": {"value": 100.0, "unit": "unit"}}, {"id": "ing_water", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_maple_syrup", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_oil", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_vanilla_essence", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_rolled_oats", "quantity": {"value": 0.375, "unit": "pack of 500g"}}, {"id": "ing_almonds", "quantity": {"value": 0.3, "unit": "pack of 250g"}}, {"id": "ing_desiccated_coconut", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_raisins", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_almonds", "quantity": {"value": 0.3, "unit": "pack of 250g"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.017, "unit": "tub of 150g"}}, {"id": "ing_cinnamon", "quantity": {"value": 2.5, "unit": "jar"}}]', '[{"ingredients":["100 g / 3.5 oz pitted dates (1 heaped packed cup)","1/3 cup / 85 ml boiling water","1 egg","3 tbsp maple syrup or honey (Note 1)","3 tbsp coconut oil (, melted, or other plain oil (Note 2))","1 tsp vanilla essence (Note 5)"],"purpose":"Wet Ingredients:"},{"ingredients":["1 1/4 cups rolled oats","1/2 cup flaked almonds (Note 3)","1/4 cups desiccated coconut (Note 3)","1/2 cup raisins or sultanas (Note 3)","3/4 cup almond meal (almond flour) (Note 4)","1/2 tsp baking powder","1/2 tsp cinnamon (Note 5)"],"purpose":"Dry Ingredients:"}]', '[{"description":"Preheat oven to 180C/350F (standard) or 160C/320F (fan/convection). Line a tray with parchment/baking paper.","images":[],"step":1},{"description":"Roughly chop dates. Place in bowl, pour over water. Cover and leave to soak for 10 minutes+.","duration":10,"images":[],"step":2},{"description":"Mash with potato masher or fork until it becomes a paste.","images":[],"step":3},{"description":"Add remaining Wet ingredients. Mix well with wooden spoon.","images":[],"step":4},{"description":"Add Dry ingredients. Mix until all flour is incorporated - should be a thick batter (see video).","images":[],"step":5},{"description":"Measure out just shy of 1/2 cup (6 cookies) or 1/3 cup flat (8 cookies). Flatten to 1.7cm / 2/3\" thick rounds. (Note 9) Bake 20 minutes until golden.","images":[],"step":6},{"description":"Remove from oven, leave to cool on the tray.","images":[],"step":7}]', '["egg","gluten","nuts"]', '["low_calorie","vegetarian"]', '{"mealType":["breakfast","dessert"],"cuisine":[],"categories":["breakfast-recipes","cookies","dessert-recipes","dietary","dinner-tonight","easter-brunch-recipes","gluten-free-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_355c63b019f0', 'en', 'US', 'Homemade Sausage and Egg McMuffin', 'Recipe video above. This is my copycat of McDonald''s Sausage and Egg McMuffin. The sausage patties are made from scratch and it really does taste similar to the McDonald''s Sausage patty - but it tastes pure, like real food should! Great make ahead breakfast - grab and run!', 'https://www.recipetineats.com/tachyon/2016/05/Sausage-Egg-McMuffins_5.jpg', 10, 15, 25, 4, '[{"id": "ing_beef", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_sage", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_egg", "quantity": {"value": 4.0, "unit": "carton of 12"}}, {"id": "ing_english_muffins", "quantity": {"value": 4.0, "unit": "pack"}}, {"id": "ing_cheese", "quantity": {"value": 4.0, "unit": "block of 250g"}}]', '[{"ingredients":["1 lb / 500g ground pork (juicier) OR beef (mince) (Note 1)","1/2 tsp dried ground sage","1/2 tsp dried thyme","1 tsp onion powder (or garlic powder)","3/4 tsp black pepper","3/4 tsp salt","1/2 tsp sugar (any)"],"purpose":"Sausage Patties"},{"ingredients":["2 tbsp oil","4 eggs","4 English muffins (, cut in half)","4 slices cheese (Note 3)"],"purpose":"Muffins"}]', '[{"description":"Preheat oven to 130C/275F.","images":[],"step":1},{"description":"Place muffins on a baking tray, cut side up, and top with cheese. (Alternative - melt cheese on sausage patties, see video)","images":[],"step":2},{"description":"Sausage Patties","images":[],"step":3},{"title":"Mix Sausage Patty ingredients in a bowl","description":"use your hands to mix it real good!","images":[],"step":4},{"description":"Shape into 4 patties (thick ones, or 5 Maccers size patties). Make them slightly larger than the muffins because they will shrink when cooking.","images":[],"step":5},{"description":"Heat oil in a large non stick skillet over high heat. Add patties (in batches if needed). Cook the first side for 2 - 3 minutes or until browned. Flip then cook the other side until browned. (Optional: After flipping, top with cheese, cover with lid to melt).","duration":2.5,"images":[],"step":6},{"description":"Meanwhile, heat another pan over medium high heat with 1 tbsp oil. Spray egg rings with oil and place in the skillet. (Note 4 for other cook methods).","images":[],"step":7},{"description":"Crack egg into the rings. Add around 2 tbsp water into the skillet then cover with a lid. Cook for 1 - 2 minutes or until egg is cooked to your liking (I like runny yolks).","duration":1.5,"images":[],"step":8},{"description":"Remove warm muffins from the oven. Top with sausage, then egg, the lid of muffin.","images":[],"step":9},{"description":"Serve and enjoy!","images":[],"step":10}]', '["egg","milk"]', '["gluten_free"]', '{"mealType":["breakfast","snack"],"cuisine":["Western"],"categories":["breakfast-recipes","egg-recipes","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_82bb92f1a2fc', 'en', 'US', 'Frittata Egg Muffins', 'Recipe VIDEO above. Healthy doesn''t have to be bland! Just a touch of feta really makes all the difference with these frittata muffins. Great grab ''n go breakfast muffins - high in protein so it keeps you fuller for longer, keeps for days in the fridge or months in the freezer!', 'https://www.recipetineats.com/tachyon/2018/02/Healthy-Egg-Muffins_1-1.jpg', 10, 20, 30, 6, '[{"id": "ing_egg", "quantity": {"value": 6.0, "unit": "carton of 12"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_spinach", "quantity": {"value": 0.75, "unit": "bag of 250g"}}, {"id": "ing_capsicum", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 8.0, "unit": "punnet of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_feta_cheese", "quantity": {"value": 70.0, "unit": "block of 200g"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}]', '[{"ingredients":["6 eggs (large or medium)","½ tsp salt","¼ tsp black pepper","3/4 cup chopped spinach (baby or normal Spinach, or similar leafy greens)","1/2 cup diced red capsicum / bell pepper","8 cherry tomatoes (, quartered (Note 1))","½ cup shallots (, finely sliced)","70 g / 2.5 oz feta (, crumbled (about 1/2 cup))","Oil spray (, for greasing muffin tin)"]}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Spray 6 standard non stick muffin holes with oil.","images":[],"step":2},{"description":"Whisk eggs, salt and pepper. Stir through vegetables and feta.","images":[],"step":3},{"description":"Divide mixture between holes.","images":[],"step":4},{"description":"Bake 20 minutes or until the top is light golden and the centre springs back when touched.","images":[],"step":5},{"description":"Served immediately. Or allow to cool, then store in an airtight container in the fridge for 3 - 4 days, or freezer for 3 months (defrost 2 minutes in the microwave or overnight in the fridge).","images":[],"step":6}]', '["egg"]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["breakfast","snack"],"cuisine":["Western"],"categories":["breakfast-recipes","dietary","easter-brunch-recipes","egg-recipes","low-calorie-recipes","muffin-recipes","quick-and-easy","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_38e105e6a1c8', 'en', 'US', 'French Toast', 'Recipe video above. A recipe everyone should know! Made for using up leftover bread, but if you want the ultimate French Toast experience, use brioche bread (pictured in post). There’s no need to use sugar if you’re dousing with maple syrup – plus it burns easily. Best made with stale bread, otherwise, see Note 1.', 'https://www.recipetineats.com/tachyon/2014/06/French-Toast_3.jpg', 2, 10, 12, 2, '[{"id": "ing_bread", "quantity": {"value": 0.3, "unit": "loaf"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_strawberries", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_maple_syrup", "quantity": {"value": 1.0, "unit": "bottle of 250ml"}}]', '[{"ingredients":["6 slices brioche or white sandwich bread (, slightly stale (Note 1))","30 – 40g / 2 – 3 tbsp butter"]},{"ingredients":["2 large eggs (~60g / 2 oz each)","½ cup / 125 ml milk","1/2 tsp cinnamon powder","1 tsp vanilla extract"],"purpose":"Egg Mixture:"},{"ingredients":["250g / 8 oz strawberries, halved","1 tbsp white sugar"],"purpose":"Macerated Strawberries, optional:"},{"ingredients":["Maple syrup, butter"],"purpose":"Serving:"}]', '[{"description":"Whisk together Egg Mixture in a bowl. Vigorous whisk = avoid cinnamon floating on top.","images":[],"step":1},{"description":"Melt 15g / 1 tbsp butter in a non stick skillet over medium heat.","images":[],"step":2},{"description":"Dunk a piece of bread quickly into the egg mixture, coating both sides. Place in pan. Repeat with more slices to fill the pan, but don’t crowd it (do 2 or 3 at a time).","images":[],"step":3},{"title":"Cook for 2 ½","description":"3 minutes on each side until the surface is golden, then transfer to serving plates.","images":[],"step":4},{"description":"Add more butter into the pan and cook remaining bread.","images":[],"step":5},{"description":"Serve with butter and plenty of maple syrup, and Macerated Strawberries if using!","images":[],"step":6},{"description":"Macerated Strawberries (optional):","images":[],"step":7},{"description":"Toss strawberries with sugar, set aside for 20 minutes+. The strawberries will soften and sweat, and create a bit of syrup.","duration":20,"images":[],"step":8}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["breakfast"],"cuisine":["Western"],"categories":["breakfast-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_10b8c57cd7a8', 'en', 'US', 'Frittata', 'Recipe video above. A great frittata is a thing of beauty! Great for feeding a group , or a make ahead meal for breakfast, lunch and dinner. Soft and custardy on the inside, this is one of those recipes that''s great to adapt to whatever add ins you want. See notes for STOVE ONLY version.', 'https://www.recipetineats.com/tachyon/2018/09/Frittata-1.jpg', 5, 20, 25, 8, '[{"id": "ing_egg", "quantity": {"value": 10.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_bacon", "quantity": {"value": 1.5, "unit": "pack of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_baby_spinach", "quantity": {"value": 2.0, "unit": "bag of 250g"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.2, "unit": "pack of 125g"}}, {"id": "ing_spinach", "quantity": {"value": 2.0, "unit": "bag of 250g"}}]', '[{"ingredients":["10 eggs","2 tbsp milk (any)","1/2 tsp salt and pepper","1 tsp oil","300 g / 10oz bacon (, chopped)","2 garlic cloves (, minced)","1 tbsp / 15 g butter","2 big handfuls baby spinach","1 1/2 cups / 150g mozzarella cheese (, shredded (or other melting cheese))"]},{"ingredients":["More cooked chopped bacon and spinach, (for garnish as pictured)"],"purpose":"Garnish (optional):"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Whisk eggs, milk, salt and pepper.","images":[],"step":2},{"description":"Heat oil in a well seasoned skillet or non stick pan (about 26cm / 11\") over medium high heat.","images":[],"step":3},{"description":"Add bacon and cook until almost golden.","images":[],"step":4},{"description":"Add garlic and cook for 30 seconds.","duration":0.5,"images":[],"step":5},{"title":"Add spinach and toss until just wilted","description":"bacon should now be golden.","images":[],"step":6},{"description":"Turn heat down to medium. Remove about 1/3 of the bacon spinach into a bowl (for topping).","images":[],"step":7},{"description":"Add butter into the pan and swirl/spread across base of the pan.","images":[],"step":8},{"description":"Pour in about 2/3 of the egg mixture. Scatter over half the cheese, then pour over remaining egg mixture.","images":[],"step":9},{"description":"Scatter over reserved bacon and spinach, then cheese.","images":[],"step":10},{"description":"Cook for about 3 minutes until the sides are just set but not golden - check with knife.","images":[],"step":11},{"description":"Transfer to oven and cook for 8 minutes until the centre is just set and the cheese is melted on top.","duration":8,"images":[],"step":12},{"description":"Rest for a few minutes then slice and serve.","images":[],"step":13}]', '["egg","milk"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["breakfast"],"cuisine":[],"categories":["breakfast-recipes","dinner-tonight","easter-brunch-recipes","egg-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_94e6db193052', 'en', 'US', 'Shakshuka (Middle Eastern Poached or Baked Eggs)', 'Recipe video above. I call this the best baked eggs in the world, but they can also just be poached on the stove! With Middle Eastern and North African roots, the tomato sauce is lightly spiced and used as the bed to cook the eggs. PS Crusty bread is a must. PPS Recipe lends itself to great variations - see recipe notes.', 'https://www.recipetineats.com/tachyon/2014/05/Shakshuka_9.jpg', 10, 20, 30, 2, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 4.0, "unit": "carton of 12"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["2 tbsp olive oil","1 small red onion (, peeled, halved and sliced)","1 garlic clove (, minced)","1 small red capsicum (bell pepper) (, halved lengthways and sliced into 0.5cm/1/4” strips)","1 tomato (, diced)","400 g / 14 oz can crushed tomatoes","1 tbsp tomato paste","1/2 cup / 125 ml chicken or vegetable broth (or water)","1 tsp EACH paprika and cumin","1/4 tsp EACH black pepper and cayenne pepper (or other hot spice, adjust to taste)","1/2 tsp salt","4 eggs eggs (up to 6 eggs ok)","2 tbsp fresh parsley or coriander / cilantro (, roughly chopped)","Pita or crusty bread, to serve"]}]', '[{"description":"Preheat oven to 180C/350F (if intending to bake them).","images":[],"step":1},{"description":"Heat oil in a medium size cast iron skillet over medium high heat. Add garlic and onion, cook for 2 minutes until onion is translucent.","duration":2,"images":[],"step":2},{"description":"Add capsicum, cook for 1 minute. Add diced tomato, cook for 2 minutes until broken down and it becomes a bit pasty (see video).","duration":1,"images":[],"step":3},{"description":"Add canned tomatoes, tomato paste, broth, paprika, cumin, salt and pepper. Mix to combine well.","images":[],"step":4},{"description":"Lower stove to medium low and simmer for 5 minutes until just thickened enough to make indentations (don''t want dry sludge, needs to still be saucy).","duration":5,"images":[],"step":5},{"description":"Make indentations in the mixture and carefully crack the eggs in. Leave to cook for 1 minute until edges of whites are set (Note 1).","duration":1,"images":[],"step":6},{"description":"Transfer to oven and bake for 7 to 12 minutes until whites are just set but yolks are still runny (or to your taste). OR cover with lid and steam on stove for 3 minutes (runny yolks), or just simmer them without a lid.","duration":9.5,"images":[],"step":7},{"description":"Remove from oven/stove and serve immediately, scattered with the coriander or parsley. Serve with crusty bread, or pita bread.","images":[],"step":8}]', '["egg","gluten"]', '["low_calorie"]', '{"mealType":["breakfast"],"cuisine":["Israeli","Middle Eastern","North African"],"categories":["breakfast-recipes","cuisines","egg-recipes","middle-eastern-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_98b7e5df7ab7', 'en', 'US', 'Quiche Lorraine', 'Recipe VIDEO above. A classic Quiche Lorraine with a gorgeous smooth filling loaded with bacon. Make this with my EASY shortcrust quiche pastry or use store bought. Quiche is a brilliant make ahead because it''s one of those things that truly reheats well without compromise - see notes.', 'https://www.recipetineats.com/tachyon/2018/04/Quiche-Lorraine_0.jpg', 30, 75, 105, 8, '[{"id": "ing_homemade_quiche_crust", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_sheets_shortcrust", "quantity": {"value": 2.0, "unit": "pack"}}, {"id": "ing_prepared_pie_shell", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_bacon", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_egg", "quantity": {"value": 4.0, "unit": "carton of 12"}}, {"id": "ing_cream", "quantity": {"value": 1.25, "unit": "carton of 250ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_gruyere_cheese", "quantity": {"value": 1.25, "unit": "block of 200g"}}, {"id": "ing_bacon", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["1 homemade quiche crust (shortcrust pastry)","2 sheets shortcrust (, thawed)","1 prepared pie shell (, fridge or frozen)"],"purpose":"Quiche Crust – choose one:"},{"ingredients":["1 tbsp / 15g butter","1 garlic clove (, minced)","1/2 onion, finely chopped (~1/2 cup)","200 g / 6.5 oz bacon, cut into small strips (1.5 x 0.5cm / 2/3\" x 1/5\")"],"purpose":"Bacon Filling:"},{"ingredients":["4 eggs (~55- 65g / 2 oz each)","1 1/4 cups (300ml) heavy cream (thickened cream) (Note 1)","Pinch of salt & pepper"],"purpose":"Egg Mixture"},{"ingredients":["1 1/4 cups (125g) grated gruyere cheese (or tasty, cheddar, monterey jack)"],"purpose":"Cheese:"},{"ingredients":["50g / 2 oz bacon, chopped and cooked until golden"],"purpose":"Garnish (optional):"}]', '[{"title":"Frozen shortcrust pastry or homemade quiche crust","description":"prepare and bake the crust per Quiche Crust recipe (23cm / 9\" quiche tin).","images":[],"step":1},{"title":"Prepared pie shell","description":"bake per packet directions.","images":[],"step":2},{"description":"Preheat oven to 200C/390F (standard) or 180C/350F (fan / convection).","images":[],"step":3},{"description":"Melt butter in a skillet over medium high heat. Add onion, garlic and bacon. Cook until bacon is light golden.","images":[],"step":4},{"description":"Transfer to a paper towel lined bowl and leave to cool.","images":[],"step":5},{"description":"Egg Mixture:","images":[],"step":6},{"description":"Place ingredients in a bowl and whisk to combine.","images":[],"step":7},{"description":"Assembling and Baking:","images":[],"step":8},{"description":"Place quiche tin with cooked quiche crust on tray. Scatter cooled Bacon Filling evenly across base of cooked quiche crust.","images":[],"step":9},{"description":"Scatter cheese evenly across top.","images":[],"step":10},{"description":"Carefully pour Egg mixture over the top. Push some of the cheese/bacon below the surface.","images":[],"step":11},{"title":"Bake for 35","description":"40 minutes until the top is golden. The centre should still jiggly.","duration":37.5,"images":[],"step":12},{"description":"Garnish with Extra Bacon, if using. Rest for 10 minutes before removing from the pan to cut and serve.","duration":10,"images":[],"step":13}]', '["egg","milk"]', '["gluten_free"]', '{"mealType":["main_course"],"cuisine":["French","Western"],"categories":["breakfast-recipes","easter-brunch-recipes","easter-recipes","quiches-tart-and-pie-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d3b027557a52', 'en', 'US', 'Cheese and Ham Pancakes (Pikelets!)', 'Crispy cheesy outsides, fluffy insides with pops of ham, these pancakes are an outrageously delicious way to use up leftover Christmas Ham though of course you can use store bought or even bacon. Using this recipe has a base, imagine the possibilities! Grated veggies, leftover cooked chicken, sausages - let your imagination run wild! Recipe VIDEO below, useful to see thickness of batter.', 'https://www.recipetineats.com/tachyon/2017/12/Ham-and-Cheese-Pancakes-1.jpg', 10, 15, 25, 13, '[{"id": "ing_flour", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.067, "unit": "tub of 150g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.215, "unit": "L"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 1.25, "unit": "block of 250g"}}, {"id": "ing_ham", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 4.5, "unit": "bunch"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 4.5, "unit": "bunch"}}, {"id": "ing_ham", "quantity": {"value": 0.188, "unit": "kg"}}]', '[{"ingredients":["1 cup / 150 g plain flour (all purpose flour)","2 tsp baking powder","Pinch of salt and pepper","1 egg","215 ml / 3/4 cup + 2 tbsp milk (Note 1)","1 1/4 cups / 150 g grated cheddar cheese (Note 2)","1 1/4 cups / 225g chopped ham (Note 3)","1 1/2 cups shallots / scallions (, finely sliced (about 4 stalks))"]},{"ingredients":["2 - 3 tbsp butter"],"purpose":"Cooking:"},{"ingredients":["Sour cream (highly recommend, or use yoghurt)","Extra chopped shallots","Extra chopped ham (, cooked)"],"purpose":"Toppings (optional):"}]', '[{"description":"Place flour, baking powder, salt and pepper in a bowl. Mix to combine.","images":[],"step":1},{"description":"Make a well in the centre. Add egg and milk. Mix until flour is incorporated - small lumps is fine (see video / photo in post).","images":[],"step":2},{"title":"Add cheese, ham and shallots. Stir through","description":"it should have a soft dropping consistency.","images":[],"step":3},{"description":"Heat a non stick pan over medium high heat (or medium if your stove is strong).","images":[],"step":4},{"title":"If using extra ham for toppings","description":"cook it in just 1 tsp butter until golden, then remove onto paper towels to drain.","images":[],"step":5},{"title":"For the pancakes","description":"Add about 2 tsp butter, swirl to melt.","images":[],"step":6},{"description":"Place 1/4 cup batter in the pan (Note 4), then roughly spread into a 7cm / 3\" circle. Repeat to fill the pan (I do 3 in a small pan, 4 in a large).","images":[],"step":7},{"description":"Cook for 2 minutes until the underside is deep golden. Don''t wait for bubbles like normal pancakes, they won''t appear.","duration":2,"images":[],"step":8},{"description":"Flip and cook the other side for 1 1/2 minutes. Remove onto a rack.","images":[],"step":9},{"description":"Add a bit of extra butter and repeat with remaining batter.","images":[],"step":10},{"description":"Serve with dollops of sour cream (virtually mandatory!), sprinkled with extra cooked ham and shallots, if desired.","images":[],"step":11}]', '["egg","gluten","milk"]', '["low_calorie"]', '{"mealType":["main_course"],"cuisine":[],"categories":["breakfast-recipes","leftover-ham-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b45c9fae45e1', 'en', 'US', 'Build Your Own Homemade Granola (Muesli)', 'This is the ultimate build-your-own HEALTHY homemade granola recipe! Choose your own nuts, seeds, dried fruit, sweetener and flavouring. Recipe VIDEO below.', 'https://www.recipetineats.com/tachyon/2014/05/Build-Your-Own-Healthy-Homemade-Granola-Featured-Image-1.jpg', 5, 30, 35, 4, '[{"id": "ing_rolled_oats", "quantity": {"value": 1.2, "unit": "pack of 500g"}}, {"id": "ing_chilli_flakes", "quantity": {"value": 3.75, "unit": "jar of 40g"}}, {"id": "ing_nuts", "quantity": {"value": 150.0, "unit": "jar"}}, {"id": "ing_fruit", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_your_favourite_spice", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_sweetener", "quantity": {"value": 0.333, "unit": "unit"}}, {"id": "ing_fat", "quantity": {"value": 0.333, "unit": "unit"}}, {"id": "ing_flavouring", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}]', '[{"ingredients":["4 cups / 360 g rolled oats (not steel cut or quick cooking)","1 cup coconut flakes (or more nuts or oats)","1 cup raw nuts (eg. sliced almonds, chopped pecans, sunflower seeds, pumpkin seeds)","1/2 cup dried fruit (eg. chopped apricots, apple, pineapple, raisins)","1 tsp your favourite spice (eg. cinnamon, pumpkin spice, gingerbread mix)","1 pinch salt"],"purpose":"Dry Ingredients:"},{"ingredients":["1/3 cup sweetener (eg. honey, maple syrup, agave, see note 2 for Brown Sugar)","1/3 cup fat (eg. melted butter, canola oil or coconut oil)","1 1/2 tsp flavouring (eg. vanilla, almond essence, orange blossom)"],"purpose":"Wet Ingredients:"},{"ingredients":["2 egg whites"],"purpose":"CLUMPY Granola:"}]', '[{"description":"Preheat oven to 150C/300F.","images":[],"step":1},{"description":"Combine Dry ingredients, excluding dried fruit.","images":[],"step":2},{"description":"Combine Wet ingredients.","images":[],"step":3},{"description":"Combine Wet and Dry ingredients. Do a taste test. Adjust to taste - more sweet, more fat etc.","images":[],"step":4},{"description":"Spread on baking tray and bake until golden, approximately 35 - 40 minutes, tossing twice.","images":[],"step":5},{"description":"Stir through dried fruit. Cool. Store in an airtight container.","images":[],"step":6},{"description":"CLUMPY Granola:","images":[],"step":7},{"description":"Preheat oven to 140C/280F. Line a large baking tray with baking paper.","images":[],"step":8},{"description":"Combine Wet excluding egg whites.","images":[],"step":9},{"description":"Combine Dry including dried fruit.","images":[],"step":10},{"description":"Whisk egg whites with fork until foamy.","images":[],"step":11},{"description":"Mix Wet and Dry in a large bowl, then mix through egg whites.","images":[],"step":12},{"description":"Spread granola on the tray, making a hole in the centre, like a doughnut (see photo in post).","images":[],"step":13},{"title":"Bake for 45 minutes","description":"DO NOT STIR - until golden. Check at 35 minutes.","duration":45,"images":[],"step":14},{"description":"Then turn the oven off, leave the granola in the oven, and open the oven door open a bit. Leave the granola to cool. The colour will deepen and it will firm up.","images":[],"step":15},{"description":"Once cool, break into clusters. Store in an airtight container.","images":[],"step":16}]', '["egg","milk","nuts"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["breakfast"],"cuisine":[],"categories":["breakfast-recipes","egg-white-recipes","quick-and-easy","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_05ba4dacef70', 'en', 'US', 'Simple, Fluffy Pancakes', 'Recipe video above. Simple, fluffy pancakes made from scratch, an essential that everyone should know! These are soft and fluffy, easy to make, and not too sweet so you can go wild with toppings. The key is getting the batter consistency right so it is easy to spread but doesn''t spread too thinly so you get nice fluffy pancakes.', 'https://www.recipetineats.com/tachyon/2017/06/Pancakes-featured.jpg', 5, 15, 20, 13, '[{"id": "ing_flour", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.133, "unit": "tub of 150g"}}, {"id": "ing_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.438, "unit": "L"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_butter", "quantity": {"value": 4.0, "unit": "block of 250g"}}]', '[{"ingredients":["2 cups plain / all purpose flour (Note 1)","4 tsp baking powder (NOT baking soda / bi-carb (Note 1))","1/4 cup white sugar (caster / super fine is best but not essential)","Pinch of salt","1 large egg (~50g / 2oz in shell)","1 3/4 cups cups milk (any type, any fat %)","1 tsp vanilla extract or essence","4 tsp butter (, for cooking)"]}]', '[{"title":"Whisk dry","description":"Place flour, baking powder, sugar and salt in a bowl, whisk to combine.","images":[],"step":1},{"title":"Add wet ingredients","description":"Add egg, milk and vanilla. Whisk until lump free - no longer than 30 seconds.","images":[],"step":2},{"title":"Melt then wipe off most butter","description":"Heat a non-stick pan - use medium heat if you have a strong stove, medium high if you have a weak one. Add a tiny bit of butter (about 1/2 tsp) and swirl to melt. Use paper towel to mostly wipe the butter off (this is the trick to avoid a dodgy 1st pancake).","images":[],"step":3},{"description":"Pour 1/4 cup batter into the middle of the fry pan (I use a slightly heaped ice cream scoop with lever, standard is 1/4 cup).","images":[],"step":4},{"title":"Cook","description":"Swirl pan lightly to spread or use the ice cream scoop edge to spread into 11cm / 4.5\" circle (ruler is a must) (joking!). When bubbles rise to the surface (see video), flip and cook the other side until golden.","images":[],"step":5},{"title":"Keep warm and repeat","description":"Remove the pancake and keep warm in a low oven. Use more butter every 2 to 3 pancakes - depends how good your non stick coating is.","images":[],"step":6},{"description":"Serve with toppings of choice!","images":[],"step":7}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["breakfast-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8c5e275e8bde', 'en', 'US', 'No Washing Up Ham, Egg & Cheese Pockets', 'These pockets filled with ham, egg and cheese take 2 minutes to assemble and you won''t have a single dirty dish to wash! No need to measure the filling exactly, just eye ball it. Use this recipe as a base and fill these pockets with whatever you want - salami, cooked bacon, spinach, olives - the possibilities are endless! Tip: Don''t go overboard with the filling, will make it tricky to wrap.', 'https://www.recipetineats.com/tachyon/2016/12/No-Washing-Up-Ham-Cheese-Pockets-8.jpg', 3, 25, 28, 2, '[{"id": "ing_tortillas", "quantity": {"value": 2.0, "unit": "pack of 8"}}, {"id": "ing_ham", "quantity": {"value": 110.0, "unit": "kg"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 0.5, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}]', '[{"ingredients":["2 soft large wraps / tortillas (approx 23 cm / 9\" diameter) (Note 1)","110-150 g / 3.5-5 oz ham slices (Note 3)","1/2 - 2/3 cups grated cheddar or tasty cheese (or any other melting cheese) (Note 2)","2 eggs"]}]', '[{"description":"Preheat oven to 180C/350F (all oven types).","images":[],"step":1},{"description":"Place 2 pieces of foil on a work surface and spray with oil (any).","images":[],"step":2},{"description":"Place tortilla on foil. Place ham in the middle of the tortilla, making sure you arrange it so it is flat, not a mound (harder to keep egg in place). Even better, create a shallow crater shape using off ham off cuts and shavings.","images":[],"step":3},{"description":"Place cheese in the middle of the ham, the form into a ring.","images":[],"step":4},{"description":"Working quickly (one pocket at a time), crack an egg into the ring then fold the bottom and top edges in, then the left and right side to form a package (see video below recipe). Then wrap in foil. DO NOT TURN UPSIDE DOWN!!! (Egg will leak)","images":[],"step":5},{"description":"Place on baking tray.","images":[],"step":6},{"description":"Bake for 25 minutes. Check to ensure yolk is cooked by poking the pocket, you will feel the dome shape of the yolk. The base and edges should be crispy and the top will be soft.","duration":25,"images":[],"step":7},{"description":"Unwrap immediately (otherwise will sweat and lose crispiness). Serve hot!","images":[],"step":8}]', '["egg","milk"]', '["gluten_free","high_protein"]', '{"mealType":["breakfast","lunch"],"cuisine":[],"categories":["breakfast-recipes","egg-recipes","leftover-ham-recipes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_81330b0bdd39', 'en', 'US', 'Spanish Tortilla (Omelette)', 'The famed Spanish Omelette (Tortilla) is made with just eggs, potato, onions and olive oil! The unique step in this recipe is the way the potato is cooked - slices of potato are "stewed" in olive oil which makes them beautifully creamy, almost like they have been confited. The Spanish Omelette is not only served for breakfast and lunch, it is also commonly served as part of a Tapas spread!', 'https://www.recipetineats.com/tachyon/2016/08/Spanish-Omelette-Tortilla_1.jpg', 15, 45, 60, 6, '[{"id": "ing_potato", "quantity": {"value": 750.0, "unit": "bag of 2kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 8.0, "unit": "carton of 12"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["750 g / 1.5 lb potatoes ((Note 1), peeled and cut into 0.5cm / 1/5\" thick slices)","1 onion (, sliced)","1/2 cup / 125 ml olive oil","8 eggs","Salt and pepper","Fresh parsley"]}]', '[{"description":"Heat oil in a non stick fry pan over medium heat. Add onion and potatoes, then turn over.,Place a lid on and stew the potatoes gently for 20 minutes or so, turning the potatoes 3 or 4 times with an egg flip until soft and cooked through. If the potatoes sizzle and are browning, turn the heat down.","duration":20,"images":[],"step":1},{"description":"Meanwhile, whisk eggs then season with salt and pepper.","images":[],"step":2},{"description":"When potatoes are ready, remove with a slotted spoon into a colander to allow excess oil to drain away.","images":[],"step":3},{"description":"Pour out most of the remaining oil in the skillet, leaving behind about 1 1/2 - 2 tbsp of oil.","images":[],"step":4},{"description":"Turn stove up to medium high. Turn grill/broiler onto high.","images":[],"step":5},{"description":"Return potatoes to the skillet, then pour over the egg. Cook for 5 minutes or until the underside is light golden.","duration":5,"images":[],"step":6},{"description":"If the centre is still uncooked, which mine almost always is, pop the omelette under the grill/broiler for a couple of minutes until the centre is just set.","images":[],"step":7},{"description":"Remove then rest for a few minutes. Place a serving platter on top of the fry pan then flip to turn out the omelette upside down.","images":[],"step":8},{"description":"Serve warm or at room temperature (I prefer warm!).","images":[],"step":9},{"description":"I served this as part of a Tapas Spread!","images":[],"step":10}]', '["egg"]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["breakfast"],"cuisine":["Spanish"],"categories":["breakfast-recipes","dietary","easter-brunch-recipes","gluten-free-recipes","mediterranean-recipes","spanish-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5d4e0f008552', 'en', 'US', 'Nutella Crêpes', 'Soft, buttery crêpes filled with warm melty Nutella and fresh slices of strawberries. What a combination!Serve for dessert, snack or a special treat for breakfast. The crêpe recipe is JB''s - see here for his full recipe including a tutorial video for how to make crêpes.The crepes can be made in advance - cool then store covered in the fridge for up to 3 days. Warm gently either on the stove or microwave, then assemble the Nutella crepes.', 'https://www.recipetineats.com/tachyon/2016/08/Strawberry-Nutella-Crepes_1.jpg', 10, 25, 95, 15, '[{"id": "ing_flour", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 250.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 45.0, "unit": "block of 250g"}}, {"id": "ing_nutella", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_strawberries", "quantity": {"value": 2.0, "unit": "punnet of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.045, "unit": "kg"}}]', '[{"ingredients":["1 2/3 cups plain flour / all-purpose flour (, sifted)","3 tbsp caster sugar / superfine sugar (, regular white sugar is fine too)","1/4 tsp cooking salt / kosher salt","3 large eggs (, (55g/2oz each in shell) - fridge cold is fine)","2 cups full fat milk (, but works with lite milk too)","1/3 cup water (Note 1)","2 tbsp vegetable oil or other neutral flavoured oil (Note 1)","45 g (3 tbsp) unsalted butter (, cut into small cubes (for cooking))"]},{"ingredients":["1 - 2 tbsp Nutella (, homemade or store-bought)","2 strawberries (, sliced)","Icing sugar / powdered sugar (, for dusting)"],"purpose":"For Nutella Crepes – per crepe"}]', '[{"description":"Abbreviated recipe","images":[],"step":1},{"description":"Whisk flour, sugar and salt. Add eggs then milk, water, oil and whisk into a smooth batter. Cover and rest for an hour. Cook in a lightly buttered non-stick pan, swirling ¼ cup batter to cover the surface. Cook for 1 minute. Flip, cook for 30 seconds. Spread with Nutella, top with strawberries. Fold into quarters, serve dusted with icing sugar!","duration":1,"images":[],"step":2},{"description":"Make the batter","images":[],"step":3},{"description":"Sift flour into a large mixing bowl. Add sugar and salt, then whisk to combine.","images":[],"step":4},{"description":"Make a well in the centre and add the eggs. Whisk gently and only mix in a bit of the flour. You can’t blend all the flour with just the eggs yet, so just mix in enough to make a thick paste.","images":[],"step":5},{"description":"Gradually add the milk, whisking between each addition to create a smooth batter with no lumps.","images":[],"step":6},{"description":"Whisk in the water and oil until the batter is glossy and pourable. When you dip a spoon in, it should coat the back lightly. Not too thick, not too runny. (Note 1)","images":[],"step":7},{"description":"Cover and rest for 1 hour at room temperature. (Note 2)","images":[],"step":8},{"description":"Cook the crêpes","images":[],"step":9},{"description":"Heat a 24cm / 9.5\" non-stick crêpe pan over medium-high heat (medium if your stove runs hot). If you don’t have one, any good non-stick pan will work, just adjust how much batter you pour in depending on the size, so it spreads nicely without being too thick or thin.","images":[],"step":10},{"description":"Melt about 1/2 tsp butter, then wipe it off with a paper towel, you want just a little of butter left, no visible pools. (Note 3)","images":[],"step":11},{"title":"Pour the batter","description":"Using a ladle, scoop up ¼ cup of batter, lift the pan off the heat, ladle most of the batter into the centre, and immediately swirl the pan so the batter coats the surface in a thin, even layer. Still while swirling, use the rest of the batter to fill up the empty spots before it sets. Tilting quickly gives you uniform crêpes.","images":[],"step":12},{"description":"Cook for 45 seconds to 1 minute until the underside is lightly golden and flip using a long spatula and cook the other side for about 30 seconds. (Note 4 & 5)","duration":0.75,"images":[],"step":13},{"description":"Slide onto a plate, then repeat, adding butter each time.","images":[],"step":14},{"description":"Spread as much or as little Nutella on a crepe as you want. Place strawberries on one half. Fold into quarters, transfer to plate. Repeat for as many as you want. Dust with icing sugar, serve!","images":[],"step":15}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert","snack"],"cuisine":["French"],"categories":["breakfast-recipes","dessert-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_06f8a60de1ea', 'en', 'US', 'Bill Grangers Corn Fritters with Avocado Salsa', 'These are the legendary Bill Granger Corn Fritters with Avocado Salsa. The extra step that makes these corn fritters really special is blending some of the corn and cilantro (coriander) into the batter - it makes the whole fritter truly taste of corn, rather than just bursts of it when you bite into kernels. This recipe makes 12 fritters and serves 4.', 'https://www.recipetineats.com/tachyon/2016/04/Bill-Granger-Corn-Fritters-close-up.jpg', 10, 15, 25, 4, '[{"id": "ing_corn", "quantity": {"value": 1.125, "unit": "can of 400g"}}, {"id": "ing_onion", "quantity": {"value": 30.0, "unit": "pack of 1kg"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_chilli_flakes", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.033, "unit": "tub of 150g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_tomato", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_tabasco_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}]', '[{"ingredients":["3 cups fresh corn kernels (~ 3 large corn cobs)","1 small red onion chopped","2 large eggs (55 - 60g/2oz each)","1/4 cup cilantro/coriander leaves and some stems (lightly packed)","1/2 tsp cooking salt ((kosher salt), or 1 tsp sea salt flakes)","Freshly ground Black pepper","1 cup plain flour (all-purpose flour)","1 tsp baking powder","3 tbsp olive oil"]},{"ingredients":["1 large ((or 2 small) ripe avocado, stone removed and diced)","1 1/2 tomatoes (, seeded and diced (about 3/4 cup, diced))","2 tbsp coriander/cilantro (, roughly chopped)","2 tbsp lemon or lime juice","2 tbsp finely chopped spring onions scallions or red onion","1 dash Tabasco sauce (, optional)","1/4 tsp cooking salt (/ kosher salt (1/2 tsp sea salt flakes))","Freshly ground Black pepper"],"purpose":"Avocado Salsa"}]', '[{"title":"Turn on the oven to very low","description":"just to keep the fritters warm.","images":[],"step":1},{"description":"Place 2 cups of the corn kernels and the onion, eggs, coriander, salt and pepper in a bowl and whizz with a stick blender until most of the corn is pureed (but still lumpy, not completely smooth). You can also do this step in a blender or food processor.","images":[],"step":2},{"description":"Stir through remaining corn, flour and baking powder until just combined.","images":[],"step":3},{"description":"Heat 1 tablespoon of the oil in a skillet/fry pan over a medium high heat.","images":[],"step":4},{"description":"When the oil is hot, drop 2 heaped tablespoons of mixture per fritter into the pan and cook in batches for 1 1/2 minutes each side, or until golden.","images":[],"step":5},{"description":"Transfer to a baking tray and keep warm in the oven while you are making the rest of the fritters.","images":[],"step":6},{"description":"To serve, stack 3 corn fritters on each plate and top with avocado salsa and extra cilantro/coriander leaves if desired.","images":[],"step":7},{"description":"Combine all ingredients, toss very gently.","images":[],"step":8}]', '["egg","gluten"]', '["vegan","vegetarian"]', '{"mealType":["breakfast"],"cuisine":["Western"],"categories":["breakfast-recipes","dinner-tonight","fritters-tots-and-similar","main-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8cd78c8ce106', 'en', 'US', 'Caprese Baked Eggs', 'Caprese - for breakfast! Though I''d happily have this for lunch or dinner. :) I like to melt most of the bocconcini and reserve a few slices to top it just before serving. But it''s entirely up to you!', 'https://www.recipetineats.com/tachyon/2016/02/Caprese-Baked-Eggs_1.jpg', 10, 30, 40, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_cannellini_beans", "quantity": {"value": 396.9, "unit": "pack"}}, {"id": "ing_tomato", "quantity": {"value": 0.198, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_mixed_italian_herbs", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 0.794, "unit": "punnet of 250g"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_bocconcini", "quantity": {"value": 6.0, "unit": "unit"}}, {"id": "ing_egg", "quantity": {"value": 4.0, "unit": "carton of 12"}}, {"id": "ing_balsamic_vinegar", "quantity": {"value": 0.667, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","½ small onion (, diced (brown, white or yellow))","14 oz / 400g can cannellini beans (or other beans of choice)","14 oz / 400g can crushed tomato","¼ cup chicken broth/stock (or water)","1 tbsp mixed Italian herbs (, dried (Note 1 for substitution))","½ tsp sugar (optional) (Note 2)","Salt and pepper","7 oz / 200g cherry tomatoes (1/2 punnet)","½ cup (packed) basil leaves roughly torn","6 oz / 180g bocconcini (, sliced OR buffalo mozzarella, torn (Note 3))","4 eggs"]},{"ingredients":["2/3 cup balsamic vinegar","2 tbsp brown sugar","Salt"],"purpose":"Balsamic Syrup"},{"ingredients":["Toasted crusty bread slices"],"purpose":"To Serve"}]', '[{"description":"Heat oven to 180C/350F. Heat olive oil in a medium skillet over medium high heat.","images":[],"step":1},{"description":"Add garlic and onion and sauté for 3 minutes or until translucent.","duration":3,"images":[],"step":2},{"description":"Add cannellini beans, tomato, chicken broth, herbs, sugar, salt and pepper. Bring to simmer, turn down heat to medium and cook for 3 minutes, stirring occasionally. Adjust salt, pepper and sugar to taste. Stir through HALF the basil.","duration":3,"images":[],"step":3},{"description":"Make dents in the mixture using the back of a wooden spoon. Crack eggs into the dent. Top with cherry tomatoes and most of the bocconcini around the eggs.","images":[],"step":4},{"description":"Transfer to the oven. Bake for 15 minutes or until whites are just set but yolks are still runny (or to taste).","duration":15,"images":[],"step":5},{"description":"Sprinkle over remaining basil and bocconcini cheese. Either drizzle the Balsamic Syrup over in the skillet or serve on the side for people to help themselves. Serve with crusty bread!","images":[],"step":6},{"description":"Place balsamic vinegar, sugar and salt in a small frypan or saucepan over medium high heat. Bring to simmer then turn down to medium. Simmer for 4-5 minutes, stirring occasionally, until syrupy. It''s ready when your spatula leaves a path when you run it across the bottom of the frypan. Set aside until required. Use hot or at room temperature - it thickens as it cools.","duration":4.5,"images":[],"step":7}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["breakfast"],"cuisine":["Italian","Western"],"categories":["breakfast-recipes","dietary","egg-recipes","gluten-free-recipes","italian-recipes","most-popular","quick-and-easy","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_fdacd101645d', 'en', 'US', 'Sausage & Bacon Country Breakfast Casserole', 'Breakfast for an army! Great for making ahead AND it reheats well too. Tastes just like a country fry up breakfast with all the essentials - bacon, eggs, sausages, potatoes and bread! This serves 6 very generously, or 8 (normal servings).', 'https://www.recipetineats.com/tachyon/2015/12/Sausage-Bacon-Country-Breakfast-Casserole_5.jpg', 20, 40, 60, 6, '[{"id": "ing_bread", "quantity": {"value": 2.5, "unit": "loaf"}}, {"id": "ing_egg", "quantity": {"value": 7.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_potato", "quantity": {"value": 10.0, "unit": "bag of 2kg"}}, {"id": "ing_bacon", "quantity": {"value": 1.417, "unit": "pack of 200g"}}, {"id": "ing_sausages", "quantity": {"value": 0.907, "unit": "pack of 500g"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["2.5 ft / 80 cm baguette ((french stick), preferably slightly stale)","7 eggs","1 1/2 cups milk (full fat) or half and half (I use milk)","10 oz / 300 g potatoes (, peeled and diced into 1/2\" / 1.2cm cubes)","10 oz / 300 g bacon (, roughly chopped)","1 lb / 500 g sausage (, removed from casing (use good quality - Note 1))","1 cup grated cheddar cheese","1 tbsp butter (, melted (optional))","Finely chopped parsley (optional)"]}]', '[{"description":"Slice the baguette into 2cm / 0.8\" thick slices and place in a baking dish.","images":[],"step":1},{"description":"Whisk the eggs and milk together. Pour 2/3 of the egg mixture over the bread. Turn the bread to make sure both sides of every piece is soaked in egg mixture. Set aside to soak while you cook the bacon and sausage.","images":[],"step":2},{"description":"Cook potatoes in boiling water for 2 minutes.","duration":2,"images":[],"step":3},{"description":"Preheat oven to 180C/350F.","images":[],"step":4},{"description":"Heat skillet over high heat. Add bacon and cook until very lightly cooked. Remove with a slotted spoon and drain on paper towels.","images":[],"step":5},{"description":"Pour off excess fat. Add sausage and cook, breaking it up as you go, until lightly browned. Remove from the skillet and drain on paper towels.","images":[],"step":6},{"description":"By now, most of the egg mixture should be soaked up by the bread. Stand the bread upright in the baking dish.","images":[],"step":7},{"description":"Distribute half the potato between the bread, then top with half the sausage, half the bacon and half the cheese. Repeat with remaining potato, sausage, bacon and cheese (finish with cheese).","images":[],"step":8},{"description":"Pour remaining egg mixture over everything.","images":[],"step":9},{"description":"Cover loosely with foil and bake for 30 minutes.","duration":30,"images":[],"step":10},{"description":"Remove foil and drizzle butter over the bread.","images":[],"step":11},{"description":"Bake for a further 10 minutes until the bread is golden. Serve, garnished with parsley if using.","images":[],"step":12}]', '["egg","milk"]', '["gluten_free","high_protein"]', '{"mealType":["breakfast"],"cuisine":[],"categories":["breakfast-recipes","casseroles-and-cosy-bakes","easter-brunch-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d2e2edba1cb6', 'en', 'US', 'Leftover Mashed Potato Cheese & Bacon Cakes', 'This might be called "Leftover Mashed Potato" cakes but most of the time, I will make mashed potatoes especially to make these! Great for breakfast, lunch OR dinner! I made these with bacon but they''re also lovely with canned tuna (drained of oil) or even diced cooked chicken or any other protein.', 'https://www.recipetineats.com/tachyon/2015/11/Leftover-Mashed-Potato-Cheese-Bacon-Cakes_Featured-Image.jpg', 15, 6, 21, 12, '[{"id": "ing_potato", "quantity": {"value": 2.0, "unit": "bag of 2kg"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_bacon", "quantity": {"value": 1.134, "unit": "pack of 200g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.5, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 0.375, "unit": "loaf"}}, {"id": "ing_oil", "quantity": {"value": 4.0, "unit": "bottle"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["2 - 2 1/2 cups mashed potato (, cold)","1 large egg or 2 small eggs","1/3 cup plain flour","1 cup grated melting cheese","8 oz / 250g bacon (, diced)","1/2 cup scallions/shallots (, thinly sliced)","1/4 tsp salt"],"purpose":"Potato Cakes"},{"ingredients":["2 cups panko breadcrumbs OR 3/4 cup plain flour","4 to 6 tbsp oil (any cooking oil)","Pepper"],"purpose":"Cooking"}]', '[{"description":"Mix together the Potato Cake ingredients in a bowl until just combined.","images":[],"step":1},{"description":"Spread the panko or flour out on a large plate or baking tray (to fit 6 patties).","images":[],"step":2},{"description":"Measure out 1/4 cup level amount of potato mixture OR a slightly heaped ice cream scooper (this is what I use because using the lever, it pops out easily) and drop onto panko/flour. Repeat to fill plate / baking tray (don''t crowd, difficult to handle).","images":[],"step":3},{"description":"Use an egg flip (or base of cup) to pat it down to 1.5cm/2/3\" thick patties, then flip and pat to coat the other side with panko/flour. Set aside and repeat with remaining potato mixture.","images":[],"step":4},{"description":"Heat 1/2 the oil in a large skillet over medium high heat. Cook 6 patties at a time until golden brown on each side - around 2 minutes, then flip and cook the other side.","images":[],"step":5},{"description":"Remove onto a paper towel lined baking tray. Cook remaining patties.","images":[],"step":6},{"description":"Serve hot!","images":[],"step":7}]', '["egg","gluten","milk"]', '[]', '{"mealType":["breakfast"],"cuisine":[],"categories":["breakfast-recipes","quick-and-easy","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3df0fab7105a', 'en', 'US', 'Whole Egg, Bacon and Avocado Quesadilla', 'Breakfast quesadillas just got a whole lot more interesting!', 'https://www.recipetineats.com/tachyon/2015/09/Egg-Bacon-Avocado-Quesadilla_600px_1_Featured.jpg', 5, 15, 20, 4, '[{"id": "ing_bacon", "quantity": {"value": 3.0, "unit": "pack of 200g"}}, {"id": "ing_tortillas", "quantity": {"value": 4.0, "unit": "pack of 8"}}, {"id": "ing_egg", "quantity": {"value": 4.0, "unit": "carton of 12"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_cheese", "quantity": {"value": 0.5, "unit": "block of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["3 rashers of streaky bacon (, chopped)","4 flour tortillas (Note 1)","4 eggs","1 large avocado (, halved and sliced)","1/2 cup grated cheese (I used cheddar)","Salt and pepper"]}]', '[{"description":"Heat a skillet over high heat. Add the bacon and cook until cooked to your liking. Remove bacon onto a paper towel lined plate.","images":[],"step":1},{"description":"Drain excess fat from the skillet and wipe away/scrape off any black bits. Return to the stove over medium heat.","images":[],"step":2},{"description":"Place a tortilla in the skillet. Place avocado slices around the rim of half the tortilla and thinner slices across the middle to form a \"ring\" to hold the egg - as per the photo below. Squish the pieces close together to seal them so egg does not leak.","images":[],"step":3},{"description":"Crack an egg into the centre, sprinkle with bacon, cheese and season with salt and pepper. Fold the tortilla over and cook for 4 minutes or until golden and crisp. I usually cook 2 in the skillet.","duration":4,"images":[],"step":4},{"description":"Flip, turning over the folded edge (i.e. slide the flip under the curved edge and flip over the folded edge). Cook the other side for 3 minutes or until golden and crisp. Remove from the skillet. Repeat with remaining tortillas.","duration":3,"images":[],"step":5},{"description":"Serve immediately, while hot!","images":[],"step":6}]', '["egg","gluten","milk"]', '[]', '{"mealType":["breakfast","lunch"],"cuisine":[],"categories":["breakfast-recipes","dietary","egg-recipes","gluten-free-recipes","mexican-recipes","most-popular","quesadillas","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_417a52ef18f5', 'en', 'US', 'Crispy Cheesy Sausage Hash Browns', 'Loaded hash browns! These are made with sausage and cheese mixed throughout the shredded potato, then panfried until golden. Great for make ahead and as finger food for parties! ! PS This is also sensational made with chorizo. Ugh. It''s so good that it''s painful!', 'https://www.recipetineats.com/tachyon/2015/08/Cheesy-Sausage-Hash-Browns_Featured.jpg', 10, 18, 28, 13, '[{"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_oil", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_sausages", "quantity": {"value": 0.454, "unit": "pack of 500g"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 0.75, "unit": "block of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.5, "unit": "bunch"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1 lb / 500g potato (, about two large (Note 1))","2 1/2 tbsp oil","8 oz / 250g sausage (, remove from casings (the best quality you can afford))","3/4 cup grated cheddar cheese (or any other melting cheese, but not mozzarella)","1/2 cup sliced scallions/shallots (green and white part)","1 egg","1/4 cup flour","Pepper"]}]', '[{"description":"Peel and shred the potato using a standard box grater.","images":[],"step":1},{"description":"Place the potato in a colander and run under cold water for 10 seconds, or until the water runs clear.","duration":0.16666666666666666,"images":[],"step":2},{"description":"Shake off excess water, then transfer the potato to a clean tea towel. Bundle it up and squeeze hard to remove excess water, then transfer to a bowl.","images":[],"step":3},{"description":"Heat 1/2 tbsp of oil in a skillet over high heat. Cook the sausage, breaking it up as you go (like cooking ground meat/mince).","images":[],"step":4},{"description":"Add sausage to potatoes. Add remaining ingredients and mix to combine.","images":[],"step":5},{"description":"Wipe the skillet clean with a paper towel, discarding excess fat. Heat 1 tbsp oil in a skillet over medium high heat.","images":[],"step":6},{"description":"Place 1/4 cup of mixture in the skillet, and use the base of the cup measure to pat it down to about 8mm / 1/3\" thickness. Repeat for however many you can fit in the skillet.","images":[],"step":7},{"description":"Cook until deep golden brown (about 3 minutes), then flip and cook the other side until golden brown and crispy.","images":[],"step":8},{"description":"Remove onto a rack and place in a low oven to keep warm while you cook the remaining hash browns.","images":[],"step":9},{"description":"Serve hot, garnished with extra scallions/shallots if desired.","images":[],"step":10}]', '["egg","gluten","milk"]', '["keto_friendly","low_calorie"]', '{"mealType":["breakfast"],"cuisine":[],"categories":["breakfast-recipes","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_28009d8d9d11', 'en', 'US', 'Bacon, Egg and Mushroom Tart (Puff Pastry)', 'A fancy looking tart that is actually very easy to put together! Great for making ahead for a brunch with friends and family. The topping possibilities are endless! I used Gruyere cheese in this which has a slightly nutty flavour. But you can use any melting cheese that you want. This recipe makes 2 of the pictured tart.', 'https://www.recipetineats.com/tachyon/2015/08/Bacon-Egg-Mushroom-Puff-Pastry-Tart_Hero.jpg', 15, 20, 35, 4, '[{"id": "ing_egg", "quantity": {"value": 5.0, "unit": "carton of 12"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.12, "unit": "tub of 250g"}}, {"id": "ing_gruyere_cheese", "quantity": {"value": 0.667, "unit": "block of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_sheet_frozen_puff_pastry", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.142, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 6.0, "unit": "pack of 200g"}}]', '[{"ingredients":["5 eggs","1 tbsp Dijon mustard","2 tbsp thick sour cream or creme fraiche (or sub with mayonnaise)","2/3 cup grated gruyere cheese (, separated (2 x 1/3 cup) (or any other melting cheese))","Salt and pepper","1 sheet store bought frozen puff pastry (, thawed (25 cm x 25cm / 10\" x 10\"))","1 tbsp butter (salted or unsalted)","5 oz / 150g mushrooms (, sliced (approximately 2 cups of sliced mushrooms))","6 - 8 oz / 200 - 250 g bacon (, roughly chopped)"]}]', '[{"description":"Preheat oven to 180C/350F. Spray a baking tray lightly with oil.","images":[],"step":1},{"description":"Separate the egg yolk and whites of one egg. Place the yolk in a bowl and place the whites in another bowl.","images":[],"step":2},{"description":"To the egg yolk, add the mustard, sour cream, 1/3 cup cheese, salt and pepper. Mix then set aside.","images":[],"step":3},{"description":"Lightly whisk together the egg white leftover from the Cheese Spread (above) with the remaining 4 eggs.","images":[],"step":4},{"description":"Cut the puff pastry in half. Use a knife to score a 1cm / 1/3\" border (see photo below). (Note 1) Transfer to baking tray.","images":[],"step":5},{"description":"(Optional) Dip a brush into the egg mixture and lightly brush over the border (makes it extra golden).","images":[],"step":6},{"description":"Spread the Cheese Spread within the border. Sprinkle over the remaining cheese.","images":[],"step":7},{"description":"Bake for 20 minutes or until golden and the edges are puffed. The cheese centre will bubble and puff up while in the oven, but will settle down once out of the oven","duration":20,"images":[],"step":8},{"description":"While the pastry is baking, make the Toppings (below).","images":[],"step":9},{"description":"Remove from the oven. (Note 2) Divide the scrambled eggs between the tarts, staying within the border. Top with mushrooms then pile the bacon on.","images":[],"step":10},{"description":"Bake for a further 5 minutes or until the puff pastry is a deep golden brown.","images":[],"step":11},{"description":"Remove from oven and serve immediately!","images":[],"step":12},{"description":"Melt butter in a non stick frypan over medium heat. Add the eggs and leave them for 20 seconds until starting to set, then slowly start folding them in from the outside in. Stir gently and continue folding until just set but still wet. Season with salt and pepper then remove from the frypan.","duration":0.3333333333333333,"images":[],"step":13},{"description":"Return frypan to the stove and increase to high heat. Add the bacon and cook until light golden brown. Remove from the pan but reserve bacon fat (drain if there is excess).","images":[],"step":14},{"description":"Add the mushrooms to the bacon fat and cook for a few minutes until softened but not soggy. Sprinkle with salt and pepper. Remove skillet from the stove and set aside (you can leave the mushrooms in).","images":[],"step":15}]', '["egg","milk","mustard"]', '["gluten_free","high_protein"]', '{"mealType":["breakfast"],"cuisine":[],"categories":["breakfast-recipes","easter-brunch-recipes","egg-recipes","mushroom-recipes","pork-recipes","quiches-tart-and-pie-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_68389858cce4', 'en', 'US', 'Smoked Salmon and Egg Breakfast Mille-feuille', 'My breakfast interpretation of the classic French dessert, Mille-feuille! Super fast to prepare, this is a great breakfast to impress friends and family. Makes 8 - I find 2 per serving is sufficient.', 'https://www.recipetineats.com/tachyon/2015/07/Breakfast-Mille-feuille_600px_5-Main_Featured-Image.jpg', 5, 25, 30, 8, '[{"id": "ing_sheet_frozen_puff_pastry", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_egg", "quantity": {"value": 8.0, "unit": "carton of 12"}}, {"id": "ing_cream", "quantity": {"value": 0.25, "unit": "carton of 250ml"}}, {"id": "ing_salt", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_salmon_fillets", "quantity": {"value": 0.17, "unit": "kg"}}, {"id": "ing_cr_me_fra_che_plus_more_for_serving", "quantity": {"value": 0.667, "unit": "unit"}}, {"id": "ing_chives", "quantity": {"value": 0.03, "unit": "kg"}}]', '[{"ingredients":["1 sheet store bought frozen puff pastry (, thawed (25 cm x 25cm / 10\" x 10\"))"]},{"ingredients":["8 eggs","1/4 cup cream or full cream milk (double this for creamier eggs - Note 1)","1/2 to 3/4 tsp salt","Black pepper","2 tbsp butter"],"purpose":"Scrambled Eggs"},{"ingredients":["6 oz / 200g smoked salmon","2/3 cup crème fraîche (Note 2), plus more for serving (optional)","2 tbsp chives (, finely chopped, plus more for garnish)"],"purpose":"Mille-feuille"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Cut the puff pastry in half, then each half into 4 pieces to make 8 pieces that are 6 cm x 12.5 cm / 2.5\" x 5\".","images":[],"step":2},{"description":"Place on a baking tray lined with parchment paper (baking paper) or sprayed with oil.","images":[],"step":3},{"description":"Whisk the eggs in a bowl. Then brush the puff pastry with the eggs, taking care not to brush the cut sides (optional step - makes the pastry more golden).","images":[],"step":4},{"description":"Bake for 15 to 20 minutes, or until puffed and golden.","duration":17.5,"images":[],"step":5},{"description":"Remove from the oven and split each piece in half horizontally (so you have a top and bottom).","images":[],"step":6},{"description":"Place on a rack to cool.","images":[],"step":7},{"description":"Scrambled Eggs","images":[],"step":8},{"description":"Whisk the cream into the eggs.","images":[],"step":9},{"description":"Melt butter in a pan over medium heat if you have gas or medium high for electric. Don''t let the butter brown. Add the eggs and don''t touch it for 20 seconds.","duration":0.3333333333333333,"images":[],"step":10},{"description":"Then use a wooden spoon with a flat edge (or egg flip) to gently scrape the bottom and fold the eggs over. Continue to do this for 30 seconds to 1 minute, until the eggs are mostly cooked but still wet.","duration":0.5,"images":[],"step":11},{"description":"Turn the stove off, add salt and pepper and keep folding until the eggs are just before done to your liking (they will continue to cook for a bit). Remove from the stove.","images":[],"step":12},{"description":"Mix the crème fraîche and chives together in a small bowl.","images":[],"step":13},{"description":"Place the bottom half of each puff pastry piece on a serving platter. Divide the eggs between them, top with smoked salmon then spread with crème fraîche mixture. Place the top half of the puff pastry on the salmon.","images":[],"step":14},{"description":"Serve immediately with extra crème fraîche on the side, if desired.","images":[],"step":15}]', '["egg","fish","milk"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["breakfast"],"cuisine":[],"categories":["breakfast-recipes","egg-recipes","fish-recipes","salmon-recipes","seafood-recipes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e74f6eaee78e', 'en', 'US', 'Cheese and Bacon Bread Boats', 'This tastes just like a quiche - only better because it''s CRUSTIER! (And much faster to make!). This freezes really well (once cooked). Wrap it in foil and you can pop it straight into the oven to reheat from frozen. The filling possibilities are endless! I''ve provided a few suggestions in the notes.', 'https://www.recipetineats.com/tachyon/2015/07/Cheese-Bacon-Egg-Boats_680px_1.jpg', 5, 20, 25, 2, '[{"id": "ing_bacon", "quantity": {"value": 0.284, "unit": "pack of 200g"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_cream", "quantity": {"value": 0.12, "unit": "carton of 250ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 2.0, "unit": "loaf"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 0.25, "unit": "block of 250g"}}]', '[{"ingredients":["2 oz / 60g bacon (, diced)","2 large or 3 small eggs","2 tbsp cream or milk","Salt and pepper (pinch of each)","2 baguettes (, about 20 / 8\" long and 6cm / 2.5\" in diameter)","1 tbsp melted butter (, for brushing or oil spray (optional))","2 tbsp finely chopped/sliced shallots/scallions or jalapeños (or 1 tbsp fresh herb of choice) (optional)","1/4 cup cheddar or tasty cheese (, grated (or any other flavoured cheese that melts))"]}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Heat a non stick pan over high heat. Cook the bacon until lightly browned, then drain on a paper towel and set aside.","images":[],"step":2},{"description":"Whisk together the eggs, cream and salt and pepper in a jug.","images":[],"step":3},{"description":"Cut a \"V\" shape out of each baguette. Pull some bread out, leaving about 1/2\" / 1.25cm thick base.","images":[],"step":4},{"description":"Brush crust of the bread with melted butter. (Optional - this makes the bread extra golden and buttery)","images":[],"step":5},{"description":"Place the bread on a baking tray.","images":[],"step":6},{"description":"Carefully pour half the egg mixture into the crevice of each baguette. Leave it for a couple of minutes to soak into the bread a bit.","images":[],"step":7},{"description":"Divide the bacon and shallots between each baguette. Then sprinkle over half the cheese (reserve the other half to put on top).","images":[],"step":8},{"description":"Carefully pour the remaining egg mixture into each baguette. Pour slowly, giving the egg time to sink into the filling. Top with remaining cheese.","images":[],"step":9},{"description":"Bake at 350F/180C for 20 to 25 minutes, or until light golden brown on top and the egg does not \"jiggle\" when you shake the baguette.","duration":22.5,"images":[],"step":10},{"description":"Serve whole or sliced.","images":[],"step":11}]', '["egg","milk"]', '["gluten_free"]', '{"mealType":["breakfast"],"cuisine":[],"categories":["breakfast-recipes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_288ca7049f2a', 'en', 'US', 'Nutella Stuffed Pancakes', 'Pancakes stuffed with Nutella! Best eaten warm but still fabulous at room temperature. Great treat for special occasions! Makes 6 to 7 pancakes.', 'https://www.recipetineats.com/tachyon/2015/06/Nutella-Stuffed-Pancakes_680px_1.jpg', 10, 20, 30, 6, '[{"id": "ing_nutella", "quantity": {"value": 10.0, "unit": "unit"}}, {"id": "ing_flour", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.1, "unit": "tub of 150g"}}, {"id": "ing_sugar", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_vanilla_essence", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_strawberries", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}]', '[{"ingredients":["10 - 14 tbsp Nutella"]},{"ingredients":["1 1/2 cups plain flour","3 tsp baking powder","4 tbsp sugar","Pinch of salt"],"purpose":"Dry Ingredients"},{"ingredients":["1 egg","1cup + 2 tbsp milk (I used low fat)","1 tsp vanilla essence (optional)"],"purpose":"Wet Ingredients"},{"ingredients":["1 tsp butter (, separated (2 x 1/2 tsp))","Sliced strawberries (optional)"],"purpose":"Other"}]', '[{"description":"Frozen Nutella Disc","images":[],"step":1},{"description":"Line a baking tray with baking paper (parchment paper).","images":[],"step":2},{"description":"Dollop 1 1/2 to 2 tbsp of Nutella onto the baking tray and spread into a disc around 2 1/2\" / 6cm in diameter and 1/5\" / 1/2 cm thick. (Note 1) Repeat to make 7 discs.","images":[],"step":3},{"description":"Place the tray in the freezer until firm (around 1 to 1 1/2 hours).","images":[],"step":4},{"description":"Peel off the parchment paper. Keep the Nutella discs in the freezer until required (they soften quickly).","images":[],"step":5},{"description":"Place the Dry Ingredients in a bowl and whisk to combine.","images":[],"step":6},{"description":"Make a well in the centre and place the Wet Ingredients in the well. Whisk until combined and lump free (stop whisking as soon as it is smooth, don''t over whisk).","images":[],"step":7},{"description":"Melt 1/2 tsp butter in a non stick fry pan over medium heat. Once melted, wipe most of the butter off with a paper towel. (Note 2)","images":[],"step":8},{"description":"Take 3 Frozen Nutella Discs out of the freezer just before you start cooking. (Note 3)","images":[],"step":9},{"description":"Dollop 1/4 cup of batter into the fry pan. Working quickly, place 1 Frozen Nutella Disc in the middle of the batter, then top with batter to cover the Nutella disc (Note 4).","images":[],"step":10},{"description":"When bubbles start appearing around the edges (around 2 minutes), lift up the edge and make sure the underside is golden. Then flip and cook until the other side is golden.","images":[],"step":11},{"description":"Repeat with remaining batter. Melt more butter in the pan after the 3rd or 4th pancake. You should be able to make 7 in total, but sometimes it makes 6 - depends on how much batter you use on top of the Nutella.","images":[],"step":12},{"description":"Serve warm with sliced strawberries, if using. You could also serve with cream but I find that it''s not necessary!","images":[],"step":13}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["breakfast"],"cuisine":[],"categories":["breakfast-recipes","most-popular"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0756a87978af', 'en', 'US', 'Cream Cheese Stuffed French Toast', 'A baked french toast in the form of a loaf with a cream cheese filling! It tastes like a cheesecake baked into a french toast! The french toast is soft, custardy and buttery and not overly sweet because the richness and sweetness comes from the cream cheese filing. The top of the loaf has a crunchy, sweet crust which is reminiscent of the golden crust you get from traditional pan fried french toast. Serving with strawberries is optional. There is plenty of flavour already!', 'https://www.recipetineats.com/tachyon/2015/05/DSC_0137.jpg', 15, 40, 55, 6, '[{"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_cream_cheese", "quantity": {"value": 250.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_egg", "quantity": {"value": 4.0, "unit": "carton of 12"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_egg", "quantity": {"value": 4.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 12.0, "unit": "loaf"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_strawberries", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}]', '[{"ingredients":["Butter (, for greasing)"]},{"ingredients":["250 g / 8oz cream cheese (, at room temperature)","1/3 cup sugar (white)","1 tsp vanilla extract","1 egg","2 tbsp lemon juice"],"purpose":"Cream Cheese Filling"},{"ingredients":["4 eggs","3/4 cup + 2 tbsp milk (low fat or full fat)","3 tbsp sugar (white)","Pinch of salt"],"purpose":"Egg Mixture"},{"ingredients":["12 fresh slices sandwich bread (crusts removed) (Note 1)","2 tbsp butter (, diced (optional) (Note 2))","2 tbsp brown sugar (optional) (Note 2)"],"purpose":"French Toast Bake"},{"ingredients":["1 punnet strawberries (, sliced)","1 tbsp sugar"],"purpose":"Macerated Strawberries (optional - Note 3)"}]', '[{"description":"Preheat oven to 180C/350F. Generously butter a 10cm x 21cm / 4\" x 8\" loaf tin","images":[],"step":1},{"title":"Make Cream Cheese Filling","description":"beat (or mix) the cream cheese, sugar and vanilla until combined. Then add the egg and lemon juice, then beat/mix until smooth, light and fluffy.","images":[],"step":2},{"description":"Whisk the Egg Mixture ingredients together in a large bowl.","images":[],"step":3},{"description":"Dip 2 slices of bread into the Egg Mixture. Because you''re using fresh bread, it should soak through with egg mixture pretty quickly.","images":[],"step":4},{"description":"Line the base of the loaf tin with the egg dipped bread. Cut bread if necessary to fill in gaps. Repeat twice more so you have 3 layers of egg dipped bread.","images":[],"step":5},{"description":"Spread all the Cream Cheese filling over the bread. Then top with two more layers of egg-dipped bread.","images":[],"step":6},{"description":"Dot surface with butter and scatter over the sugar.","images":[],"step":7},{"description":"Bake for 40 minutes until golden and puffed. Check at 30 minutes - if the top is already dark golden, then cover loosely with foil and return to the oven to finish baking (this is what I did).","duration":40,"images":[],"step":8},{"description":"Allow to rest for 15 minutes in the tin before turning out onto a cooling rack to rest for a further 5 minutes.","duration":15,"images":[],"step":9},{"description":"To serve, topped with Macerated Strawberries.","images":[],"step":10},{"description":"Macerated Strawberries","images":[],"step":11},{"description":"Combine strawberries and sugar in a bowl and set aside to \"sweat\" for at least 20 minutes.","images":[],"step":12}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["breakfast"],"cuisine":[],"categories":["breakfast-recipes","dessert-recipes","most-popular"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e4ceb72cb94f', 'en', 'US', 'Sausage and Egg Stuffed Potatoes', 'Breakfast favorites, assembled in a potato skin! This idea lends itself to many other possibilities such as adding bacon, mushroom, spinach, or finely chopped other greens with the sausage.', 'https://www.recipetineats.com/tachyon/2015/04/Sausage-Egg-Stuffed-Potatoes_2.jpg', 10, 20, 30, 2, '[{"id": "ing_potato", "quantity": {"value": 2.0, "unit": "bag of 2kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_sausages", "quantity": {"value": 7.0, "unit": "pack of 500g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_cheese", "quantity": {"value": 0.25, "unit": "block of 250g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["2 medium baked potatoes (, around 250g/8oz each (Notes 1 & 2))","1/2 tbsp olive oil","7 - 8 oz / 200 - 250g sausages (the best you can afford) meat removed from casings (Note 3)","2 eggs (, at room temperature)","1/4 cup grated cheese (any melting cheese of choice, I used cheddar)","Finely diced parsley (optional garnish)"]}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Cut the lid off the potatoes and scoop out the flesh. If the potatoes are cold, pop them in the oven to warm up while it is preheating. (Note 4)","images":[],"step":2},{"description":"Heat 1/2 tbsp of olive oil in a fry pan over high heat. Add the sausage and cook until browned, using a wooden spoon to break the sausage up into little pieces (as small as you can).","images":[],"step":3},{"title":"Optional step","description":"Brush the outside of the potatoes with melted butter or olive oil - for extra flavour and crispiness.","images":[],"step":4},{"description":"Fill the potatoes with sausage, pressing down to compress as much as you can (this prevents egg sinking into the sausage).","images":[],"step":5},{"description":"Crack the egg on top, sprinkle with cheese, then place in the oven to bake for 18 to 25 minutes, or until the egg whites are set and the yolks are still runny. Check it at 15 minutes then take a peek every 5 minutes - I find that it can go from uncooked to overcooked quickly. My oven was heated well and my potato was piping hot so it took 18 minutes.","duration":21.5,"images":[],"step":6},{"description":"Remove from the oven and serve immediately, sprinkled with parsley if using.","images":[],"step":7}]', '["egg","milk"]', '["gluten_free","high_protein"]', '{"mealType":["breakfast"],"cuisine":["Western"],"categories":["breakfast-recipes","dietary","egg-recipes","gluten-free-recipes","potato-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bcc3f5e88d3c', 'en', 'US', 'Italian Sausage Quiche', 'This isn''t traditional Italian but it is sure packed with Italian flavours! This must be made using Italian sausages as it is a key flavouring component for the filling.', 'https://www.recipetineats.com/tachyon/2015/02/Italian-Sausage-Quiche-2.jpg', 20, 70, 90, 8, '[{"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_sheets_frozen_shortcut_pastry", "quantity": {"value": 1.5, "unit": "pack"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_sausages", "quantity": {"value": 0.68, "unit": "pack of 500g"}}, {"id": "ing_egg", "quantity": {"value": 6.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_mixed_italian_herbs", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 0.4, "unit": "punnet of 250g"}}]', '[{"ingredients":["Oil spray","1 1/2 sheets frozen shortcut pastry ((Note 1), thawed OR one 9\"/23cm ready made pie crust)","1 tbsp olive oil","2 garlic cloves (, minced)","1 small onion (, diced (brown, white, yellow))","12 oz / 350g Italian sausages (, casings removed)","6 eggs","1 cup milk","1 tbsp dried Mixed Italian Herbs (Note 2)","1 tsp salt","1/2 tsp black pepper","1 cup grated cheddar cheese (or tasty, provolone, monterey jack or any other flavoured melting cheese)","2/3 cup cherry tomatoes (, halved and seeds scooped out)"]}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Lightly spray a 9\"/23cm quiche flan or pie dish with oil.","images":[],"step":2},{"description":"Line with the pastry, trimming the excess. Use the extra 1/2 sheet to fill in any gaps as 1 sheet of pastry is slightly too small for a standard flan. Press to seal well.","images":[],"step":3},{"description":"Cover pastry with parchment (baking) paper, then fill with raw rice or dried beans to weigh it down.","images":[],"step":4},{"description":"Place in the oven and bake for 20 minutes, then remove parchment paper and rice/beans. Return to the oven for a further 10 minutes until golden. Remove from oven.","duration":20,"images":[],"step":5},{"description":"Prepare Filling","images":[],"step":6},{"description":"Heat oil in a fry pan over high heat. Add the garlic and onions and sauté for 2 minutes. Then add the sausage and cook, using a spatula to break it up into pieces. Cook until the sausage is browned, then remove the pan from the stove (sausage can stay in the pan).","duration":2,"images":[],"step":7},{"description":"Whisk the eggs, milk, herbs, salt and pepper in a bowl until combined.","images":[],"step":8},{"description":"Assemble And Bake Quiche","images":[],"step":9},{"description":"Scatter half the cheese in the pie crust, then most of the sausage mixture. Pour over the egg mixture, top with remaining cheese and sausage. Then gently place the cherry tomatoes on the surface (cut side down).","images":[],"step":10},{"description":"Carefully transfer to the oven. Bake for 40 minutes until golden brown on top and the filling has set.","duration":40,"images":[],"step":11},{"description":"Remove from the oven and let rest for 10 minutes before serving.","duration":10,"images":[],"step":12}]', '["egg","milk"]', '["gluten_free","low_calorie"]', '{"mealType":["breakfast","lunch"],"cuisine":["Italian-esque"],"categories":["breakfast-recipes","italian-recipes","pork-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b191ad99314e', 'en', 'US', 'Mexican Breakfast Tacos (Chorizo and Egg)', 'A great recovery breakfast that has a zing of spice and the strong flavours of Chorizo piled into a soft taco. I usually find that one is enough per person but if you''re really starving, then you''ll need two!', 'https://www.recipetineats.com/tachyon/2015/02/Mexican-Eggs-and-Chorizo-Breakfast-Tacos-1.jpg', 15, 15, 30, 4, '[{"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_mexican_or_spanish_chorizo", "quantity": {"value": 0.198, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_chilli", "quantity": {"value": 2.0, "unit": "pack of 100g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_egg", "quantity": {"value": 333.333, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_tortillas", "quantity": {"value": 4.0, "unit": "pack of 8"}}, {"id": "ing_feta_cheese", "quantity": {"value": 1.0, "unit": "block of 200g"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["2 tomatoes (, deseeded and diced)","1/2 red onion (, diced)","2 tbsp lime juice (adjust to taste) (around 1 lime)","1 tbsp olive oil","2 tbsp coriander/cilantro leaves","1/2 tsp salt","Black pepper"],"purpose":"Pico de gallo"},{"ingredients":["1 tbsp olive oil","7 oz / 200g Mexican or raw Spanish chorizo (, removed from casings (Note 1))"],"purpose":"Chorizo"},{"ingredients":["2 garlic cloves","2 birds eye chilies (, deseeded and finely chopped (adjust to taste))","1 small onion (brown, yellow, white)","4 large eggs (, lightly whisked (or 6 small eggs))","1 tbsp milk","3/4 tsp salt","Black pepper"],"purpose":"Mexican Scrambled Eggs (\"Eggs\")"},{"ingredients":["4 small tortillas (, corn or flour (around 6\" / 12 cm rounds))","Cotija or feta (, crumbled)","Avocado (, diced)","Cilantro/coriander leaves"],"purpose":"To Serve"}]', '[{"description":"Combine Pico de gallo ingredients EXCEPT THE SALT in a bowl and set aside while you prepare the rest of the breakfast.","images":[],"step":1},{"title":"Cook Chorizo","description":"Heat olive oil in a non stick fry pan over high heat. Add the chorizo and cook, breaking up the pieces, until browned. Remove chorizo into a bowl. Drain excess fat but leave enough to cook the eggs.","images":[],"step":2},{"title":"Make the Eggs","description":"Reduce heat to medium. Add garlic, chilies and onion to the pan and sauté for 2 to 3 minutes until translucent and starting to turn golden. Add the eggs and milk and stir slowly with a wooden spoon until the eggs start to set. Remove the pan from the stove while they are still a bit wet because they will keep cooking. Stir through salt and pepper - adjust to taste.","duration":2.5,"images":[],"step":3},{"description":"Warm tortillas in the microwave or oven, per packet instructions.","images":[],"step":4},{"description":"Add salt to pico de gallo and toss.","images":[],"step":5},{"title":"Assemble","description":"Place some scrambled eggs in a tortilla then top with chorizo then pico de gallo. Garnish with cotija / feta, avocado and coriander/cilantro leaves.","images":[],"step":6}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["breakfast"],"cuisine":["Mexican-esque"],"categories":["breakfast-recipes","dietary","egg-recipes","gluten-free-recipes","mexican-recipes","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6c9d96097dc5', 'en', 'US', 'Spicy Italian Breakfast Roll Ups (Breakfast On The Go / Mini Taquitos)', 'Great food on the go, freezable and microwavable. These are made using soft tacos (small tortillas) so they are a great size for eating on the move with your hands. The tortillas bake crisp but do not crumble and the filling holds together well when you bite into it. The scrambled egg is flavoured so it is not the usual pale yellow colour, it is a slightly brown colour.', 'https://www.recipetineats.com/tachyon/2015/02/DSC_00971.jpg', 20, 15, 35, 8, '[{"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_sausages", "quantity": {"value": 0.567, "unit": "pack of 500g"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_chilli", "quantity": {"value": 3.0, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_egg", "quantity": {"value": 6.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_cheese", "quantity": {"value": 0.75, "unit": "block of 250g"}}, {"id": "ing_basil", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_tortillas", "quantity": {"value": 8.0, "unit": "pack of 8"}}]', '[{"ingredients":["1/2 tbsp olive oil","10 oz / 300g spicy Italian Sausages (Note 1)","1 tbsp butter","1 small onion (, diced (brown, yellow, white, spanish))","3 birds eye chillis (, sliced (adjust amount to taste - Note 2))","2 cloves garlic","6 eggs","1 tbsp milk","3/4 tsp salt","Black pepper","3/4 cup grated cheese (I used cheddar, any other flavoured cheese that melts works fine)","1/4 cup fresh basil leaves (, thinly sliced (or sub with 1 tbsp dried Italian herbs - basil, parsley, oregano))","8 small tortillas (, corn or flour (around 6\" / 12 cm rounds))","Olive oil (, for brushing)"]}]', '[{"description":"Preheat oven to 180C/350F. Spray a baking tray with oil, or line with parchment/baking paper.","images":[],"step":1},{"description":"Remove sausages from casings.","images":[],"step":2},{"description":"Heat oil in a large fry pan over high heat. Add the sausage and cook, breaking up into chunky pieces, until nicely browned. Remove from pan.","images":[],"step":3},{"description":"Turn stove down to medium high and melt butter in the same pan (don''t clean the pan). Add the onion, chills and garlic and sauté for 3 to 5 minutes until the onion is translucent and a light golden brown.","duration":4,"images":[],"step":4},{"description":"Add the eggs, milk, salt and pepper. Stir slowly, not vigorously, using a wooden spoon until the eggs are \"holding together\" but are still wet - about 5 minutes.","images":[],"step":5},{"description":"Remove pan from the stove, stir through the sausage, cheese and basil leaves.","images":[],"step":6},{"description":"Divide filling between the tortillas.","images":[],"step":7},{"description":"Roll up the tortillas and place on the baking tray, seam side down. Brush with olive oil (optional), then bake for 15 to 20 minutes until light golden and slightly crisp.","duration":17.5,"images":[],"step":8},{"description":"Serve while warm.","images":[],"step":9},{"description":"To freeze, allow to cool then place in the freezer. To reheat, defrost then reheat in the oven (to make it crisp again) or in the microwave (the tortilla will reheat soft so it will be more like a burrito).","images":[],"step":10}]', '["egg","gluten","milk"]', '["low_calorie"]', '{"mealType":["breakfast"],"cuisine":["Italian-esque"],"categories":["breakfast-recipes","dietary","gluten-free-recipes","italian-recipes","pork-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e50a66e19379', 'en', 'US', 'Chorizo Breakfast Hash with Crispy Smashed Potatoes and Eggs', 'A loaded breakfast hash with chorizo, bacon, cherry tomatoes, crispy smashed potatoes and eggs.', 'https://www.recipetineats.com/tachyon/2015/01/Chorizo-Bacon-Smashed-Potato-Breakfast-Hash-LR-edited-FINAL.jpg', 5, 15, 20, 2, '[{"id": "ing_potato", "quantity": {"value": 8.0, "unit": "bag of 2kg"}}, {"id": "ing_bacon", "quantity": {"value": 2.0, "unit": "pack of 200g"}}, {"id": "ing_chorizo", "quantity": {"value": 0.085, "unit": "kg"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 0.6, "unit": "punnet of 250g"}}, {"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["8 (220g / 7oz) baby potatoes (, skin on)","2 rashers of bacon (, or 3 strips of streaky bacon, cut into large dice)","3 oz / 100g chorizo ((about 1/2 chorizo), sliced 1/2cm / 1/5\" thick)","1 cup cherry tomatoes (, halved)","3 or 4 eggs","2 tbsp water","Salt and pepper","Avocado slices (optional)","1/2 tbsp fresh parsley (, finely chopped (optional, for garnish))","Crusty bread to serve"]}]', '[{"description":"Steam, boil or microwave the potatoes until soft. (Note 1)","images":[],"step":1},{"description":"Cut the potatoes in half.","images":[],"step":2},{"description":"Heat a skillet or fry pan over high heat.","images":[],"step":3},{"description":"Add the bacon (add a dash of olive oil if you have lean bacon) and fry until browned but not crisp.","images":[],"step":4},{"description":"Remove onto a plate with a slotted egg flip. (Note 2)","images":[],"step":5},{"description":"Add the chorizo into the same fry pan and cook each side until browned, around 2 to 3 minutes.","images":[],"step":6},{"description":"Remove on the plate with the bacon. (Note 2)","images":[],"step":7},{"description":"Place the potatoes, cut side down, into the fry pan. Use the egg flip or a potato masher to \"smash\" the potatoes down so they flatten onto the fry pan. Sprinkle with salt.","images":[],"step":8},{"title":"Cook the first side until golden brown","description":"around 1 to 1 1/2 minutes. Then turn and cook the other side until just golden brown, pressing down with the egg flip - around 1 to 1 1/2 minutes. Sprinkle with salt.","images":[],"step":9},{"description":"Add the bacon, chorizo and cherry tomatoes into the fry pan. Toss gently.","images":[],"step":10},{"description":"Crack the eggs into the pan. Drizzle the water down the side of the pan, then put a lid on the fry pan (Note 3). The eggs will \"steam cook\".","images":[],"step":11},{"description":"Cook until the eggs are cooked to your liking. For \"just set\" egg white with runny yolks, it is usually around 1 1/2 minutes.","images":[],"step":12},{"description":"Remove from the stove, sprinkle with salt and pepper. Top with sprinkle of parsley and avocado (if using).","images":[],"step":13},{"description":"Serve with crusty bread or toast.","images":[],"step":14}]', '["egg","gluten"]', '["high_protein"]', '{"mealType":["breakfast"],"cuisine":[],"categories":["breakfast-recipes","dietary","gluten-free-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_57e9ddc57bcf', 'en', 'US', 'Muffin Tin Breakfast Croque Madame Toastie Cups', 'A fresh take on the classic French grilled ham and cheese! Adapted from a recipe by Rachel Khoo.', 'https://www.recipetineats.com/tachyon/2014/12/Croque-madame-take-2-12531.jpg', 10, 30, 40, 6, '[{"id": "ing_butter", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_gruyere_cheese", "quantity": {"value": 0.333, "unit": "block of 200g"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_nutmeg", "quantity": {"value": 1.25, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 7.5, "unit": "loaf"}}, {"id": "ing_egg", "quantity": {"value": 6.0, "unit": "carton of 12"}}, {"id": "ing_leg_ham", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 1/2 tbsp unsalted butter","1 1/2 tbsp flour","1 1/4 cups milk (full fat works best, though low fat does work)","1/3 cup grated gruyere cheese ((or tasty or cheddar), plus extra for sprinkling)","2 tsp Dijon mustard","1/4 tsp freshly ground nutmeg","1/4 tsp salt","Black pepper"],"purpose":"Bechamel Cheese Sauce"},{"ingredients":["6 large slices of fresh white bread (Notes 1 and 2)","2 tbsp melted butter (salted or unsalted)","6 eggs","100 g / 3 oz leg ham"],"purpose":"Toast Cups"},{"ingredients":["Fresh parsley (, finely chopped)","Freshly ground nutmeg"],"purpose":"Garnish"}]', '[{"description":"Turn the oven on to 180C/350F.","images":[],"step":1},{"description":"Cut the crusts off the bread, then roll out with a rolling pin until flattened.","images":[],"step":2},{"description":"Press the bread into Texas muffin tins to form cups. Place into the oven (even if it is still heating up) for 5 minutes, just to dry the bread out a bit (Note 3). Don''t let it brown.","duration":5,"images":[],"step":3},{"description":"Bechamel Cheese Sauce","images":[],"step":4},{"description":"Melt the butter in a saucepan over medium high heat. Add the flour and stir until a paste forms.","images":[],"step":5},{"description":"Add half the milk and whisk until the sauce thickens - around 1 minute.","images":[],"step":6},{"description":"Add the remaining milk, Dijon mustard, nutmeg, salt and pepper. Keep whisking because once the milk heats up, it thickens very quickly. Whisk until the sauce is thick enough to coat the spoon thickly (around 1 1/2 to 2 minutes), around the consistency of tomato ketchup.","images":[],"step":7},{"description":"Remove from heat and let cool for 5 minutes. The sauce will thicken considerably as it cools. Then stir the cheese in.","duration":5,"images":[],"step":8},{"description":"Assemble Toast Cups","images":[],"step":9},{"description":"Brush the melted butter around the edges of the toast cups (to help them brown nicely).","images":[],"step":10},{"description":"Divide the ham between the toast cups, then carefully crack an egg into each.","images":[],"step":11},{"description":"Top with Bechamel Cheese Sauce, then sprinkle each with a pinch of grated cheese.","images":[],"step":12},{"description":"Bake for 18 minutes (for runny yolks) to 23 minutes (firm yolks). (Note 4)","duration":18,"images":[],"step":13},{"description":"Rest for a few minutes, then sprinkle with parsley and a grating of fresh nutmeg.","images":[],"step":14},{"description":"Serve immediately.","images":[],"step":15}]', '["egg","gluten","milk","mustard"]', '["low_calorie"]', '{"mealType":["breakfast"],"cuisine":["French"],"categories":["breakfast-recipes","muffin-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_60b12d69a43b', 'en', 'US', 'Hasselback Baked French Toast', 'A french toast bake unlike any other! Using baguettes (french stick bread) soaked in an egg mixture, this comes out golden and crusty on the outside and custardy on the inside. When you serve it, it fans out like hasselback potatoes which make perfect crevices to pour maple syrup into!', 'https://www.recipetineats.com/tachyon/2014/12/Hasselback-French-Toast-2.jpg', 10, 25, 35, 4, '[{"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_egg", "quantity": {"value": 5.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.333, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 0.25, "unit": "block of 250g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_maple_syrup", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.05, "unit": "bottle of 50ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.03, "unit": "kg"}}]', '[{"ingredients":["1 baguette / french stick (, 60 cm / 2 feet long (Note 1))"]},{"ingredients":["5 eggs","1 1/3 cup milk (preferably whole fat but low fat works just fine)","1/4 tsp salt"],"purpose":"Egg Mixture"},{"ingredients":["1/4 cup butter","2 tbsp brown sugar","2 tbsp maple syrup","1/2 tsp cinnamon powder","1/2 tsp vanilla extract or essence (optional)"],"purpose":"Butter Mixture"},{"ingredients":["Icing sugar (confectionary sugar)","Maple syrup"],"purpose":"Toppings (not optional!)"}]', '[{"description":"Cut the french stick loaf into 3 equal pieces.","images":[],"step":1},{"description":"Cut slices into each piece around 1.5cm / 0.5\" thick almost through to the base (like hasselback potatoes / classic garlic bread).","images":[],"step":2},{"description":"Place the Egg Mixture into a bowl and whisk to combine.","images":[],"step":3},{"description":"Place the Egg Mixture and bread into a ziplock bag or plastic bag. Remove as much air as you can and seal. Set aside for at least 1 hour (or overnight), turning once or twice, or until most of the Egg Mixture has been soaked up by the bread. (Note 1)","images":[],"step":4},{"description":"Preheat oven to 180C/350F.","images":[],"step":5},{"description":"Place the bread into a baking dish (22 x 22 cm / 8 x 8\"), cut side up.","images":[],"step":6},{"description":"Place in the oven and bake for 20 minutes.","duration":20,"images":[],"step":7},{"description":"Place the Butter Mixture into a small saucepan over medium heat. Heat until melted and combined, stirring occasionally. You could do this in the microwave too - around 2 x 30 second bursts, stirring in between.","images":[],"step":8},{"description":"Remove the french toast from the oven. Pour the butter mixture over the french toast and return to oven. Bake for a further 5 to 10 minutes or until golden and crispy on top.","images":[],"step":9},{"description":"Remove from oven and let it rest for 5 minutes.","duration":5,"images":[],"step":10},{"description":"Sift over icing sugar (confectioners sugar) and serve with maple syrup.","images":[],"step":11}]', '["egg","milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["breakfast"],"cuisine":[],"categories":["breakfast-recipes","dessert-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_429df8272dd6', 'en', 'US', 'Hash Brown Crust Quiche Lorraine', 'A mash up of two of my favourite brunch dishes - hash brown and quiche! This can be made using frozen shredded hash browns or you can shred your own (directions provided for both).', 'https://www.recipetineats.com/tachyon/2014/12/Hash-Brown-Crust-Quiche-Lorraine-11.jpg', 25, 75, 100, 8, '[{"id": "ing_potato", "quantity": {"value": 1.2, "unit": "bag of 2kg"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_pinch_nutmeg", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_bacon", "quantity": {"value": 0.851, "unit": "pack of 200g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_cheese", "quantity": {"value": 0.75, "unit": "block of 250g"}}]', '[{"ingredients":["1.2 lb / 600g starchy potatoes ((Note 1) OR 4 cups (not packed) frozen shredded hash browns, thawed)","2 tbsp unsalted butter (, melted)","1 tsp salt","Butter (, for greasing)","Oil spray (or olive oil)"],"purpose":"Hash Brown Crust"},{"ingredients":["2 egg yolks","2 eggs","1 cup milk (preferably full cream, but low fat will also work)","3/4 cup cream","Pinch of freshly grated nutmeg (optional)","1/2 tsp salt","Black pepper"],"purpose":"Egg Mixture"},{"ingredients":["1/2 tbsp butter","6 oz / 180g bacon (, cut into large dice (about 1cm x 0.5cm / 2/3\" x 1/5\"))","1 small onion (, diced (or half a large onion))","1 garlic clove (, minced)","3/4 cup grated cheese (tasty, cheddar or gruyere)"],"purpose":"Filling"}]', '[{"description":"Preheat oven to 425F/220C with the oven shelf in the top 1/3 of the oven.","images":[],"step":1},{"description":"Grease a 9\"/ 23cm pie dish (Note 2)","images":[],"step":2},{"description":"Hash Brown Crust","images":[],"step":3},{"description":"If shredding potatoes yourself, peel and grate the potatoes. Place the shredded potatoes into a colander and rinse for 10 seconds, using your hands to move the grated potatoes around, until the water runs clear.","duration":0.16666666666666666,"images":[],"step":4},{"description":"Take a handful of the rinsed grated potatoes OR the thawed frozen shredded hash browns and squeeze the excess water out, then place into a large bowl. Repeat with remaining potato. You should have about 4 cups of shredded potato.","images":[],"step":5},{"description":"Add melted butter and salt and mix to combine.","images":[],"step":6},{"description":"Pour the shredded potato into the pie dish. Use a large dessert spoon to spread the hash browns over the base and side of the pie dish.","images":[],"step":7},{"description":"Use your hands or a spatula to pat down the base of the hash brown crust so it is fairly firmly packed.","images":[],"step":8},{"description":"Spray the hash brown crust with oil spray (I used olive oil spray).","images":[],"step":9},{"description":"Bake the crust for 30 minutes.","duration":30,"images":[],"step":10},{"description":"Prepare Filling & Egg Mixture","images":[],"step":11},{"description":"While the crust is baking, melt 1/2 tbsp butter in a fry pan over medium high heat.","images":[],"step":12},{"description":"Add onion, garlic and bacon into the fry pan. Saute until the onion is translucent and the bacon is just starting to brown (but not crisp).","images":[],"step":13},{"description":"Remove from the stove and set aside to cool slightly.","images":[],"step":14},{"description":"Place Egg Mixture ingredients in a bowl and whisk to combine.","images":[],"step":15},{"description":"When the crust is light golden brown on the surface of the base and golden brown on the walls of the crust (around 30 minutes), remove from the oven.","images":[],"step":16},{"description":"Scatter the bacon onion mixture across the base, then the cheese.","images":[],"step":17},{"description":"Then pour the Egg Mixture in.","images":[],"step":18},{"description":"Baking the Quiche","images":[],"step":19},{"description":"Return the quiche to the oven and turn the oven down to 180C/350F.","images":[],"step":20},{"description":"Bake for 25 minutes, or until the Filling is set. Test this either by inserting a skewer into the centre (it should come out clean) or by touching the centre gently (it should spring back).","duration":25,"images":[],"step":21},{"description":"Let it rest for 5 to 10 minutes before serving.","duration":7.5,"images":[],"step":22}]', '["egg","milk"]', '["gluten_free","low_calorie"]', '{"mealType":["breakfast","lunch"],"cuisine":[],"categories":["breakfast-recipes","dietary","gluten-free-recipes","most-popular","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0781f365f86f', 'en', 'US', 'Bacon Tart with Pumpkin and Maple', 'Maple, bacon and pumpkin is a stellar flavour combination. This tart is from the menu of a popular bistro called Pinbone in Woollahra, Sydney. The original recipe required homemade puff pastry. I chose the easier path and made this with frozen puff pastry. In addition the original recipe calls for the pumpkin to be roasted and the caramelisation adds extra flavour. However, sometimes I just steam the pumpkin in the microwave because I find that the difference is barely noticeable due to the strong flavours coming from the bacon and maple syrup. Plus it is much more convenient because the pumpkin is prepared while the oven is preheating, so it is much faster (you save around 30 minutes of cooking time). So I have provided directions for both methods.', 'https://www.recipetineats.com/tachyon/2014/12/Maple-Bacon-Pumpkin-Tart-2.jpg', 10, 40, 50, 2, '[{"id": "ing_sheet_frozen_puff_pastry", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_bacon", "quantity": {"value": 1.6, "unit": "pack of 200g"}}, {"id": "ing_maple_syrup", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_pumpkin", "quantity": {"value": 0.198, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1 sheet store bought frozen puff pastry (, thawed (25 cm x 25cm / 10\" x 10\"))","8 slices streaky bacon (Note 1)","1 1/2 tbsp maple syrup (Note 2)","Oil spray"],"purpose":"Tart"},{"ingredients":["7 oz / 200g butternut or Jap pumpkin (, peeled and roughly diced into 1.5cm/0.5\" cubes)","1/2 tbsp olive oil (only required if roasting the pumpkin)","1 tbsp butter","Salt and pepper"],"purpose":"Pumpkin"}]', '[{"description":"Preheat oven to 220C/425F.","images":[],"step":1},{"description":"Spray a baking tray with olive oil (or grease with butter or oil)","images":[],"step":2},{"description":"Cook Pumpkin either by roasting or microwaving it (see instructions below). Transfer to a large bowl (cools faster) and add butter plus a pinch of salt and pepper. Mash with a fork until the pumpkin is smooth and set aside.","images":[],"step":3},{"description":"Cut puff pastry in half (Note 3). Place one piece on top of the other. Place the double layered pastry on the baking tray.","images":[],"step":4},{"description":"Cover pastry with a sheet of baking (parchment) paper (not weighed down, just place it on top of the pastry). Bake for 15 minutes until it has puffed up a bit and it is a very light golden brown.","duration":15,"images":[],"step":5},{"description":"While the pastry is pre-baking, trim the bacon so it is wider than the width of the tart by approximately 1.5cm / 1/2\" (Note 4).","images":[],"step":6},{"description":"Remove the pastry from the oven and discard baking paper.","images":[],"step":7},{"description":"Working quickly, spread the pumpkin on the pastry, leaving a 1cm / 1/4\" border.","images":[],"step":8},{"description":"Place the bacon on the tart, overlapping each slice. The 8 slices should cover the whole tart.","images":[],"step":9},{"description":"Place in the oven and bake for 20 minutes until deep golden.","duration":20,"images":[],"step":10},{"description":"Remove from the oven and brush half the maple syrup on the bacon and the pastry border.","images":[],"step":11},{"description":"Place the tart back in the oven for a further 7 to 10 minutes, until the bacon and pastry is a deep, dark golden brown. (Note 5)","images":[],"step":12},{"description":"Remove from oven and brush with remaining maple syrup. Season with pepper if desired.","images":[],"step":13},{"description":"Serve with a light side salad. This tart reheats well in the oven and keeps for 2 days in the fridge, but it is best served fresh out of the oven.","images":[],"step":14},{"description":"Cooking the Pumpkin","images":[],"step":15},{"title":"Roasting","description":"Toss pumpkin in olive oil and roast for 20 - 25 minutes until golden brown. Remove from oven, then proceed with recipe directions.","duration":22.5,"images":[],"step":16},{"title":"Microwaving","description":"Place pumpkin in a microwave proof bowl (or steamer) with a splash of water. Cover with lid or cling wrap (pierce with a fork a few times if using cling wrap) then microwave on high for 8 minutes. Drain water before use, then proceed with recipe directions.","duration":8,"images":[],"step":17}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["breakfast"],"cuisine":[],"categories":["breakfast-recipes","easter-brunch-recipes","pumpkin","quiches-tart-and-pie-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c4197c29f673', 'en', 'US', 'Smoked Salmon Potato Rosti Stack', 'A great breakfast when you want to impress or to treat yourself. The potato rosti can be made the day before (see notes for directions).', 'https://www.recipetineats.com/tachyon/2014/11/DSC_0213.jpg', 15, 5, 20, 2, '[{"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_salmon_fillets", "quantity": {"value": 0.085, "unit": "kg"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.12, "unit": "tub of 250g"}}, {"id": "ing_dill_to_garnish", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1 lb / 500 g potatoes (2 large or 3 medium) (see note 1 for potato type)","1 tbsp melted butter","1 tbsp olive oil","1/4 tsp salt","Pepper","3 oz / 100g Smoked salmon","2 tbsp sour cream","Dill to garnish (optional)"]}]', '[{"description":"Microwave the potatoes (unpeeled, whole) for 1 1/2 minutes on high, turn then microwave for a further 2 minutes. Or boil the potatoes for 5 minutes. The potatoes should be uncooked in the middle.","duration":5,"images":[],"step":1},{"description":"Use a dishcloth to hold the potatoes and peel the skin off. I find it easiest to do this with a butter knife.","images":[],"step":2},{"description":"Use a cheese grater and grate the potato.","images":[],"step":3},{"description":"Add butter, salt and pepper and mix to combine.","images":[],"step":4},{"description":"Heat olive oil in a large fry pan over medium high heat.","images":[],"step":5},{"description":"Scoop up 1/4 cup of potato mixture and use an egg flip to lightly pack the potato into the measuring cup. Then place into the pan and lightly pat down with an egg flip to make the rosti about 1 cm / 1/3\" thick. Repeat with remaining mixture.","images":[],"step":6},{"title":"Cook until each side is golden brown","description":"around 1 1/2 - 2 minutes for each side.","images":[],"step":7},{"description":"Remove from fry pan.","images":[],"step":8},{"description":"To serve, stack 3 rostis on each plate, top with smoked salmon, a dollop of sour cream and dill.","images":[],"step":9}]', '["fish","milk"]', '["gluten_free","low_calorie"]', '{"mealType":["breakfast"],"cuisine":[],"categories":["breakfast-recipes","dietary","easter-recipes","fish-recipes","gluten-free-recipes","most-popular","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_740e1c4569a1', 'en', 'US', 'Sunday Sunshine Baked Eggs in Mushrooms', 'Something different for breakfast that takes minutes to prepare! Note: the recipe assumes the pasta sauce and cheese have salt in them. If not, just sprinkle a pinch of salt over the pasta sauce before cracking the egg in.', 'https://www.recipetineats.com/tachyon/2014/10/Baked-Eggs-in-Mushroom-1.jpg', 5, 15, 20, 2, '[{"id": "ing_mushroom", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.09, "unit": "pack of 500g"}}, {"id": "ing_cream", "quantity": {"value": 0.24, "unit": "carton of 250ml"}}, {"id": "ing_cheese", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["2 large mushrooms (flat, Portobello) (note 1)","2 eggs","3 tbsp pasta sauce (or pizza sauce or other sauce of preference) (note 2)","4 tbsp cream (1/4 cup)","4 tbsp grated cheese OR 2 slices of cheese (any cheese that''s good for melting. I used sliced tasty cheese)","Fresh parsley (, finely chopped (optional - for serving))"]}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"title":"Remove stalk from mushroom. Optional","description":"scrape gills out with a teaspoon (the brown part). I usually only do this if the mushroom is on the small side and I need to make more room for the egg to fit.","images":[],"step":2},{"description":"Divide the pasta sauce between the mushrooms and spread.","images":[],"step":3},{"description":"Crack an egg into each mushroom.","images":[],"step":4},{"description":"Pour cream over the eggs, drizzling to try to cover the whole surface.","images":[],"step":5},{"description":"Place mushrooms in the oven for 10 minutes.","duration":10,"images":[],"step":6},{"description":"Remove from oven and sprinkle over the cheese, then return to oven.","images":[],"step":7},{"description":"Bake for a further 5 minutes or until the egg whites are just set and (hopefully) the yolks are still runny (see note 3 for cooking time guidance). Remember that the eggs will continue to cook after you take them out of the oven.","images":[],"step":8},{"description":"Garnish with parsley, if using, then serve immediately.","images":[],"step":9}]', '["egg","gluten","milk"]', '["keto_friendly","low_calorie","vegetarian"]', '{"mealType":["breakfast"],"cuisine":[],"categories":["breakfast-recipes","dietary","egg-recipes","gluten-free-recipes","mushroom-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cacd5ba368de', 'en', 'US', 'Huevos Rancheros Tortilla Bowls', 'Something different for breakfast this weekend! This recipe makes just enough for 3 - I have tried to stretch it to 4 but it was not quite enough (I thought). Or it is for 2 very hungry people!', 'https://www.recipetineats.com/tachyon/2014/10/Huevos-Rancheros-Tortilla-Bowls-12.jpg', 5, 20, 25, 3, '[{"id": "ing_tortillas", "quantity": {"value": 3.0, "unit": "pack of 8"}}, {"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_canned_tomatoes", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_black_beans", "quantity": {"value": 0.281, "unit": "can of 400g"}}, {"id": "ing_paprika", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}]', '[{"ingredients":["3 flour tortillas (20cm/8\" rounds)","3 eggs"]},{"ingredients":["1 1/2 tbsp olive oil","2 garlic cloves (, minced)","1 small onion ((red, brown, white, yellow), halved and sliced)","1 cup red capsicum ((bell peppers), roughly diced)","1/4 cup coriander/cilantro (leaves and stems roughly chopped) (loosely packed)","400 g / 14 oz crushed tinned tomato","3/4 cup canned black beans (, drained)","1/2 tsp paprika powder","1/2 tsp cumin powder","1/2 - 3/4 tsp salt","Black pepper"],"purpose":"Filling"},{"ingredients":["Diced avocado","Sour cream","Grated cheese"],"purpose":"Garnishes (optional)"}]', '[{"description":"Heat a fry pan over high heat. Use a fry pan with a lid or use the lid of a larger pot (it doesn''t matter if it doesn''t fit snugly).","images":[],"step":1},{"description":"Place tortilla in fry pan and cook for 30 seconds until charred. Flip and cook the other side for 30 seconds.","duration":0.5,"images":[],"step":2},{"description":"Remove from fry pan and place into a bowl or casserole dish to form a bowl shape. As the tortilla cools, it will hold its shape in a bowl form.","images":[],"step":3},{"description":"Repeat with remaining tortillas.","images":[],"step":4},{"description":"Heat oil in fry pan over high heat.","images":[],"step":5},{"description":"Add garlic and onion and sauté for 2 minutes until starting to become translucent.","duration":2,"images":[],"step":6},{"description":"Add capsicum (bell pepper) and cook for 2 minutes until starting to char.","duration":2,"images":[],"step":7},{"description":"Add remaining Tomato Filling ingredients, reserving some coriander leave for garnish. Bring to simmer and cook for 1 minute to thicken, then turn heat down to medium.","duration":1,"images":[],"step":8},{"description":"Cook eggs","images":[],"step":9},{"description":"Use a spoon to make 3 indents in the Tomato Filling.","images":[],"step":10},{"description":"Crack eggs into indents.","images":[],"step":11},{"description":"Cover with lid and cook for 3 minutes or to your liking. Check it at 2 minutes, then take a quick peek every 30 seconds thereafter. It can go from under to overcooked in a flash! Note that the eggs will continue to cook slightly after taking it off the heat.","duration":3,"images":[],"step":12},{"description":"Remove fry pan from heat.","images":[],"step":13},{"description":"Divide Tomato Filling between each Tortilla Bowl, topped with an egg.","images":[],"step":14},{"description":"Top with remaining coriander leaves and garnish of choice. Serve immediately.","images":[],"step":15}]', '["egg","gluten","milk"]', '["high_protein","vegetarian"]', '{"mealType":["breakfast"],"cuisine":["Mexican"],"categories":["breakfast-recipes","dietary","gluten-free-recipes","mexican-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ff058e5f95b9', 'en', 'US', 'Bacon French Toast', 'A cross between a muffin, pull apart bread and french toast! Great food on the go that''s perfect for feeding an army. You can even freeze them!', 'https://www.recipetineats.com/tachyon/2014/09/Bacon-French-Toast-Muffin-10.jpg', 10, 15, 25, 6, '[{"id": "ing_bread", "quantity": {"value": 0.938, "unit": "loaf"}}, {"id": "ing_bacon", "quantity": {"value": 3.0, "unit": "pack of 200g"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_maple_syrup", "quantity": {"value": 1.0, "unit": "bottle of 250ml"}}]', '[{"ingredients":["5 cups of bread (, cut into 2cm/1\" cubes (fresh or stale - see notes 1 and 2))","3 rashers bacon (, diced)","Oil spray"]},{"ingredients":["3 eggs","1 1/4 cups milk (low or full fat)","1 tsp sugar","2 pinches salt"],"purpose":"Egg Mixture"},{"ingredients":["Maple syrup (optional)"],"purpose":"To Serve"}]', '[{"description":"Combine the Egg Mixture ingredients in a bowl and whisk with a fork until combined.","images":[],"step":1},{"description":"Add bread cubes and mix well to each piece of bread is well coated with the Egg Mixture.","images":[],"step":2},{"description":"If using fresh bread, set aside for 10 to 30 minutes in the fridge. If using stale bread, set aside for 20 minutes to overnight. If you''re in a rush, use your hands to gently squeeze the cubes to help them absorb the egg mixture faster.","duration":20,"images":[],"step":3},{"description":"Preheat oven to 180C/350F.","images":[],"step":4},{"description":"Spray a medium fry pan with oil spray and heat on high heat. Add the bacon and cook until just starting to brown. Don''t cook until it is very brown because otherwise it will overcook in the oven. Remove bacon from fry pan and drain on absorbent paper.","images":[],"step":5},{"description":"Spray 6 holes in a muffin tin.","images":[],"step":6},{"description":"Mix the bread-egg mixture to evenly disperse the egg mixture that will have settled at the bottom of the bowl.","images":[],"step":7},{"description":"Divide 1/3 of the bread-egg mixture between the 6 muffin cups.","images":[],"step":8},{"description":"Sprinkle with half the bacon, then press the mixture down with medium pressure using the back of a spoon.","images":[],"step":9},{"description":"Top with the remaining bread mixture. Use your fingers to lightly compress them. Each muffin should be slightly mounded even after lightly compressing them. The bread cubes on top will puff back up when you bake it.","images":[],"step":10},{"description":"Sprinkle with remaining bacon.","images":[],"step":11},{"description":"Bake for 15 to 20 minutes until the top is golden brown.","duration":17.5,"images":[],"step":12},{"description":"Let rest for 5 minutes before removing from the muffin tin.","duration":5,"images":[],"step":13},{"description":"Serve with maple syrup, if using.","images":[],"step":14}]', '["egg","gluten","milk"]', '["low_calorie"]', '{"mealType":["breakfast"],"cuisine":[],"categories":["breakfast-recipes","most-popular","muffin-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2fc369a36857', 'en', 'US', 'Parmesan Garlic Broccoli Fritters', 'There is a very high broccoli to fritter batter ratio in this recipe. It''s a fabulous way to hide a lot of greens in irresistible little bites that even kids will gobble up! Makes 6 fritters about 9cm/3" in diameter, 1cm/1/3" thick. Adapted from Smitten Kitchen', 'https://www.recipetineats.com/tachyon/2014/09/DSC_0037.jpg', 10, 10, 20, 6, '[{"id": "ing_broccoli", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}]', '[{"ingredients":["3 cups broccoli florets and stem (, roughly chopped into 2cm/1 inch pieces (see notes) (about 1 medium head of broccoli))","2 tbsp oil (vegetable, olive oil, canola)"]},{"ingredients":["1 garlic clove (, minced)","1/2 cup plain flour","1/4 cup grated parmesan","1 egg","2 tbsp milk (low fat or full fat)","1/2 tsp salt","Black pepper"],"purpose":"Batter"},{"ingredients":["Lemon Yogurt Sauce ((1 batch) - really quick to make - or just plain yogurt)","Extra lemon wedges (, optional)"],"purpose":"For serving"}]', '[{"title":"Sauce first","description":"Make the Lemon Yogurt Sauce (needs to be set aside 20 minutes to let flavours meld).","images":[],"step":1},{"title":"Cook broccoli","description":"Steam or boil the broccoli until quite tender (but not mushy). I did this in the microwave using a steamer, it took 3 minutes on high.","images":[],"step":2},{"title":"Squish","description":"Use a potato masher to roughy \"squish\" the broccoli. Not to look like mashed potato, but just to squish it a bit so when cooked it can be flattened with a spatula to make fritters with a smooth surface rather than having big lumps sticking out.","images":[],"step":3},{"title":"Batter","description":"Place egg in a bowl and use a fork to lightly beat the egg. Add the remaining Batter ingredients and mix until combined. The Batter may seem a little thick but it will loosen up when you add the broccoli because when you squish it, it will release some liquid.","images":[],"step":4},{"title":"Broccoli","description":"Add the broccoli and mix to evenly disperse throughout the Batter.","images":[],"step":5},{"title":"Cook","description":"Heat 1 tbsp of oil in a fry pan over medium heat. Scoop 1/4 cup of Batter and drop into the pan and use a spoon to gently flatten to about 1cm/1/3\" thickness (I do 3 fritters at a time). Cook each side for 2 to 3 minutes until golden brown. Repeat with remaining Batter.","duration":2.5,"images":[],"step":6},{"description":"Serve with the Lemon Yoghurt Sauce and extra lemon wedges, if desired.","images":[],"step":7}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["breakfast-recipes","broccoli-recipes","dinner-tonight","fritters-tots-and-similar","main-dishes","most-popular","quick-and-easy","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0da1ec84647b', 'en', 'US', 'Cheese and Bacon Muffin Tin Hash Browns', 'A great way to make hash browns for a crowd!', 'https://www.recipetineats.com/tachyon/2014/09/Bacon-Cheese-Hash-brown-muffins-2.jpg', 15, 30, 45, 12, '[{"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_bacon", "quantity": {"value": 3.0, "unit": "pack of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["1 kg / 2 lb starchy potatoes (see notes)","2 1/2 tbsp olive oil (, separated)","1 cup grated cheese (any melting cheese)","3 bacon rashers (, finely diced)","3/4 tsp salt","Pepper","1 tbsp parsley (, finely chopped (for garnish - optional))"]}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Heat 1/2 tbsp of olive oil in a pan over high heat. Add the bacon and sauté until crispy. Remove and drain on a paper towel.","images":[],"step":2},{"description":"Peel and grate the potatoes and place in a colander. Rinse under cold water for a few seconds (to remove starch which helps make them fluffy inside and also stops the potatoes from browning).","images":[],"step":3},{"description":"Working a handful at a time, squeeze out the excess water and place into the bowl.","images":[],"step":4},{"description":"Add most of the bacon (reserve some to garnish), 2 tbsp olive oil, salt, pepper and cheese. Mix well to combine.","images":[],"step":5},{"description":"Spray a 12 hole muffin tray with oil.","images":[],"step":6},{"description":"Place 1/3 cup (packed) of the mixture into each hole. Pat down lightly with the back of a spoon.","images":[],"step":7},{"description":"Bake for 30 minutes until dark golden brown on top.","duration":30,"images":[],"step":8},{"description":"Let stand for a few minutes before turning out from the muffin tray.","images":[],"step":9},{"description":"Garnish with parsley and remaining bacon, and serve immediately.","images":[],"step":10}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["main_course"],"cuisine":[],"categories":["breakfast-recipes","most-popular","muffin-recipes","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a3d8b63f49f4', 'en', 'US', 'Zucchini Tian (Naturally Healthy)', 'The real name of this dish is Tian de Courgettes au Riz (Zucchini Tian) and it is a Julia Child recipe. It is like a cross between a gratin and risotto. You will be amazed by how creamy this cream-less, butter-less dish is, yet has only 250 calories per serving (as a main).', 'https://www.recipetineats.com/tachyon/2014/08/Zucchini-Risotto-2.jpg', 5, 45, 50, 4, '[{"id": "ing_zucchini", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_zucchini", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_parmesan", "quantity": {"value": 0.333, "unit": "pack of 200g"}}, {"id": "ing_white_rice", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1 kg (2 lb) zucchini","1 brown onion (, finely diced (1 cup))","2 garlic cloves (, minced)","3 tbsp olive oil (, separated)","2 1/2 cups warm liquid: zucchini juices plus milk (, heated in a pan (see directions))","2/3 cups parmesan cheese (, grated)","1/2 cup medium grain white rice (, uncooked (Note 6))","2 tbsp flour","2 tsp salt","Black pepper"]}]', '[{"description":"Prepare the Zucchini","images":[],"step":1},{"description":"Grate the zucchini and place in a large bowl. Sprinkle with 2 tsp salt and use your hands to mix through well.","images":[],"step":2},{"description":"Place zucchini in a colander over a bowl to collect the juices that sweat out. Leave for at least 20 minutes.","images":[],"step":3},{"description":"Squeeze the liquid out of the zucchini, straining the liquid through the colander to add to the zucchini juices collected.","images":[],"step":4},{"description":"Rinse the zucchini under cold water for 15 seconds, then squeeze out excess water, but this time do not save the water that is squeezed out.","duration":0.25,"images":[],"step":5},{"description":"Pat the zucchini with paper towels to mostly dry.","images":[],"step":6},{"description":"To Prepare Gratin","images":[],"step":7},{"description":"Top up the zucchini juices with milk to make a total of 2 1/2 cups of liquid. Warm liquid in microwave or on the stove.","images":[],"step":8},{"description":"Heat 2 tbsp olive oil in a large heavy base pan over medium heat. Add garlic and onion and sauté for 8 minutes until translucent and starting to turn golden.","duration":8,"images":[],"step":9},{"description":"Turn heat up to medium high, add the zucchini and cook for 5 minutes, stirring frequently.","duration":5,"images":[],"step":10},{"description":"Add flour and cook for 2 minutes, stirring constantly.","duration":2,"images":[],"step":11},{"description":"Remove from heat. Add all but 2 tbsp of the parmesan cheese and stir quickly to combine.","images":[],"step":12},{"description":"Do a taste test to check for seasoning. Add more salt if desired, and a good grind of black pepper. I do not add more salt as I don''t think it is required.","images":[],"step":13},{"description":"Add rice and liquid. If making ahead, stop here, then proceed with the next step on the day of serving.","images":[],"step":14},{"description":"Preheat oven to 220C/425F","images":[],"step":15},{"description":"Return pan to heat and bring to simmer.","images":[],"step":16},{"description":"If the pan you are using is not ovenproof, pour the contents into a buttered baking dish.","images":[],"step":17},{"description":"Sprinkle over the remaining 2 tbsp of parmesan cheese and drizzle over the remaining 1 tbsp of olive oil.","images":[],"step":18},{"description":"Cover with lid or foil, then place in the top 1/3 of the oven.","images":[],"step":19},{"description":"Bake for 15 minutes, then remove the lid/foil and bake for a further 10 to 15 minutes until the top is golden and the liquid appears to have been absorbed. (Tilt the dish slightly. If liquid pools then return to the oven for 5 minutes at a time.)","duration":15,"images":[],"step":20},{"description":"Rest for 10 minutes. While resting, any residual liquid will be absorbed.","duration":10,"images":[],"step":21},{"description":"Best served immediately.","images":[],"step":22}]', '["gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["French","Italian"],"categories":["breakfast-recipes","dietary","low-calorie-recipes","one-pot-recipes","winter-recipe-collection","zucchini-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d36e56a31b76', 'en', 'US', 'Chicken and Spinach Strata (Bread Bake)', 'Dinner in a snap! No chopping, and a great way to use up leftovers.', 'https://www.recipetineats.com/tachyon/2014/08/Chicken-Spinach-Strata-Baking-Dish-1.jpg', 10, 15, 25, 4, '[{"id": "ing_bread", "quantity": {"value": 1.312, "unit": "loaf"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_spinach", "quantity": {"value": 250.0, "unit": "bag of 250g"}}, {"id": "ing_chicken", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_egg", "quantity": {"value": 6.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["7 cups french bread (, cut into 2 cm / 1 inch cubes)","1 cup grated cheese (any melting cheese is fine - tasty, cheddar, mozzarella)","250 g / 8 oz frozen spinach (2 packets, chopped)","1 cup shredded or diced chicken (, or any other cooked protein, ham or bacon)","Parsley (, finely chopped (garnish - optional))"]},{"ingredients":["6 eggs","1 1/4 cups milk","1/4 cup grated parmesan","1 tsp salt","Black pepper"],"purpose":"Egg Mixture"}]', '[{"description":"Defrost the spinach in the microwave (4 minutes on high), then squeeze out excess water.","images":[],"step":1},{"title":"Make Egg mixture","description":"Place ingredients into a bowl and whisk until combined.","images":[],"step":2},{"description":"Spread half the bread into the base of a baking dish 25cm x 25cm (10\" x 10\").","images":[],"step":3},{"description":"Layer with the spinach, then chicken then top with half the cheese.","images":[],"step":4},{"description":"Top with remaining bread. Squish the bread down to compress (this helps the egg mixture to be soaked up evenly).","images":[],"step":5},{"title":"Pour over egg mixture","description":"try to cover all the bread evenly.","images":[],"step":6},{"description":"Top with remaining cheese, then squish down to help the bread soak up the egg mixture.","images":[],"step":7},{"description":"Set aside for at least 15 minutes, preferably 30 minutes.","images":[],"step":8},{"title":"To freeze","description":"Cover tightly and place in freezer. Defrost completely before cooking.","images":[],"step":9},{"description":"Preheat oven to 180C/350F.","images":[],"step":10},{"description":"Cover baking dish with foil and bake for 20 minutes. Remove foil, then bake for a further 10 minutes until golden on top.","duration":20,"images":[],"step":11},{"description":"Serve immediately, sprinkled with parsley if desired.","images":[],"step":12}]', '["egg","gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["main_course"],"cuisine":[],"categories":["breakfast-recipes","chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","one-pot-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ea2f0a206f51', 'en', 'US', 'Quiche Toast Cups', 'Cute mini quiches made using plain old sandwich bread. Who can possibly resist these? Makes 6 quiches (3 servings).', 'https://www.recipetineats.com/tachyon/2014/08/Quiche-Toast-Cup-2.jpg', 10, 15, 25, 3, '[{"id": "ing_bacon", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_onion", "quantity": {"value": 0.25, "unit": "pack of 1kg"}}, {"id": "ing_oil", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_bread", "quantity": {"value": 0.3, "unit": "loaf"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.167, "unit": "L"}}, {"id": "ing_cheese", "quantity": {"value": 0.333, "unit": "block of 250g"}}, {"id": "ing_parsley", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 5.0, "unit": "bottle"}}]', '[{"ingredients":["1 rasher of bacon (, rind removed, diced (50g / 1.5 oz))","1/4 onion (, finely diced (brown, white or yellow))","1 tsp oil","6 slices white sandwich bread (fresh)","2 regular size eggs (or 3 small)","2/3 cup milk","1/3 cup cheese (, grated (tasty, gruyere, cheddar - any good melting cheese))","2 tsp parsley (, finely chopped)","Salt and pepper","Oil spray"]}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Heat 1 tsp oil in small pan over high heat. Add onion and bacon and sauté until bacon is crisp - about 2 minutes. Remove from heat and set aside (you can just leave it in the pan).","images":[],"step":2},{"description":"Cut bread into rounds or just cut crusts off. I use a 800g/28oz tomato can (emptied and washed) - the perfect size to cut rounds to fit into muffin tins out of bread, pastry etc.","images":[],"step":3},{"description":"Use a rolling pin to flatten the bread.","images":[],"step":4},{"description":"Lightly spray 6 muffin tin holes with oil spray, then press the bread into the muffin tin.","images":[],"step":5},{"description":"Place in oven for 3 minutes. Remove from oven and set aside. The toast cups should not be browned, just a bit dry (like \"toast\").","duration":3,"images":[],"step":6},{"description":"Whisk together the egg, milk, parsley and a pinch of salt and pepper.","images":[],"step":7},{"description":"Divide the bacon mixture between the 6 toast cups, then the cheese.","images":[],"step":8},{"description":"Pour 2 1/2 tbsp of egg mixture into each cup, then immediately place in the oven. If you take too long between pouring the egg mixture into the toast cups and putting it in the oven, the egg will start soaking into the bread.","images":[],"step":9},{"description":"Bake for 12 to 15 minutes until the top is lightly golden and the filling is set.","duration":13.5,"images":[],"step":10},{"description":"Remove from oven and rest for 5 minutes before serving. The filling will be puffed up but it will deflate while resting.","duration":5,"images":[],"step":11},{"description":"Garnish with extra parsley if desired. Serve warm.","images":[],"step":12}]', '["egg","gluten","milk"]', '["low_calorie"]', '{"mealType":["breakfast","snack"],"cuisine":[],"categories":["breakfast-recipes","finger-food","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_59acf753cbfc', 'en', 'US', 'Giant Hash Brown', 'When you need to feed a crowd, why slave over the stove making batch after batch of hash browns when you can make one giant one?', 'https://www.recipetineats.com/tachyon/2014/07/Giant-Hash-Brown-2.jpg', 10, 15, 25, 4, '[{"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.06, "unit": "L"}}]', '[{"ingredients":["1 kg / 2 lb potatoes (starchy - see notes)","1 tsp salt (plus more to taste)","Black pepper","4 tbsp extra virgin olive oil (, separated)"]}]', '[{"description":"Peel and grate the potatoes, placing the grated potato into a large bowl of water (this stops the potato from going brown while you continue grating).","images":[],"step":1},{"description":"Using a large colander, rinse the potato until the water comes clear (to remove the starch which keeps the potato from going brown as well as making it crispy).","images":[],"step":2},{"description":"Working a handful at a time, squeeze out the excess water and place into the bowl.","images":[],"step":3},{"description":"Mix in 1 tbsp of olive oil, salt and pepper.","images":[],"step":4},{"description":"Heat 2 tbsp olive oil in a 22cm/9 inch non stick pan over medium high heat.","images":[],"step":5},{"description":"Place shredded potato mixture in pan, spread out and lightly pat down with a spatula. It should be about 1.5cm/0.6\" thick.","images":[],"step":6},{"description":"Cook for 5 to 8 minutes until golden brown and crispy. Use a spatula to lift a corner to check for doneness.","duration":6.5,"images":[],"step":7},{"description":"Get a large plate and slide the hash brown onto it.","images":[],"step":8},{"description":"Place the pan on top of the plate, then quickly flip upside down. Use a tea towel if you need so you can hold onto the fry pan when flipping. Don''t worry if it breaks when you flip it, it''s salvageable!","images":[],"step":9},{"description":"Drizzle the remaining 1 tbsp of oil around the edges of the fry pan. If your hash brown broke when you flipped it, use a spatula to lightly pat it back into shape.","images":[],"step":10},{"description":"Cook until golden brown and crispy, about 4 to 6 minutes. Use a spatula to lift up to check.","images":[],"step":11},{"description":"Slide out of the plan onto a serving plate. Season with additional salt if required. To serve, garnish with chopped parsley (optional) and cut into wedges.","images":[],"step":12}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["breakfast"],"cuisine":[],"categories":["breakfast-recipes","most-popular","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f722aa1315ec', 'en', 'US', 'Twice Baked Make Ahead Cheese Souffle', 'A twice baked light-as-air cheese soufflé covered in a golden, bubbly, creamy sauce that is freezer (and refrigerator) friendly. You will be amazed how much it puffs up when you bake it the 2nd time just prior to serving!', 'https://www.recipetineats.com/tachyon/2014/06/Twice-Baked-Make-Ahead-Cheese-Souffle.jpg', 15, 35, 50, 4, '[{"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_cream", "quantity": {"value": 1.25, "unit": "carton of 250ml"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}]', '[{"ingredients":["60 g / 2 oz / 4 tbsp unsalted butter","1 cup finely chopped leeks or scallions/shallots (white part only)","1/3 cup (40 g / 1.5 oz) plain all purpose flour (unsifted)","1 cup milk","1 cup grated good melting cheese (see notes)","3 eggs (, separated)","Pinch of salt and pepper"]},{"ingredients":["1 1/4 cups cream (unwhipped)","4 tbsp grated cheese","Pinch of salt and pepper"],"purpose":"For Reheating/Second Bake"}]', '[{"description":"Preheat oven to 180C/350F. Grease four ramekins or 6 small ramekins very well (see notes for size).","images":[],"step":1},{"description":"Bring kettle to boil with plenty of water.","images":[],"step":2},{"description":"Melt half the butter (i.e. 2 tbsp) in a medium saucepan over medium heat, add the leek and cook for a couple of minutes until softened, then remove from pan into a bowl.","images":[],"step":3},{"description":"In the same pan, melt the remaining butter, add the flour and stir for a couple of minutes. Then whisking constantly, add 1/4 of the milk, and when it has combined (it will be a thick paste consistency) add the remaining milk, whisking constantly over the medium heat.","images":[],"step":4},{"description":"Continue to whisk and in a minute or two, it will start to thicken. Once it becomes the consistency of a thick pouring cream, remove from heat, add the cheese and leeks and mix to combine. The cheese does not need to melt. Set aside for 5 minutes to cool slightly, then add the egg yolks, salt and pepper and mix to combine.","duration":5,"images":[],"step":5},{"description":"Meanwhile, beat the egg whites until stiff then fold a spoonful of the whites into the cheese mixture to lighten it. Then pour the cheese mixture into the bowl with the egg whites and gently fold it to combine. Do NOT over mix as it will knock out the air out of the egg whites, it is mixed enough when there are still slight streaks of white and yellow.","images":[],"step":6},{"description":"Spoon the mixture into ramekins and smooth the tops. Place in a baking dish then pour boiling water around the ramekins so that it comes half way up their sides.","images":[],"step":7},{"description":"Bake in oven for about 20 minutes or until puffed up and golden on top. Remove from oven and leave in ramekins for a couple of minutes. Then run a small knife around the edge before turning out the souffles. They will deflate a little as they cool.","images":[],"step":8},{"title":"To freeze","description":"Once completely cool, cover in cling wrap and freeze. To make, defrost completely (do not use microwave), I usually do this by leaving them in the fridge overnight.","images":[],"step":9},{"description":"Second Bake Prior to Serving","images":[],"step":10},{"description":"Preheat the oven to 180C/350F.","images":[],"step":11},{"description":"Place a soufflé on a gratin or pie dish (I used a tart dish), pour 1/4 of the cream over the top, scatter 1 tbsp grated cheese and a pinch of salt and pepper.","images":[],"step":12},{"description":"Bake for 15 minutes until puffed up and the cream is bubbly and golden.","duration":15,"images":[],"step":13},{"description":"Serve immediately.","images":[],"step":14}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["breakfast","snack"],"cuisine":["French"],"categories":["breakfast-recipes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_082af9008802', 'en', 'US', 'Really Quick Broccoli Pasta', 'Recipe video above. This is a great emergency meal OR carb + veg side for all those times when your cupboards are bare except for broccoli, pasta, and some kind of cheese. It''s saucy without using tons of oil, and there''s loads of sub options. Quick and utterly scrumptious - loaded with tons of broccoli!', 'https://www.recipetineats.com/tachyon/2019/04/Broccoli-Pasta_5.jpg', 5, 10, 15, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.7, "unit": "pack of 500g"}}, {"id": "ing_broccoli", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.075, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_mixed_herbs", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}]', '[{"ingredients":["350g / 12 oz dried short pasta (I used small shells)","2 broccoli heads (BIG!)","1 cup shredded cheese (or more!)"]},{"ingredients":["2 tsp lemon zest","2 tbsp lemon juice (or more!)","5 tbsp extra virgin olive oil","1/3 cup parmesan (, finely grated)","2 garlic cloves (, minced)","1 tsp mixed dried herbs (or fresh!)","1/2 tsp+ red pepper flakes (add more if you want spicy!)","1 tsp sugar","3/4 tsp salt","1/2 tsp pepper"],"purpose":"Pasta Sauce (Notes for subs):"},{"ingredients":["More parmesan"],"purpose":"Serving:"}]', '[{"title":"Cook pasta","description":"Boil a large pot of water with 2 tsp salt, add pasta.","images":[],"step":1},{"description":"While pasta is cooking:","images":[],"step":2},{"title":"Chop broccoli","description":"Chop broccoli into small florets.","images":[],"step":3},{"title":"Cook broccoli: Add broccoli into water 1","description":"2 minutes before pasta is cooked.","images":[],"step":4},{"title":"Sauce ingredients in jar","description":"Place Sauce ingredients in a jar with lid.","images":[],"step":5},{"title":"Reserve pasta water","description":"SCOOP OUT 1 cup pasta cooking water just before draining. Then drain and return pasta back into same pot on turned off stove.","images":[],"step":6},{"title":"Add pasta water into Sauce","description":"Add 1/2 cup pasta water to Pasta Sauce jar, shake well.","images":[],"step":7},{"title":"Add Sauce & Cheese to pasta","description":"Pour Sauce and add cheese into pot with pasta.","images":[],"step":8},{"description":"Stir then serve! Stir vigorously, adding more pasta water if required. Add more salt and pepper if required. Serve immediately, garnished with parmesan.","images":[],"step":9}]', '["gluten","milk"]', '["high_protein","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["broccoli-recipes","dinner-tonight","emergency-recipes","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy","side-dishes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d88f3516a58f', 'en', 'US', 'Broccoli and Potato Soup', 'Recipe video above. A thick, hearty, creamy Broccoli and Potato Soup that will warm your soul! Tastes rich and indulgent, but it''s made without a single drop of cream.', 'https://www.recipetineats.com/tachyon/2017/01/Potato-Broccoli-Soup_1.jpg', 10, 20, 30, 4, '[{"id": "ing_butter", "quantity": {"value": 40.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_potato", "quantity": {"value": 800.0, "unit": "bag of 2kg"}}, {"id": "ing_broccoli", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_bacon", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}]', '[{"ingredients":["40g / 3 tbsp unsalted butter","1 small onion (, finely chopped)","2 garlic cloves (, minced)","1/3 cup flour","2 cups milk (, any fat %)","2 cups chicken broth/stock (, low sodium)","2 cups water","1 tsp salt","1/2 tsp black pepper","800 g / 1.6 lb potato (, peeled and cut into 1.25 / 1/2\" cubes (Note 1))","5 cups broccoli, small florets (1 large head, ~300g/10oz, Note 1)","1+ cups grated cheese (, cheddar or tasty (or other of choice))"]},{"ingredients":["Cook bacon pieces (highly recommended)","Shallots/scallions (, finely sliced)","Grated cheese"],"purpose":"Garnish, optional"}]', '[{"description":"Melt butter in a large pot over medium high heat. Add onion and garlic, cook for 3 minutes or until onion is softened.","duration":3,"images":[],"step":1},{"description":"Add flour and mix into onion mixture. Cook for 30 seconds.","duration":0.5,"images":[],"step":2},{"description":"While stirring, slowly pour the milk in and keep mixing as it turns into a thickish paste that''s mostly smooth. Use a whisk to make it smooth if needed.","images":[],"step":3},{"description":"Add chicken stock, water, salt and pepper. Stir, then add potato.","images":[],"step":4},{"description":"Bring to simmer then adjust heat so it''s simmering gently. Cook for 8 minutes (no lid) or until potato is almost cooked. Stir ocassionally so the base doesn''t catch.","duration":8,"images":[],"step":5},{"description":"Add broccoli and stir. Cook for 2 minutes (or until broccoli is cooked to your liking), then take the pot off the stove.","duration":2,"images":[],"step":6},{"title":"Stir through cheese (I use 1 cup)","description":"broth soup be nicely thickened. Add more salt if needed.","images":[],"step":7},{"description":"Ladle into bowls and top with garnishes of choice.","images":[],"step":8}]', '["gluten","milk"]', '[]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["broccoli-recipes","dietary","gluten-free-recipes","low-calorie-recipes","main-dishes","potato-recipes","quick-and-easy","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d971123c585b', 'en', 'US', 'Easy Broccoli Cheese Soup', 'Recipe video above. This Broccoli Soup is a cream of broccoli soup that''s thick and creamy, with a great hit of cheese! It''s creamy whether you make it with or without cream, though the cream does add an extra edge of luxury. Don''t forget the hot crusty bread for dunking!', 'https://www.recipetineats.com/tachyon/2016/01/Broccoli-Cheese-Soup_2-1.jpg', 5, 25, 30, 5, '[{"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_broccoli", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_potato", "quantity": {"value": 2.0, "unit": "bag of 2kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}]', '[{"ingredients":["1 tbsp (15g) butter (or olive oil)","2 garlic cloves (, minced)","1 onion (, diced (brown, white yellow))","4 cups (1 litre) chicken broth / stock (, low sodium (or veg stock))","1 1/2 cups water","700g / 1.4lb broccoli florets (2 large broccoli + diced peeled stem, Note 1)","2 potatoes (, peeled and diced into 1.5cm / 2/3\" cubes)","3/4 tsp cooking salt / kosher salt","1/4 tsp black pepper","1 1/2 cups cheddar cheese (, shredded (or other cheese of choice))","3/4 cup cream (or milk)"]},{"ingredients":["Cream, for drizzling","Extra grated cheese"],"purpose":"To Serve (optional)"}]', '[{"description":"Melt butter in a large pot over medium high heat. Add onion and garlic, saute for 2 minutes until onion is softened.","duration":2,"images":[],"step":1},{"description":"Add broth/ water, broccoli, potato, salt and pepper. Bring to simmer, then place the lid on, turn the heat down to medium high and cook for 20 minutes or until the broccoli is soft.","duration":20,"images":[],"step":2},{"description":"Turn stove off (but leave on stove). Puree using a stick blender until smooth (Note 2).","images":[],"step":3},{"description":"Stir in cream, then add cheese a handful at a time, stirring in between to melt.","images":[],"step":4},{"description":"Taste and add more salt if desired.","images":[],"step":5},{"description":"Ladle into bowls. Drizzle with cream and top with extra grated cheese, if desired.","images":[],"step":6}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["main_course"],"cuisine":[],"categories":["broccoli-recipes","dietary","dinner-tonight","gluten-free-recipes","low-calorie-recipes","main-dishes","quick-and-easy","soup-recipes","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8986b538e293', 'en', 'US', 'Broccoli Chicken Fritters', 'Recipe video above. This combination of juicy chicken pieces and tender broccoli inside a fritter with a crispy golden crust is seriously delicious! For a version made with ground chicken (mince), try these Baked Chicken Broccoli Patties.', 'https://www.recipetineats.com/tachyon/2019/04/Broccoli-Chicken-Fritters_1.jpg', 10, 20, 30, 16, '[{"id": "ing_broccoli", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.2, "unit": "tub of 500g"}}, {"id": "ing_ketchup", "quantity": {"value": 0.06, "unit": "bottle of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}]', '[{"ingredients":["1 large head broccoli (, cut into florets)","500g / 1lb chicken breast or thigh (, cut into 0.8cm / 1/3\" pieces)","1/2 cup (75g) flour (any type)","1/2 cup (50g) parmesan cheese (, grated or shredded)","2 eggs","2 garlic cloves (, minced)","3/4 tsp salt","Pepper"],"purpose":"Fritters:"},{"ingredients":["3 - 4 tbsp olive oil"],"purpose":"Cooking:"},{"ingredients":["2/3 cup (165g) sour cream or Greek yogurt","2 tbsp ketchup","Squeeze of lemon (, plus more for serving (optional))"],"purpose":"Pink Sauce – mix:"}]', '[{"description":"Preheat oven to 100C/210F.","images":[],"step":1},{"description":"Steam broccoli until tender, then roughly chop. (Note 1)","images":[],"step":2},{"description":"Add broccoli and remaining Fritter ingredients in a bowl and mix well.","images":[],"step":3},{"description":"Add enough oil in skillet to cover base. Heat to medium high.","images":[],"step":4},{"description":"Dollop 1/4 cup mixture into skillet, then pat down. (Note 2)","images":[],"step":5},{"description":"Cook 2.5 minutes until deep golden, then flip and cook for 2 minutes.","duration":2,"images":[],"step":6},{"description":"Transfer to rack, keep warm in oven.","images":[],"step":7},{"description":"Serve with Pink Sauce!","images":[],"step":8}]', '["egg","gluten","milk"]', '["keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["broccoli-recipes","chicken","chicken-breast-recipes","chicken-recipes","dinner-tonight","fritters-tots-and-similar","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6f18a4b4bf95', 'en', 'US', 'One Pot Broccoli, Chicken and Rice Casserole', 'Recipe VIDEO above. Made from scratch, this tastes like a risotto but is so much more straight forward to make! A complete meal in one pot.', 'https://www.recipetineats.com/tachyon/2018/01/One-Pot-Chicken-Broccoli-Rice_7.jpg', 10, 20, 30, 5, '[{"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_white_rice", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_broccoli", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.6, "unit": "pack of 125g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["2 tbsp (30g ) unsalted butter","1 tbsp olive oil","1 onion (, finely chopped)","2 garlic cloves (, minced)","500g (1 lb) chicken thigh (, cut into bite size pieces (Note 1))","2.5 tbsp flour (or 1 ½ tbsp. cornflour / cornstarch)","2 cups (500 ml) milk (any, I use low fat)","2 cups (500 ml) chicken broth","1 1/4 cups (225g) long grain white rice (, uncooked (Note 2))","1 tsp dried thyme (or other herb of choice)","Salt and pepper","1 large head of broccoli, broken / cut into small florets (~400 - 500g / 14 oz - 1 lb) (Note 3)","2 cups (200g) shredded mozzarella or cheddar (or other cheese of choice) (Note 4)","Finely chopped parsley (, optional garnish)"]}]', '[{"description":"Melt butter and heat oil in a pot over high heat. Add onion and garlic, cook for 1 minute. Add chicken and cook until it changes from pink to white. (Note 5)","duration":1,"images":[],"step":1},{"description":"Turn stove DOWN to medium. Add flour and stir for 1 minute.","duration":1,"images":[],"step":2},{"description":"Add half the milk, stirring as you go, and once incorporated into the flour add the rest of the milk and stir.","images":[],"step":3},{"description":"Add broth, rice, thyme and a just pinch of salt and pepper.","images":[],"step":4},{"description":"Stir, bring to simmer, then cover. Turn down to medium low and cook for 12 minutes.","duration":12,"images":[],"step":5},{"title":"Remove lid","description":"there should still be liquid on the surface. Working quickly, add broccoli, push down so it’s partly submerged, cover and cook for a further 3 minutes until broccoli is just cooked.","images":[],"step":6},{"description":"Preheat grill/broiler. Remove lid and stir through half the cheese – don’t worry if it looks a bit too saucy, excess liquid gets sucked up in minutes (see video). Smooth surface, top with remaining cheese. Grill/broil until melted (or just put lid on and allow to melt with residual heat on turned off stove).","images":[],"step":7},{"description":"Serve immediately, garnished with parsley if desired.","images":[],"step":8}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["broccoli-recipes","casseroles-and-cosy-bakes","chicken-breast-recipes","chicken-recipes","dinner-tonight","one-pot-recipes","quick-and-easy","rice-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f93451a7e231', 'en', 'US', 'Cheesy Chicken Mince Fritters with Broccoli', 'Recipe video above. It''s hard to believe these fritters made with chicken mince are BAKED not FRIED! With almost an entire head of broccoli in them, these are juicy, cheesy and so irresistible. This makes 15 fritters about 6 cm / 2.25" wide, 1cm / 2/5" thick. Trying making burgers or meatballs!', 'https://www.recipetineats.com/tachyon/2017/08/Cheesy-Broccoli-Chicken-Fritters-6.jpg', 15, 25, 40, 4, '[{"id": "ing_chicken_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_broccoli", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.5, "unit": "pack of 125g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_yogurt", "quantity": {"value": 0.2, "unit": "tub of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 0.013, "unit": "bunch"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}]', '[{"ingredients":["500 g / 1 lb chicken mince (ground chicken) (, or turkey or pork (Note 1))","1 garlic clove, (minced)","1 egg","¾ cup panko breadcrumbs","2 packed cups broccoli (, soft cooked & finely chopped (1 head)(Note 2))","¾ cup finely chopped shallots","1 1/2 - 2 cups shredded mozzarella (or other cheese of choice)","3/4 tsp salt (reduce to 1/2 tsp if using a flavoured cheese)(Note 3)","Black pepper"],"purpose":"Fritters:"},{"ingredients":["Oil spray"],"purpose":"Cooking:"},{"ingredients":["2/3 cup plain yoghurt","1/8 tsp EACH dried dill, parsley and chives","¼ tsp onion powder","½ garlic clove, minced","1 - 2 tsp extra virgin olive oil","Squeeze of lemon juice, (optional)"],"purpose":"Yoghurt Ranch Sauce (optional):"}]', '[{"description":"Preheat oven to 200C/390F. Line a baking tray with baking paper (or spray with oil).","images":[],"step":1},{"description":"Place Fritter ingredients in a bowl, mix to combine.","images":[],"step":2},{"description":"Measure out about ¼ cup of mixture and pat into fritter shapes about 6 cm / 2.25\" wide, 1cm / 2/5\" thick (they shrink a bit and become thicker).","images":[],"step":3},{"description":"Place on tray. Spray the top (generously) with oil.","images":[],"step":4},{"description":"Bake for 15 minutes, flip, spray with oil again then bake for a further 8 - 10 minutes until golden on top. Serve immediately with Sauce.","duration":15,"images":[],"step":5},{"title":"Sauce","description":"Mix ingredients together. Add salt and pepper to taste. Set aside for 20+ minutes.","images":[],"step":6}]', '["egg","milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["broccoli-recipes","chicken-mince-recipes","chicken-recipes","dinner-tonight","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_09f462259731', 'en', 'US', 'Ultra Lazy Creamy Chicken and Broccoli Pasta Bake', 'Recipe video above. One for all those busy nights - a complete HEALTHY meal all made in one baking dish. 5 minutes prep, pop it in the oven, then out comes perfectly cooked chicken and broccoli pasta bake smothered in a creamy sauce. Serves 4 - 5.', 'https://www.recipetineats.com/tachyon/2017/07/Ultra-Lazy-Creamy-Chicken-Pasta-Bake-2.jpg', 10, 35, 45, 5, '[{"id": "ing_chicken", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_broccoli", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}]', '[{"ingredients":["400g / 14 oz chicken tenderloin (raw) (, breast or thigh, cut into 1.5cm / 3/5\" pieces)","Salt and pepper","1 tsp dried thyme (or other herbs and/or spices of choice)","250g / 8 oz spiral pasta, uncooked (See Note 1 for other shapes)","1/4 cup flour (all purpose / plain)","1 1/2 cups chicken broth/stock (, warmed)","2 cups milk (, warmed (any fat %))","1 large garlic clove (, minced)","2 tbsp / 30g unsalted butter (, recommended but optional)","1 large broccoli ( or 2 medium broccoli or cauliflower, broken into small to medium florets (Note 2 for subs))","1 1/2 cups (tightly packed) shredded cheddar or colby cheese (or tasty cheese, pizza mix etc, Note 3)"]}]', '[{"description":"Preheat oven to 200°C/390°F (180°C fan-forced).","images":[],"step":1},{"description":"Sprinkle chicken with salt (be generous), pepper and thyme, toss to coat.","images":[],"step":2},{"description":"Spread pasta in a 23 x 33cm / 9 x 13\" baking dish. Sprinkle flour all across the surface (don''t dump in clump else it won''t dissolve). Pour over milk and broth, add garlic and butter. Stir.","images":[],"step":3},{"description":"Spread chicken over the top, then broccoli.","images":[],"step":4},{"description":"Cover with foil, bake for 15 minutes (or 20 minutes if milk & broth were cold).","duration":15,"images":[],"step":5},{"description":"Remove foil, STIR WELL. Add most of the cheese, then STIR WELL again. Top with remaining cheese.","images":[],"step":6},{"title":"Return to oven. Bake for 15","description":"20 minutes until top is golden and sauce is thickened (See note 4 for troubleshooting).","duration":17.5,"images":[],"step":7},{"description":"Stand for a few minutes then serve immediately!","images":[],"step":8}]', '["gluten","milk"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["broccoli-recipes","casseroles-and-cosy-bakes","chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","emergency-recipes","low-calorie-recipes","main-dishes","one-pot-pasta-recipes","one-pot-recipes","pasta-bakes","pasta-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_713a132f3934', 'en', 'US', 'Baked Broccoli Cheese Balls', 'You''ll be surprised how much broccoli is crammed into these! They certainly don''t taste healthy - but they are. They are juicy and moist inside, golden on the outside, they stay pretty round after baking, and are gorgeous to serve as a vegetarian main or as bites! Serves 3 - 4 as a main. Recipe video below and Gluten Free option in notes.', 'https://www.recipetineats.com/tachyon/2017/05/Broccoli-Cheese-Balls-3.jpg', 15, 25, 40, 3, '[{"id": "ing_broccoli", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 0.188, "unit": "loaf"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_cheese", "quantity": {"value": 0.75, "unit": "block of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.04, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_yogurt", "quantity": {"value": 1.0, "unit": "tub of 500g"}}]', '[{"ingredients":["2 cups (packed) roughly chopped soft cooked broccoli (well drained) (~400g/14 oz raw broccoli) (Note 1)","1 cup panko breadcrumbs","2 large eggs (~55g/2oz each in-shell)","3/4 cup shredded cheese (Cheddar, Colby or Tasty cheese are my usual)","2 green onion stems (, finely sliced)","2 cloves garlic (, finely minced)","1/4 tsp cooking salt / kosher salt (halve for table salt, + 50% for flakes)","Black pepper","Olive oil spray"]},{"ingredients":["1 batch Lemon Yogurt Sauce (or plain yogurt)"],"purpose":"To serve:"}]', '[{"description":"Preheat oven to 200°C/400°F (180°C fan forced). Line a tray with baking / parchment paper. (Note 2)","images":[],"step":1},{"title":"Mixture","description":"Place all ingredients (except oil spray) in a bowl. Mix well to combine, mashing up the broccoli as you go (like when you are cooking mince).","images":[],"step":2},{"title":"Form balls","description":"Scoop up a heaped tablespoon, then press in firmly. Flick out into your hand then form into a ball. Place on tray. Repeat with remaining mixture - should make 15 - 18 balls.","images":[],"step":3},{"title":"Spray and bake","description":"Spray with oil then bake for 25 minutes, or until the surface is slightly crisp and golden.","duration":25,"images":[],"step":4},{"title":"Serve with Lemon Yoghurt Sauce","description":"it also goes great with ketchup!","images":[],"step":5}]', '["egg","milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["broccoli-recipes","finger-food","fritters-tots-and-similar","quick-and-easy","super-bowl-party-food","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1a81fbb46188', 'en', 'US', 'Baked Macaroni Cheese with Chicken & BROCCOLI', 'EASY baked Mac and Cheese loaded with chicken and broccoli - a COMPLETE meal all made in one pot! This recipe requires the specific ratio of water, milk and macaroni that I''ve specified in the recipe. Don''t be alarmed at how much liquid there is when you take it out of the oven before broiling/grilling the top. You will be surprised how quickly the liquid evaporates into a thick sauce. Watch the VIDEO to see how easy this is to make!', 'https://www.recipetineats.com/tachyon/2016/02/Baked-Macaroni-Cheese-Chicken-Broccoli_1.jpg', 15, 30, 45, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.625, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.6, "unit": "pack of 500g"}}, {"id": "ing_broccoli", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_panko", "quantity": {"value": 37.5, "unit": "jar"}}, {"id": "ing_parmesan", "quantity": {"value": 0.15, "unit": "pack of 200g"}}]', '[{"ingredients":["1 tbsp olive oil","1 lb / 500g skinless chicken breast or thigh fillets (, cut into bite size pieces)"]},{"ingredients":["3 tbsp butter","2 garlic cloves (, minced)","1 small onion (, finely chopped)","4 tbsp plain flour","2 1/2 cups milk (, low fat)","1 cup water","1 tsp salt","Black pepper","2 cups macaroni / elbow pasta (Note 1)","1 large head of broccoli (, broken into florets (or 1 1/2 smaller ones))","1 1/2 - 2 cups grated cheese (cheddar, tasty or gruyere)"],"purpose":"Mac N Cheese"},{"ingredients":["1/4 cup panko (or ordinary breadcrumbs)","2 tbsp parmesan cheese"],"purpose":"Topping"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Heat oil in a deep heavy based skillet or dutch oven over high heat. Add chicken and cook until just cooked - it''s fine if it''s still raw inside. Remove chicken into a bowl. (Note 2)","images":[],"step":2},{"description":"Reduce heat to medium and melt butter. Add garlic and onion and saute for 5 minutes until onion is translucent. Add flour and cook for 1 minute.","duration":5,"images":[],"step":3},{"description":"Pour in half the milk and whisk it in so the flour butter mixture melts. It should thicken quite quickly - around 30 seconds. Pour the remaining milk in, whisking constantly, then add the water, salt and pepper.","images":[],"step":4},{"description":"Turn the heat up to medium high and cook, whisking occasionally, for around 3 to 5 minutes until you start seeing steam rising from the white sauce when you whisk it.","images":[],"step":5},{"description":"Add the macaroni and chicken, stir, then top with broccoli.","images":[],"step":6},{"description":"Place the lid on and bake for 20 minutes.","duration":20,"images":[],"step":7},{"description":"Remove from the oven, switch oven to broiler/grill on high.","images":[],"step":8},{"description":"Remove lid (Note 3), stir through cheese, then sprinkle over panko and parmesan. (Will still look bit watery at this stage).","images":[],"step":9},{"description":"Place pot under the broiler/grill for 5 minutes, or until top is golden.","duration":5,"images":[],"step":10},{"description":"Remove, then let it stand for 5 minutes before serving (sauce thickens quickly).","duration":5,"images":[],"step":11}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["broccoli-recipes","casseroles-and-cosy-bakes","chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","most-popular","one-pot-pasta-recipes","one-pot-recipes","pasta-bakes","pasta-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ce2d27eb46ee', 'en', 'US', 'Creamy Bacon, Chicken and Broccoli Strata (Bread Bake)', 'A creamy chicken and broccoli bake made from scratch topped with bread and panko to make it extra crunchy! It''s like a pasta bake / strata (savoury bread pudding), just as filling but with a lot less carbs.', 'https://www.recipetineats.com/tachyon/2014/08/Creamy-Bacon-Chicken-Broccoli-Bake-1.jpg', 15, 40, 55, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 2.0, "unit": "pack of 200g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_broccoli", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 40.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 0.5, "unit": "block of 250g"}}, {"id": "ing_milk", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 3.0, "unit": "loaf"}}, {"id": "ing_panko", "quantity": {"value": 37.5, "unit": "jar"}}, {"id": "ing_parmesan", "quantity": {"value": 0.15, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["250 g / 8 oz chicken breast fillet (, cut into small bite size pieces)","2 bacon rashers (, diced)","1 small brown onion ((or 1/2 large), diced)","4 packed cups (300g/10oz) broccoli florets","1 garlic clove (, minced)","1/2 tbsp olive oil"]},{"ingredients":["40 g / 1.3 oz / 3 tbsp butter","1/2 cup flour","1/2 cup grated cheese (tasty, cheddar, gruyere or any other good melting cheese)","3 cups low fat milk","1 tsp garlic powder","1/2 tsp salt","Black pepper"],"purpose":"Béchamel Sauce"},{"ingredients":["3 to 4 slices of thick slice white sandwich bread (, cut into 1cm / 1/3\" cubes (note 1))","1/4 cup panko (or breadcrumbs)","2 tbsp parmesan cheese (, grated)","Fresh parsley (, finely chopped, to garnish (optional))"],"purpose":"Topping"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Chicken Mixture","images":[],"step":2},{"description":"Heat olive oil in a deep non stick fry pan over high heat. Add onion, minced garlic and bacon. Saute for 2 to 3 minutes until onion is translucent and bacon is starting to brown.","duration":2.5,"images":[],"step":3},{"description":"Add chicken and cook just until the outside of the chicken turns white (do not cook through). By this time, the onion should be caramelised and bacon should be crisp.","images":[],"step":4},{"description":"Remove from pan onto paper towel to drain.","images":[],"step":5},{"description":"Make the Béchamel Sauce (see notes for tips)","images":[],"step":6},{"description":"Lower heat to medium. Wipe pan clean and return to heat.","images":[],"step":7},{"description":"Melt butter, then add flour and whisk constantly for 1 1/2 minutes.","images":[],"step":8},{"description":"Add 1 1/2 cups of milk, whisking constantly, until it is well combined and lump free. It should be very thick.","images":[],"step":9},{"description":"Add remaining milk and whisk to combine well. Cook for 2 minutes or so, whisking constantly, until it thickens to the consistency of pouring cream (not whipped cream).","duration":2,"images":[],"step":10},{"description":"Remove from heat and add garlic powder, cheese, salt and pepper. Whisk until the cheese is melted and the sauce is smooth. Do a taste test and add more salt if you want.","images":[],"step":11},{"description":"Assemble and Bake","images":[],"step":12},{"description":"Place broccoli in baking dish (see notes for size), then top with chicken onion mixture. Pour over half the béchamel sauce.","images":[],"step":13},{"description":"Top with bread cubes, then drizzle over the remaining béchamel sauce as evenly as possible over the bread cubes. Use an egg flip to squash the bread cubes down - this helps disperse the béchamel sauce throughout the bake.","images":[],"step":14},{"description":"Sprinkle over panko and parmesan cheese.","images":[],"step":15},{"description":"Place in oven and bake for 20 to 25 minutes, until golden brown.","duration":22.5,"images":[],"step":16},{"description":"To Serve","images":[],"step":17},{"description":"Let stand for 5 minutes before serving. Garnish with finely chopped parsley, if desired.","duration":5,"images":[],"step":18}]', '["fish","gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["broccoli-recipes","casseroles-and-cosy-bakes","chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9c412e0af4e3', 'en', 'US', 'Amazing CRISPY Parmesan Garlic Roasted Brussels Sprouts', 'Recipe video above. With a crispy parmesan garlic crust and extra crunch from breadrumbs, these may well be the BEST brussels sprouts you ever have in your life!!! And they''re SO EASY.', 'https://www.recipetineats.com/tachyon/2019/10/Crispy-Parmesan-Roasted-Brussels-Sprouts_7.jpg', 35, 0, 35, 4, '[{"id": "ing_brussels_sprouts", "quantity": {"value": 500.0, "unit": "unit"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}, {"id": "ing_bread", "quantity": {"value": 0.062, "unit": "loaf"}}]', '[{"ingredients":["500g/ 1lb brussels sprouts (Note 1)","2 tbsp extra virgin olive oil","2 garlic cloves (, minced)","1/2 tsp salt","1/4 tsp black pepper","1/3 cup (30g) parmesan (, finely grated)","1/3 cup panko breadcrumbs (Note 2)"]}]', '[{"description":"Preheat oven to 200°C/400°F.","images":[],"step":1},{"title":"Prepare brussels sprouts","description":"Trim the base, cut in half and remove the loose, rough outer leaves.","images":[],"step":2},{"description":"Place in a bowl, pour over oil and toss gently.","images":[],"step":3},{"description":"Sprinkle with garlic, salt, pepper, parmesan and breadcrumbs.","images":[],"step":4},{"description":"Toss to coat, then spread out on tray cut face down.","images":[],"step":5},{"description":"Roast for 20 minutes, flip then roast for a further 10 minutes until the outer leaves are deep golden brown and crispy (see photos/video).","duration":20,"images":[],"step":6},{"description":"Immediately transfer to warm serving bowl. Scrape loose parmesan breadcrumbs off the tray and sprinkle, then serve immediately.","images":[],"step":7}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["brussels-sprouts","quick-and-easy","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_dc56d370a655', 'en', 'US', 'Brussel Sprout Salad', 'This brussels sprout salad is a recipe I''m sharing at the request of a brussels-sprout-hating friend after I served this at a lunch! The key to what makes this so good is: shaving the brussels sprouts (makes the flavour so mild), the fresh juicy sweetness from the apple, pop of salty from the bacon and warm crunch from the hazelnuts. With all of that going on in a salad, you only need a very light simple dressing.', 'https://www.recipetineats.com/tachyon/2016/10/Brussel-Sprout-Salad-2.jpg', 15, 10, 25, 4, '[{"id": "ing_hazel_nuts", "quantity": {"value": 56.7, "unit": "jar"}}, {"id": "ing_bacon", "quantity": {"value": 0.9, "unit": "pack of 200g"}}, {"id": "ing_apples", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_brussels_sprouts", "quantity": {"value": 300.0, "unit": "unit"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.09, "unit": "bottle of 500ml"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["2 oz / 50g hazel nuts","180 g / 6oz bacon, chopped","1 red apple","1 tbsp lemon juice","300 g / 10 oz brussels sprouts"],"purpose":"Salad"},{"ingredients":["4 tbsp olive oil","3 tbsp apple cider vinegar","2 tsp Dijon mustard","Salt and pepper"],"purpose":"Dressing"}]', '[{"description":"Preheat oven to 180C/350F. Toast hazelnuts for 5 minutes or until golden brown. Cool then roughly chop. Set aside.","duration":5,"images":[],"step":1},{"description":"Either place the bacon on the baking tray used for the hazelnuts and bake until golden, or cook in a skillet. Drain on paper towels.","images":[],"step":2},{"description":"Cut apple into matchsticks, keeping the skin on. Toss in lemon juice.","images":[],"step":3},{"description":"Shave brussels sprouts finely using a slicer or food processor.","images":[],"step":4},{"description":"Place Dressing ingredients in a jar and shake well. Adjust salt and pepper to taste.","images":[],"step":5},{"description":"Place Salad ingredients in a bowl, toss with Dressing. Set aside for 5 minutes before serving (to soften the brussels sprouts slightly).","duration":5,"images":[],"step":6}]', '["mustard"]', '["gluten_free","low_calorie"]', '{"mealType":["lunch"],"cuisine":[],"categories":["brussels-sprouts","easter-brunch-recipes","easter-sides-fresh-light","quick-and-easy","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5a9b826ec5de', 'en', 'US', 'Crispy Prawn Burgers (Shrimp)', 'Recipe video above.', 'https://www.recipetineats.com/tachyon/2025/09/Prawn-burgers_5.jpg', 16, 4, 20, 4, '[{"id": "ing_shrimp", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 0.75, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_lettuce", "quantity": {"value": 4.5, "unit": "head"}}, {"id": "ing_gherkins", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_bang_bang_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}]', '[{"ingredients":["400g / 14oz fresh OR 500g/1lb frozen raw peeled prawns (shrimp) (Note 1)","1 garlic (, minced)","1/4 cup green onion (, finely sliced)","1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper"],"purpose":"Prawn patties"},{"ingredients":["1 egg (, lightly whisked with a fork)","1/2 cup plain flour (all-purpose flour)","1 1/4 cups panko breadcrumbs","1/2 cup olive oil (, or any neutral flavoured oil (vegetable, canola etc))"],"purpose":"Crumbing:"},{"ingredients":["4 brioche buns (10-12cm / 4-5\" wide) (or other soft white buns, lightly toasted)","1 1/2 cups shredded iceberg lettuce (or cos lettuce (romaine))","Gherkins (, finely sliced)","1 1/2 cups shredded iceberg lettuce (or cos lettuce (romaine))"],"purpose":"Burgers:"}]', '[{"description":"Blitz half prawns and garlic, mix with rest of pattie ingredients. Roll into balls, dredge in flour, egg, then flatten into patty in panko, flip to coat. Fry 4 minutes until golden, assemble burgers.","images":[],"step":1},{"title":"Thaw","description":"If using frozen prawns, thaw thoroughly and discard excess water (you lose ~20% in weight in water), then chop into 8mm / 1/3\" pieces.","images":[],"step":2},{"title":"Blitz","description":"Put half the prawns and garlic in a jug large enough to fit the head of a stick blender. Blitz until it becomes a paste (no need to puree 100% perfectly).","images":[],"step":3},{"title":"Prawn patties mixture","description":"Scrape into a bowl. Mix in the chopped prawns green onion, salt and pepper. The mix will be sloppy, but don’t worry - it firms up as it cooks, and the shaping method handles the softness. :)","images":[],"step":4},{"title":"Dredging station","description":"Put the egg and flour in separate shallow bowls, and the panko on a plate (need squishing space).","images":[],"step":5},{"title":"Crumb","description":"Using slightly wet hands, roll mixture into 4 balls. Coat ball in flour, then egg (let the excess drip off), then press down into a patty in the panko. Make it a smidge larger than the size of your bun (it shrinks a wee bit). Flip using a spatula, press down to adhere panko and make sure to coat the sides. Remove with a spatula onto a plate, repeat with remaining balls.","images":[],"step":6},{"title":"Cook","description":"Heat the oil in a large non-stick pan over medium high heat. Cook patties for 2 minutes on each side until golden, then remove onto a paper towel lined tray.","duration":2,"images":[],"step":7},{"title":"Assemble burgers as follows","description":"smear base with sauce. Top with prawn patty, cover with gherkins, pile on lettuce. Smear lid with sauce, place on top, EAT! (Homemade fries on the side are the ultimate sidekick but were out of reach today, so I used frozen).","images":[],"step":8}]', '["egg","gluten","shellfish"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Australian","Western"],"categories":["burger-recipes","prawns-shrimp","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9e8e0af4ea41', 'en', 'US', 'Bang Bang Sauce', 'This creamy, sweet, tiny-bit-spicy pink sauce was popularised in America as the sauce for "Bang Bang Shrimp" - crispy fried prawns tossed din the sauce - but the world quickly discovered it''s just as good with burgers, wraps, tacos, fries and even as a salad dressing!This goes particularly well with the Prawn Burgers that I also published today (Shrimp Burgers).', 'https://www.recipetineats.com/tachyon/2025/09/Bang-Bang-Sauce_9.jpg', 3, 0, 3, 0, '[{"id": "ing_mayonnaise", "quantity": {"value": 0.188, "unit": "jar of 400g"}}, {"id": "ing_chilli", "quantity": {"value": 0.3, "unit": "pack of 100g"}}, {"id": "ing_sriracha", "quantity": {"value": 0.037, "unit": "bottle of 400ml"}}]', '[{"ingredients":["1/2 cup whole-egg mayonnaise (Note 1)","2 tbsp sweet chilli sauce (Note 2)","1 tbsp sriracha (, or other chilli sauce you want, adjust amount to control spiciness (Note 3))"]}]', '[{"description":"Mix ingredients together until smooth.","images":[],"step":1},{"description":"Use for smearing in burgers, wraps (Doner Kebabs!), sandwiches, as a dipping sauce for fries, wedges, chicken fingers, drizzle across salads and poke bowls. And soon, I will share my Bang Bang Shrimp recipe!","images":[],"step":2}]', '["egg"]', '["gluten_free","vegetarian"]', '{"mealType":["main_course"],"cuisine":["American"],"categories":["burger-recipes","sauces"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f7556716390e', 'en', 'US', 'Homemade Peri-naise', 'Peri-naise is the famous creamy pink sauce from Nando''s, the Portuguese chicken restaurant chain. They use it for burgers, in wraps, dipping fries and drizzling on rice and salad bowls. I''m sharing this recipe as the sauce for One Pot Nando''s Portuguese Chicken and Rice which I also published today, but I also use it for tacos, burritos and quesadillas - to name a few! Here''s the two ways I make it - one based on a homemade Peri Peri sauce (tastes a little "fresher"), and the other to make anytime using dried spices (more similar to store bought bottles).', 'https://www.recipetineats.com/tachyon/2025/09/Peri-naise_2.jpg', 5, 0, 5, 0, '[{"id": "ing_peri_peri_sauce", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.281, "unit": "jar of 400g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}]', '[{"ingredients":["3 tbsp Peri Peri Sauce","3/4 cup mayonnaise (, preferably whole egg (Note 1))"],"purpose":"PERI PERI SAUCE VERSION:"},{"ingredients":["3/4 cup mayonnaise (, preferably whole egg (Note 1))","1 tsp smoked paprika (sub regular paprika)","1/2 tsp garlic powder (sub fresh garlic, finely grated)","1/2 tsp onion powder","1/4 tsp cayenne pepper (adjust or remove for not spicy)","1/2 tsp white sugar","1 tbsp lemon juice (or apple cider vinegar)","1/4 tsp cooking salt / kosher salt"],"purpose":"DRY SPICE VERSION (quicker, make anytime)"}]', '[{"title":"Mix","description":"For both versions, mix ingredients in a bowl and refrigerate for at least 30 minutes before using to let the flavours meld, if you can.","images":[],"step":1},{"description":"Use for burgers and wraps, dipping (like fries, crunchy tenders, popcorn chicken), drizzling on salad and rice bowls, poke bowls etc. See list of suggested recipes in post!","images":[],"step":2},{"title":"Storage","description":"The Peri Peri Sauce version will keep 5 days in the fridge, the dry spices one will keep for at least a week. Not suitable for freezing.","images":[],"step":3}]', '["egg"]', '["gluten_free","keto_friendly","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Portuguese"],"categories":["burger-recipes","sauces"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cf4281819efc', 'en', 'US', 'Ultra Crunchy Fried Chicken Burger', 'Recipe video above. KFC, eat your heart out! Our Fried Chicken Burger is way crunchier than yours, the chicken is way juicier and it tastes way better! The trick is to mix a bit of marinade into the flour coating - this creates lumps that fries up into an awesome ultra crunchy crust. See my Fried Chicken recipe for ravings and musings about this method. (Thanks Kenji!)', 'https://www.recipetineats.com/tachyon/2023/09/Crispy-fried-chicken-burgers_5.jpg', 15, 15, 210, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 0.75, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_lettuce", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_herkins_dill_pickles", "quantity": {"value": 0.002, "unit": "kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.25, "unit": "jar of 400g"}}, {"id": "ing_garlic", "quantity": {"value": 1.25, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.094, "unit": "pack of 400g"}}, {"id": "ing_celery", "quantity": {"value": 0.025, "unit": "head"}}, {"id": "ing_paprika", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.016, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.006, "unit": "jar of 200g"}}, {"id": "ing_ginger", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.15, "unit": "jar of 50g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.75, "unit": "L"}}]', '[{"ingredients":["2 x 250g/8oz chicken breast (I use this)","4 boneless thigh fillets"],"purpose":"Chicken choices:"},{"ingredients":["3/4 cup buttermilk (Note 1 for sub)","1 1/2 tsp cooking / kosher salt","1 large egg"],"purpose":"Marinade:"},{"ingredients":["4 soft buns (, split and lightly toasted (mine are 10cm/4\"))","2 - 3 cups iceberg lettuce (, finely sliced (or other leafy greens of choice))","2 tomatoes (, sliced (optional, sometimes I do))","2 gherkins / dill pickles (, sliced on an angle)"],"purpose":"Burgers:"},{"ingredients":["2/3 cup mayonnaise (, preferably whole egg)","3/4 tsp garlic (, finely grated (1 clove))"],"purpose":"Garlic mayo:"},{"ingredients":["3/4 cup flour (, plain / all purpose)","1/4 cup corn flour / cornstarch"],"purpose":"Crunchy coating:"},{"ingredients":["1/4 tsp celery salt (or heaped 1/8 tsp celery seed)","1/2 tsp sweet paprika","1/8 tsp cayenne pepper (inc to 1/2 tsp for spicy ZINGER burger!)","1/2 tsp onion powder","1 tsp garlic powder","1/4 tsp mustard powder","1/4 tsp ginger powder","1/2 tsp dried thyme","1/2 tsp dried oregano","1/2 tsp cooking salt / kosher salt","1 1/2 tsp black pepper"],"purpose":"Fried chicken seasoning:"},{"ingredients":["3 cups vegetable oil (or canola or peanut) (2.5cm/1\" depth in cooking vessel)"],"purpose":"To fry:"}]', '[{"description":"Shortform recipe:","images":[],"step":1},{"description":"Pound chicken to 1cm / 0.4\" thickness, trim, marinade 3 - 24 hrs. Mix coating and seasoning, mix in 2 tbsp marinade. Coat chicken, fry at 180°C/350°F for 4 min (don''t touch for first 90 sec). Assemble!","duration":4,"images":[],"step":2},{"description":"Full instructions:","images":[],"step":3},{"title":"Chicken","description":"Cover the chicken with a freezer bag or plastic sheet and pound to 1cm / 0.4\" even thickness. Trim to just a touch larger than the size of your bun. Save off-cuts for another use (stir fry - or Dozer, in my case!).","images":[],"step":4},{"title":"Marinade","description":"Whisk Marinade ingredients in a bowl. Add chicken, toss. Marinate in the fridge for 3 hours minimum, to overnight (don''t go beyond 24 hrs).","images":[],"step":5},{"title":"Garlic mayo","description":"Mix in a small bowl and refrigerate until required.","images":[],"step":6},{"title":"Prepare crunchy coating","description":"Mix flour, cornflour and Seasoning ingredients in a bowl. Drizzle over 2 tablespoons of the marinade, then use fingers to mix through to form lumps - when this sticks to the chicken, it fries up into awesome crunchy bits!!","images":[],"step":7},{"description":"Heat oil in a large heavy based pot over medium high heat to 180°C/350°F (Note 2).","images":[],"step":8},{"title":"Coat chicken","description":"Pick up a piece of chicken and allow excess marinade to drip off. Press to coat in flour coating. Shake off excess, then fry for 2 minutes on each side until golden. DO NOT TOUCH for the first 90 seconds to allow the coating to adhere. I fry 2 at a time. Drain on paper towels, cook remaining chicken.","duration":2,"images":[],"step":9},{"title":"Assemble","description":"Smear garlic mayo on the top and bottom of the buns. Pile lettuce on the base, top with tomato if using. Then chicken, gherkins and put the lid on. Sink your teeth into it immediately and enjoy!","images":[],"step":10}]', '["egg","gluten","mustard","peanuts"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["burger-recipes","chicken","chicken-breast-recipes","chicken-recipes","deep-fried-recipes","iconic-dishes","mains"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e49547d80532', 'en', 'US', 'Special Burger Sauce', 'Recipe video above. A great homemade burger sauce is an easy win to elevate a big juicy hamburger from yum to holy crapola, this is so good!!! Dead easy and so much better than store bought. Slather on your favourite burger (here are all my Burger recipes) or try the Cheeseburger recipe pictured in post!Want a tomato one? Try this Tomato Chutney for Burgers.Makes just over 3/4 cup, enough for 4 - 5 burgers.', 'https://www.recipetineats.com/tachyon/2022/08/Special-Burger-Sauce_1.jpg', 5, 0, 5, 4, '[{"id": "ing_mayonnaise", "quantity": {"value": 0.281, "unit": "jar of 400g"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_gherkins", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_gherkin_juice", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_vinegar", "quantity": {"value": 0.003, "unit": "L"}}, {"id": "ing_paprika", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_garlic", "quantity": {"value": 0.833, "unit": "pack of 3 heads"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}]', '[{"ingredients":["3/4 cup whole egg mayonnaise (Note 1)","1 tbsp American yellow mustard (Note 2)","2 tbsp sweet gherkins finely chopped (Note 3)","2 tsp gherkin juice (from the pickle jar) (Note 4)","2 tsp white sugar","1/2 tsp white wine vinegar (Note 5)","1/2 tsp paprika","1/2 tsp garlic granules (or 1/4 tsp garlic powder)","1/2 tsp onion powder"]}]', '[{"description":"Combine all ingredients in a small bowl or jug and stir until smooth.","images":[],"step":1},{"title":"Use for burgers","description":"browse my Burger collection or try the latest and greatest Cheeseburger! I generously slather on the base bun as well as the lid (or drizzle the stack).","images":[],"step":2}]', '["egg","mustard"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["burger-recipes","sauces"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_65e03f8e66ad', 'en', 'US', 'Quick tomato chutney sauce for burgers', 'Recipe video above. We can do better than ketchup! This is essentially a tomato chutney but far less sweet and doesn''t include ginger, chilli or other spices you often find in chutney (which I didn''t want for a burger sauce). Use for your burger of choice and anything you''d ordinarily dollop/smear chutney on - see in post for extensive suggestion.Makes 1 1/2 cups, enough to generously slather onto 5 to 6 burgers (But I''m quite greedy).', 'https://www.recipetineats.com/tachyon/2022/08/Homemade-Burger-Sauce-Tomato_7.jpg', 5, 30, 35, 4, '[{"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.06, "unit": "bottle of 500ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.006, "unit": "jar of 200g"}}, {"id": "ing_celery", "quantity": {"value": 0.025, "unit": "head"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["800 g / 28 oz canned tomato (, crushed or diced)","1 tbsp Worcestershire sauce","2 tbsp apple cider vinegar","2 tbsp brown sugar","1 tsp garlic powder","1 tsp onion powder","1/4 tsp smoked paprika","1/4 tsp mustard powder","1/4 tsp celery salt","1/2 tsp cooking/kosher salt","1/4 tsp black pepper"]}]', '[{"description":"Mix all the ingredients in a medium saucepan.","images":[],"step":1},{"description":"Simmer Bring to a simmer over medium heat then lower heat to medium low so it''s simmering gently.","images":[],"step":2},{"description":"Cook for 25 minutes, stirring regularly, until it reduces down and is thick enough so you can draw a path across the base of the saucepan (see video or step photos).","duration":25,"images":[],"step":3},{"title":"Cool & slather","description":"Transfer into a bowl. For use on burgers, cool then slather. Browse my Burger collection for options! If using to dollop or dip for any number of the other suggested uses in the post, use warm or cooled!","images":[],"step":4}]', '["mustard"]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["burger-recipes","sauces"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e2cec46ff1a0', 'en', 'US', 'Homemade Filet-O-Fish Burger (BAKED!)', 'Recipe video above. Tastes remarkably similar to McDonald''s with the added bonus that it''s bigger, it''s healthier and you know exactly what goes in it! Toasting the breadcrumbs guarantees beautiful golden, truly crunchy fish fillets even though these are baked. Fry option - follow the dredge / crumbing / fry steps in this Schnitzel recipe.', 'https://www.recipetineats.com/tachyon/2018/08/Homemade-Filet-O-Fish_3.jpg', 15, 20, 35, 4, '[{"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_fish_fillets", "quantity": {"value": 400.0, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_cheese", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.037, "unit": "jar of 400g"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_flour", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_corn", "quantity": {"value": 0.037, "unit": "can of 400g"}}, {"id": "ing_parsley", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_capers", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 0.045, "unit": "net of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2 cups panko breadcrumbs (Note 1)","400 - 500 g / 0.8 - 1 lb white fish fillets (, flat / thin (I used Ling, Note 2))","4 soft buns (, brioche recommended (Note 3))","4 slices processed cheese (Note 4)","Oil spray (I use olive oil)"]},{"ingredients":["1 egg","1 tbsp mayonnaise","1 tbsp dijon mustard (or other mustard)","1 tbsp flour","1/2 tsp salt","Black pepper"],"purpose":"Dredge Batter (Note 5):"},{"ingredients":["1 cup / 220g mayonnaise","1 tbsp dill pickle / gherkin/ cornichon (, very finely chopped)","1 tsp fresh parsley (, chopped*)","1 tsp capers (, drained and finely chopped*)","1.5 tbsp lemon juice (, fresh (or cider vinegar))","1 tsp white sugar","1/4 tsp salt"],"purpose":"Tartare Sauce:"}]', '[{"description":"Mix ingredients in a bowl. Set aside for 10 minutes+.","duration":10,"images":[],"step":1},{"description":"Toast Breadcrumbs:","images":[],"step":2},{"description":"Preheat oven to 180C/350F.","images":[],"step":3},{"description":"Spread breadcrumbs on a tray. Spray with oil directly down, not from side.","images":[],"step":4},{"title":"Bake for 3","description":"5 minutes until golden. Immediately transfer to bowl.","duration":4,"images":[],"step":5},{"description":"Brush tray clean, spray with oil.","images":[],"step":6},{"description":"Crumbing / baking:","images":[],"step":7},{"description":"Cut fish fillets into square-ish shapes slightly larger than the buns (they shrink when cooked).","images":[],"step":8},{"description":"Mix Batter ingredients in a bowl.","images":[],"step":9},{"description":"Carefully coat fish in batter (handle with care, fish fillets can be delicate).","images":[],"step":10},{"description":"Place in breadcrumbs. Use other hand to cover top and sides with breadcrumbs, pressing to adhere. Transfer to tray. Repeat with remaining fish.","images":[],"step":11},{"title":"Bake 12","description":"15 minutes until fish is cooked through. Immediately top with cheese - allow residual heat to make it semi melt (do not oven melt processed cheese, you get a plasticy film!).","images":[],"step":12},{"description":"Cut buns in half, microwave for 20 seconds to warm through (microwave = stays soft).","duration":0.3333333333333333,"images":[],"step":13},{"description":"Top with fish and cheese, dollop with tartare sauce. Devour!","images":[],"step":14}]', '["egg","fish","gluten","milk","mustard"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["burger-recipes","dinner-tonight","fish-recipes","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c25cefd99053', 'en', 'US', 'Veggie Burgers', 'Recipe video above. A Veggie Burger created by a carnivore, for carnivores. It is not a vegetarian burger pretending to be a meat burger, packed with obscure ingredients. This is just a flavour packed, juicy vegetarian burger that''s satisfyingly meaty! Chilling time: 1 hour', 'https://www.recipetineats.com/tachyon/2018/04/Veggie-Burgers_9a.jpg', 20, 35, 30, 4, '[{"id": "ing_mushroom", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_cannellini_beans_drained", "quantity": {"value": 400.0, "unit": "pack"}}, {"id": "ing_carrot", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_cashews", "quantity": {"value": 75.0, "unit": "jar"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.075, "unit": "jar of 400g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_rice", "quantity": {"value": 112.5, "unit": "pack"}}, {"id": "ing_green_onion", "quantity": {"value": 2.25, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_french_fries", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}]', '[{"ingredients":["250g/8oz mushrooms, sliced","2 tsp olive oil","400g / 14 oz can cannellini beans, drained (Note 1)","1 large carrot , grated"],"purpose":"Beans and Veggies:"},{"ingredients":["1/2 cup (70g) cashews, raw unsalted (Note 2)","1/2 cup (55g) panko breadcrumbs (Note 3)","1/2 cup (50g) grated parmesan","1 egg","2 tbsp mayonnaise","1 garlic clove (, minced)","1/2 tsp each paprika, salt and pepper","3/4 cup (150g) cooked brown rice (Note 4)","3/4 cup green onions (, sliced)"],"purpose":"Patties:"},{"ingredients":["2 - 3 tbsp olive oil (or other)","Soft buns, lettuce, tomato, cheese, pickles, sauces, avocado, beetroot"],"purpose":"Burger:"},{"ingredients":["French fries","Baked potato wedges"],"purpose":"On the side"}]', '[{"description":"Beans and Veggies:","images":[],"step":1},{"description":"Preheat oven to 180C/350F (standard) or 160C/320F (fan/convection).","images":[],"step":2},{"description":"Pile mushrooms on a baking tray. Drizzle over oil, toss, then spread on the tray.","images":[],"step":3},{"description":"Spread beans on another tray, sprinkle carrots all over.","images":[],"step":4},{"description":"Put beans on top shelf and mushrooms on the shelf underneath.","images":[],"step":5},{"description":"Bake for 15 minutes or until surface of beans is dried out and splitting and they look thoroughly unappetising, and the carrots around the edge of the tray are a bit golden. (Note 5) Remove tray with beans from oven.","duration":15,"images":[],"step":6},{"description":"Move mushrooms to top shelf, bake for further 10 minutes until dried out and wrinkly. Remove from oven, cool.","images":[],"step":7},{"description":"Patties:","images":[],"step":8},{"description":"Place cashews in food processor. Blitz until they are breadcrumb size, don''t blitz to powder.","images":[],"step":9},{"description":"Add beans, mushrooms and carrot. Blitz on high for 10 seconds or until chopped to large crumb size (see video and photos).","duration":0.16666666666666666,"images":[],"step":10},{"description":"Add breadcrumbs, egg, parmesan, garlic, paprika, mayonnaise, salt and pepper. Blitz for 15 - 30 seconds until it comes together like meat burger mixture but you can still see bits in it. (Note 6)","duration":0.375,"images":[],"step":11},{"description":"Add rice and shallots, blitz for 2 seconds until just dispersed (over blitzed rice = gluey).","duration":0.03333333333333333,"images":[],"step":12},{"description":"Mixture should hold together well to form patties, but not stick to hands. If too wet, add breadcrumbs. If too crumbly, blitz more.","images":[],"step":13},{"title":"Shape into 4","description":"6 patties, between 1.5 - 1.8cm / 0.6 - 0.7\" thick and 10cm / 4\" wide (Note 7). Refrigerate for at least 1 hour.","images":[],"step":14},{"title":"To Cook","description":"Stove:","images":[],"step":15},{"description":"Cook burgers cold, straight from the fridge.","images":[],"step":16},{"title":"Heat 2","description":"3 tbsp olive oil skillet on the stove over medium to medium-high heat.","images":[],"step":17},{"title":"Add 3","description":"4 patties and cook until deep golden and crispy, 4 minutes. Carefully flip then cook the other side for 4 minutes until golden, then transfer to paper towel lined plate to drain.","duration":4,"images":[],"step":18},{"description":"Cook cold, straight from fridge. Brush BBQ and Veggie patties with oil. Heat BBQ to medium high. Cook 4 minutes each side until a nice dark crust forms.","images":[],"step":19},{"description":"Toast buns, spread top bun with relish or sauce of choice. Top with your choice of burger fillings and the Veggie Burger, then more sauce if desired.","images":[],"step":20}]', '["egg","milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["burger-recipes","quick-and-easy","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6a8b941d5933', 'en', 'US', 'Guacamole', 'Recipe video above. A really great Guacamole, the way it''s made in Mexico and in the best Mexican restaurants around the world! The secret step that makes this so special is making a paste with onion, chilli, coriander/cilantro and salt before adding the avocado. Mashing is key to release flavour. And nobody wants raw onion chunks in their guac!', 'https://www.recipetineats.com/tachyon/2016/12/Guacamole_6.jpg', 10, 0, 10, 5, '[{"id": "ing_onion", "quantity": {"value": 30.0, "unit": "pack of 1kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_avocado", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_lime", "quantity": {"value": 4.0, "unit": "net of 500g"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2 tbsp finely chopped white onion (or red, brown or yellow)","1 tbsp finely chopped jalapeno or serrano chilli (or other chilli of choice) (adjust to taste)","1/2 tsp salt (, plus more to taste)","1/4 cup roughly chopped coriander/cilantro leaves","2 medium avocados (or 1 very large one) (Note 1)","Lime juice (, to taste (I use 1/4 - 1/2 lime))","Optional: 1 ripe tomato (, peeled, deseeded and chopped)"]}]', '[{"description":"Place the onion, jalapeño, salt and half the coriander on a cutting board and use a fork to mash until juicy. OR do this in a mortar and pestle - grind into a paste.","images":[],"step":1},{"description":"Scrape into a bowl, add avocado and remaining coriander, and mash to desired consistency.","images":[],"step":2},{"title":"Do a taste test then adjust to your taste","description":"salt, lime juice for sour, more chilli for spiciness.","images":[],"step":3},{"description":"If using tomatoes, stir through.","images":[],"step":4},{"description":"Serve with corn chips!","images":[],"step":5}]', '[]', '["gluten_free","keto_friendly","low_calorie","vegan","vegetarian"]', '{"mealType":["snack"],"cuisine":["Mexican"],"categories":["burritos","dietary","dip-recipes","fajitas","gluten-free-recipes","mexican-recipes","nachos-recipes","quick-and-easy","super-bowl-party-food","taco-recipes","vegan-lifestyle"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_19f53b412df9', 'en', 'US', 'Chicken Burrito', 'Recipe video above. This is a chicken burrito stuffed with a juicy seasoned chicken filling, refried beans, corn, cheese and Mexican Red Rice. The refried beans makes it juicy inside without being soggy, adds flavour and holds it all together so the filling doesn''t come tumbling out when you pick it up!', 'https://www.recipetineats.com/tachyon/2020/02/Chicken-Burritos_2.jpg', 15, 15, 30, 5, '[{"id": "ing_tortillas", "quantity": {"value": 5.0, "unit": "pack of 8"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 5.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_refried_beans", "quantity": {"value": 400.0, "unit": "pack"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_white_rice", "quantity": {"value": 0.375, "unit": "kg"}}, {"id": "ing_rice", "quantity": {"value": 375.0, "unit": "pack"}}, {"id": "ing_corn", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_salsa", "quantity": {"value": 1.0, "unit": "bottle"}}]', '[{"ingredients":["5 tortillas (, flour (approx 20cm/8\" wide))"]},{"ingredients":["1 tsp each onion powder, dried oregano, salt","2 tsp each dried cumin powder, paprika","1/4 tsp black pepper","3/4 tsp cayenne pepper (optional, adjust to taste)"],"purpose":"Burrito Seasoning:"},{"ingredients":["600g / 1.2 lb chicken breast (, sliced in half horizontally (Note 1))","2 tbsp olive oil (, separated)","1/2 onion (, chopped)","2 garlic cloves (, finely minced)","1 red capsicum/bell pepper (, diced)","400g/14oz refried beans (, canned (Note 2))","1/4 cup water"],"purpose":"Chicken Filling:"},{"ingredients":["2.5 cups white rice (, plain (cooked, Note 3))","2.5 cups Mexican Red Rice (the best for Burritos!)"],"purpose":"Rice – CHOOSE one:"},{"ingredients":["400g/14oz canned corn (, drained (or 280g/9oz frozen thawed))","1.5 cups (150g) cheese (, shredded (Mexican blend, cheddar, tasty, Montery Jack))","1/4 cup coriander/cilantro (, finely chopped)"],"purpose":"Other Stuffings:"},{"ingredients":["Avocado sauce","Sour cream","Salsa (restaurant style, smooth)"],"purpose":"Sauce for dunking – choose:"}]', '[{"title":"Burrito Seasoning","description":"Mix Seasoning ingredients. Drizzle 1 tbsp oil over chicken, mix to coat. Sprinkle with Seasoning, toss to coat.","images":[],"step":1},{"title":"Cook chicken","description":"Heat 1 tbsp oil in a large skillet over high heat. Add chicken, cook 2 minutes. Turn and cook 1.5 minutes. Remove, rest 2 minutes then chop.","images":[],"step":2},{"title":"Saute onion","description":"In the same skillet, add onion and garlic, cook 1 minute. Add capsicum, cook 2 minutes until onion is translucent.","images":[],"step":3},{"title":"Finish Filling","description":"Add refried beans, diced chicken and water. Stir and cook for 2 minutes until reduces slightly. Should be thick and juicy, not watery and not dry/stodgy! Let cool 5 minutes - will thicken.","duration":2,"images":[],"step":4},{"description":"Assemble burritos:","images":[],"step":5},{"description":"Gently warm tortillas in microwave (makes them pliable), lay on work surface.","images":[],"step":6},{"description":"Place rice on lower third, top with Chicken Filling, corn, cheese then sprinkle with coriander. Fold up, burrito style.","images":[],"step":7},{"title":"Toasting","description":"Either pan fry over medium high heat (no oil) for 2 minutes each side to make tortilla crispy and melt cheese a bit OR wrap tightly in foil and bake in oven 10 minutes at 180°C/350°F.","duration":2,"images":[],"step":8},{"description":"Dunk in sauce(s) of choice or douse with hot sauce of choice, and devour! Suggestions: Avocado Sauce, Guacamole, sour cream, Restaurant Style Salsa, Queso, Nacho Cheese Dip.","images":[],"step":9},{"description":"Freezer friendly! Note 4 for directions.","images":[],"step":10}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Mexican","Tex-Mex"],"categories":["burritos","chicken-breast-recipes","chicken-recipes","main-dishes","mexican-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9aa9803e6399', 'en', 'US', 'Avocado Sauce', 'Recipe video above. A terrific bright sauce with natural richness from avocado! Use for dipping and dolloping for all things Mexican - quesadillas, nachos, tacos, burritos - or for chips, crackers, vegetable sticks.', 'https://www.recipetineats.com/tachyon/2018/06/Quesadillas_9-1.jpg', 5, 0, 5, 4, '[{"id": "ing_large", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.2, "unit": "tub of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.5, "unit": "pack of 3 heads"}}, {"id": "ing_lemon", "quantity": {"value": 4.0, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1 large (, ripe avocado)","1/3 cup sour cream or yoghurt","1/2 small clove of garlic","Juice of 1/2 lemon OR 1 lime","1 - 2 tbsp olive oil","1/2 cup (packed) coriander / cilantro, roughly chopped","Salt and pepper to taste"]}]', '[{"description":"Combine all ingredients in a food processor, blend until very smooth. (Or use a stick blender). Use water to adjust consistency as required.","images":[],"step":1},{"description":"Adjust lemon or lime as required, and add salt to taste (bearing in mind saltiness of the food you are serving it with). Should have a bit of tang if intended to be paired with rich, bold flavoured food like Mexican food.","images":[],"step":2},{"title":"Keeps for 4 days in an airtight container","description":"and stays green!","images":[],"step":3}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Mexican"],"categories":["burritos","dip-recipes","fajitas","mexican-recipes","quick-and-easy","sauces","taco-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d05947bd9985', 'en', 'US', 'Mexican Red Rice', 'Fluffy, beautifully seasoned Mexican Red Rice (Arroz Rojo). With a whisper of coriander / cilantro flavour, this is tasty enough to eat plain. The key to fluffy rice is the right water to rice ratio, and don''t use too much tomato paste otherwise the liquid gets too thick = gluggy rice. Makes just over 3 cups, once fluffed. Scale up recipe by using slider on Servings. See AUTHENTICITY note below. Recipe VIDEO below.', 'https://www.recipetineats.com/tachyon/2017/10/Mexican-Red-Rice_-2.jpg', 3, 15, 18, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_white_rice", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.263, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 1.0, "unit": "jar of 50g"}}, {"id": "ing_coriander", "quantity": {"value": 0.04, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.04, "unit": "bunch"}}]', '[{"ingredients":["1 1/2 tbsp olive oil","2 garlic cloves (, minced)","1/2 small white onion (, finely chopped)","1 cup long grain white rice (, uncooked (Note 1))","1 3/4 cups (435 ml) chicken or vegetable broth (Note 2)","2 1/2 tbsp tomato paste","1/4 tsp salt","1 serrano or jalapeno pepper (, whole (optional))","1 sprig coriander / cilantro"]},{"ingredients":["Finely chopped coriander / cilantro leaves"],"purpose":"Optional garnish:"}]', '[{"description":"Heat oil in a large saucepan over medium heat. Add garlic, stir briefly, then add onion. Cook for 4 - 5 minutes until translucent (not browned / golden).","duration":4.5,"images":[],"step":1},{"description":"Add rice, broth, salt and tomato paste. Stir until tomato paste is dissolved.","images":[],"step":2},{"description":"Plonk in jalapeno and coriander. Cover, bring to simmer, then lower heat to low so the water is simmering gently.","images":[],"step":3},{"description":"Cook for 15 minutes or until the liquid is absorbed (tilt pot to check).","duration":15,"images":[],"step":4},{"description":"Remove from heat, leave lid on and rest for 10 minutes (KEY STEP). The residual liquid on the surface of the rice will get absorbed and rice will go from sticky to fluffy.","duration":10,"images":[],"step":5},{"title":"Fluff with fork then serve! (Optional","description":"garnish with extra coriander)","images":[],"step":6}]', '[]', '["gluten_free","low_calorie"]', '{"mealType":["main_course"],"cuisine":[],"categories":["burritos","dietary","easter-sides-warm-hearty","gluten-free-recipes","mexican-recipes","quick-and-easy","rice-recipes","rice-side-dishes","side-dishes","taco-recipes","vegan-lifestyle"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_41d3ea253391', 'en', 'US', 'Pico de Gallo (Authentic)', 'This is an authentic recipe for Pico de Gallo from "Truly Mexican", a fabulous cookbook filled with authentic Mexican recipes. Use this recipe as a base and adjust to your taste - more or less spiciness, and even add olive oil if you want! This makes enough for 8 tacos (as a topping).', 'https://www.recipetineats.com/tachyon/2016/04/Pico-de-Gallo-Mexican-Tomato-Salsa_1.jpg', 5, 0, 5, 2, '[{"id": "ing_tomato", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_onion", "quantity": {"value": 37.5, "unit": "pack of 1kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.225, "unit": "pack of 100g"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_chilli_flakes", "quantity": {"value": 0.062, "unit": "jar of 40g"}}]', '[{"ingredients":["3 large tomatoes","1/3 cup cilantro/coriander leaves (, roughly chopped)","1/4 cup finely chopped white onion (Note 1)","1 1/2 tbsp finely chopped jalapeño or serrano chilli (adjust to taste)","1 - 2 tbsp lime juice (adjust to taste)","1/2 tsp salt ((table salt) or 3/4 tsp kosher / sea salt flakes)"]}]', '[{"description":"Cut the tomatoes in half and use a teaspoon to scoop out the seeds and watery centre. Cut into 1cm / 1/3\" dice.","images":[],"step":1},{"description":"Combine with remaining ingredients. Set aside for 5 to 20 minutes. Serve as a topping or side for things like tacos, burritos, enchiladas, quesadillas and any Mexican dish!","duration":12.5,"images":[],"step":2},{"description":"This can be made ahead up to 1 day. Leave out the lime juice and salt (otherwise the tomato juices will leech out), cover and refrigerate. Drain excess liquid, add lime juice and salt just before serving.","images":[],"step":3}]', '[]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Mexican"],"categories":["burritos","dietary","dip-recipes","fajitas","gluten-free-recipes","mexican-recipes","nachos-recipes","quick-and-easy","side-dishes","side-salads","taco-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2317689a85d3', 'en', 'US', 'Taco Slaw', 'A slaw designed for use in tacos. A limey sour cream dressing that does so well with Mexican flavours, bit of crunch from the cabbage with signature slaw “juiciness” which acts like a sauce so you don''t need to bother with a salsa or taco sauce.Ideal for things like Crunchy Chicken Taco Fingers, Fish Tacos, Chipotle Prawn Tacos, Baja Fish Tacos, Grilled Chicken for Tacos (ie pieces of protein) rather than things that are shredded and saucy (too same-same). You can also serve it as a side salad, like regular slaw!', 'https://www.recipetineats.com/tachyon/2025/01/Taco-slaw_8.jpg', 15, 0, 15, 12, '[{"id": "ing_cabbage", "quantity": {"value": 6.0, "unit": "head"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.3, "unit": "tub of 250g"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.075, "unit": "jar of 400g"}}, {"id": "ing_lime", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_lime", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}]', '[{"ingredients":["6 tightly packed cups green cabbage (, finely shredded (about 1/4 head))","1 cup green onion (, finely sliced on the diagonal)","1/2 cup finely chopped coriander/cilantro leaves"]},{"ingredients":["1/2 cup sour cream (sub plain yogurt)","2 tbsp mayonnaise (OR 1 tbsp olive oil (ie halve amount))","2 tsp lime zest","1 tbsp lime juice","1/2 tsp cooking salt / kosher salt (halve for table salt)"],"purpose":"Taco Slaw Dressing:"}]', '[{"description":"Mix the dressing ingredients in a large bowl.","images":[],"step":1},{"title":"Toss","description":"Add the Slaw ingredients then toss well with hands or tongs.","images":[],"step":2},{"description":"Set aside for at least 1 hour until the cabbage becomes wilted and floppy. Toss again then use in tacos!","images":[],"step":3}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["cabbage","mexican-recipes","side-salads","taco-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_06e2b7ccc367', 'en', 'US', 'Jamaican Slaw', 'Recipe video above. A refreshingly tangy side salad with unmistakable tropical vibes thanks to the vibrant yellow dressing and juicy little pops of pineapple. The perfect accompaniment to bold flavoured Jamaican mains like Jerk Fish and Jerk Chicken!', 'https://www.recipetineats.com/tachyon/2023/01/Jamaican-Slaw_0.jpg', 15, 0, 15, 5, '[{"id": "ing_cabbage", "quantity": {"value": 4.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 300.0, "unit": "pack of 1kg"}}, {"id": "ing_pineapple", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_raisins", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_mustard", "quantity": {"value": 0.225, "unit": "jar of 200g"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.167, "unit": "bottle of 500ml"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_jalape_o", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_green_onion", "quantity": {"value": 0.75, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["4 heaped cups green cabbage (, finely shredded)","2 cups shredded carrot (2 - 3 carrots)","1 1/2 cups diced pineapple (, 1cm / 1/2\" cubes (fresh or canned in juice) (Note 1))","3/4 cup raisins (or sultanas)"],"purpose":"Jamaican Slaw:"},{"ingredients":["3 tbsp yellow mustard (, American or other (Note 2))","1/3 cup apple cider vinegar","1/3 cup extra virgin olive oil","1 tbsp jalapeño (, deseeded, finely minced)","1/4 cup green onion (, finely chopped (Note 3))","1/2 tsp cooking/kosher salt","1/4 tsp black pepper"],"purpose":"Jamaican Slaw Dressing:"}]', '[{"title":"Dressing","description":"Shake ingredients in a jar until combined.","images":[],"step":1},{"title":"Wilt","description":"Place all the Slaw ingredients in a large bowl. Pour over Dressing and toss. Leave to wilt for at least 1 hour.","images":[],"step":2},{"title":"Serve","description":"Toss well to coat in the juices & dressing pooled at the bottom of the bowl. Transfer to bowl and serve!","images":[],"step":3}]', '["mustard"]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Caribbean","Hawaiian","Jamaican","Tropical!"],"categories":["cabbage","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c9d3a1ab5d8c', 'en', 'US', 'White Christmas Rocky Road', 'Recipe video above. This is my festive white chocolate rocky road, with add-ins chosen for Christmassy colours as well as flavour combination (glacé cherries and coconut is a win!). I like to top it with extra cherries and pistachios to give it an extra special touch. I don''t do that for regular rocky road. Because, you know. Christmas is special! ;)Feel free to switch the add-ins (dried fruits, biscuits, other nuts, raspberries, Turkish delight - see post for lots of other ideas). My rule of thumb is ~4 1/2 cups for every 500g/1 lb chocolate. And don’t skip the oil! Makes the chocolate meltier so it coats everything better, and it’s easier to cut. Gift or hoard for yourself. Go on! You deserve it! :)', 'https://www.recipetineats.com/tachyon/2025/12/White-Christmas-Rocky-Road_0.jpg', 15, 0, 15, 20, '[{"id": "ing_chocolate", "quantity": {"value": 500.0, "unit": "block of 100g"}}, {"id": "ing_grapes", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_marshmallows_most_cut_in_half", "quantity": {"value": 2.5, "unit": "unit"}}, {"id": "ing_pistachios", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_cherries", "quantity": {"value": 0.3, "unit": "pack of 500g"}}, {"id": "ing_desiccated_coconut", "quantity": {"value": 0.075, "unit": "kg"}}]', '[{"ingredients":["500g/ 1 lb white chocolate melts/discs (I use this), chips or block chopped (Note 1)","2 tbsp grapeseed oil or other neutral flavoured oil (Note 2)"]},{"ingredients":["2 1/2 cups (tightly packed) marshmallows ((regular size), most cut in half)","1 cup pistachios (, unsalted ,toasted (Note 3))","1 cup glacé cherries","1/2 cup desiccated coconut (, unsweetened (or finely shredded, not flakes))"],"purpose":"Add-ins"}]', '[{"title":"Pan","description":"Lightly grease a 20cm/8\" square pan with butter then line with baking paper (parchment paper) with overhang (to make it easier to lift out later).","images":[],"step":1},{"title":"Reserve toppings","description":"Set aside 8 or so of the nicest glacé cherries. Finely chop 1 tablespoon of the pistachios.","images":[],"step":2},{"title":"Melt chocolate","description":"Place chocolate and oil in a heatproof bowl. Microwave in 30 second increments, stirring in between, until melted and smooth.","images":[],"step":3},{"title":"Add-ins","description":"Stir the Add-ins into the chocolate. Pour into pan, spreading out evenly - I also like to bang and shake the pan assertively (also very satisfying!).","images":[],"step":4},{"description":"Top with reserved glace cherries and sprinkle with chopped pistachios.","images":[],"step":5},{"description":"Refrigerate for 3 hours or until firm. Lift out of the pan using the paper overhang, then cut! I cut into 5 lines, then into chunks for eating or larger pieces for gifting!","images":[],"step":6}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["candy","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cc817bd10f56', 'en', 'US', 'Homemade Movie Popcorn (Stay-crisp Butter Popcorn)', 'Recipe video above. It''s buttery and yellow, just like the buckets you buy at the movie theatre Candy Bar! The yellow colour is optional, the butter is not. Bonus: The popcorn stays crisp for several days, thanks to the clarified butter (aka ghee). If you skip making the Popcorn Butter, see notes for recipe amendments.', 'https://www.recipetineats.com/tachyon/2018/08/Movie-Popcorn_1.jpg', 5, 15, 20, 8, '[{"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_corn", "quantity": {"value": 0.113, "unit": "can of 400g"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_water", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_saffron_powder", "quantity": {"value": 1.25, "unit": "jar"}}, {"id": "ing_turmeric", "quantity": {"value": 0.003, "unit": "jar"}}]', '[{"ingredients":["3 tbsp Popcorn Butter or ghee (Note 1)","3/4 cup popcorn kernels","2 - 3 tbsp Extra Popcorn Butter or ghee (Note 1)","1 tsp Popcorn Salt"],"purpose":"Movie Popcorn:"},{"ingredients":["1 tbsp salt"],"purpose":"Popcorn Salt:"},{"ingredients":["250 g / 2 sticks unsalted butter"],"purpose":"Popcorn Butter (clarified butter / ghee):"},{"ingredients":["1 1/2 tsp warm tap water","1/4 tsp saffron powder (, imitation (Note 2))","1/8 tsp tumeric powder"],"purpose":"Yellow Colouring (optional):"}]', '[{"description":"Place 3 tbsp Popcorn Butter in a large 10L/10qt lightweight pot over medium heat (medium high if weak stove).","images":[],"step":1},{"description":"When the butter is almost melted, pour in Yellow Colouring, if using. Quickly give the pan a shake to disperse the colouring across the base.","images":[],"step":2},{"description":"Add kernels, shake quickly to spread across the base, then clamp lid on. The kernels will start popping after a minute or so.","images":[],"step":3},{"description":"Shake briefly once after 30 seconds or so. When the popping stops, immediately pour popcorn into a large bowl.","images":[],"step":4},{"description":"Melt Extra Popcorn Butter in microwave. Pour over popcorn, sprinkle over salt. Shake and toss well to disperse. Extra fantastic served warm but still irresistible at room temp.","images":[],"step":5},{"description":"Place in a mortar and pestle and grind into a fine powder. OR use about 1/2 cup salt and blitz in food processor.","images":[],"step":6},{"description":"Popcorn Butter (video helpful):","images":[],"step":7},{"description":"Place butter in a silver saucepan over medium low to medium heat.","images":[],"step":8},{"description":"Leave to melt, it will start to sputter and spit, then foam.","images":[],"step":9},{"description":"When you push the foam aside and you see brown bits on the bottom of the saucepan, remove from heat. Takes about 10 minutes.","images":[],"step":10},{"description":"Line a strainer with 2 paper towels, then strain butter through - discard brown bits.","images":[],"step":11},{"description":"Pour strained butter into a jar or container. It sets when it cools. Use in liquid or set form. Keeps in the pantry for months (it is now ghee / clarified butter).","images":[],"step":12},{"description":"Yellow Colouring (optional):","images":[],"step":13},{"description":"Mix ingredients in a small bowl until spices dissolve.","images":[],"step":14}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["snack"],"cuisine":["Western"],"categories":["candy","dietary","gluten-free-recipes","quick-and-easy","snacks","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a01c125896f4', 'en', 'US', 'Tuna sandwich', 'Recipe video above. Here''s my version of the classic tuna sandwich. Tuna in oil, not water. Juice from the pickle jar adds much desired tang (oh, I use the pickles too!). Dijon for flavour, dill for lovely herbiness, celery for crunch and green onion for freshness. Spread onto your favourite bread and enjoy!Makes enough for 4 sandwich-bread sandwiches, or 6 medium bread rolls.', 'https://www.recipetineats.com/tachyon/2023/08/Tuna-sandwich_2.jpg', 10, 0, 10, 4, '[{"id": "ing_oil", "quantity": {"value": 425.0, "unit": "bottle"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.281, "unit": "jar of 400g"}}, {"id": "ing_celery", "quantity": {"value": 2.25, "unit": "head"}}, {"id": "ing_dill_pickle", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_liquid_from_pickle_jar", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_mustard", "quantity": {"value": 0.15, "unit": "jar of 200g"}}, {"id": "ing_dill", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_lettuce", "quantity": {"value": 2.4, "unit": "head"}}, {"id": "ing_butter", "quantity": {"value": 8.0, "unit": "block of 250g"}}, {"id": "ing_bread", "quantity": {"value": 0.4, "unit": "loaf"}}]', '[{"ingredients":["425g/ 15 oz canned tuna in oil (, drained (Note 1))","3/4 cup whole egg mayonnaise or Kewpie (Note 2)","3/4 cup finely diced celery (1 stalk, cut in 4 lengthways, then finely diced)","5 tbsp finely chopped dill pickle (Note 3)","2 tbsp liquid from pickle jar (Note 3)","2 tbsp Dijon mustard","3 tbsp finely chopped dill (or parsley or basil)","1/3 cup finely sliced green onion (, ~2 stems (Note 4))","1/2 tsp black pepper"],"purpose":"Tuna sandwich filling:"},{"ingredients":["8 pieces butter lettuce (2 per sandwich)","Salted butter (, for spreading)","8 slices bread or 4 rolls (Note 5)"],"purpose":"For sandwiches:"}]', '[{"title":"Filling","description":"Put all the Tuna Filling ingredients in a bowl. Mix well using a wooden spoon, breaking up the tuna so the filling becomes fairly smooth. The pickles and celery will take a beating too which is encouraged -> flavour melding!","images":[],"step":1},{"title":"Sandwich","description":"Divide Tuna Filling between 4 sandwiches (or more/less depending on bread size). I butter the bread and use 2 pieces of lettuce per sandwich. Enjoy!","images":[],"step":2}]', '["egg","fish","gluten","milk","mustard"]', '["high_protein"]', '{"mealType":["lunch"],"cuisine":["Western"],"categories":["canned-tuna","no-cook-food","quick-and-easy","sandwiches-and-sliders"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_17c12ccf2907', 'en', 'US', 'Crispy rice with spicy tuna (Nobu copycat)', 'Recipe video above. A shameless copycat of a signature Nobu restaurant appetiser - crispy rice cakes with tuna or salmon in a creamy spicy dressing. Easy to make at a fraction of the cost - they charge $30 for a minuscule serving! Serve as a canapé, starter for dinner or as a main with an Asian side salad or smashed cucumbers.The original uses raw tuna but I''ve also created a canned tuna version - think, sushi roll filling.', 'https://www.recipetineats.com/tachyon/2023/06/Crispy-rice-spicy-tuna_6.jpg', 30, 20, 50, 15, '[{"id": "ing_rice", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_one_topping_of_choice_nobu_sashimi_tuna_or_tuna", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_jalape_o", "quantity": {"value": 15.0, "unit": "unit"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_sashimi_grade_tuna", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_sriracha", "quantity": {"value": 0.037, "unit": "bottle of 400ml"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.05, "unit": "jar of 400g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_oil", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}]', '[{"ingredients":["1 batch crispy rice cakes (15 pieces)","ONE topping of choice (below) - Nobu sashimi tuna or canned tuna","1 avocado (, cut into small thin slices (or make avocado sauce))","15 jalapeño slices (, thin, optional garnish)","1/2 tsp black sesame seeds (, for garnish)"]},{"ingredients":["225g / 7oz sashimi grade tuna (, or salmon (Note 1))","1 tbsp sriracha (, adjust spiciness to taste (Note 2))","4 tsp kewpie mayonnaise (Note 3)","1 tsp sesame oil","1/4 tsp cooking salt","2 tbsp finely chopped green onion","1 tsp white sesame seeds","1 1/2 tsp black sesame seeds (, divided)"],"purpose":"Nobu spicy tuna (raw):"},{"ingredients":["360g/12oz canned tuna in oil (, drained (Note 4))","3 tbsp sriracha (Note 2)","4 tbsp kewpie mayonnaise (Note 3)","1 tbsp lemon juice (sub rice vinegar)","1 tsp sesame oil","1/2 tsp cooking/kosher salt","1/4 cup finely chopped green onion","2 tsp white sesame seeds (, optional)","1 1/2 tsp black sesame seeds (, divided)"],"purpose":"Creamy spicy canned tuna topping:"}]', '[{"description":"Start the rice the day before or first thing in the morning - it needs minimum 4 hours to chill.","images":[],"step":1},{"description":"Make the toppings first, then refrigerate while you cook the crispy rice cakes.","images":[],"step":2},{"description":"Cook the crispy rice cakes and sprinkle with salt per the recipe.","images":[],"step":3},{"title":"Assemble","description":"Place rice cakes on a serving platter. Pile on toppings - I use teaspoons to make football shapes then slide on. Sprinkle with black sesame seeds, top with jalapeño. Eat!","images":[],"step":4},{"description":"Nobu spicy tuna topping:","images":[],"step":5},{"title":"Freeze to firm","description":"Place tuna in the freezer for 30 minutes to partially freeze - it''s much easier to finely chop when slightly firm.","duration":30,"images":[],"step":6},{"title":"Cut into 0.5cm / 1/2\" cubes","description":"the smaller the better! Place into a bowl and let it de-chill for 20 minutes (not as nice ice-cold).","duration":20,"images":[],"step":7},{"title":"Mix","description":"Add everything into the tuna and mix until combined.","images":[],"step":8},{"description":"Creamy canned tuna (sushi-roll filling style):","images":[],"step":9},{"description":"Place tuna in a bowl and use a fork to mash it up really finely. Add everything else and mix well.","images":[],"step":10}]', '["fish","sesame"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["snack"],"cuisine":["Asian","Modern Asian"],"categories":["canned-tuna","finger-food","fish-recipes","modern-asian","seafood-recipes","snacks"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8a0a9eb1cc38', 'en', 'US', 'The most amazing canned tuna pasta!', 'Recipe video above. One of the pantry-pasta greats. I love this recipe because it really showcases what great food you can make using canned tuna! Fabulous flavour beyond just canned tuna thanks to the anchovies, the freshness of lemon and tangy capers. The oil from the can of tuna is used as the sauce so don''t be tempted to use tuna in brine!', 'https://www.recipetineats.com/tachyon/2023/04/Canned-tuna-pasta_0-copy.jpg', 10, 15, 25, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.4, "unit": "pack of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 285.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_fish_fillets", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_baby_capers", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["200g / 7oz spaghetti (, or other thin long pasta)","1 tbsp cooking salt (, for cooking pasta)"]},{"ingredients":["285g/ 10 oz (approx) canned tuna in oil (, drained, oil reserved (I use 3 x 95g/3.5oz cans, Note 1))","2 clove garlic (, finely minced)","2 anchovy fillets (, minced (Note 2))","1/2 tsp chilli flakes / red pepper flakes (can skip, Note 3)","2 tsp baby capers (or finely chopped pickles)","1 tbsp parsley (, finely chopped (ok to skip))","1 tsp lemon zest","2 tbsp lemon juice (sub 1 tbsp apple cider or sherry vinegar)","1/4 tsp cooking/kosher salt","1/4 tsp black pepper"],"purpose":"Tuna sauce:"}]', '[{"title":"Cook pasta","description":"Bring 3 litres / 3 quarts of water to the boil with the 1 tablespoon of salt. Cook pasta per the packet time minus 1 minute. Just before draining, scoop out ~1 cup pasta cooking water, then drain the pasta.","images":[],"step":1},{"title":"Sauté aromatics","description":"In the same pot, heat the reserved oil from the tuna cans over medium heat. Add the garlic, anchovies and chilli flakes. Cook and stir for 1 minute.","duration":1,"images":[],"step":2},{"title":"Toss pasta","description":"Add the pasta, capers and 1/3 cup of reserved pasta water. Toss using 2 spatulas for 2 minutes.","duration":2,"images":[],"step":3},{"title":"Add tuna","description":"Turn off the heat. Add tuna, parsley, lemon zest, juice, salt and pepper. Toss gently to mix through - try to keep some tuna chunks.","images":[],"step":4},{"description":"Serve immediately!","images":[],"step":5}]', '["fish","gluten"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["canned-tuna","dinner-tonight","emergency-recipes","fish-recipes","mains","other","pasta-recipes","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1bed0cbe1403', 'en', 'US', 'Tuna Mornay (Creamy Tuna Casserole Pasta Bake)', 'Recipe video above. Tuna Mornay is how you elevate canned tuna above a glum pantry staple into a delish family meal! It’s a tuna casserole pasta bake with a creamy sauce, sweet pops of corn and crunchy topping, baked until golden and bubbly. Simple to make, economical and oh-so-delish!', 'https://www.recipetineats.com/tachyon/2019/11/Tuna-Mornay_6.jpg', 10, 35, 45, 5, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.7, "unit": "pack of 500g"}}, {"id": "ing_butter", "quantity": {"value": 40.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_tuna", "quantity": {"value": 0.425, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_bread", "quantity": {"value": 0.094, "unit": "loaf"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["350g / 12oz penne pasta (or other short pasta)","40g / 3 tbsp butter","3 garlic cloves (, finely minced)","4 tbsp (50g) flour (, plain/all purpose)","4 cups (1 litre) milk (, any fat %, dairy or non dairy (1 quart))","2 tsp Vegeta, or chicken or veg stock powder/granulated bouillon (Note 1)","1/2 cup (50g) parmesan (, finely shredded)","1/2 tsp each mustard powder, onion and garlic powder (Note 2)","425g / 15 oz canned tuna (, preferably in oil, drained (sub salmon))","400g / 14 oz canned corn (, drained (or other veg, Note 3))"]},{"ingredients":["25g / 1.5 tbsp butter (, melted)","1/2 cup (60g) panko breadcrumbs","1/4g (25g) parmesan (, finely grated)","1/4 tsp salt","Chives or parsley (, optional garnish)"],"purpose":"Crunchy Topping:"}]', '[{"description":"Preheat oven to 180°C/350°F.","images":[],"step":1},{"title":"Crunchy Topping","description":"Mix together.","images":[],"step":2},{"description":"Cook pasta per packet directions MINUS 1 minute. Drain then allow to cool slightly, then return into pot.","images":[],"step":3},{"title":"White Sauce","description":"Melt butter in a large pot over medium heat. Add garlic and cook for 30 seconds.","duration":0.5,"images":[],"step":4},{"description":"Add flour and stir into melted butter. While whisking, gradually pour in about 1/3 of the milk. Once the flour-butter mixture is incorporated into the milk, pour in remaining milk and whisk.","images":[],"step":5},{"description":"Add Vegeta, mustard, onion and garlic powder, whisk.","images":[],"step":6},{"description":"When the milk starts to heat up, whisk constantly to make sure the white sauce doesn’t catch on the base.","images":[],"step":7},{"title":"After 4","description":"5 minutes, the sauce should be thick enough that you can draw a path across the back of a spoon (see video). Remove from stove and stir in parmesan.","images":[],"step":8},{"title":"Assemble & Bake","description":"Add tuna into pasta and flake into large chunks with fork (not too much, don''t want it to turn to mush when stirred). Add corn, pour over sauce, then gently stir.","images":[],"step":9},{"description":"Scrape into baking dish, top with Crunchy Topping.","images":[],"step":10},{"description":"Bake 25 minutes until top is golden and edges are bubbling. Sprinkle with chives if desired then serve!","images":[],"step":11}]', '["fish","gluten","milk","mustard"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["canned-tuna","casseroles-and-cosy-bakes","pasta-bakes","pasta-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_eabda0665deb', 'en', 'US', 'Tuna Pasta Bake', 'Recipe video above. When the cupboards are bare, and all you have is canned tuna, pasta and canned tomato, you can still make a wickedly delicious dinner! Customise to your hearts content - add vegetables, fresh herbs, chilli flakes, stir through cheese, olives, capers, sun dried tomatoes - get creative! See note 9 for a lower cal version, and Tuna Mornay for a CREAMY version!', 'https://www.recipetineats.com/tachyon/2017/06/Tuna-Pasta-Bake-2.jpg', 10, 30, 40, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_italian_mixed_herbs", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_can_chunk_tuna_drained", "quantity": {"value": 0.425, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.4, "unit": "pack of 500g"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.2, "unit": "pack of 125g"}}]', '[{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","1 small onion (, finely diced)","800g / 28 oz crushed tomato (Note 1)","1 tbsp tomato paste (optional, thickens sauce slightly)","3/4 cup (185ml) water (Note 2)","1 tbsp Italian mixed herbs (, or other dried herbs of choice)","1 tsp salt","1/2 tsp black pepper","425g / 15 oz can chunk tuna (preferably in oil), drained (Note 3)","200g / 7 oz spiral pasta (or other pasta of choice)","1 1/2 cups (150g) shredded mozzarella cheese (Note 4)","Olive Oil (, for drizzling)"]}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Cook pasta per packet directions, minus 1 minute. Drain, rinse under tap water to stop it sticking together, set aside.","images":[],"step":2},{"description":"Meanwhile, make the sauce. Heat an ovenproof skillet over medium high heat. Add garlic and onion, cook for 3 minutes until golden.","duration":3,"images":[],"step":3},{"description":"Add tomato, water, herbs, salt and pepper and tomato paste if using. Stir, bring to simmer, lower heat to medium and simmer energetically for 5 minutes (stir every now and then) until it thickens.","duration":5,"images":[],"step":4},{"description":"Adjust salt to taste. Also add a touch of sugar if it tastes a bit sour (depends on quality of tomato).","images":[],"step":5},{"description":"Turn the stove off, add pasta, stir in.","images":[],"step":6},{"title":"Add tuna and GENTLY stir it in","description":"don''t break up the tuna so it disintegrates into mush. Leave some chunks on the surface (nice when it is golden).","images":[],"step":7},{"description":"Drizzle with oil, top with cheese then bake for 20 minutes until golden and you get those nice crusty bits you see in the photos.","duration":20,"images":[],"step":8},{"description":"Stand for 3 minutes then serve!","duration":3,"images":[],"step":9}]', '["fish","gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Australia","Western"],"categories":["canned-tuna","casseroles-and-cosy-bakes","pasta-bakes","pasta-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4633d5dffedc', 'en', 'US', 'Chicken Mushroom Pie with Duchess Potato lid', 'Recipe video above. I want to rave about the rich, savoury filling but all anyone can talk about is the Duchess Potato topping.....😅 Fluffy and buttery inside with crispy parmesan crusted ridges, I want to pick them off one by one and eat them all by myself!As for the filling - think, rich Guinness Stew, but with chicken, and 2 hours faster to make. Guinness beer adds instant depth of flavour, and beef rather than chicken broth has a richer flavour and makes the sauce an enticing deep brown colour.Make one big pie as I''ve done, or single serve size. Excellent for making ahead to bake later! (See note 6 if you don''t have a piping bag for star tip)', 'https://www.recipetineats.com/tachyon/2025/07/Duchess-potato-chicken-pie_9.jpg', 20, 60, 80, 6, '[{"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 0.5, "unit": "pack of 200g"}}, {"id": "ing_onion", "quantity": {"value": 1.5, "unit": "pack of 1kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_beer", "quantity": {"value": 0.568, "unit": "bottle of 330ml"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_milk", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.15, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["60 g / (4 tbsp) unsalted butter (, approximately divided into 4 (no need to be accurate))","4 garlic cloves (, finely minced)","1 1/2 tsp cooking salt / kosher salt (, divided (Note 1))","1 tsp black pepper (, divided)"]},{"ingredients":["750 g / 1.5 lb chicken thighs (, boneless skinless (Note 2))","500 g/1 lb button mushrooms - very small ones whole (, larger ones halved or quartered)","100 g / 3.5 oz thick cut streaky bacon (, cut into 2.5cm/1\" squares)","1 1/2 onions (, cut into 2cm/1\" square or thick wedges)","2 sprigs fresh thyme (or 1/2 tsp dried thyme)","1/4 cup plain flour (all-purpose flour)","3/4 cup Guinness beer (Note 3)","1 1/2 cups beef stock / broth (, low sodium)","3/4 cup water","1 tbsp tomato paste"],"purpose":"Pie filling:"},{"ingredients":["1 kg / 2 lb starchy potatoes (, peeled, cut into 2.5cm / 1\" cubes (Note 4))","30g / 2 tbsp unsalted butter (, cut into 1.5 cm / 1/2\" pieces)","1/3 cup milk (, hot)","1/8 tsp white pepper (sub black)"],"purpose":"Mashed potato topping:"},{"ingredients":["30g / 2 tbsp unsalted butter (, melted (or olive oil spray))","2 tbsp grated parmesan (, sandy store bought type works best or grate your own)","2 tsp finely chopped parsley for garnish (, optional)"],"purpose":"Topping:"}]', '[{"description":"Brown mushrooms, remove, sear chicken (aggressively!) in same pan, cut into large pieces. Sauté bacon, onion and garlic, deglaze with Guinness, make roux, add stock, simmer with mushrooms to thicken (~10 min). Add chicken towards end. Pour into a baking dish, pipe on mashed potato, finish with butter and parmesan, bake 30 min.","images":[],"step":1},{"title":"Garlic butter mushrooms","description":"Melt 1/4 of the butter in a large 30cm/12\" non stick pan over high heat. Add mushrooms, toss for 3 - 4 minutes until you get some browning on the surface. Add another 1/4 of the butter, melt, toss to coat. Add 1/4 tsp each salt and pepper and half the garlic, toss 30 seconds until garlic is golden - mushrooms will still be hard inside, they finish cooking later. Remove into bowl (make sure you scrape out all garlic bits).","duration":3.5,"images":[],"step":2},{"title":"Sear chicken","description":"Sprinkle the chicken with 1/2 tsp salt and 1/4 tsp pepper. In the same pan, melt another 1/4 of the butter until hot and foamy. Sear chicken 2 minutes on each side until nicely golden but inside is still raw (if they don''t fit in a single layer, do in batches). Remove onto plate, once cool enough to handle cut into 2.5cm (1\") pieces.","images":[],"step":3},{"title":"Bacon and onion","description":"In the same pan, add bacon and stir for 15 seconds, then add the onion (there should be enough fat from the chicken). Cook for 2 minutes until the onion edges are golden and starting to soften. Add remaining garlic and stir 20 seconds.","duration":0.25,"images":[],"step":4},{"title":"Deglaze with Guinness","description":"Add Guinness and let it simmer rapidly, scraping the base of the pan to loosen any golden bits into the liquid (“fond” = free flavour!), until the Guinness is reduced down by 75%.","images":[],"step":5},{"title":"Sauce","description":"Lower heat to medium and add remaining butter. Once melted, sprinkle flour all across the surface and stir for 1 minute - it will look pasty. While stirring, pour in half the stock. Keep stirring until the flour paste dissolves into the stock, for lump-free sauce (yay!). Then add remaining stock, water, tomato paste, 1/4 tsp salt and 1/2 tsp pepper, stir well.","duration":1,"images":[],"step":6},{"title":"Simmer","description":"Add the mushrooms plus all mushroom juices accumulated in the bowl into the pan. Simmer for 10 minutes or until the liquid reduces down into a fairly thick gravy and the mushrooms become soft. (Meanwhile, start the mash)","duration":10,"images":[],"step":7},{"title":"Thicken sauce","description":"Add the chicken (plus all juices) and simmer for another 2 to 3 minutes until the gravy is quite thick and you can draw a path on the base of the pan. (Sauce thickness now = sauce thickness once baked). Taste - add more salt if needed (I don’t).","images":[],"step":8},{"title":"Assemble","description":"Pour into a 1.5 - 2 L (6 - 8 cup) baking pan and smooth the surface. (Note 5 for other pan sizes)","images":[],"step":9},{"description":"Preheat oven to 200°C / 390°F (180°C fan-forced).","images":[],"step":10},{"title":"Duchess potato topping","description":"Pipe mounds of mashed potato swirls on the surface. My swirls have a 4.5cm base (1.6\"), about 4cm tall (1.4\"), then I fill gaps with small swirls/blobs. I use all the mash! Drizzle with melted butter, sprinkle with parmesan. (Note 6 for no piping bag)","images":[],"step":11},{"description":"Bake for 30 minutes, rotating the pan at the 20 minute mark.","duration":30,"images":[],"step":12},{"title":"Serve","description":"Rest for 10 minutes, sprinkle with parsley if using. Attack!","duration":10,"images":[],"step":13},{"title":"Make mash","description":"Put the potatoes into a large pot of cold tap water. Bring to a boil over high heat then cook for 15 minutes until soft. Drain, pass through a potato ricer (smoother) or mash well with a potato masher in the now empty pot. Add butter, milk, 1/2 tsp salt and 1/8 tsp white pepper, stir through - it should be creamy but not loose (so it holds its form when piped).","duration":15,"images":[],"step":14},{"title":"Piping bag","description":"Transfer mash into a piping bag fitted with a star tip. (Note 6 for no piping bag)","images":[],"step":15}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["casseroles-and-cosy-bakes","chicken","chicken-recipes","mains","quiches-tart-and-pie-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_15961522cbb1', 'en', 'US', 'Chicken Cacciatore', 'Recipe video above. I love this chicken stew, made with simple ingredients that''s so cosy and comforting. Also known as Hunter''s Stew, this is made with a tomato sauce that''s rich with red wine, herbs, and Kalamata olives. While there are various regional variations, capsicum (bell peppers) and mushrooms are typical vegetable inclusions though I''ve also seen varieties using fennel which is so distinctly Italian too (finely slice and sauté). Serve over mash or polenta for the perfect cosy evening meal.', 'https://www.recipetineats.com/tachyon/2024/06/Chicken-Cacciatore-50813.jpg', 15, 55, 70, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_rosemary", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_fish_fillets", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_pinot_noir", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_whole_kalamata_olives", "quantity": {"value": 16.0, "unit": "bottle"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["4 bone in chicken thighs large (1 kg / 2 lb)","4 chicken drumsticks","1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper","1 tbsp olive oil"],"purpose":"Chicken (Note 1):"},{"ingredients":["1 onion (, halved, finely sliced)","2 rosemary sprigs ((about 15 cm/6\" long), or 1 tsp dried rosemary)","2 bay leaves (, preferably fresh else dried)","3 garlic cloves (, finely minced)","3 anchovy fillets (or 1 tsp anchovy paste), optional (Note 2)","250g / 8 oz mushrooms (, sliced)","2 red capsicum (, sliced 8 mm thick (medium, not giant))","1/3 cup tomato paste","3/4 cup pinot noir (or other dry red wine (Note 3))","2 cups chicken stock/broth (, low sodium)","400g/14 oz canned crushed tomato","16 whole kalamata olives (, pitted, drained)","1/4 tsp cooking/kosher salt","1/4 tsp black pepper","1 tsp dried oregano"],"purpose":"Cacciatore:"},{"ingredients":["Mashed potato ( or polenta)","Finely chopped parsley (, for sprinkling (optional))"],"purpose":"Serving"}]', '[{"title":"Season","description":"Spread the chicken out on a tray. Sprinkle both sides with the salt and pepper.","images":[],"step":1},{"title":"Brown skin","description":"Heat the oil over high heat in a large, deep, heavy based pan, preferably one with a lid (Note 4). Place the chicken thighs in the pan, skin side down, and cook until the skin is golden brown, around 6 minutes. Turn and cook the flesh side for just 1 minute, then remove the chicken onto the same tray. Then add the drumsticks and brown each side as best you can, about 1 1/2 minutes on each side (the shape makes it awkward). Remove onto the tray.","images":[],"step":2},{"title":"Onion","description":"Pour off and discard all but about 2 tablespoons of fat. Turn the heat down to medium and let the pan cool slightly. Add the onion, rosemary leaves, bay leaves and dried oregano. Cook for 3 minutes until the onion is starting to soften.","duration":3,"images":[],"step":3},{"title":"Garlic and anchovies","description":"Clear a space in the middle of the pan. Add the anchovies and garlic, cooking, mashing up the anchovies, until the garlic is light golden, then stir it into the onion.","images":[],"step":4},{"title":"Vegetables & tomato paste","description":"Turn the heat back up to high. Add the mushroom and capsicum. Stir until softened - about 5 minutes (the mushrooms will go watery then the water will evaporate). Add the tomato paste and cook for 2 minutes to cook out the sour flavour - do not shortcut this.","duration":2,"images":[],"step":5},{"title":"Sauce","description":"Add the wine. Stir, bring to simmer then allow to reduce by around 75%. Add the stock, canned tomato, salt and pepper. Stir, bring to a simmer.","images":[],"step":6},{"title":"Simmer","description":"Then carefully place the chicken into the sauce (skin side up) and pour any juices on the tray in as well. When the liquid returns to a simmer, cover, reduce the heat to medium then simmer energetically for 20 minutes. Remove lid, add olives, simmer for a further 10 minutes (no lid). This will reduce and thicken the sauce.","duration":20,"images":[],"step":7},{"title":"Serve","description":"Serve the chicken with plenty of sauce over mashed potato or polenta, sprinkled with parsley if desired.","images":[],"step":8}]', '["fish"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["casseroles-and-cosy-bakes","chicken","chicken-drumstick-recipes","chicken-recipes","mains","stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9d3a5c00a721', 'en', 'US', 'Chicken pasta bake', 'Recipe video above. Everything a chicken pasta bake should be - big, juicy, bubbly, cosy, with loads of extra tasty sauce, sizzling seasoned chicken, bacon and plenty of cheese. Nice change from the usual creamy pasta bakes!This is a complete meal with starch, protein and veg so you won''t need a side salad for this. Love the juicy chunks of tomato!', 'https://www.recipetineats.com/tachyon/2023/05/Chicken-pasta-bake_7.jpg', 15, 45, 60, 6, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_italian_herb_mix", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_rigatoni", "quantity": {"value": 300.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.833, "unit": "pack of 3 heads"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_baby_spinach", "quantity": {"value": 2.0, "unit": "bag of 250g"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.6, "unit": "pack of 125g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}]', '[{"ingredients":["500g / 1 lb chicken thighs (, cut into small bite size pieces (Note 1))","1/2 tsp cooking/kosher salt","1/4 tsp black pepper","1/2 tsp garlic powder","2 tsp Italian herb mix (, any store bought type)"],"purpose":"Seasoned Chicken"},{"ingredients":["300g/10oz rigatoni (or penne, elbow macaroni, shells or similar)","2 tsp salt (, for cooking pasta)","5 slices streaky bacon","1/2 onion (, finely chopped)","2 garlic cloves (, minced)","1 1/2 tsp dried oregano","1/2 tsp chilli flakes / red pepper flakes","1/2 cup chardonnay or other dry white wine (Note 2)","2 tbsp tomato paste","700g / 24oz tomato passata (Note 3)","1/2 cup water","1 tsp cooking/kosher salt","1/2 tsp black pepper","3 tomatoes (, cut into 8 wedges then halved)","2 big handfuls baby spinach (or bite size kale)","2 cups mozzarella, (shredded)","1/2 cup (tightly packed) parmesan, (finely shredded)"],"purpose":"Pasta bake"}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan).","images":[],"step":1},{"description":"Cook pasta per packet directions, using boiling water seasoned with the 2 teaspoons of salt. Drain, rinse briefly under tap water, then set aside to cool while making the sauce.","images":[],"step":2},{"title":"Season chicken","description":"Toss together Seasoned Chicken ingredients in a bowl.","images":[],"step":3},{"title":"Crisp bacon","description":"Put bacon in an unheated very large non-stick pan (Note 2). Turn stove on medium high. The fat will melt so the bacon cooks in its own fat. Cook until light golden, remove onto paper towels, leaving fat in the pan. Once cool, cut into 1cm / 1/3\" pieces.","images":[],"step":4},{"title":"Sizzle chicken","description":"Top up bacon fat with olive oil if you don’t have at least 1 tbsp. Increase heat to high. Cook chicken for 3 minutes until light golden on the outside but still raw inside. Remove into a bowl with a slotted spoon.","duration":3,"images":[],"step":5},{"title":"Sauce","description":"In the same pan, cook garlic and onion for 1 minute, then add chilli flakes and oregano. Cook for 2 minutes until onion is translucent. Add wine and rapidly simmer for 1 to 2 minutes until mostly evaporated. Add tomato paste and cook for 1 minute to concentrate and improve flavour. Add passata, then use the water to rinse out the bottle. Add salt, pepper, chicken (including all juices on the plate). Mix, then simmer for 5 minutes on medium.","duration":1,"images":[],"step":6},{"title":"Toss","description":"Add baby spinach, tomato, pasta and bacon. Toss well.","images":[],"step":7},{"title":"Assemble","description":"Transfer to 23 x 33cm/9 x 13\" pan. Top with mozzarella then parmesan. Bake 25 minutes until melted with some golden spots.","images":[],"step":8},{"title":"Serve","description":"Stand for 5 minutes then serve!","duration":5,"images":[],"step":9}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian-esque","Western"],"categories":["casseroles-and-cosy-bakes","chicken","chicken-recipes","mains","pasta-bakes","pasta-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_21c841bde5ba', 'en', 'US', 'Spinach Ricotta Stuffed Shells (Conchiglioni)', 'Recipe VIDEO above. There''s no need to mess around stuffing hot floppy shells. Just stuff uncooked jumbo pasta shells and bake in loads of sauce! Bonus: The shells absorb the flavour of the sauce, and there''s plenty of tasty sauce for serving. Because nobody likes dry pasta shells!', 'https://www.recipetineats.com/tachyon/2023/03/Spinach-ricotta-stuffed-shells_4.jpg', 25, 105, 60, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.111, "unit": "bottle of 750ml"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.033, "unit": "jar of 50g"}}, {"id": "ing_spinach", "quantity": {"value": 250.0, "unit": "bag of 250g"}}, {"id": "ing_ricotta", "quantity": {"value": 2.0, "unit": "tub of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_nutmeg", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.8, "unit": "pack of 125g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}]', '[{"ingredients":["2 tbsp olive oil","2 eschallots/shallots or 1 small onion (, finely chopped (Note 1))","4 garlic cloves (, finely minced)","1 bay leaf (, fresh (sub dried))","1/2 tsp each dried thyme and oregano","1/3 cup tomato paste","700g / 25 oz tomato passata (US: tomato sauce) (Note 2)","1/3 cup Chardonnay or other dry white wine (sub more stock)","4 cups vegetable stock/broth (, low sodium)","3/4 tsp salt","1 1/2 tsp white sugar","1/3 tsp black pepper"],"purpose":"Sauce (you need LOTS!):"},{"ingredients":["250g / 8 oz frozen chopped spinach (, thawed (Note 3))","500g / 1 lb ricotta (, full fat please (Note 4))","1/2 cup parmesan (, finely shredded)","1 cup shredded cheese (Mozzarella, Colby, Cheddar, Tasty, Gruyere, Swiss, anything!)","1 egg","1 large garlic clove (, minced)","Grated fresh nutmeg (just a sprinkling) ( or 1/8 tsp nutmeg powder (optional))","3/4 tsp cooking / kosher salt","1/2 tsp black pepper"],"purpose":"Filling:"},{"ingredients":["250g / 8 oz jumbo pasta shells (conchiglioni) (Note 3)","1 1/2 cups shredded mozzarella","1/2 cup parmesan (, shredded)","Fresh basil and parmesan (, for garnish (optional))"],"purpose":"Stuffed shells"}]', '[{"title":"Sauté","description":"Heat oil in a small pot over medium high heat. Add garlic, onion, bay leaf, thyme and oregano. Cook for 3 - 4 minutes until the onion is translucent. Add tomato paste and cook for 1 minute.","duration":3.5,"images":[],"step":1},{"title":"Reduce wine","description":"Add wine, increase heat to high and let it simmer rapidly until mostly evaporated (about 2 minutes).","images":[],"step":2},{"title":"Simmer","description":"Add passata, stock, sugar, salt and pepper. Stir then simmer on low *(uncovered) for 20 minutes. Use while hot.","duration":20,"images":[],"step":3},{"title":"Squeeze spinach","description":"Grab handfuls of spinach and squeeze out excess water.","images":[],"step":4},{"title":"Mix filling","description":"Place spinach in a bowl with remaining Filling ingredients. Mix well.","images":[],"step":5},{"description":"Assemble & Bake:","images":[],"step":6},{"description":"Preheat oven to 200°C/400°F (180°C fan).","images":[],"step":7},{"title":"Stuff","description":"Stuff UNCOOKED shells with spinach ricotta filling. Stuff them full!","images":[],"step":8},{"title":"Assemble","description":"Pour the hot tomato sauce in a 23 x 33 cm / 9 x 13\" baking dish. Gently place the stuffed shells in - most will be submerged, some may poke above surface.","images":[],"step":9},{"title":"Bake","description":"Cover with a baking tray (or foil) then bake for 70 minutes.","duration":70,"images":[],"step":10},{"title":"Cheese it! Check the shells","description":"they should be al dente! (If not, return to oven, covered). Sprinkle with mozzarella then parmesan. Bake 15 minutes until melted.","images":[],"step":11},{"description":"Serve, garnished with extra parmesan and basil if desired!","images":[],"step":12}]', '["egg","gluten","milk"]', '["high_protein","vegetarian"]', '{"mealType":["dinner"],"cuisine":["American-Italian","Italian","Western"],"categories":["casseroles-and-cosy-bakes","cosy-desserts","italian-recipes","pasta-bakes","pasta-recipes","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c0bed5d30664', 'en', 'US', 'Chorizo chickpea stew (fast)', 'Recipe video above. This is a great, hearty, full flavoured Spanish-inspired stew that''s quick to make. Chorizo is the shortcut here, adds a ton of flavour into the sauce!Serve this as a chunky soup with crusty bread for mopping, flatbreads for dunking, or like stew over a bed of couscous, small pasta (like orzo/risoni, orecchiette), mashed potato or cauliflower puree. For an extra hit of protein, top with a fried egg. YUM!Serves 2 hearty appetites, or 3 normal appetites.', 'https://www.recipetineats.com/tachyon/2023/01/Chorizo-chickpea-stew_0.jpg', 7, 20, 27, 2, '[{"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_chorizo", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_thyme", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["1 1/2 tbsp olive oil","250g / 8 oz chorizo (2 pieces) (, cut into 8mm / 1/3\" slices (Note 1))","2 garlic cloves (, minced)","1/2 tsp dried thyme","1/2 tsp smoked paprika (sub normal paprika)","1 bay leaf (, preferably fresh, otherwise dried)","400g / 14oz can crushed tomato","400g/14 oz can chickpeas (, drained (or other beans of choice))","1 cup chicken stock/broth (, low sodium)","1/4 tsp cooking/kosher salt","1/4 tsp black pepper"]}]', '[{"title":"Sauté chorizo","description":"Heat olive oil in a large saucepan or small pot over medium high heat. Add chorizo and cook for 3 minutes or until golden.","duration":3,"images":[],"step":1},{"title":"Sauté aromatics","description":"Add garlic, thyme, paprika and bay leaf, then stir for 1 minute.","duration":1,"images":[],"step":2},{"title":"Add everything else","description":"Add tomato, chickpeas, chicken stock, salt and pepper. Stir, bring to a simmer then lower the heat down to medium low so it is simmering very gently.","images":[],"step":3},{"description":"Cook for 15 minutes (no lid), stirring regularly to ensure the base does not catch, until the sauce has reduced and thickened.","duration":15,"images":[],"step":4},{"title":"Serve","description":"Discard bay leaf and serve. I love this with hot crusty bread (slathered with butter!).","images":[],"step":5}]', '[]', '["gluten_free","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Spanish","Spanish Style","Western"],"categories":["casseroles-and-cosy-bakes","dinner-tonight","quick-and-easy","stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_99df5f43dfdc', 'en', 'US', 'Chicken Tagine', 'Recipe video above. Browned chicken braised in a spiced sauce, the secret to a great Moroccan Chicken Tagine is a well-balanced spice blend! Best made with bone-in chicken thighs, which stay juicy for the required sauce simmering time. Drumsticks work well too. Some versions are made with olives, others use dried fruit, and some even use both. I''ve opted for fruit because it''s one of the few dishes I love fruit with meat! See note 7 for the olive option (it''s delish too). Note: Crushed tomato isn''t typically used in traditional tagines but I love how it thickens the sauce so it clings to the couscous better. Without, the sauce is watery.', 'https://www.recipetineats.com/tachyon/2022/05/Chicken-tagine_5.jpg', 15, 40, 55, 6, '[{"id": "ing_apricots", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 6.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.625, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_cumin", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_ginger", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.025, "unit": "bunch"}}, {"id": "ing_powder", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_couscous_plain_or_with_fruit_and_or_nuts", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.025, "unit": "bunch"}}, {"id": "ing_kalamata_olives", "quantity": {"value": 150.0, "unit": "bottle"}}, {"id": "ing_almonds", "quantity": {"value": 0.2, "unit": "pack of 250g"}}]', '[{"ingredients":["1 cup dried apricot, halved (Note 1)","6 x 220g / 7 oz chicken thighs (, bone-in skin-on (Note 2))","3/4 tsp salt (cooking/kosher salt)","2 tbsp olive oil","1 onion ((brown/yellow), cut into 0.3 cm/ 1/8\" slices)","2 garlic cloves (, finely minced)","1 cinnamon stick (sub 1/2 tsp powder)","400 g / 14 oz crushed tomato (1 can)","400g / 14 oz canned chickpeas (, drained (Note 10))","1 tbsp preserved lemon skin (, finely minced (Note 3))","2 1/2 cups chicken stock, low-sodium ( (or homemade))"]},{"ingredients":["1 tsp cooking salt","3/4 tsp ground cumin","3/4 tsp ground ginger","3/4 tsp black pepper","1/2 tsp allspice powder","1/4 tsp cinnamon powder","1/4 tsp coriander powder","1/8 tsp clove powder"],"purpose":"Ras el hanout spice blend (Note 4):"},{"ingredients":["Couscous - plain or with fruit and/or nuts (recipe here)","2 tbsp fresh coriander (, roughly chopped)"],"purpose":"For serving:"},{"ingredients":["1 cup kalamata olives (instead of apricots) (Note 7)","1/3 cup slivered almonds (, lightly toasted, for garnish (Note 8))"],"purpose":"Alternative add in options"}]', '[{"title":"Plump apricots","description":"Soak the dried apricots in a bowl of boiling water for 30 minutes, then drain (this plumps them up).","duration":30,"images":[],"step":1},{"title":"Season chicken","description":"Sprinkle both sides of the chicken with the salt.","images":[],"step":2},{"title":"Brown chicken","description":"Heat oil the oil in a large, deep skillet or pot (Note 5) over high heat. Place chicken in the skillet skin side down and cook for 8 to 10 minutes until deep golden. Turn and cook the flesh side for 1 minute then remove to a plate.","duration":9,"images":[],"step":3},{"title":"Sauté aromatics & spices","description":"Discard all but 2 tablespoons of fat in the skillet. Reduce heat to medium. Add onions and cook for 3 minutes. Add garlic and cook for 1 minute. Add the Ras el hanout and stir for 30 seconds.","duration":3,"images":[],"step":4},{"title":"Tagine sauce","description":"Add the cinnamon stick, tomato, chickpeas, plumped apricots, stock and preserved lemon, then stir. Place the chicken on top, skin side up.","images":[],"step":5},{"title":"Simmer covered 5 minutes","description":"Bring the liquid to a simmer then cover with a lid (Note 6). Cook for 5 minutes, adjusting the heat as needed so the liquid is simmering (but not too rapidly else base may catch).","duration":5,"images":[],"step":6},{"title":"Simmer uncovered 20 minutes","description":"Remove lid then cook for a further 20 minutes or until the internal temperature of the chicken is at least 70°C/158°F (Note 6).","images":[],"step":7},{"title":"Serve","description":"Remove from stove and rest for 5 minutes. Serve over couscous (Note 9), sprinkled with fresh coriander.","duration":5,"images":[],"step":8}]', '["gluten"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Moroccan"],"categories":["casseroles-and-cosy-bakes","chicken","chicken-recipes","cuisines","mains","middle-eastern-recipes","moroccan","stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1fa37409724e', 'en', 'US', 'Baked Mac and Cheese', 'Recipe VIDEO above. Still the best Baked Mac and Cheese I''ve ever had in my life! Perfect in every way, this has a stunningly white, ultra creamy cheese sauce with a beautiful crunchy, buttery topping. Great one for serving at gatherings because it won''t dry out and go stodgy like most Macaroni Cheese recipes because of the extra step of tossing the macaroni in butter (stops it from bloating) and because it''s extra saucy out of the oven. TOP TIP: Grate your own cheese, it makes all the difference. Store bought includes anti-caking agents that can make your sauce a bit grainy or powdery.', 'https://www.recipetineats.com/tachyon/2020/11/Baked-Mac-and-Cheese-pull-shot.jpg', 10, 60, 70, 6, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_bread", "quantity": {"value": 0.125, "unit": "loaf"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_gruyere_cheese", "quantity": {"value": 2.0, "unit": "block of 200g"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.8, "unit": "pack of 125g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.013, "unit": "jar of 200g"}}]', '[{"ingredients":["250g / 8 oz macaroni (elbow pasta)","1 tbsp (15g) unsalted butter (or 2 tsp oil)"],"purpose":"Macaroni:"},{"ingredients":["2/3 cup panko breadcrumbs (Note 1)","2 tbsp (30g) unsalted butter (, melted)","1/4 tsp salt"],"purpose":"Topping:"},{"ingredients":["4 tbsp (60g) unsalted butter","1/3 cup flour (, plain / all purpose)","3 cups milk (, warmed (low or full fat))","2 cups freshly shredded cheese, gruyere best (followed by cheddar and Colby) (Note 2)","1 cup freshly shredded mozzarella cheese (, or more other cheese of choice (Note 2))","3/4 tsp salt"],"purpose":"Sauce:"},{"ingredients":["1 tsp garlic powder","1/2 tsp onion powder","1/2 tsp mustard powder"],"purpose":"Seasonings (optional):"}]', '[{"title":"Cook pasta","description":"Bring a large pot of water to the boil. Add macaroni and cook per packet directions MINUS 1 minute.","images":[],"step":1},{"title":"Toss in butter","description":"Drain, return pasta to pot, add butter and toss until melted. Set aside to cool while making the Sauce (Optional - Note 3).","images":[],"step":2},{"description":"Mix together Topping. Set aside.","images":[],"step":3},{"description":"Sauce (video is helpful):","images":[],"step":4},{"description":"Preheat oven to 180°C/350°F (all oven types).","images":[],"step":5},{"title":"Make roux","description":"In a large saucepan or in an ovenproof skillet (I use my 26cm/9\" Lodge cast iron skillet), melt butter over medium heat. Add flour and cook, stirring constantly, for 1 minute.","duration":1,"images":[],"step":6},{"title":"Add milk","description":"Add about 1 cup of the milk and mix to dissolve the paste into the milk. Then add remaining milk and mix until lump free (use whisk if required).","images":[],"step":7},{"title":"Add Seasonings","description":"Mix in salt and Seasonings if using.","images":[],"step":8},{"title":"Thicken sauce","description":"Cook, stirring/whisking regularly, for 5 - 8 minutes until thickened to a cream consistency. When the Sauce coats the back of a wooden spoon, you should be able to draw a path with your finger.","duration":6.5,"images":[],"step":9},{"title":"Add cheese","description":"Remove from stove, add cheese and stir - cheese doesn''t need to melt.","images":[],"step":10},{"title":"Check salt","description":"Adjust salt to taste (if you use recommended cheeses, you won''t need more).","images":[],"step":11},{"title":"Assemble","description":"Pour Sauce into pot with Macaroni. Stir quickly, then pour back into the skillet (I did this) or a baking dish (Note 4). Sprinkle with breadcrumb topping.","images":[],"step":12},{"description":"Bake for 25 minutes or until top is light golden. Don''t bake too long otherwise you''ll bake away the Sauce!","duration":25,"images":[],"step":13},{"title":"Serve","description":"Serve immediately! I sprinkled mine with a bit of fresh parsley. See notes for best make-ahead method.","images":[],"step":14}]', '["gluten","milk","mustard"]', '["high_protein","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["casseroles-and-cosy-bakes","easter-recipes","easter-sides-warm-hearty","pasta-bakes","pasta-recipes","quick-and-easy","side-dishes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cf5a8dcf7b6a', 'en', 'US', 'Eggplant Parmigiana (Parmigiana di Melanzane)', 'Recipe video above. There''s a little labour involved in this. But you''ll be rewarded with one of the all-time greatest vegetarian comfort foods known to mankind!Assemble ahead, then pop in the oven to bake when you''re ready!', 'https://www.recipetineats.com/tachyon/2021/05/Eggplant-Parmigiana_1.jpg', 40, 60, 100, 8, '[{"id": "ing_egg", "quantity": {"value": 1.8, "unit": "carton of 12"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 0.833, "unit": "pack of 200g"}}, {"id": "ing_basil", "quantity": {"value": 1.2, "unit": "bunch"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.2, "unit": "pack of 125g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["1.8kg / 4 lbs large eggplants (aubergines) - about 5 (, sliced lengthways 8mm (1/3\")-thick (skin on, Note 1))","1/4 cup olive oil (for brushing)"],"purpose":"Baked Eggplant Slices:"},{"ingredients":["1 2/3 cups parmesan (, finely grated)","2 cups basil leaves ((loosely packed), stalks reserved)","1 1/2 cups mozzarella (, shredded (for topping) (Note 2))"],"purpose":"Layers:"},{"ingredients":["2 tbsp extra virgin olive oil","1 onion (, finely diced)","5 garlic cloves (, finely minced)","600ml / 20oz tomato passata (Note 3)","400g/ 14oz canned tomatoes (, crushed or finely chopped (Note 4))","1 1/2 tsp white sugar","1 1/2 tbsp fresh oregano (, finely chopped (or 1/2 tsp dried oregano, or 1 sprig fresh basil))","1 cup water","3/4 tsp salt","1/4 tsp black pepper"],"purpose":"Sugo (tomato sauce):"}]', '[{"description":"Baking eggplant:","images":[],"step":1},{"description":"Preheat oven to 220°C / 430°F (200°C fan).","images":[],"step":2},{"title":"Line three trays","description":"Line three large trays with baking / parchment paper.","images":[],"step":3},{"title":"Brush eggplant with oil","description":"Brush eggplant slices on each side with oil.","images":[],"step":4},{"title":"Bake 35 minutes","description":"Arrange eggplant in a single layer on the trays and bake for about 35 - 45 mins or until browning and tender, turning the eggplant halfway. I put the trays on the top shelf, in the middle, then I put one tray on the floor of the oven. As each tray finishes, I remove the tray and move the others up.","images":[],"step":5},{"title":"Cool","description":"Remove from oven, leave on trays to cool.","images":[],"step":6},{"description":"Tomato sauce (sugo):","images":[],"step":7},{"title":"Sauté onions and garlic","description":"Heat olive oil in a large skillet over medium-high heat. Sauté onions and garlic for 3 minutes until softened and just about to colour on the edges.","duration":3,"images":[],"step":8},{"title":"Add remaining ingredients","description":"Pour in the passata , canned tomatoes, water, oregano and sugar. Stir and bring to a simmer.","images":[],"step":9},{"title":"Simmer 30 minutes: Simmer uncovered for about 30","description":"40 minutes, stirring occasionally, until thickened, adding the basil stalks halfway through cooking (so they don’t lose their flavour).","images":[],"step":10},{"description":"The final consistency should be slightly thicker than a pasta sauce so it’s spreadable and not leaching liquid, but not too pasty either. Add extra water a little at a time if required during cooking if it gets too thick. Remove the basil stalks and discard.","images":[],"step":11},{"title":"Season","description":"Stir in salt and pepper. (Remember, we get salt from the parmesan too, so no need to go overboard here)","images":[],"step":12},{"description":"Assembling and baking:","images":[],"step":13},{"description":"Reduce oven to 180°C / 350°F (160°C fan).","images":[],"step":14},{"description":"Smear a little tomato sauce in the bottom of baking dish, 23 x 33cm / 9 x 13\" (or thereabouts).","images":[],"step":15},{"title":"Layer 1","description":"Lay one third of the eggplant so it covers the base (some overlap is OK when layering eggplant). Spread 1/3 of the remaining sugo over eggplant. Drizzle with a little olive oil. Sprinkle with 1/3 of the parmesan, and 1/3 of basil leaves.","images":[],"step":16},{"title":"Layer 2","description":"Repeat another 1/3 each of eggplant, tomato sauce, olive oil, basil and parmesan.","images":[],"step":17},{"title":"Layer 3 (top layer)","description":"Repeat again with remaining eggplant, tomato sauce and some olive oil. Do not put basil on top layer (we will garnish after baking). Scatter with remaining parmesan, then all the mozzarella.","images":[],"step":18},{"description":"Bake for 25 mins until bubbling and golden.","duration":25,"images":[],"step":19},{"title":"Rest","description":"Let it rest for 5 to 10 minutes (easier to slice neatly). Scatter over remaining fresh basil leaves. Cut like lasagna and serve! (Optional: sprinkle with extra parmesan).","duration":7.5,"images":[],"step":20}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["American-Italian","Italian"],"categories":["casseroles-and-cosy-bakes","dietary","gluten-free-recipes","italian-recipes","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6399a0413b12', 'en', 'US', 'Pastitsio (Greek Pasta Bake)', 'Recipe video above. Greece''s answer to Italian Lasagna! This traditional Greek dish is made with layers of pasta topped with a rich meat sauce perfumed with a hint of cinnamon and clove, topped with a thick layer of cheese sauce.For the neat layers pictured, arrange the pasta so they''re all going in one direction, and rest the baked Pastitsio for 15 minutes before slicing. Excellent for making ahead (keeps for 4 to 5 days in the fridge) and freezes very well!', 'https://www.recipetineats.com/tachyon/2021/02/Pastitsio-_4.jpg', 15, 120, 135, 8, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.25, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_round_clove", "quantity": {"value": 1000.0, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_nutmeg", "quantity": {"value": 0.625, "unit": "jar"}}, {"id": "ing_cheese", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 2.0, "unit": "pack of 500g"}}, {"id": "ing_feta_cheese", "quantity": {"value": 120.0, "unit": "block of 200g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}]', '[{"ingredients":["2 tbsp olive oil","3 garlic cloves (, finely minced)","2 red onions (, finely chopped (sub yellow or brown onions))","1 kg / 2 lb beef mince (ground beef)","3/4 cup red wine (, dry (Note 1))","800g / 28 oz canned crushed tomato","2 beef bouillon cubes (, crumbled (stock cubes))","2 tbsp tomato paste","1 tsp white sugar","1 bay leaf","1/2 tsp cinnamon powder","1 cinnamon stick (or extra 1/2 tsp cinnamon powder)","1/4 tsp ground cloves","3/4 tsp salt","1 tsp black pepper"],"purpose":"Meat Sauce:"},{"ingredients":["100g / 7 tbsp butter (, unsalted)","3/4 cup flour (, plain/all purpose)","1 litre / 4 cups milk (, whole/full fat best but low fat ok)","1/8 tsp nutmeg (, preferably freshly grated)","1/2 tsp salt","100g / 3 oz Kefalotyri Greek cheese (sub Parmesan or Romano) (, finely shredded (Note 2))","2 egg yolks (egg whites are used in the pasta)"],"purpose":"Greek Bechamel:"},{"ingredients":["400g / 14 oz Pastitsio No. 2 pasta / Greek bucatini (sub small ziti, penne or normal bucatini, Note 3)","120g / 4 oz feta (, crumbled)","2 egg whites (yolks used in Béchamel)"],"purpose":"Pasta:"},{"ingredients":["75g / 3 oz Kefalotyri Greek cheese (sub parmesan or Romano) (, finely grated (Note 2))"],"purpose":"Topping:"}]', '[{"description":"Heat in a large pot over high heat. Add garlic and onion, cook for 2 - 3 minutes until onion is softened. Add beef and cook, breaking it up as you go, until it changes from red to brown.","duration":2.5,"images":[],"step":1},{"description":"Add wine and and cook until the wine has mostly evaporated - about 3 minutes.","images":[],"step":2},{"description":"Add remaining Meat Sauce ingredients. Stir well, bring to simmer, then reduce heat to medium / medium low so it''s simmering gently. Cook for 45 min to 1 hour until liquid is mostly gone, stirring every now and then. It should be a thick mixture with little liquid, not saucy like Spaghetti Bolognese (Note 4).","duration":45,"images":[],"step":3},{"description":"Remove from stove and cool. Preferably to room temperature, otherwise for at least 30 minutes before assembling (lid off).","images":[],"step":4},{"description":"Greek Béchamel (Note 5):","images":[],"step":5},{"description":"Melt butter in a large saucepan over medium heat. Add flour and stir for 1 minute.","duration":1,"images":[],"step":6},{"description":"While stirring, slowly pour half the milk in. It should turn into a wet paste. Then again, while stirring, pour in remaining milk - the paste should easily dissolve so it''s lump-free. If not, just whisk vigorously.","images":[],"step":7},{"description":"Cook, stirring so the base doesn''t catch, for 5 minutes or until thick enough so it coats the back of a wooden spoon thickly and you can draw a path across it with your finger.","duration":5,"images":[],"step":8},{"description":"Remove from stove. Stir in nutmeg, cheese and salt.","images":[],"step":9},{"description":"Leave to cool for 5 minutes. Then whisk in egg yolks quickly. Place lid on and set aside. If sauce cools and gets too thick to pour, just reheat on a low stove until pourable.","duration":5,"images":[],"step":10},{"description":"Pasta (Note 6):","images":[],"step":11},{"description":"When you''re ready to assemble, cook the pasta per packet instructions, minus 1 minute.","images":[],"step":12},{"description":"Drain, then return to the pot. Leave to cool for 3 minutes, then stir through egg whites. Gently stir through crumbled feta.","duration":3,"images":[],"step":13},{"description":"Assemble and bake:","images":[],"step":14},{"description":"Preheat oven to 180°C/350°F (all oven types).","images":[],"step":15},{"description":"Place pasta in a baking dish (33 x 22 x 7 cm / 9 x 13 x 2.75\"), arranging them so they are all going in the same direction as best you can (for visual effect when sliced). Make the surface as level as you can.","images":[],"step":16},{"description":"Top with Meat Sauce, then smooth the surface.","images":[],"step":17},{"description":"Pour over Béchamel Sauce, then sprinkle over the cheese.","images":[],"step":18},{"description":"Bake 30 min or until crust turns golden.","images":[],"step":19},{"description":"Cool for at least 10 minutes so you can cut neat slices with the layers neatly visible. Serve!","images":[],"step":20}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Greek"],"categories":["casseroles-and-cosy-bakes","greek-recipes","mediterranean-recipes","pasta-bakes","pasta-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a839b8dac309', 'en', 'US', 'Chicken Tetrazzini (creamy chicken mushroom pasta bake)', 'Recipe video above. A big, creamy pasta bake with juicy chicken and mushrooms. Cheesy, hot and completely delicioius! Rumoured to be named after an Italian opera star Luisa Tetrazzini when an American Chef created this dish for her. So it''s not authentic Italian - but it doesn''t make this any less delicious!!', 'https://www.recipetineats.com/tachyon/2020/08/Chicken-Tetrazzini_0.jpg', 15, 60, 75, 8, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}]', '[{"ingredients":["500g / 1lb spaghetti or other long pasta, cooked per packet (penne, macaroni, ziti ok too) (Note 1)"]},{"ingredients":["2 tbsp (30g) butter","500g / 1lb chicken thighs (, skinless boneless (Note 2))"],"purpose":"Chicken"},{"ingredients":["4 tbsp (60g) butter (, unsalted)","500g / 1lb mushrooms (, sliced 1/2 cm / 1/5\" thick)","2 garlic cloves (, minced)","1 onion (, finely chopped)","4 tbsp flour","2 cups milk (, any fat, any type)","1 cup cream (, heavy / thickened (sub more milk))","2 cups chicken stock/broth (, low sodium (or water + 2 stock cubes))","1/2 tsp black pepper","1 tsp salt","2 cups cheese (, shredded (cheddar, jack, colby - not mozz))"],"purpose":"Creamy Sauce"}]', '[{"description":"Melt 2 tbsp butter in a large pot over high heat. Add chicken, sprinkle with pinch of salt and pepper. Cook 1 1/2 minutes until golden.","images":[],"step":1},{"description":"Turn chicken, sprinkle with salt and pepper. Cook 1 minute until golden then remove onto plate - doesn''t need to be fully cooked (will cook more in oven).","images":[],"step":2},{"description":"Rest 5 minutes, then chop into small pieces, or shred.","images":[],"step":3},{"description":"Preheat oven to 160°C / 325°F.","images":[],"step":4},{"title":"Cook mushrooms","description":"Melt 4 tbsp butter over high heat in the same pot. Add mushrooms and cook for 4 minutes until starting to go floppy but not yet golden.","duration":4,"images":[],"step":5},{"title":"Add onion","description":"Add garlic and onion, cook for 3 minutes until mushrooms are golden. Add a pinch of salt and pepper halfway through.","duration":3,"images":[],"step":6},{"title":"Add flour & milk","description":"Turn heat down to medium. Add flour. Stir for 30 seconds. Add milk and stir for 10 seconds or until it thickens (see video at 52 sec).","duration":0.5,"images":[],"step":7},{"title":"Add cream and broth","description":"Add chicken stock, cream, 1 tsp salt and 1/2 tsp pepper. Stir, then let the mixture heat up, stirring every now and then so it doesn''t catch on the base, and cook until the sauce thickens enough so you can draw a path on the back of the spoon (video at 1.04). Do not make it very thick - it gets thicker in next steps.","images":[],"step":8},{"title":"Add cheese & pasta","description":"Turn stove off. Stir through half the cheese (will melt in oven), then add pasta and chicken. Toss to mix, taste and add more salt if needed.","images":[],"step":9},{"title":"Bake","description":"Pour into 23 x 33cm / 9 x 13\" pan, smooth surface. Top with remaining cheese. Bake 25 minutes until golden and bubbly. Serve immediately!","images":[],"step":10}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["casseroles-and-cosy-bakes","chicken-breast-recipes","chicken-recipes","italian-recipes","pasta-bakes","pasta-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2e596835d0b8', 'en', 'US', 'Baked Spinach and Ricotta Rotolo', 'Recipe video above. Rotolo is a lessor known Italian pasta dish where a filling is rolled up in pasta sheets then rolled like a roulade, poached, sliced then served. It is so tasty, but quite technical and time consuming to make. This is my version - a baked version which is made more like cannelloni. Much easier, just as tasty and best of all, you get crunchy brown bits you don''t get with the traditional rotolo!Want a meat filling? Use the filling from this Spinach & Beef Cannelloni - scale up by 50% (or use extra spinach), cool (will thicken) then roll!', 'https://www.recipetineats.com/tachyon/2014/07/Spinach-Ricotta-Rotolo-09.jpg', 30, 45, 75, 5, '[{"id": "ing_lasagne_sheets", "quantity": {"value": 8.0, "unit": "unit"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_spinach", "quantity": {"value": 500.0, "unit": "bag of 250g"}}, {"id": "ing_ricotta", "quantity": {"value": 2.0, "unit": "tub of 250g"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.8, "unit": "pack of 125g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_nutmeg", "quantity": {"value": 0.625, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["8 - 10 fresh lasagne sheets (15 x 11 cm/6 x 4.5\") (Note 1)","1 cup mozarella cheese (, shredded)","1 tbsp olive oil (for drizzling later)"]},{"ingredients":["500g / 1 lb frozen spinach (pre chopped) (, thawed and excess water squeezed out (Note 2))","500 g / 1 lb ricotta cheese (NOT smooth, whipped or spreadable in tubs, Note 3)","1 cup mozzarella cheese (, shredded)","1 egg","1/2 cup parmesan cheese (, shredded)","1 garlic clove (, pressed using garlic crusher or finely grated)","1/8 tsp finely grated nutmeg (substitute nutmeg powder)","3/4 tsp salt","1/2 tsp Black pepper"],"purpose":"Filling"},{"ingredients":["2 tbsp olive oil","2 cloves garlic (, minced)","1/2 onion (, finely diced (brown, yellow, white))","3/4 tsp salt","1/2 tsp black pepper","700 g / 24 oz tomato passata (US: Tomato puree) (Note 5)","1 1/2 cups water","Handful basil leaves (optional)"],"purpose":"Tomato Sauce"}]', '[{"description":"Heat oil in a 25cm/10\" ovenproof skillet over medium high heat. (Note 6)","images":[],"step":1},{"description":"Add garlic and sauté for 10 seconds then add onion.","duration":0.16666666666666666,"images":[],"step":2},{"description":"Cook onion until translucent and starting to turn golden, then passata, water, chilli flakes (if using), salt and pepper.","images":[],"step":3},{"description":"Simmer for 5 minutes on medium low, then stir through basil. Should be quite thin - the lasagna sheets will absorb water while in the oven so sauce thickens alot in oven.","duration":5,"images":[],"step":4},{"description":"Scoop out 1 cup of the Tomato Sauce which will be used to drizzle over the dish at the end. Keep sauce warm.","images":[],"step":5},{"description":"Filling & Assembling:","images":[],"step":6},{"description":"Preheat oven to 180°C/350CF (all oven types)","images":[],"step":7},{"description":"Place Filling ingredients in a bowl. Mix well with wooden spoon.","images":[],"step":8},{"description":"As per the photo & video, lay out the lasagne sheet with the shorter end in front of you.","images":[],"step":9},{"description":"Place 1/3 cup (packed) of filling onto the lasagne sheet. Dab some water on the end furthest away from you (to seal the roll), then roll up starting from the end closest to you. Finish with the seal down.","images":[],"step":10},{"description":"Cut rolls into 3 (so each piece is 3.5cm/1.5\" wide). Place the rolls into the tomato sauce with the filling facing up.","images":[],"step":11},{"description":"Repeat with remaining lasagna sheets until all the Filling is used up.","images":[],"step":12},{"description":"Drizzle the reserved Tomato Sauce over (don''t cover completely, leave some exposed).","images":[],"step":13},{"description":"Cover loosely with foil, bake 30 minutes.","images":[],"step":14},{"description":"Remove from oven, remove foil. Drizzle with oil, top with mozzarella.","images":[],"step":15},{"description":"Bake 15 minutes or until the cheese is bubbly and golden and you''ve got some crunchy golden bits on the edges. Serve!","images":[],"step":16}]', '["egg","milk"]', '["gluten_free","high_protein","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["casseroles-and-cosy-bakes","italian-recipes","most-popular","one-pot-pasta-recipes","one-pot-recipes","pasta-bakes","pasta-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_00a5320dffe7', 'en', 'US', 'Creamy Pasta Bake "formula" - make this with ANYTHING!', 'Recipe video above. This is a "formula" using a creamy white sauce to make a pasta bake using anything you''ve got. Add in literally any meat, raw or cooked, any vegetable (frozen, canned, dried, fresh, pickled). Canned tuna or salmon, bacon, ham, chorizo. You''re only limited by your imagination! (Eer - and what''s in your pantry 😂) If using raw meat and veg that needs to be cooked, cook them first then make the sauce in the same pot. If using add ins like canned salmon and corn that do not need pre cooking, just make the sauce and mix it up with the pasta, then bake until bubbly and golden! See above in post for combination suggestions.', 'https://www.recipetineats.com/tachyon/2020/03/Creamy-pasta-bake-make-with-anything-1.jpg', 15, 40, 55, 8, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 1.25, "unit": "L"}}, {"id": "ing_stock_bouillon_cube_or_powder", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_parmesan", "quantity": {"value": 0.375, "unit": "pack of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}]', '[{"ingredients":["500g / 1lb pasta (any short or long except risoni/orzo) (Note 1)","1 tbsp salt (for water)"]},{"ingredients":["4 tbsp (60g) butter (, unsalted)","2 garlic cloves (, minced (optional, sub 1 tsp powder))","5 tbsp flour (, any (GF option Note 2))","5 cups (1.25 litres) milk (, any fat, any type)","2 tsp stock / bouillon cube or powder (, chicken or veg)","3/4 cup (75g) parmesan","1/2 tsp black pepper"],"purpose":"Creamy Sauce (Note 2 for subs)"},{"ingredients":["1 tsp EACH thyme and parsley (, or any other dried herbs)","1/2 tsp EACH mustard, garlic, onion powder"],"purpose":"Choose ONE flavouring (optional)"},{"ingredients":["8 cups Add Ins - raw or cooked meats, bacon, ham, diced vegetabes (frozen, canned, fresh), canned or fresh fish (Note 3)"],"purpose":"Add Ins"},{"ingredients":["1 tbsp olive oil","Salt and pepper"],"purpose":"For Cooking RAW Add Ins (like raw chicken, mushrooms, zucchini)"},{"ingredients":["2 cups (200g) cheese (, shredded (Note 4))"],"purpose":"Cheesy Topping"}]', '[{"description":"Preheat oven to 180°C/350°F.","images":[],"step":1},{"title":"Pasta","description":"Boil water with 1 tbsp salt. Add pasta, bring back up to boil then cook per packet directions MINUS 2 minutes. Should be just cooked, still slightly firm in middle. Drain, return to pot.","images":[],"step":2},{"description":"Cooking RAW Meat & Vegetables","images":[],"step":3},{"description":"Heat half butter & 1 tbsp oil in a large pot over high heat. Stir in garlic for 10 seconds, then cook your raw meat and vegetables with a sprinkle of salt and pepper. Meat must be fully cooked - will not cook further in oven.","duration":0.16666666666666666,"images":[],"step":4},{"description":"Add remaining butter, melt. Mix in flour, then follow Creamy Sauce step 2 onwards.","images":[],"step":5},{"description":"Start here if you have NO COOK Add Ins (like canned tuna): Melt butter in large saucepan over medium heat. Add garlic and stir for 10 seconds, then stir in flour.","duration":0.16666666666666666,"images":[],"step":6},{"description":"While mixing, gradually pour in about 1/3 of the milk. Once the flour-butter mixture is incorporated into the milk, pour in remaining milk and mix.","images":[],"step":7},{"description":"Add remaining milk, stock powder, parmesan, pepper and herbs (if using) and mix. When the milk starts to heat up, mix constantly to make sure the white sauce doesn’t catch on the base.","images":[],"step":8},{"title":"After 4","description":"5 minutes, the sauce should be thick enough that you can draw a path across the back of a spoon (see video).","images":[],"step":9},{"description":"Assemble & Bake","images":[],"step":10},{"description":"Return cooked pasta into pot. Mix with sauce and no-cook Add Ins.","images":[],"step":11},{"description":"Spread in large casserole dish, top with cheese and bake 25 minutes until golden and bubbly. Serve!","images":[],"step":12}]', '["fish","gluten","milk","mustard"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["casseroles-and-cosy-bakes","coronavirus-food","pasta-bakes","pasta-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d80d8f8b199f', 'en', 'US', 'Emergency Chicken Rice Casserole', 'Recipe video above. Dump-and-bake creamy chicken rice casserole made FROM SCRATCH! Perfectly cooked rice, creamy cheesy sauce, juicy seasoned chicken. Unusually high liquid-to-rice ratio because 1) baked uncovered (brown chicken); and 2) creamy rice (rather than stodgy!). See Note 7 re: SCALING recipe!', 'https://www.recipetineats.com/tachyon/2019/08/Ultra-Lazy-Chicken-Rice-Casserole_6.jpg', 10, 45, 55, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.003, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.625, "unit": "L"}}, {"id": "ing_white_rice", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_broccoli", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.04, "unit": "bunch"}}]', '[{"ingredients":["500g (1 lb) chicken thighs or tenders (tenderloin) (, cut into 1.5cm / 2/3\" pieces (Note 1))","1/2 tsp dried thyme","1 tsp garlic powder","1/2 tsp pepper","1/2 tsp vegetable or chicken stock powder (granulated bouillon) (Note 2)","1 tbsp olive oil"],"purpose":"Chicken:"},{"ingredients":["2 1/2 cups (625 ml) chicken broth/stock (, low sodium)","2 1/2 cups (625 ml) milk (, any fat %)","1 1/2 cups long grain white rice (, uncooked (Note 3))","1/4 cup (35g) flour (, plain / all purpose)","1 tsp vegetable or chicken stock powder (granulated bouillon) (Note 2)","2 cloves garlic (, minced)","2 tbsp (30g) unsalted butter","2 broccoli heads (large!), cut into florets (Note 4)","2 cups (200g) shredded cheese"],"purpose":"Rice:"},{"ingredients":["2 green onions (, finely sliced)"],"purpose":"Garnish:"}]', '[{"description":"Preheat oven to 190°C/375°F (180°C/350°F fan/convection).","images":[],"step":1},{"description":"Mix Chicken Ingredients.","images":[],"step":2},{"description":"Heat chicken broth and milk until hot using any method (stove, microwave). Can combine together in saucepan. (Note 5)","images":[],"step":3},{"description":"Spread rice in 23 x 33cm / 9 x 13\" ceramic or glass baking dish. (Note 6)","images":[],"step":4},{"description":"Sprinkle with flour, stock powder and garlic.","images":[],"step":5},{"description":"Add the hot chicken broth, stir until flour dissolved (some small lumps ok).","images":[],"step":6},{"description":"Add milk, swish rice to spread out evenly.","images":[],"step":7},{"description":"Spread broccoli on top, then chicken, then plonk butter on (anywhere).","images":[],"step":8},{"description":"Bake uncovered for 40 minutes. (Might get some browned skin on surface, that''s ok)","duration":40,"images":[],"step":9},{"title":"CHECK rice before stirring","description":"should be JUST cooked (Note 7).","images":[],"step":10},{"description":"Add half the cheese, stir through, being sure to get rice in the corners and edges of pan. Should be creamy and quite loose (see video).","images":[],"step":11},{"description":"Top with cheese, return to oven for 5 minutes until just melted.","duration":5,"images":[],"step":12},{"description":"Sprinkle with green onion, if using, then serve!","images":[],"step":13}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["casseroles-and-cosy-bakes","chicken-recipes","dinner-tonight","emergency-recipes","quick-and-easy","rice-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c73ad1b37efa', 'en', 'US', 'Spinach & Ricotta Pasta Bake', 'Recipe video above. A lazy meal for midweek that tastes like spinach and ricotta stuffed shells or cannelloni - but without all the labour! Feel free to use your favourite store bought pasta sauce if you prefer. Reheats well and freezes well too!', 'https://www.recipetineats.com/tachyon/2015/09/Spinach-Ricotta-Pasta-Bake_6.jpg', 15, 40, 55, 6, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.6, "unit": "pack of 500g"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.2, "unit": "pack of 125g"}}, {"id": "ing_ricotta", "quantity": {"value": 1.814, "unit": "tub of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_spinach", "quantity": {"value": 350.0, "unit": "bag of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.007, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_italian_mixed_herbs", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_chilli", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}]', '[{"ingredients":["300g / 10 oz ziti pasta, (uncooked, or other short pasta of choice)","1 1/2 cups mozzarella cheese (, shredded (or more! For topping))"]},{"ingredients":["1 lb / 500 g ricotta (Note 1)","1/2 cup parmesan cheese (, grated)","2 garlic cloves (, crushed)","350g / 12oz frozen chopped spinach, (thawed and excess liquid pressed out )","1 cup mozzarella cheese (, shredded)","3/4 tsp salt & pepper"],"purpose":"Ricotta Mixture"},{"ingredients":["1 tbsp extra virgin olive oil","2 garlic cloves (, minced)","700g / 24oz tomato passata (1 standard bottle) (Note 2)","1 tsp EACH onion and garlic powder","2 tsp dried Italian Mixed Herbs (Note 3)","1/2 tsp dried chili flakes (, to taste (optional))","1 tsp sugar","1 tsp salt","Black pepper","2 tbsp water (if needed)"],"purpose":"Shortcut Pasta Sauce"},{"ingredients":["Parmesan cheese (, grated)"],"purpose":"To Serve"}]', '[{"description":"Preheat oven to 350F/180C.","images":[],"step":1},{"title":"Pasta Sauce","description":"Pour out about 1/4 cup of the passata (to make room to add flavourings). Add the remaining Pasta Sauce ingredients into the bottle, screw the lid on and give it a shake.","images":[],"step":2},{"description":"Cook pasta for time per packet MINUS 1 minute.","images":[],"step":3},{"description":"SCOOP OUT 1 mugful pasta cooking water, drain and set aside.","images":[],"step":4},{"title":"Ricotta Mixture","description":"Mix Ricotta Mixture ingredients in a very large bowl. Use a splash of pasta cooking water if needed to make it creamy.","images":[],"step":5},{"description":"Add pasta and stir to combine. Transfer to a heatproof baking dish.","images":[],"step":6},{"description":"Top with Pasta Sauce, top with cheese. Loosely cover with foil.","images":[],"step":7},{"description":"Bake for 25 minutes, then remove the cover and bake for a further 10 minutes or until the cheese is melted and bubbly.","duration":25,"images":[],"step":8},{"description":"Serve while hot and fresh!","images":[],"step":9}]', '["gluten","milk"]', '["high_protein","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Dinner"],"categories":["casseroles-and-cosy-bakes","dinner-tonight","main-dishes","pasta-bakes","pasta-recipes","quick-and-easy","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a5140d9f013b', 'en', 'US', 'Vegetable Lasagna', 'Recipe VIDEO above. Layered with roasted vegetables, spinach and ricotta, a homemade sauce and as much cheese as you see fit, this big batch vegetarian lasagna reheats brilliantly. Epic meat-free food for carnivores!', 'https://www.recipetineats.com/tachyon/2019/02/Vegetable-Lasagna_10.jpg', 25, 50, 75, 8, '[{"id": "ing_pumpkin", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_zucchini", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_spinach", "quantity": {"value": 250.0, "unit": "bag of 250g"}}, {"id": "ing_ricotta", "quantity": {"value": 2.0, "unit": "tub of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_rated_nutmeg_optional", "quantity": {"value": 75.0, "unit": "jar"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.075, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.825, "unit": "jar of 50g"}}, {"id": "ing_lasagne_sheets", "quantity": {"value": 375.0, "unit": "unit"}}, {"id": "ing_mozzarella", "quantity": {"value": 2.4, "unit": "pack of 125g"}}]', '[{"ingredients":["500 g / 1 lb pumpkin (, 2cm / 4/5\" cubes)","2 large zucchinis (, cut into 2cm / 4/5\" chunks)","2 onions (any type) (, cut into wedges)","2 tbsp olive oil","1 garlic clove (, minced)","Salt and pepper"],"purpose":"Roasted Vegetables (Note 1):"},{"ingredients":["250 g / 8 oz frozen chopped spinach (, thawed)","500 g / 1 lb ricotta (Note 2)","1/2 cup / 50 g grated parmesan (or 3/4 cup shredded cheese)","1 egg","1 garlic clove (, minced)","1/8 tsp grated nutmeg, optional (fresh or powder)","1/2 tsp each Salt and pepper"],"purpose":"Spinach Ricotta:"},{"ingredients":["1 tbsp olive oil","1 garlic clove","1 small onion (, finely chopped (any, I use brown))","700 g / 24 oz tomato passata (Note 3)","400 g / 14 oz crushed tomato","1/2 cup / 125 ml water","3/4 tsp each dried thyme and oregano (or basil, parsley)","1/2 tsp dried chilli flakes (can omit / adjust to taste)","Salt and pepper"],"purpose":"Sauce:"},{"ingredients":["330g / 11 oz jar roasted red pepper strips, drained (Note 4)","375 g / 13 oz fresh lasagne sheets (Note 5)","300 g / 3 cups shredded mozzarella (or MORE!)"],"purpose":"Lasagna:"}]', '[{"description":"Roasted Vegetables:","images":[],"step":1},{"description":"Preheat oven to 200C/390F.","images":[],"step":2},{"description":"Place vegetables on the tray, drizzle with oil, sprinkle with garlic, salt and pepper. Toss.","images":[],"step":3},{"description":"Roast for 25 minutes, turning at 15 minutes, until tender and browned.","duration":25,"images":[],"step":4},{"description":"Remove from oven, loosen from tray with spatula while warm (can stick when cools).","images":[],"step":5},{"description":"Heat oil in a skillet over medium high heat. Add garlic and onion, cook for 3 minutes until golden.","duration":3,"images":[],"step":6},{"description":"Add passata, crushed tomato, water, dried herbs, chilli, salt and pepper. Stir. Simmer on medium low heat for 20 minutes. Adjust salt at the end. *Add a teeny touch of sugar if it''s a bit sour, depends on quality of tomatoes used.*","duration":20,"images":[],"step":7},{"description":"Remove from stove and let cool for 5 minutes before using.","duration":5,"images":[],"step":8},{"description":"Ricotta Mixture:","images":[],"step":9},{"description":"Place ingredients in a bowl and mix until combined.","images":[],"step":10},{"description":"Preheat oven to 160C/320F.","images":[],"step":11},{"description":"Spread a ladle of tomato sauce on the base of a large baking dish (Note 5).","images":[],"step":12},{"description":"Cover with lasagna sheets, tearing as required to fit.","images":[],"step":13},{"description":"Top with roasted vegetables, scatter over red peppers. Spoon over 2 1/2 cups of Sauce, then sprinkle with half the cheese.","images":[],"step":14},{"description":"Cover with lasagna sheets. Spread over Ricotta mixture.","images":[],"step":15},{"description":"Cover with lasagna sheets. Pour over remaining sauce and sprinkle with remaining cheese.","images":[],"step":16},{"title":"Bake for 25","description":"30 minutes or until the cheese is golden. If using dried lasagna sheets, stick a knife in the middle to ensure it''s cooked - if it needs longer, cover and stick it back in the oven.","duration":27.5,"images":[],"step":17},{"description":"Rest for 5 minutes before cutting and serving. Store leftovers per notes - brilliant reheated!","duration":5,"images":[],"step":18}]', '["egg","milk"]', '["gluten_free","high_protein","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["casseroles-and-cosy-bakes","pasta-bakes","pumpkin","sunday-supper","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_858ea012e9f7', 'en', 'US', 'Garlic Shrimp Mac and Cheese (Prawns)', 'Recipe video above. Plump, juicy garlicky shrimp WITH a silky creamy, cheesy macaroni AND a crunchy parmesan topping?? Be still my beating heart. BONUS: It''s all made in ONE POT!', 'https://www.recipetineats.com/tachyon/2018/12/Shrimp-Mac-and-Cheese_7.jpg', 7, 15, 22, 6, '[{"id": "ing_shrimp", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.625, "unit": "L"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.6, "unit": "pack of 125g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.013, "unit": "jar of 200g"}}, {"id": "ing_bread", "quantity": {"value": 0.062, "unit": "loaf"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}]', '[{"ingredients":["500 g / 1 lb peeled shrimp/prawns (Note 1)","3 garlic cloves (, finely chopped)","1 tbsp olive oil","50 g / 3.5 tbsp unsalted butter (, divided)","3 tbsp / 30g flour (, plain / all purpose)","2 cups / 500ml milk (, preferably warmed (Note 2))","2.5 cups hot tap water","250 g / 8 oz elbow macaroni (, uncooked (2.5 cups))","1.5 cups (150g) cheese (Cheddar, gruyere, or other), freshly grated (Note 3)","3/4 cup (75g) mozzarella cheese (, freshly grated (Note 3))"]},{"ingredients":["3/4 tsp salt","1/4 tsp pepper","1 tsp garlic powder","1/2 tsp mustard powder"],"purpose":"Seasonings:"},{"ingredients":["1/3 cup panko breadcrumbs","1/4 cup grated parmesan","1 tbsp olive oil"],"purpose":"Parmesan Breadcrumb Topping:"}]', '[{"description":"Preheat broiler/grill on high.","images":[],"step":1},{"description":"Mix together Breadcrumb Topping.","images":[],"step":2},{"description":"Heat oil and melt 1 tbsp butter in a large, deep skillet or heatproof pot on the stove over high heat.","images":[],"step":3},{"description":"Add shrimp, sprinkle with pepper, then cook for 1 minute. Add garlic and cook for another minute until the shrimp has changed colour but not fully cooked.","duration":1,"images":[],"step":4},{"description":"Transfer to bowl. Turn heat down to medium.","images":[],"step":5},{"description":"Melt remaining butter. Add flour and cook for 1 minute.","duration":1,"images":[],"step":6},{"description":"Pour milk in slowly, stirring as you go. Once incorporated and lump free (use whisk if needed), stir in Seasonings, then water.","images":[],"step":7},{"description":"Once the liquid is hot, add macaroni. Cook for 8 minutes, stirring regularly, until macaroni is almost cooked through, then take it off the stove.","duration":8,"images":[],"step":8},{"description":"Add cheeses and stir through, then add shrimp. Taste for salt - tweak if needed. It should be saucy (see video) - it gets absorbed. Should still be saucy at this stage - sauce gets absorbed/thickens more in next step.","images":[],"step":9},{"description":"Sprinkle over breadcrumbs, then place under the hot grill for just 2 - 3 minutes until the top is golden.","images":[],"step":10},{"description":"Sprinkle with parsley if desired and served immediately!","images":[],"step":11}]', '["gluten","milk","mustard","shellfish"]', '["high_protein"]', '{"mealType":["main_course"],"cuisine":[],"categories":["casseroles-and-cosy-bakes","dinner-tonight","easter-mains-fish-seafood","easter-sides-warm-hearty","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","prawns-shrimp","quick-and-easy","seafood-recipes","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_87f43efb79bf', 'en', 'US', 'SPICY ITALIAN CHICKEN CASSEROLE', 'Juicy chicken with crispy skin in a spicy tomato sauce with bell peppers, olives and capers. Inspired by Mario Batali’s Sicilian Chicken (but more sauce!). Feel free to dial back the spiciness. Made on the stove, this is a hearty dinner on the table in 30 minutes. Recipe VIDEO below.', 'https://www.recipetineats.com/tachyon/2017/10/Spicy-Italian-Chicken-1.jpg', 10, 20, 30, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.185, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_black_olives", "quantity": {"value": 112.5, "unit": "bottle"}}, {"id": "ing_baby_capers", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["5 chicken thighs , skin on, bone in (about 200g / 7 oz each) (Note 1 for breast)","Salt and pepper","2 tsp olive oil","2 garlic cloves (, minced)","1 medium onion (, finely chopped)","1 EACH red and green capsicum / bell pepper (, sliced)","½ cup / 125 ml white or red wine (any is fine, I use dry white) (Note 2 for subs)","800 g / 28 oz can crushed tomato","¾ cup / 185 ml water (, swilled in empty tomato can)","1 tsp red pepper flakes ((chilli flakes), adjust to taste)","3/4 cup black olives (, pitted (or 1/3 cup sliced))","2 tbsp baby capers","Salt and pepper to taste","¼ cup finely chopped parsley"]}]', '[{"description":"Use a small knife to prick 5 or so gashes into the skin of the chicken. Sprinkle each side with salt and pepper.","images":[],"step":1},{"description":"Place chicken skin side down in a cold large non stick skillet, then turn stove onto medium high. As it heats up, the fat under the skin will start to melt through the holes in the skin.","images":[],"step":2},{"title":"Cook for 4","description":"5 minutes or until the skin is golden and crispy. Turn the chicken and cook the other side for 3 minutes.","duration":4.5,"images":[],"step":3},{"description":"Remove chicken onto a plate, discard fat (don’t scrape the pan) then return to the stove.","images":[],"step":4},{"description":"Add oil, garlic and onion. Cook for 1 minute, then add capsicum. Cook for 2 minutes then add wine. Bring to a simmer and stir, scraping the pan to get those golden bits mixed in.","duration":1,"images":[],"step":5},{"description":"Once most of the wine is evaporated and it doesn’t smell winey anymore, add the tomato, water and pepper flakes. Stir, bring to a simmer, adjust heat so it’s bubbling energetically but not rapidly (and not slowly).","images":[],"step":6},{"description":"After 5 minutes (or so), stir through olives and capers. Taste the sauce and add salt and pepper.","images":[],"step":7},{"description":"Then place chicken into the sauce, being careful not to submerge the skin. Cook for another 5 minutes.","images":[],"step":8},{"description":"Sprinkle over parsley. Serve with crusty bread, or use half the sauce to toss through / pour over pasta and the other half to serve with chicken (see photos in post).","images":[],"step":9}]', '[]', '["gluten_free"]', '{"mealType":["main_course"],"cuisine":[],"categories":["casseroles-and-cosy-bakes","chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","italian-recipes","main-dishes","quick-and-easy","stews","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_27b2c3b8bbe3', 'en', 'US', 'Spinach Ricotta Cannelloni', 'Recipe VIDEO above. Juicy, perfectly seasoned spinach and ricotta filling inside cannelloni pasta tubes, topped with a simple, tasty tomato sauce and melted cheese. Great for freezing!First published in September 2017, this reader favourite recipe is included by popular demand in my debut cookbook Dinner. I took the opportunity to make it even better by increasing the volume and thinning the thickness of the sauce so there''s plenty of liquid to cook the cannelloni but it''s still saucy when you serve it up. It was great before, it''s AMAZING now!', 'https://www.recipetineats.com/tachyon/2017/09/Spinach-Ricotta-Cannelloni-1-copy-1.jpg', 25, 35, 60, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_tomato", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_wine", "quantity": {"value": 0.111, "unit": "bottle of 750ml"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.033, "unit": "jar of 50g"}}, {"id": "ing_basil", "quantity": {"value": 0.4, "unit": "bunch"}}, {"id": "ing_spinach", "quantity": {"value": 250.0, "unit": "bag of 250g"}}, {"id": "ing_ricotta", "quantity": {"value": 2.0, "unit": "tub of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_nutmeg", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_cannelloni_tubes", "quantity": {"value": 18.0, "unit": "unit"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.8, "unit": "pack of 125g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}]', '[{"ingredients":["2 tbsp olive oil","1 onion (, finely chopped)","4 garlic clove (, minced)","1 bay leaf (, fresh (sub dried))","1/2 tsp each dried thyme and oregano","1/3 cup tomato paste","800 g / 28 oz canned crushed tomato","4 cups vegetable or chicken stock/broth (, low sodium)","1/3 cup Chardonnay or other dry white wine (sub more stock)","3/4 tsp salt","1 1/2 tsp sugar","1/3 tsp black pepper","2/3 cup basil leaves (, roughly torn (recommended but not critical))"],"purpose":"Sauce (you need LOTS!):"},{"ingredients":["250 g / 8 oz frozen chopped spinach (, thawed (Note 1))","500 g / 1 lb ricotta (, full fat please (Note 2))","1/3 cup parmesan (, finely shredded)","1 cup shredded cheese (Mozzarella, Colby, Cheddar, Tasty, Gruyere, Swiss)","1 egg","1 large garlic clove (, minced)","Grated fresh nutmeg (just a sprinkling) ( or 1/8 tsp nutmeg powder (optional))","3/4 tsp cooking / kosher salt","1/2 tsp black pepper"],"purpose":"Filling:"},{"ingredients":["18 - 22 dried cannelloni tubes (250g pack) (or 14 manicotti tubes (8.8 oz) (Note 3))","1/3 cup parmesan (, finely shredded)","1 1/4 cups shredded Mozzarella","More basil and parmesan (, for garnish (optional))"],"purpose":"Cannelloni"}]', '[{"title":"Sauté","description":"Heat oil in a small pot over medium high heat. Add garlic, onion, bay leaf, thyme and oregano. Cook for 3 - 4 minutes until the onion is translucent. Add tomato paste and cook for 1 minute.","duration":3.5,"images":[],"step":1},{"title":"Reduce wine","description":"Add wine, increase heat to high and let it simmer rapidly until mostly evaporated (about 2 minutes).","images":[],"step":2},{"title":"Simmer","description":"Add tomatoes, stock, sugar, salt and pepper. Stir then simmer on medium low for 20 minutes.","duration":20,"images":[],"step":3},{"title":"Blitz","description":"Remove bay leaf then blitz with a stick blender until smooth. Simmer for 1 more minute then remove from the stove","images":[],"step":4},{"title":"Basil","description":"Stir in basil then cover to keep warm until required.","images":[],"step":5},{"title":"Squeeze spinach","description":"Place spinach in a colander and press out most of the liquid (don''t need to thoroughly squeeze dry).","images":[],"step":6},{"title":"Mix filling","description":"Place Spinach in bowl with remaining Filling ingredients. Mix, taste, adjust salt and pepper to taste (different cheeses have different saltiness).","images":[],"step":7},{"description":"Assemble & Bake:","images":[],"step":8},{"description":"Preheat oven to 180°C/350°F (160°C fan).","images":[],"step":9},{"title":"Pan","description":"Choose a baking pan which will comfortably fit about 20 cannelloni - mine is 21 x 26 cm / 8.5 x 10.5\".","images":[],"step":10},{"title":"Smear","description":"Spread 1 cup of Sauce on the base (stops cannelloni from sliding around).","images":[],"step":11},{"title":"Fill tubes","description":"Transfer Filling to a piping bag with a large nozzle (that fits in the tubes), or use a strong ziplock bag. Or do this step using a knife (it''s a bit tedious though!). Pipe the filling into the tubes.","images":[],"step":12},{"title":"Assemble","description":"Place cannelloni in baking dish. Pour over remaining Sauce, covering all the tubes.","images":[],"step":13},{"title":"Bake covered (but naked)","description":"Cover with foil, then bake for 30 minutes.","duration":30,"images":[],"step":14},{"description":"Cheese it! Remove foil, scatter over parmesan then mozzarella. Return to oven for 15 minutes until cheese is melted.","duration":15,"images":[],"step":15},{"description":"Serve, garnished with extra parmesan and basil if desired.","images":[],"step":16}]', '["egg","milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["American-Italian","Western"],"categories":["casseroles-and-cosy-bakes","dinner-tonight","italian-recipes","main-dishes","pasta-bakes","pasta-recipes","sunday-supper","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_925a38cdaefc', 'en', 'US', 'Creamy Seafood Pasta Bake', 'Pasta baked with mixed seafood in a creamy white béchamel sauce. It''s like a gratin made with pasta - which is why I describe this as French-ish! The key to getting gorgeous flavour in the sauce is searing the seafood in the skillet first, then making the sauce in the same skillet to soak up all those seafood flavours!', 'https://www.recipetineats.com/tachyon/2016/06/Seafood-Gratin-Pasta_10.jpg', 5, 30, 35, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.397, "unit": "pack of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_mixed_seafood", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_eek", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.625, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_panko", "quantity": {"value": 112.5, "unit": "jar"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["7 oz / 200 g macaroni or other pasta of choice","1 1/2 tbsp olive oil (, separated)","1 lb / 500 g mixed raw seafood (Marinara seafood mix) (Note 1)","2 leeks (, white and pale green part only finely sliced)","2 garlic cloves (, minced)"]},{"ingredients":["3 tbsp butter","3 tbsp flour","2 1/2 cups milk","1 chicken bouillon cube ((or 1 1/2 tsp chicken stock powder) OR 1/2 cup grated parmesan cheese)"],"purpose":"White Sauce"},{"ingredients":["3/4 cup panko","1/4 cup grated parmesan cheese (high recommended)","Finely chopped fresh parsley (optional)"],"purpose":"Topping"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Cook pasta according to packet directions. Drain and pour into baking dish.","images":[],"step":2},{"description":"Heat 1 tbsp oil in a skillet over very high heat. Add seafood and sear for 30 seconds, turn then sear the other side for 30 seconds (should still be raw inside). Remove into baking dish.","duration":0.5,"images":[],"step":3},{"description":"Return pan to stove, add remaining 1/2 tbsp oil and turn down to medium. Cook leeks and garlic for 3 minutes or until soft. Add to baking dish.","duration":3,"images":[],"step":4},{"description":"Mix pasta, seafood and leeks together in the baking dish.","images":[],"step":5},{"description":"Melt butter in the skillet. Add flour and mix into the butter. Cook for 1 minute,","duration":1,"images":[],"step":6},{"title":"Add 1 cup of milk and use a whisk to combine","description":"it will thicken quickly. Add remaining milk and bouillon cube (crumbled) and whisk to combine. Cook, whisking occasionally at first then constantly as it thickens, for around 5 minutes or until the sauce is thick enough to coat the back of a wooden spoon (see photo in post). Season with salt and pepper.","images":[],"step":7},{"description":"Pour into the baking dish. Top with panko and parmesan.","images":[],"step":8},{"title":"Bake for 20","description":"25 minutes, or until the top is golden.","duration":22.5,"images":[],"step":9},{"description":"Rest for 5 minutes before serving, garnished with fresh parsley if desired.","duration":5,"images":[],"step":10},{"description":"I served this with garlic spinach (Note 2).","images":[],"step":11}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["French-ish"],"categories":["casseroles-and-cosy-bakes","dinner-tonight","easter-mains-fish-seafood","main-dishes","pasta-bakes","prawns-shrimp","seafood-recipes","sunday-supper","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3b649b6d9511', 'en', 'US', 'One Pot Chicken Enchilada Rice Casserole', 'Everything you know and love about the flavour of Chicken Enchiladas.....but in the form of a rice casserole! And all made in ONE POT on the stove! I like the flow of this recipe because you don''t need to measure everything out in advance. After cooking the bell pepper (capsicum) add the passata and chicken broth, then while that comes to a simmer you can gather all the spices. Saves time! This recipe makes a LOT. Because it is carb heavy, I think it is enough to feed 6.', 'https://www.recipetineats.com/tachyon/2015/10/Mexican-Chicken-Enchilada-Rice-Casserole_600px.jpg', 15, 25, 40, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.68, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 0.562, "unit": "can of 400g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 1.0, "unit": "jar of 50g"}}, {"id": "ing_white_rice", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}]', '[{"ingredients":["1 tbsp olive oil","400g (13oz) chicken breast, about 1/3\"/1cm thick, sliced horizontally into thin steaks (Note 1)","1 small onion, diced","3 cloves garlic, crushed","1 red bell pepper/capsicum, diced","680g (24oz) tomato passata or crushed canned tomatoes* (Note 2)","3 cups chicken broth or water (750ml)","1 1/2 cups frozen corn (250g)","1/2 tsp cayenne pepper* (spicy - adjust to taste)","1 tbsp dried oregano*","2 tsp cumin*","1 1/2 tsp coriander*","2 tsp onion powder*","1 tbsp brown sugar*","Salt and pepper","1 1/2 cups (270g) white rice (short, medium or long grain (, uncooked (Note 4))","1 - 1 1/2 cups grated cheese (about 125 - 150 g)"]},{"ingredients":["Chopped cilantro/coriander (optional)"],"purpose":"To Serve"}]', '[{"description":"Heat olive oil over medium high heat in large skillet.","images":[],"step":1},{"description":"Add chicken and cook each side for 2 minutes or until cooked, then remove onto a plate.","duration":2,"images":[],"step":2},{"description":"Add extra oil if the skillet is looking dry. Add onion and garlic, cook for 1 1/2 minutes until starting to soften.","images":[],"step":3},{"description":"Add bell peppers and cook for a further 2 minutes.","images":[],"step":4},{"description":"Add remaining ingredients except rice and cheese. Bring to simmer, then add rice.","images":[],"step":5},{"description":"Stir, cover with a lid and turn down heat to medium low. Cover and cook until rice is cooked but not mushy and most of the liquid is absorbed - about 15 to 18 minutes. (Note 3). Do not stir while it cooks.","images":[],"step":6},{"description":"Meanwhile, shred or roughly chop chicken.","images":[],"step":7},{"description":"When rice is cooked, quickly stir chicken through, sprinkle with cheese then pop under broil / grill until golden and bubbly.","images":[],"step":8},{"description":"Serve, garnished with fresh cilantro/coriander if desired.","images":[],"step":9}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Tex-Mex"],"categories":["casseroles-and-cosy-bakes","chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","mexican-recipes","most-popular","one-pot-recipes","quick-and-easy","rice-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f16048e380e6', 'en', 'US', 'One Pot Creamy Tomato Chicken Pasta Bake (no cream)', 'A pasta bake, cooked entirely in one pot! The sauce is creamy and tomatoey but is made without a drop of cream, making this a great midweek meal.', 'https://www.recipetineats.com/tachyon/2015/04/One-Pot-Creamy-Tomato-Pasta-Bake_action_680px1.jpg', 5, 30, 35, 6, '[{"id": "ing_butter", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.09, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.9, "unit": "pack of 500g"}}, {"id": "ing_chicken", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.6, "unit": "pack of 125g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["4 tbsp unsalted butter","1 small onion (, diced)","2 garlic cloves (, minced)","6 tbsp / 1/2 cup plain flour","2 cups milk (500ml)","2 cups tomato passata (500ml) (Note 1)","1 cup water (or chicken or vegetable broth) (250ml)","2 tsp salt","Black pepper","3 cups dried ziti / penne pasta (uncooked)","2 cups shredded cooked chicken","1 cup shredded cheddar cheese","3/4 cup shredded mozzarella cheese","Pepper"]},{"ingredients":["Fresh basil leaves","Freshly grated parmesan"],"purpose":"Garnish (optional)"}]', '[{"description":"Preheat oven to 350F/180C.","images":[],"step":1},{"description":"Melt butter in a deep fry pan or skillet (Note 2) over medium heat. Add the onion and garlic and sauté for 5 minutes until translucent. Add the flour and stir to combine, then cook for 2 minutes.","duration":5,"images":[],"step":2},{"description":"Add the milk and whisk for 1 minute, in small circles around the fry pan, until it starts to thicken. Then add the tomato passata, water, salt and pepper. Increase the heat to medium high and cook for around 5 minutes or until thick enough to coat the back of a metal spoon (see photo below). Whisk occasionally for the first 3 minutes, then whisk constantly for the last 2 minutes.","duration":1,"images":[],"step":3},{"description":"Do a taste test and add 1 to 2 tsp of sugar if it is a bit sour (depends on quality of passata you use).","images":[],"step":4},{"description":"Add the ziti/penne, chicken and cheddar cheese and mix through. Leave it to cook for around 1 minute on the stove, then take it off the stove.","images":[],"step":5},{"description":"Scatter with mozzarella cheese. Cover with a lid or foil (Note 3) and bake for 10 minutes. Remove the lid/foil and bake for a further 5 minutes. Rest for 5 minutes before serving, garnished with fresh basil leaves and grated parmesan, if desired.","duration":10,"images":[],"step":6}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["casseroles-and-cosy-bakes","chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","pasta-bakes","pasta-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_586b6f157e9b', 'en', 'US', 'Baked One Pot Mac and Cheese', 'If you like your Mac and Cheese with plenty of creamy, cheesy sauce, then this is the recipe for you. Added bonus: all made in one pot and not a drop of cream!', 'https://www.recipetineats.com/tachyon/2015/01/One-Pot-Mac-and-Cheese-1-Version-2.jpg', 5, 20, 25, 5, '[{"id": "ing_butter", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.09, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.454, "unit": "pack of 500g"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_bread", "quantity": {"value": 0.047, "unit": "loaf"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}]', '[{"ingredients":["4 tbsp unsalted butter","6 tbsp flour","3 cups of milk (full or low fat - I used low fat)","2 cups of water","1 tsp salt (Note 1)","Black pepper","1/2 lb / 250g dried macaroni (elbow pasta) (Note 2)","2 cups (150g / 5oz) grated tasty or cheddar cheese (or any sharp, flavoured cheese that melts well)","1 cup (75g / 2.5 oz) grated provolone dolce cheese (or mozzarella or other mild flavoured good melting cheese) (Note 3)"]},{"ingredients":["1/4 cup panko breadcrumbs (or ordinary breadcrumbs)","1/4 cup parmesan cheese (, grated)","1/2 tbsp fresh parsley (, finely chopped (optional))"],"purpose":"Topping"}]', '[{"description":"Preheat the oven to 180C/350F.","images":[],"step":1},{"description":"Melt the butter in a deep fry pan or skillet (Note 4) over medium heat. (Note 5)","images":[],"step":2},{"description":"Add the flour and stir until combined so a thick paste forms (\"roux\"). Cook, stirring constantly, for 1 minute.","duration":1,"images":[],"step":3},{"description":"Add half the milk and use a whisk to dissolve the roux into the milk. It will thicken quickly, then add the remaining milk. Whisk in small circles, rotating around the pan, to dissolve all the roux into the milk.","images":[],"step":4},{"description":"Add the water, salt and 5 grinds of pepper, then turn the heat up to medium high. Whisk leisurely so the bottom doesn''t stick to the pan. When the white sauce starts to steam and thickens such that you can see it coating the edges of the pan (around 2 to 3 minutes), add the macaroni.","images":[],"step":5},{"description":"Turn the heat down to medium and stir gently with a wooden spoon to mix the macaroni through and ensure the bottom doesn''t stick. Cook it for 1 minute. Be sure not to cook it for longer than this after adding the macaroni - this really impacts the \"sauciness\" of the dish and ensuring the macaroni isn''t overcooked.","duration":1,"images":[],"step":6},{"description":"Cover the fry pan (Note 6), then transfer it immediately to the oven on the middle shelf.","images":[],"step":7},{"description":"Bake for 12 minutes, then remove from the oven. It will seem like there is too much sauce but it reduces and thickens in the next steps. The pasta should be just cooked (al dente). It will continue cooking from the residual heat.","duration":12,"images":[],"step":8},{"description":"Turn the oven off and turn the grill/broiler on high.","images":[],"step":9},{"description":"Stir through the cheese, just enough to disperse it through the macaroni. As you stir, this will melt the cheese and thicken the sauce. Don''t stir too much because otherwise the sauce will thicken too much due to the evaporation.","images":[],"step":10},{"description":"Sprinkle over the panko and parmesan cheese, then place under the grill/broiler for a few minutes to brown.","images":[],"step":11},{"description":"Remove from the grill/broiler and let it rest for 5 minutes before serving.","duration":5,"images":[],"step":12}]', '["gluten","milk"]', '["high_protein","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["American"],"categories":["casseroles-and-cosy-bakes","dinner-tonight","easter-sides-warm-hearty","main-dishes","most-popular","one-pot-pasta-recipes","one-pot-recipes","pasta-bakes","pasta-recipes","quick-and-easy","side-dishes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a79adfcf75b1', 'en', 'US', 'Mexican Lasagna Enchilada Stack', 'An enchilada - layered like a lasagna! Made with Pork Carnitas (Mexican Pulled Pork) but you can substitute with any shredded or diced (cooked) chicken, beef or pork. This recipe makes 4 generous servings or 6 small servings.', 'https://www.recipetineats.com/tachyon/2014/09/Mexican-Lasagna-Enchilada-Stack-1-Version-2.jpg', 10, 25, 35, 4, '[{"id": "ing_tortillas", "quantity": {"value": 5.0, "unit": "pack of 8"}}, {"id": "ing_pork", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_black_beans", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_enchilada_sauce", "quantity": {"value": 337.5, "unit": "bottle"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.8, "unit": "pack of 125g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["5 - 6 tortillas","2 cups shredded Pork Carnitas (Mexican Pulled Pork) (see notes)","1 can (400g/15oz) corn","1 can (400g/15oz) black beans ( or red kidney beans)","1 small red capsicum ((bell pepper), diced)","2 1/4 cups enchilada sauce (, separated (preferably homemade - here''s my Easy Classic Enchilada Sauce))","1 cup grated mozzarella cheese (or any other melting cheese)","Fresh parsley or coriander (, finely chopped (optional - for garnish))"]}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Combine the Pork Carnitas, corn, black beans, capsicum and 1 1/2 cups of enchilada sauce in a bowl. Mix to combine.","images":[],"step":2},{"description":"Spread 1 tbsp of enchilada sauce on the base of a baking dish.","images":[],"step":3},{"description":"Line the baking dish with tortillas. I find the best way to do this is to cut the tortillas in half, place 2 on the baking dish (with the straight cut side lined to the edge of the baking dish), then cut 1 tortilla into 6 to 8 pieces and use those wedges to fill the gaps.","images":[],"step":4},{"description":"Spread half the filling across the tortillas.","images":[],"step":5},{"description":"Top with another layer of tortillas, then spread the remaining filling on top.","images":[],"step":6},{"description":"Top with a third and final layer of tortillas. Spread remaining enchilada sauce (3/4 cup) across the top, then sprinkle with mozzarella cheese.","images":[],"step":7},{"description":"Bake for 20 to 25 minutes until the cheese is melted and started to turn golden.","duration":22.5,"images":[],"step":8},{"description":"Let stand for 5 minutes, then garnish with parsley or coriander if desired and serve.","duration":5,"images":[],"step":9}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["main_course"],"cuisine":["Mexican"],"categories":["casseroles-and-cosy-bakes","mexican-recipes","pork-carnitas","pork-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5d5ac51d8afe', 'en', 'US', 'Easy Christmas Cheesecake Slab - no bake!', 'Recipe video above. Based on my classic no-bake cheesecake, this Christmas cheesecake is designed for sizzling Aussie summers because there''s no need to turn on the oven, it''s no bake! Excellent one to feed lots of people, this captures the light yet lusciously creamy qualities of a classic baked cheesecake, but it''s considerably easier to make.New to gelatine powder? Don''t worry! It''s affordable, easy to find, easy to use and gives the cheesecake a superior texture that’s smooth and stable, unlike denser or sloppy versions made without it. See FAQ above for rantings!Decorate with whipped cream, berries and rosemary sprigs for a festive look that''s effortless to do.This will serve 24 people as a smaller dessert (ideal after a big meal) or 18 generous pieces.', 'https://www.recipetineats.com/tachyon/2024/12/Christmas-cheesecake-no-bake-slab_4.jpg', 40, 0, 40, 18, '[{"id": "ing_biscoff_or_other_plain_biscuit_cookies_2_1_crumbs", "quantity": {"value": 300.0, "unit": "pack"}}, {"id": "ing_butter", "quantity": {"value": 120.0, "unit": "block of 250g"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_gelatin_powder", "quantity": {"value": 17.5, "unit": "jar"}}, {"id": "ing_water", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.5, "unit": "carton of 250ml"}}, {"id": "ing_cream_cheese", "quantity": {"value": 750.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.15, "unit": "bottle of 50ml"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_cream", "quantity": {"value": 1.5, "unit": "carton of 250ml"}}, {"id": "ing_strawberries", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_berries", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cherries", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_rosemary", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_oranges", "quantity": {"value": 6.0, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}]', '[{"ingredients":["300g/10 oz Biscoff (38 pieces) or other plain biscuit/cookies 2 1/2 cups crumbs) (Note 1)","120g (8 tbsp) unsalted butter (, melted)","1/2 tsp cinnamon powder (optional, recommended)","1 tbsp brown sugar","Pinch of salt"],"purpose":"Biscuit crust:"},{"ingredients":["3 1/2 tsp (13.5 g) gelatin powder (, unflavoured (Note 2))","3 tbsp cold tap water","1 1/2 cups thickened or heavy cream (, or any whipping cream, FRIDGE COLD (Note 3))","750g/ 24 oz cream cheese block (3 blocks, (, well softened at room temperature - don''t use tub (Note 4))","1 1/4 cups caster sugar / superfine sugar (Note 5)","1 1/2 tsp vanilla extract","1 tbsp lemon juice (not critical, can do without)"],"purpose":"No-bake cheesecake filling:"},{"ingredients":["2 cups thickened or heavy cream (, or any whipping cream, FRIDGE COLD (Note 3))","3 tbsp caster sugar / superfine sugar (or double quantity of icing sugar, sifted)","1 1/2 tsp vanilla extract"],"purpose":"Whipped cream (Chantilly cream)"},{"ingredients":["Strawberries (halve or quarter larger ones, mine were small)","Berries (- I used blackberries and raspberries)","Cherries","Rosemary sprigs","6 orange slices (, cut into half moons)","Icing sugar / confectionary sugar (, for dusting)"],"purpose":"Christmas decoration"}]', '[{"description":"Blitz crumb. Press into 33 x 23 cm / 9 x 13\" lined pan with paper overhang (important). Bloom gelatine in the water, re-melt. Whip cream. In separate bowl whip cream cheese + sugar, then vanilla, lemon, salt and gelatine. Fold in 1/4 cream, then remaining cream. Fill pan, fridge 12 hours, decorate!","images":[],"step":1},{"description":"Line pan with overhang:","images":[],"step":2},{"title":"Line","description":"Grease a 23 x 33 cm / 9 x 13\" can VERY lightly with butter or spray with a plain oil (I use canola). Line with parchment/baking paper with lots of overhang on the long side to lift the cheesecake out once set (see photos).","images":[],"step":3},{"title":"Blitz","description":"Break up biscuits roughly by hand and place in a food processor. Blitz until it becomes fine crumbs (~30 seconds).","images":[],"step":4},{"title":"Add butter","description":"Add the butter, cinnamon and salt. Blitz until it resembles wet sand (~ 10 second). It should stay together when pinched between your fingers.","images":[],"step":5},{"title":"Press","description":"Pour into the prepared pan. Spread then use your hand or something flat to press it in firmly (firmer = more stable base). Refrigerate until required.","images":[],"step":6},{"description":"Gelatine (Note 2):","images":[],"step":7},{"title":"Bloom gelatine","description":"Put the water in a small bowl and sprinkle the gelatine across the surface (don''t dump it in one place. Whisk until dissolved then set aside for 3 minute or until it firms up like rubber.","duration":3,"images":[],"step":8},{"title":"Melt","description":"Microwave for 15 seconds on high or until it melts (do not let it boil). Cool for 5 minutes while you make the filling (make sure it''s still liquid when you use it, if there''s a skin on surface or walls, warm for 5 seconds to liquify).","duration":0.25,"images":[],"step":9},{"description":"No-bake cheesecake filling:","images":[],"step":10},{"title":"Whip cream","description":"Put the cream in a bowl and whip it with an electric beater on high for 2 1/2 to 3 minutes until firm peaks form (ie not softly whipped, we want good aeration!).","images":[],"step":11},{"title":"Whip cream cheese","description":"Put the cream cheese and sugar in a separate large bowl. Using the same beater (no need to clean), beat on high for 1 1/2 minutes just until it''s soft and smooth. Add the vanilla, lemon and melted gelatine, then beat for 10 seconds on high to mix it through thoroughly. Don''t beat excessively as we don''t want too many air bubbles in the cheesecake (unsightly).","duration":0.16666666666666666,"images":[],"step":12},{"title":"Fold","description":"Add about 1/4 of the whipped cream into the cream cheese mixture. Gently fold through using a rubber spatula or large spoon (don''t mix aggressively, you''ll knock all the air out of the cream!). Then fold in the rest of the cream.","images":[],"step":13},{"title":"Refrigerate","description":"Pour into the pan and smooth the surface. Refrigerate for 12 hours+ to set.","images":[],"step":14},{"title":"Remove","description":"Use the paper overhang to lift the cheesecake out of the pan and transfer it onto a serving platter. Then slide the paper out from underneath. Refrigerate until ready to decorate.","images":[],"step":15},{"title":"Whip cream","description":"Put the ingredients in a bowl and whip on high for 2 to 3 minutes until softly whipped. (Use an electric beater or stand mixer fitted with a whisk. Also, see Note 6 for stabilising to assemble ahead).","duration":2.5,"images":[],"step":16},{"title":"Decorate","description":"Spread the cream in big swirls across the surface of the cake. Pile on the berries and cherries, tuck in the orange slices and rosemary. Dust with icing sugar then cut into slices and serve!","images":[],"step":17}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["cheesecakes","dessert-recipes","no-bake-sweet-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cb45b18436ec', 'en', 'US', 'No bake cheesecake', 'Recipe video above. To make a no-bake cheesecake that rivals a classic baked one, using gelatine is essential. It''s affordable, easy to find, easy to use, and results in a superior cheesecake compared to denser or sloppy alternatives made without gelatine. See FAQ above for rantings!The filling is exceptionally light-yet-creamy and melts into a smooth, velvety texture with every bite. And everybody loves the crispy, crumbly buttery crust!PS This cheesecake is not overly sweet, it is French patisserie/Japanese cakes level sweet. If you want American-level-sweet, increase the sugar to 1 cup.', 'https://www.recipetineats.com/tachyon/2024/09/No-bake-cheesecake_8.jpg', 40, 0, 40, 12, '[{"id": "ing_digestive_biscuits_or_graham_crackers", "quantity": {"value": 200.0, "unit": "pack"}}, {"id": "ing_butter", "quantity": {"value": 90.0, "unit": "block of 250g"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_gelatin_powder", "quantity": {"value": 11.25, "unit": "jar"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_cream_cheese", "quantity": {"value": 500.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_strawberries", "quantity": {"value": 6.0, "unit": "punnet of 250g"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}]', '[{"ingredients":["200g/7 oz digestive biscuits ((13 pieces, 1 2/3 cups crumbs), or other plain biscuits/cookies)","90g (6 tbsp) unsalted butter, melted","1/2 tsp cinnamon powder (optional)","1 tbsp brown sugar","Pinch of salt"],"purpose":"Biscuit crust:"},{"ingredients":["2 1/4 tsp (9 g) gelatin powder (, unflavoured (Note 2))","2 tbsp cold tap water","1 cup thickened or heavy cream (, or any whipping cream, FRIDGE COLD (Note 3))","500g/ 16 oz cream cheese block (not tub), well softened at room temperature (Note 4)","3/4 cup caster sugar / superfine sugar (Note 5)","1 tsp vanilla extract","1 tbsp lemon juice (not critical, can do without)"],"purpose":"No-bake cheesecake filling:"},{"ingredients":["6 strawberries (, halved (plus extra for serving))","Whipped cream (half batch for decorating, or full batch for extra to serving on side)"],"purpose":"Optional decorations:"}]', '[{"description":"Blitz crumb ingredients. Press into 20cm/8\" inverted base lined springform. Bloom gelatine in the water, re-melt. Whip cream. In separate bowl whip cream cheese + sugar, then vanilla, lemon, salt and gelatine. Fold in 1/4 cream, then remaining cream. Fill crust, fridge 6 hours.","images":[],"step":1},{"description":"Inverted cake pan:","images":[],"step":2},{"title":"Invert & line","description":"Turn the base of a 20cm/8\" springform pan UPSIDE DOWN (Note 6). Grease with butter very lightly. Place a square piece of parchment/baking paper on the base. Then clip into the springform pan – excess paper will stick out.","images":[],"step":3},{"title":"Line sides","description":"Butter and line the side of the pan.","images":[],"step":4},{"title":"Blitz","description":"Break up biscuits roughly by hand and place in a food processor. Blitz until it becomes fine crumbs (~30 seconds).","images":[],"step":5},{"title":"Add butter","description":"Add the butter, cinnamon and salt. Blitz until it resembles wet sand (~ 10 second). It should stay together when pinched between your fingers.","images":[],"step":6},{"title":"Press","description":"Pour into the prepared cake tin. Use a spatula to roughly spread it out over the base and up the walls. Then flatten and press the base and walls using something with a flat base and vertical edges (I used a measuring cup). Aim for the wall to be ~9mm (0.35\") from the top of the rim (Note 7). Refrigerate crust until required.","images":[],"step":7},{"description":"Gelatine (Note 2):","images":[],"step":8},{"title":"Bloom gelatine","description":"Put the water in a small bowl and sprinkle the gelatine across the surface (don''t dump it in one place. Whisk until dissolved then set aside for 3 minute or until it firms up like rubber.","duration":3,"images":[],"step":9},{"title":"Melt","description":"Microwave for 15 seconds on high or until it melts (do not let it boil). Cool for 5 minutes while you make the filling (make sure it''s still liquid when you use it).","duration":0.25,"images":[],"step":10},{"description":"No-bake cheesecake filling:","images":[],"step":11},{"title":"Whip cream","description":"Put the cream in a bowl and whip it with an electric beater on high for 2 minutes until firm peaks form (ie not softly whipped, we want good aeration!).","duration":2,"images":[],"step":12},{"title":"Whip cream cheese","description":"Put the cream cheese and sugar in a separate large bowl. Using the same beater (no need to clean), beat on high for 1 minute just until it''s soft and smooth. Add the vanilla, lemon and melted gelatine, then beat for 10 seconds on high to mix it through thoroughly. Don''t beat excessively as we don''t want too many air bubbles in the cheesecake (unsightly).","duration":1,"images":[],"step":13},{"title":"Fold","description":"Add about 1/4 of the whipped cream into the cream cheese mixture. Gently fold through using a rubber spatula or large spoon (don''t mix aggressively, you''ll knock all the air out of the cream!). Then fold in the rest of the cream.","images":[],"step":14},{"title":"Refrigerate","description":"Pour into the crust, smooth the surface. Refrigerate for 6 hours+ to set.","images":[],"step":15},{"description":"Remove sides of the cake pan. Use then overhang paper to slide cheesecake off the cake pan base onto a serving platter. Then slide the cheesecake off the paper.","images":[],"step":16},{"description":"Decorate the top with whipped cream and strawberries, if desired (or just dollop whipped cream on the plate). Cut into slices and serve!","images":[],"step":17}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["cheesecakes","dessert-recipes","no-bake-sweet-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_10eca5f45430', 'en', 'US', 'Basque Cheesecake', 'Recipe video above. This is the iconic Burnt Basque Cheesecake, in all its rustic perfection with the signature golden "burnt" surface that tastes like caramel, and light-as-air creamy vanilla cheesecake inside. Stunningly luscious yet light, and not that sweet at all!The surface becomes golden by baking at a higher temp than classic baked cheesecakes - 160C/320F vs 220°C/425°F for Basque. This recipe is not a basic "dump and beat" recipe, but the result is better. Texture is fluffier, as it should be, with no thick band of dry overcooked cheesecake (notorious problem!). Use a handheld electric beater or stand mixer with the paddle attachment. See Note 5 about speeds.', 'https://www.recipetineats.com/tachyon/2023/09/Basque-cheesecake_5.jpg', 15, 45, 60, 12, '[{"id": "ing_cream_cheese", "quantity": {"value": 750.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 3.0, "unit": "carton of 250ml"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_vanilla_bean_extract", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_egg", "quantity": {"value": 9.375, "unit": "carton of 12"}}]', '[{"ingredients":["750 g / 1.5 lb cream cheese blocks (, room temperature (I use Philadelphia, Note 1))","1 cup caster / superfine sugar (regular white sugar ok too)","1 1/4 cups whipping cream (, take out of fridge 15 minutes prior (Note 2))","1/4 cup flour (, plain/all-purpose)","1 tsp vanilla bean extract (or paste)","3/4 cups + 1 tbsp lightly whisked eggs (, at room temperature, ~4-5 large eggs (yes, I need you to measure! Note 3))"]}]', '[{"description":"See below for full length written recipe. Shorthand recipe is for experienced bakers.","images":[],"step":1},{"description":"Shorthand recipe","images":[],"step":2},{"title":"Prep","description":"Preheat oven to 220°C / 425°F (200°C fan) with the shelf in the middle. Press scrunched paper into 20cm/8\" springform pan.","images":[],"step":3},{"title":"Batter","description":"Beat cream cheese 2 minutes on medium. Beat in sugar on low speed for 10 seconds. In separate bowl, hand whisk 1/4 cup cream with the flour (becomes like paste). Whisk in remaining cream and vanilla. While beating on low, slowly pour cream into cream cheese, then eggs (don''t overbeat).","duration":0.16666666666666666,"images":[],"step":4},{"title":"Bake","description":"Pour into pan, bang pan on counter, pop bubbles with knife. Bake 45 min (up to 65 min possible, Note 8) until top deep golden. Cool 2 hrs on counter then 8 hrs+ in fridge uncovered. Ready for serving!","images":[],"step":5},{"description":"Full instructions recipe","images":[],"step":6},{"description":"Preheat oven to 220°C / 425°F (200°C fan) with the shelf in the middle of the oven.","images":[],"step":7},{"title":"Pan prep (Note 4)","description":"Press 2 x 40cm/16\" sheets of scrunched up baking/parchment paper arranged in an \"X\" into a 20cm/8\" springform pan (6cm / 2.5\" tall), and fold down over the rim to hold in place. You''ll need to scrunch/pleat to fit which creates the signature rustic sides! The batter will weigh it down so don''t worry if it doesn''t stay in.","images":[],"step":8},{"description":"Beat the cream cheese in a large bowl on medium speed for 2 minutes, scraping down the sides as needed, until smooth and lump-free. Add sugar and beat on low speed for 10 seconds.","duration":2,"images":[],"step":9},{"title":"Flour & cream (Note 6)","description":"Put about 1/4 of the cream and all the flour in a medium bowl. Hand whisk until lump free (it will be paste-like), then slowly pour in the remaining cream while whisking. Once flour is incorporated, whisk in vanilla. (PS not making whipped cream here! Should be pourable)","images":[],"step":10},{"description":"Slowly pour the cream into the cream cheese bowl with the beater going on low. Beat just until combined. Then slowly pour the eggs in while the beater is still on low speed. As soon as the eggs are incorporated, stop beating to minimise getting bubbles in the batter (Note 7).","images":[],"step":11},{"title":"Remove air bubbles","description":"Pour into the prepared pan. Bang the pan on the counter then pop bubbles that rise to the surface with a small sharp knife. I do repeat 3 to 5 times. (Note 7)","images":[],"step":12},{"description":"Bake 45 minutes or until the surface is a deep golden brown. It can take up to 65 minutes and that''s fine! (Seriously, read Note 8) Keep a close eye on it for the last 15 minutes, you want it deeply golden but not burnt. The centre will still be wobbly and the cake will rise like a soufflé.","images":[],"step":13},{"title":"Chill overnight","description":"Cool in the cake pan for at least 2 hours on the counter (it will sink, that''s normal). Then refrigerate for a minimum of 8 hours, uncovered.","images":[],"step":14},{"title":"Serving","description":"Release the sides of the springform pan. Hold excess paper overhang to lift off base onto a cutting board or plate. Fold down sides - I love serving it on the paper, it''s part of the visuals! Bring to room temp for 30 minutes if time permits, though also great served chilled. Cut like cake! Eat as is - doesn''t need cream, berries etc.","duration":30,"images":[],"step":15}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Basque country","Spain"],"categories":["cheesecakes","dessert-recipes","spanish-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2fa46987d055', 'en', 'US', 'Nutella Cheesecake (No Bake)', 'Recipe video above. The best way to inject serious Nutella flavour into a cheesecake? Make it NO-BAKE. Foregoing any cooking preserves the Nutella flavour better. A triple hit of Nutella also helps here: in the mousse-like cream cheese filling, the ganache topping and as a drizzle to finish it off!PS I know gelatine is not a staple ingredient for many, but I promise it''s easy to use and you can get it at regular grocery stores. It makes the cheesecake set without being overly dense. I tried without and it''s just not as good. Gelatine makes it so much better!', 'https://www.recipetineats.com/tachyon/2021/03/Nutella-Cheesecake_2.jpg', 30, 0, 30, 12, '[{"id": "ing_oreo_cookies", "quantity": {"value": 200.0, "unit": "pack"}}, {"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_gelatine_powder", "quantity": {"value": 15.0, "unit": "jar"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_cream_cheese", "quantity": {"value": 500.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_nutella", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_cream", "quantity": {"value": 2.0, "unit": "carton of 250ml"}}, {"id": "ing_chocolate", "quantity": {"value": 0.25, "unit": "block of 100g"}}, {"id": "ing_hazelnuts", "quantity": {"value": 37.5, "unit": "jar"}}]', '[{"ingredients":["200g/ 7oz Oreo cookies (1.5 standard packs, Note 1)","60g / 4 tbsp unsalted butter (, melted)"],"purpose":"Base:"},{"ingredients":["3 tsp gelatine powder (Note 2)","1/4 cup water","500g / 1 lb cream cheese (, softened (block form, Note 3))","1/2 cup soft icing sugar / powdered sugar (Note 4)","1 cup Nutella (Note 5)","1 cup heavy/thickened cream"],"purpose":"Nutella mousse filling:"},{"ingredients":["1/2 cup heavy/thickened cream","1/2 cup Nutella","1/4 cup dark chocolate chips/semi-sweet chocolate chips"],"purpose":"Nutella ganache topping:"},{"ingredients":["1/4 cup hazelnuts (, lightly toasted then chopped (Note 6))","1/2 cup heavy/thickened cream (for whipping)","3 tbsp Nutella (, warmed)"],"purpose":"Toppings:"}]', '[{"title":"Prepare pan","description":"Flip the base of a 20cm / 8\" springform pan upside down – this makes it easier to remove the finished cheesecake without the lip in the way. Butter pan base, then press on a square sheet of baking paper. Clip the pan sides onto the base, letting the excess paper overhang. Butter and line the pan sides with more baking paper.","images":[],"step":1},{"description":"Oreo biscuit base:","images":[],"step":2},{"title":"Blitz cookies","description":"Roughly break up Oreos with hands and place in food processor. Blitz until they become fine crumbs. Add melted butter, then blitz again until combined.","images":[],"step":3},{"title":"Press into pan","description":"Transfer crumbs into prepared pan, pressing evenly and firmly on to the base (I use the underside of a straight-sided, flat-bottomed cup measure to do this).","images":[],"step":4},{"description":"Nutella mousse filling:","images":[],"step":5},{"title":"Bloom gelatine","description":"Place water in a small bowl then sprinkle the gelatine powder across the surface. Stir to partly dissolve. Set aside 5 minutes. It will turn thick; this process is called blooming. Microwave the gelatine for 15 seconds to turn it into liquid, stir, then let it stand for 5 minutes to cool.","duration":0.25,"images":[],"step":6},{"title":"Cream cheese and Nutella mixture","description":"Beat cream cheese, Nutella and icing sugar until smooth. Add the cooled gelatine liquid and beat another 30 seconds.","images":[],"step":7},{"title":"Whip cream","description":"In a separate bowl, whip the cream until stiff peaks form.","images":[],"step":8},{"title":"Fold in cream","description":"Add one third of the whipped cream to the Nutella mixture and gently fold until just combined. Fold in another third of the cream the same way. Then fold in the remaining cream.","images":[],"step":9},{"title":"Transfer to cake pan","description":"Pour the mixture into the prepared tin and place back in the fridge for at least 1 hour to set.","images":[],"step":10},{"title":"Nutella ganache","description":"Place cream, Nutella and chocolate chips into a heatproof bowl. Microwave in two 30-second bursts, stirring in between, until smooth.","images":[],"step":11},{"title":"Pour ganache onto cheesecake","description":"Allow ganache to cool for 5 minutes, then pour over the set cheesecake base. Tilt pan to spread it over the surface evenly.","duration":5,"images":[],"step":12},{"description":"Refrigerate cheesecake at least 3 hours before sprinkling with hazelnuts (otherwise they sink into the cake!)","images":[],"step":13},{"title":"Decorate","description":"Sprinkle over hazelnuts. Pipe dollops of whipped cream around the edge, then drizzle with warm Nutella. Slice greedy-sized wedges and devour!","images":[],"step":14}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["cheesecakes","dessert-recipes","easter-baking-desserts"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e5e44212139d', 'en', 'US', 'Strawberry Cheesecake', 'Recipe video above. A light-yet-rich cheesecake, creamy but not dense-creamy like New York cheesecake. Topped with the most utterly incredible Strawberry Sauce topping - it''s a match made in heaven! Don''t be daunted by the number of steps - they are straightforward, I''ve just broken it down. Watch the video!', 'https://www.recipetineats.com/tachyon/2018/12/Strawberry-Cheesecake_8-SQ.jpg', 30, 55, 445, 12, '[{"id": "ing_arnott_s_marie_crackers_or_16_graham_cracker_squares", "quantity": {"value": 200.0, "unit": "pack"}}, {"id": "ing_butter", "quantity": {"value": 120.0, "unit": "block of 250g"}}, {"id": "ing_cream_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.3, "unit": "tub of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_strawberries", "quantity": {"value": 2.0, "unit": "punnet of 250g"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.019, "unit": "pack of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}]', '[{"ingredients":["200g / 7oz Arnott''s Marie crackers or other plain biscuit (Aus) or 28 Graham Cracker squares (Note 1)","120 g / 8 tbsp unsalted butter (, melted)"],"purpose":"Cheesecake Biscuit Base:"},{"ingredients":["1 lb / 500g cream cheese (, softened (Note 2))","2 tbsp plain flour (all purpose flour)","1 tsp vanilla extract","1/2 cup sour cream (full fat, sub sour cream)","1 1/2 cups caster sugar (superfine sugar)","Zest of 1 lemon","3 eggs (, at room temperature)"],"purpose":"Cheesecake Filling:"},{"ingredients":["500g / 1 lb strawberries (, half diced and half halved)","2 tbsp lemon juice OR water (Note 3)","1/2 cup white sugar","1/2 tsp vanilla extract","1 1/2 tsp cornflour/cornstarch","2 tbsp water"],"purpose":"Strawberry Topping for Cheesecake:"}]', '[{"description":"Preheat oven to 160C/320F (standard) or 140C/295F (fan/convection).","images":[],"step":1},{"description":"Get a 20cm/8\" springform cake tin. Turn the base UPSIDE DOWN (Note 4), butter lightly and place a square piece of parchment/baking paper on the base. Then clip into the springform pan - excess paper will stick out, see photos in post and video.","images":[],"step":2},{"description":"Butter and line the side of the pan.","images":[],"step":3},{"description":"Cheesecake Biscuit Base:","images":[],"step":4},{"description":"Break up biscuits roughly by hand and place in a food processor.","images":[],"step":5},{"description":"Blitz until fine crumbs (Note 5). Add butter, briefly blitz until dispersed and it resembles wet sand.","images":[],"step":6},{"description":"Pour into the prepared cake tin. Use a spatula to roughly spread it out over the base and up the walls.","images":[],"step":7},{"description":"Use something with a flat base and vertical edges (I used a measuring cup) to press the crumbs up the wall almost to the top of the sides, and flatten the base.","images":[],"step":8},{"description":"Use a mixer or beater to beat the cream cheese until just smooth, no longer than 20 seconds on speed 4. (You do not want to aerate cheesecake filling as it causes cracks when it bakes)","images":[],"step":9},{"description":"Add flour, beat for 5 seconds on speed 4 until just incorporated.","duration":0.08333333333333333,"images":[],"step":10},{"description":"Add vanilla, sour cream, sugar and lemon zest. Beat until just combined (10 sec max, speed 5).","images":[],"step":11},{"description":"Add eggs one at a time, beat in between until just combined (5 sec each), and after the last one, beat just until the egg is fully incorporated.","images":[],"step":12},{"description":"Pour into prepared crust.","images":[],"step":13},{"description":"Bake for 55 minutes. The top should be a very light golden brown, not cracked, and near perfectly flat. It should jiggle slightly when you gently shake the pan.","duration":55,"images":[],"step":14},{"description":"Cool the cake in the oven with the door open 20 cm / 8\" (Note 6), then refrigerate for 4 hours+ in the pan.","images":[],"step":15},{"description":"Remove sides. Use overhang paper to slide cheesecake off the cake pan. Then slide the cheesecake off the paper.","images":[],"step":16},{"description":"Strawberry Topping for Cheesecake:","images":[],"step":17},{"description":"Place chopped strawberries, vanilla, sugar and lemon juices in a saucepan. Stir then bring to simmer over medium heat.","images":[],"step":18},{"description":"Simmer for 10 minutes until strawberries breakdown.","duration":10,"images":[],"step":19},{"description":"Mix cornflour with water, then add into saucepan and stir.","images":[],"step":20},{"description":"Add halved strawberries and cook for 1 minute to soften.","duration":1,"images":[],"step":21},{"title":"Sauce should be syrupy","description":"remove from stove and cool. Will thicken as it cools.","images":[],"step":22},{"description":"Once cool, stirl. Adjust thickness to make it the right \"oozing\" consistency (see video, Note 7) with a tiny touch of water (be careful!).","images":[],"step":23},{"description":"Spoon onto cheesecake so it''s covered with a single layer of strawberries. Flip strawberry halves so they are facedown. Refrigerate 2 hours+.","images":[],"step":24},{"description":"Slice and serve with remaining Strawberry Sauce!","images":[],"step":25}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["cheesecakes","dessert-recipes","easter-baking-desserts"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8cb34cf809f5', 'en', 'US', 'Strawberry Cheesecake Sundae Pots', 'A twist on the classic cheesecake, this is a no-bake dessert that is fast and easy to make, and is perfect for entertaining because you can make-ahead all the elements and just assemble prior to serving!', 'https://www.recipetineats.com/tachyon/2014/05/Cheesecake-Sundae-Pots_square1.jpg', 25, 0, 25, 6, '[{"id": "ing_cream_cheese", "quantity": {"value": 225.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 1.0, "unit": "bottle of 50ml"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_cream", "quantity": {"value": 0.9, "unit": "carton of 250ml"}}, {"id": "ing_2_cups_lightly_crushed_graham_crackers", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_strawberries", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}]', '[{"ingredients":["225 g /8 oz cream cheese (, softened)","1⁄2 cup confectioners’ sugar (icing sugar)","1 1⁄2 tsp vanilla extract","1⁄2 tsp lemon zest","3⁄4 cup heavy whipping cream (, whipped)"],"purpose":"Cheesecake Mousse"},{"ingredients":["1 1⁄2 cups lightly crushed graham crackers","3 tbsp packed brown sugar","4 tbsp salted butter (, melted)"],"purpose":"Graham Cracker crumble"},{"ingredients":["250 g / 9 oz punnet of strawberries","1 cup caster sugar","1⁄4 cup cold water"],"purpose":"Strawberry Caramel"}]', '[{"description":"Cheesecake Mousse","images":[],"step":1},{"description":"Beat the cream cheese, confectioners’ sugar, vanilla and lemon zest until light and fluffy.","images":[],"step":2},{"description":"Fold in the whipped cream. Then cover and refrigerate for at least 2 hours, or until required (will keep for 3 days).","images":[],"step":3},{"description":"Strawberry Caramel","images":[],"step":4},{"description":"Puree half the strawberries.","images":[],"step":5},{"description":"Quarter the remaining berries (if large, otherwise halve).","images":[],"step":6},{"description":"Combine the sugar and water in a pan and stir over low heat to dissolve the sugar, then turn up the heat to medium high and cook for 4 to 5 minutes without stirring until a golden caramel forms.","duration":4.5,"images":[],"step":7},{"description":"Remove from heat, stir in puree carefully (it may spit) then return to low heat and stir until smooth.","images":[],"step":8},{"description":"Let cool, then add reserved berries. Refrigerate until required.","images":[],"step":9},{"description":"Graham Cracker Crumble","images":[],"step":10},{"description":"Combine the crushed crackers, brown sugar and butter in a bowl and mix well.","images":[],"step":11},{"description":"In a clear glass, place some graham cracker crumble in the base.","images":[],"step":12},{"description":"Spoon over cheesecake mousse and top with strawberry caramel.","images":[],"step":13}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dessert"],"cuisine":[],"categories":["cheesecakes","dessert-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e2ebed91956a', 'en', 'US', 'Our Easy Chilli Crisp', 'Recipe video above. This is the best Chilli Crisp I have ever had in my life. Proper crunchy bits, excellent flavour (why are so many so bland??!), savoury (not just salty), has a stack of aromatic flavour, and a warm spiciness that won''t blow your head off. Easy to make with accessible ingredients. Better than anything you can buy! We take a massive shortcut by using store bought crispy friend shallots and garlic. Frying your own is tricky even for professional chefs. We thought using store bought would compromise the greatness of a truly from-scratch chilli crisp, but it didn''t!Recipe credit: Massive thanks to Chef Hannah from our food bank RecipeTin Meals, and her father Chef Haibing Huang back in China. Chilli Crisp Lovers of the world salute you!Makes ~1 1/4 cups (310 ml)', 'https://www.recipetineats.com/tachyon/2026/03/Chilli-crisp-featured.jpg', 20, 30, 50, 310, '[{"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_star_anise", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 0.5, "unit": "jar"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.25, "unit": "jar of 50g"}}, {"id": "ing_fennel_seeds", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_water", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_chilli", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.01, "unit": "bottle of 250ml"}}, {"id": "ing_vinegar", "quantity": {"value": 0.003, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 10.0, "unit": "pack of 3 heads"}}]', '[{"ingredients":["1 dried bay leaf (substitute fresh)","1 star anise","1/2 cinnamon stick (just break by hand)","1/2 tsp green cardamom pods (~7 - 8 pods)","2 1/2 tsp red (or pink) sichuan peppercorns (whole not powder) (Note 1)","1/2 tsp fennel seeds","1/4 tsp cloves (~8 pieces)","2 tsp water"],"purpose":"Spices:"},{"ingredients":["1 green onion stem (, cut into 15cm/6\" lengths)","1 tbsp fresh ginger (, sliced 3mm/ 0.1\" thick (slice then press into tablespoon to measure))","1 cup vegetable oil (or canola or peanut oil)"],"purpose":"For Oil Infusion:"},{"ingredients":["1 tsp white sesame seeds","3 tsp dried chilli flakes (red pepper flakes) (Note 2)","1 tbsp smoked paprika (, sub regular/sweet paprika)","1/2 tsp light soy sauce (or all-purpose soy (not dark soy))","1/2 tsp Chinese black vinegar (Chinkiang) (Note 3)"],"purpose":"For Oil Sizzle:"},{"ingredients":["1 tsp caster sugar / superfine sugar (Note 4)","1 1/2 tsp cooking salt / kosher salt","1 tsp Chinese chicken stock powder","1/2 cup crispy fried shallots (, store bought (Note 6))","2 tbsp crispy fried garlic (, store bought (Note 6))"],"purpose":"Seasoning and Crispy Bits:"}]', '[{"description":"Soak Dried Spices with the water 30 minutes. Gently simmer with Oil Infusion ingredients 25 minutes. Strain into bowl over Oil Sizzle ingredients. Cool 30 minutes, mix in Seasoning & Crispy Bits. Fridge 24 hours. Mix very well before use!","images":[],"step":1},{"title":"Chop hard spices","description":"Roughly cut the cinnamon, bayleaf and star anise into ~1cm / 0.4\" pieces.","images":[],"step":2},{"title":"Soak dried spices","description":"Scrape into a bowl with the remaining Spices. Add the water and mix so everything is coated. Leave for 30 minutes so they absorb all the water. (This prevents burning when infusing hot oil and softens the surface for better flavour extraction).","duration":30,"images":[],"step":3},{"title":"Oil infusion","description":"Put the soaked spices into a 20cm/8\" saucepan with the green onion, ginger and cold oil. Start on medium-low, then adjust the heat until you see small fizzy bubbles coming up from the base.","images":[],"step":4},{"title":"30 minute fizzy simmer","description":"Maintain that gentle fizzy bubbling for 25 to 30 minutes, stirring 2 or 3 times, and ensure nothing burns. Towards the end, the bubbling will slow (a sign the water has evaporated from the spices, ginger etc) and the ginger and green onion should be dark golden, not burnt. (Note 7 if browning to fast!!)","duration":27.5,"images":[],"step":5},{"title":"Oil Sizzle ingredients","description":"Just before the oil simmering finishes, put the Oil Sizzle ingredients in a metal bowl (or high heat-proof container that can sustain hot oil). ⚠️ Don''t do this too far ahead of time else the sesame seeds may absorb too much of the liquids.","images":[],"step":6},{"title":"Strain","description":"When the infused oil is done, strain the hot oil into the bowl using a fine-mesh metal sieve. Then mix. Discard all the used spices etc caught in the strainer. (Note 8 on oil temp)","images":[],"step":7},{"title":"Cool","description":"Leave the oil to cool for at least 15 minutes.","images":[],"step":8},{"title":"Seasoning and crispy bits","description":"Mix all the Seasoning and Crunchy bits into the cooled oil.","images":[],"step":9},{"title":"Infuse overnight","description":"Pour into a jar or airtight container. Once fully cool, seal with a lid. Leave for at least 24 hours to let all the flavours meld. It just gets better with time, peaking on day 3 onwards. Keeps in the fridge for 6 to 8 weeks. Always mix well before using, being sure to agitate all the good stuff into the oil!","images":[],"step":10},{"description":"Use on stir fries, noodles, fried rice, soups (Asian or not!), eggs, in burgers, dipping sauce for dumplings, turn a boring plain poached chicken or fish into an exciting dinner, serve with steak (I DO THIS ALL THE TIME!), dollop over Lebanese pizza or roast vegetables, smear in this or this gyros and donor kebab wraps. Mix with mayo or sour cream to make an instant dip/sauce for fries, wedges or veggie sticks, or use it for tacos and burritos. The question really is - what can''t you use it for??!! :)","images":[],"step":11}]', '["gluten","peanuts","sesame","soy"]', '[]', '{"mealType":["main_course"],"cuisine":["Chinese"],"categories":["chef-hannahs-recipes","chinese-recipes","iconic-dishes","sauces"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_99a6e56f28ad', 'en', 'US', 'Chinese eggplant and minced pork - Sichuan Fish Fragrant Eggplant', 'Recipe video above. Tried making this iconic Sichuan dish before and been underwhelmed? This one’s the real deal! Called Yu Xiang Qie Zi, this is straight from our RTM Chef Hannah, born and raised in the Sichuan province of China, a family of chefs at that! Even her chef father gave this recipe his rare stamp of approval.🙌🏻For full authenticity, grab broad bean sauce and pickled chilli from an Asian store. That said, our supermarket-sub version is so good, we’d have happily shared it - if we hadn’t already tasted the OG!Traditionally, the eggplant is deep fried (and yes, that’s why it’s so melt-in-your-mouth good). But see Note 1 for a fantastic no-fry pan-steamed option! Spiciness - Low mild. There''s not that much chilli in it!', 'https://www.recipetineats.com/tachyon/2025/05/Chinese-eggplant-with-minced-pork_7.jpg', 10, 20, 30, 4, '[{"id": "ing_vegetable_oil", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_pork_mince", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 7.5, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_broad_bean_sauce", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.019, "unit": "pack of 400g"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.01, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_honey", "quantity": {"value": 0.01, "unit": "jar of 500g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.018, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_white_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1 cup vegetable oil (, or canola, sunflower oil (Note 1 for no-fry version))","1 large eggplant or 2 medium/small (450 to 500g), cut into 7 x 1.5cm batons (2.7 x 0.6\"), skin on (Note 2)","100g / 3.5 oz pork mince / ground pork (Note 3)","1 tbsp ginger (, finely minced)","1 1/2 tbsp garlic (, finely minced)","1 green onion (, finely sliced, white & pale green part (for cooking) separated from the green part (garnish))","1 tsp pickled red chilli (, or any pickled spicy peppers (Note 4))","1 tbsp broad bean sauce (, we use Pixian doubanjiang, the spicy Sichuan version(Note 5))"]},{"ingredients":["1 1/2 tsp cornflour / cornstarch","1 tbsp light soy sauce (Note 7)","1/2 tsp dark soy sauce (Note 7)","1 1/2 tbsp sugar","1 tsp honey","3 1/2 tsp black vinegar (Note 8)","1/2 cup water"],"purpose":"Sauce:"},{"ingredients":["White rice"],"purpose":"Serving:"}]', '[{"title":"ABBREVIATED","description":"Mix sauce. Fry eggplant until soft. Keep 2T oil. Cook pork 2 min, then garlic, ginger and white part green onion for 30 sec. Cook chilli + broad bean sauce 1 min. Add eggplant and sauce in 2 batches, once thickened, serve!","duration":0.5,"images":[],"step":1},{"title":"Sauce","description":"Mix the cornflour and light soy in a jug until lump free. Add the remaining Sauce ingredients and mix to combine. Set aside.","images":[],"step":2},{"title":"Fry eggplant","description":"Heat oil in a wok on high heat until hot - 180°C/350°F. Add half of the eggplant and fry for around 4 minutes, stirring and turning gently a few times, until soft all the way through and a bit browned on the surface. Remove with a slotted spoon onto a paper towel lined tray. Repeat with remaining eggplant.","images":[],"step":3},{"title":"Remove oil","description":"Carefully remove the leftover oil from the wok except 2 tablespoons, for cooking.","images":[],"step":4},{"title":"Stir fry","description":"Cool the wok slightly then return to high heat. Add the pork and cook for 1 - 2 minutes, breaking it up as you go, until you no longer see pink. Add garlic, ginger, white part of the green onion. Stir fry for 30 seconds. Add pickled red chilli and broad bean sauce. Cook for 1 minute.","duration":1.5,"images":[],"step":5},{"title":"Add sauce","description":"Give the Sauce a quick mix (to dissolve settled cornflour). Add eggplant, then add half the Sauce into the wok, toss gently until the sauce starts thickening - about 30 to 45 seconds. Add remaining Sauce, toss gently for 45 seconds until it thickens (goal: between maple syrup and honey).","duration":0.75,"images":[],"step":6},{"title":"Serve","description":"Turn off heat. Pour into a serving bowl, sprinkle with green onion. Serve with rice!","images":[],"step":7},{"description":"Healthier pan-steamed eggplant option:","images":[],"step":8},{"title":"Brown eggplant","description":"Heat 2 tbsp oil in a large non-stick pan (with lid) over medium high heat. Pan fry eggplant for 1 1/2 minutes on each side until lightly browned.","images":[],"step":9},{"title":"Steam","description":"Carefully add 1/3 cup water around the eggplant (it will steam, so be careful). Immediately cover with a lid to trap the steam. Steam for 2 minutes or until the water has evaporated and the eggplant is soft all the way through (if needed, add more water and keep steaming).","duration":2,"images":[],"step":10},{"title":"Proceed","description":"Transfer eggplant to a plate. Proceed with recipe using the large non stick pan rather than wok.","images":[],"step":11}]', '["gluten","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese","Sichuan"],"categories":["chef-hannahs-recipes","chinese-recipes","iconic-dishes","mains","pork","pork-recipes","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6be9bb6dd6de', 'en', 'US', 'Tuscan Chicken Stew', 'Recipe video above. This is a 30 minute creamy white stew filled with seared Italian-seasoned chicken, sun dried tomatoes, burst-in-your-mouth cherry tomatoes, meaty white beans and swirls of spinach in a garlicky parmesan sauce. It''s not authentic Italian but I think it channels Tuscan vibes with the bright colours of Italy, in a bowl!', 'https://www.recipetineats.com/tachyon/2026/06/Tuscan-chicken-stew-5.jpg', 13, 22, 35, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_italian_herb_mix", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.833, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_wine", "quantity": {"value": 0.111, "unit": "bottle of 750ml"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_baby_spinach", "quantity": {"value": 100.0, "unit": "bag of 250g"}}]', '[{"ingredients":["600g / 1.2 lb chicken thighs (, boneless skinless (or breast), cut into large bite size pieces 3 - 4 cm / 1.2 - 1.4\" (Note 1))"]},{"ingredients":["1 1/2 tsp Italian herb mix (store bought mix, or see Note 2)","1/2 tsp garlic powder","1/2 tsp cooking salt / kosher salt (halve for table salt, +50% for flakes)","1/4 tsp black pepper"],"purpose":"Chicken seasoning:"},{"ingredients":["1 1/2 tbsp olive oil","1 onion (, halved and sliced into 1cm / 0.4\" wedges)","3 garlic cloves (, finely minced)","1/2 cup (100 g) sun dried tomatoes (, cut into 0.5cm / 0.2\" slices (Note 3))","200g (1 1/4 cups) cherry or grape tomatoes (1 punnet)","2 x 400g/14oz cans butter beans (large lima beans), drained - or cannellini, Great Northern or other white beans (Note 4)","1/3 cup Chardonnay or other dry white wine (, substitute chicken stock/broth (Note 5))","1/3 cup plain flour / all-purpose flour (Note 6 for gluten-free)","3 cups chicken stock / broth (, low sodium)","3/4 cup thickened cream / heavy cream (, or any full fat cream ~35% fat)","1/2 cup parmesan (, finely grated or store bought sandy-type - substitute with cheddar, tasty or other sharp cheese)","100g / 3.5oz baby spinach (, or a few big handfuls torn kale)"],"purpose":"Stew:"}]', '[{"description":"Season chicken, sear. Sauté onion and garlic. Deglaze with wine, stir in flour, then stock. Add beans and sun dried tomato, simmer 7 minutes. Add cream, parmesan and cherry tomatoes, simmer 8 minutes. Stir in spinach, serve!","images":[],"step":1},{"title":"Season and sear chicken","description":"Sprinkle chicken with the seasoning and toss to coat. Heat the oil on high in a 30 cm / 12\" non stick pan until very hot. (Note 7 re: cooking vessel) Add the chicken, spread it out, then leave it for 30 seconds or so until golden. Then start stirring, leaving it for 20 seconds every now and then to get colour on the pieces, until most of the pieces are light golden.","duration":0.5,"images":[],"step":2},{"title":"Sauté onion","description":"Lower heat to medium high. Add onion and garlic then cook for around 2 minutes until the onion is wilted.","images":[],"step":3},{"title":"Deglaze and add flour","description":"Turn the heat back up to high. Add the wine and let it simmer for 1 - 2 minutes until reduced by half. Add flour and stir until it is mixed in.","duration":1.5,"images":[],"step":4},{"title":"Make sauce","description":"Slow pour in a third of the stock, mixing as you go. The flour will make the liquid turn into a thick sauce quite quickly. Then add the rest of the stock, beans and sun dried tomato, and stir well.","images":[],"step":5},{"title":"First simmer 7 minutes","description":"Bring to a simmer. Lower heat to medium or medium high so it''s simmering, not too rapidly. Simmer 7 minutes, stirring every now and then.","images":[],"step":6},{"title":"Second simmer 8 minutes","description":"Add cherry tomatoes, cream and parmesan. Mix and simmer for 8 minutes. The sauce should be reduced and thicken into a gravy consistency.","duration":8,"images":[],"step":7},{"title":"Wilt spinach","description":"Stir spinach in to make it wile (~ 30 seconds). Ladle into bowls, garnish with extra parmesan and chilli flakes if desired. Serve with warm crusty bread for dunking!","images":[],"step":8}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian-esque","Western"],"categories":["chicken","chicken-recipes","mains","stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_894df79de4d0', 'en', 'US', 'Coconut Chicken Curry - quick and easy', 'Recipe video above. This Coconut Chicken Curry proves you don’t need a long list of spices or a jar of curry paste to make a truly Indian-tasting curry - just 3 simple spices and very little effort. Tastes like a coconut-y Rogan Josh! I love that it''s made from scratch rather than using a jar of paste. I''ve used chickpeas to fill this out and add a nice nutty crunch just by opening a can, but you could use diced potatoes instead. Stirring in a handful of spinach at the end wouldn''t go astray either.Bonus - It makes a good amount so there''s enough for lunch tomorrow.Spice level - None. Feel free to add some with cayenne pepper or using a HOT curry powder!', 'https://www.recipetineats.com/tachyon/2026/04/Coconut-chicken-curry-quick-easy_7.jpg', 15, 20, 35, 5, '[{"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 7.5, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.75, "unit": "jar of 50g"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_turmeric", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.6, "unit": "carton of 250ml"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_naan", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["2 tbsp unrefined coconut oil (virgin), ie coconut flavoured, or butter, ghee, or any cooking oil you want (Note 1)","500 g/1lb boneless chicken thighs (, cut into ~2cm / 0.8\" pieces (Note 2))","1 large onion (, diced)","1 1/2 tbsp garlic (, finely grated using a microplane (~6 large cloves))","1 1/2 tbsp ginger (, finely grated using a microplane)","2 1/2 tbsp curry powder (, mild - just regular ones like Clives, Keens (feel free to use HOT for spicy!))","1 tsp cumin powder","1 tsp turmeric powder","1/4 cup tomato paste","1 1/2 cups chicken stock/broth (, low sodium)","400g / 14oz coconut cream (substitute coconut milk), full fat (Note 3)","400g / 14oz can chickpeas (, drained)","1 1/4 tsp cooking salt / kosher salt (halve for table salt, double for flakes)"]},{"ingredients":["Plain yogurt (, slightly thinned with water to make it drizzle-able)","Coriander leaves (cilantro) (, roughly chopped, recommended)","Basmati rice ((you''ll need to cook 3 cups rice grains to make enough) or other rice of choice)","Naan (, optional)"],"purpose":"Serving:"}]', '[{"description":"Melt oil, sauté onion, then garlic and ginger. Toast spices, then tomato paste, coat chicken. Reduce chicken stock by half (5 min), then add coconut, chickpeas and salt. Simmer rapidly 8 min, stand 5 min then serve over rice.","images":[],"step":1},{"title":"Sauté","description":"Melt the coconut oil in a large pot over medium high heat (or a large deep skillet). Add the onion and cook for 2 minutes, until translucent. Add the garlic and ginger, stir constantly for 30 seconds (scrape base if it starts to stick).","duration":2,"images":[],"step":2},{"title":"Toast spices","description":"Add the curry powder, turmeric and cumin. Stir for 15 seconds, taking care to make sure it doesn''t stick and burn on base (if it does, add splash of water).","duration":0.25,"images":[],"step":3},{"title":"Coat chicken","description":"Add tomato paste and stir to coat all the onion, then add the chicken and stir to coat.","images":[],"step":4},{"title":"Reduce chicken stock 5 minutes","description":"Add the chicken stock, stir well, then once it starts bubbling, simmer rapidly for 5 minutes to reduce the liquid, stirring once in a while (adjust heat as needed, we want rapid bubbles - this is a speedy recipe remember!).","duration":5,"images":[],"step":5},{"title":"Simmer 8 minutes","description":"Add the coconut cream, chickpeas and salt. Stir well, bring back up to a simmer then simmer rapidly for 8 minutes, stirring every now and then. The sauce should be creamy but a little thinner than you''d expect.","duration":8,"images":[],"step":6},{"title":"Serve","description":"Remove the pot from the stove and leave to cool for 5 minutes, during which time the sauce will thicken a bit more. Serve over basmati rice with a drizzle of yogurt and sprinkle of fresh coriander. I wouldn''t say not to a warm naan or flatbread either. :)","duration":5,"images":[],"step":7}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Indian","Western"],"categories":["chicken-recipes","curry-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_28036739f338', 'en', 'US', 'JB''s Chicken au Poivre (Creamy Peppercorn Sauce)', 'Recipe above video. Inspired by Steak with Creamy Peppercorn Sauce (Steak au Poivre), one of my all-time favourites. This recipe has the same creamy pepper sauce with brandy and cream, just swapped for golden chicken. “Chicken au Poivre” is a perfect quick mid-week dinner with a French accent!', 'https://www.recipetineats.com/tachyon/2026/02/Chicken-Au-Poivre_4-copy.jpg', 8, 20, 28, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.2, "unit": "jar of 50g"}}, {"id": "ing_brandy", "quantity": {"value": 0.333, "unit": "unit"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}]', '[{"ingredients":["2 large chicken breasts (, skinless & boneless (250–300g / 8–10oz each) (Note 1))","3/4 tsp cooking salt / kosher salt","2 tbsp vegetable oil (, or any other neutral flavoured oil)"]},{"ingredients":["2 tsp whole black peppercorns (, coarsely crushed (Note 2))","1/3 cup brandy or cognac (, or masala (Note 3))","1 1/2 cups beef stock / broth (, low sodium (Note 4))","3/4 cup thickened / heavy cream (, or any other full fat cream)"],"purpose":"SAUCE AU POIVRE"}]', '[{"description":"Season chicken with salt. Sear in oil until golden. Remove. Deglaze with cognac. Add beef stock, simmer for 4 minutes . Pour cream, add pepper and simmer for 5 minutes. Return chicken, cook for 3 minutes while basting. Serve immediately.","duration":4,"images":[],"step":1},{"title":"Prepare the chicken","description":"Cut each chicken breast in half horizontally to make 4 thin steaks and sprinkle both sides with salt (If you’re wondering why I don’t season the chicken with pepper it’s because once combined with the sauce, it would make the dish too peppery.)","images":[],"step":2},{"title":"Sear the chicken","description":"Heat oil in a large pan (28cm / 11\") over high heat. Add chicken and cook 2–3 minutes per side until golden. Remove to a plate and rest (don’t cover). If you think your chicken is still a little bit under after resting, don’t worry it will finish cooking later in the sauce.","images":[],"step":3},{"title":"Deglaze with brandy","description":"TURN THE STOVE OFF to avoid the brandy catching fire (unless you want to flambé). Then carefully pour the brandy in. Be careful, it will sizzle hard, that’s normal. Let it bubble for 20-30 seconds to let alcohol burn off, reduce by about 2/3 (turn the stove on if needed). Scrape the fond at the base of the pan well to release all that flavour. (Note 5 & 6)","duration":0.4166666666666667,"images":[],"step":4},{"title":"Beef stock","description":"Turn the heat back on high. Add beef stock. Simmer rapidly for 4 minutes, until reduced by half.","duration":4,"images":[],"step":5},{"title":"Cream","description":"Stir in cream and crushed pepper. Lower the heat to medium high. Simmer for 3-4 minutes, to reduce the sauce until it thickens enough to lightly coat the back of a spoon. Stir and scrape the sides of the pan as it reduces. Keep in mind that some stoves run stronger than others. If the heat is gentler, the sauce may take a little longer to reduce, so just allow a bit of extra time.","duration":3.5,"images":[],"step":6},{"title":"Simmer","description":"Turn heat down to medium. Return chicken and resting juices to the pan. Cook 2–3 minutes, spooning the sauce over the chicken, until it is warmed through and the sauce darkens in colour and thickens a little more. When you drag a spoon through the pan, the sauce should slowly flow back together. If it thickens too much, add a splash of cream or water to loosen.","images":[],"step":7},{"title":"Serve","description":"This dish is best served straight away. If it sits, the sauce can become too thick and the chicken be overcooked.","images":[],"step":8}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["French"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","dinner-tonight","jbs-recipes","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_60c11623ffdd', 'en', 'US', 'Kalimera''s Famous Greek Chicken Gyros', 'Recipe video above. This Chicken Gyros recipe was given to me by Thomas Deliopoulos, the owner of Kalimera Souvlaki Art which is a wildly popular gyros bar in Melbourne. It''s ridiculously, unbelievably, eye-rollingly good that has top chefs like Australia''s Ben Shrewry and New York Times food critic Sam Sifton raving!Thomas’s secret is a touch of curry powder in the marinade. Yes, really!At Kalimera, the chicken is cooked on a vertical spit layered with fat, but even on the BBQ or stove, it’s ridiculously good. I''ve made it for many people now, and everyone is nuts for it!', 'https://www.recipetineats.com/tachyon/2025/10/Kalimera-Greek-Chicken-Gyros_8.jpg', 20, 10, 1470, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.25, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.15, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_thick_cut_chips", "quantity": {"value": 400.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.3, "unit": "tub of 500g"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.113, "unit": "jar of 400g"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 9.0, "unit": "head"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_bread", "quantity": {"value": 5.0, "unit": "loaf"}}]', '[{"ingredients":["1.25 kg / 2.5 lb chicken thighs, skinless boneless"]},{"ingredients":["1 tbsp sweet paprika (ie regular paprika, not smoked not spicy)","1 tbsp mustard powder (substitute with Dijon mustard)","1 tbsp dried oregano (Greek, if you''ve got it)","1/2 tbsp curry powder (, mild not spicy *secret ingredient!* (Note 2))","1 1/2 tsp cooking salt / kosher salt (halve if using table salt, +50% if using flakes)","1/2 tsp black pepper","1/3 cup extra virgin olive oil"],"purpose":"Kalimera''s chicken gyros marinade"},{"ingredients":["400g / 14oz thick-cut chips (, frozen - optional (Note 3))","Pinch table salt (, for the chips (or chicken salt))"],"purpose":"Hot chips"},{"ingredients":["1 cup plain yoghurt (, preferably Greek or Greek-style)","3 tbsp whole-egg mayonnaise (, substitute regular mayonnaise)","3 tbsp extra virgin olive oil","2 tbsp yellow American mustard ((yes, really!) - substitute with Dijon mustard, not hot English mustard, too spicy)","2 tsp garlic powder","2 tsp sweet paprika","1/2 tsp cooking salt / kosher salt"],"purpose":"Kalimera gyros sauce:"},{"ingredients":["2 tomatoes (, halved and sliced)","3 cups cos lettuce (romaine) (, finely sliced (5mm / 0.2\"))","1/2 small red onion (, diced (5mm / 0.2\" squares))","5 x 20cm / 8\" pita breads, (the slightly bready kind if you can (Note 5))"],"purpose":"To serve"}]', '[{"description":"Marinate chicken overnight (minimum 3 hours). Mix sauce, make chips. Cook chicken, rest 3 minutes, assemble gyros as follows: Sauce, chicken, lettuce, tomato, onion, chips, sauce. Fold, devour!","images":[],"step":1},{"title":"Marinate chicken","description":"Mix the marinade ingredients in a large bowl. Add the chicken and mix well to coat. Marinate in the fridge for 24 hours (absolute minimum 3 hours!)","images":[],"step":2},{"description":"Before cooking:","images":[],"step":3},{"title":"Sauce first","description":"Mix the ingredients in a bowl and set aside for at least 20 minutes to let the flavours meld.","images":[],"step":4},{"title":"Chips next","description":"If using hot chips, make them before cooking the chicken using whatever method suits - baked, fry, air fry. (I bake for convenience and fry to impress.) Season with salt to taste (sorry, you''re going to have to eat one!) Keep them warm in a 100°C/200°F oven while you cook the chicken.","images":[],"step":5},{"description":"Cooking the chicken gyros","images":[],"step":6},{"title":"BBQ option (recommended!)","description":"Preheat the BBQ on medium high (the grill side preferred, flat iron also works). No need to oil the grills. Cook the chicken for 3 - 4 minutes on each side until deep golden with slightly charred edges.","duration":3.5,"images":[],"step":7},{"title":"Stove cook","description":"Heat a large non stick pan over medium high heat (no oil required). Cook the chicken in batches for 3 - 4 minutes on each side until deep golden and cooked through (internal temperature 72°C/162°F). Give the pan a quick wipe with paper towels between batches, to remove excess black bits.","duration":3.5,"images":[],"step":8},{"title":"Remove & rest","description":"Remove chicken onto a tray. Loosely cover with foil and rest for 3 minutes, then slice into 1 cm / 0.4\" pieces.","duration":3,"images":[],"step":9},{"description":"Heat the pita bread until warm and pliable. Honestly, microwave is so easy (stack on plate, 45 sec - 1 1/2 minutes on high). For stove, brush each side with water then heat in lightly oiled non-stick pan for 1 minute on each side (medium high), don''t let it go crispy else it will crack when folded.","duration":1,"images":[],"step":10},{"title":"Wrapping","description":"Spread 3 tablespoons of the sauce down the middle. Pile the chicken onto the sauce, add lettuce and tomato on one side. Sprinkle with red onion, pile chips on top, drizzle with more sauce. Fold to enclose, wrap in foil to keep everything in place.","images":[],"step":11},{"description":"Serve gyros with extra sauce for dunking!","images":[],"step":12}]', '["egg","milk","mustard"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Greek"],"categories":["chicken-recipes","greek-recipes","mediterranean-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4827ac1b72ac', 'en', 'US', 'JB''s Chicken Chasseur', 'Recipe video above. Chicken Chasseur (chasseur is French for “hunter”) is a classic French dish made with pieces of chicken cooked in a rich mushroom and tomato sauce with a gentle touch of brandy, finished with fresh tarragon. It’s rustic and cosy, and it was the first recipe I learned to master at cooking school back in France. - JB', 'https://www.recipetineats.com/tachyon/2025/10/Chicken-Chasseur-JB_7.jpg', 15, 45, 60, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_brandy", "quantity": {"value": 0.25, "unit": "unit"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.625, "unit": "L"}}, {"id": "ing_tarragon", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}]', '[{"ingredients":["4 chicken thighs, bone-in, skin on (~250g/8oz each) (Note 1)","4 chicken drumsticks (Note 1)","3/4 tsp cooking salt / kosher salt","1/2 tsp black pepper","3 tbsp plain flour (all-purpose flour)","2 tbsp vegetable oil (or any other neutral flavoured oil)","30g / 2 tbsp unsalted butter"]},{"ingredients":["400g / 14oz white mushrooms (, sliced 6mm/0.2”)","2 onions (, brown or yellow, halved then sliced 6mm/0.2” thick)","3 garlic cloves (, finely minced)","1/4 cup brandy (Note 2)","1/2 cup chardonnay or other dry white wine (Note 3)","3 tbsp tomato paste","2 1/2 cups beef stock (, low-sodium (note 4))","3/4 tsp cooking salt/kosher salt","1/4 tsp black pepper","30g / 2 tbsp unsalted butter (, COLD and cubed (KEEP REFRIGERATED until required) )","1 tbsp fresh tarragon (, finely chopped (Note 5))"],"purpose":"Sauce Chasseur"},{"ingredients":["Creamy mashed potato (or rice or small pasta)"],"purpose":"For serving"}]', '[{"description":"Abbreviated Recipe","images":[],"step":1},{"description":"Season and flour the chicken, then brown in oil and butter. Remove. Sauté mushrooms and onion, add garlic briefly, then pour in brandy and wine to reduce. Stir in tomato paste for 1 minute, then stock, salt, and pepper. Return chicken, simmer covered 10 minutes then uncovered for 20 minutes until tender. Finish with cold butter and fresh tarragon.","duration":1,"images":[],"step":2},{"title":"Season the chicken","description":"Pat the chicken dry thoroughly with paper towels. This removes surface moisture, allowing the skin to brown properly and avoiding splatter. Season with salt and pepper on all sides. Coat in flour, shaking off excess. This helps develop a golden crust and also thickens the sauce later.","images":[],"step":3},{"title":"Brown the Chicken","description":"Heat vegetable oil in a large (30cm/12\") skillet (with lid) over medium-high heat. Add butter, once melted and foaming, place thighs skin-side down. Sear for 5 minutes until golden and crispy. Flip and cook the other side for 1 minute. Transfer to a plate. Add the drumsticks and brown them on 3 sides, about 2 minutes per side. Don’t rush this step – browning adds depth of flavour. Transfer drumsticks to the plate with the thighs. ⚠️ Be mindful when searing skin-on chicken pieces, the skin can pop and hot oil may splash.","duration":5,"images":[],"step":4},{"title":"Onion, mushrooms and garlic","description":"In the same pan, increase the heat to high and add the mushrooms and onions. Cook for 5 minutes, stirring occasionally, until the mushrooms start to wilt. Add the garlic and cook for 30 seconds until fragrant.","duration":5,"images":[],"step":5},{"title":"Brandy and wine","description":"Pour in the brandy. Carefully flambé (ignite) if desired - let it burn until the flame dies out by itself (~10 seconds). Flambéing intensifies the aroma - and puts on a show! Or simply let it bubble for 20–30 seconds until the alcohol burns off. Add the white wine. Let it simmer rapidly to reduce by half. Use a wooden spoon to scrape up the fond (the browned bits stuck to the bottom), which is a crucial ingredient to the creation of our sauce. It will make it rich and complex.","duration":0.4166666666666667,"images":[],"step":6},{"title":"Tomato and stock","description":"Stir in the tomato paste, cook for 1 minute. Then add the stock, salt, and pepper.","duration":1,"images":[],"step":7},{"description":"Cooking","images":[],"step":8},{"title":"Simmer","description":"Return the chicken to the pan skin-side up, nestling them into the stock. Bring the sauce to a simmer, then reduce the heat to medium (bubbling constantly but not rapidly). Cover with a lid and simmer for 10 minutes. Then remove the lid and simmer uncovered for a further 20 minutes. This allows the sauce to reduce and concentrate while the chicken finishes cooking.","duration":10,"images":[],"step":9},{"title":"Reduce sauce slightly","description":"Transfer the cooked chicken to a plate. Turn the heat to medium-high, and simmer the sauce for 3 minutes to reduce slightly.","duration":3,"images":[],"step":10},{"title":"Finish the sauce","description":"Turn off the heat. Scatter half of the COLD butter cubes in then stir until melted. Scatter the rest of the butter cubes in then stir again until melted. This is a classic emulsification technique that gives the sauce a silky, glossy finish (monter au beurre) as well as thickening it slightly. (Note 6)","images":[],"step":11},{"title":"Serve","description":"Bring the sauce to a gentle simmer again. Return the chicken to the sauce and sprinkle over the fresh tarragon. Take it to the table and serve out of the pan with creamy mashed potato.","images":[],"step":12}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["French"],"categories":["chicken","chicken-drumstick-recipes","chicken-recipes","jbs-recipes","mains","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d838ea82fee0', 'en', 'US', 'Nando''s Portuguese chicken and rice - one pot recipe', 'Recipe video above. My friend calls this Portuguese biryani. I know there''s 1 billion Indians crying right now, but it describes this perfectly! A Nando''s* inspired recipe with Peri Peri rub sprinkled on chicken then cooked in the same pot with a Nando''s copycat spicy rice. Essentially a one pot version of Nando''s paella! It''s seriously good, the rice alone puts Nando''s to shame. Don''t skip the Peri-naise. :-)* Portuguese chicken restaurant chain, bit of a cult following. Do you have it where you are?UPDATE: A few readers left feedback saying they thought it was bland, if you use chicken stock/broth, the spices and the amount of salt specified in the ingredients, this just isn''t possible! :) Please make sure you''re using the right amount of salt!', 'https://www.recipetineats.com/tachyon/2025/09/Portuguese-chicken-and-rice-one-pot_9.jpg', 15, 25, 40, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.025, "unit": "bunch"}}, {"id": "ing_cayenne", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.015, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 1.0, "unit": "jar of 50g"}}, {"id": "ing_turmeric", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.562, "unit": "L"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_perinaise_pink_sauce_or_any_of_the_other_sauce_suggestions_listed_in_post", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["500g/1 lb chicken thighs (, boneless, skinless, cut into bite size pieces (Note 1))"]},{"ingredients":["2 tsp paprika (regular/sweet, not spicy)","1 tsp garlic powder (substitute large garlic clove, minced)","1 tsp dried oregano","1/4 tsp coriander","1/4 tsp cayenne (can omit for zero spicy)","1 tbsp brown sugar","1 tsp cooking salt / kosher salt (+50% for flakes, halve for table salt)","1 tbsp extra virgin olive oil","1/2 tbsp lemon juice (substitute apple cider vinegar)"],"purpose":"Portuguese chicken seasoning:"},{"ingredients":["2 tbsp extra virgin olive oil","2 garlic cloves (, finely minced)","1 small onion (, diced)","1 red capsicum ((bell pepper), deseeded, chopped into 1cm/0.4\" squares)","1 1/2 cups basmati rice (or long grain rice or medium grain rice) (Note 2)","1/4 tsp chilli flakes / red pepper flakes (omit for not spicy)","2 tsp turmeric powder","2 1/4 cups chicken stock/broth (, low sodium)","1 cup frozen peas (still frozen)","1/2 tsp cooking salt / kosher salt (+50% for flakes, halve for table salt)"],"purpose":"Nando’s copycat spicy rice (or not):"},{"ingredients":["Perinaise ((I use the quick dry spices version), Pink Sauce (Note 4) or any of the other sauce suggestions listed in post)","Green onion (, finely sliced)"],"purpose":"Garnishes:"}]', '[{"description":"Toss chicken with seasoning, sear, remove. Sauté onion and garlic, then capsicum, stir in rice, add everything else + chicken. Steam 15 minutes covered, rest 10 minutes. Serve!","images":[],"step":1},{"title":"Season chicken","description":"Mix the Portuguese Chicken Seasoning ingredients in a bowl. Add chicken and toss to coat. Set aside while you prepare the rest of the ingredients, or overnight if you want (though not necessary).","images":[],"step":2},{"title":"Sear","description":"Heat the 2 tablespoons of oil in a large heavy based pot over high heat. Add the chicken and cook until the outside is sealed and gets a bit of colour (it won''t go golden). Remove with a slotted spoon into a bowl, leaving oil behind in the pot.","images":[],"step":3},{"title":"Sauté","description":"Add garlic and onion into the pot, cook for 1 minute. Add capsicum and cook for 1 1/2 minutes or until onion is translucent.","duration":1,"images":[],"step":4},{"title":"All in","description":"Add rice and stir to coat in the tasty oil. Add remaining rice ingredients, then scatter the chicken evenly across the surface. Also add any juices accumulated in the bowl. Stir, bring to a simmer, then put the lid on and lower heat to medium low so it''s simmering gently. (Note 3)","images":[],"step":5},{"title":"Cook 15 minutes","description":"Cook for 15 minutes, no peeking, no stirring! Liquid should be absorbed - tilt pot and lift lid for quick peek.","duration":15,"images":[],"step":6},{"title":"Rest 10 minutes","description":"Remove pot from the stove and leave to rest for 10 minutes with the lid still on.","duration":10,"images":[],"step":7},{"title":"Fluff & serve","description":"Remove lid, gently toss the rice. Spoon into bowls, drizzle over Peri-naise, sprinkle with green onions and serve!","images":[],"step":8}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Portuguese inspired"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","mains","one-pot-recipes","quick-and-easy","rice-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f375a37487ed', 'en', 'US', 'My go-to Chicken Breast recipe', 'Recipe video above. Ready in 12 minutes, this is my current go-to chicken breast recipe. AKA Pan-Seared Country Seasoned Chicken Breast with Butter Sauce, it''s fast, simple, not-boring and you can make it anytime with pantry staples!Simple country-inspired seasoning tossed with the tiniest amount of flour so the chicken gets a lovely crust on it, served with a butter sauce made in the same pan so it gets flavour from the residual seasoning.Mix and match magic: Skip the sauce and just serve the seasoned chicken, or skip the spices and let the butter sauce shine with a simple salt-and-pepper seared chicken.', 'https://www.recipetineats.com/tachyon/2025/07/Anytime-Chicken-Breast-in-white-wine-sauce_5.jpg', 5, 7, 12, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 20.0, "unit": "block of 250g"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 20.0, "unit": "block of 250g"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["2 large chicken breasts (250 - 300g/8 - 10 oz each), each cut in half horizontally to form 4 steaks, no need to pound (Note 1)","20g/ 1 1/2 tbsp unsalted butter (or 1 1/2 tbsp olive oil)"]},{"ingredients":["1 tsp paprika (, regular/sweet (or smoky))","1/2 tsp onion powder (or more garlic)","1/2 tsp garlic powder (or more onion)","1/4 tsp cumin (sub coriander, thyme leaves crushed between fingers, or omit)","3/4 tsp cooking salt / kosher salt (halve for table salt, +50% for flakes)","1/8 tsp black pepper","1 1/2 tbsp flour (, plain/all-purpose, GF (Note 2))"],"purpose":"Savoury Seasoned Crust:"},{"ingredients":["1/3 cup dry white wine ( or chicken stock (low sodium), sub water (Note 3))","30g/ 2 tbsp unsalted butter","1 tbsp roughly chopped parsley (, optional but recommended)"],"purpose":"Butter sauce:"}]', '[{"description":"Dust chicken with Seasoning, pan fry in the butter, remove. Deglaze with wine, melt in butter, serve sauce on chicken.","images":[],"step":1},{"title":"Season","description":"Mix the Seasoning ingredients in a bowl. Sprinkle on each side of the chicken, spreading with fingertips to coat evenly, then shake off excess.","images":[],"step":2},{"title":"Sear","description":"Melt the butter in a large non-stick pan over high heat. Cook chicken for 2 1/2 minutes on each side until deep golden, or until the internal temperature reaches 67C/153F. Remove onto a plate.","images":[],"step":3},{"title":"Pan sauce","description":"Lower then heat to medium high. Add the wine and simmer rapidly for 1 - 1 1/2 minutes, scraping the pan with a rubber spatula to loosen the golden bits into the sauce, until it''s reduced by half. Add the butter and let it melt, mixing well to combine. (Note 4 on sauce amount)","images":[],"step":4},{"title":"Serve","description":"Serve chicken with sauce and sprinkled with parsley. Enjoy!","images":[],"step":5}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3c418264c155', 'en', 'US', 'Whipped ricotta one pot chicken pasta', 'Recipe video above. Meet your new favourite one-pot recipe! I''m sharing this as a guest-worthy dish based on a simple mid-week recipe. It''s quite amazing how just a little dollop of creamy ricotta can transform a regular bowl of pasta into something you''d expect to get at a rustic trattoria! Love how it melts into a flood of creamy goodness on your hot bowl of pasta - thicker than cream, and much lower fat.', 'https://www.recipetineats.com/tachyon/2025/04/One-pot-whipped-ricotta-chicken-pasta-with-sun-dried-tomatoes_6a.jpg', 10, 20, 30, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_tomato", "quantity": {"value": 0.22, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 220.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.22, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.083, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.22, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.7, "unit": "pack of 500g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_basil", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_ricotta", "quantity": {"value": 0.3, "unit": "tub of 250g"}}, {"id": "ing_milk", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}]', '[{"ingredients":["500g/1 lb chicken thigh fillets (, cut into small bite size pieces (or breast or tenderloin))","1/2 tsp cooking salt/kosher salt","1/4 tsp black pepper"],"purpose":"Chicken:"},{"ingredients":["220g/ 7 oz jar sun-dried tomato stripes in oil (, drained (RESERVE OIL) (Note 1))","3 tbsp oil (from the sun dried tomato jar)","1 small onion (, finely diced)","2 garlic cloves (, finely minced)","1 tbsp tomato paste (ok if you don''t have)","1/4 cup dry white wine (, optional (Note 2))","400g/14 oz canned crushed tomato","350g / 12oz fusilli pasta (spirals) (, penne, ziti, macaroni, small shells or similar, uncooked)","1 litre / 4 cups chicken stock/broth (, low sodium (sub water plus 1/2 tsp salt))","1/4 tsp cooking salt/kosher salt","1/4 tsp black pepper","1 cup basil leaves (, roughly chopped (can survive without), plus extra for garnish)"],"purpose":"Pasta:"},{"ingredients":["1/2 cup ricotta ((Paesanella is my preferred brand), full fat)","4 tbsp milk (, preferably full fat)","1/4 cup (packed) finely grated parmesan (, sub pinch of salt)"],"purpose":"Whipped ricotta:"}]', '[{"title":"Whipped ricotta","description":"Put the ingredients in a bowl. Whisk vigorously for 10 to 15 seconds until it becomes the texture of softly whipped cream. Add milk to loosen, if needed.","duration":0.20833333333333334,"images":[],"step":1},{"title":"Seal chicken","description":"Heat sun dried tomato oil in a large heavy based pot over high heat. Add the chicken. sprinkle with salt and pepper. Cook for 3 minutes until the outside is sealed but the inside is still raw. Remove with slotted spoon into a bowl.","duration":3,"images":[],"step":2},{"title":"Sauté","description":"In the same pot, add the onion and garlic. Cook for 3 minutes until the onion is translucent. Add the tomato paste and oil drained sun dried tomatoes (reserve any remaining oil for another use). Cook for 1 minute.","duration":3,"images":[],"step":3},{"title":"Deglaze","description":"Add white wine and let it simmer rapidly for 1 - 2 minutes, stirring regularly, until mostly evaporated.","duration":1.5,"images":[],"step":4},{"title":"Cooking liquid","description":"Add pasta and cooked chicken along with any juices accumulated in the bowl. Stir to coat in all the tasty flavours. Add the stock, canned tomato, salt and pepper.","images":[],"step":5},{"title":"Cook 15 minutes","description":"Give it a good stir, let it come to a boil then lower the heat to medium high so it''s simmering rapidly but not boiling like crazy. Cook for 15 minutes (no lid), stirring every 2 minutes or so at first then more regularly towards the end, so the base doesn''t catch. Lower the heat a touch towards the end, if needed.","duration":15,"images":[],"step":6},{"title":"How to tell it''s done","description":"Most of the liquid should be absorbed and the pasta should be just cooked (al dente), though still a little soupy (that''s good, it gets absorbed quickly while serving). Stir in the basil.","images":[],"step":7},{"title":"Serve","description":"Transfer into a serving bowl or divide between bowls. Dollop the whipped ricotta on top then randomly smear (or let everyone do that themselves), it will get all melty. Dig in!","images":[],"step":8}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken","chicken-recipes","dinner-tonight","mains","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_81e9be2d7579', 'en', 'US', 'Lebanese Lemon Garlic Chicken - Al Aseel copycat', 'Recipe video above. A copycat of a signature dish at Al Aseel, a popular Lebanese restaurant in Sydney! Chicken is marinated in a bold lemon-garlic yogurt mix, then smothered in a garlicky lemon yogurt sauce. Warm yogurt may sound unusual, but one bite will win you over! Serve with pita bread and Fattoush.PS. Please measure the garlic - too much is harsh, too little is sad.PPS. The salt might seem a lot, but please trust, it''s not salty!', 'https://www.recipetineats.com/tachyon/2025/04/Lebanese-lemon-garlic-chicken-Al-Aseel_2.jpg', 15, 10, 25, 3, '[{"id": "ing_chicken", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.12, "unit": "tub of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.09, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_parsley", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_extra_virgin_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["500g/ 1lb chicken tenderloin (or breast), cut into 4cm / 1.5\" squares, large vein cut out (Note 1)"]},{"ingredients":["4 tbsp Greek or plain yogurt","3 tbsp lemon juice","1 tbsp garlic (, finely grated or crushed using garlic press (~4 big cloves))","1 tbsp olive oil","1 tsp cooking salt / kosher salt (1/2 tsp table salt, 1 1/4 tsp flakes)"],"purpose":"Lemon garlic marinade:"},{"ingredients":["1 cup Greek or plain yogurt (, full fat essential here!)","3/4 tsp garlic (, finely grated or crushed using garlic press (~1 clove))","2 tbsp extra virgin olive oil","1 tbsp lemon juice","1 tbsp tahini (hulled), or extra 1 tbsp olive oil (Note 3)","1 tbsp+ water","1 tsp cooking salt / kosher salt (1/2 tsp table salt, 1 1/4 tsp flakes)"],"purpose":"Lemon garlic yogurt sauce:"},{"ingredients":["2 tbsp olive oil (, for cooking)","1 tsp parsley (, roughly chopped (or equal amounts mint and parsley))","Lemon wedges and extra virgin olive oil (, for garnish)","Lebanese bread (for sauce mopping (recommended))"],"purpose":"Cooking & serving:"}]', '[{"title":"Marinade chicken 12","description":"24 hrs. Cook in 2 batches. Whisk sauce, rest 1 hr, warm just before serving. Smother chicken, serve!","images":[],"step":1},{"title":"Marinade","description":"Mix the marinade ingredients in a bowl. Add the chicken, toss to coat then refrigerate to marinate for 12 - 24 hours (Note 2).","images":[],"step":2},{"title":"Sauce","description":"Put the sauce ingredients in a microwaveable bowl and whisk to combine. Set aside for 1 hour + to let the garlic flavour meld. (Note 4)","images":[],"step":3},{"title":"Cook chicken","description":"Drain off excess marinade from the chicken. Heat 1 tbsp oil in a large non stick pan over high heat. Place half the chicken in and cook for 1 1/2 - 2 minutes on each side until golden. Remove onto a plate.","images":[],"step":4},{"title":"Repeat","description":"Scrape out / roughly wipe loose black bits out of the pan. Reheat remaining oil and cook remaining chicken. Rest for 2 minutes.","duration":2,"images":[],"step":5},{"title":"Warm sauce","description":"While the chicken is resting, microwave for 40 seconds to warm (but not hot) then give it a good whisk. Taste and add more lemon for tangier, or more water to loosen (some yogurts are thicker than others).","duration":0.6666666666666666,"images":[],"step":6},{"title":"Serving","description":"Spread half the sauce in a shallow bowl. Use a spatula to transfer the chicken onto the yogurt. Spoon over remaining sauce, finish with a swish of olive oil and sprinkle of parsley. Serve!","images":[],"step":7}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["lebanese"],"categories":["chicken-breast-recipes","chicken-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_371c245bc354', 'en', 'US', 'Chicken and Leek Pie', 'Recipe video above. Tender bites of chicken and slippery pieces of sweet leek smothered in a creamy white-wine thyme infused sauce, bubbling under a golden puff pastry crust. Chicken and Leek Pie is comfort food we dream about!I cut my leeks in a specific way. I like larger pieces rather than thinly sliced rings which get too soggy-stringy for my taste. Also, if you don''t like / can''t get puff pastry, cover this pie in mash (like Cottage Pie!) or use a homemade shortcrust pastry.Make one big pie like I''ve done, or ramekins (makes 4 large, 5 regular). For a pie with a base, replace the filling in my Family Meat Pie (there will be leftover filling) or individual meat pies. See the FAQ above for the gluten-free option.', 'https://www.recipetineats.com/tachyon/2024/09/Chicken-and-Leek-Pie_9.jpg', 25, 60, 145, 5, '[{"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_bacon", "quantity": {"value": 0.4, "unit": "pack of 200g"}}, {"id": "ing_eek", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_celery", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_wine", "quantity": {"value": 0.111, "unit": "bottle of 750ml"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_thyme", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}]', '[{"ingredients":["50g/ 3 1/2 tbsp unsalted butter (, divided)","750g/ 1.5lb chicken thighs (, skinless, boneless, cut into 1.8 cm / 3/4\" bite size pieces (Note 1))","1/4 tsp each black pepper and cooking salt (kosher salt)"]},{"ingredients":["80g / 3 oz streaky bacon (, chopped into 1cm / 0.4\" squares (Note 2))","2 leeks (Note 3)","2 celery stems (, sliced 4 mm / 0.2\" thick (cut thick end in half lengthways first))","2 garlic cloves (, finely minced)","1/3 cup chardonnay (or other dry white wine (Note 4))","1/4 cup flour (plain / all-purpose)","1 tbsp dijon mustard (Note 5)","2 thyme sprigs (or 1/2 tsp dried thyme)","2 bay leaves (preferably fresh, else dried)","1 cup chicken stock / broth (, low sodium)","1 cup thickened / heavy cream (or any full-fat cream, or sub milk for lower fat)","1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper"],"purpose":"Pie filling:"},{"ingredients":["2 x 20cm / 8\" frozen butter puff pastry sheets (, or single sheet large enough to cover baking dish, 360g / 12 oz (Note 6))","1 egg (, yolk and whites separated, lightly whisked)"],"purpose":"Pie:"}]', '[{"description":"Sear surface of chicken in half butter, remove. Cook bacon 1 minute, then leek, celery and garlic 5 minutes. Deglaze with wine, melt remaining butter, then cook flour 1 minute. Add stock, then remaining Filling ingredients. Add chicken, thicken sauce (~5 minutes).","images":[],"step":1},{"description":"Cool filling 1 hour, assemble pie with double layer puff on rim, brush lid with yolk, bake 45 minutes 200°C/375°F (180°C fan).","images":[],"step":2},{"description":"Cut leek (step photos above helpful):","images":[],"step":3},{"description":"Trim the reedy dark green ends and root off, then cut in half. Cut each piece in half lengthways. Remove the outer 5 to 6 layers (keep them together), lay them flat, cut in half lengthways then into 1.8cm / 3/4\" squares. Cut the inner core into 2cm / 0.8\" pieces.","images":[],"step":4},{"title":"Chicken","description":"Melt half the butter in a large pan over high heat. Add the chicken, salt and pepper. Cook until the surface changes from pink to white (inside still raw), then remove into a bowl using a slotted spoon. Leave residual butter and chicken juices in the pan.","images":[],"step":5},{"title":"Sauté","description":"In the same pan, cook the bacon for 1 minute. Add the leek, celery and garlic. Cook for 5 minutes until the celery is softened. Don''t let the leek brown - lower the heat if needed.","duration":1,"images":[],"step":6},{"title":"Deglaze","description":"Add the wine and simmer rapidly on high heat, stirring, until it is mostly evaporated.","images":[],"step":7},{"title":"Roux","description":"Lower the heat to medium. Add the remaining butter. Once it melts, sprinkle the flour across the surface (don''t dump in one place) and stir for 1 minute.","duration":1,"images":[],"step":8},{"title":"Creamy sauce","description":"While stirring, slowly pour the stock in. The mixture will thicken into a thick sauce once combined. Then add the mustard, cream, thyme, bay leaves, salt and pepper. Stir to combine, then add the chicken including all the juices accumulated in the bowl.","images":[],"step":9},{"title":"Simmer","description":"Increase the heat, stir to combine. Once it comes to a simmer, reduce the heat to medium high. Simmer for 5 minutes, stirring regularly, or until the sauce is a thick creamy consistency you want in the finished pie (ie sauce thickness now = thickness in the baked pie, see Note 7).","duration":5,"images":[],"step":10},{"title":"Cool","description":"Remove the pan from the stove and cool for 1 hour. (You can also store in fridge for 3 - 4 days).","images":[],"step":11},{"description":"Assembling and baking:","images":[],"step":12},{"description":"Preheat the oven to 200°C/375°F (180°C fan-forced). Use a 1.5 litre / 1.5 quart baking pan (Note 9) or 4 to 5 x ~350ml / 12 oz ramekins.","images":[],"step":13},{"title":"Connect puff pastry sheets (if needed)","description":"Semi-thaw the puff pastry (Note 6). Brush the edge of one sheet with egg white, then overlap 0.5cm / 0.2\" with the other sheet to connect them. Use the back of a spoon to \"smear\" the pastry to hide the seam and firmly connect.","images":[],"step":14},{"description":"Cut out the pie lid (I use the dish as a cutting guide).","images":[],"step":15},{"title":"Optional strips for extra puffy edges (Note 8)","description":"Cut strips using the residual pastry to line the rim of the dish (if your dish has a thick rim, like mine) and place on the rim of the dish.","images":[],"step":16},{"description":"Fill the pie dish with the cooled filling and smooth the surface. Brush the pastry strips on the rim with egg white (if not using strips, don''t do this step) then cover with the puff pastry lid.","images":[],"step":17},{"description":"Brush the lid with egg yolk. Cut a small X in the middle.","images":[],"step":18},{"description":"Bake 45 minutes or until the surface is a deep golden brown. Rest 5 minutes then serve!","images":[],"step":19}]', '["egg","gluten","milk","mustard"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken","chicken-recipes","mains","quiches-tart-and-pie-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_60236f610f5d', 'en', 'US', 'Creamy chicken noodle soup with mini croutons', 'Recipe video above. A homemade version of instant cup-a-noodle-soup! Except, well, you know. It''s made with real ingredients. :)This is hearty, wholesome, cosy and surprisingly healthy. Creamy, but no cream!', 'https://www.recipetineats.com/tachyon/2024/07/Chicken-Noodle-Soup-51291.jpg', 15, 25, 40, 5, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_bacon", "quantity": {"value": 4.0, "unit": "pack of 200g"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_thyme", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_celery", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_corn", "quantity": {"value": 0.281, "unit": "can of 400g"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.4, "unit": "pack of 500g"}}, {"id": "ing_frozen_peas", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_parsley", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 0.188, "unit": "loaf"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}]', '[{"ingredients":["400g/10oz chicken breast (2 small), cut in half horizontally to form 2 thin steaks (sub boneless thighs)","1/4 tsp cooking salt / kosher salt","1/4 tbsp black pepper"]},{"ingredients":["4 strips streaky bacon (enough to cover base of pot)","30g/ 2 tbsp unsalted butter","1/2 onion (, finely diced)","2 garlic cloves (, finely minced)","2 sprigs thyme or 1/2 tsp dried thyme (optional)","2 celery stalks (, chopped (~0.5 x 1.2 cm / 1/5 x 1/2\" pieces))","1 carrot (, chopped (0.5 x 1 cm / 1/5 x 1/2\" pieces))","3/4 cup corn kernels (frozen thawed or canned drained)","4 tbsp flour","3 cups milk (, full fat best but low fat ok (non-dairy ok too))","2 cups low sodium chicken stock/broth","2 cups water","1 tsp cooking salt","1 1/3 cups (100g) broken angel hair pasta ( OR angel hair pasta / spaghetti broken into 6 pieces, or other small, spoon-able pasta)","3/4 cup frozen peas","1/2 tsp finely chopped parsley (, optional)"],"purpose":"Soup:"},{"ingredients":["1 cup bread ((crustless) cut into 7mm / 1/4\" cubes - sourdough type is crunchier, regular sandwich bread is fine too)","2 tsp olive oil","Pinch cooking salt / kosher salt"],"purpose":"Mini croutons:"}]', '[{"description":"Croutons & crispy bacon","images":[],"step":1},{"title":"Croutons","description":"Preheat the oven to 180°C/3450°F (160°C fan-forced). Toss the bread with the oil and salt. Bake for 8 to 10 minutes, tossing halfway, until golden and fully crisp (some breads take longer eg sourdough). Cool on the tray, set aside.","duration":9,"images":[],"step":2},{"title":"Season chicken","description":"Sprinkle both sides of the chicken with the salt and pepper.","images":[],"step":3},{"title":"Crispy bacon","description":"Place the bacon in a single layer in an un-heated, large pot. Turn the heat onto medium high then cook the bacon until golden on both sides (~2-3 minutes first side, 1 1/2 minutes second side). (Note 2). Remove bacon (leave fat in pot), drain on paper towels. It will crisp as it cools. Finely chop, set aside for garnish.","images":[],"step":4},{"title":"Cook chicken","description":"Using the same pot, still hot, cook the chicken in the tasty bacon fat for 1 1/2 minutes on each side until light golden. Remove onto a plate. Once cool enough to handle, chop into small 8 mm / 1/3\" cubes.","images":[],"step":5},{"title":"Broth","description":"Lower heat to medium high. In the same pot, melt the butter. Add the onion, garlic, celery, carrot, thyme sprigs. Cook 5 minutes until the carrot is softened, stirring regularly (don’t let the onion brown). Add flour and stir for 1 minute. While stirring, slowly pour the milk in. Once the flour is dissolved, add the stock, water and salt, then stir.","duration":1,"images":[],"step":6},{"title":"Simmer","description":"Turn the heat up to high and bring to a simmer, then lower the heat and simmer gently for 5 minutes, stirring every now and then. (The soup will seem thin, it thickens as the pasta cooks. Trust!)","duration":5,"images":[],"step":7},{"title":"Pasta","description":"Turn the heat back up to high. Add the pasta and corn. Cook for 5 minutes or until pasta is soft, adding the peas and chicken (including any juices pooled) for the last 2 minutes of cook time.","duration":5,"images":[],"step":8},{"title":"Serve","description":"Ladle into bowls, sprinkle with bacon, croutons and a pinch of parsley. Eat!","images":[],"step":9}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_98c0c9ef9775', 'en', 'US', 'One pot chicken risoni with crispy salami (orzo)', 'Recipe video above. Risoni - also known as orzo - in a creamy tomato parmesan sauce with juicy slices of seasoned chicken and lots of awesome crispy bits of golden salami! The better bacon - bolder flavour, and it doesn''t spit when you''re cooking it. :) The addition of chickpeas adds a soft nutty crunch and another layer of texture to this one-pan wonder that''s a cosy bowl of deliciousness! Total crowd pleaser.', 'https://www.recipetineats.com/tachyon/2024/01/One-pan-chicken-creamy-tomato-risoni-with-crispy-salami-2.jpg', 15, 0, 15, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_salami_stick", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_sage", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.833, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_wine", "quantity": {"value": 0.083, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.375, "unit": "pack of 500g"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}, {"id": "ing_baby_spinach", "quantity": {"value": 150.0, "unit": "bag of 250g"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_basil", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["1/2 tbsp olive oil","100g/ 3 oz salami stick (, cut into 3mm / 1/8\" thick rounds then chopped into small batons (Note 1))","2 x 250g / 8 oz chicken breasts ( (large), each cut in half horizontally to form 4 thin steaks (Note 2))"]},{"ingredients":["1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper","1/2 tsp garlic powder","3/4 tsp paprika","1/4 tsp sage powder (optional)"],"purpose":"Chicken spice mix:"},{"ingredients":["2 garlic cloves (, finely minced)","1/2 onion (, finely chopped)","1/4 cup chardonnay or other dry white wine (, optional (Note 3))","1/4 cup tomato paste","1 1/4 cups risoni/orzo (, uncooked (Note 4))","400g / 14 oz canned chickpeas (, drained (or other beans))","3 cups chicken stock (, low sodium (or veg stock))","1/2 tsp cooking / kosher salt","1/4 tsp black pepper","3/4 cup thickened / heavy cream (low-fat ok)","1/3 cup parmesan (, finely grated (I use store bought sandy type))","150g/ 5 oz baby spinach (or 4 cups kale pieces)","1/3 cup sun dried tomato (, chopped (optional) (Note 5))"],"purpose":"Creamy tomato parmesan risoni (orzo):"},{"ingredients":["2 tbsp roughly chopped basil (optional) (Note 5)"],"purpose":"Optional garnish"}]', '[{"title":"Spice Mix","description":"Mix the ingredients in a small bowl then sprinkle both sides of the chicken.","images":[],"step":1},{"title":"Crispy salami","description":"Heat the oil in a large non-stick pan over medium high heat. Cook the salami for 2 minutes, stirring constantly, until crispy and golden. Remove into a paper towel lined bowl using a slotted spoon, leaving the tasty salami fat in the pan.","duration":2,"images":[],"step":2},{"title":"Cook chicken","description":"In the same pan, cook the chicken for 3 minutes on each side until dark golden and just cooked through (internal temperature 67°C/153°F). Remove onto a plate and cover loosely with foil to keep warm.","duration":3,"images":[],"step":3},{"title":"Sauté","description":"Still on medium high, cook the garlic and onion for 1 1/2 minutes until the onion is translucent. Add the wine and let it simmer rapidly for a couple of minutes until mostly evaporated, stirring to dissolve the fond (gold bits) on the base of the pan into the wine.","images":[],"step":4},{"title":"Risoni (orzo)","description":"Add the tomato paste and stir for 1 minute to cook out the sour raw flavour. Add the risoni and stir to coat in the tomato paste. Add the chickpeas, chicken stock, salt, pepper.","duration":1,"images":[],"step":5},{"title":"Simmer","description":"Bring to a simmer, then cook for 8 minutes, stirring every minute or so, until the risoni is just about cooked. Lower the heat to medium as it gets thicker so the base doesn''t catch.","duration":8,"images":[],"step":6},{"title":"Cream & spinach","description":"Add the cream, parmesan, spinach and sun dried tomatoes (if using). Stir until the spinach is wilted then remove from the heat. The risoni should be oozy and tender. (Still firm? Note 6)","images":[],"step":7},{"title":"Finish","description":"Cut the chicken into thick slices. (Bit cool? Note 7) Spoon risoni into bowls. Top with the chicken, sprinkle with lots of crispy salami, parmesan and basil (if using). Dig in!","images":[],"step":8}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","dinner-tonight","mains","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a2fe549aa309', 'en', 'US', 'One-pan Baked Butter Chicken', 'Recipe video above. The miraculous, easy way to make butter chicken in the oven! Just put everything in a pan and pop it in the oven. That sauce is to-die for! Just like the real-thing, with a fraction of the effort.This doesn''t even need to be marinated because the flesh gets infused with flavour as it bakes. Not spicy at all, so this one for everyone!', 'https://www.recipetineats.com/tachyon/2023/11/One-pan-baked-butter-chicken_9.jpg', 10, 45, 55, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.15, "unit": "tub of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_turmeric", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_garam_masala", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_tomato", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_naan", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["1.2 kg/ 2.4lb (6 pieces) bone-in chicken thighs (, skin removed (Note 1))"]},{"ingredients":["1/2 cup plain yoghurt (, full fat)","1 tbsp lemon juice","1 tbsp ginger (, finely grated)","2 cloves garlic (, finely grated or crushed)","1 tsp turmeric powder","2 tsp garam masala (Note 2)","1/2 tsp chilli powder ((pure, not US blend) or cayenne pepper powder)","1 tsp ground cumin","1/2 tsp cooking salt / kosher salt"],"purpose":"Butter chicken marinade:"},{"ingredients":["2 tbsp/ 30g melted ghee or butter (Note 3)","1 cup tomato passata (US: tomato puree) (Note 4)","3/4 cup heavy / thickened cream (or regular cream, or coconut milk)","1 1/2 tsp white sugar","3/4 tsp cooking salt / kosher salt"],"purpose":"Butter chicken curry sauce:"},{"ingredients":["1/2 cup coriander leaves (cilantro) (, for garnish (optional))","Basmati rice (or other plain rice)","Naan (easy - no kneading required!)"],"purpose":"Serving:"}]', '[{"description":"Preheat oven to 200°C / 400°F (180°C fan-forced).","images":[],"step":1},{"title":"Coat chicken","description":"Mix the marinade ingredients in a bowl, then add the chicken and toss to coat.","images":[],"step":2},{"title":"Optional marinade","description":"overnight. (Note 5)","images":[],"step":3},{"title":"Assemble","description":"Mix Sauce ingredients in a 23 x 33cm / 9 x 13\" baking dish. Place chicken in, smooth side up. Scrape residual marinade out of bowl and dab onto chicken surface.","images":[],"step":4},{"description":"Bake 45 minutes, basting with sauce at the 30 minute and 40 minute mark. The sauce will change from pink to orangey-red (Note 6 for sauce thickening).","images":[],"step":5},{"title":"Serve","description":"Rest for 5 minutes. Then serve over basmati rice, garnished with coriander if desired! Naan for mopping would make everyone extra happy. :)","duration":5,"images":[],"step":6}]', '["milk"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["chicken","chicken-recipes","indian-recipes","mains","one-pot-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0feced2927c4', 'en', 'US', 'African coconut chicken curry - Kuku Paka', 'Recipe video above. Are you ready to discover the world''s easiest curry?? As in, a real one, made from scratch. Introducing - Kuku Paka! This chicken curry in a tomato coconut spiced sauce tastes like an Indian curry. Except it''s African, and you can get everything you need from your regular grocery store. For a strictly traditional version, sear the chicken over charcoal for chargrilled flavour before adding into the sauce. To make this Monday-night-friendly, I''ve just pan-seared. Serves 4 hearty appetites or 5 to 6 regular servings.', 'https://www.recipetineats.com/tachyon/2023/10/African-coconut-chicken-curry_3.jpg', 15, 45, 60, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_turmeric", "quantity": {"value": 7.5, "unit": "jar"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["4 chicken thigh fillets (, skin-on and bone-in (~250g/8oz each) (Note 2))","4 chicken drumsticks (~150g / 5oz each) (Note 2)","3/4 tsp cooking / kosher salt","1/2 tsp black pepper"],"purpose":"Seasoned chicken:"},{"ingredients":["2 tbsp coconut oil (or vegetable, canola or other plain oil) (Note 1)","1 onion (, finely diced)","3 garlic cloves (, finely minced)","2 tsp ginger (, finely minced)","1 tbsp coriander powder","1/2 tbsp cumin powder","1/2 tbsp turmeric powder","1 tsp pure chilli powder or cayenne pepper (, reduce or omit to taste (Note 3))","400g / 14 oz coconut milk (, full-fat (Note 4))","400g / 14 oz crushed canned tomato","1 1/4 tsp cooking / kosher salt","2 tbsp lemon juice (sub apple cider vinegar)","1/2 cup (lightly packed) coriander/cilantro leaves (sub parsley or baby spinach, or omit)"],"purpose":"The curry:"},{"ingredients":["Basmati rice"],"purpose":"Serving:"}]', '[{"title":"Season chicken","description":"Pat chicken dry using paper towels then sprinkle with the salt and pepper.","images":[],"step":1},{"title":"Brown chicken","description":"Heat oil in a large heavy based pot over high heat. Add the thighs, skin-side down, and cook for 4-5 minutes until golden brown. Turn and cook the other side for 1 minute. Transfer to a plate (it will still be raw inside). Then brown the drumsticks as best you can. I do 3 sides, 2 minutes each side. Transfer to the plate.","duration":4.5,"images":[],"step":2},{"title":"Sauté aromatics","description":"Turn heat down to medium high. Add the onion and cook for 1 minute until softened. Add garlic and ginger, cook for 30 seconds. Add the coriander, cumin, turmeric and chilli. Stir for 30 seconds.","duration":1,"images":[],"step":3},{"title":"Sauce","description":"Add coconut milk, tomato and salt. Stir, then return chicken into the pot (including juices on the plate). Submerge chicken as best you can.","images":[],"step":4},{"title":"Simmer 30 min","description":"Once the sauce comes to a simmer, reduce the heat so it’s bubbling gently. Cover and cook for 10 minutes. Remove the lid and simmer for a further 20 minutes, stirring occasionally to ensure the base doesn''t catch.","duration":10,"images":[],"step":5},{"title":"Finish & serve","description":"Stir in lemon and half of the coriander. Lade into bowls and serve garnished with the rest of the coriander!","images":[],"step":6}]', '[]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["african"],"categories":["chicken","chicken-drumstick-recipes","chicken-recipes","curry-recipes","mains","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0035a9fc479f', 'en', 'US', 'Chicken Francese', 'Recipe video above. Lightly battered pan-fried chicken breast with an elegant white wine lemon sauce. It''s like Chicken Piccata, but a thicker sauce, more of it, no capers, with subtle lemon flavour. It''s got a terrific crust that soaks up the sauce! Lovely restaurant dish that''s simple to make at home.Doesn''t taste winey because the alcohol is cooked out, leaving behind magical flavour only wine can bring to sauces.', 'https://www.recipetineats.com/tachyon/2023/10/Chicken-Francese_4.jpg', 10, 15, 25, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_wine", "quantity": {"value": 0.111, "unit": "bottle of 750ml"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["2 large chicken breasts (, skinless boneless (250-300g / 8-10oz each))","1/4 cup flour (, plain / all-purpose)","1 tsp cooking salt / kosher salt","1 tsp black pepper","2 large eggs","1 tbsp milk ( (any fat %))"],"purpose":"Chicken & coating:"},{"ingredients":["3 tbsp extra virgin olive oil","1 lemon (, thinly sliced 0.3cm / 1/8\")","50g / 3 tbsp unsalted butter","2 tbsp flour (, plain / all-purpose)","2 cups chicken stock/broth (, low sodium)","1/3 cup Chardonnay or other dry white wine (Note 1)","1/2 tsp cooking salt / kosher salt (no pepper!)","1 tbsp finely chopped parsley (, for garnish (optional))"],"purpose":"Cooking & sauce:"}]', '[{"description":"Cut each breast in half horizontally to form 4 thin steaks in total.","images":[],"step":1},{"description":"Whisk eggs and milk in a small bowl. Set aside.","images":[],"step":2},{"title":"Flour coating","description":"Mix flour, salt and pepper on a plate (I use my fingertips). Coat the chicken in the flour, shaking off excess, then set aside on a plate.","images":[],"step":3},{"description":"Heat the oil in a large nonstick pan over medium-high heat.","images":[],"step":4},{"title":"Cook chicken","description":"Dip the chicken in the egg, allow excess to drip off, then put into the pan. Cook for 3 minutes until golden. Flip, lower heat to medium, then cook for 4 minutes until the chicken is golden (internal temp 68°C/155°F). Remove onto a plate.","duration":3,"images":[],"step":5},{"title":"Lemon","description":"Add the lemon slices to the pan. Cook for a minute or until the lemons go soft / brown, then turn and cook the other side for 30 seconds. Remove onto a plate. (Note 2)","duration":0.5,"images":[],"step":6},{"description":"Wipe the pan clean using paper towels.","images":[],"step":7},{"title":"White wine sauce","description":"Still on medium heat, melt the butter in the pan. Add flour and stir for 1 minute using a wooden spoon. While stirring, slowly pour in half the stock. Once the flour is dissolved into the liquid, stir in remaining stock, then the wine and salt. (See Note 3 for lumps tip)","duration":1,"images":[],"step":8},{"title":"Thicken sauce","description":"Turn the heat up slightly then simmer for 3 - 4 minutes or until the sauce thickens into a syrupy consistency.","duration":3.5,"images":[],"step":9},{"description":"Sauce it! Return the chicken and lemon slices to the pan, then spoon the sauce all over the chicken. Sprinkle with parsley then serve the chicken with the sauce (use it ALL!).","images":[],"step":10}]', '["egg","gluten","milk"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b4a9348ac3d5', 'en', 'US', 'Golden coconut chicken curry', 'Recipe video above. This Golden Coconut Chicken Curry blows me away every time I make it - and I''ve been making it a lot lately! Such a beautiful spice blend, Thai vibes with a whisper of Indian, like a less shrimpy version of Thai Yellow Curry with a hint of Massaman. Don''t skip the star anise and cinnamon stick, and really try to use fresh turmeric rather than dried, for max flavour and yellow colour. All credit to JB for this one, his invention. :)*UPDATE: If you skip fresh turmeric and sub other spices and you''re using rather old spices (which lose flavour), the recipe won''t be as good as the rave reviews below and will make me sad*', 'https://www.recipetineats.com/tachyon/2023/09/Chicken-broccoli-coconut-curry_3.jpg', 10, 20, 30, 4, '[{"id": "ing_oil", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_star_anise", "quantity": {"value": 3.0, "unit": "jar"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_turmeric", "quantity": {"value": 15.0, "unit": "jar"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.6, "unit": "carton of 250ml"}}, {"id": "ing_broccoli", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_aram_masala", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_fennel", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_rice", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["3 tbsp coconut oil (, vegetable or canola oil (Note 1))","3 star anise","1 cinnamon stick","1 onion (, finely diced)","500g / 1lb chicken thigh fillets (, cut into small 1cm / 1/3\" slices (Note 2 options!))","1 tsp garlic (, finely grated)","1 tsp ginger (, finely grated)","3 tsp turmeric (, finely grated (sub 1 1/2 tsp powder, Note 3))","2 cups chicken stock/broth (, low sodium)","400g / 14 oz coconut cream (, unsweetened (sub coconut milk, Note 4))","1 large head broccoli (, florets cut small (can use stem too - peel & dice), or other veg (4 heaped cups))","1 cup coriander/cilantro leaves (, lightly packed, plus extra for garnish (I''d still make without this))"]},{"ingredients":["1 1/2 tsp cooking/kosher salt","1 1/2 tsp garam masala (Note 5)","1 1/2 tsp coriander powder","1/2 tsp cumin powder","1/2 tsp fennel powder (sub more garam masala)"],"purpose":"Spice mix:"},{"ingredients":["Crispy fried shallots (, store bought, for garnish (Note 6))","1 large head broccoli (, florets cut small (can use stem too - peel & dice), or other veg (4 heaped cups))"],"purpose":"Serving"}]', '[{"title":"Spice mix","description":"Mix the spices in a small bowl.","images":[],"step":1},{"title":"Toast","description":"Heat the oil in a large heavy based pot over medium high heat. Toast the star anise and cinnamon for 2 minutes.","duration":2,"images":[],"step":2},{"description":"Add onion, cook for 2 minutes.","duration":2,"images":[],"step":3},{"description":"Add chicken, cook for 3 minutes or it''s no longer pink on the outside (still raw inside).","duration":3,"images":[],"step":4},{"title":"Add aromatics","description":"Add garlic, ginger and turmeric. Cook for 1 minute.","duration":1,"images":[],"step":5},{"description":"Add spice mix and stir for 30 seconds.","duration":0.5,"images":[],"step":6},{"title":"Simmer 12 minutes","description":"Add stock and coconut cream. Stir and bring to an energetic simmer. Cook for 12 minutes (no need to stir) so the sauce thickens slightly.","duration":12,"images":[],"step":7},{"description":"Add broccoli florets. Bring back to a simmer and cook for 3 minutes or until softened.","duration":3,"images":[],"step":8},{"title":"Serve","description":"Cool for 5 minutes, this will allow the sauce to thicken slightly. Then stir in coriander and serve with rice (basmati or jasmine especially nice). Garnish with extra coriander and crispy fried shallots.","duration":5,"images":[],"step":9}]', '[]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","Indian"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","cuisines","curry-recipes","mains","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_391d4f388a0f', 'en', 'US', 'Herb & Garlic Butter Chicken Marylands (chicken leg quarters)', 'Recipe video above. Chicken marylands - such an under utilised cut of chicken! Cheap, juicy, flavourful, hard to stuff up. I tell people it''s like roast chicken: without the mess of carving up a whole chicken. Slather in herb & garlic butter then bake until golden. Don''t waste a drop of the pan juices - it''s liquid gold!Serve with potato gratin or creamy mash with garlic sautéed green beans for the perfect meal!', 'https://www.recipetineats.com/tachyon/2023/06/Herb-Garlic-Chicken-Marylands_8.jpg', 10, 50, 60, 4, '[{"id": "ing_chicken", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.111, "unit": "bottle of 750ml"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_rosemary", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["4 pieces (~1.5 kg/3 lb) chicken marylands (US: leg quarters) ( or 8 bone-in, skin-on thighs (Note 1))","1/2 tsp cooking/kosher salt","1/3 cup chardonnay or other dry white wine (sub low-sodium chicken stock/broth)"]},{"ingredients":["100g/7 tbsp unsalted butter (, softened)","4 garlic cloves (, minced using a garlic press (Note 2))","2 tsp fresh rosemary leaves (, finely chopped (Note 3 for dried))","2 tsp thyme leaves (, finely chopped (Note 3 for dried))","3/4 tsp cooking/kosher salt","1/4 tsp black pepper"],"purpose":"Herb & garlic butter:"}]', '[{"description":"Preheat oven to 220°C/425°F (200°C fan).","images":[],"step":1},{"description":"Mix Herb & Garlic Butter ingredients until combined.","images":[],"step":2},{"title":"Butter chicken","description":"Use an upside down tablespoon to loosen the chicken skin from the flesh on the thigh and most of the leg (Note 4). Smear 80% of the butter under the skin, just a small amount (~5%) on the underside (flesh side) then the remainder on top of the skin. (The flesh side gets lots of flavour from the pan juices).","images":[],"step":3},{"description":"Put chicken in roasting pan, skin side up. Sprinkle skin with the 1/2 tsp salt. Pour wine around chicken.","images":[],"step":4},{"title":"Roast 50 minutes","description":"Roast 10 minutes to get the skin going. Then reduce the heat to 200°C /400°F (180°C fan) and roast for a further 40 minutes, basting every 10 minutes from the 20 minute mark onwards.","images":[],"step":5},{"title":"Rest & serve","description":"Remove from oven. Rest 10 minutes then serve with the garlic-herb-butter pan juices as the sauce!","images":[],"step":6}]', '["milk"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_179548403868', 'en', 'US', 'Chicken Marsala', 'Recipe video above. A beloved Italian-American classic comprised of a crispy golden chicken cutlet smothered in a rich Marsala wine flavoured mushroom sauce. A restaurant favourite that''s easy to make at home, one bite and you''ll be hooked for life like I was!The key flavour here is Marsala wine so if you can''t consume alcohol or don''t have it, make Chicken in Creamy Mushroom Sauce instead! Also, this dish uses more alcohol than my usual "just a splash of wine" so it''s not recommended for kids. :)', 'https://www.recipetineats.com/tachyon/2023/06/Chicken-Marsala_0b.jpg', 10, 15, 25, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_eschalots", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_mushroom", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.333, "unit": "bottle of 750ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["2 large chicken breasts (300g/10oz each), cut in half horizontally (or 4 thighs, Note 1)","1/2 tsp cooking salt / kosher salt","1/2 tsp black pepper","1/4 cup flour (, plain/all-purpose)"],"purpose":"Golden crusted chicken:"},{"ingredients":["2 tbsp extra virgin olive oil","2 tbsp / 30g unsalted butter","2 eschalots (US: shallots), peeled and cut into 1cm / 1/3\" squares (Note 2)","1 garlic (, finely minced)","2 cups white mushrooms (, sliced 0.5cm / 1/5\" thick)","1 cup dry marsala wine (Note 3)","1/2 cup chicken stock/broth (, low sodium)","1/2 cup thickened / heavy cream ( (Note 4))","1/4 tsp cooking salt / kosher salt","1/8 tsp black pepper","1 tbsp finely chopped parsley (, for garnish (optional))"],"purpose":"Marsala sauce:"}]', '[{"description":"Chicken escalopes:","images":[],"step":1},{"title":"Pound","description":"Cut each breast in half to form 2 thin steaks. Cover with a freezer bag or Go-Between (Note 5) and pound to 1 cm / 0.4″ thickness using a meat mallet or rolling pin. This tenderises and ensures even cooking of the chicken.","images":[],"step":2},{"title":"Dust","description":"Sprinkle the surface with half the salt, pepper then flour. Lightly rub flour across surface, turn and repeat with remaining salt, pepper and flour. Shake excess flour off each piece just before cooking.","images":[],"step":3},{"title":"Cook","description":"Put half the butter and oil in a large non-stick pan over medium high heat. Once the butter is melted and foamy, place chicken in, then cook for 3 to 4 minutes until it''s gorgeously golden and crispy. Turn and cook the other side for 2 minutes. Remove onto a plate.","duration":3.5,"images":[],"step":4},{"description":"Creamy marsala sauce:","images":[],"step":5},{"title":"Sauté aromatics","description":"In the same pan, add remaining butter and oil. Once butter is melted, add eschalots and garlic. Cook for 1 minute.","duration":1,"images":[],"step":6},{"title":"Cook mushrooms","description":"Add mushrooms. Cook for 3 minutes, stirring regularly.","duration":3,"images":[],"step":7},{"title":"Reduce marsala","description":"Add marsala, turn up heat to high and boil for 3 minutes or until reduced by half.","duration":3,"images":[],"step":8},{"title":"Thicken sauce","description":"Add chicken stock, cream, salt and pepper. Stir, then lower heat so it''s simmering (not boiling rapidly) and simmer for 3 to 5 minutes until the sauce thickens to a cream consistency (not too thick, will thicken more).","duration":4,"images":[],"step":9},{"title":"Rewarm chicken","description":"Nestle chicken into sauce and leave for 30 seconds to reheat.","duration":0.5,"images":[],"step":10},{"description":"Serve! Take off the stove. Sprinkle with parsley, serve over starchy vehicle of choice (I chose mash. Rice, small pasta, polenta or bread for plate mopping also work well!).","images":[],"step":11}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian","Italian-American"],"categories":["chicken-breast-recipes","chicken-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8d75575a9ea4', 'en', 'US', 'Crunchy crumbed chicken drumsticks', 'Recipe video above. Super crunchy baked drumsticks that are generously seasoned with an addictive zingy kick from black pepper and cayenne. It''s not blow-your-head off but it has a very warm buzz! Just omit the cayenne and reduce the pepper to make it kid friendly. It''s so seasoned you don''t need a sauce for dunking but if you want something quick but great, use my honey mustard or pink sauce - both recipes in the notes.', 'https://www.recipetineats.com/tachyon/2023/05/Crunchy-crumbed-chicken-drumsticks_8.jpg', 15, 45, 60, 4, '[{"id": "ing_chicken", "quantity": {"value": 8.0, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 250.0, "unit": "carton of 12"}}, {"id": "ing_bread", "quantity": {"value": 0.188, "unit": "loaf"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_basil", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.2, "unit": "jar of 50g"}}]', '[{"ingredients":["8 chicken drumsticks","1/2 cup flour (, plain/all purpose)","3 large eggs (, beaten)","1 cup panko breadcrumbs (Note 1)","Canola oil spray (or other oil)"]},{"ingredients":["1 tbsp dried oregano","1 tbsp dried basil","1 tsp garlic powder","1 1/2 tsp smoked paprika","1 1/2 tsp cayenne pepper or pure chilli powder (- Note 2 (omit for kid-friendly))","1 1/2 tsp cooking salt","2 tsp black pepper (reduce to 1/2 tsp for kid-friendly)"],"purpose":"Seasoning:"}]', '[{"description":"Preheat oven to 200°C/400°F (180°C fan). Place a rack on a foil lined tray. Spray rack with oil.","images":[],"step":1},{"title":"Crumbing bowls","description":"Place the flour, whisked eggs and panko in 3 separate medium bowls (bear in mind shape to fit the drumsticks!).","images":[],"step":2},{"description":"Mix Seasoning in a small bowl. Put 1 tablespoon into the flour and the rest in the panko, then mix.","images":[],"step":3},{"title":"Crumb","description":"Pat drumsticks dry with paper towels. Coat in flour (shake off excess), then egg (let excess drip off). Place in panko and rotate, pressing to adhere all over, including the handle. (Note 3 for mess-free hands technique!)","images":[],"step":4},{"title":"Spray","description":"Place drumstick on the rack. Repeat with remaining chicken. Spray very generously with oil.","images":[],"step":5},{"description":"Bake 25 minutes. Turn drumsticks, spray again with oil. Bake a further 20 minutes until golden brown and super crunchy!","images":[],"step":6},{"description":"Serve Eat and enjoy the CRUNCH!","images":[],"step":7}]', '["egg","gluten"]', '["keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken","chicken-drumstick-recipes","chicken-recipes","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b20ecad7f571', 'en', 'US', 'Thai red curry pot roast chicken', 'Recipe video above. Such a spectacular way to cook a whole chicken! Cooked in a Thai red curry sauce with potatoes and beans, the pot-roasting method keeps the chicken ultra juicy. Plus, we can get away with store bought curry paste here because the chicken juices add a stack of money-can''t-buy flavour into the sauce.Easy enough for midweek, definitely impressive enough for company!', 'https://www.recipetineats.com/tachyon/2023/04/Thai-Red-Curry-Pot-Roast-Chicken_3a.jpg', 10, 75, 155, 5, '[{"id": "ing_chicken", "quantity": {"value": 1.8, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_thai_red_curry_paste", "quantity": {"value": 115.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 666.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_lemongrass", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.6, "unit": "carton of 250ml"}}, {"id": "ing_lime", "quantity": {"value": 6.0, "unit": "net of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_potato", "quantity": {"value": 600.0, "unit": "bag of 2kg"}}, {"id": "ing_green_beans", "quantity": {"value": 120.0, "unit": "pack"}}, {"id": "ing_basil", "quantity": {"value": 15.0, "unit": "bunch"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1.8 kg/ 3.6 lb whole chicken","1 tsp cooking/kosher salt","3 tbsp vegetable oil","115g/ 4 oz (1/2 cup) Thai red curry paste ( (Maesri recommended, Note 1))","2 large garlic cloves (, finely grated (Note 2))","2 tsp fresh ginger (, finely grated (Note 2))","2 tsp fresh lemongrass (, finely grated, white / pale green part only (Note 2))","1 cup chicken stock/broth (, low sodium)","400 ml/ 14 oz coconut cream (Note 3)","6 kaffir lime leaves (, crushed in hand (Note 4))","1 tbsp white sugar","2 tsp fish sauce","600g/ 1.2lb small potatoes (12 or so), (skin on (Note 5))","120g/ 4oz green beans (, trimmed and cut in half)","15 Thai basil leaves (, or more! (sub ordinary Italian basil, Note 6))"]},{"ingredients":["Jasmine rice","Red chilli (, finely sliced)","Coriander / cilantro leaves"],"purpose":"Serving + optional garnishes:"}]', '[{"title":"De-chill & salt chicken","description":"Take the chicken out of the fridge 1 hour prior. Pat dry then sprinkle with the salt.","images":[],"step":1},{"description":"Preheat oven to 200°C/400°F (180°C fan).","images":[],"step":2},{"title":"Sauté curry paste","description":"Use a large, oven-proof pot with a lid. Heat oil on medium high heat. Cook curry paste, garlic, ginger and lemongrass for 2 minutes. This step substantially improves the flavour of store bought curry paste.","duration":2,"images":[],"step":3},{"title":"Sauce","description":"Add chicken stock, stir, then simmer rapidly for 3 minutes to reduce by half. Stir in coconut cream, hand-crushed kaffir lime leaves, sugar and fish sauce.","duration":3,"images":[],"step":4},{"description":"Place chicken into the sauce. Spoon over sauce. Surround with potatoes.","images":[],"step":5},{"title":"Bake 1 hour","description":"Place the lid on and bake for 40 minutes. Remove lid spoon sauce over chicken (ie. baste). Turn the oven up to 220°C/425°F (200°C fan). Bake uncovered for 10 minutes, baste, bake another 10 minutes.","duration":40,"images":[],"step":6},{"title":"Beans, then bake 10 minutes","description":"Push beans into the sauce (wherever they fit!). Baste again then bake for a final 10 minutes (no lid).","images":[],"step":7},{"title":"Rest 10 minutes","description":"Remove chicken onto a plate (Note 7). Rest 10 minutes. Put lid on pot to keep sauce warm.","images":[],"step":8},{"title":"Serving","description":"Carve chicken, place on platter. Stir basil leaves into sauce. Pour/spoon sauce, potatoes and beans over chicken. Garnish with chilli and coriander, if desired. Serve with jasmine rice!","images":[],"step":9}]', '["fish"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Thai-ish"],"categories":["chicken-recipes","cuisines","one-pot-recipes","thai-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_89bf2e1811c6', 'en', 'US', 'Jalapeño popper stuffed chicken', 'Recipe video above. I love a stuffed chicken - and this is my (current) favourite. Think - Jalapeño popper, stuffed inside chicken. Warm, cheesy, spicy. Fabulous, easy way to make chicken breast a whole lot more exciting! Adore the jalapeño flavour in this.Spice level - not too spicy at all! The spiciness of fresh jalapeños gets dialled down a LOT when baked in the cream cheese. It will surprise you. Reader feedback - Sue says "My husband does not like spicy and said it was delicious. A definite “make again”." - 30 Mar 2023', 'https://www.recipetineats.com/tachyon/2023/03/Jalapeno-popper-stuffed-chicken_4.jpg', 15, 20, 35, 2, '[{"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_cream_cheese", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.4, "unit": "pack of 125g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}, {"id": "ing_jalape_os", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["2 x 220g/7oz chicken breast, (skinless, boneless)","1/4 tsp cooking/kosher salt","1/2 tsp smoked paprika (or ordinary paprika)","1 tbsp extra-virgin olive oil"]},{"ingredients":["60g/ 2 oz cream cheese","1/2 cup mozzarella cheese (, shredded (or other cheese))","1/4 cup parmesan (, finely shredded)","2 jalapeños (, deseeded and finely diced (Note 1))","1/2 tsp garlic powder","1/2 tsp black pepper","1/2 tsp cooking / kosher salt"],"purpose":"Jalapeño Popper Stuffing :"}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan).","images":[],"step":1},{"description":"Cut pockets into each chicken breast (Note 2), taking care not to cut all the way through. Cut on the side with the fold in the meat, to keep the smooth side intact.","images":[],"step":2},{"title":"Stuffing","description":"Microwave the cream cheese for 30 seconds to soften. Mix together with remaining jalapeño popper stuffing ingredients.","duration":0.5,"images":[],"step":3},{"title":"Stuff & seal","description":"Stuff inside the chicken pockets, stuffing it all the way in! Then seal each chicken with 2 or 3 toothpicks. If some stuffing is oozing out, that’s a bonus - it’s the best part when it crisps in the pan! Sprinkle both sides of the chicken with the paprika and salt.","images":[],"step":4},{"title":"Sear","description":"Heat the oil in an oven-proof skillet over medium-high heat. Place the breast smooth-side down, sear for 2 minutes until golden (it won''t colour more in the oven). Flip and sear the other side for another 2 minutes.","duration":2,"images":[],"step":5},{"title":"Bake 15 min","description":"Transfer the pan to the oven and bake for 15 minutes, or until the internal temperature of the chicken reaches 67°C/155°F.","duration":15,"images":[],"step":6},{"title":"Rest and serve","description":"Remove the chicken to a plate and rest for 5 minutes, then serve!","duration":5,"images":[],"step":7}]', '["milk"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","dinner-tonight","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_48859ff3efa2', 'en', 'US', 'One Pot Chicken Risoni', 'Recipe video above. A great one-pot meal for midweek, tastes like risotto but so much easier to make! Lemon garlic chicken, surprising amount of hidden vegetables, oozy tomato risoni (orzo), loaded with Greek flavours! The list of ingredients is looks long, but there''s actually a lot of repeat ingredients. :)', 'https://www.recipetineats.com/tachyon/2016/01/One-Pot-Greek-Risoni_7.jpg', 15, 35, 50, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.015, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.015, "unit": "net of 500g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_zucchini", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.45, "unit": "pack of 500g"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 0.9, "unit": "punnet of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cheese", "quantity": {"value": 0.5, "unit": "block of 250g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["1 lb / 500g chicken thighs (, boneless skinless (or breast), cut into 2 cm / 1\" pieces)","2 garlic cloves (, finely minced)","1 tbsp dried oregano","1 tbsp olive oil","1/2 tbsp lemon juice","1 tsp lemon zest","1/2 tsp each salt and pepper"],"purpose":"Lemon Garlic Chicken"},{"ingredients":["2 tbsp olive oil","2 garlic cloves (, minced)","1 small onion (, finely chopped)","2 zucchini (medium, or 1 large) (, cut into 1cm / 1/3\" cubes (Note 1))","1 red bell pepper/capsicum (, cut into 1cm / 1/3\" cubes (Note 1))","1 tbsp dried oregano","2 1/2 cups chicken broth/stock (, low sodium)","14 oz / 400g canned crushed tomatoes","1 tbsp tomato paste","1 1/2 cups orzo/risoni (Note 2)","1 1/2 cups cherry tomatoes (1 Australian punnet)","1 tsp cooking salt (kosher salt)","1/2 tsp black pepper"],"purpose":"Orzo/Risoni"},{"ingredients":["2 tbsp lemon juice (, drizzling at end)","1/2 cup (100g) Greek feta cheese (, crumbled (not optional))","Fresh oregano leaves (optional)"],"purpose":"Garnish (semi-optional)"}]', '[{"title":"Marinade chicken","description":"Combine Marinated Chicken ingredients in a bowl and set aside for marinate for 20 minutes. (Skip if in hurry, can also do overnight)","duration":20,"images":[],"step":1},{"description":"Preheat oven to 180°C/350°F (160°C fan).","images":[],"step":2},{"title":"Brown chicken (raw inside)","description":"Heat 1 tablespoon olive oil in a a large oven proof skillet or pot over high heat (Note 3). Cook chicken until lightly browned but still pink inside. Remove from skillet.","images":[],"step":3},{"title":"Sauté vegetables","description":"Add 1 tbsp olive oil, garlic and onion. Saute for 1 minute, then add zucchini and bell peppers/capsicum. Cook for 2 minutes.","duration":1,"images":[],"step":4},{"title":"Add everything else","description":"Add risoni, oregano, chicken broth, tomato, tomato paste, salt and pepper.","images":[],"step":5},{"description":"Scatter chicken and cherry tomatoes across the surface (don''t stir in).","images":[],"step":6},{"title":"Bake 15 minutes","description":"Once the liquid comes to a simmer, transfer to the oven (no lid) and bake for 15 minutes (or until risoni is just cooked, tender but still firm). There may be liquid on the surface still - that''s good!","duration":15,"images":[],"step":7},{"title":"Drizzle with lemon","description":"Remove from oven, drizzle with lemon juice. Garnish with feta and fresh oregano leaves, if desired, then serve.","images":[],"step":8}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Greek(ish)"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","greek-recipes","main-dishes","mediterranean-recipes","most-popular","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7cf0a5b018f6', 'en', 'US', 'One Pot Mexican Chicken and Rice', 'Recipe video above. Chicken seared with Fajita flavours then baked with seasoned Mexican red rice. This is a flavour explosion in one pot! People love that it''s finished in the oven. No need to worry about a scorched base!Makes more rice than you''ll need because it is difficult to make less using this method of cooking. Nobody complains, cause it''s so good!', 'https://www.recipetineats.com/tachyon/2014/12/One-Pot-mexican-chicken-and-rice_3.jpg', 15, 50, 55, 5, '[{"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.009, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_lime", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_rice", "quantity": {"value": 150.0, "unit": "pack"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_black_beans", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_ime", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["2 tsp garlic powder (or 2 garlic cloves, minced)","2 tsp paprika","2 tsp cumin powder","1 3/4 tsp salt","1/2 tsp cayenne pepper ((Note 1), optional)","Black pepper"],"purpose":"Mexican Spice Mix"},{"ingredients":["5 chicken thighs, bone-in, skin on ( (Notes 2 and 3))","2 tbsp olive oil","1 tbsp lime juice"],"purpose":"Chicken"},{"ingredients":["1 small onion (, peeled and diced (or 1/2 large))","1 garlic clove (, minced)","1 red capsicum ((bell pepper), diced or sliced)","1 cup long grain rice (, uncooked (Note 4))","1 cup chicken stock/broth (, low sodium (or vegetable stock))","3/4 cup tomato passata (US: tomato puree) (Note 5)","1 cup frozen corn kernels (or canned - drained)","1 can (400g/16oz) black beans (, drained and rinsed (sub red kidney beans))"],"purpose":"Rice"},{"ingredients":["1 lime (, plus extra to serve)","Coriander/cilantro","Sliced jalapeño peppers (optional)"],"purpose":"Garnish"}]', '[{"description":"Preheat oven to 180°C/350°F (160° fan).","images":[],"step":1},{"title":"Mexican spice mix","description":"Mix the ingredients in a small bowl.","images":[],"step":2},{"title":"Rub Chicken","description":"Place 1 1/2 tablespoons of the Mexican Spice Mix in a large bowl (reserve rest for rice) with 1 tablespoon olive oil and lime juice. Mix to form a paste then add the chicken and toss to coat the chicken.","images":[],"step":3},{"title":"Marinate (optional)","description":"Marinate chicken for 1 hour, or even overnight, if you have the time. Otherwise, it''s fine to proceed with the recipe!","images":[],"step":4},{"title":"Sear chicken","description":"Using a large deep skillet preferably with a lid (Note 6), heat the remaining 1 tbsp olive oil over medium high heat. Sear the skin side of the chicken for 4 minutes until light golden, then sear the flesh side for 1 1/2 minutes (will still be raw inside). Remove onto a plate.","duration":4,"images":[],"step":5},{"title":"Sauté aromatics","description":"If you''ve got a lot of burnt spices on the base, scrape off and discard some of it. Then in the same skillet, still over medium high heat, add the onion, garlic and capsicum (bell peppers). Sauté for 3 minutes until the onion softens.","duration":3,"images":[],"step":6},{"title":"Rice & liquid","description":"Add the rice and stir. Add chicken stock, tomato passata, corn, beans and remaining Mexican Spice Mix. Stir to combine.","images":[],"step":7},{"title":"Top with chicken","description":"Place chicken on top of the rice, skin side up. It will be partially submerged but most of the skin should be above the liquid.","images":[],"step":8},{"title":"Bake covered 25 min","description":"Bring to simmer, then cover skillet with a lid or foil and place in the oven for 25 minutes.","duration":25,"images":[],"step":9},{"title":"Bake uncovered 15 min","description":"Remove the lid/foil and bake for a further 15 minutes until only small puddles of liquid remain on the surface of the rice.","images":[],"step":10},{"title":"Rest 10 minutes","description":"Remove from the oven and allow to rest for 10 minutes (uncovered). Any remaining liquid will evaporate in this step.","duration":10,"images":[],"step":11},{"title":"Serve","description":"Squeeze the juice of 1 lime over the chicken and rice. Remove chicken or push to the side then fluff the rice. Serve, garnished with coriander/cilantro leaves, extra lime wedges and sliced jalapeños, if desired. Sour cream also goes well with this, or a dollop of guacamole or avocado sauce!","images":[],"step":12}]', '[]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","mexican-recipes","most-popular","one-pot-recipes","quick-and-easy","rice-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f205c7b87ef1', 'en', 'US', 'Chicken sandwiches', 'Recipe video above. The secret to the best chicken sandwiches like the ones you get from gourmet deli? Shred the chicken as finely as you can (stand-mixer is best!). Use mayo + sour cream so the sauce isn''t too greasy. Plus a handful of walnuts!Great platter food for gatherings, picnics and lunch boxes.Makes 10 deli-style sandwiches, 8 very generously filled sandwiches, or 15 normal lunchbox sandwiches (Note 6).', 'https://www.recipetineats.com/tachyon/2022/12/Chicken-sandwiches_3.jpg', 15, 0, 15, 10, '[{"id": "ing_chicken", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_walnuts", "quantity": {"value": 112.5, "unit": "jar"}}, {"id": "ing_corn", "quantity": {"value": 0.113, "unit": "can of 400g"}}, {"id": "ing_dill", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.25, "unit": "jar of 400g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.4, "unit": "tub of 250g"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_lemon", "quantity": {"value": 0.045, "unit": "net of 500g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_bread", "quantity": {"value": 20.0, "unit": "loaf"}}]', '[{"ingredients":["500g/ 1 lb cooked chicken meat from 1 large store bought roast chicken (Note 1)","1 celery stem (, sliced 3mm/0.1\" thick then into 0.5cm/0.2\" pieces)","1 green onion stem (, finely sliced)","3/4 cup walnuts (, roughly chopped (Note 2))","3 tbsp finely chopped cornichon/dill pickle","1 1/2 tbsp finely chopped dill (Note 3)"],"purpose":"Filling:"},{"ingredients":["2/3 cup whole egg mayonnaise (S&W best in Aus, Note 4)","2/3 cup sour cream (sub full fat yogurt)","2 tsp Dijon mustard","1 1/2 tbsp lemon juice (sub white wine or cider vinegar)","1/2 tsp onion powder (or more garlic powder)","1/4 tsp garlic powder (or more onion powder)","3/4 tsp cooking/kosher salt","1/4 tsp black pepper"],"purpose":"Sauce:"},{"ingredients":["Salted butter (, for spreading on bread)","20 slices white sandwich bread, day-old, (or more slices for less filling) (Note 5)"],"purpose":"Sandwiches:"}]', '[{"description":"Shred the chicken as finely as you can. The best method is using a stand-mixer. Just put the meat in the bowl with the paddle attachment and mix on medium speed until it''s really finely shredded (~ 1 minute). Else use a handheld beater or your hands.","images":[],"step":1},{"title":"Mix the Sauce ingredients in a bowl until smooth","description":"use a whisk if needed.","images":[],"step":2},{"description":"Pour Sauce over the chicken. Add remaining Filling ingredients. Stir until combined.","images":[],"step":3},{"description":"Spread bread with butter. Spread with Filling (see below for amount).","images":[],"step":4},{"description":"Remove crusts if desired (for the authentic \"gourmet\" experience!) and cut in half. (Tip: For really neat cuts, refrigerate sandwiches before slicing so Filling firms up).","images":[],"step":5},{"description":"Serve on platters littered with green fluffage, if desired!","images":[],"step":6},{"description":"Filling quantities (Note 6)","images":[],"step":7},{"description":"Chicken filling per sandwich:- Deli standard (recommended): 100g / 1/2 cup (makes 10 sandwiches)- Very generous: 130g / 1/2 cup (makes 8)- Everyday lunchbox: 80g (1/3 cup) (makes 15).","images":[],"step":8}]', '["egg","gluten","milk","mustard"]', '[]', '{"mealType":["snack","lunch"],"cuisine":["Western"],"categories":["chicken-recipes","finger-food","no-cook-food","quick-and-easy","sandwiches-and-sliders","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bc52387c7145', 'en', 'US', 'Honey Soy Wings', 'Recipe video above. The easiest, no-fuss way to make sticky Honey Soy Wings in the oven. Don''t you hate it when you''re promised sticky wings but the sauce stays watery and never thickens?? Trick is to just pour off chicken juices partway through cooking. Easy!Serve with fried rice or Vermicelli Noodle Salad for a great quick midweek meal.', 'https://www.recipetineats.com/tachyon/2022/11/Honey-Soy-Wings_7.jpg', 5, 60, 65, 4, '[{"id": "ing_chicken", "quantity": {"value": 1.25, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_honey", "quantity": {"value": 0.12, "unit": "jar of 500g"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.3, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.09, "unit": "bottle of 500ml"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_oil", "quantity": {"value": 7.5, "unit": "bottle"}}]', '[{"ingredients":["1.25 kg / 2.5 lb chicken wings (wingettes/drumettes), or cut up whole wings (Note 1 for whole wings)","1 tsp white sesame seeds","1 green onion stem (, finely sliced)"]},{"ingredients":["4 tbsp honey","5 tbsp light soy sauce (Note 2)","1 tbsp dark soy sauce (Note 2)","3 tbsp apple cider vinegar (or other clear vinegar)","1 large garlic clove (, crushed using garlic press (or finely minced or grated))","1/2 tbsp canola oil"],"purpose":"Honey soy marinade:"}]', '[{"description":"Mix marinade in a bowl until honey is dissolved. Pour over the wings in a ziplock bag. (Note 3)","images":[],"step":1},{"description":"Marinade for 30 minutes. You can do overnight but it doesn''t noticeably improve flavour in the flesh.","duration":30,"images":[],"step":2},{"description":"Preheat oven to 200°C/400°F (180°C fan). Line a large tray with foil then paper.","images":[],"step":3},{"title":"Bake","description":"Spread wings out on the tray, skin side up. Reserve marinade. Bake 30 minutes.","images":[],"step":4},{"description":"Drain off juices on the tray and discard. (Key step to ensure sauce thickens).","images":[],"step":5},{"title":"Sauce","description":"Pour reserved marinade over wings. Toss to coat then spread the wings out, skin side up.","images":[],"step":6},{"title":"Bake & baste","description":"Turn oven down to 180°C/350°F (160°C fan). Bake wings for 30 minutes, basting with tray juices every 10 minutes (3 times). Rearrange wings as needed if cooking unevenly, you can even turn them upside down if they brown too quickly. Sauce should be syrupy by the end so you can glaze well. (Note 4 if sauce still watery).","duration":30,"images":[],"step":7},{"title":"Serve","description":"Transfer wings into a serving bowl. Pour over syrup on tray, sprinkle with sesame seeds and green onion. Serve!","images":[],"step":8}]', '["gluten","sesame","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner","snack"],"cuisine":["Asian-esque","Western"],"categories":["chicken-recipes","chicken-wings","finger-food","quick-and-easy","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2544a6f1bff9', 'en', 'US', 'Chicken in Creamy Mustard Sauce', 'Recipe video above. Here''s a really quick way to cook chicken thighs or breast in a simple yet elegant creamy mustard sauce. Mustard adds flavour as well as thickening the sauce while tarragon infuses the sauce with elegant aniseed notes, giving it a very restaurant-y flavour. But even if you don''t have fresh tarragon or don''t like it, this is absolutely still worth making. In fact, I''ve probably made it as often without tarragon as I have with!', 'https://www.recipetineats.com/tachyon/2022/11/Chicken-in-creamy-mustard-sauce_3.jpg', 5, 10, 15, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_tarragon", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["700g / 1.4 lb chicken thigh fillets (, skinless boneless (4 - 6 pieces, Note 1))","1 1/2 tbsp olive oil","1/2 tsp cooking/kosher salt","1/4 tsp black pepper"]},{"ingredients":["1/2 cup thickened/heavy cream","1 tbsp Dijon mustard","1 tbsp whole grain mustard","1/4 tsp cooking/kosher salt","1/4 tsp black pepper","1-2 tbsp water (, as needed)"],"purpose":"Creamy mustard sauce:"},{"ingredients":["2 tsp fresh tarragon (, finely chopped (Note 2))","2 tsp parsley (, finely chopped)"],"purpose":"Optional herbs:"}]', '[{"description":"Season chicken with the salt and pepper.","images":[],"step":1},{"title":"Sear chicken thighs","description":"Heat oil in a large pan that is not non-stick over medium-high heat. (Note 3) Place chicken in pan smooth side-down and cook for 4 minutes or until deep golden. Turn and cook the other side for 3 minutes until cooked through (internal temperature 72°C/162°F, Note 4). Remove to a plate.","duration":4,"images":[],"step":2},{"title":"Breast","description":"If using breast (prepared per Note 1), sear on high for 2 minutes on each side, target temp 67°C/153°F.)","duration":2,"images":[],"step":3},{"title":"Clean pan","description":"Scrape any loose black bits out of the pan and discard.","images":[],"step":4},{"title":"Make sauce","description":"Return the pan to medium heat. Add cream and both mustards. Mix with a wooden spoon until mustard dissolves, scraping up any brown bits stuck to the pan. Once sauce is hot but not simmering, stir in salt, pepper and herbs (if using). If getting too thick loosen with a touch of water.","images":[],"step":5},{"title":"Serve","description":"Place chicken on serving plates. Spoon over sauce. Enjoy!","images":[],"step":6}]', '["milk","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9c345eb01285', 'en', 'US', 'Chicken Rissoles', 'Recipe video above. The chicken version of the beloved Aussie beef rissoles! You''ll love the oozy little pockets of cheese.Makes 14 to 16 rissoles. Serves 4 to 5 as a meal, or one Dozer.', 'https://www.recipetineats.com/tachyon/2022/09/Chicken-Rissoles_4.jpg', 15, 20, 35, 16, '[{"id": "ing_chicken_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_zucchini", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_bread", "quantity": {"value": 0.141, "unit": "loaf"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_ketchup", "quantity": {"value": 1.0, "unit": "bottle of 500g"}}]', '[{"ingredients":["500g / 1 lb chicken mince (ground chicken), excess liquid drained and discarded (Note 1)","1 carrot, medium (, grated on a shallow angle (Note 2))","1 zucchini, medium (, grated on a shallow angle (Note 2))","1 egg","1 1/2 cup Colby cheese, shredded (or cheddar, tasty, Monterey Jack - see Note 3)","3/4 cup panko breadcrumbs (Note 4)","1 tbsp finely chopped parsley (, optional)","1 tsp cooking/kosher salt","1/2 tsp black pepper"],"purpose":"Rissoles:"},{"ingredients":["2 tbsp canola oil","Ketchup - for dipping"],"purpose":"Cooking & serving:"}]', '[{"description":"Pre-heat oven to 100°C/210°F (all oven types), to keep cooked rissoles warm. Place a rack over a tray.","images":[],"step":1},{"title":"Rissole mixture","description":"Mix all ingredients together in a bowl using a wooden spoon.","images":[],"step":2},{"title":"Form patties","description":"Wet your hands (stops the mixture sticking all over your hands). Measure out just shy of 1/4 cup and shape into a 6 cm wide x 1.5cm thick pattie (2.4\" x 0.6\" thick). See Note 1 if your mixture is too loose.","images":[],"step":3},{"title":"Cook","description":"Heat 1 tablespoon oil in a large non-stick pan over medium high heat. Cook 5 - 6 rissoles at the time, 3 to 4 minutes on each side, until beautifully golden (as pictured). (Note 5 for baking)","images":[],"step":4},{"title":"Keep warm","description":"Transfer to the rack on the tray and keep warm in the oven. Add more oil as needed and cook remaining rissoles.","images":[],"step":5},{"description":"Serve straight away with ketchup for dipping!","images":[],"step":6}]', '["egg","milk"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-mince-recipes","chicken-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_25cd81634cc8', 'en', 'US', 'Crispy Baked Chicken Drumsticks', 'Recipe video above. This is just a great, simple chicken drumsticks recipe you can get in the oven quickly. Tossed in a 3-ingredient, barbecue rub-like seasoning, they''re beautifully crispy thanks to a touch of baking powder, a tried and proven secret ingredient in my Truly Crispy Baked Chicken Wings recipe!', 'https://www.recipetineats.com/tachyon/2022/07/Crispy-Baked-Chicken-Drumsticks_5.jpg', 10, 45, 55, 5, '[{"id": "ing_chicken", "quantity": {"value": 12.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.625, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.2, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.068, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.1, "unit": "tub of 150g"}}]', '[{"ingredients":["12 chicken drumsticks (Note 1)","2 tbsp extra virgin olive oil","Oil spray"]},{"ingredients":["3 tsp garlic powder","3 tsp onion powder","5 tsp smoked paprika","2 tsp black pepper","1 1/2 tsp cooking/kosher salt","4 1/2 tbsp plain/all-purpose flour","3 tsp baking powder (makes them crispier, DO NOT confuse with baking soda / bi-carb) (Note 3)"],"purpose":"Seasoning (Note 2):"}]', '[{"title":"Preparation","description":"Preheat the oven to 200°C/390°F (180°C fan-forced). Line a tray with foil then place a rack on the tray (makes the underside of the drumsticks crispier, Note 4).","images":[],"step":1},{"title":"Seasoning","description":"Mix the Seasoning ingredients in a shallow bowl.","images":[],"step":2},{"title":"Coat in oil","description":"Toss the drumsticks in the olive oil. Stretch and pull the skin on each drumsticks to cover as much of the flesh as possible.","images":[],"step":3},{"title":"Coat in seasoning","description":"Coat a drumstick in the Seasoning then shake the excess off well. Place on the rack. Repeat with remaining drumsticks.","images":[],"step":4},{"title":"Spray with oil","description":"Spray the legs generously with oil.","images":[],"step":5},{"description":"Bake for 30 minutes, rotating the tray halfway through. Increase the oven to 220°C / 430°F (200°C fan) then bake for a further 15 minutes or until the skin is crispy. Enjoy!","duration":30,"images":[],"step":6}]', '["gluten"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken","chicken-drumstick-recipes","chicken-recipes","dinner-tonight","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7b601609467c', 'en', 'US', 'Chicken Fricassée (French creamy chicken stew)', 'Recipe video above. A recipe from our chef JB (yes, he''s French!), this traditional French dish is essentially a quick chicken stew with a creamy white mushroom sauce. It''s a bit like a white sauce version of the famous French Coq au Vin – but it''s much faster to make!This is a wonderful rustic family meal that''s quick enough for midweek, or to elevate to restaurant level by using homemade chicken stock.', 'https://www.recipetineats.com/tachyon/2021/09/Chicken-Fricasse_03-SQ.jpg', 20, 60, 80, 4, '[{"id": "ing_chicken", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_cream", "quantity": {"value": 0.667, "unit": "carton of 250ml"}}]', '[{"ingredients":["4 chicken drumsticks (~150g/5oz each, Note 1)","4 chicken thighs (, skin-on and bone-in (~250g/8oz each, Note 1))","1 tsp salt (cooking / kosher salt)","1/2 tsp black pepper","4 tbsp / 60g unsalted butter"],"purpose":"Chicken"},{"ingredients":["300g / 10oz white mushrooms (, halved if small, or cut in 4 to 6 if large)","2 medium brown onions (, sliced 0.6cm (1/2in) wide)","2 garlic cloves (, finely minced)","1 bay leaf (, fresh (sub dried))","3 thyme sprigs (or 1/2 tsp dried thyme)","3 tbsp flour (, plain / all-purpose)","1/2 cup white wine (, preferably chardonnay (Note 2))","3 cups chicken stock (, low sodium (preferably homemade!))","1/4 tsp salt (cooking / kosher salt)","1/4 tsp black pepper","2 tbsp parsley (, chopped)","2/3 cup thickened/heavy cream"],"purpose":"Stew ingredients"}]', '[{"title":"Season chicken","description":"Pat chicken dry with paper towels then sprinkle with salt and pepper.","images":[],"step":1},{"title":"Brown thighs","description":"Melt butter over medium-high heat in a large skillet or heavy based pot with a lid. Add chicken thighs, skin side down, and cook for 4 to 5 minutes until golden brown. Turn and cook the other side for 1 minute then remove to a plate.","duration":4.5,"images":[],"step":2},{"title":"Brown drumsticks","description":"Then brown the drumsticks, as best you can. I do 3 sides, about 2 minutes each. Then remove from skillet.","images":[],"step":3},{"title":"Sauté mushrooms and onion","description":"Add mushrooms, onion, bay leave and thyme. Cook for 5 minutes until mushroom is lightly golden - they won''t go deep golden brown.","duration":5,"images":[],"step":4},{"title":"Garlic and flour","description":"Add garlic and stir for 30 seconds. Add flour and cook for 1 minute.","duration":0.5,"images":[],"step":5},{"title":"Wine and chicken stock","description":"Add wine, chicken stock, salt and pepper. Stir, scraping the base of the pot to dissolve the brown residue stuck to the pan (\"fond\") into the sauce.","images":[],"step":6},{"title":"Return chicken to sauce","description":"Return chicken back into the sauce with the skin side up.","images":[],"step":7},{"title":"Simmer covered 10 minutes","description":"Once it comes to a simmer, adjust heat so it''s bubbling constantly but not rapidly (see video) - medium-low on my stove. Cover with lid and simmer 10 minutes.","images":[],"step":8},{"title":"Uncover 20 minutes","description":"Remove lid and let it simmer for a further 20 minutes. Chicken will be cooked - internal temperature 75°C/167°F or slightly higher.","images":[],"step":9},{"title":"Creamy sauce","description":"Remove chicken to a plate. Add cream and stir. Once it comes up to a simmer, taste sauce (I know, big ask!), and add more salt if desired..","images":[],"step":10},{"description":"Serve! Return chicken into the sauce then remove from the stove. Sprinkle with parsley and serve! Traditionally served over mashed potato or rice. Also ideal with short pasta like penne, ziti or macaroni.","images":[],"step":11}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["French"],"categories":["chicken","chicken-drumstick-recipes","chicken-recipes","mains","quick-and-easy","stews"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ffff10b2a364', 'en', 'US', 'Coq au Vin', 'Recipe video above. Coq au Vin – a true French classic from a true French chef, our very own JB! Chicken pieces are braised in a luscious, glossy red wine sauce with bacon, mushroom and onions that tastes utterly luxurious. Like Beef Bourguignon, the beauty of this dish lies in its simplicity: remarkably few ingredients and simple process with results fit for a king – or queen! For the best results, start this 2 days before serving: 12 - 24 hour marinade for the chicken (essential), then rest the finished stew overnight to let the flavours develop even further (recommended but not essential).', 'https://www.recipetineats.com/tachyon/2016/09/Coq-au-Vin_00.jpg', 15, 90, 105, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 16.0, "unit": "pack of 1kg"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_wine", "quantity": {"value": 1.0, "unit": "bottle of 750ml"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 0.75, "unit": "pack of 200g"}}, {"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.105, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}]', '[{"ingredients":["4 chicken thighs (, bone-in, skin on (~220g / 7 oz each) (Note 1))","4 chicken drumsticks (Note 1)","16 pearl onions or picking onions (Note 2)","1 bay leaf (, fresh (dry also ok))","3 thyme sprigs (sub 1 tsp dried thyme)","750 ml / 3 cups pinot noir red wine (, or other dry red wine (Note 3))"],"purpose":"Red Wine Chicken Marinade:"},{"ingredients":["3 - 4 tbsp vegetable oil (or canola oil)","3/4 tsp salt (cooking/kosher salt, or 1/2 tsp table salt)","1/2 tsp pepper"],"purpose":"Browning Chicken:"},{"ingredients":["400g / 14oz white mushrooms (, halved (quartered if large) (Note 4))","150g / 5oz bacon piece (, (speck) cut into 1 x 2.5cm / 0.4 x 1\" batons (Note 5))","60g / 4 tbsp unsalted butter","3 garlic cloves (, finely minced (with knife))","2 tbsp tomato paste","7 tbsp flour (, plain / all purpose)","750 ml / 3 cups beef stock","1/4 tsp salt (cooking/kosher salt, or 1/8 tsp table salt) (Note 7)","1/4 tsp black pepper"],"purpose":"Coq au Vin Stew:"},{"ingredients":["2 tbsp parsley (, chopped)","Mashed potato (or tagliatelle)"],"purpose":"Garnish and serving:"}]', '[{"description":"Marinate chicken:","images":[],"step":1},{"title":"Marinate chicken","description":"Place the Chicken Marinade ingredients in a large glass or ceramic bowl or dish. Marinate overnight in the fridge (minimum 12 hours, maximum 24 hours).","images":[],"step":2},{"description":"Strain wine into a bowl. Reserve herbs and wine. Separate the chicken and onion.","images":[],"step":3},{"title":"Dry chicken","description":"Spread chicken out on a try lined with paper towels, then pat dry with paper towels.","images":[],"step":4},{"title":"Reduce wine","description":"Pour red wine into a saucepan and bring to a boil over medium high heat. Simmer vigorously, skimming off any impurities that rise to the surface, until reduced by half. Set aside.","images":[],"step":5},{"description":"Brown chicken and vegetables:","images":[],"step":6},{"description":"Preheat oven to 180°C / 350°F (160°C fan).","images":[],"step":7},{"title":"Season chicken","description":"Sprinkle chicken with 3/4 tsp salt and 1/2 tsp black pepper.","images":[],"step":8},{"title":"Brown chicken","description":"Heat 3 tbsp oil in a large, heavy-based, oven-proof pot over medium-high heat. Add chicken thighs skin side down and cook for 2 - 3 minutes until nicely browned (it will be darker than usual because of the red wine). Flip thighs and cook the other side for another minute to kiss it with a little colour. Remove to a tray. Pull at skin of drumsticks to cover flesh as best as possible, then brown (I do 3 to 4 sides, ~5 minutes in total). Remove and set aside.","duration":2.5,"images":[],"step":9},{"title":"Fry bacon","description":"Remove any loose black burnt bits. Add a bit of extra oil if needed, then cook bacon for 3 minutes until golden. Add to tray with chicken.","duration":3,"images":[],"step":10},{"title":"Sauté mushrooms","description":"Add mushrooms and cook for 5 minutes, or until golden. Remove into a separate bowl.","duration":5,"images":[],"step":11},{"title":"Sauté onion","description":"Add a bit of extra oil if needed, then cook onions for 5 minutes or until there are nice golden patches.","duration":5,"images":[],"step":12},{"title":"Butter and flour","description":"Add butter into pot. Once melted, add garlic and cook for a further 1 minute. Add tomato paste and cook for 2 minutes. Add flour and cook for 2 minutes.","duration":2,"images":[],"step":13},{"title":"Add wine and stock","description":"While stirring, slowly pour in beef stock – this helps the flour dissolve lump-free into the stock. Then add the reduced wine and mix until flour mixture is dissolved and mostly lump-free. (Note 8)","images":[],"step":14},{"title":"Add everything back in","description":"Add chicken, bacon, mushroom, thyme, bay leaf, salt and pepper into the pot, then stir.","images":[],"step":15},{"title":"Oven 45 minutes","description":"Bring to a simmer, then cover and transfer to oven for 45 minutes. Chicken will be very tender - but not \"falling apart\". (Note 9)","duration":45,"images":[],"step":16},{"title":"Adjust salt","description":"Remove from oven, taste sauce and add salt if needed.","images":[],"step":17},{"title":"Leave overnight (recommended, Note 11)","description":"If time permits, leave the stew overnight before serving because as with all stews, it gets better with time! Reheat gently on a low stove in a covered pot, ensuring that chicken is fully heated through. Add water if needed to loosen sauce.","images":[],"step":18},{"description":"Serve over mashed potato or tagliatelle, sprinkled with fresh parsley! For the ultimate experience, mop the plate clean with homemade brioche (surprisingly straight forward to make). See in post for side salad and dessert options.","images":[],"step":19}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["French"],"categories":["chicken-drumstick-recipes","chicken-recipes","stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_248ab261c994', 'en', 'US', 'Mushroom Stuffed Chicken Breast', 'Recipe video above. These juicy chicken breasts are stuffed with garlicky mushrooms, spinach leaves and a blanket of oozing melted cheese. Simple to make with just a few ingredients, this is how to transform chicken breast from ho-hum into "ohhh yum!"After this one, try Sun Dried Tomato Stuffed Chicken!', 'https://www.recipetineats.com/tachyon/2021/07/Mushroom-Stuffed-Chicken-Breast_14.jpg', 15, 30, 45, 2, '[{"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_thyme", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_baby_spinach", "quantity": {"value": 2.0, "unit": "bag of 250g"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.64, "unit": "pack of 125g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}]', '[{"ingredients":["2 x 220g / 7oz chicken breast (, skinless boneless (Note 1))","3/4 tsp salt","1/4 tsp pepper","30g / 2 tbsp unsalted butter","200g / 7 oz mushrooms (, sliced 3mm (1/8″) thick (~2 heaped cups))","2 garlic cloves (, finely minced)","1/2 tsp thyme leaves (Note 2)","2 cups baby spinach (Note 3)","80 g / 3oz mozzarella (, sliced (or other melting cheese))","1 tbsp olive oil"]}]', '[{"description":"Preheat oven to 200°C/390°F (180°F fan).","images":[],"step":1},{"description":"Cut pockets into each chicken breast, being sure not to cut all the way through (see photos in post). Cut on the side with the fold in the meat, to keep the smooth side intact.","images":[],"step":2},{"description":"Season the inside and outside of the chicken with half the salt and pepper.","images":[],"step":3},{"title":"Mushroom filling","description":"Melt butter in a heavy based oven proof skillet over high heat. Add mushrooms and cook for 3 minutes until they start to turn pretty golden. Then add garlic, thyme, remaining salt and pepper and continue cooking for a further 2 minutes until mushrooms are nice and golden.","duration":3,"images":[],"step":4},{"title":"Add spinach","description":"Add baby spinach and stir until wilted - about 30 seconds.","images":[],"step":5},{"description":"Stuff mushroom mixture into the pocket of each chicken, then top with cheese.","images":[],"step":6},{"title":"Seal with toothpicks as best you can","description":"it doesn’t need to be fully sealed like we do with Chicken Kiev. Just mostly sealed.","images":[],"step":7},{"title":"Sear chicken","description":"Give the pan a quick wipe with paper towels. Heat oil over medium high heat. Sear each side of the chicken breast for 1 1/2 minutes until golden.","images":[],"step":8},{"title":"Bake 15 minutes","description":"Transfer the skillet to the oven and bake for 15 minutes, or until the internal temperature of the chicken is 65°C/149°F (chicken flesh, not the mushroom filling).","duration":15,"images":[],"step":9},{"title":"Rest 5 minutes","description":"Remove from tray onto a plate, loosely cover with foil and rest for 5 minutes. Serve! Pictured in post with easy creamy Baked Lemon Herb Risotto and baby spinach with Balsamic Dressing.","duration":5,"images":[],"step":10}]', '["milk"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","dinner-tonight","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8b10b7260e13', 'en', 'US', 'Chicken Kiev', 'Recipe video above. The trick to ensuring the melted butter stays firmly sealed inside Chicken Kiev? Partially freezing the chicken. Stops the chicken from moving as you handle it for coating / cooking which ensures the chicken remains sealed and keeps the molten river of garlic butter inside!For a real Kiev experience, you do need to deep fry. BUT for the very best healthier baked option, see Note 6.', 'https://www.recipetineats.com/tachyon/2021/05/Chicken-Kiev_2-1.jpg', 30, 30, 60, 2, '[{"id": "ing_butter", "quantity": {"value": 6.0, "unit": "block of 250g"}}, {"id": "ing_parsley", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 0.188, "unit": "loaf"}}, {"id": "ing_oil", "quantity": {"value": 1000.0, "unit": "bottle"}}]', '[{"ingredients":["6 tbsp / 90g unsalted butter (, softened (or salted butter))","2 tsp parsley (, finely chopped)","2 garlic cloves (, very finely minced (2 tsp))","1/4 tsp salt (skip if using salted butter)"],"purpose":"Garlic Butter Stuffing:"},{"ingredients":["2 x 220 - 250g (7 - 8oz) chicken breast (, skinless and boneless (Note 1))","1/2 tsp salt","1/4 tsp pepper","1 egg (, lightly whisked)","1/4 cup flour","1 cup panko breadcrumbs (Note 2)","Oil for frying (, canola or vegetable oil (~4 cups / 1 litre))"],"purpose":"Chicken:"},{"ingredients":["Parsley (, finely chopped (garnish))"],"purpose":"Serving:"}]', '[{"title":"Garlic butter filling","description":"Place ingredients in a bowl and mix until combined.","images":[],"step":1},{"title":"Shape and chill butter","description":"Scrape butter on to a small sheet of baking / parchment paper and roughly shape into 10 x 6cm / 4 x 2.4\" rectangle. Refrigerate until firm, then cut in half lengthwise to form two batons.","images":[],"step":2},{"title":"Pound chicken","description":"Place chicken smooth side down between two freezer bags or paper (Note 3). Pound to an even 0.5 cm / 0.2\" thickness using a meat mallet (Note 4 for tips!)","images":[],"step":3},{"title":"Season","description":"Sprinkle each side of the chicken with salt and pepper.","images":[],"step":4},{"title":"Stuff and roll up chicken","description":"Place a baton of butter in the middle. Trim edges if needed, then add trimmings into the centre. Fold sides in over the butter, then roll the chicken up starting from the bottom, finishing with the seam side down.","images":[],"step":5},{"title":"Wrap and partially freeze","description":"Wrap the chicken log in cling wrap, twisting the ends tightly to create a firm log shape. Place in the freezer for 30 minutes until the surface is fairly firm to touch, but not frozen solid. (Note 5)","duration":30,"images":[],"step":6},{"title":"Crumb","description":"Place egg, flour and breadcrumbs in separate bowls. Coat chicken in flour, shaking off excess. Coat in egg, drip off excess. Then coat in breadcrumbs, pressing to adhere.","images":[],"step":7},{"title":"Partial freeze","description":"Place crumbed chicken in the freezer for 30 minutes until fairly firm to handle (but not frozen solid).","duration":30,"images":[],"step":8},{"description":"Preheat oven to 180°C / 350°F. Place a rack on a tray.","images":[],"step":9},{"title":"Fry","description":"Heat oil in a heavy based pot to 190°C / 375°F. Carefully place chicken in the oil and cook, turning once or twice, until golden (2 - 3 minutes). It will still be raw inside.","images":[],"step":10},{"title":"Bake","description":"Place chicken on a rack and bake for 15 minutes or until the internal temperature of the chicken is 65°C / 150°F. Pierce the top so you don''t cause butter leakage!","duration":15,"images":[],"step":11},{"description":"Rest for 2 minutes, then serve, sprinkled with a pinch of parsley if desired!","duration":2,"images":[],"step":12}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Russian"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","deep-fried-recipes","mains","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0992d206c899', 'en', 'US', 'Chicken Piccata (Lemon Chicken with Capers)', 'Recipe video above. If, like me, you find the sauce of other Chicken Piccata recipes too sour, and the chicken kind of bland, I think you''ll love this version! The lemon tang in the sauce is pleasant rather than lip-puckering, and the flavour of the chicken is boosted with a little parmesan in the flour coating.', 'https://www.recipetineats.com/tachyon/2021/05/Chicken-Piccata_0.jpg', 10, 0, 10, 3, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_parmesan", "quantity": {"value": 0.188, "unit": "pack of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_wine", "quantity": {"value": 0.222, "unit": "bottle of 750ml"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_capers_in_brine", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}]', '[{"ingredients":["450g / 16oz chicken breast (2 large pieces), skinless boneless (Note 1)","4 tbsp flour (sub cornflour/cornstarch for GF)","2 1/2 tbsp parmesan (, finely grated (Note 2))","1/2 tsp salt","1/4 tsp pepper","2 1/2 tbsp olive oil","1 tbsp / 15g unsalted butter"]},{"ingredients":["2 tbsp / 30g unsalted butter (, cut into 1.5cm / 1/2\" cubes)","2/3 cup dry white wine (Note 3)","2 tbsp lemon juice (, fresh)","3 tbsp capers in brine (, drained (Note 4))","1 1/2 tsp parsley (, finely chopped, plus more for garnish)"],"purpose":"Lemon Sauce:"}]', '[{"description":"Crispy Parmesan Chicken:","images":[],"step":1},{"description":"Cut each breast into 3 pieces. Then place between 2 pieces of cling wrap or paper and pound to 1/2 cm / 0.2\" thickness.","images":[],"step":2},{"description":"Drizzle chicken with 1/2 tbsp olive oil and spread with your fingers on both sides.","images":[],"step":3},{"description":"Mix flour, parmesan, salt and pepper in a shallow dish. Coat chicken, pressing to adhere, then shaking off excess.","images":[],"step":4},{"description":"Heat olive oil in a large skillet over medium high heat. Then add butter and let it melt.","images":[],"step":5},{"title":"Place 3 pieces of chicken in the skillet. Cook 3","description":"4 minutes until golden, then turn and cook the other side for 1 minute. Remove onto plate, repeat with remaining chicken.","duration":1,"images":[],"step":6},{"description":"Chicken Piccata Sauce:","images":[],"step":7},{"description":"Pour out and discard excess fat in skillet, then give it a quick wipe with paper towels (no need to clean thoroughly).","images":[],"step":8},{"description":"Still on medium high heat, add wine. Let it simmer rapidly until it reduces by half - around 3 minutes.","images":[],"step":9},{"description":"Add lemon and simmer 1 minute.","images":[],"step":10},{"description":"Reduce heat to low. Add cubed butter and swirl pan to make it melt but not go foamy. Sauce should be glossy, translucent and slightly thickened.","images":[],"step":11},{"description":"Stir in capers and parsley. Serve chicken with Sauce, sprinkled with extra parsley if desired!","images":[],"step":12}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["American-Italian","Western"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a24c6cbb0774', 'en', 'US', 'Sticky Glazed Christmas Chicken', 'Recipe video above. Everybody loves the glaze on a Christmas ham. So one year, I used it for chicken instead and people went mad over it! Easier and cheaper than ham, with a much higher ratio of glaze to meat, this is so good I''ve actually had people tell me they love this more than Christmas ham!!It''s ultra-sticky on the outside, and smells and tastes like Christmas. The meat is super tender – we''ve practically slow cooked the chicken!', 'https://www.recipetineats.com/tachyon/2020/12/Sticky-Glazed-Christmas-Chicken_1.jpg', 10, 60, 70, 6, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_oranges", "quantity": {"value": 0.025, "unit": "kg"}}, {"id": "ing_oranges", "quantity": {"value": 0.025, "unit": "kg"}}, {"id": "ing_vinegar", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.15, "unit": "jar of 200g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_cinnamon", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_whole_star_anise", "quantity": {"value": 2.0, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_oranges", "quantity": {"value": 0.025, "unit": "kg"}}, {"id": "ing_good_value_leafy_greens", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_oranges", "quantity": {"value": 0.025, "unit": "kg"}}]', '[{"ingredients":["1.2 kg / 2.4 lb chicken thighs, skin on, bone in ( (Note 1))","800g / 1.6 lb chicken drumsticks (, or more thighs (Note 1))"]},{"ingredients":["5 tsp orange zest (2 oranges)","1/2 cup orange juice (from the zested oranges)","1/4 cup cider vinegar (sub white wine, sherry or champagne vinegar)","1/2 cup brown sugar (, lightly packed)","2 tbsp Dijon mustard","1 tbsp olive oil","2 tsp ground cinnamon","1 1/2 tsp allspice","1 tsp ground ginger","2 whole star anise","2 tsp salt","1/2 tsp black pepper"],"purpose":"Marinade"},{"ingredients":["2 oranges (, cut into wedges or halved then sliced)","good value leafy greens (- like endive, watercress, for the bed)","orange zest curls (Note 3)"],"purpose":"Serving and garnishes"}]', '[{"description":"Marinate Chicken","images":[],"step":1},{"description":"Mix Marinade ingredients in a jug. Pour over chicken in a large ziplock bag (Note 2). Massage to coat, then marinate chicken for ideally 24 hours (bare minimum is 3 hrs, 12 hrs is ok).","images":[],"step":2},{"description":"Cook","images":[],"step":3},{"description":"Preheat oven to 200°C/390°F (180°C fan).","images":[],"step":4},{"description":"Line 2 trays with foil then parchment/baking paper (you''ll thank me later).","images":[],"step":5},{"description":"Distribute chicken on trays, then pour the marinade over. Roast 30 minutes.","images":[],"step":6},{"description":"Roast for a further 20 minutes, basting with pan juices 2 or 3 more times until the chicken is deep golden and sticky. At first, the juices will be watery but in the final 10 minutes or so, they will thicken and darken. Once this happens, baste more frequently and heavily. (Note 4)","images":[],"step":7},{"description":"When the top tray is almost ready, switch the tray positions (ie move bottom tray up and put the top tray undenerath) so they finish at the same time. GOAL: Deep golden and sticky chicken!","images":[],"step":8},{"description":"Before plating up, baste again with the sticky juices.","images":[],"step":9},{"title":"Serving suggestion","description":"Spread leafy greens on a platter, pile on sticky chicken. Decorate with orange slices or wedges.","images":[],"step":10}]', '["mustard"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Christmas","Holiday","Western"],"categories":["chicken","chicken-drumstick-recipes","chicken-recipes","mains"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_498c3fdc6fa7', 'en', 'US', 'Leftover Turkey Pot Pie', 'Recipe video above. Leftover turkey is quite dry, given it''s a lean meat. So smothering it in a creamy sauce for a Turkey Pot Pie is the ideal way to repurpose perfectly good leftovers! This is like a cross between Chicken Pot Pie and Cheesy Garlic Bread. While the filling is delicious, that buttery garlicky cheesy topping steals the show. I just love how it gets soaked with the creamy white sauce!!Use whatever veggies you want. And of course, chicken is a straight up simple substitute for turkey if that''s what you have.', 'https://www.recipetineats.com/tachyon/2020/11/Leftover-Turkey-Pot-Pie_1.jpg', 15, 40, 55, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_mushroom", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.625, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 5.0, "unit": "loaf"}}, {"id": "ing_parmesan", "quantity": {"value": 0.15, "unit": "pack of 200g"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.8, "unit": "pack of 125g"}}]', '[{"ingredients":["1 tbsp olive oil","150g / 5 oz mushrooms (, sliced 1/2cm / 1/5\" thick)","50g / 4 tbsp butter","1 onion (, finely chopped (brown, white, yellow))","2 garlic cloves (, minced)","1 carrot (, peeled, chopped into 1cm/ 1/3\" pieces)","4 tbsp flour (plain/all purpose)","2 1/2 cups milk (any fat % fine)","4 cups (600g) cooked chopped turkey or chicken","1 1/2 cups frozen peas","1 tsp chicken or vegetable stock powder (or 1 cube. I use Vegeta powder)","1/4 tsp salt","1/2 tsp black pepper"]},{"ingredients":["50g / 4 tbsp salted butter","2 garlic cloves (, minced using garlic press)","5 packed cups bread chunks ~2.5cm/1\" cubes (Note 1)","2 tbsp parmesan cheese (, grated (optional))","1 cup mozzarella or other melting cheese, shredded or sliced (or enough slices to cover most of top)"],"purpose":"Garlic Bread Topping"}]', '[{"description":"Preheat oven to 180°C/350°F (all oven types)","images":[],"step":1},{"title":"Topping","description":"Stir together melted butter and garlic. Place bread chunks in a bowl, drizzle over butter, toss. Set aside.","images":[],"step":2},{"title":"Brown mushrooms","description":"Heat oil in an oven-proof skillet over high heat. (Note 3) Add mushrooms and cook until browned - about 4 minutes. Remove.","images":[],"step":3},{"title":"Sauté garlic & onion","description":"Lower heat to medium high. Melt butter in same skillet. Add onion and garlic, cook for 2 minutes.","duration":2,"images":[],"step":4},{"description":"Add carrot then cook for 1 minute.","duration":1,"images":[],"step":5},{"description":"Add flour, cook for 1 minute. You''ll have a pasty mix. Don''t worry if it looks dry (depends how sweaty your onions get).","duration":1,"images":[],"step":6},{"title":"Make roux","description":"While stirring, add half the milk and mix quickly to dissolve the paste into the liquid (this happens quite quickly). Add remaining liquid and stir. Add stock powder, salt and pepper, stir.","images":[],"step":7},{"title":"Thicken sauce: Cook for 2","description":"3 minutes, stirring regularly. It should start steaming and bubbling a bit, and the sauce will thicken. Thickness test: coat back of wooden spoon, you should be able to draw a line across it (see video, Note 3)","duration":2.5,"images":[],"step":8},{"description":"Add turkey, peas and mushrooms, and mix into sauce.","images":[],"step":9},{"description":"Top with bread, spread to cover surface. Grate over parmesan if using, top with melting cheese.","images":[],"step":10},{"title":"Bake: Bake for 12","description":"15 minutes or until the cheese gets some brown spots. Tent foil over so it doesn''t stick to the cheese, then bake for a further 10 minutes.","duration":13.5,"images":[],"step":11},{"title":"Serve","description":"Sprinkle with additional parmesan if desired, then serve!","images":[],"step":12}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["American","Western"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","turkey-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1881ba70a6f1', 'en', 'US', 'Chicken with Creamy Mushroom Sauce', 'Recipe video above. The creamy mushroom sauce here is a cut above the usual basic recipes, thanks to the additions of wine, parmesan and chicken stock. It turns this quick chicken dinner into a meal that''s both worthy and elegant enough to serve to company!It''s an excellent sauce to serve with chicken breast, which is very lean and doesn''t actually have very much flavour. Also, the lightly-floured crust on the chicken makes it nice and crispy, giving the sauce something to cling on to. So don’t skip it!', 'https://www.recipetineats.com/tachyon/2020/10/Chicken-in-Creamy-Mushroom-Sauce_7.jpg', 5, 15, 20, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 15.0, "unit": "block of 250g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_wine", "quantity": {"value": 0.083, "unit": "bottle of 750ml"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["2 chicken breasts, large (boneless skinless, ~600-700g / 1.2 - 1.4 lb total, Note 1)","1/2 tsp salt","black pepper","1/4 cup flour","15g / 1 tbsp unsalted butter"],"purpose":"CRISPY CHICKEN"},{"ingredients":["30g / 2 tbsp unsalted butter","300g / 10 oz mushrooms (, sliced (button or Swiss brown))","2 garlic cloves (, minced)","1/4 cup dry white wine (sub more chicken stock, Note 2)","1/2 cup chicken or vegetable stock (, low sodium)","1 cup thickened / heavy cream (, full fat (Note 3))","1/2 cup parmesan (, finely and freshly grated (Note 4))"],"purpose":"Mushroom Sauce"},{"ingredients":["2 tbsp chives (, finely sliced (optional) – sub parsley, green onions, or omit)"],"purpose":"For serving"}]', '[{"title":"Split breast","description":"Cut each breast in half horizontally to form 4 thin steaks in total.","images":[],"step":1},{"title":"Dust with flour","description":"Sprinkle each side with salt and pepper, then sprinkle with flour and use your fingers to spread it all over the surface.","images":[],"step":2},{"title":"Cook chicken","description":"Melt 15g butter in a large non-stick frying pan over medium high heat. Add chicken and cook each side for 2 1/2 minutes until golden brown and just cooked through. Remove from pan, cover and keep warm.","images":[],"step":3},{"title":"Cook mushrooms","description":"In the same frying pan, add remaining butter and increase heat to high. Add mushrooms and cook for 4 minutes, until starting to turn golden brown on the edges.","duration":4,"images":[],"step":4},{"title":"Add garlic later","description":"Then add garlic and a pinch of salt and pepper, and continue cooking for another minute until both garlic and mushrooms are golden.","images":[],"step":5},{"title":"Deglaze skillet: Add white wine","description":"it will bubble and be steamy! Cook for 30 seconds, scraping the bottom of the pan, until wine is mostly evaporated and the alcohol smell is gone.","duration":0.5,"images":[],"step":6},{"title":"Make creamy sauce","description":"Add chicken stock, cook vigorously for 1 minute so it mostly evaporates. Then add cream, lower heat to medium and simmer for 2 minutes until it reduces and thickens slightly.","duration":1,"images":[],"step":7},{"title":"Add parmesan","description":"Stir in parmesan, taste and add more salt and pepper if needed.","images":[],"step":8},{"title":"Finish chicken in sauce","description":"Return chicken to sauce for 30 seconds (to warm through slightly.) Garnish with chives and serve as-is in the pan, for people to help themselves (or transfer to serving platter, if you prefer). Alternatively, serve a portion of chicken onto each plate, spoon sauce over and garnish with more chives.","duration":0.5,"images":[],"step":9},{"title":"Sides: Ideal served with mashed potato or rice","description":"something to soak in that amazing sauce! See Note 5 for suggestions.","images":[],"step":10}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","main-dishes","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_dd094ddfce27', 'en', 'US', 'Chicken Parmigiana', 'Recipe video above. Known as Chicken Parmesan in the US, the three key things that makes this the best Parmi you''ll ever have in your life are: layers upon layers on seasoning, dry brining for the most juicy chicken ever, and extra crispy chicken. Because I''ll never understand why you''d go to the trouble of making crispy crumbed chicken if the whole thing goes soggy when smothered in tomato sauce!Bonus baked option in Note 10. So golden and crunchy it will blow your mind!', 'https://www.recipetineats.com/tachyon/2020/09/Chicken-Parmigiana_7.jpg', 20, 40, 60, 6, '[{"id": "ing_chicken_breast", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_italian_mixed_herbs", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 0.281, "unit": "loaf"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 37.5, "unit": "pack of 1kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_wine", "quantity": {"value": 0.083, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_basil", "quantity": {"value": 10.0, "unit": "bunch"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.6, "unit": "pack of 125g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.5, "unit": "L"}}]', '[{"ingredients":["3 chicken breasts (300g/10z each) (, halved horizontally to form 6 pieces (Note 2))","1 tsp salt (, cooking / kosher (or 3/4 tsp table salt, Note 3))","1/2 tsp black pepper","1/2 tsp Italian mixed herbs (Note 4)"],"purpose":"Brined Chicken Marinade (Note 1):"},{"ingredients":["1/3 cup flour (, plain/all purpose)"],"purpose":"Flour dusting:"},{"ingredients":["2 eggs","1 garlic clove (, minced using garlic press)","1/4 tsp each salt and pepper","1/4 tsp Italian mixed herbs (Note 4)"],"purpose":"Egg Dredge:"},{"ingredients":["1 1/2 cups panko breadcrumbs (sub normal, Note 5)","1/2 cup parmesan (, finely grated (store bought sand-like is best) (Note 6))","1/2 tsp salt","1/4 tsp black pepper"],"purpose":"Parmigiana Bread Crumbing:"},{"ingredients":["2 cups olive oil (or vegetable or canola)"],"purpose":"Frying:"},{"ingredients":["1 tbsp olive oil","2 garlic cloves (, finely minced)","1/4 cup onion or eschallots (, very finely chopped (Note 7))","1/4 tsp red pepper flakes ((chilli flakes), optional)","1/4 tsp Italian mixed herbs (Note 4)","1/4 cup white wine (, anything (optional, Note 10))","400g / 14 oz tomato passata (aka tomato puree) (Note 8)","1/2 cup chicken stock/broth (or water)","1/4 tsp each salt and pepper"],"purpose":"Parmigiana Pasta Sauce:"},{"ingredients":["10 basil leaves (, roughly chopped (sub pinch of dried - or omit))","2 cups mozzarella cheese (, shredded (or enough slices to cover))","3/4 cup parmesan (, finely grated (best to grate your own, Note 6))","1 tbsp extra virgin olive oil"],"purpose":"Layering:"},{"ingredients":["5 basil leaves (, roughly chopped)"],"purpose":"Garnish (optional)"}]', '[{"description":"Dry Brine Chicken:","images":[],"step":1},{"description":"Sprinkle both sides of chicken with salt, pepper and Italian herbs. Refrigerate for 30 minutes.","duration":30,"images":[],"step":2},{"description":"Parmigiana Tomato Sauce:","images":[],"step":3},{"description":"Heat oil in a saucepan over medium heat. Add garlic and onion, cook for 3 minutes until onion is translucent.","duration":3,"images":[],"step":4},{"description":"Add red pepper flakes and herbs, stir for 15 seconds. Add wine, turn up heat and let it simmer rapidly until mostly evaporated and winey smell is gone.","duration":0.25,"images":[],"step":5},{"description":"Add tomato, chicken stock, salt and pepper. Cover, then simmer 10 minutes on low until thickened. Cover and keep warm.","images":[],"step":6},{"description":"Preheat oven to 180°C/350°F.","images":[],"step":7},{"title":"Crumbing set up","description":"Spread flour out in a shallow bowl. Whisk Egg Dredge in a separate shallow bowl. Mix Crumbing ingredients in a third shallow bowl or pan.","images":[],"step":8},{"title":"Dredge & crumb","description":"Press both sides of chicken into flour, then shake off excess. Coat in egg, letting excess drip off, then place in Crumbing, pressing to adhere.","images":[],"step":9},{"description":"Transfer to plate and repeat with remaining chicken.","images":[],"step":10},{"description":"Frying (Note 10 for baked option):","images":[],"step":11},{"description":"Line a tray with paper towels and place rack on tray.","images":[],"step":12},{"title":"Heat 1.5","description":"2cm / 2/3\" oil in a skillet over medium high heat to 180°C/350°F (Note 9).","images":[],"step":13},{"description":"Carefully place 2 or 3 pieces of chicken in. Cook 2 minutes until underside is golden, then carefully turn and cook the other side for 1 1/2 minutes.","images":[],"step":14},{"description":"Transfer to rack, then repeat with remaining chicken. (Note 12 - oil clean and reuse)","images":[],"step":15},{"description":"Assembling & baking:","images":[],"step":16},{"description":"Place chicken on a tray. Spoon 1/3 cup sauce over the chicken - cover around 80% of the chicken, leave the ends crispy.","images":[],"step":17},{"description":"Sprinkle sauce with basil, then mozzarella cheese (pile it on in mounds to use it all up), then sprinkle with parmesan. Drizzle oil over parmesan.","images":[],"step":18},{"description":"Bake 15 minutes until cheese is melted and there''s a few brown spots - no longer, otherwise chicken will overcook.","images":[],"step":19},{"description":"Remove from oven, sprinkle with extra basil if desired. Serve immediately (with leftover Tomato Sauce, if you''d like!)","images":[],"step":20}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","deep-fried-recipes","iconic-dishes","main-dishes","mains","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8a2b5a3fc447', 'en', 'US', 'Gravy Baked Chicken (thighs & drumsticks) - 5 min prep!', 'Recipe video above. Crispy baked chicken thighs and drumsticks that magically makes its own gravy - all in one pan! Terrific last minute chicken dinner that takes minutes to prepare and is zero maintenance to cook. The flavour in the gravy is phenomenal because it''s flavoured with the chicken juices!', 'https://www.recipetineats.com/tachyon/2020/07/Gravy-Baked-Chicken.jpg', 5, 50, 55, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.25, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.375, "unit": "L"}}]', '[{"ingredients":["1.25 kg/ 3 lb bone in, skin on chicken thighs and/or drumsticks (all of one, or mix, Note 1)","2 tsp olive oil (or other oil)"]},{"ingredients":["1 tsp paprika powder","1 tsp dried thyme","1 tsp onion powder (or garlic powder)","1 tsp salt","1/2 tsp black pepper"],"purpose":"Chicken seasoning:"},{"ingredients":["4 tbsp flour (, plain/all purpose (Note 2 for GF))","1 1/2 cups beef stock/broth (yes, beef, not chicken! Note 3)","1/2 tsp black pepper"],"purpose":"Gravy:"}]', '[{"description":"Preheat oven to 200°C/390°F (180°C fan).","images":[],"step":1},{"title":"Seasoning","description":"mix in a small bowl.","images":[],"step":2},{"title":"Season chicken","description":"Place chicken in a 23 x 33cm / 9 x 13\" baking pan. Drizzle with oil then rub all over Sprinkle & rub in the Seasoning, using most on the skin side.","images":[],"step":3},{"description":"Arrange chicken skin side up in the pan.","images":[],"step":4},{"title":"Gravy mixture","description":"Whisk flour with about 1/2 cup of stock until lump free, then whisk in remaining stock and pepper (forgot in video!). Pour into the pan around the chicken.","images":[],"step":5},{"description":"Bake uncovered for 50 minutes, or until chicken is crispy and golden.","duration":50,"images":[],"step":6},{"title":"Whisk gravy","description":"Remove chicken onto a plate, then give the gravy a good whisk to make it smooth. Adjust Gravy thickness if required - Note 4. Taste and add salt and pepper, if needed.","images":[],"step":7},{"title":"Serve","description":"Pour gravy into a jug. Serve alongside chicken!","images":[],"step":8}]', '["gluten"]', '["high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-drumstick-recipes","chicken-recipes","emergency-recipes","main-dishes","one-pot-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_39f510179260', 'en', 'US', 'Chicken Salad - quick, easy, BIG!', 'Recipe video above. Here''s a speedy main course size salad that''s filled with all my favourite vegetables. I like this because it''s filled, colourful, interesting enough to serve to friends, but quick enough for a fast lunch, filling enough for dinner.', 'https://www.recipetineats.com/tachyon/2020/06/Quick-Chicken-Salad_6.jpg', 15, 0, 15, 4, '[{"id": "ing_chicken", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 36.0, "unit": "head"}}, {"id": "ing_corn", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_avocado", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_bacon", "quantity": {"value": 0.75, "unit": "pack of 200g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.09, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_mixed_herbs", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["3 cups store bought roast chicken (, shredded (Note 1))","12 cups cos / romaine lettuce (2 medium, 1 giant) (, chopped into bite size pieces (or other leafy greens))","1 cup corn kernels (can, drained - about 2/3 can)","1/2 red onion (, finely sliced)","300g/ 10oz cherry or grape tomatoes (or 2 normal tomatoes chopped)","2 cucumbers (, halved lengthwise then sliced 1cm / 1/3\" (or 1 long English/telegraph cucumber))","2 avocados (, cut into bite size chunks (or 1 giant one))","150g/ 5oz bacon (, cooked until crisp then chopped (optional))"]},{"ingredients":["2 1/2 tbsp cider vinegar (Note 2)","6 tbsp extra virgin olive oil","1 garlic clove (, minced using garlic press (~1 tsp))","1 tsp Dijon Mustard (or any smooth, non spicy mustard, optional)","2 tsp dried mixed herbs (Note 3 for subs)","1 tsp sugar (, optional (Note 4))","3/4 tsp salt","1/2 tsp black pepper"],"purpose":"Dressing:"}]', '[{"title":"Dressing","description":"Place ingredients in a jar, shake, set aside for at least 10 minutes to let flavours meld.","images":[],"step":1},{"title":"Salad","description":"Place all ingredients except bacon in a big bowl. Drizzle over most of the Dressing, then toss well.","images":[],"step":2},{"description":"Transfer to serving bowl, drizzle with remaining Dressing. Sprinkle with bacon. Serve immediately!","images":[],"step":3}]', '["mustard"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-recipes","salad-recipes-main-course"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ce4b1beecdc2', 'en', 'US', 'Oven Baked BBQ Chicken - with quick homemade barbecue sauce', 'Recipe video above. This is how I make BBQ Chicken in the oven when I''m craving sticky chicken but don''t want to fire up the BBQ! Made with a quick homemade BBQ sauce, the chicken is braised in the sauce which is loaded with extra flavour from the juices of the chicken. Fabulous sticky glaze, juicy inside!', 'https://www.recipetineats.com/tachyon/2016/10/Baked-BBQ-Chicken-with-Barbecue-Sauce_2.jpg', 10, 50, 60, 5, '[{"id": "ing_ketchup", "quantity": {"value": 0.3, "unit": "bottle of 500g"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.125, "unit": "bottle of 500ml"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 cup ketchup (or Australian/UK tomato sauce)","1/4 cup apple cider vinegar","2 tsp Worcestershire Sauce","4 tbsp brown sugar","2 tsp mustard powder","2 tsp onion powder","1/2 tsp salt","1/2 tsp fresh black pepper","1 cup water"],"purpose":"Sauce (Note 1)"},{"ingredients":["1.5 kg / 3 lb chicken thighs (bone in skin on), drumsticks or wings (Note 2)","Fresh parsley, chives or finely chopped green onions (, for garnish)"],"purpose":"Chicken"}]', '[{"description":"Preheat oven to 200°C/390°F.","images":[],"step":1},{"title":"Sauce","description":"Mix all Sauce ingredients in a ceramic/glass baking dish (Note 3), then mix in water.","images":[],"step":2},{"description":"Add chicken and turn to coat. Place chicken skin side down.","images":[],"step":3},{"description":"Bake for 20 minutes. Remove from oven, turn chicken, spoon over Sauce.","duration":20,"images":[],"step":4},{"description":"Bake for a further 30 minutes, then remove and spoon over Sauce.","images":[],"step":5},{"title":"Skim off fat (optional)","description":"Tilt pan and spoon or drain off excess fat.","images":[],"step":6},{"title":"Broil/grill","description":"Change to broiler/grill on high. Spoon sauce over chicken generously, then place under grill / broiler for 2 to 3 minutes to caramelise the chicken and the sauce to thicken more. Do not walk away - this can happen quickly!","duration":2.5,"images":[],"step":7},{"description":"Serve chicken, garnished with parsley or green onions, if using. Pictured in post with Mashed Potato and Green Bean Salad (minus feta).","images":[],"step":8},{"description":"Classic Side Dishes for BBQ Chicken","images":[],"step":9},{"description":"Cornbread, Coleslaw, Potato Salad (or try this no mayo Lemon Potato Salad), Southern Baked Beans, big leafy salad with classic Vinaigrette, steamed corn with butter, bread rolls, creamy mashed potato (or Creamy Cauliflower Mash for low carb emergency!), or Potato & Gravy.","images":[],"step":10}]', '["mustard"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-recipes","dinner-tonight","main-dishes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9df5f1a1dfd1', 'en', 'US', 'Oven Baked Chicken and Rice', 'Recipe VIDEO above. Made entirely in the oven (no stove!), the rice in this recipe is outrageously delicious! It''s buttery and garlicky, tender but not mushy. The secret tip is to briefly bake onion with garlic and butter before adding the rice, liquids and chicken - it adds a great flavour base!', 'https://www.recipetineats.com/tachyon/2018/06/Oven-Baked-Chicken-and-Rice_0.jpg', 10, 70, 80, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_white_rice", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["5 bone in chicken thigh fillets, peel skin OFF (, (Note 1))","1 onion (, chopped (brown, white or yellow))","2 cloves garlic (large) (, minced)","2 tbsp (30g) butter (or olive oil)","1 1/2 cups (270g) uncooked white rice (Note 3)","1 1/2 cups (375 ml) chicken broth/stock (, hot (I microwave))","1 1/4 cups (315 ml) water (, hot (tap is fine))"]},{"ingredients":["1 tsp paprika powder","1 tsp dried thyme","1/2 tsp garlic powder","1/2 tsp onion powder","3/4 tsp salt","Black pepper"],"purpose":"Chicken Rub (Note 2):"},{"ingredients":["Oil spray","Fresh thyme leaves or finely chopped parsley"],"purpose":"Optional garnish:"}]', '[{"description":"Preheat oven to 180°C/350°F.","images":[],"step":1},{"description":"Scatter onion and garlic in a baking dish (about 10 x 15\" / 25 x 35 cm), then place butter in the centre. Bake for 15 minutes (check at 12 minutes, mix if some bits are browning too much).","duration":15,"images":[],"step":2},{"description":"Meanwhile, mix together Chicken Rub. Sprinkle on both sides of the chicken.","images":[],"step":3},{"description":"Remove baking dish from the oven. Add rice then mix.","images":[],"step":4},{"description":"Place chicken on rice. Then pour chicken broth and water around the chicken.","images":[],"step":5},{"description":"Cover with foil, then bake for 30 minutes. Remove foil, spray chicken with oil (optional, gives chicken nicer finish), then bake for a further 20 minutes until liquid is absorbed.","duration":30,"images":[],"step":6},{"description":"Stand for 5 minutes, then remove chicken and fluff up rice. Garnish with parsley or thyme if desired, serve and enjoy!","duration":5,"images":[],"step":7},{"description":"Dish is flavoured enough to serve without sauce, but if you want to take it over the top, make this quick Gravy in 4 minutes flat (pictured in video).","images":[],"step":8}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","dietary","emergency-recipes","gluten-free-recipes","mains","one-pot-recipes","quick-and-easy","rice-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6b970abcff5b', 'en', 'US', 'Chicken Enchiladas', 'Recipe video above. If you like your enchiladas plump, juicy, saucy and full of flavour, this is the recipe for you! Homemade from scratch, the foundation of this recipe is a double duty Enchilada Spice mix.', 'https://www.recipetineats.com/tachyon/2020/03/Chicken-Enchiladas_4.jpg', 20, 45, 65, 8, '[{"id": "ing_tortillas", "quantity": {"value": 8.0, "unit": "pack of 8"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 8.0, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 5.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_refried_beans", "quantity": {"value": 400.0, "unit": "pack"}}, {"id": "ing_corn", "quantity": {"value": 8.0, "unit": "can of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["8 tortillas (, flour or corn (about 20cm/8\" wide, Note 1))"]},{"ingredients":["1 tsp EACH onion powder, garlic powder, salt","1 tbsp EACH dried cumin powder, paprika, dried oregano","1/4 tsp black pepper","3/4 tsp cayenne pepper (optional, adjust to taste)"],"purpose":"Enchilada Seasoning:"},{"ingredients":["2 tbsp olive oil","3 tbsp flour (, plain/all purpose)","2 cups (500ml) chicken stock/broth (, low sodium)","1.5 cups (375ml) tomato passata or US puree (Note 4 sub)"],"purpose":"Enchilada Sauce"},{"ingredients":["600g / 1.2lb chicken breast (, sliced in half horizontally (or boneless thigh) (Note 2))","2 tbsp olive oil (, separated)","1/2 onion (, chopped)","2 garlic cloves (, finely minced)","1 red capsicum/bell pepper (, diced)","400g / 14oz refried beans (Note 3)","400g/14oz canned corn (, drained (sub frozen 1 3/4 cups))","1/4 cup (65ml) water","1 cup (100g) cheese (shredded (Mexican cheese blend, Monterey Jack, cheddar))"],"purpose":"Chicken Filling:"},{"ingredients":["1.5 cups (150g) cheese (, shredded)","2 tbsp coriander/cilantro (, roughly chopped)"],"purpose":"Topping"}]', '[{"title":"Enchilada Seasoning","description":"Mix Enchilada Seasoning Spices. To be used for Filling and Sauce.","images":[],"step":1},{"description":"Enchilada Sauce","images":[],"step":2},{"title":"Make roux","description":"Heat oil in saucepan over medium heat. Add flour and stir 20 seconds.","images":[],"step":3},{"title":"Add other ingredients","description":"Add 2 tbsp Enchilada Seasoning, broth and tomato. Stir to combine.","images":[],"step":4},{"title":"Simmer to thicken","description":"Increase heat slightly to medium high. Cook for 4 minutes, whisking regularly, until the sauce thickens to the consistency of thick syrup (see video). Remove from stove.","duration":4,"images":[],"step":5},{"description":"Chicken Filling","images":[],"step":6},{"title":"Coat chicken","description":"Drizzle 1 tbsp oil over chicken, mix to coat. Sprinkle with Seasoning, toss to coat.","images":[],"step":7},{"title":"Cook chicken","description":"Heat remaining 1 tbsp oil in a large skillet over high heat. Add chicken, cook 2 minutes. Turn and cook 1.5 minutes. Remove, rest 2 minutes then chop.","images":[],"step":8},{"title":"Saute onion","description":"In the same skillet, add onion and garlic, cook 1 minute. Add capsicum, cook 2 minutes until onion is translucent.","images":[],"step":9},{"title":"Add everything else","description":"Add refried beans, diced chicken, corn and water. Stir and cook for 2 minutes until reduces slightly. Should be thick and juicy, not watery.","duration":2,"images":[],"step":10},{"description":"Assemble and bake:","images":[],"step":11},{"description":"Preheat oven to 180°C/350°F.","images":[],"step":12},{"title":"Roll","description":"Lay tortilla on work surface. Spread 2/3 cup Filling on lower third, sprinkle with cheese then roll up, finishing with the seam side down (to hold it closed). Repeat to make 8.","images":[],"step":13},{"description":"Smear a scoop of Enchilada Sauce across base of 22 x 33cm /9 x 13\" pan. Place Enchiladas in, pour over remaining Sauce, sprinkle with cheese.","images":[],"step":14},{"title":"Bake 20","description":"25 minutes or until cheese is melted and golden. Serve immediately, sprinkled with coriander!","images":[],"step":15}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["chicken-recipes","enchiladas","main-dishes","mexican-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b186d4aa6e30', 'en', 'US', 'Mediterranean Chicken Dinner', 'Recipe video above. Infused with classic Mediterranean flavours of garlic, lemon, oregano and paprika, this is a terrific quick dinner idea. The sauce is the star of this and marinating is optional! I made this with drumsticks but you can make this with bone-in chicken thigh fillets too.', 'https://www.recipetineats.com/tachyon/2015/11/Lemon-Garlic-Chicken-Potato-Bake_7-copy.jpg', 10, 55, 55, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.15, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 10.0, "unit": "pack of 3 heads"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_paprika", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_potato", "quantity": {"value": 5.0, "unit": "bag of 2kg"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}]', '[{"ingredients":["1kg / 2lb bone in, skin on chicken thighs and drumsticks (Note 1)","1/2 cup (125 ml) lemon juice","6 cloves garlic (, minced)","2 tsp Dijon mustard (Optional - Note 2)","2 tbsp honey or 1 tbsp sugar (or maple or other sweetener)","1 tbsp dried oregano","1.5 tsp paprika","1 tbsp olive oil","1/2 tsp EACH salt and pepper"],"purpose":"Marinade / Sauce"},{"ingredients":["5 smallish potatoes (7.5cm/3\" wide) (, quartered (Note 3))","2 red onions (, quartered)","1 cup (250ml) chicken broth/stock (, low sodium)","250g/8oz cherry tomatoes (whole)","1/2 tsp EACH salt and pepper","1 tbsp Olive oil (or oil spray)","Fresh oregano (, for garnish (optional))"],"purpose":"Bake"}]', '[{"description":"Mix Marinade ingredients in a bowl, then add chicken and toss to coat. If time permits, marinate for 24 hours, otherwise proceed to next step.","images":[],"step":1},{"description":"Preheat oven to 180C/350F.","images":[],"step":2},{"description":"Place potatoes and onion in baking pan, top with chicken. Pour over the chicken stock then marinade from the bowl.","images":[],"step":3},{"description":"Bake for 20 minutes, then remove from oven.","duration":20,"images":[],"step":4},{"description":"Scatter over cherry tomatoes, drizzle everything with 1 tbsp olive oil, sprinkle with salt and pepper. Bake for a further 30 - 35 minutes until chicken is golden and potatoes are cooked.","images":[],"step":5},{"description":"Remove from oven, garnish with fresh oregano if using and serve!","images":[],"step":6}]', '["mustard"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mediterranean","Western"],"categories":["chicken-drumstick-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","mediterranean-recipes","most-popular","one-pot-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_23566a2a247a', 'en', 'US', 'Fried Chicken - ultra craggy crispy crust!', 'Recipe video above. This is a fried chicken recipe that''s made using a technique that yields an incredible super crunchy, really craggy crust with loads of nubbly bits that get extra crunchy! Seasoned with a KFC copycat 11 Secret Herbs and Spices - but better than KFC, there''s no trace of soggy bits at all! Flesh is juicy all the way through thanks to a classic Southern buttermilk marinade (read in post why there''s no spices in the marinade!).Serve with French fries and potato with gravy for an epic homemade KFC experience at home.', 'https://www.recipetineats.com/tachyon/2020/01/Fried-Chicken_2.jpg', 15, 30, 45, 10, '[{"id": "ing_bone_in_skin_on_small_thighs_drumsticks_whole_wings_breast", "quantity": {"value": 1.8, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_flour", "quantity": {"value": 0.338, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.281, "unit": "pack of 400g"}}, {"id": "ing_celery", "quantity": {"value": 0.075, "unit": "head"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.45, "unit": "jar of 50g"}}, {"id": "ing_paprika", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_ginger", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 1.5, "unit": "L"}}]', '[{"ingredients":["1.8 kg/ 3.6lb bone in, skin on small thighs (< 200g/7oz), drumsticks, whole wings, breast (< 200g/7oz) (Note 1)"]},{"ingredients":["1 cup buttermilk (Note 2 for sub)","1 tbsp salt","1 egg"],"purpose":"Buttermilk marinade:"},{"ingredients":["2 1/4 cups flour (, plain / all purpose)","3/4 cup corn flour / cornstarch"],"purpose":"Fried Chicken Breading (Note 9):"},{"ingredients":["3 tsp salt","3/4 tsp celery salt","1.5 tbsp black pepper (Note 2)","1.5 tsp sweet paprika (ie. not hot or smoked)","1/2 tsp cayenne pepper (, optional)","1.5 tsp onion powder","3 tsp garlic powder","1 tsp mustard powder","3/4 tsp ginger powder","1.5 tsp dried thyme","1.5 tsp dried oregano"],"purpose":"KFC 11 Secret Herbs and Spices (Note 9):"},{"ingredients":["1.5 - 2 litres / quarts vegetable oil (or canola or peanut, Note 8 for re-use)"],"purpose":"To fry:"}]', '[{"description":"Buttermilk Marinade Chicken:","images":[],"step":1},{"description":"Mix Marinade in a bowl until salt dissolves.","images":[],"step":2},{"description":"Pour over chicken in ziplock bag, massage to coat chicken. Press out excess air, seal, refrigerate 12 to 24 hours, turning once or twice.","images":[],"step":3},{"description":"Pour chicken and marinade into large bowl.","images":[],"step":4},{"description":"Breading mixture:","images":[],"step":5},{"description":"Whisk together Breading and all KFC Secret Herbs & Spices.","images":[],"step":6},{"description":"Drizzle 4.5 tablespoons of Marinade into flour mixture. Use fingers to rub in so you get lots of pea sized lumpy bits all throughout (this creates extra super crunchy craggy bits).","images":[],"step":7},{"description":"Spread out in a shallow dish or pan (easier to work with).","images":[],"step":8},{"description":"Prepare to cook (work in specified order of steps):","images":[],"step":9},{"title":"Preheat oven to 80°C/175°F and place rack on tray","description":"to keep chicken warm. (Note 3)","images":[],"step":10},{"description":"Add oil to a wide, heavy based pot to a depth of 6 cm / 2.5 \" (my 26cm/10.5\" cast iron pot = 1.75L/quarts oil, Note 4)","images":[],"step":11},{"description":"Heat oil over medium to medium high heat to 180°C/350°F - maintain temp as best you can (Note 5).","images":[],"step":12},{"title":"Cooking order","description":"Start with thighs and drumsticks, wings next and cook breast last. (Note 6).","images":[],"step":13},{"description":"Squidge a piece of chicken in remaining marinade, place in flour.","images":[],"step":14},{"description":"Coat well, pressing very firmly to adhere. Transfer to plate.","images":[],"step":15},{"title":"Coat 2 or 3 more pieces","description":"just for one cooking batch, covering oil surface in single layer. (Note 7)","images":[],"step":16},{"title":"Carefully place chicken in oil","description":"it will bubble energetically but it will not spit.","images":[],"step":17},{"description":"Once chicken is in, oil temperature should drop to 150°C/300°C - adjust heat to target this.","images":[],"step":18},{"title":"DO NOT TOUCH chicken for 2 minutes","description":"to let the crust bond with the chicken skin. After this, you can move them around but oil should be deep enough that you do not need to flip (but you can if you want!).","duration":2,"images":[],"step":19},{"title":"Thighs and drumsticks","description":"cook for 8 minutes (wings for 5 minutes), or until deep golden brown and internal temperature at thickest part is 75°C / 167°F.","duration":8,"images":[],"step":20},{"title":"Breast","description":"fry for 6 minutes or until internal temperature at thickest part is 65°C / 150°F (time depends on size).","duration":6,"images":[],"step":21},{"description":"Place onto rack and keep warm in oven. Repeat with remaining chicken, coating each batch just prior to cooking.","images":[],"step":22},{"description":"Serve immediately!","images":[],"step":23},{"title":"Classic sides","description":"Coleslaw, KFC copycat potato and gravy, steamed or grilled corn, cornbread or soft rolls, fries, potato salad, Southern Baked Beans!","images":[],"step":24}]', '["egg","gluten","mustard","peanuts"]', '["high_protein","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Southern","Western"],"categories":["chicken-drumstick-recipes","chicken-recipes","deep-fried-recipes","iconic-dishes","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_96ca396a836b', 'en', 'US', 'Poached Chicken - Foolproof, perfect, AMAZINGLY juicy breast', 'Recipe video above. Forget every other method you''ve used. This recipe GUARANTEES the juiciest chicken breast you''ve ever made in your life. No special equipment, no fancy gadgets. It''s dead easy and foolproof. Use for anything that calls for cooked chicken. Slice it, dice it, shred it, pile onto sandwhiches. HIGH ALTITUDE locations - please see note 4', 'https://www.recipetineats.com/tachyon/2020/01/Poached-Chicken_8.jpg', 10, 25, 35, 2, '[{"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}]', '[{"ingredients":["2 chicken breasts (, boneless skinless, 250g/8.5 oz each (Note 1))"]},{"ingredients":["1 lemon (, quartered)","1 bay leaf (, dried or fresh)","2 garlic cloves (, minced)"],"purpose":"Optional flavourings (Note 2)"}]', '[{"description":"Take chicken out of the fridge 30 minutes before cooking.","images":[],"step":1},{"description":"Fill a saucepan with water so the chicken breast will be well submerged with at least 2\" / 5cm of water above it in a single layer (can be snug but do not stack).","images":[],"step":2},{"description":"Add Flavourings, if using (squeeze in lemon juice, add used lemon).","images":[],"step":3},{"description":"Bring water to boil.","images":[],"step":4},{"description":"Place chicken breast in water, place lid on, bring back up to the boil. IMMEDIATELY remove saucepan from stove and set aside for 20 minutes (it''s fine up to 45 min to 1 hr, won''t overcook).","duration":20,"images":[],"step":5},{"description":"Remove chicken from water. Slice and be amazed how perfectly juicy and tender the breast is!! Or chop/shred and use as desired.","images":[],"step":6},{"description":"If reserving for later use, cover loosely to cool then refrigerate whole - see Note 6.","images":[],"step":7}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","gluten-free-recipes","good-to-know","low-calorie-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c4b2f08f43a9', 'en', 'US', 'Crispy Oven Baked Chicken Tenders', 'Recipe video above. Beautifully golden, truly crunchy baked chicken tenders! The trick is to toast the breadcrumbs before coating the chicken. See recipe notes for pictured Honey Mustard Dipping sauce.', 'https://www.recipetineats.com/tachyon/2015/04/Crunchy-Baked-Chicken-Tenders_6.jpg', 15, 15, 30, 3, '[{"id": "ing_bread", "quantity": {"value": 0.281, "unit": "loaf"}}, {"id": "ing_oil", "quantity": {"value": 2.0, "unit": "bottle"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.037, "unit": "jar of 400g"}}, {"id": "ing_mustard", "quantity": {"value": 0.113, "unit": "jar of 200g"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chicken", "quantity": {"value": 0.5, "unit": "kg"}}]', '[{"ingredients":["1 1/2 cups panko breadcrumbs (Note 1)","Oil spray"],"purpose":"Breadcrumb"},{"ingredients":["1 egg","1 tbsp mayonnaise","1 1/2 tbsp dijon mustard (or other mustard)","2 tbsp flour","1/2 tsp salt","Black pepper"],"purpose":"Batter"},{"ingredients":["500 g/1 lb chicken tenderloins (or breast cut into 2/3\" / 1.5cm thick slices, lengthwise)","Oil spray"],"purpose":"Chicken"}]', '[{"description":"Preheat oven to 200°C/390°F (180° fan-forced).","images":[],"step":1},{"title":"Toast panko","description":"Spread panko on a baking tray, spray with oil (spray vertically to avoid blowing the panko off the tray), then bake for 3 to 5 minutes until light golden. Transfer to bowl.","duration":4,"images":[],"step":2},{"description":"Place a rack on a baking tray (not critical but bakes more evenly).","images":[],"step":3},{"title":"Dredge batter","description":"Place the Batter ingredients in a bowl and whisk with a fork until combined. Add the chicken into the Batter and toss to coat.","images":[],"step":4},{"description":"Crumbing (see video & photo in post)","images":[],"step":5},{"description":"Pick up chicken with tongs and place it into the panko bowl.","images":[],"step":6},{"title":"Crumb","description":"Sprinkle surface with breadcrumbs, then press down to adhere. Transfer onto baking tray. Marvel at clean fingers, repeat with remaining chicken.","images":[],"step":7},{"title":"Spray & bake","description":"Spray lightly with oil, sprinkle with a touch of salt (optional). Bake 15 minutes (medium) or up to 20 minutes if gigantic. Any longer = dried out chicken.","images":[],"step":8},{"title":"Serve","description":"Remove from oven and serve immediately, with Sauce of choice (Honey Mustard pictured, see Note 2) and sprinkled with fresh parsley, if desired.","images":[],"step":9}]', '["egg","gluten","mustard"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["main_course"],"cuisine":[],"categories":["chicken","chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","mains","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2010c7dbba4d', 'en', 'US', 'Slow Cooker Mexican Chicken Soup', 'Recipe video above. 10 minutes prep, then throw everything into your slow cooker and come home to the ultimate comfort food. This is a hearty, chunky soup that just happens to be healthy. Excessive toppings are a must!', 'https://www.recipetineats.com/tachyon/2014/05/Slow-Cooker-Mexican-Chicken-Soup_8.jpg', 10, 480, 490, 7, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_chicken", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_black_beans", "quantity": {"value": 2.0, "unit": "can of 400g"}}, {"id": "ing_corn", "quantity": {"value": 2.0, "unit": "can of 400g"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_tortillas", "quantity": {"value": 1.0, "unit": "pack of 8"}}]', '[{"ingredients":["1 tbsp olive oil","1 onion (, diced (brown, white, yellow))","1 red capsicum/bell pepper (, large, diced)","3 cloves garlic (, minced)","3 cups (750ml) chicken broth/stock (, low sodium)","800g / 28 oz canned black beans, drained (2 cans, or other beans, Note 1)","800g / 28 oz canned corn, drained (2 cans, or 500g/1lb frozen or fresh corn)","800g / 28oz crushed canned tomato (OR 700g tomato passata (Note 2))","500g / 1 lb chicken breast"]},{"ingredients":["1 tbsp dried oregano","2 tsp cumin powder","2 tsp paprika powder","1 tsp each onion powder and garlic powder (or 2 tsp of one of them)","1 tsp cayenne pepper (optional, adjust spiciness)","1 tsp each salt + black pepper"],"purpose":"Spices"},{"ingredients":["Shredded cheese (recommended)","Sour cream or yogurt (recommended)","Coriander/cilantro (recommended)","Lime wedges (recommended)","Avocado, diced","Corn chips or tortillas (, for dunking)"],"purpose":"Toppings"}]', '[{"description":"Heat the oil over medium heat in a large skillet and sauté the onion, capsicum/bell pepper and garlic for 5 minutes until translucent.","duration":5,"images":[],"step":1},{"description":"Add a splash of chicken broth, bring to simmer then tip it all into the slow cooker. (Instant Pot: Do Step 1 & 2 on saute function).","images":[],"step":2},{"description":"Add remaining chicken broth, Spices, corn, bean and tomato. Give it a good stir, then add chicken and push down to submerge.","images":[],"step":3},{"description":"Slow cook for 6 to 8 hours on LOW. (Or pressure cooker 25 minutes on high, see Note for stove).","images":[],"step":4},{"description":"Remove chicken onto plate, shred with 2 forks. Return into slow cooker, give it a good stir. Check if it needs more salt or pepper.","images":[],"step":5},{"description":"Ladle into bowls and serve with Toppings of choice!","images":[],"step":6}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Mexican"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","gluten-free-recipes","low-calorie-recipes","main-dishes","mexican-recipes","quick-and-easy","slow-cooker-recipes","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_49cb8ba13215', 'en', 'US', 'Crispy Herb Baked Chicken with Gravy', 'Recipe video above. This is a fantastic, easy way to make "roast chicken" for loads of people without the fuss of man handling a whole chicken! Quick to prepare, no advance marinating or brining, the idea here is high temp cooking which really seals in the juices, creating crispy skin and meat that''s so juicy, it''s ideal for reheating to serve (which is what we did for a 40 guest Christmas lunch last weekend). Bonus mess-free way of making gravy with outrageously delicious flavour.', 'https://www.recipetineats.com/tachyon/2019/12/Herb-Baked-Chicken-and-Gravy_4-HERO.jpg', 5, 35, 40, 6, '[{"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 1.8, "unit": "kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 1.8, "unit": "kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_rosemary", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_sage", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_marjoram", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.015, "unit": "bottle of 250ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["1 tbsp vegetable oil (or canola or peanut oil, NOT butter or olive oil, Note 1)"]},{"ingredients":["1.8 kg / 3.6 lb whole chicken, butterflied / spatchcocked","1.8 kg / 3.6 lb large chicken thighs with bone in, skin on AND drumsticks (mix)"],"purpose":"Choose ONE chicken (Note 2):"},{"ingredients":["1 tsp dried oregano","1 tsp dried rosemary","1 tsp dried thyme","1 tsp dried sage (or 1/2 tsp ground sage)","3/4 tsp dried marjoram","1 tsp salt (coarse / kosher salt, OR 1 3/4 tsp sea salt flakes)","1/2 tsp black pepper"],"purpose":"Herb rub (Note 3):"},{"ingredients":["3 tbsp flour","1 1/2 cups (375ml) chicken stock/broth (, low sodium)","3/4 tsp dark soy sauce or gravy browner liquid","Salt and pepper to taste"],"purpose":"Gravy"}]', '[{"description":"Fridge dry skin (optional, for extra crispy skin):","images":[],"step":1},{"description":"Pat chicken skin dry with paper towels. Leave chicken in fridge overnight, uncovered, to dry skin out.","images":[],"step":2},{"description":"Cooking:","images":[],"step":3},{"description":"Preheat oven to 240°C/ 465°F (220°C fan).","images":[],"step":4},{"description":"Line tray with foil then baking / parchment paper, place rack on tray (Note 4)","images":[],"step":5},{"description":"Mix Rub in a bowl.","images":[],"step":6},{"description":"Pat chicken skin dry with paper towel.","images":[],"step":7},{"description":"Drizzle with oil and rub all over, then sprinkle with Rub. Use hands to rub herbs all over the chicken, getting right into all the cracks and crevices. Place on rack.","images":[],"step":8},{"title":"Thigh + drumsticks","description":"Arrange thigh pieces skin side up, and for drumsticks the side with the most skin up.","images":[],"step":9},{"title":"Butterflied/spatchcocked","description":"Arrange breast side up with tail end of chicken pointed back towards back of oven, neck end closest to door.","images":[],"step":10},{"title":"Thighs + drumsticks","description":"roast for 35 minutes or until internal temperature is 75°C/165°F, or juices run clear when pierced in the middle.","duration":35,"images":[],"step":11},{"title":"Butterflied/spatchcocked","description":"roast for 45 minutes, or until internal temperature is: 66°C / 151°F for the breast AND 75°C/165°F when inserted into the joint between the leg and the thigh.","duration":45,"images":[],"step":12},{"title":"Extra browning","description":"if skin isn''t browned/crispy enough, flick grill/broiler on high for 1 - 3 minutes. CAREFUL - browns super quick!","duration":2,"images":[],"step":13},{"description":"Tent VERY loosely with foil (to preserve crispy skin) for 5 minutes.","duration":5,"images":[],"step":14},{"description":"Scrape every bit of juice, fat and all the brown stuff off the tray into a saucepan.","images":[],"step":15},{"description":"Turn stove onto medium. Once juices are bubbling, add flour and whisk to combine.","images":[],"step":16},{"description":"Slowly pour in broth, whisking as you go.","images":[],"step":17},{"description":"Add soy sauce or gravy browner and pepper.","images":[],"step":18},{"title":"Continue stirring for 3 to 5 minutes","description":"as it becomes steamy, gravy will thicken.","duration":4,"images":[],"step":19},{"description":"Once it becomes a syrupy consistency (see video), remove from stove. Adjust salt to taste right at end, then pour into jug.","images":[],"step":20},{"description":"Carve up the chicken as you would a roast chicken. Cut breast into 3 or 4 pieces. Cut thighs in half along the bone.","images":[],"step":21},{"description":"Pile it all up onto a plate, garnish with parsley or other fresh herbs. Serve with gravy!","images":[],"step":22}]', '["gluten","milk","peanuts","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-drumstick-recipes","chicken-recipes","roasts","sunday-supper"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d2a4fa114cd7', 'en', 'US', 'Chicken Brine', 'Recipe video above. BRINING is the secret to the most succulent, tender roast chicken you will EVER have in your life! Adapted from a recipe by Thomas Keller, one of the great masters of the culinary world. The flesh is seasoned all the way through with a hint of the brine flavourings (herbs, lemon, garlic).', 'https://www.recipetineats.com/tachyon/2014/05/Chicken-Brine_3.jpg', 15, 60, 1515, 5, '[{"id": "ing_water", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 4.0, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 0.4, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.28, "unit": "bunch"}}, {"id": "ing_rosemary", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 5.0, "unit": "unit"}}, {"id": "ing_honey", "quantity": {"value": 0.125, "unit": "jar of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 2.0, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.3, "unit": "jar of 50g"}}, {"id": "ing_chicken", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.3, "unit": "jar of 50g"}}]', '[{"ingredients":["2 litres / 2 quarts water (, cold tap water)","1/3 cup kosher or cooking salt, NOT table salt (Note 1)","2 lemons (, quartered)","10 sprigs parsley (, fresh )","7 sprigs thyme","2 sprigs rosemary","5 bay leaves, fresh (or 3 dried)","1/4 cup honey","6 garlic cloves, (smashed (Note 3))","1 tbsp black peppercorns"],"purpose":"Brine"},{"ingredients":["1.5 - 2 kg / 3-4lb chicken (, whole)","3 tbsp / 40g butter (, melted)","Salt and pepper to season"],"purpose":"Roast Chicken"}]', '[{"description":"Pour about 1/3 of the water into a large pot (large enough for the brine and submerged chicken) with remaining Brine ingredients. Bring to boil boil 1 minute, stir to dissolve salt.","images":[],"step":1},{"description":"Remove from heat, pour in remaining water. Cool completely before using (I cool about 30 min then refrigerate 1 1/2 hours). DO NOT put chicken in before full cool, this is a health hazard (Note 4).","images":[],"step":2},{"description":"Flip chicken upside down (so legs and breast are on underside. Submerge chicken in brine, cover and refrigerate for 12 - 24 hours (Note 5). Don''t worry if underside of chicken doesn''t stay under water - the the breast side is, that is what matters.","images":[],"step":3},{"description":"Roasting Brined Chicken:","images":[],"step":4},{"description":"Remove chicken from brine and pat dry to remove excess moisture.","images":[],"step":5},{"description":"Tie legs with string (if desired), tuck wings under. Drizzle/brush with most of the butter all over, including underside (butter will firm up on contact).","images":[],"step":6},{"description":"Sprinkle with pepper and the TINIEST pinch of salt, place chicken on a rack in a heavy based roasting tray. Set aside for 20 minutes.","duration":20,"images":[],"step":7},{"description":"Preheat fan forced oven to 220°C/430°F.","images":[],"step":8},{"description":"Turn down the oven to 180°C/350°F, then roast chicken for 50 minutes to 1 hour (Note 7) or until the internal temperature at the joint between the leg and thigh is 75°C/165°F, or until juices run clear.","duration":50,"images":[],"step":9},{"description":"Check at 45 minutes, rotate the pan if not browning evenly, and brush top with remaining melted butter.","images":[],"step":10},{"description":"Remove chicken from the roasting tray, cover loosely with foil and rest for 10 to 15 minutes.","duration":12.5,"images":[],"step":11},{"description":"Chicken is so juicy, it needs little more than a tiny drizzle of the juices in the pan (go easy, it''s salty). Otherwise, make a gravy while the chicken is resting - see Note 8.","images":[],"step":12}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","good-to-know","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_88d0e49e9d93', 'en', 'US', 'Sicilian Chicken Spaghetti', 'Recipe video above. A quick tomato chicken spaghetti with olives, artichokes and a kick of spice if you so choose! Very little prep - nothing to chop except garlic!', 'https://www.recipetineats.com/tachyon/2019/09/Sicilian-Chicken-Pasta_9.jpg', 5, 15, 20, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.64, "unit": "pack of 500g"}}, {"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_black_olives", "quantity": {"value": 150.0, "unit": "bottle"}}, {"id": "ing_artichokes_drained", "quantity": {"value": 0.17, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.009, "unit": "jar of 50g"}}, {"id": "ing_basil", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["320g / 11oz spaghetti (or other long pasta)","2 chicken breasts (, each halved horizontally to form 2 thin steaks)","2 tbsp olive oil","Salt and pepper","3 garlic cloves (, minced)","1/2 cup (125 ml) white wine (Note 1)","800g / 28oz can crushed tomato","1/2 cup (125 ml) water (about 1/3 empty tomato can)","1 cup (100g) sliced black olives (Note 2)","170g / 6 oz artichokes (marinated in can or jar), drained (Note 2)","1/2 - 1 tsp red pepper flakes (spiciness - adjust to taste!)","1/2 tsp salt and pepper (, each)","1 cup basil leaves (, optional (or sub baby spinach))"]},{"ingredients":["Parmesan cheese (, freshly grated)"],"purpose":"Serving"}]', '[{"description":"Cook pasta in a large pot of salted boiling water per packet directions, MINUS 1 minute. Drain. (Do this while sauce is simmering)","images":[],"step":1},{"title":"Cook chicken","description":"Sprinkle both sides of chicken with salt and pepper. Heat 1 tbsp oil in a large skillet over high heat. Sear chicken 1 1/2 minutes on each side until golden, then remove from skillet. Shred while sauce is simmering.","images":[],"step":2},{"description":"Add remaining 1 tbsp oil. Add garlic and sauté for 15 seconds.","duration":0.25,"images":[],"step":3},{"description":"Add wine and let it simmer rapidly for 1 minute, stirring to dissolve brown bits on bottom of skillet into the wine, until mostly evaporated.","duration":1,"images":[],"step":4},{"description":"Add tomato, water, olives, artichoke, red pepper flakes, salt and pepper. Stir, simmer on medium for 5 minutes.","duration":5,"images":[],"step":5},{"description":"Stir shredded chicken into sauce.","images":[],"step":6},{"description":"Add pasta into sauce, still on the stove. Toss well for 1 minute or until sauce reduces more and is clinging to pasta strands, rather than pooled in the skillet.","duration":1,"images":[],"step":7},{"description":"Just before serving, toss through fresh basil.","images":[],"step":8},{"description":"Serve immediately with parmesan!","images":[],"step":9}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["American-Italian","Italian"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","italian-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c91eff732ca4', 'en', 'US', 'White Chicken Lasagna', 'Recipe video above. Tender shredded chicken and golden, garlicky mushrooms smothered in a cheesy Alfredo sauce, layered up with lasagna sheets. It''s a WHITE chicken lasagna - and it''s amazing!', 'https://www.recipetineats.com/tachyon/2019/08/White-Chicken-Lasagna_2.jpg', 15, 75, 90, 8, '[{"id": "ing_chicken_breast", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 0.12, "unit": "bunch"}}, {"id": "ing_vegeta", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_mushroom", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_sheets_lasagna", "quantity": {"value": 375.0, "unit": "pack"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.6, "unit": "pack of 125g"}}]', '[{"ingredients":["1 kg/ 2lb chicken breast ( or boneless skinless thigh)","4 cups (1L) milk (, any fat %)","2 cups (500ml) chicken broth (/ stock)","2 bay leaves (, dried)","3 sprigs thyme (or 1 tsp dried thyme)","2 tsp Vegeta (or chicken stock powder/granulated bouillon, Note 1)","1/2 tsp black pepper"],"purpose":"Chicken & semi-homemade stock:"},{"ingredients":["2 tbsp (30g) butter (, separated)","2 tbsp olive oil (, separated)","500g / 1lb mushrooms (, quartered)","2 garlic cloves (, minced)","1/2 tsp salt and pepper (, each)"],"purpose":"Mushrooms:"},{"ingredients":["50g / 4tbsp butter","2 garlic cloves (, minced)","3/4 cup (110g) flour (, plain / all purpose)","2 cups (200g) cheddar cheese (, shredded (Note 2))"],"purpose":"White sauce:"},{"ingredients":["375g (13 oz) lasagna sheets (, fresh (or 250g/8oz dried) (Note 3))","2 cups (200g) mozzarella cheese (, shredded)"],"purpose":"Lasagna:"}]', '[{"description":"Place milk, broth and stock powder in a large saucepan. Bring to a very gentle simmer over medium heat, add chicken, pepper, bay leaves and thyme.","images":[],"step":1},{"description":"Place lid on, simmer gently on medium low for 15 minutes (do not boil, can make milk split).","duration":15,"images":[],"step":2},{"description":"Remove chicken and shred. Cover pot and set poaching liquid aside.","images":[],"step":3},{"description":"Heat half the oil and butter in a very large, deep skillet over high heat (or use large pot). Add half the mushrooms with half the garlic, salt and pepper.","images":[],"step":4},{"description":"Cook for 5 minutes, stirring leisurely, until golden. Transfer to bowl and repeat with remaining mushrooms.","duration":5,"images":[],"step":5},{"description":"Lower heat down to medium.","images":[],"step":6},{"description":"Melt butter in skillet, then add garlic. Stir until golden.","images":[],"step":7},{"description":"Add flour. Stir constantly for 1 minute.","duration":1,"images":[],"step":8},{"description":"Gradually pour in 2 cups of reserved poaching liquid while stirring constantly, it should turn into a thick paste.","images":[],"step":9},{"description":"Mix in another cup of liquid, then add remaining liquid and stir well to dissolve. Use whisk if necessary to make lump free.","images":[],"step":10},{"description":"Stir constantly for 1 to 2 minutes until it thickens - you should be able to draw a path across a spoon (see video).","duration":1.5,"images":[],"step":11},{"description":"Remove from heat, stir in cheese until melted. Taste and add more salt & peppers, if needed.","images":[],"step":12},{"description":"REMOVE 2 1/2 cups (625ml) of sauce (save for topping). Then stir in chicken and mushrooms into remaining sauce.","images":[],"step":13},{"description":"Assemble & Bake:","images":[],"step":14},{"description":"Preheat oven to 180°C/350°F.","images":[],"step":15},{"description":"Smear some sauce on the base of a 23 x 33 cm / 9 x 13\" baking dish. Cover base with lasagna sheets.","images":[],"step":16},{"description":"Top with half chicken mixture, then lasagna sheets, remaining chicken mixture then more lasagna sheets.","images":[],"step":17},{"description":"Pour over reserved White Sauce, sprinkle with mozzarella. Cover loosely with foil or use upside down baking tray (ensure it''s not touching cheese).","images":[],"step":18},{"description":"Bake for 25 minutes. Remove foil, bake further 10 minutes until golden and bubbly.","duration":25,"images":[],"step":19},{"description":"Stand 10 minutes, garnish with parsley if desired then cut to serve!","images":[],"step":20}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","iconic-dishes","main-dishes","pasta-bakes","pasta-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0298973ad088', 'en', 'US', 'Chicken with Creamy Sun Dried Tomato Sauce', 'Recipe video above. Dinner on the table in 20 minutes! The sauce is ridiculously addictive - I''m tempted to double it!', 'https://www.recipetineats.com/tachyon/2015/07/Chicken-with-Creamy-Sun-Dried-Tomato-Sauce_2.jpg', 10, 10, 20, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_tomato", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_chicken", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_basil", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["750g / 1.5lb chicken thighs OR chicken breast (, skinless and boneless)","1/2 tsp salt","Black pepper","1/2 cup sun dried tomatoes (, strips, drained of oil (Note 1))","2 tbsp oil from sun dried tomatoes jar (Note 1)","2 garlic cloves (, minced)","1/2 cup (125 ml) white wine (sub chicken broth)","3/4 cup (185 ml) chicken broth/stock (, low sodium)","3/4 cup (185 ml) thickened / heavy cream","1/3 cup (30g) parmesan, very finely shredded (Note 2)","2 tsp Dijon mustard (Note 3)","1 cup basil leaves (, packed (optional))"]}]', '[{"title":"Breast","description":"Cut chicken in half horiztonally to form 2 thin steaks.","images":[],"step":1},{"description":"Sprinkle chicken with salt and pepper. Heat oil from sun dried tomat jar in a large skillet over high heat.","images":[],"step":2},{"description":"Add the chicken and cook until golden brown on both sides - 6 minutes total for thigh or 4 minutes for breast. Remove onto a plate, keep warm.","images":[],"step":3},{"description":"Add the garlic and cook for 15 seconds until light golden.","duration":0.25,"images":[],"step":4},{"description":"Add wine. Bring to simmer and scrape the bottom of the skillet to mix all the brown bits into the wine.","images":[],"step":5},{"description":"Let the wine simmer for 1 minute or so until the smell of alcohol is gone which means it has evaporated.","duration":1,"images":[],"step":6},{"description":"Mix in mustard, then add the chicken broth, cream, parmesan and sun dried tomatoes.","images":[],"step":7},{"description":"Bring to simmer, then reduce heat to medium and simmer for 2 to 3 minutes until thickened. Stir regularly to dissolve parmesan cheese.","duration":2.5,"images":[],"step":8},{"description":"Taste sauce and add more salt and pepper if needed.","images":[],"step":9},{"description":"Stir through basil leaves, then return chicken into pan. Spoon sauce over and simmer 1 minute.","images":[],"step":10},{"description":"Serve immediately! Great served over mashed potato, Creamy Mashed Cauliflower or pasta. Or serve with bread on the side to mop up sauce!","images":[],"step":11}]', '["milk","mustard"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1383e8914ce8', 'en', 'US', 'Chicken Nachos', 'Recipe video above. Crispy chips loaded with juicy Mexican shredded chicken, plenty of melted cheese and toppings of choice. Your new favourite way with nachos! This chicken is a terrific all-purpose Mexican chicken, especially great in Tacos.', 'https://www.recipetineats.com/tachyon/2019/06/Chicken-Nachos_3.jpg', 15, 10, 25, 4, '[{"id": "ing_tortillas", "quantity": {"value": 31.25, "unit": "pack of 8"}}, {"id": "ing_chicken", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 250.0, "unit": "block of 250g"}}, {"id": "ing_quick_guacamole", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 0.09, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_avocado", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 3.0, "unit": "bunch"}}]', '[{"ingredients":["250g / 8 oz tortilla or plain corn chips (Note 1)","Shredded chicken for nachos (, recipe follows)","250g / 8 oz (2.5 cups) shredded cheddar or Monterey Jack cheese (Note 2)","Quick guacamole (, recipe follows)","Toppings: Sour cream, Coriander / cilantro leaves, Jalapeno (, sliced or chopped)"],"purpose":"Nachos"},{"ingredients":["700 g / 1.2 lb chicken thighs or breast (, skinless boneless (Note 3))","1.5 tbsp olive oil","2 tbsp tomato paste","2 tsp sugar","1 cup (250ml) chicken broth, separated (liquid stock)"],"purpose":"Chicken for Nachos"},{"ingredients":["3 tbsp lime juice (Note 4)","1 tbsp olive oil","2 garlic cloves (, minced)","2 tsp EACH garlic powder, onion powder, dried oregano","3 tsp EACH cumin powder, paprika","1/2 tsp cayenne pepper (optional)","1/2 tsp salt and pepper (, each)"],"purpose":"Homemade Nachos Meat Seasoning"},{"ingredients":["2 avocados (, medium)","3 tbsp coriander/cilantro (, roughly chopped)","2 tbsp lime juice (1 large)"],"purpose":"Quick Guacamole"}]', '[{"description":"Chicken for Nachos","images":[],"step":1},{"description":"Place Nachos Seasoning ingredients in a bowl. Add 2 tbsp of the chicken broth and mix to form a loose paste.","images":[],"step":2},{"description":"Add chicken, turn to coat in paste.","images":[],"step":3},{"description":"Heat oil in a large skillet over medium high heat. Cook chicken for 3 minutes on each side (reserve paste left in bowl). Remove chicken into a shallow dish.","duration":3,"images":[],"step":4},{"description":"Return skillet to stove. Add remaining chicken broth, tomato paste, sugar and scrape in any paste left in the bowl. Mix to dissolve, scraping base of pan, and bring to simmer.","images":[],"step":5},{"description":"Meanwhile, shred chicken with forks, or chop (don''t worry if raw inside).","images":[],"step":6},{"description":"Return chicken into sauce, toss and simmer for 3 minutes until sauce reduces down to a thick sauce. Adjust salt to taste. Keep warm.","duration":3,"images":[],"step":7},{"description":"Quick Guacamole:","images":[],"step":8},{"description":"Place ingredients in a bowl. Use potato masher to mash to desired consistency. Adjust salt and pepper to taste.","images":[],"step":9},{"description":"Preheat oven to 180C/350F.","images":[],"step":10},{"description":"Place half the corn chips slightly overlapping on a tray. Top with half the (warm) chicken and cheese.","images":[],"step":11},{"description":"Top with remaining chips and cheese. Bake 7 minutes or until cheese is melted and bubbly.","images":[],"step":12},{"description":"Garnish with coriander/cilantro and jalapeño. Serve immaterial with quick Guacamole and sour cream.","images":[],"step":13}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Mexican","Tex-Mex"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","mexican-recipes","nachos-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2810a48f904f', 'en', 'US', 'Jambalaya Recipe (easy)', 'Recipe VIDEO above. Many people consider this to be the world''s best one pot rice meal.... you won''t hear any arguments from me!! Filled with big, punchy New Orleans flavours, a homemade Creole/Cajun spice delivers top notch flavour with consistency results for everyone, no matter where you live in this big wide world. This Jambalaya is started on the stove then finished in the oven - exactly the same outcome as cooking the whole thing on the stove (the traditional way), but far less risk of uneven cooked rice and mushy gluey rice from over stirring. And it''s just easier - entirely hands off time! :)', 'https://www.recipetineats.com/tachyon/2019/06/Jambalaya_0.jpg', 20, 50, 70, 5, '[{"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_bacon", "quantity": {"value": 0.9, "unit": "pack of 200g"}}, {"id": "ing_sausages", "quantity": {"value": 0.4, "unit": "pack of 500g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_shrimp", "quantity": {"value": 12.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 150.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_steak", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.002, "unit": "kg"}}, {"id": "ing_rice", "quantity": {"value": 187.5, "unit": "pack"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_paprika", "quantity": {"value": 0.5, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cayenne", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}]', '[{"ingredients":["1 tbsp vegetable oil","180g (6oz) bacon (, preferably SMOKED, chopped)","200g (7oz) andouille or smoked sausage (, sliced 0.5cm / 1/5\" thick (Note 1))","300g (10oz) chicken thigh (, skinless boneless, cut into 2.5cm /1\" pieces)","12 prawns/shrimp (, raw, large, (peeled, with or without tails))","4 garlic cloves (, minced)","1 tbsp (15g) butter","1 onion (, large, cut into 1.5 cm / 0.5\" pieces)","2 celery ribs (, cut into 1.5 cm / 0.5\" pieces)","2 green capsicum / bell pepper (, medium, cut into 1.5 cm / 0.5\" pieces)","1.25 cups long grain rice (, uncooked (Note 2))","2.5 cups (625ml) low-sodium chicken broth / stock (Note 3)","200g (6.5oz) crushed canned tomato","2 tbsp tomato paste","1 cup green onions (, sliced, plus more for serving)"]},{"ingredients":["2 tsp chopped fresh thyme (or 1 tsp dried thyme)","4 tsp sweet paprika","1 tsp garlic powder","1 tsp onion powder","1/2 tsp cayenne powder (adjust spice to taste)","1/2 tsp black pepper","1/2 tsp salt"],"purpose":"Creole Seasoning Mix:"}]', '[{"description":"Preheat oven to 180C/350F (all types).","images":[],"step":1},{"description":"Heat oil in a very large skillet or dutch oven over medium high heat. (Note 4)","images":[],"step":2},{"description":"Add bacon, cook for 30 seconds (to start fat melting), then add sausages. Cook until sausages are golden - about 3 minutes - then remove into bowl.","duration":0.5,"images":[],"step":3},{"description":"Add chicken into the pan and cook until golden (doesn''t need to cook inside), then add to bowl with bacon.","images":[],"step":4},{"description":"Sear prawns in the pan for 1.5 minutes on each side, then transfer to a separate bowl (reserve until later).","images":[],"step":5},{"description":"Add butter, then garlic, onion, celery and capsicum. Cook for 3 to 4 minutes or until slightly softened.","duration":3.5,"images":[],"step":6},{"description":"Add rice, stir to coat grains in oil.","images":[],"step":7},{"description":"Add chicken broth, tomato paste, canned tomato, thyme and Seasoning Mix.","images":[],"step":8},{"description":"Stir well, then add chicken, sausages and bacon (including all liquid).","images":[],"step":9},{"description":"When you see bubbles across most of the surface, stir well once more. Ensure all rice is submerged, cover with lid, and transfer to oven. (See video)","images":[],"step":10},{"description":"Bake 20 minutes. Remove lid and check rice by eating a few grains (careful, very hot!) If the rice is just about done (Note 5 for the correct consistency), go to next step. If rice grains are still firm in the centre, continue to cook, checking rice every 5 mins - most ovens take about 30 mins total cooking (see Note 7).","images":[],"step":11},{"description":"Add prawns/shrimp and green onions, QUICKLY (but gently!) stir through, cover with lid, and return to oven for just 3 minutes (just to heat prawns).","images":[],"step":12},{"description":"Remove from oven (see video for finished consistency), stir gently to fluff, then serve, garnished with more green onions if desired.","images":[],"step":13}]', '["milk","shellfish"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Cajun","Louisiana","New Orleans"],"categories":["chicken-recipes","iconic-dishes","one-pot-recipes","rice-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9dbb9e5c6ab2', 'en', 'US', 'Chicken Pasta recipe of your dreams!', 'Recipe VIDEO above. The creamy chicken pasta recipe of your dreams! A creamy chicken Alfredo with sun dried tomato, spinach and bacon, you''ll love how the shredded chicken acts like a mop for the luxurious Alfredo sauce!', 'https://www.recipetineats.com/tachyon/2019/05/Chicken-Alfredo_8.jpg', 5, 15, 20, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.6, "unit": "pack of 500g"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.25, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 0.375, "unit": "pack of 200g"}}, {"id": "ing_baby_spinach", "quantity": {"value": 70.0, "unit": "bag of 250g"}}, {"id": "ing_tomato", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 0.6, "unit": "pack of 200g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.375, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["300g / 10 oz fettuccine (Note 1)","30g / 2 tbsp butter (, separated)","2 chicken breasts (, cut in half horizontally)","1/2 tsp each salt and pepper","2 garlic cloves (, minced)","1/2 cup (125ml) dry white wine (sub more chicken broth)","1/2 cup (125ml) chicken stock / broth (, low sodium)","1 1/4 cups (315ml) cream (, thickened / heavy (Note 2))","3/4 cup (75g) parmesan (, finely shredded (Note 3))","70g / 2.5oz baby spinach","100 g / 3oz sun dried tomato strips (Note 4)"]},{"ingredients":["120g / 4oz bacon (, cooked and crumbled)","More parmesan","Parsley (, for garnish (optional))"],"purpose":"Serving:"}]', '[{"description":"Cook pasta in a large pot of salted boiling water for time per packet minus 1 1/2 minutes.","images":[],"step":1},{"description":"Just before draining, scoop out a mugful of pasta cooking water. Then drain pasta.","images":[],"step":2},{"description":"Sprinkle both sides of chicken with salt and pepper.","images":[],"step":3},{"description":"Melt half the butter in a large skillet over hig heat.","images":[],"step":4},{"description":"Add chicken and cook for 2 minutes on each side until deep golden.","duration":2,"images":[],"step":5},{"description":"Remove chicken onto plate, rest for a few minutes then shred with 2 forks.","images":[],"step":6},{"description":"Turn down heat to medium high. In the same skillet, add remaining butter and garlic.","images":[],"step":7},{"description":"Cook garlic for 30 seconds until golden, then add wine.","duration":0.5,"images":[],"step":8},{"description":"Simmer rapidly, stirring to scrape the brown bits off the bottom of the pan. Once mostly evaporated, add chicken broth, cream, parmesan and sun dried tomato.","images":[],"step":9},{"title":"Simmer on medium for 3","description":"5 minutes, stirring leisurely, until it reduces and thickens.","duration":4,"images":[],"step":10},{"description":"Essential Tossing:","images":[],"step":11},{"description":"Add spinach, chicken and cooked pasta.","images":[],"step":12},{"title":"Toss for 1 1/2","description":"2 minutes on the stove, until sauce thickens and coats the pasta strands (see VIDEO). Use pasta cooking water if needed if it gets too thick.","images":[],"step":13},{"description":"Serve immediately with parmesan, crumbled bacon and parsley (if desired).","images":[],"step":14}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f1365b686cc7', 'en', 'US', 'Quick Chicken Tacos - WITH sauce!', 'Recipe video above. A 2-in-1 chicken taco filling: shredded chicken AND sauce made in the same pan using the same seasoning mix! Because it''s so juicy and packed with tons of flavour, the toppings can be kept simple and there''s not need to make an extra sauce. No marinating required.', 'https://www.recipetineats.com/tachyon/2019/03/Chicken-Tacos_3.jpg', 15, 10, 25, 12, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 0.09, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_tortillas", "quantity": {"value": 1.0, "unit": "pack of 8"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}]', '[{"ingredients":["700 g / 1.2 lb chicken thighs (, skinless boneless (or breast))","1.5 tbsp olive oil","2 tbsp tomato paste","2 tsp sugar","1 cup (250ml) chicken broth, separated (liquid stock)"]},{"ingredients":["3 tbsp lime juice (Note 1)","1 tbsp olive oil","2 garlic cloves (, minced)","2 tsp EACH garlic powder, onion powder, dried oregano","3 tsp EACH cumin powder, paprika","1/2 tsp cayenne pepper (adjust spiciness to taste, can skip)","1 tsp salt","1/2 tsp black pepper"],"purpose":"HOMEMADE TACO SEASONING:"},{"ingredients":["Taco shells or tortillas (, warmed per packet directions)","Diced tomato (, onion, avocado, coriander/cilantro leaves)","Shredded lettuce","Shredded cheese","Sour cream"],"purpose":"To serve:"}]', '[{"description":"Place Taco Seasoning ingredients in a bowl. Add 2 tbsp of the chicken broth and mix to form a loose paste.","images":[],"step":1},{"description":"Add chicken, turn to coat.","images":[],"step":2},{"description":"Heat oil in a large skillet over medium high heat. Cook chicken for 3 minutes on each side until lightly seared. (Reserve marinade dregs in bowl)","duration":3,"images":[],"step":3},{"description":"Remove chicken into a shallow dish.","images":[],"step":4},{"description":"Return skillet to stove, reduce to medium. Add remaining chicken broth, tomato paste, sugar and scrape in any marinade left in the bowl. Mix to dissolve, scraping base of pan, and bring to simmer","images":[],"step":5},{"description":"Meanwhile, shred chicken with forks, or chop (don''t worry if raw inside).","images":[],"step":6},{"description":"Return chicken into sauce, toss and simmer for 2 to 3 minutes until sauce reduces to a thin syrup consistency (add water if reduces too fast). Adjust salt to taste.","duration":2.5,"images":[],"step":7},{"description":"Transfer chicken and all sauce to serving bowl.","images":[],"step":8},{"description":"Warm taco shells or tortillas.","images":[],"step":9},{"description":"Stuff with chicken, making sure it''s soaked with the sauce.","images":[],"step":10},{"description":"Top with tomato, avocado, onion, coriander, lettuce and sour cream. Devour!","images":[],"step":11}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican","Tex-Mex"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","dinner-tonight","mains","mexican-recipes","quick-and-easy","taco-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ae28d9c6e414', 'en', 'US', 'Easy Chicken Curry', 'Recipe video above. This is a Western style curry, and it''s the easiest chicken curry I know how to make with the least ingredients possible without sacrificing tastiness! Very mild, not spicy at all (assuming curry powder is mild).', 'https://www.recipetineats.com/tachyon/2019/03/Best-easy-Chicken-Curry_5.jpg', 8, 20, 28, 4, '[{"id": "ing_oil", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.75, "unit": "jar of 50g"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.675, "unit": "can of 400ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_frozen_peas", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}]', '[{"ingredients":["1.5 tbsp oil (vegetable, canola)","2 garlic cloves (, minced)","2 tsp ginger (, grated)","1/2 onion (, finely chopped)","500g / 1lb chicken thighs, sliced (Note 1)","2.5 tbsp curry powder (Note 2)","270 ml / 1.25 cups coconut milk (, full fat (9 oz) (Note 3))","1.5 cups (375 ml) chicken stock low sodium","1/2 tsp salt","3/4 cup frozen peas","1/4 cup coriander / cilantro leaves (, chopped)"]}]', '[{"description":"Heat oil in a skillet over medium high heat. Cook garlic, ginger and onion for 3 minutes until onion is translucent.","duration":3,"images":[],"step":1},{"description":"Add chicken and cook until it it changes from pink to white.","images":[],"step":2},{"description":"Add curry powder and cook for 2 minutes.","duration":2,"images":[],"step":3},{"description":"Add coconut milk and chicken stock. Stir, lower heat to medium and cook, simmering rapidly, for 10 minutes until sauce reduces and thickens.","duration":10,"images":[],"step":4},{"description":"Add peas and salt. Cook for a further 2 minutes, then taste to see if it needs more salt. Garnish with coriander.","images":[],"step":5},{"description":"Serve over rice, noodles or mashed potato!","images":[],"step":6}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken","chicken-recipes","curry-recipes","dietary","dinner-tonight","gluten-free-recipes","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_434fc8348836', 'en', 'US', 'Oven Baked Chicken Breast', 'Recipe VIDEO above. My tips for a truly juicy, Oven Baked Chicken Breast: a touch of brown sugar in the seasoning which makes the chicken sweat while it bakes so it creates a semi "sauce", and cooking fast on a high temp! Go by the colour of the crust to know when it''s cooked through.', 'https://www.recipetineats.com/tachyon/2018/05/Oven-Baked-Chicken-Breast_-with-Garlic-Butter-Kale-Rice.jpg', 5, 18, 23, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["4 chicken breasts (, 150 - 180g / 5 - 6 oz each (Note 1))","2 tsp olive oil"]},{"ingredients":["1 1/2 tbsp brown sugar","1 tsp paprika","1 tsp dried oregano or thyme (, or other herb of choice)","1/4 tsp garlic powder","1/2 tsp each salt and pepper"],"purpose":"Seasoning:"},{"ingredients":["Finely chopped parsley"],"purpose":"Garnish, optional:"}]', '[{"description":"Preheat oven to 425°F/220°C (200°C fan).","images":[],"step":1},{"description":"Pound chicken to 1.5cm / 0.6\" at the thickest part - using a rolling pin, meat mallet or even your fist (key tip for even cooking + tender chicken).","images":[],"step":2},{"description":"Mix Seasoning.","images":[],"step":3},{"description":"Line tray with foil and baking / parchment paper. Place chicken upside down on tray. Drizzle chicken with about 1 tsp oil. Rub over with fingers. Sprinkle with Seasoning.","images":[],"step":4},{"description":"Flip chicken. Drizzle with 1 tsp oil, rub with fingers, sprinkle with Seasoning, covering as much of the surface area as you can.","images":[],"step":5},{"description":"Bake 18 minutes, or until surface is golden per photos and video, or internal temperature is 165°F/75°C using a meat thermometer.","images":[],"step":6},{"description":"Remove from oven and immediately transfer chicken to serving plates.","images":[],"step":7},{"title":"Wait 3","description":"5 minutes before serving, garnished with freshly chopped parsley if desired. Pictured with a side of Garlic Butter Rice with Kale.","images":[],"step":8}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","emergency-recipes","gluten-free-recipes","low-calorie-recipes","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ee33234a0baa', 'en', 'US', 'Chicken Stew', 'Recipe video above. Slow cooked chicken with ultra tender flesh and outrageous crispy skin smothered in a gravy-like sauce that''s lip smackingly delicious. Carrots, celery, onion and potato make this a filling meal so you won''t need a side - except perhaps some crusty bread to dunk in the sauce! Make this in a large oven proof pot, or see notes if you don''t have one.', 'https://www.recipetineats.com/tachyon/2018/05/Chicken-Stew_5.jpg', 10, 90, 100, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_carrot", "quantity": {"value": 3000.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 4.0, "unit": "head"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_worscestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_thyme", "quantity": {"value": 0.12, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_potato", "quantity": {"value": 600.0, "unit": "bag of 2kg"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["1 tbsp olive oil","1.5 kg / 3lb bone in, skin on chicken thighs and drumsticks (6 to 8 pieces)","Salt and pepper","2 onions (, halved and cut into wedges)","2 garlic cloves (, minced)","3 large carrots (, cut thick end into 1.5cm / 3/5\" pieces, thin end 2.5cm/1\")","4 celery stalks (, cut into 2cm / 4/5\" chunks)","1/2 cup (125 ml) white wine (or water)","3 tbsp (35g) flour","3 cups (750 ml) chicken broth (, low low sodium)","2 tbsp tomato paste","2 tsp Worscestershire sauce","3 sprigs thyme (, or 1 tsp dried thyme (or other herb))","2 bay leaves (dried or fresh)","600 g / 1.2lb baby potatoes (, halved (quarter large ones))"]},{"ingredients":["Fresh thyme or parsley (chopped)","Warm crusty bread"],"purpose":"Serving (optional):"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Heat oil in a large pot over high heat. Brown chicken on both sides until light golden, sprinkling with salt and pepper. Remove from pot. (Do in 2 batches if pot not big enough).","images":[],"step":2},{"description":"If there''s too much oil in the pot, discard some. Add onion and garlic. Cook for 2 minutes until onion is translucent.","duration":2,"images":[],"step":3},{"description":"Add carrots and celery, cook for 1 minute.","duration":1,"images":[],"step":4},{"description":"Add wine. Stir, scraping the bottom of the pan to dissolve the brown bits into the liquid. Cook for 1 minute until liquid is mostly gone.","duration":1,"images":[],"step":5},{"description":"Sprinkle flour across surface, stir.","images":[],"step":6},{"description":"Add broth, tomato paste, Worcestershire sauce, thyme and bay leaves. Stir to dissolve tomato paste.","images":[],"step":7},{"description":"Place chicken on top, keeping the skin above the liquid level as much as you can.","images":[],"step":8},{"description":"Bring to simmer then cover. Bake for 45 minutes.","duration":45,"images":[],"step":9},{"description":"Remove from oven, remove lid. Add potatoes, pushing them into the liquid and rearranging chicken so they sit on top (for lovely crispy skin).","images":[],"step":10},{"description":"Return to oven without the lid for a further 40 minutes until the chicken skin is deep golden and super crispy, the potatoes are soft and the sauce is thickened.","images":[],"step":11},{"description":"Taste sauce and adjust salt and pepper to taste.","images":[],"step":12},{"description":"Serve with warm crusty bread on the side to dunk in the sauce - or go all the way with Garlic Bread! Optional: garnish with extra fresh thyme leaves or parsley.","images":[],"step":13}]', '["gluten"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","quick-and-easy","stews","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cb93471958e8', 'en', 'US', 'Honey Mustard Baked Chicken Drumsticks', 'Recipe video above. A terrifically easy baked chicken drumsticks with a magical 4 ingredient Honey Mustard sauce. Plus, option to add crispy smashed potatoes for an effortless dinner on one tray!', 'https://www.recipetineats.com/tachyon/2018/04/Honey-Mustard-Baked-Chicken-Drumsticks-with-Crispy-Smashed-Potatoes_0.jpg', 11, 60, 71, 4, '[{"id": "ing_potato", "quantity": {"value": 4.0, "unit": "bag of 2kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 8.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.15, "unit": "jar of 200g"}}, {"id": "ing_mustard", "quantity": {"value": 0.15, "unit": "jar of 200g"}}, {"id": "ing_honey", "quantity": {"value": 0.125, "unit": "jar of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.013, "unit": "pack of 400g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_broccoli", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["4 x 150g/5oz potatoes (Note 1)","2 tbsp / 30 g olive oil or melted butter"],"purpose":"Smashed Potatoes (optional):"},{"ingredients":["8 chicken legs (about 1 kg / 2 lb) (Note 2)","2 tsp olive oil"],"purpose":"Chicken:"},{"ingredients":["2 tbsp Dijon mustard (Note 3)","1 tbsp wholegrain mustard (or use more Dijon)","1/4 cup honey","1 garlic clove (, minced)","1 tsp cornflour/cornstarch (Note 4)","Pinch of salt and pepper"],"purpose":"Sauce:"},{"ingredients":["Fresh thyme leaves or chopped parsley","Steamed broccolini"],"purpose":"For serving (optional):"}]', '[{"description":"Smashed Potatoes option:","images":[],"step":1},{"description":"Microwave potatoes for 10 minutes on high or until cooked. (Note 5)","duration":10,"images":[],"step":2},{"description":"Place on one side of tray. Squish using potato masher (Note 6) to about 1.7cm / 2/3\" thickness. Drizzle with oil, sprinkle with salt and pepper.","images":[],"step":3},{"description":"If making smashed potatoes, fold up the edges of the foil the drumsticks are on","images":[],"step":4},{"description":"Sticky Baked Drumsticks:","images":[],"step":5},{"description":"Preheat oven to 180C/350F.","images":[],"step":6},{"description":"Mix Sauce ingredients together with a good pinch of salt and pepper.","images":[],"step":7},{"description":"Line tray with foil, then top with parchment paper.","images":[],"step":8},{"description":"Place drumsticks on paper. If making smashed potatoes, fold up the edges of the foil so the sauce won''t leak into the potatoes (doesn''t need to be high - even 1cm / 2/5\" is enough, video useful).","images":[],"step":9},{"description":"Spoon Sauce over drumsticks. Drizzle chicken with olive oil.","images":[],"step":10},{"description":"Bake for 30 minutes. Turn drumsticks (not potatoes), spoon juices over drumsticks.","duration":30,"images":[],"step":11},{"description":"Bake for a further 20 minutes, turn, spoon over juices. Bake for 10 - 15 minutes until sauce reduces and the drumsticks are golden and sticky.","duration":12.5,"images":[],"step":12},{"description":"Remove from oven. Squidge the drumsticks around in what should now be a syrupy sauce. (Note 7) Serve drumsticks with sauce, with crispy smashed potatoes and steamed broccolini on the side. Sprinkle with fresh thyme leaves if using.","images":[],"step":13}]', '["milk","mustard"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-drumstick-recipes","chicken-recipes","dinner-tonight","main-dishes","one-pot-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_dc19ad410cb3', 'en', 'US', 'Sticky Baked Chicken Thighs', 'Recipe video above. This is what you make if you''ve got boneless skinless chicken thighs and haven''t planned anything for dinner. You''ve probably got everything required for the glaze - and if you don''t, there''s plenty of sub options. Savoury and sweet, the sauce is great drizzled over everything!', 'https://www.recipetineats.com/tachyon/2019/02/Sticky-Baked-Chicken-Thighs_5.jpg', 5, 25, 30, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_ketchup", "quantity": {"value": 0.075, "unit": "bottle of 500g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}]', '[{"ingredients":["700g / 1.4lb chicken thighs (, skinless boneless (5-7 pieces), Note 1)"]},{"ingredients":["1/4 cup ketchup","3 tbsp brown sugar (, lightly packed)","1.5 tbsp soy sauce (, all purpose or light (NOT dark))","1 tbsp apple cider vinegar","1 tbsp olive oil","2 tsp Worcestershire Sauce","2 clove garlics (, minced)"],"purpose":"Glaze (Note 2 for subs):"}]', '[{"description":"Preheat oven to 220°C/420°F (200°C fan).","images":[],"step":1},{"title":"Pan","description":"Use a pan large enough to fit the thighs lying flat (not bunched up/folded). Line pan with foil (you''ll thank me later), place thighs in pan.","images":[],"step":2},{"title":"Glaze 1","description":"Mix Glaze ingredients together. Spoon over about 2/3 of the Glaze on the surface of each (not underside), reserve rest.","images":[],"step":3},{"description":"Bake 15 minutes, remove pan.","images":[],"step":4},{"description":"Flick to grill/broiler on high, adjust shelf to be 20cm/8\" from heat source.","images":[],"step":5},{"title":"Glaze 2","description":"Spoon pan juices over chicken. Then spoon/dab remaining Glaze onto chicken.","images":[],"step":6},{"description":"Broil chicken for 8 to 10 minutes until surface is nicely caramelised.","duration":9,"images":[],"step":7},{"title":"Rest","description":"Remove and stand for a few minutes (uncovered) before serving with pan juices.","images":[],"step":8}]', '["gluten","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-recipes","dinner-tonight","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_fe3ff2c848fd', 'en', 'US', 'Easy Chicken Cordon Bleu', 'Recipe video above. My midweek version of Chicken Cordon Bleu. All the flavour, all the crunch, much faster to make, and it''s better for you because it''s baked! Choose your method for crumbing the chicken - Super Easy or Quick Dredge (see photos for difference). Super Easy coats the top and sides of the chicken, but is faster than the Dredging Method. Served with a gorgeous traditional Dijon Cream Sauce!', 'https://www.recipetineats.com/tachyon/2015/10/Easy-Chicken-Cordon-Bleu-2.jpg', 15, 30, 45, 2, '[{"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_cheese", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_ham", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.113, "unit": "jar of 400g"}}, {"id": "ing_mustard", "quantity": {"value": 0.113, "unit": "jar of 200g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_flour", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 0.225, "unit": "pack of 200g"}}]', '[{"ingredients":["Panko breadcrumbs - 1/2 cup for Super Easy or 1 cup for Quick Dredge","Oil spray"],"purpose":"Breadcrumbs"},{"ingredients":["2 small chicken breasts, (around 6-7oz/180-210g each)","Salt and pepper","4 slices swiss cheese (Note 1)","4 to 6 slices of ham, (about 2.5oz/75g (Note 2))"],"purpose":"Chicken"},{"ingredients":["3 tbsp mayonnaise","1 1/2 tbsp Dijon mustard"],"purpose":"Method 1: Super Easy"},{"ingredients":["1 egg","2 tsp plain flour"],"purpose":"Method 2: Quick Dredge"},{"ingredients":["1 1/2 tbsp butter","1 1/2 tbsp flour","1 1/4 cups milk (Note 3)","2 tbsp Dijon mustard","3 tbsp parmesan cheese, finely grated"],"purpose":"Dijon Cream Sauce (makes 1 cup)"}]', '[{"description":"Preheat oven to 200C/390F (standard) or 180C/350F (fan).","images":[],"step":1},{"description":"Spread panko breadcrumbs on a baking tray and spray with oil. Bake for 3 minutes or until light golden. Remove and scrape into bowl straight away.","duration":3,"images":[],"step":2},{"description":"Cut a pocket into each chicken breast, as per the photo below.","images":[],"step":3},{"description":"Fold the cheese in half and place 2 pieces inside each pocket. Do the same with the ham. Close the pocket, seal with 2 toothpicks. Sprinkle with salt and pepper.","images":[],"step":4},{"description":"Super Easy Method","images":[],"step":5},{"description":"Mix the mayonnaise, mustard, salt and pepper in a bowl. Spread onto the top and sides of the chicken (not underside).","images":[],"step":6},{"description":"Sprinkle panko over the chicken, using your other hand to press the breadcrumbs onto the side of the chicken. Spray with oil.","images":[],"step":7},{"description":"Quick Dredge Method","images":[],"step":8},{"description":"Whisk egg and flour. Dip chicken into egg mixture, then into the panko breadcrumbs. Transfer to tray, spray with oil.","images":[],"step":9},{"description":"Bake for 25 to 30 minutes, or until golden brown and just cooked through. Remove toothpicks, serve with the Dijon Cream Sauce.","duration":27.5,"images":[],"step":10},{"description":"Dijon Cream Sauce","images":[],"step":11},{"description":"Melt butter over medium heat in a small saucepan. Add flour and cook for 1 minute.","duration":1,"images":[],"step":12},{"description":"Add half the milk and whisk until the flour mixture is blended in.","images":[],"step":13},{"description":"Add remaining milk, mustard and cheese. Cook for 3 minutes, whisking constantly, until thickened. It will thicken as it cools.","duration":3,"images":[],"step":14},{"description":"Remove from heat, add salt and pepper to taste. Serve with chicken.","images":[],"step":15}]', '["egg","gluten","milk","mustard"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["French(ish)"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","mains","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bc3d0c16ae60', 'en', 'US', 'Roast Chicken', 'RECIPE VIDEO ABOVE. Slathered with a garlic-herb-lemon butter, this roast chicken is juicy on the inside with crispy golden skin on the outside. An all round flavour bomb with the most incredible liquid gold pan juices to use as the sauce! See notes for gravy option and cook times for other chicken sizes.', 'https://www.recipetineats.com/tachyon/2016/05/Roast-Chicken_6a.jpg', 15, 90, 105, 5, '[{"id": "ing_chicken", "quantity": {"value": 1.75, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_rosemary", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_sage", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_rosemary", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_wine", "quantity": {"value": 0.333, "unit": "bottle of 750ml"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}]', '[{"ingredients":["1.75 - 2 kg / 3.5 - 4lb whole chicken (, patted dry)","Salt and pepper","2 tsp olive oil","1 lemon, quartered","3 rosemary sprigs"]},{"ingredients":["100 g / 1 stick unsalted butter (, melted)","3 garlic cloves (, minced)","1 tbsp sage (, finely chopped (Note 1))","2 tsp rosemary (, finely chopped (Note 1))","1 tbsp parsley (, finely chopped (Note 1))","1/2 tsp each salt and black pepper"],"purpose":"Butter:"},{"ingredients":["1 cup / 250 ml dry white wine (, or low sodium chicken broth)","1 onion (, quartered (Note 2))","1 garlic bulb (, halved horizontally (Note 2))"],"purpose":"Under Chook:"}]', '[{"description":"Take the chicken out of the fridge 30 minutes before cooking.","images":[],"step":1},{"description":"Preheat oven to 220C/450F (standard) or 200C/430F (fan/convection). Put shelf in the middle.","images":[],"step":2},{"description":"Mix together Butter ingredients. Add juice from 2 wedges of lemon.","images":[],"step":3},{"description":"Place chicken in a roasting pan. Use a dessert spoon to loosen skin from chicken (see video). Do the top (the breast) and the drumsticks – not the underside.","images":[],"step":4},{"description":"Prop chicken upright, drizzle butter under skin, using most of the garlic/herb sludge, but saving a bit of butter for the skin (Note 3).","images":[],"step":5},{"description":"Drizzle / smear remaining butter all over surface of the chicken. Squeeze over juice of 2 lemon wedges.","images":[],"step":6},{"description":"Stuff used lemon wedges and rosemary inside chicken.","images":[],"step":7},{"description":"Tie drumstick ends with string and tuck wing tips under the chicken.","images":[],"step":8},{"description":"Sprinkle all over with salt and pepper.","images":[],"step":9},{"description":"Place onion and garlic in the pan, place chicken on top. Pour wine around, drizzle chicken with oil.","images":[],"step":10},{"description":"Transfer to oven. Roast for 10 minutes, then turn oven down to 180C/350F (all oven types). Roast for a further 1 hr 15 minutes, or until the internal temperature is 75C/165F or until juices run clear when pierced at the join between the drumstick and the body. Baste twice (30 min then at 1 hr), spooning pan juices over skin.","duration":10,"images":[],"step":11},{"title":"Rest for 15 minutes","description":"don’t cover, skin becomes wet.","duration":15,"images":[],"step":12},{"description":"Serve with pan juices (see video for how to carve). I discard onion but use the garlic in the pan. See notes for side suggestions & how to use carcass for incredible homemade broth!","images":[],"step":13}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-recipes","dietary","easter-mains","easter-recipes","gluten-free-recipes","iconic-dishes","main-dishes","roasts","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_523224221b01', 'en', 'US', 'Homemade Chicken Noodle Soup (from scratch!)', 'Recipe video above. A classic version made from scratch using a whole chicken. It''s light yet full of flavour that you can''t get using store bought chicken broth!', 'https://www.recipetineats.com/tachyon/2017/05/Chicken-Noodle-Soup-from-scratch_3.jpg', 20, 100, 120, 6, '[{"id": "ing_chicken", "quantity": {"value": 1.8, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_steak", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 4.0, "unit": "bunch"}}, {"id": "ing_water", "quantity": {"value": 9.0, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken", "quantity": {"value": 1.8, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 1.8, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.4, "unit": "pack of 500g"}}, {"id": "ing_vegeta", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1.8 kg / 3.5 lb whole chicken (, rinsed and cleaned, the best quality you can afford (Note 1))","1 head of garlic (, cut in half horiztonally)","2 carrots (, cut into chunks)","2 celery ribs (, cut into chunks)","2 onions (, peeled and cut into quarters)","1 tbsp black peppercorns","2 bay leaves (, fresh or dried)","4 thyme sprigs (or 1 1/2 tsp dried thyme leaves)","9 - 10 cups water (enough to just cover chicken)"],"purpose":"Homemade Broth:"},{"ingredients":["1 tbsp olive oil","1 large onion (, diced)","3 garlic cloves (, minced)","2 medium carrots (, cut in quarters lengthwise then chopped)","2 celery ribs (, cut into 1 cm/ 1/2\" thick pieces)","2 cups shredded chicken (from homemade broth)","2 litres / 2 quarts homemade chicken broth (above)","200 g/ 6 oz egg noodles or pasta of choice (Note 3)","2 - 3 tsp Vegeta or other stock powder (Note 4)","1/2 tsp black pepper","4 thyme sprigs (, optional)","1 bay leaf (, optional)","Finely chopped parsley (, for garnish (optional))"],"purpose":"Soup:"}]', '[{"description":"Place the chicken in a large pot. Add remaining Broth ingredients, then add enough water so the chicken is just covered (too much water = weak broth).","images":[],"step":1},{"description":"Cover with lid, bring the water to a gentle simmer over medium heat. Then adjust heat so it''s simmering GENTLY with the lid on. Simmer 1.5 hours until chicken is tender and easily comes off the bone. (Or 8 hours on low in a slow cooker)","images":[],"step":2},{"description":"Scoop scum off surface once or twice during first 30 minutes.","images":[],"step":3},{"description":"Transfer chicken to pan. Shred meat and discard bones. You''ll only need half the chicken meat, save the rest for another purpose.","images":[],"step":4},{"description":"Remove carrots, celery etc from broth, and discard. Optional: Chop carrot and celery, add back into soup with chicken. (Note 5)","images":[],"step":5},{"title":"Optional","description":"Refrigerate soup for a few hours until the fat sets, then scoop the fat off the surface (I do this, healthier & makes soup clearer).","images":[],"step":6},{"description":"Heat oil in a large pot over medium meat. Add onion and garlic, cook for 2 minutes. Add celery and carrots, cook for 5 minutes until softened and a bit sweet, don''t let them brown.","duration":2,"images":[],"step":7},{"description":"Turn heat up to medium high. Gently pour 8 cups broth in (top up with water if necessary), leaving behind residue settled in the bottom of the broth pot.","images":[],"step":8},{"description":"Add Vegeta (stock powder), thyme, bay leaf and pepper. Stir.","images":[],"step":9},{"description":"When it starts bubbling, add noodles/pasta. Cook for time per packet MINUS 2 minutes. Stir gently only once or twice (Note 6).","images":[],"step":10},{"description":"Add half the chicken, stir (it warms quickly), then season with salt and pepper to taste - season well!","images":[],"step":11},{"description":"Serve soup immediately, garnished with fresh parsley.","images":[],"step":12}]', '["egg","gluten"]', '["high_protein","low_calorie"]', '{"mealType":["main_course"],"cuisine":[],"categories":["chicken-recipes","iconic-dishes","main-dishes","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a7a5bbf4b662', 'en', 'US', 'Butter Chicken', 'RECIPE VIDEO above. This is a Chef recipe and is one of the easiest Indian curries to make. The Butter Chicken Sauce is so good that you will want it on tap! Many restaurants take it over the top by adding copious amounts of ghee or butter into the sauce, but you''ll find this rich enough as it is.And next time, try the streamlined One-Pan Baked Butter Chicken (readers are loving it!).', 'https://www.recipetineats.com/tachyon/2019/01/Butter-Chicken_5.jpg', 10, 25, 35, 3, '[{"id": "ing_yogurt", "quantity": {"value": 0.15, "unit": "tub of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_turmeric", "quantity": {"value": 0.013, "unit": "jar"}}, {"id": "ing_garam_masala", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.68, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_tomato", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_white_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1/2 cup plain yoghurt (, full fat)","1 tbsp lemon juice","1 tsp tumeric powder","2 tsp garam masala (Note 1)","1/2 tsp chilli powder or cayenne pepper powder (Note 2)","1 tsp ground cumin","1 tbsp ginger, freshly grated","2 cloves garlic, crushed","1.5 lb / 750 g chicken thigh fillets, cut into bite size pieces"],"purpose":"Marinade"},{"ingredients":["2 tbsp (30 g) ghee or butter, ( OR 1 tbsp vegetable oil (Note 3))","1 cup tomato passata (aka tomato puree) (Note 4)","1 cup heavy / thickened cream (Note 5)","1 tbsp sugar","1 1/4 tsp salt"],"purpose":"Curry"},{"ingredients":["Basmati rice","White rice","Coriander/cilantro (optional)"],"purpose":"To serve – choose"}]', '[{"title":"Optional blitz","description":"for an extra smooth sauce, combine the Marinade ingredients (except the chicken) in a food processor and blend until smooth. (I do not do this)","images":[],"step":1},{"title":"Marinade","description":"Combine the Marinade ingredients with the chicken in a bowl. Cover and refrigerate overnight, or up to 24 hours (minimum 3 hrs).","images":[],"step":2},{"title":"Cook chicken","description":"Heat the ghee (butter or oil) over high heat in a large fry pan. Take the chicken out of the Marinade but do not wipe or shake off the marinade from the chicken (but don''t pour the Marinade left in the bowl into the fry pan).","images":[],"step":3},{"description":"Place chicken in the fry pan and cook for around 3 minutes, or until the chicken is white all over (it doesn''t really brown because of the Marinade).","images":[],"step":4},{"title":"Sauce","description":"Add the tomato passata, cream, sugar and salt. Also add any remaining marinade left in the bowl. Turn down to low and simmer for 20 minutes. Do a taste test to see if it needs more salt.","duration":20,"images":[],"step":5},{"description":"Garnish with coriander/cilantro leaves if using. Serve with basmati rice.","images":[],"step":6},{"description":"The Butter Chicken is pictured with my very easy No Yeast Flatbread and no-fry papadums (Note 5).","images":[],"step":7}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["main_course"],"cuisine":["Indian"],"categories":["chicken-breast-recipes","chicken-recipes","curry-recipes","dietary","gluten-free-recipes","iconic-dishes","indian-recipes","main-dishes","most-popular","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c30ed1dfab49', 'en', 'US', 'Lemon Garlic Slow Cooker Roast Chicken', 'Recipe video above. This is a quick and easy yet amazing way to cook a whole chicken in the slow cooker - it''s a slow cooker "roast chicken"! It''s so moist and juicy inside, like it’s been brined or marinated. VERY forgiving recipe!', 'https://www.recipetineats.com/tachyon/2014/08/Lemon-Garlic-Slow-Cooker-Roast-Chicken_4.jpg', 10, 300, 310, 5, '[{"id": "ing_chicken", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.037, "unit": "pack of 400g"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}]', '[{"ingredients":["2 kg / 4 lb whole chicken (, patted dry (Note 1))"]},{"ingredients":["1 tsp dried thyme","1/2 tsp dried parsley","1/2 tsp dried oregano","3/4 tsp salt","1/2 tsp black pepper","2.5 tbsp olive oil ((or melted butter), plus extra for drizzling)","3 garlic cloves (, minced)","1 large lemon (, all zest + all juice)"],"purpose":"Rub (Note 2):"},{"ingredients":["1 tbsp cornflour/cornstarch mixed with 1 tbsp water","1 extra lemon (, just in case)"],"purpose":"Lemon Sauce:"}]', '[{"title":"Rub","description":"Mix Rub ingredients. should be fairly thick and sludgy. Adjust with extra oil if too thick.","images":[],"step":1},{"title":"Loosen Skin","description":"Use upside spoon to loosen skin of chicken (see video). Spoon most of the Rub under the skin, leaving about 1 tbsp mostly oil for the skin. Use hands or spoon on skin to spread the paste - doesn''t need to be perfect.","images":[],"step":2},{"description":"Stuff used lemon inside the chicken.","images":[],"step":3},{"description":"Put rack inside slow cooker (Note 3), place chicken on top. Spread with remaining sludge, sprinkle with a pinch of salt and pepper.","images":[],"step":4},{"description":"Slow cook 5 hours on low or 3 hours on high, or until juices run clear or internal temperature is 75C / 165F using a meat thermometer. (Note 4 for other cook methods)","images":[],"step":5},{"title":"Brown skin","description":"Remove chicken from slow cooker, drizzle with a bit of extra oil. Grill/broil on medium high for 5 to 10 minutes to brown the skin (~25cm /10\" from heat source). Or oven 240C/450F for 10 min.","duration":7.5,"images":[],"step":6},{"description":"Spoon over pan juices, then serve with Lemon Sauce! (No need to rest chicken)","images":[],"step":7},{"description":"Pour all slow cooker liquid into a saucepan, add cornflour / water mixture. Mix.","images":[],"step":8},{"description":"Bring to simmer over medium high and cook until liquid thickens to thin syrup (depends how much liquid you have, usually 3 min or so). Adjust salt and pepper to taste, add more lemon if desired (the extra lemon). Pour into jug.","images":[],"step":9}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["chicken-recipes","dietary","easter-mains","easter-recipes","gluten-free-recipes","greek-recipes","main-dishes","mediterranean-recipes","most-popular","quick-and-easy","slow-cooker-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ca72e08ec8df', 'en', 'US', 'Chicken Stroganoff', 'Recipe video above. You love Beef Stroganoff...now try CHICKEN! Golden seared chicken with a creamy mushroom Stroganoff gravy, I like making this with whole chicken thighs so I can brown it nicely which leaves brown bits in the pan that makes an incredible flavour base for the sauce!', 'https://www.recipetineats.com/tachyon/2018/11/Chicken-Stroganoff_8.jpg', 5, 15, 20, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 40.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.4, "unit": "tub of 250g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 250.0, "unit": "pack of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["600g / 1.2 lb chicken thighs (4 - 5) (, boneless skinless (or breast or tenderloin, Note 1))","1 tsp garlic powder","Salt and pepper","1 tbsp olive oil"],"purpose":"Chicken:"},{"ingredients":["1 large onion (, chopped)","300g / 10oz mushrooms (, sliced (not too thin))","40g / 3 tbsp butter","2 tbsp flour (Note 2)","2 cups / 500 ml beef broth/stock (, salt reduced)","1 tbsp Dijon mustard","2/3 cup (150g) sour cream (or yogurt)"],"purpose":"Gravy:"},{"ingredients":["250 - 300 g / 8 - 10 oz pasta or egg noodles of choice (Note 3)","Chopped parsley or chives (, for garnish (optional))"],"purpose":"Serving:"}]', '[{"description":"Sprinkle chicken with garlic powder, salt and pepper on both sides.","images":[],"step":1},{"description":"Heat oil in a large skillet over medium heat. Place chicken in skillet smooth side down.","images":[],"step":2},{"description":"Press down lightly with with spatula. Cook for 4 minutes until golden.","duration":4,"images":[],"step":3},{"description":"Turn and press lightly with spatula. Cook for 2 minutes.","duration":2,"images":[],"step":4},{"description":"Remove chicken onto a plate.","images":[],"step":5},{"description":"Turn heat up to medium high. Add butter, melt. Then add onions, cook for 1 minute, then add mushrooms.","duration":1,"images":[],"step":6},{"description":"Cook mushrooms until golden. Scrape bottom of fry pan to get all the golden bits off (this is flavour!).","images":[],"step":7},{"description":"Add flour, cook, stirring, for 1 minute.","duration":1,"images":[],"step":8},{"description":"Add half the broth while stirring. Once incorporated, add remaining broth.","images":[],"step":9},{"description":"Stir, then add sour cream and mustard. Stir until incorporated (don''t worry if it looks split, sour cream will \"melt\" as it heats).","images":[],"step":10},{"description":"Bring to simmer ,then reduce heat to medium low. Once it thickens to the consistency of pouring cream (3 minutes), adjust salt and pepper to taste.","images":[],"step":11},{"description":"Add chicken back in (including plate juices). Simmer for 1 minute, then remove from stove.","duration":1,"images":[],"step":12},{"description":"Serve over pasta or egg noodles, sprinkled with parsley or chives if desired.","images":[],"step":13}]', '["egg","gluten","milk","mustard"]', '["high_protein","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken","chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","mains","mushroom-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_fcceea8f8ac8', 'en', 'US', 'Juicy Roast Turkey', 'Recipe video above. This is still the only way I roast a whole turkey - dry brined with a seasoned salt. Start it in a hot oven upside down, then finish in a lower oven right side up. Brush with lots of butter, but only add minced garlic and fresh herbs towards the end else it burns. The turkey flesh is juicy, the skin is crisply golden, it''s simple, practical and foolproof. No buckets of liquid brine! You can even start it while the turkey is still partially frozen - it will brine as it thaws. Dry brined meats also cook faster - a 5kg/10lb turkey takes under 2 hours. Useful, when there''s lots of oven demand!Start this recipe two days before cooking. You can brine up to 3 days, but 4 days doesn''t add anything and I worry about food safety. Use the RECIPE SCALER to change ingredients to the weight of your turkey (click/tap on servings and slide!).', 'https://www.recipetineats.com/tachyon/2018/11/Juicy-Roast-Turkey_Dry-Brined_2.jpg', 20, 120, 140, 10, '[{"id": "ing_whole_turkey", "quantity": {"value": 4.536, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_mixed_herbs", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_butter", "quantity": {"value": 10.0, "unit": "block of 250g"}}, {"id": "ing_rosemary", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_wine", "quantity": {"value": 0.5, "unit": "bottle of 750ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_chicken", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["10 lb / 5kg whole turkey (, thawed (plain not pre brined) (Note 1))"]},{"ingredients":["2 1/2 tbsp kosher salt / cooking salt (Note 2)","2 tsp dried thyme (, or other herb of choice)","1 tsp paprika (, sweet or ordinary)","1 tsp garlic powder (optional)","1/2 tsp black pepper"],"purpose":"Dry Brine Salt Rub:"},{"ingredients":["2 heads of garlic (, halved horizontally (ie 4 halves))","1 onion (, halved - skin on is fine (brown, yellow, white))","2 small bunch mixed herbs (, sage, rosemary, thyme, parsley (optional, Note 3))","10 tbsp (150g) unsalted butter (, melted)","1 tbsp (in total) sage, rosemary and thyme (, finely chopped - equal amounts of each (Note 3))","3 garlic cloves (, minced)","1 1/2 cups dry white wine (, or water (Note 4))","Salt & pepper"],"purpose":"For Roasting"},{"ingredients":["4 cups chicken broth / stock (, low sodium)","5 tbsp flour (, plain / all purpose)","Salt and pepper"],"purpose":"Gravy (~ 4 cups/1L)"}]', '[{"description":"Rub turkey with the Salt Rub, wrap mummy-like in cling wrap. Fridge 48 hrs, flipping halfway. Stuff, roast upside down 30min in hot 220°C/425°F (200°C fan) oven, flip, garlic-herb-butter baste, finish roasting in lower oven 165°C/325°F (150°C fan).","images":[],"step":1},{"description":"Dry Brining Preparation","images":[],"step":2},{"title":"Salt Rub","description":"Mix together the Rub ingredients.","images":[],"step":3},{"title":"Prep Turkey","description":"Pat the turkey dry with paper towels, inside and out. Remove giblets or anything else inside the turkey. (Note 5)","images":[],"step":4},{"title":"Sprinkle","description":"Sprinkle 1 teaspoon of the Salt Rub inside the turkey and use you hand to spread it (roughly is fine). Turn the turkey upside down, then rub 1 teaspoon of the Salt Rub on the underside.","images":[],"step":5},{"description":"Turn the turkey upright and rub the remaining Salt Rub on the turkey, using most on the breast - even some under the skin if you can.","images":[],"step":6},{"description":"Wrap turkey mummy-like in lots of cling wrap (works best, I find) or place the turkey in a sealable plastic bag (Note 6).","images":[],"step":7},{"description":"Brining (Note 7):","images":[],"step":8},{"description":"Place turkey upside down in baking pan. Refrigerate 2 days (minimum) up to 3 days (4 days adds nothing, I find).","images":[],"step":9},{"title":"24 hours later","description":"Flip turkey so it''s right side up.","images":[],"step":10},{"title":"24 (to 48 hours) later","description":"unwrap turkey. The skin should be moist but not wet. If wet, pat dry. Leave out for 30 min before roasting.","duration":30,"images":[],"step":11},{"description":"Prepare for roasting:","images":[],"step":12},{"description":"Preheat oven to 220°C/425°F (200°C fan-forced)","images":[],"step":13},{"title":"Prep for roasting","description":"Place the onions and garlic in a roasting pan. Place a roasting rack on top - if you have one (Note 8 for sub).","images":[],"step":14},{"description":"Stuff bunch of herbs + 2 garlic halves + 3 tbsp butter (45g) inside the turkey. Tie drumsticks together with kitchen twine (optional).","images":[],"step":15},{"description":"Place turkey UPSIDE DOWN on the rack. Twist the wings so they are on top - see video. Brush with a bit of melted butter. Sprinkle with a tiny bit of salt and pepper.","images":[],"step":16},{"title":"Wine","description":"Pour wine in roasting pan.","images":[],"step":17},{"description":"Roast for 30 minutes.","duration":30,"images":[],"step":18},{"title":"Flip & brush","description":"Use a tea towel to turn the turkey over so it''s right side up. Brush with butter, sprinkle with a tiny bit of salt and pepper.","images":[],"step":19},{"description":"Turn oven down to 165°C/325°F (150°C fan).","images":[],"step":20},{"description":"Roast turkey 45 minutes.","images":[],"step":21},{"title":"Garlic herb butter","description":"Mix remaining butter with garlic and herbs. Brush turkey generously with butter.","images":[],"step":22},{"description":"Roast turkey for a further 30 minutes or until a) the thermometer that comes with the turkey pops up; or b) a thermometer inserted between the breast and leg reads 165°F/75°C. (Notes 9, 10). Cover loosely with foil if browning too much.","images":[],"step":23},{"title":"Rest","description":"Remove turkey onto serving plate, cover loosely with foil and rest for 30 minutes before transferring to platter for presentation and carving (see in post for styling idea).","duration":30,"images":[],"step":24},{"description":"Serve turkey with gravy and/or Cranberry Sauce.","images":[],"step":25},{"description":"Place roasting pan (with garlic, onion etc still in it) on the stove over medium high heat. Add flour and cook for 2 minutes.","duration":2,"images":[],"step":26},{"description":"Add broth and use a potato masher to mash the onion and garlic into the mixture. Use a wooden spoon to scrap the bottom of the pan. Cook for 3 to 5 minutes or until thickened.","duration":4,"images":[],"step":27},{"description":"Strain into a bowl, pressing down to extract all the flavour out of the onion and garlic. Transfer to gravy boat.","images":[],"step":28}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-recipes","dietary","gluten-free-recipes","iconic-dishes","main-dishes","roasts","turkey-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_004c57a252d8', 'en', 'US', 'Chicken Pot Pie', 'Recipe video above. Everybody''s favourite Chicken Pot Pie! A creamy chicken and vegetable filling with a hint of thyme, topped with puff pastry. The smell when this is baking is SO GOOD! Makes 4 large, 6 medium or 1 large pie. Brilliant freezer standby meal.', 'https://www.recipetineats.com/tachyon/2018/10/Chicken-Pot-Pie_2.jpg', 15, 60, 75, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_thyme", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 2000.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_steak", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_thyme", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_wine", "quantity": {"value": 0.111, "unit": "bottle of 750ml"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sheet_puff_pastry", "quantity": {"value": 2.0, "unit": "pack"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}]', '[{"ingredients":["600 g/1.2lb chicken breast (or boneless thighs)","2 cups milk (, any fat % (Note 1))","1 cup chicken broth (stock)","2 tsp chicken or vegetable stock powder (Note 2)","2 sprigs thyme (, optional)"],"purpose":"Chicken & broth:"},{"ingredients":["1 large onion (, chopped)","2 large carrots ((3 small). chopped)","3 celery ribs (, chopped)","2 garlic cloves (, minced)","50g / 3 tbsp butter","1 tsp dried thyme","1/3 cup white wine (sub more chicken stock)","1/3 cup flour","1/2 cup grated parmesan","1/2 tsp black pepper","1 cup frozen peas (, no need to thaw)","2 sheets puff pastry (enough to cover pots, with drape)","1 egg (, lightly whisked)"],"purpose":"Chicken Pot Pie:"}]', '[{"description":"Place milk, broth and stock powder in a large saucepan. Bring to a very gentle simmer over medium heat, add chicken and thyme.","images":[],"step":1},{"description":"Place lid on, simmer gently on medium low for 15 minutes (do not boil, can make milk split).","duration":15,"images":[],"step":2},{"description":"Remove chicken, shred or dice (don''t worry if inside a bit uncooked). Cover pot and set poaching liquid aside.","images":[],"step":3},{"description":"Chicken Pot Pie:","images":[],"step":4},{"description":"Melt butter in a large pot over medium high heat. Add garlic and onion, cook for 2 minutes. Add thyme, carrot and celery, cook for 3 minutes or until carrot is softened.","duration":2,"images":[],"step":5},{"description":"Add wine. Stir, scraping the bottom of the pot, and cook for 1 1/2 minutes or until wine is mostly evaporated.","images":[],"step":6},{"description":"Add flour and stir for 1 minute.","duration":1,"images":[],"step":7},{"description":"Add about half the reserved poaching liquid and stir until all flour is incorporated - it will be a thick sludge.","images":[],"step":8},{"description":"Add remaining milk broth, parmesan, pepper. Stir.","images":[],"step":9},{"description":"Add chicken and peas, stir.","images":[],"step":10},{"description":"Once mixture is heated (you''ll see steam), cook for 3 minutes to thicken the sauce, stirring regularly. (Note 3)","duration":3,"images":[],"step":11},{"title":"Remove from heat. Spoon into oven proof pots","description":"4 large or 6 small (Note 4). Cool in fridge at least 30 minutes. (Note 5)","images":[],"step":12},{"description":"Assembly & Baking:","images":[],"step":13},{"description":"Meanwhile, remove puff pastry from freezer to partially thaw. Then use a bowl as a guide to cut rounds from the pastry about 2.5cm / 1\" wider (all the way around) than the pots - be generous!","images":[],"step":14},{"description":"Preheat oven to 180C/350F.","images":[],"step":15},{"description":"Brush edge of pots with egg. Top with puff pastry, folding down the edges.","images":[],"step":16},{"description":"Brush pastry with egg. Cut a 2cm / 2/3\" slide in the middle with a small knife.","images":[],"step":17},{"title":"Bake 35","description":"40 minutes until deep golden.","images":[],"step":18},{"description":"Serve immediately!","images":[],"step":19}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2aeecf3c299e', 'en', 'US', 'Greek Chicken', 'Recipe video above. Yogurt is a magical marinade! This chicken is golden on the outside, beautifully tenderised on the inside and infused with terrific garlic-oregano flavours. Serve this with a Greek Salad and flatbread - or see in post for a full Greek Feast menu! Marinade time: Overnight, min 3 hrs.', 'https://www.recipetineats.com/tachyon/2018/09/Greek-Feast_3.jpg', 8, 50, 58, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.25, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 2.0, "unit": "pack of 3 heads"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.15, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.225, "unit": "tub of 500g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.225, "unit": "tub of 500g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.45, "unit": "bunch"}}]', '[{"ingredients":["1.25 kg / 2.5 lb drumsticks and chicken thighs (, bone in skin on (Note 1))"]},{"ingredients":["6 garlic cloves (, minced (~ 2 tbsp))","2 tbsp white wine vinegar (or red wine or apple cider vinegar)","1/2 cup / 125 ml lemon juice","2 tbsp extra virgin olive oil","3/4 cup Greek yogurt (I use Farmers Union)","1 1/2 tbsp dried oregano","1 tsp salt","1/2 tsp black pepper"],"purpose":"Marinade:"},{"ingredients":["Plain Greek yogurt or Tzatziki","Fresh oregano leaves (optional)"],"purpose":"Serving (optional):"}]', '[{"description":"Mix Marinade ingredients in a large bowl.","images":[],"step":1},{"description":"Add chicken and coat well. Marinade for 24 hours (3 hours minimum).","images":[],"step":2},{"description":"Preheat oven to 180C.350F.","images":[],"step":3},{"description":"Line a tray with foil (trust me), place rack on tray (optional).","images":[],"step":4},{"description":"Place chicken on rack (reserve marinade), skin side up. Bake 30 minutes,","images":[],"step":5},{"title":"Remove from oven. Brush with marinade","description":"do not flip.","images":[],"step":6},{"description":"Return to oven for 20 minutes or until golden and a bit crispy. Give it a spray of olive oil just before it''s done if you want an extra crispy, shiny coat.","duration":20,"images":[],"step":7},{"description":"Rest for a few minutes before serving. Juicy and tasty enough to serve plain but extra great with tzatziki or even some plain yogurt.","images":[],"step":8}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Greek"],"categories":["chicken-breast-recipes","chicken-recipes","greek-recipes","main-dishes","mediterranean-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9b5847dc52c1', 'en', 'US', 'Chicken Fajitas', 'Recipe video above. The secret ingredient in this Fajita marinade is orange juice. It injects flavour as well as brining, and makes the chicken caramelise beautifully when cooked. It doesn’t taste like oranges at all once cooked. Use any coloured peppers you want – though seeing a kaleidoscope of colours on a platter will bring a smile to anyone’s face!', 'https://www.recipetineats.com/tachyon/2017/04/Chicken-Fajitas_8.jpg', 15, 15, 30, 4, '[{"id": "ing_ime_juice", "quantity": {"value": 0.25, "unit": "unit"}}, {"id": "ing_oranges", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_tortillas", "quantity": {"value": 8.0, "unit": "pack of 8"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_lime", "quantity": {"value": 0.075, "unit": "net of 500g"}}]', '[{"ingredients":["1/4 cup / 65 ml lime juice","1/4 cup / 65 ml orange juice (Note 1 for subs)","2 tbsp olive oil","2 garlic cloves (, minced)","1 tsp cumin powder","1 tsp salt","1/2 tsp black pepper"],"purpose":"Marinade:"},{"ingredients":["700g / 1.2 lb skinless chicken thighs or 2 large chicken breasts (, halved horizontally (Note 2))","2 tbsp olive oil","3 capsicums / bell peppers (, deseeded and sliced (red, yellow or green))","1 large onion (, halved and sliced thickly (brown, yellow, white or red))"],"purpose":"Fajitas:"},{"ingredients":["8– 12 small tortillas","1 large avocado (, halved and sliced)","Sour cream","Fresh lime wedges"],"purpose":"To Serve:"}]', '[{"description":"Place Marinade ingredients in a large bowl and mix. Add chicken, toss well to coat. Marinade for 1 hour to 24 hours (or freeze immediately then defrost overnight).","images":[],"step":1},{"description":"Use 2 skillets to cook the chicken and vegetables at the same time, if you can.","images":[],"step":2},{"description":"Heat 1 tbsp oil in a heavy based skillet over high heat until smoking. Add vegetables to cover the base of the pan in a single layer without too much overlapping (I cook in 3 batches). Spread out, leave for 45 seconds (to char it).","duration":0.75,"images":[],"step":3},{"description":"Toss quickly then spread out. Sprinkle with salt and pepper. Leave 45 seconds, toss then spread out, then leave 45 seconds. Remove onto platter and repeat with remaining Vegetables.","images":[],"step":4},{"description":"Heat 1 tbsp oil in a large skillet over medium high heat. Add chicken and cook for 3 to 4 minutes until caramelised. Turn and cook the other side for 3 – 4 minutes.","duration":3.5,"images":[],"step":5},{"description":"Remove onto a plate, cover loosely with foil. Rest for 3 minutes then slice.","duration":3,"images":[],"step":6},{"description":"To Serve:","images":[],"step":7},{"description":"Warm tortillas using chosen method.","images":[],"step":8},{"description":"Pile peppers and onion onto tortilla. Top with chicken, drizzle with sour cream, squeeze over lime juice. Fold, devour and be happy.","images":[],"step":9}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","fajitas","gluten-free-recipes","main-dishes","mains","mexican-recipes","quick-and-easy","taco-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ec1393e00f2e', 'en', 'US', 'Lemon Chicken Salad', 'Recipe video above. A substantial salad with a lemon marinated chicken, dressed with a dill lemon dressing with a touch of honey. You''ll love how the dressing does double duty as the marinade! Bacon is optional - totally delicious without, but always fabulous with. Serves 2 as a meal, 4 as a side.', 'https://www.recipetineats.com/tachyon/2018/07/Lemon-Chicken-Salad-1a.jpg', 15, 8, 23, 2, '[{"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_honey", "quantity": {"value": 0.03, "unit": "jar of 500g"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_chicken_breast", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_dill", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 24.0, "unit": "head"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 0.6, "unit": "punnet of 250g"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_corn", "quantity": {"value": 0.281, "unit": "can of 400g"}}, {"id": "ing_bacon", "quantity": {"value": 0.6, "unit": "pack of 200g"}}]', '[{"ingredients":["2 tsp lemon zest","2 tbsp lemon juice","1 tbsp honey","1 tsp Dijon mustard","3 tbsp extra virgin olive oil","1 large garlic clove (, minced)","1/2 tsp salt + 1/4 tsp black pepper"],"purpose":"Dressing/Marinade:"},{"ingredients":["1 large chicken breast (, halved horizontally* OR 2 boneless skinless chicken thighs)","1 tbsp lemon juice (, extra)","Salt and pepper","1/2 tbsp olive oil"],"purpose":"Chicken:"},{"ingredients":["2 tbsp finely chopped dill","8 cups cos/romaine lettuce (, chopped (or other lettuce of choice, Note 2))","1 cup cherry tomatoes (, halved)","1 medium avocado (, quartered and sliced thickly)","1/2 red onion (, small, finely sliced)","3/4 cup corn kernels (, fresh or canned drained)","120g/ 4 oz bacon (, cooked then chopped (optional))"],"purpose":"Salad:"}]', '[{"description":"Place Dressing ingredients in a jar. Shake well.","images":[],"step":1},{"description":"Place chicken in a bowl. Add 2 tbsp Dressing, 1 tbsp extra lemon juice, plus a pinch of salt and pepper. Mix well. Marinate minimum 20 minutes up to 24 hours.","images":[],"step":2},{"description":"Heat oil in a non stick skillet over medium high heat (or use bacon fat if you use bacon in this!). Add chicken and cook. Halved breasts: 2 minutes each side. Thigh: 4 minutes each side.","images":[],"step":3},{"description":"Transfer to plate, cover loosely with foil for 3 minutes. Slice.","duration":3,"images":[],"step":4},{"description":"Add dill into remaining dressing. Shake.","images":[],"step":5},{"description":"Place remaining salad ingredients in a bowl. Top with chicken.","images":[],"step":6},{"description":"Drizzle dressing all over. Crumble over bacon if using. Serve immediately!","images":[],"step":7}]', '["mustard"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","quick-and-easy","salad-recipes-main-course"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5202326ad070', 'en', 'US', 'Crispy Garlic Chicken Thighs', 'Recipe video above. A fantastic quick and easy chicken thigh recipe! You''ll love the terrific garlic flavour in this - seared on the crust and in the sauce. The trick to crispy skinless chicken thighs is to cook longer on a lower heat.', 'https://www.recipetineats.com/tachyon/2018/06/Garlic-Chicken-Thighs_6a.jpg', 3, 12, 15, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_butter", "quantity": {"value": 25.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["700 g / 1.2 lb skinless boneless chicken thighs (5 to 6)","1 tsp garlic powder","Salt and pepper","1 tbsp olive oil","1/2 cup / 125 ml dry white wine (or broth or water)","25 g / 2 tbsp unsalted butter","2 large garlic cloves (, minced)","Finely chopped parsley (, optional)"]}]', '[{"description":"Sprinkle both sides of chicken with garlic powder, salt and pepper.","images":[],"step":1},{"description":"Heat oil in a large skillet over medium heat. Place chicken in skillet smooth side down.","images":[],"step":2},{"description":"Press down lightly with with spatula. Cook for 5 minutes until deep golden and crispy.","duration":5,"images":[],"step":3},{"description":"Turn and press lightly with spatula. Cook for 2 minutes. Add garlic and butter, cook for 1 minute until garlic is light golden and it smells amazing.","duration":2,"images":[],"step":4},{"description":"Add wine, then turn up heat. Stir around the chicken to dissolve golden bits stuck on the skillet into the wine. Simmer rapidly for 1 1/2 minutes or until alcohol smell evaporates.","images":[],"step":5},{"description":"Remove from heat. Serve chicken with sauce.","images":[],"step":6}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["main_course"],"cuisine":[],"categories":["chicken","chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_902ae41fc7cd', 'en', 'US', 'Mexican Avocado Chicken Salad', 'Recipe video above (see how I scoop out avocado!) A fully loaded salad, satisfying to have as a meal! Crunchy lettuce, creamy avocado corn and tomato salsa, marinated Mexican chicken drizzled with a lime dressing. Makes 2 meal size servings or 3 normal servings. Marinate 30 min.', 'https://www.recipetineats.com/tachyon/2017/05/Mexican-Chicken-Salad-4.jpg', 15, 8, 23, 3, '[{"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_honey", "quantity": {"value": 0.03, "unit": "jar of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 0.6, "unit": "punnet of 250g"}}, {"id": "ing_corn", "quantity": {"value": 0.003, "unit": "can of 400g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_lettuce", "quantity": {"value": 5.0, "unit": "head"}}]', '[{"ingredients":["2 tbsp lime juice","1 tbsp honey","1/4 cup olive oil (65ml)","1 garlic clove, minced","½ tsp salt + black pepper"],"purpose":"Lime Dressing / Marinade:"},{"ingredients":["2 small chicken breasts, 400g/14oz (pound or split if thicker than 2cm / 4/5”)","1/2 tsp EACH chipotle powder (Note 1) and oregano","1/4 tsp cumin powder","Salt & pepper","1/2 tbsp olive oil"],"purpose":"Chicken:"},{"ingredients":["1 avocado, chunky dice (watch video to see how I do this)","1 cup cherry tomatoes, halved","¾ cup corn kernels (canned, drained)","½ red onion, finely chopped"],"purpose":"Avocado Salsa:"},{"ingredients":["1/4 cup coriander / cilantro, finely chopped","5 heaped cups cos / romaine lettuce, cut into bite size pieces"],"purpose":"Salad:"}]', '[{"description":"Place Lime Dressing ingredients in a jar, shake well.","images":[],"step":1},{"description":"Put 2 tablespoons of Dressing in a ziplock bag. Add chipotle, oregano, cumin, salt and pepper, mix/squidge bag. Add chicken, seal and massage to coat. Marinate 30 min – overnight.","images":[],"step":2},{"description":"Heat 1 tbsp olive oil in skillet over medium low, cook chicken to taste (2cm / 4/5” takes around 8 minutes), getting a nice brown crust on it. Rest 5 min then slice.","images":[],"step":3},{"description":"Add 2 tablespoons of coriander into Dressing, shake.","images":[],"step":4},{"description":"Place avocado, corn, tomato and onion in a bowl. Add remaining coriander, drizzle with a bit of Dressing, toss gently.","images":[],"step":5},{"description":"Place lettuce in a bowl, drizzle with a bit of Dressing, toss.","images":[],"step":6},{"title":"Assemble Salad","description":"Place lettuce on a serving platter. Top with Salsa and sliced chicken. Drizzle with remaining Dressing. Serve.","images":[],"step":7}]', '[]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["chicken-breast-recipes","chicken-recipes","mexican-recipes","quick-and-easy","salad-recipes-main-course"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_afb9089ef6bb', 'en', 'US', 'Chicken and Rice Soup', 'Recipe video above. You don''t need to manhandle a whole chicken to make a beautiful flavour infused, golden, savoury broth. Use chicken pieces instead - it''s so much faster and the broth is absolutely incredible! Better flavour that using breast or rotisserie chicken. Inactive simmer time: 30 minutes.', 'https://www.recipetineats.com/tachyon/2018/04/Chicken-and-Rice-Soup_8-1.jpg', 15, 55, 60, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 3.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_steak", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_vegeta_stock_powder", "quantity": {"value": 15.0, "unit": "jar"}}, {"id": "ing_parsley", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_chicken", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_bone_in", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_white_rice", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1 tbsp olive oil","1 tbsp butter (or more oil)","2 garlic cloves (, minced)","1 onion (, chopped)","3 carrots (, halved then cut into 1cm / 2/5\" slices (quarter if really thick))","3 celery ribs (, cut into 1 cm / 2/5\" slices)","3 tsp Vegeta stock powder (, or 2 x vegetable or chicken bouillon cube, or 2 tsp powder (Note 2))","1/2 tsp dried parsley","1/2 tsp dried thyme, optional","1/4 tsp black pepper (, finely ground)","4 cups (1 litre) chicken broth (, low sodium)","4 cups (1 litre) water","600 g (1.2 lb) bone in (, skinless chicken thighs, 4 x 150g/5oz (Note 1))","1 cup (180g) long grain white rice (, uncooked (Note 3))","Salt, adjust to taste","1 tbsp finely chopped parsley (optional)"]}]', '[{"description":"Place oil and butter in a large pot over medium high heat. Add onion and garlic, cook for 5 minutes until onion is translucent.","duration":5,"images":[],"step":1},{"description":"Add carrots and celery, stir for 1 minute.","duration":1,"images":[],"step":2},{"description":"Add stock powder, dried parsley, thyme (if using), pepper, chicken broth, water. Stir, then add chicken.","images":[],"step":3},{"description":"Cover with lid, simmer on medium low for 30 minutes. Adjust heat so it''s bubbling a nice amount, but not crazy energetically or super slowly. Skim off excess foam build up once or twice (not critical, just makes broth clearer).","duration":30,"images":[],"step":4},{"description":"Remove lid, add rice. Stir, cover, simmer 15 minutes.","images":[],"step":5},{"description":"Remove soup from stove.","images":[],"step":6},{"description":"Remove chicken into large bowl. Shred with 2 forks, discard bones then stir into soup.","images":[],"step":7},{"description":"Stir in half the parsley, taste for salt and add if required. Serve, then garnish with extra parsley.","images":[],"step":8}]', '["milk"]', '["gluten_free"]', '{"mealType":["main_course"],"cuisine":[],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","quick-and-easy","rice-recipes","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_aa81cb546061', 'en', 'US', 'Chicken Tikka Masala', 'Recipe VIDEO above. Make this iconic curry at home!!! It''s a stunner - and although there''s an extensive looking list of ingredients, it''s astonishingly straight forward. Far better than paste in a jar, less oily than restaurants, and you can get everything you need from supermarkets!Spice level: Low. Marinating time: 3 - 24 hours', 'https://www.recipetineats.com/tachyon/2018/04/Chicken-Tikka-Masala_0.jpg', 15, 45, 60, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.15, "unit": "tub of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 10.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_garam_masala", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.016, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_turmeric", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.016, "unit": "jar of 40g"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_tomato", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.417, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.4, "unit": "carton of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["600g/ 1.2lb chicken thigh (boneless, skinless), cut into 3cm / 2.2\" cubes (Note 1)","1/2 cup plain yoghurt, ( full fat best (Greek is fine))","6 cloves garlic (, minced (~1.5 tbsp))","1 tbsp fresh ginger (, grated)","1 tsp garam masala (Note 2)","1 tsp each salt, cumin, ground coriander, paprika (sweet, normal or smokey)","1 tbsp vegetable oil","1/8 tsp cayenne pepper (optional)","Pinch black pepper","2 tsp lemon juice"],"purpose":"Chicken Tikka Marinade:"},{"ingredients":["1 - 2 tbsp oil (Note 3)"],"purpose":"Cooking Chicken:"},{"ingredients":["2 tsp turmeric","1 tbsp garam masala (Note 2)","2 tsp coriander","1 tsp cumin","1/8 tsp cardamom powder","1/8 tsp cayenne pepper"],"purpose":"Curry Sauce Spices:"},{"ingredients":["3 tbsp (65ml) vegetable oil (Note 3)","30g / 2 tbsp unsalted butter OR ghee","1 onion, finely chopped (brown, white or yellow)","1 tsp salt","2 tbsp fresh ginger (, grated)","6 cloves garlic (, crushed or grated)","1 tbsp paprika (not smoked)","1 2/3 cups (400ml) tomato passata (tomato puree)","1 2/3 cups (400ml) water","100 ml (1/3 cup + 1 tbsp) cream (thickened or pure is fine)","1 tsp sugar","50g / 3 tbsp unsalted butter OR ghee"],"purpose":"Curry Sauce:"},{"ingredients":["Basmati rice"],"purpose":"Serving"}]', '[{"description":"Combine all ingredients except chicken in a bowl and mix. Add chicken and turn well to coat.","images":[],"step":1},{"description":"Cover with cling wrap and leave in fridge to marinate overnight (3 hours minimum).","images":[],"step":2},{"description":"Heat 1 tbsp oil in a non stick pan over high heat until smoking. Add half the chicken and spread out. Leave for 2 minutes or until charred. Turn each piece and cook the other side until charred - don''t worry if not cooked inside. (Note 4, also Video helpful here) Remove into bowl.","duration":2,"images":[],"step":3},{"description":"Scrape out charred bits left in pan and discard. Add more oil if required and cook remaining chicken.","images":[],"step":4},{"description":"Wipe skillet with paper towels (or do this part in a pot as you need a lid). Turn heat down to medium high.","images":[],"step":5},{"description":"Add oil and butter. When butter is melted, add onions, ginger and salt.","images":[],"step":6},{"description":"Cook, stirring constantly to ensure it doesn''t burn, until the ginger is starting to turn golden and the onions smell sweet, about 5 - 7 minutes.","images":[],"step":7},{"description":"Reduce the heat to medium. Add the garlic and paprika, and cook for 2 minutes.","duration":2,"images":[],"step":8},{"description":"Add the Curry Sauce Spices, and cook a further 2 minutes, stirring.","images":[],"step":9},{"description":"Add tomato passata and water, and mix. Bring to a simmer, then cover and reduce heat to low.","images":[],"step":10},{"description":"Simmer for 15 minutes, stirring occasionally.","duration":15,"images":[],"step":11},{"description":"Pour curry into a bowl, then use a stick blender to puree until smooth (Note 5).","images":[],"step":12},{"description":"Return sauce to skillet. Add cream, sugar and butter. Stir to melt the butter.","images":[],"step":13},{"description":"Add chicken, stir. Simmer for a few minutes until the chicken is cooked through.","images":[],"step":14},{"title":"Optional","description":"Sprinkle with a pinch of extra garam masala at the end.","images":[],"step":15},{"description":"Serve over basmati rice, sprinkled with coriander/cilantro if desired. Try this No Yeast Flatbread as a quick naan!","images":[],"step":16}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["chicken-breast-recipes","chicken-recipes","curry-recipes","dietary","gluten-free-recipes","iconic-dishes","indian-recipes","main-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_94039338708c', 'en', 'US', 'Oven Baked Chicken with Rice Pilaf (Cranberry, Walnut and Apple)', 'The RICE PILAF in this recipe is sensational. Tastes savoury but with a touch of apple sweetness, herby fragrance, combined with plump cranberries, warm crunch of walnuts, and with fresh apple providing a fabulous finishing touch. The chicken is sticky from the jam (great shortcut trick) and savoury from the seasoning spices. The key step that makes a real difference is "oven sautéing" onion and garlic first. Festive inspired midweek meal to have all year round! Recipe VIDEO below.', 'https://www.recipetineats.com/tachyon/2017/12/Baked-Chicken-with-Rice-Pilaf-2.jpg', 15, 65, 80, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_white_rice", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_apples", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_cranberries", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_walnuts", "quantity": {"value": 150.0, "unit": "jar"}}, {"id": "ing_apples", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_rosemary", "quantity": {"value": 0.075, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_jam", "quantity": {"value": 0.135, "unit": "jar of 370g"}}, {"id": "ing_mustard", "quantity": {"value": 0.188, "unit": "jar of 200g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 50.0, "unit": "bottle"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["5 chicken thigh fillets (, bone in (about 220g / 7oz each) (Note 1))"]},{"ingredients":["1 small onion (, finely chopped)","1 garlic clove (, minced)","50g (3.5 tbsp) unsalted butter (or sub with oil of choice)","1 1/2 cups (270g) long grain white rice (, uncooked (Note 2))","1 1/4 cups (315 ml) apple juice","1 1/2 cups (375 ml) chicken broth","1 cup (120g) dried cranberries (or other dried fruit of choice)","1 cup (125g) walnuts , roughly chopped (or other nuts of choice)","1 red apple (, cut into small dice)"],"purpose":"Rice:"},{"ingredients":["3/4 tsp dried rosemary","1 tsp dried thyme","3/4 tsp salt","1/2 tsp pepper"],"purpose":"Rice Herbs:"},{"ingredients":["1/3 cup (100g) apricot jam (or other jam - Note 3)","2 1/2 tbsp Dijon mustard","1/2 tsp garlic powder","1/2 tsp All Spice","1/4 tsp paprika","3/4 tsp salt","1/4 tsp black pepper"],"purpose":"Sticky Chicken Glaze:"},{"ingredients":["Oil spray","Fresh parsley (, finely chopped)"],"purpose":"Garnish (optional):"}]', '[{"description":"Preheat oven to 200C/390F (standard) or 180C/350F (fan/convection).","images":[],"step":1},{"description":"Use a baking dish about 22 x 33cm / 9 x 13\".","images":[],"step":2},{"description":"Scatter onion and garlic in baking dish, dollop butter over. Bake for 15 minutes, then remove.","duration":15,"images":[],"step":3},{"description":"If your chicken has skin on it, remove it (just pull it off). Otherwise, the rice will be too greasy.","images":[],"step":4},{"description":"Whisk together Sticky Chicken Glaze. Add chicken, turn to coat.","images":[],"step":5},{"description":"Add rice, apple juice, chicken broth and Rice Herbs into the pan with the onion. Stir.","images":[],"step":6},{"description":"Add cranberries and walnuts. Stir.","images":[],"step":7},{"title":"Top with chicken","description":"it will be partly submerged. Save glaze in bowl.","images":[],"step":8},{"title":"Cover with foil. Bake 20 minutes. Remove foil","description":"don''t worry if there''s still liquid (Note 4).","images":[],"step":9},{"title":"Spoon all remaining Glaze onto chicken. Optional","description":"spray with oil (gives chicken a slightly nicer finish). Bake for another 30 - 35 minutes until chicken is browned.","images":[],"step":10},{"description":"Remove pan from oven. Rest 5 minutes. Remove chicken, add apple, then use fork to fluff rice.","images":[],"step":11},{"description":"Serve chicken with rice pilaf, garnished with fresh parsley if desired.","images":[],"step":12}]', '["milk","mustard"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","one-pot-recipes","quick-and-easy","rice-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_968c3ab634e5', 'en', 'US', 'Garlic Herb Butter Roasted Turkey Breast', 'RECIPE VIDEO above. An incredible way to roast turkey breast! The garlic herb butter smeared under the skin bastes the breast while it roasts, and creates a butter pan sauce to serve on the side. A meat thermometer will ensure your turkey comes out beautifully juicy. Truly worth using fresh herbs for this recipe, but see notes for dried options.', 'https://www.recipetineats.com/tachyon/2017/11/Herb-Garlic-Butter-Roast-Turkey-Breast-4.jpg', 20, 90, 110, 6, '[{"id": "ing_5_6_lb_single_turkey_breast", "quantity": {"value": 2.5, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_rosemary", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 4.0, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 150.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 4.0, "unit": "pack of 3 heads"}}, {"id": "ing_sage", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_rosemary", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["2.5 - 3 kg / 5-6 lb single turkey breast (, skin on, bone in (Note 1), NOT BRINED)","1/2 tsp salt","Black pepper","Small bunch of fresh herbs - 4 rosemary sprigs (, 8 sprigs sage, 10 thyme sprigs)","12 garlic cloves (, smashed with side of knife (see video))"]},{"ingredients":["150 g / 5 oz (10 tbsp) unsalted butter, softened","1 1/4 tsp table salt or 1 1/2 tsp kosher salt","1/2 tsp black pepper","4 large garlic cloves (, minced)","1 tbsp finely chopped sage (, fresh)","1 tbsp finely chopped rosemary (, fresh)","1 tbsp fresh thyme leaves (, fresh)","1 tbsp finely chopped parsley leaves (, fresh)"],"purpose":"Butter:"}]', '[{"title":"Remove fridge chill","description":"Take turkey out of the fridge 45 minutes before cooking (or 30 minutes if it''s super hot where you are).","images":[],"step":1},{"description":"Preheat oven to 200C / 390F (all oven types). Put rack in the lower middle position. (Note 3)","images":[],"step":2},{"description":"Place garlic and bunch of herbs in the middle of a baking dish. (Note 4)","images":[],"step":3},{"title":"Butter","description":"Mix Butter ingredients together.","images":[],"step":4},{"title":"Loosen skin","description":"Use an upside teaspoon to help loosen the skin from the turkey flesh (easiest to go under the paper thin layer under the surface skin). Video helpful here.","images":[],"step":5},{"title":"Smear butter under skin","description":"Use about 2/3 of the butter, and smear it under the skin on the top half of the breast. Best to smear using hands under the skin (not on surface), to ensure it spreads as evenly as possible.","images":[],"step":6},{"description":"Turn turkey upside down. Reserve about 2 tbsp butter for the surface, smear the rest on the underside.","images":[],"step":7},{"description":"Place turkey in pan on the herbs, skin side up. Now smear skin with remaining butter - you don''t want much on the skin because the herb bits burn.","images":[],"step":8},{"title":"STOP HERE for make ahead option","description":"the turkey can be left like this for up to 24 hours. Remove from fridge 45 minutes before serving then proceed.","images":[],"step":9},{"description":"Sprinkle top and sides of breast with salt and pepper all over. Place turkey in oven, turn DOWN to 180C/350F.","images":[],"step":10},{"description":"Roast for 1 hr 30 minutes, basting all over every 30 minutes. (Note 5)","duration":60,"images":[],"step":11},{"title":"COOK TIME / INTERNAL TEMPERATURE","description":"The turkey is cooked when the meat thermometer inserted at the thickest part is 74C/165F. I check in several places. Allow 15 minutes per 500g/1 lb of turkey. My 2.8 kg / 5.5lb bone in turkey took 1 hr 40 minutes.","images":[],"step":12},{"description":"COVER turkey with foil when it becomes golden to your taste, at any point during the cook time (1 hr 15 minutes for me).","images":[],"step":13},{"title":"Rest","description":"Remove turkey from pan and place on serving plate. Cover loosely with foil and rest for 15 to 20 minutes before carving.","duration":17.5,"images":[],"step":14},{"description":"Butter Sauce (Note 6):","images":[],"step":15},{"description":"The pan will have melted butter and roasting juices. Remove herbs and garlic, squeezing out juices. Pour sauce into jug, serve with turkey.","images":[],"step":16},{"title":"Gravy option","description":"see Note 11. I personally love using the butter, but I understand if you feel the need for gravy!","images":[],"step":17}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-recipes","dietary","gluten-free-recipes","main-dishes","roasts","turkey-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_303938c20540', 'en', 'US', 'BAKED Chicken Meatballs with Spaghetti', 'Recipe VIDEO above. Golden brown on the outside, soft and juicy on the inside, these Baked Chicken Meatballs are lip smackingly delicious! Pass them around with ketchup at a gathering or make Spaghetti and Meatballs!', 'https://www.recipetineats.com/tachyon/2017/09/Baked-Chicken-Meatballs-2.jpg', 20, 25, 45, 4, '[{"id": "ing_chicken_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.25, "unit": "pack of 1kg"}}, {"id": "ing_bread", "quantity": {"value": 0.094, "unit": "loaf"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.25, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_basil", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_basil", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}]', '[{"ingredients":["500 g/1lb chicken mince (ground chicken), or turkey or pork (Note 1)","1/4 small white onion (, grated into the bowl)","1/2 cup panko breadcrumbs","1/3 cup grated parmesan","1 large garlic clove (, minced)","1/4 cup finely chopped parsley (or 2 tsp dried parsley or basil)","1 egg","1/4 tsp salt","1/2 tsp pepper","Olive oil spray (or olive oil)"],"purpose":"Meatballs:"},{"ingredients":["1 tbsp olive oil","1 garlic clove (, finely chopped)","3/4 small onion , finely chopped","800 g / 28 oz crushed tomato","1 cup / 250 ml water (swirl in tomato can to clean out)","Handful basil leaves (, torn, or 1 tsp dried herbs (e.g. Italian mix, oregano, thyme, basil))"],"purpose":"Pasta Sauce:"},{"ingredients":["250 g/ 1/2 lb spaghetti or other long strand pasta of choice (, cooked per packet)","Fresh basil (, optional)","Parmesan cheese"],"purpose":"Serving:"}]', '[{"description":"Preheat oven to 200C/390F (standard) or 180C/350F (fan/convection).","images":[],"step":1},{"description":"Place a rack on a tray, and spray the rack with oil.","images":[],"step":2},{"description":"Place Meatball ingredients in a bowl, mix well. Scoop up a heaped tablespoon, roll into a ball and place on the rack. Repeat with remaining mixture - should make 25 - 30. Tip: spray hands with oil or wet lightly with water.","images":[],"step":3},{"description":"Spray each ball well with oil, then bake for 25 minutes until golden brown. Give ''em a squeeze and you''ll see how soft they are!","duration":25,"images":[],"step":4},{"description":"Heat oil in a large skillet over medium high heat. Add garlic and onion, cook for 2 - 3 minutes until translucent. Add tomato and water, stir then turn heat down to medium. Simmer for 5 - 10 minutes, then season to taste with salt and pepper and stir through basil (or use dried herbs).","duration":2.5,"images":[],"step":5},{"description":"Cook pasta in a large pot of boiling water. Drain then return pasta to the same pot.","images":[],"step":6},{"description":"Add Sauce and meatballs, toss.","images":[],"step":7},{"description":"Serve, garnished with fresh basil and parmesan.","images":[],"step":8}]', '["egg","gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-mince-recipes","chicken-recipes","dinner-tonight","italian-recipes","main-dishes","meatball-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1a53a4bf3e58', 'en', 'US', 'Chicken with Mushroom Gravy', 'RECIPE VIDEO ABOVE. The mushroom gravy is to die for!! My tip is to use beef rather than chicken broth which sounds counter intuitive but it gives the gravy better flavour (not "beefy") and a deep brown gravy colour. Refer to the notes for using chicken broth instead.', 'https://www.recipetineats.com/tachyon/2017/09/Chicken-in-Mushroom-Gravy-6.jpg', 5, 15, 20, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.12, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["600 g / 1.2 lb chicken breasts, boneless skinless, (, 4 small ones (Note 1))","Salt and pepper","2 tsp olive oil","1 tbsp / 15g butter"],"purpose":"Chicken:"},{"ingredients":["2 tbsp / 30 g butter (, separated)","120 g / 4 oz mushrooms (, sliced)","1 garlic clove (, finely chopped (or minced))","1/4 cup / 35g flour (3 tbsp)","2 cups / 500 ml beef broth (Note 2 for chicken broth)"],"purpose":"Mushroom Gravy:"},{"ingredients":["Thyme or parsley"],"purpose":"Garnish (optional):"}]', '[{"description":"Place a plastic bag or cling wrap over the chicken and pound to even thickness 2cm / 4/5\" thick. Sprinkle both sides generously with salt and pepper.","images":[],"step":1},{"description":"Heat oil and melt 1 tbsp butter in a large skillet over high heat. Add chicken and cook for 3 minutes or until golden, then turn and cook the other side for 3 minutes. Transfer to plate, cover loosely with foil.","duration":3,"images":[],"step":2},{"description":"Add 1 tbsp butter to the skillet. Add mushrooms and cook for 3 minutes or until pretty golden.","duration":3,"images":[],"step":3},{"description":"Add remaining 1 tbsp butter and garlic. Cook for 1 minute until mushrooms are golden.","duration":1,"images":[],"step":4},{"description":"Turn heat DOWN to medium. Add flour and mix for 1 minute.","duration":1,"images":[],"step":5},{"description":"Add about 1/4 of the beef broth, mixing as you go. Once incorporated, add remaining broth gradually, mixing constantly. This is key to avoid lumps in gravy. Use a whisk if needed (works fine even with mushrooms in there) (Note 3 for beginner option).","images":[],"step":6},{"description":"Cook gravy for about 2 minutes or until it thickens to your taste - remember it will thicken more as it cools when serving. Adjust salt and pepper.","images":[],"step":7},{"description":"If you want, return chicken to the pan and turn to coat in gravy.","images":[],"step":8},{"description":"Place chicken on serving plates, top with gravy. Best served with mashed potato or similar to optimise the mushroom gravy experience!","images":[],"step":9}]', '["gluten","milk"]', '["low_calorie"]', '{"mealType":["main_course"],"cuisine":[],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","mushroom-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0bc4b51094ed', 'en', 'US', 'Homemade Cream of Chicken Soup recipe', 'Recipe VIDEO above. A homemade version of Cream of Chicken Soup, light years away from the canned stuff! This version is light on the veggies and chicken to make it like what you get in cans, but feel free to load it up with more. Consider adding noodles or rice too!', 'https://www.recipetineats.com/tachyon/2014/08/Cream-of-Chicken-Soup-4-2.jpg', 10, 10, 20, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_milk", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_frozen_peas", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 0.1, "unit": "loaf"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1 tbsp olive oil","50 g / 3.5 tbsp unsalted butter","½ cup / 75 g flour","1 garlic clove (, minced)","½ small brown onion (, finely chopped)","1 small carrot (, diced)","1/2 red capsicum/bell pepper (, finely chopped)","1 small celery stick (, diced)","2 cups / 500 ml chicken stock / broth (, preferably low sodium)","3 cups / 750 ml milk (, any fat %)","½ tsp salt","¼ tsp EACH garlic powder (, onion powder, dried thyme, black pepper (“Spices”))","3/4 cup frozen peas","1 cup cooked chicken (, diced or shredded)"]},{"ingredients":["2 slices white bread (, cut into cubes)","Olive oil spray","Salt"],"purpose":"Croutons"}]', '[{"description":"Heat oil in a large pot over medium high heat. Add onion and garlic and cook for 2 minutes until partly translucent but not browned.","duration":2,"images":[],"step":1},{"description":"Add carrots, celery and capsicum, cook for 1 minute to soften.","duration":1,"images":[],"step":2},{"description":"Add butter and melt. Then add flour and mix until incorporated, and stir constantly for 1 minute.","duration":1,"images":[],"step":3},{"description":"Add broth, mix until flour is incorporated, then add milk. Mix to combine, then add salt, Spices, chicken and peas.","images":[],"step":4},{"description":"Bring to simmer, mixing occasionally to stop bottom of sticking. As it heats, it will thicken – about 4 to 5 minutes. Don’t let it bubble.","images":[],"step":5},{"description":"Once thickened to your taste, adjust salt and pepper. Ladle into bowls and serve garnished with croutons and fresh thyme if desired.","images":[],"step":6},{"title":"Croutons","description":"Spray croutons generously with oil, sprinkle with salt, then bake for 5 minutes at 180C/350F or until golden and crunchy.","duration":5,"images":[],"step":7}]', '["gluten","milk"]', '["low_calorie"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","most-popular","quick-and-easy","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b87579ea2162', 'en', 'US', 'San Fran Chicken Salad with Yoghurt Ranch Dressing', 'Inspired by Souvla, a popular restaurant in San Francisco, this is one of the best chicken salads I''ve ever had. Yes there are lots of components - but it is worth it! Yoghurt is a terrific marinade for chicken - tenderises, adds juiciness and infuses with flavour. It''s satisfying, filling, fresh, great textures, the dressing is awesome. Great show off salad to serve to friends! VIDEO below.', 'https://www.recipetineats.com/tachyon/2017/08/San-Fran-Chicken-Salad_-5.jpg', 30, 5, 35, 2, '[{"id": "ing_greek_yogurt", "quantity": {"value": 0.3, "unit": "tub of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_chicken_breast", "quantity": {"value": 200.0, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_oil", "quantity": {"value": 0.5, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 1.25, "unit": "pack of 1kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_vinegar", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_kale_torn_into_bite_size_pieces", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_oranges", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 12.0, "unit": "head"}}, {"id": "ing_fennel_shaved_or", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_handful_snow_pea_sprouts_optional", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}]', '[{"ingredients":["1 cup Greek yoghurt, preferably full fat","1/2 - 1 tbsp olive oil","1 small garlic clove, minced","1/4 tsp EACH dried dill, parsley, chives, onion powder, garlic powder, salt, black pepper (Note 1)","1/2 tsp white sugar","Squeeze of lemon juice, to taste"],"purpose":"Yoghurt Ranch Dressing:"},{"ingredients":["200 - 250 g / 7 - 8 oz chicken breast, halved horizontally","1 tbsp lemon juice","1 small garlic clove, minced","1/2 - 1 tbsp oil, for cooking"],"purpose":"Chicken & Marinade:"},{"ingredients":["1/2 red onion, halved then finely sliced","1/2 tsp salt","1 tsp white sugar","1/2 cup white wine vinegar, or cider vinegar"],"purpose":"Pickled Onion:"},{"ingredients":["3 cups kale, torn into bite size pieces (Note 2)","1 - 2 tsp extra virgin olive oil","Pinch of salt"],"purpose":"Marinated Kale:"},{"ingredients":["1 grapefruit or orange","4 cups cos lettuce, romaine or other crispy lettuce, torn or cut into bite size pieces","1/2 fennel, shaved (0.5 mm / 1/5\" thickness) or finely sliced","Handful snow pea sprouts, optional","1/4 cup shredded parmesan"],"purpose":"Salad:"}]', '[{"description":"Mix the Yoghurt Ranch Dressing ingredients in a bowl. Adjust olive oil + lemon juice to taste.","images":[],"step":1},{"title":"Chicken Marinade","description":"Transfer 1/4 cup of Yoghurt Ranch Dressing into a bowl with the chicken. Add lemon juice and garlic. Toss to coat, marinate for 1 hr - 24 hours.","duration":60,"images":[],"step":2},{"description":"Place Pickled Onion ingredients in a bowl, toss to coat. Set aside for 1 hour+ or until onion is softened (if in a rush, make sure the onion is finely sliced = faster pickle).","images":[],"step":3},{"description":"Place kale in a large bowl, drizzle with oil then sprinkle with salt. Use your fingers to massage the oil onto the leaves - you want to ensure every part of the kale is coated in oil. Set aside for 30 minutes or until kale is softened.","duration":30,"images":[],"step":4},{"title":"Segment the grapefruit or orange","description":"watch the video. Do this over a bowl to catch juices. Squeeze all remaining juice out of the membrane after segmenting.","images":[],"step":5},{"title":"Pour juices into the Dressing. Mix","description":"it should now be more of a Dressing consistency.","images":[],"step":6},{"title":"Cook Chicken","description":"Heat oil in a skillet over high heat. Add chicken and cook for 2 minutes on each side, until nicely charred. Transfer onto plate, cover loosely with foil and rest for 3 minutes. Slice thinly.","duration":2,"images":[],"step":7},{"title":"Assemble Salad","description":"Add lettuce, fennel and chicken into the kale bowl. Spoon over most of the dressing to coat everything lightly, then toss well. Transfer into a serving bowl.","images":[],"step":8},{"description":"Scatter over grapefruit, onion (not the liquid), top with a handful of snow pea sprouts, sprinkle over parmesan. Drizzle over remaining dressing to taste. Serve!","images":[],"step":9}]', '["milk"]', '["gluten_free"]', '{"mealType":["main_course"],"cuisine":[],"categories":["chicken-breast-recipes","chicken-recipes","salad-recipes-main-course"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7d5fd145317e', 'en', 'US', 'Lemon Parmesan Cabbage Salad with Grilled Chicken', 'A terrific cabbage salad tossed with a parmesan and lemon dressing, sweet pops of peas, subtle freshness from mint and topped with a simple, super tasty marinated chicken. Something a bit different, yet still so familiar! Skip the chicken for a super tasty cabbage salad. MARINATING TIME: 30 minutes minimum', 'https://www.recipetineats.com/tachyon/2017/05/Lemon-Parmesan-Cabbage-Salad-with-Chicken-5.jpg', 10, 10, 20, 3, '[{"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.25, "unit": "bottle of 250ml"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_cabbage", "quantity": {"value": 5.0, "unit": "head"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_mint", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 0.5, "unit": "pack of 200g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}]', '[{"ingredients":["2 small chicken breasts (150g/5oz each), 2 cm / 4/5\" thick (or 1 large, cut in half horizontally)","1/4 cup soy sauce","2 tbsp lemon juice","1 tsp dried oregano","1 garlic clove (, minced)","Black pepper","2 tsp olive oil"],"purpose":"Grilled Chicken:"},{"ingredients":["5 heaped cups shredded green cabbage","1/2 red onion (, finely sliced)","1 cup peas (fresh is always best, but I usually use frozen)","1 cup fresh mint leaves (lightly packed)","100 g / 3.5 oz freshly grated parmesan (about 1 heaped cup) (Note 2)","2 tbsp fresh lemon juice","1/4 cup / 60 ml extra virgin olive oil (good quality counts here!)","Black pepper"],"purpose":"Cabbage Salad:"}]', '[{"description":"If the chicken is much thicker than 2cm / 4/5\", pound lightly or cut in half horizontally.","images":[],"step":1},{"description":"Place the Grilled Chicken ingredients in a ziplock bag and set aside for 30 minutes to overnight.","duration":30,"images":[],"step":2},{"description":"Use the oil to brush the grill, or heat oil in a skillet over medium high heat. Cook the chicken for 4 minutes on each side, then remove onto a plate. Cover loosely with foil, rest for 5 minutes, then slice thinly.","duration":4,"images":[],"step":3},{"description":"Cook the peas in boiling water (or steam), drain then rinse under cold tap water to cool down.","images":[],"step":4},{"description":"Place cabbage, peas, mint and onion in a bowl. Add parmesan, lemon juice, olive oil, and pepper.","images":[],"step":5},{"description":"Toss well. Adjust salt to taste, add more parmesan if desired.","images":[],"step":6},{"description":"Transfer to serving plates, top with chicken. Garnish with more parmesan and black pepper, then serve.","images":[],"step":7}]', '["gluten","milk","soy"]', '[]', '{"mealType":["main_course"],"cuisine":[],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","quick-and-easy","salad-recipes-main-course"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0ce59a76942f', 'en', 'US', 'Baked Balsamic Chicken', 'Recipe video above! No marinating required, just mix together a simple sauce, pour it over the chicken and bake. You will be amazed how incredible it tastes - and how sticky they are! PS If using the recipe scaler (hover over Servings), please read notes.', 'https://www.recipetineats.com/tachyon/2017/04/Balsamic-Baked-Chicken-4.jpg', 5, 50, 55, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_balsamic_vinegar", "quantity": {"value": 0.25, "unit": "bottle of 250ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.15, "unit": "bottle of 250ml"}}, {"id": "ing_honey", "quantity": {"value": 0.125, "unit": "jar of 500g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}]', '[{"ingredients":["1 kg / 2 lb chicken thighs (5 pieces, bone in, skin on), or drumsticks or wings (any combination) (Note 1)"]},{"ingredients":["1/4 cup (65 ml) balsamic vinegar","2 1/2 tbsp / 50 ml soy sauce (, all purpose or light (not dark soy sauce))","1/4 cup (85 g / 65 ml) honey","1/4 cup (45g) brown sugar (, loosely packed (Note 2))","2 garlic cloves, minced (or 1 1/2 tsp garlic paste from jar)"],"purpose":"Sauce:"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Line a baking dish with foil and baking / parchment paper.","images":[],"step":2},{"description":"Mix together Sauce in a bowl.","images":[],"step":3},{"description":"Place chicken in baking dish, skin side down for thighs and wings. Make sure the pan is big enough so the chicken is squished up next to each other (sauce may not reduce enough), but not so large that there is more than 4\"/10 cm between every piece of chicken (sauce may reduce too much).","images":[],"step":4},{"description":"Pour over Sauce. Bake 30 minutes. Turn chicken over, spoon over sauce.","images":[],"step":5},{"description":"Bake 20 minutes or until chicken is cooked through. The Sauce should have thickened.","images":[],"step":6},{"description":"Stand for 5 minutes, then spoon Sauce over chicken and serve.","duration":5,"images":[],"step":7}]', '["gluten","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_edc77abe1b6b', 'en', 'US', 'One Pot Italian Chicken & Orzo / Risoni Pasta', 'RECIPE VIDEO ABOVE. A super tasty and quick meal all made in one pot! Chicken infused with Italian flavours and a rich tomato basil orzo / risoni pasta. Refer to the notes for how to skip the marinating time and also how to cook the chicken WITH the risoni. Feel free to add or substitute the capsicum / bell peppers in this!', 'https://www.recipetineats.com/tachyon/2017/01/One-Pot-Italian-Chicken-and-Tomato-Basil-Risoni.jpg', 10, 25, 35, 4, '[{"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_italian_herb_mix", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_chicken_breast", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.45, "unit": "pack of 500g"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}, {"id": "ing_basil", "quantity": {"value": 0.1, "unit": "bunch"}}]', '[{"ingredients":["2 tbsp white wine vinegar","1 tbsp olive oil","1 tsp Dijon mustard","1 tsp Italian herb mix (or make your own with basil, parsley, oregano)","1 garlic clove (, minced)","1/2 tsp salt + black pepper"],"purpose":"Marinade"},{"ingredients":["1 tbsp olive oil","4 x 110 - 120g/4oz chicken breasts (, skinless and boneless (Note 1))"],"purpose":"Chicken"},{"ingredients":["1/2 tbsp olive oil (if required)","1 small onion (, finely chopped (brown, white, yellow))","1 garlic clove (, minced)","1 red capsicum / bell pepper (, chopped)","1 1/2 cups risoni / orzo pasta (Note 2)","400 g / 14 oz can crushed tomato","3 cups chicken stock / broth","1 tsp Italian herb mix","Pinch of red pepper flakes (chilli flakes) (optional)","Salt and pepper","1/4 cup (3 tbsp) grated parmesan cheese (optional)","1 cup basil leaves"],"purpose":"Risoni"}]', '[{"description":"Mix Marinade ingredients together in a large bowl. Add chicken and mix to coat. Marinate for 1 hour - 24 hours (See Note 3 to skip marinating).","images":[],"step":1},{"description":"Heat oil in skillet over medium heat. Add chicken and cook for 4 minutes on each side, or until cooked. Transfer to a plate and cover with foil to keep warm while resting.","duration":4,"images":[],"step":2},{"description":"Turn heat up to medium high. Add oil if required.","images":[],"step":3},{"description":"Add onion and garlic, cook for 2 minutes. Add capsicum and cook for 1 minute or until onion is translucent.","duration":2,"images":[],"step":4},{"description":"Add risoni, tomato, chicken stock, Italian herbs, red pepper flakes, salt and pepper. Mix and bring to simmer, then lower heat to medium low or so it simmers gently.","images":[],"step":5},{"title":"Cook for 9","description":"10 minutes, stirring frequently (otherwise it will stick).","duration":9.5,"images":[],"step":6},{"description":"Take it off the stove when the risoni is just cooked (touch under is ok, finishes cooking in residual heat very quickly). It should still be saucy (see video).","images":[],"step":7},{"title":"Stir through parmesan and basil","description":"excess liquid will evaporate in this step.","images":[],"step":8},{"description":"Spoon risoni into serving bowls, top with chicken. Serve with extra parmesan and basil.","images":[],"step":9}]', '["gluten","milk","mustard"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["chicken-breast-recipes","chicken-recipes","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_31dcc08f179e', 'en', 'US', 'Oven Baked Chicken Quesadillas', 'This is how to make multiple Quesadillas in one batch, rather than making them one by one on the stove! They are crispy and stuffed with Fajita flavoured chicken, onion, capsicum/bell peppers and of course cheese. Use this technique to make quesadillas with anything you want - just ensure you cool the filling. See recipe VIDEO below the recipe to see how crispy these are!', 'https://www.recipetineats.com/tachyon/2016/12/Baked-Chicken-Quesadillas-7.jpg', 15, 16, 31, 4, '[{"id": "ing_chicken", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 5.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_tortillas", "quantity": {"value": 4.0, "unit": "pack of 8"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}]', '[{"ingredients":["400 g / 14 oz chicken (, cut into small bite size pieces (thigh, breast or tenderloin))","1 tsp cumin powder","1 tsp garlic powder (or sub with onion powder)","1/2 tsp cayenne pepper (or adjust to taste)","1 tsp paprika powder","1/2 tsp salt + black pepper","1 tbsp olive oil"],"purpose":"Chicken"},{"ingredients":["1 tbsp olive oil","1/2 small onion (, diced (brown, white, yellow))","1 garlic clove (, minced)","1 red capsicum / bell pepper (, diced)","1 green capsicum / bell pepper (, diced)"],"purpose":"Filling"},{"ingredients":["4 flour tortillas (20cm/8\")","Olive oil spray","1 cups grated cheese, or more to taste (tasty, cheddar, Monterey Jack, Pepper Jack or other melting cheese of choice) (Note 1)"],"purpose":"Quesadillas"}]', '[{"description":"Place Chicken ingredients in a bowl and mix to coat chicken.","images":[],"step":1},{"description":"Heat oil in skillet over high heat. Add onion and garlic, cook for 1 minute. Then add capsicum and cook for 2 minutes until starting to soften. Transfer into bowl.","duration":1,"images":[],"step":2},{"description":"Return skillet to the stove. Add chicken and cook until browned. Add to same bowl. Set aside until the filling cools (to speed it up, cover and refrigerate, and/or spread out on plate).","images":[],"step":3},{"description":"Preheat oven to 220C / 430F (standard) or 200C/390F (fan / convection).","images":[],"step":4},{"description":"Spray baking tray lightly with olive oil. Heat in the oven while you assemble the quesadillas.","images":[],"step":5},{"description":"Divide the filling between the tortillas, covering half the surface. Top with cheese. Fold in half and press down gently but firmly.","images":[],"step":6},{"description":"Remove baking tray from oven. Transfer quesadillas onto tray (you should hear a soft sizzle).","images":[],"step":7},{"description":"Bake for 8 minutes. Then turn the quesadillas (over the folded edge) then press down with the egg flip. Bake for a further 8 minutes or until the surface is crispy.","duration":8,"images":[],"step":8},{"description":"Remove from oven and serve immediately!","images":[],"step":9}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Tex-Mex"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","mexican-recipes","most-popular","quesadillas","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1b53ba108fe9', 'en', 'US', 'Creamy Chicken and Bacon Pasta', 'Recipe video above. This is for those days when you just need a really, really great creamy pasta but you want to keep it simple. The pops of bacon in this is sooo good, and the sauce is utterly luxurious and unapologetically rich, saucier than a classic Alfredo.But, for those days when you want to go all out, make the Creamy Chicken Pasta of My Dreams (it''s more loaded, and name-worthy!).', 'https://www.recipetineats.com/tachyon/2016/12/Creamy-Chicken-Bacon-Pasta-4.jpg', 5, 15, 20, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.34, "unit": "pack of 500g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.34, "unit": "pack of 500g"}}, {"id": "ing_bacon", "quantity": {"value": 5.0, "unit": "pack of 200g"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.17, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}]', '[{"ingredients":["6 oz / 180 g fettuccine (or other long strand pasta)","3/4 cup pasta cooking water (, scoop out just before draining)","5 -7 oz / 150 - 200 g bacon (, chopped)","6 oz / 180g chicken breast (, cut in half horizontally (1 large))","1/4 tsp each salt and pepper (, for seasoning chicken)"]},{"ingredients":["1 tbsp (15 g) unsalted butter","2 garlic cloves (, finely minced)","1/2 small onion (, finely chopped (brown, white or yellow))","3/4 cup heavy cream / thickened cream (or any full fat cream)","1/4 tsp each salt and pepper (, for sauce)","1/2 cup finely shredded parmesan (or 1/4 cup store bought grated) (Note 2)"],"purpose":"Creamy pasta sauce"},{"ingredients":["Fresh parsley","Parmesan"],"purpose":"To Serve"}]', '[{"description":"Cook pasta per packet minus 2 minutes, reserve 1 cup pasta water before draining. Cook bacon, then chicken, sauté garlic and onion, simmer with cream, 3/4 cup pasta water, parmesan, salt and pepper. Toss with pasta 1 1/2 minutes, TASTE to check for salt. Serve with parmesan.","images":[],"step":1},{"title":"Cook pasta","description":"Bring a large pot of salted water to boil. Add pasta and cook for time per packet MINUS 2 minutes (finishes cooking in Sauce).","images":[],"step":2},{"title":"RESERVE water (important!)","description":"SCOOP OUT 1 cup (250ml) of pasta cooking water, then drain.","images":[],"step":3},{"title":"Cook bacon","description":"Meanwhile, heat the oil in a non-stick pan and cook bacon until golden. Remove and drain on paper towels, reserve bacon fat in pan.","images":[],"step":4},{"title":"Cook chicken","description":"Season chicken on both sides with the salt and pepper. Cook in the bacon fat for 2 minutes on each side. Remove, then cut into thick slices when cool enough to handle (do this while sauce is simmering).","duration":2,"images":[],"step":5},{"description":"Wipe pan (optional) using paper towels to keep sauce pretty and white, and for a buttery clean tasting sauce rather than very bacon-y (Note 3).","images":[],"step":6},{"title":"Sauté onion","description":"Over medium heat using the same pan, melt the butter. Add garlic and onion, cook for 3 - 4 minutes until onion is light golden and soft.","duration":3.5,"images":[],"step":7},{"title":"Make sauce","description":"Add cream, about 3/4 cup pasta water, parmesan, salt and pepper. Stir, then simmer for 2 minutes until it reduces slightly - the sauce will still be a too thin, don''t worry, it thickens in the next step.","duration":2,"images":[],"step":8},{"description":"Add pasta and toss gently in the sauce for about 1 1/2 minutes, still on the stove. The sauce will thicken and coat the pasta rather than pooling in the pan. Do this step until you get the sauce consistency you want. If your sauce gets too thick, add a splash of pasta water.","images":[],"step":9},{"title":"Toss and taste","description":"Toss through bacon and chicken. Taste and add more salt if needed (depends on bacon saltiness).","images":[],"step":10},{"title":"Serve","description":"Serve immediately, garnished with parmesan and parsley!","images":[],"step":11}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d510a78a7505', 'en', 'US', 'Honey Mustard Chicken', 'This is a homemade version of the popular Honey Mustard simmer sauces sold at supermarkets. The Honey Mustard Sauce is slightly tangy, sweet and beautifully creamy. Great for chicken, pork, turkey and fish. **ADJUST SERVINGS by using the slider!**', 'https://www.recipetineats.com/tachyon/2016/08/Honey-Mustard-Chicken_2.jpg', 7, 10, 17, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.037, "unit": "jar of 400g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.013, "unit": "pack of 400g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_chicken", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.188, "unit": "jar of 200g"}}, {"id": "ing_honey", "quantity": {"value": 0.125, "unit": "jar of 500g"}}, {"id": "ing_mustard", "quantity": {"value": 0.188, "unit": "jar of 200g"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["700 g / 1.4 lb chicken tenderloin or chicken breast cut into thick strips (Note 1)","Salt and pepper"]},{"ingredients":["2 tbsp flour","1 tsp garlic powder"],"purpose":"Seasoning (optional – Note 2)"},{"ingredients":["1 tbsp mayonnaise (Note 3)","1 tsp cornstarch / cornflour or 2 tsp flour"],"purpose":"Thickener"},{"ingredients":["1 1/2 tbsp + 1/2 tbsp olive oil","2 cloves garlic (minced)","1 cup chicken broth / stock (250ml)","1/4 cup Dijon mustard (70g)","1/4 cup honey (85g)"],"purpose":"Sauce"},{"ingredients":["1 - 2 tbsp wholegrain mustard, adjust to taste","2 tsp sprigs thyme or 1/2 dried thyme (Note 4)","Fresh parsley, finely chopped"],"purpose":"Optional Extras (I used these)"}]', '[{"description":"Sprinkle chicken with salt and pepper, then toss with Seasoning if using.","images":[],"step":1},{"title":"Thickener","description":"In a small bowl, mix together the mayonnaise and flour.","images":[],"step":2},{"description":"Heat 1 1/2 tbsp oil in a skillet over medium high heat. Add chicken and cook for 2 minutes on each side or until golden. Remove onto a plate.","duration":2,"images":[],"step":3},{"description":"Reduce heat to medium. Add remaining oil in the middle of the skillet and put garlic straight onto the puddle of oil. Sauté for 20 seconds or until golden (don''t let it burn).","duration":0.3333333333333333,"images":[],"step":4},{"description":"Add chicken broth, bring to simmer, scraping the bottom of the fry pan.","images":[],"step":5},{"description":"Whisk in Dijon Mustard and honey, then whisk in Thickener (make sure you scrape it all in).","images":[],"step":6},{"description":"Add thyme and wholegrain mustard, if using.","images":[],"step":7},{"title":"Cook for 1","description":"2 minutes or until starting to thicken. Adjust salt and pepper to taste.","duration":1.5,"images":[],"step":8},{"description":"Return chicken and any juices pooled on the plate into the sauce. Turn to coat and reheat through - about 1 1/2 minutes - or until sauce is thickened to your taste.","images":[],"step":9},{"description":"Serve on mashed potato, garnished with parsley, with a simple side salad.","images":[],"step":10}]', '["gluten","mustard"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_74fb2f46ddf5', 'en', 'US', 'Chicken & Mushroom Risotto', 'The new way to make risotto that comes out just as creamy as the traditional method: no heating up the broth, no need to add it gradually and no need to stir constantly! The bacon garnish is optional but honestly, it is so worth the effort. Also, I use the bacon fat in the pot to cook the chicken and mushrooms. Why waste the free flavour? :)', 'https://www.recipetineats.com/tachyon/2016/08/Chicken-Mushroom-Risotto_4.jpg', 10, 40, 50, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_bacon", "quantity": {"value": 0.354, "unit": "pack of 200g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.34, "unit": "kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.369, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_arborio_rice", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.34, "unit": "kg"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 tsp - 1 tbsp olive oil","2.5 oz / 75 g bacon (preferably streaky / fatty) (optional)","12 oz / 350 g chicken thigh fillets (, cut into bite size pieces)","13 oz / 400 g mushrooms (, sliced (I use Swiss brown))","2 tbsp / 30 g unsalted butter","2 garlic cloves (, minced)","1 onion (, finely diced (brown, white, yellow))","1/2 cup / 125 ml white wine (optional - sub with water or chicken broth)","1 1/4 cups / 250 g arborio risotto rice (, uncooked (Note 1))","4 cups / 1 litre chicken broth/stock"]},{"ingredients":["1/2 cup / 35 g freshly grated parmesan cheese","1 - 3 tbsp / 15 - 50 g unsalted butter","Freshly chopped parsley"],"purpose":"Finishing"}]', '[{"description":"Heat 1 tsp oil in a pot or skillet (Note 2) over high heat. Add bacon and cook until golden. Transfer to small microwave-proof bowl.","images":[],"step":1},{"title":"Leave about 1 tbsp bacon fat in pot","description":"discard excess. Add chicken* and cook until browned and cooked through. Transfer to separate bowl.","images":[],"step":2},{"description":"Add mushrooms* and cook until light golden. Add to bowl with chicken.","images":[],"step":3},{"description":"Turn heat down to medium and return pot to the stove. Add butter, and melt. Add garlic and onion. Sauté for 3 minutes or until softened.","duration":3,"images":[],"step":4},{"description":"Turn heat up to high, add rice and stir until the grains become partially translucent - no longer than 1 minute. (Note 3)","images":[],"step":5},{"description":"Add wine and cook, scraping the bottom of the pot (to get any brown bits), until the alcohol smell evaporates ~ 2 minutes.","images":[],"step":6},{"description":"Turn heat down to medium low. Add about 3 cups of stock. Then leave it, uncovered, stirring just once or twice, until most of the liquid has been absorbed.","images":[],"step":7},{"description":"Check firmness of rice and add 1/2 cup of stock at a time, stirring in between until absorbed, until the rice is cooked to your taste. (Note 4)","images":[],"step":8},{"description":"Add chicken and mushrooms back into the risotto towards the end, just to heat through.","images":[],"step":9},{"description":"Right at the end when the risotto is ready, add a splash of chicken broth to make the risotto to make it slightly soupy, then take it off the stove.","images":[],"step":10},{"title":"KEY STEP","description":"Add butter (the more the better!) and parmesan, then stir vigorously (activates the starch and makes it super creamy). The excess liquid will evaporate quickly, so add more if you want a soupier risotto, like what you get at posh restaurants.","images":[],"step":11},{"description":"Serve IMMEDIATELY!! (Note5) Garnish with reheated bacon, and extra parmesan and parsley if desired.","images":[],"step":12}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","italian-recipes","main-dishes","mushroom-recipes","quick-and-easy","risotto-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d4d8f52d5211', 'en', 'US', 'Bacon Wrapped Chicken', 'Juicy chicken wrapped in bacon, baked to golden perfection and slathered in gorgeous bacon juices! The brown sugar makes the bacon extra tasty and the Seasoning gives the chicken even more flavour. Simple and ridiculously delicious!', 'https://www.recipetineats.com/tachyon/2016/08/Bacon-Wrapped-Chicken_2.jpg', 15, 25, 40, 4, '[{"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_flour", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 0.6, "unit": "pack of 200g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.005, "unit": "L"}}]', '[{"ingredients":["1 tsp garlic powder","1 tsp paprika","1/2 tsp cayenne pepper (or sub with more paprika)","1 tbsp flour","1/2 tsp salt","Black pepper"],"purpose":"Seasoning"},{"ingredients":["4 large chicken thigh fillets (about 5oz / 150g each), cut in half (Note 1)","8 pieces bacon (, streaky (Note 2))","2 tbsp brown sugar","1 tsp olive oil (optional)"],"purpose":"Chicken"}]', '[{"description":"Preheat oven to 200C/390F (fan forced / convection) (Note 3)","images":[],"step":1},{"description":"Line tray with baking paper.","images":[],"step":2},{"description":"Combine Seasoning in a small bowl. Place brown sugar in a separate bowl.","images":[],"step":3},{"description":"Coat chicken in Seasoning, shaking off excess. Place on one end of bacon and roll up, finishing with the seam side down. Repeat with remaining chicken.","images":[],"step":4},{"title":"Coat chicken in sugar","description":"use your fingers to rub it on if required. Place on baking tray.","images":[],"step":5},{"description":"Drizzle with olive oil (helps make it brown faster, optional)","images":[],"step":6},{"description":"Bake for 25 minutes. If the bacon is not golden enough for your taste, switch on the broiler for a few minutes.","duration":25,"images":[],"step":7},{"description":"Brush the juices on the tray onto the bacon to make it glossy and juicy. Serve on mashed potatoes, drizzled with extra pan juices if desired!","images":[],"step":8}]', '["gluten"]', '["high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c02f2a8030e5', 'en', 'US', 'Chicken in White Wine Cream Sauce', 'Chicken in a creamy white wine sauce - comfort food and it''s finest! So simple to make, the key to this recipe is the white wine which transforms into an incredible broth by braising the chicken slowly in it so the chicken is incredibly tender. This is very French-country-chic! :)', 'https://www.recipetineats.com/tachyon/2016/07/Chicken-with-Bacon-White-Wine-Cream-Sauce_6.jpg', 10, 75, 85, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 1.134, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_bacon", "quantity": {"value": 0.709, "unit": "pack of 200g"}}, {"id": "ing_wine", "quantity": {"value": 0.667, "unit": "bottle of 750ml"}}, {"id": "ing_chicken", "quantity": {"value": 1.134, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 tbsp olive oil","2.5 lb / 1.2 kg chicken pieces (, bone in thigh & drumsticks are ideal (Note 1))","1 tbsp / 15g / 0.5 oz butter","3 garlic cloves (, crushed)","1 onion (brown, white, yellow), finely chopped (~1 cup)","5 oz / 150 g bacon (, diced)","2 cups / 500 ml dry white wine (Note 2)","1 cup / 250 ml chicken broth / stock or water","2 tsp fresh thyme leaves (or 1 tsp dried)","3/4 cup / 185 ml cream (pouring or heavy cream, but not low fat cream)"]},{"ingredients":["Finely chopped parsley"],"purpose":"Garnish"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Season chicken with salt and pepper. Heat oil in an ovenproof skillet (with lid) over high heat. Add chicken skin side down and cook until golden brown, then turn and cook the other side for 1 minute. Remove chicken from skillet. Drain excess fat from skillet (do not wipe).","duration":1,"images":[],"step":2},{"description":"Reduce heat to medium high. Melt butter then add garlic and onion. Cook for 3 minutes until softened, then add bacon. Cook until golden.","duration":3,"images":[],"step":3},{"description":"Add wine. Bring to simmer, scraping the bottom of the skillet to mix the brown bits into the liquid. Simmer for 2 minutes.","duration":2,"images":[],"step":4},{"description":"Add chicken broth, thyme and return chicken to the skillet, skin side up. Cover with lid or foil, then transfer to the oven. Bake for 60 minutes, covered, then remove the lid and bake for a further 15 minutes to recrisp the skin. The chicken should be very tender.","duration":60,"images":[],"step":5},{"description":"Remove chicken or move to side. Stir cream into sauce and season with salt and pepper to taste.","images":[],"step":6},{"description":"Garnish with plenty of parsley. Serve with creamy mashed potatoes. Mine are pictured with Glazed Carrots.","images":[],"step":7}]', '["milk"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["French-style"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","one-pot-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_fcc52bc66bbc', 'en', 'US', 'Sun Dried Tomato, Spinach & Cheese Stuffed Chicken Breast', 'Chicken breast slathered with an Italian dressing then stuffed with sun dried tomato, spinach and cheese. The chicken breast stays beautifully juicy because it cooks faster than whole chicken breast, even though this is stuffed. Also the juices from the sun dried tomato, cheese and Italian dressing baste the chicken as it roasts!', 'https://www.recipetineats.com/tachyon/2016/06/Sun-Dried-Tomato-Stuffed-Chicken-Breast_5.jpg', 5, 20, 25, 2, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.17, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.28, "unit": "pack of 125g"}}, {"id": "ing_spinach", "quantity": {"value": 1.0, "unit": "bag of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["6oz/180g small chicken breasts (2 pieces), boneless and skinless","1/2 cup sun dried tomato (oil packed. Use enough to cover the chicken, cut into strips)","4 slices mozzarella cheese (or other melting cheese of choice)","leaves Handful of spinach","2 tsp olive oil"]},{"ingredients":["1 tbsp Dijon Mustard","1 tbsp white wine vinegar or lemon juice","1/2 tsp sugar, any","2 tsp olive oil","1/2 tsp EACH Italian mixed herbs and red pepper flakes (Note 1)","Salt & pepper"],"purpose":"Italian Dressing"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Whisk together the Italian Dressing ingredients in a bowl. It will be thicker than salad dressing.","images":[],"step":2},{"description":"Cut a pocket into each chicken breast, taking care not to cut all the way though.","images":[],"step":3},{"description":"Coat the chicken (inside and out) with the Italian Dressing.","images":[],"step":4},{"description":"Place chicken on work surface. Stuff with sun dried tomato, top with cheese then finish with spinach leaves. Just stuff in as much as you can.","images":[],"step":5},{"description":"Seal with toothpicks (just stick them in on the diagonal - see photo in post).","images":[],"step":6},{"description":"Heat oil in an ovenproof skillet over high heat. Add chicken and cook for 1 1/2 minutes on each side, or until golden.","images":[],"step":7},{"description":"Transfer to oven and cook for 15 minutes, or until cheese is melted and bubbly and chicken is cooked through. Rest for 3 minutes before serving, drizzled with the juices in the skillet.","duration":15,"images":[],"step":8}]', '["milk","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ace302a5f57e', 'en', 'US', 'Hawaiian Chicken Salad', 'A giant salad loaded with the tropical flavours of Hawaii! This recipe is based on the marinade for these Hawaiian Chicken Skewers I shared a few weeks ago - see note 1 for how to REUSE the marinade for this recipe. This recipe also uses leftover Coconut Lime Cilantro/Coriander Rice that I shared as a side for the skewers.', 'https://www.recipetineats.com/tachyon/2016/06/Hawaiian-Chicken-Salad-Lime-Dressing_3.jpg', 15, 10, 25, 2, '[{"id": "ing_marinade", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.208, "unit": "can of 400ml"}}, {"id": "ing_pineapple", "quantity": {"value": 0.25, "unit": "unit"}}, {"id": "ing_tomato", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_lime", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_chicken", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_chicken_breast", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 0.188, "unit": "can of 400g"}}, {"id": "ing_pineapple", "quantity": {"value": 0.25, "unit": "unit"}}, {"id": "ing_lettuce", "quantity": {"value": 4.0, "unit": "head"}}, {"id": "ing_avocado", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 1.25, "unit": "pack of 1kg"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 0.3, "unit": "punnet of 250g"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_dressing", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_ime_juice", "quantity": {"value": 0.25, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["Marinade ((Note 1):)","1/3 cup coconut milk (from a can)","1/4 cup pineapple juice (from can, save pineapple pieces)","1 tbsp tomato sauce/ketchup","1 tbsp soy sauce","Zest of 1 lime","2 garlic cloves (, minced)","1/4 tsp EACH onion powder (, cumin, paprika, ginger powder, salt)","Chicken & Salad:","1/2 tbsp olive oil","1 large chicken breast (, halved horizontally)","1/2 cup corn","1/2 - 3/4 cup pineapple pieces (from can)","4 - 6 cups chopped lettuce","1/2 avocado (, cut into wedges)","1/2 red onion (, finely sliced)","1/2 cup cherry tomatoes (, halved)","1 small carrot, finely shredded","1 - 1 1/2 cups Coconut Lime Cilantro / Coriander Rice (Note 2)","Dressing:","1 1/2 tbsp lime juice","2 1/2 tbsp olive oil","2 tbsp finely chopped cilantro/coriander","1/2 garlic minced","1/2 tsp sugar or honey","1/4 tsp salt","Black pepper"]}]', '[{"description":"Mix together Marinade ingredients, marinate chicken for minimum 3 hours, preferably overnight.","images":[],"step":1},{"description":"Shake Dressing ingredients together in a jar, set aside for at least 15 minutes.","images":[],"step":2},{"description":"Heat oil in a non stick skillet over high heat (or BBQ). Add chicken and cook each side for 3 minutes or until golden. Remove and cover loosely with foil for 5 minutes, then slice thickly.","duration":3,"images":[],"step":3},{"description":"Sear 1/2 cup pineapple pieces and corn in the skillet until golden.","images":[],"step":4},{"description":"Pile salad ingredients on a platter and top with sliced chicken. Drizzle over Dressing. Serve and pretend you''re in Hawaii!","images":[],"step":5}]', '["gluten","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner","lunch"],"cuisine":["Hawaiian"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","gluten-free-recipes","most-popular","salad-recipes-main-course","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1accca9710b5', 'en', 'US', 'Oven Fried Parmesan Baked Chicken Tenders', 'These oven fried chicken tenders TRULY come out just like they''ve been fried! They are a beautiful golden brown all over and super crunchy. Make these with chicken tenderloins or cut chicken breast into tenderloin length strips! This is the parmesan flavoured version of these Truly Golden Crunchy Baked Chicken Tenders I shared last year.', 'https://www.recipetineats.com/tachyon/2016/06/Parmesan-Baked-Chicken-Tenders_3.jpg', 15, 15, 30, 3, '[{"id": "ing_bread", "quantity": {"value": 0.188, "unit": "loaf"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.037, "unit": "jar of 400g"}}, {"id": "ing_mustard", "quantity": {"value": 1.0, "unit": "jar of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chicken", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}]', '[{"ingredients":["1 cup panko breadcrumbs (Note 1)","Olive oil spray","1/2 cup grated parmesan cheese (, store bought (Note 2))"],"purpose":"Breadcrumb"},{"ingredients":["1 egg","1 tbsp mayonnaise* (I use whole egg mayonnaise)","1½ tbsp dijon mustard* (or any other mustard of choice)","1 garlic clove (, minced*)","2 tbsp plain flour","Salt & pepper"],"purpose":"Batter"},{"ingredients":["500 g /1 lb chicken tenderloins (or chicken breast cut into ⅔\" / 1.5cm thick slices, lengthwise)","Oil spray"],"purpose":"Chicken"}]', '[{"description":"Preheat oven to 200C/390F.","images":[],"step":1},{"description":"Spread panko breadcrumbs on a baking tray. Spray lightly with oil. Bake for 3 to 5 minutes or until LIGHT golden.","duration":4,"images":[],"step":2},{"description":"Scrape into a bowl. Add parmesan and mix.","images":[],"step":3},{"description":"In a separate bowl, whisk together Batter ingredients with a fork. Add chicken and mix to coat.","images":[],"step":4},{"title":"Optional","description":"Place a rack on the baking tray (Note 3)","images":[],"step":5},{"description":"Pick up chicken with left hand and place in breadcrumbs. Use right hand to sprinkle with breadcrumbs, press to adhere. Use right hand to transfer to baking tray. Repeat with remaining chicken. Spray lightly with oil.","images":[],"step":6},{"description":"Bake for 15 minutes for small tenders, 18 minutes for large ones. No longer than 20 minutes, otherwise they will begin to lose juiciness.","duration":15,"images":[],"step":7},{"description":"Serve immediately with Ranch or Honey Mustard Dip if desired (Note 4).","images":[],"step":8}]', '["egg","gluten","milk","mustard"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","low-calorie-recipes","main-dishes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_864e6ef26e50', 'en', 'US', 'Baked Italian Chicken with Potatoes', 'Turn every day ingredients into something special! The chicken does not need to be marinated because this recipe makes a wonderful sauce, but if you do then it will be even more tasty. I like to par boil the potatoes because I really love how it sucks up the flavour of the Italian Dressing. But you can skip this step if you prefer to cook it all in the oven - refer to Note 4 for steps.', 'https://www.recipetineats.com/tachyon/2014/07/Italian-Chicken-Potatoes_4.jpg', 15, 45, 60, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 0.9, "unit": "punnet of 250g"}}, {"id": "ing_potato", "quantity": {"value": 3.0, "unit": "bag of 2kg"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.4, "unit": "pack of 125g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_rosemary", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_vinegar", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["4 - 5 chicken thigh fillets (, skin on and bone in (about 6oz/200g each))","1/2 tbsp olive oil","1 tin (14oz/400g) crushed tomatoes","1 1/2 cups cherry tomatos","3 (around 1.5lb/ 750g in total) medium size potatoes (, peeled and cut into bite size pieces)","1/2 cup mozzarella cheese (, grated (or any other good melting cheese))","Salt and pepper"]},{"ingredients":["1/2 tbsp each dried rosemary and thyme (OR oregano) leaves (or 2 tbsp fresh)","2 garlic cloves (, minced)","3 tbsp red wine or white wine vinegar (Note 1)","3 tbsp extra virgin olive oil","1/2 tsp salt","Black pepper"],"purpose":"Italian Dressing"},{"ingredients":["Basil leaves (optional)"],"purpose":"Garnish"}]', '[{"description":"Preheat oven to 350F/180C.","images":[],"step":1},{"description":"Mix together Italian Dressing ingredients.","images":[],"step":2},{"description":"Boil or microwave the potatoes until slightly undercooked - about 5 minutes boiling / 5 minutes on high in a steamer in the microwave. Use a fork to rough the potatoes up a bit - this allows the potatoes to absorb more of the dressing flavour - and sprinkle with a pinch of salt and pepper.","images":[],"step":3},{"description":"Meanwhile, season the chicken on both sides with salt and pepper. Heat 1/2 tbsp olive oil in large oven proof skillet over high heat.","images":[],"step":4},{"title":"Add chicken and brown well on both sides","description":"around 5 minutes each side.","images":[],"step":5},{"description":"Remove skillet from heat, and pour off the excess fat.","images":[],"step":6},{"description":"Place potatoes around the chicken and pour over the crushed tomatoes. Season with a pinch of salt and pepper and drizzle the Italian Dressing all over.","images":[],"step":7},{"title":"Place cherry tomatoes on top and bake for 25","description":"30 minutes or until chicken is cooked through.","duration":27.5,"images":[],"step":8},{"description":"Remove from oven and sprinkle on cheese, then bake for a further 5 minutes until the cheese is melted and golden.","images":[],"step":9},{"description":"Let stand for 5 to 10 minutes before serving. Garnish with basil leaves if you wish.","duration":7.5,"images":[],"step":10}]', '["milk"]', '["gluten_free"]', '{"mealType":["main_course"],"cuisine":["Italian"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","italian-recipes","main-dishes","most-popular","one-pot-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1066f3c9c080', 'en', 'US', '5 Ingredient Sticky Stove Top Balsamic Drumsticks', 'Sticky chicken drumsticks that are cooked on the stove in half the time it takes to bake! Don''t let the short list of ingredients fool you - the glaze tastes like it has a lot more in it. Adapted from this Sticky Stove Top Chicken recipe from Sparks People. This recipe is NOT suited for scaling up because the glaze will not thicken. Watch the cooking video (in post) to see exactly how this is made - in particular, watch the braising liquid transform into the sticky glaze!', 'https://www.recipetineats.com/tachyon/2015/04/Sticky-Balsamic-Drumsticks_4.jpg', 5, 25, 30, 4, '[{"id": "ing_chicken", "quantity": {"value": 8.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_balsamic_vinegar", "quantity": {"value": 0.5, "unit": "bottle of 250ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.333, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.6, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["8 chicken drumsticks (2 lb / 1 kg) (Note 1)","1 cup water","1/2 cup balsamic vinegar","1/3 cup soy sauce (all purpose or light, not dark)","3 tbsp sugar (brown)","3 garlic cloves (, minced)"]},{"ingredients":["2 tsp fresh grated ginger","2 tbsp Sriracha or 1 tsp red pepper flakes (Note 2)"],"purpose":"Extra Flavourings (Optional)"},{"ingredients":["Parsley or shallots/scallions (, finely sliced)"],"purpose":"Garnishes (optional)"}]', '[{"description":"Combine all ingredients (including Extra Flavourings, if using) in a large skillet/fry pan or pot (Note 3) over medium high heat. The chicken should be in a single layer.","images":[],"step":1},{"description":"Bring to boil, turn chicken, then turn down to medium so it simmers energetically but not rapidly. DO NOT cover the pan with a lid.","images":[],"step":2},{"description":"Cook for 20 minutes, turning the chicken at 10 minutes.","duration":20,"images":[],"step":3},{"description":"At 20 minutes, the chicken should be cooked. Move the chicken to the side of the skillet, propping and stacking them up on the edges of the skillet to clear the surface of the liquid as much as possible so it can reduce.","images":[],"step":4},{"description":"Simmer for 5 minutes or until the liquid thickens (consistency of thick pouring cream) and coats the chicken. Keep an eye on the sauce, once it starts to thicken it will reduce quickly, don''t let it go too far. Roll the chicken in the glaze.","duration":5,"images":[],"step":5},{"description":"Remove the skillet from the stove and stand for 5 minutes - the sauce will thicken slightly more. Roll the chicken in the glaze again, then serve, garnished with parsley or scallions if desired.","duration":5,"images":[],"step":6},{"description":"Serve, garnished with scallions/shallots if using.","images":[],"step":7}]', '["gluten","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-drumstick-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d6addde9f9b4', 'en', 'US', 'Mexican Shredded Chicken', '5 minutes prep is all that''s required for this shredded chicken tossed in a smokey, mildly spicy red sauce that''s loaded with flavour. Make this in your slow cooker, pressure cooker or on the stove - directions provided for all!', 'https://www.recipetineats.com/tachyon/2016/03/Slow-Cooker-Mexican-Chicken_1.jpg', 10, 240, 250, 5, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.68, "unit": "kg"}}, {"id": "ing_chipotles_in_adobo_sauce", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_tomato", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}]', '[{"ingredients":["1.5 lb / 750g chicken breast (, skinless boneless (~3 halves))","1/2 cup Chipotles in Adobo Sauce (4 chillies + sauce) (Note 1)","14 oz / 400g can crushed tomatoes","2 garlic cloves (, crushed)","1 tsp EACH dried oregano, cumin powder and onion powder (or garlic powder)","2 tsp sugar (any)","3/4 tsp salt (Note 2)","Pepper"],"purpose":"Chicken & Sauce"},{"ingredients":["3 tbsp olive oil (Note 3)","2 tbsp lime juice"],"purpose":"To Finish"}]', '[{"description":"Cook Chicken","images":[],"step":1},{"title":"Slow Cooker","description":"Place Chicken & Sauce ingredients in the slow cooker and cook for 4 hours on low. The chicken is ready when it can be shredded easily with 2 forks but it should NOT be mushy (i.e. overcooked).","images":[],"step":2},{"title":"Pressure cooker","description":"35 minutes on high.","images":[],"step":3},{"title":"Stove","description":"Place Chicken & Sauce ingredients in a medium saucepan and add 1 cup water. Simmer covered on medium low for 40 - 50 minutes, turning chicken occasionally, until chicken can be shredded with 2 forks.","duration":45,"images":[],"step":4},{"description":"Remove chicken and shred. Set aside.","images":[],"step":5},{"description":"Add lime juice (to taste) and 1 tbsp olive oil to the sauce. Use a stick blender (or transfer to blender) to puree the sauce. Adjust salt and pepper to taste. You should have about 2 cups of sauce.","images":[],"step":6},{"description":"Brown Chicken","images":[],"step":7},{"description":"Heat 1 tbsp oil in a large skillet over high heat. Add 1/3 to 1/2 the chicken and fry until dark golden brown on one side, flip and cook the other side very briefly (don''t brown), then remove. Use 1 tbsp oil for each batch you fry.","images":[],"step":8},{"description":"To Serve","images":[],"step":9},{"description":"Toss chicken in the sauce OR serve it on the side.","images":[],"step":10},{"description":"Use for tacos (guacamole and Pico de Gallo, enchiladas, burritos, on green Mexican rice, quesadillas, sliders, on tostadas.","images":[],"step":11}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["chicken-breast-recipes","chicken-recipes","main-dishes","mexican-recipes","most-popular","quick-and-easy","slow-cooker-recipes","taco-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a00e118e1c3c', 'en', 'US', 'Chicken Salad with Avocado Dressing', 'A scrumptious, healthy salad that''s satisfying enough to have as a meal. The star of this is the creamy avocado dressing - full of nutrients, flavour and so delicious!', 'https://www.recipetineats.com/tachyon/2016/03/Chicken-Salad-Avocado-Dressing_7.jpg', 15, 5, 20, 2, '[{"id": "ing_avocado", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 30.0, "unit": "pack of 1kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_yogurt", "quantity": {"value": 0.03, "unit": "tub of 500g"}}, {"id": "ing_lime", "quantity": {"value": 0.09, "unit": "net of 500g"}}, {"id": "ing_milk", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_chicken_breast", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 0.45, "unit": "punnet of 250g"}}, {"id": "ing_lettuce", "quantity": {"value": 15.0, "unit": "head"}}]', '[{"ingredients":["1/2 large or 1 small ripe avocado","1 garlic clove (, minced)","2 tbsp diced red onion","1/4 cup cilantro (, stems and leaves, not packed in)","1/2 tbsp olive oil (optional)","1 tbsp plain low fat yoghurt (I use Greek)","3 tbsp lime juice","3 - 5 tbsp low fat milk","1/4 tsp onion or garlic powder","1/2 tsp salt","Black pepper"],"purpose":"Avocado Dressing"},{"ingredients":["5 - 7 oz / 250 - 300g chicken breast (, skinless boneless (I had 1 large one))","1 tbsp olive oil"],"purpose":"Chicken"},{"ingredients":["1 tsp smoked paprika","1/4 tsp each onion powder (, garlic powder, cayenne pepper, salt)","2 tbsp plain flour","Black pepper"],"purpose":"Spice Rub"},{"ingredients":["1/2 cup diced red onion","1 corn (, steamed, kernels cut off (or 3/4 cup cooked kernels))","3/4 cup cherry tomatoes (, halved or quartered)","5 cups chopped lettuce"],"purpose":"Salad"}]', '[{"title":"Avocado Dressing","description":"Place the ingredients in a small food processor and whizz until smooth. Use MILK to adjust consistency, and adjust salt to taste. (Note 1)","images":[],"step":1},{"title":"Spice Rub","description":"Combine ingredients and scatter on a plate.","images":[],"step":2},{"title":"Chicken: Slice into 4","description":"5 thin steaks on the diagonal, then coat both sides with Spice Rub.","images":[],"step":3},{"title":"Cook Chicken","description":"Heat oil in a large skillet over high heat. Add chicken and cook both sides until dark brown. Remove onto a plate and cover loosely with foil. Rest for 5 minutes then slice thickly.","duration":5,"images":[],"step":4},{"description":"Pile the Salad ingredients onto a serving platter then place the chicken on the side.","images":[],"step":5},{"description":"Serve with Avocado Dressing.","images":[],"step":6}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["lunch"],"cuisine":[],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","low-calorie-recipes","main-dishes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_554f7f45b76b', 'en', 'US', 'Slow Cooker Honey Buffalo Chicken Sliders', 'An effortless way to feed a crowd for game day! The sauce for these sliders are a jazzed up version of traditional Buffalo Sauce used for Buffalo Wings. Refer to the notes to choose your spiciness! The Blue cheese sauce is optional - this recipe is designed to have enough flavour even without it. Please refer to the notes for making this on the stove or in a pressure cooker. This makes enough for 7 rolls (10cm/4" diameter) with chicken piled on as per the photos. You can probably stretch it to 8!', 'https://www.recipetineats.com/tachyon/2016/02/Honey-Buffalo-Chicken-Sliders_4.jpg', 15, 240, 255, 7, '[{"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_hot_sauce", "quantity": {"value": 3.0, "unit": "bottle of 150ml"}}, {"id": "ing_honey", "quantity": {"value": 0.002, "unit": "jar of 500g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_cornstarch", "quantity": {"value": 2.0, "unit": "pack of 400g"}}, {"id": "ing_bread", "quantity": {"value": 7.0, "unit": "loaf"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}]', '[]', '[{"description":"Buffalo Chicken","images":[],"step":1},{"description":"Place chicken in one layer in slow cooker and sprinkle with garlic powder, paprika, thyme, salt and pepper. Add remaining Buffalo Chicken ingredients, mostly around the chicken rather than on top. Cook on LOW for 4 hours. (Note 2)","images":[],"step":2},{"description":"Remove chicken from slow cooker and shred roughly with too forks.","images":[],"step":3},{"description":"Toss in Sauce and keep warm.","images":[],"step":4},{"description":"Mix cornstarch with 2 tbsp water and add to Sauce (after chicken is removed). Simmer on sauté setting in slow cooker for 5 minutes, or until thickened to a syrup consistency (or transfer to saucepan and do this over medium heat).","duration":5,"images":[],"step":5},{"description":"Adjust salt & spiciness to taste per Note 1.","images":[],"step":6},{"description":"To serve","images":[],"step":7},{"description":"Split rolls in half and toast (if desired). Butter (if desired), then place lettuce on bottom half and top with chicken. Serve warm, with Blue Cheese Sauce if you''re a fan of blue cheese!","images":[],"step":8}]', '["gluten","milk","soy"]', '["high_protein"]', '{"mealType":["main_course"],"cuisine":["American","Western"],"categories":["chicken-breast-recipes","chicken-recipes","main-dishes","most-popular","one-pot-recipes","quick-and-easy","slow-cooked-fall-apart","slow-cooker-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b5ff0d06d67e', 'en', 'US', 'Easy Chicken Noodle Soup', 'This is how I make chicken noodle soup when I don''t have the time to make a complete homemade stock from scratch. It''s in between a super quickie version made using pre-cooked shredded chicken with chicken broth/stock, and the ultimate homemade version by poaching a whole chicken. It''s remarkable what a difference browning the chicken and cooking it in broth + water makes to the flavour base. Plus my tip for extra flavour is sautéing dried herbs with the onion!', 'https://www.recipetineats.com/tachyon/2015/12/Chicken-Vegetable-Noodle-Soup_2.jpg', 15, 45, 60, 4, '[{"id": "ing_bone_in", "quantity": {"value": 0.635, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_celery", "quantity": {"value": 6.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 300.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.635, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.34, "unit": "pack of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1.4 lb / 700g bone in (, skin on chicken thigh fillets (Note 1))","Salt and pepper","1 - 2 tbsp olive oil (, separated)","2 tsp dried thyme","2 tsp oregano","1 small onion (, diced (brown, white or yellow))","2 garlic cloves (, crushed)","2 cups celery (, chopped (Note 2))","2 cups carrots (, chopped (Note 2))","3 cups chicken broth/stock","3 cups water","6 oz / 200g thick egg pasta (or other pasta of choice) (Note 3)","Finely chopped parsley for garnish (optional)"]}]', '[{"description":"Season chicken generously with salt and pepper.","images":[],"step":1},{"description":"Heat 1 tbsp oil in a dutch oven or large pot over medium high heat.","images":[],"step":2},{"title":"Add chicken, skin side down, and cook until brown","description":"1 1/2 to 2 minutes. Turn and cook the other side for 2 minutes. Transfer to a plate.","duration":2,"images":[],"step":3},{"description":"Turn the heat down to medium low. Discard all but about 1 tbsp fat from the pot. If you don''t have any fat, add 1 tbsp olive oil (or 2 tbsp if there is not much chicken fat), then add the onion, garlic, thyme and oregano.","images":[],"step":4},{"description":"Cook for 2 minutes, then add the celery and carrots. Cook for 3 minutes.","duration":2,"images":[],"step":5},{"description":"Add a splash of the chicken broth and mix in, scraping the bottom of the pot.","images":[],"step":6},{"description":"Return the chicken and juices into the pot, add the chicken broth and water.","images":[],"step":7},{"description":"Turn the heat up to medium to bring to a simmer. Place the lid on and cook for 30 minutes, or until the chicken is cooked enough to shred.","duration":30,"images":[],"step":8},{"description":"Remove the chicken into a large bowl or plate.","images":[],"step":9},{"description":"Add the pasta into the pot. (Note 3)","images":[],"step":10},{"description":"While the pasta is cooking, remove the skin from the chicken and discard it. Then shred the flesh into chunks using 2 forks.","images":[],"step":11},{"description":"Return the chicken to the pot. Season to taste with salt and pepper.","images":[],"step":12},{"description":"Serve, garnished with parsley if desired.","images":[],"step":13}]', '["egg","gluten"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","quick-and-easy","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8f05482d6107', 'en', 'US', 'White Chicken (or Turkey) Enchilada Soup', 'I tried making this various ways, including poaching the chicken in the liquid. I found this to be the best way - maximum flavour AND as white as possible! This recipe is also perfect for using up leftover turkey. Just skip the chicken cooking step and toss in chopped or shredded turkey straight into the soup!', 'https://www.recipetineats.com/tachyon/2015/11/White-Chicken-Enchilada-Soup_2.jpg', 10, 20, 30, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_jalape_os", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.15, "unit": "tub of 250g"}}, {"id": "ing_corn", "quantity": {"value": 0.562, "unit": "can of 400g"}}, {"id": "ing_white_beans_drained", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}]', '[{"ingredients":["400 g chicken breast","1/4 tsp salt","Black pepper","1 tbsp olive oil"]},{"ingredients":["2 tbsp butter","2 garlic cloves (, crushed)","1 onion (, diced (brown, white, yellow))","3 tbsp plain flour","1 cup chicken broth / stock","4 cups milk (I used low fat)","1 tsp cumin powder","1 tsp coriander power","2 to 4 tbsp canned jalapeños (, finely chopped OR 1 x 4.5oz / 127g canned chopped peeled green chili)","1/4 cup sour cream (I used light)","1 1/2 cups corn (frozen or canned)","21 oz / 600g canned white beans ((1 1/2 cans), drained)","1/2 to 1 tsp salt","Black pepper"],"purpose":"Soup"}]', '[{"description":"Slice the chicken breast into 1cm / 1/3\" thick steaks. Sprinkle with salt and pepper.","images":[],"step":1},{"description":"Heat the oil in a large pot over medium high heat. Add the chicken breast (in 2 batches if necessary) and cook each side for 2 minutes each or until golden and just cooked through.","duration":2,"images":[],"step":2},{"description":"Transfer to a plate. Once cool enough to handle, shred with a fork or your hands (I do this while the soup is cooking), or chop it.","images":[],"step":3},{"description":"Turn the heat down to medium and add butter into the same pot. When the butter is melted, add onion and garlic. Cook for 3 minutes or until the onion is translucent and soft.","duration":3,"images":[],"step":4},{"description":"Add flour and cook for 2 minutes. Add chicken broth and cook, scraping the bottom of the pot to stir the brown bits into the liquid (extra flavour!).","duration":2,"images":[],"step":5},{"description":"Add the milk, cumin powder, coriander and jalapeños. Turn the heat up to medium high and cook, whisking occasionally, until the soup thickens slightly - about 5 minutes.","images":[],"step":6},{"description":"Whisk the sour cream in. Then add the corn, beans and shredded chicken. Cook for 1 minute or so until everything is heated through.","duration":1,"images":[],"step":7},{"description":"Adjust salt to taste.","images":[],"step":8},{"description":"Serve piping hot with all the trimmings!","images":[],"step":9}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["main_course"],"cuisine":[],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","mexican-recipes","one-pot-recipes","quick-and-easy","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0a1591af3a72', 'en', 'US', 'KFC Oven Baked "Fried" Chicken Tenders', 'Crunchy and perfectly seasoned, it really does taste like KFC! It is a mash up of my own recipe, the "11 Secret Herbs and Spices" from the Homemade KFC recipe by Every Nook & Cranny, and the coating recipe from this Best Baked "Fried" Chicken by Carlsbad Cravings.. Marinating makes the chicken extra juicy but if you don''t have time to marinate, this is still worth making! (See Note 3) PS I know it looks like a lot of salt but it''s not overly salty, it''s KFC level salty. Reduce salt and/or celery salt if desired.', 'https://www.recipetineats.com/tachyon/2015/09/KFC-Copycat-Oven-Baked-Fried-Chicken-Tenders_680px_2.jpg', 15, 25, 40, 4, '[{"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_celery", "quantity": {"value": 0.3, "unit": "head"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_basil", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.15, "unit": "jar of 50g"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_paprika", "quantity": {"value": 0.75, "unit": "jar of 40g"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_chicken", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.3, "unit": "tub of 500g"}}, {"id": "ing_flour", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 0.188, "unit": "loaf"}}, {"id": "ing_corn", "quantity": {"value": 0.094, "unit": "can of 400g"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}]', '[{"ingredients":["1/2 tsp salt","1 tbsp celery salt (Note 1)","2 tsp garlic powder","1/2 tsp dried thyme","1/2 tsp dried basil","1/2 tsp dried oregano","1/2 tbsp coarsely ground black pepper","1 tbsp mustard powder","2 tbsp paprika (not smoked, use sweet or plain)","1 tsp ground ginger","1 tsp cayenne pepper or ground pure chili (optional - for KFC \"Zinger\" flavour!)"],"purpose":"KFC Spice Mix"},{"ingredients":["1.2 - 1.4 lb / 600 - 700 g chicken tenderloin (10 - 12 pieces) (Note 2)","1 cup buttermilk OR 1/3 cup plain yoghurt + 2/3 cup milk (Note 3)","1 cup flour","1 cup panko breadcrumbs","1/4 cup cornmeal (Note 4)","2 tbsp butter (unsalted)","1 tbsp vegetable or canola oil","Oil spray"],"purpose":"Chicken"}]', '[{"description":"Combine the Spice Mix in a bowl.","images":[],"step":1},{"description":"Place 1 tbsp of Spice Mix in a ziplock bag with the chicken and buttermilk. Set aside to marinate for at least 2 hours, preferably 3 but ideally overnight.","images":[],"step":2},{"description":"To Cook","images":[],"step":3},{"description":"Preheat oven to 400F/200C.","images":[],"step":4},{"description":"Place the butter and oil on a large rimmed baking tray. Place in the oven for a few minutes until the butter is just melted. Remove and tip the tray to spread the oil and butter all over.","images":[],"step":5},{"description":"Combine the remaining Spice Mix, flour, panko and cornmeal in a bowl and mix. Place half in a large ziplock bag.","images":[],"step":6},{"description":"Drain the chicken of excess marinade using a colander.","images":[],"step":7},{"description":"Transfer half the chicken into the ziplock bag, seal in air so it is puffed like a balloon, then shake to coat the chicken in the seasoning. Press through the bag so the coating is firmly stuck onto the chicken. Place the chicken onto the baking tray.","images":[],"step":8},{"description":"Place the remaining coating into the ziplock bag and repeat with remaining chicken.","images":[],"step":9},{"description":"Spray the top with oil and place in the oven. Bake for 12 minutes, then turn, spray and bake for a further 8 to 10 minutes or until golden. Don''t bake more than 25 minutes, otherwise the chicken will dry out!","duration":12,"images":[],"step":10},{"description":"Serve with your favourite dipping sauce. I used Honey Mustard Sauce (Note 7).","images":[],"step":11}]', '["gluten","milk","mustard"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-recipes","dinner-tonight","main-dishes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_fd20cfe1d1d5', 'en', 'US', 'Chicken Meatloaf Wellington with Sun Dried Tomatoes', 'A fresh take on meatloaf! Made with chicken, scattered with sun dried tomatoes and the fresh burst of basil. Encase in puff pastry to create a cross between the British classic Beef Wellington and meatloaf (but made with chicken!).', 'https://www.recipetineats.com/tachyon/2015/09/Chicken-Meatloaf-Wellington_1-Featured.jpg', 15, 40, 55, 5, '[{"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 0.141, "unit": "loaf"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_basil", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_tomato", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_sheet_puff_pastry", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["1 small onion (, grated (about 1/2 cup))","1 lb / 500 g ground chicken (mince) (Note 1)","3/4 cup panko breadcrumbs","1/4 cup parmesan cheese (, finely grated)","1 egg","1/3 cup fresh basil (, roughly chopped (Note 2))","3/4 cup roughly chopped sun dried tomatoes","1 tsp salt","Black pepper"],"purpose":"Filling"},{"ingredients":["1 sheet puff pastry (, thawed)","1 egg (, lightly beaten (optional) (Note 3))"],"purpose":"Pastry"}]', '[{"description":"Preheat oven to 180C/350F. Line a baking tray with parchment paper.","images":[],"step":1},{"description":"Place the Filling ingredients in a bowl and use your hands to mix together. It should be quite soft and wet, not dry and crumbly.","images":[],"step":2},{"description":"Place the filling onto the puff pastry. Shape into a loaf and roll the puff pastry up, ending with the seam side down.","images":[],"step":3},{"description":"Transfer to baking tray. Cut a few diagonal slashes across the top.","images":[],"step":4},{"description":"Brush with egg wash and bake for 35 to 40 minutes, or until the pastry is deep golden brown. Turn the tray at around 25 minutes for even browning.","duration":37.5,"images":[],"step":5},{"description":"Remove from the oven. Rest for 5 minutes before serving.","duration":5,"images":[],"step":6}]', '["egg","milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-mince-recipes","chicken-recipes","dinner-tonight","main-dishes","most-popular"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4473cf255160', 'en', 'US', 'White Chicken Enchiladas', 'This white sauce version of Enchiladas gives the classic a serious run for its money!', 'https://www.recipetineats.com/tachyon/2015/08/White-Enchiladas_Plated-Featured.jpg', 15, 25, 40, 4, '[{"id": "ing_butter", "quantity": {"value": 2.5, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.3, "unit": "tub of 250g"}}, {"id": "ing_chicken", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_cumin", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_chilli", "quantity": {"value": 0.3, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_chicken", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.5, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_rtillas", "quantity": {"value": 8.0, "unit": "unit"}}]', '[{"ingredients":["2 1/2 tbsp butter","3 tbsp flour","1 cup milk","1/2 cup light sour cream","1 cup chicken broth","1/2 tsp cumin powder","2 tbsp finely chopped jalapeños OR canned green chilies (Note 2)","1/2 tsp salt + pepper"],"purpose":"White Sauce"},{"ingredients":["2 1/2 cups shredded cooked chicken (I used poached chicken breast)","1 cup frozen corn","1/2 cup sliced scallions","Salt and pepper","2 cups grated cheese (Note 1)","8 to rtillas (flour or corn)"],"purpose":"Enchiladas"}]', '[{"description":"Melt butter over medium heat in a skillet. Add flour and cook for 1 minute.","duration":1,"images":[],"step":1},{"title":"Add milk, whisk until thickened","description":"about 30 seconds to 1 minute. Add sour cream and chicken broth. Whisk and cook for 2 minutes - it should thicken slightly. Stir through cumin, jalapeños, salt and pepper. Remove from heat and set aside.","duration":2,"images":[],"step":2},{"description":"Preheat oven to 180C/350F.","images":[],"step":3},{"description":"Mix together 1/4 cup White Sauce, chicken, corn, scallions, 1 cup of grated cheese, salt and pepper.","images":[],"step":4},{"description":"Pop the tortillas in the microwave for 15 seconds to warm through (so they don''t crack when rolled up).","duration":0.25,"images":[],"step":5},{"description":"Divide filling between tortillas, and roll them up like a cigar.","images":[],"step":6},{"description":"Smear 2 tbsp of White Sauce in baking dish. Place enchiladas in the dish, seam side down. Pour over remaining White Sauce, scatter with remaining cheese.","images":[],"step":7},{"description":"Bake for 25 minutes, until bubbly and golden. Serve hot!","duration":25,"images":[],"step":8},{"title":"Optional","description":"Serve Pico de Gallo to top it or serve it on the side. I added avocado to my base Pico de Gallo Recipe.","images":[],"step":9}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","enchiladas","main-dishes","mexican-recipes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_52d01eac228e', 'en', 'US', 'Prosciutto Wrapped Chicken and Scalloped Potatoes (One Pan!)', 'This is one of those recipes that is easy enough for midweek but elegant enough for company - at least, in my opinion! By baking the chicken on top of the potato, the juices mingles with the salty prosciutto then drips down onto the potato, adding extra (serious) flavour oomph!', 'https://www.recipetineats.com/tachyon/2015/08/One-Pan-Prosciutto-Chicken-Potatoes_Featured.jpg', 15, 45, 60, 4, '[{"id": "ing_ricotta", "quantity": {"value": 0.4, "unit": "tub of 250g"}}, {"id": "ing_lemon", "quantity": {"value": 4.0, "unit": "net of 500g"}}, {"id": "ing_sage", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_ong_or_8_small_thin_slices_of_prosciutto", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_potato", "quantity": {"value": 1.5, "unit": "bag of 2kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["2/3 cup ricotta","Zest of 1 small lemon (, or 1/2 large lemon)","1 1/2 tsp finely sliced fresh sage leaves (Note 1)","1/4 tsp salt","Pepper"],"purpose":"Ricotta Filling"},{"ingredients":["4 chicken thigh fillets (, skinless and boneless (about 5 - 7 oz / 150 - 200g each))","4 long or 8 small thin slices of prosciutto","1.5 lb / 750 g potatoes (, peeled and cut into thin slices)","1 garlic clove (, crushed (optional))","1 1/2 tbsp olive oil + 1/2 tbsp extra olive oil","1 tsp dried thyme leaves","1/4 cup freshly grated parmesan","Salt and pepper"],"purpose":"Prosciutto Chicken & Potatoes"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Mix together the Ricotta Filling ingredients in a small bowl.","images":[],"step":2},{"description":"Lay out the prosciutto on a work surface. Place chicken lengthwise at the bottom of each strip.","images":[],"step":3},{"description":"Divide Ricotta Filling between the chicken, placing it at the bottom (closest to you).","images":[],"step":4},{"description":"Roll up the chicken, wrapping it in the prosciutto, finishing with the seam side down. Not too tightly otherwise the ricotta will ooze out!","images":[],"step":5},{"description":"Use toothpicks to seal the ends. (Note 2)","images":[],"step":6},{"description":"Spread the potato slices on the base of a roasting dish or large ovenproof skillet. Fan them out so they are overlapping slightly.","images":[],"step":7},{"description":"Mix together 1 1/2 tbsp olive oil and garlic then pour over the potatoes, using a teaspoon or brush to spread it out. Sprinkle with salt and pepper and thyme leaves.","images":[],"step":8},{"description":"Place chicken on top of the potato, drizzle the chicken with 1/2 tbsp olive oil and bake for 40 minutes.","duration":40,"images":[],"step":9},{"description":"Remove chicken onto a plate to rest, covered loosely with foil.","images":[],"step":10},{"description":"Sprinkle the potatoes with parmesan cheese, then return just the potatoes back into the oven and turn up the oven to maximum. Bake for 5 minutes.","duration":5,"images":[],"step":11},{"description":"Remove potatoes from the oven. Place chicken back on top.","images":[],"step":12},{"description":"Serve asap!","images":[],"step":13}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","most-popular","one-pot-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a474fbff15c1', 'en', 'US', 'Shredded Sweet Soy Chicken Breast', 'A simple, fast, very tasty way to prepare chicken. Chicken breast is perfect for shredding. Because it''s so lean, it is especially great combined with a jammy intense flavoured sauce that is sweet and sour. Add a kick of chili if you want! Great served on rice, or use the sauce as the flavouring for a fried rice!', 'https://www.recipetineats.com/tachyon/2015/07/Sweet-Soy-Shredded-Chicken_600px_1_Featured-Image.jpg', 10, 60, 70, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.333, "unit": "bottle of 250ml"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_jam", "quantity": {"value": 0.122, "unit": "jar of 370g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.3, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.025, "unit": "pack of 400g"}}]', '[{"ingredients":["1 lb / 500g chicken breast (skinless, boneless pieces)","2 cloves of garlic (, minced)","1/2 onion (, finely diced)","1 tbsp oil (vegetable, canola, olive oil or grapeseed oil)","1/3 cup soy sauce (ordinary soy sauce)","1/3 cup white vinegar (or substitute with other vinegar except balsamic)","3 tbsp jam (Note 1)","1 tbsp black peppercorns or 1/2 tbsp ground black pepper (Note 2)","3/4 cups water"],"purpose":"Shredded Chicken"},{"ingredients":["2 tsp cornstarch / cornflour","3 tsp water"],"purpose":"Sauce Thickening"}]', '[{"title":"Slow Cooker","description":"Place all the Shredded Chicken ingredients in the slow cooker and cook on low for 5 hours (or 2 1/2 hours on high).","images":[],"step":1},{"title":"Pressure Cooker","description":"Place all the Shredded Chicken ingredients in the pressure cooker. Cook for 35 minutes on high.","duration":35,"images":[],"step":2},{"title":"Stove","description":"Place all the Shredded Chicken ingredients in a saucepan large enough for the chicken to fit snugly in one layer. Add 1/2 cup extra water so the chicken is mostly, but not completely submerged. Cover and simmer for about 50 to 60 minutes, turning once or twice.","images":[],"step":3},{"description":"The chicken is ready when it can be easily shredded with two forks. Remove the chicken from the liquid and shred it while it is warm. Set aside and cover to keep warm.","images":[],"step":4},{"description":"Transfer the liquid from the slow cooker / pressure cooker to a saucepan and bring to simmer. (Note 3) Reduce to around1 1/4 cups - it should only take a few minutes.","images":[],"step":5},{"description":"Mix together the Sauce Thickening ingredients and add to the saucepan. Simmer until it it thickens to a syrup consistency.","images":[],"step":6},{"description":"Toss the chicken in the sauce and serve over rice. (Note 4)","images":[],"step":7}]', '["gluten","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","low-calorie-recipes","main-dishes","most-popular","quick-and-easy","slow-cooker-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1936d88c97f7', 'en', 'US', 'One Pot Creamy Parmesan Garlic Risotto with Lemon Pepper Chicken', 'Two dishes made in one pot! Creamy, dreamy risotto with yummy garlic parmesan flavours topped with crispy roast chicken. Cooking the chicken on top of the rice is like making rice with triple strength stock!', 'https://www.recipetineats.com/tachyon/2015/06/One-Pot-Creamy-Risotto-Lemon-Pepper-Chicken-4.jpg', 10, 50, 60, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.907, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.094, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_rice", "quantity": {"value": 225.0, "unit": "pack"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_chicken", "quantity": {"value": 0.907, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.5, "unit": "pack of 200g"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1/2 tbsp olive oil","2 lb / 1 kg chicken thighs (, skin on and bone in (5 pieces) (Note 1))","2 - 3 tbsp Lemon Pepper Seasoning (Note 2)"],"purpose":"Chicken"},{"ingredients":["2 tbsp butter","4 garlic cloves (, minced)","1 onion (, finely diced)","1 1/2 cups risotto rice (arborio)","1/2 cup white wine (, any (or stock or water))","4 cups chicken broth (stock)","1 cup milk (I use low fat)","1/2 tsp salt","Black pepper"],"purpose":"Risotto"},{"ingredients":["1 cup freshly grated parmesan (lightly packed)","2 tbsp butter","1/2 to 1 cup milk (preferably warmed)","Fresh thyme leaves (, or finely chopped parsley, chives or oregano (optional))"],"purpose":"Risotto Finishes"}]', '[{"description":"Preheat oven to 180C/350F (fan forced) / 200C/390F (conventional).","images":[],"step":1},{"description":"Coat chicken with Lemon Pepper Seasoning, using most of it on the skin.","images":[],"step":2},{"description":"Heat olive oil over medium heat in a large oven proof fry pan (Note 3).","images":[],"step":3},{"description":"Place the chicken in the pan skin side down. Cook for 3 minutes then turn the heat up to medium high and cook for a further 2 minutes or until browned. Turn and cook for 3 minutes. (Note 4)","duration":3,"images":[],"step":4},{"description":"Remove chicken onto a plate. Discard excess oil in the pan and wipe the pan with a paper towel.","images":[],"step":5},{"description":"Return the pan to the stove, still on medium high.","images":[],"step":6},{"description":"Melt butter in the pan. Add garlic and onion and cook for 2 minutes or until onion is translucent.","duration":2,"images":[],"step":7},{"description":"Add rice and stir until the grains turn from white to translucent. Add wine and cook for 1 to 2 minutes, or until the wine is mostly evaporated.","duration":1.5,"images":[],"step":8},{"description":"Add chicken broth, milk, salt and pepper. Bring to a simmer on the stove. Give it a quick stir then place the chicken on top of the rice (pour juices on the plate in too). Then place a lid (or foil) on the pan and transfer to the oven.","images":[],"step":9},{"description":"Bake for 20 minutes with the lid on. Remove the lid and return to the oven for another 10 minutes, or until the rice is firm but just cooked (not mushy!) and the chicken is crispy.","duration":20,"images":[],"step":10},{"description":"Remove the chicken from the rice. Stir through Risotto Finishes, using the milk to get the risotto to a creamy consistency.","images":[],"step":11},{"description":"Return chicken on top. Serve immediately, with fresh thyme leaves and extra parmesan, if desired.","images":[],"step":12}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","italian-recipes","main-dishes","most-popular","one-pot-recipes","quick-and-easy","risotto-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_95c2ccf47758', 'en', 'US', 'Honey Mustard Baked Chicken with Potatoes & Bacon', 'This is one of those dishes that is easy enough for mid week but fancy enough for a dinner party. The flavour of the sauce is incredible. It''s got the chicken juices mixed in as well as bacon. A fully loaded one pan meal!', 'https://www.recipetineats.com/tachyon/2015/05/Honey-Mustard-Baked-Chicken-with-Bacon-and-Roast-Potatoes_680px_MAIN.jpg', 10, 60, 70, 5, '[{"id": "ing_potato", "quantity": {"value": 2.0, "unit": "bag of 2kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 0.992, "unit": "pack of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_wine", "quantity": {"value": 0.25, "unit": "bottle of 750ml"}}, {"id": "ing_mustard", "quantity": {"value": 0.25, "unit": "jar of 200g"}}, {"id": "ing_honey", "quantity": {"value": 0.06, "unit": "jar of 500g"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_cream", "quantity": {"value": 0.12, "unit": "carton of 250ml"}}, {"id": "ing_water", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["2 lb / 1kg potatoes (, peeled and cut into large chunks)","1 tbsp olive oil","Salt and pepper"],"purpose":"Potatoes"},{"ingredients":["2 - 2 1/2 lb / 1 - 1.25 kg chicken thighs (5 pieces), skin on and bone in (Note 1)","Salt and pepper","7 oz / 200g bacon (, diced, separated)","2 garlic cloves (, minced)","1/2 onion (, finely diced (brown, white or yellow))"],"purpose":"Chicken"},{"ingredients":["3/4 cup white wine (Note 2)","1/3 cup dijon mustard","2 tbsp honey","1 tsp dried thyme (or 2 tsp fresh thyme leaves)","2 tbsp milk or cream (I used milk. This is just for colour)","1/3 cup water (Note 3)"],"purpose":"Mustard Sauce"},{"ingredients":["Fresh thyme leaves or finely chopped parsley"],"purpose":"Garnish (optional)"}]', '[{"description":"Cook potatoes in boiling water for 5 minutes, then drain. Sprinkle with salt and pepper and drizzle with olive oil.","duration":5,"images":[],"step":1},{"description":"Preheat oven to 190C/375F.","images":[],"step":2},{"description":"Sprinkle chicken with salt and pepper.","images":[],"step":3},{"description":"Heat a large skillet / frypan over medium high heat. Add HALF the bacon and cook until lightly browned. Transfer bacon to a paper towel lined plate.","images":[],"step":4},{"description":"Turn the stove down to medium. Add the chicken into the pan, skin side down. Cook for 3 minutes or until very lightly browned and chicken fat has \"melted\" into the pan. Turn the chicken over and cook for 2 minutes, then remove chicken onto a plate.","duration":3,"images":[],"step":5},{"description":"Drizzle 1 tbsp of the fat in the pan over the potatoes, then pour off and discard the rest. Return the pan to the stove.","images":[],"step":6},{"description":"Add the garlic and onion and cook until the onion is lightly browned and translucent - about 2 minutes.","images":[],"step":7},{"description":"Add wine into the pan and scrape the brown bits off the bottom of the pan to mix in with the sauce. Bring to simmer and cook for 2 minutes or so, or until you can no longer smell alcohol fumes.","duration":2,"images":[],"step":8},{"description":"Add the remaining Mustard Sauce ingredients and cooked bacon and stir to combine. Then add the chicken and potatoes back into the pan, sprinkle over remaining bacon.","images":[],"step":9},{"title":"Bake for 40","description":"50 minutes (no cover), or until chicken and potatoes are golden brown.","duration":45,"images":[],"step":10},{"description":"Rest for 5 minutes before serving, garnished with fresh thyme leaves and/or parsley, if desired.","duration":5,"images":[],"step":11}]', '["milk","mustard"]', '["gluten_free","high_protein"]', '{"mealType":["main_course"],"cuisine":[],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","most-popular","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b1721a050345', 'en', 'US', 'One Pot Greek Chicken and Lemon Rice', 'Recipe video above. The best chicken and rice recipe in the world!! This is not an authentic Greek dish (as far as I know!) but it is made using classic Greek ingredients. The beauty of this is that it is all made in one pot / pan. Cooking the rice with the chicken on top adds extra flavour to the rice because the chicken juices get soaked up by the rice. MARINATING TIME: 20 minutes to overnight. {Recipe video above} SCALE RECIPE using servings slider - hover mouse over Servings.', 'https://www.recipetineats.com/tachyon/2015/04/One-Pot-Greek-Chicken-Lemon-Rice.jpg', 10, 50, 60, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_rice", "quantity": {"value": 150.0, "unit": "pack"}}, {"id": "ing_chicken", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}]', '[{"ingredients":["5 chicken thighs, skin on, bone in (about 1 kg / 2 lb) (Note 1)","1 - 2 lemons, use the zest + 4 tbsp lemon juice (Note 7)","1 tbsp dried oregano","4 garlic cloves, minced","1/2 tsp salt"],"purpose":"Chicken and Marinade"},{"ingredients":["1 1/2 tbsp olive oil, separated","1 small onion, finely diced","1 cup (180g) long grain rice (, uncooked (Note 6))","1 1/2 cups (375 ml) chicken broth / stock","3/4 cup (185 ml) water","1 tbsp dried oregano","3/4 tsp salt","Black pepper"],"purpose":"Rice"},{"ingredients":["Finely chopped parsley or oregano (optional)","Fresh lemon zest (highly recommended)"],"purpose":"Garnish"}]', '[{"description":"Combine the Chicken and Marinade ingredients in a ziplock bag and set aside for at least 20 minutes but preferably overnight.","images":[],"step":1},{"description":"To Cook","images":[],"step":2},{"description":"Preheat oven to 180°C/350°F.","images":[],"step":3},{"description":"Remove chicken from marinade, but reserve the Marinade.","images":[],"step":4},{"description":"Heat 1/2 tbsp olive oil in a deep, heavy based skillet (Note 2) over medium high heat.","images":[],"step":5},{"description":"Place the chicken in the skillet, skin side down, and cook until golden brown, then turn and cook the other side until golden brown. Remove the chicken and set aside.","images":[],"step":6},{"description":"Pour off fat and wipe the pan with a scrunched up ball of paper towel (to remove black bits), then return to the stove.","images":[],"step":7},{"description":"Heat 1 tbsp olive oil in the skillet over medium high heat. Add the onion and sauté for a few minutes until translucent. Then add the remaining Rice ingredients and reserved Marinade.","images":[],"step":8},{"description":"Let the liquid come to a simmer and let it simmer for 30 seconds. Place the chicken on top then place a lid on the skillet (Note 3). Bake in the oven for 35 minutes. Then remove the lid and bake for a further 10 minutes, or until all the liquid is absorbed and the rice is tender (so 45 minutes in total).","duration":0.5,"images":[],"step":9},{"description":"Remove from the oven and allow to rest for 5 to 10 minutes before serving, garnished with parsley or oregano and fresh lemon zest, if desired.","duration":7.5,"images":[],"step":10}]', '[]', '["gluten_free","high_protein"]', '{"mealType":["main_course"],"cuisine":["Greek"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","greek-recipes","main-dishes","mediterranean-recipes","most-popular","nagis-picks","one-pot-recipes","quick-and-easy","rice-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6de894b4ceff', 'en', 'US', 'Rotisserie Flavoured Chicken and Potato Bake & a Giveaway!', 'A one pan meal - TWO dishes in one pan! By baking the potato gratin with chicken on top, the chicken juices mix into the potato gratin, creating incredible flavour. The chicken fat is rendered on the stove first to remove excess fat and is seasoned with a rotisserie chicken flavoured rub.', 'https://www.recipetineats.com/tachyon/2015/02/Rotisserie-Chicken-Potato-Gratin-FINAL-Version-2.jpg', 15, 60, 75, 4, '[{"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 2.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.833, "unit": "pack of 3 heads"}}, {"id": "ing_potato", "quantity": {"value": 1.5, "unit": "bag of 2kg"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}]', '[{"ingredients":["1/2 tsp onion powder","1/2 tsp garlic powder","1 tsp paprika","1 1/2 tsp dried thyme leaves","1/2 tsp salt","1/4 tsp black pepper"],"purpose":"Rub"},{"ingredients":["4 chicken thigh fillets (, skin on and bone in (about 1.5lb/750g))","1 tbsp olive oil"],"purpose":"Chicken"},{"ingredients":["1 large onion (, halved then sliced)","2 garlic cloves (, crushed)","1.5 lb / 750g potatoes ((Note 1), peeled and sliced into 1/8\" / 0.3cm slices)","1 cup milk","1 tsp salt","Black pepper","1/2 cup parmesan (, grated)"],"purpose":"Potato"}]', '[{"description":"Preheat oven to 350F/180C.","images":[],"step":1},{"description":"Combine the Rub ingredients in a small bowl. Rub onto the chicken, using most on the skin side.","images":[],"step":2},{"description":"Heat olive oil over medium heat in a large fry pan. (Note 2) Place chicken in the pan, skin side down. Cook for 10 minutes - this renders the fat. Then turn and cook the other side for 2 minutes. Remove chicken onto a plate.","duration":10,"images":[],"step":3},{"description":"Pour out and discard all the fat but do not wipe the pan. Return the pan to the stove and turn up the heat to medium high.","images":[],"step":4},{"description":"Add the onion and garlic together and sauté for 2 minutes.","duration":2,"images":[],"step":5},{"description":"Add half the milk and bring to simmer. Use a wooden spoon to scrape the bottom of the pan to mix the brown bits into the milk.","images":[],"step":6},{"description":"Place half the potatoes in the pan. Scatter over 1/2 tsp salt, black pepper and half the parmesan.","images":[],"step":7},{"description":"Repeat with remaining potato, salt and parmesan, then pour over the remaining milk.","images":[],"step":8},{"description":"Use a egg flip to press the potatoes into the milk while it simmers for 10 minutes and some of the milk has evaporated.","duration":10,"images":[],"step":9},{"description":"Place chicken on the potato, then place in the oven and bake for 40 to 50 minutes, until the chicken is cooked and the potatoes are golden brown on top.","duration":45,"images":[],"step":10},{"description":"Allow to rest for 5 minutes before serving.","duration":5,"images":[],"step":11}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["main_course"],"cuisine":[],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","most-popular","one-pot-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_10277bf20a60', 'en', 'US', 'One Pan Spanish Chicken with Chorizo, Tomato and Potatoes', 'A one-pan dinner, chock full of flavour thanks to the chorizo! The active prep / cook time is only around 20 minutes so this is a super fast meal for midweek!', 'https://www.recipetineats.com/tachyon/2015/01/DSC_0318.jpg', 15, 50, 65, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_potato", "quantity": {"value": 8.0, "unit": "bag of 2kg"}}, {"id": "ing_chorizo_cut_into_1_3cm_1_8_slices", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 0.5, "unit": "punnet of 250g"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_paprika", "quantity": {"value": 0.562, "unit": "jar of 40g"}}, {"id": "ing_chilli", "quantity": {"value": 0.25, "unit": "pack of 100g"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["4 chicken thigh fillets (, skin on and bone in (about 8oz/250g each) (Note 1))","8 - 12 baby potatoes (, scrubbed and skin on, halved (or 3 medium potatoes, cut into 4) (Note 2))","2 chorizo (5 - 6 oz / 150 - 200g in total), cut into 1/3cm / 1/8\" slices (Note 3)","2 cloves garlic (, minced)","1 small red capsicum ((bell pepper), cut into slices)","1 small red onion (, halved and cut into slices (or ordinary onion))","1 can (15oz/400g) crushed tomatoes","1 tbsp dried oregano","1/2 to 1 punnet cherry tomatoes (8oz / 250g) (Note 4)"]},{"ingredients":["2 tbsp lemon juice (Note 5)","1 1/2 tbsp paprika","1/4 - 1/2 tsp cayenne or chilli powder (adjust to taste for spiciness)","1 1/2 tsp salt","Black pepper"],"purpose":"Rub"},{"ingredients":["Fresh oregano leaves"],"purpose":"Garnish (optional)"}]', '[{"description":"Preheat oven to 350F/180C.","images":[],"step":1},{"description":"Combine the Rub ingredients in a small bowl. Slather over the chicken.","images":[],"step":2},{"description":"Boil or microwave the potatoes until slightly undercooked.","images":[],"step":3},{"description":"Heat the oil in a large, deep fry pan or oven proof casserole dish over high heat.","images":[],"step":4},{"description":"Add the chicken, skin side down, and cook unit light brown - about 1 to 1 1/2 minutes. Then turn and cook the other side until a slightly deeper brown - about the same time. Remove into a big bowl.","images":[],"step":5},{"description":"Add the chorizo and fry until light brown on each side - about 1 minute (each side). Remove into the same bowl as the chicken.","images":[],"step":6},{"description":"If the pan is looking dry (depends on fattiness of chicken and chorizo), add 1 tbsp of olive oil. I did not need this.","images":[],"step":7},{"description":"Add the garlic, capsicum (bell pepper) and onion and sauté for 2 minutes until the capsicum is slightly charred. It will be extra charred from the dark brown residue from the chorizo and chicken.","duration":2,"images":[],"step":8},{"description":"Add the canned tomatoes and oregano and stir to combine, scraping the bottom of the pan. Then add the potato, chicken, chorizo and cherry tomatoes. Nestle the chicken in so it is half submerged in the tomato.","images":[],"step":9},{"description":"Bring to simmer, then cover with a lid (I use a lid from a large pot) or foil and bake for 30 to 40 minutes until the chicken is cooked through and dark brown.","duration":35,"images":[],"step":10},{"description":"Serve, garnished with fresh oregano leaves if desired.","images":[],"step":11}]', '[]', '["gluten_free","high_protein"]', '{"mealType":["main_course"],"cuisine":["Spanish Style"],"categories":["chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","mediterranean-recipes","most-popular","one-pot-recipes","quick-and-easy","spanish-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_82f07371cfba', 'en', 'US', 'Taco Stack', 'Stacked tacos! These are made with layers of tortillas, Pork Carnitas (Mexican Shredded Pork) or Chicken, Corn and Tomato Salsa and melted cheese. Fun, fabulous and easy. If you make this with leftover Pork Carnitas then it''s super quick too! Serves 2 very hungry people or 4 dieting people. Note: This stack is made with meat that is juicy and moist so all that is needed is a dollop of sour cream to finish it off. If you are concerned your meat is too dry, I suggest having a side sauce to add moisture.', 'https://www.recipetineats.com/tachyon/2015/01/Taco-Stack.jpg', 20, 20, 40, 2, '[{"id": "ing_tortillas", "quantity": {"value": 8.0, "unit": "pack of 8"}}, {"id": "ing_chicken", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_corn", "quantity": {"value": 8.0, "unit": "can of 400g"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_ime", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.544, "unit": "kg"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_jalape_os", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["8 small tortillas (, corn or flour (around 6\" / 12 cm rounds))","3 cups shredded Pork Carnitas or Quick Mexican Chicken (see below)","1 tbsp olive oil","1 1/2 cups grated cheese (I used Monterey Jack. See Note 1 for other suggestions)"]},{"ingredients":["1 1/4 cups corn kernels (, fresh, frozen or canned (drained) (I used frozen))","1 tbsp olive oil","1 punnet cherry tomatoes (, diced (or 2 medium tomatos, deseeded and diced, around 1 1/2 cups (Note 2)))","2 shallots / scallions (, green part only, sliced)","1/2 lime (, juice only (add more or less to taste))","Salt and pepper to taste"],"purpose":"Salsa"},{"ingredients":["1.2 lb / 600g chicken thigh fillets (, skinless and boneless, cut into 1cm / 2/5\" slices (Note 3))","1 tsp garlic powder (or add 1 minced garlic clove into the oil in the fry pan)","2 tsp cumin powder","1 tsp paprika","1/2 tsp oregano","Pinch of cayenne or chili powder (for heat - adjust to taste)","1 1/2 tsp salt","Black pepper","1 lime (, juice only)","1 tbsp olive oil"],"purpose":"Quick Mexican Chicken"},{"ingredients":["Sour cream","Cilantro / coriander","Jalapeños (, finely chopped)","Avocado (, diced)"],"purpose":"Garnish and toppings"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Prepare either the Pork Carnitas or Quick Mexican Chicken.","images":[],"step":2},{"description":"Place the corn tortillas in the oven (I do it directly on the shelf) and bake for 3 to 5 minutes on each side, just to make them a bit stiff but not browned.","duration":4,"images":[],"step":3},{"description":"Place a tortilla on a baking tray. Scatter 1/6th of the Pork Carnitas or Quick Mexican Chicken on the tortilla and top with Salsa (reserve some for Topping) then cheese. Place another tortilla on top and repeat, then again (so you end up with 3 layers of meat. Place the 4th tortilla on top. I don''t put anything on it, but you could sprinkle some cheese if you want.","images":[],"step":4},{"description":"Repeat with remaining 4 tortillas.","images":[],"step":5},{"description":"Bake for 10 minutes until heated through and cheese is melted (it does not take long).","duration":10,"images":[],"step":6},{"description":"Remove from oven.","images":[],"step":7},{"description":"Top with remaining Salsa and Toppings of choice (I used sour cream, avocado, jalapeño and coriander/cilantro)","images":[],"step":8},{"description":"Heat 1 tbsp olive oil in a large pan over high heat. Add the corn and sauté for a couple of minutes until charred to your liking. (This step is optional)","images":[],"step":9},{"description":"Allow to cool slightly, then toss with remaining Salsa ingredients.","images":[],"step":10},{"description":"Defrost (if using frozen), then heat 1 tbsp olive oil in a large fry pan over high heat.","images":[],"step":11},{"description":"Add Pork Carnitas and cooking until the underside is golden brown (do not flip - Note 4).","images":[],"step":12},{"description":"Remove from pan (scrape up all the brown bits) and set aside.","images":[],"step":13},{"description":"Quick Mexican Chicken","images":[],"step":14},{"description":"Combine all ingredients other than the oil in a bowl and toss to combine.","images":[],"step":15},{"description":"Heat the oil in a large fry pan over high heat.","images":[],"step":16},{"description":"Add the chicken and sauté until browned and cooked through.","images":[],"step":17},{"description":"Remove chicken from the fry pan. Allow to cool then either roughly chop into smaller pieces or use a fork to \"shred\".","images":[],"step":18}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["main_course"],"cuisine":["Mexican - My Way"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","gluten-free-recipes","mexican-recipes","pork-carnitas","pork-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_eb1ac84490df', 'en', 'US', 'Jamie Oliver''s Chicken in Milk {Seriously Delish}', 'Though the ingredients list might seem odd, this is actually one of the best chicken dishes I have ever had. Possibly the best roast chicken I''ve ever had. It''s incredibly easy to make and produces a very tender chicken with crispy skin on top. The braising liquid reduces to a fabulous sauce that has a hint of freshness from the lemon and muskiness from the sage and cinnamon. The whole cloves of garlic cook in the skin so they are soft and mushy (mild garlic flavour, much more sweet), perfect for popping out of the skin and eating with the chicken, or spread it on toast! The milk dissolves into bits of curd which remind me of bocconcini and taste like little bursts of creaminess.', 'https://www.recipetineats.com/tachyon/2014/12/Chicken-in-Milk-1445.jpg', 5, 100, 105, 4, '[{"id": "ing_chicken", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_stick_cinnamon", "quantity": {"value": 0.5, "unit": "jar"}}, {"id": "ing_oosely_packed_sage_leaves", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_emons", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 16.667, "unit": "pack of 3 heads"}}, {"id": "ing_milk", "quantity": {"value": 0.562, "unit": "L"}}]', '[{"ingredients":["3 - 3.5 lb / 1.5 - 1.8 kg whole chicken","2 tsp salt (plus more to taste)","Black pepper","2 tbsp olive oil","1/2 stick cinnamon","1/4 cup loosely packed fresh sage leaves","2 lemons (, zest only (avoid grating the pith which is bitter))","10 cloves of garlic (, whole, skin on)","2 1/4 cups milk (I used low fat)"]}]', '[{"description":"Preheat oven to 190C/375F.","images":[],"step":1},{"description":"Wash the chicken under water and pat dry with paper towels.","images":[],"step":2},{"description":"Sprinkle over the salt and 5 grinds of black pepper and pat all over the chicken, concentrating on the top and sides.","images":[],"step":3},{"description":"Heat oil in a heavy based pot over high heat. (Note 1)","images":[],"step":4},{"description":"Brown the chicken all over as best you can. I find the easiest way to do this (and minimising skin tearing) is with tongs stuck in the rear of the chicken and a wooden spoon to lift and leverage the chicken. Tilt the chicken as required to brown as much of the skin as you can. (Note 2)","images":[],"step":5},{"description":"If you can manage it (or if you have a helper), pour the excess fat out of the pot with the chicken still in it. If you can''t, remove the chicken onto a plate, then drain the fat.","images":[],"step":6},{"description":"Add the remaining ingredients into the pot (return the chicken to the pot if you removed it).","images":[],"step":7},{"description":"Bake covered for 40 minutes, then bake uncovered for 50 minutes (1.5 hrs in total).","duration":40,"images":[],"step":8},{"description":"Let stand for 5 minutes or so before removing the chicken from the pot onto a serving plate. Serve the sauce on the side. I prefer not to strain it because I want the bits of curd and garlic on my chicken, as well as bits of sage.","duration":5,"images":[],"step":9}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","most-popular","one-pot-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3d5303811ee5', 'en', 'US', 'Festive Christmas Roast Duck with Apple Cider Drizzle', 'An easy roast duck with crispy skin rubbed with Christmas inspired spices and accompanied with a light Apple Cider Drizzle. Easy to make, easy on the wallet, and a fabulous centrepiece for any festive gathering. Unlike other poultry, duck reheats really well - it remains juicy and the skin crisps up wonderfully as well. So this recipe is great to make ahead.', 'https://www.recipetineats.com/tachyon/2014/12/DSC_0460.jpg', 15, 90, 105, 10, '[{"id": "ing_whole_duck", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.2, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_chicken", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.125, "unit": "bottle of 500ml"}}, {"id": "ing_apples", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.2, "unit": "jar of 50g"}}, {"id": "ing_few_handfuls_of_rocket_arugula_leaves", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_pomegranate", "quantity": {"value": 1.0, "unit": "kg"}}]', '[{"ingredients":["1 whole duck (around 2 - 2.5 kg) (if frozen, it must be thawed) (Note 1)","1 onion ((brown, yellow or white), unpeeled and quartered)","1 cup water","1 whole head of garlic (, cut in half horizontally)"]},{"ingredients":["2 tsp garlic powder","1 tsp onion powder","1 tsp cinnamon powder","1 tsp All Spice powder","1 tbsp salt","10 grinds black pepper","1 1/2 tbsp unsalted butter (, softened (Note 2))"],"purpose":"Spice Rub"},{"ingredients":["1 cup chicken broth/stock (or duck broth, which is better but more expensive and harder to find)","1/4 cup apple cider vinegar (Note 3)","1/2 cup apple juice","Salt and pepper"],"purpose":"Apple Cider Drizzle"},{"ingredients":["Few handfuls of rocket / arugula leaves","1 pomegranate (, halved)"],"purpose":"Garnish"}]', '[{"description":"Preheat oven to 210C/410C.","images":[],"step":1},{"description":"Place the onion, garlic and water in a baking dish, then place a rack on top.","images":[],"step":2},{"description":"Rinse the duck under water, including inside the cavity. Use paper towels to pat dry. Or, if you have the foresight, rinse it the night before and leave it in the fridge overnight, uncovered, to dry out.","images":[],"step":3},{"description":"Place the Spice Rub in a small bowl and mix to combine.","images":[],"step":4},{"description":"Slather the Spice Rub all over the skin of the duck (not inside). Use most of it on the top and sides.","images":[],"step":5},{"description":"Place duck on the rack and put in the oven. Roast for 20 minutes, then turn down the oven to 180C/350F. The total roasting time (including the initial 20 minutes) should be 40 minutes per 1 kg / 20 minutes per 1 lb of duck.","duration":20,"images":[],"step":6},{"description":"To check if it is done, insert a skewer into the part where the leg meets the breast. If the juice runs clear, it is ready.","images":[],"step":7},{"description":"Remove duck from the oven. Remove duck from the baking tray, loosely cover with foil and let it rest for 20 minutes.","duration":20,"images":[],"step":8},{"description":"Place on a bed of rocket/arugula lettuce. Scatter with pomegranate seeds (Note 4) and serve with the Apple Cider Drizzle on the side.","images":[],"step":9},{"description":"Apple Cider Drizzle","images":[],"step":10},{"description":"Pour all the fat, juice, onion and garlic in the baking tray through a sieve placed over a bowl. Use a spoon or potato masher to mush the onion and garlic so you can extract maximum flavour.","images":[],"step":11},{"description":"If there is an excessive amount of fat floating on top of the juices, try to spoon it off (save it for roasting potatoes or vegetables, that stuff is gold!).","images":[],"step":12},{"description":"Pour 1/4 cup of the juices into a small saucepan. Add apple cider vinegar, apple juice, chicken broth and place over medium heat. Bring to simmer and let it simmer for 2 to 3 minutes until it reduces by about 1/4, then remove from the stove.","duration":2.5,"images":[],"step":13},{"description":"Season to taste with salt and pepper. Also, adjust tartness and sweetness to your taste with more apple cider vinegar or white sugar.","images":[],"step":14},{"description":"Serve on the side of the duck.","images":[],"step":15}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Festive"],"categories":["chicken-recipes","dietary","duck","gluten-free-recipes","main-dishes","roasts"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_63c3e150ea5c', 'en', 'US', 'Chicken & Green Vegetable Pilaf (One Pot Dinner)', 'A complete meal in one-pot, loaded with vegetables! Unintentionally healthy at only 370 calories per serving.', 'https://www.recipetineats.com/tachyon/2014/10/DSC_0159.jpg', 7, 15, 22, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_zucchini", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_es_asparagus", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_frozen_peas", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_cheese", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.438, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}]', '[{"ingredients":["300g (10oz) chicken breast (1 large one) (see notes)","2 tbsp olive oil","1 brown onion (, diced)","2 garlic cloves (, minced)","3 zucchinis (, cut into 1.5cm/0.5cm cubes)","3 bunches asparagus (, cut into 5cm/2 inch pieces)","1 small lemon","2 cups frozen peas","60g (2oz) feta cheese (, crumbled (see notes))","1 cup long grain or basmati rice (, uncooked (see notes for substitutes))","1 3/4 cups chicken stock (broth)","Salt and pepper"]},{"ingredients":["Parsley (, finely chopped)","Wedges of lemon"],"purpose":"Optional - to serve"}]', '[{"description":"Heat olive oil in a large pot (preferably non stick) over medium high heat. Add the garlic and onion and sauté until the onion is softened and starting to brown - about 2 minutes.","images":[],"step":1},{"description":"Add rice and stir to coat the grains with the oil, then add chicken stock. Bring to simmer then turn down heat to medium low.","images":[],"step":2},{"description":"Place chicken on top of the rice (partially submerged), then cover pot and cook for 5 minutes.","duration":5,"images":[],"step":3},{"description":"Remove lid and add peas and zucchinis (don''t stir, just scatter them across the top), then cover and cook for a further 5 to 8 minutes until most of the water has been absorbed and the rice is just slightly undercooked. It might take longer if you are using a smaller pot.","images":[],"step":4},{"description":"Remove the chicken and set aside to rest for a few minutes. Scatter the asparagus over the top, then place the lid back on and cook for 1 to 2 minutes until rice is al dente (cooked but still firm to touch), then remove the pot from the stove and let stand for 5 minutes.","duration":1.5,"images":[],"step":5},{"description":"Shred the chicken with a fork (or your fingers, if cool enough), then add back into the pot with the resting rice.","images":[],"step":6},{"description":"Season to taste with salt and pepper. Squeeze juice of the lemon over the rice.","images":[],"step":7},{"description":"Gently stir the rice to fluff it up and toss the ingredients through.","images":[],"step":8},{"description":"Spoon onto serving plates, scatter with feta and parsley (if using), and lemon wedges on the side.","images":[],"step":9}]', '["milk"]', '["gluten_free","high_protein","low_calorie"]', '{"mealType":["main_course"],"cuisine":[],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","one-pot-recipes","quick-and-easy","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5a818b0da846', 'en', 'US', 'Syrian Chicken', 'This is a simple but exotic dish of chicken with a spiced crispy skin baked with a rich tomato broth. It is served with Giant Couscous (also known as Moghrabieh, Israeli or Pearl Couscous) which can be substituted with ordinary couscous, pasta (risoni/orzo), rice, polenta or even mashed potato.', 'https://www.recipetineats.com/tachyon/2014/10/Syrian-Chicken-with-Giant-Couscous-12-Version-4.jpg', 15, 30, 45, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.907, "unit": "kg"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_ginger", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_chilli", "quantity": {"value": 2.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_tomato", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_saffron_powder", "quantity": {"value": 0.625, "unit": "jar"}}, {"id": "ing_thyme", "quantity": {"value": 0.12, "unit": "bunch"}}, {"id": "ing_currants", "quantity": {"value": 0.25, "unit": "unit"}}, {"id": "ing_giant_couscous", "quantity": {"value": 226.8, "unit": "pack"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}]', '[{"ingredients":["2 tbsp olive oil","2 lb / 1 kg chicken thigh fillets (, bone in and skin on (4 to 5 pieces) (see notes))"]},{"ingredients":["1 tsp cumin powder","1 tsp cinnamon powder","1 tsp salt","Black pepper"],"purpose":"Chicken Spices"},{"ingredients":["1 1/2 tbsp fresh ginger (, finely chopped)","3 garlic cloves (, minced)","1 onion (, halved and finely sliced)","2 birds eye chilis (, finely chopped (or to taste) (see notes))","1/4 cup (combined) mint and coriander leaves, roughly chopped","2 tbsp lemon juice","14 oz / 400 g canned crushed tomato","1 cup chicken stock / broth","1/8 tsp saffron powder (see notes)","1/2 tsp cumin powder","3 sprigs of thyme or 1 tsp dried thyme leaves","1/4 cup dried currants or sultanas (optional) (see notes)"],"purpose":"Sauce"},{"ingredients":["8 oz / 250 g giant couscous (Israeli or Pearl Couscous)","Yoghurt (optional)"],"purpose":"To Serve"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Place chicken on a plate or in a large bowl. Sprinkle with Chicken Spices and use your hands to coat the chicken.","images":[],"step":2},{"description":"Heat olive oil in a large, oven proof fry pan over high heat.","images":[],"step":3},{"description":"Add chicken, skin side down, and sear until the skin is nicely browned. Turn chicken over and cook the other side until browned. Remove chicken from pan. Drain pan of excess oil.","images":[],"step":4},{"description":"Add onion, garlic, ginger and chili into the pan. Saute for 2 minutes until the onion is translucent and starting to brown.","duration":2,"images":[],"step":5},{"description":"Add canned tomato, chicken stock/broth, saffron powder, cumin powder and thyme. Bring to simmer, then turn the stove off. Nestle the chicken into the tomato broth, then cover with foil (or lid) and place into the oven. Bake for 25 to 35 minutes.","duration":30,"images":[],"step":6},{"description":"Meanwhile, cook the Giant Couscous according to packet instructions. Usually it just needs to be boiled in salted water for around 4 minutes, then drain it.","images":[],"step":7},{"description":"When the chicken is dark golden brown and cooked, remove from oven. Stir through dried currents (if using), lemon juice and half the mint and coriander. Then sprinkle over remaining mint and coriander.","images":[],"step":8},{"description":"Serve on Giant Couscous with a dollop of yoghurt, if using.","images":[],"step":9}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Mediterranean","Middle Eastern","Syrian"],"categories":["chicken-recipes","dinner-tonight","main-dishes","mediterranean-recipes","most-popular","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b272c4499d40', 'en', 'US', 'Hawaiian Chicken', 'This finger lickin'' good chicken is marinated in a sweet, tangy and spicy pineapple glaze! Perfectly matched with coconut rice.', 'https://www.recipetineats.com/tachyon/2014/10/Sticky-Hawaiian-Chicken-with-Coconut-Rice-1.jpg', 15, 50, 65, 4, '[{"id": "ing_chicken", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_pineapple", "quantity": {"value": 440.0, "unit": "unit"}}, {"id": "ing_tomato", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.5, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_onion", "quantity": {"value": 15.0, "unit": "pack of 1kg"}}, {"id": "ing_cumin", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_chilli", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_rice", "quantity": {"value": 150.0, "unit": "pack"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.625, "unit": "can of 400ml"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_desiccated_coconut", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1.5 kg / 3lb chicken drumsticks","2 tbsp olive oil"]},{"ingredients":["440 g / 15 oz can crushed pineapple in natural juice (about 1.5 cups) (see notes)","1/2 cup tomato sauce or ketchup","1/2 cup light soy sauce (see notes)","4 tbsp brown sugar","2 tbsp malt vinegar (see notes)","1 tsp fresh ginger (, grated)","3 garlic cloves (, minced)","1 tbsp paprika powder","1 tbsp dried onion flakes","1/2 tbsp cumin powder","1/2 tsp chili powder ((or cayenne powder). Adjust to taste.)","Black pepper"],"purpose":"Marinade Glaze"},{"ingredients":["1 cup long grain or medium grain rice (, uncooked)","1 cup coconut milk (see notes)","1 cup water","1/2 tsp salt","3/4 tsp sugar"],"purpose":"Coconut Rice"},{"ingredients":["Lime wedges (, to serve)","Coriander/cilantro leaves (, for garnish on rice and chicken)","Toasted desiccated coconut (, for garnish on rice)"],"purpose":"Optional Garnish"}]', '[{"description":"Marinate the Chicken","images":[],"step":1},{"description":"Combine the Marinade Glaze ingredients in a saucepan over medium high heat. Bring to simmer, then turn it down to medium for 10 minutes or so until it reduced by around 1/3 and is a bit syrupy. The pineapple should be softened and starting to breakdown. Give it a mush with a potato masher to help it along.","duration":10,"images":[],"step":2},{"description":"Allow Marinade Glaze to cool, then combine in a large ziplock bag or bowl with the chicken.","images":[],"step":3},{"description":"Marinate for at least 4 hours, up to 24 hours. You could also freeze the chicken with the marinade.","images":[],"step":4},{"description":"Cook the Chicken","images":[],"step":5},{"description":"Preheat oven to 180C/350F.","images":[],"step":6},{"description":"Bring the chicken to room temperature.","images":[],"step":7},{"description":"Dip the chicken and Marinade into a baking dish.","images":[],"step":8},{"description":"Drizzle over olive oil then spoon over some of the Marinade Glaze onto the drumsticks, ensuring you get some pineapple chunks on the chicken itself.","images":[],"step":9},{"description":"Place chicken in the oven and bake for 20 minutes. Remove baking tray from oven and turn the chicken and again spoon the marinade & pineapple bits onto the chicken.","duration":20,"images":[],"step":10},{"description":"Bake for a further 15 minutes and check the chicken. If the marinade pooled in the baking dish is looking dry and starting to burn, then pour in a bit of water.","images":[],"step":11},{"description":"Return chicken to the oven and bake until dark golden brown and the Marinade Glaze is caramelised and sticky (about 5 to 10 minutes).","images":[],"step":12},{"description":"Combine ingredients in a saucepan over high heat. Cover with a lid and bring to boil.","images":[],"step":13},{"description":"Turn down heat to low then leave to simmer for 15 to 18 minutes until all the liquid has been absorbed.","duration":16.5,"images":[],"step":14},{"description":"Remove from heat and allow to rest for at least 5 minutes before serving.","images":[],"step":15},{"description":"To Serve","images":[],"step":16},{"description":"Garnish rice with tasted desiccated coconut (optional).","images":[],"step":17},{"description":"Scatter coriander/cilantro over rice and chicken and serve with lime wedges on the side.","images":[],"step":18}]', '["gluten","soy"]', '["high_protein"]', '{"mealType":["main_course"],"cuisine":["Hawaiian"],"categories":["chicken-breast-recipes","chicken-drumstick-recipes","chicken-recipes","dietary","gluten-free-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8aa7f57dee10', 'en', 'US', 'Quick Chicken Pot Pie', 'This is how you make a pie from scratch in 20 minutes!', 'https://www.recipetineats.com/tachyon/2014/09/Free-form-chicken-pot-pie-21.jpg', 5, 10, 15, 4, '[{"id": "ing_sheet_puff_pastry_thawed", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_bacon", "quantity": {"value": 2.0, "unit": "pack of 200g"}}, {"id": "ing_marsala", "quantity": {"value": 0.25, "unit": "unit"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_frozen_mixed_peas", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_broccoli", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_cheese", "quantity": {"value": 0.5, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1 sheet puff pastry ((25cm x 25cm / 10\" x 10\"), thawed)","Oil spray","2 tbsp butter","400 g/13oz chicken thigh fillets ((or tenderloin or breast), cut into small bite size pieces)","1 onion ((small, brown, white or yellow), diced)","2 garlic cloves (, minced)","2 bacon rashers (, diced)","1/4 cup marsala (or dry sherry, port or white wine) (see notes)","2 tbsp plain flour","2 cups frozen mixed peas (, corn and carrots, thawed)","2 cups small broccoli florets (see notes)","2 cups milk (full cream or low fat)","1/2 cup grated cheese (any cheese that melts. I used tasty)","1/4 tsp salt (plus more to taste)","Black pepper"]}]', '[{"description":"Preheat oven to 200C/390F. Lightly spray baking tray with oil.","images":[],"step":1},{"description":"Cut puff pastry into 4 pieces and place on baking tray. Bake for 15 minutes until puffed and golden. Remove from oven and set aside.","duration":15,"images":[],"step":2},{"description":"Meanwhile, melt butter in large pan over high heat.","images":[],"step":3},{"description":"Add onion and garlic cloves and sauté for 1 minute.","duration":1,"images":[],"step":4},{"description":"Add bacon and chicken and cook for 2 to 3 minutes until chicken is lightly browned but still not cooked through inside.","duration":2.5,"images":[],"step":5},{"description":"Add marsala and cook for 30 seconds to allow the alcohol to cook out. Most of the marsala should evaporate.","duration":0.5,"images":[],"step":6},{"description":"Add the broccoli, peas, corn and carrots and stir to combine.","images":[],"step":7},{"description":"Sprinkle the flour over and add milk, stirring to dissolve the flour into the milk.","images":[],"step":8},{"description":"Bring to simmer then stir through cheese, salt and pepper. Adjust salt to your taste.","images":[],"step":9},{"description":"Simmer, stirring for 30 seconds to 1 minute until the sauce is thickened, then remove from heat.","duration":0.5,"images":[],"step":10},{"description":"To serve, divide the chicken filling between 4 plates and top with a piece of puff pastry.","images":[],"step":11}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["main_course"],"cuisine":[],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0854006252cb', 'en', 'US', 'Caesar Salad Wonton Cups', 'Everything tastes better in miniature form!', 'https://www.recipetineats.com/tachyon/2014/08/Caesar-Salad-Wonton-Cups-3.jpg', 20, 10, 30, 12, '[{"id": "ing_wonton_wrappers", "quantity": {"value": 12.0, "unit": "unit"}}, {"id": "ing_lettuce", "quantity": {"value": 7.5, "unit": "head"}}, {"id": "ing_chicken", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 1.5, "unit": "pack of 200g"}}, {"id": "ing_bread", "quantity": {"value": 0.047, "unit": "loaf"}}, {"id": "ing_parmesan", "quantity": {"value": 0.15, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_fish_fillets", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.375, "unit": "jar of 400g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.15, "unit": "pack of 200g"}}, {"id": "ing_milk", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["12 wonton wrappers","2 1/2 cups cos/romaine lettuce (, shredded)","1 cup cooked chicken (, diced)","1 1/2 bacon rashers (, diced)","1/4 cup bread (, diced finely (preferably stale))","2 tbsp parmesan cheese (, freshly grated)","2 tsp fresh parsley (, finely chopped (optional - for garnish))","Salt","Olive oil spray"]},{"ingredients":["1 garlic clove (, minced)","2 anchovy fillets","2 tbsp fresh lemon juice","1 tsp Dijon mustard","1 tsp Worcestershire sauce","1 cup mayonnaise (, preferably whole egg)","1/2 cup freshly grated parmesan cheese","Milk (, to adjust consistency)","1/4 tsp salt","Black pepper"],"purpose":"Dressing"}]', '[{"description":"Preheat oven to 180C/350F. Fit the wonton wrappers into each hole of a standard size muffin / cupcake tin (not mini and not Texas muffin tins!). Spray the wontons lightly with olive oil. Bake for 8 to 12 minutes, until golden and crispy. Remove from oven and set aside to cool.","duration":10,"images":[],"step":1},{"description":"Heat a small non stick pan over high heat. Spray with oil, add bacon and sauté until crispy, then remove and drain on absorbent paper towel.","images":[],"step":2},{"description":"Return pan to stove, reduce heat to medium high and spray pan with oil. Add finely diced bread. Shake pan (or stir) to brown evenly. Remove mini croutons from pan, scatter over a pinch of salt and set aside.","images":[],"step":3},{"description":"Place Dressing ingredients in a blender or food processor and whizz until smooth. If it seems too thick, use a tiny splash of milk to adjust the consistency.","images":[],"step":4},{"description":"Place cos lettuce, chicken and bacon in a bowl with 6 to 8 tbsp of dressing (depending on how much dressing you want to use) and toss gently to combine.","images":[],"step":5},{"description":"Divide the salad between the wonton cups, top with croutons, a pinch of parmesan and a sprinkle of parsley.","images":[],"step":6},{"description":"Serve immediately.","images":[],"step":7}]', '["egg","fish","gluten","milk","mustard"]', '["keto_friendly","low_calorie"]', '{"mealType":["snack"],"cuisine":[],"categories":["chicken-breast-recipes","chicken-recipes","finger-food","most-popular"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_aa5bb9720836', 'en', 'US', 'Mid Week Paella', 'A fast and easy midweek version of Paella that''s full of flavour! I added spinach to make it a complete one pot meal but this is optional.', 'https://www.recipetineats.com/tachyon/2014/08/Midweek-Paella-4.jpg', 10, 20, 30, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_chorizo", "quantity": {"value": 0.18, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_spinach", "quantity": {"value": 2.0, "unit": "bag of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_frozen_peas", "quantity": {"value": 0.333, "unit": "unit"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_rice", "quantity": {"value": 150.0, "unit": "pack"}}, {"id": "ing_parsley", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 1.0, "unit": "jar of 50g"}}]', '[{"ingredients":["1 tbsp olive oil","350 g / 12 oz chicken thigh fillets (, cut into 8 pieces)","180 g / 6oz chorizo (, the best you can afford. I like to use a spicy one. (Note 3))","1 small brown onion (, diced)","1 small red capsicum / bell pepper (, roughly diced)","2 cups (packed) shredded spinach (optional - see Note 1)","2 garlic cloves (, minced)","1 can (400g/14oz) crushed tomato","1 1/2 cups chicken stock/broth","1/3 cup frozen peas","1 tsp paprika","1 cup spanish calasparra rice (Note 2)","1 1/2 tbsp parsley (, finely chopped)","Salt and pepper"]}]', '[{"description":"Cut chorizo into quarters vertically, then slice into 0.5cm / 1/3 inch pieces.","images":[],"step":1},{"description":"Season chicken with salt and pepper.","images":[],"step":2},{"description":"Heat olive oil in pan over high heat. Add chicken and sear each side until golden brown, but not cooked through. It will finish cooking with the rice. Remove chicken from the pan onto a plate and set aside.","images":[],"step":3},{"description":"Place garlic, onion and chorizo in pan. The chorizo will release oil so you don''t need extra oil. Stir and cook for 1 minute until the chorizo starts to brown.","duration":1,"images":[],"step":4},{"description":"Add capsicum, then stir and cook for 1 minute until chorizo is dark golden brown.","duration":1,"images":[],"step":5},{"description":"Add rice and stir until coated with the oil.","images":[],"step":6},{"description":"Add chicken stock, tinned tomato, spinach, half the peas and paprika. Stir gently to mix, bring to simmer then turn down heat to medium high so the stock remains at a gentle simmer.","images":[],"step":7},{"description":"Place the chicken into the pan, mostly submerged.","images":[],"step":8},{"description":"Cook, without stirring, for 10 minutes. Then scatter the remaining peas over the top and continuing cooking for a further 5 minutes until most of the liquid is absorbed and the rice is cooked but it should still be slightly firm (al dente).","duration":10,"images":[],"step":9},{"description":"Remove from heat and let stand for 5 minutes. Any residual liquid will be absorbed while it is resting.","duration":5,"images":[],"step":10},{"description":"Scatter with parsley and serve.","images":[],"step":11}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["main_course"],"cuisine":["Spanish"],"categories":["chicken-recipes","mediterranean-recipes","one-pot-recipes","quick-and-easy","spanish-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c764a49c0479', 'en', 'US', 'Cobb Salad', 'Recipe video above. The mighty Cobb Salad! Don''t skip the blue cheese. It''s what makes this a Cobb Salad, and not just another chicken salad. :) Love the presentation on a big platter with the ingredients in neat rows. Serve Dressing on the side for everyone to help themselves (better than tossing each item individually).', 'https://www.recipetineats.com/tachyon/2023/08/Cobb-Salad_0.jpg', 15, 20, 35, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_bacon", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_egg", "quantity": {"value": 4.0, "unit": "carton of 12"}}, {"id": "ing_lettuce", "quantity": {"value": 36.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_avocado", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_gorgonzola_dolce_or_roquefort", "quantity": {"value": 200.0, "unit": "unit"}}, {"id": "ing_chives", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.075, "unit": "L"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.15, "unit": "bottle of 500ml"}}, {"id": "ing_green_onion", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}]', '[{"ingredients":["400g/14 oz chicken breast (2 pieces)","1/4 tsp cooking/kosher salt","1/4 tsp black pepper"],"purpose":"Chicken:"},{"ingredients":["200g/7oz streaky bacon strips","4 x 9 minute boiled eggs (, quartered)","12 cups cos / romaine lettuce (1 large head, 2 small), chopped (or other crispy lettuce)","2 large tomatoes (, cut into 8 wedges then halved (or 250g/8oz cherry tomatoes halved))","2 avocados (, cut into large pieces)","200g/7oz gorgonzola dolce (my favourite) or roquefort (traditional), ( crumbled (or other blue cheese - Note 1))","2 tbsp chives (, finely chopped)"],"purpose":"Cobb Salad:"},{"ingredients":["1 tbsp dijon mustard","5 tbsp extra virgin olive oil","5 tbsp apple cider vinegar (sub white wine or red wine vinegar)","3/4 tsp cooking/kosher salt","1/4 tsp black pepper","2 tbsp eschallot ((US: shallot), very finely minced)","1/2 tsp white sugar"],"purpose":"Dressing:"}]', '[{"title":"Dressing","description":"Shake ingredients in a jar.","images":[],"step":1},{"title":"Flavour chicken","description":"Poach chicken using this method (20 minute foolproof-guaranteed-juicy). Cool to room temperature then cut into 2cm / 0.75” cubes. Toss with salt, pepper and 2 tablespoons of Dressing. Set aside.","images":[],"step":2},{"title":"Crisp bacon","description":"Place bacon strips in a non-stick pan (not heated, no oil). Turn heat onto medium high - as the pan heats up, the fat will begin to melt. Cook for 2 minutes until golden, turn and cook the other side for 1 1/2 minutes until golden. Drain on paper towels. Once cool and crisp, chop into 1.5cm / 0.6\" pieces.","duration":2,"images":[],"step":3},{"title":"Assemble","description":"Spread lettuce on a large platter. Arrange the ingredients on top in the Cobb Salad signature neat rows: egg, bacon, avocado, tomato and chicken. Crumble blue cheese across the top, sprinkle with chives. Pour dressing into a jug.","images":[],"step":4},{"title":"Serving","description":"Let everybody help themselves to the salad and Dressing!","images":[],"step":5}]', '["egg","milk","mustard"]', '["gluten_free","high_protein"]', '{"mealType":["dinner","lunch"],"cuisine":["American","Western"],"categories":["chicken","chicken-breast-recipes","mains","no-cook-food","salad-recipes-main-course"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_abcdc991d0d4', 'en', 'US', 'Duck Confit - French slow roasted duck legs', 'Recipe video above. A traditional recipe for Duck Confit from a French chef! Called Confit de Canard in French, duck legs are slow-cooked in duck fat until the meat is meltingly tender, then the skin crisped to golden perfection. This Duck Confit recipe is low-effort and DOESN''T require buckets of duck fat! Simple, yet a lusciously indulgent dish worthy of gracing restaurant tables. This might just be the ultimate dish for a low-stress dinner party or treating your loved ones!Recipe courtesy of our resident French Chef Jean-Baptiste Alexandre. Meet Chef "JB" here.', 'https://www.recipetineats.com/tachyon/2021/06/Duck-Confit-photo-_8.jpg', 15, 530, 545, 4, '[{"id": "ing_x_250g_duck_legs", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_duck_fat", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sage", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_rosemary", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 10.0, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.3, "unit": "jar of 50g"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_star_anise", "quantity": {"value": 8.0, "unit": "jar"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_juniper_berries", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_s", "quantity": {"value": 8.0, "unit": "pack"}}]', '[{"ingredients":["4 x 250g / 8oz duck legs (, skin on, bone in (aka maryland); (Note 1))","750 ml / 25 oz duck fat (Note 2)"],"purpose":"Duck:"},{"ingredients":["4 tsp cooking/kosher salt (Note 4)","1/3 cup thyme sprigs (, lightly packed)","1/3 cup sage sprigs (, lightly packed)","1/3 cup rosemary sprigs (, lightly packed)","1/3 cup oregano sprigs (, lightly packed)","6 cloves garlic (, smashed with skin on)","1 eschalot ((US: shallot), peeled and sliced 0.7cm (1/3\") thick)","1 tbsp black peppercorns","1 tbsp coriander seeds","8 star anise","2 bay leaves","2 tbsp juniper berries","8 cloves"],"purpose":"Dry cure (Note 3):"}]', '[{"title":"Coat duck with dry cure","description":"Place duck legs and all the Dry Cure ingredients in a large bowl. Toss well with your hands.","images":[],"step":1},{"title":"Cure 12","description":"24 hrs: Transfer to a ceramic or glass dish large enough so the duck fits in a single layer but snugly. Cover and refrigerate for 12 - 24 hours (no longer is necessary).","images":[],"step":2},{"title":"Rinse","description":"Brush off cure and rinse duck under tap water to clean them (remove all salt and black bits). Pat dry with paper towels.","images":[],"step":3},{"description":"Slow cooking (confit):","images":[],"step":4},{"description":"Preheat oven to 100°C/210°F (80°C fan) with a shelf positioned in the middle of the oven.","images":[],"step":5},{"title":"Roasting pan","description":"Place duck in a small metal roasting pan with high sides. They should fit snugly, touching each other, but in a single layer. (Note 5)","images":[],"step":6},{"title":"Cover with duck fat","description":"Pour fat over duck. It should pretty much cover the legs. (Note 6)","images":[],"step":7},{"title":"Heat fat in pan","description":"Place pan on the stove over medium-high heat. Heat fat until bubbling energetically all across the surface (ie not just around the edges).","images":[],"step":8},{"title":"Cover with paper","description":"Turn off stove. Cover surface with baking / parchment paper, cut to size so it sits on the surface of the fat over the duck. Gently push down to remove air bubbles. Cover pan tightly with a double layer of foil.","images":[],"step":9},{"title":"Slow cook","description":"Carefully transfer to the oven. Cook for 8 hours.","images":[],"step":10},{"title":"Check flesh","description":"Remove one duck leg (gently). Turn over to check the flesh side – meat should be fall-apart tender. Leg should also give easily when pressure is applied to the joint (see video).","images":[],"step":11},{"description":"Storing cooked Duck Confit (optional):","images":[],"step":12},{"description":"Duck can be stored submerged in fat at this stage. The meat juice should be strained off first.","images":[],"step":13},{"description":"Remove duck to a non-reactive container in which they fit snugly. (Note 7) Pour over cooled duck fat, leaving juice sediment behind. Ensure it fully covers the duck (push duck under while warm and pliable as needed, using tongs).","images":[],"step":14},{"description":"Once fully cool, cover with lid and place in fridge (5 days) or freezer (3 months). Fat will solidify.","images":[],"step":15},{"description":"To cook, heat duck gently in a container in microwave to melt the fat. Proceed with recipe.","images":[],"step":16},{"description":"Crisping skin and finishing Duck:","images":[],"step":17},{"description":"Preheat oven to 240°C/465°F (220°C fan). Place a rack over a deep roasting pan.","images":[],"step":18},{"title":"Remove duck from fat","description":"Remove duck from fat, allowing excess oil to drip off. Pat excess oil off with paper towels.","images":[],"step":19},{"title":"Prepare for roasting","description":"Pour 2.5cm / 1\" of boiling water water into the roasting pan (steam keeps flesh moist). Place duck on rack, skin side up.","images":[],"step":20},{"title":"Crisp skin","description":"Roast duck for 40 minutes until the skin is a deep golden and crispy. Rotate pan as needed for even colour. (You won''t have problems with fat smoking as it drips into the water)","duration":40,"images":[],"step":21},{"title":"Serve","description":"Rest briefly to cool, and serve! A classic French side dish for Duck Confit is Lentil Ragout. (pictured in post)","images":[],"step":22}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["French"],"categories":["chicken","duck","iconic-dishes","mains","roasts","slow-cooked-fall-apart"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_223ef0e0e47f', 'en', 'US', 'Hot Chocolate Fudge Cake', 'Recipe video above. Think of it as a sliceable version of Chocolate Self Saucing Pudding - with a LOT more chocolate fudge sauce! The perfect cosy dessert for cool winter days that''s easy to make.', 'https://www.recipetineats.com/tachyon/2023/07/Hot-chocolate-fudge-cake_7-2.jpg', 15, 40, 55, 10, '[{"id": "ing_flour", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_cocoa_powder", "quantity": {"value": 0.2, "unit": "pack of 250g"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.025, "unit": "tub of 150g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.019, "unit": "tub of 200g"}}, {"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 75.0, "unit": "block of 250g"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_chocolate", "quantity": {"value": 1.25, "unit": "block of 100g"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}]', '[{"ingredients":["1 cup plain/all-purpose flour (Note 2)","1/3 cup cocoa powder ((unsweetened), sifted (Note 1)30g)","3/4 tsp baking powder (Note 2)","3/4 tsp baking soda/bi-carb (sifted if lumpy) (Note 2)","1 cup caster/superfine sugar (sub ordinary white sugar)","1/4 tsp salt"],"purpose":"Dry:"},{"ingredients":["1/2 cup milk (, full fat, at room temperature)","1/2 cup milk (, full fat, at room temperature)","75g / 5 tbsp unsalted butter (, melted and cooled slightly)","1 tbsp oil ((canola, veg or other neutral oil) - keeps cake moist for days)","1 tsp vanilla extract","1/2 cup boiling water"],"purpose":"Wet:"},{"ingredients":["1 cup thickened / heavy cream, or pure cream (not low fat, too thin)","1 1/4 cups dark chocolate melts or chips (US: semi-sweet chips) - or finely chopped 60 - 70% cocoa chocolate block (Note 3)"],"purpose":"Chocolate fudge sauce:"},{"ingredients":["Vanilla ice cream"],"purpose":"Serving:"}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan). Grease a 20cm/8\" cake pan with butter then line with paper.","images":[],"step":1},{"description":"Whisk Dry ingredients in a large bowl.","images":[],"step":2},{"title":"Add Wet","description":"Then add all the Wet ingredients EXCEPT the boiling water. Whisk until combined. Then add the boiling water and whisk until smooth. The batter will be pretty thin.","images":[],"step":3},{"title":"Bake 40 min","description":"Pour into the pan. Bake for 40 minutes or until a skewer inserted into the centre comes out mostly clean - a faint smear of batter isn''t a bad thing, we''re making a fudge cake here!","duration":40,"images":[],"step":4},{"description":"Cool in the pan for 10 minutes. Invert onto a plate, then onto a cooling rack or plate right side up. Cool for a further 10 minutes - the cake will still be warm for serving.","duration":10,"images":[],"step":5},{"title":"Serving","description":"Cut slices of the warm cake. Top with a scoop of ice cream. Douse with fudge sauce - just shy of 1/4 cup per slice (10 slices). Eat and swoon!","images":[],"step":6},{"description":"Chocolate fudge sauce (makes 2 cups):","images":[],"step":7},{"description":"Heat cream until hot, just before boiling point, using your method of choice - saucepan or microwave.","images":[],"step":8},{"title":"Stand 5 min","description":"Put chocolate in bowl. Pour over hot cream. Ensure all chocolate is submerged, then cover with a plate. Leave for 5 minutes.","duration":5,"images":[],"step":9},{"title":"Mix","description":"Using a whisk or rubber spatula, mix vigorously until the cream and chocolate combine into a silky chocolate sauce.","images":[],"step":10},{"description":"Cool to thicken for 20 minutes. Give it a stir then pour into a jug for serving!","duration":20,"images":[],"step":11}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["chocolate","puddings-cosy-desserts","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d65d5a10abaf', 'en', 'US', 'Birthday Cake', 'Recipe video above. With three layers of soft, buttery Vanilla Cake slathered with My Favourite Chocolate Frosting, this is the Birthday Cake I always wished I had as a kid. The kind every “normal” kid seemed to get, and I was quietly jealous of! The frosting is totally dreamy - rich chocolate flavour, way less sweet than buttercream, completely smooth, it tastes like the most delicious chocolate mousse you''ve ever had. The perfect all-rounder - spread, layer, pipe tall swirls, stays creamy even when refrigerated, rich but not overly so. Finish your cake with a generous shower of sprinkles. Because, birthdays! 🎉', 'https://www.recipetineats.com/tachyon/2026/04/Birthday-cake_0-1.jpg', 35, 22, 57, 12, '[{"id": "ing_flour", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 2.5, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 333.333, "unit": "carton of 12"}}, {"id": "ing_sugar", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 115.0, "unit": "block of 250g"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.3, "unit": "bottle of 50ml"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_chocolate", "quantity": {"value": 200.0, "unit": "block of 100g"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_cocoa_powder", "quantity": {"value": 0.15, "unit": "pack of 250g"}}, {"id": "ing_butter", "quantity": {"value": 115.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_cream_cheese", "quantity": {"value": 250.0, "unit": "block of 250g"}}]', '[{"ingredients":["2 cups plain / all purpose flour (Note 1)","2 1/2 teaspoons baking powder","1/4 tsp cooking salt (kosher salt) (halve for table salt, +50% for flakes)","4 large eggs (50 - 55g / 2 oz each), at room temp (Note 3)","1 1/2 cups caster / superfine sugar (granulated/regular ok too, Note 2)","115g / 1/2 cup unsalted butter (, cut into 1.5cm / 1/2” cubes (or so))","1 cup milk (, full fat (Note 5))","3 tsp vanilla extract","3 tsp vegetable or canola oil (, or other plain flavoured oil (Note 6))"],"purpose":"3 layer vanilla cake"},{"ingredients":["200g / 7 oz dark chocolate chips or melts (semi-sweet chocolate chips) (, or chopped block (Note 7))","3/4 cup thickened cream / heavy cream (, or other whipping cream 35 – 40% fat (Note 7))","1/4 cup dutch processed cocoa powder (no need to sift), or regular unsweetened cocoa powder (Note 8)","1/4 tsp cooking salt / kosher salt (halve for table salt, +50% for flakes)","100g / 7 tbsp unsalted butter (, softened)","2 cups (250g) soft icing sugar / powdered sugar (, sifted (Note 9))","250g / 8 oz Philadelphia cream cheese block (not tub) (, at room temperature (Note 10))","1/2 cup thickened cream / heavy cream (, for whipping, fridge cold (Note 7))"],"purpose":"My Favourite Chocolate Frosting"}]', '[{"title":"Vanilla cake","description":"Beat eggs and sugar until triple in volume, fold in flour. Whisk hot milk + butter + oil + vanilla, temper with bit of batter, then slowly beat into cake batter. Bake in 3 pans for 23 minutes, cool inverted then frost.","duration":23,"images":[],"step":1},{"title":"My Favourite Chocolate Frosting","description":"Bloom cocoa, mix into melted chocolate. Cream butter, beat in icing sugar, then cream cheese and chocolate mixture. Fridge 2 hours. Whip with cream. Use immediately.","images":[],"step":2},{"description":"Preheat oven to 180°C/350°F (160°C fan) for 20 minutes before starting the batter (Note 11). Place shelf in the middle of the oven.","duration":20,"images":[],"step":3},{"title":"Pans","description":"Grease 3 x 20cm / 8” cake pans with butter, then line with parchment / baking paper. Best to use cake pan without a loose base, if you can, as the batter is quite thin. (Note 12)","images":[],"step":4},{"title":"Dry ingredients","description":"Whisk flour, baking powder and salt in a large bowl. Set aside.","images":[],"step":5},{"title":"Beat eggs until triple","description":"Beat eggs for 30 seconds on speed 6 of a Stand Mixer fitted with a whisk attachment, or hand beater. With the beater still going, pour in the sugar over 45 seconds, then beat on speed 8 for 7 minutes until the eggs triple in volume and become white.","duration":0.5,"images":[],"step":6},{"title":"Heat Milk-Butter","description":"While egg is beating, place butter and milk in a heatproof jug and microwave 2 minutes on high until the milk is hot and butter is melted (or use stove). Don''t let the milk boil over.","images":[],"step":7},{"title":"Add flour in 3 batches","description":"When the egg is whipped, add the flour in 3 batches beating for 5 seconds on Speed 1 in between. Once all the flour is in, beat for another 5 - 10 seconds until you can''t see any flour, then stop beating straight away.","duration":0.08333333333333333,"images":[],"step":8},{"title":"Combine milk, vanilla & oil with batter","description":"Pour hot milk, vanilla and oil into the now empty flour bowl. Add about 1 1/2 cups of cake batter into the hot milk bowl (no need to be 100% accurate with amount). Whisk vigorously using a handheld whisk until smooth and a bit foamy.","images":[],"step":9},{"title":"Slowly beat in milk","description":"Turn beater back on Speed 1 then pour the Milk mixture into the cake batter over 15 seconds, then turn beater off.","images":[],"step":10},{"title":"Scrape and final mix","description":"Scrape down sides and base of bowl. Beat on Speed 1 for 10 seconds - batter should now be smooth and pourable.","duration":0.16666666666666666,"images":[],"step":11},{"description":"Divide batter between three pans (370g / 13 oz batter per pan). Bang each cake pan on the counter 3 times to knock out big bubbles (Note 13).","images":[],"step":12},{"description":"Bake 23 minutes or until golden and toothpick inserted into centre comes out clean.","images":[],"step":13},{"title":"Cool","description":"Remove pans from oven. Cool in cake pans for 15 minutes, then gently turn out onto cooling racks. Cool upside down - slight dome will flatten perfectly. Level cake = neat layers.","duration":15,"images":[],"step":14},{"title":"Refrigerate","description":"Once fully cool on the counter, refrigerate for 30 minutes before frosting (makes it easier to frost as cake is firmer when cold).","duration":30,"images":[],"step":15},{"title":"Frost","description":"Use the cake layers upside for flat surfaces. Spread 1 cup Chocolate Frosting on each layer, then frost the sides and surface generously. Use leftover frosting to pipe decorative swirls on the top.","images":[],"step":16},{"description":"Sprinkle! Decorate with sprinkles as desired. How I decorate the base - place sprinkles around the base, then use a butter knife to scoop them up and press onto the sides. See video for visual demo.","images":[],"step":17},{"description":"Chocolate Frosting:","images":[],"step":18},{"title":"Bloom cocoa","description":"Heat the cream in a heatproof bowl until hot but make sure it doesn''t come to a boil. Add cocoa powder and whisk until lump free – it will be like a thin paste. Set aside 5 minutes to bloom (brings out chocolate flavour).","images":[],"step":19},{"title":"Melt chocolate","description":"Place the chocolate chips in a heatproof bowl and melt in the microwave in bursts until smooth – 30 seconds on high, stir, then 20 second increments.","images":[],"step":20},{"title":"Chocolate paste","description":"Add the cocoa paste into the melted chocolate. Whisk until combined and smooth, it will be like a thin paste. Cool for 15 minutes on the counter – it will thicken. Don''t worry if a skin forms on the surface, it will beat out in the next step.","duration":15,"images":[],"step":21},{"title":"Cream cheese whip","description":"In a separate large bowl, beat butter with a handheld mixer until soft and fluffy (about 1 1/2 minutes on high). Add icing sugar and beat until sandy and no large butter lumps remain (~ 30 seconds). Add cream cheese and beat until smooth and creamy (~30 seconds), stopping once no yellow butter bits remain.","images":[],"step":22},{"title":"Beat in chocolate","description":"Add all the chocolate paste and beat until combined. Taste. Yum!","images":[],"step":23},{"title":"Refrigerate","description":"Cover the bowl with cling wrap and refrigerate for 2 hours until properly fridge-cold (stick the beaters in the bowl). You can leave it in the fridge at this point for days.","images":[],"step":24},{"title":"Fluff frosting","description":"Remove bowl from the fridge. Add the 1/2 cup of cream and salt. Beat on high for 1 1/2 minutes or until you have stiff peaks (ie upright Santa hats, not floppy elf hat). The frosting should be beautifully creamy like buttercream but fluffy like whipped cream. Use immediately (see My Favourite Chocolate Frosting full recipe for notes on keeping, shelf life, etc)","images":[],"step":25}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["classic-cakes","iconic-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5a9d125348ac', 'en', 'US', 'Black Forest Cake (Schwarzwälder Kirschtorte)', 'Recipe video above. The most German of cakes: Black Forest Cake! You''ll love how this cake''s layers are lovely and moist (too often they are terribly dry!), and how this Black Forest Cake is not too sweet so you can actually taste all the elements. TIP: Though it seems a shame not to use fresh cherries when they''re in season, using jarred or canned cherries in between sponge layers really does work better. They''re softer so texturally they make more sense, plus the flavoured syrup from the jar is perfect to brush the cake layers.You MUST make this cake at least 4 hours ahead or even better, overnight, for flavours to develop!', 'https://www.recipetineats.com/tachyon/2021/05/Black-Forest-Cake-new_7.jpg', 40, 60, 100, 12, '[{"id": "ing_egg", "quantity": {"value": 500.0, "unit": "carton of 12"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_cocoa_powder", "quantity": {"value": 0.3, "unit": "pack of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 150.0, "unit": "block of 250g"}}, {"id": "ing_cherries", "quantity": {"value": 1.34, "unit": "pack of 500g"}}, {"id": "ing_cherries", "quantity": {"value": 1.34, "unit": "pack of 500g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.05, "unit": "pack of 400g"}}, {"id": "ing_cream", "quantity": {"value": 4.0, "unit": "carton of 250ml"}}, {"id": "ing_vanilla", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_sugar", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_chocolate", "quantity": {"value": 100.0, "unit": "block of 100g"}}, {"id": "ing_cherries", "quantity": {"value": 1.34, "unit": "pack of 500g"}}]', '[{"ingredients":["6 large eggs (, at room temperature (Note 7))","1 tsp vanilla extract","1 1/4 cup caster sugar (superfine sugar)","1/2 cup dutch processed cocoa powder (or unsweetened regular cocoa power, Note 1)","2/3 cup plain flour (all-purpose flour)","150g / 10.5 tbsp unsalted butter (, melted and cooled)"],"purpose":"Chocolate Cake:"},{"ingredients":["670g / 23.5 oz pitted morello cherries in syrup (sour cherries, in jar or can) (, drained and juice reserved (Note 2))","1/3 cup kirsch or cherry liqueur (optional – sub with more reserved cherry juice, Note 3)","1/2 cup caster sugar (superfine sugar)","4 tsp cornflour / cornstarch"],"purpose":"Cherry Syrup:"},{"ingredients":["4 cups / 1 litre thickened / heavy cream (Note 4)","2 tsp vanilla","1/3 cup soft icing sugar / powdered sugar (Australia: Not pure icing sugar, Note 5)","100g / 3.5 oz dark chocolate / bittersweet chocolate","12 maraschino or fresh cherries (for decorating top of cake)"],"purpose":"Decorating:"}]', '[{"description":"Chocolate sponge cake layers:","images":[],"step":1},{"title":"Oven and cake pans","description":"Preheat oven to 180°C / 350°F (160°C fan). Grease 3 x 20cm (8”) cake pans with butter, line with parchment / baking paper.","images":[],"step":2},{"title":"Sift dry ingredients","description":"Combine dry ingredients by sifting the cocoa and plain flour into a bowl. Set aside.","images":[],"step":3},{"title":"Beat eggs","description":"Beat eggs for 30 seconds on speed 6 of a stand mixer fitted with a whisk attachment, or hand beater.","duration":0.5,"images":[],"step":4},{"title":"Slowly add sugar","description":"With the beater still going, slowly pour the sugar in over 45 seconds, then add the vanilla.","images":[],"step":5},{"title":"Beat 7 minutes","description":"Beat for 7 minutes more on speed 8, or until tripled in volume and pale in colour. Don''t shortcut this step; this is what makes the cake rise (there''s no baking powder used).","duration":7,"images":[],"step":6},{"title":"Fold in dry ingredients","description":"Add the flour and cocoa mixture to the batter, folding in with a spatula until just combined (a few streaks of flour remaining is fine). Be gentle here, we don''t want to knock out the air bubbles.","images":[],"step":7},{"title":"Fold in butter","description":"Add the butter and fold gently through until just combined. Once you can no longer see any flour, stop stirring.","images":[],"step":8},{"title":"Fill cake pans","description":"Pour the batter into the three prepared pans. The batter should be fairly thin and pourable.","images":[],"step":9},{"title":"Bake","description":"Place into the oven and bake for 25 minutes, until springy to the touch and a skewer inserted into the cake centre comes out clean. (Note 5 regarding shelf placement)","duration":25,"images":[],"step":10},{"title":"Cool","description":"Remove from the oven. Cool in the pan for 10 minutes before turning the cakes out onto a rack to cool completely.","duration":10,"images":[],"step":11},{"title":"Drain cherries","description":"Drain jar of cherries, reserving liquid.","images":[],"step":12},{"title":"Cherry cornflour slurry","description":"Measure out 1/4 cup (60ml) of the reserved cherry juice and mix with the cornflour to make a slurry. Set aside.","images":[],"step":13},{"title":"Make cherry syrup","description":"Place a medium pot over medium-low heat. Add the sugar and another 1/3 cup of reserved juice. Bring to a gentle simmer to dissolve the sugar. Stir in the cornflour slurry and bring to a simmer. Cook for 1 minute, stirring, until it thickens into a thin syrup.","duration":1,"images":[],"step":14},{"title":"Soak cherries, cool","description":"Remove from the heat and stir in the kirsch. Pour the syrup over the drained cherries and allow to cool completely before using.","images":[],"step":15},{"description":"Chocolate curls (Note 8):","images":[],"step":16},{"title":"Melt chocolate","description":"Break up the block of chocolate and place in a microwave-safe bowl. Gently melt in microwave by heating over three 20 second bursts, stirring in between.","images":[],"step":17},{"title":"Spread","description":"Pour the melted chocolate over the back of a baking pan and spread out with a spatula as thinly as possible. Refrigerate for 3 - 4 minutes until the centre is just set.","duration":3.5,"images":[],"step":18},{"title":"Scrape curls","description":"Using something with a sharp, straight edge (I use a bench scraper, spatula or the back of a knife also works), hold it at a 45 degree angle and scrape along the tray away from you to create curls. Do a small test patch first. If the chocolate is too hard, the curls may break or flake (leave to soften slightly and try again). If the chocolate is too soft, the curls sag and won''t roll (refrigerate more to harden).","images":[],"step":19},{"description":"Having problems?? Don''t worry! Just scrape to make shavings instead – it still looks amazing!","images":[],"step":20},{"title":"Refrigerate","description":"Carefully place curls on a plate and refrigerate until ready to use.","images":[],"step":21},{"description":"Just prior to assembling, place cream, icing sugar and vanilla in a large bowl. Whip into pretty stiff peaks - about 5 minutes on high. Refrigerate until needed.","images":[],"step":22},{"description":"Place one cake layer upside down on a serving platter (or cake decorating turn table, if you''re a pro! :) ).","images":[],"step":23},{"title":"Brush with cherry syrup","description":"Brush the cake layer with 1/4 cup of the cherry syrup the cherries are soaking in.","images":[],"step":24},{"title":"Cream layer","description":"Spread with 1 cup of whipped cream, leaving a 1cm (1/2\") border (the weight of the next cake layer gently pressed will push cream to edge).","images":[],"step":25},{"title":"Layer cherries","description":"Top the cream with half the cherries (in a single layer), using a slotted spoon to drain well (but don''t pat dry, want the cherries juicy!).","images":[],"step":26},{"title":"Repeat","description":"Top with another cake layer, brush with 1/4 cup syrup, spread with 1 cup cream, top with remaining cherries, and place 3rd cake layer on top.","images":[],"step":27},{"title":"Cover with cream","description":"Reserve 1 1/2 cups whipped cream for piping cream decorations. Spread the remaining cream over the top and side of the cake. Pipe dollops around the edge of top using a large star-tipped nozzle. Top each dollop with a maraschino cherry.","images":[],"step":28},{"title":"Chocolate shavings","description":"Pile large chocolate curls in the middle (I stack in a tent shape like building a fire!). Use the smaller broken shavings to coat the base of the sides of the cake (using cold hands, scoop up shavings, press on side).","images":[],"step":29},{"title":"Rest 4 hours+","description":"Leave cake in the fridge for at least 4 hours, preferably overnight, to allow flavours to develop and syrup to really soak into the cake.","images":[],"step":30},{"title":"Take out of fridge","description":"Remove from fridge 30 minutes prior to serving (but be mindful of cream melting on hot days). Slice and serve proudly!","images":[],"step":31}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":["German"],"categories":["classic-cakes","german-food","iconic-dishes","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d24d2a64fd00', 'en', 'US', 'Easter Cake', 'Recipe video above. This Easter Cake is not so much a recipe as it is a charming Easter Cake decorating idea! A 3-layer vanilla cake is frosted with pale blue, fluffy Vanilla Buttercream Frosting and speckled with chocolate. Finally, it''s topped with a toasted coconut "nest" nestled with mini candy eggs. Pretty as a picture!', 'https://www.recipetineats.com/tachyon/2021/04/Easter-Cake_1-copy.jpg', 45, 30, 75, 12, '[{"id": "ing_vanilla_cake", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_butter", "quantity": {"value": 340.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.3, "unit": "bottle of 50ml"}}, {"id": "ing_drops_blue_gel_food_colouring", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_cocoa_powder", "quantity": {"value": 0.06, "unit": "pack of 250g"}}, {"id": "ing_water", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_toothbrush", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_chilli_flakes", "quantity": {"value": 7.5, "unit": "jar of 40g"}}, {"id": "ing_egg", "quantity": {"value": 16.667, "unit": "carton of 12"}}]', '[{"ingredients":["1 Vanilla Cake (, 3 layers (or other 20cm/8\" cake of choice, Note 1))"]},{"ingredients":["340g/ 3 sticks unsalted butter (, 1.25cm / ½\" cubes, softened to 18°C/64°F (Note 3))","750g/ 1.5 lb (6 cups) soft icing sugar / powdered sugar (, sifted)","3 tsp vanilla extract","1 - 2 drops blue gel food colouring (or 1 - 2 tsp blue food colouring, Note 4)","1/8 tsp salt"],"purpose":"Pastel Blue Vanilla Buttercream (Note 2):"},{"ingredients":["1 tbsp cocoa powder (unsweetened or sweetened, doesn''t matter)","3 tbsp boiling water","Toothbrush (or basting brush)"],"purpose":"Frosting Speckles:"},{"ingredients":["2 cups coconut flakes (or shaved)","200g/ 7oz small Easter eggs (I use pastel coloured speckled ones, Note 5)"],"purpose":"Decorating:"}]', '[{"title":"Level","description":"Trim the top of cakes if required/desired to make the layers level (for aesthetic purposes).","images":[],"step":1},{"title":"Chill","description":"Place cake layers in fridge until thoroughly chilled (this makes it easier to frost so crumbs don''t go everywhere).","images":[],"step":2},{"title":"Toast coconut","description":"Preheat oven to 160°C/325°F (140°C fan). Spread coconut on a tray. Bake 6 - 10 minutes, stirring every couple of minutes, until golden. (Bake time depends on sugar level, so keep an eye on it). Cool.","images":[],"step":3},{"description":"Buttercream Frosting:","images":[],"step":4},{"title":"Cream butter","description":"Beat butter in a stand mixer on Speed 8 for 3 minutes until it changes from yellow to almost white.","duration":3,"images":[],"step":5},{"title":"Add icing sugar in 3 batches","description":"Add icing sugar in 3 batches, starting the mixer on speed 1 until partially incorporated, then increasing until it''s mostly mixed in.","images":[],"step":6},{"title":"Vanilla, salt, and beat 2 mins","description":"Add vanilla and salt, then beat on Speed 8 for 2 minutes until almost white, and it''s beautifully fluffy.","duration":2,"images":[],"step":7},{"title":"Colour (Note 4)","description":"Remove 1 tbsp frosting into a small bowl. Add 1 drop of blue gel, mix in. Add 1 teaspoon of coloured frosting back into main frosting, beat until incorporated (scrape down sides as needed). Add more coloured frosting 1 teaspoon at a time until desired tone is achieved.","images":[],"step":8},{"description":"Speckle Mixture:","images":[],"step":9},{"description":"Mix cocoa and boiling water.","images":[],"step":10},{"title":"Frosting","description":"Spread 3/4 cup frosting between each cake layer, then using remaining frosting for side and surface (I usually have ~1/2 cup frosting leftover, but better safe than sorry!).","images":[],"step":11},{"title":"Speckles","description":"Place something behind cake as a backboard for the speckling mess! Dip toothbrush in cocoa mixture, then use fingers to flick speckles onto cake surface - sides and top. (Hint: Practice in sink first). TIP: When doing top of cake, angle toothbrush 45 degrees down NOT over cake, to avoid accidental big drips.","images":[],"step":12},{"title":"Coconut Nest","description":"Pile coconut in the middle to form a \"nest\" then pile a mound of eggs in it.","images":[],"step":13},{"title":"Coconut Rim","description":"Place a mound of coconut all along the base of the cake, then dot with Easter Eggs.","images":[],"step":14},{"title":"Bask in praise","description":"Take proudly to table and bask in the compliments!","images":[],"step":15}]', '["egg","milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Easter"],"categories":["classic-cakes","easter-baking-desserts","easter-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_dde86f0c02ac', 'en', 'US', 'Christmas Cake - EASY moist fruit cake', 'Recipe video above. This is an easy Christmas Cake that requires no overnight fruit soaking. It''s a fruit cake that''s incredibly easy to make, with a rich, velvety texture that''s full flavoured and so moist it can be eaten plain. (But no one turns away a slosh of custard!) Just as good made on the day - or weeks later.', 'https://www.recipetineats.com/tachyon/2019/12/Christmas-Cake-decorated-with-fondant-marzipan-and-cherries.jpg', 30, 195, 285, 20, '[{"id": "ing_raisins", "quantity": {"value": 300.0, "unit": "unit"}}, {"id": "ing_apricots", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_mixed_peel", "quantity": {"value": 75.0, "unit": "unit"}}, {"id": "ing_cherries", "quantity": {"value": 0.3, "unit": "pack of 500g"}}, {"id": "ing_dates", "quantity": {"value": 180.0, "unit": "unit"}}, {"id": "ing_apples", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 120.0, "unit": "block of 250g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_molasses", "quantity": {"value": 45.0, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cinnamon", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_nutmeg", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_egg", "quantity": {"value": 250.0, "unit": "carton of 12"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.017, "unit": "tub of 150g"}}, {"id": "ing_flour", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_walnuts", "quantity": {"value": 112.5, "unit": "jar"}}, {"id": "ing_cream", "quantity": {"value": 2.0, "unit": "carton of 250ml"}}, {"id": "ing_bread", "quantity": {"value": 0.312, "unit": "loaf"}}, {"id": "ing_bread", "quantity": {"value": 0.312, "unit": "loaf"}}, {"id": "ing_cherries", "quantity": {"value": 0.3, "unit": "pack of 500g"}}, {"id": "ing_cherries", "quantity": {"value": 0.3, "unit": "pack of 500g"}}, {"id": "ing_drippy_white_glaze", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["300g / 10 oz raisins","150g / 5 oz diced dried apricots (, chopped 8 mm / 1/3\")","75g / 2.5 oz mixed peel (, diced 5mm / 1/5)","150g / 5 oz glace cherries (, chopped 8 mm / 1/3\")","180g / 6 oz dates (, diced 5mm / 1/5\")","1 cup + 2 tbsp apple juice, OR 1/3 brandy + 2/3 juice ( (Note 2))"],"purpose":"Fast soaked fruit (Note 1):"},{"ingredients":["120g / 8 tbsp unsalted butter (, softened (1 US stick))","1 1/2 cups dark brown sugar (, packed (Note 3))","1/2 cup vegetable oil (or canola, peanut, grapeseed)","3 tbsp molasses or golden syrup (Note 4)","1/2 tsp salt","1/2 tsp all spice","1/2 tsp cinnamon","1/2 tsp nutmeg","3 large eggs","1/2 tsp baking powder","1 2/3 cups plain flour (all purpose flour)","3/4 cup walnuts (, chopped (optional))"],"purpose":"Cake:"},{"ingredients":["500ml / 1 pint pouring custard (, homemade or store bought (Note 5))"],"purpose":"For serving (optional)"},{"ingredients":["250g / 8 oz \"ready to roll\" marzipan","250g / 8 oz \"ready to roll\" white fondant","Cherries dusted with icing sugar"],"purpose":"White Christmas Cake decoration, as pictured (optional)"},{"ingredients":["Cherries or other fruit dusted with icing sugar (on plain cake, looks very pretty!)","Drippy white glaze (directions below)"],"purpose":"Other Decorating Options (optional)"}]', '[{"description":"Fast Soaked Fruit:","images":[],"step":1},{"description":"Place dried fruit and juice/brandy in a large microwavable container. Microwave 1 1/2 minutes on high or until hot.","images":[],"step":2},{"description":"Stir to coat all fruit in liquid. Cover then set aside for 1 hour (to plump up/soak and cool).","images":[],"step":3},{"description":"Preheat oven to 160°C / 320°F (140°C fan). Grease and line a 21 - 22 cm / 8 - 9\" round cake pan with baking paper (parchment paper) (7 cm / 2.75\" tall).","images":[],"step":4},{"description":"Using an electric beater, beat butter and sugar until smooth and creamy (about 1 minute on speed 5).","images":[],"step":5},{"description":"Add oil and molasses, beat until combined.","images":[],"step":6},{"title":"Add salt, spices and baking powder","description":"beat until incorporated.","images":[],"step":7},{"description":"Add eggs, one at a time, beating until just incorporated","images":[],"step":8},{"description":"Stir in the flour.","images":[],"step":9},{"description":"When mostly incorporated, stir in the fruit mix (including all the extra liquid in bowl) and walnuts (if using).","images":[],"step":10},{"description":"Pour into cake pan, cover with foil and bake for 2 1/2 hours. Remove the foil then bake for another 30 to 45 minutes, or until a skewer inserted into middle comes out clean with no batter on it (check first at 30 minutes).","images":[],"step":11},{"description":"Remove from oven and cool for 20 minutes before transferring to cooling rack. Cool completely before serving.","duration":20,"images":[],"step":12},{"description":"Cake is moist and so full flavoured, it can be eaten plain. But see below for decorating and serving ideas (traditionally served with pouring custard).","images":[],"step":13},{"title":"Cutting","description":"Either cut into thin wedges, or cut cake into thin strips (2cm / 0.75\" or so), then cut those strips into serving size pieces.","images":[],"step":14},{"description":"Christmas Cake Decorating options:","images":[],"step":15},{"description":"Traditional White Christmas Cake (pictured in post) - Marzipan and fondant, see Decorating Note.","images":[],"step":16},{"title":"Simple","description":"pile top with fresh cherries or other fruit, dust with icing sugar (powdered sugar). Wrap a ribbon around the cake for extra touch!","images":[],"step":17},{"title":"Drippy white glaze","description":"use the glaze in this Lemon Cake recipe, but leave out the lemon juice (ie make a plain sweet white glaze). Flip cake upside down for flat surface then glaze per that recipe.","images":[],"step":18},{"title":"Serving","description":"serve with custard for a traditional experience! Either homemade custard or store bought pouring custard (jazz it up by mixing in vanilla seed paste!).","images":[],"step":19}]', '["egg","gluten","milk","peanuts"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Australia","British","Western"],"categories":["classic-cakes","dessert-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9ef37f8a6b35', 'en', 'US', 'My best Vanilla Cake - stays moist 4 days!', 'Recipe video above. Your classic vanilla butter cake but with Japanese techniques applied for the most plush, soft and moist yellow cake like you’ve never had before. This professional bakery style cake stays fresh and moist for 4 days — that’s unheard of! This is THE Vanilla Cake recipe for all occasions — from layer cakes to birthday cakes, Victoria Sponge to strawberry shortcake … the possibilities are endless.....-------------------Frosting - classic vanilla buttercream provided, see here for my secret Less-Sweet Fluffy Frosting. Different pan sizes - Note 9. Cupcakes - see Vanilla Cupcakes recipe. Metric/weights - click button above ingredients. Sweetness - Note 11. Cake flour - no need, better with plain flour. Guarantee success - read top 5 points in Notes below. For chocolate cake - see this recipe.', 'https://www.recipetineats.com/tachyon/2020/08/My-best-Vanilla-Cake_9.jpg', 20, 30, 50, 10, '[{"id": "ing_flour", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 2.5, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 333.333, "unit": "carton of 12"}}, {"id": "ing_sugar", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 115.0, "unit": "block of 250g"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.3, "unit": "bottle of 50ml"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_butter", "quantity": {"value": 115.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.225, "unit": "kg"}}]', '[{"ingredients":["2 cups plain / all purpose flour (cake flour OK too, Note 1)","2 1/2 teaspoons baking powder","1/4 tsp cooking salt (kosher salt)","4 large eggs (50 - 55g / 2 oz each), at room temp (Note 3)","1 1/2 cups caster sugar / superfine sugar (granulated/regular ok too, Note 2)","115g / 1/2 cup unsalted butter (, cut into 1.5cm / 1/2” cubes (or so))","1 cup milk (, full fat (Note 5))","3 tsp vanilla extract (, the best you can afford (Note 6))","3 tsp vegetable or canola oil (Note 7)"]},{"ingredients":["225g / 2 sticks unsalted butter (, softened)","500g / 1 lb soft icing sugar / powdered sugar (, SIFTED)","3 tsp vanilla extract","2 - 4 tbsp milk (, to adjust thickeness, if needed)"],"purpose":"Vanilla Buttercream"}]', '[{"description":"Beat eggs and sugar until triple in volume, gently add flour in 3 batches. Temper hot milk and butter with bit of batter, then slowly beat into cake batter. Bake in 3 pans for 22 minutes, cool inverted then frost.","duration":22,"images":[],"step":1},{"description":"Preheat oven to 180°C/350°F (160°C fan) for 20 minutes before starting the batter (Note 8). Place shelf in the middle of the oven.","duration":20,"images":[],"step":2},{"title":"Pans","description":"Grease 2 x 20cm / 8” cake pans with butter, then line with parchment / baking paper. (Note 9 more pan sizes) Best to use cake pan without loose base, if you can.","images":[],"step":3},{"title":"Dry ingredients","description":"Whisk flour, baking powder and salt in a large bowl. Set aside.","images":[],"step":4},{"description":"Beat eggs until aerated:","images":[],"step":5},{"title":"30 sec beat","description":"Beat eggs for 30 seconds on speed 6 of a Stand Mixer fitted with a whisk attachment, or hand beater.","duration":0.5,"images":[],"step":6},{"title":"Slowly add sugar","description":"With the beater still going, pour the sugar in over 45 seconds.","images":[],"step":7},{"title":"Triple volume","description":"Then beat for 7 minutes on speed 8, or until tripled in volume and white.","duration":7,"images":[],"step":8},{"description":"Finish cake batter:","images":[],"step":9},{"title":"Heat Milk-Butter (Note 5)","description":"While egg is beating, place butter and milk in a heatproof jug and microwave 2 minutes on high to melt butter (or use stove).","images":[],"step":10},{"title":"Add flour in 3 batches","description":"When the egg is whipped, add the flour in 3 batches beating for 5 seconds on Speed 1 in between each addition. Once all the flour is in, beat for another 5 - 10 seconds until you can''t see any flour, then stop beating the cake batter straight away.","duration":0.08333333333333333,"images":[],"step":11},{"title":"Combine milk, vanilla & oil","description":"Pour hot milk, vanilla and oil into the now empty flour bowl.","images":[],"step":12},{"title":"Temper","description":"Add about 1 1/2 cups (2 ladles or so) of the cake batter into the hot milk (don''t need to be 100% accurate with amount). Use a whisk to mix until smooth - you can be vigorous here. Will look foamy.","images":[],"step":13},{"title":"Slowly add milk","description":"Turn beater back on Speed 1 then pour the hot milk mixture into the cake batter over 15 seconds, then turn beater off.","images":[],"step":14},{"title":"Scrape and final mix","description":"Scrape down sides and base of bowl. Beat on Speed 1 for 10 seconds - batter should now be smooth and pourable.","duration":0.16666666666666666,"images":[],"step":15},{"title":"Pour batter into pans","description":"560g / 20 oz batter per pan.","images":[],"step":16},{"title":"Knock out bubbles","description":"Bang each cake pan on the counter 3 times to knock out big bubbles (Note 10)","images":[],"step":17},{"description":"Bake 30 minutes or until golden and toothpick inserted into centre comes out clean.","images":[],"step":18},{"title":"Cool","description":"Remove from oven. Cool in cake pans for 15 minutes, then gently turn out onto cooling racks. If using as layer cakes, cool upside down - slight dome will flatten perfectly. Level cake = neat layers.","duration":15,"images":[],"step":19},{"title":"Frost","description":"Once cake layers are fully cool, top with frosting of choice, or cream and fresh berries or jam. See list of ideas in post!","images":[],"step":20},{"description":"Vanilla Buttercream:","images":[],"step":21},{"title":"Cream butter","description":"Beat butter with paddle attachment in stand mixer for 3 minutes on high until it changes from yellow to almost white, and it becomes fluffy and creamy.","duration":3,"images":[],"step":22},{"description":"Add icing sugar / powdered sugar gradually in 3 lots, beating slowly (to avoid a powder storm) then once mostly incorporated, beat on high for a full 3 minutes until fluffy.","images":[],"step":23},{"title":"Finish","description":"Add vanilla and milk, then beat for a further 30 seconds. Use milk only if needed to make it lovely and soft but still holds its form (eg for piping). Use immediately. (If you make ahead, refrigerate then beat to re-fluff).","images":[],"step":24}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["classic-cakes","dessert-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4d9196df2317', 'en', 'US', 'Single Serve Chocolate Chip Cookie', 'Recipe video above. You will be pulling this out of the oven in just over 20 minutes! Really, it''s incredible how fast it is to make a small batch of cookies. :)Note - whether you make one giant cookie, two large ones or four sensible ones, this recipe is strictly a one-person affair. No obligation to share!! 😈 I prefer making 2 large 10cm/4" cookies as the ratio of soft/chewy middle to crispy edges is perfect to me, so that''s the base recipe. But for a big impact cookie, make one large 17cm/7" one!', 'https://www.recipetineats.com/tachyon/2026/05/Single-serve-chocolate-chip-cookie.jpg', 10, 15, 35, 2, '[{"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.025, "unit": "bottle of 50ml"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.003, "unit": "tub of 200g"}}, {"id": "ing_chocolate", "quantity": {"value": 0.333, "unit": "block of 100g"}}, {"id": "ing_chilli_flakes", "quantity": {"value": 0.003, "unit": "jar of 40g"}}]', '[{"ingredients":["30g / 2 tbsp unsalted butter (, cut into a few chunks)","2 1/2 tbsp (tightly packed) brown sugar","1 1/2 tbsp caster sugar / superfine sugar (regular / granulated is ok too)","1 egg yolk from a large egg FRIDGE COLD ( ~55g/2oz in shell (Note 1))","1/4 tsp vanilla extract","Pinch of salt","1/3 cup + 1 tbsp plain flour / all-purpose flour","1/8 tsp baking soda (, sifted if lumpy (Note 2 re: baking powder))","1/3 cup dark chocolate chips / semi-sweet chocolate chips (, or whatever choc chips / chopped chocolate you want)","Pinch salt flakes (, optional)"]}]', '[{"description":"Mix sugar and melted butter, then yolk, vanilla and salt. Mix in dry, then choc chips. Shape into 2 x 1.5cm/0.6\" thick discs. Bake 13 - 14 min at 190°C/375°F (170°C fan-forced).","images":[],"step":1},{"description":"FULL RECIPE (2 large cookies)","images":[],"step":2},{"description":"Preheat oven to 190°C/375°F (170°C fan-forced). Place a sheet of baking paper on a tray.","images":[],"step":3},{"title":"Partially melt butter","description":"Put the butter in a microwave proof bowl. Heat on high for 30 seconds or until mostly melted. Stir to finish melting - it should look a little milky. (Note 3)","duration":0.5,"images":[],"step":4},{"title":"Wet ingredients","description":"Add both sugars into the butter, mix with a rubber spatula to combine. Add yolk, vanilla and salt. Mix to combine.","images":[],"step":5},{"title":"Dry ingredients","description":"Scatter flour across surface then baking soda across flour. Mix until flour is almost fully incorporated. Mix through most of the chocolate chips (reserve some for topping).","images":[],"step":6},{"title":"Shape","description":"Form 2 balls and flatten to 1.5cm/0.6\" thick. Place on tray. If your dough is too sticky to handle, pop it in the fridge for 5 to 10 minutes (see Note 4).","duration":7.5,"images":[],"step":7},{"title":"Smaller/larger cookies","description":"You can also do 3 or 4 smaller cookies (same bake time and temp) or one giant cookie (see below).","images":[],"step":8},{"title":"Bake for 13","description":"14 minutes or until edges are tinged gold and the centre is pale golden.","duration":13.5,"images":[],"step":9},{"title":"Top","description":"Place reserved chocolate chips on top of each (chocolate will melt and glue to surface) and sprinkle with salt flakes if using.","images":[],"step":10},{"title":"Cool 10 minutes","description":"Leave cookies to cool on the tray for 10 minutes so they firm up and finish cooking. Then attack! (Or transfer to rack to fully cool then store in an airtight container).","duration":10,"images":[],"step":11},{"description":"ONE GIANT COOKIE ~17cm/7\" wide","images":[],"step":12},{"description":"Preheat oven to 180°C/350°F (160°C fan-forced). Make one large ball and flatten to 2cm/0.8\" thick. Bake 16 - 18 minutes until edges are golden and middle is pale golden. Press reserved chocolate chips on surface, cool 10 minutes on the tray before attacking!","images":[],"step":13}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["cookies","egg-yolk-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4b81191915cf', 'en', 'US', 'Biscotti', 'Recipe video above. There are countless biscotti flavours these days but almond is probably the most traditional, and it''s certainly the one I reach for most often!This biscotti is crisp as it should be, but not tooth-breakingly hard like shop bought ones often are. They are the thinner which I prefer over those really chunky versions which I find is just too much crunchy biscuit in a mouthful. Just make sure you use a sharp serrated knife to slice the logs, and let them cool fully before cutting so they’re less prone to crumbling or breaking.', 'https://www.recipetineats.com/tachyon/2026/05/Biscotti-3.jpg', 25, 50, 165, 40, '[{"id": "ing_almonds", "quantity": {"value": 0.75, "unit": "pack of 250g"}}, {"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_almonds", "quantity": {"value": 0.75, "unit": "pack of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.263, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.067, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}]', '[{"ingredients":["1 1/4 cups almonds (, whole, raw, unsalted (Note 1))","60g (4 tbsp) unsalted butter, melted and cooled but still fluid ( (or light olive oil - Note 2))","3/4 cup caster sugar (superfine sugar)","2 large eggs (, fridge cold best, 50-55g / 2oz each (Note 3))","1 tsp vanilla extract","3/4 tsp almond extract (substitute more vanilla)","1 3/4 cups plain flour (all-purpose flour)","2 tsp baking powder (sub 1/2 tsp baking soda)","1/4 tsp cooking salt / kosher salt (halve for table salt, +50% for flakes)"]}]', '[{"description":"Toast almonds 10 min, cool. Whisk butter and sugar, then remaining wet ingredients. Stir in dry ingredients with wooden spoon. Shape into 2 logs, bake 25 min at 180°C/350°F (160°C fan). Cool, slice 8mm / 1/3\" thick, bake 24 min (flipping halfway) at 150°/300°F (130°C fan), cool on trays.","images":[],"step":1},{"description":"Preheat the oven to 180°C/350°F (160°C fan-forced).","images":[],"step":2},{"title":"Toast almonds","description":"Spread the almonds on a tray and bake for 10 minutes, shaking the tray once. Fully cool before adding into dough.","duration":10,"images":[],"step":3},{"title":"Wet ingredients","description":"Whisk the butter and caster sugar in a bowl. Add eggs, vanilla and almond extract, whisk to combine.","images":[],"step":4},{"title":"Dry ingredients","description":"Add the flour, then scatter the baking powder and salt across the surface. Mix with a wooden spoon until the flour is almost completely mixed in. Add the almonds, mix until fully combined - it should be like a cookie dough, a bit sticky but just firm enough to handle. (If it''s super sticky, refrigerate 15 min).","images":[],"step":5},{"title":"Logs","description":"Divide the mixture into two and scrape out onto a paper lined tray. Shape into 2 logs 5 cm wide, 2 cm tall, 27 cm long (2 x 0.8 x /12\"), set 7cm/2.5\" apart - they will spread. (If the mixture is sticky, use wet hands, if really sticky, refrigerate dough for 10 minutes).","duration":10,"images":[],"step":6},{"title":"Bake 1 (30 minutes)","description":"Bake for 25 minutes or until light golden. Fully cool - about 1 hour. (Cooler = easier to slice without crumbling, it''s even easier the next day).","duration":25,"images":[],"step":7},{"title":"Bake 2","description":"crisp them!","images":[],"step":8},{"description":"Preheat oven to 150°/300°F (130°C fan-forced).","images":[],"step":9},{"title":"Slice","description":"Using a sharp serrated knife, slice on the diagonal into 7mm / 1/3\" thick slices. You can cut thicker if you want, but I like my biscotti thinner. I get ~40 pieces plus log ends.","images":[],"step":10},{"title":"Bake 2 (24 minutes)","description":"Place on 2 lined trays. Bake for 12 minutes, flip, then bake for another 12 minutes or until light golden. (They will take longer if you cut yours thicker).","duration":12,"images":[],"step":11},{"title":"Cool on the tray","description":"they will fully crisp once cool. Enjoy!","images":[],"step":12}]', '["egg","gluten","milk","nuts"]', '["keto_friendly","low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Italian"],"categories":["cookies","dessert-recipes","italian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_349ec624626c', 'en', 'US', 'Tomato paste replacement for canned tomato', 'Here''s how to use tomato paste as a replacement for canned tomato or passata in cooking. Use for things like bologneses and in soups that call for canned tomato.Once cooked into a dish, no one will ever be able to tell that you used tomato paste instead of canned tomato!Recipe makes 400g/14oz which is one standard can of tomato.', 'https://www.recipetineats.com/tachyon/2020/03/Canned-tomato-substitute-tomato-paste.jpg', 5, 0, 5, 4, '[{"id": "ing_tomato", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}]', '[{"ingredients":["4 tbsp tomato paste","1.5 tbsp flour","1 1/2 cups water (, separated)","1.5 tsp sugar"]}]', '[{"description":"Whisk together 1/4 cup water (65ml) with the flour until lump free.","images":[],"step":1},{"description":"Then mix in remaining water, tomato paste and sugar.","images":[],"step":2},{"description":"Use in recipes in place of canned tomato, add it at the time the recipe calls for canned tomato to be added. It will be watery while it''s \"raw\", but the flour will thicken the mixture as it cooks in things like bolognese, soup (like Minestrone), curries (like this Coconut Lentil Curry) and pasta bakes.","images":[],"step":3},{"description":"Pictures in post show the thickness after cooking on stove for 3 minutes on medium high - not necessary to do if added into a recipe then cooked.","duration":3,"images":[],"step":4},{"description":"There is no limit for how long it can be cooked for - you can use it for a quick recipe like this Bacon Pasta, or simmered for hours like in Ragu.","images":[],"step":5},{"title":"Fridge storing","description":"will keep for 5 days in the fridge.","images":[],"step":6},{"title":"Freezing","description":"simmer 3 minutes on medium high, stirring regularly, until it thickens. Cool, freeze.","images":[],"step":7}]', '["gluten"]', '["vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["coronavirus-food","sauces","vegan-lifestyle"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_17d4583ae6c2', 'en', 'US', 'Easy French Apple Tart - Tarte Fine aux Pommes', 'Recipe video above. It’s hard to believe a proper French tart can be this simple and this good - but here we are! This one comes straight from JB (yes, our actual French chef), who whipped it up like it was no big deal. Sometimes, his idea of "no big deal" is out of reach for regular folk like me. But for once, it isn''t at all! 😂The base is extra crisp thanks to a little sprinkle of sugar, and the apple is only lightly sweetened, that''s all it needs. Use any type of apple you like, but my favourite is gala (we tried quite a few). And while we can all pretend ice cream is optional, it isn''t really. :)', 'https://www.recipetineats.com/tachyon/2025/05/Easy-French-Apple-Tart_7.jpg', 12, 30, 42, 4, '[{"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.025, "unit": "kg"}}, {"id": "ing_apples", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.025, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.004, "unit": "carton of 250ml"}}]', '[{"ingredients":["1 square sheet butter puff pastry (25cm / 10\" square), barely thawed (Note 1)","5 tsp caster sugar (/ superfine sugar (sub regular / granulated))","2 large gala apples (or 3 medium), peeled, cut in half, core removed, sliced 0.5cm / 0.2\" thick (Note 2)","1 tbsp unsalted butter (, melted)"]},{"ingredients":["Icing sugar / powdered sugar (, for dusting (optional))","Vanilla ice cream (not really optional!)"],"purpose":"For serving:"}]', '[{"title":"ABBREVIATED","description":"Sprinkle paper with 3t sugar, put puff on, fold in 1cm / 0.4\" edge. Top with apple, brush butter, sprinkle 2t sugar. Bake on preheated tray at 210°C/375°F (190°C fan) for 30 minutes.","duration":30,"images":[],"step":1},{"title":"Hot tray","description":"Put a baking tray in the oven then turn it on and pre-heat to 210°C/375°F (190°C fan-forced).","images":[],"step":2},{"title":"Sugar underside of puff","description":"Place a sheet of baking paper (parchment paper) on the counter. Sprinkle with 3 teaspoons of sugar, roughly in the shape of the puff pastry sheet.","images":[],"step":3},{"title":"Fold edge","description":"Place puff pastry on top of the sugar. Fold the edges inwards to create a 1cm / 0.4\" edge.","images":[],"step":4},{"title":"Apples","description":"Arrange the apples slices in 3 rows, overlapping them slightly.","images":[],"step":5},{"title":"Butter and sugar","description":"Brush the apple slices and edges with melted butter, then sprinkle with the sugar (apple and edge).","images":[],"step":6},{"title":"Bake","description":"Transfer the tart on the paper to the hot baking tray (keep it on the paper). Bake for 30 minutes, or until the edges are golden.","duration":30,"images":[],"step":7},{"title":"Serve","description":"Cut into 6, dust with icing sugar and serve warm with vanilla ice cream.","images":[],"step":8}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["French"],"categories":["cosy-desserts","dessert-recipes","quick-and-easy","sweet-pies"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a851629d73a2', 'en', 'US', 'Apple and rhubarb crumble', 'Recipe video above. The only thing I make when rhubarb season arrives - rhubarb crumble! I like to add apple into mine so the filling isn''t just baby-food-mush. Adore the tangy filling - there is nothing else like it. Extra crumbly topping also works well.SERVING WITH ICE CREAM IS A MUST!', 'https://www.recipetineats.com/tachyon/2023/07/Rhubarb-crumble-with-apple_5.jpg', 15, 35, 50, 5, '[{"id": "ing_rhubarb", "quantity": {"value": 10.0, "unit": "bunch"}}, {"id": "ing_sugar", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_apples", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_oranges", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_rolled_oats", "quantity": {"value": 0.3, "unit": "pack of 500g"}}, {"id": "ing_flour", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.017, "unit": "tub of 150g"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_butter", "quantity": {"value": 90.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.004, "unit": "carton of 250ml"}}]', '[{"ingredients":["500g/ 4 1/2 cups rhubarb stems","1/3 cup white sugar","3 Granny Smith apples (~600g/1.2lb whole) (, peeled and cut 1.5cm / 3/5\" cubes, ~3 cups/450g once cut (Note 2))","Zest of 1 orange (, optional but recommended)"],"purpose":"Rhubarb filling:"},{"ingredients":["1 cup rolled oats (not quick or steel cut)","1 cup flour (, plain/all purpose)","3/4 cup (tightly packed) brown sugar","1/2 tsp baking powder","1/2 tsp cinnamon powder","90g/ 6 tbsp unsalted butter (, melted)","Pinch of salt"],"purpose":"Topping:"},{"ingredients":["Vanilla ice cream (- or pouring custard)"],"purpose":"Serving (must!)"}]', '[{"description":"Preheat oven to 200°C/375°F (180°C fan).","images":[],"step":1},{"title":"Filling","description":"Place rhubarb, apple, sugar and orange zest in a large mixing bowl and toss well. Spread evenly in a 30 x 20cm baking dish (12 x 8\") (Note 3)","images":[],"step":2},{"title":"Crumble topping","description":"Place topping ingredients in a bowl and mix with a wooden spoon until all the flour is incorporated (use cutting motion/ smearing up wall, as needed). It will be a sandy mixture.","images":[],"step":3},{"title":"Scrunch & top","description":"Grab handfuls of crumble and enclose your fist to press into lumps. Break into clumps and scatter over the filling. (Note 4 explains this unusual step!).","images":[],"step":4},{"description":"Bake for 35 minutes or until rhubarb is soft and the crumble is golden brown. (Bake time - Note 5)","duration":35,"images":[],"step":5},{"title":"Rest & serve","description":"Remove from the oven, rest for 5 minutes. Scoop into bowls and serve with vanilla ice cream or custard!","duration":5,"images":[],"step":6}]', '["gluten","milk"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":["British","Western"],"categories":["cosy-desserts","puddings-cosy-desserts"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8253d2504f73', 'en', 'US', 'Creamy Cinnamon Rice Pudding (really easy!)', 'Recipe video above. A cosy, creamy rice pudding with the perfect soft rice texture - but not mushy and gluey. A hint of cinmamon and handful of raisins really elevates this into a dessert that can be served just as it is, straight out of the pot, rather than fussing with making a compote or similar that you really do need for plain rice puddings. But a scoop of vanilla ice cream will really take it over the top!', 'https://www.recipetineats.com/tachyon/2020/06/Rice-Pudding-cinnamon_7.jpg', 5, 60, 65, 5, '[{"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_milk", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.2, "unit": "bottle of 50ml"}}, {"id": "ing_white_rice", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_sultanas", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_cinnamon", "quantity": {"value": 3.75, "unit": "jar"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}]', '[{"ingredients":["1 tbsp unsalted butter (, for greasing)","4 cups milk (full or reduced fat, Note 1)","1/3 cup white sugar","2 tsp vanilla extract","3/4 cup medium grain white rice, uncooked (- definitely the best for rice pudding (Note 2))","1/2 cup sultanas or raisins (Note 3)","3/4 tsp cinnamon","1/2 cup cream (, thickened/heavy (or bit of butter))"]}]', '[{"description":"Preheat oven to 180°C/350°F (all types).","images":[],"step":1},{"description":"Grease a 10 cup+ casserole dish with butter.","images":[],"step":2},{"description":"Place milk, sugar and vanilla in a saucepan over medium high heat. Bring to a simmer, stirring to dissolve the sugar, until the surface is foamy - do not boil, it will split.","images":[],"step":3},{"description":"Place rice, sultanas and cinnamon in baking dish. Pour over milk, give it a brief stir then cover with lid or foil.","images":[],"step":4},{"description":"Bake for 1 hour, stirring every 20 minutes to break up the rice that starts to set on the base.","images":[],"step":5},{"description":"After 1 hour, remove from oven and add cream. Give it a good stir - it will look a bit watery straight out of the oven but it evaporates quickly. I like mine creamy so it oozes when you serve it.","images":[],"step":6},{"description":"Serve immediately, just as is or with a scoop of vanilla ice cream if you want to take it over the top!","images":[],"step":7}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["cosy-desserts","dessert-recipes","puddings-cosy-desserts","quick-and-easy","rice-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_900850387f6f', 'en', 'US', 'Self Saucing Butterscotch Pudding', 'Recipe video above. One batter magically transforms into a warm butterscotch pudding with PLENTY of butterscotch sauce bubbling underneath! This pudding has terrific butterscotch flavour from the dark brown sugar as well as the golden syrup (see recipe for subs).', 'https://www.recipetineats.com/tachyon/2019/09/Self-Saucing-Butterscotch-Pudding_4.jpg', 15, 40, 55, 6, '[{"id": "ing_brown_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.083, "unit": "tub of 150g"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_golden_syrup", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_flour", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.004, "unit": "carton of 250ml"}}]', '[{"ingredients":["1/4 cup (50g) dark brown sugar (, packed (Note 1))","1 1/4 cup (185g) plain flour (all purpose flour)","2.5 tsp baking powder","100g / 7 tbsp unsalted butter (, melted)","1 egg","1/2 cup (125ml) milk (full or low fat)","4 tbsp golden syrup (Note 2)"],"purpose":"Butterscotch Pudding:"},{"ingredients":["3/4 cup (150g) dark brown sugar (, packed (Note 2))","2 tbsp cornflour / corn starch","2 cups (500ml) boiling water"],"purpose":"Butterscotch Sauce:"},{"ingredients":["Vanilla ice cream"],"purpose":"Serving"}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan).","images":[],"step":1},{"description":"Grease a 6 cup baking dish (1.6L/1.6Q) with butter.","images":[],"step":2},{"title":"Butterscotch Sauce","description":"Whisk sugar and cornflour in bowl. Set aside.","images":[],"step":3},{"title":"Pudding batter","description":"Place sugar, flour and baking powder in a separate bowl. Whisk to combine.","images":[],"step":4},{"description":"Add butter, egg, milk and golden syrup. Whisk until mostly lump free.","images":[],"step":5},{"description":"Scrape into baking dish and smooth surface.","images":[],"step":6},{"description":"Sprinkle Butterscotch Sauce sugar mixture all over surface.","images":[],"step":7},{"description":"Pour boiling water over the surface over the back of a dessert spoon held as close to the batter as you can (to soften the pour so it doesn''t break the surface of the batter).","images":[],"step":8},{"description":"Transfer to oven, bake 40 minutes or until skewer inserted into the cake part comes out clean.","images":[],"step":9},{"description":"Cut through pudding to reveal butterscotch sauce underneath.","images":[],"step":10},{"description":"To serve, scoop pudding into a bowl then douse with butterscotch sauce. Top with ice cream!","images":[],"step":11}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["cosy-desserts","dessert-recipes","puddings-cosy-desserts","quick-and-easy","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a8eaca278114', 'en', 'US', 'Strawberry Crumble', 'Recipe video above. A fabulous strawberry dessert recipe that''s quick and easy to assemble! Tender, juicy strawberries smothered in a self-creating strawberry syrup topped with a crumbly topping. The toughest part is deciding what to serve it with - ice cream, cream or custard??', 'https://www.recipetineats.com/tachyon/2018/08/Strawberry-Crumble_5.jpg', 15, 35, 50, 6, '[{"id": "ing_rolled_oats", "quantity": {"value": 0.225, "unit": "pack of 500g"}}, {"id": "ing_flour", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.017, "unit": "tub of 150g"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 90.0, "unit": "block of 250g"}}, {"id": "ing_strawberries", "quantity": {"value": 4.0, "unit": "punnet of 250g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.094, "unit": "pack of 400g"}}, {"id": "ing_sugar", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_cream", "quantity": {"value": 0.004, "unit": "carton of 250ml"}}]', '[{"ingredients":["3/4 cup rolled oats / oatmeal (quick cooking is ok)","3/4 cup white flour (, plain/all purpose)","3/4 cup brown sugar (loosely packed)","1/2 tsp baking powder","3/4 tsp cinnamon powder","Pinch of salt","90g / 6 tbsp unsalted butter (, melted)"],"purpose":"Topping"},{"ingredients":["1 kg / 2 lb strawberries (, ripe)","2 1/2 tbsp cornflour / cornstarch","1/3 - 1/2 cup white sugar (Note 1)","2 tbsp water","1 tsp vanilla extract"],"purpose":"Strawberry Filling"},{"ingredients":["Vanilla ice cream (, dollop cream or custard)"],"purpose":"To Serve"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Place all ingredients except butter in a bowl. Mix to combine. Add butter and mix to incorporate.","images":[],"step":2},{"description":"Strawberry Filling:","images":[],"step":3},{"description":"Hull / cut top off strawberries. Cut larger ones in half, leave small ones whole (2cm / 4/5\" height).","images":[],"step":4},{"description":"Place strawberries in bowl. Scatter over cornflour, toss well to coat evenly.","images":[],"step":5},{"description":"Add sugar, water and vanilla. Mix well.","images":[],"step":6},{"description":"Assemble and bake:","images":[],"step":7},{"description":"Pour strawberries into a baking pan (Note 2). Crumble over topping, using your fingers to get some nice crumbly chunks.","images":[],"step":8},{"description":"Bake for 30 to 40 minutes until the Topping is deep golden and the strawberry syrup is bubbling up energetically all around the edges - see video, this is a key sign that the strawberry sauce has thickened sufficiently.","duration":35,"images":[],"step":9},{"description":"Stand for a few minutes before serving with ice cream or your choice of topping.","images":[],"step":10}]', '["gluten","milk"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["cosy-desserts","dessert-recipes","easter-baking-desserts","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_afa6a8c393b2', 'en', 'US', 'Caramel Self Saucing Baked Apples', 'Sweet, plump, juicy Baked Apples that makes its own caramel sauce!! This is a terrific quick and easy dessert for assembling ahead then popping in the oven while you’re eating dinner. Just don’t forget the ice cream! Recipe video below.', 'https://www.recipetineats.com/tachyon/2018/06/Baked-Apples_2.jpg', 15, 40, 55, 4, '[{"id": "ing_apples", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.025, "unit": "pack of 400g"}}, {"id": "ing_walnuts", "quantity": {"value": 150.0, "unit": "jar"}}, {"id": "ing_maple_syrup", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_cinnamon", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_round_clove", "quantity": {"value": 0.625, "unit": "jar"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 75.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["4 apples (, juicy ones (Modi red apples are ideal, Note 1))","3/4 cup water","2 tsp cornflour/cornstarch"]},{"ingredients":["1 cup walnuts or pecans (, chopped (or sub with oats))","2 tbsp maple syrup (or honey or golden syrup)","1 tsp cinnamon","1/8 tsp ground cloves","1/2 cup brown sugar (, packed)","75 g / 5 tbsp unsalted butter (, melted)","Pinch of salt"],"purpose":"Filling/Sauce:"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Mix Filling ingredients together then set aside while you prep the apples – it will firm up and become scoopable (pop in fridge if its super hot where you are).","images":[],"step":2},{"description":"Cut the apples in half through the core then use an ice cream scooper, spoon or small knife to scoop out the core (see video).","images":[],"step":3},{"description":"Place apples in a baking dish so they are reasonably snug – you don’t want heaps of space around them. Pile Filling on the apples – I use an ice cream scoop.","images":[],"step":4},{"description":"Mix cornflour with a splash of the water, mix to dissolve, then add remaining water. Pour around the apples.","images":[],"step":5},{"description":"Cover with foil, bake 20 minutes. Remove foil, then bake a further 20 minutes until the crumb is deep golden and the apples are tender (but not sloppy soft) and there’s a syrupy caramel in the pan (it thickens a bit more when serving).","images":[],"step":6},{"description":"To serve, spoon over caramel sauce, then top with ice cream and serve with more sauce!","images":[],"step":7}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["cosy-desserts","dessert-recipes","dietary","easter-baking-desserts","gluten-free-recipes","puddings-cosy-desserts","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9a4d093ade4f', 'en', 'US', 'Spicy Asian Cucumber Salad', 'Recipe video above. If you love cucumbers, or even if you don''t, you have to try this Asian cucumber salad recipe! Smashing is a classic Asian technique, it creates crevices for the chunky chilli dressing to nestle in. The perfect combination of refreshing and firecracker heat. OBSESSED!Spice level - Decent warm buzz but not blow-your-head-off if you are using my go-to chilli crisp, the Laoganma Crispy Chilli Oil. Note 3.Scared of the chilli? Make Smashed Cucumbers with ginger sauce instead!', 'https://www.recipetineats.com/tachyon/2023/06/Eating-spicy-cucumber-salad-with-spoon.jpg', 7, 0, 37, 4, '[{"id": "ing_cucumber", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.3, "unit": "pack of 100g"}}, {"id": "ing_white_seame_seeds", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.1, "unit": "pack of 100g"}}]', '[{"ingredients":["4 cucumbers (~20cm/8\", scale up/down for shorter/longer, Note 1)","3/4 tsp cooking/kosher salt","1 eschalot/French onion (, halved then very thinly sliced (US: shallot) (Note 2))","1 cup green onion (, green part only finely sliced (1 large, 2 small stems))","2 tbsp+ chilli crisp (crispy chilli oil) - Laoganma is my fave (Note 3)","2 tsp white seame seeds (, toasted (save some for topping))"]},{"ingredients":["1 1/2 tbsp rice vinegar (sub any clear vinegar)","2 tsp soy sauce (, all-purpose or light (Note 4))","2 tsp sesame oil (, toasted (ie brown, not yellow))"],"purpose":"Dressing:"}]', '[{"description":"Smash & salt cucumbers","images":[],"step":1},{"title":"Smash","description":"Hit cucumbers with a meat mallet, rolling pin or similar to make the sides burst open. Cut in half lengthwise then into 2.5cm/1\" pieces.","images":[],"step":2},{"title":"Salt 30 min","description":"Place in a bowl, toss with salt. Set aside for 30 minutes to draw out water (Note 5). Drain/strain and discard salty water, leave cucumbers in same bowl.","duration":30,"images":[],"step":3},{"description":"Whisk Dressing in a bowl.","images":[],"step":4},{"title":"CHECK spiciness of your chilli crisp","description":"they vary by brand. If using Laoganma, stick with recipe, else adjust to taste.","images":[],"step":5},{"title":"Toss","description":"Put green onion, eschalots, sesame seeds, dressing and chilli crisp in with the cucumbers. Toss until eschalots go floppy - ~30 seconds.","images":[],"step":6},{"description":"Serve, sprinkled with extra sesame seeds and dollops of chilli crisp if you dare!","images":[],"step":7},{"title":"Note","description":"Water continues to come out of cucumbers so after few hours/next day, you''ll have a lot more dressing but not as intense flavoured. So eat/serve with spoon to get plenty of dressing in every bite!","images":[],"step":8}]', '["gluten","sesame","soy"]', '["keto_friendly","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Asian","Chinese"],"categories":["cucumber","quick-and-easy","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e3c19280c16c', 'en', 'US', 'Thai Glass Noodle Stir Fry (Pad Woon Sen)', 'Recipe video above. A big, family-size home-style Thai noodle stir fry using glass noodles, those thin clear noodles you probably bought by accident instead of rice vermicelli noodles and forgot about in the pantry - that''s me! Classic Thai flavours, savoury with a touch of sweet, with a nice hit of garlicky goodness. I chose vegetables that make this fast to make, but feel free to use what you want, just keep it to about 5 cups total. Soy sauce works fine if you don’t have MAGGI seasoning (every Thai household will have this though!). Adapted from this Pad Woon Sen on Hot Thai Kitchen. My recipe is scaled up, add-ins streamlined and sauce strength slightly tweaked to my palette.', 'https://www.recipetineats.com/tachyon/2026/03/Thai-Glass-Noodles-Pad-Woon-See_5.jpg', 15, 10, 25, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_broccoli", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_maggi_seasoning", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["250g / 8 oz dried bean thread noodles (glass noodles), prepared per packet (Note 1)","2 tbsp canola oil (, or other neutral oil suitable for stir fries)","1/2 onion (, cut into thin wedges)","4 garlic cloves (, finely minced (knife or crusher is fine))","1 big bunch Chinese broccoli (gai lan), or choi sum","3 eggs (, whisked)"],"purpose":"Glass noodle stir fry:"},{"ingredients":["350g / 12 oz chicken thighs (, boneless and skinless, sliced into small 5mm / 0.2\" thin strips (Note 3))","2 tsp MAGGI seasoning (or light soy sauce (Note 4))","Pinch white pepper (substitute black pepper)"],"purpose":"Chicken:"},{"ingredients":["2 tbsp oyster sauce (or vegetarian oyster sauce)","1 tbsp fish sauce","1 tbsp MAGGI seasoning (, substitute light or all-purpose soy sauce (Note 4))","1 tbsp canola oil (, or other plain flavoured oil)","1 tsp white sugar","1/8 tsp white pepper (substitute black pepper)"],"purpose":"Sauce:"}]', '[{"description":"Mix sauce, toss chicken in Maggi. In 30cm/12\" pan, cook onion 15 sec, cook chicken ~ 2 min, adding Chinese broccoli stems and garlic towards end. Push everything to side, drizzle oil, scramble eggs, mix everything together. Add Chinese broccoli leaves, noodles, sauce, toss well. Serve!","images":[],"step":1},{"description":"Toss chicken with MAGGI and pepper. Set aside while you finish preparing everything else.","images":[],"step":2},{"description":"Mix the sauce ingredients in a small bowl. (It won''t seem enough for the volume of noodles but trust the process! It packs a ton of flavour.)","images":[],"step":3},{"title":"Cook chicken and onion","description":"Heat 2 tablespoons of the oil in a large 30cm/12\" non-stick pan over high heat until very hot (see Note 5 if your pan is smaller). Add onion and stir for 15 seconds. Add chicken and stir for 2 minutes until almost cooked through.","duration":0.25,"images":[],"step":4},{"description":"Add garlic and Chinese broccoli stems. Stir for 1 minute or until chicken is cooked.","duration":1,"images":[],"step":5},{"title":"Scramble eggs","description":"Push everything to one side of the pan, drizzle 1/2 tablespoon oil in the cleared space. Pour the eggs in and gently stir to scramble. When it''s almost cooked, toss through the chicken.","images":[],"step":6},{"title":"Leaves, noodles and sauce","description":"Add the Chinese broccoli leaves, noodles (on top, to weigh down) then pour the sauce all over the noodles. Use two spatulas to toss until the noodles are all stained with sauce and there''s no water in the pan.","images":[],"step":7},{"description":"Serve immediately!","images":[],"step":8}]', '["egg","fish","gluten","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["cuisines","noodles","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_631884abba0c', 'en', 'US', 'Layered Golden Rice Bake with Spiced Meat', 'Recipe video above. This is essentially a streamlined version of Tachin, the iconic Middle Eastern saffron rice cake with its signature crispy crust, baked, then inverted like a pie. Here, I skip the flipping, use ingredients you can find at regular stores, and it''s a large format that serves 10 yet takes little more effort than Bolognese.The top gets crispy, the meat layered inside is fragrant with Middle Eastern spices, and the rice is vibrant yellow with the distinct perfume of saffron. If saffron threads are out of reach, use imitation powder instead. Though it won''t smell the same, you’ll still get vibrant yellow colour!PS. DO NOT SKIP THE LEMON YOGURT SAUCE! (Please, please🥰) See Note 5.', 'https://www.recipetineats.com/tachyon/2026/03/Golden-Saffron-Rice-Bake-with-Baharat-Spiced-Lamb_2.jpg', 30, 70, 100, 8, '[{"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_lamb_mince", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_baharat_spice_mix", "quantity": {"value": 37.5, "unit": "jar"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_cayenne", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_water", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_saffron_threads", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_water", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_yogurt", "quantity": {"value": 0.45, "unit": "tub of 500g"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_pine_nuts", "quantity": {"value": 0.375, "unit": "pack of 100g"}}, {"id": "ing_sour_cream", "quantity": {"value": 3.0, "unit": "tub of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_pine_nuts", "quantity": {"value": 0.375, "unit": "pack of 100g"}}]', '[{"ingredients":["1 1/2 tbsp olive oil","4 garlic cloves (, finely minced)","1 onion (, finely diced)","750g / 1 1/2 lb lamb mince (first choice), or beef (Note 1)","2 1/2 tbsp baharat spice mix (- store bought or make your own (Note 3))","2 tsp cumin powder","2 tsp cooking salt / kosher salt","1/2 tsp cayenne powder (, optional, for very subtle warmth)","3 tbsp tomato paste","1 small eggplant (, skin on, cut into 1cm / 0.4\" cubes, ~2 heaped cups (Note 2))","1 1/2 cups water"],"purpose":"Persian spiced meat filling:"},{"ingredients":["3 cups basmati rice (, uncooked)","1 tbsp cooking salt / kosher salt (, for rice cooking water)","1/2 tsp saffron threads (Note 4 for imitation powder, more cost effective)","2 tbsp boiling water","1 1/2 cups plain unsweetened yogurt (, full fat (regular, Greek or Greek-style))","2 large eggs (~55g/2oz each in-shell)","1/4 cup extra virgin olive oil","1 tsp cooking salt / kosher salt"],"purpose":"Golden rice:"},{"ingredients":["1/4 cup pine nuts (slivered or flaked almonds also great)","2 - 3 tbsp extra virgin olive oil (, for drizzling)"],"purpose":"Layering:"},{"ingredients":["3 batches Lemon Yogurt Sauce (YES 3 BATCHES!), or even plain yogurt or sour cream (Note 5)","2 tbsp coriander / cilantro roughly chopped (, optional garnish)","1 tbsp roughly chopped toasted pine nuts (, optional garnish)"],"purpose":"Serving:"}]', '[{"title":"Filling","description":"sauté onion and garlic, then cook lamb. Add spices, tomato paste then eggplant and water. Simmer 8 min until filling thickens. Saffron rice: grind saffron, soak in hot water. Mix with yogurt, oil, eggs and salt, mix in par boiled rice. Layer in pan with lamb, drizzle, bake 50 min until top is crispy. Slice and serve!","images":[],"step":1},{"description":"Preheat oven to 200°C/400°F (180°C fan-forced).","images":[],"step":2},{"title":"Toast pine nuts","description":"Heat a large non-stick pan (30cm/12\") over medium heat. Add pine nuts and toast for 1 minute, stirring constantly, until they have golden brown spots. Remove into a bowl and set aside.","duration":1,"images":[],"step":3},{"description":"Spiced lamb filling:","images":[],"step":4},{"title":"Cook meat","description":"In the same pan, heat the oil over high heat. Cook the onion and garlic for 1 1/2 minutes. Add lamb and cook, breaking it up as you go, for 5 minutes until you no longer see red.","duration":5,"images":[],"step":5},{"title":"Spices","description":"Add the baharat, cumin and salt. Cook for 1 minute, then stir in tomato paste. Add the eggplant and stir to coat in the flavours until you no longer see any white eggplant flesh.","duration":1,"images":[],"step":6},{"title":"Simmer","description":"Add the water and bring it to a rapid simmer. Lower heat to medium high, then simmer for 8 minutes, stirring regularly, until the filling is thick enough that you can draw a path across the pan and it holds in place. The eggplant should be mostly cooked through (cooks more in oven). It''s now ready for use (can use hot or or cool).","duration":8,"images":[],"step":7},{"title":"Soak saffron","description":"Grind the saffron mostly into a powder in a mortar and pestle (Note 4). Add hot water and leave for 5 minutes+ to soak.","duration":5,"images":[],"step":8},{"title":"Parboil rice","description":"Bring a large pot of water to the boil with the 1 tablespoon of salt. Add rice and boil for 5 minutes, stirring every now and then. Drain well in a colander. (The rice is only partially cooked, it finishes cooking in the oven).","duration":5,"images":[],"step":9},{"title":"Yogurt mixture","description":"Whisk together the yogurt, saffron water, oil, eggs and salt in a large bowl (or used rice boiling pot). Add rice and mix to combine - it will be pale yellow (becomes brighter once baked).","images":[],"step":10},{"description":"Assemble and bake:","images":[],"step":11},{"title":"Assemble","description":"Spread half the rice in a 23 x 33cm / 9 x 13\" dish. Spread over all the lamb mixture then sprinkle with pine nuts. Dollop remaining rice across the surface then spread.","images":[],"step":12},{"title":"Bake","description":"Drizzle over the extra virgin olive oil. Bake 50 minutes until the top is golden around the edges.","images":[],"step":13},{"description":"Rest 10 minutes in the pan then cut. Serve with Lemon Yogurt Sauce.","images":[],"step":14}]', '["egg","milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern","Persian"],"categories":["cuisines","dietary","gluten-free-recipes","middle-eastern-recipes","rice-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2cbcdaa90dec', 'en', 'US', 'Thai red duck curry', 'Recipe video above. There''s something magical about the combination of rich duck meat and Thai red curry! This duck curry recipe features duck breast with golden skin that''s thickly sliced and served in a coconut red curry sauce. Add lychees or pineapples for a very special dish that''s to die for!Note: the duck skin doesn''t stay super crispy given the saucy environment it ends up in. I like to serve the duck with most of the skin above the sauce line so it doesn''t go completely soggy, though if that doesn''t bother you it''s also nice to stir the duck slices throughout the sauce. Your choice!', 'https://www.recipetineats.com/tachyon/2025/01/Thai-red-duck-curry_8.jpg', 15, 30, 45, 4, '[{"id": "ing_duck_breast", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_thai_red_curry_paste", "quantity": {"value": 115.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 666.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_lime", "quantity": {"value": 6.0, "unit": "net of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_green_beans", "quantity": {"value": 120.0, "unit": "pack"}}, {"id": "ing_basil", "quantity": {"value": 20.0, "unit": "bunch"}}, {"id": "ing_ychees", "quantity": {"value": 8.0, "unit": "unit"}}, {"id": "ing_pineapple", "quantity": {"value": 1.25, "unit": "unit"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_basil", "quantity": {"value": 20.0, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_lime", "quantity": {"value": 6.0, "unit": "net of 500g"}}]', '[{"ingredients":["500g/ 1 lb duck breasts (, boneless, skin on (3 pieces) (Note 1))","1/4 tsp cooking salt / kosher salt","1/4 tsp white pepper (sub finely ground black pepper)"],"purpose":"Crispy skin duck:"},{"ingredients":["115g/ 4 oz (1/2 cup) Thai red curry paste","2 large garlic cloves (, finely grated (Note 3))","2 tsp fresh ginger (, finely grated (Note 3))","1 cup chicken stock/broth (, low sodium)","400ml/ 14 oz coconut milk (, full fat (Note 4))","6 - 8 makrut lime leaves (, crushed in hand (Note 5))","2 tsp white sugar","2 tsp fish sauce","120g/ 4oz green beans (, trimmed and cut in half)","1 lightly packed cup Thai basil leaves (sub regular basil, Note 6)"],"purpose":"Thai red curry:"},{"ingredients":["8 - 12 lychees (, whole, peeled, seed removed. Fresh best, canned ok too! (Note 7))","1 1/4 cups pineapple pieces (, preferably fresh, canned ok (Note 7))"],"purpose":"Lychees or pineapple – CHOOSE ONE:"},{"ingredients":["Jasmine rice (cook 2 cups of raw rice)","Thai basil leaves (, extra)","Coriander/cilantro leaves/small sprigs (, optional)","Large red chilli (, finely sliced (optional))","Lime wedges (, recommended)"],"purpose":"For serving / garnish:"}]', '[{"description":"Slash duck skin, season. Cold pan, no oil, 10 min medium low (weigh down duck) until golden. Reserve 3 tbsp fat. Finish in oven 8 min (target 60°C/140°F, medium), rest. Sauté curry paste in duck fat with garlic and ginger, add stock, reduce by half, add coconut, fish sauce, sugar, lime leaves, simmer 2 min. Add beans, simmer 3 min, add lychees or pineapple, simmer 2 min. Slice duck, serve!","images":[],"step":1},{"description":"Crispy golden duck breast:","images":[],"step":2},{"description":"Preheat the oven to 180°C/350°F (160°C fan-forced).","images":[],"step":3},{"title":"Score","description":"Sprinkle half the salt and pepper on the flesh of the duck. Turn. Use a sharp knife to make 5 or 6 diagonal scores on the skin of the breast. Don''t pierce the flesh and don''t cut all the way to the edge of the skin (Note 8). Pat the skin dry with paper towels, sprinkle with remaining salt and pepper.","images":[],"step":4},{"title":"Cold pan, no oil","description":"Don''t turn the stove on yet. Use an oven-proof pan (any type). Place the duck skin side down in the cold pan, no oil required. Place another pan on top to lightly weigh the duck down (keeps skin flat).","images":[],"step":5},{"title":"Cook 10 minutes","description":"Turn the stove onto medium low. Cook for 10 minutes or until the skin is golden and crispy. Fat will melt out of the duck skin and it will cook in its own fat. (Note 8)","duration":10,"images":[],"step":6},{"title":"Reserve duck fat","description":"Pour off 2 to 3 tablespoons of the duck fat into the pan you will use to make the curry sauce.","images":[],"step":7},{"title":"Oven 8 minutes","description":"Once the skin is crispy, turn and cook the flesh side for 1 minute. Then transfer the pan to the oven for 8 minutes or until the internal temperature is 60°C/140°F (medium, Note 9)","duration":1,"images":[],"step":8},{"title":"Rest","description":"Transfer to a rack or plate and rest for 5 minutes until ready to assemble the curry.","duration":5,"images":[],"step":9},{"description":"Thai red curry sauce:","images":[],"step":10},{"title":"Sauté curry paste","description":"Heat the duck fat (from step 6 above) on medium heat in a deep skillet. Cook the curry paste, garlic and ginger for 4 to 5 minutes. It will dry out and darken in colour, and substantially improves the flavour (especially store bought, but even homemade).","duration":4.5,"images":[],"step":11},{"title":"Sauce","description":"Add chicken stock, stir, then simmer rapidly to reduce by half (2 -3 minutes). Stir in coconut milk, hand-crushed kaffir lime leaves, sugar and fish sauce. Simmer gently on medium for 2 minutes.","duration":2,"images":[],"step":12},{"title":"Add ins","description":"Add the beans, simmer for 3 minutes until just cooked. Add the lychees or pineapple, simmer 1 minute. Taste and add a tad extra fish sauce if it needs salt.","duration":3,"images":[],"step":13},{"description":"Spoon some sauce in to cover the base of a large deep platter or wide bowl.","images":[],"step":14},{"description":"Slice duck breast, just shy of 5mm / 0.2\" thick. Place on the sauce, fanning it out slightly to expose the pink flesh.","images":[],"step":15},{"title":"Remaining sauce","description":"Spoon the remaining sauce, lychees etc around the duck, avoiding the duck skin.","images":[],"step":16},{"description":"Garnish with Thai basil leaves, coriander, chilli and lime wedges.","images":[],"step":17},{"title":"Serve","description":"Take to the table with flourish and serve with jasmine rice!","images":[],"step":18}]', '["fish"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["cuisines","curry-recipes","duck","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e9697f3f5416', 'en', 'US', 'Fall-apart massaman lamb shoulder', 'Recipe video above. Fall-apart succulent lamb smothered in a rich massaman curry sauce with melt-in-your-mouth potatoes that will take you 5 minutes to prepare. This larger-format version of Lamb Shanks Massaman Curry is made for groups: make up to 4 shoulders at once (serves 25 - 30!), reheats 110% perfectly (unlike lamb leg!), it looks impressive and a crowd pleaser. Plus it''s kid friendly because Massaman Curry isn''t spicy!', 'https://www.recipetineats.com/tachyon/2024/10/Massaman-lamb-shoulder_9a.jpg', 5, 270, 275, 6, '[{"id": "ing_lamb", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_maesri_massaman_curry_paste", "quantity": {"value": 114.0, "unit": "bottle"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 2.0, "unit": "jar"}}, {"id": "ing_star_anise", "quantity": {"value": 2.0, "unit": "jar"}}, {"id": "ing_potato", "quantity": {"value": 600.0, "unit": "bag of 2kg"}}, {"id": "ing_chilli", "quantity": {"value": 20.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2-2.25kg/ 4 - 4.5 lb lamb shoulder (, bone in, excess fat trimmed (but leave thin fat layer on (Note 1))","114g/ 4oz (1/2 cup) Maesri Massaman curry paste (1 can) (, or other brand (Note 2))","400g/ 14 oz can coconut milk (, full fat (Note 3))","3 cups chicken stock/broth (, low sodium)","1 onion (, halved then cut into 1 cm / 1/2\" thick wedges)","2 cinnamon sticks (or 1/2 tsp powder)","2 star anise (won''t ruin if you don''t have this)","600g/ 1.2 lb small baby potatoes (, whole (don''t cut cubes, Note 4))"]},{"ingredients":["2 large red chillis (, finely sliced diagonally (optional))","1 cup (lightly packed) coriander leaves & sprigs (cilantro) (, highly recommended)","Jasmine rice (basmati also excellent)"],"purpose":"Garnishes / serving:"}]', '[{"description":"Abbreviated recipe:","images":[],"step":1},{"description":"Whisk curry, coconut and stock, put lamb in upside down. Add spices and potatoes, foil cover, roast 1 hour at 220°C/425°F (200°C fan), 3 hours 180°C/350°F (160°C fan) or until fall-apart. Uncover, turn lamb, 30 minutes. Garnish, serve!","images":[],"step":2},{"description":"Full recipe steps:","images":[],"step":3},{"description":"Preheat the oven to 220°C/425°F (200°C fan-forced).","images":[],"step":4},{"description":"Whisk the curry paste, coconut milk and chicken stock in a pan until lump free. Put lamb shoulder in, turn to coat in the sauce then place it so it''s upside down (ie meaty / fat side down).","images":[],"step":5},{"description":"Place the onion, cinnamon sticks, star anise and potatoes around the lamb. Cover with foil.","images":[],"step":6},{"title":"Slow-cook","description":"Roast for 1 hour. LOWER the oven to 180°C/350°F (160°C fan) then roast for a further 3 hours. (Note 5)","images":[],"step":7},{"title":"Check","description":"Remove foil and use forks to check the meat is virtually “fall-apart-tender”, it should be by this time. If not, cover and keep cooking.","images":[],"step":8},{"title":"Brown","description":"Turn the lamb over, spoon over sauce. Bake uncovered 30 minutes or until deep golden. (Note 6 for sauce adjustments)","images":[],"step":9},{"title":"Serve","description":"Rest for 10 - 15 minutes. Spoon off as much or as little excess fat off surface, discard. Mix sauce well (it''s quite runny, if it was thicker it''d be too rich). Transfer to a serving dish, if you like, sprinkle with chilli and coriander. Serve! (Note 7 for serving styles)","duration":12.5,"images":[],"step":10}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Thai-ish"],"categories":["cuisines","curry-recipes","iconic-dishes","lamb-recipes","main-dishes","mains","roast-lamb","roasts","stews","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_713940c7c1c2', 'en', 'US', 'Tray bake dinner: lamb kofta meatballs', 'Recipe video above. This easy sheet pan dinner combines beautifully spiced lamb kofta meatballs with colourful roast vegetables for a Middle Eastern dinner that''s as versatile as it is delicious. Stuff into warm flatbreads, serve with couscous or rice bowls, or add a side of roasted cauliflower for a substantial low-carb dinner.Less messy and healthier than pan frying - less oil! Tip: make meatballs on the large side so they don''t dry out in the oven.', 'https://www.recipetineats.com/tachyon/2024/03/Baked-lamb-kofta-meatballs_2.jpg', 20, 20, 40, 4, '[{"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_lamb_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_round_cinnamon", "quantity": {"value": 500.0, "unit": "jar"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.5, "unit": "jar of 50g"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.5, "unit": "jar of 50g"}}, {"id": "ing_quantity_tahini_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_yogurt", "quantity": {"value": 1.0, "unit": "tub of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_lettuce", "quantity": {"value": 9.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["1/2 onion (, grated using a box grater)","500 g / 1 lb lamb mince ((ground lamb), or beef)","1/4 cup panko breadcrumbs (sub regular breadcrumbs)","2 cloves garlic (, finely minced)","2 tbsp coriander/cilantro (, finely chopped)"],"purpose":"KOFTAS"},{"ingredients":["2 tsp cumin","2 tsp coriander","2 tsp paprika (plain, sub smoked)","1 1/2 tsp ground cinnamon","3/4 tsp cayenne pepper (a bit spicy, reduce to taste or leave out)","3/4 tsp cooking salt / kosher salt","1/2 black pepper"],"purpose":"KOFTA SPICES"},{"ingredients":["1 large red capsicum (, deseeded, sliced into 1 cm thick slices)","1 large yellow capsicum (, deseeded, sliced into 1 cm thick slices)","1 red onion (, cut into thin wedges)","1 tbsp extra virgin olive oil","1/4 tsp each cooking/kosher salt and pepper"],"purpose":"VEGETABLES"},{"ingredients":["1 quantity Tahini sauce","1 quantity Lemon Yogurt Sauce (or even just plain yogurt)"],"purpose":"SAUCE OPTIONS (Choose one):"},{"ingredients":["Olive oil spray (for the meatballs)","4 flatbreads (or rice, couscous or cauliflower rice)","3 cups shredded iceberg lettuce (or other leafy greens)","2 tomatoes (, halved, cut into thin slices)","1 tbsp coriander/cilantro leaves (, finely chopped, optional (for sprinkling))"],"purpose":"SERVING (wraps option)"}]', '[{"description":"Preheat oven to 200°C/400°F (180°C fan-forced).","images":[],"step":1},{"title":"Kofta meatballs","description":"Place the Kofta ingredients and spices in a bowl. Use your hands to combine thoroughly then roll 16 large-ish meatballs (I scoop all mixture onto a tray, then roll into balls). Spread them out on a large tray.","images":[],"step":2},{"title":"Vegetables","description":"Toss the vegetables with the oil, salt and pepper. Scatter around the meatballs.","images":[],"step":3},{"title":"Bake","description":"Spray the meatballs with oil. Bake for 15 minutes then switch the oven to the grill/broiler on high. Cook for a further 5 minutes to get some colour on the surface.","duration":15,"images":[],"step":4},{"title":"Serve","description":"Sprinkle with the chopped coriander then serve! To make wraps, stuff with lettuce, tomato, meatballs, and the cook capsicum and onion. Drizzle with lots of tahini sauce or Lemon Yogurt Sauce then tuck in! Other ideas: rice or couscous bowls or big salads - see below.","images":[],"step":5}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Middle Eastern"],"categories":["cuisines","lamb-recipes","meatball-recipes","middle-eastern-recipes","one-pot-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_df85461cf533', 'en', 'US', 'Tahini Sauce', 'This is my classic Tahini sauce recipe which is very versatile and a great way to make a creamy sauce without using mayonnaise.Serve with all things Middle Eastern. Drizzle over roasted vegetables, use as a dressing or as a dip for vegetable sticks, pita bread or crackers. It''s just a great, quick sauce recipe to know!Makes just over 1/3 cup (85 ml).', 'https://www.recipetineats.com/tachyon/2024/03/Tahini-sauce_7.jpg', 5, 0, 5, 4, '[{"id": "ing_tahini", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_water", "quantity": {"value": 2.5, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.167, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_honey", "quantity": {"value": 0.015, "unit": "jar of 500g"}}, {"id": "ing_pine_nuts", "quantity": {"value": 0.375, "unit": "pack of 100g"}}]', '[{"ingredients":["1/4 cup tahini (, hulled (Note 1))","2 1/2 - 3 tbsp water (Note 2)","1 tbsp lemon juice (Note 3)","1/2 garlic clove (, pressed through garlic crusher or grated using microplane (to make sauce smooth))","1/4 tsp cooking salt / kosher salt","1/4 tsp white pepper (sub black pepper, Note 4)","1 1/2 tsp honey (, optional (Note 5))"]},{"ingredients":["1/4 cup flaked almonds, pine nuts or pistachios (, toasted (Note 2))"],"purpose":"Garnish:"}]', '[{"description":"Mix Tahini Sauce ingredients until combined. It should be loose enough so it can be drizzled, but not too runny. Set aside 15 minutes to let the flavours meld.","images":[],"step":1},{"description":"Sauce for Middle Eastern cooked proteins (like Chicken Shawarma, Lamb Shawarma, koftas and meatballs) and in wraps, sandwiches","images":[],"step":2},{"title":"Roasted vegetables","description":"drizzle over roasted vegetables (carrots, cauliflower, broccoli, pumpkin, green beans and asparagus are some favourites)","images":[],"step":3},{"description":"Dip for pita bread, crisps or raw vegetable sticks, and things like Arayes (crispy Lebanese Meat Stuffed Pita Breads).","images":[],"step":4}]', '[]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Middle Eastern"],"categories":["cuisines","middle-eastern-recipes","sauces"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1431fc0ca79d', 'en', 'US', 'Panang Curry - real, from scratch', 'Recipe video above. This is a stunning Panang Curry made entirely from scratch. It''s for people who adore real Thai food, can handle the heat and understand that you just can''t replicate the fresh flavour of a real Penang Curry using paste from a jar! Not even using my favourite Maesri curry paste that I''ll happily use for Thai Red and Green Curry.It calls for a trip to the Asian store but once you have the ingredients, it''s straightforward to make. See SPICINESS note in notes section below - yep, it''s spicy, and it can''t be avoided!', 'https://www.recipetineats.com/tachyon/2023/08/Panang-curry-prawn_8-close-up.jpg', 30, 30, 60, 4, '[{"id": "ing_shrimp", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_roasted_peanuts", "quantity": {"value": 45.0, "unit": "jar"}}, {"id": "ing_lemongrass", "quantity": {"value": 40.0, "unit": "bunch"}}, {"id": "ing_eschalots", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_galangal_note_5", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_shrimp", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_oil", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_cream", "quantity": {"value": 1.25, "unit": "carton of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.018, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_green_beans", "quantity": {"value": 200.0, "unit": "pack"}}, {"id": "ing_basil", "quantity": {"value": 12.0, "unit": "bunch"}}, {"id": "ing_rice", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_peanuts", "quantity": {"value": 0.113, "unit": "jar"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}]', '[{"ingredients":["700g/ 1.4 lb whole raw prawns/shrimp ((ie shell on), medium ~8cm / 3\"long - Note 1)","350g / 12 oz boneless, skinless chicken thighs (, cut into 7mm/ 1/3\" slices)"],"purpose":"Protein – choose ONE:"},{"ingredients":["1 1/2 cups chicken stock/broth (, low-sodium (not fish/seafood - Note 2))"],"purpose":"For prawn stock (shrimp):"},{"ingredients":["2/3 cup dried Chinese chillies (not Thai!) ((24 x 6cm/2.5\" long, 1/2 cup (15g) once deseeded chopped) - Note 3)","3 tbsp roasted peanuts unsalted","2 lemongrass stems (, finely grated (2 x 20cm/8\" lengths) - Note 4)","2 eschalots (, roughly chopped (1/2 cup))","1 tbsp galangal, finely grated ((~1.5cm / 0.6\" piece) - Note 5)","5 garlic cloves (, finely minced)","1 1/2 tbsp shrimp paste in bean oil ( - Note 6)","1/2 tsp each ground coriander, cumin, nutmeg","1 tbsp (packed) finely sliced kaffir lime leaves ( (~ 6 leaves) - Note 7)"],"purpose":"Curry paste:"},{"ingredients":["3 tbsp canola oil","1 1/4 cups coconut cream (, full-fat (standard Aus 270ml small can ok))","3 1/2 tsp white sugar","4 1/2 tsp fish sauce","1/4 tsp cooking/kosher salt","200g/7oz green beans (, trimmed, cut in half (~1 1/2 cups))","12 Thai basil leaves ( - Note 8)"],"purpose":"Curry:"},{"ingredients":["Jasmin rice","2 tbsp unsalted peanuts (, finely chopped)","Red cayenne peppers (, finely sliced (optional))","Thai basil leaves (, 3 leaves per serving - Note 8)"],"purpose":"SERVING and GARNISHES"}]', '[{"title":"Simmer","description":"Peel and devein prawns, reserving heads and shells. Bring chicken stock to a simmer in a small pot on high heat. Add prawn heads & shells, bring back to a simmer, then reduce to low heat. Simmer uncovered for 15 minutes, periodically crushing the heads lightly with a potato masher and skimming off any orange scum.","duration":15,"images":[],"step":1},{"description":"Strain into a jug, discarding heads. You should have just over 300 ml (1 1/4 cups) of stock. Leave undisturbed to let the sediment settle (~ 5min+).","images":[],"step":2},{"description":"Cut chillies in half then tap / squeeze out seeds (use a chopstick if needed for stubborn seeds). Discard seeds (spicy!). Chop chilli.","images":[],"step":3},{"description":"Soak dried chillis in 2 cups of boiling water for 30 minutes. Drain in a colander, reserve soaking liquid.","duration":30,"images":[],"step":4},{"title":"Peanuts","description":"Put peanuts in a tall jar that comfortably fits the head of a stick blender (or use a small blender). Cover the jar opening with your hand and pulse until finely ground.","images":[],"step":5},{"title":"Blitz paste","description":"Add drained chillis and remaining Curry Paste ingredients, along with 1/4 cup of the reserved chilli soaking liquid. Blend, scraping down the sides as you go, for about 30 seconds until smooth, using extra chilli water only if needed to help blend.","images":[],"step":6},{"description":"Cooking:","images":[],"step":7},{"title":"Cook curry paste","description":"Heat oil in a large deep frying pan over medium-low heat. Cook curry paste for 5 minutes, stirring constantly. The paste should be drier, darker, smelling aromatic and no longer raw.","duration":5,"images":[],"step":8},{"title":"Sauce","description":"Add 1 cup (250 ml) prawn stock, being careful to pour off just the clearer liquid and leaving the sediment behind. Stir in the coconut cream, sugar, fish sauce and salt. Mix in the green beans.","images":[],"step":9},{"description":"Simmer for 2 minutes until the sauce thickens and the beans are half cooked.","duration":2,"images":[],"step":10},{"description":"Add prawns, stir, then simmer for another 2 minutes until the prawns are cooked. Stir in the Thai basil leaves. The final taste should lean mostly savoury and sweet, and medium spiciness.","images":[],"step":11},{"description":"Serve over jasmine rice garnished with chopped peanuts, chilli and more Thai basil leaves!","images":[],"step":12}]', '["fish","shellfish"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["cuisines","curry-recipes","iconic-dishes","prawns-shrimp","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_640c9bf238ad', 'en', 'US', 'Moroccan Lamb Meatballs', 'Recipe video above. The fragrance when these meatballs are cooking is outrageous! These meatballs are based on my fan-favourite Lamb Koftas, flavoured with a special blend of spices that smells so exotic but are everyday pantry staples!The Minted Yoghurt is fabulous - pairs so well with the flavour of these meatballs. See notes for suggestions for more sides - pictured in post stuffed in pita pockets.', 'https://www.recipetineats.com/tachyon/2017/07/Moroccan-lamb-meatballs_2.jpg', 25, 10, 30, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_lamb_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.225, "unit": "tub of 500g"}}, {"id": "ing_mint", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_lettuce", "quantity": {"value": 15.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_red_cabbage", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}]', '[{"ingredients":["1 1/2 tbsp olive oil (for cooking)"]},{"ingredients":["500 g / 1 lb lamb mince (ground lamb) (Note 1)","1 small onion (, grated using box grater (~1/2 cup, including juices, Note 2))","1/2 cup panko breadcrumbs (sub ordinary)","1 egg","2 cloves garlic, crushed","1/4 cup coriander/cilantro leaves (, finely chopped)","1 1/2 tsp EACH cumin, coriander, paprika (any, but I like smoked paprika)","1/2 tsp EACH cinnamon, cayenne pepper (add more for spicy)","1 tsp cooking/kosher salt","1/4 tsp black pepper"],"purpose":"Meatballs:"},{"ingredients":["3/4 cup plain yoghurt (I use Greek)","1/2 cup (tightly packed) mint leaves","2 tsp lemon juice","1/4 tsp cooking/kosher salt"],"purpose":"Minted Yoghurt Sauce (Note 3):"},{"ingredients":["4 pita pockets (, Lebanese or pita bread)","5 cups shredded lettuce (iceberg, cost/romaine)","2 tomatoes (, halved, thinly sliced)","1 red onion (, halved, finely sliced)","OR Shredded Red Cabbage, Carrot and Mint Salad (instead of lettuce, tomato and onion)","Extra coriander/cilantro leaves, (finely chopped (optional))"],"purpose":"To Serve as pockets:"}]', '[{"title":"Mint yogurt sauce","description":"Set aside 1/2 cup yogurt. Place all other ingredients in a jug that fits the head of a stick blender. Blitz until it turns green - it will be runny. Stir in reserved yogurt (this thickens it again). Refrigerate until required.","images":[],"step":1},{"title":"Meatballs","description":"Place all Meatball ingredients in a bowl. Mix well with your hands. Measure out 1 heaped tablespoon, then roll into balls. Repeat with remaining mixture - should have 20 - 24 meatballs.","images":[],"step":2},{"title":"Cook","description":"Heat oil in a large non stick pan over medium heat. Add half the meatballs and cook, turning to brown all over, for 8 minutes, or until cooked through. Transfer to plate. (Oven option - Note 4)","duration":8,"images":[],"step":3},{"title":"Serving","description":"Cut pita pockets in half, warm for 10 seconds in the microwave, then pry it open. Stuff with lettuce, tomato, onion, then meatballs (I do 2 per half pocket). Drizzle with Mint Yogurt Sauce and fresh coriander.","duration":0.16666666666666666,"images":[],"step":4}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern","Moroccan"],"categories":["cuisines","dinner-tonight","lamb-recipes","main-dishes","meatball-recipes","middle-eastern-recipes","moroccan","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f50b786c9ec4', 'en', 'US', 'Jewelled rice pilaf', 'Recipe video above. This gorgeous, vibrant Persian saffron rice is perfumed with spices and studded with dried nuts and fruit. Featured in post with fish koftas. See in post for a list of suggestions for other things to serve this with!', 'https://www.recipetineats.com/tachyon/2023/04/Jewelled-rice_2-1.jpg', 15, 30, 45, 6, '[{"id": "ing_saffron_threads", "quantity": {"value": 0.5, "unit": "jar"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_fennel_seeds", "quantity": {"value": 1.25, "unit": "jar"}}, {"id": "ing_cumin", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.016, "unit": "jar of 40g"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.016, "unit": "jar of 40g"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.562, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_lemon", "quantity": {"value": 0.005, "unit": "net of 500g"}}, {"id": "ing_cranberries", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_apricots", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_olden_raisins", "quantity": {"value": 0.25, "unit": "unit"}}, {"id": "ing_pistachios", "quantity": {"value": 0.25, "unit": "unit"}}, {"id": "ing_almonds", "quantity": {"value": 0.15, "unit": "pack of 250g"}}, {"id": "ing_pomegranate", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_pistachios", "quantity": {"value": 0.25, "unit": "unit"}}]', '[{"ingredients":["1/2 - 1 tsp saffron threads (125 - 250mg) (SUB: 1/4 tsp saffron powder OR 1/2 tsp tumeric powder) (Note 1)","2 tbsp boiling water"],"purpose":"Saffron water:"},{"ingredients":["2 tbsp (30g) ghee or butter (Note 2)","1/4 tsp fennel seeds","1/4 tsp cumin seeds","1 onion (, finely diced)","2 garlic cloves (, minced)","1 cinnamon stick","1/8 tsp all spice","1/8 tsp cardamom powder","1 1/2 cups basmati rice (Note 3)","2 1/4 cups vegetable stock (, low sodium (or chicken))","3/4 tsp cooking/kosher salt","2 bay leaves (preferably fresh, else dried)","1/2 tsp lemon zest"],"purpose":"Rice pilaf:"},{"ingredients":["1/4 cup dried cranberries","1/4 cup dried apricots (, cut in 1cm / 1/3\" pieces)","1/4 cup golden raisins","1/4 cup pistachios (, toasted (Note 5))","1/4 cup slivered almonds (, toasted (Note 5))"],"purpose":"Fruit & nuts (your choice, Note 4):"},{"ingredients":["2 tbsp (30g) ghee or butter, melted","1/2 pomegranate (, seeds only (Note 6))","2 tbsp coriander/cilantro leaves roughly chopped","2 tbsp roughly chopped toasted pistachios (Note 5)"],"purpose":"Finishing:"}]', '[{"title":"Soak saffron","description":"Grind saffron into a powder using a mortar and pestle (Note 1). Mix in boiling water then set aside while the rice is cooking.","images":[],"step":1},{"title":"Sauté","description":"Melt ghee or butter in large saucepan over medium high heat. Add fennel and cumin, then stir for 30 seconds. Add onion and garlic. Cook for 5 minutes. Add cinnamon, cardamom and all spice, then stir for 30 seconds. Add rice and stir for 1 minute to coat in the beautiful flavour.","duration":0.5,"images":[],"step":2},{"title":"Cook rice","description":"Add the stock, bay leaves, lemon, salt, fruit and nuts. Stir, bring to a simmer, then put lid on. Reduce stove to low (should still be simmering gently around edges), and cook for 14 minutes. Do not peek or stir!","duration":14,"images":[],"step":3},{"title":"Rest","description":"Quickly check to ensure liquid is absorbed. Remove from the stove (lid still on) and leave for 10 minutes.","duration":10,"images":[],"step":4},{"description":"Yellow! Pour over half the saffron water then very gently fluff the rice using a rubber spatula (so you don''t break the long rice strands). Once mostly mixed through, add remaining saffron water and ghee. Gently toss until the rice is all yellow.","images":[],"step":5},{"title":"Serve","description":"Tumble onto serving platter. Sprinkle with pomegranate seeds, coriander, pistachios and serve with fish koftas.","images":[],"step":6}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Middle Eastern","Persian"],"categories":["cuisines","middle-eastern-recipes","rice-recipes","rice-side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_86700367b746', 'en', 'US', 'Thai Black Sticky Rice Pudding', 'Recipe video above. Thai Black Sticky Rice Pudding is a traditional Thai dessert that is favoured by upscale modern Asian restaurants for its striking jet black colour. It’s hard to believe you can make something so delicious that is fundamentally made with just rice, water and sugar!', 'https://www.recipetineats.com/tachyon/2021/08/Close-up-black-sticky-rice.jpg', 10, 30, 280, 5, '[{"id": "ing_rice", "quantity": {"value": 150.0, "unit": "pack"}}, {"id": "ing_rice", "quantity": {"value": 150.0, "unit": "pack"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_pandan_leaves", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_shaved_coconut", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_mango", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["1 cup black glutinous rice (aka black sticky rice) (Note 1)","4 tbsp white glutinous rice (white sticky rice) (Note 1)","4 cups water","2 pandan leaves (, folded and knotted (Note 2))","1 cup (loosely packed) palm sugar (or brown sugar), grated with box grater (Note 3)","1/2 tsp salt"]},{"ingredients":["1/2 cup coconut cream (very highly recommended)","1/8 tsp salt","1/2 cup shaved coconut (, toasted, optional (Note 4))","Mango cubes or crushed peanuts (, for topping, optional)"],"purpose":"Toppings:"}]', '[{"title":"Soak rice","description":"Place both rices in a bowl and cover with water (5cm / 2\" above). Soak for 4 hours (up to 12 hours).","images":[],"step":1},{"description":"Strain the rice and add it to a small pot or large saucepan.","images":[],"step":2},{"title":"Pandan leaves","description":"Add the knotted pandan leaves.","images":[],"step":3},{"title":"Simmer 30 minutes","description":"Add 4 cups of cold water. Bring to boil. Turn stove down to low so it''s simmering very gently (small, slow little bubbles). Simmer 30 minutes (no lid), stirring frequently for the last 15 minutes and almost constantly towards the end (so the base does not catch).","images":[],"step":4},{"title":"Consistency","description":"Rice should be soft / fully cooked through, water reduced, and sauce should be creamy not watery (starch from rice thickens water).","images":[],"step":5},{"title":"Add sugar","description":"Stir in sugar and salt until it dissolves (~20 seconds).","images":[],"step":6},{"title":"Ladle into bowls","description":"it should ooze slowly, not be runny nor so thick it stays in a mound, see video for consistency. (If it''s too thick, add a touch of water and stir).","images":[],"step":7},{"title":"Toppings","description":"Mix coconut cream with salt. Drizzle onto rice pudding. Top with toasted coconut and mango if using. Serve immediately.","images":[],"step":8}]', '[]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Asian","Thai"],"categories":["cuisines","dessert-recipes","dietary","gluten-free-recipes","puddings-cosy-desserts","quick-and-easy","thai-recipes","vegan-lifestyle"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7b181e442b60', 'en', 'US', 'Thai Yellow Curry (from scratch!)', 'Recipe video above. Thai curries are famous for the sublime aromatic flavours balancing sweet, tart, savoury and spiciness. Thai Yellow Curry is one such magnificent example, with its rich yellow colour, incredible depth of flavour and a heady combination of both fresh and ground herbs and spices.This is made from scratch with a homemade Yellow Curry Paste. There are quite a few ingredients involved but if you truly want the best, it''s worth it!This is a creation the RecipeTin Team is proud to call our own - we worked damn hard on it! (Then we celebrated by making another 100 as the first meals we donated through RecipeTin Meals ❤️)SPICINESS: Adjust by varying fresh chilli. Use 1 for extremely mild, 2 for quite mild, 4 for spicy (but not blow-your-head off).', 'https://www.recipetineats.com/tachyon/2021/08/Thai-Yellow-Curry_26a.jpg', 30, 30, 60, 4, '[{"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_lemongrass", "quantity": {"value": 40.0, "unit": "bunch"}}, {"id": "ing_eschalots", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_turmeric", "quantity": {"value": 30.0, "unit": "jar"}}, {"id": "ing_galangal", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 13.333, "unit": "pack of 3 heads"}}, {"id": "ing_shrimp", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_fenugreek_powder", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.2, "unit": "carton of 250ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.025, "unit": "kg"}}, {"id": "ing_tamarind_puree", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_shrimp", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_bamboo_shoots", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_basil", "quantity": {"value": 16.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["10 dried red chillis (~6cm/2.5\" long), chopped into 1cm / 0.5\" pieces (Note 1)","1 - 4 fresh birds eye chillis (, deseeded, roughly (1 for extremely mild, 4 for fairly spicy, Note 2))","2 lemongrass stems (Note 3)","1 large or 2 small eschalots (, roughly chopped (~ 1/2 cup) (Note 4))","2 tbsp fresh turmeric (, finely grated (about 2cm / 0.8\" piece) (Note 5))","2 tbsp galangal (, finely grated (about 2cm / 0.8\" piece) (Note 6))","8 cloves garlic (, roughly chopped)","1 1/2 tbsp Thai shrimp paste in bean oil (Note 7)","1 tsp ground coriander","1 tsp ground cumin","1/4 tsp ground cardamom","1/2 tsp fenugreek powder (Note 8)","1/8 tsp white pepper (sub black)"],"purpose":"Thai Yellow Curry Paste:"},{"ingredients":["3 tbsp vegetable oil (or canola or peanut oil)","1 medium potato (, peeled, cut into 2.5cm / 1\" pieces x 1cm/ 0.4\" thick (Note 9))","1 small carrot (, peeled, sliced into 5mm / 0.2\" slices on the diagonal)","1 cup chicken stock (, low sodium)","300 ml / 10oz coconut cream (Note 10)","4 tsp fish sauce (, plus more to taste (Note 11))","5 tsp white sugar","2 tsp tamarind puree (Note 12)","350g / 12oz prawns/shrimp (, medium, peeled, tail on optional (700g/1.4lb unpeeled) (Note 13))","1/2 cup bamboo shoots (, canned, drained, loosely packed (Note 14))"],"purpose":"Curry:"},{"ingredients":["16 Thai basil leaves (highly recommended, Note 15)","1 Red chilli (, finely sliced (optional, use large for not spicy))","2 tbsp Crispy fried shallots (optional, store bought, Note 16)","Jasmine rice"],"purpose":"Garnishes & serving:"}]', '[{"title":"Soak dried chillis","description":"Roughly chop chillies and transfer to bowl, leaving behind seeds. Cover with boiling water and soak for 30 minutes then drain (reserve soaking water).","duration":30,"images":[],"step":1},{"title":"Check spiciness","description":"Have a nibble of soaked chilli, should not be that spicy. If it is spicy, only use 1/3 to 1/2 of the amount (Note 1).","images":[],"step":2},{"title":"Prepare lemongrass","description":"Remove woody top half and outer layers of lemongrass. Grate with microplane. (See in post or video for preparation demo)","images":[],"step":3},{"title":"Make curry paste","description":"Place chillis, lemongrass and all remaining curry paste ingredients in a jar just wide enough to fit a stick blender. Add 3 tablespoons chilli soaking water. Blitz with stick blender until smooth so there''s no hard grit - rub between your fingers to check - about 15 seconds on high. (Or use small food processor or Nutribullet, scraping down sides well).","images":[],"step":4},{"title":"Cook off curry paste","description":"Heat oil in a medium heavy based skillet over medium heat. (Mine is a 26cm / 10.5\" Lodget cast iron) Add curry paste and cook for 3 to 4 minutes until it dries out a bit a smells fragrant.","duration":3.5,"images":[],"step":5},{"title":"Reduce stock","description":"Add chicken stock, stir to dissolve paste, then simmer for 1 minute.","duration":1,"images":[],"step":6},{"description":"Cook curry:","images":[],"step":7},{"title":"Add remaining curry sauce ingredients","description":"Reduce heat to medium low. Add tamarind, fish sauce and sugar. Stir until tamarind is dissolved. Then stir in coconut, carrot and potato.","images":[],"step":8},{"title":"Simmer","description":"Bring to simmer, then simmer gently for 15 minutes or until potato is almost fully soft. Pierce with knife to check, it might take 20 minutes.","duration":15,"images":[],"step":9},{"title":"Prawns and bamboo shoots","description":"Add prawns and bamboo shoots. Stir, then cook for 3 minutes until prawns are just cooked.","duration":3,"images":[],"step":10},{"title":"ADJUST sauce","description":"Taste and adjust the curry sauce at this point. Thin sauce with stock or water, add salt, fish sauce or sugar if needed. See Note 17.","images":[],"step":11},{"description":"Serve! Transfer curry to serving bowl. Garnish with Thai Basil, fresh chilli and crispy shallots. Serve with jasmine rice.","images":[],"step":12}]', '["fish","peanuts","shellfish"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["cuisines","curry-recipes","iconic-dishes","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3f949117e775', 'en', 'US', 'Vegetable Tagine', 'Recipe video above. A vegetarian Moroccan stew loaded with heady and warm spices, filled with tender vegetables. Make this with any veg you have - just don''t skimp on the spices!!Pan-roasting each vegetable to get a bit of colour on them before simmering is worth the effort to get the most flavour out of the vegetables. Because colour = flavour! Serve with couscous.', 'https://www.recipetineats.com/tachyon/2021/01/Vegetable-Tagine_3.jpg', 30, 60, 90, 8, '[{"id": "ing_cardamom_powder", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_round_fennel_seeds_fennel_powder", "quantity": {"value": 7.5, "unit": "jar"}}, {"id": "ing_cayenne", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_turmeric", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_round_clove", "quantity": {"value": 7.5, "unit": "jar"}}, {"id": "ing_ginger", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.075, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_pumpkin", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_cauliflower", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.875, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_60z_green_beans", "quantity": {"value": 200.0, "unit": "pack"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_almonds", "quantity": {"value": 0.3, "unit": "pack of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}]', '[{"ingredients":["1 tbsp cardamom powder","1 tbsp coriander powder","1 tbsp cumin powder","1 1/2 tsp ground fennel seeds / fennel powder","1 tsp cayenne (omit for non-spicy)","2 tsp turmeric","1/4 tsp ground cloves","1/4 tsp ground ginger"],"purpose":"Tagine spice mix:"},{"ingredients":["5 tbsp olive oil","1/2 red onion (sliced; (sub any type of onion))","1 garlic clove (, finely minced)","800g/1.6lb butternut pumpkin / squash ((1/2 a small), peeled, cut into 2.5cm / 1\" cubes)","1 small eggplant (, cut into 2.5cm / 1/2\" cubes)","1/2 cauliflower head (, small, cut into bite size florets)","1 capsicum / bell pepper (, cut into 2.5cm / 1\" pieces (red or yellow))","2 tomatoes (, seeds removed, cut into 1cm / 1/3\" dice)","3 1/2 cups water","2 tsp salt","1/2 tsp black pepper","400g/ 14oz canned chickpeas (, drained)","200g / 60z green beans (, cut into 3.5cm / 1.5\" pieces (~2 cups cut))","Zest of 1 lemon","2 tbsp lemon juice"],"purpose":"Tagine (Note 1):"},{"ingredients":["1/2 cup slivered almonds (, toasted)","1/4 cup coriander / cilantro (, roughly chopped)","Plain yogurt","Pinch of paprika or cayenne pepper"],"purpose":"Garnishes / for serving:"}]', '[{"description":"Combine Tagine Spice Mix ingredients.","images":[],"step":1},{"description":"Preheat oven to 180°C/350°F.","images":[],"step":2},{"description":"Heat 1 tbsp oil in a large, heavy-based pot over medium high heat. Add garlic and onion, cook until onion is wilted (~ 1 1/2 minutes), then remove to a large bowl. Scrape out any remaining garlic bits from pan (so they don''t burn).","images":[],"step":3},{"description":"Add pumpkin / squash and cook, stirring, for 3 minutes or until lightly golden on most sides. Remove to same bowl.","duration":3,"images":[],"step":4},{"description":"Add 2 tbsp olive oil. Cook eggplant for 3 minutes until tinged with gold on most sides, remove to same bowl.","duration":3,"images":[],"step":5},{"description":"Add 1 tbsp oil if pot is looking dry. Add capsicum and cauliflower, cook for 2 minutes until the cauliflower is a bit golden on the edges. Remove into bowl.","duration":2,"images":[],"step":6},{"description":"Add tomato and cook for 1 minute. Add Spice Mix, stir for 1 minute.","duration":1,"images":[],"step":7},{"description":"Add all vegetables back to pot. Add water (it should just about cover the vegetables, they will sink), salt and pepper. Stir, bring to simmer on stove, then transfer to oven for 30 minutes. (Alternatively simmer on low stove, but stir gently otherwise veg may breakdown too much.)","duration":30,"images":[],"step":8},{"description":"Remove from oven, add beans and chickpeas. Simmer for 15 minutes uncovered on stove on medium-low to cook the beans and reduce the sauce.","duration":15,"images":[],"step":9},{"description":"Stir through lemon juice and zest. The idea here is that some of the veg (butternut, cauliflower) breaks down a bit to slightly thicken the sauce. It also gets thicker left overnight.","images":[],"step":10},{"description":"For a traditional experience, serve over couscous. Otherwise, try white, brown, or basmati rice, or quinoa. Or, serve just as is like a chunky stew. For a low-carb option try cauliflower rice! I like to top mine with a dollop of yogurt, a sprinkle of almonds, coriander/cilantro and a pinch of paprika or cayenne.","images":[],"step":11}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern","Moroccan"],"categories":["cuisines","dietary","gluten-free-recipes","low-calorie-recipes","middle-eastern-recipes","moroccan","stews","vegan-lifestyle","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7ac21d2cb7c7', 'en', 'US', 'Couscous', 'A traditional side dish of North African, commonly known as a Moroccan staple served with stewy things like Tagine. But essentially, I just use it like rice - serve it with anything!A light sprinkle of fresh herbs adds welcome colour, or fruit and nuts to add interest. Me, I do both! Exceptional served with Vegetable Tagine.Makes 5 cups (fluffed)', 'https://www.recipetineats.com/tachyon/2021/01/Couscous_4.jpg', 3, 10, 13, 6, '[{"id": "ing_couscous", "quantity": {"value": 300.0, "unit": "pack"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_apricots", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_currants", "quantity": {"value": 0.333, "unit": "unit"}}, {"id": "ing_almonds", "quantity": {"value": 0.12, "unit": "pack of 250g"}}]', '[{"ingredients":["2 cups couscous","2 cups chicken or vegetable stock (, low sodium)","1 tbsp extra virgin olive oil","1 tbsp lemon juice","1/2 tsp salt"]},{"ingredients":["2 tbsp coriander/cilantro (, finely chopped)","2 tbsp parsley (, finely chopped)"],"purpose":"Herb option:"},{"ingredients":["1/3 cup dried apricots (, chopped)","1/3 cup currants or sultanas","2 tbsp slivered almonds (, toasted)"],"purpose":"Fruit and nuts:"}]', '[{"description":"Heat chicken stock until boiling using whatever method you choose (stove, 3 - 4 minutes in microwave on high).","images":[],"step":1},{"description":"Pour over couscous in a heatproof bowl. Shake to level the couscous, cover with plate (or cling wrap).","images":[],"step":2},{"description":"Leave for 10 minutes, then fluff with fork. Stir through olive oil, lemon juice and salt.","duration":10,"images":[],"step":3},{"description":"Stir through either herbs or fruit & nuts. Or as I do, use it all! Keep warm until ready to use. Ideal served with Tagine, or anything Middle Eastern.","images":[],"step":4}]', '["gluten"]', '["low_calorie"]', '{"mealType":["main_course"],"cuisine":["Middle Eastern","Moroccan"],"categories":["cuisines","middle-eastern-recipes","moroccan","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5a8ea660f762', 'en', 'US', 'Lamb Shanks Massaman Curry', 'Recipe video above. Epic combination - fall apart lamb shanks in a rich massaman curry sauce, a wildy popular dish at upscale Thai restaurants! The coconut and spice infused flavour of the curry sauce is a dead set perfect match with the flavour of lamb meat. Don''t be fooled by the simplicty of this recipe - hours in the oven works magic. (Read in post if you are dubious!)SPICINESS - mild! Massaman curry is one of the mildest curries in Thai cuisine.', 'https://www.recipetineats.com/tachyon/2020/06/Lamb-Shanks-Massaman-Curry_0.jpg', 5, 180, 185, 5, '[{"id": "ing_lamb", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_maesri_massaman_curry_paste", "quantity": {"value": 114.0, "unit": "bottle"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_potato", "quantity": {"value": 400.0, "unit": "bag of 2kg"}}, {"id": "ing_star_anise", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1.5kg/ 3 lb lamb shanks (5 small, 4 medium, 2 - 3 large) (Note 1)","114g/ 4oz Maesri Massaman curry paste (1 can) (, or other brand (Note 2))","400ml/ 14oz coconut milk (, full fat (Ayam brand is best, Note 3))","2 cups chicken stock/broth (, low sodium (Note 4))","1 onion (, halved then sliced 1cm / 1/3\" thick (brown, white, yellow))","400g/ 14oz small potatoes (2.5cm/1\" wide, halve if bigger)","1 star anise","1 cinnamon stick"]},{"ingredients":["Red chilli (, finely sliced (small = spicy, large = less spicy))","Coriander/cilantro","Steamed jasmine rice"],"purpose":"Garnishes:"}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan).","images":[],"step":1},{"description":"Mix curry paste, coconut milk and stock in a 22 x 33cm / 9 x 13\" baking dish, preferably glass or ceramic (Note 5). Add onion, potato, star anise, cinnamon and lamb.","images":[],"step":2},{"description":"Turn shanks to coat in sauce, then cover with foil.","images":[],"step":3},{"description":"Bake in oven for 2 hours. Remove foil, bake for a further 1 hour (small shanks) or 1.5 hrs (medium to large shanks), turning lamb twice to brown evenly, until meat is so tender it can easily be teased apart with 2 forks.","images":[],"step":4},{"description":"Remove lamb onto plate. Carefully skim off excess fat off the surface (tilt dish, it''s easier) - I get about 1/3 cup. Mix sauce in baking dish - it should be reduced down to a syrupy thickness (Note 6).","images":[],"step":5},{"description":"Serve lamb with sauce over jasmine rice, garnished with chilli and coriander. For a larger banquet, put the curry out on a platter to share!","images":[],"step":6}]', '[]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","Modern Asian","Thai"],"categories":["cuisines","curry-recipes","iconic-dishes","lamb-recipes","lamb-shanks","slow-cooked-fall-apart","stews","sunday-supper","thai-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b357ff850d2b', 'en', 'US', 'Thai Green Curry', 'Recipe video above. This is how to make a really great QUICK green curry by pimping up curry in a jar, OR using a homemade green curry paste! Don''t skip frying off the curry paste, this makes all the difference. See Spiciness info in Note 1 (remember, Green Curry is supposed to be spicy!)', 'https://www.recipetineats.com/tachyon/2019/02/Thai-Green-Curry_5.jpg', 15, 20, 35, 4, '[{"id": "ing_thai_red_curry_paste", "quantity": {"value": 4.0, "unit": "bottle"}}, {"id": "ing_quantity_homemade_green_curry_paste", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 666.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_lemongrass", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 6.0, "unit": "net of 500g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 0.167, "unit": "carton of 12"}}, {"id": "ing_snow_peas", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_basil", "quantity": {"value": 16.0, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 6.0, "unit": "net of 500g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["4 - 6 tbsp Thai Green Curry Paste (Maesri best) OR (Note 1)","1 quantity homemade green curry paste (Note 1)"],"purpose":"Curry – use ONE:"},{"ingredients":["2 large garlic cloves (, minced)","2 tsp fresh ginger (, finely grated)","1 tbsp lemongrass paste (Note 2)"],"purpose":"Extras – for jar curry paste (Note 2):"},{"ingredients":["2 tbsp vegetable oil","1 cup (250ml) chicken or vegetable broth, low sodium","400 g/14oz coconut milk (, full fat (Note 4))","1 - 3 tsp fish sauce *","1 - 3 tsp white sugar *","1/8 tsp salt *","6 kaffir lime leaves (, torn in half (Note 5))","350 g/12 oz chicken thigh (, skinless boneless, sliced (Note 6))","2 Japanese eggplants, (, small, 1cm / 2/5\" slices (Note 7))","1 1/2 cups snow peas (, small, trimmed)","16 Thai basil leaves (Note 8)","Juice of 1/2 lime (, to taste)"],"purpose":"Green Curry:"},{"ingredients":["Crispy fried Asian shallots (, high recommended (Note 9))","Thai basil or cilantro/coriander (, recommended)","Green or red chillies slices (, optional)","Steamed jasmine rice"],"purpose":"Garnishes:"}]', '[{"description":"Heat oil in a heavy based skillet or pot over medium high heat.","images":[],"step":1},{"description":"Add curry paste (and garlic, ginger and lemongrass Extras, if using) and cook for 2 to 3 minutes until it mostly \"dries out\" - see video. Don''t breath in the fumes!!","duration":2.5,"images":[],"step":2},{"description":"Add chicken broth and coconut milk, mix to dissolve paste.","images":[],"step":3},{"title":"Curry in a jar seasonings","description":"Add 1 tsp fish sauce, 1 tsp sugar, no salt.","images":[],"step":4},{"title":"Homemade curry paste seasonings","description":"Add 3 tsp fish sauce, 3 tsp sugar, 1/8 tsp salt.","images":[],"step":5},{"description":"Add kaffir lime leaves. Mix then bring to simmer.","images":[],"step":6},{"description":"Add chicken, stir then lower heat to medium so it''s bubbling gently. Cook 7 minutes.","images":[],"step":7},{"description":"Add eggplants, cook 5 minutes until soft.","images":[],"step":8},{"description":"Taste sauce. Add fish sauce or salt for more saltiness, sugar for sweetness.","images":[],"step":9},{"description":"Add snow peas, cook 2 minutes until a bit softened, then stir through basil and lime juice. Sauce should have reduced but will still be a be on the thin side, not thick - that''s how it''s should be. DO NOT keep simmering - sauce will darken.","images":[],"step":10},{"description":"Serve curry over jasmine rice with garnishes of choice.","images":[],"step":11}]', '["fish"]', '["gluten_free","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["cuisines","curry-recipes","iconic-dishes","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_911abc5e0cf9', 'en', 'US', 'Middle Eastern Shredded Lamb', 'I can''t say with certainty that this is authentic because it''s a recipe I created. But it uses classic Middle Eastern ingredients, so possibly it is! The lamb is really juicy because it''s made with lamb shoulder, a cut that is made for slow cooking. The pan frying step to get the crunchy brown bits is not optional - it''s key! ! ! As with any shredded meat recipe, a little goes a long way. This makes around 8 cups of shredded lamb which I think is enough to serve 8 people as a main (with rice). See separate recipe below for Chickpea Pilaf (Rice).', 'https://www.recipetineats.com/tachyon/2015/05/Middle-Eastern-Shredded-Lamb-Chickpea-Pilaf-Rice-1.jpg', 10, 210, 220, 8, '[{"id": "ing_cumin", "quantity": {"value": 0.005, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_paprika", "quantity": {"value": 0.005, "unit": "jar of 40g"}}, {"id": "ing_cardamon", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.068, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.006, "unit": "pack of 3 heads"}}, {"id": "ing_lamb", "quantity": {"value": 1.75, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}]', '[]', '[{"description":"Preheat oven to 150C/300F.","images":[],"step":1},{"description":"Combine the Spice Mix ingredients in a small bowl. Set aside 1 1/2 tbsp of the Spice Mix for later (to pan fry the lamb).","images":[],"step":2},{"description":"Add the olive oil and garlic into the Spice Mix, then rub all over the lamb.","images":[],"step":3},{"description":"Place the lamb on a roasting rack set in a roasting dish (Note 1). Pour the water in the base of the dish. Cover with a lid or double layer of foil.","images":[],"step":4},{"description":"Roast for 3 1/2 hours or until the meat is tender enough to pull off with a fork.","images":[],"step":5},{"description":"Remove the lid. Turn the oven up as high as it will go and roast for 15 - 20 minutes until the lamb is browned.","duration":17.5,"images":[],"step":6},{"description":"Remove the lamb from the oven. Allow to rest for 20 minutes, then shred coarsely with two forks.","duration":20,"images":[],"step":7},{"description":"Skim excess fat off the juices in the roasting dish then set aside. (Note 2)","images":[],"step":8},{"description":"Browning the Shredded Lamb","images":[],"step":9},{"description":"Toss the shredded lamb with the reserved Spice Mix (from Step 2 above).","images":[],"step":10},{"description":"Heat 1 tbsp of oil in a heavy based pan over high heat. Add some lamb (don''t crowd the pan) and drizzle over about 3 tbsp of the pan juices. Cook until the underside is dark golden brown and crispy - about 1 to 1 1/2 minutes (the juices you poured over will evaporate).","images":[],"step":11},{"description":"If the lamb is cold, flip to warm the other side but do not brown too much (retains juiciness).","images":[],"step":12},{"description":"Remove lamb from the fry pan, and repeat with remaining lamb, adding extra oil if required.","images":[],"step":13},{"description":"To serve, drizzle with a squeeze of lemon juice (this makes a big difference) and top with fresh coriander, plus yoghurt (if using). Serve on Chickpea Pilaf (Rice).","images":[],"step":14}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Middle Easter / Moroccan"],"categories":["cuisines","dietary","gluten-free-recipes","lamb-recipes","main-dishes","middle-eastern-recipes","rice-recipes","side-dishes","slow-cooker-recipes","sunday-supper","uncategorized","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3809b53b94dc', 'en', 'US', 'Middle Eastern Lamb and Lentil Rice Pilaf', 'Coriander, cumin and cinnamon is a classic Middle Eastern spice combination that goes fabulously with lamb. It also works very well with beef. I swap between using spinach and silverbeet (chard) for this recipe because sometimes one is better value than the other, so I''ve included directions for both as they are slightly different (because spinach leaves are more delicate). I serve this with a side of fresh sliced tomatoes (without dressing) to make a complete meal. The clean flavours of the tomato are a perfect contrast to the aromatic rice.', 'https://www.recipetineats.com/tachyon/2014/08/Middle-Eastern-Pilaf-4.jpg', 5, 15, 20, 4, '[{"id": "ing_lamb", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_spinach", "quantity": {"value": 6.0, "unit": "bag of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_lentils", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_rice", "quantity": {"value": 150.0, "unit": "pack"}}, {"id": "ing_water", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.312, "unit": "jar of 40g"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_chilli", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["400 g / 13 oz mince/ground lamb","1 onion (, diced (brown, white or yellow))","6 cups (loosely packed) spinach or silverbeet/chard, roughly shredded","2 garlic cloves (, minced)","2 tbsp olive oil","1 tin lentils (, drained (400g/14oz) (Note 6))","1 cup rice (, preferably basmati (see notes))","1 1/2 cups water (see notes)"]},{"ingredients":["2 tsp coriander powder","2 1/2 tsp cumin powder","1/2 tsp cinnamon powder","1/2 tsp chilli powder (, or cayenne pepper or other hot chilli powder (not American Chilli Powder) (optional))","1 1/2 tsp salt","1/2 tsp ground black pepper","1 tsp sugar"],"purpose":"Spice Mix"},{"ingredients":["3 tomatoes (, sliced thickly)","Fried Asian Shallots (Scallions) (optional - see notes)","Parsley leaves (optional)"],"purpose":"To Serve"}]', '[{"description":"Heat oil in a large pot over medium high heat.","images":[],"step":1},{"description":"Add garlic and onion. Sauté for 2 to 3 minutes until golden and translucent.","duration":2.5,"images":[],"step":2},{"description":"Turn up heat to high and add lamb. Use spatula to break mince up and cook until browned.","images":[],"step":3},{"description":"Add Spice Mix and cook for 30 seconds until spices are fragrant and mixed through the mince.","duration":0.5,"images":[],"step":4},{"description":"If using silverbeet/chard, add half the silverbeet into the pan and sauté for 15 seconds until starting to wilt. (If using spinach, do not add any at this stage).","duration":0.25,"images":[],"step":5},{"description":"Add rice, water and lentils and stir. Bring to simmer, then put lid on and turn down heat to medium low.","images":[],"step":6},{"description":"Cook for 10 to 12 minutes until water is absorbed.","duration":11,"images":[],"step":7},{"description":"Remove pot from heat, take lid off and quickly spread the remaining silverbeet or all the spinach on top of the rice, then put the lid back on.","images":[],"step":8},{"description":"Rest rice for 10 minutes. Remove lid, stir through silverbeet/spinach and fluff up the rice.","duration":10,"images":[],"step":9},{"description":"Spoon rice into serving dish, top with Fried Asian Shallots and parsley if desired. Serve the sliced tomatoes on the side.","images":[],"step":10}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["main_course"],"cuisine":["Middle Eastern"],"categories":["cuisines","dinner-tonight","lamb-recipes","main-dishes","middle-eastern-recipes","rice-recipes","rice-side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2c7f58f7ad02', 'en', 'US', 'Middle Eastern Roasted Vegetables with Tahini Sauce', 'A simple Middle Eastern dish that''s perfect for using up left over veggies at the end of a week. You can use any vegetables you want, just make sure to cut them to size so they cook in roughly the same time. Stuffed into pitas, it makes a wonderful light meal or lunch, or a perfect side.', 'https://www.recipetineats.com/tachyon/2014/06/DSC_0035.jpg', 10, 30, 40, 2, '[{"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_zucchini", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_pumpkin", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_cauliflower", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_beetroot", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_tahini", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 0.09, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_za_atar_spice_mix", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_pine_nuts", "quantity": {"value": 0.3, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["1 red onion (, sliced thickly)","1 carrot (, cut into thick sticks)","1 zucchini (, cut into thick sticks)","1/4 pumpkin (, cut into 2\"/3cm cubes)","1 1/2 cups large cauliflower florets","1 beetroot (, cut into 1.5\"/2cm cubes)","2 tbsp olive oil","1 tsp salt","Black pepper"],"purpose":"Roasted Vegetables"},{"ingredients":["3 tbsp tahini","3 tbsp lemon juice","1 small garlic clove (, minced (or 1/2 large))","1/2 tsp salt","Black pepper","Water"],"purpose":"Tahini Sauce (see notes for alternative)"},{"ingredients":["2 tsp za''atar spice mix (see notes)","2 tbsp pine nuts (, dry roasted)","1 tbsp coriander (, chopped (or parsley))"],"purpose":"Garnishes"}]', '[{"description":"Preheat oven to 350F/180C.","images":[],"step":1},{"description":"Combine Roasted Vegetable ingredients, spread on baking tray and bake for 30 to 40 minutes.","duration":35,"images":[],"step":2},{"description":"Combine Tahini Sauce ingredients. Mix until smooth, and use water to adjust to the consistency of honey.","images":[],"step":3},{"description":"Pile roasted vegetables onto a plate. Sprinkle with za''atar, drizzle with Tahini Sauce, scatter over roasted pine nuts and coriander.","images":[],"step":4},{"description":"Serve with lebanese bread wedges or pita bread.","images":[],"step":5}]', '[]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Middle Eastern"],"categories":["cuisines","middle-eastern-recipes","quick-and-easy","side-dishes","side-salads","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_06fcb54912ed', 'en', 'US', 'Crispy Couscous Pancake with Tomato & Onion', 'A fabulous way to prepare couscous - everyone loves the crunchy burnt bits!', 'https://www.recipetineats.com/tachyon/2014/05/DSC_00611-680x680-1.jpg', 5, 20, 25, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_couscous", "quantity": {"value": 150.0, "unit": "pack"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["4 tbsp olive oil","1 cup couscous","1 tsp vegetable stock powder (or chicken stock powder, or just salt)","3/4 cup boiling water","1 brown onion, diced","2 medium tomatoes, diced (about 1 1/4 cups) (see notes)","1 tbsp tomato paste","1 tsp sugar","Handful coriander or parsley leaves (optional)","1/2 tsp salt","Fresh black pepper"]}]', '[{"description":"Combine couscous, stock powder (or salt) and water. Cover with cling wrap and put aside for 10 minutes, then fluff with a fork.","duration":10,"images":[],"step":1},{"description":"Heat 2 tbsp olive oil in a pan about 20cm wide over medium heat.","images":[],"step":2},{"description":"Add the onion and sauté until translucent and soft, but not browned - about 3 to 5 minutes.","images":[],"step":3},{"description":"Add tomato paste and sugar and stir for 1 minute.","duration":1,"images":[],"step":4},{"description":"Add the diced tomatoes, salt and black pepper and cook for 3 minutes.","duration":3,"images":[],"step":5},{"description":"Combine the tomato mixture and couscous, and mix well.","images":[],"step":6},{"description":"Wipe the pan (you don''t need to clean it thoroughly), then heat the remaining 2tbsp olive oil over medium heat.","images":[],"step":7},{"description":"Add the couscous mixture, using the back of a spoon to press the mixture firmly and evenly into the pan. The firmer you press it in, the better it will hold together.","images":[],"step":8},{"description":"Cover (even with a lid for a larger pot is fine) and leave for 10 minutes.","duration":10,"images":[],"step":9},{"description":"Remove from heat, loosen the edges slightly with a knife, put a plate on top, say a prayer, then flip quickly to invert the couscous pancake onto a plate with the crispy side up.","images":[],"step":10},{"description":"Serve warm while it is nice and crispy!","images":[],"step":11}]', '["gluten"]', '[]', '{"mealType":["main_course"],"cuisine":["Middle Eastern"],"categories":["cuisines","middle-eastern-recipes","pasta-recipes","quick-and-easy","side-dishes","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b95b2c12ce96', 'en', 'US', 'Peach Crumble Muffins', 'Recipe video above. Introducing my new favourite peach recipe - Peach Crumble Muffins! Soft buttery crumb littered with juicy bits of peach, and a crunchy, crumbly pecan topping. Amazing with ripe, in-season peaches, but honestly so good with canned peaches too!Top tip: Make sure your egg, yogurt and peaches are at room temperature, not fridge cold, else the batter will sieze and be too thick. Stays fresh 3 days (peaches keep the crumb moist).', 'https://www.recipetineats.com/tachyon/2026/02/Peach-muffins_4.jpg', 25, 25, 50, 12, '[{"id": "ing_peaches", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_peaches", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.15, "unit": "tub of 500g"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_flour", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.025, "unit": "tub of 200g"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_pecans", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}]', '[{"ingredients":["1 1/4 cups peaches (, ripe but firm, skin on, cut into small 1.25cm / 1/2\" pieces (Note 1))","3/4 cup Extra chopped peaches (- for topping)"],"purpose":"Peaches (2 large, 3 medium):"},{"ingredients":["100 g (7 tbsp) unsalted butter, melted, cooled","2/3 cup caster sugar / superfine sugar (granulated/regular white sugar ok too)","1/2 cup plain unsweetened yogurt (, at room temperature (Note 2))","1 large egg (, at room temperature (~55g/2oz shell-on weight))","1 tsp vanilla extract"],"purpose":"Wet batter ingredients:"},{"ingredients":["1 1/2 cups plain flour / all-purpose flour","1 tsp baking soda (bi-carbonate soda) (Note 3)","1/2 tsp cinnamon powder","1/8 tsp cooking salt / kosher salt"],"purpose":"Dry muffin ingredients:"},{"ingredients":["1/3 cup plain flour / all-purpose flour","1/3 cup (tightly packed) brown sugar","1/2 cup pecans (sub rolled oats for nut-free)","1/2 tsp cinnamon powder","1/8 tsp cooking salt / kosher salt","30g (2 tbsp) unsalted butter (, melted)"],"purpose":"Crumbly topping:"}]', '[{"description":"Mix Crumble ingredients. Whisk Dry and Wet ingredients in separate bowls, mix together, stir in peaches. Fill muffin tin, top with extra peaches, top with Crumble. Bake 200°C / 390°F (180°C fan) 23 - 25 minutes.","images":[],"step":1},{"description":"Preheat oven to 180°C / 350°F (160°C fan-forced).","images":[],"step":2},{"title":"Toast pecans","description":"Spread the pecans on a tray and place in the oven for 5 minutes. Remove, cool slightly then finely chop.","duration":5,"images":[],"step":3},{"description":"Turn oven up to 200°C / 390°F (180°C fan-forced). Line a 12 hole standard muffin tin with paper liners.","images":[],"step":4},{"title":"Crumbly topping","description":"Mix the flour, sugar, salt and chopped pecans using a fork in a small bowl. Add butter and mix until it resembles wet sand. Set aside.","images":[],"step":5},{"title":"Muffin batter","description":"Whisk the Dry ingredients in a large bowl. Whisk the Wet ingredients in a separate bowl. Pour the Wet into the Dry ingredients bowl then mix with a rubber spatula until the flour is almost incorporated - about 14 stirs, the batter will be lumpy.","images":[],"step":6},{"title":"Add peaches","description":"Add the 1 1/2 cups peach pieces, then mix just until you can no longer see flour and the peaches are dispersed. Minimum stirs is key here, for soft muffins!","images":[],"step":7},{"title":"Fill muffin tin","description":"Working quickly (Note 4), divide the batter between the holes, filling to the top - a lever ice cream scoop is super useful here! Lightly press the Extra peaches on top of each muffin, then spoon the Crumble on - just pile it on top and use it all!","images":[],"step":8},{"title":"Bake 23","description":"25 minutes (check first at 23 minutes), until a toothpick comes out clean. Leave in the muffin tin for 10 minutes then transfer to fully cool on a rack - or eat!","duration":10,"images":[],"step":9}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["cupcakes-and-muffins","muffin-recipes","peach-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c0887950c8a4', 'en', 'US', 'Mango muffins', 'Recipe video above. All too often, mango muffin recipes lack actual mango flavour. It''s not enough to just stir chopped mango into a muffin, and one mango is not enough for 12 muffins!But these muffins DO actually taste of mango, with mango puree stirred into the batter and plenty of chopped mango added! They sit tall and proud, with a crunchy top, lovely hint of coconut flavour and a beautiful soft crumb thanks to the moisture from the mangoes. You will need two very big mangos or three medium ones. If you are short, make sure you use the right amount for the puree then lose out on the chopped mango.', 'https://www.recipetineats.com/tachyon/2024/01/Mango-muffins_1.jpg', 20, 24, 44, 12, '[{"id": "ing_flour", "quantity": {"value": 0.338, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.031, "unit": "tub of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 50.0, "unit": "bottle"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_mango", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_mango", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_desiccated_coconut", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.113, "unit": "kg"}}]', '[{"ingredients":["2 1/4 cups plain flour (all-purpose flour)","1 1/4 tsp baking soda (bi-carbonate soda), sifted if lumpy (Note 1)","Pinch of salt"],"purpose":"Dry ingredients:"},{"ingredients":["1/3 cup unrefined coconut oil (or unsalted butter), melted and slightly cooled (Note 2)","1 large egg (55 - 60g/2 oz each in shell)","1 tsp white vinegar (Note 1)","3/4 cup white sugar (can reduce to 1/2 cup but no less)","1 tsp vanilla extract","1 cup (260g) mango puréed mango ((1 1/3 cups small chopped mango reduces to 1 cup once pureed, Note 3), room temp)"],"purpose":"Wet ingredients:"},{"ingredients":["2 cups (370g) chopped mango (, small, 8mm to 1 cm max, room temp (Note 3))","1/2 cup desiccated coconut (, unsweetened (finely shredded coconut))"],"purpose":"Add-ins:"},{"ingredients":["2 tbsp demerara sugar (Note 4)"],"purpose":"Crunchy topping:"}]', '[{"description":"Preheat oven to 220°C/425°F (200°C fan-forced). Spray a muffin tin with canola oil or grease well with butter. (Note 5)","images":[],"step":1},{"title":"Batter","description":"Whisk Dry ingredients in a medium bowl. Whisk all the Wet ingredients well in a separate large bowl until smooth. Pour the Dry ingredients into the Wet ingredients. Use a rubber spatula to mix together until the flour is almost incorporated.","images":[],"step":2},{"title":"Add-ins","description":"Add the chopped mango and coconut, then mix until you no longer see flour - stop mixing, even if there are a few flour lumps, else the muffin will be dry and tough. The mixture will be thicker than typical muffin batters because it gets a lot of moisture from the mangoes as it bakes.","images":[],"step":3},{"title":"Crunchy top","description":"Divide between muffin holes, it should be slightly mounded (as pictured in post). Sprinkle the top of each with 1/2 teaspoon of Demerara sugar.","images":[],"step":4},{"title":"Bake","description":"Place in the oven. Immediately turn the oven down to 200°C/390°F (180°C fan). Bake for 24 minutes or until the surface is golden and crunchy, and a skewer inserted into the middle comes out clean.","duration":24,"images":[],"step":5},{"title":"Cool","description":"Leave in the muffin tin for 10 minutes then transfer onto a cooling rack. Cool for at least another 10 minutes before grabbing one!","duration":10,"images":[],"step":6}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["cupcakes-and-muffins","muffin-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_76db1d8792e7', 'en', 'US', 'Melting Afghan chickpea curry', 'Recipe video above. I never knew chickpeas could be so meltingly creamy by adding a smidge of baking soda! I also love how the sauce is thickened by cooking lentils until they breakdown, two neat tricks picked up from this Pakistani Lahori Chanay by Sugar Spice & More. Combined with an Afghan spice mix from the chickpea curry in Parwana, a wonderful Afghan cookbook by Durkhanai Ayubi, adapted in pursuit of recreating the chickpea curry I had from Afghan Sufra in Lakemba, an area of Sydney known for its wonderful Middle Eastern and sub-continental food scene. I’m obsessed!', 'https://www.recipetineats.com/tachyon/2025/05/Afghani-Chickpea-Curry_0.jpg', 15, 45, 60, 5, '[{"id": "ing_ghee", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 2.0, "unit": "jar"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 7.5, "unit": "pack of 3 heads"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_lentils", "quantity": {"value": 0.188, "unit": "can of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_chickpeas", "quantity": {"value": 3.0, "unit": "can of 400g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.006, "unit": "tub of 200g"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_turmeric", "quantity": {"value": 7.5, "unit": "jar"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_round_clove", "quantity": {"value": 1.25, "unit": "jar"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["3 tbsp ghee (, substitute unsalted butter or coconut oil (for vegan))","2 cinnamon sticks (sub 1/2 tsp powder, add with other spices)","1 onion (, finely chopped)","1 1/2 tbsp grated ginger","1 1/2 tbsp grated garlic","2 bay leaves (, preferably fresh else dried)","1/2 cup dried red split lentils (Note 1)","1 cup water","1 litre vegetable stock (, low sodium)","1/2 tsp cooking / kosher salt","3 x 400g/14oz cans chickpeas (, drained (Note 2))","1/4 tsp baking soda / bi-carbonate soda (makes chickpeas creamy, optional)"]},{"ingredients":["1 tbsp coriander powder","1 tbsp cumin powder","1 1/2 tsp turmeric powder","3/4 tsp cardamom powder","1/4 tsp ground cloves"],"purpose":"Spices (Note 3):"},{"ingredients":["Basmati rice (and/or Afghan bread (Note 4), or other flatbread)","Yogurt (I like to slightly thin with water so it can be drizzled)","Fresh coriander / cilantro leaves (, roughly chopped)"],"purpose":"Serving:"}]', '[{"title":"Sauté","description":"Melt the ghee in a large pot over medium high heat. Add the cinnamon and toast for 30 seconds. Add the onion, ginger, garlic and bay leaves. Cook for 3 minutes until the onion is translucent (stir regularly so the garlic & ginger don''t catch).","duration":0.5,"images":[],"step":1},{"title":"Spices and lentils","description":"Add the Spices and stir for 30 seconds. Add the lentils and stir to coat in the spices.","duration":0.5,"images":[],"step":2},{"title":"Simmer lentils","description":"Add the stock and salt. Stir, bring to a simmer. Lower the head to medium, put the lid on and simmer for 15 minutes.","duration":15,"images":[],"step":3},{"title":"Simmer chickpeas","description":"Add the chickpeas, water and baking soda. Increase the heat to make it simmer again. Then lower the stove slightly and leave to simmer gently for 30 minutes without a lid or until the lentils mostly broken down to make a thin gravy (you can cook an extra 10 minutes to thicken more if you want).","duration":30,"images":[],"step":4},{"description":"Serve with rice on the side and Afghan or other flatbreads for dunking, drizzled with yogurt and sprinkled with fresh coriander if you want (I do).","images":[],"step":5}]', '["gluten","milk"]', '["vegetarian"]', '{"mealType":["dinner"],"cuisine":["Afghan","Middle Eastern"],"categories":["curry-recipes","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e669ddde7782', 'en', 'US', 'Lamb korma curry', 'Recipe video above. In stark contrast to bold spicy curries like Vindaloo, Lamb Korma is creamy, nutty and gently spiced. It''s easy to love and so family-friendly, I call it the "other butter chicken"! Slow cooked until the meat is fall-apart tender, I particularly love the subtle cashew flavour in the sauce from the pureed cashews, and the distinct flavour that lamb adds to sauce.* Oven method yields the best flavour but see note 8 for slow cooker, instant pot and pressure cooker methods. Super handy, and I was very happy with it!', 'https://www.recipetineats.com/tachyon/2024/05/Lamb-korma_main.jpg', 20, 150, 170, 4, '[{"id": "ing_onion", "quantity": {"value": 2000.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 2666.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_cashews", "quantity": {"value": 37.5, "unit": "jar"}}, {"id": "ing_water", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_ghee", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_lamb", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_round_turmeric", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_ginger", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_aram_marsala", "quantity": {"value": 5.5, "unit": "unit"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 10.0, "unit": "jar of 40g"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 2.0, "unit": "jar"}}, {"id": "ing_sugar", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_naan", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["2 large onions (, cut into 1cm/1/2\" squares (brown or yellow))","8 large garlic cloves (, peeled, halved)","4cm/ 1.5\" piece ginger (, peeled, sliced 3mm/0.2\" thick)"],"purpose":"Onion paste:"},{"ingredients":["1/4 cup cashews (, roasted, unsalted (~20 cashews))","1/3 cup water"],"purpose":"Cashew puree:"},{"ingredients":["3 tbsp ghee ((Note 1), or unsalted butter)","800g / 1.6 lb lamb shoulder ((Note 2), trimmed off excess fat, cut into 4-5 cm / 2\" cubes)","1/2 tsp ground turmeric","2 1/2 tsp ground ginger","5 1/2 tsp garam marsala (Note 3)","1 tsp kashmiri chilli powder (or smoked paprika + cayenne - Note 4)","2 cups chicken stock/broth (, low-sodium)","10 cardamom pods (green), lightly crushed, wrapped and tied in muslin or cheesecloth (Note 5)","2 cinnamon sticks","4 tsp white sugar","1 1/2 tsp cooking salt / kosher salt","1/2 cup coconut cream (, full-fat (Note 6))","1/2 cup cream (, full-fat (any type - thickened/heavy, pure etc)(Note 6))"],"purpose":"Lamb korma"},{"ingredients":["Basmati rice (or other plain white rice of choice)","Naan (, for dunking! (optional))","Cashews finely chopped (optional sprinkle)","Coriander/cilantro leaves (, roughly chopped (optional garnish))"],"purpose":"SERVING"}]', '[{"title":"Onion puree","description":"Place the onion, garlic and ginger into a tall container that fits the head of a stick blender. Blitz until smooth – about 5 to 10 seconds. Scrape into a bowl, set aside.","images":[],"step":1},{"title":"Cashew puree","description":"In the same jar, while covering the mouth of the jar with your hand (to prevent flying cashew comets), blitz the cashews and water with the stick blender until smooth, about 10 seconds. , Set aside.","images":[],"step":2},{"description":"Preheat the oven to 180°C/350°F (160°C fan-forced).","images":[],"step":3},{"title":"Reduce onion puree","description":"Melt and heat ghee in a ~24 cm/ 10\" oven-proof pot over high-heat. Cook the onion puree, stirring regularly, for 8 minutes until it has reduced by half. Don’t let it caramelise.","duration":8,"images":[],"step":4},{"description":"Add lamb, reduce to medium-high heat then stir until the meat changes from red to light brown. Don’t try to brown the meat (it won''t happen).","images":[],"step":5},{"title":"Sauce","description":"Add turmeric, ground ginger, garam marsala and kashmiri chilli, then stir through. Pour in the stock (the liquid should just barely cover the meat). Add cardamom pod sachet and cinnamon sticks, then stir. Bring to a simmer, cover with a lid then transfer to the oven.","images":[],"step":6},{"title":"Slow cook","description":"Cook for 1 1/2 hours. Stir in Cashew Puree, put the lid back on then return to the oven for another 30 minutes. The sauce should have thickened to a creamy consistency and lamb should be tender end to pull apart with forks with no effort. (Note 6)","images":[],"step":7},{"title":"Creamy sauce","description":"Place the pot on a low heat. Add the sugar, salt, coconut cream and cream, then stir. Simmer for 2 minutes, then you’re done!","duration":2,"images":[],"step":8},{"description":"Serve over basmati rice with a sprinkle of cashew nuts and coriander, if desired. Naan for dunking highly recommended!","images":[],"step":9}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["curry-recipes","indian-recipes","stews"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_48fe9b3f9de7', 'en', 'US', 'Vindaloo', 'Recipe video above. Vindaloo is a traditional Indian curry that''s not for the faint hearted! Big, bold curry flavours. Deep, vibrant red colour. Chunks of beef slow cooked to fall apart perfection. And yep, it''s spicy! For serious curry lovers, it''s hard to top this. As with all curries, use fresh spices for the best results (yes, spices fade in flavour over time). And no, unfortunately this won''t work in a slow cooker, pressure cooker or instant pot (Note 7).Serve with naan for mopping and yogurt for cooling. ** SPICE WARNING!!! Read Spiciness note below. **', 'https://www.recipetineats.com/tachyon/2021/07/Beef-Vindaloo_1.jpg', 20, 150, 170, 4, '[{"id": "ing_beef", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.9, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_s", "quantity": {"value": 4.0, "unit": "pack"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 4.0, "unit": "jar of 40g"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_ginger", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_fenugreek_seeds", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_turmeric", "quantity": {"value": 1.25, "unit": "jar"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.105, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_ghee", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.037, "unit": "jar of 200g"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_curry_leaves", "quantity": {"value": 10.0, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["800g / 1.6 lb beef chuck (, cut into 3cm / 1.2\" cubes (Note 1))","1 1/2 tsp salt"]},{"ingredients":["6 tbsp Kashmiri chilli powder - TEST spiciness before using! (Note 2)","2 tsp coriander seeds","3 tsp cumin seeds","4 cloves","4 cardamom pods (green)","2 tsp cinnamon powder","1/2 tsp black peppercorns","2 tbsp fresh ginger (, roughly chopped)","10 garlic cloves (yes, 10!)","1 tsp brown sugar","1 tsp fenugreek seeds (Note 3)","1/4 tsp turmeric powder","7 tbsp white vinegar","2 cups water"],"purpose":"Curry paste:"},{"ingredients":["50g / 3 tbsp ghee or unsalted butter (Note 4)","1 onion (, finely chopped (brown, yellow, white))","2 tsp ginger (, finely grated)","4 garlic cloves (, finely minced)","1 1/2 tsp black mustard seeds (Note 5)","2 tbsp tomato paste","10 curry leaves (, fresh (Note 6))","2 cups beef stock (, low sodium (if using homemade, add 1/2 tsp salt))"],"purpose":"Curry sauce:"},{"ingredients":["2 tbsp coriander/cilantro leaves (, roughly chopped)"],"purpose":"Garnish:"}]', '[{"title":"Salt beef","description":"Toss beef in salt.","images":[],"step":1},{"description":"Check spiciness of kashmiri chilli powder and adjust if desired. See Spiciness Note below.","images":[],"step":2},{"title":"Curry Paste","description":"Place Curry Paste ingredients in a Nutribullet or small food processor with 1 cup of the water. Blitz until smooth. Pour over beef. Pour remaining 1 cup water into Nutribullet, shake (to clean out remaining curry paste), then pour/scrape over beef.","images":[],"step":3},{"title":"Marinate beef","description":"Mix beef in curry paste, cover, then marinate 2 hours. (Note: marinade is fairly thin - the water cooks down during slow cooking.)","images":[],"step":4},{"description":"Preheat oven to 190°C/375°F (170°C fan).","images":[],"step":5},{"title":"Curry sauce","description":"Melt ghee over medium high. Cook onion, ginger and garlic until they become translucent - about 3 minutes.","images":[],"step":6},{"title":"Mustard seeds","description":"Add black mustard seeds then cook until onion is tinged with gold. Stir in tomato paste, cook 1 minute.","images":[],"step":7},{"title":"Puree sauce","description":"Add beef stock, stir. Transfer into a jug then use a stick blender to puree until smooth. Pour back into the pot.","images":[],"step":8},{"title":"Add beef","description":"Add beef and curry leaves, stir then bring to boil.","images":[],"step":9},{"title":"Slow cook","description":"Cover with a lid, then place in the oven for 2 hours or until beef is fall apart tender and the sauce has darkened in colour and thickened. (See Note 7 if sauce hasn''t reduced enough).","images":[],"step":10},{"title":"Serve","description":"Garnish with coriander, then serve over basmati rice with a side of naan!","images":[],"step":11}]', '["milk","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["curry-recipes","indian-recipes","slow-cooked-fall-apart","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e9df305d3217', 'en', 'US', 'Samosa Recipe', 'Recipe video above. Moist, spiced potato wrapped in tender, flaky pastry, Samosas are one of the world''s great street snacks! Despite this, it''s hard to find a great one.Here I''ve come up with what is my ideal Samosa – it''s just the right size, with the right thickness of flaky pastry and a deliciously moist potato filling, so that every bite is perfect. I''ve gone all the way and used authentic spices to remain true to this classic, and I daresay the result is better than any restaurant I''ve been to!Makes 12 Samosas.', 'https://www.recipetineats.com/tachyon/2021/02/Samosas-on-plate.jpg', 30, 15, 45, 12, '[{"id": "ing_flour", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_ajwain_seeds", "quantity": {"value": 0.013, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 0.24, "unit": "bottle"}}, {"id": "ing_water", "quantity": {"value": 0.09, "unit": "L"}}, {"id": "ing_potato", "quantity": {"value": 500.0, "unit": "bag of 2kg"}}, {"id": "ing_oil", "quantity": {"value": 0.12, "unit": "bottle"}}, {"id": "ing_cumin", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.005, "unit": "jar of 200g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.03, "unit": "pack of 100g"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_garam_masala", "quantity": {"value": 0.013, "unit": "jar"}}, {"id": "ing_amchur", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_asafoetida", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_cumin", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_turmeric", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_coriander", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_tamarind_dipping_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}]', '[]', '[{"description":"Potato Filling:","images":[],"step":1},{"title":"Boil potato until soft","description":"Peel then cut potatoes in half. Place in a pot of cold water, bring to boil then cook until very soft, ~10 minutes.","images":[],"step":2},{"title":"Mash roughly","description":"Remove the potatoes onto a plate and roughly mash with a fork, leaving some large chunks (we want some textural interest).","images":[],"step":3},{"title":"Cook spice seeds","description":"Heat oil in a large skillet over medium heat. Add the cumin seeds, mustard seeds & coriander seeds. Stir the spices for about 30 seconds or until fragrant – don''t let them burn!","images":[],"step":4},{"description":"Add the ginger, chilli, peas and continue to stir a further minute or so until the chilli is soft.","images":[],"step":5},{"title":"Add remaining spices","description":"Add the garam masala, amchur, asafoetida, cumin powder, turmeric and salt. Cook a further 30 seconds.","images":[],"step":6},{"description":"Add potato and gently stir to coat in spices for about 1 minute.","images":[],"step":7},{"title":"Cool","description":"Remove from the stove, stir in chopped coriander leaves. Spread potato mixture out on a plate and let it cool completely before using.","images":[],"step":8},{"title":"Mix dry ingredients","description":"Place the flour, salt and ajwain seeds into a bowl and stir to combine.","images":[],"step":9},{"title":"Rub ghee into flour","description":"Add the ghee or oil and mix with your fingertips until the dough resembles breadcrumbs. (This step is key to making flaky samosa pastry.)","images":[],"step":10},{"title":"Form a ball","description":"Add the water and mix with the flour until you form a ball of dough. It should be pliable and soft, but not so sticky it sticks to your hands,.","images":[],"step":11},{"title":"Rest 30 minutes","description":"Cover the dough in the bowl with glad wrap and leave to rest for 30 minutes.","duration":30,"images":[],"step":12},{"title":"Making the Samosas","description":"see video:","images":[],"step":13},{"title":"Cut into 6","description":"Cut the dough into 6 equal portions, then roll each into a ball. Keep the balls on a plate covered with cling wrap so they don''t dry out.","images":[],"step":14},{"title":"Place between paper","description":"Place one ball on a sheet of parchment/baking paper. Press down to flatten, then cover with another sheet of paper. Do not flour the work surface - it will dry the pastry out.","images":[],"step":15},{"title":"Roll out","description":"Roll the dough into a disc about 2mm / 1/10\" thick (~16cm /6.5” diameter).","images":[],"step":16},{"title":"Cut in half","description":"Cut through the centre to create two semicircles (2 samosas per disc).","images":[],"step":17},{"title":"Make cone","description":"Brush the straight side with water, then fold straight edge to join itself and form a cone. Overlap the edges by about 1 cm / 2/5\" then press edges to seal.","images":[],"step":18},{"title":"Fill with potato","description":"Make an \"O\" with your forefinger and thumb, then hold the cone in the \"O\". Fill with about 2 tbsp of Potato Mixture, lightly pressing in.","images":[],"step":19},{"title":"Seal","description":"Brush the open pastry edge with water, then press together so your Samosa is fully sealed. Place sealed edge down on work surface and press down to fold. Trim off excess pastry, fold in corners. Pinch the top corner to make it pointy.","images":[],"step":20},{"title":"Repeat with remaining Samosas","description":"you should make 12 in total.","images":[],"step":21},{"title":"Heat oil to medium","description":"In a deep pan or pot, heat 5cm / 2\" oil to 160°C/320°F). (Note 7)","images":[],"step":22},{"title":"Fry 1: Carefully drop 3","description":"4 samosas in the oil and cook for 3 minutes, moving them around occasionally (if they touch the base of the pot for too long, they get brown spots).","duration":3,"images":[],"step":23},{"title":"Drain and repeat","description":"Remove from the oil and drain on paper towels. Repeat with the remaining samosas.","images":[],"step":24},{"title":"Increase oil heat","description":"Increase the oil temperature up to 190°C/375°F.","images":[],"step":25},{"title":"Fry 2: Carefully place 3","description":"4 samosas at the time into the oil, and cook for 1 1/2 to 2 minutes until they are deep golden. Remove from the oil and drain on paper towels. Repeat with remaining Samosas.","images":[],"step":26},{"description":"Serve hot with Tamarind Sauce or a Mint Raita (see separate recipe card below this one)","images":[],"step":27}]', '["gluten","mustard"]', '["low_calorie","vegetarian"]', '{"mealType":["snack"],"cuisine":["Indian"],"categories":["curry-recipes","iconic-dishes","indian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_92e4271893a8', 'en', 'US', 'Palak Paneer – Indian Spinach Curry with Homemade Fresh Cheese', 'Recipe video above. A dish this iconic demands to be made properly – from scratch, with lots of fresh spinach and homemade paneer (Indian fresh cheese!) This is a magnificent vegetarian curry, packed with an extraordinary amount of nutrition and goodness!', 'https://www.recipetineats.com/tachyon/2021/02/Indian-Palak-Paneer_4.jpg', 45, 25, 70, 6, '[{"id": "ing_batch_homemade_paneer", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_ghee", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.5, "unit": "pack of 1kg"}}, {"id": "ing_fenugreek_seeds", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.01, "unit": "pack of 100g"}}, {"id": "ing_spinach", "quantity": {"value": 700.0, "unit": "bag of 250g"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.333, "unit": "carton of 250ml"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}]', '[{"ingredients":["1 batch homemade Paneer (Indian fresh cheese; recipe linked below)","30g / 2 tbsp ghee or unsalted butter (for pan frying, Note 2)"],"purpose":"Homemade Paneer (Note 1):"},{"ingredients":["30g/2 tbsp ghee or unsalted butter (Note 2)","1 1/2 onions (, finely chopped (brown or yellow))","1 tsp fenugreek seeds (whole) (Note 3)","1 tsp ground cumin","1 tsp ground coriander","3/4 tsp salt (, kosher/cooking salt (if using table salt, reduce by 1/4 tsp))","1/4 tsp black pepper","2 garlic cloves (, finely chopped)","2 tsp ginger (, finely grated (20g))","2 tomatoes (, peeled, seeded and diced (Note 4))","1 green chilli (, finely sliced (cayenne, Note 5))","700g/ 1.4lb fresh spinach leaves (English spinach) (, thoroughly washed and roughly chopped (~9 cups very tightly packed) (Note 6))","1/4 cup water","1/3 cup + 1 tbsp cream (pure, heavy or thickened)","1 tbsp lemon juice"],"purpose":"Palak Paneer:"}]', '[{"title":"Saute onion & spices","description":"Melt butter in a large pot over medium heat. Add onion, fenugreek, cumin, coriander, salt and pepper. Cook for 3 minutes until onion is softened but not golden.","duration":3,"images":[],"step":1},{"description":"Add garlic and ginger, cook for 2 minutes.","duration":2,"images":[],"step":2},{"description":"Add the tomato and chilli, cook for 3 minutes on a medium heat.","duration":3,"images":[],"step":3},{"title":"Add spinach: Add about 1/3 of the spinach","description":"or as much as you can handle in the pot (!) – and stir until wilted. Then add more spinach along with the water, cook again until wilted. Repeat until all the spinach is wilted.","images":[],"step":4},{"title":"Cook 10 minutes","description":"Cook, stirring every now and then, for 10 minutes still on a medium heat.","duration":10,"images":[],"step":5},{"title":"Cream & lemon","description":"Add the cream and lemon juice. Cook, stirring gently, for 3 minutes.","duration":3,"images":[],"step":6},{"title":"Puree half spinach","description":"Remove half the spinach into a tall container and blend it to a puree using a stick blender. Pour pureed spinach back into the pot, and stir to combine.","images":[],"step":7},{"title":"Add Pan Fried Paneer","description":"Gently stir in golden pan-fried paneer (see below). Stir gently to mix through.","images":[],"step":8},{"description":"Serve over basmati rice with fluffy, chewy homemade naan on the side!","images":[],"step":9},{"description":"Golden Pan-Fried Paneer (Note 8):","images":[],"step":10},{"description":"Cut paneer into 1.25cm / ½\" thick slices. Then cut each slice into 2.5cm x 2 x 1.25cm thick pieces / 1 x ⅘\" x ½\" pieces – approximately!","images":[],"step":11},{"description":"Melt half the ghee or butter in a non-stick pan over medium-high heat.","images":[],"step":12},{"title":"Place half the paneer in the pan and cook for 1","description":"1 1/2 minutes until light golden - I tend to make it deep golden because colour = more flavour, but traditional is just a hint of gold Turn, then cook the other side until light golden.","images":[],"step":13},{"description":"Remove onto paper towel-lined plate. Repeat with remaining butter and paneer. Use per recipe.","images":[],"step":14}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["curry-recipes","iconic-dishes","indian-recipes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0c5641317a17', 'en', 'US', 'Goan Fish Curry', 'Recipe video above. This famous Goan fish curry comes to you from Goa, a little pocket of Indian paradise that''s all about the sun, surf, sand and excellent seafood! Deeply aromatic with a tomato and coconut based sauce, this recipe has a few more spices and steps than the more home-style recipes you''ll find online because this aims to replicate the richer sauce and layers of flavour you get at (good) Indian restaurants.Once you''ve made this with fish, try it with prawns/shrimp - it''s also excellent!SPICINESS: Quite spicy as written, but not blow-your-head-off! I thoroughly enjoy it as written, not suffering. See Spice Note below for adjustment to reduce / eliminate spiciness.', 'https://www.recipetineats.com/tachyon/2020/10/Goan-Fish-Curry_6.jpg', 15, 20, 35, 4, '[{"id": "ing_chilli", "quantity": {"value": 20.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_turmeric", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_fenugreek_powder", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_round_clove", "quantity": {"value": 1.875, "unit": "jar"}}, {"id": "ing_garlic", "quantity": {"value": 10.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_tamarind_puree", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_water", "quantity": {"value": 0.09, "unit": "L"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.013, "unit": "jar of 200g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 20.0, "unit": "pack of 100g"}}, {"id": "ing_chilli", "quantity": {"value": 20.0, "unit": "pack of 100g"}}, {"id": "ing_tomato", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 20.0, "unit": "pack of 100g"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2 1/2 tbsp Kashmiri chilli powder (Note 1)","1 tbsp coriander","2 tsp cumin","1 tsp turmeric","1/2 tsp fenugreek powder (Note 2)","3/8 tsp ground cloves","6 cloves garlic (, minced)","1 tbsp fresh ginger (, finely grated)","2 tbsp tamarind puree (Note 3)","1/2 red onion (, chopped)","6 tbsp water (plus more, as needed)"],"purpose":"Curry paste:"},{"ingredients":["3 tbsp vegetable oil","1/2 tsp black mustard seeds (Note 4)","1/2 red onion (, cut in half again (like a quartered orange) and thinly sliced)","1 tbsp tomato paste","2/3 cup canned tomato pulp/polp (Mutti), OR tomato passata or crushed tomato, Note 5)","2/3 cup water","400ml/ 14oz coconut milk (, full fat (Note 6))","1 1/4 tsp salt (, cooking/kosher (or 3/4 tsp fine table salt))","1 1/2 tsp sugar","1/4 tsp chilli powder (pure chilli, not US Chili Powder which is a mix, Note 7)","2 long green chillies (, cut into half lengthwise and deseeded, optional (Note 8))","1 tomato (, cut into 8 wedges then into 2.5cm / 1\" chunks)","600g / 1.2 lb firm-fleshed white fish (, cut into 3cm / 1.25\" cubes (Note 9))"],"purpose":"Curry:"},{"ingredients":["1/4 cup fresh coriander/cilantro leaves","Finely sliced green chillies (, optional)","Basmati rice"],"purpose":"Garnishes / serving:"}]', '[{"description":"Place Curry Paste ingredients in a tall jug or milkshake container (something that fits the head of a blender stick) then blitz on high for 5 to 10 seconds until the onion is pureed. Add more water if needed to make it puree.","duration":0.125,"images":[],"step":1},{"title":"Sizzle black mustard seeds","description":"Heat oil over medium heat in a large pot. Add black mustard seeds and let them sizzle for 30 seconds - careful, they might pop!","duration":0.5,"images":[],"step":2},{"title":"Saute onion","description":"Add red onion and cook for 3 minutes until edges start to tinge with gold.","duration":3,"images":[],"step":3},{"title":"Cook off curry paste","description":"Add curry paste and cook for 3 minutes - to evaporate water, make spices bloom and cook garlic & ginger.","duration":3,"images":[],"step":4},{"title":"Cook off tomato","description":"Turn heat up to medium high. Add tomato paste and tomato pulp, cook for 2 minutes.","duration":2,"images":[],"step":5},{"title":"Coconut milk","description":"Add water, coconut milk, sugar, salt and chilli powder if using. Stir, then bring to simmer, low heat so it''s bubbling gently.","images":[],"step":6},{"title":"Simmer 2 minutes, add tomato & green chilli","description":"Simmer for 2 minutes, add tomato and green chilli.","duration":2,"images":[],"step":7},{"title":"Simmer 3 minutes","description":"Simmer for another 3 minutes, stirring every now and then - sauce should be thickened (not watery), it gets looser again when fish is added (because fish will drop some juices = even more flavour!).","images":[],"step":8},{"title":"Add fish","description":"Add fish, stir, cook for 3 to 4 minutes until fish easily flakes.","duration":3.5,"images":[],"step":9},{"title":"Garnish & serve","description":"Remove from stove and transfer to serving bowl. Garnish with coriander/cilantro and fresh green chillies if desired. Serve with basmati rice!","images":[],"step":10}]', '["fish","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["curry-recipes","fish-recipes","indian-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_92c0519c1b52', 'en', 'US', 'Rogan Josh (Indian Lamb Curry)', 'Recipe video above. An Indian lamb curry to die for! A heady combination of intense spices in a creamy tomato curry sauce, the lamb is fall apart tender and packs a serious flavour punch. While this recipe calls for a lengthy list of spices, you won''t need to take a trip to an Indian store to get them - they''re even sold at my local grocery store!', 'https://www.recipetineats.com/tachyon/2020/02/Rogan-Josh_4.jpg', 20, 150, 170, 4, '[{"id": "ing_hee", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.15, "unit": "jar of 40g"}}, {"id": "ing_s", "quantity": {"value": 4.0, "unit": "pack"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_lamb", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_paprika", "quantity": {"value": 0.75, "unit": "jar of 40g"}}, {"id": "ing_chilli", "quantity": {"value": 0.037, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 0.4, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.5, "unit": "jar of 40g"}}, {"id": "ing_turmeric", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_nutmeg_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_garam_marsala", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_fennel", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.15, "unit": "tub of 500g"}}, {"id": "ing_garam_masala", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_fennel", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.4, "unit": "bunch"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["3 1/2 tbsp ghee (, substitute butter (Note 1))","1 cinnamon stick","6 green cardamom pods (, lightly bruised)","4 cloves","1 large onion (, finely chopped)","3 cloves garlic (, finely minced)","1 tbsp ginger (, finely grated)","5 tbsp tomato passata (US: tomato puree/sauce, Note 5)","1 tsp cooking salt / kosher salt (halve for table salt, double for flakes)","750g/1.5lb boneless lamb shoulder (, cut into 3cm/1.2\" cubes (Note 6))","1 1/2 cups chicken stock (, salt reduced (broth))"]},{"ingredients":["2 tbsp paprika (, normal or sweet)","3/4 tsp chilli powder (or to taste, Note 2)","4 tsp ground coriander","4 tsp ground cumin","2 tsp turmeric powder","1/4 tsp nutmeg powder","1 tsp garam marsala (Note 3)","1/2 tsp fennel powder (Note 4)"],"purpose":"SPICES:"},{"ingredients":["1/2 cup plain yoghurt (Greek yogurt fine)","1/2 tsp extra garam masala (Note 3)","1/2 tsp extra fennel powder"],"purpose":"FINISHES"},{"ingredients":["Chopped coriander leaves, finely shredded ginger, yogurt","Basmati rice"],"purpose":"SERVING/GARNISH"}]', '[{"description":"Toast whole spices in ghee, then sauté onion, garlic and ginger. Toast ground spices 30 seconds, add tomato, salt, stock and lamb. Simmer gently covered 1 hr 45 min until lamb fork-tender, simmer with lid off 15 min to reduce. Stir in Finishes, serve!","images":[],"step":1},{"title":"Toast whole spices","description":"Melt ghee over medium heat in large heavy based pot. Add cinnamon, cardamom and cloves and cook for one minute.","images":[],"step":2},{"title":"Sauté","description":"Add onion and cook for 7 minutes, stirring frequently, until pieces are golden and starting the brown on the edges. Add the garlic and ginger, cook for another minute.","duration":7,"images":[],"step":3},{"title":"Toast spices","description":"Stir in the Spices, cook for 30 seconds.","duration":0.5,"images":[],"step":4},{"title":"Sauce and lamb","description":"Mix in the tomato puree and salt, then add stock and mix. Add lamb, stir, bring to simmer.","images":[],"step":5},{"title":"Simmer 1 h 45 min","description":"Place lid on and adjust heat to low or medium low so it''s simmering gently. Cook 1 hour 45 minutes, giving it an occasional stir, until lamb is quite tender - use 2 forks to check, it should pry apart pretty easily.","images":[],"step":6},{"title":"Reduce","description":"Remove lid, and continue cooking for another 15 minutes (to reduce sauce slightly) - lamb should be very tender by this stage.","images":[],"step":7},{"title":"Finish","description":"Stir in the Yogurt, the Extra garam marsala and fennel. Cook for another few minutes.","images":[],"step":8},{"description":"Serve with basmati rice, sprinkled with fresh coriander leaves and other garnishes if desired. More sides (pictured): Cucumber salad (Note 7) and Easy naan - No Yeast Flatbread","images":[],"step":9}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["curry-recipes","indian-recipes","lamb-recipes","main-dishes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e4a089c7c802', 'en', 'US', 'Curried Sausages', 'Recipe video above. A retro classic! Browned sausages smothered in a curry flavoured gravy with onions, carrots and peas. Skip the old school method of boiling sauces - that''s throwing away free flavour! Browning sausages in the same skillet used to make the curried gravy makes a MUCH tastier sauce. I promise!', 'https://www.recipetineats.com/tachyon/2019/04/Curried-Sausages_2.jpg', 5, 15, 20, 4, '[{"id": "ing_oil", "quantity": {"value": 7.5, "unit": "bottle"}}, {"id": "ing_sausages", "quantity": {"value": 1.2, "unit": "pack of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.3, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_peas", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["0.5 tbsp oil","600g / 1.2lb sausages (, of choice (Note 1))","2 garlic cloves (, minced)","1 onion (, halved and sliced)","1 carrot (, peeled, sliced on the diagonal)","1 tbsp curry powder (, or more (Note 2))","3 tbsp flour (, any type (Note 3 for GF))","2 cups (500ml) chicken stock/broth (, low sodium)","1 tsp sugar","1/2 tsp salt (, plus more to taste)","1/2 tsp black pepper","1 cup peas (, frozen)"]}]', '[{"description":"Heat oil in a large skillet over medium high heat.","images":[],"step":1},{"description":"Cook sausages, turning to brown all over then remove. Optional: slice sausages into pieces on the diagonal.","images":[],"step":2},{"description":"In the same skillet, add garlic and onion. Cook for 2 minutes until translucent.","duration":2,"images":[],"step":3},{"description":"Add curry powder and stir for 30 seconds.","duration":0.5,"images":[],"step":4},{"description":"Add flour and mix for 30 seconds.","duration":0.5,"images":[],"step":5},{"description":"Gradually pour in chicken stock, mixing constantly.","images":[],"step":6},{"description":"Add carrots, sugar, salt and pepper, stir well.","images":[],"step":7},{"description":"Add sausages and peas, bring to simmer and cook for 3 minutes or until sauce thickens.","duration":3,"images":[],"step":8},{"description":"Serve over mashed potato, rice, pasta or noodles. For low carb, try mashed cauliflower!","images":[],"step":9}]', '["gluten"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["curry-recipes","dinner-tonight","quick-and-easy","sausage-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_81a2e1367367', 'en', 'US', 'Chicken Biryani', 'Recipe video above. Curried chicken cooked in a pot buried under a mount of fragrant, fluffy rice. Biryani is a celebration of all that we love about Indian food! Make this with other proteins or vegetables - see notes. There''s a load of spices in this - and it''s worth it! (Plus you''ll find everything at every day supermarkets). Spiciness: moderate low.', 'https://www.recipetineats.com/tachyon/2018/08/Chicken-Biryani_1-1.jpg', 20, 60, 80, 8, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.2, "unit": "tub of 500g"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 2.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_round_turmeric", "quantity": {"value": 0.625, "unit": "jar"}}, {"id": "ing_cinnamon", "quantity": {"value": 1.25, "unit": "jar"}}, {"id": "ing_cayenne", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_garam_marsala", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.75, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.009, "unit": "kg"}}, {"id": "ing_s", "quantity": {"value": 10.0, "unit": "pack"}}, {"id": "ing_bay_leaf", "quantity": {"value": 5.0, "unit": "unit"}}, {"id": "ing_star_anise", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_cardamon_pods", "quantity": {"value": 6.0, "unit": "unit"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.338, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_saffron_threads", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_butter", "quantity": {"value": 0.25, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}]', '[{"ingredients":["750g (1.5 lb) chicken thighs (, skin on, bone in, halved along bone (Note 1))"]},{"ingredients":["2/3 cup (150 ml) yoghurt (, plain)","1/2 cup (125 ml) water","2 tbsp vegetable oil (or other plain oil)","6 garlic cloves (, minced)","2 tsp finely grated fresh ginger","1/8 tsp ground turmeric","1/4 tsp cinnamon","1/2 tsp cayenne (adjust spiciness to taste)","1/2 tsp ground cardamom","2 tsp garam marsala (Note 2)","2 tsp coriander","1 tbsp cumin","2 tbsp paprika (, sweet / ordinary (not smoked))","1 3/4 tsp salt"],"purpose":"Marinade:"},{"ingredients":["2 tbsp salt","10 cloves","5 dried bay leaves","1 star anise","6 green cardamon pods","2 1/4 cups (450g) uncooked basmati rice (Note 3)"],"purpose":"Par Boiled Rice:"},{"ingredients":["2 medium onions (yellow, brown) (, halved and finely sliced)","1 cup (250 ml) oil (, for frying)"],"purpose":"Crispy Onions (Note 4):"},{"ingredients":["1 tsp saffron threads (loosely packed) (Note 5)","2 tbsp warm water"],"purpose":"Saffron:"},{"ingredients":["1 cup coriander / cilantro (, chopped)","1/4 cup (60g) ghee or unsalted butter (, melted (Note 6))"],"purpose":"Biryani:"},{"ingredients":["Crispy onions (above)","Chopped coriander / cilantro","Yoghurt (Note 7)"],"purpose":"Garnish:"}]', '[{"description":"Mix Marinade in a large pot (about 26cm / 11\" diameter). Add chicken and coat well. Marinade 20 minutes to overnight.","images":[],"step":1},{"description":"Par Boiled Rice:","images":[],"step":2},{"description":"Bring 3 litres / 3 quarts water to the boil, add salt and spices.","images":[],"step":3},{"description":"Add rice, bring back up to the boil then cook for 4 minutes, or until rice is just cooked still a bit firm in the middle. Rice will taste salty at this stage, disappears in next stage of cooking.","duration":4,"images":[],"step":4},{"title":"Drain immediately. Set aside. (Note 10 re","description":"leaving whole spices in)","images":[],"step":5},{"description":"Heat oil in a large saucepan over medium high heat. Cook onion, in batches, for 3 to 4 minutes, until golden brown. Don''t burn - they become bitter.","duration":3.5,"images":[],"step":6},{"description":"Remove onto paper towel lined plate. Repeat with remaining onion.","images":[],"step":7},{"description":"Place in a bowl, leave for 10 minutes+.","duration":10,"images":[],"step":8},{"description":"Place pot with chicken in it onto a stove over medium heat. Cover and cook for 5 minutes.","duration":5,"images":[],"step":9},{"description":"Remove lid. Cook for 5 minutes, turning chicken twice.","duration":5,"images":[],"step":10},{"description":"Remove from heat.","images":[],"step":11},{"title":"Turn chicken so skin side is down","description":"it should cover most of the base of the pot.","images":[],"step":12},{"description":"Scatter over half the onion then half the coriander.","images":[],"step":13},{"description":"Top with all the rice. Gently pat down and flatten surface.","images":[],"step":14},{"description":"Drizzle saffron across rice surface in random pattern, then drizzle over ghee.","images":[],"step":15},{"description":"Place lid on. Return to stove over medium heat.","images":[],"step":16},{"description":"As soon as you see steam, turn down to low then cook for 25 minutes.","duration":25,"images":[],"step":17},{"description":"Remove from stove, rest with lid on for 10 minutes.","duration":10,"images":[],"step":18},{"description":"To Serve:","images":[],"step":19},{"description":"Aim to serve it so you get nice patches of yellow rice, white rice, the curry stained rice + chicken (rather than all mixed up). To do this, use a large spoon and dig deep into the pot, and try to scoop up as much as you can in one scoop.","images":[],"step":20},{"title":"Turn out into bowl","description":"or onto platter. Garnish with remaining onion and coriander with yoghurt on the side (see Note 7 for Minted Yoghurt)","images":[],"step":21}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["curry-recipes","dietary","gluten-free-recipes","iconic-dishes","indian-recipes","main-dishes","rice-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_867a0a7f10f7', 'en', 'US', 'Dal (Indian Lentil Curry)', 'Recipe video below. There are countless variations of Dal all across India. This is a northern Indian version called "dal tadka" that''s akin to what is served in Indian restaurants. "Tadka" refers to spices sizzling in hot oil that''s poured over the dal. It''s dramatic and gives it a flavour bump - but is optional. I include it for company, and leave it out for midweek or if being served alongside other punchy flavoured curries. Heat level in this recipe is mild - just a tickle. If you like it fiery, try leaving in the seeds in the chillies and/or adding some chilli powder. This is a dal that''s flavourful to have as a main!', 'https://www.recipetineats.com/tachyon/2018/07/Dal_0-2.jpg', 15, 90, 105, 3, '[{"id": "ing_ghee", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.02, "unit": "pack of 100g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 2.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_curry_leaves", "quantity": {"value": 8.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_cumin", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_chana_dal", "quantity": {"value": 150.0, "unit": "pack"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_turmeric", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_aram_marsala", "quantity": {"value": 0.125, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_hee", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_green_onion", "quantity": {"value": 0.04, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.013, "unit": "jar of 200g"}}, {"id": "ing_chilli", "quantity": {"value": 0.02, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2 tbsp / 30 g ghee (, or 1 tbsp oil + 1 tbsp/15g butter (Note 1))","2 green cayenne chillies (, deseeded and cut into chunks (optional) (Note 2))","1 medium onion (, finely chopped (brown or yellow))","6 garlic cloves (, finely chopped)","1 tbsp ginger (, finely chopped (1.5cm / 3/5\"))","8 fresh curry leaves (, or 6 dried (Note 3))","1 tomato (, chopped)","1/2 tsp ground cumin","1 cup dried chana dal (, yellow split peas or other yellow lentils (Note 4 for other lentils))","4 cups / 1 litre water","1/2 tsp turmeric powder","1/8 tsp garam marsala","3/4 tsp salt"],"purpose":"Dal"},{"ingredients":["1 1/2 tbsp / 20g ghee (, or half each butter + oil (Note 1))","1 eschalot or 1/4 small onion (, halved lengthways and sliced (Note 5))","1 tsp cumin seeds","1/2 tsp black mustard seeds (optional)","3 dried chillies (, broken in half, seeds removed (optional))"],"purpose":"Tadka (optional):"},{"ingredients":["Fresh coriander/cilantro sprigs (optional)","Steamed basmati rice"],"purpose":"To serve"}]', '[{"title":"Soak Lentils","description":"Rinse lentils and leave to soak in plenty of water for 1 hour. Drain in colander.","images":[],"step":1},{"description":"Heat ghee/oil in a heavy based saucepan over high heat. Add green chillies and fry for a minute until starting to blister.","images":[],"step":2},{"description":"Add onions and fry until softened.","images":[],"step":3},{"description":"Lower heat to medium, add garlic, ginger and curry leaves. Cook for 1 minute until garlic starts to turn golden and smells amazing.","duration":1,"images":[],"step":4},{"description":"Add tomatoes and cumin, cook until tomatoes start to break down and thicken to a paste - about 2 minutes.","images":[],"step":5},{"description":"Add lentils, water, tumeric and salt. Stir, bring to simmer, cover and simmer gently for 1 hour. Stir two or three times during the hour.","images":[],"step":6},{"description":"Remove lid and simmer gently for 30 minutes to thicken, stirring every now and then. The dal is ready when it has a consistency like porridge - some lentils should be intact but some have broken down to thicken the sauce.","duration":30,"images":[],"step":7},{"description":"Stir through garam masala at the end. Adjust salt if desired.","images":[],"step":8},{"description":"Pour over Tadka, if using, and stir through.","images":[],"step":9},{"description":"Serve Dal over rice, garnished with a sprig of coriander if desired.","images":[],"step":10},{"title":"Tadka","description":"Sizzling Spices (optional)","images":[],"step":11},{"description":"Heat ghee in a small pan over medium heat until hot but not smoking.","images":[],"step":12},{"description":"Add cumin and mustard seeds, stir until cumin is slightly golden.","images":[],"step":13},{"description":"Then add chillies and cook for 20 seconds, then add eschallots and cook until tinged with gold. Don''t let the spices burn!","duration":0.3333333333333333,"images":[],"step":14},{"description":"Immediately pour into Dahl.","images":[],"step":15}]', '["milk","mustard"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Indian"],"categories":["curry-recipes","iconic-dishes","indian-recipes","main-dishes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c07e19c1c759', 'en', 'US', 'Vegetable Curry', 'This packs a serious flavour punch and is loaded with vegetables! I used plenty of variety, but feel free to use less. Just substitute based on volume rather than weight (because vegetable weight/density differs), and adjust the chilli and cayenne pepper to control spiciness, as well as using either mild or hot curry powder.', 'https://www.recipetineats.com/tachyon/2017/07/Vegetable-Curry.jpg', 15, 25, 40, 5, '[{"id": "ing_curry_powder", "quantity": {"value": 0.6, "unit": "jar of 50g"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_nutmeg_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_garlic", "quantity": {"value": 666.667, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_zucchini", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_sweet_potato", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_cauliflower", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_frozen_peas", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_baby_spinach", "quantity": {"value": 2.0, "unit": "bag of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_white_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2 tbsp curry powder (, mild or hot (Note 1))","1 tsp All Spice powder","1 tsp nutmeg powder (or 1/2 tsp freshly grated nutmeg)","1 1/2 tsp smoked paprika (sub with sweet or ordinary paprika)","2 tsp dried thyme leaves (or 3 tsp fresh thyme leaves)","1 tsp cumin powder","3/4 tsp cayenne pepper (adjust to taste)","1 tsp pepper (white or black)"],"purpose":"Spice Mix:"},{"ingredients":["3 tbsp cooking oil","1 large onion (, diced (brown, white, yellow))","1 large red chilli / cayenne pepper (, deseeded and finely sliced)","2 large garlic cloves (, minced)","1 large red capsicum / bell pepper * (, chopped into 1.7cm / 2/3\" pieces (~1.5 cups))","800g/ 28 oz canned crushed tomato","2 cups (500 ml) vegetable or chicken broth","1 zucchini (, diced (~1 cup) *)","2 cups sweet potato * (, 1.5cm / 3/5\" cubes (~225g/7.5oz))","2 cups cauliflower florets * (, small / medium (~180g/6oz))","3/4 cup frozen peas *","2 handfuls baby spinach (, optional (Note 2))","1/2 cup finely chopped coriander/cilantro ((leaves and stems), plus more for garnish)","Salt and pepper","Yoghurt (plain or Greek)"],"purpose":"Curry:"},{"ingredients":["Basmati rice","White rice"],"purpose":"Serving – choose:"}]', '[{"description":"Heat oil in a large pot over medium high heat. Add garlic and onion, cook for 2 minutes. Add cayenne and cook until onion is translucent.","duration":2,"images":[],"step":1},{"description":"Add Spice Mix and cook, stirring constantly, for 1 - 2 minutes until the spice is fragrant and wet. If too dry, add a tiny touch of water or oil.","duration":1.5,"images":[],"step":2},{"description":"Add capsicum and zucchini, cook for 1 minute.","duration":1,"images":[],"step":3},{"description":"Add tomato, broth, potato and cauliflower. Mix well, bring to simmer, cover, lower heat to medium.","images":[],"step":4},{"description":"Simmer for 15 minutes or until potato is pretty soft, then remove lid and simmer for another 10 minutes+ until sauce is slightly thickened and potato is soft.","duration":15,"images":[],"step":5},{"description":"Add peas, stir, cook for 2 minutes. Add coriander and spinach, stir until wilted.","duration":2,"images":[],"step":6},{"description":"Season to taste until salt and pepper. Serve over basmati rice or plain white rice. Garnish with yoghurt and more coriander.","images":[],"step":7}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Caribbean"],"categories":["curry-recipes","dietary","dinner-tonight","gluten-free-recipes","indian-recipes","main-dishes","quick-and-easy","vegan-lifestyle","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_73639cd3c056', 'en', 'US', 'Almond Lace Tuiles', 'Recipe video above. These caramelised, wafer-thin Lace Almond Tuiles are a simple French snack or dessert that always makes an impression. As the name suggests, these biscuits look just like a piece of delicate lace, only even better as they’re edible! Eat them plain, fill them with cream and berries, or use as a topper for ice cream or a plated dessert for an instant restaurant touch.', 'https://www.recipetineats.com/tachyon/2026/05/Lace-Tuilles-3.jpg', 10, 30, 160, 14, '[{"id": "ing_sugar", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_oranges", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_almonds", "quantity": {"value": 0.45, "unit": "pack of 250g"}}]', '[{"ingredients":["2/3 cup caster sugar (superfine sugar)","1/4 cup plain flour (all-purpose flour)","50g / 3 1/2 tbsp unsalted butter (, melted)","3 tbsp orange juice (Note: I use 15 ml tablespoons. Some tablespoon measures in Australia are 20 ml)","3/4 cup almond flakes (, or slivered almonds)"]}]', '[{"description":"Mix flour and sugar, mix in butter and orange juice, then almonds. Refrigerate 2 hours. Dollop 4 x 1 tbsp mounds on a tray (do 2 trays). Bake 5 min, spread melted tuiles into 10cm/4\" circles, bake 13-15 min until deep golden. Cool 1 - 1 1/2 min, lift and shape on rolling pins, will crisp as they cool.","images":[],"step":1},{"title":"Mix dry","description":"In a bowl, combine the caster sugar and plain flour using a wooden spoon or a spatula.","images":[],"step":2},{"title":"Add wet","description":"Pour in the melted butter and orange juice. Mix until combined.","images":[],"step":3},{"title":"Add almonds","description":"Gently fold in the almond flakes. The batter is quite loose, it is not a stiff cookie dough.","images":[],"step":4},{"description":"Refrigerate for 2 hours. This firms up the batter to make it scoop-able.","images":[],"step":5},{"description":"Preheat the oven to 170°C / 340°F (150°C fan-forced). Line 2 baking trays with baking paper / parchment paper.","images":[],"step":6},{"title":"Mounds","description":"Scoop a tablespoon of mixture out of the bowl and use a teaspoon to scoop it out onto the tray. Do 4 mounds on each tray, leaving about 10cm / 4” between each mound.","images":[],"step":7},{"title":"First bake","description":"Bake for 5 minutes. The mounds will have melted (mostly or fully). Remove the trays and, using a fork, gently press and spread each into a 10cm/4\" circle - do your best, they don''t have to be perfect circles. Don''t worry if you have holes, they will close up as the batter melts in the 2nd bake. This step is what makes the tuiles so thin they end up with the signature see-through lace pattern.","duration":5,"images":[],"step":8},{"title":"Second bake","description":"Return to the oven and bake for another 13 to 15 minutes until they are deep golden brown, not just a light golden. The bottom tray may need an extra 1 to 2 minutes.","images":[],"step":9},{"title":"Prepare shaping station","description":"Place 2 rolling pins over folded tea towels so they stay stable. (Note 1)","images":[],"step":10},{"title":"Cool 1 minute","description":"Remove trays from the oven. Let the tuiles cool on the tray for 1 to 1 1/2 minutes so they slightly firm up enough to be able to lift them with a spatula without breaking. (Note 2) If the tuiles have melted into each other, separate them during this time - just use a butter knife.","images":[],"step":11},{"title":"Shaping","description":"The video is helpful here (at 1.05 minutes ). Working quickly, gently lift them using an offset spatula or regular spatula and place them over the rolling pins to create their signature curved shape. If the tuiles set too much to be shaped, pop them back into the oven for a minute or two, until they become pliable again.","images":[],"step":12},{"title":"Cool to crisp","description":"Leave to fully cool and crisp (about 5 minutes) then transfer onto a cooling rack to fully cool. (Note 3)","images":[],"step":13},{"description":"Repeat the same process with the remaining tuile mixture.","images":[],"step":14},{"description":"Serve with desserts, ice cream, coffee or simply enjoy as a crisp sweet snack. They are also lovely filled with whipped cream and berries, as pictured in the post.","images":[],"step":15}]', '["gluten","milk","nuts"]', '["keto_friendly","low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["French"],"categories":["dessert","dessert-recipes","jbs-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9f7390e13499', 'en', 'US', 'Lemongrass Chicken Rice Paper Rolls', 'Recipe video above. You can make chicken rice paper rolls using plain shredded chicken. But they''re so much more exciting with caramelised little bits of lemongrass marinated chicken! This is one of those recipes I pitch as "light-and-fresh-but-not-boring", not that we would expect anything less from the Vietnamese. The fresh mint in this really makes it, so don''t skimp on it! But the thing everybody goes mad for is the peanut sauce. Always!Feel free to switch the vegetables - see Ingredients section in post for lots of other options. For a peanut-free sauce alternative, use sweet chilli sauce with a dash of lime or sriracha.Next time - try the Prawn Rice Paper Rolls!', 'https://www.recipetineats.com/tachyon/2025/09/Lemongrass-chicken-rice-paper-rolls_3.jpg', 25, 6, 46, 10, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_lemongrass", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_rice", "quantity": {"value": 15.0, "unit": "pack"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.14, "unit": "pack of 500g"}}, {"id": "ing_cabbage", "quantity": {"value": 3.0, "unit": "head"}}, {"id": "ing_red_cabbage", "quantity": {"value": 3.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_mint", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.06, "unit": "jar of 375g"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.025, "unit": "pack of 100g"}}]', '[{"ingredients":["350g / 12oz boneless chicken thighs (, very finely sliced (2.5cm/1\" wide, 3mm / 1/8\" thick(Note 1))","1 1/2 tbsp fish sauce (substitute light or all-purpose soy sauce)","2 tbsp brown sugar","1 tbsp lemongrass (, finely grated (or paste) (Note 2))","1 tbsp lime juice (substitute rice vinegar or apple cider vinegar)","1 garlic clove (, finely grated)"],"purpose":"Lemongrass marinated chicken"},{"ingredients":["1 tbsp canola oil (or other neutral oil, for cooking)"],"purpose":"Cooking chicken"},{"ingredients":["10 sheets round rice paper (, ~22cm/8.5\" (Note 3))","70g / 2.5 oz dried vermicelli noodles ((rice noodles), or other very thin noodles)","1 cup (packed) green cabbage (, very finely sliced (so it''s soft and floppy not stiff and pokey) - or any lettuce)","1 cup (packed) red cabbage (, very finely sliced (or any lettuce))","1 carrot (, peeled and finely julienned (or cucumber))","1/4 cup coriander / cilantro leaves (roughly chopped (or Thai Basil leaves, extra mint leaves))","3/4 cup small mint leaves ((or tear larger ones), regular, or Vietnamese mint)"],"purpose":"Rice paper rolls"},{"ingredients":["1 1/2 tbsp natural peanut butter (, smooth (Substitute regular peanut butter spread, Note 4))","2 tbsp hoisin sauce","1 tbsp white vinegar (or 1/2 tbsp lime juice)","1/4 - 1/3 cup milk ( (any fat %) (or water))","1 small garlic clove (, finely grated)","2 tsp brown sugar","1/8 tsp cooking salt / kosher salt","1/2 tsp crushed chilli, samba oelak or other chilli paste (, adjust spiciness to taste (optional))"],"purpose":"Vietnamese Peanut Dipping Sauce"}]', '[{"title":"Marinate chicken","description":"Mix the Marinade ingredients in a bowl. Add chicken and toss to coat. Set aside to marinate for 15 minutes while you prepare everything else (or overnight).","duration":15,"images":[],"step":1},{"title":"Peanut Sauce","description":"Mix ingredients together in a small bowl until combined, using milk to adjust the consistency if needed so it''s not too thick.","images":[],"step":2},{"title":"Noodles","description":"Place vermicelli noodles in a bowl and cover with hot water for 2 minutes, then drain very well and let cool. (Or follow packet instructions, if different).","duration":2,"images":[],"step":3},{"title":"Cook chicken","description":"Heat the oil in a large non-stick pan over high heat until very hot. Add half the chicken (leave residual marinade in bowl) and cook for 3 minutes, stirring constantly, until lightly caramelised. Remove from the pan and spread out on a plate to cool before using. Repeat with remaining chicken. (Note: I don''t cook in 2 batches in the video because the stove is super strong).","duration":3,"images":[],"step":4},{"title":"Water bowl","description":"Fill a large bowl with warm water. (The bowl doesn''t need to be large enough to fit the whole rice paper in one go.)","images":[],"step":5},{"description":"Submerge rice paper in the water for 2 seconds (if your bowl isn''t large enough to fit the whole rice paper in one go, that''s fine, just rotate it and count 2 seconds for each section you submerge into the water), place the smooth side down on a cutting board. (Note 3)","duration":0.03333333333333333,"images":[],"step":6},{"title":"Stuffing","description":"Place stuffing just beneath the middle, in whatever order you want (it doesn''t really matter), but try to pile in a symmetrical stack (for ease of rolling / neat rolls). My typical: sprinkle ~2 tsp coriander, top with one-tenth of the chicken, then carrots, cabbages, mint leaves (generous), and noodles last to weigh everything down (I wrap around hand to bundle into a neat shape).","images":[],"step":7},{"title":"Roll (Note 5)","description":"Fold the lower part of the rice paper up over the stuffing, then fold the sides in. Roll to enclose the filling, making it fairly firm. It will self-stick to seal (yay!). Don''t worry if it''s a bit wonky, it will still taste fabulous!","images":[],"step":8},{"title":"Serve","description":"Transfer to serving plate (ignore what I do in the video - don''t stack! They stick.) Serve with peanut dipping sauce. Sometimes I cut in half and stand upright, per photos in the post (great for appetisers!).","images":[],"step":9}]', '["fish","gluten","milk","peanuts","soy"]', '["low_calorie"]', '{"mealType":["snack"],"cuisine":["Vietnamese"],"categories":["dietary","gluten-free-recipes","low-calorie-recipes","summer","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9f629f547dae', 'en', 'US', 'Country harvest root vegetable soup', 'Recipe video above. I don''t harvest and I don''t live in the country. I just didn''t think "Root Vegetable Soup" did this recipe justice - so I got creative to get your attention!😅 Root veg are great for naturally creamy soups thanks to the higher starch content, though we give this a luxe boost with a scant 1/2 cup of cream. Nourishing, never boring, and flexible too - in case your harvest basket is missing items! Love that it''s made with water not stock - curry powder adds a flavour boost so it doesn''t taste flat. Bonus - LOW CAL!', 'https://www.recipetineats.com/tachyon/2025/05/Creamy-root-vegetable-soup_1.jpg', 20, 30, 50, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.3, "unit": "jar of 50g"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_water", "quantity": {"value": 1.5, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_sweet_potato", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_medium_parsnip_cut_into_1_5cm_0_5_pieces", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_celeriac_cut_into_1_5cm_0_5_pieces", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.3, "unit": "jar of 50g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["2 tbsp extra virgin olive oil","1 tbsp (15g) unsalted butter","1 onion (, chopped into large dice)","3 garlic cloves (, chopped)","1 tbsp curry powder (I like Clive, but any will do, Note 1)","1 tsp dried thyme leaves (Note 2)","1 1/2 litre (6 cups) water","2 tsp cooking salt/kosher salt (halve for table salt)","1/2 tsp black pepper","1/2 cup thickened cream (heavy cream, or regular), plus extra for garnish (Note 3)"]},{"ingredients":["1 large potato ((~300g/10oz), peeled, cut into 2.5cm/1\" cubes)","1 medium sweet potato ((350g/12oz), peeled, cut into 2.5cm/1\" cubes)","2 medium carrots (, peeled, cut into 1.5cm/0.5\" pieces)","1 small/medium parsnip ((150g/5oz), peeled, cut into 1.5cm/0.5\" pieces)","1 small celeriac (600g/1.2 lb), peeled, cut into 1.5cm/0.5\" pieces (~2 heaped cups)"],"purpose":"Root vegetables (Note 4):"},{"ingredients":["Warm crusty bread","Parsley (, finely chopped)","Pinch extra curry powder","Pinch black pepper"],"purpose":"Serving/garnish (optional):"}]', '[{"title":"Sauté","description":"Put the olive oil and butter in a large heavy-based pot over medium-high heat. Once the butter is melted, cook the onion and garlic for 2 minutes until the onion is softened.","duration":2,"images":[],"step":1},{"description":"Add root vegetables, thyme and curry powder. Cook for three minutes stirring regularly, until the outside of the vegetables starts to soften.","images":[],"step":2},{"title":"Simmer 15 minutes","description":"Turn stove up to high. Add water, salt and pepper. Stir, then once it comes to a simmer, lower heat to medium high and simmer rapidly for 15 minutes (no lid) until all the vegetables are soft (check with knife).","duration":15,"images":[],"step":3},{"description":"Stir in cream, simmer for 1 minute.","duration":1,"images":[],"step":4},{"title":"Blitz","description":"Remove from heat and use a stick blender to blitz until smooth. (Note 5 for blender) Adjust to taste - water to thin, salt and pepper if needed, extra cream for more indulgent.","images":[],"step":5},{"description":"Serve in bowls. Drizzle with cream, pinch of curry powder, parsley and pepper. Serve with warm crusty bread!","images":[],"step":6}]', '["gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dinner","snack"],"cuisine":["Western"],"categories":["dietary","gluten-free-recipes","low-calorie-recipes","soup-recipes","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2c559c7f6dc4', 'en', 'US', 'Puttanesca Fish Tray Bake', 'Recipe video above. Baked fish dinners can be so dull. Not this one! Think - spaghetti puttanesca flavours in the form of a one pan fish dinner. It''s a Puttanesca fish tray bake! Good for you, easy to make, fabulously delicious.Note: If you only have fine table salt, halve the salt quantities else it will be too salty.', 'https://www.recipetineats.com/tachyon/2025/05/Puttanesca-fish-tray-bake-shoot-1_3.jpg', 15, 45, 60, 4, '[{"id": "ing_potato", "quantity": {"value": 600.0, "unit": "bag of 2kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_fennel", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_pitted_kalamata_olives", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_baby_capers", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_organo", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_basil", "quantity": {"value": 20.0, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["600g/1.2 lb baby potatoes (, smaller ones up to 3.5cm/1.5\" halved, larger ones quartered (Note 1))","1 1/2 tbsp extra virgin olive oil","1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper"],"purpose":"Roasted potatoes:"},{"ingredients":["1 medium fennel (, fronds reserved for garnish, halved, cut into 0.5cm / 0.2\" half moon shapes (Note 2))","1 1/2 cups (200g) cherry or grape tomatoes (1 punnet)","1/2 cup pitted kalamata olives","3 garlic cloves (, finely minced (can use garlic crusher))","3 tbsp baby capers (or regular, roughly chopped)","3 anchovy fillets (, finely minced - can reduce to 1 (Note 3))","400g/ 14oz canned tomato (, crushed or diced)","1/2 tsp chilli flakes ((red pepper flakes), mild spiciness, can reduce or omit)","1 tsp dried organo","1/4 tsp cooking salt / kosher salt","1/4 tsp black pepper"],"purpose":"Puttanesca sauce:"},{"ingredients":["4 x 160 - 180g / 6oz barramundi fillets (, skinless, or other firm fish fillets about 2.5/3cm/1\" thick (Note 4))","1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper","1 1/2 tbsp extra virgin olive oil"],"purpose":"Fish:"},{"ingredients":["1 loosely packed cup basil leaves (, roughly chopped (recommended but can live without or sub with 2 tbsp roughly chopped parsley))","Warm crusty bread (, for mopping)"],"purpose":"Finishing / serving:"}]', '[{"description":"Preheat oven to 220°C/390°F (200°C fan-forced).","images":[],"step":1},{"title":"Roast potatoes","description":"In a large mixing bowl, toss the potatoes with the oil, salt and pepper. Spread on a baking tray with a rim at least 2cm/0.8\" high (or 23x33cm / 9x13\" pan). Roast for 20 minutes.","duration":20,"images":[],"step":2},{"title":"Puttanesca sauce","description":"Meanwhile, mix all the sauce ingredients together (use the potato bowl, no need to clean). Add to the tray, toss with the potatoes, return to the oven for 10 minutes.","duration":10,"images":[],"step":3},{"title":"Season fish","description":"Pat the fish dry with paper towels. Sprinkle each side with the salt and pepper.","images":[],"step":4},{"title":"Bake fish","description":"Place fish on top of puttanesca sauce. Drizzle all over with the 1 1/2 tablespoons of oil. Bake 15 minutes or until fish is just cooked through (it should flake easily).","images":[],"step":5},{"title":"Serve","description":"Remove from the oven. Drizzle with a bit more olive oil, scatter with basil and reserved fennel fronds. Serve with warm, crusty bread!","images":[],"step":6}]', '["fish","gluten"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","fish-recipes","gluten-free-recipes","mains","one-pot-recipes","other","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d1115e64f3d8', 'en', 'US', 'Vietnamese Peanut Sauce Lettuce Wraps', 'Recipe video above. Such a great DIY summer spread, a regular all through summer in my circles! It''s essentially a lower-cal version of Vietnamese rice paper rolls. The fresh herbs and the peanut sauce are key here! Everything else you can switch: prawns for shredded chicken, pan fried salmon or other fish (flake into big chunks) or even tofu (I pan fry batons). Use whatever shreddable veg you want. Emergency version: store bought roast chicken (shredded) + packet shredded coleslaw veg + peanut sauce + noodles. SO GOOD.', 'https://www.recipetineats.com/tachyon/2024/01/Vietnamese-lettuce-wraps-with-peanut-sauce_8.jpg', 20, 0, 20, 4, '[{"id": "ing_shrimp", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.15, "unit": "pack of 500g"}}, {"id": "ing_lettuce", "quantity": {"value": 240.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_beansprouts", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_mint", "quantity": {"value": 1.2, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 1.2, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 3.0, "unit": "pack of 100g"}}, {"id": "ing_roasted_peanuts", "quantity": {"value": 37.5, "unit": "jar"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.08, "unit": "jar of 375g"}}, {"id": "ing_hoisin", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.208, "unit": "can of 400ml"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_sambal_oelak_can_omit", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_dark_soy", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_radishes", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_vinegar", "quantity": {"value": 1.0, "unit": "L"}}]', '[{"ingredients":["300g / 10 oz peeled whole cooked prawns/shrimp (, medium (600g/1.2lb unpeeled whole prawns - this is what I use) - Note 1)","75g / 2.5 oz dried vermicelli noodles (or glass noodles or rice)","12 large or 16 -20 small lettuce leaves ((I used baby cos/romaine), eg iceberg, butter lettuce)"],"purpose":"The lettuce cups:"},{"ingredients":["1 batch quick pickled carrots and daikon (, below *recommended* OR 2 carrots finely julienned (use plain))","2 cups beansprouts","2 cucumbers (, julienned)","2 cups mint leaves","2 cups coriander/cilantro sprigs (sub with chives + extra mint)","3 birds eye red chilli (, finely sliced (optional))","1/4 cup roasted peanuts (, finely chopped (recommended))"],"purpose":"Veg and herbs:"},{"ingredients":["2 tbsp natural peanut butter (, smooth (ie not sweetened) - Note 2)","2 tbsp hoisin","1 - 2 tbsp lime juice (, sub rice vinegar)","1/3 cup LOW FAT coconut milk (Note 3)","1 large garlic clove (, finely grated)","1 tsp+ sambal oelak (or other chilli sauce/paste of choice), can omit (adj to taste)","1 tsp dark soy (Note 4)","1 tsp white sugar","1/2 tsp cooking salt / kosher salt"],"purpose":"Vietnamese Peanut Sauce:"},{"ingredients":["2 medium carrots (, peeled cut into 2 mm / 1/10″ batons)","1/2 large white radish (daikon) (, peeled, cut the same as carrots)","1 1/2 cups boiling water","1/2 cup white sugar","4 tsp cooking salt / kosher salt","3/4 cup rice wine vinegar (sub apple cider vinegar)"],"purpose":"Quick pickled vegetables"}]', '[{"title":"Pickle first","description":"Put the boiling water, salt and sugar in a bowl. Mix to to dissolve, then add vinegar. Submerge vegetables and leave for 2 hours. Drain then use per recipe (or store in fridge submerged in liquid).","images":[],"step":1},{"title":"Peanut sauce","description":"Mix the peanut sauce ingredients and set aside for the flavours to meld while you prepare the platter. Start with 1 tbsp lime juice and add more if you want tarter.","images":[],"step":2},{"title":"Prawns (shrimp)","description":"Cut the prawns in half horizontally and remove the vein.","images":[],"step":3},{"title":"Noodles","description":"Soak the noodles in boiling water per packet directions. Rinse under cold water (to prevent stickiness) then drain very well.","images":[],"step":4},{"title":"Lay it all out","description":"Pile everything onto a giant platter or put things in little bowls, then let everybody help themselves!","images":[],"step":5},{"title":"Assemble","description":"Here''s my order: lettuce leaf, noodles first, then veg* (carrots, bean sprouts etc), prawns, stuff herbs down the side, drizzle with sauce, sprinkle with peanuts and chilli. Bundle and bite!","images":[],"step":6}]', '["milk","peanuts","shellfish","soy"]', '["gluten_free","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Vietnamese"],"categories":["dietary","gluten-free-recipes","low-calorie-recipes","no-cook-food","prawns-shrimp","summer","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_880b53615e1c', 'en', 'US', 'Almost no-oil Pan Fried Eggplant', 'Recipe video above. This is a recipe for how to cook eggplant on the stove with virtually no oil - less than 1/2 teaspoon for a whole eggplant! I use a highly effective, simple pan-steaming method used for Asian dumplings like gyoza! Eat it as is, or see in post for a list of toppings and sauces to serve with this pan fried eggplant. Which one is your favourite??', 'https://www.recipetineats.com/tachyon/2023/10/Pan-fried-eggplant-with-little-oil_3.jpg', 3, 10, 13, 2, '[{"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_see_in_post_for_ideas_and_links_to_recipes_for_sauces_etc", "quantity": {"value": 1.0, "unit": "bottle"}}]', '[{"ingredients":["1 large eggplant (aubergine), around 20cm/8” (~400g/14 oz) (Note 1)","Olive oil spray (or other oil spray) (Note 2)","1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper","1/4 cup water"]},{"ingredients":["See in post for ideas and links to recipes for sauces etc!"],"purpose":"Sauces and toppings for serving:"}]', '[{"description":"Cut the eggplant into 2cm / 0.8” rounds.","images":[],"step":1},{"description":"Spray each side generously with oil and sprinkle with salt and pepper.","images":[],"step":2},{"title":"Brown","description":"Heat a large non-stick pan with a lid over medium high heat, no oil. (Note 3) Add the eggplant slices and pan fry for 1 1/2 to 2 minutes on each side or until you get some nice browning on it. As much or as little as you want!","images":[],"step":3},{"title":"Pan steam","description":"Carefully add water around the eggplant (it will bubble and steam, so do this carefully). Then immediately cover with a lid to trap the steam in. Steam for 2 minutes or until the water has evaporated.","duration":2,"images":[],"step":4},{"title":"Check","description":"Use a butter knife to check to ensure the eggplant is cooked through. If not, add a bit more water and steam again!","images":[],"step":5},{"title":"Serve","description":"Transfer to a serving plate and serve! Great as is, or to dress it up a tiny bit, add a swish of olive oil, squeeze of lemon juice and parsley leaves, or a smear of chilli crisp! See in post for more ways to serve.","images":[],"step":6}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","eggplant","how-to","low-calorie-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0a730f9c9eb6', 'en', 'US', 'The Sweet Potato Soup', 'Recipe video above. A healthy dose of cumin plus a good amount of onion and leek keeps things interesting with this Sweet Potato Soup! If leeks are a bit pricey, use more onion instead. Serve with a shower of something crunchy - croutons, nuts, crispy shallots. I used pistachios and flatbread ribbons, fried for speed, but they can be baked - Note 3.', 'https://www.recipetineats.com/tachyon/2023/04/Sweet-Potato-Soup_0.jpg', 10, 30, 40, 6, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_eek", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_sweet_potato", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_cumin", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 1.25, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_cream", "quantity": {"value": 0.333, "unit": "carton of 250ml"}}, {"id": "ing_something_to_drizzle_dollop", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["2 tbsp extra virgin olive oil","30g / 2 tbsp unsalted butter ( - or more oil)","2 onions (, diced)","2 leeks (, white and pale green part only, quartered, cut into 1cm / 1/2\" slices (Note 1))","2 garlic cloves (, chopped)","1 kg/ 2 lb sweet potato (, peeled, quartered lengthwise, cut into 2cm / 0.8\" chunks)","1 tbsp cumin powder","1.25 litre / 1.25 quarts chicken or vegetable stock (, low sodium (Note 2))","1.5 tsp cooking / kosher salt","1 tsp black pepper","1/3 cup cream ((any type) or an extra knob of butter)"]},{"ingredients":["Something to drizzle / dollop (- extra virgin olive oil, cream, yogurt, sour cream)","Something crunchy - flatbread strips ((pictured, Note 3), croutons, pistachios, pepitas, crispy fried shallots)"],"purpose":"Garnishes (Note 3)"}]', '[{"title":"Sauté aromatics","description":"Heat the oil and melt the butter in a large heavy based pot over medium heat. Cook the onion, leek and garlic for 5 minutes until softened.","duration":5,"images":[],"step":1},{"description":"Add the sweet potato and cumin, cook for another 3 minutes, stirring regularly.","images":[],"step":2},{"title":"Simmer 20 minutes","description":"Add the stock, salt and pepper. Bring to a simmer, then cook for 20 minutes at a gentle simmer until the sweet potato is very tender (no lid).","duration":20,"images":[],"step":3},{"title":"Blitz","description":"Remove the pot from the stove. Blitz with a hand-held stick until smooth. (Note 4 for blender) Stir in cream.","images":[],"step":4},{"title":"Garnish","description":"Ladle into bowls. Drizzle with yogurt, cream or olive oil with a sprinkle of something crunchy - pictured with pistachios and crispy flatbread strips (Note 3).","images":[],"step":5}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["dietary","low-calorie-recipes","quick-and-easy","soup-recipes","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d103e1d2cd8e', 'en', 'US', 'Roast Lamb Leg with Gravy', 'Recipe video above. I love a roast lamb leg! My top tip is to use a meat thermometer. There''s no way to guarantee perfect blushing pink roast lamb without one, even if it''s a cheap one!Rubbed with rosemary garlic and accompanied with a killer gravy for lamb. Serve with peas, buttered steamed carrots and crunchy roast potatoes (either classic or ultra crunchy duck fat potatoes).', 'https://www.recipetineats.com/tachyon/2016/10/Roast-lamb-leg_2.jpg', 5, 100, 15, 6, '[{"id": "ing_lamb", "quantity": {"value": 2.75, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_rosemary", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_rosemary", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.375, "unit": "kg"}}]', '[{"ingredients":["2.75 - 3 kg / 5.5 - 6 lb lamb leg (, bone-in (Note 1))","1 1/2 tsp cooking salt","1/2 tsp black pepper"]},{"ingredients":["1 1/2 tbsp fresh rosemary leaves (, finely chopped)","3 garlic cloves (, finely minced)","2 tbsp olive oil"],"purpose":"Rub"},{"ingredients":["2 whole heads of garlic (, halved horizontally (Note 2))","Few sprigs rosemary (optional)"],"purpose":"Base"},{"ingredients":["4 tbsp flour (, plain/all purpose)","2 1/2 cups beef broth / stock (, low sodium (Note 3))"],"purpose":"Gravy"}]', '[{"description":"Take lamb out of fridge at least 1 hour before roasting. (Note 4)","images":[],"step":1},{"description":"Preheat oven to 240°C/475°F (220°C fan) with oven shelf in the middle.","images":[],"step":2},{"title":"Rub","description":"Mix rosemary, garlic and olive oil.","images":[],"step":3},{"title":"Prepare lamb","description":"Place lamb leg in a roasting pan. Coat with the rub using your hands, the sprinkle with the salt and pepper. Place garlic and rosemary sprigs underneath the lamb, garlic cut face up.","images":[],"step":4},{"description":"Roast lamb leg for 20 minutes. Turn the oven down to 200°C/400°F (180°C fan) and roast for a further 1 hour or until the internal temperature reaches 53°C/127°F for medium rare (Note 5 other doneness). Check first at 45 minutes - everyone''s oven is different!","duration":20,"images":[],"step":5},{"title":"Rest","description":"Remove lamb from oven. Transfer lamb to plate, loosely cover with foil and rest for 20 minutes to 1 hour (it will still be warm enough for serving!). The internal temperature will rise to 62°C/144°F (medium rare). Make gravy while lamb is resting - below.","duration":20,"images":[],"step":6},{"description":"Serve lamb with gravy, duck fat or classic crunchy roast potatoes, peas and steamed carrots tossed with butter and parsley.","images":[],"step":7},{"description":"Gravy for roast lamb leg","images":[],"step":8},{"title":"Drippings in pan","description":"Discard rosemary sprigs. You should have around 4 - 5 tbsp of fat (drippings). If less, add butter. If much more, discard a bit.","images":[],"step":9},{"title":"Add flour","description":"Place roasting pan on stove over medium heat. When the fat starts to bubble, then add flour. Mix flour in and cook for 1 minute.","duration":1,"images":[],"step":10},{"title":"Stock","description":"Pour in half the beef stock and mix to dissolve sludge in, then add remaining beef stock and mix.","images":[],"step":11},{"title":"Garlic squidging","description":"Use a potato masher (if you''re really keen like me) to mush the garlic to squeeze out the flavour (also helps flour caught in garlic to dissolve).","images":[],"step":12},{"title":"Taste","description":"Check salt and pepper (I don''t add more).","images":[],"step":13},{"title":"Thicken","description":"Simmer for a couple of minutes, stirring, until it starts to thicken. Take it off the stove BEFORE the gravy is the thickness you want because it will keep thickening.","images":[],"step":14},{"description":"Strain into a bowl, mushing garlic to squeeze all the liquid out. Then pour into gravy jug and serve with lamb!","images":[],"step":15}]', '["gluten"]', '["high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Aussie","British","New Zealand"],"categories":["dietary","easter-mains","easter-recipes","gluten-free-recipes","lamb-recipes","main-dishes","most-popular","roast-lamb","roasts","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d2f5f45f8545', 'en', 'US', 'Chewy muesli bars (granola bars)', 'Recipe video above. These are chewy, no-bake muesli bars that will keep for 2 weeks. Cheaper, tastier and much healthier than store-bought, it''s also an excellent way to clear out random leftover nuts and dried fruit. Just stick to the recipe ratio of "glue" to add-ins (3 1/2 cups total). My combination is a dead-ringer for Australia''s popular Carmen''s Classic Fruit & Nut Muesli Bars (which cost $6.50 for 6!).After crunchy muesli bars? Here they are!', 'https://www.recipetineats.com/tachyon/2023/02/Muesli-bars_5.jpg', 15, 5, 20, 10, '[{"id": "ing_peanut_butter", "quantity": {"value": 0.2, "unit": "jar of 375g"}}, {"id": "ing_honey", "quantity": {"value": 0.25, "unit": "jar of 500g"}}, {"id": "ing_rolled_oats", "quantity": {"value": 0.45, "unit": "pack of 500g"}}, {"id": "ing_sultanas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_desiccated_coconut", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_almonds", "quantity": {"value": 0.3, "unit": "pack of 250g"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.3, "unit": "pack of 100g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_cinnamon", "quantity": {"value": 2.5, "unit": "jar"}}]', '[{"ingredients":["1/2 cup (120g) pure natural peanut butter, smooth, or other nut butter (mix oil in well, Note 1)","1/2 cup (175 g) honey (Note 2)"]},{"ingredients":["1 1/2 cups rolled oats","1 cup sultanas","1/4 cup desiccated coconut (, unsweetened)","1/2 cup almonds (, very roughly chopped)","1/4 cup pepitas","2 tbsp white sesame seeds","1/8 tsp salt","1/2 tsp cinnamon"],"purpose":"Add ins (3 1/2 cups your choice, Note 3):"}]', '[{"title":"Mix Add-ins","description":"Using a wooden spoon, mix the add-ins in a large microwaveable bowl (just in case, Note 4).","images":[],"step":1},{"title":"Glue","description":"Using a rubber spatula, mix the peanut butter and honey in a saucepan over medium heat until smooth. Once combined, turn the stove down to low. As soon as you start seeing little bubbles around the edges, cook for 5 minutes, stirring constantly scraping the base, until it is like a very thick caramel (see photos and video in post). You should be able to draw a path across the base and it holds before closing in on itself. DO NOT WALK AWAY, it will catch easily. (Note 5)","duration":5,"images":[],"step":2},{"title":"Mix","description":"Immediately pour it all over surface of the oats etc then mix with the wooden spoon. It takes a bit of effort but it does come together eventually. Stabbing and smearing against the wall of the bowl helps. If it gets too thick, microwave for 20 seconds on high to loosen the glue then mix (then it''s a breeze!).","duration":0.3333333333333333,"images":[],"step":3},{"title":"Press","description":"Put a square piece of paper over a 20cm/8\" square tin (no need to grease). Drop muesli mix in then spread right into the corners, using a combination of your hands and the wooden spoon. Firmer press = chewier muesli bars.","images":[],"step":4},{"title":"Set","description":"Refrigerate 2 hours until firm then cut into 10 bars (cut in half, then each half into 5).","images":[],"step":5}]', '["milk","peanuts","sesame"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["breakfast","snack"],"cuisine":["Australian","Western"],"categories":["dessert-recipes","dietary","gluten-free-recipes","snacks"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_681954c5523d', 'en', 'US', 'Gazpacho', 'Recipe video above. If the thought of this chilled Spanish soup conjures up visions of watery, bland, pureed vegetables, think again! Fabulous refreshing and full of flavour. Marinating isn''t traditional but does improve flavour. So it''s recommended, especially if you use economical vinegar or if your tomatoes aren''t farm-fresh-ripe-and-sweet (ie typical tomatoes from everyday grocery stores....)This version has no bread in it - it''s thick enough as is, I find. Serve with crusty bread on the side, for dunking. Fabulous meal for a hot summer day!Serves 3 hearty appetites, 4 normal appetites (with bread for dunking).', 'https://www.recipetineats.com/tachyon/2023/01/Gazpacho_2.jpg', 15, 0, 15, 3, '[{"id": "ing_tomato", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_cucumber", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 37.5, "unit": "pack of 1kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_vinegar", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["1 kg / 2 lb ripe tomatoes ((~7), cut into 8 wedges, core removed)","1 cucumber (20cm/8\" long) (, peeled and diced into 1cm / 1/2\" cubes)","1 red capsicum/bell pepper (, cut into 1.5 cm / 1/2\" cubes)","2 garlic cloves (, chopped)","1/4 cup red onion (, finely diced (Note 1))","1/4 cup extra virgin olive oil (, + extra for serving)","1 1/2 tbsp sherry vinegar (sub white wine or champagne vinegar)","3/4 tsp cooking/kosher salt","1/2 tsp black pepper"],"purpose":"Gazpacho:"},{"ingredients":["Crusty bread","Cucumber (, cut into small cubes (optional))"],"purpose":"Serving:"}]', '[{"title":"Marinate","description":"Toss all the gazpacho ingredients together in a large bowl. Cover then set aside to marinate, preferably 12 to 24 hours, or at least 3 hours. (Note 3)","images":[],"step":1},{"title":"Blitz","description":"Transfer everything into a blender and blitz on high until smooth. (Or use a tall jug with a hand blender). For 100% perfectly smooth, pass through a fine mesh strainer or food mill and discard solids (Note 2)","images":[],"step":2},{"title":"Serve","description":"Pour into a bowl. Rest for 15 minutes to let the bubbles subside. Stir, then ladle into bowls.","duration":15,"images":[],"step":3},{"title":"Garnish","description":"Top with diced cucumber, if using, and a swish of olive oil. Serve with crusty bread!","images":[],"step":4}]', '["gluten"]', '["low_calorie","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Spanish"],"categories":["dietary","low-calorie-recipes","no-cook-food","soup-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1392e7d5b593', 'en', 'US', 'Hazelnut Olive Oil Cake (GF, DF)', 'Recipe video above: This is the Lemon Olive Oil cake from a delightful cookbook called "Just Desserts" by Charlotte Ree (Amazon here). I''ve taken the liberty of renaming it because I enjoy the hazelnut flavour so much, I wanted to headline it. So I did!Personally, olive oil in desserts confuses my taste buds. So I like that it''s not a dominant flavour here, hazelnut is. Olive oil gives this cake a rich brownie-like texture in a way that butter never will. I''m addicted to the meringue-like crispy edges - I want to slice it all off and run away with it!This is an excellent gluten-free, dairy-free cake you can make for gatherings that pretty much everyone can enjoy. Don''t skip the lemon zest! I tried it with and without, and it''s amazing how it brings out the hazelnut flavour. I LOVE THIS cake!', 'https://www.recipetineats.com/tachyon/2022/09/Olive-oil-hazelnut-cake_7.jpg', 15, 45, 60, 12, '[{"id": "ing_hazelnut_meal", "quantity": {"value": 150.0, "unit": "unit"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.013, "unit": "tub of 200g"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_extra_virgin_olive_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 250.0, "unit": "carton of 12"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.2, "unit": "bottle of 50ml"}}, {"id": "ing_whole_hazelnuts", "quantity": {"value": 37.5, "unit": "jar"}}, {"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_cr_me_fra_che", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["150g / 5oz hazelnut meal (1 3/4 cups firmly packed) (ground hazelnut, sub almond meal, Note 1)","1/2 tsp baking soda / bicarbonate soda (, sifted (Note 2))","Zest of 1 lemon (, finely grated (about 2 teaspoon or so))","Pinch of salt","1/2 cup + 1 1/2 tbsp extra-virgin olive oil (Note 3)","1 cup caster sugar / superfine sugar (sub ordinary/granulated sugar)","3 large eggs (, at room temperature (Note 4))","2 tsp vanilla extract"]},{"ingredients":["1/4 cup whole hazelnuts (, toasted then roughly chopped (Note 5))","Icing sugar / confectioners'' sugar (, for dusting)","Crème fraîche (dollop for company)"],"purpose":"Optional decoration:"}]', '[{"description":"Preheat oven to 170°C / 340°F (150°C fan). Grease a 20 cm/8\" springform pan with olive oil then line with baking paper (parchment paper), then grease the paper. (Note 6)","images":[],"step":1},{"title":"Dry ingredients","description":"In a medium bowl, mix the hazelnut meal, baking soda, lemon and salt.","images":[],"step":2},{"title":"Beat wet ingredients","description":"In a large bowl, beat the olive oil, eggs and sugar for 2 to 3 minutes on speed 7 of a handheld beater or until it becomes pale and thick (like pouring cream).","duration":2.5,"images":[],"step":3},{"description":"Add vanilla and beat on speed 1 for 10 seconds.","duration":0.16666666666666666,"images":[],"step":4},{"title":"Mix in dry","description":"Add the Dry ingredients and mix in gently using a rubber spatula.","images":[],"step":5},{"title":"Bake 45 minutes","description":"Pour the batter into the prepared pan and bake for 45 minutes. It will puff up dramatically in the oven but it collapses as it cools.","duration":45,"images":[],"step":6},{"title":"Cool","description":"Remove from the oven and allow the cake to fully cool in the pan before releasing from the springform pan. This is a rustic cake that has higher edges and a flatter centre. Perfect proportions, I say: plenty of meringue-like edges and not an overwhelming amount of the rich brownie-like centre of the cake!","images":[],"step":7},{"title":"Decorate","description":"Sprinkle with hazelnuts and dust with icing sugar, if desired. Serve fully cool.","images":[],"step":8}]', '["egg","nuts"]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["dessert-recipes","dietary","easter-baking-desserts","gluten-free-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c93e7300e836', 'en', 'US', 'Immunity Boosting Green Goddess Soup', 'Recipe video above. A feel-good soup packed full of nutrition created to cure winter colds! While you could switch out the veg with whatever you’ve got, I’ve tried various combinations and this is my favourite for best flavour so it doesn’t taste like you’re eating a bowl of hot grass.Don’t skip the spices. Doesn’t look like much but it really makes a difference!', 'https://www.recipetineats.com/tachyon/2022/07/Immunity-Boosting-Green-Goddess-Soup-1.jpg', 15, 0, 15, 8, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_fennel", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_celery", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_broccoli", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.013, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 1.75, "unit": "L"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_kale", "quantity": {"value": 5.0, "unit": "unit"}}, {"id": "ing_baby_spinach", "quantity": {"value": 5.0, "unit": "bag of 250g"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_cup_sunflower_seeds", "quantity": {"value": 30.0, "unit": "jar"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}]', '[{"ingredients":["2 tbsp olive oil","1 onion (, diced (Note 1))","1 leek (white part only) or another onion (, diced (Note 1))","1 medium fennel (, chopped (Note 2))","2 celery stems (, roughly chopped)","5 garlic cloves (, roughly minced)","3/4 tsp all spice powder (sub mixed spice)","3/4 tsp cumin powder (sub coriander)","1 medium potato ((any type), peeled, 1.5 cm cubes )","1 head broccoli (, florets (peel and chop stalk too))","2 1/2 tsp cooking / kosher salt","3/4 tsp black pepper","1.75 litres / quarts water (Note 3)","1 cup frozen peas (Note 4)","5 cups (tightly packed) kale leaves (, roughly chopped (1 small bunch, Note 5))","5 cups (tightly packed) baby spinach (Note 6)","3/4 cup thickened cream (Note 7)"]},{"ingredients":["2 tbsp sunflower seeds, toasted (or croutons or other toasted nuts, Note 8)","Cream and/or olive oil for drizzling"],"purpose":"Garnishes"}]', '[{"title":"Sauté aromatics","description":"Heat oil in a very large pot (6L/qt) over medium high heat. Cook onion, leek, celery, garlic and fennel for 5 minutes until softened.","duration":5,"images":[],"step":1},{"title":"Cook spices","description":"Add all spice and cumin, and cook for 1 minute.","duration":1,"images":[],"step":2},{"description":"Add water, potatoes, broccoli, salt and pepper. Stir, bring to simmer, and simmer for 7 minutes (no lid) until the broccoli is tender.","duration":7,"images":[],"step":3},{"title":"Add peas","description":"Add peas, simmer for 1 minute.","duration":1,"images":[],"step":4},{"title":"Blitz in kale","description":"Remove pot off the stove. Add kale, push it under the liquid, then blitz with a stick blender until mostly smooth. Add spinach, push under the liquid then blitz again until smooth as possible (approx 3 to 5 mins). This will result in a smooth soup but with little green bits in it - I like this for a little texture.","images":[],"step":5},{"title":"Serve","description":"Stir in cream. Ladle into bowls, drizzle with extra cream and/or olive oil and finish with a sprinkle of sunflower seeds. Eat and feel great!","images":[],"step":6}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","low-calorie-recipes","soup-recipes","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0291b8e516de', 'en', 'US', 'Maple Glazed Ham', 'RECIPE VIDEO ABOVE. Baked ham made easy! The most incredible ham glaze ever with a subtle perfurme from maple and festive spices. If using a larger ham, use recipe Scaler (click on Servings and slide). Recipe will serve 30 - 40 with another main and sides, or 25 if it''s the only main. New to Glazed Ham? Start here -> Guide to Making Glazed HamDon''t have maple syrup? Use honey, or make a classic Brown Sugar Mustard Glazed Ham.', 'https://www.recipetineats.com/tachyon/2017/12/Maple-Glazed-Ham_3.jpg', 30, 120, 170, 30, '[{"id": "ing_leg_ham", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_oranges", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_maple_syrup", "quantity": {"value": 0.75, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.225, "unit": "jar of 200g"}}, {"id": "ing_round_cinnamon", "quantity": {"value": 3.75, "unit": "jar"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}]', '[{"ingredients":["5 kg / 10 lb leg ham, ( bone in, skin on (Note 1))","30 Cloves (for studding the ham, optional - mainly for decorative purposes)","2 oranges (, cut into quarters (Note 2))","1 cup (250ml) water"]},{"ingredients":["3/4 cup (185ml) maple syrup (sub honey)","3/4 cup (165g) brown sugar (, packed)","3 tbsp dijon mustard (can sub American or other plain mustard)","3/4 tsp ground cinnamon","1/2 tsp All Spice ( (or nutmeg))"],"purpose":"Glaze"}]', '[{"description":"Take ham out of fridge 1 hour prior.","images":[],"step":1},{"description":"Preheat oven to 160°C / 320°F (140°C fan). Arrange shelf in lower third so the ham will be sitting in the centre of the oven (rather than in top half of oven).","images":[],"step":2},{"description":"Place the Glaze ingredients in a bowl and mix until combined - use whisk if needed.","images":[],"step":3},{"description":"Remove ham rind (skin)","images":[],"step":4},{"description":"Run small knife around bone handle, down each side of the ham, and under the rind on the cut face. (See video & photos in post)","images":[],"step":5},{"description":"Slide fingers under the rind on the cut face of the ham, and run them back and forth to loosen while pulling the rind back. Use knife if needed to slice off any residual rind.","images":[],"step":6},{"description":"Lightly cut 2.5cm / 1\" diamonds across the fat surface of the ham, about 75% of the way into the fat. Avoid cutting into the meat.","images":[],"step":7},{"description":"Insert a clove in the intersection of the cross of each diamond on the surface (optional).","images":[],"step":8},{"description":"Glaze and Baking","images":[],"step":9},{"description":"Place the ham in a large baking dish. Prop handle up on edge of pan + scrunched up foil so surface of the ham is level (for more even caramelisation).","images":[],"step":10},{"description":"Squeeze the juice of 1 orange (4 quarters) over the ham. Then place them along with the remaining orange into the baking dish around the ham.","images":[],"step":11},{"description":"Brush / spoon half the glaze all over the surface and cut face of the ham (don''t worry about underside, glaze drips down into pan)","images":[],"step":12},{"description":"Pour the water in the baking dish, then place in the oven.","images":[],"step":13},{"title":"Bake for 1.5","description":"2 hrs, basting very generously every 30 minutes with remainig glaze + juices in pan, or until sticky and golden.","images":[],"step":14},{"description":"Use foil patches to protect bits that brown faster than others - press on lightly, caramelisation won''t peel off with the foil.","images":[],"step":15},{"description":"Allow to rest for at least 20 minutes before serving. Baste, baste, baste before serving - as the glaze in the pan cools, it thickens which means it \"paints\" the ham even better - but be sure to save pan juices for drizzling.","images":[],"step":16},{"description":"Serving and presentation tips","images":[],"step":17},{"title":"My favourite sauce: Use pan juices as the sauce","description":"it''s loaded with flavour! Pour into a jug and warm so it''s pourable. Thin slightly with water if required. Drizzle sparingly as the glaze flavour is intense!","images":[],"step":18},{"title":"Other condiments","description":"Dijon mustard, wholegrain mustard, onion jam, tomato chutney, cranberry sauce.","images":[],"step":19},{"title":"Presentation","description":"Wrap handle with baking paper and ribbon if desired. Remove cloves. Cover serving platter with lots of green fluffage, then place ham on. Surround with more quartered oranges, for colour. Let people admire before carving!","images":[],"step":20},{"title":"Serving","description":"Personal preference whether to serve at room temp or warm, I like either. I also like to drizzle with pan juices - it looks messier but tastes fabulous. Slice thinly! I start slicing at the table, then finish it in the kitchen (towards end when it gets messy!)","images":[],"step":21},{"title":"Leftovers","description":"See list in post for recipe using leftover ham and ham bone!","images":[],"step":22},{"title":"Storing","description":"Will keep for at least a week in the fridge if properly stored using a water-vinegar soaked ham bag or pillowcase. Otherwise freeze - don''t forget the bone! See How to Store Glazed Ham for directions.","images":[],"step":23}]', '["mustard"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["dietary","easter-mains","easter-recipes","gluten-free-recipes","iconic-dishes","pork-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e4bfa83e8a72', 'en', 'US', 'Bacon Wrapped Pork Tenderloin', 'Recipe video above. Bacon wrapped pork tenderloin is one of those incredible miracle recipes that just happens to only require 4 ingredients - pork, bacon, honey and olive oil. Just sear the pork, then roll up in bacon, drizzle with honey and bake!Had one too many sad, dried out roast pork tenderloins? This happens because this cut has almost no fat. By wrapping it in bacon, it not only protects the pork but the bacon juices bastes the pork, helping it stay nice and juicy!', 'https://www.recipetineats.com/tachyon/2015/05/Bacon-wrapped-pork_71.jpg', 5, 30, 35, 4, '[{"id": "ing_bacon", "quantity": {"value": 8.0, "unit": "pack of 200g"}}, {"id": "ing_pork", "quantity": {"value": 8.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_honey", "quantity": {"value": 0.06, "unit": "jar of 500g"}}]', '[{"ingredients":["8 to 10 slices of streaky bacon (, long enough to wrap around the pork 1 1/2 times.)","1 lb / 500g pork tenderloin (, at room temperature)","Salt and pepper","1 tbsp olive oil","2 tbsp honey ( or maple syrup (honey works better, it''s thicker))"]}]', '[{"description":"Preheat oven to 200°C/390°F (180°C fan).","images":[],"step":1},{"title":"Lay out bacon","description":"Lay the bacon strips vertically on a board, slightly overlapping (see photo in post). There should be enough bacon so when rolled will wrap the length of the pork.","images":[],"step":2},{"description":"Season the pork with salt and pepper. Tuck the thin end of the fillet under so the pork is roughly the same thickness from end to end.","images":[],"step":3},{"title":"Brown pork","description":"Heat the oil in an oven-proof skillet over high heat. Sear the pork on all sides until nicely browned. (Don''t worry about cooking through, it will go in the oven.) Turn off heat, remove pork and allow to cool enough to handle.","images":[],"step":4},{"title":"Wrap pork in bacon","description":"Place pork on the arranged bacon at the end closest to you. Use a long knife to lift the bacon under the pork and roll the pork so the bacon wraps around the fillet. Finish with the bacon seam side down.","images":[],"step":5},{"title":"Honey","description":"Use the knife to transfer back into the skillet. Drizzle over honey and brush all over.","images":[],"step":6},{"title":"Bake 25 minutes","description":"Transfer skillet to oven for 25 minutes and roast pork until the internal temperature is 65°C / 149°F. (Note 1) Baste with pan juices at the 20 minute mark, mopping up plenty of the honey and juices pooled in the pan (this will make bacon deep golden).","duration":25,"images":[],"step":7},{"title":"Rest 5 minutes","description":"Remove from oven and let it rest for 5 minutes. Baste once more just before serving. To serve, cut into thick slices. Serve with remaining pan juices.","duration":5,"images":[],"step":8}]', '[]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["dietary","dinner-tonight","gluten-free-recipes","main-dishes","mains","most-popular","pork","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1b5556e564bb', 'en', 'US', 'Fish Seasoning - for any fish', 'Recipe video above. This is a great spice seasoning for fish that makes for a quick and easy way to add flavour to fish. Based on Old Bay Seasoning, it''s a combination of spices that works really well together. I''ve used flathead fillets today, but it can be used for any fish suitable for pan-frying. Don''t worry if you don''t have all the spices, there''s plenty of subs. Allow ~180g/6oz fish per person.', 'https://www.recipetineats.com/tachyon/2021/06/Fish-Seasoning-Flathead-_6.jpg', 5, 10, 15, 4, '[{"id": "ing_celery", "quantity": {"value": 0.1, "unit": "head"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.013, "unit": "jar of 200g"}}, {"id": "ing_mace", "quantity": {"value": 0.25, "unit": "unit"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_round_clove", "quantity": {"value": 0.625, "unit": "jar"}}, {"id": "ing_ginger", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.016, "unit": "jar of 40g"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.016, "unit": "jar of 40g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 45.0, "unit": "block of 250g"}}, {"id": "ing_butter", "quantity": {"value": 45.0, "unit": "block of 250g"}}]', '[{"ingredients":["1 tsp celery salt ((or 3/4 tsp salt])","1/4 tsp black pepper","1 tsp smoked paprika","1/2 tsp mustard powder","1/4 tsp mace","1/4 tsp allspice","1/8 tsp ground clove","1/8 tsp ginger powder","1/8 tsp cayenne pepper (or pure chilli powder)","1/8 tsp ground cardamom"],"purpose":"Fish Seasoning (Note 1 for subs):"},{"ingredients":["750g / 1.5lb fish fillets (, skinless, boneless (I used flathead, Note 2))","45g / 3 tbsp unsalted butter","30g / 2 tbsp Extra unsalted butter – for drizzling (optional)"],"purpose":"Fish:"}]', '[{"title":"Fish Seasoning","description":"Place ingredients in a bowl and mix to combine. It will keep for months in an airtight container. This quantity is enough for 750g / 1.5lb fish (serves 4 people)","images":[],"step":1},{"description":"Seasoning and cooking fish:","images":[],"step":2},{"title":"Season fish","description":"Sprinkle Seasoning on both sides of fish. Lightly rub to spread Seasoning.","images":[],"step":3},{"title":"Cook fish in two batches","description":"Melt 30g / 2tbsp butter in large non-stick skillet over medium high heat. Cook fish until golden on each side (see Cook times below). Remove to a plate.","images":[],"step":4},{"title":"Cook remaining fish","description":"Melt remaining butter in skillet and cook remaining fish.","images":[],"step":5},{"title":"Rest","description":"Rest fish for 3 minutes before serving with extra butter sauce (see next step).","duration":3,"images":[],"step":6},{"title":"Extra butter sauce (optional)","description":"Add extra butter into pan over medium heat and melt until foaming. Drizzle over fish when serving.","images":[],"step":7}]', '["fish","milk","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","dinner-tonight","fish-recipes","low-calorie-recipes","mains","other","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8e573b3148f8', 'en', 'US', 'Tuna Steak', 'Recipe video above. The perfect tuna steak is seared on the outside and deliciously rare on the inside. It takes 2 1/2 minutes flat - fastest fish recipe ever! Tuna loin is lean so best served raw or rare if cooked, to enjoy the tender, almost creamy flesh. There''s a reason why tuna is a darling of the fine dining scene! Best served just slightly warm or at room temperature. Pictured with Sauce Vierge, a summery, simple French salsa / vinaigerette sauce that pairs perfectly with fish!', 'https://www.recipetineats.com/tachyon/2021/05/Tuna-Steak-Main_2.jpg', 5, 3, 8, 2, '[{"id": "ing_x_180_200g_tuna_2_5_3cm_1_1_2_thick", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_sauce_vierge", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_chervil", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["2 x 180 - 200g (6.5 - 7oz) tuna (skinless, boneless). 2.5-3cm / 1-1.2\" thick (Note 1)","1 tsp olive oil","1/4 tsp sea salt","1/8 tsp black pepper"]},{"ingredients":["2 tsp olive oil (, or oil spray)"],"purpose":"Cooking:"},{"ingredients":["Sauce Vierge (French salsa / vinaigrette for fish)","Chervil sprigs (substitute small flat leaf or curly parsley leaves) or small edible flowers (optional)"],"purpose":"Serving suggestion (Note 2):"}]', '[{"title":"Prepare resting tray","description":"Place a rack on a tray. (Note 3)","images":[],"step":1},{"title":"Oil and season tuna","description":"Drizzle half the oil over the tuna. Smear over one side, then sprinkle with half the salt and pepper. Flip and repeat.","images":[],"step":2},{"title":"Heat skillet","description":"Heat skillet (preferably a skillet with grille lines) over high heat until smoking hot. The hotter, the better!","images":[],"step":3},{"title":"Oil skillet (if required)","description":"If your skillet is not well-seasoned, brush skillet with olive oil or take pan off stove and spray with any oil (SAFETY WARNING! Note 4)","images":[],"step":4},{"title":"Cook first side","description":"Place tuna steak in the skillet (I do one at a time for best results, Note 5) and cook for 45 seconds.","duration":0.75,"images":[],"step":5},{"title":"Rotate for grill lines","description":"Turn steak 45 degree. Continue cooking another 45 seconds.","images":[],"step":6},{"title":"Cook other side","description":"Flip tuna carefully, then leave for 1 minute or until the internal temperature in the middle reads 48°C / 118°F (Note 6).","duration":1,"images":[],"step":7},{"title":"Rest","description":"Remove tuna from skillet and place on rack. Rest for 5 minutes – it will cool down almost to room temperature. This is desirable for easier slicing and better eating (Note 7) Serve! See Note 2 for sauce options.","duration":5,"images":[],"step":8},{"title":"Plating up","description":"with Sauce Vierge option (pictured):","images":[],"step":9},{"title":"Slice, if desired (Note 7)","description":"Place tuna on a board with criss-crossing grill lines facing up. Slice the tuna into 4 or 5 thick slices, holding the edges with your fingers as needed to ensure the seared surface doesn''t crumble. Transfer to serving plate and separate the slices slightly so they insides are just visible, or on an a slightly angle, overlapping each other.","images":[],"step":10},{"title":"Sauce Vierge","description":"Spoon the Sauce Vierge over steaks, leaving small piles of tomato here and there on the tuna slices, and a few on the plate. Other sauce options: See Note 2.","images":[],"step":11},{"title":"Finishing","description":"Drizzle with a bit of olive oil. It looks beautiful as it is, but if you want to raise the bar even higher, add a few small sprigs of chervil and some edible flowers!","images":[],"step":12}]', '["fish"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Universal","Western"],"categories":["dietary","easter-mains-fish-seafood","fish-recipes","gluten-free-recipes","low-calorie-recipes","mains","other","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_452f771389a1', 'en', 'US', 'Sauce Vierge (fresh French sauce / salsa)', 'Sauce Vierge is a French sauce made from diced tomatoes, olive oil, fresh herbs and lemon juice. It pairs especially well with seafoods, such as the Tuna Steak I shared today.Sauce Vierge was popularised by Michel Guérard, a French chef who championed nouvelle cuisine (literally, "new cuisine") in the 1970''s, a food style which emphasised freshness, simplicity, and lightness. Really, this sauce couldn''t be a better expression of this style of French cooking!Serve with white meats (chicken, pork), vegetables, use as a salsa-type dip (corn chips, mini crostini), pile onto toasted bread to make bruschetta or crostini, pile over an omelette or frittata, or corn fritters! Great made on the day, even better the next day!', 'https://www.recipetineats.com/tachyon/2021/05/Sauce-Vierge-making.jpg', 10, 0, 10, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_black_olives", "quantity": {"value": 12.0, "unit": "bottle"}}, {"id": "ing_fish_fillets", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.833, "unit": "pack of 3 heads"}}, {"id": "ing_parsley", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_chives", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_tarragon", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["5 1/2 tbsp extra virgin olive oil","2 tbsp fresh lemon juice","2 tomatoes (, seeded and diced into 0.8cm (1/3\") cubes (Note 1))","12 black olives (, pitted and cut into strips (Spanish, kalamata, or other))","2 anchovy fillets (, very finely minced (Note 2))","1/2 tsp garlic (, very finely minced)","1 tsp parsley (, finely chopped (Note 3))","1/2 tsp chives (, finely chopped (Note 3))","1/2 tsp tarragon leaves (, finely chopped (Note 3))","1/4 tsp salt","1/4 tsp black pepper"]}]', '[{"title":"Mix","description":"Mix ingredients in a bowl. Taste and add more salt if you want (depends how salty the food you are putting it on is).","images":[],"step":1},{"title":"Uses","description":"Use at room temperature as a salsa / sauce, piled onto fish (such as Tuna Steak), other seafood, grilled or steamed vegetables, chicken, pork, over pasta, piled onto bread, or even as a dip for scooping up with crostini or corn chips! You can also warm the sauce if you wish: Gently heat in a small pot and warm to blood temperature. Do not simmer or boil or you''ll lose the freshness!","images":[],"step":2},{"title":"Storage","description":"Use immediately on making, or the next day. Keep in a very airtight container and allow to come to room temperature before serving.","images":[],"step":3}]', '["fish"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["main_course"],"cuisine":["French"],"categories":["dietary","gluten-free-recipes","sauces"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4d684710170c', 'en', 'US', 'Whole Baked Fish – Herb-stuffed with Garlic & Dill Butter Sauce', 'Recipe video above. For anyone who''s wondered how to cook a whole fish, the best and easiest way is to bake it whole. The flesh is at its juiciest and most tender, and it''s completely effortless! Roasting fish this way is easy enough for midweek meals, but still makes an impressive centrepiece for occasions! I''m using a whole snapper today, but this recipe will work for virtually any fish. See Note 1 for other fish ideal to cook whole.', 'https://www.recipetineats.com/tachyon/2021/04/Whole-Baked-Fish_7.jpg', 10, 20, 30, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_dill_sprigs_packed", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_butter", "quantity": {"value": 150.0, "unit": "block of 250g"}}, {"id": "ing_dill", "quantity": {"value": 0.075, "unit": "kg"}}]', '[{"ingredients":["2 x 800g / 1.6 lb whole snapper or other whole fish (, scaled, gutted and cleaned (Note 1))","1 1/2 tsp salt (, kosher/cooking (not table salt))","1/2 tsp black pepper","2 tbsp extra virgin olive oil"]},{"ingredients":["1/2 cup fresh dill sprigs, packed","1/2 cup parsley leaves, packed","4 garlic cloves (, finely sliced)","1 lemon (, sliced (8 slices each lemon))"],"purpose":"Stuffing:"},{"ingredients":["150g / 10 tbsp unsalted butter (, cut into cubes)","2 tsp garlic (, finely minced)","1 tbsp fresh dill (, finely chopped)"],"purpose":"Dill Garlic Butter:"}]', '[{"description":"Preheat oven to 220°C/430°F (200°C fan). Line a tray with parchment/baking paper.","images":[],"step":1},{"title":"Trim fins","description":"Cut all fins off the fish using scissors – both fins on the side, and the fins on the back and underside of the fish (but not the tail).","images":[],"step":2},{"title":"Slash flesh","description":"Cut 3 slashes on each side of the fish, cutting through flesh down to the bone (see photos in post and/or video, helpful!).","images":[],"step":3},{"title":"Stuff fish (Note 2)","description":"Sprinkle a bit of salt and pepper inside the cavity of the fish. Scatter the cavity with garlic slices, then stuff with parsley and dill. Layer lemons on top of herbs.","images":[],"step":4},{"title":"Tie fish (Note 3)","description":"Using kitchen string make 3 ties to hold fish together.","images":[],"step":5},{"title":"Season skin","description":"Sprinkle remaining salt and pepper on the skin (both sides), including a bit on the head of the fish. Then drizzle with olive oil. Rub all over the fish, including in the slashes.","images":[],"step":6},{"title":"Bake 20 minutes (Note 4)","description":"Place fish on prepared tray. Bake for 20 minutes or until the internal temperature is 55°C/131°F (insert thermometer in the thickest part of the fish, not against the bone). Alternatively, use a small knife at one of the cut slits in the fish to prise a bit of meat gently away from the spine. If it flakes away from the bone without resistance, it''s done.","duration":20,"images":[],"step":7},{"title":"Rest","description":"Remove from oven, transfer to serving platter and leave it to rest for 5 minutes. The internal temperature will rise to 58°C / 136.5F (\"medium\", ie. just-cooked and not raw at all, very juicy and moist).","duration":5,"images":[],"step":8},{"description":"Serve with Garlic & Dill Butter Sauce on the side. Either pour over the butter just prior to serving the fish, or let everyone help themselves. See this video by Serious Eats for a concise tutorial for how to carve and serve a whole roasted fish.","images":[],"step":9},{"description":"Garlic & Dill Butter Sauce:","images":[],"step":10},{"title":"Melted butter","description":"Place butter in a saucepan over medium-high heat. Once melted, add garlic and cook, stirring, for 45 seconds to 1 minute until it smells ridiculously good and you''re salivating!","duration":0.75,"images":[],"step":11},{"title":"Add dill","description":"Remove from heat. Stir in dill. Use per recipe.","images":[],"step":12}]', '["fish","milk"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","easter-mains-fish-seafood","fish-recipes","gluten-free-recipes","mains","other","seafood-recipes","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a97f4491ff04', 'en', 'US', 'Mushroom Soup', 'Recipe video above. This is a magnificent yet easy, creamy Mushroom Soup where you''ll enjoy intense mushroom flavour with every mouthful! Forget whole mushrooms bits floating in a wan broth. Blending the soup releases all the gorgeous, earthy flavour locked up in the mushrooms into every luscious, creamy bite.', 'https://www.recipetineats.com/tachyon/2021/04/Mushroom-Soup-in-bowl.jpg', 10, 30, 40, 4, '[{"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_mushroom", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.812, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_croutons", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_extra_virgin_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["30g / 2 tbsp unsalted butter","1 onion (, chopped)","2 garlic cloves (, minced)","400g / 14 oz white mushrooms (Note 1)","200g/ 7 oz Swiss Brown/Cremini mushroom (Note 1)","3 1/4 cups vegetable stock","1/4 tsp salt (, cooking/kosher)","1/8 tsp black pepper","3/4 cup crème fraiche or cream (any full-fat) (Note 3)"]},{"ingredients":["Croutons (Note 4)","Cream or extra virgin olive oil (, for drizzling)","Parsley ((roughly chopped), chervil (if you''re feeling a bit fancy), or thyme leaves)","Bread for dunking"],"purpose":"Garnishes/serving:"}]', '[{"title":"Chopping mushrooms","description":"Cut mushrooms into 4 slices, then dice into 3 or 4 pieces.","images":[],"step":1},{"title":"Saute onion and garlic","description":"Melt butter in a large pot over medium high heat. Add onion and garlic. Cook for 3 minutes until softened, but not golden.","duration":3,"images":[],"step":2},{"title":"Cook mushrooms","description":"Add mushrooms and cook for 10 minutes, stirring regularly. Do not try to brown; they won''t as the pot is too crowded but we do not need colour.","duration":10,"images":[],"step":3},{"title":"Simmer 15 min","description":"Add vegetable stock, salt and pepper. Bring to a boil, then lower heat to medium and simmer gently for 15 minutes without a lid.","duration":15,"images":[],"step":4},{"title":"Cream","description":"Stir in cream (or crème fraiche), then simmer for another 5 minutes.","images":[],"step":5},{"title":"Blitz","description":"Transfer to a blender (do in batches, if necessary). Remove the cap from the feeding hole in the blender lid (Note 5), cover the hole with a folded tea towel. Blend until completely smooth.","images":[],"step":6},{"description":"Return to pot, simmer for a minute or two until bubbles caused by blending largely subside and soup is hot.","images":[],"step":7},{"title":"Serve","description":"Ladle into bowls. Garnish with a drizzle of extra virgin olive oil or cream, croutons and parsley or (if you''re feeling a bit fancy), chervil. Don''t forget bread for dunking!","images":[],"step":8}]', '["gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["dietary","gluten-free-recipes","mushroom-recipes","soup-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9b3362af698f', 'en', 'US', 'Homemade Vegetable Stock', 'Recipe video above. This is an easy, classic vegetable stock that''s an essential addition to every cook''s toolkit. It will complement and bring flavour into anything you use it in.As with all stocks, homemade vegetable stock is far superior to store bought, with the added bonus that it''s the easiest of all stocks to make! The ingredients are simple, affordable and very minimal waste is discarded after straining compared to meat based stocks like beef stock.Makes 1 litre / 1 quart vegetable stock (4 cups). Use in place of any recipe calling for vegetable stock (same quantity) or even chicken stock.', 'https://www.recipetineats.com/tachyon/2021/04/Homemade-Vegetable-Stock_7.jpg', 0, 120, 120, 4, '[{"id": "ing_water", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_parsley", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_coriander", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2 litres / 2 quarts water","2 medium carrots (unpeeled), cut in 3 (180g/6oz each)","1 onion (, quartered (~250g/8oz))","1 celery stem (, cut in 4 pieces (~180g/6oz))","2 garlic cloves, (smashed (Note 1))","3 parsley stems","1 bay leaf","1 thyme sprig","1/2 tsp black peppercorns","1/2 tsp coriander seeds","1 tsp salt (, kosher/cooking for store bought level salted vegetable stock (Note 2))"]}]', '[{"title":"Simmer 2 hours","description":"Place all ingredients in a large pot. Bring to simmer over high heat, then reduce heat to low and simmer for 2 hours without a lid. The water should not be bubbling, it should just ripple gently. Stock should reduce by about half.","images":[],"step":1},{"description":"Strain, pressing juices out of the vegetables. You should have 1 litre / 1 quart (4 cups) of stock. If you have much more than this, return the strained liquid into the pot and simmer to continue to reduce.","images":[],"step":2},{"title":"How to use","description":"Use in place of store-bought stock in any recipe - 1:1 ratio.","images":[],"step":3},{"title":"Storage","description":"Keeps in the fridge for 5 days, or freeze for 3 months. I usually freeze in 1 cup portions in jars, small ziplock bags (freeze flat for efficient use of space and faster defrosting) or in plastic containers.","images":[],"step":4}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["dietary","gluten-free-recipes","homemade-stocks","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_82881b115ad1', 'en', 'US', 'Slow-Roasted Crispy Pork Belly', 'Recipe video above. This is a pork belly that''s slow-roasted so the fat renders and cooks the belly confit-style in its own fat. The result? Ridiculously juicy, impossibly tender yet still-sliceable meat, crowned with the most amazing crispy crackling of your life. It comes down to three simple, game-changing techniques: 1. Do NOT score the skin; 2. Low heat followed by high heat; 3. Keep the pork level using balls of foil.Perfect meat, perfect crackling ... Every. Single. Time! (Read the post for all the details on how to do it right!)Bonus: Excellent for make ahead, reheats 99% perfectly the next day. See notes.', 'https://www.recipetineats.com/tachyon/2021/04/Overhead-slow-roasted-pork-belly.jpg', 5, 180, 185, 4, '[{"id": "ing_pork", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_fennel_powder_fennel_seeds", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_apples", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_vermouth_jus", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_cauliflower", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_see_in_post_for_more_sauce_options", "quantity": {"value": 1.0, "unit": "bottle"}}]', '[{"ingredients":["1kg / 2 lb pork belly with skin on","1 1/2 tsp olive oil (, divided)","1/2 tsp fennel powder / ground fennel seeds (, optional, Note 3)","1 tsp salt (, cooking/kosher salt (or 7/8 tsp table salt), divided)","1/4 tsp black pepper"]},{"ingredients":["Apple Sauce ()","Vermouth Jus ()","Cauliflower Puree (, (Note 2))","See in post for more Sauce options"],"purpose":"For serving (as pictured in post):"}]', '[{"title":"Dry skin overnight","description":"Place pork belly on a plate. Pat skin dry with paper towels. Leave uncovered in fridge overnight to dry out the skin. (If you don''t have time, pat the skin dry as best you can).","images":[],"step":1},{"description":"Preheat oven to 140°C/285°F (120°C fan).","images":[],"step":2},{"title":"Season flesh","description":"Drizzle flesh (only) with 1 tsp oil. Sprinkle over 1/2 tsp salt, the pepper and fennel powder. Rub all over the flesh, including on the sides, being sure you get right into all the cracks and crevices.","images":[],"step":3},{"title":"Wrap in foil","description":"Place 2 pieces of foil on a work surface. Put the belly in middle of foil, skin side up. Fold the sides in to enclose the belly, forming an open box, pinching corners to seal tightly and make it as snug as possible. Place meat on a tray.","images":[],"step":4},{"title":"Season skin","description":"Pat skin dry with paper towels. Rub with 1/2 tsp oil then sprinkle remaining 1/2 tsp salt evenly all over the skin surface, from edge to edge.","images":[],"step":5},{"title":"Slow roast 2 1/2 hours","description":"Place in the oven and roast for 2 1/2 hours. After 1 1/2 hours, remove and tighten the foil (pork will have shrunk), and continue cooking. This keeps the pork fat level up as high as possible, and the flesh protected so it stays moist.","images":[],"step":6},{"title":"Increase heat","description":"Remove pork from oven, then increase heat to 240°C/465°F (all oven types).","images":[],"step":7},{"title":"Level pork","description":"Remove pork from foil and place on a rack set over a tray (using rack is best, but optional). Use scrunched up balls of foil stuffed under pork to prop up so the skin surface is as level and horizontal as possible (see photos in post).","images":[],"step":8},{"description":"30 minutes on high heat! Place the pork back in the oven for 30 minutes, rotating after 15 minutes as needed, until the crackling is deep golden, puffy and crispy all over. If some patches are browning faster, protect with foil patches. ⚠️ Open oven with care as it will be smokey - open your windows!","duration":30,"images":[],"step":9},{"title":"Rest 10 minutes","description":"Remove pork from oven. Rest for 10 minutes before slicing.","duration":10,"images":[],"step":10},{"title":"Serving","description":"Slice into 2cm / ⅘\"-thick slices using a serrated knife. Pictured in post with Apple Sauce and Vermouth Jus, with a side of Cauliflower Puree (Note 2)! See directions in post for how to plate it up as pictured (fine dining style!), as well as a list of more sauce options.","images":[],"step":11}]', '[]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","gluten-free-recipes","iconic-dishes","mains","pork","pork-recipes","roasts","slow-cooked-fall-apart"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e19cd37c75c1', 'en', 'US', 'Apple Sauce', 'Recipe video above. This is a recipe for an Apple Sauce, one of the two sauces I chose to accompany a Slow-Roasted Crispy Pork Belly I also published today. What sets this sauce apart from your run-of-the-mill basic Apple Sauce recipes? Starting with a caramel rather than just mixing sugar into the sauce. The result is a distinctly deeper, richer flavour in return for very little extra effort!See in post for more ideas for Apple Sauce uses, both savoury and sweet!Makes ~2 cups', 'https://www.recipetineats.com/tachyon/2021/04/Apple-Sauce_1.jpg', 10, 15, 25, 8, '[{"id": "ing_apples", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 1.0, "unit": "kg"}}]', '[{"ingredients":["3 gala apples (, peeled, quartered, cored, and sliced thinly (Note 1))","1/4 cup caster sugar / superfine sugar","2 tbsp sherry vinegar","50g / 3 ½ tbsp unsalted butter","1 pinch of salt"]}]', '[{"description":"Place sugar in a medium saucepan over low heat. Shake pan to spread sugar. Leave for a few minutes until the edges start melting and turning golden, then swirl the pan to spread the caramel/sugar to encourage even melting (do not stir, sugar may crystallise).","images":[],"step":1},{"description":"Once the sugar is all melted, add apple and vinegar. Mix, and cook for 8 - 10 minutes, stirring occasionally, until the apple is completely soft.","duration":9,"images":[],"step":2},{"description":"Add the butter, stir it in until mostly melted. Blitz until smooth using a stick blender (tilt saucepan if needed to ensure head is completely submerged to avoid splattering).","images":[],"step":3},{"title":"Serve with","description":"Slow-roasted crispy pork belly or any pork dishes. Also great for sweet applications – see in post for more ideas!","images":[],"step":4}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["dietary","gluten-free-recipes","sauces"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c74297076028', 'en', 'US', 'Beetroot Cured Salmon (Gin or Vodka, Gravlax)', 'Recipe video above. Too many cured salmon recipes are way too salty ot way too sweet! But once you know the right propotions, it''s ridiculously simple to make and far cheaper than buying equivalent shop-bought versions.Gently flavoured with spices and a little vodka or gin, this a show-stopping, sophisticated-looking modern classic. Wonderful elegant canape or individually plated starter (fine dining favourite!), as part of an antipasto platter or cheeseboard, or just generally having in the fridge to nibble or use in sandwiches!1kg / 2 lb salmon will easily serve 16 people as a starter (slices are cut thinly)Start this recipe at least 2 days before serving, preferably 3 days.', 'https://www.recipetineats.com/tachyon/2021/03/Beetroot-Cured-Salmon_0-1-copy.jpg', 10, 0, 10, 12, '[{"id": "ing_salmon_fillets", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_beetroot_beet_and_in_1cm_0_5_cubes", "quantity": {"value": 400.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_caraway_seeds", "quantity": {"value": 20.0, "unit": "jar"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.4, "unit": "jar of 50g"}}, {"id": "ing_coriander", "quantity": {"value": 0.4, "unit": "bunch"}}, {"id": "ing_vodka", "quantity": {"value": 5.5, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.4, "unit": "jar of 50g"}}, {"id": "ing_juniper_berries", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_in", "quantity": {"value": 400.0, "unit": "unit"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.6, "unit": "tub of 250g"}}, {"id": "ing_horseradish", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.003, "unit": "net of 500g"}}, {"id": "ing_dill", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_capers", "quantity": {"value": 50.0, "unit": "bottle"}}, {"id": "ing_oil", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 0.003, "unit": "net of 500g"}}]', '[{"ingredients":["1kg/ 2 lb single piece of fresh salmon","400g/ 14 oz beetroot/beet (raw), peeled and diced in 1cm / 0.5\" cubes (500g/1 lb weight pre-peeling)","1 cup cooking salt / kosher salt ( (NOT iodised and NOT table salt, Note 2))","2/3 cup white sugar"],"purpose":"Cured Salmon – Base:"},{"ingredients":["4 tsp caraway seeds (, whole)","4 tsp white peppercorn (, whole)","4 tsp coriander seeds (, whole)","5 1/2 tbsp vodka (OK to omit, Note 5)"],"purpose":"Vodka cure flavourings (Option 1):"},{"ingredients":["4 tsp black peppercorns (, whole)","4 tsp juniper berries (, whole)","4 tsp coriander seeds (, whole)","5 1/2 tbsp gin (OK to omit, Note 5)"],"purpose":"Gin Cure Flavourings (Option 2):"},{"ingredients":["1 cup sour cream","3 tbsp horseradish (fresh), finely grated (Note 6)","1/4 tsp salt","1/4 tsp lemon zest","1 tsp chopped dill"],"purpose":"Horseradish cream (for serving, Note 6 options):"},{"ingredients":["2 cucumbers (Lebanese not the long English/Telegraph ones)","2 tbsp red or white wine vinegar","1/4 tsp salt","2 tsp dill (, roughly chopped)"],"purpose":"Cucumber Ribbons, lightly pickled"},{"ingredients":["Dark rye bread (, thinly sliced 3mm / ⅛ \" (or crackers or other thinly sliced bread))","1/3 cup capers (some for garnish, some for assembling bites)","1/4 cup oil (vegetable, canola)","Fresh dill sprigs and lemon wedges or slices"],"purpose":"For serving:"}]', '[{"title":"Make beetroot cure","description":"Place the beetroot, sugar, salt plus the gin cure OR vodka cure ingredients in a food processor. Blitz until pureed like a smoothie – about 15 seconds on high, scraping down the sides as needed.","images":[],"step":1},{"title":"Line container","description":"Use a container into which the salmon fits snugly, but flat (Note 3). Line with two large pieces of cling wrap, overlapping one horizontally and one vertically, like a cross (so it will wrap salmon completely).","images":[],"step":2},{"title":"Place salmon in beetroot","description":"Spread beetroot mixture on the cling wrap inside the container. Lay salmon on top, flesh side down. Press down lightly but not too firm – flesh should be fully in contact with beetroot, not base of container.","images":[],"step":3},{"title":"48-hour cure","description":"Wrap up securely with the cling wrap, cover with lid (or seal container with more cling wrap). Refrigerate 48 hours (do not turn).","images":[],"step":4},{"title":"Rinse","description":"Unwrap salmon, rinse off beetroot mixture, then pat dry.","images":[],"step":5},{"title":"Recommended","description":"rest overnight: If time permits, place washed and dried salmon in an airtight container and refrigerate overnight. This allows the salt to redistribute more evenly throughout the salmon. (Note 4)","images":[],"step":6},{"title":"Horseradish cream","description":"Mix ingredients together until smooth.","images":[],"step":7},{"title":"Cucumber Ribbons","description":"Use a potato peeler to make long thing ribbons lengthwise down the cucumber. Toss with vinegar and salt, set aside for 10 minutes. Drain liquid, toss with dill, transfer to serving dish.","duration":10,"images":[],"step":8},{"title":"Fried crispy capers","description":"Heat oil in a small pan to 190°C/375°F. Fry capers for 30 sec/1 min until crisp. Drain on paper towels and cool.","duration":0.5,"images":[],"step":9},{"title":"Crispy bread","description":"Brush bread lightly on each side with olive oil, then bake in a 180°C/350°F oven for 8 minutes, turning halfway, until crisp.","duration":8,"images":[],"step":10},{"title":"Plating","description":"Place uncut salmon on a serving platter (one you can cut on). Scatter salmon with crispy capers and fresh dill. Place crispy bread and horseradish cream on the side, along with fresh lemon if using.","images":[],"step":11},{"title":"To serve","description":"Cut thin slices down to the skin (but not through it). Pivot the knife blade so it''s almost parallel to the skin and cut the each slice carefully away from the skin (you cannot eat the skin). Smear crispy bread with horseradish cream, top with salmon, a few capers, and sprig of fresh dill. Devour!","images":[],"step":12}]', '["fish","gluten","milk"]', '["keto_friendly","low_calorie"]', '{"mealType":["snack"],"cuisine":["Nordic"],"categories":["dietary","easter-brunch-recipes","easter-mains","easter-mains-fish-seafood","easter-recipes","finger-food","fish-recipes","gluten-free-recipes","iconic-dishes","mains","other","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e41029274863', 'en', 'US', 'Salsa Verde recipe', 'Recipe video above. Salsa Verde is the Swiss Army knife of condiments! This herby, tangy and savoury green sauce goes with so many things, especially roasted and grilled meats, seafood and vegetables. It''s featured in my Rosemary Garlic Rack of Lamb recipe.This Salsa Verde version is a variation on traditional Italian Salsa Verde, made with basil, parsley and mint, giving a lovely balance where no one herb dominates. It''s a softer, more rounded and less pungent version which I feel is a bit more versatile for use.Want a classic Italian Salsa Verde? Add garlic and anchovies, and only use parsley.', 'https://www.recipetineats.com/tachyon/2021/03/Salsa-Verde_7.jpg', 10, 0, 10, 1, '[{"id": "ing_basil", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_mint", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_gherkins", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_capers", "quantity": {"value": 7.5, "unit": "bottle"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_ice_cube_for_loosening_but_keeps_the_mixture_green", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_anchovies", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.5, "unit": "pack of 3 heads"}}, {"id": "ing_parsley", "quantity": {"value": 0.45, "unit": "bunch"}}]', '[{"ingredients":["1 cup green basil (, packed)","3/4 cup parsley (, flatleaf; packed)","1/2 cup mint leaves (, packed)","2 tbsp gherkins (, roughly chopped)","1/2 tbsp capers","1 tsp dijon mustard","1/2 tbsp red wine vinegar","4 tbsp extra virgin olive oil","1/4 tsp salt","1 ice cube - for loosening but keeps the mixture green."]},{"ingredients":["1 - 2 anchovies","1/2 small garlic clove (, roughly chopped)","Substitute the basil and mint with more parsley"],"purpose":"CLASSIC ITALIAN additions"}]', '[{"title":"Blitz","description":"Place all ingredients in a tall container and blitz into a fine puree (or to the texture you prefer) using a stick blender. You could also use a small food processor.","images":[],"step":1},{"title":"Serving","description":"See in post for extensive list. Serve with steaks, chops or roasted lamb, beef, pork, chicken and seafood (especially great with fish!). It''s also excellent with legumes, cooked vegetables and even eggs. You can also use it in the same ways as a tapenade or pesto: Spread on crostini, use in sandwiches, dress salads with it, toss with pasta!","images":[],"step":2}]', '["mustard"]', '["gluten_free","keto_friendly","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Italian"],"categories":["dietary","gluten-free-recipes","italian-recipes","sauces"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c6510f43ab62', 'en', 'US', 'Garlic Butter Salmon recipe', 'Recipe video above. This is a simple-yet-luxurious, cheffy way to cook salmon. By basting continuously with foaming garlic butter, it seeps into every crack and crevice of the salmon and gives it the ultimate buttery crust.It may seem like a lot of butter for one recipe, but you need it to ensure good basting coverage. You do not have to use all of it for serving. Save leftover butter (even if just a smear!) and pan fry bread with it tomorrow, see post for photos. It''s Amazing – with a capital A!', 'https://www.recipetineats.com/tachyon/2021/03/Garlic-Butter-Salmon_9.jpg', 5, 8, 13, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 90.0, "unit": "block of 250g"}}, {"id": "ing_lemon", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["4 salmon fillets ((180g/6oz each), skinless and boneless)","1/2 tsp salt (, cooking / kosher)","1/4 tsp black pepper","1 1/2 tbsp olive oil","1 tbsp garlic (~2 cloves) (, finely minced by hand (don''t use a garlic press))","90g / 6 tbsp salted butter (, cut into cubes (or unsalted + 1/4 tsp salt))","1 tsp lemon juice (, plus more to taste)","2 tsp parsley (, finely chopped)"]}]', '[{"title":"Season salmon","description":"Take salmon out of fridge 30 minutes prior to cooking. Sprinkle both sides with salt and pepper.","images":[],"step":1},{"title":"Sear salmon 3 mins","description":"Heat oil in large non stick skillet over medium-high heat. Add salmon, presentation side (ie. curved side) down, and cook for 3 minutes until golden.","duration":3,"images":[],"step":2},{"title":"Turn, cook 1 min, then add butter","description":"Turn salmon and cook the other side for 1 minute. THEN put the butter in.","duration":1,"images":[],"step":3},{"title":"Baste 1 1/2 minutes","description":"Once butter is melted and foaming, add garlic and immediately start spooning the bubbling butter continuously over the salmon for 1 1/2 minutes. To do this, tilt the pan slightly so the butter pools on one side. Use a large spoon to scoop the butter up and spoon it over the salmon.","images":[],"step":4},{"title":"Remove salmon from stove","description":"Check Internal temperature of salmon. It should be 50°C/122°F for medium-rare (optimum juiciness pull temp). Remove salmon to a plate. Rest for 3 minutes – it will rise to 53°C/127°F. (See Note 2 for internal temperatures)","duration":3,"images":[],"step":5},{"title":"Add lemon juice to butter","description":"Put pan back on unlit stove to keep butter hot. Add lemon juice.","images":[],"step":6},{"title":"Serve","description":"Place salmon on serving plates. Spoon over butter (be judicious, it''s rich!), garnish with a sprinkle of parsley. Pictured in the post with Cauliflower Mash and leafy greens with French Vinaigrette.","images":[],"step":7}]', '["fish","milk"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","dinner-tonight","fish-recipes","gluten-free-recipes","mains","other","quick-and-easy","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_37ac14735846', 'en', 'US', 'Whole Orange Cake - flourless', 'Recipe video above. This is a wonderful moist cake that''s bursting with orange flavour in a way that you can only achieve using whole oranges - rind and all! Boiling the oranges removes the bitterness from the pith (white part). You still get the fainest whiff of bitterness in the finshed cake - but it''s actually pleasant and reminds you that you''re eating real oranges!It''s a terrific and easy cake that''s perfect to take to any gatherings since it''s also gluten-free and everyone can eat it. The nutty almond flavour is wonderful, and keeps it ultra-moist.Makes 1 x 23cm 9" cake 4 cm / 1.6" high, or 2 x 20cm/8" cakes 3cm / 1.2" high.', 'https://www.recipetineats.com/tachyon/2020/10/Flourless-Orange-Cake_2.jpg', 5, 90, 95, 12, '[{"id": "ing_oranges", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.042, "unit": "tub of 150g"}}, {"id": "ing_egg", "quantity": {"value": 500.0, "unit": "carton of 12"}}, {"id": "ing_sugar", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_almonds", "quantity": {"value": 1.65, "unit": "pack of 250g"}}]', '[{"ingredients":["2 medium oranges, fresh whole with rind on - any type","1 1/4 tsp baking powder","6 large eggs (, at room temp (Note 2))","1 1/4 cups white sugar","2 3/4 cups almond meal / ground almonds (Note 3)"]}]', '[{"title":"Boil 10 minutes","description":"Place oranges in a pot and cover with cold water. Bring to the boil over medium high heat. Boil for 10 minutes and drain.","duration":10,"images":[],"step":1},{"title":"Repeat x 2","description":"Put oranges back in the pot, cover with cold water and boil again for 10 minutes. Drain, then repeat once more (ie. boil oranges 3 x 10 minutes). Shortcut: Boil 40 minutes without draining, keeping an eye on water level. (Note 4)","duration":10,"images":[],"step":2},{"title":"Chop","description":"Rinse oranges, then cool slightly so you can handle them. Slice into 1cm / 1/4\" slices then dice, removing any seeds. Cool completely.","images":[],"step":3},{"title":"Preheat oven","description":"Preheat oven to 160°C/320°F (140°C fan). Grease and line a 23cm/9\" cake pan with baking/parchment paper. (Note 5)","images":[],"step":4},{"title":"Blitz oranges","description":"Place chopped oranges in a food processor (Note 6). Blitz on high for 4 x 10 second bursts, scraping down the sides in between, until it''s pureed into a marmalade consistency with only a few visible bits of rind remaining. It does not need to be completely smooth.","images":[],"step":5},{"title":"Blitz in remaining ingredients","description":"Add almond meal, eggs, baking powder and sugar. Blitz for 5 - 10 seconds on high until combined.","duration":0.125,"images":[],"step":6},{"title":"Bake 60 minutes","description":"Pour into prepared cake pans. Bake 60 minutes until the surface is golden and a toothpick inserted into the centre comes out clean.","images":[],"step":7},{"title":"Cool","description":"Cool fully in cake pan. Unless using loose base pan, cover surface with baking paper to help you turn it out (cake is sticky so may stick to your hand and tear surface otherwise.)","images":[],"step":8},{"title":"Serve: Decorate as desired","description":"I used slices of fresh oranges, rind strips and sprigs of flowers. A dusting of icing sugar / powdered sugar is also lovely. Cut, then serve! See Note 7 for suggestions.","images":[],"step":9}]', '["egg","nuts"]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["dessert-recipes","dietary","gluten-free-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_71b01e847fcf', 'en', 'US', 'Ceviche', 'Recipe video above. This is a traditional Mexican version of Ceviche except it''s not overly sour!! Actually, limes are typically less sour in Central and South America, than they are in Australia, the US and most Western countries, so I balance out the sour with olive oil. Avocado adds a deliciously creamy element, while the onion, tomato and coriander bring brightness to the dish. Serve sharing-style with corn chips, or in individual bowls for an elegant starter with crostini. Serves: 3 as a meal with corn chips or crostini, 5 - 6 as a starter', 'https://www.recipetineats.com/tachyon/2020/09/Ceviche_8.jpg', 10, 5, 15, 5, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.25, "unit": "pack of 1kg"}}, {"id": "ing_jalape_o_add_more_or_less_for_spiciness", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 8.0, "unit": "punnet of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_ime_juice", "quantity": {"value": 0.333, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}]', '[{"ingredients":["400g / 14 oz kingfish, tuna, sea bass or other sashimi-grade fish suitable for raw eating ( (Note 1))","1/4 red onion (, very finely sliced using mandolin (so it \"flops\"))","2 tsp fresh jalapeño (, finely chopped (or green chilli) - add more or less for spiciness)","8 cherry tomatoes (, halved (large ones quartered))","1/4 tsp black pepper","1/3 cup lime juice (, fresh (or lemon juice))"],"purpose":"“Cooked” fish:"},{"ingredients":["1/2 tsp salt (, cooking / kosher (or 1/4 tsp table salt, Note 2))","1 avocado (, ripe, cut into 1.25cm / 1/2\" cubes)","1/4 cup coriander/cilantro leaves (, roughly chopped (sub chives))","2 tbsp extra virgin olive oil (Note 3)"],"purpose":"Add ins:"}]', '[{"title":"Cut fish","description":"Cut fish into 1.25cm / 1/2\" cubes.","images":[],"step":1},{"title":"Toss in lime, leave 5 minutes","description":"Place in a bowl with onion, jalapeño, tomato, pepper and lime juice. Gently toss, then set aside for 5 minutes, mixing gently once.","duration":5,"images":[],"step":2},{"description":"Add avocado then serve! Sprinkle over salt, then add avocado, coriander and olive oil. Gently stir, then serve immediately with corn chips (see in post for other ideas).","images":[],"step":3},{"description":"Ceviche will be good for 20 minutes or so, then fish will start to overcook and firm up. Do not leave overnight (for food safety reasons).","duration":20,"images":[],"step":4}]', '["fish"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Asian influence","Mexican","South American"],"categories":["dietary","finger-food","fish-recipes","fresh-and-bright","gluten-free-recipes","iconic-dishes","low-calorie-recipes","mains","mexican-recipes","other","quick-and-easy","seafood-recipes","south-american-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a2772e7f577c', 'en', 'US', 'Mediterranean Brown Rice Salad', 'Recipe video above. This Brown Rice Salad looks way too healthy to taste as good as it does! The fresh dill and coriander/cilantro with the bright lemon dressing totally makes it. The perfectly cooked, nutty brown rice helps. Everything else is customisable.Serves 6 to 8 as a side, 4 as a meal. Keeps for 3 days. Exellent work lunch option, and serving for lunch with friends.', 'https://www.recipetineats.com/tachyon/2020/09/Brown-Rice-Salad_8.jpg', 15, 40, 55, 8, '[{"id": "ing_rice", "quantity": {"value": 450.0, "unit": "pack"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_tightly_packed_baby_rocket_arugula", "quantity": {"value": 0.04, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_dill", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.09, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.075, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_mustard", "quantity": {"value": 0.013, "unit": "jar of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_black_olive_slices", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_halloumi", "quantity": {"value": 200.0, "unit": "unit"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["3 cups cooked brown rice (, cooled but not cold)","2 tomatoes (, diced)","2 cucumbers (, diced (or 1 long English/continental cucumber))","1/2 red onion (, chopped (sub 2 stems green onion))","40g/ 4 cups tightly packed baby rocket/arugula (, roughly chopped (or baby spinach))","1/3 cup coriander/cilantro leaves (, roughly chopped (Note 2))","1/3 cup fresh dill leaves (, roughly chopped (Note 2))"],"purpose":"Salad (Note 1):"},{"ingredients":["3 tbsp lemon juice","5 tbsp extra virgin olive oil","1 garlic cloves (, minced using garlic press)","1/2 tsp Dijon mustard (Note 3)","3/4 tsp salt (, kosher/cooking salt (1/2 tsp table salt))","1/2 tsp black pepper"],"purpose":"Lemon Dressing:"},{"ingredients":["1/2 cup black olive slices","200g/7oz halloumi (, sliced then pan fried in a little olive oil until golden and crispy)","Other topping options: feta, parmesan, nuts (Note 4)"],"purpose":"Optional extras (pictured):"}]', '[{"description":"Place Dressing ingredients in a jar and shake well to combine.","images":[],"step":1},{"description":"Place Salad ingredients in a big bowl. Drizzle over Dressing, toss well.","images":[],"step":2},{"description":"Transfer to serving bowl. If using Halloumi, pile on top.","images":[],"step":3},{"description":"Serve!","images":[],"step":4}]', '["milk","mustard"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Mediterranean","Western"],"categories":["dietary","fresh-and-bright","gluten-free-recipes","low-calorie-recipes","rice-recipes","rice-side-dishes","salad-recipes-main-course","side-dishes","side-salads","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3a94444db743', 'en', 'US', 'Slow Roast Leg of Lamb', 'Recipe video above. A very forgiving, very easy way to roast a leg of lamb, where the meat is slow-cooked until it''s tender enough to pull it off the bone with tongs. It is not the blushing pink flesh carving sort (use this traditional Roast Lamb recipe if that''s what you''re after). Lamb leg is lean, so to slow cook it''s best to partially submerge in a flavoured liquid which keeps the flesh moist plus infuses with flavour. I''m using garlic and rosemary in this recipe - classic lamb flavours!**IMPORTANT** Lamb leg is lean so it should only be cooked for 1.5 hours until blushing pink & juicy (per this traditional Roast Lamb recipe) or slow cooked for 4.5 hrs until fall apart (this recipe). Anything in between is tough and not nice! For more roast lamb recipes, browse the recipe collection or take my Roast Lamb Matchmaker to find your perfect recipe!', 'https://www.recipetineats.com/tachyon/2020/04/Slow-Roasted-Lamb-Leg-featured-image.jpg', 15, 315, 330, 6, '[{"id": "ing_lamb", "quantity": {"value": 2.25, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_rosemary", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["2.25 kg / 4.5 lb leg of lamb (, bone in (or shoulder) (Note 1))","1 1/2 tsp cooking salt / kosher salt (double for flakes)","1/2 tsp black pepper","1 1/2 tbsp olive oil","1 whole garlic head (, unpeeled, cut in half horizontally)","1 onion (, quartered (unpeeled is fine))","2 rosemary sprigs (2 = whisper of rosemary flavour, 4 sprigs = stronger flavour)","3 cups beef stock/broth (, low sodium (or homemade))","2 cups water"]},{"ingredients":["4 tbsp plain flour (all-purpose flour)","1 cup water","Salt and pepper (, to taste)"],"purpose":"Gravy:"}]', '[{"description":"Season leg with salt and pepper, place upside down on garlic, onion and rosemary. Pour liquids in, drizzle with oil, cover with foil. Roast 4 1/2 hours at 170°C/335°F (150°C fan) until meat is pull-apart tender. Flip, return to oven 20 - 30 minutes at 200°C/390°F (180° fan) until well browned. Make gravy while resting.","images":[],"step":1},{"description":"Preheat oven to 170°C/335°F (150°C fan-forced).","images":[],"step":2},{"description":"Place garlic, onion and rosemary in a metal roasting pan.","images":[],"step":3},{"title":"Season lamb","description":"Place lamb leg right side up in the pan. (Note 2) Sprinkle the surface with half the salt and pepper and rub it in.","images":[],"step":4},{"description":"Turn lamb over and place it so it mostly sits on the garlic and onion. Sprinkle with remaining salt and pepper, rub it in. (Video helpful here)","images":[],"step":5},{"title":"Add liquids and cover","description":"Drizzle lamb with olive oil. Pour broth and water around the lamb - it won''t cover it, that''s ok, the lamb sinks into it. Cover with foil (don''t use a lid, you want a bit of liquid to steam out).","images":[],"step":6},{"title":"Slow roast","description":"Place in the oven and roast for 4 1/2 hours. (See Notes for roasting time table)","images":[],"step":7},{"title":"Check meat","description":"Remove from the oven, remove foil. Turn lamb over. Check it to ensure the meat is tender enough to pry a bit off easily with a fork. If not, return, covered, to oven.","images":[],"step":8},{"title":"Brown lamb","description":"Return uncovered lamb to the oven and roast for a further 40 minutes or until well browned all over. (Don''t increase the temperature as then it doesn''t brown as evenly)","images":[],"step":9},{"title":"Rest","description":"Remove lamb, spoon over pan juices generously. Transfer to serving platter, cover loosely with foil while you make the gravy (stays warm for 1 - 1 1/2 hours).","images":[],"step":10},{"title":"Skim fat","description":"Use a large spoon to skim off and discard some of the fat from the surface of the liquid.","images":[],"step":11},{"title":"Add flour","description":"Place pan on the stove on medium high. When the liquid bubbles, add flour. Use a whisk to mix it in - this may take a few minutes as the liquid reduces.","images":[],"step":12},{"title":"Add water","description":"Once it looks like sludge (see video), whisk in 1/2 - 1 cup of water until it becomes a gravy consistency to your taste. Adjust salt and pepper to taste - I rarely add extra salt.","images":[],"step":13},{"description":"Strain gravy into a bowl, pressing juices out of the onion etc. Pour gravy into jug.","images":[],"step":14},{"description":"The meat is tender so you will only need tongs to tear the meat off. Serve with gravy!","images":[],"step":15}]', '["gluten"]', '["high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","easter-mains","easter-recipes","gluten-free-recipes","iconic-dishes","lamb-recipes","main-dishes","roast-lamb","roasts","slow-cooked-fall-apart","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e90cafbc9909', 'en', 'US', 'Garlic Prawns (Shrimp!)', 'Recipe video above. Hands down, my favourite way to cook fresh prawns! Simple and fabulous, the 3 tips for top notch garlic prawns is to chop rather than use a mincer for the garlic (it splatters and burns on high heat), add the garlic partway through cooking (else it burns), and a splash of wine gives this a flavour edge as well as stopping the garlic from burning. Serves 2 - 3 as a main, 4 - 5 as a starter.', 'https://www.recipetineats.com/tachyon/2017/05/Garlic-Prawns_6.jpg', 10, 6, 16, 4, '[{"id": "ing_shrimp", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 40.0, "unit": "block of 250g"}}, {"id": "ing_wine", "quantity": {"value": 0.083, "unit": "bottle of 750ml"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["500g / 1lb prawns (shrimp) (, peeled and deveined, tail on (unpeeled weight 1kg/2lb, Note 1))","1/2 tsp cooking/koshfer salt","1/2 tsp black pepper","3 tbsp extra virgin olive oil (separated)","3 tsp finely minced garlic cloves (~ 4 cloves) (use knife, not crusher/mincer)"]},{"ingredients":["40g / 3 tbsp unsalted butter (, cut into 1.5cm / 1/2\" cubes (Note 2))","1/4 cup chardonnay or other dry white wine (Note 3)","1 tbsp lemon juice","1 tbsp parsley, finely chopped (garnish)"],"purpose":"Garlic butter sauce"},{"ingredients":["Lemon wedges","Bread for mopping!"],"purpose":"Serving"}]', '[{"title":"Marinade","description":"Place the prawns, 1 tablespoon olive oil and pepper in bowl. Gently toss then set aside for 20 minutes (no longer else the prawns will sweat from the salt),.","duration":20,"images":[],"step":1},{"description":"Cooking","images":[],"step":2},{"title":"Sear in batches","description":"Heat 1 tablespoon olive oil in a large non-stick frying pan over high heat. Place half the prawns in the pan then sear each side for just 45 seconds, using tongs to turn.","images":[],"step":3},{"title":"Remove & repeat","description":"Remove prawns onto a plate, heat the last 1 tablespoon of oil and cook each side for 45 seconds.","duration":0.75,"images":[],"step":4},{"description":"Return first batch of prawns back into pan.","images":[],"step":5},{"title":"Garlic","description":"Add garlic then stir for 30 seconds.","duration":0.5,"images":[],"step":6},{"title":"Add wine","description":"it will sizzle and be steamy! Stir, scraping the bottom of the pan, until wine mostly evaporates - around 30 seconds.","images":[],"step":7},{"title":"Butter & lemon","description":"Scatter butter across pan, add lemon juice. Swirl butter around the pan until it melts, then toss through the parsley.","images":[],"step":8},{"title":"Serve","description":"Transfer the prawns and all the butter sauce onto a serving plate. Serve with extra lemon wedges. Bread for mopping is essential - try this simple Crusty Artisan Bread!","images":[],"step":9}]', '["gluten","milk","shellfish"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner","snack"],"cuisine":["Western"],"categories":["dietary","dinner-tonight","easter-mains-fish-seafood","gluten-free-recipes","main-dishes","prawns-shrimp","quick-and-easy","seafood-recipes","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_156146728eec', 'en', 'US', 'Leek and Potato Soup', 'Recipe video above. Thick and creamy Leek and Potato Soup, a French classic. Few ingredients, prepared well, and it''s just so enjoyable to eat. TOP TIP: Do not over blitz the soup, it activates the starch in the potato and will give your soup an unpleasantly sticky mouthfeel. This is a mistake commonly made in recipes that instruct to blitz, blitz, blitz!', 'https://www.recipetineats.com/tachyon/2015/10/Potato-Leek-Soup_5.jpg', 10, 35, 40, 5, '[{"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_eek", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 1.5, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 2.0, "unit": "loaf"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chives", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}]', '[{"ingredients":["2 tbsp (30g) butter","2 garlic cloves (, large, finely minced)","3 leeks (, white and pale green parts only sliced thinly (about 2 cups) (Note 1))","1 kg / 2lb potatoes (Sebago/Russet/Maris Piper) (, peeled a diced into 1\"/2.5cm cubes (Note 2))","1.5 litre / 1.5 qt chicken or vegetable stock (, low sodium (6 cups))","3/4 cup cream (, heavy/thickened (sub milk))","1 tsp cooking salt / kosher salt (table salt - reduce by 25%)","1/2 tsp black pepper"]},{"ingredients":["2 thick slices bread (, torn into crouton size pieces)","1 tbsp melted butter, or olive oil spray","Salt"],"purpose":"Croutons"},{"ingredients":["Chives (, finely chopped)","Extra cream (, for garnish)"],"purpose":"Garnish"}]', '[{"title":"Sauté","description":"Melt butter in a large pot over medium heat. Add garlic and leek and sauté for 7 minutes until soft and sweet.","duration":7,"images":[],"step":1},{"title":"Simmer 25 minutes","description":"Add potatoes and broth. Turn heat up and bring to simmer, then place lid on and lower heat so it''s simmering gently. Simmer for 25 minutes or until potato is very soft and almost falling apart.","duration":25,"images":[],"step":2},{"title":"Minimal blitz","description":"Turn the stove off and puree with a stick blender until JUST smooth. Do not over puree (Note 3).","images":[],"step":3},{"title":"Season","description":"Add salt and pepper, then stir through cream.","images":[],"step":4},{"description":"Serve, drizzled with cream and sprinkled with chives and croutons.","images":[],"step":5},{"description":"Preheat oven to 180°C/350°F (160°C fan-forced). Drizzle bread with melted butter (or spray with oil). Bake for 5 minutes or until golden and crunchy. Sprinkle with a pinch of salt while hot!","duration":5,"images":[],"step":6}]', '["gluten","milk"]', '["low_calorie"]', '{"mealType":["main_course"],"cuisine":["French"],"categories":["dietary","dinner-tonight","gluten-free-recipes","low-calorie-recipes","main-dishes","potato-recipes","quick-and-easy","soup-recipes","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_83ce9102cb6e', 'en', 'US', '45 Cal Creamy HEALTHY Soup!', 'Recipe video above. {Low Cal, GF, low carb} My secret method to make a really low calorie creamy soup that is seriously delicious! Using boiled PEELED zucchini, simmer until soft then blitz into what looks like everybody''s favourite calorie-laden creamy broths.....but it''s guilt free. Zucchini is ideal - purees smooth, neutral flavour that''s easily disguisable. It doesn''t taste like zucchini - just a savoury creamy soup. I''ve used it to make a healthy version of homemade Cream of Chicken Soup. But imagine the possibilies - use it in place of any soup that has a creamy white broth!', 'https://www.recipetineats.com/tachyon/2020/01/Super-Skinny-Cream-of-Chicken-Soup_6.jpg', 10, 20, 30, 5, '[{"id": "ing_zucchini", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 500.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 500.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 225.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 4.5, "unit": "head"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_frozen_peas", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["700g/ 1.2 lb zucchinis ((4 largish), peeled and cut into 1.5cm / 3/5\" slices)","1/2 large onion (, roughly chopped (brown, white, yellow))","2 garlic cloves (, whole)","2 cups (500 ml) chicken broth (or veg broth)","2 cups (500 ml) water","1/2 tsp each garlic and onion powder (or 1 tsp of one of them)","1/4 tsp black pepper","1 cup (250 ml) 0% fat milk (or other milk of choice)"],"purpose":"Healthy Creamy Soup Broth:"},{"ingredients":["1 tbsp (15g) butter or olive oil","2 garlic cloves (, minced)","1/2 large onion (, finely chopped)","1.5 cups carrot (, peeled and finely diced)","1.5 cups celery (, finely chopped)","1 small red capsicum/bell pepper (, finely chopped)","1.5 cups cooked chicken breast (, diced)","3/4 cup frozen peas"],"purpose":"Soup Add Ins:"},{"ingredients":["Fresh thyme (high recommended, or sub chives)"],"purpose":"Garnish:"}]', '[{"description":"Healthy Creamy Broth:","images":[],"step":1},{"description":"Place all Broth ingredients EXCEPT milk into a pot, cover with lid and bring to energetic simmer over medium high heat.","images":[],"step":2},{"description":"Lower to medium and simmer for 15 minutes until zucchinis is very soft.","duration":15,"images":[],"step":3},{"description":"Remove from heat, add milk. Use a handheld blender to blitz until smooth. Add salt to taste. Marvel at creamy broth with so few calories!","images":[],"step":4},{"description":"Healthy Cream of Chicken Soup:","images":[],"step":5},{"description":"Melt butter in a pot or large saucepan over medium heat.","images":[],"step":6},{"description":"Add garlic, onion, carrot and celery. Cook for 3 minutes, then add capsicum. Cook for another 2 minutes until onion is translucent and sweet.","duration":3,"images":[],"step":7},{"description":"Add Broth, chicken and peas. Bring to gentle simmer for just 2 to 3 minutes or until peas are cooked.","images":[],"step":8},{"description":"Taste and adjust salt and pepper.","images":[],"step":9},{"description":"Ladle into bowls, sprinkle with a pinch of fresh thyme leaves. Devour, and marvel at how such a creamy, totally delicious bowl of soup has so few calories!!","images":[],"step":10}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","gluten-free-recipes","low-calorie-recipes","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_31e4a72ef630', 'en', 'US', 'Fish Fingers', 'Recipe video above. Fish Fingers so perfectly golden and crunchy it''s hard to believe they''re BAKED rather than fried! Toasting the breadcrumbs makes all the difference because fish cooks in the oven so much faster than it takes to brown the breadcrumbs. BONUS: This is a mess free breading technique!', 'https://www.recipetineats.com/tachyon/2020/01/Fish-Fingers_5.jpg', 15, 15, 30, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_bread", "quantity": {"value": 0.281, "unit": "loaf"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.037, "unit": "jar of 400g"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_tartare_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["600g / 1.2lb white fish fillets (, patted dry (Note 1))","Oil spray (olive oil or any plain)"]},{"ingredients":["1 1/2 cups (75g) panko breadcrumbs (Note 2)","1/4 cup (25g) parmesan","2 tsp paprika (, optional)","1/2 tsp salt and pepper (, each)"],"purpose":"Crumb"},{"ingredients":["1 egg","1 tbsp mayonnaise","2 tbsp flour","1/4 tsp salt and pepper (, each)"],"purpose":"Batter"},{"ingredients":["Tartare sauce or other seafood dipping sauce","Lemon wedges","Finely chopped chives or parsley (, garnish (optional))"],"purpose":"Serving"}]', '[{"description":"Preheat oven to 180°C / 350°F.","images":[],"step":1},{"title":"Toast breadcrumbs","description":"Spread breadcrumbs on tray. Spray with oil, bake 4 minutes until golden. Transfer toasted breadcrumbs into bowl, add remaining Crumb ingredients and mix.","images":[],"step":2},{"description":"Increase oven to 220°C / 425°F (fan 200°C). Spray used tray with oil.","images":[],"step":3},{"title":"Batter","description":"Mix Batter ingredients in a separate bowl.","images":[],"step":4},{"description":"Cut the fish into strips 1.5 x 11 cm / 3/5 x 4.5\" (they shink 30% in length).","images":[],"step":5},{"description":"Place fish in Batter, gently mix with rubber spatula to coat. Do not leave sitting around (will become watery), coat immediately.","images":[],"step":6},{"title":"Breading","description":"Pick up fish with tongs, place in breadcrumbs. Spoon over crumb, use fingers to press to adhere.","images":[],"step":7},{"title":"Baking","description":"Transfer to baking tray. Spray with oil, bake 13 minutes or until crispy on the outside.","images":[],"step":8},{"description":"Serve immediately with lemon wedges, Tartare Sauce or other Sauce of choice - see here for recipes, any of these great for fish fingers! Also Note 3 for few quick sauce options.","images":[],"step":9}]', '["egg","fish","gluten","milk"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","fish-recipes","low-calorie-recipes","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e6c8fbb55997', 'en', 'US', 'Cucumber Canapés with Smoked Salmon Mousse', 'Recipe video above. Fabulous finger food, fast to make vast quantities rather than the usual fiddly assembly! Happens to be HEALTHY. By far the most popular finger food I''ve served at gatherings in recent years - people love the freshness of the cucumber with the richness of the smoked salmon mousse! (Which is just a fancy name for pureed smoked salmon dip LOL!)', 'https://www.recipetineats.com/tachyon/2020/01/Cucumber-Canapes-with-Smoked-Salmon-Mousse_4.jpg', 20, 0, 20, 40, '[{"id": "ing_salmon_fillets", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_cream_cheese", "quantity": {"value": 150.0, "unit": "block of 250g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.12, "unit": "tub of 250g"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.075, "unit": "jar of 400g"}}, {"id": "ing_dill", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_cucumber", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_dill", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}]', '[{"ingredients":["150g / 5 oz smoked salmon (Note 1)","150g / 5 oz Cream Cheese (, softened (I use Philadelphia, Note 2))","2 tbsp/ 30g sour cream","2 tbsp/ 40g mayonnaise","1/3 cup fresh dill (, roughly chopped (sub chives))","1 garlic clove (, minced)","2 tsp lemon zest (1 lemon)","2 tbsp lemon juice","1/4 tsp salt and pepper (, each (Note 3))"],"purpose":"Smoked Salmon Mousse:"},{"ingredients":["3 long cucumbers (Telegraph / English) (OR 6 standard cucumbers (Note 4))"],"purpose":"Cucumber:"},{"ingredients":["Extra dill sprigs","Lemon slices (, for serving)"],"purpose":"Garnish:"}]', '[{"description":"Place Salmon Mousse ingredients in a food processor. Blitz until completely smooth, scraping down sides as needed.","images":[],"step":1},{"description":"Fit piping bag with wide star tip nozzle (1.5-2cm / 0.6 - 0.75\" wide), then transfer Mousse into piping bag. Refrigerate for 5 hours until firmed.","images":[],"step":2},{"description":"Cut into 1.5cm thick / 0.6\" slices.","images":[],"step":3},{"description":"Use a small melon baller or teaspoon to scoop a well out.","images":[],"step":4},{"description":"Pipe mousse into cucumbers. Top with dill and serve immediately.","images":[],"step":5}]', '["fish","milk"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["snack"],"cuisine":["Western"],"categories":["dietary","finger-food","gluten-free-recipes","low-calorie-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6a446cd3d9f5', 'en', 'US', 'Brazilian Fish Stew (Moqueca Baiana)', 'Recipe video above. A traditional Brazilian dish in a delicately flavoured coconut base broth with terrific depth of flavour that belies the relatively short ingredient list! The broth is quite refreshing and not too rich, unlike many strong flavoured, rich coconut based curries. I made this just using fish but it is also made as a seafood stew with prawns and calamari.', 'https://www.recipetineats.com/tachyon/2015/09/Brazilian-Fish-Stew_6.jpg', 10, 25, 35, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_cumin", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.992, "unit": "can of 400ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.9, "unit": "bunch"}}]', '[{"ingredients":["1 lb / 500g firm white fish fillet (, no skin, cut into 1\"/2.5cm cubes (Note 1))","1 tbsp lime juice","1/4 tsp salt","Black pepper","1 tbsp olive oil"],"purpose":"Fish"},{"ingredients":["1 1/2 tbsp olive oil or coconut oil (Note 4)","2 garlic cloves (, minced)","1 small onion (, finely diced (brown, yellow or white))","1 red capsicum / bell pepper ((large), halved and sliced)","1 1/2 tsp sugar (any)","1 tbsp cumin powder","1 tbsp paprika","1 tsp cayenne pepper (optional)","1/2 tsp salt","14 oz / 400ml coconut milk (full fat best, Note 2)","14 oz / 400ml canned crushed tomatoes","1 cup fish broth/stock (or chicken or vegetable, Note 3)"],"purpose":"Broth"},{"ingredients":["1 - 2 tbsp lime juice (, plus more for serving)","3 tbsp roughly chopped fresh cilantro / coriander (, plus more for serving)"],"purpose":"Finishes"}]', '[{"description":"Combine the fish, lime juice, oil, salt and pepper in a bowl. Cover with cling wrap and refrigerate for 20 minutes.","duration":20,"images":[],"step":1},{"description":"Heat the 1 tbsp olive oil in a large skillet over high heat. Add the fish and cook until just cooked through and light golden brown. Remove from the skillet and set aside.","images":[],"step":2},{"description":"Reduce the stove to medium high and heat 1 1/2 tbsp olive oil in the same skillet. Add the garlic and onion and cook for 1 1/2 minutes or until the onion is starting to become translucent.","images":[],"step":3},{"description":"Add the bell peppers and cook for 2 minutes.","duration":2,"images":[],"step":4},{"description":"Add the remaining Broth ingredients. Bring to simmer, then turn down to medium. Cook for 15 to 20 minutes or until it thickens. Adjust salt and pepper to taste.","duration":17.5,"images":[],"step":5},{"title":"Return the fish to the broth to reheat","description":"about 2 minutes.","images":[],"step":6},{"description":"Stir through lime juice.","images":[],"step":7},{"description":"Garnish with cilantro/coriander and serve with rice or Lime Rice. For a low carb option, try Cauliflower Rice!","images":[],"step":8}]', '["fish"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Brazilian"],"categories":["dietary","dinner-tonight","easter-mains-fish-seafood","fish-recipes","gluten-free-recipes","main-dishes","seafood-recipes","south-american-recipes","stews","sunday-supper"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_448ed42d7e36', 'en', 'US', 'Juicy Slow Cooker Turkey Breast', 'RECIPE VIDEO above. I''ve tried a handful of other methods over the years. This has produced the juiciest turkey breast by far, without brining the breast in advance. Plus slow cooking is very forgiving so you don''t need to be spot on with the cooking time. SCALE RECIPE by moving slider on Servings to adjust for different turkey weights. Complete your feast - browse the new Thanksgiving Recipe Index!', 'https://www.recipetineats.com/tachyon/2016/11/Slow-Cooker-Turkey-Breast_1a.jpg', 15, 480, 495, 8, '[{"id": "ing_turkey_breast_skin_on_bone_in_or_boneless", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.5, "unit": "L"}}, {"id": "ing_chicken_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}]', '[{"ingredients":["2 kg / 4 lb turkey breast, skin on, bone in or boneless (if using frozen, thaw it) (Note 1)","1 head of garlic, cut in half horizontally","1 onion (brown, yellow or white), unpeeled, cut in half","5 sprigs of thyme (or 2 tsp dried thyme leaves)"]},{"ingredients":["1 1/2 tsp garlic powder","1 1/2 tsp onion powder","1 tsp paprika","2 tsp salt","5 grinds of black pepper","1 1/2 - 2 tbsp olive oil"],"purpose":"Rub"},{"ingredients":["Chicken stock/broth (or water), for topping up liquid (see Gravy step 1)","4 tbsp / 50g butter","1/4 cup / 35g flour","Salt and pepper"],"purpose":"Gravy"}]', '[{"description":"Place Rub ingredients in a bowl and mix to combine, it should be a wet paste.","images":[],"step":1},{"description":"Pat the turkey dry all over with paper towels. Slather with the Rub, using most for the side and top.","images":[],"step":2},{"description":"Place the garlic, onion and thyme face down in the slow cooker. Place the turkey breast on top so it is elevated.","images":[],"step":3},{"description":"Slow Cook on LOW for 6 hours (do not use high) or until internal temperature reads 165F/75C when thermometer is inserted into the middle. Check internal temperature at 5 hours if you can. (To roast, follow this recipe).","images":[],"step":4},{"description":"Remove turkey from the slow cooker (do not leave in slow cooker on Warm setting) and let it rest for 20 minutes before crisping the skin.","duration":20,"images":[],"step":5},{"description":"Preheat gril/broiler to high.","images":[],"step":6},{"description":"Place an oven shelf 30cm / 1 foot from the heat source.","images":[],"step":7},{"description":"Remove turkey breast from the slow cooker into a heatproof serving dish.","images":[],"step":8},{"description":"Place on the oven shelf and broil for 3 to 5 minutes until the skin is crispy. Keep an eye on it - it browns very quickly!","duration":4,"images":[],"step":9},{"description":"Serve immediately with gravy on the side.","images":[],"step":10},{"description":"Strain the liquid into a measuring jug, squishing the garlic etc to extract all the flavour. If you are short of 2 cups, top up with chicken broth (I usually get 2 cups of liquid from a 4 lb / 2 kg turkey breast).","images":[],"step":11},{"description":"Melt butter in a saucepan over medium heat. Add flour and mix to combine. Pour about 1/2 cup of liquid into the flour mixture and mix until it forms a paste. Slowly add remaining liquid, stirring as your go. Use a whisk if required to make the gravy smooth. Simmer until thickened - take it off before it is as thick as you want because it will continue to thicken.","images":[],"step":12},{"description":"Season to taste with salt and pepper. Serve with turkey.","images":[],"step":13}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Christmas","Festive"],"categories":["dietary","easter-mains","easter-recipes","gluten-free-recipes","main-dishes","most-popular","quick-and-easy","slow-cooker-recipes","turkey-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2112cd9cfad7', 'en', 'US', 'Pizza Stuffed Mushrooms', 'Recipe video above. This is the sort of recipe that you can absolutely make your own with your favourite pizza toppings! TIP: avoid watery filling by cutting a small cross in the cap of the mushroom to let excess water drain out as it bakes. Serve as a light meal, or serve 2 as a main meal.', 'https://www.recipetineats.com/tachyon/2019/07/Pizza-Stuffed-Mushrooms_0.jpg', 10, 20, 30, 5, '[{"id": "ing_mushroom", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_pizza_sauce", "quantity": {"value": 100.0, "unit": "bottle"}}, {"id": "ing_salami", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.25, "unit": "pack of 1kg"}}, {"id": "ing_black_olive_slices", "quantity": {"value": 0.333, "unit": "unit"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.8, "unit": "pack of 125g"}}]', '[{"ingredients":["5 large mushrooms (, 10cm/4\" wide (portobello, flat mushrooms etc, Note 1))","2 tbsp olive oil","Salt and pepper","2/3 cup pizza sauce (I use store bought)","100g/ 3.5 oz salami slices (, chopped)","1/4 red onion (, finely chopped)","1/3 cup black olive slices","1 cup (100g) mozzarella cheese (, shredded )"]}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Carefully break or cut the stems off the mushrooms.","images":[],"step":2},{"description":"Chop stems (will use as filling).","images":[],"step":3},{"description":"Place mushrooms cap side up. Using a small, sharp, THIN knife, cut a small cross in the mushroom, taking great care not to split the mushroom (to drain excess water, Note 2)","images":[],"step":4},{"description":"Brush the tops with oil, then quickly sprinkle on salt and pepper (be fast so it sticks!)","images":[],"step":5},{"description":"Flip then lightly dab the inside with remaining oil, sprinkle with salt and pepper.","images":[],"step":6},{"description":"Fill mushrooms with pizza sauce, sprinkle with chopped mushroom, onion, half salami and half olives.","images":[],"step":7},{"title":"Bake 1","description":"Bake 10 minutes, remove from oven.","images":[],"step":8},{"description":"Top with cheese, remaining salami and olives.","images":[],"step":9},{"title":"Bake 2","description":"Bake further 10 minutes until cheese is melted. Serve immediately!","images":[],"step":10},{"description":"Preheat BBQ to medium high.","images":[],"step":11},{"title":"Follow above steps in closed BBQ","description":"10 minutes for Bake 1, then 5 - 8 minutes for Bake 2.","images":[],"step":12}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","dinner-tonight","low-calorie-recipes","mushroom-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a5413fbde8c0', 'en', 'US', 'Oven Baked Sausages with Potatoes, Vegetable AND Gravy!', 'Recipe VIDEO above. Cooking sausages in the oven with vegetables and gravy is a terrific quick dinner idea that takes mere minutes to assemble! The sausages get nicely browned, the vegetables tender, and a flavour packed gravy. Kind of like making a stew!', 'https://www.recipetineats.com/tachyon/2018/03/Sausage-Bake_4-1.jpg', 15, 45, 60, 4, '[{"id": "ing_potato", "quantity": {"value": 700.0, "unit": "bag of 2kg"}}, {"id": "ing_carrot", "quantity": {"value": 3.0, "unit": "pack of 1kg"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_sausages", "quantity": {"value": 8.0, "unit": "pack of 500g"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.3, "unit": "kg"}}]', '[{"ingredients":["700g / 1.4 lb baby potatoes (, halved)","3 carrots (, peeled and cut into 2\"/5cm pieces)","2 red onions (, each cut into 8 wedges)","2 garlic cloves, minced","2 tbsp olive oil","2 tsp dried thyme","1 tsp dried oregano","Salt and pepper"],"purpose":"Vegetables"},{"ingredients":["8 - 10 sausages (500-700g / 1-1.4lb) (Note 2)","Oil spray (optional)"],"purpose":"Sausages"},{"ingredients":["2 tbsp / 30g melted butter, unsalted","2 1/2 tbsp flour (plain / all purpose)","2 cups / 500 ml beef broth (or chicken) ( (Note 3))","Fresh thyme (, for garnish (optional))"],"purpose":"Gravy"}]', '[{"description":"Preheat oven to 200C/390F (standard) or 180C/350F (fan / convection).","images":[],"step":1},{"description":"Place Vegetable ingredients in a large bowl. Toss well to coat.","images":[],"step":2},{"description":"Add sausages and toss briefly.","images":[],"step":3},{"description":"Transfer into roasting pan. Pan should be of a size so the vegetables are stacked about 2 deep - see photos and video. Rearrange sausages so they are on top.","images":[],"step":4},{"description":"In the same bowl used for the vegetables, add butter and flour. Whisk.","images":[],"step":5},{"description":"Add a bit of beef broth and whisk, then whisk in remaining broth. (Don''t worry if you end up with some floating butter bits)","images":[],"step":6},{"description":"Pour down the side of the pan (don''t pour over the sausages or veggies).","images":[],"step":7},{"title":"Optional: Spray sausages with oil","description":"browns slightly better (especially lean sausages).","images":[],"step":8},{"description":"Bake 25 minutes. Turn sausages. Spray again with oil (optional) then bake for a further 25 minutes or until sausages are browned and potatoes are soft.","images":[],"step":9},{"description":"Serve Sausages and Vegetables with Gravy on top, garnished with fresh thyme leaves if desired. (See notes for Gravy thickness adjustment)","images":[],"step":10}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","dinner-tonight","gluten-free-recipes","main-dishes","one-pot-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d51777d8ab91', 'en', 'US', '25 BEST Party Food Recipes!', 'My top 25 Party Food Recipes! Here''s a printable list with links to the recipes listed in this post (so you don''t have to print out this whole post with all the photos :) ) Also browse the full Party Recipes collection!', 'https://www.recipetineats.com/tachyon/2014/12/Party-Food-Recipes-Cover-Image.jpg', 15, 0, 15, 8, '[{"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_cocktail_meatballs", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_cream_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_salmon_fillets", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_corn", "quantity": {"value": 0.003, "unit": "can of 400g"}}, {"id": "ing_shrimp", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chargrilled_vegetable_platter", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_shrimp", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["Vietnamese Rice Paper Rolls","Cocktail Meatballs","Cheese & Garlic Crack Bread","Crispy Parmesan Roasted Potatoes","Salami Cream Cheese Roll","Smoked Salmon Appetizer Bites","Cheese and Bacon Potato Skins","Sausage Rolls","Stay Crispy Movie Popcorn","Prawn Dipping Sauces","Chargrilled Vegetable Platter","Coconut Prawns/Shrimp with Thai Mango Dipping Sauce"],"purpose":"BITES & NIBBLES:"}]', '[{"description":"Queso Dip (Mexican Cheese Dip)","images":[],"step":1},{"description":"French Onion Dip (also see Soup Mix dip version, retro classic!)","images":[],"step":2},{"description":"Festive Italian Cheese Log","images":[],"step":3},{"description":"Spinach Artichoke Dip","images":[],"step":4},{"description":"Smoked Salmon Dip","images":[],"step":5},{"description":"Restaurant Style Salsa","images":[],"step":6},{"title":"Crudites Platter","description":"see Hummus recipe","images":[],"step":7},{"description":"2 Minute Festive Brie","images":[],"step":8},{"description":"Herb Chilli Feta","images":[],"step":9},{"description":"Cheese Truffles","images":[],"step":10},{"description":"Crispy Baked Buffalo Wings","images":[],"step":11},{"description":"Crispy Baked Wings with Honey Garlic Sauce","images":[],"step":12},{"description":"Sticky Chinese Chicken Wings","images":[],"step":13}]', '["fish","gluten","milk","shellfish"]', '[]', '{"mealType":["snack"],"cuisine":[],"categories":["dietary","finger-food","gluten-free-recipes","most-popular","quick-and-easy","super-bowl-party-food","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b8f916f758ac', 'en', 'US', 'Hot Corn Dip', 'Recipe video above. Bubbly, creamy and bursting with flavour! The secret that makes this so good is to saute the corn! Serve with corn chips, crackers or even veggie sticks.', 'https://www.recipetineats.com/tachyon/2018/02/Hot-Corn-Dip_1.jpg', 10, 45, 55, 12, '[{"id": "ing_corn", "quantity": {"value": 4.0, "unit": "can of 400g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.02, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_cheese", "quantity": {"value": 250.0, "unit": "block of 250g"}}, {"id": "ing_jalapeno", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_cream_cheese", "quantity": {"value": 250.0, "unit": "block of 250g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.45, "unit": "tub of 250g"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.281, "unit": "jar of 400g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 1.15, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.15, "unit": "pack of 100g"}}, {"id": "ing_corn", "quantity": {"value": 4.0, "unit": "can of 400g"}}]', '[{"ingredients":["4 corn on the cob ((large, or 5 smaller), or 500g / 1 lb frozen corn)","4 tsp olive oil","2 tbsp / 30 g butter","2 garlic cloves (, minced)","1 large red capcsicum / bell pepper (, diced)","1 large green capsicum / bell pepper (, diced)","1 red onion (, finely chopped)","250 g / 8 oz shredded Monterey Jack cheese or other cheese of choice (Note 1)","1 jalapeno (, finely chopped)","250 g / 8 oz cream cheese (, softened)","3/4 cup / 170g sour cream","3/4 cup / 175g mayonnaise","3/4 tsp salt","115g / 4 oz can green chillies, chopped (Note 2)","3 shallots / scallions (, finely sliced)"]},{"ingredients":["Coriander / cilantro (, chopped)","Green chillies or jalapeño (, sliced)","Sautéed corn"],"purpose":"Garnishes, optional:"}]', '[{"description":"Preheat oven to 160C/320F.","images":[],"step":1},{"title":"Cut the corn off the cob. Tip","description":"Use bundt pan or ramekin. in large bowl, see video. If using frozen corn, no need to thaw.","images":[],"step":2},{"description":"Melt 1 tbsp butter then add 2 tsp oil in a skillet over high heat. Add half the corn and half the garlic. Cook, stirring (or tossing!) for 3 minutes or until corn is golden (golden = better flavour). Transfer corn to bowl, repeat with remaining corn.","duration":3,"images":[],"step":3},{"description":"If the skillet looks dry, add a touch of oil. Add both capsicums and onion, cook for 2 minutes until softened. Add to bowl with corn.","duration":2,"images":[],"step":4},{"description":"Add half the cheese into the bowl, then all the remaining ingredients. Mix, transfer to baking dish.","images":[],"step":5},{"description":"Top with remaining cheese. Bake 30 minutes or until golden and bubbly on top.","images":[],"step":6},{"description":"Top with garnishes if desired. Serve hot with corn chips!","images":[],"step":7}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["snack"],"cuisine":[],"categories":["dietary","dip-recipes","gluten-free-recipes","quick-and-easy","super-bowl-party-food","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_508c947b4fc0', 'en', 'US', 'Easy Classic Cranberry Sauce', 'Recipe video above. A classic, easy cranberry sauce recipe for your turkey centrepiece. Store bought tastes nothing like this homemade version! The touch of lemon zest is what makes that little extra difference. Adjust the sweetness to your taste. This to me has a nice balance of sweet / tart, without being overly sweet like jam. Easy to adjust thickness with more water so don''t worry if it gets too thick when it cools. Makes almost 3 cups.', 'https://www.recipetineats.com/tachyon/2015/11/Easy-Classic-Cranberry-Sauce_1.jpg', 2, 20, 22, 10, '[{"id": "ing_bag_frozen_cranberries", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.001, "unit": "net of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["16 oz / 500g bag frozen cranberries (or fresh)","1 cup white sugar","1/3 cup water","1/8 tsp lemon zest","Pinch of salt"]}]', '[{"description":"Tip the cranberries in a saucepan set over medium low heat. Remove a heaped 1/2 cup of cranberries and set aside.","images":[],"step":1},{"description":"Add remaining ingredients. Cook for 5 minutes or until sugar is dissolved.","duration":5,"images":[],"step":2},{"description":"Increase heat to medium high. Cook for 10 minutes or until most of the cranberries have burst and the liquid is syrupy.","duration":10,"images":[],"step":3},{"description":"Reduce heat to low, stir through reserved cranberries. Adjust sweetness to your taste with more sugar and add a pinch of salt.","images":[],"step":4},{"description":"Allow to cool and store in the fridge for up to 3 weeks. The sauce will continue to thicken as it cools. Best served at room temperature or warm. Serve with a juicy Roast Turkey - or Slow Cooker Turkey Breast or Roasted Breast.","images":[],"step":5}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["dietary","gluten-free-recipes","quick-and-easy","side-dishes","turkey-recipes","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b76c889202ce', 'en', 'US', 'Creamy Vegetable Soup with Noodles (No cream!)', 'Recipe video above. A cream cream-less soup with lots and lots of fresh veggies, plus noodles! Use 7 - 8 cups of diced vegetables of choice, including onion. If making ahead or you know you''ll have leftovers, cook the pasta separately and place in the bowl, then ladle over soup (because noodles left in soup becomes bloated and overly soft). Make it Gluten Free by using GF pasta and cornflour sub to thicken soup (Note 2).', 'https://www.recipetineats.com/tachyon/2018/09/Cream-of-Vegetable-Soup-with-Noodles_1a.jpg', 10, 20, 30, 4, '[{"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_vegeta", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.4, "unit": "pack of 500g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_steak", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}]', '[{"ingredients":["50g (3 tbsp) butter (, unsalted)","2 garlic cloves (, minced)","1/2 onion (, finely chopped)","1 tsp dried thyme","1/3 cup (70g) flour (Note 2 cornflour/cornstarch GF)","3 cups (750 ml) milk (, any (I use low fat))","2 cups (500 ml) vegetable or chicken broth (, low sodium)","1 cup (250 ml) water","3 tsp Vegeta or other stock powder (Note 1)","200g / 7oz linguine or other pasta (, broken into 4 pieces)","Salt and pepper to taste"]},{"ingredients":["2 carrots (, diced)","2 celery ribs (, diced)","1 red capsicum/bell pepper (, diced)","1 cup corn kernels (, frozen or canned drained)","1 cup frozen peas"],"purpose":"Vegetables (sub 8 cups any diced veg):"},{"ingredients":["Fresh thyme leaves"],"purpose":"Optional garnish:"}]', '[{"description":"Melt butter in a large pot over medium high heat. Add garlic and onion, cook for 2 minutes. Then add carrot and celery. Cook for a further 2 minutes, then add capsicum and cook for another 1 minute.","duration":2,"images":[],"step":1},{"description":"Add flour and mix, cook for 1 minute.","duration":1,"images":[],"step":2},{"description":"Add about half the broth and mix. Once flour is incorporated into the broth, add remaining broth, milk, water, dried thyme, Vegeta and pepper. Mix, then add corn and peas.","images":[],"step":3},{"description":"Bring to simmer then lower heat slightly.","images":[],"step":4},{"description":"Break pasta into 4 pieces and add into pot. Cook for 10 minutes or until pasta is just cooked. Adjust salt and pepper to taste.","duration":10,"images":[],"step":5},{"description":"Ladle into bowls and serve, garnished with a tiny sprinkle of fresh thyme leaves if desired.","images":[],"step":6}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","dinner-tonight","gluten-free-recipes","main-dishes","quick-and-easy","soup-recipes","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9a05a24052e5', 'en', 'US', 'Vegetable Pasta - One Pot!', 'Recipe video above. A quick healthy dinner with more veg and less pasta, all made in one pot! For a lower cal option, skip the cheese and serve with parmesan sprinkled on top. Workflow: Get the onion cooking while you prep the other ingredients.', 'https://www.recipetineats.com/tachyon/2018/09/One-Pot-Vegetable-Pasta_3.jpg', 5, 15, 20, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_zucchini", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_broccoli", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_italian_herb_mix", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","1 onion (, finely chopped)","2 zucchinis* (, halved lengthwise and cut into sliced 0.8cm / 1/3\" slices)","1 red capsicum/bell pepper* (, halved and sliced)","1 cup corn* (frozen or canned)","1 broccoli* (, broken into bite size florets)","250g/ 0.5lb ziti/penne (, or other short pasta (Note 1))","800 g / 28 oz crushed tomato","1.5 cups / 375 ml vegetable or chicken broth","2 tbsp tomato paste","1 tbsp Italian herb mix (or other dried herbs)","1 tsp garlic powder","1/2 tsp red pepper flakes (chilli flakes, adjust spiciness to taste)","1.5 tsp salt","0.5 tsp black pepper"]},{"ingredients":["1.5 cups shredded cheese of choice (Cheddar, tasty, Monterey Jack etc)"],"purpose":"Optional:"},{"ingredients":["Finely chopped parsley (optional)","Parmesan (if not using cheese)"],"purpose":"To serve:"}]', '[{"description":"Heat oil in a large pot over medium. Add garlic and onion - cook slowly for 3 to 4 minutes until onion is translucent and sweet.","duration":3.5,"images":[],"step":1},{"description":"Turn heat up to medium high, add zucchini and capsicum. Cook 1 1/2 minutes.","images":[],"step":2},{"description":"Add remaining ingredients EXCEPT pasta and broccoli. Stir until tomato paste dissolves.","images":[],"step":3},{"description":"When liquid starts bubbling, lower heat to medium, add pasta and stir. Top with broccoli, push in.","images":[],"step":4},{"description":"Place lid on and cook for 5 minutes.","duration":5,"images":[],"step":5},{"description":"Remove lid. Cook for another 3 to 4 minutes, stirring frequently, until pasta is almost cooked through and most of the liquid has been absorbed by the pasta.","images":[],"step":6},{"description":"Stir through half the cheese (if using). Adjust salt and pepper to taste.","images":[],"step":7},{"description":"Top with remaining cheese, put lid on. Leave for 1 minute until cheese is melted and pasta is perfectly cooked.","duration":1,"images":[],"step":8},{"description":"Garnish with parsley and serve immediately. Don''t leave leftovers in the pot, residual heat will overcook the pasta so transfer into a serving dish.","images":[],"step":9}]', '["gluten","milk"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","dinner-tonight","low-calorie-recipes","main-dishes","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5d99363bb9d4', 'en', 'US', 'Slow Roasted Rosemary Garlic Lamb Shoulder', 'Recipe video above. Lamb shoulder is cheaper, juicier and easier to roast than leg. Infused with rosemary garlic flavours, this is not the sort of roast for carving, just pull the meat off with tongs. Make Crazy Crunchy Roast Potatoes while the lamb is resting!', 'https://www.recipetineats.com/tachyon/2015/02/Slow-Cooked-lamb-Shoulder_1.jpg', 15, 210, 225, 4, '[{"id": "ing_lamb", "quantity": {"value": 1.8, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_rosemary", "quantity": {"value": 0.32, "unit": "bunch"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}]', '[{"ingredients":["1.8kg / 3.5 lb lamb shoulder (bone in) (Note 1)","2 tbsp olive oil","2 tsp salt","1 tsp black pepper","1 onion, quartered (no need to peel)","1 head garlic (, cut in half horizontally)","3 garlic cloves (, cut into slivers)","8 sprigs rosemary","1 cup water"]},{"ingredients":["2 tbsp flour","2 cups beef broth (or 1 cup red wine + 1 cup water)","Salt and pepper"],"purpose":"Gravy"}]', '[{"description":"Preheat oven to 240°C/465°F (220°C fan forced).","images":[],"step":1},{"description":"Rub the lamb with the olive oil, salt and pepper.","images":[],"step":2},{"description":"Use a thin, sharp knife to make 12 incisions in the lamb, deep as you can but without piercing through the bottom of the lamb. (See photo in post and video","images":[],"step":3},{"description":"Stuff bits of rosemary and garlic slivers into the holes (chopstick helpful!)","images":[],"step":4},{"description":"Place the onion, halved garlic bulb and rosemary in the base of a roasting pan. Place the lamb on top. Pour water around.","images":[],"step":5},{"description":"Cover with lid or tightly with a double layer of foil. Place in the oven, and TURN DOWN to 180°C/350°F (160°C fan).","images":[],"step":6},{"title":"Slow roast, covered","description":"Roast, covered with the foil, for 3 hours. (Note 1 for different sizes).","images":[],"step":7},{"title":"Brown it, uncovered","description":"Remove foil, check to ensure there''s still liquid in the pan. If not, add 3/4 cup water (otherwise onion/garlic will burn). Turn up the oven to 220°C/425°F and roast for a further 20 to 30 minutes, until the skin is browned and crisp.","images":[],"step":8},{"title":"Check if ready","description":"By now, you should be able to part the meat with two forks - if not, just cover and return to oven at 180°C/350°F (160°C fan) until you can do so.","images":[],"step":9},{"title":"Rest","description":"Remove lamb from the roasting pan and transfer to a plate. Cover loosely with foil then a couple of tea towels and let it rest for at least 20 minutes, up to a couple of hours (after this, you may want to reheat).","images":[],"step":10},{"description":"Serve with gravy (below). If you want to go all out, make Duck Fat Potatoes or Super Crispy Roasted Potatoes!","images":[],"step":11},{"description":"Tilt the pan and use a spoon to remove all but around 2 tbsp of fat (try to avoid scooping out any juices).","images":[],"step":12},{"description":"Place the roasting pan on the stove over medium high heat. Add the flour and stir to mix in with the fat. Cook for 30 seconds.","duration":0.5,"images":[],"step":13},{"description":"Add the stock gradually and stir to combine. Use a potato masher to mash the onion and garlic, making sure that all the garlic squeezes out of the skin.","images":[],"step":14},{"description":"Allow it to simmer for 1 to 2 minutes until it is just before your desired consistency (it will thicken a bit as it cools), then remove from the stove. Season to taste with salt and pepper, strain into bowl being sure to squeeze all juices out of garlic etc, then transfer into gravy jug.","duration":1.5,"images":[],"step":15}]', '["gluten"]', '[]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["dietary","easter-mains","easter-recipes","gluten-free-recipes","iconic-dishes","lamb-recipes","main-dishes","quick-and-easy","roast-lamb","roasts","slow-cooked-fall-apart","sunday-supper"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6a84414fab73', 'en', 'US', 'Prawn Risotto (Shrimp)', 'This is a great everyday prawn risotto that’s a cut above basic risottos. Searing the prawn (shrimp) makes a terrific flavour base that compensates for not using a homemade seafood stock. And as long as you use a large pot, you don’t need to stand at the stove for 20 minutes to stir constantly and add hot broth a ladle at a time for ultra creamy risotto – read more in post. Recipe video below.', 'https://www.recipetineats.com/tachyon/2018/05/Prawn-Risotto_0.jpg', 10, 25, 35, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_shrimp", "quantity": {"value": 400.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_wine", "quantity": {"value": 0.111, "unit": "bottle of 750ml"}}, {"id": "ing_arborio_rice", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}, {"id": "ing_butter", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 – 2 tbsp olive oil","400 – 500g (14oz – 1 lb) prawns/shrimp, raw, peeled (Note 1)","Salt and pepper","1 1/2 tbsp (20g) butter","1/2 onion (, finely chopped)","2 garlic cloves (, minced)","1/3 cup (85 ml) dry white wine (or water)","1 1/2 cups (270g) Arborio rice (, uncooked (Note 2))","3 cups (750ml) chicken broth (, low sodium, at room temp)","1 cup (250 ml) milk (, room temp (full or low fat))","1 cup (150g) frozen peas (, thawed)","1/3 cup (40g) grated parmesan"]},{"ingredients":["1 – 2 tbsp (15 – 30g) Extra Butter","Grated parmesan","Finely chopped parsley (optional)"],"purpose":"Finishing / serving:"}]', '[{"description":"Heat 1 tbsp oil in a large heavy based pot over medium high heat. Spread half the prawns in a single layer, sprinkle with salt and pepper. Cook for 1 ½ minutes, then turn and cook the other side for 1 minute. Remove into bowl.","duration":1,"images":[],"step":1},{"description":"Add a touch more oil and repeat with remaining prawns. Set aside and keep warm.","images":[],"step":2},{"description":"Turn heat down to medium. Melt butter in pot then add onion and garlic. Cook for 2 minutes until translucent.","duration":2,"images":[],"step":3},{"description":"Add wine, and stir, scraping the bottom of the pot to mix the brown bits from the prawn into the liquid. Bring to simmer and cook for 2 minutes until harsh alcohol smell is gone.","duration":2,"images":[],"step":4},{"description":"Add rice and stir for 30 seconds until rice is translucent on edges.","duration":0.5,"images":[],"step":5},{"description":"Add about 2/3 of the chicken broth. Stir, bring to simmer. Adjust heat so it’s simmering gently.","images":[],"step":6},{"description":"Simmer for 5 minutes. Stir, then simmer for a further 2 minutes until broth is mostly absorbed and rice is visible on the surface (see video and photos).","duration":5,"images":[],"step":7},{"description":"Add remaining broth and milk. Stir, simmer for 3 minutes. Stir, simmer for 2 minutes.","duration":3,"images":[],"step":8},{"description":"Risotto should be soupy and rice still a tiny bit undercooked.","images":[],"step":9},{"description":"Add peas and parmesan, quickly stir.","images":[],"step":10},{"description":"Taste, then add salt and pepper, then quickly stir.","images":[],"step":11},{"description":"Add Extra Butter, then stir vigorously for 10 seconds (this is the step that makes it very creamy).","duration":0.16666666666666666,"images":[],"step":12},{"description":"Lastly, gently stir through prawns (tip in any juices too).","images":[],"step":13},{"description":"Remove risotto from heat, it should be porridge-like. (Note 3, see video) To loosen, add hot tap water 2 tbsp at time and stir through.","images":[],"step":14},{"description":"Give it a good final stir just before serving. Then ladle into bowls (it should ooze a bit, not be sticky lump). Garnish with parmesan and parsley if desired.","images":[],"step":15}]', '["milk","shellfish"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dietary","dinner-tonight","gluten-free-recipes","italian-recipes","main-dishes","prawns-shrimp","quick-and-easy","rice-recipes","risotto-recipes","seafood-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3402785cbecb', 'en', 'US', 'Magic healthy low cal creamy Vegetable Soup!', 'Recipe video above. It''s a cream of vegetable soup.... without the guilt! Super low cal and gluten free, the soup broth is made using whizzed up peeled zucchini, cauliflower and onion. Zucchini has a terrific neutral flavour which makes a creamy broth just like creamy soups thickened using butter and flour (and often cream!) - but with 90% less calories!', 'https://www.recipetineats.com/tachyon/2018/02/Healthy-Creamy-Vegetable-Soup_6.jpg', 15, 35, 50, 6, '[{"id": "ing_cauliflower", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_zucchini", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 2000.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 3.0, "unit": "head"}}, {"id": "ing_capsicum", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_zucchini", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 medium head of cauliflower (, about 600 - 700g / 1.2 - 1.4 lb (Note 1))"]},{"ingredients":["500g / 1 lb zucchinis ((2 large), peeled and cut into 1.5cm / 3/5\" slices)","1 large onion (, roughly chopped (brown, white, yellow))","2 garlic cloves (, whole)","2 cups (500 ml) vegetable or chicken broth","2 cups (500 ml) water","1 cup (250 ml) 0% fat milk (or other milk of choice)","1/2 tsp each garlic powder and onion powder (or 1 tsp of one of them)","Pinch black pepper"],"purpose":"Low Cal Creamy Soup Broth:"},{"ingredients":["1 tbsp olive oil","1 garlic clove (, minced)","1 onion (, chopped (brown, white, yellow))","2 large carrots (, cut into 1.25cm / 1/2\" pieces)","3 celery sticks (, cut into 0.75cm / 1/4\" slices)","2 red capsicum / bell peppers (, cut into 1 cm / 2/5\" pieces)","500g / 1 lb zucchinis ((2 large), peeled and cut into 1.25cm / 1/2\" slices)","1 tsp dried thyme (or other herb of choice)","Salt and pepper","Finely chopped parsley (, optional garnish)"],"purpose":"Soup:"}]', '[{"title":"For soup","description":"Break off 1/4 of the cauliflower into small bite size florets and put aside to use in the soup.","images":[],"step":1},{"title":"For broth","description":"Break up the rest of the cauliflower into medium florets. If you have a small cauliflower, use the stem too - peel then rough dice.","images":[],"step":2},{"description":"Place cauliflower for broth in a large pot. Add zucchini, onion, whole garlic cloves, vegetable broth and water. (Note 2)","images":[],"step":3},{"description":"Place lid on, bring to boil then adjust heat so it''s simmering energetically. Cook for 15 minutes or until cauliflower is soft.","duration":15,"images":[],"step":4},{"description":"Transfer to blender (Note 3), add garlic powder, onion powder, pepper and milk. Place lid on, place tea towel on lid and hold down very firmly, then whizz to puree soup, starting on low then getting faster.","images":[],"step":5},{"description":"Remove lid. Marvel at super low cal ultra creamy soup broth.","images":[],"step":6},{"description":"Heat oil in a large pot over medium high heat. Add onion and garlic, cook for 1 minute. Then add carrots and celery, cook for 2 minutes.","duration":1,"images":[],"step":7},{"description":"Add thyme, capsicum and zucchini. Cook until softened, around 2 minutes.","images":[],"step":8},{"description":"Pour in soup broth. Adjustment consistency with water to achieve desired thickness. Add reserved cauliflower.","images":[],"step":9},{"description":"Simmer 5 minutes to bring flavours together. Season with salt and pepper.","images":[],"step":10},{"description":"Serve, garnished with parsley. Or splurge your calorie credits on a piece of grilled cheese to dunk into the soup!!","images":[],"step":11}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["dietary","dinner-tonight","low-calorie-recipes","main-dishes","quick-and-easy","soup-recipes","uncategorized","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_905c7d731432', 'en', 'US', 'Prawn Mango and Avocado Salad with Noodles', 'This Prawn Mango and Avocado Salad with Noodles is perfect for balmy summer days. Drizzled with a terrific Lime Sweet Chilli Dressing, this is a great no-cook meal! This recipe serves 2 and it is enough for a meal (see Nutrition ones). Recipe VIDEO below.', 'https://www.recipetineats.com/tachyon/2017/11/Prawn-Avocado-Mango-Salad-6.jpg', 15, 0, 15, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.18, "unit": "pack of 500g"}}, {"id": "ing_shrimp", "quantity": {"value": 12.0, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 8.0, "unit": "head"}}, {"id": "ing_mango", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 0.25, "unit": "pack of 1kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.375, "unit": "pack of 100g"}}, {"id": "ing_lime", "quantity": {"value": 0.12, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_coriander", "quantity": {"value": 0.45, "unit": "bunch"}}]', '[{"ingredients":["90 g / 3 oz dried vermicelli noodles","12 - 16 large cooked prawns (shrimp), peeled (enough for 2 people)","8 - 10 soft lettuce leaves (, about 15 cm /6\" rounds (Note 1))","1 medium mango (, ripe, cut into 1.5 cm / 3/5\" pieces (Note 2))","1 medium avocado (, cut into 1.5 cm / 3/5\" pieces (Note 2))","1/4 red onion (, finely diced)"]},{"ingredients":["2 1/2 tbsp Sweet Chilli Sauce (store bought)","4 tbsp lime juice (or 2 1/2 tsp rice vinegar or cider vinegar)","2 1/2 tbsp olive oil","1 small garlic clove (, minced)","1 1/2 tsp sugar","Salt and pepper","1 1/2 tbsp finely chopped coriander / cilantro"],"purpose":"Dressing:"}]', '[{"description":"Soak vermicelli noodles in freshly boiled water, per packet directions. Drain then set aside to cool.","images":[],"step":1},{"description":"Place Dressing ingredients except coriander in a bowl. Whisk well. Stir through coriander. Adjust salt and pepper to taste.","images":[],"step":2},{"description":"Place avocado and mango in a bowl. Drizzle over 3 teaspoons of Dressing, GENTLY toss.","images":[],"step":3},{"description":"Place 4 to 5 lettuce leaves on each plate, overlapping slightly (see video for how I do it).","images":[],"step":4},{"description":"Divide the noodles between each plate. Then spoon over mango avocado salsa, sprinkle each plate all over with red onion and top with prawns.","images":[],"step":5},{"description":"Drizzle over remaining Dressing all over everything, including the noodles. Serve immediately.","images":[],"step":6}]', '["shellfish"]', '["gluten_free"]', '{"mealType":["main_course"],"cuisine":[],"categories":["dietary","dinner-tonight","gluten-free-recipes","main-dishes","no-cook-food","prawns-shrimp","quick-and-easy","salad-recipes-main-course","seafood-recipes","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_72e94aae04a9', 'en', 'US', 'WILD RICE SALAD', 'The vibrant colours, flavours and textures in this salad are sensational! A great holiday salad or for special occasions. Serves 3 as meal or 5 - 6 as side. Recipe VIDEO below.', 'https://www.recipetineats.com/tachyon/2017/11/Wild-Rice-Salad-1-1.jpg', 10, 50, 60, 3, '[{"id": "ing_rice", "quantity": {"value": 150.0, "unit": "pack"}}, {"id": "ing_baby_rocket_arugula", "quantity": {"value": 0.12, "unit": "kg"}}, {"id": "ing_pomegranate", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_feta_cheese", "quantity": {"value": 100.0, "unit": "block of 200g"}}, {"id": "ing_cranberries", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_pecans", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.09, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.167, "unit": "pack of 3 heads"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["150g (5oz / 1 cup) wild rice (, uncooked (Note 1))","120g (4oz) baby rocket / arugula (, roughly chopped (~2 giant handfuls))","1 pomegranate (, seeds only (see video, Note 2))","100g (3.5oz) feta (, preferably soft Danish, crumbled (Note 3))","3/4 cup dried cranberries (or similar)","3/4 cup roughly chopped toasted pecans","1 cup green onions (, sliced (or chopped red onion))"]},{"ingredients":["2 tbsp white wine vinegar (or cider vinegar, or other clear-ish vinegar)","6 tbsp extra virgin olive oil","1/2 garlic clove (, minced)","1 tsp sugar","1/2 tsp salt","1/2 tsp black pepper"],"purpose":"Dressing:"}]', '[{"description":"Boil 1 litre/quart+ of water in large saucepan (no need to be exact). Add rice, lower heat so it’s simmering gently. Cover then cook for 40 minutes (Note 4), or until rice is tender but not super soft (some will burst).","duration":40,"images":[],"step":1},{"description":"Drain then leave to steam dry and cool.","images":[],"step":2},{"description":"Shake Dressing in a jar, set aside for 15 minutes+.","duration":15,"images":[],"step":3},{"description":"Place rocket, rice, cranberries, pecans and green onions in a bowl. Add some of the feta and pomegranate. Pour over most of the Dressing, toss gently.","images":[],"step":4},{"description":"Transfer into serving bowl, top with remaining feta and pomegranate. Serve immediately.","images":[],"step":5}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["dietary","easter-brunch-recipes","easter-sides-fresh-light","gluten-free-recipes","pasta-salads-and-rice-salads","quick-and-easy","rice-recipes","rice-side-dishes","salad-recipes-main-course","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_fd4d6844079e', 'en', 'US', 'Baked Mushroom Rice', 'Recipe video above. The oven baked version of the wildly popular Mushroom Rice! The idea behind this recipe is that the mushrooms act as a "lid" over the rice as it bakes, and the mushroom juices drip into the rice - best broth ever! The rice is FLUFFY, garlicky and buttery, and the mushrooms are golden brown and juicy inside.', 'https://www.recipetineats.com/tachyon/2017/10/Baked-Mushroom-Rice_6.jpg', 10, 35, 45, 6, '[{"id": "ing_mushroom", "quantity": {"value": 0.65, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 2.0, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_rice", "quantity": {"value": 225.0, "unit": "pack"}}, {"id": "ing_chicken", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}]', '[{"ingredients":["650g (1.3 lb) mushrooms (, quartered (Note 1))","50g (3.5 tbsp) butter (, melted (hot, not cooled))","2 - 3 garlic cloves (, minced (I use 3 - nice and garlicky!))","Salt and pepper","1.5 tbsp olive oil"]},{"ingredients":["1 1/2 cups long grain rice (, uncooked)","1 1/2 cups (375 ml) chicken or vegetable broth (, low sodium)","1 1/4 cups (315 ml) water","1 tsp dried thyme","1 tsp garlic powder"],"purpose":"Rice:"},{"ingredients":["3 shallots / green onions / scallions (, finely sliced)","1 - 2 tbsp butter (, optional)"],"purpose":"Finishes:"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Place mushrooms in a large bowl. Pour over hot melted butter, add garlic, salt and pepper. Toss well.","images":[],"step":2},{"title":"Place all the Rice ingredients in a baking pan","description":"22 x 33 cm / 9 x 13\". Mine is 30 x 24 cm / 12 x 9.5\" - don''t need to be exact here, but don''t stray too much from pan size.","images":[],"step":3},{"description":"Mix and shake the pan to spread the rice out evenly.","images":[],"step":4},{"title":"Spread the mushrooms over the rice","description":"they will be partially submerged but should pretty much cover the whole surface area (to be the \"lid\" while the rice cooks).","images":[],"step":5},{"description":"Drizzle over olive oil.","images":[],"step":6},{"title":"Bake for 35","description":"40 minutes or until mushroom is golden. Remove from oven and rest for 5 minutes.","duration":37.5,"images":[],"step":7},{"title":"Finishes","description":"Add extra butter (if using) and scallions. Toss through rice. Serve!","images":[],"step":8}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["dietary","easter-sides-warm-hearty","gluten-free-recipes","mushroom-recipes","quick-and-easy","rice-recipes","rice-side-dishes","side-dishes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cd31ed7ba9a4', 'en', 'US', 'Oven Baked Rice and Vegetables', 'Recipe video above. Fluffy seasoned rice AND oven roasted veggies, all baked in ONE PAN! Imagine the possibilities!', 'https://www.recipetineats.com/tachyon/2017/09/Oven-Baked-Vegetables-and-Rice.jpg', 10, 50, 60, 5, '[{"id": "ing_jasmine_rice", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_cauliflower", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_zucchini", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 2.0, "unit": "can of 400g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_paprika", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 1.0, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 1/2 cups basmati or jasmine rice (, uncooked (Note 1 for other rice types))","1 1/2 cups (375ml) chicken or vegetable broth (I use chicken)","1 1/4 cups (315ml) water","2 garlic cloves (, minced)","2 medium carrots (, cut into 1 cm thick slices, larger pieces halved)","30g (2 tbsp) unsalted butter (optional)"],"purpose":"Rice:"},{"ingredients":["1 red onion (, halved and cut into wedges)","1 capsicum / bell pepper (, cut into 2.5cm / 1\" pieces)","1/2 small cauliflower (, broken into florets)","2 zucchini (, cut into 2cm / 4/5\" chunks)","2 corn cobs (, each cut into 3 (6 small cobs))","1/4 cup olive oil (, plus more for drizzling)"],"purpose":"Roasting Vegetables (Note 2):"},{"ingredients":["1 1/2 tsp paprika","1 1/2 tsp thyme or other dried herb of choice","1 tsp garlic powder (or onion powder)","1 tsp salt (Note 3 for low sodium)","1 tsp pepper (, plus extra)"],"purpose":"Spice Mix:"},{"ingredients":["Finely chopped parsley"],"purpose":"Garnish (optional):"}]', '[{"description":"Preheat oven to 200C/390F (standard) / 180C/350F (fan / convection).","images":[],"step":1},{"description":"Mix Spice Mix in a small bowl.","images":[],"step":2},{"description":"Place Rice ingredients in a baking dish (including the carrots), about 23 x 30 cm / 9 x 13\". Add 1 1/2 tsp Spice Mix. Stir, cover with foil, bake for 20 minutes.","duration":20,"images":[],"step":3},{"description":"Meanwhile, place Roasting Vegetable ingredients in a large bowl, drizzle with 1/4 cup olive oil. Sprinkle over remaining Spice Mix. Mix well - hands are best for this.","images":[],"step":4},{"description":"Remove rice from oven.","images":[],"step":5},{"description":"Turn oven UP to 220C/430F (standard) / 200C/390F (fan / convection).","images":[],"step":6},{"description":"Take off foil. Spread the Roasting Vegetables on top of the rice. Make sure there''s a bit of each type of vegetable on the surface. Push corn mostly under.","images":[],"step":7},{"description":"Drizzle with more oil (optional), sprinkle with more pepper.","images":[],"step":8},{"title":"Bake for 30 minutes. Remove from oven, rest for 5","description":"10 minutes.","duration":30,"images":[],"step":9},{"description":"Sprinkle with parsley if desired. Push vegetables aside, fluff rice and toss it through the vegetables a bit (rice gets more flavour). Serve!","images":[],"step":10}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dietary","easter-sides-warm-hearty","gluten-free-recipes","one-pot-recipes","quick-and-easy","rice-recipes","rice-side-dishes","side-dishes","vegan-lifestyle","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_01abe2e68748', 'en', 'US', 'Creamy Zucchini Soup', 'You don’t need loads of cream or even a roux to make a creamy zucchini soup. The natural texture of the zucchini flesh whizzes up beautifully to be a silky, creamy texture. It’s well worth the extra few minutes to saute onions until golden for the extra flavour it adds. Topping the soup with a pinch of parmesan is a great finishing touch, otherwise try croutons, finely sliced basil or other herb.', 'https://www.recipetineats.com/tachyon/2017/08/Creamy-Zucchini-Soup-1.jpg', 10, 20, 30, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_zucchini", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["1 tbsp olive oil or butter","2 garlic cloves (, minced)","1 large onion (, chopped (brown, yellow or white))","1 kg / 2 lb zucchinis (, cut into 1.5cm / 3/5” slices, larger ones halved (Note 1))","3 cups / 750 ml vegetable or chicken broth (, preferably salt reduced)","1 cup / 250 ml water","3/4 cup / 185 ml cream, heavy / thickened (or light or add a good knob of butter instead) (Note 2)","1 cup / 250 ml milk (, any fat %, or more cream)"]},{"ingredients":["Cream (, for swirling)","Finely shredded parmesan"],"purpose":"Garnish:"}]', '[{"description":"Heat oil in a large pot over medium high heat. Add garlic and onions, and cook for 3 - 4 minutes until they are light golden brown.","duration":3.5,"images":[],"step":1},{"description":"Add zucchinis, broth and water. Bring to a boil, then cover and reduce heat to medium. Optional: Scoop brown foam (scum) off surface every now and then.","images":[],"step":2},{"title":"Cook for 15","description":"20 minutes or until zucchini is very soft.","duration":17.5,"images":[],"step":3},{"description":"Use a stick blender to whizz until smooth. (Note 1 for blender)","images":[],"step":4},{"description":"Stir through cream and milk. Add salt and pepper to taste.","images":[],"step":5},{"description":"Ladle into bowls, swirl over a touch of cream if desired, a pinch of shredded parmesan, and more pepper. Serve hot or at room temperature.","images":[],"step":6}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["main_course"],"cuisine":[],"categories":["dietary","dinner-tonight","gluten-free-recipes","low-calorie-recipes","main-dishes","quick-and-easy","soup-recipes","vegetarian-recipes","winter-recipe-collection","zucchini-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3c29732007fd', 'en', 'US', 'Spanish Healthy Vegetable Soup', 'Recipe video above. This is my version of the famous Zero Weight Watchers Points vegetable soup. Mine has 0.4 WW points but is much MUCH tastier! Spanish flavours inspired by the seasoning for homemade Chorizo (yes, really!), the broth of this soup is MUCh tastier than the Zero WW soup!!!', 'https://www.recipetineats.com/tachyon/2017/07/Healthy-Vegetable-Soup.jpg', 15, 30, 45, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_fennel_seeds", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 20.0, "unit": "head"}}, {"id": "ing_capsicum", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_cabbage", "quantity": {"value": 15.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["2 tsp olive oil","1 onion (, finely chopped)","2 garlic cloves (, minced)","1 tbsp dried oregano","2 tsp fennel seeds (optional)","2 medium carrots (, finely chopped)","1 large celery stalk/rib (, finely chopped)","2 red capsicums / bell peppers (, cut into 2 cm / 4/5” pieces)","5 cups cabbage (, cut into 3 cm / 1.2” pieces (about 400g/14oz))","800g / 28 oz crushed tomato","3 cups (750 ml) vegetable or chicken broth (low fat!)","1 tbsp smoked paprika (or any paprika)","1 tsp cayenne pepper (adjust spiciness to taste)"],"purpose":"Soup:"},{"ingredients":["Salt and pepper to taste","1 lemon – zest + juice to taste","Finely chopped parsley"],"purpose":"Finishes (not optional!):"}]', '[{"description":"Heat oil in a large pot over medium heat. Add garlic and onion, cook for 30 seconds or so.","duration":0.5,"images":[],"step":1},{"description":"Add oregano and fennel seeds, cook for 2 minutes (lets flavour “bloom”).","duration":2,"images":[],"step":2},{"description":"Turn heat down to medium low. Add carrots and celery, cook, stirring regularly, for 8 minutes until onion is sweet (not browned). This step is key to the flavour base of this soup.","duration":8,"images":[],"step":3},{"description":"Add capsicum, turn heat up to high and cook for 2 minutes, stirring constantly.","duration":2,"images":[],"step":4},{"description":"Add remaining Soup ingredients, bring to simmer then place lid on. Turn heat down to medium low, simmer for 25 minutes.","duration":25,"images":[],"step":5},{"description":"Remove lid, adjust salt and pepper to taste.","images":[],"step":6},{"description":"Ladle soup into bowls. Grate over lemon zest, squeeze of lemon juice and sprinkle with parsley. Serve!","images":[],"step":7}]', '[]', '["gluten_free","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Spanish Style","Western"],"categories":["dietary","dinner-tonight","gluten-free-recipes","low-calorie-recipes","main-dishes","mediterranean-recipes","quick-and-easy","soup-recipes","vegan-lifestyle","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f7445da59d40', 'en', 'US', 'Cowboy Rice Salad', 'A Southwestern rice salad filled with bright zesty flavours and tossed with a lime dressing. Made with brown rice for extra flavour, and a hint of spice flavour in the dressing to drive home the SouthWestern flavours! Serves 8 - 10 as a side, 4 - 6 as a main. Recipe video below!', 'https://www.recipetineats.com/tachyon/2017/04/Cowboy-Rice-Salad-5.jpg', 20, 0, 20, 8, '[{"id": "ing_rice", "quantity": {"value": 675.0, "unit": "pack"}}, {"id": "ing_ime_juice", "quantity": {"value": 0.333, "unit": "unit"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_honey", "quantity": {"value": 0.045, "unit": "jar of 500g"}}, {"id": "ing_chipotle", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_cumin", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_corn", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_black_beans", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_tomato", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["4 1/2 cups cooked brown rice"]},{"ingredients":["1/3 cup lime juice (, plus more to taste)","1/2 cup olive oil","1 1/2 tbsp honey","1/2 tsp chipotle powder ( (sub with smoked paprika + cayenne pepper))","1/2 tsp cumin powder","1/2 tsp garlic powder ( (or 1 garlic clove, minced))","3/4 tsp salt","Black Pepper"],"purpose":"Dressing:"},{"ingredients":["1 red capsicum/bell pepper (, diced)","1 green capsicum/bell pepper (, diced)","1 small red onion (, chopped)","1 x 400g (14oz) corn kernels (, drained)","1 x 400g (14oz) black beans (, drained and rinsed)","3 tomatoes (, watery seeds removed then diced)","1 cup coriander/cilantro leaves (, roughly chopped (Note 2))"],"purpose":"Salad:"}]', '[{"description":"Place Dressing ingredients in a jar, shake. Taste test, adjust to your taste.","images":[],"step":1},{"description":"Place Salad ingredients and rice in a bowl. Drizzle with dressing. Toss, then serve. Fantastic served straight away and even the next day!","images":[],"step":2}]', '[]', '["gluten_free","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Western"],"categories":["dietary","easter-sides-fresh-light","gluten-free-recipes","pasta-salads-and-rice-salads","quick-and-easy","rice-recipes","rice-side-dishes","salad-recipes-main-course","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b4540d2fea7e', 'en', 'US', 'Cured Salmon Gravlax (it''s so easy!)', 'Homemade Gravlax is so much cheaper and it tastes BETTER than store bought because store bought is usually too salty and you can never get that real fresh dill flavour. It''s so crazy easy to make, this is going to blow your mind! The key to nailing gravlax is: cure time, salt type and sugar vs salt ratio. More food-nerd info in the notes - including how to make this with smaller fillets (don''t just use the servings scaler function please!) Recipe video below.', 'https://www.recipetineats.com/tachyon/2017/04/Salmon-Gravlax-6.jpg', 10, 0, 10, 10, '[{"id": "ing_black_pepper", "quantity": {"value": 0.3, "unit": "jar of 50g"}}, {"id": "ing_dill", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_salmon_fillets", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_mustard", "quantity": {"value": 0.25, "unit": "jar of 200g"}}, {"id": "ing_mustard", "quantity": {"value": 0.25, "unit": "jar of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.3, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}]', '[{"ingredients":["1 tbsp white peppercorns (whole) (Note 1)","1 cup fresh dill, roughly chopped (1 big bunch)","250g / 8 oz rock salt (Note 2)","250g / 8 oz white sugar (Note 3)","1 kg / 2 lb salmon, sashimi-grade, bones removed and skin on (Note 4)"]},{"ingredients":["1/2 cup / 125 ml heavy / thickened cream","1/3 cup Dijon Mustard (or hot mustard if you want a kick)","2 tsp Mustard Powder","Salt and pepper"],"purpose":"Mustard Cream Sauce"},{"ingredients":["Rye bread slices or other bread/crackers (Note 5)","Lemon wedges","1/4 cup fresh dill, roughly chopped (for garnish)"],"purpose":"To Serve"}]', '[{"description":"Crush peppercorns with the side of a knife (or roughly grind using mortar and pestle).","images":[],"step":1},{"description":"Combine peppercorns with salt, sugar and dill.","images":[],"step":2},{"description":"Place 2 large pieces of cling wrap on a work surface, slightly overlapping. Spread half the salt mixture in the shape of the salmon.","images":[],"step":3},{"description":"Place salmon on salt, skin side down. Top with remaining salt mixture.","images":[],"step":4},{"description":"Wrap with cling wrap. Place in a large dish. Top with something flat (like small cutting board) then 3 x 400g / 14oz cans (\"Weights\").","images":[],"step":5},{"description":"Refrigerate for 12 hours. There will be liquid in the dish. Turn salmon over (will be gloopy/wet)), then replace Weights and return to fridge. After another 12 hours, turn salmon over again, replace Weights. After another 12 hours, remove salmon from fridge. 36 hours total for Medium Cure - Perfect Gravlax to my taste (See Note 2 for description and more curing times).","images":[],"step":6},{"description":"Unwrap salmon, scrape off salt then rinse. Pat dry. If time permits, return to the fridge for 3 - 12 hours uncovered (dries surface better, lets salt \"settle\" and permeate through flesh more evenly).","images":[],"step":7},{"title":"Sprinkle over the 1/4 cup extra dill","description":"for garnish and flavour.","images":[],"step":8},{"description":"Slice thinly on an angle, do not cut through skin (i.e. don''t eat skin). Serve with toasted bread, Mustard Sauce, extra dill and lemon wedges.","images":[],"step":9},{"description":"Mix ingredients, making sure to season with salt and pepper. It should taste like a creamy mustard - a touch of tartness, but mostly to add moisture to the dish. You can add lemon juice and/or zest if you wish - I like to serve with wedges so people can adjust to their taste.","images":[],"step":10}]', '["fish","gluten","milk","mustard"]', '["low_calorie"]', '{"mealType":["main_course"],"cuisine":[],"categories":["dietary","easter-mains-fish-seafood","finger-food","fish-recipes","gluten-free-recipes","iconic-dishes","salmon-recipes","seafood-recipes","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d6ee9fed236e', 'en', 'US', '3 Minute Melty Festive Brie (Speed Baked Brie)', 'This is one of my greatest secret weapons for gatherings. It looks fantastic, you don''t need to use an expensive brie for this, it''s adaptable to your taste, it takes minutes to make, and it''s an absolute and total crowd pleaser! The flavour combination is a killer: creamy brie with the warm nuttiness of pecans, sweetness from maple syrup and juicy pops of pomegranate. Normally brie served like this is baked, but you can''t tell the difference between baking and microwaving!', 'https://www.recipetineats.com/tachyon/2016/12/3-Minute-Melted-Brie-3-2.jpg', 2, 1, 3, 4, '[{"id": "ing_brie", "quantity": {"value": 1.0, "unit": "block of 200g"}}, {"id": "ing_pecans", "quantity": {"value": 0.25, "unit": "unit"}}, {"id": "ing_pomegranate_seeds", "quantity": {"value": 37.5, "unit": "jar"}}, {"id": "ing_maple_syrup", "quantity": {"value": 0.25, "unit": "bottle of 250ml"}}]', '[{"ingredients":["1 (250 g / 8 oz) whole brie (Note 1)","1/4 cup roughly chopped pecans (, roasted (Note 2))","1/4 cup pomegranate seeds","1/4 cup maple syrup"]}]', '[{"description":"Unwrap brie and place on a small microwave-proof plate with a rim (so maple syrup doesn''t go everywhere).","images":[],"step":1},{"description":"Microwave on high for 1 minute 15 seconds, or until the brie is very soft when you prod the centre. Watch the brie as you microwave it - if it starts to puff up too much (i.e. risk of bursting), turn microwave off and leave brie inside - residual heat will continue to melt it.","duration":1,"images":[],"step":2},{"description":"Top with pecans, pomegranate seeds and maple syrup. Serve immediately with crackers of choice (choose ones suitable for scooping). I serve this with a spoon and/or small pate knife.","images":[],"step":3}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["snack"],"cuisine":[],"categories":["dietary","gluten-free-recipes","quick-and-easy","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_92db19b9d29d', 'en', 'US', 'Port Braised Lamb Shanks', 'These lamb shanks are just like what you get at high end restaurants! Port and red wine is the key to the incredible sauce that these lamb shanks are braised in. Get discount bottles - no need to splurge on expense wine for this!', 'https://www.recipetineats.com/tachyon/2016/09/Lamb-Shanks-Port-Braised_4.jpg', 15, 180, 195, 4, '[{"id": "ing_amb_shanks", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_port", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_wine", "quantity": {"value": 0.5, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_parsley", "quantity": {"value": 4.0, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 4.0, "unit": "bunch"}}]', '[{"ingredients":["4 lamb shanks (, approx 400g/13oz each (Note 1))","Salt and pepper","2 tbsp olive oil (, separated)","2 garlic cloves (, minced)","1 onion (, finely chopped (white, brown, yellow))","1 celery stalk (, finely chopped (optional, but recommended))","1 carrot (, finely chopped (optional, but recommended))","3 tbsp / 1/4 cup flour (35g)","2 cups / 500 ml beef broth (liquid beef stock) (or sub with chicken broth)","3 cups / 750 ml port (Note 2)","1 1/2 cups / 375ml red wine (, or more beef broth (Note 3))","3 tbsp / 1/4 cup tomato paste","5 sprigs thyme or 2 tsp dried thyme","3 dried bay leaves (or 5 fresh)","4 stalks fresh parsley (optional)"]},{"ingredients":["Fresh parsley (, finely chopped)"],"purpose":"To Serve"}]', '[{"description":"Season lamb with salt and pepper.","images":[],"step":1},{"description":"Heat 1 tbsp oil in a dutch oven or large heavy based pot over high heat. Add 2 lamb shanks and cook, turning, until browned (see photo). Remove then repeat with remaining lamb.","images":[],"step":2},{"description":"Turn heat down to medium. Add remaining 1 tbsp oil, garlic, onion, carrot and celery. Sauté for 5 minutes until onion is softened.","duration":5,"images":[],"step":3},{"description":"Add flour. Mix into onion mixture.","images":[],"step":4},{"title":"Add remaining ingredients. Mix","description":"lumps are ok, they will dissolve while cooking.","images":[],"step":5},{"title":"Add lamb back in","description":"the meat should be mostly submerged. Bring to simmer, then turn heat down to medium low and cover with lid.","images":[],"step":6},{"description":"Simmer for 2 hours (Note 4) then remove lid and simmer for 30 minutes.","images":[],"step":7},{"description":"Remove lamb into a bowl.","images":[],"step":8},{"title":"Optional","description":"Strain sauce in dutch oven into a bowl. Use spoon to press into onion etc to squeeze out all the flavourful liquid. Pour sauce into dutch oven. (Note 5)","images":[],"step":9},{"description":"Skim excess fat off sauce.","images":[],"step":10},{"description":"Increase heat to medium high and reduce liquid by half or until it thickens to a syrup consistency.","images":[],"step":11},{"description":"Return lamb shanks and juices pooled in the bowl into sauce to reheat, then serve with creamy mashed potato, garnished with parsley.","images":[],"step":12}]', '["gluten"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dietary","gluten-free-recipes","lamb-shanks","main-dishes","slow-cooked-fall-apart","slow-cooker-recipes","stews","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2462e24d50cb', 'en', 'US', 'Pork Carnitas Tacos', 'A Pork Carnitas Taco spread, a copy cat of the famous Carnitas tacos at Old Town Mexican Cafe in San Diego (just 30 minutes from the Mexican border), reputed to be the BEST in town! My Pork Carnitas are ridiculously easy, yet packed full of flavour, succulent and has plenty of the all important golden brown bits!!', 'https://www.recipetineats.com/tachyon/2016/08/Pulled-Pork-Tacos_4.jpg', 10, 0, 10, 4, '[{"id": "ing_pork", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_tortillas", "quantity": {"value": 1.0, "unit": "pack of 8"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_refried_beans", "quantity": {"value": 396.9, "unit": "pack"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.333, "unit": "tub of 250g"}}]', '[{"ingredients":["Pork Carnitas","Spicy Tomato Salsa Sauce","Small tortillas (corn or flour)","Avocado slices","Tomato slices","Lime wedges","White onions (, finely sliced or diced)","Coriander / cilantro leaves","Grated cheese"]},{"ingredients":["1/4 cup finely chopped onion (white, brown or yellow)","1 garlic clove (, minced)","2 tbsp olive oil","14 oz / 435 g can refried beans (I use Old El Paso)","1 tsp onion powder (or garlic powder)","1/2 tsp cumin","1/3 - 1/2 cup sour cream"],"purpose":"Dressed Up Canned Refried Beans (Note 1)"}]', '[{"description":"Heat oil in a saucepan over medium high heat. Add garlic and onion, saute for 3 minutes.","duration":3,"images":[],"step":1},{"description":"Add remaining ingredients except sour cream and stir to combine. Add about 1/4 cup sour cream, stir, then add more to achieve your desired consistency. Once the beans are heated, remove from heat.","images":[],"step":2},{"description":"Pork Carnitas Tacos","images":[],"step":3},{"description":"Warm tortillas, according to packet instructions.","images":[],"step":4},{"description":"Pile up Pork Carnitas on a plate.","images":[],"step":5},{"description":"Spoon Refried Beans onto a plate and top with grated cheese.","images":[],"step":6},{"description":"Place coriander, lime, onion, tomato and avocado onto a plate.","images":[],"step":7},{"description":"Serve with Spicy Tomato Salsa on the side as the sauce!","images":[],"step":8}]', '["gluten","milk"]', '["low_calorie"]', '{"mealType":["main_course"],"cuisine":["Mexican"],"categories":["dietary","gluten-free-recipes","mexican-recipes","pork-carnitas","pork-recipes","quick-and-easy","taco-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_674ad3132244', 'en', 'US', 'No Chop Roast Pumpkin Soup', 'A creamy luscious pumpkin soup with extra intense pumpkin flavours, made without chopping the pumpkin! The longer roast time required for the pumpkin to become soft makes the pumpkin flesh even sweeter and more intensely flavoured that usual roast pumpkin soups. You don''t even need chicken or vegetable broth/stock in this! I made this in my high performance Vitamix Blender (I am officially OBSESSED with it!!) but it can be made in any blender. Or even using a stick blender.', 'https://www.recipetineats.com/tachyon/2016/07/No-Chop-Roasted-Pumpkin-Soup_3.jpg', 5, 70, 75, 5, '[{"id": "ing_pumpkin", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_milk", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.004, "unit": "carton of 250ml"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["1.5 kg / 3 lb butternut pumpkin ((US: butternut squash), cut in half, skin on)","1 onion (, peeled (brown, yellow or white))","1 head of garlic","2 tbsp olive oil","3/4 tsp salt","Black pepper","3 - 4 cups milk (of choice)"]},{"ingredients":["Cream for drizzling","Finely chopped parsley","Garlic bread for dunking"],"purpose":"Garnish"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Place pumpkin cut side up on baking tray with onion and garlic. Drizzle with oil, sprinkle with salt and pepper. Wrap garlic in foil.","images":[],"step":2},{"title":"Bake for 70","description":"80 minutes or until the pumpkin is soft (test with skewer).","duration":75,"images":[],"step":3},{"description":"Pour 2 cups of milk into a blender.","images":[],"step":4},{"description":"Scoop seeds out of pumpkin and discard. Use a large spoon to scoop out pumpkin flesh from one pumpkin half and place into blender.","images":[],"step":5},{"description":"Peel off most of the dark burnt outer layer of onion. Cut in half (with spoon!) and transfer to blender.","images":[],"step":6},{"description":"Unwrap garlic and squeeze the flesh out of half the garlic into the blender.","images":[],"step":7},{"description":"Whizz until smooth. Adjust consistency to taste with water / milk. Adjust seasoning to taste.","images":[],"step":8},{"description":"Pour into bowls. Repeat with remaining pumpkin.","images":[],"step":9},{"description":"Drizzle with cream, sprinkle with parsley and serve with hot garlic bread on the side.","images":[],"step":10}]', '["gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["dietary","dinner-tonight","gluten-free-recipes","main-dishes","pumpkin","quick-and-easy","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a87e75d1f54f', 'en', 'US', 'Greek Lemon Rice Pilaf', 'This lemon rice pilaf is so delicious, you can eat it plain! Loaded with bright zesty flavours from lemon juice and layers of extra flavour from garlic, onion and chicken broth.', 'https://www.recipetineats.com/tachyon/2016/07/Lemon-Rice_3.jpg', 10, 20, 30, 5, '[{"id": "ing_oil", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_white_rice", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 0.9, "unit": "bunch"}}, {"id": "ing_dill", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1 1/2 tbsp extra virgin oil (or butter)","1 garlic clove (, minced)","1/2 onion (, finely chopped (white, brown, yellow))","1 1/2 cups long grain white rice (, uncooked (Note 1))","1 1/4 cups chicken broth","1 cup water","1 large lemon (1 tsp zest + 3 - 4 tbsp lemon juice)","3 tbsp finely chopped parsley","3 tbsp finely chopped dill (or sub with parsley, oregano, basil chives, mint)","Salt and pepper"]}]', '[{"description":"Heat oil over medium heat in large saucepan or small pot.","images":[],"step":1},{"description":"Add garlic and onion. Cook for 5 minutes or until translucent and sweet.","duration":5,"images":[],"step":2},{"description":"Add rice and stir until rice turns mostly translucent.","images":[],"step":3},{"description":"Add broth and water. Place lid on, bring to simmer then turn heat down to low.","images":[],"step":4},{"description":"Cook for 12 minutes or until water is evaporated.","duration":12,"images":[],"step":5},{"description":"Remove from from stove and rest for 10 minutes (keep the lid on).","duration":10,"images":[],"step":6},{"description":"Remove lid. stir through lemon zest, lemon juice, herbs and salt and pepper to taste.","images":[],"step":7},{"description":"Lovey served warm or at room temperature.","images":[],"step":8}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["main_course"],"cuisine":[],"categories":["dietary","easter-sides-fresh-light","easter-sides-warm-hearty","gluten-free-recipes","greek-recipes","italian-recipes","mediterranean-recipes","quick-and-easy","rice-recipes","rice-side-dishes","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3afa1e590bac', 'en', 'US', 'Balsamic Pork Chops', 'Super simple, yet serious flavour!! The Balsamic sauce is tangy and sweet, and this will go fantastically with any protein - chicken, beef, pork and even lamb! The flavour of this syrup is quite intense so you do not need much for each serving - just spoon a couple of tablespoons over each pork. While the total cook time may seem long, it is mostly hands off time because the balsamic syrup doesn''t need to be watched over as it reduces.', 'https://www.recipetineats.com/tachyon/2016/07/Balsamic-Pork-Chops_5.jpg', 5, 25, 30, 4, '[{"id": "ing_pork", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_balsamic_vinegar", "quantity": {"value": 1.0, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["4 pork chops (, 2.5cm / 1\" thick, about 200-250g/7-8oz each (excluding any bone) (Note 1))","1 - 2 tbsp olive oil","1 garlic clove (, minced)","1 onion (, finely sliced (~1 cup of onion, brown, yellow or white))","1 cup balsamic vinegar","1/3 cup / 60g brown sugar (Note 2)","Salt and pepper"]},{"ingredients":["Crumbled goats cheese or feta","Fresh parsley or thyme"],"purpose":"Garnish (optional)"}]', '[{"description":"Sprinkle both sides of pork with salt and pepper.","images":[],"step":1},{"description":"Heat 1 tbsp oil in a large skillet over medium high heat. Cook the first side for 4 minutes until it has a lovely dark gold crust, then turn and cook the other side for 3 minutes. (Note 3)","duration":4,"images":[],"step":2},{"description":"Transfer to a plate, cover loosely with foil.","images":[],"step":3},{"description":"Add 1 tbsp oil to the skillet, still on medium high. Add garlic and onion, cook until translucent - around 3 minutes.","images":[],"step":4},{"description":"Add balsamic vinegar and brown sugar. Stir until the sugar is melted. When it comes to a simmer, adjust the heat so it is bubbling gently, not rapidly.","images":[],"step":5},{"description":"Simmer for ~5 to 8 minutes or until it reduces by almost half and is a THIN syrup. Then add the pork back into the skillet, including all the juices on the plate. Simmer, turning pork to reheat, for 2 minutes or until the the sauce becomes syrupy (to your taste) and pork is reheated. (Note 4)","duration":2,"images":[],"step":6},{"description":"Serve, garnished with crumbled goats cheese if desired.","images":[],"step":7}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","dinner-tonight","gluten-free-recipes","main-dishes","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_aa2bb99d5e87', 'en', 'US', 'Chorizo & Kale Risotto', 'Risotto in a rich Chorizo flavoured tomato broth! I used kale to add greens and a pop of colour, but you can substitute with spinach, or even leave it out!', 'https://www.recipetineats.com/tachyon/2016/04/Chorizo-Risotto_1.jpg', 10, 25, 35, 4, '[{"id": "ing_chicken", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_chorizo", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_arborio_rice", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_kale", "quantity": {"value": 5.0, "unit": "unit"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["3 cups chicken broth/stock (, salt reduced)","2 tbsp tomato paste","2 cups tomato passata (Note 1)"],"purpose":"Stock"},{"ingredients":["1/2 tbsp olive oil","350g (12oz) chorizo (, some sliced and the remainder finely chopped (Note 7))","1 onion (, finely chopped (brown, white or yellow))","2 garlic cloves (, minced)","1 1/2 cups arborio rice (risotto rice), uncooked (Note 2)","1/2 cup white wine (sub with chicken broth or water)"],"purpose":"Risotto"},{"ingredients":["5 cups kale leaves (, removed from stalk, torn into bite size pieces (packed) (Note 3))","2 - 4 + tbsp butter","Freshly grated parmesan cheese (optional)"],"purpose":"To Finish"}]', '[{"description":"Whisk together Stock ingredients in a small saucepan over medium low heat. Once heated, turn down to low and keep warm. (Note 4)","images":[],"step":1},{"description":"Heat oil in a pot or large skillet over high heat. Add chorizo and cook until golden brown. Remove into a bowl and set aside.","images":[],"step":2},{"description":"There should be some red oil in the skillet from the chorizo. If not, add a bit of oil.","images":[],"step":3},{"description":"Turn heat down to medium. Cook onion and garlic for 5 minutes until translucent.","duration":5,"images":[],"step":4},{"description":"Add rice and stir to coat grains in oil until translucent.","images":[],"step":5},{"description":"Add wine, turn up the heat to medium high and simmer, stirring, until most of the wine has evaporated.","images":[],"step":6},{"description":"Turn heat down to medium low and add 1 cup of stock. Stir leisurely until mostly absorbed into the rice, then add another cup of stock. Continue 1 cup at a time until the risotto is just cooked - squeeze a grain, it should still be firm but cooked through - about 15 minutes. Make the risotto as saucy (or not) as you want - liquid will absorb in the next step so lean towards saucier than what you want.","images":[],"step":7},{"description":"When the risotto is done (Note 5), remove it from the stove.","images":[],"step":8},{"description":"Add butter (the more the better!) and stir energetically - this will activate the starch and make it creamy. Stir chorizo in then partially stir kale through the risotto. Plonk the lid on and let it rest for 3 minutes (kale will wilt in this step).","duration":3,"images":[],"step":9},{"description":"Adjust salt and pepper to taste. Serve immediately! (Note 6)","images":[],"step":10}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","dinner-tonight","gluten-free-recipes","italian-recipes","main-dishes","quick-and-easy","risotto-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_87663ec90e4a', 'en', 'US', 'Brown Sugar Broiled Salmon', 'Really great quick way to cook salmon - a brown sugar glaze smeared on salmon fillets, optional addition of veggies, then broil it. Terrific caramelisation, really quick delicious dinner.', 'https://www.recipetineats.com/tachyon/2016/04/One-Tray-Brown-Sugar-Salmon_5.jpg', 4, 8, 12, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_es_asparagus", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_broccoli", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 0.6, "unit": "punnet of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.037, "unit": "jar of 400g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}]', '[{"ingredients":["4 x 5-8 oz/ 150-180g salmon fillets (, skin on or off (I use on))","2 bunches asparagus (Note 1)","1 bunch broccolini (Note 1)","1 cup cherry tomatoes","1 tbsp olive oil","Salt and pepper"]},{"ingredients":["1 tbsp Dijon mustard","1 tbsp mayonnaise (I use whole egg mayonnaise)","2 tbsp brown sugar","1/4 tsp cayenne pepper"],"purpose":"Glaze (Note 2)"}]', '[{"description":"Preheat broiler/griller on high. Place the oven shelf 6\"/15cm from the heat source.","images":[],"step":1},{"description":"Spray a baking tray with oil (I use olive oil, any is fine).","images":[],"step":2},{"description":"Pile asparagus, broccolini and cherry tomatoes on the baking tray. Drizzle with olive oil and sprinkle with salt and pepper. Toss with hands then spread out on the tray, mostly on one layer.","images":[],"step":3},{"description":"Wedge salmon pieces on the tray between the vegetables. Sprinkle with salt and pepper.","images":[],"step":4},{"description":"Mix Glaze ingredients together. Slather on the salmon - tops and sides.","images":[],"step":5},{"title":"Grill/broil for 8 minutes","description":"don''t flip. The salmon should be caramelised and the inside should be blushing pink.","duration":8,"images":[],"step":6},{"description":"Rest for 2 minutes then serve with crusty bread rolls.","duration":2,"images":[],"step":7}]', '["egg","fish","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","dinner-tonight","fish-recipes","gluten-free-recipes","low-calorie-recipes","main-dishes","one-pot-recipes","quick-and-easy","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_56520156fdc2', 'en', 'US', 'Greek Slow Roasted Leg of Lamb', 'This is the Greek way of roasting lamb - slow roasted until tender enough to pull apart, braised in a lemon garlic thyme broth that infuses the flesh with flavour and reduces into a lemony, herby jus rather than having to fuss with making a gravy. Easier and more foolproof than traditional roast lamb leg (the carving sort with pink meat) because there’s no worry about overcooking. There’s also a rosemary garlic version of this slow cooked leg (with gravy!) and plenty of other roast lamb recipes - take the Roast Lamb Matchmaker to find your perfect one!This recipe takes 7 1/2 hours to cook (7 hours in oven plus 30 minutes resting time) and is best served freshly made, so start late morning to serve for dinner, or get up VERY early to serve for lunch!Source: adapted from this Slow Roasted Leg of Lamb by Kalofagas', 'https://www.recipetineats.com/tachyon/2016/03/Greek-Slow-Roast-Lamb_7.jpg', 15, 420, 465, 8, '[{"id": "ing_garlic", "quantity": {"value": 20.0, "unit": "pack of 3 heads"}}, {"id": "ing_lamb", "quantity": {"value": 3.175, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 2000.0, "unit": "pack of 1kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.4, "unit": "bunch"}}, {"id": "ing_rosemary", "quantity": {"value": 0.12, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_bayleaves", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_lemon", "quantity": {"value": 0.15, "unit": "net of 500g"}}, {"id": "ing_wine", "quantity": {"value": 0.5, "unit": "bottle of 750ml"}}, {"id": "ing_chicken", "quantity": {"value": 0.225, "unit": "kg"}}]', '[{"ingredients":["12 cloves of garlic, peeled","7 lb / 3.5 kg leg of lamb (, bone-in (Note 1 & Note 3 for roasting times for larger/smaller))","1 1/2 tsp cooking salt / kosher salt (double for flakes or flaky salt)","1/2 tsp black pepper","3 tsp paprika powder (regular / sweet, not spicy or smoked)","3 tsp garlic powder (or sub with onion powder)","2 tbsp olive oil","2 large onions (, quartered (white, brown, yellow, red))","10 sprigs of thyme","3 sprigs rosemary","3 tsp dried oregano","3 dried bayleaves (or 5 fresh)","1/2 cup lemon juice ((2 - 3 lemons), plus more to taste)","1 1/2 cups white wine (or sub with chicken broth/stock, low salt)","2 cups chicken broth/stock (, low sodium)"]}]', '[{"description":"Stuff incisions with garlic, season, roast leg uncovered 30 min at 240°C/465°F (220°C fan). Lower to 180°C/350°F (160°C fan). Put everything else in pan, flip leg upside down, fill with hot water 1/4 way up, roast covered 3 1/2 hours. Flip lamb, roast covered another 2 1/2 hours, then brown uncovered 30 minutes. Strain pan juices, serve!","images":[],"step":1},{"description":"Preheat oven to 240°C/465°F (220°C fan-forced). (Note 2)","images":[],"step":2},{"title":"Garlic incisions","description":"Use a small knife to make around 25 incisions all over the lamb, with most on the top. Cut around 6 cloves into slivers and stuff them into the incisions.","images":[],"step":3},{"title":"Season","description":"Sprinkle the lamb generously all over with salt, pepper, paprika and garlic powder. Drizzle with olive oil and rub all over the lamb.","images":[],"step":4},{"title":"30 minute browning","description":"Place the lamb in a roasting pan and roast for 30 minutes or until it has a nice brown crust.","duration":30,"images":[],"step":5},{"title":"Prepare for slow-roasting","description":"Remove from the oven. Turn the oven down to 180°C/350°F (160°C fan-forced). Turn the lamb upside down. Pour / place all the remaining ingredients in the pan around the lamb (including remaining garlic cloves). Fill the roasting pan with hot water so it comes up about 1/4 - 1/3 of the way up the height of the lamb.","images":[],"step":6},{"title":"Slow roast part 1 (3 1/2 hours)","description":"Cover with lid or with baking/parchment paper then 2 layers of foil. Roast for 3 1/2 hours. Top up water if it dries out (e.g. Might happen if your foil is loose) ** See Note 3 for larger/smaller leg roasting times **","images":[],"step":7},{"title":"Slow roast part 2 (2 1/2 hours)","description":"Remove the roast from the oven and remove the lid/foil. Turn the lamb over so it is the right side up. Cover again and roast for a further 2 1/2 hours, or until you can pull meat apart easily with forks.","images":[],"step":8},{"title":"Finish browning","description":"Remove cover and roast for a further 20 - 30 minutes (to brown).","images":[],"step":9},{"title":"Rest","description":"Remove from the oven and transfer lamb to serving platter. Cover loosely with foil and rest for 30 - 40 minutes.","duration":35,"images":[],"step":10},{"title":"Sauce","description":"Strain liquid into a clear jug. The fat will rise to the top. Scoop/pour most of it off and discard (I get 3/4 - 1 cup). There should be 2 - 3 cups of Sauce left. Adjust salt, pepper and lemon to taste.","images":[],"step":11},{"description":"Serve lamb with the Sauce on the side and Truly Crunchy Roast Potatoes* or Greek Lemon Potatoes. The lamb will stay warm enough for 1 hour so you can roast / prep other sides during this time.","images":[],"step":12}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Greek"],"categories":["dietary","easter-mains","easter-recipes","gluten-free-recipes","greek-recipes","lamb-recipes","main-dishes","mediterranean-recipes","roast-lamb","roasts","slow-cooked-fall-apart","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6aab0fa959bd', 'en', 'US', 'Apple Cider Glazed Pork Tenderloin', 'Apple cider is the secret to a marinade that makes pork tenderloin incredibly moist with a gorgeous glaze! The marinade also does double duty as the sauce. You will be amazed at the incredible flavour in this with so few ingredients! I used Rochdale Apple Cider for this recipe - a New Zealand cider that is available at all major liquor outlets in Australia including Dan Murphy''s and Liquorland.', 'https://www.recipetineats.com/tachyon/2016/01/Apple-Cider-Glazed-Pork-Tenderloin_6.jpg', 5, 30, 35, 4, '[{"id": "ing_pork", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_apples", "quantity": {"value": 0.312, "unit": "kg"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_honey", "quantity": {"value": 0.06, "unit": "jar of 500g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1 lb/500g pork tenderloin"]},{"ingredients":["11 oz/330ml sweet apple cider (alcoholic aka \"hard cider\") - I used Rochdale Apple Cider (Note 1)","1 bay leaf (, dried (or 2 fresh))","2 tbsp honey","2 tbsp brown sugar","2 garlic cloves (, minced)","1/2 tsp salt","Black Pepper"],"purpose":"Marinade"},{"ingredients":["1 tbsp olive oil"],"purpose":"To Cook"},{"ingredients":["1 1/2 tbsp butter","1 tbsp dijon mustard","Salt and pepper"],"purpose":"Sauce"}]', '[{"description":"Mix the Marinade ingredients in a bowl.","images":[],"step":1},{"description":"Place Marinade and pork in a large ziplock bag and marinate in the refrigerator overnight, up to 24 hours.","images":[],"step":2},{"description":"To Cook","images":[],"step":3},{"description":"Remove pork in the marinade from the refrigerator 30 minutes prior to cooking (to bring to room temperature).","images":[],"step":4},{"description":"Preheat oven to 180C/350F.","images":[],"step":5},{"description":"Heat olive oil in a skillet over medium high heat. Remove pork from marinade (reserve marinade) and place in pan. Sear until golden brown all over - don''t let it burn (Note 2).","images":[],"step":6},{"description":"Transfer skillet to the oven and roast for 15 to 20 minutes, or until the internal temperature using a meat thermometer reads 145F/62C. (Note 3)","duration":17.5,"images":[],"step":7},{"description":"Remove pork from skillet onto a plate and cover loosely with foil to rest while you make the sauce.","images":[],"step":8},{"description":"Place skillet on the stove over high heat with butter. When the butter is melted, add reserved Marinade and mustard. Whisk until smooth.","images":[],"step":9},{"description":"Bring to boil, then turn heat down so it is simmering VERY rapidly, and cook until the liquid becomes syrupy - about 4 to 5 minutes. Adjust salt to taste.","images":[],"step":10},{"description":"Remove skillet from the stove, roll pork in the sauce, then remove and slice. Pour remaining sauce in the skillet into a jug and serve on the side.","images":[],"step":11},{"description":"I served this with a fennel apple salad on the side. (Note 4)","images":[],"step":12}]', '["milk","mustard"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","gluten-free-recipes","pork-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6d7326623ca1', 'en', 'US', 'Cheesy Italian Arancini Rice Balls', 'A classic Italian dish, I''ve made these bite size to be finger food but they are typically made larger to serve as a meal or appetiser! This makes 25 mini Arancini balls about the size of a golf ball. :) Great for making ahead - they keep in the fridge for 3 days, then just reheat at 350F/180C for 10 minutes!', 'https://www.recipetineats.com/tachyon/2015/10/Cheesy-Italian-Arancini-Balls_600px_Featured.jpg', 30, 60, 90, 25, '[{"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_rice", "quantity": {"value": 225.0, "unit": "pack"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_chicken", "quantity": {"value": 0.525, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.6, "unit": "pack of 125g"}}, {"id": "ing_parsley", "quantity": {"value": 0.75, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_bread", "quantity": {"value": 0.375, "unit": "loaf"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}]', '[{"ingredients":["2 tbsp butter","2 garlic cloves (, minced)","1 small onion (, finely diced (white, yellow, brown))","1 1/2 cups risotto rice (arborio)","1/2 cup white wine (or substitute with broth/stock or water)","3 1/2 cups chicken broth/stock","1 cup milk"],"purpose":"Baked Risotto"},{"ingredients":["1 egg","1 cup grated cheddar cheese","3/4 cup grated mozzarella cheese","2 1/2 tbsp finely chopped fresh parsley (, or 1 1/2 tbsp dried parsley (Note 1))","1/2 tsp salt","Pepper"],"purpose":"Rice Mixture"},{"ingredients":["1/2 cup plain flour","1/2 tsp salt","Black pepper","2 eggs","2 cups panko breadcrumbs","Cooking oil (I used vegetable oil)"],"purpose":"Coating"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Melt butter in a skillet over medium heat. Add garlic and onion and cook for 5 minutes until soft.","duration":5,"images":[],"step":2},{"description":"Add rice and stir until grains turn translucent. Add wine and turn up the heat to medium high. Cook until liquid is mostly absorbed/evaporated.","images":[],"step":3},{"description":"Add chicken broth and milk. Stir, bring to simmer, cover, then transfer to oven. Baked, covered, for 30 to 40 minutes until all liquid is absorbed and rice is tender.","duration":35,"images":[],"step":4},{"description":"Remove from oven and allow to cool. Add Rice Mixture Ingredients and mix to combine. Cover and transfer to refrigerator for at least 3 hours or preferably overnight.","images":[],"step":5},{"description":"Mix flour, salt and pepper in a shallow bowl, eggs in another (lightly beaten) and panko in a third shallow bowl.","images":[],"step":6},{"description":"Measure out a level (packed) ice cream scoop of rice mixture (about 2 1/2 tbsp) and roll into a ball. (Note 2)","images":[],"step":7},{"description":"Roll in flour, then dredge in egg mixture, then coat in panko, pressing to coat. (Note 3) Repeat with remaining mixture.","images":[],"step":8},{"description":"Cook","images":[],"step":9},{"description":"In a medium saucepan, pour in 1\"/2.5cm depth of oil and heat over medium high heat.","images":[],"step":10},{"description":"Toss in a breadcrumb and if it starts sizzling immediately, the oil is hot enough.","images":[],"step":11},{"description":"Carefully transfer a few balls into the hot oil, using a spoon. Turn frequently so they cook golden evenly, and when they are a deep golden brown, remove onto a paper towel lined plate to drain.","images":[],"step":12},{"description":"Repeat with remaining balls.","images":[],"step":13},{"description":"To Serve","images":[],"step":14},{"description":"Serve with Marinara Sauce (optional) (Note 4) sprinkled with finely chopped fresh parsley if desired.","images":[],"step":15}]', '["egg","gluten","milk"]', '[]', '{"mealType":["snack"],"cuisine":["Italian"],"categories":["deep-fried-recipes","dietary","finger-food","gluten-free-recipes","italian-recipes","quick-and-easy","side-dishes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8eb5ae9eb3cd', 'en', 'US', 'One Tray Oven Baked Honey Chili Lime Salmon with Potatoes and Beans', 'Easy midweek cooking without compromising on flavour! Golden crunchy roasted potatoes with salmon glazed with chili, lime and honey and a side of greens to make it a complete meal. If you use smaller salmon, you can most certainly make this for 4.', 'https://www.recipetineats.com/tachyon/2015/06/Chili-Lime-Salmon-Overhead.jpg', 15, 35, 50, 3, '[{"id": "ing_salmon_fillets", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_honey", "quantity": {"value": 0.045, "unit": "jar of 500g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_potato", "quantity": {"value": 14.0, "unit": "bag of 2kg"}}, {"id": "ing_butter", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_green_beans", "quantity": {"value": 226.8, "unit": "pack"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_ime", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["3 pieces of salmon (5 - 7 oz / 150 - 200g each, skin on or off)"]},{"ingredients":["1 large lime ((or 2 small ones) - 1 1/2 tsp zest + 3 tbsp lime juice)","1 1/2 tbsp honey","1 tbsp soy sauce (or fish sauce)","2 garlic cloves (, minced)"],"purpose":"Marinade"},{"ingredients":["14 oz / 450 g baby potatoes (, halved (Note 1))","1 1/2 tbsp melted butter (or olive oil)","1/8 tsp salt","1 garlic clove (, minced (optional))"],"purpose":"Roast Potatoes"},{"ingredients":["8 oz / 250 g green beans (, trimmed)","1 tsp olive oil"],"purpose":"Beans"},{"ingredients":["1/2 tsp salt","Black pepper","1 birds eye chili (, frozen whole (or finely chopped unfrozen chili))","1 lime"],"purpose":"Garnish and seasoning"}]', '[{"description":"Preheat oven to 180C/350F and place a large rimmed baking tray in the oven.","images":[],"step":1},{"description":"Combine the Marinade ingredients in a bowl or ziplock bag. Add the salmon and set aside to marinate for 20 minutes (while the potatoes are roasting). (Note 2)","duration":20,"images":[],"step":2},{"description":"Toss the Roast Potato ingredients in a bowl. Remove the tray from the oven and pour the potatoes onto the tray. Place in the oven and roast for 20 minutes. (Note 3)","duration":20,"images":[],"step":3},{"description":"Combine the Beans ingredients into bowl you used for the potatoes (so residual butter sticks to beans) and toss.","images":[],"step":4},{"description":"Remove salmon from the Marinade, reserving the Marinade.","images":[],"step":5},{"description":"Remove tray from the oven. Move the potatoes to one side and place the salmon in the middle, skin side down. Pile the beans into one corn of the tray (don''t spread them out, they will overcook).","images":[],"step":6},{"description":"Sprinkle over the salt and pepper all over everything on the tray.","images":[],"step":7},{"description":"Drizzle some Marinade on each salmon, then place the tray into the oven and bake for 4 minutes per 1/2 inch / 5 minutes per 1.5 cm of thickness (thickest part of the salmon). My salmon was 1.25 inches / 3 cm thick so I baked it for 10 minutes. (Note 4)","duration":4,"images":[],"step":8},{"description":"Turn the grill/broiler onto maximum. (Note 5) Drizzle the remaining Marinade onto the salmon and grill for 2 minutes or until light golden on top.","duration":2,"images":[],"step":9},{"description":"Rest for 3 minutes. Use a grater to grate frozen chili and lime zest over the salmon. Serve with lime wedges on the side.","duration":3,"images":[],"step":10}]', '["fish","gluten","milk","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dietary","dinner-tonight","fish-recipes","gluten-free-recipes","low-calorie-recipes","main-dishes","most-popular","one-pot-recipes","quick-and-easy","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2a0c27569716', 'en', 'US', 'Glazed Stovetop Carrots', 'These carrots look and taste like they''ve been roasted - but they are made on the stove! Great recipe for holiday feasts when the oven is tied up with other dishes!', 'https://www.recipetineats.com/tachyon/2015/05/Stovetop-Glazed-Carrots_2-SQ.jpg', 10, 10, 20, 4, '[{"id": "ing_carrot", "quantity": {"value": 6.0, "unit": "pack of 1kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_honey", "quantity": {"value": 0.02, "unit": "jar of 500g"}}, {"id": "ing_water", "quantity": {"value": 0.167, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["6 carrots (, peeled, cut into quarters lengthwise then halved)","3 tbsp olive oil","2 tsp honey","2/3 cup water","Salt and pepper","Parsley (, finely chopped, for garnish (optional))"]}]', '[{"description":"Heat the oil in a very large skillet over medium high heat.","images":[],"step":1},{"description":"Add carrots and shake the pan so they are (almost all) cut side down. Cook for 5 to 7 minutes without stirring until golden brown.","duration":6,"images":[],"step":2},{"description":"Add remaining ingredients except parsley. Stir once then allow to cook until the water is evaporated and carrots start to caramelise - about 3 minutes.","images":[],"step":3},{"description":"Stir once or twice until caramelised, then transfer to serving dish.","images":[],"step":4},{"description":"Sprinkle with parsley and serve warm","images":[],"step":5}]', '[]', '["gluten_free","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["dietary","easter-sides-warm-hearty","gluten-free-recipes","quick-and-easy","side-dishes","side-salads","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d03a39ad02e0', 'en', 'US', 'Creamy Dreamy Cauliflower Soup', 'This cauliflower soup is made extra creamy and thick with the addition of potatoes. You can make it even richer by stirring in some cream or creme fraiche, but I don''t think it''s needed.', 'https://www.recipetineats.com/tachyon/2015/04/Creamy-Cauliflower-Soup_680px.jpg', 10, 15, 25, 4, '[{"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_cauliflower", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_potato", "quantity": {"value": 8.0, "unit": "bag of 2kg"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}]', '[{"ingredients":["3 garlic cloves (, roughly chopped)","1 kg / 2 lb (1 medium head) cauliflower (, florets broken off and stalk roughly chopped)","8 oz / 250 g (1 large, 2 small) potatoes (, peeled and roughly diced)","1 large onion (, peeled and roughly chopped)","2 cups milk (any - dairy, non dairy, full fat or low fat)","2 cups chicken broth / stock","Salt and pepper to taste"],"purpose":"Soup"},{"ingredients":["Thyme (highly recommended!)","Cream and/or olive oil (, to drizzle)"],"purpose":"To garnish (optional)"}]', '[{"description":"Place all Soup ingredients (except salt and pepper) in a large pot over high heat and bring to boil, then turn down to medium and let it simmer for 10 to 15 minutes, or until the cauliflower is very soft.","duration":12.5,"images":[],"step":1},{"description":"Use a hand held blender and blend until smooth (Note 1), then add salt and pepper to taste.","images":[],"step":2},{"description":"If the soup is too thick for your taste, add more milk, water or stock (and more salt if needed). If you want it even thicker, let it simmer on the stove for a while longer to reduce down and thicken (be careful not to reduce it so much that it is too salty).","images":[],"step":3},{"description":"Serve, garnished with fresh thyme leaves and drizzled with cream and/or olive oil, if desired.","images":[],"step":4}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["main_course"],"cuisine":[],"categories":["dietary","dinner-tonight","gluten-free-recipes","main-dishes","quick-and-easy","soup-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ba6e5107af38', 'en', 'US', 'Juicy Cuban Mojo Pork Roast (Chef Movie recipe)', 'This is the Mojo Marinated Roast Pork from the John Favreau movie "Chef". The recipe was created by rock star LA chef Roy Choi. The flavours of the marinade are classic Cuban, citrusy and strong. It infuses into the pork incredibly well. I made this with boneless pork shoulder because I made it specifically with the intention of using leftovers to make Cubanos (Cuban sandwiches) and boneless is easier to slice. But it can also be made with bone-in pork (add 0.5kg/1lb to the pork weight). This roast is extremely tender though is still suited to carving rather than "pulling apart" with tongs - though I also provide the cook times for a pulled Cuban pork option!', 'https://www.recipetineats.com/tachyon/2015/03/Cuban-Mojo-Marinated-Pork-sliced_680px.jpg', 15, 180, 195, 8, '[{"id": "ing_olive_oil", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_oranges", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_oranges", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_ime_juice", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_mint", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 2.667, "unit": "pack of 3 heads"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_pork_shoulder", "quantity": {"value": 1.814, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 0.15, "unit": "net of 500g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}]', '[{"ingredients":["3/4 cup extra virgin olive oil","1 cup cilantro / coriander, (lightly packed)","1 tbsp orange zest","3/4 cup orange juice, (fresh)","1/2 cup lime juice","1/4 cup mint leaves, (lightly packed)","8 garlic cloves","1 tbsp fresh oregano leaves, (packed (or 1/2 tbsp dried oregano))","2 tsp ground cumin","1 tsp salt","1 tsp black pepper"],"purpose":"Marinade"},{"ingredients":["4 lb / 2 kg pork shoulder / pork butt, (skinless and boneless (not loin or leg roast, will dry out))"],"purpose":"Pork"},{"ingredients":["2 tbsp lime juice","1/4 cup orange juice","Salt and pepper"],"purpose":"Mojo Sauce"}]', '[{"description":"Combine Marinade ingredients in a food processor and blend until the herbs and garlic are finely chopped. Alternatively, you can finely chop/mince the garlic and herbs then mix all ingredients in a bowl.","images":[],"step":1},{"description":"Place in a large ziplock bag with the pork. Place in the fridge overnight (in a bowl, just to be safe).","images":[],"step":2},{"description":"Remove the pork from the Marinade and leave on counter for 1 hour (bring to room temp). Reserve the Marinade.","images":[],"step":3},{"description":"Preheat oven to 220°C/425°F (200°C fan).","images":[],"step":4},{"description":"Roast, uncovered, for 30 minutes. Base with pan juices.","duration":30,"images":[],"step":5},{"description":"Reduce heat to 190°C/375°F (170°C). Roast for another 1 1/2 - 2 hours, basting every half hour, until the internal temperature reaches 70°/160°F. At this temperature, the pork is cooked, still juicy, and carvable, as it is intended to be (Note 1)","images":[],"step":6},{"description":"Fall-apart tender alternative (not slicable, meat falls apart): Roast at 160°C/320°F (all oven types) for 3 1/2 hours, or until the meat can be easily shredded using 2 forks (check on side).","images":[],"step":7},{"description":"Remove from the oven and place on a plate, loosely covered with foil. Rest for 20 minutes before serving with the Mojo Sauce on the side. I decorated mine with pan fried slices of oranges and extra cilantro/coriander leaves.","duration":20,"images":[],"step":8},{"description":"Place the reserved Marinade, Mojo Sauce ingredients and 2 tbsp of the roasting pan drippings into a small saucepan. Bring to boil and add salt and pepper to taste. You might also want to add more lime juice or even a touch of sugar. Turn the heat down and simmer for 1 minute, then remove from the stove and set aside.","duration":1,"images":[],"step":9}]', '[]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["main_course"],"cuisine":["Caribbean","Cuban"],"categories":["dietary","easter-mains","easter-recipes","gluten-free-recipes","main-dishes","pork-recipes","roasts","south-american-recipes","sunday-supper"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ad34742fdd9b', 'en', 'US', 'Fall Apart Oven Baked Ribs with Chipotle BBQ Sauce', 'Pork ribs slow cooked in the oven until tender and falling off the bone, coated with a homemade Barbecue Sauce with a great balance of sweet, tang and heat. A one pan recipe! This is one of those recipes that is very forgiving with both cook time and substituting ingredients.', 'https://www.recipetineats.com/tachyon/2015/01/DSC_0424.jpg', 15, 2, 17, 10, '[{"id": "ing_paprika", "quantity": {"value": 0.562, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.562, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.15, "unit": "jar of 50g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_beef_steak", "quantity": {"value": 2.268, "unit": "kg"}}, {"id": "ing_beer", "quantity": {"value": 1.0, "unit": "bottle of 330ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_chipotle_in_adobo_sauce", "quantity": {"value": 99.225, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 15.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 7.5, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_vinegar", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 50.0, "unit": "bottle"}}, {"id": "ing_tabasco_sauce", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}]', '[{"ingredients":["1 1/2 tbsp sweet paprika","1 tbsp salt","1 1/2 tbsp garlic powder","1/2 tbsp black pepper","1 tbsp onion powder","1/2 tbsp cayenne pepper","1/2 tbsp dried thyme","1/2 tbsp dried oregano"],"purpose":"Rub"},{"ingredients":["5 lb / 2.5 kg American style pork ribs (, cut into individual ribs (to fit into one baking dish))","1 bottle dark beer (About 12 oz / 375 ml. Stout, porter or a dark ale)"],"purpose":"Ribs"},{"ingredients":["14 oz / 400g can crushed tomato","3.5 oz / 100g can Chipotle in Adobo Sauce (, chipotle and sauce (1/2 a standard can) (Note 1))","1 large onion ((brown, white or yellow), diced)","2 garlic cloves (, minced)","1 tbsp tomato paste","2 tbsp brown sugar","1/4 cup white wine vinegar (or 2 tbsp normal white vinegar + 1 tsp sugar)","1/3 cup Worcestershire sauce","2 tbsp Tabasco sauce (, or other hot sauce. Adjust to taste.)","1/2 tbsp salt","Black pepper"],"purpose":"Chipotle BBQ Sauce (\"Sauce\")"},{"ingredients":["Fresh coriander/cilantro leaves","Lime wedges"],"purpose":"To Serve"}]', '[{"description":"Combine the Rub ingredients in a bowl.","images":[],"step":1},{"description":"Pat the ribs dry, then rub with the Rub. If time permits, refrigerate, covered, for at least 2 hours or overnight.","images":[],"step":2},{"description":"Take ribs out of the fridge, place in a large baking dish in a single layer (squished is ok, they will shrink slightly).","images":[],"step":3},{"description":"Preheat oven to 160C/325F.","images":[],"step":4},{"description":"Pour beer into the baking dish and cover with a lid (use foil if you don''t have a lid). Place in the oven and cook for 1 hour.","images":[],"step":5},{"description":"Meanwhile, make the Sauce.","images":[],"step":6},{"description":"Take out of the oven and remove lid. Pour the sauce over the ribs, then return to the oven (uncovered).","images":[],"step":7},{"description":"Bake for 45 minutes to 1 hour 15 minutes, turning once or twice, until the ribs are cooked to your liking. The meat should be very tender and comes off the bone easily, and the sauce should be thick and \"jam-like\". If the pan starts looking dry, add a splash of water.","duration":45,"images":[],"step":8},{"description":"To finish the ribs off, grill/broil for 5 to 10 minutes to get a nice browned finish on top (this is an optional step).","duration":7.5,"images":[],"step":9},{"description":"Serve, garnished with fresh coriander/cilantro leaves and wedges of lime.","images":[],"step":10},{"description":"Blend or process the canned tomato in a food processor, Chipotle in Adobo Sauce, onion and garlic.","images":[],"step":11},{"description":"Stir through remaining ingredients. Set aside until required.","images":[],"step":12}]', '[]', '["gluten_free","high_protein"]', '{"mealType":["main_course"],"cuisine":["American","Tex-Mex"],"categories":["dietary","gluten-free-recipes","pork-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b4a2dcc9354a', 'en', 'US', 'Ham and Corn Chowder with Potato', 'A hearty, creamy soup made using leftover Christmas ham (or store bought leg ham). Refer to Note 5 for a shortcut way of making this soup which will let you get this soup on the table in just 15 minutes. Make this a more complete meal by adding extra vegetables! I often add frozen diced vegetables - just add it when you add the corn into the soup. This serves 3 normal people or 2 very hungry people. It is a very filling soup!', 'https://www.recipetineats.com/tachyon/2014/12/Ham-Potato-Corn-Chowder_3.jpg', 5, 20, 25, 3, '[{"id": "ing_ham", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_potato", "quantity": {"value": 2.0, "unit": "bag of 2kg"}}, {"id": "ing_corn", "quantity": {"value": 0.562, "unit": "can of 400g"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 1.5, "unit": "L"}}, {"id": "ing_thyme", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1 1/2 cups ham (, roughly chopped (Note 1))","1/2 tbsp olive oil","3 tbsp butter","1 garlic clove (, minced)","1 small onion (, diced (or half large onion) (yellow, brown or white))","2 potatoes (, peeled and diced into 8mm / 1/3\" cubes (Note 2))","1 1/2 cups frozen corn (or drained canned corn)","5 tbsp flour","2 cups milk (I use low fat but full fat will work too)","1 cup chicken stock","1 1/2 - 2 cups water","1 1/2 tsp fresh thyme leaves ((or 1 tsp dried thyme), plus extra for garnish)","1/2 tsp salt","Black pepper"]}]', '[{"description":"Melt butter in a large saucepan over medium heat.","images":[],"step":1},{"description":"Add the onion and garlic and sauté for 5 minutes until translucent. Do not let the onion brown.","duration":5,"images":[],"step":2},{"description":"Add the flour and whisk until mixed through the butter. Pour 1 cup of milk in and whisk until it starts to thicken (around 1 1/2 minutes), then pour the remaining cup of milk in. Whisk until it thickens - around 1 to 1 1/2 minutes. Then add the chicken stock, and 1 1/2 cups of water and whisk until combined.","images":[],"step":3},{"description":"Increase heat to medium high and add the potatoes into the soup. Cook for 10 to 12 minutes (Note 3), whisking fairly regularly to ensure the soup doesn''t stick to the bottom of the saucepan. The soup will thicken as it cooks. Use the remaining 1/2 cup of water if the soup gets too thick before the potato has finished cooking.","duration":11,"images":[],"step":4},{"description":"Just before the potato has finished cooking, add the corn in (just to heat it through).","images":[],"step":5},{"description":"While the potato is cooking, heat olive oil in a small fry pan over high heat. Add the ham and sauté for 1 - 2 minutes until nicely browned. Remove fry pan from the heat and set aside. (Note 4)","duration":1.5,"images":[],"step":6},{"description":"When the potato is cooked (tender but still holding its shape), remove the soup from the stove and stir through most of the thyme and ham (reserve a bit for garnish).","images":[],"step":7},{"description":"If the soup is too thick for your liking, use water (or milk) to get the soup to your desired consistency. Add the salt and 5 grinds of black pepper, then do a taste test and adjust the saltiness if required.","images":[],"step":8},{"description":"Serve, garnished with remaining thyme leaves and ham.","images":[],"step":9}]', '["gluten","milk"]', '[]', '{"mealType":["main_course"],"cuisine":[],"categories":["dietary","dinner-tonight","gluten-free-recipes","leftover-ham-recipes","main-dishes","most-popular","pork-recipes","quick-and-easy","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_dc20affe8f0c', 'en', 'US', 'Mini Pizza Potato Skins', 'These are great for entertaining as they are "one bite" appetisers that can be prepared ahead. I make these my "express" way by microwaving the potatoes, then crisping them in the oven. You could also bake them so I''ve provided directions for that as well. Use whatever toppings take your fancy!', 'https://www.recipetineats.com/tachyon/2014/11/Mini-Pizza-Potato-Skins-2.jpg', 5, 20, 25, 8, '[{"id": "ing_potato", "quantity": {"value": 8.0, "unit": "bag of 2kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_pizza_sauce", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 14.4, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["8 baby potatoes (, about the size of a golf ball (chat, new or salad potatoes))","2 tbsp olive oil (, or oil spray)","1/2 cup pizza sauce (, preferably homemade (see notes))","1 cup grated melting cheese (I used mozzarella. Tasty, cheddar, gruyere and swiss would also also well)","48 pieces mini pepperoni slices (see notes)","Finely chopped parsley (, to garnish (optional))"]}]', '[{"description":"Preheat oven to 220C/430F.","images":[],"step":1},{"description":"Prick each potato 2 to 3 times with a fork. Spread them out evenly around the edge of the microwave turntable (or in a circle for microwaves without a turntable). Microwave on high for 2 minutes. Turn potatoes over then microwave for a further 2 minutes, or until just cooked. Remove from microwave.","duration":2,"images":[],"step":2},{"description":"Cut each potato in half, then use a teaspoon to scoop the filling out, leaving a thin layer of potato.","images":[],"step":3},{"description":"Place the potatoes on a baking tray, skin side up.","images":[],"step":4},{"description":"Brush with olive oil (or spray) then sprinkle with a pinch of salt.","images":[],"step":5},{"description":"Bake skins for 10 minutes or until the skin is browned and a bit crispy.","duration":10,"images":[],"step":6},{"description":"Turn the grill (broiler) on.","images":[],"step":7},{"description":"Flip the potato skins over so the bowl side is facing up.","images":[],"step":8},{"description":"Fill each potato skin with about 1 1/2 tsp of pizza sauce, then top with grated cheese.","images":[],"step":9},{"description":"Place 2 to 3 pepperoni''s on each, then place under the grill (broiler) for 3 to 5 minutes until the cheese is melted and the pepperoni is just starting to brown.","duration":4,"images":[],"step":10},{"description":"Sprinkle with parsley, if using, and serve immediately.","images":[],"step":11}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["snack"],"cuisine":[],"categories":["dietary","finger-food","gluten-free-recipes","most-popular","quick-and-easy","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_06e21519a760', 'en', 'US', 'Hot Mushroom and Pepperoni Pizza Dip', 'If you love pizza, and you love dip, then you are going fall in love with this pizza dip! This makes ALOT of dip - it serves at least 8 to 12. I made it this big so it resembles a pizza in size.', 'https://www.recipetineats.com/tachyon/2014/11/Hot-Pepperoni-Pizza-Dip-2.jpg', 15, 20, 35, 8, '[{"id": "ing_cream_cheese", "quantity": {"value": 8.0, "unit": "block of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.3, "unit": "tub of 250g"}}, {"id": "ing_pizza_sauce", "quantity": {"value": 150.0, "unit": "bottle"}}, {"id": "ing_black_pepper", "quantity": {"value": 1.5, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 50.0, "unit": "pack of 1kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.8, "unit": "pack of 125g"}}, {"id": "ing_cheese", "quantity": {"value": 8.0, "unit": "block of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 1.5, "unit": "jar of 50g"}}, {"id": "ing_french_sticks", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}]', '[{"ingredients":["8 oz / 250g cream cheese (, at room temperature)","1/3 cup grated parmesan cheese","1/2 cup sour cream (light or full fat)"],"purpose":"Base"},{"ingredients":["1 cup pizza sauce (see notes for fast homemade pizza sauce recipe)","1/2 cup pepperoni (, roughly diced)","1/3 cup onion (, diced (brown, white, yellow or red))","1/2 cup mushrooms (, roughly diced)"],"purpose":"Pizza Topping"},{"ingredients":["1 cup mozzarella cheese (, grated)","1/2 cup tasty cheese (, grated (or any other melting cheese with flavour) (see notes))","12 slices pepperoni"],"purpose":"Cheese topping"},{"ingredients":["2 french sticks (, cut into slices)","2 cloves garlic (, halved (skin on))"],"purpose":"Garlic Toast"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Heat a non stick fry pan over high heat.","images":[],"step":2},{"description":"Add the diced pepperoni and fry for 1 minute until it starts to brown.","duration":1,"images":[],"step":3},{"description":"Then add the onions and sauté for 1 minute. Then add the mushrooms and cook for 30 seconds.","duration":1,"images":[],"step":4},{"description":"Remove onion mixture from the fry pan and place onto a plate with a paper towel (to drain the excess fat).","images":[],"step":5},{"description":"Combine the Base ingredients in a bowl and mix until smooth and combined.","images":[],"step":6},{"description":"Spread the Base in a 20 cm / 8 inch base with a 24 cm / 9 inch rim pie dish.","images":[],"step":7},{"description":"Spread the pizza sauce over the Base, then sprinkle with the onion mixture.","images":[],"step":8},{"description":"Sprinkle over the tasty cheese, then the mozzarella cheese.","images":[],"step":9},{"description":"Place sliced pepperoni over the cheese.","images":[],"step":10},{"description":"Bake in the oven for 15 to 20 minutes, until golden brown and bubbling. Check it at 15 minutes.","duration":17.5,"images":[],"step":11},{"description":"Serve immediately with Garlic Toast.","images":[],"step":12},{"description":"Spread french stick slices on 2 baking trays (or one very large one).","images":[],"step":13},{"description":"Bake for 5 to 8 minutes until crispy and lightly browned.","duration":6.5,"images":[],"step":14},{"description":"Remove from oven and rub each piece lightly with the cut side of the garlic.","images":[],"step":15}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["dietary","dip-recipes","gluten-free-recipes","most-popular","quick-and-easy","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7430d3074471', 'en', 'US', 'Sweetened Condensed Milk Caramel (Dulce de Leche)', 'Dulce De Leche is the king of all caramels. And it''s effortless if you make it in a slow cooker with sweetened condensed milk! I have also provided directions for making this on the stove top as well.', 'https://www.recipetineats.com/tachyon/2014/10/Dulce-De-Leche-4.jpg', 1, 480, 481, 3, '[{"id": "ing_milk", "quantity": {"value": 2.0, "unit": "L"}}]', '[{"ingredients":["2 cans sweetened condensed milk (395g / 14 oz each) (see notes)"]}]', '[{"description":"Place cans in slow cooker on their side. Don’t worry about removing the label.","images":[],"step":1},{"description":"Cover cans with hot tap water until the water is about 5 cm / 2” above the cans.","images":[],"step":2},{"description":"Set slow cooker for 8 hours on low.","images":[],"step":3},{"description":"If you want your caramel to be a really dark golden colour, slow cook for a further 2 hours.","images":[],"step":4},{"description":"Remove cans from slow cooker using tongs. DO NOT OPEN CANS WHILE HOT. The contents might burst out – dangerous!","images":[],"step":5},{"description":"Submerge cans in cold water to cool before opening. It only takes 10 minutes or so.","images":[],"step":6},{"description":"If not using right away, transfer into jars or air tight containers, do not leave it in the can.","images":[],"step":7},{"description":"To make on stove top","images":[],"step":8},{"description":"Place cans in a large pot and cover with water so that it is 5 cm / 2 inches above the cans.","images":[],"step":9},{"title":"Place on a small burner and bring JUST to boil","description":"don''t walk away, you don''t want to leave the cans boiling in water.","images":[],"step":10},{"description":"Then turn down the heat to medium low (or low if you stove is powerful), put the lid on and let it simmer for 2 hours to get the consistency and colour as per the photos you see, otherwise for 3 hours if you want to darker and thicker.","images":[],"step":11},{"description":"Remove from the pot. Allow to cool before opening (otherwise the Dulce De Leche might burst out when you open it). You can speed up the process by submerging the cans in cold water.","images":[],"step":12}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["South American"],"categories":["dessert-recipes","dietary","frosting-and-icing","gluten-free-recipes","main-dishes","quick-and-easy","slow-cooker-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ea484fd10fc8', 'en', 'US', 'Tzatziki', 'Recipe video above. Nobody makes Tzatziki as good as your yiayia, but just in case you want to make one using actual measurements (rather than a little bit of this and a slosh of that!), here is my recipe. Use as a dip for vegetable sticks and warm pita bread, as a sauce for Gyros, Doner kebabs and chicken skewers, and dolloping on Greek baked chicken pieces.', 'https://www.recipetineats.com/tachyon/2026/03/Tzatziki_7.jpg', 20, 6, 26, 1, '[{"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.375, "unit": "tub of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_dill_optional_see_note", "quantity": {"value": 0.03, "unit": "kg"}}]', '[{"ingredients":["2 Lebanese cucumbers (Persian cucumbers)","1 1/4 cups Greek yoghurt (or Greek-style yogurt, preferably full fat)","1 tbsp lemon juice","1 tbsp extra virgin olive oil (or more if you want richer)","1 garlic clove (, minced)","1/4 heaped teaspoon cooking salt / kosher salt (halve for table salt, +50% for flakes)","Pinch of black pepper","2 tbsp finely chopped dill ((or mint), OPTIONAL - see note)"]}]', '[{"title":"Deseed, shred and squeeze","description":"Cut the cucumber in half lengthwise. Use a teaspoon to scrape the watery seeds out. Coarsely grate the cucumber using a box grater. Then wrap in a tea towel and squeeze to remove excess liquid.","images":[],"step":1},{"title":"Mix","description":"Place cucumber in a bowl. Add remaining ingredients then mix to combine.","images":[],"step":2},{"description":"Set aside for at least 20 minutes for the flavours to meld.","images":[],"step":3},{"description":"Use immediately or keep in an airtight container in the fridge for 3 days.","images":[],"step":4}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner","lunch"],"cuisine":["Greek"],"categories":["dip-recipes","greek-recipes","quick-and-easy","sauces"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f61a9450d69c', 'en', 'US', 'Whipped Feta Dip', 'Recipe video above. This will save you when you need something fast, low-cost but a little different to take to gatherings! Serve with slices of bread, crackers of vegetable sticks served up on a big platter that everyone will dive into.', 'https://www.recipetineats.com/tachyon/2022/10/Feta-Dip_1.jpg', 10, 0, 10, 8, '[{"id": "ing_feta_cheese", "quantity": {"value": 400.0, "unit": "block of 200g"}}, {"id": "ing_cream_cheese", "quantity": {"value": 125.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.417, "unit": "pack of 3 heads"}}, {"id": "ing_lemon", "quantity": {"value": 0.015, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_honey", "quantity": {"value": 0.09, "unit": "jar of 500g"}}, {"id": "ing_pistachios", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_parsley", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 0.015, "unit": "net of 500g"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_lebanese", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_crackers", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}]', '[{"ingredients":["400g / 10 oz Danish feta (, at room temp (ie. the creamy sort, not crumbly Greek sort, Note 1))","125g/ 4 oz cream cheese (at room temp) or 3/4 cup yogurt (Note 2)","1/4 tsp garlic (, crushed using garlic press (Note 3))","1 1/2 tsp lemon zest (, optional)","3 tbsp extra virgin olive oil"],"purpose":"Creamy Feta Dip:"},{"ingredients":["3 tbsp honey","1 tbsp extra virgin olive oil","2 tbsp pistachios (, roughly chopped)","1/2 tsp parsley (, finely minced)","Pinch of chilli / red pepper flakes (, optional)","Sprinkle of lemon zest (, optional)"],"purpose":"Toppings (Note 4 for subs):"},{"ingredients":["Thick slices of bread (, warmed)","Lebanese (, pita or flat bread wedges)","Crackers","Veggie sticks (ie crudités)"],"purpose":"Dipping options – choose:"}]', '[{"title":"Feta Dip","description":"Place all ingredients except the oil in a food processor. Blitz on high for 10 seconds or until pretty smooth, scraping down the sides once. (You could also use a stick blender, but a stand mixer will not work)","duration":0.16666666666666666,"images":[],"step":1},{"title":"Olive oil","description":"With the motor running, slowly pour the olive oil through the feeder then blitz until the dip is smooth and creamy, scraping down the sides as needed.","images":[],"step":2},{"description":"Spread on a shallow bowl-plate / regular plate so it''s around 1.5cm / 0.6\" thick. Use the back of a spoon to create swirls for the honey and oil to pool in.","images":[],"step":3},{"description":"Drizzle over the honey and olive oil. Sprinkle with pistachios, parsley, chilli and lemon. Serve immediately with dippers of choice!","images":[],"step":4}]', '["gluten","milk"]', '["keto_friendly","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Mediterranean","Western"],"categories":["dip-recipes","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_444d0370291d', 'en', 'US', 'Hot Buffalo Chicken Dip', 'Recipe video above. This might be the best hot dip recipe I know! Moreish, meaty, spicy, cheesy oozy goodness. This version has a few more steps than the quick and easy "dump it all in a bowl" recipes. But the end result is better. Far better! Quite possibly my all-time favourite hot dip.SPICINESS: Pretty spicy but not "blow-your-head-off". If you''re concerned, hold back half the buffalo sauce, then just stir it in at the end just before baking, adding as much as you think you can handle!', 'https://www.recipetineats.com/tachyon/2021/02/Buffalo-Chicken-Dip_9-1.jpg', 15, 30, 45, 16, '[{"id": "ing_mayonnaise", "quantity": {"value": 0.125, "unit": "jar of 400g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.2, "unit": "tub of 250g"}}, {"id": "ing_butter", "quantity": {"value": 0.333, "unit": "block of 250g"}}, {"id": "ing_parsley", "quantity": {"value": 0.75, "unit": "bunch"}}, {"id": "ing_dill", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.005, "unit": "bottle of 500ml"}}, {"id": "ing_lemon", "quantity": {"value": 0.005, "unit": "net of 500g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 2.5, "unit": "bottle"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_hot_sauce", "quantity": {"value": 1.667, "unit": "bottle of 150ml"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_cream_cheese", "quantity": {"value": 250.0, "unit": "block of 250g"}}, {"id": "ing_cheese", "quantity": {"value": 250.0, "unit": "block of 250g"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 1.25, "unit": "block of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.5, "unit": "bunch"}}, {"id": "ing_green_onion", "quantity": {"value": 1.5, "unit": "bunch"}}, {"id": "ing_corn", "quantity": {"value": 0.003, "unit": "can of 400g"}}]', '[{"ingredients":["1/3 cup mayonnaise (, whole egg (Hellman''s and S&W recommended) (Note 1))","1/3 cup sour cream (, full fat)","1/3 cup buttermilk (Note 2)","2 1/2 tbsp parsley (, preferably curly, very finely minced (sub flatleaf parsley))","2 tsp fresh dill (, finely minced)","1/2 tsp apple cider vinegar (or more lemon)","1/2 tsp lemon juice (or more cider vinegar)","1/2 tsp worcestershire sauce","1/2 tsp onion powder","1 tsp garlic powder"],"purpose":"Homemade Ranch:"},{"ingredients":["1 cup Frank’s Red Hot sauce (Note 3)","3 cups shredded cooked chicken breast (Note 4)","250g/ 8oz cream cheese (, cut into 8 cubes)","2 1/2 cups colby cheese (, shredded yourself (Note 5))","1 1/4 cups cheddar cheese (, shredded yourself (Note 5))","1 tsp ground black pepper","1/2 cup green onion (, finely sliced)"],"purpose":"Buffalo Chicken Dip:"},{"ingredients":["Extra green onion","Corn chips, crackers, crostini, vegetable sticks (especially celery - very on-theme!)"],"purpose":"Garnish & serving:"}]', '[{"description":"Preheat oven to 180°C/350°F.","images":[],"step":1},{"title":"Make ranch dressing base","description":"Combine mayonnaise, sour cream, buttermilk, parsley, dill, vinegar, lemon, Worcestershire, onion powder and garlic powder in a bowl. Set aside for 10 minutes to let the flavours develop.","duration":10,"images":[],"step":2},{"title":"Simmer on stove","description":"Transfer the ranch dressing to a saucepan over medium low heat. Add cream cheese, hot sauce and pepper. Stir until cream cheese melts and the mixture is combined and smooth.","images":[],"step":3},{"title":"Mix","description":"Transfer the hot cream mixture in a large bowl. Add chicken, ¾ of the cheese (reserve rest for top) and green onion. Mix well until fully combined.","images":[],"step":4},{"description":"Transfer into a 6 cup / 1.5L casserole dish, top with remaining cheese.","images":[],"step":5},{"description":"Bake 20 minutes until bubbly and golden. For more brown spots, flick the broiler/grill on for the last few minutes.","images":[],"step":6},{"description":"Garnish with reserved green onion. Devour recklessly with corn chips, crackers or if you''re feeling a bit virtuous, perhaps some vegetable sticks …","images":[],"step":7}]', '["egg","milk"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["snack"],"cuisine":["American"],"categories":["dip-recipes","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ce7ff42059a7', 'en', 'US', 'Pesto', 'Recipe video above. This is how I make basil pesto. Make it smooth for the best flavour when tossed through pasta, or chunkier if you want to use it as a dip. See in post for a list of chunky vs smooth and a list of uses! Also see how to use pesto to make a JUICY Pesto Pasta (hint: it''s not just pasta and pesto).', 'https://www.recipetineats.com/tachyon/2019/02/Pesto_6.jpg', 10, 0, 10, 1, '[{"id": "ing_pine_nuts", "quantity": {"value": 2.0, "unit": "pack of 100g"}}, {"id": "ing_basil", "quantity": {"value": 1.2, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.105, "unit": "L"}}]', '[{"ingredients":["2 tablespoons pine nuts","2 cups / 60g / 2oz fresh basil leaves (tightly pack measuring cup, Note 1)","1/2 cup (50 g) parmesan, (finely grated (tightly pack the cup))","1/2 tsp cooking/kosher salt","1/4 tsp black pepper","1 garlic clove (, small)","7 tbsp extra virgin olive oil (, best quality)"]}]', '[{"title":"Toast pine nuts","description":"Preheat small skillet over medium high heat (no oil). Add pine nuts and toast until light brown. Immediately remove and let cool slightly.","images":[],"step":1},{"title":"Blitz pesto","description":"Place all ingredients except olive oil in a food processor or blender. Blitz until finely chopped.","images":[],"step":2},{"title":"Add oil while blitzing","description":"With the motor running, slowly pour the oil in through the feeder tube. Blitz until smooth (or to desired consistency), adding a touch of extra oil (or water) if required to help it blitz.","images":[],"step":3},{"title":"Handheld blender stick","description":"Place all ingredients (including oil) in a bowl. Blitz with hand held blender until smooth.","images":[],"step":4},{"description":"Storage and Use:","images":[],"step":5},{"description":"Store in a super airtight container in the fridge for up to 3 days, or freezer for 3 months. If it''s not a super airtight container, smooth the surface and cover with a thin layer of olive oil - basil goes brown when in contact with air.","images":[],"step":6},{"title":"Makes enough for","description":"300g/10oz dried pasta of choice (can stretch to 350g/12oz). See here for how to make a great simple pesto pasta!","images":[],"step":7}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dinner"],"cuisine":["American-Italian"],"categories":["dinner-tonight","dip-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_183b515ef6ad', 'en', 'US', 'Christmas Appetiser: Italian Cheese Loaf', 'Recipe video above. Looks so festive, easy to make and a flavour bomb inside! Terrific economical, make ahead alternative to expensive cheese platters. It''s like an antipasto platter in cheese log form! Adaptable and versatile! **Can freeform it instead of using loaf pan**', 'https://www.recipetineats.com/tachyon/2018/12/Italian-Cheese-Log-Christmas-Appetizer_6a.jpg', 20, 0, 20, 15, '[{"id": "ing_cream_cheese", "quantity": {"value": 500.0, "unit": "block of 250g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.2, "unit": "tub of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_salami", "quantity": {"value": 0.18, "unit": "kg"}}, {"id": "ing_olives", "quantity": {"value": 112.5, "unit": "bottle"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_tomato", "quantity": {"value": 0.22, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_rosemary", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_jatz_or_other_crackers", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["500g/ 1 lb cream cheese (, softened (Note 1))","1/3 cup sour cream (Note 2)","1/2 tsp EACH thyme, oregano, basil, rosemary, black pepper (OR 1 tsp Italian Seasoning)","1 tsp EACH garlic powder, salt, red pepper/chilli flakes (adjust to taste)","2 cup cheddar or other cheese (, freshly grated (Note 3))","280g / 9 oz roasted peppers (, drained and finely chopped)","180g / 6 oz salami (, finely chopped (Note 4))","3/4 cup green olives (, finely chopped)","1/3 cup green onion (, finely minced (3 - 4 stalks))"],"purpose":"Cheese Log:"},{"ingredients":["220g / 7 oz sun dried tomato strips with OIL (, roughly chopped)","1/4 cup parsley (, finely chopped (or chives))","Rosemary sprigs (decoration)","Jatz or other crackers (, for serving)"],"purpose":"Topping/serving:"}]', '[{"description":"Spray a loaf pan with oil then line with cling wrap with overhang.","images":[],"step":1},{"description":"Mix Cheese Log ingredients together. Taste and adjust salt if needed (bear in mind saltiness of crackers you are serving with).","images":[],"step":2},{"description":"Scrape into loaf pan and level surface, pressing to remove air pockets. Smaller pan = taller loaf.","images":[],"step":3},{"description":"Cover with cling wrap overhang and refrigerate for 4 hours+ (up to 1 week).","images":[],"step":4},{"description":"Turn out onto platter, peel off cling wrap.","images":[],"step":5},{"description":"Top with sun dried tomato and pour over oil. Garnish with parsley and rosemary sprigs to give it a festive look.","images":[],"step":6},{"description":"Best to serve closer to room temp than fridge cold. Serve with crackers! Knives for smearing optional - it''s soft enough to scoop with crackers.","images":[],"step":7}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["main_course"],"cuisine":[],"categories":["dip-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ca4c2c2a5ee6', 'en', 'US', 'Avocado Dip', 'Recipe video above. It''s like a cross between Guacamole and Hummus! This is a great bigger-batch avocado dip that takes minutes to make, for those times when you want one avocado to go further, or when you''ve got friends who are split between the Guac and Hummus camps. See notes for more variations.', 'https://www.recipetineats.com/tachyon/2018/06/Avocado-Hummus_7.jpg', 5, 0, 5, 6, '[{"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.09, "unit": "tub of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_pine_nuts", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1 large avocado, 300g/10oz whole (or 2 medium)","1 can chickpeas, drained (~14oz / 420g)","3 tbsp tahini (sesame paste) OR yoghurt","2 - 3 tbsp fresh lemon or lime juice","1/4 cup coriander / cilantro leaves, packed (some stems ok)","2 - 3 tbsp extra virgin olive oil","1 large garlic clove","Salt and pepper to taste","1 - 2 tbsp water as required"]},{"ingredients":["Extra virgin olive oil","Coriander/cilantro leaves","Pine nuts (, toasted (hummus-style!))"],"purpose":"Garnishes (optional):"}]', '[{"description":"Cut avocado in half, remove seed. Use spoon to scoop flesh into food processor. Add remaining ingredients. Start with just a pinch of salt because canned chick peas vary in saltiness. Whizz until smooth, scraping down sides as required.","images":[],"step":1},{"title":"Adjust","description":"sour with lemon, salt, pepper, and dip consistency with water. Whizz again.","images":[],"step":2},{"description":"Dollop onto plate. Use spoon to make swirls on top. Drizzle over olive oil, sprinkle to pine nuts, garnish with coriander. Serve with chips, crackers or pita bread, see notes for most amazing stay-green storage tip!","images":[],"step":3}]', '["milk","sesame"]', '["gluten_free","vegetarian"]', '{"mealType":["snack"],"cuisine":[],"categories":["dip-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d382233bf48b', 'en', 'US', 'Spinach Artichoke Dip', 'Recipe video above. This dip is a hit with everyone! Particularly terrific served warm, but also fantastic at room temperature, this dip is soft so crackers won’t break when you scoop up dip! Quick to make using a microwave, though you can bake if you prefer (it doesn’t add anything to flavour, but some like to brown the top, I don''t).', 'https://www.recipetineats.com/tachyon/2017/05/Spinach-Artichoke-Dip-7.jpg', 10, 0, 10, 10, '[{"id": "ing_artichoke_hearts_in_brine", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_spinach", "quantity": {"value": 250.0, "unit": "bag of 250g"}}, {"id": "ing_cream_cheese", "quantity": {"value": 250.0, "unit": "block of 250g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.125, "unit": "jar of 400g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_cheese", "quantity": {"value": 250.0, "unit": "block of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["400 g / 14 oz artichoke hearts in brine (, drained (Note 1))","250 g / 8 oz frozen chopped spinach (, thawed (Note 2))","250 g / 8 oz Philadelphia cream cheese (Note 3)","1 tsp garlic powder (or 2 garlic cloves, minced)","1/3 cup mayonnaise (Note 4)","½ cup sour cream or yoghurt (full fat recommended)","1 cup grated cheese (, any with flavour like Cheddar, Colby, Tasty Cheese (Australian) (Note 5))","½ cup grated parmesan cheese","Salt and pepper to taste"]}]', '[{"description":"Roughly chop the artichokes.","images":[],"step":1},{"description":"Squeeze excess liquid out of spinach. Either use paper towels or a clean dishtowel, or my method is to use a colander and press liquid out using a wooden spoon.","images":[],"step":2},{"description":"Place cream cheese in a large heatproof bowl. Microwave in 2 x 30 second bursts or until softened. Mix until smooth.","images":[],"step":3},{"description":"Add remaining ingredients. Mix until just combined (don’t overmix vigorously, otherwise you’ll smush the artichokes and spinach).","images":[],"step":4},{"description":"Warm in microwave to your taste. Adjust salt and pepper to taste.","images":[],"step":5},{"description":"Best served warm but terrific served at room temperature too! Serve with your favourite crackers, vegetable sticks and chips.","images":[],"step":6}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["snack"],"cuisine":[],"categories":["dip-recipes","quick-and-easy","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6d5eb45101a0', 'en', 'US', 'Queso Dip (Mexican Cheese Dip)', 'Recipe video above. Copycat of Queso Dip (Mexican Cheese Dip) sold in jars in the US and at Mexican restaurants. Made with real cheese and stays silky smooth even when it cools! AND it reheats perfectly. Makes about 2.5 cups. IMPORTANT: Please read Note 1 regarding store bought shredded cheese.', 'https://www.recipetineats.com/tachyon/2017/07/Chile-Con-Queso-14.jpg', 5, 10, 15, 10, '[{"id": "ing_cheddar_cheese", "quantity": {"value": 2.5, "unit": "block of 250g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.037, "unit": "pack of 400g"}}, {"id": "ing_butter", "quantity": {"value": 0.5, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.25, "unit": "pack of 1kg"}}, {"id": "ing_milk", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_can_green_chile_fire_roasted", "quantity": {"value": 113.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_milk", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2 1/2 cups (tightly packed) cheddar cheese, freshly shredded (Important - read Note 1)","1 tbsp cornflour / cornstarch","1/2 tbsp (10g) unsalted butter","1 large garlic clove (, finely minced)","1/4 small white onion (, very finely chopped (~1/4 cup))","375g / 13 oz evaporated milk (1 can) (, not low fat)","1 small tomato (, finely diced (3/4 cup) (Note 2))","1/4 tsp each onion powder, garlic powder, cumin","113g /4 oz can chopped green chile, fire roasted (Subs Note 3)","1/4 cup coriander / cilantro (, finely chopped )","2 - 3 tbsp milk (, any type (to loosen, as needed))","Salt (, to taste (cheese brands differ in saltiness, may not need))"]}]', '[{"title":"Toss","description":"Place cheese and cornflour in a bowl, toss to coat.","images":[],"step":1},{"description":"Melt butter over medium heat in a large saucepan or small pot.","images":[],"step":2},{"title":"Sauté","description":"Add garlic and onion, cook slowly for 3 minutes or until onion is translucent but not browned. Add tomato (including juices) and cook for 2 minutes until tomato is slightly softened.","duration":3,"images":[],"step":3},{"description":"Add evaporated milk and cheese. Stir, then add chiles and Spices.","images":[],"step":4},{"title":"Melt","description":"Stir until cheese melts and it becomes a silky sauce.","images":[],"step":5},{"title":"Add salt to taste","description":"amount required depends on saltiness of cheese used - and stir through coriander.","images":[],"step":6},{"title":"Adjust consistency","description":"Stir in milk or water to adjust consistency (I use 2 tbsp) - the dip thickens when it cools, and milk can be added later to adjust to taste.","images":[],"step":7},{"description":"Remove from heat. Serve warm or at room temperature - it will be soft and scoopable even when it cools.","images":[],"step":8},{"description":"Store in the refrigerator. When refrigerated, it becomes the consistency of the cheese spread sold in jars that are not in the refrigerator section. Reheat in microwave and adjust consistency as desired with a tiny bit of milk. If you add too much, just put on stove again until it thickens. Freezes 3 months, fridge 5 days.","images":[],"step":9}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Mexican"],"categories":["dip-recipes","mexican-recipes","nachos-recipes","quick-and-easy","super-bowl-party-food","taco-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_007b90b4daa0', 'en', 'US', 'Easy French Onion Soup Dip', 'Throw back from the 80''s! This French Onion Dip is the ONLY recipe I make using a store bought packet mix. I can''t let it go - it brings me right back to my childhood!', 'https://www.recipetineats.com/tachyon/2017/06/French-Onion-Dip-with-Soup-Mix-5.jpg', 5, 0, 5, 10, '[{"id": "ing_sour_cream", "quantity": {"value": 1.6, "unit": "tub of 250g"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.003, "unit": "jar of 400g"}}, {"id": "ing_onion", "quantity": {"value": 40.0, "unit": "pack of 1kg"}}]', '[{"ingredients":["400 g / 14 oz sour cream (full fat is better)","½ cup mayonnaise (Mayo labelled “whole egg” mayo is best)","40 g / 1.4 oz French Onion Soup Mix (store bought) (, salt reduced is best)"]}]', '[{"description":"Mix ingredients together in a bowl. Rest for 5 minutes or until onion bits in the soup mix become softened.","duration":5,"images":[],"step":1},{"description":"Serve with your favorite chips!","images":[],"step":2}]', '["egg","milk"]', '["gluten_free","vegetarian"]', '{"mealType":["snack"],"cuisine":[],"categories":["dip-recipes","quick-and-easy","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7b5852dc9efc', 'en', 'US', 'Cheese and Bacon Dip', 'Recipe video above. This warm dip is really creamy, super cheesy and loaded with bacon. It takes minutes to make in the microwave! Serving it in a bread bowl is optional - I love it because I love tearing into the dip soaked bread. This makes around 4 1/2 - 5 cups of dip. Plenty!', 'https://www.recipetineats.com/tachyon/2016/10/Cheese-and-Bacon-Dip-1_-3.jpg', 10, 25, 35, 10, '[{"id": "ing_bacon", "quantity": {"value": 1.75, "unit": "pack of 200g"}}, {"id": "ing_cream_cheese", "quantity": {"value": 250.0, "unit": "block of 250g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.6, "unit": "tub of 250g"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.281, "unit": "jar of 400g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.8, "unit": "pack of 125g"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_jatz_ritz_or_other_plain_savoury_cracker", "quantity": {"value": 5.0, "unit": "pack"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_crackers", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["350 g / 12 oz bacon (, chopped)","250 g / 8 oz cream cheese (, softened)","1 cup sour cream (preferably full fate)","3/4 cup mayonnaise","1 tsp garlic powder (or sub with onion powder)","1 cup shredded tasty or cheddar cheese (Note 1)","1 cup shredded mozzarella cheese (Note 1)","1 cup shallots / scallions (, chopped (~4 - 5 stalks))"]},{"ingredients":["1 round cob bread (sourdough works best)","5 Jatz / Ritz or other plain savoury cracker (, crushed (Note 2))","Oil spray"],"purpose":"Bread bowl & topping (optional)"},{"ingredients":["Crackers (, chips, toasted bread)"],"purpose":"To serve"}]', '[{"description":"Cook bacon in a non stick skillet / fry pan over high heat until browned. Transfer to paper towel lined plate to drain.","images":[],"step":1},{"description":"Mix cream cheese, mayonnaise, sour cream and garlic powder together in a heat proof bowl.","images":[],"step":2},{"description":"Stir through most of the bacon, all the cheese and most of the shallots. Microwave on high for 3 minutes. The dip may look like the oil from the cheese has separated. Just stir well and it will come (and stay) together.","duration":3,"images":[],"step":3},{"description":"If serving as is, pour into a serving bowl, top with remaining bacon and shallots.","images":[],"step":4},{"description":"Serve with crackers, chips and the bread you pulled out to create the bread bowl (I toast it).","images":[],"step":5},{"description":"If making this in a bread bowl. use a small knife to cut a circle on the top of the cob loaf then remove enough bread to make a bowl. Pour the dip into the bowl.","images":[],"step":6},{"description":"Top with crushed crackers, spray with oil. Bake for 20 minutes at 180C/350F until top is golden.","duration":20,"images":[],"step":7},{"description":"Top with remaining bacon and shallots. Serve warm.","images":[],"step":8}]', '["gluten","milk"]', '["keto_friendly","low_calorie"]', '{"mealType":["snack"],"cuisine":[],"categories":["dip-recipes","most-popular","quick-and-easy","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_580e47ca69f2', 'en', 'US', 'Jalapeno Popper Dip', 'Jalapeno Poppers - in dip form! This dip is warm, creamy and cheesy with a lovely kick from the Jalapeños. It''s not overly spicy because the jalapeño is balanced out by the creaminess. Most Jalapeño Popper dips have similar ingredients except I use canned rather than fresh jalapeños. The slight tang from the brining liquid is great to cut through the richness of the dip. Also I use slightly more sour cream than most so the dip stays soft even when it cools. This makes 4 cups of dip, enough for 1 large cob loaf (put leftovers in ramekins and make smaller ones).', 'https://www.recipetineats.com/tachyon/2016/07/Jalapeno-Popper-Dip_HERO.jpg', 10, 40, 50, 8, '[{"id": "ing_cream_cheese", "quantity": {"value": 6.0, "unit": "block of 250g"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.125, "unit": "jar of 400g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.3, "unit": "tub of 250g"}}, {"id": "ing_cumin", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 0.75, "unit": "block of 250g"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.6, "unit": "pack of 125g"}}, {"id": "ing_jalape_os", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["6 oz / 180g Philadelphia cream cheese (, at room temperature)","1/3 cup mayonnaise","1/2 cup sour cream","1/2 tsp cumin powder","1/2 tsp each onion powder and garlic powder (or 1 tsp of one of these)","3/4 cup grated cheddar cheese (or tasty, Monterey Jack or other flavoured cheese)","3/4 cup grated Mozzarella Cheese","3/4 - 1 cup canned jalapeños (, drained and finely chopped)","1/2 tsp salt","Pepper"],"purpose":"Dip"},{"ingredients":["1 Cob Bread (round loaf 25cm / 10\" diameter) (optional)","1 tbsp butter (, melted)","1/2 cup panko breadcrumbs"],"purpose":"Bread & Topping"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Cut the top off the bread, use a small knife to cut a ring and pull out the bread to form a bowl (leaving a 1cm / 1/2\" border/crust). Place bread on foil.","images":[],"step":2},{"description":"Mix together cream cheese, mayonnaise and sour cream. Add remaining Dip ingredients, mix combine. Pour into bread bowl.","images":[],"step":3},{"description":"Mix together butter and panko. Sprinkle over top of dip.","images":[],"step":4},{"description":"Wrap bread in foil. Bake for 30 minutes, then roll foil edges down and bake for a further 10 to 15 minutes until the panko is golden, the dip is bubbling and the bread is golden (insert knife into centre to ensure it is hot). (Note 1)","duration":30,"images":[],"step":5},{"description":"Serve with corn chips and the bread pulled out of the bread bowl (cut into chunks. Toasting is optional)","images":[],"step":6}]', '["gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["snack"],"cuisine":["American"],"categories":["dip-recipes","quick-and-easy","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d9f336ec3ba1', 'en', 'US', 'Four-Layer Drip Dog Birthday Cake', 'Recipe video above. A four-layer drip cake that looks so real, it''s hard to believe it''s made entirely from dog-friendly ingredients!!Frosting note: While it might sound weird for a frosting to be made of whipped potato, dogs don''t care! It looks and behaves like buttercream frosting, but is dog friendly so you can use it in abundance to decorate the cake (not recommended for usual frostings made with cream cheese/peanut butter etc etc)', 'https://www.recipetineats.com/tachyon/2021/04/Dozer-dog-birthday-cake-main.jpg', 30, 40, 130, 20, '[{"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.2, "unit": "jar of 375g"}}, {"id": "ing_oil", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_milk", "quantity": {"value": 0.167, "unit": "L"}}, {"id": "ing_maple_syrup", "quantity": {"value": 0.333, "unit": "bottle of 250ml"}}, {"id": "ing_carrot", "quantity": {"value": 375.0, "unit": "pack of 1kg"}}, {"id": "ing_flour", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.062, "unit": "tub of 200g"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.75, "unit": "tub of 500g"}}, {"id": "ing_water", "quantity": {"value": 0.167, "unit": "L"}}, {"id": "ing_blue_food_colouring_gel", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.188, "unit": "pack of 400g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.75, "unit": "tub of 500g"}}, {"id": "ing_silver_blue_and_white_balls_candles_birthday_sign", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["2 large eggs (, at room temperature (Note 1))","1/2 cup peanut butter (spread or pure)","1/4 cup oil (canola or vegetable)","2/3 cup milk (or water)","1/3 cup honey or maple syrup (or apple sauce, else skip it)","2 1/2 cups carrot, grated (2 large carrots, peeled)","2 cups flour, plain/all-purpose (or whole wheat / wholemeal flour)","2 1/2 tsp baking soda (sub 6 tsp baking powder)"],"purpose":"Dog birthday cake:"},{"ingredients":["1kg / 2 lb potatoes (, peeled, cut into chunks)","3/4 - 1 cup yoghurt ((plain unsweetened) or water)","Water or milk as needed (to adjust consistency)","Blue food colouring gel (or liquid) (or other colour of choice, Note 2)"],"purpose":"Dog-friendly \"Buttercream\" (Whipped Potato Yogurt):"},{"ingredients":["1/2 cup cornflour / cornstarch","1/4 cup yoghurt (plain, unsweetened)","1 - 2 tbsp milk (, as needed)"],"purpose":"Drippy Frosting"},{"ingredients":["Silver, blue and white balls, candles, birthday sign"],"purpose":"Decorations"}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan).","images":[],"step":1},{"title":"Cake pans","description":"Grease and line the base of 2 x 15cm (6\") cake pans that are 7.5cm (3\") deep (Note 3 for other cake pan sizes).","images":[],"step":2},{"title":"Mix wet ingredients","description":"Whisk together eggs, peanut butter, oil, honey and milk (small peanut butter lumps are ok).","images":[],"step":3},{"title":"Add dry ingredients","description":"Stir in carrot. Add flour and baking soda, stir until just combined (over-mixing = hard cake = sad birthday pooch!)","images":[],"step":4},{"title":"Fill cake pans","description":"Divide batter between cake pans, spread and smooth surface.","images":[],"step":5},{"title":"Bake","description":"Bake 30 minutes or until skewer inserted into the centre comes out clean. Cool on racks.","images":[],"step":6},{"title":"Level and halve","description":"Trim the mound off the top of each cake to make the tops flat. Then cut each cake horizontally in half using a serrated knife so you have four, even, flat cake layers. Frost per below.","images":[],"step":7},{"description":"Dog-friendly \"Buttercream\"","images":[],"step":8},{"title":"Cook potatoes","description":"Boil, steam or microwave potato until very soft.","images":[],"step":9},{"title":"Whip","description":"Whip potato and yoghurt with an electric beater until fluffy and smooth as possible – about 1 1/2 minutes on medium speed (speed 5).","images":[],"step":10},{"title":"Adjust thickness","description":"Use water as needed to loosen frosting to a soft, spreadable consistency (like human buttercream frosting). Use while warm – it \"sets\" and gets harder when it cools, Note 4.","images":[],"step":11},{"title":"White and blue frosting","description":"Use uncoloured frosting to frost between cake layers and sandwich them. Keep remaining frosting to be coloured and used to frost the surface.","images":[],"step":12},{"description":"White Drip Frosting:","images":[],"step":13},{"description":"Mix ingredients in a small bowl, starting with 1 tablespoon milk. The frosting should be thin enough so it will spread quite smoothly on the top of the cake, but thick enough so the drips you make down the side will hold their form. (Do a test on a straight-walled glass). Adjust thickness with more cornflour / cornstarch (for thicker) or more milk (for thinner).","images":[],"step":14},{"title":"Sandwich layers","description":"Place one cake layer on a turntable or serving platter. Spread with 3/4 cup white frosting. Top with another layer of cake, spread with 3/4 cup frosting, then repeat once more and top with the 4th cake layer.","images":[],"step":15},{"title":"Colouring frosting","description":"Colour the remaining frosting blue using blue gel. To achieve the colour pictured, dip a toothpick into gel container and smear colouring on the surface of the potato. Dip a clean toothpick again into the gel and repeat (you need two dips to get enough colour into frosting). Mix frosting until colour is uniform.","images":[],"step":16},{"title":"Frosting surface with blue","description":"Frost the top and sides of the cake with the blue frosting, spreading it as smoothly as you can.","images":[],"step":17},{"title":"Drip Frosting: Spoon 2","description":"3 tablespoons of Drip Frosting on the top of the cake and spread carefully to the edge, ensuring you don''t coax it over the edge. Now scoop up a teaspoon of the Drip Frosting and \"drip\" it down the side of the cake from the top edge. Repeat all around, making drips of different lengths.","images":[],"step":18},{"title":"Decorate","description":"Decorate cake as desired with decorations that you want to stick to the frosting. I used silver, blue and white balls.","images":[],"step":19},{"title":"Set frosting","description":"Immediately refrigerate for at least 3 hours to make the Drip Frosting set. (Also, the silver balls will sweat on the Drip Frosting unless it sets quickly). Keep refrigerated until ready to serve.","images":[],"step":20},{"description":"Happy birthday to your pooch!!!","images":[],"step":21}]', '["egg","gluten","milk","peanuts"]', '["low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Dog Food"],"categories":["dog-treat-recipes","dozer"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7e27a10fb6e6', 'en', 'US', 'Pupcakes! (dog cupcakes with "frosting")', 'Recipe video above - don''t miss Dozer "helping" me make these cupcakes! Made with banana and peanut butter which dogs go mad over, the crumb is moist and tender, stays fresh for a week. Frosted generously with doggie friendly icing made with potato - much better for dogs than using loads of cream cheese, peanut butter or other typical frosting options. For METRIC - toggle under ingredients.', 'https://www.recipetineats.com/tachyon/2020/04/Pupcakes-dog-cupcakes_8-1.jpg', 15, 25, 40, 12, '[{"id": "ing_bananas", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.2, "unit": "jar of 375g"}}, {"id": "ing_honey", "quantity": {"value": 0.167, "unit": "jar of 500g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_flour", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.083, "unit": "tub of 150g"}}, {"id": "ing_oil", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_potato", "quantity": {"value": 500.0, "unit": "bag of 2kg"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.3, "unit": "tub of 250g"}}, {"id": "ing_dog_bone_biscuits", "quantity": {"value": 12.0, "unit": "pack"}}]', '[{"ingredients":["2 ripe bananas (150g/5oz after peeling, ~2/3 cup mashed)","1/2 cup peanut butter (, smooth or creamy (Note 1))","1/3 cup honey","2 eggs","1 1/2 cups flour (, all purpose/plain OR wholewheat/wholemeal (Note 2))","2 1/2 tsp baking powder","1/4 cup oil (, vegetable, canola, peanut or olive oil)","3/4 cup water"],"purpose":"Pupcakes:"},{"ingredients":["500g / 1lb potatoes (, peeled and cut into 2 cm/1\" pieces)","2 tbsp honey","1/2 cup yogurt, plain low fat ((any unsweetened type) OR sour cream)","2 - 4 tbsp water","12 small dog bone biscuits (, for decorating (optional))"],"purpose":"Fluffy dog friendly \"frosting\":"}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan). Line a 12 hole muffin tin with cupcake liners.","images":[],"step":1},{"description":"Place bananas in a bowl and mash with a potato masher until smooth as you can get it.","images":[],"step":2},{"description":"Add peanut butter, honey and eggs. Whisk well until smooth.","images":[],"step":3},{"description":"Add flour, baking powder, oil and water. Whisk until smooth.","images":[],"step":4},{"description":"Divide between cupcakes until 3/4 full. Bake 22 minutes until the top is golden, or skewer comes out clean.","images":[],"step":5},{"description":"Transfer to cooling rack and cool for 30 minutes before topping with \"frosting\"","duration":30,"images":[],"step":6},{"description":"Place potato in a large pot of water. Bring to boil, then cook potato for 20 minutes until very, very soft and starting to crumble on the edges.","duration":20,"images":[],"step":7},{"description":"Drain, then return into empty pot. Add yogurt, honey and water (starting with 2 tbsp). Beat with electric beater for 1 minute on speed 3, increasing to speed 5, for 1 minute or until smooth and creamy. Add more water if needed - it should have a soft consistency like frosting.","duration":1,"images":[],"step":8},{"description":"Transfer to piping bag fitted with a 1.5cm / 3/5\" round nozzle (Note 3 for other nozzles). Pipe in swirling motion onto cupcakes, top with dog biscuit.","images":[],"step":9}]', '["egg","gluten","milk","peanuts"]', '["keto_friendly","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["dog-treat-recipes","dozer","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6fbe34ece28e', 'en', 'US', 'Dog cake recipe - with dog friendly fluffy frosting!', 'Recipe video above. A dog cake with "frosting" that looks so impossibly real, it''s been mistakenly eaten by unsuspecting people on many occasions! Made with dog friendly ingredients with an irresistible peanut butter smell. Fine for humans to consume - but it''s a bit odd tasting for our palette!', 'https://www.recipetineats.com/tachyon/2019/04/Dozer-dog-birthday-cake-4a.jpg', 15, 25, 40, 20, '[{"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.2, "unit": "jar of 375g"}}, {"id": "ing_oil", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_milk", "quantity": {"value": 0.167, "unit": "L"}}, {"id": "ing_maple_syrup", "quantity": {"value": 0.333, "unit": "bottle of 250ml"}}, {"id": "ing_carrot", "quantity": {"value": 375.0, "unit": "pack of 1kg"}}, {"id": "ing_flour", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.062, "unit": "tub of 200g"}}, {"id": "ing_potato", "quantity": {"value": 600.0, "unit": "bag of 2kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.75, "unit": "tub of 500g"}}]', '[{"ingredients":["2 eggs","1/2 cup peanut butter (spread or pure)","1/4 cup oil (canola, vegetable)","2/3 cup milk (or water)","1/3 cup honey or maple syrup (or apple sauce or skip it)","2 1/2 cups shredded carrot (2 large)","2 cups whole wheat / wholemeal flour (or white flour)","2 1/2 tsp baking soda"],"purpose":"Dog birthday cake:"},{"ingredients":["600 - 700g / 1.2 - 1.4lb potatoes (, peeled, cut into chunks)","3/4 - 1 cup yogurt (plain unsweetened) or water"],"purpose":"Dog Friendly Fluffy Frosting (Whipped Potato Yogurt):"}]', '[{"description":"Preheat oven to 180C/350F (160C fan).","images":[],"step":1},{"description":"Grease and line the base of 2 x 20cm/8\" cake pans.","images":[],"step":2},{"description":"Whisk together eggs, peanut butter, oil, honey and milk (little peanut butter lumps ok).","images":[],"step":3},{"description":"Stir in carrots. Then add flour and baking soda, stir until just combined (over mixing = hard cake = sad birthday pooch).","images":[],"step":4},{"description":"Divide batter between the cake pans, spread and smooth surface.","images":[],"step":5},{"description":"Bake 25 minutes or until skewer inserted into the centre comes out clean.","images":[],"step":6},{"description":"Cool on racks. Frost per below.","images":[],"step":7},{"description":"Doggie Fluffy Frosting:","images":[],"step":8},{"description":"Boil, steam or microwave potato until very soft.","images":[],"step":9},{"description":"Whip potato and yoghurt with an electric beater until fluffy and smooth as possible (won''t go 100% smooth) - about 1 1/2 minutes on medium speed (speed 5).","images":[],"step":10},{"description":"Use water as needed to loosen frosting to soft spreadable consistency (like human buttercream frosting!). Use while warm (it \"sets\" when it cools).","images":[],"step":11},{"description":"Spread 1/4 frosting on one cake.","images":[],"step":12},{"description":"Top with other cake. Frost tops and sides with remaining frosting, reserving some to pipe decorations if desired (3/4 cup frosting).","images":[],"step":13}]', '["egg","gluten","milk","peanuts"]', '["low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Dog Food"],"categories":["dog-treat-recipes","dozer"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b570a1d6bb5c', 'en', 'US', 'How to cook crispy skin duck breast', 'Recipe video above. The trick to cooking duck breast is to start the skin in a cold pan with no oil, then cook it on low heat to let the fat render (melt) which allows the skin to go crispy. Then finish it off in the oven - best way to ensure the flesh is perfectly cooked from edge to edge, for tender, rich, perfect duck slices!As for doneness inside - treat duck like steak rather than chicken breast: it is more tender and juicy if it is medium rare rather than well done (whereas chicken is chewy if still pink!). Though I personally think duck is still enjoyable if well done (eg Chinese BBQ duck is well done and it''s not dry!).You can use this recipe for as many duck breasts as can fit in a pan without crowding it.', 'https://www.recipetineats.com/tachyon/2025/01/Crispy-skin-duck-breast_4.jpg', 2, 20, 22, 1, '[{"id": "ing_duck_breast", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1 duck breast (, boneless, skin on (Note 1))","1/8 tsp cooking salt / kosher salt","Pinch white pepper (sub finely ground black pepper)"],"purpose":"Crispy skin duck:"}]', '[{"description":"Preheat the oven to 180°C/350°F (160°C fan-forced).","images":[],"step":1},{"title":"Score","description":"Sprinkle half the salt and pepper on the flesh of the duck. Turn. Use a sharp knife to make 5 or 6 diagonal scores on the skin of the breast. Don''t pierce the flesh and don''t cut all the way to the edge of the skin (Note 2). Pat the skin dry with paper towels, sprinkle with remaining salt and pepper.","images":[],"step":2},{"title":"Cold pan, no oil","description":"Don''t turn the stove on yet. Use an oven-proof pan (any type). Place the duck skin side down in the cold pan, no oil required. Place another pan on top to lightly weigh the duck down (keeps skin flat). (Note 3)","images":[],"step":3},{"title":"Cook 10 minutes","description":"Turn the stove onto medium low. Cook for 10 minutes or until the skin is golden and crispy. Fat will melt out of the duck skin and it will cook in its own fat. (Note 4)","duration":10,"images":[],"step":4},{"title":"Oven 8 minutes","description":"Once the skin is crispy, turn and cook the flesh side for 1 minute. Then transfer the pan to the oven for 6 minutes for medium rare (internal temperature 54°C/130°F, restaurant default) or 8 minutes for medium (60°C/140°F, my preferred).","duration":1,"images":[],"step":5},{"title":"Rest","description":"Transfer to a rack or plate and rest for 5 minutes before serving. Serve whole or slice!","duration":5,"images":[],"step":6}]', '[]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["duck"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_68312a6b532d', 'en', 'US', 'Pierogi Ruskies - Polish Dumplings', 'Recipe video above. Pierogi Ruskie''s are Polish dumplings filled with cheesy, creamy mashed potatoes served with an onion butter sauce. They are even more delicious than they sound! Traditionally made with quark which is an European fresh cheese which isn''t easily found in Australia, so I''ve used cheddar because I want this recipe to be as accessible as possible to many people to experience the greatness that is Pieorgis!!! More in Note 2.Excellent weekend project – eat some today and freeze some for later (they cook from frozen). Makes a nice big batch of 30 pierogis. For more dumplings of the world - head here!', 'https://www.recipetineats.com/tachyon/2023/10/Pierogi-ruskies_5.jpg', 45, 40, 115, 30, '[{"id": "ing_flour", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_potato", "quantity": {"value": 500.0, "unit": "bag of 2kg"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["2 cups flour (, plain/all-purpose)","1 tsp cooking/kosher salt","50g / 3 tbsp unsalted butter","1/2 cup water","1 large egg (, whisked (55-60g/2oz))"],"purpose":"Pierogi dough:"},{"ingredients":["500g / 1 lb potatoes (, peeled and sliced 1cm / 1/2\" thick (2 medium, Note 1))","1 tbsp cooking/kosher salt ( - for cooking potatoes)","30g / 2 tbsp unsalted butter","1 cup shredded cheddar cheese (, tightly packed cup (Note 2))","1/4 tsp cooking/kosher salt","1/2 tsp black pepper"],"purpose":"Pierogi filling:"},{"ingredients":["30g/ 2 tbsp unsalted butter","1 onion (, finely diced)","1/2 tsp cooking/kosher salt"],"purpose":"Onion Butter:"},{"ingredients":["1 tbsp cooking/kosher salt (- for boiling water)","25g/ 1 1/2 tbsp unsalted butter (, per 8 - 10 pierogis (Note 3))","Sour cream (, for serving)","Parsley or chives (, finely chopped - just a pinch)"],"purpose":"Cooking and serving:"}]', '[{"title":"Boil potatoes","description":"Put potato and 1 tbsp salt in a large saucepan. Add cold tap water so it''s 3cm/1 inch above potatoes. Bring to a boil on high heat then reduce heat to medium high and simmer for 15 minutes or until potatoes are soft.","duration":15,"images":[],"step":1},{"title":"Mash","description":"Drain, then pass the potatoes through a potato ricer into a bowl (or use potato masher)","images":[],"step":2},{"title":"Cheese it","description":"Immediately add butter, cheese, salt and pepper. Mix with a wooden spoon until fully combined.","images":[],"step":3},{"title":"Cool","description":"Spread out ~1cm / 1/2\" thick on a tray. Cover with cling wrap, pressing so it is fully in contact. Cool on the counter (~30 min) then refrigerate until cold (1 hour+).","images":[],"step":4},{"title":"Melt butter","description":"Heat up the water and butter in a small saucepan over medium heat just until butter is melted, do not boil water. (Or do this in the microwave). Turn off heat.","images":[],"step":5},{"title":"Mix dough","description":"Whisk the flour and salt in a mixing bowl. Make a well in the centre and then add the butter water plus egg. Mix to combine into a shaggy dough.","images":[],"step":6},{"title":"Knead","description":"Scrape out onto a lightly floured work surface. Knead for 5 minutes until the dough becomes smooth (Note 3). You could also use your stand mixer.","duration":5,"images":[],"step":7},{"title":"Rest","description":"Wrap with cling wrap and leave on the counter for 30 minutes.","duration":30,"images":[],"step":8},{"description":"Wrapping pierogis:","images":[],"step":9},{"title":"Roll & cut","description":"On a lightly floured surface, roll out the dough to 3mm / 1/8\" thickness. Cut out rounds using a 7.5 cm / 3\" cutter. Do as many as you can, then gather surplus dough into a ball, wrap with cling wrap and set aside for later.","images":[],"step":10},{"title":"Fill & wrap","description":"Place 1 tablespoon of cheesy potato filling in the middle of a round. Dip finger with water and run along edge of half the circle. Fold dough over to enclose the filling and press to seal, making slight indents (no pleats).","images":[],"step":11},{"title":"Wrap remaining","description":"Place them on a lightly floured tray and continue to wrap remaining Pierogi (including rolling out the remaining dough). You should get ~30 pierogis.","images":[],"step":12},{"description":"Onion butter sauce:","images":[],"step":13},{"description":"In a non stick skillet, melt the butter until foamy over medium heat. Add onion and salt, then cook, stirring regularly, for 10 to 15 minutes until golden on the edges. Scrape out into a bowl, then set aside (OK to cool).","duration":12.5,"images":[],"step":14},{"description":"Cooking & serving pierogis:","images":[],"step":15},{"title":"Batch cooking","description":"Directions below are for cooking and serving 10. Boil pierogis in batches of 10 to 12 max, they need space to bounce around in the water, and you need space to toss them in the butter. (Note 4 for big batch cooking)","images":[],"step":16},{"title":"Boil 5 minutes","description":"Bring ~3 litres/quarts of water to the boil with 1 tbsp salt. Lower 10 piergosi into the water. Cook for 5 minutes - they should be floating on the surface.","duration":5,"images":[],"step":17},{"title":"Reserve water & drain","description":"Dip a jug into the water and scoop out ~1 cup water. Then use a slotted spoon to transfer pierogi into a bowl (or drain, if not cooking more).","images":[],"step":18},{"title":"Butter sauce","description":"Melt butter in a large skillet over medium heat. Add 1/3 of the onion butter plus the cooked pierogis with 2 tablespoons of the reserved cooking water. Toss for 1 minute, still on the stove, until the pierogis are coated in the butter. (Note 4 on scaling up)","duration":1,"images":[],"step":19},{"title":"Serve","description":"Slide onto a serving plate, scraping out every drop of butter. Sprinkle with parsley, add a dollop of sour cream. Eat and be happy!","images":[],"step":20}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["dinner"],"cuisine":["European","polish"],"categories":["dumplings","iconic-dishes","potato-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_878bc7d71be6', 'en', 'US', 'Malfatti (Italian Spinach Ricotta Dumplings in Napoli Sauce)', 'Recipe video above. Malfatti means “badly formed” in Italian. These irregular spinach ricotta gnocchi-like dumplings may look a bit wonky, but they taste incredible!Like gnudi except with the addition of spinach, this traditional Italian dish can be served straight after boiling them. But it''s really worth a quick 15 minute bake to get a light golden crust on the Malfatti as well as caramelisation on the edges of the Napoli sauce. It really takes it in a deliciously different direction!Servings: This will serve 4 very hungry people, or 5 standard servings.', 'https://www.recipetineats.com/tachyon/2021/06/Malfatti-Spinach-Ricotta-Dumplings_8.jpg', 25, 45, 70, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_baby_spinach", "quantity": {"value": 300.0, "unit": "bag of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.5, "unit": "bunch"}}, {"id": "ing_ricotta", "quantity": {"value": 2.0, "unit": "tub of 250g"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_parmesan", "quantity": {"value": 0.5, "unit": "pack of 200g"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}]', '[{"ingredients":["2 tbsp olive oil","2 garlic cloves (, finely minced)","1/2 onion (, very finely diced)","800g / 24 oz crushed tomato (or diced)","1 tbsp tomato paste","1/2 cup water","1 basil stem (leaves kept for the Malfatti)","1/2 tsp white sugar","3/4 tsp salt","1/2 tsp black pepper"],"purpose":"Napoli Sauce:"},{"ingredients":["300g / 10oz baby spinach (~6 tightly packed cups, Note 4)","1/2 tsp salt"],"purpose":"Spinach for Malfatti:"},{"ingredients":["1 tbsp olive oil","2 garlic cloves (, finely minced)","1 eschallot (large), finely chopped (or 1/2 red onion)","500g / 1 lb ricotta (must be dry type, not wet and spreadable, Note 1)","1/4 cup (lightly packed) basil leaves, finely sliced (use stem for sauce)","1 egg (Note 2)","1 egg yolk (Note 2)","1 cup parmesan (, finely grated)","1/2 cup flour (, plain / all-purpose)","1/2 tsp salt","1/2 tsp black pepper"],"purpose":"Malfatti:"},{"ingredients":["1/4 cup parmesan (, finely grated)","Basil leaves (, small (optional))"],"purpose":"Serving:"}]', '[{"title":"Saute garlic and onion","description":"Heat oil in a small pot or large skillet over medium heat. Add garlic and onion and cook for 3 minutes until onion is softened.","duration":3,"images":[],"step":1},{"title":"Simmer sauce","description":"Add remaining ingredients plus the stem of basil. Bring to a simmer, then reduce stove to low and cook, stirring every now and then, for 20 minutes. It should be fairly thick rather than a loose runny sauce.","duration":20,"images":[],"step":2},{"title":"Drain ricotta, if needed","description":"The ricotta should be the dry and fairly crumbly type rather than wet, soft and almost spreadable. If it''s wet, see Note 1 for removing excess water (wet ricotta makes Malfatti hard to shape and cook!)","images":[],"step":3},{"title":"Sweat spinach","description":"Toss spinach with 1/2 tsp salt in large colander. Leave for 20 minutes. Roll up in tea towel and squeeze tightly to remove excess liquid. Roughly chop.","duration":20,"images":[],"step":4},{"title":"Sauté garlic, eschalot and spinach","description":"Heat oil in a skillet over medium high heat. Add garlic and eschalot, cook for 1 minute until translucent. Add spinach and cook until just wilted. Transfer to large bowl, allow to cool.","duration":1,"images":[],"step":5},{"title":"Malfatti mixture","description":"Add ricotta and all remaining Malfatti ingredients into the bowl. Mix well to combine. It should be too wet to roll with hands without sticking, but still firm enough to shape into dumplings.","images":[],"step":6},{"title":"Form dumplings","description":"Using 2 dessert spoons, scoop up about 1 1/2 tablespoons of mixture then shape into a football (quenelle) using the two spoons. Place on a paper-lined tray. You should get about 24-30.","images":[],"step":7},{"title":"Boil dumplings","description":"Bring a large pot of water to the boil, then carefully put 6 dumplings in. Cook for 2 minutes, they should float to the surface. Remove with slotted spoon on to paper towel lined tray. Repeat for remaining Malfatti.","duration":2,"images":[],"step":8},{"description":"Preheat oven to 180°C / 350°F.","images":[],"step":9},{"title":"Assemble","description":"Pour Napoli Sauce into a baking dish, then top with Malfatti. Drizzle with extra virgin olive oil.","images":[],"step":10},{"description":"Bake 15 minutes or until the Malfatti has a faint blush of gold on the surface (Note 3).","images":[],"step":11},{"description":"Serve! Sprinkle baked Malfatti with parmesan and basil leaves (tear large leaves). Spoon into bowls and served as-is. No starchy side is required, think of these as like gnocchi. Just add a leafy green salad with Italian Dressing or Balsamic Dressing!","images":[],"step":12}]', '["egg","gluten","milk"]', '["high_protein","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["dumplings","italian-recipes","pasta-bakes","pasta-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5b79b5f1ce7c', 'en', 'US', 'French Fish Pie', 'Recipe video above. This is a homestyle fish pie I like to make for Easter, one of my mother used to make for us. Chunks of white fish fillets slowly poached in creamy béchamel with fennel, leek and fresh dill then topped with mashed potato and baked until golden. Don''t be surprised that it doesn’t call for a homemade fish stock, you’ll still get plenty of flavour from the fish itself and the fresh herbs.', 'https://www.recipetineats.com/tachyon/2026/03/French-Fish-Pie_3.jpg', 30, 60, 100, 6, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_fennel", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_eek_halved_lengthwise_then_cut_into_2cm_0_8_pieces", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_milk", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_dill", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}]', '[{"ingredients":["1 leek (, (white and pale green parts only), halved lengthwise, then cut into 2cm / 0.8\" pieces)","1/2 tsp cooking salt / kosher salt (half for table salt, +50% for flakes)"]},{"ingredients":["1 tbsp extra virgin olive oil","2 tbsp (30g) unsalted butter","1 brown / yellow onion (, diced 0.6cm / 0.2\")","1/2 fennel (stalks cut off) (, diced 0.6cm / 0.2\" (Note 2))","1 leek (, (white and pale green parts only), halved lengthwise, then cut into 2cm / 0.8\" pieces)","3 garlic cloves (, finely minced)","1/2 cup plain flour / all-purpose flour (, (Note 3))","1/2 cup dry white wine (, any type (Note 4))","1 1/2 cups HOT milk, full fat preferred (, but works with lite milk too)","1 cup HOT thickened cream / heavy cream","1 tbsp fresh dill (, finely chopped (substitute with parsley or 1/2 tbsp tarragon))","3/4 tsp cooking salt / kosher salt (, half for table salt)","1/4 tsp black pepper"],"purpose":"Fish pie sauce"},{"ingredients":["1kg / 2lbs starchy potatoes","2 tbsp (30g) unsalted butter (, cold, cut in small cubes)","1/3 cup hot milk, full fat preferred (, but works with lite milk too)","3/4 tsp cooking salt / kosher salt (, half for table salt)","1/8 tsp ground white pepper (, or black pepper)","olive oil spray (optional)"],"purpose":"Mash potato topping"}]', '[{"description":"Sauté onion, fennel, leek and garlic, add flour, wine, milk, cream, salt and pepper to make the sauce, stir in dill and add fish. Pipe on mashed potato. Spray olive oil. Bake for 35 minutes until golden. Rest 5 minutes, then serve.","duration":35,"images":[],"step":1},{"description":"First place potatoes in a large saucepan, cover with cold water. Bring to a boil, then simmer 25 minutes until very soft. You can start making the sauce while the potatoes are cooking.","images":[],"step":2},{"description":"Preheat oven to 200°C / 390°F (180°C fan). I highly recommend placing a baking tray lined with foil at the bottom of your oven to catch any bubbling filling that may leak during baking. Easier to clean!","images":[],"step":3},{"title":"Season fish","description":"Pat fish pieces dry with paper towels and sprinkle all sides with salt. Set aside.","images":[],"step":4},{"title":"Sauté vegetables","description":"Heat oil and butter in a 26cm / 10\" cast-iron skillet over medium-high heat. Add onion, fennel, leek and garlic. Cook 5 minutes until softened and light golden. Stirring regularly. (Note 5)","images":[],"step":5},{"title":"Make sauce","description":"Add flour, stir for 30 seconds. Pour in white wine. It will simmer rapidly at first, then mix it in, it will look pasty. Slowly pour in the HOT milk and cream while stirring. Add salt and pepper. Bring to a simmer, cook 1 minute until thickened. The sauce should be quite thick, fully coating the back of the spoon then gently run down it. Set aside.","duration":0.5,"images":[],"step":6},{"title":"Finish mashed potato","description":"(see instructions below).","images":[],"step":7},{"title":"Finish filling","description":"Stir in dill. Add the fish pieces to the sauce, gently nestling them in so they’re mostly submerged. Then, using a spatula, carefully stir and move them around just enough to coat them in the sauce. Smooth the surface.","images":[],"step":8},{"title":"Potato topping","description":"Pipe mounds of mashed potato swirls on the surface. My swirls have a 4.5cm base (1.6\"), about 4cm tall (1.4\"), then I fill gaps with small swirls/blobs. Make sure to use all the mash! Spray lightly with olive oil. (Note 6)","images":[],"step":9},{"title":"Bake","description":"Bake 35 minutes, rotating halfway, until golden on top. If it''s not golden enough, place it under the grill for a few minutes.","images":[],"step":10},{"title":"Serve","description":"Rest for 10 minutes before serving to cool slightly and let the sauce thicken a bit more.","duration":10,"images":[],"step":11},{"title":"Finish mash","description":"Drain well. Pass through a potato ricer or return to the pot and mash well with a potato masher. Do not use a stick blender, it will overwork the starch, turning the mash gluey instead of fluffy. Add butter, salt and white pepper, stir until combined then add hot milk. Stir until smooth. It should be creamy but not loose (so it holds its shape when piped).","images":[],"step":12},{"title":"Piping bag","description":"Transfer into a piping bag fitted with a star tip. (Note 7)","images":[],"step":13}]', '["fish","gluten","milk"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["French","Western"],"categories":["easter-mains-fish-seafood","easter-recipes","fish-recipes","jbs-recipes","mains"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c20b75a13838', 'en', 'US', 'Slow-roast Easter stuffed lamb', 'Recipe video above. Make this to impress! Lamb shoulder slow-cooked until fork-tender but still slices like a dream to show off that herby, nutty stuffing, a stunner with the rich lamb meat. You''ll love the impressive stuffing-to-meat ratio, confit-style melting potatoes, and lush gravy. PS. Yes the rolling/tying part can be fiddly if you''re new to it. But don''t be intimidated, watch the video and look at the step photos, it''s infinitely doable even for first timers. And don’t worry if your lamb comes out a little rustic - eg wonky, or filling burstage. Once it’s on the platter, no one will notice, but the flavour will be all there!Recipe credit: Our very own Chef JB!', 'https://www.recipetineats.com/tachyon/2025/04/Easter-stuffed-lamb-shoot-2_2.jpg', 40, 180, 400, 5, '[{"id": "ing_lamb", "quantity": {"value": 1.35, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_eschalots", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_mushroom", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_baby_spinach", "quantity": {"value": 2.0, "unit": "bag of 250g"}}, {"id": "ing_skinless_hazelnuts", "quantity": {"value": 45.0, "unit": "jar"}}, {"id": "ing_pistachios", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_parsley", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_rosemary", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.005, "unit": "bottle of 250ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_rosemary", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_saut_ed_green_beans", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["1.35 - 1.5 kg/ 2.7 - 3 lb deboned lamb shoulder (Note 1)","1 1/2 tsp cooking salt / kosher salt (, divided)","1 tsp black pepper (, divided)","2 tsp extra virgin olive oil"]},{"ingredients":["1 tbsp / 20g unsalted butter","2 eschalots (, finely diced (US: shallots, sub 1 small onion) (Note 2))","3 garlic cloves (, finely minced)","300g/ 10 oz mushrooms (, button/white (Note 3))","2 tightly packed cups baby spinach (, roughly chopped 100g)","3 tbsp skinless hazelnuts (Note 4)","3 tbsp pistachios (, roughly chopped (Note 4))","1 1/2 tbsp parsley (, finely chopped (ok to omit))","1 1/2 tsp rosemary (, fresh, finely chopped (sub fresh thyme, or 1 tsp dried))","1 tbsp lemon zest (divine touch, don''t skip this!)","1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper"],"purpose":"The fabulous herb & nut stuffing:"},{"ingredients":["1 kg/ 2 lb baby potatoes (, cut in half (4 if large) (Note 5))","1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper","1 tbsp extra virgin olive oil"],"purpose":"Melting potatoes:"},{"ingredients":["2 tbsp flour (plain / all-purpose)","1 1/4 cups beef stock/broth (, low sodium)","1/4 tsp dark soy sauce (optional, for deeper colour) (Note 6)","Salt and pepper (, if needed (I don''t add any more))"],"purpose":"Gravy:"},{"ingredients":["1 tbsp pistachios (, roughly chopped (optional garnish))","Rosemary sprigs (, optional garnish)","Sautéed green beans (pictured - vegetable side, splash of colour)"],"purpose":"Serving:"}]', '[{"title":"Roast hazelnuts","description":"Preheat oven to 180°C/350°F (160°C fan-forced). Roast the hazelnuts for 8 minutes. Cool, then roughly chop.","duration":8,"images":[],"step":1},{"description":"Blitz the mushrooms in a food processor, scraping down the sides as needed, until the mushrooms are chopped into little 3mm/0.1\" pieces.","images":[],"step":2},{"title":"Duxelle","description":"Melt the butter in a non-stick pan over high heat. Add eschalots, garlic and mushrooms. Cook, stirring regularly, for 5 minutes or until the liquid that comes out of the mushrooms mostly evaporates. Add spinach and cook until wilted.","duration":5,"images":[],"step":3},{"title":"Cool","description":"Transfer the filling into a bowl. Cool for 20 minutes then stir in remaining ingredients.","duration":20,"images":[],"step":4},{"title":"Stuffing log","description":"Pile the stuffing on a piece of cling wrap. Use your hands to roughly shape it into a 35cm / 13.5\" long log. Tightly roll up with cling wrap. Place in the freezer for 3 hours (up to 3 days) until it is firm. (Note 7)","images":[],"step":5},{"description":"Pound and roll lamb:","images":[],"step":6},{"title":"Pound","description":"Place the lamb shoulder fat-side down. Cover with plastic wrap (I use go between) or baking paper. Then use a rolling pin or meat mallet to pound the meat (hard!) into a 40 x 22cm rectangle (15.5 x 8.5\"). Aim for even thickness ~1.75cm (2/3\"). Trim and patch as needed to make your rectangle - see video, I cut & rearrange 2 large flappy bits that stick out.","images":[],"step":7},{"title":"Roll","description":"Sprinkle the surface of the lamb with half the salt and pepper. Unwrap the frozen stuffing log then roll it up tightly, finishing with the seam side down.","images":[],"step":8},{"title":"Tie","description":"Secure with kitchen twine tied every 2cm / 0.8\". (See video for tips)","images":[],"step":9},{"description":"Preheat oven to 220°C/425°F (200°C fan-forced).","images":[],"step":10},{"title":"Season","description":"Rub the lamb roll all over with the olive oil, then sprinkle with the remaining salt and pepper.","images":[],"step":11},{"title":"Potatoes","description":"Toss the potatoes with the salt, pepper and olive oil in a large roasting pan (not a baking tray). Put the lamb on top of the potato, on the diagonal if needed to fit.","images":[],"step":12},{"title":"Short high temp roast","description":"Roast for 30 minutes (renders some fat and gives the colour a head start).","duration":30,"images":[],"step":13},{"title":"Slow roast","description":"Turn the oven down to 160°C/320°F (140°C fan). Cook for 2 1/2 hours, or until the internal temperature is 98°C/208°F or the meat can be fairly easily teased apart using two fork (check in a discreet spot).","images":[],"step":14},{"title":"Rest","description":"Remove lamb and potato to a tray and loosely cover with foil while you make the gravy.","images":[],"step":15},{"title":"Drippings","description":"The roasting pan will have meat juices and fat. Tilt the pan so you can scoop off and discard all but 3 tablespoons of fat (the clear liquid that rises to the surface). Make sure you keep the dark brown juices in the pan. If you''re short of fat, add butter.","images":[],"step":16},{"title":"Heat fat","description":"Put the pan directly on the stove over medium heat. Once the fat is hot, sprinkle the flour over and stir for 1 minute.","duration":1,"images":[],"step":17},{"title":"Thicken","description":"While stirring, slowly pour in the stock. Add soy sauce, then keep stirring as it bubbles gently until it thickens into a maple syrup consistency.","images":[],"step":18},{"description":"Taste and add more salt and pepper if desired (I don''t need more). Pour into a jug (strain, if needed).","images":[],"step":19},{"description":"Cut the string off the lamb then slice into 2cm / 0.8\" thick slices.","images":[],"step":20},{"description":"Plate on a platter, surround with the potatoes. Serve with gravy, sprinkled with extra chopped pistachios if desired! (Shown in the video with sautéed green beans).","images":[],"step":21}]', '["gluten","milk","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["easter-mains","easter-recipes","easter-sides-warm-hearty","lamb","lamb-recipes","mains","roast-lamb"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_74a959c34823', 'en', 'US', 'Ultimate slow-roasted lamb: 12-hour Lamb Shoulder', 'Recipe video above. A 3-hour lamb shoulder is great. A 12-hour lamb shoulder is better! The meat is even more succulent because a lower cooking temperature means less moisture loss, and better flavour infusion from the rub. The sauce is a Lamb Jus made using the braising juices so it has phenomenal flavour. Don''t be intimidated, it''s simple and no more difficult to make than gravy!This is an excellent make-ahead recipe for gatherings. Why? Because you can make up to 4 shoulders in one standard oven. And the room for error is also almost nil; it''s almost entirely hands-off cooking that magically takes care of itself overnight. Most importantly, the meat is so juicy it reheats 100% perfectly. I cook it overnight and reheat to serve that evening.About scaling up: 2 shoulders can be cooked in one large pan with no change to cook time. 4 shoulders (2 lambs in 2 pans, on 2 shelves) takes about 14 to 15 hours.', 'https://www.recipetineats.com/tachyon/2021/10/12-Hour-Greek-Slow-Roasted-Lamb-Shoulder_4.jpg', 10, 780, 790, 5, '[{"id": "ing_lamb", "quantity": {"value": 1.6, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_rosemary", "quantity": {"value": 0.25, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.013, "unit": "pack of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}]', '[{"ingredients":["1.6 - 2.2kg / 3.2 - 4.4lb lamb shoulder (, bone-in (Note 1))","2 cups water (Note 2)","1 brown onion (unpeeled), cut into 6 wedges (Note 3)"]},{"ingredients":["2 1/2 tsp fresh rosemary (, chopped (finely))","1 tbsp dried oregano","2 garlic cloves (big!) (, finely chopped)","1 tsp salt (, kosher or cooking salt (or 3/4 tsp table salt))","1/2 tsp black pepper","1/4 cup extra virgin olive oil"],"purpose":"Marinade"},{"ingredients":["1 tsp cornflour / cornstarch","1/4 cup water","1/4 tsp salt"],"purpose":"Jus, for serving"}]', '[{"description":"Preheat oven to 230°C / 450°F (210°C fan).","images":[],"step":1},{"title":"Marinade/rub","description":"Mix the Marinade ingredients in a small bowl. Rub all over the lamb surface, getting it right into all the cracks and crevices!","images":[],"step":2},{"title":"Marinate 2","description":"24 hrs: If time permits, marinate for 2 hours on the counter in a roasting pan, or up to 24 hours in the fridge. I skip this step more often than not, however. (Note 4)","images":[],"step":3},{"title":"Prepare roasting pan","description":"Scatter onion in the base of the roasting pan. Place lamb shoulder on top . Pour water into pan.","images":[],"step":4},{"description":"Roast uncovered for 45 minutes.","duration":45,"images":[],"step":5},{"title":"Slow-roast 12 hours","description":"Turn oven down to 100°C/210°F (both fan and standard, Note 5). Cover lamb with baking paper, then a double layer of foil and seal very tightly to avoid water evaporation. Roast for 12 hours (I always do overnight!).","images":[],"step":6},{"title":"Check meat","description":"Test side of lamb with two forks. The meat should be fall-apart tender. If not, cover and return to oven.","images":[],"step":7},{"title":"Remove lamb","description":"There will (should!) be a lot of liquid pooled under the lamb in the roasting pan. Remove lamb to a large dish. Cover loosely with foil to keep warm. It will stay warm for 2 to 3 hours. See Note for reheating / making ahead.","images":[],"step":8},{"title":"Reduce liquid","description":"Strain all the liquid in the roasting pan into a saucepan (Note 2). Bring to a boil then simmer rapidly on medium-high until it reduces down to 1 cup (250ml).","images":[],"step":9},{"title":"Thicken","description":"Mix cornflour with water. Pour into jus in a thin stream while stirring continuously. Continue to cook for a minute or two over medium heat, stirring every now and then, until it thickens to a syrup consistency. Add salt and pepper to taste.","images":[],"step":10},{"description":"Serve:","images":[],"step":11},{"description":"Serve Slow Roasted Lamb with Jus. Use tongs for tearing meat off - no knife for carving needed! Pictured in post with Greek Lemon Roasted Potatoes, a perfect match for this Greek-ish flavoured lamb. Roasted Vegetables would also be ideal.","images":[],"step":12}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Australian","Western"],"categories":["easter-mains","easter-recipes","iconic-dishes","lamb","lamb-recipes","mains","roast-lamb","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_74648aa2183d', 'en', 'US', 'Rack of Lamb with Rosemary Garlic Marinade (Oven Roasted)', 'Recipe video above. Here is a wonderful, classic way to cook a rack of lamb that makes the most of this premium cut of meat! Infused with the flavours of rosemary and garlic from a marinade, then roasted to perfection, it''s served with Salsa Verde for a deliciously fresh accompaniment that plays beautifully against the rich lamb.Allow 3 to 4 cutlets per person.', 'https://www.recipetineats.com/tachyon/2021/03/Lamb-Rack-Main.jpg', 10, 25, 35, 4, '[{"id": "ing_lamb", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_rosemary", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_quantity_salsa_verde", "quantity": {"value": 1.0, "unit": "bottle"}}]', '[{"ingredients":["2 x 800g / 1.3lb racks of lamb (, frenched (Note 1))"]},{"ingredients":["4 garlic cloves (, minced)","1 tbsp fresh rosemary (, finely chopped)","4 tbsp extra virgin olive oil","1/2 tsp salt (, cooking/kosher salt)","1/4 tsp black pepper"],"purpose":"Marinade:"},{"ingredients":["2 tbsp olive oil - for searing (1 tbsp each rack)"],"purpose":"Cooking:"},{"ingredients":["30g / 2 tbsp butter (, cut into 1cm / ½\" cubes)","2 garlic cloves (, smashed (use side of knife))","1 sprig rosemary"],"purpose":"Basting finish:"},{"ingredients":["1 quantity Salsa Verde (see separate recipe)"],"purpose":"Serving:"}]', '[{"title":"Marinate lamb","description":"Mix marinade ingredients in a ziplock bag (Note 2). Place lamb in bag, massage to coat, then seal and marinate for at least 24 hours and up to 48 hours.","images":[],"step":1},{"description":"Remove lamb from fridge 1 hour prior to cooking, to ensure even cooking.","images":[],"step":2},{"title":"Wrap bones in foil (optional)","description":"Wrap each bone with a small piece of foil. This keeps the bones white and looks prettier.","images":[],"step":3},{"title":"Preheat oven","description":"Preheat oven to 200°C/390°F (180°C fan).","images":[],"step":4},{"title":"Sear","description":"Heat 1 tbsp oil in a cast iron skillet (or other oven-proof, heavy-based skillet) over high heat. Sear one lamb rack on all sides until golden brown, including the ends. Remove and repeat with other lamb rack.","images":[],"step":5},{"title":"Roast","description":"Place both racks in the skillet and roast for 15 minutes, or until the internal temperature is 57°C/135°F (for medium-rare). Remove pan from oven.","duration":15,"images":[],"step":6},{"title":"Baste","description":"Add butter, smashed garlic and rosemary to pan. The residual heat of the pan will melt the butter. Spoon the butter over the lamb continuously for 30 seconds.","duration":0.5,"images":[],"step":7},{"title":"Rest","description":"Remove lamb from skillet and place on a rack set over a tray. Pour butter remaining in the skillet over lamb. Cover loosely with foil and rest for 5 minutes.","duration":5,"images":[],"step":8},{"description":"Carve and serve! Cut lamb into individual cutlets or several cutlets per slice. Serve with Salsa Verde!","images":[],"step":9},{"title":"Sides","description":"Pictured in post with a Spring Salad and individual Mini Potato Gratin Stacks.","images":[],"step":10}]', '["milk"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["easter-mains","easter-recipes","easter-sides-warm-hearty","lamb-recipes","roast-lamb","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_498329e6e8d1', 'en', 'US', 'Pork Roast with Crispy Pork Crackling', 'Recipe video above. This is how to make a pork roast with tender juicy flesh, with a crazy-crispy crackling! The crackle is bubbly and puffy from edge to edge as it should be, rather than an impenetratable rock hard flat sheet of skin or worse still, littered with rubbery patches.And the gravy is to die for, thanks to the flavour loaded roasting pan juices!KEY STEPS: Use pork shoulder, dry skin, no need to score (but if it''s already scored, that''s ok), salt the skin evenly, slow roast low uncovered, keep the skin surface level using foil balls, and blast it for crispy skin! Read the post for extra tips, step photos, and why this recipe works!', 'https://www.recipetineats.com/tachyon/2018/04/Pork-Roast-Crispy-Crackling_0.jpg', 15, 200, 215, 10, '[{"id": "ing_pork_shoulder", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.125, "unit": "jar of 50g"}}, {"id": "ing_fennel_seeds", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_cider", "quantity": {"value": 1.515, "unit": "bottle of 330ml"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.125, "unit": "jar of 50g"}}]', '[{"ingredients":["3 kg/ 6 lb boneless skin on pork shoulder, NOT scored (, unrolled / netting removed (Note 1 & 6))","3 tsp cooking / kosher salt (NOT salt flakes or table salt, Note 7)","1 1/4 tsp black pepper","2 tsp fennel seeds (or other herb/spice of choice)","1 tbsp+ 1 tsp olive oil","1 garlic bulb (, halved horizontally)","2 onions (, halved (brown, white, red))","2 cups dry white wine, or alcoholic or non-alcoholic cider (Note 2)"]},{"ingredients":["1/4 cup flour (Note 5)","2 cups chicken broth/stock (, low sodium)","Salt and pepper"],"purpose":"Gravy:"}]', '[{"title":"Dry skin","description":"Pat the skin dry with paper towels. If time permits, leave in the fridge uncovered overnight (even 1 hr helps). If not, pat extra well.","images":[],"step":1},{"description":"Preheat oven to 220°C/430°F (200°C fan).","images":[],"step":2},{"title":"Season flesh","description":"Sprinkle pork flesh with 1 1/2 tsp salt, all the pepper and all fennel seeds and 1 tbsp olive oil. Rub into flesh, right into all the crevices and cracks.","images":[],"step":3},{"title":"Salt skin","description":"Flip pork, drizzle skin with 1 tsp oil, then rub all over with fingers. Sprinkle all over with remaining 1 1/2 tsp salt, taking care to get even coverage. Un-salted patches will not become bubbly crackling, it will be a hard flat sheet.","images":[],"step":4},{"title":"Garlic & onion bed","description":"Place halved garlic bulbs and onion in roasting pan. Place pork skin side up on top of them.","images":[],"step":5},{"title":"Wine","description":"Carefully pour wine into the pan, being sure not to wet the skin. Transfer to oven.","images":[],"step":6},{"title":"Lower oven","description":"Immediately turn oven down to 160°C/320°F (140°C fan).","images":[],"step":7},{"title":"Slow roast","description":"Roast for 2 1/2 hours.","images":[],"step":8},{"title":"Level at 1 1/2 hours","description":"Check pork after 1 1/2 hours to see if the pork is warped and the skin''s overall surface is significantly unlevelled. If so, adjust to make the skin surface as level as possible using balls of foil and moving large dislodged pork pieces to the side (key tip for crispy crackling, Note 3). Then return to oven for the remaining 1 hour.","images":[],"step":9},{"title":"Check pan & salt on skin","description":"If pan is drying out, add some water. If there are bald patches on the skin without salt (eg it fell off), spray lightly with oil spray (or brush lightly with oil) then sprinkle with salt. (Remember, salt = bubbly skin!)","images":[],"step":10},{"title":"Increase heat","description":"Turn oven up to 250°C/485°F (all oven types), or as high as it will go if your oven won''t go this high.","images":[],"step":11},{"title":"Make skin crisp","description":"Return pork to oven for 30 minutes, rotating pan as needed, until skin is crisp and bubbly all over. If needed, use foil patches, secured with water soaked toothpicks, to cover parts that are done and keep crisping up remaining patches.","duration":30,"images":[],"step":12},{"title":"Rest","description":"Transfer pork to serving platter, tent loosely with foil (don''t worry, crackling stays super-crisp) and rest for 20 minutes (stays warm up to 1 hour). Then slice using a serrated knife.","duration":20,"images":[],"step":13},{"title":"Serve with gravy. Don''t pour gravy over crackling","description":"pour it off to the side! See note for reheating.","images":[],"step":14},{"title":"Transfer fat to saucepan","description":"Skim off 3 tablespoons of fat from the roasting pan and put in a saucepan.","images":[],"step":15},{"title":"Strain pan juices","description":"Place strainer over bowl and scrape in all the remaining pan juices (including onion and garlic). Press out juices, then discard onion & garlic. Skim off excess fat from surface and discard - no need to be exact here!","images":[],"step":16},{"title":"Gravy roux","description":"Heat the saucepan with the fat over medium heat. Add flour and cook for 1 minute.","duration":1,"images":[],"step":17},{"title":"Add liquids","description":"Pour stock in while whisking so it''s lump free. Then pour in strained pan juies.","images":[],"step":18},{"title":"Thicken","description":"Simmer until thickened to syrup consistency - about 3 minutes - it will thicken more as it cools a little while serving. (Note 4 for colour tip)","images":[],"step":19},{"title":"Season","description":"Adjust salt and pepper to taste. Pour into serving jug. Serve with pork.","images":[],"step":20}]', '["gluten"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["easter-mains","easter-recipes","iconic-dishes","main-dishes","pork-recipes","roasts","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_49924032080d', 'en', 'US', 'Rosemary Crumbed Rack of Lamb', 'Recipe video above. This is a recipe that really makes the most lamb racks which are a pricey cut of meat! Adding a crunchy rosemary-garlic crumb not only adds extra flavour but is also a great textural contrast to the soft and tender lamb meat. To stop the crumb falling off lamb racks, just add a touch of egg into the mustard spread. Egg is after all the ultimate natural food glue!Serve straight up (lamb cutlets are sooo juicy and tender, most people think no sauce is necessary!), with a Creamy White Wine & Mustard Sauce or else a Pea Puree (great colour and is as good as a sauce).', 'https://www.recipetineats.com/tachyon/2020/12/Crumbed-rack-of-lamb_5.jpg', 20, 45, 65, 3, '[{"id": "ing_lamb", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 1.25, "unit": "carton of 12"}}, {"id": "ing_mustard", "quantity": {"value": 0.225, "unit": "jar of 200g"}}, {"id": "ing_rosemary", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_bread", "quantity": {"value": 0.188, "unit": "loaf"}}, {"id": "ing_parmesan", "quantity": {"value": 0.15, "unit": "pack of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_wine", "quantity": {"value": 0.333, "unit": "bottle of 750ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}]', '[{"ingredients":["1 rack of lamb (6 to 9 bones) (, your choice Frenched or not (Note 1))","1 1/4 tsp salt","3/4 tsp black pepper","2 tbsp olive oil"]},{"ingredients":["3 tsp egg (, lightly whisked (Note 2))","3 tbsp Dijon mustard","1 tbsp fresh rosemary leaves (, finely chopped)","1 small garlic clove (, minced)"],"purpose":"Dijon Mustard “Glue”:"},{"ingredients":["1 cup Panko breadcrumbs (Note 3)","2 tbsp parmesan (, finely grated)","1 garlic clove (, finely minced (knife, not garlic press))","1/4 tsp each salt and pepper","2 tbsp fresh rosemary leaves (, finely chopped)","30g / 2 tbsp butter (, melted)"],"purpose":"Garlic Parmesan Crumb:"},{"ingredients":["1 cup dry white wine (sauvignon blanc, pinto gris, semillon, or any blend)","1 cup chicken stock (, low sodium)","1 cup heavy/thickened cream","1 tbsp dijon mustard","1/8 tsp each salt and pepper"],"purpose":"Creamy White Wine & Mustard Sauce (Optional, Note 5):"}]', '[{"description":"Preheat oven to 200°C/390°F (all oven types). Place shelf in the middle of the oven.","images":[],"step":1},{"title":"Season","description":"Sprinkle lamb rack with salt and pepper.","images":[],"step":2},{"title":"Sear","description":"Heat 1 tbsp oil in a heavy based skillet over high heat. Sear lamb rack all over until nicely browned - including each short end - about 1 1/2 minutes on each side. It will be fully raw inside, but that''s OK. Transfer to plate and let cool for 5 minutes, uncovered.","duration":5,"images":[],"step":3},{"title":"Mustard Spread","description":"Mix dijon, rosemary and garlic in a small bowl. Then add 3 teaspoons of egg, and mix again.","images":[],"step":4},{"title":"Making the crumb","description":"Mix Crumb ingredients EXCEPT butter in a bowl. Then use a fork to stir through butter. Spread on a dinner plate (large enough that fits lamb).","images":[],"step":5},{"title":"Crumbing the lamb","description":"Spread the underside of the rack with mustard mix. Press into breadcrumb mixture, then spread mustard mix over the other side as well as each end. Then press those sides into the breadcrumb mixture.","images":[],"step":6},{"description":"Transfer lamb to rack set on a tray. Surround with parboiled vegetables if using - but don''t crowd the lamb.","images":[],"step":7},{"title":"Roast","description":"Frenched racks for 20 minutes, or untrimmed racks for 30 - 35 minutes, or until internal temperature registers 60°C/140°F (for medium rare).","duration":20,"images":[],"step":8},{"title":"Rest meat","description":"Transfer lamb to a cutting board, loosely cover with foil. (If you roasted veg, leave in tray or pan and keep warm in turned off oven).","images":[],"step":9},{"title":"Carve","description":"Rest 5 minutes then slice carefully using your hands to hold the crumb gently in place where you are cutting using a very sharp knife. If your service allows it, it''s best to cut 2 or 3 bones together (ie. a double/triple cutlet portion), because the crumb stays on better. Slicing single cutlets is super hard (sadly)!","images":[],"step":10},{"description":"Serve as-is (no sauce), with Creamy White Wine & Mustard Sauce, or Pea Puree.","images":[],"step":11},{"description":"Creamy White Wine & Mustard Sauce","images":[],"step":12},{"description":"Boil wine and chicken stock together until reduced by 3/4, then whisk in cream and mustard and simmer for 3 - 5 minutes until thickened. The consistency should be a thin pouring sauce. We don''t want to coat the lamb too thickly as the sauce flavour will be overpowering.","duration":4,"images":[],"step":13}]', '["egg","milk","mustard"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["easter-mains","easter-recipes","lamb-recipes","main-dishes","mains","roast-lamb"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_72ecde8a7363', 'en', 'US', 'Lamb Chops with Rosemary Gravy (Loin chops, forequarter, cutlets)', 'Recipe video above. Rosemary and lamb is a classic combination. So we''re doubling up on rosemary here - marinading with garlic and rosemary first, then smothering in rosemary gravy!', 'https://www.recipetineats.com/tachyon/2020/06/Lamb-Chops-with-Rosemary-Gravy_6-copy.jpg', 10, 15, 25, 4, '[{"id": "ing_lamb", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_rosemary", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_rosemary", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["750g/ 1.5lb lamb chops (loin chops, forequarter, cutlets) (Note 1)"]},{"ingredients":["1/4 cup extra virgin olive oil","3 garlic cloves (, finely minced)","1 tbsp rosemary leaves (, finely chopped (Note 2))","1 tsp each salt and pepper"],"purpose":"Lamb Chop Marinade:"},{"ingredients":["2 cups beef stock (, low sodium)","3 tbsp flour (, plain/all purpose (Note 3 for GF))","1 tbsp rosemary leaves (, finely chopped (Note 2))","2 rosemary sprigs (, optional)"],"purpose":"Gravy:"}]', '[{"title":"Marinade","description":"Mix Marinade ingredients together, then pour over chops. Turn to coat and leave to marinade for at least 1 hour, preferably 3 hours or overnight.","images":[],"step":1},{"description":"Cooking:","images":[],"step":2},{"description":"Take lamb out of fridge 30 minutes prior to cooking (to bring to room temp).","images":[],"step":3},{"description":"Heat a large skillet over high heat (no oil needed).","images":[],"step":4},{"description":"Pick up a chop, scrape off excess bits of garlic (it burns) and let excess oil drip off. Place in skillet. Once all chops are in, turn heat down to medium high.","images":[],"step":5},{"description":"Cook times for medium rare (internal temp 62°C/145°F):","images":[],"step":6},{"title":"Loin chops & forequarter chops","description":"4 minutes each side, or until internal temp is 62°C/145°F for medium rare (Note 4 other doneness)","images":[],"step":7},{"title":"Cutlets & thin leg steaks","description":"3 minutes on the first side then 2 minutes on the second side.","images":[],"step":8},{"title":"Rest","description":"Remove lamb from skillet and place on a plater. Loosely cover with foil and rest for 3 minutes while you make the gravy.","duration":3,"images":[],"step":9},{"description":"Pour off all but about 3 tbsp oil (if you''re short, add butter), return skillet to medium heat.","images":[],"step":10},{"description":"Add flour and stir for 30 seconds.","duration":0.5,"images":[],"step":11},{"description":"Pour in beef stock while stirring constantly to dissolve flour mixture in. If you have lumps, use a whisk.","images":[],"step":12},{"description":"Add chopped rosemary and sprig.","images":[],"step":13},{"title":"Simmer, stirring regularly, for 2","description":"3 minutes until it thickens in a gravy consistency.","duration":2.5,"images":[],"step":14},{"description":"Serve lamb chops with gravy over creamy mashed potato and a side of peas!","images":[],"step":15}]', '["gluten"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Australian","Western"],"categories":["easter-mains","easter-recipes","lamb","lamb-recipes","main-dishes","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_36ce5ccbbdee', 'en', 'US', 'Easy Tiramisu (Chef Recipe)', 'Recipe video above. You will be amazed how silky rich and yet LIGHT this Tiramisu tastes! This is slightly adapted from this recipe by Vanessa Martin, a well regarded Australian-Italian chef. This is a traditional recipe made using raw eggs that are not cooked or tempered, and with only mascarpone - no cream! You just can''t achieve the same mouthfeel if you use normal cream. :) (Read in post or note about raw egg concerns)', 'https://www.recipetineats.com/tachyon/2016/03/Tiramisu_5.jpg', 30, 0, 30, 6, '[{"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.05, "unit": "bottle of 50ml"}}, {"id": "ing_mascarpone", "quantity": {"value": 8.0, "unit": "unit"}}, {"id": "ing_black_coffee", "quantity": {"value": 1.25, "unit": "unit"}}, {"id": "ing_frangelico_or_kahlua", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_lady_fingers_pavesini_or_savoiardi_biscuits", "quantity": {"value": 184.275, "unit": "pack"}}, {"id": "ing_cocoa", "quantity": {"value": 0.003, "unit": "jar"}}]', '[{"ingredients":["3 eggs (, yolks and whites separated)","1/2 cup (110g) caster sugar (superfine sugar)","1/2 tsp vanilla extract","8 oz / 250g mascarpone (, good brand (Important - read Note 1))","1 1/4 cups black coffee (, hot and strong! (Note 2))","2 tbsp (or more!) Frangelico or Kahlua (, or other liquor of choice (skip for alcohol free))","6.5 oz / 200g (24 - 30) lady fingers, pavesini or savoiardi biscuits (Note 3)","Cocoa (, for dusting)"]}]', '[{"description":"Beat yolks and sugar in stand mixer or electric beater on speed 6 to 7 for 10 minutes or until it changes from yellow to pale yellow (almost white), and is thick (see video for consistency).","duration":10,"images":[],"step":1},{"description":"Add vanilla and mascarpone, beat until just combined and smooth. Transfer mixture to a bowl, set aside.","images":[],"step":2},{"description":"Clean bowl and whisk. Add egg whites and beat until it''s stiff (3 minutes on speed 7, should be all white foam, see video!)","images":[],"step":3},{"description":"Add 1/2 the cream mixture into the egg whites. Gently fold through. When most incorporated, add the remaining cream mixture and fold through until just combined - don''t bash out all the air in the egg whites! (Note 4)","images":[],"step":4},{"description":"Mix coffee and liquor together. Quickly dip biscuits in and line the bottom of a 8”/20cm square dish. (See video or step photos above to see how I arrange them).","images":[],"step":5},{"description":"Spread over half the cream, then top with another layer of coffee dipped biscuits.","images":[],"step":6},{"description":"Spread with remaining cream.","images":[],"step":7},{"title":"Cover, refrigerate for at least 4","description":"5 hours, preferably overnight","images":[],"step":8},{"title":"Dust with cocoa powder just before serving","description":"either before you cut or after placing onto serving plates.","images":[],"step":9}]', '["egg","milk"]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Italian"],"categories":["dessert-recipes","easter-recipes","iconic-dishes","italian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_448639a95a82', 'en', 'US', 'Hot Cross Buns recipe', 'Recipe video above. Fluffy, perfectly spiced homemade Hot Cross Buns! Watch video to see the dough before and after kneading, and how I roll the balls to get nice smooth golden tops. Also, see below for the NO KNEAD version!', 'https://www.recipetineats.com/tachyon/2017/03/Hot-Cross-Buns-5.jpg', 25, 20, 165, 12, '[{"id": "ing_yeast", "quantity": {"value": 0.03, "unit": "pack of 5 sachets"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_bread", "quantity": {"value": 5.0, "unit": "loaf"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.025, "unit": "jar of 40g"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.025, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sultanas", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_oranges", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_flour", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.075, "unit": "L"}}, {"id": "ing_jam", "quantity": {"value": 0.037, "unit": "jar of 370g"}}]', '[]', '[{"title":"Mix dry","description":"Place flour, yeast, sugar, all spice, cinnamon, and salt in a large bowl. Briefly mix with stand mixer fitted with a dough hook.","images":[],"step":1},{"title":"Add wet","description":"Add butter, milk, egg, sultanas and zest.","images":[],"step":2},{"title":"Standmixer","description":"Mix for 5 minutes until a smooth elastic dough forms. Start on speed 2 then once the ingredients are combined, increase to speed 4. After 1 minute, add extra flour if required, just enough so dough comes away from side of bowl when mixing and doesn''t stick terribly to your fingers. (Note 5).","duration":5,"images":[],"step":3},{"title":"Hand kneading","description":"Alternatively, dust a work surface with flour and knead by hand for 10 minutes.","duration":10,"images":[],"step":4},{"description":"Dough is kneaded enough when it''s smooth and does not break when stretched - see photos & video for before/after comparison.","images":[],"step":5},{"description":"Leave dough in the bowl, cover with cling wrap and place in a warm, wind free place to rise until doubled in size. This will take anywhere between 30 minutes to 1 1/2 hours depending on how warm it is - see Note 6.","images":[],"step":6},{"description":"Forming Balls (watch video, it''s helpful):","images":[],"step":7},{"description":"Line a 31.5 x 23.5 cm / 9 x 13\" tray with baking paper with overhang.","images":[],"step":8},{"description":"Remove cling wrap and punch dough to deflate.","images":[],"step":9},{"description":"Dust work surface with flour, place dough on work surface, shape into a log - this will deflate the air. Cut into 12 equal pieces.","images":[],"step":10},{"description":"Take one piece and press down with palm, then use your fingers to gather into a ball, then roll the dough briefly to form a ball. This stretches the dough on one side and that''s how I get a nice smooth surface.","images":[],"step":11},{"description":"Place the ball with the smooth side up on the tray. Repeat with remaining dough. Line them up 3 x 4.","images":[],"step":12},{"description":"Spray a piece of cling wrap lightly with oil (any), then loosely place over the tray.","images":[],"step":13},{"title":"Return tray to warm place and leaver 30","description":"45 minutes, until the dough has risen by about 75% (less than double in size).","images":[],"step":14},{"description":"Partway through Rise #2, preheat oven to 180°C/350°F (all oven types).","images":[],"step":15},{"description":"Mix flour and water until a thick runny paste forms - see video for thickness required.","images":[],"step":16},{"description":"Spoon into a round 3 mm piping bag or small ziplock bag then snip corner.","images":[],"step":17},{"description":"Remove the cling wrap and pipe crosses onto the buns. Go slow so it hugs the curves.","images":[],"step":18},{"description":"Bake in preheated oven (180°C/350°F) for 22 minutes, or until the surface is a deep golden brown. The surface colour is the best test for this recipe.","duration":22,"images":[],"step":19},{"description":"Meanwhile, place jam and water in a bowl, microwave for 30 seconds. Mix to combine.","duration":0.5,"images":[],"step":20},{"description":"Remove buns from oven. Use overhang to lift buns onto a cooling rack.","images":[],"step":21},{"description":"Brush with jam mixture while warm. Allow to cool to warm before serving.","images":[],"step":22}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["easter-recipes","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_227f969d5caf', 'en', 'US', 'Fish Chowder Soup', 'Recipe video above. Fish Chowder is such a great easy fish recipe that''s can''t-stop-eating-it good! A thick and hearty creamy white fish soup, I adore this combination of tender potatoes, carrots, sweet corn and peas with big flakes of fish.', 'https://www.recipetineats.com/tachyon/2019/04/White-Fish-Soup_6.jpg', 10, 25, 35, 5, '[{"id": "ing_butter", "quantity": {"value": 40.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 37.5, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_potato", "quantity": {"value": 2.0, "unit": "bag of 2kg"}}, {"id": "ing_corn", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_green_onion", "quantity": {"value": 0.75, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["40g / 3 tbsp butter (, unsalted )","2 garlic cloves (, minced)","1 small onion (, finely chopped)","2 small carrots (, halved, cut into 0.5cm / 1/5\" slices)","1/2 cup (125ml) dry white wine (can skip)","1/4 cup (35g) flour ( (plain / all purpose))","3 cups (750 ml) milk (, any fat %)","2 cups (500 ml) fish stock, clam juice OR chicken stock, preferably low sodium (Note 1)","2 cups potato (, 1.5 cm/ 0.5\" cubes (~1 large potato))","1 cup corn (, frozen or canned (drained))","0.5 tsp salt (, plus more to taste)","Finely ground black pepper","600 g/1.2 lb white fish fillets (, skinless, cut into 2cm / 4/5\" pieces (Note 2))","1 cup peas (, frozen)"]},{"ingredients":["1/4 cup green onions (, halved and finely sliced (garnish))","Crusty bread for dunking"],"purpose":"Garnish/serving (optional):"}]', '[{"description":"Melt butter in a large pot over medium heat.","images":[],"step":1},{"description":"Add garlic and onion, cook for 5 minutes until translucent but not golden.","duration":5,"images":[],"step":2},{"description":"Add carrots and stir through.","images":[],"step":3},{"description":"Turn heat up to high and add wine. Stir then let it simmer rapidly until it''s mostly evaporated.","images":[],"step":4},{"title":"Add flour and stir for 30 seconds","description":"it will become sludgy!","duration":0.5,"images":[],"step":5},{"description":"Slow pour in broth while stirring to dissolve paste, then stir in milk.","images":[],"step":6},{"description":"Add potato, corn, salt and pepper. Bring to simmer then turn heat down so it''s simmering gently.","images":[],"step":7},{"description":"Cook, stirring every now and then, for 8 minutes or until potato is almost cooked.","duration":8,"images":[],"step":8},{"description":"Add fish and peas, simmer for 3 minutes or until fish is just cooked (should flake easily).","duration":3,"images":[],"step":9},{"description":"Adjust salt and pepper to taste. If soup is too thick, add a touch of water or milk.","images":[],"step":10},{"description":"Serve, garnished with green onions and crusty bread on the side for dunking!","images":[],"step":11}]', '["fish","gluten","milk","shellfish"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["easter-mains-fish-seafood","easter-recipes","fish-recipes","soup-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0aa249fafde6', 'en', 'US', 'Brown Sugar Glazed Ham', 'Recipe video above. It''s truly incredible how such a simple Brown Sugar Ham Glaze can transform into the most incredibly sticky, caramelised ham! See Notes for handy make ahead tips.New to glazed ham? Start here -> How to Make Glazed Ham. Want to try my signature clove studded Maple Glazed Ham? Here it is!', 'https://www.recipetineats.com/tachyon/2018/12/Brown-Sugar-Glazed-Ham_0-SQ.jpg', 15, 90, 105, 20, '[{"id": "ing_ham", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_honey", "quantity": {"value": 0.125, "unit": "jar of 500g"}}, {"id": "ing_mustard", "quantity": {"value": 0.188, "unit": "jar of 200g"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.125, "unit": "bottle of 500ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cinnamon", "quantity": {"value": 3.75, "unit": "jar"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.188, "unit": "jar of 200g"}}, {"id": "ing_ribbon", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_rosemary", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["4-6 kg / 8-12 lb bone in ham, rind and fat on (Note 1)","2 cups water (Note 2)"]},{"ingredients":["3/4 cup brown sugar","1/4 cup honey (or maple)","1/4 cup Dijon mustard","1/4 cup apple cider vinegar (Note 3)","1/2 tsp black pepper"],"purpose":"Brown Sugar Ham Glaze:"},{"ingredients":["3/4 tsp cinnamon*","1/2 tsp All Spice*","3/4 tsp mustard powder * (ordinary, not hot)"],"purpose":"Spices (Note 4):"},{"ingredients":["Ribbon","Few sprigs of rosemary (or other herb / leaves)"],"purpose":"Presentation (optional):"}]', '[{"description":"Take ham out of the fridge 1 hour prior.","images":[],"step":1},{"description":"Preheat oven to 160C / 320F (standard) or 140C / 285F (fan). Arrange shelf in lower third so the ham will be sitting in the centre of the oven (not right at the top of the oven, this causes more uneven cooking on surface).","images":[],"step":2},{"description":"Remove rind & scoring:","images":[],"step":3},{"description":"Remove the rind (skin) of the ham, ensuring you leave the fat on (Note 5 for steps, photos in post and video above)","images":[],"step":4},{"title":"Scoring","description":"Cut 2.5cm / 1\" diamonds into the fat (don''t cut into flesh).","images":[],"step":5},{"description":"Brown Sugar Ham Glaze:","images":[],"step":6},{"description":"Place brown sugar, honey, mustard, cider vinegar, pepper and Spices into saucepan over medium high heat. Simmer and stir until sugar is dissolved.","images":[],"step":7},{"description":"Baste & Cook:","images":[],"step":8},{"description":"Place rack in a baking pan and place ham on rack.","images":[],"step":9},{"description":"Baste all over with the glaze (except the handle), including underside and the cut face. Reserve remaining glaze for basting.","images":[],"step":10},{"description":"Bake for 1.5 hours, basting every 20 minutes with reserved glaze (Note 6) and pan juices, until caramelised and the internal temperature is 60C/140F. (Note 7)","images":[],"step":11},{"description":"Stick bits of foil on parts that are browning too quickly, and you can even lower the oven temp. (Note 8)","images":[],"step":12},{"description":"Rest ham for 15 to 30 minutes+, basting generously with the pan drippings - use it like paint to make your ham beautifully bronzed all over with a thick glaze. (Note 9)","duration":22.5,"images":[],"step":13},{"description":"Sauce (Note 10):","images":[],"step":14},{"description":"Whisk water into pan juices until it''s a thick honey-like pouring consistency.","images":[],"step":15},{"description":"Presentation & Serving:","images":[],"step":16},{"description":"Wrap handle with baking paper, secure in place with ribbon. Stick in rosemary sprigs.","images":[],"step":17},{"description":"Place ham on table as centrepiece with Sauce on the side. Lovely served warm or at room temp!","images":[],"step":18},{"description":"Once everyone has oohed and aahed over it, nominate someone to be the Ham Carver! Slice thinly and serve with sauce.","images":[],"step":19},{"title":"Leftovers","description":"See list in post for recipe using leftover ham and ham bone!","images":[],"step":20},{"title":"Storing","description":"Will keep for at least a week in the fridge if properly stored using a water-vinegar soaked ham bag or pillowcase. Otherwise freeze - don''t forget the bone! See How to Store Glazed Ham for directions.","images":[],"step":21}]', '["mustard"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["easter-mains","easter-recipes","iconic-dishes","mains"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_31ccacae3b5c', 'en', 'US', 'Slow Cooker Pork Loin Roast OR Pork Shoulder', 'Recipe video above. Pork loin OR shoulder slow cooked in an incredible Honey Butter sauce! I love the way the pork soaks up the flavour of the sauce - and how it only requires 5 ingredients!', 'https://www.recipetineats.com/tachyon/2018/09/Slow-Cooker-Honey-Garlic-Pork-Roast_9-2.jpg', 10, 600, 610, 8, '[{"id": "ing_pork", "quantity": {"value": 1.75, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_honey", "quantity": {"value": 0.375, "unit": "jar of 500g"}}, {"id": "ing_butter", "quantity": {"value": 125.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_vinegar", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.037, "unit": "pack of 400g"}}]', '[{"ingredients":["1.75 - 2.5 kg / 3.5 - 5lb pork loin OR shoulder/boston butt ( ,or scotch fillet, skinless (Note 1))","1.5 tbsp olive oil (, separated)"]},{"ingredients":["2 tsp EACH paprika, thyme","1 tsp EACH garlic powder, onion powder","1/2 tsp cayenne pepper (, optional)","1/2 tsp pepper","2 tsp salt"],"purpose":"Spice Rub:"},{"ingredients":["3/4 cup honey","125g / 1/2 cup butter (, unsalted)","5 cloves garlic (, minced)","1/4 cup cider vinegar","1/2 tsp salt and pepper (, each)"],"purpose":"Honey Butter Sauce:"},{"ingredients":["3 tsp cornflour/cornstarch mixed with splash of water"],"purpose":"Thickener:"}]', '[{"title":"Spice Rub","description":"Rub pork with about 1 tsp oil. Mix Rub together then sprinkle over pork. Pat to adhere all over.","images":[],"step":1},{"title":"Brown","description":"Heat 1 tbsp oil in a large skillet over medium heat. Add pork and sear all around until deep golden brown (don''t let spices burn). Place pork in slow cooker.","images":[],"step":2},{"title":"Honey Butter Sauce","description":"Wipe pan. Add butter and melt. Add garlic and cook for 1 minute until golden. Add remaining Sauce ingredients, mix, simmer rapidly for 30 seconds.","duration":1,"images":[],"step":3},{"description":"Slow Cook:","images":[],"step":4},{"description":"Pour Sauce over pork. Cover slow cooker.","images":[],"step":5},{"title":"Pork loin","description":"Cook on LOW for 4 to 5 hours (see Note 2 for cook times for different sizes)","images":[],"step":6},{"title":"Pork Shoulder","description":"Cook on LOW for 10 hours (see Note 2 for cook times for different sizes, and Note 4 for oven, InstantPot and pressure cooker methods).","images":[],"step":7},{"description":"Remove pork onto serving platter, cover loosely with foil (10 - 20 minutes rest). (See Note 6 on Doneness)","images":[],"step":8},{"description":"Pour all juices in slow cooker into large saucepan. Add cornflour water mixture, mix.","images":[],"step":9},{"title":"Thicken Sauce","description":"Simmer on medium high for 5 minutes or until it reduces down to a syrupy consistency (Note 3).","duration":5,"images":[],"step":10},{"title":"Slice pork into thick slices (1.5","description":"2 cm / 3/5 - 4/5\" thick). Serve with PLENTY of Honey Butter Sauce!","images":[],"step":11}]', '["fish","milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","easter-mains","easter-recipes","main-dishes","mains","pork","pork-recipes","quick-and-easy","roasts","slow-cooker-recipes","sunday-supper"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3e9f49e09873', 'en', 'US', 'Fish Pie', 'Recipe VIDEO above. A grand Fish Pie, fit for a king yet economical to make! Chunks of fish flakes smothered in a creamy white sauce, topped with mashed potato then baked until golden. Use a combination of both smoked and raw unsmoked fish for optimum flavour and texture. Fresh tarragon is also optional - it gives an extra edge to the flavour that people can''t quite put their finger on!', 'https://www.recipetineats.com/tachyon/2018/03/Fish-Pie_2.jpg', 15, 60, 75, 6, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_uncategorized", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_tarragon", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_potato", "quantity": {"value": 750.0, "unit": "bag of 2kg"}}, {"id": "ing_milk", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_egg", "quantity": {"value": 4.0, "unit": "carton of 12"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}]', '[{"ingredients":["400 g / 14 oz smoked fish of choice (Note 1)","400 g / 14 oz raw unsmoked fish of choice (, I used Perch (Note 2))","3 cups / 750 ml milk (, low fat or full fat)","1 brown onion (, quartered (Note 3))","4 cloves (, optional (Note 4))"],"purpose":"Fish:"},{"ingredients":["50 g / 3 tbsp unsalted butter","2 garlic cloves (, minced)","1/2 small onion (, finely chopped)","1 small carrot (, finely chopped)","1 small celery stick (, finely chopped)","1/3 cup / 50g plain flour (all purpose flour, Note 11 for GF)","1 tbsp fresh tarragon (, finely chopped (optional))","2 tbsp parsley (, finely chopped)","Salt and pepper"],"purpose":"White Sauce:"},{"ingredients":["750 g / 1.5 lb floury potatoes (, peeled and cut into 2.5cm / 1\" pieces (Note 5))","30 g / 2 tbsp+ unsalted butter","1/2 cup / 125 ml milk, any fat %"],"purpose":"Potato Topping:"},{"ingredients":["1 cup frozen peas","4 hard boiled eggs (, quartered (optional) (Note 6))","30 g / 2 tbsp butter (, melted)","1/4 cup / 15g grated parmesan cheese (, optional)","Finely chopped parsley (, for garnish (optional))"],"purpose":"Pie:"}]', '[{"description":"Push a clove into the skin of each onion. Place in a pot or large skillet, add milk, turn stove onto medium high heat.","images":[],"step":1},{"title":"When milk is barely simmering, add fish","description":"don''t worry if it''s not entirely covered, it can be turned / moved around.","images":[],"step":2},{"description":"Poach fish for 7 minutes, then use a slotted spoon to transfer fish straight into a medium baking dish (Note 8).","duration":7,"images":[],"step":3},{"description":"Flake into chunks using forks. Remove bones if you see any.","images":[],"step":4},{"description":"Use slotted spoon to remove onion and cloves from milk, discard. RESERVE milk.","images":[],"step":5},{"description":"Preheat oven to 180C/350F. Boil water for potatoes.","images":[],"step":6},{"description":"Melt butter in a large, deep skillet or pot over medium high heat. Add onion and garlic, cook for 1 minute. Then add celery and carrot, cook for 5 minutes until carrot is soft.","duration":1,"images":[],"step":7},{"title":"Turn heat down to medium low. Add flour, mix in","description":"it will look gluey.","images":[],"step":8},{"description":"Add half the milk and quickly start mixing. Once incorporated, the mixture will thicken quickly. Add remaining milk and stir. (Video helpful here)","images":[],"step":9},{"description":"Turn heat up to medium and keep stirring until the mixture thickens to the consistency of honey - about 3 minutes. (Note 7)","images":[],"step":10},{"description":"Take it off the heat, stir through tarragon and parsley. Adjust salt and pepper to taste.","images":[],"step":11},{"description":"Scatter top of flaked fish with peas, then pour over the Sauce. GENTLY stir through (don''t want fish to turn into mush!).*","images":[],"step":12},{"description":"Smooth top, then nestle egg in all over the pie.","images":[],"step":13},{"description":"Bring a large pot of water to the boil. Add potatoes and cook for 15 minutes or until soft. (Do this while making the Sauce).","duration":15,"images":[],"step":14},{"description":"Drain potato, add butter, milk, salt and pepper. Mash until creamy - add more milk if required.","images":[],"step":15},{"description":"Immediately dollop then spread onto pie (cold mash = hard to spread).","images":[],"step":16},{"description":"Use fork to draw squiggles on surface (rough surface = better golden bits).","images":[],"step":17},{"description":"Drizzle surface with melted butter, sprinkle with parmesan.","images":[],"step":18},{"description":"Bake for 35 minutes or until top is deep golden.","duration":35,"images":[],"step":19},{"description":"Stand for 5 minutes before serving, garnished with parsley if desired. See notes for reheating and make ahead.","duration":5,"images":[],"step":20}]', '["egg","fish","gluten","milk"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["British","Western"],"categories":["easter-mains","easter-mains-fish-seafood","easter-recipes","fish-recipes","seafood-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a078e9455b91', 'en', 'US', 'Slow Cooker Roast Lamb Leg with Gravy', 'Recipe video above. The easiest, most succulent roast lamb you''ll ever have! This is not the carving sort of lamb, you can just tear the meat off using tongs.', 'https://www.recipetineats.com/tachyon/2017/04/Slow-Cooker-Roast-Lamb-7.jpg', 5, 600, 605, 5, '[{"id": "ing_lamb", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 666.667, "unit": "pack of 3 heads"}}, {"id": "ing_rosemary", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_rosemary", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_braising_liquid_from_slow_cooker", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["2.0 kg / 4 lb lamb leg, bone in (Note 1)","1 tsp salt","black pepper","2 large garlic cloves (, minced)","1 1/2 tsp dried thyme OR rosemary (or 2.5 tsp finely chopped fresh)","1 tbsp olive oil","2 cups / 500ml beef stock (or chicken) (Note 2)","1 sprig rosemary (, optional)"]},{"ingredients":["50 g / 3 tbsp butter","3 tbsp / 40 g flour (any white)","2 cups / 500 ml braising liquid from slow cooker (, strained)","Salt and pepper"],"purpose":"Gravy:"}]', '[{"description":"Place lamb in slow cooker or on work surface. Sprinkle with salt, pepper, thyme or rosemary and garlic. Drizzle over oil, then rub on both sides.","images":[],"step":1},{"description":"Pour beef stock into slow cooker, add sprig of rosemary (if using).","images":[],"step":2},{"description":"SLOW COOK on low for 10 hours, or pressure cook on high for 1 hour 40 minutes. (See oven version here)","images":[],"step":3},{"description":"The lamb should be tender enough to pull off with tongs, but still holding together (just!). Carefully remove lamb from slow cooker and transfer to tray.","images":[],"step":4},{"description":"Drizzle lightly with oil (any). Bake at 200C/390F for 20 minutes or until browned. Remove and rest for 10 minutes before serving with gravy.","duration":20,"images":[],"step":5},{"title":"Strain liquid in slow cooker into a bowl","description":"you will have more than the 2 cups of broth you added, I usually have over 3 cups. Measure out 2 cups of liquid, reserve remaining liquid just in case.","images":[],"step":6},{"description":"Melt butter in a saucepan over medium heat. Add flour and cook for 1 minute.","duration":1,"images":[],"step":7},{"description":"Add a bit of liquid, mixing as you go so it dissolves. Then add remaining liquid. Whisk if there are lumps.","images":[],"step":8},{"description":"Increase to medium high heat and cook, stirring regularly, until thickened to your taste. Use remaining liquid to thin if required.","images":[],"step":9}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["easter-mains","easter-recipes","lamb-recipes","main-dishes","quick-and-easy","roast-lamb","roasts","slow-cooked-fall-apart","slow-cooker-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e9f2798e0ade', 'en', 'US', 'Baked Parmesan Crusted Salmon with Lemon Cream Sauce', 'A simple showstopper salmon recipe! Fantastic centrepiece for a special occasion yet easy enough for midweek. Don''t skip the sauce! It makes all the difference to this dish because the salmon is not marinated. Though made with cream, it is not rich, it''s quite tangy - perfect pairing with rich salmon.', 'https://www.recipetineats.com/tachyon/2016/11/Parmesan-Crusted-Salmon-6.jpg', 10, 30, 40, 6, '[{"id": "ing_salmon_fillets", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 3.0, "unit": "jar of 200g"}}, {"id": "ing_bread", "quantity": {"value": 0.188, "unit": "loaf"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_dill", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_wine", "quantity": {"value": 0.417, "unit": "bottle of 750ml"}}, {"id": "ing_cream", "quantity": {"value": 1.5, "unit": "carton of 250ml"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}]', '[{"ingredients":["1 (1 - 1.4 kg / 2 - 2.8 lb) side of salmon ( (Note 1))","3- 4 tbsp Dijon mustard"]},{"ingredients":["1 cup panko breadcrumbs (50g) (Note 2)","Oil spray","50g / 3 tbsp butter (, melted)","1/3 cup grated parmesan (, store bought (1/2 cup fresh grated) (Note 3))","2 tbsp finely chopped fresh parsley","2 tbsp finely chopped fresh dill","Zest of 1 lemon","1/2 tsp salt","Pepper"],"purpose":"Parmesan Crumb"},{"ingredients":["30g / 2tbsp butter","1 eschallot / finely chopped (Note 4)","1 1/4 cups dry white wine (Note 5)","1 1/2 cups heavy cream / thickened cream","1 tbsp Dijon mustard","2 1/2 tbsp lemon juice (plus more to taste)","1/2 tsp sugar","Salt and pepper"],"purpose":"Lemon Cream Sauce"},{"ingredients":["Watercress","Lemon wedges","Fresh dill"],"purpose":"Serving"}]', '[{"description":"Take salmon out of the fridge to bring to room temperature.","images":[],"step":1},{"description":"Preheat oven to 200°C / 390°F (180°C fan).","images":[],"step":2},{"description":"Spread panko on baking tray, spray generously with oil then bake for 3 to 5 minutes until light golden brown. (Note 6) Scrape into bowl immediately.","duration":4,"images":[],"step":3},{"description":"Add butter and stir, then add remaining Parmesan Crumb ingredients.","images":[],"step":4},{"description":"Line same tray with foil. Place salmon on foil.","images":[],"step":5},{"description":"Spread Dijon on salmon using a butter knife. Just a thin coating - like buttering toast.","images":[],"step":6},{"description":"Sprinkle Crumb all over.","images":[],"step":7},{"description":"Bake for 20 minutes for just cooked juicy perfection, or to taste. (Note 7)","duration":20,"images":[],"step":8},{"description":"Remove from oven. Loosen salmon from foil using egg flip or butter knife - skin will hopefully be stuck to foil.","images":[],"step":9},{"description":"Plate watercress on serving platter.","images":[],"step":10},{"description":"Use foil to lift salmon onto watercress on serving plate, then slide out the foil from under it (see video under recipe). Serve with Lemon Cream Sauce and lemon wedges on the side.","images":[],"step":11},{"description":"Lemon Cream Sauce","images":[],"step":12},{"description":"Melt butter in a saucepan over medium high heat. Add eschalots and cook for 2 minutes. Add wine and bring to boil. Leave to boil rapidly for 5 minutes or until reduced by 3/4 or so.","duration":2,"images":[],"step":13},{"description":"Turn heat down to medium. Add cream, sugar, salt and pepper. Stir, then add lemon juice and mustard. Stir again. Simmer for 2 to 3 minutes or until thickened (see video). Adjust salt, pepper and lemon to taste. Be generous with the salt - remember the salmon is not marinated, the only salt is in the topping.","duration":2.5,"images":[],"step":14},{"title":"Optional","description":"strain. I don''t bother.","images":[],"step":15},{"description":"Allow to cool for 10 minutes or so. It will thicken as it cools. It can be served warm or at room temperature.","duration":10,"images":[],"step":16}]', '["fish","milk","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dinner-tonight","easter-mains","easter-mains-fish-seafood","easter-recipes","fish-recipes","iconic-dishes","main-dishes","most-popular","quick-and-easy","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a788c343ff02', 'en', 'US', 'Stovetop Macaroni and Cheese', 'Recipe video above. This classic Macaroni and Cheese just happens to be made in one pot! Though made with the usual ingredients, the sauce is extra silky and glossy, and it clings to the macaroni without having to make make the sauce super thick because the pasta is cooked in the sauce. So there''s no risk of gluggy Mac N Cheese or overcooked pasta.', 'https://www.recipetineats.com/tachyon/2016/11/Mac-and-Cheese-Stovetop_-1.jpg', 3, 15, 18, 5, '[{"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.625, "unit": "L"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.6, "unit": "pack of 125g"}}, {"id": "ing_cheese", "quantity": {"value": 0.75, "unit": "block of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.013, "unit": "jar of 200g"}}]', '[{"ingredients":["50 g / 3 1/2 tbsp butter","3 tbsp flour","2 cups milk (full fat preferred but low fat is ok)","2 1/2 cups water","250 g / 2 1/2 cups elbow macaroni (, uncooked)","3/4 cup mozzarella cheese (, shredded)","1 1/2 cups cheese (Cheddar, Colby, Gruyere) (, shredded (Note 1))","Salt and pepper"]},{"ingredients":["1 tsp garlic powder","1/2 tsp onion powder","1/2 tsp mustard powder"],"purpose":"Seasonings (optional)"}]', '[{"description":"Melt butter in a medium pot or large saucepan over medium heat. Add flour and cook for 1 minute.","duration":1,"images":[],"step":1},{"description":"Add about 3/4 cup of milk and mix into butter mixture - it will become a slurry pretty quickly.","images":[],"step":2},{"description":"Add remaining milk and mix so the slurry mixes in. Then add water and Seasonings.","images":[],"step":3},{"description":"Add macaroni and mix. Stir occasionally as it comes to heat. When you see wisps of steam as you stir, lower the heat down to medium low.","images":[],"step":4},{"title":"Stir regularly as it cooks for 9","description":"10 minutes (it will bubble gently), or until the sauce thickens and the macaroni is just cooked - tender but still firm. It should still be saucey at this stage and thinner than you want.","duration":9.5,"images":[],"step":5},{"description":"Take it off the stove and stir the cheese in quickly. Adjust salt and pepper to taste. <- In this step, the sauce thickens and reduces considerably.","images":[],"step":6},{"description":"Serve immediately!!","images":[],"step":7}]', '["gluten","milk","mustard"]', '["vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","easter-recipes","easter-sides-warm-hearty","main-dishes","most-popular","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy","side-dishes","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bcd42a100e3c', 'en', 'US', 'Smoked Salmon Bites (Appetizer)', 'These Smoked Salmon Appetisers are fantastic to take to gatherings because it is fast to make loads - no fiddly assembly one by one - and it''s served at room temperature. These were a hit with my taste testers! See below the recipe for the cooking video (and Dozer cameo at the end!).', 'https://www.recipetineats.com/tachyon/2016/10/Smoked-Salmon-Bites_2.jpg', 15, 0, 15, 49, '[{"id": "ing_cream_cheese", "quantity": {"value": 250.0, "unit": "block of 250g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.3, "unit": "tub of 250g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_dill", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_tortillas", "quantity": {"value": 3.0, "unit": "pack of 8"}}, {"id": "ing_salmon_fillets", "quantity": {"value": 350.0, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}]', '[{"ingredients":["250g / 8 oz cream cheese, softened","1/2 cup sour cream","1/2 tsp garlic powder","Zest of 1 lemon ((large) - more is better, adjust to taste!)","1/2 tsp salt","1/4 cup dill, chopped"],"purpose":"Spread"},{"ingredients":["3 soft large wraps / tortillas (approx 23 cm / 9\" diameter) (Note 1)","350 - 480 g / 12 - 16 oz smoked salmon slices","Table butter"],"purpose":"Assembly"}]', '[{"description":"Mix Spread ingredients together.","images":[],"step":1},{"description":"Spread half on a flatbread in a square shape.","images":[],"step":2},{"description":"Top with half the smoked salmon.","images":[],"step":3},{"title":"Spread a flatbread with butter","description":"just thinly, like buttering a piece of bread. Place the butter side down onto the salmon (Note 2)","images":[],"step":4},{"description":"Spread remaining Spread on flatbread, again in a square shape. Top with remaining salmon. Butter 3rd wrap and place butter side down onto the salmon.","images":[],"step":5},{"description":"Use a large flat object, like a cutting board, and press down lightly to smooth the surface and compress everything.","images":[],"step":6},{"description":"Cover with cling wrap and refrigerate for 4 hours (up to 48 hours) so the filling sets.","images":[],"step":7},{"description":"Using a serrated knife, trim edges to make a square. Don''t cut down - filling may squirt out, cut back and forth in a sawing motion. Chef privileges: nibble on offcuts.","images":[],"step":8},{"description":"Cut square into 6 or 7 even strips, then each strip into squares. Serve with toothpicks, wedges of lemon and extra dill for garnish.","images":[],"step":9}]', '["fish","milk"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["snack"],"cuisine":[],"categories":["easter-recipes","finger-food","fish-recipes","most-popular","salmon-recipes","seafood-recipes","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8894b7ec5cd0', 'en', 'US', 'Pork Sausage Apple Stuffing in Pancetta Cups (Muffin Tin)', 'Stuffing baked in pancetta cups! The stuffing is slightly adapted from this Pork Sausage Dressing recipe by Hapa Nom Nom. These are fantastic made on the day but even better the day after because the flavours meld together even more. They reheat very well in the oven - both the pancetta and the tops crisp up again in the oven.', 'https://www.recipetineats.com/tachyon/2014/12/Pork-Sausage-Stuffing-Pancetta-Cups.jpg', 20, 20, 40, 16, '[{"id": "ing_of_pancetta", "quantity": {"value": 0.64, "unit": "kg"}}, {"id": "ing_sausages", "quantity": {"value": 0.907, "unit": "pack of 500g"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_apples", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_almonds", "quantity": {"value": 0.2, "unit": "pack of 250g"}}, {"id": "ing_bread", "quantity": {"value": 0.938, "unit": "loaf"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_sage", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}]', '[{"ingredients":["16 slices of pancetta (, around 12cm/5\" in diameter (so it fits the muffin tin nicely))","1 lb / 500g Italian pork sausage (, casings removed (Note 1))","3 tbsp unsalted butter","1 small onion (, finely chopped)","1 celery stalk (, thinly sliced)","1 granny smith apple (, skin on, finely chopped)","1/3 cup almonds (, roughly chopped (note: original recipe called for pecans which I didn''t have))","5 cups slightly stale white bread (, cut into 1/3\" / 1cm cubes (Notes 2 & 3))","1 1/2 cups chicken stock/broth (or turkey)","1/2 cup heavy cream (not whipped)","1 tsp fresh sage (, finely chopped (or 1/2 tsp dried sage))","1 tsp fresh thyme (, finely chopped (or 1/2 tsp dried thyme))","Salt and pepper","1 large egg (, lightly beaten)"]}]', '[{"description":"Preheat oven to 350F/180C with the oven rack in the middle.","images":[],"step":1},{"description":"Get 2 muffin trays and partially stack them so you have 16 muffin holes and the \"joined\" muffin tins will fit on one shelf (Note 4).","images":[],"step":2},{"description":"Line the holes with pancetta.","images":[],"step":3},{"description":"Heat a large fry pan over high heat. Add the pork sausage and cook it, breaking up the meat as you go. Cook until the sausage changes from pink to light brown and some of the bits starts to brown - about 5 minutes.","images":[],"step":4},{"description":"Remove the sausage into a bowl and drain the excess fat.","images":[],"step":5},{"description":"Return the pan to the stove and reduce the heat to medium high. Add the butter, and once melted, add the onion and celery. Sauté for around 3 minutes until the onion is translucent.","images":[],"step":6},{"description":"Add the apple and almonds, and cook, stirring occasionally, for another 3 minutes.","images":[],"step":7},{"description":"Remove the fry pan from the stove. Add the bread and gently stir to combine.","images":[],"step":8},{"description":"Add the chicken stock/broth, cream, sage and thyme and sit to combine. Season with salt and pepper to taste.","images":[],"step":9},{"description":"Add the egg and stir until mixed through.","images":[],"step":10},{"description":"Divide the mixture between the 16 pancetta cups.","images":[],"step":11},{"description":"Bake for 15 to 20 minutes until the top is golden brown.","duration":17.5,"images":[],"step":12},{"description":"Remove from the oven and let them rest for 10 minutes before serving.","duration":10,"images":[],"step":13},{"description":"To make ahead, transfer to a cooling rack. Cover and refrigerate until required. Then reheat in a 180C/350C preheated oven for 5 to 10 minutes until the pancetta and top is crispy.","duration":7.5,"images":[],"step":14}]', '["egg","gluten","milk"]', '["keto_friendly","low_calorie"]', '{"mealType":["main_course"],"cuisine":[],"categories":["easter-recipes","easter-sides-warm-hearty","most-popular","pork-recipes","side-dishes","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3ecbba7ded30', 'en', 'US', 'Chocolate Custard Cake', 'Recipe video above. Whether you consider this a giant chocolate tart or chocolate custard cake, we will agree it''s one of the most delicious desserts you will ever make. A cross between a chocolate mousse cake and a chocolate Flan Patissier (French custard tart), it''s deeply chocolatey, ultra creamy, yet not overly rich, and shockingly straightforward to make. The perfect finale for any occasion!', 'https://www.recipetineats.com/tachyon/2023/01/Chocolate-custard-cake_7-close-up.jpg', 30, 60, 90, 10, '[{"id": "ing_oreo_cookies", "quantity": {"value": 200.0, "unit": "pack"}}, {"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_milk", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_vanilla", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_sugar", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 10.0, "unit": "carton of 12"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.188, "unit": "pack of 400g"}}, {"id": "ing_chocolate", "quantity": {"value": 200.0, "unit": "block of 100g"}}, {"id": "ing_cream", "quantity": {"value": 0.004, "unit": "carton of 250ml"}}, {"id": "ing_strawberries", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.1, "unit": "kg"}}]', '[{"ingredients":["200g/ 7oz Oreo cookies (1.5 standard packs, Note 1)","60g/ 4 tbsp unsalted butter (, melted)"],"purpose":"BASE:"},{"ingredients":["3 cups milk (, full fat)","2 tsp vanilla","2/3 cups caster sugar (superfine sugar, sub regular)","120g/ 4.2 oz egg yolks (~6 - 7 large eggs, Note 2)","5 tbsp (50g) cornflour / cornstarch","200g / 7 oz 70% cocoa chocolate (, finely chopped (I use Lindt, Note 3))"],"purpose":"CUSTARD:"},{"ingredients":["Chantilly cream","Raspberry or strawberries","Icing sugar / powdered sugar (, for dusting)"],"purpose":"FOR SERVING (optional):"}]', '[{"title":"Prepare pan","description":"Flip the base of a 20cm / 8\" springform pan upside down – this makes it easier to remove the finished cake without the lip in the way. Grease pan base with butter, then press on a square sheet of baking paper. Clip the pan sides onto the base, letting the excess paper stick out (ease of removal later).","images":[],"step":1},{"description":"Preheat oven to 180°C / 350°F (160°C fan-forced).","images":[],"step":2},{"description":"Heat the milk, vanilla and about half the sugar in a large saucepan over medium high heat until just before boiling, stirring to dissolve the sugar.","images":[],"step":3},{"title":"Yolk mixture","description":"Place egg yolks and remaining sugar in a large bowl and whisk to combine. Add cornflour and whisk until smooth.","images":[],"step":4},{"title":"Temper eggs","description":"While whisking the eggs, slowly pour in the hot milk in a thin stream while whisking. Whisk until fully combined.","images":[],"step":5},{"title":"Thicken custard","description":"Pour the egg-milk mixture back into the same saucepan. Place over medium low heat, stirring constantly so the base doesn''t catch, until it starts to thicken (you will feel it). It should happen within 3 to 5 minutes. If it gets lumpy, remove off heat, whisk vigorously – will become smooth.","images":[],"step":6},{"title":"Stir 45 sec after bubbles","description":"When the custard is thickened and steamy, and you see the first big lazy bubbles appear on the base (pause whisking to see), whisk constantly on the stove for a further 45 seconds then remove from stove.","images":[],"step":7},{"description":"Add chocolate and stir until fully melted.","images":[],"step":8},{"title":"Cool","description":"Transfer into a bowl, immediately cover with cling wrap touching the surface. (You can strain if you''re concerned about lumps). Set aside while preparing the base.","images":[],"step":9},{"title":"Blitz cookies","description":"Roughly break up Oreos with hands and place in food processor. Blitz until they become fine crumbs. Add melted butter, then blitz again until combined.","images":[],"step":10},{"title":"Press","description":"Transfer crumbs into prepared pan, pressing evenly and firmly on to the base (I use the underside of a straight-sided, flat-bottomed cup measure to do this).","images":[],"step":11},{"title":"Bake 1 hour","description":"Whisk custard until smooth to loosen. Pour onto the base, smooth surface. Bake 60 minutes, rotating the cake pan at the 45 minute mark. It will still be wobbly when you pull it out of the oven.","images":[],"step":12},{"description":"Cool for 3 hours on the counter, in the pan. Refrigerate at least 12 hours to allow the custard to fully set.","images":[],"step":13},{"title":"Serve","description":"Best to cut when fridge cold and serve at room temp (for creamiest custard!). Remove springform sides and paper, then use paper overhang to slide the cake off the base. Cut like cake and serve! Lovely with dollop of Chantilly cream and a raspberry or strawberry. Dust with icing sugar to make it pretty!","images":[],"step":14}]', '["egg","milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["dessert-recipes","easter-baking-desserts","sweet-pies"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_360aae8e408b', 'en', 'US', 'Chocolate Mirror Glaze', 'Recipe video above. Deceptively straight forward, it mainly takes patience! The 3 key things for a flawless, reflective mirror glaze are:1. Smooth frosting and level cake - because bumps and dents show up on shiny glazes. See my tutorial for How to Make Frosting Smooth on Cakes; 2. Ensure the glaze is completely smooth (just follow my recipe); and3. Ensure the glaze is at 30°C/86° so it spreads smoothly for a thin, flawless finish. Proper Mirror Glazes are no thicker than 3mm and are not made with condensed milk, for superior results (read in post for more info).Inactive cooling time includes time to cool Chocolate Ganache though directions to make and spread are in separate recipes (see Ganache recipe and Smooth Frosting post).', 'https://www.recipetineats.com/tachyon/2020/11/Chocolate-Mirror-Glaze-Cake.jpg', 60, 0, 60, 12, '[{"id": "ing_chocolate", "quantity": {"value": 1.0, "unit": "block of 100g"}}, {"id": "ing_chocolate", "quantity": {"value": 1.0, "unit": "block of 100g"}}, {"id": "ing_water", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_gelatine_powder", "quantity": {"value": 20.0, "unit": "jar"}}, {"id": "ing_cream", "quantity": {"value": 0.667, "unit": "carton of 250ml"}}, {"id": "ing_cocoa_powder", "quantity": {"value": 0.6, "unit": "pack of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_gold_dust_and_gold_leaf", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["1 x 20cm / 8\" chocolate cake (2 layers) (Note 1)","2 batches Dark Chocolate Ganache (Note 2)"]},{"ingredients":["2 1/2 tbsp water (just cold tap water)","4 tsp gelatine powder (Note 3)"],"purpose":"Gelatine for glaze:"},{"ingredients":["2/3 cup water","2/3 cup cream (, pure / regular whipping cream, better than thickened/heavy cream (Note 4))","1 cup cocoa powder (, unsweetened, sifted (preferably dutch processed, Note 5))","1 cup + 2 tbsp white sugar (, caster/superfine (Note 6))"],"purpose":"Mirror Glaze:"},{"ingredients":["Gold dust and gold leaf (, optional decorations (Note 7))"],"purpose":"Decorating (optional, as pictured)"}]', '[{"description":"Cake and Ganache Frosting preparation:","images":[],"step":1},{"description":"Refrigerate cake layers for at least 1 hour until well-chilled (for easier handling). Then trim cake to make it level and frost cake with chocolate ganache so it''s smooth and level (follow the tutorial in this post: How to Frost Cakes Smoothly).","images":[],"step":2},{"description":"After the ganache is smooth and level, refrigerate for at least 1 hour before coating with Mirror Glaze.","images":[],"step":3},{"description":"Make Mirror Glaze:","images":[],"step":4},{"title":"Bloom gelatine","description":"Place water in a small bowl. Then sprinkle gelatine across surface, mix just so all the powder is wet. Leave for 5 minutes - it will become like a rubber consistency. (This is called \"blooming gelatine\".)","duration":5,"images":[],"step":5},{"title":"Whisk cocoa and water","description":"Place cocoa and water in a medium saucepan then mix until virtually lump-free. It will be like a paste.","images":[],"step":6},{"title":"Add cream and sugar","description":"Add a splash of cream to cocoa mix and stir. It will loosen up. Add remaining cream and sugar, then GENTLY continue to mix to combine. Do not mix vigorously and do not use a whisk (Note 7).","images":[],"step":7},{"title":"Bring glaze to boil","description":"Turn stove onto medium high heat. As soon as it comes to the boil, remove from the stove.","images":[],"step":8},{"title":"Dissolve gelatine","description":"Add gelatine lump, then GENTLY stir until it dissolves and you have a smooth glossy glaze. (There may be some white foam, that''s ok.)","images":[],"step":9},{"description":"Cool & Strain Mirror Glaze:","images":[],"step":10},{"title":"First straining","description":"Using a shallow bowl and small fine mesh strainer, strain the glaze into a bowl. Pour and position the strainer so the glaze falls the smallest distance possible. If you pour from a height, this creates bubbles = bad!","images":[],"step":11},{"title":"Bubble check","description":"Twist the bowl back and forth between your hands rapidly. This will make any bubbles rise and gather in the centre. If you see bubbles, see \"Note 8: Bubble Troubleshooting\".","images":[],"step":12},{"title":"Cool glaze","description":"Cover with cling wrap, pressing the cling wrap onto the surface of the glaze to prevent a skin from forming. Cool on the counter for 2 hours until it reaches 30°C/86°F. See Note 9 for overnight refrigeration.","images":[],"step":13},{"title":"Second straining","description":"Just before pouring over the cake, strain the glaze into a jug. As before, tilt the jug and strainer as you pour the glaze in to minimise the distance the glaze falls.","images":[],"step":14},{"title":"Transfer cake to rack","description":"Remove cake from fridge, transfer onto a rack. (See Note 9 for how I do it.) Place rack on a tray to catch excess glaze.","images":[],"step":15},{"title":"Pour over mirror glaze","description":"Starting at the centre of the cake, pour the glaze on, moving in an expanding spiral motion gradually towards the outer edge of the cake, to make the glaze spread across the surface and drape like curtain down the sides. For the most perfect surface, try to do it in one motion without breaking the pour. Pour with confidence in a thick stream rather than a thin drizzle (which might set too quick and leave drips).","images":[],"step":16},{"title":"Ensure all sides are fully coated","description":"if not, quickly do a little pour down the sides to coat the naked patches.","images":[],"step":17},{"title":"Transfer cake to platter","description":"Before the mirror glaze sets (takes ~10 minutes), move the cake to a cake platter (Note 9 again for my cake-shifting method).","images":[],"step":18},{"title":"Fix blemishes","description":"Use excess glaze on the tray and in the jug to fill gaps and tears. Then smooth over with a warmed palette knife (either lightly warm with a blow torch or dip into warm water and wipe). See video for demo.","images":[],"step":19},{"description":"How to Slice Cake Cleanly with Neat Layers:","images":[],"step":20},{"description":"Fill a tall jug with warm tap water. Dip a knife in, then wipe dry. Make one slice into the cake.","images":[],"step":21},{"description":"Clean knife, dip in warm water and dry again. Make your second cut to get your wedge. Pull wedge out and marvel at the perfect layers before continuing to cut more slices! See notes for storage.","images":[],"step":22}]', '["milk"]', '["gluten_free","keto_friendly","vegetarian"]', '{"mealType":["dessert"],"cuisine":["French","Western"],"categories":["dessert-recipes","easter-baking-desserts","frosting-and-icing"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_83ed0b7b235f', 'en', 'US', 'Chocolate Cake', 'Recipe VIDEO above. This is the everyday Chocolate Cake I make over and over again. The crumb is tender and moist, it truly tastes of chocolate (rarer than you might think!) and you only need one bowl and a whisk. It''s the famous Hershey''s "Perfectly Chocolate" Cake , one of the few recipes I''ve used from another source with no changes to the ingredients at all (yes it''s Perfect!)', 'https://www.recipetineats.com/tachyon/2018/03/Chocolate-Cake_2.jpg', 10, 35, 45, 8, '[{"id": "ing_flour", "quantity": {"value": 0.263, "unit": "kg"}}, {"id": "ing_cocoa_powder", "quantity": {"value": 0.45, "unit": "pack of 250g"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.05, "unit": "tub of 150g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.037, "unit": "tub of 200g"}}, {"id": "ing_sugar", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.2, "unit": "bottle of 50ml"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_chocolate", "quantity": {"value": 1.5, "unit": "block of 100g"}}]', '[{"ingredients":["1 3/4 cups plain / all purpose flour","3/4 cup cocoa powder (, unsweetened (Note 2))","1 1/2 tsp baking powder","1 1/2 tsp baking soda (bi-carb soda)","2 cups white sugar (Note 1)","1 tsp salt","2 eggs (~55-65g / 2 oz each)","1 cup milk (low or full fat)","1/2 cup vegetable oil (or canola)","2 tsp vanilla extract","1 cup boiling water"]},{"ingredients":["1 1/2 batches Chocolate Buttercream Frosting (slide scaler on recipe)"],"purpose":"Chocolate Buttercream Frosting"}]', '[{"description":"Preheat oven to 180C°/350°F (160°C fan). Read Note 4 regarding shelf positions.","images":[],"step":1},{"description":"Grease 2 x 22cm/9\" cake pans with butter, then line the base. (Note 3 re: springform pans and other pan sizes).","images":[],"step":2},{"description":"Sift flour, cocoa, baking powder and baking soda into a large bowl. Add Sugar and salt. Whisk briefly to combine.","images":[],"step":3},{"description":"Add eggs, milk, oil and vanilla. Whisk well to combine until lump free - about 30 seconds.","images":[],"step":4},{"description":"Add boiling water and whisk to incorporate. The batter is VERY thin (see video).","images":[],"step":5},{"description":"Pour batter into cake pans.","images":[],"step":6},{"description":"Bake for 35 minutes or until a wooden skewer inserted into the centre comes out clean. See Note 4 regarding cook time if pans are on different shelves.","duration":35,"images":[],"step":7},{"description":"Cool for 10 minutes, then turn out onto wire racks upside down (Note 5).","duration":10,"images":[],"step":8},{"description":"Cool completely before frosting. I frosted the cake with my Chocolate Buttercream Frosting (scale recipe up by 50%).","images":[],"step":9}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["easter-baking-desserts"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_96589e38feda', 'en', 'US', 'JB''s Cheese Soufflé - Soufflé au Fromage', 'Recipe video above. Cheese Soufflé is a traditional French dish that combines simple pantry staples into something truly special. It rises beautifully in the oven, with a golden top and soft, airy centre. Don’t be intimidated by the name, it’s easier than you think to make it at home. I promise! I still remember my restaurant days, total chaos every time a soufflé came out of the oven. Someone would shout “Soufflé!!” and hope the wait staff appeared instantly, because one thing’s for sure: Soufflé doesn’t wait.', 'https://www.recipetineats.com/tachyon/2025/10/Cheese-souffle_6.jpg', 15, 30, 45, 4, '[{"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 75.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 2.0, "unit": "jar of 50g"}}, {"id": "ing_cheese", "quantity": {"value": 150.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_cream", "quantity": {"value": 0.01, "unit": "carton of 250ml"}}]', '[{"ingredients":["2 cups full fat milk (, but works with lite milk too)","75 g (5 tbsp) unsalted butter","1/2 cup plain flour (all-purpose)","1/2 tsp cooking salt / kosher salt (halve for table salt, + 50% for flakes)","2 pinches ground white pepper (substitute black pepper)","150 g (1 1/2 cups) Gruyère cheese (, shredded using a standard box grater (tightly packed if using cups) (Note 2 for other cheeses))","3 egg yolks (from large eggs (55g/2oz each in shell), at room temperature (Note 1))","4 egg whites (from large eggs, at room temperature (total egg whites ~ 120g/4.2oz, Note1))","1/2 tsp cream of tartar (, sifted if lumpy (Note 3))","15 g (1 tbsp) unsalted butter (, melted (to grease the ramekins))"]}]', '[{"description":"Melt butter, cook flour 2 minutes, whisk in warm milk in 3 batches. Add salt and pepper, turn off heat, whisk in yolks one at a time, then melt through gruyere over low heat. Beat egg whites and cream of tartar to firm peaks, starting on medium for 2 minutes, then increasing to high. Whisk 1/4 of the whites into Mornay Sauce, then fold through remainder in 3 batches. Fill butter brushed ramekins to 1cm/0.4” from rim, clean inside of rim. Bake at 200°C/400°F (180°C fan) for 20 minutes. No peeking! Serve immediately.","duration":2,"images":[],"step":1},{"description":"Preheat oven to 200°C / 400°F (180°C fan-forced). A properly hot oven is crucial, it''s what gives the soufflé its famous lift. A cold oven = a sad soufflé.","images":[],"step":2},{"title":"Prepare the ramekins (Note 4)","description":"Brush the insides of 4 (325ml / 1 1/3 cups) ramekins generously with melted butter (use all the butter). No need to brush upwards (see post for why). Set on a baking tray.","images":[],"step":3},{"description":"Make Mornay sauce (cheese sauce)","images":[],"step":4},{"title":"Heat the milk","description":"Place the milk in a small saucepan over medium heat. Warm it until it’s steaming but not boiling. Set aside.","images":[],"step":5},{"title":"Make the roux","description":"While the milk is heating, let’s start our roux. In a large saucepan, melt the butter over medium heat. Once melted, add the flour. Whisk it gently, it will be thick and pasty at first like a wet sand. Cook, whisking constantly, for about 2 minutes. It will thin up and become smooth and glossy. Make sure to use the whisk to get into the corners of the pot and don’t let it brown. Reduce heat if you think it’s too high.","images":[],"step":6},{"title":"Make Béchamel","description":"Add a third of the hot milk to the roux while whisking vigorously, it will thicken very quickly. Add half of the leftover milk, whisk until smooth and then pour the rest of it along with the salt and pepper. Keep whisking for 30 seconds to a minute until thickened and smooth, lumps will go away. It will be thick enough so you can draw a path with a spatula in the middle, it should hold its shape for a moment before slowly sinking back.","duration":0.5,"images":[],"step":7},{"title":"Turn it into a Mornay sauce","description":"Turn off the heat and whisk in the egg yolks, one at a time, until fully combined (don''t worry the egg yolks won''t cook). Then, turn the heat back on to medium and whisk in the grated Gruyère until melted through. Scrape down the sides and cover with a lid. Set aside.","images":[],"step":8},{"description":"Folding in the Egg Whites and Baking","images":[],"step":9},{"title":"Beat the egg whites, gently at first","description":"Add egg whites and the cream of tartar in a large bowl. Using a hand mixer or a stand mixer fitted with a whisk attachment, beat the egg whites on medium speed for 2 minutes then high speed for 30 seconds until you get firm peaks. Starting slowly helps the protein structure to develop properly. Rush it and you risk unstable, foamy whites that collapse when folded in.","duration":2,"images":[],"step":10},{"title":"Fold gently","description":"Give the Mornay a quick whisk to make it smooth again then add in a quarter of the egg whites and whisk it in to loosen it. Then gently fold a third of the remaining egg whites in using a rubber spatula until mostly incorporated. Use slow, sweeping motions from the bottom of the pot, you want to keep as much air in as possible. (See video at 2.15 minutes) Rough folding = flat soufflé. Few lumps are ok. Repeat twice more with the rest of the egg whites.","images":[],"step":11},{"title":"Fill the ramekins","description":"Pour the mixture evenly into the ramekins using a ladle or a large serving spoon, filling to about 1cm / 0.4\" below the rim. Smooth the tops with the back of a teaspoon dipped in water, no need to be 100% meticulous here, just get rid of big bumps. Run your thumb around the inside rim of each ramekin to clean it, this gives the soufflé a clean edge to rise against.","images":[],"step":12},{"title":"Bake","description":"Place the ramekins on a baking tray and bake for 20 minutes until tall and golden. Do not open the oven door while it''s baking, the sudden drop in heat will make them sink. When it''s cooked, the soufflés should jiggle a bit when you shake the ramekin.","duration":20,"images":[],"step":13},{"title":"Serve immediately","description":"As soon as they’re out, serve straight away. Soufflés don''t wait. So make sure all your family/guest are seated so they can enjoy the show!","images":[],"step":14}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["dinner","lunch","snack"],"cuisine":["French"],"categories":["easter-brunch-recipes","egg-recipes","iconic-dishes","jbs-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_882560a6a52e', 'en', 'US', 'Pearl Couscous Salad', 'Recipe video above. I adore the bright Mediterranean flavours in this salad! Great one to take to gatherings for something a little different that everyone always loves. Serve as a side (6 to 8) or a meal in itself (serves 4).Also known as Israeli and gourmet Couscous, pearl couscous is the big brother version of the more common small couscous. Texture and taste like pasta – soft but a bit chewy, but has a pearly, slippery surface (hence the name).', 'https://www.recipetineats.com/tachyon/2017/07/Israeli-Couscous-Salad-3.jpg', 15, 15, 30, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_pears", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_baby_spinach", "quantity": {"value": 3.0, "unit": "bag of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_dill", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["2 tsp olive oil","1 garlic clove (, minced)","½ small onion (, finely chopped)","1 1/2 cups (250g/ 8oz) pearl couscous (aka gourmet or Israeli couscous, Note 1)","1 1/2 cups vegetable or chicken broth (, low sodium)","1 cup water"],"purpose":"Couscous:"},{"ingredients":["2 cucumbers (, diced (about 2 cups))","250g / 8 oz cherry tomatoes (, halved (about 2 cups))","3 cups baby spinach (, finely sliced (Note 2))","¼ cup coriander / cilantro (, finely chopped (or sub with parsley))","¼ cup dill (, finely chopped)"],"purpose":"Salad:"},{"ingredients":["2 tsp lemon zest","2 tbsp lemon juice","1/4 cup extra virgin olive oil","1 tsp Dijon mustard","1 garlic clove (, minced)","1 tsp sugar (, optional)","3/4 tsp cooking / kosher salt","1/2 tsp black pepper"],"purpose":"Lemon Dressing (Note 3):"}]', '[{"title":"Sauté onion & garlic","description":"Heat oil in a large saucepan or small pot over medium high heat. Add garlic and onion, saute until the onion is translucent and starting to brown.","images":[],"step":1},{"title":"Couscous & broth","description":"Add couscous and stir, cooking for 1 minute. Add broth and water, bring to a simmer. Then place the lid on and turn the heat down to medium low so it is simmering gently.","duration":1,"images":[],"step":2},{"description":"Cook for 10 minutes until the liquid is absorbed and the couscous is cooked through but still firm. Use a fork to separate the couscous, then transfer into a large bowl to cool. (It will form a sticky block but don''t worry, it will separate when tossed with Dressing).","duration":10,"images":[],"step":3},{"title":"Dressing","description":"Place Dressing ingredients in a jar and shake well.","images":[],"step":4},{"description":"Toss! Add Salad ingredients into the bowl, pour over Dressing and toss. Serve at room temperature.","images":[],"step":5}]', '["gluten","mustard"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["easter-brunch-recipes","easter-sides-fresh-light","mediterranean-recipes","pasta-recipes","pasta-salads-and-rice-salads","quick-and-easy","salad-recipes-main-course","side-salads","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bf834f6f91bd', 'en', 'US', 'Greek Lemon Orzo Salad (Risoni)', 'A fabulous side, great for taking to gatherings, and substantial enough to have as a meal, this Lemon Orzo Salad tastes like a Greek Salad with a bright zesty lemon dressing! As vegetable sizes can differ, adjust the quantities to your taste.', 'https://www.recipetineats.com/tachyon/2017/01/Greek-Lemon-Orzo-Salad-3.jpg', 10, 0, 10, 6, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.3, "unit": "pack of 500g"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.4, "unit": "punnet of 250g"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_feta_cheese", "quantity": {"value": 150.0, "unit": "block of 200g"}}, {"id": "ing_onion", "quantity": {"value": 0.25, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_whole_black_olives", "quantity": {"value": 150.0, "unit": "bottle"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.075, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1 cup / 200 g risoni / orzo pasta","350 g / 12 oz cherry tomatoes (, halved (or 2 large tomatoes))","2 Lebanese / Persian cucumbers (, diced)","150 g / 5 oz firm feta (, cut into 1/2cm/ 1/2\" cubes)","1/4 - 1/2 red onion (, cut into wedges and sliced thinly)","1 green capsicum/bell pepper (, cut into 3 cm / 2.25\" strips (Note 1))","150 g / 5 oz whole black olives (, seed in (adjust qty to taste))","1 1/2 tsp dried oregano"]},{"ingredients":["2 tsp lemon zest","3 tbsp lemon juice","5 tbsp olive oil","1 tsp Dijon mustard (or other mild mustard)","1 garlic clove (, minced)","1 tsp sugar","1/2 tsp salt","Black pepper"],"purpose":"Dressing"}]', '[{"description":"Place Dressing ingredients in a jar and shake well. Set aside for 10+ minutes.","images":[],"step":1},{"description":"Cook orzo / risoni per packet directions. Drain and rinse under cold water to stop them cooking further. Drain well.","images":[],"step":2},{"description":"Place orzo and remaining Salad ingredients in a bowl. Drizzle with dressing and toss gently to coat. Serve!","images":[],"step":3}]', '["gluten","mustard"]', '["low_calorie","vegan","vegetarian"]', '{"mealType":["lunch"],"cuisine":[],"categories":["easter-brunch-recipes","easter-sides-fresh-light","greek-recipes","mediterranean-recipes","pasta-recipes","pasta-salads-and-rice-salads","quick-and-easy","salad-recipes-main-course","side-salads","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c6fa390416b4', 'en', 'US', 'Christmas Baked Salmon', 'Recipe video above. Have you ever seen a Baked Salmon that looks so festive? What''s more, it''s DEAD EASY! Featuring a honey butter-glazed side of salmon baked in foil, slathered with creamy dill sauce and finally topped with a glittering Holiday "Tapenade", this Salmon Tarator inspired dish pays extremely high dividends for very little work.See notes for alternatives for many of the ingredients - even the salmon!', 'https://www.recipetineats.com/tachyon/2020/12/Christmas-Baked-Salmon_5.jpg', 20, 30, 50, 12, '[{"id": "ing_salmon_fillets", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.011, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 150.0, "unit": "block of 250g"}}, {"id": "ing_honey", "quantity": {"value": 0.25, "unit": "jar of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.9, "unit": "tub of 250g"}}, {"id": "ing_dill", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.5, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 4.0, "unit": "net of 500g"}}, {"id": "ing_cranberries", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_oranges", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_almonds", "quantity": {"value": 0.6, "unit": "pack of 250g"}}, {"id": "ing_parsley", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_pomegranate", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 4.0, "unit": "net of 500g"}}, {"id": "ing_emons", "quantity": {"value": 2.0, "unit": "unit"}}]', '[{"ingredients":["1.2 - 1.5 kg / 2.4 - 3lb salmon side (skin on, bones removed, Note 1)","2 1/4 tsp salt (, cooking/kosher (Note 2))","1 tsp black pepper"],"purpose":"Salmon:"},{"ingredients":["150g / 5oz butter (, unsalted)","1/2 cup honey","3 garlic cloves (, finely minced (garlic press or knife))"],"purpose":"Honey Butter Glaze:"},{"ingredients":["1 1/2 cups sour cream (, full fat (low fat is too watery))","1/2 cup fresh dill (, finely chopped (lightly packed cup))","1/2 eschallot (French onion) (, finely grated)","1 1/2 tbsp lemon zest","1/2 tsp salt (, cooking/kosher (Note 2))"],"purpose":"Creamy Dill Sauce:"},{"ingredients":["1 cup dried cranberries","1 cup orange juice","1 cup slivered almonds (, toasted (Note 3))","1/3 cup parsley (, roughly chopped)","1/4 tsp each salt and pepper","1 tbsp extra virgin olive oil"],"purpose":"Holiday \"Tapenade\":"},{"ingredients":["1 pomegranate (, only the seeds)","1/4 cup parsley (, roughly chopped)","3 tbsp lemon juice","2 lemons, extra (, cut in 6 pieces each (for serving, don''t skip this))"],"purpose":"Finishing:"}]', '[{"description":"Creamy Dill Sauce","images":[],"step":1},{"description":"Mix ingredients in a bowl until smooth. Keep refrigerated until required.","images":[],"step":2},{"description":"Holiday Tapenade","images":[],"step":3},{"title":"Plump cranberries","description":"Heat orange juice in a saucepan over high heat until hot. Turn stove off, add cranberries, cover. Stand 15 minutes, then drain in a colander (discard liquid). Cool.","images":[],"step":4},{"title":"Mix","description":"Mix cranberries, toasted almonds (see Note 3), parsley, salt and olive oil in bowl. Use at room temp.","images":[],"step":5},{"description":"Cooking salmon","images":[],"step":6},{"description":"Preheat oven to 180°C/350°F (all oven types).","images":[],"step":7},{"title":"Prepare salmon","description":"Place a large sheet of foil on a tray (double layer for safety is recommended), then top with baking/parchment paper. Place salmon on paper, then fold up the foil sides a bit to cup them so glaze won''t run onto tray.","images":[],"step":8},{"title":"Glaze","description":"Place ingredients in a saucepan over medium high heat. Once it started foaming, turn down to medium, let it foam for 2 minutes then remove and pour straight over the salmon.","duration":2,"images":[],"step":9},{"title":"Season","description":"Sprinkle salmon with salt and pepper, putting most of the salt on the thicker part of the salmon.","images":[],"step":10},{"title":"Wrap","description":"Cover salmon with a smaller piece of paper, then foil. Fold and seal up sides to enclose salmon in a parcel - it doesn''t need to be 100% tightly sealed.","images":[],"step":11},{"description":"Bake 15 minutes. Remove salmon from oven.","images":[],"step":12},{"title":"Uncover / fold excess paper","description":"Remove paper and foil and paper cover. Fold/scrunch paper and foil sides down to expose salmon surface. Tucking paper down also ensures it won''t catch fire when broiling.","images":[],"step":13},{"title":"Grill/broil to brown","description":"Switch oven to grill/broiler on high. Place salmon on middle shelf in the oven and broil 7 to 10 minutes until you get caramelisation mostly on the edges, a bit on top. Don''t put it too close to the heat element otherwise paper might catch on fire! Check to ensure salmon is cooked - either pry open in middle to check or use a probe to check internal temperatures (Note 4).","images":[],"step":14},{"title":"Transfer to plate","description":"Use foil overhang to transfer salmon onto serving platter straight away (otherwise it keeps cooking). Slide the foil then paper out from under the salmon (see video at 1 min 24s or step photos in post), allowing juices to pool on platter (it''s gold stuff!).","images":[],"step":15},{"title":"Cool","description":"Loosely cover with foil, then leave to cool for at least 15 minutes, up to 1 hour or longer (for room temp serving - Note 6 for serving notes).","images":[],"step":16},{"description":"Assembly and serving","images":[],"step":17},{"description":"Dollop then thickly spread with Creamy Dill Sauce (~0.8cm / 1/3\" thick layer).","images":[],"step":18},{"description":"Pile over Holiday Tapenade, scatter generously with pomegranate seeds, and then remaining parsley. Squeeze over lemon juice.","images":[],"step":19},{"title":"Serving","description":"Serve with extra lemon wedges so people can add more to taste. Cut into pieces - I use a cake cutter for serving. Encourage people to slop up some of the honey-butter sauce that will be mixed with semi melted Creamy Dill Sauce - it''s so good! This dish is best served slightly warm, not piping hot, also excellent at room temp.","images":[],"step":20}]', '["fish","milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["easter-mains","easter-mains-fish-seafood","fish-recipes","mains","other","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2d8e8d49a951', 'en', 'US', 'Spanakopita', 'Recipe video above. Spanakopita - the iconic traditional Greek Spinach Pie with layers upon layers of golden buttery flaky filo pastry. For the best Spanakopita of your life, use raw rather than cooked spinach, and layer the phyllo pastry with finely shredded Greek cheese so it sticks together rather than flying everywhere when you cut it!This pie is a perfect thickness with a good ratio of Spinach Feta filling to pastry. It will serve 4 to 5 people as a main dish.', 'https://www.recipetineats.com/tachyon/2021/03/Spanakopita_0-1-1.jpg', 40, 25, 65, 4, '[{"id": "ing_spinach", "quantity": {"value": 300.0, "unit": "bag of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_feta_cheese", "quantity": {"value": 175.0, "unit": "block of 200g"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.15, "unit": "tub of 500g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.04, "unit": "bunch"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_mint", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_dill", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.005, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.005, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_nutmeg", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_sheets_filo_pastry", "quantity": {"value": 16.0, "unit": "pack"}}, {"id": "ing_butter", "quantity": {"value": 120.0, "unit": "block of 250g"}}, {"id": "ing_cheese", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.025, "unit": "pack of 100g"}}]', '[{"ingredients":["300g/10oz English spinach leaves","1/2 tsp salt"],"purpose":"Spinach:"},{"ingredients":["175g/6oz Greek feta (, crumbled)","1/2 cup Greek yoghurt","2 green onions / scallions (, finely sliced)","1 egg","2 tbsp mint (, finely chopped)","1 tbsp dill (, finely chopped)","1/2 tsp lemon zest","1/2 tbsp lemon juice","2 garlic cloves (, finely chopped)","1/2 tsp nutmeg (, freshly grated)","1/4 tsp black pepper","1/4 tsp salt","1/4 tsp cayenne pepper"],"purpose":"Filling:"},{"ingredients":["16 sheets filo pastry (Note 2)","120g/ 8 tbsp butter (, melted)","60g / 2/3 cup Greek Kefalotyri cheese (, finely grated (sub parmesan, Note 3))","1/2 tsp white sesame seeds (or more black)","1/2 tsp black sesame seeds (or more white)"],"purpose":"Filo pastry:"}]', '[{"description":"Preheat oven to 220°C/430°F (200°C fan). Line a tray with baking paper / parchment paper.","images":[],"step":1},{"title":"Sweat spinach","description":"Place spinach in a large colander or bowl. Sprinkle with salt, toss through. Leave for 10 minutes to sweat.","duration":10,"images":[],"step":2},{"title":"Wring out water","description":"Place a handful of spinach in a tea towel, then wring out tightly to remove excess water.","images":[],"step":3},{"title":"Filling","description":"Place spinach in a bowl with remaining Filling ingredients. Mix well to combine.","images":[],"step":4},{"title":"Trim filo","description":"Cut 16 sheets of filo pastry into 32 x 25cm / 13 x 10\" (pictured) or 26cm / 10.5\" square.","images":[],"step":5},{"title":"8 base layers","description":"Layer 8 sheets of filo pastry on the tray, brushing each layer with melted butter.","images":[],"step":6},{"title":"Filling","description":"Spread filling on filo pastry. Smooth surface and leave a 2.5cm / 1\" border.","images":[],"step":7},{"title":"8 Filo topping layers (Note 4)","description":"Cover spinach with a sheet of filo pastry. Brush with butter, sprinkle with Kefalotyri. Repeat for Sheets #2 to #5. Then cover with filo sheets #6 to #8, brushing with butter in between, but do NOT sprinkle with cheese (neater finish).","images":[],"step":8},{"title":"Seal","description":"Press edges down to seal. Crimp and trim if desired (see process steps in post or video) or just leave the edges flat on the tray.","images":[],"step":9},{"title":"Sesame seeds","description":"Brush the top with butter, sprinkle with sesame seeds.","images":[],"step":10},{"title":"Bake","description":"Bake 25 minutes, or until golden brown on the surface.","images":[],"step":11},{"description":"Serve! Serve immediately! It is at its absolute prime fresh out of the oven, though still good as long as its hot (~15 min or so). The base does lose crispiness as it cools.","images":[],"step":12}]', '["egg","milk","sesame"]', '["gluten_free","high_protein","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Greek"],"categories":["easter-mains","greek-recipes","iconic-dishes","mediterranean-recipes","quiches-tart-and-pie-recipes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_22c796ccb172', 'en', 'US', 'Mignonette Sauce for Oysters', 'This is a classic recipe for mignonette sauce to serve with oysters, a staple at fine dining restaurants. Think of this as an elevated alternative to eating oysters with just a squeeze of fresh lemon juice - vinegar provides tang plus extra flavour from eschalots with the bonus of a lovely pink colour!Makes enough for 24 oysters. Some people use only a little, others go to town with it.', 'https://www.recipetineats.com/tachyon/2023/12/Mignonette-sauce-for-oysters_5.jpg', 5, 0, 5, 24, '[{"id": "ing_green_onion", "quantity": {"value": 0.75, "unit": "bunch"}}, {"id": "ing_vinegar", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_oysters", "quantity": {"value": 12.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["2 1/2 tbsp eschalot (US: shallot), finely minced (Note 1)","3 tbsp red wine vinegar (, preferably a good quality one (Note 2))"],"purpose":"Mignonette:"},{"ingredients":["12 - 24 oysters (Note 3)","Black pepper (, sprinkle yourself (Note 4))"],"purpose":"Oysters:"}]', '[{"title":"Mignonette","description":"Mix together in a bowl then set aside for at least 2 hours to let the flavours meld.","images":[],"step":1},{"title":"Serving","description":"Transfer into a little dish with a small spoon. Serve alongside oysters (generally people help themselves).","images":[],"step":2},{"title":"Using","description":"Most people just use about 1/2 tsp for small oysters and 3/4 tsp for large. Some people will use more liberally! Comes down to personal taste.","images":[],"step":3}]', '[]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["snack"],"cuisine":["French","Western"],"categories":["easter-mains-fish-seafood","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_126c0cf1e931', 'en', 'US', 'Tetsuya''s Oysters with Japanese Dressing', 'This recipe is based on Tetsuay’s oyster dressing from his cookbook. I changed the proportions and added sesame and mirin to make the dressing more flavourful and re-align the balance of salt/sweet/tang. I think he uses premium sauces which can cost 5x as much as mainstream brands!If salmon roe is out of reach, just skip it. This dressing is so good on its own. Use liberally and save leftovers for salad or dipping prawns!Makes enough for 24 oysters.', 'https://www.recipetineats.com/tachyon/2023/12/Tetsuya-oysters-Japanese-dressing_4-close-up.jpg', 10, 0, 10, 12, '[{"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.03, "unit": "bottle of 250ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_mirin", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_ginger", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_oysters", "quantity": {"value": 12.0, "unit": "kg"}}, {"id": "ing_salmon_fillets", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_chives", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1 tsp white sugar","1 1/2 tsp Japanese soy sauce (substitute light soy, Note 1)","2 tbsp rice vinegar (Note 2)","2 tsp mirin (Note 3)","3 tbsp grapeseed or vegetable oil (or other neutral oil)","2 tsp sesame oil (, toasted (Note 4))","1 1/2 tsp grated ginger"],"purpose":"Japanese oyster dressing"},{"ingredients":["12 oysters (Sydney Rock or Pacific, Note 5)","20 g / 2/3 oz (1 heaped tbsp) salmon roe (, for topping (optional, makes it extra special, Note 6))","2 tsp chives (, finely sliced)","Rock salt (, crushed ice or leafy greens - for serving bed (Note 7))"],"purpose":"Serving:"}]', '[{"description":"Combine sugar, soy, rice vinegar and mirin in a jug or bowl. Whisk well until sugar is dissolved. Add oils and ginger. Whisk again and use immediately.","images":[],"step":1},{"description":"Place oysters on a serving platter on ice or rock salt (Note 7).","images":[],"step":2},{"title":"Spoon dressing in each","description":"I use 3/4 teaspoon on small oysters and 1 1/4 teaspoon for large. Or more!","images":[],"step":3},{"description":"Top with a small pile of salmon roe, sprinkle with chives. Serve!","images":[],"step":4}]', '["fish","gluten","sesame","soy"]', '[]', '{"mealType":["snack"],"cuisine":["Modern Asian","Modern Japanese"],"categories":["easter-mains-fish-seafood","finger-food","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_62d2e303959b', 'en', 'US', 'Cucumber lime jalapeno granita for oysters', 'Ice cold shavings of lime-cucumber-jalapeno granita goes so well with oysters, especially on hot summer days! I fiddled with the quantities a lot before landing what I think is the perfect balance. Great one to make now and serve tomorrow or even next week. I like that it''s something a little bit different but still easy. Impresses everyone!Makes enough for 24 oysters.', 'https://www.recipetineats.com/tachyon/2023/12/Cucumber-lime-granita-for-oysters-close-up.jpg', 10, 0, 10, 12, '[{"id": "ing_cucumber", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_lime", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_lime", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_jalape_o", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_oysters", "quantity": {"value": 12.0, "unit": "kg"}}, {"id": "ing_jalape_o", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["1/2 cup cucumber (, peeled, watery seeds removed, diced into ~1cm/1/2\" cubes)","1 tsp lime zest","3 tbsp lime juice","2 tsp caster sugar","1 tbsp finely chopped jalapeño (, deseeded (Note 1))"]},{"ingredients":["12 - 24 oysters (Note 2)","Jalapeño slices (, for decoration (optional))"],"purpose":"Serving:"}]', '[{"title":"Granita","description":"Place ingredients in a jug just large enough to fit a stick blender. Blitz until smooth - it should be like a smoothie. Pour in a small container so the depth is no deeper than 3cm / 2.2\". Freeze for 6 hours+.","images":[],"step":1},{"title":"Scrape","description":"Use a fork to scrape into shavings (it''s not hard). Use immediately or return to freezer until required.","images":[],"step":2},{"title":"Serving","description":"Place oysters on a serving platter. (Note 3)","images":[],"step":3}]', '[]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["snack"],"cuisine":["Western"],"categories":["easter-mains-fish-seafood","finger-food","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c0d8526319a5', 'en', 'US', 'Fish koftas', 'Recipe video above. These fish koftas are like your favourite Middle Eastern lamb koftas - except made with fish. Adore the spicing! Serve with Jewelled rice pilaf for a stunning platter of food.Makes 10 to 12 koftas, serves 4 to 5.', 'https://www.recipetineats.com/tachyon/2023/04/Fish-koftas_4.jpg', 20, 10, 35, 10, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_feta_cheese", "quantity": {"value": 70.0, "unit": "block of 200g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_yogurt", "quantity": {"value": 0.225, "unit": "tub of 500g"}}, {"id": "ing_mint", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_rice", "quantity": {"value": 75.0, "unit": "pack"}}]', '[{"ingredients":["500g/1 lb white fish fillets (,skinless, cut in pieces (Note 1))","1 egg white (add leftover yolk to scrambled eggs!)","1/2 red onion (, grated using a box grater (keeps koftas soft!))","2 garlic (, finely minced)","1 tsp cumin powder","1 tsp coriander powder","1/4 tsp cinnamon powder","1/4 tsp cardamom powder","1 tsp cooking salt (kosher salt)","1/2 cup rice flour (sub cornflour/cornstarch)","2 tbsp chopped parsley","70g/ 2.5 oz danish feta (, plus extra for optional garnish (Note 2))","2 tbsp extra virgin olive oil"]},{"ingredients":["3/4 cup plain yogurt (, unsweetened)","1/2 cup (tightly packed) mint leaves","2 tsp lemon juice","1/4 tsp cooking / kosher salt"],"purpose":"Minted yogurt"},{"ingredients":["Parsley or coriander (, roughly chopped)","Persian Jewelled Rice (or plain basmati rice)"],"purpose":"Serving (optional, pictured)"}]', '[{"title":"Fish & egg blitz","description":"Place fish and egg white in a food processor. Blitz on high until smooth. (30 sec to 1 minute) A stick blender also works but it will take a bit longer.","images":[],"step":1},{"title":"Kofta mixture","description":"Add onion, garlic, all the spices, salt, rice flour and parsley. Blitz on high until smooth (1 minute). Consistency should be like a paste. (Note","images":[],"step":2},{"title":"Feta","description":"Remove the blade, then crumble the feta in. Aim for chunks. Mix delicately (so the feta doesn''t disintegrate).","images":[],"step":3},{"title":"Form koftas","description":"Use wet hands so the mixture doesn''t stick. Portion the mixture into 10 - 12 (70g / 1/3 cup each), and shape into a 10cm / 4\" cylinder. Thread onto skewers then slightly flatten to 1.75cm / 2/3\" thick. (Note 3)","images":[],"step":4},{"title":"Cook","description":"Heat olive oil over medium high heat in a large non-stick pan. Cook half the koftas for 2 minutes on each side until golden, or until the internal temperature reaches 50°C/122°F.","duration":2,"images":[],"step":5},{"title":"Rest","description":"Remove onto a plate and cook the remaining koftas. (Internal temperature of cooked koftas will rise to 55°C/131°F).","images":[],"step":6},{"description":"Serve with Minted Yogurt and Jewelled rice pilaf for a stunning platter of food!","images":[],"step":7},{"description":"Blitz all ingredients in a tall jug just large enough to fit a stick blender. Keep refrigerated until required.","images":[],"step":8}]', '["egg","fish","gluten","milk"]', '["keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern","Persian"],"categories":["easter-mains-fish-seafood","fish-recipes","mains","other","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b43d6353d607', 'en', 'US', 'Singapore Chilli Crab', 'Recipe video above. Here''s arguably the most famous crab recipe in the world: Singapore Chilli Crab! For the pinnacle of the experience, make this using fresh, live mud crab that you clean and cut yourself, or ask the fish shop to cut the crab for you (make sure they save the tomalley "crab mustard", Note 8). Be prepared to get messy eating it (half the fun!) – and to be surprised at how quick it is to make! Flavour: The sauce is a bit spicy but not excessively (Note 2 for adjustment). It is supposed to be a bit sweet, vinegary and intensely savoury. It gets massive flavour from the combination of crab juices, tomalley ("crab mustard", Note 8), belachan shrimp paste, and the soy bean paste! The traditional sauce has bits of egg ribbson in it, and includes ketchup - yes, really!Serves 3 - 4 as a meal with rice and some vegetables.', 'https://www.recipetineats.com/tachyon/2021/07/Singapore-Chilli-Crab_4.jpg', 20, 20, 40, 3, '[{"id": "ing_live_mud_crab_or_other_large_crab", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 5.0, "unit": "pack of 100g"}}, {"id": "ing_taucu_paste", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 2.0, "unit": "pack of 3 heads"}}, {"id": "ing_eschalots", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_shrimp", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 5.0, "unit": "pack of 100g"}}, {"id": "ing_ketchup", "quantity": {"value": 0.06, "unit": "bottle of 500g"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_green_onion", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["1.5 kg / 3lb live mud crab or other large, fresh crab"]},{"ingredients":["5 red cayenne chilli (, seeds left in, roughly chopped (Note 2))","2 tbsp taucu paste (fermeted soy paste, sub miso Note 3)","6 garlic cloves ((small), roughly chopped)","2 eschalots (small), roughly chopped (Note 4)","3 tbsp ginger (, roughly chopped (~7.5cm / 3\" piece))"],"purpose":"Chilli paste:"},{"ingredients":["1/4 cup canola oil","1 tbsp belachan dried shrimp paste (, chopped (sub shrimp paste, Note 5))","1 cup tomato passata (Note 6)","1/2 cup sweet chilli sauce","2 tbsp ketchup","2 cups water","1 egg (, lightly whisked)","3 tbsp white vinegar"],"purpose":"Singapore Chilli Crab Sauce:"},{"ingredients":["Fresh coriander (, leaves whole or roughly chopped)","2 tbsp green onion (, finely sliced (or 1/4 cup finely sliced on angle, ice water 3 minutes for slight curl))","Golden mantou buns (Note 7)"],"purpose":"Garnishes/serving:"}]', '[{"title":"Prepare crab","description":"See separate tutorial for how to clean and cut a whole crab. You will end up with: 1) Crab pieces; and 2) Reserved tomalley (\"crab mustard\", Note 8) and crab juices in a separate bowl. This is a key \"secret ingredient\" used to flavour the sauce.","images":[],"step":1},{"title":"Chilli paste","description":"Place ingredients in a small food processor or Nutribullet. Blitz until it''s a fairly smooth paste.","images":[],"step":2},{"title":"Sauté belachan","description":"Heat oil in a large pot over medium-high heat. Add belachan and cook for 2 minutes, stirring constantly. It will smell pungent (to put it mildly), but have faith! It will mellow and transform!","duration":2,"images":[],"step":3},{"title":"Cook off chilli paste","description":"Add chilli paste and cook, stirring, for 3 minutes.","duration":3,"images":[],"step":4},{"title":"Add tomato passata","description":"Add tomato passata and cook, stirring regularly, for 4 minutes.","duration":4,"images":[],"step":5},{"title":"Add remaining sauce ingredients","description":"Add sweet chilli sauce, ketchup, water and stir to combine.","images":[],"step":6},{"title":"Add claws","description":"Add the crab claws first (they take longer to cook), stir to coat in sauce. Bring to a boil, then reduce heat to simmer. Cover with a lid and cook 3 minutes.","images":[],"step":7},{"title":"Add \"crab mustard\" and juices","description":"Add the reserved tomalley (\"crab mustard\") along with all the crab juices.","images":[],"step":8},{"title":"Add remaining crab pieces","description":"Remove lid, add remaining crab pieces and any juices that have collected in this bowl. Stir pieces to coat, put the lid back on and cook for 7 minutes.","duration":7,"images":[],"step":9},{"title":"Remove crab","description":"Use tongs to remove crab pieces into a bowl.","images":[],"step":10},{"title":"Egg ribbons","description":"With the sauce still on the stove, and while stirring in a circular motion, pour the egg in a thin stream into the middle of the pot. This will create little ribbons of egg in the sauce that is traditional and look lovely.","images":[],"step":11},{"title":"Vinegar","description":"Stir in vinegar.","images":[],"step":12},{"title":"Return crab","description":"Return the crab pieces into the pot, gently stir to coat in the sauce.","images":[],"step":13},{"description":"Plating up and serving:","images":[],"step":14},{"description":"Transfer crab pieces into a large serving plate or shallow dish. Pour over all the sauce from the pot. Garnish with coriander and green onion.","images":[],"step":15},{"description":"Serve with golden mantou buns (steamed and fried Chinese buns, traditional - Note 7), or homemade brioche (ultimate sub!), baguette, crusty bread or dinner rolls. Alternatively serve with rice on the side.","images":[],"step":16},{"title":"How to eat","description":"Be prepared to get messy! Dive in for the claw (the prime piece!). Use crab or nut crackers to break the shell (or a meat tenderiser or hammer - anything to get to that meat!!) and reveal hunks of sweet juicy crab meat. Dunk generously in sauce and devour.","images":[],"step":17},{"title":"Leftover Sauce","description":"You will have leftover sauce. It''s loaded with flavour so save it, it''s precious! See in post for ideas for how to use.","images":[],"step":18}]', '["egg","shellfish","soy"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Singapore"],"categories":["easter-mains-fish-seafood","iconic-dishes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a590753dfec0', 'en', 'US', '"Poor Man''s Lobster" – Monkfish with Herb Browned Butter', 'Recipe video above. With sweet, meaty shellfish-like flesh, monkfish is affectionately known as "poor man''s lobster". But there''s certainly nothing "poor" about this dish!If you''re new to cooking monkfish, this is a good recipe to try. It''s easy and showcases just how good monkfish is. There''s a reason it''s a firm favourite with upmarket restaurants!Other names: Stargazer is another name for monkfish in Australia.Allow around 150 - 180g / 5 - 6oz monkfish per serving.', 'https://www.recipetineats.com/tachyon/2021/06/Monkfish_1.jpg', 10, 8, 18, 2, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_thyme", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_chives", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_chervil", "quantity": {"value": 0.5, "unit": "unit"}}]', '[{"ingredients":["300g / 10oz monkfish fillets (, skinless and boneless (Note 1))","1 1/2 tbsp extra virgin olive oil","1/4 tsp salt","1/8 tsp black pepper (, finely ground)","2 tbsp/ 30g unsalted butter (, cut into 1cm (1/2\") cubes)","2 garlic cloves (, smashed (Note 2))","2 sprigs thyme"]},{"ingredients":["1/2 tsp parsley (, finely chopped)","1/2 tsp chives (, finely chopped)","1/2 tsp chervil (, finely chopped)"],"purpose":"Fresh herbs (Note 3):"}]', '[{"title":"Cut fillets","description":"Cut each monkfish into 3 or 4 even size pieces. (Note 1)","images":[],"step":1},{"title":"Season","description":"Sprinkle both sides of fish with salt and pepper.","images":[],"step":2},{"title":"Rack for resting","description":"Place a rack over a tray (optional, for resting fish, Note 5)","images":[],"step":3},{"description":"Cooking monkfish (Note 2):","images":[],"step":4},{"title":"Heat oil","description":"Heat oil in non-stick pan over medium heat (medium-high for weak stoves).","images":[],"step":5},{"title":"Sear first side, then turn","description":"Place thickest pieces of fish in the pan first. Leave for 1 minute then add the thinner pieces. (Note 4). Cook for a further 2 minutes, then flip fish.","duration":1,"images":[],"step":6},{"title":"Add butter and baste","description":"Add butter to pan. After it starts melting, add garlic and thyme. When the butter starts foaming, tilt the pan and start spooning the butter over the fish. Do this for 2 minutes or until the internal temperature is 55°C/131°F (Note 6), or the flesh flakes easily. Butter will begin to smell nutty - it''s now brown butter!","duration":2,"images":[],"step":7},{"title":"Rest","description":"Transfer fish onto the rack and rest for 3 minutes.","duration":3,"images":[],"step":8},{"title":"Add herbs","description":"Add herbs to butter remaining in pan. Serve this Herb Brown Butter with monkfish.","images":[],"step":9},{"description":"Optional plating up, fine dining style!","images":[],"step":10},{"description":"Slice monkfish into 2.5cm / 1\" pieces. Place on pea puree, then drizzle with Herb Brown Butter. Optional garnish with any combination of dill, parsley, chervil.","images":[],"step":11}]', '["milk"]', '["gluten_free","high_protein","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","easter-mains-fish-seafood","fish-recipes","mains","other","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8037edf11742', 'en', 'US', 'Acqua Pazza - Italian Poached Fish', 'Recipe video above. This is a recipe that showcases Italian cooking at its best: a handful of simple ingredients to create something magical! Fish is half poached, half steamed in a tomato-white wine based sauce, then served over crispy garlic crostini.The literal translation of this dish is "fish in crazy water". Maybe because who would think that fish poached in water could be so delicious? That''s crazy! :)', 'https://www.recipetineats.com/tachyon/2021/02/Acqua-Pazza_0.jpg', 10, 40, 50, 2, '[{"id": "ing_fish_fillets", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 0.25, "unit": "pack of 1kg"}}, {"id": "ing_fennel", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 5.0, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 15.0, "unit": "punnet of 250g"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 15.0, "unit": "punnet of 250g"}}, {"id": "ing_chardonnay", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_basil", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}]', '[{"ingredients":["2 x 180g/6oz snapper fillets, or other white fish, (, skin on, bones and scales removed (Note 1))","1/4 tsp salt"]},{"ingredients":["2 tbsp extra virgin olive oil","1/4 red onion (, sliced 1cm / 1/3\" thick)","1/2 fennel (medium) (, sliced sliced 1cm / 1/3\" thick)","1/2 large red chilli (cayenne pepper) (, seeds removed and finely chopped (Note 2))","2 garlic cloves (, finely minced)","15 red cherry tomatoes (, halved)","10 yellow cherry tomatoes (, halved (or more red))","3/4 cup chardonnay (not too woody) (, or other dry white wine (Note 3))","2 cups water","1/4 tsp salt","1 tbsp basil (, finely sliced (keep stems), plus more for garnish)","1 tbsp parsley (, finely chopped (keep stems))"],"purpose":"Sauce:"},{"ingredients":["1 crusty baguette (, cut 4 to 6 slices on a diagonal, 1cm / 1/3\" thick)","1/4 tsp salt","1 - 2 tbsp extra virgin olive oil","1 garlic clove (, halved (for rubbing))"],"purpose":"Garlic Crostini:"}]', '[{"title":"Sauté fennel and onion","description":"Heat oil in a non-stick skillet over medium heat. Add fennel and onion, cook 4 minutes until softened but not golden.","images":[],"step":1},{"title":"Garlic and chilli","description":"Add garlic and chilli, cook for 1 minute until garlic is softened.","duration":1,"images":[],"step":2},{"title":"Tomatoes","description":"Add cherry tomatoes, cook for 4 minutes.","duration":4,"images":[],"step":3},{"title":"Reduce wine","description":"Turn stove up to high, add wine and simmer rapidly for 2 - 3 minutes until reduced by half.","duration":2.5,"images":[],"step":4},{"title":"Simmer sauce","description":"Add water and salt, and the basil & parsley stems if you kept them. Bring to boil, then lower stove to medium and simmer for 20 - 25 minutes until sauce reduces by about 2/3 (it will thicken from tomatoes breaking down).","duration":22.5,"images":[],"step":5},{"title":"Cook fish","description":"Sprinkle flesh side of fish with salt, then place on sauce skin side down (it will mostly sit above sauce). Cover with lid (or foil or tray) and cook for 6 minutes or until internal temperature registers 55°C/131°F (for medium, no rare/raw left with optimum juiciness).","duration":6,"images":[],"step":6},{"title":"Remove fish","description":"Remove lid, transfer fish to plate.","images":[],"step":7},{"title":"Add herbs","description":"Remove basil and parsley stems. Stir basil and parsley into sauce. Taste sauce, add more salt if required.","images":[],"step":8},{"description":"To serve:","images":[],"step":9},{"description":"Place 2 crostini in a shallow bowl. Spoon over a bit of the chunky sauce, top with fish. Spoon remaining sauce around.","images":[],"step":10},{"description":"Garnish with extra basil and a drizzle of olive oil. Serve immediately.","images":[],"step":11},{"description":"Garlic crostini:","images":[],"step":12},{"description":"Preheat oven to 180°C/350°F (all types).","images":[],"step":13},{"description":"Brush olive oil on bread, sprinkle with a bit of salt. Flip and repeat. Bake 10 minutes, turning halfway, or until fully crispy.","images":[],"step":14},{"description":"Rub bread lightly on one side with cut face of garlic. Use warm or at room temperature.","images":[],"step":15}]', '["fish"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["easter-mains-fish-seafood","fish-recipes","italian-recipes","mains","other","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f11a7ddaa101', 'en', 'US', 'Lobster Recipes - for cooked lobster or crayfish', 'Here are 6 easy recipes for cooked lobster or crayfish that make the most of this luxury seafood! When you buy pre-cooked lobster, it''s best to keep it simple to preserve the flavour in the flesh (flavour is better with freshly cooked raw lobster - but much more expensive to buy!).TOP TIP: Keep it simple and don''t re-cook lobster that''s already cooked (risk of drying out, loss of flavour). Treat it like buckets of cooked whole prawns you peel yourself!Rundown of each recipe in recipe notes below.', 'https://www.recipetineats.com/tachyon/2020/12/Lobster-recipes-cover-photo-1.jpg', 5, 0, 5, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_marie_rose_aka_thousand_island", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_tartare_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_seafood_cocktail_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_recipetin_family_favourite_seafood_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_shrimp", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 2.0, "unit": "loaf"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_whole_capers", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_anchovies", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_lobster_meat", "quantity": {"value": 0.16, "unit": "kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.094, "unit": "jar of 400g"}}, {"id": "ing_celery", "quantity": {"value": 0.75, "unit": "head"}}, {"id": "ing_green_onion", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_chives", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 3.0, "unit": "loaf"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.003, "unit": "jar of 40g"}}]', '[{"ingredients":["Whole cooked lobster(s) or crayfish"],"purpose":"Lobster"},{"ingredients":["Marie Rose aka Thousand Island","Tartare Sauce","Seafood Cocktail Sauce (most intense flavoured, use sparingly)","RecipeTin Family Favourite Seafood Sauce (my pick!)"],"purpose":"1. Seafood Sauces for Lobster – choose:"},{"ingredients":["Prawn Cocktail recipe - sub prawns with lobster"],"purpose":"2. Lobster Cocktail"},{"ingredients":["50g / 3 tbsp salted butter (, cut into 1.5cm / 1/2\" cubes (or unsalted + 1/4 tsp salt))","1 garlic clove (, very finely minced)","1/4 tsp black pepper","1 tbsp parsley (, finely chopped)","1 tbsp+ lemon juice","Lemon wedges & 1/2 cup parsley leaves (, for serving)","Crusty bread (, for mopping plate!)"],"purpose":"3. Lobster with Herb & Garlic Butter (enough for 2 lobsters)"},{"ingredients":["Lemon Butter Sauce recipe","1/4 tsp salt","Lemon wedges & 1/2 cup parsley leaves (, for serving)","Crusty bread (, for mopping plate!)"],"purpose":"4. Lobster with French Lemon Butter Sauce (2 lobsters)"},{"ingredients":["1 cup (lightly packed) parsley (, chopped (OK to include some stems, up to 1/4 cup)","1 tbsp whole capers","2 tsp Dijon mustard","1 garlic clove (, chopped)","2 tsp red or white wine vinegar","1 anchove (large, or 2 small) (, chopped)","1/4 cup extra virgin olive oil","1/8 tsp black pepper"],"purpose":"5. Lobster with Salsa Verde (4 lobsters)"},{"ingredients":["160g / 1 cup cooked lobster meat (, cut into 1cm/ 2/5\" cubes (1 x 600g/1.2lb whole lobster))","2 1/2 tbsp kewpie mayonnaise (or Hellman''s) (Note 3)","2 1/2 tbsp celery, finely chopped (~ 1 stalk)","1 1/2 tbsp green onions (, very finely sliced)","2 tsp chives (, finely chopped)","2 tsp lemon juice","1/4 tsp salt","Pinch black pepper","butter (, softened, for buttering buns)","3 mini brioche buns or rolls (or other very soft roll best for this)","Plain potato chips (, for serving (classic accompaniement))","Garnishes (optional): Pinch paprika, chopped chives, lemon wedges"],"purpose":"6. Lobster Rolls"}]', '[{"description":"If lobster was frozen, thaw lobster overnight in a bowl or tray (with sides to catch liquid). Drain well before use.","images":[],"step":1},{"description":"Remove shell (see photos in post):","images":[],"step":2},{"title":"Cut between head and tail","description":"Insert a small knife at a 45 degree angle into the gap between the tail and head. Cut along the top and sides through to the middle - no need to do underneath.","images":[],"step":3},{"title":"Separate head from tail","description":"Twist the tail to separate it from the head. It will pull out meat from the head as well.","images":[],"step":4},{"title":"Clean","description":"Scrape or trim off any yellow of black residue on the end that came out of the head.","images":[],"step":5},{"title":"Cut underside","description":"Cut down both sides of the soft shell on the underside of the tail. Then peel it back like a can of sardines to reveal the lobster flesh.","images":[],"step":6},{"title":"Remove flesh: Carefully remove the flesh","description":"it should come off the shell cleanly.","images":[],"step":7},{"title":"Remove poop vein","description":"if you see a poop vein (black \"string\" down the back of the lobster tail meat), then carefully pull it out. If you stretch the meat out straight, you should be able to pull it out in one go. Otherwise, pick it out when you slice it. (Sometimes poop vein is thick, sometimes barely there!)","images":[],"step":8},{"title":"Residual meat in head","description":"There will be some residual meat in the head that can be used. The yellow \"mustard\" (called tomalley) has very intense lobstar flavour but is an acquired taste... I do not eat it!","images":[],"step":9},{"title":"How to serve","description":"Lobster tail meat can be served whole, sliced into thick or thin pieces or diced, depending on use. I do not recommend shredded as it loses juiciness.","images":[],"step":10},{"description":"Seafood Sauces:","images":[],"step":11},{"description":"Make Sauce per the Dipping Sauces recipe.","images":[],"step":12},{"description":"Serve alongside lobster for dipping. Either cut the lobster into bite size pieces, or serve whole for people to cut themselves. Plate it up individually or on a share platter.","images":[],"step":13},{"description":"Lobster Cocktail:","images":[],"step":14},{"description":"Make the Prawn Cocktail recipe but substitute prawn for lobster cut into small bite size pieces.","images":[],"step":15},{"description":"Lobster with Herb & Garlic Butter:","images":[],"step":16},{"description":"Melt butter in a small skillet over medium heat. Once foamy, add garlic and cook until light golden. Remove from stove, add lemon juice and parsley.","images":[],"step":17},{"title":"Serving","description":"Pour into serving bowl and serve alongside lobster. Garnish with parsley leaves and lemon wedges.","images":[],"step":18},{"title":"Eating","description":"Let people either dip in bite size pieces or drizzle over lobster, plated up indivudually or on a share style plate. Mop plate clean with crusty bread!","images":[],"step":19},{"description":"Lobster with Lemon Browned Butter Sauce","images":[],"step":20},{"description":"Make the sauce per the Lemon Browned Butter Sauce recipe.","images":[],"step":21},{"description":"Slice the lobster into bite size pieces. Pile onto plate or arrange on indivudual plates. Sprinkle with salt (necessary as browned butter is unsalted).","images":[],"step":22},{"title":"Serving","description":"Drizzle with some browned butter, then serve more on the side. Garnish with parsley leaves and lemon wedges.","images":[],"step":23},{"title":"Eating","description":"To eat, dip or drizzle lobster with more browned butter. Mop plate clean with crusty bread!","images":[],"step":24},{"description":"Blitz ingredients in a Nutribullet or small food processor until it becomes a paste. It should be smooth but a bit of courseness for texture ie don''t blend into a smoothie.","images":[],"step":25},{"description":"Slice lobster into bite size pieces. Arrange on indvidual plates or share plate. Drizzle little dollops of salsa verde over lobster - don''t go overboard, the flavour is quite strong!","images":[],"step":26},{"description":"Garnish with lemon wedges & parlsey leaves, serve.","images":[],"step":27},{"description":"Place lobster in a bowl. Add mayonnaise, lemon, chives, celery, green onions, salt and pepper. Gently toss to coat.","images":[],"step":28},{"description":"Split then generously butter buns or rolls. Stuff generously! Makes 2 mini brioche buns or 3 round rolls.","images":[],"step":29}]', '["gluten","milk","mustard","shellfish"]', '[]', '{"mealType":["snack"],"cuisine":["Western"],"categories":["easter-mains-fish-seafood","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_040012ed299e', 'en', 'US', 'Seafood Spaghetti Marinara', 'A classic seafood pasta made with a pre-made seafood marinara mix. This is really simple to make, and the key to this recipe is the step where the pasta is finished cooking in the sauce. This is called "emulsifying", and it''s an essential Italian cooking technique where the starch in the pasta cooking water reacts with the oil in the sauce and makes the sauce thick and luscious so it coats every strand of pasta.', 'https://www.recipetineats.com/tachyon/2016/06/Seafood-Marinara-Spaghetti_2.jpg', 5, 15, 20, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.34, "unit": "pack of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_seafood_marinara_mix", "quantity": {"value": 10.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["6 oz / 180g dried spaghetti pasta (or other long pasta of choice)","2 1/2 tbsp olive oil (, separated)","10 oz / 300g seafood Marinara mix (, or make your own (Note 1))","2 garlic cloves (, minced)","1/2 onion (, finely chopped (~1/2 cup))","1/2 cup white wine (any) (Note 2)","2 cups tomato passata/tomato puree ((Note 3) OR 600g/20oz canned crushed tomato + 1/2 cup water)","1/2 tsp sugar","2 tbsp finely chopped fresh parsley"]}]', '[{"description":"Bring a large pot of salted water to boil. Cook pasta according to packet directions, but reduce the cooking time by 1 minute (because the pasta will finish cooking in the sauce). RESERVE 1 mug of pasta water, then drain the pasta.","images":[],"step":1},{"description":"Separate the seafood mix based on cook time. Longest cook time: fish and medium / large prawns, medium cook time: small prawns, shortest cook time: calamari.","images":[],"step":2},{"description":"Heat 1 1/2 tbsp oil in a large skillet over high heat. Add fish and large prawns first, cook for 30 seconds. Add small prawns, cook for 30 seconds. Add calamari, cook for 1 minute. Immediately transfer everything to a bowl.","duration":0.5,"images":[],"step":3},{"description":"Reduce heat to medium high. Heat remaining 1 tbsp oil, then add garlic and onion. Cook for 3 minutes until onion is translucent.","duration":3,"images":[],"step":4},{"description":"Add wine and bring to simmer, scraping the bottom of the skillet to mix the brown bits into the liquid. Simmer for 1 minute or until alcohol smell has evaporated.","duration":1,"images":[],"step":5},{"description":"Add tomato passata, sugar, salt & pepper. Low heat to medium high, bring to simmer and cook for 2 minutes. Adjust salt and pepper to taste.","duration":2,"images":[],"step":6},{"description":"Add pasta, seafood, around 1/2 cup of reserved pasta cooking water into the sauce. Toss gently and cook for 1 to 2 minutes or until the sauce has thickened and coats the pasta.","duration":1.5,"images":[],"step":7},{"description":"Serve, garnished with fresh parsley. (See Note 4 re: parmesan cheese)","images":[],"step":8}]', '["gluten"]', '["vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["dinner-tonight","easter-mains-fish-seafood","italian-recipes","main-dishes","pasta-recipes","prawns-shrimp","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c4ac09ffe695', 'en', 'US', 'The best Potato Salad', 'Recipe video above. Use this recipe if you want a really great classic potato salad. The secret step: dressing hot potatoes with French Dressing so they absorb the flavour before tossing with a creamy mayo/sour cream dressing. Every bite is perfection! Great fresh, better in 3 hours, even better tomorrow. Thank you for the recipe, Mrs B, it really is the BEST!', 'https://www.recipetineats.com/tachyon/2014/08/Potato-salad_9.jpg', 15, 15, 150, 6, '[{"id": "ing_potato", "quantity": {"value": 2.0, "unit": "bag of 2kg"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 1.25, "unit": "pack of 200g"}}, {"id": "ing_french_dressing_or", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_cucumber", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_celery", "quantity": {"value": 3.0, "unit": "head"}}, {"id": "ing_onion", "quantity": {"value": 37.5, "unit": "pack of 1kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.125, "unit": "jar of 400g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.2, "unit": "tub of 250g"}}, {"id": "ing_cream", "quantity": {"value": 0.333, "unit": "carton of 250ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.167, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}]', '[{"ingredients":["3/4 cup cucumber, finely diced (1 x 15cm/6\" cucumber, cut lengthwise and remove watery seeds first)","2 tsp cooking / kosher salt (, for cooking potatoes)","250g / 8oz streaky bacon","1/2 cup French Dressing (- homemade (below) or store bought (Note 2))","3/4 cup cucumber, finely diced (1 x 15cm/6\" cucumber, cut lengthwise and remove watery seeds first)","1 cups celery, finely sliced diagonally (~ 2 ribs)","1/4 cup white onion, finely minced (, ~ 1/2 onion (Note 3))"],"purpose":"Potato Salad"},{"ingredients":["1/3 cup mayonnaise (, preferably whole-egg)","1/3 cup sour cream (, full fat (sub yogurt))","1 tbsp horseradish cream (or horseradish relish) (Note 4)","1/2 tsp cooking / kosher salt","1/4 tsp black pepper"],"purpose":"Potato Salad Dressing"},{"ingredients":["1 tbsp dijon mustard","2 tbsp white wine vinegar (sub apple cider vinegar)","1/4 cup extra virgin olive oil","1 tbsp water (for volume, rather than more oil)","1/2 tsp white sugar","1/2 garlic clove (, finely grated or minced)","1/2 tsp salt","1/4 tsp black pepper"],"purpose":"French Dressing (essential! Note 2)"}]', '[{"title":"French Dressing","description":"Shake ingredients in a jar until well combined.","images":[],"step":1},{"title":"Cook potatoes (CAREFUL! Note 5)","description":"Put potatoes and 2 teaspoon salt in a large pot of cold water. Turn the stove on. Once the water is simmering, cook for 4 minutes or until the potatoes are JUST cooked (still bit firm in the middle) - they will keep cooking with residual heat. Drain immediately (gently!).","duration":4,"images":[],"step":2},{"description":"Douse hot potatoes! Carefully transfer potatoes into a large bowl and pour over French Dressing. Gently toss to coat then set aside for 2 hours so potatoes absorb the dressing and cool (less fragile).","images":[],"step":3},{"title":"Crispy bacon","description":"Lay half the bacon in a cold non-stick pan. Turn onto medium high and cook until golden (the fat will melt as the pan warms up so it cooks in its own fat). Turn and cook the other side until golden. Drain paper towels, repeat with remaining bacon. Once cool and crisp, chop into small pieces.","images":[],"step":4},{"title":"Creamy Dressing","description":"Mix ingredients in a bowl until combined.","images":[],"step":5},{"title":"Toss","description":"Add creamy dressing, celery, cucumber, onion, and most of the bacon. Toss gently to combine.","images":[],"step":6},{"title":"Serving","description":"Serve garnished with remaining bacon. If time permits, I recommend setting aside for a few hours, or even better, overnight, to give the flavours a chance to meld. But still amazing served straight away! Always serve at room temperature, not fridge cold.","images":[],"step":7}]', '["egg","milk","mustard"]', '["gluten_free","low_calorie"]', '{"mealType":["lunch"],"cuisine":["Western"],"categories":["easter-sides-fresh-light","most-popular","potato-recipes","side-salads","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_182ebe92bda0', 'en', 'US', 'Italian Pasta Salad with Homemade Italian Dressing', 'Recipe video above. If you''re going to make a giant pasta, make it RIGHT with a beautiful homemade Italian Dressing!', 'https://www.recipetineats.com/tachyon/2017/03/Italian-Pasta-Salad-2.jpg', 15, 10, 25, 8, '[{"id": "ing_olive_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_vinegar", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 0.113, "unit": "pack of 200g"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 0.025, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.6, "unit": "pack of 500g"}}, {"id": "ing_thick_salami_cut_into_2_5cm_1_batons", "quantity": {"value": 0.18, "unit": "kg"}}, {"id": "ing_baby_bocconcini", "quantity": {"value": 200.0, "unit": "unit"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_whole_olives", "quantity": {"value": 250.0, "unit": "bottle"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.2, "unit": "punnet of 250g"}}, {"id": "ing_basil", "quantity": {"value": 0.05, "unit": "bunch"}}]', '[{"ingredients":["1/2 cup extra virgin olive oil","1/4 cup red or white wine vinegar (I like using red)","1 1/2 tbsp freshly grated parmesan cheese (Note 1)","1 tbsp sugar (any)","1 large garlic clove, minced","1/2 tsp each dried basil and oregano","1/4 tsp dried parsley","1/2 tsp dried chilli flakes (red pepper flakes) (optional)","3/4 tsp salt","1/2 tsp black pepper"],"purpose":"Italian Dressing"},{"ingredients":["300g/10oz spiral pasta, or other pasta of choice","180g/6oz thick sliced salami, cut into 2.5cm/1\" batons (see photo in post or videos) (I use spicy salami)","200g/7oz baby bocconcini, halved (Note 2)","1 red capsicum/bell pepper, cut into 3cm/2.2cm strips","250g/8oz whole olives (I used Sicilian and pitted black) (Note 3)","2 cups cherry tomatoes, halved (~1.5 Australian punnets)","1 cup (tightly packed) fresh basil leaves"],"purpose":"Pasta Salad"}]', '[{"description":"Place Dressing ingredients in a jar and shake well.","images":[],"step":1},{"description":"Cook pasta according to packet directions minus 1 minute. Drain in a colander and rinse under cold water to stop it cooking further. Shake excess water off well then transfer into large bowl.","images":[],"step":2},{"description":"Place remaining Pasta Salad ingredients in the bowl. Drizzle over Dressing and toss. Serve at room temperature.","images":[],"step":3},{"description":"Make ahead PRO TIP (Note 4):","images":[],"step":4},{"description":"SCOOP OUT a mug of pasta cooking water just before draining. Add 3 tbsp water to Dressing, shake well. Use this Dressing per above, but reserve 3 tbsp to freshen up pasta salad on Day 2 onwards.","images":[],"step":5},{"title":"Freshen up pasta salad","description":"Bring to room temp or briefly microwave (cold pasta = dry) to warm gently. Toss with Reserved Dressing then serve.","images":[],"step":6}]', '["gluten","milk"]', '[]', '{"mealType":["dinner","lunch"],"cuisine":["Italian"],"categories":["dinner-tonight","easter-sides-fresh-light","italian-recipes","no-cook-food","pasta-recipes","pasta-salads-and-rice-salads","quick-and-easy","salad-recipes-main-course"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d0fe3651165a', 'en', 'US', 'JB''s Pommes Anna', 'Recipe video above. Introducing Pommes Anna - the ultimate French potato cake. Thinly sliced potato, lots of butter, crispy edges, soft centre, and a big “wow” moment when you flip it out. We’ve had quite a few of those in the process of developing it! When simple ingredients make beautiful result.', 'https://www.recipetineats.com/tachyon/2025/11/Pommes-Anna_9-1.jpg', 30, 100, 140, 8, '[{"id": "ing_potato", "quantity": {"value": 1.6, "unit": "bag of 2kg"}}, {"id": "ing_butter", "quantity": {"value": 160.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_chilli_flakes", "quantity": {"value": 1.0, "unit": "jar of 40g"}}]', '[{"ingredients":["1.6 kg / 3.5 lb medium starchy potato","160g / 5.6 oz unsalted butter (makes 1/2 cup clarified butter) (Note 2)","1 tsp cooking salt / kosher salt","1/4 tsp white pepper powder"]},{"ingredients":["1 sprinkle sea salt flakes (, if you want (I did!))"],"purpose":"Optional"}]', '[{"description":"Build 3 layers of thinly sliced potatoes (1.5mm / 0.06\") in a spiral pattern brushing with clarified butter and seasoning as you go. Bake 70 minutes at 200°C / 400°F (180°C fan) covered with cartouche then 30 minutes uncovered. Rest 10 minutes, flip, and enjoy!","images":[],"step":1},{"description":"How to make Clarified Butter:","images":[],"step":2},{"description":"Melt the butter in a saucepan or microwave. Set aside for 5 minutes until the milk solids settle on the bottom (white stuff). Scrape off the foam, then slowly pour the clear golden butter through a small sieve into a jug while leaving the milk solids behind (discard it). That clear golden butter is your clarified butter.","duration":5,"images":[],"step":3},{"description":"How to make Pommes Anna:","images":[],"step":4},{"title":"Prep pan","description":"Preheat oven to 200°C / 400°F (180°C fan-forced). Brush the base of a 26cm / 10\" cast-iron skillet with 2 tablespoons of clarified butter. (Note 3)","images":[],"step":5},{"title":"Slice potatoes","description":"Peel potatoes and using a mandolin, slice 2 or 3 potatoes 1.5mm / 0.6\" thick. Quickly sort the slices into small, medium and large sizes. Do not put them in water. (Note 4 + 5)","images":[],"step":6},{"title":"Build the first layer","description":"Using the medium size slices, put one slice in the middle, then build a spiral around it, overlapping each slice by about 3/4. Then, using the larger slices, make a second spiral around the first one until the whole base is fully and evenly covered. If you have medium slices left, you can use them here too. The second spiral should slightly overlap the first to keep the final shape tidy and firm. Tuck some small slices inside the tiny gap in the centre, do this for every layer to keep the middle neat.","images":[],"step":7},{"description":"Brush / dab generously with clarified butter, taking care not to disturb or lift the slices. Season with a third of the salt and white pepper.","images":[],"step":8},{"title":"Build two more layers","description":"Repeat the same spiral pattern for 2 more layers, brushing with clarified butter and seasoning each layer.","images":[],"step":9},{"title":"Cartouche","description":"Place a cartouche (circle of baking paper / parchment paper) on top. (Note 6)","images":[],"step":10},{"description":"Bake for 70 minutes. Remove the cartouche, then bake another 30 minutes until the top and edges are deep golden and crispy.","duration":70,"images":[],"step":11},{"title":"Rest + flip","description":"Rest for 10 minutes on the counter. Flip onto a plate and lift the pan to reveal your beautiful Pommes Anna. Serve immediately, happiness does not wait 😊","duration":10,"images":[],"step":12}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["French"],"categories":["easter-sides-warm-hearty","jbs-recipes","potato-recipes","potatoes","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6677a802b500', 'en', 'US', 'Fondant Potatoes (Melting potatoes)', 'Recipe video above. Golden on the outside and meltingly tender inside (hence the name!), infused with flavour from roasting in a buttery stock. Lovely, elegant way to cook potatoes, very restaurant-y! If you''re in a hurry, don''t worrying about shaping into cylinders. Just cut thick slabs of potato (whatever shape they happen to be!) and cook per the recipe. Or, just use a potato peeler to shape as best you can. It will still taste just as good!', 'https://www.recipetineats.com/tachyon/2023/11/Fondant-potatoes_4-close-up.jpg', 15, 50, 60, 8, '[{"id": "ing_potato", "quantity": {"value": 4.0, "unit": "bag of 2kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_thyme", "quantity": {"value": 6.0, "unit": "bunch"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.25, "unit": "L"}}]', '[{"ingredients":["4 x 400g/14 oz large floury potatoes (, peeled (Aus: Sebago (dirt brushed), US: Russet, UK: King Edward))","3/4 tsp cooking salt / kosher salt","1/2 tsp black pepper","2 tbsp extra virgin olive oil","3 tbsp / 50g unsalted butter (, cut into 1cm / 1/2\" cubes)","6 thyme sprigs (sub 1/2 tsp dried thyme)","1 cup chicken stock / broth (, low sodium (or vegetable))"]}]', '[{"description":"Preheat oven to 200°C / 390°F (180°C fan-forced).","images":[],"step":1},{"description":"Carve / cut each potato into cylinders ~ 6cm/ 2\" diameter, 7 cm height. Then cut in half so you have 8 short cylinders 3.5 cm / 1.4\" tall. See cutting method options below.","images":[],"step":2},{"title":"Season","description":"Pat potato dry. Place in a large bowl and toss with half the oil plus all the salt and pepper.","images":[],"step":3},{"title":"Sear","description":"In an ovenproof heavy based skillet (Note 2), heat the remaining 1 tbsp oil over medium high heat. Put the potato in and cook each side for 6 - 8 minutes or until golden.","duration":7,"images":[],"step":4},{"title":"Cook","description":"Add butter and thyme. Once melted, spoon the butter over the potato (\"basting\"). Add stock, bring to a boil then transfer to the oven and bake for 30 minutes until the potatoes are tender, basting at the 15 minute mark. The stock will be absorbed by the potato, leaving just butter.","duration":30,"images":[],"step":5},{"title":"Serve","description":"Baste one more time then serve! For a restaurant-y option, serve alongside steak with béarnaise sauce and buttered peas.","images":[],"step":6},{"description":"Cutting method options (see video for demo of each):","images":[],"step":7},{"title":"Prep for all methods","description":"Trim a bit off both ends so the potato stands upright. Once carved into a tall cylinder 6cm/ 2\" diameter, at least 7cm/3\" height, so we can cut into 3.5 cm / 1.4\" tall pieces. Save leftover potato to make mash (keep in water to prevent turning brown).","images":[],"step":8},{"title":"Pro method","description":"Lie potato on its side and use a knife to carve around to form a cylinder.","images":[],"step":9},{"description":"Intermediate (I do this)- Stand potato upright and use a knife to shave thin slivers down, rotating as needed, to carve into a cylinder. You can use a potato peeler for some of this too (just be a bit careful, less control).","images":[],"step":10},{"title":"Easy","description":"Use 6cm/ 2\" (or as close as possible) wide cutters to press rounds out!","images":[],"step":11},{"title":"Easy potato peeler","description":"Use a potato peeler to shape as best you can, rotating as you go.","images":[],"step":12},{"title":"Doesn''t matter!","description":"Just cut potatoes into 3.5cm / 1.4\" thick slices! Even if your rounds are not so round, it will still taste delicious. Only cut enough to fill the pan, as pictured, else you''ll have too much potato for the stock being used (flavour dilution),","images":[],"step":13}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["easter-sides-warm-hearty","potato-recipes","potatoes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_377d48e97503', 'en', 'US', 'Creamy Corn Casserole', 'Recipe video above. A sensational side dish for anytime, but especially for Thanksgiving, this creamy Corn Casserole tastes like a cross between corn bread and soufflé. It tastes very corn-y, it''s sweet yet savoury, very moist and soft inside. Make this using corn bread mix OR from scratch!', 'https://www.recipetineats.com/tachyon/2016/11/Creamy-Corn-Casserole_0.jpg', 10, 55, 65, 10, '[{"id": "ing_flour", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 1.05, "unit": "can of 400g"}}, {"id": "ing_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.1, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_corn", "quantity": {"value": 1.05, "unit": "can of 400g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.6, "unit": "tub of 250g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}]', '[{"ingredients":["2/3 cup (100g) flour* (all purpose/plain)","1/2 cup (80g) yellow cornmeal* (Note 2)","1/4 cup (55g) white sugar*","1 tbsp baking powder*","1/4 tsp salt*","Pinch of cayenne pepper"],"purpose":"Dry Ingredients"},{"ingredients":["420 g / 14 oz creamed corn (Note 3 for sub)","420 g / 14 oz canned corn kernels - do not drain!!","2 eggs (, beaten)","1 stick / 115 g unsalted butter (, melted)","1 cup (230g) sour cream","2 tbsp vegetable oil"],"purpose":"Wet Ingredients"}]', '[{"description":"Preheat oven to 325F/165C.","images":[],"step":1},{"description":"Whisk Dry ingredients in a bowl.","images":[],"step":2},{"description":"Add Wet Ingredients, including all the liquid in the canned corn kernels. Mix well.","images":[],"step":3},{"description":"Pour into a 2-2.5 quart / 2-2.5 litre / 8 cup casserole dish.","images":[],"step":4},{"title":"Bake for 55","description":"60 minutes (standard ovens) or 50 minutes (fan forced / convection), or until set but still a bit jiggle in the centre (it will set when cooled). The top should be a deep golden brown.","duration":57.5,"images":[],"step":5},{"description":"Serve warm or even at room temperature.","images":[],"step":6}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Southern"],"categories":["easter-sides-warm-hearty","most-popular","quick-and-easy","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_17f33f311f2f', 'en', 'US', 'Rice Pilaf with Nuts and Dried Fruit', 'Recipe video above. A fragrant rice that''s right at home on your holiday feasting table or a Middle Eastern spread! Switch the nuts and fruit to whatever you want, and feel free to customise the Spices too. This is a rice so good, you''ll be eating it straight out of the pot!', 'https://www.recipetineats.com/tachyon/2018/10/Rice-Pilaf-with-Nuts-and-Dried-Fruit_6.jpg', 10, 20, 30, 5, '[{"id": "ing_pistachios", "quantity": {"value": 0.333, "unit": "unit"}}, {"id": "ing_almonds", "quantity": {"value": 0.2, "unit": "pack of 250g"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.263, "unit": "kg"}}, {"id": "ing_sultanas", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_apricots", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_round_cinnamon", "quantity": {"value": 1.25, "unit": "jar"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.016, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["1/3 cup pistachios (, shelled)","1/3 cup slivered almonds","2 tbsp (30g) unsalted butter (or olive oil)","2 garlic cloves (, minced)","1/2 small onion (, finely chopped)","1 cup (180g) uncooked basmati rice (, (Note 1))","1 3/4 cups (435ml) vegetable or chicken broth / stock","1/2 cup dried sultanas or raisins","1/4 cup dried apricots","Finely chopped parsley (, optional garnish)"]},{"ingredients":["1/4 tsp ground cinnamon","1/4 tsp ground cardamom","1/8 tsp ground cumin","1/4 tsp black pepper"],"purpose":"Spices:"}]', '[{"description":"Place dry, oil free large saucepan or small skillet over medium high heat.","images":[],"step":1},{"description":"Add almonds and pistachios. Toast lightly, shaking the pan, until the nuts smell amazing. Remove immediately.","images":[],"step":2},{"description":"Melt butter in a large saucepan over medium high heat. Add garlic and onion, saute until translucent.","images":[],"step":3},{"description":"Add rice and stir for 30 seconds or until mostly translucent.","duration":0.5,"images":[],"step":4},{"description":"Add Spices, stir. Add broth, sultanas and apricots, stir.","images":[],"step":5},{"description":"Cover with lid, bring to simmer then immediately turn heat down to medium low (low for strong ovens).","images":[],"step":6},{"description":"Cook for 15 minutes or until liquid is absorbed (tilt pot to check). Then remove pot from the stove (still covered) and leave, undisturbed, for 10 minutes.","duration":15,"images":[],"step":7},{"description":"Remove lid, use fork to fluff rice. Add most of the nuts, toss.","images":[],"step":8},{"description":"Transfer to serving bowl. Garnish with remaining nuts and a little sprinkle of parsley if using. Serve!","images":[],"step":9}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Contemporary Middle Eastern","Western - Holiday Sides"],"categories":["easter-sides-warm-hearty","quick-and-easy","rice-recipes","rice-side-dishes","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4bf213b5e501', 'en', 'US', 'Tomato Basil Rice', 'Recipe video above. This is a copycat of the Tomato Basil Rice convenience packs sold at supermarkets. It''s a seasoned rice flavoured enough that you can eat it plain. Ideal served on the side of many mains! Makes 3 cups of cooked rice.', 'https://www.recipetineats.com/tachyon/2018/08/Tomato-Basil-Rice_5.jpg', 7, 15, 22, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_basil", "quantity": {"value": 0.125, "unit": "bunch"}}, {"id": "ing_white_rice", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.263, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_basil", "quantity": {"value": 0.125, "unit": "bunch"}}]', '[{"ingredients":["1 1/2 tbsp olive oil (or butter)","2 garlic cloves (, finely chopped)","1/2 brown onion (, finely chopped)","1 1/4 tsp dried basil","1 cup (180g) long grain white rice (, uncooked (Note 1))","1 3/4 cups (435 ml) chicken broth (, full salt (or Veg broth))","2 1/2 tbsp tomato paste","3/4 tsp paprika (, sweet or normal (not smoked))","1 tsp sugar (any)","1 sprig of basil with leaves","1/3 cup finely chopped basil"]}]', '[{"description":"Heat oil in a large saucepan over medium heat. Add garlic and onion, cook until translucent, 2 - 3 minutes. Add basil and cook for 20 seconds - don''t let it burn.","duration":0.3333333333333333,"images":[],"step":1},{"description":"Add remaining ingredients except basil. Mix until tomato paste is dissolved.","images":[],"step":2},{"description":"Crush basil sprig in hand, drop on surface then push in (leave on surface, don''t stir).","images":[],"step":3},{"description":"Cover and bring to simmer, then immediately turn down heat to medium low (or low if stove is strong) and cook for 15 minutes or until liquid is fully absorbed - tilt saucepan to check.","duration":15,"images":[],"step":4},{"description":"Remove from heat and set aside, covered, for 10 minutes.","duration":10,"images":[],"step":5},{"description":"Remove basil sprig. Fluff with fork, taste for salt. Then leave to stand for another 5 minutes, uncovered. Stir through fresh basil. Serve immediately.","images":[],"step":6}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Italian-esque"],"categories":["dinner-tonight","easter-sides-warm-hearty","quick-and-easy","rice-recipes","rice-side-dishes","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9dd08805e480', 'en', 'US', 'Garlic Butter Rice with Kale', 'Recipe video above. A ripper kale recipe - it''s time to think beyond a salad! There''s an enormous amount of kale hidden in amongst all that buttery, garlicky rice... Try this with spinach, chard or even grated carrots!', 'https://www.recipetineats.com/tachyon/2018/05/Garlic-Butter-Rice-with-Kale_9.jpg', 10, 25, 35, 6, '[{"id": "ing_kale", "quantity": {"value": 7.0, "unit": "unit"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 3.0, "unit": "pack of 3 heads"}}, {"id": "ing_white_rice", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.338, "unit": "kg"}}, {"id": "ing_almonds", "quantity": {"value": 0.2, "unit": "pack of 250g"}}]', '[{"ingredients":["7 cups kale sliced leaves (, tightly packed (1cm / 2/5\" slices) (Note 1))","2 tsp extra virgin olive oil","Salt and pepper"],"purpose":"Marinated Kale:"},{"ingredients":["2 tbsp (30g) unsalted butter","3 - 4 large garlic cloves (, minced)","1 1/2 cups uncooked white rice (Note 2)","2 1/4 cups chicken broth (or vegetable)"],"purpose":"Garlic Butter Rice:"},{"ingredients":["1 - 2 tbsp (15 - 30g) butter","1/3 cup chopped almonds (or other nuts / seeds of choice)"],"purpose":"Finishing:"}]', '[{"description":"Place kale in a large bowl. Drizzle over oil, sprinkle with a small pinch of salt and pepper. Scrunch with hands for 30 seconds, set aside while rice cooks.","duration":0.5,"images":[],"step":1},{"description":"Melt butter in a large pot over medium high heat. Add garlic and stir for 1 minute until just starting to turn golden and is incredibly fragrant.","duration":1,"images":[],"step":2},{"description":"Add rice, stir for 10 seconds.","duration":0.16666666666666666,"images":[],"step":3},{"description":"Add broth, stir, then cover.","images":[],"step":4},{"description":"Turn heat down to medium or medium low so the liquid is simmering very gently. Cook for 12 - 15 minutes until all liquid is absorbed (tilt pot to check).","duration":13.5,"images":[],"step":5},{"description":"Quickly toss all the kale on top of the rice, put the lid back on then remove from heat.","images":[],"step":6},{"description":"Rest for 10 to 15 minutes. Fluff rice with fork, stirring kale through.","duration":12.5,"images":[],"step":7},{"description":"Lastly, stir through extra butter and add salt and pepper to taste.","images":[],"step":8},{"description":"Serve and sprinkle over nuts (or stir nuts through rice).","images":[],"step":9}]', '["milk"]', '["gluten_free"]', '{"mealType":["main_course"],"cuisine":[],"categories":["easter-sides-warm-hearty","quick-and-easy","rice-recipes","rice-side-dishes","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bdd4fa7b16b5', 'en', 'US', 'Mushroom Rice Recipe', 'Recipe VIDEO above. One for mushroom lovers! Brown the mushrooms well so the base of the pot turns brown, then deglaze it with broth so all that flavour ends up in the rice as well as staining it a lovely earthy brown colour. Also see Baked Mushroom Rice!', 'https://www.recipetineats.com/tachyon/2017/08/Mushroom-Rice-Pilaf-4-1.jpg', 10, 20, 30, 8, '[{"id": "ing_olive_oil", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.5, "unit": "pack of 1kg"}}, {"id": "ing_rice", "quantity": {"value": 225.0, "unit": "pack"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.562, "unit": "L"}}, {"id": "ing_green_onion", "quantity": {"value": 1.5, "unit": "bunch"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}]', '[{"ingredients":["2 - 3 tbsp olive oil (, separated)","30g / 2 tbsp butter","750g / 1.5 lb mushrooms (, sliced 3 - 5 mm / 1/8 - 1/5\" thick (Note 1))","2 garlic cloves (, minced)","1 small onion (, finely diced)","1 1/2 cups long grain rice, uncooked (Note 2)","2 1/4 cups vegetable stock / broth (or chicken) (Note 3)","1 1/2 - 2 cups green onions (, sliced)","Optional: More butter to stir through"]}]', '[{"description":"Heat 2 tbsp oil in a large pot over high heat. Add half the mushrooms, and cook for 5 minutes until golden. Season with salt and pepper then remove and set aside (we put these in at the end, mushrooms cooked in rice don''t stay as golden).","duration":5,"images":[],"step":1},{"title":"If the pot is dry, another 1/2","description":"1 tbsp oil, and add butter. When melted, add onions and garlic.","images":[],"step":2},{"description":"Cook for 30 seconds, then add remaining mushrooms. Cook for 5 minutes or until mushrooms are lightly browned (they won''t caramelise as well as the first batch) and the base of the pot is brown.","duration":0.5,"images":[],"step":3},{"description":"Add rice and a splash of broth. Mix so the brown stuff on the bottom of the pot mixes into the liquid. (Video below helpful here)","images":[],"step":4},{"description":"Once the base of the pot is clean, add remaining liquid. Place lid on, bring to a simmer then turn down to medium low.","images":[],"step":5},{"description":"Cook for 15 minutes or until there is no residual liquid (tilt pot to check).","duration":15,"images":[],"step":6},{"description":"Remove from stove, remove lid, QUICKLY toss in reserved mushrooms and scallions, put lid back on. Leave for 10 minutes (do not skip this step!).","duration":10,"images":[],"step":7},{"title":"Fluff rice using a fork or wooden spoon. OPTIONAL","description":"Stir through more butter. :) Serve!","images":[],"step":8}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["dinner-tonight","easter-sides-warm-hearty","main-dishes","mushroom-recipes","quick-and-easy","rice-recipes","rice-side-dishes","side-dishes","sunday-supper","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_dd4da8e257fc', 'en', 'US', 'Coconut Coriander (Cilantro) Lime Rice', 'A classic coconut rice recipe, with the added freshness of lime and cilantro/coriander (can be omitted if you wish). I served this with Hawaiian Marinated Chicken (together, these recipes use 1 standard can of coconut milk). This makes enough rice to serve 4 as a side.', 'https://www.recipetineats.com/tachyon/2016/05/Coconut-Lime-Rice_13.jpg', 5, 20, 25, 4, '[{"id": "ing_rice", "quantity": {"value": 225.0, "unit": "pack"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.469, "unit": "can of 400ml"}}, {"id": "ing_water", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}]', '[{"ingredients":["1 1/2 cups long grain rice, uncooked (jasmine is great too)","3/4 cup coconut milk","1 1/2 cups water","1/2 tsp white sugar","1/4 tsp salt"],"purpose":"Rice"},{"ingredients":["1/4 cup finely chopped coriander / cilantro leaves","1 - 2 tbsp fresh lime juice (adjust to your taste)"],"purpose":"To Finish"}]', '[{"description":"Place Rice ingredients in a medium saucepan over medium heat with the lid on. Bring to simmer then turn down to medium low.","images":[],"step":1},{"description":"Cook for 15 to 18 minutes, or until liquid has been absorbed. Remove from heat, leaving the lid on, and rest for 10 minutes.","duration":16.5,"images":[],"step":2},{"description":"Fluff rice with a fork then stir through coriander/cilantro and lime juice. Adjust lime juice to taste.","images":[],"step":3}]', '[]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["easter-sides-warm-hearty","quick-and-easy","rice-recipes","rice-side-dishes","side-dishes","south-american-recipes","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_045afd61eb0f', 'en', 'US', 'Baked Arancini Balls', 'Leftover risotto is pretty horrid. So turn it into something amazing with just a few ingredients. These arancini balls are baked, not fried, so you won''t feel as guilty when you have seconds....and thirds....and fourths.....', 'https://www.recipetineats.com/tachyon/2014/08/Baked-Arancini-2.jpg', 20, 30, 50, 12, '[{"id": "ing_leftover_risotto", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_cheese", "quantity": {"value": 0.333, "unit": "block of 250g"}}, {"id": "ing_bread", "quantity": {"value": 0.062, "unit": "loaf"}}, {"id": "ing_bread", "quantity": {"value": 0.062, "unit": "loaf"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}]', '[{"ingredients":["3 cups leftover risotto (see note 1)","1 egg","1/3 cup grated cheese (tasty, cheddar, mozzarella or any other good melting cheese)","1/3 cup plain breadcrumbs (Optional - to thicken the risotto. May not be required - see note 2)","1 1/2 cups panko breadcrumbs","1/2 tsp salt","3 tbsp olive oil"]}]', '[{"description":"Combine risotto with the egg and cheese and mix well.","images":[],"step":1},{"description":"Do a test ball to determine stiffness of risotto (optional step - see note 2): Take a slightly mounded scoop of the risotto using an ice cream scooper (about 1/4 cup), roll it into an egg shape and place it upright on a small plate so that it is higher than it is wide. Wait a minute or two and see if it holds its shape. If it collapses at bit, use the plain breadcrumbs to thicken the risotto - you may not need any, you might need more or less. Do another test until you are happy with the consistency.","images":[],"step":2},{"description":"Cover risotto and refrigerate for at least 1 hour.","images":[],"step":3},{"description":"Preheat oven to 180C/350F.","images":[],"step":4},{"description":"Lightly grease or spray a baking tray.","images":[],"step":5},{"description":"Combine panko and salt in a bowl. Then add the olive oil and use your fingers to lightly \"rub\" the olive oil into the panko and disperse it as evenly as possible","images":[],"step":6},{"title":"Make the arancini balls","description":"As per the test ball, make arancini balls using the ice-cream scooper. Drop the balls into the bowl with the panko. Spoon over the panko, then use your fingers to either roll and pat the panko so it sticks to the arancini.","images":[],"step":7},{"description":"Scoop the arancini out of the panko bowl using a dessert spoon and use your fingers to shape it into an egg / cylinder shape.","images":[],"step":8},{"description":"Place the arancini onto the baking tray upright so it stands taller than it is wide. The reason for this is that the arancini will collapse a bit when baking. So by shaping them slightly taller, when they come out of the oven they will be more of a ball shape rather than collapsing into a pattie.","images":[],"step":9},{"description":"Bake for 20 to 30 minutes until golden.","duration":25,"images":[],"step":10},{"description":"Remove from oven, rest for 5 minutes before serving.","duration":5,"images":[],"step":11},{"description":"Garnish with finely chopped parsley if desired.","images":[],"step":12}]', '["egg","milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["snack"],"cuisine":["Italia"],"categories":["easter-sides-warm-hearty","finger-food","italian-recipes","pumpkin","side-dishes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_54f3286f56ec', 'en', 'US', 'Devilled eggs', 'Recipe video above. Arguably everybody''s favourite egg recipe! Easy, affordable party food that''s excellent for making ahead.Making a great one is easy - just don''t overcook the eggs, don''t use too much mayo and make the filling smooth rather than lumpy. Oh, and use butter rather than oil (creamier, tastier - thank you Julia Child!) and enjoy the nifty trick for boiled eggs with a neatly centred yolk.Don''t worry, they''re not spicy. And PS, you don''t need to wait until your next party. They make a great meal with a big Garden Salad on the side!', 'https://www.recipetineats.com/tachyon/2025/02/Devilled-eggs_8.jpg', 20, 10, 43, 18, '[{"id": "ing_egg", "quantity": {"value": 1000.0, "unit": "carton of 12"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_hot_sauce", "quantity": {"value": 0.067, "unit": "bottle of 150ml"}}, {"id": "ing_vinegar", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.025, "unit": "jar of 400g"}}, {"id": "ing_salt", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_paprika", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_chives", "quantity": {"value": 0.015, "unit": "kg"}}]', '[{"ingredients":["12 large eggs (50-55g / 2 oz each in shell, fridge cold (Note 1)"]},{"ingredients":["2 tsp Dijon mustard","2 tsp Tabasco or other hot sauce","1 tsp white wine vinegar","2 tsp mayonnaise (, whole egg mayo preferred, or kewpie)","1/4 heaped teaspoon cooking salt / kosher sale (Note 3)","50 g/ 3 tbsp cold unsalted butter (, cut into 1 cm / 0.2\" cubes)"],"purpose":"Devilled eggs filling (Note 2 for subs):"},{"ingredients":["Paprika (, regular/sweet, or smoked)","1 tbsp chives (, finely chopped)"],"purpose":"Garnish:"}]', '[{"description":"Hard boil eggs, halve, blitz yolks with Filling ingredients except butter, then blitz in butter. Pipe (18 - 20 pieces), garnish, serve!","images":[],"step":1},{"description":"Hard boil eggs with centred yolks:","images":[],"step":2},{"title":"Large pot","description":"Bring a large pot with 15cm / 6 water to the boil. Lower eggs in gently using a spider or slotted spoon. Lower heat a tiny bit if needed to stop the eggs from jostling around so much they crack.","images":[],"step":3},{"title":"Boil and swirl","description":"Boil eggs for 10 minutes. Swirl the water every minute for the first 6 minutes, using the handle of a wooden spoon. Give the water 4 or 5 fast stirs in one direction to make the water and eggs swirl in the water. The centrifugal force will make the yolks cook centred in the egg white (ie no thin broken egg white walls) (Note 4).","duration":10,"images":[],"step":4},{"title":"Peel","description":"Fill a sink with cold tap water. Remove eggs from the boiling water using a slotted spoon or spider. Leave for 5 minutes until cool enough to handle. Tap the base then peel under water (it''s easier).","duration":5,"images":[],"step":5},{"description":"Fill devilled eggs:","images":[],"step":6},{"title":"Remove yolks","description":"Cut eggs in half and remove the yolks using a teaspoon.","images":[],"step":7},{"title":"Filling","description":"Place the yolks and all filling ingredients EXCEPT butter in a small food processor (Note 5). Blitz until yolks are broken up. Add butter and blitz, scraping down the sides as needed, until the butter is blended through. The filling should be creamy (smear with back of spoon to check).","images":[],"step":8},{"description":"Choose the best 18 to 20 egg white halves. (Note 6) Brush yolk crumbs off the cut surface.","images":[],"step":9},{"title":"Pipe","description":"Transfer filling into a piping bag fitted with a nozzle of your choice (I use a star). Fill so it''s mounded - I do about the same amount as a whole yolk.","images":[],"step":10},{"description":"Sprinkle with paprika and chives. Serve! (Best enjoyed at room temperature rather than fridge cold as the filling is creamier.)","images":[],"step":11}]', '["egg","milk","mustard"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["egg-recipes","finger-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_acb331d76563', 'en', 'US', 'Egg sandwich', 'Recipe video above. At the heart of a great egg sandwich is a creamy egg filling and essential to this are soft boiled, not hard boiled eggs! The creamy yolks practically makes its own mayonnaise sauce and the soft-set egg whites almost dissolve in your mouth.If you''re making to impress, refrigerate to firm the filling so you can cut neat edges.', 'https://www.recipetineats.com/tachyon/2023/03/Egg-sandwich_1.jpg', 10, 8, 18, 4, '[{"id": "ing_egg", "quantity": {"value": 6.0, "unit": "carton of 12"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.037, "unit": "jar of 400g"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_chives", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 0.4, "unit": "loaf"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}]', '[{"ingredients":["6 soft boiled eggs (, at room temperature (Note 1))","1 tbsp whole egg mayonnaise (S&W brand best, Note 2)","2 tsp dijon mustard","2 tsp finely chopped chives (sub green onion)","1/2 tsp black pepper","1/8 tsp cooking/kosher salt (yes really, that''s all!)"],"purpose":"Egg sandwich filling:"},{"ingredients":["8 slices soft white sandwich bread (Note 3)","Soft salted butter (, for spreading on bread)"],"purpose":"Sandwich:"}]', '[{"title":"Mash egg","description":"Place the eggs in a bowl and crush with a fork. Once mostly broken up, use a potato masher to mash them up really well. Smaller egg white bits = creamier filling.","images":[],"step":1},{"title":"Filling","description":"Add remaining filling ingredients and gently stir to combine. Taste and add more salt if desired, but add with caution because it''s bizarre how little salt eggs can take!","images":[],"step":2},{"title":"Make sandwich","description":"Butter the bread. Divide filling between 4 pieces of bread, spread evenly edge to edge. Trim crusts (optional), then cut as you wish. (Note 4 tips)","images":[],"step":3},{"title":"Serve","description":"Always serve at room temperature, for best flavour!","images":[],"step":4}]', '["egg","gluten","milk","mustard"]', '["low_calorie","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Universal","Western"],"categories":["egg-recipes","sandwiches-and-sliders"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_44a8ab2a6886', 'en', 'US', 'Carbonara (real)', 'Recipe video above. These days, so many carbonara recipes cheat with cream which is a shame. The traditional method uses raw egg which is mixed vigorously with hot pasta and parmigiana reggiano cheese which transforms into a silky, creamy, luxurious sauce unlike anything you''ve ever had before. Arguably the best pasta dish in the whole world!This is a pasta that must be eaten straight away to truly experience its magnificence. Serve in warm bowls!', 'https://www.recipetineats.com/tachyon/2023/01/Carbonara_6a.jpg', 5, 15, 20, 4, '[{"id": "ing_guanciale", "quantity": {"value": 0.175, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.8, "unit": "pack of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.8, "unit": "pack of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["175g/6 oz guanciale (pancetta or block bacon), ( weight after skin removed (Note 1))","2 large eggs (Note 2)","2 egg yolks (Note 2)","100g/3.5 oz parmigiano reggiano (, finely shredded (or pecorino romano, sub parmesan, Note 3))","1/4 tsp black pepper","400g/14 oz spaghetti","1 tbsp cooking/kosher salt (for cooking pasta)","1/2 cup pasta cooking water","1 garlic clove (, finely minced (optional, Note 4))"]},{"ingredients":["Parsley (, finely chopped)","Parmigiano reggiano"],"purpose":"Garnish (optional):"}]', '[{"title":"Guanciale","description":"Cut into 0.5cm / 1/5\" thick slices then into batons.","images":[],"step":1},{"title":"Carbonara sauce","description":"Place eggs and yolks in a large bowl. Whisk to combine. Then stir in the parmesan and pepper.","images":[],"step":2},{"title":"Cook pasta","description":"Bring 4 litres (4 quarts) of water to the boil with the salt. Add pasta and cook per the packet directions.","images":[],"step":3},{"title":"Reserve pasta water","description":"Just before draining, scoop out 1 cup of pasta cooking water, then drain the pasta.","images":[],"step":4},{"title":"Cook guanciale","description":"While the pasta is cooking, place guanciale in a non stick pan over medium high heat. Cook for 4 to 5 minutes until golden. No oil needed - as the guanciale heats up, the fat will melt so it fries in its own fat. If using garlic, add it in the last minute.","duration":4.5,"images":[],"step":5},{"title":"Pasta in pan","description":"Tip the hot pasta into the pan and toss to coat in guanciale fat.","images":[],"step":6},{"title":"Mix pasta in sauce","description":"Transfer the pasta and any residual fat in the pan into the bowl with the egg. Add 1/2 cup (125 ml) pasta cooking water. Stir vigorously using the handle of a wooden spoon for 1 minute and watch as the sauce transforms from watery to creamy and clings to the pasta strands!","duration":1,"images":[],"step":7},{"title":"Serve","description":"Transfer into warm bowls. Serve immediately, garnished with a little extra parmigiana reggiano if desired, and a pinch of black pepper and finely chopped parsley.","images":[],"step":8}]', '["egg","gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["egg-recipes","egg-yolk-recipes","iconic-dishes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3750abf05ccf', 'en', 'US', 'Pavlova Christmas Tree', 'Recipe video above. The grandest of all Pavlovas!!! With the signature delicate meringue crust and marshmallowy insides, all smothered in cream and berries just like a traditional Pav. More straightforward to make and more stable to stand than you''d expect, the Pav and Coulis can be made the day before.Get the little ones involved building it!To ensure success: Really read the recipe from start to finish, look at the process step photos in the post above and watch the video.', 'https://www.recipetineats.com/tachyon/2020/12/Pavlova-Christmas-Tree_3-2.jpg', 30, 60, 90, 12, '[{"id": "ing_egg", "quantity": {"value": 8.333, "unit": "carton of 12"}}, {"id": "ing_sugar", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.031, "unit": "pack of 400g"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.006, "unit": "L"}}, {"id": "ing_raspberries", "quantity": {"value": 2.0, "unit": "punnet of 125g"}}, {"id": "ing_cream", "quantity": {"value": 2.0, "unit": "carton of 250ml"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.2, "unit": "bottle of 50ml"}}, {"id": "ing_skewers", "quantity": {"value": 28.0, "unit": "pack of 50"}}, {"id": "ing_strawberries", "quantity": {"value": 10.0, "unit": "punnet of 250g"}}, {"id": "ing_strawberries", "quantity": {"value": 10.0, "unit": "punnet of 250g"}}, {"id": "ing_christmas_tree_star_topper", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_raspberries", "quantity": {"value": 2.0, "unit": "punnet of 125g"}}, {"id": "ing_rosemary", "quantity": {"value": 16.0, "unit": "bunch"}}, {"id": "ing_sugar", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_strawberries", "quantity": {"value": 10.0, "unit": "punnet of 250g"}}]', '[{"ingredients":["2/3 cup egg whites (from 5 - 6 large eggs, at room temperature (Note 1))","1 1/4 cups caster sugar (superfine white sugar)","2 1/2 tsp cornflour/cornstarch","1 1/4 tsp white vinegar (Note 2)"],"purpose":"Pavlova:"},{"ingredients":["250g / 8oz frozen or fresh raspberries (no need to thaw, Note 3)","2 tbsp caster sugar (superfine white sugar)"],"purpose":"Raspberry coulis (or strawberry):"},{"ingredients":["2 cups thickened/heavy cream (Note 8)","2 tsp vanilla extract","1 tbsp caster sugar (superfine white sugar)"],"purpose":"Whipped Cream:"},{"ingredients":["28cm/ 11\" bamboo skewer – or 2 shorter skewers (Note 4)","10 strawberries (, medium, cut into 1.75cm / 3/4\" rounds (\"Strawberry Pillars\"))","12 strawberries cut into 1cm dices (for scattering between layers)"],"purpose":"To build:"},{"ingredients":["Christmas tree star topper (, edible or not, sticky taped to a toothpick)","125g/ 4oz raspberries","16 small sprigs of rosemary","2 tbsp icing sugar/powdered sugar (, for dusting)"],"purpose":"Decorating:"},{"ingredients":["More strawberries ((diced), raspberries, blueberries, and any other fruit you fancy!)"],"purpose":"Serving:"}]', '[{"description":"Preheat oven to 150°C / 300°F (130°C fan) (We drop the temperature down later). Set the oven shelves in the centre and lowest racks.","images":[],"step":1},{"title":"Draw circles","description":"Take two sheets of baking/parchment paper and, using a pen that shows on the other side of the paper, trace circles around bowls, cookie cutters, scone cutters or glasses as follows:Tray 1: 15cm, 12cm, 6.5cm (6″, 4.8″, 2.5″) diameter roundsTray 2: 10cm, 8.5cm, 5cm, 4cm (4″, 3.5″, 2″, 1.7″) diameter rounds","images":[],"step":2},{"description":"Turn the paper over and bake on the unmarked side (otherwise pen may stain pav).","images":[],"step":3},{"description":"Meringue for Pavlova:","images":[],"step":4},{"title":"Soft peaks","description":"Place egg whites in a bowl of a stand mixer and beat on Speed 8 for 1 1/2 minutes. (Note 5)","images":[],"step":5},{"title":"Add sugar gradually","description":"With the beater still going, add sugar 1 tablespoon at a time until all used up - it should take around 90 seconds.","images":[],"step":6},{"title":"Beat 6 min","description":"Beat for a further 6 minutes (still on Speed 8) until thick, glossy and no sugar grains remain (rub between fingers to check).","images":[],"step":7},{"title":"Add cornflour & vinegar","description":"Stop beater, sift cornflour over surface. Add vinegar. Beat on speed 8 for a further 30 seconds.","images":[],"step":8},{"title":"Test","description":"Flip bowl upside down. Meringue should be stiff enough that it does not fall out! If it does, keep beating.","images":[],"step":9},{"description":"Piping Pavlova Rounds:","images":[],"step":10},{"description":"Fit a piping bag with a large 1.2cm / 1/2\" diameter star shaped piping nozzle, fill with meringue mixture. (Note 6 for alternatives)","images":[],"step":11},{"description":"Pipe tight coils, leaving a 1.2cm / 1/2\" border within the guidelines for the decorative edge (except the two smallest ones, they are too small for decorative rims).","images":[],"step":12},{"description":"Then do another coil on top (ie two layers) so they are 2cm / 4/5″ thick. Smooth surface. Pipe decorative edge, if using (I just do tight up-and-down swirls, see video).","images":[],"step":13},{"title":"Repeat for all rounds. (Note","description":"Pavs will expand ever so slightly but will not rise)","images":[],"step":14},{"description":"Place Tray 1 on middle shelf in oven, Tray 2 underneath.","images":[],"step":15},{"title":"Turn oven DOWN","description":"Immediately turn oven DOWN to 120°C/250°F (100°C fan).","images":[],"step":16},{"description":"Bake 1 hour. Check to ensure base of large ones are fully crisp and dry, not wet & sticky. You should be able to lift off without sagging - be GENTLE, it''s fragile until dried out.","images":[],"step":17},{"title":"Cool 3 hours IN oven","description":"Turn oven off. Leave pavlova to fully cool in oven, at least 3 hours, maybe longer. I often leave overnight. In this step, the outside of pav dries out and becomes more sturdy. The pav should be fully crisp and dry to touch.","images":[],"step":18},{"description":"Store until needed in airtight containers, in a cool, dry part of your house (I keep mine in the downstairs laundry! Note 9)","images":[],"step":19},{"description":"Raspberry Coulis (make at least 2 hours ahead):","images":[],"step":20},{"description":"Place ingredients in a saucepan over medium heat. Simmer 5 minutes, mashing with fork. Puree with stick blender (strain if you want, I do not). Cool fully before use.","images":[],"step":21},{"title":"Whip cream just before building","description":"do not whip in advance and keep in fridge, it deflates.","images":[],"step":22},{"description":"Place cream, vanilla and sugar in a large chilled bowl. Beat on high for 5 minutes until stiff. (Go beyond soft, lightly whipped, we need the structure!). Refrigerate until the very moment until you start buildling.","duration":5,"images":[],"step":23},{"description":"Construction (watch video!)","images":[],"step":24},{"title":"Be prepared","description":"Have everything out, ready to use. Construct at or near where you plan to serve.","images":[],"step":25},{"title":"Layer 1","description":"Place largest Pavlova Round on serving platter. Spread with 1cm / 2/5\" thick layer of cream, right to the edge. Place 4 strawberry pillars around the edge, onto which the next layer will rest. Gently press them into the cream so they rest on the pav surface. Scatter some chopped strawberries in the middle of the pillars – not too many as we do not want to weigh the pav down. Drizzle with raspberry coulis, especially near the edge so it oozes out prettily. Spread with a bit more cream to cover the strawberries – make sure the cream is level for the next layer. Stick a skewer into the centre, pointy end up.","images":[],"step":26},{"title":"Layer 2","description":"Thread the centre of the next largest Pavlova Round onto the skewer, spinning back and forth gently to \"screw\" it through rather than pushing it through. It won''t shatter – pav is tougher than you think. Repeat the cream, strawberry pillars, strawberry dice, coulis and cream steps above.","images":[],"step":27},{"title":"Repeat Layers 3 to 7","description":"Continue this with layers 3 to 7, finishing with the smallest meringue. You will only need 2 strawberry pillars on the smaller layers, and 1 under the centre of the smallest. If the skewer isn''t long enough, thread through another one for the upper part of the tree. With each layer, check that the tree is straight and level. Use strawberries to level up the layers.","images":[],"step":28},{"title":"Star topper","description":"When the smallest Pavlova is placed on the very top, finish with a dollop of cream, small drizzle of coulis. Then insert the star, plus a raspberry and sprig or rosemary!","images":[],"step":29},{"description":"Decorate with sprigs of rosemary, and insert raspberries onto the edges between layers (halve if necessary, to fit), using them to level out crooked layers, if needed.","images":[],"step":30},{"description":"Dust with icing sugar and then serve immediately!","images":[],"step":31},{"description":"The top 2 layers are single serving size. The next 2 layers will serve 2 people each. The bottom 4 layers can be cut like traditional Pavs and will easily serve another 8 - 10 people.","images":[],"step":32}]', '["egg","milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Dessert"],"categories":["dessert-recipes","egg-white-recipes","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f9aa619a366e', 'en', 'US', 'Béarnaise Sauce - Fast, easy, foolproof method', 'Recipe video above. Béarnaise Sauce, considered by many to be one of the finest steak sauces in the world, and a classic spin on Hollandaise sauce, one of the 5 French “mother sauces.” It''s notoriously difficult to make by hand. This recipe uses a foolproof stick blender method that yields exactly the same results in 2 minutes flat - and has the tick of approval from our resident French Chef JB!Serve over steak or pan seared salmon for a fine dining restaurant experience at home.Makes enough to (very) generously sauce 3 large steaks, or 4 sensible portions.', 'https://www.recipetineats.com/tachyon/2021/02/Spooning-Bearnaise-Sauce-on-Steak_5.jpg', 10, 2, 12, 4, '[{"id": "ing_wine", "quantity": {"value": 0.03, "unit": "bottle of 750ml"}}, {"id": "ing_vinegar", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_tarragon", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 225.0, "unit": "block of 250g"}}, {"id": "ing_tarragon", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_chervil", "quantity": {"value": 0.5, "unit": "unit"}}]', '[{"ingredients":["1 1/2 tbsp white wine (, dry, not too fruity, sweet or woody (Note 1))","1 1/2 tbsp white wine vinegar (Note 2)","1/4 tsp black pepper (, coarsely crushed)","1 eschallot (small), peeled and finely sliced (Note 3)","2 sprigs tarragon (Note 6)"],"purpose":"Infused Vinegar :"},{"ingredients":["3 egg yolks (, at room temperature (Note 4))","1/4 tsp salt (, kosher/cooking salt)","225g / 16 tbsp unsalted butter (, cut into 1cm / 1\" cubes - 2 US sticks (Note 5))","1/2 tbsp tarragon leaves (, finely chopped (Note 6))","1/2 tbsp chervil (, finely chopped (Note 6))"],"purpose":"Béarnaise Sauce:"}]', '[{"description":"Infused Vinegar:","images":[],"step":1},{"description":"Place Infused Vinegar ingredients in a small saucepan over medium low heat.","images":[],"step":2},{"description":"Simmer for 2 minutes, then remove from stove and let it stand for 5 minutes to infuse.","duration":2,"images":[],"step":3},{"description":"Strain, pressing to extract as much liquid as possible. You should have around 1 tbsp of liquid. Cool 5 minutes before use.","images":[],"step":4},{"description":"Quick Clarified Butter:","images":[],"step":5},{"description":"Place butter in a jug and microwave until melted (1 - 1½ minutes on high, but watch it carefully so it doesn''t explode!).","images":[],"step":6},{"description":"Stand for 30 seconds until the milky whites settle at the bottom (this is the milk solids) and clarified butter (golden part) sits above it.","duration":0.5,"images":[],"step":7},{"description":"Pour off 175g / 3/4 cup of the clarified butter, discard the milky whites remaining. Use in this recipe while hot.","images":[],"step":8},{"title":"Alternative","description":"Just melt 175g / 3/4 cup ghee, which is the same thing as clarified butter.","images":[],"step":9},{"description":"Béarnaise Sauce:","images":[],"step":10},{"description":"Place egg yolks, infused vinegar and salt in a tall, narrow container that the blender stick fits in all the way to the base. Blitz briefly to combine.","images":[],"step":11},{"description":"With the stick blender going on high, slowly drizzle the butter in over about a minute. Important: The butter must still be hot! If it has cooled, reheat until hot.","images":[],"step":12},{"description":"After all the butter is in, blitz for a further 10 seconds, moving the stick up and down.","images":[],"step":13},{"title":"Thickness","description":"Add 1 tablespoon water, then blitz to incorporate. Add more water as needed, 1 teaspoon at a time, until the Bearnaise Sauce is a thick sauce but loose enough to ooze across a steak, coating it thickly.","images":[],"step":14},{"title":"Fresh herbs","description":"Stir in tarragon and chervil.","images":[],"step":15},{"title":"Using","description":"Use immediately, or keep warm until required. I use a thermos – a good one will keep it warm for at least 1 hour. Use warm or at room temperature. See note for storing and reheating.","images":[],"step":16}]', '["egg","milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["French"],"categories":["egg-yolk-recipes","roast-beef"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3aa975dedc92', 'en', 'US', 'Hollandaise sauce', 'Recipe video above. The easy way to make this classic French Sauce! The end result is just as good as making it the classic way by hand -- which takes a good 15 minutes of whisking set over a double boiler and plenty of experience -- except it takes 90 seconds flat and it''s foolproof.I prefer using a stick blender rather than normal blender because there''s less waste / easier to scrape the sauce out.Use this sauce for Eggs Benedict, over aspargus, steak - it can fancy up anything! See in post for a list of ideas and notes for how to reheat leftovers easily.Makes about 1 1/4 cups, enough for 8 Eggs Benedict (ie 8 individual eggs). This sauce is rich, you don''t need much per serve!', 'https://www.recipetineats.com/tachyon/2020/10/Reheating-Hollandaise-Sauce_9.jpg', 5, 3, 8, 8, '[{"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.045, "unit": "net of 500g"}}, {"id": "ing_water", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 175.0, "unit": "block of 250g"}}]', '[{"ingredients":["3 egg yolks (, from large eggs (55-60g / 2 oz each, Note 1))","1/4 tsp cayenne pepper (or white pepper)","1/4 tsp salt ((or)","1 1/2 tbsp lemon juice (, plus more to taste)","1 1/2 tbsp water","175 g/ 1 1/2 sticks unsalted butter (, cut into 1.5 cm / 1/2\" cubes (Note 2))"]}]', '[{"description":"Place egg yolks in a tall narrow container that the blender stick fits in all the way to the base.","images":[],"step":1},{"description":"Add water, lemon juice, cayanne pepper and salt. Blitz briefly to combine.","images":[],"step":2},{"description":"Melt butter in a heatproof jug until hot (be very careful to ensure it doesn''t explode if using microwave!). If you use a stove, pour into a jug.","images":[],"step":3},{"description":"Let butter stand for just 15 seconds or so until the milky whites settles at the bottom of the jug. (Note 2)","images":[],"step":4},{"description":"With the blender stick going on high, slowly pour the butter in a thin stream into the eggs over around 45 seconds. Leave behind most of the milky whites in the butter - about 1 1/2 tbsp. (Note 2) Once all the butter is in, the sauce should be thick, creamy, smooth and pale yellow.","images":[],"step":5},{"description":"Now blitz for a further 10 seconds, moving the stick up and down.","images":[],"step":6},{"title":"Thickness","description":"If too thick, mix in warm tap water 1 teaspoon at a time.","images":[],"step":7},{"title":"Salt adjustment","description":"Add a touch of extra salt if using for something non salty like asparagus, leave salt as is if pairing with salty foods like Eggs Benedict, steak, fish.","images":[],"step":8},{"title":"Lemon adjustment","description":"Make it slightly more tangy that you want if using for something like Eggs Benedict, steak or salmon (because it''s diluted when you eat it, and also balances the rich food). But make it perfectly lemony to your taste if using for something like Asparagus.","images":[],"step":9},{"title":"Using","description":"Use immediately, or keep warm until required - if covered and wrapped in a tea towel, it will stay warm for 15 minutes. Use warm or at room temperature. Use warm tap water for loosening. See note for storing and reheating.","duration":15,"images":[],"step":10}]', '["egg","milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["French","Western"],"categories":["egg-yolk-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_71901cfc2c78', 'en', 'US', 'Persian Saffron Rice (Tachin)', 'Recipe video above. This is a rice side dish that will steal the show! The rice stays fluffy and tastes quite rich, but it''s not heavily flavoured (hence suitable as a side dish), yet is flavoured enough that you''ll want to eat it plain. The barberries provide welcome pops of sour but don''t fret if you can''t find them, see Note 2 for substitutions. This rice dish will pair terrifically with any Persian / Middle Eastern / Lebanese / Gulf recipes. See in post for Persian Feast menu!', 'https://www.recipetineats.com/tachyon/2018/09/Persian-Saffron-Rice-Tachin_7a.jpg', 15, 65, 80, 9, '[{"id": "ing_basmati_rice", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_barberries", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_water", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_saffron_threads", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_water", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_yogurt", "quantity": {"value": 0.3, "unit": "tub of 500g"}}, {"id": "ing_oil", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}]', '[{"ingredients":["2 cups / 360g basmati rice, uncooked (Note 1)","1 tbsp salt","3 litres / 3 quarts water"],"purpose":"Parboiled Rice:"},{"ingredients":["1/2 cup dried barberries (Note 2)","2 tbsp / 30g unsalted butter","1 1/2 tsp rose water (optional)"],"purpose":"Barberries:"},{"ingredients":["1 tsp saffron threads (Note 3)","2 tbsp warm water","1 cup / 250 g plain yogurt (I use Farmers Union Greek Yogurt)","1/2 cup / 125 ml oil (, neutral (or butter!))","3 egg yolks (Note 4 for using leftover whites)","3/4 tsp salt"],"purpose":"Saffron Rice:"}]', '[{"description":"Parboiled Rice:","images":[],"step":1},{"description":"Bring water to the boil in a large pot. Add salt and rice. Bring back up to the boil then cook for 5 minutes. Drain and leave to steam dry for 5 minutes.","duration":5,"images":[],"step":2},{"description":"Melt butter in a small pan over medium heat. Add barberries and cook for about 1 1/2 minutes until they plump up (see video!).","images":[],"step":3},{"description":"Remove from heat (they will shrivel quickly) then stir through rose water (if using).","images":[],"step":4},{"description":"Preheat oven to 200C/390F (standard) or 180C/350F (fan).","images":[],"step":5},{"description":"Lightly grease a glass pie dish with oil.","images":[],"step":6},{"description":"Ground saffron into powder (optional step). Add water and leave to seep for 10 minutes.","duration":10,"images":[],"step":7},{"description":"Mix yogurt, egg, oil, saffron water and salt in a large bowl.","images":[],"step":8},{"description":"Add rice, stir well.","images":[],"step":9},{"description":"Pour half the rice in the pie dish, smooth surface. Top with 1/3 of the barberries.","images":[],"step":10},{"description":"Cover with remaining rice, smooth surface, sprinkle over another 1/3 of the barberries. Press down firmly, cover with foil.","images":[],"step":11},{"title":"Bake 60","description":"80 minutes until the crust is deep golden all over.","images":[],"step":12},{"description":"Rest for 10 minutes. Remove foil. Place serving plate on pie dish then flip upside down (it won''t stick because of the oil, see video!).","duration":10,"images":[],"step":13},{"description":"Scatter surface with remaining barberries then serve.","images":[],"step":14}]', '["egg","milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Persian"],"categories":["egg-yolk-recipes","quick-and-easy","rice-recipes","rice-side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7be39f3c2fa0', 'en', 'US', 'Crispy pea fritters - great emergency meal!', 'Recipe video above. This is a super handy recipe for when your fridge is looking a little bare, because who doesn’t have some frozen peas lurking in the back of your freezer? Grab them and a bag of pre-shredded cheese, and you’ll have a stack of these crispy golden fritters on the table in 20 minutes flat! PS The more rustic they are, the better. Because rustic = ragged edges = more crispy cheesy edges. OBSESSED.', 'https://www.recipetineats.com/tachyon/2024/07/Crispy-pea-fritters_4-3.jpg', 10, 10, 20, 9, '[{"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.094, "unit": "pack of 400g"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.017, "unit": "tub of 150g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_frozen_peas", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 2.25, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_yogurt", "quantity": {"value": 0.15, "unit": "tub of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.833, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["1/4 cup flour ((plain/all-purpose) - Note 4 gluten free)","1/4 cup cornflour / cornstarch (, or more flour (Note 1))","1/2 tsp baking powder","1/2 tsp garlic powder","1/2 tsp cooking salt ((kosher salt), or 1/4 tsp table salt)","1/4 tsp black pepper","1 large egg (~55g/2 oz)","2 tbsp milk ((any type, any fat %), or water)"],"purpose":"Batter:"},{"ingredients":["2 cups frozen peas (, still frozen (break up large clumps) (Note 2))","1 cup shredded cheese ((cheddar, tasty, colby - anything that melts, Note 3), packet shredded is fine)","3/4 cup finely sliced green onion (ok to omit)"],"purpose":"Add-ins:"},{"ingredients":["1/4 cup olive oil (, for cooking)"],"purpose":"For cooking:"},{"ingredients":["1/2 cup plain yogurt","2 tsp lemon juice","2 tsp extra virgin olive oil","1/8 tsp finely grated garlic (, optional)","Pinch each salt and pepper"],"purpose":"Lemon Yoghurt Dipping Sauce:"}]', '[{"description":"Abbreviated recipe","images":[],"step":1},{"description":"Mix the Batter ingredients. Stir in the Add-ins. Scoop, flatten, cook 1 1/2 minutes each side. Eat!","images":[],"step":2},{"description":"Full instructions","images":[],"step":3},{"title":"Lemon Yogurt Dipping Sauce","description":"Mix the ingredients together in a bowl and set aside while you cook the fritters to let the flavours meld.","images":[],"step":4},{"title":"Fritter batter","description":"Mix the Batter ingredients until combined. Add the Add-ins, then mix until the batter coats all the peas. It will look like waaaay too much peas for batter, but have faith! The batter will set as it cooks.","images":[],"step":5},{"title":"Measure & flatten","description":"Heat enough oil to cover the base of a pan on medium high (~2 1/2 tbsp). Pack a 3 tbsp cookie scoop (#20) or 1/4 cup measure firmly with the mixture. Place mound in the pan, then flatten to 1.25 / 0.5\" thick. Repeat to to fill the pan (I do 4 - 5 at a time)","images":[],"step":6},{"title":"Cook","description":"Cook for 1 1/2 minutes until the underside is golden, then turn and cook the other side for 1 1/2 minutes until golden and crispy. Transfer onto a paper towel lined tray. Repeat with remaining batter to make 9 -10 in total.","images":[],"step":7},{"description":"Serve with Lemon Yogurt Dipping Sauce!","images":[],"step":8}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dinner","snack"],"cuisine":["Western"],"categories":["emergency-recipes","fritters-tots-and-similar","quick-and-easy","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_dc1bf0ffe4b5', 'en', 'US', 'Penne all''Arrabbiata (spicy tomato pasta)', 'Recipe video above. “Arrabbiata” means “angry” in Italian and refers to how the spiciness of this classic Italian pasta! I love how this simple dish is made interesting with a good kick of chilli.To be authentic, use whole peeled tomatoes and mash them up with a fork. For convenience, I use crushed tomatoes. SPICINESS - See Note 1.', 'https://www.recipetineats.com/tachyon/2023/10/Penne-Arrabbiata-4.jpg', 5, 20, 25, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.8, "unit": "pack of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 1.0, "unit": "jar of 40g"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["400g/ 14oz penne or ziti (, or other pasta of choice (short or long))","1 tbsp cooking / kosher salt (, for cooking pasta)"]},{"ingredients":["4 tbsp extra virgin olive oil","3 garlic cloves (, finely minced)","1 red cayenne pepper chilli (, finely chopped (with seeds) (Note 2))","1/2 tsp chilli flakes (red pepper flakes)","800g / 28 oz canned crushed tomato","1 1/4 tsp cooking / kosher salt","1/4 tsp black pepper","1/2 tsp white sugar (, only if needed (Note 3))"],"purpose":"Arrabiata sauce:"},{"ingredients":["parmesan (, finely grated)","2 tsp finely chopped parsley (, optional)"],"purpose":"Serving:"}]', '[{"title":"Sauté","description":"Heat oil in a large pot over medium heat. Add garlic and stir for 10 seconds. Add cayenne and chilli flakes. Cook for 1 minute, or until garlic is light golden.","duration":0.16666666666666666,"images":[],"step":1},{"description":"Add tomato, salt and pepper. Rinse out the tomato cans with the water and add into the pot.","images":[],"step":2},{"title":"Simmer","description":"Turn up the heat to high, stir, then once it comes to a simmer, turn back down to medium heat and simmer for 15 minutes. (Taste check at 10 min – if sour, add the sugar.)","duration":15,"images":[],"step":3},{"title":"Cook pasta","description":"Meanwhile, bring a large pot of water to the boil with the 1 tablespoon of salt. Add pasta and cook per packet directions.","images":[],"step":4},{"title":"Save water","description":"Just before draining, give the pot a big stir (to agitate the starch) then scoop out 1 cup of the water and set aside. (Note 4) Drain pasta.","images":[],"step":5},{"title":"Toss","description":"Add pasta into the sauce along with 1/2 cup of the pasta cooking water. Toss well (still on the stove) until the pasta is coated with the pasta sauce. Use extra pasta cooking water if needed, to loosen.","images":[],"step":6},{"title":"Serve","description":"Divide between bowls and serve immediately with parmesan and parsley, if using.","images":[],"step":7}]', '["gluten","milk"]', '["vegetarian"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["emergency-recipes","italian-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_59ae4eb71402', 'en', 'US', 'Emergency "Dump ''n Bake" Fried Rice', 'Recipe video above. This recipe was conceived as an emergency, ultra low-effort side dish. Just dump all the ingredients in a pan, and shove it in the oven. End result: seasoned rice that''s amazingly similar to wok-tossed fried rice! Every grain of rice is perfectly cooked and fluffy, and the bacon even goes golden!Uses less liquid than the usual 1 : 1.5 rice to water ratio because we need to factor in the water that comes off the frozen vegetables (a surprising amount!).Bonus: this recipe starts with uncooked rice. No need to plan ahead with day-old cooked rice like you usually do!Add in options - like eggs, chicken, see Notes.PLEASE DO NOT stray from recommended rice per recipe. If you do, I cannot guarantee outcome!', 'https://www.recipetineats.com/tachyon/2021/07/Baked-Fried-Rice_80.jpg', 5, 50, 55, 5, '[{"id": "ing_white_rice", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_frozen_veg", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_bacon", "quantity": {"value": 0.938, "unit": "pack of 200g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.5, "unit": "bunch"}}]', '[{"ingredients":["1 1/2 cups long grain white rice (, UNCOOKED (Note 1))","2 cups chicken or veg stock (, low sodium)","1 1/2 tbsp light soy sauce (Note 2)","1 tbsp Chinese cooking wine (dry sherry, mirin or sake, Note 3)","2 garlic cloves (, minced with crusher (straight into pan))","2 cups frozen diced veg (carrots, peas, corn mix, Note 4 fresh veg)","1/4 tsp white pepper","1 1/4 cups / 180g bacon (uncooked) or ham (, chopped (I use store bought chopped bacon, Note 5))"],"purpose":"Baked Fried Rice:"},{"ingredients":["1 tbsp sesame oil","1/2 cup green onion (, finely sliced (2 - 3 stems))"],"purpose":"Finishing:"}]', '[{"description":"Preheat oven to 200°C / 390°F (180°C fan).","images":[],"step":1},{"title":"Mix ingredients in baking dish","description":"Place all Baked Fried Rice ingredients except bacon in a baking dish (~22 x 32cm / 9 x 13\"). Stir, then spread rice evenly across pan.","images":[],"step":2},{"title":"Top with bacon","description":"Scatter bacon across surface.","images":[],"step":3},{"title":"Bake covered 40 min","description":"Cover with foil. Bake 40 minutes.","images":[],"step":4},{"title":"Bake uncovered 15 min","description":"Remove foil. Bake uncovered 15 minutes - this will colour the bacon. Liquid should be absorbed, rice should be cooked (but will seem wet, will absorb and soften while resting).","images":[],"step":5},{"title":"Rest 10 min","description":"Cover loosely with foil, stand for 10 minutes.","duration":10,"images":[],"step":6},{"title":"Fluff","description":"Add green onion and sesame oil. Fluff rice with fork, marvel at how perfectly cooked the rice grains are. Serve!","images":[],"step":7}]', '["gluten","sesame","soy"]', '[]', '{"mealType":["main_course"],"cuisine":["Asian"],"categories":["emergency-recipes","fried-rice","quick-and-easy","rice-recipes","rice-side-dishes","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_34a60a0d3508', 'en', 'US', 'No-Stir Creamy Lemon & Herb Baked Risotto (it''s magic!)', 'Recipe video above. This risotto recipe is made using an entirely hands-off oven method that makes risotto possible even on the busiest nights! Ultra creamy, no stirring and you don''t even need to sauté onion and garlic - they "saute" in the oven because they floats on the surface with the butter. Surely the most easy risotto in the world!Fragrant with lemon and herbs, it''s good enough to eat on its own but makes a wonderful accompaniment to meats, fish, seafood and mains as a side that''s also a semi-sauce, such as in Monday''s Crispy Skin Salmon.', 'https://www.recipetineats.com/tachyon/2020/11/Creamy-baked-risotto-lemom-herb_9.jpg', 5, 35, 40, 5, '[{"id": "ing_arborio_rice", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_chives", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_dill", "quantity": {"value": 0.045, "unit": "kg"}}]', '[{"ingredients":["1 1/2 cups Arborio risotto rice (Note 1)","4 cups chicken stock (, low sodium (or vegetable))","1/2 onion (, finely diced (brown, white, yellow))","1 garlic clove (, finely minced (large!))","30g/ 2 tbsp butter (, unsalted, cut into 1.5cm / 1/2\" pieces)","1/2 tsp black pepper"],"purpose":"Risotto:"},{"ingredients":["1/3 cup parmesan cheese (, finely grated (store bought pre grated is fine))","30g/ 2 tbsp extra butter (, unsalted, cut into 1.5cm / 1/2\" pieces (Note 3))"],"purpose":"Finishes:"},{"ingredients":["2 tsp lemon rind (1 lemon)","2 - 3 tbsp lemon juice","1 tbsp parsley (, finely chopped)","2 tbsp chives (, finely chopped)","3 tbsp dill (, finely chopped)"],"purpose":"Lemon Herb Flavour (excellent with fish & prawns, Note 4):"}]', '[{"description":"Preheat oven to 180°C/350°F (all oven types).","images":[],"step":1},{"title":"Heat stock","description":"Heat up the chicken stock until just before boiling using whatever method suits - stove or microwave.","images":[],"step":2},{"title":"Pour everything into casserole dish","description":"Pour the stock into a small casserole pot ~24cm/10\" wide. Then add all the remaining Risotto ingredients - rice, butter, onion, garlic, pepper.","images":[],"step":3},{"title":"Bake 35 minutes","description":"Cover with lid or foil, bake 35 minutes or until rice is just cooked - tender but not mushy. The risotto will still look liquidy - that''s what you want to ensure risotto is creamy at the end!","images":[],"step":4},{"title":"Stir vigorously","description":"Remove from oven, stir ta few times to break up rice. Add finishing butter and parmesan, then stir vigorously until the watery liquid becomes creamy, and mostly evaporates/gets absorbed.","images":[],"step":5},{"title":"Goal","description":"oozy and creamy:The risotto should be oozy and creamy, not thick, gluey or stodgy. If it gets too thick, add 1 tbsp of boiling water at a time to loosen it up, stirring well after each addition.","images":[],"step":6},{"title":"Taste for salt","description":"Taste for seasoning and adjust (I find it''s just right).","images":[],"step":7},{"description":"Serve asap! Serve while hot and creamy, topped with more parmesan if desired!","images":[],"step":8},{"description":"Lemon Herb flavouring option:","images":[],"step":9},{"description":"Add lemon rind, juice and herbs, stir through gently just before serving.","images":[],"step":10}]', '["milk"]', '["gluten_free"]', '{"mealType":["main_course"],"cuisine":["Italian","Western"],"categories":["emergency-recipes","quick-and-easy","rice-recipes","rice-side-dishes","risotto-recipes","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_29409440487b', 'en', 'US', 'Swiss Mushroom Burgers', 'Recipe video above. Big, juicy Swiss Mushrooms Burgers are a mighty vegetarian burger that at first glance, looks like a beef burger! Large mushrooms are roasted with garlic butter, topped with Swiss cheese then stuffed into fully loaded soft rolls.Only got small mushrooms? No worries, read the recipe notes!Desperate for meat? Add a meat burger pattie (beef, chicken mince/ground, or chicken breast/thigh), or even bacon and egg!Fully loaded veggie burger - add a vegetarian burger pattie (one of my signature recipes!).', 'https://www.recipetineats.com/tachyon/2020/08/Easy-Swiss-Mushroom-Burgers_7.jpg', 10, 40, 50, 4, '[{"id": "ing_mushroom", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_cheese", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 3.0, "unit": "pack of 1kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.25, "unit": "jar of 400g"}}, {"id": "ing_ketchup", "quantity": {"value": 0.06, "unit": "bottle of 500g"}}, {"id": "ing_sriracha", "quantity": {"value": 1.0, "unit": "bottle of 400ml"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_lettuce", "quantity": {"value": 8.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_french_fries", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}]', '[{"ingredients":["4+ BIG mushrooms - like portobello, BBQ flat mushrooms (20% larger than buns, or buy multiple per burger) (Note 1)","30g / 2 tbsp unsalted butter","2 garlic cloves (, finely minced)","1/2 tsp each salt and pepper","1/2 tbsp olive oil","4 slices swiss cheese (or any other cheese slice of choice)"]},{"ingredients":["3 onions (, cut into 0.7cm / 1/3\" rings)","1 tbsp olive oil","1/4 tsp each salt and pepper"],"purpose":"Onions (or use raw red onions)"},{"ingredients":["2/3 cup mayonnaise (or sour cream + pinch of salt)","2 tbsp ketchup","1 - 3 tsp Sriracha (adjust spiciness to taste)"],"purpose":"Pink Burger Sauce"},{"ingredients":["4 buns or rolls (I like brioche)","8 - 12 lettuce leaves","2 tomatoes"],"purpose":"Burgers (Note 2 for more options)"},{"ingredients":["French fries","Baked potato wedges"],"purpose":"On the side"}]', '[{"description":"Preheat oven to 220°C/450°F (200°F fan).","images":[],"step":1},{"title":"Garlic butter","description":"Place butter, garlic, salt and pepper in a heatproof jug. Microwave to melt butter, then stir.","images":[],"step":2},{"title":"Brush with butter","description":"Brush the mushroom cap with butter (smooth side), then place on a tray gills side up (ie stalk facing up). Brush remaining butter onto the rims and gills, being sure to scrape up all the garlic in the jug.","images":[],"step":3},{"title":"Olive oil","description":"Drizzle with olive oil.","images":[],"step":4},{"description":"Roast 25 minutes, then flip mushrooms. Brush with tay juices, roast a further 10 minutes or until the centre of the mushrooms are tender. {Meanwhile, cook onion, mix Sauce)","images":[],"step":5},{"title":"Top with cheese","description":"Place a slice of cheese on each mushroom, return to oven for 3 minutes just to melt the cheese.","duration":3,"images":[],"step":6},{"title":"Toast buns","description":"Place split buns in the oven at the same time - to lightly toast.","images":[],"step":7},{"description":"Assemble burgers","images":[],"step":8},{"description":"Spread base of bun with a dollop of Pink Sauce. Top with lettuce, then tomato, then mushroom, then onion. Spread lid with a lesser smear of Pink Sauce, then place on burger. Devour!","images":[],"step":9},{"description":"Mix together, use per recipe.","images":[],"step":10},{"description":"Heat oil in a large skillet over high heat. Cook onion for 5 to 7 minutes until tinged with gold and floppy. Season with a pinch of salt and pepper.","duration":6,"images":[],"step":11}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","emergency-recipes","main-dishes","mushroom-recipes","quick-and-easy","sandwiches-and-sliders","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8f047e5cdfeb', 'en', 'US', 'An excellent No Yeast Pizza Dough - quick easy homemade pizza!', 'Recipe video above. Meet your new best friend - a no yeast pizza dough that makes a quick and easy homemade pizza, fresh out of the oven in 20 minutes flat! This pizza crust without yeast is not just a sad substitute for the real deal made with yeast. It''s truly great, yet takes a fraction of the time and effort.Spread with pizza sauce, choose your favourite toppings then bake for a pizza night in!', 'https://www.recipetineats.com/tachyon/2020/05/No-Yeast-Pizza_0-1-2.jpg', 7, 13, 20, 1, '[{"id": "ing_bread", "quantity": {"value": 0.25, "unit": "loaf"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.067, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.01, "unit": "L"}}]', '[{"ingredients":["1 1/3 cups bread flour (or plain / all purpose flour, Note 2)","2 tsp baking powder","3/4 tsp salt","3/4 tsp sugar"],"purpose":"Dry ingredients:"},{"ingredients":["2 tsp olive oil (or any other oil)","1/2 cup water (cold tap water)"],"purpose":"Wet ingredients:"},{"ingredients":["1 tbsp Extra Flour (, for dusting)","2 tsp vegetable oil (optional) (, for brushing crust (or canola or other neutral oil) (Note 3))"],"purpose":"Other"}]', '[{"description":"Preheat oven to 250°C / 480°F (230°C fan) (Note 4.) Place shelf in the top quarter of the oven.","images":[],"step":1},{"description":"Spray pizza pan or baking tray lightly with oil.","images":[],"step":2},{"description":"Prepare pizza sauce and toppings. Keep shredded mozzarella in the fridge (Note 5).","images":[],"step":3},{"description":"Food processor option (40 sec):","images":[],"step":4},{"title":"Blitz","description":"Using the standard S blade, add Dry Ingredients and pulse twice. Add water and olive oil. Blitz on low for 40 seconds - it will come together into a shaggy ball (video 33 sec).","duration":0.6666666666666666,"images":[],"step":5},{"title":"Shape","description":"Sprinkle work surface with half Extra Flour, scrape dough out. Sprinkle with remaining Extra Flour and firmly shape into a ball. Proceed with rolling out steps below.","images":[],"step":6},{"description":"Hand Kneading option (3 min):","images":[],"step":7},{"title":"Mix","description":"Place Dry ingredients in a bowl, mix to combine with a rubber spatula. Add water and olive oil, mix until flour is incorporated as best you can.","images":[],"step":8},{"title":"Knead","description":"Sprinkle work surface with half Extra Flour, dip dough out. Sprinkle with remaining Extra Flour then knead for 3 to 4 minutes until it''s pretty smooth (video 38 sec), using more flour only if needed. Shape into a ball. Proceed with rolling out steps below.","duration":3.5,"images":[],"step":9},{"description":"Rolling out dough:","images":[],"step":10},{"title":"Goal dough texture","description":"Your dough should be soft and elastic, and not stick to your hands. It will not be completely smooth like yeast dough (video 38 sec)(Note 6).","images":[],"step":11},{"description":"Roll out your dough ball into a 30cm/12\" round.","images":[],"step":12},{"title":"Stretch","description":"Transfer to pizza pan, preferably with holes (for crispier base), or a baking tray (Note 7 pizza stone). Use your fingers to pull from the centre to fill the pan to the edge - avoid pinching the edges (to ensure puffy crust!).","images":[],"step":13},{"description":"Top with 1/4 cup pizza sauce and toppings of choice.","images":[],"step":14},{"description":"Brush the crust edge (just exposed edge with no toppings on it) with oil.","images":[],"step":15},{"description":"Bake 12 minutes, until the edges are crispy and golden. Cut and serve immediately!","images":[],"step":16}]', '["gluten"]', '["low_calorie","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["emergency-recipes","good-to-know","pizza-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_06b5e3fcec32', 'en', 'US', 'Emergency Corn Chowder Soup', 'Recipe video above. Emergency corn chowder is a soup recipe that involves little more than popping open cans of corn and USING THE EMPTIED CANS to measure the liquids to add into the soup! Tastes just like your favourite creamy corn chowder - but faster to make!', 'https://www.recipetineats.com/tachyon/2019/09/Emergency-Corn-Chowder__1.jpg', 3, 12, 15, 3, '[{"id": "ing_oil", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_bacon", "quantity": {"value": 0.4, "unit": "pack of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_cream", "quantity": {"value": 1.6, "unit": "carton of 250ml"}}, {"id": "ing_corn", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.417, "unit": "L"}}, {"id": "ing_milk", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_flour", "quantity": {"value": 0.022, "unit": "kg"}}]', '[{"ingredients":["1 tsp oil ( or butter)","2 slices bacon (, streaky!)","2 garlic cloves (, minced)","400g/14oz can creamed corn (1 can)","400g/14oz can corn kernels (, drained (1 can))","1 2/3 cups (400ml) chicken stock ( / broth (1 empty can*))","3/4 cup (200ml) milk (, any fat % (1/2 empty can*))","1 potato (, diced into 1.5 cm/ 1/2\" small cubes)","1/2 tsp each salt and pepper","1 green onion (, finely sliced)"]},{"ingredients":["1/2 cup (125 ml) milk (, any fat % (1/4 empty can*))","1 1/2 tbsp cornflour / corn starch"],"purpose":"Soup thickener:"}]', '[{"description":"Place oil then bacon in pot. Turn stove onto medium high heat then cook until bacon is golden on both sides.","images":[],"step":1},{"description":"Remove bacon and chop once cooled.","images":[],"step":2},{"description":"If there''s loads of excess fat in the pot, drain some.","images":[],"step":3},{"description":"Add garlic and stir for 20 seconds. Add creamed corn, kernels, chicken stock, milk, potato, salt and pepper.","duration":0.3333333333333333,"images":[],"step":4},{"description":"Stir, bring to simmer then adjust to medium. Simmer 5 minutes until potato is just tender.","images":[],"step":5},{"title":"Soup Thickener","description":"Mix together milk and cornflour, then pour into soup.","images":[],"step":6},{"description":"Stir and simmer for 1 minute until it thickens into a creamy soup (see video for thickness).","duration":1,"images":[],"step":7},{"description":"Add more salt if needed.","images":[],"step":8},{"description":"Ladle into bowls, top with green onion and bacon. Devour!","images":[],"step":9}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","emergency-recipes","quick-and-easy","soup-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7282f7fd574c', 'en', 'US', '12 Minute Baked Salmon Fajitas', 'Recipe video above. Here is a big Fajita dinner spread that''s all cooked in the oven at the same time! Caramelised cubes of salmon heavily seasoned with a Fajita spice blend, colourful fajita vegetables and a pile of steamy warm tortillas, just add sliced avocado and make a simple taco sauce while they''re in the oven. I used my new Creamy Jalapeño Sauce but if that''s out of reach or you''re worried about spiciness (it''s got a little zing), either use my Instant Pink Taco Sauce or just plain sour cream.', 'https://www.recipetineats.com/tachyon/2026/05/Tray-bake-salmon-fajitas-7.jpg', 18, 12, 30, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_onion", "quantity": {"value": 5.0, "unit": "pack of 1kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_capsicum", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 5.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_cream", "quantity": {"value": 0.004, "unit": "carton of 250ml"}}, {"id": "ing_pink_taco_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_tortillas", "quantity": {"value": 12.0, "unit": "pack of 8"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}]', '[{"ingredients":["600g / 1.2lb skinless salmon fillets (, cut into 2.5cm/1\" cubes (Note 1))"]},{"ingredients":["1 1/2 tbsp extra virgin olive oil","2 tsp smoked paprika (or regular paprika)","1 tsp EACH garlic, onion, cumin powder","1/2 tsp dried oregano","3/4 tsp cooking salt / kosher salt (halve for cooking salt, double for flakes)","1 tsp (tightly packed) brown sugar (helps the salmon brown!)","1/4 tsp cayenne pepper ((optional), for small spiciness)"],"purpose":"Fajita seasoning:"},{"ingredients":["3 capsicums (1 each red, yellow, green) (, deseeded, cut into 0.75cm / 1/3\" strips)","1 red onion (, cut into 0.75cm / 1/3\"wedges)","1 1/2 tbsp extra virgin olive oil","1 garlic clove (, minced using garlic press or knife)","1/2 tsp cooking salt / kosher salt"],"purpose":"Fajita Vegetables:"},{"ingredients":["Creamy Jalapeno Sauce","Pink Taco Sauce (2 ingredients!)","Sour cream"],"purpose":"CHOOSE a fajita sauce:"},{"ingredients":["12 - 16 taco-size tortillas (, corn or flour (3 to 4 per person, depending on size), wrapped in foil (make 2 parcels))","1 avocado (, sliced)","2 tbsp roughly chopped coriander ((cilantro), optional but recommended)","Lime wedges (, optional)"],"purpose":"Serving:"}]', '[{"description":"Toss Vegetable ingredients on a tray. Toss salmon with Fajita Seasoning, spread on separate tray lined with wrinkled foil. Bake 12 minutes at 240°C/465°F (220°C fan) along with foil wrapped tortillas. Make sauce. Serve!","images":[],"step":1},{"description":"Preheat oven to 240°C/465°F (220°C fan-forced).","images":[],"step":2},{"title":"Crinkled foil trick for baking fish","description":"Lightly scrunch up foil, then gently unfold it so it stays wrinkled. Lots of little pointing bits = good! The wrinkles lift the fish slightly, preventing sticking and soggy undersides – clever Japanese fish-cooking trick (thanks mum!). Place on one side of the tray and fold the edges over the rim to secure. Repeat with another sheet to cover the whole tray.","images":[],"step":3},{"title":"Fajita flavour fish","description":"Mix the Fajita seasoning ingredients in a bowl, it should be like a thin paste. Add fish and toss to coat. Spread out on the foil so the salmon is not touching each other.","images":[],"step":4},{"title":"Toss veg","description":"On a separate large tray, toss capsicum and onion with the oil, garlic and salt. Spread it out in a single layer.","images":[],"step":5},{"description":"Wrap stack of tortillas in foil (make 2 parcels).","images":[],"step":6},{"title":"Bake everything","description":"Put the salmon on the top shelf, vegetables on the middle shelf and tortillas into the oven (I put them on the floor of the oven but don’t do this if your heat element is there, mine comes from the back). Bake 12 minutes, or until the salmon flakes (don''t turn or toss).","images":[],"step":7},{"title":"Sauce","description":"Meanwhile, put the sauce ingredients in a small jug and blitz with stick blender until smooth.","images":[],"step":8},{"title":"Lay everything out","description":"Transfer the salmon and vegetable onto a serving platter, pour all tray juices over. Place warmed tortillas, sauce, avocado, lime wedges and coriander on the side.","images":[],"step":9},{"title":"Making a fajita","description":"Take a warm tortilla. Stuff with a little vegetables, place 2 pieces of salmon on then flake into large chucks. Tuck in avocado, drizzle with sauce, lime juice, sprinkle with coriander, devour!","images":[],"step":10}]', '["fish","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Mexican","Tex-Mex"],"categories":["fajitas","mains","mexican-recipes","one-pot-recipes","other","salmon-recipes","taco-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8b2bfabd26cc', 'en', 'US', 'Creamy Jalapeño Sauce', 'This is a great zippy, spicy, creamy sauce for anything Mexican. It''s not overly spicy, it''s more a fresh zing. Use for tacos, quesadillas, burritos and anything Mexican. Also great for dipping in veggie sticks or corn chips!Makes 1 cup, enough for 16 to 20 tacos, or dipping sauce for 3 - 4 burritos.', 'https://www.recipetineats.com/tachyon/2026/05/Creamy-Jalapeno-Sauce-3.jpg', 10, 0, 10, 1, '[{"id": "ing_pickled_jalape_os", "quantity": {"value": 0.333, "unit": "unit"}}, {"id": "ing_jalape_os", "quantity": {"value": 0.333, "unit": "unit"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.2, "unit": "tub of 250g"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.125, "unit": "jar of 400g"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_lime", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}]', '[{"ingredients":["1/3 cup pickled jalapeños (my default - I like the tanginess and convenience)","3 - 4 tbsp roughly chopped fresh jalapeños (, white membrane and seeds removed (terrific fresh jalapeño flavour))"],"purpose":"CHOOSE ONE Jalapeño (Note 1):"},{"ingredients":["1/3 cup sour cream","1/3 cup whole-egg mayonnaise or kewpie (, or more sour cream (Note 2))","1/3 cup tightly packed coriander/cilantro leaves (just rip a handful of leaves off the stems, some stems is fine)","1 small garlic clove","2 tsp lime juice","1/4 tsp cooking salt / kosher salt (use a little extra if using fresh jalapeños)"],"purpose":"EVERYTHING ELSE:"}]', '[{"title":"Blitz and stir","description":"Put everything EXCEPT the sour cream in a jug. Blitz using a stick blender until it''s completely smooth. Then stir in the sour cream. (Note 3) Taste and add more salt or lime juice, if needed.","images":[],"step":1}]', '["egg","milk"]', '["gluten_free","keto_friendly","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Mexican"],"categories":["fajitas","mexican-recipes","sauces","taco-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_54ef46d2452d', 'en', 'US', 'Instant Pink Taco Sauce', 'This is my most used taco sauce. It’s creamy, cooling, with a little zing - everything I want in a sauce for Mexican food. I use for all types of tacos, plus quesadillas and burritos, though I think it''s especially great with fish tacos. Honestly though, it’s a brilliant all-rounder I use on all sorts of things - wedges, chicken fingers, roasted vegetables. Sriracha isn''t Mexican but it''s a brilliant short cut - spiciness, tang, garlic, salt all in one bottle.Store in the fridge and use within the shelf life of the sour cream. See notes for a non-spicy alternative. Makes 1/2 cup, enough for 12 tacos (4 servings).', 'https://www.recipetineats.com/tachyon/2026/05/Pink-taco-sauce-6.jpg', 5, 0, 5, 4, '[{"id": "ing_sour_cream", "quantity": {"value": 0.3, "unit": "tub of 250g"}}, {"id": "ing_sriracha", "quantity": {"value": 0.05, "unit": "bottle of 400ml"}}]', '[{"ingredients":["1/2 cup sour cream - substitute yogurt for lower calorie (, or add mayonnaise for richness)","4 tsp sriracha (or other hot sauce - start with less and add to taste)"]}]', '[{"description":"Mix ingredients until smooth. If you want a looser drizzling texture, add a tiny bit of water.","images":[],"step":1}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Mexican"],"categories":["fajitas","mexican-recipes","sauces","taco-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c3fb3b400ef1', 'en', 'US', 'Maple Crisp Brie Bites', 'Recipe video above. Think of this as a cheeseboard turned into a canapé! Or, fancy cheese and crackers. :-) Crisp maple-butter crostini topped with brie, prosciutto shards, toasted pecans and thyme, I think this is a fabulous low-cost way to make a platter of something a little special. :-) Excellent to take places, already assembled.', 'https://www.recipetineats.com/tachyon/2025/07/Maple-brie-bites_7.jpg', 15, 20, 35, 30, '[{"id": "ing_bread", "quantity": {"value": 26.0, "unit": "loaf"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_maple_syrup", "quantity": {"value": 0.25, "unit": "bottle of 250ml"}}, {"id": "ing_chilli_flakes", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_prosciutto", "quantity": {"value": 0.24, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.8, "unit": "carton of 250ml"}}, {"id": "ing_pecans", "quantity": {"value": 0.25, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["26 - 30 slices good baguette (sourdough, ciabatta etc) (, sliced 6mm / 0.25\" thick (Note 1))"]},{"ingredients":["50g / 3 1/2 tbsp unsalted butter","1/4 cup maple syrup (, real, not artificial flavoured syrup (sub honey))","1/4 tsp salt flakes (or 1/8 tsp cooking salt / kosher salt)"],"purpose":"Maple butter:"},{"ingredients":["6 slices prosciutto (or similar cured meats (Note 2))","200g / 7 oz triple cream brie","1/4 cup pecans (, lightly toasted, pretty finely chopped, or other nuts)","2 tbsp maple syrup (, for a tiny drizzle on each (optional))","1 tbsp fresh thyme leaves (really try to use this, it''s so good!)"],"purpose":"Topping:"}]', '[{"description":"Simmer maple butter ingredients 20 seconds, brush on crostini, bake 20 min (turn at 15 min mark) at 180C/350F (160C fan), bake prosciutto 15 min at same time. Cool, top with brie, prosciutto shard, pecans, maple drizzle, thyme.","images":[],"step":1},{"description":"Preheat oven to 180°C/350°F (160°C fan-forced). Line 2 large trays with foil then baking paper.","images":[],"step":2},{"title":"Maple butter","description":"Melt the butter in a saucepan over medium heat. Add the maple syrup and salt, stir. Once it comes to a simmer, let it simmer gently for 20 seconds then remove from the stove.","duration":0.3333333333333333,"images":[],"step":3},{"description":"Brush/dab the maple butter on both sides of each piece of bread. Spread on a tray.","images":[],"step":4},{"title":"Prosciutto","description":"Place the prosciutto on the other tray (they can overlap slightly, they shrink so much!).","images":[],"step":5},{"title":"Oven","description":"Put both trays in the oven.","images":[],"step":6},{"title":"15 minute mark","description":"remove the prosciutto, it should be wrinkled and dark red. Transfer to paper towels to drain the fat, it will crisp as it cools. Break into shards (long ones look impressive but any shape works).","images":[],"step":7},{"title":"20 minutes for crostini","description":"turn the crostini after 15 minutes, then return to the oven for another 5 minutes or until crisp on the edges, lightly crisp on the cut face but not crisp all the way through - it will crisp more as it cools. If you take it too far, it can actually become too crisp!","images":[],"step":8},{"title":"Cool","description":"Remove from the oven and let it cool for 10 minutes, or fully cool to room temperature.","duration":10,"images":[],"step":9},{"description":"Place a slice of brie on the crostini. Stick a crispy prosciutto shard in (or place/pile/crumble on top). Sprinkle with a pinch of pecans, drizzle with a tiny amount of maple, and lastly sprinkle with a few thyme leaves.","images":[],"step":10},{"description":"Transfer to platter and serve!","images":[],"step":11}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["snack"],"cuisine":["Western"],"categories":["finger-food","snacks"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_577c3e5a07f2', 'en', 'US', 'Golden Halloumi with Honey and Thyme', 'Recipe video above. It''s impossible to resist devouring golden fried halloumi straight from the pan, when it''s crispy on the surface and gooey inside. And why should we? It''s so great plain! But one day, try it with a drizzle of honey and sprinkle of thyme. It is Outrageously Delicious (caps intentional) and a 2-second-way to dress up halloumi when you''ve got company.Serve with warm pita bread, olives, and a good olive oil for a simple yet thoroughly enjoyable starter.Tip: Handle the slices carefully so they hold together (there is a partial crack in the middle of halloumi blocks).', 'https://www.recipetineats.com/tachyon/2024/09/Haloumi-honey-thyme_6.jpg', 3, 3, 6, 1, '[{"id": "ing_halloumi", "quantity": {"value": 225.0, "unit": "unit"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_maple_syrup", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_thyme", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 2.0, "unit": "pack of 100g"}}]', '[{"ingredients":["225-250g/ 8oz halloumi (block, Cyprus made PDO stamped recommended (Note 1))","2 tbsp olive oil"]},{"ingredients":["1 1/2 tbsp honey ((eyeball it), sub maple syrup)","1/2 tsp fresh thyme leaves and tiny sprigs","2 - 3 pinches chilli flakes ((red pepper flakes), optional)"],"purpose":"Optional finishing:"}]', '[{"description":"Abbreviated recipe:","images":[],"step":1},{"title":"Cut into 1","description":"1.25cm / 0.4 - 0.5\" slices, pat dry. Pan fry in the oil on medium high until golden, serve on pre-warmed plate, with optional finishes.","images":[],"step":2},{"title":"Cut halloumi into 1-1.25 cm thick slices (0.4","description":"0.5\") (see Note 3). Place the slices on a paper towel and pat the surface dry.","images":[],"step":3},{"description":"Warm a serving plate. (Note 4)","images":[],"step":4},{"description":"Heat the oil in a non stick pan over medium high heat.","images":[],"step":5},{"title":"Fry","description":"Carefully place the halloumi in the pan (I use my hands). Cook for 1 1/2 minutes or until the underside is golden. Shuffle if needed so they cook evenly.","images":[],"step":6},{"description":"Turn gently (I use a spatula + butter knife to guide) and cook the other side for 1 - 1/2 minutes until golden.","images":[],"step":7},{"description":"Transfer onto the serving plate.","images":[],"step":8},{"title":"Optional finishes","description":"Working quickly, drizzle with honey, sprinkle with thyme and chilli flakes. I do full honey coverage for some slices, and for others just a drizzle.","images":[],"step":9},{"description":"Serve immediately, quick, before the halloumi goes squeaky! :) Though actually, the squeak doesn’t bother me but it''s at its prime straight out of the pan when the surface is still crisp and the inside is soft. (Note: Honey on the plate is ideal for bread mopping)","images":[],"step":10}]', '[]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["snack"],"cuisine":["Greek","Western"],"categories":["finger-food","quick-and-easy","snacks"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3b17e816fe02', 'en', 'US', 'Crispy Salt & Pepper Squid', 'Recipe video above. It only took us 3 years to crack the ultimate, truly crispy Salt and Pepper Squid! Hand on heart, this is crispier than any squid I''ve had in a restaurant, ever. The fry batter is light, super crunchy and not greasy at all. In fact, it''s so crispy it stays crispy even when it''s stone cold!After eliminating rice flour, potato flour and tapioca, we found the perfect ratio of flour to cornflour (cornstarch) that fries up crunchy in mere minutes, before the squid can overcook. But the final key was refrigerating the batter for 30 minutes. This allowed the gluten to develop so the batter clings to the slippery squid better and doesn''t fry up chewy or greasy.', 'https://www.recipetineats.com/tachyon/2024/02/Salt-and-pepper-squid-in-a-bowl.jpg', 15, 0, 15, 3, '[{"id": "ing_whole_baby_squid", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_squid_tubes", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.25, "unit": "pack of 400g"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.017, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 0.167, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 3.0, "unit": "bottle"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.188, "unit": "jar of 400g"}}, {"id": "ing_garlic", "quantity": {"value": 0.833, "unit": "pack of 3 heads"}}]', '[{"ingredients":["700 g / 1.4 lb medium whole baby squid","500 g / 1 lb squid tubes (, already cleaned)"],"purpose":"Squid – choose (Note 1):"},{"ingredients":["2/3 cup cornflour / cornstarch","1/3 cup plain / all-purpose flour","1/2 tsp baking powder","1/2 tsp cooking / kosher salt","1/4 tsp white pepper powder","2/3 cup cold tap water"],"purpose":"Batter (Note 2):"},{"ingredients":["3 – 4 cups vegetable or canola oil (~4cm / 1.5\" depth in a pot)","Cooking / kosher salt ( - just a pinch!)","White pepper powder"],"purpose":"Cooking / seasoning:"},{"ingredients":["1/2 cup whole egg mayonnaise ( or kewpie)","1/2 tsp finely grated garlic"],"purpose":"Easy aioli (garlic mayonnaise):"}]', '[{"description":"Preparing squid:","images":[],"step":1},{"description":"Cut one side of the squid tube to lay it out in one flat piece. Pat both sides dry with a paper towel.","images":[],"step":2},{"description":"Lightly score the inside with a small sharp knife in 1.5 cm / 0.6\" diamonds (don''t cut all the way through). (Note 3)","images":[],"step":3},{"description":"Cut the squid into pieces 5 x 2cm (2 x 1\") rectangles (approximately).","images":[],"step":4},{"description":"Mix the ingredients together in a bowl and set aside for at least 20 minutes (up to 24 hours).","images":[],"step":5},{"title":"Batter","description":"Whisk the flour, cornflour, baking powder and salt in a bowl. Then whisk in water until smooth. Refrigerate for 30 minutes. (Note 4)","duration":30,"images":[],"step":6},{"title":"Heat oil","description":"Fill small heavy based pot or large saucepan with 4cm / 1.5\" of oil. Heat to 160°C/320°F on medium high heat. (I use a Thermapen to check the temp)","images":[],"step":7},{"description":"Give the batter a quick whisk then add all the squid in a toss to coat. (Including tentacles if using baby squid - it''s the crunchiest!)","images":[],"step":8},{"title":"Batter","description":"Cook the squid in 3 batches. Pick up some squid and let the excess batter to drip off. Careful place in the oil. Use chopsticks to seperate the pieces that stick together.","images":[],"step":9},{"description":"Fry baby squid for 2 minutes or the regular squid tubes for 3 minutes until light golden. Use a spider or slotted spoon to remove the squid on a paper towel lined tray.","duration":2,"images":[],"step":10},{"title":"Repeat","description":"Fry remaining squid, making sure the oil comes back to temperature before cooking batches 2 and 3.","images":[],"step":11},{"title":"Fry 2","description":"crisp it!","images":[],"step":12},{"title":"Increase oil temp","description":"Increase the stove to high and bring the the oil up to 200°C/390°F.","images":[],"step":13},{"title":"Bowl","description":"Line a large mixing bowl with double layer of paper towels.","images":[],"step":14},{"title":"Fry","description":"Place half of the squid in the oil (it''s ok to crowd the pot). Cook for 1 1/2 minutes, until it becomes deep golden and crispy. Remove into the bowl. Bring the oil back up to 200°C/390°F then fry the remaining squid.","images":[],"step":15},{"title":"Season","description":"Remove paper towel. Taste first then sprinkle lightly with as much salt and pepper as you want (the batter has salt in it already). Toss well.","images":[],"step":16},{"description":"Serve:","images":[],"step":17},{"description":"Pour into a serving bowl and serve with aioli! This batter is so good, it will stay crispy even once the squid has gone cold.","images":[],"step":18}]', '["egg","gluten","shellfish"]', '[]', '{"mealType":["snack","dinner"],"cuisine":["Western"],"categories":["deep-fried-recipes","finger-food","iconic-dishes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9cd69a34b583', 'en', 'US', 'Jalapeño poppers', 'Recipe video above. There''s no one way to make Jalapeño poppers. The stuffing can be herby, or bacony, they can be crumbed and fried, or wrapped in bacon and baked (that''s a LOT of bacon!).Mine have a bacon-cheddar-cream cheese filling, then I top with shredded cheese to act as a glue for crunchy breadcrumbs. I like to pre-toast the breadcrumbs so they are evenly golden. It takes 3 minutes and so worth it - rather than serving them with a white crumb with splotchy brown patches.Serve at your next gathering and watch them disappear in a flash!', 'https://www.recipetineats.com/tachyon/2024/02/Jalapeno-poppers_3.jpg', 30, 25, 55, 24, '[{"id": "ing_jalape_os", "quantity": {"value": 12.0, "unit": "unit"}}, {"id": "ing_bacon", "quantity": {"value": 0.75, "unit": "pack of 200g"}}, {"id": "ing_cream_cheese", "quantity": {"value": 250.0, "unit": "block of 250g"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.5, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 0.125, "unit": "loaf"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_chives", "quantity": {"value": 0.03, "unit": "kg"}}]', '[{"ingredients":["12 jalapeños (, about 7.5cm / 3\" long, cut in half and deseeded)"]},{"ingredients":["150g / 5oz streaky bacon (Note 2)","250g/ 8 oz cream cheese (I use Philadelphia)","1 1/2 cups (150g) sharp cheddar cheese, ( shredded (or regular cheddar, tasty, Monterey Jack, colby))","1/2 cup green onion (, finely sliced (2 big stems))","2 garlic cloves (, finely minced)","1/4 tsp cooking/kosher salt","1/8 tsp black pepper"],"purpose":"Filling:"},{"ingredients":["2/3 cup panko breadcrumbs (Note 3)","1/8 tsp salt","1 - 2 tbsp olive oil"],"purpose":"Crunchy topping:"},{"ingredients":["1 cup (100 g) sharp cheddar cheese, (shredded (or other cheese listed above))","2 tbsp chives (, finely sliced (optional garnish))"],"purpose":"Topping"}]', '[{"title":"Crumbled bacon","description":"Place bacon in a single layer in a large unheated non-stick pan (no oil, Note 2). Turn the stove onto medium high. As the pan heats up, the fat will start to melt. Once sizzling, cook each side for 2 minutes or until golden. Remove onto paper towels to drain the fat (leave fat in the pan). Repeat with remaining bacon. Once cool and crisp, finely chop into crumbs.","duration":2,"images":[],"step":1},{"title":"Toast breadcrumbs","description":"Top up the bacon fat with the oil so you have 2 tablespoons in total. Cool the pan slightly then return to medium heat. Add the breadcrumbs and salt. Toast, stirring regularly, until evenly golden - about 3 minutes. Transfer into a bowl and set aside.","images":[],"step":2},{"title":"Filling","description":"Put 3/4 of the bacon in a bowl (reserve the rest for topping). Add remaining ingredients then stir with a wooden spoon until combined.","images":[],"step":3},{"description":"Preheat oven to 200°C/375°F (180°C fan). Line a tray with foil then place a rack on it (to keep jalapeños level).","images":[],"step":4},{"description":"Stuff jalapeños with the filling, slightly above the rim (it sinks a bit) but not too high else there will be overflow. Place on the rack so the surface is level. Top with the shredded cheese, press down to flatten. Spoon over panko.","images":[],"step":5},{"description":"Bake 15 minutes or until the cheese is melted and jalapeño is softened but still holding its shape (not saggy).","images":[],"step":6},{"description":"Transfer to serving platter, sprinkle with reserved bacon and chives. Serve hot! No dipping sauce needed.","images":[],"step":7}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["snack"],"cuisine":["American","Western"],"categories":["finger-food","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_70ba6e0b6fb5', 'en', 'US', 'Crispy rice', 'Recipe video above. Crispy rice is just rice that''s packed in a pan, cut then pan fried until ultra golden and crispy. They make a great snack just as they are - you will DEVOUR a whole pile - or a base to make irresistible appetisers. Think - modern Asian canapés topped with spicy tuna (Nobu style!), tuna poke, egg or chicken salad sandwich filling, ceviche or salmon mousse!', 'https://www.recipetineats.com/tachyon/2023/06/Crispy-rice-cakes_3.jpg', 10, 30, 40, 15, '[{"id": "ing_rice", "quantity": {"value": 150.0, "unit": "pack"}}, {"id": "ing_water", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 50.0, "unit": "bottle"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1 cup sushi rice (Note 1)","1 1/2 cups water","1/3 cup canola oil (vegetable, peanut or other neutral oil)","3/4 tsp cooking / kosher salt (, for sprinkling rice cakes (Note 2))"]},{"ingredients":["1 tbsp rice vinegar (Note 3)","1 tsp caster sugar (Note 3)"],"purpose":"Sushi seasoning:"}]', '[{"description":"Cook rice, rest, pour over seasoning, fluff. Press firmly into 20cm/8\" lined pan, weigh down. Cool, fridge overnight (min 6 hrs). Cut into 15 rectangles, pan fry 4 min each side, sprinkle with salt.","images":[],"step":1},{"title":"Sushi seasoning","description":"Mix together until sugar dissolves.","images":[],"step":2},{"title":"Cook rice (Note 4)","description":"Place rice and water in a small pot (no lid) over medium high heat. Once it''s bubbling on the edges and the middle is rippling, put the lid on and turn down to medium low (or low for strong stoves). Cook for 13 minutes or until water is absorbed.","duration":13,"images":[],"step":3},{"title":"Rest","description":"Remove from heat then rest for 10 minutes with the lid still on.","duration":10,"images":[],"step":4},{"title":"Season","description":"Remove lid. Pour over sushi seasoning. Fluff rice with rubber spatula.","images":[],"step":5},{"description":"Press, cool, cut:","images":[],"step":6},{"title":"Press","description":"Place a sheet of baking/parchment paper on a 20cm/8\" square pan. Scrape hot rice into the pan and spread evenly. Cover with another piece of paper and press in very firmly.","images":[],"step":7},{"title":"Weigh down (recommended, Note 5)","description":"For best results, place something flat on top (2nd same size pan is ideal) then weigh down with 5 x 400g/14oz cans.","images":[],"step":8},{"title":"Cool","description":"Fully cool, cover with cling wrap, then refrigerate overnight (min 6 hours). Speedy option: Fridge uncovered until fully cool, cover, freeze 1 hour, fridge 1 hour.","images":[],"step":9},{"title":"Cut","description":"Lift rice out using paper overhang. Wet the knife blade (neater cuts). Cut rice into 15 rectangles (5 strips, then each into 3).","images":[],"step":10},{"description":"Cooking:","images":[],"step":11},{"title":"Pan fry","description":"Heat about 1/4 cup of the oil in a large non-stick pan over medium high. Place in half the rice cakes - they should sizzle gently. Lower heat to medium. Cook for 4 minutes until really golden and crispy. Turn and cook the other side for 4 minutes.","duration":4,"images":[],"step":12},{"title":"Salt","description":"Remove onto a paper towels lined plate. Sprinkle each side with salt while hot.","images":[],"step":13},{"title":"Keep cooking","description":"Add remaining oil and cook remaining rice cakes.","images":[],"step":14},{"description":"Serve as snack (you won''t be able to stop!) or a base for canapés.","images":[],"step":15},{"title":"Topping suggestions","description":"Spicy tuna (Nobu copycat), tuna poke, salmon mousse, crostini toppings.","images":[],"step":16}]', '["peanuts"]', '["gluten_free","keto_friendly","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Asian"],"categories":["finger-food","modern-asian","rice-recipes","rice-side-dishes","snacks"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b66807c4ced1', 'en', 'US', 'Blini with smoked salmon', 'Recipe video above. Blini isn''t blini unless it''s made with yeast and buckwheat flour which adds a lovely nutty flavour to these mini pancakes! But if you are desperate and don''t have yeast, see Note 8 for how to make blini without yeast. :)Top with smoked salmon and dill crème fraîche (or sour cream) for an elegant, timeless canapé that never fails to impress. (Makes 35 though depends on number of test blinis, there are usually casualties)', 'https://www.recipetineats.com/tachyon/2022/12/Blini-with-smoked-salmom-close-up.jpg', 20, 20, 40, 35, '[{"id": "ing_water", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_yeast", "quantity": {"value": 0.5, "unit": "pack of 5 sachets"}}, {"id": "ing_sugar", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_canola_spray", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_cream_cheese", "quantity": {"value": 125.0, "unit": "block of 250g"}}, {"id": "ing_cr_me_fra_che", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_dill", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_black_pepper", "quantity": {"value": 1.0, "unit": "jar of 50g"}}, {"id": "ing_salmon_fillets", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_dill", "quantity": {"value": 0.01, "unit": "kg"}}]', '[{"ingredients":["3 tbsp warm water","1/2 tsp dry yeast (Note 1 re: instant yeast)","3/4 tsp white sugar","1/3 cup plain flour (all-purpose flour)","1/3 cup buckwheat flour (Note 2)","1/8 tsp cooking/kosher salt","1/3 cup milk (, full-fat, warm)","30g / 2 tbsp unsalted butter (, melted and cooled)","1 large egg (at room temperature, lightly beaten (Note 3))","Canola spray (, for cooking)"],"purpose":"Blini:"},{"ingredients":["125 g / 4 oz cream cheese (, softened)","3/4 cup crème fraîche (or sour cream) (Note 4)","2 tsp fresh dill (, finely chopped (sub chives, parsley))","1 tsp lemon juice (or apple cider vinegar)","1/4 tsp cooking/kosher salt","1 pinch white pepper (sub black pepper)"],"purpose":"Dill crème fraiche:"},{"ingredients":["300 g / 10 oz smoked salmon (or trout) slices (Note 5)","Extra fresh dill (, for garnish)"],"purpose":"Topping:"}]', '[{"title":"Foamy yeast 10 min","description":"Warm a small bowl by running under warm water, then wipe dry. (Note 6). Mix the warm water, yeast and 1/4 tsp of the sugar in the bowl until yeast is mostly dissolved (some small floating lumps ok). Cover with cling wrap and leave in a warm place for 10 minutes until the surface is foamy.","duration":10,"images":[],"step":1},{"title":"Mix dry","description":"With a wooden spoon, mix both flours, salt and the rest of the sugar in a separate medium bowl.","images":[],"step":2},{"title":"Add wet","description":"Stir in milk, butter, egg and all the foamy yeast mixture. Mix well until incorporated. It will be runny like pancake batter.","images":[],"step":3},{"title":"Rise 1 1/2 hours","description":"Cover with cling wrap and set in another larger bowl filled with 3cm/1\" of warm water (to create a cosy, warm environment for batter rising). Let the batter rise in a warm place for 1 1/2 to 2 hours until it doubles in volume and has bubbles breaking the surface.","images":[],"step":4},{"description":"Cook blini:","images":[],"step":5},{"title":"Piping bag","description":"Stir batter before using. Transfer to a piping bag fitted with 4mm (1/6\") round piping tip (or snip a 6 mm / 1/4\" hole in the end). Tie off the piping bag end with a rubber band (loosely, as batter keeps expanding).","images":[],"step":6},{"title":"Spray pan with oil","description":"Place a large non stick pan over medium high heat. Once hot, remove pan from stove, spray lightly with oil then return to stove (⚠️Note 7)","images":[],"step":7},{"title":"Cook","description":"Pipe 2.5cm / 1\" rounds that spread to 4cm / 1.7\" in the pan. Cook the first side 45 seconds to 1 minute or until it has golden spots in the middle and has the signature gold Blini \"ring\" around it. Flip and cook the other side for 30 seconds.","duration":0.5,"images":[],"step":8},{"title":"Cool","description":"Transfer to a cooling rack. Wipe pan briefly with a paper towel, spray with oil and heat again. Continue cooking blinis, taking care to keep the pan at the right temperature.","images":[],"step":9},{"description":"Assembling blini:","images":[],"step":10},{"description":"Cool blini before assembling.","images":[],"step":11},{"title":"Dill crème fraîche","description":"Mix ingredients until smooth. Refrigerate until required.","images":[],"step":12},{"title":"Smoked salmon","description":"Cut into 4 x 5 cm pieces (1.5 x 2\")","images":[],"step":13},{"title":"Assemble","description":"Spread 3/4 teaspoon of dill crème fraîche on a blini. Coil on a piece of salmon, top with dill. Transfer to a larger platter. Use lemon wedges and extra dill as platter garnishes, if desired. Serve with bubbles and wine!","images":[],"step":14}]', '["egg","fish","gluten","milk"]', '[]', '{"mealType":["snack"],"cuisine":["European","Western"],"categories":["finger-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2511a0d5cb0f', 'en', 'US', 'Crostini - toasted bread for toppings and dunking', '“Crostini” means “little crusts” (ie. “little toasts”) in Italian and that’s exactly what they are: Thin, small slices of bread, brushed with olive oil, sprinkled with salt, toasted until crisp and then piled with toppings or used for for dunking.Rubbing with garlic is optional - but it really does add that special touch!See in post for ideas for toppings and other dishes ideal for serving with crostini.', 'https://www.recipetineats.com/tachyon/2021/09/Crostini-for-Acqua-Pazza.jpg', 5, 10, 15, 2, '[{"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}]', '[{"ingredients":["1 crusty baguette (, thin)","salt","1 - 3 tbsp extra virgin olive oil (depends how many crostini you''re making)"]},{"ingredients":["1 garlic clove (, halved (for rubbing, optional))"],"purpose":"Optional garlic flavour (recommended!)"}]', '[{"title":"Small crostini (for canapes)","description":"slice bread 0.5cm / 1/4-inch thick on the diagonal.","images":[],"step":1},{"description":"Large crostini (for serving on the side of dishes) - Cut on a diagonal, 1cm / 1/3\" thick.","images":[],"step":2},{"description":"Preheat oven (all types):- Small crostini to 160°C/325°F- Large crostini to 180°C/350°F","images":[],"step":3},{"description":"Brush olive oil lightly on bread, sprinkle with a bit of salt. Flip and repeat. Bake 10 minutes, turning halfway, or until fully crispy.","images":[],"step":4},{"description":"Rub bread lightly on one side with cut face of garlic. Use warm if serving with a dish, or cool if piling on toppings.","images":[],"step":5}]', '[]', '["gluten_free","high_protein","vegan","vegetarian"]', '{"mealType":["snack"],"cuisine":[],"categories":["finger-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_768f9c6e63f5', 'en', 'US', 'Crostini - 8 delicious ways!', 'Recipe video above. 8 fabulous Crostini topping ideas, with an emphasis festive holiday vibes! These irresistible party bites have it all: Colour, Christmas flavours, are easy to make in large batches, and are economical.The Crostini bread can be made days in advance; they stays crispy for ages!Quantity - specific for each Topping in ingredients list.', 'https://www.recipetineats.com/tachyon/2019/10/Holiday-Crostini-Topping-Ideas.jpg', 20, 10, 30, 16, '[{"id": "ing_bread", "quantity": {"value": 1.5, "unit": "loaf"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_baby_bocconcini_cut_into_8", "quantity": {"value": 350.0, "unit": "unit"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.6, "unit": "punnet of 250g"}}, {"id": "ing_basil", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_balsamic_glaze", "quantity": {"value": 60.0, "unit": "bottle"}}, {"id": "ing_cream_cheese", "quantity": {"value": 250.0, "unit": "block of 250g"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_dill", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_salmon_fillets", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_baby_capers", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_dill", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_ricotta", "quantity": {"value": 1.0, "unit": "tub of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_shrimp", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_avocado", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_cheese", "quantity": {"value": 250.0, "unit": "block of 250g"}}, {"id": "ing_strawberries", "quantity": {"value": 14.0, "unit": "punnet of 250g"}}, {"id": "ing_honey", "quantity": {"value": 0.06, "unit": "jar of 500g"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_beef", "quantity": {"value": 0.18, "unit": "kg"}}, {"id": "ing_baby_rocket_arugula", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_cranberries", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_pitted_black_olives", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_pitted_green_olives", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_almonds", "quantity": {"value": 0.15, "unit": "pack of 250g"}}, {"id": "ing_frozen_peas", "quantity": {"value": 150.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_parmesan", "quantity": {"value": 0.15, "unit": "pack of 200g"}}, {"id": "ing_mint", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.15, "unit": "pack of 100g"}}]', '[{"ingredients":["30 slices artisan type baguette or French stick (, cut 0.5cm / 1/4-inch thick on the diagonal (Note 1))","3 tbsp extra virgin olive oil","salt","1 garlic clove (, cut in half)"],"purpose":"Crostini bread:"},{"ingredients":["350g/ 12 oz baby bocconcini (small ones), cut into 8 (Note 2)","400g/ 14 oz cherry tomatoes (, cut into 8 (Note 3))","1/2 cup (packed) basil leaves (, finely sliced)","3 tbsp extra virgin olive oil","3/4 tsp salt and pepper (, each)","4 tbsp balsamic glaze (, store bought or homemade)"],"purpose":"Caprese (makes 30):"},{"ingredients":["250g/ 8oz spreadable cream cheese (or creme fraiche, Note 4)","2 tsp lemon zest","2 tbsp lemon juice","1 tsp salt and pepper (, each)","1/3 cup dill (, finely chopped)","500g/ 1 lb smoked salmon (, cut into 2cm / 4/5\" x 7.5cm / 3\" strips)","75g/ 2.5oz baby capers","30 dill sprigs (, for garnish)"],"purpose":"Smoked Salmon with Dill Cream Cheese (makes 30):"},{"ingredients":["250g/ 8 oz ricotta (, or similar (smooth easiest to spread))","500g/ 1 lb antipasto mix - olives ((pitted), peppers, sun dried tomato, artichokes)"],"purpose":"Mediterranean (makes 30):"},{"ingredients":["500g/1 lb prawns/shrimp (, peeled and deveined)","2 garlic cloves (, minced)","1/2 tsp each salt and pepper","3 tbsp olive oil (, separated)","2 eschallots/French onions (, finely chopped)","1/4 cup coriander/cilantro leaves (, finely chopped)","2 tbsp lime juice","2 avocados (, halved and seed removed)"],"purpose":"Garlic Prawns/Shrimp and Avocado (makes 30):"},{"ingredients":["160g / 5.5 oz goats cheese (, softened (or cream cheese, Danish feta or a good smooth ricotta))","14 - 16 ripe strawberries (, sliced 3mm / 1/8\" thick)","2 tbsp honey","2 tsp fresh thyme leaves"],"purpose":"Strawberry with Goats Cheese and Honey – new! (makes 16)"},{"ingredients":["2 tsp Hot English Mustard (or more, if you’re brave!)","160g / 5.5 oz goats cheese (, softened (or cream cheese, Danish feta or a good smooth ricotta))","180g / 6oz rare roast beef (, shaved or finely sliced)","16 baby rocket/arugula leaf (, for garnish)"],"purpose":"Rare roast beef with Hot English Mustard – new! (makes 16)"},{"ingredients":["1/2 cup parsley (, finely chopped)","1/2 cup dried cranberries (, separated (they tend to stick together))","1/4 cup pitted black olives (, finely chopped)","1/4 cup pitted green olives (, finely chopped)","1/4 cup almonds (preferably blanched) (, finely chopped)","2 tbsp extra virgin olive oil"],"purpose":"Holiday Tapenade – new! (makes 16)"},{"ingredients":["150g / 5oz frozen peas","1/2 small garlic clove (, minced)","2 tbsp parmesan (, finely grated)","1/4 tsp each salt and pepper","250g / 8oz cooked peeled prawns/shrimp (500g/1lb cooked whole, Note 5)","2 tbsp mint leaves (, finely chopped)","2 tsp lemon juice","extra virgin olive oil (, for drizzling)","1 tbsp parsley (, finely chopped)","1 tbsp large red chilli (cayenne peppers) (, deseeded and finely chopped)"],"purpose":"Chilli and Mint Prawns on Parmesan Pea Puree – new! (makes 16)"}]', '[{"description":"Preheat oven to 160°C / 320°F (all oven types).","images":[],"step":1},{"description":"Brush bread with oil, sprinkle with salt, flip and repeat. Bake 5 minutes.","images":[],"step":2},{"description":"Remove, then rub the surface lightly with garlic. Bake for a further 5 minutes until completely crispy, then remove and leave to cool fully before adding toppings.","images":[],"step":3},{"description":"Place all ingredients except balsamic glaze in a bowl and gently toss. Taste and add more salt & pepper if desired. Spoon onto crostini, then drizzle with balsamic glaze. Done!","images":[],"step":4},{"description":"Smoked Salmon with Dill Cream Cheese:","images":[],"step":5},{"description":"Mix cream cheese, lemon zest, lemon juice, dill, salt and pepper. Spread on crostini, then fold salmon pieces on top. Top with 3 capers and sprig of dill each. Serve!","images":[],"step":6},{"description":"Finely chop antipasto mix. Smear crostini with ricotta, pile on antipasto. Ready!","images":[],"step":7},{"description":"Garlic Prawn/Shrimp and Avocado:","images":[],"step":8},{"title":"Cook prawns","description":"Toss prawns with 1 tbsp oil, garlic, salt and pepper. Preheat large skillet over high heat with 1 tbsp olive oil. Add half the prawns and sauté until just cooked. Remove, then repeat with remaining prawns.","images":[],"step":9},{"description":"Cool, then chop into 0.75cm / 1/3\" pieces and transfer to bowl. Add 1 tbsp olive oil, eschallots, coriander and lime. Toss, then add more salt and pepper to taste.","images":[],"step":10},{"title":"Assemble","description":"Smear crostini with avocado, then spoon on shrimp. Serve! No, wait - Eat one yourself, then serve. Because they''ll be gone before you can even put the plate down, trust me! 😂","images":[],"step":11},{"description":"Strawberry with Goats Cheese and Honey:","images":[],"step":12},{"description":"Spread crostini with goats cheese. Layer strawberry slices. Drizzle with honey just before serving and sprinkle with thyme leaves.","images":[],"step":13},{"description":"Rare Roast Beef with Hot English Mustard:","images":[],"step":14},{"description":"Spread crostini with as much English Mustard as you dare(!), then cream cheese. Drape with a slice of beef, top with sprig of rocket.","images":[],"step":15},{"description":"\"Holiday Tapenade\":","images":[],"step":16},{"description":"Mix chopped tapenade ingredients in a small bowl. Set aside for at least 30 minutes to let the flavours meld, then taste and add salt if required.","images":[],"step":17},{"description":"Spread crostini with goats cheese. Pile on tapenade. Serve!","images":[],"step":18},{"description":"Chilli and Mint Prawns on Parmesan Pea Puree:","images":[],"step":19},{"title":"Pea puree","description":"Boil peas per packet directions until soft, then drain well. Transfer to small bowl with high sides. Add garlic, parmesan, olive oil, salt and pepper. Blitz with handheld blender stick until smooth. Stir through mint and lemon juice. Set aside to fully cool.","images":[],"step":20},{"title":"Prawns: Peel then chop meat into 0.75","description":"1 cm pieces.","images":[],"step":21},{"title":"Assemble","description":"Smear crostini with pea puree. Pile on prawn, drizzle with olive oil, sprinkle with parsley and chilli.","images":[],"step":22}]', '["fish","milk","mustard","shellfish"]', '["gluten_free"]', '{"mealType":["snack"],"cuisine":["Western"],"categories":["finger-food","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5a591744a79c', 'en', 'US', 'Homemade Sausage Rolls', 'Recipe video above. "The secret is the bacon..." It really takes this sausage roll to another level! Also, sautéing the onion and celery before mixing into the filling makes it sweet and more moist than the usual, and using panko instead of normal breadcrumbs also contributes to making the filling of this sausage roll so moist.The addition of fennel adds an extra burst of flavour but it''s optional. Pork and fennel are great mates and though most everyday suburban bakeries won''t use it, you''ll find better bakeries use it (like Bourke St Bakery). If you''re wary, drop it to 1/2 teaspoon. Or just skip it!', 'https://www.recipetineats.com/tachyon/2016/07/Sausage-Rolls-recipe_5.jpg', 20, 30, 50, 20, '[{"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_bacon", "quantity": {"value": 0.709, "unit": "pack of 200g"}}, {"id": "ing_fennel_seeds", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_pork_mince", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 0.141, "unit": "loaf"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_sheet_puff_pastry", "quantity": {"value": 2.5, "unit": "pack"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1/2 tbsp olive oil","2 cloves garlic (, minced)","1 brown onion (, small, finely chopped)","1 celery stalk (, finely chopped)","5 oz / 150g bacon (, finely minced (streaky and fatty, not the lean stuff!))","2 tsp fennel seeds (, toasted (optional) (Note 1))","1 lb / 500g pork mince (ground pork) (not lean)","3/4 cup / 40g panko breadcrumbs (Note 2)","1 egg","1/2 tsp salt","Black pepper"],"purpose":"Filling"},{"ingredients":["2 1/2 sheets puff pastry (, thawed then each cut into half (Note 3))","1 egg (, lightly whisked)","Ketchup / tomato sauce"],"purpose":"Baking & Serving"}]', '[{"description":"Heat oil in a non stick fry pan over medium high heat. Sauté garlic, onion & celery for 2 minutes, then add bacon.","duration":2,"images":[],"step":1},{"description":"Cook for a further 2 minutes (don''t make bacon golden) then transfer to bowl and allow to cool for 10 minutes.","duration":10,"images":[],"step":2},{"description":"Add remaining Filling ingredients into the bowl. Use your hands to mix well.","images":[],"step":3},{"description":"Lay out a rectangle of pastry, long edge closest to you. Brush egg along one long edge.","images":[],"step":4},{"description":"Get 1/5 th of the filling and shape into a long log shape down the middle of the pastry. Ensure the meat is tight and compact, without gaps.","images":[],"step":5},{"description":"Brush edge of pastry with egg. Then roll up, finishing with the seam side down.Roll up, sealing on the edge with egg wash on it .","images":[],"step":6},{"description":"If you have time/patience, refrigerate for 1 hour (makes it easier/neater to cut)","images":[],"step":7},{"description":"To Cook","images":[],"step":8},{"description":"Preheat oven to 350F/180C.","images":[],"step":9},{"description":"Cut each log into four equal lengths, or just two if you want full size sausage rolls. Brush with egg.","images":[],"step":10},{"description":"Place on 2 baking trays lined with baking paper (or sprayed with oil). Bake for 30 - 35 minutes in total, swapping tray shelves at 20 minutes, or until the pastry is deep golden brown. (Note: The filling will still look pink because of the bacon, but it''s easy to tell from texture that it''s cooked)","duration":32.5,"images":[],"step":11},{"description":"Cool slightly on trays. Serve hot or warm with tomato sauce or ketchup!","images":[],"step":12}]', '["egg"]', '["gluten_free","low_calorie"]', '{"mealType":["snack"],"cuisine":["Australian","British","Western"],"categories":["finger-food","pork-recipes","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2a3edb751273', 'en', 'US', 'Salami Cream Cheese Roll', 'A great appetiser to make for a crowd - no fiddly assembly, make ahead and easy to transport. Cream cheese and salty salami is a stellar combination. Add whatever you want into the filling - capers add a nice tang to an otherwise rich filling.', 'https://www.recipetineats.com/tachyon/2017/02/Salami-Rolls-17.jpg', 10, 0, 10, 25, '[{"id": "ing_cream_cheese", "quantity": {"value": 250.0, "unit": "block of 250g"}}, {"id": "ing_salami", "quantity": {"value": 0.18, "unit": "kg"}}, {"id": "ing_baby_capers", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_crackers", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["250 g / 8 oz cream cheese (I use Philadelphia, 1 block)","180 g/ 6 oz sliced large salami (Note 1)","1/4 cup baby capers (, drained)","2 tbsp finely chopped parsley or basil (or other herb of choice, or omit)","Crackers (, to serve (I use Jatz))"]}]', '[{"description":"Place the cold cream cheese on a large piece of cling wrap.","images":[],"step":1},{"description":"Cover with another piece of cling wrap.","images":[],"step":2},{"description":"Use a rolling pin to roll it into a rectangle about 32cm / 13\" x 23 cm / 9\". (Note 2)","images":[],"step":3},{"description":"Peel off the cling wrap. Cover with salami, slightly overlapping.","images":[],"step":4},{"description":"Cover salami with a new piece of cling wrap. Press down then turn over so the cream cheese side is up.","images":[],"step":5},{"description":"Peel cling wrap off to expose cream cheese. Sprinkle with capers and parsley.","images":[],"step":6},{"description":"Starting from the long edge, roll up, removing cling wrap as you go (see video below). Roll firmly to avoid air bubbles.","images":[],"step":7},{"description":"Once rolled, wrap with the same cling wrap, twist the ends and refrigerate for 4 hours+.","images":[],"step":8},{"description":"Unwrap from cling wrap. Slice into rounds. Serve with crackers.","images":[],"step":9}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["snack"],"cuisine":[],"categories":["finger-food","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c5dd0810c928', 'en', 'US', 'Spinach Ricotta Rolls', 'A juicy spinach ricotta filling encased with buttery, flaky puff pastry. Great finger food or to pop into lunch boxes, thought they are definitely best served warm! Refer to the notes for make ahead instructions and the recipe video below. Some people like to serve this with tomato sauce.', 'https://www.recipetineats.com/tachyon/2017/01/Spinach-Ricotta-Rolls-2.jpg', 10, 25, 35, 24, '[{"id": "ing_spinach", "quantity": {"value": 250.0, "unit": "bag of 250g"}}, {"id": "ing_ricotta", "quantity": {"value": 1.6, "unit": "tub of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_pinch_nutmeg", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_sheet_puff_pastry", "quantity": {"value": 3.0, "unit": "pack"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["250 g / 8 oz frozen chopped spinach (, thawed (Note 1))","400 g / 13 oz firm ricotta (Note 2)","¾ cup grated parmesan","1 ½ cups shredded cheese (cheddar, tasty, Monterey Jack, Gruyere, Pepper Jack)","1 egg","1 large garlic clove (, minced)","Pinch of nutmeg (fresh grated or powder)","¼ - ½ tsp salt","Black pepper"],"purpose":"Filling"},{"ingredients":["3 sheets puff pastry (Note 3)","1 egg (, beaten)","Sesame seeds (optional)"],"purpose":"Rolls"}]', '[{"description":"Take pastry out of freezer.","images":[],"step":1},{"description":"Place spinach in a colander and use a wooden spoon or your hands to press out excess water. You could also do this using a tea towel or paper towels. Transfer spinach to a bowl (drink the liquid, it’s good for you!).","images":[],"step":2},{"description":"Add remaining Filling ingredients. Mix to combine.","images":[],"step":3},{"description":"Place pastry on work surface and cut in half to create 2 rectangles – you should have 6 in total.","images":[],"step":4},{"description":"Divide filling between pastries, brush edge with egg then roll up, finishing with the seam side down.","images":[],"step":5},{"description":"Refrigerate for 15 minutes. Meanwhile, preheat oven to 180C/350F.","duration":15,"images":[],"step":6},{"description":"Spray 2 x baking trays with oil (any).","images":[],"step":7},{"description":"Cut rolls into 4, or whatever size you want. Brush tops with egg (makes it golden) then sprinkle with sesame seeds.","images":[],"step":8},{"description":"Bake for 25 minutes, then take out the top tray and move the bottom tray to the top and give it an additional 5 - 10 minutes to make it golden.","duration":25,"images":[],"step":9},{"title":"Best served warm","description":"the pastry is crispier and the filling is juicier. See notes for make ahead instructions.","images":[],"step":10}]', '["egg","milk","sesame"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["snack"],"cuisine":[],"categories":["finger-food","quick-and-easy","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ac85cf7e473b', 'en', 'US', 'Chorizo Bites in Sweet & Spicy Sauce', 'Golden brown chorizo in a sweet and spicy sauce that''s so good, your guests will be mopping it up with bread!', 'https://www.recipetineats.com/tachyon/2016/11/Chorizo-Bites-with-Sweet-Spicy-Sauce-2.jpg', 10, 7, 17, 8, '[{"id": "ing_pineapple", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_ketchup", "quantity": {"value": 0.02, "unit": "bottle of 500g"}}, {"id": "ing_hot_sauce", "quantity": {"value": 0.067, "unit": "bottle of 150ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.019, "unit": "pack of 400g"}}, {"id": "ing_pineapple", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_chorizo", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_toothpicks_for_serving", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["3/4 cup pineapple juice","2 tsp ketchup (or Australia/UK tomato sauce)","2 tsp+ hot sauce of choice (Franks etc, adj to taste)","2 tbsp brown sugar (, packed)","1 garlic clove (, finely chopped or minced)","1/4 tsp salt","Pepper"],"purpose":"Sauce"},{"ingredients":["1 1/2 tsp cornflour / cornstarch","1 tbsp water or pineapple juice"],"purpose":"Thickener"},{"ingredients":["4 (~600 g / 1.2 lb) chorizo (Note 1)","2 tsp oil","Parsley (, for garnish (optional))","Toothpicks for serving"],"purpose":"Chorizo"}]', '[{"description":"Cut Chorizo into 8mm / 1/3\" thick slices on a slight angle","images":[],"step":1},{"description":"Mix together Sauce in a bowl.","images":[],"step":2},{"description":"Mix together Thickener in a small bowl.","images":[],"step":3},{"description":"Heat oil in a skillet over medium high heat. Add chorizo and cook until golden brown on both sides - around 3 minutes.","images":[],"step":4},{"description":"Add Sauce and simmer for 3 minutes.","duration":3,"images":[],"step":5},{"description":"Add Thickener and mix quickly, then simmer for 45 seconds to 1 minute until thickened - see video below recipe.","duration":0.75,"images":[],"step":6},{"description":"Transfer to serving bowl. Garnish with parsley if desired and serve with toothpicks.","images":[],"step":7}]', '[]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["snack"],"cuisine":[],"categories":["finger-food","pork-recipes","quick-and-easy","spanish-recipes","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6e4f108f56a9', 'en', 'US', '5 Easy Tapas Recipes', 'Create your own tapas bar at home! These are easy to make and can be prepared in advance so you can be eating and drinking with your friends rather than scurrying around in the kitchen! Tapas dishes are typically served with generous amounts of olive oil - fantastic for mopping up the flavours with bread. But feel free to cut back on the oil if you prefer! I recommend marinating the olives for 24 hours to allow the flavours to infuse.', 'https://www.recipetineats.com/tachyon/2016/08/Easy-Spanish-Tapas.jpg', 30, 30, 60, 6, '[{"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_shrimp", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_chorizo", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_plump_black_and_green_olives", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_oranges", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_rosemary", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_jam", "quantity": {"value": 0.003, "unit": "jar of 370g"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_anchovies", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_spanish_omelette_recipe_here", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_wine", "quantity": {"value": 1.0, "unit": "bottle of 750ml"}}]', '[{"ingredients":["1/4 cup / 65 ml olive oil","4 garlic cloves - 3 smashed (, 1 minced)","250 g / 8 oz raw prawns (, peeled)","Pinch of red pepper flakes","Finely chopped parsley","Optional: lemon"],"purpose":"Garlic Prawns / Shrimp"},{"ingredients":["1/4 cup olive oil (65 ml)","4 garlic cloves - 3 smashed (, 1 minced)","300 g / 10 oz Swiss brown or other small mushrooms","Finely chopped parsley"],"purpose":"Garlic mushrooms"},{"ingredients":["2 (~250g / 8oz) chorizos (, sliced (Note 3) )","1/2 tsp olive oil"],"purpose":"Chorizo"},{"ingredients":["250 g / 8 oz plump black and green olives","1 clove garlic (, minced)","1/2 tsp red pepper flakes","2 tsp Lemon or orange zest","1/3 cup olive oil (85 ml)","1 tsp fresh rosemary leaves (or 1/2 tsp dried oregano or 1 tsp fresh thyme)"],"purpose":"Marinated Olives (Note 4)"},{"ingredients":["Jamon cured ham","Manchego Spanish Cheese","White Anchovies"],"purpose":"Spanish Antipasto"},{"ingredients":["Spanish Omelette recipe here"],"purpose":"Spanish Omelette"},{"ingredients":["Bread (, Olive oil, Lemon wedges)","La Mesa Y Los Amigos Tempranillo Spanish Wine (great with tapas!)"],"purpose":"To Serve"}]', '[{"description":"Garlic Prawns (Note 1)","images":[],"step":1},{"description":"Place the smashed garlic in a skillet with the oil over medium heat. Sauté for 10 minutes, squishing the garlic down to squeeze juice out as it cooks, until garlic is golden brown. Then remove and discard garlic.","duration":10,"images":[],"step":2},{"description":"Sprinkle prawns with salt and pepper. Turn stove up to high. When oil is hot, add prawns and cook for 2 minutes (for medium prawns) or until charred and just cooked. Just before the end, add the minced garlic and quickly saute, then transfer prawns into serving bowl.","duration":2,"images":[],"step":3},{"description":"Sprinkle with parsley and red pepper flakes if using.","images":[],"step":4},{"description":"Garlic Mushrooms (Note 1)","images":[],"step":5},{"description":"Halve or quarter the mushrooms, depending on size.","images":[],"step":6},{"description":"Follow Garlic Prawn steps, except cook mushrooms instead of prawns. Cook the mushrooms until they are golden.","images":[],"step":7},{"description":"Heat oil in a skillet over high heat. Cook Chorizo until golden on both sides, then transfer to serving bowl, scraping in oil in the skillet.","images":[],"step":8},{"description":"Marinated Olives (Note 4)","images":[],"step":9},{"description":"Combine ingredients in an airtight jar. Refrigerate for 24 hours - no longer than 48 hours. Bring to room temperature before serving.","images":[],"step":10},{"description":"Spanish Antipasto","images":[],"step":11},{"description":"Bring cheese to room temperature. Place on platter with ham and anchovies.","images":[],"step":12},{"description":"To Serve","images":[],"step":13},{"description":"Place serving bowls / platters on table with plenty of bread to dunk into the leftover olive oil. Serve with your favourite Spanish wine!","images":[],"step":14}]', '["gluten","milk"]', '[]', '{"mealType":["snack"],"cuisine":["Spanish"],"categories":["finger-food","mediterranean-recipes","prawns-shrimp","quick-and-easy","spanish-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_51a5bf9ef3b2', 'en', 'US', 'Parmesan Shortbread Biscuits', 'These buttery biscuits have the texture of shortbread with the kick of parmesan cheese flavour. The biscuits are buttery and have a "soft crumble" when you bite into them. IMPORTANT: Please ensure you measure the ingredients by weight. Cup sizes measure between countries and so for accuracy reasons, I have written the recipe by weight rather than cups because this recipe requires accurate measurement of ingredients to achieve the desired result.', 'https://www.recipetineats.com/tachyon/2016/03/Parmesan-Shortbread-Biscuits_1-SQ.jpg', 10, 15, 25, 25, '[{"id": "ing_butter", "quantity": {"value": 3.5, "unit": "block of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.496, "unit": "pack of 200g"}}, {"id": "ing_flour", "quantity": {"value": 0.094, "unit": "kg"}}, {"id": "ing_rosemary", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["3.5 oz / 100g salted butter (, chopped (Note 1))","3.5 oz / 100g parmesan cheese (, grated (Note 2))","3.3 oz / 95g plain flour"]},{"ingredients":["1 tbsp rosemary leaves (, roughly chopped (or 2 1/2 tsp dried rosemary))"],"purpose":"For rosemary flavoured biscuits"}]', '[{"description":"Two Ways To Make The Dough","images":[],"step":1},{"description":"Process the butter, flour and parmesan in a food processor until a wet crumbly dough; OR","images":[],"step":2},{"title":"Alternative method","description":"Place the flour and butter into a bowl and use your fingers to rub the butter into the flour until a crumble dough forms. Then add the parmesan cheese and use your fingers to rub it into the mixture.","images":[],"step":3},{"description":"If you are making rosemary biscuits, add the rosemary at the same time as the parmesan cheese.","images":[],"step":4},{"description":"Make the biscuits","images":[],"step":5},{"description":"Lightly flour a surface and turn the dough out onto it. Knead to bring together, then shape into two logs with a diameter of around 3 cm / 1.2\" and about 15cm/6\" in length.","images":[],"step":6},{"description":"Wrap with cling wrap and refrigerate for 1 hour or until firm. (Note 2)","images":[],"step":7},{"description":"Preheat oven to 180°C/350F. Line 1 large baking tray or 2 ordinary baking trays with baking paper (parchment paper).","images":[],"step":8},{"description":"Remove the log from the fridge and use a sharp knife to cut the log into 7mm/ 1/3\" thick rounds.","images":[],"step":9},{"description":"Place the biscuits onto the baking tray at least 2cm / 1\" apart.","images":[],"step":10},{"description":"Bake biscuits for 12 minutes or until light golden.","duration":12,"images":[],"step":11},{"description":"Stand on trays for 5 minutes then transfer to a wire rack to cool.","duration":5,"images":[],"step":12}]', '["gluten","milk"]', '["keto_friendly","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["finger-food","most-popular"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b40552ff4795', 'en', 'US', 'Mexican Spring Rolls (Egg Rolls)', 'These Mexican spring rolls are so scrumptious you should make a double batch! Made healthier by baking, and stuffed full of the flavours of Mexico. I made this using Mexican Pulled Pork Carnitas because this recipe is part of a series using leftovers. But you can substitute with shredded or diced chicken or beef.', 'https://www.recipetineats.com/tachyon/2014/07/Mexican-Spring-Rolls-2.jpg', 15, 30, 45, 12, '[{"id": "ing_bread", "quantity": {"value": 12.0, "unit": "loaf"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_enchilada_sauce_for_dipping", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_pork", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 0.75, "unit": "block of 250g"}}, {"id": "ing_corn", "quantity": {"value": 0.188, "unit": "can of 400g"}}, {"id": "ing_black_beans", "quantity": {"value": 0.281, "unit": "can of 400g"}}, {"id": "ing_capsicum", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_paprika", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}]', '[{"ingredients":["12 spring roll wrappers or 16 egg roll wrappers (, defrosted (Note 2))","Olive oil spray","Enchilada sauce - for dipping (Note 3)"]},{"ingredients":["1 packed cup leftover pulled pork (Note 1)","3/4 cup grated cheese (cheddar, tasty or any other good melting cheese)","1/2 cup corn kernels (canned)","3/4 cup black beans (canned)","1/2 cup red bell peppers ((capsicum), diced)","1/4 cup coriander leaves","1/4 tsp paprika","1/4 tsp cumin","1/2 tsp onion powder","1/2 tsp salt"],"purpose":"Filling"}]', '[{"description":"Preheat the oven to 350F/180C.","images":[],"step":1},{"description":"Combine the filling ingredients and mix well.","images":[],"step":2},{"description":"Place a wrapper diagonally in front of you. Place 1/4 cup of the filling on the bottom half of the wrapper and shape into a log. If you are using egg roll wrappers, use 3 tablespoons per wrapper.","images":[],"step":3},{"description":"Roll up the wrapper to halfway, then fold in the left and right sides, then roll to the end, using a little water to seal.","images":[],"step":4},{"description":"Spray the spring rolls lightly, then turn each spring roll and lightly spray the other side.","images":[],"step":5},{"description":"Bake for 30 minutes, turning once, until golden.","duration":30,"images":[],"step":6},{"description":"Serve with Enchilada Sauce as the dipping sauce.","images":[],"step":7}]', '["egg","milk"]', '["gluten_free","low_calorie"]', '{"mealType":["snack"],"cuisine":["Mexican"],"categories":["finger-food","mexican-recipes","pork-recipes","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_484b53b23b59', 'en', 'US', 'Cajun Baked Salmon Bites', 'Recipe video above. Cajun Baked Salmon Bites is just a really tasty, no-fuss way to cook salmon, fast (12 minutes!). Cut into cubes so the Cajun flavour hits every bite, then bake in a hot oven so it browns without overcooking the inside. No stove splatter, yay!You''ll love the crinkled foil tray lining used here - it''s a nifty Japanese fish-baking tip. Crinkled foil = no sticking, no soggy underside on the salmon, plus less washing up (no rack). YAY!Serve with whatever your heart desires - stuffed into tacos, make rice bowls, add to salads, eat off the tray. You just can''t go wrong!', 'https://www.recipetineats.com/tachyon/2025/11/Cajun-baked-salmon_5.jpg', 7, 12, 19, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 0.025, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.013, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}]', '[{"ingredients":["4 salmon fillets (, skinless, cut into 2.5cm / 1\" cubes (~600 - 700g / 1.2 - 1.4lb total))"]},{"ingredients":["2 tsp paprika (regular/sweet, smoked also lovely)","3/4 tsp cooking salt / kosher salt (halve for table salt, +50% for flakes)","1 tsp onion powder","1 tsp garlic powder (don''t sub with fresh garlic, will burn)","1/4 tsp dried thyme","1/4 tsp black pepper","1/4 tsp cayenne pepper (, optional for slight spiciness)","2 1/2 tsp brown sugar (, tightly pack the teaspoons)","2 tbsp olive oil"],"purpose":"Cajun spice mix (Note 1):"}]', '[{"description":"Coat salmon with Cajun seasoning, bake on crumpled foil 12 minutes at 240°C/460°F (220°C fan-forced) until lightly browned. Enjoy!","images":[],"step":1},{"description":"Preheat the oven to 240°C/460°F (220°C fan-forced).","images":[],"step":2},{"title":"Crinkled foil trick","description":"Lightly scrunch up foil, then gently unfold it so it stays wrinkled. Lots of little pointy bits = good!.Place on the tray and fold the edges to secure, repeat with another sheet to cover the whole tray. The wrinkles lift the fish slightly, preventing sticking and soggy undersides - clever Japanese fish-cooking trick!","images":[],"step":3},{"title":"Coat salmon","description":"Put the Cajun Spice mix ingredients in a bowl and mix. Add salmon and toss to coat. Spread on the foil (the more spaced out they are, the better they colour).","images":[],"step":4},{"description":"Bake 12 minutes (don''t turn). Remove salmon from the tray (so they don''t keep cooking) then enjoy!","images":[],"step":5},{"description":"For Cajun Salmon Rice Bowls pictured:","images":[],"step":6},{"title":"Photos in post","description":"rice, lettuce, tomato, radish, avocado, Cajun salmon bites.","images":[],"step":7},{"title":"Video","description":"Rice, Cajun salmon bites, roasted corn avocado salsa - made at the same time as the salmon (Note 2).","images":[],"step":8},{"title":"Sauces and garnishes for both bowls","description":"Peri-naise or leftover pink Gyros sauce (or just kewpie/regular mayo mixed with sriracha or ketchup), chopped coriander or green onion.","images":[],"step":9}]', '["fish"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Cajun","Western"],"categories":["fish-recipes","mains","other","quick-and-easy","salmon-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8b39192909dd', 'en', 'US', 'Seafood Chowder', 'Recipe video above. This is a seafood soup so good, it''s hard to believe it''s made with cheap ''n cheerful marinara mix and store-bought stock. Using chicken rather than store-bought fish stock (awful stuff!), a cheeky dash of fish sauce rather than salt and bacon are some of the flavour enhancers we deploy here!Of course, if you use homemade fish stock and a hand-picked mix of fresh seafood, it will be upmarket-restaurant-worthy. :) Also see FAQ for more vegetable options.', 'https://www.recipetineats.com/tachyon/2025/09/Seafood-chowder_9.jpg', 20, 20, 40, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.65, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_bacon", "quantity": {"value": 0.5, "unit": "pack of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_chardonnay", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_potato", "quantity": {"value": 2.0, "unit": "bag of 2kg"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_corn", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.65, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 0.9, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["650g/ 1.3lb seafood marinara mix or mixed fresh seafood - fish (, squid, prawns, cooked mussel meat (Note 1))","50g (3 tbsp) unsalted butter","100g/ 4oz streaky bacon (, chopped into 1.5cm / 1/2\" squares)","2 cloves garlic (, finely minced)","1/2 cup chardonnay (or other dry white wine (can skip))","1/3 cup flour (, plain/all-purpose (Note 3 for gluten-free))","1 litre (4 cups) chicken stock/broth, low sodium OR homemade fish stock (avoid store-bought fish stock) (Note 2)","2 medium carrots (, peeled, cut into 7mm / 1/3\" pieces (~1 1/2 cups))","2 large potatoes (any type fine), peeled, cut into 1cm / 0.2\" cubes (~2 1/2 cups)","1 cup thickened cream / heavy cream (sub milk for lighter option)","1 cup corn (frozen or canned, drained)","2 tsp fish sauce","Pinch white pepper (substitute black pepper)"]},{"ingredients":["3 tbsp chives or parsley (, finely chopped, for garnish)","Crusty bread ( or better yet, garlic bread!)"],"purpose":"SERVING"}]', '[{"description":"Cook bacon in butter, remove. Sauté garlic, deglaze with white wine, make roux. Add stock, simmer potato, carrots and bacon 10 min. Add cream, corn, fish sauce, pepper, raw seafood - simmer 3 min. Stir in cooked seafood, taste for salt. Serve!","images":[],"step":1},{"title":"Marinara mix","description":"Separate cooked seafood (usually mussels, sometimes prawns/shrimp) from raw seafood. We put them in at different times.","images":[],"step":2},{"description":"Cut any large pieces of fish into 2.5cm / 1\" cubes.","images":[],"step":3},{"title":"Bacon","description":"In a heavy-based pot, melt the butter over medium heat. Add bacon and cook for 3 - 4 minutes until the edges are light golden. Use a slotted spoon to remove into bowl, leaving fat in the pot.","duration":3.5,"images":[],"step":4},{"title":"Deglaze","description":"Add the garlic and cook for 10 seconds (don''t let it brown). Add the wine, simmer rapidly on high for 3 minutes, scraping the base to loosen any golden bacon bits, until the wine is mostly evaporated.","duration":0.16666666666666666,"images":[],"step":5},{"title":"Roux","description":"Reduce heat down to medium, add the flour and mix for 1 minute (\"roux\").","duration":1,"images":[],"step":6},{"title":"Broth","description":"While stirring, pour in about 1 cup of the stock and mix to dissolve the roux - it will thicken into a paste. Add the remaining stock and stir well until lump free (use a whisk if needed).","images":[],"step":7},{"title":"Simmer 10 minutes","description":"Increase heat to high, bring to the boil, add the carrots, potatoes and bacon. Lower heat to medium and simmer for 10 - 12 minutes, or until the carrots are just about done.","duration":11,"images":[],"step":8},{"title":"Simmer raw seafood 3 minutes","description":"Add the cream, fish sauce, pepper, corn and raw seafood. Simmer for 3 minutes until the fish is just cooked (test - flesh should flake).","duration":3,"images":[],"step":9},{"title":"Cooked seafood","description":"Stir in cooked seafood, taste and add more salt if needed (I don''t).","images":[],"step":10},{"title":"Serve","description":"Ladle into bowls, sprinkle with chives. Serve with warm crusty bread for dunking!","images":[],"step":11}]', '["fish","gluten","milk","shellfish"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["fish-recipes","mains","other","seafood-recipes","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_070cb433311d', 'en', 'US', 'Lemon garlic salmon tray bake - easy & healthy!', 'Recipe video above. A tasty salmon tray bake recipe that''s as simple as it is healthy. Salmon infused with an assertive lemon garlic marinade cooks in just 11 minutes alongside parmesan asparagus and blistered cherry tomatoes. No stove splatter - yay! Green beans would also work great, or thin broccolini stems (and the florets go crunchy!). Shower with parmesan and squeeze of lemon for an easy finishing touch.', 'https://www.recipetineats.com/tachyon/2024/02/Lemon-garlic-salmon-tray-bake_1.jpg', 10, 11, 21, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_es_asparagus", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 0.8, "unit": "punnet of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_lemon", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["4 x 180g/6 oz salmon fillets (, skin on or off, doesn''t matter (Note 1))"]},{"ingredients":["1 tsp lemon zest (1 lemon)","1 tbsp lemon juice","2 tbsp extra virgin olive oil","1 tsp dijon mustard (Note 2)","2 garlic cloves (, grated using microplane (Note 3))","1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper"],"purpose":"Marinade slather:"},{"ingredients":["3 bunches asparagus (, woody ends snapped or trimmed off (Note 4))","200g/ 7 oz cherry tomatoes (or grape tomatoes, 1 Aussie punnet)","2 tsp extra virgin olive oil","1/4 tsp each salt and pepper"],"purpose":"Vegetables (optional):"},{"ingredients":["Olive oil spray","Parmesan (, finely grated)","Lemon wedges or slices (, optional)","Parsley (, finely chopped, optional)","Crusty bread or toast (, for serving)"],"purpose":"Cooking & serving:"}]', '[{"title":"Lemon garlic paste","description":"Mix the marinade ingredients in a small bowl. Slather onto the top and sides of the salmon. If time permits, marinade for 1 hour. Otherwise, proceed with recipe.","images":[],"step":1},{"description":"Preheat oven grill / broiler to 280°C/525°F or as high as yours goes. Place the oven shelf 20 cm /8\" from the heat source.","images":[],"step":2},{"title":"Prepare tray","description":"Toss the asparagus and cherry tomatoes with the olive oil, salt and pepper. Spread out on a large tray then clear space for the salmon. Place salmon on the tray leaving a bit of space between each. Spray surface of salmon with oil.","images":[],"step":3},{"title":"Cook","description":"Grill/broil for 11 minutes or until the salmon is done - the flesh should flake, the internal temperature should be 50°C/122°F (Note 5).","duration":11,"images":[],"step":4},{"title":"Serve","description":"Transfer salmon and vegetables to plate. Grate parmesan over the vegetables. Squeeze lemon juice over the salmon, sprinkle with parsley. Eat!","images":[],"step":5}]', '["fish","gluten","milk","mustard"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","fish-recipes","mains","one-pot-recipes","other","quick-and-easy","salmon-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9f3589a5e9ed', 'en', 'US', 'Calabrian Fish Ragu', 'Recipe video above. This is a fish pasta in a richly spiced fish ragu pasta sauce. The spice mix is based on njuda, the bold flavoured spreadable Calabrian salami paste that''s rising in popularity in the restaurant scene! It''s a great way to make fish stretch further, cooked in a unique way that''s outrageously delicious with big, bold Southern Italian flavours.No stale bread? Use panko instead. See notes. 3 servings? I know it''s a little odd, but the spice mix didn''t scale down neatly to make pasta for 2! (3/8 tsp nutmeg?!). Leftovers are always delicious. :)', 'https://www.recipetineats.com/tachyon/2023/10/Calabrian-fish-ragu-pasta_6-1.jpg', 10, 25, 35, 3, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_fennel_seeds", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_chilli", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_nutmeg_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_bread", "quantity": {"value": 0.188, "unit": "loaf"}}]', '[{"ingredients":["250g/ 8 oz firm white fish fillets (, skinless, boneless, cut into 2 cm / 0.8\" cubes (barramundi, snapper, cod - Note 1))","3/4 tsp black peppercorns (Note 2 for ground option)","1 tsp fennel seeds (Note 2 for ground option)","1 tbsp smoked paprika (sub ordinary paprika)","1/2 tsp red chilli flakes ((red pepper flakes), feel free to reduce/omit)","1/2 tsp nutmeg powder","1/2 tsp caster / superfine sugar","3/4 tsp cooking / kosher salt","3 tbsp extra virgin olive oil","2 tbsp tomato paste"],"purpose":"Calabrian spiced fish:"},{"ingredients":["250g/8 oz linguine pasta (or fettuccine, spaghetti)","1 tbsp cooking / kosher salt (, for pasta water)","1 1/2 tbsp extra virgin olive oil","3 garlic cloves (, finely minced)","3/4 cup tomato passata (US: tomato puree, Note 3)"],"purpose":"Pasta:"},{"ingredients":["1 tbsp finely chopped parsley","Parmesan cheese (, finely grated, for serving)"],"purpose":"Garnish:"},{"ingredients":["1 cup stale bread like sourdough, ciabatta (, crusts removed, torn/chopped into irregular 1cm/0.4\" pieces (Note 4))","2 tsp extra virgin olive oil","1 pinch cooking / kosher salt"],"purpose":"Pangrattato"}]', '[{"title":"Toast & grind","description":"Preheat a large deep skillet or pot over medium heat (Note 5), no oil. Toast black peppercorn and fennel for 1 1/2 to 2 minutes until it smells fragrant and the fennel is lightly browned. Transfer to a mortar and use a pestle and grind to a powder while still hot.","images":[],"step":1},{"title":"Coat fish","description":"Transfer to a medium bowl with remaining Calabrian spiced fish ingredients. Stir well with a spatula until combined. Set aside.","images":[],"step":2},{"title":"Cook pasta","description":"Boil 3 litres of water with the cooking salt. Cook pasta per packet directions minus 1 minute. Just before draining, scoop out 1 1/2 cups pasta cooking water. Then drain in a colander and leave until ready to use.","images":[],"step":3},{"title":"Calabrian fish ragu","description":"While the pasta is cooking, heat olive oil in the same skillet you used to toast the fennel on medium high. Add garlic and cook for 1 minute. Add the fish. Cook for 2 minutes, stirring regularly. Add tomato passata. Simmer for 5 minutes, stirring occasionally. Add 1 cup of the reserved pasta cooking water and simmer for 2 minutes.","duration":1,"images":[],"step":4},{"title":"Toss pasta","description":"Add pasta and 3/4 of the parsley. Toss for 1 minute to coat the pasta with the sauce. Most of the fish will break up into flakes but some will remain in larger chunks - this is good! We don''t want disintegrated mush, nor giant chunks. Once the pasta turns red and the sauce and fish bits are clinging to the pasta straws, remove from heat and divide between bowls immediately.","duration":1,"images":[],"step":5},{"title":"Serve","description":"Sprinkle with pasta, pangrattato and parmesan. Eat immediately!","images":[],"step":6},{"description":"Preheat oven to 180°C / 350°F (160°C fan-forced).","images":[],"step":7},{"description":"Toss bread, oil and salt in a small bowl. Spread on a tray and bake for 10 minutes, tossing at the 5 minute mark, or until light golden and fully crisp.","duration":10,"images":[],"step":8}]', '["fish","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian-esque"],"categories":["fish-recipes","italian-recipes","mains","other","pasta-recipes","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b262f1b1519c', 'en', 'US', 'Creamy fish on potato gratin', 'Recipe video above. This is a one-pan meal with fish baked on top of a potato gratin in a creamy sauce with a golden crunchy topping. It''s a cross between a casserole, gratin and a pie. The idea is that the panko acts like a lid, keeping the fish succulent as it bubbles away in the cream while the gratin soaks up the tasty fish juices.This is a fabulous cosy, rustic oven baked fish recipe that''s effortless yet company worthy!', 'https://www.recipetineats.com/tachyon/2023/05/Creamy-baked-fish-on-potato-gratin_7.jpg', 10, 45, 55, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_leeks", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_potato", "quantity": {"value": 2.0, "unit": "bag of 2kg"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_bread", "quantity": {"value": 0.141, "unit": "loaf"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}]', '[{"ingredients":["4 x 160g/5oz white fish fillets (, ~2cm / 0.8\" thick, skinless (barramundi, snapper, tilapia, cod, salmon - Note 1))","1/2 tsp cooking/kosher salt","1/4 tsp black pepper"]},{"ingredients":["3 tbsp / 50g unsalted butter","2 large leeks (, white and pale green part only, washed, cut in half lengthways, sliced 5mm / 0.2\" thick OR 2 onions (Note 2))","3 garlic cloves (, minced)","2 medium starchy potatoes (250g / 8oz each), peeled (Note 3)","3/4 tsp cooking/kosher salt","1/2 tsp black pepper","1/2 cup dry white wine (, any type, sub more veg stock (Note 4))","1/2 cup vegetable stock/broth (, low sodium)","1 cup thickened/heavy cream"],"purpose":"Potato gratin:"},{"ingredients":["3/4 cup panko breadcrumbs","2 tbsp extra virgin olive oil","1/4 cup parmesan (, finely shredded)"],"purpose":"Crunchy topping:"}]', '[{"description":"Preheat the oven to 180°C/350°F (160°C fan) with a shelf in the middle.","images":[],"step":1},{"title":"Potatoes","description":"Cut the potatoes into quarters, then sliced 4mm / 1/6\" thick. Place cut potato in a large bowl of water (prevents from going brown, removes excess starch so it cooks quicker). Drain before use.","images":[],"step":2},{"title":"Crunchy topping","description":"Mix panko and olive oil in a bowl. Then stir in parmesan.","images":[],"step":3},{"title":"Season fish","description":"Sprinkle salt and pepper on both sides of the fish fillets. Set aside.","images":[],"step":4},{"title":"Sauté","description":"Melt butter in a large oven-proof skillet (30cm/12\") over high heat until foamy. Add leek and garlic, then cook for 3 minutes.","duration":3,"images":[],"step":5},{"title":"Sauté potatoes","description":"Add potato, salt and pepper. Cook for 6 minutes, stirring regularly. The potatoes should be half cooked at this stage.","duration":6,"images":[],"step":6},{"title":"Reduce wine and stock","description":"Pour in white wine. Simmer rapidly until it is mostly evaporated - about 1 minute. Pour in stock, then simmer for 1 1/2 minutes or until reduced by half.","images":[],"step":7},{"title":"Top with fish","description":"Turn the stove off. Place fish on top of the potatoes, presentation side up. (Note 1) Pour cream all over, aiming for full coverage. Sprinkle with panko breadcrumbs.","images":[],"step":8},{"title":"Bake for 30 minutes","description":"I know this sounds like a long time but the fish stays succulent!","duration":30,"images":[],"step":9},{"title":"Colour topping","description":"Switch to the oven grill (broiler) on high and move the skillet up to the top shelf. Grill/broil 4 minutes or until golden.","images":[],"step":10},{"title":"Rest","description":"Remove and rest for 5 minutes, then serve! Eat the fish and gratin together with each mouthful for maximum eating pleasure!!","duration":5,"images":[],"step":11}]', '["fish","milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["French-style","Western"],"categories":["fish-recipes","mains","one-pot-recipes","other","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a9d95f30fe20', 'en', 'US', 'Kedgeree - British curried rice and fish', 'Recipe video above. Traditional English smoked fish and rice dish - think of it as an English biryani! Smoked haddock or cod tossed through a butter spiced rice studded with eggs, this is true fusion food at its best.', 'https://www.recipetineats.com/tachyon/2023/04/Kedgeree_3.jpg', 15, 30, 45, 5, '[{"id": "ing_chicken_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_smoked_haddock_or_cod", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_rice", "quantity": {"value": 337.5, "unit": "pack"}}, {"id": "ing_butter", "quantity": {"value": 75.0, "unit": "block of 250g"}}, {"id": "ing_curry_leaves", "quantity": {"value": 15.0, "unit": "kg"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.15, "unit": "jar of 40g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.2, "unit": "jar of 50g"}}, {"id": "ing_turmeric", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}]', '[{"ingredients":["4 cups/ 1 litre chicken stock/broth (, low-sodium (Note 5))","500g/1 lb smoked haddock or cod (, skin-on (or other smoked fish, Note 1))","2 1/4 cups long grain rice (, uncooked)","75g / 5 tbsp unsalted butter","15 curry leaves (optional, Note 2)","6 green cardamom pods (, lightly crushed (Note 3))","1 brown onion (, diced)","2 garlic cloves (, finely minced)","2 tsp curry powder (anything! Use spicy if you want, I use mild)","1/2 tsp turmeric powder","1 cup frozen peas (, thawed)","1/2 cup coriander/cilantro leaves (, roughly chopped (sub green onion or parsley))","3 hard boiled eggs (, halved or quartered (9 minute cook))"]}]', '[{"title":"Poach fish","description":"Bring chicken stock to a boil in a large saucepan or small pot. Place fish in (it should all be just about submerged, Note 4) and adjust heat so the stock is barely rippling. Poach it gently for 8 minutes or until the fish flakes apart. Remove fish onto a large plate.","duration":8,"images":[],"step":1},{"title":"Flake fish","description":"When cool enough to handle, discard skin (gently scrape with a butter knife) and flake fish into large pieces, checking for any bones.","images":[],"step":2},{"title":"Reserve stock","description":"Measure out 1/2 cup of the poaching liquid and set aside for later (drizzle on at end to juice up the rice).","images":[],"step":3},{"title":"Cook rice 13 min","description":"Add rice into the poaching liquid in the saucepan. Bring to a simmer over high heat. Cover with lid then reduce heat to low. Cook for 13 minutes.","duration":13,"images":[],"step":4},{"title":"Rest rice 10 min","description":"Remove the saucepan from the stove with the lid on and rest for 10 minutes. Fluff rice using a rubber spatula.","duration":10,"images":[],"step":5},{"title":"Curried butter","description":"While the rice is resting, melt the butter in a very large (30cm/12\") non stick skillet or pot, over medium-high heat. Add the cardamom pods and curry leaves and stir for 30 seconds. Add the onions, garlic and sauté for 5 minutes until browning at the edges, stirring regularly.","duration":0.5,"images":[],"step":6},{"title":"Toss rice","description":"Lower heat to medium. Stir in the curry powder and turmeric, and then the rice. Toss the rice in the spiced butter until well coated and uniformly yellow. Pour over the reserved 1/2 cup of fish poaching stock, and toss to mix through (it moistens the rice).","images":[],"step":7},{"title":"Season with salt if required","description":"Check the rice for seasoning. If you used store-bought packet stock, you should find there''s enough natural saltiness already. Otherwise season to taste and mix rice well.","images":[],"step":8},{"title":"Peas & fish","description":"Stir through the peas and most of the coriander (hold some back for garnish). Then gently fold through the fish, taking care to keep some pieces in large chunks.","images":[],"step":9},{"title":"Serve","description":"Spoon out rice onto one large platter or individual plates to serve. Top with boiled egg halves, and garnish with the remaining coriander. EAT!","images":[],"step":10}]', '["egg","fish","milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["British","English"],"categories":["fish-recipes","mains","other","quick-and-easy","rice-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5a76b93cf025', 'en', 'US', 'Chilli Lime Fish', 'Recipe video above. Pan-seared chunks of white fish are coated in a syrupy, spicy lime sauce in this dish loosely based on pla tort sahm rot, a traditional Thai street stall favourite. It tastes a bit like a fish version of everybody''s favourite Chilli Garlic Prawns. Very quick to make, it''s loaded with big flavours!Spice level: fairly spicy but not blow-your-head-off. See Note 4 for how to control the spiciness.', 'https://www.recipetineats.com/tachyon/2022/10/Chilli-Lime-Fish-cookbook-reference-photo_5.jpg', 10, 8, 18, 2, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.33, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_sriracha", "quantity": {"value": 0.075, "unit": "bottle of 400ml"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_rice", "quantity": {"value": 37.5, "unit": "pack"}}, {"id": "ing_steamed_asian_greens", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["330g / 11 oz thin white fish fillets (~1cm / 0.4\" thick) (, skinless, cut into 6cm / 2.5\" (or so) squares pieces (Note 1))","1/4 tsp cooking/kosher salt","1/4 cup rice flour or ordinary flour (Note 2)","2 tbsp canola oil"],"purpose":"Fish:"},{"ingredients":["2 tsp sesame oil","2 garlic cloves (, finely minced with a knife (Note 3))","2 tsp ginger (, finely minced with a knife (Note 3))","1 tsp chilli flakes / red pepper flakes (Note 4)","2 tbsp sriracha (Note 4)","2 tsp light soy sauce or fish sauce (Note 5)","3 tbsp brown sugar","1/2 cup water","2 tbsp lime juice"],"purpose":"Sauce:"},{"ingredients":["2 tbsp coriander/cilantro leaves","1 tbsp large red chilli (, finely sliced)","Lime wedges"],"purpose":"Garnishes (optional):"},{"ingredients":["Rice of choice","Steamed Asian greens"],"purpose":"Serve with:"}]', '[{"title":"Dust fish","description":"Sprinkle with salt, dust with rice flour, shake off excess.","images":[],"step":1},{"title":"Cook fish","description":"In a non-stick skillet, heat oil over medium-high heat. Cook the fish until golden on each side then remove to a plate.","images":[],"step":2},{"title":"Fish cooking times","description":"Thin fillets 1 cm / 2/5\" thick: 1 1/2 minutes each side; thicker fillets 1.5 - 1.75cm / 0.6 - 0.75\" thick 2 minutes each side) or until the internal temperature is 55°C / 130°F. Remove fish to a plate and set aside.","images":[],"step":3},{"title":"Sauté aromatics","description":"In the same pan, add sesame oil on medium heat. Cook garlic, chilli and ginger until golden - about 20 seconds.","images":[],"step":4},{"title":"Sauce","description":"Add everything else except lime juice. Stir, simmer, then reduce until syrupy - about 2 minutes. Add lime juice and stir. (If sauce gets too thick, add water)","images":[],"step":5},{"title":"Coat fish","description":"Return fish into sauce, turning to coat in the sauce.","images":[],"step":6},{"description":"Serve over rice, with garnishes of choice! Pictured with steamed baby pak choy tossed with Asian Sesame Dressing.","images":[],"step":7}]', '["fish","gluten","sesame","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Modern Asian","Thai-ish"],"categories":["fish-recipes","mains","other","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9a562a1e1042', 'en', 'US', 'Italian Crusted Sardines', 'Recipe video above. Here''s the perfect recipe for the sardine-shy: coat filleted sardines with an assertive Italian crust then pan fry until crispy. It''s an explosion of flavour and texture cooked in 2 1/2 minutes flat, making it one of the fastest fish recipes around!Excellent recipe for the sardine wary or first timers - no bones to worry about, and the intense Italian flavours balance out any concerns about the fishy flavour of sardines.Serve on crostini with a fresh salad on the side.', 'https://www.recipetineats.com/tachyon/2021/09/Mediterranea-Crusted-Sardines_4-Square.jpg', 10, 5, 15, 2, '[{"id": "ing_butter", "quantity": {"value": 8.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_bread", "quantity": {"value": 0.094, "unit": "loaf"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_pinenuts", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_fish_fillets", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_baby_capers", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.3, "unit": "pack of 200g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_onion", "quantity": {"value": 20.0, "unit": "pack of 1kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_parsley", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["8 butterflied sardines (20g each = 160g total, Note 1)","1/4 tsp salt","1/8 tsp pepper","1/4 tsp smoked paprika (sub normal or sweet)","3 tbsp extra virgin olive oil"],"purpose":"Sardines:"},{"ingredients":["1/2 cup panko breadcrumbs (Note 2)","1 garlic clove (, finely minced)","2 tsp toasted pinenuts (, finely chopped (Note 3))","2 anchovies fillets (, finely minced (sub 3/4 tsp paste, Note 4))","1 tsp baby capers (, drained, finely chopped (Note 5))","1 tsp lemon zest","4 tbsp pecorino cheese (, finely grated (or parmesan))","2 tsp fresh oregano (, chopped (sub 1/2 tsp dried))","1 tbsp extra virgin olive oil"],"purpose":"Italian Crust:"},{"ingredients":["4 tsp red onion, finely chopped (~1/4 small onion)","1 tsp large red chilli, finely chopped (, deseeded)","2 tsp parsley (, finely chopped)"],"purpose":"Topping:"}]', '[{"title":"Mix Crust","description":"Mix the Italian Crust ingredients in a bowl. Spread on a small plate.","images":[],"step":1},{"title":"Mix Topping","description":"Mix the Topping together in another small bowl.","images":[],"step":2},{"description":"Crust sardines:","images":[],"step":3},{"title":"Prepare sardines","description":"Pat sardines dry with paper towel. Sprinkle both sides of each sardine with the salt and pepper. Sprinkle the skin side only with the paprika.","images":[],"step":4},{"title":"Crust flesh side","description":"Press flesh side only firmly into the breadcrumbs - it won''t completely cover, that''s what we want (Note 6). Place on plate, breadcrumb side up. Repeat with remaining sardines.","images":[],"step":5},{"description":"Cooking sardines:","images":[],"step":6},{"title":"Pan fry sardines","description":"Heat oil in a large non stick skillet over medium high heat. Place sardines in, skin side down. Cook for 60 seconds, then carefully turn. Cook the crust side for 90 seconds or until golden and crispy.","duration":1,"images":[],"step":7},{"title":"Topping & oil drizzle","description":"Remove sardines onto plate, crust side up. Sprinkle with Topping. Pour remaining hot oil over sardines - enjoy the sizzle!","images":[],"step":8},{"description":"Serve immediately! Ideal served with crostini for the ultimate sardines on toast. See in post for side salad pairings.","images":[],"step":9}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["dinner-tonight","fish-recipes","italian-recipes","mains","other","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_eff49e4638ee', 'en', 'US', 'Fish with White Wine Sauce', 'Recipe video above. This is a beautiful, elegant white wine sauce that will go with virtually any fish. The simple restaurant trick we deploy here is to mix in cold cubes of butter which makes the sauce glossy and satiny. It''s a classic French technique called monter au beurre.Don''t try this sauce with baked fish (make this Baked Fish with Lemon Cream Sauce instead). You need to pan fry because the fond left in the pan after pan frying dissolves into the sauce and adds flavour.', 'https://www.recipetineats.com/tachyon/2021/08/Fish-in-white-wine-cream-sauce_95.jpg', 5, 12, 17, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_wine", "quantity": {"value": 0.417, "unit": "bottle of 750ml"}}, {"id": "ing_lemon", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_parsley", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["4 x 150g / 5oz white fish fillets (, skinless, boneless (I used snapper, Note 1))","1/2 tsp salt","1/4 tsp pepper","2 tbsp extra virgin olive oil"],"purpose":"Pan seared fish:"},{"ingredients":["1 eschalot (, small, finely chopped (~1 1/2 tbs, Note 2))","1 1/4 cups white wine (, dry, not sweet or too woody (chardonnay is especially good, Note 3))","1 tsp lemon juice (sub white wine vinegar)","1 tsp white wine vinegar (sub more lemon)","1/8 tsp salt","1 pinch pepper","1 pinch white sugar","1 cup thickened/heavy cream","30g / 2 tbsp unsalted butter (, cold, cut into 1cm / 1/3\" cubes)"],"purpose":"White wine sauce:"},{"ingredients":["2 tsp finely chopped parsley (or chives)"],"purpose":"Garnish, optional:"}]', '[{"description":"Cook fish:","images":[],"step":1},{"description":"Preheat oven to 50°C/120°F. Place rack over a tray.","images":[],"step":2},{"title":"Season fish","description":"Sprinkle fish with salt and pepper.","images":[],"step":3},{"title":"Cook fish","description":"Heat oil in a large non stick skillet over medium high heat. Cook fish in two batches until golden, 2 minutes on each side, or until the internal temperature is 55°C/131°F. (Note 4)","images":[],"step":4},{"title":"Keep warm","description":"Place fish on rack, and place in the oven to keep warm.","images":[],"step":5},{"description":"White wine sauce:","images":[],"step":6},{"title":"Discard oil","description":"Tip out excess oil from the skillet but don''t wipe clean.","images":[],"step":7},{"title":"Reduce wine","description":"Add eschalot, white wine, lemon juice, vinegar, salt, pepper, sugar to the pan. Bring to simmer (still on medium high) and reduce by half (~3 minutes).","images":[],"step":8},{"title":"Simmer cream","description":"Add cream, simmer for 2 minutes.","duration":2,"images":[],"step":9},{"title":"Finish with COLD butter","description":"Turn heat to low and add cold butter one cube at a time while mixing with wooden spoon. Once all the butter is incorporated, the sauce should be thickened, satiny and beautifully glossy.","images":[],"step":10},{"title":"Optional strain","description":"Strain the sauce through a sieve (discard eschalot), then pour it back into the pan.","images":[],"step":11},{"title":"Fish in sauce","description":"Place fish back into the pan in the sauce. Spoon some sauce over the fish, leave for 30 seconds.","duration":0.5,"images":[],"step":12},{"title":"Serve","description":"Transfer fish onto serving plates. Spoon sauce over each fish, sprinkled with parsley if desired. Pictured with a side of pea puree (great colour splash!).","images":[],"step":13}]', '["fish","milk"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["French-ish","Western"],"categories":["dinner-tonight","fish-recipes","mains","other","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0ffa15dca2f8', 'en', 'US', 'Really good Fish Cakes', 'Recipe video above. You''ll find plenty of fish cake recipes floating around. But there are good fish cakes and then there are great fish cakes! The trick is to keep the potato chunky and the fish in big flakes rather than letting it all turn into a mush. Meanwhile, adding garlic, chilli, green onion and thyme to the mix keeps these fish cakes full of flavour!Pan fry then bake for best results. Pan fry golden, then bake to heat all the way through (because I like my fish cakes chunky!) and reheat the first batch you pan fried.', 'https://www.recipetineats.com/tachyon/2021/07/Fish-Cakes_96.jpg', 30, 95, 125, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_potato", "quantity": {"value": 800.0, "unit": "bag of 2kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 1.5, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 20.0, "unit": "pack of 100g"}}, {"id": "ing_thyme", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_flour", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_bread", "quantity": {"value": 0.234, "unit": "loaf"}}, {"id": "ing_oil", "quantity": {"value": 150.0, "unit": "bottle"}}]', '[{"ingredients":["500g / 1 lb white fish fillets (, skinless boneless, cut into 3cm / 1.2\" pieces (Note 1))","60g / 4 tbsp unsalted butter","1/2 tsp salt","1/4 tsp black pepper"],"purpose":"Fish:"},{"ingredients":["800g / 1.6 lb potatoes ( – Sebago (Aus), Russet (US), Maris Piper / King Edwards (UK) (Note 2) (makes 500g flesh))","2 garlic cloves (, finely minced)","1/2 cup green onion (, finely sliced (~1 large stem))","2 large red chillis (, deseeded and finely chopped (can omit))","1 tbsp thyme leaves (, chopped)","1 tbsp parsley (, finely chopped)","3/4 tsp salt"],"purpose":"Fish cakes:"},{"ingredients":["1 cup flour","2 eggs (, lightly whisked)","1 1/4 cups panko breadcrumbs (sub ordinary breadcrumbs)","1 cup vegetable or canola oil (, for frying (~ 1cm / 0.4\" depth))"],"purpose":"Crumbing and cooking:"}]', '[{"description":"Bake potatoes in a 220°C / 430°F (200°C fan) oven for 75 minutes or until they can be pierced with a knife with no resistance. Cut in half and scoop flesh out into a large bowl.","duration":75,"images":[],"step":1},{"title":"Turn oven down to 200°C / 390°F (180°C fan)","description":"fish cakes are finished in the oven.","images":[],"step":2},{"description":"Cook fish (while baking potatoes):","images":[],"step":3},{"description":"Set a rack over a tray. Sprinkle fish with salt and pepper.","images":[],"step":4},{"description":"Melt butter in a large non-stick skillet over medium high heat. Add half the fish and cook, turning, for 4 minutes in total. It should be just cooked inside (ie. flakes easily) but not golden.","duration":4,"images":[],"step":5},{"description":"Transfer to rack to cool. Repeat with remaining fish.","images":[],"step":6},{"description":"Fish Cake Mixture:","images":[],"step":7},{"title":"Sauté garlic","description":"In the same skillet, add garlic, chilli ,thyme and green onion into the leftover butter. Cook for 1 minute until garlic is golden, then pour over the potato, being sure to scrape out every drop of butter!","duration":1,"images":[],"step":8},{"title":"Roughly mash potato","description":"Add parsley and salt, then use a wooden spoon to roughly mash the potato. Don''t use a potato masher, we want some chunks, not smooth mashed potato.","images":[],"step":9},{"title":"Mix in fish","description":"Add fish then gently stir through, breaking it up a bit so you have some nice flakes mixed throughout the potato. Don''t mash the fish up too enthusiastically - we want fish chunks!","images":[],"step":10},{"title":"Form fish cakes","description":"Scoop out 1/4 cup of mixture. Pack it in firmly, pop out onto hand and shape firmly into a 1.75cm / 2/3\" thick cake. The potato will make it hold together, if you press firmly. You should make 13 to 15.","images":[],"step":11},{"description":"Crumb and cook:","images":[],"step":12},{"title":"Crumb","description":"Coat in flour (shake off excess), dip in egg (let excess drip off) then coat in breadcrumbs, pressing to adhere.","images":[],"step":13},{"title":"Pan fry 3 minutes","description":"Heat oil in skillet over medium high heat. Cook fish cakes in batches for 1 1/2 minutes on each side until golden, then transfer to a paper towel-lined tray. If you''re pedantic like me, stand them on their side and roll slowly to cook and make the sides golden too.","images":[],"step":14},{"title":"Bake 10 minutes","description":"Remove paper towel from under the fish cakes. Bake for 10 minutes (this heats all the fish cakes all the way through into the middle + reheats the first batch cooked).","duration":10,"images":[],"step":15},{"description":"Serve with lemon wedges, tartare sauce, plain mayonnaise (Kewpie!), sour cream, ketchup or tomato sauce.","images":[],"step":16}]', '["egg","fish","gluten","milk"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["fish-recipes","mains","other","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6afecd3fc001', 'en', 'US', 'Salmon with Herb & Garlic Cream Sauce', 'Recipe video above. This quick, creamy Salmon Sauce gets a fine dining touch with the addition of fresh tarragon and chervil. It''s simply an excellent, easy salmon recipe for all those times when you want a touch of luxury with minimal effort!', 'https://www.recipetineats.com/tachyon/2021/01/Salmon-in-Creamy-Herb-Garlic-Sauce_6.jpg', 5, 15, 20, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 15.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_tarragon", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chervil", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_parsley", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["4 salmon fillets (, skinless (~180g/6oz each) (Note 1))","1/2 tsp black pepper","1/2 tsp salt","1 tbsp olive oil","15g / 1 tbsp butter (, unsalted)"],"purpose":"Salmon"},{"ingredients":["2 garlic cloves (, finely minced)","1/2 cup dry white wine (or more chicken stock) (Note 2)","1/2 cup chicken or vegetable stock/broth (, low sodium)","1 cup cream (, heavy/thickened )","1/2 cup parmesan (, finely grated (grate your own, Note 3))","2 tsp tarragon leaves* (, finely chopped)","2 tsp chervil* (, finely chopped)","2 tsp parsley* (, finely chopped, plus more for garnish)"],"purpose":"Creamy garlic sauce:"}]', '[{"title":"Season","description":"Pat salmon dry, then sprinkle with salt and pepper.","images":[],"step":1},{"title":"Pan-sear","description":"Heat oil in a large non stick skillet over medium high heat. Add salmon, presentation side down, and cook for 3 minutes until golden brown.","duration":3,"images":[],"step":2},{"title":"Flip","description":"Turn salmon and cook the other side for another 2 minutes, until the internal temperature registers 49°C / 120°F (for medium-rare, recommended) or until cooked to your taste (Note 5).","images":[],"step":3},{"title":"Butter baste","description":"When it''s almost cooked, add the butter. Melt, then spoon over the salmon a few times.","images":[],"step":4},{"title":"Rest","description":"Remove salmon onto plate, and cover loosely with foil to keep warm.","images":[],"step":5},{"description":"Creamy Salmon Sauce:","images":[],"step":6},{"title":"Sauté garlic","description":"Add garlic and stir for 20 seconds or until light golden.","duration":0.3333333333333333,"images":[],"step":7},{"title":"Reduce wine","description":"Add white wine, turn up heat to high. Bring to simmer while stirring base of the pan to dissolve all the golden bits into the sauce. Cook 1 minute or until it most evaporates and the wine-y smell is gone.","images":[],"step":8},{"title":"Thicken cream & stock","description":"Add cream and chicken stock, then simmer on medium heat for 2 - 3 minutes until reduced and slightly thickened.","duration":2.5,"images":[],"step":9},{"title":"Add parmesan & herbs","description":"Stir through parmesan (this will thicken sauce more), then the herbs. Taste sauce and see if more salt and pepper is needed.","images":[],"step":10},{"title":"Serve","description":"Serve salmon with Creamy Sauce, ensuring there''s something on the plate to soak up all that amazing sauce! Mashed Potato rates highly. See above video for list of suggestions (including side salads).","images":[],"step":11}]', '["fish","milk"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner","snack"],"cuisine":["Western"],"categories":["dinner-tonight","fish-recipes","mains","other","quick-and-easy","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9f1d25fd5a17', 'en', 'US', 'Crispy Beer Battered Fish', 'Recipe video above. This makes a light, crispy fish batter like you''ve never had before! Stays crispy for a good 15 - 20 min, though my fish disappears long before that.The yeast and carbonation in beer makes the batter puffy just like you get at good fish ''n chip shops. Meanwhile the rice flour + shock of ice cold batter hitting the hot oil makes it super crispy. Normal wheat flour doesn''t cut it – the batter goes soggy within minutes!You can''t taste the beer at all, and the alcohol gets cooked out. Serve with ultra crispy French fries for the ultimate homemade Fish & Chips experience.', 'https://www.recipetineats.com/tachyon/2021/01/Beer-Battered-Fish_8.jpg', 10, 12, 22, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 1.0, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_beer", "quantity": {"value": 0.758, "unit": "bottle of 330ml"}}, {"id": "ing_oil", "quantity": {"value": 4.0, "unit": "bottle"}}, {"id": "ing_tartare_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_homemade_crispy_french_fries", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}]', '[{"ingredients":["700g/ 1.4lb white fish fillets (, like flathead, snapper, whiting, cod, tilapia, flathead (skinless, boneless, Note 1))"],"purpose":"Fish:"},{"ingredients":["¼ cup rice flour (Note 2)"],"purpose":"Dusting:"},{"ingredients":["¾ cup plain/all purpose flour","¼ cup rice flour (makes it super crispy, Note 2)","1¼ tsp baking powder","¼ tsp salt","1 cup very cold beer (, anything other than dark beers like stout, porter etc (Note 3))"],"purpose":"Crispy Fish Batter:"},{"ingredients":["4 - 5 cups peanut oil (or vegetable, canola or cottonseed oil)"],"purpose":"Cooking:"},{"ingredients":["Tartare Sauce","Lemon Wedges","Homemade Crispy French fries","Baked Potato Wedges"],"purpose":"Serving:"}]', '[{"title":"Dry & cut fish","description":"Pat fish dry using paper towels or a tea towel. Cut into 7 x 3cm / 3 x 1¼\" batons, or larger fillets if you prefer. If you have very thick fillets, cut in half horizontally (Note 1)","images":[],"step":1},{"title":"Dusting bowl","description":"Place ¼ cup rice flour in a shallow bowl.","images":[],"step":2},{"title":"Heat oil: Heat 6cm / 2\"","description":"3\" oil in a large heavy based pot over medium high heat to 190°C/375°F.","images":[],"step":3},{"title":"Salt & dust","description":"While oil is heating, sprinkle 3 or 4 pieces of fish with a pinch of salt, then coat in rice flour and shake off excess. You can leave them like this for up to 10 minutes.","images":[],"step":4},{"title":"Cold batter","description":"Just before cooking, whisk together the flour, rice flour, baking powder and salt. Add very cold beer into the batter and whisk just until incorporated evenly into the flour. Do not over-mix, do not worry about flour lumps (Note 4). It should be a fairly thin batter but fully coat the back of a spoon. If too thick, add beer 1 tsp at a time.","images":[],"step":5},{"title":"Dredge fish","description":"Dunk a piece of fish in the batter, the let the excess drip off very briefly.","images":[],"step":6},{"title":"Fry 3 minutes","description":"Carefully lower into oil, dropping it in away from you, one piece at a time. Don''t crowd the pot; fry in batches. Fry for 3 minutes, flipping after about 2 minutes, until deep golden.","duration":3,"images":[],"step":7},{"title":"Drain","description":"Drain on paper towels. Repeat with remaining fish. Serve hot! However it will stay crisp for 15 - 20 minutes. (Note 5 for larger batch cooking).","duration":17.5,"images":[],"step":8},{"description":"Serve with Tartare Sauce, lemon wedges and a leafy green salad on the side dressed with a classic vinaigrette. Serve with Crispy French Fries or oven baked wedges!","images":[],"step":9}]', '["fish","gluten","peanuts"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["deep-fried-recipes","fish-recipes","iconic-dishes","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d680e7dad1cf', 'en', 'US', 'Crispy Skin Salmon', 'Recipe video above. Cooking salmon so the skin is evenly crispy from end to end is simple if you follow two key tips: Firstly, ensuring the skin is dry. Secondly, using enough oil to cover the base of the skillet so the skin fries properly and goes golden and crispy rather than just burning in patches. Easy!Pictured with a creamy Lemon & Herb Risotto (ultra easy hands-free baked method!).', 'https://www.recipetineats.com/tachyon/2020/11/Crispy-Salmon-in-skillet.jpg', 3, 10, 13, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}]', '[{"ingredients":["4 salmon fillets (, skin-on (Note 1))","1 tsp olive oil (or other cooking oil)","1 tsp salt (, cooking/kosher (3/4 tsp table salt, Note 2))","1/2 tsp black pepper"]},{"ingredients":["2 tbsp olive oil (or vegetable oil)"],"purpose":"Cooking:"},{"ingredients":["lemon wedges"],"purpose":"Serving:"}]', '[{"title":"Dry skin","description":"Pat the skin of the salmon very well with a paper towel until dry. If time permits, place the salmon skin side up in the fridge for 1 hour (uncovered,) to dry it out even more.","images":[],"step":1},{"title":"Season","description":"Drizzle flesh side with half the oil (just a tiny bit) and rub over skin. Sprinkle with half the salt and pepper. Turn fillet over and repeat. Do not do this step until just before cooking.","images":[],"step":2},{"title":"Heat oil","description":"Put enough oil in a large non stick skillet so it fully covers the base. Heat on medium high until it shimmers (but not smoking).","images":[],"step":3},{"title":"Skin side down","description":"Place salmon in the skillet skin side down, then immediately turn the head down to medium.","images":[],"step":4},{"title":"Press down","description":"Using a spatula or something similar, press down on each salmon for 10 seconds so the skin is pushed flat against the skillet and \"sets\" its form. If you can do at least two at a time that is ideal.","duration":0.16666666666666666,"images":[],"step":5},{"title":"Cook 7 minutes","description":"Cook for 7 minutes, or until the salmon is cooked 3/4 of the way through (you will see the colour changing up the side of the salmon) and the skin is crispy.","duration":7,"images":[],"step":6},{"title":"90 sec on flesh side","description":"Flip the salmon to skin side is up and cook for a further 90 seconds.","images":[],"step":7},{"description":"Final skin blast! (My secret tip) Flip the salmon again to skin side down, turn the heat up to medium high and cook the skin side again for 60 seconds, just to give it a final blast of heat to reinforce crispiness!","duration":1,"images":[],"step":8},{"description":"Serve skin side UP to protect the crispy skin. Fish skin will only stay crispy while it''s hot, so serve immediately! Pictured in post with creamy Lemon & Herb Risotto which acts as a side dish and semi-sauce (super easy no-stir recipe!).","images":[],"step":9}]', '["fish"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["fish-recipes","mains","other","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a6130927a800', 'en', 'US', 'Celebration Salmon Salad with Yoghurt Ranch Dressing', 'Recipe VIDEO above. A show off salad for gatherings! Hot smoked salmon adds a touch of special to this salad that''s loaded with fabulous flavours and textures. You''ll love the dressing! Recipe written for 5 servings, double batch pictured in post, shown as a main dish for a buffet.', 'https://www.recipetineats.com/tachyon/2019/12/Celebration-Salmon-Salad_3.jpg', 30, 5, 35, 5, '[{"id": "ing_salmon_fillets", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.5, "unit": "bottle of 500ml"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.6, "unit": "tub of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_chives", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_dill", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_lemon", "quantity": {"value": 0.09, "unit": "net of 500g"}}, {"id": "ing_kale", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_peaches", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 30.0, "unit": "head"}}, {"id": "ing_fennel", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_snow_pea_sprouts", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_parmesan", "quantity": {"value": 0.375, "unit": "pack of 200g"}}]', '[{"ingredients":["500g / 1 lb hot smoked salmon (, store bought, any flavour (Note 1))"]},{"ingredients":["1 small red onion (, halved then finely sliced)","1 cup (250 ml) apple cider vinegar ((enough to just cover onion), sub white wine vinegar)","1 tsp salt","2 tsp white sugar"],"purpose":"Quick Pickled Onion:"},{"ingredients":["2 cups Greek yoghurt (, full fat recommended)","3 tbsp extra virgin olive oil","1 garlic clove (, minced)","1/4 cup fresh chives, finely chopped","1/4 cup fresh dill, finely chopped","1/2 tsp EACH onion powder, garlic powder, salt, black pepper","1 1/2 tsp white sugar","3 tbsp lemon juice"],"purpose":"Yoghurt Ranch Dressing:"},{"ingredients":["4 cups (packed) kale (, torn into bite size pieces (Note 2))","2 tsp extra virgin olive oil","Pinch of salt"],"purpose":"Marinated Kale:"},{"ingredients":["2 pieces fruit - nectarines, peaches, grapefruit or blood oranges (get whatever''s ripe and juicy, or sub normal oranges)","10 cups cos lettuce / romaine (torn or cut into bite size pieces (Note 3))","1 small fennel (, shaved (0.5 mm / 1/5\" thickness) or finely sliced)","1 handful snow pea sprouts (can omit)","3/4 cup (75g) parmesan (, shredded (Note 4))"],"purpose":"Salad:"}]', '[{"title":"Flake salmon","description":"Use two forks to flake salmon into large chunks.","images":[],"step":1},{"title":"Dressing","description":"Mix the Yoghurt Ranch Dressing ingredients in a bowl. Adjust olive oil + lemon juice to taste. Leave 20 minutes.","images":[],"step":2},{"title":"Pickle Onions","description":"Place ingredients in a bowl, toss to coat. Set aside for 1 hour+ or until onion is softened (if in a rush, make sure the onion is finely sliced = faster pickle). Drain.","images":[],"step":3},{"title":"Marinated Kale","description":"Place kale in a large bowl, drizzle with oil then sprinkle with salt. Use your fingers to massage the oil onto the leaves - you want to ensure every part of the kale is coated in oil. Set aside for 30 minutes or until kale is softened.","duration":30,"images":[],"step":4},{"description":"Nectarines/peaches option- halve then finely slice.","images":[],"step":5},{"title":"Grapefruit/blood orange option","description":"segment per video. Squeeze all remaining juice out of the membrane after segmenting, mix into dressing.","images":[],"step":6},{"description":"Place lettuce, kale, fennel, 1/2 cup onion in bowl. Drizzle with about 1 cup dressing and 1/3 cup parmesan. Toss well to coat. Taste, add more parmesan or salt if you want, or more dressing.","images":[],"step":7},{"description":"Pile half dressed lettuce onto serving platter. Flake over half the salmon and half the fruit. Scatter with more red onion.","images":[],"step":8},{"description":"Top with remaining lettuce, salmon, fruit and onion (might not use all onion).","images":[],"step":9},{"description":"Drizzle with some dressing (might not use all, serve remainder on side). Scatter over snow pea sprouts, sprinkle with remaining parmesan. Place on table and let everyone help themselves!","images":[],"step":10}]', '["fish","milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["fish-recipes","salad-recipes-main-course","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1d58f936c9a7', 'en', 'US', 'Salmon Patties', 'Recipe VIDEO above. Made with either fresh salmon OR canned salmon, these are so moreish! Golden crispy on the outside, savoury and juicy on the inside, these are baked, not fried, so they''re healthier and there''s less cleaning up. Makes 12 patties.', 'https://www.recipetineats.com/tachyon/2018/02/Salmon-Patties_8.jpg', 15, 20, 35, 4, '[{"id": "ing_bread", "quantity": {"value": 0.188, "unit": "loaf"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_salmon_fillets", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_dill", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}]', '[{"ingredients":["1 cup Panko breadcrumbs (Note 1 for subs)","1 small onion ((or 1/2 large), grated)","1 garlic clove (, finely minced)","400 g/ 14 oz cooked fresh salmon OR canned red or pink salmon (, drained (Note 2))","2 shallots / scallions / green onions (, finely sliced)","1/3 cup fresh dill (, roughly chopped (or 1 tsp dried herbs of choice))","2 eggs","1/2 cup parmesan (, grated or shredded)","1/4 tsp each salt and pepper"]},{"ingredients":["2 tbsp vegetable oil","Oil spray"],"purpose":"Cooking:"}]', '[{"description":"Preheat oven to 220C/430F standard (200C fan)","images":[],"step":1},{"description":"Place breadcrumbs in a bowl. Grate over onion, including juices. Mix onion into breadcrumbs, ensuring all breadcrumbs are soaked. (Note 3)","images":[],"step":2},{"description":"Add remaining ingredients except salmon. Mix well.","images":[],"step":3},{"description":"Add salmon. Stir through gently, leaving flakes of salmon (rather than vigorously mixing salmon into tiny pieces).","images":[],"step":4},{"description":"Scoop up 1/4 cup mixture (level, packed standard ice cream scoop, see Video). Form round patties about 1.5 cm/ 2/3\" thick and set aside.","images":[],"step":5},{"description":"Drizzle oil all over tray. Place in oven for 2 minutes until hot - oil will spread over tray. Tilt tray to spread if needed.","duration":2,"images":[],"step":6},{"title":"Place patties on tray","description":"DO NOT press down (makes them stick on tray). Spray surface with oil spray.","images":[],"step":7},{"description":"Bake 15 minutes. Flip, spray surface with oil spray, bake 5 minutes.","images":[],"step":8},{"description":"Serve with sour cream or yoghurt on the side for dipping / dolloping, and extra fresh dill if desired.","images":[],"step":9},{"description":"I served mine with cauliflower puree and Yoghurt Slaw - healthy side options! (Note 3)","images":[],"step":10}]', '["egg","fish","milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","fish-recipes","main-dishes","quick-and-easy","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_70e10b2bd897', 'en', 'US', 'Salmon Alfredo Pasta', 'A creamy Alfredo pasta tossed with flakes of hot smoked salmon (or plain cooked salmon). Make sure you follow the steps to toss the sauce and pasta with some of the pasta cooking water - it makes all the difference to create a luscious creamy sauce using only 1/2 cup of cream!', 'https://www.recipetineats.com/tachyon/2016/01/Salmon-Alfredo_7.jpg', 10, 15, 25, 3, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.454, "unit": "pack of 500g"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 0.925, "unit": "pack of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 6.0, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}]', '[{"ingredients":["8 oz / 250g dried fettuccine","3 tbsp / 50g unsalted butter","1 small shallot (US) / eschallot (Australia), very finely minced (Note 1)","½ cup / 125 ml heavy cream (Note 2)","¾ cup / 185 ml freshly grated Parmigiano Reggiano or parmesan (Notes 3 and 4)","¼ teaspoon salt","Good grind of black pepper","6-7 oz / 180 - 200g hot smoked salmon fillet (, flaked (Note 5))"]},{"ingredients":["Fresh parsley (optional)","Extra Parmigiano Reggiano"],"purpose":"Garnish"}]', '[{"description":"Bring a large pot of salted water to boil. Add the fettuccine and cook until al dente (still firm but just cooked through). (Note 6)","images":[],"step":1},{"description":"Meanwhile, melt the butter in a deep fry pan over medium high heat. (Note 7)","images":[],"step":2},{"description":"Add the shallots and sauté for 2 minutes or until tender.","duration":2,"images":[],"step":3},{"description":"Add the cream and bring to boil. Turn heat down to medium low and simmer for 3 minutes.","duration":3,"images":[],"step":4},{"description":"Remove the fry pan from the heat and stir through the Parmigiano Reggiano, salt and pepper until the sauce is smooth.","images":[],"step":5},{"description":"TAKE OUT 1/2 cup of pasta water PLUS scoop out an extra mug (extra, just in case). Then drain the pasta in a colander.","images":[],"step":6},{"description":"Transfer the pasta and 1/2 cup of reserved pasta water into the fry pan with the sauce. Add salmon. Return the fry pan to the stove over medium heat. Toss very gently to coat the pasta in the sauce and allow the sauce to emulsify (Note 6) for 1 1/2 - 2 minutes, until the sauce coats the pasta - there should be no sauce pooled at the bottom of the skillet. (Note 7)","images":[],"step":7},{"description":"Remove from the stove and serve immediately, garnished with extra Parmigiano Reggiano and fresh parsley, if using.","images":[],"step":8}]', '["fish","milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["dinner-tonight","fish-recipes","italian-recipes","main-dishes","pasta-recipes","quick-and-easy","salmon-recipes","seafood-recipes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c4459ff530c5', 'en', 'US', 'Crispy Chinese Rice Paper Wrapped Fish (5 Ingredients)', '5 ingredient magic - on a budget! (I get salt and pepper for free ;) ) I saw this on a Chinese cooking show years ago. Make these bite size like I have - or larger by using overlapping pieces of rice paper to encase the fish.', 'https://www.recipetineats.com/tachyon/2015/10/Crispy-Chinese-Rice-Paper-Wrapped-Fish_680px_Featured.jpg', 20, 10, 30, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.499, "unit": "kg"}}, {"id": "ing_chinese_five_spice", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_rice", "quantity": {"value": 15.0, "unit": "pack"}}, {"id": "ing_oil", "quantity": {"value": 2.0, "unit": "bottle"}}]', '[{"ingredients":["1.1 lb / 600 g firm white fish fillets (Note 1)","2 tsp Chinese Five Spice Powder (Note 2)","3/4 - 1 tsp salt","Black pepper","1/4 cup coriander/cilantro leaves","15 to 18 rice paper rounds (, 22cm/9\" diameter (Note 3))","2 to 3 tbsp cooking oil"]}]', '[{"description":"Cut the fish into 2\"/5cm long x 1\"/3cm wide pieces, about 16 pieces. (Note 4)","images":[],"step":1},{"description":"Combine Chinese Five Spice Powder, salt and pepper.","images":[],"step":2},{"description":"Sprinkle with with spice mix.","images":[],"step":3},{"description":"Fill a large bowl with hot tap water. Dunk the rice paper into the water for 3 seconds, then transfer it to a work surface. (Note 5)","duration":0.05,"images":[],"step":4},{"description":"Place a piece of fish at the bottom of the rice paper, per the photo below. Top with 2 coriander leaves, then roll up to enclose the fish with the rice paper. Repeat with remaining fish.","images":[],"step":5},{"description":"Heat oil in a skillet over medium high heat. Add the fish and cook for 2 minutes or until dark golden brown and crispy. Turn and cook the other side. Repeat with remaining fish (I cook them in 2 batches).","duration":2,"images":[],"step":6},{"description":"Transfer to a paper lined plate.","images":[],"step":7},{"description":"Serve immediately, while hot and crispy!","images":[],"step":8}]', '["fish"]', '["gluten_free","high_protein"]', '{"mealType":["main_course"],"cuisine":["Chinese"],"categories":["dinner-tonight","fish-recipes","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a9bfa23c9301', 'en', 'US', 'Haloumi fries', 'Recipe video above. These can be baked, air-fried or shallow fried (best, most golden and crunchy and fastest). It''s the best haloumi recipe I know - Haloumi Fries! Think - french fries, but a whole lot more interesting and faster to make. Super crunchy outside (thanks panko!) and warm, salty haloumi cheese insides. Excellent snack, starter for a Mediterranean menu or passing around at parties.PS The garlic dipping sauce is the perfect dunking sauce.', 'https://www.recipetineats.com/tachyon/2023/08/Haloumi-Fries_6.jpg', 15, 10, 25, 5, '[{"id": "ing_cheese", "quantity": {"value": 360.0, "unit": "block of 250g"}}, {"id": "ing_oil", "quantity": {"value": 300.0, "unit": "bottle"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_italian_herbs", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 0.188, "unit": "loaf"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.15, "unit": "tub of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_lemon", "quantity": {"value": 0.005, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.005, "unit": "L"}}]', '[{"ingredients":["360g / 12oz haloumi cheese blocks (, 2 x 180g/6 oz blocks (Note 1))","2 cups canola oil (or other natural oil)","2 large eggs (, whisked)"]},{"ingredients":["1/2 cup plain/all purpose flour","1 tbsp Italian herbs (Note 2)","1 tbsp smoked paprika (sub ordinary paprika)","1 tsp ground white pepper (sub black pepper)"],"purpose":"Flour dredge:"},{"ingredients":["1 cup panko breadcrumbs (- or ordinary breadcrumbs (Note 3))","1/4 tsp cooking/kosher salt"],"purpose":"Crumbing:"},{"ingredients":["1/2 cup plain Greek yoghurt","1 garlic clove (, finely grated using a microplane)","1/2 tsp lemon juice (sub white vinegar)","1 tsp extra virgin olive oil","1/4 tsp cooking/kosher salt"],"purpose":"Yoghurt garlic dipping sauce:"}]', '[{"title":"Garlic dipping sauce","description":"Mix ingredients in a bowl and set aside for at least 20 minutes to let the flavours develop.","images":[],"step":1},{"description":"Cut the haloumi into fries around 1.5cm / 0/6\" thick. The length will depend on the shape of your haloumi. I cut mine into 5 slices lengthwise, then each into half which makes uniform fries, and get 20 pieces.","images":[],"step":2},{"title":"Dry","description":"Pat halloumi mostly dry using tea towels.","images":[],"step":3},{"title":"Prep","description":"Using 3 bowls large enough to toss the halloumi, put the eggs in one bowl, mix Flour Dredge in another and mix Crumbing ingredients in a third.","images":[],"step":4},{"title":"Crumb","description":"Dip a haloumi fry in flour, shake off excess. Dip in egg, allow excess to drip off. Coat in breadcrumbs, pressing to adhere, then place on tray. PRO: Do 2 at a time. 🙌🏻 Toss haloumi in breadcrumbs (by tossing the bowl) so you don''t have to touch. 🙌🏻","images":[],"step":5},{"description":"Heat oil in a medium sauce pan over high heat until it reaches 180°C/350°F (Note 4).","images":[],"step":6},{"description":"Fry 5 haloumi sticks at a time for 1 1/2 minutes. Drain on a paper towel lined tray. Repeat with remaining haloumi.","images":[],"step":7},{"title":"Air fry and baking","description":"see Note 5.","images":[],"step":8},{"description":"Serve hot with yoghurt garlic dipping sauce!","images":[],"step":9}]', '["egg","gluten","milk"]', '["high_protein","vegetarian"]', '{"mealType":["snack"],"cuisine":["Greek","Western"],"categories":["deep-fried-recipes","greek-recipes","mediterranean-recipes","snacks"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bea738cf7e02', 'en', 'US', 'Perfect Crispy French Fries', 'Recipe video above. If you want French fries that stay crispy for a good 15 minutes - even after they''ve gone cold(!) - this is the recipe for you. Adapted from a ground-breaking method documented in The Food Lab by the legendary Kenji López-Alt, read in post for why this recipe works and makes the best French fries!I really hope you try this one day so you can experience the awesomeness of homemade French fries. McDonald''s is incomparable!', 'https://www.recipetineats.com/tachyon/2022/09/Crispy-Fries_8.jpg', 10, 25, 35, 4, '[{"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_chilli_flakes", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_shaker_fries_seasoning", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_rosemary", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}]', '[{"ingredients":["1 kg / 2 lb (3 - 4) floury potatoes ( (Note 1, Aus: Sebago/dirt aka brushed, US: Russet/Idaho, UK: Maris Piper, King Edward))","2 tbsp white vinegar (Note 2)","1 tbsp cooking salt / kosher salt (Note 3)","1 litre/quart canola/vegetable oil"]},{"ingredients":["Salt - table salt or sea salt flakes","Shaker fries seasoning","Rosemary salt","Nori salt (coming soon)"],"purpose":"Seasoning (choose):"}]', '[{"title":"Cut","description":"Peel the potatoes. Cut into 6 mm / 1/4\" French fries using a serrated knife. (Note 4)","images":[],"step":1},{"description":"Keep cut fries submerged in a bowl of water to prevent them from going brown while you cut the remainder. (No need for actual soaking beyond this.)","images":[],"step":2},{"title":"Rinse","description":"Transfer potatoes to a colander and rinse under tap water for 15 - 20 seconds.","duration":0.2916666666666667,"images":[],"step":3},{"title":"Simmer","description":"Place fries in a large pot with 2 litres/quarts of cold tap water, vinegar and salt. Bring to a boil over high heat then immediately reduce stove to low so the surface is rippling gently (Note 5), not big bubbles. Cook for 10 minutes then carefully remove using a slotted spoon into a colander (do not tip into colander, fries will break).","duration":10,"images":[],"step":4},{"title":"Dry 5 min","description":"Spread the fries on 2 tea towel lined trays. Leave to steam dry for 5 minutes.","duration":5,"images":[],"step":5},{"title":"Pot","description":"Pour 3 cm / 1.2\" of oil in a pot that is at least 10cm/4\" high (⚠️for safety, need at least 7 cm / 3\" from oil surface to rim of pot, Note 6)","images":[],"step":6},{"description":"Separate the fries into 3 Batches (for cooking).","images":[],"step":7},{"description":"Heat oil to 205°C/400°F over medium high heat.","images":[],"step":8},{"title":"⚠️10 sec pause (Note 7)","description":"Lower 1/3 of Batch 1 fries into the oil using a slotted spoon. WAIT 10 seconds, add another 1/3 of the fries, wait 10 seconds, then add the remaining Batch 1 fries.","images":[],"step":9},{"title":"50 sec fry","description":"Fry for 50 seconds, moving them around once or twice. Then remove with a slotted spoon onto 2 paper towel lined trays, spread out in a single layer. The fries will still be white and floppy.","duration":0.8333333333333334,"images":[],"step":10},{"description":"Repeat Fry #1 with Batches 2 and 3, ensuring the oil is back at 205°C/400°F before cooking.","images":[],"step":11},{"title":"30 min cool","description":"Leaves fries to cool for 30 minutes.","duration":30,"images":[],"step":12},{"title":"Line a large bowl with paper towels","description":"for draining and tossing.","images":[],"step":13},{"title":"Fry #2","description":"Heat oil to 205°C/400°F. Fry half the French fries for 4 minutes, moving them around twice, or until golden brown and crispy. Drain in the lined bowl, then repeat with remaining fries.","duration":4,"images":[],"step":14},{"description":"Season & serve!","images":[],"step":15},{"description":"Sprinkle fries with salt or seasoning or choice. (Note 8) Toss and serve!","images":[],"step":16},{"description":"Fries will stay crispy even once cool. See note for large batch cooking tip.","images":[],"step":17}]', '[]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["deep-fried-recipes","potato-recipes","potatoes","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d2b5e5e07c97', 'en', 'US', '"Sizzling Beef" Steak Fried Rice', 'Recipe video above. This is a bit special because it''s rare to see fried rice made with juicy bites of steak! With marinated, tenderised beef pieces "sizzled" until golden (aka - your favourite Chinese restaurant Sizzling Beef!), this is an excellent recipe to make with economical cuts like sizzle steak, minute steak, and pre-cut stir fry strips. The beef is caramelised on the outside, and tenderised so it doesn''t overcook. It''s so soft and velvety, you will be shocked!', 'https://www.recipetineats.com/tachyon/2024/09/Sizzling-Beef-Fried-Rice-54326a.jpg', 15, 10, 85, 4, '[{"id": "ing_beef_steak", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.01, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_sugar", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.009, "unit": "tub of 200g"}}, {"id": "ing_oil", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_green_onion", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_white_rice", "quantity": {"value": 0.52, "unit": "kg"}}, {"id": "ing_green_beans", "quantity": {"value": 200.0, "unit": "pack"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["300g/ 10 oz rump beef steak (US: top sirloin)"]},{"ingredients":["1/2 tsp dark soy sauce (Note 2)","2 tsp oyster sauce (Note 3)","2 tbsp water","1 garlic clove","1/4 tsp sugar (any)","3/8 tsp baking soda (bi-carbonate soda) (ie 1/4 teaspoon HEAPED, Note 4)"],"purpose":"Tenderising beef marinade:"},{"ingredients":["2 1/2 tbsp canola or peanut oil (, separated)","4 green onion stems (, cut into 1.25 cm / 1/2\" lengths, white part separated from green part)","2 garlic cloves (, finely minced)","520g/ 1 lb (4 cups) cooked, day-old long grain white rice, (or other plain rice), refrigerated overnight (Note 5)","200g/7 oz green beans (, cut into 1.25 cm pieces (~ 2 heaped cups) (Note 6))"],"purpose":"Fried rice:"},{"ingredients":["2 tbsp fish sauce (Note 7)","1 1/2 tbsp oyster sauce (Note 3)","1/2 tsp sugar (any type)"],"purpose":"Fried rice sauce:"},{"ingredients":["2 eggs","1/2 tsp sesame oil","Pinch of salt and pepper (preferably white, but black ok)"],"purpose":"Scrambled egg:"}]', '[{"description":"Marinate beef 1 hour. Cook beef in 2 tbsp oil on high in a large pan until lightly seared, add white part of green onion and beans, cook until beef is caramelised, adding garlic towards the end. Add rice and sauce, toss well. Scramble egg on side of pan, toss through green part of green onion. Eat!","images":[],"step":1},{"title":"Marinade & tenderise beef","description":"Mix the marinade ingredients in a bowl then add the beef and toss well. Set aside for 1 hour (up to 24 hours), or the time specified in Note 1.","images":[],"step":2},{"title":"Sauce","description":"Mix the Sauce ingredients. Set aside.","images":[],"step":3},{"description":"Whisk the Scrambled Egg ingredients. Set aside.","images":[],"step":4},{"title":"Sizzle beef","description":"Heat 2 tablespoons of oil in a large non-stick pan over high heat (mine is 30cm/12\", see Note 8 for why no wok). Add the beef and cook for 2 minutes until the surface is sealed. Add the garlic, white part of the green onion and beans. Cook for another 1 minute until the beef is caramelised, stirring constantly so it doesn''t catch and burn.","duration":2,"images":[],"step":5},{"title":"Rice and sauce","description":"Add the rice and sauce. Toss for a good 1 1/2 - 2 minutes to give the rice a chance to get toasty.","images":[],"step":6},{"title":"Scramble egg","description":"shove all the rice to one side and shif the pan so the empty space is set over the flame. Add the remaining 1/2 tablespoon oil and spread. Pour the egg, swirl, give it 10 seconds to partially set then do lazy swirls with your spatula to scramble it softly. Once mostly cooked, quickly (but gently!) toss it though the rice.","images":[],"step":7},{"title":"Serve","description":"Add the green part of the green onion and toss through. Divide between bowls and enjoy!","images":[],"step":8}]', '["egg","fish","gluten","peanuts","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese","Thai-ish"],"categories":["fried-rice","quick-and-easy","rice-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_884818c11be3', 'en', 'US', 'Crispy Zucchini Fritters', 'Recipe video above. Zucchini fritters made extra crispy and extra tasty with the addition of parmesan! Crispy on the outside, and moist but not soggy on the inside. Love how these are light on batter - just enough to hold it together. Serves 2 as a light-ish meal.', 'https://www.recipetineats.com/tachyon/2018/08/Zucchini-Fritters_9.jpg', 15, 12, 27, 6, '[{"id": "ing_zucchini", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_green_onion", "quantity": {"value": 0.04, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.017, "unit": "tub of 150g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.04, "unit": "bunch"}}]', '[{"ingredients":["500 g/1 lb zucchini (2 medium ~ 23cm/9\" long)","1 tsp salt"],"purpose":"Zucchini:"},{"ingredients":["1 large egg","2 green onions (, halved then finely sliced)","1/4 cup parmesan (, grated (fresh or store bought))","1 garlic clove (, large, minced)","1/2 cup / 75 g flour","1/2 tsp baking powder","Pinch of pepper","4 tbsp olive oil (, separated)"],"purpose":"Batter:"},{"ingredients":["Yoghurt or sour cream","More chopped green onions"],"purpose":"For Serving:"}]', '[{"description":"Grate zucchini using a box grater. Grate on the diagonal so you get long strands.","images":[],"step":1},{"description":"Place in a bowl and sprinkle with salt. Mix, then leave for 10 minutes+.","duration":10,"images":[],"step":2},{"description":"Squeeze out excess water using hands (or bundle up tea towel) then place zucchini in a bowl.","images":[],"step":3},{"description":"Preheat oven to 200F/100C (for keeping fritters warm). Place rack on tray (helps keep crispy)","images":[],"step":4},{"description":"Add egg, green onions, parmesan and garlic into the zucchini bowl. Mix to combine.","images":[],"step":5},{"description":"Scatter over flour and baking powder (don''t dump in one spot), and add pinch of pepper. Mix until flour is just incorporated - batter should be thick but soft (see video, Note 1).","images":[],"step":6},{"description":"Cooking:","images":[],"step":7},{"description":"Heat 2 tbsp oil in a non stick pan over medium high heat (or medium if stove is strong). Drop 1/4 cup batter in the pan (ice cream scoop is perfect). Do 3 or 4 mounds.","images":[],"step":8},{"description":"Flatten lightly with spatula to about 1cm / 4/5\" thick.","images":[],"step":9},{"description":"Cook for 3 minutes until underside is deep golden (adjust heat if browning too quickly). Flip and cook the other side for 3 minutes. Transfer to tray and place in oven to keep warm.","duration":3,"images":[],"step":10},{"description":"Repeat with remaining batter.","images":[],"step":11},{"description":"Serve immediately with a dollop of yoghurt or sour cream and garnish of extra green onions if desired.","images":[],"step":12}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["dinner-tonight","fritters-tots-and-similar","quick-and-easy","vegetarian-recipes","zucchini-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_73a74064cc59', 'en', 'US', 'Vanilla Buttercream Frosting', 'Recipe video above. A classic vanilla buttercream that’s creamy and fluffy, and perfect for frosting cakes, cupcakes, and everything in between! Vanilla is such a classic flavour, this frosting is a terrific all-rounder that goes with almost any type of cake, though I especially love it with my Vanilla Cake and Vanilla Cupcakes.Makes enough frosting for 2 layer 20 cm / 8" cake (top, sides and inside), top only of slab cake (23 x 33cm / 9 x 13"), 12 cupcakes piped ~ 3.5cm / 1.5" high, 18 cupcakes spread on thickly. Click on servings and slide to scale recipe up or down.-------------------After a less sweet frosting? Use my Secret Less-Sweet Fluffy Frosting. The texture is exactly like buttercream and it''s also 100% smooth (no matter what anyone tells you, buttercream will never, ever be 100% smooth, you will always have faint graininess from icing sugar, it''s just the way it is!).', 'https://www.recipetineats.com/tachyon/2026/04/Vanilla-frosting-close-up.jpg', 10, 0, 10, 3, '[{"id": "ing_butter", "quantity": {"value": 250.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.3, "unit": "bottle of 50ml"}}, {"id": "ing_milk", "quantity": {"value": 2.0, "unit": "L"}}]', '[{"ingredients":["250g / 2 sticks unsalted butter (, softened)","500g / 1 lb soft icing sugar / powdered sugar (, SIFTED (Note 1))","3 tsp vanilla extract (or upgrade to vanilla bean paste)","2 - 4 tbsp milk (or cream, to adjust thickness, if needed)"]}]', '[{"title":"Cream butter","description":"Beat butter with paddle attachment in stand mixer for 3 minutes on high until it changes from yellow to almost white, and it becomes fluffy and creamy. (Note 2)","duration":3,"images":[],"step":1},{"description":"Add icing sugar / powdered sugar gradually in 3 lots, beating slowly (to avoid a powder storm!) then once mostly incorporated, beat on high for a full 3 minutes until fluffy.","images":[],"step":2},{"title":"Finish","description":"Add vanilla and milk, then beat for a further 30 seconds. Use milk only if needed to make it lovely and soft but still holds its form (eg for piping). Use immediately to frost on cooled cakes and cupcakes! I especially love vanilla buttercream with a beautiful soft Vanilla Cake (pictured in post) or on Vanilla Cupcakes.","images":[],"step":3},{"title":"Remove unsightly air bubbles","description":"Use a stick blender! Just blitz it around the bowl and watch the bubbles disappear. :)","images":[],"step":4},{"title":"Make it pure white","description":"Vanilla buttercream is not pure white because of the butter and vanilla extract (which is brown). To make it pure white (like wedding cake white!) use a white food colouring (like this one). To make it whiter without using colouring, use a pale yellow butter (like Lurpak). You can also use a clear vanilla extract if you can find a good one which I have yet to find (most are imitation essence).","images":[],"step":5}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["dessert-recipes","frosting-and-icing"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_760ece79e9bf', 'en', 'US', 'Chocolate Ganache', 'Recipe video above. Made with just cream and chocolate, ganache is a baking staple with many applications that adds a spot of instant luxury! A pourable fudge sauce when warm, for glazing cakes or making drip decorations, to a spreadable and pipable frosting when cool, or for making truffles when cold (use this recipe for truffles). The possibilities are endless - here''s just a few ideas!While it is simple to make, things can go wrong if made without care. So follow the directions and read the Key Points below.Rule of thumb - The lighter the chocolate, the softer it is, so the less cream you use.Makes 2 cups / 500 ml - enough to frost 1 layer round 20 - 23cm / 8-9" cake (top and sides), smear onto 12 cupcakes, or sauce for 6 to 8 sundaes.2 layer cakes (filling, sides and top) - double the recipe (click on servings and slide). Slightly more than you need, but better to be safe than sorry!', 'https://www.recipetineats.com/tachyon/2020/11/Chocolate-Ganache_4.jpg', 5, 2, 7, 2, '[{"id": "ing_chocolate", "quantity": {"value": 250.0, "unit": "block of 100g"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_chocolate", "quantity": {"value": 250.0, "unit": "block of 100g"}}, {"id": "ing_chocolate", "quantity": {"value": 250.0, "unit": "block of 100g"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_chocolate", "quantity": {"value": 250.0, "unit": "block of 100g"}}]', '[{"ingredients":["250g/ 8oz dark chocolate or semi-sweet chocolate block (up to 50% cocoa, Note 1)","1 cup thickened / heavy cream (, pure cream or whipping cream (Note 2))"],"purpose":"Dark Chocolate Ganache:"},{"ingredients":["375g/ 12 oz milk chocolate block (Note 3)","1/2 cup thickened / heavy cream (, pure cream or whipping cream (Note 2))"],"purpose":"Milk Chocolate Ganache:"},{"ingredients":["400g / 14 oz white chocolate block (Note 4)","1/3 cup + 1 tbsp thickened / heavy cream (, pure cream or whipping cream (Note 2))"],"purpose":"White Chocolate Ganache:"},{"ingredients":["See Chocolate Truffles recipe (less cream for firmer ganache)"],"purpose":"Chocolate Truffles:"}]', '[{"description":"Chop chocolate:","images":[],"step":1},{"description":"Using a sharp knife or serrated knife, finely chop the chocolate. Then scrape it all into a heatproof bowl - including all those little powdery shards!","images":[],"step":2},{"title":"Heat cream","description":"Place cream in a small saucepan over heat or in a heatproof jug to microwave. Heat until hot and steaming but DO NOT let it boil - it might cause the chocolate to split or go grainy. (Note 6)","images":[],"step":3},{"title":"Pour cream over chocolate","description":"Pour hot cream over chocolate, then spread chocolate out so it''s as evenly covered by cream as possible. Cream will not fully cover white or milk chocolate, that''s OK.","images":[],"step":4},{"title":"Wait 10 minutes","description":"Leave for 10 minutes. Do not cover (Note 7).","duration":10,"images":[],"step":5},{"title":"Stir until smooth","description":"Using a rubber spatula or spoon, stir until cream and chocolate are incorporated and it''s silky smooth. (Note 8 about lumps)","images":[],"step":6},{"title":"Milk & white chocolate only","description":"Because there is less cream, the chocolate may not fully melt. In which case, micrwoave for 20 seconds, stir gently, then microwave again for 10 seconds and stir - this should be enough to fully melt the chocolate. (Note 5)","duration":0.3333333333333333,"images":[],"step":7},{"title":"Troubleshooting","description":"If your ganache splits (ie. oil streaks) or is grainy, or it''s too thick or thin, see above in post for how to fix these problems.","images":[],"step":8},{"title":"Cooling","description":"If cooling your ganache (to spread, pipe or whip), cool it uncovered for 30 minutes. Then cover with cling wrap and press so it contacts the surface (so you don''t get a skin forming) and continue to cool.","duration":30,"images":[],"step":9},{"title":"Pourable / dipping sauce / pour glaze","description":"allow to cool for 15 minutes on the counter until it''s still runny but pourable. Use as required - pour over cakes as a thick chocolate glaze, over sundaes, into bowls to use for dipping, or to make drip decorations.","duration":15,"images":[],"step":10},{"title":"Spreadable frosting","description":"cool to a spreadable peanut butter consistency. Cool 30 minutes on the counter then EITHER 4 hours in the fridge, stirring every now and then for even cooling, OR refrigerate overnight and then leave to soften on counter for 15 - 20 minutes.","duration":17.5,"images":[],"step":11},{"title":"Whipped Ganache","description":"Place bowl and whisk attachment in fridge for 20 minutes. Place ganache in bowl then whip on high for 2 minutes until it changes to a pale brown colour and it''s fluffier. Smear or pipe onto cakes and cupcakes.","duration":20,"images":[],"step":12},{"title":"Truffles","description":"cool overnight in the fridge until firm. Use this Chocolate Truffles recipe.","images":[],"step":13},{"title":"More ideas and uses","description":"Click here: What to do with chocolate ganache !","images":[],"step":14}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["dessert-recipes","frosting-and-icing"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0263f552bf04', 'en', 'US', 'German Pork Knuckle (Schweinshaxe) - Slow Roasted with Crispy crackling!', 'Recipe video above. Realistically, one knuckle will serve 2. But for wow factor, serve one per person!!!While producing tender Pork Knuckle flesh is straightforward enough, very few recipes truly nail the crispy crackling. So here is a recipe that finally does! The skin is crispy all over and fabulously bubbly, shattering into a thousand porky shards when you bite instead of breaking your teeth on hard, leathery patches!Meanwhile, the flesh is seasoned with traditional flavourings and the Pork Knuckle is served with an authentic, dark and malty German beer gravy. It''s every carnivore''s dream come true!', 'https://www.recipetineats.com/tachyon/2021/05/German-Pork-Knuckle_7-main-1.jpg', 20, 180, 200, 2, '[{"id": "ing_pork", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_juniper_berries", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_caraway_seeds", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_fennel_seeds", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_beer", "quantity": {"value": 1.515, "unit": "bottle of 330ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.025, "unit": "pack of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1 x 1.25kg / 2.5lb pork knuckle (Note 1)","2 tbsp white vinegar (Note 2)","3 garlic cloves (, cut into 4 - 6 slivers (Note 3))"]},{"ingredients":["2 tsp salt (, kosher / cooking salt NOT table salt (Note 4))","1 tsp black pepper","1 tsp juniper berries (Note 5)","1 tsp caraway seeds","1 tsp fennel seeds"],"purpose":"Marinade Rub:"},{"ingredients":["2 cups dark German beer (Note 6)","2 cups chicken stock / broth (, low sodium)","1 carrot (, unpeeled, sliced 2cm / 0.8\" thick)","1 onion (, unpeeled, halved, cut into 1.25cm / 1/2\" thick slices)","1 head garlic (, cut in two halves horizontally)","5 juniper berries (Note 5)","2 bay leaves (, preferably fresh otherwise dried)"],"purpose":"Beer Gravy:"},{"ingredients":["2 tsp cornflour/cornstarch","1/2 cup water","1 tsp white sugar","1/4 - 1/2 tsp salt (, kosher / cooking salt NOT table salt (Note 4))"],"purpose":"Gravy thickening and seasoning:"}]', '[{"description":"Preparation and seasoning:","images":[],"step":1},{"title":"Prick skin","description":"Poke lots of small holes all over the pork knuckle’s skin, using a small sharp knife or even a pin (eg. safety pin, sewing pin). Take care not to pierce through the fat into the flesh (Note 7).","images":[],"step":2},{"title":"Vinegar","description":"Brush (or rub) 1 tbsp of the vinegar on the pork flesh only, including inside cracks / crevices and meat under the skin where it meets the flesh (but do not peel skin back). Avoid getting vinegar on the skin.","images":[],"step":3},{"title":"Stud with garlic","description":"Make shallow incisions in the pork flesh (only) with a small knife then stuff with the garlic slivers.","images":[],"step":4},{"title":"Seasoning rub","description":"Pound the rub ingredients in a mortar and pestle until it''s a coarse powder (or use a Nutribullet, spice grinder or similar).","images":[],"step":5},{"title":"Rub seasoning on pork","description":"Rub pork skin with olive oil. Then rub the seasoning mix all over the pork – on the flesh, skin, and getting into all the cracks and crevices.","images":[],"step":6},{"title":"Skewer skin (secret for crispy skin! Note 8)","description":"Pull the skin down to stretch it tight so there''s no creases. Then thread through 2 metal skewers in a \"X\" formation near the base of the knuckle. Pierce through skin 2cm / 0.8\" from the base of the pork knuckle to hold the stretched skin in place.","images":[],"step":7},{"title":"\"Marinate\" overnight","description":"Place pork standing on a plate, then leave uncovered in the fridge overnight (Note 9).","images":[],"step":8},{"description":"Preheat oven to 180°C / 350°F (160°C fan).","images":[],"step":9},{"title":"Beer gravy","description":"Put all beer gravy ingredients in a roasting pan (deep enough to hold all liquids and vegetables).","images":[],"step":10},{"title":"Rack on pan","description":"Place a rack over the pan. Place pork knuckle on rack, sitting upright. (Note 10)","images":[],"step":11},{"title":"Slow roast","description":"Roast for 2 hours 10 minutes, rotating tray half way. (If the liquid in the pan is getting too low and in danger of drying out, top with 1/2 cup of water at a time.) Roast until the internal temperature in the thickest part of meat reaches 85°C / 185°F.","images":[],"step":12},{"description":"Make crispy Pork Knuckle crackling!","images":[],"step":13},{"description":"Remove knuckle from oven, transfer knuckle to a tray.","images":[],"step":14},{"title":"Increase oven","description":"Increase oven to 260°C / 500°F (240°C fan) (Note 11)","images":[],"step":15},{"title":"Brush skin with vinegar","description":"Brush skin with 1/2 the remaining 1 tbsp of vinegar. Place in oven for 30 minutes, rotating tray halfway and brushing with remaining vinegar.","duration":30,"images":[],"step":16},{"description":"Skin should be crispy, dip golden and mostly bubbly.","images":[],"step":17},{"title":"Rest","description":"Rest 15 minutes before serving with German Beer Gravy!","images":[],"step":18},{"description":"German beer gravy:","images":[],"step":19},{"title":"Strain liquid","description":"Strain roasting pan juices into a saucepan. Ideally you should have around 1.5 - 2 cups.","images":[],"step":20},{"title":"Thicken","description":"Bring liquid to a simmer. Mix cornflour and water, then pour into liquid while stirring. Add sugar and salt to taste.","images":[],"step":21},{"title":"Simmer","description":"Simmer for 2 minutes or until it becomes a thin syrup consistency (German beer gravy should not be as thick as normal gravy, but quite runny). If it''s too thick, add a touch of water. Too thin, simmer to reduce - it will thicken. Serve with pork knuckle!","duration":2,"images":[],"step":22}]', '[]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Bavarian","German"],"categories":["german-food","iconic-dishes","mains","pork","pork-recipes","roasts"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_14d5ae9eefad', 'en', 'US', 'How to make clarified butter', 'Clarified butter is regular butter taken one clever step further - melted gently so the milk solids and water separate out, leaving pure, golden butterfat that tastes richer, lasts longer, and handles high heat like a dream. Great to know how to make it because it’s one of those cooking-essential skills that gives you better flavour, better control, and instantly elevates so many dishes!YIELDS 80%, so you can scale this up/down as needed. I''m using a standard Australian butter block (250g).', 'https://www.recipetineats.com/tachyon/2020/10/Clarified-butter-and-ghee_6.jpg', 3, 1, 9, 4, '[{"id": "ing_butter", "quantity": {"value": 250.0, "unit": "block of 250g"}}]', '[{"ingredients":["250g or 2 US sticks 16 (tbsp) unsalted butter (, cut into 1cm / 1\" cubes )"]}]', '[{"title":"Gently melt","description":"Place butter in a jug and microwave in increments until melted (1 - 1½ minutes on high, but watch it carefully so it doesn''t explode!). You could also do this in a saucepan, then pour it into a clear jug.","images":[],"step":1},{"description":"Stand for a couple of minutes until the milky whites settle at the bottom (this is the milk solids) and clarified butter (golden part) sits above it. Scrape off and discard any foamy scum.","images":[],"step":2},{"description":"Pour off the golden clarified butter, taking care to avoid the milky whites remaining. You should get an 80% yield - 250g butter = 195g clarified 2 US sticks (1 cup) = just over 3/4 cup.","images":[],"step":3},{"description":"Use per recipe or keep for later. It will solidify like regular butter and can be re-melted.","images":[],"step":4}]', '["milk"]', '["gluten_free","keto_friendly","vegetarian"]', '{"mealType":["main_course"],"cuisine":["French","Western"],"categories":["good-to-know","sauces"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f1e3e5aa7b02', 'en', 'US', 'How to make Ghee and Clarified Butter (same thing - almost)', 'Recipe video above. Ghee is a form of clarified butter, where butter that is simmered until the water content is evaporated, then the milk solids are strained out to leave just pure gold butter fat with a nutty, intense butter flavour. It''s shelf stable (3 months pantry, 1 year fridge), has a higher smoke point than butter so you can pan fry and roast on high heat without smoking out your house. Chef-secret ingredient, used in many recipes in place of ordinary butter for extra flavour (like Hollandaise Sauce), make pan fried things like Potato Rosti super crispy, and the traditional fat used in Indian curries.', 'https://www.recipetineats.com/tachyon/2020/10/Clarified-butter-and-ghee_6.jpg', 3, 10, 13, 220, '[{"id": "ing_butter", "quantity": {"value": 250.0, "unit": "block of 250g"}}]', '[{"ingredients":["250g / 2 sticks unsalted butter (, cut into 2.5cm / 1\" cubes (or so))"]}]', '[{"description":"Use a small or medium saucepan or small skillet with a silver base so it''s easier to see when milk solids are golden.","images":[],"step":1},{"description":"Put butter in then let it melt over medium-low heat.","images":[],"step":2},{"title":"Leave to simmer for 10 minutes","description":"it will start to foam at about 5 minutes, then at 7 minutes most of the foam will be gone, and by the end the foam should be almost all gone.","duration":10,"images":[],"step":3},{"description":"The ghee is ready when the milk solids that settle on the base of the pan turn golden.","images":[],"step":4},{"description":"Strain through a mesh colander lined with a single sheet of paper towel.","images":[],"step":5},{"description":"Then pour into a jar for storage. Keep in the pantry 3 months (firms to peanut butter consistency), or fridge 1 year (hardens like butter).","images":[],"step":6},{"description":"Use in place of butter or fat for pan frying, roasting, sauces. The smoke point of ghee / clarified butter is 230°C / 450°F which is considerably higher than common oils such as vegetable oil and olive oil, so it won''t smoke and burn.","images":[],"step":7},{"title":"Use with caution in baking recipes","description":"such as cakes and cookies.","images":[],"step":8}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["good-to-know","sauces"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1364d7ddfd44', 'en', 'US', 'How to cook brown rice', 'Recipe video above. The best method and cook time for truly fluffy, perfectly cooked brown rice depends on what type of brown rice you have. Did you know that basmati rice cooks in less than half the time as long grain brown rice?BEFORE YOU START: Determine what rice you have and read the "Before You Start" in the notes below.BIGGEST TIP - skip the absorption method (high risk of gluey) and ignore the packet directions!! Servings: 1 cup uncooked brown rice makes 3 cups cooked rice which will serve 3 people.', 'https://www.recipetineats.com/tachyon/2020/09/Perfectly-Cooked-Brown-Rice_7.jpg', 1, 30, 31, 3, '[{"id": "ing_basmati_rice", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_rice", "quantity": {"value": 150.0, "unit": "pack"}}, {"id": "ing_water", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_rice", "quantity": {"value": 150.0, "unit": "pack"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1 cup brown rice - medium grain, long grain or basmati","8 cups water (Note 1)"],"purpose":"Boil and Drain:"},{"ingredients":["1 1/2 cups short grain brown rice (medium grain ok too)","2 1/2 cups BOILING water (Note 2)"],"purpose":"Baked Rice:"},{"ingredients":["Quick cooking rice (ie par boiled) (- will not work)","Brown jasmine (- not yet tested)"],"purpose":"Will NOT work for / not yet tested:"}]', '[{"title":"Rinsing rice","description":"only required if you purchased from bulk bins. If you rinse, reduce water by 1/4 cup for baked version.","images":[],"step":1},{"description":"Boil and Drain:","images":[],"step":2},{"title":"Boil water","description":"Bring water to a boil in a small pot or large saucepan over high heat.","images":[],"step":3},{"title":"Boil rice","description":"Add rice, then boil rice until just cooked, a tiny bit firmer than you want (it gets softer during Rest step). Use these times as a guide (Note 3):- Medium and long grain rice: 30 minutes- Basmati rice: 12 minutes (1st check) to 14 minutes","images":[],"step":4},{"title":"Drain VERY well (key tip! Note 4)","description":"Drain rice in a colander, shaking the pot well to remove as much water as you can, and shaking the colander to remove excess water from the rice. Pot should steam dry from residual heat.","images":[],"step":5},{"title":"Rest","description":"Return rice to now-dry pot. Put lid on and put it back on the turned off stove. Leave for 10 minutes.","duration":10,"images":[],"step":6},{"title":"Fluff and serce","description":"Fluff rice with fork and serve.","images":[],"step":7},{"description":"Preheat oven to 180°C/350°F (all oven types).","images":[],"step":8},{"title":"Combine rice and water","description":"Pour rice and boiling water into a 20cm/8\" square pan or round casserole pot. Cover with lid or foil.","images":[],"step":9},{"description":"Bake 1 hour 15 minutes.","images":[],"step":10},{"title":"Rest, fluff & serve","description":"Remove from oven, stand 10 minutes then fluff with fork and serve.","images":[],"step":11}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Asian","Indian","Western"],"categories":["good-to-know","rice","rice-recipes","rice-side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_220052dbd26b', 'en', 'US', 'Pizza Dough recipe', 'Recipe video above. This pizza dough can be made by hand with 5 minutes of kneading, or in 40 seconds flat using a food processor (see 2nd recipe card below). It makes a pizza crust like you get at Italian wood fired pizzerias - puffy edges with a chewy crumb, enough structure so you can pick up slices rather than being a sloppy mess. But not dry and stiff like a thin cracker! Best to use weights provided, if you can. Makes 3 pizzas.', 'https://www.recipetineats.com/tachyon/2020/05/Ball-of-pizza-dough.jpg', 30, 30, 60, 3, '[{"id": "ing_bread", "quantity": {"value": 600.0, "unit": "loaf"}}, {"id": "ing_yeast", "quantity": {"value": 0.02, "unit": "pack of 5 sachets"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.33, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.04, "unit": "pack of 125g"}}, {"id": "ing_pizza_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_topping_of_choice", "quantity": {"value": 1.0, "unit": "unit"}}]', '[]', '[{"title":"Mix dry","description":"Place flour, yeast, sugar and salt in a large bowl. Mix with a wooden spoon.","images":[],"step":1},{"title":"Add wet","description":"Make a well in the centre. Pour in oil and water. Mix to bring together so it comes away from the side of the bowl.","images":[],"step":2},{"title":"Knead 5 minutes","description":"Sprinkle work surface with 1/2 the Extra Flour. Scrape dough out of bowl. Bring together into a ball then knead for 5 minutes until pretty smooth (see video for Before v After, Note 5). Shape dough into a ball.","duration":5,"images":[],"step":3},{"description":"Drizzle large bowl with Extra Olive Oil (can use same bowl).","images":[],"step":4},{"description":"Place dough in, turn over and rub top with oil.","images":[],"step":5},{"description":"Cover with cling wrap, then put in a warm place for 1 - 2 hours until it doubles in size. (Rise #1)","images":[],"step":6},{"title":"Optional fridge","description":"flavour development:","images":[],"step":7},{"description":"After rising, refrigerate bowl with dough for up to 5 days (do not punch down). Flavour gets better with time. (Note 7)","images":[],"step":8},{"description":"Form small balls, Rise #2:","images":[],"step":9},{"description":"Scrape dough out of bowl on work surface lightly dusted with flour. Shape into log, fully deflating dough in the process.","images":[],"step":10},{"title":"Cut into 3 equal portions (330g / 11.6 oz each)","description":"one for each pizza base.","images":[],"step":11},{"description":"For each dough portion, shape into a ball, tuck the sides under, money-bag style, so you have a smooth surface.","images":[],"step":12},{"title":"Place balls, smooth side up, on a large tray","description":"5cm / 2\" from edge of tray, 10cm / 4\" from each other.","images":[],"step":13},{"description":"Sprinkle balls with a touch of flour and lightly rub to coat surface (so they don''t stick to tea towel). Cover balls with lightly damp tea towel. Alternatively, cover loosely with a sheet of baking paper then seal tray with cling wrap, ensuring the dough balls have plenty of space to rise under the cling wrap.","images":[],"step":14},{"description":"Leave in warm place 1 hour until almost double in size. (If fridge-cold, this will take 3 - 4 hours).","images":[],"step":15},{"description":"Stretch pizza base:","images":[],"step":16},{"description":"Preheat oven to 275°C / 530°F, or as high as it will go. Put shelf in top third of oven.","images":[],"step":17},{"description":"Sprinkle work surface with 1/2 tbsp flour. Place one dough ball on top.","images":[],"step":18},{"description":"Without touching the edges, use finger tips and back of fingers to deflate dough gently and spread out into a 20cm/8\" round. Then use your fingers and palms to stretch the dough, working around the circle, until it''s almost the size of a 30cm / 12\" pizza pan.","images":[],"step":19},{"description":"Drag onto the pizza pan (or paddle if cooking on pizza stone, Note 8). Then finish stretching it to fill the pan. Neaten up the shape so it''s as perfectly round and uniform as possible – the shape you have now is the shape it will bake to! Leave 1 cm / 1/3\" of the edge untouched as much as possible (for puffy crusts!).","images":[],"step":20},{"description":"Topping / Cooking (work quickly!):","images":[],"step":21},{"description":"Spread with 1/4 cup pizza sauce, 130g / 1 1/3 cups freshly grated mozzarella, then toppings of choice (see Topping recipes here).","images":[],"step":22},{"description":"Bake 10 minutes, rotating at 4 minutes and checking at 8 minutes, until cheese is melted and has some golden spots.","images":[],"step":23},{"description":"Cut into wedges, serve immediately!!","images":[],"step":24},{"description":"Repeat process for remaining balls to make two more pizzas.","images":[],"step":25}]', '["gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["good-to-know","main-dishes","pizza-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_38fba5c4f685', 'en', 'US', 'Pizza toppings', 'Here are our top 12 favourite pizza toppings! This list will continue to grow, at which point I''ll start creating separate recipes for each pizza. For now, enjoy this handy 12-in-1 list! Also see - homemade pizza dough (dough and cooking) and pizza sauce recipe. No yeast? No worries! Make this Magic No Yeast Pizza Dough.', 'https://www.recipetineats.com/tachyon/2020/05/Pizza-Toppings.jpg', 10, 10, 20, 1, '[{"id": "ing_pizza_base", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_pizza_sauce", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.067, "unit": "pack of 125g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.75, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 50.0, "unit": "pack of 1kg"}}, {"id": "ing_bacon", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_capsicum", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_black_olives", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_ham_batons", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_pineapple", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_barbecue_sauce", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.75, "unit": "jar of 50g"}}, {"id": "ing_cabanossi_pieces", "quantity": {"value": 0.333, "unit": "unit"}}, {"id": "ing_shrimp", "quantity": {"value": 12.0, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 25.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_chilli", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_baby_rocket", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_sausages", "quantity": {"value": 0.225, "unit": "pack of 500g"}}, {"id": "ing_kale", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.067, "unit": "pack of 125g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_basil", "quantity": {"value": 12.0, "unit": "bunch"}}, {"id": "ing_capricciosa_recipe", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.067, "unit": "pack of 125g"}}, {"id": "ing_cheese", "quantity": {"value": 1.333, "unit": "block of 250g"}}, {"id": "ing_cheese", "quantity": {"value": 1.333, "unit": "block of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.225, "unit": "pack of 200g"}}, {"id": "ing_prosciutto", "quantity": {"value": 8.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_potato", "quantity": {"value": 1.25, "unit": "bag of 2kg"}}, {"id": "ing_rosemary", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["1 pizza base (28cm / 11\" base, see separate recipe)","1/4 cup pizza sauce (see separate recipe)"]},{"ingredients":["1 1/3 cups mozzarella cheese (, freshly grated)","20 slices pepperoni (, cut 3mm / 1/8” thick)"],"purpose":"Pepperoni"},{"ingredients":["1 1/3 cups mozzarella cheese (, freshly grated)","1/3 cup onion (, cut 0.5cm (1/4”) thick)","1/3 cup bacon (, cut into 1 x 3cm (1/2 x 2”) pieces)","1/2 cup capsicum (, sliced 0.5cm (1/4”) thick)","12 slices pepperoni (, cut 3mm / 1/8” thick)","1/3 cup beef mince (ground beef) (, formed into 1cm (1/2”) balls)","1/3 cup button mushrooms (, cut 3mm (1/8”) thick)","1/4 cup black olives (, sliced)"],"purpose":"Supreme"},{"ingredients":["1 1/3 cups mozzarella cheese (, freshly grated)","2/3 cup ham (, cut into 2 x 0.5cm (1 x 1/4\") batons)","1/2 cup pineapple (, cut into small chunks)"],"purpose":"Ham & Pineapple"},{"ingredients":["3 tbsp barbecue sauce (instead of pizza sauce)","1 1/4 cups mozzarella cheese (, freshly grated)","10 slices pepperoni (, cut 3mm (1/8”) thick)","1/3 cup bacon (, cut into 1 x 3cm (1/2 x 2”) pieces)","1/3 cup cabanossi (, cut into 5mm (1/4”) pieces)","1/3 cup beef mince (ground beef) (, formed into 1cm (1/2”) balls)","1/3 cup ham (, cut into 2 x 0.5cm (1 x 1/4\") batons)"],"purpose":"BBQ Meatlovers"},{"ingredients":["1 1/3 cups mozzarella cheese (, freshly grated)","12 medium raw prawns/shrimp (, shelled and deveined)","25g / 1 1/2 tbsp butter (, unsalted)","1/4 tsp salt","1 tbsp garlic (, chopped)","1/2 cup capsicum (, sliced 0.5cm (1/4”) thick)","1/2 cup onion (, sliced 0.5cm (1/4”) thick)","2 tsp long red chillis (, sliced finely)","1 cup baby rocket (, loosely packed)"],"purpose":"Garlic Butter Prawns & Chilli"},{"ingredients":["1 1/3 cups mozzarella cheese (, freshly grated)","3/4 cup pork sausage (, skin removed, torn into 12 or so little balls (raw))","1 1/2 cups kale (, stems removed, torn into pieces (raw))","2 tsp olive oil"],"purpose":"Sausage & Kale"},{"ingredients":["125g / 4.4oz fresh buffalo mozzarella (, very well drained)","2 tbsp extra virgin olive oil","12 basil leaves"],"purpose":"Margherita"},{"ingredients":["Capricciosa recipe (separate recipe with video tutorial)"],"purpose":"Capricciosa"},{"ingredients":["1 heaped cup mozzarella cheese (, freshly grated)","1/2 cup sliced provolone cheese (, torn into pieces)","1/3 cup blue cheese (, broken into 1.5cm (1/2”) pieces)","3 tbsp parmesan cheese (, grated)"],"purpose":"Quattro Formaggio (Four Cheese Pizza)"},{"ingredients":["1 1/3 cup mozzarella cheese (, freshly grated)","1 tbsp olive oil (, plus extra for drizzling)","8 - 10 slices prosciutto","1 cup baby rocket (, loosely packed)"],"purpose":"Prosciutto & Rocket"},{"ingredients":["Cheese and garlic pizza (separate recipe)"],"purpose":"Cheese garlic pizza"},{"ingredients":["1 1/3 cups mozzarella cheese (, freshly grated)","1 1/4 cups potato (waxy variety) (, 2mm (1/12\") slices)","1 tbsp fresh rosemary leaves (picked, loosely packed)","1/4 tsp salt","1 1/2 tbsp extra virgin olive oil"],"purpose":"Potato & Rosemary"}]', '[{"description":"Preheat oven to 275°C/530°F, or as high as it will go. Place oven shelf in top third of oven.","images":[],"step":1},{"description":"Stretch dough to form pizza base and slide onto baking pan.","images":[],"step":2},{"description":"Follow topping directions below, then place in oven.","images":[],"step":3},{"description":"Turn pizza at 4 minutes so it cooks evenly, and check at 8 minutes (even if recipe says 10 minutes). Take out early if cheese gets too brown.","images":[],"step":4},{"description":"Spread pizza sauce over base, followed by cheese.","images":[],"step":5},{"description":"Distribute pepperoni over pizza, and bake.","images":[],"step":6},{"description":"Spread pizza sauce over base, followed by cheese.","images":[],"step":7},{"description":"Scatter remaining ingredients over pizza, and bake.","images":[],"step":8},{"description":"Ham & Pineapple","images":[],"step":9},{"description":"Spread pizza sauce over base, followed by cheese.","images":[],"step":10},{"description":"Scatter remaining ingredients over pizza, and bake.","images":[],"step":11},{"description":"Spread barbecue sauce over base, followed by cheese.","images":[],"step":12},{"description":"Scatter remaining ingredients over pizza, and bake.","images":[],"step":13},{"description":"Garlic Butter Prawns & Chilli","images":[],"step":14},{"description":"Toss prawns/shrimp with salt.","images":[],"step":15},{"description":"Heat butter over medium heat in a skillet or heavy frying pan until frothing. Add garlic and cook for another 30 seconds.","images":[],"step":16},{"description":"Cook prawns for 1 minute on one side until just starting to brown. Flip prawns, cook 1 minute more and remove. Reserve garlic butter.","duration":1,"images":[],"step":17},{"description":"Spread pizza sauce over base, followed by cheese.","images":[],"step":18},{"description":"Scatter remaining ingredients except rocket over pizza, top with prawns. Bake until done.","images":[],"step":19},{"description":"Drizzle reserved garlic butter over prawns and scatter with rocket.","images":[],"step":20},{"description":"Spread pizza sauce over base, followed by cheese.","images":[],"step":21},{"description":"Scatter remaining ingredients over pizza, and bake. (Note 2)","images":[],"step":22},{"description":"Spread pizza sauce over base. Drizzle 1 tbsp of oil over base, and bake.","images":[],"step":23},{"description":"After 5 minutes, remove pizza from oven. Tear buffalo mozzarella into 10 pieces and distribute over pizza. Continue baking until pizza is done.","images":[],"step":24},{"description":"Drizzle with remaining olive oil, and scatter with basil leaves.","images":[],"step":25},{"description":"See recipe directions in the separate recipe here.","images":[],"step":26},{"description":"Quattro Formaggio (Four Cheese Pizza)","images":[],"step":27},{"description":"Spread mozzarella cheese over base. Scatter provolone, parmesan and finally blue cheese over pizza. Bake.","images":[],"step":28},{"description":"Prosciutto & Rocket","images":[],"step":29},{"description":"Spread pizza sauce over base, followed by cheese. Drizzle 1 tbsp oil over pizza and bake.","images":[],"step":30},{"description":"2 minutes before the pizza is done, remove from oven. Drape prosciutto casually around the pizza.","images":[],"step":31},{"description":"Continue baking until done. Scatter rocket over pizza and drizzle with a little more olive oil.","images":[],"step":32},{"description":"Cheese & Garlic","images":[],"step":33},{"description":"See recipe directions in the separate recipe here.","images":[],"step":34},{"description":"Potato & Rosemary","images":[],"step":35},{"description":"Spread mozzarella cheese over base.","images":[],"step":36},{"description":"Arrange potato slices over pizza, each slice overlapping no more than 1/3 so it will cook through properly.","images":[],"step":37},{"description":"Sprinkle over the rosemary and salt, and drizzle with the olive oil. Bake for the standard cooking time given. Check with a fork or skewer that the potato is tender. If not fully cooked, cook another 2 minutes.","images":[],"step":38}]', '["milk","shellfish"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["good-to-know","leftover-ham-recipes","pizza-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0bea77e2f7c6', 'en', 'US', 'Pizza Sauces', 'Pick the one that suits your needs to make homemade pizza! (No Yeast pizza dough here)Instant Pizza Sauce - An intense flavour with the signature tang of tomato paste which compliments rich / intense flavoured pizza toppings. Tastes like Leggos pizza sauce sold at the stores. I use this the most often - personal taste and sheer convenience.Fresh and Bright - A lighter, fresher pizza sauce thanks to the addition of passata. Ideal for more delicate toppings like margherita, vegetable pizzas and most classic Italian pizzas.New York Pizza Sauce - A richly flavoured New York-style pizza sauce. Based on this recipe from Serious Eats.', 'https://www.recipetineats.com/tachyon/2020/05/Spreading-pizza-sauce-on-homemade-pizza-crust.jpg', 5, 0, 5, 4, '[{"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_parsley", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}]', '[{"ingredients":["1 cup tomato paste (, unsalted (Note 1))","1 tsp salt (Note 1)","2 tsp white sugar","2 tsp olive oil","2 tsp garlic (, finely minced (optional))","2 tbsp water","1/2 tsp EACH dried parsley (, basil and oregano (optional))"],"purpose":"Instant Pizza Sauce:"},{"ingredients":["1 cup tomato passata (Note 2)","1 tbsp tomato paste","1/2 tsp salt","1 tsp sugar","1 tbsp olive oil"],"purpose":"Fresh and Bright Pizza Sauce:"},{"ingredients":["2 tbsp olive oil","1 onion ((small), finely chopped)","2 cloves garlic grated or finely chopped","800g / 28 oz canned crushed tomatoes","1 tsp dried oregano","3/4 tsp salt","1 tsp sugar"],"purpose":"New York Pizza Sauce:"}]', '[{"description":"Instant Pizza Sauce:","images":[],"step":1},{"description":"Combine ingredients and mix well.","images":[],"step":2},{"description":"Fresh and Bright Pizza Sauce:","images":[],"step":3},{"description":"Combine ingredients and mix well","images":[],"step":4},{"description":"New York Pizza Sauce:","images":[],"step":5},{"description":"Heat oil in a heavy-based, medium saucepan over medium heat. Add onion and garlic, and sautee until onions are soft but not coloured.","images":[],"step":6},{"description":"Add tomatoes, oregano, salt and sugar. Bring to a simmer. Reduce heat to low, and cook, stirring occasionally, until reduced by half (about 1 hour). You will need to stir more frequently towards the end to stop the sauce catching","images":[],"step":7},{"description":"Leave to cool before using.","images":[],"step":8},{"description":"Using pizza sauce:","images":[],"step":9},{"description":"Use 1/4 cup of pizza sauce for each pizza (30cm/12\" wide).","images":[],"step":10},{"description":"Place raw pizza crust on a pizza pan (preferably with holes). Spread sauce evenly using the back of a spoon, leaving a 1cm / 1/2\" border for the crust.","images":[],"step":11},{"description":"Cover with toppings of choice (less is more!). Standard pizza - sprinkle with 130g / 4.5 oz freshly shredded mozzarella cheese, then 1 cup toppings such as sliced pepperoni. (See this post for pizza topping recipes)","images":[],"step":12},{"description":"Bake in preheated 275°C / 530°F oven on top shelf for 10 minutes, rotating at 4 minutes, until cheese has golden specks and crust is crisp. (See this homemade pizza recipe for full cooking directions, or this NO YEAST Pizza Dough recipe)","duration":10,"images":[],"step":13}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["good-to-know","pizza-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9316e2d27e66', 'en', 'US', 'Gravy recipe (tastes like KFC - but a million times better!)', 'Recipe video above. This recipe is how I make a seriously tasty gravy using water in 4 minutes flat. The secret is to use both chicken AND beef stock cubes. Beef adds colour and flavour oomph, whereas chicken is the base flavour. Use crumbled cubes if you can as some brands of beef powder won''t give the same nice brown colour (ends up pale). Also pictured - KFC copycat mashed potato (extra light and creamy, just like KFC!) (GLUTEN FREE in notes)', 'https://www.recipetineats.com/tachyon/2020/02/Gravy_4.jpg', 1, 3, 4, 6, '[{"id": "ing_chicken_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_beef_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.562, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1 chicken stock cube / bouillon cube (sub 2 tsp powder) (Note 1)","1 beef stock cube / bouillon cube (sub 2 tsp powder) (Note 1)","2 1/4 cups (565ml) boiling water","60g/ 4 tbsp butter (, unsalted)","4 tbsp flour (, plain / all purpose)","1/2 tsp onion powder (ok to omit or sub garlic powder)","1/4 tsp finely ground black pepper","Salt (, if needed)"]}]', '[{"description":"Crumble cubes into boiling water, mix to dissolve.","images":[],"step":1},{"description":"Melt butter in a saucepan over medium heat.","images":[],"step":2},{"description":"Add flour, onion powder and pepper. Mix into butter with a wooden spoon or whisk.","images":[],"step":3},{"description":"While stirring, slowly pour in half the liquid. Once incorporated into the flour butter roux (it will thicken quickly), add remaining liquid and mix.","images":[],"step":4},{"title":"Stir for 1.5","description":"2 minutes until it thickens to a gravy consistency (it''s quick as water is already hot). Taste, add more salt and pepper if needed.","images":[],"step":5},{"description":"Serve over chops, steak, sausages, veggies, roast chicken, pork, beef, lamb. Pictured - KFC Potato and Gravy copycat!","images":[],"step":6}]', '["gluten","milk"]', '["keto_friendly","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["good-to-know","roasts","sauces"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_618b3c79806f', 'en', 'US', 'Greek Kofta Kebabs', 'Recipe video above. This Greek Kofta kebab features a secret spice mix from a well known Melbourne souvlaki shop called Kalimera Souvlaki Art. The owner gave me his chicken gyros recipe for a story I did for Good Food. I used the same blend for lamb mince koftas - it''s spectacular! The secret ingredient is a hint of curry powder, which adds warmth and depth without a curry taste. Genius!Served with my version of his Secret Souvlaki Sauce, crafted from clues he gave me. It''s so good, I use it to dunk crackers, veggie sticks and hot chips.', 'https://www.recipetineats.com/tachyon/2024/08/Greek-lamb-kofta-kebabs_5.jpg', 15, 10, 25, 4, '[{"id": "ing_lamb_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1000.0, "unit": "pack of 3 heads"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.15, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_skewers", "quantity": {"value": 8.0, "unit": "pack of 50"}}, {"id": "ing_yogurt", "quantity": {"value": 0.225, "unit": "tub of 500g"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.075, "unit": "jar of 400g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_bread", "quantity": {"value": 0.005, "unit": "loaf"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}]', '[{"ingredients":["500g/ 1 lb lamb mince (or beef, or 50/50 beef/lamb, Note 1)","3 large garlic cloves (, crushed using garlic press or finely grated)","2 tsp paprika (regular/sweet, not smoked)","2 tsp mustard powder","4 1/2 tsp dried oregano","1 1/2 tsp curry powder (, not spicy, any brand fine (Kalimera secret ingredient! Note 2))","3/4 tsp cooking salt / kosher salt","1/4 tsp black pepper"],"purpose":"Kofta kebab:"},{"ingredients":["1 tbsp olive oil","8 skewers (, optional (I use 18cm/7.5\"))"],"purpose":"For cooking:"},{"ingredients":["3/4 cup plain yogurt (, preferably Greek (full-fat best))","2 tbsp mayonnaise (, preferably whole-egg)","2 tbsp extra virgin olive oil","1 tbsp American yellow mustard (ie the bright yellow American stuff!)","1 1/2 tsp garlic powder","1 1/2 tsp paprika (sweet/regular, not smoked or spicy)","1/2 tsp cooking salt / kosher salt"],"purpose":"Secret Sauce (Note 3):"},{"ingredients":["4 Greek pita bread (, pockets or flatbreads, warmed (TIPS - Note 4!))","2 tomatoes (, halved and sliced)","1/2 red onion (, finely sliced or chopped)","Iceberg lettuce (, finely sliced (or other leafy greens))"],"purpose":"Serving:"}]', '[{"title":"Sauce","description":"Mix the ingredients in a bowl and set aside to let the flavours meld while you make the kofta kebabs.","images":[],"step":1},{"title":"Kofta kebabs","description":"Put all the ingredients in a bowl and mix well with your hands until the spices are mixed through. Divide into 8, shape into 13cm/5\" logs. Thread onto skewers then flatten slightly to about 1.25cm / 0.5\" thick (Note 5).","images":[],"step":2},{"title":"Cook","description":"Heat 1 tbsp oil in a large non stick pan over medium high heat. Cook half the koftas for 2 minutes on each side until golden, then about 30 seconds on each short edge (just for a bit of colour). Reduce the heat if they''re browning too fast. Transfer to a serving plate, loosely cover with foil to keep warm. Cook the remaining koftas. (Scrape out loose burnt bits, if any. You shouldn''t need extra oil.)","duration":2,"images":[],"step":3},{"description":"Serve and assemble! Pile the lettuce, tomato and onion on the plate and put the sauce in a bowl. To assemble, take a warm pita bread and smear some sauce down the middle. Top with lettuce and 1 or 2 koftas (removed from the skewers), tuck tomato down the side and sprinkle with onion. Fold and EAT!","images":[],"step":4}]', '["egg","gluten","milk","mustard"]', '["high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Greek"],"categories":["greek-recipes","lamb","lamb-recipes","mains","mediterranean-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_94ef5a62facc', 'en', 'US', 'Sautéed Green Beans with Garlic', 'This is a wonderful,classic preparation for a green beans side dish - simmer beans until bright green then toss with garlic until golden and crispy. Serve as a side with everything, any cuisine, from Western to Italian, Middle Eastern to French!If serving with Asian food, I like to add the tiniest drizzle of sesame oil at the end and sometimes a sprinkle of sesame seeds. Just gives it that little Asian-esque finishing touch!Love green beans? So do I! See all my Green Bean Sides.', 'https://www.recipetineats.com/tachyon/2021/10/Garlic-Sauteed-Green-Beans_08.jpg', 5, 8, 13, 2, '[{"id": "ing_green_beans_trimmed", "quantity": {"value": 250.0, "unit": "pack"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 1.0, "unit": "jar of 50g"}}]', '[{"ingredients":["250g/ 8oz green beans (, trimmed (Note 1))","1 tsp salt"],"purpose":"Blanched Green Beans:"},{"ingredients":["1 tbsp extra virgin olive oil (or... butter!)","2 garlic cloves (, finely minced (~ 2 tsp), do not use jar or garlic crusher (Note 2))","1/8 tsp salt","1 pinch black pepper"],"purpose":"For Sautéing:"}]', '[{"title":"Blanch beans","description":"Bring a large saucepan of water to the boil with 1 teaspoon of salt. Add beans, cook for 4 minutes (they will turn bright green), drain, then rinse under cold tap water to cool. (There''s really no need to shock in ice water). Shake off excess water.","duration":4,"images":[],"step":1},{"title":"Sauté","description":"Heat oil in a large skillet over medium high heat. Add green beans and garlic. Toss (or stir!) for 2 minutes until the garlic is golden and crispy. Add salt and pepper, then toss.","duration":2,"images":[],"step":2},{"title":"Serve","description":"Transfer beans to serving dish. Serve warm!","images":[],"step":3},{"title":"Prepare ahead","description":"Blanch beans per step 1, cool and dry, store in fridge until required. When ready to serve, just toss with garlic. It''s an instant on-demand side!","images":[],"step":4}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["green-beans","quick-and-easy","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ba8a36f39857', 'en', 'US', 'Chicken stock recipe', 'Recipe video above. This is the only chicken stock recipe you''ll ever need. It''s an excellent all-rounder that can be used for everything from clear soups to rich stews, gravies and creamy sauces. The key is to use chicken frames (carcass) which yields the ideal balance of flavour, nutrients and richness. They are inexpensive and even available at grocery stores these days.No rinsing or roasting prep like call for beef stock, just plonk everything in a pot and let it simmer for a few hours!Makes 2 litres / 2 quarts. Fridge 5 days or freezer for 6 months.', 'https://www.recipetineats.com/tachyon/2021/09/Homemade-chicken-stock_92.jpg', 15, 180, 195, 2, '[{"id": "ing_chicken", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.15, "unit": "jar of 50g"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_water", "quantity": {"value": 3.0, "unit": "L"}}]', '[{"ingredients":["2 kg/ 4 lb chicken frames (ie carcass) (, raw (Note 1))","1 carrot ((medium), unpeeled, cut into 4 equal pieces)","1/2 onion (, peeled and halved)","1 celery stem (, cut in four (use the leaves too))","1/2 tbsp black peppercorns","1 tbsp apple cider vinegar (Note 2)","2 bay leaves (, fresh (or 1 dried))","2 thyme sprigs (or 1/2 tsp dried leaves)","3 parsley sprigs","3 litres / 3 quarts water (just tap water, cold)"]}]', '[{"description":"How to make chicken stock:","images":[],"step":1},{"title":"Fill pot","description":"Place all the chicken stock ingredients into a large stockpot (7 litre / 7 quarts+). Fill with 3 litres / 3 quarts of cold water, which should just about cover the bones. (Note 3)","images":[],"step":2},{"title":"Scoop off scum","description":"Bring to a boil on medium-high heat. Scoop off and discard any foam that collects on the surface using a ladle (this helps make stock clear).","images":[],"step":3},{"title":"Simmer 3 hours","description":"Turn stove down to low and simmer for 3 hours with no lid. The stove should be low enough so the surface is barely rippling and you just get a gentle bubble every now and then. Too rapid boiling = murky stock.","images":[],"step":4},{"title":"Strain","description":"Using a lid to hold the bones and vegetables in the pot, pour the stock through a fine sieve into another pot or large bowl. (Alternatively, scoop out the solids first with a slotted spoon and then strain.)","images":[],"step":5},{"title":"Goal","description":"You should end up with 2 litres / 2 quarts of stock. If you have more than about 2.25 litres / quarts, reduce by simmering on low (else the stock will be too weak). If you have less than 2 litres / quarts, top up with water.","images":[],"step":6},{"title":"Fill jars/containers","description":"Measure out into containers for storage and faster cooling. (I do multiples of 1 cup)","images":[],"step":7},{"title":"Cool","description":"Allow to cool on the counter then refrigerate. This will make any fat rise to surface and solidify.","images":[],"step":8},{"title":"Discard fat","description":"Scrape fat off the surface and discard.","images":[],"step":9},{"description":"Storing and using:","images":[],"step":10},{"description":"Ready to use! This stock is equivalent in strength to store-bought stock, so it can be used 1:1 in any recipe calling for chicken stock.","images":[],"step":11},{"description":"Store for 5 days in the fridge or freezer for 6 months. (Note 6)","images":[],"step":12},{"title":"Salt adjustment (Note 5)","description":"Homemade stock is unsalted whereas store-bought stock is salted. Add 1/4 tsp salt for every 1 cup homemade chicken stock (250ml) to match the salt level of store-bought low sodium chicken stock.","images":[],"step":13},{"title":"To use","description":"Cold stock has a jellied consistency (Note 4). It takes barely a minute to turn liquid on a medium-high stove, or microwave. You can also just add it in jelly form straight into dishes, but sometimes you may need to liquify it to measure.","images":[],"step":14}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["main_course"],"cuisine":["French","Western"],"categories":["homemade-stocks"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4b747e02f9fc', 'en', 'US', 'Homemade beef stock recipe', 'Recipe video above. This is a classical French-style recipe for homemade beef stock. It''s vastly superior to any store-bought stock, and is one of the main things that distinguishes home and restaurant cooking.It takes time to make, but if you truly want the best, it''s worth it!Makes: 1.25 - 1.5 L / quarts stock (5 - 6 cups), ready use store-bought strength, UNSALTED. Add 1/3 tsp salt for each 1 cup (250ml) homemade beef stock to match store-bought low sodium beef stock. Other homemade stocks: chicken stock | vegetable stock', 'https://www.recipetineats.com/tachyon/2021/02/Homemade-Beef-Stock_1.jpg', 10, 480, 490, 1, '[{"id": "ing_beef", "quantity": {"value": 2.5, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.15, "unit": "jar of 50g"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 12.0, "unit": "bunch"}}, {"id": "ing_water", "quantity": {"value": 3.0, "unit": "L"}}]', '[{"ingredients":["2.5 kg / 5 lb meaty beef bones (, back and neck preferably, plus one marrow bone for richness (or knuckles) (Note 1))","1 carrot (, unpeeled, cut in half)","1/2 onion ((brown or yellow), peel and cut in half)","2 tomatoes (, cut into quarters (keep seeds in) (Note 2))","1/2 tbsp coriander seeds (Note 2)","1 tbsp apple cider vinegar (Note 3)","1/2 tbsp black peppercorns","1 celery stem (, cut in half or thirds (leaves on ok))","2 bay leaves (, fresh (or 1 dried))","2 thyme sprigs (or 1/2 tsp dried leaves)","12 parsley sprigs (, if you have it (not essential))","3 litres/quarts water (, cold tap water)"]}]', '[{"description":"Preheat oven to 220°C/430°F (200°C fan-forced).","images":[],"step":1},{"description":"Spread bones out across 2 baking trays. Roast for 1 hour, turning at 30 minutes, or until very well browned.","images":[],"step":2},{"description":"Drain and discard excess fat, if any.","images":[],"step":3},{"description":"Place bones into large stock pot (7 litres/7 quarts+ capacity)","images":[],"step":4},{"description":"Place tray on stove, turn onto medium. Add 3/4 cup water. When it comes to a simmer, start scraping the tray. The drippings (fond) on the tray will loosen and dissolve into the liquid.","images":[],"step":5},{"description":"Once most of the drippings are removed from the base, scrape all the liquid into the pot. Repeat with other tray.","images":[],"step":6},{"description":"Add remaining ingredients into the pot. Start with 3 litres of water, then squish the bones etc down to fit snugly in the pot. Add more water if needed, to just cover the bones (ingredients will collapse a bit as stock cooks). The water quantity depends on shape of bone and pot – my water level came to 5.75 litres/quarts mark on pot.","images":[],"step":7},{"title":"Boil then simmer","description":"Bring to a boil on medium high, then turn down to low so it''s simmering ever so gently, with only a small bubble bursting every now and then.","images":[],"step":8},{"title":"Remove surface scum","description":"Scoop off any surface scum using a ladle and discard.","images":[],"step":9},{"description":"Simmer for 8 hours on very low, no lid. Liquid level should reduce to around 4 litres/quarts for all - if not, just reduce after straining (Step 3 under Strain & Finish).","images":[],"step":10},{"title":"Other methods:","description":"Stove 3 hours on medium-low (very gentle simmer, with lid cracked)- oven (lid on) for 8 to 10 hours at 120°C/250°F (100°C fan). Water level will only reduce by about 500ml / 0.5 qt. Strain then rapid boil to reduce to 1.5 lt / 1.5 qt. - slow cooker 8 to 10 hours on low. Reduce after straining to 1.5 lt / 1.5 qt.","images":[],"step":11},{"description":"Strain & finish:","images":[],"step":12},{"title":"Strain","description":"Fish out most bones. Strain stock with remaining vegetables through a fine mesh colander / strainer set over a large pot or bowl. Leave strainer for a few minutes to let it drip.","images":[],"step":13},{"title":"Cool to room temperature","description":"Set stock pot or bowl in sink filled with cold water. Leave stock to cool for around 1h 15 mins, changing water every 20 mins or so as it gets warm.","images":[],"step":14},{"title":"Measure stock volume","description":"Pour stock into a vessel to measure volume - it should be between around 1.3 - 1.7 litres/quarts. If it''s much more, reduce on the stove, otherwise stock flavour will be too weak.","images":[],"step":15},{"description":"Refrigerate stock. When fat has solidified on surface, carefully scrape off with a large spoon and discard. You should have 1.25 - 1.5 L/Qts remaining.","images":[],"step":16},{"description":"Ready! Beef stock is now ready to use! This stock is equivalent in strength to store-bought stock, so it can be used 1:1 in any recipe calling for beef stock.","images":[],"step":17},{"title":"Salt adjustment","description":"Homemade stock is unsalted whereas store-bought stock is salted. Add 1/4 tsp salt for every 1 cup homemade beef stock (250ml) to match the salt level of store-bought low sodium beef stock.","images":[],"step":18},{"title":"To use","description":"Cold stock has a jellied consistency (Note 4). It takes barely a minute to turn liquid on a medium high stove, or microwave. You can also just add it in jelly form straight into dishes, but sometimes you may need to liquify it to measure.","images":[],"step":19}]', '[]', '["gluten_free","low_calorie"]', '{"mealType":["main_course"],"cuisine":["French","Western"],"categories":["homemade-stocks"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6f2e41a420ca', 'en', 'US', 'How to cut butternut pumpkin (butternut squash)', 'Tutorial video above. This is how I cut butternut squash - called butternut pumpkin here in Australia and NZ. Use butternut as a direct substitute in any recipe calling for pumpkin. Same cook times, cook methods and quantities!Use to make classic Pumpkin Soup, Thai Coconut Pumpkin Soup, roast it, make a salad, a coconut curry or make pumpkin risotto!', 'https://www.recipetineats.com/tachyon/2023/08/How-to-cut-butternut-cover-thumbnail.jpg', 5, 0, 5, 1, '[{"id": "ing_pumpkin", "quantity": {"value": 1.0, "unit": "kg"}}]', '[{"ingredients":["1 whole butternut pumpkin / butternut squash (same thing)"]}]', '[{"description":"Peel off the skin using a potato peeler. The skin is softer than pumpkin so it''s easier.","images":[],"step":1},{"description":"Cut in half using a sharp knife. Just straight through the middle, lying down. Use the weight of your body pressing down on the knife and/or rock the knife back and forth.","images":[],"step":2},{"description":"Stand upright, then cut in half again.","images":[],"step":3},{"description":"Scoop out the seeds using a spoon.","images":[],"step":4},{"description":"Cut the cheeks off the side with the stem (too hard to cut through the stem). Then trim all the butternut flesh from around the hard stem.","images":[],"step":5},{"title":"Cut","description":"And finally, cut the butternut into the size you want! For Pumpkin Soup, you will want them in 3cm / 1.2\" chunks.","images":[],"step":6}]', '[]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["how-to","pumpkin","pumpkin-squash"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9fe5e9fe473f', 'en', 'US', 'Rum raisin ice cream (easy, no ice cream maker!)', 'Recipe video above. This has rum flavour unlike anything you can buy at the shops. Relish in it!EASY ice cream recipe - In this recipe, fluffy whipped cream is used to replicate the effect of incorporating air into traditional ice cream by churning in an ice cream maker. Condensed milk, meanwhile, keeps the mixture from freezing into a solid block and keeps it creamy and scoop-able, just like real ice cream! Skeptical? Don''t blame you. Read glowing reviews here and here!', 'https://www.recipetineats.com/tachyon/2023/01/Rum-and-raisin-ice-cream-in-cone.jpg', 10, 0, 10, 6, '[{"id": "ing_raisins", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_rum", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_milk", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_rum", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.016, "unit": "jar of 40g"}}, {"id": "ing_cream", "quantity": {"value": 2.0, "unit": "carton of 250ml"}}, {"id": "ing_cream", "quantity": {"value": 2.0, "unit": "carton of 250ml"}}, {"id": "ing_chocolate", "quantity": {"value": 1.0, "unit": "block of 100g"}}]', '[{"ingredients":["1 1/2 cups raisins (separate with fingers)","1/2 cup rum ( (preferably Jamaican! Note 2))"],"purpose":"Rum soaked raisins (Note 1):"},{"ingredients":["1 x 395g / 14oz can condensed milk (Note 3)","1/4 cup rum, dark or golden ( (preferably Jamaican! Note 2))","1 tsp vanilla extract","1/8 tsp allspice powder (, optional)","2 cups thickened/heavy cream, fridge cold (any whipping cream works)"],"purpose":"Ice cream:"},{"ingredients":["Ice cream cones","Rum raisin chocolate (, finely chopped (pictured in post))"],"purpose":"Serving (all optional)"}]', '[{"description":"Rum soaked raisins:","images":[],"step":1},{"title":"Chop","description":"Roughly chop the raisins (about in half) and break them up with your fingers so they are not stuck together.","images":[],"step":2},{"title":"Soak","description":"Heat the rum in a small saucepan on medium high, just until hot. Add raisins, spread to submerge as best you can. Then leave to soak for 30 minutes.","duration":30,"images":[],"step":3},{"title":"Pour off excess","description":"The raisins should absorb most of the rum. If not, see Note 4.","images":[],"step":4},{"title":"Condensed milk & flavourings","description":"Place the condensed milk, rum, vanilla and all-spice in a bowl. Briefly beat just to combine with a handheld beater (or mix by hand), then stir in the rum soaked raisins.","images":[],"step":5},{"title":"Whipped cream","description":"Place the cream in a separate large bowl and beat on high with an electric beater for 2 1/2 to 3 minutes until well whipped (stand mixer 1 - 1 1/2 minutes). We''re not looking for \"soft whipped\" here, we want stiff peaks and good aeration!","images":[],"step":6},{"title":"Fold together","description":"Fold about 1 cup whipped cream into the condensed milk mixture. Once mostly incorporated (some lumps is fine), pour the condensed milk mixture into the cream and gently continue folding until smooth (minimise folding as less aeration = denser ice cream). To help remove lumps, \"smear\" visible cream bits across the surface or against the side of the bowl rather than vigorously stirring.","images":[],"step":7},{"title":"Freeze 12 hours","description":"Spread in a 1.5 litre / 1.5 quart container (Note 6). Cover with lid or cling wrap. Freeze at least 12 hours.","images":[],"step":8},{"description":"Serve! To scoop, you''ll only need to leave it out for a minute or two, like real ice cream! Then scoop and serve in bowls or in cones. I topped mine with chopped rum raisin chocolate, because, why not? :)","images":[],"step":9}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Caribbean","Jamaican"],"categories":["dessert-recipes","ice-cream","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_165863a4f0b4', 'en', 'US', 'Strawberry Ice Cream (No Churn)', 'Recipe video above. This is flavour money can''t buy! Incredibly creamy, not a speck of iciness in sight, with beautiful fresh strawberry flavour. No ice cream maker required!', 'https://www.recipetineats.com/tachyon/2018/07/Strawberry-Ice-Cream-No-Churn_3b.jpg', 20, 60, 80, 6, '[{"id": "ing_strawberries", "quantity": {"value": 4.0, "unit": "punnet of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_milk", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 2.0, "unit": "carton of 250ml"}}]', '[{"ingredients":["1 kg / 2 lb strawberries (, ripe, hulled and halved)","1 tbsp white sugar","1 tsp vanilla extract (optional)","1 can sweetened condensed milk (395g / 13 oz)","2 cups / 500 ml cream (, full fat, for whipping (Note 1))"]}]', '[{"description":"Roast Strawberries:","images":[],"step":1},{"description":"Preheat oven to 160°C/320°F (140°C fan) with shelf in the middle.","images":[],"step":2},{"description":"Pile strawberries on a tray. Sprinkle over sugar. Toss through, then spread strawberries out on tray.","images":[],"step":3},{"description":"Roast for 45 minutes, rotating tray halfway. Remove from oven, toss strawberries, then return to oven for 15 minutes. Keep an eye on it - don''t want juices to become toffee and stick to tray.","duration":45,"images":[],"step":4},{"description":"Remove from oven, use spatula to scrape into a food processor, being sure to get all the juices and caramelised bits off the tray.","images":[],"step":5},{"description":"Blitz until smooth as possible (caramelised bits won''t blitz smooth), scrape into bowl then cool completely.","images":[],"step":6},{"description":"Ice Cream Mixture:","images":[],"step":7},{"description":"Add condensed milk and vanilla into strawberries. Beat well for 1 1/2 minutes on high to aerate and combine.","images":[],"step":8},{"description":"Place cream in another bowl. Use electric beater to beat into stiff peaks - about 3 minutes on high.","images":[],"step":9},{"description":"Add a dollop of cream into the strawberry mixture. Fold through gently, don''t beat in furiously (see video for technique). When mostly mixed through, add another dollop and for through about 5 times.","images":[],"step":10},{"description":"Tip strawberry mixture into the cream bowl. Gently fold through until it''s a uniform pink colour - about 15 to 20 folds max. Some streaks is ok.","images":[],"step":11},{"description":"Freezing & serving:","images":[],"step":12},{"description":"Pour mixture into a container (preferably glass with airtight lid), smooth top.","images":[],"step":13},{"description":"Place sheet of baking paper on surface and press out air bubbles (stops icicles forming). Cover with lid, freeze 12+ hours.","images":[],"step":14},{"description":"Remove from freezer, remove paper. Scoop with ice cream scooper and serve in cones or bowls!","images":[],"step":15}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dessert"],"cuisine":[],"categories":["dessert-recipes","ice-cream"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_aa88a485be43', 'en', 'US', 'Homemade Mango Ice Cream Recipe', '{Video below} A magic way to make a creamy scoopable ice cream without an ice cream maker! It''s truly creamy and scoopable like ice cream you buy in tubs. Store bought is simply no comparison because you just cannot buy a real mango flavoured ice cream at the shops. It just doesn''t exist! Note: I wasn''t able to make this with an extremely intense mango flavour because the more mango that is added, the less creamy it gets. So getting the best mango flavour into the ice cream is dependent on using juicy ripe mangoes with good mango flavour! See Note 1. Also see notes for how to make this with other flavours. :)', 'https://www.recipetineats.com/tachyon/2017/02/Mango-Ice-Cream-8.jpg', 15, 10, 25, 6, '[{"id": "ing_mango", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_milk", "quantity": {"value": 0.395, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 2.0, "unit": "carton of 250ml"}}, {"id": "ing_yellow_liquid_food_colouring", "quantity": {"value": 0.125, "unit": "unit"}}]', '[{"ingredients":["2 large mangoes (, ripe and juicy - to make 2 cups puree (Note 1))","395 g / 14 oz sweetened condensed milk (1 can)","2 cups thickened cream / heavy cream / whipping cream (, cold)","1/8 tsp yellow liquid food colouring (optional) (Note 5)"]}]', '[{"description":"Dice the flesh of the mango (see video for how I do it). Puree using a blender, food processor or stick blender then measure out 2 cups of mango puree (about 2 1/4 cups of diced mango).","images":[],"step":1},{"description":"Pour puree into a non stick skillet over medium low heat. Cook, stirring constantly, for 8 - 10 minutes or until it reduces by half. The test is when you can drag a wooden spoon across the skillet and the path remains there for a second (see video). Or measure out the puree to ensure it''s reduced to at least 1 cup - less is even better!","duration":9,"images":[],"step":2},{"description":"Combine cooled mango and condensed milk in a bowl. Add food colouring if using. Whisk until combined.","images":[],"step":3},{"description":"Beat cream with a hand held beater or stand mixer until stiff peaks form (see video).","images":[],"step":4},{"description":"Take a scoop of cream and put it in the mango mixture. Fold through until mostly combined - lumps is fine (this is just to lighten it up a bit).","images":[],"step":5},{"description":"Then pour the mango mixture into the cream. Fold through (see video) rather than mixing vigorously like you would cake batter, until lump free. This will take a few minutes.","images":[],"step":6},{"description":"Pour into a container (preferably with a lid). I recommend glass, if you can, or other non reactive container.","images":[],"step":7},{"description":"Place a piece of baking / parchment paper on the surface. Then place lid on or using cling wrap.","images":[],"step":8},{"description":"Freeze for 12+ hours.","images":[],"step":9},{"description":"Remove parchment paper. Stand for 5 minutes to soften slightly, then scoop and serve!","duration":5,"images":[],"step":10},{"description":"If frozen for 24 hours or longer, it will need a couple of extra minutes to soften to a scoop able consistency.","images":[],"step":11}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dessert"],"cuisine":[],"categories":["dessert-recipes","ice-cream","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3f3c383198de', 'en', 'US', 'Porchetta - Dozer''s last recipe', 'Recipe video above. Most porchetta recipes promise epic crackling, but few deliver that properly blistered crispness all the way around. You might get bubbles on top, but the sides and underside are flat and hard skin, or worse, rubbery.This one works. It has incredible crispy crackling ALL over - top, sides and even underneath - with insanely juicy meat. See the video for proof! The keys are a 1 - 2 day fridge dry, slow roasting on low then a hot blast, salting just before roasting, and using a rack on a tray, not a roasting pan.This is the last recipe developed under Dozer''s watchful eye, so it will always hold a special place in my heart. It was a big one - but he was at my feet, cheering me on every step of the way. ❤️', 'https://www.recipetineats.com/tachyon/2026/02/Porchetta-overhead-take-2.jpg', 60, 270, 3210, 8, '[{"id": "ing_pork", "quantity": {"value": 2.5, "unit": "kg"}}, {"id": "ing_fennel_seeds", "quantity": {"value": 30.0, "unit": "jar"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.013, "unit": "kg"}}, {"id": "ing_rosemary", "quantity": {"value": 0.9, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 2000.0, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_pork", "quantity": {"value": 2.5, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.013, "unit": "kg"}}]', '[{"ingredients":["2.5 kg / 5lb pork belly with skin on (, NOT SCORED (Note 1))"]},{"ingredients":["2 tbsp fennel seeds (Note 1)","2 tsp black peppercorns (Note 1)","2 1/2 tsp cooking salt / kosher salt (halve for table salt, +50% for salt flakes)","3 tbsp finely chopped rosemary leaves - about 1/4 cup leaves (Note 3 for dried)","2 tsp red chilli flakes (red pepper flakes)","6 large garlic cloves (, finely grated with a microplane or garlic crusher)"],"purpose":"Rub:"},{"ingredients":["2 1/2 tsp cooking salt / kosher salt (halve for table salt, +50% for salt flakes)","2 tbsp olive oil (, divided)"],"purpose":"For skin:"},{"ingredients":["3 tbsp pork belly fat (reserved from roasting)","1/4 cup plain flour / all-purpose flour","2 cups water","1/4 tsp freshly ground black pepper","Salt (, if needed (I usually don''t need))"],"purpose":"Gravy:"}]', '[{"title":"Score pork, rub, roll, tie, fridge dry on rack 24","description":"48 hours. Oil and salt skin, slow roast 110°C /215°F for 3 1/2 hours, transfer to new rack, drizzle with oil, crackle at 240°C//465°F for 30 - 40 minutes. Make gravy using tray drippings.","duration":35,"images":[],"step":1},{"title":"Marinate 1","description":"2 days","images":[],"step":2},{"title":"Toast spices","description":"Preheat a small pan over medium heat (no oil). Toast fennel seeds and black peppercorns, tossing regularly, for 1 1/2 to 2 minutes until the fennel seeds are lightly browned.","images":[],"step":3},{"title":"Porchetta rub","description":"Crush fennel and peppercorns into a coarse powder using a mortar and pestle, or spice grinder. Add remaining Rub ingredients and mix with a spoon - it will be like a thick wet paste.","images":[],"step":4},{"title":"Trim excess meat","description":"Pat the pork skin dry with paper towels. Cut off about ~3cm / 2.2\" meat along one long edge (leave the skin) so the pork rolls neatly. Do a mock roll-up to see how much to cut off - it''s ideal if the skin fully encloses the meat, but usually this isn''t possible. (Note 4 for tips). Reserve the trimmed meat - we be rolling it up insi","images":[],"step":5},{"description":"Score 3cm / 1.2\" diamonds into the flesh, taking care not to cut through the meat (~1 cm/0.4\" deep).","images":[],"step":6},{"title":"Rub","description":"Use your hands to spread the Rub into the flesh side, being sure to get into the cuts you made. Also rub the extra piece of pork you trimmed off.","images":[],"step":7},{"title":"Tie","description":"Place the trimmed piece of pork in the middle. Roll firmly then tie at 2.5cm/1\" intervals, starting at the centre then the ends, then working in towards. I do 8 equidistant ties on the skin (26cm / 10.5\" log, one end has meat oozing out so can’t be tied).","images":[],"step":8},{"title":"Fridge 1","description":"2 days - Place on a rack on a tray and refrigerate uncovered for 48 hours (24 hours is ok) to let the rub infuse the flesh and the skin dry so it crackles really well. 12 hours is my bare minimum!","images":[],"step":9},{"description":"Preheat oven to 130°C/265°F (120°C fan-forced) with the shelf in the middle. (Note 5)","images":[],"step":10},{"title":"Oil and salt skin","description":"Remove the rack from under the pork and wipe the tray clean. Working on the tray, rub the pork skin with 1 tablespoon of the oil, then sprinkle and rub the salt in. Salt will catch on the ties - try to spread it out evenly all over the skin, and roll the pork on the salt that falls on the tray. No need to bring pork to room temp before roasting, it can go in the oven cold.","images":[],"step":11},{"title":"Slow roast","description":"Put the pork on the rack again on a clean tray. Slow roast for 3 1/2 hours. The flesh should be pretty tender (use 2 forks to check ends) but not “fall apart” (not our goal). The skin should still be soft - this is what we want at this stage.","images":[],"step":12},{"title":"Oil and increase heat","description":"Remove the pork from the oven and turn it up to 240°C/465°F. Working quickly, transfer the pork still on the rack to a clean tray. (Keep the used tray for gravy drippings). Drizzle with the remaining 1 tablespoon of oil (don’t rub with fingers) then put it back in the oven - you want it in there as it is heating up.","images":[],"step":13},{"title":"Crackle skin","description":"Roast for 30 to 40 minutes, rotating at the 15 - 20 minute mark, until the skin is all puffy and crispy all over (top and sides).","duration":35,"images":[],"step":14},{"title":"Rest and carve","description":"Remove from the oven and leave it to rest for at least 30 minutes (up to 1 hour) before cutting the strings and slicing with a serrated knife. To keep it warm for longer, put it in a low 50°C/125°F oven after resting. Serve with gravy!","images":[],"step":15},{"title":"Reserve fat","description":"Pour all the fat off the slow-roasting tray from step 4 into a jug (don’t scrape, just pour).","images":[],"step":16},{"title":"Deglaze tray","description":"Pour 1/2 cup of water onto the tray set on a stove on medium. When the water starts simmering, use a rubber spatula to loosen all the bits stuck on the tray. (If you have an induction stove, use boiling water - that should be enough to delegate, or if needed, pop the tray in the oven).","images":[],"step":17},{"title":"Make gravy","description":"Measure out 3 tablespoons fat (from step 1) and put into a large saucepan. Heat on medium high, then add flour and stir for 1 minute. Whisk in water from deglazing tray, remains water and pepper. Simmer for 2 minutes or until it thickens. Taste, add salt if needed (I don’t). Serve with pork.","duration":1,"images":[],"step":18}]', '["gluten"]', '[]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["iconic-dishes","italian-recipes","mains","pork","pork-recipes","roasts"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2e090f03c9b0', 'en', 'US', 'Beef Empanadas', 'Recipe video above. This dough is easy to work with and comes together in seconds using a good processor. While I really encourage you to make the dough, you''ll still get an excellent empanada fix making this with store-bought puff pastry or shortcrust pastry.Empanada dough adapted from Kevin Is Cooking and the filling is based on the New York Times Cooking Beef Empanadas recipe (I found the flavour a bit mild and too dry, so I tweaked).', 'https://www.recipetineats.com/tachyon/2023/04/Beef-empanadas_7.jpg', 45, 50, 95, 10, '[{"id": "ing_flour", "quantity": {"value": 0.375, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 175.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_chorizo", "quantity": {"value": 0.12, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_potato", "quantity": {"value": 150.0, "unit": "bag of 2kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_olives", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_empanada_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_other_options", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["2 1/2 cups plain/all-purpose flour","175g/ 12 tbsp cold unsalted butter (, cut into 1 cm / 1/2\" cubes)","1 tsp cooking/kosher salt","1 egg yolk","1/2 cup warm milk (, full fat (30 sec microwave))"],"purpose":"Empanada shortcrust pastry:"},{"ingredients":["1 1/2 tbsp olive oil","1/2 onion (, finely chopped)","1 garlic cloves (, minced)","300g/10 oz beef mince (ground beef)","120g/4 oz chorizo","2 tsp tomato paste","1 tsp fresh thyme (, finely chopped)","1/2 tsp EACH dried oregano, cumin, paprika","1/4 tsp cayenne pepper","1/4 tsp cooking/kosher salt","3/4 cup chicken stock/broth (, low sodium)","1/2 cup tomato passata (sub US tomato sauce or crushed tomato)","150g/5oz potato (, peeled, cut into 8mm/ 1/3\" cubes (~1 cup))","1/3 cup green onion (, finely sliced)"],"purpose":"Empanada Filling:"},{"ingredients":["2 hard boiled eggs (9 minutes using this method)","1/4 cup green olives (, roughly chopped)","2 eggs (, separated, yolks whisked (for sealing and brushing pastry))"],"purpose":"Other:"},{"ingredients":["Empanada sauce","Other options (- ketchup, ketchup + sriracha, pink sauce, taco sauce, salsa dip)"],"purpose":"Dipping sauces:"}]', '[{"description":"Empanada Filling:","images":[],"step":1},{"title":"Blitz chorizo","description":"Roughly chop chorizo into 1.5cm / 1/2\" pieces. Blitz using a stick blender until it becomes a paste (Note 1)","images":[],"step":2},{"title":"Sauté aromatics","description":"Heat oil in a large non stick pan over high heat. Cook onion and garlic for 2 minutes.","duration":2,"images":[],"step":3},{"title":"Cook meat","description":"Add chorizo and cook for 2 minutes. Add beef and cook until you no longer see raw beef. Add tomato paste and cook for 1 minute. Then add everything else except green onion, then stir.","duration":2,"images":[],"step":4},{"title":"Cook 15 min","description":"Bring to a simmer then lower heat so it''s simmering gently. Cook for 15 minutes, stirring every now and then. Goal - juicy but not watery filling, with cooked potato.","duration":15,"images":[],"step":5},{"title":"Cool","description":"Stir through green onion. Transfer to bowl and fully cool before using (~ 2 hours).","images":[],"step":6},{"description":"Empanada shortcrust pastry:","images":[],"step":7},{"title":"Blitz dough","description":"Whisk milk and yolk in a small jug. Pulse flour, salt and butter in a food processor until the butter becomes fine crumbs - largest lumps no bigger than peas (~ 4 to 6 times). Add egg-milk mixture, then blitz on low until it comes together into a ball of dough - about 10 seconds. (Note 2 for hand method)","images":[],"step":8},{"title":"Chill 30 min","description":"Turn out onto a lightly floured work surface, then bring together into a smooth log ~20cm/8\" long. Cut in half, shape into 2cm / 0/8\" thick round discs. Wrap in cling wrap then refrigerate 30 minutes (or overnight - Note 3).","images":[],"step":9},{"title":"Cut rounds","description":"Place one chilled disc on a lightly floured work surface. Roll out to 3 mm / 0.1\" thickness. Cut 15 cm/6\" rounds (I use a bowl), or other size as desired (Note 3). Keep covered in the fridge, stacked on paper, as you continue to roll and cut. You should get 10 or 11 rounds.","images":[],"step":10},{"description":"Make empanadas:","images":[],"step":11},{"description":"Preheat oven to 220°C/425°F (200°C fan).","images":[],"step":12},{"title":"Filling","description":"Filling should be cold but spreadable (Note 4). Place 3 tablespoons (55g) of filling on the top half of a round of pastry. Spread flat in a half-moon shape, leaving a 1.5cm / 0.6\" border. Sprinkle with olive and egg.","images":[],"step":13},{"title":"Seal","description":"Brush edge with egg white, fold to enclose, pressing out air and sealing the edge. Optional: Do empanada pleats - see step photos in post or video at 3 min 30 sec. Alternatively, crimp with fork or leave plain.","images":[],"step":14},{"title":"Bake 20 min","description":"Place empanadas on 2 baking trays. Brush with egg yolk. Bake 20 minutes or until golden brown all over and crispy on the base.","images":[],"step":15},{"title":"Serve hot with dipping sauce of choice","description":"my favourite is the homemade Empanada Sauce!","images":[],"step":16}]', '["egg","gluten","milk"]', '[]', '{"mealType":["snack","dinner"],"cuisine":["Brazilian","South American"],"categories":["iconic-dishes","quiches-tart-and-pie-recipes","snacks","south-american-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c52c7aca968a', 'en', 'US', 'Toad in the hole', 'Recipe video above. The great British classic! Sausages nestled in a giant Yorkshire pudding, in all its puffed up glory, with delightfully crispy edges. The trick for stability is a dab of mayonnaise! Taught to me by an English chef, learned from his days working in pubs and restaurants in the UK. (See note 4)Some recipes will have you just bake the sausages from raw, but your gravy will be much tastier if you start with sausage drippings. So sear your sausages first!', 'https://www.recipetineats.com/tachyon/2023/02/Toad-in-the-hole_4.jpg', 15, 40, 55, 4, '[{"id": "ing_sausages", "quantity": {"value": 1.4, "unit": "pack of 500g"}}, {"id": "ing_beef", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 20.833, "unit": "carton of 12"}}, {"id": "ing_flour", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.037, "unit": "jar of 400g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 2.5, "unit": "bottle"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["700g/1.4lb pork sausages, or other sausage (8 x 85g/3oz, Note 1)","10g / 2 tsp beef drippings OR canola/veg oil (Note 4)"]},{"ingredients":["250 ml / 1 cup eggs (, lightly whisked (4-5 large eggs, yes, I need you to measure! Note 2))","1 cup plain flour (all-purpose flour)","3/4 cup milk (, full fat)","1/4 cup water","1 tbsp mayonnaise (, full-fat (secret ingredient! See Note 3))","1/2 tsp cooking salt (kosher salt)","Pinch white pepper","50g (1/4 cup) beef drippings OR canola/veg oil (Note 4)"],"purpose":"Yorkshire pudding Batter:"},{"ingredients":["30g / 2 tbsp beef drippings OR unsalted butter (Note 4)","2 onions (, halved, cut into 7 mm / 1/4\" wedges)","1 garlic clove (, finely minced)","3 tbsp plain flour (all-purpose flour)","2 cups beef stock (broth) (, low sodium)","1/2 tsp Worcestershire sauce","1/2 tsp black pepper","1/4 tsp cooking salt (kosher salt)"],"purpose":"Onion gravy:"}]', '[{"title":"Batter","description":"Whisk eggs in a bowl, then whisk in flour until lump free. Whisk in water, milk, mayonnaise, salt and pepper. Place in the fridge until required.","images":[],"step":1},{"description":"Preheat oven to 220°C/425°F (200°C fan). Put the 1/4 cup beef drippings in a 23 x 33cm metal pan (9 x 13\"). Place in the oven for 15 minutes to melt and become very hot.","duration":15,"images":[],"step":2},{"title":"Brown sausages","description":"Heat the 2 tsp (10g) of drippings in a pan over medium high heat. Brown the sausages all over, but keep one side just lightly browned (this side will brown more in the oven). Keep them raw inside. Remove onto a plate.","images":[],"step":3},{"title":"Assemble","description":"Take batter out of fridge and whisk. Working quickly, take the hot pan out of oven. Spread sausages in the pan, lightly browned side up, keeping clear of the pan walls (Note 5 for arranging tip). Pour the batter in around the sausages.","images":[],"step":4},{"title":"Bake","description":"Bake 25 minutes on the top shelf until the sides puff up and is golden brown. The top of the edges should be nice and crispy!","images":[],"step":5},{"description":"Serve immediately with onion gravy! Expect some deflation - though far less than typical recipes thanks to the mayo.","images":[],"step":6},{"description":"Onion gravy (Note 6):","images":[],"step":7},{"title":"Brown onion","description":"Add beef drippings into the pan used for browning the sausages. Melt over high heat. Add onions and cook, stirring constantly, until nicely browned (~5 minutes). Add garlic and stir 30 seconds. Add flour and stir for 1 minute so it''s well mixed through the onions (= lump-free gravy!).","duration":1,"images":[],"step":8},{"title":"Add stock","description":"Slowly pour in beef stock, stirring as you go. Add Worcestershire sauce, salt and pepper.","images":[],"step":9},{"title":"Thicken","description":"Bring to a simmer, stirring, for 2 minutes until thickens into a gravy. Keep warm until ready to use!","duration":2,"images":[],"step":10}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["British","English"],"categories":["iconic-dishes","news","sausage-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cea89452d5df', 'en', 'US', 'Borek', 'Recipe video above. If you think this Borek looks amazing, just wait until you taste it!! A spiced lamb filling littered with pine nuts and currants encased in layers up on layers of flaky filo pastry arranged in a dramatic spiral, this pastry goes by various names incuding burek, bourekas, and byrek.It''s an excellent return on effort, looking so much more difficult than it actually is to make!Vegetarian version - Use the spinach feta filling from Spanakopita!', 'https://www.recipetineats.com/tachyon/2021/07/Borek_40.jpg', 30, 60, 90, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_lamb_mince", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_cumin", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.075, "unit": "bunch"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}, {"id": "ing_currants", "quantity": {"value": 0.333, "unit": "unit"}}, {"id": "ing_pine_nuts", "quantity": {"value": 0.5, "unit": "pack of 100g"}}, {"id": "ing_tomato", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_yogurt", "quantity": {"value": 0.06, "unit": "tub of 500g"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_sheets_phyllo_pastry", "quantity": {"value": 12.0, "unit": "pack"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}]', '[{"ingredients":["2 tbsp olive oil","1 onion (, finely diced (1 small or 1/2 a large))","2 garlic cloves (, finely minced)","600g / 1.2 lb lamb mince (ie. ground lamb, or substitute beef)","1 1/2 tsp ground cumin","3/4 tsp each of ground coriander, cinnamon, paprika (plain or sweet paprika)","1/2 tsp allspice (sub mixed spice or similar spice mix)","1/2 tsp cayenne pepper or Turkish red pepper flakes (reduce for less spicy)","1/2 tsp black pepper","1 1/4 tsp salt (cooking / kosher salt, OR 1 tsp table salt)","1/3 cup currants (or raisins or sultanas, roughly chopped)","1/3 cup pine nuts (, toasted (Note 1))","1 cup tomato passata (tomato puree in US, Note 2)","1/4 cup water"],"purpose":"Lamb Filling:"},{"ingredients":["1 egg","2 tbsp plain yogurt","30g / 2 tbsp unsalted butter (, melted)"],"purpose":"Yogurt wash for filo (stops cracking):"},{"ingredients":["12 sheets phyllo pastry (Note 3)","25g / 1 1/2 tbsp unsalted butter (, melted and cooled)","White sesame seeds (optional)"],"purpose":"Pastry:"},{"ingredients":["1 cup plain yogurt","1/4 tsp garlic (, finely grated)","1 tbsp lemon juice","1 tbsp extra virgin olive oil","Pinch of salt"],"purpose":"Lemon Yogurt Sauce:"}]', '[{"title":"Cook onion and garlic","description":"Heat oil on high in a large skillet. Cook onion and garlic for 2 to 3 minutes until softened.","duration":2.5,"images":[],"step":1},{"title":"Cook lamb and spices","description":"Add lamb and cook lamb, breaking it up as you go, until mostly changes from pink to brown. Then add all the spices and cook for 1 minute.","duration":1,"images":[],"step":2},{"title":"Simmer","description":"Add tomato passata and water, mix. Then add currants and pine nuts. Bring to simmer, turn heat down to medium low and cook until liquid reduces so the mixture is moist but not watery.","images":[],"step":3},{"title":"Cool","description":"Remove from stove and allow to fully cool before using.","images":[],"step":4},{"description":"Lemon Yogurt Sauce:","images":[],"step":5},{"description":"Mix ingredients in a small bowl. Set aside for at least 20 minutes.","images":[],"step":6},{"description":"Preheat oven to 200°C / 390°F (180°C fan).","images":[],"step":7},{"title":"Yogurt Wash (Note 4)","description":"Mix ingredients until combined.","images":[],"step":8},{"title":"Prepare filo","description":"Open the filo pastry packet and unroll the pastry. Peel one layer off and place on a piece of baking / parchment paper. Cover the remainder with a lightweight damp tea towel to stop them from drying out.","images":[],"step":9},{"title":"Brush with yogurt wash","description":"Drizzle / flick yogurt wash across filo using a pastry brush. Then lightly brush across surface in a thin layer. You don''t need to cover every inch, just mostly cover the surface.","images":[],"step":10},{"title":"Layer filo","description":"Top with another filo pastry sheet, and brush this too with yogurt wash. Then repeat so you have 4 layers in total, but do not brush the last (4th) filo with yogurt wash once laid.","images":[],"step":11},{"title":"Fill and roll","description":"Place 1/3 of the Lamb filling along the bottom edge. Using the aid of a long kitchen knife to get it started, roll up into a log. Doesn''t need to be tight and don''t try, as the pastry is delicate.","images":[],"step":12},{"title":"Make 3 logs","description":"Repeat to make 3 logs, using all the Filling.","images":[],"step":13},{"description":"Shape into spiral and bake:","images":[],"step":14},{"title":"Spiral","description":"Take one log and place on a piece of baking / parchment paper. Coil into a spiral. Join a second log to the first by stuffing the ends inside each other, using yogurt wash to adhere. Continue forming the spiral. Log sides should be in contact but not tightly squished.","images":[],"step":15},{"title":"Transfer to baking vessel","description":"Brush a 26cm / 10.5″ cast iron skillet (Note 5) with melted butter. Then use the paper to transfer the borek into the skillet, and slide the paper out.","images":[],"step":16},{"title":"Brush with butter","description":"Brush the top with butter, sprinkle with sesame seeds.","images":[],"step":17},{"description":"Bake for 40 minutes or until pastry is golden.","duration":40,"images":[],"step":18},{"description":"Serve! Remove from oven. Cut wedges like pie. Serve with Lemon Yogurt Sauce!","images":[],"step":19}]', '["egg","milk","sesame"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Mediterranean","Middle Eastern","Turkish"],"categories":["iconic-dishes","lamb-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d3ec20059fd3', 'en', 'US', 'Easy slow cooker BBQ pulled pork', 'Recipe video above. This may well be the juiciest, most flavourful pulled pork you ever have in your life! Homemade BBQ Sauce totally makes it. And there''s no denying that using a slow cooker yields the juiciest pulled pork with very little effort. BIG BATCH recipe, 100% perfect for freezing, ideal for entertaining!Love this recipe? One day, try my ultimate Pulled Pork recipe.', 'https://www.recipetineats.com/tachyon/2019/11/Close-up-of-pulled-pork-with-BBQ-Sauce.jpg', 15, 600, 615, 12, '[{"id": "ing_pork_shoulder", "quantity": {"value": 3.5, "unit": "kg"}}, {"id": "ing_beer", "quantity": {"value": 0.758, "unit": "bottle of 330ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.5, "unit": "bottle of 500ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_molasses", "quantity": {"value": 45.0, "unit": "jar"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 20.0, "unit": "bottle"}}, {"id": "ing_tabasco", "quantity": {"value": 2.0, "unit": "unit"}}]', '[{"ingredients":["3.5-4.5kg/ 5-7lb pork butt / pork shoulder (, bone in, fat cap on (Note 1))","1 cup beer (, apple cider or apple juice (Note 2))"]},{"ingredients":["3 tbsp brown sugar","1 tbsp paprika powder","1 tbsp garlic powder","2 tsp onion powder","2 tsp mustard powder","1 tsp cumin powder","1 tbsp salt","1 tsp black pepper"],"purpose":"RUB:"},{"ingredients":["1 cup apple cider vinegar (Note 3)","3 cups tomato ketchup (or Aussie tomato sauce)","1 cup water (or use remaining beer!)","3 tbsp molasses (, orginal (not blackstrap, Note 4))","2/3 cup brown sugar","4 tsp mustard powder","3 tsp garlic powder","4 tsp Worcestershire sauce","2 tsp salt","2 tsp black pepper","2 tsp Tabasco ( or cayenne pepper (optional, for spiciness))"],"purpose":"BBQ Sauce:"}]', '[{"description":"Mix the Rub together, then rub all over the pork.","images":[],"step":1},{"description":"Place in a slow cooker, pour over beer. Slow cook on low for 10 hours. Pork should be tender enough to easily shred.","images":[],"step":2},{"description":"Browning in oven (optional, recommended):","images":[],"step":3},{"description":"Preheat oven to 180°C / 350°F.","images":[],"step":4},{"description":"Transfer from slow cooker into a roasting pan (reserve liquid).","images":[],"step":5},{"description":"Scoop fat off surface of juices in slow cooker and drizzle over pork (about 1/3 cup), then roast pork for 20 minutes.","duration":20,"images":[],"step":6},{"description":"Remove from oven, cut thick layer of fat off top and discard. Spoon over 1/4 cup fat from slow cooker juices, then roast 15 minutes.","images":[],"step":7},{"description":"Shred pork using 2 forks. Pour over BBQ sauce, toss gently.","images":[],"step":8},{"description":"Serve stuffed in sliders with Coleslaw, or make a Southern dinner plate with Coleslaw, Mac and Cheese, Corn bread, steamed corn & green beans tossed in butter, with Margaritas to quench your thirst!","images":[],"step":9},{"description":"Barbecue Sauce:","images":[],"step":10},{"description":"Place all ingredients in a saucepan and simmer over medium heat, stirring occasionally, for 45 minutes or until thickened.","duration":45,"images":[],"step":11},{"title":"Add 3/4","description":"1 cup of juices from slow cooker until sauce is syrup consistency.","images":[],"step":12},{"title":"Adjust to taste","description":"sweetness with brown sugar / honey, salt and sour with vinegar. Use per recipe.","images":[],"step":13}]', '["mustard"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["BBQ","Southern","Texas","Western"],"categories":["iconic-dishes","pork-recipes","sandwiches-and-sliders","sauces","slow-cooked-fall-apart","slow-cooker-recipes","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_032482eb232b', 'en', 'US', 'Reuben Sandwich recipe!', 'Recipe VIDEO above. The iconic Reuben Sandwich made famous by Katz''s Deli in New York, made at home! Hands down still one of the best sandwiches I have ever had in my life, the most incredible combination of ingredients, the star of which is warm fall-apart tender homemade pastrami!', 'https://www.recipetineats.com/tachyon/2019/04/Reuben-Sandwich_8-copy.jpg', 20, 15, 35, 5, '[{"id": "ing_homemade_pastrami", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_bread", "quantity": {"value": 0.5, "unit": "loaf"}}, {"id": "ing_cheese", "quantity": {"value": 10.0, "unit": "block of 250g"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_grapes", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_cabbage", "quantity": {"value": 7.0, "unit": "head"}}, {"id": "ing_vinegar", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_caraway_seeds", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_dill_pickle_gherkin", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.281, "unit": "jar of 400g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.15, "unit": "tub of 250g"}}, {"id": "ing_chilli", "quantity": {"value": 0.375, "unit": "pack of 100g"}}, {"id": "ing_horseradish_to_taste", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_paprika", "quantity": {"value": 0.031, "unit": "jar of 40g"}}]', '[{"ingredients":["1 kg / 2 lb homemade pastrami (1 quantity, easy!) (Note 1)","10 slices light rye bread","10 slices Swiss cheese","Butter (, for spreading)"]},{"ingredients":["1 tbsp grapeseed oil","1/2 onion (, thinly sliced)","350g/ 12 oz white cabbage (, thinly shredded (1/4 large head, 6 - 8 big handfuls))","1 1/4 cups (300ml) cider vinegar","1/3 cup (85 ml) water","1 tsp salt","2 tsp sugar","1 tsp caraway seeds (, optional (Note 2))"],"purpose":"Quick Sauerkraut:"},{"ingredients":["1 tbsp onion (, finely minced)","1 tbsp dill pickle/gherkin (, finely minced)","3/4 cup mayonnaise","1/4 cup sour cream (can sub more mayo)","2.5 tbsp sriracha, spicy ketchup or Chili Sauce (or 1/4 cup ketchup + 2 tsp tabasco) (Note 3)","3 tsp horseradish (jar), to taste (spicy/tang)","1 tsp Worcestershire sauce","1/4 tsp sweet paprika"],"purpose":"Russian Dressing:"}]', '[{"description":"Russian Dressing:","images":[],"step":1},{"description":"Mix ingredients, refrigerate 20 minutes+ (keeps 2 weeks).","images":[],"step":2},{"description":"Quick Sauerkraut:","images":[],"step":3},{"description":"Dissolve sugar and salt in vinegar.","images":[],"step":4},{"description":"Heat oil in a large pot over medium heat. Add onion and cook for 2 minutes to soften, don''t let it brown.","duration":2,"images":[],"step":5},{"description":"Add cabbage, vinegar, water and caraway seeds, give it a toss.","images":[],"step":6},{"description":"Cover, cook on low for 15 minutes, mixing once at 10 minutes.","duration":15,"images":[],"step":7},{"description":"Transfer to container (including liquid), cool until just warm. Keeps 2 weeks in the fridge.","images":[],"step":8},{"description":"Prepare Pastrami:","images":[],"step":9},{"description":"Thinly slice still cold pastrami (Note 1). Place in a container with a couple of tablespoons of pastrami liquid (reserved from cooking, see pastrami recipe).","images":[],"step":10},{"description":"Microwave to warm through (or use other method of choice etc cover with foil and place in oven).","images":[],"step":11},{"description":"Assemble Reuben:","images":[],"step":12},{"description":"Preheat grill/broiler to medium high with shelf about 25cm/10\" from heat source.","images":[],"step":13},{"description":"Toast bread. Spread with butter, then 1 tbsp Russian Dressing on each piece.","images":[],"step":14},{"description":"Pick up pastrami and let excess juices drip away, then place on bread.","images":[],"step":15},{"description":"Do same for sauerkraut, pile onto pastrami, then top with cheese.","images":[],"step":16},{"description":"Also place cheese on other slice of bread (ie with just Russian Dressing).","images":[],"step":17},{"description":"Place under grill until cheese is just melted. Sandwich together and devour while hot!","images":[],"step":18}]', '["gluten","milk"]', '["vegetarian"]', '{"mealType":["dinner"],"cuisine":["American","Jewish"],"categories":["iconic-dishes","sandwiches-and-sliders","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_44b2542af5ea', 'en', 'US', 'Carnitas (Mexican Slow Cooker Pulled Pork)', 'Recipe VIDEO above. Spiciness: Not at all. Scale recipe using Servings slider.These carnitas capture that elusive combination of flavourful, juicy AND crispiness. Pan frying to get the golden bits is not optional! Broiling/grilling will not produce the same results. Stuff them in tacos for an authentic Carnitas Tacos experience, see notes for other uses! FAQ below recipe.', 'https://www.recipetineats.com/tachyon/2018/05/Pork-Carnitas-1000px.jpg', 15, 360, 375, 10, '[{"id": "ing_pork_shoulder", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.013, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_jalapeno", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 6.667, "unit": "pack of 3 heads"}}, {"id": "ing_oranges", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}]', '[{"ingredients":["2 kg / 4 lb pork shoulder (pork butt) (, skinless, boneless (5lb/2.5kg bone in) (Note 1))","2 1/2 tsp salt","1 tsp black pepper","1 onion (, chopped)","1 jalapeno (, deseeded, chopped)","4 cloves garlic, minced","3/4 cup juice from orange (2 oranges)"]},{"ingredients":["1 tbsp dried oregano","2 tsp ground cumin","1 tbsp olive oil"],"purpose":"Rub"}]', '[{"description":"Rinse and dry the pork shoulder, rub all over with salt and pepper.","images":[],"step":1},{"description":"Combine the Rub ingredients then rub all over the pork.","images":[],"step":2},{"description":"Place the pork in a slow cooker (fat cap up), top with the onion, jalapeño, minced garlic (don''t worry about spreading it) and squeeze over the juice of the oranges.","images":[],"step":3},{"description":"Slow Cook on low for 10 hours or on high for 7 hours. (Note 2 for other cook methods)","images":[],"step":4},{"description":"Pork should be tender enough to shred. Remove from slow cooker and let cool slightly. Then shred using two forks.","images":[],"step":5},{"title":"Optional","description":"Skim off the fat from the juices remaining in the slow cooker and discard.","images":[],"step":6},{"description":"If you have a lot more than 2 cups of juice, then reduce it down to about 2 cups. The liquid will be salty, it is the seasoning for the pork. Set liquid aside - don''t bother straining onion etc, it''s super soft.","images":[],"step":7},{"description":"Heat 1 tbsp of oil in a large non stick pan or well seasoned skillet over high heat. Spread pork in the pan, drizzle over some juices. Wait until the juices evaporate and the bottom side is golden brown and crusty. Turn and just briefly sear the other side - you don''t want to make it brown all over because then it''s too crispy, need tender juicy bits.","images":[],"step":8},{"description":"Remove pork from skillet. Repeat in batches (takes me 4 batches) - don''t crowd the pan.","images":[],"step":9},{"description":"Just before serving, drizzle over more juices and serve hot, stuffed in tacos (see notes for sides, other serving suggestion and storage/make ahead).","images":[],"step":10}]', '[]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["main_course"],"cuisine":["Mexican"],"categories":["dinner-tonight","iconic-dishes","main-dishes","mexican-recipes","most-popular","pork-carnitas","pork-recipes","quick-and-easy","slow-cooked-fall-apart","slow-cooker-recipes","taco-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ca6f84ac8c5d', 'en', 'US', 'Gozleme!!', 'Recipe video above. Crispy Turkish flatbreads stuffed with juicy fillings! Choose ONE Filling - either Spinach and Feta, or spiced Lamb OR Beef with spinach and peppers. Can stretch to 5 gozlemes. Works with GLUTEN FREE flour too!', 'https://www.recipetineats.com/tachyon/2019/03/Spinach-Feta-Gozleme.jpg', 30, 20, 50, 4, '[{"id": "ing_flour", "quantity": {"value": 0.375, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_baby_spinach", "quantity": {"value": 300.0, "unit": "bag of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_feta_cheese", "quantity": {"value": 300.0, "unit": "block of 200g"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.6, "unit": "pack of 125g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_lamb_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_cumin", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cayenne", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}]', '[{"ingredients":["2.5 cups (375g) flour (, plain/all purpose (GF Note 4))","1/3 cup (85ml) extra virgin olive oil","3/4 cup (185ml) water","1/2 tsp salt"],"purpose":"Gozleme pastry:"},{"ingredients":["300g / 10oz baby spinach","2 garlic cloves (, minced)","2 eggs","1 tsp black pepper","300g / 10 oz Danish feta (soft feta, Note 2)","2 cups (200g) shredded mozzarella cheese (Note 3)"],"purpose":"Spinach & Feta:"},{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","1 onion (, finely chopped)","500g / 1 lb beef or lamb mince (ground)","1 capsicum / bell pepper (, chopped)","90g / 3 oz baby spinach","1.5 tsp cumin powder","1 tsp paprika","1/2 tsp cayenne (adjust spiciness to taste)","3/4 tsp each salt and pepper","1 tbsp water","120g / 4 oz Danish feta (Note 2)"],"purpose":"Spiced Lamb or Beef:"},{"ingredients":["1 - 1.5 tbsp olive oil (, per gozleme)","Lemon wedges (optional)"],"purpose":"Cooking / Serving:"}]', '[{"description":"Fit stand mixer with dough hook. Combine flour, oil, salt and water in the stand mixer bowl. Mix for 2.5 minutes on medium high speed 7 until smooth (see video for before & after). (Note 4) Dough should be a pliable, smooth ball, not sticky.","images":[],"step":1},{"description":"Cover and rest for 20 minutes.","duration":20,"images":[],"step":2},{"description":"Sprinkle work surface with flour. Cut dough into 4 pieces.","images":[],"step":3},{"description":"Roll out into 35cm/14\" x 20cm/8\" rectangle.","images":[],"step":4},{"description":"Make EITHER the lamb / beef Filling, or Spinach & Feta (or make 1/2 batch of both!).","images":[],"step":5},{"description":"Lamb or Beef Filling:","images":[],"step":6},{"description":"Heat oil in large skillet over high heat.","images":[],"step":7},{"description":"Cook garlic and onion for 1 minute. Add capsicum, cook for 2 minutes.","duration":1,"images":[],"step":8},{"description":"Add beef and cook until it changes from pink to brown, breaking it up as you go.","images":[],"step":9},{"description":"Add cumin, paprika, cayenne (if using), salt, pepper and water. Cook for 2 minutes.","duration":2,"images":[],"step":10},{"description":"Add spinach, stir until wilted.","images":[],"step":11},{"description":"Cool before using.","images":[],"step":12},{"description":"Spinach Feta Filling:","images":[],"step":13},{"description":"Place spinach, garlic, egg and pepper in a bowl. Scrunch with hands to reduce volume and make spinach \"floppy\".","images":[],"step":14},{"description":"Add feta and stir through.","images":[],"step":15},{"description":"Making Gozleme:","images":[],"step":16},{"description":"Spread Filling on half the pastry, pushing to the edge. Sprinkle Lamb/Beef Filling with crumbled feta. Sprinkle Spinach Feta with mozzarella cheese, if using.","images":[],"step":17},{"description":"Fold other side of pastry over to cover Filling. Press down edges, pressing out excess air pockets trapped inside as you go. Use water if needed to seal well.","images":[],"step":18},{"description":"Sprinkle flour on a round pizza paddle (or similar). Slide gozleme onto paddle.","images":[],"step":19},{"description":"Cooking:","images":[],"step":20},{"description":"Heat 1.5 tbsp oil in a large skillet over medium high heat. (I usually get 2 pans going)","images":[],"step":21},{"description":"Slide gozleme into skillet. Cook, lightly pressing down (including edges), until deep golden and crispy - about 3 minutes. Flip and cook, pressing down lightly, until crispy.","images":[],"step":22},{"description":"Transfer to cutting board. Cut into 6 or 8 pieces.","images":[],"step":23},{"description":"Serve immediately with lemon wedges, if desired.","images":[],"step":24}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner","snack"],"cuisine":["Turkish"],"categories":["iconic-dishes","mediterranean-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2651fd03a86e', 'en', 'US', 'Peanut Butter Caramel Pie', 'Recipe video above. Tastes like a snickers bar, in pie form! A cookie crust with a creamy, soft set peanut butter caramel filling. This is sweet and rich (being that it''s caramel) so it should serve 12 people easily, possibly more.', 'https://www.recipetineats.com/tachyon/2019/02/Peanut-Butter-Caramel-Pie_4a.jpg', 20, 15, 35, 12, '[{"id": "ing_oreo_cookies", "quantity": {"value": 274.0, "unit": "pack"}}, {"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.25, "unit": "carton of 250ml"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.4, "unit": "jar of 375g"}}, {"id": "ing_cream", "quantity": {"value": 0.25, "unit": "carton of 250ml"}}, {"id": "ing_chocolate", "quantity": {"value": 150.0, "unit": "block of 100g"}}, {"id": "ing_peanuts", "quantity": {"value": 0.094, "unit": "jar"}}]', '[{"ingredients":["274g / 9.5 oz Oreo cookies (2 standard packs/rows - Note 1)","60g / 4 tbsp butter (, melted)","Pinch of salt"],"purpose":"Crust:"},{"ingredients":["100g (7 tbsp) unsalted butter","1/2 cup (110g) (packed) brown sugar","1 can sweetened condensed milk (395g/14oz)","1/4 cup (65ml) cream (, any type, full fat (not low fat))","1 tsp salt","1 cup (280g) peanut butter, smooth (Note 2)"],"purpose":"Peanut Butter Caramel:"},{"ingredients":["1/3 cup (85ml) heavy/thickened cream (Note 3a)","150g / 5 oz milk chocolate chips (or other of choice, Note 3b)","1/4 cup roughly chopped peanuts"],"purpose":"Topping:"}]', '[{"description":"Grease and line the base only of a 23cm / 9\" tart tin with a loose base, or pie dish. (Or a springform pan of a similar size).","images":[],"step":1},{"description":"Preheat oven to 160C / 325F (all oven types).","images":[],"step":2},{"description":"Blitz biscuits in food processor until they are fine crumbs.","images":[],"step":3},{"description":"Add butter and blitz until it looks like wet sand (scrape sides/base if needed).","images":[],"step":4},{"description":"Pour into tin, spread out then then press firmly into base and sides – use something flat like a cup to assist. Transfer to a baking tray for ease of handling.","images":[],"step":5},{"description":"Melt butter in a large saucepan over medium heat. Add sugar, and stir until sugar is melted. Butter may not incorporate fully. Don''t let it bubble away for ages, just until sugar is melted.","images":[],"step":6},{"description":"Turn stove off.","images":[],"step":7},{"description":"Working quickly, pour in the condensed milk & cream, whisking as you go. Once incorporated, add peanut butter and salt, and stir until smooth.","images":[],"step":8},{"description":"Pour into crust and bake for 12 minutes or until the surface has a wrinkly “skin” on it.","duration":12,"images":[],"step":9},{"description":"Cool for 20 minutes.","duration":20,"images":[],"step":10},{"description":"Place cream and chocolate in a heat proof bowl. Microwave in 2 x 30 second bursts, stirring in between, until smooth.","images":[],"step":11},{"description":"Pour over cooled caramel filling. Leave for 10 minutes to firm up slightly then sprinkle with peanuts.","duration":10,"images":[],"step":12},{"description":"Refrigerate for 2 hours to allow chocolate to set.","images":[],"step":13},{"description":"Remove from fridge and bring to room temperature before slicing to serve.","images":[],"step":14}]', '["milk","peanuts"]', '["gluten_free","vegetarian"]', '{"mealType":["dessert"],"cuisine":[],"categories":["dessert-recipes","iconic-dishes","sweet-pies"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0d694c1ea5a2', 'en', 'US', 'Chocolate Mousse', 'Recipe video above. Light and airy yet rich, this is a Chocolate Mousse made the classic French way, as served in fine dining restaurants. Less cream, richer mouth feel, true chocolate flavour. It''s actually quite straight forward to make! Excellent dessert for dinner parties because they keep 100% perfectly in the fridge for 2 days, they''re elegant and indulgent but not heavy and overly sweet.See notes section for comment on raw eggs (yes it''s essential to make mousse properly).', 'https://www.recipetineats.com/tachyon/2018/09/Chocolate-Mousse_9.jpg', 20, 0, 20, 4, '[{"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_chocolate", "quantity": {"value": 125.0, "unit": "block of 100g"}}, {"id": "ing_butter", "quantity": {"value": 10.0, "unit": "block of 250g"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_chocolate", "quantity": {"value": 125.0, "unit": "block of 100g"}}]', '[{"ingredients":["3 eggs (~55g/2 oz each)","125g / 4.5 oz 70% cocoa chocolate or bittersweet chocolate, (, break or cut into small 1 cm / 0.2\" pieces (Note 1))","10g / 0.3 oz unsalted butter","1/2 cup cream (, full fat (Note 2))","3 tbsp caster sugar (superfine white sugar)"]},{"ingredients":["More whipped cream","Chocolate shavings (Note 3)"],"purpose":"Decorations:"}]', '[{"description":"For reliable results, work at a steady pace so your whipped egg whites and cream do not get too warm!","images":[],"step":1},{"description":"Separate eggs and yolks while eggs are cold. Place whites in a large bowl and yolks in a small bowl. Leave whites while you prepare other ingredients. (Note 4)","images":[],"step":2},{"description":"Whisk yolks until uniform.","images":[],"step":3},{"title":"Melt chocolate and butter","description":"Place chocolate in a microwave-proof bowl with the butter. Melt in the microwave in 20 second bursts, stirring in between, until smooth. (Stir in optional flavourings at this point, but read Note 6 first). Set aside to cool slightly while you proceed with other steps - we want it at room temperature but still pourable.","images":[],"step":4},{"title":"Whip cream","description":"Beat cream until stiff peaks form, being careful not to over-whip (see video).","images":[],"step":5},{"title":"Whip whites","description":"Clean the whisks. Add sugar into the egg whites bowl. Beat until firm peaks form. GOAL - flopping \"elf hat\"! (see video and Note 5 for what this means).","images":[],"step":6},{"description":"Fold together all ingredients:","images":[],"step":7},{"title":"Yolks and cream","description":"Fold egg yolks into cream using a rubber spatula - 8 folds max. Some streaks is fine.","images":[],"step":8},{"title":"Check chocolate temperature","description":"The chocolate should be cooled to room temperature but still runny (minimum 35°C / 95°F; ideal 40°C / 104°F). If too cool or thick, microwave in burst of 5 seconds at a time until runny.","images":[],"step":9},{"title":"Chocolate into cream","description":"Pour chocolate into cream yolk mixture. Fold through - 8 folds max. Some streaks here are ok.","images":[],"step":10},{"title":"Fold in egg whites","description":"Add 1/4 of beaten egg whites into chocolate mixture. Fold through until incorporated - \"smear\" the spatular across surface to blend white lumps in - aim for 10 folds.","images":[],"step":11},{"description":"Pour chocolate mixture into egg whites. Fold through until incorporated and no more white lumps remain - aim for 12 folds max, but ensure there are no obvious egg white patches.","images":[],"step":12},{"title":"Chill in fridge","description":"Divide mixture between 4 small glasses or pots. Refrigerate for at least 6 hours, preferably overnight.","images":[],"step":13},{"description":"To serve, garnish with cream and chocolate shavings. Raspberries and a tiny sprig of mint for colour would also be lovely!","images":[],"step":14}]', '["egg","milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["French","Western"],"categories":["dessert-recipes","iconic-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0151e07f93dd', 'en', 'US', 'Mexican Fiesta Menu', 'Round up the amigos for a Mexican Fiesta! The suggested menu plan below is a great low-effort one with wow factor. Plenty for making ahead and the Carnitas freeze perfectly! See recipes linked to each dish, or where not linked, directions are below. Cook time includes slow cooking time for Carnitas.', 'https://www.recipetineats.com/tachyon/2018/05/Mexican-Fiesta.jpg', 60, 600, 660, 8, '[{"id": "ing_pork", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_restaurant_style_salsa", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_authentic_guacamole", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_red_cabbage", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_tortillas", "quantity": {"value": 1.0, "unit": "pack of 8"}}, {"id": "ing_tortillas", "quantity": {"value": 1.0, "unit": "pack of 8"}}, {"id": "ing_corn", "quantity": {"value": 0.003, "unit": "can of 400g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_chicken", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_shrimp", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_pico_de_gallo", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_queso_dip", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_corn", "quantity": {"value": 0.003, "unit": "can of 400g"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_corn", "quantity": {"value": 0.003, "unit": "can of 400g"}}, {"id": "ing_pig_out_salsa", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_rice", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_refried_beans", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_hot_sauce", "quantity": {"value": 1.0, "unit": "bottle of 150ml"}}, {"id": "ing_jalapeno", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_churros", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["Pork Carnitas","Restaurant style salsa (doubles as taco sauce + dip)","Authentic Guacamole","Pickled red cabbage (Note 1)","Warmed tortillas","Homemade tortilla chips (see below)","Grilled corn (See below)","Sour Cream","Chopped white onions (Note 2)","Coriander/cilantro leaves (whole or chopped)","Lime wedges"],"purpose":"Mexican Fiesta menu plan (as pictured in post):"},{"ingredients":["Marinated Chicken for tacos","Lime marinated chicken","Chicken Fajitas","Mexican Shredded Chicken","Beef Fajitas","Mexican Shredded Beef","Fish Tacos","Prawn/shrimp Tacos"],"purpose":"Other Protein options:"},{"ingredients":["Pico de Gallo","Queso Dip (stays silky when cool!)","Mexican Corn Salad","Avocado Corn Salad","Mexican Grilled Corn with Chipotle Adobo Sauce","Pig Out Salsa (Chorizo and Corn)","Mexican Red Rice","Refried Beans (Note 3)","Shredded Cheeses","Avocado Slices (instead of guac)","Hot Sauces","Sliced Jalapeno"],"purpose":"Other Side options:"},{"ingredients":["Churros (quick, and great for make ahead)"],"purpose":"To Finish:"}]', '[{"description":"Choose one or two proteins, then sides of choice. See linked recipes for directions (except tortilla chips and grilled corn, see below).","images":[],"step":1},{"title":"Main Taco Filling Selection","description":"The most convenient big batch protein is Pork Carnitas because it freezes great and only requires a quick pan fry to freshen up, and stays good for several hours (tips are in Carnitas recipe notes). The Shredded Chicken and Beef are almost as good (pork is slightly juicier) and stored similarly. The next simplest is Fish Tacos because it''s very quick to cook, then just put them in a serving dish and break into chunks with fork. If you want to use one of the chicken recipes to make ahead, use boneless thigh fillets, cook, then keep whole, cover and cool, reserve every drop of leached juice. Before serving, chop/slice, cover and microwave reheat.","images":[],"step":2},{"title":"Taco Fixings","description":"I like to have at least one fresh thing to stuff in tacos (pickled cabbage is my choice in this Fiesta), + a sauce (the Restaurant Style Salsa,) + avocado in some form (guac or slices or in Pico de Gallo) + coriander/cilantro. Chopped white onion is very common in Mexico, and Tex Mex fans such as myself will almost always have sour cream and shredded cheese too!","images":[],"step":3},{"title":"Other Sides","description":"Tortillas + things to stuff in tortillas usually makes for a satisfying meal in itself, but to round things out I usually provide a salad or vegetables of some form. Plain grilled corn is very on theme!","images":[],"step":4},{"description":"Directions (for items listed above without recipe link):","images":[],"step":5},{"title":"Homemade Tortillas Chips","description":"Chop corn tortillas to desired shape, fry in oil until crisp and light golden. Transfer for paper towel, sprinkle with salt while hot.","images":[],"step":6},{"title":"Grilled Corn","description":"Grill corn on BBQ over high heat until nicely charred. Brush with melted salted butter and sprinkle with chipotle powder (or chilli or cayenne, to taste)","images":[],"step":7}]', '["fish","milk","shellfish"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["iconic-dishes","mexican-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6881b7104693', 'en', 'US', 'Vegetable Samosa Pie', 'Recipe video above. Take everything you know about samosas - the curried mashed potato filling, the crispy pastry - put it in giant pie form, add a stack of extra vegetables and voila! Vegetable Samosa Pie! This is a big, vegetarian main course dinner that''s something different yet also familiar, and wonderfully versatile - stuff with any veggies you want.Simplify SPICES: I''ve stayed true to traditional Samosa filling, so there''s a fairly lengthy list of spices. It can be drastically simplified - see Notes 1 to 3.SPICINESS: Very mild - just a slight warmth. Dial it up if you want, or omit it!Blind baking / Crispy Base: See Note 5.Those who tried the South Indian Eggplant Curry I shared last week will love the common ingredients in this!', 'https://www.recipetineats.com/tachyon/2020/08/Vegetable-Samosa-Pie__2.jpg', 15, 100, 115, 6, '[{"id": "ing_potato", "quantity": {"value": 700.0, "unit": "bag of 2kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.037, "unit": "jar of 200g"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_fennel_seeds", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_curry_leaves", "quantity": {"value": 15.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_turmeric", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.2, "unit": "jar of 50g"}}, {"id": "ing_chilli", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_tomato", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_zucchini", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_cauliflower", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sheet_puff_pastry", "quantity": {"value": 2.0, "unit": "pack"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["700g / 1.4lb potato (, cut into 2cm / 4/5\" pieces)"]},{"ingredients":["3 tbsp vegetable oil","1.5 tsp black mustard seeds (Note 1)","1 tsp cumin seeds (Note 2)","1 tsp fennel seeds (Note 2)","15 curry leaves (, fresh (Note 3))","1 tbsp garlic (, finely grated)","1 tbsp ginger (, finely grated)","1 onion (, finely chopped (brown, white, yellow))","1/2 tsp turmeric powder","2 tsp curry powder (Note 4)","1/2 tsp chilli powder (, adjust spiciness to taste (pure ground, not US Chili Spice Mi, sub cayenne)","1 tbsp tomato paste","1 tomato * (, chopped into 1.5cm / 1/2\" pieces)","1 zucchini * (, chopped into 1.5cm / 1/2\" pieces)","1 carrot * (, chopped into 1.5cm / 1/2\" pieces)","1/2 cauliflower * (small), cut/broken into small florets (~ 3 cups)","1/2 tsp black pepper","1 tsp salt","2 cups water","1 cup frozen green peas *"],"purpose":"Filling:"},{"ingredients":["2 sheets puff pastry (Note 5)","1 egg (, lightly whisked)"],"purpose":"Puff pastry crust:"},{"ingredients":["Plain yogurt","Coriander/cilantro leaves (, option (decorative only, pictured))"],"purpose":"Serving:"}]', '[{"description":"Bring a pot of water to the boil then cook potato for 12 - 15 minutes until very soft.","duration":13.5,"images":[],"step":1},{"description":"Drain, mash and set aside.","images":[],"step":2},{"title":"Sizzling spices","description":"Heat oil in a dutch oven or pot over high heat. Add black mustard seeds, cumin and fennel seeds. Let them sizzle for 15 seconds - careful, they might pop!","duration":0.25,"images":[],"step":3},{"title":"Curry leaves","description":"Then add curry leaves and stir for 15 seconds.","duration":0.25,"images":[],"step":4},{"title":"Aromatics","description":"Add garlic, ginger and onion. Cook for 4 to 5 minutes until onion is tinged with gold.","duration":4.5,"images":[],"step":5},{"title":"Tomato","description":"Add tomato paste and tomato, cook for 30 seconds.","duration":0.5,"images":[],"step":6},{"title":"Spices","description":"Add curry powder, turmeric and chilli. Cook for 30 seconds.","duration":0.5,"images":[],"step":7},{"title":"Most Veg","description":"Add zucchini, carrot and cauliflower. Stir well to coat in the spice paste.","images":[],"step":8},{"title":"Water","description":"Add water, salt and pepper. Stir, bring to a simmer then put the lid on and reduce heat to medium low (so it''s simmer gently).","images":[],"step":9},{"title":"Cook & reduce","description":"Cook for 15 minutes until vegetables are soft. Then remove lid and simmer for 5 minutes to reduce liquid a bit.","duration":15,"images":[],"step":10},{"title":"Add mash","description":"Remove from stove. Add peas and potato, mix through well.","images":[],"step":11},{"title":"Taste","description":"Taste and add more salt and pepper if needed.","images":[],"step":12},{"title":"Cool","description":"Place lid on and cool for at least 30 minutes (even overnight is fine).","images":[],"step":13},{"description":"Preheat oven to 180°C/350°F (all oven types).","images":[],"step":14},{"description":"Grease a large pie dish with butter, or oil spray (Note 6). Drape in a puff pastry sheet.(I don''t blind bake here - see Note 5)","images":[],"step":15},{"title":"Fill with Filling","description":"slightly mounded is fine.","images":[],"step":16},{"description":"Fold in the corners of the puff pastry sheet.","images":[],"step":17},{"title":"Top with puff pastry sheet","description":"turn 90 degrees to the base puff pastry sheet (see photo).","images":[],"step":18},{"title":"Fold the overhang puff pastry under itself","description":"no need to be neat here, this is a rustic pie!","images":[],"step":19},{"title":"Egg wash","description":"Brush with egg, cut a 2cm / 1\" cross in the middle (to let steam escape).","images":[],"step":20},{"description":"Bake 50 to 60 minutes, until the top is very deep golden and flaky.","images":[],"step":21},{"description":"Stand 5 minutes then slice to serve. A dollop of plain yogurt goes well with this!","images":[],"step":22}]', '["egg","milk","mustard"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["indian-recipes","main-dishes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9f7f1dec97e5', 'en', 'US', 'Curried Rice (Basmati rice)', 'Recipe video above. You need more than just curry powder for a great Curried Rice! Basmati adds a beautifully nutty aroma to this rice recipe. Spiciness: Warm hum, not overly spicy. Not intended to be a full-on authentic Indian recipe, but leans more towards Indian than unflavourful Western curry recipes (you know the type I mean!)', 'https://www.recipetineats.com/tachyon/2019/02/Curried-Rice_3.jpg', 10, 20, 30, 6, '[{"id": "ing_curry_powder", "quantity": {"value": 0.3, "unit": "jar of 50g"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_paprika", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_chilli", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_butter", "quantity": {"value": 40.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.338, "unit": "kg"}}, {"id": "ing_frozen_peas", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cashews", "quantity": {"value": 150.0, "unit": "jar"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}]', '[{"ingredients":["3 tsp yellow curry powder (Note 1)","1 tsp cumin","1 tsp coriander","1/2 tsp paprika","1/2 tsp chilli powder (adjust spiciness to taste) (Note 2)"],"purpose":"Spices:"},{"ingredients":["40g (3 tbsp) butter (or ghee or oil) (Note 3)","1 onion (, finely chopped)","3 garlic cloves (, minced)","2 tsp ginger (, finely chopped or grated)","1 1/2 cups (275g) uncooked basmati rice (Note 4)","2 small carrot (, peeled and grated)","2 1/4 cups (560 ml) chicken or vegetable broth, low sodium (Note 5)","2 cups (300g) frozen peas","1 1/4 tsp salt","1/2 tsp black pepper"],"purpose":"Rice:"},{"ingredients":["1 cup (150g) cashews (, roasted, unsalted)","1/2 cup coriander/cilantro leaves (, finely chopped)","Yogurt (, for serving (optional))"],"purpose":"Finishes:"}]', '[{"description":"Rinse rice until water runs pretty clear, then drain well. (Note 4)","images":[],"step":1},{"description":"Melt butter in a small to medium pot (or large saucepan) over medium high heat.","images":[],"step":2},{"description":"Add garlic and ginger, cook 30 seconds. Add onion and cook for 2 minutes until partly translucent.","duration":2,"images":[],"step":3},{"title":"Add carrot and cook for 2","description":"3 minutes until softened and sweet.","duration":2.5,"images":[],"step":4},{"description":"Add rice and stir to coat all the grains in the oil.","images":[],"step":5},{"description":"Add Spices and mix to coat the rice.","images":[],"step":6},{"description":"Add broth, peas, salt and pepper, stir. If any rice is protruding above the surface, poke it under the liquid.","images":[],"step":7},{"description":"When the entire surface of the liquid is simmering, stir once, place lid on and immediately turn heat down to LOW.","images":[],"step":8},{"description":"Cook for 14 minutes, do not peek while cooking!","duration":14,"images":[],"step":9},{"description":"Lift lid slightly and quickly tilt pot to check to ensure liquid has been absorbed. Clamp lid back on and remove from heat.","images":[],"step":10},{"description":"Stand for 10 minutes, undisturbed.","duration":10,"images":[],"step":11},{"description":"Use a rubber spatula to gently fluff the rice. (Note 6)","images":[],"step":12},{"description":"Add most of the cashews and coriander, stir through.","images":[],"step":13},{"description":"Transfer to serving bowl, sprinkle with remaining cashews and coriander. See in post for serving ideas.","images":[],"step":14}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Indian"],"categories":["dinner-tonight","indian-recipes","quick-and-easy","rice-recipes","rice-side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f0c188701c73', 'en', 'US', 'Tuna Carpaccio', 'Recipe video above. If you are like me and love anything carpaccio, then you’ll love this one! This is a simple yet fancy recipe, similar to one I used to make at a restaurant I''ve worked at, that you can easily make at home to impress your family or guests. The tuna is gently brushed with a lemon vinaigrette, seasoned then topped with pickled onion and freshly chopped chive. Serves 2 as an entrée or 4 as nibbles, perfect to start a meal or share.', 'https://www.recipetineats.com/tachyon/2026/04/Tuna-Carpaccio_3.jpg', 20, 0, 20, 2, '[{"id": "ing_tuna", "quantity": {"value": 0.12, "unit": "kg"}}, {"id": "ing_chilli_flakes", "quantity": {"value": 0.016, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 2.0, "unit": "jar of 50g"}}, {"id": "ing_chive", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_few_edible_flowers", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.25, "unit": "pack of 1kg"}}, {"id": "ing_vinegar", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_bread", "quantity": {"value": 12.0, "unit": "loaf"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}]', '[{"ingredients":["120g / 4.2oz g tuna (, skinless, boneless, cut into 2 pieces (sashimi-grade preferably) (Note 1))","1/8 tsp sea salt flakes (, or 1 large pinch cooking salt / kosher salt, or small pinch table salt)","2 pinches Espelette pepper (, or 1 pinch chilli powder or black pepper (Note 2))","½ tsp finely chopped chive","Few edible flowers (optional)"],"purpose":"Tuna"},{"ingredients":["¾ tsp lemon juice","3 tsp extra virgin olive oil","1/8 tsp caster sugar / superfine sugar"],"purpose":"Lemon Vinaigrette"},{"ingredients":["1/4 white onion layer (, (or brown/yellow onion), finely sliced 2mm / 0.08\" (Note 3))","1 1/2 tbsp white wine vinegar (, or apple cider vinegar )"],"purpose":"Pickled Onion"},{"ingredients":["12 - 16 small slices pane di casa bread (, or other bread , 3 - 4mm / 1/8\" thick (Note 4))","2 tbsp extra virgin olive oil","Few pinches cooking salt / kosher salt"],"purpose":"Crostinis"}]', '[{"description":"Mix onion with vinegar, set aside. Combine vinaigrette ingredients, set aside. Flatten the first piece of tuna to 2mm. Flip onto plate. Flatten the second piece, cut into smaller pieces to fill any gaps on the plate. Brush vinaigrette, sprinkle salt, Espelette pepper and chives, then top with pickled onion and edible flowers. Serve immediately with crostini.","images":[],"step":1},{"title":"Pickle onion","description":"Combine sliced onion and vinegar in a small bowl. Set aside for 15 minutes to soften. (You will have more than needed, use generously if you like.)","duration":15,"images":[],"step":2},{"title":"Make vinaigrette","description":"Mix lemon juice, olive oil and sugar in a small bowl. Set aside.","images":[],"step":3},{"title":"Flatten tuna (first piece)","description":"Place one piece of tuna on its flat side between two sheets of go-between (or baking paper / parchment paper) on a chopping board. Using a rolling pin, GENTLY tap and roll until about 2mm / 0.08\" thin (don’t smash!). (Note 5 & 6)","images":[],"step":4},{"title":"Transfer to plate","description":"Place tuna flat side down onto the middle of a plate (I use a 26cm / 10\"), then slowly peel off the sheet of plastic (or paper if using).","images":[],"step":5},{"title":"Repeat & fill","description":"Flatten the second piece the same way, return it onto the chopping board. Cut into pieces that you think will fill the empty gaps, then arrange over the plate so you end up with a thin, even layer of tuna.","images":[],"step":6},{"title":"Dress","description":"Gently brush the lemon vinaigrette over the tuna.","images":[],"step":7},{"title":"Finish","description":"Sprinkle with salt flakes, Espelette pepper and chives. Top with a few slices of pickled onion and edible flowers if using.","images":[],"step":8},{"title":"Serve","description":"Serve immediately with crostini on the side. Enjoy!","images":[],"step":9},{"description":"Crostini for Carpaccio","images":[],"step":10},{"description":"Preheat oven to 180°C/350°F (160°C fan-forced). Brush each side of bread with oil and sprinkle a tiny bit of salt, spread in single layer on a tray. Bake 15 minutes, turning halfway, until crisp. Cool on tray before using.","images":[],"step":11}]', '["fish","gluten"]', '["keto_friendly","low_calorie"]', '{"mealType":["snack"],"cuisine":["Italian","Mediterranean"],"categories":["italian-recipes","jbs-recipes","mediterranean-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_fc11d8b13e0d', 'en', 'US', 'Penne alla Vodka', 'Recipe video above. I think this was THE viral pasta about 5 years ago - but I totally missed the trend (not cool enough 😅). While the young probably love that it''s got vodka in it, I love it because you get to use a whole packet of pasta and a whole tub of tomato paste - no measuring, no waste!Jokes aside, vodka adds depth and almost floral-like notes into the sauce without tasting boozy, and though not a standard step, cooking off the paste really lifts the flavour and cuts the sourness. Makes regular taste just as good as the pricier double-concentrate paste!', 'https://www.recipetineats.com/tachyon/2025/08/Penne-alla-vodka_2.jpg', 5, 15, 20, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 1.25, "unit": "carton of 250ml"}}, {"id": "ing_vodka", "quantity": {"value": 0.333, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["500g / 1 lb penne or ziti (rigatoni is also a fave, else any other pasta)","2 tsp cooking salt / kosher salt (, for pasta cooking water)","1 1/2 tbsp olive oil","1/2 small onion (, finely diced (smaller dice than usual is better))","2 garlic cloves (, finely minced)","1/2 cup (140g / 4.5 oz) tomato paste (UK: tomato puree)","1 1/4 cups heavy / thickened cream (UK: double cream - Note 2)","1/3 cup vodka (, or chicken stock/broth for alcohol free (Note 3))","1/2 tsp red pepper flakes ((chilli flakes), 100% optional)","3/4 tsp cooking salt / kosher salt (halve for table salt)","Pinch black pepper","50g / 1 loosely packed cup freshly grated parmesan (, plus more for serving (Note 4))","1/2 cup+ pasta cooking water (Note 5)","2 tsp parsley (, finely chopped, for serving (optional))"]}]', '[{"description":"Sauté garlic and onion, cook off tomato paste, simmer with cream, vodka, chilli flakes, S&P 3 min, stir in parmesan at end. Toss with pasta and 1/2 cup pasta water, eat!","images":[],"step":1},{"title":"Cook pasta","description":"Bring a large pot of water to the boil with the pasta salt. Cook pasta per the packet directions until al dente. (Meanwhile cook the sauce)","images":[],"step":2},{"title":"⭐️ Reserve pasta water","description":"Just before draining, give the pasta a big stir to agitate the starch then scoop out a cup of the water. Then drain the pasta.","images":[],"step":3},{"title":"Sauté","description":"Heat the oil in a large pot or non-stick pan over medium high heat. Cook the onion and garlic for 1 1/2 minutes until translucent. Add the tomato paste and cook, stirring constantly, for 2 minutes until it darkens in colour (lower heat if catching on base).","duration":2,"images":[],"step":4},{"title":"Make sauce","description":"Add the cream, stir well to dissolve the tomato paste. Then add the chilli flakes, salt, pepper and vodka. Simmer on low for 3 minutes, stirring regularly. Stir in the parmesan until melted, then turn off the heat until the pasta is ready.","duration":3,"images":[],"step":5},{"description":"Toss! Add the pasta and 1/2 cup of the pasta cooking water. Over medium heat on the stove, stir for 1 - 1 1/2 minutes until all the pasta is nicely coated with the rust coloured sauce, using extra pasta cooking water to loosen if needed.","images":[],"step":6},{"description":"Serve immediately in warmed pasta bowls* with a dusting of extra parmesan and pinch of parsley. Add a side of garlic bread and big Italian Salad, then finish with Tiramisu for a classic trattoria meal at home!","images":[],"step":7}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["American-Italian","Italian"],"categories":["italian-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_deba1e59e15a', 'en', 'US', 'Easy Ricotta Gnocchi with creamy mushroom sauce', 'Recipe video above. An easy recipe for pillowy soft gnocchi made using ricotta instead of potato. It''s real Italian food - fast! Takes a third of the time to make compared to potato gnocchi, and it''s lighter and softer so you won''t feel as weighed down. Served with a creamy mushroom sauce which is to-die-for sauce for pillowy soft gnocchi. See below recipe card for more gnocchi sauces. Serves 3 as a main, 4 to 5 as a starter.', 'https://www.recipetineats.com/tachyon/2024/06/Ricotta-Gnocchi-51183.jpg', 20, 15, 30, 3, '[{"id": "ing_ricotta", "quantity": {"value": 1.0, "unit": "tub of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.375, "unit": "pack of 200g"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 0.5, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_mushroom", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chardonnay", "quantity": {"value": 0.333, "unit": "unit"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.667, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 0.375, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["250g / 8oz ricotta (, must be full fat (Note 1))","3/4 cup (75g) freshly grated parmesan cheese (Note 2)","1 large egg (55 - 60g/2oz)","1 egg yolk (egg white use ideas here)","1/4 tsp cooking salt / kosher salt","Pinch black pepper","3/4 - 1 cup flour (plain/all-purpose), plus more for dusting (Note 3)"],"purpose":"Gnocchi"},{"ingredients":["30g / 2 tbsp unsalted butter","2 garlic cloves (, finely minced )","1/2 onion or 1 eschallot ((US: shallot), finely chopped)","2 thyme sprigs (sub 1/2 tsp dried thyme)","250g / 8oz white mushrooms (, sliced in 5mm / 0.2\" slices)","1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper","1/3 cup chardonnay (or other dry white wine (skip for non alcoholic))","1/2 cup chicken stock/broth (, low sodium)","2/3 cup thickened / heavy cream (or pure cream)"],"purpose":"Creamy mushroom sauce"},{"ingredients":["Freshly grated parmesan","Fresh parsley (, finely chopped (optional))"],"purpose":"Garnish"}]', '[{"description":"Homemade ricotta gnocchi","images":[],"step":1},{"title":"Mix","description":"Put all the gnocchi ingredients in a bowl except the flour. Use a rubber spatula or wooden spoon to mix until combined (smear up the wall if needed, to help cream the ricotta).","images":[],"step":2},{"title":"Add flour","description":"Add 3/4 cup of flour and mix until just combined so it is a very sticky dough that will hold its shape in a mound, but is not runny like a muffin batter (see video for consistency). Stickier dough = softer gnocchi! Use the remaining flour, 1 tbsp at a time, if needed, but try to stick with 3/4 cup. You can always add more flour in the next step. (Note 3)","images":[],"step":3},{"title":"Form disc","description":"Sprinkle a work surface with flour then scrape the dough out onto it. Sprinkle the top lightly with flour then use your hands to give the dough a light knead to bring it into a ball then pat it into a disc about 2.5cm/1\" thick. Cut it into 8 wedges, using a knife or dough scraper dusted with flour as needed between each cut","images":[],"step":4},{"title":"Roll and cut","description":"Roll each piece into a log 25cm/10\" long, about 1.25cm / 1/2\" wide. Cut into 1.5 cm / 3/5\" pieces (Can freeze at this point - Note 4)","images":[],"step":5},{"description":"Creamy mushroom sauce","images":[],"step":6},{"title":"Cook mushrooms","description":"Melt the butter in a large pan over high heat. Add the onion, garlic and thyme sprigs. Cook for 1 minute. Add mushrooms, salt and pepper. Cook for 5 minutes until the mushrooms is softened.","duration":1,"images":[],"step":7},{"title":"Sauce","description":"Add the wine and simmer rapidly for 1 to 2 minutes, stirring to scrape the base of the pan, until mostly evaporated. Add the stock/broth and cream, then stir.","duration":1.5,"images":[],"step":8},{"title":"Simmer","description":"Bring to a simmer then reduce the heat to medium low and simmer gently for 5 minutes until thickened. (It''s ok if it seems a bit thin, the starch from gnocchi will thicken it quickly, have faith!).","duration":5,"images":[],"step":9},{"description":"Cook gnocchi & sauce it","images":[],"step":10},{"title":"Cook gnocchi","description":"Bring a large pot of water to the boil with 2 teaspoons of salt. Tumble the gnocchi in and cook for around 2 1/2 minutes, or until the gnocchi is floating on the surface for around 30 seconds, no longer (else they overcook!)","images":[],"step":11},{"title":"Sauce it","description":"Use a spider or large slotted spoon to scoop the gnocchi out of the water and straight into the sauce (excess water drips in the sauce are good!). Turn the heat up to medium and toss gently for 1 minute or until the sauce thickens and coats the gnocchi. If the sauce gets too thick, add a splash of the gnocchi cooking water.","duration":1,"images":[],"step":12},{"description":"Serve immediately, garnished with freshly grated parmesan and parsley, if desired.","images":[],"step":13}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["italian-recipes","pasta-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_990e1b1052c7', 'en', 'US', 'Sausage ragu with pappardelle pasta', 'Recipe video above. Take your meat sauce to the next level by using sausages instead of plain beef to make an incredible Sausage Ragu! Like Shredded Beef Ragu, cooking this sausage pasta sauce long and slow gives it time to develop deep, complex flavours. Complete your Italian feast with Garlic Bread, a garden salad with Italian Dressing and a beautiful Tiramisu.', 'https://www.recipetineats.com/tachyon/2016/02/Sausage-ragu_7.jpg', 20, 135, 155, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_fennel_seeds", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_sausages", "quantity": {"value": 0.7, "unit": "pack of 500g"}}, {"id": "ing_sausages", "quantity": {"value": 0.7, "unit": "pack of 500g"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.333, "unit": "bottle of 750ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_chilli", "quantity": {"value": 0.013, "unit": "pack of 100g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["2 tbsp olive oil","1 small onion (, finely chopped)","3 garlic cloves (, finely minced)","1 carrot (, peeled and grated using a box grater (Note 1))","2 celery stalks (, grated using a box grater (Note 1))","1 tsp fennel seeds","350g / 12 oz pork sausages (, meat removed from casings (Note 2))","350g / 12 oz beef sausages (, meat removed from casings (Note 2))","2 tbsp tomato paste","1 cup pinot noir red wine (sub 0% alcohol red wine or more chicken stock)","1 cup chicken stock/broth (, low sodium)","400g/14 oz can crushed tomato","3 thyme sprigs (or 1/2 tsp dried)","2 bay leaves (fresh better, else dried)","1/2 tsp cooking salt / kosher salt","1/2 tsp black pepper","1/4 tsp chilli flakes ( (red pepper flakes), optional (for hint of heat))"],"purpose":"Sausage ragu:"},{"ingredients":["500g/ 1 lb pappardelle pasta (, or other pasta (80g/2.8oz per serving) (Note 3))","Parmesan or parmigiano reggiano (, finely grated, for serving)","Parsley (, finely chopped, optional garnish (just a pinch))"],"purpose":"To serve:"}]', '[{"description":"Preheat oven to 180°C (160°C fan-forced).","images":[],"step":1},{"title":"Soffrito","description":"Heat the oil in a large heavy based pot (with a lid) over medium heat. Add the onion, garlic, carrot, celery and fennel seeds. Cook for 8 minutes until the carrot is soft and sweet, but not golden.","duration":8,"images":[],"step":2},{"title":"Cook sausage","description":"Turn the heat up to high and add the sausage. Cook, breaking it up as you go, as best you can. It doesn''t crumble as well as mince/ground meat but that''s ok, we will break it up more later.","images":[],"step":3},{"title":"Deglaze","description":"Once the meat is no longer pink (it doesn''t really brown), add the tomato paste. Cook for 1 minute. Add the wine and let it simmer rapidly for 2 minutes until reduced by half, stirring regularly to scrape the base of the pot clean.","duration":1,"images":[],"step":4},{"title":"Slow cook #1 (1 hr)","description":"Add the remaining ragu ingredients. Stir, bring to a simmer, put the lid on and place it in the oven for 1 hour.","images":[],"step":5},{"title":"Slow cook #2 (45 min)","description":"Remove from the oven and use a potato masher to mash the meat finer. Put the lid back on, and return to the oven for 45 minutes. The sauce will be quite thick, it gets loosened when tossed with the pasta.","duration":45,"images":[],"step":6},{"title":"Salt","description":"Taste and add more salt if desired. (Sausages vary in saltiness so I always start with less)","images":[],"step":7},{"title":"Cook pasta","description":"Cook the pappardelle according to the packet instructions. Just before draining, scoop out 1 1/2 cups of the cooking water and set it aside.","images":[],"step":8},{"title":"Toss with sauce","description":"Have the ragu pot on the stove over medium heat. Add the pasta into the pot along with 1/2 cup of the pasta cook water. Use two spatulas to toss the pasta until the ragu is tangled in the pasta strands and it is stained red from the sauce. Use extra pasta cooking water if needed to loosen it up.","images":[],"step":9},{"description":"Serve in pre-warmed bowls, garnish with parmesan and a pinch of parsley if desired. Eat immediately!","images":[],"step":10}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["italian-recipes","main-dishes","most-popular","pasta-recipes","slow-cooked-fall-apart","slow-cooker-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_73d4109d75d1', 'en', 'US', 'Creamy Tuscan Chicken Soup', 'Recipe video above. My (current) favourite chicken soup - utterly divine! Creamy broth, juicy little bits of chicken, pasta (I used small shells), swirls of spinach and a sprinkling of sun dried tomato which I use instead of the usual croutons. Easy, one pot, quick to make, and great for making ahead.I call it "Tuscan" because to me it has Tuscan vibes, so christened it as such with a cute name. But no, it''s not authentic - and that''s ok! It''s still delicious. :)', 'https://www.recipetineats.com/tachyon/2023/07/Creamy-Tuscan-Chicken-Soup_3.jpg', 15, 20, 35, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_celery", "quantity": {"value": 40.0, "unit": "head"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.5, "unit": "pack of 200g"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_baby_spinach", "quantity": {"value": 2.0, "unit": "bag of 250g"}}, {"id": "ing_tomato", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.025, "unit": "pack of 400g"}}]', '[{"ingredients":["500 g/1 lb chicken thighs (, skinless boneless (Note 1 for breast))","1/2 tsp each salt and pepper"]},{"ingredients":["30g / 2 tbsp unsalted butter","1 onion (, finely chopped)","2 garlic cloves (, minced)","2 large celery stems (, finely sliced (sub 2 carrots))","1/2 cup chardonnay ( or other dry white wine, optional (Note 2))","4 cups chicken stock/broth (, low sodium)","3 cups water","1 tsp cooking/kosher salt","1/2 tsp black pepper","250g/8 oz small pasta shells (or other small pasta, rice, potato etc - see Note 3)","1 cup (tightly packed) parmesan, (finely grated or store bought pre-grated (sandy type) (Note 4))","1 cup thickened/heavy cream (Note 5 for milk sub)","2 packed cups baby spinach (, chopped kale or similar)","1/2 cup sun dried tomato strips (, chopped into 1cm pieces, plus bit of oil drizzling (Note 6))"],"purpose":"Soup:"},{"ingredients":["2 tsp cornflour/cornstarch mixed with 2 tsp water"],"purpose":"Soup thickener (cornflour slurry):"}]', '[{"title":"Cook outside of chicken","description":"Sprinkle each side with the salt and pepper. Melt butter in a large pot over medium high heat. Once foamy, place the chicken in and cook the first side for 3 minutes or until light golden, then the other side for 2 minutes - it''s fine if the inside is still raw, it cooks more later. Remove onto a plate.","duration":3,"images":[],"step":1},{"title":"Soup flavour base","description":"Turn the stove down to medium low. Add garlic, onion and celery into the same pot then cook for 3 minutes or until the onion is softened.","duration":3,"images":[],"step":2},{"title":"Deglaze","description":"Turn up to high, add wine, stir, then let it simmer until the wine reduces by half.","images":[],"step":3},{"title":"Broth & pasta","description":"Add stock/broth, water, salt and pepper. Bring to a boil then add the pasta. Cook for the time per the pasta packet directions (~10 minutes), stirring every now and then so the pasta doesn''t stick to the base of the pot.","images":[],"step":4},{"title":"Add chicken partway","description":"While the pasta is cooking, chop the chicken into 1.5cm / 1/2\" pieces then add into the pot to finish cooking.","images":[],"step":5},{"title":"Finish soup","description":"Once the pasta is cooked, turn heat down to low. Stir in parmesan until melted. Stir in the cornflour-water mixture, cream and spinach. Stir for a minute until spinach is wilted and soup thickens slightly.","images":[],"step":6},{"title":"Serve","description":"Ladle into bowls. Sprinkle with sun dried tomato strips (and a bit of oil looks nice for finishing). Eat!","images":[],"step":7},{"title":"Storing","description":"Separate pasta from soup so it doesn''t bloat, refrigerate both. Just scoop out with slotted spoon. (Note 6)","images":[],"step":8}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["main_course"],"cuisine":["Italian-esque","Western"],"categories":["italian-recipes","quick-and-easy","soup-recipes","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_10d82007651a', 'en', 'US', 'Spaghetti alla Puttanesca', 'Recipe video above. Spaghetti alla Puttanesca is a traditional Italian pasta from Naples with a sauce based on pantry essentials. This plants it firmly in the (excellent) emergency-meals collection!You don''t need much salt in Puttanesca sauce because the olives, capers and anchovies provide the seasoning. Don''t skip the anchovies - sauteeing it cooks out the fishy flavour and it just dissolves in the sauce, leaving behind savoury flavour you can''t get from just plain salt. You''d have to have a finely attuned palette to even know it''s in the sauce!', 'https://www.recipetineats.com/tachyon/2021/08/Spaghetti-Puttanesca_64-SQ.jpg', 5, 15, 20, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.4, "unit": "pack of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_fish_fillets", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_pitted_black_olives", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_capers", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_chilli", "quantity": {"value": 0.013, "unit": "pack of 100g"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_sugar", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_basil", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["200g / 7oz spaghetti (, or other long pasta)","2 tbsp extra virgin olive oil (, plus more for drizzling)","2 garlic cloves (, finely minced (knife, not garlic press))","3 anchovy fillets (, finely minced (Note 1))","1/4 cup pitted black olives (, preferably in oil, quartered (Note 2))","1 tbsp capers (, drained (Note 3))","1/4 tsp chilli flakes (red pepper flakes)","400g / 14oz can crushed tomato (or hand crush whole canned tomatoes)","1/2 cup water","1 tsp fresh oregano (, roughly chopped (sub 1/4 tsp dried))","1/8 tsp kosher / cooking salt (or 2 pinches table salt)","1/8 tsp black pepper","1/4 tsp sugar (, if needed (depends on tomato quality, Note 4))","2 tbsp fresh basil (, roughly chopped (Note 6))"]}]', '[{"title":"Prepare","description":"Bring a large pot of water to the boil, ready for the pasta. Warm serving bowls (I microwave 1 minute).","images":[],"step":1},{"title":"Cook garlic","description":"Heat olive oil in a medium skillet over medium high heat. Add garlic and cook for 15 seconds until it starts turning golden.","duration":0.25,"images":[],"step":2},{"title":"Cook anchovies","description":"Add anchovies, capers, olives and chilli flakes. Cook for 1 minute.","duration":1,"images":[],"step":3},{"title":"Tomato","description":"Add tomato, then add the 1/2 cup of water into the can. Swirl around to rinse then pour into the skillet.","images":[],"step":4},{"title":"Simmer","description":"Add oregano, salt and pepper. Stir, bring to simmer, then turn down to low and cook over medium heat for 10 minutes or until the tomato has broken down and created a sauce. Turn off stove when ready if not timed with cooked pasta.","duration":10,"images":[],"step":5},{"title":"Cook pasta","description":"Meanwhile, add 2 teaspoons salt into the pot of water. Then add pasta and cook per packet directions.","images":[],"step":6},{"title":"Reserve pasta water (Note 5)","description":"Just before draining, scoop out a mugful of pasta cooking water and set aside. Then drain pasta in a colander.","images":[],"step":7},{"title":"Toss pasta","description":"Immediately add pasta into sauce. Add 1/4 cup of pasta cooking water reserved from previous step (Note 5) then use 2 wooden spoons to toss the pasta, still on a low stove, for 1 minute or until the sauce is no longer in the skillet but rather clinging to the pasta strands (but still slick and slippery). If the pasta gets too dry, add more pasta cooking water and toss.","duration":1,"images":[],"step":8},{"title":"Serve","description":"Immediately transfer into warmed bowls. Drizzle with olive oil, sprinkle with basil. Serve immediately!","images":[],"step":9}]', '["fish","gluten"]', '[]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["dinner-tonight","italian-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_37bb95f22138', 'en', 'US', 'Pasta alla Norma (Eggplant pasta)', 'Recipe video above. This is a traditional Italian pasta dish from Sicily, usually begun by cooking eggplant on the stove in a hefty amount of oil. I prefer roasting the eggplant - less oil plus the eggplant holds its shape better, especially when you roast at a high temp to caramelise the surface!Finishing with a good amount of fresh basil is traditional but even if you don''t have any, there''s other alternatives to add a touch of other flavour - such as fresh thyme, or extra dried herbs in the sauce.This is an excellent and satisfyingly "meaty" vegetarian main dish that will have even card-carrying carnivores asking for seconds!', 'https://www.recipetineats.com/tachyon/2020/11/Pasta-alla-norma-eggplant-pasta_6.jpg', 10, 45, 55, 4, '[{"id": "ing_egg", "quantity": {"value": 66.667, "unit": "carton of 12"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_wine", "quantity": {"value": 0.083, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_italian_herbs", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.6, "unit": "pack of 500g"}}, {"id": "ing_basil", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["800g / 1.6 lb eggplant (, cut into 2.5cm/1\" cubes (2 medium/large ones))","2 tbsp extra virgin olive oil","1/2 tsp each salt and pepper"]},{"ingredients":["2 tbsp extra virgin olive oil","2 garlic cloves (, finely minced)","1/2 small onion (, very finely chopped (or 2 eschallots))","1/4 cup dry white wine (, anything not too sweet or woody (Note 1))","700g / 24 oz tomato passata (aka tomato puree, Note 2)","1/4 cup water","1 tsp dried Italian herbs (or oregano)","1/2 tsp red pepper flakes (, optional (for a hint of heat))","1/2 tsp each salt and pepper","300g / 10 oz spaghetti or other pasta, long or short (macaroni, rigatoni, penne, ziti, fettucini, bucatini)"],"purpose":"Pasta Sauce:"},{"ingredients":["1/2 cup basil leaves (, roughly chopped (Note 3))","Parmesan cheese (, grated (or ricotta salata if you have it - more traditional))"],"purpose":"Serving:"}]', '[{"description":"Roasted eggplant:","images":[],"step":1},{"description":"Preheat oven to 240°C / 450°F (220°C fan). Line a tray with baking / parchment paper.","images":[],"step":2},{"description":"Toss eggplant with oil, salt and pepper. Spread on the tray and roast for 20 minutes.","duration":20,"images":[],"step":3},{"description":"Flip, then roast for a further 5 minutes. Cool on tray (this helps the eggplant hold its shape when tossing).","images":[],"step":4},{"description":"Cooking pasta:","images":[],"step":5},{"description":"Bring a large pot of salted water to the boil. Start cooking the pasta a couple of minutes after you start making the sauce (next section), until al dente or to your liking.","images":[],"step":6},{"description":"Heat oil in a very large skillet over medium heat. Add garlic, cook for 20 seconds until golden, then add onion and cook for 2 to 3 minutes until translucent and cooked through.","duration":0.3333333333333333,"images":[],"step":7},{"description":"Increase heat to medium-high and add wine, if using. Let it simmer, scraping the base of the pan to deglaze, until the wine mostly evaporates.","images":[],"step":8},{"description":"Add tomato passata. Now pour the water into the passata bottle, screw on the lid, shake, and pour that in too (waste nothing!)","images":[],"step":9},{"description":"Add dried herbs, red pepper flakes, salt and pepper. Stir and simmer 5 minutes.","images":[],"step":10},{"description":"Stir in eggplant, then add cooked and drained pasta. GENTLY toss until pasta is coated in the sauce (so the eggplant doesn''t turn into complete mush!).","images":[],"step":11},{"description":"Serve immediately, garnished with a good pinch of fresh basil and parmesan.","images":[],"step":12}]', '["gluten","milk"]', '["vegetarian"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["italian-recipes","pasta-recipes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_02b09d3844e4', 'en', 'US', 'Mushroom Pasta', 'Recipe video above. An incredible way to use mushrooms in a meal - in a mushroom pasta! The tastiness of this pasta lies in the mushrooms you use because it''s all about the mushrooms. This pasta is made the proper Italian way so even though it''s only made with 6 ingredients, it''s saucy and juicy and so incredibly tasty!', 'https://www.recipetineats.com/tachyon/2016/10/Mushroom-Pasta_6.jpg', 10, 15, 20, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.32, "unit": "pack of 500g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.32, "unit": "pack of 500g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}]', '[{"ingredients":["200g / 7 oz short pasta like orecchiette, penne, macaroni (Note 1)","160g/6 oz long pasta - spaghetti, fettucine (Note 1)"],"purpose":"CHOOSE pasta"},{"ingredients":["400g / 14 oz mushrooms (, sliced 1/2 cm / 1/5\" thick (Note 2))","50g / 3 tbsp unsalted butter (, separated)","1 tbsp olive oil","2 garlic cloves (, finely minced)","1/2 tsp each salt and pepper","1/2 cup freshly grated parmesan cheese (or 1/4 cup store bought grated)"],"purpose":"Garlic Butter Mushrooms for pasta"},{"ingredients":["Parsley (, finely chopped)","Parmesan cheese (, grated)"],"purpose":"To serve"}]', '[{"description":"Bring a large pot of salted water to the boil. Add the pasta into the pot when you start cooking the mushrooms.","images":[],"step":1},{"description":"Cook pasta per packet instructions minus 1 minute. RESERVE 1 mugful of pasta cooking liquid, then drain pasta.","images":[],"step":2},{"description":"Melt half butter and all oil in a large skillet over heat.","images":[],"step":3},{"description":"Add mushrooms and cook until water has leeched then evaporated, and the mushrooms start to turn golden around edges - around 5 minutes.","images":[],"step":4},{"description":"Halfway through cooking, add salt & pepper.","images":[],"step":5},{"description":"Add garlic and remaining butter, cook for 2 minutes until mushrooms and garlic are golden.","duration":2,"images":[],"step":6},{"description":"Add pasta, about 3/4 cup of reserved pasta water and parmesan. Toss gently or until water reduces and thickens into a saucy glaze that coats the pasta. If the pasta dries out, add more pasta water.","images":[],"step":7},{"description":"Taste and add more salt and pepper if needed.","images":[],"step":8},{"description":"Remove from stove and serve immediately, garnished with fresh parsley and parmesan cheese.","images":[],"step":9}]', '["gluten","milk"]', '["high_protein","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["dinner-tonight","italian-recipes","main-dishes","most-popular","mushroom-recipes","pasta-recipes","quick-and-easy","uncategorized","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7286fb921209', 'en', 'US', 'Baked Creamy Pumpkin Risotto', 'Recipe video above. You''ll be amazed how creamy this risotto is - even though it''s BAKED without constant stirring! And it tastes as magnificent as it looks! Note: you won''t use all the brown butter, see notes for ways to use the leftovers.', 'https://www.recipetineats.com/tachyon/2014/07/Pumpkin-Risotto_8.jpg', 15, 30, 45, 5, '[{"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_arborio_rice", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_pumpkin", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_wine", "quantity": {"value": 0.083, "unit": "bottle of 750ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.875, "unit": "L"}}, {"id": "ing_sage", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_sage", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}]', '[{"ingredients":["3 tbsp / 50 g unsalted butter (, divided)","1 1/2 cups arborio rice (risotto rice) (Note 1)","1 onion (, diced)","600 g / 20 oz pumpkin (weight after peeling and deseeding) (, diced into 1.7cm/2/3\" cubes (about 4 heaped cups) (Note 2))","3 garlic cloves (, minced)","1/4 cup dry white wine (or water or broth)","3 1/2 cups vegetable or chicken stock/broth","2 tbsp sage leaves, roughly chopped (Note 3)","1/2 cup parmesan cheese (, finely grated)","Salt & pepper"]},{"ingredients":["50 g / 3 tbsp butter (, salted)","12 - 20 sage leaves"],"purpose":"Crispy Sage & Brown Butter (optional)"},{"ingredients":["Grated parmesan"],"purpose":"To Garnish"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Melt 1 tbsp / 20g butter in ovenproof pot (preferably with a lid) over medium high heat.","images":[],"step":2},{"description":"Add garlic and onion and cook until onion is translucent.","images":[],"step":3},{"description":"Add chopped sage and cook for 1 minute.","duration":1,"images":[],"step":4},{"description":"Add rice and stir so all the rice grains are coated with the butter and semi translucent.","images":[],"step":5},{"description":"Add white wine and cook until the the liquid evaporates - about 1 minute.","images":[],"step":6},{"description":"Add pumpkin and broth, stir. Let the liquid heat up but do not bring to simmer.","images":[],"step":7},{"description":"Put lid on (or cover tightly with foil) and place in oven for 25 minutes, until rice is just cooked (firm but not raw) - don''t worry if there''s excess liquid. If rice is still uncooked, return to oven for 5 minutes.","duration":25,"images":[],"step":8},{"description":"Add remaining butter and parmesan cheese.","images":[],"step":9},{"description":"Stir vigorously until the pumpkin turns into a puree and blends into the risotto. If it''s too thick then add a splash of hot tap water. Should have a porridge like consistency so it sags a bit when served (see video), rather than staying in a tall, firm pile.","images":[],"step":10},{"description":"Spoon into serving bowls. Garnish with crispy sage, 1 or 2 teaspoons of brown butter and parmesan cheese. Devour immediately!","images":[],"step":11},{"description":"Melt butter in a small pan over medium high heat. Once foaming, add sage leaves and stir gently.","images":[],"step":12},{"description":"Cook for 1 1/2 minutes or until crispy.","images":[],"step":13},{"description":"Immediately remove sage onto paper towel lined plate and pour butter into a heat proof jug (butter should be brown by now).","images":[],"step":14}]', '["milk"]', '["gluten_free"]', '{"mealType":["main_course"],"cuisine":[],"categories":["dinner-tonight","italian-recipes","main-dishes","pumpkin","quick-and-easy","rice-recipes","rice-side-dishes","risotto-recipes","sunday-supper","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3b53a0875c54', 'en', 'US', 'Creamy Garlic Prawn Pasta', 'Recipe VIDEO above. Pasta tossed with a garlic infused creamy sauce and plump, juicy prawns! (Shrimp) This pasta version of Creamy Garlic Prawns is a quick meal you''ll get on the table in 20 minutes, this is luscious but it''s not too rich. The key is to emulsify the sauce (i.e. thicken it) by tossing the pasta in the sauce just before serving - this is the proper Italian way to make pasta. Serves 4.', 'https://www.recipetineats.com/tachyon/2017/11/Creamy-Garlic-Prawn-Pasta-4.jpg', 5, 20, 25, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.68, "unit": "pack of 500g"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_shrimp", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_cream", "quantity": {"value": 1.25, "unit": "carton of 250ml"}}, {"id": "ing_chicken", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_parmesan", "quantity": {"value": 0.375, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.375, "unit": "pack of 200g"}}]', '[{"ingredients":["12 oz / 350g fettuccine (, or other long strand pasta of choice)","50 g / 3 tbsp unsalted butter (, separated)","500 g / 1 lb small or medium peeled prawns / shrimp (, raw or 1kg / 2 lb whole unpeeled (Note 1))","4 garlic cloves (, finely minced with a knife)","1/2 cup Chardonnay or other dry white wine (Note 2 for sub)","1 1/4 cups heavy / thickened cream (or regular cream, pouring cream etc, full fat (Note 3))","1/2 cup chicken broth ((or fish or vegetable broth), preferably low sodium)","3/4 cup (75 g) finely grated parmesan cheese (freshly grated) (Note 4)","2 tbsp finely chopped parsley (, optional)","Black pepper","Parmesan (, for serving)"]}]', '[{"title":"Cook pasta","description":"Bring to boil a large pot of water. Add a big pinch of salt and the pasta, then cook per packet MINUS 1 minute - it will finish cooking in the sauce later so we want it slightly under. (Note 5).","images":[],"step":1},{"title":"Reserve water","description":"Just before draining, scoop out 1 cup of pasta cooking water and set aside, we need this to thicken the sauce later. Drain pasta.","images":[],"step":2},{"title":"Lightly cook prawns in 2 batches","description":"Meanwhile, melt about 1/3 of the butter in a large non stick skillet over medium high heat. Add half the prawns, spread out, and cook for 1 1/2 minutes, then turn and toss using 2 spatulas for another 1 - 1 1/2 minutes until just barely cooked (the prawns will cook more in the sauce). Remove prawns into a bowl. Repeat - add half the remaining butter, cook the remaining prawns then remove.","images":[],"step":3},{"title":"Sauté garlic","description":"In the same skillet, add the remaining butter. Once melted, add the garlic and stir for 20 seconds until fragrant (don''t let it burn, lower heat it needed).","duration":0.3333333333333333,"images":[],"step":4},{"title":"Deglaze","description":"Add wine and stir. Simmer rapidly for 2 minutes, scraping the pan to dissolve any bits stuck to it into the liquid, until wine mostly evaporates (see video).","duration":2,"images":[],"step":5},{"title":"Sauce","description":"Add cream, broth and parmesan. Stir until the parmesan is melted, then leave to simmer for 1 1/2 minutes until it thickens slightly - it will still be quite watery though which is fine, it will thicken more in next step.","images":[],"step":6},{"title":"Toss & thicken sauce","description":"Add prawns, pasta plus about 1/4 cup of reserved pasta water. Toss pasta energetically (still on stove on medium high) and in 1 to 2 minutes, the sauce will thicken and start clinging to the pasta. It will seem like nothing is happening at first but trust the process, it will happen! If you take it too far and the sauce gets too thick, add a small splash of remaining reserved pasta cooking water to loosen and toss again (you can do this repeatedly as needed).","images":[],"step":7},{"title":"Finish","description":"Add most of the parsley and a grind of black pepper, taste and check if you need salt (I don''t need more), then give it a quick toss.","images":[],"step":8},{"description":"Serve immediately, garnished with remaining parsley and parmesan if desired.","images":[],"step":9}]', '["fish","gluten","milk","shellfish"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","italian-recipes","main-dishes","pasta-recipes","prawns-shrimp","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8833556f0dfa', 'en', 'US', '$2 Homemade Frozen Pizzas', 'VIDEO above. Stock your freezer with these quick homemade frozen pizzas! Made with store bought flatbreads, these thin and crispy pizzas are baked from frozen. Terrific economical standby meal, feel free to use your toppings of choice. Makes 10 pizzas, 25cm / 10" diameter.', 'https://www.recipetineats.com/tachyon/2017/10/Homemade-Frozen-Pizza_2.jpg', 20, 40, 60, 10, '[{"id": "ing_bread", "quantity": {"value": 0.013, "unit": "loaf"}}, {"id": "ing_salami", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_black_olives", "quantity": {"value": 112.5, "unit": "bottle"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_mushroom", "quantity": {"value": 15.0, "unit": "kg"}}, {"id": "ing_mozzarella", "quantity": {"value": 3.2, "unit": "pack of 125g"}}, {"id": "ing_cheese", "quantity": {"value": 400.0, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["10 Greek pita bread (thick round flatbreads, 25cm / 10\" diameter) (Note 1)","250 g / 8 oz salami sliced (, chopped)","3/4 cup / 100 g sliced black olives (, drained)","1 large green capsicum / bell pepper (, sliced)","1 large red onion (, chopped)","15 medium mushrooms (, sliced (~golf ball size))","400 g / 14 oz / 4 cups shredded mozzarella cheese","300 - 350 g / 10 - 12 oz / 3.5 cups shredded Monterey Jack"]},{"ingredients":["1/4 cup / 65 ml extra virgin olive oil","3 garlic cloves (, minced)","800 g / 28 oz crushed canned tomato","2 tbsp tomato paste","1/2 cup / 125 ml water","1 tsp dried oregano","1 tsp dried thyme","1 tsp red chilli flakes (adjust to taste)","3/4 tsp salt","1/2 tsp black pepper"],"purpose":"Easy Homemade Pizza Sauce (Note 3):"}]', '[{"description":"Heat olive oil in a large saucepan over medium heat. Add garlic and cook for 1 minute until fragrant. Add remaining ingredients, stir, and adjust heat so it is simmering gently (about medium heat). Cook down for 40 minutes, then puree with a stick (or cool a bit then transfer to blender).","duration":1,"images":[],"step":1},{"description":"COOL before using (hot sauce = soggy base). (Note 4)","images":[],"step":2},{"description":"Top a flatbread with 2.5 tbsp of Sauce. Sprinkle a tiny amount of cheese over the base, avoiding the very edges (glue for toppings - see video).","images":[],"step":3},{"description":"Sprinkle over onion, capsicum, salami, olives, mushrooms then cheese. Repeat with remaining flatbreads.","images":[],"step":4},{"description":"Stack them using paper in between each pizza. Wrap in groups of 3 or so (whatever you are comfortable handling). Transfer to a large airtight container or ziplock bag and freeze.","images":[],"step":5},{"description":"Remove oven shelf from oven and clean.","images":[],"step":6},{"description":"Preheat oven to 240C/460F (standard) / 220C / 430F (fan/convection).","images":[],"step":7},{"description":"Place frozen (or unfrozen freshly made) pizza directly on shelf. Bake for 10 minutes or until golden on the edges and the base is crispy.","duration":10,"images":[],"step":8},{"description":"Cut and serve immediately!","images":[],"step":9}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","italian-recipes","main-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_212bae0c1c61', 'en', 'US', 'Sausage Pasta', 'A super quick meal made using chopped Italian Sausages that end up looking like mini meatballs! The sausages are the flavour base for this sauce, so get the best quality ones you can afford. Look for sausages where you can see little white chunks of fat and seasoning. Avoid the cheap sausages that are a uniform pink colour.', 'https://www.recipetineats.com/tachyon/2017/08/Sausage-Pasta-3.jpg', 5, 15, 20, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_sausages", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_baby_spinach", "quantity": {"value": 1.0, "unit": "bag of 250g"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["250 g / 0.5 lb spiral pasta (Note 1)","500 g / 1 lb good Italian sausages (, or other quality sausages of choice)","1 tbsp olive oil","1 small onion (, finely chopped)","2 garlic cloves (, minced)","800 g / 28 oz crushed tomato (or tomato passata)","1 tsp chilli flakes / red pepper flakes (adjust to taste)","Salt and pepper","1 - 2 big handfuls baby spinach (optional)"]},{"ingredients":["Basil leaves (, finely sliced)","Parmesan"],"purpose":"Garnish:"}]', '[{"description":"Bring a large pot of water to the boil. Cook pasta per packet directions MINUS 1 -2 minutes.","images":[],"step":1},{"description":"Just before you drain, RESERVE 1 cup of pasta cooking water. Then drain pasta.","images":[],"step":2},{"description":"Use a sharp knife to cut sausages into chunks about 1.5cm/3/5\". It will get a bit smeary and the chunks will be weird shapes - don''t worry, it self fixes while cooking!","images":[],"step":3},{"description":"Heat oil in a large skillet over high heat. Add sausages and cook until quite browned on the outside, doesn''t have to be cooked through inside.","images":[],"step":4},{"description":"Add onion and garlic, cook for 2 minutes until onion is translucent and sausages are very browned.","duration":2,"images":[],"step":5},{"description":"Add tomato, chilli flakes, pinch of salt and pepper. Mix and turn heat down to medium. Lets it bubble away energetically for 8 minutes or until it is quite thickened, stirring every now and then.","duration":8,"images":[],"step":6},{"description":"Add baby spinach (if using), pasta, and about 1/2 cup pasta cooking water. Toss quickly, no longer than 1 minute (otherwise the pasta may start to break).","images":[],"step":7},{"description":"Remove from stove, and serve immediately, garnished with plenty of basil and parmesan. Enjoy!","images":[],"step":8}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["American-Italian","Western"],"categories":["dinner-tonight","italian-recipes","main-dishes","pasta-recipes","quick-and-easy","readers-choice"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8ebe6852c899', 'en', 'US', 'Easy Pumpkin Gnocchi with Sage Butter Sauce', 'VIDEO ABOVE. This is a super easy way to make gnocchi and the secret ingredient is ricotta which keeps the gnocchi soft and pillowy inside. Much easier than the classic recipe made with potato. It tastes unbelievable - soft inside, touch of sweet, golden crisp surface and finished with a classic Sage Butter Sauce! Makes 2 very generous servings or 4 as a starter.', 'https://www.recipetineats.com/tachyon/2017/06/Pumpkin-Gnocchi-a.jpg', 20, 10, 30, 4, '[{"id": "ing_pumpkin", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_ricotta", "quantity": {"value": 0.3, "unit": "tub of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_sage", "quantity": {"value": 20.0, "unit": "kg"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}]', '[{"ingredients":["300 g /10oz fresh pumpkin (, steamed or boiled then mashed or 2/3 cup canned pumpkin puree)","1/2 cup ricotta (, full fat (Note 2))","1 1/4 cup plain flour ((all purpose flour), plus more for dusting)","1/3 cup parmesan cheese (, finely grated)","1 egg","1/4 tsp salt","Black pepper"],"purpose":"Gnocchi Dough"},{"ingredients":["1 tsp olive oil","50g / 3.5 tbsp butter (Note 3)","20 fresh sage leaves"],"purpose":"Sage Butter Sauce:"},{"ingredients":["Black pepper (and salt if needed)","Parmesan"],"purpose":"To serve:"}]', '[{"description":"Line a colander with 4 sheets of paper towel. Spread the fresh mashed pumpkin or canned puree onto the paper towel (see photo in post) then leave for 5 minutes.","duration":5,"images":[],"step":1},{"description":"Measure out 1/2 cup of pumpkin puree (scale up if you scaled recipe, Note 6).","images":[],"step":2},{"description":"Place pumpkin and remaining Gnocchi ingredients in a bowl. Use a wooden spoon to mix well - it should be a soft dough. (Note 4)","images":[],"step":3},{"description":"Dust a work surface with flour, tip dough out, sprinkle with flour then pat into log shape.","images":[],"step":4},{"description":"Cut into 6 pieces. Roll into 1.7cm / 2/3\" ropes, then cut into squares (Note 5).","images":[],"step":5},{"title":"Optional","description":"Use a fork to press down lightly on the cut side of the gnocchi.","images":[],"step":6},{"description":"Cooking","images":[],"step":7},{"description":"Bring a large pot of water to the boil.","images":[],"step":8},{"description":"Scrape gnocchi onto parchment paper, then tip into water. Cook for 1 minute or until all the gnocchi rises to the surface (means it is cooked), then drain.","duration":1,"images":[],"step":9},{"description":"Meanwhile, melt about 1 teaspoon of the butter plus oil in a large skillet over medium high heat. Add gnocchi and cook, shaking the pan, until the gnocchi is just starting to turn brown (about 1 1/2 minutes).","images":[],"step":10},{"description":"Add remaining butter, once it melts, add sage leaves. Stir and cook for 2 1/2 minutes or until gnocchi is golden, sage is crisp and butter is slightly browned. Add salt if you used unsalted butter.","images":[],"step":11},{"description":"Serve immediately, garnished with parmesan and pepper.","images":[],"step":12}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dinner","snack"],"cuisine":["Italian","Western"],"categories":["italian-recipes","pasta-recipes","pumpkin","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1fb717cccf92', 'en', 'US', 'Pan Fried Gnocchi with Pumpkin & Spinach', '{See video below} Soft fluffy gnocchi, pan fried in butter to create a beautiful golden crust then tossed with roasted pumpkin & spinach in a butter sauce. I use pumpkin to fill out this recipe because it has far less calories than gnocchi for the same weight and it adds a gorgeous flavour to this dish!', 'https://www.recipetineats.com/tachyon/2017/02/Gnocchi-with-Roasted-Pumpkin-Spinach.jpg', 15, 20, 35, 2, '[{"id": "ing_pumpkin", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_gnocchi", "quantity": {"value": 350.0, "unit": "pack"}}, {"id": "ing_butter", "quantity": {"value": 45.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_baby_spinach", "quantity": {"value": 80.0, "unit": "bag of 250g"}}, {"id": "ing_sage", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["500g/1lb pumpkin, cut into 2cm / 4/5\" pieces","1 tbsp olive oil","350g/12oz gnocchi, store bought (Note 1)","45g / 3 tbsp butter, salted (unsalted also ok, just add more salt)","1 garlic clove (large), minced","80g / 2.5oz baby spinach leaves","1/2 tsp fresh sage, finely sliced","Salt & pepper","Parmesan cheese, freshly grated"]}]', '[{"description":"Preheat oven to 200C/390F. Place pumpkin in a large bowl, drizzle with oil, sprinkle with salt and pepper. Toss to coat, spread out on tray and bake for 20 - 25 minutes, turning once, until golden and soft inside. Set aside.","duration":22.5,"images":[],"step":1},{"description":"Bring a large pot of water to the boil, add a good pinch of salt. Cook gnocchi according to packet directions, or until gnocchi pops to the surface of the water (see video). SCOOP OUT a large mug of cooking water, then drain gnocchi.","images":[],"step":2},{"description":"Place butter in a skillet then put on the stove over medium high heat. Once it foams, add gnocchi immediately. Stir, turn up the heat to high, then leave to cook for about 30 seconds.","images":[],"step":3},{"description":"Add garlic and sage, then stir / toss for no longer than 1 1/2 minutes (i.e. 2 minutes in total - see note 2) until gnocchi is golden on both sides.","images":[],"step":4},{"description":"Add about 3/4 cup of gnocchi cooking water and toss - the water will evaporate quickly and transform into a sauce.","images":[],"step":5},{"description":"Then add the pumpkin, spinach and about 1/4 cup of cooking water. Stir quickly , then season with salt and pepper. Toss then serve immediately with freshly grated parmesan.","images":[],"step":6}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dinner-tonight","italian-recipes","main-dishes","pasta-recipes","pumpkin","quick-and-easy","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_222f1a3922d0', 'en', 'US', 'Garlic Butter Cauliflower Pasta with Pangritata', 'A handful of humble ingredients transforms into an incredible easy midweek meal. The key step is emulsifying the pasta (step 7) which is when the oils in the pan react with the starch in the pasta to form a sticky, luscious sauce that coats every single strand of pasta. It''s how proper Italian restaurants can make the most simple of pastas so incredible!', 'https://www.recipetineats.com/tachyon/2015/08/Garlic-Butter-Cauliflower-Pasta_600px_Featured.jpg', 10, 15, 25, 3, '[{"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_cauliflower", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.454, "unit": "pack of 500g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.5, "unit": "pack of 100g"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 to 2 slices bread (, crusts removed, preferably stale (enough to make 1/2 cup))","Oil spray (preferably olive oil)","2 tbsp unsalted butter","1 tbsp olive oil","2 garlic cloves (, smashed (Note 1))","1/2 large head of cauliflower (, broken/cut into florets about 2\"/5cm long (about 4 to 5 cups) (Note 2))","8 oz / 250 g fettuccine (or pasta of choice)","1/2 red onion (, thinly sliced)","1/2 to 1 tsp red chili flakes","1 lemon (: 2 tbsp lemon juice + zest of 1/2 the lemon)","Salt & pepper"]},{"ingredients":["Parmesan cheese (, freshly grated)","Fresh parsley (, finely chopped (optional))"],"purpose":"To serve"}]', '[{"title":"Dice the bread into small pieces","description":"you want (at least!) 1/2 cup. Spray generously with oil.","images":[],"step":1},{"description":"Heat a large skillet over medium high heat. Add the bread crumbs and saute for about 2 minutes until golden brown. Remove from the skillet into a bowl and sprinkle with salt.","images":[],"step":2},{"description":"Cauliflower Pasta","images":[],"step":3},{"description":"Return the skillet to the stove. Melt the butter then add the oil. When hot, add the smashed garlic cloves and cook for 1 minute until fragrant.","duration":1,"images":[],"step":4},{"description":"Add the cauliflower. Cook, stirring occasionally, for around 3 minutes, then add the red onion and sprinkle with salt and pepper. Continue cooking for another 5 minutes, until the cauliflower is beautiful golden brown but still a bit firm.","images":[],"step":5},{"description":"Remove the smashed garlic cloves.","images":[],"step":6},{"title":"Meanwhile, cook the pasta in salted boiling water","description":"1 minute less than the recommended cooking time on the packet!","images":[],"step":7},{"description":"RESERVE 1/2 cup of the pasta cooking water. Then drain the pasta or use tongs to transfer it directly to the skillet.","images":[],"step":8},{"description":"Pour the reserved pasta cooking water into the skillet along with the red chili flakes, a good pinch of salt and pepper. Gently toss the pasta for 1 to 2 minutes, until the water evaporates - you will be left with a luscious coating of sauce on each strand of pasta (this is called emulsification) and the cauliflower will finish cooking.","duration":1.5,"images":[],"step":9},{"description":"Remove from the stove. Grate over zest of 1/2 the lemon and drizzle over about 2 tbsp of lemon juice. Toss quickly.","images":[],"step":10},{"description":"Serve, sprinkled with Pangrattato with freshly grated parmesan and parsley, if using.","images":[],"step":11}]', '["gluten","milk"]', '["vegetarian"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dinner-tonight","italian-recipes","main-dishes","most-popular","pasta-recipes","quick-and-easy","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_227a27f9f723', 'en', 'US', 'Easy Homemade Ricotta Gnocchi', 'Using ricotta, you can make homemade gnocchi from scratch in less than 30 minutes. It''s real Italian food - fast! The gnocchi is light and fluffy, just like potato gnocchi. I''ve provided two sauces because I can''t decide which is better so choose which one you prefer! The browned butter lets the flavour of the gnocchi shine through. But you can''t be too generous with butter and I like my pasta saucy, so I''ve provided a classic tomato sauce too.', 'https://www.recipetineats.com/tachyon/2015/07/Gnocchi-Tomato-Sauce-1_MAIN_600px.jpg', 20, 10, 30, 3, '[{"id": "ing_ricotta", "quantity": {"value": 1.0, "unit": "tub of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.375, "unit": "pack of 200g"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.794, "unit": "kg"}}, {"id": "ing_mixed_italian_herbs", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_parmesan", "quantity": {"value": 0.375, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["250g / 8oz ricotta (, must be full fat (Note 1))","3/4 cup (75g) freshly grated parmesan cheese (Note 2)","1 large egg (55 - 60g/2oz)","1 egg yolk (egg white use ideas here)","1/4 tsp cooking salt / kosher salt","Pinch black pepper","3/4 to 1 cup flour (plain/all-purpose), plus more for dusting (Note 3)"],"purpose":"Gnocchi"},{"ingredients":["4 tbsp / 60 g unsalted butter","1/4 tsp cooking / kosher salt (omit if using salted butter)","Black pepper"],"purpose":"Browned Butter Sauce"},{"ingredients":["2 tbsp olive oil","3 garlic cloves (, minced)","1/2 onion (, finely diced)","28 oz / 800 g canned crushed tomatoes","1 tbsp mixed dried Italian herbs (or any combination of dried parsley, basil, oregano and thyme)","1 tsp salt","Black pepper"],"purpose":"Tomato Sauce"},{"ingredients":["Freshly grated parmesan","Fresh parsley (, finely chopped (optional))"],"purpose":"Garnish"}]', '[{"description":"Homemade ricotta gnocchi","images":[],"step":1},{"title":"Mix","description":"Put all the gnocchi ingredients in a bowl except the flour. Use a rubber spatula or wooden spoon to mix until combined (smear up the wall if needed, to help cream the ricotta).","images":[],"step":2},{"title":"Add flour","description":"Add 3/4 cup of flour and mix until just combined so it is a very sticky dough that will hold its shape in a mound, but is not runny and stir-able like a batter (see video for consistency). Stickier dough = softer gnocchi! Use the remaining flour, 1 tbsp at a time, if needed, but try to stick with 3/4 cup. (Note 3)","images":[],"step":3},{"title":"Logs","description":"Sprinkle a work surface with flour then scrape the dough out onto it. Sprinkle the surface lightly with flour then use your hands to bring the dough into a disc about 2.5cm/1\" thick. Cut it into 8 wedges.","images":[],"step":4},{"title":"Roll and cut","description":"Roll each piece into a log 25cm/10\" long, about 1.25cm / 1/2\" wide. Cut into 1 1/2 cm / 3/5\" pieces (I cut 4 logs at a time).(Can freeze at this point - Note 4)","images":[],"step":5},{"description":"Cook gnocchi","images":[],"step":6},{"title":"Boil","description":"Bring a large pot of water to boil. Tumble the gnocchi in and cook for around 2 1/2 minutes, or until the gnocchi is floating on the surface for around 30 seconds.","images":[],"step":7},{"title":"Drain","description":"Reserve 1 mug of cooking water. Then drain and add the gnocchi into the frypan with your sauce of choice (you only need one of them, not both). Follow the instructions below.","images":[],"step":8},{"description":"Browned Butter Sauce","images":[],"step":9},{"description":"Melt the butter in a large fry pan over medium high heat. Let it bubble until it turns brown. Add the salt and pepper. If the gnocchi isn''t ready yet, remove from the stove until ready.","images":[],"step":10},{"title":"Add gnocchi","description":"Pour the cooked gnocchi into the fry pan along with 1/2 cup of the reserved cooking water. Gently stir, coating the gnocchi in the melted butter, cooking for 1 minute. This is the step when the butter and starch in the water emulsify so the sauce coats each piece of gnocchi.","duration":1,"images":[],"step":11},{"description":"Do a taste test and add more salt if required. Serve immediately.","images":[],"step":12},{"title":"Sauté","description":"Heat the olive oil over medium high heat. Add the garlic and onion. Sauce for 3 to 5 minutes until the onion is translucent. Add the remaining ingredients and cook for 10 minutes. Do a taste test and adjust saltiness to taste.","duration":4,"images":[],"step":13},{"description":"Add the gnocchi and 1/2 cup of the reserved cooking water. Cook for 1 minute, stirring gently. The olive oil and starch in the water will emulsify to thicken the sauce so it clings to the gnocchi better.","duration":1,"images":[],"step":14},{"description":"To Serve","images":[],"step":15},{"description":"Serve immediately as the gnocchi will start to harden after about 15 minutes as it cools. You can reheat in the microwave to soften.","images":[],"step":16},{"description":"Garnish with freshly grated parmesan and parsley, if desired.","images":[],"step":17}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["dinner-tonight","italian-recipes","main-dishes","most-popular","pasta-recipes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bb75254ce8c3', 'en', 'US', 'Fettuccine Alfredo', 'This recipe is an indulgent pasta you can make from scratch in just over 15 minutes, start to finish. Leisurely too, no rush! Have all the ingredients laid out and ready to go so the pasta finished cooking just when the sauce is ready. This pasta easily serves 3 people. It''s only 420 calories per serving because this is a proper restaurant version where the sauce is emulsified (step 7) so the sauce clings to each pasta rather than the pasta swimming in a lot of creamy sauce.', 'https://www.recipetineats.com/tachyon/2015/06/Alfredo-Fettuccine_680px_action.jpg', 5, 13, 18, 3, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.454, "unit": "pack of 500g"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 0.375, "unit": "pack of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}]', '[{"ingredients":["8 oz / 250g dried fettuccine","3 tbsp unsalted butter","1 small shallot (, very finely minced (eschallot in Australia) (Note 1))","1/2 cup heavy cream (Note 2)","3/4 cup freshly grated Parmigiano Reggiano or parmesan (Notes 3 and 4)","1/4 tsp salt","Good grind of black pepper"]},{"ingredients":["Fresh parsley (optional)","Extra Parmigiano Reggiano"],"purpose":"Garnish"}]', '[{"description":"Bring a large pot of salted water to boil. Add the fettuccine and cook until al dente (still firm but just cooked through). (Note 5)","images":[],"step":1},{"description":"Meanwhile, melt the butter in a deep fry pan over medium high heat. (Note 6)","images":[],"step":2},{"description":"Add the shallots and sauté for 2 minutes or until tender.","duration":2,"images":[],"step":3},{"description":"Add the cream and bring to boil. Turn heat down to medium low and simmer for 3 minutes.","duration":3,"images":[],"step":4},{"description":"Remove the fry pan from the heat and stir through the Parmigiano Reggiano, salt and pepper until the sauce is smooth.","images":[],"step":5},{"description":"TAKE OUT 1/4 cup of pasta water PLUS scoop out an extra mug (extra, just in case). Then drain the pasta in a colander.","images":[],"step":6},{"description":"Transfer the pasta and 1/4 cup of reserved pasta water into the fry pan with the sauce. Return the fry pan to the stove over medium high heat. Toss very gently to coat the pasta in the sauce and allow the sauce to emulsify (Note 6) for 1 minute. (Note 7)","duration":1,"images":[],"step":7},{"description":"Remove from the stove and serve immediately, garnished with extra Parmigiano Reggiano and fresh parsley, if using.","images":[],"step":8}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["dinner-tonight","italian-recipes","main-dishes","most-popular","pasta-recipes","quick-and-easy","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a1b225afe734', 'en', 'US', 'Shrimp / Prawn Pasta with Lemon', 'Using the prawn / shrimp heads and shells to make a quick stock (which is used as the sauce) takes this pasta to the next level. The pasta has a thick glossy coating from the "emulsification" of the starchy water and oil in pan combined with the rich, deep flavour of the prawn sauce.', 'https://www.recipetineats.com/tachyon/2014/12/Lemon-Prawn-Shrimp-Pasta.jpg', 20, 40, 60, 4, '[{"id": "ing_large", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.8, "unit": "pack of 500g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.8, "unit": "pack of 500g"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.5, "unit": "punnet of 250g"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 0.9, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 0.9, "unit": "bunch"}}]', '[{"ingredients":["1 lb / 500g large (, raw, unpeeled prawns/shrimp)","2 garlic cloves (, minced)","2 tbsp extra virgin olive oil"],"purpose":"Prawns / Shrimp"},{"ingredients":["1 cup chicken or fish stock/broth (or vegetable)","1 1/2 cups water","1/2 cup white wine (optional - sub with water)","1/2 onion (, roughly chopped)"],"purpose":"Stock"},{"ingredients":["400 g / 13oz spaghetti","3/4 cup pasta cooking water (i.e. scoop it out once the pasta is cooked)","3 tbsp extra virgin olive oil (, plus extra for drizzling)","1 garlic clove (, minced)","1 1/2 punnets cherry tomatoes (, cut in half (or 3 large tomatoes, diced))","1 large lemon ((or 1 1/2 small lemons), zest and juice)","3 tbsp fresh parsley (, finely chopped)","2 tsp dried chili flakes (optional)","Salt","Black pepper"],"purpose":"Pasta"},{"ingredients":["Extra lemon wedges","Extra fresh parsley (, finely chopped)"],"purpose":"To Serve"}]', '[{"description":"Peel and devein the prawns, keeping the tails in tact. (Note 1)","images":[],"step":1},{"description":"Discard the vein and place the heads and shells in a saucepan or pot to make the stock. (Note 2)","images":[],"step":2},{"description":"Cut the larger prawns lengthwise in half.","images":[],"step":3},{"description":"Add 2 minced garlic cloves the minced garlic and 2 tbsp of olive oil. Use your fingers to gently coat the prawns. Cover and set aside to marinate while you make the stock.","images":[],"step":4},{"description":"Add the remaining stock ingredients into the saucepan/pot and place over high heat. Bring to boil then turn down to medium / medium high and let it simmer rapidly.","images":[],"step":5},{"description":"Get a potato masher and \"crush\" the prawn heads and shells (to extract maximum flavour). Do this a couple of times while it is simmering.","images":[],"step":6},{"description":"When the liquid has reduced to around 1 to 1 1/2 cups, strain the stock into a bowl, then pour the stock back into the pot. (Note 3) Place lid on, then set the stock aside, keeping it warm until required.","images":[],"step":7},{"description":"Cook the Pasta and Prawns/Shrimp","images":[],"step":8},{"description":"Bring a large pot of water with 2 tsp of salt to boil. Add pasta and cook until just before al dente (Note 4).","images":[],"step":9},{"description":"While the pasta is cooking, heat 1 tbsp olive oil in a large deep fry pan over high heat.","images":[],"step":10},{"description":"Add the prawns and cook the first side for 1 minute, then turn and cook the other side for 1 minute. Remove onto a plate, loosely cover with foil and set aside. (Note 5)","duration":1,"images":[],"step":11},{"description":"Add the remaining 2 tbsp of olive oil and 1 garlic clove (minced) into the fry pan. Scrape the residual oil and garlic from the bowl the prawns were marinating in as well. Return the fry pan to the stove and sauté until the garlic is fragrant.","images":[],"step":12},{"description":"Transfer the cooked pasta into the fry pan (use tongs to transfer it from the pasta pot) along with 3/4 cup of the pasta water (this is a key step) and cherry tomatoes. Gently toss the pasta in the fry pan for around 1 minute. The water will thicken and turn into a glossy coating on the pasta.","images":[],"step":13},{"description":"Add the lemon zest, lemon juice, parsley, chilli (if using) and prawns/shrimp. Quickly toss to combine, then pour over the stock and toss quickly to coat all the pasta. Then remove from heat immediately.","images":[],"step":14},{"description":"Season to taste with salt and pepper (always do this last).","images":[],"step":15},{"description":"Drizzle with extra olive oil, and serve immediately, with extra lemon wedges and fresh parsley if desired.","images":[],"step":16},{"title":"Note","description":"seafood pastas and risottos are not traditionally garnished with parmesan (in Italy), however, I say do as you wish!","images":[],"step":17}]', '["fish","gluten","shellfish"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["dinner-tonight","italian-recipes","main-dishes","most-popular","pasta-recipes","prawns-shrimp","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e0c662937c93', 'en', 'US', 'Slow Cooker Marinara Sauce', 'A good marinara sauce is an essential for everyone. I love this one because you just dump the ingredients into a slow cooker then leave it to work it''s magic. The slow cooking caramelises the sugar in the tomato and creates a depth of flavour you will never get from store bought pasta sauce.', 'https://www.recipetineats.com/tachyon/2014/08/Slow-Cooker-Marinara-Sauce-1.jpg', 5, 360, 365, 6, '[{"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_basil", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_balsamic_vinegar", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["2 cans (800g/28oz each can) crushed tomatoes (see notes)","1 can (170 g / 6 oz) tomato paste","1 medium brown onion ((or white or yellow), diced)","2 garlic cloves (, minced)","2 bay leaves (dried or fresh)","1 tbsp brown sugar (or honey)","1 tbsp dried basil","2 tsp dried oregano","2 tbsp olive oil","1 tbsp balsamic vinegar","1 1/2 tsp salt","1/2 tsp black pepper"]}]', '[{"description":"Combine all ingredients in a slow cooker. Set for 6 to 8 hours on low.","images":[],"step":1},{"title":"Optional step","description":"Remove bay leaves, then use a handheld blender to puree until smooth (or to your liking).","images":[],"step":2},{"description":"Cool before refrigerating or freezing.","images":[],"step":3},{"description":"To use for pasta","images":[],"step":4},{"description":"Bring a large pot of salted water to boil and add pasta.","images":[],"step":5},{"description":"Heat olive oil in a pan, add garlic and diced onion, cook until translucent then add 2 cups of Marinara Sauce per 500g/1lb of dried pasta.","images":[],"step":6},{"description":"Bring sauce to rapid simmer, then add pasta (cooked to just before al dente).","images":[],"step":7},{"description":"Add 1/4 cup of pasta water and cook for 1 to 2 minutes until pasta is al dente and the sauce has thickened and coats the pasta.","duration":1.5,"images":[],"step":8},{"description":"Serves 4 hungry people or 6 normal servings.","images":[],"step":9}]', '[]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["italian-recipes","main-dishes","most-popular","pasta-recipes","quick-and-easy","slow-cooker-recipes","vegan-lifestyle","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5bf716f73c3d', 'en', 'US', 'Beurre Blanc Sauce', 'Recipe video above. This classic and elegant Beurre Blanc sauce is beautifully light yet creamy with a signature tang. Often served with a simple pan-fried fish at fine-dining restaurants, bistros and cafés, it also works well with shellfish, chicken or even vegetables. Simple to make but like any butter-emulsified sauce it can be temperamental. So I’d say two things: cold butter and low heat! Follow those two rules, take your time, and the sauce will come together perfectly.Optional safeguard against splitting - just use a bit of cream. See Note 4.', 'https://www.recipetineats.com/tachyon/2026/05/Beurre-blanc-sauce-9.jpg', 5, 15, 20, 4, '[{"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_wine", "quantity": {"value": 0.083, "unit": "bottle of 750ml"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 200.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.12, "unit": "carton of 250ml"}}]', '[{"ingredients":["1 small eschalot (, finely diced - aka French onion, US: shallot (Note 1))","1/4 cup white wine (, dry, not sweet or too woody (chardonnay is good) (Note 2))","2 tbsp white wine vinegar (Note 3)","200g / 2 sticks unsalted butter (, cold, cut in small dice 1cm / 0.4\" (keep in fridge until needed))","1/2 tsp cooking salt / kosher salt (, (or half for table salt, +50% for flakes))"]},{"ingredients":["2 tbsp thickened cream / heavy cream (Note 4)"],"purpose":"Optional safeguard from splitting"}]', '[{"description":"Reduce onion shallot, wine and vinegar to 2–3 tbsp of liquid. On low heat, whisk in 1 tbsp cold butter at a time. Add salt, strain. Use immediately.","images":[],"step":1},{"title":"Make reduction","description":"In a small saucepan over medium heat, add the onion shallot, white wine and vinegar. Let it simmer gently until it reduces by 2/3 (about 5 minutes once it starts simmering). You should have just 2 to 3 tablespoons of the liquid left no including the onion shallot. If using cream (see Note 4), add it now and continue simmering until the mixture reduces again to just 2 to 3 tablespoons of liquid. (Note 5)","images":[],"step":2},{"title":"Add COLD butter","description":"Turn the heat to low. That is very important because if it’s too hot, your sauce will split (you don''t want the mixture to even reach a simmer, use your smallest burner). Add the cold butter, one heaped tablespoon at a time while whisking briskly and constantly. (Note 6)","images":[],"step":3},{"title":"Emulsify sauce","description":"Let each addition melt before adding more. The sauce will thicken as you add the butter and will become of a pale milky yellow colour. This should take around 5 minutes. Add the salt in at the end. (Note 7)","images":[],"step":4},{"title":"Sauce consistency","description":"Keep whisking until all the butter is incorporated, the sauce should be slightly thickened like pouring cream with a pale yellow colour. It should lightly coat the back of a spoon.","images":[],"step":5},{"title":"Strain","description":"Strain the sauce through a fine sieve into another small saucepan, pressing on the eschalots to extract all the flavour. (Note 9)","images":[],"step":6},{"title":"Warm and serve","description":"Place the saucepan over LOW heat on your smallest burner to keep the sauce gently warm while you cook your protein. The heat must stay very low or the sauce will split. You only want to keep it warm, not hot. (Note 8) When needed, spoon generously over fish like I do here or chicken, or even simple steamed vegetables. Sprinkle some finely chopped chive over the top and enjoy!","images":[],"step":7}]', '["milk"]', '["gluten_free","keto_friendly","vegetarian"]', '{"mealType":["main_course"],"cuisine":["French"],"categories":["jbs-recipes","sauces"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bfb38911c291', 'en', 'US', 'Poulet Rôti - French Roast Chicken', 'Recipe video above. You''ve been asking for a simple but delicious roast chicken? Say no more! You must try this French roast chicken. With a herbes de Provence butter tucked under its skin and cooked over potato chunks and whole cloves of garlic, this pot roast chicken will be the juiciest piece of meat you''ve had for a long time. So now it''s time to treat yourself! Say "Oui, oui!" to juicy chicken fragrant with herbs, confit garlic and melt in your mouth potatoes! Please make sure you don''t cut the potatoes too small else they will turn to mush before the chicken is cooked. Cut to the size I specify.', 'https://www.recipetineats.com/tachyon/2026/04/Poulet-Roti_6.jpg', 40, 70, 110, 4, '[{"id": "ing_chicken", "quantity": {"value": 1.8, "unit": "kg"}}, {"id": "ing_herbes_de_provence", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_potato", "quantity": {"value": 750.0, "unit": "bag of 2kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["1.8kg / 4lb whole chicken (Note 1)","1 1/2 tsp herbes de Provence (, buy or make your own (Note 2))","3 thyme sprigs (, optional)","3/4 tsp cooking salt / kosher salt (, halve for table salt, +50% for flakes)","1 tbsp extra virgin olive oil"]},{"ingredients":["100g / 1 stick unsalted butter (, softened)","2 garlic cloves (, finely grated)","3 tsp herbes de Provence (Note 2)","1 tsp cooking salt / kosher salt (, halve for table salt, +50% for flakes)"],"purpose":"Herbs Butter"},{"ingredients":["750g / 1.65lb starchy potatoes","8 garlic cloves (, whole, unpeeled)","3/4 tsp cooking salt / kosher salt (, halve for table salt, +50% for flakes)","1/2 tsp black pepper","3 tbsp extra virgin olive oil"],"purpose":"Potatoes"}]', '[{"description":"Spread Herb Butter under chicken skin. Rub chicken with oil, salt inside and skin. Roast on potatoes and garlic – covered 30 minutes at 210°C / 410°F (190°C fan-forced), then 40 minutes uncovered, basting 3 times, or until the internal temperature reaches 72°C. Rest upright 15 minutes.","images":[],"step":1},{"description":"Preheat oven to 210°C / 410°F (190°C fan-forced). Place a 28cm cast-iron pot (no lid) in the oven to heat up.","images":[],"step":2},{"title":"Bring chicken to room temp","description":"Remove the chicken from the fridge and its packaging. Place it on a plate and let it sit on the counter while you prepare everything else. (Note 4)","images":[],"step":3},{"title":"Make herb butter","description":"In a small bowl, mix the softened butter with herbes de Provence, salt and finely grated garlic until well combined. Set aside.","images":[],"step":4},{"description":"Prepare Chicken and Potatoes","images":[],"step":5},{"description":"Pat the chicken completely dry with paper towels, including the skin and inside the cavity.","images":[],"step":6},{"title":"Loosen the skin","description":"From the tail end, gently slide an upside down spoon (not too large, dessert size is ideal for this) between the skin and the breast meat using slow sweeping motions to break membrane connecting them. After the breasts, use the same technique for the thighs and drumsticks. (Note 5)","images":[],"step":7},{"title":"Add butter under the skin","description":"Start with the breast, spoon 2/3 of the butter directly onto the meat under the skin and gently press on the outside of the skin with your hands to flatten and spread it all over evenly. Then divide the remaining butter between the two legs and spread it the same way. (Note 6)","images":[],"step":8},{"title":"Season and finish the chicken","description":"Season inside the cavity with 1/4 tsp salt, Herbs de Provence and thyme sprigs. Tie the drumsticks tightly together. Rub the whole chicken with olive oil and season the outside evenly with the remaining salt. Tuck the wings under and set aside on the counter.","images":[],"step":9},{"title":"Prepare potatoes","description":"Place potatoes, whole garlic cloves, salt, pepper and olive oil in a mixing bowl. Toss well to coat, then set aside.","images":[],"step":10},{"title":"Roast covered","description":"Carefully remove the hot pot from the oven. Place the potatoes at the bottom, then place the chicken on top. Cover loosely with foil and roast for 30 minutes. (Note 7)","duration":30,"images":[],"step":11},{"title":"Baste and continue roasting","description":"Remove the pot from the oven and take off the foil. Baste the chicken with the juices in the pot, moving the potatoes aside if needed to access the liquid (a spoon works fine, though a baster is perfect for this). Return to the oven and roast uncovered for 40 minutes, basting twice more until the internal temperature at the thigh joint reaches 72°C / 162°F (if slightly over, don’t stress, this one is very forgiving). (Note 8)","duration":40,"images":[],"step":12},{"title":"Rest (very important!)","description":"Lift and rest the chicken on its side in the pot, legs up, breast side down. Baste once more with the juices, then rest for 15 minutes. (Note 9)","duration":15,"images":[],"step":13},{"title":"Serve","description":"Carve the chicken (See video. Don''t forget the oysters, the small, very tender pieces of meat on the back near the thigh. There are only two, and they are the best bites. Easy to miss, so don’t forget them!) and serve with the potatoes, all the pan juices and a sprinkle of fresh thyme leaves. Enjoy! (Note 10)","images":[],"step":14}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["French"],"categories":["jbs-recipes","main-dishes","roasts"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_529970970327', 'en', 'US', 'Coquillettes au Jambon - French Macaroni and Cheese with Ham', 'Recipe Video above. A stovetop mac & cheese, that''s what this is really! Without the hassle of baking it! This dish was a big part of my childhood diet and even now but somehow never got sick of it. Who wouldn''t? Pasta, cheese sauce and ham. A great comfort meal, done fast and done right. Enjoy!', 'https://www.recipetineats.com/tachyon/2026/04/Coquilettes-au-jambon_0.jpg', 10, 15, 25, 5, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_ham", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 75.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_round_nutmeg", "quantity": {"value": 1.25, "unit": "jar"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}]', '[{"ingredients":["500g / 1 lb elbow pasta / macaroni (, but any similar size pasta would work )","1 tsp cooking salt / kosher salt (, for pasta water, half for table salt)","200g / 7 oz ham slices (I use ham off-the-bone), diced 1cm / 0.4\" (Note 1)"]},{"ingredients":["75g / 5tbsp tbsp unsalted butter","1/2 cup plain flour / all-purpose flour","3 cups milk (, HOT, full fat preferred, but work with lite milk too)","1 tsp cooking salt / kosher salt (, halve for table salt, +50% for flakes)","3/4 tsp black pepper","1/4 tsp ground nutmeg (, (Note 2))","1 1/2 cups Gruyère cheese, grated (, shredded using a standard box grater (tightly packed if using cups) (Note 3))","1/2 cup pasta cooking water"],"purpose":"CHEESE SAUCE (MORNAY SAUCE)"}]', '[{"description":"Cook pasta per packet directions, scoop out 1 cup of water just before draining. In the same pot, melt butter, cook flour 2 min. Whisk in milk. Add salt, pepper and nutmeg, stir in cheese until melted. Stir in ham, then 1/2 cup pasta cooking water. Toss with pasta until coated, serve.","images":[],"step":1},{"title":"Cook pasta","description":"Bring a large pot of water and salt to the boil. Cook pasta according to packet instructions. I always like to give a few stirs at the beginning so they don''t stick to each other.","images":[],"step":2},{"description":"Reserve 1 cup pasta cooking water, then drain and give the pasta brief rinse under cold water. Set aside and keep the pot for the sauce.","images":[],"step":3},{"title":"Make roux","description":"Using the pasta pot, melt the butter over medium heat. Add flour and whisk for 2 minutes. At first it will look like thick and pasty then it will loosen to become a smooth, glossy paste. Make sure to use the whisk to get into the corners of the pot and don’t let it brown, reduce heat if needed.","duration":2,"images":[],"step":4},{"title":"Adding milk","description":"Add half of the hot milk to the roux while whisking vigorously, it will thicken very quickly. Once smooth, slowly pour in the remaining milk while continuing to whisk. Keep whisking for 30 seconds to 1 minute until the sauce is smooth, with no lumps. It should be thick enough that you can draw a path with a spatula through the middle, holding its shape briefly before slowly sinking back. (Note 4)","duration":0.5,"images":[],"step":5},{"title":"Season","description":"Add salt, pepper and nutmeg. Stir to combine.","images":[],"step":6},{"title":"Add cheese and ham","description":"Stir in Gruyère cheese and whisk until fully melted. You just made a Mornay sauce! Then stir in the ham with a wooden spoon.","images":[],"step":7},{"title":"Finish sauce","description":"Pour in 1/2 cup of the reserved pasta cooking water and stir until silky. Bring back to a simmer. It will be quite runny, it will thicken when the pasta is added.","images":[],"step":8},{"title":"Combine","description":"Add drained pasta and stir well until fully coated, the sauce will thicken slightly and cling to the macaroni. Add more pasta water if the sauce gets too thick.","images":[],"step":9},{"description":"Serve immediately while hot and creamy. I like to grind extra black pepper on top just before eating. Enjoy!","images":[],"step":10}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["French","Western"],"categories":["jbs-recipes","main-dishes","pasta-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2c6b1fa7c0de', 'en', 'US', 'JB''s Mushroom Tart', 'Recipe video above. This is a simple mushroom tart that I used to make for my family back in France. Called "Tarte Fine aux Champignons" in French, buttery puff pastry is topped with melted Gruyère, sautéed mushrooms and baked until crispy and golden. It''s simple but delicious as a light meal with a fresh salad on the side.You''ll probably be surprised by the volume of mushrooms once sliced but it will reduce significantly as it cooks and bakes to an even layer on the puff.', 'https://www.recipetineats.com/tachyon/2026/03/JB-Mushroom-Tart_1.jpg', 20, 30, 50, 4, '[{"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_thyme", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_chilli_flakes", "quantity": {"value": 1.0, "unit": "jar of 40g"}}, {"id": "ing_extra_virgin_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}]', '[{"ingredients":["1 square sheet butter puff pastry (25cm / 10″ square), barely thawed (Note 1)","1 tbsp extra virgin olive oil","2 tbsp (30g) unsalted butter","400g / 14oz Swiss brown mushrooms (, sliced 0.5cm (Note 3))","1/2 tsp cooking salt / kosher salt (, use half for table salt)","1/4 tsp black pepper","1 1/2 cups (tightly packed) Gruyère cheese (, grated (Note 2))","2 tsp (10g) unsalted butter (, melted (for brushing))"]},{"ingredients":["1 1/2 tsp fresh thyme leaves","1 pinch sea salt flakes","truffle oil or good extra virgin olive oil (, to drizzle (optional) (Note 4))"],"purpose":"Toppings"}]', '[{"description":"Sauté mushrooms 5 minutes. Place puff pastry on baking paper, fold a 1 cm / 0.4\" border, brush edges with butter, top with Gruyère and mushrooms. Bake on the preheated tray for 30 minutes. Finish with fresh thyme, salt flakes and truffle oil.","duration":30,"images":[],"step":1},{"title":"Hot tray","description":"Place a baking tray in the oven. Turn the oven on and preheat to 210°C / 410°F (190°C fan).","images":[],"step":2},{"title":"Cook the mushrooms","description":"Heat the olive oil and butter in a frying pan over medium-high heat. Add mushrooms, salt and pepper. Cook for 5 minutes, stirring regularly, until soft. Transfer mushrooms to a colander over a bowl to drain in case of excess liquid.","duration":5,"images":[],"step":3},{"title":"Prepare the base","description":"Place a sheet of baking paper / parchment paper on the bench. Put the puff pastry on top. Fold the edges inwards to create a 1 cm / 0.4″ border and brush them with melted butter.","images":[],"step":4},{"title":"Assemble","description":"Spread the grated Gruyère evenly over the pastry. Top with the mushrooms, spreading them evenly too.","images":[],"step":5},{"title":"Bake","description":"Lift the baking paper and tart onto the hot tray in the oven. Bake for 30 minutes, until the pastry is golden and crisp (sides and underneath).","duration":30,"images":[],"step":6},{"title":"Finish and serve","description":"Sprinkle with fresh thyme leaves and salt flakes. Drizzle with truffle oil or a good virgin olive oil (optional but highly recommended). Cut and serve hot.","images":[],"step":7}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["lunch","dinner","snack"],"cuisine":["French"],"categories":["jbs-recipes","mushroom-recipes","mushrooms","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7a064c388856', 'en', 'US', 'JB''s French Pork Schnitzel', 'People say adding “French” to something doesn’t mean it’s better. But my passport would like to disagree! These schnitzels get a French flair with Herbes de Provence in the breadcrumbs. Now they''re French Pork Schnitzels - escalope de porc panées. Let’s go!', 'https://www.recipetineats.com/tachyon/2026/03/French-pork-schnitzel-1.jpg', 25, 10, 35, 4, '[{"id": "ing_beef_steak", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_bread", "quantity": {"value": 0.281, "unit": "loaf"}}, {"id": "ing_herbes_de_provence", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_chilli_flakes", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 0.4, "unit": "bunch"}}, {"id": "ing_rosemary", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_marjoram", "quantity": {"value": 1.25, "unit": "unit"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.075, "unit": "bunch"}}]', '[{"ingredients":["4 pork steaks or chops (125g to 150g / 4.4oz to 5.3oz each) (Note 1)","3/4 tsp cooking salt / kosher salt","1/2 tsp black pepper"]},{"ingredients":["1/3 cup plain flour / all-purpose flour","2 eggs, lightly whisked (, from large eggs (55g / 2oz each in shell))","1 1/2 cup panko breadcrumbs (Note 2)","3 tbsp herbes de Provence (Note 3)","1/2 cup vegetable oil (, or any other neutral flavoured oil)"],"purpose":"CRUMBING AND COOKING:"},{"ingredients":["1 lemon, cut into wedges","sea salt flakes"],"purpose":"TO FINISH:"},{"ingredients":["4 tsp dried thyme","3 tsp dried rosemary (Note 4)","1 1/4 tsp dried marjoram or savory (, sub with more thyme or rosemary)","3/4 tsp dried oregano"],"purpose":"HERBES DE PROVENCE:"}]', '[{"description":"Pound pork to 0.5cm / 0.2″, season with salt and pepper. Coat in flour, egg, then panko mixed with herbes de Provence. Fry over medium-high heat 2 minutes per side until golden.","images":[],"step":1},{"description":"Preheat the oven to 70°C / 160°F (all ovens).","images":[],"step":2},{"title":"Pound the pork","description":"Place the pork between two sheets of baking paper / parchment paper or freezer bags. (Note 5) Pound with a meat mallet until evenly 0.5 cm / 0.2 inch thick. (Note 6)","images":[],"step":3},{"title":"Season","description":"Season both sides with salt and pepper. Set aside.","images":[],"step":4},{"title":"Prepare the crumbing station","description":"Place flour, eggs, and panko mixed with herbes de Provence in three separate bowls. (Note 7)","images":[],"step":5},{"title":"Crumb","description":"Coat pork in flour and shake off excess. Dip in egg and let excess drip off. Press into the breadcrumb mixture so it sticks well. Transfer on a tray and repeat with remaining pork.","images":[],"step":6},{"title":"Cook the schnitzels","description":"Heat the oil in a frying pan over medium-high heat, it should be 0.4cm / 0.15\" deep. When hot, add 2 schnitzels. Cook 2 minutes until golden. Flip and cook the other side 2 minutes. Transfer to a rack over a tray and place in the warm oven. Repeat with the remaining two schnitzels. (Note 8)","images":[],"step":7},{"title":"Rest and Serve","description":"Let the schnitzels rest on the rack outside of the oven for 2 minutes before serving with a wedge of lemon and a sprinkle of salt flakes.","duration":2,"images":[],"step":8}]', '["egg","gluten"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["French","French influence"],"categories":["jbs-recipes","mains","pork","pork-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_762f88513d03', 'en', 'US', 'Herbes de Provence', 'This is a recipe for Herbes de Provence, a classic French herb blend. It can be surprisingly hard to find outside France so I''m sharing my recipe. There''s many versions, but this is from my restaurant days in France and is made with just 4 herbs - rosemary, thyme, marjoram and oregano. It brings the unmistakable flavour of southern France to chicken, roasted vegetables, stews, fish or even a quick salad dressing. And it''s used in my French Schnitzel Escalope de Porc Panée which I also published today.', 'https://www.recipetineats.com/tachyon/2026/03/Herbs-de-Provence_2.jpg', 5, 0, 5, 5, '[{"id": "ing_thyme", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_rosemary", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_marjoram", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_organo", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["2 tbsp dried thyme","2 tbsp dried rosemary (Note 1)","2 tsp dried marjoram (or savory) (Note 2)","1 tsp dried organo"]}]', '[{"title":"Finely chop if needed","description":"If any of the leaves are especially large (rosemary and thyme can be), finely chop them with a knife or use a spice grinder. You will get more flavour out of them.","images":[],"step":1},{"description":"Mix the dried herbs then use per recipe.","images":[],"step":2},{"description":"Store in an airtight jar in a cool, dry pantry for up to 3 months (or the shelf life of the herbs you used).","images":[],"step":3}]', '[]', '["gluten_free","keto_friendly","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["French","Provencial french"],"categories":["jbs-recipes","spice-blends"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_52d8a79e0a60', 'en', 'US', 'Creamy French Dressing', 'This is JB''s recipe for a creamy French salad dressing. I like that it''s thick enough to be visible on salad leaves, but it''s not weighed down with excessive amounts of mayo. Rather, it''s bright and a bit tangy. Toss with leafy leaves for an instant French Salad, make JB''s lovely French Baby Gem Salad, or drizzle over steamed greens to make them instantly more delicious. It would also be fabulous for a pasta salad or potato salad!Makes 100ml (just over 1/3 cup), enough to dress a side salad for 4 to 5 people.', 'https://www.recipetineats.com/tachyon/2026/03/Creamy-French-Dressing.jpg', 10, 0, 10, 100, '[{"id": "ing_mayonnaise", "quantity": {"value": 0.075, "unit": "jar of 400g"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_grapes", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_chive", "quantity": {"value": 0.022, "unit": "kg"}}]', '[{"ingredients":["2 tbsp whole-egg mayonnaise (, or Kewpie (Note 1))","1 tsp Dijon mustard","1 tbsp white wine vinegar (Note 2)","2 tbsp extra virgin olive oil","1 tbsp grapeseed oil (, or vegetable, canola or other plain flavoured oil (Note 3))","1/4 tsp cooking salt / kosher salt (halve for table salt, + 50% for flakes)","1/8 tsp black pepper","2 tsp water","1 1/2 tbsp finely chopped chive (Note 4)"]}]', '[{"title":"Shake","description":"Place all the ingredients in a jar and shake until combined. Alternatively, whisk in a small bowl or jug.","images":[],"step":1},{"description":"Keeps in the fridge for 3 days.","images":[],"step":2},{"title":"To use","description":"drizzle over leafy greens and toss gently to coat. Pictured in post on a French Bistro Baby Gem Salad.","images":[],"step":3}]', '["egg","mustard"]', '["gluten_free","keto_friendly","vegetarian"]', '{"mealType":["lunch"],"cuisine":["French"],"categories":["jbs-recipes","salad-dressings"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a05413b74db3', 'en', 'US', 'Coquilles Saint-Jacques', 'Recipe video above. Coquilles Saint-Jacques is a French scallop au gratin starter, a true bistro classic I''ve always loved. With sweet scallops baked in a creamy mushroom Béchamel and a golden cheesy crust, you''ll be surprised how easy it is to make. Comforting and rich, a lovely way to start a dinner.', 'https://www.recipetineats.com/tachyon/2025/12/Coquilles-Saint-Jacques_7-1.jpg', 30, 20, 50, 4, '[{"id": "ing_7_1_medium_scallops", "quantity": {"value": 0.22, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_mushroom", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_nutmeg", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_bread", "quantity": {"value": 0.141, "unit": "loaf"}}, {"id": "ing_cheese", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}]', '[{"ingredients":["220g / 7 1/2 oz medium raw scallops (Note 1)","1/4 tsp cooking salt / kosher salt"]},{"ingredients":["30g / 2 tbsp unsalted butter","1 eschalot (US: shallot), finely diced (Note 2)","200g / 7 oz white mushrooms (, diced 8mm / 1/4\")","2 tbsp plain flour (all-purpose)","1/2 cup hot milk (, preferably full fat but works with lite milk too)","1/2 cup hot thickened cream (heavy cream) (, or any other full fat cream)","1/4 tsp cooking salt / kosher salt","1/8 tsp black pepper","1 pinch ground nutmeg"],"purpose":"Mushroom Béchamel Sauce"},{"ingredients":["3/4 cup panko breadcrumbs (Note 3)","50 g / 3 tbsp unsalted butter (, melted)","50g / 1/2 cup Gruyère cheese (, shredded using a standard box grater (tightly packed if using cups) (Note 4))","1/8 tsp cooking salt"],"purpose":"Cheesy Crust"}]', '[{"description":"Pat scallops dry, remove the chewy side muscle, slice in half. Cook mushrooms and eschalot in butter, make a creamy béchamel. Mix the crust. Season and cover scallops in gratin dishes, top with crust, bake 20 minutes at 200°C / 400°F (180°C / 350°F fan).","images":[],"step":1},{"description":"Preheat oven to 200°C / 400°F (180°C fan-forced).","images":[],"step":2},{"title":"Prepare the scallops","description":"Pat them dry with paper towel. Remove the little side muscle (the “foot”) if you see it, it''s edible but get chewy when cooked. (Note 1) Set aside until needed.","images":[],"step":3},{"description":"Mix the crust ingredients and set aside until needed.","images":[],"step":4},{"description":"Mushroom Béchamel Sauce","images":[],"step":5},{"description":"Melt butter in a medium pot over medium heat. Add the eschalot and mushrooms. Stir regularly and cook for 4–5 minutes until the mushrooms are soft.","duration":4.5,"images":[],"step":6},{"description":"Add flour. Stir and cook for 30 seconds. It will look a bit pasty, that’s normal.","duration":0.5,"images":[],"step":7},{"description":"Pour in the hot milk and cream. Then stir until incorporated and lump free. (Note 5)","images":[],"step":8},{"title":"Thicken","description":"Add the salt, pepper and nutmeg, then stir well. When you see the first small bubbles appearing, let it cook for 30 seconds, then take it off the stove. It should be more pourable than a regular Béchamel, so it spreads easily around the scallops. (Note 6)","duration":0.5,"images":[],"step":9},{"description":"Season the scallops with salt and divide them between 4 shallow ramekins. (We use flat round ramekins: 11cm / 4.3\" diameter, 2.5cm / 1\" deep.) (Note 7)","images":[],"step":10},{"title":"Sauce","description":"Cover scallops with ALL the mushroom béchamel. Make sure to fill up all the gaps. Flatten the surface with a small spatula or the back of a spoon.","images":[],"step":11},{"title":"Cheesy crust","description":"Scatter the cheesy crust evenly over each ramekin, right to the edges. We want a golden top with no empty spots.","images":[],"step":12},{"title":"Bake","description":"Place ramekins on a tray and bake 20 minutes until golden.","images":[],"step":13},{"title":"Serve","description":"Rest 2 minutes, then serve. (Note 8) And bon appétit, of course!","images":[],"step":14}]', '["gluten","milk"]', '["vegetarian"]', '{"mealType":["snack"],"cuisine":["French"],"categories":["jbs-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ea459fbbf11b', 'en', 'US', 'Lamb tagine', 'Recipe video above. My favourite of all tagines! The ras el hanout spice mix is sheer perfection with lamb, and slow cooking works wonders to develop rich flavours in the sauce and make the lamb fork tender. Serve over couscous for a stunning Moroccan meal. Your house will smell amazing!-> Also see Chicken and Vegetable Tagine.', 'https://www.recipetineats.com/tachyon/2023/08/Lamb-tagine_4.jpg', 15, 120, 135, 5, '[{"id": "ing_lamb", "quantity": {"value": 1.6, "unit": "kg"}}, {"id": "ing_lamb", "quantity": {"value": 1.6, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 2.0, "unit": "jar"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.625, "unit": "L"}}, {"id": "ing_apricots", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_turmeric", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_fennel", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_round_clove", "quantity": {"value": 15.0, "unit": "jar"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_almonds", "quantity": {"value": 0.3, "unit": "pack of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_batches_couscous", "quantity": {"value": 1.5, "unit": "pack"}}]', '[{"ingredients":["1.6 kg/ 3.2lb boneless lamb shoulder, trim the fat, then ( cut in 3.5cm / 1.5\" cubes (1kg/2lb after trimming))","1 kg / 2 lb lamb stewing meat or shoulder, already trimmed of fat (cut in 3.5cm / 1.5\" cubes)"],"purpose":"Use one of these lambs (Note 1):"},{"ingredients":["1 tsp cooking/kosher salt","1/2 tsp black pepper","3 tbsp canola oil","3 garlic cloves (, finely minced)","2 brown onions (, diced (1cm / 0.3\" cubes))","1 1/2 tbsp tomato paste","2 tsp grated ginger","2 cinnamon sticks","2 1/2 cups chicken stock/broth (, low sodium)","1 cup dried apricots (, whole (Note 2 for olives option))","2 - 3 tsp lemon zest (just use 1 whole lemon, Note 3 for preserved lemon)"],"purpose":"Tagine:"},{"ingredients":["1 tbsp ground coriander","1 tbsp ground cumin","2 tsp ground cardamom","2 tsp turmeric powder","1 1/2 tsp fennel powder","1 tsp cayenne pepper (can reduce for less spicy - Note 4)","1/4 tsp ground cloves","1/4 tsp ground ginger","1/2 tsp cooking/kosher salt"],"purpose":"Ras el hanout (Note 4):"},{"ingredients":["1/2 cup slivered almonds (, toasted (Note 5))","1/2 cup coriander/cilantro leaves roughly chopped","1 1/2 batches couscous (I just use plain, but you can add the fruit and nuts if you want)"],"purpose":"For serving:"}]', '[{"description":"Preheat oven to 180°F/350°F (160°C fan). (Note 6 re: other cook methods)","images":[],"step":1},{"title":"Spice mix","description":"Mix the ingredients in a bowl then set aside.","images":[],"step":2},{"title":"Brown lamb","description":"Toss lamb with the salt and pepper. Heat the oil in a large oven-proof dutch oven (with a lid) over high heat. Brown the lamb in 3 batches, turning to colour the pieces all over, about 3 minutes. Remove into a bowl, then repeat with remaining lamb. Set aside.","images":[],"step":3},{"title":"Aromatics","description":"Turn heat down to medium high. Add onion and garlic, cook for 3 minutes until soft. Add tomato paste, ginger, cinnamon and spice mix. Cook for 1 1/2 minutes, stirring constantly.","duration":3,"images":[],"step":4},{"title":"Sauce","description":"Add chicken stock and water, stir, then return the lamb into the pot.","images":[],"step":5},{"title":"Slow cook 1 hr 45 min","description":"Bring to a simmer, cover with a lid then cook in the oven for 45 minutes. Add apricots, put the lid back on and cook for another 1 hour, checking halfway to ensure the sauce hasn''t reduced all the way (if you''re concerned, add 1/2 cup water).","duration":45,"images":[],"step":6},{"title":"Lemon finish","description":"Lamb should be tender - check! Gently stir in lemon zest.","images":[],"step":7},{"description":"Serve over plain couscous, sprinkled with almonds and coriander.","images":[],"step":8}]', '["gluten"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Moroccan","North African"],"categories":["lamb","lamb-recipes","mains","moroccan","slow-cooked-fall-apart","stews"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ce03cd624a01', 'en', 'US', 'Persian Lamb Shanks', 'Recipe video above. A traditional Persian dish - fall apart lamb shanks with a well seasoned, delicately flavoured broth. Pair this with the iconic Persian Tachin (baked saffron rice), a Persian chopped salad and finish with a Persian Love Cake to complete your Persian feast!', 'https://www.recipetineats.com/tachyon/2018/09/Persian-Lamb-Shanks_6.jpg', 10, 180, 190, 4, '[{"id": "ing_amb_shanks", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 10.0, "unit": "pack of 3 heads"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_turmeric", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_nutmeg", "quantity": {"value": 1.25, "unit": "jar"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_cinnamon", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_cinnamon", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_saffron_threads", "quantity": {"value": 1.25, "unit": "jar"}}]', '[{"ingredients":["4 lamb shanks (, about 300g/10oz each (Note 1))","Salt and pepper","1 - 2 tbsp vegetable oil (or canola)","1 large onion (, sliced (yellow, brown))","6 cloves garlic (, chopped)","1 litre / 4 cups water","500 ml / 2 cups chicken broth","2 medium tomatoes (, chopped)"]},{"ingredients":["1 tsp turmeric","3/4 tsp salt","1/4 tsp + 1/8 tsp nutmeg","1/4 tsp + 1/8 tsp cardamom powder","1/2 tsp cinnamon","1/8 tsp extra cinnamon (, extra for later)","1/4 tsp saffron threads (Note 2)"],"purpose":"Spices:"}]', '[{"description":"Sprinkle shanks with salt and pepper.","images":[],"step":1},{"description":"Heat 1 tbsp oil in a large heavy based pot over medium high heat. Brown shanks all over, 2 at a time. Remove from pot.","images":[],"step":2},{"description":"Discard excess oil, clean pot if it''s very dirty.","images":[],"step":3},{"description":"Add 1 tbsp oil. Cook onion and garlic for 2 minutes until translucent.","duration":2,"images":[],"step":4},{"description":"Stir in the turmeric, cinnamon, tomatoes, and salt.","images":[],"step":5},{"description":"Add chicken broth and stir well.","images":[],"step":6},{"description":"Place shanks in pot, then add water as needed so the shanks are 3/4 or fully covered, but no more than 1L/4 cups water. (Note 2)","images":[],"step":7},{"description":"If shanks not fully submerged, make a cartouche (baking paper lid, Note 3).","images":[],"step":8},{"description":"Bring up to the boil. Place the cartouche snugly on surface (if using), cover pot leaving a little crack (to ensure it doesn''t boil over).","images":[],"step":9},{"description":"Turn heat down so simmering very gently. Cook 1.5 hours, turning every 30 minutes.","images":[],"step":10},{"description":"Add cardamom and nutmeg into liquid.","images":[],"step":11},{"description":"Cook for another 1 hour until meat is very tender and falling off the bone.","images":[],"step":12},{"description":"Carefully remove meat from liquid into a bowl and cover with foil.","images":[],"step":13},{"title":"Simmer broth rapidly 30","description":"45 min until reduced by half.","images":[],"step":14},{"description":"Add saffron and remaining 1/8 tsp cinnamon.","images":[],"step":15},{"title":"Simmer further 10","description":"15 min until reduced to 500 ml / 2 cups. Should taste like a very well seasoned, intensely savoury but lightly spiced broth.","images":[],"step":16},{"description":"Return meat to pot to gently reheat for a few minutes, turning and basting the meat with the liquid to keep it moist.","images":[],"step":17},{"description":"Serve shanks with the braising liquid as a sauce. Pictured garnished with pomegranate seeds (leftover from salad, see Notes) or mint leaves, for visual only.","images":[],"step":18}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Persian"],"categories":["lamb","lamb-recipes","lamb-shanks","main-dishes","mains","quick-and-easy","slow-cooked-fall-apart","slow-cooker-recipes","stews","sunday-supper"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c94806c67199', 'en', 'US', 'Shepherd''s Pie', 'Recipe video above. Shepherd’s Pie is one of those foods that brings a smile to everyone’s face – especially when you get seconds! While it''s traditionally made with lamb, this is equally delicious made with beef (and makes it a Cottage Pie!) Terrific make ahead! GF option in Note 4.', 'https://www.recipetineats.com/tachyon/2018/06/Shepherds-Pie_1.jpg', 10, 70, 80, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_rosemary", "quantity": {"value": 0.075, "unit": "bunch"}}, {"id": "ing_lamb", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_beef", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_potato", "quantity": {"value": 1.2, "unit": "bag of 2kg"}}, {"id": "ing_milk", "quantity": {"value": 0.167, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 2.0, "unit": "pack of 200g"}}, {"id": "ing_thyme", "quantity": {"value": 0.075, "unit": "bunch"}}]', '[{"ingredients":["1 1/2 tbsp olive oil","2 garlic cloves (, minced)","1 onion (, finely chopped)","1 carrot (, finely chopped)","1 rib celery (, finely chopped)","3/4 tsp each dried thyme and rosemary (or 2 sprigs fresh thyme + 1 sprig rosemary)","750g (1.5 lb) ground lamb (mince) OR beef","1/4 cup flour (, plain/all purpose)","1/4 cup tomato paste","2 cups beef stock / broth","1/2 cup red wine (or water)","1 beef bouillon cube (, crumbled (OXO brand crumbles easily))","1 tbsp Worcestershire sauce","2 bay leaves (, dried or fresh)","3/4 tsp cooking salt / kosher salt","1/2 tsp black pepper","1 cup frozen peas"]},{"ingredients":["1.2kg (2.2 lb) potatoes, peeled and cut into 2.5cm / 1\" cubes","2/3 cup milk (whole or low fat)","2 tbsp (30g) unsalted butter"],"purpose":"Mashed Potato"},{"ingredients":["2 – 3 tbsp grated parmesan (, optional)","2 tbsp (30g) unsalted butter (, melted)","Fresh thyme leaves, optional garnish"],"purpose":"Cheesy crust"}]', '[{"title":"Sauté","description":"Heat oil in a large skillet over medium high heat. Add onion and garlic, cook for 1 minute. Then add carrots, celery, thyme and rosemary. Cook for 3 minutes or until softened and sweet.","duration":1,"images":[],"step":1},{"title":"Cook lamb","description":"Turn heat up to high. Add lamb and cook, breaking it up as you go, until browned.","images":[],"step":2},{"title":"Make sauce","description":"Add flour and mix in. Add tomato paste, broth, red wine, bouillon cube, Worcestershire sauce and bay leaves. Stir well.","images":[],"step":3},{"title":"Simmer and thicken","description":"Bring to simmer, then turn down heat so it is simmering rapidly - I have it on medium. Cook for 30 minutes, stirring occasionally, until it reduces down to a thick gravy consistency (Note 1) (see video).","duration":30,"images":[],"step":4},{"title":"Cool","description":"Add salt and pepper, taste, then add more if you like. Transfer Filling to 1.5 litre / 1.5 quart pie baking dish. Stir through peas. Cover, then refrigerate to cool for 1 - 2 hours or overnight (optional, Note 2)","images":[],"step":5},{"description":"Preheat oven to 180°C/350°F (both fan and standard).","images":[],"step":6},{"title":"Boil potatoes","description":"Place the potatoes in a large pot. Add water so it’s 10cm / 4” above potatoes. Bring to a boil then cook for 15 minutes or until soft. Drain then return potatoes into the pot on the turned off stove. Allow to steam dry for 30 seconds or so (Note 3).","duration":15,"images":[],"step":7},{"title":"Mash","description":"Add butter and mash until melted, then add milk, salt and pepper. Mash until it''s soft and smooth (ie spreadable, but not sloppy), adjusting with a touch more milk if required.","images":[],"step":8},{"description":"Spread mash onto pie, use a fork to draw squiggles over the surface. Sprinkle with parmesan, drizzle with butter.","images":[],"step":9},{"title":"Bake for 30","description":"40 minutes or until deep golden on top and bubbling on the edges. Stick a knife into the middle to ensure it is piping hot.","duration":35,"images":[],"step":10},{"description":"Stand for 5 minutes before serving, garnished with fresh thyme leaves if desired.","duration":5,"images":[],"step":11}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Australian","British","Western"],"categories":["lamb-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_270e2df1a054', 'en', 'US', 'Lamb Shanks in Red Wine Sauce', 'Recipe video above. A classic way to prepare shanks, these are slow cooked in a deeply flavoured red wine sauce until they are meltingly tender. You can''t taste the red wine at the end, it completely transforms into a rich sauce. Make this in the oven, on your stove or even in a slow cooker - instructions provided for all!Note: This is my original lamb shanks recipe. There is also a more involved Restaurant-style red wine lamb shanks version in my cookbook which is more "fine-dining" style and involves an overnight marinade. See Note 7 for more information!', 'https://www.recipetineats.com/tachyon/2022/07/Lamb-Shanks-Red-Wine-Sauce_2_900px.jpg', 20, 210, 230, 4, '[{"id": "ing_amb_shanks", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_carrot", "quantity": {"value": 150.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 3.0, "unit": "head"}}, {"id": "ing_wine", "quantity": {"value": 0.833, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["4 lamb shanks (, around 13 oz / 400g each (Note 1))","1 tsp EACH cooking/kosher salt and pepper","2 - 3 tbsp olive oil (, separated)","1 onion (, finely diced (brown, yellow or white))","3 garlic cloves (, minced)","1 cup carrot (, peeled, finely diced (Note 2))","1 cup celery (, finely diced (Note 2))","2 1/2 cups red wine (full bodied (good value wine, not expensive! Note 3)","800 g / 28oz can crushed tomatoes","2 tbsp tomato paste","2 cups chicken stock (, low sodium (or water))","5 sprigs of thyme ((preferably tied together), or 2 tsp dried thyme)","2 dried bay leaves (or 4 fresh)"]},{"ingredients":["Mashed potato (, polenta or pureed cauliflower)","Fresh thyme leaves (, optional garnish)"],"purpose":"To Serve:"}]', '[{"title":"Preheat the oven to 180°C/350°F (all oven types","description":"fan and standard).","images":[],"step":1},{"title":"Season shanks","description":"Pat the lamb shanks dry and sprinkle with salt and pepper.","images":[],"step":2},{"title":"Brown","description":"Heat 2 tablespoons of olive oil in a large heavy based pot over high heat. Sear the lamb shanks in 2 batches until brown all over, about 5 minutes. Remove lamb onto a plate and drain excess fat (if any) from the pot.","images":[],"step":3},{"title":"Sauté aromatics","description":"Turn the heat down to medium low. Heat remaining 1 tablespoon of olive oil in the same pot. Add the onion and garlic, cook for 2 minutes. Add carrot and celery. Cook for 5 minutes until onion is translucent and sweet.","duration":2,"images":[],"step":4},{"title":"Braising liquid","description":"Add the red wine, chicken stock, crushed tomato, tomato paste, thyme and bay leaves. Stir to combine.","images":[],"step":5},{"title":"Add shanks","description":"Place the lamb shanks into the pot, squeezing them in to fit so they are mostly submerged. (Note 1)","images":[],"step":6},{"title":"Oven 2 hours covered","description":"Turn stove up, bring liquid to a simmer. Cover, then transfer to the oven for 2 hours (see notes for other cook methods).","images":[],"step":7},{"title":"Uncovered 30 minutes","description":"Remove lid, then return to the oven for another 30 minutes (so 2 1/2 hours in total). Check to ensure lamb meat is ultra tender - if not, cover and keep cooking. Ideal is tender meat but still just holding onto bone.","images":[],"step":8},{"description":"Remove lamb onto plate and keep warm. Pick out and discard bay leaves and thyme.","images":[],"step":9},{"title":"Sauce","description":"Strain the sauce into a bowl, pressing to extract all sauce out of the veggies (Note 5 for repurposing the veggies). Pour strained sauce back into pot. If needed, bring to a simmer over medium heat and reduce slightly to a syrupy consistency (see video) - I rarely need to. Taste then add salt and pepper to taste (Note 5 on sauce taste).","images":[],"step":10},{"description":"Serve the lamb shanks on mashed potato or cauliflower puree with plenty of sauce! Garnish with thyme leaves if desired.","images":[],"step":11}]', '[]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["lamb-recipes","lamb-shanks","main-dishes","most-popular","slow-cooked-fall-apart","slow-cooker-recipes","stews","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_fee8e66fd88d', 'en', 'US', 'Pea and Ham Soup (slow cooker or stove)', 'Recipe video above. This is a fabulous "throw it all in the slow cooker" soup. There''s no need to cook the onion separately - it "sautés" itself in the fat from the ham that rises to the surface. Thick, hearty soup broth infused with incredible flavour from the ham! Use leftover ham bone, or purchase a ham hock.', 'https://www.recipetineats.com/tachyon/2020/02/Pea-and-Ham-Soup_4.jpg', 10, 600, 610, 6, '[{"id": "ing_split_peas", "quantity": {"value": 500.0, "unit": "pack"}}, {"id": "ing_bacon", "quantity": {"value": 1.2, "unit": "pack of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_water", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["500g / 1lb dried split peas (Note 1)","1.2-1.5kg / 2.4-3lb ham hock (aka ham bone), bacon hock or MEATY leftover ham bone (Note 2)","1/4 tsp salt (start with less, adjust later)","3/4 tsp black pepper","2 garlic cloves (, minced)","2 bay leaves (, dried or fresh)","1 onion (, finely chopped)","1 carrot (, peeled and finely chopped)","2 celery sticks (, finely chopped)","8 cups (2 litres/qts) water"]},{"ingredients":["Parsley (, finely chopped)","Crusty bread for dunking!"],"purpose":"Garnishes / serving:"}]', '[{"description":"Place peas in slow cooker, push ham in. Scatter all ingredients around the ham bone, then pour over water.","images":[],"step":1},{"description":"Slow cook 8 to 10 hours on LOW or 6 hours on HIGH. (Or 2.5 hours on low on stove, 1 h - 1 hr 20 min pressure cooker/Instant Pot on HIGH)","images":[],"step":2},{"description":"Remove ham bone, shred ham meat. Discard bone and fatty skin.","images":[],"step":3},{"description":"Remove bay leaves. Use a stick blender to blitz 2 or 3 times - thickens soup but doesn''t make it completely smooth (my preference, you can blend completely if you want).","images":[],"step":4},{"description":"Return ham into slow cooker, stir. Taste and add more salt if needed (soup gets lots of salt from ham).","images":[],"step":5},{"description":"Serve garnished with parsley. Serve with crusty bread for dunking - make a quick Irish Soda Bread, Garlic Bread or upgrade to Cheesy Garlic Bread!","images":[],"step":6}]', '["gluten"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["leftover-ham-recipes","slow-cooker-recipes","soup-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0a15d7af93bb', 'en', 'US', 'Bangers & Mash (Sausage with Onion Gravy)', 'Recipe video above. Everybody loves a good sausage recipe, and this is the great British classic! Affectionately known as "Bangers and Mash" to Aussies and Brits, this is so easy to make, you will never ever use a store bought gravy powder!', 'https://www.recipetineats.com/tachyon/2016/10/Bangers-and-Mash-with-Onion-Gravy_42.jpg', 5, 20, 25, 4, '[{"id": "ing_oil", "quantity": {"value": 7.5, "unit": "bottle"}}, {"id": "ing_sausages", "quantity": {"value": 8.0, "unit": "pack of 500g"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_peas", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["1/2 tbsp oil","8 sausages of choice (Note 1)","1 large onion (, halved and finely sliced (yellow, white or brown) (Note 2))","2 garlic cloves (, minced)","3 tbsp flour (plain)","2 cups beef stock/broth","1/4 tsp salt","1/2 tsp black pepper"]},{"ingredients":["Mashed potato","Peas"],"purpose":"To Serve"}]', '[{"title":"Cook sausages","description":"Heat oil in a large skillet / fry pan over medium high heat. Add sausages and cook, turning, until browned as much as possible all over and cooked through. Cook time will differ depending on sausage size - mine take around 8 minutes.","images":[],"step":1},{"description":"Remove sausages onto a plate. Turn heat down to medium.","images":[],"step":2},{"title":"2 tbsp oil remaining","description":"You need around 2 tbsp oil left in the skillet. If you have much less, add a bit of butter or oil.","images":[],"step":3},{"title":"Saute onion and garlic","description":"Add onion and garlic, cook until golden brown - around 4 minutes.","images":[],"step":4},{"title":"Cook off flour 2 minutes","description":"Add flour and mix through. Then cook, stirring constantly for 2 minutes.","duration":2,"images":[],"step":5},{"title":"Gradually add beef stock","description":"Add about 3/4 cup of beef broth and mix into the onion so it becomes a sludge. Then add remaining beef broth and mix until combined. If it''s lumpy, use a whisk to help make it smooth.","images":[],"step":6},{"title":"Thicken gravy","description":"Simmer, stirring, for 2 to 3 minutes until the gravy thickens but is slightly thinner than you want - it will thicken more as you serve it.","duration":2.5,"images":[],"step":7},{"title":"Season","description":"Add salt and pepper. Stir, taste, then add more salt if you want.","images":[],"step":8},{"description":"Serve sausages with plenty of gravy, with mashed potato and peas on the side. (Low carb option - Creamy Cauliflower Mash)","images":[],"step":9}]', '["gluten"]', '["high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Australian","British"],"categories":["dinner-tonight","main-dishes","most-popular","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_dea186d5023f', 'en', 'US', 'Pasta with Creamy Zucchini Sauce', 'Recipe video above. This is a wonderful way to use zucchinis to make a luscious pasta dinner! It''s summery yet at the same time comforting, quick, easy and while perhaps not low fat, this makes a good dent into our daily recommended vegetable intake!', 'https://www.recipetineats.com/tachyon/2020/07/Creamy-Zucchini-Pasta-Sauce_8.jpg', 10, 15, 25, 4, '[{"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_zucchini", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 0.375, "unit": "pack of 200g"}}, {"id": "ing_corn", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.6, "unit": "pack of 500g"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["50g / 3 tbsp unsalted butter","2 garlic cloves (, minced)","1/2 onion (, finely sliced (brown, white, yellow))","600g / 1.2 lb zucchini ((courgette), grated using standard box grater)","1/2 tsp EACH salt and pepper","1 cup thickened/heavy cream","3/4 cup chicken or vegetable stock/broth (, low sodium)","3/4 cup parmesan (, finely grated using microplane (Note 1 for store bought))","1 cup corn (canned, drained, about 2/3 of a can, OR fresh)","300g/ 10oz spaghetti, fettucini or other long strand pasta ( (I used bucatini))"]},{"ingredients":["Parmesan","Extra finishing options: Handful of fresh basil (stir in at end), sprinkle of bacon or pangrattato"],"purpose":"Finishing & serving"}]', '[{"description":"Cook Pasta:","images":[],"step":1},{"description":"Bring a large pot of water to the boil with 1 tablespoon of salt.","images":[],"step":2},{"description":"Cook pasta per packet directions MINUS 2 minutes (yes, 2 whole minutes!) - pasta should be a bit too firm in the middle.","images":[],"step":3},{"description":"Scoop out a big mug of pasta cook water, set aside (for sauce loosening, just in case), then drain.","images":[],"step":4},{"description":"Creamy zucchini sauce:","images":[],"step":5},{"description":"Melt butter in a large skillet or pot over medium high heat.","images":[],"step":6},{"title":"Garlic and onion","description":"Add garlic and onion, cook for 1 1/2 minutes until onion is slightly golden.","images":[],"step":7},{"title":"Cook Zucchini","description":"Add zucchini, cook for 1 minute. Then add salt and pepper, then stir for 2 minutes until it reduces in volume by about 1/2.","duration":1,"images":[],"step":8},{"title":"Add liquids","description":"Stir in cream, chicken stock, parmesan and corn. Bring to simmer, then reduce heat to medium and simmer for 3 minutes. It will still seem watery because water comes out of the zucchini - don''t worry, it cooks down in the next step.","duration":3,"images":[],"step":9},{"description":"Toss! Add pasta, then use two wooden spoons to toss well for 2 minutes, or until sauce reduces and is coating the pasta instead of pooling in the skillet. If it gets too thick, add a splash of reserved pasta cooking water. Pasta will finish cooking in this step.","duration":2,"images":[],"step":10},{"title":"Serve","description":"Remove from stove, serve immediately, garnished with extra parmesan.","images":[],"step":11}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["main-dishes","mains","pasta-recipes","quick-and-easy","vegetarian-recipes","zucchini-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_744dcc5f1955', 'en', 'US', 'Crispy Baked Shrimp in Lemon Butter Sauce (Prawns)', 'Recipe video above. People call this Magic Baked Shrimp - named as such because it''s so simple to make, yet it tastes like a million bucks! Shrimp (prawns) baked in a white wine-butter reduction with lemon and garlic, with a crunchy parmesan breadcrumb topping! Don''t skip crust bread for dunking in the incredible sauce! It''s basically a crunchy version of Shrimp Scampi!', 'https://www.recipetineats.com/tachyon/2019/08/Baked-Shrimp-Prawns_6.jpg', 10, 15, 25, 4, '[{"id": "ing_shrimp", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.25, "unit": "bottle of 750ml"}}, {"id": "ing_butter", "quantity": {"value": 75.0, "unit": "block of 250g"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 0.141, "unit": "loaf"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}]', '[{"ingredients":["500g/ 1 lb jumbo prawns/shrimp (, peeled and deveined (Note 1))","3/4 cup dry white wine (sub chicken broth)","75g/ 5 tbsp unsalted butter (, melted)","2 tbsp lemon juice","3 garlic cloves (, minced)","1/2 tsp salt","1/4 tsp pepper"]},{"ingredients":["3/4 cup panko breadcrumbs (Note 2)","1/4 cup parmesan (, finely shredded)","1/4 tsp salt","1.5 tbsp olive oil"],"purpose":"Crunchy Topping:"},{"ingredients":["Finely chopped parsley","Lemon"],"purpose":"Garnish:"}]', '[{"description":"Preheat oven to 220°C/430°F (all oven types).","images":[],"step":1},{"description":"Pour wine and half the butter into 9 x 13\" / 22 x 33cm baking pan (see Note 3 if using glass). Place in oven for 10 minutes to reduce.","duration":10,"images":[],"step":2},{"description":"Toss prawns with remaining butter, garlic, lemon juice, salt and pepper. Butter may harden - that''s ok.","images":[],"step":3},{"description":"Mix Crunchy Topping ingredients.","images":[],"step":4},{"title":"Remove pan from oven. Add prawns","description":"spread out in single layer, but snug.","images":[],"step":5},{"description":"Top with Crunchy Topping. Bake 12 minutes.","images":[],"step":6},{"title":"Flick to broiler/grill on high, broil for 1","description":"2 minutes (max) to brown top a bit more.","duration":1.5,"images":[],"step":7},{"description":"Sprinkle with parsley. Serve immediately with lemon wedges and crusty bread to mop up the incredible sauce!","images":[],"step":8}]', '["milk","shellfish"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","main-dishes","prawns-shrimp","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0e061b94dd4f', 'en', 'US', 'Garlic Herb Slow Cooker Turkey Breast', 'Recipe video above. Slather your turkey breast with garlic herb butter so it bastes with flavour and keeps the breast moist as it cooks in the slow cooker. Slow cooker is the easiest, safest way too cook turkey breast without brining or marinating! See here for the roasted version of this recipe. Also see the classic spice rubbed Juicy Slow Cooker Turkey Breast.', 'https://www.recipetineats.com/tachyon/2018/11/Slow-Cooker-Garlic-Herb-Turkey-Breast.jpg', 15, 360, 375, 8, '[{"id": "ing_5_6_lb_single_turkey_breast", "quantity": {"value": 2.5, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_rosemary", "quantity": {"value": 0.12, "unit": "bunch"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_butter", "quantity": {"value": 150.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_rosemary", "quantity": {"value": 0.12, "unit": "bunch"}}, {"id": "ing_chicken", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.01, "unit": "bottle of 250ml"}}]', '[{"ingredients":["2.5 - 3 kg / 5-6 lb single turkey breast (, skin on, bone in (Note 1), NOT BRINED)","1 1/2 tsp salt","Black pepper","1 brown onion (, halved)","1 head of garlic (, halved horizontally)","3 sprigs rosemary, 8 sprigs thyme (optional)","Oil (, for drizzling (for skin))"]},{"ingredients":["150 g / 10 tbsp unsalted butter (, softened)","1 1/2 tsp salt","1/2 tsp black pepper","4 large garlic cloves (, minced)","1 tbsp EACH finely chopped fresh sage, rosemary leaves, thyme leaves and parsley (, fresh)"],"purpose":"Garlic Herb Butter (Note 2):"},{"ingredients":["Chicken broth/stock, for topping up (if required)","1/3 cup / 50g flour","1/2 tsp + dark soy sauce (or gravy colouring) (Note 3)"],"purpose":"Garlic Butter Gravy:"}]', '[{"title":"Garlic Herb Butter","description":"Mix ingredients together.","images":[],"step":1},{"title":"Loosen skin (video helpful)","description":"Pat breast dry. Use small knife to cut slit on one side to separate skin from flesh. Slide upside tablespoon between flesh and skin, all over turkey.","images":[],"step":2},{"title":"Slather","description":"Slather about 2/3 of the butter under the skin, then the remaining all over the surface including underside.","images":[],"step":3},{"title":"Season skin","description":"Sprinkle surface with 1/2 tsp salt + pepper. (Can leave overnight - 2 days at this stage)","images":[],"step":4},{"title":"Put in Slow Cooker","description":"Place garlic and onion in slow cooker (mine is 5L / 5 qt). Place turkey on top, skin side up. Top with thyme and rosemary sprigs.","images":[],"step":5},{"title":"Slow Cook","description":"Cook 6 hours on low, first checking at 4 hours to be safe, until internal temperature reads 75C/165F when inserted into the middle.","images":[],"step":6},{"title":"Rest","description":"Transfer turkey to baking tray (reserve juices). Cover loosely with foil, rest for 20 minutes.","duration":20,"images":[],"step":7},{"title":"Crisp","description":"Remove herb sprigs, drizzle turkey with oil (not butter, it burns / not as crispy). Place under a broiler/grill on high (~30cm/12\" from heat source) for 5 to 10 minutes until skin is crispy and bronzed - keep an eye on it, it''s quick.","duration":7.5,"images":[],"step":8},{"description":"Serve turkey with gravy on the side (below), or Cranberry Sauce.","images":[],"step":9},{"description":"Strain slow cooker juices into a bowl. Press juices out of onion and garlic. If you''ve got less than 2.5-3 cups (675-750ml) of liquid, top up with store bought broth/stock.","images":[],"step":10},{"description":"When liquid settles, spoon off about 1/4 cup fat/butter from surface.","images":[],"step":11},{"description":"Place in saucepan set over medium heat. When it bubbles, add flour and mix for 1 minute.","duration":1,"images":[],"step":12},{"description":"Add all slow cooker juices into saucepan. Stir until lump free (use whisk if necessary). Simmer for 3 to 5 minutes until it thickens.","duration":4,"images":[],"step":13},{"description":"Add dark soy (if using), pepper and salt to taste. Pour into jug and serve with turkey.","images":[],"step":14}]', '["gluten","milk","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["main-dishes","slow-cooker-recipes","turkey-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bb86a7928197', 'en', 'US', 'Oven Baked Pork Chops with Potatoes', 'Recipe video above. This is a sauce made for baked pork chops. It makes them come out golden and sticky, rather than pale and bland. It''s a country-style sauce that''s savoury and a bit sweet! Potatoes are optional - or sub with other roastable veg.', 'https://www.recipetineats.com/tachyon/2016/09/Baked-Pork-Chops_2.jpg', 10, 30, 40, 4, '[{"id": "ing_worcestershire_sauce", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_ketchup", "quantity": {"value": 0.06, "unit": "bottle of 500g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.02, "unit": "bottle of 500ml"}}, {"id": "ing_pork", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_potato", "quantity": {"value": 800.0, "unit": "bag of 2kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1 tsp Worcestershire Sauce","2 tbsp ketchup (Note 1)","1 tbsp soy sauce (Note 2)","2 tbsp brown sugar (or white)","1 tbsp olive oil (or vegetable or canola oil)","1 clove garlic, (minced)","2 tsp apple cider vinegar (Note 3)"],"purpose":"Rub"},{"ingredients":["4 pork chops / cutlets (, around 200-250g/7-8oz each including bone (Note 4))","800g/ 1.6 lb baby potatoes (, larger ones cut in half (Note 5))","1 tbsp olive oil","Salt & pepper"],"purpose":"Chops"}]', '[{"description":"Preheat oven to 220C / 430F (standard oven) or 200C / 390F (fan forced / convection).","images":[],"step":1},{"description":"Toss potatoes in oil, sprinkle with salt and pepper. Scatter on baking tray.","images":[],"step":2},{"description":"Place in oven for 15 minutes (giving them a head start).","duration":15,"images":[],"step":3},{"description":"Meanwhile, mix the Rub ingredients together in a small bowl.","images":[],"step":4},{"description":"Slather the pork on both sides with the Rub, reserving some Rub for basting. (See notes for marinating)","images":[],"step":5},{"description":"Take the tray out of the oven. Toss potatoes then push them to the edge.","images":[],"step":6},{"description":"Place pork on tray. Bake for 15 minutes.","duration":15,"images":[],"step":7},{"description":"Remove tray from oven, flick to broiler/grill on high (shelf about 20cm/8\" from heat source).","images":[],"step":8},{"description":"Flip pork, spoon over reserved rub and dab on sides. (Note 4). Broil 7 - 10 minutes until pretty well caramelised.","images":[],"step":9},{"description":"Remove from oven. Use a brush to get the golden juices off the tray and dab it onto the pork - this is key for flavour and colour! Pop it back under the broiler for a couple of minutes to finish off.","images":[],"step":10},{"description":"Serve, scraping the juices on the tray onto the pork, then garnish with parsley if desired.","images":[],"step":11}]', '["gluten","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","main-dishes","most-popular","one-pot-recipes","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d2e3e6bfbe8b', 'en', 'US', 'Creamy Carrot Soup', 'Recipe video above. Carrot soup is incredibly delicious - sweet, savoury and creamy. And I LOVE the colour! The bacon makes a terrific flavour base here, but you can skip it (Note 1).', 'https://www.recipetineats.com/tachyon/2018/06/Carrot-Soup_2.jpg', 10, 30, 40, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_bacon", "quantity": {"value": 0.8, "unit": "pack of 200g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_carrot", "quantity": {"value": 5000.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_milk", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["1 tbsp olive oil or butter","4 slices streaky bacon (~120g/4oz)","1 onion (, chopped)","2 garlic cloves (, minced)","5 large carrots (, cut into 1.5 cm / 3/5\" chunks)","1 litre / 1 quart vegetable or chicken broth (4 cups)","1/2 cup / 125 ml cream","3/4 cup / 185ml milk (any fat %)","Salt and pepper"]},{"ingredients":["Fresh thyme or chopped parsley","Cream (, for swirling)","Crusty bread"],"purpose":"Serving:"}]', '[{"description":"Heat oil in a large pot over medium high heat. Add bacon and cook until golden. Remove from pot, cool then chop.","images":[],"step":1},{"description":"Add onion and garlic into the bacon drippings. Cook for 2 minutes until onion is translucent but not browned.","duration":2,"images":[],"step":2},{"description":"Add carrots and stir well to coat the carrot in the oil.","images":[],"step":3},{"description":"Add broth, then stir. Cover with lid, adjust heat so it is simmering energetically (about medium). Cook for 20 - 25 minutes until carrot is very soft.","duration":22.5,"images":[],"step":4},{"description":"Remove lid, turn heat off. Use a stick blender to puree the carrot (or cool slightly and do in blender).","images":[],"step":5},{"description":"Add cream, milk, salt and pepper to taste. Stir. Adjust thickness with milk (or water), if desired.","images":[],"step":6},{"description":"Ladle soup into bowls. Garnish with swirls of cream, bacon and parsley or thyme if desired. Serve with crusty bread.","images":[],"step":7}]', '["gluten","milk"]', '["low_calorie"]', '{"mealType":["main_course"],"cuisine":[],"categories":["dinner-tonight","main-dishes","quick-and-easy","soup-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_be75afa9939a', 'en', 'US', 'French Onion Soup', 'Recipe video above. One of the most epic soups of the world does take time to make but it''s so worth it! The deeply caramelised onions make an incredible flavour base for the broth. And that cheesy toast is a must! See recipe notes for SLOW COOKER Caramelised Onions.', 'https://www.recipetineats.com/tachyon/2018/11/French-Onion-Soup_1.jpg', 20, 90, 110, 4, '[{"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 1250.0, "unit": "pack of 1kg"}}, {"id": "ing_wine", "quantity": {"value": 0.25, "unit": "bottle of 750ml"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 0.12, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 6.0, "unit": "loaf"}}, {"id": "ing_gruyere_cheese", "quantity": {"value": 100.0, "unit": "block of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["100 g / 3.5oz unsalted butter","1.25 kg / 2.5 lb brown / yellow onions (, peeled, halved, thinly sliced top to bottom (Note 1))","3/4 cup (185ml) dry white wine (, optional (Note 2))","2 tbsp flour (, plain / all purpose)","1.5 litres / 6 cups / 1.5 quarts good quality beef broth./stock OR chicken (, low sodium/salt reduced (Note 3))","2 dried bay leaves (or 3 fresh) (optional)","3 sprigs fresh thyme (optional)","Salt and pepper"]},{"ingredients":["6 - 8 slices French baguette (or other softish bread (Note 4))","100 g / 3.5 oz gruyere (or mozzarella cheese, or other melting cheese of choice)","Fresh parsley or thyme leaves (, for garnish (optional))"],"purpose":"Cheesy Toast"}]', '[{"description":"Caramelise Onions (See Notes for SLOW COOKER option)","images":[],"step":1},{"description":"Melt butter in a heavy based casserole pot over medium heat. When it starts to foam, add onions and stir to coat in butter.","images":[],"step":2},{"title":"30 min on medium low","description":"Turn heat down to medium low. Cook for 30 minutes stirring every few minutes, until the onions have softened and are semi transparent.","duration":30,"images":[],"step":3},{"title":"Salt, 20 min on medium high","description":"Turn heat up to medium or medium high. Add salt, and cook for a further 20 - 30 minutes, stirring more regularly, until onions are deep golden and sweet.","images":[],"step":4},{"title":"Deglaze","description":"Add wine, then simmer rapidly for 2 minutes until mostly evaporated, stirring to scrape the bottom of the pot.","duration":2,"images":[],"step":5},{"title":"Flour","description":"Sprinkle flour over the onion and cook for 1 minute.","duration":1,"images":[],"step":6},{"title":"Add broth & herbs","description":"Add broth, thyme and bay leaves.","images":[],"step":7},{"title":"Simmer","description":"Cover, lower heat so it''s simmering gently then simmer for 30 minutes.","duration":30,"images":[],"step":8},{"title":"Serve","description":"Season to taste with salt and pepper. Ladle into bowls. Top with 1 or 2 slices of cheesy toast.","images":[],"step":9},{"description":"Preheat grill / broiler to high.Toast each side of bread until light golden.","images":[],"step":10},{"description":"Top bread with cheese, then grill until melted and some brown spots appear.","images":[],"step":11}]', '["gluten","milk"]', '["low_calorie"]', '{"mealType":["main_course"],"cuisine":["French"],"categories":["main-dishes","most-popular","soup-recipes","sunday-supper","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_37c4922697ee', 'en', 'US', 'Turkey Gravy - for ROASTED Turkey', 'Recipe video above. This is a recipe for how to make gravy for turkey that''s been roasted so you have pan drippings to use as the base for gravy (ie the juices and oil in the base of the pan when the turkey is finished cooking). See separate recipe card below for SLOW COOKER turkey (different method).If you don''t have either, use my from-scratch gravy recipe instead.This recipe assumes a WHOLE Roasted Turkey to 6 kg / 8 - 12lb. If yours is larger, scale recipe up (see Note 1 for quantity) If you roasted breast, you won''t have much pan drippings (because it''s pretty lean) so use the Slow Cooker turkey gravy recipe below. This gravy is outrageously delicious so make plenty! Freezes for 3 months.', 'https://www.recipetineats.com/tachyon/2018/11/Juicy-Roast-Turkey_Dry-Brined_9.jpg', 5, 10, 15, 4, '[{"id": "ing_drippings_in_turkey_roasting_pan", "quantity": {"value": 0.09, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.09, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[]', '[{"description":"Place the roasting pan on the stove over medium heat. Single burner is fine, but ideal if it fits across two. Leave garlic, onion etc and other flavourings things in the pan (Note 1)","images":[],"step":1},{"description":"When it starts sizzling/bubbling, add flour. Cook for 1 minute, stirring constantly.","duration":1,"images":[],"step":2},{"description":"Gradually pour the liquid in, mixing constantly. Once it''s all in, it should be lump free. If not, use a whisk - whisk around the onion etc.","images":[],"step":3},{"title":"Simmer until it thickens to taste","description":"gravy will thicken more as it cools. Adjust salt and pepper to taste right at the end.","images":[],"step":4},{"description":"Strain into a bowl, pressing the juices out of the onion, garlic etc. then discard them.","images":[],"step":5},{"title":"Pour gravy into jug and serve with turkey. Tip","description":"To keep gravy warm, store in a thermos!","images":[],"step":6}]', '["gluten"]', '[]', '{"mealType":["main_course"],"cuisine":[],"categories":["main-dishes","roasts","sauces","turkey-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7d661b946f63', 'en', 'US', 'French Onion Smothered Pork Chops', 'Recipe video above. French Onion Soup meets juicy pan seared pork! A gravy made with caramelised onion that tastes like your favourite French Onion soup. For the full French Onion experience, don''t skip the cheese! Make this with any type of pork chops you want - or chicken!', 'https://www.recipetineats.com/tachyon/2018/11/French-Onion-Smothered-Pork-Chops_4.jpg', 10, 25, 35, 4, '[{"id": "ing_pork", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 2000.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.833, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_oil", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_beef", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_rosemary", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["4 - 5 pork chops (, boneless (~ 150-200g/5-7oz each) (Note 1))","1/2 tsp garlic powder","Salt and pepper","2 large onions (, sliced into rings (brown, yellow or white))","2 garlic cloves (, minced)","1.5 tbsp / 25g butter (or olive oil)","1 tsp oil (, if needed)","Salt and pepper","1 cup/250ml beef broth/stock (, low sodium)","2 tbsp flour","4 slices cheese (Note 2)","Finely chopped fresh rosemary leaves"]}]', '[{"title":"Caramelise Onions","description":"Melt butter on medium (or medium low for strong stoves). Add onion and garlic, cook 15 minutes until golden brown and caramelised, stirring regularly (see video). Remove from skillet.","images":[],"step":1},{"title":"Prepare Chops","description":"Sprinkle chops with garlic, salt and pepper.","images":[],"step":2},{"title":"Sear","description":"Add oil into skillet if needed. Turn heat up to high. Sear chops 1 minute on each side until nicely browned but not cooked inside. Remove onto plate.","images":[],"step":3},{"title":"Gravy","description":"Turn heat down to medium. Return onion into skillet, scraping in juices. Add flour, mix.","images":[],"step":4},{"description":"Add beef broth and mix until incorporated. Season sauce to taste with salt and pepper.","images":[],"step":5},{"title":"Simmer Chops in Sauce","description":"When it comes to a simmer, give it a big stir then add pork chops.","images":[],"step":6},{"description":"Top chops with cheese, cover with lid to melt and finish cooking the chops through - only 3 minutes for thin chops like I''m using. Internal temp of 160F/70C for no pink (or 155F/68C for blush of pink).","images":[],"step":7},{"title":"Garnish","description":"Remove lid, sprinkle with rosemary. Spoon over French Onion Gravy, then sprinkle with more rosemary.","images":[],"step":8},{"description":"Serve immediately, over mashed potato or similar.","images":[],"step":9}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","main-dishes","mains","pork","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_eed837dd2b13', 'en', 'US', 'Brown Sugar Garlic Butter Pork Roast', 'Recipe video above. Ultra tender pork with an insane caramelised crust and a buttery sweet-savoury sauce. The pairing of the sweet with the savoury is incredible in this pork roast!', 'https://www.recipetineats.com/tachyon/2018/07/Brown-Sugar-Caramelised-Pork-Roast_1.jpg', 10, 135, 145, 6, '[{"id": "ing_pork_shoulder", "quantity": {"value": 1.75, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_vinegar", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}]', '[{"ingredients":["1.75 - 2kg / 3.5 - 4lb pork shoulder / butt (, cut into 8 equal pieces (Note 1))","1 tsp each salt and pepper"]},{"ingredients":["100 g / 7 tbsp unsalted butter","1/2 cup / 80g brown sugar (, loosely packed)","1/4 cup / 65 ml cider vinegar (white wine or red wine vinegar also fine)","4 garlic cloves (, minced)","1/4 tsp each salt and pepper"],"purpose":"Sauce:"}]', '[{"description":"Preheat oven to 160C/320F (standard) or 140C/290F (fan).","images":[],"step":1},{"description":"Place Sauce ingredients in a saucepan over medium heat. Once better has melted, stir to combine then leave for 1 - 2 minutes until sugar is melted. Remove from heat.","duration":1.5,"images":[],"step":2},{"description":"Sprinkle pork pieces all over with salt and pepper.","images":[],"step":3},{"description":"Line pan with foil then parchment / baking paper, place pork in pan.","images":[],"step":4},{"description":"Pour Sauce all over pork. Cover with foil. Bake for 1 hour 15 minutes.","images":[],"step":5},{"description":"Remove from oven, remove foil. Turn pork. Return to oven uncovered for 20 minutes.","duration":20,"images":[],"step":6},{"description":"Remove from oven. Turn pork, spoon pan juices over. Return to oven for 20 - 30 minutes or until pork is golden and sauce has reduced to a thin syrup (thickens more when it cools).","duration":25,"images":[],"step":7},{"description":"Stand for 5 minutes, then turn pork to coat in sauce. Serve pork with syrupy pan sauce. Pictured in post with this Everyday Cabbage Salad.","duration":5,"images":[],"step":8}]', '["milk"]', '["gluten_free"]', '{"mealType":["main_course"],"cuisine":[],"categories":["main-dishes","mains","pork","pork-recipes","quick-and-easy","roasts","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6e7aa882995c', 'en', 'US', 'Quesadilla (Beef, Vegetable or Chicken)', 'Recipe video above. Choose ONE Filling! The spice mix adds terrific flavour - great with vegetable, chicken, beef, pork and turkey. Freezer friendly!', 'https://www.recipetineats.com/tachyon/2018/06/Quesadillas_4.jpg', 10, 15, 25, 6, '[{"id": "ing_tortillas", "quantity": {"value": 6.0, "unit": "pack of 8"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_corn", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_one_filling_of_choice_below", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 5.0, "unit": "pack of 1kg"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 5.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_black_beans", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 0.375, "unit": "can of 400g"}}]', '[{"ingredients":["6 - 8 flour tortillas (20cm/8\")","2 cups (200g) shredded Monterey Jack cheese (or other of choice) (Note 1)","3/4 cup roughly chopped coriander/cilantro","1 cup corn kernels (frozen thawed or can drained)","ONE Filling of Choice, below (beef, chicken or vegetable)"],"purpose":"Quesadillas:"},{"ingredients":["1 tsp each onion powder, dried oregano, salt","2 tsp each cumin powder, paprika","1/4 tsp each black pepper, cayenne pepper (optional)"],"purpose":"Quesadilla Spice Mix:"},{"ingredients":["2 1/2 tbsp olive oil","2 garlic cloves (, minced)","1/2 onion (, finely chopped)","500g / 1 lb ground beef / mince","1 small red capsicum/bell peppers (, diced)","2 tbsp tomato paste","1/4 cup (65 ml) water"],"purpose":"Beef Filling:"},{"ingredients":["2 1/2 tbsp olive oil","500 g/1 lb chicken thighs (, skinless boneless (Note 2))","2 garlic cloves (, minced)","1 small onion (, quartered and sliced)","1 small red capsicum/bell pepper (, diced)"],"purpose":"Chicken Filling:"},{"ingredients":["2 tbsp vegetable oil","1 onion (, diced)","2 garlic cloves (, minced)","1 can of black beans, drained (400g/14oz)","1 capsicum/bell pepper (, diced (any colour))","1 cup corn (canned drained or frozen thawed)","1/4 cup tomato paste","1/4 cup (65 ml) water"],"purpose":"Vegetable Filling:"}]', '[{"description":"Place tortilla on work surface. Sprinkle one side with a bit of cheese, top with Filling of Choice. Sprinkle with corn*, coriander and top with cheese. Fold in half.","images":[],"step":1},{"description":"Preheat non stick skillet over medium low heat (no oil, if pan is not non-stick use 2 tsp oil).","images":[],"step":2},{"description":"Place quesadilla in skillet, press down lightly, cover with lid. Cook for 3 minutes until underside is super golden brown and crispy.","duration":3,"images":[],"step":3},{"description":"Carefully flip over the folded edge (see video). Press down lightly. Cook for 3 minutes until crispy (no lid).","duration":3,"images":[],"step":4},{"description":"Transfer to cutting board, cut in half. Serve immediately!","images":[],"step":5},{"title":"Dipping Sauce options","description":"Sour cream, salsa, Avocado Sauce (pictured)","images":[],"step":6},{"description":"Spice Mix:","images":[],"step":7},{"description":"Mix ingredients in a small bowl. Use for one of the Fillings Options below.","images":[],"step":8},{"description":"Heat oil in a skillet over high heat. Add onion and garlic, cook for 2 minutes.","duration":2,"images":[],"step":9},{"description":"Add beef and cook, breaking it up as you go. Once it changes from pink to brown, add capsicum. Cook for 1 minute.","duration":1,"images":[],"step":10},{"description":"Add tomato paste, water and Spice Mix. Cook for 2 minutes. Transfer to bowl, cool.","duration":2,"images":[],"step":11},{"description":"Chicken Filling:","images":[],"step":12},{"description":"Drizzle chicken with 1 tbsp oil, toss to coat. Sprinkle over Spice Mix, toss well to coat.","images":[],"step":13},{"description":"Heat 1 tbsp oil in a large skillet over high heat. Add onion and garlic, cook for 2 minutes. Add capsicum and cook for 1 minute. Transfer to bowl, cool.","duration":2,"images":[],"step":14},{"description":"Return pan to stove, reduce to medium heat. Add remaining 1/2 tbsp oil. Add chicken and cook for 3 minutes until deep golden. Turn and cook for 3 minutes until cooked through.","duration":3,"images":[],"step":15},{"description":"Transfer chicken to cutting board, rest for 2 minutes then dice and cool. Combine with capsicum mixture.","duration":2,"images":[],"step":16},{"description":"Vegetable Filling:","images":[],"step":17},{"description":"Heat oil in a skillet over high heat. Add onion and garlic, cook for 2 minutes. Add capsicum, cook for 1 minute.","duration":2,"images":[],"step":18},{"description":"Add beans, corn, tomato paste, water and Spice Mix. Cook for 2 minutes. Transfer to bowl, cool.","duration":2,"images":[],"step":19}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican","Tex-Mex"],"categories":["dinner-tonight","main-dishes","mexican-recipes","quesadillas","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a74262062ffa', 'en', 'US', 'Pasta with Tomato Cream Sauce', 'Recipe video above. Pasta in a pink tomato cream sauce! You''ll love how creamy this sauce is, how there''s plenty of it and yet you don''t need gallons of cream. Slurp-worthy as it is, or use it as a base for add ins of your choice - suggestions in the recipe notes.', 'https://www.recipetineats.com/tachyon/2018/03/Creamy-Tomato-Pasta_8.jpg', 5, 15, 20, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.6, "unit": "pack of 500g"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_milk", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 0.375, "unit": "pack of 200g"}}, {"id": "ing_basil", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["300g/10 oz spaghetti","2 tbsp / 30g unsalted butter","3 garlic cloves (, minced)","½ onion (, finely chopped)","1 cup / 250 ml tomato passata (/ tomato puree (Note 1))","3/4 cup / 185 ml heavy / thickened cream (Note 2 for subs)","1/2 cup / 125 ml milk (, low fat)","3/4 cup / 30g parmesan (, finely freshly grated (Note 3))","1 tsp dried basil, or other herb of choice","1 tsp chicken or vegetable stock powder (, or 1 bouillon cube, crumbled (Note 4))","Finely ground pepper + salt"]}]', '[{"description":"Cook pasta in a big pot of boiling water for time per packet MINUS 2 minutes. Just before draining, scoop out a mugful of pasta cooking water.","images":[],"step":1},{"description":"Melt butter in large skillet over medium heat. Add garlic and onion, cook until translucent - about 2 minutes.","images":[],"step":2},{"description":"Add remaining ingredients. Stir until parmesan is melted. Turn heat up slightly and simmer for 2 minutes. Adjust salt to taste.","duration":2,"images":[],"step":3},{"description":"Add pasta. Toss for 1 to 2 minutes or until sauce thickens and is clinging to pasta instead of swimming on the base of the skillet (video shows this well). Use reserved pasta cooking water if required to thin the sauce out if it gets too thick.","duration":1.5,"images":[],"step":4},{"description":"Serve immediately, garnished with more parmesan and parsley if desired.","images":[],"step":5}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","main-dishes","pasta-recipes","quick-and-easy","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_542b20e01cd2', 'en', 'US', 'Corn Chowder with Bacon', 'Recipe video above. Make your next Corn Chowder extra tasty by using the bacon drippings to make the soup base and after cutting the kernels off, throw the corn cobs into the broth to infuse it with extra corn flavour! The potato is cooked until very soft, so the edges are starting to breakdown and this helps thicken the soup.', 'https://www.recipetineats.com/tachyon/2017/10/Corn-Chowder-11.jpg', 15, 35, 50, 5, '[{"id": "ing_corn", "quantity": {"value": 4.0, "unit": "can of 400g"}}, {"id": "ing_corn", "quantity": {"value": 4.0, "unit": "can of 400g"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_bacon", "quantity": {"value": 1.25, "unit": "pack of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_potato", "quantity": {"value": 600.0, "unit": "bag of 2kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_green_onion", "quantity": {"value": 2.25, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["4 ears of corn","4 cups / 750g / 1.5 lb frozen or canned corn (, drained)"],"purpose":"Corn (choose one)"},{"ingredients":["1 tsp butter (or oil)","250g / 8 oz bacon (, chopped)","30g / 2 tbsp butter (use 3 tbsp if bacon is lean)","1 garlic clove (, minced)","1 small onion (, diced (or half large onion) (yellow, brown or white))","5 tbsp flour","2 cups chicken broth (, low sodium)","3 cups milk (I use low fat but full fat will work too)","600g / 1.2 lb potatoes (, cut into 1 cm / 2/5\" cubes (about 2 large))","2 sprigs of thyme OR 1 tsp dried thyme","3/4 cup cream (Note 1)","3/4 cup shallots / scallions (, green part finely sliced)","Salt and finely ground pepper to taste"],"purpose":"Soup:"}]', '[{"title":"Cut the corn off the cob. This is how I do it","description":"Place a small ramekin in a large bowl. Place corn on the ramekin then cut the corn off. See video. Keep naked cobs.","images":[],"step":1},{"description":"Place 1 tsp butter in a large pot over medium high heat. Add bacon and cook until golden. Use a slotted spoon to remove onto a paper towel lined plate. Leave fat in pot.","images":[],"step":2},{"description":"Lower heat to medium high. Add 2 tbsp butter, once melted, add garlic and onion. Cook for 2 - 3 minutes until onion is translucent.","duration":2.5,"images":[],"step":3},{"description":"Add flour and mix it in. Cook, stirring, for 1 minute.","duration":1,"images":[],"step":4},{"description":"Add broth, milk, potatoes, thyme and bay leaf. Break naked cobs into 2 or 3 and add into the liquid. Put the lid on and simmer for 25 minutes (adjust heat so it''s simmering energetically but not bubbling like crazy or super gently).","duration":25,"images":[],"step":5},{"description":"Remove lid, remove corn cobs. Add corn and cook for 5 minutes or until cooked to your taste.","duration":5,"images":[],"step":6},{"description":"Stir through cream and 3/4 of the bacon and shallots. Adjust salt and pepper to taste. Ladle into bowls and garnish with remaining bacon and shallots.","images":[],"step":7}]', '["gluten","milk"]', '[]', '{"mealType":["main_course"],"cuisine":[],"categories":["dinner-tonight","main-dishes","quick-and-easy","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_abdea3facba5', 'en', 'US', 'Slow Cooker BBQ Pulled Pork Sandwich', 'See recipe video above. Tender perfectly seasoned slow cooker pulled pork smothered in a homemade BBQ Sauce (see notes for using store bought). Add a classic coleslaw then pile it high onto buns! Great food for gatherings - easy and good value to feed a crowd. Make this in the slow cooker, oven or pressure cooker.', 'https://www.recipetineats.com/tachyon/2017/01/BBQ-Pulled-Pork-Sandwiches-1.jpg', 15, 480, 495, 6, '[{"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.019, "unit": "jar of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_pork_shoulder", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_apples", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_quantity_coleslaw", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_bread", "quantity": {"value": 6.0, "unit": "loaf"}}, {"id": "ing_pork", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_ketchup", "quantity": {"value": 0.75, "unit": "bottle of 500g"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.25, "unit": "bottle of 500ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 15.0, "unit": "bottle"}}]', '[{"ingredients":["2 tbsp brown sugar","2 tsp paprika powder","1 tsp onion powder","1 tsp garlic powder","1/2 tsp cumin powder","3/4 tsp mustard powder","1 tsp salt","1/2 tsp black pepper"],"purpose":"Rub"},{"ingredients":["1.5 - 2.2 kg/ 3 - 4.5 lb pork shoulder or butt (, skinless and boneless (Note 1))","3/4 cup apple cider or apple juice (Note 2)","1 quantity Coleslaw","6 - 8 bread rolls"],"purpose":"Pork"},{"ingredients":["1 cup pork juices from slow cooker, once cooked","2 1/2 cups ketchup","1/2 cup apple cider vinegar","2/3 cup brown sugar","1 1/2 tsp each black pepper, onion (or garlic powder), mustard powder","1 tbsp lemon juice","1 tbsp Worcestershire sauce"],"purpose":"BBQ Sauce (Note 5)"}]', '[{"description":"Mix together Rub then rub all over the pork. Optional: Marinate for 1 hour.","images":[],"step":1},{"description":"Place in the slow cooker and pour over apple cider. Slow cook for 8 hours on low or pressure cook for 1 hr 30 minutes on high. (Note 3)","images":[],"step":2},{"description":"Remove pork from liquid into a roasting pan. Reserve liquid.","images":[],"step":3},{"title":"OPTIONAL: Roast pork for 20","description":"30 minutes at 180C/350F until browned (Note 4). Meanwhile, make BBQ Sauce.","duration":25,"images":[],"step":4},{"title":"Shred pork with forks","description":"it should be fall apart tender (see video).","images":[],"step":5},{"title":"Toss in BBQ sauce","description":"use as much as you like, the recipe makes enough to coat the pork well but not dripping in sauce, plus a bit extra on the side.","images":[],"step":6},{"description":"To make Pulled Pork Sandwiches, pile pork on warmed rolls and top with Coleslaw. I like to lay everything out for people to make their own.","images":[],"step":7},{"description":"Place all ingredients in a medium saucepan over medium heat and whisk. Bring to simmer, then turn down the heat so it simmers gently. Cook for 1 hour. Remove from stove and use per recipe.","images":[],"step":8}]', '["gluten","mustard"]', '[]', '{"mealType":["dinner"],"cuisine":["Southern"],"categories":["main-dishes","pork-recipes","quick-and-easy","sandwiches-and-sliders","slow-cooked-fall-apart","slow-cooker-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e335e9c8a0ac', 'en', 'US', 'Cajun Baked Turkey Breast and Dressing (Stuffing)', 'This is a genius recipe for a spectacular EASY Thanksgiving centrepiece packed full of big flavours! Avoiding dry baked turkey breast is notoriously difficult, but this recipe tackles that problem in 2 ways: a) Brining the turkey with a Cajun rub; 2) baking the turkey in the same pan as the Dressing (stuffing), it keeps the turkey moist. Plus the turkey juices gets soaked up by the Dressing. No gravy needed - the Dressing has a golden crust but is so juicy underneath, you don''t need gravy. Don''t stress if you can''t get Andouille sausages - refer to the notes. See Note 4 for adjustment for different Turkey sizes. Use Scaler by putting cursor / tap on Servings then move to your turkey weight to adjust recipe scale.', 'https://www.recipetineats.com/tachyon/2016/11/Cajun-Turkey-with-Dressing-6.jpg', 15, 240, 255, 8, '[{"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_rosemary", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_pound_bone_in_turkey_breast", "quantity": {"value": 3.629, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 2000.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_steak", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.002, "unit": "kg"}}, {"id": "ing_sausages", "quantity": {"value": 1.134, "unit": "pack of 500g"}}, {"id": "ing_tabasco_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_bread", "quantity": {"value": 0.281, "unit": "loaf"}}]', '[{"ingredients":["1 tbsp kosher salt *","1 tsp each freshly cracked black pepper (, ground oregano **)","2 tsp each onion powder (, garlic powder, smoked paprika ^)","1/2 tsp cayenne pepper","1/2 tsp. each dried thyme and rosemary"],"purpose":"Cajun Rub"},{"ingredients":["8 lb / 4 kg pound bone-in turkey breast (\"crown\" or \"buffe\") (Note 1)"],"purpose":"Turkey"},{"ingredients":["4 tbsp / 50g butter","8 cloves garlic (, minced (2 tbsp))","2 large onions (, finely chopped^^ (4 cups))","2 celery ribs (, finely chopped (2 cups))","2 green peppers / capsicum (, finely chopped (2 cups))","1 1/4 lb / 650g Andouille sausages (Note 3 for subs!)","1-2 tbsp Tabasco sauce (, to taste)","2 cups chicken stock / broth","1 1/2 cups bread crumbs (panko breadcrumbs can be substituted)"],"purpose":"Dressing / Stuffing (Note 2)"}]', '[{"description":"Mix together Cajun Rub.","images":[],"step":1},{"description":"Rub turkey breast with 3 tbsp of poultry rub (Note 1). Place on a plate and refrigerate overnight, uncovered (24 - 36 hours).","images":[],"step":2},{"title":"Remove turkey from fridge","description":"leave out while making Dressing / Stuffing.","images":[],"step":3},{"description":"Use a food processor to ground the sausages, or finely chop them. If using raw substitute sausages (see Note 3), you can just squeeze the meat out of the casings.","images":[],"step":4},{"description":"Melt butter in large skillet over medium high heat. Add the garlic, half the onion, half the celery and half the capsicum. Cook for 10 minutes or until the vegetables are softened.","duration":10,"images":[],"step":5},{"description":"Transfer vegetables into a bowl. If the skillet is looking dry, add a tiny splash of oil. Add sausage and cook, breaking it up as you go.","images":[],"step":6},{"description":"Add cooked onion etc back into the skillet and add remaining onion, celery and capsicum. Stir.","images":[],"step":7},{"description":"Add tabasco (start with 1 tbsp) and chicken broth. Bring to simmer, then turn heat down to medium. Simmer for 10 minutes.","duration":10,"images":[],"step":8},{"description":"Stir in breadcrumbs then remove from heat. It should still be very moist and a bit liquidy, but not like soup.","images":[],"step":9},{"description":"While Dressing is simmering, preheat oven to 325F / 165C (standard) or 295F / 145C (fan forced / convection).","images":[],"step":10},{"description":"Place turkey breast in a roasting pan so there is 2\"/5cm (or so) around it for the dressing.","images":[],"step":11},{"description":"Spoon dressing around the turkey.","images":[],"step":12},{"title":"Cover loosely with foil then bake for 3 1/4","description":"3 1/2 hours, then uncover and roast for an additional 30 minutes to brown and crisp the skin, or until the internal temperature of the turkey is 75C / 165F (Note 4).","images":[],"step":13},{"description":"Remove from oven then loosely cover with foil. Rest for 20 minutes before serving (Note 5).","duration":20,"images":[],"step":14}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["American","Cajun"],"categories":["main-dishes","roasts","turkey-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c049a72deaf2', 'en', 'US', 'Pork Tenderloin with Creamy Marsala Sauce', 'Juicy pork tenderloin smothered in a Creamy Marsala Sauce with Mushrooms. It''s like gravy - but even better because the sauce has beautiful layers of flavour in it from the Marsala. Using wine in cooking is how posh restaurants make such beautiful sauces! Use this Marsala Sauce for other proteins like chicken, veal and beef.', 'https://www.recipetineats.com/tachyon/2016/06/Pork-Tenderloin-Creamy-Marsala-Sauce_4.jpg', 5, 30, 35, 3, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_pork", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.142, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.75, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_marsala", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_tarragon", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.25, "unit": "carton of 250ml"}}]', '[{"ingredients":["1 tbsp olive oil","1 lb / 500g pork tenderloin (Note 1)"]},{"ingredients":["2 tbsp butter (salted or unsalted)","5 oz / 150g mushrooms (, sliced (I used Swiss Brown))","1/4 cup finely chopped shallots or onion","1 garlic clove (, minced)","1 1/2 tbsp flour","1/2 cup / 125 ml marsala (Note 2)","2 cups / 500 ml chicken broth (, low sodium)","5 tarragon leaves (optional) (thyme is also lovely) (Note 3)","1/4 cup / 65 ml cream"],"purpose":"Creamy Marsala Sauce"}]', '[{"description":"Preheat oven to 200C/390F.","images":[],"step":1},{"description":"Sprinkle pork with salt and pepper.","images":[],"step":2},{"description":"Heat oil in an ovenproof skillet over high heat. Sear on all sides until nicely browned.","images":[],"step":3},{"description":"Place in the oven for 15 minutes for the faintest blush of pink (pictured) or 18 to 20 minutes for no pink. See Note 4 for internal cook temperatures.","duration":15,"images":[],"step":4},{"description":"Remove pork from skillet onto a plate, cover with foil and set aside in a warm place while you make the sauce.","images":[],"step":5},{"description":"Creamy Marsala Sauce","images":[],"step":6},{"description":"Melt 1 tbsp butter in the same skillet over high heat. Cook mushrooms until browned, then remove.","images":[],"step":7},{"description":"Reduce heat to medium high, melt 1 tbsp butter,. Add onion and garlic, cook for 2 minutes or until onion is softened. Add flour and mix.","duration":2,"images":[],"step":8},{"description":"Add marsala, cook until mostly evaporated (about 1 minute). Add tarragon and chicken broth, whisk until dissolved. Bring to simmer and cook until the liquid reduces by half - 3 to 5 minutes.","images":[],"step":9},{"description":"Add cream and mix, then return the mushrooms and pork into the skillet as well as juices pooled on the plate. Simmer for 1 - 2 minutes until the sauce thickens into a thin gravy consistency (it will thicken more as you serve).","duration":1.5,"images":[],"step":10},{"description":"Transfer to serving platter with the gravy on the side or poured over the top. Serve with mashed potatoes of course!! (Here is my Make Ahead Mashed Potatoes recipe)","images":[],"step":11}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["French-ish"],"categories":["dinner-tonight","main-dishes","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7640b1e8e01f', 'en', 'US', 'Sun Dried Tomato Pasta', 'This is like sun dried tomato pesto, but it''s creamy and the flavour of the sun dried tomatoes and basil is a lot more intense! I like to serve it hot, like other creamy pastas I make, but people I''ve given leftovers to tell me that they like it at room temperature too. This version has spinach tossed through it but it''s also lovely with chicken, shrimp/prawns, roasted vegetables and even bacon!', 'https://www.recipetineats.com/tachyon/2015/11/Cream-Sun-Dried-Tomato_2-Featured-600px.jpg', 15, 15, 30, 4, '[{"id": "ing_tomato", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_basil", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.15, "unit": "tub of 250g"}}, {"id": "ing_cream", "quantity": {"value": 0.25, "unit": "carton of 250ml"}}, {"id": "ing_milk", "quantity": {"value": 0.438, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.6, "unit": "pack of 500g"}}, {"id": "ing_tomato", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_spinach", "quantity": {"value": 4.0, "unit": "bag of 250g"}}, {"id": "ing_basil", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["3/4 cup (tightly packed) sun dried tomatoes, roughly chopped (Note 1) + more for garnish","1/2 cup basil leaves (, lightly packed)","1/4 cup yoghurt or sour cream (optional) (Note 2)","1/4 cup cream (Note 3)","1 3/4 cups milk (I use low fat)","1 tbsp tomato paste (optional) (Note 4)","1/4 cup parmesan cheese (, finely grated)","1/2 tsp salt","Pepper"],"purpose":"Creamy Sauce"},{"ingredients":["300 g pasta of choice (I like penne/ziti)","1 tbsp oil from sun dried tomatoes","2 garlic cloves (, crushed)","1 small onion (, finely diced (brown, white or yellow))","4 cups (tightly packed) finely shredded fresh English spinach"],"purpose":"Pasta"},{"ingredients":["Parmesan cheese","Fresh basil (, finely shredded)"],"purpose":"To Serve (optional)"}]', '[{"description":"Place the Creamy Sauce ingredients in a blender and puree until smooth. Adjust salt to your taste.","images":[],"step":1},{"description":"Heat oil in a large skillet over medium high heat. Add garlic and cook for 20 seconds, then add onion and cook for 3 to 5 minutes until translucent and cooked through.","duration":0.3333333333333333,"images":[],"step":2},{"description":"Meanwhile, cook your pasta of choice in a large pot of salted boiling water until al dente (just cooked through but still firm). SCOOP out 1 mug of the pasta cooking water, then drain the pasta.","images":[],"step":3},{"description":"Add the pasta into the skillet, then pour the Creamy Sauce in, all the spinach and about 1/2 cup of the pasta water (Note 5). Stir to coat the pasta in the sauce and to wilt the spinach. Cook, stirring gently, for about 2 minutes until the sauce is warmed through. Adjust salt to taste.","images":[],"step":4},{"description":"Use the remaining pasta water to get the sauce to the consistency you want.","images":[],"step":5},{"description":"Remove from the stove and serve immediately, with more parmesan cheese and basil if desired.","images":[],"step":6}]', '["gluten","milk"]', '["vegetarian"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dinner-tonight","main-dishes","pasta-recipes","quick-and-easy","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d6467f0a2650', 'en', 'US', 'Creamy Mushroom and Spinach Orzo (Risoni) (One Pot)', 'An easy dinner for midweek all made in one pot. Super creamy but made without a single drop of cream! Nutrition grade rating of A-. Make it even more nutritious by adding more vegetables!', 'https://www.recipetineats.com/tachyon/2015/05/Spinach-Parmesan-Creamy-Risoni-1.jpg', 10, 20, 30, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_mushroom", "quantity": {"value": 0.544, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.45, "unit": "pack of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.375, "unit": "pack of 200g"}}, {"id": "ing_spinach", "quantity": {"value": 8.0, "unit": "bag of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.375, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 tbsp olive oil","1.2 lb / 600g mushrooms (, sliced (I used button mushrooms))"]},{"ingredients":["3 tbsp butter, unsalted","3 garlic cloves (, minced)","1 small onion (, finely diced)","3 tbsp flour","1 1/2 cups / 375 ml milk (I used low fat)","3 cups / 750 ml chicken broth","1 1/2 cups orzo / risoni, uncooked (Note 1)","1/2 tsp salt","Black pepper","3/4 cup parmesan cheese (, grated)","8 oz / 250g frozen spinach ((1 box), thawed, excess water squeezed out)"],"purpose":"Orzo / Risoni"},{"ingredients":["Extra parmesan cheese","Finely chopped parsley"],"purpose":"Garnish (optional)"}]', '[{"description":"Heat the olive oil in a large non stick pan over high heat (if you aren''t using non stick, use more oil).","images":[],"step":1},{"description":"Add the mushrooms and cook until softened (around 3 minutes). Remove from the pan and set aside.","images":[],"step":2},{"description":"Lower the heat to medium and melt the butter in the pan. Add garlic and onion, and sauté until the onion becomes translucent - around 3 minutes.","images":[],"step":3},{"description":"Add the flour, stir it in and cook for 1 minute.","duration":1,"images":[],"step":4},{"description":"Add the milk and chicken broth and use a whisk to mix the butter flour mixture into the liquid.","images":[],"step":5},{"description":"Increase heat to medium high. Add the orzo/risoni, salt and pepper, stir once, then put a lid on (Note 2). Bring it to a simmer, then leave it to cook for around 8 to 10 minutes or until the orzo/risoni is cooked but still slightly firm, and it is still quite saucy. Note: If you have a strong stove, turn it down slightly so it just simmers).","images":[],"step":6},{"description":"While the orzo is cooking, break up the spinach into little pieces with your fingers.","images":[],"step":7},{"description":"Remove the pan from the stove. Stir through the parmesan, spinach and cooked mushrooms. Check if more salt or pepper is required.","images":[],"step":8},{"description":"Serve immediately, garnished with more parmesan and fresh finely chopped parsley, if desired.","images":[],"step":9}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dinner-tonight","main-dishes","most-popular","mushroom-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_25cdf6bb8a6a', 'en', 'US', 'Mexican Chipotle Pork and Beans', 'Recipe video above. This is a big pot of saucy, shreddable meat in a rich, spicy, chipotle sauce. Pork shoulder is slow cooked into fall-apart submission with meaty lima beans that absorbs the bold flavoured sauce. Stuff in tacos, serve over red rice, eat like stew!SPICE NOTE: This sauce is spicy. Not off-the-charts spicy, but it has a good kick! If you''re concerned, remove half the chillis from the can of chipotle in adobo (as the chillies are where the spiciness is). If you''re still worried, best to give this a miss because chipotle in adobo IS spicy!!', 'https://www.recipetineats.com/tachyon/2023/05/Mexican-Chipotle-Pork-and-Beans_6.jpg', 15, 170, 185, 6, '[{"id": "ing_pork_shoulder", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_chipotle_in_adobo", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_oranges", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}]', '[{"ingredients":["1.5kg / 3lb pork shoulder (skinless, boneless), cut into 6 equal pieces (Note 1)","1 tsp cooking/kosher salt","1/2 tsp black pepper","2 tsp cumin powder"],"purpose":"Pork:"},{"ingredients":["200g / 7 oz chipotle in adobo (- the chillis + sauce (Note 2))","2 tbsp olive oil","1 onion (, finely chopped)","4 garlic cloves (, finely minced)","1/4 cup tomato paste","1 cup orange juice (real, not reconstituted sweetened stuff - Note 3)","2 cups chicken stock/broth (, low sodium)","2 bay leaves (fresh, else dried)","1 tsp cooking/kosher salt","3 x 420g / 16 oz canned butter beans / lima beans (, or other of choice (Note 4))"],"purpose":"Sauce:"},{"ingredients":["1 tbsp dried oregano","1 tsp cumin powder","1 tsp coriander powder","1/2 tsp allspice powder"],"purpose":"Dried herbs & spices"}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan).","images":[],"step":1},{"title":"SPICINESS","description":"Read note above about spiciness!","images":[],"step":2},{"description":"Puree chipotle in adobo until smooth using a stick blender or similar.","images":[],"step":3},{"description":"Sprinkle pork all over with salt, pepper and cumin.","images":[],"step":4},{"title":"Brown pork","description":"Heat all the oil in a large oven-proof pot over high heat. Brown the pork all over in 2 batches, the remove onto a plate (~ 1 minute each side).","images":[],"step":5},{"title":"Sauté","description":"Cool the pot slightly then return to medium heat. If the pot looks dry, add 1 tbsp oil. Sauté onion, garlic, the herbs & spices for 3 minutes.","duration":3,"images":[],"step":6},{"title":"Cook off tomato & chipotle","description":"Add tomato paste and cook it off for 2 minutes. Add chipotle puree and cook for 2 minutes.","duration":2,"images":[],"step":7},{"title":"Slow cook 2 hours","description":"Add remaining ingredients EXCEPT beans. Stir, then bring to simmer. Place pork in - arrange so its submerged as best as possible. Cover with lid. Place in oven for 2 hours. (Note 6 other cook methods)","images":[],"step":8},{"title":"Add beans, cook 30 min","description":"Remove lid, add beans. Return to oven for 30 minutes without lid to caramelise the surface. The pork will be fork-tender!","duration":30,"images":[],"step":9},{"description":"Serve like stew over Mexican red rice or with tortillas for dunking. Or make wickedly food tacos with finely chopped white onion, fresh coriander/cilantro, avocado slices and a squeeze of lime. More serving options above the recipe video.","images":[],"step":10}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["mains","mexican-recipes","pork","pork-recipes","slow-cooked-fall-apart","slow-cooker-recipes","stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d835d34e8e79', 'en', 'US', 'Just a great Pork Rub', 'Recipe video above. This is a real great all-rounder rub for pork chops. It gives the pork great flavour, a lovely warm red colour, and if you throw a knob of butter in at the end, you get a tasty flavoured sauce too!There''s enough spices in the rub so that if you''re missing one or two, the rub will still be tasty, see Note 1.Makes 4 tablespoons / 45g of rub which will season 4 thick-cut chops. Keeps for the shelf life of the spices you used.', 'https://www.recipetineats.com/tachyon/2021/08/Pork-Rub_06.jpg', 5, 12, 17, 4, '[{"id": "ing_smoked_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.011, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_mustard", "quantity": {"value": 0.019, "unit": "jar of 200g"}}, {"id": "ing_cumin", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_sage", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_pork", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}]', '[{"ingredients":["1 tbsp smoked paprika","2 1/4 tsp salt (cooking/kosher salt, Note 2)","3/4 tsp black pepper","1 1/2 tsp garlic powder","1 1/2 tsp onion powder","1 tsp dried oregano","3/4 tsp mustard powder","1/2 tsp cumin powder","1/2 tsp sage powder"],"purpose":"Pork rub (subs Note 1):"},{"ingredients":["4 pork chops, any type (pictured: pork cutlets, 220g/7oz each, 2cm / 0.8\" thick) (Note 3)","1 1/2 tbsp olive oil (per batch you cook)","50g / 4 tbsp unsalted butter (for flavoured butter sauce, 15 g / 1 tbsp per chop)"],"purpose":"Pork:"}]', '[{"title":"Rub: Mix spices in a small bowl. Keeps for weeks","description":"even months! (Whatever the shelf life of the spices is you used).","images":[],"step":1},{"title":"Using pork rub","description":"Pat pork chops dry. Sprinkle then use your fingers to lightly rub the seasoning on both sides, as well as the sides. Shake off excess. Cook per below.","images":[],"step":2},{"title":"Cooking thin pork chops","description":"up to 1.75 cm / 0.7\" thick (Note 3):","images":[],"step":3},{"description":"Place a rack over a tray. (Note 4)","images":[],"step":4},{"description":"Heat oil in a heavy based skillet over medium-high heat.","images":[],"step":5},{"description":"Cook pork chops for 3 minutes on each side until deep golden. Don''t crowd the pan else the pork will stew instead of sear!","duration":3,"images":[],"step":6},{"description":"Rest on rack for 3 minutes.","duration":3,"images":[],"step":7},{"description":"Melt butter in skillet, stirring to dissolve rub left in pan into the butter. Serve over pork!","images":[],"step":8},{"title":"Cooking THICK pork chops","description":"2cm / 0.8\"+ (Note 3):","images":[],"step":9},{"description":"Preheat oven to 200°C/390°F (180°C fan). Place a rack over a tray. (Note 4)","images":[],"step":10},{"description":"Heat oil in a heavy based skillet over medium high heat.","images":[],"step":11},{"description":"Use tongs to sear the edge of the chops (fat strip), rotating as you go, until you get nice colour all around, about 3 minutes in total (see video demo). Then sear each side for 2 minutes until golden.","duration":2,"images":[],"step":12},{"description":"Put pan into the oven and allow to finish cooking for 3 minutes or until the internal temperature reaches 65°C/149°F. Remove pork and rest 3 minutes on rack.","duration":3,"images":[],"step":13},{"description":"Melt butter in skillet, stirring to dissolve rub left in pan into the butter. Serve over pork!","images":[],"step":14}]', '["milk","mustard"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","mains","pork","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7dfcdd73275e', 'en', 'US', 'Pork Tenderloin with Creamy Mustard Sauce', 'Recipe video above. This is one of those recipe gems that proves just few ingredients and minimal effort can still deliver a knock-out dish!It''s easy enough for a weeknight meal, but can step up as a dish elegant enough for company. A pinch of fresh tarragon adds a lovely sweet aniseed flavour, while mustard brings the oomph and thickens the sauce.Note: The cook time is affected by the size of the pork fillet so a meat thermometer is highly recommended to ensure the pork is cooked perfectly.', 'https://www.recipetineats.com/tachyon/2021/05/Pork-Tenderloin-with-Creamy-Mustard-Sauce_4.jpg', 8, 20, 33, 5, '[{"id": "ing_pork", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_tarragon", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}]', '[{"ingredients":["2 pork tenderloins (, 500g / 1lb each (Note 1))","1 tsp salt","1 tsp pepper","2 tbsp oil (vegetable, canola, or olive oil)"]},{"ingredients":["1/2 cup cream (, heavy / thickened (Note 2))","1 tbsp Dijon mustard (Note 3)","1 tbsp whole grain mustard (Note 3)","2 tsp tarragon (, finely chopped (Note 4))","2 tsp parsley (, finely chopped (Note 4))","1/2 tsp salt","1/2 tsp pepper","1 - 2 tbsp water (, as needed)"],"purpose":"Sauce:"}]', '[{"title":"Preheat oven","description":"Preheat oven to 200°C / 390°F (180°C fan). Place a rack over a tray (for resting the cooked meat).","images":[],"step":1},{"title":"Season pork","description":"Sprinkle the tenderloins all over with salt and pepper.","images":[],"step":2},{"title":"Sear pork","description":"Heat oil in a large oven-proof skillet over medium-high heat. Sear pork all over until golden. This takes around 5 minutes (I sear 4 sides).","images":[],"step":3},{"title":"Bake (Note 5)","description":"Transfer the skillet with the pork in it to the oven. Bake for 12 - 15 minutes or until an instant read thermometer reads 65°C / 149°F. This will have a blush of pink, a perfect medium for optimum juiciness. (For no pink at all, add 3 minutes cooking and target an internal temperature of 68°C / 155°F.)","duration":13.5,"images":[],"step":4},{"title":"Rest","description":"Remove pork from skillet and transfer to the resting rack for 5 minutes.","duration":5,"images":[],"step":5},{"title":"Creamy Mustard Sauce","description":"Return same skillet to the stove over medium heat. Add cream and both mustards. Mix well, scraping the bottom of the pan to dissolve any golden bits stuck to the base of the pan into the sauce (free flavour!). Once it becomes hot but not simmering, stir in salt, pepper, tarragon and parsley. If the sauce seems too thick, thin with a little water as needed. No need to simmer, the sauce is done!","images":[],"step":6},{"title":"Serve: Slice into 2","description":"2.5cm (0.8 - 2\") slices. Serve with Creamy Mustard Sauce!","images":[],"step":7}]', '["milk","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","mains","pork","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1b90880ba9f8', 'en', 'US', 'Pesto pasta salad', 'Recipe video above. Don''t skimp on pesto, and don''t be shy with olive oil. If you do, you''ll end up staring at a mound of flavour-lacking, dry pesto pasta salad, thinking "darn it, I should have just followed the recipe!".PS Just 2 tablespoons of mayo is the secret here. Just gives an edge of creaminess without weighing it down, plus significantly improves the quality of next-day leftovers - prevents it from drying out.TIP: Homemade pesto obviously rules here, but if you need to resort to store-bought, get it from the fridge rather than aisle. It''s better.', 'https://www.recipetineats.com/tachyon/2023/03/Pesto-pasta-salad_9.jpg', 15, 15, 30, 5, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.7, "unit": "pack of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_pinenuts", "quantity": {"value": 30.0, "unit": "jar"}}, {"id": "ing_basil", "quantity": {"value": 1.2, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.105, "unit": "L"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.075, "unit": "jar of 400g"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_baby_bocconcini", "quantity": {"value": 220.0, "unit": "unit"}}, {"id": "ing_baby_rocket_arugula", "quantity": {"value": 0.22, "unit": "kg"}}, {"id": "ing_basil", "quantity": {"value": 1.2, "unit": "bunch"}}]', '[{"ingredients":["350g / 12oz spiral pasta (fusilli, or other of choice, 3 1/2 cups)","1 tbsp salt (, for cooking pasta)"]},{"ingredients":["2 tbsp pinenuts (, toasted (sub walnuts, cashews, almonds))","2 cups (tightly packed) basil leaves","1 small garlic clove (, minced)","1/2 cup parmesan (, finely grated)","1/2 tsp cooking/kosher salt","1/4 tsp black pepper","7 tbsp extra virgin olive oil (or 50/50 grapeseed/olive oil)"],"purpose":"Pesto (Note 1):"},{"ingredients":["2 tbsp mayonnaise (S&W, else Hellman''s, Note 2)","250g (1 heaped cup) cherry tomatoes, cut in half","220g/ 7 oz baby bocconcini (, drained, cut in half (Note 3))","1 cup (tightly packed) baby rocket/arugula leaves (40g)","1/2 tsp cooking/kosher salt","Small basil leaves (, optional garnish)"],"purpose":"Pasta Salad:"}]', '[{"title":"Cook pasta","description":"Bring 3 litres of water to the boil with the salt. Cook for the pasta packet time + 1 minute. Drain in a colander, rinse under cold water. Shake off excess water well, then allow to fully cool and dry.","images":[],"step":1},{"title":"Pesto","description":"Place all ingredients in a tall jug just large enough to fit the head of a stick blender. Blitz under pretty smooth. Not a green smoothie, we still want some visible green bits! but not chunks.","images":[],"step":2},{"title":"Toss","description":"Place pasta in a bowl, scrape in the pesto. Add mayonnaise then toss well. Add bocconcini and tomato, toss gently just to disperse. Add rocket/arugula and toss just to disperse.","images":[],"step":3},{"title":"Serve","description":"Transfer into a serving bowl. Scatter with basil leaves, if using. Serve!","images":[],"step":4}]', '["gluten","milk"]', '["high_protein","vegetarian"]', '{"mealType":["lunch","dinner"],"cuisine":["Western"],"categories":["pasta-recipes","pasta-salads-and-rice-salads","salad-recipes-main-course","side-salads","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a29db9f1af40', 'en', 'US', 'Mega Italian Salad', 'My favourite big Italian salad. The homemade dressing is seriously tasty! The croutons and dusting of parmesan is the perfect finishing touch that everybody loves. Serve with pasta, a cosy lasagne or big tray of cannelloni. Lots of suggestions in the post!{No video today because I thought this was quite straight forward. But if you want one, leave me a message below!}', 'https://www.recipetineats.com/tachyon/2022/09/Mega-Italian-Salad_5.jpg', 10, 15, 25, 6, '[{"id": "ing_bread", "quantity": {"value": 0.15, "unit": "loaf"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 0.1, "unit": "pack of 200g"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_basil", "quantity": {"value": 0.025, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.013, "unit": "pack of 100g"}}, {"id": "ing_salt", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_whole_pitted_kalamata_olives", "quantity": {"value": 150.0, "unit": "bottle"}}, {"id": "ing_parmesan", "quantity": {"value": 0.1, "unit": "pack of 200g"}}]', '[{"ingredients":["3 slices white sandwich bread (, ~1.75 cm / 3/4\" thick, crust off, cut into cubes (Note 1))","1 tbsp extra virgin olive oil","2 pinches salt"],"purpose":"Croutons:"},{"ingredients":["1/4 cup extra virgin olive oil","2 tbsp red wine vinegar (Note 2)","4 tsp freshly grated parmesan (Note 1)","2 tsp sugar (any)","1/4 tsp each garlic powder","1/4 tsp dried basil","1/4 tsp chilli flakes ((red pepper flakes), optional)","1/2 tsp cooking/kosher salt","1/8 tsp black pepper"],"purpose":"Italian Dressing:"},{"ingredients":["1 head cos / romaine lettuce (, chopped into large or small bite size pieces (Note 3))","2 large tomatoes (, cut into 6 to 8 wedges, then each wedge in half)","1/2 green capsicum/bell pepper (, 1.5cm / 2/3\" cubes)","1/2 red onion (, finely sliced)","1 cup whole pitted kalamata olives (Note 4)","1/4 cup (tightly packed) finely grated parmesan"],"purpose":"Salad:"}]', '[{"title":"Croutons","description":"Preheat oven to 200°C/390°F (180°C fan). Toss bread with oil and salt. Spread on a tray and bake 15 minutes, stirring twice, until golden and fully crisp. Cool on tray.","images":[],"step":1},{"title":"Dressing","description":"Shake ingredients in a jar.","images":[],"step":2},{"title":"Make salad","description":"Set aside some parmesan for garnish. Place croutons and all remaining salad ingredients in a large bowl. Pour Dressing over, toss well.","images":[],"step":3},{"title":"Serve","description":"Transfer salad into a serving bowl. Sprinkle with reserved parmesan. Serve immediately!","images":[],"step":4}]', '["gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["lunch"],"cuisine":["American-Italian","Italian"],"categories":["salad-recipes-main-course","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5e8e6a61487a', 'en', 'US', 'Warm French Goat''s Cheese Salad (Salade de Chêvre Chaud)', 'Recipe video above. Warm Goat’s Cheese Salad is a classic starter found in bistros all across France. Called Salade de Chêvre Chaud, it''s a fresh leaf salad with nuts and bacon, and crowned with pan-fried goat’s cheese medallions that are golden outside and oozing inside. Simple to make, this most French of French salads makes for a chic change from the usual crumbled goats cheese number!Serves 4 as a starter, or 2 as a meal', 'https://www.recipetineats.com/tachyon/2021/06/French-Goats-Cheese-Salad_6.jpg', 20, 10, 30, 2, '[{"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 0.062, "unit": "loaf"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_pine_nuts", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_walnuts", "quantity": {"value": 37.5, "unit": "jar"}}, {"id": "ing_bacon", "quantity": {"value": 0.5, "unit": "pack of 200g"}}, {"id": "ing_lettuce", "quantity": {"value": 0.5, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_chives", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.417, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_mustard", "quantity": {"value": 0.006, "unit": "jar of 200g"}}, {"id": "ing_balsamic_vinegar", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.068, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}]', '[{"ingredients":["2 x 60g / 2oz ripened goat''s cheese (, each round 5-6cm (2-2.2\") wide, ideally AOC (Note 1))","1 egg","2 tbsp flour (, plain / all-purpose)","1/3 cup breadcrumbs (regular kind, else sub panko; (Note 2))","30g / 2 tbsp butter (, unsalted)"],"purpose":"Crumbed Goats Cheese Medallions:"},{"ingredients":["2 tsp pine nuts","1/4 cup walnuts","100g / 3.5oz bacon (streaky; cut into 0.5 x 1.25cm (1/5 x 1/2\") lardons)","1/2 head of red oak or bibb lettuce (large) (, washed, dried and leaves torn into 2 or 3 large pieces; (Note 3))","1 tomato (large; cut into 8 wedges)","1/2 tsp chives (, finely chopped)"],"purpose":"Salad:"},{"ingredients":["1/4 tsp garlic (, very finely minced)","1 tbsp eschalot (, finely diced (~ 1 tbsp); (Note 4))","1/4 tsp Dijon mustard","1 1/2 tbsp balsamic vinegar (the best quality you can afford)","4 1/2 tbsp extra virgin olive oil (the best quality you can afford)","1/8 tsp salt"],"purpose":"Vinaigrette:"}]', '[{"description":"Crumb goat''s cheese:","images":[],"step":1},{"title":"Slice cheese","description":"Cut goat''s cheese if necessary to create ~ 1.25cm (1/2\") thick rounds.","images":[],"step":2},{"description":"Place flour, whisked egg and breadcrumbs in 3 separate, small bowls.","images":[],"step":3},{"title":"Crumb cheese","description":"Coat cheese in flour, shake off excess. Dip in egg, allow excess to drip. Coat with breadcrumbs, pressing to adhere. Place on plate and set aside.","images":[],"step":4},{"title":"Toast nuts","description":"Spread nuts in a layer on a tray. Toast in a 180C / 375F oven for around 5 minutes until they are lightly browned and smell toasty. Immediately transfer to a small bowl to cool. Alternatively, toast in a skillet over medium heat (walnuts will take longer than pine nuts, so best to do in separate batches).","images":[],"step":5},{"title":"Cook bacon","description":"Place bacon in a cold non-stick pan. Turn the stove to medium and let the pan warm up. Once the fat starts to melt, turn the heat to high. Stir and cook bacon until golden. Drain excess fat on paper towels.","images":[],"step":6},{"title":"Dressing","description":"Shake dressing ingredients in a jar.","images":[],"step":7},{"title":"Begin assembling salad","description":"Place lettuce in a bowl, casually arrange tomatoes, then sprinkle with nuts and bacon.","images":[],"step":8},{"description":"Pan-fry cheese:","images":[],"step":9},{"description":"Melt butter in a small non-stick pan over medium-high heat.","images":[],"step":10},{"title":"Pan-fry cheese","description":"Once butter is foaming, cook crumbed cheeses for 1 - 1 1/2 minutes on one side until golden. Carefully turn, cook other side for 1 minute until golden. Remove and drain on paper towels.","duration":1,"images":[],"step":11},{"description":"Drizzle each salad with 2 tbsp of dressing. Arrange 2 crumbed cheeses on top of each salad. Sprinkle with chives.","images":[],"step":12},{"description":"Serve immediately, while cheese is hot and melty inside!","images":[],"step":13}]', '["egg","gluten","milk","mustard"]', '["high_protein"]', '{"mealType":["lunch"],"cuisine":["French"],"categories":["salad-recipes-main-course","side-salads","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d9cee3c9bf0e', 'en', 'US', 'My Favourite Quinoa Salad', 'Recipe video above. Elevate your Quinoa Salad with two simple tricks: Toasting the quinoa in the oven to give it a gorgeous nutty flavour (great cheffy tip!), and use a wickedly good garlic/ginger dressing!It makes an excellent meal-worthy Asian-style salad, or colourful rainbow salad to take to gatherings. Don''t skip the sprinkle of Wasabi Pea dust. It''s the cherry on top!Serves: 10-12 as side, 5 as meal', 'https://www.recipetineats.com/tachyon/2021/03/My-Favourite-Quinoa-Salad-5.jpg', 20, 35, 55, 10, '[{"id": "ing_quinoa", "quantity": {"value": 150.0, "unit": "pack"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_cucumber", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_red_cabbage", "quantity": {"value": 9.0, "unit": "head"}}, {"id": "ing_green_onion", "quantity": {"value": 0.04, "unit": "bunch"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_shelled_edamame", "quantity": {"value": 150.0, "unit": "pack"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.3, "unit": "bottle of 250ml"}}, {"id": "ing_mirin", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_grapes", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.094, "unit": "jar of 400g"}}, {"id": "ing_sugar", "quantity": {"value": 0.013, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_wasabi_peas", "quantity": {"value": 0.333, "unit": "unit"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.15, "unit": "pack of 100g"}}]', '[{"ingredients":["1 cup quinoa (, tri-colour (or other colour, Note 1))","2 cups water"],"purpose":"Quinoa:"},{"ingredients":["1 cup cucumber (, finely diced (Note 2))","1 carrot (, medium, peeled and finely shredded (Note 3))","3 cups red cabbage (, finely shredded (~1/4 small or 1/8 large cabbage))","2 green onions (, finely sliced)","250g/ 8oz cherry tomatoes (, small ones quartered, large ones cut into 6)","1 cup shelled edamame (, cooked per packet then cooled (Note 4))","1 red capsicum/bell pepper (, finely chopped)","1/2 cup coriander/cilantro leaves (, finely chopped)"],"purpose":"Salad:"},{"ingredients":["5 tbsp soy sauce (, light or all-purpose (Note 5))","2 tbsp mirin (Note 6)","2 tbsp rice wine vinegar (sub: cider, sherry or champagne vinegar)","2 tbsp sesame oil (, toasted (Note 7))","2 1/2 tbsp canola, vegetable or grapeseed oil","2 1/2 tbsp Kewpie mayonnaise (sub whole-egg mayo such as Hellman''s or S&W, Note 8)","2 1/2 tsp sugar (white or brown)","2 tsp ginger (, freshly grated)","1 garlic clove (, crushed using garlic press or finely grated using microplane)"],"purpose":"Dressing:"},{"ingredients":["1/3 cup wasabi peas (, crushed (Note 9))","1 tbsp sesame seeds (, toasted (Note 10))"],"purpose":"Garnishes:"}]', '[{"description":"Cook quinoa:","images":[],"step":1},{"title":"Toast for extra flavour","description":"Preheat oven to 200°C/390°F (180° fan) Spread quinoa on a tray. Bake 15 minutes, stirring halfway, until it''s lightly browned and smells nutty.","images":[],"step":2},{"title":"Rinse","description":"Transfer to fine mesh sieve or strainer. Rinse under running water for 10 seconds, shake off excess water well.","duration":0.16666666666666666,"images":[],"step":3},{"title":"Cook","description":"Scrape into a medium saucepan. Add water, place lid on. Bring to simmer on medium heat, then lower stove to low and simmer for 15 minutes (or until all water is absorbed, tilt pot to check).","duration":15,"images":[],"step":4},{"title":"Rest","description":"Remove from stove (lid still on) and rest for 10 minutes.","duration":10,"images":[],"step":5},{"title":"Fluff & cool","description":"Remove lid, fluff quinoa with a fork and allow to fully cool before using. (Spread on a tray if you want to speed things up).","images":[],"step":6},{"title":"Dressing","description":"Place ingredients in a jar and shake well.","images":[],"step":7},{"description":"Toss salad! Place quinoa in a large bowl. Add all salad ingredients. Pour over dressing, toss very well.","images":[],"step":8},{"title":"Garnish","description":"Either transfer to a large serving platter or individual bowls. Sprinkle generously with crushed Wasabi Peas and sesame seeds. Devour!","images":[],"step":9}]', '["egg","gluten","sesame","soy"]', '["low_calorie","vegetarian"]', '{"mealType":["dinner","lunch"],"cuisine":["Asian-esque"],"categories":["salad-recipes-main-course"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b807a6a8f60e', 'en', 'US', 'Chicken Pasta Salad with Creamy Dressing', 'Recipe video above. This is a big batch Chicken Pasta Salad with plenty of creamy dressing, lightened up using a combination of sour cream and mayonnaise so it''s not excessively oil. Make it today, enjoy it for days!After a no mayo version? Use a Creamy Yogurt Dressing instead.', 'https://www.recipetineats.com/tachyon/2021/02/Creamy-Chicken-Pasta-Salad_2.jpg', 20, 10, 30, 10, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 0.75, "unit": "pack of 200g"}}, {"id": "ing_celery", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.04, "unit": "bunch"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_avocado", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.375, "unit": "jar of 400g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.6, "unit": "tub of 250g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_sugar", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 1.0, "unit": "jar of 50g"}}]', '[{"ingredients":["500g / 1 lb macaroni / elbow pasta (or other pasta of choice)","1 tbsp salt (to cook pasta)"]},{"ingredients":["3 cups cooked chicken (, shredded or finely chopped (Note 1))","150g / 5 oz bacon (, chopped)","2 celery stalks (, finely sliced)","1 red capsicum / bell pepper (, finely diced)","2 green onions (, finely sliced)","2 carrots ((medium), shredded using standard box grater)","2 cups shredded cheese (cheddar, tasty, Colby)","2 avocados (small/medium), cut into bite size pieces (optional)"],"purpose":"Pasta Salad:"},{"ingredients":["1 cup mayonnaise (, whole egg best (Hellmann''s, Best Foods, S&W or other whole egg mayonnaise))","1 cup sour cream (, full fat (low fat ok too))","3 tbsp cider vinegar","1 tbsp Dijon mustard","4 tsp sugar","1 1/2 tsp garlic powder","2 tsp salt","1 tsp pepper"],"purpose":"DRESSING:"}]', '[{"title":"Cook pasta","description":"Bring a large pot of water to the boil. Add salt, then cook pasta per packet directions. Drain well, let cool.","images":[],"step":1},{"title":"Dressing","description":"Mix Dressing ingredients in a bowl. Set aside 10 minutes+.","images":[],"step":2},{"title":"Cook bacon","description":"Place bacon in a cold non-stick skillet (Note X). Turn stove on to medium high, then cook bacon until golden. Drain on paper towels.","images":[],"step":3},{"description":"Toss! Place cooked pasta in a large bowl along with all the Pasta Salad ingredients, reserving some bacon for garnish. Pour over Dressing, then toss well.","images":[],"step":4},{"description":"Set aside for 20 minutes. Transfer to serving bowl, sprinkle with remaining bacon. Serve!","duration":20,"images":[],"step":5},{"title":"Storage: Keeps for 3","description":"4 days in the fridge. Best to bring to room temp before serving!","images":[],"step":6}]', '["egg","gluten","milk","mustard"]', '["high_protein"]', '{"mealType":["lunch","dinner"],"cuisine":["Western"],"categories":["no-cook-food","pasta-salads-and-rice-salads","salad-recipes-main-course","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a48e24cde0d4', 'en', 'US', 'Creamy Goat Cheese & Roasted Red Pepper Risoni (Orzo)', 'Recipe video above. Goat''s cheese and jarred fire-roasted red peppers (capsicum) makes this dish special even though it''s quick and simple! The sauce is a little bit smoky and a little bit creamy, while olives add briny freshness. Tastes like a Mediterranean risotto!Get the risoni boiling first then start on the sauce. Serve as a meal or as a side with a simple piece of cooked fish, prawns/shrimp, chicken or pork chops.', 'https://www.recipetineats.com/tachyon/2025/01/Roasted-red-pepper-goats-cheese-risoni_2.jpg', 7, 13, 20, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 0.31, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_kalamata_olives", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_cheese", "quantity": {"value": 120.0, "unit": "block of 250g"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["250g/ 8oz risoni pasta (orzo) (, or other very small pasta (tiny stars, novelty shapes like dinosaurs, ditalini))","2 tsp cooking salt/kosher salt (, for cooking the pasta)","2 tbsp extra virgin olive oil","1 red onion (, halved then cut into 5mm / 0.2\" slices (sub regular onion))","2 garlic cloves (, finely minced)","310g/ 10oz jar chargrilled / fire-roasted sliced red capsicum/peppers","2 cups tomato passata or puree (Note 2)","1/2 cup sliced Kalamata olives ( or other briny/pickly thing (like pickles, chopped))","1/4 tsp cooking salt / kosher salt","1/4 tsp black pepper","120g/4 oz goat''s cheese (, the creamy feta type (Note 3))"]},{"ingredients":["1 tightly packed cup basil leaves","1 tbsp roughly chopped parsley (, plus extra for garnish)"],"purpose":"Finishing – CHOOSE (Note 4)"}]', '[{"title":"Boil risoni","description":"Bring a small pot or large saucepan of water to the boil. Add salt and cook risoni until just under al dente (ie still a bit firm inside) as it will cook more in the sauce. 8 minutes for me.","images":[],"step":1},{"title":"Drain & rinse","description":"Just before draining, scoop out 1/2 cup pasta cooking water and set aside. Drain, rinse briefly under the tap then leave the risoni in the colander while you finish the sauce.","images":[],"step":2},{"title":"Sauté","description":"Heat the oil in a large non stick skillet (30cm/12\") over high heat. Add onion and cook for 2 minutes until starting to soften. Add garlic and capsicum strips. Cook for 2 minutes until the onion is softened.","duration":2,"images":[],"step":3},{"title":"Simmer","description":"Add tomato and olives. Bring to a simmer, lower heat to medium and simmer for 5 minutes, stirring every now and then.","duration":5,"images":[],"step":4},{"title":"Melt goat cheese","description":"Add cooked risoni, salt, pepper and the pasta cooking water. Stir to combine. Add most of the goat''s cheese (reserve some for garnish), stir so it melts.","images":[],"step":5},{"title":"Basil & serve","description":"Stir through basil or parsley just before serving. Divide between bowls. Crumble over reserved goat''s cheese, sprinkle with extra basil. Dig in with a spoon!","images":[],"step":6}]', '["gluten","milk"]', '["vegetarian"]', '{"mealType":["dinner"],"cuisine":["Mediterranean vibes","Western"],"categories":["dinner-tonight","mediterranean-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cdef31925f9d', 'en', 'US', 'Cheesy baked Mexican beef and beans', 'Recipe video above. A bubbly casserole of sorts, this Mexican beef and bean is like a baked version of chilli con carne with lots of melty cheese - but faster to make. Think of it like your ultimate all-purpose Mexican beef - stuff in tacos, DIY burrito wraps, dunk with corn chips - like nachos!', 'https://www.recipetineats.com/tachyon/2023/03/Cheesy-Mexican-Beef-and-Beans-Casserole_8a.jpg', 15, 30, 45, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_kidney_beans", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_tomato", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_pickled_jalape_o", "quantity": {"value": 0.333, "unit": "unit"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_cumin", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2 tbsp olive oil","1 red onion (, finely chopped)","2 garlic cloves (, finely minced)","1 green capsicum / bell pepper (, cut into 1cm / 1/2\" cubes (or other colour))","500g/ 1 lb beef mince (ground beef) (Note 1)","400g/ 14oz can red kidney beans or black beans (, drained (or other beans))","1 cup tomato passata (Note 2)","1/3 cup pickled sliced jalapeño (Note 3)","1 1/2 cups Colby cheese (, shredded (or other cheese, Note 4))"]},{"ingredients":["1 1/2 tsp cumin powder","1 1/2 tsp smoked paprika (sub normal paprika)","1 tsp garlic powder (sub onion powder)","1 tsp garlic powder (sub onion powder)","1 tsp dried oregano","1/2 tsp cayenne pepper (sub black pepper)","1 tsp cooking/kosher salt"],"purpose":"Mexican spice mix:"}]', '[{"description":"Preheat oven to 200°C / 400°F (180°C fan).","images":[],"step":1},{"title":"Sauté","description":"Heat the olive oil in a cast-iron skillet over medium high heat (or other oven-proof pan). Cook onion, garlic and capsicum for 3 minutes.","duration":3,"images":[],"step":2},{"title":"Cook beef & spices","description":"Add beef and cook, breaking it up as you go, until you no longer see raw meat. Add spices, then cook for 1 minute.","duration":1,"images":[],"step":3},{"title":"Beans & tomato","description":"Add kidney beans and passata. Stir, then bring to a simmer.","images":[],"step":4},{"description":"Cheese it! Scatter the jalapeño across the surface, top with cheese.","images":[],"step":5},{"description":"Bake 15 minutes (no lid) then remove from the oven.","images":[],"step":6},{"description":"Serve! Scoop into bowls and serve with corn chips or tortillas with your favourite Mexican fixings (guacamole or avocado sauce pico de gallo or restaurant style salsa, fresh coriander/coriander, sour cream). Dunk like nachos, make DIY burritos or tacos!","images":[],"step":7}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["mexican-recipes","one-pot-recipes","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_574435a6092b', 'en', 'US', 'Beef Barbacoa - Mexican Pulled Beef for Tacos and everything!', 'Recipe video above. Ultra-juicy Mexican pulled beef, tossed in a chipotle-spiced sauce! With a unique subtly spiced, tangy flavour, use this Beef Barbacoa for tacos, burritos, enchiladas, taquitos – the possibilities are endless. This is a slow cooker version that''s simple to put together. Which means ... effortless. YES!', 'https://www.recipetineats.com/tachyon/2021/03/Beef-Barbacoa_3.jpg', 10, 495, 505, 10, '[{"id": "ing_beef_cheeks", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_bay_leaf", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_chipotle_chiles_in_adobo_sauce", "quantity": {"value": 4.0, "unit": "bottle"}}, {"id": "ing_beef", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.25, "unit": "bottle of 500ml"}}, {"id": "ing_lime", "quantity": {"value": 0.12, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 2.0, "unit": "pack of 3 heads"}}, {"id": "ing_cumin", "quantity": {"value": 0.5, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_round_clove", "quantity": {"value": 20.0, "unit": "jar"}}]', '[{"ingredients":["2kg / 4 lb beef cheeks (, or chuck beef(see Note 1))","1 tsp salt (, kosher/cooking)","1 tsp black pepper","2 tbsp vegetable oil (, for searing)","4 bay leaves"]},{"ingredients":["4 chipotle chiles in adobo sauce (Note 2)","3/4 cup dark ale (beer), or low sodium beef broth/stock ( (Note 3))","1/2 cup apple cider vinegar","4 tbsp lime juice","6 garlic cloves","4 tsp ground cumin","2 tsp oregano","1/2 tsp ground cloves"],"purpose":"Barbacoa Sauce:"}]', '[{"title":"Cut beef","description":"Cut large cheeks in half so you have around 12 - 15 pieces cheeks. If using chuck, cut into 12 or so pieces.","images":[],"step":1},{"title":"Season","description":"Sprinkle with salt and pepper.","images":[],"step":2},{"title":"Brown beef","description":"Heat oil in a large pot or skillet over high heat. Sear beef in batches, browning aggressively all over. Place beef in slow cooker.","images":[],"step":3},{"title":"Blitz sauce","description":"Place Barbacoa Sauce ingredients in a blender, food processor or similar (I use a Nutribullet). Blend until smooth – it shouldn''t take long.","images":[],"step":4},{"title":"Slow cooker (see Note 4 for alt. cooking methods)","description":"Pour sauce over cheeks in slow cooker. Add bay leaves. Arrange cheeks so they are submerged as much as possible. Don''t worry, they will release juice as they cook and raise the liquid level.","images":[],"step":5},{"description":"Slow-cook for 8 hours on low. The beef should be effortless to shred when done.","images":[],"step":6},{"title":"Shred","description":"Remove cheeks from slow cooker into a pan. Shred using 2 forks.","images":[],"step":7},{"title":"Sauce","description":"Pour over 3 or 4 ladles of the sauce, then toss.","images":[],"step":8},{"title":"Serve","description":"Use in tacos with taco fixings of choice! Pictured with Mexican Red Rice, Pickled Red Cabbage for Tacos (in this Fish Tacos recipe) and Lime Crema (Note 5).","images":[],"step":9}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["mexican-recipes","slow-cooked-fall-apart","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f902cbfe2cc0', 'en', 'US', 'Prawn Tacos (Shrimp) - with Chipotle Lime Marinade', 'Recipe video above. Chipotle is the power ingredient here, adding a stack of flavour and a hit of heat to this zesty, earthy, Mexican marinade for prawns. Perfectly paired with a creamy-yet-zingy Slaw with the trademark juiciness and floppiness of traditional Coleslaw, but made lighter with no mayonnaise which is too heavy for prawns. The Pink Taco Sauce is my quick sauce of choice here, but there''s enough juiciness in the Slaw and Tacos that you could forgo it - or just add a dash of your favourite hot sauce, or just a dollop of plain sour cream.LEMON alternative - use lemon when limes are not in season. Albeit not traditional Mexican, it works perfectly!SPICE LEVEL: Medium, chipotle is a bit spicy! You can dial it down.', 'https://www.recipetineats.com/tachyon/2020/08/Prawn-tacos_shrimp__3.jpg', 15, 6, 21, 4, '[{"id": "ing_shrimp", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_ime_juice", "quantity": {"value": 0.25, "unit": "unit"}}, {"id": "ing_chipotle", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cabbage", "quantity": {"value": 24.0, "unit": "head"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.225, "unit": "tub of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.45, "unit": "tub of 250g"}}, {"id": "ing_sriracha", "quantity": {"value": 2.0, "unit": "bottle of 400ml"}}, {"id": "ing_tortillas", "quantity": {"value": 12.0, "unit": "pack of 8"}}, {"id": "ing_lime", "quantity": {"value": 2.0, "unit": "net of 500g"}}]', '[{"ingredients":["500g/1 lb medium prawns/shrimp (, peeled (frozen thawed, or 1 kg / 2lb unpeeled whole))","Zest of 1 lime (or lemon)","1/4 cup lime juice (or lemon)","1 tbsp chipotle powder (MEDIUM spicy, can reduce to 2 tsp for MILD, Note 1)","2 tbsp coriander/cilantro (, finely chopped (sub chives))","2 garlic cloves (, minced)","1/4 cup olive oil","1/2 tsp each salt and pepper"],"purpose":"Prawn/shrimp taco marinade:"},{"ingredients":["8 cups green cabbage (, finely shredded (about 1/4 head))","1/2 onion (, very finely chopped (brown, yellow, white))","3/4 cup plain yogurt ((like Greek), unsweetened)","1/4 coriander/cilantro (, finely chopped (sub chives))","1/4 cup lime juice (or lemon)","1/4 cup extra virgin olive oil","1/2 tsp each salt and pepper"],"purpose":"Taco Slaw:"},{"ingredients":["3/4 cup sour cream (or yogurt)","2 - 3 tbsp sriracha (, adjust to taste (Note 2))"],"purpose":"PINK TACO SAUCE:"},{"ingredients":["1 tbsp olive oil","12 - 15 small tortillas ((corn or flour), warmed or charred per packet)","Lime wedges (highly recommended)","Coriander/cilantro (, roughly chopped)"],"purpose":"TO COOK & SERVE"}]', '[{"description":"Mix Marinade ingredients in a bowl, then toss the prawns in the marinade.","images":[],"step":1},{"title":"Set aside for just 20 minutes","description":"no longer. Even 5 minutes is enough.","images":[],"step":2},{"description":"Warm a serving bowl using any method (microwave 1 minute, hot water then dry).","images":[],"step":3},{"description":"Heat 1 tablespoon oil in a large skillet over high heat. Add half the prawns and cook each side for 60 seconds (or on a BBQ on high heat, suggest double skewer for easy rotation).","duration":1,"images":[],"step":4},{"description":"Transfer to warmed bowl, loosely cover with foil. Cook the remaining prawns.","images":[],"step":5},{"description":"Serve with Slaw, Pink Taco Sauce, warmed tortillas and lime wedges.","images":[],"step":6},{"description":"Place all ingredients in a very large bowl then toss well (I use my hands!).","images":[],"step":7},{"description":"Set aside for at least 1 hour until the cabbage becomes wilted and floppy. Keeps for 3 days!","images":[],"step":8},{"description":"Mix ingredients and adjust Sriracha to your taste. Mix well - sour cream becomes looser the more you mix it.","images":[],"step":9}]', '["gluten","milk","shellfish"]', '[]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["mexican-recipes","prawns-shrimp","quick-and-easy","taco-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0455856e71a0', 'en', 'US', 'Taco Sauce', 'A simple taco sauce to serve with any type of tacos. Adds that extra bit of flavour and sauce. It rivals any jar you''ll buy from the store - except you know exactly what goes in it! Great to freeze in serving size portions.', 'https://www.recipetineats.com/tachyon/2018/11/Taco-Sauce_0a.jpg', 5, 10, 15, 1, '[{"id": "ing_tomato", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_cumin", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}]', '[{"ingredients":["2 cups / 500ml tomato passata / puree OR 1 can (16 ounce) US tomato sauce ( (Note 1))","3/4 cup / 185 ml water","1 tbsp cumin","2 tsp onion powder","1 tsp garlic powder","1/2 tsp paprika","1 tsp sugar","1/4 + teaspoon cayenne pepper (adjust heat to taste)","1 1/2 tsp dried oregano","1/4 tsp black pepper","1/2 tsp salt"]}]', '[{"description":"Place all ingredients in a saucepan. Mix then simmer for 10 minutes on medium low.","duration":10,"images":[],"step":1},{"description":"Transfer to serving bowl, cool and serve with tacos or other Mexican dishes requiring a sauce. Makes around 2.5 cups.","images":[],"step":2},{"description":"Or cool, then refrigerate for up to 5 days OR freeze.","images":[],"step":3}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Tex-Mex"],"categories":["dinner-tonight","mexican-recipes","quick-and-easy","sauces","taco-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_12c4f6091ee9', 'en', 'US', 'Freezer Friendly Mexican Meals', 'This is how you make 5 AWESOME freezer friendly Mexican Meals for 4 people in 1 hour for $50!', 'https://www.recipetineats.com/tachyon/2014/09/5-Freezer-Friendly-Mexican-Meals-Cover-Page-v21.jpg', 45, 15, 60, 20, '[{"id": "ing_pdf_version_or_excel_version_of_shopping_list", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_labels_for_food_to_be_frozen", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["PDF version or Excel version of Shopping List (combined + individual recipes)","Labels for food to be frozen."]}]', '[{"description":"Night Before or In the Morning","images":[],"step":1},{"description":"Cook the Pork Carnitas per the recipe instructions. It will only take you 5 minutes to prepare to put in the slow cooker.","images":[],"step":2},{"description":"When the Pork Carnitas are ready, shred the pork and pour over the juices from the slow cooker. You can store the cooked pork in the fridge for up to 3 days.","images":[],"step":3},{"title":"Brown the Pork Carnitas","description":"Heat 1/2 tbsp of olive oil in a large pan. Add half the Pork Carnitas and press down lightly with a spatula to help them brown evenly. Once the underside is brown and crispy, remove from the pan and set aside (about 1 1/2 to 2 minutes). Do not flip - only one side should be crispy (see notes). Repeat with remaining Pork Carnitas.","images":[],"step":4},{"description":"Make the Enchilada Sauce as per the recipe.","images":[],"step":5},{"description":"Make the caramelised onion (for the Quesadillas and Pork Rolls) at the same time you are making the Enchilada Sauce (both are fairly low maintenance). Use the directions from one of those recipes and double it (the quantities and directions are the same).","images":[],"step":6},{"description":"Dice the capsicum and set aside.","images":[],"step":7},{"description":"Assemble each of the meals as per the recipe instructions. Ensure you follow the instructions for making the recipes to freeze.","images":[],"step":8},{"description":"Mexican Pork Rolls with Caramelized Onions","images":[],"step":9},{"description":"Enchilada Stack","images":[],"step":10}]', '[]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Mexican"],"categories":["mexican-recipes","pork-carnitas","pork-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7c7db989bd1c', 'en', 'US', 'Pulled Pork Carnitas Quesadillas', 'These Quesadillas are a great make-ahead dinner because they freeze so well and don''t take long to defrost. They are made using pulled pork but you can substitute with any other cooked protein (refer to notes).', 'https://www.recipetineats.com/tachyon/2014/09/DSC_0112.jpg', 10, 20, 30, 4, '[{"id": "ing_pork", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.2, "unit": "pack of 125g"}}, {"id": "ing_tortillas", "quantity": {"value": 8.0, "unit": "pack of 8"}}, {"id": "ing_corn", "quantity": {"value": 0.188, "unit": "can of 400g"}}, {"id": "ing_capsicum", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_butter", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_balsamic_vinegar", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1 1/2 cups shredded Pork Carnitas (Mexican Pulled Pork)","1 1/2 cups shredded mozzarella cheese","8 tortillas","1/2 cup corn kernels (frozen or canned)","1/2 cup diced red capsicum (bell pepper)","1 tbsp olive oil","Salt and pepper","Fresh parsley or coriander (, finely chopped (optional garnish))"]},{"ingredients":["1 1/2 tbsp butter","2 brown onions (, halved and finely sliced)","1 1/2 tbsp brown sugar","1 tbsp balsamic vinegar","1/2 tsp salt","Black pepper"],"purpose":"Caramelized Onions"}]', '[{"title":"Caramelised Onions","description":"Melt butter in a fry pan over medium heat. Add onions and cook for 7 minutes, stirring every now and then so they cook evenly. Add remaining Caramelized Onion ingredients and cook for a further 5 minutes, stirring occasionally until sticky and caramelised. Remove from heat and set aside.","duration":7,"images":[],"step":1},{"title":"Brown Pork Carnitas (optional)","description":"Heat 1/2 tbsp oil in a fry pan over high heat. Add Pork Carnitas and press down lightly with a spatula to help crisp up. When the Pork Carnitas are heated through and the underside is golden brown and crisp (about 1 to 1/2 minutes), remove from pan (do not flip).","images":[],"step":2},{"description":"Lay out the tortillas. Divide the cheese between the tortillas, scattering evenly across half of each tortilla. Top with pork carnitas, corn, capsicum and Caramelised Onion. Season to taste with pepper and salt. (Note: Different cheeses have different levels of saltiness, so be careful not to over season.) Fold the tortillas in half.","images":[],"step":3},{"title":"To freeze","description":"Wrap each tortilla tightly in cling wrap and freeze until required. Defrost before cooking.","images":[],"step":4},{"title":"To cook","description":"Heat 1/2 tbsp olive oil in a large pan over medium high heat. Add as many quesadillas as will fit in the pan. Cook until nicely browned on the underside (about 1 1/2 minutes), then flip over the folded edge. Cook the other side until browned, then remove from pan. Tip: Keep cooked quesadillas warm in a very low oven. Keep then in spread out in a single layer so they stay crisp.","images":[],"step":5},{"description":"Serve immediately, garnished with parsley if desired.","images":[],"step":6}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Mexican"],"categories":["mexican-recipes","pork-carnitas","pork-recipes","quesadillas","slow-cooked-fall-apart"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0f74327bc69a', 'en', 'US', 'Mexican Pizzas', 'This is a great make-ahead meal that you can assemble then pop into the freezer, ready to bake for a quick meal. I like making these with flatbreads which are not only much better value (and healthier) than store bought pizza bases, but also they also bake crispier which I love!', 'https://www.recipetineats.com/tachyon/2014/09/DSC_0159.jpg', 10, 10, 20, 4, '[{"id": "ing_bread", "quantity": {"value": 5.0, "unit": "loaf"}}, {"id": "ing_enchilada_sauce", "quantity": {"value": 150.0, "unit": "bottle"}}, {"id": "ing_chicken", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 7.5, "unit": "bottle"}}, {"id": "ing_corn", "quantity": {"value": 0.188, "unit": "can of 400g"}}, {"id": "ing_capsicum", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 4.0, "unit": "bunch"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.2, "unit": "pack of 125g"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["4 large flatbreads (about 30cm /12 inches in diameter)","1 cup enchilada sauce (preferably homemade, here is my Easy Classic Enchilada Sauce)","1 1/2 cups shredded cooked Pork Carnitas ((Mexican Shredded Pork), chicken or any other protein of your choice)","1/2 tbsp oil","1/2 cup corn kernels (canned or frozen)","1/2 cup red capsicum ((Bell peppers), diced)","4 shallots / scallions (, finely sliced (or 1/2 red spanish onion, diced))","1 1/2 cups grated mozzarella cheese (or any good melting cheese)","2 tbsp fresh parsley or coriander/cilantro (, finely chopped (optional - for garnish))"]}]', '[{"description":"Preheat oven to 220C/430F. You want the oven screaming hot!","images":[],"step":1},{"title":"Optional (but not really...)","description":"Heat 1/2 tbsp of oil in a fry pan over high heat. Add pork carnitas (or whatever protein you are using) and use a spatula to press down to make the bottom golden and crispy. Do not flip. When it is golden and crispy, remove from pan and set aside.","images":[],"step":2},{"description":"Divide the enchilada sauce between each flatbread and spread evenly.","images":[],"step":3},{"description":"Top with shallots / scallions.","images":[],"step":4},{"description":"Scatter over the pork carnitas, corn kernels, capsicum then lastly the cheese.","images":[],"step":5},{"description":"Get 2 baking trays and place 2 pizzas on each.","images":[],"step":6},{"description":"Bake for 10 to 15 minutes, alternating trays halfway. The pizza is ready when the cheese is melted and starting to bubble.","duration":12.5,"images":[],"step":7},{"description":"Remove from oven, scatter with parsley or coriander (if using), then cut into wedges and serve.","images":[],"step":8}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["main_course"],"cuisine":["Mexican"],"categories":["mexican-recipes","pork-carnitas","pork-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_db4c0edf9e67', 'en', 'US', 'Mexican Pork Rolls', 'Soft white rolls piled high with shredded pork mixed with enchilada sauce, topped with gooey melted cheese and caramelized onions.', 'https://www.recipetineats.com/tachyon/2014/09/DSC_0170-Version-2.jpg', 5, 15, 20, 4, '[{"id": "ing_pork", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_enchilada_sauce", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_butter", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_balsamic_vinegar", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.4, "unit": "pack of 125g"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 1/2 cups shredded Pork Carnitas (Mexican Pulled Pork)","1/2 cup Enchilada Sauce (preferably homemade - here is my Easy Classic Enchilada Sauce)"],"purpose":"Filling"},{"ingredients":["1 1/2 tbsp butter","2 brown onions (, halved and finely sliced)","1 1/2 tbsp brown sugar","1 tbsp balsamic vinegar","1/2 tsp salt","Black pepper"],"purpose":"Caramelized Onions"},{"ingredients":["1/2 cup grated mozzarella cheese (or any other good melting cheese)","4 soft white bread rolls","Fresh parsley (, finely chopped, for garnish (optional))"],"purpose":"To Serve"}]', '[{"description":"Melt butter in a fry pan over medium heat. Add onions and cook for 7 minutes, stirring every now and then so they cook evenly. Add remaining Caramelized Onion ingredients and cook for a further 5 minutes, stirring occasionally until sticky and caramelised. Remove onion from pan and set aside.","duration":7,"images":[],"step":1},{"title":"Brown Pork Carnitas","description":"Wipe pan clean and return to stove. Heat 1/2 tbsp oil over high heat. Add Pork Carnitas and press down lightly with a spatula to help crisp up. When the Pork Carnitas are heated through and the underside is golden brown and crisp (about 1 to 1/2 minutes), remove from pan (do not flip).","images":[],"step":2},{"description":"Place Pork Carnitas and Enchilada Sauce and mix to combine.","images":[],"step":3},{"description":"Preheat grill (broiler) on high.","images":[],"step":4},{"description":"Split rolls in half. Divide the Filling between them and pile onto the bottom half of the roll. Top with cheese then grill (broil) for 3 minutes until melted.","duration":3,"images":[],"step":5},{"description":"Remove from the grill, top with caramelised onion and sprinkle with parsley (if using).","images":[],"step":6},{"description":"Sandwich with the other half of the bread roll and serve immediately.","images":[],"step":7}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["main_course"],"cuisine":["Mexican"],"categories":["mexican-recipes","pork-carnitas","pork-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9f2835c377fd', 'en', 'US', 'Pulled Pork Enchiladas', 'Using leftover Pork Carnitas (Mexican Pulled Pork) or other shredded meat, it takes a mere 15 minutes to assemble this dish to pop into the oven, making this a sensational mid week meal! Note that the Pork Carnitas used in this recipe is already seasoned and flavoured so if you substitute with an unseasoned meat then please refer to the notes for seasonings to add to the filling mixture.', 'https://www.recipetineats.com/tachyon/2014/07/Pork-Carnitas-Enchiladas-3.jpg', 15, 25, 40, 4, '[{"id": "ing_pork", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_kidney_beans", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_corn", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_tortillas", "quantity": {"value": 8.0, "unit": "pack of 8"}}, {"id": "ing_enchilada_sauce", "quantity": {"value": 450.0, "unit": "bottle"}}]', '[{"ingredients":["2 cups (packed) Pork Carnitas (Mexican Pulled Pork) or other shredded meat (see notes)","1 tbsp olive oil","1 cup tinned black beans or red kidney beans (, drained)","1 can (15oz / 400g) corn kernels (, drained)","2 cups shredded cheese (any good melting cheese)","8 tortillas","3 cups (750ml / 25oz) Enchilada Sauce (homemade or store bought)"]}]', '[{"description":"Preheat oven to 350F/180C.","images":[],"step":1},{"description":"Heat 1 tbsp olive oil in a pan over high heat. Add the pork carnitas and cook until the bottom is nicely browned - about 1 1/2 minutes. Do not turn, just make the bottom crispy (to keep the pulled pork as moist as possible), then remove the pulled pork into a bowl. It does not matter if the top isn''t heated through, it will heat in the oven.","images":[],"step":2},{"description":"Add the corn, black beans, 1/2 cup enchilada sauce and 1/2 cup cheese into the bowl and mix to combine.","images":[],"step":3},{"description":"Spread 1/2 cup of Enchilada Sauce on the bottom of the baking dish.","images":[],"step":4},{"description":"Place 1/2 packed cup of filling (from step 3) into a tortilla and roll up and place in the baking dish.","images":[],"step":5},{"description":"Pour over the remaining Enchilada Sauce, and bake for 10 minutes.","duration":10,"images":[],"step":6},{"description":"Remove from oven and scatter the cheese on, then bake for a further 10 to 15 minutes until the cheese is bubbling and golden.","images":[],"step":7},{"description":"Let stand for 5 minutes before serving.","duration":5,"images":[],"step":8}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["main_course"],"cuisine":["Mexican"],"categories":["mexican-recipes","most-popular","pork-carnitas","pork-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d1e34a1774e3', 'en', 'US', 'Salted Caramel Sauce', 'A very easy recipe for salted caramel. My "go to" that I make all the time for drizzling on ice cream, pancakes, bars and more!', 'https://www.recipetineats.com/tachyon/2014/05/Salted-Caramel-Sauce_square.jpg', 3, 10, 13, 4, '[{"id": "ing_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_vanilla", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}]', '[{"ingredients":["1 cup caster sugar","1/2 cup water","3/4 cup heavy whipping cream","1 tsp vanilla","1/4 tsp salt"]}]', '[{"description":"Combine sugar and water in saucepan over medium heat.","images":[],"step":1},{"description":"Bring to rolling boil, stirring to help dissolve the sugar.","images":[],"step":2},{"description":"Boil for 5 to 8 minutes, until it turns a golden brown.","duration":6.5,"images":[],"step":3},{"description":"Pour in the cream, whisking constantly. Be careful, as the caramel is hot and it will foam.","images":[],"step":4},{"description":"Once the cream is combined, remove from heat and whisk in the salt and vanilla.","images":[],"step":5},{"description":"The caramel will seem thin. It thickens alot as it cools.","images":[],"step":6}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["dessert-recipes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cc54037eb58c', 'en', 'US', 'Mushroom Gravy (easy, from scratch, no drippings required)', 'Recipe video above. Mushroom gravy is excellent served over steak or chicken. Though ask an Aussie and they''ll tell you the best use is over a schnitzel – preferably with rosti, though mash rates highly too!Gravy colour note: The deepness and richness of colour will depending on the beef stock you use. Generally speaking, a better stock will have deeper colour = darker (nicer!) -looking gravy.Makes: 3 cups (freezes perfectly too!)', 'https://www.recipetineats.com/tachyon/2021/03/Mushroom-Gravy_7-copy.jpg', 10, 15, 25, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 45.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 2.5, "unit": "pack of 3 heads"}}, {"id": "ing_mushroom", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.5, "unit": "L"}}]', '[{"ingredients":["1 tbsp olive oil","45g / 3 tbsp butter (, unsalted)","1 1/2 tsp garlic (, finely minced (~1 large or 2 medium cloves))","400g / 14oz mushrooms (, sliced 3mm / ⅛\" thick (white/button or Swiss/Cremini))","1/4 tsp salt","1/8 tsp black pepper"],"purpose":"Mushrooms:"},{"ingredients":["30g / 2 tbsp butter (, unsalted)","4 tbsp flour (, plain / all-purpose)","2 cups beef stock / broth","1/4 tsp black pepper","Salt (, to taste)"],"purpose":"Gravy:"}]', '[{"description":"Cook mushrooms:","images":[],"step":1},{"description":"Heat the olive oil in a large skillet over medium-high heat, then add butter and let it melt.","images":[],"step":2},{"title":"Cook half mushrooms","description":"Add half the mushrooms and cook for 2 mins. Add half the salt and pepper, then continue to cook for another 2 mins until most mushrooms are becoming golden. Then add half the garlic and cook until mushrooms are fully golden, and remove to a plate.","duration":2,"images":[],"step":3},{"title":"Cook remaining mushrooms","description":"Melt remaining butter, then cook remaining mushrooms per above (adding salt & pepper partway through, and garlic towards the end). Remove to a plate.","images":[],"step":4},{"description":"Lower heat to medium. In the same skillet, melt the butter.","images":[],"step":5},{"description":"Add flour and stir continuously for 1 1/2 minutes so the roux doesn''t burn. Don''t worry if the mixture is a bit dry and sandy, it depends how much fat is left from the mushrooms.","images":[],"step":6},{"description":"While stirring, slowly pour in the beef stock. This should avoid lumps in the gravy. If there are lumps, just whisk vigorously to dissolve them.","images":[],"step":7},{"description":"Cook for 3 to 4 minutes, or until it thickens to a thin-syrup consistency. Stir every now and then at first, then more regularly as the gravy thickens so it doesn''t burn on the base of the skillet.","duration":3.5,"images":[],"step":8},{"description":"Stir in cooked mushrooms, cook for a further 1 minute. Taste and add more salt if needed (if using unsalted homemade stock, you will need more).","images":[],"step":9},{"description":"Pour into a gravy jug and serve with everything! It''s particularly great and very Aussie poured over schnitzel with a side of rosti or chips! Otherwise serve with steak, simple pan-seared chops or chicken, sprinkled with salt and pepper before cooking.","images":[],"step":10}]', '["gluten","milk"]', '["keto_friendly","low_calorie"]', '{"mealType":["main_course"],"cuisine":["European","Western"],"categories":["mushroom-recipes","sauces"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cdde56200e9e', 'en', 'US', 'Mushroom Risotto', 'Recipe video above. Creamy, comforting Mushroom Risotto fully loaded with garlicky, buttery mushrooms stirred through the risotto AND piled on top. Mouthwateringly delicious, cosy food that''s elegant enough to serve at a dinner party. It takes time to make mushrooms golden brown, but it''s worth every minute - it''s amazing!!', 'https://www.recipetineats.com/tachyon/2019/10/Mushroom-Risotto_7.jpg', 15, 35, 50, 4, '[{"id": "ing_mushroom", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_wine", "quantity": {"value": 0.083, "unit": "bottle of 750ml"}}, {"id": "ing_arborio_rice", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}]', '[{"ingredients":["500g (1 lb) mushrooms (, sliced 3 mm / 1/8\" thick (Note 1))","250g (1/2 lb) mushrooms (, quartered (Note 1))","3 tbsp butter","2 tbsp olive oil","2 garlic cloves (, minced)","1/2 tsp salt and pepper (, each)"],"purpose":"Mushrooms:"},{"ingredients":["1 tbsp butter","1 garlic clove (, minced)","2 eschallots / French onions (, finely chopped (or 1/2 onion))","1/4 cup dry white wine (Note 2)","1 1/4 cups arborio rice (, uncooked)","5 cups chicken broth/stock (, low sodium, warm (Note 3))"],"purpose":"Risotto:"},{"ingredients":["1/2 cup cream (, optional but recommended(Note 4))","2 tbsp (30g) butter (, optional (Note 4))","1/2 cup parmesan cheese (, finely grated)","1/2 tsp salt and pepper (, each)"],"purpose":"Finishes:"},{"ingredients":["Finely chopped parsley or chives","Parmesan (, freshly grated)"],"purpose":"Serving:"}]', '[{"description":"Garlic Butter Mushrooms","images":[],"step":1},{"description":"Add 1 tbsp oil and half the butter in a large heavy based pot over high heat (Note 5). Once melted, add half the mushrooms and cook until pretty golden brown (~4 min).","images":[],"step":2},{"description":"Add 1/2 the garlic, 1/4 tsp each salt and pepper, then continue to cook until golden brown (~1.5 min). Then remove into bowl.","images":[],"step":3},{"description":"Repeat with remaining mushrooms, then remove.","images":[],"step":4},{"description":"Turn heat down to medium. In the same pot, melt butter then add garlic and onion.","images":[],"step":5},{"description":"Cook 2 minutes until onion is translucent but not golden.","images":[],"step":6},{"description":"Add wine and allow to simmer rapidly for 2 minutes, scraping the base of the pot, until mostly evaporated.","duration":2,"images":[],"step":7},{"description":"Add rice and stir for 1 minute until semi translucent.","duration":1,"images":[],"step":8},{"description":"Add about 1.5 cups of stock. Stir, then leave for 3 minutes, stirring just a few times, until mostly absorbed (~3 min).","duration":3,"images":[],"step":9},{"description":"Add about 1.5 cups stock, stir every now and then until mostly absorbed (~3 min) - no need to stir constantly. Repeat twice more until all stock used up, rice is just cooked but risotto still creamy and sloppy (~10 min, Note 6).","images":[],"step":10},{"description":"Add cream and butter, stir vigorously to make creamy.","images":[],"step":11},{"description":"Stir in parmesan, salt and pepper.","images":[],"step":12},{"description":"Stir through half the mushrooms, then taste and add more salt and pepper if needed. Consistency should be creamy, not stodgy (Note 7).","images":[],"step":13},{"description":"Reheat remaining mushrooms (I microwave).","images":[],"step":14},{"description":"Spoon risotto into bowls, then top with reserved mushrooms (including a drizzle of buttery juices pooled in bowl!)","images":[],"step":15},{"description":"Garnish with parsley if using, and extra parmesan. Serve immediately!","images":[],"step":16}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner","snack"],"cuisine":["American-Italian","Italian","Western"],"categories":["mushroom-recipes","pasta-recipes","rice-recipes","rice-side-dishes","risotto-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_49fac396f5a9', 'en', 'US', 'Creamy Mushroom Pasta', 'Recipe video above. It''s your creamy pasta dream come true...loaded with golden buttery garlicky mushrooms! SCALING UP (slide scaler): Cook mushroom in batches, otherwise they''ll steam instead of going golden.', 'https://www.recipetineats.com/tachyon/2019/09/Creamy-Mushroom-Pasta_4.jpg', 8, 12, 20, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.32, "unit": "pack of 500g"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_mushroom", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_chicken", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["160g/ 6oz fettuccine ( or linguine (Note 1))","2 tbsp (30g) unsalted butter","1/2 tbsp olive oil (Note 2)","300g/ 10 oz mushrooms (, sliced 1/3 cm / 1/8\" thick (white, cremini/swiss brown))","2 garlic cloves (, finely chopped)","1/2 cup (125 ml) white wine (, dry (or rose, sub more broth))","1/2 cup (125ml) chicken broth/stock (, low sodium (or veg))","3/4 cup (185ml) cream (, heavy / thickened (Note 3))","1/3 cup (30g) parmesan (, finely grated (Note 4))","1/2 tsp salt and pepper (, each)"]},{"ingredients":["Extra parmesan (, for serving)","Parsley (, roughly chopped (optional))"],"purpose":"Serving:"}]', '[{"description":"Cook pasta in salted water for 1 minute less than time per packet (start this mid mushroom cook). Just before draining, scoop out 1 cup cooking water, then drain.","duration":1,"images":[],"step":1},{"description":"Melt butter and heat oil in a large skillet over high heat.","images":[],"step":2},{"description":"Add mushrooms and cook, stirring regularly. When they start to sweat, add a pinch of salt and pepper.","images":[],"step":3},{"title":"When pretty golden (about 4","description":"5 minutes), add garlic and cook until garlic is golden and mushroom is golden.","images":[],"step":4},{"description":"Stand back and add wine (it will be steamy!!), stir, scraping the bottom of the skillet. Simmer rapidly until wine is mostly evaporated and winey smell is gone.","images":[],"step":5},{"description":"Add broth, cream, parmesan, salt and pepper. Stir to dissolve parmesan and simmer for 2 minutes, stirring regularly.","duration":2,"images":[],"step":6},{"title":"Transfer pasta into sauce, toss for 1","description":"2 minutes until sauce thickens and coats pasta. If sauce gets too thick (rather than slick, see video), add a splash of reserved pasta cooking water.","duration":1.5,"images":[],"step":7},{"description":"Garnish with parsley and serve immediately with extra parmesan!","images":[],"step":8}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","mushroom-recipes","pasta-recipes","quick-and-easy","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a6465a8b5a3d', 'en', 'US', 'Panna Cotta', 'Recipe video above. There''s no reason to fear Panna Cotta! Turning it out is a breeze if you give the moulds a light oil spritz. As for the signature wobble? Just use the right gelatine to liquid ratio. It''s not hard - it''s listed in the recipe!Note: Most Panna Cottas are quite flat. I like mine taller so I use an assortment of vessels as moulds - pudding moulds, tea cups, small coffee cups - anything that''s taller than wider (so not ramekins), you lose about 30-40% of height when unmoulded.See Note 5 if you are not un-moulding, the recipe is even easier!', 'https://www.recipetineats.com/tachyon/2025/09/Panna-cotta_8-close-up.jpg', 10, 5, 15, 6, '[{"id": "ing_elatine_powder", "quantity": {"value": 12.5, "unit": "jar"}}, {"id": "ing_milk", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_vanilla_bean_paste_with_seeds_or_1_vanilla_bean_pod", "quantity": {"value": 7.5, "unit": "jar"}}, {"id": "ing_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 1.25, "unit": "carton of 250ml"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_raspberries", "quantity": {"value": 1.0, "unit": "punnet of 125g"}}, {"id": "ing_pineapple", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_raspberries", "quantity": {"value": 250.0, "unit": "punnet of 125g"}}, {"id": "ing_sugar", "quantity": {"value": 0.037, "unit": "kg"}}]', '[{"ingredients":["2 1/2 tsp gelatine powder (, unflavoured - can reduce to 2 1/4 tsp if not un-moulding (Note 1))","1/2 cup milk (, full fat)"],"purpose":"Bloom gelatine:"},{"ingredients":["1 cup milk (, full fat)","1 1/2 tsp vanilla bean paste with seeds (substitute vanilla extract) OR 1 vanilla bean pod (see Note 6 for extra steps)","1/4 cup caster sugar (superfine sugar)","1 pinch cooking salt / kosher salt","1 1/4 cups heavy or thickened cream (, or whipping cream (un-whipped), not dolloping cream)","Oil spray (, neutral flavour (eg canola, not olive oil))"],"purpose":"Panna Cotta:"},{"ingredients":["Pictured - Raspberry coulis (below), chopped pistachios, mint, raspberries","Other ideas - Fresh berries, shaved chocolate, fruit compote, passionfruit pulp, citrus slices, finely chopped mango or pineapple (,)"],"purpose":"Decoration options"},{"ingredients":["250g / 8 oz raspberries (, fresh or frozen (no need to thaw))","3 tbsp white sugar"],"purpose":"Raspberry coulis option (optional)"}]', '[{"description":"Bloom gelatine in saucepan 5 min, warm to melt. Add sugar, milk, vanilla and salt, once milk is warm, cool 10 min. Add cream, fridge 1 hr (stir), then pour into lightly oiled moulds. Fridge 6 hrs+, invert!","images":[],"step":1},{"title":"Bloom gelatine","description":"Pour the 1/2 cup of milk in a small saucepan, sprinkle the gelatine across the surface then whisk in. Leave for 5 minutes - the gelatine will swell and look curdled.","duration":5,"images":[],"step":2},{"title":"Melt","description":"Gently warm the gelatine mixture on medium low heat and stir until it melts and looks like lump-free milk again. Don''t let it simmer.","images":[],"step":3},{"title":"Vanilla infused","description":"Add the milk, sugar, vanilla bean paste and pinch of salt. Heat just to let the milk warm and stir gently to dissolve the sugar. Don''t let the milk simmer or even get steamy or frothy, just gently warm.(Note 2) Once the sugar is dissolved, remove from the heat and leave for 10 minutes to let the vanilla flavour to infuse.","duration":10,"images":[],"step":4},{"title":"Add cream","description":"Stir in cream. Pour into a large jug or bowl, clear glass is best (so you can check for seed sinking later).","images":[],"step":5},{"title":"Cool to thicken slightly","description":"Refrigerate uncovered for 1 hour, stirring at the 30 minute and 45 minute mark, scraping along the sides (in case it starts to set). See Note 3 for why this step is important!","images":[],"step":6},{"title":"Check thickness","description":"After 1 hour, the mixture should be a pouring cream consistency. Stir, leave for 15 seconds then check the underside to ensure the vanilla beans aren''t settling back on the base.(SOS: If you left it too long in the fridge and it sets, you can always gently re-melt in the microwave or stove and start again. Only make it warm, gelatine melts at a very low temp.)","duration":0.25,"images":[],"step":7},{"title":"Oil and fill moulds","description":"Lightly oil spray 6 moulds (about 2/3 cup / 160ml each), then lightly wipe out excess. Divide mixture between moulds (if you spy lumps, strain).","images":[],"step":8},{"description":"Refrigerate at least 6 hours, preferably overnight. (If not un-moulding, 4 hours is enough).","images":[],"step":9},{"title":"Run knife around rim","description":"Remove the Panna Cotta from the fridge. Run the tip of a small knife around the edge of the surface.","images":[],"step":10},{"title":"Remove","description":"Invert mould onto a plate. Grip the plate and mould with both hands and give it an assertive shake to loosen the Panna Cotta (it might take a few goes). You''ll hear and feel it \"plop\" out! (Note 4 for troubleshooting).","images":[],"step":11},{"title":"Serving","description":"It''s so silky and creamy, it''s delicious plain though nice to pop a few berries for colour on top. To decorate as pictured, spoon raspberry coulis onto the top and coax some drips down the sides (if you want). Sprinkle with pistachios, top with a raspberry, tuck in a mint sprig. Serve! (Also see in post for more decorating ideas).","images":[],"step":12},{"description":"Raspberry coulis","images":[],"step":13},{"description":"Put ingredients in a small saucepan over medium heat. Once the raspberry juices start simmering, simmer for 5 minutes, mashing the raspberries as you go. Blitz with a stick blender tilt saucepan to submerge the head, else transfer into a jug), strain through a fine sieve to remove seeds. Cool completely before using, it thickens as it cools. To loosen if needed, add water 1 teaspoon at a time and mix thoroughly.","duration":5,"images":[],"step":14}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Italian"],"categories":["dessert-recipes","no-bake-sweet-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4f11597f213f', 'en', 'US', 'Green Ginger Rice Noodles', 'Recipe video above. Rice noodles tossed in a ginger-forward, "Asian-pesto" sauce that’s based on Hainanese Chicken’s Ginger Shallot Sauce. Crazy good, fast, and it even turns the noodles green which I’m weirdly obsessed with. I threw in some shredded chicken for protein to make it a meal. Cucumber would be so great to make this a refreshing side dish (deseeded, batons or thin half-moons).Serve it warm or cold. It’s a total win for hot days, lunch boxes, or whenever you’re doing an Asian-ish spread. I see myself making this A LOT this summer!', 'https://www.recipetineats.com/tachyon/2025/11/Green-ginger-noodles_4.jpg', 15, 0, 15, 4, '[{"id": "ing_chicken", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_rice_noodles", "quantity": {"value": 0.08, "unit": "pack of 375g"}}, {"id": "ing_green_onion", "quantity": {"value": 12.0, "unit": "bunch"}}, {"id": "ing_ginger", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 50.0, "unit": "bottle"}}, {"id": "ing_sriracha", "quantity": {"value": 1.0, "unit": "bottle of 400ml"}}, {"id": "ing_green_onion", "quantity": {"value": 12.0, "unit": "bunch"}}]', '[{"ingredients":["350g / 3 cups shredded cooked chicken (I use my foolproof poached chicken)","350g / 3 cups shredded cooked chicken (I use my foolproof poached chicken)"]},{"ingredients":["4 cups (lightly packed) green onion (, cut into ~1.25cm / 1/2\" pieces (5 - 6 BIG stems!))","1/4 cup roughly chopped ginger (, ~ 4mm / 1/6\" pieces)","2 garlic cloves (, roughly chopped)","2 tbsp rice vinegar","2 tbsp water","2 tbsp light soy sauce (, or all-purpose soy sauce (not dark soy sauce - Note 2))","1 tsp cooking salt / kosher salt (halve for table salt, +50% for flakes)","1/4 tsp white pepper (, or black)","1/3 cup grapeseed oil (, or other neutral flavoured oil (vegetable, canola etc))"],"purpose":"Ginger shallot sauce (Note 3)"},{"ingredients":["Sriracha - use as much as you dare!","1/4 cup crispy shallots (store bought)"],"purpose":"For serving:"}]', '[{"description":"Blitz (pulsing) 1/4 of the green onion with ginger, garlic, vinegar and water until ginger is pureed. Then blitz in remaining green onion and soy until pesto-like. Stir in oil and salt, set aside 10 minutes. Toss with noodles and chicken, serve with crispy shallots and sriracha!","images":[],"step":1},{"description":"Ginger shallot sauce first:","images":[],"step":2},{"title":"Blitz","description":"Put 1/4 of the green onions in a tall jug (or deep bowl), top with the ginger, garlic, vinegar and water. Blitz with a stick blender until the ginger and garlic is pureed (~ 15 seconds). Add the remaining green onions and soy sauce. Blitz until all the green onion is finely chopped but don''t let it become green smoothie, it should be a pesto-like consistency. Asian pesto! :) (Note 4 if you don''t have a stick blender)","images":[],"step":3},{"title":"Stir and set aside","description":"Stir in the oil, salt and pepper. Then set aside for 10 minutes to let the flavours meld while you rehydrate the noodles.","duration":10,"images":[],"step":4},{"description":"Toss and eat!","images":[],"step":5},{"description":"Toss the noodles with the Green Ginger Sauce first. Toss well so it coats the noodles nicely. Then add the chicken, toss well again. (If you add chicken first, too much sauce clings to it). Loosen with a touch of water if needed.","images":[],"step":6},{"title":"Warm or cold serving","description":"If serving the noodles cold, set aside for 15 minutes+ to let the noodles cool. The flavours will continue to develop. If serving warm, serve straight away.","duration":15,"images":[],"step":7},{"title":"Serve","description":"Divide between bowls, drizzled with sriracha, sprinkle with crispy shallots, eat!","images":[],"step":8}]', '["gluten","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["no-cook-food","noodles","quick-and-easy","summer"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cd8b34b32222', 'en', 'US', 'Italian Orzo Salad (Risoni) with Crispy Salami Bits', 'Recipe video above. The crispy salami bits are the hero here. The better bacon. Why aren''t we putting crispy salami in everything??!Tossed through a risoni/orzo salad inspired by my favourite Mega Italian Salad with lots of fresh vegetables and a good handful of cheese to keep things tasty. Excellent packed lunch, keeps well for days, love that you can eat it with a spoon. Serves 4 - 5 as a meal. Make this today, find another pasta salad for next week here!', 'https://www.recipetineats.com/tachyon/2023/07/Italian-risoni-orzo-salad_3.jpg', 15, 15, 30, 5, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_salami", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_kalamata_olives", "quantity": {"value": 150.0, "unit": "bottle"}}, {"id": "ing_tightly_packed_baby_rocket_arugula", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.6, "unit": "punnet of 250g"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_basil", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.013, "unit": "pack of 100g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}]', '[{"ingredients":["250g / 8oz risoni / orzo pasta ( - 1 1/4 cups (Note 1))","2 tsp salt (, for cooking pasta)","2 tsp extra virgin olive oil"]},{"ingredients":["250g/ 8 oz salami slices (, chopped into 1.25 cm / 1/2\" squares (Note 2))","1 cup sliced kalamata olives (1 x 220g/7oz jar) - or other olives or briny things (Note 4)","2 tightly packed cups baby rocket / arugula (, torn by hand)","400g/ 14oz cherry tomatoes (, quartered (2 1/2 cups))","1 large green capsicum (, cut into 1.25cm / 1/2\" squares)","1/2 red onion (, finely diced)","1 1/2 cups (tightly packed) colby cheese (, shredded into short strands (Note 5))"],"purpose":"Salad add-ins (Note 2):"},{"ingredients":["1/3 cup extra virgin olive oil","3 tbsp red wine vinegar (or white wine vinegar, sub apple cider vinegar)","1 garlic clove (, crushed using garlic press or grated using microplane)","1 tsp dried basil","1/4 tsp red chilli flakes (optional)","1 tsp dried oregano","1/2 tsp sugar","1 tsp cooking/kosher salt"],"purpose":"Italian dressing:"}]', '[{"title":"Cook pasta","description":"Bring a large pot of water to the boil. Add salt and risoni/orzo, then cook per packet directions (usually ~10 minutes). Drain in colander, rinse, shake off excess water well. Transfer to large bowl. Toss with the olive oil then let cool.","images":[],"step":1},{"title":"Dressing","description":"Shake in a jar.","images":[],"step":2},{"title":"Crispy salami","description":"Put salami in cold large non-stick pan, with no oil. Turn onto medium high - as the pan heats up, the fat will melt so it cooks in its own fat. Cook for 3 - 5 minutes, stirring regularly, until light golden. Drain on paper towels. It will crisp as it cools.","duration":4,"images":[],"step":3},{"title":"Toss","description":"Set aside 1/3 of the salami for topping. Put all remaining salad ingredients in with the risoni. Toss. Pour over dressing. Toss, toss, toss!","images":[],"step":4},{"description":"Serve! Tumble into serving bowl. Sprinkle with remaining salami. Divide between bowls. Eat with spoon! Best eaten at room temp, not fridge cold (can taste flavours better).","images":[],"step":5}]', '["gluten","milk"]', '[]', '{"mealType":["lunch","dinner"],"cuisine":["Western"],"categories":["no-cook-food","pasta-recipes","pasta-salads-and-rice-salads","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_dfecc1db1a8c', 'en', 'US', 'Smoked Sausage and Rice - easy one pot dinner!', 'Recipe video above. The smoked sausage is the trick here to get great flavour into this quick one pot dinner. Tastes like Jambalaya, minus the cajun flavours, and much faster to make. Everybody loves this!I used kransky sausages but you can use any smoked sausages you want, including chorizo. You can even use raw sausages - see Note 1! Also feel free to use other vegetables - anything that can hold up to 20 minutes on the stove.', 'https://www.recipetineats.com/tachyon/2021/08/One-Pot-Sausage-and-Rice_74.jpg', 10, 30, 40, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_sausages", "quantity": {"value": 0.8, "unit": "pack of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_white_rice", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.625, "unit": "L"}}, {"id": "ing_frozen_peas", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["3 tbsp extra virgin olive oil","5 garlic cloves (, finely minced)","2 onions (medium), chopped (or 1 large)","1 yellow capsicum (, cut into 1.5cm / 1\" squares)","1 red capsicum (, cut into 1.5cm / 1\" squares)","400 g/ 14oz (~3) kransky or other smoked sausages (, sliced 0.5cm thick / 1/4\" thick)","3/4 tsp salt","1/2 tsp pepper","3/4 tsp smoked paprika (sub normal paprika)","1 1/2 cup long grain white rice (, uncooked (Note 2 other rices))","2 1/2 cups chicken stock/broth (, low sodium (or veg stock))","2 cups frozen peas (, thawed)","2 tbsp parsley (, chopped (optional))"]}]', '[{"title":"Cook sausage","description":"Heat 2 tbsp oil in a large heavy based pot over medium high heat. Add sausages and cook until golden. Remove with a slotted spoon.","images":[],"step":1},{"title":"Cook onion and garlic","description":"Add remaining 1 tbsp oil. Add garlic and onion, cook for 2 minutes. Add capsicum and cook for 2 minutes until onion is translucent.","duration":2,"images":[],"step":2},{"title":"Add rice and liquid","description":"Add rice, chicken stock, paprika, salt, pepper and the sausage. Stir, bring to boil, then reduce heat to low so it''s simmering very gently.","images":[],"step":3},{"title":"Cover and cook","description":"Cover with lid, cook 20 minutes.","images":[],"step":4},{"title":"Add peas and rest","description":"Remove pot from stove. Working quickly, remove lid, add peas, then quickly put the lid back on. Rest 10 minutes - the residual heat with cook the peas.","images":[],"step":5},{"title":"Fluff and serve","description":"Add parsley. Use a fork to fluff the rice. Serve immediately!","images":[],"step":6}]', '[]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["one-pot-recipes","quick-and-easy","rice-recipes","rice-side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_76ee601a8aed', 'en', 'US', 'Nagi''s Big, Easy Pasta Salad', 'Recipe video above. This is the big-batch pasta salad I make when I''m short on time. The trick that puts this into guest-serving territory is to toss the hot, freshly cooked pasta in the dressing. You will be shocked how much flavour it absorbs!Do this, and it''s delicious no matter what you add in. My combination is the bare minimum that delivers everything I seek in a pasta salad. There''s no need to add a gazillion ingredients!Workflow - Chop the veg and make the dressing while the pasta is cooking. This will cut down active cook/prep time to 15 minutes.', 'https://www.recipetineats.com/tachyon/2024/08/Big-easy-pasta-salad_2.jpg', 10, 15, 65, 6, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_tomato", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_kalamata_olives", "quantity": {"value": 50.0, "unit": "bottle"}}, {"id": "ing_feta_cheese", "quantity": {"value": 200.0, "unit": "block of 200g"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.167, "unit": "bottle of 500ml"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_honey", "quantity": {"value": 0.02, "unit": "jar of 500g"}}, {"id": "ing_italian_herb_mix", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["500g/ 1 lb bow tie pasta (farfalle) (, or other short/medium pasta (Note 1))"]},{"ingredients":["2 cucumbers (, halved lengthways and finely sliced (~17cm/7\" long, sliced 2mm / 1/16\", I use a mandolin))","3 cups (500g) cherry or grape tomatoes (, halved (or chop 4 regular tomatoes))","1/3 cup roughly chopped Kalamata olives (3/4 cup whole pitted or 1/2 cup sliced, then chop)","200g/ 7oz Greek feta (, cut into 6mm / 1/4\" batons (they will crumble a bit, this is good))","1 packed cup basil leaves (, torn by hand (Note 2 for alternatives))"],"purpose":"Add-ins (7 cups \"anything\" – Note 2)"},{"ingredients":["1/2 cup extra virgin olive oil","1/3 cup apple cider vinegar (Note 3)","2 garlic cloves (, minced using garlic press or very finely minced using a knife)","2 tsp dijon mustard (can omit)","2 tsp honey (sub maple syrup or 1 tsp sugar, Note 4)","1 1/2 tsp Italian herbs mix (Note 5)","3/4 tsp cooking salt / kosher salt","1/4 tsp black pepper"],"purpose":"Dressing"}]', '[{"description":"Summary directions","images":[],"step":1},{"description":"Cook pasta until soft, toss with 2/3 Dressing, cool. Toss with everything else except basil, then add basil. Serve!","images":[],"step":2},{"description":"Full directions","images":[],"step":3},{"title":"Dressing","description":"Shake the Dressing ingredients in a large jar. It should be sharp, the flavour mellows once tossed.","images":[],"step":4},{"title":"Cook pasta until soft","description":"Bring a large pot of salted water to the boil. Cook the pasta until it is very soft, about 2 - 3 minutes longer than the time on the packet but taste to check because packet directions have been known to lie! Pasta firms up when it''s cold (nobody likes hard, cold pasta!), so cook the pasta until extra soft.","images":[],"step":5},{"title":"Flavour soak","description":"Drain the pasta very well, shaking off excess water. Transfer into a large bowl. Give the Dressing a good shake then pour over about two-thirds. Toss well, then leave the pasta to soak up the dressing as it cools (~40 minutes).","images":[],"step":6},{"title":"Toss","description":"Add the tomato, cucumber, feta and olives. Pour over the remaining Dressing. Toss well. Add basil, toss again.","images":[],"step":7},{"title":"Serve","description":"Tumble into big serving bowl. Dig in!","images":[],"step":8}]', '["gluten","mustard"]', '["vegetarian"]', '{"mealType":["lunch","dinner"],"cuisine":["Western"],"categories":["pasta-recipes","pasta-salads-and-rice-salads","quick-and-easy","summer","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a3a487f89354', 'en', 'US', 'Pasta Primavera', 'Recipe video above. This is the Pasta Primavera recipe made famous by Le Cirque restaurant in NYC. It was first published in a magazine in the 1970''s! This is an excellent big creamy pasta fix with less guilt thanks to a ton of vegetables. The trick here is timing so that all the vegetables finish cooking to tender-crisp perfection at the same time. Don''t skip the pine nuts. It''s the signature finishing touch.Counting calories? See note 1 on how to lighten the dish.', 'https://www.recipetineats.com/tachyon/2022/10/Pasta-Primavera-recipe_9.jpg', 15, 20, 35, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.6, "unit": "pack of 500g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_zucchini", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_broccoli", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_snow_peas", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_asparagus", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_peas", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 10.0, "unit": "punnet of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 5.0, "unit": "block of 250g"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.6, "unit": "pack of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_basil", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_pinenuts", "quantity": {"value": 30.0, "unit": "jar"}}]', '[{"ingredients":["300g / 10 oz linguine (fettucine, or other long and flat pasta, Note 1)"]},{"ingredients":["150g / 5oz white mushrooms (, sliced 0.4cm / 1/6\" thick (~8 pieces))","1/2 large zucchini (, cut into 0.5cm / 0.2\" rounds (100g/4 oz piece))","1 bunch broccolini","1 1/2 cup snow peas (~10 pieces, 75g/2.5oz)","1 bunch green asparagus (~8 to 10)","1 cup green peas (, defrosted)","10 cherry tomatoes (, cut in half)","2 garlic cloves (, finely minced)"],"purpose":"Vegetables (Note 2):"},{"ingredients":["5 tbsp / 75 g unsalted butter","1 cup thickened / heavy cream (Note 3)","1/2 cup Parmigiano reggiano (, finely grated (sub regular parmesan, Note 4))"],"purpose":"Cream sauce:"},{"ingredients":["3 tbsp extra virgin olive oil","1/3 cup pasta cooking water (, scoop out just before draining (Note 6))","1 tsp cooking/kosher salt","1/4 tsp black pepper","1/2 cup fresh basil leaves (, finely sliced (Note 5))","2 tbsp pinenuts (, toasted (Note 7))"],"purpose":"Cooking:"}]', '[{"description":"Cut vegetables:","images":[],"step":1},{"title":"Broccolini","description":"Cut off florets then cut in half lengthwise. Then slice the stems diagonally into 2.5 cm / 1\" lengths.","images":[],"step":2},{"title":"Snow peas","description":"Remove the tough string running down the \"seam\" of the pea. Stack several peas and slice on the diagonal about 1cm / 0.4\" wide.","images":[],"step":3},{"title":"Asparagus","description":"Snap the base off the asparagus, it will naturally break where the woody stem stars. Cut tips off, leave whole and set aside. Slice the stems diagonally into 2.5 cm / 1\" lengths.","images":[],"step":4},{"description":"Melt butter in a saucepan over medium-high heat. Add cream and Parmigiano reggiano. Stir, and once the cream starts simmering gently, stir until the cheese melts then take it off the stove and set aside.","images":[],"step":5},{"description":"Bring a large pot of water to the boil over high heat. Add 1 tablespoon of salt and add the pasta. Cook for the time per the packet minus 1 minute. Meanwhile, cook vegetables.","images":[],"step":6},{"title":"Reserve pasta water","description":"Just before draining the pasta, scoop out a mug of pasta cooking water and set aside. Drain the pasta.","images":[],"step":7},{"description":"Cook:","images":[],"step":8},{"title":"Mushrooms","description":"Heat half the olive oil in a large skillet over high heat. Cook mushrooms for 4 minutes until golden, remove to a plate.","duration":4,"images":[],"step":9},{"title":"Veg","description":"Heat remaining oil in the same skillet. Cook broccolini, snow peas and asparagus for 2 minutes. Add zucchini, tomato, green peas, garlic, salt and pepper. Cook for a further 3 minutes. Add mushroom back in, toss, then remove from heat.","duration":2,"images":[],"step":10},{"description":"Toss! Return pasta into the now-empty pot. Add vegetables, cream sauce and 1/3 cup pasta water. Toss over medium heat using 2 wooden spoons until the sauce thickens and clings to the pasta strands rather than pooling in the base of the pot, about 1 to 2 minutes. (If at any stage the pasta gets too thick, add a splash more pasta water and toss on stove).","images":[],"step":11},{"title":"Basil & pine nuts","description":"Quickly toss through basil. Divide between 4 bowls. Sprinkle with pine nuts. Devour immediately!","images":[],"step":12}]', '["gluten","milk"]', '["high_protein","vegetarian"]', '{"mealType":["dinner"],"cuisine":["American-Italian"],"categories":["pasta-recipes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d5ee74355d38', 'en', 'US', 'Orecchiette Sausage Pasta in Creamy Tomato Sauce', 'Recipe video above. Orecchiette has one big thing going for it that other pastas do not: its cup shape makes it the perfect vehicle to hold special pasta sauces. The creamy tomato sausage pasta sauce featured in this recipe is orecchiette worthy. Decadent? Yes. Have salad tomorrow!', 'https://www.recipetineats.com/tachyon/2020/06/Orecchiette-Sausage-in-Creamy-Tomato-Sauce_5.jpg', 10, 15, 25, 5, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.8, "unit": "pack of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_sausages", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_wine", "quantity": {"value": 0.083, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_milk", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}, {"id": "ing_italian_herbs", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_kale", "quantity": {"value": 3.0, "unit": "unit"}}]', '[{"ingredients":["400g / 14oz orecchiette pasta (or other pasta)","1 tbsp olive oil","2 garlic cloves (, minced)","500g / 1lb Italian pork sausages (, meat squeezed out of their casings (see video, Note 1))","1/4 cup white wine (, anything not too sweet (sub water))","1 cup tomato passata (called \"tomato puree\" in US, Note 2)","3/4 cup cream (, heavy/thickened)","3/4 cup milk (any fat %)","1/3 cup parmesan (, finely grated)","1 tsp Italian herbs (Note 3)","1/4 tsp red pepper flakes (chilli flakes)","1/4 tsp each salt and pepper","3 cups (packed) kale leaves (, torn into bite size pieces (or baby spinach, swiss chard, Tuscan kale etc))","Parmesan (, for serving)"]}]', '[{"description":"Bring a large pot of water to the boil and cook pasta according to packet directions MINUS 1 minute. Just before draining, scoop out 1 cup of pasta cooking water and set aside. (Note 4)","images":[],"step":1},{"description":"Heat oil in a very large skillet over high heat. Add garlic and cook for 15 seconds.","duration":0.25,"images":[],"step":2},{"description":"Add sausage meat and cook, breaking it up as you go, until there are some little golden bits - about 4 minutes.","images":[],"step":3},{"description":"Add wine and cook, scraping the bottom of the skillet to remove the golden bits, and allow wine to evaporate - the winey smell will disappear.","images":[],"step":4},{"description":"Add remaining ingredients except kale. Stir well, bring to simmer then turn stove down to low and simmer gently for 2 minutes to bring all the flavours together.","duration":2,"images":[],"step":5},{"description":"Add pasta and kale. Toss well for 1 minute to coat pasta well with the sauce - it will thicken. If the sauce gets too thick, use the reserved pasta cooking water to loosen it up (Note 4).","duration":1,"images":[],"step":6},{"description":"Serve immediately, garnished with freshly grated parmesan","images":[],"step":7}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian-esque","Western"],"categories":["pasta-recipes","quick-and-easy","sausage-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_26c48806a359', 'en', 'US', 'Bruschetta summer pasta salad', 'Recipe video above. This is everything you want when it''s too hot to cook! Quick, nearly no cook (just boil pasta) and full of bright, fresh, bruschetta-inspired tomato flavours.Workflow - Get the water boiling. While pasta is cooking, make dressing and chop tomatoes.', 'https://www.recipetineats.com/tachyon/2025/01/Bruschetta-pasta-salad_9.jpg', 15, 15, 30, 6, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_basil", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_balsamic_vinegar", "quantity": {"value": 0.25, "unit": "bottle of 250ml"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_pinenuts", "quantity": {"value": 37.5, "unit": "jar"}}, {"id": "ing_balsamic_glaze", "quantity": {"value": 1.0, "unit": "bottle"}}]', '[{"ingredients":["500g/1 lb penne (, ziti or other short pasta)","2 tsp cooking salt / kosher salt (, for cooking pasta)"]},{"ingredients":["1 kg / 2 lb tomatoes (, chopped into 1.25cm / 1/2” pieces, keep all juices (Note 2))","1/2 tsp cooking salt / kosher salt (Note 3)","3/4 cup tightly packed basil leaves (, finely sliced (Note 1))","1/2 cup (tightly packed) finely shredded parmesan"],"purpose":"Bruschetta"},{"ingredients":["1/2 cup extra virgin olive oil (good time to break out the good stuff)","1/4 cup balsamic vinegar","2 garlic cloves (, minced using garlic press or very finely minced using knife)","3/4 tsp cooking salt / kosher salt (Note 3)","1/4 tsp black pepper"],"purpose":"Dressing:"},{"ingredients":["1/4 cup pinenuts (, toasted)","Balsamic glaze (, for drizzling (Note 6))"],"purpose":"Optional extra finishes (Note 4)"}]', '[{"description":"Short directions","images":[],"step":1},{"description":"Cook pasta in salted water until extra soft, toss with 2/3 Dressing, cool. Toss tomato with remaining Dressing, leave 10 min. Pour off juices into pasta, toss. Add 1/2 tsp salt into tomato, toss. Add into pasta with basil, parmesan. Finish with balsamic glaze and pine nuts. Enjoy!","images":[],"step":2},{"description":"Full directions","images":[],"step":3},{"title":"Dressing","description":"Shake the ingredients in a jar (or whisk in a jug).","images":[],"step":4},{"title":"Soft cooked pasta","description":"Bring a large pot of water to the boil with the 2 teaspoons of salt. Cook the pasta per the packet time plus 2 minutes, until the pasta is overcooked and soft. (Note 5) Drain in a colander, then return the pasta into the same pot.","images":[],"step":5},{"title":"Flavour the pasta","description":"Give the dressing a good shake then pour 2/3 of it over the pasta. Stir (enjoy the smell!). Set aside to cool for 15 minutes and let the pasta absorb the dressing flavour.","duration":15,"images":[],"step":6},{"title":"Bruschetta","description":"Put chopped tomato and all watery juices into a bowl. Pour over remaining Dressing, gently toss. Set aside for 10 minutes or until the pasta is cool to let the flavours meld.","duration":10,"images":[],"step":7},{"title":"Finishing (the order matters!)","description":"Pour the juices accumulated in the tomato bowl into the pasta then toss to disperse. Add the salt into the tomato, gently toss, then add the tomato into the pasta. Add the basil, parmesan, gently toss.","images":[],"step":8},{"title":"Serve","description":"Pour into a big bowl and serve! If using extra finishes, drizzle with a swish of balsamic glaze (not too much, it''s strong!) and sprinkle with pine nuts. Eat!","images":[],"step":9}]', '["gluten","milk"]', '["vegetarian"]', '{"mealType":["lunch","dinner"],"cuisine":["Western"],"categories":["pasta-salads-and-rice-salads","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_dbf6c42c0e1d', 'en', 'US', 'Pizza Capricciosa', 'Recipe video above. Topped with artichokes, ham, olives and mushrooms with a tomato pizza sauce, this is a pizza that''s almost uniquely Australian that we are VERY fond of! Though you can find it in some parts of Italy, you won''t see it in many other places around the world.I just love the combination - and that you can be generous with the toppings without overwhelming the pizza. Cook times:Classic yeast pizza dough - 5 to 6 hrs dough rising (total) | 10 min prep | 10 min cookNo-yeast pizza dough - 0 min dough rising | 10 min prep | 10 min oil steeping | 10 min cookStore bought pizza dough - 5 min prep | 10 min prep | 10 min cook** To make more than one pizza (who ever makes just one??!) slide the servings scaler **', 'https://www.recipetineats.com/tachyon/2024/05/Pizza-Capricciosa_8.jpg', 10, 10, 20, 1, '[{"id": "ing_classic_pizza_dough", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_yeast", "quantity": {"value": 1.0, "unit": "pack of 5 sachets"}}, {"id": "ing_uncategorized", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.167, "unit": "pack of 3 heads"}}, {"id": "ing_parsley", "quantity": {"value": 0.013, "unit": "bunch"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.067, "unit": "pack of 125g"}}, {"id": "ing_artichokes", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_mushroom", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_shaved_leg_ham", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_kalamata_olives", "quantity": {"value": 37.5, "unit": "bottle"}}]', '[{"ingredients":["1 classic pizza dough (wood-fired Italian style)","1 fast no-yeast pizza dough (this is excellent!)","1 Store bought (30cm/12\")"],"purpose":"Pizza base – choose one (Note 1):"},{"ingredients":["1/4 cup tomato paste","1/4 tsp cooking salt / kosher salt","1/2 tsp white sugar","1/2 tbsp water","1/2 garlic clove (, finely minced (optional))","1/8 tsp EACH dried parsley , basil and oregano (optional)"],"purpose":"Pizza sauce"},{"ingredients":["1 1/3 cup (130 g) mozzarella cheese, freshly shredded (Note 2)","1/2 cup artichokes (from a jar, preferably oil, drained & sliced (Note 3))","3 button mushrooms (, cut into 3 mm / 1/8\" slices)","2/3 cup (70 g) shaved leg ham (, torn into pieces (thinner is better) (Note 4))","1/4 cup sliced kalamata olives (or black olives)"],"purpose":"Capricciosa topping:"}]', '[{"description":"Preheat oven to 250°C / 480°F (both fan and standard). Allow time to get it nice and hot!!","images":[],"step":1},{"title":"Pizza sauce","description":"Mix the ingredients in a small bowl then set aside.","images":[],"step":2},{"title":"Pizza base","description":"Make and stretch out your chosen pizza base (no rolling pin!), stretch onto a pizza pan or baking tray per the directions in your chosen pizza base. (Note 4 for pizza stone)","images":[],"step":3},{"title":"Top","description":"Spread the pizza sauce on the pizza, leaving a 1 cm/1/2\" border along the edge. Sprinkle with cheese first, then drape the ham randomly across the surface, sprinkle with olives, artichoke slices and mushrooms. (If using the no-yeast pizza base, spray/brush exposed crust with olive oil.)","images":[],"step":4},{"title":"Bake for 10","description":"12 minutes, turning after 4 minutes, or until the the cheese has golden spots and the crust is crispy. Cut and eat, stat!","duration":11,"images":[],"step":5}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Australian","Italian"],"categories":["pizza-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1221c3547c57', 'en', 'US', 'Garlic cheese pizza', 'Recipe video above. No visit to your favourite pizzeria start without garlic cheese pizza! My best garlic pizza calls for both parmesan and mozzarella cheese, and to infuse olive oil with garlic (it only takes 10 minutes). It''s outrageously good!Cook times:Classic yeast pizza dough - 5 to 6 hours dough rising (total) | 10 min prep | 8 min cookNo-yeast pizza dough - 0 min dough rising | 10 min prep | 10 min oil steeping | 8 min cookStore bought pizza dough - 5 min prep | 10 min oil steeping | 8 min cook', 'https://www.recipetineats.com/tachyon/2023/05/Garlic-cheese-pizza_9.jpg', 10, 8, 18, 1, '[{"id": "ing_classic_pizza_dough", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_yeast", "quantity": {"value": 1.0, "unit": "pack of 5 sachets"}}, {"id": "ing_uncategorized", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.8, "unit": "pack of 125g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}]', '[{"ingredients":["1 classic pizza dough (wood-fired Italian style)","1 fast no-yeast pizza dough (this is excellent!)","1 Store bought"],"purpose":"Pizza 30cm/12\" base – your choice (Note 1):"},{"ingredients":["2 tbsp extra virgin olive oil","2 tsp garlic (2 - 3 large cloves), crushed using garlic press or make paste using side of knife - Note 2)","1/8 tsp cooking salt / kosher salt (or table salt, or double qty for salt flakes)","1 cup mozzarella cheese (tightly packed cup), shredded using box grater (Note 3 on pre-shredded)","1/2 cup parmesan (tightly packed cup), shredded using box grater (Note 3)"],"purpose":"Garlic pizza topping:"}]', '[{"description":"Preheat oven to 250°C / 480°F (230°C fan). Allow time to get it nice and hot!!","images":[],"step":1},{"title":"Garlic infused oil","description":"Mix olive oil and garlic in a small bowl. Set aside to infuse with flavour for 10 minutes.","duration":10,"images":[],"step":2},{"title":"Pizza base","description":"Make and roll out chosen pizza base, stretch onto pan.","images":[],"step":3},{"title":"Top","description":"Spread oil (and all garlic) onto the base, leaving the crust baked. Sprinkle with salt, parmesan then mozzarella. (If using no-yeast base, spray/brush exposed crust with olive oil.)","images":[],"step":4},{"description":"Bake 8 minutes, turning after 4 minutes, or until the the cheese has golden spots. Cut and eat, stat!","images":[],"step":5}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dinner","snack"],"cuisine":["Italian"],"categories":["pizza-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_934f113e6576', 'en', 'US', 'Pork Tenderloin with Honey Garlic Sauce', 'Recipe VIDEO above. Tender, succulent pork fillet seasoned with a rub, seared until golden then baked in a Honey Garlic Sauce until sticky on the outside and juicy on the inside. Simply incredible! (And really, it''s SIMPLE!)', 'https://www.recipetineats.com/tachyon/2019/05/Honey-Garlic-Pork-Tenderloin_1.jpg', 10, 25, 35, 5, '[{"id": "ing_pork", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_honey", "quantity": {"value": 0.25, "unit": "jar of 500g"}}]', '[{"ingredients":["2 pork tenderloin (pork fillet), 500g/1lb each (Note 1)","1 1/2 tbsp olive oil (or butter)","3 garlic cloves (, very finely chopped)"]},{"ingredients":["1/2 tsp garlic powder","1/2 tsp paprika","1/2 tsp salt","1/2 tsp black pepper"],"purpose":"Pork Tenderloin Rub:"},{"ingredients":["3 tbsp cider vinegar (Note 2)","1 1/2 tbsp soy sauce, light or all purpose (Note 2)","1/2 cup honey (or maple syrup)"],"purpose":"Honey Garlic Sauce:"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Mix Sauce ingredients together.","images":[],"step":2},{"description":"Mix Rub ingredients then sprinkle over the pork.","images":[],"step":3},{"description":"Heat oil in a large oven proof skillet (Note 3) over high heat. Add pork and sear until golden all over.","images":[],"step":4},{"description":"When pork is almost seared, push to the side, add garlic and cook until golden.","images":[],"step":5},{"description":"Pour sauce in. Turn pork once, then immediately transfer to the oven.","images":[],"step":6},{"title":"Roast 15","description":"18 minutes or until the internal temperature is 68C / 155F (Note 4).","images":[],"step":7},{"description":"Remove pork onto plate, cover loosely with foil and rest 5 minutes.","images":[],"step":8},{"description":"Place skillet with sauce on stove over medium high heat, simmer rapidly for 3 minutes until liquid reduces down to thin syrup.","duration":3,"images":[],"step":9},{"description":"Remove from stove, put pork in and turn to coat in sauce.","images":[],"step":10},{"description":"Cut pork into thick slices and serve with sauce!","images":[],"step":11}]', '["fish","gluten","milk","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b9aa1ed70a57', 'en', 'US', 'Cuban Pork Sandwich (Cubanos) from Chef Movie', 'This is the cubanos sandwich recipe from the 2014 movie Chef. The food in the recipe was created by real life rock star chef Roy Choi. This is the actual recipe from the movie! It was published on thestar.com. This is supposed to be made with a panini / sandwich press but I do not have one so I''ve provided instructions for how to make this in a skillet. AND these are great for freezing! Refer Note 1 for instructions.', 'https://www.recipetineats.com/tachyon/2015/04/Cuban-Sandwiches-Cubanos_side-view_680px.jpg', 10, 15, 25, 2, '[{"id": "ing_thin_slices_baked_leg_ham", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_large", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_bread", "quantity": {"value": 2.0, "unit": "loaf"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_mustard", "quantity": {"value": 0.005, "unit": "jar of 200g"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_or_3_dill_pickles", "quantity": {"value": 2.0, "unit": "kg"}}]', '[{"ingredients":["2 thin slices baked leg ham","4 large (, thin slices Mojo Marinated Pork)","2 pieces of white baguettes (, 6 inch/15 cm in length, cut in half)","Melted butter (, for brushing)","American mustard","2 thin slices Swiss cheese","2 or 3 dill pickles (, thinly sliced)"]}]', '[{"description":"Heat skillet over medium heat. Add ham and pork slices, and cook each side until slightly browned then remove to a plate.","images":[],"step":1},{"description":"Butter cut sides of baguettes then place in the skillet, cut side down, for 2 minutes until lightly browned. Remove onto work surface.","duration":2,"images":[],"step":2},{"description":"Layer the bottom of the baguettes with pork, ham, then cheese and pickles. Cut, break or fold the ham, pork and cheese so they fit. Spread the cut side of the bun tops with mustard then place on the sandwich.","images":[],"step":3},{"description":"Butter the bottom AND top of the outside of the baguettes.","images":[],"step":4},{"description":"Heat skillet over medium high heat. Place the baguettes in the skillet, top with a sheet of baking paper then weigh it down with a heavy skillet or pot (use cans if necessary for extra weight so the sandwich compressed). Cook for 3 minutes on each side, until dark golden brown and crispy, and the cheese is melted.","duration":3,"images":[],"step":5},{"description":"Let sandwiches stand 1 minute before cutting in half. Serve IMMEDIATELY.","images":[],"step":6}]', '["milk","mustard"]', '["gluten_free","high_protein"]', '{"mealType":["lunch"],"cuisine":["Cuban","South American"],"categories":["pork-recipes","sandwiches-and-sliders","south-american-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3f778f476cd2', 'en', 'US', 'Crispy potato straws (Pommes Paille)', 'Recipe video above. 1 x 300g/10oz potato will make about 3 heaped cups of fries (lightly packed).', 'https://www.recipetineats.com/tachyon/2024/07/Crispy-potato-straws-Pommes-Paille_6.jpg', 10, 10, 20, 1, '[{"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 1.5, "unit": "L"}}, {"id": "ing_chilli_flakes", "quantity": {"value": 0.003, "unit": "jar of 40g"}}]', '[{"ingredients":["1 potato (Aus: Sebago, US: russet, UK: Maris Piper), or other starchy or all-rounder potato (Note 1)","1 1/2 - 2 cups vegetable oil (canola, sunflower or peanut oil)","Sea salt flakes (, crushed with fingers into a powder)"]}]', '[{"title":"Shred","description":"Finely julienne the potato using a julienne mandoline, 2-4 mm / 1/16 - 1/8\" thick. (Note 2)","images":[],"step":1},{"title":"Rinse","description":"Place potato in a bowl of water and rinse, changing the water as needed, until the water is clear. Drain in a colander. (Potato can be kept in water overnight in the fridge).","images":[],"step":2},{"title":"Dry","description":"Spread on tea towels then pat dry. If time permits, spread out and air dry for 1 hour+. (Drier potato = less oil bubbling + crispier fries).","images":[],"step":3},{"description":"Heat the oil in a saucepan over high heat to 180°C/350°F, ensuring there is 10 cm/4\" clearance above the oil surface (the oil bubbles up).","images":[],"step":4},{"title":"Add potato into oil","description":"SLOWLY scatter potato across the surface of the oil (don''t dump in once place). ⚠️The oil will bubble up to ~7cm/3\", so add potato slowly, and you can pause until the bubbles subside before adding more. (Note 3 for cooking tips)","images":[],"step":5},{"title":"Fry for 1 1/2","description":"2 minutes, using chopsticks (or similar) to stir once or twice. Once light golden and crisp, scoop out and drain on paper towels. (It goes more golden as it drains). Repeat with remaining potato.","images":[],"step":6},{"title":"Season","description":"Carefully slide the fries into a bowl. Sprinkle with salt and gently toss. Serve immediately while warm, or cool.","images":[],"step":7},{"description":"Serve in bowls for munching, as a garnish like for Beef Tataki or serve a mound alongside a juicy steak or other protein (see in post for more ideas).","images":[],"step":8}]', '["peanuts"]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["French"],"categories":["potato-recipes","snacks"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_751c38bbf09c', 'en', 'US', 'Brie Potato Dauphinoise (Gratin)', 'Recipe video above. I used to think classic Potato Dauphinoise was the ultimate potato bake But then we plonked brie on it and it catapulted into another stratosphere! Because brie trumps ordinary cheese every day of the week, and twice on special occasions .Mini brie are good value at grocery stores ($2.80 each), expensive ones are wasted for this purpose. Also, this is great for making ahead.', 'https://www.recipetineats.com/tachyon/2023/12/Brie-potato-dauphinoise_2c.jpg', 15, 110, 105, 10, '[{"id": "ing_cream", "quantity": {"value": 1.5, "unit": "carton of 250ml"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_potato", "quantity": {"value": 1.25, "unit": "bag of 2kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_brie", "quantity": {"value": 3.0, "unit": "block of 200g"}}]', '[{"ingredients":["1 1/2 cups thickened / heavy cream (, full fat - or just pure cream (Note 1))","2 garlic cloves (, finely minced)","30g / 2 tbsp unsalted butter (, melted)","1.25 kg / 2.5 lb starchy potatoes (Aus: Sebago dirt brushed, US: Russet, UK: Maris Piper) (Note 2)","1 tsp cooking / kosher salt","1/2 tsp black pepper","2 tsp thyme leaves (, fresh (optional - but highly recommended, Note 3))","3 x 125g / 4oz small brie (8cm / 3.2\" wide) (, fridge cold, cut in half horizontally (or camembert) (Note 4))"]}]', '[{"title":"Cream Mixture","description":"Place butter, cream and garlic in a jug. Mix until combined.","images":[],"step":1},{"description":"Preheat oven to 180°C/350°F (both fan and standard ovens).","images":[],"step":2},{"title":"Slice potatoes","description":"Peel the potatoes and slice them 1/8\"/3 mm thick. Or use a slicer!","images":[],"step":3},{"title":"Layer 1","description":"Spread 1/3 of the potatoes in a 1.5 litre / 6 cup baking dish (Note 5). Then pour over 1/3 of the Cream Mixture, scatter with 1/3 of the salt, pepper and thyme.","images":[],"step":4},{"title":"Layers 2 & 3","description":"Repeat for the 2nd and third layer.","images":[],"step":5},{"title":"Cover & bake","description":"Cover with foil, and bake for 1 hour 20 minutes or until the potatoes in the middle are soft (use knife to test), it might take 1 1/2 hours. (Note 6)","images":[],"step":6},{"title":"Top with brie, bake again","description":"Remove foil. Place brie on the surface, cut side down. Bake for a further 30 minutes until the brie is oozy and the edges tinged with gold.","images":[],"step":7},{"title":"Serve","description":"Stand 5 minutes before serving and be prepared to swoon!","images":[],"step":8}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["French"],"categories":["potato-recipes","potatoes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2e1915157c36', 'en', 'US', 'Hasselback potatoes', 'Recipe video above. Soft on the inside and crispy on the edges, brushed with garlic rosemary olive oil! Hasselback success relies on thin slices so they fan out as they bake, allowing oil and salt to drip in between with crispy edges. Otherwise, they end up like regular roast spuds! Making sure you cut through enough and using oval shaped spuds also help to ensure they fan out properly.Worried about your knife skills? Don''t! So what if your slices are irregular or a little too thick? Wonky hasselbacks still trump regular roast spuds every day of the week. :)', 'https://www.recipetineats.com/tachyon/2023/10/Hasselback-potatoes.jpg', 15, 80, 95, 5, '[{"id": "ing_potato", "quantity": {"value": 5.0, "unit": "bag of 2kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_rosemary", "quantity": {"value": 3.0, "unit": "bunch"}}]', '[{"ingredients":["5 - 6 x 250g / 8oz potatoes","1 1/2 tsp extra virgin olive oil","1/4 tsp cooking salt / kosher salt"]},{"ingredients":["1/4 cup extra virgin olive oil","1 1/4 tsp cooking salt / kosher salt (Note 2)","4 garlic cloves (, skin on, smashed (optional) (Note 3))","3 rosemary sprigs (optional but recommended) (Note 3)"],"purpose":"Basting:"}]', '[{"description":"Shortform recipe:","images":[],"step":1},{"description":"Hasselback slice 2mm thick. Rub/sprinkle with 1 1/2 tsp oil and 1/4 tsp salt.","images":[],"step":2},{"description":"Bake 200°C/400°F (180°C fan) for 30 min. Pour over oil, sprinkle with salt, throw garlic and rosemary on tray. Bake further 40 min, basting generously every 10 min (getting oil between slices key), until cooked. Crank up to 220°C/425°F (200°C fan), baste, bake 10 - 15 min until extra golden.","duration":30,"images":[],"step":3},{"description":"Preheat oven to 200°C/400°F (180°C fan-forced).","images":[],"step":4},{"title":"Cut prep","description":"Cut a thin slice off the base of a potato to make it sit flat while cutting. Place the potato between 2 wooden spatulas or chopsticks (no thicker than 1cm / 0.4\" - Note 4), to make it impossible for you to accidentally cut all the way through!","images":[],"step":5},{"title":"THIN slices","description":"Cut the potato into very thin slices, aiming for 2 mm. The cuts on the edges of the potato can be slightly thicker as the edges bake up crisper. (Note 4 for tips)","images":[],"step":6},{"title":"Rub","description":"Drizzle each potato the 1 1/2 tsp oil then sprinkle/rub with the 1/4 tsp salt (ie share across all).","images":[],"step":7},{"title":"Bake 1","description":"Place the potatoes on a tray. Bake for 30 minutes, then remove from oven.","duration":30,"images":[],"step":8},{"title":"Baste 1","description":"The potato slices should be slightly less \"stuck\" together at this stage. Pour the 1/4 cup olive oil over the potatoes then sprinkle the salt evenly over. The salt gets spread later, so don''t worry if it looks like a lot! Throw the garlic and rosemary on the tray.","images":[],"step":9},{"title":"Baking/basting","description":"Bake the potatoes for another 40 minutes, basting with the oil on the tray every 10 minutes. Brush with a bit of pressure across the surface of the potatoes to encourage the oil and salt to drip down. Once oil gets between the slices, they will fan out more and more.","images":[],"step":10},{"title":"CRISP IT!","description":"Once the potatoes are soft in the centre (check with knife), turn the oven UP to 220°C/425°F (200°C). Baste the potatoes again then bake for a further 10 - 15 minutes until the edges are nice and golden. I am quite bold with this step, many others do not seek as much crispy edges.","images":[],"step":11},{"description":"Serve immediately while hot and the edges are crispy! Peeling off those end bits are the BEST.","images":[],"step":12}]', '[]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["swedish","Western"],"categories":["potato-recipes","potatoes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8a2b3c76a262', 'en', 'US', 'Creamy Garlic Prawns (Shrimp)', 'Recipe video above. Creamy Garlic Prawns are your favourite garlic prawns … PLUS a creamy garlic sauce! A few simple tricks give a leg-up to the sauce for a result that''s a cut above your basic recipes: deglaze the pan with a little white wine, a splash of chicken stock and sprinkle of parmesan. Because plump, sweet prawns demand the BEST sauce!', 'https://www.recipetineats.com/tachyon/2020/09/Creamy-Garlic-Prawns_7.jpg', 5, 12, 17, 4, '[{"id": "ing_shrimp", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 15.0, "unit": "block of 250g"}}, {"id": "ing_wine", "quantity": {"value": 0.083, "unit": "bottle of 750ml"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["500g / 1lb peeled prawns/shrimp (, large/jumbo best (Note 1))","1 garlic cloves (, finely minced)","1 tbsp olive oil","1/2 tsp black pepper","1/2 tsp salt"],"purpose":"Garlic marinated prawns:"},{"ingredients":["15g / 1 tbsp unsalted butter"],"purpose":"Cooking prawns:"},{"ingredients":["2 garlic clove (, finely minced)","15g / 1 tbsp unsalted butter","1/4 cup dry white wine (or more chicken stock) (Note 2)","1/2 cup chicken or vegetable stock/broth (, low sodium)","1 cup heavy/thickened cream","1/2 cup parmesan (, finely grated (grate your own, Note 3))","2 tbsp parsley (, finely chopped)"],"purpose":"Creamy garlic sauce:"}]', '[{"description":"Marinate Prawns:","images":[],"step":1},{"description":"Place prawns, garlic, oil and pepper in a bowl. Toss to coat, set aside 20 minutes if time permits (no longer).","images":[],"step":2},{"description":"Stir through salt just prior to cooking.","images":[],"step":3},{"description":"Cook prawns:","images":[],"step":4},{"description":"Melt 15g / 1 tbsp butter in a large skillet over medium high heat. Add half the prawns and cook for 1 minute on each side, then remove.","duration":1,"images":[],"step":5},{"description":"Repeat with remaining prawns (you shouldn''t need more butter), then remove. Scrape out excess remaining garlic from pan and add to cooked prawns.","images":[],"step":6},{"description":"Add butter into skillet and let it melt. Add garlic and stir for 30 seconds or until light golden.","duration":0.5,"images":[],"step":7},{"description":"Add white wine, turn up heat to high. Bring to simmer while stirring base of the pan to dissolve all the golden bits into the sauce. Cook 1 minute or until it most evaporates and the winey smell is gone.","images":[],"step":8},{"description":"Add chicken stock and reduce until mostly gone and just a thin layer remains on base of skillet.","images":[],"step":9},{"description":"Add cream, then simmer on medium heat for 2 minutes until reduced and slightly thickened.","duration":2,"images":[],"step":10},{"description":"Stir through parmesan, then add the prawns back in. Taste sauce and see if more salt and pepper is needed.","images":[],"step":11},{"description":"Serve sprinkled with parsley, over mashed potato or something to soak up that fabulous sauce!","images":[],"step":12}]', '["milk","shellfish"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner","snack"],"cuisine":["Western"],"categories":["prawns-shrimp","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c090aea3c413', 'en', 'US', 'Honey Cake', 'Recipe video above. All too often, honey cakes lack any discernible honey flavour. But you can''t miss the flavour in this one, that''s for sure! You''ll love how this is made only using honey, no sugar at all, and how the soft cake gets soaked with honey syrup hot out of the oven.Serve warm for the best eating experience. Brilliant as a pudding-like cake dessert to finish off a cosy dinner.', 'https://www.recipetineats.com/tachyon/2022/07/Honey-Cake-take-3_5.jpg', 15, 45, 60, 10, '[{"id": "ing_flour", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.05, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 225.0, "unit": "block of 250g"}}, {"id": "ing_honey", "quantity": {"value": 0.333, "unit": "jar of 500g"}}, {"id": "ing_egg", "quantity": {"value": 333.333, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_oranges", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_almonds", "quantity": {"value": 1.0, "unit": "pack of 250g"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.007, "unit": "net of 500g"}}, {"id": "ing_cream", "quantity": {"value": 0.004, "unit": "carton of 250ml"}}]', '[{"ingredients":["1 cup plain flour / all-purpose flour (Note 1)","1 1/2 tsp baking powder","1/2 tsp cooking salt (kosher salt)","225 g (1 cup) unsalted butter (, at room temperature (Note 2))","2/3 cup honey","4 large eggs (, at room temperature (Note 3))","3 tbsp milk (, preferably full-fat, slightly warmed)","1 pinch orange zest (, optional (brings out honey flavour))","1/3 cup almond flakes"],"purpose":"Honey cake"},{"ingredients":["2/3 cup honey","1/4 cup water","3/4 tsp lemon juice (recommended but optional)"],"purpose":"Honey syrup"},{"ingredients":["Vanilla ice cream, cream, lightly toasted almond flakes or slivered almonds"],"purpose":"Topping options for serving"}]', '[{"description":"Preheat the oven to 180°C/350°F (160°C fan).","images":[],"step":1},{"title":"Prepare cake pan","description":"Butter and line a 20cm/8\" round pan or springform pan with baking paper (base and sides).","images":[],"step":2},{"title":"Whisk Dry ingredients","description":"Whisk together the flour, baking powder and salt in a small bowl.","images":[],"step":3},{"title":"Cream butter and honey","description":"In a separate bowl, cream the butter and honey for 3 minutes, scraping down the sides halfway, until smooth and fluffy. (Speed 7 handheld beater or stand mixer fitted with whisk attachment).","duration":3,"images":[],"step":4},{"title":"Add eggs and flour","description":"Add one egg, mix with a wooden spoon for 30 seconds until mostly incorporated into the batter (mixture will looked curdled). Then add in 1/4 of the flour and mix until the batter comes together. Repeat again - mixing in 1 egg, then a portion of flour - until you''ve used all the eggs.","duration":0.5,"images":[],"step":5},{"title":"Milk and zest","description":"Stir in the milk and orange zest, stir until the batter is almost completely smooth. The batter should be quite thick, but soft.","images":[],"step":6},{"title":"Bake 45 min","description":"Scrape batter into the prepared pan, smooth the surface and sprinkle with almonds. Bake for 45 minutes or until a knife inserted into the centre comes out clean.","duration":45,"images":[],"step":7},{"title":"Cool 30 min","description":"Remove cake from the oven. Cool for 30 minutes in the pan - don’t skip this else the cake gets too dense when soaked with syrup.","duration":30,"images":[],"step":8},{"title":"Honey Syrup","description":"Meanwhile, make the syrup. Bring the honey and water to a gentle boil for 5 minutes over medium-low heat. Add the lemon juice and boil for 2 more minutes. Remove from heat, cool for 10 minutes then use per below.","duration":5,"images":[],"step":9},{"title":"Poke and soak","description":"Poke about 30 holes all across the surface using a skewer (between the almond flakes). Pour 1/4 of the warm Honey Syrup across the surface (if using a springform pan, put it on a plate in case it leaks). Once it mostly sinks in, repeat 3 more times, waiting between pours for the syrup to soak in. Then leave the cake to soak for 15 minutes.","duration":15,"images":[],"step":10},{"title":"Serve","description":"Serve warm. Remove the springform pan sides, or serve it straight out of the cake pan (Note 4 for removing from cake pan). I typically serve it plain. However Topping Options suggested above would never be turned away!","images":[],"step":11}]', '["egg","gluten","milk","nuts"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["puddings-cosy-desserts","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_059371ebc30d', 'en', 'US', 'Roasted Garlic Butter', 'This is a recipe for a butter that''s given a massive flavour leg up with roasted garlic, parmesan and anchovies. I am hopelessly addicted to it, and I use it on everything: slather on bread, on cooked proteins (chicken, fish, steak), and steamed vegetables. It''s especially brilliant with roast beef, like the Beef Rump Cap Roast (Picanha) I also shared today.Use softened, or shape it into a log, refrigerate then cut slices and place on a hot dish to let it slowly melt.Makes 150g / 2/3 cup, enough for 6 to 8 people as a sauce for steak etc.', 'https://www.recipetineats.com/tachyon/2025/11/Roasted-garlic-butter.jpg', 7, 30, 37, 8, '[{"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 125.0, "unit": "block of 250g"}}, {"id": "ing_anchovies", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["1 large head of garlic (, separate the cloves but keep skin on)","1 tsp olive oil","Pinch of salt"],"purpose":"Roasted garlic:"},{"ingredients":["2 tbsp roasted garlic (above)","125g (1 stick / 8 tbsp) unsalted butter (, softened)","1 tsp anchovy paste (or finely chopped whole anchovies) (Note 1)","25g (1/4 cup very tightly packed) parmesan (, finely grated using microplane)","1/4 tsp cooking salt / kosher salt"],"purpose":"Everything else:"},{"ingredients":["1 tbsp parsley finely minced (, optional)"],"purpose":"Optional finish:"}]', '[{"description":"If making this with the Rump Cap / Picanha roast (the recipe this butter was shared with), put the foil wrapped garlic in the oven at 140°C/285°F (120°C fan-forced) with the rump cap for 1 hour.","images":[],"step":1},{"description":"Roasted garlic:","images":[],"step":2},{"description":"Preheat oven to 180°C/350°F (160°C fan-forced).","images":[],"step":3},{"description":"Put the garlic cloves on a piece of foil, drizzle with oil and salt, then enclose with the foil.","images":[],"step":4},{"description":"Place in the oven for 30 minutes or until the garlic flesh is soft like a paste (check a big one).","duration":30,"images":[],"step":5},{"description":"Open the foil and when cool enough to handle, squeeze the flesh out into a bowl.","images":[],"step":6},{"description":"Measure out 2 tablespoons of the roasted garlic paste into a small bowl. Add remaining butter ingredients, then blitz with a stick blender until smooth. Stir in parsley, if using.","images":[],"step":7},{"description":"Add a dab on steak, grilled chicken, fish etc, or on steamed vegetables. Or serve with dinner rolls - it''s amazing! I like using it when softened but you can also make a log, refrigerate to firm then cut slices.","images":[],"step":8}]', '["fish","milk"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["quick-and-easy","roast-beef","sauces"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_138af84f0415', 'en', 'US', '8 minute Lebanese Pizzas (Lahmacun!)', 'Recipe video above. Invented in pursuit of more interesting ways to use chicken mince, this is a SOS take on traditional manakish Lebanese pizzas made with flatbreads topped with a thin layer of meat, commonly known by the Turkish name lahmacun. Astoundingly fast to make, and extremely versatile, think of this recipe as a blueprint rather than a rule book. Use any ground meat, add shredded vegetables - and topping options are endless! Don''t skip the feta and olive oil for toppings. It really makes it. :)', 'https://www.recipetineats.com/tachyon/2025/01/Quick-Lebanese-pizza_1.jpg', 5, 3, 8, 1, '[{"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_chicken_mince", "quantity": {"value": 0.125, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_baharat_spice_mix", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_paprika", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_pine_nuts", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1 x ~30cm/12\" Lebanese bread (, (sub other thin flatbreads, Note 1))"]},{"ingredients":["125g / 4 oz chicken mince (ground chicken) (Note 2)","2 tsp tomato paste","1 tsp Baharat spice mix (aka Lebanese 7 spice) (Note 3 subs)","1/2 tsp paprika (, sweet (or smoked))","1 garlic clove (, crushed using garlic press)","1/4 tsp cooking salt / kosher salt (halve for table salt)","1 tbsp finely chopped parsley (or coriander/cilantro, totally optional (sub 1 tsp dried oregano))","1 1/2 tbsp extra virgin olive oil (, for cooking (or regular olive oil))"],"purpose":"Spiced Chicken Mince spread:"},{"ingredients":["Extra virgin olive oil","2 tbsp Danish feta or goats cheese (, crumbled (or regular feta))"],"purpose":"Toppings – essential! (Note 4)"},{"ingredients":["Lemon juice (, just a light drizzle)","Dried chilli flakes / red pepper flakes","~1 tbsp toasted pine nuts (, roughly chopped (sub pistachios, almonds, sesame seeds))","1 tsp finely chopped parsley (or coriander/cilantro)"],"purpose":"Toppings – optional (makes it even better!)"}]', '[{"description":"Trim bread to fit pan, mix filling, smear on bread. Heat oil on high, pan fry 90 seconds meat side down, then bread side 90 seconds until crispy. Top, cut, eat!","images":[],"step":1},{"description":"Use a large 30cm/12\" non-stick pan. If needed, use scissors to cut one side of the Lebanese bread so it fits in your pan (Note 1 & 5)","images":[],"step":2},{"description":"Mix the Chicken Spread ingredients in a bowl. Spread all across the surface of one side of the bread like peanut butter, smearing and pressing it onto the bread well so it sticks. Use it all! (It will be a fairly thin layer.)","images":[],"step":3},{"title":"Cook meat side","description":"Heat 1 tablespoon of oil in the pan over high heat. Place the bread in meat side down and cook for 90 seconds, pressing down lightly to encourage colour. The meat will stick to the bread!","duration":1.5,"images":[],"step":4},{"title":"Crisp bread","description":"Turn with tongs (there should be some golden patches) and cook the bread side for 90 seconds until golden and crispy (lower heat if browning too quickly).","duration":1.5,"images":[],"step":5},{"title":"Toppings","description":"Slide onto cutting board, sprinkle with feta, drizzle with extra virgin olive oil. Sprinkle with other toppings you choose. Cut into 8 like pizza, enjoy!","images":[],"step":6}]', '["gluten","milk","sesame"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["lebanese","Middle Eastern"],"categories":["quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8954343d276c', 'en', 'US', 'Blondies', 'Recipe video above. Think - butterscotch flavoured brownies! Thin crackly surface (like brownies!), crispy on the edges, chewy inside. Ridiculously easy, outrageously addictive, wonderfully versatile - add in whatever you want, see the Ingredients section in the post for ideas. I love the combination of white chocolate and walnuts or macadamia nuts.Don''t skip the browned butter step. It really makes it. Recipe source: Smitten Kitchen, one of my most trusted recipe sources. A rare recipe where I have changed nothing!', 'https://www.recipetineats.com/tachyon/2024/07/Blondies_1.jpg', 15, 25, 40, 16, '[{"id": "ing_butter", "quantity": {"value": 125.0, "unit": "block of 250g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_flour", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_chocolate", "quantity": {"value": 1.0, "unit": "block of 100g"}}, {"id": "ing_walnuts", "quantity": {"value": 75.0, "unit": "jar"}}, {"id": "ing_chilli_flakes", "quantity": {"value": 0.031, "unit": "jar of 40g"}}]', '[{"ingredients":["125g/8 tbsp (1 US stick) unsalted butter (Note 1)","1 cup brown sugar (, (light brown sugar also ok, but not dark brown))","1 large egg (~50g/2 oz)","1 tsp vanilla extract","1 cup flour (, plain/all-purpose)","1/4 tsp cooking salt / kosher salt (halve for table salt)"]},{"ingredients":["1 cup white chocolate chips","1/2 cup walnuts (, roughly chopped)"],"purpose":"Add-ins – 1 1/2 cups “anything you want”, I used:"},{"ingredients":["1/4 tsp sea salt flakes"],"purpose":"Optional sprinkling:"}]', '[{"description":"Preheat the oven to 180°C/350°F (160°C fan-forced). Grease a 20 cm/8\" square pan with butter and line with baking paper (parchment paper).","images":[],"step":1},{"title":"Toast walnuts (Note 3)","description":"Spread the walnuts on a tray and roast for 5 minutes. Remove from the oven and cool.","duration":5,"images":[],"step":2},{"title":"Browned butter (don''t skip this step)","description":"Place the butter in a silver saucepan (not black) over medium high heat. Once melted, lower the heat to medium so it''s simmer gently. Simmer for 3 to 4 minutes, stirring every now and then (it will go foamy), until it smells nutty and you see little golden specks in the butter. Immediately pour the butter and all the golden bits into a bowl.","duration":3.5,"images":[],"step":3},{"title":"Batter","description":"Add the sugar into the hot butter and mix to combine using a wooden spoon. Leave to cool for 3 minutes. Add the egg and vanilla, mix until combined. Add the flour and salt, and mix to combine. It will be very thick, almost like roll-able cookie dough. Add the chocolate chips and walnuts and mix through.","duration":3,"images":[],"step":4},{"title":"Bake","description":"Scrape into the prepared pan, spread and smooth the surface (I use my hands). Bake for 25 minutes or until the edges are lightly tinged with gold and the surface has a paper thin \"crackly\" layer.","duration":25,"images":[],"step":5},{"description":"Rest in the pan for 10 minutes before lifting onto a cutting board. Cool for at least another 10 minutes (else it''s still a bit too soft and smeary), sprinkle with salt flakes (if using). Cut into 16 squares or 9 giant squares, then devour!","duration":10,"images":[],"step":6}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["dessert-recipes","quick-and-easy","slices-bars"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f92b5b3bdc1e', 'en', 'US', 'Garlic rice', 'Recipe video above. Garlic Rice is the easiest, best tasting side dish that you can serve with anything! From roast chicken to chops, stir fries to fish, Middle Eastern to Mexican food, this buttery rice is so flavourful you can eat it plain.Have some tonight, freeze some for later! See notes for recipe scaling tips.', 'https://www.recipetineats.com/tachyon/2023/08/Garlic-rice_5.jpg', 5, 20, 25, 6, '[{"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_white_rice", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["50 - 75g/ 4 - 5 tbsp unsalted butter (, divided (Note 1))","5 garlic cloves (, finely minced (Note 2))","2 cups white rice (uncooked) ( - long grain, medium grain, short grain (sushi rice) or basmati (Note 3))","3 cups chicken stock/broth (, low sodium (stock powder option - see Note 4))","3/4 tsp cooking/kosher salt (or 1/2 tsp table salt)","1 tbsp parsley (, finely chopped, plus extra for garnish (optional))"]}]', '[{"description":"No need to rinse the rice. The rice will be fluffy because this recipe uses the right ratio: 1.5 cups liquid for every 1 cup of rice.","images":[],"step":1},{"title":"Sauté garlic","description":"Melt half the butter in a large saucepan over medium high heat. Once foamy, add the garlic and cook for 30 seconds until it turns light golden.","duration":0.5,"images":[],"step":2},{"title":"Coat rice","description":"Add the rice and stir for 30 seconds or until the grains turn translucent.","duration":0.5,"images":[],"step":3},{"title":"Simmer","description":"Add stock and salt. Turn heat up to high, then once the water starts bubbling, put the lid on and immediately turn the stove down to low (or medium low, if your stove is weak/small). (Note 5)","images":[],"step":4},{"title":"Cook 15 minutes","description":"Cook the rice for 15 minutes. No stirring, don''t lift the lid.","duration":15,"images":[],"step":5},{"title":"Rest 10 minutes","description":"Tilt the saucepan and have a quick peek to ensure all the water is absorbed. Then remove off the stove, with the lid still on, and rest for 10 minutes.","duration":10,"images":[],"step":6},{"description":"Fluff rice, then fluff through remaining butter until melted. Toss through parsley, then tumble into serving dish. Sprinkle with extra parsley then serve!","images":[],"step":7}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Asian","Western"],"categories":["quick-and-easy","rice","rice-recipes","rice-side-dishes","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e7d7a12e4b6e', 'en', 'US', 'Bursty Tomato Burrata Salad', 'Recipe video above. My favourite burrata recipe - Bursty Tomato Burrata Salad. Juicy roasted cherry tomatoes, creamy burrata cheese, dollops of pesto, swish of olive oil and crusty bread. Simple, luscious, rustic perfection. Gorgeous appetiser or light meal that''s not too expensive to make.Finishing with pesto takes this over the top but it''s still worth making even without. But whatever you do, don''t forget bread for mopping!', 'https://www.recipetineats.com/tachyon/2023/07/Burrata-roasted-tomatoes-pesto_6.jpg', 10, 10, 20, 4, '[{"id": "ing_cheese", "quantity": {"value": 200.0, "unit": "block of 250g"}}, {"id": "ing_basil", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_tomato", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_green_onion", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_chilli_flakes", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_basil", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["200g/ 6 oz x 1 fresh burrata cheese (Aus: Paesanella is my go-to, Note 1)","1/4 cup basil pesto (, preferably homemade, recommended but not essential (Note 2))"]},{"ingredients":["500g/ 1 lb (4 cups) cherry or grape tomatoes","2 tbsp extra virgin olive oil","2 tbsp eschalot (, finely chopped (US: shallot), ~1/2 small (Note 3 subs))","1/2 tsp cooking/kosher salt","1/4 tsp black pepper","2 tsp sherry vinegar (or apple cider or red wine vinegar)"],"purpose":"Roasted tomato:"},{"ingredients":["1/2 tsp salt flakes (or half the quantity for cooking/kosher salt) (Note 4)","1 tbsp extra virgin olive oil (, a good one is best, for finishing)","Few fresh basil leaves (, for sprinkling (Note 2))","Warmed crusty bread (, for mopping)"],"purpose":"Serving:"}]', '[{"title":"De-chill","description":"Take the burrata out of the fridge and leave on the counter for 30 minutes, to take the fridge-chill out of it. Keep it in the water in the tub.","duration":30,"images":[],"step":1},{"description":"Roasted tomatoes:","images":[],"step":2},{"description":"Preheat oven to 200°C/400°F (180°C fan).","images":[],"step":3},{"title":"Roast 10 min","description":"Toss the cherry tomatoes with the olive oil, eschalot, salt and pepper (in a bowl, or on a tray). Spread on a tray. Roast 10 minutes until softened but not collapsing.","images":[],"step":4},{"title":"Vinegar","description":"Gently push the tomatoes to one end of the tray. Drizzle over vinegar. No need to mix.","images":[],"step":5},{"title":"Tomatoes","description":"Carefully transfer tomatoes to a plate, spreading them out in a single layer.","images":[],"step":6},{"title":"Burrata","description":"Gently (GENTLY!!) drain the water out of the tub and roll the burrata out into your hand. Place a burrata on top of tomatoes.","images":[],"step":7},{"title":"Finish","description":"Drizzle the 1 tablespoon of good extra virgin olive oil all over the plate. Dollop pesto randomly all over. Sprinkle with salt flakes and basil.","images":[],"step":8},{"description":"Serve with crusty bread on the side!","images":[],"step":9},{"description":"Nominate a person to do the cutting honours. Break into the burrata with a serving spoon. Let the centre ooze out. Make sure you scoop up a bit of everything, pile onto bread and eat! Don''t forget to mop the plate clean. The juices are the best part.","images":[],"step":10}]', '["gluten","milk"]', '["keto_friendly","low_calorie","vegetarian"]', '{"mealType":["snack"],"cuisine":["Italian","Western"],"categories":["quick-and-easy","tomato"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a0db4dcf17d7', 'en', 'US', 'Mojito', 'Recipe video above. The world''s most refreshing cocktail, ever!! Made for hot summer days, but truthfully we make Mojitos year round just because we love the fresh minty flavour! SCALE RECIPE using slider.', 'https://www.recipetineats.com/tachyon/2019/10/Mojito-3.jpg', 3, 0, 3, 1, '[{"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_mint", "quantity": {"value": 10.0, "unit": "bunch"}}, {"id": "ing_rum", "quantity": {"value": 60.0, "unit": "unit"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.375, "unit": "tub of 200g"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_mint", "quantity": {"value": 10.0, "unit": "bunch"}}]', '[{"ingredients":["30ml / 1 oz lime juice (, fresh)","30ml / 1 oz sugar syrup (, homemade (Note 1))","10 mint leaves","60 ml / 2 oz white rum (I use Bicardi, Note 2)","1/2 cup (125ml) club soda / soda water (Note 3)"]},{"ingredients":["Lime wedges or slices","Mint sprigs"],"purpose":"Garnishes"}]', '[{"description":"Place lime juice, rum and sugar syrup in tall glass. Use a muddler (Note 4) to bruise the mint to release flavour.","images":[],"step":1},{"description":"Fill glass with ice, pour over rum and soda water, then stir.","images":[],"step":2},{"description":"Garnish with lime slice and mint leaves. Serve immediately!","images":[],"step":3}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Cuban","Western"],"categories":["quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ddf6a701202b', 'en', 'US', 'Tequila Sunrise', 'Recipe video above. Simple recipe but useful to see the best way to get the red "sunrise" effect on the bottom of the glass! Use recipe SCALER to scale recipe up.', 'https://www.recipetineats.com/tachyon/2019/09/Tequila-Sunrise.jpg', 5, 0, 5, 1, '[{"id": "ing_tequila", "quantity": {"value": 45.0, "unit": "unit"}}, {"id": "ing_oranges", "quantity": {"value": 0.09, "unit": "kg"}}, {"id": "ing_grenadine_syrup", "quantity": {"value": 15.0, "unit": "unit"}}, {"id": "ing_oranges", "quantity": {"value": 0.09, "unit": "kg"}}, {"id": "ing_cherries", "quantity": {"value": 1.0, "unit": "pack of 500g"}}]', '[{"ingredients":["45 ml / 1.5oz tequila","90ml / 3 oz orange juice","15 ml / 0.5 oz grenadine syrup"]},{"ingredients":["Orange slices","Maraschino cherry"],"purpose":"Garnishes"}]', '[{"description":"Pour tequila and orange juice in a tall glass. Scale up recipe as required for your glass side (1 part tequila to 3 parts OJ)!","images":[],"step":1},{"description":"Mix, then fill with ice.","images":[],"step":2},{"description":"Drizzle grenadine down the side of the glass over the back of a teaspoon (see video). Do not mix!","images":[],"step":3},{"description":"Garnish with orange slice and Maraschino cherry. Serve immediately!","images":[],"step":4}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Tropical!","Western"],"categories":["quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_49be494610c5', 'en', 'US', 'Espresso Martini', 'Recipe video above. This will wake you up - AND get you partying! I love having espresso martinis when I need a pick me up at the start of an evening, and for after dinner drinks. USE SCALER to make multiple drinks or for a larger glass.', 'https://www.recipetineats.com/tachyon/2019/09/Espresso-Martini_3.jpg', 5, 0, 5, 1, '[{"id": "ing_vodka", "quantity": {"value": 40.0, "unit": "unit"}}, {"id": "ing_kahlua", "quantity": {"value": 20.0, "unit": "unit"}}, {"id": "ing_espresso_coffee", "quantity": {"value": 20.0, "unit": "unit"}}, {"id": "ing_coffee_beans", "quantity": {"value": 3.0, "unit": "pack"}}]', '[{"ingredients":["40ml / 1 1/3oz Vodka","20ml (2/3 oz) Kahlua","20ml (2/3 oz) espresso coffee (, cooled)","3 coffee beans (, garnish)"]}]', '[{"description":"Place the vodka, kahlua and espresso in a cocktail shaker with ice.","images":[],"step":1},{"description":"Shake vigorously 10 times, then pour briskly into a cocktail glass. (Scrape out foam inside if necessary)","images":[],"step":2},{"description":"Garnish wtih 3 coffee beans and serve immediately.","images":[],"step":3}]', '[]', '["gluten_free","keto_friendly","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_eb078489dee3', 'en', 'US', 'Frozen Strawberry Daiquiris', 'Recipe video above. The most incredible real strawberry flavour - the ultimate strawberry daiquiri! Skip the ice - it dilutes the flavour. This frozen daiquiri has the perfect slushy consistency, and it''s dangerously drinkable - there''s a fair slug of booze in this but you can''t taste it!', 'https://www.recipetineats.com/tachyon/2019/09/Frozen-Strawberry-Daiquiri_1.jpg', 10, 0, 10, 2, '[{"id": "ing_strawberries", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_strawberries", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 0.12, "unit": "net of 500g"}}, {"id": "ing_rum", "quantity": {"value": 120.0, "unit": "unit"}}, {"id": "ing_lime", "quantity": {"value": 0.12, "unit": "net of 500g"}}]', '[{"ingredients":["250g/ 8 oz frozen strawberries (, leaves removed)","60g/ 2 oz fresh strawberries (, leaves removed (4 strawberries, Note 1))","30 ml / 1 oz sugar syrup (Note 2)","60 ml / 2 oz lime juice (, fresh)","120 ml / 4 oz white rum (Note 3)"]},{"ingredients":["Fresh strawberries (, cut slit in base)","Lime slices"],"purpose":"Garnish options:"}]', '[{"description":"Place all ingredients in a blender or Nutribullet.","images":[],"step":1},{"description":"Blitz until all strawberries are blitzed.","images":[],"step":2},{"description":"Taste and adjust sweet with more syrup, sour with lime (and booze if you dare!).","images":[],"step":3},{"description":"Pour into glasses (see video for consistency) and serve, garnished with fresh strawberries!","images":[],"step":4}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b30ab98b5876', 'en', 'US', 'Persian Love Cake', 'Recipe video above. A beautiful Persian cake with a lovely subtle citrus flavour and hint of spice. For an authentic Persian flavour, don''t skip the rosewater! They differ in strength so start with a small amount and adjust to your taste - too much can be overpowering.', 'https://www.recipetineats.com/tachyon/2018/09/Persian-Love-Cake_2.jpg', 15, 60, 75, 12, '[{"id": "ing_almonds", "quantity": {"value": 0.2, "unit": "pack of 250g"}}, {"id": "ing_semolina", "quantity": {"value": 225.0, "unit": "pack"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.1, "unit": "tub of 150g"}}, {"id": "ing_round_nutmeg", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_butter", "quantity": {"value": 120.0, "unit": "block of 250g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_yogurt", "quantity": {"value": 0.3, "unit": "tub of 500g"}}, {"id": "ing_oranges", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_pistachios", "quantity": {"value": 50.0, "unit": "unit"}}, {"id": "ing_lemon", "quantity": {"value": 0.1, "unit": "net of 500g"}}, {"id": "ing_water", "quantity": {"value": 0.005, "unit": "L"}}]', '[{"ingredients":["2 cups (200g) almond meal (almond flour)","1 1/2 cups (165g) semolina","1 tbsp baking powder","1/2 tsp ground nutmeg","1.5 tsp ground cardamom","120g / 8 tbsp unsalted butter (, at room temperature)","3/4 cup (150g) brown sugar (, packed)","3/4 cup (150g) white sugar","2 eggs","1 cup (250g) plain yoghurt","Zest of one orange","50g / 2 oz raw pistachios (, chopped or slivered (or almonds))"]},{"ingredients":["1/3 cup (85 ml) lemon juice","1/3 cup (70g) white sugar","1 tsp+ rosewater (adjust to taste, start with less)"],"purpose":"Syrup:"}]', '[{"description":"Preheat oven 180C/350F (standard) or 160C/320F (fan). Grease and line a 22cm/9\" cake pan.","images":[],"step":1},{"description":"Mix almond meal, semolina, baking powder, nutmeg and cardamon in bowl.","images":[],"step":2},{"description":"Beat butter and both sugars with an electric beater until incorporated. Add eggs, beat until smooth. Then add yoghurt and orange zest, beat until smooth.","images":[],"step":3},{"description":"Add dry ingredients. Stir until mixed through.","images":[],"step":4},{"description":"Pour into pan, smooth surface. Scatter over pistachios.","images":[],"step":5},{"description":"Bake 50 minutes to 1 hour, until skewer inserted into the centre comes out clean.","images":[],"step":6},{"title":"Poke 30","description":"40 holes all over the cake using a skewer (poke all the way through). Pour warm syrup over while cake still hot. Leave to soak for 1 hour+ before removing from pan. Cool then slice to serve.","images":[],"step":7},{"description":"Pictured decorated with dried rose petals. Alternative: no decorations (pistachios alone look great!), dust with icing / confectionary sugar, of a Lemon Glaze (use this one)","images":[],"step":8},{"description":"Place ingredients in a saucepan over medium heat. Bring to simmer and stir to dissolve sugar. Simmer for 2 minutes. Keep warm (or reheat) for pouring.","duration":2,"images":[],"step":9}]', '["egg","gluten","milk","nuts"]', '["vegetarian"]', '{"mealType":["dessert"],"cuisine":["Persian"],"categories":["dessert-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9f34c1f47843', 'en', 'US', 'Mango Daiquiris', 'Bursting with bright summer flavours, these mango daiquiris are the king of all cocktails! I make mine in a blender but I''ve also provided directions to make this without. This makes 3 cups / 750ml - perfect amount for 4 martini glasses.', 'https://www.recipetineats.com/tachyon/2017/01/Mango-Daiquiris-9.jpg', 10, 0, 10, 750, '[{"id": "ing_mango", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_rum", "quantity": {"value": 90.0, "unit": "unit"}}, {"id": "ing_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 0.075, "unit": "net of 500g"}}, {"id": "ing_heaped_cup_of_ice_cubes_plus_more_to_serve", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_strawberries", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_lime", "quantity": {"value": 0.075, "unit": "net of 500g"}}, {"id": "ing_mint", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 large ripe mango (1 1/4 cups of flesh)","90 ml / 3 oz white rum (I use Bacardi)","2 tbsp sugar syrup (adjust to taste) (Note 1)","1/4 cup fresh lime juice","1 heaped cup of ice cubes ((or 1 cup crushed ice), plus more to serve)"]},{"ingredients":["1/4 cup white sugar","1/4 cup boiling water"],"purpose":"Sugar Syrup (Note 1)"},{"ingredients":["Strawberries","Lime slices","Mint"],"purpose":"Garnish (optional)"}]', '[{"description":"Chill glasses in the fridge.","images":[],"step":1},{"description":"Make With Blender","images":[],"step":2},{"description":"Place Daiquiri ingredients in the blender in the order listed (ice last, blends better).","images":[],"step":3},{"description":"Whizz until ice is blitzed. Taste test then adjust sour with lime and sweetness with sugar.","images":[],"step":4},{"title":"Pour into glasses","description":"this recipe makes the perfect amount to fill 4 martini glasses.","images":[],"step":5},{"description":"Garnish with strawberries, lime and mint if desired. Serve cold.","images":[],"step":6},{"description":"Without Blender","images":[],"step":7},{"description":"Puree mango using a stick blender or food processor.","images":[],"step":8},{"description":"Pour into 1 litre / 1 quart or larger jar or bottle. Add bacardi, sugar syrup and 1/2 cup water (Note 3). Refrigerate until chilled. Also refrigerate the limes and glasses.","images":[],"step":9},{"description":"Once chilled, add lime juice and ice cubes into the bottle. Shake well, then serve, straining the ice cubes. You can also put some crushed ice into the glasses, but remember that as the ice melts, it will dilute the cocktail.","images":[],"step":10}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["quick-and-easy","tropical","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_57fcd1074868', 'en', 'US', 'Lemon Yogurt Sauce', 'A great creamy sauce that''s super quick to make and goes with "everything" from beef skewers to roasted vegetables, Gyros wraps to broccoli fritters. I even use it on tacos! It''s bright, lemony, slightly garlicky and creamy, without the greasiness of mayo. I love that it works with all sorts of cuisines, though it''s especially great with Middle Eastern and Mediterranean flavours.On the odd occasion I don''t have a fresh lemon, I''ll use 1/2 tbsp apple cider vinegar or rice vinegar (the touch of extra tang really works in this sauce), or just substitute with more olive oil (for a smidge extra richness).Makes 1 cup.', 'https://www.recipetineats.com/tachyon/2020/10/Lemon-Yogurt-Sauce_9.jpg', 5, 0, 5, 1, '[{"id": "ing_yogurt", "quantity": {"value": 0.3, "unit": "tub of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.417, "unit": "pack of 3 heads"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}]', '[{"ingredients":["1 cup plain yogurt (, preferably full-fat (I use Greek-style, greek or regular plain works))","1/4 tsp finely grated garlic (1/2 clove)","1 tbsp lemon juice (sub half the amount with apple cider vinegar, or other clear vinegar)","1 tbsp extra-virgin olive oil (, plus more to thin if desired)","1/4 tsp cooking salt/kosher salt (halve for fine table salt, +50% for flakes)","Pinch black or white pepper (, optional)","Extra water or olive oil to thin (, if needed (use with caution, taste and add extra salt if needed))"]}]', '[{"description":"Mix the ingredients in a bowl and set aside for at least 20 minutes to let the flavours meld.","images":[],"step":1},{"title":"Loosen","description":"If you want to thin it slightly (for drizzling) add water or olive oil 1 tablespoon at a time, taste and add more salt if needed. Use for dipping, drizzling, dolloping, smearing (see in post for so many ideas!)","images":[],"step":2}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Mediterranean","Middle Eastern"],"categories":["quick-flick-recipes","sauces"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8ce3ef9108b6', 'en', 'US', 'Hot buttered corn rice', 'Recipe video above. Hot Buttered Corn Rice - a simple yet delicious upgrade from plain steamed rice. Serve with any cuisine, any dish - goes with everything. Make lots - everyone will go in for seconds!', 'https://www.recipetineats.com/tachyon/2024/08/Hot-buttered-corn-rice_3.jpg', 7, 12, 29, 4, '[{"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 3.0, "unit": "pack of 3 heads"}}, {"id": "ing_corn", "quantity": {"value": 0.75, "unit": "can of 400g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_rice", "quantity": {"value": 150.0, "unit": "pack"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_green_onion", "quantity": {"value": 0.04, "unit": "bunch"}}]', '[{"ingredients":["50g/ 4 tbsp unsalted butter (, divided)","3 big garlic cloves (, finely minced (can use garlic press))","2 cups frozen corn (no need to thaw), or fresh corn kernels (Note 1)","1/4 tsp cooking salt / kosher salt","Pinch of pepper","1 cup long grain rice (, uncooked, not rinsed (Note 2))","1 1/2 cups low-sodium chicken stock/broth (+ 2 tbsp extra if using fresh corn)","2 green onion stems (, finely sliced)"]}]', '[{"title":"Pot size","description":"Use a small pot or large saucepan about 20-22 cm/8-9\". (Note 3)","images":[],"step":1},{"title":"Sauté","description":"Melt half the butter in a pot over high heat. Add the garlic and stir for 15 seconds. Add the corn and half the salt. Stir for 2 minutes.","duration":0.25,"images":[],"step":2},{"title":"Bring to simmer","description":"Add the rice and stir for 30 seconds. Add the stock and remaining salt, and pepper. Stir, bring to a simmer (make sure the whole surface is bubbling/ripplling), then put the lid on and turn the heat down to medium low (or low, if your stove is strong). (Note 4)","duration":0.5,"images":[],"step":3},{"description":"Cook for 12 minutes (no peeking, no stirring!). The liquid should be absorbed by now - tilt the pot and take a quick peek to check.","duration":12,"images":[],"step":4},{"title":"Rest 10 minutes","description":"Remove the pot from the stove and let it rest for 10 minutes with the lid on. This step is key, do not skip it! (Note 5)","duration":10,"images":[],"step":5},{"title":"Toss","description":"Lift the lid, add the remaining butter, fluff the rice to melt the butter through. Add green onion and toss through.","images":[],"step":6},{"description":"Tumble into serving bowl. Serve hot!","images":[],"step":7}]', '["milk"]', '["gluten_free"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["rice-recipes","rice-side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3714e8bd9b91', 'en', 'US', 'Jamaican rice and peas', 'Recipe video above. Perfumed with thyme and all spice with a hint of traditional warmth from fresh chilli, this Jamaican coconut rice makes the perfect side dish for tropical themed foods such as Jerk Fish or Chicken, with a side of Jamaican slaw!Baking is best - Ordinarily, this dish is prepared on the stove. But I find the most fuss-free way to make coconut rice is in the oven.Fluffier, no scorched base, entirely hands off. Try it. You''ll be converted for life!', 'https://www.recipetineats.com/tachyon/2023/01/Jamaican-Rice-and-Peas-Beans_8.jpg', 10, 45, 55, 6, '[{"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_kidney_beans", "quantity": {"value": 2.0, "unit": "can of 400g"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_white_rice", "quantity": {"value": 0.3, "unit": "kg"}}]', '[{"ingredients":["50g / 3 tbsp unsalted butter (or 2 tbsp canola or veg oil)","2 garlic cloves (, finely minced)","1 small onion (, finely chopped)","1 tsp dried thyme","1 tsp all spice powder (sub mixed spice)","2 bay leaves (, preferably fresh)","1 scotch bonnet or habanero chilli - any colour (optional), keep whole (Note 1)","2 x 400g / 14oz cans red kidney beans (, drained (Note 2))","1 x 400 ml / 14oz coconut milk (, full fat (Note 3))","1 cup water","1 tsp cooking salt","2 cups long grain white rice (Note 4)"]}]', '[{"description":"Preheat oven to 200°C/400°F (180°C fan).","images":[],"step":1},{"title":"Sauté aromatics","description":"Melt butter over medium-high heat in a medium or large ovenproof pot (Note 5). Cook garlic, onion, thyme, all spice, bay leaves, scotch bonnet until onion is translucent (~ 3 minutes).","images":[],"step":2},{"description":"Add coconut milk, water, beans and salt. Once it comes to a simmer, add rice then give it a quick stir. Once you see bubbles breaking the surface, immediately cover then transfer to oven.","images":[],"step":3},{"description":"Bake for 40 minutes. All liquid should be absorbed (tilt to check) though you will have some coconut cream on the surface.","duration":40,"images":[],"step":4},{"title":"Rest","description":"Leave the pot on the counter with the lid on for 15 minutes. Then fluff and serve!","duration":15,"images":[],"step":5}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Caribbean","Jamaican","Tropical!"],"categories":["rice-recipes","rice-side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b2911bb8398c', 'en', 'US', 'Buttery Seasoned Rice', 'Recipe video above. Fluffy, seasoned, buttery rice that will elevate any meal! Homemade version of boxed rices like Rice-a-Roni and Uncle Bens. Economical way to make a really tasty rice side dish that will go with anything! Makes 6 cups cooked rice (fluffed), serves 6 - 8 as a side. Make a big batch, refrigerate 4 days or freeze 3 months!', 'https://www.recipetineats.com/tachyon/2020/03/Seasoned-Rice_3.jpg', 5, 13, 18, 6, '[{"id": "ing_white_rice", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.812, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}]', '[{"ingredients":["2 cups long grain white rice (, uncooked (Note 1 for brown rice))","3 1/4 cups water (cold tap water)","2 tsp chicken powder / granulated bouillon (, or 2 cubes dissolved in boiling water (Note 2))","1 tsp garlic powder (*)","1 tsp onion powder (*)","1 tsp paprika (*)","1/2 tsp dried thyme (*)","2 tbsp dried parsley (*, optional)","1 tsp salt","1/2 tsp black pepper"]},{"ingredients":["50g / 3 tbsp butter, unsalted (or MORE!)"],"purpose":"Stir through:"}]', '[{"description":"Place all Rice ingredients in a large saucepan and give it a stir.","images":[],"step":1},{"description":"Bring to simmer over medium high heat (edges bubbling, entire surface rippling), put the lid on and turn stove down to medium low (LOW for strong stoves). It should be simmering gently.","images":[],"step":2},{"title":"Cook for 13 minutes","description":"do not lift lid!","duration":13,"images":[],"step":3},{"description":"Tilt pot then QUICKLY peek to ensure all water is absorbed.","images":[],"step":4},{"description":"Remove from stove, stand 10 minutes with lid on.","images":[],"step":5},{"description":"Add butter and fluff rice with a rubber spatula. Serve!","images":[],"step":6},{"title":"Storage","description":"please read Note 4.","images":[],"step":7},{"title":"Rice cooker","description":"Same ingredients, water and rice ratio. Pop it all in your rice cooker and cook per manufacturer directions, stir through butter at end.","images":[],"step":8}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["rice-recipes","rice-side-dishes","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cf2b8d796603', 'en', 'US', 'Chimichurri butter', 'Chimichurri sauce enriched with butter with sautéed instead of raw garlic. Terrific with any cooked protein and cooked vegetable. Brilliant with steak and roast beef, like the Rump Cap roast / picanha I published today!Don''t be tempted to try to blitz up the parsley and butter with a stick blender instead of mincing the parsley with a knife - it will emulsify and become cloudy immediately, and be green as well! Note: This is not a compound butter where you roll it into a log then slice rounds as needed. This is a melted butter sauce - because we sauté the garlic first. Makes 3/4 cup (180ml).', 'https://www.recipetineats.com/tachyon/2025/11/Chimichurri-butter_1.jpg', 10, 2, 12, 6, '[{"id": "ing_butter", "quantity": {"value": 125.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["125g / 1 stick (8 tbsp) unsalted butter","3/4 tsp cooking salt / kosher salt (reduce by 30% for table salt, + 30% for flakes)","3 tsp garlic (, finely minced (3 - 4 cloves))","1 tsp large red chilli (, deseeded, finely minced (or Birds Eye/Thai, for extra spicy!))","1 tbsp red wine vinegar (or lemon juice)","1/4 cup finely minced parsley leaves (about 1 cup leaves before chopping)","2 tbsp fresh oregano (, finely minced)"]}]', '[{"title":"Sauté","description":"Melt butter with the salt on medium heat. Sauté garlic and red chilli until the garlic is very light golden - about 30 seconds.","images":[],"step":1},{"title":"Herbs","description":"Remove from heat. Let it cool for at least 5 minutes. Stir in the parsley, oregano and vinegar just before serving.","images":[],"step":2},{"description":"Serve warm! (ie butter melted). Spoon over steak, roast beef slices, vegetables (cooked), other cooked proteins (fish, chicken, prawns/shrimp, pork).","images":[],"step":3},{"title":"Making ahead","description":"You can let the garlic butter sit around for a while (even overnight), just melt to liquify before stirring in the parsley and oregano.","images":[],"step":4}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":[],"categories":["roast-beef","sauces"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_665ad93fc3ad', 'en', 'US', 'Cowboy Butter - for steak, and so much more!', 'This goes phenomenally well with steak (try it with Tomahawk!), though I''ve been using it with everything from chicken to toast, vegetables to hot steamed rice.Most recipes just mix raw garlic in, but honestly, doing a mini sauté is so worth it - the garlic flavour is much nicer.', 'https://www.recipetineats.com/tachyon/2025/05/Cowboy-butter.jpg', 5, 1, 6, 2, '[{"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}]', '[{"ingredients":["100g / 7 tbsp unsalted butter (, softened, divided)","1 large garlic clove (, finely minced (1 tsp) - knife best (Note 1))","1 tbsp Dijon mustard","1 tsp smoked paprika (sub regular paprika)","1 tsp chilli flakes / red pepper flakes","1/4 tsp cooking salt / kosher salt (halve for table salt)"]}]', '[{"title":"Sauté garlic","description":"In a small frying pan, melt 1 tbsp (15g) of butter over medium heat until it starts foaming then add the garlic and cook for 30 seconds while stirring until it becomes very, very light golden. Remove from the stove and let it cool for 3 minutes (the garlic will go more golden).","duration":0.5,"images":[],"step":1},{"title":"Mix","description":"Put the rest of the butter and remaining ingredients in a small mixing bowl. Pour the garlic butter over. Mix until combined.","images":[],"step":2},{"description":"Serve with steak! It''s also excellent with other cooked meats, seafood and even vegetables.","images":[],"step":3},{"description":"How to use Cowboy Butter:","images":[],"step":4},{"description":"I like to use it softened as it melts thicker over hot steak. You can also melt gently then dip bites of steak in, or roll it into a log using cling wrap, refrigerate then cut slices off on an as-need basis (you can place the coins on the steak to let it melt).","images":[],"step":5}]', '["milk","mustard"]', '["gluten_free","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["roast-beef","sauces"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3aade9599e67', 'en', 'US', 'My best Grilled Cheese Sandwich', 'Recipe video above. A grilled cheese sandwich is not diet food. So when I have one, it has to be great! So this is my recipe for my very best Grilled Cheese Sandwich. 2 types of cheese. The right bread. Butter both sides. And cook it on the stove! {Read in post for why.}Crispy, salty, buttery exterior and oozy, molten cheese inside. Are you ready to meet the ultimate cheese toastie??', 'https://www.recipetineats.com/tachyon/2023/07/Grilled-Cheese-sandwich-photo-main.jpg', 5, 7, 12, 1, '[{"id": "ing_bread", "quantity": {"value": 0.1, "unit": "loaf"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 0.333, "unit": "block of 250g"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.24, "unit": "pack of 125g"}}]', '[{"ingredients":["2 slices sourdough bread (, sliced 1.3–1.5cm thick (0.5 - 0.6\") - Note 1)","30g/ 2 tbsp SALTED butter (, for spreading on bread (or unsalted + pinch of salt))","1/3 cup (heaped) vintage cheddar cheese or gruyere, (freshly grated (or other melting cheese of choice) - Note 2)","30g/ 1/3 cup mozzarella, ( freshly grated - Note 2)"]}]', '[{"title":"Butter bread","description":"Slather both sides of each piece of bread with the butter (yes, all 4 sides!).","images":[],"step":1},{"title":"Light toast","description":"Heat a heavy-based skillet or frying pan over medium low heat (no oil or butter). Place both pieces of bread in the skillet and lightly toast for 1 minute to warm it through and create a light crust. (When we flip, this gives the cheese a head start).","duration":1,"images":[],"step":2},{"title":"Pile on cheese","description":"Flip one slice of bread, then pile on the cheddar cheese followed by the mozzarella. Place the other slice of bread on top, with the hot toasted side in contact with the cheese.","images":[],"step":3},{"title":"Cook 3 minutes","description":"Cook for 3 minutes or until the bread is evenly golden and crisp, pressing down lightly with a spatula every now and then. If it''s browning too quickly, remove remove from the stove to cool down a bit and lower heat.","duration":3,"images":[],"step":4},{"title":"Flip, 3 minutes","description":"Turn the sandwich over, and cook the other side for 3 minutes or until the bread is golden and the cheese is melted.","duration":3,"images":[],"step":5},{"title":"Devour","description":"Transfer to cutting board. Cut in half in one swift motion. Admire cheese pull. Devour.","images":[],"step":6}]', '["gluten","milk"]', '["high_protein","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Western"],"categories":["sandwiches-and-sliders"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0cb49661606c', 'en', 'US', 'Christmas Leftovers Toasted Bread Bowl', 'Recipe video above. This isn''t really a recipe, it''s more of an idea you can make your own. A way to completely transform leftovers into an epic sandwich for sharing! Use leftover ham, cooked meats, roasted veg, cheese platter leftovers. Imagine the possibilities! Great served fresh AND travels well!', 'https://www.recipetineats.com/tachyon/2018/12/Bread-Bowl-Sandwich-Christmas-Leftover-Ham-Turkey_6.jpg', 15, 30, 45, 4, '[{"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_ham_turkey_and_other_meat_slices", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_antipasto_things", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_cheese", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_baby_spinach", "quantity": {"value": 3.0, "unit": "bag of 250g"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}]', '[{"ingredients":["1 round or oval bread loaf (Note 1)","300 g / 10 oz ham, turkey and other cooked meat slices","1 cup roughly chopped antipasto things (olives, sun dried tomato, chargrilled peppers, artichokes, feta etc)","4 - 6 slices cheese of choice (I used Swiss in the video)","3 big handfuls baby spinach (~75g / 2.5oz)"]},{"ingredients":["50 g / 3 tbsp salted butter (, melted)","1 garlic clove (, minced)"],"purpose":"Garlic Butter:"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Mix butter and garlic.","images":[],"step":2},{"description":"Cut the top off the bread loaf. Pick out bread from the loaf and the lid, leaving a wall and floor about 1.5cm / 3/5\" thick.","images":[],"step":3},{"description":"Place bread on a large sheet of foil on a baking tray.","images":[],"step":4},{"title":"Dab / brush inside with butter. Layer with","description":"half spinach, turkey, antipasto things, remaining spinach, ham, cheese.","images":[],"step":5},{"description":"Tuck flappy bits inside the loaf, top with lid.","images":[],"step":6},{"description":"Brush with butter all over. Wrap with foil.","images":[],"step":7},{"title":"Weigh down with something flat and heavy","description":"cast iron skillet is ideal.","images":[],"step":8},{"description":"Bake for 20 minutes. Remove skillet and foil.","duration":20,"images":[],"step":9},{"description":"Bake for a further 10 minutes until golden.","images":[],"step":10},{"description":"Cut into thick slices and serve immediately!","images":[],"step":11}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["sandwiches-and-sliders"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3928ee3c5361', 'en', 'US', 'Raspberry Coulis', 'This is my recipe for raspberry coulis. It''s a vibrant, tart-sweet silky smooth raspberry sauce made simply by simmering berries with a little sugar, blitzing, and straining until smooth. A restaurant favourite!Not all recipes simmer on the stove but I like to because it makes the sauce more syrupy and it combines better so it clings to things and doesn''t "bleed" on the plate. I don''t always strain but I do when I''m cooking to impress, or for refined desserts like Pana Cotta. I''m sharing this recipe as a filling for Pavlova Bombs which is the primary recipe for today. And yes, it''s even more fun than the name suggests!', 'https://www.recipetineats.com/tachyon/2025/12/Raspberry-coulis_1.jpg', 5, 7, 12, 1, '[{"id": "ing_raspberries", "quantity": {"value": 2.0, "unit": "punnet of 125g"}}, {"id": "ing_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.005, "unit": "net of 500g"}}]', '[{"ingredients":["250g/ 8 oz raspberries (, fresh or frozen (no need to thaw))","2 1/2 tbsp caster sugar ((superfine sugar) - or regular/granulated sugar)","1/2 tsp lemon juice"]}]', '[{"title":"Heat and mash","description":"Place ingredients in a small saucepan over medium heat. As it heats up, the raspberries will release liquid. Once the liquid is simmering and the raspberries soften, mash them up with a fork.","images":[],"step":1},{"description":"Simmer for 3 minutes. Puree with stick blender (you can do this in the saucepan if the head of the stick blender is submerged, else, transfer mixture to a jug).","duration":3,"images":[],"step":2},{"description":"Strain into a bowl (optional), pressing out as much coulis as you can. Discard seeds.","images":[],"step":3},{"description":"Cool fully on the counter then refrigerate until required, it will thicken. Once cool, you can thin with a little water if needed. Typically served cold, but it can also be used warm!","images":[],"step":4}]', '[]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["dessert-recipes","sauces"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_956e823dcd18', 'en', 'US', 'Honey Mustard Dipping Sauce', 'A creamy dipping sauce with just the right notes of sweet and tang, universally great for "everything!". Use it as a dipping sauce - think crunchy chicken tenders, fish fingers, popcorn chicken, wedges, fries and even roasted broccoli, steamed beans or veggie sticks. Or spoon it over a chicken, fish or pork pan fried with just a little salt and pepper.Substitute the mayonnaise with yogurt for a lower fat version. For a brighter yellow colour, use 50/50 dijon and American yellow mustard.', 'https://www.recipetineats.com/tachyon/2025/01/Honey-mustard-sauce_6.jpg', 3, 0, 3, 0, '[{"id": "ing_mayonnaise", "quantity": {"value": 0.188, "unit": "jar of 400g"}}, {"id": "ing_mustard", "quantity": {"value": 0.15, "unit": "jar of 200g"}}, {"id": "ing_honey", "quantity": {"value": 0.06, "unit": "jar of 500g"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 1.0, "unit": "bottle of 500ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1/2 cup mayonnaise (, preferably whole egg (Note 1))","2 tbsp dijon mustard","2 tbsp honey","1 - 2 tsp apple cider vinegar or lemon juice","Pinch of salt and white pepper (sub black)"]}]', '[{"description":"Mix the ingredients together, starting with 1 teaspoon of vinegar or lemon juice, then adding the other if you want it a bit tangier. Ready to use!","images":[],"step":1}]', '["egg","mustard"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["sauces"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_055cca01ca5a', 'en', 'US', 'Vermouth Jus', 'Recipe video above. This is a recipe for Vermouth Jus which I''m sharing as the sauce for Crispy Slow Roasted Pork Belly. A jus is an intensely-flavoured, meat stock reduction sauce favoured by fine dining French restaurants to serve alongside meats and fish. If you have homemade beef stock or chicken stock on hand, this is a deceptively easy sauce that will elevate any dish to fine dining levels!It must be made with either homemade beef stock. Store-bought stock or broth just won''t work unfortunately.Makes: 100ml / 3.5 oz. It doesn''t sound like much, but you only need 1 - 1.5 tbsp per serving because it is so strongly flavoured.', 'https://www.recipetineats.com/tachyon/2021/04/Vermouth-Jus_7-copy.jpg', 5, 20, 25, 4, '[{"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_dry_vermouth", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.12, "unit": "carton of 250ml"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}]', '[{"ingredients":["2 tbsp/ 30g unsalted butter","1 eschallot (, thinly sliced (aka French onion. US: shallot, Note 1))","3 tbsp dry vermouth (Note 2)","2 cups homemade beef stock (cannot use store bought, Note 3)","2 tbsp cream","1/8 tsp salt (, kosher/cooking (Note 4))","1/8 tsp black pepper (, finely ground)"]}]', '[{"description":"Melt butter in a skillet over medium low heat. Add eschalot and cook for 4 - 5 minutes, until softened and sweet. Do not allow to colour.","duration":4.5,"images":[],"step":1},{"description":"Add vermouth and turn the heat up to medium-high. Let it simmer, scraping the base of the pan to dissolve any fond (stuck caramelised bits) into the liquid, until the liquid is almost totally evaporated. The alcohol cooks out during this step.","images":[],"step":2},{"description":"Add beef stock and let it simmer for 6 to 7 minutes until it reduces by 3/4 (exact time will differ depending on stove strength and pan size).","duration":6.5,"images":[],"step":3},{"description":"Add cream and simmer for a further 4 minutes or until it changes from a pale cream colour to a medium brown colour.","images":[],"step":4},{"description":"Season with salt and pepper, and taste. If it tastes a bit thin, continue to reduce.","images":[],"step":5},{"description":"Strain sauce through a fine mesh strainer into a bowl. If you have much more than 100ml / 3.5 oz jus once strained, then return to pan and simmer on low for a bit longer. (Be sure to use a rubber spatula so you don''t waste a drop!).","images":[],"step":6},{"description":"Jus is an intensely-flavoured sauce and so is used sparingly (allow 1.5 tbsp - 2 tbsp max per serve). Restaurants will typically serve it already poured with the meat, rather than a jug for people to serve themselves. Drizzle it on the plate around or on protein using a spoon (pan seared or roast slices). See in post for some ideas, including how I plated up the Crispy Pork Belly slices using this jus.","images":[],"step":7}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["main_course"],"cuisine":["French","Western"],"categories":["sauces"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_213b9d603866', 'en', 'US', 'Crispy marinated baby octopus', 'Recipe video above. Here''s an easy, outrageously delicious way to cook baby octopus: simmered until tender, marinated in bold Mediterranean flavours, seared until crispy. Add a Greek Salad, bread for mopping and a glass of chilled wine for the perfect summer meal!2 kg / 4 lb raw baby octopus will serve 5 to 6 people as a main - it shrinks quite substantially. It might even be better the next day, so look forward to leftovers!', 'https://www.recipetineats.com/tachyon/2023/02/Crispy-baby-octopus_3.jpg', 10, 75, 85, 6, '[{"id": "ing_baby_octopus", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 4.0, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 2.0, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.09, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.09, "unit": "net of 500g"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_parsley", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_lemon", "quantity": {"value": 0.09, "unit": "net of 500g"}}]', '[{"ingredients":["2 kg / 4 lb baby octopus (, rinsed (Note 1))"]},{"ingredients":["4 litres / quarts water","1 onion (, halved, skin on)","6 garlic cloves (, smashed (Note 2))","1 tsp black peppercorns (sub 1/2 tsp ground pepper)","2 tsp cooking salt (kosher salt)","3 tbsp lemon juice (or apple cider vinegar)","3 parsley stems (with leaves)","2 bay leaves (, fresh or dried)"],"purpose":"Braising liquid:"},{"ingredients":["1/2 cup extra virgin olive oil","6 garlic cloves (, very finely minced (or use garlic press))","2 tsp lemon zest (one large lemon)","2 tbsp lemon juice","1 tsp dried red chilli flakes ((red pepper flakes), optional)","1/2 tsp each cooking/kosher salt and black pepper"],"purpose":"Marinade:"},{"ingredients":["1 tbsp canola oil (for BBQ or large skillet)","2 tsp parsley (, finely chopped (optional))","1 large red chilli (, finely sliced (optional))","Lemon wedges (highly recommended)"],"purpose":"Cooking & serving:"}]', '[{"title":"Braising","description":"Put all the braising liquid ingredients in a large pot and bring to a boil over high heat. Add octopus, bring back up to the boil, then reduce the heat to low so the water is simmering very, very gently. Scoop off and discard scum off the surface when it accumulates.","images":[],"step":1},{"description":"Braise 1 hour until tender, first checking at the 45 minute mark, or until octopus is tender (take a little nibble to check!).","images":[],"step":2},{"description":"Drain octopus in a colander. Pick out and discard the bay leaves, onion etc. Transfer octopus into a bowl.","images":[],"step":3},{"title":"Marinate","description":"Mix marinade ingredients in a bowl. Pour over the octopus (while still hot). Toss, allow to fully cool, cover with cling wrap then marinate overnight in the fridge. (Note 4)","images":[],"step":4},{"title":"Cook until crispy (BBQ)","description":"Heat a BBQ hot plate on medium high until hot. Spread oil across the hot plate. Use tongs to transfer the octopus onto the BBQ (leave residual oil behind), spread out and cook for 3 to 5 minutes, rotating as needed to brown all over, and most especially ensuring the legs are golden and crispy. (Stove - use a large skillet, cook in 2 or 3 batches).","duration":4,"images":[],"step":5},{"title":"Serve","description":"Pile octopus on a plate. Sprinkle with parsley and chilli, add lemon wedges. EAT and be happy! Serve with bread for mopping or see Note 4 for crushed potatoes pictured in post dressed with residual marinade.","images":[],"step":6}]', '["shellfish"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner","snack"],"cuisine":["Mediterranean","Western"],"categories":["seafood-recipes","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d8ba3c043260', 'en', 'US', 'Rosemary Salt', 'The best way to make rosemary salt is to dry fresh rosemary then grind into a powder with salt. It takes 2 minutes in the microwave and stays a lovely green colour! Much better flavour than using stir bought dried, and fresh rosemary is too wet.A great flavoured salt to useadd extra flavour into dishes, such as the homemade French Fries I shared today. Sprinkle on Focaccia, poultry, steak, lamb chops, potatoes and vegetables. Use for savoury muffins and salad dressings in place of plain salt for extra flavour. See above for a list of suggestions!', 'https://www.recipetineats.com/tachyon/2022/09/Rosemary-salt.jpg', 5, 2, 7, 4, '[{"id": "ing_rosemary", "quantity": {"value": 4.0, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}]', '[{"ingredients":["4 x 15 cm/6\" sprigs of rosemary","1/2 tsp table salt (Note 1)"]}]', '[{"title":"Prep","description":"Place a sheet of paper towel on a heatproof plate. Spread rosemary on the paper towel, then cover with another single sheet of paper towel.","images":[],"step":1},{"description":"Microwave in 4 x 30 second increments on high until the rosemary leaves are fully dry and can be crumbled into powder between your fingers, but still a lovely vibrant green! (Note 2 for oven)","images":[],"step":2},{"description":"Grind into a coarse powder in a mortar and pestle (or even with your fingers). Goal: some fine powder and some coarse little rosemary bits.","images":[],"step":3},{"title":"Mix","description":"Measure out 3 teaspoons of the rosemary powder and mix in a small bowl with the salt.","images":[],"step":4},{"title":"Use","description":"Sprinkle on homemade fries, cooked proteins, use in place of plain salt in cheese muffins, on focaccia and in salad dressings! Best used uncooked as the rosemary is susceptible to burning. Store in an airtight container in the pantry.","images":[],"step":5}]', '[]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["European","Western"],"categories":["seasonings"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2a543a8dfbd2', 'en', 'US', 'My favourite Tomato Salad', 'A big, juicy tomato salad is a staple everyone should know how to make well! Rather than shaking up a dressing, sprinkle the garlic, eshallots/shallots and salt straight onto the tomato wedges. The flavour sticks better.Use everyday red tomatoes though if you can get them, heirloom tomatoes will add a great splash of colour.', 'https://www.recipetineats.com/tachyon/2022/07/The-Best-Tomato-Salad_0.jpg', 10, 0, 10, 4, '[{"id": "ing_tomato", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_eschalots", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.833, "unit": "pack of 3 heads"}}, {"id": "ing_vinegar", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 2.0, "unit": "jar of 50g"}}, {"id": "ing_basil", "quantity": {"value": 0.45, "unit": "bunch"}}]', '[{"ingredients":["4 ripe tomatoes (180g/ 6oz each) (Note 1)","1 1/2 tsp finely minced eschalots (US: shallots) (Note 2)","1/2 tsp finely minced garlic (use a knife, not garlic press)","1 tbsp white wine vinegar (Note 3)","3 tbsp extra virgin olive oil","3/4 tsp cooking / kosher salt","2 pinches white pepper","1 1/2 tbsp finely sliced basil leaves (, plus extra for garnish (Note 4))"]}]', '[{"description":"Cut the tomatoes into 8 or 10 wedges, cutting out the core. Place in a large bowl.","images":[],"step":1},{"description":"Sprinkle over eschallots, garlic, salt and pepper. Drizzle with olive oil and vinegar.","images":[],"step":2},{"description":"Gently toss to coat tomatoes. Add basil, toss again to disperse.","images":[],"step":3},{"title":"Pour into bowl and serve immediately! (Tip","description":"Bread for mopping up the tomato juices is on point).","images":[],"step":4}]', '[]', '["gluten_free","keto_friendly","low_calorie","vegan","vegetarian"]', '{"mealType":["lunch"],"cuisine":["Italian","Western"],"categories":["side-salads","tomato"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5f205ff7fe38', 'en', 'US', 'Outrageous Nutella Brownies', 'Recipe video above. Fudgy chocolate brownies with the signature crinkly top stuffed with a layer of Nutella! Having tried various Nutella Brownies in my time, I''ve found this is the best way to get a good hit of Nutella flavour into brownies. Mixing/swirling it in just doesn''t have the same effect!', 'https://www.recipetineats.com/tachyon/2019/01/Nutella-Brownies_4.jpg', 15, 35, 50, 16, '[{"id": "ing_nutella", "quantity": {"value": 400.0, "unit": "unit"}}, {"id": "ing_butter", "quantity": {"value": 200.0, "unit": "block of 250g"}}, {"id": "ing_chocolate", "quantity": {"value": 200.0, "unit": "block of 100g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.1, "unit": "bottle of 50ml"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_cocoa_powder", "quantity": {"value": 0.15, "unit": "pack of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["400g / 13 oz Nutella (Note 1)"],"purpose":"Nutella Slab:"},{"ingredients":["200 g / 1 3/4 US sticks (14 tbsp) unsalted butter","200 g / 1 1/4 cups / 7 oz dark chocolate melts / semi sweet chocolate chips (Note 2)","1 cup (175g) brown sugar (, loosely packed )","3 eggs (, room temp)","1 tsp vanilla extract"],"purpose":"Wet:"},{"ingredients":["1/2 cup (75g) flour (, plain/all purpose, sifted if lump)","1/4 cup (30g) cocoa powder (, sifted)","Pinch of salt"],"purpose":"Dry:"}]', '[{"description":"Grease a 20cm/8\" square pan with butter then line with parchment/baking paper with overhang.","images":[],"step":1},{"description":"Scrape Nutella into pan, spread. Freeze 1 hour or until solid.","images":[],"step":2},{"description":"Using paper overhang, remove onto a plate and return to freezer (softens pretty quickly)","images":[],"step":3},{"description":"Preheat oven to 180C/350F (standard) or 160C/320F (fan forced / convection).","images":[],"step":4},{"description":"Reline the same pan with parchment/baking paper with overhang.","images":[],"step":5},{"description":"Place butter and chocolate chips in a heatproof bowl, microwave in 30 second bursts (takes me 1 min) until almost melted. Stir to finish melting and incorporate butter into chocolate.","images":[],"step":6},{"description":"Cool for a few minutes. Add eggs, sugar and vanilla, whisk to combine.","images":[],"step":7},{"description":"Add Dry ingredients, whisk to combine (few lumps ok).","images":[],"step":8},{"description":"Assemble & Bake:","images":[],"step":9},{"description":"Pour half batter into pan. Use spatula/egg flip to lift frozen Nutella slab and place on top. Top with remaining batter.","images":[],"step":10},{"description":"Bake 35 minutes. Insert skewer in middle to check if cooked - should come out with mostly pale brown smear (Nutella) and a bit of dark brown smear (brownie, fudgy).","images":[],"step":11},{"description":"Cool in pan 30 minutes, then use paper overhang to lift out. Cool for at least another 45 minutes then slice into 16 pieces (4 x 4) and serve!","images":[],"step":12}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":[],"categories":["dessert-recipes","slices-bars"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4d7a56f7c22f', 'en', 'US', 'Vegetable Beef Soup (Fall apart beef!)', 'Recipe VIDEO above. Melt-in-your-mouth chunks of beef, vegetables and potato in a hearty herb infused broth. You''ll love how the soup broth is slightly thickened and the extra flavour the wine or beer adds to the soup (the secret ingredient!). 20 minutes active cook/prep.', 'https://www.recipetineats.com/tachyon/2019/05/Vegetable-Beef-Soup_3.jpg', 15, 110, 125, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_celery", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 3.0, "unit": "pack of 1kg"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.5, "unit": "bottle of 750ml"}}, {"id": "ing_water", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_potato", "quantity": {"value": 2.0, "unit": "bag of 2kg"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.2, "unit": "kg"}}]', '[{"ingredients":["1.5 tbsp olive oil (, separated)","500g/1 lb stewing beef (, cut into 1.75cm / 2/3\" cubes (Note 1))","1/2 tsp salt and pepper","1 onion (, chopped)","3 garlic (, minced (1 tbsp))","2 celery (, cut into 0.8 cm / 1/3\" slices)","3 carrots (, cut into 0.5 cm / 1/5\" thick slices (halve larger ones))","4 tbsp flour","2 1/2 cups (625ml) beef broth/stock (, low sodium)","1 1/2 cups (375ml) dry red wine, Guinness beer or stout (Note 2)","1.5 cups (375ml) water","2 tbsp tomato paste","2 bay leaves","1 tsp thyme dried","1 cup frozen peas","2 potatoes ((any), cut into 1.5cm / 2/3\" cubes)"]},{"ingredients":["1 tbsp (15g) butter or oil","200g/ 6oz small mushrooms (, quartered or halved)"],"purpose":"Buttery mushrooms (optional):"}]', '[{"description":"Heat 1 tbsp oil until very hot in a large, heavy based pot over high heat.","images":[],"step":1},{"description":"Pat beef dry with paper towels, then sprinkle with salt and pepper.","images":[],"step":2},{"description":"Brown beef aggressively in 2 or 3 batches, adding more oil if needed. Remove browned beef into a bowl.","images":[],"step":3},{"description":"If pot looks dry, add a touch more oil.","images":[],"step":4},{"description":"Add garlic and onion, cook for 2 minutes.","duration":2,"images":[],"step":5},{"description":"Add carrot and celery, cook for 2 minutes or until onion is translucent.","duration":2,"images":[],"step":6},{"description":"Stir in flour, then slowly pour in beef broth while constantly stirring.","images":[],"step":7},{"description":"Add beer, water, tomato paste, bay leaves and thyme, stir well. Then add the beef back in.","images":[],"step":8},{"description":"Cover, adjust heat to medium low so it''s bubbling gently. Simmer 1 hr 15 min or until beef is pretty tender.","images":[],"step":9},{"description":"Add potatoes and peas, simmer for a further 20 minutes without the lid. Add cooked mushrooms in the last 5 minutes.","images":[],"step":10},{"description":"The soup is ready when the potatoes are cooked and beef is very tender (see video).","images":[],"step":11},{"description":"Adjust salt and pepper to taste (I like lots of pepper in this!).","images":[],"step":12},{"description":"Ladle into bowls. Sprinkle with parsley and serve with crusty bread if desired. Try quick Cheesy Garlic Bread or super easy Irish Soda Bread!","images":[],"step":13},{"description":"Buttery Mushrooms (optional):","images":[],"step":14},{"description":"Melt butter in a large skillet over medium high heat. Add mushrooms and cook for 5 minutes until browned. Sprinkle with salt and pepper.","duration":5,"images":[],"step":15}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["slow-cooker-recipes","soup-recipes","stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4dd00d01d6a1', 'en', 'US', 'Texan BBQ Candied Nuts', 'Recipe video above. These Texan BBQ flavoured candied nuts are my current nibbling obsession. Savoury enough for pre-dinner drinks. Just sweet enough to be an after dinner treat! You could even package them up and gift - assuming they don''t mysteriously "disappear" beforehand....Use any nuts you want. Similar size nuts are ideal, though when I''m feeling lazy I just grab a bag of mixed nuts. Just make sure they''re unsalted.', 'https://www.recipetineats.com/tachyon/2025/07/Texan-BBQ-candied-nuts_0.jpg', 5, 25, 60, 8, '[{"id": "ing_pecans", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_almonds", "quantity": {"value": 0.9, "unit": "pack of 250g"}}, {"id": "ing_cashews", "quantity": {"value": 150.0, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 25.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_chipotle", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_chilli_flakes", "quantity": {"value": 0.188, "unit": "jar of 40g"}}]', '[{"ingredients":["1 1/2 cups pecans","1 1/2 cups almonds (, raw unsalted (or toasted))","1 cup cashews (, raw, unsalted (toasted ok too))","1 1/2 tsp cooking salt / kosher salt (halve for table salt, increase by 50% for flakes)"],"purpose":"Nuts (Note 1):"},{"ingredients":["25g / 1 1/2 tbsp unsalted butter","1/2 cup white sugar (Note 3)","2 tbsp water","1 tsp smoked paprika","1 tsp chipotle (slightly spicy, can sub with 3/4 tsp extra smoked paprika)","1/2 tsp coriander powder","1/2 tsp cumin powder","1/2 tsp onion powder","1/2 tsp garlic powder","1/2 tsp black pepper","1/4 tsp cayenne pepper (, optional (for more spicy!))"],"purpose":"Texan spiced candy coating (Note 2):"},{"ingredients":["Sea salt flakes (, for extra salt to taste)"],"purpose":"Optional"}]', '[{"description":"Abbreviated recipe:","images":[],"step":1},{"description":"Simmer candied coating 2 min, toss with nuts, bake 20 min at 180°C/350°F (160°C fan), tossing halfway. Break up while warm, fully cool. Attack!","images":[],"step":2},{"description":"Preheat oven to 180°C/350°F (160°C fan-forced). Line a large tray with foil then baking paper (parchment).","images":[],"step":3},{"title":"Nuts","description":"Put the nuts in a bowl.","images":[],"step":4},{"title":"Candied coating","description":"Put the butter in a small saucepan over medium heat. Once mostly melted, add all the remaining candied coating ingredients. Stir, then once it comes to a simmer, reduce stove to medium low so it''s simmering gently for 2 minutes, stirring regularly so it doesn’t catch.","duration":2,"images":[],"step":5},{"title":"Toss","description":"Pour over the nuts, toss well - take about 30 seconds, use a rubber spatula. It should be quite thick and coat the nuts well, no runny caramel pooling at bottom of bowl.","images":[],"step":6},{"title":"Bake","description":"Spread on tray, bake for 20 minutes, tossing well at the halfway mark, until the nuts are deep golden. There should be hardly any candy coating liquid left on the tray.","duration":20,"images":[],"step":7},{"title":"Break up","description":"Cool undisturbed on the tray for 10 minutes then break it up while still warm (separates better). Then leave to fully cool on the tray - the candy coating will fully harden (about 30 minutes). (Note 4 if nut surface is not shiny smooth)","duration":10,"images":[],"step":8},{"title":"Uses","description":"Serve in bowls for snacking (brilliant bar snack), fill jars for gifting, add to platters, chop and sprinkle on salads. Adding a sprinkle of sea salt is a nice finishing touch.","images":[],"step":9}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["snack","dessert"],"cuisine":["Western"],"categories":["snacks"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_859b99f3e9aa', 'en', 'US', 'Crunchy muesli bars (granola bars)', 'Recipe video above. I''ve never come across a crunchy muesli bar recipe that stayed crunchy beyond a day. So I decided to make my own - and these stay crunchy for 3+ weeks! Adapted from my chewy muesli bars, I found the key to be lightly toasting the oats then cutting the bars before baking. The chewy muesli bars also have a higher ratio of honey and peanut butter which is what makes them chewy!PS Even though they''re sugar free, I munch on these when I need a sweet-treat fix, yet they''re healthy enough for breakfast.', 'https://www.recipetineats.com/tachyon/2024/02/Crunchy-muesli-bars_2.jpg', 10, 35, 45, 10, '[{"id": "ing_honey", "quantity": {"value": 0.125, "unit": "jar of 500g"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.1, "unit": "jar of 375g"}}, {"id": "ing_rolled_oats", "quantity": {"value": 0.45, "unit": "pack of 500g"}}, {"id": "ing_almonds", "quantity": {"value": 0.3, "unit": "pack of 250g"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_sultanas", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_chocolate", "quantity": {"value": 2.0, "unit": "block of 100g"}}]', '[{"ingredients":["1/4 cup honey (Note 1)","1/4 cup natural peanut butter, smooth (or crunchy!) (Note 2)"],"purpose":"The glue:"},{"ingredients":["1 1/2 cups rolled oats* (not steel cut)","1/2 cup almonds* (, roughly chopped)","1/4 cup pepitas* (pumpkin seeds)","1/2 cup sultanas*","3/4 tsp cinnamon powder (or other, like pumpkin spice)","1/4 tsp cooking / kosher salt","2 tbsp small chocolate chips (or 3 tbsp regular dark choc chips, optional (Note 4))"],"purpose":"Muesli bars (Note 3):"}]', '[{"description":"Preheat the oven to 160°C/325°F (140°C fan-forced). Place a sheet of baking paper over a 20 cm / 8\" square tin with overhang so it''s easy to lift out later (no greasing needed).","images":[],"step":1},{"title":"Toast","description":"Spread the oats, chopped almonds and pepitas on a tray. Bake for 10 minutes. Tip into a heatproof bowl. (Note 5) Add the sultanas, cinnamon and salt.","duration":10,"images":[],"step":2},{"title":"Muesli mixture","description":"Microwave the honey and peanut butter in a heatproof jug for 30 seconds on high. Mix to combine. (Note 6) Pour over the oat mixture and mix through. It might seem like it won''t mix in, but persist, it will! Use a cutting motion if needed. Last resort - Note 7","duration":0.5,"images":[],"step":3},{"title":"Press","description":"Tip the muesli mixture into the pan then press firmly into the pan. Once cooled, scatter the choc chips across surface (if using). Cover with a sheet of paper then press down firmly with your hands to push the choc chips in.","images":[],"step":4},{"description":"Refrigerate for 1 hour or until firm enough to lift out without bending.","images":[],"step":5},{"description":"Preheat the oven to 160°C/325°F (140°C fan-forced).","images":[],"step":6},{"title":"Cut","description":"Use the paper overhang to lift the muesli slab onto a cutting board. Cut in half, then each into 5 (10 bars). Transfer onto a tray using the paper, then space the muesli bars out.","images":[],"step":7},{"description":"Bake for 25 minutes or until quite golden on the surface and golden brown on the edges but not burnt.","duration":25,"images":[],"step":8},{"title":"Cool & crunchy","description":"Remove from the oven and cool on the tray - it will become crunchy! Store in an airtight container once cooled, in the fridge if it''s warm where you are. It will still be crunchy 3 weeks later!","images":[],"step":9}]', '["peanuts"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["breakfast","snack"],"cuisine":["Australian","Western"],"categories":["dessert-recipes","snacks"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_99b6cbf12663', 'en', 'US', 'Pearl Barley Soup', 'Recipe video above. This is a recipe for a Pearl Barley Soup filled with lots of vegetables that''s clean, nutritious and (yet!) oh-so-tasty. The chewy, nutty barley makes it so much more interesting than using just pasta or rice. A great soup recipe to make your own - follow my cook method and broth flavourings. Then mix and match the vegetables to suit your cravings - or fridge contents!', 'https://www.recipetineats.com/tachyon/2021/09/Barley-Soup_40.jpg', 10, 45, 55, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_or_1_medium_swede_into_1cm_0_4_cubes", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_mushroom", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_thyme", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.025, "unit": "bunch"}}, {"id": "ing_round_fennel", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.009, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_pears", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 1.75, "unit": "L"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["2 tbsp extra virgin olive oil","1 onion (, finely diced)","2 small or 1 large carrot ((~200g/7oz), peeled, chopped into 1cm / 0.4\" cubes)","2 celery stems (, chopped into 1cm / 0.4\" cubes)","2 small or 1 medium swede (US: rutabaga), peeled, chopped into 1cm / 0.4\" cubes (~200g, Note 1)","150g / 5 oz white mushrooms (, cut in 4 (larger ones cut into 6 or 8))","2 garlic cloves (, finely minced)","1/2 tsp fresh thyme (, chopped (or 1/4 tsp dried))","1/4 tsp ground coriander","1/4 tsp ground fennel","2 fresh bay leaves (or 1 dried)","1 3/4 tsp cooking/kosher salt","1/2 tsp black pepper","1 cup pearl barley (, NOT hulled barley (Note 2))","1.75 litres / quarts vegetable stock","1 cup fresh parsley leaves"]}]', '[{"description":"Rinse barley in a colander with cold tap water. Leave to drain for several minutes.","images":[],"step":1},{"title":"Sauté veg 5 minutes","description":"Heat olive oil in a pot over medium-high heat. Add onion, carrot, celery, swede, mushrooms and garlic (yes, all at once!). Cook for 5 minutes, stirring regularly.","duration":5,"images":[],"step":2},{"title":"Sauté herbs/spices","description":"Add thyme, coriander, fennel, bay leaves, salt and pepper. Cook for 1 minute.","duration":1,"images":[],"step":3},{"title":"Simmer 35 minutes","description":"Add pearl barley and vegetable stock. Stir, bring to a boil and simmer for 35 minutes until barley is cooked. It will have a nice chew to it but should not have a hard centre like uncooked rice.","duration":35,"images":[],"step":4},{"title":"Stir in parsley","description":"Stir in parsley leaves. Ladle into bowls and serve!","images":[],"step":5},{"description":"Storing leftovers:","images":[],"step":6},{"description":"Strain soup (or use slotted spoon), store vegetables/barley separate from soup broth. Otherwise the barley will soak up all the liquid!","images":[],"step":7}]', '["gluten"]', '["low_calorie","vegan","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["soup-recipes","vegan-lifestyle","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5165fdd50aa0', 'en', 'US', 'Cold Corn Soup for Summer', 'Recipe video above. Corn Soup is one of those rare soups best served cold. For all those days when it''s too hot to even contemplate eating hot food!Sweet summer corn is the star here that makes a simple corn stock that drives home the corn flavour. If you can''t get good fresh corn where you are, use frozen corn instead but prop the flavour up with chicken or vegetable stock.Serve cold as a canape in shot glasses, tea cups as a starter, or bowls as a meal. Serves 6 as a meal.', 'https://www.recipetineats.com/tachyon/2021/06/Cold-Corn-Soup_0.jpg', 15, 45, 60, 6, '[{"id": "ing_corn", "quantity": {"value": 8.0, "unit": "can of 400g"}}, {"id": "ing_water", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_eek", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_thyme", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_corn", "quantity": {"value": 8.0, "unit": "can of 400g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.75, "unit": "bunch"}}]', '[{"ingredients":["8 ears yellow corn (Note 1 for frozen corn)","3 litres / 3 quarts water"],"purpose":"Corn stock:"},{"ingredients":["100g/ 7 tbsp unsalted butter","2 garlic cloves (, chopped)","1/2 onion (, finely sliced)","1 celery stalk (, sliced)","1/2 leek (, white part only, finely sliced (sub 1/2 onion))","1 tsp salt (, cooking/kosher salt, plus more as needed)","1 cup cream (, full fat)"],"purpose":"Corn soup:"},{"ingredients":["2 sprigs of thyme","1 bay leaf (, preferably fresh otherwise dried)","1 tsp black peppercorns","1 tsp coriander seeds"],"purpose":"Herb Spice Sachet (Note 2):"},{"ingredients":["Extra corn kernels (, sautéed in butter until golden with a pinch of salt and pepper)","1/4 cup green onion (, finely sliced)"],"purpose":"Optional Garnish:"}]', '[{"title":"Cut off kernels","description":"Cut the corn kernels off the cobs and transfer to a bowl.","images":[],"step":1},{"title":"Corn stock","description":"Cut the cobs in half. Place in a large pot with the water. Bring to a boil, then reduce to medium low and simmer for 30 minutes. Strain - it should be 2 litres. If it''s much more , simmer to reduce. If less, top up with water.","duration":30,"images":[],"step":2},{"title":"Sachet","description":"Bundle the bay leaf, thyme, black peppercorns and coriander seeds loosely in a small piece of cheesecloth to create a sachet. Tie with cooking twine to secure.","images":[],"step":3},{"title":"Sauté aromatics","description":"Melt butter in a pot over medium high heat. Add onion, celery, leek and garlic. Cook for 4 - 5 minutes until soft.","duration":4.5,"images":[],"step":4},{"title":"Cook corn","description":"Add corn kernels then cook for 6 to 7 minutes.","duration":6.5,"images":[],"step":5},{"title":"Simmer","description":"Add the corn stock and the sachet. Bring it to a boil and let it simmer for 20 minutes.","duration":20,"images":[],"step":6},{"title":"Cream","description":"Add the cream and cook for 3 minutes.","duration":3,"images":[],"step":7},{"title":"Blend and sieve","description":"Remove the Sachet. Blend in batches in a blender on high speed until smooth. CAUTION! Hot liquid + tightly sealed blender lid = soup explosion! To avoid this, either cool before blending. OR remove the lid of the feeding tube in the blender lid. Cover the exposed hole with a folded tea towel as you blend hot liquid. You will see me do this in the recipe video.","images":[],"step":8},{"title":"Strain","description":"Pass through a fine sieve.","images":[],"step":9},{"title":"Adjust salt","description":"Taste and add more salt if needed.","images":[],"step":10},{"title":"Chill and serve","description":"Cool, then transfer to the fridge to chill completely. Intended to be served chilled or cool, but also great at room temperture or warm!","images":[],"step":11},{"title":"How to serve","description":"In shot glasses as a canape, tea cups as a small starter, or bowls as a meal with hunks of crusty bread. Garnish with kernels sauteed in butter with green onion slices and a drizzle of extra virgin olive oil (basil oil would be even more incredible!).","images":[],"step":12}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner","snack"],"cuisine":["Western"],"categories":["soup-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_548000224fa5', 'en', 'US', 'Celeriac Soup', 'Recipe video above. Celeriac is an unsung hero of the vegetable world! It makes a wonderful creamy Celeriac Soup that''s an elegant near pure-white colour, and happens to be low carb. It''s thick, creamy and comforting. Texture like potato but better flavour - tastes mildly like celery but with earthy, nutty undertones.Make it as a sophisticated first course for a dinner party, or just a cosy dinner for midweek.This easily makes enough soup for 5 people as a meal (with some crusty bread on the side!)', 'https://www.recipetineats.com/tachyon/2021/03/Celeriac-Soup_0.jpg', 15, 45, 60, 5, '[{"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_eek", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_celery", "quantity": {"value": 3.0, "unit": "head"}}, {"id": "ing_celeriac", "quantity": {"value": 800.0, "unit": "unit"}}, {"id": "ing_potato", "quantity": {"value": 200.0, "unit": "bag of 2kg"}}, {"id": "ing_water", "quantity": {"value": 1.5, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_coriander", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_croutons", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_chives", "quantity": {"value": 0.015, "unit": "kg"}}]', '[{"ingredients":["60g / 4 tbsp butter (, unsalted)","2 garlic cloves (, finely chopped)","1 onion (, diced (brown or yellow))","1/2 leek (white part only) (, diced into 1cm / ½\" cubes (~ 3/4 cup, Note 1))","3 celery stems (, diced into 1cm / ½\" cubes (~1 1/2 cups))","800g / 1.6 lb (peeled weight) celeriac (, cut into 2cm / ⅘\" cubes (~1kg / 2lb unpeeled, Note 2))","200g / 7oz potato (, peeled, cut into 2cm / 4/5\" cubes (floury or all-rounder – about 1 large; Note 3))","1.5 litres / quarts (6 cups) water (, or stock if you prefer)","1 1/2 tsp salt","1/4 tsp white pepper","1 cup cream (, full fat (pure, thickened or heavy, Note 4))"]},{"ingredients":["1 bay leaf (, fresh)","2 thyme sprigs","1/2 tsp black peppercorn (go without if no sachet)","1/2 tsp coriander seeds (1/8 tsp powder if no sachet)"],"purpose":"Spice Sachet (Note 5):"},{"ingredients":["Croutons (Note 6)","Olive oil (, for drizzling)","1 tbsp chives (, finely chopped (sub parsley or chervil))"],"purpose":"Garnish/Serving:"}]', '[{"title":"Spice and herb sachet","description":"Bundle the bay leaf, thyme, black peppercorns and coriander seeds loosely in a small piece of cheesecloth to create a sachet. Tie with cooking twine to secure.","images":[],"step":1},{"title":"Cook onion and leek","description":"Melt butter in large pot over medium-low heat. Add onion, leek, celery and garlic. Cook for 10 minutes until onion is soft but not golden. Don''t rush this part – this creates an important flavour base so we can make this soup using water not stock.","duration":10,"images":[],"step":2},{"title":"Cook celeriac and potato","description":"Add celeriac and potato. Cook for 10 minutes, stirring regularly, until the outside of the celeriac and potato starts to soften. Be careful to not colour the celeriac - we''re going for a white soup here!","duration":10,"images":[],"step":3},{"title":"Simmer 25 minutes","description":"Add salt, pepper, Spice and Herb Sachet, and water. Bring to a boil, then turn down to a simmer. Simmer for 25 minutes (no lid) until celeriac is very soft.","duration":25,"images":[],"step":4},{"title":"Cream","description":"Add cream, simmer for another 3 minutes.","images":[],"step":5},{"title":"Blitz","description":"Remove Sachet, then blitz until fully smooth using your method of choice: Stick blender (~ 3 mins), or cool slightly and do in a blender in batches (Note 5)","images":[],"step":6},{"title":"Adjust seasoning","description":"Adjust salt and pepper to taste.","images":[],"step":7},{"title":"Serving","description":"Ladle into bowls. Sprinkle with croutons and chives, drizzle with olive oil. Serve with crusty bread for dunking!","images":[],"step":8}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["soup-recipes","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_dee5246f6808', 'en', 'US', 'Minestrone Soup', 'Recipe video above. The heartiest of all chunky soups, filled with anything your heart desires! While the add ins are endlessly customisable, stick with the soup broth recipe because I''ve made it extra tasty!* Asterix marked items can be substituted with any cookable vegetables, 6 cups in total.', 'https://www.recipetineats.com/tachyon/2020/07/Minestrone-Soup_0.jpg', 20, 45, 65, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_bacon", "quantity": {"value": 0.75, "unit": "pack of 200g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_kidney_beans", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.3, "unit": "pack of 500g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_zucchini", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_green_beans", "quantity": {"value": 100.0, "unit": "pack"}}, {"id": "ing_baby_spinach", "quantity": {"value": 2.0, "unit": "bag of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["1 tbsp olive oil","150g / 5oz bacon (, finely chopped)","1 onion (, chopped)","2 garlic cloves (, minced)","800g/ 28oz crushed tomato (or 700g passata)","2 cups chicken stock/broth (, low sodium)","2 cups water","3 tbsp tomato paste","2 tsp Worcestershire sauce","400g/ 14oz canned kidney beans (, drained)","1 tsp EACH salt and pepper","1 cup small pasta (, like ditalini, tiny shells, risoni/orzo, baby macaroni, alphabet or star pasta)","1/4 cup parmesan (, grated)"]},{"ingredients":["1 celery rib* (, chopped 1.5cm / 1/2\" pieces)","1 large carrot* (, peeled and diced 1.5cm / 1/2\" pieces)","1 zucchini* (, chopped 1.5cm / 1/2\" pieces)","1 potato* (, cut into 1.5cm / 1/2\" pieces (peel if needed))","100g / 3oz green beans* (, trimmed then cut into 2cm / 3/5\" lengths)","2oz/ 60g baby spinach (or frozen spinach, kale or similar - can leave out)"],"purpose":"Minestrone Vegetables (Note 1):"},{"ingredients":["More parmesan","Chopped parsley","Crusty bread for dunking!"],"purpose":"For serving – optional:"}]', '[{"description":"Heat oil over high heat in a very large pot.","images":[],"step":1},{"description":"Add bacon, cook until starting to turn golden (~2 min) then add garlic and onion.","images":[],"step":2},{"description":"Cook until onion is translucent and bacon is light golden ~ 2minutes.","images":[],"step":3},{"description":"Add carrot, celery and zucchini. Stir for 1 minute to coat in flavour.","duration":1,"images":[],"step":4},{"description":"Add crushed tomato, chicken stock, water, tomato paste, Worcestershire sauce, kidney beans, salt and pepper.","images":[],"step":5},{"description":"Stir, bring to simmer, then place lid on and adjust heat so it''s simmering gently.","images":[],"step":6},{"description":"Simmer 20 minutes, then add potato and beans.","images":[],"step":7},{"description":"Simmer 5 minutes, then add pasta. Cook for time per pasta packet MINUS 1 1/2 minutes.","images":[],"step":8},{"description":"Remove from stove, stir through parmesan and baby spinach. Taste and adjust for salt and pepper.","images":[],"step":9},{"description":"Serve, garnished with extra parmesan and a sprinkle of parsley if desired. Warm crusty bread on the side would certainly be the cherry on top!","images":[],"step":10}]', '["gluten","milk"]', '["high_protein","low_calorie"]', '{"mealType":["dinner"],"cuisine":["American-Italian","Italian","Western"],"categories":["soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4132fb580ca6', 'en', 'US', 'Chicken Stew (Casserole)', 'Recipe video above. This is the faster way to make a chicken stew (casserole) that''s done in an hour but tastes like it''s been simmering all day! The trick is to use boneless thigh fillets, beef instead of chicken broth, a good slug of red wine and BACON!', 'https://www.recipetineats.com/tachyon/2019/07/Chicken-Stew_5.jpg', 15, 50, 65, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_bacon", "quantity": {"value": 0.75, "unit": "pack of 200g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 3.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_wine", "quantity": {"value": 0.5, "unit": "bottle of 750ml"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_thyme", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_potato", "quantity": {"value": 350.0, "unit": "bag of 2kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_green_beans", "quantity": {"value": 150.0, "unit": "pack"}}]', '[{"ingredients":["0.5 tbsp olive oil","150g/5oz bacon (, chopped)","750g/ 1.5lb boneless skinless chicken thighs (, cut into 3cm / 1.25\" pieces (Note 1))","1/2 tsp salt and pepper (, each)","3 garlic cloves (, minced (1 tbsp))","1 onion (, sliced)","3 carrots (, peeled, halved lengthwise, sliced 1cm / 1/3\" thick)","2 celery stalks (, sliced 1cm / 1/3\" thick)","1 1/2 cups (375ml) red wine (Note 2)","4 tbsp flour","3 cups (750ml) beef stock/broth (, low sodium (or chicken, Note 3))","400g/ 14oz crushed tomato (, canned)","2 tsp Worcestershire sauce","1/2 tsp salt and pepper (, each)","1 1/2 tsp dried thyme","2 dried bay leaves","350g/ 12 oz baby potatoes (, halved)","200g/ 6oz mushrooms (, halved (large quartered))","150g/ 5 oz green beans (, trimmed and halved)"]}]', '[{"description":"Place oil and bacon in a large heavy based casserole pot over high heat.","images":[],"step":1},{"description":"When the oil is heated and bacon releases some fat, add chicken.","images":[],"step":2},{"description":"Sprinkle with salt and pepper and cook, until chicken and bacon is browned.","images":[],"step":3},{"description":"Add garlic and onion, cook 1 minute.","images":[],"step":4},{"description":"Add celery and carrot, cook 2 minutes.","images":[],"step":5},{"description":"Add red wine, allow to simmer rapidly 2 minutes until the winey alcohol smell is gone.","images":[],"step":6},{"description":"Add flour, mix until incorporated.","images":[],"step":7},{"description":"Slowly pour in half the beef broth while stirring, then pour the rest in.","images":[],"step":8},{"description":"Add tomato, Worcestershire, thyme, bay leaves, salt, pepper.","images":[],"step":9},{"description":"Stir, add potato.","images":[],"step":10},{"description":"Cover, simmer 30 minutes.","images":[],"step":11},{"description":"Remove lid, add mushrooms and green beans. Simmer without lid* for a further 10 minutes.","images":[],"step":12},{"description":"Serve with crusty bread, sprinkled with parsley if desired!","images":[],"step":13}]', '["gluten"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a861adc1516c', 'en', 'US', 'Mini Christmas Cakes - ideal for gifting!', 'Recipe video above. Here''s my classic Christmas Cake converted into mini form! They look so great lined up on a platter to serve at a gathering, and are also ideal for gifting because they have a long shelf life. The cake is beautifully moist, rich with dried fruit, perfumed with Christmas spices. Dense, but soft pudding-like, not like an enjoyable brick as many store bought ones are.', 'https://www.recipetineats.com/tachyon/2023/11/Mini-Christmas-Cakes_6.jpg', 30, 150, 285, 9, '[{"id": "ing_raisins", "quantity": {"value": 300.0, "unit": "unit"}}, {"id": "ing_apricots", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_mixed_peel", "quantity": {"value": 75.0, "unit": "unit"}}, {"id": "ing_cherries", "quantity": {"value": 0.3, "unit": "pack of 500g"}}, {"id": "ing_dates", "quantity": {"value": 180.0, "unit": "unit"}}, {"id": "ing_apples", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 115.0, "unit": "block of 250g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_molasses", "quantity": {"value": 45.0, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cinnamon", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_nutmeg", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.017, "unit": "tub of 150g"}}, {"id": "ing_flour", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_walnuts", "quantity": {"value": 112.5, "unit": "jar"}}, {"id": "ing_sugar", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_christmas_fondant_see_directions_here", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sugar", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_vanilla", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_milk", "quantity": {"value": 1.5, "unit": "L"}}]', '[{"ingredients":["300g / 10 oz raisins","150g / 5 oz diced dried apricots (, chopped 8 mm / 1/3\")","75g / 2 1/2 oz mixed peel (, diced 5mm / 1/5)","150g / 5 oz glace cherries (, chopped 8 mm / 1/3\")","180g / 6 oz dates (, diced 5mm / 1/5\")","1 cup + 2 tbsp apple juice ( , OR 1/3 brandy + 2/3 juice (Note 2))"],"purpose":"Fast soaked fruit (Note 1):"},{"ingredients":["115g / 8 tbsp unsalted butter (, softened (1 US stick))","1 1/2 cups brown sugar (, packed (or dark brown sugar for a darker crumb, Note 3))","1/2 cup vegetable oil (or canola, peanut, grapeseed)","3 tbsp molasses or golden syrup (Note 4)","1/2 tsp salt","1/2 tsp all spice","1/2 tsp cinnamon","1/2 tsp nutmeg","3 eggs","1/2 tsp baking powder","1 2/3 cups plain flour (all purpose flour)","3/4 cup walnuts (, chopped (optional))"],"purpose":"Cake:"},{"ingredients":["Icing sugar, for dusting","Christmas fondant - see directions here"],"purpose":"Decorating"},{"ingredients":["1 1/2 cups soft icing sugar / powdered sugar","1 tbsp / 15g unsalted butter, softened","1/2 tsp vanilla","1 1/2 - 3 tbsp milk"],"purpose":"Christmas Pudding Drippy Glaze"}]', '[{"description":"Fast Soaked Fruit:","images":[],"step":1},{"title":"Heat","description":"Place dried fruit and juice/brandy in a large microwavable container. Microwave 1 1/2 minutes on high or until hot.","images":[],"step":2},{"title":"Soak","description":"Stir to coat all fruit in liquid. Cover then set aside for 1 hour (to plump up/soak and cool).","images":[],"step":3},{"description":"Preheat oven to 160°C / 320°F (140°C fan). Grease and line a 20cm / 8\" square cake pan with baking paper / parchment paper, or larger pan to get more cakes out of it. (Note 5 on pan size).","images":[],"step":4},{"title":"Beating","description":"Using an electric beater, beat butter and sugar until smooth and creamy (about 1 minute on speed 5). Add oil and molasses, beat until combined. Add salt, spices and baking powder - beat until incorporated. Add eggs, one at a time, beating until just incorporated.","images":[],"step":5},{"description":"Stir in the flour with a wooden spoon, then the dried fruit (including all the extra liquid in bowl) and walnuts (if using).","images":[],"step":6},{"description":"Pour into the cake pan, it will fill it right to the top (it won''t spill over, the cake barely rises). Cover the surface with paper then cover with foil.","images":[],"step":7},{"title":"Bake 2 1/2 hours","description":"Bake for 2 hours, remove the foil and paper, then bake for a further 30 minutes. A skewer inserted into middle should come out clean with no batter on it.","images":[],"step":8},{"description":"Remove from oven and cool for 20 minutes before transferring to cooling rack. Cool completely before cutting.","duration":20,"images":[],"step":9},{"title":"Cutting","description":"Trim off the sides (to make them neat). Then cut into 9 squares (or more, if you want). Trim the surface (to make them level as the cake slightly domes). Then flip upside down and decorate the base of the cake.","images":[],"step":10},{"description":"Decorating, gifting and serving","images":[],"step":11},{"title":"Simple","description":"Dust with icing sugar. That''s all this cake needs, it''s so full flavoured and moist! Wrap with cellophane and ribbon to gift.","images":[],"step":12},{"title":"Ribbon","description":"Wrap and tie a ribbon around each cake. Nice way to present for serving. (Optional to include for gift wrapping too, but then there''s a double ribbon situation happening - ie ribbon and cake, ribbon on cellophane!)","images":[],"step":13},{"title":"Drippy white glaze","description":"Mix the icing sugar, butter, vanilla and start with 2 tbsp milk. Mix really well (it will take time to come together, be patient). Then adjust thickness using 1/2 tsp milk at a time. BE CAREFUL - it goes from too thick to too thin very easily! Goal: Thick glaze that will ooze \"pudding style\", as pictured, rather than dripping in long streaks. Spoon onto cake, coaxing it down the sides. Allow to set before wrapping.","images":[],"step":14},{"title":"Fondant","description":"See directions in my classic round Christmas Cake.","images":[],"step":15},{"title":"Serving","description":"serve with custard for a traditional experience! Either homemade custard or store bought pouring custard.","images":[],"step":16}]', '["egg","gluten","milk","peanuts"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Australia","British","Western"],"categories":["dessert-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_00bae2819365', 'en', 'US', 'Cinnamon Apple Teacake', 'Recipe video above. Apples take centre stage in this lovely teacake! The crumb is soft and beautifully moist, there''s apple inside and on top. It takes time to chop the apple, but the cake part is dead easy - just a bowl and a wooden spoon! (Correction: plus a whisk and rubber spatula. But NO electric mixer required!)', 'https://www.recipetineats.com/tachyon/2020/05/Cinnamon-Apple-Teacake_2.jpg', 15, 50, 65, 12, '[{"id": "ing_apples", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.312, "unit": "jar of 40g"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.067, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_vanilla_extract", "quantity": {"value": 0.2, "unit": "bottle of 50ml"}}, {"id": "ing_jam", "quantity": {"value": 0.061, "unit": "jar of 370g"}}, {"id": "ing_water", "quantity": {"value": 0.015, "unit": "L"}}]', '[{"ingredients":["600g/ 1.2 lb Granny Smith apples, peeled and cored (or any other - red, green, golden) (4 large, 5 small/medium, Note 1)","2 1/2 tsp cinnamon powder","50g/ 3 tbsp unsalted butter (, melted)","2 tbsp white sugar"],"purpose":"Cinnamon Apples:"},{"ingredients":["1 1/2 cups flour (, plain/all purpose)","2 tsp baking powder","1/2 tsp salt"],"purpose":"Dry:"},{"ingredients":["4 tbsp/ 60g unsalted butter (, melted)","1/2 cup oil (canola, vegetable)","2 large eggs (, at room temperature (~55g/1.95 oz each) (Note 2))","3/4 cup white sugar (, caster / superfine best (but not essential))","2 tsp vanilla extract"],"purpose":"Wet:"},{"ingredients":["1 1/2 tbsp apricot jam (or other flavour)","1 tbsp water"],"purpose":"Glaze (optional):"}]', '[{"description":"Preheat oven to 180°C/350°F (all oven types).","images":[],"step":1},{"description":"Grease a 20cm / 8\" springform pan with butter, then line with baking paper (parchment paper).","images":[],"step":2},{"description":"Chop half the apples into 1.25 cm / 1/2\" pieces.","images":[],"step":3},{"description":"Slice the other half into 3mm / 1/8\" thick slices.","images":[],"step":4},{"description":"Place into separate bowls. Sprinkle/drizzle each bowl with half the butter, sugar and cinnamon. Toss to coat, set aside.","images":[],"step":5},{"description":"Whisk Dry ingredients in a large bowl.","images":[],"step":6},{"description":"Pour Wet ingredients in a separate bowl in the order listed. Whisk well to combine.","images":[],"step":7},{"description":"Pour Wet into the Dry ingredients bowl. Mix with a wooden spoon or rubber spatula until flour is incorporated.","images":[],"step":8},{"description":"Add chopped apple. Gently mix through until JUST dispersed (to keep cinnamon on apple, not dispersed through batter).","images":[],"step":9},{"description":"Scrape into cake pan, smooth surface.","images":[],"step":10},{"title":"Top with sliced apples","description":"fan them out in a circle, overlapping each other by 1/4 (fiddle away to use up all the apple / make it even!).","images":[],"step":11},{"description":"Bake 50 minutes, or until skewer inserted into the centre comes out clean (Note 3). Cover loosely with foil if you have to bake beyond 50 min (to stop apples burning).","images":[],"step":12},{"description":"Place on cooling rack, release sides of springform pan.","images":[],"step":13},{"description":"Glaze & Serve:","images":[],"step":14},{"title":"Heat Glaze","description":"Place jam and water in a small bowl, microwave 20 seconds to warm, then mix.","images":[],"step":15},{"title":"Glaze","description":"Brush apples on surface with glaze.","images":[],"step":16},{"title":"Cool","description":"Allow to cool at least 30 minutes before cutting with sharp knife. It is sheer perfection when it''s still slightly warm in the middle.","images":[],"step":17}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dessert"],"cuisine":["Western"],"categories":["dessert-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f6fee28d7201', 'en', 'US', 'Sweet potato steaks', 'Recipe video above. I know the ingredients looks exorbitantly long for something I describe as "an easy way to turn sweet potatoes into a really tasty meaty dinner"! But actually, it is very straight forward. Thick slices of sweet potato roasted with a simple spice mix, then served on a bed of tahini yogurt topped with a glitter of garlic-sesame-chilli and pine nuts. It''s a fabulous flavour combination!Serve with something crunchy - toasted pita bread is my pick. (Note 5)', 'https://www.recipetineats.com/tachyon/2023/08/Roasted-Sweet-Potato-Steaks_6a.jpg', 10, 60, 70, 2, '[{"id": "ing_sweet_potato", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.3, "unit": "tub of 500g"}}, {"id": "ing_tahini", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 0.045, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.833, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_green_onion", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_pine_nuts", "quantity": {"value": 0.3, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_pinch_of_sumac", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["1 gigantic sweet potato - to cut 2 x “steaks” (1.8 cm thick, 17 cm long, 7 cm wide (0.7 x 6.5 x 2.75\") - Note 1)","2 - 3 tsp olive oil"]},{"ingredients":["1 1/2 tsp smoked paprika (sub ordinary)","1/2 tsp onion powder (or more garlic powder)","1/2 tsp onion powder (or more garlic powder)","1/4 tsp cumin powder","1/2 tsp cooking/kosher salt","1/4 tsp black pepper"],"purpose":"Spice mix:"},{"ingredients":["1 cup plain yogurt (250g)","2 1/2 tbsp tahini (Note 2)","1 1/2 tbsp lemon juice","1 garlic clove (, finely grated)","1/2 tsp cooking/kosher salt"],"purpose":"Whipped tahini yogurt sauce:"},{"ingredients":["2 tbsp extra virgin olive oil","3 garlic cloves (, finely minced)","1 1/2 tbsp eschallot (US: shallot), finely chopped (Note 3)","1 tbsp red cayenne pepper (, deseeded, finely chopped (not spicy, Note 4))","1 tbsp green cayenne pepper (, deseeded, finely chopped (not spicy, Note 4))","1 tbsp white sesame seeds"],"purpose":"Topping:"},{"ingredients":["2 tbsp pine nuts (, toasted)","2 tbsp coriander/cilantro leaves (, finely chopped)","Pinch of sumac (, optional (or paprika))","Pita or lebanese bread (, toasted (Note 5))"],"purpose":"Serving:"}]', '[{"description":"Preheat oven to 200°C/400°F (180°C fan-forced). Line a tray with parchment/baking paper.","images":[],"step":1},{"title":"Bake sweet potato","description":"Rub sweet potato steaks with oil, then sprinkle each side evenly with spice mix (don’t rub, it smears). Bake 45 - 50 minutes until potato is soft. Don’t flip.","images":[],"step":2},{"title":"Tahini yogurt sauce","description":"Whisk ingredients in a medium heat-proof bowl until mostly combined. Microwave for 20 seconds on high. Whisk again - it will be like softly whipped cream! Use warm or at room temp.","duration":0.3333333333333333,"images":[],"step":3},{"description":"Toast pine nuts in a small pan (no oil) preheated over medium heat. Once lightly golden, remove into a bowl.","images":[],"step":4},{"title":"Topping","description":"In the same pan, heat oil (still on medium). Add all Topping ingredients and cook, stirring, until the garlic is golden. Transfer into a bowl immediately.","images":[],"step":5},{"title":"Assemble","description":"Smear most of the yogurt sauce on plate (save some for drizzling). Put sweet potato on top. Sprinkle with Topping, drizzle with yogurt sauce, then sprinkle with pine nuts, coriander and sumac. EAT with crunchy toasted flatbread!","images":[],"step":6}]', '["gluten","milk","sesame"]', '["vegetarian"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern"],"categories":["sweet-potato","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d0f1163c1c7b', 'en', 'US', 'Homemade Paneer (Fresh Indian Cottage Cheese)', 'Recipe video above. Homemade paneer is far superior to store bought. It''s softer and creamier, and has much better flavour. It''s easy to make, without special equipment. All it takes is a little patience to let the cheese set in the fridge for 4 hours. Use paneer to make the great Indian classic, Palak Paneer (Spinach Curry with Paneer)', 'https://www.recipetineats.com/tachyon/2021/02/Homemade-Paneer-recipe_3.jpg', 10, 600, 610, 4, '[{"id": "ing_milk", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.12, "unit": "net of 500g"}}]', '[{"ingredients":["2 litres / 2 quarts milk (, full-fat (low-fat won''t work))","4 tbsp lemon juice (sub white vinegar)"]}]', '[{"description":"Heat the milk in a large saucepan over medium high heat until the top becomes foamy, just as looks like it''s about to boil.","images":[],"step":1},{"description":"Turn stove off. Add lemon juice and stir for 1 minute. The milk should begin to curdle. If it doesn’t, turn the stove back on and bring back to a gentle boil until the solids separate.","duration":1,"images":[],"step":2},{"description":"Strain & remove excess water:","images":[],"step":3},{"title":"Line strainer or colander","description":"Place over a deep bowl. Line strainer with 2 layers of cheesecloth (Note 1).","images":[],"step":4},{"title":"Strain","description":"Ladle in half of the curdled milk to begin with, then pour the rest in. Leave until all the liquid drains – this might take 5 to 10 minutes.","images":[],"step":5},{"title":"Rinse","description":"Discard liquid (whey) in the bowl. Bundle the paneer up in the cheesecloth (it will still be quite watery at this stage) then rinse bundle briefly under cold tap water. This helps to remove lemon flavour + cool for easier handling.","images":[],"step":6},{"description":"Squeeze out excess water by twisting the cheesecloth and squeezing the bundle, but not so hard that paneer squeezes out through the cloth. Once liquid no longer comes out, stop. The paneer will still be quite soft at this stage.","images":[],"step":7},{"title":"Weigh cheese down with weights","description":"Shape cheese into a disc around 2cm / ¾\" thick, still wrapped in cheesecloth. Place in a strainer or colander set over a bowl. Top with a small plate then 2 x 400g/14oz cans (or similar weight).","images":[],"step":8},{"description":"Refrigerate for 4 hours. During this time the paneer will set (become firm) and remaining liquid will drain out. (Note 2)","images":[],"step":9},{"description":"Storage / cutting:","images":[],"step":10},{"description":"Remove paneer from fridge and carefully unwrap. There will be a dent in the middle, this is normal (it''s from the draining).","images":[],"step":11},{"description":"At this stage, the paneer is now ready for use. You can either cut it immediately and use in a recipe (such as Palak Paneer!), or store the whole uncut block for another time and just cut when needed.","images":[],"step":12},{"description":"Store in the fridge for up to 2 weeks, or freeze for 3 months.","images":[],"step":13}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0a4f799e4f22', 'en', 'US', 'Incredible, Simple French Carrot Salad', 'Recipe video above. This carrot salad will surprise you - it''s so simple, yet so incredibly delicious! I''d go as far as to say it''s can''t-stop-eating-it good (and that''s a big call to make about a salad!) It''s a slight riff on a classic French Carrot Salad (which is typically dressed much more lightly with just lemon and olive oil). At the risk of offending an entire nation - this is tastier! 😂', 'https://www.recipetineats.com/tachyon/2019/10/Carrot-Salad_8.jpg', 10, 0, 10, 5, '[{"id": "ing_carrot", "quantity": {"value": 4.0, "unit": "pack of 1kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.04, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_mustard", "quantity": {"value": 0.037, "unit": "jar of 200g"}}, {"id": "ing_honey", "quantity": {"value": 0.03, "unit": "jar of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["4 carrots (, medium, peeled)","2 green onion stems (, finely sliced on the diagonal)","1/4 cup parsley (, finely chopped (optional))"]},{"ingredients":["1 1/2 tsp dijon mustard","1 tbsp honey","2 tbsp lemon juice (, fresh)","4 tbsp extra virgin olive oil","1/2 tsp salt","1/4 tsp black pepper"],"purpose":"Honey Dijon Mustard dressing"}]', '[{"description":"Grate the carrot use a standard box grater (or the shredder attachment of food processor). Aim for strands about 4cm/1.5\" long.","images":[],"step":1},{"description":"Place in a bowl with green onion and parsley.","images":[],"step":2},{"description":"Shake Dressing ingredients in a jar. Pour over carrot, toss then serve.","images":[],"step":3}]', '["mustard"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["main_course"],"cuisine":["Western"],"categories":["uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6b4d8a54cfa8', 'en', 'US', 'Spicy Korean Pork Stir Fry', 'The marinade for this stir fry is an authentic Korean Marinade for Spicy Korean BBQ Pork. It''s so jammy and loaded with flavour, it''s brilliant for using as a stir fry. I made this with pork but it goes great with beef and chicken too. MARINATING TIME: 30 minutes recommended to overnight, but even no marinating is still delicious as the sauce flavour is so strong.', 'https://www.recipetineats.com/tachyon/2016/05/Korean-Pork-Stir-Fry_6.jpg', 10, 5, 15, 4, '[{"id": "ing_pork_shoulder", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_pears", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.02, "unit": "pack of 100g"}}, {"id": "ing_gochujang", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_oil", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_rice", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["1 lb / 500g boneless pork shoulder (excess fat trimmed) (Note 1)"]},{"ingredients":["1 small pear (, grated (1/2 cup) (or nashi pear OR apple) (Note 2))","1/2 medium onion (, grated (1/4 cup) (brown, white or yellow))","1/2 tsp fresh ginger (, minced or finely chopped)","1 garlic clove (, crushed)","1 tbsp soy sauce (all purpose or light soy sauce)","2 tbsp brown sugar","2 tsp sesame oil","3 tbsp gochujang ((Korean Hot Pepper Paste) OR see Note 3 for substitution)"],"purpose":"Marinade"},{"ingredients":["1 tbsp oil","1 garlic (, minced)","1 onion (, halved and sliced (brown, white or yellow))"],"purpose":"Stir Fry"},{"ingredients":["1 scallion/shallot stalk (, sliced)","Sesame seeds","Rice"],"purpose":"To Serve"}]', '[{"description":"Cut pork into thin slices. If using pork shoulder, as I did, halve it lengthwise to form two long pieces, then slice the pieces. See photo below.","images":[],"step":1},{"description":"Combine Marinade ingredients in a bowl. Add pork. Marinate for 30 minutes, or overnight.","duration":30,"images":[],"step":2},{"description":"To cook, heat oil in a large non stick skillet (Note 4) over high heat. Add garlic and onion, cook for 2 minutes until translucent. Add pork and cook for 5 minutes or until dark golden and caramelised, and just cooked through.","duration":2,"images":[],"step":3},{"title":"Serve immediately with rice","description":"or for a low carb, low cal option, try Cauliflower Rice! Garnish with sliced shallots and sesame seeds.","images":[],"step":4}]', '["gluten","sesame","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Korean"],"categories":["uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8a27cf02cc51', 'en', 'US', 'Vietnamese pork noodle bowls (bun thit nuong)', 'Recipe video above. Popular Vietnamese street food! Fabulous combination of contrasting flavours and textures, fresh vegetables with flavourful lemongrass marinated pork, noodles and herbs, all doused in a mild nuoc cham sauce (so you can use lots).Light and fresh yet anything but dull. Excellent DIY spread for gatherings - lay it all out on tables and let everyone put their own bowls together. Chicken version here. Slightly different toppings because chicken is a white meat, pork is richer. :)', 'https://www.recipetineats.com/tachyon/2023/04/Vietnamese-noodles-lemongrass-pork-6.jpg', 30, 10, 40, 4, '[{"id": "ing_lemongrass", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.4, "unit": "pack of 500g"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 2.0, "unit": "bag of 250g"}}, {"id": "ing_mint", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_peanuts", "quantity": {"value": 0.094, "unit": "jar"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_radishes", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.75, "unit": "bottle of 250ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.068, "unit": "kg"}}, {"id": "ing_vinegar", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_lime", "quantity": {"value": 3.0, "unit": "net of 500g"}}, {"id": "ing_water", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_chilli", "quantity": {"value": 2.0, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 8.333, "unit": "pack of 3 heads"}}]', '[{"ingredients":["1 batch lemongrass marinated pork (it''s marinated overnight. 8 pieces, serves 4)","200g/ 7oz dried vermicelli noodles (Note 1)","1 head soft lettuce (like butter lettuce), torn into large bite size pieces (or 4 cups shredded iceberg, cos/romaine)","2 cucumbers (, halved lengthwise then sliced on the diagonal 3mm / 0.15\" thick)","2 cups bean sprouts","Handful mint leaves","Handful cilantro/coriander","1/4 cup finely chopped unsalted peanuts","Sliced red chilli (for garnish - optional)","Lime wedges (to serve - optional but recommended)"]},{"ingredients":["2 medium carrots (, peeled cut into 2-3mm / 1/10″ batons )","1/2 large white radish (daikon) (, peeled, cut the same as carrots)","1 1/2 cups boiling water","1/2 cup white sugar","4 tsp cooking salt (kosher salt)","3/4 cup rice vinegar (sub apple cider vinegar)"],"purpose":"Vietnamese pickled vegetables (Note 2)"},{"ingredients":["4 1/2 tbsp white sugar","4 1/2 tbsp fish sauce (Note 3)","3 tbsp rice wine vinegar","3 tbsp lime juice","1/2 cup water","2 birds eye chilli or Thai chilli (, deseeded and finely chopped (Note 4))","5 cloves garlic (, finely chopped)"],"purpose":"Nuoc cham Vietnamese sauce (Note 3):"}]', '[{"description":"Make pickled vegetables:","images":[],"step":1},{"title":"Pickle","description":"In a large bowl, dissolve the salt and sugar in the hot water. Stir in vinegar. Add carrots and daikon – they should just about be covered.","images":[],"step":2},{"title":"2 hours","description":"Leave for 2 hours until slightly floppy. Drain well then use per recipe.","images":[],"step":3},{"title":"Nuoc cham sauce","description":"Mix ingredients together. Until sugar is dissolved.","images":[],"step":4},{"title":"Vermicelli noodles","description":"Soak in boiling water for 5 minutes (or per packet directions). Drain, rinse under tap water, then cool and drain thoroughly (nobody likes watery noodles!).","duration":5,"images":[],"step":5},{"title":"Toppings","description":"Prepare all the other toppings, ready to use.","images":[],"step":6},{"description":"Cook pork per the recipe.","images":[],"step":7},{"title":"Assemble bowls","description":"Place noodles in a bowl. Top with lettuce, pickled vegetables, cucumber and bean sprouts. Slice pork, place 2 steaks on each bowl. Top with herbs, sprinkle with peanuts and sliced chilli. Add a lime wedge.","images":[],"step":8},{"description":"Serve with nuoc cham on the side so everybody can help themselves. Douse generously! Dive in and eat!","images":[],"step":9}]', '["fish","milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Vietnamese"],"categories":["vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
